        [6100101] = {
          ContentFR = "Près du feu de camp surgit une étendue d’eau, tapissée de narcisses en fleurs.\nUne femme contemple son reflet sur la surface trouble.\nBien que floue, cette image est si envoûtante qu’elle semble charmer jusqu’aux étoiles elles-mêmes.",
          DialogueId = 6100101,
          GUID = "0F455DD2",
          NextDialogue = 6100102,
          RougeTalkActorType = 3,
          Subtitle = "Where campfire light meets water, daffodils bloom.\nA woman studies her rippling reflection — captivating enough to make the night sky pause in wonder."
        },
        [6100102] = {
          ContentFR = "« Ô mon bien-aimé, où donc erres-tu ? »\n« J’ai parcouru toute l’Atlasia, les îles azurées de Luca, les vallées émeraude de Huaxu, les cimes où s’attardent les souffles d’Aethyrie, et le Fjord d’Askard, où la glace printanière se brise en éclats fragiles. »",
          DialogueId = 6100102,
          GUID = "0F455DFC",
          NextDialogue = 6100103,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room301_Char01",
          Subtitle = "\"My beloved, where do you wander?\"\n\"I've searched all Atlasia — through Luca's azure isles and Huaxu's emerald vales, where Aethyrie's breezes linger in the treetops, and where the Askard Fjord spring cracks the thinning ice.\""
        },
        [6100103] = {
          ContentFR = "« Et pourtant... je n’ai jamais trouvé celui que je chéris. »\n« La beauté qui m’égale doit être prisonnière des eaux du Lac Sacré d’Elysium... »\nMurmures adressés à son propre reflet.",
          DialogueId = 6100103,
          GUID = "0F455E26",
          NextOptions = {
            [1] = 6100104,
            [2] = 6100106
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room301_Char01",
          Subtitle = [[
"Yet I've found no one to cherish."
"The beauty who equals me must be imprisoned in the Sacred Lake of Elysium."
She murmurs softly to her own reflection.]]
        },
        [6100104] = {
          ContentFR = "<I>Révéler qu’il ne s’agit que de son reflet</>",
          DialogueId = 6100104,
          GUID = "0F455E50",
          IsKeyOption = true,
          NextDialogue = 6100105,
          RougeTalkActorType = 2,
          Subtitle = "\"You're gazing at your own reflection.\""
        },
        [6100105] = {
          ContentFR = "« Qui es-tu ? {性别:Un voyageur|Une voyageuse} de passage ? » \nElle lève les yeux, t’adresse un bref regard.\n« Si tu découvres un moyen de la délivrer, reviens me voir. »",
          DialogueId = 6100105,
          GUID = "0F455E7A",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room301_Char01",
          Subtitle = [[
"Who are you? A passing traveler?"
She lifts her gaze, studying you with a fleeting glance.
"Come back when you've learned how to set her free."]]
        },
        [6100106] = {
          ContentFR = "<I>Tenter de cueillir les narcisses du lac</>",
