        [6100203] = {
          ContentFR = "<I>Tenter de répondre</>",
          DialogueId = 6100203,
          GUID = "0F456E8E",
          NextDialogue = 6100204,
          RougeTalkActorType = 2,
          Subtitle = "Try to answer"
        },
        [6100204] = {
          ContentFR = "Tu ouvres la bouche... mais aucun son ne sort. Quelle année ? Quelle époque ?\nDans l’obscurité sans fin, tu as depuis longtemps perdu toute mesure du temps.",
          DialogueId = 6100204,
          GUID = "0F456EB8",
          NextDialogue = 6100206,
          RougeTalkActorType = 3,
          Subtitle = "You open your mouth to answer— but wait.\nWhat year is it now? What year should it be?\nIn the endless dark, you lost all measure of time long ago."
        },
        [6100206] = {
          ContentFR = "Ton silence lui tient lieu de réponse.",
          DialogueId = 6100206,
          GUID = "0F456F0C",
          NextDialogue = 6100207,
          RougeTalkActorType = 3,
          Subtitle = "Your silence answers for you."
        },
        [6100207] = {
          ContentFR = "Le vieillard soupire.\n« Je vois... tu n’es pas {性别:différent|différente}. Moi non plus je ne sais plus depuis combien de temps je suis prisonnier. Tout s’est effacé... il ne me reste que ces rides et ce marteau. »",
          DialogueId = 6100207,
          GUID = "0F456F36",
          NextDialogue = 6100208,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room302_Char01",
          Subtitle = "\"So you're no different,\" he sighs.\n\"I stopped counting how many years I've been trapped here. The memories are gone — all that's left is this hammer, and the wrinkles time carved into me.\""
        },
        [6100208] = {
