        [6100301] = {
          ContentFR = "Auprès du feu solitaire s’élève une chanson.\nUne femme s’avance, ses pas aussi légers qu’une plume, sa voix claire comme le chant d’un oiseau nocturne.",
          DialogueId = 6100301,
