        [6100401] = {
          ContentFR = "Un vieil homme s’avance vers le feu de camp. Tu remarques qu’il tient une lanterne à la main.",
          DialogueId = 6100401,
          GUID = "0F458F0A",
          NextDialogue = 6100402,
          RougeTalkActorType = 3,
          Subtitle = "An old man approaches the campfire. You notice he's carrying a lantern."
        },
        [6100402] = {
          ContentFR = "« Voyons voir... Oh ! Vous avez, vous aussi, une lanterne ! »\n« Mais sachez-le : toute flamme finit par s’éteindre. Et dans l’Abysse, sans lumière pour guider vos pas, vous serez à jamais perdu dans les ténèbres. »",
          DialogueId = 6100402,
          GUID = "0F458F34",
          NextDialogue = 6100403,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room304_Char01",
          Subtitle = "\"Let me see… Oh! So you have a lantern too!\"\n\"Yet all flames must fade in time. You know this — without light in the abyss, darkness claims you forever.\""
        },
        [6100403] = {
          ContentFR = "« Achetez donc une lanterne de rechange. Même une lueur infime pourrait bien vous sauver la vie dans les épreuves à venir. »",
          DialogueId = 6100403,
          GUID = "0F458F5E",
          NextOptions = {
            [1] = 6100404,
