            [3] = 6100408
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room304_Char01",
          Subtitle = "\"Best carry a spare lantern. Even the faintest glow may save your life on the road ahead.\""
        },
        [6100404] = {
          ContentFR = "<I>Acheter la lanterne</>",
          DialogueId = 6100404,
          GUID = "0F458F88",
          IsKeyOption = true,
          NextDialogue = 6100405,
          RougeTalkActorType = 2,
          Subtitle = "Buy the Lantern"
        },
        [6100405] = {
          ContentFR = "« Ah... quelle générosité, {性别:voyageur|voyageuse} ! Que le Dieu des Étoiles vous bénisse. »\nSon visage se fend d’un large sourire, chaque ride s’illuminant de joie. »",
          DialogueId = 6100405,
          GUID = "0F458FB2",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room304_Char01",
          Subtitle = "\"Ah… Such generosity, traveler! May the God of Stars smile upon you on your path.\"\nEvery wrinkle on his face dances with delight."
        },
        [6100406] = {
          ContentFR = "<I>Demander s’il possède d’autres objets utiles</>",
          DialogueId = 6100406,
          GUID = "0F458FDC",
          IsKeyOption = true,
          NextDialogue = 6100407,
          RougeTalkActorType = 2,
