    Loader = function()
      return {
        [6101703] = {
          ContentFR = "« Dis-moi, {性别:voyageur|voyageuse} ! Laquelle est la tienne ? La lanterne d’or, la lanterne de bois, ou la simple lanterne ? »",
          DialogueId = 6101703,
          GUID = "0F4664A6",
          NextOptions = {
            [1] = 6101704,
            [2] = 6101707,
            [3] = 6101710
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room317_Char01",
          Subtitle = "\"Greetings, dear traveler! Pray tell — did you drop this golden lantern, this humble wooden lantern, or perhaps… this perfectly ordinary lantern?\""
        },
        [6101704] = {
          ContentFR = "<I>La lanterne d’or</>",
          DialogueId = 6101704,
          GUID = "0F4664D0",
          IsKeyOption = true,
          NextDialogue = 6101705,
          RougeTalkActorType = 2,
          Subtitle = "The golden lantern"
        },
        [6101705] = {
          ContentFR = "« Ahahaha ! » Il éclate d’un grand rire tonitruant, son corps secoué d’exagération.\n« Splendide ! J’aime ton style ! Devant un trésor, il faut savoir tendre la main ! »\n« Prends-la, {性别:voyageur|voyageuse} ! Qui résiste à l’éclat de l’or, hein ? »",
          DialogueId = 6101705,
          GUID = "0F4664FA",
          NextDialogue = 6101706,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room317_Char01",
          Subtitle = "\"Ahahaha!\" His whole body shakes from the laughter. \"Splendid! I like your style! True greed doesn't ask — it takes!\"\n\"Take it, darling! Who could resist such glittering gold — am I right?!\""
        },
        [6101706] = {
          ContentFR = "L’homme plonge tête la première dans l’eau, et aussitôt, la surface se referme, comme si elle n’avait jamais existé.\nTu baisses les yeux : la lanterne repose intacte à tes pieds, entourée de Braises.",
          DialogueId = 6101706,
          GUID = "0F466524",
          RougeTalkActorType = 3,
          Subtitle = [[
The man plunges into the water, and the surface vanishes without a trace.
The lantern sits undisturbed at your feet, while scattered embers litter the ground around it.]]
        },
        [6101707] = {
          ContentFR = "<I>La lanterne de bois</>",
          DialogueId = 6101707,
          GUID = "0F46654E",
          IsKeyOption = true,
          NextDialogue = 6101708,
          RougeTalkActorType = 2,
          Subtitle = "The wooden lantern"
        },
        [6101708] = {
          ContentFR = "« Hein ? Toi... tu es drôle ! » Il penche la tête, et ses orbites noires semblent sans fond.\n« Le bois fait une piètre lanterne... mais pourquoi pas ? Ici, dans l’Abysse, rien n’est impossible ! »\n« Bénédictions sur toi, {性别:voyageur|voyageuse} ! Un chemin singulier t’attend. »",
          DialogueId = 6101708,
          GUID = "0F466578",
          NextDialogue = 6101709,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room317_Char01",
          Subtitle = "\"Hmm? You… intrigue me!\" He tilts his head, his dark eyes bottomless. \"Wood makes for poor lanterns — yet why shouldn't it? This is the abyss! Everything's possible here!\"\n\"Blessings upon you, dear one! What an interesting journey awaits.\""
        },
        [6101709] = {
          ContentFR = "L’homme plonge tête la première dans l’eau, et la surface se referme aussitôt, comme si rien n’avait jamais été.\nÀ tes pieds repose la lanterne, intacte. Tout près, un Artéfact luit faiblement dans l’ombre.",
          DialogueId = 6101709,
          GUID = "0F4665A2",
          RougeTalkActorType = 3,
          Subtitle = [[
The man plunges into the water, and the surface vanishes without a trace.
The lantern sits undisturbed at your feet, yet beside it now rests an Artefact.]]
        },
        [6101710] = {
          ContentFR = "<I>La lanterne ordinaire</>",
          DialogueId = 6101710,
          GUID = "0F4665CC",
          IsKeyOption = true,
          NextDialogue = 6101711,
          RougeTalkActorType = 2,
          Subtitle = "The ordinary lantern"
        },
        [6101711] = {
          ContentFR = "« Pff, vous voilà tous rendus ternes par l’Église Élyséenne... » Il pousse plusieurs soupirs théâtraux, l’air profondément déçu.\n« L’honnêteté est si... ennuyeuse. Tu ne voudrais pas plutôt échanger ta lanterne ? »",
          DialogueId = 6101711,
          GUID = "0F4665F6",
          NextDialogue = 6101712,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room317_Char01",
          Subtitle = "Tsk, tsk, the Elysian Church has turned you all into such dull people. He sighs dramatically, disapproving of your choice. \"Honesty is so dreadfully dull. Don't you want a new lantern?\""
        },
        [6101712] = {
          ContentFR = "« Soit... L’honnêteté est une vertu, paraît-il. Voilà ta récompense, comme dans l’histoire. »",
          DialogueId = 6101712,
          GUID = "0F466620",
          NextDialogue = 6101713,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room317_Char01",
          Subtitle = "\"Very well.\" He shakes his head. \"Honesty is supposed to be a virtue, isn't it? Then let the tale unfold — here's your reward, just as the story promised.\""
        },
        [6101713] = {
          ContentFR = "L’homme plonge tête la première dans l’eau, et la surface se referme aussitôt.\nÀ tes pieds, la lanterne repose intacte, sa flamme, plus vive qu’avant.",
          DialogueId = 6101713,
          GUID = "0F46664A",
          RougeTalkActorType = 3,
          Subtitle = [[
The man plunges into the water, and the surface vanishes without a trace.
The lantern sits undisturbed at your feet, yet it burns brighter.]]
        },
        [6101801] = {
          ContentFR = "Tu t’assieds près du feu pour te reposer.\nSoudain, un bruit étrange effleure ton oreille... puis s’éloigne, monte au-dessus de ta tête.\nIl enfle, de plus en plus clair : un froissement doux, comme des ailes de velours qui se frôlent.",
          DialogueId = 6101801,
          GUID = "0F4674BA",
          NextDialogue = 6101802,
          RougeTalkActorType = 3,
          Subtitle = "You settle beside the campfire for a rest.\nSuddenly, a faint sound tickles your ear... then rises, drifting somewhere above.\nIt swells — a soft, feathery rustle, like velvet wings brushing together."
        },
        [6101802] = {
          ContentFR = "« Hé ! {性别:Petit veinard|Petite veinarde} ! »",
          DialogueId = 6101802,
          GUID = "0F4674E4",
          NextDialogue = 6101803,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01",
          Subtitle = "\"Hey there! Lucky traveller!\""
        },
        [6101803] = {
          ContentFR = "Une pluie de plumes chatoyantes descend sur toi. Jamais, dans l’Abysse, tu n’as vu autant de couleurs à la fois.\nBientôt, tu te retrouves enseveli sous cet amas bariolé, ridicule pantin d’une farce de rue, oscillant entre le comique et le pathétique.",
          DialogueId = 6101803,
          GUID = "0F46750E",
          NextDialogue = 6101804,
          RougeTalkActorType = 3,
          Subtitle = "A flurry of vibrant feathers rains down from above — more colours than you've ever seen in the Abyssum.\nYou find yourself knee-deep in absurd fluff, like the butt of a street prank caught between comedy and pity."
        },
        [6101804] = {
          ContentFR = "« Quoi, pas de réaction ? Tu traînes ici depuis si longtemps... tu ne t’ennuies pas ? »\nUn homme avec un masque grotesque d’oiseau apparaît, suspendu la tête en bas.\nIl descend lentement jusqu’à ce que ses yeux soient au même niveau que les tiens.\nComment il tient cette posture, tu n’en sais rien. Mais ce qui compte, c’est que le bec de son masque vacille dangereusement, prêt à heurter ton visage.",
          DialogueId = 6101804,
          GUID = "0F467538",
          NextOptions = {
            [1] = 6101805
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01",
          Subtitle = [[
"Hello? Aren't you going to react? How long have you been down here? Isn't it dull yet?"
A figure descends upside-down, eyes level with yours. He wears a comical bird mask, the beak swaying dangerously close to your nose.
How he's holding that pose, you can't begin to guess.]]
        },
        [6101805] = {
          ContentFR = "<I>« Je n’ai pas le temps de jouer. »</>",
          DialogueId = 6101805,
          GUID = "0F467562",
          NextDialogue = 6101806,
          RougeTalkActorType = 2,
          Subtitle = "I don't have time for this."
        },
        [6101806] = {
          ContentFR = "« Allons, ne sois pas si {性别:froid|froide}. Les vieux de l’Église Élyséenne ne t’ont-ils pas appris ? Une bonne action chaque jour attire la chance !\nAllez, <H>joue avec moi</>. Si tu gagnes, je t’offre une récompense, si tu perds... rien du tout. Pas de punition. Alors ? »",
          DialogueId = 6101806,
          GUID = "0F46758C",
          NextOptions = {
            [1] = 6101807,
            [2] = 6101808
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01",
          Subtitle = [[
"Aw, don't be so frosty. Didn't those Elysian fogeys ever tell you? A good deed a day keeps bad luck away!"
"Come on, play a little game with me. Win, and I'll give you a prize. Lose? No punishment. Nothing's at stake here. What do you say?"]]
        },
        [6101807] = {
          ContentFR = "<I>« D’accord. »</>",
          DialogueId = 6101807,
          GUID = "0F4675B6",
          IsKeyOption = true,
          RougeTalkActorType = 2,
          Subtitle = "Alright then."
        },
        [6101808] = {
          ContentFR = "<I>« Non, vraiment, je n’ai pas le temps. »</>",
          DialogueId = 6101808,
          GUID = "0F4675E0",
          IsKeyOption = true,
          NextDialogue = 6101809,
          RougeTalkActorType = 2,
          Subtitle = "Seriously, I've got things to do."
        },
        [6101809] = {
          ContentFR = "« Bon, bon, inutile de forcer. Je ne suis pas un mauvais bougre, après tout. »\n« La prochaine fois, peut-être ! »",
          DialogueId = 6101809,
          GUID = "0F46760A",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01",
          Subtitle = "\"If you say so. I'm no villain — wouldn't dream of forcing anyone's hand.\"\n\"Next time, then!\""
        },
        [6101901] = {
          ContentFR = "La lueur du feu éclaire le visage ridé d’un vieil homme.\nUn marteau de fer repose dans sa main, et à ses pieds gisent des armes éparpillées.\nQuand ses yeux croisent les tiens, une étincelle de joie y brille un instant.",
          DialogueId = 6101901,
          GUID = "0F468522",
          NextDialogue = 6101902,
          RougeTalkActorType = 3,
          Subtitle = [[
Firelight falls across the withered face of an old man.
An iron hammer rests in his hand, and at his feet lie weapons, scattered across the earth.
At the sight of you, a faint spark of joy kindles in his eyes.]]
        },
        [6101902] = {
          ContentFR = "« Jeune {性别:voyageur|voyageuse}... saurais-tu m’indiquer la route d’Élysium ? »\nSa voix est rauque, éteinte.\n« J’ai tourné en rond si longtemps par ici... mais je n’arrive plus à retrouver le chemin de ma maison... »",
          DialogueId = 6101902,
          GUID = "0F46854C",
          NextOptions = {
            [1] = 6101903
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01",
          Subtitle = [[
"Young one... do you know the road to Elysium?"
His voice is rough, brittle, worn thin by age.
"I have wandered these paths in circles, yet no matter how I search, I cannot find the road that leads me home..."]]
        },
        [6101903] = {
          ContentFR = "<I>Garder le silence</>",
          DialogueId = 6101903,
          GUID = "0F468576",
          NextDialogue = 6101904,
          RougeTalkActorType = 2,
          Subtitle = "Remain silent."
        },
        [6101904] = {
          ContentFR = "« Je vois... toi aussi, tu es perdu, n’est-ce pas ? »\nLe vieillard pousse un long soupir et baisse la tête.",
          DialogueId = 6101904,
          GUID = "0F4685A0",
          NextOptions = {
            [1] = 6101905
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01",
          Subtitle = [[
"I see... you too are lost, are you not?" 
The old man sighs deeply, bowing his head.]]
        },
        [6101905] = {
          ContentFR = "<I>Demander s’il peut te donner une arme</>",
          DialogueId = 6101905,
          GUID = "0F4685CA",
          NextDialogue = 6101906,
          RougeTalkActorType = 2,
          Subtitle = "Ask if he might spare you a weapon."
        },
        [6101906] = {
          ContentFR = "« Une arme ? Tu parles de celles-là, par terre ? »\n« Ah... oui... je me souviens à présent. J’étais... forgeron. »\n« J’ai forgé des armes pour quelques âmes, afin qu’elles s’enfuient, et puis— »",
          DialogueId = 6101906,
          GUID = "0F4685F4",
          NextDialogue = 6101907,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01",
          Subtitle = "\"A weapon? You mean those scattered on the ground?\"\n\"Ah... yes... I remember now. I was... a blacksmith.\"\n\"I forged arms for a few souls, helped them flee... and after that—\""
        },
        [6101907] = {
          ContentFR = "Son regard se voile, comme s’il venait enfin de se rappeler pourquoi il était venu en ce lieu.\nPuis, il secoue doucement la tête et t’adresse un sourire fatigué.",
          DialogueId = 6101907,
          GUID = "0F46861E",
          NextDialogue = 6101908,
          RougeTalkActorType = 3,
          Subtitle = [[
His gaze clouds, as though he has finally remembered why he came to this place.
Then, with a faint shake of the head, he gives you a weary smile.]]
        },
        [6101908] = {
          ContentFR = "« Bien sûr, mon enfant. »\n« Choisis celle qui te plaît. Qu’elle te protège. »",
          DialogueId = 6101908,
          GUID = "0F468648",
          NextOptions = {
            [1] = 6101909,
            [2] = 6101910
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01",
          Subtitle = [[
"Of course, child." 
"Take your pick. May it guard you well."]]
        },
        [6101909] = {
          ContentFR = "<I>Choisir parmi les armes à sa gauche</>",
          DialogueId = 6101909,
          GUID = "0F468672",
          IsKeyOption = true,
          NextDialogue = 6101911,
          RougeTalkActorType = 2,
          Subtitle = "Choose from the weapons to his left."
        },
        [6101910] = {
          ContentFR = "<I>Choisir parmi les armes à sa droite</>",
          DialogueId = 6101910,
          GUID = "0F46869C",
          IsKeyOption = true,
          NextDialogue = 6101911,
          RougeTalkActorType = 2,
          Subtitle = "Choose from the weapons to his right."
        },
        [6101911] = {
          ContentFR = "Tu ranges l’arme choisie.\nDéjà, le vieillard semble t’avoir oublié : ses yeux demeurent fixés sur le marteau dans sa main, perdu dans de sombres pensées.",
          DialogueId = 6101911,
          GUID = "0F4686C6",
          RougeTalkActorType = 3,
          Subtitle = [[
You tuck the weapon away. 
The old man seems to have forgotten you. His gaze lingers on the hammer in his hands, as though lost in solemn reflection.]]
        },
        [6102001] = {
          ContentFR = "Un martèlement métallique résonne. Des étincelles jaillissent, se fondant dans la lumière du feu.\nEn suivant le bruit, tu découvres le vieil homme devant une forge de fortune, son marteau s’abattant avec force. La sueur perle à son front.",
          DialogueId = 6102001,
          GUID = "0F46958A",
          NextDialogue = 6102002,
          RougeTalkActorType = 3,
          Subtitle = [[
You hear the clash of metal upon metal.
Following the sound, you find the old man at a makeshift forge, hammer swinging with vigour. Sparks leap into the campfire's glow as sweat trickles down his brow.]]
        },
        [6102002] = {
          ContentFR = "« Bonjour, jeune {性别:voyageur|voyageuse} ! »\nIl te salue d’une voix pleine de chaleur.",
          DialogueId = 6102002,
          GUID = "0F4695B4",
          NextOptions = {
            [1] = 6102003
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01",
          Subtitle = [[
"Ah, greetings, young one!" 
The old man calls out with cheerful warmth.]]
        },
        [6102003] = {
          ContentFR = "<I>Bonjour</>",
          DialogueId = 6102003,
          GUID = "0F4695DE",
          NextDialogue = 6102004,
          RougeTalkActorType = 2,
          Subtitle = "Hello."
        },
        [6102004] = {
          ContentFR = "« On dirait que toi aussi, tu es coincé dans cet endroit, hein ? »\nIl se désigne d’un geste, un sourire en coin. « Moi aussi. »",
          DialogueId = 6102004,
          GUID = "0F469608",
          NextOptions = {
            [1] = 6102005
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01",
          Subtitle = "\"Looks like you're trapped here too?\" He gestures at himself with a wry smile. \"So am I.\""
        },
        [6102005] = {
          ContentFR = "<I>Nous nous retrouvons</>",
          DialogueId = 6102005,
          GUID = "0F469632",
          NextDialogue = 6102006,
          RougeTalkActorType = 2,
          Subtitle = "We meet again."
        },
        [6102006] = {
          ContentFR = "« Nous nous sommes déjà rencontrés ? » dit-il, troublé.\n« Ma mémoire me joue des tours... je n’arrive plus à me souvenir de grand-chose, ces derniers temps... »",
          DialogueId = 6102006,
          GUID = "0F46965C",
          NextDialogue = 6102007,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01",
          Subtitle = "\"Again? We've met before?\" he asks, puzzled. \"I can't seem to recall... My memory's not what it used to be...\""
        },
        [6102007] = {
          ContentFR = "Il rit d’un air franc, puis désigne la forge :\n« Cet endroit est dangereux. J’ai forgé quelques armes : prends-en une. »\n« Puisque je ne trouve pas de sortie, autant revenir à mon métier. Qui sait ? Peut-être qu’un jour, l’une de ces lames tombera entre les mains d’un grand chevalier, et qu’il nous mènera enfin hors de cet enfer. »",
          DialogueId = 6102007,
          GUID = "0F469686",
          NextOptions = {
            [1] = 6102008,
            [2] = 6102009,
            [3] = 6102010
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01",
          Subtitle = "\"It's not safe round here. I've forged a few weapons — feel free to take one.\" \nHe gestures heartily toward his work. \n\"Since I can't find a way out, I thought I'd return to my craft. Who knows — perhaps one day, one of these blades will find its way to a worthy knight, and they might lead us out of this wretched place.\""
        },
        [6102008] = {
          ContentFR = "<I>Choisir parmi les armes fraîchement forgées</>",
          DialogueId = 6102008,
          GUID = "0F4696B0",
          IsKeyOption = true,
          NextDialogue = 6102011,
          RougeTalkActorType = 2,
          Subtitle = "Choose from the newly forged weapons."
        },
        [6102009] = {
          ContentFR = "<I>Choisir parmi les pièces terminées, soigneusement rangées</>",
          DialogueId = 6102009,
          GUID = "0F4696DA",
          IsKeyOption = true,
          NextDialogue = 6102011,
          RougeTalkActorType = 2,
          Subtitle = "Choose from the neatly arranged finished pieces."
        },
        [6102010] = {
          ContentFR = "<I>Choisir dans le coin poussiéreux de l’atelier</>",
          DialogueId = 6102010,
          GUID = "0F469704",
          IsKeyOption = true,
          NextDialogue = 6102011,
          RougeTalkActorType = 2,
          Subtitle = "Choose from the dusty corner of the forge."
        },
        [6102011] = {
          ContentFR = "Tu repars avec l’arme choisie, tandis que la chaleureuse voix du vieillard t’accompagne encore quelque temps.",
          DialogueId = 6102011,
          GUID = "0F46972E",
          RougeTalkActorType = 3,
          Subtitle = "With your chosen weapon in hand, you set off once more, the old man's warm farewell echoing behind you."
        },
        [6102101] = {
          ContentFR = "La lueur vacillante du feu dessine le profil penché d’une poétesse.\nÀ demi agenouillée près des flammes, elle tend la main et trace lentement de sinueux motifs dans la cendre.",
          DialogueId = 6102101,
          GUID = "0F46A5F2",
          NextDialogue = 6102102,
          RougeTalkActorType = 3,
          Subtitle = [[
The campfire flickers, etching the poet's downcast profile in shifting light.
She half-kneels by the fire, tracing winding patterns in the ash with her fingertip.]]
        },
        [6102102] = {
          ContentFR = "« S’il n’existe nulle échappatoire... alors accepte ton destin. »\n« Si les mots ne peuvent être des lames pour percer le mensonge, qu’ils deviennent les briques de nos songes... »\nElle s’interrompt, son doigt suspendu dans l’air.\n« Hmm... »",
          DialogueId = 6102102,
          GUID = "0F46A61C",
          NextDialogue = 6102103,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01",
          Subtitle = "\"If there is nowhere left to run, then embrace your fate.\"\n\"If words cannot become blades to pierce through lies, then let them be bricks with which to build our dreams—\"\nThe poet pauses, lifting her finger slightly.\n\"Hmm...\""
        },
        [6102103] = {
          ContentFR = "Un souvenir s’éveille au fond de ta mémoire : tu es {性别:certain|certaine} d’avoir déjà entendu ce poème.\nUne volute de cendre effleure ta joue, et presque malgré toi, tu souffles la phrase manquante—",
          DialogueId = 6102103,
          GUID = "0F46A646",
          NextOptions = {
            [1] = 6102104
          },
          RougeTalkActorType = 3,
          Subtitle = "A memory stirs within your mind — you are certain you have heard this poem before.\nA wisp of ash brushes your cheek, and almost without thinking, you whisper the missing final line:"
        },
        [6102104] = {
          ContentFR = "<I>« Écrire un mensonge, et allumer une flamme qui jamais ne s’éteindra. »</>",
          DialogueId = 6102104,
          GUID = "0F46A670",
          NextDialogue = 6102105,
          RougeTalkActorType = 2,
          Subtitle = "\"To write a lie, and kindle a flame that never dies.\""
        },
        [6102105] = {
          ContentFR = "« ... ! »\nElle lève la tête, ses yeux s’illuminent d’un étonnement joyeux.\n« Quelle phrase merveilleuse... c’est le vers final que j’attendais ! Quelle chance de rencontrer {性别:un|une} semblable en ce lieu. »",
          DialogueId = 6102105,
          GUID = "0F46A69A",
          NextOptions = {
            [1] = 6102106
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01",
          Subtitle = "\"Hmm...!?\" \nThe poet lifts her gaze, astonishment softening into joy. \n\"What a marvellous turn of phrase — just the ending I had longed for! How fortunate, to find a kindred spirit here.\""
        },
        [6102106] = {
          ContentFR = "<I>« En vérité, c’est toi qui l’as écrit... dans un autre temps. »</>",
          DialogueId = 6102106,
          GUID = "0F46A6C4",
          NextDialogue = 6102107,
          RougeTalkActorType = 2,
          Subtitle = "\"It was you who wrote it — in another time.\""
        },
        [6102107] = {
          ContentFR = "« Un autre... temps ? »\nLa surprise passe sur son visage, vite remplacée par une lueur ardente, comme attisée par les flammes.\n« Je comprends... Tu es le cœur de cette épopée. {性别:Celui|Celle} que je rencontrerai encore, au détour d’une autre trame du temps, n’est-ce pas ? »",
          DialogueId = 6102107,
          GUID = "0F46A6EE",
          NextOptions = {
            [1] = 6102108
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01",
          Subtitle = "\"'Another time'...?\" \nAt first she looks surprised, then her eyes brighten, kindled like the firelight itself. \n\"Ah... So you are the one — the heart of this poem. The one I shall meet again, upon another path through time... is that it?\""
        },
        [6102108] = {
          ContentFR = "<I>Hocher la tête</>",
          DialogueId = 6102108,
          GUID = "0F46A718",
          NextDialogue = 6102109,
          RougeTalkActorType = 2,
          Subtitle = "Nod."
        },
        [6102109] = {
          ContentFR = "« Alors ce poème... est-ce le tien, ou le mien ? Charmant paradoxe... Les érudits de l’Académie de l’Arbre Sacré en perdraient la raison ! »\nElle rit doucement.\n« Quand nous nous reverrons, permets-moi de composer un poème pour toi. Pour l’heure, tends-moi ta main, que je t’offre ma bénédiction. »",
          DialogueId = 6102109,
          GUID = "0F46A742",
          NextOptions = {
            [1] = 6102110,
            [2] = 6102111
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01",
          Subtitle = "\"Then tell me — who truly wrote this poem, you or I? Heh... What a beguiling paradox... The Sacred Tree Scholars would be enthralled by such a tale.\"\nThe poet chuckles.\n\"When next we meet, allow me to write you a verse of your own. For now — give me your hand, that I might leave you with my blessing.\""
        },
        [6102110] = {
          ContentFR = "<I>Tendre la main gauche</>",
          DialogueId = 6102110,
          GUID = "0F46A76C",
          IsKeyOption = true,
          NextDialogue = 6102112,
          RougeTalkActorType = 2,
          Subtitle = "Extend your left hand."
        },
        [6102111] = {
          ContentFR = "<I>Tendre la main droite</>",
          DialogueId = 6102111,
          GUID = "0F46A796",
          IsKeyOption = true,
          NextDialogue = 6102112,
          RougeTalkActorType = 2,
          Subtitle = "Extend your right hand."
        },
        [6102112] = {
          ContentFR = "Avec la cendre qui lui reste au bout des doigts, la poétesse inscrit quelques signes dans ta paume.\nTu ne saurais en déchiffrer le sens, mais leur chaleur vive pulse encore, ardente sans brûler.\nQuand tu relèves les yeux, elle a disparu.",
          DialogueId = 6102112,
          GUID = "0F46A7C0",
          RougeTalkActorType = 3,
          Subtitle = "With the last of the ash upon her fingertip, the poet inscribes something upon your palm.\nYou cannot read the symbols, but their warmth feels vivid and ardent — and yet not burning in the least.\nWhen you look up again, she is gone."
        },
        [6102201] = {
          ContentFR = "« Ô dieu changeant des destins, tantôt nous donnes-tu la joie, tantôt nous abandonnes-tu à la douleur... »\n« Gardons toujours un cœur pieux... Car ton fil immaculé nous liera, au bout du chemin, au Paradis des Paradis... »\nLe garçon lit avec une ferveur appliquée, inconscient de ta présence.",
          DialogueId = 6102201,
          GUID = "0F46B65A",
          NextDialogue = 6102202,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room321_Char01",
          Subtitle = [[
"O fickle God of Fate... At times Thou grantest joy, at times castest down in woe..." 
"Yet still we cleave to reverence... For Thy thread of purest white shall, in the end, bind us to the bliss of the Heaven above Heavens..." 
The boy recites with solemn devotion, wholly unaware of your presence.]]
        },
        [6102202] = {
          ContentFR = "Tu t’approches en silence, jetant un coup d’œil rapide à l’ouvrage.\nComme dans tes souvenirs, les pages de l’hymnaire sont maculées d’une écriture noire, tordue, qui semble vouloir s’arracher au papier.",
          DialogueId = 6102202,
          GUID = "0F46B684",
          NextDialogue = 6102203,
          RougeTalkActorType = 3,
          Subtitle = "You draw nearer, stealing a glance at the book in his hands.\nJust as you remembered, the hymnal pages are defaced with writhing black script steeped in malice — as though straining to tear itself free of the page."
        },
        [6102203] = {
          ContentFR = "« Oh... bonjour. Toi aussi, tu veux lire ? »\nEnfin il te remarque, levant les yeux avec curiosité.",
          DialogueId = 6102203,
          GUID = "0F46B6AE",
          NextOptions = {
            [1] = 6102204,
            [2] = 6102208
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room321_Char01",
          Subtitle = [[
"Hello... are you here to read as well?" 
At last he notices you, lifting his head in quiet curiosity.]]
        },
        [6102204] = {
          ContentFR = "<I>Empêcher de lire</>",
          DialogueId = 6102204,
          GUID = "0F46B6D8",
          IsKeyOption = true,
          NextDialogue = 6102205,
          RougeTalkActorType = 2,
          Subtitle = "Stop him from reading."
        },
        [6102205] = {
          ContentFR = "Tu arraches le livre de ses mains et le refermes d’un geste sec.",
          DialogueId = 6102205,
          GUID = "0F46B702",
          NextDialogue = 6102206,
          RougeTalkActorType = 3,
          Subtitle = "You pull the book from his hands and snap it shut."
        },
        [6102206] = {
          ContentFR = "« Qu’est-ce que... !? »\nIl se redresse, inquiet, puis baisse les yeux vers ses paumes vides.\n« Attends... je n’ai plus besoin de lire ? Je... je suis libre ? »",
          DialogueId = 6102206,
          GUID = "0F46B72C",
          NextDialogue = 6102207,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room321_Char01",
          Subtitle = "\"What are you—!?\" \nHe exclaims, worry creasing his brow. Then, staring at his empty hands, his voice drops to a murmur.\n\"Wait... I don't have to read anymore? I... I'm free?\""
        },
        [6102207] = {
          ContentFR = "Tu ignores la douleur qui te brûle les doigts, et lui adresses un sourire discret.\nPuis tu jettes le livre au feu.\nLes flammes s’élancent d’un coup, des ronces noires s’y mêlent, te fondant dessus comme une tempête.",
          DialogueId = 6102207,
          GUID = "0F46B756",
          RougeTalkActorType = 3,
          Subtitle = "You suppress the pain prickling at your fingertips, and offer a faint smile. Then, you hurl the book into the fire.\nThe flames roar skyward — black thistles rising with them, lashing upward like a storm."
        },
        [6102208] = {
          ContentFR = "<I>Garder le silence</>",
          DialogueId = 6102208,
          GUID = "0F46B780",
          IsKeyOption = true,
          NextDialogue = 6102209,
          RougeTalkActorType = 2,
          Subtitle = "Remain silent."
        },
        [6102209] = {
          ContentFR = "Tu le sais : rien de ce que tu pourrais faire ne changerait son destin.\nUn autre devoir t’attend — rassembler les Lumistellas, et mettre fin à ce cauchemar sans fin.",
          DialogueId = 6102209,
          GUID = "0F46B7AA",
          NextDialogue = 6102210,
          RougeTalkActorType = 3,
          Subtitle = [[
You know, in your heart, that whatever you do now will not change what awaits him.
There is a greater task before you: to gather Glazeystal, and bring this long nightmare to an end.]]
        },
        [6102210] = {
          ContentFR = "En un instant, les ronces noires surgissent et engloutissent l’enfant.\nTu pousses un léger soupir... et poursuis ta route.",
          DialogueId = 6102210,
          GUID = "0F46B7D4",
          RougeTalkActorType = 3,
          Subtitle = [[
In the blink of an eye, black thistles surge forth, swallowing the boy whole. 
You let out a soft sigh... and press onward.]]
        },
        [6102301] = {
          ContentFR = "« Regarde, mon enfant... il y a un feu de camp ici. »\nDe l’autre côté des flammes, une femme solitaire relève la tête et sourit. La lumière dévoile son visage émacié.\n« Comme c’est doux... merci, {性别:étranger bienveillant|étrangère bienveillante}. »",
          DialogueId = 6102301,
          GUID = "0F46C6C2",
          NextOptions = {
            [1] = 6102302
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01",
          Subtitle = "\"My child... quick — look, there's a fire here.\" \nOn the far side of the flames, a lone woman lifts her head and smiles. The firelight reveals the gaunt contours of her face.\n\"So warm... Thank you, kind stranger.\""
        },
        [6102302] = {
          ContentFR = "<I>Demander où est son enfant</>",
          DialogueId = 6102302,
          GUID = "0F46C6EC",
          NextDialogue = 6102303,
          RougeTalkActorType = 2,
          Subtitle = "Ask where her child is."
        },
        [6102303] = {
          ContentFR = "« Mon enfant est juste là... »",
          DialogueId = 6102303,
          GUID = "0F46C716",
          NextDialogue = 6102304,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01",
          Subtitle = "\"My child is right here — see?\""
        },
        [6102304] = {
          ContentFR = "Tu suis son geste. \nDevant toi, une pierre haute comme un enfant, couverte de mousse.\nPrès de son sommet, serti dans une fissure, brille un bijou, une broche étincelante, que la verdure enlace comme un cœur enseveli.\nLa femme caresse tendrement la surface humide, insensible à la boue qui lui colle aux doigts.",
          DialogueId = 6102304,
          GUID = "0F46C740",
          NextOptions = {
            [1] = 6102305,
            [2] = 6102308
          },
          RougeTalkActorType = 3,
          Subtitle = "You follow her gaze to a moss-covered stone, about waist height.\nSet into a crevice near its crown, a glittering brooch gleams, ringed with delicate moss — like a heart entombed.\nShe tenderly strokes the stone's surface, heedless of the soil clinging to her fingers."
        },
        [6102305] = {
          ContentFR = "<I>Dire la vérité</>",
          DialogueId = 6102305,
          GUID = "0F46C76A",
          IsKeyOption = true,
          NextDialogue = 6102306,
          RougeTalkActorType = 2,
          Subtitle = "Tell her the truth."
        },
        [6102306] = {
          ContentFR = "« Quelles absurdités dis-tu là ?! »\nUne rage soudaine embrase son regard. Elle s’interpose devant la pierre, la protégeant de tout son corps, et crie d’une voix déchirée :\n« C’est mon enfant… elle est là ! Personne ne me la prendra… jamais ! »",
          DialogueId = 6102306,
          GUID = "0F46C794",
          NextDialogue = 6102307,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01",
          Subtitle = "\"What nonsense are you spouting!?\" \nHer eyes flare with sudden fury. She throws herself before the stone, shielding it with her body as her voice shatters into a hysterical scream:\n\"This is my child — she's right here! No one will take her from me... never again!\""
        },
        [6102307] = {
          ContentFR = "Tu restes muet.\nTu aurais dû savoir que briser ce rêve ne changerait rien.\nAlors tu te relèves et t’éloignes, laissant le feu à la femme et à son \"enfant\".\nMais dans l’ombre qui guette, un Umbré tapi bondit sur toi—",
          DialogueId = 6102307,
          GUID = "0F46C7BE",
          RougeTalkActorType = 3,
          Subtitle = "You fall silent. \nPerhaps it was folly to pierce this fragile dream — you knew from the start that it would change nothing.\nSo you rise and walk away, leaving the fire to warm the woman... and her \"child.\" But in the darkness beyond, an Abyssoid stirs — and strikes."
        },
        [6102308] = {
          ContentFR = "<I>Aller dans son sens</>",
          DialogueId = 6102308,
          GUID = "0F46C7E8",
          IsKeyOption = true,
          NextDialogue = 6102309,
          RougeTalkActorType = 2,
          Subtitle = "Play along."
        },
        [6102309] = {
          ContentFR = "« Merci... Elle est craintive, mais elle t’apprécie, je le sens. »\nSa voix est douce, ses mains continuent de caresser machinalement la pierre.\n« Tu es {性别:parti seul|partie seule} ? Ce n’est pas bien... Ta famille doit s’inquiéter. Rentre vite chez toi. »",
          DialogueId = 6102309,
          GUID = "0F46C812",
          NextDialogue = 6102310,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01",
          Subtitle = "\"Thank you. She's always been shy around strangers — but I think she rather likes you.\"\nThe woman's voice is gentle. Her hands keep stroking the moss-grown stone with tender, absent rhythm.\n\"Are you alone on the road? That will not do — your family must be worried... Hurry home now.\""
        },
        [6102310] = {
          ContentFR = "Tu la remercies poliment, puis reprends ta route.\nDerrière toi, la femme et son \"enfant\" s’estompent, avalés par les ombres au-delà du cercle de lumière.",
          DialogueId = 6102310,
          GUID = "0F46C83C",
          RougeTalkActorType = 3,
          Subtitle = [[
You thank her politely and turn to leave.
Behind you, the woman and her "child" fade into the shadows beyond the firelight.]]
        },
        [6102401] = {
          ContentFR = "« ... disparues... disparues... »\nLa jeune fille, les yeux vides, rampe à même le sol, ses doigts griffant la terre, les ongles prêts à s’y briser.",
          DialogueId = 6102401,
          GUID = "0F46D72A",
          NextOptions = {
            [1] = 6102402
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01",
          Subtitle = [[
"Gone... They're gone..." 
The hollow-eyed girl lies prone upon the ground, her hands fumbling blindly, nails digging into the earth.]]
        },
        [6102402] = {
          ContentFR = "<I>Demander ce qu’elle cherche</>",
          DialogueId = 6102402,
          GUID = "0F46D754",
          NextDialogue = 6102403,
          RougeTalkActorType = 2,
          Subtitle = "Ask what she is searching for."
        },
        [6102403] = {
          ContentFR = "« Mes pierres... mes pierres... elles étaient là, juste là... »\nElle murmure, le désespoir fixé sur le feu de camp à tes pieds.\n« Ma flamme... elle s’éteint... que faire... que faire... »",
          DialogueId = 6102403,
          GUID = "0F46D77E",
          NextOptions = {
            [1] = 6102404,
            [2] = 6102408
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01",
          Subtitle = [[
"My stones... my stones... I swear they were right here..."
She whispers, her gaze locked in despair upon the campfire at your feet.
"My flame... it's fading... What am I to do... what am I to do..."]]
        },
        [6102404] = {
          ContentFR = "<I>Aider la jeune fille</>",
          DialogueId = 6102404,
          GUID = "0F46D7A8",
          IsKeyOption = true,
          NextDialogue = 6102405,
          RougeTalkActorType = 2,
          Subtitle = "Help her."
        },
        [6102405] = {
          ContentFR = "Tu essaies de te souvenir de l’éclat de ces pierres qu’elle chérissait. Leur origine t’échappe, mais ton instinct te souffle qu’avec un peu de magie de feu, tu pourrais en recréer.\nAlors, concentrant ton pouvoir dans les flammes du feu de camp...\nEn un éclair, de minuscules gemmes dorées chutent comme des étoiles filantes, tintant doucement en heurtant le sol, pures comme des clochettes.",
          DialogueId = 6102405,
          GUID = "0F46D7D2",
          NextDialogue = 6102406,
          RougeTalkActorType = 3,
          Subtitle = "You try to recall the stones she cherished. Though their origin eludes you, you sense that fire magic could shape something akin to them.\nUsing the campfire as a focus, you gather your power, channelling it through its heat...\nIn an instant, golden fragments fall like meteors from above — ringing softly as they strike the earth, each note bright as a bell."
        },
        [6102406] = {
          ContentFR = "« Ah... ! Mes pierres — ce sont mes pierres ! Merci, messager des dieux ! »\nElle les ramasse une à une, ravie comme une enfant, les serrant contre elle dans le pli de sa robe.",
          DialogueId = 6102406,
          GUID = "0F46D7FC",
          NextDialogue = 6102407,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01",
          Subtitle = "\"Ah...! My stones — these are my stones! Thank you, messenger of the gods!\"\nShe scoops them up one by one, cradling them in the fold of her skirt like treasures beyond price."
        },
        [6102407] = {
          ContentFR = "Elles sont identiques aux cristaux que tu avais aperçus autrefois dans ses bras. Tu ne peux t’empêcher de songer : étaient-elles depuis toujours les traces oubliées d’un de tes anciens voyages ?\nQu’importe. Elle a retrouvé sa \"certitude\". Toi, tu dois poursuivre ton voyage.",
          DialogueId = 6102407,
          GUID = "0F46D826",
          RougeTalkActorType = 3,
          Subtitle = "They match the crystals you once glimpsed in her arms. You cannot help but wonder: were they always there — fragments left behind in some forgotten journey of your own?\nEither way, the girl has reclaimed her \"certainty\"... And you, too, must walk on."
        },
        [6102408] = {
          ContentFR = "<I>Dire que le monde ne peut pas toujours céder à nos désirs</>",
          DialogueId = 6102408,
          GUID = "0F46D850",
          IsKeyOption = true,
          NextDialogue = 6102409,
          RougeTalkActorType = 2,
          Subtitle = "Tell her that life doesn't always go the way we hope."
        },
        [6102409] = {
          ContentFR = "« Je sais... je sais. »\n« C’est pour cela que j’ai renoncé... Je n’ouvre plus les livres, je ne questionne plus l’origine de la magie, je ne demande plus ce qui se cache dans la tour... »\n« Tout ce que je veux, maintenant, c’est un peu de lumière... même cela m’est refusé ? »",
          DialogueId = 6102409,
          GUID = "0F46D87A",
          NextDialogue = 6102410,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01",
          Subtitle = [[
"I know... I know."
"That's why I've given up... I no longer read the books, nor ponder the origin of magic, nor ask what lies within that tower..." 
"All I want now is a scrap of firelight.. Is even that too much to ask?"]]
        },
        [6102410] = {
          ContentFR = "Tu restes muet.\nD’un geste brusque, elle se relève. Avant que tu ne puisses réagir, elle franchit le brasier d’un pas résolu.\nSon corps se fond lentement aux flammes, jusqu’à disparaître.\nTu détournes ton regard... et continues ta route.",
          DialogueId = 6102410,
          GUID = "0F46D8A4",
          RougeTalkActorType = 3,
          Subtitle = [[
You are left speechless. 
Suddenly, the girl rises to her feet. Before you can react, she steps resolutely into the fire.
Her form melts slowly into the blaze, until not a trace remains.
You turn away... and press on.]]
        },
        [6102501] = {
          ContentFR = "Le feu brûle paisiblement. Cette fois, aucune vision n’y danse.\nAlors que tu t’apprêtes à partir, ton regard s’accroche à de minuscules éclats scintillants—\nDe petites pierres dorées, éparpillées sur le sol, pareilles à des étoiles tombées sur la terre.",
          DialogueId = 6102501,
          GUID = "0F46E792",
          NextOptions = {
            [1] = 6102502,
            [2] = 6102506
          },
          RougeTalkActorType = 3,
          Subtitle = "The campfire burns quietly. This time, no Phantasms stir within its glow. \nAs you turn to leave, something catches your eye —\nScattered across the soil at your feet, tiny golden stones gleam like stars fallen from the heavens."
        },
        [6102502] = {
          ContentFR = "<I>Ramasser les pierres et les jeter dans le feu</>",
          DialogueId = 6102502,
          GUID = "0F46E7BC",
          IsKeyOption = true,
          NextDialogue = 6102503,
          RougeTalkActorType = 2,
          Subtitle = "Pick up the stones and cast them into the fire."
        },
        [6102503] = {
          ContentFR = "La flamme s’élève, plus vive, puis s’étend étrangement de côté.\nTu recules d’un pas prudent, soudain, une silhouette surgit du brasier. Ce qui se déploie autour d’elle n’est pas du feu, mais des mèches étincelantes de chevelure.",
          DialogueId = 6102503,
          GUID = "0F46E7E6",
          NextDialogue = 6102504,
          RougeTalkActorType = 3,
          Subtitle = "The flames leap higher — then stretch unnaturally to either side.\nYou step back, wary. Suddenly, a figure takes shape within the blaze... And you see that the light streaming outward is not flame at all, but strands of a girl's hair."
        },
        [6102504] = {
          ContentFR = "« Bonjour ! Tu as trouvé mes pierres, n’est-ce pas ? »\nElle bondit hors du feu, secouant la tête : de ses cheveux jaillissent des fragments dorés qui tintent joyeusement en tombant.\n« Plus besoin de chercher dehors — regarde ! Il me suffit d’entrer dans le feu, et je peux en créer moi-même ! »",
          DialogueId = 6102504,
          GUID = "0F46E810",
          NextDialogue = 6102505,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room324_Char01",
          Subtitle = "\"Hello! You found my stones, didn't you?\"\nThe girl leaps from the fire, tossing her head as golden pebbles tumble from her hair with a bright, crackling chime.\n\"Now I need never search again — see? So long as I step into the fire, I can make the stones myself!\""
        },
        [6102505] = {
          ContentFR = "« Pardonne-moi, je n’ai pas le temps de bavarder, il m’en faut encore cent quarante-six. »\n« Mais tiens, j’ai découvert ceci. Peut-être cela t’aidera-t-il. Prends-le, et que ton voyage soit sûr et rapide ! »\nElle glisse un objet dans ta main, puis retourne se fondre dans les flammes.",
          DialogueId = 6102505,
          GUID = "0F46E83A",
          NextDialogue = 6102510,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room324_Char01",
          Subtitle = "\"Forgive me, I've no time for chitchat — I'm still far from collecting all one hundred and forty-six.\"\n\"But I found something that may aid you. Please, take it — and may your journey be swift and safe!\"\nShe presses something into your hand, then vanishes once more into the flames."
        },
        [6102506] = {
          ContentFR = "<I>Observer en silence</>",
          DialogueId = 6102506,
          GUID = "0F46E864",
          IsKeyOption = true,
          NextDialogue = 6102507,
          RougeTalkActorType = 2,
          Subtitle = "Observe quietly."
        },
        [6102507] = {
          ContentFR = "La flamme continue de brûler, paisible. Dans le murmure du feu, il te semble entendre une voix.",
          DialogueId = 6102507,
          GUID = "0F46E88E",
          NextDialogue = 6102508,
          RougeTalkActorType = 3,
          Subtitle = "The fire burns on, steady and soft. For a moment, you fancy you hear a voice within the flames."
        },
        [6102508] = {
          ContentFR = "« Oui... oui. J’ai compris. »\nLa voix paisible de la jeune fille résonne, empreinte de douceur.\n« Les questions doivent savoir où s’arrêter. Le feu est un don des dieux, non une réaction de matière. Comme ces petites pierres : des trésors divins, qui m’offrent un sommeil apaisé... »",
          DialogueId = 6102508,
          GUID = "0F46E8B8",
          NextDialogue = 6102509,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room324_Char01",
          Subtitle = "\"Yes... yes. I'll keep it in mind.\"\nThe girl's gentle, contented voice drifts from the fire.\n\"Questions must know their limits. Flame is the gift of the gods, not merely matter reacting to heat. Just like these stones — treasures bestowed upon me, that I might sleep in peace...\""
        },
        [6102509] = {
          ContentFR = "Tu tournes les talons sans un mot. Une pierre roule devant toi, ton pas l’écrase en poussière sans que tu y prennes garde.\nAinsi donc, les trésors des dieux... sont aussi fragiles.",
          DialogueId = 6102509,
          GUID = "0F46E8E2",
          NextDialogue = 6102510,
          RougeTalkActorType = 3,
          Subtitle = "You turn away in silence. A stone rolls to the path before you. You step forward — and inadvertently crush it beneath your boot.\nThe treasure of the gods... so fragile, after all."
        },
        [6102510] = {
          ContentFR = "Et tu songes : cette flamme était-elle la \"certitude\" de son bonheur, ou bien le \"carcan\" qui la retient prisonnière ?\nPeut-être n’y a-t-il jamais eu de différence.",
          DialogueId = 6102510,
          GUID = "0F46E90C",
          RougeTalkActorType = 3,
          Subtitle = "And you wonder — was that flame a \"certainty\" that granted her peace... or a \"shackle\" that bound her still? \nPerhaps the two were never different at all."
        },
        [6102601] = {
          ContentFR = "« Pardon... tout est ma faute... Je suis trop bête, je n’ai pas retenu les hymnes... Trop paresseuse pour écouter les sermons jusqu’au bout... »\n« Ô dieux... pardonnez-moi... »",
          DialogueId = 6102601,
          GUID = "0F46F7FA",
          NextDialogue = 6102602,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01",
          Subtitle = [[
"Forgive me... it's all my fault... I'm too stupid to remember the hymns... Too lazy to sit through the sermons..."
"O divine ones, please forgive me..."]]
        },
        [6102602] = {
          ContentFR = "Elle confesse dans le vide, ou peut-être ne distingue-t-elle plus les vivants.\nElle paraît encore plus affaiblie que la dernière fois : ses yeux eux-mêmes se sont ternis.",
          DialogueId = 6102602,
          GUID = "0F46F824",
          NextDialogue = 6102603,
          RougeTalkActorType = 3,
          Subtitle = "The girl murmurs her confession as though no one's watching — or perhaps, she no longer sees anyone at all.\nShe looks worse than last time; even her eyes have lost their light."
        },
        [6102603] = {
          ContentFR = "« Vous... {性别:le voyageur|la voyageuse}... déjà... tant de temps passé ? »\nEnfin, elle vous aperçoit, sa tête se tourne avec lenteur.\n« {性别:Voyageur|Voyageuse}... dites-moi... pourquoi ? Pourquoi, malgré mes prières jour et nuit, les dieux ne me répondent-ils jamais ? »",
          DialogueId = 6102603,
          GUID = "0F46F84E",
          NextOptions = {
            [1] = 6102604,
            [2] = 6102608
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01",
          Subtitle = "\"You are... the traveller... Has it been so long already?\" \nAt last, she notices you — turning her head with weary slowness. \n\"Traveller... tell me... why is it that though I pray day and night, the gods never answer?\""
        },
        [6102604] = {
          ContentFR = "<I>Encourager à continuer de prier</>",
          DialogueId = 6102604,
          GUID = "0F46F878",
          IsKeyOption = true,
          NextDialogue = 6102605,
          RougeTalkActorType = 2,
          Subtitle = "Encourage her to continue her prayers."
        },
        [6102605] = {
          ContentFR = "Ce n’est pas encore l’heure de réécrire son destin. Alors, tu prolonges le mensonge, car parfois, un mensonge est encore une forme d’espérance.\nTu lui assures que si elle continue de prier, un jour, le salut viendra.\nEt ce n’est pas tout à fait faux : tu crois que l’Abysse sera vaincue. Mais ses prières n’y changeront rien. La vérité repose non dans le rite, mais dans la lanterne que tu tiens.",
          DialogueId = 6102605,
          GUID = "0F46F8A2",
          NextDialogue = 6102606,
          RougeTalkActorType = 3,
          Subtitle = "It was not yet time to change her fate. So you let the lie endure — for even falsehood may serve as a form of hope.\nYou tell her that if she continues to pray, then salvation will come one day.\nAnd it is not wholly untrue. You believe the Abyss may yet be overcome. It's just that her prayers do not matter. The truth lies not in ritual — but in the Lantern you bear."
        },
        [6102606] = {
          ContentFR = "« Je comprends... Je vous crois. »\nElle joint les mains et reprend sa prière, sa voix plus ferme.",
          DialogueId = 6102606,
          GUID = "0F46F8CC",
          NextDialogue = 6102607,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01",
          Subtitle = [[
"I see... I believe you." 
She clasps her hands and resumes her prayers, her voice steadier than before.]]
        },
        [6102607] = {
          ContentFR = "Tu pousses un soupir discret, serres la lanterne, et reprends ta marche.",
          DialogueId = 6102607,
          GUID = "0F46F8F6",
          RougeTalkActorType = 3,
          Subtitle = "With a quiet sigh, you tighten your grip on the Lantern — and press onward."
        },
        [6102608] = {
          ContentFR = "<I>Dire que les dieux ne répondent pas</>",
          DialogueId = 6102608,
          GUID = "0F46F920",
          IsKeyOption = true,
          NextDialogue = 6102609,
          RougeTalkActorType = 2,
          Subtitle = "Tell her the gods will not answer."
        },
        [6102609] = {
          ContentFR = "« Les dieux... ne me répondront pas ?\nEst-ce à cause de mes péchés ? Parce que je ne mérite pas d’être sauvée ? »\nSes yeux se noient de désespoir, des larmes glissent sur ses joues couvertes de plaies.",
          DialogueId = 6102609,
          GUID = "0F46F94A",
          NextOptions = {
            [1] = 6102610
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01",
          Subtitle = [[
"The gods... will never answer me?" 
"Is it because my sins are too deep... that I am no longer worthy of salvation?" 
She looks at you in despair, tears slipping down cheeks already pocked with sores.]]
        },
        [6102610] = {
          ContentFR = "<I>« Parce que tu n’as jamais péché. »</>",
          DialogueId = 6102610,
          GUID = "0F46F974",
          NextDialogue = 6102611,
          RougeTalkActorType = 2,
          Subtitle = "\"It is because you never bore any sin.\""
        },
        [6102611] = {
          ContentFR = "« Hein... ? »\nElle reste figée, la confusion dans le regard.",
          DialogueId = 6102611,
          GUID = "0F46F99E",
          NextDialogue = 6102612,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01",
          Subtitle = [[
"Huh...?" 
The girl freezes, her eyes wide with confusion.]]
        },
        [6102612] = {
          ContentFR = "Tu lui offres un sourire résolu, promettant que tu trouveras un moyen de mettre fin à sa souffrance.\nElle acquiesce vaguement... et tu remarques alors que ses plaies ne saignent plus.\nTu lui fais un signe d’adieu, serres la lanterne... et reprends ton chemin.",
          DialogueId = 6102612,
          GUID = "0F46F9C8",
          RougeTalkActorType = 3,
          Subtitle = "You give her a steady smile and make her a promise: that you will find a way to end her suffering.\nShe stares at you, half comprehending... and gives a faint nod. Then you notice — her wounds have ceased to bleed.\nWith a final wave, you tighten your grip on the Lantern, and press onward."
        },
        [6102701] = {
          ContentFR = "« Fusa, Déesse de la Pleine Lune — »\n« Souveraine des sentiers radieux, tisseuse des fils du destin... »\n« Sous la coupole céleste et dans l’éclat de la lune, reçois notre hymne fervent... »",
          DialogueId = 6102701,
          GUID = "0F470862",
          NextDialogue = 6102702,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room326_Char01",
          Subtitle = "\"Fusa, Goddess of the Full Moon—\"\n\"Mistress of radiant paths, Weaver of destiny's threads...\"\n\"By the dome and the moonlight as witness, we lift our hymn of devotion unto You...\""
        },
        [6102702] = {
          ContentFR = "Des silhouettes se dressent dans le feu, leurs voix unies en une prière solennelle.",
          DialogueId = 6102702,
          GUID = "0F47088C",
          NextDialogue = 6102703,
          RougeTalkActorType = 3,
          Subtitle = "Figures rise within the fire, their voices joined in solemn prayer."
        },
        [6102703] = {
          ContentFR = "« Qui es-tu ? {性别:Un voyageur égaré|Une voyageuse égarée} ? »\nL’une d’elles se tourne vers toi, un doux sourire aux lèvres, la main tendue.\n« Viens prier avec nous la Déesse de la Pleine Lune. Elle bénira sûrement ton chemin. »",
          DialogueId = 6102703,
          GUID = "0F4708B6",
          NextDialogue = 6102704,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room326_Char01",
          Subtitle = "\"Who are you? A traveller astray?\" \nOne worshipper turns towards you, smiling gently as she reaches out her hand. \n\"Come — join us in prayer to the Goddess of the Full Moon. Surely She will bless the path before you.\""
        },
        [6102704] = {
          ContentFR = "Ils élèvent leur chant vers <H>Fusa</>, Déesse du Destin, la <H>Neuvième des Divinités</>.\nMaîtresse de la pleine lune, elle tire à elle l’argent de sa lumière pour en tresser les fils du destin.",
          DialogueId = 6102704,
          GUID = "0F4708E0",
          NextOptions = {
            [1] = 6102705,
            [2] = 6102709
          },
          RougeTalkActorType = 3,
          Subtitle = "They raise their hymn to Fusa, Goddess of Fate — ninth among the Great Nine.\nShe who reigns over the full moon, and draws down its silvery light to weave the threads of fate."
        },
        [6102705] = {
          ContentFR = "<I>Joindre ta voix à leur prière</>",
          DialogueId = 6102705,
          GUID = "0F47090A",
          IsKeyOption = true,
          NextDialogue = 6102706,
          RougeTalkActorType = 2,
          Subtitle = "Join their prayer."
        },
        [6102706] = {
          ContentFR = "C’était le genre d’assemblée que tu détestais enfant, ces louanges creuses, apprises par cœur et vite oubliées.\nPourtant, une étrange nostalgie t’envahit.\nTu baisses la tête et te joins à leur prière.",
          DialogueId = 6102706,
          GUID = "0F470934",
          NextDialogue = 6102707,
          RougeTalkActorType = 3,
          Subtitle = "This was the kind of gathering you once despised as a child — hollow praises, memorised and soon forgotten. Yet now, a faint nostalgia stirs within you.\nYou bow your head and join them in prayer."
        },
        [6102707] = {
          ContentFR = "« Fusa, Déesse de la Pleine Lune, constante à travers les cieux, au sein des flux et reflux du destin... »\n« À toi, nous rendons hommage. Protège tes fidèles... »\n« Accorde-nous une félicité sans ombre. »",
          DialogueId = 6102707,
          GUID = "0F47095E",
          NextDialogue = 6102708,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = [[
"Fusa, Goddess of the Full Moon, ever constant across the heavens, amidst fate's turning."
"To You we give honour. Bless Your faithful..."
"And grant us flawless fortune and joy."]]
        },
        [6102708] = {
          ContentFR = "Les yeux clos, tu reprends en silence la dévotion des croyants.\nQuand tu les rouvres, leurs silhouettes se sont évanouies.",
          DialogueId = 6102708,
          GUID = "0F470988",
          RougeTalkActorType = 3,
          Subtitle = [[
Eyes closed, you echo the devotion of the faithful.
And when you open them again, the figures are gone.]]
        },
        [6102709] = {
          ContentFR = "<I>Refuser leur prière</>",
          DialogueId = 6102709,
          GUID = "0F4709B2",
          IsKeyOption = true,
          NextDialogue = 6102710,
          RougeTalkActorType = 2,
          Subtitle = "Refuse to join their prayer."
        },
        [6102710] = {
          ContentFR = "« Refuser ? Mais... pourquoi ? »\nSa voix s’éraille, se fait tranchante.\n« Hérétique ! Serais-tu {性别:un|une} adepte du Noctilunisme ? {性别:Un|Une} disciple de Nepha ? »",
          DialogueId = 6102710,
          GUID = "0F4709DC",
          NextDialogue = 6102711,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room326_Char01",
          Subtitle = "\"Refuse? You—why!?\" \nThe worshipper's voice sharpens with disbelief.\n\"Heretic! Are you of the Noclunism? A follower of Nepha!?\""
        },
        [6102711] = {
          ContentFR = "À ce nom interdit, tous les regards se braquent sur toi. Leurs visages se distordent, se muant en masques hideux de haine.\nTu soupires : impossible d’éviter le combat. Il te faut briser le cercle qui t’oppresse.",
          DialogueId = 6102711,
          GUID = "0F470A06",
          RougeTalkActorType = 3,
          Subtitle = "At that forbidden name, all eyes turn. Their faces twist — the warmth gone, replaced by grotesque hatred.\nYou sigh. There's no avoiding it now — you'll have to break free from their encircling ranks."
        },
        [6102801] = {
          ContentFR = "« Ô ciseaux qui tranchent le fil du destin, souveraine du silence éternel... »\n« Par l’Abysse et la longue nuit pour témoins, écoute ma prière... »",
          DialogueId = 6102801,
          GUID = "0F4718CA",
          NextDialogue = 6102802,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char01",
          Subtitle = [[
"Shears of fate's thread, Mistress of eternal stillness..."
"By the Abyss and the long night as witness, hear my humble prayer..."]]
        },
        [6102802] = {
          ContentFR = "À nouveau, des silhouettes surgissent des flammes, récitant en chœur une litanie que tu ne connais pas.",
          DialogueId = 6102802,
          GUID = "0F4718F4",
          NextDialogue = 6102803,
          RougeTalkActorType = 3,
          Subtitle = [[
Figures rise once more within the fire, their voices joined in solemn chant.
You listen in silence. The words are unfamiliar to you.]]
        },
        [6102803] = {
          ContentFR = "« Qui es-tu ? {性别:Un voyageur égaré|Une voyageuse égarée} ? »\nUne fidèle t’aperçoit, elle sourit et te tend la main.\n« Ou bien as-tu, toi aussi, entrevu la vérité cachée, et viens-tu chercher l’étreinte de la véritable salvatrice — Nepha ? »",
          DialogueId = 6102803,
          GUID = "0F47191E",
          NextDialogue = 6102804,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char01",
          Subtitle = "\"Who are you? A traveller astray?\" \nOne worshipper turns towards you, smiling gently as she reaches out her hand. \n\"Or have you too glimpsed the hidden truth — and come seeking the embrace of the true saviour, Nepha?\""
        },
        [6102804] = {
          ContentFR = "<H>Nepha</>... tu te souviens.\nUn nom absent des textes orthodoxes d’Élysium, à peine lisible dans de vieux manuscrits effacés par le temps.\nUn nom interdit : la <H>Dixième Divinité</> oubliée.",
          DialogueId = 6102804,
          GUID = "0F471948",
          NextDialogue = 6102805,
          RougeTalkActorType = 3,
          Subtitle = "Nepha... you remember the name. \nRarely mentioned in the Orthodox texts of Elysium... you have seen it only in dust-laden scrolls, half-effaced by time. A forbidden name — the long forgotten tenth deity."
        },
        [6102805] = {
          ContentFR = "Sœur cadette de Fusa, Déesse de la Pleine Lune et du Destin, Nepha est la Déesse de la Lune Noire et de la Mort.\nL’aînée tisse le fil, la cadette le tranche.\nDe leur lutte sans fin sont nés les cycles de la lune, le flux des marées.\nEt si ces gens la vénèrent, alors ce sont des...",
          DialogueId = 6102805,
          GUID = "0F471972",
          NextOptions = {
            [1] = 6102806
          },
          RougeTalkActorType = 3,
          Subtitle = "She was the Goddess of the Dark Moon and of Death. Sister to Fusa.\nWhile her elder sister weaves the threads of fate, Nepha severs them.\nTheir endless struggle gave rise to the waxing and waning of the moon, and stirred the tides.\nIf these people are Her followers, then they must be—"
        },
        [6102806] = {
          ContentFR = "<I>Demander leur foi</>",
          DialogueId = 6102806,
          GUID = "0F47199C",
          NextDialogue = 6102807,
          RougeTalkActorType = 2,
          Subtitle = "Ask about their faith."
        },
        [6102807] = {
          ContentFR = "« Si tu es ici, tu le sais déjà : l’Abysse n’est pas un gouffre mort. Il vit, il croît, il s’étend sans fin.\nNi l’épée sacrée des chevaliers, ni la lumière de la Pleine Lune ne peuvent retenir sa marée obscure.\nToute lumière court vers son extinction, toute vie vers sa fin. La seule certitude, c’est la disparition. L’Abysse est la vraie forme du monde.\nBienvenue, {性别:cher voyageur|chère voyageuse}, parmi les fidèles du <H>Noctilunisme</>. »",
          DialogueId = 6102807,
          GUID = "0F4719C6",
          NextOptions = {
            [1] = 6102808,
            [2] = 6102811
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char02",
          Subtitle = "\"Since you stand here, you must already know — the Abyss is not a lifeless pit. It is alive. Ever growing. Ever spreading.\"\n\"The golden holy sword of the knights cannot hold back its dark tide. The light of the Full Moon cannot pierce the abysmal quiet.\"\n\"As every light races towards its extinguishing, so too must all living things meet their end. The only certainty... is perishing. The Abyss is the world's true form.\"\n\"Welcome, dear traveller — to the Noclunism.\""
        },
        [6102808] = {
          ContentFR = "<I>Accepter à leur invitation</>",
          DialogueId = 6102808,
          GUID = "0F4719F0",
          IsKeyOption = true,
          NextDialogue = 6102809,
          RougeTalkActorType = 2,
          Subtitle = "Accept their invitation."
        },
        [6102809] = {
          ContentFR = "Même face à de simples spectres, tu n’as nulle envie de provoquer de nouveaux conflits.\nAlors tu prends un air grave et récites quelques bribes des dogmes du Noctilunisme que tu avais vaguement entendues : « L’instinct de mort »... « La rédemption de Nepha »... « L’Abysse est l’éternité »...\nLeurs traits se détendent, ils hochent la tête avec approbation, séduits par tes paroles.",
          DialogueId = 6102809,
          GUID = "0F471A1A",
          NextDialogue = 6102810,
          RougeTalkActorType = 3,
          Subtitle = "Even if they were only phantoms, you wish not to provoke them needlessly.\nSo, with a solemn expression and well-practised tone, you begin to recite the tenets of the Noclunism — fragments once heard and half-remembered: \"The deathward instinct\"... \"Nepha's salvation\"... \"The Abyss is eternity itself\"... \nTheir faces soften. They nod again and again, pleased by your borrowed eloquence."
        },
        [6102810] = {
          ContentFR = "« Ton savoir nous impressionne, ta sagesse nous subjugue. Reçois ces présents, {性别:ami inconnu|amie inconnue} ! »\nTu as su les tromper. Finalement, toutes les sermons de ton enfance ne t’étaient pas inutiles.",
          DialogueId = 6102810,
          GUID = "0F471A44",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char02",
          Subtitle = "\"Your great learning humbles us, your wisdom humbles us. Please — accept these gifts, friend!\" \nYou bluff your way through. Perhaps... not every sermon of your youth is wasted on wandering thoughts."
        },
        [6102811] = {
          ContentFR = "<I>Refuser leur invitation</>",
          DialogueId = 6102811,
          GUID = "0F471A6E",
          IsKeyOption = true,
          NextDialogue = 6102812,
          RougeTalkActorType = 2,
          Subtitle = "Refuse their invitation."
        },
        [6102812] = {
          ContentFR = "Au long de ta route, toi aussi, tu as souvent songé au sens de la vie, au sens de la mort. Parfois, tu as cru que la mort était la seule délivrance.\nMais ces rencontres imprévues ont rallumé en toi la raison de marcher encore dans les ténèbres.\nTu brûleras ton propre corps comme bûche, s’il le faut, pour illuminer ce monde figé. Même l’espace d’un instant, tu brilleras contre l’éternité morte.",
          DialogueId = 6102812,
          GUID = "0F471A98",
          NextDialogue = 6102813,
          RougeTalkActorType = 3,
          Subtitle = "Along this weary road, you too have pondered often —\nthe meaning of life, the meaning of death. At times, you've believed that death might be the only release.\nBut those few chance encounters... They've rekindled your reason to keep walking — through the dark, and through the doubt. Now, your resolve burns like a flame:\nYou will drive back the dark, even if it means burning your own body as kindling. Even if your light endures for only a moment — you will blaze against this stagnant eternity."
        },
        [6102813] = {
          ContentFR = "« L’Abysse n’est pas éternité. Vous n’êtes que des échos, ombres d’êtres disparus. »\nTu lèves ton arme.\n« Retournez là où est votre place, âmes des trépassés— »",
          DialogueId = 6102813,
          GUID = "0F471AC2",
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"The Abyss is not Eternity. You are but echoes — phantoms of lives once lived.\"\nYou raise your weapon. \n\"Back to where you belong, souls of the departed—\""
        },
        [6102901] = {
          ContentFR = "Tu t’assieds près du feu pour te reposer.\nSoudain, un bruit étrange effleure ton oreille... puis s’éloigne, monte au-dessus de ta tête.\nIl enfle, de plus en plus clair : un froissement doux, comme des ailes de velours qui se frôlent.",
          DialogueId = 6102901,
          GUID = "0F472932",
          NextDialogue = 6102902,
          RougeTalkActorType = 3,
          Subtitle = "You settle beside the campfire for a rest.\nSuddenly, a faint sound tickles your ear... then rises, drifting somewhere above.\nIt swells — a soft, feathery rustle, like velvet wings brushing together."
        },
        [6102902] = {
          ContentFR = "« Hé ! {性别:Petit veinard|Petite veinarde} ! »",
          DialogueId = 6102902,
          GUID = "0F47295C",
          NextDialogue = 6102903,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01",
          Subtitle = "\"Hey there! Lucky traveller!\""
        },
        [6102903] = {
          ContentFR = "Une pluie de plumes chatoyantes descend sur toi. Jamais, dans l’Abysse, tu n’as vu autant de couleurs à la fois.\nBientôt, tu te retrouves enseveli sous cet amas bariolé, ridicule pantin d’une farce de rue, oscillant entre le comique et le pathétique.",
          DialogueId = 6102903,
          GUID = "0F472986",
          NextDialogue = 6102904,
          RougeTalkActorType = 3,
          Subtitle = "A flurry of vibrant feathers rains down from above — more colours than you've ever seen in the Abyssum.\nYou find yourself knee-deep in absurd fluff, like the butt of a street prank caught between comedy and pity."
        },
        [6102904] = {
          ContentFR = "« Quoi, pas de réaction ? Tu traînes ici depuis si longtemps... tu ne t’ennuies pas ? »\nUn homme avec un masque grotesque d’oiseau apparaît, suspendu la tête en bas.\nIl descend lentement jusqu’à ce que ses yeux soient au même niveau que les tiens.\nComment il tient cette posture, tu n’en sais rien. Mais ce qui compte, c’est que le bec de son masque vacille dangereusement, prêt à heurter ton visage.",
          DialogueId = 6102904,
          GUID = "0F4729B0",
          NextOptions = {
            [1] = 6102905
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01",
          Subtitle = [[
"Hello? Aren't you going to react? How long have you been down here? Isn't it dull yet?"
A figure descends upside-down, eyes level with yours. He wears a comical bird mask, the beak swaying dangerously close to your nose.
How he's holding that pose, you can't begin to guess.]]
        },
        [6102905] = {
          ContentFR = "<I>« Je n’ai pas le temps de jouer. »</>",
          DialogueId = 6102905,
          GUID = "0F4729DA",
          NextDialogue = 6102906,
          RougeTalkActorType = 2,
          Subtitle = "I don't have time for this."
        },
        [6102906] = {
          ContentFR = "« Allons, ne sois pas si {性别:froid|froide}. Les vieux de l’Église Élyséenne ne t’ont-ils pas appris ? Une bonne action chaque jour attire la chance !\nAllez, <H>joue avec moi</>. Si tu gagnes, je t’offre une récompense, si tu perds... rien du tout. Pas de punition. Alors ? »",
          DialogueId = 6102906,
          GUID = "0F472A04",
          NextOptions = {
            [1] = 6102907
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01",
          Subtitle = [[
"Aw, don't be so frosty. Didn't those Elysian fogeys ever tell you? A good deed a day keeps bad luck away!"
"Come on, play a little game with me. Win, and I'll give you a prize. Lose? No punishment. Nothing's at stake here. What do you say?"]]
        },
        [6102907] = {
          ContentFR = "<I>« D’accord. »</>",
          DialogueId = 6102907,
          GUID = "0F472A2E",
          IsKeyOption = true,
          RougeTalkActorType = 2,
          Subtitle = "Alright then."
        },
        [6103001] = {
          ContentFR = "« Ô, chantons un hymne à <H>Shaliel</> !\n« Il est le Saint d’Élysium. »\n« Il reçut les révélations de Fusa, enseigna aux hommes miséricorde, pardon et amour,\net fit refleurir, sur la terre cramoisie d’Élysium, les jeunes rameaux de la paix. »",
          DialogueId = 6103001,
          GUID = "0F47399A",
          NextDialogue = 6103002,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01",
          Subtitle = [[
"O let us raise a hymn to Shaliel!" 
"He, the hallowed Saint of Elysium..."
"Who hearkened to Fusa's revelation, and taught mankind mercy, forgiveness, and love."
"Upon the crimson soil of Elysium, peace once more put forth its tender shoots."]]
        },
        [6103002] = {
          ContentFR = "Un vieil homme, vêtu en ménestrel, caresse du bout des doigts une paroi brisée.\nMalgré ses fissures, le mur demeure intact : à la lueur de ta lanterne, une fresque se révèle, immense — l’image même de <H>Shaliel</> que le poète exalte.\nSaint de deux millénaires passés, premier siège des <H>Sept Vertus</>, celui de la Tempérance.\nLe poète chante sans fin, ignorant ta présence.",
          DialogueId = 6103002,
          GUID = "0F4739C4",
          NextOptions = {
            [1] = 6103003
          },
          RougeTalkActorType = 3,
          Subtitle = "An old man stands near the broken wall, garbed in a bard's robe. One hand brushes its weathered surface as he sings.\nThough fractured, the wall is well preserved. And in the Lantern's faint glow, a mural emerges — a towering image of the very Shaliel the bard exalts.\nShaliel — saint of two millennia past, one of the first Seven Virtues: Temperance.\nThe bard sings on, unaware of your presence."
        },
        [6103003] = {
          ContentFR = "<I>Continuer d’écouter</>",
          DialogueId = 6103003,
          GUID = "0F4739EE",
          NextDialogue = 6103004,
          RougeTalkActorType = 2,
          Subtitle = "Keep listening."
        },
        [6103004] = {
          ContentFR = "« Mais le cœur du Saint demeurait blessé, par la promesse que Fusa fit aux mortels — le Paradis des Paradis. »\n« Et lorsqu’un jour, au bord des flots d’azur, il demeura soixante-dix-sept jours en silence, sous la pleine lune il contempla la vérité, et dans les eaux sacrées, il toucha l’Éternité. »",
          DialogueId = 6103004,
          GUID = "0F473A18",
          NextDialogue = 6103005,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01",
          Subtitle = "\"Yet the Saint's heart was ever troubled:\"\n\"by Fusa's promise to mankind — the Heaven above Heavens.\"\n\"At last, after seventy-seven days of stillness beside the azure lake,\"\n\"beneath the full moon, he beheld the truth... and in its waters, he touched Eternity.\""
        },
        [6103005] = {
          ContentFR = "Tu comprends son chant.\nAu bord du lac, Shaliel reçut la révélation de Fusa, Déesse du Destin. Son âme quitta ce monde pour le Paradis des Paradis, atteignant l’Éternité. Ainsi devint-il le premier Élu.\nD’autres ensuite portèrent la marque divine, le stigmate des dieux. Un à un, ils traversèrent le Lac Sacré et gagnèrent la terre promise.\nCes récits des premiers temps de l’Église d’Élysium, tu les connais bien.",
          DialogueId = 6103005,
          GUID = "0F473A42",
          NextOptions = {
            [1] = 6103006
          },
          RougeTalkActorType = 3,
          Subtitle = "You understand the song.\nAt the lake's edge, Shaliel received revelation from Fusa — Goddess of Fate. His soul departed then for the Heaven above Heavens, attaining what the faithful called Eternity. Thus was he the first of the Chosen.\nAnd in the years that followed, others too bore the divine brands. One by one, they crossed the holy lake, and reached the promised land.\nSuch were the early tales of the Elysian Church. You remember them well."
        },
        [6103006] = {
          ContentFR = "<I>Continuer d’écouter</>",
          DialogueId = 6103006,
          GUID = "0F473A6C",
          NextDialogue = 6103007,
          RougeTalkActorType = 2,
          Subtitle = "Keep listening."
        },
        [6103007] = {
          ContentFR = "« Et pourtant, deux mille ans plus tard, quand je contemple, des collines, le Lac Sacré,\npourquoi n’y reste-t-il qu’un gouffre noir et tourbillonnant ? »\n« Ô Shaliel, Saint de la Sagesse, dis-moi : où donc se trouve le paradis qu’avait promis la Déesse ? »",
          DialogueId = 6103007,
          GUID = "0F473A96",
          NextDialogue = 6103008,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01",
          Subtitle = "\"Yet two thousand years hence, when I gaze from the hills upon the holy lake...\"\n\"Why is there naught but a black whirlpool?\"\n\"O Shaliel, our Saint of Wisdom...\"\n\"Tell me — where lies the paradise the Goddess once promised?\""
        },
        [6103008] = {
          ContentFR = "Le poète pleure en chantant.\nSon récit glisse de la gloire passée à l’abîme présent.\nNul ne sait quand cela commença — une nuit, sans prévenir, le Lac Sacré, jadis le plus pur sanctuaire des fidèles d’Élysium, fut englouti par l’Abysse.\nComme l’avaient clamé les apostats mille ans plus tôt : « Les Neuf Dieux sont morts ! »\nContinuer d’écouter ?",
          DialogueId = 6103008,
          GUID = "0F473AC0",
          NextOptions = {
            [1] = 6103009,
            [2] = 6103013
          },
          RougeTalkActorType = 3,
          Subtitle = "The bard sings, and tears fall. The theme of his song has shifted from distant glory to the vile gloom before your eyes.\nNo one knows exactly when it began. But one night, without warning, the Sacred Lake — purest and holiest to the Elysian faithful for two thousand years — was devoured by the Abyss.\nAnd just as the apostates once said a thousand years ago: \"The Great Nine are dead!\" \nWill you keep listening?"
        },
        [6103009] = {
          ContentFR = "<I>Continuer d’écouter</>",
          DialogueId = 6103009,
          GUID = "0F473AEA",
          IsKeyOption = true,
          NextDialogue = 6103010,
          RougeTalkActorType = 2,
          Subtitle = "Keep listening."
        },
        [6103010] = {
          ContentFR = "« Pourquoi l’Abysse immonde demeure-t-elle muette ? »\n« Pourquoi, sous l’argent pur de la pleine lune, la Déesse se tait ? »\n« Ô Shaliel... est-il vrai, comme le murmurent les disciples du Noctilunisme,\nque jamais tu n’atteignis le Paradis des Paradis — mais que tu tournas le dos à la lune,\npour devenir un démon ? »",
          DialogueId = 6103010,
          GUID = "0F473B14",
          NextDialogue = 6103011,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01",
          Subtitle = "\"Why does the foul Abyss give no word?\"\n\"The silver gleam of the full moon falls upon me — yet the Goddess does not answer.\"\n\"O Shaliel, is it true, as the followers of the Noclunism whisper:\"\n\"You never reached the Heaven above Heavens — but turned your back upon the moon... and became a devil?\""
        },
        [6103011] = {
          ContentFR = "« Attends... qu’as-tu dit ? »\nSes mots t’assaillent.\nC’est la plus terrible rumeur des hérétiques : le lac n’aurait jamais été sacré, et Shaliel, premier des Élus, n’aurait pas été sauvé... mais sacrifié.\nTu te rappelles que <H>quelqu’un</> t’avait déjà soufflé cette même suspicion.",
          DialogueId = 6103011,
          GUID = "0F473B3E",
          NextDialogue = 6103012,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"Hold on — what are you saying?\" \nThe bard's words strike you unawares. It is the heretics' most dangerous rumour — that the lake was never sacred, that Shaliel, first among the Chosen, was not saved... but sacrificed.\nYou remember now — someone once whispered this to you."
        },
        [6103012] = {
          ContentFR = "Mais le poète poursuit, effleurant son luth comme si tu n’existais pas.\nSa voix s’éloigne, s’éteint... et lui disparaît.",
          DialogueId = 6103012,
          GUID = "0F473B68",
          RougeTalkActorType = 3,
          Subtitle = [[
But the bard only strums his lyre, his voice fading into yet another verse. As if you were never there at all.
His voice recedes, until even his figure is gone.]]
        },
        [6103013] = {
          ContentFR = "<I>Quitter cet endroit</>",
          DialogueId = 6103013,
          GUID = "0F473B92",
          IsKeyOption = true,
          NextDialogue = 6103014,
          RougeTalkActorType = 2,
          Subtitle = "Leave this place."
        },
        [6103014] = {
          ContentFR = "Tu l’appelles à plusieurs reprises pour attirer son attention. Tu voudrais lui parler, mais il poursuit son antique hymne, comme si tu n’existais pas. Tu comprends qu’il n’y a rien d’utile à tirer de lui, tu te détournes et t’éloignes.",
          DialogueId = 6103014,
          GUID = "0F473BBC",
          RougeTalkActorType = 3,
          Subtitle = [[
You call out a few times, hoping to draw the bard's attention. You wish to speak with him. But he sings on, lost in his ancient hymn.
No words of worth will come from him now. At last, you turn away.]]
        },
        [6200101] = {
          ContentFR = "Le brouhaha de jeunes voix résonne au loin, un son que tu n’avais pas entendu depuis bien longtemps dans l’Abysse.\nDes voix ardentes, vibrantes, encore indemnes de la noirceur rampante.\nTu en es sûr : ce ne sont ni des spectres, ni des illusions, mais bien des humains de chair et d’os.\nÀ les entendre, ils n’ont pas dû mettre les pieds ici depuis bien longtemps.",
          DialogueId = 6200101,
          GUID = "0F857412",
          NextDialogue = 6200102,
          RougeTalkActorType = 3,
          Subtitle = "Youthful chatter carries through the gloom — a sound you haven't heard in the abyss for ages. Vibrant. Alive. Untainted by the creeping darkness.\nYou know with absolute certainty these aren't souls or illusions, but living, breathing humans. The tone of their conversation suggests they've only just arrived."
        },
        [6200102] = {
          ContentFR = "Tu suis le son malgré toi. Peu à peu, la brume se déchire, et tu aperçois quatre jeunes chevaliers.\nChacun porte armes et atours différents, mais tous arborent l’iris sacré d’Élysium sur leur poitrine.",
          DialogueId = 6200102,
          GUID = "0F85743C",
          NextDialogue = 6200103,
          RougeTalkActorType = 3,
          Subtitle = "You can't resist following the sound. You push forward as the mist begins to part — revealing four young Knights standing before you.\nTheir attire and gear vary, yet each bears the fleur-de-lis emblem of Elysium."
        },
        [6200103] = {
          ContentFR = "« Capitaine, on est bien dans la bonne direction ? »\nLa jeune chevalière blonde grimpe trois marches d’un vieil escalier, bondit d’un élan, et redescend aussitôt.\n« Ça ne ressemble qu’à des ruines... »",
          DialogueId = 6200103,
          GUID = "0F857466",
          NextDialogue = 6200104,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01",
          Subtitle = [[
"Are you sure this is the right way, Captain?"
The blonde Knight bounds up the ancient staircase and leaps back down in one fluid motion.
"It's just another pile of rubble."]]
        },
        [6200104] = {
          ContentFR = "« Une chose est sûre : on n’est encore jamais venus ici. »\nLe jeune capitaine avance d’un pas posé, dépassant Cathy.\n« Dans le Lac Sacré, on perd vite tout repère. Il ne reste qu’à avancer pas à pas. »",
          DialogueId = 6200104,
          GUID = "0F857490",
          NextDialogue = 6200105,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02",
          Subtitle = [[
"At least I know we haven't been here before."
The young captain strides past her with measured steps.
"Navigating the Sacred Lake is impossible. We'll just have to take it step by step."]]
        },
        [6200105] = {
          ContentFR = "« Et toi, Cathy, tu ne te fatigues pas à sautiller comme ça ? »\nIl laisse échapper un soupir résigné en voyant son amie virevolter.\n« Ménage tes forces. Ce lieu est dangereux, inutile de gaspiller ton énergie hors du combat. »",
          DialogueId = 6200105,
          GUID = "0F8574BA",
          NextDialogue = 6200106,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02",
          Subtitle = [[
"And, don't you ever get tired bouncing around like that, Cathy?"
The young captain sighs as he watches his hyperactive teammate.
"Save your energy. This place is dangerous. Let's not take unnecessary risks."]]
        },
        [6200106] = {
          ContentFR = "« Fatiguée ? Pas du tout ! Je n’ai pas ton épée et ton bouclier énormes à traîner. »\nElle fait tourner son pistolet sur son doigt avec aisance.\n« D’ailleurs... pourquoi ça s’appelle \"Lac Sacré\" ? Entre ces Souillés et ces illusions, je ne vois rien de bien sacré. »",
          DialogueId = 6200106,
          GUID = "0F8574E4",
          NextDialogue = 6200107,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01",
          Subtitle = [[
"I have lots of energy to spare! You're the one who's lugging around that massive sword and shield."
With a flick of her wrist, she spins the gun deftly on her index finger. 
"So why call this Sacred Lake? These Filthoids and Phantasms don't really scream holy."]]
        },
        [6200107] = {
          ContentFR = "« Cathy, modère tes paroles. »\nLe prêtre Charon, tenant son bâton, prend un air grave.\n« Le Lac Sacré est un lieu béni, choisi par les dieux pour les élus. Même corrompu par les ténèbres, il demeure un sanctuaire que nous, enfants d’Élysium, devons respecter. »",
          DialogueId = 6200107,
          GUID = "0F85750E",
          NextDialogue = 6200108,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char03",
          Subtitle = [[
"Watch your words, Cathy."
The male Caron Priest grips his staff firmly.
"The Sacred Lake remains hallowed ground where the chosen receive divine grace. Though darkness now taints it, we of Elysium must still keep reverence in our hearts."]]
        },
        [6200108] = {
          ContentFR = "La quatrième, une sorcière drapée d’un manteau sombre, un long arc dans le dos, ricane doucement, d’un ton moqueur. Son capuchon noir dissimule son visage, rendant toute expression invisible.",
          DialogueId = 6200108,
          GUID = "0F857538",
          NextDialogue = 6200109,
          RougeTalkActorType = 3,
          Subtitle = "The fourth member — a cloaked female Sorceress with a longbow strapped to her back — gives a dismissive chuckle at his words. Her black hood shadows her face, hiding any expression."
        },
        [6200109] = {
          ContentFR = "Flynn s’apprête à intervenir pour apaiser la tension, mais ses mots se meurent.\nC’est alors qu’il te remarque.",
          DialogueId = 6200109,
          GUID = "0F857562",
          NextDialogue = 6200110,
          RougeTalkActorType = 3,
          Subtitle = "The young captain opens his mouth to defuse the tension, but no words come. Just as he struggles for a solution, his gaze lands on you."
        },
        [6200110] = {
          ContentFR = "« Vous n’avez pas l’air de faire partie de l’Ordre. Seriez-vous {性别:un voyageur égaré|une voyageuse égarée} en ces lieux ? »",
          DialogueId = 6200110,
          GUID = "0F85758C",
          NextOptions = {
            [1] = 6200111
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02",
          Subtitle = "\"No knightly crest marks you. Did you wander here by chance?\""
        },
        [6200111] = {
          ContentFR = "Je suis {性别:un voyageur|une voyageuse}.",
          DialogueId = 6200111,
          GUID = "0F8575B6",
          NextDialogue = 6200112,
          RougeTalkActorType = 2,
          Subtitle = "I am a traveler."
        },
        [6200112] = {
          ContentFR = "« {性别:Un voyageur|Une voyageuse}... ? » L’étonnement traverse son visage, vite remplacé par une douceur prévenante.\n« Alors sans doute ignorez-vous que ce lieu, la terre sainte d’Élysium, est aujourd’hui trop dangereux pour s’y aventurer. »",
          DialogueId = 6200112,
          GUID = "0F8575E0",
          NextDialogue = 6200113,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02",
          Subtitle = "\"A traveler…?\" Confusion flickers across the young man's face before giving way to patient concern. \"Then you may not know. This is Elysium's sacred ground. Dangerous circumstances now make it unfit for visitors.\""
        },
        [6200113] = {
          ContentFR = "« Je me présente : Flynn, chevalier de l’Ordre des Plumes-Célestes, sous l’Église Élyséenne. »\nIl désigne ses compagnons.\n« Nous pourrions vous raccompagner si vous le souhaitez. »",
          DialogueId = 6200113,
          GUID = "0F85760A",
          NextOptions = {
            [1] = 6200114
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02",
          Subtitle = "\"I'm Flynn, a Knight of the Wingfeather Order under The Elysian Church.\" He gestures to his team. \"We'd be honored to escort you to safety if you'll permit us.\""
        },
        [6200114] = {
          ContentFR = "Inutile. J’ai encore quelque chose à accomplir ici.",
          DialogueId = 6200114,
          GUID = "0F857634",
          NextDialogue = 6200115,
          RougeTalkActorType = 2,
          Subtitle = "That won't be necessary. I still have unfinished business here."
        },
        [6200115] = {
          ContentFR = "« Alors je dois vous prévenir : cette terre sainte est aussi un lieu interdit. Notre devoir nous commande d’en chasser les intrus. »",
          DialogueId = 6200115,
          GUID = "0F85765E",
          NextDialogue = 6200116,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char03",
          Subtitle = "\"I must warn you. This is hallowed ground — and forbidden territory. Our knightly oath compels us to remove trespassers.\""
        },
        [6200116] = {
          ContentFR = "La sorcière en capuchon éclate d’un rire amer.\n« Chasser ? Et comment, je te prie ? Même nous, nous ne savons pas comment en sortir. »\nSes mots tombent, glacials, comme des flocons qui fouettent le visage.",
          DialogueId = 6200116,
          GUID = "0F857688",
          NextDialogue = 6200117,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char04",
          Subtitle = "\"…How exactly are we supposed to do that?\" The cloaked Sorceress lets out a sneer. \"Last I checked, even we're trapped in this place.\"\nHer words cut like winter's first frost against bare skin."
        },
        [6200117] = {
          ContentFR = "« Allez, allez. » La jeune chevalière blonde s’interpose pour calmer le jeu.\n« Ce {性别:voyageur n’est pas un blasphémateur|voyageuse n’est pas une blasphématrice}, et {性别:il|elle} se débrouille visiblement très bien. Autant faire comme si on n’avait rien vu. »",
          DialogueId = 6200117,
          GUID = "0F8576B2",
          NextDialogue = 6200118,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01",
          Subtitle = "\"Alright, alright.\" The blonde Knight interjects in mediation. \"Our 'traveler' here seems capable enough, and certainly no blasphemer. No harm in going our separate ways and pretending we never crossed paths, yes?\""
        },
        [6200118] = {
          ContentFR = "Puis, avec une étincelle dans les yeux, elle se penche vers toi :\n« D’ailleurs, {性别:voyageur|voyageuse}, auriez-vous aperçu une épéiste de treize ou quatorze ans, aux cheveux roses et portant une immense épée dans le dos ? »",
          DialogueId = 6200118,
          GUID = "0F8576DC",
          NextOptions = {
            [1] = 6200119
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01",
          Subtitle = "\"Say, traveler.\" She nudges Flynn aside, leaning into you. \"You wouldn't happen to have seen a girl around here? Thirteen, maybe fourteen — pink hair, wielding a giant sword?\""
        },
        [6200119] = {
          ContentFR = "... Non.",
          DialogueId = 6200119,
          GUID = "0F857706",
          NextDialogue = 6200120,
          RougeTalkActorType = 2,
          Subtitle = "…No, I haven't."
        },
        [6200120] = {
          ContentFR = "« Je vois... Alors, si vous la croisez, dites-lui que l’escouade du <H>Crépuscule Silencieux</> la recherche. Vous nous rendriez un grand service ! »",
          DialogueId = 6200120,
          GUID = "0F857730",
          NextOptions = {
            [1] = 6200121
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01",
          Subtitle = "\"I see… If you do meet her, please tell her — Squad Hushed Dusk is looking for her. We'd be so grateful!\""
        },
        [6200121] = {
          ContentFR = "Pourquoi la cherchez-vous ?",
          DialogueId = 6200121,
          GUID = "0F85775A",
          NextDialogue = 6200122,
          RougeTalkActorType = 2,
          Subtitle = "Why do you seek her?"
        },
        [6200122] = {
          ContentFR = "« Eh bien... c’est, disons, notre commandante. Mais chut, je n’en dirai pas plus, ou Milton me fera la morale. »",
          DialogueId = 6200122,
          GUID = "0F857784",
          NextDialogue = 6200123,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01",
          Subtitle = "\"This is awkward to admit, but she's technically our… commanding officer. Though I shouldn't elaborate — Milton will have my head if I say more.\""
        },
        [6200123] = {
          ContentFR = "« Ça suffit, Cathy. » Le prêtre fronce les sourcils.\n« Finissons notre mission. »",
          DialogueId = 6200123,
          GUID = "0F8577AE",
          NextDialogue = 6200124,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char03",
          Subtitle = "\"Then hold your tongue.\" The Priest's brow darkens. \"No more distractions. On with our mission.\""
        },
        [6200124] = {
          ContentFR = "« Êtes-vous sûr de ne pas vouloir de notre aide ? Ce lieu est dangereux, peut-être pourriez-vous marcher avec nous... »",
          DialogueId = 6200124,
          GUID = "0F8577D8",
          NextOptions = {
            [1] = 6200125
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02",
          Subtitle = "\"Are you certain you don't need our help?\" The young man's gaze lingers with concern. \"This is a very dangerous place — at least travel with us.\""
        },
        [6200125] = {
          ContentFR = "Non, je préfère avancer {性别:seul|seule}.",
          DialogueId = 6200125,
          GUID = "0F857802",
          NextDialogue = 6200126,
          RougeTalkActorType = 2,
          Subtitle = "No, I'm fine on my own."
        },
        [6200126] = {
          ContentFR = "« Bien. Puisque telle est votre volonté... »",
          DialogueId = 6200126,
          GUID = "0F85782C",
          NextOptions = {
            [1] = 6200127
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02",
          Subtitle = "\"Very well. If your resolve is set…\""
        },
        [6200127] = {
          ContentFR = "Et dans un endroit pareil, vous n’avez pas peur ?",
          DialogueId = 6200127,
          GUID = "0F857856",
          IsKeyOption = true,
          NextDialogue = 6200128,
          RougeTalkActorType = 2,
          Subtitle = "Aren't you afraid, if it's so dangerous here?"
        },
        [6200128] = {
          ContentFR = "Il esquisse un sourire sûr de lui.\n« La foi écarte la peur. Jusqu’à notre prochaine rencontre, {性别:voyageur|voyageuse}, que le Dieu de la Pleine Lune veille sur votre route. »",
          DialogueId = 6200128,
          GUID = "0F857880",
          NextDialogue = 6200129,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02",
          Subtitle = "\"Faith shields the devout from fear.\" The young man flashes a steadfast smile. \"Till our paths cross again. May the God of Full Moon bless your journey.\""
        },
        [6200129] = {
          ContentFR = "Les chevaliers s’éloignent ensemble, te laissant {性别:seul|seule} face à la brume infinie.",
          DialogueId = 6200129,
          GUID = "0F8578AA",
          RougeTalkActorType = 3,
          Subtitle = "The Knights depart together, leaving only endless mist before you."
        },
        [6200201] = {
          ContentFR = "La chevalière blonde surgit des ténèbres, sa chevelure d’or traçant dans l’ombre un sillage lumineux.\nMais elle n’est plus tout à fait la même : son vêtement est déchiré, taché d’un rouge sombre.",
          DialogueId = 6200201,
          GUID = "0F85847A",
          NextDialogue = 6200202,
          RougeTalkActorType = 3,
          Subtitle = "The young Knight emerges from the shadows, her golden hair cutting through the gloom like liquid light.\nShe is different from the last time you met — tattered edges and dark stains upon her clothes whisper stories of their own tales."
        },
        [6200202] = {
          ContentFR = "« Ah, {性别:voyageur|voyageuse}... nos chemins se croisent à nouveau ! »\nElle agite la main, fatiguée mais joyeuse.",
          DialogueId = 6200202,
          GUID = "0F8584A4",
          NextOptions = {
            [1] = 6200203
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01",
          Subtitle = "\"Ah, my wandering friend returns!\" Fatigue tugs at her stance, yet her arm swings wide in eager greeting."
        },
        [6200203] = {
          ContentFR = "Et vos compagnons ?",
          DialogueId = 6200203,
          GUID = "0F8584CE",
          NextDialogue = 6200204,
          RougeTalkActorType = 2,
          Subtitle = "Where are your friends?"
        },
        [6200204] = {
          ContentFR = "« Eh bien... des Souillés, des spectres — enfin, ces ombres, nous sont tombés dessus. »",
          DialogueId = 6200204,
          GUID = "0F8584F8",
          NextDialogue = 6200205,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01",
          Subtitle = "\"Well… We just ran into quite a few Filthoids, and ghosts — I mean those shadows lurking in the dark…\""
        },
        [6200205] = {
          ContentFR = "« Je les ai combattus, mais quand tout s’est dissipé... ils avaient disparu. Vous ne les auriez pas vus ? »",
          DialogueId = 6200205,
          GUID = "0F858522",
          NextOptions = {
            [1] = 6200206
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01",
          Subtitle = "\"I fought them off with everything I had. But when the dust settles, everyone's gone. Have you seen them?\""
        },
        [6200206] = {
          ContentFR = "Non.",
          DialogueId = 6200206,
          GUID = "0F85854C",
          NextDialogue = 6200207,
          RougeTalkActorType = 2,
          Subtitle = "No."
        },
        [6200207] = {
          ContentFR = "Son regard se baisse, tel un voile qui recouvre le soleil.",
          DialogueId = 6200207,
          GUID = "0F858576",
          NextDialogue = 6200208,
          RougeTalkActorType = 3,
          Subtitle = "Her eyes lower like a veil drawn across dawn."
        },
        [6200208] = {
          ContentFR = "« Flynn me répète toujours de rester en formation... Si seulement je l’avais écouté, au lieu de foncer tête baissée... »",
          DialogueId = 6200208,
          GUID = "0F8585A0",
          NextDialogue = 6200209,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01",
          Subtitle = "\"Flynn keeps lecturing me about formations and watching each other's backs… Ah, if only I'd listened instead of charging ahead.\""
        },
        [6200209] = {
          ContentFR = "« Je n’aurais jamais imaginé que le Lac Sacré soit un endroit pareil... D’ordinaire, même si je me perds, je finis toujours par retrouver les autres. Mais ici... Les lieux changent dès qu’on détourne les yeux. Ce chemin, je viens pourtant de l’emprunter, et il est déjà devenu méconnaissable. C’est comme si... »\nSes poings se serrent.\n« Comme si ces ombres les avaient emportés... effaçant jusqu’à la moindre trace de leur passage. »",
          DialogueId = 6200209,
          GUID = "0F8585CA",
          NextOptions = {
            [1] = 6200210
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01",
          Subtitle = "\"I had no idea the Sacred Lake would be like this. Back home, even if I wander off, I always find my way back. But here… paths rewrite themselves the moment you turn away. It's almost like…\"\nHer fists clench.\n\"It's like the shadows snatched them away… erasing every trace they ever left behind.\""
        },
        [6200210] = {
          ContentFR = "« Ne vous inquiétez pas. Vous finirez par les retrouver... Comme vous m’avez trouvé. »",
          DialogueId = 6200210,
          GUID = "0F8585F4",
          NextDialogue = 6200211,
          RougeTalkActorType = 2,
          Subtitle = "Don't worry. You'll find each other. You found me, right?"
        },
        [6200211] = {
          ContentFR = "Elle cligne des yeux, un peu surprise.",
          DialogueId = 6200211,
          GUID = "0F85861E",
          NextDialogue = 6200212,
          RougeTalkActorType = 3,
          Subtitle = "Cathy blinks in surprise and stares at you for a moment."
        },
        [6200212] = {
          ContentFR = "« Nous nous serions déjà rencontrés ? »\nSes yeux brillants reflètent ton visage, un reflet qui t’apparaît étrangement étranger.",
          DialogueId = 6200212,
          GUID = "0F858648",
          NextDialogue = 6200213,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01",
          Subtitle = "\"Have we met before?\"\nHer bright eyes mirror your face — a reflection that feels unsettlingly unfamiliar."
        },
        [6200213] = {
          ContentFR = "« J’ai l’impression de vous avoir croisé bien avant notre rencontre au Lac Sacré... »",
          DialogueId = 6200213,
          GUID = "0F858672",
          NextOptions = {
            [1] = 6200214
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01",
          Subtitle = "\"There's something familiar about you… Not from our last meeting, but further back — before we ever set foot in the Sacred Lake.\""
        },
        [6200214] = {
          ContentFR = "Juste une impression.",
          DialogueId = 6200214,
          GUID = "0F85869C",
          NextDialogue = 6200215,
          RougeTalkActorType = 2,
          Subtitle = "Just your mind playing tricks on you."
        },
        [6200215] = {
          ContentFR = "« Oui, sans doute. »\nUn sourire discret, comme un rayon qui perce les nuages.",
          DialogueId = 6200215,
          GUID = "0F8586C6",
          NextDialogue = 6200216,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01",
          Subtitle = [[
"You're probably right."
A faint smile tugs at her lips like sunlight struggling through storm clouds.]]
        },
        [6200216] = {
          ContentFR = "« Après m’être perdue, j’ai marché seule si longtemps… Vous rencontrer m’a prouvé que je n’étais pas condamnée à errer seule dans cet enfer. »",
          DialogueId = 6200216,
          GUID = "0F8586F0",
          NextDialogue = 6200217,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01",
          Subtitle = "\"After losing them, I wandered alone for ages. Meeting you now it's the first proof that I'm not damned to walk this hellscape for eternity.\""
        },
        [6200217] = {
          ContentFR = "« Peut-être que ce n’est qu’un désir... le souffle d’une autre <H>vie vivante</>. »",
          DialogueId = 6200217,
          GUID = "0F85871A",
          NextOptions = {
            [1] = 6200218
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01",
          Subtitle = "\"Perhaps I've just missed the warmth of another living soul.\""
        },
        [6200218] = {
          ContentFR = "J’espère que vous retrouverez vite vos compagnons.",
          DialogueId = 6200218,
          GUID = "0F858744",
          IsKeyOption = true,
          NextDialogue = 6200219,
          RougeTalkActorType = 2,
          Subtitle = "I hope you'll find your friends soon."
        },
        [6200219] = {
          ContentFR = "« Merci. Ne vous inquiétez pas, ce sont des chevaliers d’exception. Même sans moi, ils s’en sortiront. C’est à moi de les retrouver... »",
          DialogueId = 6200219,
          GUID = "0F85876E",
          NextDialogue = 6200220,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01",
          Subtitle = "\"Thanks! But don't worry — they're elite Knights. They'll survive without me. I'm the one who needs to reach them…\""
        },
        [6200220] = {
          ContentFR = "Elle t’adresse un dernier sourire :\n« Adieu, {性别:voyageur|voyageuse}. Que vous puissiez, vous aussi, accomplir ce qui vous attend. »",
          DialogueId = 6200220,
          GUID = "0F858798",
          NextDialogue = 6200221,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01",
          Subtitle = "\"Farewell, traveler. May your path lead you to what you seek.\""
        }
      }
    end
  },
  {
    MinKey = 6200221,
    MaxKey = 6201601,
    Loader = function()
      return {
        [6200221] = {
          ContentFR = "Cathy agite la main et s’éloigne. Autour de toi, la nuit reprend ses droits, comme si l’aube n’avait jamais existé.",
          DialogueId = 6200221,
          GUID = "0F8587C2",
          RougeTalkActorType = 3,
          Subtitle = [[
Kaysie waves farewell and disappears.
The light fades with her, plunging everything back into the endless night.]]
        },
        [6200301] = {
          ContentFR = "Encore des ruines, des murs effondrés, des tours brisées.\nUn spectacle mille fois répété dans l’Abysse.",
          DialogueId = 6200301,
          GUID = "0F8594E2",
          NextDialogue = 6200302,
          RougeTalkActorType = 3,
          Subtitle = "Another wasteland of rubble.\nThis is nothing new — you've walked these ruins a thousand times before in the abyss."
        },
        [6200302] = {
          ContentFR = "Mais ce ne sont pas que des pierres : des armes abandonnées, des corps à demi enfouis, l’odeur âcre du sang et de la cendre.\nTu as trop souvent croisé semblable vision, d’autres âmes offertes au \"Lac Sacré\", de gré ou de force.",
          DialogueId = 6200302,
          GUID = "0F85950C",
          NextDialogue = 6200303,
          RougeTalkActorType = 3,
          Subtitle = [[
Not just broken walls and collapsed towers, but abandoned weapons, half-buried bodies barely visible beneath the wreckage. The air reeks of blood and ashes.
You've seen this too often. More offerings to the so-called "Sacred Lake", whether they came willingly or not.]]
        },
        [6200303] = {
          ContentFR = "Un éclat attire ton regard : un insigne maculé de sang, l’iris sacré d’Élysium. Tu l’as vu récemment, bien trop récemment.",
          DialogueId = 6200303,
          GUID = "0F859536",
          NextDialogue = 6200304,
          RougeTalkActorType = 3,
          Subtitle = "Suddenly a bloodied emblem catches your eye — the fleur-de-lis, unmistakable. You've seen this emblem not so long ago."
        },
        [6200304] = {
          ContentFR = "Tu dégages les pierres éparses. Là, une épée rougie s’élève encore, fichée droit dans le sol, comme si la main qui la serrait avait refusé de céder, même dans l’agonie.",
          DialogueId = 6200304,
          GUID = "0F859560",
          NextDialogue = 6200305,
          RougeTalkActorType = 3,
          Subtitle = "You push aside the rubble and find a bloodstained sword. It's still standing upright — like its owner refused to fall even in death."
        },
        [6200305] = {
          ContentFR = "Autour, les restes parlent d’eux-mêmes : un bâton brisé, des flèches dispersées, un pistolet tordu.\nAlors tu comprends : tu connais ces âmes.",
          DialogueId = 6200305,
          GUID = "0F85958A",
          NextDialogue = 6200306,
          RougeTalkActorType = 3,
          Subtitle = "Then you see them — shattered staffs, broken arrows, ruined pistols.\nNow you know the names behind these fallen souls."
        },
        [6200306] = {
          ContentFR = "« La foi écarte la peur », répétaient-ils... Mais, au dernier souffle, leur croyance les a-t-elle vraiment délivrés de la douleur ?\nTu ne le sauras jamais. Tu n’as pas besoin de le savoir.",
          DialogueId = 6200306,
          GUID = "0F8595B4",
          NextDialogue = 6200307,
          RougeTalkActorType = 3,
          Subtitle = [[
"Faith shields the devout from fear." But does it truly spare them death's agony when the end comes?
You'll never know, and you don't need to.]]
        },
        [6200307] = {
          ContentFR = "Tu refermes leurs yeux et détournes les talons. Le deuil est inutile : le prochain tour du cadran effacera tout.",
          DialogueId = 6200307,
          GUID = "0F8595DE",
          NextDialogue = 6200308,
          RougeTalkActorType = 3,
          Subtitle = [[
The next turn of the dial will erase all of this.
Mourning and praying are pointless. Not planning to stay, you close their eyes, then turn away without looking back.]]
        },
        [6200308] = {
          ContentFR = "... Mais une voix s’élève dans ta mémoire, claire, insistante :\n« C’est à moi de les retrouver... »",
          DialogueId = 6200308,
          GUID = "0F859608",
          NextDialogue = 6200309,
          RougeTalkActorType = 3,
          Subtitle = "\"I'm the one who needs to reach them…\"\nHer words flash through your thoughts, calling out to you as if trying to remind you of something important."
        },
        [6200309] = {
          ContentFR = "Tu te retournes. Et soudain, tu perçois l’anomalie : sur quatre corps figés, un seul échappe à la cendre noire.\nCathy. Ses vêtements sont tachés seulement du sang des Souillés.",
          DialogueId = 6200309,
          GUID = "0F859632",
          NextOptions = {
            [1] = 6200310
          },
          RougeTalkActorType = 3,
          Subtitle = "You look back at the wreckage. This time, you notice something strange — while the four young Knights lie cold, only Cathy's clothes remain untouched by the black ash.\nHer armor bears only the layered stains of dried and fresh Filthoid blood."
        },
        [6200310] = {
          ContentFR = "Alors tu comprends. Comme toi, elle est arrivée trop tard.",
          DialogueId = 6200310,
          GUID = "0F85965C",
          IsKeyOption = true,
          NextDialogue = 6200311,
          RougeTalkActorType = 2,
          Subtitle = "That's when you realise she came late to this fight, just as you did."
        },
        [6200311] = {
          ContentFR = "Quand elle a retrouvé ses compagnons, ils n’étaient déjà plus que des dépouilles dans les décombres.",
          DialogueId = 6200311,
          GUID = "0F859686",
          NextDialogue = 6200312,
          RougeTalkActorType = 3,
          Subtitle = "By the time she found them, her friends were already unrecognizable remains in the rubble."
        },
        [6200312] = {
          ContentFR = "Alors elle est restée.\nÀ garder leurs dépouilles.\nÀ racheter son \"abandon\".\nÀ défendre, jusqu’au dernier battement, le serment des chevaliers.\n... Ou peut-être que les ténèbres ont fini par consumer son dernier espoir, et qu’elle a supplié la mort de l’emporter.",
          DialogueId = 6200312,
          GUID = "0F8596B0",
          NextDialogue = 6200313,
          RougeTalkActorType = 3,
          Subtitle = [[
So she stayed, fighting to the end beside those she once lost.
Was it to protect her fallen friends, to atone for "abandoning" them, or simply to uphold your knightly vows?
Had the endless darkness finally crushed her last hope, leaving her to beg for death's mercy?]]
        },
        [6200313] = {
          ContentFR = "Désormais, elle ne peut plus te répondre.",
          DialogueId = 6200313,
          GUID = "0F8596DA",
          RougeTalkActorType = 3,
          Subtitle = "Silence is all that remains."
        },
        [6200401] = {
          ContentFR = "Des voix s’élèvent au loin, des voix jeunes, animées.\nVoilà si longtemps que tu n’as pas entendu une telle chaleur dans l’Abysse : vibrantes, pleines de vie, encore intactes, épargnées par l’ombre rampante.\nTu sais d’instinct qu’il ne s’agit ni de spectres ni d’illusions : ce sont bien des êtres de chair et de sang.",
          DialogueId = 6200401,
          GUID = "0F85A54A",
          NextDialogue = 6200402,
          RougeTalkActorType = 3,
          Subtitle = "Youthful chatter carries through the gloom — a sound you haven't heard in the abyss for ages. Vibrant. Alive. Untainted by the creeping darkness.\nYou know with absolute certainty these aren't souls or illusions, but living, breathing humans."
        },
        [6200402] = {
          ContentFR = "Tu sais aussi qui ils sont.",
          DialogueId = 6200402,
          GUID = "0F85A574",
          NextDialogue = 6200403,
          RougeTalkActorType = 3,
          Subtitle = "You recognize them."
        },
        [6200403] = {
          ContentFR = "Tu avances dans la direction du bruit. La brume se déchire peu à peu... et les voilà : quatre jeunes chevaliers.\nLeurs tenues n’ont pas encore connu la poussière, leurs armes nulle souillure. L’iris sacré de leurs insignes resplendit d’un éclat doré, défiant les ténèbres de son éclat immaculé.",
          DialogueId = 6200403,
          GUID = "0F85A59E",
          NextDialogue = 6200404,
          RougeTalkActorType = 3,
          Subtitle = "Following the sound, you push forward as the mist begins to part — revealing those four young Knights standing before you.\nTheir armors are still unstained by time or battle. The sacred fleur-de-lis emblem on their clothes gleams like captured sunlight, defying the abyss with its radiance."
        },
        [6200404] = {
          ContentFR = "« Capitaine, on est bien dans la bonne direction ? »\nLa jeune chevalière blonde grimpe trois marches d’un vieil escalier, bondit d’un élan, et redescend aussitôt.\n« Ça ne ressemble qu’à des ruines... »",
          DialogueId = 6200404,
          GUID = "0F85A5C8",
          NextDialogue = 6200405,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01",
          Subtitle = [[
"Are you sure this is the right way, Captain?"
The blonde Knight bounds up the ancient staircase and leaps back down in one fluid motion.
"It's just another pile of rubble."]]
        },
        [6200405] = {
          ContentFR = "« Une chose est sûre : on n’est encore jamais venus ici. »\nLe jeune capitaine avance d’un pas posé, dépassant Cathy.\n« Dans le Lac Sacré, on perd vite tout repère. Il ne reste qu’à avancer pas à pas. »",
          DialogueId = 6200405,
          GUID = "0F85A5F2",
          NextDialogue = 6200406,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02",
          Subtitle = [[
"At least I know we haven't been here before."
The young captain strides past her with measured steps.
"Navigating the Sacred Lake is impossible. We'll just have to take it step by step."]]
        },
        [6200406] = {
          ContentFR = "« Et toi, Cathy, tu ne te fatigues pas à sautiller comme ça ? »\nIl laisse échapper un soupir résigné en voyant son amie virevolter.\n« Ménage tes forces. Ce lieu est dangereux, inutile de gaspiller ton énergie hors du combat. »",
          DialogueId = 6200406,
          GUID = "0F85A61C",
          NextDialogue = 6200407,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02",
          Subtitle = [[
"And, don't you ever get tired bouncing around like that, Cathy?"
The young captain sighs as he watches his hyperactive teammate.
"Save your energy. This place is dangerous. Let's not take unnecessary risks."]]
        },
        [6200407] = {
          ContentFR = "« Fatiguée ? Pas du tout— »",
          DialogueId = 6200407,
          GUID = "0F85A646",
          NextOptions = {
            [1] = 6200408
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01",
          Subtitle = "\"I have lots of energy to spare! You're the one who—\""
        },
        [6200408] = {
          ContentFR = "Il n’a pas tort.",
          DialogueId = 6200408,
          GUID = "0F85A670",
          NextDialogue = 6200409,
          RougeTalkActorType = 2,
          Subtitle = "He's got a point."
        },
        [6200409] = {
          ContentFR = "Elle s’arrête net, les yeux écarquillés, tournée vers toi.",
          DialogueId = 6200409,
          GUID = "0F85A69A",
          NextDialogue = 6200410,
          RougeTalkActorType = 3,
          Subtitle = "The girl stops mid-sentence, turning to you with wide eyes."
        },
        [6200410] = {
          ContentFR = "« Vous êtes... ? »",
          DialogueId = 6200410,
          GUID = "0F85A6C4",
          NextOptions = {
            [1] = 6200411
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01",
          Subtitle = "\"You are…?\""
        },
        [6200411] = {
          ContentFR = "« {性别:Un voyageur|Une voyageuse}. Je parcours ces lieux depuis plus longtemps que vous. Croyez-moi : cet endroit est bien plus terrible que vous ne l’imaginez. »",
          DialogueId = 6200411,
          GUID = "0F85A6EE",
          NextDialogue = 6200412,
          RougeTalkActorType = 2,
          Subtitle = "A traveler. I've been here longer than you have. Trust me—this place is far more dangerous than you think."
        },
        [6200412] = {
          ContentFR = "« {性别:Un voyageur|Une voyageuse}... ? » L’étonnement traverse son visage, le même qu’à votre dernière rencontre.\n« Mais ici, c’est la terre sainte d’Élysium... Comment êtes-vous entré ? »",
          DialogueId = 6200412,
          GUID = "0F85A718",
          NextOptions = {
            [1] = 6200413
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02",
          Subtitle = "\"A traveler…?\" The young Knight's expression flickers with familiar confusion, just like last time. \"But this is Elysium's sacred ground… How did you get in?\""
        },
        [6200413] = {
          ContentFR = "J’ai mes raisons. Et un but à accomplir. Tout comme vous.",
          DialogueId = 6200413,
          GUID = "0F85A742",
          NextDialogue = 6200414,
          RougeTalkActorType = 2,
          Subtitle = "I have my reasons — and a purpose to fulfil. Just like you."
        },
        [6200414] = {
          ContentFR = "« ... ? »",
          DialogueId = 6200414,
          GUID = "0F85A76C",
          NextDialogue = 6200415,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char03",
          Subtitle = "\"Hmm…?\""
        },
        [6200415] = {
          ContentFR = "La sorcière, jusque-là muette, relève enfin la tête.\nPour la première fois, tu croises son regard : sombre, méfiant, scrutateur, tel une bulle remontant à la surface d’un lac noir.",
          DialogueId = 6200415,
          GUID = "0F85A796",
          NextDialogue = 6200416,
          RougeTalkActorType = 3,
          Subtitle = "This time, the cloaked Sorceress finally shows a flicker of interest in you.\nShe lifts her head. You finally see her eyes — dark, doubtful, searching, like bubbles surfacing in shadowed waters."
        },
        [6200416] = {
          ContentFR = "« On dirait que vous connaissez une vérité qui nous échappe... Une vérité de l’Abysse. »",
          DialogueId = 6200416,
          GUID = "0F85A7C0",
          NextDialogue = 6200417,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char03",
          Subtitle = "\"It sounds like you know truths about this abyss — truths we've yet to uncover.\""
        },
        [6200417] = {
          ContentFR = "« Calista ! Voilà des paroles impies, indignes d’une fille d’Élysium ! Ici, c’est le Lac Sacré — le Lac Sacré ! »",
          DialogueId = 6200417,
          GUID = "0F85A7EA",
          NextDialogue = 6200418,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char04",
          Subtitle = "\"Calista…! Only heretics speak such blasphemy! This is sacred ground, our Sacred Lake!\""
        },
        [6200418] = {
          ContentFR = "Calista l’ignore, fixant toujours ton visage, dans l’attente de ta réponse.",
          DialogueId = 6200418,
          GUID = "0F85A814",
          NextDialogue = 6200419,
          RougeTalkActorType = 3,
          Subtitle = "Calista ignores his rebuke, her gaze steady on you, waiting for an answer."
        },
        [6200419] = {
          ContentFR = "Que pourrais-tu dire ?",
          DialogueId = 6200419,
          GUID = "0F85A83E",
          NextDialogue = 6200420,
          RougeTalkActorType = 3,
          Subtitle = "What will you say? What can you say?"
        },
        [6200420] = {
          ContentFR = "Les mettre en garde, leur ordonner de rebrousser chemin ? Mais tu sais qu’ils n’écouteraient pas. Leur foi le leur interdit.\nLa foi.\nUn mot plus lourd que n’importe quelle exhortation, plus puissant qu’un avertissement, plus implacable qu’un souvenir.",
          DialogueId = 6200420,
          GUID = "0F85A868",
          NextDialogue = 6200421,
          RougeTalkActorType = 3,
          Subtitle = "Tell them to turn back now? You know their faith forbids it.\nFaith — such a heavy word. It holds more weight than a stranger's warning or the plea of a face grown unfamiliar."
        },
        [6200421] = {
          ContentFR = "Pour ceux qui ont grandi sous la lumière de cette croyance, entendre une vérité de trop revient à fixer le soleil : une brûlure à jamais gravée dans l’âme.",
          DialogueId = 6200421,
          GUID = "0F85A892",
          NextDialogue = 6200422,
          RougeTalkActorType = 3,
          Subtitle = "For those raised in faith's radiance, unwanted truths burn like staring at the sun — leaving only daylight's cruel tattoo upon the soul."
        },
        [6200422] = {
          ContentFR = "Alors tu détournes les yeux.",
          DialogueId = 6200422,
          GUID = "0F85A8BC",
          NextOptions = {
            [1] = 6200423
          },
          RougeTalkActorType = 3,
          Subtitle = "You shake your head, avoiding her gaze."
        },
        [6200423] = {
          ContentFR = "L’Abysse est trompeur. Ne te laisse pas distancer, Cathy.",
          DialogueId = 6200423,
          GUID = "0F85A8E6",
          NextDialogue = 6200424,
          RougeTalkActorType = 2,
          Subtitle = "It's easy to get lost in the abyss. Stay close to your friends, Cathy."
        },
        [6200424] = {
          ContentFR = "« Hein ? Pourquoi moi ? »",
          DialogueId = 6200424,
          GUID = "0F85A910",
          NextDialogue = 6200425,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01",
          Subtitle = "\"Huh? Why single me out?\""
        },
        [6200425] = {
          ContentFR = "« Parce que c’est évident. Même {性别:un étranger|une étrangère} voit bien que tu es la plus imprudente du groupe. »",
          DialogueId = 6200425,
          GUID = "0F85A93A",
          NextDialogue = 6200426,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02",
          Subtitle = "\"Means you should reflect. Even strangers can see you're the most restless one.\""
        },
        [6200426] = {
          ContentFR = "« Mais pas du tout ! Et même si je me perds, je vous retrouve aussitôt. »\nElle gonfle les joues.",
          DialogueId = 6200426,
          GUID = "0F85A964",
          NextOptions = {
            [1] = 6200427
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01",
          Subtitle = "\"As if! I'd find you all in no time if we got separated.\" The girl pouts."
        },
        [6200427] = {
          ContentFR = "Pas toujours...",
          DialogueId = 6200427,
          GUID = "0F85A98E",
          IsKeyOption = true,
          NextDialogue = 6200428,
          RougeTalkActorType = 2,
          Subtitle = "Next time might be too late."
        },
        [6200428] = {
          ContentFR = "Un frisson passe sur son visage, surprise par la gravité de ton ton.",
          DialogueId = 6200428,
          GUID = "0F85A9B8",
          NextDialogue = 6200429,
          RougeTalkActorType = 3,
          Subtitle = "Cathy freezes, caught off guard by your grave tone."
        },
        [6200429] = {
          ContentFR = "Flynn intervient aussitôt, digne représentant des Chevaliers d’Élysium.\nIl sait que la foi ne suffit pas : la prudence est aussi une vertu.\nAssez de curiosité pour apprendre, mais jamais au point de courtiser le désastre.\nComme devant une porte interdite entrouverte dans une cathédrale : la sagesse est de détourner le regard et feindre de n’avoir rien vu.",
          DialogueId = 6200429,
          GUID = "0F85A9E2",
          NextDialogue = 6200430,
          RougeTalkActorType = 3,
          Subtitle = "Flynn steps forward — a true Knight of Elysium indeed. For a noble knight, piety alone is not enough; prudence too must be his virtue. He understands the delicate balance of curiosity — enough to gather information, yet not so much as to invite calamity. Like when you find a locked door in the sacred hall left slightly ajar, the wisest choice is to pause, turn away, and pretend you never saw it."
        },
        [6200430] = {
          ContentFR = "« Nous ignorons qui vous êtes vraiment, mais il est clair que vous avez votre propre chemin. Quant à nous, notre mission nous attend. »\nIl incline la tête avec gravité.\n« Que le Dieu de la Pleine Lune guide vos pas. »",
          DialogueId = 6200430,
          GUID = "0F85AA0C",
          NextDialogue = 6200431,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02",
          Subtitle = "\"Though we don't know your true identity, you're clearly here for a reason. Forgive us — duty calls us elsewhere.\" He bows solemnly. \"May the God of Full Moon bless your journey.\""
        },
        [6200431] = {
          ContentFR = "Les chevaliers s’éloignent ensemble, te laissant {性别:seul|seule} face à la brume infinie.",
          DialogueId = 6200431,
          GUID = "0F85AA36",
          RougeTalkActorType = 3,
          Subtitle = "The Knights depart together, leaving only endless mist before you."
        },
        [6200501] = {
          ContentFR = "Les combats sans fin t’ont vidé de tes forces.\nLa dernière braise s’éteint dans ta paume. Ton chemin s’efface.",
          DialogueId = 6200501,
          GUID = "0F85B5B2",
          NextDialogue = 6200502,
          RougeTalkActorType = 3,
          Subtitle = "Endless battles drain your strength.\nThe last ember slips through your fingers — direction lost in the void."
        },
        [6200502] = {
          ContentFR = "La lanterne tombe, son verre éclatant dans un fracas tranchant, comme une lame déchirant la nuit.\nDe toutes parts, les ombres se ruent, lacérant ton corps, rongeant tes nerfs.",
          DialogueId = 6200502,
          GUID = "0F85B5DC",
          NextDialogue = 6200503,
          RougeTalkActorType = 3,
          Subtitle = [[
The lantern falls to the ground, its crystal shattering with a sound like blades cutting through the silent darkness.
Splintered shadows rush toward you from every direction, corroding your flesh and biting at your nerves.]]
        },
        [6200503] = {
          ContentFR = "Puis vient l’abandon.\nTes sens se fondent dans l’obscurité, qui te berce doucement. Elle enveloppe tes plaies, apaise ta fatigue.",
          DialogueId = 6200503,
          GUID = "0F85B606",
          NextDialogue = 6200504,
          RougeTalkActorType = 3,
          Subtitle = "As your senses merge with the darkness, you stop resisting. It embraces you gently, tending your wounds, and soothing your weariness."
        },
        [6200504] = {
          ContentFR = "Peut-être est-ce ainsi que tout doit finir. Dans un souffle, la nuit te murmure :\n« Tu as assez tenu. »",
          DialogueId = 6200504,
          GUID = "0F85B630",
          NextDialogue = 6200505,
          RougeTalkActorType = 3,
          Subtitle = "Perhaps this is meant to be. The darkness whispers to you —\n\"You've held on long enough.\""
        },
        [6200505] = {
          ContentFR = "Oui... tu as lutté de toutes tes forces. À chaque cycle, tu as combattu, souffert, bu le désespoir comme un vin amer.\nToujours {性别:seul|seule}. Toujours sans lumière.",
          DialogueId = 6200505,
          GUID = "0F85B65A",
          NextDialogue = 6200506,
          RougeTalkActorType = 3,
          Subtitle = "Indeed… You've fought hard enough. Cycle after solitary cycle, you battle and struggle, drinking despair like fine wine while drowning in endless pain — yet dawn's light remains beyond reach."
        },
        [6200506] = {
          ContentFR = "Tu es {性别:épuisé|épuisée}. Laisse-toi aller.",
          DialogueId = 6200506,
          GUID = "0F85B684",
          NextDialogue = 6200507,
          RougeTalkActorType = 3,
          Subtitle = "Weariness claims you. Let it end here."
        },
        [6200507] = {
          ContentFR = "Le sommeil t’emporte dans son berceau d’ombre... Mais soudain, un visage perce ta conscience. Tu ne distingues plus ses traits, pourtant ce souvenir indistinct tranche ta torpeur comme une lame.\nIl secoue ton esprit, soulève une marée.",
          DialogueId = 6200507,
          GUID = "0F85B6AE",
          NextDialogue = 6200508,
          RougeTalkActorType = 3,
          Subtitle = "You feel yourself drifting into the dark cradle of sleep — until a distant figure surfaces in your mind. Though its face eludes you, this vague memory cuts through your numbness like a blade, jolting you awake. It churns the sea of your thoughts, stirring relentless tides."
        },
        [6200508] = {
          ContentFR = "C’était lui.\nCelui qui avait juré de vaincre les ténèbres à tes côtés.\nCelui qui a fait de toi une victime des cycles.",
          DialogueId = 6200508,
          GUID = "0F85B6D8",
          NextDialogue = 6200509,
          RougeTalkActorType = 3,
          Subtitle = "That figure — the one who vowed to conquer the darkness with you, to escape the abyss together, and the architect of your torment."
        },
        [6200509] = {
          ContentFR = "Tu ne l’as pas encore retrouvé. Tu ne peux pas céder.\nAussi douce soit son étreinte, l’obscurité n’est pas ton destin.\nTu dois continuer. Pour ton but. Pour ta promesse. Pour briser ce cercle absurde.",
          DialogueId = 6200509,
          GUID = "0F85B702",
          NextOptions = {
            [1] = 6200510
          },
          RougeTalkActorType = 3,
          Subtitle = "You still haven't found them. Yes… now you remember.\nDon't you dare close your eyes. No matter how sweet the darkness beckons, this is not the ending you seek.\nFight on — for the journey's end, for your promise, for breaking this cursed cycle."
        },
        [6200510] = {
          ContentFR = "Tourner le cadran",
          DialogueId = 6200510,
          GUID = "0F85B72C",
          IsKeyOption = true,
          NextDialogue = 6200511,
          RougeTalkActorType = 2,
          Subtitle = "Rotate the dial"
        },
        [6200511] = {
          ContentFR = "Tu tournes le cadran. Et l’histoire recommence, depuis son origine.",
          DialogueId = 6200511,
          GUID = "0F85B756",
          RougeTalkActorType = 3,
          Subtitle = "Again, you turn the lantern's dial back to where the story begins."
        },
        [6200601] = {
          ContentFR = "Les directions se dérobent sans cesse dans l’Abysse. Tu ne sais jamais si tu avances... ou si tu recules.\nParfois, l’impression d’être enfermé dans une spirale sans fin t’écrase : un cercle fermé, un ouroboros sans échappatoire.",
          DialogueId = 6200601,
          GUID = "0F85C61A",
          NextDialogue = 6200602,
          RougeTalkActorType = 3,
          Subtitle = [[
Directions warp constantly in the abyss. You can't always tell if you're moving forward or backward.
Sometimes you feel trapped in an ouroboros spiral, circling without hope of escape.]]
        },
        [6200602] = {
          ContentFR = "Mais quand cette silhouette colossale surgit dans ton champ de vision, ton instinct le crie aussitôt : voilà le \"cœur battant\" de l’Abysse.",
          DialogueId = 6200602,
          GUID = "0F85C644",
          NextDialogue = 6200603,
          RougeTalkActorType = 3,
          Subtitle = "Yet when this colossal entity appears before you, instinct screams — this is the abyss's \"beating heart.\""
        },
        [6200603] = {
          ContentFR = "Tu lèves ta lanterne. Sa lumière fragile s’écrase contre l’immensité de ses contours et disparaît, engloutie sans merci.\nTout autour, les ténèbres se soulèvent comme une encre trouble, se déversant vers un même centre.",
          DialogueId = 6200603,
          GUID = "0F85C66E",
          NextDialogue = 6200604,
          RougeTalkActorType = 3,
          Subtitle = [[
You raise the lantern, but its feeble light drowns the moment it grazes His edges.
The chaotic darkness swirls like ink, converging toward a single point.]]
        },
        [6200604] = {
          ContentFR = "La terre gronde, le sol se rompt sous tes pieds, et tu chutes dans le noir.\nUn instant, tu sens ton propre corps se dissoudre, se mêler à ce flot impur, se délier et couler vers l’Être qui dévore tout.",
          DialogueId = 6200604,
          GUID = "0F85C698",
          NextDialogue = 6200605,
          RougeTalkActorType = 3,
          Subtitle = "The earth shudders and splits, swallowing you whole.\nYour body dissolves into the churning dark — limbs scattering like ink in water, pulled toward the devouring heart."
        },
        [6200605] = {
          ContentFR = "Un silence strident broie ton crâne. Ton instinct de survie hurle : « fuis ! »",
          DialogueId = 6200605,
          GUID = "0F85C6C2",
          NextOptions = {
            [1] = 6200606,
            [2] = 6200615
          },
          RougeTalkActorType = 3,
          Subtitle = "A deafening silence crushes your skull. Survival instinct screams: Turn back now."
        },
        [6200606] = {
          ContentFR = "<I>Continuer à le fixer</>",
          DialogueId = 6200606,
          GUID = "0F85C6EC",
          IsKeyOption = true,
          NextDialogue = 6200607,
          RougeTalkActorType = 2,
          Subtitle = "Don't look away."
        },
        [6200607] = {
          ContentFR = "Tu refuses pourtant.\nTu te redresses dans le vide, la lanterne brandie bien haut, et ton geste seul proclame : « je ne te crains pas. »",
          DialogueId = 6200607,
          GUID = "0F85C716",
          NextDialogue = 6200608,
          RougeTalkActorType = 3,
          Subtitle = "You refuse to back down.\nRising from the void, lantern held high — your stance declares what words cannot: this darkness holds no terror for you."
        },
        [6200608] = {
          ContentFR = "Alors, peu à peu, quelque chose fissure ce chaos. Une brèche.\nDe l’insondable obscurité s’infiltre en toi... et, incroyable, tu comprends ce qu’elle te transmet.",
          DialogueId = 6200608,
          GUID = "0F85C740",
          NextDialogue = 6200609,
          RougeTalkActorType = 3,
          Subtitle = "Gradually, something fractures the darkness — a sliver of fissure appears, slipping something into your veins. Unthinkable, yet you comprehend its whispers."
        },
        [6200609] = {
          ContentFR = "Des émotions humaines : le doute. La colère. La douleur. Le désespoir.\nEt, par-dessus tout... une tristesse écrasante.\nComme si l’Abysse elle-même aspirait à une fin.",
          DialogueId = 6200609,
          GUID = "0F85C76A",
          NextDialogue = 6200610,
          RougeTalkActorType = 3,
          Subtitle = [[
These are human emotions: doubt, fury, anguish, despair, and crushing sorrow.
A sorrow so overwhelming it feels as if the very abyss itself is longing for an end.]]
        },
        [6200610] = {
          ContentFR = "« Comment puis-je t’aider ? » La question t’échappe, brûlante.",
          DialogueId = 6200610,
          GUID = "0F85C794",
          NextDialogue = 6200611,
          RougeTalkActorType = 3,
          Subtitle = "The question burns in your throat: \"How can I help you?\""
        },
        [6200611] = {
          ContentFR = "Cette lanterne n’éclaire pas assez. Continue ton chemin, murmure-t-Il. Au terme du cycle, tu trouveras la réponse.",
          DialogueId = 6200611,
          GUID = "0F85C7BE",
          NextDialogue = 6200612,
          RougeTalkActorType = 3,
          Subtitle = "Keep on. Your lantern's flame still falters in the dark. It says. Your answer awaits at the cycle's end."
        },
        [6200612] = {
          ContentFR = "« Où s’achève-t-il ? »",
          DialogueId = 6200612,
          GUID = "0F85C7E8",
          NextDialogue = 6200613,
          RougeTalkActorType = 3,
          Subtitle = "\"Where does it end?\" You ask."
        },
        [6200613] = {
          ContentFR = "Aucune réponse.\nSeulement cette obscurité qui t’entoure doucement, et la lueur de ta lanterne qui demeure seule, suspendue dans le vide.",
          DialogueId = 6200613,
          GUID = "0F85C812",
          NextDialogue = 6200614,
          RougeTalkActorType = 3,
          Subtitle = "Only silence answers. Darkness cradles you tenderly, until only your lantern's light persists in the void."
        },
        [6200614] = {
          ContentFR = "Alors tu tournes le cadran. Et le temps s’inverse encore une fois.",
          DialogueId = 6200614,
          GUID = "0F85C83C",
          RougeTalkActorType = 3,
          Subtitle = "So you turn the dial on the lantern, rewinding time once more."
        },
        [6200615] = {
          ContentFR = "<I>Faire demi-tour</>",
          DialogueId = 6200615,
          GUID = "0F85C866",
          IsKeyOption = true,
          NextDialogue = 6200616,
          RougeTalkActorType = 2,
          Subtitle = "Turn back"
        },
        [6200616] = {
          ContentFR = "Sage décision.\nTu recules, tu pivotes, tu fuis. L’instinct t’arrache au gouffre, même si tu sais qu’aucun chemin ne ramènera tes pas.",
          DialogueId = 6200616,
          GUID = "0F85C890",
          NextDialogue = 6200617,
          RougeTalkActorType = 3,
          Subtitle = [[
A wise choice.
Turn back. Step away. Instinct screams for retreat though you know you can never retrace your footsteps.]]
        },
        [6200617] = {
          ContentFR = "Soudain, une présence te glace l’échine. Il est là, derrière toi, muet... et triste de te voir partir.",
          DialogueId = 6200617,
          GUID = "0F85C8BA",
          NextDialogue = 6200618,
          RougeTalkActorType = 3,
          Subtitle = "Out of nowhere, a presence prickles between your shoulder blades — silent, watching, aching with the weight of your departure."
        },
        [6200618] = {
          ContentFR = "« Veux-tu que je reste ? » chuchotes-tu dans ton cœur.",
          DialogueId = 6200618,
          GUID = "0F85C8E4",
          NextDialogue = 6200619,
          RougeTalkActorType = 3,
          Subtitle = "\"Do you want me to turn back?\" Your heart whispers the question into the dark."
        },
        [6200619] = {
          ContentFR = "Non. Suis ta route, répond-Il. Au terme du cycle, nous nous reverrons.",
          DialogueId = 6200619,
          GUID = "0F85C90E",
          NextDialogue = 6200620,
          RougeTalkActorType = 3,
          Subtitle = "No. Walk your path, It speaks. At the cycle's end, we'll meet again."
        },
        [6200620] = {
          ContentFR = "« Où s’achève-t-il ? »",
          DialogueId = 6200620,
          GUID = "0F85C938",
          NextDialogue = 6200621,
          RougeTalkActorType = 3,
          Subtitle = "\"Where does it end?\" You ask."
        },
        [6200621] = {
          ContentFR = "La nuit franchit ton épaule et vient emplir l’espace de sa tendresse.\nIl ne reste plus que la lueur vacillante de ta lanterne.",
          DialogueId = 6200621,
          GUID = "0F85C962",
          NextDialogue = 6200622,
          RougeTalkActorType = 3,
          Subtitle = "Only silence answers. Darkness flows over your shoulder, gently saturating the space around you, until only your lantern's light persists in the void."
        },
        [6200622] = {
          ContentFR = "Alors tu tournes le cadran. Et le temps s’inverse encore une fois.",
          DialogueId = 6200622,
          GUID = "0F85C98C",
          RougeTalkActorType = 3,
          Subtitle = "So you turn the dial on the lantern, rewinding time once more."
        },
        [6200701] = {
          ContentFR = "Un jeune homme énigmatique se tient près du feu de camp.\nDifficile d’estimer son âge — seule sa voix te le laisse deviner.\nCe n’est pas votre première rencontre.",
          DialogueId = 6200701,
          GUID = "0F85D682",
          NextDialogue = 6200702,
          RougeTalkActorType = 3,
          Subtitle = "A mysterious young man stands by the campfire. In truth, you cannot be sure of his age — you only guess from the sound of his voice.\nThis is not your first encounter."
        },
        [6200702] = {
          ContentFR = "« Nous revoici, {性别:courageux voyageur|courageuse voyageuse}. »",
          DialogueId = 6200702,
          GUID = "0F85D6AC",
          NextDialogue = 6200703,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"We meet again, brave traveller.\""
        },
        [6200703] = {
          ContentFR = "Il te salue avec courtoisie.\nTu ne distingues pas ses yeux : un masque de métal anguleux dissimule son visage du front aux joues.",
          DialogueId = 6200703,
          GUID = "0F85D6D6",
          NextDialogue = 6200704,
          RougeTalkActorType = 3,
          Subtitle = "He greets you with quiet courtesy.\nYou cannot see his eyes — a sharp-edged mask of metal covers his face from brow to cheek."
        },
        [6200704] = {
          ContentFR = "« Ceux qui errent trop longtemps dans l’Abysse se perdent, et finissent par devenir des Umbrés. »\n« Mais la <H>lumière</> de ces objets te guidera, pour que tu ne sois pas englouti.\nDépose-les dans ta lanterne — qu’ils en deviennent des Lucimèches. »\nÀ la place de son regard, le feu se reflète sur l’acier poli.",
          DialogueId = 6200704,
          GUID = "0F85D700",
          NextDialogue = 6200705,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Those who wander the Abyss for too long often lose their way — until, at last, they become one of the Abyssoids.\"\n\"But the light within these objects will guide you, lest your path be swallowed by the darkness,\" he says. \"Place them within your Lantern, as its Lampwick.\"\nWhere his eyes should be, the firelight shimmers faintly, caught in the steel."
        },
        [6200705] = {
          ContentFR = "« Mais je crois que tu ne l’as jamais oublié. Car tu <H>finis toujours</> par revenir ici. »\n« Comme toujours, j’ai disposé quelques provisions près du feu. Prends ce dont tu as besoin. »",
          DialogueId = 6200705,
          GUID = "0F85D72A",
          NextOptions = {
            [1] = 6200706
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"But I do not think you ever truly forget. For you are always fated to return here."
"As always, I have laid out supplies by the campfire. Take what you need, whenever the need arises."]]
        },
        [6200706] = {
          ContentFR = "<I>Qui êtes-vous ?</>",
          DialogueId = 6200706,
          GUID = "0F85D754",
          NextDialogue = 6200707,
          RougeTalkActorType = 2,
          Subtitle = "Who are you?"
        },
        [6200707] = {
          ContentFR = "« Encore cette question. Tu me l’as posée tant de fois. Pardonne-moi, je ne puis y répondre. »\n« Non par volonté de cacher la vérité, mais parce que moi-même, ici et maintenant, j’ignore quel nom me convient. »\nIl rit doucement.",
          DialogueId = 6200707,
          GUID = "0F85D77E",
          NextDialogue = 6200708,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"That question again. You've asked it many times. Forgive me — I cannot answer, not now.\"\n\"Not because I would hide the truth... but because I, too, am unsure — here and now — what name I ought to claim.\"\nHe lets out a soft laugh."
        },
        [6200708] = {
          ContentFR = "« Alors faisons simple : considère-moi comme un humble <H>marchand</>.\nTout comme toi, tu te dis souvent : \"Je ne suis qu’{性别:un humble voyageur|une humble voyageuse}.\" »",
          DialogueId = 6200708,
          GUID = "0F85D7A8",
          NextOptions = {
            [1] = 6200709
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Then let us keep it simple — think of me as a humble merchant.\"\n\"Just as you so often say of yourself: 'I am but a humble traveller.'\""
        },
        [6200709] = {
          ContentFR = "<I>Je dois partir.</>",
          DialogueId = 6200709,
          GUID = "0F85D7D2",
          IsKeyOption = true,
          NextDialogue = 6200710,
          RougeTalkActorType = 2,
          Subtitle = "I must be on my way."
        },
        [6200710] = {
          ContentFR = "« Adieu, {性别:courageux voyageur|courageuse voyageuse}. Que la flamme de ta lanterne ne s’éteigne jamais. »\nSon visage demeure invisible. \nMais peut-être, derrière le masque, ses yeux abritent-ils eux aussi le reflet vacillant du feu.",
          DialogueId = 6200710,
          GUID = "0F85D7FC",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"Farewell, brave traveller," he says. "May the flame of your Lantern shine ever unceasing upon your path."
You still cannot see his face. Perhaps, behind the mask, the firelight flickers in his eyes.]]
        },
        [6200801] = {
          ContentFR = "Le Marchand de l’Abysse se tient près du feu de camp, comme à chacune de vos rencontres.\nNulle plainte spectrale, nulle rumeur d’Umbrés : seulement le silence, qui cerne cet endroit.",
          DialogueId = 6200801,
          GUID = "0F85E6EA",
          NextDialogue = 6200802,
          RougeTalkActorType = 3,
          Subtitle = "The Abyssal Merchant stands beside the fire — just as he always has.\nNo howls of Abyssoids; only silence enfolds this place."
        },
        [6200802] = {
          ContentFR = "« Nous revoici, {性别:voyageur égaré|voyageuse égarée}. »\n« Tu es venu pour cette faible <H>lueur</>. »\nSa voix est calme et posée, telle l’eau d’un lac immobile.\n« Et moi, j’attends, pour ajouter à ta lanterne une nouvelle Lucimèche. »",
          DialogueId = 6200802,
          GUID = "0F85E714",
          NextOptions = {
            [1] = 6200803
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"We meet again, wandering traveller."
"You've come for the faint glow."
His voice is calm and steady, like a still lake untouched by wind.
"And I remain... to set a new wick within your Lantern's flame."]]
        },
        [6200803] = {
          ContentFR = "<I>Pourquoi ne pas simplement me la donner ?</>",
          DialogueId = 6200803,
          GUID = "0F85E73E",
          NextDialogue = 6200804,
          RougeTalkActorType = 2,
          Subtitle = "Why can't you just give it to me?"
        },
        [6200804] = {
          ContentFR = "« Comme tu le vois, je n’ai plus ce pouvoir. »\nIl secoue la tête.\n« Tout ce que je puis faire désormais, c’est d’user d’un sort modeste pour changer tes quelques Braises en une Lucimèche. »",
          DialogueId = 6200804,
          GUID = "0F85E768",
          NextDialogue = 6200805,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"As you can see, I no longer possess such power.\"\nHe shakes his head.\n\"All that remains to me is a humble spell — to weave your Embers into a wick of light.\""
        },
        [6200805] = {
          ContentFR = "Le Marchand prend la lanterne.\nDans ses mains, les Braises s’animent, semblables à des lucioles qui s’envolent, jusqu’à se fondre en une Lucimèche.",
          DialogueId = 6200805,
          GUID = "0F85E792",
          NextOptions = {
            [1] = 6200806
          },
          RougeTalkActorType = 3,
          Subtitle = "The Merchant takes your Lantern.\nIn his hands, the Embers stir — like fireflies taking flight — until at last, they gather into a single, shining wick."
        },
        [6200806] = {
          ContentFR = "<I>Merci.</>",
          DialogueId = 6200806,
          GUID = "0F85E7BC",
          NextDialogue = 6200807,
          RougeTalkActorType = 2,
          Subtitle = "Then... thank you."
        },
        [6200807] = {
          ContentFR = "Tu secoues doucement la lanterne : grâce à la mèche, la lueur vacillante s’est faite plus claire.\nC’est ton unique compagne. Dans l’obscurité insondable de l’Abysse, elle seule t’empêche de perdre ta route.",
          DialogueId = 6200807,
          GUID = "0F85E7E6",
          NextOptions = {
            [1] = 6200808
          },
          RougeTalkActorType = 3,
          Subtitle = "You give the lantern a gentle shake. With its new wick, the once-faint glow now burns a little brighter.\nIn this vast and gloomy Abyss, it is your only companion — the one light that keeps you from losing your way."
        },
        [6200808] = {
          ContentFR = "<I>Je dois partir.</>",
          DialogueId = 6200808,
          GUID = "0F85E810",
          IsKeyOption = true,
          NextDialogue = 6200809,
          RougeTalkActorType = 2,
          Subtitle = "I must be on my way."
        },
        [6200809] = {
          ContentFR = "« Adieu, {性别:voyageur égaré|voyageuse égarée}. »\n« Que la flamme de ta lanterne ne s’éteigne jamais. »",
          DialogueId = 6200809,
          GUID = "0F85E83A",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Farewell, wandering traveller,\" he says. \"May the flame of your Lantern shine ever unceasing upon your path.\""
        },
        [6200901] = {
          ContentFR = "Encore une fois, tu es revenu ici.\nSi l’Abysse offre un lieu où ton cœur puisse trouver un instant de répit, c’est bien celui-là.",
          DialogueId = 6200901,
          GUID = "0F85F752",
          NextOptions = {
            [1] = 6200902
          },
          RougeTalkActorType = 3,
          Subtitle = [[
Once again, you find yourself here.
If there is a haven in the dark, this is the closest thing to it.]]
        },
        [6200902] = {
          ContentFR = "<I>Vous êtes toujours là.</>",
          DialogueId = 6200902,
          GUID = "0F85F77C",
          NextDialogue = 6200903,
          RougeTalkActorType = 2,
          Subtitle = "You're still here."
        },
        [6200903] = {
          ContentFR = "« Oui. »\nSa voix est égale, douce.\n« Je resterai jusqu’à pouvoir t’aider à mettre fin à ces ténèbres. »",
          DialogueId = 6200903,
          GUID = "0F85F7A6",
          NextOptions = {
            [1] = 6200904
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"I am."
The Merchant's voice is calm, ever gentle.
"Until I can aid you in ending this darkness, I shall remain."]]
        },
        [6200904] = {
          ContentFR = "<I>Mais personne d’autre ne se souviendra de moi.</>",
          DialogueId = 6200904,
          GUID = "0F85F7D0",
          NextDialogue = 6200905,
          RougeTalkActorType = 2,
          Subtitle = "But no one else remembers me."
        },
        [6200905] = {
          ContentFR = "« Les spectres de l’Abysse, les quelques humains qui subsistent... Quand je tourne le cadran pour revenir en arrière, ils m’oublient. Comme si nous ne nous étions jamais rencontrés, jamais parlé. »\n« Même si je sauve quelqu’un, il meurt la fois suivante. »\n« Même si je rencontre beaucoup d’âmes, je finis toujours {性别:seul|seule}. »",
          DialogueId = 6200905,
          GUID = "0F85F7FA",
          NextDialogue = 6200906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"Those... ghosts of the Abyss, and the few humans who remain — when I turn the dial and return to the past, they forget me, as though we had never met, never spoken.\"\n\"Even if I manage to save someone, most still perish the next time.\"\n\"Though I meet many along the way... in the end, I remain alone.\""
        },
        [6200906] = {
          ContentFR = "« Oui. Dans l’Abysse, tout revient, vague après vague, rejeté vers le passé. »\n« Mais toi, tu es {性别:différent|différente}. En tenant ce cadran, tu t’es placé hors du cours du temps. »\nIl laisse échapper un léger soupir.",
          DialogueId = 6200906,
          GUID = "0F85F824",
          NextDialogue = 6200907,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"Yes. The Abyss moves like the tide, ever returning all things to yesterday."
"But you are different. As the owner of the dial, you now stand beyond the current of time."
He lets out a quiet sigh.]]
        },
        [6200907] = {
          ContentFR = "{性别:« Ici, dans l’Abysse, tu commandes au temps. Toi seul es <H>éternel</>, avec un pouvoir qui n’appartenait jadis qu’aux dieux. »\n« Mais ce pouvoir n’offre pas un trône : il fait de toi un prisonnier. Tu es condamné à voir tout ce qui t’entoure disparaître, encore et encore, sans jamais le retenir. »|« Ici, dans l’Abysse, tu commandes au temps. Toi seule es <H>éternelle</>, avec un pouvoir qui n’appartenait jadis qu’aux dieux. »\n« Mais ce pouvoir n’offre pas un trône : il fait de toi une prisonnière. Tu es condamnée à voir tout ce qui t’entoure disparaître, encore et encore, sans jamais le retenir. »}\nDans sa voix calme tremble une nuance imperceptible.\n« Pourtant, c’est le seul moyen d’affronter l’Abysse. »",
          DialogueId = 6200907,
          GUID = "0F85F84E",
          NextOptions = {
            [1] = 6200908
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Here in the Abyss, time bends to your will. You alone are eternal — wielding a sceptre once meant only for the gods.\"\n\"Yet that sceptre leads not to a throne, but to a prison. It binds you to witness, again and again, as all things are torn from you — never to be held.\"\nThere's the faintest quiver in his otherwise calm voice.\n\"And still... it is the only way to defy the Abyss.\""
        },
        [6200908] = {
          ContentFR = "<I>Je dois partir.</>",
          DialogueId = 6200908,
          GUID = "0F85F878",
          IsKeyOption = true,
          NextDialogue = 6200909,
          RougeTalkActorType = 2,
          Subtitle = "I must be on my way."
        },
        [6200909] = {
          ContentFR = "« Adieu, {性别:voyageur solitaire|voyageuse solitaire}. »\n« Que la flamme de ta lanterne ne s’éteigne jamais. »",
          DialogueId = 6200909,
          GUID = "0F85F8A2",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Farewell, lonely traveller,\" he says. \"May the flame of your Lantern shine ever unceasing upon your path.\""
        },
        [6201001] = {
          ContentFR = "Tu trouves encore un court répit.\nPas d’Umbrés, pas de plaintes d’âmes perdues. Ici, tu es en sécurité.\nTu glisses lentement contre un mur brisé et t’assieds.",
          DialogueId = 6201001,
          GUID = "0F8607BA",
          NextOptions = {
            [1] = 6201002
          },
          RougeTalkActorType = 3,
          Subtitle = "Once again, you find a fleeting moment of respite.\nNo Abyssoids give chase. No wailing souls. At last — a place of safety.\nYou sink slowly to the ground, resting against a broken wall."
        },
        [6201002] = {
          ContentFR = "<I>Je suis {性别:fatigué|fatiguée}.</>",
          DialogueId = 6201002,
          GUID = "0F8607E4",
          NextDialogue = 6201003,
          RougeTalkActorType = 2,
          Subtitle = "I'm tired."
        },
        [6201003] = {
          ContentFR = "« Encore et encore, j’avance. Encore et encore, je recommence. »\n« Je sais que ce combat est le mien... mais combien de temps durera-t-il encore ? »",
          DialogueId = 6201003,
          GUID = "0F86080E",
          NextDialogue = 6201004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = [[
"Again and again I push forward. Again and again I start over."
"I know this battle is mine... but I don't know how much longer it will last."]]
        },
        [6201004] = {
          ContentFR = "« Lorsque la bénédiction divine — la <H>Lumistella</> — se rassemblera, et que la lanterne sera restaurée, alors un miracle se manifestera. »\n« Tu porteras une lumière assez forte pour déchirer ces ténèbres. »",
          DialogueId = 6201004,
          GUID = "0F860838",
          NextOptions = {
            [1] = 6201005
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"When the divine blessing — Pure Glazeystal — is gathered once more, and the Lantern restored, a miracle shall be revealed.\"\n\"Then shall you bear a light strong enough to cleave this darkness.\""
        },
        [6201005] = {
          ContentFR = "<I>Non. Ce n’est pas ce que je veux savoir.</>",
          DialogueId = 6201005,
          GUID = "0F860862",
          NextDialogue = 6201006,
          RougeTalkActorType = 2,
          Subtitle = "That's not what I meant."
        },
        [6201006] = {
          ContentFR = "« J’ignore depuis combien de temps je marche ici... Dix ans ? Vingt ? Plus encore ? La seule chose que je compte, c’est le nombre de fois où j’ai tourné le cadran. »\n« Et pourtant, la lanterne brille toujours si faiblement... comme si tout ce que j’ai fait n’avait aucun sens. »\n« Et si je mourais avant de la réparer ? Alors tout ce que j’ai traversé... qu’aurait-ce été ? »\n« Une farce stupide et tragique ? »",
          DialogueId = 6201006,
          GUID = "0F86088C",
          NextDialogue = 6201007,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"I don't even know how long I've wandered here — ten years? Twenty? Or longer still? All I can count is how many times I've turned the dial.\"\n\"And still the Lantern's glow remains so faint... as if all I've done were in vain.\"\n\"What if it's never made whole — not until I'm already gone? Then everything I've done... what would it all be for?\"\n\"Would it all just be some pathetic joke?\""
        },
        [6201007] = {
          ContentFR = "« Oui. »\nIl ne nie pas, et cela t’étonne.",
          DialogueId = 6201007,
          GUID = "0F8608B6",
          NextDialogue = 6201008,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"Yes."
He does not deny it. The starkness of the answer catches you off guard.]]
        },
        [6201008] = {
          ContentFR = "« Je t’ai vu lever ton arme encore et encore, chasser les ombres, comme j’ai vu des milliers d’ouvriers tailler la pierre, poser les fondations d’un temple. »\n« J’ai vu une fille jeter des cailloux dans le feu, encore et encore, comme j’ai vu des milliers de paysans semer les champs, année après année. »\n« Tout labeur, toute lutte, pour que tout recommence. Pas seulement toi et moi : les âmes de l’Abysse, les vivants d’en haut — tous rejouent sans fin cette tragédie. »\n« Si cela t’est trop lourd, tu peux à tout moment poser ce fardeau. Alors tout s’achèvera. »",
          DialogueId = 6201008,
          GUID = "0F8608E0",
          NextOptions = {
            [1] = 6201009
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"I have seen you raise your blade, again and again,\ndriving back the Abyssoids — just as I have seen thousands of masons hewing stone, laying the foundations of a temple.\"\n\"I have seen a girl toss pebbles into the flame, again and again — just as I have seen thousands of farmers scatter seed, year after year.\"\n\"All effort, all struggle... only for the cycle to begin anew.\nNot just you and I — but the souls of the Abyss, and the living above — all are bound within this endless tragedy.\"\n\"And if that burden proves too great for you to carry... you may always lay it down. And then — it would end.\""
        },
        [6201009] = {
          ContentFR = "<I>Refuser</>",
          DialogueId = 6201009,
          GUID = "0F86090A",
          NextDialogue = 6201010,
          RougeTalkActorType = 2,
          Subtitle = "Refuse."
        },
        [6201010] = {
          ContentFR = "Mettre fin à tout — ce serait devenir comme ces spectres errants.\nTon cœur tendre n’existerait plus. Tu ne craindrais plus la solitude, tu ne souffrirais plus de cette absurdité sans fin.\nMais... serait-ce vraiment le bonheur ?",
          DialogueId = 6201010,
          GUID = "0F860934",
          NextDialogue = 6201011,
          RougeTalkActorType = 3,
          Subtitle = [[
To end it all would be to become one of those drifting souls.
Your gentle heart would fade. You'd no longer fear solitude, no longer feel the torment of this endless cycle. But... would that truly be happiness?]]
        },
        [6201011] = {
          ContentFR = "« Non. » Tu reprends ton arme.\n« Je continuerai à me battre. À chercher ces maudits fragments de Lumistella. »",
          DialogueId = 6201011,
          GUID = "0F86095E",
          NextOptions = {
            [1] = 6201012
          },
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = [[
"No." You take up your blade once more. 
"I'll keep fighting. I'll keep chasing those damned Glazeystal shards."]]
        },
        [6201012] = {
          ContentFR = "<I>Je dois partir.</>",
          DialogueId = 6201012,
          GUID = "0F860988",
          IsKeyOption = true,
          NextDialogue = 6201013,
          RougeTalkActorType = 2,
          Subtitle = "I must be on my way."
        },
        [6201013] = {
          ContentFR = "« Adieu, {性别:voyageur inflexible|voyageuse inflexible} »\n« Que la flamme de ta lanterne ne s’éteigne jamais. »",
          DialogueId = 6201013,
          GUID = "0F8609B2",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Farewell, steadfast traveller,\" he says. \"May the flame of your Lantern shine ever unceasing upon your path.\""
        },
        [6201101] = {
          ContentFR = "Le marchand prend ta lanterne. Sans un mot, vous échangez Braises et Lucimèches.\nMais cette fois, tu n’as pas l’intention de t’attarder.",
          DialogueId = 6201101,
          GUID = "0F861822",
          NextOptions = {
            [1] = 6201102
          },
          RougeTalkActorType = 3,
          Subtitle = [[
The Abyssal Merchant takes the Lantern from your hands. Without a word, you trade Embers for a Lampwick with him.
This time, you have no intention of lingering.]]
        },
        [6201102] = {
          ContentFR = "<I>Je dois partir.</>",
          DialogueId = 6201102,
          GUID = "0F86184C",
          IsKeyOption = true,
          NextDialogue = 6201103,
          RougeTalkActorType = 2,
          Subtitle = "I must be on my way."
        },
        [6201103] = {
          ContentFR = "« Tiens, prends ceci. »\nSa voix s’élève derrière toi. Il dépose un objet dans ta main.\n« Cela ne brille pas, il ne requiert donc aucune Braise. »\nC’est un bonbon, limpide, translucide, qui repose dans ta paume tachée de sang et de cendre.",
          DialogueId = 6201103,
          GUID = "0F861876",
          NextDialogue = 6201104,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Take this.\"\nA young voice speaks softly from behind you. He presses something into your hand.\n\"It gives no light, so no Ember is needed.\"\nA piece of candy — clear, translucent — rests in your blood-stained palm."
        },
        [6201104] = {
          ContentFR = "Tu le poses sur ta langue et le laisses fondre. Le goût de menthe sauvage t’envahit : vif, glacé, pénétrant. Pour la première fois depuis longtemps, ton esprit s’éclaircit... Tu redeviens humain.\nLes Umbrés cessent d’envahir tes pensées. Au contraire, des souvenirs reviennent : une tour dressée jusqu’aux nuages, le chêne qu’enfant tu ne pouvais t’empêcher d’escalader, la crème glacée sur une assiette d’argent, la balançoire qui grinçait dans la cour.\nPreuve que tu as bel et bien vécu.",
          DialogueId = 6201104,
          GUID = "0F8618A0",
          NextDialogue = 6201105,
          RougeTalkActorType = 3,
          Subtitle = "You place it on your tongue and let it melt. The taste is wild mint — sharp, cool, piercing. For the first time in ages, your mind clears... and you remember what it is to be human.\nNo longer do Abyssoids haunt your thoughts. Instead, memories return: a tower that pierced the clouds; the oak you could never resist climbing; the chill of cream on a silver plate; the swing swaying in the backyard.\nThese memories — proof that you have lived."
        },
        [6201105] = {
          ContentFR = "Et ce mystérieux marchand ? Était-il un homme, ou un spectre ? Aime-t-il le goût du sucre ? Souffre-t-il d’être prisonnier de l’Abysse ? A-t-il lui aussi vécu un jour à la surface, sous la lumière du soleil ?\nTu n’as pas le temps d’y songer.\nIl faut continuer à combattre. Sans fin.",
          DialogueId = 6201105,
          GUID = "0F8618CA",
          NextDialogue = 6201106,
          RougeTalkActorType = 3,
          Subtitle = "And what of the mysterious Abyssal Merchant? Was he human, or phantom? Does he like the taste of candy? Does it wound him, being bound to this Abyss? Did he once walk in sunlight, in the world above — and live, as you did?\nBut there is no time to linger.\nYou must fight on. Without end."
        },
        [6201106] = {
          ContentFR = "« Adieu, {性别:voyageur lucide|voyageuse lucide} »\n« Que la flamme de ta lanterne ne s’éteigne jamais. »",
          DialogueId = 6201106,
          GUID = "0F8618F4",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "Farewell, level-headed traveller,\" he says. \"May the flame of your Lantern shine ever unceasing upon your path.\""
        },
        [6201201] = {
          ContentFR = "Dernièrement, la lassitude t’accable moins. Tu t’es même {性别:surpris|surprise} à échanger quelques mots avec ces spectres qui rôdent.\nEst-ce ton cœur qui s’endurcit, qui s’engourdit... ou bien le signe avant-coureur d’une chute ?\nQu’importe. Pour l’heure, ton esprit est étrangement léger.",
          DialogueId = 6201201,
          GUID = "0F86288A",
          NextDialogue = 6201202,
          RougeTalkActorType = 3,
          Subtitle = "Lately, the weariness weighs on you less. You even chat with some of the Abyssoids now.\nYou cannot tell if your heart is hardening, growing numb — or if this is the fracture before collapse.\nFor now, at least, you do not feel so bad."
        },
        [6201202] = {
          ContentFR = "« Aujourd’hui, j’ai croisé des adeptes du Sélénisme et du Noctilunisme. »\n« L’un jurait servir la lumière, l’autre les ténèbres. Le plus drôle, c’est que lorsque je leur ai dit que je me fichais de leurs dieux, tous deux ont craché les mêmes insultes. »\n« Et vous ? Croyez-vous en un dieu ? »",
          DialogueId = 6201202,
          GUID = "0F8628B4",
          NextDialogue = 6201203,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"I met two zealots today — one sworn to Selenism, the other to Noclunism.\"\n\"One claimed to serve the light, the other the dark. The irony was this: when you told them you cared nothing for their gods, both spat the same profanities.\"\n\"And you? Do you follow a god?\""
        },
        [6201203] = {
          ContentFR = "« Je sers Fusa. »\nC’est la première fois que le marchand répond à une question sur lui-même.\n« Je prononce Son nom, je loue Sa grâce, je célèbre l’éclat de la Pleine Lune. »",
          DialogueId = 6201203,
          GUID = "0F8628DE",
          NextDialogue = 6201204,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"I serve Fusa." 
For the first time, the Merchant answers a question about himself.
"I speak Her name, hail Her grace, and honour the light of the Full Moon."]]
        },
        [6201204] = {
          ContentFR = "Tu hausses les sourcils — tu t’attendais à quelque chose de plus mystérieux, de plus déroutant.",
          DialogueId = 6201204,
          GUID = "0F862908",
          NextDialogue = 6201205,
          RougeTalkActorType = 3,
          Subtitle = "His words surprise you — you had expected something more arcane, more intriguing."
        },
        [6201205] = {
          ContentFR = "« Donc vous adhérez aux dogmes de l’Orthodoxie Élyséenne ? »\n« Quiconque prie avec ferveur la Déesse de la Pleine Lune serait sauvé, porté par les fils lumineux qu’Elle tisse ? »",
          DialogueId = 6201205,
          GUID = "0F862932",
          NextDialogue = 6201206,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = [[
"So... you believe in all that Elysian Orthodox teaching?
That if you pray devoutly to the Goddess of the Full Moon, She will weave threads of blessing, and draw us from the dark?"]]
        },
        [6201206] = {
          ContentFR = "« Non. Je <H>suis les pas</> de Fusa, mais je ne <H>crois pas</> en Fusa. »\n« J’avais seulement besoin d’un repère sûr, d’un point fixe qui justifie la route que j’ai choisie. »",
          DialogueId = 6201206,
          GUID = "0F86295C",
          NextOptions = {
            [1] = 6201207
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"No. I follow Fusa, but I do not believe in Her.\" \n\"I only needed something — something certain — to justify the path I chose to walk.\""
        },
        [6201207] = {
          ContentFR = "<I>Je ne comprends pas.</>",
          DialogueId = 6201207,
          GUID = "0F862986",
          NextDialogue = 6201208,
          RougeTalkActorType = 2,
          Subtitle = "I don't understand."
        },
        [6201208] = {
          ContentFR = "« Nous devons donner, non prendre. »\n« Aimer, non haïr. »\n« Accueillir, non blesser. »\n« Voilà ce que je crois juste. Mais si je crois à la liberté des consciences, alors je n’ai aucune preuve que ces choix soient justes. »",
          DialogueId = 6201208,
          GUID = "0F8629B0",
          NextDialogue = 6201209,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"We should give, not take."
"We should love, not hate."
"We should embrace, not wound."
"This is what I hold to be right. Yet if I believe in freedom of the human mind, I cannot prove what I believe to be true."]]
        },
        [6201209] = {
          ContentFR = "« Alors j’ai renoncé à la \"liberté\". J’ai placé Fusa au-dessus de tout. Ainsi, ce que je tenais pour juste est devenu vérité — irréfutable, sans faille, affranchie du doute. »\nIl soupire doucement.\n« D’une certaine manière... je suis peut-être celui qui L’offense le plus. »",
          DialogueId = 6201209,
          GUID = "0F8629DA",
          NextDialogue = 6201210,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"So I cast aside 'freedom' and chose Fusa, who achieves utmost transcendence. In that way, what I held as right became truth — flawless, unquestioned, beyond the need of proof.\"\nHe lets out a sigh.\n\"In a sense... perhaps I am Her ultimate transgressor.\""
        },
        [6201210] = {
          ContentFR = "« Donc... ce que vous dites, c’est que... »\n« Si je voulais me convaincre d’avancer encore dans cet Abysse, je pourrais inventer un... dieu de la marche, juste pour me persuader de continuer ? »",
          DialogueId = 6201210,
          GUID = "0F862A04",
          NextDialogue = 6201211,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"So what you're saying is...\" \nYou search for words. \n\"If I wanted to keep pressing on in this Abyss, I might as well invent a... god of walking — just to convince myself I must go on?\""
        },
        [6201211] = {
          ContentFR = "Le marchand rit doucement.\n« Hmm... tu pourrais le voir ainsi. »",
          DialogueId = 6201211,
          GUID = "0F862A2E",
          NextOptions = {
            [1] = 6201212
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"Mmm... You could say that." 
He chuckles softly.]]
        },
        [6201212] = {
          ContentFR = "Tu secoues la tête.\n« Vous êtes décidément un être à part... mais j’ai déjà trop traîné. Il est temps de partir. »",
          DialogueId = 6201212,
          GUID = "0F862A58",
          IsKeyOption = true,
          NextDialogue = 6201213,
          RougeTalkActorType = 2,
          Subtitle = "What a kook. But I've lingered too long. I should be on my way."
        },
        [6201213] = {
          ContentFR = "« Adieu, {性别:voyageur avisé|voyageuse avisée} »\n« Que la flamme de ta lanterne ne s’éteigne jamais. »",
          DialogueId = 6201213,
          GUID = "0F862A82",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Farewell, wise traveller,\" he says. \"May the flame of your Lantern shine ever unceasing upon your path.\""
        },
        [6201301] = {
          ContentFR = "« Je n’ai pas fermé l’œil depuis longtemps. »\nTu y pensais déjà en venant : cette fois, ta requête serait particulière.\n« Pourrais-je vous acheter quelque chose... un rêve ? »\n« Si c’est en votre pouvoir. »",
          DialogueId = 6201301,
          GUID = "0F8638F2",
          NextDialogue = 6201302,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"It has been long since last I rested.\"\nYou've already planned the trade before you come here.\n\"Could I buy something from you — a dream?\"\n\"If such a thing is possible.\""
        },
        [6201302] = {
          ContentFR = "« Je ne suis pas un tisseur de rêves. Je ne puis promettre qu’il soit tel que tu le désires. »\nIl secoue lentement la tête.\n« Mais je peux essayer. »\n« Autrefois, quand je racontais des histoires à ma petite sœur, elle dormait toujours d’un sommeil paisible. »",
          DialogueId = 6201302,
          GUID = "0F86391C",
          NextDialogue = 6201303,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"I am no dream-weaver. I cannot promise it will be what you seek."
He shakes his head slowly.
"But perhaps I may try."
"Long ago, when I told stories to my little sister, she would always sleep well."]]
        },
        [6201303] = {
          ContentFR = "Tu amasses un peu de paille, la disposes tant bien que mal.\nLa fatigue retombe sur toi comme une chape. Tu désires un rêve, une halte, ne serait-ce qu’un instant.",
          DialogueId = 6201303,
          GUID = "0F863946",
          NextDialogue = 6201304,
          RougeTalkActorType = 3,
          Subtitle = "You gather a heap of straw, softening it as best you can.\nWeariness settles over you once more. You yearn for a dream — for just a brief rest."
        },
        [6201304] = {
          ContentFR = "« Il était une fois, » dit-il, « un jeune orfèvre, qui tomba amoureux de la Lune. »\n« En secret, il en mesura les contours, projetant de forger un collier avec les plus précieuses gemmes, et de l’offrir à la lune croissante qu’il chérissait. »\n« Mais lorsque l’ouvrage fut achevé, la Lune avait grandi — le collier ne lui allait plus. Alors il recommença, sertissant toutes les pierres qu’il possédait. Mais lorsqu’il leva les yeux, la Lune avait encore enflé — pleine et ronde comme un plat d’argent. »",
          DialogueId = 6201304,
          GUID = "0F863970",
          NextDialogue = 6201305,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Once upon a time,\" he said, \"there was a boy — a young goldsmith — who fell in love with the Moon.\"\n\"In secret he measured her shape and size, planning to forge a necklace from the finest gems the world could offer — a gift for the crescent Moon he adored.\"\n\"But when the work was done, the Moon had grown rounder, and the necklace no longer fit.\"\n\"So he began again, setting every jewel he had ever gathered. Yet when he returned, the Moon was rounder still — full as a silver dish upon the sky.\""
        },
        [6201305] = {
          ContentFR = "Tu reconnais ce conte. Ta mère te l’avait déjà narré, autrefois.\nLe sommeil t’envahit, tiède et doux.",
          DialogueId = 6201305,
          GUID = "0F86399A",
          NextDialogue = 6201306,
          RougeTalkActorType = 3,
          Subtitle = [[
It is an old fairytale. You dimly recall your mother once telling it to you.
Sleep begins to drift over you.]]
        },
        [6201306] = {
          ContentFR = "« ... Alors, songea l’orfèvre, je forgerai trois colliers, de tailles différentes. L’un d’eux, au moins, lui ira. »\n« Mais quand il revint vers l’astre aimé, la Lune avait disparu. »\n« Le ciel n’était plus que ténèbres, piquetées d’étoiles. Comme si la Lune n’avait jamais existé. »",
          DialogueId = 6201306,
          GUID = "0F8639C4",
          NextDialogue = 6201307,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"'Then I shall make three necklaces in different sizes,' thought the goldsmith. 'Surely one will fit her.'\"\n\"But when he brought his offerings to the Moon he loved,\nshe was gone.\"\n\"The sky lay black, with only stars upon it — as if the Moon had never been there at all.\""
        },
        [6201307] = {
          ContentFR = "Tu sombres dans un rêve argenté.",
          DialogueId = 6201307,
          GUID = "0F8639EE",
          NextDialogue = 6201308,
          RougeTalkActorType = 3,
          Subtitle = "You sink into a moonlit dream."
        },
        [6201308] = {
          ContentFR = "« ... Ainsi, l’orfèvre qui avait perdu la Lune frappa le métal jour après jour, forgeant des colliers que jamais nul ne porterait. » \n« Ses larmes tombèrent sur la terre — et de ces larmes naquirent des arbres de cristal, dont les fruits brillaient comme la Lune disparue. » \n« Avec le temps, les mortels les appelèrent Arbres Célestes, et les fruits, Phoxènes... »\n« {性别:Voyageur fatigué|Voyageuse fatiguée}... dors-tu déjà ? Alors dors bien, et rêve en paix. »",
          DialogueId = 6201308,
          GUID = "0F863A18",
          NextDialogue = 6201309,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"...And so the goldsmith who had lost the Moon struck his hammer day after day, forging necklaces that would never be worn."
"His tears fell upon the earth, and from them grew glittering trees, heavy with fruit, each one shining like the Moon he loved."
"In time, people named the trees Heaventree, and the fruit Phoxene..."
"Weary traveller... have you drifted off? Sweat dreams, then."]]
        },
        [6201309] = {
          ContentFR = "Premier rêve : une balançoire se balance dans le jardin d’une cour.\nTu es redevenu enfant. Le vieux majordome t’attend, bras ouverts, prêt à t’accueillir.\n« Bienvenue chez toi, mon ▇▇. »\n...",
          DialogueId = 6201309,
          GUID = "0F863A42",
          NextDialogue = 6201310,
          RougeTalkActorType = 3,
          Subtitle = "In your first dream, a swing drifts in a garden courtyard. \nYou are small again. The old butler stands beside it, arms open, waiting for you to run into them. \n\"Welcome back, my ▇▇.\" \n..."
        },
        [6201310] = {
          ContentFR = "Deuxième rêve : de jeunes chevaliers se tiennent sur une colline où fleurit le thym.\nIls brandissent l’étendard à l’iris d’or, leurs chevelures fouettées par le vent. Ils rient, ils crient ton nom.\n« En avant, mon seigneur ▇▇ ! »",
          DialogueId = 6201310,
          GUID = "0F863A6C",
          NextDialogue = 6201311,
          RougeTalkActorType = 3,
          Subtitle = "In the second dream, young knights stand upon a hillside of blooming thyme.\nThey raise a banner of golden iris; their hair streams in the wind as they call your name, smiling.\n\"Let us set out, Lord ▇▇.\" \n..."
        },
        [6201311] = {
          ContentFR = "Troisième rêve : tu aperçois {性别:un autre voyageur|une autre voyageuse}, portant une lanterne semblable à la tienne. Tu l’as croisé trois fois déjà.\nSa silhouette s’éloigne, s’efface dans les ténèbres.\nTu cours de toutes tes forces, haletant.",
          DialogueId = 6201311,
          GUID = "0F863A96",
          NextDialogue = 6201312,
          RougeTalkActorType = 3,
          Subtitle = "In the third dream, you see another traveller — carrying a lantern like yours. You have seen {性别：him|her} three times now.\n{性别：His|Her} figure drifts farther and farther, fading into the dark.\nYou run, heart pounding, chasing with all your strength."
        },
        [6201312] = {
          ContentFR = "« Reste ! »\nTa voix rauque tremble de détresse, plus encore que dans tes combats.",
          DialogueId = 6201312,
          GUID = "0F863AC0",
          NextDialogue = 6201313,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = [[
"Could you stay?"
Your hoarse cry is more desperate than in any battle.]]
        },
        [6201313] = {
          ContentFR = "« Je suis {性别:désolé|désolée}, ▇▇. »\n{性别:Le voyageur|La voyageuse} se retourne, mais la flamme vacillante de sa lanterne ne révèle pas son visage.\n« Nos routes vont en <H>sens inverse</>. Alors je dois partir. »",
          DialogueId = 6201313,
          GUID = "0F863AEA",
          NextDialogue = 6201314,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char02",
          Subtitle = "\"I'm sorry, ▇▇.\"\n{性别：He|She} turns, the lantern's flame wavering across {性别：his|her} face — yet you cannot see it clearly.\n\"Our paths run in opposite directions. That's why... I have to go.\""
        },
        [6201314] = {
          ContentFR = "« Mais... je ne veux plus être seul ! »\nTu tends la main, comme un enfant réclamant la dernière friandise. Tu n’attrapes que le vide.\nEt tu pleures. Depuis combien de temps n’avais-tu pas pleuré ?",
          DialogueId = 6201314,
          GUID = "0F863B14",
          NextDialogue = 6201315,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"But — I don't want to be alone anymore!\" \nYou reach for the hem of {性别：his|her} coat — like a petulant child begging for the last piece of candy — but catch only air.\nTears spill down your cheeks. How long has it been since you last cried?"
        },
        [6201315] = {
          ContentFR = "« Ne pleure pas, ▇▇. »\nSa main effleure ta joue, essuie tes larmes avec une douceur infinie. Tu sens son souffle, la chaleur d’un être vivant.\n« Nos routes forment <H>un cercle</>. Même si nos pas suivent des chemins opposés, nous nous retrouverons. »",
          DialogueId = 6201315,
          GUID = "0F863B3E",
          NextDialogue = 6201316,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char02",
          Subtitle = "\"Don't cry, ▇▇.\"\n{性别：He|She} brushes your cheek, tender and merciful, wiping your tears away. You feel {性别：his|her} breath — the unmistakable warmth of another human.\n\"Our journey is a circle. Even walking in opposite directions, we are bound to meet again.\""
        },
        [6201316] = {
          ContentFR = "Sa lanterne s’illumine d’un éclat argenté — plus vif, toujours plus vif, comme une pleine lune versant ses rayons.\n{性别:Il|Elle} s’avance dans cette lumière aveuglante.\n...\n...\nTu t’éveilles au parfum de menthe sauvage.",
          DialogueId = 6201316,
          GUID = "0F863B68",
          NextDialogue = 6201317,
          RougeTalkActorType = 3,
          Subtitle = "You see the lantern in {性别：his|her} hand begin to glow with silver-white radiance — brighter, ever brighter, like a full moon casting its silver threads of light...\nAnd {性别：he|she} steps into the blinding silver glow.\n...\n...\nYou wake to the scent of wild mint."
        },
        [6201317] = {
          ContentFR = "« Était-ce un beau rêve ? »",
          DialogueId = 6201317,
          GUID = "0F863B92",
          NextDialogue = 6201318,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"Was it a sweet dream?\""
        },
        [6201318] = {
          ContentFR = "« Oui... il était si long. Comme si des années avaient passé. »",
          DialogueId = 6201318,
          GUID = "0F863BBC",
          NextDialogue = 6201319,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"Yes... it felt long. As though many years had passed.\""
        },
        [6201319] = {
          ContentFR = "« Tant mieux. Tu as encore la chance de pouvoir rêver. »",
          DialogueId = 6201319,
          GUID = "0F863BE6",
          NextDialogue = 6201320,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = "\"That's good. You are fortunate still, to be able to dream.\""
        },
        [6201320] = {
          ContentFR = "Tu te relèves, serrant la lanterne. Ton combat reprend — une route sans fin, une solitude sans rivage.",
          DialogueId = 6201320,
          GUID = "0F863C10",
          NextOptions = {
            [1] = 6201321
          },
          RougeTalkActorType = 3,
          Subtitle = "You rise, Lantern in hand. Your battle continues — an endless, solitary road."
        },
        [6201321] = {
          ContentFR = "« Merci. Je dois y aller. »",
          DialogueId = 6201321,
          GUID = "0F863C3A",
          IsKeyOption = true,
          NextDialogue = 6201322,
          RougeTalkActorType = 2,
          Subtitle = "Thank you. I should be going."
        },
        [6201322] = {
          ContentFR = "« Adieu, {性别:voyageur endurant|voyageuse endurante} »\n« Puisse venir un jour où ton chemin ne soit plus solitaire. »",
          DialogueId = 6201322,
          GUID = "0F863C64",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01",
          Subtitle = [[
"Farewell, steadfast traveller," he says.
"May there come a day when you no longer walk this road alone."]]
        },
        [6201401] = {
          ContentFR = "Ténèbres... ténèbres... ténèbres plus profondes encore.\nTu dérives, englouti sous les eaux immobiles, porté toujours plus bas par un fleuve sans fin.",
          DialogueId = 6201401,
          GUID = "0F86495A",
          NextDialogue = 6201402,
          RougeTalkActorType = 3,
          Subtitle = "Darkness... darkness... and darkness yet deeper—\nYou drift in silence, submerged beneath still waters,\ncarried ever downward along a river without end."
        },
        [6201402] = {
          ContentFR = [[
Puis, de loin, une lueur approche.
Une <H>lanterne</>.]],
          DialogueId = 6201402,
          GUID = "0F864984",
          NextDialogue = 6201403,
          RougeTalkActorType = 3,
          Subtitle = [[
And then, from afar, a light begins to draw near.
It is a Lantern.]]
        },
        [6201403] = {
          ContentFR = "« Tu es revenu. Je le savais... tu reviendrais. »\nLa flamme tremblante éclaire son visage ridé.",
          DialogueId = 6201403,
          GUID = "0F8649AE",
          NextOptions = {
            [1] = 6201404
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01",
          Subtitle = "\"You have returned. I always knew you would.\"\nThe flickering flame reveals the face of its bearer — an aged woman."
        },
        [6201404] = {
          ContentFR = "<I>Vous me connaissez ?</>",
          DialogueId = 6201404,
          GUID = "0F8649D8",
          NextDialogue = 6201405,
          RougeTalkActorType = 2,
          Subtitle = "Do you know me?"
        },
        [6201405] = {
          ContentFR = "« Oui. »\nSes yeux voilés brillent soudain, comme du bois mort où renaît une fleur.\n« Je t’ai attendu... si longtemps. »",
          DialogueId = 6201405,
          GUID = "0F864A02",
          NextOptions = {
            [1] = 6201406
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01",
          Subtitle = [[
"Yes."
Her clouded eyes kindle with light, like dead wood bursting into bloom.
"I have waited for you... for a very, very long time."]]
        },
        [6201406] = {
          ContentFR = "<I>Je crois avoir oublié qui je suis.</>",
          DialogueId = 6201406,
          GUID = "0F864A2C",
          NextDialogue = 6201407,
          RougeTalkActorType = 2,
          Subtitle = "I can't remember who I am."
        },
        [6201407] = {
          ContentFR = "« Le chemin que nous parcourons est <H>un cercle</>. »\nElle sourit.\n« Maintenant que tu es revenu ici, tout ce que tu avais oublié va te revenir. »",
          DialogueId = 6201407,
          GUID = "0F864A56",
          NextOptions = {
            [1] = 6201408
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01",
          Subtitle = "\"The path we walk is a circle.\"\nShe smiles.\n\"And now that you've come full circle — all you have forgotten shall soon return.\""
        },
        [6201408] = {
          ContentFR = "<I>Que dois-je faire, désormais ?</>",
          DialogueId = 6201408,
          GUID = "0F864A80",
          NextDialogue = 6201409,
          RougeTalkActorType = 2,
          Subtitle = "What should I do next?"
        },
        [6201409] = {
          ContentFR = "« Quitte cet endroit. Quitte l’<H>Abysse</>. C’est le vœu de <H>tous les toi</> qui ont foulé ce chemin. »\nElle te tend la lanterne. Ses doigts sont glacés, presque fantomatiques. Mais la flamme, elle, rayonne d’un or chaud et brûlant.\nTu remarques sur son cadre un cadran gravé de fines <H>graduations</>.",
          DialogueId = 6201409,
          GUID = "0F864AAA",
          NextOptions = {
            [1] = 6201410
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01",
          Subtitle = "\"Leave this place. Leave the Abyss. That has ever been the wish of every you that has ever walked this path.\"\nShe places the Lantern in your hands. Her fingers are cold as a ghost's — yet the Lantern burns golden, bright, and warm.\nSet into its frame is a dial, etched with fine gradations."
        },
        [6201410] = {
          ContentFR = "<I>Comment puis-je quitter cet endroit ?</>",
          DialogueId = 6201410,
          GUID = "0F864AD4",
          IsKeyOption = true,
          NextDialogue = 6201411,
          RougeTalkActorType = 2,
          Subtitle = "How can I leave this place?"
        },
        [6201411] = {
          ContentFR = "« Cette lanterne porte la bénédiction des dieux. »\n« Restaure-la avec assez de <H>Lumistella</>, et elle ouvrira une voie dans l’océan de l’Abysse.\n« Et si jamais tu fais face à un péril mortel... alors <H>retourne</> le cadran. »",
          DialogueId = 6201411,
          GUID = "0F864AFE",
          NextDialogue = 6201412,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01",
          Subtitle = [[
"This Lantern carries a divine blessing."
"Restore it with enough Pure Glazeystal, and it shall part the depths of the Abyss, opening a path before you."
"Should you face mortal peril... turn the dial in reverse."]]
        },
        [6201412] = {
          ContentFR = "Elle sourit encore, silencieuse et sereine.\n« Avant de partir, peut-être veux-tu entendre encore quelques histoires de l’Abysse. »\n« Elles sont comme des éclats de bois flottant sur le fleuve du temps. »\n« Je te l’ai dit : notre chemin est un cercle. Ces récits sont peut-être ton \"passé\"... peut-être ton \"avenir\". »\n« Mais sans doute possible : <H>ce sont tes histoires</>. »",
          DialogueId = 6201412,
          GUID = "0F864B28",
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01",
          Subtitle = "\"Before you set out, perhaps you would like to hear a tale or two of this Abyss.\"\nShe smiles again, serene and still.\n\"These are but fragments — driftwood upon the river of time. As I have told you, the path we tread is a circle. To you, these stories may be of your 'past'... or of your 'future'.\"\n\"Yet this much is certain: they are your stories.\""
        },
        [6201501] = {
          ContentFR = "Des pas résonnent dans l’obscurité — lourds, traînants, finissant en un frottement râpeux.\nTu avances vers la source. Quatre silhouettes se dessinent : les chevaliers du Crépuscule Silencieux. Vos routes se croisent à nouveau. Ils ne portent pas de blessures, mais leurs visages n’ont plus rien de la lumière qui les animait lors de votre dernière rencontre.",
          DialogueId = 6201501,
          GUID = "0F8659C2",
          NextDialogue = 6201502,
          RougeTalkActorType = 3,
          Subtitle = "Footsteps echo in the dark — dull, dragging, tapering into a gritty scrape.\nYou follow the sound. Four figures emerge at last: the Knights of Hushed Dusk. Your paths cross again. They stand unscathed, yet their faces bear none of the light they wore when last you met."
        },
        [6201502] = {
          ContentFR = "« Nous devons encore marcher ? Combien de temps a-t-on déjà erré ainsi ? »\nLa voix de la sorcière est saturée de fatigue, comme si la cape sur ses épaules était une dalle de pierre.",
          DialogueId = 6201502,
          GUID = "0F8659EC",
          NextDialogue = 6201503,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = [[
"Are we truly still walking...? How long has it been?"
The Sorceress's voice hangs heavy with fatigue, as if the cloak on her shoulders were a slab of stone.]]
        },
        [6201503] = {
          ContentFR = "« Quatre jours... cinq, peut-être ? Ou davantage... Ma montre de poche s’est arrêtée. »\nSa voix râpe comme une lame sur du papier effiloché. Même un prêtre aussi fervent que lui n’arrive plus à préserver sa ferveur habituelle.",
          DialogueId = 6201503,
          GUID = "0F865A16",
          NextDialogue = 6201504,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton",
          Subtitle = [[
"Four days... five, perhaps... longer still. My pocket watch has stopped."
The Priest's voice rasps like a blade on frayed paper. Even a man of faith can no longer summon his usual reverence.]]
        },
        [6201504] = {
          ContentFR = "« Puisque nous sommes tous épuisés, arrêtons-nous ici. Dormez un peu. Je veillerai. »\nLe jeune homme propose avec douceur, bien que sa propre voix trahisse la lassitude.",
          DialogueId = 6201504,
          GUID = "0F865A40",
          NextDialogue = 6201505,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton",
          Subtitle = "\"Then let's stop here a while. You can rest — I'll keep watch.\"\nThe young man speaks with quiet care for his companions, though weariness seeps into his words."
        },
        [6201505] = {
          ContentFR = "« Je reste avec toi ! Comme ça, si l’un de nous s’assoupit, l’autre pourra le réveiller. »\nElle force la légèreté, et d’un regard, l’empêche de murmurer ses excuses.",
          DialogueId = 6201505,
          GUID = "0F865A6A",
          NextDialogue = 6201506,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy",
          Subtitle = [[
"I'll keep watch with you. If either of us drifts off, the other can wake them!"
She presses false brightness into her tone, cutting Flynn short with a glance before he can whisper an apology.]]
        },
        [6201506] = {
          ContentFR = "Ils déposent leurs sacs sur un sol à peu près plat, improvisant un camp rudimentaire. Tandis que Calista et Milton s’allongent, Flynn et Cathy s’écartent un peu. \nLe silence s’accroche à leurs dos, comme une image figée. \nFlynn baisse la tête, soupirant à voix basse — si bas que seule Cathy l’entend.",
          DialogueId = 6201506,
          GUID = "0F865A94",
          NextDialogue = 6201507,
          RougeTalkActorType = 3,
          Subtitle = [[
They find a patch of level ground, set down their packs, and make a rough camp.
Once Calista and Milton have lain down, Flynn and Kathy wander a short distance aside. Silence drapes across their backs, the moment frozen like a still frame.
Flynn lowers his head and sighs softly, a breath so low it reaches no ears but Kathy's.]]
        },
        [6201507] = {
          ContentFR = "« Tiens donc... rare de t’entendre soupirer. »\nSouriante, elle sort un petit paquet froissé.\n« Tu veux un bonbon ? J’en ai fait passer en cachette. Il n’en reste que deux. On partage. »",
          DialogueId = 6201507,
          GUID = "0F865ABE",
          NextDialogue = 6201508,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy",
          Subtitle = "\"Aww, it's rare to hear you sigh.\" Smiling, she pulls a crumpled paper packet from her pocket. \"Candy? I smuggled these in. Just two left — let's share them.\""
        },
        [6201508] = {
          ContentFR = "« ... Non, merci. Tu les aimes, garde-les. »",
          DialogueId = 6201508,
          GUID = "0F865AE8",
          NextDialogue = 6201509,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = "\"...No, thank you. You've a sweet tooth. Best you keep them.\""
        },
        [6201509] = {
          ContentFR = "« C’est toujours meilleur quand on partage avec un ami. »",
          DialogueId = 6201509,
          GUID = "0F865B12",
          NextDialogue = 6201510,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy",
          Subtitle = "\"Candy's always sweeter when you share it with a friend.\""
        },
        [6201510] = {
          ContentFR = "Elle croque un bonbon, puis glisse l’autre — encore emballé — dans la main de Flynn.\nIl reste muet, la tête basse. \nElle attend, silencieuse, laissant fondre le bonbon sur sa langue, le temps qu’il trouve ses mots.",
          DialogueId = 6201510,
          GUID = "0F865B3C",
          NextDialogue = 6201511,
          RougeTalkActorType = 3,
          Subtitle = "She slips one into her mouth, then presses the last piece — wrapper and all — into Flynn's hand. He only lowers his head in silence, unmoving.\nSo she waits, saying no more, letting the candy melt on her tongue as she waits for her friend to collect his thoughts and find his words."
        },
        [6201511] = {
          ContentFR = "« As-tu vu... cet Umbré, l’épée à la main ? »\nEnfin, le jeune homme rompt le silence, la voix basse.",
          DialogueId = 6201511,
          GUID = "0F865B66",
          NextDialogue = 6201512,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = [[
"Did you see it... that Abyssoid, the one with the sword?"
At last, Flynn speaks in a low voice.]]
        },
        [6201512] = {
          ContentFR = "« Celui qui frappait tout, même les siens ? Bien sûr que je l’ai vu ! Sa lame d’argent brillait comme dans les légendes... comme celle de ton idole... »\nElle s’interrompt, le regard soudain fixé sur Flynn.\n« Dis-moi pas que c’était... le <H>Chevalier de l’Aube Lunaire</> ? »",
          DialogueId = 6201512,
          GUID = "0F865B90",
          NextDialogue = 6201513,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy",
          Subtitle = "\"You mean the one who cut down everything — even his own kind? Of course I saw him. That silver sword of his was so bright it near blinded me. It was just like the weapon your idol bore in the tales...\"\nShe falters, turning to Flynn.\n\"Wait... you don't mean — the Moonrise Knight?\""
        },
        [6201513] = {
          ContentFR = "« ... Oui. C’était lui. Je connais son visage, ses portraits, ses gravures... Je ne pouvais me tromper. »\nIl enfouit son visage entre ses mains.\n« Et quand je l’ai reconnu... j’ai eu peur. Si même lui a succombé à l’Abysse... alors nous ? Et si moi aussi, un jour, je tournais mon épée contre mes camarades ? »",
          DialogueId = 6201513,
          GUID = "0F865BBA",
          NextDialogue = 6201514,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = [[
"...Yes. It was him. I've pored over his likeness a thousand times, in portraits and illustrations. I could never mistake him."
The young man exhales, burying his face in his hands.
"Truth is... the moment I recognised him, I was scared. If even he could be overcome by the Abyss... what chance have we? And what if that's how I fall as well? What if one day I turn my blade... on those I call comrades?"]]
        },
        [6201514] = {
          ContentFR = "Elle lui tapote doucement le dos.\n« C’est vrai, l’Abysse est plus terrible que tout ce qu’on imaginait... Mais je crois que la volonté humaine peut l’emporter. »\nSon sourire s’adoucit.\n« Réfléchis : il frappait même les autres Umbrés. Cela ne veut-il pas dire qu’il résistait encore ? Même changé, il se souvenait de son but premier. »",
          DialogueId = 6201514,
          GUID = "0F865BE4",
          NextDialogue = 6201515,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy",
          Subtitle = "\"Yeah... we never imagined the Abyss would be so terrifying. But even so, I believe — whatever comes — the will of humankind can endure it.\"\nKathy pats her friend's back, gentle yet firm.\n\"Think of it. That Knight struck at even other Abyssoids. Doesn't that mean he hadn't yielded? Even in a ghostly form, he still clung to his first purpose — didn't he?\""
        },
        [6201515] = {
          ContentFR = "« Mmh... »",
          DialogueId = 6201515,
          GUID = "0F865C0E",
          NextDialogue = 6201516,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = "\"Mm...\""
        },
        [6201516] = {
          ContentFR = "Tu détournes le regard, décidé à les laisser en paix. Mais Cathy t’aperçoit.",
          DialogueId = 6201516,
          GUID = "0F865C38",
          NextDialogue = 6201517,
          RougeTalkActorType = 3,
          Subtitle = [[
This does not feel the moment to intrude, and you mean to leave them their brief reprieve.
But as you turn away, Kathy catches sight of you.]]
        },
        [6201517] = {
          ContentFR = "« Oh ! C’est vous, {性别:le voyageur|la voyageuse} d’avant ! Quelle chance, vous êtes {性别:sain et sauf|saine et sauve} ! »",
          DialogueId = 6201517,
          GUID = "0F865C62",
          NextDialogue = 6201518,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy",
          Subtitle = "\"Huh!?\" She brightens, rushing over. \"You're that traveller from before! I can't believe it — you're safe! That's great!\""
        },
        [6201518] = {
          ContentFR = "Flynn s’approche, surpris.\n« Vous n’êtes pas {性别:un homme|une femme} ordinaire. Vous êtes entré dans l’Abysse avant nous... Comment avez-vous gardé une volonté si ferme ? »",
          DialogueId = 6201518,
          GUID = "0F865C8C",
          NextOptions = {
            [1] = 6201519
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = "Flynn follows, surprise plain upon his face.\n\"So it's true — you're no ordinary soul. You entered the Abyss before us... How have you endured so long?\""
        },
        [6201519] = {
          ContentFR = "<I>{性别:Je m’y suis simplement accoutumé.|Je m’y suis simplement accoutumée.}</>",
          DialogueId = 6201519,
          GUID = "0F865CB6",
          NextDialogue = 6201527,
          RougeTalkActorType = 2,
          Subtitle = "I... just grew used to it."
        },
        [6201520] = {
          ContentFR = "Flynn hoche la tête, admiratif.\n« Alors... dites-moi. Pensez-vous que nous vaincrons l’Abysse ? »",
          DialogueId = 6201520,
          GUID = "0F865CE0",
          NextOptions = {
            [1] = 6201521,
            [2] = 6201524
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = "His surprise softens slowly into admiration.\n\"Then tell me — how do you see the Abyss? Do you believe mankind can prevail?\""
        },
        [6201521] = {
          ContentFR = "<I>Oui.</>",
          DialogueId = 6201521,
          GUID = "0F865D0A",
          IsKeyOption = true,
          NextDialogue = 6201522,
          RougeTalkActorType = 2,
          Subtitle = "We will."
        },
        [6201522] = {
          ContentFR = "« Tu vois ? Même le voyageur le croit. On réussira notre mission. Alors reprends courage ! »",
          DialogueId = 6201522,
          GUID = "0F865D34",
          NextDialogue = 6201523,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy",
          Subtitle = "\"See? Even the traveller believes it. We'll finish this mission. So chin up, all right?\""
        },
        [6201523] = {
          ContentFR = "Mais elle se trompe.\nLa \"victoire\" à laquelle tu crois n’est pas celle que l’Église leur a assignée.\nTu sais trop bien ce qui les attend : douleur et désespoir, encore et encore.\nIls mourront mille fois sans jamais savoir qu’ils vivent déjà en enfer.\nTu ne dis rien pourtant.\nSi l’avenir ne peut être changé... alors peut-être que l’ignorance est une forme de grâce.",
          DialogueId = 6201523,
          GUID = "0F865D5E",
          RougeTalkActorType = 3,
          Subtitle = [[
But she misunderstands you. The "triumph" you hold to is not the mission laid upon them by the Church.
You know too well: only pain and despair await them. Again and again they will fall, never knowing they already tread in hell.
Yet you say nothing. If the future cannot be altered, perhaps ignorance is mercy enough.]]
        },
        [6201524] = {
          ContentFR = "<I>Je... je ne sais pas.</>",
          DialogueId = 6201524,
          GUID = "0F865D88",
          IsKeyOption = true,
          NextDialogue = 6201525,
          RougeTalkActorType = 2,
          Subtitle = "I'm not sure."
        },
        [6201525] = {
          ContentFR = "« Même vous... vous n’avez pas cette certitude ? »\nLe regard du jeune homme s’assombrit. Puis, soudain, il se redresse, la voix vibrante d’une résolution fébrile — tu ignores s’il cherche à s’encourager, ou à se mentir.\n« Qu’importe. Nous sommes des chevaliers d’Élysium. Même sans espoir, nous combattrons jusqu’au bout. »",
          DialogueId = 6201525,
          GUID = "0F865DB2",
          NextDialogue = 6201526,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = "\"Even you... cannot say for certain?\"\nThe young man's gaze falters. Yet soon he lifts his head once more, his voice ringing with rekindled resolve — whether to steel himself or to deceive himself, you cannot tell.\n\"Still... we are Knights of Elysium. Even if all hope is gone, we will fight to the very end.\""
        },
        [6201526] = {
          ContentFR = "Tu sais trop bien ce qui les attend : douleur et désespoir, encore et encore.\nIls mourront mille fois sans jamais savoir qu’ils vivent déjà en enfer.\nMais face à ses yeux brûlants de conviction, tu n’as pas le cœur de briser son illusion.",
          DialogueId = 6201526,
          GUID = "0F865DDC",
          RougeTalkActorType = 3,
          Subtitle = [[
You know too well: only pain and despair await them. Again and again they will fall, never knowing they already tread in hell. 
Yet when you meet the Knight's unwavering eyes, you cannot bring yourself to speak the cruel truth.]]
        },
        [6201527] = {
          ContentFR = "<I>{性别:J’ai été perdu, j’ai regretté, j’ai désespéré... mais j’ai fini par accepter.|J’ai été perdue, j’ai regretté, j’ai désespéré... mais j’ai fini par accepter.}</>",
          DialogueId = 6201527,
          GUID = "0F865CB7",
          NextDialogue = 6201520,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = " I've felt lost, regretful, hopeless... but now, I've come to terms with it."
        },
        [6201601] = {
          ContentFR = "Un fracas d’acier jaillit des ténèbres : quelque part devant toi, une bataille fait rage.\nDans l’ombre, tu distingues un jeune chevalier. Rassemblant ses dernières forces, il lève son épée longue et abat l’Umbré qui lui fait face.",
          DialogueId = 6201601,
          GUID = "0F866A2A",
          NextDialogue = 6201602,
          RougeTalkActorType = 3,
          Subtitle = [[
A sharp clash of steel rings out in the darkness. Somewhere ahead, a battle rages.
Through the gloom you glimpse a young Knight, longsword lifted with what strength remains, striking down the Abyssoid before him.]]
        }
      }
    end
  },
  {
    MinKey = 6201602,
    MaxKey = 10011707,
    Loader = function()
      return {
        [6201602] = {
          ContentFR = "Soudain, une ombre file. D’instinct, il brandit son bouclier — une flèche s’y plante. Il se fige : l’empennage porte l’iris doré d’Élysium, mais taché de noir. Une seule archère pouvait décocher cela.",
          DialogueId = 6201602,
          GUID = "0F866A54",
          NextDialogue = 6201603,
          RougeTalkActorType = 3,
          Subtitle = "Then — a slim shadow sweeps past. By instinct he raises his shield, catching the strike. An arrow juts from the cracked wood. When he sees it clearly, he freezes.\nIts fletching bears the golden Iris of Elysium — but the base is stained black. There is only one archer who would do that..."
        },
        [6201603] = {
          ContentFR = "« Calista... ? »",
          DialogueId = 6201603,
          GUID = "0F866A7E",
          NextDialogue = 6201604,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = "\"Calista...?\""
        },
        [6201604] = {
          ContentFR = "L’Umbré avance, muet, ses membres rongés par l’obscurité se fondant déjà dans sa cape. À l’appel de Flynn, \"elle\" ne répond pas, bandant une nouvelle fois son arc.",
          DialogueId = 6201604,
          GUID = "0F866AA8",
          NextDialogue = 6201605,
          RougeTalkActorType = 3,
          Subtitle = "The Abyssoid presses closer, its limbs gnawed by the darkness, until they seem to blur into the cloak that shrouds it. \"She\" gives no answer to Flynn's call — only draws the bowstring taut once more."
        },
        [6201605] = {
          ContentFR = "Depuis leurs premiers pas dans l’Abysse, ils ont découvert, horrifiés, que nombre des silhouettes hostiles leur étaient familières. Anciens chevaliers d’Élysium, partis jadis combattre l’Abysse, et qui, après leur mort, furent absorbés, changés en ombres, dressés contre leurs propres compagnons.",
          DialogueId = 6201605,
          GUID = "0F866AD2",
          NextDialogue = 6201606,
          RougeTalkActorType = 3,
          Subtitle = "From their very first steps into the Abyss, they are horrified to see familiar figures among the hostile, human-like Abyssoids. Many were once Knights of Elysium, who had marched here to bring down the Abyss — only to be claimed by it in death, reborn as part of its darkness, and set against their former comrades."
        },
        [6201606] = {
          ContentFR = "C’est là la plus cruelle des malédictions de l’Abysse : vivre est déjà une condamnation. Ceux qui meurent vite deviennent des spectres ordinaires, reflets de leur vie passée. ",
          DialogueId = 6201606,
          GUID = "0F866AFC",
          NextDialogue = 6201607,
          RougeTalkActorType = 3,
          Subtitle = "This is the Abyss's cruellest curse: to live is itself a curse. Those who fall swiftly may still become mere phantoms, resembling what they were in life."
        },
        [6201607] = {
          ContentFR = "Mais ceux qui persistent, refusant de tomber... chaque seconde qui s’écoule les ronge davantage. Le moindre doute, une seule faille dans leur volonté, et les ténèbres s’emparent de leur esprit, les transformant en bêtes démentes, réduits à frapper aveuglément.",
          DialogueId = 6201607,
          GUID = "0F866B26",
          NextDialogue = 6201608,
          RougeTalkActorType = 3,
          Subtitle = "But if one refuses to die and struggles on, then every passing moment the darkness gnaws at their will. In the end, each battle becomes a gamble: should their resolve falter even for an instant, the Abyss devours their mind, leaving only a mindless beast driven to slaughter."
        },
        [6201608] = {
          ContentFR = "Comme celle qui se tient maintenant devant Flynn.",
          DialogueId = 6201608,
          GUID = "0F866B50",
          NextDialogue = 6201609,
          RougeTalkActorType = 3,
          Subtitle = "Just like the one who stands before Flynn now."
        },
        [6201609] = {
          ContentFR = "« Non... non, pas toi... je t’en supplie... »\nLes mains crispées sur la garde de son épée commencent à trembler.\n« Milton est déjà tombé... si toi aussi... »",
          DialogueId = 6201609,
          GUID = "0F866B7A",
          NextDialogue = 6201610,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = "\"No... don't do this... I don't want to hurt you... please...\" His hands shake upon the hilt of his sword. \"Milton's already gone. If I lose you too...\""
        },
        [6201610] = {
          ContentFR = "Mais la flèche siffle vers son cœur. Il lève son bouclier. Une seconde flèche passe, lui ouvrant la joue d’un trait de sang.",
          DialogueId = 6201610,
          GUID = "0F866BA4",
          NextDialogue = 6201611,
          RougeTalkActorType = 3,
          Subtitle = "But the arrow comes anyway, swift for his heart. He wrenches up his shield. Another hisses past — slashing his cheek, spilling blood."
        },
        [6201611] = {
          ContentFR = "« Aaaah ! »",
          DialogueId = 6201611,
          GUID = "0F866BCE",
          NextDialogue = 6201612,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = "\"Aaaah—!\""
        },
        [6201612] = {
          ContentFR = "Dans un cri, il lève son épée et frappe — encore, encore, encore — jusqu’à ce que l’Umbré se dissolve enfin en cendres. Vacillant, il s’appuie sur sa lame plantée au sol. Devant ce qu’il reste de son ancienne compagne, il s’effondre, sanglotant à s’en briser la voix.",
          DialogueId = 6201612,
          GUID = "0F866BF8",
          NextDialogue = 6201613,
          RougeTalkActorType = 3,
          Subtitle = "With a cry, he swings his blade — once, twice, again — until the Abyssoid at last dissolves into ash.\nHis body trembles, held up only by the sword. Before the dust that was once his comrade, he breaks, his voice torn by grief, and weeps aloud."
        },
        [6201613] = {
          ContentFR = "Quand les sanglots s’apaisent enfin, un silence étrange retombe. Le combat est bel et bien terminé, pourtant, l’amie qui combattait à ses côtés — cette fille toujours à bondir, bruyante et pleine de vie — ne revient pas, le sourire aux lèvres, comme à l’accoutumée.",
          DialogueId = 6201613,
          GUID = "0F866C22",
          NextDialogue = 6201614,
          RougeTalkActorType = 3,
          Subtitle = "When the weeping finally ebbs, an eerie silence fills the hollow air. The battle is over — yet the girl who once fought beside him, always bounding, always loud and full of life, does not return with her usual grin. Not this time."
        },
        [6201614] = {
          ContentFR = "« Cathy... Cathy ? Tu vas bien ? »\nIl s’avance vers elle en traînant son corps couvert de blessures, chaque pas plus lourd que le précédent.",
          DialogueId = 6201614,
          GUID = "0F866C4C",
          NextDialogue = 6201615,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = [[
"Kathy...? Kathy, are you all right?"
He staggers towards her, dragging his battered body.]]
        },
        [6201615] = {
          ContentFR = "Un silence lourd s’abat. Mais Cathy ne revient pas. Elle reste figée, les bras pendants, haletante comme une noyée. Des volutes sombres s’échappent de ses plaies, s’enroulent à ses membres, noircissent ses cheveux d’or, jusqu’à engloutir son corps tout entier.",
          DialogueId = 6201615,
          GUID = "0F866C76",
          NextDialogue = 6201616,
          RougeTalkActorType = 3,
          Subtitle = [[
She does not seem to hear his call. She stands rooted in place, her arms hanging limp. Her breathing comes in sharp, frantic gasps, as though she were drowning, struggling in vain to hold on to the air.
From her wounds seeps a baleful black mist. It coils about her limbs, darkens her shining hair, and at last devours her whole form.]]
        },
        [6201616] = {
          ContentFR = "Son épée s’écrase dans la boue mêlée de sang et de larmes. Lui-même s’effondre à genoux, brisé.",
          DialogueId = 6201616,
          GUID = "0F866CA0",
          NextDialogue = 6201617,
          RougeTalkActorType = 3,
          Subtitle = "The sword slips from his grasp, sinking into mud mixed with blood and tears. He falls to his knees."
        },
        [6201617] = {
          ContentFR = "« Je... j’abandonne. Tu m’entends ? »\nIl ferme les yeux, la tête levée vers le ciel, si cette profondeur d’ombre peut encore s’appeler un ciel, et sa voix tombe, lisse et immobile comme une eau morte.\n« Qui que tu sois... quelles que soient tes raisons de nous infliger cela... j’en ai assez. Je suis épuisé. C’en est assez. Emporte-moi aussi. »",
          DialogueId = 6201617,
          GUID = "0F866CCA",
          NextDialogue = 6201618,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = "\"I... surrender. Do you hear me?\" \nHe closes his eyes, face upturned to the sky — if such darkness can be called sky. His voice is calm as stagnant water.\n\"Whoever you are... whatever your reason to torment us like this... I am fed up. I am weary. Enough. Take me as well...\""
        },
        [6201618] = {
          ContentFR = "Devant lui, quelque chose rampe dans l’ombre, s’approche. Il ferme les yeux, prêt à accueillir la mort. Mais deux mains soulèvent son épée tombée, et la lui remettent.",
          DialogueId = 6201618,
          GUID = "0F866CF4",
          NextDialogue = 6201619,
          RougeTalkActorType = 3,
          Subtitle = "Something stirs in the dark — rustling, drawing near. He does not open his eyes, simply waits, ready for the end.\nThen — a pair of hands lifts his fallen blade, and presses the hilt back into his grasp."
        },
        [6201619] = {
          ContentFR = "« Tu as donc si peu de foi en moi ? »\nSa voix fend la nuit, douce et claire. Une silhouette efface ses larmes, enlace sa tête penchée, couvre son corps ensanglanté d’une étreinte apaisante.\n« Rassure-toi... quoi qu’il arrive, je ne changerai pas. »",
          DialogueId = 6201619,
          GUID = "0F866D1E",
          NextDialogue = 6201620,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy",
          Subtitle = "\"Really now — have a little more faith in me, won't you?\"\nHer voice cleaves the darkness, gentle, warm. A shadow brushes away his tears, cradles his bowed head, shields his broken form.\n\"Don't worry. Whatever happens... I promise you this — I will not change.\""
        },
        [6201620] = {
          ContentFR = "« ... Oui. Je te crois. »\nIl ouvre les bras, prêt à embrasser l’obscurité elle-même.",
          DialogueId = 6201620,
          GUID = "0F866D48",
          NextDialogue = 6201621,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = [[
"...Yeah. I believe you." 
He lifts his arms, and embraces the dark.]]
        },
        [6201621] = {
          ContentFR = "Tu sais que ce n’est qu’un faux espoir, que cela ne leur apportera que plus de souffrance. \nPourtant tu ne peux t’en empêcher : tu lèves ta lanterne et accours.\nSous la lumière du Lumistella, l’ombre se dissipe. Les cheveux de Cathy reprennent leur éclat doré.\nLes deux chevaliers te fixent, pétrifiés.",
          DialogueId = 6201621,
          GUID = "0F866D72",
          NextDialogue = 6201622,
          RougeTalkActorType = 3,
          Subtitle = "You know it is false hope. You know it can only lead them to greater suffering. And yet — you cannot restrain yourself.\nYou raise your Lantern and rush to their side. In the glow of Glazeystal, the darkness recoils. Her hair, once drowned in shadow, shines golden once more.\nThe two Knights look up at you, dazed."
        },
        [6201622] = {
          ContentFR = "« {性别:Voyageur|Voyageuse}... ? C’est bien vous ? Vous nous avez sauvés ? »\nLa jeune fille contemple ses mains retrouvées intactes, les tournant comme pour s’assurer qu’elles sont bien réelles. L’étonnement se peint sur son visage, presque incrédule.\n« Merci... ! J’ai toujours su que vous n’étiez pas quelqu’un d’ordinaire... mais jamais je n’aurais imaginé que vous portiez une force pareille. »",
          DialogueId = 6201622,
          GUID = "0F866D9C",
          NextDialogue = 6201623,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy",
          Subtitle = "\"Traveller...? Did you save us?\" \nKathy stares at her hands, whole and unblemished. Astonishment lights her eyes.\n\"Thank you...! I always knew you were no ordinary soul — but I never dreamt you held such power.\""
        },
        [6201623] = {
          ContentFR = "« Hah... » souffle Flynn, encore hébété, comme si la scène lui échappait.",
          DialogueId = 6201623,
          GUID = "0F866DC6",
          NextOptions = {
            [1] = 6201624
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = [[
"Hah..." 
Flynn exhales, unsteady, as though still unsure this is real.]]
        },
        [6201624] = {
          ContentFR = "<I>Inutile de me remercier. Dites-moi plutôt : que comptez-vous faire maintenant ?</>",
          DialogueId = 6201624,
          GUID = "0F866DF0",
          IsKeyOption = true,
          NextDialogue = 6201625,
          RougeTalkActorType = 2,
          Subtitle = "No need to thank me. What are your plans from here?"
        },
        [6201625] = {
          ContentFR = "« Continuer, évidemment ! Mais d’abord, soignons Flynn. »",
          DialogueId = 6201625,
          GUID = "0F866E1A",
          NextDialogue = 6201626,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy",
          Subtitle = "\"Now that we're safe? We carry on, of course! But first — Flynn needs some patching up.\""
        },
        [6201626] = {
          ContentFR = "Elle perçoit ton inquiétude, et lui oppose un sourire éclatant.",
          DialogueId = 6201626,
          GUID = "0F866E44",
          NextDialogue = 6201627,
          RougeTalkActorType = 3,
          Subtitle = "She catches the worry in your eyes, and answers it with a bright smile."
        },
        [6201627] = {
          ContentFR = "« Voyageur, vous souvenez-vous de la question que Flynn vous avait posée, la dernière fois que nous nous sommes rencontrés ? Je crois que j’ai enfin trouvé ma réponse. »\nSa voix est calme, assurée, chaque mot pesé.\n« L’Abysse ne sera pas vaincu par une seule bataille, ni par un seul héros. Il sera vaincu par nous tous, par l’accumulation de tous nos efforts. Tant que nous avançons, même d’un pas infime, nous ajoutons notre part à ce combat. »\n« Un jour... un jour, cela finira par changer quelque chose. Alors il n’est pas nécessaire de craindre notre propre fin : ce qui importe, c’est de continuer à avancer, d’apporter ne serait-ce qu’une goutte à l’océan de la victoire finale. »",
          DialogueId = 6201627,
          GUID = "0F866E6E",
          NextDialogue = 6201628,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy",
          Subtitle = "\"Traveller — do you remember the question Flynn asked you last time we met? I think I finally understand.\" Her tone is calm, resolute. \"The Abyss will not be defeated by one battle, nor by some mighty hero. It will be defeated by all of us — by our efforts, joined together. If we keep adding to them, again and again, then one day... something must change. So it doesn't matter how we end. What matters is that we go on. Even the smallest step forward is our share toward that final victory.\""
        },
        [6201628] = {
          ContentFR = "« Cathy... je ne pensais pas t’entendre dire ça. À côté de toi, je parais un bien piètre capitaine. »\nIl reprend ses esprits, se redresse grâce à elle.\n« L’Abysse s’étend sans cesse. Si nous n’agissons pas, il engloutira tout Élysium. Même si ce n’est que pour gagner du temps, nous devons combattre jusqu’au bout. Et nous n’avons pas encore retrouvé Dame Lisbell. »",
          DialogueId = 6201628,
          GUID = "0F866E98",
          NextDialogue = 6201629,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = "\"Heh... Kathy. Never thought I'd hear something so wise from you. Makes me seem a poor captain beside you.\"\nAt last, Flynn regains his senses. With her support, he rises — and straightens his back.\n\"The Abyss spreads with every moment. If left unchecked, it will consume all of Elysium. Even if we can only delay it, we must fight to the end. Besides... we still haven't found Dame Lisbell.\""
        },
        [6201629] = {
          ContentFR = "« Exactement ! Nous devons la ramener avec nous. {性别:Voyageur|Voyageuse}, poursuis ton chemin. Ne prends pas notre fardeau. Reçois seulement notre bénédiction. »\nLa main sur le cœur, ses yeux plongent dans les tiens, solennels :\n« <H>Que la Déesse du Destin t’enveloppe de mille rayons de lune, et que tes ailes brillent à jamais, pures et immaculées comme la Pleine Lune.</> »",
          DialogueId = 6201629,
          GUID = "0F866EC2",
          NextDialogue = 6201630,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy",
          Subtitle = "\"Right! We've still got to bring her home. So, Traveller — walk your path. Don't worry about us. Do not bear our burden. Only carry our blessing with you.\"\nShe presses her hand over her heart, meeting your eyes,\nand speaks with solemn sincerity:\n\"May the Goddess of Fate bathe you in a thousand beams of moonlight, and may your wings shine for ever, flawless as the full moon.\""
        },
        [6201630] = {
          ContentFR = "C’est une bénédiction rare et grave. À Élysium, on ne l’adresse qu’à ceux que l’on pense ne jamais revoir. Ce n’est pas un adieu désespéré : c’est une acceptation sereine du destin.\n« Je souhaite que ton chemin soit sûr... et j’accepte que ce vœu soit peut-être notre dernier adieu. »",
          DialogueId = 6201630,
          GUID = "0F866EEC",
          NextDialogue = 6201631,
          RougeTalkActorType = 3,
          Subtitle = [[
It is a blessing most solemn. In Elysium, such words are given only to one you may never see again.
Yet it is no farewell of despair. It is calm acceptance of fate.
"I wish you safe passage on the road ahead... and accept that it may mean we are parted, in life or in death, forevermore."]]
        },
        [6201631] = {
          ContentFR = "Tu inclines la tête, reprends ta lanterne, et avances de nouveau dans la nuit.",
          DialogueId = 6201631,
          GUID = "0F866F16",
          RougeTalkActorType = 3,
          Subtitle = "You give Kathy a silent nod. Raising your Lantern, you step once more onto the path before you."
        },
        [6201701] = {
          ContentFR = "Des voix s’élèvent au loin, des voix jeunes, animées.\nVoilà si longtemps que tu n’as pas entendu une telle chaleur dans l’Abysse : vibrantes, pleines de vie, encore intactes, épargnées par l’ombre rampante.\nTu sais d’instinct qu’il ne s’agit ni de spectres ni d’illusions : ce sont bien des êtres de chair et de sang.",
          DialogueId = 6201701,
          GUID = "0F867A92",
          NextDialogue = 6201702,
          RougeTalkActorType = 3,
          Subtitle = "The voices of young men and women drift through the Abyss. It has been so long since you last heard such sounds here — lively, vibrant, untouched by darkness.\nAnd you know: these are no phantoms, no echoes of the dead, but living human beings."
        },
        [6201702] = {
          ContentFR = "Une fois encore, tu croises leur route.",
          DialogueId = 6201702,
          GUID = "0F867ABC",
          NextDialogue = 6201703,
          RougeTalkActorType = 3,
          Subtitle = "Once more, you cross paths with them."
        },
        [6201703] = {
          ContentFR = "Comme chaque fois, les quatre jeunes chevaliers émergent ensemble de la brume.\nMais leurs silhouettes couvertes de sang hantent toujours ta mémoire. Et tu te demandes : qui est le plus à plaindre ?\nEux, condamnés à mourir encore et encore dans le désespoir ?\nOu toi, condamné à les voir périr à chaque cycle ?",
          DialogueId = 6201703,
          GUID = "0F867AE6",
          NextDialogue = 6201704,
          RougeTalkActorType = 3,
          Subtitle = "As before, the four young Knights emerge together from the mist.\nYet their blood-stained figures linger sharp in your memory. For a moment, you cannot tell which is crueller — for them, doomed to die in despair time after time... or for you, condemned to watch them die again and again."
        },
        [6201704] = {
          ContentFR = "« Capitaine, on est bien dans la bonne direction ? »\nLa jeune chevalière blonde grimpe trois marches d’un vieil escalier, bondit d’un élan, et redescend aussitôt.\n« Ça ne ressemble qu’à des ruines... »",
          DialogueId = 6201704,
          GUID = "0F867B10",
          NextDialogue = 6201705,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy",
          Subtitle = [[
"Is this the right way, Captain?"
The young blonde Knight bounds up the ancient steps in a rush, then leaps down in one swift motion.
"It just looks like a ruin to me."]]
        },
        [6201705] = {
          ContentFR = "« Une chose est sûre : on n’est encore jamais venus ici. »\nLe jeune capitaine avance d’un pas posé, dépassant Cathy.\n« Dans le Lac Sacré, on perd vite tout repère. Il ne reste qu’à avancer pas à pas. »",
          DialogueId = 6201705,
          GUID = "0F867B3A",
          NextOptions = {
            [1] = 6201706,
            [2] = 6201716
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = [[
"At least I know we haven't been here before."
The young captain strides past her with measured steps.
"Navigating the Sacred Lake is impossible. We'll just have to take it step by step."]]
        },
        [6201706] = {
          ContentFR = "<I>Rebroussez chemin... tant qu’il est encore temps.</>",
          DialogueId = 6201706,
          GUID = "0F867B64",
          IsKeyOption = true,
          NextDialogue = 6201707,
          RougeTalkActorType = 2,
          Subtitle = "Turn back... while you still can."
        },
        [6201707] = {
          ContentFR = "« Hmm ? Qui êtes-vous... ? »",
          DialogueId = 6201707,
          GUID = "0F867B8E",
          NextDialogue = 6201708,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = "\"Hmm? And you are...?\""
        },
        [6201708] = {
          ContentFR = "« Vous êtes bien les compagnons de Dame Lisbell, n’est-ce pas ? Elle m’a chargé de vous prévenir : l’Abysse est infiniment plus dangereux que tout ce que nous imaginions. Aucune escouade, même valeureuse, ne peut y survivre. Rentrez, je vous en prie. Ne sacrifiez pas vos vies pour rien. »\nQu’importe si ce n’est qu’un mensonge. Tant qu’au moins, <W>cette fois</>, ils peuvent vivre.",
          DialogueId = 6201708,
          GUID = "0F867BB8",
          NextDialogue = 6201709,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"You're friends of Lisbell, right? She asked me to warn you: the Abyss is far more perilous than you imagine. No single squad can withstand it. Go back — do not throw your lives away.\"\nYou do not care if it is nothing but a lie. So long as they survive this time, it is worth it."
        },
        [6201709] = {
          ContentFR = "« Quoi ?! Vous savez où est Dame Lisbell ? Elle va bien ? Où est-elle ? »",
          DialogueId = 6201709,
          GUID = "0F867BE2",
          NextDialogue = 6201710,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy",
          Subtitle = "\"Really!? You know Dame Lisbell? Is she safe? Where is she?\""
        },
        [6201710] = {
          ContentFR = "« Attends, Cathy. »\nLe prêtre l’arrête, ses yeux pleins de méfiance posés sur toi.\n« Dame Lisbell n’est pas de celles qui reculent. Ne profanez pas son nom pour nous tromper. Et puis, n’oubliez pas : cette croisade fut ordonnée par Sa Sainteté le Pape lui-même. Même si la route devant nous mène droit en enfer, nous ne reculerons pas. »",
          DialogueId = 6201710,
          GUID = "0F867C0C",
          NextDialogue = 6201711,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton",
          Subtitle = [[
"Hold on, Kathy."
The Priest draws her back, his eyes narrowing with suspicion.
"Dame Lisbell is not one to falter. Please do not use her name to deceive us. Besides, this campaign was decreed by His Holiness the Pope himself. Even if the road before us is hell itself, we will not retreat."]]
        },
        [6201711] = {
          ContentFR = "Tu soupires intérieurement.\nLes mortels prononcent parfois le mot « enfer » sans jamais en comprendre le poids véritable.",
          DialogueId = 6201711,
          GUID = "0F867C36",
          NextDialogue = 6201712,
          RougeTalkActorType = 3,
          Subtitle = [[
You let out a quiet sigh.
So often, when people speak of "hell," they scarcely grasp its true meaning.]]
        },
        [6201712] = {
          ContentFR = "« Vous nous dites de rebrousser chemin... »\nLa sorcière au manteau sombre te fixe de ses yeux insondables, sa voix glaciale.\n« Mais en vérité... cela ne servirait à rien, n’est-ce pas ? »",
          DialogueId = 6201712,
          GUID = "0F867C60",
          NextDialogue = 6201713,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = [[
"You tell us to turn back..."
The cloaked Sorceress fixes you with her deep gaze, her voice cold as ever.
"But really... it wouldn't make a difference, would it?"]]
        },
        [6201713] = {
          ContentFR = "Tu ne réponds pas.\nElle a raison. Même s’ils reculaient maintenant, ils ne retrouveraient jamais la sortie. Dans l’Abysse, \"avancer\" ou \"reculer\" ne sont que des illusions.\nLes sauver vraiment... cela n’aurait qu’un seul sens : mettre fin à ce cycle de désespoir.",
          DialogueId = 6201713,
          GUID = "0F867C8A",
          NextDialogue = 6201714,
          RougeTalkActorType = 3,
          Subtitle = "It is a question you cannot answer.\nShe is right. Even if they turn back, they will never find their way again. In this Abyss, \"forward\" and \"backward\" are nothing but self-deception.\nTo truly save them, there is only one path — to end this cycle of despair."
        },
        [6201714] = {
          ContentFR = "« Mes amis... »\nTu poses solennellement ta main sur ton cœur et les contemples.\n« <H>Que la Déesse du Destin vous enveloppe de mille rayons de lune, et que vos ailes brillent à jamais, pures et immaculées comme la Pleine Lune.</> »",
          DialogueId = 6201714,
          GUID = "0F867CB4",
          NextDialogue = 6201715,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = [[
"My friends..."
You place a hand solemnly over your chest and look upon the young Knights.
"May the Goddess of Fate bathe you in a thousand beams of moonlight, and may your wings shine for ever, flawless as the full moon."]]
        },
        [6201715] = {
          ContentFR = "À tes mots, un sourire empreint de tristesse passe sur le visage de Calista. Et soudain, tu comprends : ce qu’elle espérait vraiment, c’était que tu la contredises. Même par un mensonge.",
          DialogueId = 6201715,
          GUID = "0F867CDE",
          RougeTalkActorType = 3,
          Subtitle = "At your words of blessing, a faint, sorrowful smile touches Calista's lips. And in that moment you realise: perhaps what she truly wished... was for you to contradict her. Even with a lie."
        },
        [6201716] = {
          ContentFR = "<I>Braves chevaliers, que la Déesse de la Pleine Lune protège votre voyage.</>",
          DialogueId = 6201716,
          GUID = "0F867D08",
          IsKeyOption = true,
          NextDialogue = 6201717,
          RougeTalkActorType = 2,
          Subtitle = "Brave Knights, may the Goddess of the Full Moon watch over your journey."
        },
        [6201717] = {
          ContentFR = "« Hmm ? »\nTa bénédiction soudaine le laisse interdit.\n« Qui êtes-vous... ? »",
          DialogueId = 6201717,
          GUID = "0F867D32",
          NextDialogue = 6201718,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn",
          Subtitle = [[
"Hm?"
Your sudden blessing leaves the young man bewildered.
"And you are...?"]]
        },
        [6201718] = {
          ContentFR = "« Vous êtes les compagnons de Dame Lisbell, n’est-ce pas ? Elle m’a confié ce message : l’Abysse est bien plus terrible que tout ce que vous croyez. Vous affronterez des épreuves redoutables. Soyez prêts. »",
          DialogueId = 6201718,
          GUID = "0F867D5C",
          NextDialogue = 6201719,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"You're friends of Lisbell, right? She asked me to warn you: the Abyss is far more perilous than you imagine. You will face trials beyond anything you know. Be prepared.\""
        },
        [6201719] = {
          ContentFR = "« Quoi ?! Vous savez où est Dame Lisbell ? Elle va bien ? Où est-elle ? »",
          DialogueId = 6201719,
          GUID = "0F867D86",
          NextDialogue = 6201720,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy",
          Subtitle = "\"Really!? You know Dame Lisbell? Is she safe? Where is she?\""
        },
        [6201720] = {
          ContentFR = "« Attends, Cathy. Ne crois pas si vite quelqu’un dont nous ignorons tout. »\nLe prêtre t’arrête, son regard empli de suspicion.\n« Dame Lisbell n’a pas une nature si grave. Je doute qu’elle ait jamais parlé de la sorte. Et puis, cette croisade fut décrétée par le Pape en personne. Nous ferons notre devoir, sans qu’on nous le rappelle. »",
          DialogueId = 6201720,
          GUID = "0F867DB0",
          NextDialogue = 6201721,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton",
          Subtitle = [[
"Hold on, Kathy. It's not wise to trust someone we've just met."
The Priest draws her back, his eyes narrowing with suspicion.
"Dame Lisbell is not of such a sober temperament. I can scarcely imagine her speaking with such gravity. Besides, this campaign was decreed by His Holiness the Pope himself. We will do our utmost. We need no further reminder."]]
        },
        [6201721] = {
          ContentFR = "« Pour ma part, je crois {性别:ce voyageur|cette voyageuse}. Ici, on s’habitue à la folie, un simple changement de caractère n’a rien d’étonnant... »\nElle relève la tête et t’observe longuement, comme pour résoudre une énigme.\n« Mais vous... qui êtes-vous vraiment ? J’ai l’impression... que je vous ai déjà rencontré. »",
          DialogueId = 6201721,
          GUID = "0F867DDA",
          NextDialogue = 6201722,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = "\"I, for one, believe this traveller speaks truth. Dwell in this place long enough, and even madness itself begins to seem ordinary — what is a shift in temperament compared to that?\"\nThe Sorceress lifts her head, fixing her deep eyes upon you as though to unravel a riddle.\n\"Who are you, truly? I cannot shake the feeling... that I have seen you before.\""
        },
        [6201722] = {
          ContentFR = "« ... Qui je suis n’a aucune importance. »\nTu offres un sourire apaisé aux jeunes chevaliers.\n« Tout ce que vous devez savoir, c’est que ma bénédiction est sincère. Même si la fin est déjà écrite... je souhaite que vous trouviez un sens à votre route. »",
          DialogueId = 6201722,
          GUID = "0F867E04",
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = [[
"...My name doesn't matter."
You look upon the young Knights and offer an earnest smile.
"All you need to know is that my blessing is sincere. Even if the end has already been written... I pray you may still find meaning in the journey."]]
        },
        [6201801] = {
          ContentFR = "Au loin, tu aperçois deux silhouettes familières, encerclées par une nuée d’Umbrés : Milton et Calista.\nIls combattent dos à dos, taillant vague après vague, mais l’assaut ne cesse de croître.\nAlors tu lèves ta lanterne. Sous l’éclat glacé du Lumistella, les ombres reculent — un répit, rien de plus.",
          DialogueId = 6201801,
          GUID = "0F868AFA",
          NextDialogue = 6201802,
          RougeTalkActorType = 3,
          Subtitle = "From a distance, you glimpse two familiar figures hemmed in by a horde of Abyssoids — Milton and Calista.\nThey fight in perfect accord, cutting through wave after wave, yet still the tide does not relent.\nYou lift your Lantern and advance. At the Glazeystal's radiant glow, the Abyssoids recoil — if only for a moment."
        },
        [6201802] = {
          ContentFR = "« Vous... vous êtes {性别:celui|celle} que nous avons croisé. »\nLe prêtre sursaute, puis baisse les yeux, honteux.\n« J’ai douté de vous, je vous ai jugé à tort... et malgré cela, vous venez nous secourir. Je vous dois mes excuses, et ma gratitude, {性别:voyageur|voyageuse}. »",
          DialogueId = 6201802,
          GUID = "0F868B24",
          NextDialogue = 6201803,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton",
          Subtitle = [[
"You... you are the one from before."
The Priest startles, then drops his gaze in quiet shame.
"I spoke harshly before, yet still you came to our aid. I pray you, accept both my apology and my gratitude, mysterious traveller."]]
        },
        [6201803] = {
          ContentFR = "Elle rabat sa capuche et s’incline légèrement. Ses cheveux d’un noir de jais s’échappent de l’ombre du tissu.\n« Comme je le pensais... vous n’êtes pas un simple mortel. Merci pour votre aide.\nCette lanterne que vous portez... serait-ce un artéfact sacré ? Comment parvient-elle à disperser les Umbrés ? »",
          DialogueId = 6201803,
          GUID = "0F868B4E",
          NextOptions = {
            [1] = 6201804
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = [[
"So it's true... you're no ordinary soul. My thanks."
The Sorceress lowers her hood in greeting, the same jet-black hair tumbling free.
"That lantern you carry... is it some holy relic? By what power does it drive the Abyssoids away?"]]
        },
        [6201804] = {
          ContentFR = "<I>C’est un objet qu’on m’a confié.</>",
          DialogueId = 6201804,
          GUID = "0F868B78",
          NextDialogue = 6201805,
          RougeTalkActorType = 2,
          Subtitle = "Someone entrusted it to me."
        },
        [6201805] = {
          ContentFR = "« Dans ce cas, je n’en demanderai pas davantage. Mais avec elle, nous pourrions traverser l’Abysse plus sûrement. Accepteriez-vous que nous marchions à vos côtés ? »",
          DialogueId = 6201805,
          GUID = "0F868BA2",
          NextDialogue = 6201806,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = "\"If that is so, I shall not pry. Yet with such a lantern, our way through the Abyss would be far lighter. Might we walk at your side?\""
        },
        [6201806] = {
          ContentFR = "« Cela m’est égal. Mais sachez-le : nos buts diffèrent. Je cherche seulement à réparer cette lanterne, en rassemblant les fragments de Lumistella. »",
          DialogueId = 6201806,
          GUID = "0F868BCC",
          NextDialogue = 6201807,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"I don't mind. But know this — my path is not yours. I'm only here to restore the lantern, gathering shards of Glazeystal.\""
        },
        [6201807] = {
          ContentFR = "« Qu’importe nos missions... Mon instinct me dit qu’en voyageant à vos côtés, nous serons plus près de la vérité de l’Abysse. »",
          DialogueId = 6201807,
          GUID = "0F868BF6",
          NextDialogue = 6201808,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = "\"At this point, our mission scarcely matters... Yet something tells me that with you, we stand a better chance of uncovering the truth of the Abyss.\""
        },
        [6201808] = {
          ContentFR = "« Calista, qu’est-ce que tu racontes ! »\nAvant même que tu ne répondes, le prêtre s’interpose, furieux.\n« Même séparés des autres, nous restons des chevaliers d’Élysium. Même seul, on ne renonce pas au devoir ! »",
          DialogueId = 6201808,
          GUID = "0F868C20",
          NextDialogue = 6201809,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton",
          Subtitle = [[
"What nonsense is that, Calista?" 
Before you can reply, the Priest cuts in sharply.
"Though parted from the others, we are still Knights of Elysium. Even if but one remains, our duty endures!"]]
        },
        [6201809] = {
          ContentFR = "Son ton s’enflamme, et les flèches de son carquois frémissent contre sa cape.\n« Le devoir, toujours le devoir... Il ne reste que ça dans ta tête ? Regarde ce que nous affrontons ici : Souillés, illusions, spectres errants... Si le Lac Sacré est bien la porte du Paradis des Paradis, comme on nous l’enseigne, alors dis-moi : que sont ces Umbrés ?\nNe ressemble-t-il pas plutôt à la tanière du démon, comme le proclament les Noctilunistes ? »",
          DialogueId = 6201809,
          GUID = "0F868C4A",
          NextDialogue = 6201810,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = "\"Heh... duty. Is your head filled with nothing but hollow oaths?\"\nThe Sorceress's voice flares, quiver rattling with each sharp movement.\n\"Look at what we have faced here — Filthoids, Phantasms, wandering shades and spirits. If those above are right, and the Sacred Lake really leads to the Heaven above Heavens... then what are these Abyssoids we must cut down? Does this not resemble more a demon's den, as the Noclunism once—\""
        },
        [6201810] = {
          ContentFR = "« Tu... tu divagues ! Tu parles comme une hérétique ! »\nIl s’efforce de garder contenance, mais sa voix trahit un doute.\n« Ces Umbrés... ce sont peut-être des âmes qui ont échoué à l’ultime épreuve, dont la foi a vacillé. En les purifiant, nous restaurerons peut-être le Lac Sacré. N’est-ce pas une épreuve imposée par les Neuf ? S’ils nous jugent dignes et constants, ils nous protégeront. »",
          DialogueId = 6201810,
          GUID = "0F868C74",
          NextDialogue = 6201811,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton",
          Subtitle = "\"Y—You are mad! You speak like a heretic!\"\nHe clings to his composure, yet a faint hesitation threads his voice.\n\"Those Abyssoids... perhaps their faith faltered, and they failed the last trial. If we sweep aside these obstacles, the Sacred Lake may yet be restored. Perhaps this is the trial ordained by the Great Nine Themselves — and if we remain steadfast, their protection shall shield us from harm...\""
        },
        [6201811] = {
          ContentFR = "Un rire amer lui échappe, bientôt étouffé par un soupir las.\n« Si tes dieux se souciaient vraiment de nous, ils seraient descendus eux-mêmes pour purifier ce lieu. Mais non... On nous a envoyés ici en offrande. Le but n’était pas de vaincre, mais de nourrir l’Abysse de sacrifices. »\n« Regarde les Umbrés que nous avons croisées : combien étaient des chevaliers comme nous, envoyés avant nous ? »",
          DialogueId = 6201811,
          GUID = "0F868C9E",
          NextDialogue = 6201812,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = "\"If your gods truly cared, they'd descend themselves to cleanse this hell.\"\nA bitter laugh breaks from her, fading into a weary sigh.\n\"Perhaps we were sent only to die. The purge was never the point — what mattered was sacrifice upon sacrifice, to sate the Abyss. Many of the Abyssoids we have faced... were Knights sent before us.\""
        },
        [6201812] = {
          ContentFR = "« Des vétérans — plus âgés, forgés par d’innombrables guerres, plus forts et plus sages que nous. Et pourtant, eux aussi sont tombés, changés en spectres errants. Il n’y a pas d’issue. La folie ou la mort... tôt ou tard, ce sera notre sort. »",
          DialogueId = 6201812,
          GUID = "0F868CC8",
          NextDialogue = 6201813,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = "\"They were veterans — older, stronger, wiser, tempered by countless wars. Yet they too fell, and now they haunt us as Abyssoids. There is no escape. Madness or death awaits us all — sooner or later.\""
        },
        [6201813] = {
          ContentFR = "Ses lèvres se pincent, son visage se tend. Ses doigts crispés sur le bâton trahissent son tremblement.\nEnfin, il reprend, d’une voix forcée mais calme.\n« ... Compte tenu des circonstances, je vais faire comme si je n’avais rien entendu. Flynn est absent : c’est à moi que revient le commandement. »\n« Je t’ordonne de cesser tes blasphèmes et de remplir ton devoir de chevalier. »",
          DialogueId = 6201813,
          GUID = "0F868CF2",
          NextDialogue = 6201814,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton",
          Subtitle = [[
The Priest's lips press tight, his face drawn. He grips his staff to mask the tremor in his hands.
At length, he speaks again, his voice outwardly composed.
"...Given the circumstances, I shall pretend I never heard those words. Flynn is absent, and by rank the command falls to me. I order you: cease your slander of the Doctrine and the Saints, and fulfil your duty as a Knight."]]
        },
        [6201814] = {
          ContentFR = "Elle baisse la tête, résignée, et rabat sa capuche.\n« ... Soit. Mourir plus tôt ou plus tard ne change rien. Mais, en amie, je te le demande : si tout ce en quoi tu crois n’est qu’un mensonge, cela vaut-il vraiment la peine d’y sacrifier ta vie ? »",
          DialogueId = 6201814,
          GUID = "0F868D1C",
          NextDialogue = 6201815,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = "\"...Very well. Dying sooner is no ill fate.\"\nShe bows her head and draws her hood once more, as though yielding to her fate.\n\"Even so... as your friend, I must ask — if your faith rests upon falsehoods, is it truly worth dying for?\""
        },
        [6201815] = {
          ContentFR = "Il ne répond pas, secoue doucement la tête, puis s’avance d’un pas et t’incline un salut.\n« Pardonnez-nous cette querelle. Nous allons reprendre la route dès que nous aurons repris nos forces. »\n« Adieu, noble {性别:voyageur|voyageuse}. Que la Déesse de la Pleine Lune veille sur votre chemin. »",
          DialogueId = 6201815,
          GUID = "0F868D46",
          NextOptions = {
            [1] = 6201816,
            [2] = 6201818,
            [3] = 6201820
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton",
          Subtitle = [[
"..." 
The Priest gives no answer, only shakes his head in silence. At last he steps forward and bows to you. 
"Forgive our unseemly quarrel. We are resolved now. Once we have taken our rest, we shall continue onward. Farewell, kind traveller. May the Goddess of the Full Moon watch over your journey."]]
        },
        [6201816] = {
          ContentFR = "<I>Que la Déesse de la Pleine Lune veille aussi sur le vôtre.</>",
          DialogueId = 6201816,
          GUID = "0F868D70",
          IsKeyOption = true,
          NextDialogue = 6201817,
          RougeTalkActorType = 2,
          Subtitle = "May the Goddess of the Full Moon watch over yours as well."
        },
        [6201817] = {
          ContentFR = "Milton esquisse un sourire apaisé. Calista détourne le visage, silencieuse.\nTu leur rends un signe de tête, puis reprends ta route.",
          DialogueId = 6201817,
          GUID = "0F868D9A",
          RougeTalkActorType = 3,
          Subtitle = [[
At your words, Milton smiles faintly, as though at peace. Calista turns aside in silence, her face hidden.
With a final nod, you turn and walk away.]]
        },
        [6201818] = {
          ContentFR = "<I>Je doute que la Déesse de la Pleine Lune ait encore la force de m’aider.</>",
          DialogueId = 6201818,
          GUID = "0F868DC4",
          IsKeyOption = true,
          NextDialogue = 6201819,
          RougeTalkActorType = 2,
          Subtitle = "I fear the Goddess of the Full Moon has little aid left for me."
        },
        [6201819] = {
          ContentFR = "Milton détourne les yeux, mal à l’aise, mais se tait. Calista t’adresse un sourire triste, puis baisse la tête.\nTu leur rends un signe de tête, puis reprends ta route.",
          DialogueId = 6201819,
          GUID = "0F868DEE",
          RougeTalkActorType = 3,
          Subtitle = [[
At your words, Milton averts his eyes, clearly uneasy, but remains silent. Calista gives a sorrowful smile, then lowers her head in weary resignation.
With a final nod, you turn and walk away.]]
        },
        [6201820] = {
          ContentFR = "<I>Je crois... que ce n’est pas la foi qui importe, mais notre courage.</>",
          DialogueId = 6201820,
          GUID = "0F868E18",
          IsKeyOption = true,
          NextDialogue = 6201821,
          RougeTalkActorType = 2,
          Subtitle = "I think... perhaps what truly matters is not faith, but courage."
        },
        [6201821] = {
          ContentFR = "Surpris, Milton et Calista échangent un regard. Puis le silence les enveloppe, lourd de réflexion.\nTu n’ajoutes rien. Après tout, ces mots ne sont pas vraiment les tiens — et toi-même, tu n’en saisis pas encore tout le sens.\nTu leur rends un signe de tête, puis reprends ta route.",
          DialogueId = 6201821,
          GUID = "0F868E42",
          RougeTalkActorType = 3,
          Subtitle = "At your words, Milton and Calista trade a surprised glance, then sink into thoughtful silence.\nYou add nothing more — for the words were not your own, and even now their meaning eludes you.\nWith a final nod, you turn and walk away."
        },
        [6201901] = {
          ContentFR = "Une âcre odeur de sang plane dans l’air, lourde et menaçante.\nCette obscurité sans fond, ce silence oppressant — tout te dit que tu ne trouveras rien de ce que tu cherches.\nEt pourtant... une étrange prémonition t’étreint : comme si quelqu’un, quelque chose, t’appelait à franchir ce seuil.\nAlors, tu avances.",
          DialogueId = 6201901,
          GUID = "0F869B62",
          NextDialogue = 6201902,
          RougeTalkActorType = 3,
          Subtitle = "A sharp, ominous tang of blood drifts from ahead.\nThe depthless dark, the crushing silence — everything warns there is nothing here worth seeking. And yet, a strange premonition stirs within you... as though something waits, willing you to venture into the void. And so, you step forward."
        },
        [6201902] = {
          ContentFR = "Soudain, des éclats blancs jaillissent dans les ténèbres.\nNon... pas de la lumière.\nEn y regardant mieux, tu distingues des carapaces blanchâtres, celles des Souillés, entassées les unes sur les autres comme les toiles frénétiques d’un peintre hérétique enivré.\nInstinctivement, tu recules d’un pas — et deux silhouettes familières se dressent à tes côtés.",
          DialogueId = 6201902,
          GUID = "0F869B8C",
          NextDialogue = 6201903,
          RougeTalkActorType = 3,
          Subtitle = "Suddenly, pale gleams break across the dark — no, not light. You peer closer, and see them for what they are: the bleached husks of Filthoids, piled one upon another, as if some heretic painter had hurled his strokes in a drunken frenzy.\nYou flinch back — and two familiar figures take shape beside you."
        },
        [6201903] = {
          ContentFR = "« Kof... kof... ça n’en finit jamais... »\nCalista essuie le sang qui perle à ses lèvres et laisse son arc tomber à terre.\n« C’était ma dernière flèche... désormais, il ne reste que la magie. »\n« Hé... j’ai bien mérité ma place auprès de vos dieux, non ? Alors, je vous en conjure : quand je tomberai, ne jetez pas mon corps dans une fosse commune. Laissez-moi au moins un corps intact. »",
          DialogueId = 6201903,
          GUID = "0F869BB6",
          NextDialogue = 6201904,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = [[
"Cough... cough... This just never ends..."
The Sorceress wipes the blood from her lips, her longbow slipping from her grasp.
"That was my last arrow. It's magic or nothing now. Ha... that should count as devotion to your gods. Just don't throw me into some mass grave. Let my body at least remain whole."]]
        },
        [6201904] = {
          ContentFR = "« Ne dis pas n’importe quoi — derrière toi ! »\nMilton abat son bâton d’un geste furieux, une lueur jaillit, déchirant l’ombre.\n« Tch... encore des Umbrés... »",
          DialogueId = 6201904,
          GUID = "0F869BE0",
          NextDialogue = 6201905,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton",
          Subtitle = "\"Don't say that — look out!\"\nThe Priest lashes his staff through the dark, its tip bursting with light.\n\"Tch... more Abyssoids...\""
        },
        [6201905] = {
          ContentFR = "Tu pivotes en même temps que Calista : une marée d’ombres déferle sur vous, enjambant les cadavres des Souillés, comme si l’artiste fou avait renversé un nouveau seau d’encre noire sur sa toile.\nTu lèves la lanterne à la hâte — mais rien ne se passe. Et soudain tu comprends : la lumière traverse le bâton de Milton, comme s’il n’était pas là.",
          DialogueId = 6201905,
          GUID = "0F869C0A",
          NextDialogue = 6201906,
          RougeTalkActorType = 3,
          Subtitle = "You wheel around with Calista, watching them surge forward, rolling over the shattered Filthoid husks like another stroke of ruin across a grotesque canvas.\nYou raise your Lantern in haste — but it does nothing. And then you see it: the Lantern's glow passes straight through Milton's staff."
        },
        [6201906] = {
          ContentFR = "Alors la vérité t’éclaire : ce n’est pas le présent. Rien de tout cela n’est réel, sinon une réminiscence, une ombre de mémoire.\nTu es à leurs côtés, oui — mais {性别:impuissant|impuissante}.\nImmobile, spectateur condamné, tu n’as d’autre choix que de les voir s’épuiser, se blesser, s’effondrer.",
          DialogueId = 6201906,
          GUID = "0F869C34",
          NextDialogue = 6201907,
          RougeTalkActorType = 3,
          Subtitle = "And it strikes you — this is no reality, but the echo of a memory. You stand at their side, yet powerless, forced only to watch as they bleed, falter, and fall."
        },
        [6201907] = {
          ContentFR = "Les Umbrés tombent, un à un. Quatre restaient... puis trois... deux... enfin un.\nS’il restait à l’un d’eux un souffle pour contre-attaquer.\nSi leurs compagnons les avaient rejoints à temps.\nSi un éclat de Lumistella avait scintillé non loin... alors peut-être. Peut-être auraient-ils survécu.\nMais non. Rien.\nRien que toi — témoin trop tardif.",
          DialogueId = 6201907,
          GUID = "0F869C5E",
          NextDialogue = 6201908,
          RougeTalkActorType = 3,
          Subtitle = "The Abyssoids dwindle. Four remain... then three... two... one. If either Knight had a breath of strength left.\nIf their comrades had reached them in time. If a single shard of Glazeystal had lain close at hand... They might have won. They might have lived.\nBut no. Nothing. All that remains is you — the bystander who came too late."
        },
        [6201908] = {
          ContentFR = "Une silhouette humaine s’avance. Un Umbré — ancien camarade, peut-être mentor, peut-être ami.\nSa lance noire se tend droit vers le cœur de Calista.\nTu fermes les yeux. Tu refuses de voir.",
          DialogueId = 6201908,
          GUID = "0F869C88",
          NextDialogue = 6201909,
          RougeTalkActorType = 3,
          Subtitle = "A human-shaped Abyssoid lurches near — once their senior, comrade, perhaps even friend. His black spear thrusts straight for Calista's heart.\nYou shut your eyes, unwilling to see."
        },
        [6201909] = {
          ContentFR = "« Milton... ?! Toi... pourquoi... ? »",
          DialogueId = 6201909,
          GUID = "0F869CB2",
          NextDialogue = 6201910,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = "\"Milton...!? You... why...?\""
        },
        [6201910] = {
          ContentFR = "Tu les rouvres. Et la lance perce la poitrine du prêtre.\nL’ombre se dissout. Milton s’effondre, et le sang éclabousse l’austère blancheur de sa tunique — toujours impeccable, même dans la mort.",
          DialogueId = 6201910,
          GUID = "0F869CDC",
          NextDialogue = 6201911,
          RougeTalkActorType = 3,
          Subtitle = "You open them again — the spear has pierced Milton's chest instead. The Abyssoid dissolves into mist, and he crumples, blood soaking the immaculate robes he had kept so carefully."
        },
        [6201911] = {
          ContentFR = "« Qu’as-tu fait... ? Pourquoi... ? »\nCalista tombe à genoux, les mains tremblantes, jetant des sorts de guérison dérisoires.\n« N’étais-je pas ton hérétique, à tes yeux ? Pourquoi risquer ta vie pour moi ? N’avais-tu pas une foi à prouver ? Alors pourquoi... pourquoi l’avoir jetée ainsi ? »",
          DialogueId = 6201911,
          GUID = "0F869D06",
          NextDialogue = 6201912,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = "\"What... what have you done...? You...\"\nThe Sorceress falls to her knees beside him, frantic, weaving a healing spell — in vain.\n\"Did you not call me a heretic...? Then why... why waste your life on me? Weren't you so bent on proving your faith? Then why cast your life away like this?\""
        },
        [6201912] = {
          ContentFR = "« Parce que ma foi m’ordonnait... de protéger mes compagnons. Tu peux la mettre en doute, mais cela — j’en suis sûr. »\nPour la première fois, son visage sévère se détend. Un sourire naît, non plus celui du prêtre, mais celui de l’homme.\n« J’ai déjà assez donné aux dieux. Alors, une fois au moins, laisse-moi parler pour moi. Calista... oublie ces serments, ces devoirs. Quitte cet endroit. Vis. »",
          DialogueId = 6201912,
          GUID = "0F869D30",
          NextDialogue = 6201913,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton",
          Subtitle = "\"Because my faith taught me... to protect my comrades. Doubt it if you must... but of this I am certain.\"\nFor the first time, the stern Priest's face softens — a smile warm and human, belonging wholly to the man himself.\n\"I have given the gods enough already... so let me speak once for myself. Calista... cast aside the oaths, the duty. Leave this place. Live.\""
        },
        [6201913] = {
          ContentFR = "« Hein... ? »",
          DialogueId = 6201913,
          GUID = "0F869D5A",
          NextDialogue = 6201914,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = "\"What...?\""
        },
        [6201914] = {
          ContentFR = "« Une fois que je serai parti, tu seras ton propre capitaine. Libre de suivre ton choix. Comme tu l’as toujours dit... fuis. Sors de cet Abysse. Ou cherche {性别:le voyageur|la voyageuse}. Peu importe. Mais vis. »",
          DialogueId = 6201914,
          GUID = "0F869D84",
          NextDialogue = 6201915,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton",
          Subtitle = "\"Once I am gone, you will be your own commander. Free to act as you will. As you always said... run. Escape the Abyss. Or seek out that traveller. Whatever it takes — live.\""
        },
        [6201915] = {
          ContentFR = "Les larmes roulent sur les joues pâles de Calista, tombant sur la tunique du prêtre, réchauffant un instant le sang déjà figé.\n« Mais... seule... où pourrais-je aller...? »",
          DialogueId = 6201915,
          GUID = "0F869DAE",
          NextDialogue = 6201916,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = [[
Tears streak down her pale cheeks, falling onto his robes, softening the clotted blood.
"But now that I'm all alone... how far could I possibly go...?"]]
        },
        [6201916] = {
          ContentFR = "« Tu divagues encore... »\nDe sa main tremblante — celle qui maniait jadis le bâton avec une fermeté inébranlable — Milton détache l’insigne de sa poitrine et le dépose dans la sienne.\n« Tu as toujours été la meilleure d’entre nous. La première à voir la vérité ici. La première à la questionner avec courage. Toi... tu peux y arriver. Tu survivras... »",
          DialogueId = 6201916,
          GUID = "0F869DD8",
          NextDialogue = 6201917,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton",
          Subtitle = "\"You're speaking nonsense again...\"\nWith trembling fingers — the same hand that once gripped his staff with unyielding strength — he unfastens the insignia from his chest and presses it into her palm.\n\"You were always the best among us. From the day we entered this place, you were the first to see the truth, the first to question it with courage. You... can endure. I believe in you...\""
        },
        [6201917] = {
          ContentFR = "L’illusion se dissipe avant qu’elle n’ait le temps de répondre.\nLe silence retombe. Tu retrouves le corps du prêtre, glacé, inerte.\nDe son flanc, l’ombre suinte, noire et épaisse. Bientôt, lui aussi se relèvera, privé de repos, pour errer comme les autres.",
          DialogueId = 6201917,
          GUID = "0F869E02",
          NextOptions = {
            [1] = 6201918,
            [2] = 6201920
          },
          RougeTalkActorType = 3,
          Subtitle = "The Phantasms fade before Calista can answer.\nIn the stillness, you find the Priest's body — cold, lifeless. Black mist seeps from his wound. Soon, he too will rise as a restless Abyssoid."
        },
        [6201918] = {
          ContentFR = "<I>Mettre fin à sa souffrance</>",
          DialogueId = 6201918,
          GUID = "0F869E2C",
          IsKeyOption = true,
          NextDialogue = 6201919,
          RougeTalkActorType = 2,
          Subtitle = "(Help him end his suffering.)"
        },
        [6201919] = {
          ContentFR = "Avant que la corruption n’achève son œuvre, tu lèves la lanterne et lui offres le repos.\n« Merci... »\nAs-tu vraiment entendu cette voix ? Ou n’était-ce qu’un écho que ton esprit inventa, pour s’apaiser ?",
          DialogueId = 6201919,
          GUID = "0F869E56",
          RougeTalkActorType = 3,
          Subtitle = "Before the transformation completes, you raise your Lantern and grant him release.\n\"Thank you...\"\nPerhaps you truly heard the words. Or perhaps they were only in your mind — a comfort you chose to believe."
        },
        [6201920] = {
          ContentFR = "<I>Refuser d’agir</>",
          DialogueId = 6201920,
          GUID = "0F869E80",
          IsKeyOption = true,
          NextDialogue = 6201921,
          RougeTalkActorType = 2,
          Subtitle = "(You cannot bring yourself to strike.)"
        },
        [6201921] = {
          ContentFR = "Tu recules, incapable de lever la main.\nMais déjà, l’Umbré se dresse. Cette main livide que son ami venait de laisser échapper, se referme de nouveau sur le bâton.\nIl t’attaque.\nTu pousses un long soupir, lames levées, et l’abats. Comme toujours.",
          DialogueId = 6201921,
          GUID = "0F869EAA",
          RougeTalkActorType = 3,
          Subtitle = "You step back, unable to raise your hand.\nBut the Abyssoid stirs. That pale hand — once fallen limp from his friend's grasp — closes once more around his staff, lashing out at you.\nWith a weary sigh, you lift your blade and strike him down. As always."
        },
        [6202001] = {
          ContentFR = "Encore une fois, tu es parvenu au terme du cycle.\nLes éclats de Lumistella que tu as réunis sont trop faibles pour affronter le cœur de l’Abysse.\nIl te faut, une fois encore, remonter le temps.",
          DialogueId = 6202001,
          GUID = "0F86ABCA",
          NextDialogue = 6202002,
          RougeTalkActorType = 3,
          Subtitle = [[
Once again, you reach the cycle's end.
The Glazeystal you hold is still too little to face the heart of the Abyss. You must rewind time once more.]]
        },
        [6202002] = {
          ContentFR = "Tu erres dans le flot du chaos, sans but.\nTu as croisé Son regard tant de fois qu’il ne t’effraie plus, tu accueilles simplement, en silence, les dernières minutes de ce cycle.\nSoudain, une silhouette familière se détache de l’ombre.",
          DialogueId = 6202002,
          GUID = "0F86ABF4",
          NextDialogue = 6202003,
          RougeTalkActorType = 3,
          Subtitle = [[
You drift through the torrent of chaos. You have met Its gaze too many times to fear it; you simply endure the final minutes in calm...
Until a familiar figure emerges before you.]]
        },
        [6202003] = {
          ContentFR = "« Ah... c’est vous... vous êtes donc encore en vie. »\nCalista s’appuie contre un pan de mur effondré. Son manteau en lambeaux ne dissimule plus les plaies qui labourent son corps.\n« Qui êtes-vous, en réalité ? Pourquoi... pourquoi n’y a-t-il aucune peur dans vos yeux après tout ce que vous avez vu ? »",
          DialogueId = 6202003,
          GUID = "0F86AC1E",
          NextOptions = {
            [1] = 6202004,
            [2] = 6202006
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = [[
"Ah... it's you... So you're still alive, after all."
She leans against a shattered wall, her ragged cloak failing to hide the wounds that score her body.
"Who... are you? Why is there no fear in your eyes, even after all you have seen?"]]
        },
        [6202004] = {
          ContentFR = "<I>Je l’ai déjà affronté tant de fois... dans tant de cycles.</>",
          DialogueId = 6202004,
          GUID = "0F86AC48",
          IsKeyOption = true,
          NextDialogue = 6202005,
          RougeTalkActorType = 2,
          Subtitle = "I have faced It many times, across countless cycles."
        },
        [6202005] = {
          ContentFR = "« Des cycles... ? »\nDans ses yeux passe une lueur, comme chez un érudit qui comprend enfin l’énigme.\n« Ah... je vois. Tout s’explique. Voilà pourquoi votre regard sur nous était si... plein de compassion. Vous avez déjà vu, mille fois, notre fin... n’est-ce pas ? Alors bientôt je les rejoindrai à nouveau... et, à y penser ainsi, la mort semble soudain moins terrible. »",
          DialogueId = 6202005,
          GUID = "0F86AC72",
          NextDialogue = 6202008,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = [[
"Cycles?"
Her eyes kindle with sudden light, like a scholar grasping a riddle at last.
"Ah... I see. Now it all makes sense. No wonder your eyes looked on us with such... mercy. You have watched our end, again and again... haven't you? Then soon, I shall be with them once more. If that is true... death no longer seems so frightening."]]
        },
        [6202006] = {
          ContentFR = "<I>Il est des vérités qu’il vaut mieux ignorer.</>",
          DialogueId = 6202006,
          GUID = "0F86AC9C",
          IsKeyOption = true,
          NextDialogue = 6202007,
          RougeTalkActorType = 2,
          Subtitle = "Ignorance is bliss."
        },
        [6202007] = {
          ContentFR = "Calista esquisse un sourire las.\n« Vous avez raison... Je n’ose imaginer ce qu’il vous a fallu traverser pour posséder un calme à la fois si redoutable... et si puissant. »\nSes yeux noirs se posent sur toi, d’une douceur inattendue, comme ceux d’une amie au moment des adieux.\n« J’ai toujours senti que vous nous cachiez quelque chose... Mais je veux croire que vous aviez vos raisons, comme eux avaient leur foi. »",
          DialogueId = 6202007,
          GUID = "0F86ACC6",
          NextDialogue = 6202008,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = "\"Heh... you are right. I cannot fathom what you have endured, to bear a calm so... dreadful, and so strong.\"\nHer dark eyes linger on you — gentle, peaceful, like an old friend at parting.\n\"I always felt... you were holding something back. But I believe you had your reasons, just as they had their faith.\""
        },
        [6202008] = {
          ContentFR = "« Prenez ceci... S’il vous plaît... gardez-le avec vous. Considérez que c’est ma dernière requête. »\nD’une main tremblante, elle te tend un carnet usé.\n« Milton m’a dit de fuir... mais je sais que je ne rentrerai pas. Alors, au moins, que cette vie serve encore à quelque chose. »",
          DialogueId = 6202008,
          GUID = "0F86ACF0",
          NextDialogue = 6202009,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = [[
"Please... take this. Carry it with you, if you can. It is my final request..."
With a trembling hand she presses a worn notebook into yours.
"Milton told me to run... but I know I will not make it back. So at the very least... let this life leave behind some worth."]]
        },
        [6202009] = {
          ContentFR = "« Dans cet Abysse... j’ai passé tant de temps à me demander quelle foi était la vraie. La Déesse de la Pleine Lune ou celle de la Lune Noire ? Je n’ai jamais trouvé la réponse. Je me suis même querellée avec mes compagnons. »\nElle pousse un soupir, mi-ironique, mi-accablé.\n« Aujourd’hui je comprends enfin : la vérité d’une foi importe peu. Ce qui compte, c’est ce que font ceux qui y croient. Mes compagnons l’ont prouvé par leurs actes — et j’ai trouvé cela juste. Alors, pour finir, je vous offre ma bénédiction... au nom de leur foi, qu’elle soit vraie ou non. »",
          DialogueId = 6202009,
          GUID = "0F86AD1A",
          NextDialogue = 6202010,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = "\"In this Abyss... I spent so long questioning which faith was true. The Goddess of the Full Moon, or the Goddess of the Dark Moon — who was real? I never found the answer, and quarrelled with my friends over it again and again.\"\nShe sighs, half in self-mockery.\n\"Only now do I see: the truth of faith itself matters little. What matters is what its believers do. My friends proved their faith through action — and I believe they did the right thing. So in the end, I choose to give you my blessing... in the name of their faith, true or not.\""
        },
        [6202010] = {
          ContentFR = "« Alors... Voyageur... »\nSa main pâle tremble contre sa poitrine. Ses yeux déjà voilés s’efforcent de saisir ta silhouette.\n« <H>Que la Déesse du Destin t’enveloppe de mille rayons de lune, et que tes ailes brillent à jamais, pures et immaculées comme la Pleine Lune.</> »",
          DialogueId = 6202010,
          GUID = "0F86AD44",
          NextDialogue = 6202011,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista",
          Subtitle = [[
"Then... Traveller..."
Her trembling pale hand presses to her chest. Eyes glazed with fading light, she struggles to hold your form in view.
"May the Goddess of Fate bathe you in a thousand beams of moonlight, and may your wings shine for ever, flawless as the full moon."]]
        },
        [6202011] = {
          ContentFR = "Son souffle s’éteint.\nTu refermes doucement ses paupières.\nUn sourire paisible demeure sur ses lèvres, comme si elle s’était simplement endormie.",
          DialogueId = 6202011,
          GUID = "0F86AD6E",
          NextDialogue = 6202012,
          RougeTalkActorType = 3,
          Subtitle = [[
Her breath slips away.
You close her eyes with care. A gentle smile lingers on her lips, as though she merely drifted into sleep.]]
        },
        [6202012] = {
          ContentFR = "Tu ouvres le carnet qu’elle t’a confié.\nLe papier est taché de poussière et de sang, mais l’écriture reste lisible.\n« Moi, Calista, membre du Crépuscule Silencieux de l’Ordre des Plumes-Célestes sous l’Église Élyséenne, consigne ici tout ce que j’ai observé du Lac Sacré. Si quelqu’un trouve ce carnet, puisse-t-il lui offrir ne serait-ce qu’un mince secours pour sortir d’ici. »",
          DialogueId = 6202012,
          GUID = "0F86AD98",
          NextDialogue = 6202013,
          RougeTalkActorType = 3,
          Subtitle = [[
You unfold the notebook she placed in your hands. Though smudged with blood and dirt, the writing is still legible.
"I, Calista of the 'Hushed Dusk' squad of the Wingfeather Order under the Elysian Church, set down here what I have observed concerning the Sacred Lake. Should someone find this notebook, may these notes lend the smallest aid to your journey."]]
        },
        [6202013] = {
          ContentFR = "À la lumière de ta lanterne, tu parcours ces pages tracées à la hâte dans la pénombre.\nElles recensent des Umbrés et des illusions : leurs faiblesses, et les moyens de les dissiper.\nPuis une page retient ton attention :\n« Il est certain désormais que les écrits du <H>Noctilunisme</H> ne sont pas entièrement faux... Le Lac Sacré n’a aucun lien avec le Paradis des Paradis. Le prétendu \"appel divin\" n’est en réalité qu’un sacrifice. Cet endroit est saturé de la rancune et des malédictions des morts. »\n« Ma famille servait la Déesse de la Lune Noire et le cœur de l’Abysse. Elle croyait qu’une des Sept Vertus, <H>Shaliel</>, n’est jamais montée aux Paradis des Paradis mais est devenue le <H>Roi Démon</> sous ce lac — le cœur même de l’Abysse. Il dévore les âmes pour les offrir à Nepha. »",
          DialogueId = 6202013,
          GUID = "0F86ADC2",
          NextDialogue = 6202014,
          RougeTalkActorType = 3,
          Subtitle = "By lantern-light you skim the pages. Hasty scrawls, likely scratched in the dark, chart Abyssoids and Phantasms — their weaknesses, the means to drive them away. \nOne page arrests your gaze.\n\"It is certain now: the scriptures of the Noclunism are not wholly false... The Sacred Lake has no tie to the Heaven above Heavens. The so-called 'summoning' is closer to sacrifice. This place brims with the malice of the dead — a vessel of their lingering spite.\"\n\"My family were devotees of the Noclunism. They worshipped the Abyss and the Goddess of the Dark Moon, and believed that one of the Seven Virtues, Shaliel, never ascended to the Heaven above Heavens, but became instead the Demon King beneath the lake — the very heart of the Abyss. He devours souls, offering them to Nepha.\""
        },
        [6202014] = {
          ContentFR = "« Longtemps je me suis raccrochée à l’Orthodoxie, refusant d’y croire. Mais chaque recoin de l’Abysse me demande : et si les écrits du Noctilunisme disaient vrai ? Si la fin du monde n’était que ténèbres et néant ? »\n« Alors... l’Abysse est-il invincible ? »\n« Hélas, mon corps épuisé ne tiendra pas assez pour trouver la réponse. »",
          DialogueId = 6202014,
          GUID = "0F86ADEC",
          NextDialogue = 6202015,
          RougeTalkActorType = 3,
          Subtitle = [[
"In past years I clung to the Orthodoxy, refusing to believe such horrors. Yet the Abyss questions me at every turn: what if the Noclunism's scriptures were true...? What if our world's end is truly darkness and nothingness?"
"Then... could the Abyss truly be invincible?"
"Alas, this frail body will not endure long enough to learn the answer."]]
        },
        [6202015] = {
          ContentFR = "« Milton m’a raconté qu’une <H>Épée Sainte</>, <H>Koranu</>, s’est brisée jadis dans le Lac Sacré. C’était une relique de l’Église, dotée d’un pouvoir hors du commun...\nEt j’ai vu, dans cet Abysse, un voyageur portant une lanterne capable de chasser les Umbrés. »\n« S’il existe quelque chose qui puisse vaincre l’Abysse, je crois que ce sont ces deux choses. »",
          DialogueId = 6202015,
          GUID = "0F86AE16",
          NextDialogue = 6202016,
          RougeTalkActorType = 3,
          Subtitle = [[
Milton once told me about a Holy Sword named Koranu, shattered here at the Sacred Lake by accident long ago. It was a relic of the Church, said to bear immense power... And I once saw a traveller whose lantern could drive back the Abyssoids."
"If anything can defeat the Abyss... it may be those two."]]
        },
        [6202016] = {
          ContentFR = "Tu vois qu’il reste encore beaucoup de pages. Ton impatience te pousse à les tourner à toute vitesse — qu’avait-elle donc encore découvert ?\nMais bientôt, tu comprends : le reste de ses notes ne parle plus de l’Abysse.",
          DialogueId = 6202016,
          GUID = "0F86AE40",
          NextDialogue = 6202017,
          RougeTalkActorType = 3,
          Subtitle = [[
You find more pages waiting. You turn them quickly, eager to see what further truths she may have set down.
Yet soon you realise these records speak no more of the Abyss.]]
        },
        [6202017] = {
          ContentFR = "« À toi qui lis ces lignes, merci d’être allé si loin. Je t’en prie, souviens-toi d’eux pour moi. »",
          DialogueId = 6202017,
          GUID = "0F86AE6A",
          NextDialogue = 6202018,
          RougeTalkActorType = 3,
          Subtitle = "\"To the one reading this... thank you for coming so far. I ask only this: remember them for me.\""
        },
        [6202018] = {
          ContentFR = "Ses mots t’arrachent un instant à l’Abysse, et t’emportent ailleurs :\nun petit dortoir dans le camp des chevaliers d’Élysium, baigné de lumière dorée.\nTu ouvres le journal d’une jeune chevalière, et son histoire, celle de ses trois compagnons, t’y attend.",
          DialogueId = 6202018,
          GUID = "0F86AE94",
          NextDialogue = 6202019,
          RougeTalkActorType = 3,
          Subtitle = "For a fleeting moment, her words carry you elsewhere, far from the Abyss — to the Elysian Knights' camp.\nA small, lamplit dormitory, warm with quiet light. You open a young Knight's journal... and find the story of her and three companions."
        },
        [6202019] = {
          ContentFR = "Ils s’étaient entraînés ensemble :\n« Vous formez presque une escouade, tous les quatre ! — le maître d’armes nous avait répété ça tant de fois que Flynn avait fini par le prendre au sérieux et proposé de nous trouver un nom. Cathy, évidemment, avait suivi aussitôt — ces deux-là étaient toujours en train de chahuter. Mais je n’aurais jamais cru que Milton se prêterait à ce jeu. »\n« Avait-il, lui aussi, des rêves de héros cachés ? »\n« \"Crépuscule Silencieux\" ou \"Patates Vaillantes\" — c’étaient les deux noms proposés par Flynn et Cathy. Milton et moi avons voté sans hésiter pour le premier. Étant donné que le repas du jour était un ragoût de pommes de terre, je soupçonne fortement Cathy d’avoir improvisé le sien en mangeant. »\n« Quant à Flynn et son \"Crépuscule\"... Personne d’autre n’aurait remarqué. Mais nous savions tous qu’il rendait là un hommage discret à son chevalier préféré, le \"Chevalier de l’Aube Lunaire\".",
          DialogueId = 6202019,
          GUID = "0F86AEBE",
          NextDialogue = 6202020,
          RougeTalkActorType = 3,
          Subtitle = "They trained together:\n\"'You four are practically a squad,' the instructor always said. So Flynn took it seriously and insisted we choose a squad name. Kathy, of course, chimed in — those two were always fooling around. But I never thought Milton would humour them. Does he secretly nurse some kind of hero complex?\"\n\"'Hushed Dusk' versus 'Valiant Potatoes' — Flynn's and Kathy's suggestions. Milton and I chose the first without hesitation. Considering the day's lunch was potato stew, I suspect Kathy coined hers on the spot.\"\n\"As for Flynn's 'Dusk'... outsiders might not see it, but we all knew it was a secret homage to his beloved Moonrise Knight.\""
        },
        [6202020] = {
          ContentFR = "Ils avaient combattu ensemble :\n« En marche, Cathy disparaissait toujours sans qu’on s’en aperçoive. Au début, on s’inquiétait, mais elle réapparaissait chaque fois à l’endroit le plus improbable pour nous faire sursauter. À force, on n’y faisait plus attention. Mais comment faisait-elle ? Son cerveau n’est clairement pas taillé pour apprendre une magie de téléportation... »\n« Milton, ce rat de bibliothèque, avait même emporté des livres au front en disant qu’il les lirait pendant ses temps libres. Incroyable... »\n« Puis un jour, une flèche enflammée de l’Empire a réduit sa pile en cendres. Il traîna toute la journée une mine sombre comme la nuit... Franchement, il aurait dû remercier ce soldat de l’Empire : son paquetage avait au moins perdu les deux tiers de son poids. »",
          DialogueId = 6202020,
          GUID = "0F86AEE8",
          NextDialogue = 6202021,
          RougeTalkActorType = 3,
          Subtitle = "They fought together:\n\"On marches, Kathy would always vanish. At first we panicked, but she always turned up again in the strangest places, giving us a fright. In time, we grew used to it. Still... how does she manage it? She's hardly the type to master teleportation magic...\"\n\"Milton, that hopeless bookworm, actually carried books onto the battlefield, claiming he'd read in spare moments. Unbelievable...\"\n\"Later, one of the Empire's fire arrows burned the lot to ash. He sulked for an entire day. Honestly, he should have thanked that soldier — his pack was at least two-thirds lighter afterwards.\""
        },
        [6202021] = {
          ContentFR = "Ils avaient accepté leur mission ensemble :\n« Pour éviter les ennuis, je n’ai rien dit à mes parents de mon inscription à l’expédition contre l’Abysse — seulement à mon frère. Mais lui aussi s’est mis à me sermonner, parlant de complot de l’Église et jurant que le Roi Démon ferait de nous tous des sacrifices... C’était épuisant. »\n« En vérité, l’idée d’affronter l’Abysse ne m’attirait pas du tout. Mais Flynn était tellement enthousiaste que je n’ai pas eu le cœur de refuser. Dans les campagnes précédentes, nous n’avions jamais été en première ligne, nous perdions plus que nous ne gagnions. Il devait rêver d’avoir enfin l’occasion de se prouver... Alors je l’ai suivi, pour l’aider à réaliser son rêve de chevalier. Après tout, tant qu’on reste ensemble, peu importe où l’on va. »",
          DialogueId = 6202021,
          GUID = "0F86AF12",
          NextDialogue = 6202022,
          RougeTalkActorType = 3,
          Subtitle = "They undertook the mission together:\n\"To avoid arguments, I never told my parents I'd signed up for the Abyss expedition — only my brother. But even he scolded me, calling it a Church plot, swearing the Demon King would make sacrifices of us... Ugh. All that nagging was exhausting.\"\n\"Truthfully, I never cared about fighting the Abyss. But Flynn was so eager, I couldn't turn him down. In our past battles we were never at the front — we lost more often than we won. He must have longed for a chance to prove himself... So I signed up too — just to help him chase that dream of being a true Knight. As long as we stick together, it doesn't matter where we go.\""
        },
        [6202022] = {
          ContentFR = "...",
          DialogueId = 6202022,
          GUID = "0F86AF3C",
          NextDialogue = 6202023,
          RougeTalkActorType = 3,
          Subtitle = "..."
        },
        [6202023] = {
          ContentFR = "Tu tournes encore quelques pages, et atteins la dernière.",
          DialogueId = 6202023,
          GUID = "0F86AF66",
          NextDialogue = 6202024,
          RougeTalkActorType = 3,
          Subtitle = "You reach the final page."
        },
        [6202024] = {
          ContentFR = "« Ô dieux silencieux — si, comme Milton le croyait, Votre regard est réellement posé sur nous... accordez-moi cette dernière grâce. »\n« Laissez mon âme rejoindre la leur. »\n« Alors je Vous pardonnerai — Votre indifférence, Votre cruauté. Je pardonnerai chaque épreuve que Vous nous avez imposée, chaque mensonge que Vous avez tissé. »",
          DialogueId = 6202024,
          GUID = "0F86AF90",
          NextDialogue = 6202025,
          RougeTalkActorType = 3,
          Subtitle = "\"O silent gods — if, as Milton believed, Your gaze is truly upon us... then I beg You: grant me one last mercy.\"\n\"Let my soul be reunited with theirs.\"\n\"Then I will forgive You — Your indifference, Your cruelty. I will forgive every trial You set before us, every lie You wove.\""
        },
        [6202025] = {
          ContentFR = "<H>« Mes ailes n’ont plus besoin de la clarté de la Pleine Lune. Qu’un vent léger, seulement, me porte là où ils m’attendent. »</>",
          DialogueId = 6202025,
          GUID = "0F86AFBA",
          NextDialogue = 6202026,
          RougeDialogueMainIcon = "Texture2D'/Game/UI/Texture/Dynamic/Image/RougeLike/T_Rouge_Story13.T_Rouge_Story13'",
          RougeTalkActorType = 3,
          Subtitle = "\"My wings no longer need the radiance of the full moon. I ask only for a soft wind, to bear me home — to where they wait.\""
        },
        [6202026] = {
          ContentFR = "Tu refermes le carnet. La chaleur de ses pages subsiste encore au bout de tes doigts.",
          DialogueId = 6202026,
          GUID = "0F86AFE4",
          NextDialogue = 6202027,
          RougeTalkActorType = 3,
          Subtitle = "You close the notebook. The warmth of its pages lingers against your fingertips."
        },
        [6202027] = {
          ContentFR = "« Je vous le promets... je briserai ce cycle. Et, sous l’éclat de la Pleine Lune, vous serez réunis. »",
          DialogueId = 6202027,
          GUID = "0F86B00E",
          RougeTalkActorType = 2,
          SpeakNpcId = 910004,
          Subtitle = "\"I promise... I will break this cycle. And when the full moon shines, it will guide you back to one another.\""
        },
        [7002001] = {
          ContentFR = "Les présents s’entassent en vrac, apportés les uns après les autres au fil des jours.\nEn y regardant de plus près, on distingue des fleurs sauvages, un bol de soupe désormais froid mais encore parfumé, une boîte à musique rayée mais finement ouvragée, ou encore une boîte de guimauves décorée d’un petit oiseau...\nParmi tout cela, un paquet sans nom attire l’attention : un simple coffret noué d’un ruban maladroit. À l’intérieur repose un flacon du meilleur antidouleur de l’Empire. L’intention est touchante, mais offrir un tel remède à quelqu’un plongé dans le coma semble, pour le moins, inutile.",
          DialogueId = 7002001,
          GUID = "11875DCA",
          Subtitle = [[
The care packages are scattered across the room. They seem to have been brought in by various individuals over the past few days.
On closer inspection, the packages reveal an assortment of thoughtful items: a bouquet of wildflowers, a bowl of now-cold but still aromatic meat soup, a scratched yet beautifully crafted music box, and a tin of cotton candy with a drawing of a little bird on its surface...
Among these items lies a plain gift box tied with a clumsily made ribbon bow, missing a name tag. Inside is a bottle of the Empire's finest painkiller. While the gesture is undoubtedly kind, gifting a painkiller to someone in a coma feels, perhaps, a little misplaced.]]
        },
        [7003001] = {
          ContentFR = "Ces derniers jours, plusieurs agressions d’une extrême brutalité ont eu lieu dans la cité extérieure de Givrelac. Les scènes de crime sont chaotiques et sanglantes.\nTous les citoyens sont instamment priés de rester chez eux la nuit, portes et fenêtres bien verrouillées.\nPour ceux qui disposent d’un permis de port d’armes : si vous croisez l’agresseur, n’essayez en aucun cas de riposter, c’est trop dangereux. Sauvez votre vie avant tout.\nToute information sur l’agresseur doit être communiquée immédiatement aux Veilleurs, à l’attention de Rhythm Fischer.\nQue l’Empereur protège ses fidèles sujets en ces heures sombres.\nToute gloire à l’Empereur.",
          DialogueId = 7003001,
          GUID = "118801DA",
          Subtitle = "Multiple brutal assaults have recently occurred in the outer city. The attacks were exceptionally violent, leaving behind chaotic scenes. Citizens are strongly urged to stay indoors at night and keep their doors and windows securely locked.\nFor citizens holding a weapons permit: If you encounter the perpetrator, do not attempt to retaliate — it's extremely dangerous! Please prioritise your safety above all else.\nIf you have any information regarding the perpetrator, please contact the Escort immediately, attention: Rhythm Fischer.\nThe Emperor shall protect his loyal subjects through these trying times. All glory to our Emperor."
        },
        [10010101] = {
          Camera = "67.539062,-1123.730225,550.733276,0.000081,-22.799314,91.999741,35.0,1000.0,false,Manual,2.8",
          ContentFR = "Berry, je...",
          DefaultLookAt = "KeepState",
          DialogueId = 10010101,
          DisableMouth = 1,
          Duration = 1.5,
          ExStoryInfo = "Player",
          GUID = "190F2A32",
          RelatedWikiId = {
            [1] = 304001,
            [2] = 204001,
            [3] = 408001,
            [4] = 201001
          },
          SpeakNpcId = 100001,
          Subtitle = "Berry, I...",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2A32"
        },
        [10010102] = {
          ContentFR = "Chut.",
          DialogueId = 10010102,
          DisableMouth = 1,
          Duration = 3,
          GUID = "190F2A5C",
          SpeakNpcId = 100003,
          Subtitle = "Ssh...",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2A5C"
        },
        [10010103] = {
          ContentFR = "Tu vas bien ?",
          DialogueId = 10010103,
          DisableMouth = 1,
          Duration = 2,
          GUID = "190F2A86",
          SpeakNpcId = 100003,
          Subtitle = "Are you all right?",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2A86"
        },
        [10010104] = {
          ContentFR = "Hm.",
          DialogueId = 10010104,
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "190F2AB0",
          SpeakNpcId = 100001,
          Subtitle = "Yeah.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2AB0"
        },
        [10010105] = {
          ContentFR = "Repose-toi encore un peu. Je reste là, je ne vais nulle part.",
          DialogueId = 10010105,
          DisableMouth = 1,
          Duration = 5,
          GUID = "190F2ADA",
          SpeakNpcId = 100003,
          Subtitle = "Get some more sleep. I won't leave — I'll be right here when you wake up.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2ADA"
        },
        [10010106] = {
          ContentFR = "Pas besoin. Redescendons, retournons au village.",
          DialogueId = 10010106,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "190F2B04",
          SpeakNpcId = 100001,
          Subtitle = "It's okay. We should get down the mountain and head to the village.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B04"
        },
        [10010107] = {
          ContentFR = "Maintenant ? Mais... depuis deux jours, on entend ces rugissements là-bas...",
          DialogueId = 10010107,
          DisableMouth = 1,
          Duration = 4,
          GUID = "190F2B2E",
          SpeakNpcId = 100003,
          Subtitle = "You wanna go back? There've been roars coming from there for days...",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B2E"
        },
        [10010108] = {
          ContentFR = "Je me disais que si on pouvait rentrer, récupérer nos armes...",
          DialogueId = 10010108,
          DisableMouth = 1,
          Duration = 4.5,
          ExStoryInfo = "Player",
          GUID = "190F2B58",
          SpeakNpcId = 100001,
          Subtitle = "I was thinking, if we could make it home and grab our weapons—",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B58"
        },
        [10010109] = {
          ContentFR = "Avec ta force, tu trouveras forcément une issue.",
          DialogueId = 10010109,
          DisableMouth = 1,
          Duration = 2.5,
          ExStoryInfo = "Player",
          GUID = "190F2B82",
          SpeakNpcId = 100001,
          Subtitle = "And with your strength, you'll find a way out.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B82"
        },
        [10010110] = {
          ContentFR = "Et puis, rester ici... personne ne viendra nous sauver, pas vrai ?",
          DialogueId = 10010110,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "Player",
          GUID = "190F2B83",
          SpeakNpcId = 100001,
          Subtitle = "No one's going to save us no matter how long we stay here anyway.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B83"
        },
        [10010111] = {
          ContentFR = "... D’accord. Allons-y.",
          DialogueId = 10010111,
          DisableMouth = 1,
          Duration = 3,
          GUID = "190F2BAC",
          SpeakNpcId = 100003,
          Subtitle = "...Let's go then.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAC"
        },
        [10010112] = {
          ContentFR = "Doucement.",
          DialogueId = 10010112,
          GUID = "190F2BAD",
          SpeakNpcId = 100003,
          Subtitle = "Take it easy.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAD"
        },
        [10010113] = {
          ContentFR = "Attention où tu mets les pieds, ne trébuche pas.",
          DialogueId = 10010113,
          GUID = "190F2BAE",
          SpeakNpcId = 100003,
          Subtitle = "Watch your step.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAE"
        },
        [10010114] = {
          ContentFR = "Ta blessure n’est pas encore guérie... tu es {性别:sûr|sûre} que ça ira ?",
          DialogueId = 10010114,
          GUID = "190F2BAF",
          NextDialogue = 10010115,
          SpeakNpcId = 100003,
          Subtitle = "You're not fully recovered. Are you sure you can do this?",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAF"
        },
        [10010115] = {
          ContentFR = "Je vais bien. Juste quelques égratignures.",
          DialogueId = 10010115,
          ExStoryInfo = "Player",
          GUID = "190F2BB1",
          NextDialogue = 10010116,
          SpeakNpcId = 100001,
          Subtitle = "I'm okay. It's just a few scratches.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BB1"
        },
        [10010116] = {
          ContentFR = "Ne force pas trop. Tu auras besoin de ton énergie si jamais on croise un Souillé.",
          DialogueId = 10010116,
          GUID = "190F2BB2",
          SpeakNpcId = 100003,
          Subtitle = "Don't push yourself too hard. We still have to save some strength for those Filthoids.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BB2"
        },
        [10010201] = {
          ContentFR = "Si tu veux vivre, dis-moi la vérité.",
          DialogueId = 10010201,
          Duration = 4,
          GUID = "190F3A9A",
          SpeakNpcId = 100005,
          Subtitle = "Tell me the truth if you want to live.",
          VoiceName = "voice/$Locale$/story/1001/100102/190F3A9A"
        },
        [10010202] = {
          ContentFR = "Pourquoi es-tu ici ? Qui sont tes compagnons ?",
          DialogueId = 10010202,
          Duration = 5,
          GUID = "190F3AC4",
          SpeakNpcId = 100005,
          Subtitle = "Why are you here, who's with you,",
          VoiceName = "voice/$Locale$/story/1001/100102/190F3AC4"
        },
        [10010203] = {
          ContentFR = "Et toi... qui es-tu ?",
          DialogueId = 10010203,
          Duration = 3.5,
          GUID = "190F3AEE",
          SpeakNpcId = 100005,
          Subtitle = "and who on earth are you?",
          VoiceName = "voice/$Locale$/story/1001/100102/190F3AEE"
        },
        [10010204] = {
          Camera = "10000,11000,2000,0.000046,-4.799929,73.987312,35.0,150.0,false,Manual,2.8",
