          Duration = 2,
          GUID = "190F3AF1"
        },
        [10010301] = {
          Content = "我们现在赤手空拳，尽可能避开它们吧。",
          DialogueId = 10010301,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "190F4B02",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100103/190F4B02"
        },
        [10010401] = {
          ContentFR = "Prends cette épée. Elle pourra toujours servir.",
          DialogueId = 10010401,
          DisableMouth = 1,
          Duration = 3,
          GUID = "190F5B6A",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001
          },
          SpeakNpcId = 100003,
          Subtitle = "Take that sword with you. It might be helpful one day.",
          TalkActionId = {
            [1] = "100001:FuXiong_Start"
          },
          VoiceName = "voice/$Locale$/story/1001/100104/190F5B6A"
        },
        [10010402] = {
          ContentFR = "Protège-toi. Les Souillés, je m’en charge.",
          DialogueId = 10010402,
          DisableMouth = 1,
          Duration = 4,
          GUID = "190F5B94",
          SpeakNpcId = 100003,
          Subtitle = "Keep yourself safe. I'll take care of these Filthoids.",
          TalkActionId = {
            [1] = "100001:FuXiong_End"
          },
          VoiceName = "voice/$Locale$/story/1001/100104/190F5B94"
        },
        [10010501] = {
          Content = "拿起剑的时候，熟悉而陌生的记忆涌上来……",
          DialogueId = 10010501,
          Duration = 3,
          GUID = "190F6BD2",
          NextDialogue = 10010502,
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100105/190F6BD2"
        },
        [10010502] = {
          Content = "……已经很久没有像这样战斗过了。",
          DialogueId = 10010502,
          Duration = 2.5,
          GUID = "190F6BFC",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100105/190F6BFC"
        },
        [10010601] = {
          ContentFR = "Vite. Direction le quai.",
          DialogueId = 10010601,
          Duration = 2,
          GUID = "190F7D0C",
          SpeakNpcId = 100003,
          Subtitle = "Let's head to the wharf.",
          VoiceName = "voice/$Locale$/story/1001/100106/190F7D0C"
        },
        [10010701] = {
          ContentFR = "Tss... Pas un seul bateau n’a été laissé.",
          DialogueId = 10010701,
          GUID = "190F8CA2",
          NextDialogue = 10010702,
          SpeakNpcId = 100003,
          Subtitle = "Ugh, they didn't even leave one single boat.",
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CA2"
        },
        [10010702] = {
          ContentFR = "Quand les Souillés ont attaqué, tu étais encore au village, non ? Si tu n’étais pas revenue me chercher, tu aurais pu partir avec eux.",
          DialogueId = 10010702,
          ExStoryInfo = "Player",
          GUID = "190F8CCC",
          NextDialogue = 10010703,
          SpeakNpcId = 100001,
          Subtitle = "You were at the village when the Filthoids came, weren't you? If it wasn't for coming back for me, you could have escaped with them.",
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CCC"
        },
        [10010703] = {
          ContentFR = "Ne dis pas de bêtises. Tu aurais fait pareil pour moi. Cherchons plutôt le long de la côte... il y a peut-être une vieille embarcation.",
          DialogueId = 10010703,
          GUID = "190F8CF6",
          SpeakNpcId = 100003,
          Subtitle = "Don't be silly. You'd have done the same for me. Let's search along the shore and see if there's any old boats or something.",
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CF6"
        },
        [10010704] = {
          Content = "别说傻话。我们先沿着海岸找找有没有废旧的船。",
          DialogueId = 10010704,
          GUID = "190F8CF7",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CF7"
        },
        [10010801] = {
          Camera = "233.692749,98.025391,337.437744,0.000525,-38.008308,-170.090546,35.000008,500.0,false,Disable,22.0",
          ContentFR = "C’est... Ça a dû tomber quand ils ont fui.",
          DefaultLookAt = "KeepState",
          DialogueId = 10010801,
          ExStoryInfo = "Player",
          FinalCamera = "233.692749,98.025391,306.806396,0.000525,-38.008308,-170.090546,35.000008,500.0,false,Disable,22.0",
          GUID = "190F9D0A",
          LookAt = {
            [1] = "100001:p(QuestPoint102)",
            [2] = "100003:p(QuestPoint102)"
          },
          NextDialogue = 10010802,
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 303001
          },
          SpeakNpcId = 100001,
          Subtitle = "These are... Someone must have lost them when they ran away.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1001/100108/190F9D0A"
        },
        [10010802] = {
          Camera = "45.787476,-42.09668,191.500977,0.000512,-35.408981,145.509857,30.0,500.0,false,Disable,22.0",
          ContentFR = "Hmm. Prends-la. Mieux vaut être armés.",
          DefaultLookAt = "KeepState",
          DialogueId = 10010802,
          FinalCamera = "25.377319,-28.079102,173.898438,0.000512,-35.408981,145.509857,30.0,500.0,false,Disable,22.0",
          GUID = "190F9D34",
          SpeakNpcId = 100003,
          Subtitle = "Hmm, take it. It's always good to be well-armed.",
          TalkActionId = {
            [1] = "100003:Agree"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1001/100108/190F9D34"
        },
        [10010901] = {
          Content = "这边。",
          DialogueId = 10010901,
          Duration = 2,
          GUID = "190FAD9D",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100109/190FAD9D"
        },
        [10011001] = {
          ContentFR = "D’autres Souillés arrivent...",
          DialogueId = 10011001,
          GUID = "190FBDDA",
          NextDialogue = 10011002,
          SpeakNpcId = 100003,
          Subtitle = "More Filthoids are coming...",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBDDA"
        },
        [10011002] = {
          ContentFR = "{nickname}, ne t’éloigne pas de moi. Si besoin, on utilisera nos signaux.",
          DialogueId = 10011002,
          GUID = "190FBE04",
          NextDialogue = 10011003,
          SpeakNpcId = 100003,
          Subtitle = "Stay close, . If necessary, give out the secret signals.",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE04"
        },
        [10011003] = {
          ContentFR = "Tu t’en souviens, n’est-ce pas ? Ceux qu’on a inventés, en montant la première fois pour éviter les bêtes.",
          DialogueId = 10011003,
          GUID = "190FBE05",
          NextDialogue = 10011004,
          SpeakNpcId = 100003,
          Subtitle = "We made them up earlier so as not to alert the Filthoids up the mountain, remember?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE05"
        },
        [10011004] = {
          ContentFR = "Bien sûr.",
          DialogueId = 10011004,
          ExStoryInfo = "Player",
          GUID = "190FBE06",
          NextDialogue = 10011005,
          SpeakNpcId = 100001,
          Subtitle = "Yes.",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE06"
        },
        [10011005] = {
          ContentFR = "D’accord, on vérifie. Deux tapotements sur l’épaule droite ?",
          DialogueId = 10011005,
          GUID = "190FBE07",
          NextDialogue = 10011006,
          SpeakNpcId = 100003,
          Subtitle = "Alright, a quick check — Two pats on the right shoulder means...?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE07"
        },
        [10011006] = {
          ContentFR = "« Attention derrière toi. »",
          DialogueId = 10011006,
          ExStoryInfo = "Player",
          GUID = "190FBE08",
          NextDialogue = 10011007,
          SpeakNpcId = 100001,
          Subtitle = "\"Watch your back.\"",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE08"
        },
        [10011007] = {
          ContentFR = "Deux frappes sur la poitrine ?",
          DialogueId = 10011007,
          GUID = "190FBE09",
          NextDialogue = 10011008,
          SpeakNpcId = 100003,
          Subtitle = "And two taps on the chest?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE09"
        },
        [10011008] = {
