        },
        [10011702] = {
          Camera = "112.41748,326.53125,131.15976,0.001058,1.609964,-59.853107,35.0,100000.0,true,DoNotOverride,2.8",
          ContentFR = "Les soldats ont fait de leur mieux. Les Souillés qui pullulent sur l’île, ça, on ne pouvait pas le prévoir. Mais la journée n’est pas perdue pour autant...",
