          DisableMouth = 1,
          Duration = 7.6,
          GUID = "191030DC",
          SpeakNpcId = 100006,
          Subtitle = "The soldiers did their best with the Filthoids. These are indeed unforeseen circumstances.\nBut we did find something valuable on this island today—",
          VoiceName = "voice/$Locale$/story/1001/100117/191030DC"
        },
        [10011703] = {
          ContentFR = "On a trouvé des installations d’alchimie qu’elle utilisait, et même un dirigeable avec un numéro de série de la Légion.",
          DialogueId = 10011703,
          DisableMouth = 1,
          Duration = 5.4,
          GUID = "19103106",
          SpeakNpcId = 100006,
          Subtitle = "Alchemical tools she has used and an airship with a Legion serial number on it.",
          VoiceName = "voice/$Locale$/story/1001/100117/19103106"
        },
        [10011704] = {
          Camera = "126.422852,269.644531,140.342804,0.001063,-0.790492,125.942245,35.0,100000.0,true,DoNotOverride,2.8",
