          Duration = 3,
          GUID = "19103130",
          SpeakNpcId = 100005,
          Subtitle = "You realise we're looking for \"No. 0,\" not this useless junk, right?",
          VoiceName = "voice/$Locale$/story/1001/100117/19103130"
        },
        [10011705] = {
          ContentFR = "Dix ans de recherches, évidemment que c’est compliqué... Mais nos unités maritimes ont intercepté plusieurs bateaux de fuyards. Avec un peu de chance, on pourra leur arracher quelques",
          DialogueId = 10011705,
          DisableMouth = 1,
          Duration = 9.5,
          GUID = "1910315A",
          SpeakNpcId = 100006,
          Subtitle = "We've been searching for over a decade... But our maritime unit intercepted several of the villagers' vessels.\nThey might be able to dig up some—",
          VoiceName = "voice/$Locale$/story/1001/100117/1910315A"
        },
        [10011706] = {
          ContentFR = "Des coups de feu ?",
          DialogueId = 10011706,
