          Subtitle = "If you wish to save all this...",
          VoiceName = "voice/$Locale$/story/1001/100119/191052D5"
        },
        [10012001] = {
          ContentFR = "Tiens bon ! J’ai presque...",
          DefaultLookAt = "Self",
          DialogueId = 10012001,
          DisableMouth = 1,
          Duration = 3,
          GUID = "191061EA",
          LookAt = {
            [1] = "100005:n(100003)"
          },
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 201002
          },
          SpeakNpcId = 100003,
          Subtitle = "Hang in there! I got you...",
          VoiceName = "voice/$Locale$/story/1001/100120/191061EA"
        },
        [10012002] = {
          ContentFR = "Berry !",
          DialogueId = 10012002,
          DisableMouth = 1,
          Duration = 1,
          ExStoryInfo = "Player",
          GUID = "191061EB",
          SpeakNpcId = 100001,
          Subtitle = "Berry!",
          VoiceName = "voice/$Locale$/story/1001/100120/191061EB"
        },
        [10012003] = {
          ContentFR = "Abandonne, n° 0. Même la lame la plus solide finit par se briser.",
          DefaultLookAt = "KeepState",
          DialogueId = 10012003,
          DisableMouth = 1,
          Duration = 4.5,
          GUID = "19106214",
          LookAt = {
            [1] = "100005:n(100003)"
          },
          SpeakNpcId = 100005,
          Subtitle = "Give it up, No. 0. Even the toughest blade has its breaking point.",
          VoiceName = "voice/$Locale$/story/1001/100120/19106214"
        },
        [10012004] = {
          ContentFR = "Viens avec moi, et tu vivras... tout comme cet enfant que tu tiens tant à protéger.",
          DialogueId = 10012004,
          DisableMouth = 1,
          Duration = 5.5,
          GUID = "19106218",
          SpeakNpcId = 100005,
          Subtitle = "Come back with me, and you'll live — so will this kid you care so much about.",
          VoiceName = "voice/$Locale$/story/1001/100120/19106218"
        },
        [10012005] = {
          ContentFR = "Sinon, {性别:il|elle} mourra...",
          DialogueId = 10012005,
          DisableMouth = 1,
          Duration = 3.5,
          GUID = "19106219",
          SpeakNpcId = 100005,
          Subtitle = "Otherwise, {性别:he|she} will—",
          VoiceName = "voice/$Locale$/story/1001/100120/19106219"
        },
        [10012006] = {
          ContentFR = "... Promets-le-moi.",
          DefaultLookAt = "KeepState",
          DialogueId = 10012006,
          DisableMouth = 1,
          Duration = 1.7,
          GUID = "1910623E",
          SpeakNpcId = 100003,
          Subtitle = "...Give me your word.",
          VoiceName = "voice/$Locale$/story/1001/100120/1910623E"
        },
        [10012007] = {
          ContentFR = "Hmm ?",
          DialogueId = 10012007,
          DisableMouth = 1,
          Duration = 1,
          GUID = "1910623F",
          SpeakNpcId = 100005,
          Subtitle = "Hmm?",
          VoiceName = "voice/$Locale$/story/1001/100120/1910623F"
        },
        [10012008] = {
          ContentFR = "Je viens avec toi, mais tu dois {性别:le|la} laisser partir.",
          DefaultLookAt = "KeepState",
          DialogueId = 10012008,
          DisableMouth = 1,
          Duration = 4,
          GUID = "19106268",
          LookAt = {
            [1] = "100007:n(100005)"
          },
          SpeakNpcId = 100003,
          Subtitle = "I'll go back with you, but you have to promise to let {性别:him|her} go.",
          VoiceName = "voice/$Locale$/story/1001/100120/19106268"
        },
        [10012009] = {
          ContentFR = "Promets-le ! Sinon, tu ramèneras nos deux cadavres !",
          DefaultLookAt = "KeepState",
          DialogueId = 10012009,
          DisableMouth = 1,
          Duration = 3.5,
          GUID = "19106292",
          SpeakNpcId = 100003,
          Subtitle = "Give me your word! Or, you can take two corpses back!",
          VoiceName = "voice/$Locale$/story/1001/100120/19106292"
        },
        [10012010] = {
          ContentFR = "Tu te méprends. Ce n’est pas une négociation, c’est un ordre.",
          DefaultLookAt = "Self",
          DialogueId = 10012010,
          DisableMouth = 1,
          Duration = 5.5,
          GUID = "190F7C64",
          LookAt = {
            [1] = "100005:n(100005)"
          },
          SpeakNpcId = 100005,
          Subtitle = "Perhaps I wasn't clear — This is not a negotiation, it's an order.",
          VoiceName = "voice/$Locale$/story/1001/100106/190F7C64"
        },
        [10012011] = {
          ContentFR = "... Berry.",
          DefaultLookAt = "KeepState",
          DialogueId = 10012011,
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "191062E6",
          LookAt = {
            [1] = "100005:n(100003)"
          },
          SpeakNpcId = 100001,
          Subtitle = "...Berry.",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E6"
        },
        [10012012] = {
          ContentFR = "... ?! Tu... !",
          DialogueId = 10012012,
          DisableMouth = 1,
          Duration = 1,
          GUID = "191062E7",
          SpeakNpcId = 100003,
          Subtitle = "...?! You...!",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E7"
        },
        [10012013] = {
          ContentFR = "Fuis, et reste en vie.",
          DialogueId = 10012013,
          DisableMouth = 1,
          Duration = 1.5,
          ExStoryInfo = "Player",
          GUID = "191062E8",
          SpeakNpcId = 100001,
          Subtitle = "Get out of here, and live.",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E8"
        },
        [10012014] = {
          ContentFR = "Noooon !",
          DialogueId = 10012014,
          DisableMouth = 1,
          Duration = 1.5,
          GUID = "191062E9",
          SpeakNpcId = 100003,
          Subtitle = "No—!!",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E9"
        },
        [10012015] = {
          ContentFR = "Petite question, {nickname}. Le signal des trois clignements signifie...",
          DialogueId = 10012015,
          Duration = 5,
          GUID = "191062F0",
          SpeakNpcId = 100003,
          Subtitle = "Quick question, . The \"three quick blinks\" means—",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F0"
        },
        [10012016] = {
          ContentFR = "Je m’en souviens, Berry ! Trois clignements signifie...",
          DialogueId = 10012016,
          Duration = 6,
          ExStoryInfo = "Player",
          GUID = "191062F1",
          SpeakNpcId = 100001,
          Subtitle = "I've got this, Berry. Three quick blinks means...",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F1"
        },
        [10012017] = {
          ContentFR = "« Même si tu es {性别:tout seul, tu dois rester fort|toute seule, tu dois rester forte} et continuer à vivre. »",
          DialogueId = 10012017,
          DialoguePanelType = "None",
          Duration = 5,
          ExStoryInfo = "Player",
          GUID = "191062F2",
          SpeakNpcId = 100001,
          Subtitle = "\"Even if left all alone, you should be brave and live on.\"",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F2"
        },
        [10012018] = {
          ContentFR = "« Jusqu’au jour où nous nous reverrons. »",
          DialogueId = 10012018,
          DialoguePanelType = "None",
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "191062F3",
          SpeakNpcId = 100001,
          Subtitle = "\"Until the day we meet again.\"",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F3"
        },
        [10012101] = {
          ContentFR = "C’est...",
          DialogueId = 10012101,
          Duration = 1.5,
          GUID = "19107252",
          NextDialogue = 10012102,
          SpeakNpcId = 100005,
          Subtitle = "That is...",
          VoiceName = "voice/$Locale$/story/1001/100121/19107252"
        },
        [10012102] = {
          ContentFR = "Le n° 0 n’est pas censé pouvoir libérer tout son pouvoir... pourquoi... ?",
          DialogueId = 10012102,
          Duration = 2.5,
          GUID = "1910727C",
          NextDialogue = 10012103,
          SpeakNpcId = 100005,
          Subtitle = "No. 0 is not supposed to release all her powers yet. Why...",
          VoiceName = "voice/$Locale$/story/1001/100121/1910727C"
        },
        [10012103] = {
          ContentFR = "Non, ce n’est pas son pouvoir, c’est la Résonance.",
          DialogueId = 10012103,
          Duration = 3,
          GUID = "1910727D",
          NextDialogue = 10012104,
          SpeakNpcId = 100005,
          Subtitle = "No, that's not her power, it's Resonance.",
          VoiceName = "voice/$Locale$/story/1001/100121/1910727D"
        },
        [10012104] = {
          ContentFR = "... {性别:Ce gamin|Cette gamine} qu’elle protège... {性别:serait-il|serait-elle} le nouveau réceptacle du pouvoir de Résonance ?",
          DialogueId = 10012104,
          Duration = 2.5,
          GUID = "191072A6",
          NextDialogue = 10012110,
          SpeakNpcId = 100005,
          Subtitle = "...That brat she's trying to protect... That's the new receptacle for the Power of Resonance?",
          VoiceName = "voice/$Locale$/story/1001/100121/191072A6"
        },
        [10012105] = {
          ContentFR = "... La réapparition simultanée du pouvoir de \"Résonance\" et du \"n° 0\"... que cela signifie-t-il ?",
          DialogueId = 10012105,
          Duration = 3,
          GUID = "191072D0",
          SpeakNpcId = 100005,
          Subtitle = "The reappearance of the \"Power of Resonance\" and \"No. 0\" together... What could this possibly mean...?",
          VoiceName = "voice/$Locale$/story/1001/100121/191072D0"
        },
        [10012110] = {
          ContentFR = "À bien y réfléchir, l’apparence de {性别:ce gamin|cette gamine} tout à l’heure était...",
          DialogueId = 10012110,
          GUID = "191072D1",
          NextDialogue = 10012105,
          SpeakNpcId = 100005,
          Subtitle = "Come to think of it,  {性别:his|her} face was...",
          VoiceName = "voice/$Locale$/story/1001/100121/191072D1"
        },
        [10012201] = {
          ContentFR = "Vite !",
          DialogueId = 10012201,
          Duration = 2,
          GUID = "191082BA",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 201003
          },
          SpeakNpcId = 100003,
          Subtitle = "Run!",
          VoiceName = "voice/$Locale$/story/1001/100122/191082BA"
        },
        [10012202] = {
          ContentFR = "Tu ne m’échapperas pas !",
          DialogueId = 10012202,
          Duration = 2,
          GUID = "191082BB",
          SpeakNpcId = 100006,
          Subtitle = "You can't get away!",
          VoiceName = "voice/$Locale$/story/1001/100122/191082BB"
        },
        [10012301] = {
          Content = "你的伤……好些没有？",
          DialogueId = 10012301,
          Duration = 2,
          GUID = "19109322",
          NextDialogue = 10012302,
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100123/19109322"
        },
        [10012302] = {
          Content = "好多了，只是还有些头晕……",
          DialogueId = 10012302,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1910934C",
          NextDialogue = 10012303,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100123/1910934C"
        },
        [10012303] = {
          Content = "那就好，不要勉强自己。",
          DialogueId = 10012303,
          Duration = 2,
          GUID = "1910934D",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100123/1910934D"
        },
        [10012401] = {
          ContentFR = "On dirait que quelqu’un a vécu ici.",
          DialogueId = 10012401,
          ExStoryInfo = "Player",
          GUID = "1910A38A",
          NextDialogue = 10012402,
          SpeakNpcId = 100001,
          Subtitle = "It seems someone used to live here.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A38A"
        },
        [10012402] = {
          ContentFR = "C’était chez toi, pas vrai, Berry ?",
          DialogueId = 10012402,
          ExStoryInfo = "Player",
          GUID = "1910A3B4",
          NextDialogue = 10012403,
          SpeakNpcId = 100001,
          Subtitle = "This was your home, am I right, Berry?",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A3B4"
        },
        [10012403] = {
          ContentFR = "... Je...",
          DialogueId = 10012403,
          GUID = "1910A3DE",
          NextDialogue = 10012404,
          SpeakNpcId = 100003,
          Subtitle = "...I...",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A3DE"
        },
        [10012404] = {
          ContentFR = "... Oui. Mais pas seulement moi. Ici, c’était notre maison.",
          DialogueId = 10012404,
          GUID = "1910A408",
          NextDialogue = 10012405,
          SpeakNpcId = 100003,
          Subtitle = "...Yes, and no. It was OUR home.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A408"
        },
        [10012405] = {
          ContentFR = "« Notre » maison ? Pourtant je ne me souviens de rien.",
          DialogueId = 10012405,
          ExStoryInfo = "Player",
          GUID = "1910A432",
          NextDialogue = 10012406,
          SpeakNpcId = 100001,
          Subtitle = "Our home? But I don't remember a thing.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A432"
        },
        [10012406] = {
          ContentFR = "... Ce n’est pas grave. Peut-être que c’est mieux ainsi. Quand on sera sortis d’ici, on bâtira une nouvelle maison.",
          DialogueId = 10012406,
          GUID = "1910A433",
          SpeakNpcId = 100003,
          Subtitle = "...It's okay. Maybe it's all for the best. After we make it out, we'll build a new home.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A433"
        },
        [10012501] = {
          Content = "任务失败，请重新开始。",
          DialogueId = 10012501,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1910B3F2",
