        },
        [10019102] = {
          ContentFR = "Ton ▇▇... le pouvoir de ▇▇...",
          DialogueId = 10019102,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1914EEEC",
          SnapShot = "MEMORY",
