        },
        [10030415] = {
          ContentFR = "<I>Je n’ai rien à lui dire.</>",
          DialogueId = 10030415,
          GUID = "191C2EF6",
          NextDialogue = 10030416,
          Subtitle = "I've got nothing to say to her."
        },
        [10030416] = {
          Camera = "17.873657,-44.469727,169.63678,-0.00131,-21.59972,96.626923,35.000008,39.151329,false,DoNotOverride,22",
          ContentFR = "J’ai entendu ce qui s’est passé au bord du Lac du Deuil la dernière fois. Je sais que tu n’as probablement pas envie de la voir.",
          DialogueId = 10030416,
          GUID = "191C2F20",
          NextDialogue = 10030417,
          SpeakNpcId = 200003,
          Subtitle = "I heard about what happened at Lamenting Lake that day. I know you probably don't want to see her.",
          VoiceName = "voice/$Locale$/story/1003/100304/191C2F20"
        },
        [10030417] = {
          Camera = "406.211243,-635.881592,325.041443,-0.001344,-16.600023,119.224098,35.0,240.900818,false,Manual,22.0",
          ContentFR = "Mais tu es {性别:le seul survivant|la seule survivante} de l’<H>attaque</> de cette nuit-là. Je doute qu’elle abandonne.",
          DialogueId = 10030417,
          FinalCamera = "391.624817,-609.80957,316.13501,-0.001344,-16.600023,119.224098,35.0,240.900818,false,Manual,22.0",
          GUID = "191C2F4A",
          NextDialogue = 10030418,
          SpeakNpcId = 200003,
          Subtitle = "But you were the sole survivor of the murder case that night. I doubt she'll give up easily.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100304/191C2F4A"
        },
        [10030418] = {
