        [10030420] = {
          Camera = "80.631256,-105.42334,178.525864,0.000193,-10.403314,115.354118,35.000015,142.834564,false,Manual,22.0",
          DialogueId = 10030420,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "80.489944,-105.125,178.525864,0.000199,-12.403227,110.153175,35.000015,290.266602,false,Manual,22.0",
          GUID = "191C2FC9",
          Scripts = "MoveTo{ActorId{200003},TargetPoint{\"kami_01_leave\"},MoveSpeed{90},Visibility{\"Show\"}}",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 3
        },
        [10030421] = {
          ContentFR = "Les présents s’entassent en vrac, apportés les uns après les autres au fil des jours.\nEn y regardant de plus près, on distingue des fleurs sauvages, un bol de soupe désormais froid mais encore parfumé, une boîte à musique rayée mais finement ouvragée, ou encore une boîte de guimauves décorée d’un petit oiseau...\nParmi tout cela, un paquet sans nom attire l’attention : un simple coffret noué d’un ruban maladroit. À l’intérieur repose un flacon du meilleur antidouleur de l’Empire. L’intention est touchante, mais offrir un tel remède à quelqu’un plongé dans le coma semble, pour le moins, inutile.",
          DialogueId = 10030421,
          GUID = "191C2FF2",
          Subtitle = [[
The care packages are scattered across the room. They seem to have been brought in by various individuals over the past few days.
On closer inspection, the packages reveal an assortment of thoughtful items: a bouquet of wildflowers, a bowl of now-cold but still aromatic meat soup, a scratched yet beautifully crafted music box, and a tin of cotton candy with a drawing of a little bird on its surface...
Among these items lies a plain gift box tied with a clumsily made ribbon bow, missing a name tag. Inside is a bottle of the Empire's finest painkiller. While the gesture is undoubtedly kind, gifting a painkiller to someone in a coma feels, perhaps, a little misplaced.]],
          VoiceName = "voice/$Locale$/story/1003/100304/191C2FF2"
        },
        [10030422] = {
          Camera = "80.631256,-105.42334,178.525864,0.000193,-10.403314,115.354118,35.000015,142.834564,false,Manual,22.0",
          ContentFR = "Si tu veux en savoir plus, va aux Asphodèles. Tes amis t’y attendent depuis des jours.",
          DialogueId = 10030422,
          GUID = "191C2FC8",
          NextDialogue = 10030420,
          SpeakNpcId = 200003,
          Subtitle = "If you want answers, go to The Asphodel and ask your friends. They've been worried about you these past few days.",
          VoiceName = "voice/$Locale$/story/1003/100304/191C2FC8"
        },
        [10030501] = {
          ContentFR = "<I>Mmmh... il y a plein de ballons dans Givrelac... C’est une fête ?</>",
          DialogueId = 10030501,
          DisableMouth = 1,
          GUID = "191C3D12",
          NextDialogue = 10030502,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Huh, there are so many balloons around Icelake... Is it some kind of festival?)",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3D12"
        },
        [10030502] = {
          ContentFR = "<I>Mais malgré ces décorations, l’air reste pesant, froid...</>",
          DialogueId = 10030502,
          DisableMouth = 1,
          GUID = "191C3D3C",
          NextDialogue = 10030503,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(But even with all these festive decorations, the lingering chill in the air is still pretty obvious...)",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3D3C"
        },
        [10030503] = {
          ContentFR = "<I>Il vaut mieux que j’aille voir Snow et l’Étranger, pour savoir ce qui s’est passé pendant mon absence.</>",
          DialogueId = 10030503,
          DisableMouth = 1,
          GUID = "191C3D66",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(I should go check in with Snow and Outsider to find out what's happened while I was unconscious.)",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3D66"
        },
        [10030504] = {
          ContentFR = "Treize personnes... treize personnes ! Disparues en une seule nuit !",
          DialogueId = 10030504,
          Duration = 5,
          GUID = "191C3D90",
          SpeakNpcId = 700036,
          Subtitle = "13 people... 13 people! All gone in a single night!",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3D90"
        },
        [10030505] = {
          ContentFR = "Même rester enfermé à la maison n’est plus sûr... Que va-t-on devenir ?",
          DialogueId = 10030505,
          Duration = 7,
          GUID = "191C3DBA",
          SpeakNpcId = 700038,
          Subtitle = "Even staying home isn't safe anymore. What are we supposed to do?",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3DBA"
        },
        [10030506] = {
          ContentFR = "<I>Soupir...</> Ces vieux os ne me permettront jamais de déménager...",
          DialogueId = 10030506,
          Duration = 7,
          GUID = "191C3DE4",
          SpeakNpcId = 700246,
          Subtitle = "*sigh* ...These old bones couldn't possibly move because of something like this...",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3DE4"
        },
        [10030507] = {
          ContentFR = "Les acteurs tournent dans la boîte à musique, tandis que nous errons dans le labyrinthe de Givrelac ! Le renversement approche, et la Mer du Silence accueille déjà ses invités !",
          DialogueId = 10030507,
          Duration = 12,
          GUID = "191C3E0E",
          SpeakNpcId = 700015,
          Subtitle = "The performers spin inside the music box, while we wander through the maze of Icelake! The fateful twist is near, and the Misty Sea welcomes its new visitors!",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3E0E"
        },
        [10030508] = {
          ContentFR = "N-N’approche pas ! Ne me tue pas... Les Veilleurs... Où sont les Veilleurs ?!",
          DialogueId = 10030508,
          Duration = 9,
          GUID = "191C3E38",
          SpeakNpcId = 700035,
          Subtitle = "S—Stay back! Don't kill me... Escort... Where's the Escort!?",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3E38"
        },
        [10030509] = {
          ContentFR = "Ce... ce n’était pas humain. Un monstre. Forcément un monstre...",
          DialogueId = 10030509,
          Duration = 4,
          GUID = "191C3E62",
          SpeakNpcId = 700034,
          Subtitle = "It was definitely a monster... nothing else could've done this...",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3E62"
        },
        [10030510] = {
          ContentFR = "Ces derniers jours, plusieurs agressions d’une extrême brutalité ont eu lieu dans la cité extérieure de Givrelac. Les scènes de crime sont chaotiques et sanglantes.\nTous les citoyens sont instamment priés de rester chez eux la nuit, portes et fenêtres bien verrouillées.\nPour ceux qui disposent d’un permis de port d’armes : si vous croisez l’agresseur, n’essayez en aucun cas de riposter, c’est trop dangereux. Sauvez votre vie avant tout.\nToute information sur l’agresseur doit être communiquée immédiatement aux Veilleurs, à l’attention de Rhythm Fischer.\nQue l’Empereur protège ses fidèles sujets en ces heures sombres.\nToute gloire à l’Empereur.",
          DialogueId = 10030510,
          GUID = "191C3E8C",
          Subtitle = "Multiple brutal assaults have recently occurred in the outer city. The attacks were exceptionally violent, leaving behind chaotic scenes. Citizens are strongly urged to stay indoors at night and keep their doors and windows securely locked.\nFor citizens holding a weapons permit: If you encounter the perpetrator, do not attempt to retaliate — it's extremely dangerous! Please prioritise your safety above all else.\nIf you have any information regarding the perpetrator, please contact the Escort immediately, attention: Rhythm Fischer.\nThe Emperor shall protect his loyal subjects through these trying times. All glory to our Emperor.",
          VoiceName = "voice/$Locale$/story/1003/100305/191C3E8C"
        },
        [10030601] = {
          ContentFR = "<I>Faire un signe de la main</>",
          DialogueId = 10030601,
          GUID = "191C4D7A",
          NextDialogue = 10030603,
          Subtitle = "Wave hello."
        },
        [10030602] = {
          ContentFR = "<I>Siffler pour attirer leur attention</>",
          DialogueId = 10030602,
          GUID = "191C4DA4",
          NextDialogue = 10030603,
          Subtitle = "Whistle to grab their attention."
        },
        [10030603] = {
          Camera = "78.226898,5.710938,147.152344,0.000109,-17.401026,138.984924,35.000011,249.345123,false,Manual,3.0",
          ContentFR = "Waaah ! {nickname} ! C’est vraiment toi, en chair et en os !",
          DialogueId = 10030603,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "191C4DCE",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "200021:n(100001)",
            [3] = "100001:n(200002)"
          },
          NextDialogue = 10030604,
          SpeakNpcId = 200002,
          Subtitle = "Waaaah! ! It really is you!!",
          TalkActionId = {
            [1] = "200002:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4DCE"
        },
        [10030604] = {
          Camera = "-205.596069,-83.395508,180.607422,0.000125,-12.400939,31.862011,35.282173,313.231873,false,Manual,6.0",
          ContentFR = "Oh ? Survivre à une <H>Traque aux Charons</> ? Hé, t’as la peau plus dure qu’une Noix à coque de fer. Franchement, je croyais que les Vagabonds de la Nuit allait couler avant même de lever l’ancre.",
          DialogueId = 10030604,
          GUID = "191C4DF8",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10030605,
          SpeakNpcId = 200021,
          Subtitle = "Huh, surviving the Charon Hunt? I've got to say, you're tougher than an Ironshell Nut. Honestly, I thought the ship of our Noctoyagers would sink before it even left the dock.",
          TalkActionId = {
            [1] = "200021:Think_Start",
            [2] = "200002:Explain02_End"
          },
          TurnTo = {
            [1] = "100304:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4DF8"
        },
        [10030605] = {
          Camera = "0.396332,244.167969,21.378906,0.000094,25.396158,-121.224731,35.000011,411.428223,false,Manual,22.0",
          ContentFR = "Pff ! Tu parles ! Celui qui a couru partout en ville pour trouver des médecins, et qui a supplié Camilla de prendre soin {性别:de lui|d’elle} ces derniers jours... c’est bien toi ! Maintenant {性别:qu’il|qu’elle} est {性别:réveillé|réveillée}, tu fais le malin ?",
          DialogueId = 10030605,
          GUID = "191C4E22",
          LookAt = {
            [1] = "200002:n(200021)",
            [2] = "100001:n(200021)",
            [3] = "200021:n(200002)"
          },
          NextDialogue = 10030606,
          SpeakNpcId = 200002,
          Subtitle = "Pfft! Says the guy who's been running all over town looking for doctors and grovelling to Camilla to take care of {性别:him|her} these past few days! Now that {性别:he|she} is all better, you're talking hot air again.",
          TalkActionId = {
            [1] = "200002:Angry01_Start",
            [2] = "200021:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4E22"
        },
        [10030606] = {
          Camera = "23.498505,-207.322266,260.337891,0.00005,-27.40271,113.967453,35.000011,411.428162,false,Manual,3.0",
          ContentFR = "J’ai pas— ! Hé, Petit Champi, je t’avertis, arrête d’en rajouter ou je— !",
          DialogueId = 10030606,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "191C4E4C",
          NextDialogue = 10030607,
          SpeakNpcId = 200021,
          Subtitle = "I did not—! I'm warning you, Button Mushroom, quit twisting my words, or else—",
          TalkActionId = {
            [1] = "200021:Confident_Start",
            [2] = "200002:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4E4C"
        },
        [10030607] = {
          Camera = "-405.321106,133.943359,83.382812,0.000094,-6.002507,-9.651911,35.0,681.079041,false,Manual,3.0",
          ContentFR = "<I>Hmm... à les voir, ils ont l’air en pleine forme, ces deux-là.</>",
          DialogueId = 10030607,
          DisableMouth = 1,
          FacialId = {
            [1] = "200002:None"
          },
          FinalCamera = "-405.321106,133.943359,83.382812,0.000094,-1.002378,-9.652462,35.000008,520.892517,false,Manual,6.0",
          GUID = "191C4E76",
          NextDialogue = 10030608,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Hmm... Looks like these two are doing just fine.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100306/191C4E76"
        },
        [10030608] = {
          Camera = "135.663208,-35.232422,147.521484,0.000062,-15.799928,131.261826,35.000023,295.694153,false,Manual,6.0",
          ContentFR = "Petit larbin, comment tu te sens ? Voyons voir... les bras et les jambes sont là, la couleur de ta corne est parfaite... Bon, ton teint laisse à désirer, mais ça, on arrangera.",
          DialogueId = 10030608,
          GUID = "191C4EA0",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "200021:n(100001)",
            [3] = "100001:n(200002)"
          },
          NextDialogue = 10030609,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, how are you feeling? Hmm... Arms and legs are all in place, and the colour of your horn looks great, though your face is a bit pale.",
          TalkActionId = {
            [1] = "200002:Bai_Think2Confident"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4EA0"
        },
        [10030609] = {
          ContentFR = "Parfait ! Je savais bien que \"{性别:le Chevalier Blanc immortel, l’Étoile renaissante des Vagabonds de la Nuit, le Comte Démon béni|la Chevalière Blanche immortelle, l’Étoile renaissante des Vagabonds de la Nuit, la Comtesse Démon bénie}\" n’abandonnerait jamais son Roi Démon !",
          DialogueId = 10030609,
          FacialId = {
            [1] = "200002:Happy02"
          },
          GUID = "191C4ECA",
          NextDialogue = 10030610,
          SpeakNpcId = 200002,
          Subtitle = "Good! I knew the \"Immortal White Knight, the Reborn Star of the Noctoyagers, the Blessed Demon Earl\" wouldn't leave their Demon King behind!",
          VoiceName = "voice/$Locale$/story/1003/100306/191C4ECA"
        },
        [10030610] = {
          ContentFR = "Ne bouge pas d’ici, j’vais te chercher des fruits bien frais pour reprendre des forces !",
          DialogueId = 10030610,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "191C4EF4",
          NextDialogue = 10030631,
          SpeakNpcId = 200002,
          Subtitle = "Stay right here — I'll go grab some nutritious fruit for you!",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4EF4"
        },
        [10030611] = {
          Camera = "-205.596069,-83.395508,180.607422,0.000125,-12.400939,31.862019,35.282173,323.045349,false,Manual,6.0",
          ContentFR = "<I>Comment ça, plus le titre est long, plus le rang baisse ?! ... Non, je dois pas me laisser distraire par ses bêtises.</>",
          DialogueId = 10030611,
          DisableMouth = 1,
          GUID = "191C4F1E",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10030612,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Why is my title getting longer, but the rank keeps dropping? Wait... I can't let Snow's silly titles distract me.)",
          VoiceName = "voice/$Locale$/story/1003/100306/191C4F1E"
        },
        [10030612] = {
          Camera = "-205.596069,-83.395508,180.607422,0.000125,-12.400939,31.862019,35.282173,323.045349,false,Manual,6.0",
          ContentFR = "Tout à l’heure, vous parliez d’une... <H>Traque aux Charons</> ? C’est quoi exactement ?",
          DialogueId = 10030612,
          GUID = "191C4F48",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10030613,
          SpeakNpcId = 100001,
          Subtitle = "What were you talking about earlier? Charon Hunt? What's that?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4F48"
        },
        [10030613] = {
          Camera = "190.638672,10.195312,120.152344,0.000129,5.198969,171.649796,35.282173,291.788361,false,Manual,6.0",
          ContentFR = "Un sacré pétrin, dont tu pourras pas t’échapper.",
          DialogueId = 10030613,
          FacialId = {
            [1] = "200021:Angry01"
          },
          GUID = "191C4F72",
          LookAt = {
            [1] = "200002:n(100304)"
          },
          NextDialogue = 10030614,
          Scripts = "SetLocation{ActorId{200002},TargetPoint{\"bai_02_walkin\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200021,
          Subtitle = "It's a trouble you can't run away from.",
          TalkActionId = {
            [1] = "200021:Explain01_Start",
            [2] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4F72"
        },
        [10030614] = {
          Camera = "1141.481445,-277.025391,7.660156,0.000071,7.39676,-70.647835,35.000023,392.616089,false,Manual,6.0",
          ContentFR = "Excusez-moi... {nickname} est {性别:réveillé|réveillée} ?",
          DialogueId = 10030614,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "191C4F9C",
