CameraMoveTo{_delay{1.5},TargetPosition{"1180.628296,-769.296875,95.171875,0.000036,-15.803131,78.751717,35.000023,411.821381,false,Manual,6.0"},duration{0}}
}]],
          SpeakNpcId = 100304,
          Subtitle = "Excuse me, is  awake?",
