        },
        [10030615] = {
          ContentFR = "Hiiih !",
          DialogueId = 10030615,
          FacialId = {
            [1] = "200002:Shock02"
          },
          GUID = "191C4FC6",
          LookAt = {
            [1] = "200002:n(100304)"
          },
          NextDialogue = 10030616,
          SpeakNpcId = 200002,
          Subtitle = "Eek!",
          TalkActionId = {
            [1] = "200002:Shock_Start",
            [2] = "200021:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4FC6"
        },
        [10030616] = {
          Camera = "1297.798462,-671.682617,65.072266,0.000065,-0.601719,155.368057,35.000008,116.489357,false,Manual,3.0",
          ContentFR = "Tiens, la voilà... Le pétrin en personne. Et elle est pas du genre à lâcher l’affaire.",
          DialogueId = 10030616,
          FacialId = {
            [1] = "200002:None"
          },
          FinalCamera = "1297.798462,-671.682617,65.072266,0.000066,-0.601685,155.368103,35.000008,2653.720459,false,Manual,3.0",
          GUID = "191C4FF0",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100001:n(100304)"
          },
          NextDialogue = 10030617,
          SpeakNpcId = 200021,
          Subtitle = "Speak of the devil. Here comes your trouble — a big one, with a name.",
          TalkActionId = {
            [1] = "200021:Confident_Start"
          },
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "100001:n(100304)"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C4FF0"
        },
        [10030617] = {
          Camera = "230.647583,-1.03125,119.628906,0.000082,4.597776,170.360352,35.0,130.051529,false,DoNotOverride,3.0",
          ContentFR = "... Rhythm Fischer ?",
          DialogueId = 10030617,
          GUID = "191C501A",
          NextDialogue = 10030618,
          SpeakNpcId = 100001,
          Subtitle = "...Rhythm Fischer?",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "200002:Shock_End",
            [3] = "200021:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C501A"
        },
        [10030618] = {
          ContentFR = "Ouais. Elle débarque presque tous les jours, à la même heure, pour prendre des nouvelles.",
          DialogueId = 10030618,
          GUID = "191C5044",
          NextDialogue = 10030619,
          SpeakNpcId = 200021,
          Subtitle = "Yup. She's been stopping by every day around this time to ask about your situation.",
          TalkActionId = {
            [1] = "200021:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C5044"
        },
        [10030619] = {
          ContentFR = "... Vu que tu dis « tous les jours », ça veut dire que tu t’en es déjà occupé plusieurs fois. Je te la laisse. Allez, courage, tu gères.",
          DialogueId = 10030619,
          GUID = "191C506E",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "100001:n(200021)"
          },
          NextDialogue = 10030620,
          SpeakNpcId = 100001,
          Subtitle = "...Since you say \"every day,\" that means you've already dealt with her a bunch of times. She's all yours, Outsider. You've got this.",
          TurnTo = {
            [1] = "100001:n(200021)"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C506E"
        },
        [10030620] = {
          ContentFR = "Minute, pas si vite. Je te l’ai dit, ce genre de pétrin, tu pourras pas l’esquiver.",
          DialogueId = 10030620,
          GUID = "191C5098",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 10030621,
          SpeakNpcId = 200021,
          Subtitle = "Not so fast. I told you, this trouble is something you can't run away from.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C5098"
        },
        [10030621] = {
          ContentFR = "La <W>Traque aux Charons</>... ce sont des <W>meurtres en série</> qui secouent la cité extérieure. Comme tu es l’unique {性别:survivant|survivante}, la Légion ne peut pas faire autrement que de t’interroger. La question, c’était juste quand.",
          DialogueId = 10030621,
          GUID = "191C50C2",
          NextDialogue = 10030622,
          SpeakNpcId = 200021,
          Subtitle = "Charon Hunt is a string of serial murders in the outer city. As the sole survivor, there's no way the Legion won't want some information from you. It's only a matter of time.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100306/191C50C2"
        },
        [10030622] = {
          ContentFR = "Et franchement, tomber sur elle, c’est pas le pire. Dans la Légion, t’en as des bien plus brutaux. Crois-moi, tu préféreras encore avoir affaire à cette Fischer plutôt qu’à d’autres.",
          DialogueId = 10030622,
          GUID = "191C50EC",
          NextOptions = {
            [1] = 10030623,
            [2] = 10030624
          },
          SpeakNpcId = 200021,
          Subtitle = "Honestly, she seems pretty reasonable for a legion officer. If it were someone more heavy-handed, you'd be wishing it was her instead.",
          VoiceName = "voice/$Locale$/story/1003/100306/191C50EC"
        },
        [10030623] = {
          ContentFR = "<I>...</>",
          DialogueId = 10030623,
          GUID = "191C5116",
