        },
        [10030722] = {
          Camera = "36.484009,179.044922,176.644531,0.000295,-14.206376,-130.375656,35.000023,223.128433,false,Manual,6.0",
          ContentFR = "Bon, je vois... Tu dois encore en vouloir à Rhythm Fischer pour ce qui s’est passé cette nuit-là.",
          DialogueId = 10030722,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "191C5F5C",
          NextDialogue = 10030723,
          SpeakNpcId = 200021,
          Subtitle = "Alright, I know. You're probably still bitter about Rhythm Fischer for what happened that night.",
          TalkActionId = {
            [1] = "200021:Explain01_Start",
            [2] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5F5C"
        },
        [10030723] = {
          Camera = "36.484009,179.044922,176.644531,0.000295,-14.206376,-130.375656,35.000023,223.128433,false,Manual,6.0",
          ContentFR = "Mais ce serait pas mal de se mettre en bons termes avec elle. Le réseau d’infos de la Légion est partout, ça pourrait t’aider pour ta <H>recherche d’une certaine personne</>.",
          DialogueId = 10030723,
          GUID = "191C5FB0",
          NextDialogue = 10030724,
          Scripts = "CameraMoveTo{_delay{3},TargetPosition{\"-22.493896,92.760742,157.833984,0.000282,-9.206241,-123.576553,35.000019,109.330856,false,Manual,3.0\"},duration{0}}",
          SpeakNpcId = 200021,
          Subtitle = "But, it wouldn't be a bad thing to get on good terms with Fischer. I mean, the Legion's got connections everywhere. Your search for somebody might get somewhere.",
          VoiceName = "voice/$Locale$/story/1003/100307/191C5FB0"
        },
        [10030724] = {
          Camera = "7.651123,-118.004883,114.373047,0.000265,8.99109,120.035538,35.000019,156.230972,false,Manual,6.0",
          ContentFR = "Et puis, tu ne veux pas mettre la main sur ce lâche qui t’a attaqué dans le dos ?",
          DialogueId = 10030724,
          GUID = "191C5FB1",
          NextDialogue = 10030725,
          SpeakNpcId = 200021,
          Subtitle = "Besides, don't you want to take down that dishonorable coward with your own hands?",
          VoiceName = "voice/$Locale$/story/1003/100307/191C5FB1"
        },
        [10030725] = {
          ContentFR = "Quant à moi, j’ai aussi envie de régler cette histoire de \"Traque aux Charons\" rapidement. Toute la cité extérieure est en état de panique, et ma vieille porte ne supportera pas un verrou de plus.",
          DialogueId = 10030725,
          GUID = "191C5F86",
          NextDialogue = 10030726,
          SpeakNpcId = 200021,
          Subtitle = "As for me, I want this whole \"Charon Hunt\" mess resolved as soon as possible, too. The whole outer city's been on edge, and that rickety old door on my house can't take another lock.",
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C5F86"
        },
        [10030726] = {
          Camera = "13.800354,86.224609,170.464844,0.000277,-12.408418,-140.354614,35.000015,93.577675,false,Manual,3.0",
          ContentFR = "La Légion... Là ou se trouve Berry...",
          DialogueId = 10030726,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "13.800354,86.224609,170.464844,0.000278,-16.20825,-139.955261,35.000019,129.836029,false,Manual,6.0",
          GUID = "191C5FDA",
          NextDialogue = 10030727,
          SpeakNpcId = 100001,
          Subtitle = "The Legion... Berry's whereabout...",
          TalkActionId = {
            [1] = "100001:Sigh_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100307/191C5FDA"
        },
        [10030727] = {
          ContentFR = "... Les meurtres... la personne qui m’a attaqué cette nuit...",
          DialogueId = 10030727,
          GUID = "191C6004",
          NextDialogue = 10030728,
          SpeakNpcId = 100001,
          Subtitle = "The murders... And the one who attacked me...",
          VoiceName = "voice/$Locale$/story/1003/100307/191C6004"
        },
        [10030728] = {
          Camera = "-405.713257,243.483398,93.306641,0.000202,3.588124,-31.563541,35.000015,535.205933,false,Manual,3.0",
          ContentFR = "<I>Soupir,</> d’accord. Allons-y.",
          DialogueId = 10030728,
          FinalCamera = "13.302612,85.791016,170.464844,0.000279,-16.20825,-139.555191,35.000019,129.836029,false,Manual,6.0",
          GUID = "191C602E",
          SpeakNpcId = 100001,
          Subtitle = "*sighs* Fine. Let's do this.",
          TalkActionId = {
            [1] = "100001:Sigh_End"
          },
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "100001:n(200021)"
          },
          VoiceName = "voice/$Locale$/story/1003/100307/191C602E"
        },
        [10030801] = {
          Camera = "61.057617,108.540283,127.39502,-0.000122,5.801385,-131.604752,40.000011,1.5,false,DoNotOverride,1.2",
          ContentFR = "Je pensais qu’on irait dans un bureau.",
          DialogueId = 10030801,
          FacialId = {
            [1] = "200021:Doubt01",
            [2] = "100001:Confident01"
          },
          FinalCamera = "73.068359,122.071289,125.557617,-0.000122,5.801385,-131.604752,40.000011,1.5,false,DoNotOverride,1.2",
          GUID = "191C6E4A",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100304:n(100001)"
          },
          NextDialogue = 10030802,
          RelatedWikiId = {
            [1] = 201011
          },
          Scripts = "CameraMoveTo{_delay{2},TargetPosition{\"68.806641,188.34668,131.112061,-0.000122,2.60125,-129.004272,35.0,299.586945,false,Manual,3.390601\"},duration{0}}",
          SpeakNpcId = 200021,
          Subtitle = "I thought it would be somewhere like an office.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6E4A"
        },
        [10030802] = {
          Camera = "40.330078,-14.789795,129.912109,-0.000122,3.401612,100.797935,35.000019,1.5,false,DoNotOverride,1.2",
          ContentFR = "Hmm. Quand je suis fatiguée, je viens ici prendre l’air. Il n’y a presque jamais personne, c’est un endroit idéal pour parler sérieusement.",
          DialogueId = 10030802,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "42.864258,-28.097412,129.106689,-0.000122,3.401612,100.798004,35.000019,1.5,false,DoNotOverride,1.2",
          GUID = "191C6E74",
          NextDialogue = 10030803,
          Scripts = "PlayAnimation{_delay{2},ActorId{100304},AnimationId{\"Explain02_Start\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "I come here to clear my head when I'm feeling overwhelmed. It's quiet, and there's rarely anyone around — perfect for discussing serious matters.",
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6E74"
        },
        [10030803] = {
          Camera = "938.864258,-1600.42627,644.140015,0.000063,-15.356232,125.519363,35.000008,3496.211426,false,Manual,1.2",
          ContentFR = "Donc, la \"Traque aux Charons\" est une série de meurtres survenus à Givrelac. Vous en avez sans doute déjà entendu parler.",
          DialogueId = 10030803,
          FacialId = {
            [1] = "100304:Unhappy01"
          },
          FinalCamera = "921.212891,-1613.348145,644.140015,0.000062,-15.156223,125.719307,35.000008,3496.211426,false,Manual,1.2",
          GUID = "191C6E9E",
          NextDialogue = 10030804,
          SpeakNpcId = 100304,
          Subtitle = "So, the \"Charon Hunt\" is a series of murders that took place here in Icelake. I assume you've already heard about it.",
          TalkActionId = {
            [1] = "100304:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6E9E"
        },
        [10030804] = {
          Camera = "22.568359,-184.945801,150.498779,14.412785,-8.200291,103.409584,25.0,1.5,false,DoNotOverride,1.2",
          ContentFR = "Le 22 novembre, à l’aube : cinq morts, un blessé. Le 25 novembre, à l’aube également : treize morts.",
          DialogueId = 10030804,
          FacialId = {
            [1] = "100304:Sad02"
          },
          FinalCamera = "17.014648,-186.657471,149.025391,14.414536,-7.200214,102.210579,25.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C6EC8",
          NextDialogue = 10030805,
          Scripts = "PlayAnimation{_delay{5},ActorId{100304},AnimationId{\"Explain01_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "November 22, early morning: 5 dead, 1 injured. November 25, early morning: 13 dead.",
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6EC8"
        },
        [10030805] = {
          Camera = "23.945312,90.854004,160.98999,10.805622,-22.999117,107.011467,25.0,1.5,false,DoNotOverride,1.2",
          ContentFR = "Les crimes ont eu lieu dans le quartier est, là où vivent surtout des Charons. C’est de là que vient le nom de \"Traque aux Charons\".",
          DialogueId = 10030805,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "18.341797,89.56958,158.005859,10.810204,-18.79888,98.613777,25.000002,1.5,false,DoNotOverride,1.2",
          GUID = "191C6EF2",
          NextDialogue = 10030806,
          RelatedWikiId = {
            [1] = 405005
          },
          SpeakNpcId = 100304,
          Subtitle = "The attacks primarily occurred in the eastern district, home to many Charon residents, which is why the case has been dubbed the \"Charon Hunt.\"",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6EF2"
        },
        [10030806] = {
          Camera = "154.362305,294.067871,116.455078,-0.000122,2.199355,-123.791985,40.000027,420.30722,false,Manual,1.2",
          ContentFR = "Ça, on le sait déjà. Mais vous attendez quoi exactement de {nickname} ?",
          DialogueId = 10030806,
          FinalCamera = "152.069336,295.810059,116.455078,-0.000122,2.199355,-122.592339,40.000027,420.30722,false,Manual,1.2",
          GUID = "191C6F1C",
          NextDialogue = 10030807,
          Scripts = "PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Talk02_Start\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Yeah, we've heard about that. What do you need from ?",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6F1C"
        },
        [10030807] = {
          Camera = "35.023438,-85.893799,135.901367,-0.000122,-1.000022,97.196419,40.0,1.5,false,DoNotOverride,1.2",
          ContentFR = "J’ai besoin que {nickname} me livre le plus de détails possible. Dans un instant, je vous conduirai sur les lieux de l’attaque {性别:qu’il|qu’elle} a subie il y a cinq jours. La rue est actuellement placée sous scellés par la Légion.",
          DialogueId = 10030807,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "39.05957,-117.875977,136.462891,-0.000122,-1.000022,97.196419,40.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C6F46",
          NextDialogue = 10030808,
          Scripts = "PlayAnimation{_delay{5},ActorId{100304},AnimationId{\"Talk01_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "I need  to provide as many details about the case as possible. In a while, I'll take you all to the scene where {性别:he|she} was attacked five days ago. That street is currently sealed off by the Legion.",
          TalkActionId = {
            [1] = "100304:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6F46"
        },
        [10030808] = {
          Camera = "37.841797,-240.143555,136.698242,-0.000122,-0.799986,100.997322,40.0,1.5,false,DoNotOverride,1.2",
          ContentFR = "Mais vous êtes avant tout une victime. Revenir sur les lieux pourrait raviver de douloureux souvenirs. Cela risquerait de ralentir l’enquête, mais si vous préférez, nous pouvons aussi faire l’interrogatoire au Bureau de la Sécurité.",
          DialogueId = 10030808,
          FinalCamera = "27.549805,-242.12207,136.698242,-0.000122,-0.799959,99.197517,40.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C6F70",
          NextOptions = {
            [1] = 10030809,
            [2] = 10030811
          },
          Scripts = [[
PARA{
PlayAnimation{_delay{2},ActorId{200021},AnimationId{"Talk02_End"},Duration{2}},
SEQ{CameraMoveTo{_delay{5},TargetPosition{"24.785156,58.79248,123.002441,-0.000123,3.599427,-100.993622,40.000011,1.5,false,DoNotOverride,1.2"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{"32.329102,57.327148,123.002441,-0.000122,3.999438,-104.194237,40.000011,1.5,false,DoNotOverride,1.2"},duration{10}}}
}]],
          SpeakNpcId = 100304,
          Subtitle = "But I understand revisiting the scene might bring up unpleasant memories. If it's too much for you, we can conduct the enquiry at the Security Bureau instead — it might not be as efficient, but it's an option.",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6F70"
        },
        [10030809] = {
          ContentFR = "<I>Ce n’est pas nécessaire. Finissons-en.</>",
          DialogueId = 10030809,
          GUID = "191C6F9A",
          ImprPlusId = 1006,
          NextDialogue = 10030810,
          Subtitle = "No need. Let's just get it over with."
        },
        [10030810] = {
          Camera = "202.821289,-682.109375,384.926758,-0.000121,-20.999859,108.990448,35.0,1.5,false,DoNotOverride,1.2",
          ContentFR = "Merci pour votre coopération, Vagabonds de la Nuit. Vous êtes aussi solides et courageux que le dit la rumeur.",
          DialogueId = 10030810,
          FinalCamera = "177.298828,-690.292236,384.926758,-0.00012,-21.199854,106.390915,35.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C6FC4",
          NextDialogue = 10030813,
          Scripts = "PlayAnimation{_delay{2},ActorId{100304},AnimationId{\"Explain02_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "Thank you for your cooperation, Noctoyagers. You're as tough and reliable as they say.",
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C6FC4"
        },
        [10030811] = {
          ContentFR = "<I>Je ne suis pas si fragile que ça.</>",
          DialogueId = 10030811,
          GUID = "191C6FEE",
          ImprPlusId = 1009,
          NextDialogue = 10030812,
          Subtitle = "I'm not that fragile."
        },
        [10030812] = {
          Camera = "202.821289,-682.109375,384.926758,-0.000121,-20.999859,108.990448,35.0,1.5,false,DoNotOverride,1.2",
          ContentFR = "Pardon. J’ai eu tort de présumer.",
          DialogueId = 10030812,
          FinalCamera = "177.298828,-690.292236,384.926758,-0.00012,-21.199854,106.390915,35.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C7018",
          NextDialogue = 10030813,
          Scripts = "PlayAnimation{_delay{2},ActorId{100304},AnimationId{\"Explain02_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "Apologies, I shouldn't have just assumed.",
          TalkActionId = {
            [1] = "100304:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C7018"
        },
        [10030813] = {
          Camera = "32.081055,-28.242676,78.543457,-0.000123,11.19845,-70.9897,40.000027,1.5,false,DoNotOverride,1.2",
          ContentFR = "Hé hé ! Ne vous fiez pas à l’allure délicate de mon petit larbin : {性别:il|elle} est bien plus solide qu’on ne le croit !",
          DialogueId = 10030813,
          FacialId = {
            [1] = "200002:Happy01"
          },
          FinalCamera = "12.866211,27.515869,68.764893,-0.000122,8.398448,-71.189598,40.000027,1.5,false,DoNotOverride,1.2",
          GUID = "191C7042",
          NextDialogue = 10030814,
          Scripts = "PlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Explain01_End\"},Duration{2}}",
          SpeakNpcId = 200002,
          Subtitle = "Hehe, don't be fooled by how gentle my Little Minion looks — {性别:he|she}'s very tough on the inside!",
          TalkActionId = {
            [1] = "200002:Explain02_Start"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1003/100308/191C7042"
        },
        [10030814] = {
          Camera = "27.410156,-34.083984,136.467285,-0.000122,3.230529,-113.933205,30.0,1.5,false,DoNotOverride,1.2",
          ContentFR = "Je peux vous aider dans votre enquête. Mais... les Chasseurs de Phoxène n’acceptent jamais une mission sans récompense.",
          DialogueId = 10030814,
          FinalCamera = "39.094727,-7.752686,134.841309,-0.000122,2.430516,-113.932823,30.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C706C",
          NextDialogue = 10030815,
          SpeakNpcId = 100001,
          Subtitle = "I can assist with your investigation. But we Phoxhunters don't take on jobs for free.",
          TalkActionId = {
            [1] = "200002:Agree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C706C"
        },
        [10030815] = {
          Camera = "25.53418,-187.426025,140.700439,-0.000122,-2.369632,101.068672,30.0,1.5,false,DoNotOverride,1.2",
          ContentFR = "Combien demandez-vous ?",
          DialogueId = 10030815,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          GUID = "191C7096",
          NextDialogue = 10030816,
          SpeakNpcId = 100304,
          Subtitle = "What's your price?",
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100308/191C7096"
        },
        [10030816] = {
          Camera = "237.609375,311.72168,37.491455,-0.000121,10.798064,-126.589691,30.0,1.5,false,DoNotOverride,1.2",
          ContentFR = "Je veux que vous me fassiez une promesse. Aidez-moi le jour où j’aurai besoin de vous.",
          DialogueId = 10030816,
          FinalCamera = "258.552734,295.424072,37.491455,-0.000122,10.998025,-130.988983,30.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C70C0",
          NextDialogue = 10030817,
          Scripts = "PlayAnimation{_delay{1},ActorId{100001},AnimationId{\"Confident_End\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "On top of the payment, I need you to promise me one thing — help me when I need it in the future.",
          TalkActionId = {
            [1] = "100001:Confident_Start",
            [2] = "100304:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C70C0"
        },
        [10030817] = {
          Camera = "8.558594,-5.310303,122.864258,-0.000121,5.400015,89.397499,35.0,1.5,false,DoNotOverride,1.2",
          ContentFR = "...",
          DialogueId = 10030817,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "8.689453,7.668945,124.09082,-0.000121,5.400015,89.397499,35.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C70EA",
          NextDialogue = 10030818,
          SpeakNpcId = 100304,
          Subtitle = "...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C70EA"
        },
        [10030818] = {
          Camera = "-120.288086,-367.168945,91.211426,-0.000122,4.400308,70.991791,35.000023,1.5,false,DoNotOverride,1.2",
          ContentFR = "Très bien. Je vous le promets. J’apporterai mon aide autant que possible.",
          DialogueId = 10030818,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "-120.288086,-367.168945,91.211426,-0.000122,2.800302,70.991676,35.000023,1.5,false,DoNotOverride,1.2",
          GUID = "191C7114",
          NextDialogue = 10030819,
          SpeakNpcId = 100304,
          Subtitle = "Alright, I promise you. I'll help however I can.",
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C7114"
        },
        [10030819] = {
          Camera = "-36.814453,-5.089111,124.812256,-AA1160.000122,5.000607,71.789139,35.000023,1.5,false,DoNotOverride,1.2",
          ContentFR = "... Minute ! Hors de question d’enfreindre le règlement militaire : pas de meurtre, pas de vol... ah, et surtout, aucune aide aux Déchus !",
          DialogueId = 10030819,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "-29.711914,16.467773,126.797119,-0.000122,5.000607,71.588997,35.000023,1.5,false,DoNotOverride,1.2",
          GUID = "191C713E",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10030820,
          Scripts = "PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Explain02_Start\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "...Wait! Breaking military regulations is off the table — no murder, no theft... Oh, and absolutely no aiding the Forsakens...!",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100308/191C713E"
        },
        [10030820] = {
          Camera = "134.194336,248.073242,103.617432,-0.000122,4.396907,-126.986076,30.000002,1.5,false,DoNotOverride,1.2",
          ContentFR = "Non, non, rien de tout ça, je vous rassure ! Nous sommes des honnêtes citoyens. C’est juste que notre capitaine a été {性别:séparé|séparée} de sa famille, et qu’un jour nous aurons peut-être besoin de votre soutien pour les retrouver.",
          DialogueId = 10030820,
          FacialId = {
            [1] = "200021:Ahaha01"
          },
          FinalCamera = "129.308594,251.674316,103.617432,-0.000122,4.396907,-125.585915,30.000002,1.5,false,DoNotOverride,1.2",
          GUID = "191C7168",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10030821,
          Scripts = "PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Sigh_End\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Whoa, nothing like that! Don't worry, Officer, we're law-abiding folks. It's just that our captain got separated from {性别:his|her} family, and might need your help to look for them.",
          TalkActionId = {
            [1] = "200021:Sigh_Start",
            [2] = "100304:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100308/191C7168"
        },
        [10030821] = {
          Camera = "40.24707,133.596191,138.103271,-0.000122,2.000023,170.404037,35.0,1.5,false,DoNotOverride,1.2",
          ContentFR = "{性别:Séparé|Séparée} de sa famille ?",
          DialogueId = 10030821,
          FacialId = {
            [1] = "200021:Shock01"
          },
          FinalCamera = "39.746094,130.626221,138.103271,-0.000122,2.000023,170.404037,35.0,1.5,false,DoNotOverride,1.2",
          GUID = "191C7192",
          NextDialogue = 10030822,
          SpeakNpcId = 100304,
          Subtitle = "Got separated from your family?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100308/191C7192"
        },
        [10030822] = {
          Camera = "155.024414,-651.978271,105.728516,-0.000122,7.398713,107.904366,40.000023,1.5,false,DoNotOverride,1.2",
          ContentFR = "Je comprends parfaitement votre détresse ! Moi aussi, je ne vois presque jamais les miens... Quand la \"Traque aux Charons\" sera élucidée, je mettrai tout en œuvre pour vous aider à retrouver votre famille !",
          DialogueId = 10030822,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "155.024414,-651.978271,105.728516,-0.000122,2.598771,106.304527,40.000011,1.5,false,DoNotOverride,1.2",
          GUID = "191C71BC",
          NextDialogue = 10030823,
          Scripts = "PlayAnimation{_delay{6},ActorId{100304},AnimationId{\"Talk02_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "I completely understand how you feel. I barely get to see my family all year round... Once the \"Charon Hunt\" case is resolved, I promise I'll do everything in my power to help you find your family!",
          TalkActionId = {
            [1] = "100304:Talk02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1003/100308/191C71BC"
        },
        [10030823] = {
          Camera = "6.436523,-56.493652,135.884766,-0.000122,7.398474,-105.213242,35.000019,1.5,false,DoNotOverride,1.2",
          ContentFR = "<I>Qu’est-ce qui lui prend, tout à coup ? Je... j’étouffe...</>",
          DialogueId = 10030823,
          DisableMouth = 1,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "13.727539,-29.676025,130.914795,-0.000122,6.607538,-104.814003,35.000023,1.5,false,DoNotOverride,1.2",
          GUID = "191C71E6",
          NextDialogue = 10030824,
          SpeakNpcId = 100001,
          Subtitle = "(Uh... Why is she so fired up all of a sudden? I... I can't breathe...)",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1003/100308/191C71E6"
        },
        [10030824] = {
          Camera = "61.378906,214.812744,138.863037,-0.000122,-3.16205,-110.605522,35.000023,1.5,false,DoNotOverride,1.2",
          ContentFR = "A-Allons voir les lieux du crime d’abord, officier.",
          DialogueId = 10030824,
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "54.251953,217.491455,138.863037,-0.000122,-2.962021,-109.205406,35.000023,1.5,false,DoNotOverride,1.2",
          GUID = "191C7210",
          Scripts = "PARA{PlayAnimation{_delay{0},ActorId{100001},AnimationId{\"Shock_End\"},Duration{2}}},SEQ{CameraMoveTo{_delay{2},TargetPosition{\"317.952148,296.217041,241.933594,0.00006,-17.356466,-140.280762,25.000006,1.5,false,DoNotOverride,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"392.445312,358.106934,272.203857,0.00006,-17.356466,-140.280762,25.000006,1.5,false,DoNotOverride,1.2\"},duration{10}}}",
          SpeakNpcId = 100001,
          Subtitle = "L—Let's just head to the crime scene first, Officer.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100308/191C7210"
        },
        [10030901] = {
          ContentFR = "Sacré capitaine, tu es vraiment incroyable, oser négocier avec un officier de la Légion.",
          DialogueId = 10030901,
          GUID = "191C7EB2",
          NextDialogue = 10030902,
          SpeakNpcId = 200021,
          Subtitle = "Captain, you're really something, daring to bargain with a legion officer.",
          VoiceName = "voice/$Locale$/story/1003/100309/191C7EB2"
        },
        [10030902] = {
          ContentFR = "C’est pas toi qui disais qu’elle serait facile à gérer ?",
          DialogueId = 10030902,
          GUID = "191C7EDC",
          NextDialogue = 10030903,
          SpeakNpcId = 100001,
          Subtitle = "Didn't you say she was easy to deal with?",
          VoiceName = "voice/$Locale$/story/1003/100309/191C7EDC"
        },
        [10030903] = {
          ContentFR = "Oui, mais je ne pensais pas que tu poserais tes conditions comme ça. Tu ignores ce qui lui passe par la tête... et si jamais...",
          DialogueId = 10030903,
          GUID = "191C7F06",
          NextDialogue = 10030904,
          SpeakNpcId = 200021,
          Subtitle = "Yeah, but we didn't expect you to go full-on negotiating. It's not like you know what she is thinking. What if she—",
          VoiceName = "voice/$Locale$/story/1003/100309/191C7F06"
        },
        [10030904] = {
          ContentFR = "Je réfléchis à la meilleure façon de reconstituer le profil du meurtrier.",
          DialogueId = 10030904,
          GUID = "191C7F30",
          NextDialogue = 10030905,
          SpeakNpcId = 100304,
          Subtitle = "I'm thinking about how to quickly reconstruct the perpetrator's profile.",
          VoiceName = "voice/$Locale$/story/1003/100309/191C7F30"
        },
        [10030905] = {
          ContentFR = "Chut... Elle a entendu. Elle a l’ouïe beaucoup trop fine.",
          DialogueId = 10030905,
          GUID = "191C7F5A",
          NextDialogue = 10030906,
          SpeakNpcId = 100001,
          Subtitle = "Shh... she heard us. Her hearing is way too sharp.",
          VoiceName = "voice/$Locale$/story/1003/100309/191C7F5A"
        },
        [10030906] = {
          ContentFR = "Vous me flattez. Mais rester alerte en toute circonstance est essentiel pour bien accomplir sa mission.",
          DialogueId = 10030906,
          GUID = "191C7F84",
          NextDialogue = 10030907,
          SpeakNpcId = 100304,
          Subtitle = "You flatter me. Staying sharp at all times is essential for carrying out duties more effectively.",
          VoiceName = "voice/$Locale$/story/1003/100309/191C7F84"
        },
        [10030907] = {
          ContentFR = "<I>Ce n’était pas un compliment !</>",
          DialogueId = 10030907,
          DisableMouth = 1,
          GUID = "191C7FAE",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(I was not flattering!)",
          VoiceName = "voice/$Locale$/story/1003/100309/191C7FAE"
        },
        [10031001] = {
          Camera = "-478.665039,-1042.830078,66.149902,0.000152,1.999353,62.608269,35.000008,941.904541,false,Manual,1.2",
          ContentFR = "Nous y sommes. {nickname}, cette rue... vous vous en souvenez ?",
          DetectiveQuestionId = 1001,
          DialogueId = 10031001,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "-471.366211,-1046.613281,66.149902,0.000152,1.999353,62.608269,35.000008,941.904541,false,Manual,1.2",
          GUID = "191C8F1A",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextOptions = {
            [1] = 10031002,
            [2] = 10031003
          },
          RelatedWikiId = {
            [1] = 201011,
            [2] = 405005
          },
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-28.166992,-140.116943,104.505859,0.000152,11.999488,-42.391018,35.000011,941.904541,false,DoNotOverride,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-25.53418,-137.13916,104.505859,0.000151,11.999488,-43.791016,35.000011,941.904541,false,DoNotOverride,1.2\"},duration{5}}}",
          SpeakNpcId = 100304,
          Subtitle = "This is it. , does this street look familiar?",
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100310/191C8F1A"
        },
        [10031002] = {
          ContentFR = "<I>Oui, je m’en souviens.</>",
          DetectiveQuestionId = 1001,
          DialogueId = 10031002,
          GUID = "191C8F44",
          ImprPlusId = 1007,
          NextDialogue = 10031004,
          Subtitle = "Yes, I remember it."
        },
        [10031003] = {
          ContentFR = "<I>Si on vous assomme en pleine rue, ça ne s’oublie pas.</>",
          DetectiveQuestionId = 1001,
          DialogueId = 10031003,
          GUID = "191C8F6E",
          ImprPlusId = 1010,
          NextDialogue = 10031004,
          Subtitle = "Well, if someone knocked you out cold on the street, you wouldn't forget either."
        },
        [10031004] = {
          Camera = "90.230469,-472.615723,119.978027,0.000191,-0.400393,102.218979,40.0,941.904541,false,DoNotOverride,1.2",
          ContentFR = "Alors, vous souvenez-vous de l’heure approximative de l’attaque ?",
          DetectiveQuestionId = 1001,
          DialogueId = 10031004,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "90.230469,-472.615723,130.0,0.000199,-0.400393,102.219009,40.0,941.904541,false,DoNotOverride,1.2",
          GUID = "191C8F98",
          NextDialogue = 10031005,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"100304:n(100001)\"}}",
          SpeakNpcId = 100304,
          Subtitle = "Do you recall the approximate time of the attack?",
          TalkActionId = {
            [1] = "100304:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100310/191C8F98"
        },
        [10031005] = {
          Camera = "-64.777344,-47.655518,128.217285,0.000165,-0.000854,-48.591522,40.0,941.904541,false,DoNotOverride,1.2",
          ContentFR = "Non... Pas vraiment. À ce moment-là, je ne me sentais pas très bien. Je savais que je ne trouverais pas le sommeil, alors j’ai {性别:préféré|préférée} marcher un peu en ville.",
          DetectiveQuestionId = 1001,
          DialogueId = 10031005,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "-66.598633,-49.306152,128.217285,0.000165,-0.000854,-46.391235,40.0,941.904541,false,DoNotOverride,1.2",
          GUID = "191C8FC2",
          NextDialogue = 10031006,
          Scripts = "PlayAnimation{_delay{3},ActorId{100001},AnimationId{\"ScratchHead_End\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "Not really. At the time, I was... not feeling great. I figured I wouldn't be able to sleep, so I decided to take a walk around the city.",
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100310/191C8FC2"
        },
        [10031006] = {
          Camera = "-401.587891,135.657227,245.506836,0.000158,-15.000843,-35.580502,35.0,941.904541,false,DoNotOverride,22",
          ContentFR = "Pour l’heure exacte... j’étais préoccupé, mes pensées étaient ailleurs. Je ne m’en rappelle pas.",
          DetectiveQuestionId = 1001,
          DialogueId = 10031006,
          FacialId = {
            [1] = "100001:Think01"
          },
          FinalCamera = "-408.319336,125.966064,245.506836,0.000153,-15.000843,-32.580688,35.0,941.904541,false,DoNotOverride,22",
          GUID = "191C8FEC",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 10031007,
          Scripts = "PlayAnimation{_delay{3},ActorId{200002},AnimationId{\"Think_Start\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "As for the exact time... I was preoccupied, so it's a bit of a blur.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100310/191C8FEC"
        },
        [10031007] = {
          Camera = "124.522461,-52.962646,126.131836,0.000177,4.398307,-110.971413,35.0,941.904541,false,DoNotOverride,1.903106",
          ContentFR = "Tss, on aurait dû rentrer ensemble, ce soir-là.",
          DetectiveQuestionId = 1001,
          DialogueId = 10031007,
          FacialId = {
            [1] = "200021:Sad01"
          },
          FinalCamera = "131.162109,-55.508545,126.131836,0.000174,4.398307,-112.770927,35.0,941.904541,false,DoNotOverride,1.903106",
          GUID = "191C9016",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10031008,
          Scripts = "PARA{LookAt{_delay{3},LookAtDescription{\"100001:n(200021)\"}},PlayAnimation{_delay{3.5},ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{2}}}",
          SpeakNpcId = 200021,
          Subtitle = "Ugh, we should've stuck together that night.",
          TalkActionId = {
            [1] = "200021:DisagreeHead",
            [2] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100310/191C9016"
        },
        [10031008] = {
          Camera = "114.541016,142.993408,51.0,0.000056,8.797734,-105.975533,35.0,941.904541,false,DoNotOverride,1.903106",
          ContentFR = "Ce n’est rien. C’est moi qui voulais marcher {性别:seul|seule}.",
          DetectiveQuestionId = 1001,
          DialogueId = 10031008,
          FinalCamera = "122.243164,140.819336,51.0,0.000055,8.797734,-107.575684,35.0,941.904541,false,DoNotOverride,1.903106",
          GUID = "191C9040",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10031009,
          Scripts = "PlayAnimation{_delay{2},ActorId{100001},AnimationId{\"Explain02_Start\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "It's fine. It was me who insisted on having some time alone.",
          TalkActionId = {
            [1] = "200002:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100310/191C9040"
        },
        [10031009] = {
          Camera = "16.606445,-174.10498,173.058594,10.800163,-21.601551,-45.770706,35.0,941.904541,false,DoNotOverride,1.903106",
          ContentFR = "<I>Attends... quand je suis arrivé dans cette rue, le vent venait de tomber et la lune apparaissait. D’après sa position, c’était... entre quatre et cinq heures du matin.</>",
          DetectiveQuestionId = 1001,
          DialogueId = 10031009,
          DisableMouth = 1,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "191C906A",
          LookAt = {
            [1] = "200021:n(100304)"
          },
          NextDialogue = 10031010,
          SpeakNpcId = 100001,
          Subtitle = "(Wait... I remember when I reached this street, the wind had just stopped, and the moon came out. Judging by the moon's position, it must've been... between 4 and 5 a.m.)",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100310/191C906A"
        },
        [10031010] = {
          Camera = "120.47168,-462.604004,186.308594,0.000047,-12.402864,110.025742,35.0,941.904541,false,DoNotOverride,1.903106",
          ContentFR = "<I>Je devrais en informer Rhythm.</>",
          DetectiveQuestionId = 1001,
          DialogueId = 10031010,
          DisableMouth = 1,
          FinalCamera = "120.47168,-462.604004,186.308594,0.000047,-10.402828,110.02562,35.0,941.904541,false,DoNotOverride,1.903106",
          GUID = "191C9094",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          SpeakNpcId = 100001,
          Subtitle = "(I should tell Rhythm about this.)",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100310/191C9094"
        },
        [10031101] = {
          Camera = "844.44043,-1090.708984,244.199707,0.000182,-7.000854,132.199615,50.000008,100000.0,false,Manual,22.0",
          ContentFR = "Entre quatre et cinq heures... Parfait, cela concorde avec le témoignage de Camilla Scarlet. Votre mémoire est précise, elle n’a pas été affectée par votre évanouissement.",
          DialogueId = 10031101,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "792.896484,-1033.864258,234.775391,0.000182,-7.000854,132.199615,50.000008,100000.0,false,Manual,22.0",
          GUID = "191C9F82",
          LookAt = {
            [1] = "100304:n(100001)",
            [2] = "200021:n(100304)",
            [3] = "200002:n(100304)",
            [4] = "100001:n(100304)"
          },
          NextDialogue = 10031102,
          RelatedWikiId = {
            [1] = 201011,
            [2] = 405005
          },
          Scripts = "PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Think_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "Between 4 and 5 a.m... Hmm, that matches perfectly with Camilla Scarlet's testimony. It seems your memory is sharp and hasn't been affected by your time spent unconscious.",
          TalkActionId = {
            [1] = "100304:Think_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100311/191C9F82"
        },
        [10031102] = {
          Camera = "164.110352,-295.21875,130.549805,0.000187,-2.201418,135.795242,35.0,324.824371,false,Manual,3.0",
          ContentFR = "Bien. Et concernant l’agresseur : que pouvez-vous me dire ? Le moindre détail compte.",
          DialogueId = 10031102,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191C9FAC",
          NextDialogue = 10031103,
          SpeakNpcId = 100304,
          Subtitle = "Now, about the perpetrator. What can you recall about their features? Even the smallest detail could be helpful.",
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191C9FAC"
        },
        [10031103] = {
          Camera = "1.719727,-99.894531,130.34082,0.000209,1.398256,-61.207794,35.000011,324.828125,false,Manual,22.0",
          ContentFR = "L’attaque a été trop soudaine, je n’ai pas eu le temps de voir son visage. Mais une chose est sûre : ce n’était pas humain.",
          DialogueId = 10031103,
          FacialId = {
            [1] = "200002:Shock01",
            [2] = "200021:Shock01"
          },
          GUID = "191C9FD6",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          NextDialogue = 10031104,
          Scripts = "CameraMoveTo{_delay{7},TargetPosition{\"56.811523,-148.78833,135.421875,0.000207,4.598254,-77.806282,35.000011,324.828125,false,Manual,22.0\"},duration{0}},",
          SpeakNpcId = 100001,
          Subtitle = "It all happened so fast... I didn't get a clear look at the perpetrator. But one thing I'm certain of — it... wasn't human.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191C9FD6"
        },
        [10031104] = {
          Camera = "56.811523,-148.78833,135.421875,0.000208,4.59824,-76.605972,35.000015,324.828125,false,Manual,22.0",
          ContentFR = "La dernière image avant de perdre connaissance, c’est... un visage monstrueux. Impossible de dire s’il s’agissait d’un Souillé ou d’autre chose.",
          DialogueId = 10031104,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "191CA000",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10031105,
          Scripts = "PlayAnimation{_delay{6},ActorId{100001},AnimationId{\"Think_End\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "The last thing I saw before passing out was a monstrous face. Though I'm not sure if it was a Filthoid or something else entirely.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA000"
        },
        [10031105] = {
          Camera = "149.513672,-169.366943,198.691895,0.000219,-21.601606,154.789032,35.0,324.824371,false,DoNotOverride,22",
          ContentFR = "Hmm... Un monstre, nous le savions déjà. Rien d’autre ?",
          DialogueId = 10031105,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "191CA02A",
          LookAt = {
            [1] = "200021:n(100304)"
          },
          NextDialogue = 10031106,
          Scripts = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Think_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "Hmm... A monster. That fits with what we know so far. Is there anything else you can remember?",
          TalkActionId = {
            [1] = "100304:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA02A"
        },
        [10031106] = {
          Camera = "5.640625,-44.589111,120.307129,0.000218,2.797017,-73.17907,35.000015,324.824371,false,DoNotOverride,22",
          ContentFR = "Attendez, si ! Il y a encore une chose !",
          DialogueId = 10031106,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "191CA054",
          NextDialogue = 10031107,
          SpeakNpcId = 100001,
          Subtitle = "Wait, there's one more thing!",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA054"
        },
        [10031107] = {
          ContentFR = "Je vous écoute !",
          DialogueId = 10031107,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "191CA07E",
          NextDialogue = 10031108,
          SpeakNpcId = 100304,
          Subtitle = "Please go ahead!",
          TalkActionId = {
            [1] = "100304:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA07E"
        },
        [10031108] = {
          ContentFR = "... Une voix.",
          DialogueId = 10031108,
          GUID = "191CA0A8",
          NextDialogue = 10031109,
          SpeakNpcId = 100001,
          Subtitle = "The singing voice...",
          TalkActionId = {
            [1] = "100304:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA0A8"
        },
        [10031109] = {
          Camera = "145.999023,-899.881348,124.759277,0.000267,33.387341,-12.212714,15.0,324.824371,false,Manual,3.0",
          ContentFR = "Ici, dans cette rue, j’avais l’impression d’être suivi... Et avec les pas, j’ai entendu... une voix qui chantait.",
          DialogueId = 10031109,
          FinalCamera = "116.962891,-893.183594,105.121094,0.000266,33.387348,-12.612405,15.0,324.824371,false,Manual,3.0",
          GUID = "191CA0D2",
          NextDialogue = 10031110,
          SpeakNpcId = 100001,
          Subtitle = "I remember something following me on this street. Along with its footsteps, I heard... its singing.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100311/191CA0D2"
        },
        [10031110] = {
          Camera = "5.640625,-44.589111,120.307129,0.000218,2.797017,-73.17907,35.000015,324.824371,false,DoNotOverride,22",
          ContentFR = "Oui. C’était rauque, comme un soufflet brisé, mais ça chantait. <H>Ce monstre chantait</>.",
          DialogueId = 10031110,
          GUID = "191CA0FC",
          NextDialogue = 10031111,
          SpeakNpcId = 100001,
          Subtitle = "Yes, that's it. Its voice was raspy, broken — almost like wind blowing through shattered pipes. But that monster was unmistakably singing.",
          VoiceName = "voice/$Locale$/story/1003/100311/191CA0FC"
        },
        [10031111] = {
          Camera = "105.765625,-455.361328,108.25,0.000137,4.600098,105.407356,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Une chanson ? Personne ne m’avait parlé de ça... Excellent, un nouvel indice ! Je savais bien que votre souffrance n’aurait pas été vaine.",
          DialogueId = 10031111,
          FacialId = {
            [1] = "100304:Happy01"
          },
          GUID = "191CA126",
          NextDialogue = 10031112,
          Scripts = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Confident_Start\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "A singing voice? No one else has mentioned that — Great, this is a brand-new lead! I knew your suffering wouldn't be in vain.",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA126"
        },
        [10031112] = {
          Camera = "124.522461,-52.962646,126.131836,0.000177,4.398307,-110.971375,35.0,941.904541,false,DoNotOverride,1.903106",
          ContentFR = "Hé, officier... Vous vous rendez compte que ça sonne un peu déplacé ?",
          DialogueId = 10031112,
          GUID = "191CA150",
          LookAt = {
            [1] = "100304:n(200021)",
            [2] = "100001:n(100304)"
          },
          NextDialogue = 10031113,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"200021:n(100304)\"}},PlayAnimation{ActorId{200021},AnimationId{\"Explain01_Start\"},Duration{2}}}",
          SpeakNpcId = 200021,
          Subtitle = "Ahem, Officer, that might come across as a bit insensitive, don't you think?",
          TalkActionId = {
            [1] = "100304:Confident_End",
            [2] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA150"
        },
        [10031113] = {
          Camera = "90.230469,-472.615723,119.978027,0.000191,-0.400393,102.219055,40.0,941.904541,false,DoNotOverride,1.2",
          ContentFR = "... Vous avez raison. Pardonnez-moi. Je pensais seulement que grâce à ce détail, l’affaire ferait enfin un pas décisif, et que nous pourrions rendre la paix à la population. Je n’ai pas voulu tourner votre douleur en dérision. Toutes mes excuses.",
          DialogueId = 10031113,
          FacialId = {
            [1] = "100304:Shock01"
          },
          GUID = "191CA17A",
          NextOptions = {
            [1] = 10031114,
            [2] = 10031116
          },
          Scripts = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Explain02_Start\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "...My apologies. I was just thinking that with this new clue, we might finally end this case and restore peace to everyone. I didn't mean to trivialise your pain and suffering. I'm truly sorry.",
          TalkActionId = {
            [1] = "200021:Explain01_End",
            [2] = "100304:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA17A"
        },
        [10031114] = {
          ContentFR = "<I>Ce n’est rien.</>",
          DialogueId = 10031114,
          GUID = "191CA1A4",
          ImprPlusId = 1007,
          NextDialogue = 10031115,
          Subtitle = "It's okay."
        },
        [10031115] = {
          Camera = "58.354492,-249.67041,147.177734,0.000189,-3.600589,110.819168,40.0,941.904541,false,DoNotOverride,1.2",
          ContentFR = "Merci pour votre indulgence.",
          DialogueId = 10031115,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191CA1CE",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10031123,
          SpeakNpcId = 100304,
          Subtitle = "Thank you for your understanding.",
          TalkActionId = {
            [1] = "100304:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA1CE"
        },
        [10031116] = {
          ContentFR = "<I>Je veux des dommages et intérêts.</>",
          DialogueId = 10031116,
          GUID = "191CA1F8",
          ImprPlusId = 1010,
          NextDialogue = 10031117,
          Subtitle = "I want compensation for emotional damage."
        },
        [10031117] = {
          Camera = "58.354492,-249.67041,147.177734,0.000189,-3.600589,110.819168,40.0,941.904541,false,DoNotOverride,1.2",
          ContentFR = "Combien ? Si c’est dans mes moyens...",
          DialogueId = 10031117,
          GUID = "191CA222",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10031118,
          SpeakNpcId = 100304,
          Subtitle = "How much do you need? If it's within my means...",
          TalkActionId = {
            [1] = "100304:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA222"
        },
        [10031118] = {
          Camera = "124.522461,-52.962646,126.131836,0.000177,4.398307,-110.971375,35.0,941.904541,false,DoNotOverride,1.903106",
          ContentFR = "Sérieusement ? C’est évidemment une blague... Officier, vous devez être une Charon Couronnée qui n’a pas dû passer beaucoup de temps dans la cité extérieure, hein ?",
          DialogueId = 10031118,
          GUID = "191CA24C",
          NextDialogue = 10031119,
          RelatedWikiId = {
            [1] = 407003
          },
          SpeakNpcId = 200021,
          Subtitle = "Seriously? It's obviously a joke... Officer, you must be a Laurelled Charon who's never dealt with the folks in the outer city, right?",
          TalkActionId = {
            [1] = "200021:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA24C"
        },
        [10031119] = {
          ContentFR = "Si vous alliez dans les taudis en habits civils, vous ne verriez pas la nuit tomber avant de vous faire dépouiller jusqu’aux chaussures.",
          DialogueId = 10031119,
          GUID = "191CA276",
          NextDialogue = 10031120,
          SpeakNpcId = 200021,
          Subtitle = "If you walked into the slums in plain clothes, I bet you wouldn't even make it to sundown without getting swindled out of every coin in your pocket.",
          TalkActionId = {
            [1] = "100304:Explain02_End",
            [2] = "200021:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA276"
        },
        [10031120] = {
          Camera = "149.513672,-169.366943,198.691895,0.000219,-21.601578,154.789032,35.0,324.824371,false,DoNotOverride,22",
          ContentFR = "\"Charon Couronné\" ? ... Je crains de ne pas avoir encore mérité cet honneur.",
          DialogueId = 10031120,
          FacialId = {
            [1] = "100304:Sad02"
          },
          GUID = "191CA2A0",
          NextDialogue = 10031121,
          Scripts = "PlayAnimation{_delay{5},ActorId{100304},AnimationId{\"DisagreeHead\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "\"Laurelled Charon\"... I'm afraid I haven't earned that honour yet.",
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA2A0"
        },
        [10031121] = {
          Camera = "114.541016,142.993408,51.0,0.000056,8.797734,-105.975571,35.0,941.904541,false,DoNotOverride,1.903106",
          ContentFR = "En vérité, je viens moi-même de Brumelac. J’ai connu cette vie, je sais combien il est difficile pour les Charons de la cité extérieure de survivre. C’est pourquoi, quand je peux aider, je le fais.",
          DialogueId = 10031121,
          FacialId = {
            [1] = "100304:Sad02"
          },
          GUID = "191CA2CA",
          NextDialogue = 10031122,
          RelatedWikiId = {
            [1] = 408003
          },
          SpeakNpcId = 100304,
          Subtitle = "Actually, I grew up in Mist Aken myself. I know what it's like — I know how hard it is for Charons in the outer city to make ends meet. So, when I can help, I do what I can.",
          TalkActionId = {
            [1] = "100304:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA2CA"
        },
        [10031122] = {
          ContentFR = "Et puis, c’est moi qui me suis emportée tout à l’heure. Alors...",
          DialogueId = 10031122,
          GUID = "191CA2F4",
          NextDialogue = 10031123,
          SpeakNpcId = 100304,
          Subtitle = "Besides, it was I who spoke out of line earlier, so...",
          TalkActionId = {
            [1] = "100304:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA2F4"
        },
        [10031123] = {
          Camera = "133.141602,-83.859375,106.349609,0.000045,10.39638,-116.369263,35.000011,941.904541,false,DoNotOverride,1.903106",
          ContentFR = "Bon, réglons d’abord cette affaire de \"Traque aux Charons\". Puisqu’il a fallu tout ce mal pour me faire venir ici, autant mener l’enquête sérieusement.",
          DialogueId = 10031123,
          GUID = "191CA31E",
          Scripts = "PlayAnimation{_delay{3},ActorId{100001},AnimationId{\"Explain01_Start\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "Alright, let's put everything else on hold until the \"Charon Hunt\" case is wrapped up. Since you went to all this trouble to bring me here, let's focus on the investigation and get it done.",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "100304:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100311/191CA31E"
        },
        [10031201] = {
          Camera = "-802.193359,-200.429199,291.232422,0.000171,-5.395378,13.011268,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "Concernant ce \"chant de monstre\"... pouvez-vous essayer d’en fredonner la mélodie ?",
          DetectiveQuestionId = 1003,
          DialogueId = 10031201,
          FinalCamera = "-802.193359,-200.429199,291.232422,0.000172,-13.395387,14.612322,35.000011,100000.0,false,Manual,22.0",
          GUID = "191CAFEA",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10031202,
          Scripts = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Explain01_Start\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "About the \"monster's singing\" you mentioned just now... Do you think you could try humming the melody?",
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "100304:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CAFEA"
        },
        [10031202] = {
          Camera = "-71.710938,137.977051,125.391113,0.000207,1.204244,-66.988014,35.000023,358.523438,false,DoNotOverride,22",
          ContentFR = "...",
          DetectiveQuestionId = 1003,
          DialogueId = 10031202,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "191CB014",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          NextDialogue = 10031203,
          Scripts = "PlayAnimation{_delay{3},ActorId{100001},AnimationId{\"Think_Start\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100304:Explain01_End"
          },
          TurnTo = {
            [1] = "100001:n(100304)"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CB014"
        },
        [10031203] = {
          Camera = "-54.453125,66.138184,140.532715,0.000112,-0.197263,-73.591354,35.000011,100000.0,false,DoNotOverride,22",
          ContentFR = "{性别:Désolé|Désolée}. Impossible de retrouver la mélodie.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031203,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "191CB03E",
          LookAt = {
            [1] = "200002:n(100304)"
          },
          NextDialogue = 10031204,
          Scripts = "PlayAnimation{_delay{2},ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "Sorry, I couldn't do it. I can't get the tune right.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CB03E"
        },
        [10031204] = {
          Camera = "-69.961914,-225.399414,156.75,0.000232,-6.595599,79.803307,35.000023,358.523438,false,Manual,3.0",
          ContentFR = "Je comprends. La musique n’est pas mon fort non plus.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031204,
          FacialId = {
            [1] = "100304:Ahaha01"
          },
          GUID = "191CB068",
          NextOptions = {
            [1] = 10031205,
            [2] = 10031207
          },
          SpeakNpcId = 100304,
          Subtitle = "I understand. Music isn't my strong suit either.",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          TurnTo = {
            [1] = "200021:n(100304)"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CB068"
        },
        [10031205] = {
          ContentFR = "<I>Oui, chanter est si difficile.</>",
          DetectiveQuestionId = 1003,
          DialogueId = 10031205,
          GUID = "191CB092",
          ImprPlusId = 1009,
          NextDialogue = 10031206,
          Subtitle = "Yeah, singing is hard."
        },
        [10031206] = {
          Camera = "-54.453125,66.138184,140.532715,0.000112,-0.197263,-73.591354,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "Et puis, je n’ai entendu la chanson qu’une fois. Impossible de retenir l’air. Mais si je l’entends de nouveau, je pourrai sûrement la reconnaître.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031206,
          GUID = "191CB0BC",
          NextDialogue = 10031209,
          SpeakNpcId = 100001,
          Subtitle = "Besides, I only heard it once. It's hard to remember the tune. But if I hear it again, I might be able to recognise it.",
          TalkActionId = {
            [1] = "100304:Explain02_End",
            [2] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CB0BC"
        },
        [10031207] = {
          ContentFR = "<I>Je ne suis pas mauvais en musique. Ne me mettez pas dans le même panier que vous.</>",
          DetectiveQuestionId = 1003,
          DialogueId = 10031207,
          GUID = "191CB0E6",
          ImprPlusId = 1010,
          NextDialogue = 10031208,
          Subtitle = "I'm not bad at music. Don't lump me in with you."
        },
        [10031208] = {
          Camera = "-54.453125,66.138184,140.532715,0.000112,-0.197263,-73.591354,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "J’ai juste oublié parce que je suis resté trop longtemps dans le coma. Si je l’entends à nouveau, je la reconnaîtrai sans aucun doute.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031208,
          GUID = "191CB110",
          NextDialogue = 10031209,
          SpeakNpcId = 100001,
          Subtitle = "I've just been in a coma for too long and forgot. If I hear it again, I'll definitely recognise it.",
          TalkActionId = {
            [1] = "100304:Explain02_End",
            [2] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CB110"
        },
        [10031209] = {
          Camera = "-53.863281,-63.319824,136.021973,0.000113,2.80494,77.005501,35.000015,100000.0,false,Manual,22.0",
          ContentFR = "Alors je compte sur vous pour rester à l’écoute.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031209,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191CB13A",
          SpeakNpcId = 100304,
          Subtitle = "Alright, I'll count on you to keep an ear out for it then.",
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100312/191CB13A"
        },
        [10031210] = {
          ContentFR = "C’est... un morceau de tissu ? Il est plutôt agréable au toucher.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031210,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_MainCurtain.T_Guide_Chapter_MainCurtain'}",
          GUID = "191CB164",
          NextDialogue = 10031211,
          SpeakNpcId = 100001,
          Subtitle = "What's this... a piece of cloth? It feels pretty nice.",
          VoiceName = "voice/$Locale$/story/1003/100312/191CB164"
        },
        [10031211] = {
          ContentFR = "<I>Berry adorerait ce côté tout doux...</>",
          DetectiveQuestionId = 1003,
          DialogueId = 10031211,
          DisableMouth = 1,
          GUID = "191CB18E",
          NextDialogue = 10031212,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Berry would definitely love this fuzzy texture...)",
          VoiceName = "voice/$Locale$/story/1003/100312/191CB18E"
        },
        [10031212] = {
          ContentFR = "Laissez-moi voir... Hmm, du velours. D’après le motif et les plis, il s’agit d’un <H>rideau de scène</>.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031212,
          GUID = "191CB1B8",
          NextDialogue = 10031213,
          SpeakNpcId = 100304,
          Subtitle = "Let me take a look... Hmm, it's velvet. Judging by the patterns and creases, it looks like a piece of a stage curtain.",
          VoiceName = "voice/$Locale$/story/1003/100312/191CB1B8"
        },
        [10031213] = {
          ContentFR = "Le seul endroit avec une scène à proximité, c’est le <H>Théâtre Galea</>. Ils préparent actuellement la <H>Fête de la Chandelle d’Argent</>, et avec toute l’agitation, il n’est pas surprenant que quelqu’un ait accidentellement jeté un vieux rideau.",
          DetectiveQuestionId = 1003,
          DialogueId = 10031213,
          GUID = "191CB1E2",
          NextDialogue = 10031214,
          RelatedWikiId = {
            [1] = 406002,
            [2] = 405006
          },
          SpeakNpcId = 100304,
          Subtitle = "The only place nearby with a stage is the Galea Theatre. They've been preparing for the Silvercandle Carnival, and with all the hustle and bustle, it wouldn't be surprising if someone accidentally discarded an old stage curtain.",
          VoiceName = "voice/$Locale$/story/1003/100312/191CB1E2"
        },
        [10031214] = {
          ContentFR = "<I>Fête de la Chandelle d’Argent... Les décorations dans la cité, c’est donc pour cette fête ?</>",
          DetectiveQuestionId = 1003,
          DialogueId = 10031214,
          DisableMouth = 1,
          GUID = "191CB20C",
          NextDialogue = 10031215,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Silvercandle Carnival... Is that what all the decorations are for?)",
          VoiceName = "voice/$Locale$/story/1003/100312/191CB20C"
        },
        [10031215] = {
          ContentFR = "Seul ce morceau ne suffit pas à tirer des conclusions, mais si l’on combine cette piste avec celle que vous avez mentionnée tout à l’heure...",
          DetectiveQuestionId = 1003,
          DialogueId = 10031215,
          GUID = "191CB236",
          NextDialogue = 10031216,
          SpeakNpcId = 100304,
          Subtitle = "This piece of fabric alone doesn't tell us much. But if we connect it with the clue you mentioned earlier...",
          VoiceName = "voice/$Locale$/story/1003/100312/191CB236"
        },
        [10031216] = {
          ContentFR = "<I>Hmm... un rideau de scène. Cela semble effectivement lié à cette autre piste.</>",
          DetectiveQuestionId = 1003,
          DialogueId = 10031216,
          DisableMouth = 1,
          GUID = "191CB260",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Hmm... A stage curtain. It does seem to connect to that clue somehow.)",
          VoiceName = "voice/$Locale$/story/1003/100312/191CB260"
        },
        [10031301] = {
          ContentFR = "Hé ! Il y a une <H>girouette cassée</> dans cette poubelle. Ouah, elle a l’air quasi neuve ! On l’a juste jetée ? Quel gaspillage... On pourrait l’emporter !",
          DetectiveQuestionId = 1002,
          DialogueId = 10031301,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_Vane.T_Guide_Chapter_Vane'}",
          GUID = "191CC052",
          NextDialogue = 10031302,
          SpeakNpcId = 200002,
          Subtitle = "Hey, look! There's a broken weather vane in this rubbish bin. Wow, it looks practically brand new! Someone just tossed it out like that? What a waste... Let's take it with us!",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC052"
        },
        [10031302] = {
          ContentFR = "Vous collectionnez les girouettes ? Voilà un passe-temps étrange. Je pourrais demander à un de mes subordonnés de vous en acheter une neuve, mais celle-ci est une pièce à conviction, vous ne pouvez pas la garder.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031302,
          GUID = "191CC07C",
          NextDialogue = 10031303,
          SpeakNpcId = 100304,
          Subtitle = "Do you collect weather vanes? That's quite an unusual hobby. I could have one of my subordinates get you a new one, but this is a piece of evidence — you can't have it now.",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC07C"
        },
        [10031303] = {
          ContentFR = "Euh... Je disais ça comme ça... Je... je n’ai pas vraiment un faible pour les girouettes...",
          DetectiveQuestionId = 1002,
          DialogueId = 10031303,
          GUID = "191CC0A6",
          NextDialogue = 10031304,
          SpeakNpcId = 200002,
          Subtitle = "Uh... I was just saying it offhand. I-It's not like I actually have a thing for weather vanes or anything...",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC0A6"
        },
        [10031304] = {
          ContentFR = "Ouinn, c’est la première fois que quelqu’un prend mes paroles au sérieux... je suis trop touchée... ouinn...",
          DetectiveQuestionId = 1002,
          DialogueId = 10031304,
          GUID = "191CC0D0",
          NextDialogue = 10031305,
          SpeakNpcId = 200002,
          Subtitle = "Waaah, someone actually took my words seriously for once... I'm so touched, waaah...",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC0D0"
        },
        [10031305] = {
          ContentFR = "Officier Fischer, depuis quand cette rue est-elle scellée ?",
          DetectiveQuestionId = 1002,
          DialogueId = 10031305,
          GUID = "191CC0FA",
          NextDialogue = 10031306,
          SpeakNpcId = 100001,
          Subtitle = "Officer Fischer, when was this street sealed off?",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC0FA"
        },
        [10031306] = {
          ContentFR = "Le matin suivant le premier incident de \"Traque aux Charons\".",
          DetectiveQuestionId = 1002,
          DialogueId = 10031306,
          GUID = "191CC124",
          NextDialogue = 10031307,
          SpeakNpcId = 100304,
          Subtitle = "The morning after the first \"Charon Hunt\" incident.",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC124"
        },
        [10031307] = {
          ContentFR = "C’est relativement rapide... Et comme cette girouette est pratiquement neuve, elle n’a sûrement pas été jetée volontairement...",
          DetectiveQuestionId = 1002,
          DialogueId = 10031307,
          GUID = "191CC14E",
          NextDialogue = 10031308,
          SpeakNpcId = 100001,
          Subtitle = "That's fairly prompt... Since this weather vane is practically new, it shouldn't have been discarded on purpose...",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC14E"
        },
        [10031308] = {
          ContentFR = "Ce serait à cause de la tempête cette nuit-là ?",
          DetectiveQuestionId = 1002,
          DialogueId = 10031308,
          GUID = "191CC178",
          NextDialogue = 10031309,
          SpeakNpcId = 200021,
          Subtitle = "Could it have been the strong winds that night?",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC178"
        },
        [10031309] = {
          ContentFR = "Non. Après la tempête il y a cinq jours, le Bureau de la Sécurité a bien reçu de nombreux rapports de dommages matériels, mais cette girouette n’a pas été soufflée par le vent, il est beaucoup plus probable qu’elle ait été <H>renversée par le coup de l’agresseur</>.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031309,
          GUID = "191CC1A2",
          NextDialogue = 10031310,
          SpeakNpcId = 100304,
          Subtitle = "No. After the storm five days ago, the Security Bureau did receive numerous reports of property damage, but this weather vane wasn't blown off — it's much more likely knocked down by the perpetrator.",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC1A2"
        },
        [10031310] = {
          ContentFR = "Selon le témoignage de Madame Camilla, le coupable a sauté sur le <H>toit</> après l’avoir affrontée. Cette girouette doit provenir de là.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031310,
          GUID = "191CC1CC",
          NextDialogue = 10031311,
          SpeakNpcId = 100304,
          Subtitle = "According to Ms Camilla's account, the perpetrator jumped onto the rooftop after engaging with her. This weather vane must have fallen from up there.",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC1CC"
        },
        [10031311] = {
          ContentFR = "<I>Le toit... autant aller y jeter un œil.</>",
          DetectiveQuestionId = 1002,
          DialogueId = 10031311,
          DisableMouth = 1,
          GUID = "191CC1F6",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(The rooftop... might as well check it out.)",
          VoiceName = "voice/$Locale$/story/1003/100313/191CC1F6"
        },
        [10031401] = {
          ContentFR = "C’est bien celle-ci, l’angle de rupture correspond parfaitement. À en juger par la courbure de la base, il semble que ce ne soit pas le vent qui l’ait emportée, mais qu’elle ait été frappée avec force.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031401,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_VaneBottom.T_Guide_Chapter_VaneBottom'}",
          GUID = "191CD0BA",
          NextDialogue = 10031402,
          SpeakNpcId = 100304,
          Subtitle = "This is it. The break aligns perfectly. Judging by the bending on the base, apparently it was not blown off by the wind — it was struck with force.",
          VoiceName = "voice/$Locale$/story/1003/100314/191CD0BA"
        },
        [10031402] = {
          ContentFR = "Et à partir de cet angle, on peut déduire dans quelle direction l’agresseur s’est enfui.",
          DetectiveQuestionId = 1002,
          DialogueId = 10031402,
          GUID = "191CD0E4",
          SpeakNpcId = 100304,
          Subtitle = "And based on the angle of bending, we can deduce the direction the perpetrator fled.",
          VoiceName = "voice/$Locale$/story/1003/100314/191CD0E4"
        },
        [10031501] = {
          Camera = "-300.109375,-328.852295,9.648438,0.000113,8.397396,46.788681,30.0,100000.0,false,Manual,3.0-300.109375,-328.852295,9.648438,0.000113,8.397396,46.788681,30.0,100000.0,false,Manual,22.0",
          ContentFR = "C’est exact, vous l’avez vu aussi. L’agresseur a fui en direction du sud-ouest.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031501,
          FinalCamera = "-300.109375,-328.852295,9.648438,0.000112,13.797432,46.589191,30.0,100000.0,false,Manual,22.0",
          GUID = "191CE122",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100001:n(100304)",
            [3] = "200002:n(100304)",
            [4] = "100304:n(100001)"
          },
          NextDialogue = 10031502,
          SpeakNpcId = 100304,
          Subtitle = "That's right, you saw it too. The perpetrator fled southwest.",
          TalkActionId = {
            [1] = "100304:Explain01_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100315/191CE122"
        },
        [10031502] = {
          Camera = "-196.082031,-87.382202,123.586182,0.000121,4.399837,29.404526,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "Si vous le savez déjà, pourquoi les Veilleurs ne vont-ils pas directement fouiller ?",
          DetectiveQuestionId = 1004,
          DialogueId = 10031502,
          FacialId = {
            [1] = "200021:Think01"
          },
          GUID = "191CE14C",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10031503,
          SpeakNpcId = 200021,
          Subtitle = "If you already know that, why hasn't the Escort gone over there to search?",
          TalkActionId = {
            [1] = "200021:Think_Start",
            [2] = "100304:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE14C"
        },
        [10031503] = {
          Camera = "210.840332,-20.857056,160.915527,0.000128,-7.400673,172.395859,35.000011,328.483368,false,Manual,3.0",
          ContentFR = "Manque de personnel et renseignements incomplets.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031503,
          FacialId = {
            [1] = "200021:None",
            [2] = "100304:Sad01"
          },
          GUID = "191CE176",
          NextDialogue = 10031504,
          SpeakNpcId = 100304,
          Subtitle = "We're short on manpower, and our intel is incomplete.",
          TalkActionId = {
            [1] = "100304:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE176"
        },
        [10031504] = {
          ContentFR = "Nous avons procédé à des vérifications dans les usines, habitations et écoles du sud-ouest, mais la zone est trop vaste. Aucun progrès significatif pour l’instant.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031504,
          GUID = "191CE1A0",
          NextDialogue = 10031505,
          SpeakNpcId = 100304,
          Subtitle = "We've been systematically combing through the factories, residences, and schools in the southwest, but the sheer scale of the area has made progress slow. So far, there's been no major breakthrough.",
          TalkActionId = {
            [1] = "200021:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE1A0"
        },
        [10031505] = {
          Camera = "53.891113,3.93689,137.345459,0.00013,-1.601071,-174.00856,35.000011,103.373474,DoNotOverride,22",
          ContentFR = "Pour être honnête, sur cette affaire, il n’y a que moi et quelques subordonnés... L’un d’eux a été tué par ce monstre. Il faisait partie des victimes du 25 novembre.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031505,
          FinalCamera = "16.574219,0.020508,136.559082,0.00013,-1.201041,-174.00856,35.000011,103.373474,DoNotOverride,22",
          GUID = "191CE1CA",
          LookAt = {
            [1] = "100304:n(100304)"
          },
          NextDialogue = 10031506,
          SpeakNpcId = 100304,
          Subtitle = "To be honest, it's just me and a few of my subordinates working on this case... And one of them was killed by that perpetrator. He was among the victims on November 25.",
          TalkActionId = {
            [1] = "100304:Sigh_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100315/191CE1CA"
        },
        [10031506] = {
          ContentFR = "Quand nous l’avons retrouvé, tous ses organes internes avaient été écrasés, comme de la pâte sous un rouleau à pâtisserie.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031506,
          GUID = "191CE1F4",
          NextDialogue = 10031507,
          SpeakNpcId = 100304,
          Subtitle = "When we found him, all his internal organs had been crushed, like dough flattened under a rolling pin.",
          TalkActionId = {
            [1] = "100304:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE1F4"
        },
        [10031507] = {
          Camera = "-192.28125,-79.032227,113.535645,0.000153,6.002226,26.208307,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "... Mes condoléances.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031507,
          FacialId = {
            [1] = "200021:Sad01"
          },
          GUID = "191CE21E",
          NextDialogue = 10031508,
          SpeakNpcId = 200021,
          Subtitle = "...My condolences.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE21E"
        },
        [10031508] = {
          Camera = "25.955078,-88.894897,153.555908,0.000082,-7.000821,146.786774,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "Attraper l’agresseur est le seul moyen de rendre justice et de faire honneur à tous. Mais... nous n’avons toujours pas trouvé ce monstre.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031508,
          FacialId = {
            [1] = "100304:Unhappy01"
          },
          GUID = "191CE248",
          NextDialogue = 10031509,
          SpeakNpcId = 100304,
          Subtitle = "Catching the perpetrator is the only way to honour him and deliver true justice and closure to all. But... we haven't found that monster yet.",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE248"
        },
        [10031509] = {
          ContentFR = "J’ai plusieurs fois demandé du renfort à mes supérieurs, mais mes demandes ont été rejetées, ou plutôt, ils veulent que je localise précisément la cachette de l’agresseur avant de pouvoir envoyer des renforts.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031509,
          GUID = "191CE272",
          NextDialogue = 10031510,
          Scripts = "PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Explain02_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "I've requested reinforcements from my superiors multiple times, but my applications keep getting denied — or rather, they say I need to pinpoint the perpetrator's exact hideout before my request can be approved.",
          VoiceName = "voice/$Locale$/story/1003/100315/191CE272"
        },
        [10031510] = {
          Camera = "-75.790039,-151.490479,103.759521,0.000096,7.797897,37.589153,35.000015,320.964508,false,Manual,3.0",
          ContentFR = "Laissez-moi deviner, c’était dans un quartier Charon, le monstre ne va pas vers la cité intérieure... donc vos supérieurs s’en moquent ?",
          DetectiveQuestionId = 1004,
          DialogueId = 10031510,
          FacialId = {
            [1] = "200021:Angry01"
          },
          GUID = "191CE29C",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10031511,
          SpeakNpcId = 200021,
          Subtitle = "Let me guess — it happened in a Charon neighbourhood, and the monster isn't headed for the inner city. So your superiors just don't care, right?",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE29C"
        },
        [10031511] = {
          Camera = "234.138672,-54.546997,140.426514,0.000134,-4.200279,171.592026,35.0,328.483368,false,Manual,22.0",
          ContentFR = "Je n’oserais pas faire de telles suppositions.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031511,
          FacialId = {
            [1] = "100304:Sad02"
          },
          GUID = "191CE2C6",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          NextDialogue = 10031512,
          SpeakNpcId = 100304,
          Subtitle = "I wouldn't dare make such assumptions.",
          TalkActionId = {
            [1] = "100304:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE2C6"
        },
        [10031512] = {
          Camera = "-75.790039,-151.490479,103.759521,0.000096,7.797897,37.589153,35.000015,320.964508,false,Manual,3.0",
          ContentFR = "Hum.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031512,
          GUID = "191CE2F0",
          NextDialogue = 10031513,
          Scripts = "PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"DisagreeHead\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Heh.",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE2F0"
        },
        [10031513] = {
          Camera = "-173.730469,-12.869507,127.995117,0.000144,-0.600647,-13.806776,35.000015,234.613907,false,Manual,3.0",
          ContentFR = "Alors accélérons les choses et aidons l’Officier Fischer à résoudre cette affaire au plus vite.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031513,
          GUID = "191CE31A",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10031514,
          SpeakNpcId = 100001,
          Subtitle = "Then let's pick up the pace and help Officer Fischer solve this case as quickly as possible.",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE31A"
        },
        [10031514] = {
          Camera = "129.509766,-215.724609,129.291016,0.000136,-1.800014,129.604965,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "Merci infiniment !",
          DetectiveQuestionId = 1004,
          DialogueId = 10031514,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191CE344",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          SpeakNpcId = 100304,
          Subtitle = "Thank you so much!",
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100315/191CE344"
        },
        [10031601] = {
          ContentFR = "C’est... de la neige bleue ?",
          DetectiveQuestionId = 1004,
          DialogueId = 10031601,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_MoonWaterOnSnow.T_Guide_Chapter_MoonWaterOnSnow'}",
          GUID = "191CF18A",
          NextDialogue = 10031602,
          SpeakNpcId = 100001,
          Subtitle = "Is this... blue snow?",
          VoiceName = "voice/$Locale$/story/1003/100316/191CF18A"
        },
        [10031602] = {
          ContentFR = "J’ai vérifié, ce sont quelques gouttes de <H>Phoxichor</>. Quand il s’infiltre dans la neige, il s’étale comme une petite fleur.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031602,
          GUID = "191CF1B4",
          NextDialogue = 10031603,
          SpeakNpcId = 100304,
          Subtitle = "I've checked — it's a few drops of Phoxichor. When it seeps into the snow, it spreads out like a flower.",
          VoiceName = "voice/$Locale$/story/1003/100316/191CF1B4"
        },
        [10031603] = {
          ContentFR = "C’est beau, n’est-ce pas ? Chaque fois que je vois ces petites \"fleurs\" bleues, j’ai l’impression que toute ma fatigue disparaît.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031603,
          GUID = "191CF1DE",
          NextDialogue = 10031604,
          SpeakNpcId = 100304,
          Subtitle = "Beautiful, isn't it? Every time I see these little blue \"flowers,\" it feels like the day's exhaustion simply melts away.",
          VoiceName = "voice/$Locale$/story/1003/100316/191CF1DE"
        },
        [10031604] = {
          ContentFR = "Vu la couleur, la pureté est assez élevée... Il y aurait eu une fuite de Phoxichor ?",
          DetectiveQuestionId = 1004,
          DialogueId = 10031604,
          GUID = "191CF208",
          NextDialogue = 10031605,
          SpeakNpcId = 200021,
          Subtitle = "Look at this colour — the purity seems pretty high. Could there have been a Phoxichor leak?",
          VoiceName = "voice/$Locale$/story/1003/100316/191CF208"
        },
        [10031605] = {
          ContentFR = "Hmm... c’est possible. Mais par précaution, j’ai besoin de confirmer quelque chose avec vous, {nickname}.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031605,
          GUID = "191CF232",
          SpeakNpcId = 100304,
          Subtitle = "Hmm... That is possible. But just to be sure, I need to confirm something with .",
          VoiceName = "voice/$Locale$/story/1003/100316/191CF232"
        },
        [10031701] = {
          Camera = "-606.177734,-381.434937,-17.229248,-0.001038,12.606322,29.999029,35.000015,1068.077393,false,Manual,1.2",
          ContentFR = "Le Phoxichor, donc... Pour être sûre, laissez-moi vous poser une question.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031701,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "-606.177734,-381.434937,-17.229248,-0.001038,10.206399,27.999102,35.000015,1068.077393,false,Manual,1.2",
          GUID = "191D01F2",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100001:n(100304)",
            [3] = "200002:n(100304)",
            [4] = "100304:n(100001)"
          },
          NextDialogue = 10031702,
          SpeakNpcId = 100304,
          Subtitle = "The Phoxichor... Hmm, there's something I need to ask, just to clarify.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100317/191D01F2"
        },
        [10031702] = {
          Camera = "89.222656,-173.515381,134.491943,0.000058,-2.800077,128.408691,35.000008,1068.077393,false,DoNotOverride,1.2",
          ContentFR = "Lorsque vous avez été attaqué, avez-vous senti une odeur âcre ? Disons... 80 % de peinture mélangée à 20 % de pain moisi ? Pardon, je ne suis pas très douée avec les comparaisons...",
          DetectiveQuestionId = 1004,
          DialogueId = 10031702,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "85.961914,-176.022827,134.491943,0.000058,-2.800077,125.808693,35.000008,1068.077393,false,DoNotOverride,1.2",
          GUID = "191D021C",
          NextDialogue = 10031703,
          Scripts = "PlayAnimation{_delay{8},ActorId{100304},AnimationId{\"Think_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "When you encountered the perpetrator, did you notice any strange smells? Something sharp and unpleasant — like a mix of 80% paint and 20% mouldy bread? Sorry, I'm not great with analogies...",
          TalkActionId = {
            [1] = "100304:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100317/191D021C"
        },
        [10031703] = {
          Camera = "-86.515625,-65.973633,106.226318,0.000065,7.599678,-10.196134,35.000011,1068.077393,false,DoNotOverride,1.2",
          ContentFR = "<I>C’est quoi, cette description d’odeur !</>",
          DetectiveQuestionId = 1004,
          DialogueId = 10031703,
          DisableMouth = 1,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "-85.334961,-59.396606,106.226318,0.000066,7.599678,-13.396557,35.000011,1068.077393,false,DoNotOverride,1.2",
          GUID = "191D0246",
          NextDialogue = 10031704,
          SpeakNpcId = 100001,
          Subtitle = "(What kind of smell is that supposed to be!?)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100317/191D0246"
        },
        [10031704] = {
          Camera = "-96.705078,-143.869263,95.202881,0.000087,9.999096,26.805567,35.000008,1068.077393,false,DoNotOverride,1.2",
          ContentFR = "Hmm... Je ne saurais pas dire à quoi ça correspond, mais en y repensant, quand l’agresseur s’est jeté sur moi, j’ai effectivement été pris à la gorge par une odeur piquante.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031704,
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "-96.705078,-143.869263,104.202881,0.000087,9.999096,26.805567,35.000008,1068.077393,false,DoNotOverride,1.2",
          GUID = "191D0270",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10031705,
          Scripts = "PlayAnimation{_delay{5},ActorId{100001},AnimationId{\"Think_End\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "Hmm... I'm not sure what you mean, but now that you mention it, I do remember being hit by a sharp, acrid smell when the perpetrator lunged at me.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100317/191D0270"
        },
        [10031705] = {
          Camera = "-18.842773,-73.567017,152.472168,14.402329,-18.200684,-16.794279,35.000008,1068.077393,false,DoNotOverride,1.2",
          ContentFR = "Oh... Vous pensez que ce Phoxichor provenait de lui ?",
          DetectiveQuestionId = 1004,
          DialogueId = 10031705,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "-17.683594,-69.659546,151.472412,14.402889,-18.200684,-20.594292,35.000008,1068.077393,false,DoNotOverride,1.2",
          GUID = "191D029A",
          NextDialogue = 10031706,
          SpeakNpcId = 100001,
          Subtitle = "Oh, so you think this Phoxichor might have come from the perpetrator?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100317/191D029A"
        },
        [10031706] = {
          Camera = "30.242188,-125.663452,122.202881,0.00007,2.198481,134.384232,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "C’est très probable. Le Phoxichor raffiné par les Éolipyliens contient toujours des gaz irritants. Puisque vous avez senti cette odeur à ce moment-là, cela veut dire que...",
          DetectiveQuestionId = 1004,
          DialogueId = 10031706,
          FacialId = {
            [1] = "100304:Confident01"
          },
          GUID = "191D02C4",
          NextDialogue = 10031707,
          SpeakNpcId = 100304,
          Subtitle = "Exactly. The Phoxichor produced by The Aeolipile is mixed with irritant gases. If you noticed a strong smell at the time, it likely means...",
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100317/191D02C4"
        },
        [10031707] = {
          Camera = "543.564453,-205.252319,435.404053,0.000018,-33.600193,159.203293,35.000008,716.027466,false,Manual,3.75987",
          ContentFR = "L’agresseur en était couvert. Ces petites \"fleurs\" bleues ont dû couler directement de son corps.",
          DetectiveQuestionId = 1004,
          DialogueId = 10031707,
          FinalCamera = "543.564453,-205.252319,435.404053,0.000016,-31.200125,159.203293,35.000008,716.027466,false,Manual,3.75987",
          GUID = "191D02EE",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10031708,
          Scripts = "PlayAnimation{_delay{5},ActorId{100304},AnimationId{\"Talk03_Start\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "The perpetrator was covered in a large amount of Phoxichor. And these blue \"flowers\" must be traces of it dripping from its body.",
          TalkActionId = {
            [1] = "100304:Give"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100317/191D02EE"
        },
        [10031708] = {
          Camera = "-417.143555,-180.520386,240.427246,0.000078,-15.201309,20.769833,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "À Givrelac, seuls quelques endroits permettent d’entrer en contact avec une telle quantité de Phoxichor. En recoupant cela avec l’autre indice, nous devrions pouvoir localiser sa cachette...",
          DetectiveQuestionId = 1004,
          DialogueId = 10031708,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "-411.535156,-195.579224,240.427246,0.00008,-15.201316,23.169575,35.000008,100000.0,false,Manual,22.0",
          GUID = "191D0318",
          LookAt = {
            [1] = "200021:n(100304)"
          },
          Scripts = [[
SEQ{
CameraMoveTo{_delay{10.1},TargetPosition{"63.268066,-21.932739,125.937256,0.000074,-0.001619,174.367065,35.000008,100000.0,false,DoNotOverride,22.0"},duration{0}},PlayAnimation{ActorId{100304},AnimationId{"Think_Start"},Duration{2}}
}]],
          SpeakNpcId = 100304,
          Subtitle = "There are only a few places in Icelake where someone could come into contact with that much Phoxichor. Combine this with the other clues, and we should be able to narrow down the perpetrator's hideout...",
          TalkActionId = {
            [1] = "100304:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100317/191D0318"
        },
        [10031801] = {
          Camera = "-342.152344,282.909912,272.925049,0.000034,-19.599909,-37.180103,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Ça doit être tout, non ? Je doute qu’on trouve autre chose par ici.",
          DialogueId = 10031801,
          FinalCamera = "-331.673828,296.23291,272.925049,0.000032,-19.599909,-39.579273,35.000008,100000.0,false,Manual,22.0",
          GUID = "191D125A",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100001:n(100304)",
            [3] = "200002:n(100304)",
            [4] = "100304:n(200021)"
          },
          NextDialogue = 10031802,
          SpeakNpcId = 200021,
          Subtitle = "Looks like that's about it. I don't think we'll find any more clues around here.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100318/191D125A"
        },
        [10031802] = {
          Camera = "44.365234,78.752808,133.202881,0.000121,-1.600279,-147.961914,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "Je vous présente mes excuses. Laisser un tel crime se produire dans la cité extérieure... c’est un manquement des Veilleurs.",
          DialogueId = 10031802,
          FacialId = {
            [1] = "100304:Disappoint01"
          },
          FinalCamera = "48.303223,72.461182,133.202881,0.000121,-1.600279,-150.161926,35.000011,100000.0,false,Manual,22.0",
          GUID = "191D1284",
          NextDialogue = 10031803,
          Scripts = "PARA{PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Talk01_End\"},Duration{2}},PlayAnimation{_delay{6},ActorId{100304},AnimationId{\"Explain02_End\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "I apologise on behalf of the Escort. The fact that such a heinous crime occurred in the outer city is a failure on our part.",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100318/191D1284"
        },
        [10031803] = {
          Camera = "-132.708008,65.039062,117.88916,0.000001,4.998906,-11.002963,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Officier, vous n’étiez pas en charge de ce secteur auparavant, pas vrai ? Vous venez d’être affectée ici ?",
          DialogueId = 10031803,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "-179.000977,74.04187,113.763672,0.0,4.598903,-11.002993,35.000008,100000.0,false,Manual,22.0",
          GUID = "191D12AE",
          NextDialogue = 10031804,
          SpeakNpcId = 200021,
          Subtitle = "Officer Fischer, you weren't in charge of this area before, right? Did you just get reassigned here recently?",
          TalkActionId = {
            [1] = "200021:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100318/191D12AE"
        },
        [10031804] = {
          Camera = "-16.977539,46.6698,125.709717,0.000075,6.600018,-144.78064,35.000011,100000.0,false,DoNotOverride,22",
          ContentFR = "Oui. Avant, je travaillais dans le quartier ouest. Le mois dernier, j’ai été promue adjudante et on m’a transférée ici, responsable de la sécurité du quartier est.",
          DialogueId = 10031804,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "-19.689453,50.511108,125.709717,0.000077,6.600018,-142.580902,35.000011,100000.0,false,DoNotOverride,22",
          GUID = "191D12D8",
          NextDialogue = 10031805,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{3},TargetPosition{\"204.946777,101.599731,159.530762,0.000074,-7.599855,-152.38298,35.000008,100000.0,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"207.978027,96.109253,159.530762,0.000074,-7.599855,-152.383148,35.000008,100000.0,false,Manual,22.0\"},duration{5}}},PlayAnimation{_delay{3},ActorId{100304},AnimationId{\"Talk03_Start\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "That's correct. I used to work on different tasks in the western district. I was promoted to Warrant Officer last month and reassigned here to oversee the safety of the eastern district.",
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100318/191D12D8"
        },
        [10031805] = {
          Camera = "-73.910156,65.542358,74.60791,0.000098,0.799842,23.224178,35.000011,100000.0,false,DoNotOverride,22",
          ContentFR = "Pas étonnant qu’on ne t’ait jamais vue avant ! Officier Fischer, tu donnes une impression très différente des autres soldats.",
          DialogueId = 10031805,
          FacialId = {
            [1] = "200002:Smile01"
          },
          FinalCamera = "-90.253906,58.527954,74.360107,0.000098,0.799842,23.223717,35.000011,100000.0,false,DoNotOverride,22",
          GUID = "191D1302",
          NextDialogue = 10031806,
          SpeakNpcId = 200002,
          Subtitle = "No wonder we haven't seen you before! You come off as... very different from the other soldiers, Officer Fischer.",
          TalkActionId = {
            [1] = "200002:Think_Start",
            [2] = "100304:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100318/191D1302"
        },
        [10031806] = {
          Camera = "191.307129,435.008789,37.078125,0.00013,7.99826,-112.344269,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Différente ?",
          DialogueId = 10031806,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "210.843262,426.630981,37.078125,0.000135,7.99826,-114.742035,35.000008,100000.0,false,Manual,22.0",
          GUID = "191D132C",
          LookAt = {
