          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100318/191D132C"
        },
        [10031807] = {
          Camera = "-326.931641,-120.544556,20.60791,0.000194,7.801114,24.140871,45.0,467.682953,false,Manual,1.2",
          ContentFR = "Ben oui ! Les Veilleurs, d’habitude, ils s’en fichent des Charons. Mais toi, on dirait que tu fais vraiment tout ton possible pour protéger tout le monde.",
          DialogueId = 10031807,
          FacialId = {
            [1] = "200002:Happy01"
          },
          FinalCamera = "-326.931641,-120.544556,20.60791,0.000193,12.001059,23.740007,45.0,467.682953,false,Manual,1.2",
          GUID = "191D1356",
          NextDialogue = 10031808,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-20.78418,81.839844,115.9646,0.000192,-23.001925,28.659264,35.000011,100000.0,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-22.509766,85.253906,115.9646,0.000191,-23.001917,26.458944,35.000011,100000.0,false,Manual,22.0\"},duration{5}}},PlayAnimation{_delay{2},ActorId{200002},AnimationId{\"Explain02_Start\"},Duration{2}}}",
          SpeakNpcId = 200002,
          Subtitle = "Uh-huh! The Escort soldiers usually don't care about what happens to Charons. But you... you seem to care, and you try reeeally hard to protect everyone.",
          TalkActionId = {
            [1] = "200002:Agree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100318/191D1356"
        },
        [10031808] = {
          Camera = "-19.192383,-14.246948,123.953857,0.000194,4.197493,-51.741867,35.000011,100000.0,false,DoNotOverride,22",
          ContentFR = "<I>... Tout son possible pour protéger tout le monde ?</>",
          DialogueId = 10031808,
          DisableMouth = 1,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "-16.361328,-12.029907,123.953857,0.000194,4.197493,-53.941723,35.000011,100000.0,false,DoNotOverride,22",
          GUID = "191D1380",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10031809,
          SpeakNpcId = 100001,
          Subtitle = "(...Trying hard to protect everyone?)",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100318/191D1380"
        },
        [10031809] = {
          ContentFR = "Le Souillé est extrêmement dangereux. Même s’il a cessé d’attaquer, il pourrait simplement être en sommeil. Allez vite vous réfugier dans la cité. Les Veilleurs se chargeront du reste.",
          DialogueId = 10031809,
          GUID = "191D13AA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10031809.T_Story_Recall_10031809'",
          NextDialogue = 10031810,
          SpeakNpcId = 100304,
          Subtitle = "The Filthoid is highly dangerous. Although it's ceased attacking, it may only be in temporary dormancy. Return to the city immediately — the Escort will take it from here.",
          VoiceName = "voice/$Locale$/story/1003/100318/191D13AA"
        },
        [10031810] = {
          Camera = "-6.571289,-30.124878,167.953857,0.000099,-24.802855,-53.526508,35.000011,100000.0,false,DoNotOverride,22",
