        [10031811] = {
          Camera = "-3.238281,-27.738281,167.953857,0.000103,-24.802847,-55.926167,35.000011,100000.0,false,DoNotOverride,22",
          ContentFR = "<I>Assez. Ce n’est pas le moment de penser à ça... Concentre-toi sur les indices.</>",
          DialogueId = 10031811,
          DisableMouth = 1,
          GUID = "191D13FE",
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-383.398438,416.402466,79.084717,0.000141,3.59604,-47.732109,35.000008,100000.0,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-374.693359,424.314697,79.084717,0.000141,3.59604,-48.731846,35.000008,100000.0,false,Manual,22.0\"},duration{5}}}",
