    Loader = function()
      return {
        [10032204] = {
          Camera = "-38.398422,-255.859344,70.714844,0.000165,6.599745,108.419289,40.0,340.239532,false,Manual,3.429005",
          ContentFR = "Les coutures ne tiennent pas, le motif est grossier... Le Théâtre Galea n’utiliserait jamais une camelote pareille. Qui vous envoie ? Vous êtes un de ces journaleux à ragots ? Vous voulez salir notre réputation en disant qu’on utilise des décors de pacotille ?",
          DialogueId = 10032204,
          FinalCamera = "-38.398422,-255.859344,70.714844,0.000166,7.799755,108.219391,40.0,340.239532,false,Manual,3.429005",
          GUID = "191D5478",
          NextDialogue = 10032205,
          SpeakNpcId = 100329,
          Subtitle = "The stitching is a mess, and the pattern's just as bad. Galea Theatre would never use something this shoddy. Who sent you? Are you some tabloid hack trying to smear our theatre?",
          TalkActionId = {
            [1] = "100329:Disagree",
            [2] = "100001:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100322/191D5478"
        },
        [10032205] = {
          Camera = "-103.923096,98.783195,108.738281,0.000139,7.197059,-62.586468,35.000011,284.991394,false,DoNotOverride,3.584893",
          ContentFR = "Hé, du calme ! Rien de tout ça. On a trouvé ce tissu sur une scène de crime liée à la \"Traque aux Charons\", on vient juste vérifier, c’est tout.",
          DialogueId = 10032205,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "-96.228012,102.699203,108.738281,0.000139,7.197059,-64.586884,35.000011,284.991394,false,DoNotOverride,3.584893",
          GUID = "191D54A2",
          NextDialogue = 10032206,
          SpeakNpcId = 200021,
          Subtitle = "Whoa, calm down. We're not tabloid hacks. We found this at the \"Charon Hunt\" crime scene and just wanted to get some information.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100322/191D54A2"
        },
        [10032206] = {
          Camera = "134.718857,678.446716,706.917969,-0.001009,-39.19453,-108.145706,40.0,340.239532,false,DoNotOverride,3.429005",
          ContentFR = "... Alors maintenant, vous insinuez qu’on est mêlés à un meurtre ?! Vous n’êtes que des foutus journaleux !",
          DialogueId = 10032206,
          FacialId = {
            [1] = "200021:Confident01"
          },
          FinalCamera = "161.966888,668.893982,706.917969,-0.001007,-39.194515,-110.545403,40.0,340.239532,false,DoNotOverride,3.429005",
          GUID = "191D54CC",
          NextOptions = {
            [1] = 10032207,
            [2] = 10032208
          },
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-36.183578,-243.968689,115.859375,0.000218,2.599987,118.410843,35.000008,100000.0,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-36.183578,-243.968689,121.722656,0.000225,1.199948,118.210846,35.000008,100000.0,false,Manual,22.0\"},duration{5}}}",
          SpeakNpcId = 100329,
          Subtitle = "...Now you're accusing us of being involved in a murder case!? You filthy tabloid hack!",
          TalkActionId = {
            [1] = "100329:Angry01_Start",
            [2] = "200021:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100322/191D54CC"
        },
        [10032207] = {
          ContentFR = "<I>On vous a dit qu’on n’était pas des journalistes !</>",
          DialogueId = 10032207,
          GUID = "191D54F6",
          ImprPlusId = 1007,
          NextDialogue = 10032209,
          Subtitle = "He told you we're not tabloid hacks!"
        },
        [10032208] = {
          ContentFR = "<I>Répète encore une fois « journaleux », et je t’enfonce ce chiffon sorti tout droit des poubelles... dans la gorge.</>",
          DialogueId = 10032208,
          GUID = "191D5520",
          ImprPlusId = 1010,
          NextDialogue = 10032209,
          Subtitle = "One more word about tabloid hack, and I'll shove this dirty rag — straight from the rubbish bin — down your throat."
        },
        [10032209] = {
          Camera = "-91.937477,-19.004244,138.511719,0.000139,-2.397847,-94.204163,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Nous assistons les Veilleurs dans l’enquête sur la \"Traque aux Charons\". Nous avons trouvé ce velours sur les lieux de l’attaque, et nous devons vérifier son origine. Merci de bien vouloir coopérer.",
          DialogueId = 10032209,
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "-85.894508,-19.564302,138.511719,0.000138,-2.597869,-96.603889,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191D5521",
          NextDialogue = 10032210,
          Scripts = "PlayAnimation{_delay{3},ActorId{100001},AnimationId{\"Confident_Start\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "We're assisting the Escort in investigating the \"Charon Hunt\" case. This velvet cloth was found at the crime scene, and we need your cooperation to verify its origin.",
          TalkActionId = {
            [1] = "200021:Talk01_End",
            [2] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100322/191D5521"
        },
        [10032210] = {
          Camera = "-82.898415,-30.874966,169.933594,0.000135,-14.003205,122.032799,45.000011,284.991394,false,DoNotOverride,3.584893",
          ContentFR = "... Les Veilleurs ? D’accord, j’ai réagi trop vite. Désolé.",
          DialogueId = 10032210,
          FacialId = {
            [1] = "100329:CM_Idle"
          },
          FinalCamera = "-82.898415,-30.874966,167.605469,0.000139,-12.403131,121.633614,45.000023,284.991394,false,DoNotOverride,3.584893",
          GUID = "191D554A",
          NextDialogue = 10032211,
          SpeakNpcId = 100329,
          Subtitle = "The Escort... Alright, guess I was too sensitive. Sorry about that.",
          TalkActionId = {
            [1] = "100329:Angry01_End",
            [2] = "100001:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100322/191D554A"
        },
        [10032211] = {
          Camera = "195.853271,-530.033142,237.539062,7.201614,-13.600497,120.839867,45.0,284.991394,false,DoNotOverride,3.584893",
          ContentFR = "Depuis cette histoire, il y a deux ans, on a des rumeurs qui nous collent à la peau... Ces foutus journaleux racontaient que la troupe n’était qu’une bande d’imposteurs. Ça a rendu notre directrice malade au point de rester alitée des semaines.",
          DialogueId = 10032211,
          FacialId = {
            [1] = "100329:CM_Sad01"
          },
          FinalCamera = "208.112061,-522.162048,239.332031,7.201801,-13.600518,122.240273,45.0,284.991394,false,DoNotOverride,3.584893",
          GUID = "191D5574",
          NextDialogue = 10032212,
          SpeakNpcId = 100329,
          Subtitle = "Ever since that incident two years ago, tabloid hacks have been spreading rumours about the troupe, calling us a fraud. It was so bad that the director fell ill and couldn't get out of bed for weeks.",
          TalkActionId = {
            [1] = "100329:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100322/191D5574"
        },
        [10032212] = {
          Camera = "-110.570213,148.667206,110.816406,0.000218,-0.000676,-90.985168,35.000011,315.079285,false,Manual,3.120782",
          ContentFR = "En tout cas, ce tissu n’est pas à nous. Les registres des accessoires sont là-bas, vous pouvez les consulter si vous voulez. Moi, je dois retourner bosser.",
          DialogueId = 10032212,
          FacialId = {
            [1] = "100329:CM_Angry01"
          },
          FinalCamera = "-107.103416,148.607758,112.542969,0.000218,0.199332,-92.38517,35.000011,315.079285,false,Manual,3.120782",
          GUID = "191D559E",
          NextDialogue = 10032213,
          Scripts = "PlayAnimation{_delay{2},ActorId{100329},AnimationId{\"Disagree\"},Duration{2}}",
          SpeakNpcId = 100329,
          Subtitle = "Anyway, this fabric is definitely not ours. The props inventory is right over there — check it yourself if you don't believe me. Now, if you'll excuse me, I've got work to do.",
          TalkActionId = {
            [1] = "100329:Sigh_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100322/191D559E"
        },
        [10032213] = {
          Camera = "-1017.098938,642.821167,548.960938,0.000052,-21.599352,-39.762207,55.000011,1185.884644,false,Manual,1.2",
          ContentFR = "Hé, vous, les morveux ! Quand vous enlevez les perruques, vous les remettez sur les mannequins ! Revenez ici tout de suite ou je vous les couds directement sur le crâne !",
          DialogueId = 10032213,
          FinalCamera = "-1008.682922,652.714722,548.960938,0.000058,-21.199362,-42.361965,55.000011,1185.884644,false,Manual,1.2",
          GUID = "191D55C8",
          LookAt = {
            [1] = "100329:n(100329)"
          },
          Scripts = "MoveTo{_delay{3},ActorId{100329},TargetPoint{\"cp2fixsimple13Point01\"},MoveSpeed{80},Visibility{\"Show\"}}",
          SpeakNpcId = 100329,
          Subtitle = "Hey, you little punks! Put those wigs back on the mannequins when you're done! Get back here! I swear I'll sew those wigs onto your scalps!",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100329:p(90)"
          },
          VoiceName = "voice/$Locale$/story/1003/100322/191D55C8"
        },
        [10032214] = {
          ContentFR = "08 oct.\nPréparés : costumes et sacs de couchage.\nConfirmé par : Mondry\n(Note : Les réserves de nourriture s’épuisent. <H>Pour le mois intensif de répétitions à venir, il faudra demander une nouvelle livraison.</>)\n...\n12 nov.\nRemplacés : trois microphones.\nConfirmé par : Grinde\n(Note : L’un d’eux émet un son beaucoup trop fort, mais la directrice Putsch a insisté pour le garder tel quel.)\n14 nov.\nInstallé : rideau rouge. Le rideau doré a été renvoyé à l’entrepôt.\nConfirmé par : Bell\n...\n24 nov.\nRetrouvés : cinq perruques égarées.\nConfirmé par : Bell\n(Note : Les coins de la loge accumulent toutes sortes d’objets. Je vais tout vider aujourd’hui.)\n25 nov.\nPréparés : quinze couronnes de fleurs, neuf paires de bottes de cavalier.\nConfirmé par : Mondry",
          DialogueId = 10032214,
          DialoguePanelType = "{type:showtext;topic:READ_NAME_2000046;content:READ_TEXT_2000046}",
          GUID = "191D55F2",
          Subtitle = [[
8-Oct
Organized: Costumes and sleeping bags.
Logged by: Mondry
(Note: Food supplies are running low. We'll need to bring in another batch soon to prepare for the upcoming month-long intensive rehearsals.)
...
12-Nov
Replaced: Three new microphones.
Logged by: Grinde
(Note: One microphone produces an unusually loud sound, but Director Putsch insisted that it remain as is.)
14-Nov
Updated: Red curtain installed; gold curtain returned to storage.
Logged by: Bell
...
24-Nov
Retrieved: Five missing wigs.
Logged by: Bell
(Note: The dressing room corners are cluttered and seem to hide all sorts of things. I'll clean them out today.)
25-Nov
Organized: Fifteen flower crowns; nine pairs of riding boots.
Logged by: Mondry]],
          VoiceName = "voice/$Locale$/story/1003/100322/191D55F2"
        },
        [10032301] = {
          Camera = "27.207031,22.800903,135.363281,7.222204,-1.399963,-168.822205,30.000002,334.113678,false,DoNotOverride,2.014144",
          ContentFR = "Ta gorge est beaucoup trop tendue. Relâche-toi. Ouvre bien ta bouche, laisse ton souffle porter ta voix. Place le son plus en arrière... imagine que tu projettes ta voix jusqu’à un point au fond de ta nuque.",
          DialogueId = 10032301,
          FinalCamera = "27.207031,22.800903,135.363281,7.22229,-0.199885,-168.62204,30.000002,334.113678,false,DoNotOverride,2.014144",
          GUID = "191D6462",
          LookAt = {
            [1] = "100318:n(100319)"
          },
          NextDialogue = 10032302,
          Scripts = "SEQ{PlayAnimation{_delay{2},ActorId{100318},AnimationId{\"Explain01_Start\"},Duration{2}},CameraMoveTo{_delay{3},TargetPosition{\"-164.449219,9.727783,158.671875,7.202853,-7.800021,-13.643471,30.0,334.113678,false,Manual,2.014144\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-164.449219,9.727783,158.671875,7.203086,-6.799986,-12.844124,30.000002,334.113678,false,Manual,2.014144\"},duration{5}}}",
          SpeakNpcId = 100318,
          Subtitle = "Your throat is too tense. Relax. Let your mouth open fully, and let your breath carry your voice. Place the sound further back — imagine projecting it to a single point at the back of your head.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100323/191D6462"
        },
        [10032302] = {
          Camera = "87.0,17.469238,161.0,-10.803343,-34.997726,-25.183821,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Désolé, Madame Violetta... Je... je vais réessayer...",
          DialogueId = 10032302,
          FinalCamera = "86.523438,17.706665,161.0,-10.805331,-17.197323,-25.181259,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191D648C",
          LookAt = {
            [1] = "200021:n(100319)"
          },
          NextDialogue = 10032303,
          Scripts = "SEQ{CameraMoveTo{_delay{2},TargetPosition{\"292.714844,63.104004,116.441406,0.000027,2.999129,-155.242996,28.0,444.234283,false,Manual,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"289.470703,70.371338,116.441406,0.000027,2.999129,-152.843063,28.0,444.234283,false,Manual,1.2\"},duration{5}}}",
          SpeakNpcId = 100319,
          Subtitle = "Sorry, Ms Violetta. I—I'll try again...",
          TalkActionId = {
            [1] = "100318:Explain01_End",
            [2] = "100319:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D648C"
        },
        [10032303] = {
          Camera = "-27.283203,5.417847,146.285156,0.000012,-1.000759,-169.428741,30.0,507.051575,false,DoNotOverride,1.888818",
          ContentFR = "Après si longtemps en tournée, cet enfant n’a toujours pas fait de progrès... Tout le monde n’a pas la chance de naître avec une si belle voix, comme Parsifal.",
          DialogueId = 10032303,
          FinalCamera = "-28.900391,13.89624,146.285156,0.000012,-1.000759,-165.827866,30.0,507.051575,false,DoNotOverride,1.888818",
          GUID = "191D64B6",
          LookAt = {
            [1] = "200002:n(100318)",
            [2] = "100001:n(100318)"
          },
          NextDialogue = 10032304,
          RelatedWikiId = {
            [1] = 201023
          },
          Scripts = "SEQ{CameraMoveTo{_delay{8},TargetPosition{\"-135.996094,31.62146,154.839844,0.000098,-8.001225,-58.604973,30.000002,396.015259,false,Manual,3.782681\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-135.996094,31.62146,154.839844,0.000099,-6.401185,-57.404716,30.000002,396.015259,false,Manual,3.782681\"},duration{5}}}",
          SpeakNpcId = 100318,
          Subtitle = "Even after all this time on tour, this child still hasn't made much progress... I suppose not everyone can be like Parsifal, blessed with such a beautiful voice.",
          TalkActionId = {
            [1] = "100318:Disagree",
            [2] = "100319:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D64B6"
        },
        [10032304] = {
          Camera = "120.300781,-176.238037,135.574219,-0.000975,-18.79834,-114.166992,35.000015,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Hé, toi là ! T’as une drôle de tête... Tu caches quelque chose, avoue ! Le Grand Roi Démon doit t’interroger sur-le-champ !",
          DialogueId = 10032304,
          FacialId = {
            [1] = "200002:Shock01"
          },
          FinalCamera = "91.683594,-240.064636,111.714844,-0.000973,-18.79834,-114.167809,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191D64E0",
          LookAt = {
            [1] = "200002:n(100319)"
          },
          NextDialogue = 10032305,
          SpeakNpcId = 200002,
          Subtitle = "Hey, there! Your face looks so weird — are you hiding something? This Great Demon King demands a thorough interrogation!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 0.25,
          VoiceName = "voice/$Locale$/story/1003/100323/191D64E0"
        },
        [10032305] = {
          Camera = "-480.984375,-299.570007,14.378906,0.000082,7.997612,22.783634,30.0,507.051575,false,DoNotOverride,1.888818",
          ContentFR = "Allez courage... tu peux le faire... C’est le spectacle le plus important de l’année... On a répété si longtemps. Tout va bien se passer... ça doit aller...",
          DialogueId = 10032305,
          FinalCamera = "-446.701172,-285.171936,19.574219,0.000082,7.997612,22.783634,30.0,507.051575,false,DoNotOverride,1.888818",
          GUID = "191D650A",
          NextDialogue = 10032306,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"209.808594,-9.461182,148.214844,-0.001007,-3.399767,179.219086,23.11084,55.505848,false,Manual,3.597996\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"268.642578,-10.263184,151.722656,-0.000977,-3.39974,179.219086,50.0,110.476624,false,Manual,3.597996\"},duration{10}}}",
          SpeakNpcId = 100319,
          Subtitle = "Come on, you can do this... This is the most important performance of the year... We've rehearsed so many times... Everything's going to be fine... It has to be fine...",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100319:p(180)"
          },
          VoiceName = "voice/$Locale$/story/1003/100323/191D650A"
        },
        [10032306] = {
          Camera = "76.632812,-203.543945,113.671875,0.00036,-21.404112,-99.75795,35.000023,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Hééé, ne pars pas comme ça ! Le Roi Démon te parle !",
          DialogueId = 10032306,
          FinalCamera = "76.632812,-203.543945,113.671875,0.000355,-18.20401,-99.558105,35.000023,100000.0,false,DoNotOverride,22.0",
          GUID = "191D6534",
          NextDialogue = 10032307,
          SpeakNpcId = 200002,
          Subtitle = "Hey—! Stop! This Demon King is talking to you!",
          TalkActionId = {
            [1] = "200002:Angry01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100323/191D6534"
        },
        [10032307] = {
          Camera = "129.429688,47.965576,145.164062,0.000083,-2.200434,-81.589478,40.0,294.933868,false,Manual,5.052657",
          ContentFR = "Ça va ? Tu veux peut-être faire une pause ?",
          DialogueId = 10032307,
          FinalCamera = "126.857422,47.725708,145.164062,0.000083,-2.200434,-79.989059,40.0,294.933868,false,Manual,5.052657",
          GUID = "191D655E",
          LookAt = {
            [1] = "100001:n(100319)"
          },
          NextDialogue = 10032308,
          SpeakNpcId = 100001,
          Subtitle = "Are you alright? Do you need to take a break?",
          TalkActionId = {
            [1] = "200002:Angry01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D655E"
        },
        [10032308] = {
          Camera = "65.917969,43.683716,141.953125,0.000108,3.597747,-32.569561,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "N-Non... inutile... Je ne peux pas me permettre de retarder les répétitions...",
          DialogueId = 10032308,
          FinalCamera = "72.085938,53.345337,141.953125,0.000109,4.397719,-38.769005,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191D6588",
          NextDialogue = 10032309,
          SpeakNpcId = 100319,
          Subtitle = "No... No time to rest... I have to keep up with rehearsals...",
          TalkActionId = {
            [1] = "100319:Disagree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D6588"
        },
        [10032309] = {
          Camera = "169.253906,74.701294,123.164062,0.000129,2.59791,-117.5755,40.0,357.36673,false,Manual,3.974401",
          ContentFR = "Vraiment ? Parce que tu ressembles plutôt à quelqu’un qui sort tout droit d’un cercueil.",
          DialogueId = 10032309,
          FacialId = {
            [1] = "200021:Confident01"
          },
          FinalCamera = "166.167969,76.279785,123.164062,0.000129,2.59791,-116.375122,40.0,353.284943,false,Manual,3.974401",
          GUID = "191D65B2",
          LookAt = {
            [1] = "200021:n(100319)"
          },
          NextDialogue = 10032310,
          SpeakNpcId = 200021,
          Subtitle = "You sure? You look like someone who just crawled out of a coffin.",
          TalkActionId = {
            [1] = "200021:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D65B2"
        },
        [10032310] = {
          Camera = "12.228516,34.297607,98.183594,0.0001,13.597519,-19.587948,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Je... je vais très bien ! Tout le monde vit comme ça depuis plus d’un mois. Il faut que je continue... il faut que je tienne...",
          DialogueId = 10032310,
          FacialId = {
            [1] = "100319:CM_Angry01"
          },
          FinalCamera = "12.228516,34.297607,98.183594,0.000096,17.197609,-19.187962,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191D65DC",
          NextDialogue = 10032311,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"253.134766,37.984253,164.96875,7.209229,-12.99707,-154.195969,25.0,294.933868,false,Manual,5.052657\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"253.134766,37.984253,164.96875,7.209455,-9.196863,-154.196396,25.0,294.933868,false,Manual,5.052657\"},duration{5}}}",
          SpeakNpcId = 100319,
          Subtitle = "I...I'm just fine! Everyone's been living like this for over a month now. I just need to keep going... Keep going...",
          TalkActionId = {
            [1] = "200021:Talk02_End",
            [2] = "100319:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D65DC"
        },
        [10032311] = {
          Camera = "105.410156,-129.692505,108.539062,0.00026,12.795806,-78.157402,35.000023,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Alors, peux-tu me dire si il y a quelqu’un qui s’est permis de sécher les répétitions, ou qui sortirait en cachette la nuit ?",
          DialogueId = 10032311,
          FacialId = {
            [1] = "100001:Confident01",
            [2] = [[

100319:CM_Idle]]
          },
          FinalCamera = "110.507812,-128.654907,108.539062,0.000264,12.795792,-80.756798,35.000023,100000.0,false,DoNotOverride,22.0",
          GUID = "191D6606",
          NextDialogue = 10032312,
          SpeakNpcId = 100001,
          Subtitle = "Then, could you tell me if anyone has been skipping rehearsals or sneaking out at night?",
          TalkActionId = {
            [1] = "100001:Explain02_Start",
            [2] = "100319:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D6606"
        },
        [10032312] = {
          Camera = "60.613281,172.818604,110.851562,0.00027,3.197088,-73.568634,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Impossible... <H>Tout le monde est enfermé ici pour répéter, personne n’est sorti une seule fois.</> Si tu ne me crois pas, va voir le planning là-bas... On répète sans arrêt jusqu’à la fin de la Fête de la Chandelle d’Argent.",
          DialogueId = 10032312,
          FinalCamera = "74.958984,177.049438,110.851562,0.00027,3.197088,-76.368439,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191D6630",
          NextDialogue = 10032313,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"420.828125,629.299683,7.058594,0.000122,5.998579,-120.187637,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"447.3125,613.425903,7.058594,0.000123,5.998579,-123.187904,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100319,
          Subtitle = "No, no one would do that. Everyone's been locking themselves in here for the rehearsals, never stepping outside. If you don't believe me, check the schedule over there yourself... We'll be rehearsing nonstop until the Silvercandle Carnival ends.",
          TalkActionId = {
            [1] = "100001:Explain02_End",
            [2] = "100319:Disagree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D6630"
        },
        [10032313] = {
          Camera = "-19.873047,-192.083679,136.808594,0.000255,0.595859,-25.564138,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Au fait, l’Étranger, c’est quoi exactement cette Fête de la Chandelle d’Argent ?",
          DialogueId = 10032313,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "-56.113281,-174.762634,136.449219,0.000255,-0.204161,-25.363207,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191D665A",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10032314,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"49.513672,4.430176,117.238281,0.00011,7.797972,-110.591614,45.000027,392.267242,false,DoNotOverride,5.540613\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"38.136719,8.624023,117.238281,0.000109,7.797972,-108.39164,45.000027,392.267242,false,DoNotOverride,5.540613\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "Outsider, what exactly is the Silvercandle Carnival?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D665A"
        },
        [10032314] = {
          Camera = "-320.859375,1100.031616,28.5,-0.000032,9.262918,-73.549782,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "C’est une fête où les gens enfilent des masques, se déguisent de façon extravagante, et laissent de côté leur identité et leur race. Tous se rassemblent au théâtre pour assister aux spectacles et danser jusqu’au matin.",
          DialogueId = 10032314,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "-320.859375,1100.031616,28.5,-0.000031,5.462908,-73.948982,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191D6684",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10032315,
          Scripts = "PlayAnimation{_delay{8},ActorId{200021},AnimationId{\"Talk01_End\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "It's a festival where people put on masks, dress in bizarre costumes, and set aside their identities and races. Everyone gathers at the theatre to watch performances and dance through the night.",
          TalkActionId = {
            [1] = "200021:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D6684"
        },
        [10032315] = {
          Camera = "17.898438,-172.325745,200.007812,0.002227,-29.792526,-136.767868,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Cette nuit-là, peu importe que tu sois Sola ou Charon derrière ton masque. Ce qui compte, c’est de chanter, danser, crier ensemble.",
          DialogueId = 10032315,
          FinalCamera = "20.896484,-175.429382,200.007812,0.002231,-29.79254,-140.567673,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "191D66AE",
          NextDialogue = 10032316,
          SpeakNpcId = 200021,
          Subtitle = "For one night, no one cares if you're a Sola or a Charon. All that matters is singing, dancing, and letting loose together.",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D66AE"
        },
        [10032316] = {
          Camera = "76.511719,-140.939392,119.402344,-0.00003,11.462054,-69.546867,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "C’est difficile d’imaginer une fête pareille à Givrelac... Les gens d’ici ont l’air si... sérieux.",
          DialogueId = 10032316,
          FinalCamera = "76.511719,-140.939392,119.402344,-0.000031,9.461997,-66.347099,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191D66D8",
          NextDialogue = 10032317,
          SpeakNpcId = 100001,
          Subtitle = "It's hard to imagine a festival like that in a place like Icelake. People here seem... pretty uptight.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D66D8"
        },
        [10032317] = {
          Camera = "160.525391,-52.564697,106.691406,0.00035,9.3942,-138.753281,45.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Haha, justement. Plus on se retient au quotidien, plus on a besoin de tout lâcher et de hurler à plein poumons, de temps en temps.",
          DialogueId = 10032317,
          FinalCamera = "152.615234,-43.393677,106.691406,0.000343,9.3942,-136.353165,45.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191D6702",
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"4283.351562,3130.114258,1144.804688,0.000308,-11.204836,-141.568665,55.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"4543.302734,3336.384766,1210.519531,0.000308,-11.204836,-141.568665,55.0,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 200021,
          Subtitle = "Haha, well, the more tightly people are wound in their daily lives, the more they wish to scream and let it all out once in a while.",
          TalkActionId = {
            [1] = "200021:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100323/191D6702"
        },
        [10032318] = {
          ContentFR = "Un registre épais où chaque membre du personnel voit son emploi du temps consigné dans le moindre détail : répétitions, repas, sommeil, même les passages aux toilettes.\nOn ignore si la directrice du théâtre a véritablement \"enfermé\" ses comédiens avec une sévérité impitoyable, ou si elle n’a fait que les surveiller de près pour mieux les protéger.",
          DialogueId = 10032318,
          GUID = "191D672C",
          Subtitle = [[
A thick attendance log that meticulously records every staff member's daily schedule, tracking everything from rehearsals to meals, sleeping hours, and even bathroom breaks.
It's hard to tell whether the director is ruthlessly "imprisoning" everyone in the theatre or simply keeping a vigilant watch to protect her performers.]],
          VoiceName = "voice/$Locale$/story/1003/100323/191D672C"
        },
        [10032401] = {
          Camera = "-1135.283203,2455.108398,-2052.257812,7.20768,17.796782,-75.54464,20.086287,100000.0,false,Manual,22.0",
          ContentFR = "Ouah, ce micro est vachement puissant !",
          DialogueId = 10032401,
          FinalCamera = "-1135.283203,2455.108398,-2052.257812,7.207845,20.796669,-75.344231,20.086287,100000.0,false,Manual,22.0",
          GUID = "191D74CA",
          LookAt = {
            [1] = "200021:n(100313)",
            [2] = "100001:n(100313)",
            [3] = "200002:n(100313)"
          },
          NextDialogue = 10032402,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/02/micfeedback\"},PlayAs2D{true}}",
          SpeakNpcId = 200002,
          Subtitle = "Whoa, that microphone's so loud!",
          TalkActionId = {
            [1] = "200002:Shock_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100324/191D74CA"
        },
        [10032402] = {
          Camera = "-249.160156,195.398193,-1041.367188,0.000288,32.664738,-72.531853,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "Tout le monde en place ! La troisième répétition commence maintenant !",
          DialogueId = 10032402,
          FinalCamera = "-241.269531,170.382812,-1024.136719,0.000283,34.264702,-72.131714,35.000011,100000.0,false,Manual,22.0",
          GUID = "191D74F4",
          NextDialogue = 10032403,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-100.162109,-93.307861,-857.605469,-0.005187,-23.177856,117.845169,30.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-87.929688,-85.529785,-857.605469,-0.005188,-23.177856,121.845268,30.0,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100313,
          Subtitle = "Everyone, take your positions! The third rehearsal starts now!",
          TalkActionId = {
            [1] = "100313:Confident_Start",
            [2] = "200002:Shock_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100324/191D74F4"
        },
        [10032403] = {
          Camera = "-1084.892578,2085.785645,-1882.074219,-0.000794,-20.80938,110.409325,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "J’ai jeté un œil au registre, ça confirme que personne n’a quitté le théâtre depuis plus d’un mois. Même les ours en hibernation sortent plus souvent qu’eux.",
          DialogueId = 10032403,
          FinalCamera = "-1096.111328,2081.808105,-1882.074219,-0.000793,-20.80938,105.409744,35.000008,100000.0,false,Manual,22.0",
          GUID = "191D751E",
          NextDialogue = 10032404,
          SpeakNpcId = 200021,
          Subtitle = "I checked the attendance log — it shows nobody has left the theatre at all for over a month. Even hibernating bears get out more often than this.",
          TalkActionId = {
            [1] = "200021:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100324/191D751E"
        },
        [10032404] = {
          Camera = "-1271.912109,1894.476685,-1985.0,-0.000732,2.793752,62.786755,35.000023,100000.0,false,Manual,22.0",
          ContentFR = "Oui... avec des répétitions aussi intensives, personne n’aurait pu s’éclipser pour attaquer. Allons voir si Rhythm a découvert quelque chose de son côté.",
          DialogueId = 10032404,
          FinalCamera = "-1271.912109,1894.476685,-1994.0,-0.000732,2.793752,62.786755,35.000023,100000.0,false,Manual,22.0",
          GUID = "191D7548",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          Scripts = "PARA{PlayAnimation{_delay{4},ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{2}},SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-1086.335938,2159.28418,-1904.109375,-0.000733,-25.205978,47.585659,35.000023,100000.0,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-1082.457031,2155.790283,-1904.109375,-0.000734,-25.205986,50.185623,35.000023,100000.0,false,Manual,22.0\"},duration{5}}}}",
          SpeakNpcId = 100001,
          Subtitle = "With such intensive rehearsals, no one would've had the chance to sneak out and orchestrate a \"hunt\"... Let's go see if Rhythm has found anything.",
          TalkActionId = {
            [1] = "200021:Think_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100324/191D7548"
        },
        [10032501] = {
          Camera = "11.992188,-453.371582,208.899658,0.000117,-14.399677,82.172852,35.000019,100000.0,false,Manual,22.0",
          ContentFR = "Déjà de retour ? Vous êtes bien plus rapides que la plupart des soldats.",
          DialogueId = 10032501,
          FacialId = {
            [1] = "100304:Smile01"
          },
          FinalCamera = "21.268555,-454.01416,208.899658,0.000116,-14.399677,83.372566,35.000019,100000.0,false,Manual,22.0",
          GUID = "191D8532",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "100001:n(100304)",
            [3] = "200002:n(100304)"
          },
          NextOptions = {
            [1] = 10032502,
            [2] = 10032504
          },
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405005,
            [3] = 201011
          },
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"81.686646,-4.163086,116.147217,0.000112,3.399938,88.778122,35.000019,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"81.44812,-15.35498,115.483398,0.000112,3.399938,88.778122,35.000019,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100304,
          Subtitle = "That was quick. Faster than most soldiers I've worked with.",
          TalkActionId = {
            [1] = "100304:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D8532"
        },
        [10032502] = {
          ContentFR = "<I>Évidemment. Je suis {性别:le meilleur|la meilleure}.</>",
          DialogueId = 10032502,
          GUID = "191D855C",
          ImprPlusId = 1010,
          NextDialogue = 10032503,
          Subtitle = "Of course. I'm a genius."
        },
        [10032503] = {
          Camera = "118.575439,1.040527,107.395508,0.000438,5.801542,-99.6222,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Dommage que le théâtre n’ait rien révélé d’utile. Et de votre côté, à la zone industrielle ?",
          DialogueId = 10032503,
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "128.399414,-0.741699,107.395508,0.000438,5.801542,-103.222313,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191D855D",
          NextDialogue = 10032505,
          Scripts = "PlayAnimation{_delay{5.5},ActorId{100304},AnimationId{\"Give\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "Too bad we didn't find anything useful in the theatre. What about things on your side?",
          TalkActionId = {
            [1] = "100001:DisagreeHead",
            [2] = "100304:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D855D"
        },
        [10032504] = {
          ContentFR = "<I>On n’a pas trouvé grand-chose au théâtre, donc l’enquête a été vite bouclée.</>",
          DialogueId = 10032504,
          GUID = "191D8586",
          ImprPlusId = 1007,
          NextDialogue = 10032505,
          Subtitle = "There wasn't much to find in the theatre, so it didn't take long."
        },
        [10032505] = {
          Camera = "139.100586,559.121094,255.143799,0.000448,-14.799346,-99.026108,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "De mon côté, les ouvriers sont hors de cause. Mais j’ai trouvé ça dans une fabrique de machines.",
          DialogueId = 10032505,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_MoonWater.T_Guide_Chapter_MoonWater'}",
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "155.200317,556.564453,255.143799,0.000448,-14.799332,-97.826088,35.000011,100000.0,false,Manual,22.0",
          GUID = "191D85B0",
          NextDialogue = 10032506,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"120.424194,-52.796387,101.331787,0.000415,5.801644,101.378357,35.000008,100000.0,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"128.880249,-51.19043,101.331787,0.000425,5.801644,104.779152,35.000008,100000.0,false,Manual,22.0\"},duration{5}}},PlayAnimation{_delay{5.5},ActorId{100304},AnimationId{\"Give\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "The workers at the factory area are all cleared of suspicion. But I did find this at a motor plant.",
          TalkActionId = {
            [1] = "100304:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D85B0"
        },
        [10032506] = {
          Camera = "52.115723,170.890625,134.337646,0.000045,-14.206348,-69.411613,45.0,295.914764,false,Manual,6.899518",
          ContentFR = "Mais... c’est du Phoxichor, non ?",
          DialogueId = 10032506,
          FacialId = {
            [1] = "200002:Confident02"
          },
          FinalCamera = "49.032349,169.800781,134.337646,0.000047,-14.206348,-68.211639,45.0,295.914764,false,Manual,6.899518",
          GUID = "191D85DA",
          LookAt = {
            [1] = "100304:n(200002)",
            [2] = "200002:n(100304)"
          },
          NextDialogue = 10032507,
          SpeakNpcId = 200002,
          Subtitle = "Isn't that Phoxichor?",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D85DA"
        },
        [10032507] = {
          Camera = "103.700073,-16.408691,103.009521,0.000502,8.39629,95.988274,35.000015,149.275681,false,Manual,22.0",
          ContentFR = "Non. Sentez un peu.",
          DialogueId = 10032507,
          GUID = "191D8604",
          NextDialogue = 10032508,
          SpeakNpcId = 100304,
          Subtitle = "Take a sniff.",
          TalkActionId = {
            [1] = "100304:Talk03_Start",
            [2] = "200002:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100325/191D8604"
        },
        [10032508] = {
          Camera = "83.609619,-27.326172,111.722656,0.000411,-23.398956,-52.766521,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Beurk ! Quelle odeur de poisson... Ça sent... l’Épinegivre ! Les Asphodèles en ont reçu une cargaison récemment, j’ai passé des heures à les vider et à les nettoyer !",
          DialogueId = 10032508,
          FacialId = {
            [1] = "200002:Shock01"
          },
          FinalCamera = "80.201172,-29.955078,111.722656,0.000412,-23.398956,-51.566967,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191D862E",
          LookAt = {
            [1] = "200021:n(200002)"
          },
          NextDialogue = 10032509,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{3},TargetPosition{\"39.420166,207.152344,135.722656,0.000417,-9.398347,-71.963043,35.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"39.420166,207.152344,135.722656,0.000418,-7.398317,-71.962883,35.0,100000.0,false,DoNotOverride,22.0\"},duration{8}}},PlayAnimation{_delay{4},ActorId{200002},AnimationId{\"Shock_End\"},Duration{2}}}",
          SpeakNpcId = 200002,
          Subtitle = "Eww... so fishy! It smells like... Frostspines! The Asphodel just had a batch delivered a couple of days ago. I spent hours gutting and cleaning them!",
          TalkActionId = {
            [1] = "200002:Shock_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D862E"
        },
        [10032509] = {
          Camera = "126.557007,23.318359,114.344238,0.00044,4.800209,-130.965836,30.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Tiens donc... Petit Champi, tu ferais sûrement une super ballerine. Fallait te mettre en scène au théâtre !",
          DialogueId = 10032509,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "131.013794,19.098633,114.344238,0.000441,4.800209,-132.566101,30.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191D8658",
          LookAt = {
            [1] = "200002:n(200021)"
          },
          NextDialogue = 10032510,
          SpeakNpcId = 200021,
          Subtitle = "Huh, Button Mushroom, you must be a great ballerina! We should've had you perform back at the theatre.",
          TalkActionId = {
            [1] = "200021:ConfidentLR_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D8658"
        },
        [10032510] = {
          Camera = "-38.285278,-94.880859,166.193604,0.000415,-29.598597,-7.961472,30.000013,100000.0,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Ballerine ? Mais j’y connais rien ! Pourquoi tu dis ça ?",
          DialogueId = 10032510,
          FacialId = {
            [1] = "200002:Happy01"
          },
          FinalCamera = "-37.809326,-91.476074,166.193604,0.000415,-29.598597,-9.561579,30.000013,100000.0,false,DoNotOverride,22.0",
          GUID = "191D8682",
          NextDialogue = 10032511,
          SpeakNpcId = 200002,
          Subtitle = "Ballerina? I don't know ballet... Why?",
          TalkActionId = {
            [1] = "200002:Confident_Start",
            [2] = "200021:ConfidentLR_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D8682"
        },
        [10032511] = {
          Camera = "260.250977,-33.956055,52.295166,0.000392,13.198178,-153.158432,30.000002,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Dommage. Je pensais qu’à force de te tenir sur la pointe des pieds pour servir les tables aux Asphodèles, tu avais déjà les bases parfaites.",
          DialogueId = 10032511,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "261.581543,-36.869141,52.295166,0.000392,13.198186,-154.158371,30.000002,100000.0,false,DoNotOverride,22.0",
          GUID = "191D86AC",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextDialogue = 10032512,
          Scripts = "PlayAnimation{_delay{5},ActorId{200021},AnimationId{\"Talk01_End\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Well, with all the time you spend on your toes bussing tables at The Asphodel, you've got the perfect foundation. Such a waste!",
          TalkActionId = {
            [1] = "200021:Talk01_Start",
            [2] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D86AC"
        },
        [10032512] = {
          Camera = "34.129639,-43.955566,119.972656,0.000447,-25.599173,-26.162193,30.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Nan ! Pas besoin, je monte juste sur une caisse... Attends... Hé ! C’est méchant !",
          DialogueId = 10032512,
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          FinalCamera = "32.1073,-47.393066,119.972656,0.000446,-25.599178,-24.760878,30.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191D86D6",
          LookAt = {
            [1] = "100001:n(100304)"
          },
          NextDialogue = 10032513,
          Scripts = "PlayAnimation{_delay{3},ActorId{200002},AnimationId{\"Angry01_End\"},Duration{2}}",
          SpeakNpcId = 200002,
          Subtitle = "Nah, I always stand on a crate— Wait... hey! That's mean!",
          TalkActionId = {
            [1] = "200021:Talk01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100325/191D86D6"
        },
        [10032513] = {
          Camera = "82.171143,-65.495605,193.210693,0.000503,-28.600132,-144.951599,40.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "D’accord d’accord, j’arrête. Mais alors, Officier, qu’en pensez-vous ? Les ouvriers ont trempé les Épinegivres dans du Phoxichor ?",
          DialogueId = 10032513,
          FacialId = {
            [1] = "200021:None"
          },
          FinalCamera = "83.917847,-68.359375,193.210693,0.000498,-28.600119,-147.551743,40.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191D8700",
          LookAt = {
            [1] = "100304:n(200021)",
            [2] = "200002:n(200002)"
          },
          NextDialogue = 10032514,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{4},TargetPosition{\"139.094971,188.817871,126.572998,0.000448,-0.80002,-121.158913,40.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"142.020386,187.085938,126.572998,0.000448,-0.80002,-122.359116,40.000011,100000.0,false,DoNotOverride,22.0\"},duration{5}}},PlayAnimation{_delay{5},ActorId{200021},AnimationId{\"Talk01_Start\"}},LookAt{_delay{2},LookAtDescription{\"200021:n(100304)\"}}}",
          SpeakNpcId = 200021,
          Subtitle = "*chuckles* Alright, alright, no more messing around. So, Officer, what's your take? Do you think the workers soaked Frostspines in Phoxichor?",
          TalkActionId = {
            [1] = "200002:Angry01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D8700"
        },
        [10032514] = {
          Camera = "-1.008301,-498.653809,218.979004,0.000549,-14.798089,81.42189,40.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Non, regardez bien, ce n’est pas du Phoxichor, mais de <H>l’huile d’Épinegivre</>. Elles ont juste la même couleur.",
          DialogueId = 10032514,
          FinalCamera = "-1.008301,-498.653809,218.979004,0.000546,-13.998042,81.221817,40.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191D872A",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10032515,
          Scripts = "SEQ{CameraMoveTo{_delay{4},TargetPosition{\"31.134766,-31.19043,186.413574,0.000501,-21.798998,70.431305,40.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"38.342407,-33.75293,186.413574,0.000518,-21.798998,72.630898,40.0,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100304,
          Subtitle = "No, look closer. This isn't Phoxichor — it's Frostspine fish oil. They just happen to look similar in colour.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D872A"
        },
        [10032515] = {
          Camera = "76.022827,74.375488,162.032227,0.000882,-32.598751,79.993546,40.000023,100000.0,false,DoNotOverride,22.0",
          ContentFR = "J’ai interrogé les ouvriers, la nuit du crime, il y a cinq jours, aucun n’a entendu quoi que ce soit. Avec seulement quatre heures de sommeil par jour, ils étaient plongés dans un sommeil de plomb.",
          DialogueId = 10032515,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "70.541504,75.342773,162.032227,0.000874,-32.598743,75.193024,40.000023,100000.0,false,DoNotOverride,22.0",
          GUID = "191D8754",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10032516,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{4},TargetPosition{\"-18.515747,-444.968262,82.468506,0.001037,4.201358,77.162735,40.000031,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-11.348267,-446.600586,82.468506,0.001038,4.201358,77.962593,40.000031,100000.0,false,DoNotOverride,22.0\"},duration{5}}},PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Talk03_End\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "I questioned the workers. On the night of the incident five days ago, none of them heard anything unusual. They were so overworked that they barely got four hours of sleep and were completely out cold.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D8754"
        },
        [10032516] = {
          Camera = "0.012451,143.523926,125.083984,0.000653,1.200392,-16.001678,40.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "En revanche, il y a bien eu quelque chose d’étrange, le lendemain matin, certains ont découvert dans l’usine un <H>harpon</> portant l’inscription « Association des pêcheurs de Givrelac ». Personne ne sait comment il est arrivé là.",
          DialogueId = 10032516,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "1.198853,147.661133,125.083984,0.000653,1.200392,-16.001678,40.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191D877E",
          LookAt = {
            [1] = "200002:n(100304)"
          },
          NextDialogue = 10032517,
          RelatedWikiId = {
            [1] = 406003
          },
          Scripts = "SEQ{CameraMoveTo{_delay{4},TargetPosition{\"-66.778442,-679.911621,382.91748,0.000637,-23.599512,77.208534,40.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-90.513062,-673.508789,382.91748,0.000638,-23.599504,74.607948,40.0,100000.0,false,DoNotOverride,22.0\"},duration{8}}}",
          SpeakNpcId = 100304,
          Subtitle = "However, something odd did happen. The next morning, a few workers found a harpoon in the plant. No one knew how it got there, but it was inscribed with the words \"Property of The Fisheries.\"",
          TalkActionId = {
            [1] = "100304:Think_Start",
            [2] = "200021:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D877E"
        },
        [10032517] = {
          Camera = "29.666016,-119.382324,101.084961,0.000634,3.200497,77.202171,40.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Et dans l’entrepôt où ils stockent le Phoxichor, j’ai trouvé deux bonbonnes d’huile d’Épinegivre rangées dans des conteneurs de Phoxichor. Comme les deux liquides sont bleu pâle, les ouvriers ne se sont rendu compte de rien.",
          DialogueId = 10032517,
          FinalCamera = "22.327759,-117.646973,101.084961,0.000634,3.200497,75.601952,40.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191D87A8",
          NextDialogue = 10032518,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{4},TargetPosition{\"33.071289,363.424805,252.911621,0.000645,-24.199612,-83.987556,30.0,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"33.071289,363.424805,252.911621,0.00065,-20.399471,-83.987297,30.0,100000.0,false,DoNotOverride,22.0\"},duration{8}}},PlayAnimation{_delay{6},ActorId{100304},AnimationId{\"Talk03_Start\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "I also found two canisters of fish oil stored in Phoxichor containers in their warehouse. The workers didn't notice anything off because both liquids are pale blue...",
          TalkActionId = {
            [1] = "100304:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200002:n(100304)"
          },
          VoiceName = "voice/$Locale$/story/1003/100325/191D87A8"
        },
        [10032518] = {
          Camera = "22.444702,246.847168,138.516602,0.000591,-6.399757,-72.792931,40.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Donc... le soir du crime, quelqu’un a pris deux conteneurs de Phoxichor et les a remplacés par deux d’huile de poisson ?",
          DialogueId = 10032518,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "16.506226,245.166016,138.516602,0.000589,-6.399757,-69.792786,40.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191D87D2",
          LookAt = {
            [1] = "100304:n(100001)",
            [2] = "200021:n(100001)",
            [3] = "200002:n(100304)"
          },
          NextDialogue = 10032519,
          Scripts = "SEQ{CameraMoveTo{_delay{4},TargetPosition{\"57.131958,-6.844727,79.989014,0.000618,16.39875,-75.169418,40.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"62.431885,-5.442383,79.989014,0.000619,16.39871,-77.368843,40.000011,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "Are you saying that on the night of the incident, someone swapped two canisters of Phoxichor with fish oil?",
          TalkActionId = {
            [1] = "100001:Explain02_Start",
            [2] = "100304:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D87D2"
        },
        [10032519] = {
          Camera = "69.809082,-244.192383,136.203857,0.000569,-3.200435,81.807693,45.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Exactement. Et avec les indices que nous avons rassemblés... le suspect le plus probable est—",
          DialogueId = 10032519,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "64.114136,-243.390137,136.203857,0.000568,-3.200435,81.207619,45.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191D87FC",
          NextOptions = {
            [1] = 10032520,
            [2] = 10032524,
            [3] = 10032526,
            [4] = 10032528
          },
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"90.963501,79.835938,123.744385,0.000576,0.599936,91.399673,45.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"86.686279,79.730957,123.744385,0.000576,0.599936,91.399673,45.000011,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100304,
          Subtitle = "Exactly. And based on the clues we've gathered so far, the suspect is most likely to be—",
          TalkActionId = {
            [1] = "100304:AgreeHead",
            [2] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D87FC"
        },
        [10032520] = {
          ContentFR = "<I>Un comédien.</>",
          DialogueId = 10032520,
          GUID = "191D8826",
          ImprPlusId = 1016,
          NextDialogue = 10032521,
          Subtitle = "A performer."
        },
        [10032521] = {
          Camera = "229.553223,-24.303223,112.156982,0.000577,5.999119,-157.593369,45.000023,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Tu viens pas de les innocenter, justement ?",
          DialogueId = 10032521,
          FacialId = {
            [1] = "200021:Think01"
          },
          FinalCamera = "226.745605,-17.493164,112.156982,0.000578,5.999119,-156.193588,45.000023,100000.0,false,DoNotOverride,22.0",
          GUID = "191D8850",
          NextDialogue = 10032522,
          SpeakNpcId = 200021,
          Subtitle = "Didn't you just rule them out yourself?",
          TalkActionId = {
            [1] = "200021:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D8850"
        },
        [10032522] = {
          Camera = "-69.483032,35.310059,94.026611,0.000575,5.998443,-55.788017,45.000023,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Ah ? Oh, je plaisantais, haha !",
          DialogueId = 10032522,
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "-65.130127,38.267578,94.026611,0.000574,5.998443,-57.587849,45.000023,100000.0,false,DoNotOverride,22.0",
          GUID = "191D887A",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10032523,
          SpeakNpcId = 100001,
          Subtitle = "Oh, I was just kidding, haha!",
          TalkActionId = {
            [1] = "100001:ScratchHead_Start",
            [2] = "200021:Sigh_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D887A"
        },
        [10032523] = {
          Camera = "-35.920166,-562.795898,68.926025,0.000548,4.198333,77.592812,45.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "En tenant compte du harpon et de l’huile, j’estime que le suspect est plutôt un pêcheur.",
          DialogueId = 10032523,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "-28.810059,-564.327148,68.926025,0.000549,4.198333,78.392654,45.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191D88A4",
          LookAt = {
            [1] = "100001:n(100304)",
            [2] = "200021:n(100304)"
          },
          NextDialogue = 10032531,
          Scripts = "PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Think_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "Hmm... Considering the harpoon and the fish oil, I think the suspect is most likely to be a fisherman.",
          TalkActionId = {
            [1] = "100304:Think_Start",
            [2] = "100001:ScratchHead_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100325/191D88A4"
        },
        [10032524] = {
          ContentFR = "<I>Un ouvrier.</>",
          DialogueId = 10032524,
          GUID = "191D88CE",
          ImprPlusId = 1016,
          NextDialogue = 10032525,
          Subtitle = "A worker."
        },
        [10032525] = {
          Camera = "-52.859375,-596.512695,69.789795,0.000565,3.798207,76.587906,45.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Je les ai déjà blanchis, tous avaient un alibi solide. Avec le harpon et l’huile, le suspect le plus probable reste un pêcheur.",
          DialogueId = 10032525,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "-43.747559,-598.684082,69.789795,0.000566,3.798207,77.987732,45.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191D88F8",
          LookAt = {
            [1] = "200021:n(100304)"
          },
