          SpeakNpcId = 100320,
          SpeakNpcName = "Cp2CharacterName29",
          Subtitle = "Meow— Meow!",
          VoiceName = "voice/$Locale$/story/1003/100326/191D95C4"
        },
        [10032603] = {
          ContentFR = "Miaou... miaou ?",
          DialogueId = 10032603,
          GUID = "191D95EE",
          NextDialogue = 10032604,
          SpeakNpcId = 100320,
          SpeakNpcName = "Cp2CharacterName29",
          Subtitle = "Meow... Meow?",
          VoiceName = "voice/$Locale$/story/1003/100326/191D95EE"
        },
        [10032604] = {
          ContentFR = "<I>Ce chat fixe Rhythm depuis un moment... Il aurait senti quelque chose d’inhabituel ?</>",
          DialogueId = 10032604,
          DisableMouth = 1,
          GUID = "191D9618",
          NextDialogue = 10032605,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(This cat keeps staring at Rhythm... Could it have picked up on some strange scent?)",
          VoiceName = "voice/$Locale$/story/1003/100326/191D9618"
        },
        [10032605] = {
          ContentFR = "Officier Fischer, puis-je emprunter ce flacon d’huile de poisson un instant ?",
          DialogueId = 10032605,
          GUID = "191D9642",
          NextDialogue = 10032606,
          SpeakNpcId = 100001,
          Subtitle = "Officer Fischer, could I borrow that fish oil for a second?",
          VoiceName = "voice/$Locale$/story/1003/100326/191D9642"
        },
        [10032606] = {
          ContentFR = "Tiens. Vous avez découvert quelque chose ?",
          DialogueId = 10032606,
          GUID = "191D966C",
          NextDialogue = 10032607,
          SpeakNpcId = 100304,
          Subtitle = "Here. Did you notice something?",
          VoiceName = "voice/$Locale$/story/1003/100326/191D966C"
        },
        [10032607] = {
          ContentFR = "Oui, je veux juste vérifier une hypothèse.",
          DialogueId = 10032607,
          GUID = "191D9696",
          NextDialogue = 10032608,
          SpeakNpcId = 100001,
          Subtitle = "Yeah. I've got a theory I want to test.",
          VoiceName = "voice/$Locale$/story/1003/100326/191D9696"
        },
        [10032608] = {
          ContentFR = "Miaou— miaou miaou !",
          DialogueId = 10032608,
          GUID = "191D96C0",
          SpeakNpcId = 100320,
          SpeakNpcName = "Cp2CharacterName29",
          Subtitle = "Meow— Meowww!",
          VoiceName = "voice/$Locale$/story/1003/100326/191D96C0"
        },
        [10032609] = {
          ContentFR = "Suivons ce chat, il semble vouloir nous montrer quelque chose.",
          DialogueId = 10032609,
          GUID = "191D96EA",
          NextDialogue = 10032610,
          SpeakNpcId = 100001,
          Subtitle = "Let's follow that cat — I think it's trying to lead us somewhere.",
          VoiceName = "voice/$Locale$/story/1003/100326/191D96EA"
        },
        [10032610] = {
          ContentFR = "Vraiment perspicace... pas étonnant pour quelqu’un ayant été {性别:dresseur d’animaux|dresseuse d’animaux}.",
          DialogueId = 10032610,
          GUID = "191D96EB",
          NextDialogue = 10032611,
          SpeakNpcId = 100304,
          Subtitle = "Sharp instincts. True to your roots as an animal trainer.",
          VoiceName = "voice/$Locale$/story/1003/100326/191D96EB"
        },
        [10032611] = {
          ContentFR = "<I>... Merci, l’Étranger.</>",
          DialogueId = 10032611,
          DisableMouth = 1,
          GUID = "191D96EC",
          NextDialogue = 10032612,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...Thanks for that, Outsider.)",
          VoiceName = "voice/$Locale$/story/1003/100326/191D96EC"
        },
        [10032612] = {
          ContentFR = "Miaou— miaou miaou miaou !",
          DialogueId = 10032612,
          GUID = "191D9714",
          SpeakNpcId = 100320,
          SpeakNpcName = "Cp2CharacterName29",
