        [10032613] = {
          ContentFR = "Le chat a disparu au loin.",
          DialogueId = 10032613,
          GUID = "191D973E",
          Subtitle = "The cat disappeared into the distance.",
          VoiceName = "voice/$Locale$/story/1003/100326/191D973E"
        },
        [10032614] = {
          ContentFR = "Toi, le méchant qui a blessé mon petit larbin ! Tu pensais vraiment pouvoir te cacher ? La Justice est là !",
          DialogueId = 10032614,
          GUID = "191D9768",
          NextDialogue = 10032615,
          SpeakNpcId = 200002,
          Subtitle = "Aha! You scoundrel! How dare you hurt my Little Minion and then think you can hide! Justice has arrived!",
          VoiceName = "voice/$Locale$/story/1003/100326/191D9768"
        },
        [10032615] = {
          ContentFR = "Hein ? Les Veilleurs ? Non... non me frappez pas ! Je... je vais parler !",
          DialogueId = 10032615,
          GUID = "191D9792",
          SpeakNpcId = 100314,
          Subtitle = "Huh? The Escort? Please, don't hurt me! I'll talk! I'll tell you everything!",
