          GUID = "191E0B3C",
          SpeakNpcId = 100304,
          Subtitle = "Darn it... I'm tied up!",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0B3C"
        },
        [10033319] = {
          ContentFR = "Dé... truire...",
          DialogueId = 10033319,
          GUID = "191E0B66",
          NextDialogue = 10033320,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName01",
          Subtitle = "DESTRRRROY...",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0B66"
        },
        [10033320] = {
          ContentFR = "Je couvre la retraite des blessés ! Ne paniquez pas !",
          DialogueId = 10033320,
          GUID = "191E0B90",
          NextDialogue = 10033321,
          SpeakNpcId = 100001,
          Subtitle = "I'll cover the retreat of the wounded. Stay focused — don't lose your nerve!",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0B90"
        },
        [10033321] = {
          ContentFR = "Je compte sur vous.",
          DialogueId = 10033321,
          GUID = "191E0BBA",
          NextDialogue = 10033322,
          SpeakNpcId = 100304,
          Subtitle = "Be careful.",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0BBA"
        },
        [10033322] = {
          ContentFR = "<I>Kof... </>Merci...",
          DialogueId = 10033322,
          GUID = "191E0BE4",
          SpeakNpcId = 100344,
          Subtitle = "*coughs* ...Thank you.",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0BE4"
        },
        [10033323] = {
          ContentFR = "L’Étranger, il y a une ouverture sur sa gauche !",
          DialogueId = 10033323,
          GUID = "191E0C0E",
          NextDialogue = 10033324,
          SpeakNpcId = 100001,
          Subtitle = "Outsider, there's an opening on its left!",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0C0E"
        },
        [10033324] = {
          ContentFR = "Je m’en occupe.",
          DialogueId = 10033324,
          GUID = "191E0C38",
          SpeakNpcId = 200021,
          Subtitle = "I'm on it.",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0C38"
        },
        [10033325] = {
          ContentFR = "On l’a ! Rhythm, maintenant !",
          DialogueId = 10033325,
          GUID = "191E0C62",
          SpeakNpcId = 200021,
          Subtitle = "We've got it pinned! Rhythm, now!",
          VoiceName = "voice/$Locale$/story/1003/100333/191E0C62"
        },
        [10033401] = {
          ContentFR = "Re... Retraite...",
          DialogueId = 10033401,
          GUID = "191E18DA",
          SpeakNpcId = 100311,
          Subtitle = "Re...Retreat...",
          VoiceName = "voice/$Locale$/story/1003/100334/191E18DA"
        },
        [10033402] = {
          ContentFR = "... Ce monstre... n’est pas seul... Il y en a un autre... !",
          DialogueId = 10033402,
          GUID = "191E1904",
          SpeakNpcId = 100311,
          Subtitle = "There's... more than... one monster...!",
          VoiceName = "voice/$Locale$/story/1003/100334/191E1904"
        },
        [10033403] = {
          ContentFR = "Tenez-les... empêchez-les d’avancer...",
          DialogueId = 10033403,
          GUID = "191E192E",
          SpeakNpcId = 100311,
          Subtitle = "Stop them...",
          VoiceName = "voice/$Locale$/story/1003/100334/191E192E"
        },
        [10033404] = {
          ContentFR = "N… non… la ligne de défense est brisée…",
          DialogueId = 10033404,
          GUID = "191E1958",
          SpeakNpcId = 100311,
          Subtitle = "We can't... they've broken through...",
          VoiceName = "voice/$Locale$/story/1003/100334/191E1958"
        },
        [10033405] = {
          ContentFR = "Évacuez les blessés ! Vite, sortez-les d’abord !",
          DialogueId = 10033405,
          GUID = "191E1982",
          SpeakNpcId = 100311,
          Subtitle = "Evacuate the wounded! Hurry! Get them out first!",
          VoiceName = "voice/$Locale$/story/1003/100334/191E1982"
        },
