          VoiceName = "voice/$Locale$/story/1003/100335/191E2996"
        },
        [10033504] = {
          Camera = "112.855469,32.067932,49.595215,-0.000244,14.78796,-153.224548,25.000006,170.053772,false,DoNotOverride,3.29697",
