          Scripts = "SEQ{CameraMoveTo{_delay{1.2},TargetPosition{\"112.855469,32.067932,49.595215,-0.000245,20.987892,-153.824799,25.000006,43.460876,false,Manual,1.879206\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"123.0,7.0,36.0,64.691109,1.146194,-133.430832,25.000006,23.70698,false,Manual,1.2\"},Blend{\"easeOutQuad\"},duration{4}}}",
          SpeakNpcId = 100001,
