        },
        [10033505] = {
          Camera = "-112.908203,-136.419312,107.219604,0.000322,13.597683,-108.007072,35.000023,100000.0,false,Manual,22.0",
          ContentFR = "Merci à vous. Sans votre aide, les pertes des Veilleurs auraient été bien plus lourdes.",
          DialogueId = 10033505,
          FinalCamera = "-107.800781,-138.011902,107.219604,0.000322,13.397675,-110.206947,35.000023,100000.0,false,Manual,22.0",
          GUID = "191E29EA",
          LookAt = {
            [1] = "200021:n(100311)",
            [2] = "200002:n(100311)"
          },
          NextOptions = {
            [1] = 10033506
          },
          Scripts = "PARA{SetLocation{ActorId{200021},TargetPoint{\"Point1\"},Visibility{\"Show\"}},SetLocation{ActorId{200002},TargetPoint{\"Point2\"},Visibility{\"Show\"}},SetRotation{SetRotationDescription{\"100311:n(100001)\"}},SetRotation{SetRotationDescription{\"100001:n(100311)\"}},SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-235.177734,-315.901123,148.828979,0.00035,-3.202812,42.790451,40.0,412.833496,false,Manual,4.354144\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-238.75,-312.088318,148.828979,0.000349,-3.202819,40.790806,40.0,412.833496,false,Manual,4.354144\"},duration{10}}}}",
          SpeakNpcId = 100311,
          Subtitle = "Thank you so much for your help. Without you, the Escort would've suffered far more casualties.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E29EA"
        },
        [10033506] = {
          ContentFR = "<I>Je n’ai fait que ma part.</>",
          DialogueId = 10033506,
          GUID = "191E2A14",
          NextDialogue = 10033507,
          Subtitle = "Just doing my part."
        },
        [10033507] = {
          Camera = "1902.650391,-988.80188,108.232178,0.000259,-0.801236,149.196533,35.000011,3157.576416,false,Manual,1.376868",
          ContentFR = "Quoi qu’il en soit, nous vous sommes redevables. Je vais prévenir mes camarades pour qu’ils vous raccompagnent.",
          DialogueId = 10033507,
          FinalCamera = "1898.128906,-996.384766,108.232178,0.000259,-0.801236,149.596466,35.000011,3157.576416,false,Manual,1.376868",
          GUID = "191E2A3E",
          NextDialogue = 10033508,
          SpeakNpcId = 100311,
          Subtitle = "Still, we truly appreciate it. I'll contact my squadmates and have them escort you out.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2A3E"
        },
        [10033508] = {
          Camera = "-138.914062,-208.657227,182.986816,-0.000002,-38.999802,-104.019676,35.000023,100000.0,false,Manual,22.0",
          ContentFR = "Tch... Mon émetteur déconne encore ? Tant pis. Vous les croiserez sur la route. Nous devons sceller toute la section par laquelle vous êtes arrivés. Prenez ce passage-là, vous tomberez vite sur eux.",
          DialogueId = 10033508,
          FinalCamera = "-125.476562,-154.847595,227.898438,18.000706,-38.999802,-104.019608,35.000023,100000.0,false,Manual,22.0",
          GUID = "191E2A68",
          LookAt = {
            [1] = "200021:n(100311)",
            [2] = "200002:n(100311)"
          },
          NextDialogue = 10033509,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-83.787109,-712.988647,30.291992,-0.001007,8.196595,93.593033,35.000023,505.590393,false,Manual,11.621747\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-104.068359,-713.623779,30.291992,-0.001008,9.196576,91.393059,35.000023,505.590393,false,Manual,11.621747\"},duration{10}}}}",
          SpeakNpcId = 100311,
          Subtitle = "Ugh, the comms are acting up again. Never mind, you'll run into them on your way out. We'll have to seal off the tunnels you came through. Just head that way, and you'll see them soon.",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 0.3,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2A68"
        },
        [10033509] = {
          Camera = "108.683594,-29.236145,139.334595,0.000065,-0.203772,172.19281,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "Mon {性别:ami|amie}, t’as vraiment eu la vie dure. Tu viens de sortir du coma, et maintenant ça. Si Rhythm n’était pas intervenu, tu serais probablement en train de faire une autre longue sieste en ce moment.",
          DialogueId = 10033509,
          FinalCamera = "109.099609,-16.699524,139.334595,0.000065,-1.003785,179.992462,35.000011,100000.0,false,Manual,22.0",
          GUID = "191E2A92",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 10033510,
          Scripts = "PlayAnimation{_delay{5},ActorId{200021},AnimationId{\"Sigh_End\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Man, you've had it rough. Just woke up from a coma, and now this. If Rhythm hadn't stepped in, you'd probably be taking another long nap right now.",
          TalkActionId = {
            [1] = "200021:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2A92"
        },
        [10033510] = {
          Camera = "-223.230469,-130.493103,71.03064,0.00022,14.995399,178.000687,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Exactement ! J’ai eu une peur bleue ! Si mon petit larbin s’était mis à baver partout, qu’est-ce que j’aurais fait, moi  ?! ",
          DialogueId = 10033510,
          FacialId = {
            [1] = "200002:Shock01"
          },
          FinalCamera = "-151.314453,-134.048645,51.274292,0.000221,13.395059,176.400452,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191E2ABC",
          NextOptions = {
            [1] = 10033511,
            [2] = 10033513
          },
          Scripts = "PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Sigh_End\"},Duration{2}}",
          SpeakNpcId = 200002,
          Subtitle = "Yeah! You almost gave me a heart attack back there! I was so worried my Little Minion would end up with serious brain damage and not even recognise me anymore!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2ABC"
        },
        [10033511] = {
          ContentFR = "<I>Merci de vous inquiéter pour moi.</>",
          DialogueId = 10033511,
          GUID = "191E2AE6",
          ImprPlusId = 1009,
          NextDialogue = 10033512,
          Subtitle = "Thank you for caring about me."
        },
        [10033512] = {
          Camera = "121.15625,-31.336243,130.51001,0.000213,2.795951,170.599884,35.000015,100000.0,false,Manual,22.0",
          ContentFR = "Allez, pas besoin d’être si {性别:formel|formelle} avec nous.",
          DialogueId = 10033512,
          FinalCamera = "143.15625,-34.978027,129.421143,0.000213,2.795951,170.599884,35.000015,100000.0,false,Manual,22.0",
          GUID = "191E2B10",
          NextDialogue = 10033516,
          Scripts = "SEQ{PlayAnimation{_delay{3},ActorId{200002},AnimationId{\"Confident_End\"},Duration{2}},PlayAnimation{_delay{3},ActorId{200021},AnimationId{\"Talk02_End\"},Duration{2}}}",
          SpeakNpcId = 200021,
          Subtitle = "C'mon, no need to get all formal with your buddies.",
          TalkActionId = {
            [1] = "200021:Talk02_Start",
            [2] = "200002:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2B10"
        },
        [10033513] = {
          ContentFR = "<I>Non, vraiment, je vais bien.</>",
          DialogueId = 10033513,
          GUID = "191E2B3A",
          ImprPlusId = 1007,
          NextDialogue = 10033514,
          Subtitle = "I'm fine, really."
        },
        [10033514] = {
          Camera = "171.294922,-63.202942,123.535767,0.000178,2.594707,165.981323,35.000015,100000.0,false,Manual,22.0",
          ContentFR = "D’accord... mais dis-le si quelque chose cloche. Certaines blessures se réveillent bien plus tard. ",
          DialogueId = 10033514,
          FinalCamera = "167.292969,-79.613342,123.535767,0.000178,2.394664,161.180527,35.000015,100000.0,false,Manual,22.0",
          GUID = "191E2B64",
          NextDialogue = 10033515,
          Scripts = "PlayAnimation{_delay{2},ActorId{200021},AnimationId{\"Confident_Start\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Just don't stay quiet if something's wrong, okay? Some injuries don't show until you're old — then they hit you like a truck.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2B64"
        },
        [10033515] = {
          Camera = "-241.916016,12.718933,151.480347,0.000221,-24.00493,-116.195557,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Haha, l’Étranger, on dirait un vieux grand-père quand tu parles comme ça !",
          DialogueId = 10033515,
          FacialId = {
            [1] = "200002:Think01"
          },
          FinalCamera = "-230.193359,6.846252,151.480347,0.000232,-24.604969,-123.195885,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191E2B8E",
          LookAt = {
            [1] = "200002:n(200021)"
          },
          NextDialogue = 10033516,
          SpeakNpcId = 200002,
          Subtitle = "Wow, Outsider, you sound like a grandpa.",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2B8E"
        },
        [10033516] = {
          Camera = "-24.765625,-99.843445,139.282227,0.000232,2.592227,163.993256,35.000015,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Bon, si on n’a plus rien à faire ici... on rentre se reposer ?",
          DialogueId = 10033516,
          FinalCamera = "-32.369141,-124.105286,139.282227,0.000233,2.592227,157.393356,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191E2BB8",
          LookAt = {
            [1] = "200002:n(200002)"
          },
          NextDialogue = 10033517,
          SpeakNpcId = 200021,
          Subtitle = "Alright, since our work here's done, how about we head home and rest up?",
          TalkActionId = {
            [1] = "200002:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2BB8"
        },
        [10033517] = {
          Camera = "-140.902344,-181.350952,57.819458,0.000238,9.192799,159.999252,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Mmmh... mais Officier Fischer avait l’air très mal en point... on devrait aller voir comment elle va !",
          DialogueId = 10033517,
          FacialId = {
            [1] = "200002:Sad03"
          },
          FinalCamera = "-132.044922,-150.669006,57.819458,0.00024,9.592809,170.198151,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "191E2BE2",
          NextDialogue = 10033518,
          Scripts = "PlayFacial{_delay{3},ActorId{200002},FacialId{\"None\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Mmm... but Officer Fischer looked really bad back there! Shouldn't we check on her first?",
          TalkActionId = {
            [1] = "200002:Bai_Think2Confident",
            [2] = "200021:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100335/191E2BE2"
        },
        [10033518] = {
          Camera = "-69.097656,-83.115845,148.539307,0.000209,1.550528,163.935776,35.000015,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Elle a sûrement été envoyée à l’Hôpital de la Légion, dans la cité intérieure. Et tu sais bien qu’on n’y rentre pas comme ça.",
          DialogueId = 10033518,
          FinalCamera = "-30.691406,-94.174072,147.457397,0.000209,1.550528,163.935776,35.000015,100000.0,false,DoNotOverride,22.0",
