          FinalCamera = "100.893311,-31.535828,129.936584,0.000341,4.402733,102.394142,35.000011,100000.0,false,Manual,22.0",
          GUID = "191E4A3C",
          NextDialogue = 10033703,
          SpeakNpcId = 100001,
          Subtitle = "...They're not breathing.",
          TalkActionId = {
