        [10033802] = {
          ContentFR = "Petit larbin, viens par ici !",
          DialogueId = 10033802,
          GUID = "191E5AA4",
          SpeakNpcId = 200002,
          Subtitle = "This way, Little Minion!",
          VoiceName = "voice/$Locale$/story/1003/100338/191E5AA4"
        },
        [10033803] = {
          ContentFR = "Halte ! C’est la cité intérieure. Aucun Charon n’a le droit de passer sans autorisation spéciale !",
          DialogueId = 10033803,
          GUID = "191E5ACE",
          NextDialogue = 10033804,
          SpeakNpcId = 100325,
          Subtitle = "Halt! This is the inner city. No Charons allowed in without special clearance!",
          VoiceName = "voice/$Locale$/story/1003/100338/191E5ACE"
        },
        [10033804] = {
          ContentFR = "Oh, c’est vous. Du calme, {性别:ils|elles} viennent juste de rendre un grand service aux Veilleurs.",
          DialogueId = 10033804,
          GUID = "191E5AF8",
          NextDialogue = 10033805,
          SpeakNpcId = 100325,
          Subtitle = "Oh, it's you guys. Ease up — they just did the Escort a huge favour.",
          VoiceName = "voice/$Locale$/story/1003/100338/191E5AF8"
        },
        [10033805] = {
          ContentFR = "Vous venez faire quoi dans la cité intérieure ?",
          DialogueId = 10033805,
          GUID = "191E5B22",
          NextDialogue = 10033806,
          SpeakNpcId = 100325,
          Subtitle = "What brings you to the inner city?",
          VoiceName = "voice/$Locale$/story/1003/100338/191E5B22"
        },
        [10033806] = {
          ContentFR = "Nous voulons prendre des nouvelles de l’Officier Fischer et voir si elle va bien.",
          DialogueId = 10033806,
          GUID = "191E5B4C",
          NextDialogue = 10033807,
          SpeakNpcId = 100001,
          Subtitle = "We want to check on Officer Fischer and see if she's okay.",
          VoiceName = "voice/$Locale$/story/1003/100338/191E5B4C"
        },
        [10033807] = {
          ContentFR = "J’ai entendu dire qu’elle est sortie d’affaire, mais qu’elle est encore inconsciente. Si vous voulez vraiment la voir, je peux vous faire entrer. Restez discrets et suivez-moi.",
          DialogueId = 10033807,
          GUID = "191E5B76",
          SpeakNpcId = 100325,
          Subtitle = "I heard she made it through, though she's still unconscious in the hospital. I can take you there. Just lay low and follow me.",
          VoiceName = "voice/$Locale$/story/1003/100338/191E5B76"
        },
        [10033901] = {
          Camera = "24.498535,102.712585,126.646484,0.000073,-6.999646,-158.394653,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "L’air sent fort le désinfectant. Dans la pièce silencieuse, seule la respiration régulière de Rhythm se fait entendre.",
          DialogueId = 10033901,
          FacialId = {
            [1] = "100360:Close"
          },
          FinalCamera = "27.636719,94.549805,126.646484,0.000073,-6.799651,-160.394623,35.000008,100000.0,false,Manual,22.0",
          GUID = "191E6AE2",
          NextDialogue = 10033902,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405005,
            [3] = 201011
          },
          Scripts = "SEQ{CameraMoveTo{_delay{4},TargetPosition{\"-69.343262,549.935181,167.714844,0.000155,-3.198639,-29.731237,35.000015,100000.0,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-39.04248,602.994751,167.714844,0.000155,-3.398593,-32.931664,35.000015,100000.0,false,Manual,22.0\"},duration{4}}}",
          Subtitle = "(The faint sting of disinfectant fills the air. In the stillness of the room, Rhythm's steady breathing is the only sound.)",
          TalkActionId = {
            [1] = "100360:Lise_Lieidle"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6AE2"
        },
        [10033902] = {
          Camera = "165.0,2.0,359.658203,-179.994263,-87.068275,81.286964,35.000019,100000.0,false,Manual,22.0",
          ContentFR = "Son visage est paisible. Sans ses terribles blessures, on croirait une jeune fille plongée dans un rêve tranquille. Après tout, elle est encore à l’âge de rêver.",
          DialogueId = 10033902,
          FinalCamera = "165.0,2.0,318.0,-165.594345,-87.068413,81.287193,35.000019,100000.0,false,Manual,22.0",
          GUID = "191E6B0C",
          NextDialogue = 10033903,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"236.759277,8.561646,82.060547,-0.001007,3.71761,179.18042,35.000019,68.10289,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"236.621582,-1.383545,82.060547,-0.001007,3.71761,179.18042,35.000019,68.10289,false,Manual,22.0\"},duration{8}}}",
          Subtitle = "(She looks peaceful. Were it not for the horrific wounds, one might mistake her for a girl lost in a tranquil dream — after all, she is so young, still at an age for dreams.)",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6B0C"
        },
        [10033903] = {
          Camera = "440.781738,-108.77594,198.904297,0.000069,-9.407048,145.046661,35.000019,581.174438,false,Manual,1.203584",
          ContentFR = "On dirait qu’elle ne va pas se réveiller de sitôt.",
          DialogueId = 10033903,
          FacialId = {
            [1] = "100001:Confident01",
            [2] = "200021:Think01"
          },
          FinalCamera = "437.213867,-113.824066,198.904297,0.000069,-9.407048,144.44664,35.000019,581.174438,false,Manual,1.203584",
          GUID = "191E6B36",
          NextDialogue = 10033904,
          Scripts = "MoveTo{ActorId{200021},TargetPoint{\"Point01\"},MoveSpeed{80},Visibility{\"Show\"}}",
          SpeakNpcId = 200021,
          Subtitle = "Doesn't look like she's doing too well.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6B36"
        },
        [10033904] = {
          Camera = "15.115234,180.011108,131.390625,0.000063,-23.806725,38.66003,35.000019,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Ah ! Tu marches comme un chat ! Tu ne fais pas le moindre bruit...",
          DialogueId = 10033904,
          FacialId = {
            [1] = "200002:Shock01"
          },
          FinalCamera = "-118.733887,89.56427,200.0,0.000064,-24.006701,40.061115,35.000019,100000.0,false,DoNotOverride,22.0",
          GUID = "191E6B60",
          LookAt = {
            [1] = "200002:n(200021)"
          },
          NextDialogue = 10033905,
          SpeakNpcId = 200002,
          Subtitle = "Eek! How come you walk like a cat? Not a single sound at all...",
          TalkActionId = {
            [1] = "200002:Shock_Start",
            [2] = "200021:Confident_Start"
          },
          ToFinalCameraBlendTime = 0.25,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6B60"
        },
        [10033905] = {
          Camera = "33.217773,125.854919,134.521484,0.000093,2.393059,111.061989,35.000015,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Te voilà. As-tu réussi à signaler la situation concernant le poison aux soldats de la cité intérieure ?",
          DialogueId = 10033905,
          FinalCamera = "17.6875,121.21051,134.521484,0.000088,1.993083,104.461479,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191E6B8A",
          LookAt = {
            [1] = "100001:n(200021)",
            [2] = "200002:n(200002)",
            [3] = "200021:n(200021)"
          },
          NextDialogue = 10033906,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"142.0,-84.0,101.0,0.000097,5.591923,124.053864,35.000019,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"133.336426,-89.81842,101.0,0.000097,5.591923,121.254005,35.000019,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "There you are, Outsider. Did you manage to report the situation about the poison to the inner city soldiers?",
          TalkActionId = {
            [1] = "200002:Shock_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6B8A"
        },
        [10033906] = {
          Camera = "-21.286133,28.451904,241.835938,0.000052,-28.808077,103.452721,35.000015,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Oui, ça a pris du temps, mais ils ont compris. Et elle, ça va ?",
          DialogueId = 10033906,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          FinalCamera = "-21.286133,28.451904,241.835938,0.000062,-28.408081,97.652969,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191E6BB4",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10033907,
          Scripts = "PARA{LookAt{_delay{4},LookAtDescription{\"200021:n(200021)\"}},SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-280.063477,458.90332,239.466797,0.000107,-17.405077,-43.745438,35.000023,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-280.063477,458.90332,239.466797,0.000104,-15.204923,-43.745186,35.000023,100000.0,false,DoNotOverride,22.0\"},duration{5}}}}",
          SpeakNpcId = 200021,
          Subtitle = "Yeah, took a while, but they finally got it. How's she holding up?",
          TalkActionId = {
            [1] = "200021:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6BB4"
        },
        [10033907] = {
          Camera = "-81.523438,283.592834,150.683594,0.00011,-8.204743,-37.341213,35.000023,332.760406,false,Manual,4.091501",
          ContentFR = "Ils disent qu’elle n’est plus en danger, mais... il ne semble pas qu’elle se réveillera de sitôt.",
          DialogueId = 10033907,
          FinalCamera = "-84.269043,279.994141,150.683594,0.000113,-8.204743,-35.341167,35.000023,332.760406,false,Manual,4.091501",
          GUID = "191E6BDE",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200021:n(100360)"
          },
          NextDialogue = 10033908,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"211.149902,-1.937378,87.357422,0.000139,7.79136,141.059586,35.000019,350.177124,false,Manual,2.141533\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"208.573242,-5.074341,87.357422,0.000137,7.79136,140.259949,35.000019,350.177124,false,Manual,2.141533\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "They said she's stable, but... it doesn't look like she'll wake up anytime soon.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6BDE"
        },
        [10033908] = {
          Camera = "106.286621,81.659973,136.853516,0.000117,2.589987,156.447357,35.000023,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Elle se réveillera.",
          DialogueId = 10033908,
          FacialId = {
            [1] = "200021:Angry01"
          },
          FinalCamera = "106.286621,81.659973,136.853516,0.000117,4.390008,156.447113,35.000023,100000.0,false,DoNotOverride,22.0",
          GUID = "191E6C08",
          NextDialogue = 10033909,
          SpeakNpcId = 200021,
          Subtitle = "She will.",
          TalkActionId = {
            [1] = "200021:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6C08"
        },
        [10033909] = {
          Camera = "35.591309,171.008667,116.136719,0.000114,-15.807728,48.257145,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Quoi ?! Ne me dis pas que tu es aussi un expert en médecine !",
          DialogueId = 10033909,
          FacialId = {
            [1] = "200002:Happy01"
          },
          FinalCamera = "17.802734,151.073669,123.701172,0.000114,-15.807707,48.257084,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191E6C32",
          LookAt = {
            [1] = "200002:n(200021)"
          },
          NextDialogue = 10033910,
          SpeakNpcId = 200002,
          Subtitle = "Why? Don't tell me you are also a medicine expert!",
          TalkActionId = {
            [1] = "200002:Bai_Talk03Quick"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6C32"
        },
        [10033910] = {
          Camera = "461.0,-36.0,227.0,0.000208,-7.596256,153.67186,40.000011,699.855347,false,Manual,1.599285",
          ContentFR = "Pas vraiment. Mais je comprends un peu les gens.",
          DialogueId = 10033910,
          FinalCamera = "461.0,-36.0,234.0,0.000208,-7.596256,153.67186,40.000011,699.855347,false,Manual,1.599285",
          GUID = "191E6C5C",
          LookAt = {
            [1] = "200002:n(100360)",
            [2] = "100001:n(200021)"
          },
          NextDialogue = 10033911,
          Scripts = "PlayAnimation{_delay{4},ActorId{200021},AnimationId{\"Confident_End\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "Not at all. It's just that I read people.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6C5C"
        },
        [10033911] = {
          Camera = "22.721191,147.070129,213.337891,14.478269,-31.792528,169.829453,40.000027,699.855347,false,DoNotOverride,1.599285",
          ContentFR = "Regarde ses mains : calleuses, usées. Ce sont celles de quelqu’un qui travaille dur depuis des années. Elle est vraiment dévouée.",
          DialogueId = 10033911,
          FinalCamera = "22.27002,142.886963,212.416016,14.479208,-31.792534,167.828476,40.000027,699.855347,false,DoNotOverride,1.599285",
          GUID = "191E6C86",
          NextDialogue = 10033912,
          SpeakNpcId = 200021,
          Subtitle = "Look at her hands — calloused, roughened. Those come from years of hard work. She's indeed a dedicated soldier.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6C86"
        },
        [10033912] = {
          Camera = "-147.882324,242.155945,207.876953,0.000033,-21.398981,-37.788219,35.0,699.855347,false,DoNotOverride,1.599285",
          ContentFR = "Et en plus, c’est une tête de mule. Ses yeux pleins d’entrain m’agacent, parce que ce genre de personne ne sait jamais quand s’arrêter ni prendre une autre voie. Elle doit aller jusqu’au bout, jusqu’à se faire vraiment mal.",
          DialogueId = 10033912,
          FinalCamera = "-147.882324,242.155945,207.876953,0.000033,-18.398855,-37.787617,35.0,699.855347,false,DoNotOverride,1.599285",
          GUID = "191E6CB0",
          NextDialogue = 10033913,
          Scripts = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"91.999512,-31.641846,83.878906,0.000177,0.801796,22.820667,35.0,699.855347,false,DoNotOverride,1.599285\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"89.305664,-25.238281,83.878906,0.000177,0.801796,22.820667,35.0,699.855347,false,DoNotOverride,1.599285\"},duration{8}}}",
          SpeakNpcId = 200021,
          Subtitle = "And those eyes of hers — always so stubborn and full of determination. People like that never know when to stop or take an easier way out. They always have to push until they hurt themselves badly.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6CB0"
        },
        [10033913] = {
          Camera = "134.203613,109.259399,124.238281,-0.000946,6.40391,164.582108,35.000011,699.855347,false,DoNotOverride,1.599285",
          ContentFR = "C’est pour ça qu’avant d’avoir réglé la \"Traque aux Charons\", elle ne restera pas dans les vapes bien longtemps. Pour l’instant, on se repose et on attend qu’elle se réveille.",
          DialogueId = 10033913,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "135.833008,115.049255,124.238281,-0.000946,6.40391,166.781784,35.000011,699.855347,false,DoNotOverride,1.599285",
          GUID = "191E6CDA",
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"624.469238,-61.893066,498.599609,-0.000946,-36.395668,162.188492,35.000011,699.855347,false,DoNotOverride,1.599285\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"624.469238,-61.893066,498.599609,-0.000946,-30.996033,156.988922,35.000008,699.855347,false,DoNotOverride,1.599285\"},duration{12}}},PlayAnimation{_delay{4},ActorId{200021},AnimationId{\"ConfidentLR_End\"},Duration{2}}",
          SpeakNpcId = 200021,
          Subtitle = "So she's not going to stay down for long. She'll drag herself back into the fight before the \"Charon Hunt\" case is resolved. For now, all we have to do is have a good rest and wait for her to wake up.",
          TalkActionId = {
            [1] = "200021:ConfidentLR_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E6CDA"
        },
        [10033914] = {
          Camera = "29.499023,114.307373,105.529053,0.000116,2.145451,-109.253723,35.000011,173.868729,false,Manual,7.109471",
          ContentFR = "Rhythm... Rhythm !",
          DialogueId = 10033914,
          FacialId = {
            [1] = "100357:None"
          },
          FinalCamera = "32.957031,113.430908,105.529053,0.000117,2.145451,-112.853188,35.000011,173.868729,false,Manual,7.109471",
          GUID = "191E6D04",
