        [10033958] = {
          Camera = "136.705566,46.355042,75.931641,0.000173,10.396743,157.782089,30.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Incroyable ! Oreilles-de-chien avait raison ! Officier Fischer est aussi coriace que notre capitaine, increvable, même !",
