          FacialId = {
            [1] = "200002:Happy01"
          },
          FinalCamera = "136.705566,46.355042,75.931641,0.000171,12.596699,157.58223,30.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191E743C",
          LookAt = {
            [1] = "200021:n(100360)",
            [2] = "200002:n(100360)"
          },
          NextDialogue = 10033959,
          RelatedWikiId = {
