          },
          Scripts = "PARA{SetLocation{ActorId{200002},TargetPoint{\"cp2fixsimple24_27-29_34-35Point02\"},Visibility{\"Show\"}},SetRotation{SetRotationDescription{\"200002:n(100360)\"}}}",
          SpeakNpcId = 200002,
          Subtitle = "Mutt Ears totally called it! Officer Fischer's just as tough as our captain — practically unkillable!",
          TalkActionId = {
            [1] = "200002:Bai_Think2Confident"
          },
          ToFinalCameraBlendTime = 10,
