        [10033959] = {
          Camera = "-286.618164,517.352295,362.435547,0.000032,-29.40173,-53.420368,30.000008,104.238808,false,DoNotOverride,2.390177",
          ContentFR = "C’est vous... Je me souviens... j’étais avec Blu— non... avec vous, dans les égouts... à poursuivre ce—",
          DialogueId = 10033959,
          FinalCamera = "-258.114746,478.944214,335.484375,0.000035,-28.201666,-52.620518,30.000008,104.238808,false,DoNotOverride,2.390177",
          GUID = "191E7466",
          NextDialogue = 10033960,
          SpeakNpcId = 100360,
          Subtitle = "It's you... I remember I was with Blu— No, wait... We were in the sewers... chasing...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7466"
        },
        [10033960] = {
          Camera = "169.741211,144.894043,125.21875,3.000217,-3.200702,-87.040405,50.0,92.341805,false,Manual,12.0",
          ContentFR = "Le monstre ! Le coupable de la \"Traque aux Charons\"... vous l’avez attrapé ?",
          DialogueId = 10033960,
