          GUID = "191E7490",
          LookAt = {
            [1] = "100360:n(100001)"
          },
          NextDialogue = 10033961,
          SpeakNpcId = 100360,
          Subtitle = "The monster! The perpetrator of the \"Charon Hunt\" — did we catch it!?",
          TalkActionId = {
