          ContentFR = "Doucement, doucement. Vous êtes restée inconsciente deux jours. Buvez un peu d’eau, mangez quelque chose, et parlez après.",
          DialogueId = 10033961,
          FacialId = {
            [1] = "200021:Doubt01",
            [2] = [[

100360:Sad01]]
          },
          FinalCamera = "-0.458984,125.16803,121.416016,0.000119,17.598282,152.169144,35.000008,465.220367,false,DoNotOverride,7.813529",
          GUID = "191E74BA",
          LookAt = {
            [1] = "100360:n(200021)"
          },
          NextDialogue = 10033962,
          Scripts = "SEQ{CameraMoveTo{_delay{4},TargetPosition{\"-167.291016,247.330383,181.025391,0.000099,-10.400629,-37.432755,35.0,465.220367,false,Manual,7.813529\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-165.0625,250.305298,181.025391,0.000106,-9.800624,-38.831615,35.0,465.220367,false,Manual,7.813529\"},duration{8}}}",
          SpeakNpcId = 200021,
          Subtitle = "Whoa, slow down. You've been unconscious for two days. Take a breath, have some water and eat something first.",
          TalkActionId = {
            [1] = "200021:ConfidentLR_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E74BA"
        },
        [10033962] = {
          Camera = "109.945801,117.563965,114.839844,0.000105,6.997317,151.569946,30.000013,465.220367,false,DoNotOverride,7.813529",
          ContentFR = "Je vais vous raconter. Le jour où on vous a tirée des égouts...",
          DialogueId = 10033962,
          FacialId = {
            [1] = "200002:Smile01"
          },
          FinalCamera = "123.980957,143.491638,114.839844,0.000105,6.997317,151.569946,30.000013,465.220367,false,DoNotOverride,7.813529",
          GUID = "191E74E4",
          Scripts = "PlayAnimation{_delay{4},ActorId{100001},AnimationId{\"Talk03_End\"},Duration{2}}",
          SpeakNpcId = 100001,
          Subtitle = "I'll explain. That day, after they got you out of the sewer...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E74E4"
        },
        [10033963] = {
          Camera = "81.914062,91.29718,110.552734,0.000137,4.597366,-25.221094,30.000013,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Alors... il a fini par s’échapper... Je—",
          DialogueId = 10033963,
          FacialId = {
