            [2] = "200021:Confident01"
          },
          FinalCamera = "83.604004,94.886536,110.552734,0.000138,4.397357,-25.220875,30.000013,100000.0,false,DoNotOverride,22.0",
          GUID = "191E750E",
          LookAt = {
            [1] = "100001:n(100360)",
            [2] = "200002:n(100360)",
            [3] = "200021:n(100360)"
          },
          NextDialogue = 10033964,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405005,
            [3] = 201011,
            [4] = 201024
          },
          Scripts = "PARA{SetLocation{ActorId{200021},TargetPoint{\"Point01\"},Visibility{\"Show\"}},SetLocation{ActorId{200002},TargetPoint{\"cp2fixsimple24_27-29_34-35Point02\"},Visibility{\"Show\"}},SetRotation{SetRotationDescription{\"200002:n(100360)\"}}}",
          SpeakNpcId = 100360,
          Subtitle = "So... it got away after all... I—",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E750E"
        },
        [10033964] = {
          Camera = "131.790039,122.645935,122.564453,0.000205,6.79308,168.303848,35.000015,364.535095,false,DoNotOverride,1.2",
          ContentFR = "Hé, ne bougez pas ! Ne me dites pas que vous pensez déjà retourner dans ces égouts ? Ton équipe est encore en train de fouiller là-bas. Et vous, vous êtes blessée. Dans cet état, vous n’aiderez personne.",
          DialogueId = 10033964,
          FinalCamera = "133.391602,129.9245,122.564453,0.000205,6.79308,170.903305,35.000015,364.535095,false,DoNotOverride,1.2",
          GUID = "191E7538",
          NextDialogue = 10033965,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{3},TargetPosition{\"282.059082,49.649109,102.980469,0.000203,6.593188,170.706314,35.000011,364.535095,false,Manual,3.069153\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"282.754395,53.502625,102.980469,0.000204,6.593188,172.306107,35.000011,364.535095,false,Manual,3.069153a\"},duration{6}}},PlayAnimation{_delay{5},ActorId{200021},AnimationId{\"Talk02_End\"},Duration{2}}}",
          SpeakNpcId = 200021,
          Subtitle = "Whoa, easy! Don't tell me you're thinking about diving back into that sewer. Your squad's already on it, and you're supposed to be resting. You're not going to help anyone in your condition.",
          TalkActionId = {
            [1] = "200021:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7538"
        },
        [10033965] = {
          Camera = "397.937012,-12.607971,226.421875,0.000144,-19.40346,157.524979,30.0,388.355713,false,Manual,4.2486",
          ContentFR = "Oui. Vous avez déjà fait tout ce que vous pouviez. Laissez vos camarades prendre le relais.",
          DialogueId = 10033965,
          FinalCamera = "397.937012,-12.607971,226.421875,0.000143,-14.803314,156.525467,30.0,388.355713,false,Manual,4.2486",
          GUID = "191E7562",
          NextDialogue = 10033966,
          SpeakNpcId = 100001,
          Subtitle = "Yeah. You've done everything you can. Let your colleagues take over from here.",
          TalkActionId = {
            [1] = "100001:ConfidentR_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7562"
        },
        [10033966] = {
          Camera = "92.006348,168.797363,188.957031,0.000154,-30.005915,-51.09058,35.000011,364.535095,false,DoNotOverride,3.069153",
          ContentFR = "...",
          DialogueId = 10033966,
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "92.006348,168.797363,188.957031,0.000163,-27.405846,-52.691006,35.000011,364.535095,false,DoNotOverride,3.069153",
          GUID = "191E758C",
          NextDialogue = 10033967,
          SpeakNpcId = 100360,
          Subtitle = "...",
          TalkActionId = {
            [1] = "200021:Talk02_End",
            [2] = "100360:Lise_Liewake_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100339/191E758C"
        },
        [10033967] = {
          Camera = "-268.598145,387.694153,258.564453,0.000162,-20.205399,-40.091068,35.000015,364.535095,false,DoNotOverride,3.069153",
          ContentFR = "Pardon. Je vous fais perdre votre temps. Et je n’ai même pas été capable de tenir ma promesse... vous aider à retrouver votre famille.",
          DialogueId = 10033967,
          FinalCamera = "-290.066406,405.767212,268.894531,0.000162,-20.205399,-40.091068,35.000015,364.535095,false,DoNotOverride,3.069153",
          GUID = "191E75B6",
          NextDialogue = 10033968,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"100360:n(200021)"}},
LookAt{_delay{2.1},LookAtDescription{"100360:n(100001)"}},
}]],
          SpeakNpcId = 100360,
          Subtitle = "I'm sorry for wasting your time. I haven't even been able to keep my promise to help you find your family...",
          TalkActionId = {
            [1] = "100001:ConfidentR_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E75B6"
        },
        [10033968] = {
          Camera = "258.082031,16.400024,106.958984,0.000199,2.394418,147.306931,35.000011,364.535095,false,DoNotOverride,3.069153",
          ContentFR = "Ah... oui.",
          DialogueId = 10033968,
          FinalCamera = "258.082031,16.400024,106.958984,0.000199,3.994383,144.706436,35.000011,364.535095,false,DoNotOverride,3.069153",
          GUID = "191E75E0",
          NextDialogue = 10033969,
          SpeakNpcId = 100360,
          Subtitle = "Oh, right.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E75E0"
        },
        [10033969] = {
          Camera = "141.86377,306.253906,122.765625,0.000177,5.989379,-155.498428,35.0,216.320572,false,DoNotOverride,3.374357",
          ContentFR = "Tenez, c’est la clé de ma base secrète. L’adresse est gravée au dos. Pourriez-vous y aller et me rapporter un sceau en argent, gravé à mon nom ?",
          DialogueId = 10033969,
          FinalCamera = "144.689941,300.053467,122.765625,0.000177,5.989379,-155.498428,35.0,216.320572,false,DoNotOverride,3.374357",
          GUID = "191E760A",
          NextDialogue = 10033970,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"652.945312,463.934875,412.007812,0.000188,-23.608671,-148.696426,35.000008,216.320572,false,DoNotOverride,3.374357\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"625.39502,505.701294,412.007812,0.000183,-23.408648,-144.695618,35.000008,216.320572,false,DoNotOverride,3.374357\"},duration{5}}}",
          SpeakNpcId = 100360,
          Subtitle = "Here, take this. It's the key to my secret base. The address is written on the back. Could you go there and grab my silver seal with my name on it?",
          TalkActionId = {
            [1] = "200021:ConfidentLR_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1003/100339/191E760A"
        },
        [10033970] = {
          Camera = "291.686035,147.772278,166.871094,-10.000484,-20.003922,-142.886566,35.000015,364.535095,false,DoNotOverride,3.069153",
          ContentFR = "Je ne peux pas encore vous aider directement... mais je peux au moins écrire quelques lettres et demander à d’autres de vous prêter main forte.",
          DialogueId = 10033970,
          FinalCamera = "296.286621,140.633057,172.496094,-10.001247,-21.203911,-145.486053,35.000015,364.535095,false,DoNotOverride,3.069153",
          GUID = "191E7634",
          LookAt = {
            [1] = "100360:n(100360)"
          },
          NextOptions = {
            [1] = 10033971,
            [2] = 10033973
          },
          Scripts = "PlayAnimation{_delay{4},ActorId{100001},AnimationId{\"Talk03_End\"},Duration{1}}",
          SpeakNpcId = 100360,
          Subtitle = "I'm in no condition to do much for you right now, but I can at least write a few letters to ask for help on your behalf.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7634"
        },
        [10033971] = {
          ContentFR = "<I>On peut leur faire confiance ?</>",
          DialogueId = 10033971,
          GUID = "191E765E",
          ImprPlusId = 1006,
          NextDialogue = 10033972,
          Subtitle = "Can I trust them?"
        },
        [10033972] = {
          Camera = "326.638672,-43.474365,97.0,0.000241,5.990158,147.491592,35.000008,216.320572,false,DoNotOverride,3.374357",
          ContentFR = "Oui. Ils sont rares... mais il existe encore des gens prêts à tendre la main aux Charons.",
          DialogueId = 10033972,
          FinalCamera = "322.354492,-50.202484,97.0,0.000241,5.990158,147.491592,35.000008,216.320572,false,DoNotOverride,3.374357",
          GUID = "191E7688",
          NextDialogue = 10033975,
          SpeakNpcId = 100360,
          Subtitle = "Yes. Though few in number, there are still some who are willing to lend a hand to the Charons.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7688"
        },
        [10033973] = {
          ContentFR = "<I>Même clouée au lit, vous pensez encore à m’aider ?</>",
          DialogueId = 10033973,
          GUID = "191E76B2",
          ImprPlusId = 1009,
          NextDialogue = 10033974,
          Subtitle = "...Even in a hospital bed, you're still thinking about helping me?"
        },
        [10033974] = {
          Camera = "326.638672,-43.474365,97.0,0.000241,5.990158,147.491592,35.000008,216.320572,false,DoNotOverride,3.374357",
          ContentFR = "C’est mon devoir. Et au fond... je veux vraiment vous voir réunie avec votre famille.",
          DialogueId = 10033974,
          FinalCamera = "322.354492,-50.202484,97.0,0.000241,5.990158,147.491592,35.000008,216.320572,false,DoNotOverride,3.374357",
          GUID = "191E76DC",
          NextDialogue = 10033975,
          SpeakNpcId = 100360,
          Subtitle = "I made a promise. Besides, I truly hope you'll reunite with your family.",
          TalkActionId = {
            [1] = "200021:ConfidentLR_End",
            [2] = "100001:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100339/191E76DC"
        },
        [10033975] = {
          Camera = "301.869629,98.541199,115.601562,0.000116,3.196139,162.306015,40.000011,367.813141,false,Manual,1.2",
          ContentFR = "Alors, on accepte cette aide avec gratitude.",
          DialogueId = 10033975,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "304.80127,107.63208,115.601562,0.000116,3.196132,163.505875,40.000011,367.813141,false,Manual,1.2",
          GUID = "191E7706",
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-321.128418,431.440491,273.042969,0.000077,-18.603077,-39.290245,40.0,364.535095,false,DoNotOverride,3.069153\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-354.362305,458.634705,287.5,0.000077,-18.603077,-39.290245,40.0,364.535095,false,DoNotOverride,3.069153\"},duration{5}}}",
          SpeakNpcId = 200021,
          Subtitle = "Alright, we shall gladly accept your help, then.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1003/100339/191E7706"
        },
        [10034001] = {
          ContentFR = "Une base secrète d’un soldat... ça doit être incroyable ! C’est trop excitant !",
          DialogueId = 10034001,
          GUID = "191E7B4A",
          NextDialogue = 10034002,
          SpeakNpcId = 200002,
          Subtitle = "A soldier's secret base? I bet it's packed with cool stuff! This is so exciting!",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7B4A"
        },
        [10034002] = {
          ContentFR = "D’après l’adresse, ce serait près d’un relais routier.",
          DialogueId = 10034002,
          GUID = "191E7B74",
          NextDialogue = 10034003,
          SpeakNpcId = 200021,
          Subtitle = "The address points to somewhere near the roadside freight station.",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7B74"
        },
        [10034003] = {
          ContentFR = "Elle a vraiment planqué sa base dans un endroit pareil... ?",
          DialogueId = 10034003,
          GUID = "191E7B9E",
          NextDialogue = 10034004,
          SpeakNpcId = 100001,
          Subtitle = "She actually built her secret base in a place like that?",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7B9E"
        },
        [10034004] = {
          ContentFR = "Les gens ont tendance à choisir les endroits les plus étranges pour leurs cachettes...",
          DialogueId = 10034004,
          GUID = "191E7BC8",
          NextDialogue = 10034005,
          SpeakNpcId = 200021,
          Subtitle = "People tend to pick the oddest spots for their hideaways...",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7BC8"
        },
        [10034005] = {
          ContentFR = "Certains se réfugient dans une voiture, d’autres dans une canalisation. Alors, un relais routier... pourquoi pas.",
          DialogueId = 10034005,
          GUID = "191E7BF2",
          NextDialogue = 10034006,
          SpeakNpcId = 200021,
          Subtitle = "Some use cars, some find old pipes... A roadside freight station? Seems pretty normal to me.",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7BF2"
        },
        [10034006] = {
          ContentFR = "Euh... je ne suis pas le seul à m’être faufilé dans n’importe quel endroit étant gosse, si ?",
          DialogueId = 10034006,
          GUID = "191E7C1C",
          SpeakNpcId = 200021,
          Subtitle = "Uh... please tell me I'm not the only one who used to crawl into random places as a kid.",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7C1C"
        },
        [10034007] = {
          ContentFR = "C’est bien ici ?",
          DialogueId = 10034007,
          GUID = "191E7C46",
          NextDialogue = 10034008,
          SpeakNpcId = 100001,
          Subtitle = "Is this it?",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7C46"
        },
        [10034008] = {
          ContentFR = "L’entrée devrait être dans les parages. Cherchons un peu.",
          DialogueId = 10034008,
          GUID = "191E7C70",
          SpeakNpcId = 200021,
          Subtitle = "The entrance should be near. Let's look around.",
          VoiceName = "voice/$Locale$/story/1003/100340/191E7C70"
        },
        [10034101] = {
          Camera = "-1302.09375,188.645508,676.1875,1.753743,-22.554377,-9.436762,35.000008,199.365784,false,DoNotOverride,8.0",
          ContentFR = "Hmm, on dirait que cet endroit était autrefois une ancienne salle de maintenance.",
          DialogueId = 10034101,
          FinalCamera = "-1145.925781,162.691406,610.441406,1.753743,-22.554377,-9.436762,35.000008,199.365784,false,DoNotOverride,8.0",
          GUID = "191E8BB2",
          NextDialogue = 10034102,
          SpeakNpcId = 200021,
          Subtitle = "Hmm, looks like this place used to be an old maintenance room.",
          TalkActionId = {
            [1] = "200021:ConfidentLRToExplainR_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8BB2"
        },
        [10034102] = {
          Camera = "330.632812,-30.893555,59.353516,1.753803,12.445362,178.965683,35.0,199.365784,false,DoNotOverride,8.0",
          ContentFR = "Oh ! Ça ressemble un peu à ma chambre en désordre... enfin, au luxueux palais du Roi Démon, bien sûr !",
          DialogueId = 10034102,
          FacialId = {
            [1] = "200002:Doubt01",
            [2] = "200021:Angry01",
            [3] = "100001:Doubt01"
          },
          FinalCamera = "330.792969,-23.540039,59.5625,1.753803,12.445362,178.965683,35.0,199.365784,false,DoNotOverride,8.0",
          GUID = "191E8BDC",
          NextDialogue = 10034103,
          SpeakNpcId = 200002,
          Subtitle = "Ooh, this place is kind of like my messy... I mean, the Demon King's grand chamber!",
          TalkActionId = {
            [1] = "200002:Talk01_Start",
            [2] = "200021:ConfidentLRToExplainR_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8BDC"
        },
        [10034103] = {
          Camera = "-157.855469,20.635742,139.306641,1.753745,-2.15362,-32.439327,35.000015,199.365784,false,DoNotOverride,8.0",
          ContentFR = "Séparons-nous et cherchons le sceau en argent.",
          DialogueId = 10034103,
          FinalCamera = "-148.238281,18.021484,147.634766,1.753745,-4.553892,-31.638124,35.000011,199.365784,false,DoNotOverride,8.0",
          GUID = "191E8C06",
          Scripts = "MoveTo{ActorId{100001},TargetPoint{\"cp2fixsimple30Point01\"},MoveSpeed{100},Visibility{\"Show\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Alright, let's split up and look for the silver seal.",
          TalkActionId = {
            [1] = "200002:Talk01_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C06"
        },
        [10034104] = {
          ContentFR = "Destinataire : <H>Rhythm Fischer</>, membre des Veilleurs de Givrelac, sous la tutelle de la VIᵉ Légion dans la Région de Cocytus.\n\nPour sa décision ferme, son courage exemplaire et son efficacité sans égale lors de multiples opérations de <H>purge des Souillés</>.\nPour le rôle irremplaçable qu’elle a joué dans la préservation de l’ordre public et la sécurité de la région.\n\nAprès évaluation de la Légion, et au nom de Sa Majesté Julius, il est décrété d’élever Rhythm Fischer au rang d’adjudante et de lui remettre la Distinction de l’Empereur.\n\nQu’elle demeure un modèle pour tous les soldats, les incitant à se surpasser, à grandir ensemble et à offrir leur force à l’Empire.\n\nToute gloire à l’Empereur.",
          DialogueId = 10034104,
          DialoguePanelType = "{type:showtext;topic:READ_NAME_2000047;content:READ_TEXT_2000047}",
          GUID = "191E8C30",
          Subtitle = [[
Recipient: Rhythm Fischer, serving in the Icelake Escort under the 6th Legion in the Cocytus Region.
For demonstrating decisive leadership, exemplary bravery, and exceptional efficiency in multiple Filthoid-clearing operations over the years.
For playing an irreplaceable role in maintaining public order and ensuring the safety of the region.
Upon the assessment of the Legion, and by the decree of His Majesty Julius, Rhythm Fischer is hereby awarded the Emperor's signet ring and the rank of Warrant Officer. Let her serve as an inspiration to all soldiers, urging them to strive ever higher for the Empire's glory.
All glory to our Emperor.]],
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C30"
        },
        [10034105] = {
          ContentFR = "Dans un coin du mur chaulé, des mots gravés à la pointe d’un couteau se répètent, tantôt maladroits comme une écriture d’enfant, tantôt fermes comme une main adulte. Toujours la même phrase :\n\n« Je ne regarderai plus jamais quelqu’un mourir à cause d’un Souillé. »",
          DialogueId = 10034105,
          GUID = "191E8C5A",
          Subtitle = "One corner of the limewashed wall is covered in countless etched words. Some are crooked and childlike, while others are firm and deliberate, clearly written by an adult hand. All of them repeat the same sentence: \"I'll never let anyone die to Filthoids again.\"",
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C5A"
        },
        [10034106] = {
          ContentFR = "<H>Les Dégradés sont d’une dangerosité extrême, ne vous fiez jamais aux apparences !</>\n\nLe 24 septembre, un grave cas de <H>Dégradation</> s’est produit à Givrelac, entraînant de lourdes pertes. Après enquête de la VIᵉ Légion et de ses Veilleurs, les conclusions suivantes ont été établies :\n\nLe 13 septembre, Monsieur et Madame Fischer, habitants de la cité, croisa sur la route longeant la Rive du Lac du Deuil un jeune homme grièvement blessé : Robie Brown. Poussés par la compassion, ils l’accueillirent chez eux et lui prodiguèrent des soins.\nMais Robie Brown était en réalité un Dégradé. Il avait échappé aux contrôles réguliers de l’Empire et trouvé refuge hors des murs. Tout en acceptant l’aide du couple, il dissimula volontairement les marques de sa Dégradation. Dix jours plus tard, la tragédie survint : il se transforma en Souillé et massacra des dizaines de citoyens du quartier sud de Givrelac, dont le couple Fischer. L’intervention rapide des Veilleurs mit fin à la menace, mais trop tard pour éviter le carnage.\n\nLe bilan s’élève à 18 morts, dont 3 Solariens et 34 blessés.\n\nRappel à tous les citoyens : n’accordez jamais l’hospitalité à un Charon d’identité incertaine. Si vous soupçonnez la présence d’un Dégradé, signalez-le immédiatement au Bureau de la Sécurité.\n\nLes Dégradés resteront à jamais les ennemis de l’humanité, sans exception.\n\nToute personne surprise à protéger un Dégradé ou à dissimuler son existence sera condamnée à mort, conformément à l’article 54 du Code Pénal Hyperboréen.",
          DialogueId = 10034106,
          DialoguePanelType = "{type:showtext;topic:READ_NAME_2000048;content:READ_TEXT_2000048}",
          GUID = "191E8C84",
          Subtitle = "Deteriorators Are Exceptionally Dangerous — Do Not Be Fooled by Their Appearance!\nOn September 24th, an egregious case of Deterioration occurred in Icelake, with devastating consequences. Following an comprehensive investigation by the 6th Legion's Escort Unit, the details of the tragedy have now been confirmed:\nOn September 13th, local residents Mr and Mrs Fischer encountered a gravely injured young man, Robie Brown, collapsed by the roadside near Lamenting Lake. Acting out of compassion, they brought him into their home and cared for him.\nHowever, Robie Brown was a Deteriorator — one who had evaded the Empire's routine screenings and fled to the outskirts of the city. While receiving aid from the Fischers, Brown deliberately concealed his condition. Ten days later, he succumbed to the transformation, becoming a Filthoid. The resulting massacre in Icelake's southern district claimed the lives of dozens, including Mr and Mrs Fischer. The 6th Legion's Escort responded swiftly and succeeded in subduing the threat — but not before the damage was done.\n\nThe incident resulted in 18 deaths (including 3 Solarian citizens) and 34 injuries. Citizens are reminded: under no circumstances should you provide shelter to unidentified Charon individuals. If you suspect someone of being a Deteriorator, report them to the Security Bureau immediately. Deteriorators are — and will remain — humanity's enemies. No exceptions. Harbouring Deteriorators or concealing their condition is a capital offence under Article 54 of the Hyperborean Criminal Code, punishable by death.",
          VoiceName = "voice/$Locale$/story/1003/100341/191E8C84"
        },
        [10034107] = {
          Camera = "-106.066406,611.137695,77.603516,0.000153,5.204611,-92.19577,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Venez voir ça.",
          DialogueId = 10034107,
          FinalCamera = "-106.066406,611.137695,77.603516,0.000154,8.004599,-92.39566,35.000008,100000.0,false,Manual,22.0",
          GUID = "191E8CAE",
          LookAt = {
            [1] = "100001:p(Point04)",
            [2] = "200021:p(Point04)"
          },
          NextDialogue = 10034108,
          Scripts = "PARA{MoveTo{ActorId{100001},TargetPoint{\"Point03\"},MoveSpeed{80},Visibility{\"Show\"}},SetLocation{ActorId{200002},TargetPoint{\"Point02\"},Visibility{\"Hide\"}}}",
          SpeakNpcId = 200021,
          Subtitle = "Take a look at this.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8CAE"
        },
        [10034108] = {
          Camera = "-113.304688,236.751953,107.111328,0.000155,-26.791348,130.790771,30.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Pourquoi y a-t-il autant de lampes de mineur et de pioches dans une ancienne salle de maintenance ?",
          DialogueId = 10034108,
          FinalCamera = "-113.304688,236.751953,107.111328,0.000152,-33.191277,130.190399,30.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191E8CD8",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10034109,
          SpeakNpcId = 100001,
          Subtitle = "Why are there so many mining lamps and pickaxes in an abandoned maintenance room?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8CD8"
        },
        [10034109] = {
          Camera = "99.867188,416.986328,118.638672,0.000182,3.20773,-139.803497,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "À la fin de l’exploitation de la Fosse de Glevum, les mineurs craignaient pour leur avenir. Certains ont discrètement emporté du matériel pour le revendre ailleurs.",
          DialogueId = 10034109,
          FinalCamera = "107.375,408.098633,118.638672,0.000182,3.607713,-142.203781,35.000011,100000.0,false,Manual,22.0",
          GUID = "191E8D02",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10034110,
          SpeakNpcId = 200021,
          Subtitle = "Back when the Glevum Pit was running dry, miners started swiping gear to sell elsewhere, out of fear of losing their livelihood.",
          TalkActionId = {
            [1] = "200021:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8D02"
        },
        [10034110] = {
          Camera = "-27.976562,359.482422,156.25,0.00017,-1.390585,-141.406723,30.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Cet endroit devait être l’une de leurs caches. Rhythm l’a sans doute découverte plus tard et transformée en base secrète. Mais ce n’est pas ça que je voulais vous montrer.",
          DialogueId = 10034110,
          FinalCamera = "-16.988281,344.918945,156.25,0.000169,-1.590608,-147.206284,30.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191E8D2C",
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-178.03125,-58.620117,217.142578,-0.000061,-16.397821,77.969307,30.000002,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-178.03125,-58.620117,217.142578,-0.00006,-14.397696,77.768784,30.000002,100000.0,false,DoNotOverride,22.0\"},duration{5}}},LookAt{_delay{5},LookAtDescription{\"200021:p(Point04)\"}}}",
          SpeakNpcId = 200021,
          Subtitle = "This place must've been one of their stashes. Rhythm probably stumbled upon it later and turned it into a secret base. But that's not what I wanted to show you.",
          TalkActionId = {
            [1] = "100001:Talk03_End",
            [2] = "200021:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100341/191E8D2C"
        },
        [10034111] = {
          ContentFR = "Une boîte simple, ornée d’un nœud de ruban maladroit, posée à côté d’une fiole du meilleur analgésique impérial. À côté, une carte non glissée dans le paquet :\n« Rétablis-toi vite. »",
          DialogueId = 10034111,
          GUID = "191E8D56",
          Subtitle = "A plain gift box with a clumsily made ribbon bow, accompanied by a bottle of the Empire's finest painkiller. Next to it is an unsent note that reads: \"Get well soon.\"",
          VoiceName = "voice/$Locale$/story/1003/100341/191E8D56"
        },
        [10034201] = {
          Camera = "219.984375,651.333008,126.039062,0.000189,-0.595449,-128.390549,35.000008,527.224426,false,Manual,2.038203",
          ContentFR = "Je me demandais qui était le génie qui avait envoyé des antidouleurs à quelqu’un dans le coma. Maintenant, ça a du sens, seul Rhythm aurait eu une idée pareille...",
          DialogueId = 10034201,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "226.792969,645.869141,126.039062,0.000189,-0.795451,-129.390228,35.000008,527.224426,false,Manual,2.038203",
          GUID = "191E9C1A",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10034202,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405005,
            [3] = 201011,
            [4] = 201024
          },
          Scripts = "PARA{SetLocation{ActorId{100001},TargetPoint{\"Point03\"},Visibility{\"Show\"}},SetLocation{ActorId{200002},TargetPoint{\"Point02\"},Visibility{\"Hide\"}}}",
          SpeakNpcId = 200021,
          Subtitle = "I was wondering who the genius was that sent painkillers to someone in a coma. Now it makes sense — that's so Rhythm.",
          TalkActionId = {
            [1] = "200021:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9C1A"
        },
        [10034202] = {
          Camera = "6.648438,363.008789,131.244141,0.000182,3.603758,-146.77739,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentFR = "Bref, voilà tout ce que j’ai trouvé. Et vous ? Le sceau ?",
          DialogueId = 10034202,
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "13.488281,352.691406,131.244141,0.000182,3.603758,-149.576935,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9C44",
          NextDialogue = 10034203,
          SpeakNpcId = 200021,
          Subtitle = "Anyway, this is all I've found so far. What about you? Found the seal yet?",
          TalkActionId = {
            [1] = "200021:ScratchHead_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200021:p(-20)"
          },
          VoiceName = "voice/$Locale$/story/1003/100342/191E9C44"
        },
        [10034203] = {
          Camera = "-275.664062,320.675781,156.072266,0.000189,-3.796267,-32.382538,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentFR = "Pas encore. Mais j’ai découvert autre chose...",
          DialogueId = 10034203,
          FinalCamera = "-271.5625,327.202148,156.072266,0.000189,-3.796267,-35.982929,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9C6E",
          NextDialogue = 10034204,
          SpeakNpcId = 100001,
          Subtitle = "Not yet. But I've learned something else...",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9C6E"
        },
        [10034204] = {
          Camera = "-106.195312,289.816406,169.058594,0.000185,-23.795893,-51.580635,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentFR = "Quand Rhythm était enfant, ses parents ont été tués par un Dégradé. Et ce même Dégradé a pris la vie de nombreuses autres personnes.",
          DialogueId = 10034204,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "-101.417969,293.541992,169.058594,0.000177,-23.795885,-56.380722,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9C98",
          NextDialogue = 10034205,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-91.234375,264.868164,130.25,0.000933,-24.992582,92.009041,35.000008,527.224426,false,DoNotOverride,2.038203\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-100.582031,264.547852,130.25,0.000933,-24.992582,92.009041,35.000008,527.224426,false,DoNotOverride,2.038203\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "When Rhythm was young... her parents were killed by a Filthoid. That same Filthoid took the lives of so many others.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9C98"
        },
        [10034205] = {
          ContentFR = "Le Souillé est extrêmement dangereux. Même s’il a cessé d’attaquer, il pourrait simplement être en sommeil. Allez vite vous réfugier dans la cité. Les Veilleurs se chargeront du reste.",
          DialogueId = 10034205,
          GUID = "191E9CC2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10031809.T_Story_Recall_10031809'",
          NextDialogue = 10034206,
          SpeakNpcId = 100304,
          Subtitle = "The Filthoid is highly dangerous. Although it's ceased attacking, it may only be in temporary dormancy. Return to the city immediately — the Escort will take it from here.",
          VoiceName = "voice/$Locale$/story/1003/100342/191E9CC2"
        },
        [10034206] = {
          ContentFR = "Protéger les civils... c’est mon devoir... tant que vous êtes en sécurité...",
          DialogueId = 10034206,
          GUID = "191E9CEC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10034206.T_Story_Recall_10034206'",
          NextDialogue = 10034207,
          SpeakNpcId = 100304,
          Subtitle = "...Protecting civilians is my duty... as long as... you're all safe...",
          VoiceName = "voice/$Locale$/story/1003/100342/191E9CEC"
        },
        [10034207] = {
          Camera = "-83.59375,619.290039,74.404297,0.000918,8.607185,-95.991829,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentFR = "Elle ne veut plus jamais voir quelqu’un mourir d’un Souillé. Peut-être que c’est ça qui l’a poussée à rejoindre les Veilleurs.",
          DialogueId = 10034207,
          FinalCamera = "-65.59375,616.701172,74.404297,0.000924,8.607192,-98.191681,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9D16",
          NextDialogue = 10034208,
