          FinalCamera = "-250.34375,290.249023,178.650391,0.000827,-14.39187,-22.798668,35.000011,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9E12",
          NextDialogue = 10034214,
          SpeakNpcId = 100001,
          Subtitle = "What I truly hate is the incurable Deterioration and the gnawing helplessness back then.",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9E12"
        },
        [10034214] = {
          Camera = "-99.214844,448.524414,117.580078,0.000858,7.807739,-110.798241,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentFR = "Personne n’est coupable de ce qui est arrivé à Psyche. Si quelqu’un doit être maudit, c’est bien ce monde tordu.",
          DialogueId = 10034214,
          FinalCamera = "-89.992188,445.055664,117.580078,0.000856,7.807739,-113.997963,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9E3C",
          NextDialogue = 10034219,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-44.121094,598.605469,88.085938,0.000868,6.607477,-102.801109,35.000008,527.224426,false,DoNotOverride,2.038203\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-39.066406,621.015625,85.417969,0.000871,6.807472,-103.001343,35.000008,527.224426,false,DoNotOverride,2.038203\"},duration{5}}},PlayAnimation{_delay{3},ActorId{200021},AnimationId{\"ConfidentLRToTalk01_End\"},Duration{2}}}",
          SpeakNpcId = 200021,
          Subtitle = "Nobody's at fault for what happened to Psyche. If anything is to be blamed, it's this broken world we live in.",
          TalkActionId = {
            [1] = "200021:ConfidentLRToTalk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9E3C"
        },
        [10034215] = {
          ContentFR = "<I>Non... je n’y arrive pas encore.</>",
          DialogueId = 10034215,
          GUID = "191E9E66",
          NextDialogue = 10034216,
          Subtitle = "No... I still can't get over it."
        },
        [10034216] = {
          Camera = "31.164062,344.773438,103.396484,0.000867,11.206885,-154.599243,35.000011,527.224426,false,DoNotOverride,2.038203",
          ContentFR = "Je comprends. Certaines blessures sont trop profondes pour guérir. Ce n’est pas quelque chose que tu peux simplement balayer d’un simple \"on oublie ça\".",
          DialogueId = 10034216,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          FinalCamera = "35.367188,335.894531,103.396484,0.000868,11.206885,-157.59964,35.000011,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9E90",
          NextDialogue = 10034217,
          SpeakNpcId = 200021,
          Subtitle = "I get it. Some wounds run too deep to heal. It's not something you can just brush off with a simple \"forget it.\"",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9E90"
