        [10034217] = {
          Camera = "-64.0625,325.602539,167.652344,0.000887,-56.191696,118.603279,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentFR = "C’est normal de ne pas pardonner. Tu n’as pas à te forcer.",
          DialogueId = 10034217,
          FinalCamera = "-70.183594,322.261719,167.652344,0.000858,-55.591667,110.602448,35.000008,527.224426,false,DoNotOverride,2.038203",
          GUID = "191E9EBA",
          NextDialogue = 10034218,
          SpeakNpcId = 200021,
          Subtitle = "It's okay not to forgive. You don't have to force yourself to.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100342/191E9EBA"
        },
        [10034218] = {
          Camera = "88.582031,354.351562,113.285156,0.000858,5.408526,-148.789658,35.000008,527.224426,false,DoNotOverride,2.038203",
          ContentFR = "Une fois que cette histoire de \"Traque aux Charons\" sera terminée, et qu’elle t’aura aidé à recueillir des informations sur Berenica, tu pourras rompre les liens avec elle et ne plus jamais la revoir.",
