        },
        [10034407] = {
          ContentFR = "L’Académie d’Alchimie, le Conseil et le QG de la VIᵉ Légion sont tous là-bas. Ça peut être pour la logistique, de la politique, un rapport à rendre... ou même une vieille connaissance.",
          DialogueId = 10034407,
          GUID = "191EBE10",
          NextDialogue = 10034408,
          SpeakNpcId = 200021,
          Subtitle = "The Alchemy Academy, the Council Hall, and the 6th Legion's HQ are all there. Could be anything — logistics, politics, questioning, or maybe just catching up with someone.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE10"
        },
        [10034408] = {
          ContentFR = "Quoi qu’il en soit, ça ne nous regarde pas. Un de mes principes de survie : moins tu poses de questions, plus tu vis longtemps.",
          DialogueId = 10034408,
          GUID = "191EBE3A",
          SpeakNpcId = 200021,
          Subtitle = "None of it concerns us. One of my life rules is — the less you ask, the longer you live.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3A"
        },
        [10034410] = {
          ContentFR = "C’est bien ici qu’on doit récupérer la cargaison, non ? Ouah— ! Mais... pourquoi y a-t-il des loups des neiges ici !?",
          DialogueId = 10034410,
          GUID = "191EBE64",
          NextDialogue = 10034411,
          SpeakNpcId = 200002,
          Subtitle = "This must be the pickup spot! Whoa—! Why are there snow wolves here!?",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE64"
        },
        [10034411] = {
          ContentFR = "Vous êtes bien l’escouade locale dont a parlé le Major Lynn ? La marchandise n’est pas encore arrivée. En attendant, aidez-moi à nettoyer la zone.",
          DialogueId = 10034411,
          GUID = "191EBE8E",
          NextDialogue = 10034412,
          SpeakNpcId = 100310,
          Subtitle = "You're the local squad Major Lynn sent, right? The shipment hasn't arrived yet. While we wait, help me clear out this area.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE8E"
        },
        [10034412] = {
          ContentFR = "<I>Soupir... Génial. Encore une corvée.</>",
          DialogueId = 10034412,
          GUID = "191EBEB8",
          SpeakNpcId = 200021,
          Subtitle = "*sigh* Great... another chore on the pile.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBEB8"
        },
        [10034413] = {
          ContentFR = "Sécurisez le périmètre, maintenant !",
          DialogueId = 10034413,
          GUID = "191EBE3B",
          Subtitle = "Secure the perimeter — now!",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3B"
        },
        [10034414] = {
          ContentFR = "Givrelac est sous couvre-feu. Sans permis, pas de déplacements.",
          DialogueId = 10034414,
          GUID = "191EBE3C",
          Subtitle = "Icelake's under curfew. No movement without a permit.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3C"
        },
        [10034415] = {
          ContentFR = "On aura terminé l’affaire avant la Fête de la Chandelle d’Argent. Laissez donc ces décorations où elles sont.",
          DialogueId = 10034415,
          GUID = "191EBE3D",
          Subtitle = "We'll be done before the Silvercandle Carnival. Just leave the gaudy decorations where they are.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3D"
        },
        [10034416] = {
          ContentFR = "Test com radio. Un, deux, trois... Un, deux, trois. Vous me recevez ? Parfait, c’est clair ici aussi.",
          DialogueId = 10034416,
          GUID = "191EBE3E",
          Subtitle = "Comms check — one, two... one, two. Can you hear me? Good — loud and clear on my end too.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE3E"
        },
        [10034417] = {
          ContentFR = "On appelle ça un couvre-feu... mais pourquoi nous enfermer aussi en plein jour ?",
          DialogueId = 10034417,
          GUID = "191EBE40",
          Subtitle = "If it's called a curfew, why aren't we allowed to go out during the day either?",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE40"
        },
        [10034418] = {
          ContentFR = "Merde... Cette cargaison d’Épinegivres frais va pourrir, impossible de les écouler.",
          DialogueId = 10034418,
          GUID = "191EBE41",
          Subtitle = "Damn it, these fresh Frostspines are going to go to waste.",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE41"
        },
        [10034419] = {
          ContentFR = "Ah, ma tendre bien-aimée... Nuit cruelle où je reste seul à mon oreiller glacé. Deux rues à peine nous séparent, et pourtant, je ne puis vous rejoindre...",
          DialogueId = 10034419,
          GUID = "191EBE42",
          Subtitle = "Ah, my dearest lady, this sleepless night finds me alone with a cold pillow—though merely two streets apart, we remain cruelly divided...",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE42"
        },
        [10034420] = {
          ContentFR = "Pitié, monsieur l’officier... Je dois aller travailler, sinon ma famille va mourir de faim...",
          DialogueId = 10034420,
          GUID = "191EBE43",
          Subtitle = "Please, sir, let me go. I need to go to work. I got a family to raise...",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE43"
        },
        [10034421] = {
          ContentFR = "Encore toi ?! Fais gaffe, à ce rythme un officier va t’envoyer, toi et toute ta famille, derrière les barreaux !",
          DialogueId = 10034421,
          GUID = "191EBE44",
          Subtitle = "You again?! Watch it—one more word, and the officer will have your whole family behind bars!",
          VoiceName = "voice/$Locale$/story/1003/100344/191EBE44"
        },
        [10034501] = {
