        [10034517] = {
          Camera = "288.396484,340.865479,272.666504,0.000028,-21.39267,-98.97049,20.0,100000.0,false,Manual,22.0",
          ContentFR = "Le suspect de la \"Traque aux Charons\" que vous avez laissé filer s’est réfugié dans la cité intérieure. Il a massacré des sujets de Sa Majesté et recouvert les murs de graffitis haineux contre les Solariens... Si ce n’est pas de l’incompétence, ça y ressemble fort !",
          DialogueId = 10034517,
          FinalCamera = "306.296875,337.759277,272.666504,0.000026,-20.792625,-100.170906,20.000008,100000.0,false,Manual,22.0",
          GUID = "191ECFF2",
          NextDialogue = 10034518,
          Scripts = [[
PARA{
PlayAnimation{_delay{4},ActorId{100001},AnimationId{"ScratchHead_Start"},Duration{1}},
PlayAnimation{_delay{1},ActorId{200021},AnimationId{"Talk03_Start"},Duration{1}},
PlayAnimation{_delay{8},ActorId{100001},AnimationId{"ScratchHead_End"},Duration{1}},
}]],
          SpeakNpcId = 100310,
          Subtitle = "The \"Charon Hunt\" perp you failed to catch made it to the inner city. They killed His Majesty's loyal subjects and defaced the place with anti-Solarian graffiti. If that's not negligence, I don't know what is!",
          TalkActionId = {
            [1] = "100310:Talk01_Start",
            [2] = [[

100304:Explain02_End]]
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1003/100345/191ECFF2"
        },
        [10034518] = {
          Camera = "365.872009,5.727009,151.48291,5.003078,-8.593204,-140.975723,20.000011,100000.0,false,Manual,22.0",
          ContentFR = "Le couvre-feu n’est pas seulement pour l’attraper, mais aussi pour étouffer l’affaire. Si jamais ça s’ébruitait que des Solariens ont été tués par un Souillé en pleine cité intérieure, vous passeriez tous en cour martiale !",
          DialogueId = 10034518,
          FinalCamera = "365.872009,5.727009,156.694824,5.00317,-9.193209,-141.574554,20.000011,100000.0,false,Manual,22.0",
          GUID = "191ED01C",
          NextDialogue = 10034519,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100310},AnimationId{"Talk01_End"},Duration{1}},
PlayAnimation{_delay{4},ActorId{100310},AnimationId{"Disagree"},Duration{1}},
PlayAnimation{_delay{3},ActorId{100310},AnimationId{"Angry01_Start"},Duration{1}},
}]],
          SpeakNpcId = 100310,
          Subtitle = "The lockdown isn't just about catching the perp — it's also to keep the news under wraps. If word got out that Solas were killed by a monster in the inner city, you'd all be facing court-martial!",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 12.5,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED01C"
        },
        [10034519] = {
          Camera = "301.061676,-90.123116,187.39209,0.000131,-17.79336,-7.569943,32.000004,95.417534,false,Manual,3.0",
          ContentFR = "Ah... voilà donc pourquoi la XIIIᵉ Légion a rappliqué de si loin. « Pour la sécurité de Givrelac », qu’ils disaient... en vrai, c’est juste que <H>des nobles Solariens de la cité intérieure se sont fait descendre</>...",
          DialogueId = 10034519,
          FinalCamera = "301.061676,-90.123116,187.39209,0.000132,-17.393343,-7.56995,36.0,95.417534,false,Manual,3.0",
          GUID = "191ED046",
          NextDialogue = 10034520,
          SpeakNpcId = 200021,
          Subtitle = "Ah, so that's why the 13th Legion came all the way here — giving it all that \"protecting Icelake\" cobblers. Turns out some inner city noble Solas were killed by that monster...",
          TalkActionId = {
            [1] = "200021:Talk03ToThink_Start",
            [2] = [[

100310:Angry01_End]]
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED046"
        },
        [10034520] = {
          Camera = "23.424326,-134.963486,195.653564,0.000198,-14.392178,9.874047,25.000006,342.602386,false,Manual,3.0",
          ContentFR = "C’est ma faute, et j’accepte d’en répondre. Mais avant toute sanction, je vous en prie : permettez-moi de continuer l’enquête, afin de réparer mes erreurs.",
          DialogueId = 10034520,
          FacialId = {
            [1] = "100304:Unhappy01"
          },
          FinalCamera = "23.508778,-135.479782,199.127441,0.000201,-16.392166,9.87375,25.000006,342.602386,false,Manual,3.0",
          GUID = "191ED070",
          LookAt = {
            [1] = "100001:n(100304)",
            [2] = [[

200021:n(100304)]],
            [3] = [[

100304:n(100310)]]
          },
          NextOptions = {
            [1] = 10034521,
            [2] = 10034522
          },
          SpeakNpcId = 100304,
          Subtitle = "This occurred as a result of my negligence, and I'm willing to accept the consequences. But please, allow me to assist in the investigation and make amends.",
          TalkActionId = {
            [1] = "200021:Talk03ToThink_End",
            [2] = [[

100304:Explain02_Start]]
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED070"
        },
        [10034521] = {
          ContentFR = "<I>Ce n’est pas votre faute. Ne portez pas la responsabilité des autres.</>",
          DialogueId = 10034521,
          GUID = "191ED09A",
          ImprPlusId = 1007,
          NextDialogue = 10034523,
          Subtitle = "It's not your fault. Don't take the blame for others."
        },
        [10034522] = {
          ContentFR = "<I>Rester {性别:silencieux|silencieuse}</>",
          DialogueId = 10034522,
          GUID = "191ED0C4",
          ImprPlusId = 1016,
          NextDialogue = 10034523,
          Subtitle = "(Stay silent.)"
        },
        [10034523] = {
          Camera = "411.256287,27.705805,132.101562,0.0002,4.006999,-150.270157,45.000023,100000.0,false,Manual,22.0",
          ContentFR = "Assez. C’est au tribunal militaire de décider qui doit être puni. Tant que le Major Lynn n’a pas ordonné votre arrestation, contentez-vous de faire votre travail.",
          DialogueId = 10034523,
          FinalCamera = "412.643616,25.277588,132.101562,0.0002,4.006999,-150.270157,45.000023,100000.0,false,Manual,22.0",
          GUID = "191ED0EE",
          NextDialogue = 10034524,
          SpeakNpcId = 100310,
          Subtitle = "Save it. Who faces the penalty is for the military court to decide. If Major Lynn hasn't ordered your arrest, then just focus on doing your job.",
          TalkActionId = {
            [1] = "100304:Explain02_End",
            [2] = [[

100310:Confident_Start]]
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED0EE"
        },
        [10034524] = {
          Camera = "225.765671,-92.916252,144.391113,0.00002,-3.793917,21.826767,35.000011,92.421875,false,Manual,3.0",
          ContentFR = "À vos ordres !",
          DialogueId = 10034524,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          GUID = "191ED118",
          NextDialogue = 10034525,
          SpeakNpcId = 100304,
          Subtitle = "Yes, sir!",
          TalkActionId = {
            [1] = "100310:Confident_End",
            [2] = [[

100304:AgreeHead]]
          },
          TurnTo = {
            [1] = "200002:n(200021)"
          },
          VoiceName = "voice/$Locale$/story/1003/100345/191ED118"
        },
        [10034525] = {
          Camera = "252.645859,119.817787,133.437744,0.00002,-0.393521,-57.958469,25.000006,100000.0,false,Manual,22.0",
          ContentFR = "Je vous ai entraînés là-dedans... Je suis désolée.",
          DialogueId = 10034525,
          FacialId = {
            [1] = "100304:Disappoint01"
          },
          FinalCamera = "249.932739,118.11982,133.437744,0.00002,-0.393521,-57.558506,25.000006,100000.0,false,Manual,22.0",
          GUID = "191ED142",
          NextDialogue = 10034526,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"100304:n(100001)"}},
PlayAnimation{_delay{0.5},ActorId{100304},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 100304,
          Subtitle = "I'm sorry for dragging you all into this...",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED142"
        },
        [10034526] = {
          Camera = "123.6875,-318.221191,262.880859,0.00012,-23.791746,51.848705,20.000008,100000.0,false,Manual,22.0",
          ContentFR = "Stop. Pas la peine de sortir ce genre de discours plombants. Allez, on a du pain sur la planche pour les prochains jours.",
          DialogueId = 10034526,
          FinalCamera = "123.6875,-318.221191,267.053223,0.000114,-24.391724,51.849072,20.000008,100000.0,false,Manual,22.0",
          GUID = "191ED16C",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          Scripts = "TurnTo{_delay{1.5},TurnToDescription{\"100304:n(200021)\"}},",
          SpeakNpcId = 200021,
          Subtitle = "Uh-uh. Enough with the downer talk. Let's move — we've got our hands full for the next few days.",
          TalkActionId = {
            [1] = "100304:Talk02_End",
            [2] = [[

200021:Talk03ToTalkL_Start]]
          },
          ToFinalCameraBlendTime = 6.5,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED16C"
        },
        [10034527] = {
          ContentFR = "Deux jours plus tard",
          DialogueId = 10034527,
          GUID = "191ED196",
          Subtitle = "Two days later",
          VoiceName = "voice/$Locale$/story/1003/100345/191ED196"
        },
        [10034528] = {
          Camera = "387.177704,-477.28363,251.621094,0.000037,-18.800491,96.200485,35.000011,544.895874,false,Manual,22.0",
          ContentFR = "Quoi !? Rhythm a vraiment terminé cette énorme liste de tâches toute seule !? Bon sang, qu’est-ce qu’elle est, un chien de traîneau ?",
          DialogueId = 10034528,
          FinalCamera = "379.26709,-408.699371,228.950928,0.000039,-18.000458,96.800278,35.000011,544.895874,false,Manual,22.0",
          GUID = "191ED1C0",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(200021)",
            [3] = "100001:n(200021)"
          },
          NextDialogue = 10034529,
          SpeakNpcId = 200021,
          Subtitle = "Ooh, Rhythm actually finished that massive task list on her own!? Geeze, what is she, a sled dog?",
          TalkActionId = {
            [1] = "200021:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "200002:n(200021)"
          },
          VoiceName = "voice/$Locale$/story/1003/100345/191ED1C0"
        },
        [10034529] = {
          Camera = "76.509949,95.736488,35.371094,0.000062,15.598738,-23.400145,35.000011,544.895874,false,DoNotOverride,22",
          ContentFR = "Hé, on a quand même beaucoup aidé nous aussi !",
          DialogueId = 10034529,
          GUID = "191ED1EA",
          LookAt = {
            [1] = "200021:n(200002)",
            [2] = "200002:n(200021)",
            [3] = "100001:n(200002)"
          },
          NextDialogue = 10034530,
          SpeakNpcId = 200002,
          Subtitle = "Hey! We helped a lot too!",
          TalkActionId = {
            [1] = "200002:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100345/191ED1EA"
        },
        [10034530] = {
          Camera = "313.703003,-7.806791,124.205078,0.000106,14.197558,-47.393547,35.000015,116.556152,false,Manual,4.0",
          ContentFR = "Ah oui ? Tu veux dire quand tu as fait exploser la caisse de munitions en la portant, ou quand tu as pété la vanne en réparant la conduite d’eau, et qu’on a dû tout refaire à zéro ?",
          DialogueId = 10034530,
          FacialId = {
            [1] = "200021:Unhappy02"
          },
          GUID = "191ED214",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(200021)",
            [3] = "100001:n(200021)"
          },
          NextDialogue = 10034531,
          SpeakNpcId = 200021,
          Subtitle = "Oh yeah? You mean like setting off that ammo box you were supposed to carry, or breaking the sluice gate while patching up the pipes?",
          TalkActionId = {
            [1] = "200021:Talk02_End",
            [2] = "200002:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100345/191ED214"
        },
        [10034531] = {
          Camera = "426.979126,-187.174683,184.529053,0.000142,-24.601282,121.190933,35.000019,348.247833,false,Manual,2.8",
          ContentFR = "Euh... c’étaient des accidents, des accidents ! De simples maladresses, rien de plus !",
          DialogueId = 10034531,
          FacialId = {
            [1] = "200002:Syouganai01"
          },
          GUID = "191ED23E",
          LookAt = {
            [1] = "200021:n(200002)",
            [2] = "200002:n(200002)",
            [3] = "100001:n(200002)"
          },
          NextDialogue = 10034532,
          SpeakNpcId = 200002,
          Subtitle = "Uh... those were accidents! Just a few innocent mistakes!",
          TalkActionId = {
            [1] = "200002:ScratchHead_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100345/191ED23E"
        },
        [10034532] = {
          Camera = "379.26709,-408.699371,228.950928,0.000039,-18.000458,96.800278,35.000011,544.895874,false,Manual,22.0",
          ContentFR = "Au fait... où est Rhythm ? D’habitude, à cette heure, elle nous attend déjà au parking.",
          DialogueId = 10034532,
          FacialId = {
            [1] = "200021:None",
            [2] = "200002:None"
          },
          GUID = "191ED268",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(100001)",
            [3] = "100001:n(200021)"
          },
          NextDialogue = 10034533,
          SpeakNpcId = 100001,
          Subtitle = "Speaking of Rhythm — where is she? She's usually waiting for us at the parking lot by now.",
          TalkActionId = {
            [1] = "200002:ScratchHead_End",
            [2] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100345/191ED268"
        },
        [10034533] = {
          ContentFR = "C’est vrai. Elle ne change jamais ni l’endroit ni la posture où elle nous attend.",
          DialogueId = 10034533,
          GUID = "191ED292",
          LookAt = {
            [1] = "200021:n(200021)",
            [2] = "200002:n(200021)",
            [3] = "100001:n(200021)"
          },
          NextDialogue = 10034534,
          SpeakNpcId = 200021,
          Subtitle = "Right. She doesn't even change the spot and posture she waits for us in every day.",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "200021:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100345/191ED292"
        },
        [10034534] = {
          Camera = "240.401016,109.887741,127.815674,0.00013,3.595767,-46.793732,35.000011,296.605652,false,Manual,4.0",
          ContentFR = "Si une personne aussi rigide change ses habitudes, c’est qu’il s’est passé quelque chose. Allons fouiller les environs.",
          DialogueId = 10034534,
          GUID = "191ED2BC",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(200021)",
            [3] = "100001:n(200021)"
          },
          SpeakNpcId = 200021,
          Subtitle = "If such a rigid character is out of place, something must've come up. Let's look around.",
          VoiceName = "voice/$Locale$/story/1003/100345/191ED2BC"
        },
        [10034535] = {
          Camera = "313.962891,-339.905273,217.369629,0.000059,-19.399368,135.380035,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Oh, encore une liste ? Ne me dites pas que la Légion vous a encore refilé du boulot.",
          DialogueId = 10034535,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "313.962891,-339.905273,217.369629,0.000063,-13.999196,135.380676,35.000008,100000.0,false,Manual,22.0",
          GUID = "191ED2E6",
          NextDialogue = 10034536,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405005,
            [3] = 201011,
            [4] = 201024
          },
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{4},TargetPosition{\"26.724609,6.107422,129.455078,0.000083,-6.000642,155.993042,24.0,100000.0,false,Manual,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"14.828125,11.506348,128.541504,0.000083,-4.000551,155.593628,24.0,100000.0,false,Manual,22.0\"},duration{8}}},PlayAnimation{_delay{3},ActorId{200021},AnimationId{\"ConfidentLRToExplainR_Start\"},Duration{2}}}",
          SpeakNpcId = 200021,
          Subtitle = "Whoa, you've got another list? Don't tell me the Legion dumped more work on you.",
          TalkActionId = {
            [1] = "200021:ConfidentLR_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED2E6"
        },
        [10034536] = {
          Camera = "-341.650391,-20.949707,145.34668,0.000154,-6.197078,11.655313,35.000015,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Non. C’est un inventaire que j’ai établi moi-même. Depuis que la XIIIᵉ Légion a pris en charge cette affaire, les déplacements des citoyens sont devenus encore plus compliqués. Surtout à Brumelac, où les vivres manquent déjà cruellement.\nAlors... j’ai pensé qu’apporter un peu de provisions pourrait au moins aider.",
          DialogueId = 10034536,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "-325.760742,-56.51709,144.594238,0.000154,-5.997029,18.256239,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191ED310",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10034537,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-132.125977,37.652344,136.237793,0.000147,-3.197143,9.206694,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-127.595703,16.415039,136.237793,0.000146,-3.197109,18.007582,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{8}}},PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Talk03_End\"},Duration{2}},PlayAnimation{_delay{4},ActorId{200021},AnimationId{\"ConfidentLR_End\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "No, this is a supply list I put together. Ever since the 13th Legion took over the case, it's been harder for citizens to get around, especially in Mist Aken, where food supplies were already scarce. I thought I could at least help by delivering some essentials.",
          TalkActionId = {
            [1] = "100304:Talk03_Start",
            [2] = "200021:ConfidentLRToExplainR_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED310"
        },
        [10034537] = {
          Camera = "64.092773,19.856934,138.348145,0.000255,-4.402309,155.469559,30.000002,198.150391,false,Manual,2.669626",
          ContentFR = "Vous ne savez vraiment pas rester tranquille, hein ? Stop, je vois venir votre sempiternel « C’est mon devoir ».",
          DialogueId = 10034537,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "59.726562,11.441406,138.348145,0.000256,-4.202267,153.069778,30.000002,198.150391,false,Manual,2.669626",
          GUID = "191ED33A",
          LookAt = {
            [1] = "100001:n(100304)",
            [2] = "200021:n(100304)"
          },
          NextOptions = {
            [1] = 10034538,
            [2] = 10034541
          },
          SpeakNpcId = 200021,
          Subtitle = "Wow, you sure don't know how to take it easy, do you? I know, I know, save the \"It's my duty\" speech this time.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED33A"
        },
        [10034538] = {
          ContentFR = "<I>Aidons-la, nous aussi.</>",
          DialogueId = 10034538,
          GUID = "191ED364",
          ImprPlusId = 1007,
          NextDialogue = 10034539,
          Subtitle = "Let us help you."
        },
        [10034539] = {
          Camera = "-145.116211,-92.38623,122.953613,0.000255,0.797418,50.270557,35.000008,198.150391,false,DoNotOverride,2.669626",
          ContentFR = "Je... Merci. Je veux dire... désolée de vous déranger.",
          DialogueId = 10034539,
          FacialId = {
            [1] = "100304:Disappoint01"
          },
          FinalCamera = "-141.902344,-95.058105,122.953613,0.000255,0.997412,51.070686,35.000008,198.150391,false,DoNotOverride,2.669626",
          GUID = "191ED38E",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10034540,
          Scripts = "PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Sigh_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "You don't have to... I mean, thank you.",
          TalkActionId = {
            [1] = "100304:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100345/191ED38E"
        },
        [10034540] = {
          Camera = "275.59668,-135.068359,262.251953,0.000129,-23.202957,151.422806,35.000015,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Voilà qui est mieux. Après tout, nous avons traversé beaucoup de choses ensemble.",
          DialogueId = 10034540,
          FacialId = {
            [1] = "200021:Ahaha01",
            [2] = "100304:Sad01"
          },
          FinalCamera = "241.146484,-116.370117,245.611328,0.000129,-23.002949,151.8228,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "191ED3B8",
          NextDialogue = 10034545,
          SpeakNpcId = 200021,
          Subtitle = "That's more like it. After all, we've been through a lot together.",
          TalkActionId = {
            [1] = "200021:Talk03_End"
