        [10034546] = {
          Camera = "-12.336914,-66.583008,102.745605,0.000291,-9.999444,-97.554825,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Ouah ! De la pêche ?! Moi aussi je veux pêcher, moi aussi, moi aussi !",
          DialogueId = 10034546,
          FacialId = {
            [1] = "200002:Smile02"
