        [10034805] = {
          Camera = "-700.760254,-1834.15918,893.505981,0.003529,36.610516,-63.616196,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Mais cette couronne de fleurs... J’ai l’impression de l’avoir déjà vue quelque part...",
          DialogueId = 10034805,
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          FinalCamera = "-457.949707,-1725.961914,893.492798,0.003537,35.610363,-72.81559,35.000008,100000.0,false,Manual,22.0",
          GUID = "191EFF32",
          NextDialogue = 10034806,
