        },
        [10034806] = {
          Camera = "224.45166,-85.673828,33.008545,-0.00122,6.987447,110.23822,30.000008,527.695984,false,Manual,1.685963",
          ContentFR = "Clive se serait-il trompé ? Cet endroit ressemble davantage à un refuge improvisé qu’à une planque de criminel.",
          DialogueId = 10034806,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "221.073242,-86.915039,33.008545,-0.00122,6.987447,110.23822,30.000008,527.695984,false,Manual,1.685963w",
          GUID = "191EFF5C",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "200021:n(100001)",
            [3] = "100304:n(100001)"
          },
          NextDialogue = 10034807,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-7.965332,353.811523,152.872192,3.600152,-27.811094,127.431259,30.000013,527.695984,false,DoNotOverride,1.685963\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-5.189941,355.878906,153.064331,3.600185,-27.811087,133.031097,30.000013,527.695984,false,DoNotOverride,1.685963\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "Could Clive have got it wrong? This place doesn't seem like a villain's base at all — more like a makeshift refuge cobbled together by a homeless guy.",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200002:Talk03_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100348/191EFF5C"
        },
        [10034807] = {
          Camera = "7.339355,240.246094,104.027344,0.000396,10.940474,76.79863,30.000008,1425.639404,false,DoNotOverride,1.2",
          ContentFR = "Je ne crois pas. Regarde bien, les murs sont couverts de traces de griffes, désordonnées et profondes. C’est très probablement le repaire de la créature.",
          DialogueId = 10034807,
          FacialId = {
            [1] = "200021:Confident01"
          },
          FinalCamera = "7.339355,240.246094,104.027344,0.000392,11.940454,76.398224,30.000008,1425.639404,false,DoNotOverride,1.2",
          GUID = "191EFF86",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "200021:n(200021)",
            [3] = "100304:n(100304)"
          },
          NextDialogue = 10034808,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-952.450195,-1160.222656,66.389648,0.00039,10.741585,129.016037,30.000002,1425.639404,false,Manual,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-966.062012,-1171.243164,66.389648,0.00039,10.741585,129.016037,30.000002,1425.639404,false,Manual,1.2\"},duration{5}}}",
          SpeakNpcId = 200021,
          Subtitle = "I don't think so. Look closer — there are claw marks all over the walls. This has to be the creature's hideout.",
          TalkActionId = {
            [1] = "200021:Explain01_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100348/191EFF86"
        },
        [10034808] = {
          Camera = "72.63623,-20.603516,49.855713,0.000414,10.338515,99.624138,50.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Hmm... Mais ce n’est pas ce que j’imaginais. Il y a même une sorte de... chaleur, presque comme un foyer.",
          DialogueId = 10034808,
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "64.187988,-22.094727,49.855713,0.00041,10.338522,97.824203,50.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191EFFB0",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "100001:n(100001)"
          },
          NextDialogue = 10034809,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-12.719727,330.859375,138.181396,0.000427,-5.060214,111.810959,30.000008,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-8.650391,332.382812,138.181396,0.000431,-5.060214,117.009903,30.000008,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "Right. But this isn't quite what I expected. It even feels... kind of like a cosy little home.",
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100348/191EFFB0"
        },
        [10034809] = {
          Camera = "-851.0,-3564.0,2678.0,0.000575,-32.462578,76.610298,40.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Quand nous étions enfants, Berry accrochait toujours des bandes de tissu colorées dans notre chambre. Elle disait que ça rendait l’endroit moins triste, moins vide.",
          DialogueId = 10034809,
          FinalCamera = "-851.0,-3564.0,2706.0,0.000575,-32.462578,76.610298,40.0,100000.0,false,DoNotOverride,22.0",
          GUID = "191EFFDA",
          LookAt = {
            [1] = "100001:p(fix31_4)",
            [2] = "100304:n(100001)"
          },
          NextDialogue = 10034810,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-506.869629,-167.307617,243.748657,-0.001007,-11.265167,46.788433,30.000008,800.491821,false,Manual,1.261124\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-493.358398,-179.537109,243.748657,-0.001007,-11.865192,48.388107,30.000008,800.491821,false,Manual,1.261124\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "When we were kids, Berry would hang colourful strips of cloth all around our home. She said it'd make the place feel warmer, and less lonely.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100348/191EFFDA"
        },
        [10034810] = {
          Camera = "18.089355,286.953125,108.440918,-0.00174,-21.568111,-73.964584,30.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "En y regardant de plus près, ils ont aménagé cet endroit de manière assez majestueuse ! Peut-être sont-ils les vrais Ducs des Égouts !",
          DialogueId = 10034810,
          FacialId = {
            [1] = "200002:Smile01"
          },
          FinalCamera = "22.338867,288.074219,108.440918,-0.00174,-21.568111,-76.764099,30.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "191F0004",
          NextDialogue = 10034811,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-1.92041,529.060547,193.301636,-0.001741,-23.567587,-85.957458,30.000013,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-14.425781,525.737305,192.27063,-0.00174,-23.367571,-80.557098,30.000013,100000.0,false,DoNotOverride,22.0\"},duration{5}}}",
          SpeakNpcId = 200002,
          Subtitle = "Upon a closer look, they've set this place up pretty majestically! Maybe they're the real Dukes of the Sewers!",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100001:n(200002)"
