        [10034813] = {
          Camera = "1.158203,334.078125,122.950684,-0.00177,4.227047,-0.062805,35.000023,427.577942,false,DoNotOverride,3.623266",
          ContentFR = "Très bien.",
          DialogueId = 10034813,
          FacialId = {
            [1] = "100304:Confident01"
          },
          GUID = "191F0082",
          SpeakNpcId = 100304,
          Subtitle = "Okay.",
          TalkActionId = {
            [1] = "100304:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100348/191F0082"
        },
        [10034814] = {
          ContentFR = "Un morceau de tissu ressemblant à du rideau de théâtre. Bien que vieux et usé, il est impeccablement propre, clairement entretenu avec soin. Un examen plus approfondi confirme qu’il correspond au tissu trouvé sur la scène de l’attaque.",
          DialogueId = 10034814,
          GUID = "191F00AC",
          Subtitle = "A piece of fabric resembling theatre curtain material. Though old and worn, it is impeccably clean — clearly maintained with care.\nA closer look confirms it matches the fabric found at the crime scene.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F00AC"
        },
        [10034815] = {
          ContentFR = "Malgré leur ancienneté, ils ont été disposés et habillés avec soin. Leur attitude évoque la grâce d’acteurs livrés à leur art.",
          DialogueId = 10034815,
          GUID = "191F00D6",
          Subtitle = "Though worn with age, the mannequin has clearly been posed and styled with care, exuding a graceful elegance, — like a performer lost in the moment on stage.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F00D6"
        },
        [10034816] = {
          ContentFR = "D’énormes marques, denses et chaotiques, gravées dans la pierre comme dans une transe de douleur et de folie.",
          DialogueId = 10034816,
          GUID = "191F0100",
          Subtitle = "Huge claw marks slash across the walls — dense, erratic, as if left in a frenzy of agony and madness.",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0100"
        },
        [10034817] = {
          Camera = "-470.862305,336.71875,225.989624,0.000123,-12.395741,-25.18132,31.654133,100000.0,false,Manual,22.0",
          ContentFR = "J’ai inspecté la zone inférieure. Rien d’anormal. Et de votre côté ?",
          DialogueId = 10034817,
          FinalCamera = "-470.862305,336.71875,205.012207,0.000122,-11.195704,-25.18092,31.654133,100000.0,false,Manual,22.0",
          GUID = "191F012A",
          LookAt = {
            [1] = "200021:n(100001)"
          },
          NextDialogue = 10034818,
          Scripts = [[
