        [10035209] = {
          ContentFR = "<I>C’est compliqué... Protéger les civils et obéir aux ordres, ce sont deux devoirs qui pèsent sur vous.</>",
          DialogueId = 10035209,
          GUID = "191F417A",
          ImprPlusId = 1007,
          NextDialogue = 10035210,
          Subtitle = "It's tough, isn't it? Protecting the people and following orders are both your duties."
        },
        [10035210] = {
          Camera = "-75.948898,-23.243881,162.542236,0.000282,-10.804621,24.274958,40.0,119.498253,false,Manual,8.0",
          ContentFR = "Je comprends ce que vous voulez dire... Il est temps que je fasse un choix.",
          DialogueId = 10035210,
          FacialId = {
            [1] = "100304:Close"
          },
          FinalCamera = "-77.361824,-20.11338,162.542236,0.000282,-10.404604,22.675148,40.0,119.498253,false,Manual,8.0",
          GUID = "191F41A4",
          NextDialogue = 10035215,
          SpeakNpcId = 100304,
          Subtitle = "I know what you mean... It's time I make my choice.",
          TalkActionId = {
            [1] = "100304:Sigh_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100352/191F41A4"
        },
        [10035211] = {
          ContentFR = "<I>Alors faites ce que votre cœur dicte.</>",
          DialogueId = 10035211,
          GUID = "191F41CE",
          ImprPlusId = 1009,
          NextDialogue = 10035212,
          Subtitle = "Just follow your heart."
        },
        [10035212] = {
          Camera = "-151.905182,-13.076996,141.362305,0.000255,-2.60461,19.078295,35.0,193.682495,false,Manual,8.0",
          ContentFR = "Soyez celle qui ne renonce jamais, celle qui se bat de toutes ses forces pour protéger les autres.",
          DialogueId = 10035212,
          FinalCamera = "-149.821655,-19.036041,141.362305,0.000255,-2.604604,19.478231,35.0,193.682495,false,Manual,8.0",
          GUID = "191F41F8",
          NextDialogue = 10035215,
          Scripts = [[
