PlayAnimation{ActorId{100001},AnimationId{"Angry01_End"},Duration{5}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Be who you are — someone who never gives up, who fights with everything she's got for what's right.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100352/191F41F8"
        },
        [10035213] = {
          ContentFR = "<I>Ils nous appellent quand ça les arrange, puis nous mettent dehors quand c’est fini. J’en ai ras-le-bol de cette XIIIᵉ Légion.</>",
          DialogueId = 10035213,
          GUID = "191F4222",
          ImprPlusId = 1010,
          NextDialogue = 10035214,
          Subtitle = "They summon us when it suits them and kick us out when they're done. I'm so fed up with this arrogant 13th Legion."
        },
        [10035214] = {
          Camera = "-123.919174,101.00631,136.338379,0.000344,0.994913,-34.304741,25.000002,207.074844,false,Manual,10.0",
          ContentFR = "Respire profondément, Capitaine. Ça n’en vaut pas la peine...",
