PlayAnimation{ActorId{100304},AnimationId{"DisagreeHead"},Duration{3}},
}
}
]],
          SpeakNpcId = 100304,
          Subtitle = "Was it out of a sense of duty? To protect the people? No... not really. I'm not that selfless. I just did all that to secure a decent life and a peace of mind.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1003/100352/191F42F4"
        },
        [10035219] = {
          Camera = "-7.093658,62.875187,145.726074,0.000396,-17.213251,-45.26133,31.000006,51.557377,false,Manual,5.0",
          ContentFR = "Alors... j’ai pris ma décision.",
          DialogueId = 10035219,
          FinalCamera = "-7.093658,62.875187,145.726074,0.000396,-17.213251,-45.26133,32.0,51.557377,false,Manual,5.0",
