          SpeakNpcId = 100304,
          Subtitle = "So... I've made up my mind.",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100352/191F431E"
        },
        [10035220] = {
