        [10035240] = {
          Camera = "-5.263988,-68.392349,147.26709,0.000142,-39.022816,158.796021,25.000002,342.928192,false,DoNotOverride,22",
          ContentFR = "Petit Champi règle encore ses comptes personnels, attention à ta petite tête !",
          DialogueId = 10035240,
          FinalCamera = "-4.958195,-68.501236,147.515381,0.000144,-38.822819,158.995956,25.000002,342.928192,false,DoNotOverride,22",
