          },
          NextDialogue = 10035242,
          Scripts = "TurnTo{_delay{1},TurnToDescription{\"200021:p(90)\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Hmph-hmm~ Try and catch me, Mutt Ears~!",
          TalkActionId = {
