        [10035242] = {
          Camera = "-228.074402,-7.094055,122.501221,0.000179,0.777364,12.810387,36.000011,142.203568,false,DoNotOverride,22",
          ContentFR = "Grâce à vous deux, je vais déjà mieux. Allons-y.",
