        [10035243] = {
          Camera = "55.511089,-48.67382,134.474365,0.000208,1.577227,116.598,35.5,108.506393,false,Manual,8.0",
          ContentFR = "Très bien, Officier Fischer... euh, Rhythm.",
          DialogueId = 10035243,
          FacialId = {
            [1] = "100304:Smile01"
          },
          FinalCamera = "54.041397,-49.409149,134.474365,0.000208,1.577227,116.598274,35.5,108.506393,false,Manual,8.0",
          GUID = "191F470E",
          Scripts = [[
PARA{
PlayAnimation{_delay{1.5},ActorId{100001},AnimationId{"DisagreeHead"},Duration{1}},
SetLocation{_delay{2.5},ActorId{100001},TargetPoint{"TargetPoint_cp2fixsimple47_nvzhuHide"},Visibility{"Hide"}},
SEQ{
CameraMoveTo{_delay{2.5},TargetPosition{"-55.431602,90.369171,138.976807,0.000143,-0.022765,-35.600025,35.0,110.864754,false,Manual,3.0"},duration{0}},
CameraMoveTo{TargetPosition{"-55.431602,90.369171,138.976807,0.000143,-0.022765,-35.600025,35.0,110.864754,false,Manual,3.0"},duration{2}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Yeah, Officer Fischer... I mean, Rhythm.",
          TalkActionId = {
            [1] = "100304:Confident_Start"
          },
          ToFinalCameraBlendTime = 2.4,
          VoiceName = "voice/$Locale$/story/1003/100352/191F470E"
        },
        [10035244] = {
          ContentFR = "Nous devons encore découvrir à la fois l’identité et la localisation du coupable... mais avec les indices que nous avons, j’ai l’impression d’être dans une impasse.",
          DialogueId = 10035244,
          GUID = "191F4738",
          NextDialogue = 10035245,
          SpeakNpcId = 100001,
          Subtitle = "We need to figure out both the whereabouts and identity of the perpetrator, but it feels like we've hit a dead end with the clues we've gathered.",
          VoiceName = "voice/$Locale$/story/1003/100352/191F4738"
        },
        [10035245] = {
          ContentFR = "Récapitulons ce que nous avons trouvé jusque-là. Peut-être qu’on est passé à côté de quelque chose d’important.",
          DialogueId = 10035245,
          GUID = "191F4762",
          SpeakNpcId = 100001,
          Subtitle = "Let's go over what we've found so far. Maybe we missed something important.",
          VoiceName = "voice/$Locale$/story/1003/100352/191F4762"
        },
        [10035246] = {
          Camera = "10.279533,-79.354004,133.750244,0.000094,0.196983,102.649895,30.000008,100000.0,false,Manual,22.0",
          ContentFR = "On avait d’abord pensé, avec l’indice du rideau, que le coupable avait un lien avec l’opéra. Mais on a déjà écarté le personnel.",
          DialogueId = 10035246,
          FinalCamera = "-2.861729,-18.827354,135.044922,0.000094,1.196997,102.249947,30.000008,100000.0,false,Manual,22.0",
          GUID = "191F478C",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(100001)",
            [3] = "100304:n(100001)"
          },
          NextDialogue = 10035247,
          Scripts = [[
PARA{
SetLocation{ActorId{100001},TargetPoint{"nvzhu_48_location"},Visibility{"Show"}},
SetLocation{ActorId{100304},TargetPoint{"lise_48_location"},Visibility{"Show"}},
SetLocation{ActorId{200021},TargetPoint{"aoge_48_location"},Visibility{"Show"}},
TurnTo{TurnToDescription{"200002:p(-120)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Earlier, we suspected the perpetrator might have a connection to the opera house based on the curtain clue, but we quickly ruled out the staff.",
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "100001:n(200021)"
          },
          VoiceName = "voice/$Locale$/story/1003/100352/191F478C"
        },
        [10035247] = {
          Camera = "-2.861729,-18.827354,135.044922,0.000094,1.196997,102.249947,30.000008,100000.0,false,Manual,22.0",
          ContentFR = "Pourtant, d’après ce qu’on a découvert dans la salle secrète des égouts, le lien avec l’opéra reste évident.",
          DialogueId = 10035247,
          FacialId = {
            [1] = "100001:Think01"
          },
          FinalCamera = "-2.861729,-18.827354,135.044922,0.000094,-1.80304,105.049423,30.000013,100000.0,false,Manual,22.0",
          GUID = "191F47B6",
          NextDialogue = 10035248,
          SpeakNpcId = 100001,
          Subtitle = "Still, from what we've seen in the hidden chamber underground, it's clear the perpetrator has strong ties to opera.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1003/100352/191F47B6"
        },
        [10035248] = {
          Camera = "-314.120422,323.028412,138.915283,0.0001,-2.600881,-44.171185,30.000002,100000.0,false,Manual,22.0",
          ContentFR = "Exactement. Si l’on suppose que le coupable est un <H>amateur d’opéra</>... alors la mélodie que tu as entendue cette nuit pourrait bien être un <H>air d’opéra</>.",
          DialogueId = 10035248,
          FacialId = {
            [1] = "100001:None",
            [2] = "100304:Think01"
          },
          GUID = "191F47E0",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)",
            [4] = "100304:n(100304)"
          },
          NextDialogue = 10035249,
          SpeakNpcId = 100304,
          Subtitle = "I agree. If the perpetrator is an opera enthusiast, then the melody you heard that night might actually be an aria from an opera.",
          TalkActionId = {
            [1] = "100001:Think_End",
            [2] = "100304:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1003/100352/191F47E0"
        },
        [10035249] = {
          ContentFR = "Quelqu’un ici s’y connaît en opéra ?",
          DialogueId = 10035249,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F480A",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(100001)",
            [3] = "100304:n(100001)",
            [4] = "100001:n(200021)"
          },
          NextDialogue = 10035250,
          SpeakNpcId = 100001,
          Subtitle = "Who here knows anything about opera?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100352/191F480A"
        },
        [10035250] = {
          Camera = "-83.064827,-13.434433,122.876221,0.000078,11.996905,-30.740709,30.000013,100000.0,false,Manual,22.0",
          ContentFR = "Ne me regarde pas. C’est bien trop sophistiqué pour mes oreilles.",
          DialogueId = 10035250,
          FacialId = {
            [1] = "200021:Ahaha01",
            [2] = "100304:None"
          },
          GUID = "191F4834",
          LookAt = {
            [1] = "200021:n(200021)",
            [2] = "200002:n(200002)",
            [3] = "100304:n(200021)",
            [4] = "100001:n(200021)"
          },
          NextDialogue = 10035251,
          SpeakNpcId = 200021,
          Subtitle = "Don't look at me. That's way too fancy for my taste.",
          TalkActionId = {
            [1] = "200021:ScratchHead_Start",
            [2] = "100001:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100352/191F4834"
        },
        [10035251] = {
          Camera = "230.964554,123.720169,183.445557,0.000094,-14.6028,-143.350281,30.000008,100000.0,false,Manual,22.0",
          ContentFR = "Euh... moi non plus. Et toi, Rhythm ?",
          DialogueId = 10035251,
          FacialId = {
            [1] = "200021:None"
          },
          GUID = "191F485E",
          LookAt = {
            [1] = "200021:n(200002)",
            [2] = "100304:n(200002)",
            [3] = "100001:n(200002)"
          },
          NextDialogue = 10035252,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200002},AnimationId{"ScratchHead_Start"},Duration{2}},
PlayAnimation{ActorId{200002},AnimationId{"ScratchHead_End"},Duration{1}},
LookAt{LookAtDescription{"200002:n(100304)"}},
}]],
          SpeakNpcId = 200002,
          Subtitle = "Um, I don't know much about it either... What about you, Officer Fischer?",
          TalkActionId = {
            [1] = "200021:ScratchHead_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100352/191F485E"
        },
        [10035252] = {
          Camera = "-56.100571,-8.342358,115.075195,0.000082,8.198917,-0.569315,30.000013,100000.0,false,Manual,22.0",
          ContentFR = "Désolée. Je vous l’ai dit, la musique n’est pas mon fort... <I>soupir...</> Si seulement je m’étais pas endormie quand Blues insistait pour me faire écouter ses cassettes...",
          DialogueId = 10035252,
          FacialId = {
            [1] = "100304:Disappoint01"
          },
          GUID = "191F4888",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)",
            [4] = "100304:n(100304)"
          },
          NextDialogue = 10035253,
          SpeakNpcId = 100304,
          Subtitle = "I'm afraid not. Like I said, I'm not really great with music... *sighs* If only I hadn't fallen asleep when Blues was badgering me to listen to his tapes.",
          TalkActionId = {
            [1] = "100304:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100352/191F4888"
        },
        [10035253] = {
          ContentFR = "Attendez... Blues ! Lui, c’était un passionné d’opéra. Je me souviens qu’il avait laissé un tas de cassettes dans notre base secrète ! Ça va prendre du temps de tout écouter une par une, mais... peut-être qu’on retrouvera cet air !",
          DialogueId = 10035253,
          GUID = "191F48B2",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(100001)",
            [3] = "100001:n(200021)"
          },
          NextDialogue = 10035254,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"100304:n(100304)"}},
PlayAnimation{ActorId{100304},AnimationId{"Sigh_End"},Duration{1}},
PlayAnimation{ActorId{100304},AnimationId{"Think_Start"},Duration{1}},
}]],
          SpeakNpcId = 100304,
          Subtitle = "Wait... Blues was an absolute opera fanatic. I remember he left a collection of tapes at our secret base! It's a long shot, but if we listen to them all, we might find that melody!",
          VoiceName = "voice/$Locale$/story/1003/100352/191F48B2"
        },
        [10035254] = {
          Camera = "-314.120422,323.028412,138.915283,0.0001,-2.600881,-44.171185,30.000002,100000.0,false,Manual,22.0",
          ContentFR = "Pas mal. Merci du coup de main, Blues ! Capitaine, retournons à la base secrète.",
          DialogueId = 10035254,
          GUID = "191F48DC",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(200021)",
            [3] = "100304:n(200021)",
            [4] = "100001:n(200021)"
          },
          SpeakNpcId = 200021,
          Subtitle = "Huh! Kudos to Blues for helping out big time! Captain, let's visit that place again.",
          TalkActionId = {
            [1] = "200021:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100352/191F48DC"
        },
        [10035255] = {
          ContentFR = "Le train à destination de Dismania partira dans une heure. Bon retour à la XIIIᵉ Légion. Toute gloire à l’Empereur !",
          DialogueId = 10035255,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "191F4906",
          SpeakNpcName = "Cp2CharacterName30",
          Subtitle = "The train departing from Icelake to Dismania will leave in one hour. Godspeed to the 13th Legion! All glory to our Emperor!",
          VoiceName = "voice/$Locale$/story/1003/100352/191F4906"
        },
        [10035301] = {
          ContentFR = "Dis donc, avec une collection pareille, ton frère devait être riche en secret !",
          DialogueId = 10035301,
          GUID = "191F5092",
          NextDialogue = 10035302,
          SpeakNpcId = 200002,
          Subtitle = "Why would your brother have a huge collection of tapes? Was he secretly loaded or something?",
          VoiceName = "voice/$Locale$/story/1003/100353/191F5092"
        },
        [10035302] = {
          ContentFR = "Pas du tout. C’étaient surtout des copies qu’il enregistrait chez ses amis.",
          DialogueId = 10035302,
          GUID = "191F50BC",
          SpeakNpcId = 100304,
          Subtitle = "Not at all. Most of them were copies he made from friends.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F50BC"
        },
        [10035303] = {
          ContentFR = "La mélodie ressemble... mais ce n’est pas ça. Celle du coupable sonnait plus triste.",
          DialogueId = 10035303,
          GUID = "191F50E6",
          SpeakNpcId = 100001,
          Subtitle = "The melody sounds similar... but not quite right. The perpetrator's version felt much sadder.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F50E6"
        },
        [10035304] = {
          ContentFR = "Aïe, mes oreilles ! Sérieusement, Blues, dans quel monde cette musique existe-t-elle ?",
          DialogueId = 10035304,
          GUID = "191F5110",
          SpeakNpcId = 100001,
          Subtitle = "Ow! My ears! Seriously, Blues, in what world is this music?",
          VoiceName = "voice/$Locale$/story/1003/100353/191F5110"
        },
        [10035305] = {
          ContentFR = "Celle-ci non plus... ça ne colle pas.",
          DialogueId = 10035305,
          GUID = "191F513A",
          SpeakNpcId = 100001,
          Subtitle = "This one doesn't sound right either.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F513A"
        },
        [10035306] = {
          Camera = "375.742188,-433.851562,288.041016,0.00005,-17.800415,125.025429,25.000002,100000.0,false,Manual,22.0",
          ContentFR = "C’est tout ? Il n’y en a pas d’autres ?",
          DialogueId = 10035306,
          FinalCamera = "317.1875,-472.192383,288.041016,0.000045,-19.000452,121.826225,25.000002,100000.0,false,Manual,22.0",
          GUID = "191F5164",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(100001)",
            [3] = "100001:n(200021)"
          },
          NextDialogue = 10035307,
          SpeakNpcId = 100001,
          Subtitle = "These can't be all of them, right?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5164"
        },
        [10035307] = {
          Camera = "41.957031,83.793945,112.646484,0.000084,10.397767,-108.765564,25.000006,100000.0,false,Manual,22.0",
          ContentFR = "Alors ? Rien ?",
          DialogueId = 10035307,
          FacialId = {
            [1] = "200021:Shock02"
          },
          FinalCamera = "43.648438,88.827148,111.683594,0.000084,10.397767,-108.765564,25.000006,100000.0,false,Manual,22.0",
          GUID = "191F518E",
          NextDialogue = 10035336,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"200021:n(100001)"}},
PlayAnimation{ActorId{200021},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "Got nothing?",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100353/191F518E"
        },
        [10035308] = {
          Camera = "70.957031,207.253906,117.710938,0.000085,4.599012,-117.169922,25.000006,100000.0,false,Manual,22.0",
          ContentFR = "Où est Rhythm ?",
          DialogueId = 10035308,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "191F51B8",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10035309,
          SpeakNpcId = 100001,
          Subtitle = "Where's Rhythm?",
          VoiceName = "voice/$Locale$/story/1003/100353/191F51B8"
        },
        [10035309] = {
          ContentFR = "Elle est sortie prendre l’air.",
          DialogueId = 10035309,
          GUID = "191F51E2",
          SpeakNpcId = 200021,
          Subtitle = "She went out for some air.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F51E2"
        },
        [10035310] = {
          Camera = "27.261719,-48.188965,98.787598,0.000046,5.787246,58.397362,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "« ... Ô neige silencieuse, fille des cieux... Accorde ta bénédiction à l’enfant sans nom... Qu’il danse en liesse parmi les flocons légers... »",
          DialogueId = 10035310,
          FinalCamera = "42.640625,-23.193359,101.764648,0.000046,5.787246,58.397282,35.000008,100000.0,false,Manual,22.0",
          GUID = "191F520C",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)"
          },
          NextDialogue = 10035311,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405005,
            [3] = 201011,
            [4] = 201024
          },
          SpeakNpcId = 100304,
          Subtitle = "\"The silent silent snow, child of the sky... May the nameless child be bathed in good time... Dancing with snowflakes, so light, so great...\"",
          TalkActionId = {
            [1] = "100304:Lise_Sing_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F520C"
        },
        [10035311] = {
          Camera = "106.324219,18.061035,129.950195,0.000045,-7.413487,-143.597916,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "... C’est ça ! C’est cette mélodie ! Comment elle s’appelle ? Qu’est-ce que ça raconte ?",
          DialogueId = 10035311,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "191F5236",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100001)",
            [3] = "100001:n(100304)"
          },
          NextDialogue = 10035312,
          SpeakNpcId = 100001,
          Subtitle = "...That's it! That's the melody! What's the name of this song? What's it about?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5236"
        },
        [10035312] = {
          Camera = "-158.65625,-332.602051,130.729492,0.000072,-4.813562,57.80043,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Hein ? Celle que je viens de fredonner ? J’y ai même pas pensé... ça m’est venu tout seul. Attends...",
          DialogueId = 10035312,
          FacialId = {
            [1] = "100001:None",
            [2] = "100304:Shock01"
          },
          GUID = "191F5260",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)",
            [4] = "100304:n(100001)"
          },
          NextDialogue = 10035313,
          SpeakNpcId = 100304,
          Subtitle = "The one I just hummed? I wasn't even thinking about it — it just slipped out. Let me try to remember...",
          TalkActionId = {
            [1] = "100304:Lise_Sing_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5260"
        },
        [10035313] = {
          ContentFR = "C’est Blues qui me l’a apprise. Ça s’appelle <I>Requiem pour les sans-nom</>. Un air de l’opéra <I>Né du blizzard</>. Mais les paroles que je chantais ne sont pas les vraies. Les originales sont bien plus tristes.",
          DialogueId = 10035313,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F528A",
          NextDialogue = 10035314,
          SpeakNpcId = 100304,
          Subtitle = "Oh, Blues taught me this one. It's called Requiem for the Nameless. It's a song from the opera Children From the Snowfield. But the lyrics I sang weren't the original ones. The actual song is much sadder.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F528A"
        },
        [10035314] = {
          ContentFR = "Ça raconte l’histoire d’un esprit sans nom, qui se sacrifie pour sauver ses amis. Mais ceux-ci ne découvrent jamais la vérité. Seule la neige s’en souvient.",
          DialogueId = 10035314,
          GUID = "191F52B4",
          LookAt = {
            [1] = "100304:n(100304)"
          },
          NextDialogue = 10035315,
          SpeakNpcId = 100304,
          Subtitle = "It tells the story of a nameless fairy who sacrifices everything to save their friends, but in the end, their friends never learn the truth. Only the snow remembers.",
          TalkActionId = {
            [1] = "100304:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F52B4"
        },
        [10035315] = {
          Camera = "43.828125,-22.387695,88.140137,0.000079,8.586326,60.000477,35.0,100000.0,false,Manual,22.0",
          ContentFR = "Blues n’aimait pas cette fin. Alors il avait réécrit les paroles, en version heureuse. Il connaissait cet air par cœur, il pouvait même le jouer à l’envers. C’est pour ça qu’il ne l’a jamais enregistré.",
          DialogueId = 10035315,
          FacialId = {
            [1] = "100304:Think01"
          },
          GUID = "191F52DE",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)"
          },
          NextDialogue = 10035316,
          SpeakNpcId = 100304,
          Subtitle = "Blues didn't like that ending, though, so he rewrote the lyrics into something happier. He knew the song so well that he could even play it backwards... which is why he never recorded it.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F52DE"
        },
        [10035316] = {
          ContentFR = "Tu veux dire... que c’est bien cette mélodie que tu as entendue ?",
          DialogueId = 10035316,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F5308",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10035317,
          SpeakNpcId = 100304,
          Subtitle = "Are you saying... this is the melody you heard that night?",
          TalkActionId = {
            [1] = "100304:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5308"
        },
        [10035317] = {
          Camera = "138.671875,16.285156,67.811523,7.200567,11.981702,-152.809799,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Oui. C’est exactement celle que j’ai entendue la nuit de l’attaque.",
          DialogueId = 10035317,
          GUID = "191F5332",
          NextDialogue = 10035318,
          SpeakNpcId = 100001,
          Subtitle = "Yes, I heard it just before I was attacked.",
          TalkActionId = {
            [1] = "100001:Agree"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5332"
        },
        [10035318] = {
          Camera = "43.828125,-22.387695,88.140137,0.000081,6.1863,60.000423,35.0,100000.0,false,Manual,22.0",
          ContentFR = "...",
          DialogueId = 10035318,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "43.828125,-22.387695,88.140137,0.000079,8.586326,60.000477,35.0,100000.0,false,Manual,22.0",
          GUID = "191F535C",
          LookAt = {
            [1] = "100304:p(lise_50_ditou)"
          },
          NextDialogue = 10035319,
          SpeakNpcId = 100304,
          Subtitle = "...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F535C"
        },
        [10035319] = {
          ContentFR = "C’est un nouvel indice... mais malheureusement, il est trop large. <I>Né du blizzard</> a été joué au Théâtre Galéa pendant des dizaines d’années. C’était extrêmement populaire. Beaucoup d’habitants savent le fredonner.",
          DialogueId = 10035319,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F5386",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10035320,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt03/0071_lise_secret\"},RelatedRegionId{101103}}",
          SpeakNpcId = 100304,
          Subtitle = "It's a new clue, but unfortunately, it doesn't narrow things down much. Children From the Snowfield had been performed at Galea Theatre for decades. It was incredibly popular, so a lot of the locals know it.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F5386"
        },
        [10035320] = {
          Camera = "-47.433594,-302.833496,184.461426,0.000141,-15.616298,71.198349,25.000002,100000.0,false,Manual,22.0",
          ContentFR = "Un jour, Blues et moi avions économisé pendant six mois pour acheter deux places. Mais une fois sur place, quelqu’un nous a accusés d’avoir volé ses billets. On a été mis dehors avant que la pièce commence.",
          DialogueId = 10035320,
          FacialId = {
            [1] = "100304:Sad01"
          },
          FinalCamera = "-43.898438,-292.427002,181.38916,0.000141,-15.616298,71.198349,25.000002,100000.0,false,Manual,22.0",
          GUID = "191F53B0",
          NextDialogue = 10035321,
          SpeakNpcId = 100304,
          Subtitle = "Once, Blues and I saved up for half a year to buy two tickets to see the play. We were so excited, but on that day... someone in the theatre accused us of stealing their tickets. We were kicked out before the play even started.",
          TalkActionId = {
            [1] = "100304:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F53B0"
        },
        [10035321] = {
          ContentFR = "J’étais dévastée. Je suis restée assise des heures contre le mur du théâtre. Et là, Blues a sorti son vieil harmonica et a joué cet air. Il l’avait appris en cachette...",
          DialogueId = 10035321,
          GUID = "191F53DA",
          NextDialogue = 10035322,
          SpeakNpcId = 100304,
          Subtitle = "That night, I sat against the theatre wall for hours, feeling absolutely miserable. But Blues... he pulled out his harmonica like a magician and started playing that song. Turns out, he'd already learned it on his own.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F53DA"
        },
        [10035322] = {
          Camera = "69.078125,-79.48877,262.419922,0.000194,-37.617821,73.187332,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Et soudain, de l’autre côté du mur, un garçon s’est mis à chanter. Sa voix... magnifique, comme une alouette.",
          DialogueId = 10035322,
          FinalCamera = "75.945312,-56.791992,244.148438,0.000194,-37.617821,73.187332,35.000008,100000.0,false,Manual,22.0",
          GUID = "191F5404",
          NextDialogue = 10035323,
          SpeakNpcId = 100304,
          Subtitle = "As he played, a voice rose from the other side of the wall — a boy, singing along. His voice was so beautiful... just like a lark.",
          TalkActionId = {
            [1] = "100304:Talk02_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5404"
        },
        [10035323] = {
          Camera = "292.566406,182.274902,118.647949,0.000237,-2.417996,-149.207611,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Ce soir-là, grâce à Blues et à cet inconnu, j’ai presque oublié qu’on nous avait chassés.",
          DialogueId = 10035323,
          GUID = "191F542E",
          NextDialogue = 10035324,
          SpeakNpcId = 100304,
          Subtitle = "With Blues's harmonica and that stranger's singing, I felt so happy I almost forgot we'd been thrown out that night.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F542E"
        },
        [10035324] = {
          Camera = "72.292969,-58.250488,84.757324,0.000228,9.781732,71.391068,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "... Désolée, je me suis laissée emporter. Ce que je veux dire, c’est que cette chanson est trop répandue. Elle ne peut pas servir de preuve.",
          DialogueId = 10035324,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F5458",
          NextDialogue = 10035325,
          SpeakNpcId = 100304,
          Subtitle = "Sorry... I didn't mean to get carried away and bore you with these old stories. My point is, this song is too common. It's not specific enough to serve as evidence.",
          TalkActionId = {
            [1] = "100304:ScratchHead_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F5458"
        },
        [10035325] = {
          Camera = "35.425781,210.5625,76.637207,0.000075,18.182783,-57.792496,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "Alors, cette pièce sera rejouée bientôt ? On pourrait essayer de guetter au théâtre.",
          DialogueId = 10035325,
          FinalCamera = "35.425781,210.5625,76.637207,0.000069,11.982678,-57.391754,35.000011,100000.0,false,Manual,22.0",
          GUID = "191F5482",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(200021)",
            [3] = "100001:n(200021)"
          },
          NextDialogue = 10035326,
          SpeakNpcId = 200021,
          Subtitle = "Any chance this play's being performed again soon? Maybe we could stake out the theatre and see what happens.",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100353/191F5482"
        },
        [10035326] = {
          Camera = "46.15625,-202.915527,167.463867,0.000052,-11.016801,66.199203,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "Je ne sais pas. D’après ce que j’ai lu, l’opéra a été suspendu il y a deux ans, après un <H>incident</>.",
          DialogueId = 10035326,
          GUID = "191F54AC",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)",
            [4] = "100304:n(200021)"
          },
          NextDialogue = 10035327,
          SpeakNpcId = 100304,
          Subtitle = "Hmm... I don't know much about recent performances. From what I know, the play's been off the schedule for a while due to an accident.",
          TalkActionId = {
            [1] = "100304:ScratchHead_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F54AC"
        },
        [10035327] = {
          Camera = "109.480469,38.969727,114.763672,0.000073,-0.616664,-141.401657,35.0,100000.0,false,Manual,22.0",
          ContentFR = "Un incident ?",
          DialogueId = 10035327,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "191F54D6",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "200002:n(100001)",
            [3] = "100001:n(100304)"
          },
          NextDialogue = 10035328,
          SpeakNpcId = 100001,
          Subtitle = "An accident?",
          TalkActionId = {
            [1] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F54D6"
        },
        [10035328] = {
          Camera = "-151.640625,-339.61792,161.115723,0.000086,-9.217005,58.195625,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Oui. Je suis tombée sur le rapport en classant des dossiers. Ce n’était pas énorme, juste une bagarre lors d’une représentation.",
          DialogueId = 10035328,
          GUID = "191F5500",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10035329,
          SpeakNpcId = 100304,
          Subtitle = "Yeah. I came across a note about it while sorting through case files some time ago. It wasn't anything major — just a brawl at the theatre during a performance two years ago.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F5500"
        },
        [10035329] = {
          Camera = "24.625,-15.047363,93.071777,0.000097,8.781772,53.395985,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "La directrice de la troupe, Letizia Putsch, a déclaré qu’un des acteurs principaux avait été blessé. Depuis, la troupe de la Flûte Enchantée a suspendu les représentations de <I>Né du blizzard</>.",
          DialogueId = 10035329,
          GUID = "191F552A",
          NextDialogue = 10035330,
          SpeakNpcId = 100304,
          Subtitle = "According to Putsch, the troupe's director, their lead performer was injured during the fight. That's why the Magic Flute troupe decided to halt future performances of Children From the Snowfield.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F552A"
        },
        [10035330] = {
          ContentFR = "Laisse-moi vérifier mes notes... Voilà.",
          DialogueId = 10035330,
          GUID = "191F5554",
          NextDialogue = 10035331,
          SpeakNpcId = 100304,
          Subtitle = "Let me check my notes... here it is.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F5554"
        },
        [10035331] = {
          ContentFR = "Affaire : Bagarre au Théâtre Galea\nDate : 9 octobre, 20 h 30\n\nDépositaire de plainte : Letizia Putsch, directrice de la troupe de la Flûte Enchantée\n\nParties impliquées :\nParsifal Snowfield (comédien principal)\nSusanna Rossi (comédienne principale)\nMathew Bernard (spectateur)\nFeeley Francisco (spectateur)\n...\nRésumé de l’incident : Une altercation aurait éclaté entre des membres de la troupe et des spectateurs du premier rang. Témoignages évoquant des coups portés aux comédiens par les spectateurs. (Certaines pages du rapport officiel ont été arrachées.)\n\nConclusion : Preuves insuffisantes. Aucune suite judiciaire.\n\nRemarques : Les représentations de Né du blizzard sont suspendues jusqu’à nouvel ordre, sans date de reprise annoncée.\nJ’aurais tant voulu voir cette pièce avec Blues, pour effacer le regret de ne pas l’avoir vue autrefois. Mais il semble que ce ne soit pas pour bientôt...",
          DialogueId = 10035331,
          DialoguePanelType = "{type:showtext;topic:READ_NAME_2000049;content:READ_TEXT_2000049}",
          GUID = "191F557E",
          NextDialogue = 10035332,
          Subtitle = "Brawl at Galea Theatre\n\nDate: October 9th, 8:30 PM\n\nFiled by: Letizia Putsch, Director of the Magic Flute Troupe\n\nInvolved Parties: Parsifal Snowfield (Lead Performer), Susanna Rossie (Lead Performer), Mathew Bernard (Audience), Feeley Francisco (Audience)\n...\n\nIncident Summary: A physical altercation reportedly broke out between troupe members and two front-row audience members. Alleged assault of performers by said audience members. (Several pages of the incident report appear to have been torn out.)\n\nConclusion: Evidence found to be insufficient. Case dismissed.\n\nRemarks: Performances of Children From the Snowfield have been suspended until further notice. No resumption date announced.\nI'd hoped to watch this one with Blues — to finally make up for the show we missed all those years ago. But I guess... that won't be happening any time soon.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F557E"
        },
        [10035332] = {
          Camera = "-175.097656,-375.326904,138.394531,0.000041,-5.200041,58.387745,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "À part replonger dans les égouts, c’est notre seule piste actuelle...",
          DialogueId = 10035332,
          FacialId = {
            [1] = "100304:Think01"
          },
          FinalCamera = "-159.128906,-349.168457,135.712402,0.000042,-5.000033,59.587662,35.000011,100000.0,false,Manual,22.0",
          GUID = "191F55A8",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)"
          },
          NextDialogue = 10035333,
          SpeakNpcId = 100304,
          Subtitle = "But aside from diving into the sewers for further investigation, this is the only lead we have for now...",
          TalkActionId = {
            [1] = "100304:Think_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100353/191F55A8"
        },
        [10035333] = {
          ContentFR = "Tu as raison. Si<I> Né du blizzard </>a une signification particulière pour l’agresseur, on peut peut-être l’attirer avec ça.",
          DialogueId = 10035333,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F55D2",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10035334,
          SpeakNpcId = 100304,
          Subtitle = "You just gave me an idea. If Children From the Snowfield holds great sentimental value for the perpetrator, perhaps we can use it to draw them out.",
          TalkActionId = {
            [1] = "100304:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100353/191F55D2"
        },
        [10035334] = {
          ContentFR = "Exactement. Allons voir la directrice Putsch, et demandons-lui de diffuser une fausse annonce.",
          DialogueId = 10035334,
          GUID = "191F55FC",
          LookAt = {
            [1] = "200021:n(100304)",
            [2] = "200002:n(200021)",
            [3] = "100001:n(200021)",
            [4] = "100304:n(200021)"
          },
          NextDialogue = 10035335,
          SpeakNpcId = 200021,
          Subtitle = "Exactly. Let's pay Ms Putsch a visit at the theatre and see if she's willing to help us plant a fake announcement.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F55FC"
        },
        [10035335] = {
          ContentFR = "Stupide...",
          DialogueId = 10035335,
          GUID = "191F5626",
          NextDialogue = 10035337,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"},RelatedRegionId{101103}}",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName01",
          Subtitle = "Naive.",
          VoiceName = "voice/$Locale$/story/1003/100353/191F5626"
        },
        [10035336] = {
          Camera = "56.375,-68.62793,156.333984,0.000067,-11.400814,114.023117,25.000002,100000.0,false,Manual,22.0",
          DialogueId = 10035336,
          DialoguePanelType = "None",
          Duration = 3,
          FacialId = {
            [1] = "100001:Think01",
            [2] = "200021:None"
          },
          FinalCamera = "49.179688,-52.487305,153.078125,0.00007,-10.40082,114.023308,25.000002,100000.0,false,Manual,22.0",
          GUID = "191F518F",
