          VoiceName = "voice/$Locale$/story/1003/100359/191FB32C"
        },
        [10035903] = {
          Camera = "432.814453,-578.855469,220.180359,0.000004,-7.399868,119.568428,20.000008,680.700806,false,Manual,3",
          ContentFR = "Impossible de dormir avec un chant pareil. C’est bien la première fois que j’entends quelqu’un massacrer à ce point un air de <I>Né du blizzard</>.",
          DialogueId = 10035903,
          GUID = "191FB356",
          NextDialogue = 10035904,
          Scripts = "SetLocation{ActorId{100331},TargetPoint{\"tuosi01_53_idle\"},Visibility{\"Show\"}}",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "I wasn't sleeping. Your singing's just so unbearable. I've never heard anyone butcher a tune from Children From the Snowfield like that.",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB356"
        },
        [10035904] = {
          Camera = "-120.114258,-65.876953,220.58136,0.000004,-8.202053,-24.615345,20.000011,335.406189,false,DoNotOverride,1.2",
          ContentFR = "Haha ! Avec un instrument, ça ne sonnerait pas si mal.",
          DialogueId = 10035904,
          GUID = "191FB380",
          NextDialogue = 10035905,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Haha! If I had an instrument, maybe it wouldn't sound so bad.",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB380"
        },
        [10035905] = {
          Camera = "-120.114258,-65.876953,220.58136,0.000004,-8.202053,-24.615345,20.000011,335.406189,false,DoNotOverride,1.2",
          ContentFR = "Et la douleur, tu la ressens pas ?",
          DialogueId = 10035905,
          GUID = "191FB3AA",
          LookAt = {
            [1] = "100328:n(100331)"
          },
          NextDialogue = 10035906,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Don't you feel the pain?",
          TalkActionId = {
            [1] = "100328:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100359/191FB3AA"
        },
        [10035906] = {
          Camera = "434.479492,-573.817383,223.790649,0.000063,-8.001894,117.545296,22.000006,927.34375,false,Manual,2.799999",
          ContentFR = "Justement. Quand ça fait mal, c’est là qu’il faut chanter.",
          DialogueId = 10035906,
          GUID = "191FB3D4",
          LookAt = {
            [1] = "100328:n(100328)"
          },
          NextDialogue = 10035907,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "The worse it hurts, the more you need to sing.",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB3D4"
        },
        [10035907] = {
          Camera = "434.479492,-573.817383,223.790649,0.000063,-8.001894,117.545296,22.000006,927.34375,false,Manual,2.799999",
          ContentFR = "Garde ton souffle. Survivre aux expériences est déjà assez difficile.",
          DialogueId = 10035907,
          GUID = "191FB3FE",
          NextDialogue = 10035908,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Save your breath. Surviving the experiments is hard enough.",
          TalkActionId = {
            [1] = "100328:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1003/100359/191FB3FE"
        },
        [10035908] = {
          Camera = "180.489258,-377.827148,235.083801,0.000124,-5.80118,-21.050528,35.0,100000.0,false,Manual,22.0",
          ContentFR = "La douleur du corps n’est rien. Ce qui fait mal, c’est de voir des êtres humains... réduits à ça.",
          DialogueId = 10035908,
          GUID = "191FB428",
          NextDialogue = 10035909,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Physical pain doesn't matter. It's what they've turned human into that hurts...",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB428"
        },
        [10035909] = {
          Camera = "410.818359,-586.445312,210.064209,10.811686,-3.001451,107.757263,20.0,927.34375,false,Manual,3",
          ContentFR = "Après tout ce temps, tu crois encore qu’on est humains ? Non. Nous sommes des monstres désormais. Des monstres vides, soumis à leur volonté. Accepte-le, et tu ne souffriras plus.",
          DialogueId = 10035909,
          GUID = "191FB452",
          LookAt = {
            [1] = "100328:n(100331)"
          },
          NextDialogue = 10035910,
          Scripts = [[
SEQ{
MoveTo{ActorId{100328},TargetPoint{"tuosi01_walk"},MoveSpeed{150},Visibility{"Show"}},
CameraMoveTo{_delay{0.6},TargetPosition{"284.339844,-294.831055,217.898376,10.817102,0.598243,129.1483,20.000008,927.34375,false,Manual,22.0"},duration{0}}
}]],
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "After all this, you still think we're human? Face it. We're nothing but monsters now — mindless, soulless tools at their command. Accept it, and it won't hurt anymore.",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB452"
        },
        [10035910] = {
          Camera = "317.161133,-375.083008,228.198242,0.000137,-7.201799,-39.445698,20.000008,100000.0,false,Manual,22.0",
          ContentFR = "Non... on ne doit pas céder. Le jour où ton cœur abandonne, ce jour-là seulement tu deviens un monstre.",
          DialogueId = 10035910,
          GUID = "191FB47C",
          NextDialogue = 10035911,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "No... We can't let ourselves become monsters... The day your heart gives up is the day you truly become one.",
          TalkActionId = {
            [1] = "100331:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1003/100359/191FB47C"
        },
        [10035911] = {
          Camera = "299.682617,-302.890625,219.492859,0.000183,-2.405818,132.131363,20.000008,100000.0,false,Manual,22.0",
          ContentFR = "Tu as oublié la dernière fois que tu as tenté de fuir ? L’électricité qui t’a traversé le corps ? Tu veux vraiment recommencer ?",
          DialogueId = 10035911,
          GUID = "191FB4A6",
          LookAt = {
            [1] = "100328:n(100331)"
          },
          NextDialogue = 10035912,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Did you forget what happened the last time you tried to escape? They strapped you to the electric chair. You want another round of that?",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB4A6"
        },
        [10035912] = {
          Camera = "150.523438,-204.141602,220.726868,0.000177,-9.001649,-29.027712,20.000008,690.414062,false,Manual,2.799999",
          ContentFR = "Tu vois... tu t’en souviens encore. C’est bien la preuve que tu n’es pas un monstre.",
          DialogueId = 10035912,
          GUID = "191FB4D0",
          NextDialogue = 10035913,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "See? The fact that you still care — that's proof enough you're not a monster.",
          TalkActionId = {
            [1] = "100331:Give"
          },
          VoiceName = "voice/$Locale$/story/1003/100359/191FB4D0"
        },
        [10035913] = {
          Camera = "392.458984,-406.024414,222.654724,0.000121,-1.801845,133.350006,35.0,100000.0,false,Manual,22.0",
          ContentFR = "Sophisme.",
          DialogueId = 10035913,
          FinalCamera = "304.217773,-313.102539,219.070496,0.000124,-0.801789,133.149994,25.0,100000.0,false,Manual,22.0",
          GUID = "191FB4FA",
          NextDialogue = 10035914,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Twisted logic.",
          ToFinalCameraBlendTime = 1.5,
          VoiceName = "voice/$Locale$/story/1003/100359/191FB4FA"
        },
        [10035914] = {
          Camera = "183.125977,-413.553711,313.950928,0.000107,-24.746048,-11.405643,25.000002,100000.0,false,Manual,22.0",
          ContentFR = "Ne t’en fais pas. Je t’emmènerai avec moi quand je m’évaderai.",
          DialogueId = 10035914,
          FinalCamera = "153.149414,-407.208984,328.39209,0.000109,-24.946075,-11.006715,25.000002,100000.0,false,Manual,22.0",
          GUID = "191FB524",
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Don't worry. I'll get us out of here.",
          TalkActionId = {
            [1] = "100331:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100359/191FB524"
        },
        [10035915] = {
          ContentFR = "Oh ? Tu respires encore ? On dirait bien que ton corps s’habitue à la régénération, finalement.",
          DialogueId = 10035915,
          GUID = "191FB54E",
          NextDialogue = 10035916,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Wow, still kicking? Looks like the regeneration ability is adapting better than expected.",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB54E"
        },
        [10035916] = {
          ContentFR = "Hé, ne crois pas que j’ignore ce que tu trafiques.",
          DialogueId = 10035916,
          GUID = "191FB578",
          NextDialogue = 10035917,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Hey, don't think I don't know what you're up to.",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB578"
        },
        [10035917] = {
          ContentFR = "Tu aurais pu gagner ce combat sans effort, pas vrai ? Mais non... il a fallu que tu joue la comédie et te blesse exprès.",
          DialogueId = 10035917,
          GUID = "191FB5A2",
          NextDialogue = 10035918,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "You could've easily won, couldn't you? Yet you just had to get yourself hurt. What a performance.",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB5A2"
        },
        [10035918] = {
          ContentFR = "Mais ne t’imagine pas mourir aussi facilement, vous êtes bien trop précieux pour qu’on laisse des sujets de ce calibre se perdre. Quelle perte ce serait !",
          DialogueId = 10035918,
          GUID = "191FB5CC",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "Don't get your hopes up. We're not letting such a valuable augmented subject die for nothing! That'd be a colossal waste!",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB5CC"
        },
        [10035919] = {
          ContentFR = "Merde... encore un qui a sombré dans la folie.",
          DialogueId = 10035919,
          GUID = "191FB525",
          Subtitle = "Sh*t... there goes another.",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB525"
        },
        [10035920] = {
          ContentFR = "Dommage... celui-là avait une chance de surpasser les sujets 36 et 47.",
          DialogueId = 10035920,
          GUID = "191FB526",
          Subtitle = "What a waste... I thought they'd finally surpass Subjects 36 and 47.",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB526"
        },
        [10035921] = {
          ContentFR = "Déjà fini ? Un déchet reste un déchet.",
          DialogueId = 10035921,
          GUID = "191FB527",
          Subtitle = "That's it? Ugh. Trash in, trash out.",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB527"
        },
        [10035922] = {
          ContentFR = "Pfiou... enfin débarrassé.",
          DialogueId = 10035922,
          GUID = "191FB528",
          Subtitle = "Phew... all cleaned up.",
          VoiceName = "voice/$Locale$/story/1003/100359/191FB528"
        },
        [10036001] = {
          Camera = "-1967.145508,-1305.442383,818.028564,-0.000031,-15.201746,24.965626,24.292501,335.406189,false,DoNotOverride,1.2",
          ContentFR = "36 ! Hé, 36 !",
          DialogueId = 10036001,
          FinalCamera = "-1589.737305,-1129.726562,704.90564,-0.000031,-15.201746,24.964874,24.292501,335.406189,false,DoNotOverride,1.2",
          GUID = "191FC36A",
          NextDialogue = 10036002,
          RelatedWikiId = {
            [1] = 407003,
            [2] = 403004,
            [3] = 201024
          },
          Scripts = "MoveTo{ActorId{100328},TargetPoint{\"tuosi01_walk2\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "36! Hey, 36!",
          TalkActionId = {
            [1] = "100331:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC36A"
        },
        [10036002] = {
          ContentFR = "...",
          DialogueId = 10036002,
          GUID = "191FC394",
          LookAt = {
            [1] = "100328:n(100331)"
          },
          NextDialogue = 10036003,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC394"
        },
        [10036003] = {
          Camera = "463.391602,-580.462891,220.541992,0.000188,-7.202789,119.394897,20.0,678.51178,false,Manual,3.0",
          ContentFR = "Hé...",
          DialogueId = 10036003,
          FinalCamera = "463.229492,-580.175781,220.541992,0.000189,-7.202789,118.994843,20.0,70.352333,false,Manual,3.0",
          GUID = "191FC3BE",
          NextDialogue = 10036004,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Hey...",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC3BE"
        },
        [10036004] = {
          Camera = "-43.522461,-123.954102,225.915833,0.000146,-7.596761,-21.001686,20.000008,100000.0,false,Manual,22.0",
          ContentFR = "...",
          DialogueId = 10036004,
          GUID = "191FC3E8",
          NextDialogue = 10036005,
          Scripts = "PlayAnimation{_delay{2},ActorId{100331},AnimationId{\"Sigh_End\"},Duration{2}}",
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC3E8"
        },
        [10036005] = {
          Camera = "58.138672,-330.501953,109.144714,0.000134,8.597835,-22.997952,35.0,291.655762,false,Manual,2.8",
          ContentFR = "Tiens... prends ça... ça devrait atténuer un peu les blessures de ce matin.",
          DialogueId = 10036005,
          FinalCamera = "58.137695,-330.5,140.144714,0.000134,8.597835,-22.997952,35.0,291.655762,false,Manual,2.8",
          GUID = "191FC412",
          LookAt = {
            [1] = "100328:n(100331)"
          },
          NextDialogue = 10036006,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Hey... here, take this... it should help ease the injuries from earlier.",
          TalkActionId = {
            [1] = "100331:Give"
          },
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "100328:n(100331)"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC412"
        },
        [10036006] = {
          Camera = "463.391602,-580.462891,220.541992,0.000188,-7.202789,119.394897,20.0,678.51178,false,Manual,3.0",
          ContentFR = "... Alors c’est pour ça que tu as traîné exprès pendant ta tâche ? Que tu as encaissé des coups, juste pour récupérer quelques fioles de remède ?",
          DialogueId = 10036006,
          GUID = "191FC43C",
          NextDialogue = 10036007,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...So that's why you dragged your tasks out today? Even took a good thrashing, just to get your hands on these phials of medicine?",
          TalkActionId = {
            [1] = "100328:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC43C"
        },
        [10036007] = {
          ContentFR = "Tu m’as percé à jour.",
          DialogueId = 10036007,
          GUID = "191FC466",
          NextDialogue = 10036008,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Caught me, huh...",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC466"
        },
        [10036008] = {
          Camera = "185.640625,-233.083984,160.088501,0.000144,8.996766,-43.391754,35.0,526.580566,false,Manual,2.8",
          ContentFR = "Mais n’abandonne pas. Je t’ai promis, je te ferai sortir d’ici vivant.",
          DialogueId = 10036008,
          GUID = "191FC490",
          LookAt = {
            [1] = "100328:n(100328)"
          },
          NextDialogue = 10036009,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Don't you dare give up. I told you — I'm getting us both out of here alive.",
          TalkActionId = {
            [1] = "100331:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC490"
        },
        [10036009] = {
          Camera = "-267.09668,-233.355469,217.466675,-0.000031,-3.001649,50.570717,25.0,335.406189,false,DoNotOverride,1.2",
          ContentFR = "Pourquoi s’accrocher ? Regarde-nous... même si on s’évade, qu’est-ce qui nous attend dehors ?",
          DialogueId = 10036009,
          GUID = "191FC4BA",
          NextDialogue = 10036010,
          Scripts = "MoveTo{ActorId{100328},TargetPoint{\"tuosi01_walk3\"},MoveSpeed{200},Visibility{\"Show\"}}",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Why bother? Even if we managed to escape, what kind of life awaits us now that we've become like this?",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC4BA"
        },
        [10036010] = {
          Camera = "160.84668,-584.186523,204.747314,-0.00003,-2.401276,24.76207,25.000002,335.406189,false,DoNotOverride,1.2",
          ContentFR = "Mourir, c’est renoncer à toute chance de bonheur. Moi, je refuse.",
          DialogueId = 10036010,
          GUID = "191FC4E4",
          NextDialogue = 10036011,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "But once you're dead, nothing good can ever happen to you again. I won't go down without a fight.",
          TalkActionId = {
            [1] = "100331:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC4E4"
        },
        [10036011] = {
          Camera = "307.469727,-340.191406,161.595886,0.000178,13.19656,-47.393784,35.000011,241.246582,false,Manual,2.799999",
          ContentFR = "On a encore des rêves, non ? Des choses qu’on n’a pas accomplies.",
          DialogueId = 10036011,
          GUID = "191FC50E",
          NextDialogue = 10036012,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "We both have dreams we've yet to fulfil, haven't we?",
          TalkActionId = {
            [1] = "100331:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC50E"
        },
        [10036012] = {
          Camera = "498.730469,-495.881836,208.647461,0.00018,-0.003142,142.201035,50.0,241.246582,false,Manual,22.0",
          ContentFR = "Ça n’a plus d’importance. On est déjà foutus.",
          DialogueId = 10036012,
          FinalCamera = "447.958984,-456.501953,208.644409,0.00018,-0.003142,142.201035,50.0,241.246582,false,Manual,22.0",
          GUID = "191FC538",
          NextDialogue = 10036013,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Doesn't matter anymore. Look at us now.",
          TalkActionId = {
            [1] = "100328:DisagreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC538"
        },
        [10036013] = {
          Camera = "-223.761719,17.283203,231.583618,0.000198,-9.803254,-22.194181,20.0,241.246582,false,Manual,22.0",
          ContentFR = "Raconte-les-moi. Tant qu’on parle de nos rêves, on se rappelle qu’on est encore humains.",
          DialogueId = 10036013,
          GUID = "191FC562",
          LookAt = {
            [1] = "100328:n(100331)"
          },
          NextDialogue = 10036014,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Tell me about them. Talking about your dreams reminds you that you're still human.",
          TalkActionId = {
            [1] = "100331:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC562"
        },
        [10036014] = {
          Camera = "-217.935547,-11.030273,239.382629,0.000152,-16.403408,10.210232,35.000008,241.246582,false,Manual,22.0",
          ContentFR = "...",
          DialogueId = 10036014,
          GUID = "191FC58C",
          LookAt = {
            [1] = "100328:n(100328)"
          },
          NextDialogue = 10036015,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC58C"
        },
        [10036015] = {
          ContentFR = "... Comédien.",
          DialogueId = 10036015,
          GUID = "191FC5B6",
          NextDialogue = 10036016,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...A performer...",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC5B6"
        },
        [10036016] = {
          Camera = "475.610352,-611.675781,221.689697,0.000148,-7.606269,121.213806,20.0,1261.194092,false,Manual,22.0",
          ContentFR = "Quoi ?",
          DialogueId = 10036016,
          GUID = "191FC5E0",
          NextDialogue = 10036017,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Huh?",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC5E0"
        },
        [10036017] = {
          Camera = "475.610352,-611.675781,221.689697,0.000148,-7.606269,121.213806,20.0,1261.194092,false,Manual,22.0",
          ContentFR = "Mon rêve, c’était de devenir comédien.",
          DialogueId = 10036017,
          GUID = "191FC60A",
          NextDialogue = 10036018,
          Scripts = [[
PARA{
MoveTo{ActorId{100328},TargetPoint{"tuosi01_walk4"},MoveSpeed{120},Visibility{"Show"}},
CameraMoveTo{_delay{1},TargetPosition{"-347.200195,-320.677734,160.137878,0.000141,6.99427,50.212906,35.000008,1261.194092,false,Manual,22.0"},duration{0}}
}]],
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "I used to dream of becoming a performer.",
          TalkActionId = {
            [1] = "100328:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC60A"
        },
        [10036018] = {
          Camera = "-165.179688,-114.144531,207.396362,0.000156,-2.605772,-133.186981,25.0,1261.194092,false,Manual,22.0",
          ContentFR = "Passer l’examen de la VIᵉ Légion... c’était ma première étape pour devenir un Charon Couronné. Si j’avais pu accéder à une vie meilleure, j’aurais eu une chance de monter sur une plus grande scène...",
          DialogueId = 10036018,
          FinalCamera = "-187.849609,-138.015625,206.04657,0.000155,-1.805758,-134.186615,25.0,1261.194092,false,Manual,22.0",
          GUID = "191FC634",
          NextDialogue = 10036019,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Participating in the 6th Legion's tests was meant to be my first step toward becoming a Laurelled Charon. I thought if I could build a better life, I might one day stand on a grander stage...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC634"
        },
        [10036019] = {
          Camera = "483.212891,-613.606445,221.566162,0.000146,-6.40518,124.602669,25.0,189.198608,false,Manual,22.0",
          ContentFR = "Finies les soirées à fixer les comédiens sur scène, ou à empiler des cassettes dans le silence... juste parce que, pour nous autres Charons, notre corne répugnait le public, et nous interdisait toute représentation.",
          DialogueId = 10036019,
          GUID = "191FC65E",
          NextDialogue = 10036020,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "I wouldn't have to hide in the shadows anymore, watching others bask in the spotlight, or surround myself with tapes of songs I couldn't even play — all because, as a Charon, my horn was deemed \"sickening\" to the audience.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC65E"
        },
        [10036020] = {
          Camera = "223.780273,-418.617188,192.429321,0.000123,5.795101,-18.393356,35.0,189.198654,false,Manual,2.8",
          ContentFR = "Ha... hahaha.",
          DialogueId = 10036020,
          GUID = "191FC688",
          NextDialogue = 10036021,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Ha, hahaha.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC688"
        },
        [10036021] = {
          ContentFR = "C’est ridicule, pas vrai ?",
          DialogueId = 10036021,
          GUID = "191FC6B2",
          NextDialogue = 10036022,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "I know — it's a ridiculous dream.",
          TalkActionId = {
            [1] = "100328:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC6B2"
        },
        [10036022] = {
          ContentFR = "Pas du tout. Je trouve même que ça nous ressemble.",
          DialogueId = 10036022,
          GUID = "191FC6DC",
          NextDialogue = 10036023,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "No, I just thought of us.",
          TalkActionId = {
            [1] = "100331:Agree"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC6DC"
        },
        [10036023] = {
          Camera = "-277.438477,12.542969,206.000488,0.000168,-2.405633,-27.593695,35.000008,989.247986,false,Manual,2.8",
          ContentFR = "Moi aussi j’adore l’opéra. Voilà pourquoi on s’est entendus si vite. Quand on sortira d’ici, on construira notre propre scène, on invitera nos proches, et on jouera pour eux.",
          DialogueId = 10036023,
          GUID = "191FC706",
          NextDialogue = 10036024,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "I love opera too. No wonder we hit it off. After we get out, we'll set up a stage of our own, invite everyone we know, and put on a wonderful show for them.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC706"
        },
        [10036024] = {
          Camera = "199.172852,-433.332031,223.718994,0.000192,-3.005399,132.20047,35.000008,938.13208,false,Manual,2.8",
          ContentFR = "...",
          DialogueId = 10036024,
          FinalCamera = "215.05957,-418.922852,223.388977,0.000192,-3.005399,132.20047,35.000008,938.13208,false,Manual,2.8",
          GUID = "191FC730",
          NextDialogue = 10036025,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC730"
        },
        [10036025] = {
          Camera = "198.80957,-348.649414,122.465942,0.000148,16.993544,-28.586533,35.0,302.68161,false,Manual,2.8",
          ContentFR = "Si tu ne réponds pas, je prendrai ton silence pour un \"oui\". Et une promesse, ça se tient.",
          DialogueId = 10036025,
          GUID = "191FC75A",
          NextDialogue = 10036026,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "I'll take that as a yes. And a promise is a promise — I'll hold you to it.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC75A"
        },
        [10036026] = {
          ContentFR = "J’ai comme un pressentiment... notre chance de nous échapper arrive.",
          DialogueId = 10036026,
          GUID = "191FC784",
          LookAt = {
            [1] = "100331:n(100328)"
          },
          NextDialogue = 10036027,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "I've got a feeling... our chance to escape is coming.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC784"
        },
        [10036027] = {
          Camera = "-336.173828,-305.694336,191.327087,0.000173,2.392745,50.61248,35.000008,302.68161,false,Manual,2.8",
          ContentFR = "Ce n’est qu’une illusion.",
          DialogueId = 10036027,
          FinalCamera = "-312.927734,-277.383789,192.857788,0.000173,2.392745,50.612766,35.000011,302.68161,false,Manual,2.8",
          GUID = "191FC7AE",
          NextDialogue = 10036028,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "It might be just a delusion.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC7AE"
        },
        [10036028] = {
          Camera = "198.80957,-348.649414,122.465942,0.000148,16.993544,-28.586533,35.0,302.68161,false,Manual,2.8",
          ContentFR = "Pas du tout. Tu ne l’as pas senti ? <H>Les inhibiteurs ont de moins en moins d’effet sur nous</>.",
          DialogueId = 10036028,
          GUID = "191FC7D8",
          NextDialogue = 10036029,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "It's not. Haven't you noticed? The suppressants have been growing less effective on us over the years.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC7D8"
        },
        [10036029] = {
          ContentFR = "C’est la preuve qu’on est encore humains ! Même nos corps nous crient qu’il est temps de nous révolter !",
          DialogueId = 10036029,
          GUID = "191FC802",
          NextDialogue = 10036030,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "That's proof we're still human — even our bodies are telling us it's time to fight for ourselves!",
          TalkActionId = {
            [1] = "100331:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1003/100360/191FC802"
        },
        [10036030] = {
          Camera = "-64.507812,-225.208984,216.510254,0.000098,-1.602383,103.814949,20.0,302.68161,false,Manual,2.8",
          ContentFR = "Ou alors... c’est juste que ces maudits corps de monstres mutent trop bien.",
          DialogueId = 10036030,
          FinalCamera = "-64.507812,-225.208984,216.510254,0.000069,-43.801937,102.617737,20.0,302.68161,false,Manual,2.8",
          GUID = "191FC82C",
          NextDialogue = 10036031,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Or maybe it's just this cursed, monstrous body mutating for its own survival.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC82C"
        },
        [10036031] = {
          Camera = "201.640625,-253.776367,315.783325,0.000122,-19.205063,-42.193974,35.0,302.68161,false,Manual,2.8",
          ContentFR = "Haha ! Et les alchimistes n’ont même pas remarqué cette mutation ! Tant mieux pour nous. Attends... il nous faut un signal, un mot de passe, pour le jour où ça arrivera.",
          DialogueId = 10036031,
          FinalCamera = "221.570312,-272.848633,306.172791,0.000119,-19.20507,-43.193863,35.0,302.68161,false,Manual,2.8",
          GUID = "191FC856",
          NextDialogue = 10036032,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Haha, but the alchemists haven't even noticed it yet. Their negligence is our chance. Let me think... we should come up with a secret signal for when the time comes.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC856"
        },
        [10036032] = {
          Camera = "-268.056641,6.759766,219.209229,0.000128,-4.005373,-26.392078,35.000008,1151.087158,false,Manual,2.8",
          ContentFR = "...",
          DialogueId = 10036032,
          FinalCamera = "-268.056641,6.759766,219.209229,0.000128,-4.005373,-26.392078,35.000008,166.311462,false,Manual,2.8",
          GUID = "191FC880",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1003/100360/191FC880"
        },
        [10036033] = {
          ContentFR = "Hé, tu paries sur quel sujet cette fois ?",
          DialogueId = 10036033,
          GUID = "191FC881",
          Subtitle = "Hey, which one do you think it's gonna be this time?",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC881"
        },
        [10036034] = {
          ContentFR = "Impossible à deviner, leurs données sont presque identiques.",
          DialogueId = 10036034,
          GUID = "191FC882",
          Subtitle = "Hard to say — their metrics are almost identical.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC882"
        },
        [10036035] = {
          ContentFR = "J’ai annulé toute ma journée pour ça... Qu’ils ne me déçoivent pas.",
          DialogueId = 10036035,
          GUID = "191FC883",
          Subtitle = "Cleared my whole schedule for this. They'd better not disappoint.",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC883"
        },
        [10036036] = {
          ContentFR = "Héhé héhé... ahah ahah... j’en tremble d’excitation.",
          DialogueId = 10036036,
          GUID = "191FC884",
          Subtitle = "Heeheeheehee... ahahaha... I'm so excited I can barely breathe...",
          VoiceName = "voice/$Locale$/story/1003/100360/191FC884"
        },
        [10036101] = {
          ContentFR = "Le test final commence ! Voyons lequel de vous deux est le véritable chef-d’œuvre !",
          DialogueId = 10036101,
          Duration = 7,
          GUID = "191FD3D2",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "The final test begins! Let's find out which one of you is the ultimate augmented subject!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD3D2"
        },
        [10036102] = {
          ContentFR = "Quoi... !? Ils veulent nous forcer à nous battre l’un contre l’autre !?",
          DialogueId = 10036102,
          Duration = 5,
          GUID = "191FD3FC",
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "What!? They're making us fight each other!?",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD3FC"
        },
        [10036103] = {
          ContentFR = "On dirait bien qu’on n’a plus le choix...",
          DialogueId = 10036103,
          Duration = 4.5,
          GUID = "191FD426",
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "We really don't have a choice, do we?",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD426"
        },
        [10036104] = {
          ContentFR = "Alors il ne reste qu’une chose à faire... <H>au combat !</>",
          DialogueId = 10036104,
          Duration = 3.5,
          GUID = "191FD450",
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Guess not. Bring it on, then!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD450"
        },
        [10036105] = {
          ContentFR = "... ?!",
          DialogueId = 10036105,
          Duration = 1.2,
          GUID = "191FD47A",
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...!?",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD47A"
        },
        [10036106] = {
          ContentFR = "N’oublie pas, tu as une scène qui t’attend. Ne sois pas en retard.",
          DialogueId = 10036106,
          GUID = "191FD4A4",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Remember, you've got a stage waiting for you.",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD4A4"
        },
        [10036107] = {
          ContentFR = "Des promesses impossibles n’ont aucun sens.",
          DialogueId = 10036107,
          GUID = "191FD4CE",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "What's the point of making promises you can't keep?",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD4CE"
        },
        [10036108] = {
          ContentFR = "Elles en ont... Parce qu’un jour, elles pourraient bien être tenues.",
          DialogueId = 10036108,
          GUID = "191FD4F8",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Because someday, they might just be fulfilled.",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD4F8"
        },
        [10036109] = {
          ContentFR = "Sujet 36 ! Qu’est-ce que tu fais !? Sujet en crise ! Je demande du renfort immédiatement !",
          DialogueId = 10036109,
          GUID = "191FD522",
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "36!! What the hell are you doing!? Subject exhibiting extreme instability! Requesting backup!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD522"
        },
        [10036110] = {
          ContentFR = "Quoi... !? Tu ne m’avais jamais dit qu’on s’en sortirait comme ça !",
          DialogueId = 10036110,
          GUID = "191FD54C",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "What...!? You never said anything about making it out like this!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD54C"
        },
        [10036111] = {
          ContentFR = "<I>Kof...</> Je ne reviens jamais sur ma parole...",
          DialogueId = 10036111,
          GUID = "191FD576",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "*coughs* I... never go back on my word...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD576"
        },
        [10036112] = {
          ContentFR = "... Ça y est, c’est ouvert !",
          DialogueId = 10036112,
          GUID = "191FD5A0",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...It's open!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD5A0"
        },
        [10036113] = {
          ContentFR = "P-Professeur... désolé, je ne pensais pas que les sujets pourraient briser l’effet des inhibiteurs...",
          DialogueId = 10036113,
          GUID = "191FD5CA",
          NextDialogue = 10036114,
          SpeakNpcName = "Cp2CharacterName05",
          Subtitle = "P—Professor... I'm sorry! I didn't expect the subjects to resist the suppressant's effect...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD5CA"
        },
        [10036114] = {
          ContentFR = "Une <H>mutation</> inédite... Aucune expérimentation n’avait encore produit cela. Peut-être notre plus grande œuvre !",
          DialogueId = 10036114,
          GUID = "191FD5F4",
          NextDialogue = 10036115,
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "This kind of mutation is unprecedented in any of our test subjects. Fascinating... Perhaps they're our greatest masterpiece yet!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD5F4"
        },
        [10036115] = {
          ContentFR = "Verrouillez toute fuite d’information ! Administrez l’inhibiteur γ de dernière génération ! Je les veux vivants, coûte que coûte !",
          DialogueId = 10036115,
          GUID = "191FD61E",
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Lock down all information! Deploy the latest γ-type suppressant — bring the subject in alive, no matter the cost!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD61E"
        },
        [10036116] = {
          ContentFR = "<I>Kof,</> alors... j’y suis... arrivé... ?",
          DialogueId = 10036116,
          GUID = "191FD648",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036117,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "*coughs* Did I make it...?",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD648"
        },
        [10036117] = {
          ContentFR = "Oui ! Tu l’as fait !",
          DialogueId = 10036117,
          GUID = "191FD672",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036118,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "Yes! You made it!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD672"
        },
        [10036118] = {
          ContentFR = "Alors... tant mieux...",
          DialogueId = 10036118,
          GUID = "191FD69C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036119,
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Great...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD69C"
        },
        [10036119] = {
          ContentFR = "Fuir ? Où croyez-vous aller ? Vous n’avez pas de place dans ce monde ! Vos vies ne servent qu’au champ de bataille ou à nos laboratoires !",
          DialogueId = 10036119,
          GUID = "191FD6C6",
          NextDialogue = 10036120,
          SpeakNpcName = "Cp2CharacterName04",
          Subtitle = "Where do you think you can run off to? Monsters like you have no place in this world — your only purpose is to serve on the battlefield or in a lab!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD6C6"
        },
        [10036120] = {
          ContentFR = "...",
          DialogueId = 10036120,
          GUID = "191FD6F0",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036121,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD6F0"
        },
        [10036121] = {
          ContentFR = "Nous ne sommes pas des monstres... Nous sommes humains !",
          DialogueId = 10036121,
          GUID = "191FD71A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "We're not monsters... We're human!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD71A"
        },
        [10036122] = {
          ContentFR = "Par ici !",
          DialogueId = 10036122,
          GUID = "191FD744",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036123,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "This way!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD744"
        },
        [10036123] = {
          ContentFR = "Ce souffle... du vent ? La liberté... <I>Kof</>",
          DialogueId = 10036123,
          GUID = "191FD76E",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Is this... wind? The air of freedom... *coughs*",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD76E"
        },
        [10036124] = {
          ContentFR = "J’entends de l’eau. Il doit y avoir un conduit vers l’extérieur.",
          DialogueId = 10036124,
          GUID = "191FD798",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10036125,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "I hear water. There must be an outlet leading outside.",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD798"
        },
        [10036125] = {
          ContentFR = "Parfait... <I>Kof</>",
          DialogueId = 10036125,
          GUID = "191FD7C2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 100331,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Thank god... *coughs*",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD7C2"
        },
        [10036126] = {
          Camera = "1359.609375,981.171387,600.210815,0.000034,-15.799866,-145.19664,35.0,100000.0,false,Manual,22.0",
          ContentFR = "On a réussi !",
          DialogueId = 10036126,
          GUID = "191FD7EC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036126.T_Story_Recall_10036126'",
          NextDialogue = 10036127,
          RelatedWikiId = {
            [1] = 407003,
            [2] = 403004,
            [3] = 201024
          },
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "We made it out!",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD7EC"
        },
        [10036127] = {
          ContentFR = "Les égouts de l’académie... Il doit y avoir une bouche d’évacuation vers l’extérieur.",
          DialogueId = 10036127,
          GUID = "191FD816",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036127.T_Story_Recall_10036127'",
          NextDialogue = 10036128,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "This is the academy's drainage tunnels... There must be an outlet leading outside.",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD816"
        },
        [10036128] = {
          ContentFR = "Enfin, nous... sommes libres...",
          DialogueId = 10036128,
          GUID = "191FD840",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036128.T_Story_Recall_10036128'",
          NextDialogue = 10036129,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Can't believe we actually made it... We're... finally free...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD840"
        },
        [10036129] = {
          ContentFR = "Argh !",
          DialogueId = 10036129,
          GUID = "191FD86A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036129.T_Story_Recall_10036129'",
          NextDialogue = 10036130,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName03",
          Subtitle = "Ugh...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD86A"
        },
        [10036130] = {
          ContentFR = "Tu es blessé... Laisse-moi m’occuper de la suite.",
          DialogueId = 10036130,
          GUID = "191FD894",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036130.T_Story_Recall_10036130'",
          NextDialogue = 10036131,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "You're hurt... I'll take care of everything from here.",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD894"
        },
        [10036131] = {
          ContentFR = "D’abord, trouvons une cachette...",
          DialogueId = 10036131,
          GUID = "191FD8BE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036131.T_Story_Recall_10036131'",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          Subtitle = "First, we need to find a place to hide...",
          VoiceName = "voice/$Locale$/story/1003/100361/191FD8BE"
        },
        [10036201] = {
          Camera = "-112.558594,-18.889648,137.671387,0.000057,0.198957,165.584488,35.0,100000.0,false,Manual,22.0",
          ContentFR = "Alors... ce drôle de théâtre dans les égouts, c’était vous qui l’aviez monté peu à peu ?",
          DialogueId = 10036201,
          FinalCamera = "-112.96875,-20.488281,147.573242,0.000057,0.198957,165.584488,35.0,100000.0,false,Manual,22.0",
          GUID = "191FE43A",
          LookAt = {
            [1] = "100304:n(100327)",
            [2] = "100001:n(100327)",
            [3] = "200002:n(100327)",
            [4] = "200021:n(100327)",
            [5] = "100327:n(100304)"
          },
          NextDialogue = 10036202,
          RelatedWikiId = {
            [1] = 407003,
            [2] = 403004,
            [3] = 201024
          },
          SpeakNpcId = 200021,
          Subtitle = "So you were the ones who built that strange stage in the sewers?",
          TalkActionId = {
            [1] = "200021:Talk02_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100362/191FE43A"
        },
        [10036202] = {
          Camera = "602.476562,-249.944336,360.538574,0.000065,-25.800716,151.990204,20.0,100000.0,false,Manual,22.0",
          ContentFR = "Impossible... pourquoi Blues... pourquoi toi...",
          DialogueId = 10036202,
          FacialId = {
            [1] = "100304:Shock01"
          },
          GUID = "191FE464",
          LookAt = {
            [1] = "100304:n(100327)",
            [2] = "100001:n(100304)",
            [3] = "200002:n(100304)",
            [4] = "200021:n(100304)"
          },
          NextDialogue = 10036203,
          Scripts = "MoveTo{ActorId{100304},MoveSpeed{120},TargetPoint{\"lise_56_walk\"}}",
          SpeakNpcId = 100304,
          Subtitle = "How... why... how could this happen to you... Blues...",
          TalkActionId = {
            [1] = "200021:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE464"
        },
        [10036203] = {
          Camera = "255.566406,-24.741699,131.422363,0.000058,0.598905,163.386917,35.0,100000.0,false,Manual,22.0",
          ContentFR = "... Tu as encore mal ?",
          DialogueId = 10036203,
          FacialId = {
            [1] = "100304:Disappoint01"
          },
          FinalCamera = "223.371094,-15.542969,131.395508,0.000058,1.398898,162.986725,35.0,100000.0,false,Manual,22.0",
          GUID = "191FE48E",
          LookAt = {
            [1] = "100304:n(100327)"
          },
          NextDialogue = 10036204,
          SpeakNpcId = 100304,
          Subtitle = "...Does it still hurt?",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100362/191FE48E"
        },
        [10036204] = {
          Camera = "-10.363281,-8.108887,102.920898,0.000115,20.997046,15.209096,25.000006,495.125,false,Manual,2.799999",
          ContentFR = "Je... ça va.",
          DialogueId = 10036204,
          GUID = "191FE4B8",
          NextDialogue = 10036205,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "...I'm fine.",
          TalkActionId = {
            [1] = "100327:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE4B8"
        },
        [10036205] = {
          Camera = "90.679688,-10.201172,155.186035,0.000029,19.198732,13.00046,25.000006,233.5448,false,Manual,2.8",
          ContentFR = "Hélas, le destin ne nous a accordé qu’une brève pitié. Échapper à l’Académie... ce n’était pas le commencement d’une nouvelle vie, mais... la fin.",
          DialogueId = 10036205,
          GUID = "191FE4E2",
          NextDialogue = 10036206,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "But fate only gave us a fleeting moment of mercy — escaping the academy wasn't the start of a new life... but the beginning of the end.",
          TalkActionId = {
            [1] = "100327:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE4E2"
        },
        [10036206] = {
          ContentFR = "Pendant la fuite, les alchimistes... leur nouvel inhibiteur... a détruit ma gorge... et ravagé mon esprit...",
          DialogueId = 10036206,
          GUID = "191FE50C",
          LookAt = {
            [1] = "100327:n(100001)"
          },
          NextDialogue = 10036207,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "During our escape... the alchemists... their new suppressant ruined my voice... and messed up our minds...",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE50C"
        },
        [10036207] = {
          ContentFR = "Souvent, nous sombrions... hors de contrôle... Et mon ami... <H>le sujet 36</>... est parti avant moi.",
          DialogueId = 10036207,
          GUID = "191FE536",
          LookAt = {
            [1] = "100327:n(100327)"
          },
          NextDialogue = 10036208,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "We couldn't control ourselves... we'd go berserk from time to time... And my friend... 36... has already left this world before me.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE536"
        },
        [10036208] = {
          Camera = "-178.277344,-33.839355,138.938477,0.00009,5.597422,154.782913,50.0,239.778275,false,Manual,22.0",
          ContentFR = "Tch. J’ai toujours su que ces alchimistes étaient des monstres. Mais là... s’allier avec la VIᵉ Légion, piéger des Charons doués en magie, les transformer en cobayes... ça dépasse l’ignoble.",
          DialogueId = 10036208,
          FacialId = {
            [1] = "200021:Angry01"
          },
          GUID = "191FE560",
          NextDialogue = 10036209,
          SpeakNpcId = 200021,
          Subtitle = "Ugh, I always knew those alchemists were wicked scum, but this... this is cruelty on an entirely different level. And to think they had the gall to go in cahoots with the 6th Legion, luring Charons with strong magical aptitude just to turn them into test subjects...",
          TalkActionId = {
            [1] = "200021:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE560"
        },
        [10036209] = {
          Camera = "201.75,1.508789,159.896973,-6.000039,-11.003229,172.177917,25.000006,100000.0,false,Manual,22.0",
          ContentFR = "Écoute-moi bien, ma sœur.",
          DialogueId = 10036209,
          FacialId = {
            [1] = "100304:Shock01"
          },
          GUID = "191FE58A",
          NextDialogue = 10036210,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Listen, Sister.",
          TalkActionId = {
            [1] = "100304:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE58A"
        },
        [10036210] = {
          Camera = "55.476562,-24.161621,154.890137,-6.00001,14.795302,12.594482,25.000002,100000.0,false,Manual,22.0",
          ContentFR = "La VIᵉ Légion... nous a trompés avec ce titre... de <H>Charon Couronné</>.",
          DialogueId = 10036210,
          FinalCamera = "55.476562,-24.161621,154.890137,-6.000008,17.595236,12.594818,25.000002,100000.0,false,Manual,22.0",
          GUID = "191FE5B4",
          NextDialogue = 10036211,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "The 6th Legion... they use the title of \"Laurelled Charon\"... as a lure to deceive us.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100362/191FE5B4"
        },
        [10036211] = {
          Camera = "340.351562,-75.352051,293.490234,0.00004,-36.005245,147.978653,25.000002,100000.0,false,Manual,22.0",
          ContentFR = "Quitte... la Légion.",
          DialogueId = 10036211,
          GUID = "191FE5DE",
          NextDialogue = 10036212,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "LEAVE... the Legion.",
          TalkActionId = {
            [1] = "100327:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE5DE"
        },
        [10036212] = {
          Camera = "340.351562,-75.352051,293.490234,0.00004,-36.005245,147.978653,25.000002,100000.0,false,Manual,22.0",
          ContentFR = "Trouve un endroit sûr, paisible, et—",
          DialogueId = 10036212,
          GUID = "191FE608",
          NextDialogue = 10036213,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Find a quiet, safe place... and take care of yourse—",
          TalkActionId = {
            [1] = "100327:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100362/191FE608"
        },
        [10036213] = {
          Camera = "227.824219,31.842285,181.181152,0.000023,-16.404352,178.979095,45.0,100000.0,false,DoNotOverride,22",
          ContentFR = "Et toi ? Qu’est-ce que tu vas devenir, toi ?",
          DialogueId = 10036213,
          FacialId = {
            [1] = "100304:Shock01"
          },
          GUID = "191FE632",
          NextDialogue = 10036214,
          Scripts = "CameraMoveTo{_delay{2},TargetPosition{\"189.578125,-871.764404,19.383301,-0.0,6.995186,93.378288,25.0,100000.0,false,DoNotOverride,22\"},duration{0}}",
          SpeakNpcId = 100304,
          Subtitle = "What about you!?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE632"
        },
        [10036214] = {
          Camera = "86.808594,-88.199707,320.100586,0.000018,-29.605869,33.985477,25.0,100000.0,false,Manual,22.0",
          ContentFR = "Moi...",
          DialogueId = 10036214,
          FinalCamera = "4.820312,-143.472656,376.284668,0.000023,-32.005917,34.185921,25.0,100000.0,false,Manual,22.0",
          GUID = "191FE65C",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "I...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100362/191FE65C"
        },
        [10036215] = {
          ContentFR = "Cinq jours plus tôt, sortie des égouts",
          DialogueId = 10036215,
          GUID = "191FE686",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          Subtitle = "Five Days Ago, Sewer Exit",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE686"
        },
        [10036216] = {
          ContentFR = "Je pensais... que tu allais rester inconscient... jusqu’à la fin du monde.",
          DialogueId = 10036216,
          GUID = "191FE6B0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036217,
          RelatedWikiId = {
            [1] = 407003,
            [2] = 403004,
            [3] = 201024
          },
          SnapShot = "MEMORY",
          Subtitle = "I thought... you were going to... stay unconscious... until the end of the world.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE6B0"
        },
        [10036217] = {
          ContentFR = "C’est ma faute. Si j’étais arrivé plus tôt, ils n’auraient jamais pu te...",
          DialogueId = 10036217,
          GUID = "191FE6DA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036218,
          SnapShot = "MEMORY",
          Subtitle = "It's all my fault. If I'd got here sooner, you wouldn't have been...",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE6DA"
        },
        [10036218] = {
          ContentFR = "Non. On n’avait aucune chance. Mes instants de lucidité... se réduisent de plus en plus.",
          DialogueId = 10036218,
          GUID = "191FE704",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036219,
          SnapShot = "MEMORY",
          Subtitle = "We wouldn't. We wouldn't have stood a chance. My moments of clarity... are slipping away.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE704"
        },
        [10036219] = {
          ContentFR = "Peut-être qu’au fond, tu avais raison... Mon cœur... est déjà devenu celui d’un monstre.",
          DialogueId = 10036219,
          GUID = "191FE72E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036220,
          SnapShot = "MEMORY",
          Subtitle = "Or perhaps, like you said... my heart has already turned into... that of a monster.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE72E"
        },
        [10036220] = {
          ContentFR = "Si toi tu es un monstre... alors moi, qu’est-ce que je suis ?",
          DialogueId = 10036220,
          GUID = "191FE758",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036221,
          SnapShot = "MEMORY",
          Subtitle = "If you're a monster... then what does that make me?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE758"
        },
        [10036221] = {
          ContentFR = "Cette lumière qu’on poursuivait... elle était si éclatante, si haute... inaccessible.",
          DialogueId = 10036221,
          GUID = "191FE782",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030101.T_Story_Recall_10030101'",
          NextDialogue = 10036222,
          SnapShot = "MEMORY",
          Subtitle = "We chased so hard to catch the light, the dazzling light... only to find it's so... unreachable in the end.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE782"
        },
        [10036222] = {
          ContentFR = "Si quelque chose est hors d’atteinte... il suffit de l’abattre au sol.",
          DialogueId = 10036222,
          GUID = "191FE7AC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036223,
          Scripts = [[
SEQ
{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt03/0080_story_the_abandoned_theme"},RelatedRegionId{101103}}
}]],
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "If something is unreachable, why not pull it down to the ground?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE7AC"
        },
        [10036223] = {
          ContentFR = "Attention, <H>il est empoisonné</>... ! Qui êtes-vous ?",
          DialogueId = 10036223,
          GUID = "191FE7D6",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036224,
          SnapShot = "MEMORY",
          Subtitle = "Stay back — his body is toxic... Who are you?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE7D6"
        },
        [10036224] = {
          ContentFR = "J’ai de nombreux noms, de nombreux visages. Mais ce ne sont que des masques. La vérité, c’est que nous avons tous été rejetés par les dieux.",
          DialogueId = 10036224,
          GUID = "191FE800",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036225,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "I have many names, many faces. But in the end, they're all just labels. No matter how those labels shift or change, one truth remains — we have been forsaken by the gods.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE800"
        },
        [10036225] = {
          ContentFR = "Et toi qui es si lucide... tu devrais déjà savoir qui je suis.",
          DialogueId = 10036225,
          GUID = "191FE82A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036226,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Now, someone as sharp as you should already know who I am.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE82A"
        },
        [10036226] = {
          ContentFR = "Je suis venu vous inviter. Rejoignez-nous. Arrachons les Solariens de leurs hauteurs... qu’ils goûtent enfin à la colère des Charons.",
          DialogueId = 10036226,
          GUID = "191FE854",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036227,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "I'm here to extend an invitation. Join us. Drag the untouchable Solas down to the ground, and let them feel the wrath of Charons.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE854"
        },
        [10036227] = {
          ContentFR = "Ne refusez pas si vite. Pensez à ce que l’Empire vous a infligé, des mensonges enjolivés pour vous attirer, des tortures cruelles pour vous briser, et une désespérance infinie pour vous étouffer.",
          DialogueId = 10036227,
          GUID = "191FE87E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036228,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Don't rush to reject me. Reflect on what the Empire has done to you. They lured you in with sweet lies, broke you with merciless torture, and buried you under an ocean of despair.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE87E"
        },
        [10036228] = {
          ContentFR = "Qu’y a-t-il au bout de cette route ? Devenir un Charon Couronné ? Une vie meilleure ? Des rêves accomplis ?",
          DialogueId = 10036228,
          GUID = "191FE8A8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036229,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "And what lies at the end of this path? Becoming a Laurelled Charon? A better life? Greater dreams fulfilled?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE8A8"
        },
        [10036229] = {
          ContentFR = "Non ! Ce qui vous attend, c’est la mort, vos os rongés par les Solariens, la traque des traîtres parmi vos pairs, et l’oubli dans quelque recoin sordide.",
          DialogueId = 10036229,
          GUID = "191FE8D2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036230,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Absolutely not! What awaits is a slow death — your bones picked clean by the Sola elites, hunted by traitors among our own kind, until you're discarded like trash in some forgotten corner.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE8D2"
        },
        [10036230] = {
          ContentFR = "Avec une promesse creuse, ils poussent des Charons comme vous, comme moi, dans l’abîme.",
          DialogueId = 10036230,
          GUID = "191FE8FC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036231,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "With a single empty promise, they lure aspiring Charons like you and me straight into the abyss.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE8FC"
        },
        [10036231] = {
          ContentFR = "Tant que les mensonges de la VIᵉ Légion et de l’Académie d’Alchimie perdurent, les Charons de Givrelac tomberont les uns après les autres dans la même tragédie.",
          DialogueId = 10036231,
          GUID = "191FE926",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036232,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "As long as the 6th Legion and the Alchemy Academy's web of lies remains intact, Charons of Icelake will continue walking this path to ruin, marching straight into the same tragedy as you... again and again.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE926"
        },
        [10036232] = {
          ContentFR = "... !",
          DialogueId = 10036232,
          GUID = "191FE950",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036233,
          SnapShot = "MEMORY",
          Subtitle = "...!",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE950"
        },
        [10036233] = {
          ContentFR = "L’Empire nous a volé notre passé. Il nous laisse croupir au présent. Allons-nous lui abandonner aussi l’avenir ? Laisser ces bêtes écraser ce qui nous est cher ?",
          DialogueId = 10036233,
          GUID = "191FE97A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036234,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "The Empire stripped us of what we once had and left us trapped in this miserable present. Are we really going to let them crush everything we hold dear without putting up a fight?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE97A"
        },
        [10036234] = {
          ContentFR = "Regarde-nous. L’Empire a convoité notre force, nous a enchaînés comme des bêtes, transformés en de véritables démons.",
          DialogueId = 10036234,
          GUID = "191FE9A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036235,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Look at us. The Empire coveted our strength, shackled us like animals, and twisted us into grotesque monsters — into real demons.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE9A4"
        },
        [10036235] = {
          ContentFR = "Mais aujourd’hui, ces chaînes sont brisées. Alors n’est-ce pas l’heure de leur planter nos crocs dans la gorge ?",
          DialogueId = 10036235,
          GUID = "191FE9CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036236,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "But now, we've broken free of those chains. Isn't it time to turn their own weapons against them? Time we made them pay?",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE9CE"
        },
        [10036236] = {
          ContentFR = "Qu’ils se souviennent de nous, qu’ils ressentent notre douleur, qu’ils ne convoitent plus jamais ce qui est à nous ! Qu’ils se repentent avec leur sang ! Que tout l’Empire hurle nos noms !",
          DialogueId = 10036236,
          GUID = "191FE9F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036237,
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "Let them tremble at the mere thought of us. Let them feel the pain we've endured. Make them never dare to covet what we hold dear again! Let them repent with their blood and remember us for eternity. Let the entire Empire scream our names in terror!",
          VoiceName = "voice/$Locale$/story/1003/100362/191FE9F8"
        },
        [10036237] = {
          ContentFR = "<W>Les Déchus</>...",
          DialogueId = 10036237,
          GUID = "191FEA22",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          NextDialogue = 10036238,
          RelatedWikiId = {
            [1] = 101004
          },
          SnapShot = "MEMORY",
          Subtitle = "The Forsakens...",
          VoiceName = "voice/$Locale$/story/1003/100362/191FEA22"
        },
        [10036238] = {
          ContentFR = "Appelez cela vengeance si vous voulez. Moi j’y vois une mission, protéger les nôtres, un devoir que nous, \"démons\" devons remplir. Purger la cité intérieure de ses ordures, offrir à vos familles un avenir propre et sûr.",
          DialogueId = 10036238,
          GUID = "191FEA4C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030102.T_Story_Recall_10030102'",
          SnapShot = "MEMORY",
          SpeakNpcId = 100326,
          SpeakNpcName = "Cp2CharacterName08",
          Subtitle = "You may call it vengeance, but I call it protection. We \"demons\" bear a duty to protect our kind. We'll rid the inner city of its \"filth\" and give your loved ones the cleaner, brighter future they deserve.",
          VoiceName = "voice/$Locale$/story/1003/100362/191FEA4C"
        },
        [10036239] = {
          Camera = "145.113281,-134.397461,226.663574,-0.000549,-1.601467,54.124352,35.000011,100000.0,false,Manual,22.0",
          ContentFR = "<I>Les Déchus...</>",
          DialogueId = 10036239,
          DisableMouth = 1,
          FinalCamera = "149.515625,-128.306641,226.455078,-0.000549,-1.601467,54.124352,35.000011,100000.0,false,Manual,22.0",
          GUID = "191FEA76",
