        },
        [10036508] = {
          Camera = "-0.925781,-102.438721,6.324219,0.000062,27.593143,90.266426,35.0,100000.0,false,Manual,22.0",
          ContentFR = "Te souviens-tu du serment, le jour où tu as rejoint la Légion sous l’étendard des Trois Loups ? « Offrir ma vie à Sa Majesté. Être un soldat loyal d’Hyperborea, jusqu’à mon dernier souffle. »",
          DialogueId = 10036508,
          FinalCamera = "-0.925781,-102.438721,6.324219,0.000062,27.593143,90.266426,35.0,100000.0,false,Manual,22.0",
          GUID = "19201698",
          LookAt = {
            [1] = "100304:n(100310)"
          },
          NextDialogue = 10036509,
          SpeakNpcId = 100310,
          Subtitle = "Do you remember the oath you swore under the banner of the Three Wolves? \"To dedicate my life to His Majesty, to become a loyal soldier of Hyperborea, and to serve until death.\"",
          TalkActionId = {
            [1] = "100310:Angry01_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/19201698"
        },
        [10036509] = {
          Camera = "-0.925781,-102.438721,6.324219,0.000062,27.593143,90.266426,35.0,100000.0,false,Manual,22.0",
          ContentFR = "Major Lynn disait de toi que tu étais un talent rare, malgré ton sang de Charon. Elle voulait même te recommander pour la capitale après cette affaire.",
          DialogueId = 10036509,
          GUID = "192016C2",
          NextDialogue = 10036510,
          SpeakNpcId = 100310,
          Subtitle = "Major Lynn spoke highly of you — she considered you a very promising soldier, despite your Charon bloodline. She was even planning to recommend you for promotion to the capital once this case was resolved.",
          VoiceName = "voice/$Locale$/story/1003/100365/192016C2"
        },
        [10036510] = {
          Camera = "53.857422,378.744141,188.148438,0.000066,-9.20508,-99.947792,20.0,100000.0,false,Manual,22.0",
          ContentFR = "La XIIIᵉ Légion chérit ses talents. Je t’offre une dernière chance de prouver ta loyauté. Écarte-toi.",
          DialogueId = 10036510,
          FinalCamera = "99.798828,366.275879,188.148438,0.000071,-8.005063,-109.145584,20.0,100000.0,false,Manual,22.0",
          GUID = "192016EC",
          NextDialogue = 10036511,
          SpeakNpcId = 100310,
          Subtitle = "The 13th Legion values its ace soldiers. I'm giving you one last chance to prove your loyalty to Hyperborea. Step aside.",
          TalkActionId = {
            [1] = "100310:Angry01_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100365/192016EC"
        },
        [10036511] = {
          Camera = "99.798828,366.275879,188.148438,0.000071,-8.005063,-109.145584,20.0,100000.0,false,Manual,22.0",
