          DialogueId = 10036511,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          GUID = "19201716",
          LookAt = {
            [1] = "100304:n(100304)",
            [2] = "100001:n(100304)",
            [3] = "200021:n(100304)"
          },
          NextDialogue = 10036512,
          SpeakNpcId = 100304,
          Subtitle = "...No.",
