          FinalCamera = "428.052734,-715.745728,114.421875,0.000065,8.791054,-174.572998,50.000008,328.959259,false,Manual,2.8",
          GUID = "1920198C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036526.T_Story_Recall_10036526'",
          LookAt = {
            [1] = "200021:p(tuosi02_waist)"
          },
          NextDialogue = 10036527,
          SpeakNpcId = 100001,
          Subtitle = "Those specks... They're the same as the ones left by Lynn's final shot during the capture. That's when Outsider came up with a theory...",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100365/1920198C"
        },
        [10036527] = {
          Camera = "-161.447266,-786.827393,304.128906,0.000024,-24.4046,19.585703,35.0,6522.728027,false,Manual,2.8",
          ContentFR = "Et si ce tir... n’avait pas eu pour but de <H>tuer</>, mais de <H>marquer</> la cible ?",
          DialogueId = 10036527,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "192019B6",
          NextDialogue = 10036528,
          SpeakNpcId = 100001,
          Subtitle = "Perhaps Lynn's shot wasn't meant to kill the target, but to track him...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/192019B6"
        },
        [10036528] = {
          Camera = "-161.447266,-786.827393,304.128906,0.000024,-24.4046,19.585703,35.0,6522.728027,false,Manual,2.8",
          ContentFR = "Et si l’avertissement de Lynn, « Ne faites rien d’inutile », n’était pas du tout de la négligence... mais pour éviter de faire fuir la proie ?",
          DialogueId = 10036528,
          GUID = "192019E0",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 10036529,
          SpeakNpcId = 100001,
          Subtitle = "Her last warning to us — \"Don't overstep your place\" — might not have been an excuse for her negligence or inaction... She just didn't want us to scare off the prey!",
          VoiceName = "voice/$Locale$/story/1003/100365/192019E0"
        },
        [10036529] = {
          Camera = "-161.447266,-786.827393,304.128906,0.000024,-24.4046,19.585703,35.0,6522.728027,false,Manual,2.8",
          ContentFR = "Alors... cette grande cérémonie d’adieux de la XIIIᵉ Légion, c’était juste une mise en scène, un appât pour le meurtrier. En réalité... ils n’ont jamais quitté la cité, n’est-ce pas ?",
          DialogueId = 10036529,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "19201A0A",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "100001:n(100327)"
          },
          NextDialogue = 10036530,
          SpeakNpcId = 100001,
          Subtitle = "And that grand send-off ceremony for the 13th Legion? It was nothing but a show to trick the target. They never actually left, did they?",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201A0A"
        },
        [10036530] = {
          Camera = "144.035156,713.565552,-0.386719,7.216263,5.790484,-96.780365,50.0,100000.0,false,Manual,22.0",
          ContentFR = "{性别:Futé, le morveux|Futée, la morveuse}. Oui... Major Lynn avait découvert que la \"Traque aux Charons\" s’était étendue jusque dans la cité intérieure. Trop gros pour n’être qu’un hasard, elle a vite compris que les Déchus devaient tirer les ficelles.",
          DialogueId = 10036530,
          FinalCamera = "143.378906,713.643433,2.578125,7.216278,5.790484,-96.780365,50.0,100000.0,false,Manual,22.0",
          GUID = "19201A34",
          LookAt = {
            [1] = "100304:n(100310)",
            [2] = "100001:n(100310)",
            [3] = "200021:n(100310)",
            [4] = "100327:n(100310)"
          },
          NextDialogue = 10036531,
          SpeakNpcId = 100310,
          Subtitle = "Heh... You're one crafty little rat, aren't you? That's right. After the \"Charon Hunt\" spread to the inner city, Major Lynn suspected that the Forsakens might have been pulling the strings.",
          TalkActionId = {
            [1] = "100304:Explain02_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1003/100365/19201A34"
        },
        [10036531] = {
          Camera = "94.964844,-69.758667,103.863281,7.231426,-8.009886,105.632515,50.000011,100000.0,false,Manual,22.0",
          ContentFR = "Cette opération n’avait qu’un but, se servir du meurtrier comme d’un appât, une crevette pour ferrer le gros poisson. En un coup, écraser toute la présence des Déchus autour de Givrelac.",
          DialogueId = 10036531,
          GUID = "19201A5E",
          NextDialogue = 10036532,
          SpeakNpcId = 100310,
          Subtitle = "The whole capture operation was just bait — a tiny shrimp to lure out the real big fish — so we could catch the Forsakens and wipe out their network around Icelake.",
          VoiceName = "voice/$Locale$/story/1003/100365/19201A5E"
        },
        [10036532] = {
          Camera = "94.964844,-69.758667,103.863281,7.231426,-8.009886,105.632515,50.000011,100000.0,false,Manual,22.0",
          ContentFR = "Vous n’aviez rien à voir avec tout ça. Mais en vous opposant à la Légion, vous êtes devenus des ennemis de l’Empire. Fuyez si vous voulez... le Major Lynn vous traquera.",
          DialogueId = 10036532,
          GUID = "19201A88",
          NextDialogue = 10036533,
          SpeakNpcId = 100310,
          Subtitle = "You weren't supposed to be involved. But now that you've stood against the Legion, you've made yourselves enemies of the Empire. Run if you want — Major Lynn will hunt you down.",
          VoiceName = "voice/$Locale$/story/1003/100365/19201A88"
        },
        [10036533] = {
          Camera = "57.617188,-266.536926,76.441406,0.000157,15.18672,-106.154465,25.000002,100000.0,false,Manual,22.0",
          ContentFR = "... J’irai avec vous. J’affronterai le Major Lynn en face, et je lui expliquerai toute la vérité derrière cette \"Traque aux Charons\". Elle est intelligente, juste... elle saura écouter notre version des faits.",
          DialogueId = 10036533,
          FacialId = {
            [1] = "100304:Confident01"
          },
          GUID = "19201AB2",
          NextDialogue = 10036590,
          SpeakNpcId = 100304,
          Subtitle = "...I'll go with you. I'll face Officer Lynn myself and explain the truth behind the \"Charon Hunt.\" She's sharp and reasonable — she'll see our side.",
          TalkActionId = {
            [1] = "100304:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201AB2"
        },
        [10036534] = {
          Camera = "57.617188,-266.536926,76.441406,0.000157,15.18672,-106.154465,25.000002,100000.0,false,Manual,22.0",
          ContentFR = "Blues... pars. Quitte cet endroit. Pars vers le nord... franchis les Monts Vidofnir, au-delà d’Hyperborea. Plus loin encore, dans le grand nord... là-bas, peut-être... il restera une chance de survivre.",
          DialogueId = 10036534,
          FacialId = {
            [1] = "100304:Unhappy01"
          },
          GUID = "19201ADC",
          LookAt = {
            [1] = "100327:n(100304)",
            [2] = "200021:n(100304)"
          },
          NextDialogue = 10036535,
          Scripts = [[
PARA{
CameraMoveTo{_delay{2},TargetPosition{"57.617188,-266.536926,76.441406,0.000165,15.386653,-100.15535,25.000006,100000.0,false,Manual,22.0"},duration{2}},
SEQ{
PlayAnimation{ActorId{100304},AnimationId{"Explain02_End"},Duration{1}},
LookAt{LookAtDescription{"100304:n(100304)"}},
TurnTo{TurnToDescription{"100304:p(-160)"}},
LookAt{LookAtDescription{"100304:n(100327)"}}
}
}]],
          SpeakNpcId = 100304,
          Subtitle = "Blues, leave. Get far away from here. Head north — beyond the Vidofnir Mountains, beyond Hyperborea's reach. Go to the far north... Perhaps... you'll find a place where you can survive.",
          VoiceName = "voice/$Locale$/story/1003/100365/19201ADC"
        },
        [10036535] = {
          Camera = "49.683594,-662.985046,208.816406,0.000342,11.184892,-92.797089,25.000006,100000.0,false,Manual,22.0",
          ContentFR = "... D’accord. Mais, ma sœur... promets-moi une chose, toi aussi.",
          DialogueId = 10036535,
          GUID = "19201B06",
          LookAt = {
            [1] = "100304:n(100327)"
          },
          NextDialogue = 10036536,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "...Alright, I'll leave. But, Sister... can you promise me something too?",
          TalkActionId = {
            [1] = "100327:Agree"
          },
          VoiceName = "voice/$Locale$/story/1003/100365/19201B06"
        },
        [10036536] = {
          Camera = "4.595703,-794.21521,263.113281,0.000379,-25.013517,80.21476,25.000006,405.778778,false,Manual,6.0",
          ContentFR = "Quoi qu’il arrive... tiens bon... et vis.",
          DialogueId = 10036536,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "19201B30",
          Scripts = "MoveTo{_delay{1},ActorId{100327},MoveSpeed{90},TargetPoint{\"tuosi_61_walk\"}}",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "No matter what happens... be brave... and live on.",
          VoiceName = "voice/$Locale$/story/1003/100365/19201B30"
        },
        [10036537] = {
          Camera = "74.642578,-746.150818,201.730469,0.000171,-10.817749,163.628052,35.000011,100000.0,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Vous avez attaqué... la Légion. Dorénavant, il ne vous attend plus qu’une torture sans fin... ou la mort.",
          DialogueId = 10036537,
          FacialId = {
            [1] = "100304:Close"
          },
          FinalCamera = "74.642578,-746.150818,201.730469,0.000159,-12.017519,96.027672,35.000011,100000.0,false,Manual,22.0",
