          GUID = "19201BAE",
          LookAt = {
            [1] = "100327:n(100001)"
          },
          NextDialogue = 10036540,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Phoxhunters of Icelake... may I entrust her to you...?",
          VoiceName = "voice/$Locale$/story/1003/100365/19201BAE"
        },
        [10036540] = {
          Camera = "163.320312,-784.116699,255.972656,0.000098,-19.430269,172.310211,35.000015,474.33847,false,Manual,4.0",
          ContentFR = "Et toi, alors ?",
          DialogueId = 10036540,
          GUID = "19201BD8",
