          ContentFR = "Alors continue de fuir. Tant que tu es en vie, il y a toujours une issue.",
          DialogueId = 10036542,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "19201C2C",
          LookAt = {
            [1] = "100001:n(100327)",
