          },
          NextDialogue = 10036587,
          Scripts = "PlayAnimation{_delay{1},ActorId{100001},AnimationId{\"Angry01_Start\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "Then keep running. As long as you're alive, there's always a way.",
          VoiceName = "voice/$Locale$/story/1003/100365/19201C2C"
        },
        [10036543] = {
          Camera = "21.552734,-1753.842163,6.808594,0.000086,-2.626064,89.10537,35.000015,100000.0,false,Manual,22.0",
          ContentFR = "Pars. Tu es une bonne personne. Tout comme lui.",
          DialogueId = 10036543,
          FinalCamera = "21.552734,-1753.842163,6.808594,0.000088,7.573928,88.905312,35.000015,100000.0,false,Manual,22.0",
          GUID = "19201C56",
          LookAt = {
