        [10036580] = {
          Camera = "-382.453125,420.339905,15.285156,-0.001373,12.766176,-79.718773,11.880002,37.379047,false,Manual,3",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Si je... modifie la forme de leurs blessures...",
          DialogueId = 10036580,
          FinalCamera = "-382.085938,420.410706,6.472656,-0.001375,12.966178,-79.119835,11.88,79.454002,false,Manual,3",
          GUID = "19202268",
          NextDialogue = 10036586,
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "If I... tamper with the shapes... of their wounds...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1003/100365/19202268"
        },
        [10036581] = {
          Camera = "329.916016,-1354.722534,282.871094,10.819282,-9.806095,108.059669,25.000002,1660.609375,false,Manual,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "J-Je ne peux plus bouger... Vous... ! Et toi... traîtresse qui a vendu les siens !",
          DialogueId = 10036581,
          FacialId = {
            [1] = "100304:Angry01"
          },
          FinalCamera = "315.181641,-1309.563599,274.621094,10.818109,-9.806095,108.059586,25.0,100000.0,false,Manual,22.0",
          GUID = "1920190E",
          LookAt = {
            [1] = "100310:n(100304)"
          },
          NextDialogue = 10036524,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"},RelatedRegionId{101901}}",
          SpeakNpcId = 100310,
          Subtitle = "Guess this is it... You rotters... And you — you sneaky turncoat!",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1003/100365/1920190E"
        },
