          ContentFR = "La vérité... sur la VIᵉ Légion ! Pourquoi l’avoir cachée !?",
          DialogueId = 10036808,
          FinalCamera = "-224.714844,-698.029907,511.519531,0.000098,-19.010103,78.794853,40.000034,1104.988525,false,Manual,1.614437",
          GUID = "192047D0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036807.T_Story_Recall_10036807'",
          NextDialogue = 10036809,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Why didn't you reveal the truth... about the 6th Legion...!?",
          TalkActionId = {
            [1] = "100327:Angry01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100368/192047D0"
        },
        [10036809] = {
          Camera = "-183.076172,270.792358,207.304688,0.00035,-33.808716,50.934616,45.000011,1107.910645,false,DoNotOverride,2.743569",
          ContentFR = "...",
