        [10036812] = {
          Camera = "-150.0,-257.0,306.800781,0.000025,27.593559,-86.447357,40.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "... Une mission qu’on doit accomplir, coûte que coûte... Je vois.",
