          ContentFR = "« ...Quelque chose que je dois absolument accomplir ? »",
          DialogueId = 10036902,
          GUID = "1920573C",
          NextDialogue = 10036903,
          SpeakNpcId = 100312,
          Subtitle = "\"Something I must do...?\"",
