          ContentFR = "« Un but que tu poursuis envers et contre tout. Nous... on appelle ça un rêve. »",
          DialogueId = 10036903,
          FacialId = {
            [1] = "100357:Happy01"
          },
          FinalCamera = "186.626953,551.218262,-293.175781,0.000243,5.806268,-32.18647,60.0,119.689644,false,Manual,8.0",
          GUID = "19205766",
          NextDialogue = 10036904,
          SpeakNpcId = 100357,
          Subtitle = "\"Something you'd do anything to fulfil. We usually call it a 'dream.'\"",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1003/100369/19205766"
        },
        [10036904] = {
