        },
        [10036905] = {
          Camera = "-161.794922,25.292114,-384.535156,0.000118,27.330563,43.256008,25.0,449.12384,false,DoNotOverride,3.005529",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "« De me tenir sous les projecteurs... au centre de la scène. D’entendre les applaudissements... n’éclater que pour moi. »",
          DialogueId = 10036905,
          FacialId = {
            [1] = "100312:Happy01"
          },
          FinalCamera = "-95.255859,87.588867,-327.082031,0.000117,27.330563,43.656006,17.000002,449.12384,false,DoNotOverride,3.005529",
          GUID = "192057BA",
          Scripts = "PlayAnimation{_delay{8},ActorId{100312},AnimationId{\"Talk01_Start\"},Duration{2}},\n",
          SpeakNpcId = 100312,
          Subtitle = "\"To stand in the spotlights... at the very centre of the stage. To feel the thunder of applause... just for me.\"",
          TalkActionId = {
            [1] = "100312:Explain02_End"
          },
          ToFinalCameraBlendTime = 18,
          VoiceName = "voice/$Locale$/story/1003/100369/192057BA"
