        },
        [10037006] = {
          Camera = "116.341797,-923.589355,151.980469,0.000001,-1.547454,-123.344849,50.000008,84.640083,false,Manual,5.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Mon... tour d’entrer en scène ?",
          DialogueId = 10037006,
          FinalCamera = "116.341797,-923.589355,152.863281,0.000001,-1.547454,-123.344849,50.000008,84.640083,false,Manual,5.0",
          GUID = "1920684C",
          NextDialogue = 10037007,
          SpeakNpcId = 100312,
          Subtitle = "My turn... to take the stage?",
          TalkActionId = {
            [1] = "100312:Sigh_End"
