          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1003/100370/1920684C"
        },
        [10037007] = {
          Camera = "524.496094,-71.344421,57.726562,0.000236,0.241358,-133.546417,22.0,449.12384,false,DoNotOverride,3.005529",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Bien sûr. C’est le dernier acte de <I>Né du blizzard</>. Tu ne t’es pas préparé pour ça depuis si longtemps ?",
          DialogueId = 10037007,
          FinalCamera = "553.824219,-40.515305,57.5625,0.000236,0.241358,-133.546417,22.0,449.12384,false,DoNotOverride,3.005529",
          GUID = "19206876",
          NextDialogue = 10037008,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{3.8},TargetPosition{"258.943359,-1131.915894,153.863281,0.000024,-1.34707,138.650085,100.0,894.799927,false,Manual,8.0"},duration{0}},
CameraMoveTo{TargetPosition{"252.603516,-1139.067505,153.863281,0.000024,-1.34707,138.250031,100.0,894.799927,false,Manual,8.0"},Blend{"easeOutQuad"},duration{4.5}}
},
]],
          SpeakNpcId = 100318,
          Subtitle = "Yes, the final act of Children From the Snowfield. You've been preparing for this moment for so long, haven't you?",
          TalkActionId = {
            [1] = "100318:Talk02_End",
            [2] = "100312:Explain02_Start"
          },
          ToFinalCameraBlendTime = 3.8,
          VoiceName = "voice/$Locale$/story/1003/100370/19206876"
        },
        [10037008] = {
          Camera = "-515.626953,-292.956024,163.917969,0.000079,-2.54723,-53.34362,80.000008,911.690552,false,Manual,8.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Oui... oui, c’est vrai... Je m’en souviens, Madame Violetta.",
          DialogueId = 10037008,
          FacialId = {
            [1] = "100312:Confident01"
          },
          FinalCamera = "-510.757812,-289.32901,163.917969,0.000079,-2.54723,-53.34362,80.000008,911.690552,false,Manual,8.0",
          GUID = "192068A0",
          NextDialogue = 10037009,
          SpeakNpcId = 100312,
          Subtitle = "Yes... yes, I have. I remember now, Ms Violetta.",
          TalkActionId = {
            [1] = "100318:Explain01_End",
            [2] = "100312:Explain02_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1003/100370/192068A0"
        },
        [10037009] = {
          Camera = "-54.876953,-874.34314,116.808594,0.000103,10.605344,-44.881695,50.000008,172.15979,false,Manual,5.0",
          ContentFR = "C’est ça, ma mission... <H>achever cette représentation</>.",
          DialogueId = 10037009,
          FinalCamera = "-54.876953,-874.34314,118.550781,0.000104,10.605344,-45.282009,60.0,172.15979,false,Manual,5.0",
          GUID = "192068CA",
          SpeakNpcId = 100312,
          Subtitle = "This is what I must do — to complete this performance.",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1003/100370/192068CA"
        },
        [10037101] = {
          ContentFR = "Il y a bien longtemps... dans un château de glace, au cœur d’un pays enneigé...\nUne fée des neiges s’éveilla au rire de deux enfants.",
          DialogueId = 10037101,
          GUID = "192077E2",
          Subtitle = "Once upon a time, in a frosted castle in the Snowfield, a slumbering frost fairy was awakened by the laughter of two children.",
          VoiceName = "voice/$Locale$/story/1003/100371/192077E2"
        },
        [10037102] = {
          ContentFR = "Les enfants allumèrent un feu... mais même les flammes ne purent réchauffer le cœur gelé de la fée.",
          DialogueId = 10037102,
          GUID = "1920780C",
          Subtitle = "Though the children lit a fire, its flames could not thaw the icy core of the fairy's heart.",
          VoiceName = "voice/$Locale$/story/1003/100371/1920780C"
        },
        [10037103] = {
          ContentFR = "Jour après jour, malgré la neige et les blizzards, les enfants revenaient jouer dans le château.",
          DialogueId = 10037103,
          GUID = "19207836",
          Subtitle = "Day after day, through snowstorms and biting winds, the children came to the castle to play with the fairy.",
          VoiceName = "voice/$Locale$/story/1003/100371/19207836"
        },
        [10037104] = {
          ContentFR = "Peu à peu, à force de leurs chants et de leurs rires... la fée finit par s’y habituer.",
          DialogueId = 10037104,
          GUID = "19207860",
          Subtitle = "They laughed, sang, and danced. Slowly, the fairy grew accustomed to their company.",
          VoiceName = "voice/$Locale$/story/1003/100371/19207860"
        },
        [10037105] = {
          ContentFR = "« Si seulement je pouvais rire comme eux... »",
          DialogueId = 10037105,
          GUID = "1920788A",
          Subtitle = "\"Look there, they smile so bright, and it lights up my night. How I wish I had mine.\"",
          VoiceName = "voice/$Locale$/story/1003/100371/1920788A"
        },
        [10037106] = {
          ContentFR = "« Si seulement mon cœur de glace... pouvait un jour se réchauffer... »",
          DialogueId = 10037106,
          GUID = "192078B4",
          Subtitle = "\"My frozen heart, it's been cold for my lifetime. How I wish I could feel the warmth inside.\" ",
          VoiceName = "voice/$Locale$/story/1003/100371/192078B4"
        },
        [10037201] = {
          ContentFR = "Mais un jour... les griffes des bêtes s’abattirent sur ce pays enneigé.",
          DialogueId = 10037201,
          GUID = "1920884A",
          NextDialogue = 10037202,
          Subtitle = "One day, the claws of savage beasts reached into the Snowfield.",
          VoiceName = "voice/$Locale$/story/1003/100372/1920884A"
        },
        [10037202] = {
          ContentFR = "La terre et le ciel... furent noyés de pourpre.",
          DialogueId = 10037202,
          GUID = "19208874",
          NextDialogue = 10037203,
          Subtitle = "The once-pristine land and sky were drowned in crimson",
          VoiceName = "voice/$Locale$/story/1003/100372/19208874"
        },
        [10037203] = {
          ContentFR = "Alors, la fée quitta son château... pour honorer la promesse faite à l’enfant.",
          DialogueId = 10037203,
          GUID = "1920889E",
          NextDialogue = 10037204,
          Subtitle = "Bound by a promise made to the boy, the fairy left its castle.",
          VoiceName = "voice/$Locale$/story/1003/100372/1920889E"
        },
        [10037204] = {
          ContentFR = "« Je te l’ai juré : je descendrai vers la vallée... Je trouverai ta famille... et je la protégerai. »",
          DialogueId = 10037204,
          GUID = "192088C8",
          Subtitle = "\"I promised I would find your family in the valley below and keep her safe.\"",
          VoiceName = "voice/$Locale$/story/1003/100372/192088C8"
        },
        [10037205] = {
          ContentFR = "Dans la ville en ruines, encerclée par des bêtes... Une jeune fille tremblait au milieu des décombres.",
          DialogueId = 10037205,
          GUID = "192088F2",
          Subtitle = "In the town, beasts prowled among the ruins, circling a girl trapped beneath the rubble.",
          VoiceName = "voice/$Locale$/story/1003/100372/192088F2"
        },
        [10037206] = {
          ContentFR = "« Comment éloigner la guerre de son foyer ? Comment empêcher qu’elle ne vive dans la peur ? »",
          DialogueId = 10037206,
          Duration = 10,
          GUID = "1920891C",
          NextDialogue = 10037207,
          Subtitle = "\"Flames of war, raging day by day. Now, Death took him away; only she remains.\"",
          VoiceName = "voice/$Locale$/story/1003/100372/1920891C"
        },
        [10037207] = {
          ContentFR = "« Même si le prix à payer... est mon cœur de glace... »",
          DialogueId = 10037207,
          Duration = 10,
          GUID = "19208946",
          Subtitle = "\"No turning back, I've decided to keep her safe. Come and take my heart if that's what it takes.\"",
          VoiceName = "voice/$Locale$/story/1003/100372/19208946"
        },
        [10037208] = {
          ContentFR = "Alors, la frêle fée s’élança contre les monstres... Mais leurs griffes brisèrent d’un rien ses membres fragiles.",
          DialogueId = 10037208,
          GUID = "19208970",
          NextDialogue = 10037209,
          Subtitle = "The tiny fairy flew towards the monstrous creatures, only for its delicate limbs to snap beneath their might.",
          VoiceName = "voice/$Locale$/story/1003/100372/19208970"
        },
        [10037209] = {
          ContentFR = "Pourtant, pour la toute première fois... son cœur battit. Il battit... il hurla son propre destin !",
          DialogueId = 10037209,
          GUID = "1920899A",
          Subtitle = "The fairy's frozen heart pulsed for the first time — beating, screaming its own destiny:",
          VoiceName = "voice/$Locale$/story/1003/100372/1920899A"
        },
        [10037210] = {
          ContentFR = "« Une fée ne vaincra jamais une bête... Celui qui combat les monstres... doit lui-même devenir monstre ! »",
          DialogueId = 10037210,
          GUID = "192089C4",
          Subtitle = "\"Slay all the beasts? I know clearly... This frozen heart now burns the most!\"",
          VoiceName = "voice/$Locale$/story/1003/100372/192089C4"
        },
        [10037211] = {
          ContentFR = "« Alors qu’on m’arrache ce corps ! Que mes bras deviennent des griffes pour les déchirer ! »",
          DialogueId = 10037211,
          Duration = 10,
          GUID = "192089EE",
          NextDialogue = 10037212,
          Subtitle = "\"Come and take my frame, let my claws break the chain and rend the shade.\"",
          VoiceName = "voice/$Locale$/story/1003/100372/192089EE"
        },
        [10037212] = {
          ContentFR = "« Qu’on m’arrache ce visage ! Qu’il devienne celui d’un démon hideux ! »",
          DialogueId = 10037212,
          Duration = 10,
          GUID = "19208A18",
          NextDialogue = 10037213,
          Subtitle = "\"Come and take my face, let my fangs bleed the foes and tear the souls.\"",
          VoiceName = "voice/$Locale$/story/1003/100372/19208A18"
        },
        [10037213] = {
          ContentFR = "« Qu’on m’arrache ma voix ! Qu’elle se change en hurlement de tonnerre ! »",
          DialogueId = 10037213,
          Duration = 10,
          GUID = "19208A42",
          NextDialogue = 10037214,
          Subtitle = "\"Come and take my voice, let my roars quake the ground and shake the world.\"",
          VoiceName = "voice/$Locale$/story/1003/100372/19208A42"
        },
        [10037214] = {
          ContentFR = "« Qu’on m’arrache mon cœur ! Que la glace devienne lame... pour transpercer les bêtes ! »",
          DialogueId = 10037214,
          Duration = 10,
          GUID = "19208A6C",
          Subtitle = "\"Come and take my mind, let my sparks light the night and turn the tide.\"",
          VoiceName = "voice/$Locale$/story/1003/100372/19208A6C"
        },
        [10037215] = {
          ContentFR = "« Ainsi, enfin... je tiendrai ma promesse ! »",
          DialogueId = 10037215,
          Duration = 24,
          GUID = "19208A96",
          Subtitle = "\"The oath I've made now ends. Yes, the end.\"",
          VoiceName = "voice/$Locale$/story/1003/100372/19208A96"
        },
        [10037301] = {
          ContentFR = "Ai-je... achevé cette représentation ?",
          DialogueId = 10037301,
          GUID = "192098B2",
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "Have I... completed this performance?",
          VoiceName = "voice/$Locale$/story/1003/100373/192098B2"
        },
        [10037302] = {
          ContentFR = "Oui, Parsifal.",
          DialogueId = 10037302,
          GUID = "192098DC",
          SpeakNpcName = "Cp2CharacterName06",
          Subtitle = "Yes, Parsifal.",
          VoiceName = "voice/$Locale$/story/1003/100373/192098DC"
        },
        [10037303] = {
          ContentFR = "La représentation est terminée.",
          DialogueId = 10037303,
          GUID = "19209906",
          SpeakNpcName = "ChatCharacter20",
          Subtitle = "Your show is complete.",
          VoiceName = "voice/$Locale$/story/1003/100373/19209906"
        },
        [10037304] = {
          ContentFR = "Tu as été magnifique.",
          DialogueId = 10037304,
          GUID = "19209930",
          SpeakNpcName = "UI_Npc_Name_Aote",
          Subtitle = "That was absolutely amazing.",
          VoiceName = "voice/$Locale$/story/1003/100373/19209930"
        },
        [10037305] = {
          ContentFR = "Tu es le plus grand comédien.",
          DialogueId = 10037305,
          GUID = "1920995A",
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "You're the finest performer there's ever been.",
          VoiceName = "voice/$Locale$/story/1003/100373/1920995A"
        },
        [10037306] = {
          ContentFR = "À toutes les unités, préparez-vous— feu !",
          DialogueId = 10037306,
          GUID = "19209984",
          SpeakNpcName = "UI_Npc_Name_Linen",
          Subtitle = "All units, ready your arms — fire!",
          VoiceName = "voice/$Locale$/story/1003/100373/19209984"
        },
        [10037307] = {
          ContentFR = "Je suis... le plus grand des comédiens.",
          DialogueId = 10037307,
          GUID = "192099AE",
          SpeakNpcName = "Cp2CharacterName07",
          Subtitle = "I am... the finest performer.",
          VoiceName = "voice/$Locale$/story/1003/100373/192099AE"
        },
        [10037401] = {
          ContentFR = "Mission accomplie.",
          DialogueId = 10037401,
          GUID = "1920A91A",
          NextDialogue = 10037402,
          SpeakNpcId = 200022,
          Subtitle = "Operation concluded.",
          VoiceName = "voice/$Locale$/story/1003/100374/1920A91A"
        },
        [10037402] = {
          ContentFR = "Cible n° 2, signes vitaux confirmés. Procédez à l’extraction.",
          DialogueId = 10037402,
          GUID = "1920A944",
          SpeakNpcId = 200022,
          Subtitle = "Target No. 2's vital signs confirmed; proceeding with retrieval.",
          VoiceName = "voice/$Locale$/story/1003/100374/1920A944"
        },
        [10037501] = {
          Camera = "-63.583008,10.710693,109.947021,-0.00003,9.381203,61.161171,35.000008,1.5,false,DoNotOverride,1.2",
          ContentFR = "La lumière de la tour de guet... s’est éteinte.",
          DialogueId = 10037501,
          FacialId = {
            [1] = "100304:Smile01"
          },
          FinalCamera = "-68.545898,13.479492,109.947021,-0.00003,9.381203,58.360966,35.000008,1.5,false,DoNotOverride,1.2",
          GUID = "1920B982",
          LookAt = {
            [1] = "100304:p(cp2fixsimple04_66Point01)",
            [2] = "200002:n(100304)",
            [3] = "100001:n(100304)",
            [4] = "200021:n(100304)"
          },
          NextDialogue = 10037502,
          SpeakNpcId = 100304,
          Subtitle = "The light on the watchtower... it's gone out.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920B982"
        },
        [10037502] = {
          Camera = "-139.921875,-372.8479,83.878906,0.000085,4.580666,68.377281,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah... vous êtes là. Bonjour.",
          DialogueId = 10037502,
          FinalCamera = "-139.921875,-372.8479,83.878906,0.000087,3.180634,68.577415,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1920B9AC",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10037503,
          Scripts = "PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Talk02_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "Oh... it's you. Good morning.",
          TalkActionId = {
            [1] = "100304:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920B9AC"
        },
        [10037503] = {
          Camera = "-17.186523,234.916016,139.269043,0.000069,-2.618407,-84.018005,50.0,358.606506,false,Manual,7.19311",
          ContentFR = "Tes blessures... ça va ?",
          DialogueId = 10037503,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "-13.21582,235.332031,139.269043,0.000069,-2.618407,-84.417961,50.0,358.606506,false,Manual,7.19311",
          GUID = "1920B9D6",
          NextDialogue = 10037504,
          SpeakNpcId = 100001,
          Subtitle = "How are your injuries? Are you feeling okay?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920B9D6"
        },
        [10037504] = {
          Camera = "-74.648438,-20.898193,114.953369,0.000097,6.981259,61.583469,45.000023,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ne t’inquiète pas. Ça fait déjà plusieurs jours.",
          DialogueId = 10037504,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "-85.210938,-14.642334,114.953369,0.000097,6.981259,58.583527,45.000023,100000.0,false,DoNotOverride,2.8",
          GUID = "1920BA00",
          NextDialogue = 10037505,
          SpeakNpcId = 100304,
          Subtitle = "I'm fine. It's been several days already.",
          TalkActionId = {
            [1] = "100304:DisagreeHead",
            [2] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BA00"
        },
        [10037505] = {
          Camera = "27.269531,-19.760254,112.787598,0.00003,-19.417503,-68.015167,40.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vraiment ? Le Petit Larbin disait que c’était trop dangereux et m’interdisait de vous suivre… Et maintenant que j’ai entendu ce qui s’est passé... Ah ! Dire que c’était juste \"dangereux\" serait un mensonge énorme !",
          DialogueId = 10037505,
          FacialId = {
            [1] = "200002:Shock01"
          },
          FinalCamera = "5.042969,36.106201,133.278564,0.000035,-19.41753,-68.615051,40.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1920BA2A",
          NextDialogue = 10037506,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-79.655273,284.639893,145.479736,0.000062,-6.814336,-69.206177,40.0,409.424408,false,Manual,1.554163\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-79.655273,284.639893,145.479736,0.000061,-8.414362,-69.206169,40.0,409.424408,false,Manual,1.554163\"},duration{10}}}",
          SpeakNpcId = 200002,
          Subtitle = "Are you sure? Back then, Little Minion said it was too dangerous and wouldn't let me tag along. But after hearing what happened... I feel calling the situation \"dangerous\" was an understatement!",
          TalkActionId = {
            [1] = "200002:Bai_Shock2Think2Confident"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BA2A"
        },
        [10037506] = {
          Camera = "-33.25293,14.163086,118.577148,0.000069,7.581913,-81.00975,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Rhythm...",
          DialogueId = 10037506,
          FacialId = {
            [1] = "100304:Unhappy01"
          },
          FinalCamera = "-38.43457,13.438232,118.577148,0.000068,7.581913,-78.609329,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1920BA54",
          NextDialogue = 10037507,
          SpeakNpcId = 100001,
          Subtitle = "Rhythm...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BA54"
        },
        [10037507] = {
          Camera = "-48.94043,-193.90918,145.562012,0.000055,-3.21734,72.182663,35.000011,333.453583,false,Manual,3.947433",
          ContentFR = "Ce n’est rien. On ne pouvait rien y changer.",
          DialogueId = 10037507,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "-52.744141,-192.686279,145.562012,0.000055,-3.21734,71.382599,35.000011,333.453583,false,Manual,3.947433",
          GUID = "1920BA7E",
          NextDialogue = 10037508,
          SpeakNpcId = 100304,
          Subtitle = "It's fine. There's nothing we could've done about it anyway.",
          TalkActionId = {
            [1] = "100304:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BA7E"
        },
        [10037508] = {
          Camera = "-12.743164,78.746094,166.23877,-10.806119,-22.216761,68.781303,35.000015,333.453583,false,DoNotOverride,3.947433",
          ContentFR = "Ce monde est rempli de choses que l’on ne peut contrôler... alors ce n’est pas grave.",
          DialogueId = 10037508,
          FinalCamera = "-8.754883,77.253418,165.484375,-10.806363,-22.216761,70.981277,35.000015,333.453583,false,DoNotOverride,3.947433",
          GUID = "1920BAA8",
          NextDialogue = 10037509,
          SpeakNpcId = 100304,
          Subtitle = "This world is filled with countless things beyond our control. That's just how it is.",
          TalkActionId = {
            [1] = "100304:ScratchHead_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BAA8"
        },
        [10037509] = {
          Camera = "-16.036133,222.015137,133.278076,0.000081,-1.618529,-83.001534,45.0,350.173065,false,Manual,3.649603",
          ContentFR = "Je comprends.",
          DialogueId = 10037509,
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "-18.958984,221.722656,133.278076,0.000082,-1.618529,-81.201332,45.0,350.173065,false,Manual,3.649603",
          GUID = "1920BAD2",
          NextDialogue = 10037510,
          SpeakNpcId = 100001,
          Subtitle = "I see.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BAD2"
        },
        [10037510] = {
          Camera = "33.671875,103.241455,116.0,0.000042,8.182191,-126.613289,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Au fait... cette médaille... ?",
          DialogueId = 10037510,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter02_KarongLaurelsMedal.T_Guide_Chapter02_KarongLaurelsMedal'}",
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "43.613281,116.628174,113.602539,0.000042,8.182191,-126.613289,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1920BAFC",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10037511,
          SpeakNpcId = 200021,
          Subtitle = "By the way, is this medal...?",
          TalkActionId = {
            [1] = "200021:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BAFC"
        },
        [10037511] = {
          Camera = "-128.297852,-478.702148,60.10083,0.000092,7.180516,74.561852,40.000023,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui, c’est la médaille des Charons Couronnés. L’officier Lynn me l’a remise... pour récompenser ma \"contribution exceptionnelle\" lors de cet incident.",
          DialogueId = 10037511,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "-128.297852,-478.702148,60.10083,0.000093,5.180521,74.761528,40.000023,100000.0,false,DoNotOverride,2.8",
          GUID = "1920BB26",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10037512,
          Scripts = "PlayAnimation{_delay{6},ActorId{100304},AnimationId{\"Talk01_End\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "Yes, the \"Laurelled Charon\" medal. Officer Lynn awarded it to me — for my \"outstanding contributions\" to the case.",
          TalkActionId = {
            [1] = "100304:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BB26"
        },
        [10037512] = {
          Camera = "82.358398,198.667725,134.772949,0.000064,0.181403,-131.217133,35.000008,294.301453,false,Manual,2.670946",
          ContentFR = "Félicitations.",
          DialogueId = 10037512,
          FacialId = {
            [1] = "200021:Smile01"
          },
          FinalCamera = "84.486328,196.679443,134.772949,0.000064,0.181403,-133.017227,35.000008,294.301453,false,Manual,2.670946",
          GUID = "1920BB50",
          LookAt = {
            [1] = "100304:n(200021)"
          },
          NextDialogue = 10037513,
          SpeakNpcId = 200021,
          Subtitle = "Congratulations.",
          TalkActionId = {
            [1] = "200021:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BB50"
        },
        [10037513] = {
          Camera = "10.041016,-8.404053,138.570312,0.000085,0.58116,89.379379,36.0,154.17691,false,Manual,4.180777",
          ContentFR = "« Félicitations »... si c’était l’ancienne moi, j’aurais sans doute été ravie.",
          DialogueId = 10037513,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "10.427734,27.300537,138.931396,0.000085,0.58116,89.379379,27.0,112.349808,false,Manual,4.180777",
          GUID = "1920BB7A",
          LookAt = {
            [1] = "100304:n(100001)"
          },
          NextDialogue = 10037514,
          Scripts = "PlayAnimation{_delay{2},ActorId{100304},AnimationId{\"Explain02_Start\"},Duration{2}}",
          SpeakNpcId = 100304,
          Subtitle = "\"Congratulations\"... huh. If it were the old me, I'd probably be thrilled.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BB7A"
        },
        [10037514] = {
          Camera = "5.262695,76.219727,134.480713,0.000847,0.195241,81.158875,45.0,112.349808,false,DoNotOverride,4.180777",
          ContentFR = "Mais maintenant... cette médaille ne me sert qu’à faciliter ma démission, pour ne pas être embêtée. Elle est tachée du sang et des larmes de trop de gens... elle n’a plus de sens.",
          DialogueId = 10037514,
          FinalCamera = "2.518555,76.645996,134.480713,0.000847,0.195241,81.158875,45.0,112.349808,false,DoNotOverride,4.180777",
          GUID = "1920BBA4",
          NextDialogue = 10037515,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"240.870117,403.278564,27.020752,0.000846,9.995298,-122.032578,35.000011,112.349808,false,DoNotOverride,4.180777\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"250.574219,397.317383,27.020752,0.000846,9.995298,-123.432892,35.000011,112.349808,false,DoNotOverride,4.180777\"},duration{8}}}",
          SpeakNpcId = 100304,
          Subtitle = "But now, this medal's only purpose is to smooth the way for my resignation, sparing me from unnecessary questioning or resistance. It's stained with the blood and tears of too many innocent people and holds no meaning to me anymore.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BBA4"
        },
        [10037515] = {
          Camera = "17.008789,-203.814209,141.177002,0.000862,-3.203365,96.563492,35.000008,112.349808,false,DoNotOverride,4.180777",
          ContentFR = "Je n’ai toujours pas de nouvelles précises sur Berenica.",
          DialogueId = 10037515,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "24.445312,-202.957764,141.177002,0.000862,-3.203365,99.363602,35.000008,112.349808,false,DoNotOverride,4.180777",
          GUID = "1920BBCE",
          NextDialogue = 10037516,
          SpeakNpcId = 100304,
          Subtitle = "I still haven't found any concrete information about Berenica.",
          TalkActionId = {
            [1] = "100304:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BBCE"
        },
        [10037516] = {
          Camera = "35.515625,50.157227,180.47876,0.000898,-26.402422,105.76342,35.000011,112.349808,false,DoNotOverride,4.180777",
          ContentFR = "J’ai cherché ce que tu m’as dit à propos de \"n° 0\", mais mes contacts m’ont confirmé qu’à peine ce nom est prononcé à la XIIIᵉ Légion, tout le monde se tait. Aucune info n’en sort.",
          DialogueId = 10037516,
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "42.668945,52.17749,180.47876,0.000904,-26.202442,109.363518,35.000011,112.349808,false,DoNotOverride,4.180777",
          GUID = "1920BBF8",
          NextDialogue = 10037517,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"43.630859,193.185547,139.549805,0.000917,-3.002168,-108.237061,35.000011,112.349808,false,DoNotOverride,4.180777\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"47.787109,191.749512,139.549805,0.000918,-3.002168,-110.637024,35.000011,112.349808,false,DoNotOverride,4.180777\"},duration{8}}}",
          SpeakNpcId = 100304,
          Subtitle = "I tried looking into what you told me about \"No. 0,\" but my contacts said that even mentioning the name to anyone in the 13th Legion was met with immediate silence. They refused to disclose anything about her.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BBF8"
        },
        [10037517] = {
          Camera = "-3.491211,-54.561523,123.315186,0.000868,2.99389,85.586227,35.000015,112.349808,false,DoNotOverride,4.180777",
          ContentFR = "Toutefois, deux choses se devinent à travers leurs réactions : premièrement, elle est bien à la XIIIᵉ Légion, deuxièmement, elle est précieuse, la Légion ne la traiterait pas à la légère. Ce qui est arrivé à Blues... ne se reproduira pas avec elle.",
          DialogueId = 10037517,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "-4.466797,-67.182129,122.65332,0.000868,2.99389,85.586227,35.000015,112.349808,false,DoNotOverride,4.180777",
          GUID = "1920BC22",
          NextDialogue = 10037518,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"226.594727,371.689941,44.04834,0.000876,8.795097,-122.410477,35.000011,112.349808,false,DoNotOverride,4.180777\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"218.137695,377.131836,44.04834,0.000876,8.795097,-120.410583,35.000011,112.349808,false,DoNotOverride,4.180777\"},duration{8}}},PlayAnimation{_delay{5},ActorId{100304},AnimationId{\"ExplainTwo_Start\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "But we can be sure of two things: First, she's definitely been taken by the 13th Legion. Second, she's very important to them. They wouldn't treat her as carelessly as... as they did Blues.",
          TalkActionId = {
            [1] = "100001:Talk03_End",
            [2] = "200021:ConfidentLR_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BC22"
        },
        [10037518] = {
          Camera = "32.716797,-34.469971,153.215576,0.000896,-8.204225,-120.014557,35.000008,112.349808,false,DoNotOverride,4.180777",
          ContentFR = "... Merci. Ça me rassure un peu.",
          DialogueId = 10037518,
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "39.794922,-38.415527,153.215576,0.000897,-8.204218,-125.014954,35.000008,112.349808,false,DoNotOverride,4.180777",
          GUID = "1920BC4C",
          NextDialogue = 10037519,
          SpeakNpcId = 100001,
          Subtitle = "...Thank you. That does ease my mind a little.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BC4C"
        },
        [10037519] = {
          Camera = "21.964844,-213.820312,139.455078,0.00089,-1.203916,98.188377,45.0,112.349808,false,DoNotOverride,4.180777",
          ContentFR = "D’ailleurs, j’ai entendu autre chose... je ne sais pas si ça t’aidera.",
          DialogueId = 10037519,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "29.540039,-212.92041,139.455078,0.000889,-1.203916,100.78862,45.0,112.349808,false,DoNotOverride,4.180777",
          GUID = "1920BC76",
          NextDialogue = 10037520,
          SpeakNpcId = 100304,
          Subtitle = "Oh, and I heard something else — though I'm not sure if it's useful intel to you.",
          TalkActionId = {
            [1] = "100304:ExplainTwo_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BC76"
        },
        [10037520] = {
          Camera = "996.735352,-1726.871582,641.289185,0.000903,-14.803513,122.785484,45.0,2215.719971,false,Manual,1.2",
          ContentFR = "Dans un mois, la XIIIᵉ Légion transportera une prisonnière importante par train, de Givrelac jusqu’à la capitale, Dismania. La VIᵉ Légion a reçu l’ordre de les assister.",
          DialogueId = 10037520,
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "1030.970703,-1705.590332,641.289185,0.000901,-14.803513,124.385521,45.0,2215.719971,false,Manual,1.2",
          GUID = "1920BCA0",
          NextDialogue = 10037521,
          SpeakNpcId = 100304,
          Subtitle = "One month from now, the 13th Legion will be relocating a high-value prisoner by train from Icelake to Dismania, the imperial capital. The 6th Legion's been ordered to assist with the transport.",
          TalkActionId = {
            [1] = "100304:Talk03_Start",
            [2] = "100001:Explain02_End",
            [3] = "200021:ConfidentLR_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BCA0"
        },
        [10037521] = {
          Camera = "83.299805,386.815186,122.259033,0.000927,2.195216,-105.600525,60.0,2215.719971,false,DoNotOverride,1.2",
          ContentFR = "L’identité de cette prisonnière est top secrète. Tout ce que je sais, c’est qu’elle est actuellement soignée dans la cité intérieure sous haute sécurité. Mais quelqu’un a aperçu son dos, <H>une jeune femme d’une vingtaine d’années</>, vêtue de noir.",
          DialogueId = 10037521,
          FinalCamera = "76.230469,388.789307,122.259033,0.000926,2.195216,-104.800972,60.0,2215.719971,false,DoNotOverride,1.2",
          GUID = "1920BCCA",
          NextDialogue = 10037522,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-2.646484,-36.341553,129.882324,0.000927,1.194928,84.394646,40.000027,2215.719971,false,DoNotOverride,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-4.348633,-53.6521,129.520508,0.000927,1.194928,84.394646,40.000027,2215.719971,false,DoNotOverride,1.2\"},duration{8}}},PlayAnimation{_delay{4},ActorId{100304},AnimationId{\"Talk03ToTalkL_End\"},Duration{2}}}",
          SpeakNpcId = 100304,
          Subtitle = "The prisoner's identity is classified as top secret. All I know is that she's currently receiving treatment in the inner city under maximum security. But someone caught a glimpse of her back — a young woman in her early twenties, dressed in black.",
          TalkActionId = {
            [1] = "100304:Talk03ToTalkL_Start",
            [2] = "200021:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BCCA"
        },
        [10037522] = {
          Camera = "13.171875,-186.607422,138.582764,0.000934,-2.604645,97.007713,40.000011,335.778412,false,Manual,3.301423",
          ContentFR = "Cela correspond à ce que tu m’as dit à propos de Berenica. Si c’est bien elle, alors <H>le train qui part dans un mois</> pourrait être ta seule chance.",
          DialogueId = 10037522,
          FinalCamera = "11.713867,-174.760498,138.040771,0.000934,-2.604645,96.607719,40.000011,335.778412,false,Manual,3.301423",
          GUID = "1920BCF4",
          NextDialogue = 10037528,
          SpeakNpcId = 100304,
          Subtitle = "That matches what you've told me about Berenica. If it really is her, then the train departing in a month might be your only chance.",
          TalkActionId = {
            [1] = "100304:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BCF4"
        },
        [10037523] = {
          Camera = "53.155273,214.800293,136.875,0.00091,-1.204497,-109.395287,40.0,2215.719971,false,DoNotOverride,1.2",
          ContentFR = "Merci pour l’info. C’est le seul indice que j’ai, je tenterai ma chance quoi qu’il arrive.",
          DialogueId = 10037523,
          FinalCamera = "48.369141,216.473145,136.875,0.000909,-1.204497,-108.195312,40.0,2215.719971,false,DoNotOverride,1.2",
          GUID = "1920BD1E",
          NextDialogue = 10037524,
          SpeakNpcId = 100001,
          Subtitle = "Thank you for the intel. This is the only lead I have, so I'll give it a try no matter what.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BD1E"
        },
        [10037524] = {
          Camera = "47.507812,24.023438,119.432129,0.000913,6.194961,-114.990166,40.000011,2215.719971,false,DoNotOverride,1.2",
          ContentFR = "Et toi, tu comptes faire quoi ensuite ?",
          DialogueId = 10037524,
          FinalCamera = "50.430664,15.504883,120.135742,0.000909,6.194961,-117.989082,40.000011,2215.719971,false,DoNotOverride,1.2",
          GUID = "1920BD48",
          NextDialogue = 10037525,
          SpeakNpcId = 100001,
          Subtitle = "What about you? What are you planning to do next?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BD48"
        },
        [10037525] = {
          Camera = "51.655273,-306.141357,186.446045,-0.000365,-13.03366,102.436493,40.0,2215.719971,false,DoNotOverride,1.2",
          ContentFR = "Honnêtement, je ne sais pas. À part t’aider à retrouver Berenica, je n’ai aucune idée. Mais... j’ai promis à <H>Blues</> que je continuerais à vivre.",
          DialogueId = 10037525,
          FacialId = {
            [1] = "100304:Doubt01"
          },
          FinalCamera = "51.655273,-306.141357,186.446045,-0.000366,-10.033664,102.43644,40.0,2215.719971,false,DoNotOverride,1.2",
          GUID = "1920BD72",
          NextDialogue = 10037526,
          SpeakNpcId = 100304,
          Subtitle = "Honestly, I don't know. Other than helping you look for Berenica, I have no idea what I can do. But... I made a promise to Blues that I'll live on.",
          TalkActionId = {
            [1] = "100304:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BD72"
        },
        [10037526] = {
          Camera = "110.807617,126.41333,135.724365,-0.000366,2.766411,170.235031,40.0,2215.719971,false,DoNotOverride,1.2",
          ContentFR = "Tant que je vis, je finirai par trouver une raison de continuer... non ?",
          DialogueId = 10037526,
          FinalCamera = "109.385742,118.139404,135.724365,-0.000366,2.766411,170.235031,40.0,2215.719971,false,DoNotOverride,1.2",
          GUID = "1920BD9C",
          NextDialogue = 10037527,
          SpeakNpcId = 100304,
          Subtitle = "As long as I'm alive, I'll eventually find a reason to keep going. Isn't that how it works?",
          TalkActionId = {
            [1] = "100304:Sigh_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BD9C"
        },
        [10037527] = {
          Camera = "425.092773,630.424927,385.071289,-0.000396,-19.031857,-124.358528,40.0,2215.719971,false,DoNotOverride,1.2",
          ContentFR = "Alors... à bientôt, je suppose.",
          DialogueId = 10037527,
          FinalCamera = "458.985352,607.005127,385.071289,-0.000399,-19.031849,-126.758369,40.0,2215.719971,false,DoNotOverride,1.2",
          GUID = "1920BDC6",
          SpeakNpcId = 100304,
          Subtitle = "I guess I'll see you around.",
          TalkActionId = {
            [1] = "100304:AgreeHead",
            [2] = "200021:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100375/1920BDC6"
        },
        [10037528] = {
          ContentFR = "<I>Serait-ce Berry ? Elle... a été emmenée à Givrelac, comme moi ?</>",
          DialogueId = 10037528,
          DisableMouth = 1,
          GUID = "1920BCF5",
          NextDialogue = 10037523,
          SpeakNpcId = 100001,
          Subtitle = "(Could it be Berry? Has she... been taken to Icelake, just like me?)",
          VoiceName = "voice/$Locale$/story/1003/100375/1920BCF5"
        },
        [10037601] = {
          Camera = "-333.064697,-321.197266,145.730469,-0.000031,-2.797106,54.238285,32.000004,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Bienvenue, bienvenue ! Alors, tu préfères quoi d’abord ? Boire un coup ou manger ? Tout est prêt, j’ai mis ton petit paquet de réconfort dans l’armoire à ta gauche. Y’a de tout, tu trouveras forcément ton bonheur.",
          DialogueId = 10037601,
          FacialId = {
            [1] = "100006:None"
          },
          FinalCamera = "-333.064697,-321.197266,145.730469,-0.000031,-2.997032,49.238327,32.000004,100000.0,false,DoNotOverride,22.0",
          GUID = "1920C9EA",
          NextDialogue = 10037602,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{2.5},TargetPosition{\"-109.0,84.102295,126.0,0.000074,1.59991,-85.567017,32.000004,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-116.175293,83.578613,126.0,0.000075,1.59991,-83.766907,32.000004,100000.0,false,DoNotOverride,22.0\"},duration{5}}},SEQ{MoveTo{ActorId{200022},TargetPoint{\"Cp2Meetingstage01Point01\"},MoveSpeed{80},Visibility{\"Show\"}},PlayAnimation{_delay{4},ActorId{200022},AnimationId{\"Confident_Start\"},Duration{2}}},PlayAnimation{_delay{6},ActorId{100006},AnimationId{\"Talk02_End\"},Duration{2}}}",
          SpeakNpcId = 100006,
          Subtitle = "Welcome back. Would you like something to drink or eat first? The care package I prepared is in the cabinet to your left. A wide selection — I dare say there's something in there to suit your taste.",
          TalkActionId = {
            [1] = "100006:Talk02_Start"
          },
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1003/100376/1920C9EA"
        },
        [10037602] = {
          Camera = "-121.563477,-202.702637,164.126953,0.000196,-8.599856,76.996925,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Un coup de poing dans ta figure, ça me suffira.",
          DialogueId = 10037602,
          FacialId = {
            [1] = "200022:Doubt01"
          },
          FinalCamera = "-124.874023,-201.937988,164.126953,0.000196,-8.599856,75.596764,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CA14",
          NextDialogue = 10038301,
          SpeakNpcId = 200022,
          Subtitle = "A punch in your face would suit my taste best.",
          TalkActionId = {
            [1] = "200022:Confident_End",
            [2] = "100006:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CA14"
        },
        [10037603] = {
          Camera = "-167.920898,164.282227,90.818359,0.000226,7.996334,-76.168259,45.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Aïe... la reconnaissance, ça t’étrangle toujours autant. Pourtant, j’avais trouvé une sacrée bonne idée pour ferrer un gros poisson. Et voilà tout ce que je récolte...",
          DialogueId = 10037603,
          FinalCamera = "-175.953613,162.272461,90.818359,0.000227,7.996334,-73.96772,45.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CA3E",
          NextDialogue = 10037604,
          SpeakNpcId = 100006,
          Subtitle = "That hurts... After all the effort I put into coming up with such a brilliant idea to net you the \"big fish,\" this is the thanks I get?",
          TalkActionId = {
            [1] = "200022:Talk03_Start",
            [2] = "100006:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CA3E"
        },
        [10037604] = {
          Camera = "-146.45752,-22.482178,140.748047,0.000275,3.595323,-62.979397,45.000023,100000.0,false,DoNotOverride,22.0",
          ContentFR = "<I>Soupir...</> Moi qui rêvais qu’à ton retour, la douce et honorable demoiselle Lynn me couvrirait de remerciements pour ma brillante stratégie.",
          DialogueId = 10037604,
          FinalCamera = "-151.791016,-25.168945,140.748047,0.000274,3.595323,-60.579292,45.000023,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CA68",
          NextDialogue = 10037605,
          SpeakNpcId = 100006,
          Subtitle = "*sigh* And here I was, dreaming that our ever-so-kind Miss Lynn would return with a heartfelt speech of gratitude for my genius.",
          TalkActionId = {
            [1] = "100006:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CA68"
        },
        [10037605] = {
          Camera = "-128.90625,-70.791016,131.251953,0.0002,1.796155,80.625771,45.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "« Cher Officier Randy, je suis bouleversée, émue, comblée, infiniment reconnaissante de votre incommensurable génie ! » ... Ça ira ?",
          DialogueId = 10037605,
          FacialId = {
            [1] = "200022:None"
          },
          FinalCamera = "-133.658203,-99.58252,130.353516,0.0002,1.796155,80.625771,45.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CA92",
          NextDialogue = 10037606,
          Scripts = "PlayAnimation{_delay{4},ActorId{200022},AnimationId{\"Confident_Start\"},Duration{2}}",
          SpeakNpcId = 200022,
          Subtitle = "...\"Dear Officer Randy, thank you for your unmatched brilliance and flawless foresight.\" Happy now?",
          TalkActionId = {
            [1] = "200022:Talk03_End",
            [2] = "100006:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CA92"
        },
        [10037606] = {
          Camera = "-664.519775,-300.244873,31.783203,0.000263,5.595905,24.610184,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "... Toujours aussi charmante. Bon, trêve de plaisanteries. Le Corvin qu’on visait est mort, mais grâce aux documents qu’il transportait, on a pu raser d’un coup l’influence des Déchus à Givrelac. Leur petit projet d’expansion vers la région de Cocytus ? Fini, enterré.",
          DialogueId = 10037606,
          FinalCamera = "-672.663086,-282.618652,31.783203,0.000268,5.595905,22.408474,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CABC",
          NextDialogue = 10037607,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-105.435547,42.211914,117.0,0.000283,8.194983,-86.186249,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-114.692871,41.508057,117.0,0.000288,8.194983,-83.185959,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{10}}},PlayAnimation{_delay{6},ActorId{100006},AnimationId{\"Talk03_End\"},Duration{2}}}",
          SpeakNpcId = 100006,
          Subtitle = "Jokes aside, while that \"Raven\" we were after ended up dead, the files we found on him led to a clean sweep of The Forsakens' influence in Icelake. Their plans to expand into the Cocytus Region? Dead in the water.",
          TalkActionId = {
            [1] = "100006:Talk03_Start",
            [2] = "200022:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CABC"
        },
        [10037607] = {
          Camera = "-115.555664,-186.211426,157.191406,0.000171,-8.60028,77.005707,30.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Et même un cadavre peut encore servir. Avec un peu de chance, on pourra profiter de ce vide pour glisser quelques taupes dans leur organisation. Si ça marche, ce sera une belle victoire. Tu pourrais même finir par me dépasser dans la hiérarchie...",
          DialogueId = 10037607,
          FinalCamera = "-116.454102,-185.844482,157.191406,0.000172,-8.60028,75.005295,30.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CAE6",
          NextDialogue = 10037608,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{4},TargetPosition{\"-132.910156,86.218994,122.052734,0.000166,1.599459,-78.986641,30.000002,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-144.938477,84.210938,122.052734,0.000168,1.599459,-76.185562,30.000002,100000.0,false,DoNotOverride,22.0\"},duration{5}}},PlayAnimation{_delay{2},ActorId{100006},AnimationId{\"ConfidentLRToExplainL_Start\"},Duration{2}}}",
          SpeakNpcId = 100006,
          Subtitle = "And you know what? Even the dead can serve a purpose. With the right timing, we could exploit this intel gap to sneak a few spies into The Forsakens. If it works out, this could be a real career boost for you, Lynn. Who knows? At this rate, you might even outrank me soon.",
          TalkActionId = {
            [1] = "100006:ConfidentLR_Start",
            [2] = "200022:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CAE6"
        },
        [10037608] = {
          Camera = "-190.0,93.0,132.0,0.000254,3.593861,-1.185761,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "...",
          DialogueId = 10037608,
          FacialId = {
            [1] = "200022:Doubt01"
          },
          FinalCamera = "-189.873535,99.352295,132.0,0.000254,3.593861,-1.185761,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CB10",
          NextDialogue = 10037609,
          SpeakNpcId = 200022,
          Subtitle = "...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CB10"
        },
        [10037609] = {
          Camera = "-124.294922,146.038574,132.613281,0.000323,-0.005983,-75.163185,35.000011,1251.390991,false,DoNotOverride,1.2",
          ContentFR = "C’est quoi cette tronche ? T’as croisé un créancier, ou bien on te réclame encore des dettes ?",
          DialogueId = 10037609,
          FinalCamera = "-126.015625,145.583252,132.613281,0.000323,-0.005983,-75.163185,35.000011,1251.390991,false,DoNotOverride,1.2",
          GUID = "1920CB3A",
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-802.243164,749.524658,118.019531,0.000311,-1.005827,-49.376923,35.000008,1251.390991,false,Manual,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-795.98999,754.6521,118.019531,0.000311,-1.005793,-50.777107,35.000008,1251.390991,false,Manual,1.2\"},duration{5}}}",
          SpeakNpcId = 100006,
          Subtitle = "What's with the long face? Did you run into someone back home you owe money to or something?",
          TalkActionId = {
