        },
        [10037612] = {
          Camera = "-244.910645,-507.646484,467.576172,0.000006,-32.398735,52.788418,35.000015,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Concernant mon rapport... Les Spathatoi collabore avec la VIᵉ Légion pour mener des expériences illégales dans la région de Cocytus, sous couvert de recrutements. La XIIIᵉ Légion ne compte vraiment rien entreprendre ?",
          DialogueId = 10037612,
          FacialId = {
            [1] = "200022:Doubt01"
          },
          FinalCamera = "-228.406738,-520.140625,467.576172,0.000007,-32.398735,55.388721,35.000015,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CBB8",
          NextDialogue = 10037613,
          Scripts = "PARA{SEQ{CameraMoveTo{_delay{4},TargetPosition{\"60.190918,-3.679688,210.888672,0.000024,-33.202454,57.994335,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"53.637695,0.608398,210.888672,0.000024,-33.002453,53.19397,35.000011,100000.0,false,DoNotOverride,22.0\"},duration{5}}},PlayAnimation{_delay{4},ActorId{100005},AnimationId{\"Talk03_End\"},Duration{2}}}",
          SpeakNpcId = 200022,
          Subtitle = "It's about the report I filed earlier — the Spathatoi Academy colluding with the 6th Legion to conduct illegal experiments in the Cocytus Region under the pretence of legion recruitments... Is the 13th Legion really going to turn a blind eye to this?",
          TalkActionId = {
            [1] = "200022:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CBB8"
        },
        [10037613] = {
          Camera = "-130.780273,219.330078,-14.652344,0.000043,17.998436,-55.606266,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "La VIᵉ Légion est une alliée de la XIIIᵉ.",
          DialogueId = 10037613,
          FacialId = {
            [1] = "100005:Angry01"
          },
          FinalCamera = "-130.780273,219.330078,-14.652344,0.000042,19.398399,-55.606041,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CBE2",
          NextDialogue = 10037614,
          SpeakNpcId = 100005,
          Subtitle = "The 6th Legion is an ally of the 13th Legion.",
          TalkActionId = {
            [1] = "200022:Explain02_End",
            [2] = "100005:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CBE2"
        },
        [10037614] = {
          Camera = "-71.827148,-329.141602,88.087891,-0.001007,8.999211,54.601879,35.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Et ceux qui se sont conspirés avec les Déchus pour commettre des atrocités à Givrelac sont nos ennemis.",
          DialogueId = 10037614,
          FinalCamera = "-71.827148,-329.141602,88.087891,-0.001007,10.199214,54.601788,35.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "1920CC0C",
          NextDialogue = 10037615,
          Scripts = "PlayAnimation{_delay{4},ActorId{100005},AnimationId{\"Think_End\"},Duration{2}}",
          SpeakNpcId = 100005,
          Subtitle = "And those who conspired with The Forsakens to commit atrocities in Icelake are the \"enemies\" of the 13th Legion.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100376/1920CC0C"
        },
        [10037615] = {
          Camera = "66.424805,-167.342285,147.371094,0.000035,-0.800109,69.978958,35.000011,250.047394,false,Manual,2.787895",
          ContentFR = "Mais... !",
          DialogueId = 10037615,
          FacialId = {
            [1] = "200022:Iyada01"
          },
          FinalCamera = "63.642578,-166.536133,147.371094,0.000035,-0.800109,68.379089,35.000011,250.047394,false,Manual,2.787895",
