          },
          NextDialogue = 10100204,
          SpeakNpcId = 100001,
          Subtitle = "No, we were...",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101010/1949781C"
        },
        [10100204] = {
          ContentFR = "<I>Je dois retrouver Berry. Si elle n’avait pas eu à me protéger, elle aurait sûrement échappé aux soldats...</>",
          DialogueId = 10100204,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "1948E88E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10100204.T_Story_Recall_10100204'",
          LookAt = {
