          },
          NextDialogue = 10100205,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 100001,
          Subtitle = "(I must find Berry. If it weren't for me, she would've managed to escape from those soldiers...)",
          VoiceName = "voice/$Locale$/story/1002/101002/1948E88E"
        },
        [10100205] = {
          Camera = "-29.84375,9.120605,109.405273,0.001219,9.699885,-73.354439,35.0,117.889595,false,Manual,2.8",
          ContentFR = "<I>Peut-être...</>",
          DialogueId = 10100205,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          GUID = "1948E8B8",
          NextDialogue = 10100206,
          SnapShot = "MEMORY",
          SpeakNpcId = 100001,
          Subtitle = "(Maybe...)",
          VoiceName = "voice/$Locale$/story/1002/101002/1948E8B8"
        },
        [10100206] = {
          Camera = "-113.203125,-295.231201,144.942871,0.001206,-5.299714,67.000038,35.0,368.848145,false,Manual,4.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Hé ! Tu comptes rester planté là combien de temps ? <H>Snow</> et Camilla ont fait tout ce chemin juste pour te sauver ! Alors suis-nous sagement en ville, sinon tu vas finir en casse-croûte pour le premier Souillé qui traîne !",
          DialogueId = 10100206,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200002:Unhappy02"
          },
          FinalCamera = "-115.261719,-294.439941,138.69043,0.001206,-5.299714,69.000008,35.0,371.583008,false,Manual,4.0",
          GUID = "1948E8E2",
          NextDialogue = 10100207,
          RelatedWikiId = {
            [1] = 201004,
            [2] = 201005
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{5},TargetPosition{"-60.582031,-61.83252,90.654297,0.001224,-6.29949,77.795509,39.952579,130.753311,false,Manual,4.0"},duration{0}},
SEQ{
PlayAnimation{ActorId{200002},AnimationId{"Talk03_Start"},Duration{1}},
PlayAnimation{_delay{4},ActorId{200002},AnimationId{"Talk03_End"},Duration{2.7}},
PlayAnimation{_delay{1},ActorId{200002},AnimationId{"Explain02_Start"},Duration{1.6}},
PlayAnimation{ActorId{200002},AnimationId{"Explain02_End"},Duration{2.2}},
PlayAnimation{ActorId{200002},AnimationId{"Shock_Start"},Duration{1}}
},
LookAt{_delay{0.9},LookAtDescription{"100001:n(200002)"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Hey, are you even listening? Camilla and Snow have come all this way to save you! You better come with us to the city right now, or else you'll soon become a snack for some wandering Filthoids!",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101002/1948E8E2"
        },
        [10100207] = {
          Camera = "-251.304688,292.147461,84.040039,1.999924,0.699848,-51.566563,35.000011,460.972412,false,Manual,3.0",
          ContentFR = "En... ville ?",
          DialogueId = 10100207,
          ExStoryInfo = "Player",
          GUID = "1948E90C",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextDialogue = 10100208,
          SpeakNpcId = 100001,
          Subtitle = "To... the city?",
          TalkActionId = {
            [1] = "200002:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101002/1948E90C"
        },
        [10100208] = {
          Camera = "-48.933594,-71.695312,97.074219,0.001207,-9.199916,81.628067,36.0,141.230881,false,Manual,4.0",
          ContentFR = "Tu as eu peur, pas vrai ? Pas de panique, on sera bientôt en sécurité. <H>Givrelac</>, c’est la plus grande cité du nord d’Hyperborea !",
          DialogueId = 10100208,
          FacialId = {
            [1] = "200002:Happy01"
          },
          GUID = "1948E936",
          NextDialogue = 10100209,
          RelatedWikiId = {
            [1] = 101003,
            [2] = 408003
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200002},AnimationId{"Think_Start"},Duration{3}},
PlayAnimation{ActorId{200002},AnimationId{"Think_End"},Duration{1.2}},
PlayAnimation{ActorId{200002},AnimationId{"Explain01_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Got a fright, huh? No worries, you'll be safe in a jiffy — Icelake is the largest city in northern Hyperborea!",
          VoiceName = "voice/$Locale$/story/1002/101002/1948E936"
        },
        [10100209] = {
          Camera = "-36.417969,82.69043,124.596191,0.00116,-1.800137,-76.755249,35.000008,184.209518,false,Manual,4.0",
          ContentFR = "Hyperborea... Je suis donc dans l’Empire Hyperboréen... ?!",
          DialogueId = 10100209,
          ExStoryInfo = "Player",
