        [10100212] = {
          Camera = "109.613281,-278.998535,123.344238,0.001196,-0.900663,111.229919,35.0,350.570953,false,Manual,3.0",
          ContentFR = "Des Sibylle, il y en a à la pelle. Mais celle qu’on appelle « Commandante », il n’y en a qu’une. Tu veux vraiment la trouver ? Qu’est-ce qui t’a gelé le cerveau ?",
