        [10100816] = {
          Camera = "-114.868164,-51.003906,147.164062,0.00115,-1.499991,2.259865,35.000008,204.629532,false,Manual,6.0",
          ContentFR = "Snow te l’a déjà dit, c’est à des milliers de lieues. Et si tu comptes y retourner... sache qu’un billet de train pour le sud coûte une fortune. Avec les frais du voyage, il te faudrait bien quelques milliers de pièces d’argent.",
          DialogueId = 10100816,
          FinalCamera = "-114.868164,-51.003906,150.164062,0.00115,-1.499991,2.259865,35.000008,204.629532,false,Manual,6.0",
          GUID = "19494D20",
          NextDialogue = 10100817,
          Scripts = [[
SEQ{
PlayAnimation{_delay{3.6},ActorId{200003},AnimationId{"Talk02_End"},Duration{5.9}},
PlayAnimation{ActorId{200003},AnimationId{"Think_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Snow just told you, didn't she? It's leagues away. If you're planning to head back there... the southbound train comes with a hefty fare, not to mention the travel expenses... You'd need at least a few thousand silver coins.",
          TalkActionId = {
            [1] = "200003:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101008/19494D20"
        },
        [10100817] = {
          Camera = "-2534.498047,882.487305,128.315918,0.001157,0.000109,-69.548653,30.0,1183.44812,false,Manual,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Et même si tu décidais de mendier jusqu’aux plaines hyperboréennes, tu aurais encore les contrôles à chaque ville. La chance ne sera pas toujours de ton côté...",
          DialogueId = 10100817,
          FinalCamera = "-2516.917969,889.322266,133.45166,0.001157,0.400112,-68.748718,30.0,1183.44812,false,Manual,2.8",
          GUID = "19494D4A",
          NextDialogue = 10100818,
          SpeakNpcId = 200003,
          Subtitle = "Even if you'd rather beg your way across the Hyperborean plains, you'd still need to somehow deal with the inspections in every town you pass. Next time, you might not be so lucky—",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101008/19494D4A"
        },
        [10100818] = {
          Camera = "-196.237305,-18.549316,146.658691,0.001187,-2.999962,0.843019,35.000008,264.133331,false,Manual,6.0",
          ContentFR = "Tu pourrais très bien finir dans une cellule, quelque part, pour un bon bout de temps.",
          DialogueId = 10100818,
          GUID = "19494D74",
          NextDialogue = 10100819,
          SpeakNpcId = 200003,
          Subtitle = "For all you know, you might well find yourself languishing in prison.",
          VoiceName = "voice/$Locale$/story/1002/101008/19494D74"
        },
        [10100819] = {
          Camera = "-3.067383,-50.891113,144.484375,0.00118,-1.90149,144.27504,35.000008,98.568146,false,Manual,2.8",
          ContentFR = "<I>... Donc rentrer n’est pas simple. Il me faut d’abord de l’argent... et ce fameux \"permis de circulation\" dont parlait le soldat.</>",
          DialogueId = 10100819,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "19494D9E",
          NextDialogue = 101008062,
          Scripts = "PlayAnimation{_delay{1.5},ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Hmm... right, going all the way back is no picnic. I must first get some money and, as that soldier mentioned, a \"travel permit.\")",
          TalkActionId = {
            [1] = "200003:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101008/19494D9E"
        },
        [10100820] = {
          Camera = "-196.237305,-18.549316,146.658691,0.001187,-2.999962,0.843019,35.000008,264.133331,false,Manual,6.0",
          ContentFR = "La XIIIᵉ Légion obéit directement à Sa Majesté l’Empereur. On en trouve la trace dans chaque province, Sibylle peut apparaître dans n’importe quelle forteresse d’Hyperborea.",
          DialogueId = 10100820,
          GUID = "19494DC8",
          NextDialogue = 10100821,
          RelatedWikiId = {
            [1] = 101005
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200003},AnimationId{"Talk02_Start"},Duration{2.3}},
PlayAnimation{ActorId{200003},AnimationId{"Talk02_End"},Duration{4.1}},
PlayAnimation{ActorId{200003},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "The 13th Legion is directly under the Emperor's command, with bases in every province, so Sibylle could be in any part of Hyperborea.",
          VoiceName = "voice/$Locale$/story/1002/101008/19494DC8"
        },
        [10100821] = {
          Camera = "-389.902344,-245.504395,22.587891,0.001195,10.30069,31.257433,35.000015,178.504257,false,DoNotOverride,4.0",
          ContentFR = "Mais la plus grande probabilité, c’est la capitale impériale, Dismania : un bastion d’acier colossal, qui abrite les meilleurs soldats et toutes les armes imaginables et inimaginables.",
          DialogueId = 10100821,
          FinalCamera = "-373.101562,-274.45459,22.588379,0.001195,10.30069,35.05777,35.000015,178.504257,false,DoNotOverride,4.0",
          GUID = "19494DF2",
          NextDialogue = 10100822,
          RelatedWikiId = {
            [1] = 408004
          },
          Scripts = "PlayAnimation{_delay{2.2},ActorId{200003},AnimationId{\"Think_Start\"},Duration{1}}",
          SpeakNpcId = 200003,
          Subtitle = "The most likely place, though, is the colossal steel bastion in Dismania, the imperial capital city, where you can find the Empire's finest soldiers and an arsenal of every type of conceivable and inconceivable armaments.",
          TalkActionId = {
            [1] = "100001:Sigh_End",
            [2] = "200003:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101008/19494DF2"
        },
        [10100822] = {
          Camera = "-2070.686523,-3294.441406,2337.578125,0.001209,26.398127,22.05953,11.0,10000.0,false,Manual,1.2",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Si Hyperborea est un char de guerre rugissant, Dismania en est le moteur, le cœur en fusion. Si tu veux t’y frotter, libre à toi... J’ai vu défiler bien des fous. Tu n’es pas {性别:le premier, et sûrement pas le dernier|la première, et sûrement pas la dernière}.",
          DialogueId = 10100822,
          FinalCamera = "-1849.558594,-2787.050781,2533.88208,0.001209,26.398127,22.05953,12.0,10000.0,false,Manual,1.2",
          GUID = "19494E1C",
          NextDialogue = 10100823,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/talk_engine_roaring\"},EventKey{\"talk_engine_roaring\"},PlayAs2D{false}}",
          SpeakNpcId = 200003,
          Subtitle = "If Hyperborea is a roaring chariot, that place is its engine, its fiery core — if you want to give it a try, go ahead. You're neither the first nor the last madcap I've seen.",
          TalkActionId = {
            [1] = "200003:Think_End"
          },
          ToFinalCameraBlendTime = 17,
          VoiceName = "voice/$Locale$/story/1002/101008/19494E1C"
        },
        [10100823] = {
          Camera = "13.978516,-54.12793,140.199707,0.001178,0.098546,147.47438,35.000011,112.923691,false,Manual,2.8",
          ContentFR = "<I>Donc... affronter Sibylle, c’est affronter tout l’Empire. Ai-je la moindre chance ? Pas pour l’instant... Il me faudra un autre plan.</>",
          DialogueId = 10100823,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          FinalCamera = "11.995117,-57.471191,140.199707,0.001178,0.098546,145.674149,35.000011,112.923691,false,Manual,2.8",
          GUID = "19494E46",
          NextDialogue = 101008062,
          Scripts = [[
PARA{
StopNormalSound{EventKey{"talk_engine_roaring"}},
PlayAnimation{_delay{4.5},ActorId{100001},AnimationId{"Think_End"},Duration{1}}
}]],
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(So, what I'm facing isn't just Sibylle but the Empire behind her. Do I stand a chance? Not for now, at least... I need a plan B.)",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101008/19494E46"
        },
        [10100824] = {
          Camera = "-312.145508,-248.166504,147.804199,0.00115,-6.100185,35.0606,35.000008,524.896545,false,Manual,4.0",
          ContentFR = "Bon, ça suffit. Je suis partie trop longtemps, et les Asphodèles doivent déjà être en proie à de nouveaux troubles.",
          DialogueId = 10100824,
          FacialId = {
            [1] = "200003:Uninterested01"
          },
          FinalCamera = "-316.333984,-242.202637,147.804199,0.00115,-6.100219,35.060589,35.000008,512.693665,false,Manual,4.0",
          GUID = "19494E70",
          LookAt = {
            [1] = "200003:n(200003)",
            [2] = "200002:n(200003)",
            [3] = "100001:n(200003)"
          },
          NextDialogue = 10100825,
          SpeakNpcId = 200003,
          Subtitle = "Let's call it a day. I've been out so long, The Asphodel might be in quite disarray by now.",
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "200003:p(200)"
          },
          VoiceName = "voice/$Locale$/story/1002/101008/19494E70"
        },
        [10100825] = {
          ContentFR = "...",
          DialogueId = 10100825,
          ExStoryInfo = "Player",
          GUID = "19494E9A",
          NextDialogue = 10100826,
          SpeakNpcId = 100001,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/101008/19494E9A"
        },
        [10100826] = {
          Camera = "243.654297,-17.984863,184.813477,0.00001,-12.0,-177.54332,40.0,144.905365,false,Manual,5.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Débrouille-toi pour survivre par tes propres moyens.",
          DialogueId = 10100826,
          FinalCamera = "243.705078,-18.997559,184.813477,0.00001,-12.0,-177.54332,40.0,144.905365,false,Manual,5.0",
          GUID = "19494EC4",
          NextDialogue = 10100827,
          SpeakNpcId = 200003,
          Subtitle = "Try and survive on your own.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101008/19494EC4"
        },
        [10100827] = {
          Camera = "243.705078,-18.997559,184.813477,0.00001,-12.0,-177.54332,40.0,144.905365,false,Manual,5.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Si tu n’en es même pas capable, alors oublie ces folies de réclamer quoi que ce soit à Sibylle.",
          DialogueId = 10100827,
          FacialId = {
            [1] = "200003:None"
          },
          FinalCamera = "243.705078,-18.997559,184.813477,0.00001,-12.0,-177.54332,40.0,322.049652,false,Manual,4.0",
          GUID = "19494EEE",
          NextDialogue = 10100828,
          Scripts = "PlayAnimation{_delay{2.3},ActorId{200003},AnimationId{\"Disagree\"},Duration{1}}",
          SpeakNpcId = 200003,
          Subtitle = "If you can't even do that, then don't ever again mention any mad talk about confronting Sibylle to get your stuff back.",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101008/19494EEE"
        },
        [10100828] = {
          Camera = "9226.649414,237.270508,2393.015137,0.001301,-4.701137,91.655624,12.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "... Au nord, il y a une auberge qu’on appelle la Maison d’Hypnos. Peut-être accepteront-ils d’héberger quelqu’un avec un passé aussi flou que le tien.",
          DialogueId = 10100828,
          FinalCamera = "9226.649414,237.270508,2683.057129,0.001305,-1.701017,91.455482,13.5,100000.0,false,DoNotOverride,2.8",
          GUID = "19494F18",
          LookAt = {
            [1] = "200002:n(200003)"
          },
          NextDialogue = 10100829,
          SpeakNpcId = 200003,
          Subtitle = "...Look, there's an inn up north called the Hypnos' House that might take in someone with a sketchy backstory like you.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101008/19494F18"
        },
        [10100829] = {
          Camera = "-48.555664,-40.226562,104.655273,0.001197,-6.101961,37.254295,35.000008,176.661667,false,Manual,4.0",
          ContentFR = "Tu veux dire... ce vieux \"manoir hanté\" ?",
          DialogueId = 10100829,
          FacialId = {
            [1] = "200002:Unacceptable01"
          },
          GUID = "19494F42",
          NextDialogue = 10100830,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200002},AnimationId{"Shock_Start"},Duration{1.7}},
PlayAnimation{ActorId{200002},AnimationId{"Shock_End"},Duration{0.5}},
PlayAnimation{ActorId{200002},AnimationId{"Talk01_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "You mean... that spooky \"haunted house\"?",
          VoiceName = "voice/$Locale$/story/1002/101008/19494F42"
        },
        [10100830] = {
          Camera = "549.845703,44.259766,152.453613,0.00125,-3.698793,-176.199417,50.0,661.213013,false,Manual,8.0",
          ContentFR = "À part cet endroit si mal famé que même les soldats s’abstiennent d’y fouiller, qui accepterait d’accueillir un Charon sans permis de circulation ?",
          DialogueId = 10100830,
          GUID = "19494F6C",
          NextDialogue = 10100831,
          SpeakNpcId = 200003,
          Subtitle = "Where else would take in a Charon without a travel permit but a place that is so creepy even the soldiers didn't want to search?",
          TalkActionId = {
            [1] = "200002:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101008/19494F6C"
        },
        [10100831] = {
          Camera = "549.845703,44.259766,152.453613,0.00125,-3.698793,-176.199417,50.0,661.213013,false,Manual,8.0",
          ContentFR = "Je comprends, merci.",
          DialogueId = 10100831,
          ExStoryInfo = "Player",
          FinalCamera = "425.745117,36.01416,155.745605,0.001252,-3.698793,-176.199371,85.0,529.144958,false,Manual,8.0",
          GUID = "19494F96",
          LookAt = {
            [1] = "200002:n(200003)"
          },
          NextDialogue = 10100832,
          Scripts = "MoveTo{_delay{1.5},ActorId{200003},TargetPoint{\"P101008Kami\"},MoveSpeed{60}}",
          SpeakNpcId = 100001,
          Subtitle = "I understand, thank you.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 16,
          VoiceName = "voice/$Locale$/story/1002/101008/19494F96"
        },
        [10100832] = {
          Camera = "-216.379883,-128.320312,189.390137,0.00122,-17.30224,36.452347,50.0,370.186615,false,Manual,4.0",
          ContentFR = "Bon... Très bien ! Puisque tu as l’air {性别:tout seul et perdu|toute seule et perdue}, je vais t’y emmener, à cette Maison d’Hypnos !",
          DialogueId = 10100832,
          FacialId = {
            [1] = "200002:Unhappy02"
          },
          FinalCamera = "-230.984375,-107.061035,189.390137,0.001221,-17.30224,32.253994,50.0,351.443298,false,Manual,6.0",
          GUID = "19494FC0",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          Scripts = [[
SEQ{
PARA{
LookAt{LookAtDescription{"200002:n(100001)"}},
PlayAnimation{_delay{0.2},ActorId{200002},AnimationId{"Sigh_Start"},Duration{2.1}}
},
PlayAnimation{ActorId{200002},AnimationId{"Sigh_End"},Duration{0.4}},
PlayAnimation{ActorId{200002},AnimationId{"Think_Start"},Duration{1.3}},
PlayAnimation{ActorId{200002},AnimationId{"Confident_Start"},Duration{3.6}},
PlayAnimation{ActorId{200002},AnimationId{"SpecialConfident_Start"},Duration{2.5}},
PlayAnimation{ActorId{200002},AnimationId{"Explain01_Start"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Umm... Alright! Seeing you so lonely and lost, I'll take you to this Hypnos' House to see what's what!",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101008/19494FC0"
        },
        [10100901] = {
          ContentFR = "Ce \"manoir hanté\" dont tu parlais, qu’est-ce que c’est au juste ?",
          DialogueId = 10100901,
          ExStoryInfo = "Player",
          GUID = "19495B12",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10100902,
          SpeakNpcId = 100001,
          Subtitle = "What exactly did you mean by \"haunted house\"?",
          VoiceName = "voice/$Locale$/story/1002/101009/19495B12"
        },
        [10100902] = {
          ContentFR = "C’est ce que disent les clients des Asphodèles. On entend toujours les mêmes histoires...",
          DialogueId = 10100902,
          GUID = "19495B3C",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10100903,
          SpeakNpcId = 200002,
          Subtitle = "I heard about it from the guests at The Asphodel. There's always someone complaining—",
          VoiceName = "voice/$Locale$/story/1002/101009/19495B3C"
        },
        [10100903] = {
          ContentFR = "C’est une auberge immense, mais les portes restent fermées jour et nuit, et les voyageurs de passage sont toujours refoulés.",
          DialogueId = 10100903,
          GUID = "19495B66",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10100904,
          SpeakNpcId = 200002,
          Subtitle = "Like, even though it's such a big inn, the doors are always shut tight every day, turning away any travellers from outside the town...",
          VoiceName = "voice/$Locale$/story/1002/101009/19495B66"
        },
        [10100904] = {
          ContentFR = "Les pensionnaires n’en sortent jamais et parfois, une odeur étrange, difficile à décrire, s’en dégage...",
          DialogueId = 10100904,
          GUID = "19495B90",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10100905,
          SpeakNpcId = 200002,
          Subtitle = "Or how the lodgers seem to never ever leave, and sometimes, there's this really weird smell drifting from the inside of the house...",
          VoiceName = "voice/$Locale$/story/1002/101009/19495B90"
        },
        [10100905] = {
          ContentFR = "Ou encore, la mine de l’aubergiste est plus glaciale que les eaux du Lac du Deuil, on dirait qu’il tient une boutique de cercueils plutôt qu’une auberge !",
          DialogueId = 10100905,
          GUID = "19495BBA",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10100906,
          SpeakNpcId = 200002,
          Subtitle = "And how the innkeeper's face is colder than the waters of Lamenting Lake... It's as if he's not running an inn, but a coffin shop!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495BBA"
        },
        [10100906] = {
          ContentFR = "Ça n’a pas l’air si terrible. Je croyais qu’elle grouillait de Souillés et de Sibylles.",
          DialogueId = 10100906,
          ExStoryInfo = "Player",
          GUID = "19495BE4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10100907,
          SpeakNpcId = 100001,
          Subtitle = "It doesn't sound too bad. I thought it was crammed with Filthoids and Sibylles.",
          VoiceName = "voice/$Locale$/story/1002/101009/19495BE4"
        },
        [10100907] = {
          ContentFR = "Mais, puisqu’ils n’accueillent pas les étrangers, je crains de ne pas pouvoir...",
          DialogueId = 10100907,
          ExStoryInfo = "Player",
          GUID = "19495C0E",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10100908,
          SpeakNpcId = 100001,
          Subtitle = "But, if they don't welcome outsiders, I doubt if I can...",
          VoiceName = "voice/$Locale$/story/1002/101009/19495C0E"
        },
        [10100908] = {
          ContentFR = "Enfin, il semble que Madame Camilla Scarlet jouisse d’une certaine réputation, ici. Peut-être que je pourrais m’en servir...",
          DialogueId = 10100908,
          ExStoryInfo = "Player",
          GUID = "19495C38",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10100909,
          SpeakNpcId = 100001,
          Subtitle = "Still, it seems Ms Camilla Scarlet holds some sway here. Hmm... perhaps I could leverage her influence a little bit.",
          VoiceName = "voice/$Locale$/story/1002/101009/19495C38"
        },
        [10100909] = {
          ContentFR = "Pas besoin, pas besoin ! Tu peux dire que tu es avec Snow. Dès aujourd’hui, tu es sous ma protection, mon petit larbin !",
          DialogueId = 10100909,
          GUID = "19495C62",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10100910,
          SpeakNpcId = 200002,
          Subtitle = "Nah, you can use Snow's name. From now on, you're under my wing, my little minion!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495C62"
        },
        [10100910] = {
          ContentFR = "Merci, mais... « larbin », c’est quoi ?",
          DialogueId = 10100910,
          ExStoryInfo = "Player",
          GUID = "19495C8C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10100911,
          SpeakNpcId = 100001,
          Subtitle = "Thank you, but what's a \"minion\"?",
          VoiceName = "voice/$Locale$/story/1002/101009/19495C8C"
        },
        [10100911] = {
          ContentFR = "C’est le mot qu’on utilise dans les romans, pour désigner l’acolyte favori du grand Roi Démon !",
          DialogueId = 10100911,
          GUID = "19495CB6",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10100912,
          SpeakNpcId = 200002,
          Subtitle = "It's what they call someone in those stories who's the favourite lackey of the awesome Demon King!",
          VoiceName = "voice/$Locale$/story/1002/101009/19495CB6"
        },
        [10100912] = {
          ContentFR = "Il y a tant de Luno dans le monde... Pourquoi crois-tu que seule Snow a hérité de ces magnifiques cornes ? C’est bien la preuve que je suis destinée à devenir un Roi Démon !",
          DialogueId = 10100912,
          GUID = "19495CE0",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10100913,
