          SpeakNpcId = 200006,
          SpeakNpcName = "UI_Npc_Name_Woman_5",
          Subtitle = "Don't be upset, Mr Henrik isn't really that greedy. It's just we've been quite strapped for cash lately, otherwise he wouldn't consider selling his old house to make ends meet.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101016/1949CE3E"
        },
        [10101604] = {
