          SpeakNpcId = 200006,
          SpeakNpcName = "UI_Npc_Name_Woman_5",
          Subtitle = "Oh, I haven't introduced myself. I'm Psyche, a lodger at the Hypnos' House. And sometimes I help Mr Henrik out.",
