        [10101613] = {
          Camera = "-60.662338,-53.026855,76.228203,0.001223,6.199516,-64.1409,25.000002,82.790894,false,Manual,6.0",
          ContentFR = "Franchement... qui aurait cru que ce tenancier si rustre et morose ait à son service une fille aussi serviable et pleine de cœur...",
          DialogueId = 10101613,
          FacialId = {
            [1] = "200002:Smile01",
            [2] = "100001:Satisfy01"
          },
          FinalCamera = "-65.389259,-55.179199,76.228287,0.001223,6.199516,-62.741081,25.000002,84.377983,false,Manual,6.0",
          GUID = "1949CFE2",
          LookAt = {
            [1] = "200002:n(200006)",
            [2] = "100001:n(200006)",
            [3] = "200006:n(200006)"
          },
          NextDialogue = 10101614,
          SpeakNpcId = 200002,
          Subtitle = "Who'd have thought such a rude and gloomy innkeeper would have such a nice and helpful kid working for him...",
          TalkActionId = {
            [1] = "200002:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101016/1949CFE2"
        },
        [10101614] = {
          Camera = "390.112488,2686.977783,149.298599,0.001179,0.600053,-100.143715,50.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Grâce à elle, on a enfin trouvé un toit. Allons nous reposer un peu, je suis crevée moi aussi !",
          DialogueId = 10101614,
          FacialId = {
            [1] = "200002:Smile02",
            [2] = "100001:Satisfy01"
          },
          FinalCamera = "390.112488,2686.977783,221.628708,0.001179,0.600053,-100.143715,50.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1949D00C",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          SpeakNpcId = 200002,
          Subtitle = "Thanks to her, we've finally found a place to stay. Let's rest a bit — I'm quite tired too!",
          ToFinalCameraBlendTime = 9,
          TurnTo = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1002/101016/1949D00C"
        },
        [10101701] = {
          Camera = "246.411194,114.218262,109.373657,0.001183,-13.29721,-168.309631,50.000011,93.339378,false,Manual,5.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "<I>Trop de choses se sont enchaînées... Des rêves étranges, ce mystérieux manteau blanc, Sibylle, et \"n° 0\"... Tout semble lié, mais je n’arrive pas à assembler les pièces.</>",
          DialogueId = 10101701,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FinalCamera = "246.411194,114.218262,113.977905,0.001183,-2.89725,-167.911087,50.000011,301.668488,false,Manual,8.0",
          GUID = "1949DE52",
          NextDialogue = 10101702,
          RelatedWikiId = {
            [1] = 101003,
            [2] = 408003,
            [3] = 405001,
            [4] = 304001,
            [5] = 204002,
            [6] = 201001,
            [7] = 201002,
            [8] = 101005
          },
          Scripts = "SitOrStand{ActorId{100001},State{\"Sit\"}}",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(So much has happened... Weird dreams, that mysterious man in a white cloak, Sibylle, and \"No. 0\"... They all seem to be connected somehow, but I can't figure it out.)",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101017/1949DE52"
        },
        [10101702] = {
          Camera = "32.615486,-85.951172,141.394852,0.001194,-10.600405,119.473099,50.000011,174.121933,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "<I>La seule certitude, c’est que j’ai perdu Berry...</>",
          DialogueId = 10101702,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          FinalCamera = "20.154007,-63.900879,136.737762,0.001195,-11.20041,119.473099,50.000011,174.121933,false,Manual,22.0",
          GUID = "1949DE7C",
          NextDialogue = 10101703,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(The only thing I'm certain of is that I've lost Berry...)",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101017/1949DE7C"
        },
        [10101703] = {
          Camera = "521.906738,-420.427246,557.736206,0.001077,-34.294342,143.62709,35.000008,749.64917,false,Manual,4.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "<I>... Si elle a réussi à s’échapper, elle doit tout faire pour me retrouver... Mais je dois aussi envisager le pire : que Sibylle l’ait emmenée avec la XIIIᵉ Légion.</>",
          DialogueId = 10101703,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FinalCamera = "459.354492,-374.35791,505.258728,0.001073,-34.094299,144.027039,35.000008,749.64917,false,Manual,4.0",
          GUID = "1949DEA6",
          NextDialogue = 10101704,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...If she's managed to escape, she'd surely try everything to find me... Of course, I can't rule out the worst-case scenario that Sibylle has taken her to the Legion.)",
          ToFinalCameraBlendTime = 16,
          VoiceName = "voice/$Locale$/story/1002/101017/1949DEA6"
        },
        [10101704] = {
          Camera = "-50.302734,-52.980469,119.29213,0.001284,-17.399469,87.817223,35.000011,114.672478,false,Manual,4.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "<I>Heureusement, Sibylle semble avoir besoin de Berry pour une raison que j’ignore. Elle ne devrait pas lui faire de mal.</>",
          DialogueId = 10101704,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FinalCamera = "-50.302734,-52.980469,119.29213,0.001284,-6.599526,87.2173,35.000011,101.591904,false,Manual,6.0",
          GUID = "1949DED0",
          NextDialogue = 10101705,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(The silver lining is, it seemed that Sibylle needed Berry for some reason, so she probably wouldn't harm her.)",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101017/1949DED0"
        },
        [10101705] = {
          Camera = "-107.57486,-199.331177,124.529968,0.001198,-6.0,70.830925,35.0,247.426239,false,Manual,3.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "<I>Bref... Je dois trouver un moyen de gagner un peu d’argent à Givrelac, obtenir un permis de circulation, et seulement après décider de mes prochaines étapes.</>",
          DialogueId = 10101705,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FinalCamera = "-112.579315,-197.591553,124.529968,0.001198,-6.0,70.830925,35.0,247.426239,false,Manual,2.5",
          GUID = "1949DEFA",
          NextDialogue = 10101801,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...Anyway, I need to scrape together some money in Icelake, get a travel permit, and then plan for my next move.)",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101017/1949DEFA"
        },
