PlayAnimation{_delay{1.7},ActorId{200002},AnimationId{"Talk03_Start"},Duration{1}},
CameraMoveTo{_delay{2},TargetPosition{"-832.959534,-488.830078,151.296875,0.000224,5.201264,-23.814783,15.0,1925.824097,false,DoNotOverride,1.2"},duration{0}},
CameraMoveTo{_delay{2.1},TargetPosition{"-824.300415,-469.21582,151.296875,0.000223,5.201264,-23.812887,15.0,1925.824097,false,DoNotOverride,1.2"},duration{3}},
CameraMoveTo{_delay{5.2},TargetPosition{"-900.001282,-1053.816406,304.507812,0.000222,-3.798944,89.185745,15.0,1925.824097,false,DoNotOverride,1.2"},duration{0}},
CameraMoveTo{_delay{5.3},TargetPosition{"-925.375122,-1053.544922,304.507812,0.000222,-3.798944,89.185745,15.0,1925.824097,false,DoNotOverride,1.2"},duration{3}},
CameraMoveTo{_delay{8.4},TargetPosition{"-1724.791748,-1096.714844,124.908203,0.000239,-0.99884,22.983885,40.0,391.225189,false,Manual,2.3"},duration{0}},
CameraMoveTo{_delay{8.5},TargetPosition{"-1726.286499,-1093.358398,124.908203,0.000239,-0.99884,23.999477,40.0,1928.980469,false,Manual,3.0"},duration{3}}
}]],
          TalkActionId = {
