PlayAnimation{ActorId{200003},AnimationId{"Talk02_Start"},Duration{2.5}},
PlayAnimation{ActorId{200003},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Let's get one thing straight — this isn't child's play, nor an easy gig. It's TRUE that in this place, no one would probe into your past or background, but the rewards always come with risks.",
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/story/1002/101026/194A734A"
        },
        [10102610] = {
          Camera = "-294.801819,-157.509766,135.695312,0.001227,1.1999,33.90601,60.000004,460.630157,false,Manual,12.0",
          ContentFR = "Pas très robuste, mais {性别:déterminé|déterminée}.",
          DialogueId = 10102610,
          FacialId = {
            [1] = "200006:None",
            [2] = "200011:None"
          },
          GUID = "194A7374",
          LookAt = {
            [1] = "200011:n(200003)"
          },
          NextDialogue = 10102611,
          SpeakNpcId = 200003,
          Subtitle = "You don't look tough, though your courage is admirable.",
          TalkActionId = {
            [1] = "200003:Talk03_Start",
            [2] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101026/194A7374"
        },
        [10102611] = {
          Camera = "-43.718262,-1261.714844,610.828125,0.001481,-22.297657,82.031219,25.0,166.832703,false,DoNotOverride,22.0",
          ContentFR = "Tu es effectivement plus {性别:fort|forte} qu’un simple Charon, Je t’ai {性别:vu|vue} te battre. Mais pour devenir Chasseur de Phoxène, la force seule ne suffit pas... il te faut prouver que tu peux gérer toutes sortes d’imprévus et de clients.",
          DialogueId = 10102611,
          FinalCamera = "-98.231934,-1254.261719,610.828125,0.001477,-22.297657,82.031197,25.0,166.832703,false,DoNotOverride,22.0",
          GUID = "194A739E",
          NextDialogue = 10102612,
          Scripts = "SetLocation{ActorId{200011},TargetPoint{\"P10102601Maer\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200003,
          Subtitle = "You're indeed stronger than the average Charon — I've seen you in a fight. But brute strength isn't enough to qualify you to be a Phoxhunter. You need to prove that you're capable of dealing with all possible contingencies and a very mixed group of clients.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101026/194A739E"
        },
        [10102612] = {
          Camera = "-328.773987,-167.959961,134.214844,0.001226,0.0,28.499939,50.0,499.398407,false,Manual,10.0",
          ContentFR = "Et justement, une occasion de le prouver vient de se présenter.",
          DialogueId = 10102612,
          GUID = "194A73C8",
          LookAt = {
            [1] = "200003:n(200011)",
            [2] = "100001:n(200003)"
          },
          NextDialogue = 10102613,
          SpeakNpcId = 200003,
          Subtitle = "It just so happens that a chance for that came in just now.",
          VoiceName = "voice/$Locale$/story/1002/101026/194A73C8"
        },
