        },
        [10103215] = {
          ContentFR = "Madame Camilla ? Vous êtes venue exprès pour nous aider ?",
          DialogueId = 10103215,
          ExStoryInfo = "Player",
          GUID = "194AD507",
          LookAt = {
            [1] = "200011:n(200003)",
            [2] = [[

200003:n(200061)]]
          },
          NextDialogue = 10103216,
          SpeakNpcId = 200061,
          Subtitle = "Ms Camilla? Did you come all this way to back us up?",
          TalkActionId = {
            [1] = "200061:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101032/194AD507"
        },
        [10103216] = {
          Camera = "161.710938,-228.921875,139.269562,0.000084,-0.599397,96.330261,40.000023,212.641296,false,DoNotOverride,10.0",
          ContentFR = "Tu as traversé la moitié du monde pour venir à Givrelac. Si tu devais finir dès ton premier jour dans ce trou à rats, ce serait un peu pathétique, non ?",
          DialogueId = 10103216,
          FacialId = {
            [1] = "200011:None"
          },
          GUID = "194AD566",
          NextDialogue = 10103217,
          Scripts = "SetLocation{ActorId{200002},TargetPoint{\"101032Bai3\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200003,
          Subtitle = "Since you've come all this way to Icelake, it'd be a shame to meet your maker in this sorry spot on your first day, wouldn't it?",
          TalkActionId = {
            [1] = "200061:Explain02_End",
            [2] = "200003:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101032/194AD566"
        },
        [10103217] = {
          Camera = "-224.279297,-53.761719,138.360504,0.000002,-6.599731,-7.001203,20.000008,396.617218,false,DoNotOverride,5.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Tss, et moi qui croyais que c’était quelqu’un d’important... juste la vieille tenancière de taverne. Tu crois faire quoi ? Appeler la garde ? Tu penses vraiment que les hauts placés se soucient d’un foutu Charon—",
          DialogueId = 10103217,
          FacialId = {
            [1] = "200011:Unhappy02"
          },
          FinalCamera = "-289.886719,-45.707031,146.008194,-0.0,-6.599731,-7.001234,20.000011,115.779877,false,DoNotOverride,5.0",
          GUID = "194AD567",
          LookAt = {
            [1] = "200003:n(200053)",
            [2] = "200011:n(200053)",
            [3] = "200002:n(200002)",
            [4] = "200061:n(200061)",
            [5] = "200014:n(200053)"
          },
          Scripts = [[
PARA{
PlayAnimation{_delay{6},ActorId{200053},AnimationId{"Talk01_Start"},Duration{1}},
LookAt{_delay{1.6},LookAtDescription{"200061:n(200053)"}},
TurnTo{_delay{2},TurnToDescription{"200003:n(200053)"}},
PlayAnimation{_delay{12},ActorId{200053},AnimationId{"Talk01_End"},Duration{1}}
}]],
          SpeakNpcId = 200053,
          Subtitle = "Tsk, I thought some big shot came, turns out it's just a tavern-keeping old hen. What are you gonna do about it? Call the guards? Do you really think those high-ups give a d*mn about Charons...",
          TalkActionId = {
            [1] = "200003:Talk03_End"
          },
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "200011:p(50)",
            [2] = "200002:n(200053)",
            [3] = "200061:n(200053)"
          },
          VoiceName = "voice/$Locale$/story/1002/101032/194AD567"
        },
        [10103301] = {
          Camera = "-162.447266,-154.685547,143.238815,0.000128,0.478216,70.251183,35.0,200.0,false,Manual,5.0",
          ContentFR = "Non. On s’occupe de toi \"à notre manière\". On va t’apprendre quelques leçons de vie que ta pauvre mère n’a visiblement jamais eues le temps de t’enseigner.",
          DialogueId = 10103301,
          GUID = "194AE4D2",
          LookAt = {
            [1] = "200053:n(200003)"
          },
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405004,
            [3] = 201008,
            [4] = 201004,
            [5] = 201005
          },
          SpeakNpcId = 200003,
          Subtitle = "We'll handle you \"our way\" — teach you a few life lessons your presumably absent mother never did.",
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101033/194AE4D2"
        },
        [10103302] = {
          Camera = "66.533203,37.944336,174.613312,0.000149,-10.000031,-167.999481,35.0,212.973618,false,Manual,4.0",
          ContentFR = "Parle pas de ma mère ! Lâche-moi, sale sorcière !",
          DialogueId = 10103302,
          GUID = "194AE4FC",
          LookAt = {
            [1] = "200003:n(200053)"
          },
          SpeakNpcId = 200053,
          Subtitle = "Don't bring my mum into this...! Let go of me! You nasty hag!",
          TalkActionId = {
            [1] = "200053:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101033/194AE4FC"
        },
        [10103303] = {
          ContentFR = "Camilla saisit le poignet du jeune homme avec une force surprenante, on peut même entendre les os de son avant-bras craquer.",
          DialogueId = 10103303,
          GUID = "194AE4FD",
          IsBlack = 1,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/talk_grip_1\"},PlayAs2D{true}}",
          Subtitle = "Camilla grips the young man's wrist with surprising strength — you can even hear the bones of his forearm cracking.",
          TalkActionId = {
            [1] = "200003:Talk03_End",
            [2] = "200053:Angry01_End"
          }
        },
        [10103304] = {
          ContentFR = "Mais soudain, Camilla pousse un cri étouffé et recule en titubant, les yeux rivés sur le poignet du jeune homme.",
          DialogueId = 10103304,
          GUID = "194AE4FE",
          IsBlack = 1,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/talk_grip_2\"},PlayAs2D{true}}",
          Subtitle = "But then, Camilla gasps sharply and stumbles back, her eyes fixed on the young man's wrist."
        },
        [10103305] = {
          ContentFR = "Sa manche, déchirée dans la bagarre, révèle une marque noire profonde gravée dans sa peau. La marque est si sinistre qu'un seul mot vient à l'esprit : « démon ».",
          DialogueId = 10103305,
          GUID = "194AE4FF",
          IsBlack = 1,
          Subtitle = "His sleeve, torn in the scuffle, reveals a deep, black mark etched into his skin. The mark looks so sinister that one word comes to mind — \"demon.\""
        },
        [10103306] = {
          Camera = "-173.716797,-156.699219,143.634827,0.000134,-0.121851,67.454094,35.0,200.0,false,Manual,2.8",
          ContentFR = "...",
          DialogueId = 10103306,
          FinalCamera = "-140.003906,-116.556641,150.852997,0.000134,-0.121851,67.455696,35.0,157.698685,false,Manual,4.0",
