          Scripts = "PlayAnimation{_delay{2},ActorId{200011},AnimationId{\"Give\"},Duration{1}}",
          SpeakNpcId = 200011,
          Subtitle = "Oh, I almost forgot — here's your reward!",
          TalkActionId = {
            [1] = "200011:SpecialHoldHelmet_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF572"
        },
        [10103505] = {
          ContentFR = "Héhé, merci infiniment ! Tu m’as sauvé la vie, {性别:mon frère d’une autre mère|ma sœur d'un autre père} !",
          DialogueId = 10103505,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200011:Smile02"
          },
          GUID = "194AF573",
          NextDialogue = 10103506,
          SpeakNpcId = 200011,
          Subtitle = "Thank you so much! You're a lifesaver, my {性别:brother from another mother|sister from another mister}!",
          TalkActionId = {
            [1] = "200011:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF573"
        },
        [10103506] = {
          Camera = "-33.322266,90.494141,136.335449,0.000018,-4.258083,-78.357025,35.000011,1.5,false,Disable,1.2",
          ContentFR = "Bon, je dois vite redistribuer ces pièces. Moi, d’habitude, je \"m’approvisionne\" un peu partout à Givrelac. Si tu as besoin de moi, il suffit de donner mon nom dans les taudis, et ils t'aideront à me trouver.",
          DialogueId = 10103506,
          GUID = "194AF574",
          Scripts = "PlayAnimation{_delay{2},ActorId{200011},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 200011,
          Subtitle = "Well, I gotta go divvy up these coins. I usually do my \"shopping\" all over Icelake. If you need me, just drop my name in the slums, and they'll help you find me.",
          TalkActionId = {
            [1] = "200011:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF574"
        },
        [10103507] = {
          ContentFR = "Allez, petit larbin, allons vite revoir Camilla !",
          DialogueId = 10103507,
          GUID = "194AF575",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Alright, let's go find Camilla, little minion!",
          VoiceName = "voice/$Locale$/story/1002/101034/194AF575"
        },
        [10103601] = {
