        [10103806] = {
          Camera = "-220.573608,96.777344,99.291016,0.001347,2.799155,-17.691002,30.000002,397.786072,false,Manual,2.5",
          ContentFR = "Alors c’était toi ? {性别:Tout|Toute} propre sur toi... Qui aurait pu imaginer que tu en étais capable ?",
          DialogueId = 10103806,
          GUID = "194B37AC",
