}]],
          SpeakNpcId = 200065,
          Subtitle = "So it was you? Looking all neat and tidy, who'd have thought you had it in you?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101038/194B37AC"
        },
        [10103807] = {
          Camera = "284.5,160.327148,200.447266,0.001179,-15.600097,-147.194611,35.000011,345.690643,false,Manual,2.25",
          ContentFR = "Merci, ce n'était rien.",
