          },
          FinalCamera = "1278.716797,2242.87793,1126.149414,0.000085,-21.600649,-103.932632,25.0,168.419693,false,DoNotOverride,5.0",
          GUID = "194BBB16",
          NextDialogue = 10104608,
          Scripts = [[
SEQ{
