        [10105402] = {
          Camera = "-72.519531,598.007812,133.294922,0.001335,-3.398285,-86.062561,30.0,755.136902,false,Manual,8.0",
          ContentFR = "Il était juste là, sans qu’aucun nom ne soit dessus, non ? Allez, chez nous, dans notre boulot, y a pas de « premier arrivé, premier servi ».",
          DialogueId = 10105402,
          FacialId = {
            [1] = "200021:Blink"
