        },
        [10105601] = {
          ContentFR = "Ce petit passage n’a rien à voir avec la galerie qu’on a traversée tout à l’heure... on dirait plutôt que quelqu’un l’a creusé à la main.",
          DialogueId = 10105601,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5E2A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105602,
          SpeakNpcId = 100001,
          Subtitle = "This trail feels different from the one we passed through earlier, almost as if it's been hand-dug by someone.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E2A"
        },
        [10105602] = {
          ContentFR = "C’est vrai, tiens ! Y’a même plusieurs pioches qui traînent... On dirait bien que des aventuriers sont déjà passés par là !",
          DialogueId = 10105602,
          Duration = 3,
          GUID = "194C5E54",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105603,
          SpeakNpcId = 200002,
          Subtitle = "Yeah, there are even pickaxes lying around here... Looks like other adventurers have been here before us!",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E54"
        },
        [10105603] = {
          ContentFR = "Hein, Psyche, pourquoi t’as l’air toute pâle ? Depuis tout à l’heure tu dis rien.",
          DialogueId = 10105603,
          Duration = 3,
          GUID = "194C5E7E",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105604,
          SpeakNpcId = 200002,
          Subtitle = "You okay, Psyche? You look pale, and you've been awfully quiet for a while.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E7E"
        },
        [10105604] = {
          ContentFR = "Ah, m-moi ? J’ai l’air si mal que ça ?",
          DialogueId = 10105604,
          Duration = 3,
          GUID = "194C5EA8",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10105605,
          SpeakNpcId = 200006,
          Subtitle = "Ah, h-have I?",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5EA8"
        },
        [10105605] = {
          ContentFR = "Peut-être que... j’ai encore la chair de poule en repensant à ce monstre. Et si... si cette créature avait autrefois été...",
          DialogueId = 10105605,
          Duration = 3,
          GUID = "194C5ED2",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105606,
          SpeakNpcId = 200006,
          Subtitle = "Guess I still reelling from that monster. I keep wondering if it could have once been...",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5ED2"
        },
        [10105606] = {
          ContentFR = "Bah, ça sert à rien de flipper ! On est là avec toi !",
          DialogueId = 10105606,
          Duration = 3,
          GUID = "194C5EFC",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10105607,
          SpeakNpcId = 200002,
          Subtitle = "Relax! We're right here with you!",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5EFC"
        },
        [10105607] = {
          ContentFR = "Et puis, ce type a dit que mon petit larbin était {性别:un|une} \"Daimon\", super {性别:puissant|puissante}, pas vrai ? Même si dix autres Souillés déboulaient, ils ne feraient pas le poids face à {性别:lui|elle} !",
          DialogueId = 10105607,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5F26",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10105608,
          SpeakNpcId = 200002,
          Subtitle = "That Outsider said that my little minion is a strong \"Daimon,\" right? So even if ten more Filthoids came at us, they'd be no match for {性别:him|her}.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5F26"
        },
        [10105608] = {
          ContentFR = "Arrête un peu... je suis déjà à bout de forces, et Psyche faisait juste semblant d’être sûre d’elle.",
          DialogueId = 10105608,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5F50",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10105609,
          SpeakNpcId = 100001,
          Subtitle = "Cut it out. I'm nearly spent, and Psyche was just bluffing.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5F50"
        },
        [10105609] = {
          ContentFR = "L’important c’est que vous n’ayez rien. Peut-être que j’aurais pas dû vous embarquer là-dedans...",
          DialogueId = 10105609,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5F7A",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10105610,
          SpeakNpcId = 100001,
          Subtitle = "I'm just relieved you're both safe... Maybe I shouldn't have involved you two in such a dangerous event.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5F7A"
        },
        [10105610] = {
          ContentFR = "Non ! Au contraire, cette \"aventure\"... je suis vraiment heureuse de l’avoir vécue.",
          DialogueId = 10105610,
          Duration = 3,
          GUID = "194C5FA4",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10105611,
          SpeakNpcId = 200006,
          Subtitle = "No, not at all! I'm really happy that I took part in such an adventure.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5FA4"
        },
        [10105611] = {
          ContentFR = "Je n’aurais jamais imaginé quitter ma ville avec des {性别:amis|amies}, explorer l’inconnu, se mettre dans le pétrin, et affronter ensemble des ennemis terrifiants.",
          DialogueId = 10105611,
          Duration = 3,
          GUID = "194C5FCE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105612,
          SpeakNpcId = 200006,
          Subtitle = "I never thought I'd get out of town with friends, explore unknown places, get in trouble, and fight evil enemies together.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5FCE"
        },
        [10105612] = {
          ContentFR = "... Maintenant que j’y repense, j’ai encore un peu la tête qui tourne, comme si j’avais fait un rêve en plein jour.",
          DialogueId = 10105612,
          Duration = 3,
          GUID = "194C5FF8",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10105613,
          SpeakNpcId = 200006,
          Subtitle = "Now that I think about it, it all feels so unreal, like living a daydream.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5FF8"
        },
        [10105613] = {
          ContentFR = "Tu vois ! Même Psyche est d’accord avec moi !",
          DialogueId = 10105613,
          Duration = 3,
          GUID = "194C6022",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10105614,
          SpeakNpcId = 200002,
          Subtitle = "See? Psyche agrees with me!",
          VoiceName = "voice/$Locale$/story/1002/101056/194C6022"
        },
        [10105614] = {
          ContentFR = "...",
          DialogueId = 10105614,
          Duration = 3,
          GUID = "194C604C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/101056/194C604C"
        },
        [10105701] = {
          ContentFR = "Hé, là-bas... c’est pas Henrik ? Qu’est-ce qu’il fiche ici ?",
          DialogueId = 10105701,
          Duration = 3,
          GUID = "194C6E92",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Isn't that Henrik over there...? What's he doing here?",
          VoiceName = "voice/$Locale$/story/1002/101057/194C6E92"
        },
