        [10105806] = {
          Camera = "-146.253906,8.684082,132.574219,0.000076,6.199974,-15.00077,35.0,195.174042,false,Manual,4.235867",
          ContentFR = "Oublie l’Éclat stellaire. Le premier jour où tu es entrée à la Maison d’Hypnos, tu te souviens de ce que je t’ai dit ?",
          DialogueId = 10105806,
          GUID = "194C7FCC",
          NextDialogue = 10105807,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200005},AnimationId{"Disagree"},Duration{1}}
}]],
          SpeakNpcId = 200005,
          Subtitle = "Forget the Crystallo. Remember what I said on your first day at the Hypnos' House?",
          VoiceName = "voice/$Locale$/story/1002/101058/194C7FCC"
        },
        [10105807] = {
          Camera = "178.701172,37.807617,161.741211,0.000015,-4.800045,-164.274582,75.000015,266.881348,false,Manual,10.075966",
          ContentFR = "« Ne sors pas sans prévenir. Si tu dois aller quelque part, viens m’en parler d’abord. »",
          DialogueId = 10105807,
          FacialId = {
            [1] = "200059:Sad02"
          },
          GUID = "194C7FF6",
          LookAt = {
            [1] = "100001:n(200005)"
          },
          NextDialogue = 10105808,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200059},AnimationId{"Disagree"},Duration{1}},
LookAt{_delay{3.1},LookAtDescription{"200059:p(P10105807)"}}
}]],
          SpeakNpcId = 200059,
          Subtitle = "\"Don't wander off, and inform me first if you need to go somewhere.\"",
          TalkActionId = {
            [1] = "200059:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101058/194C7FF6"
        },
        [10105808] = {
          Camera = "1323.615234,728.070801,483.275635,0.000105,-13.600149,-151.096634,25.000006,772.823364,false,Manual,3.486191",
          ContentFR = "Bien. Rappelle-toi toujours de ça. Avant de décider quoi que ce soit, pense à mes paroles... et pense à la raison pour laquelle tes parents t’ont confiée à moi.",
          DialogueId = 10105808,
          FacialId = {
            [1] = "200059:Sad01"
          },
          FinalCamera = "1330.711914,731.98584,485.236328,0.000105,-13.600121,-151.096634,25.000006,772.823364,false,Manual,3.486191",
          GUID = "194C8020",
          LookAt = {
            [1] = "200059:p(P10105807)"
          },
          NextDialogue = 10105809,
          Scripts = [[
SEQ{
PlayAnimation{_delay{8.5},ActorId{200005},AnimationId{"Talk02_Start"},Duration{7}},
PlayAnimation{ActorId{200005},AnimationId{"Talk02_End"},Duration{1.2}},
PlayAnimation{ActorId{200005},AnimationId{"Sigh_Start"},Duration{1}}
}]],
          SpeakNpcId = 200005,
          Subtitle = "So you do remember. Before making any decisions, think about what I've told you, and why your parents left you in my care.",
          TalkActionId = {
            [1] = "200059:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101058/194C8020"
        },
        [10105809] = {
          Camera = "178.701172,37.807617,161.741211,0.000015,-4.800045,-164.274582,75.000015,266.881348,false,Manual,10.075966",
          Content = "如果耽误了正事，或者被旁人看出来什么……你知道后果。",
          DialogueId = 10105809,
          GUID = "194C8021",
          LookAt = {
            [1] = "200059:n(200005)"
          },
          NextDialogue = 10105810,
          Scripts = "PlayAnimation{_delay{3.5},ActorId{200059},AnimationId{\"Agree\"},Duration{1.2}}",
          SpeakNpcId = 200005,
          Subtitle = "If anything happens that messes things up, or if people start asking questions... you know what's at stake.",
          VoiceName = "voice/$Locale$/story/1002/101058/194C8021"
        },
        [10105810] = {
          Camera = "-24.399414,695.678223,83.461426,-0.0,1.399731,-90.397453,35.000011,289.913574,false,DoNotOverride,5.0",
          ContentFR = "... Pardonnez-moi. Je vous ai causé du souci.",
          DialogueId = 10105810,
          FinalCamera = "-24.267578,715.09375,82.98584,-0.0,1.399731,-90.397453,35.000011,289.913574,false,DoNotOverride,5.0",
          GUID = "194C804A",
          NextDialogue = 10105811,
          SpeakNpcId = 200059,
          Subtitle = "...I'm so sorry, Mr Henrik.",
          TalkActionId = {
            [1] = "200005:Sigh_End",
            [2] = "200059:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101058/194C804A"
        },
        [10105811] = {
          Camera = "-146.253906,8.684082,132.574219,0.000076,6.199974,-15.000834,35.0,195.174042,false,Manual,4.235867",
          ContentFR = "Tu es une gentille fille, mais ne laisse plus jamais cela se reproduire.",
