          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101058/194C809E"
        },
        [10105813] = {
          Camera = "115.382812,-61.85791,174.962402,0.000078,-10.400042,155.7948,35.0,252.340637,false,Manual,4.235867",
          ContentFR = "Occupe-toi de tes affaires et cesse d’entraîner les autres dans tes histoires. Ce sera mieux pour tout le monde.",
          DialogueId = 10105813,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "194C80C8",
          LookAt = {
            [1] = "200005:n(100001)"
          },
          NextOptions = {
            [1] = 101058131,
            [2] = 101058132
          },
          SpeakNpcId = 200005,
          Subtitle = "Tend your own garden and don't drag irrelevant people into your business. It's better for everyone.",
          VoiceName = "voice/$Locale$/story/1002/101058/194C80C8"
        },
        [10105814] = {
          Camera = "-248.442383,-210.168945,153.489746,0.000127,-3.200374,44.998043,35.000008,345.865082,false,Manual,5.41403",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Elle n’est pas votre fille. Et même si elle l’était, vous n’avez pas à lui refuser une si petite liberté. Vous savez à quel point ça l’a rendue heureuse de sortir un peu ?",
          DialogueId = 10105814,
          ExStoryInfo = "Player",
