        },
        [10106302] = {
          Camera = "-134.704102,-202.952148,138.852539,0.000154,3.5,48.999954,35.0,313.251678,false,Manual,4.143779",
          ContentFR = "Désolé pour la mise en scène. J’ai dû te subtiliser l’Éclat stellaire afin d’écarter les curieux et pouvoir discuter seul à seul avec toi.",
          DialogueId = 10106302,
          FacialId = {
            [1] = "200021:Confident01",
