          },
          VoiceName = "voice/$Locale$/story/1002/101067/194D1320"
        },
        [10106706] = {
          Camera = "43.533447,190.366211,124.659058,0.001232,1.999995,-65.366714,15.0,73.0,false,Manual,2.8",
          ContentFR = "Je ne suis pas d’ici, je ne connais pas vos règles à Givrelac. Chez moi, un marché c’est simple : argent contre marchandise, dans la main.",
          DialogueId = 10106706,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          FinalCamera = "43.533447,190.366211,132.331177,0.001219,-1.200071,-66.367569,15.000005,73.0,false,Manual,2.8",
          GUID = "194D134A",
          NextDialogue = 10106707,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1.5},ActorId{100001},AnimationId{"DisagreeHead"},Duration{1.8}},
PlayAnimation{ActorId{100001},AnimationId{"Think_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "I'm not from here, I'm not familiar with Icelake's ways. Where I come from, a deal means cash in one hand, goods in the other.",
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/story/1002/101067/194D134A"
        },
        [10106707] = {
