CameraMoveTo{_delay{5.8},TargetPosition{"620.515625,-151.44223,98.601562,0.000176,0.599984,-72.797096,50.0,221.792267,false,Manual,9.747352"},duration{0}},
PlayAnimation{_delay{2},ActorId{200006},AnimationId{"Explain02_Start"},Duration{1}}
}]],
          SpeakNpcId = 200006,
          Subtitle = "? What are you doing here? Does Mr Henrik know about this...? Ah, please come with me.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101069/194D33C6"
        },
        [10106904] = {
          Camera = "574.537109,-151.818848,105.101562,0.000176,-3.599967,-55.999626,30.0,238.777985,false,Manual,2.5",
          ContentFR = "Elisa, attends-moi un instant, je reviens tout de suite.",
          DialogueId = 10106904,
          Duration = 2,
          FacialId = {
            [1] = "200006:Happy02"
          },
          FinalCamera = "578.134766,-149.392853,105.101562,0.000176,-3.599967,-55.999626,30.0,240.854767,false,Manual,2.5",
          GUID = "194D33F0",
          LookAt = {
            [1] = "200006:n(200045)",
            [2] = "200045:n(200006)"
          },
          Scripts = "PlayAnimation{_delay{1.5},ActorId{200006},AnimationId{\"Explain01_Start\"},Duration{1}}",
          SpeakNpcId = 200006,
          Subtitle = "Could you wait here for a moment, Elisa? I'll be right back.",
          TalkActionId = {
            [1] = "200006:Explain02_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101069/194D33F0"
        },
        [10107001] = {
          Camera = "118.46875,153.970703,155.228516,0.000001,-1.999538,-127.20298,70.0,235.416611,false,Manual,8.483248",
          ContentFR = "Monsieur Henrik n’aime pas que des étrangers entrent ici sans autorisation... et toi, tu t’es déjà disputé avec lui. S’il te voit...",
          DialogueId = 10107001,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:Unhappy01"
          },
          FinalCamera = "118.46875,153.970703,152.742188,0.000001,-1.999538,-127.20298,70.0,235.416611,false,Manual,8.483248",
          GUID = "194D43DA",
          NextDialogue = 10107002,
          RelatedWikiId = {
            [1] = 301004,
            [2] = 405002,
            [3] = 201006,
            [4] = 201007,
            [5] = 201009
          },
          Scripts = [[
