LookAt{_delay{6},LookAtDescription{"200006:p(P101070Saiqi3)"}}
}
]],
          SpeakNpcId = 200006,
          Subtitle = "Mr Henrik doesn't allow outsiders to come in, and you two got off on the wrong foot back then. If he sees you...",
          TalkActionId = {
            [1] = "200006:DisagreeHead"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101070/194D43DA"
        },
        [10107002] = {
          Camera = "-11.103516,535.533691,150.160156,0.0,-3.999349,-87.40229,35.0,549.519409,false,Manual,4.291738",
          ContentFR = "Tu es venu pour le logement, n’est-ce pas ? Ne t’inquiète pas, cache-toi ici un instant. Je vais plaider ta cause auprès de Monsieur Henrik. Il acceptera sûrement que tu restes quelques jours de plus.",
          DialogueId = 10107002,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "-11.103516,535.533691,148.048828,0.0,-3.999328,-87.402275,35.0,549.519409,false,Manual,4.291738",
          GUID = "194D43DB",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextOptions = {
            [1] = 101070021
          },
          Scripts = "PlayAnimation{_delay{2.5},ActorId{200006},AnimationId{\"Explain02_Start\"},Duration{0.1}}",
          SpeakNpcId = 200006,
          Subtitle = "You're here for the lodging stuff, aren't you? Don't worry, just hide here for a bit. I'll talk to Mr Henrik again. He'll surely let you stay for a few more days.",
          ToFinalCameraBlendTime = 18,
          VoiceName = "voice/$Locale$/story/1002/101070/194D43DB"
        },
        [10107003] = {
          Camera = "-5.626953,58.096191,144.837891,0.000018,2.200605,-108.797859,35.000008,93.94474,false,Manual,8.483248",
          ContentFR = "Vraiment ? C’est merveilleux... ! Mais cet homme est tellement... autoritaire. Comment as-tu fait ?",
          DialogueId = 10107003,
          FacialId = {
            [1] = "200006:Happy01",
            [2] = "100001:Smile01"
          },
          GUID = "194D4404",
          NextOptions = {
            [1] = 101070031,
            [2] = 101070032
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{8.2},TargetPosition{"-28.324219,26.407959,145.527344,0.000018,1.800424,16.803524,35.000008,93.94474,false,Manual,8.483248"},duration{0}},
PlayFacial{_delay{4.2},ActorId{200006},FacialId{"Unhappy01"}},
PlayAnimation{_delay{8.3},ActorId{100001},AnimationId{"Think_Start"},Duration{1}}
}]],
          SpeakNpcId = 200006,
          Subtitle = "Ah, really? That's great! But that man is so... domineering. How did you make that happen?",
          TalkActionId = {
            [1] = "200006:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D4404"
        },
        [10107004] = {
          Camera = "-18.091797,61.085693,144.837891,0.000013,2.400675,-101.197495,35.0,93.94474,false,Manual,8.483248",
          ContentFR = "Vraiment ? Je n’aurais jamais cru qu’il puisse être aussi... sensible.",
          DialogueId = 10107004,
          FacialId = {
            [1] = "200006:Shock01"
          },
          GUID = "194D442E",
          NextDialogue = 10107005,
          SpeakNpcId = 200006,
          Subtitle = "Really? I wouldn't have pegged Mr Outsider as someone so sensitive.",
          VoiceName = "voice/$Locale$/story/1002/101070/194D442E"
        },
        [10107005] = {
          Camera = "-239.527344,-76.267822,140.667969,0.000016,-1.799365,15.204763,35.000008,357.107239,false,Manual,1.688559",
          ContentFR = "Il est... un peu différent de ce que son apparence effrontée laisse penser. Quoi qu’il en soit...",
          DialogueId = 10107005,
          ExStoryInfo = "Player",
          FinalCamera = "-258.751953,-81.134766,141.289062,0.000016,-1.7994,14.20407,35.000008,357.107239,false,Manual,1.688559",
          GUID = "194D4458",
          NextDialogue = 10107032,
          SpeakNpcId = 100001,
          Subtitle = "He's... a bit different than his brash exterior suggests. Anyway...",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101070/194D4458"
        },
        [10107006] = {
          Camera = "-5.626953,58.096191,144.837891,0.000018,2.200605,-108.797859,35.000008,93.94474,false,Manual,8.483248",
          ContentFR = "Quoi ?! C’est vrai ? Il a besoin de médicaments ? J’en ai ici, tu pourrais lui en porter...",
          DialogueId = 10107006,
          FacialId = {
            [1] = "200006:Shock01"
          },
          GUID = "194D4482",
          NextDialogue = 10107007,
          SpeakNpcId = 200006,
          Subtitle = "Really? Does he need any medicine? I've got some. Can you bring it to him?",
          VoiceName = "voice/$Locale$/story/1002/101070/194D4482"
        },
        [10107007] = {
          Camera = "-451.320312,-14.900146,146.650391,0.000003,-2.799394,3.99817,40.0,549.519409,false,Manual,4.291738",
          ContentFR = "Pas besoin ! Il a ce qu’il faut chez lui. Quoi qu’il en soit...",
          DialogueId = 10107007,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:None",
            [2] = "100001:Happy02"
          },
          FinalCamera = "-492.1875,-17.756348,148.652344,0.000003,-2.799394,3.998163,40.0,549.519409,false,Manual,4.291738",
          GUID = "194D44AC",
          NextDialogue = 10107032,
          SpeakNpcId = 100001,
          Subtitle = "That's alright! He's got his own supply at home. Anyway...",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101070/194D44AC"
        },
        [10107008] = {
          Camera = "-10.556641,523.596924,149.322266,0.0,-3.999328,-87.402275,35.0,549.519409,false,Manual,4.291738",
          ContentFR = "Oui. Tout le monde est là pour se soigner... moi y compris.",
          DialogueId = 10107008,
          FacialId = {
            [1] = "200006:Happy01",
            [2] = "100001:None"
          },
          FinalCamera = "-11.103516,535.533691,150.160156,0.0,-3.999349,-87.40229,35.0,549.519409,false,Manual,4.291738",
          GUID = "194D44D6",
          LookAt = {
            [1] = "200006:p(P101070Saiqi1)"
          },
          NextDialogue = 10107009,
          SpeakNpcId = 200006,
          Subtitle = "Yes. Everyone's recovering from some conditions here... me included.",
          TalkActionId = {
            [1] = "200006:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101070/194D44D6"
        },
        [10107009] = {
          Camera = "-20.644531,3.659912,145.527344,0.000015,0.800341,28.803095,35.000008,93.944733,false,Manual,8.483248",
          ContentFR = "Et toi, ça va ? Tu ne m’avais pas dit que tu étais malade...",
          DialogueId = 10107009,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "194D4500",
          NextDialogue = 10107010,
          Scripts = "SetRotation{SetRotationDescription{\"100001:p(19)\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Are you doing okay? You didn't tell me you were sick...",
          TalkActionId = {
            [1] = "100001:Explain02_Start",
            [2] = "200006:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D4500"
        },
        [10107010] = {
          Camera = "71.65625,83.940186,147.439453,0.000008,0.000321,-127.996948,50.0,160.507706,false,Manual,22.0",
          ContentFR = "...",
          DialogueId = 10107010,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "82.693359,98.06543,147.439453,0.000008,0.000321,-127.996948,50.0,160.507706,false,Manual,22.0",
          GUID = "194D452A",
          NextDialogue = 10107011,
          Scripts = [[
PARA{
SetRotation{SetRotationDescription{"100001:p(-19)"}},
LookAt{_delay{1},LookAtDescription{"200006:p(P101070Saiqi2)"}}
}]],
          SpeakNpcId = 200006,
          Subtitle = "...",
          TalkActionId = {
            [1] = "200006:SpecialThink_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101070/194D452A"
        },
        [10107011] = {
          ContentFR = "Ce n’est rien, juste une broutille. Hier encore, je suis allée avec toi jusqu’à la fosse. Tu n’as pas à t’en faire.",
          DialogueId = 10107011,
          GUID = "194D4554",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextDialogue = 10107012,
          Scripts = "PlayAnimation{_delay{1},ActorId{200006},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 200006,
          Subtitle = "It's just a minor ailment. I was even strong enough to explore the pit with you, remember? Don't worry about me.",
          TalkActionId = {
            [1] = "200006:SpecialThink_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D4554"
        },
        [10107012] = {
          Camera = "-451.320312,-14.900146,146.650391,0.000003,-2.799394,3.99817,40.0,549.519409,false,Manual,4.291738",
          ContentFR = "D’accord... tant que tu vas bien, ça me rassure.",
          DialogueId = 10107012,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:None"
          },
          FinalCamera = "-492.1875,-17.756348,148.652344,0.000003,-2.799394,3.998163,40.0,549.519409,false,Manual,4.291738",
          GUID = "194D457E",
          NextDialogue = 10107013,
          SpeakNpcId = 100001,
          Subtitle = "Mm, I'm glad you're okay.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101070/194D457E"
        },
        [10107013] = {
          Camera = "-32.240234,44.838135,145.527344,0.000015,2.000453,6.202501,35.0,93.94474,false,Manual,8.483248",
          ContentFR = "<I>... Alors tous les pensionnaires de la Maison d’Hypnos souffrent d’une certaine maladie...</>",
          DialogueId = 10107013,
          DisableMouth = 1,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "194D45A8",
          NextDialogue = 10107032,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...So, all the lodgers at the Hypnos' House suffer from some kind of illness.)",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D45A8"
        },
        [10107014] = {
          ContentFR = "Nous avons eu quelques différends par le passé, et j’aimerais apaiser les choses. Si possible, j’aimerais lui rendre visite à l’avenir.",
          DialogueId = 10107014,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "194D45D2",
          NextDialogue = 10107015,
          Scripts = "PlayAnimation{_delay{3},ActorId{100001},AnimationId{\"ScratchHead_End\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "I've got off on the wrong foot with Mr Henrik, so I'm looking to make amends with him. If there's a chance, I'd like to visit him in the future.",
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101070/194D45D2"
        },
        [10107015] = {
          Camera = "16.691406,22.081543,148.732422,0.000052,-2.199649,-135.59375,25.0,75.553604,false,Manual,3.314391",
          ContentFR = "Vraiment ? Monsieur Henrik est presque toujours à la maison ! Si tu en as envie, tu peux venir quand tu veux, du moment qu’il est d’accord.",
          DialogueId = 10107015,
          FacialId = {
            [1] = "200006:Happy01",
            [2] = "100001:None"
          },
          GUID = "194D45FC",
          NextDialogue = 10107016,
          SpeakNpcId = 200006,
          Subtitle = "Really? Mr Henrik is almost always at home! You're welcome to visit anytime if he says it's okay!",
          VoiceName = "voice/$Locale$/story/1002/101070/194D45FC"
        },
        [10107016] = {
          Camera = "16.691406,22.081543,148.732422,0.000052,-2.199649,-135.59375,25.0,75.553604,false,Manual,3.314391",
          ContentFR = "... Et si tu acceptes de passer de temps en temps, pour raconter à tout le monde des histoires de ta ville natale, le Sud, l’océan, tous ces endroits que nous n’avons jamais vus… oh, je suis sûre que ça les rendrait tellement heureux !",
          DialogueId = 10107016,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200006:Happy02"
          },
          FinalCamera = "21.3125,26.552246,148.972656,0.000052,-2.199649,-135.993698,25.0,75.553604,false,Manual,3.314391",
          GUID = "194D4626",
          NextDialogue = 10107017,
          SpeakNpcId = 200006,
          Subtitle = "If you'd be willing to come here and share stories about your hometown — the South, the ocean... All those places we've never been... everyone here would be thrilled!",
          TalkActionId = {
            [1] = "200006:Explain02_Start",
