          },
          NextDialogue = 10107102,
          RelatedWikiId = {
            [1] = 201006,
            [2] = 405002
          },
          SnapShot = "HEART",
          Subtitle = "(The office door is old yet spotless and polished. The doorknob won't budge an inch. Clearly, it's been locked from the inside.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 6
        },
        [10107102] = {
