        [10107103] = {
          Camera = "282.953125,16.883362,138.378906,0.000045,-0.999564,171.800415,40.0,264.652649,false,Manual,8.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Le bureau... est interdit. Personne, à part Monsieur Henrik Ethelred, ne peut y entrer.",
