          },
          ToFinalCameraBlendTime = 3.5,
          VoiceName = "voice/$Locale$/story/1002/101071/194D54C0"
        },
        [10107105] = {
          Camera = "390.625,575.312744,19.304688,0.000079,2.99999,-125.595558,25.0,116.605362,false,Manual,2.125575",
          ContentFR = "Il n’y a rien d’intéressant... Cet endroit n’apporte que le malheur.",
          DialogueId = 10107105,
          FinalCamera = "390.625,575.312744,29.46875,0.000079,2.99999,-125.595558,25.0,534.811157,false,Manual,1.2",
          GUID = "194D54EA",
          NextOptions = {
