          ExStoryInfo = "Player",
          FinalCamera = "-202.859375,56.315125,199.617188,0.000315,-16.803425,-21.701178,40.000011,263.10965,false,Manual,5.0",
          GUID = "194D9661",
          NextDialogue = 10107506,
          SpeakNpcId = 100001,
