PlayAnimation{_delay{3.5},ActorId{100006},AnimationId{"Explain01_End"},Duration{1}},
PlayAnimation{_delay{3},ActorId{100006},AnimationId{"Explain02_Start"},Duration{1}}
}]],
          SpeakNpcId = 100006,
          Subtitle = "We searched the nearby waters immediately after {性别:he|she} fell off the cliff. Theoretically speaking, {性别:he|she} shouldn't have drifted far. Unless...",
          VoiceName = "voice/$Locale$/story/1002/101080/194DE892"
        },
        [10108006] = {
          Camera = "-46.48291,518.056641,12.158203,0.000022,5.999481,-87.199181,25.000002,1007.337402,false,Manual,1.2",
