        [10108502] = {
          Camera = "-115.567871,-338.226562,281.567627,0.000205,-25.200125,66.302895,40.000011,546.789001,false,Manual,2.0",
          ContentFR = "Tu es vraiment insupportable l’Étranger ! Me faire monter la garde ici... Les grands talents de ce Roi Démon sont faits pour mener des chasses, pas pour surveiller cet homme morose !",
          DialogueId = 10108502,
          FacialId = {
            [1] = "200064:Doubt01"
          },
          FinalCamera = "-99.011719,-300.50293,244.98291,0.000237,-21.799927,66.303619,40.000011,483.54599,false,Manual,2.0",
          GUID = "194E3A1C",
          LookAt = {
            [1] = "200064:n(200021)"
          },
          NextDialogue = 10108503,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200064},AnimationId{"SpecialConfident_End"},Duration{1}},
PlayAnimation{_delay{1},ActorId{200064},AnimationId{"Talk03_Start"},Duration{1}},
PlayAnimation{_delay{4},ActorId{200064},AnimationId{"Talk03_End"},Duration{1}},
PlayAnimation{ActorId{200064},AnimationId{"Angry01_Start"},Duration{1}}
}]],
          SpeakNpcId = 200064,
          Subtitle = "You're such a pest, Outsider! Making me stand watch here... This Demon King's great talents are meant for leading hunts, not keeping tabs on that gloomy man!",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101085/194E3A1C"
        },
        [10108503] = {
          Camera = "-98.271973,73.517578,107.652588,0.000086,12.605715,-48.246983,50.0,203.457687,false,Manual,8.0",
          ContentFR = "C’est parce que vous avez un don particulier pour agir en toute discrétion, Ô Roi Démon. Regardez-nous, nous sommes si grands et maladroits que Henrik nous repérerait en un clin d’œil.",
          DialogueId = 10108503,
          FacialId = {
            [1] = "200021:Smile02",
            [2] = "100001:Smile02"
          },
          FinalCamera = "-97.125,82.003906,106.376465,0.000081,12.805723,-50.447262,50.0,211.465363,false,Manual,8.0",
          GUID = "194E3A46",
          NextDialogue = 10108504,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200021},AnimationId{"Explain01_Start"},Duration{3.3}},
PlayAnimation{ActorId{200021},AnimationId{"Explain01_End"},Duration{1.6}},
PlayAnimation{ActorId{200021},AnimationId{"Explain02_Start"},Duration{1}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "That's because, you have a special gift for acting by stealth, \"Your Majesty.\" Look at us, all big and clumsy, we'd be spotted by Henrik in no time.",
          TalkActionId = {
            [1] = "200064:Bai_Idle"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/story/1002/101085/194E3A46"
        },
        [10108504] = {
          Camera = "28.857422,-61.823242,137.124268,0.000146,-17.4002,77.194801,50.0,180.819702,false,Manual,8.0",
          ContentFR = "<I>Hum</>, tu sais flatter mon génie... Attends ! Mais tu veux juste dire que je suis petite, n’est-ce pas !",
          DialogueId = 10108504,
          FacialId = {
            [1] = "200064:Happy02"
          },
          FinalCamera = "32.961914,-44.213867,131.525879,0.000162,-17.200184,76.594582,50.0,160.226791,false,Manual,8.0",
          GUID = "194E3A70",
          NextDialogue = 10108505,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200064},AnimationId{"Think_Start"},Duration{5.5}},
PARA{
PlayAnimation{ActorId{200064},AnimationId{"Angry01_Start"},Duration{0.1}},
PlayFacial{ActorId{200064},FacialId{"Angry01"}},
}
}]],
          SpeakNpcId = 200064,
          Subtitle = "Hmph, smart of you to have recognised my greatness — wait! That's just a roundabout way of calling me short!!",
          TalkActionId = {
            [1] = "200021:Explain02_End",
            [2] = "100001:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101085/194E3A70"
        },
        [10108505] = {
          Camera = "38.050293,248.716797,38.96167,0.000147,18.199257,-84.5942,50.000008,342.942749,false,Manual,5.0",
          ContentFR = "Non, non ! Mais comment ! Vous êtes la plus grande et la plus imposante ! Les portes de Givrelac ont été construites spécialement pour vous...",
          DialogueId = 10108505,
          FacialId = {
            [1] = "100001:Smile01",
            [2] = [[

200021:Smile02]],
            [3] = [[

200064:None]]
