        [10109404] = {
          Camera = "19.714844,-41.03125,94.928711,0.00024,0.189367,126.75769,20.000008,100000.0,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Tu crois que les voyageurs ont allumé leurs lampes ? Est-ce que les fenêtres brillent, chaudes et douces, comme de petites flammes dans un foyer ?",
          DialogueId = 10109404,
          FacialId = {
            [1] = "200006:Happy02"
          },
          FinalCamera = "31.46875,-56.716797,94.905273,0.000241,-2.210632,127.157379,20.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "194ECDEE",
          LookAt = {
