]],
          SpeakNpcId = 200006,
          Subtitle = "That's nice. Do the passengers have lights on? Are the windows looking pretty and warm, like tiny flames in a fireplace?",
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/story/1002/101094/194ECDEE"
        },
        [10109405] = {
          ContentFR = "<I>C’était juste le vent.</>",
          DialogueId = 10109405,
          GUID = "10109405",
