          GUID = "194ECE42",
          NextDialogue = 10109408,
          SpeakNpcId = 100001,
          Subtitle = "Psyche... when did your eyesight start to fade?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101094/194ECE42"
        },
        [10109408] = {
          Camera = "97.648438,-137.328125,117.448242,0.00021,-3.611073,122.97995,50.000008,336.90625,false,Manual,7.017789",
          ContentFR = "Depuis quand... ?",
          DialogueId = 10109408,
          GUID = "194ECE6C",
          NextDialogue = 10109409,
          SpeakNpcId = 200006,
          Subtitle = "When was it...",
          TalkActionId = {
            [1] = "200006:Sigh_Start",
            [2] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101094/194ECE6C"
        },
        [10109409] = {
          Camera = "-173.027344,119.447266,100.172852,0.000213,0.788593,-32.62458,50.000008,287.144684,false,Manual,4.056031",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Je ne sais pas vraiment. Je pensais que ce n’était que passager, comme avant, que ça s’éclaircirait... Mais cette fois... non.",
          DialogueId = 10109409,
          FacialId = {
            [1] = "200006:Unhappy01"
          },
          FinalCamera = "-153.613281,107.021484,100.492188,0.000213,0.788593,-32.62458,50.000008,287.144684,false,Manual,4.056031",
          GUID = "194ECE6D",
          NextDialogue = 10109410,
          SpeakNpcId = 200006,
          Subtitle = "I don't really know. I thought it'd be the same as before — just blurry for a while, and then it'd go away. But now it just...",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101094/194ECE6D"
        },
        [10109410] = {
          Camera = "60.910156,-67.048828,109.011719,0.000257,-3.799709,132.574326,35.0,339.966736,false,DoNotOverride,2.608581",
          ContentFR = "N’en parlons plus. Il y a un endroit où j’aimerais aller... Tu viens avec moi ?",
          DialogueId = 10109410,
          FacialId = {
            [1] = "200006:None"
          },
          GUID = "194ECE96",
          NextOptions = {
            [1] = 10109411
          },
          Scripts = [[
