          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(\"Can't leave Icelake\"... What does she mean by that?)",
          VoiceName = "voice/$Locale$/story/1002/101100/194F300A"
        },
        [10110002] = {
