          },
          VoiceName = "voice/$Locale$/story/1002/101101/194F4072"
        },
        [10110102] = {
          ContentFR = "N-N’approche pas... ou je tire !",
          DialogueId = 10110102,
          GUID = "194F409C",
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
