        [10110814] = {
          Camera = "146.675781,107.209351,63.904297,0.000043,10.599551,-114.99369,30.000008,58.469177,false,Manual,22.0",
          ContentFR = "... Attends... Vous voulez dire que l’affaire de Rougerive, le Dégradé qu’on croyait assassiné... c’était votre fille ? Votre fille, Hayley ?!",
          DialogueId = 10110814,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200061:Shock01"
          },
          FinalCamera = "141.306641,95.676819,66.283203,0.000045,10.999548,-113.993042,30.000008,58.469177,false,Manual,22.0",
          GUID = "194FB56C",
          NextDialogue = 10110815,
          SpeakNpcId = 200061,
          Subtitle = "...Are you saying... the Deteriorator who was \"killed\" in Scarletriver... was your daughter Hayley?",
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB56C"
        },
        [10110815] = {
          Camera = "7.115234,146.331909,155.232422,-5.000005,-37.004673,-27.967878,20.000011,106.21656,false,DoNotOverride,3.0",
          ContentFR = "... Tu sais ça aussi... Ce n’était que... le dernier sursaut... d’un père désespéré...",
          DialogueId = 10110815,
          GUID = "194FB596",
          LookAt = {
            [1] = "200005:n(200061)"
          },
          NextDialogue = 10110816,
          RelatedWikiId = {
            [1] = 201006
          },
          Scripts = "LookAt{_delay{3},LookAtDescription{\"200005:p(P10110802)\"}}",
          SpeakNpcId = 200005,
          Subtitle = "...You know about that too... That was merely... the last desperate struggle... of a father in despair...",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB596"
        },
        [10110816] = {
          Camera = "61.728516,24.99762,106.603516,0.000052,17.397959,-151.616104,35.0,66.756615,false,DoNotOverride,4.0",
          ContentFR = "Nous t’avons jugé trop vite... Nous nous sommes trompés à ton sujet, Henrik. Pardonne-nous.",
          DialogueId = 10110816,
          GUID = "194FB5C0",
          NextDialogue = 10110817,
          Scripts = "PlayAnimation{_delay{4.5},ActorId{200021},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 200021,
          Subtitle = "We've been wrong about you all along... We're truly sorry, Mr Henrik.",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB5C0"
        },
        [10110817] = {
          Camera = "-88.710938,13.800842,156.517578,0.000078,-25.799891,20.60397,25.0,66.756615,false,DoNotOverride,4.0",
          ContentFR = "... Ne me pardonnez pas...",
          DialogueId = 10110817,
          GUID = "194FB5EA",
          LookAt = {
            [1] = "200005:n(200021)"
          },
          NextDialogue = 10110818,
          Scripts = "SetLocation{ActorId{200021},TargetPoint{\"P101108Aote3\"},Visibility{\"Show\"}},",
          SpeakNpcId = 200005,
          Subtitle = "...Do not forgive...",
          TalkActionId = {
            [1] = "200021:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101108/194FB5EA"
        },
        [10110818] = {
          Camera = "-592.291016,-163.594299,286.255859,0.0,0.0,89.999985,15.0,78.653053,false,DoNotOverride,2.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "J’ai guidé chacun d’eux... vers le sommeil... C’est mon péché... impardonnable...",
          DialogueId = 10110818,
          FinalCamera = "-592.291016,-125.502869,286.255859,0.0,0.0,89.999954,18.0,78.653053,false,DoNotOverride,2.0",
          GUID = "194FB614",
          NextDialogue = 10110819,
          Scripts = [[
PARA{
SetLocation{ActorId{200021},TargetPoint{"P101108Aote4"},Visibility{"Hide"}},
CameraMoveTo{_delay{3.1},TargetPosition{"-758.84375,-464.784851,67.259766,0.000049,-9.999997,89.999992,20.0,78.653053,false,DoNotOverride,2.0"},duration{0}},
CameraMoveTo{_delay{3.2},TargetPosition{"-758.84375,-384.849854,53.855469,0.00005,-3.999991,89.999962,20.0,78.653053,false,DoNotOverride,2.0"},blend{"easeOutQuad"},duration{4}}
}]],
          SpeakNpcId = 200005,
          Subtitle = "I brought them... to sleep... This is my unforgivable sin...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB614"
        },
        [10110819] = {
          Camera = "160.949219,75.923035,61.925781,0.000051,15.199233,-138.792435,18.000004,38.56216,false,DoNotOverride,22",
          ContentFR = "Et Psyche, alors... ?",
          DialogueId = 10110819,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200061:Sad01"
          },
          GUID = "194FB63E",
          NextDialogue = 10110820,
          Scripts = "SetLocation{ActorId{200021},TargetPoint{\"P101108Aote4\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200061,
          Subtitle = "Then what happened to Psyche...?",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB63E"
        },
        [10110820] = {
          Camera = "49.150391,56.432068,87.480469,0.000103,-16.60022,15.224733,30.0,212.168549,false,Manual,4.0",
          ContentFR = "... J’ai tenté... avec l’Éclat stellaire... une dernière fois...",
          DialogueId = 10110820,
          GUID = "194FB668",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110820.T_Story_Recall_10110820'",
          LookAt = {
            [1] = "200005:n(200005)"
          },
          NextDialogue = 10110821,
          RelatedWikiId = {
            [1] = 403002
          },
          SpeakNpcId = 200005,
          Subtitle = "I tried... with the Crystallo of Stella...",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB668"
        },
        [10110821] = {
          Camera = "49.150391,56.432068,87.480469,0.000104,-16.60022,15.224788,30.0,212.168549,false,Manual,4.0",
          ContentFR = "Mais je n’ai pas pu... enrayer la Dégradation...",
          DialogueId = 10110821,
          GUID = "194FB692",
          NextDialogue = 10110822,
          SpeakNpcId = 200005,
          Subtitle = "But still... couldn't avert... Deterioration...",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB692"
        },
        [10110822] = {
          Camera = "49.150391,56.432068,87.480469,0.000104,-16.60022,15.224788,30.0,212.168549,false,DoNotOverride,22",
          ContentFR = "J’aurais dû... comme toujours... l’accompagner jusqu’au bout... Mais cette enfant... elle était si spéciale...",
          DialogueId = 10110822,
          FinalCamera = "49.150391,56.432068,87.480469,0.000105,-14.200106,15.425169,30.000002,212.168549,false,DoNotOverride,22",
          GUID = "194FB6BC",
          LookAt = {
            [1] = "200005:p(P10110802)"
          },
          NextDialogue = 10110823,
          SpeakNpcId = 200005,
          Subtitle = "I was supposed to let her go... like all the others... but that child was so special...",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB6BC"
        },
        [10110823] = {
          ContentFR = "Elle connaissait son sort... et malgré tout, elle continuait de sourire... Des mois durant, elle a brillé... comme un rayon de soleil... dans ce recoin... abandonné des dieux... Comme Hayley... autrefois...",
          DialogueId = 10110823,
          GUID = "194FB6E6",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110823.T_Story_Recall_10110823'",
          NextDialogue = 10110824,
          Scripts = [[
PARA{
SetLocation{ActorId{200021},TargetPoint{"P101108Aote4"},Visibility{"Show"}}
}]],
          SpeakNpcId = 200005,
          Subtitle = "She knew what was coming, yet she's always worn... a smile... For months, she shone like a ray of sunlight... in this... godforsaken place... just like my Hayley...",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB6E6"
        },
        [10110824] = {
          Camera = "-793.369141,305.333496,141.117188,0.0,0.0,91.0,25.0,64.625702,false,DoNotOverride,3.0",
          ContentFR = "... Je suis trop vieux... Je n’ai pas eu la force... de recommencer...",
          DialogueId = 10110824,
          FinalCamera = "-796.826172,305.333496,141.117188,0.0,0.0,89.0,25.0,64.625702,false,DoNotOverride,3.0",
          GUID = "194FB710",
          NextDialogue = 10110825,
          Scripts = [[
PARA{
CameraMoveTo{_delay{2.6},TargetPosition{"-1051.294922,84.778625,89.935547,0.000001,-2.999962,46.000069,20.0,64.625702,false,DoNotOverride,3.0"},duration{0}},
CameraMoveTo{_delay{2.7},TargetPosition{"-1054.726562,88.218262,89.935547,0.000001,-2.999908,43.999973,20.0,64.625702,false,DoNotOverride,3.0"},duration{2.5}}
}]],
          SpeakNpcId = 200005,
          Subtitle = "I'm old... I couldn't... do it again...",
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB710"
        },
        [10110825] = {
          Camera = "214.019531,188.597473,38.626953,0.000023,11.498903,-119.800552,20.000008,66.756615,false,DoNotOverride,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "... Alors tu as hésité. Et dans ce moment de faiblesse, Psyche a perdu la raison. Elle t’a attaqué... et s’est enfuie.",
          DialogueId = 10110825,
          FinalCamera = "214.019531,188.597473,38.626953,0.000024,12.098812,-125.20121,20.000008,66.756615,false,DoNotOverride,4.0",
          GUID = "194FB73A",
          NextDialogue = 10110826,
          SpeakNpcId = 200021,
          Subtitle = "...So in your hesitation, you missed the last window. Psyche lost her mind, attacked you, and ran away.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB73A"
        },
        [10110826] = {
          Camera = "90.787109,25.72345,76.884766,0.000089,9.199021,-96.900833,30.000013,150.0,false,DoNotOverride,4.0",
          ContentFR = "N... non... ce n’est pas possible... !",
          DialogueId = 10110826,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "194FB764",
          NextDialogue = 10110827,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.5},ActorId{200002},AnimationId{"Sigh_Start"},Duration{1}},
SetLocation{ActorId{200021},TargetPoint{"P101108Aote7"},Visibility{"Show"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "How come... I can't believe all this...!",
          TalkActionId = {
            [1] = "200002:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1002/101108/194FB764"
        },
        [10110827] = {
          Camera = "234.738281,193.986938,31.15625,0.000068,14.59791,-132.609695,35.000008,1141.186523,false,Manual,22",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Vous... Daimons... vous pouvez l’arrêter...",
          DialogueId = 10110827,
          FinalCamera = "226.222656,184.724487,34.431641,0.000068,14.59791,-132.609695,35.000008,1141.186523,false,Manual,22",
          GUID = "194FB78E",
          LookAt = {
            [1] = "200005:n(200061)"
          },
          NextDialogue = 10110828,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{2.2},TargetPosition{"175.121094,112.294922,57.634766,0.000084,12.59758,-133.406189,35.000011,84.857964,false,Manual,3.0"},duration{0}},
CameraMoveTo{_delay{0.1},TargetPosition{"168.296875,105.074829,59.853516,0.000084,12.397572,-130.606537,35.000011,71.607964,false,Manual,3.0"},blend{"easeOutQuad"},duration{2.5}}
}]],
          SpeakNpcId = 200005,
          Subtitle = "You're Daimons... you can... stop that child...",
          TalkActionId = {
            [1] = "200002:Sigh_End"
          },
          ToFinalCameraBlendTime = 2.2,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB78E"
        },
        [10110828] = {
          ContentFR = "Elle est si douce... Faire du mal aux autres... c’est la dernière chose qu’elle voudrait...",
          DialogueId = 10110828,
          GUID = "194FB7B8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110823_2.T_Story_Recall_10110823_2'",
          LookAt = {
            [1] = "200005:n(200005)"
          },
          Scripts = [[
PARA{
SetLocation{ActorId{200002},TargetPoint{"P101108Bai5"},Visibility{"Show"}},
SetLocation{ActorId{200021},TargetPoint{"P101108Aote5"},Visibility{"Show"}}
}]],
          SpeakNpcId = 200005,
          Subtitle = "She has such a gentle soul... hurting others is the last thing she'd want... ",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB7B8"
        },
        [10110829] = {
          Camera = "255.0,93.0,161.751953,-26.036255,-90.0,14.036263,20.0,141.431259,false,DoNotOverride,4.0",
          ContentFR = "Je vous en prie... sauvez... Psyche...",
          DialogueId = 10110829,
          FinalCamera = "255.0,93.0,191.751953,-26.036255,-90.0,14.036263,20.0,141.431259,false,DoNotOverride,4.0",
          GUID = "194FB7E2",
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/enrike_death\"},PlayAs2D{true}}",
          SpeakNpcId = 200005,
          Subtitle = "Please... save... Psyche...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB7E2"
        },
        [10110830] = {
          Camera = "207.0,97.0,450.820312,-12.0,-90.0,0.0,20.0,141.431259,false,DoNotOverride,4.0",
          ContentFR = "Sauvez... Hayley...",
          DialogueId = 10110830,
          FinalCamera = "207.0,97.0,550.619141,-12.0,-90.0,0.0,20.0,141.431259,false,DoNotOverride,4.0",
          GUID = "194FB80C",
          SpeakNpcId = 200005,
          Subtitle = "Save... my Hayley...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101108/194FB80C"
        },
        [10110831] = {
          Camera = "252.439453,60.507812,27.751953,0.000142,17.999992,-160.391937,30.0,207.242523,false,Manual,10.0",
          ContentFR = "Monsieur Henrik ! ... ouin...",
          DialogueId = 10110831,
          GUID = "194FB836",
          Scripts = "PlayAnimation{_delay{4.5},ActorId{200002},AnimationId{\"Sigh_Start\"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "Mr Henrik! Waaah...",
          VoiceName = "voice/$Locale$/story/1002/101108/194FB836"
        },
        [10110832] = {
          ContentFR = "Partons. Nous devons faire vite.",
          DialogueId = 10110832,
          GUID = "194FB860",
          SpeakNpcId = 200021,
          Subtitle = "Let's go... we must hurry.",
          TalkActionId = {
            [1] = "200021:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/101108/194FB860"
        },
        [10110901] = {
          Camera = "141.478516,-28.77478,20.587891,0.000128,-1.596734,146.783646,18.0,61.395397,false,Manual,3.0",
          ContentFR = "Vous... vous partez chercher Psyche ?",
          DialogueId = 10110901,
          GUID = "194FC3B2",
          LookAt = {
            [1] = "200045:n(100001)"
          },
          NextDialogue = 10110902,
          Scripts = [[
SEQ{
MoveTo{ActorId{200045},MoveSpeed{60},TargetPoint{"P10110901"}},
PARA{
CameraMoveTo{_delay{0.7},TargetPosition{"228.541016,-90.793152,156.347656,0.000122,-4.996884,156.796143,35.0,446.663574,false,Manual,5.5"},duration{0}},
TurnTo{TurnToDescription{"100001:p(-180)"}},TurnTo{TurnToDescription{"200021:p(170)"}},TurnTo{TurnToDescription{"200002:p(195)"}}
}
}]],
          SpeakNpcId = 200045,
          Subtitle = "Are you... off to find Psyche?",
          VoiceName = "voice/$Locale$/story/1002/101109/194FC3B2"
        },
        [10110902] = {
          Camera = "-231.873047,-73.172028,160.285156,0.000103,-6.596924,20.794041,40.000011,446.663574,false,Manual,5.5",
          ContentFR = "S’il vous plaît, prenez ceci.",
          DialogueId = 10110902,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter01_Flower_1.T_Guide_Chapter01_Flower_1'}",
          GUID = "194FC3DC",
          NextDialogue = 10110903,
          SpeakNpcId = 200045,
          Subtitle = "Please take this with you.",
          TalkActionId = {
            [1] = "200045:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC3DC"
        },
        [10110903] = {
          Camera = "64.572266,91.821472,278.037109,0.0,0.0,89.999992,30.0,100000.0,false,DoNotOverride,22",
          ContentFR = "Psyche nous offrait souvent des fleurs. Même si certains d’entre nous ne pouvaient plus vraiment en sentir le parfum, ni même en distinguer les contours, elle continuait de le faire, en disant que les fleurs portent chance.",
          DialogueId = 10110903,
          FinalCamera = "64.572266,141.821472,278.037109,0.0,0.0,89.999992,30.0,100000.0,false,DoNotOverride,22",
          GUID = "194FC406",
          LookAt = {
            [1] = "200045:p(P10106801)"
          },
          NextDialogue = 10110904,
          SpeakNpcId = 200045,
          Subtitle = "Psyche often gave us flowers. Even though some of us can barely smell or see them clearly anymore, she kept doing it, saying flowers bring good luck.",
          TalkActionId = {
            [1] = "200045:Talk02_End"
          },
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/story/1002/101109/194FC406"
        },
        [10110904] = {
          Camera = "-64.513672,-54.797607,154.447266,0.000147,-5.19662,21.383118,35.000008,170.88736,false,Manual,3.0",
          ContentFR = "... Mais quand j’ai voulu lui rendre sa gentillesse, il était déjà trop tard.",
          DialogueId = 10110904,
          GUID = "194FC430",
          NextDialogue = 10110905,
          SpeakNpcId = 200045,
          Subtitle = "...But by the time I wanted to return her kindness, it was already too late.",
          TalkActionId = {
            [1] = "200045:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC430"
        },
        [10110905] = {
          Camera = "-230.103516,-78.412262,153.914062,0.000093,-5.797054,21.191561,35.000008,351.556366,false,Manual,4.0",
          ContentFR = "Apportez-lui cette fleur, je vous en prie. C’est sa préférée.",
          DialogueId = 10110905,
          GUID = "194FC45A",
          LookAt = {
            [1] = "200045:n(100001)"
          },
          NextDialogue = 10110906,
          SpeakNpcId = 200045,
          Subtitle = "Please bring this flower to her. It's her favourite.",
          TalkActionId = {
            [1] = "200045:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC45A"
        },
        [10110906] = {
          Camera = "-7.181641,-249.865479,233.710938,0.000057,-29.099882,93.194183,15.000005,100000.0,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Et dites-lui... que tous les pensionnaires de la Maison d’Hypnos l’attendent...",
          DialogueId = 10110906,
          FinalCamera = "-4.027344,-306.261597,265.148438,0.000057,-29.099882,93.194183,15.000005,100000.0,false,DoNotOverride,22.0",
          GUID = "194FC484",
          NextDialogue = 10110907,
          SpeakNpcId = 200045,
          Subtitle = "And let her know that everyone at the Hypnos' House is waiting for her...",
          TalkActionId = {
            [1] = "200045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101109/194FC484"
        },
        [10110907] = {
          Camera = "262.748047,-120.47818,147.644531,0.000102,-4.196898,153.589691,35.000008,434.590698,false,Manual,3.0",
          ContentFR = "Je le ferai. Je sauverai Psyche.",
          DialogueId = 10110907,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "194FC4AE",
          NextDialogue = 10110908,
          SpeakNpcId = 100001,
          Subtitle = "I will. I'm going to do everything I can to save her.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC4AE"
        },
        [10110908] = {
          Camera = "51.148438,0.197876,149.753906,0.000102,-4.600037,179.58815,35.000011,140.0,false,DoNotOverride,22",
          ContentFR = "Ou du moins... je l’empêcherai de commettre quelque chose qu’elle regretterait.",
          DialogueId = 10110908,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "38.595703,0.288055,150.865234,0.000102,-4.600037,179.58815,35.000011,140.0,false,Manual,DoNotOverride,22",
          GUID = "194FC4D8",
          Scripts = [[
PARA{
CameraMoveTo{_delay{2.1},TargetPosition{"-22.845703,1.761353,150.835938,0.000102,-4.600037,179.58815,35.000011,65.552429,false,DoNotOverride,22"},duration{0}},
CameraMoveTo{_delay{2.2},TargetPosition{"-27.648438,1.795654,150.466797,0.000102,-4.600037,179.58815,35.000011,65.552429,false,DoNotOverride,22"},duration{2}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Or at the very least... stop her from doing something she'd regret.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101109/194FC4D8"
        },
        [10111001] = {
          ContentFR = "Haa... haa... haa...",
          DialogueId = 10111001,
          Duration = 3,
          GUID = "194FD41A",
          SpeakNpcId = 200006,
          Subtitle = "Huff... Huff... Huff...",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD41A"
        },
        [10111002] = {
