          DialogueId = 10111905,
          GUID = "191BEBB2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...But are we just living for some kind of \"meaning\"?",
          VoiceName = "voice/$Locale$/story/1002/101119/191BEBB2"
        },
        [10112001] = {
