          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "It's all meaningless — their fleeting pity and memories will soon wither and decay with time, leaving you rotting in the ground, utterly forgotten.",
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1002/101121/195088E6"
        },
        [10112104] = {
          Camera = "-749.858276,899.738281,124.033691,0.00006,3.599072,-132.19986,80.0,607.756409,false,Manual,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Que crois-tu ? De quoi t’indignes-tu ? ... Je comprends. Tu veux me vaincre. Tu rêves qu’en me tuant, ta vie retrouve son cours... et ces jours paisibles que tu chérissais tant.",
          DialogueId = 10112104,
