        },
        [10112305] = {
          ContentFR = "Ne cède pas à ce monde froid et sans âme !",
          DialogueId = 10112305,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1950AA0A",
          SpeakNpcId = 100001,
