        },
        [10112403] = {
          Content = "站起来……",
          DialogueId = 10112403,
          ExStoryInfo = "Player",
          GUID = "1950BA1E",
          NextDialogue = 10112404,
          SpeakNpcId = 100001,
          Subtitle = "Stand up... Don't yield to this cold, unfeeling world!",
          VoiceName = "voice/$Locale$/story/1002/101124/1950BA1E"
        },
        [10112404] = {
          Content = "不要向这个冷冰冰的世界投降！",
          DialogueId = 10112404,
          ExStoryInfo = "Player",
          GUID = "1950BA48",
          NextDialogue = 10112405,
          SpeakNpcId = 100001,
          Subtitle = "Don't yield to this cold, unfeeling world!",
          VoiceName = "voice/$Locale$/story/1002/101124/1950BA48"
        },
        [10112405] = {
          Content = "我……",
          DialogueId = 10112405,
          GUID = "1950BA72",
          SpeakNpcId = 200006,
          Subtitle = "I...",
          VoiceName = "voice/$Locale$/story/1002/101124/1950BA72"
        },
        [10112501] = {
          ContentFR = "Es-tu folle ?! Que fais-tu ?! Si tu me tues, tu disparaîtras toi aussi !",
          DialogueId = 10112501,
          GUID = "1950CA5B",
          NextDialogue = 10112502,
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "Are you insane? What do you think you are doing!? Kill me, and you will be gone too!",
          VoiceName = "voice/$Locale$/story/1002/101125/1950CA5B"
        },
        [10112502] = {
          ContentFR = "Ce sont eux qui t’ont méprisée, qui t’ont blessée ! Et pourtant... c’est moi que tu veux anéantir ?!",
          DialogueId = 10112502,
          GUID = "1950CA5C",
          NextDialogue = 10112503,
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "It's them! They are the ones who insult and hurt you! And you choose to destroy me!?",
          VoiceName = "voice/$Locale$/story/1002/101125/1950CA5C"
        },
        [10112503] = {
          ContentFR = "Pourquoi refuserais-tu d’obéir à ce corps... de détruire, de réduire tout en cendres ?",
          DialogueId = 10112503,
          GUID = "1950CA86",
          NextDialogue = 10112504,
          SnapShot = "MONSTER",
          SpeakNpcId = 200052,
          Subtitle = "You should've followed the desire of this body to destroy and pulverize everything!",
          VoiceName = "voice/$Locale$/story/1002/101125/1950CA86"
        },
        [10112504] = {
          ContentFR = "Non... Ce n’est pas vrai. Car je me souviens...",
          DialogueId = 10112504,
          GUID = "1950CA87",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "No, this is not right. 'Cause I remember...",
          VoiceName = "voice/$Locale$/story/1002/101125/1950CA87"
        },
        [10112601] = {
          ContentFR = "Psyche, te souviens-tu de ton vœu le plus cher ?",
          DialogueId = 10112601,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1950DA9A",
          NextDialogue = 10112602,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0063_story_saiqi_last_word\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Psyche, do you remember what your deepest wish has always been?",
          VoiceName = "voice/$Locale$/story/1002/101126/1950DA9A"
        },
        [10112602] = {
          ContentFR = "Oui... je m’en souviens.",
          DialogueId = 10112602,
          Duration = 3,
          GUID = "1950DAEE",
          NextDialogue = 10112603,
          SpeakNpcId = 200006,
          Subtitle = "Yes, I remember now.",
          VoiceName = "voice/$Locale$/story/1002/101126/1950DAEE"
        },
        [10112603] = {
          ContentFR = "Quitter cet endroit... voyager vers un monde plus vaste.",
          DialogueId = 10112603,
          Duration = 3,
          GUID = "1950DB18",
          NextDialogue = 10112604,
          SpeakNpcId = 200006,
          Subtitle = "I've always wanted to leave this place and see the world.",
          VoiceName = "voice/$Locale$/story/1002/101126/1950DB18"
        },
        [10112604] = {
          ContentFR = "Trouver une terre chaude, où les fleurs s’épanouissent sans fin.",
          DialogueId = 10112604,
          Duration = 3,
          GUID = "1950DB42",
          NextDialogue = 10112605,
          SpeakNpcId = 200006,
          Subtitle = "To find a warm place where flowers always bloom.",
          VoiceName = "voice/$Locale$/story/1002/101126/1950DB42"
        },
        [10112605] = {
          ContentFR = "J’y arriverai. Oui... j’y arriverai.",
          DialogueId = 10112605,
          Duration = 3,
          GUID = "1950DB6C",
          SpeakNpcId = 200006,
          Subtitle = "I wish to make it there. I will make it there.",
          VoiceName = "voice/$Locale$/story/1002/101126/1950DB6C"
        },
        [10112701] = {
          ContentFR = "Psyche, je suis venu te ramener à la maison.",
          DialogueId = 10112701,
          Duration = 4,
          GUID = "1950EB02",
          SpeakNpcId = 200006,
          Subtitle = "Psyche, I'm here to take you home."
        },
