        [10113109] = {
          Camera = "166.950943,133.818985,133.208984,-1.5,-19.999264,-177.415726,30.0,246.856323,false,Manual,3.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Je n’avais jamais entendu dire qu’un Dégradé pouvait retrouver sa conscience. Mais Psyche... elle l’a fait, un instant. Avec ce qui lui restait de lucidité, elle a brisé de ses mains cette carcasse de Souillé, pour dire à tous qu’elle ne se rendrait pas.",
          DialogueId = 10113109,
          FacialId = {
            [1] = "200021:Doubt01"
          },
          FinalCamera = "160.164246,152.427582,130.655273,-1.499999,-20.199272,-173.215866,30.0,246.856323,false,Manual,3.0",
          GUID = "19512DA0",
          NextDialogue = 10113110,
          Scripts = [[
PARA{
CameraMoveTo{_delay{2.3},TargetPosition{"-106.279404,263.777679,42.93457,0.000017,12.400229,-51.421665,30.0,391.693146,false,Manual,4.0"},duration{0}},
CameraMoveTo{_delay{2.4},TargetPosition{"-115.301208,254.134064,42.93457,0.000008,12.800286,-45.021217,30.0,391.693146,false,Manual,4.0"},blend{"easeOutQuad"},duration{2.5}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "I'd never heard of any Deteriorator regaining their self-consciousness, but Psyche briefly did it. With the last bit of sobriety, she shattered that filthy beast with her own hands, telling everyone that she would not surrender.",
          TalkActionId = {
            [1] = "200021:Think_Start"
          },
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101131/19512DA0"
        },
        [10113110] = {
          Camera = "-246.400757,844.10083,-61.849609,-3.000001,7.500012,-65.621231,25.0,178.229309,false,DoNotOverride,3.0",
          ContentFR = "C’est toi... qui l’as éveillée ? La magie que tu as utilisée... c’était bien la <H>Résonance</> ?",
          DialogueId = 10113110,
          GUID = "19512DA1",
          NextDialogue = 10113111,
          SpeakNpcId = 200021,
          Subtitle = "Did you...make that happen? The magic you were using... It was Resonance, wasn't it?",
          TalkActionId = {
            [1] = "200021:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101131/19512DA1"
        },
        [10113111] = {
