          GUID = "19512DA3",
          LookAt = {
            [1] = "200021:n(200021)",
            [2] = "100001:n(200021)"
          },
          NextDialogue = 10113113,
          SpeakNpcId = 200021,
          Subtitle = "Relax, I'm not going to press you about your past. But remember what I'm gonna say—",
