          NextDialogue = 10113117,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"200021:p(Psky)\"}}",
          SpeakNpcId = 200021,
          Subtitle = "The wind here is so strong, I can't hear a thing. Even if I hear some noise, it's just the sparrows chirping.",
          VoiceName = "voice/$Locale$/story/1002/101131/19512E1C"
        },
        [10113117] = {
          Camera = "63.788624,80.274666,117.046875,0.000101,-0.000061,28.195601,35.0,46.83934,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "... Ce genre de choses, j’en ai déjà vu bien trop souvent. Mais je me fixe une règle : « une seule nuit pour les larmes. »",
          DialogueId = 10113117,
          FacialId = {
            [1] = "200021:Ahaha01"
