          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Le temps… la vie… tout est ainsi.",
          DialogueId = 10113209,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-12.246094,29.078125,-106.960693,0.000416,30.792828,-166.372574,35.0,572.451843,false,Manual,22.0",
          GUID = "19513E5A",
          NextDialogue = 10113210,
          Scripts = "PlayAnimation{_delay{1.5},ActorId{100001},AnimationId{\"Talk02_End\"},Duration{1}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Time, and life... it's all like this.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101132/19513E5A"
        },
        [10113210] = {
          Camera = "2709.152344,918.375,-499.61203,-0.0,14.99999,-161.997604,25.0,100000.0,false,Manual,22.0",
          ContentFR = "Naître pour disparaître, se rencontrer pour se séparer. La seule chose éternelle dans ce monde, c’est l’oubli.",
          DialogueId = 10113210,
          ExStoryInfo = "EXPlayer",
          GUID = "19513E84",
          LookAt = {
            [1] = "100012:n(100012)",
            [2] = "100001:p(101132Point6)"
          },
          NextDialogue = 10113211,
          Scripts = [[
SEQ{
TurnTo{_delay{2.5},TurnToDescription{"100012:p(-180)"}},
MoveTo{_delay{2},ActorId{100012},MoveSpeed{30},TargetPoint{"101132Point8"}}
}]],
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "To be born is to be destroyed; to meet is to part ways. The only thing that ever lasts in this world is \"oblivion.\"",
          VoiceName = "voice/$Locale$/story/1002/101132/19513E84"
        },
        [10113211] = {
          Camera = "-591.296875,-251.023438,103.546082,0.00011,-16.800714,40.389046,35.000008,501.351562,false,Manual,22.0",
          ContentFR = "Où vas-tu... ?",
          DialogueId = 10113211,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Unacceptable01"
          },
          GUID = "19513EAE",
          NextDialogue = 10113212,
          Scripts = [[
PARA{
MoveTo{_delay{0.5},ActorId{100001},MoveSpeed{60},TargetPoint{"101132Point2"}},
MoveTo{ActorId{100012},MoveSpeed{120},TargetPoint{"101132Point7"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Where are you going...?",
          VoiceName = "voice/$Locale$/story/1002/101132/19513EAE"
        },
        [10113212] = {
          Camera = "-591.296875,-251.023438,103.546082,0.00011,-16.800714,40.389046,35.000008,501.351562,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Comme toi, je pars pour mon propre voyage.",
          DialogueId = 10113212,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-1168.667969,-987.226562,848.928101,0.000121,-38.400719,51.188854,35.000011,501.351562,false,Manual,22.0",
          GUID = "19513ED8",
          NextDialogue = 10113213,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Like you, I'm starting my own journey.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101132/19513ED8"
        },
        [10113213] = {
          Camera = "218.238281,11.238281,-190.407471,0.000003,21.597883,-176.59758,20.000008,501.349915,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Attends ! Qui... qui es-tu vraiment ?!",
          DialogueId = 10113213,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Shock01"
          },
          FinalCamera = "167.128906,8.203125,-170.148376,0.000003,21.597883,-176.59758,20.000008,501.349915,false,Manual,22.0",
          GUID = "19513F02",
          NextDialogue = 10113214,
          Scripts = [[
PARA{
SetLocation{ActorId{100012},TargetPoint{"101132Point8"},Visibility{"Show"}},
MoveTo{ActorId{100001},MoveSpeed{50},TargetPoint{"101132Point5"}}
