          SpeakNpcId = 100001,
          Subtitle = "Wait! Who... who are you?!",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101132/19513F02"
        },
        [10113214] = {
          Camera = "-320.191406,-84.808594,164.884644,0.000057,-32.81023,166.785141,20.000008,501.349915,false,Manual,22.0",
          ContentFR = "Mon nom est...",
          DialogueId = 10113214,
          ExStoryInfo = "EXPlayer",
          GUID = "19513F2C",
          NextDialogue = 10113215,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "My name is...",
          TurnTo = {
            [1] = "100012:p(150)"
          },
          VoiceName = "voice/$Locale$/story/1002/101132/19513F2C"
        },
        [10113215] = {
          Camera = "-320.191406,-84.808594,164.884644,0.000057,-32.81023,166.785141,20.000008,501.349915,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Peut-être que nos chemins se croiseront à nouveau un jour.",
          DialogueId = 10113215,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-349.851562,-138.621094,164.884644,0.000032,-33.21019,133.384689,20.000008,501.349915,false,Manual,22.0",
          GUID = "19513F56",
          Scripts = [[
PARA{
CameraMoveTo{_delay{2.5},TargetPosition{"-37.894531,54.429688,-37.144287,0.000067,13.593162,-176.994934,12.0,350.231415,false,Manual,3.0"},duration{0}},
CameraMoveTo{_delay{2.6},TargetPosition{"-30.320312,11.925781,-39.521667,0.000067,12.993198,172.805191,12.0,350.231415,false,Manual,3.0"},blend{easeOutQuad},duration{3}}
}]],
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "Our paths may cross again one day.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101132/19513F56"
        },
        [10113301] = {
          ContentFR = "Dans ce rêve qui s’effondre encore une fois, cette voix s’est fait entendre à travers le vent.",
          DialogueId = 10113301,
          Duration = 3.5,
          GUID = "19514D72",
          NextDialogue = 10113302,
          Subtitle = "Once again, in the collapsing dream, that voice whispered through the wind.",
          VoiceName = "voice/$Locale$/story/1002/101133/19514D72"
        },
        [10113302] = {
          ContentFR = "Cette fois, je peux enfin l’entendre clairement.",
          DialogueId = 10113302,
          Duration = 3.5,
          GUID = "19514D9C",
          NextDialogue = 10113303,
          Subtitle = "Only this time, I finally made it out.",
          VoiceName = "voice/$Locale$/story/1002/101133/19514D9C"
        },
        [10113303] = {
          ContentFR = "Comme les racines d’un arbre absorbant chaque goutte d’eau, je m’efforce de graver ce nom dans ma mémoire.",
          DialogueId = 10113303,
          Duration = 4,
          GUID = "19514DC6",
          NextDialogue = 10113304,
          Subtitle = "Like tree roots eagerly absorbing every drop of water, I endeavoured to engrave that name in my mind.",
          VoiceName = "voice/$Locale$/story/1002/101133/19514DC6"
        },
        [10113304] = {
          ContentFR = "... Ce nom...",
          DialogueId = 10113304,
          Duration = 3,
          GUID = "19514DF0",
          Subtitle = "...That name is...",
          VoiceName = "voice/$Locale$/story/1002/101133/19514DF0"
        },
        [10113401] = {
          Camera = "-1818.244629,451.75,65.15918,0.0,3.799989,1.999787,35.0,269.181396,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "J’ai connu la douleur... j’ai goûté à la haine. Elles m’ont épuisée... accablée...",
          DialogueId = 10113401,
          FacialId = {
            [1] = "2000591:Happy02"
          },
          FinalCamera = "-1818.244629,451.75,77.947998,0.0,6.0,1.999786,35.0,921.225525,false,Manual,1.2",
          GUID = "19515DDA",
          NextDialogue = 10113402,
          Scripts = [[
PARA{
CameraMoveTo{_delay{3},TargetPosition{"-986.794189,356.464844,129.88501,0.000031,5.799336,133.697769,30.000002,425.998016,false,Manual,22.0"},duration{0}},
PlayAnimation{_delay{3.1},ActorId{2000591},AnimationId{"Explain02_Start"},Duration{1}}
}]],
          SpeakNpcId = 2000591,
          Subtitle = "Pain and hatred have been my acquaintances. They've wearied and agrieved me—",
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101134/19515DDA"
        },
        [10113402] = {
          Camera = "-1751.68335,1248.289062,55.207764,-0.0,4.000004,-50.000027,15.0,425.998016,false,DoNotOverride,1.2",
          ContentFR = "<H>Mais je me réjouis encore... d’avoir vu le jour dans ce monde.</>",
          DialogueId = 10113402,
          FinalCamera = "-1650.423584,1127.605469,35.868652,-0.0,4.000004,-50.000027,15.0,425.998016,false,DoNotOverride,1.2",
          GUID = "19515E04",
          NextDialogue = 10113403,
          SpeakNpcId = 2000591,
          Subtitle = "Yet, I find joy in having existed in this world.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101134/19515E04"
        },
        [10113403] = {
          Camera = "-1283.367798,582.753906,176.219971,0.000078,-2.599427,-26.997437,35.0,144.372665,false,Manual,4.831013",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "C’est mon choix.",
          DialogueId = 10113403,
          FinalCamera = "-1286.140259,577.761719,176.219971,0.000078,-2.599427,-28.997461,35.0,896.028748,false,Manual,4.092557",
          GUID = "19515E2E",
          SpeakNpcId = 2000591,
          Subtitle = "This is my choice.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101134/19515E2E"
        },
        [10113501] = {
          Camera = "196.933594,49.747803,104.415039,0.000189,3.999731,-144.598633,35.0,149.900024,false,Manual,4.0194.328125,53.443115,103.287109,0.000189,3.999731,-144.598587,35.0,150.0,false,Manual,4.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Des Souillés ?!",
          DialogueId = 10113501,
          ExStoryInfo = "Player",
          FinalCamera = "175.269531,39.89624,107.285645,0.000189,3.999731,-144.598587,35.0,125.0,false,Manual,4.0",
          GUID = "19516EEA",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          LookAt = {
            [1] = "200021:n(100001)",
            [2] = "100001:n(100001)"
          },
          NextDialogue = 10113502,
          SpeakNpcId = 100001,
          Subtitle = "Filthoids?!",
          TalkActionId = {
            [1] = "100001:Shock_Start",
            [2] = "2000331:Special_Start1"
          },
          ToFinalCameraBlendTime = 0.4,
          VoiceName = "voice/$Locale$/story/1002/101135/19516EEA"
        },
        [10113502] = {
          Camera = "238.0625,-87.837646,103.295898,0.000204,4.399468,158.005524,35.0,185.005707,false,Manual,4.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Considère cette machine bruyante comme la personne que tu veux protéger, et ces Souillés comme les ennemis qui veulent l’attaquer.",
          DialogueId = 10113502,
          FinalCamera = "240.769531,-81.229736,103.295898,0.000213,4.399468,158.005692,35.0,292.735229,false,Manual,5.0",
          GUID = "19516F14",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10113503,
          Scripts = "TurnTo{_delay{0.5},TurnToDescription{\"100001:n(200021)\"}}",
          SpeakNpcId = 200021,
          Subtitle = "Just think of this noisy piece of scrap as someone you want to protect, and these Filthoids are the baddies after her.",
          TalkActionId = {
            [1] = "100001:Shock_End"
          },
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101135/19516F14"
        },
        [10113503] = {
          Camera = "135.984375,-44.101318,130.969727,0.000225,3.999998,147.005432,35.0,200.0,false,Manual,5.0",
          ContentFR = "Protège-la à tout prix, ne laisse pas les Souillés la détruire.",
          DialogueId = 10113503,
          GUID = "19516F3E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          LookAt = {
            [1] = "100001:n(200021)"
          },
          NextDialogue = 10113504,
          Scripts = "PlayAnimation{_delay{2.5},ActorId{200021},AnimationId{\"Talk03_Start\"},Duration{1}}",
          SpeakNpcId = 200021,
          Subtitle = "Try to keep it safe — make sure it doesn't get banged up from Filthoid attacks.",
          TalkActionId = {
            [1] = "200021:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101135/19516F3E"
        },
        [10113504] = {
          Camera = "-68.972656,221.981689,176.847656,0.000192,-13.999995,-67.401672,40.0,328.456238,false,Manual,5.0",
          ContentFR = "Attends que je ne suis pas {性别:prêt|prête}—",
          DialogueId = 10113504,
          ExStoryInfo = "Player",
          GUID = "19516F68",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10113505,
          SpeakNpcId = 100001,
          Subtitle = "But I'm not ready—",
          TalkActionId = {
            [1] = "100001:Angry01_Start",
            [2] = "200021:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101135/19516F68"
        },
        [10113505] = {
          Camera = "875.300781,17.000244,70.82959,0.0,0.0,-179.999985,25.0,674.169678,false,Manual,2.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Nous, Chasseurs de Phoxène, on fait face à plein d’imprévus. Pas de panique, je te couvre !",
          DialogueId = 10113505,
          FinalCamera = "1020.636719,17.000244,70.82959,0.0,0.0,-179.999985,25.0,674.169678,false,Manual,2.0",
          GUID = "19516F92",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          Scripts = "PlayAnimation{_delay{1.5},ActorId{200021},AnimationId{\"Confident_Start\"},Duration{1}}",
          SpeakNpcId = 200021,
          Subtitle = "Well, we Phoxhunters are always dealing with unexpected situations. Don't panic, I've got your back!",
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "200021:p(45)"
          },
          VoiceName = "voice/$Locale$/story/1002/101135/19516F92"
        },
        [10113701] = {
          ContentFR = "Eh... il est cassé.",
          DialogueId = 10113701,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19518F12",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10113702,
          SpeakNpcId = 100001,
          Subtitle = "Er, it broke.",
          VoiceName = "voice/$Locale$/story/1002/101137/19518F12"
        },
        [10113702] = {
          ContentFR = "C’est fait avec de la récup’ ! Qu’il fonctionne déjà, c’est un miracle.",
          DialogueId = 10113702,
          Duration = 2.5,
          GUID = "19518F3C",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200021,
          Subtitle = "Well, it is made from scrap, after all. I was surprised that it would work!",
          VoiceName = "voice/$Locale$/story/1002/101137/19518F3C"
        },
        [10113801] = {
          Content = "任务完成",
          DialogueId = 10113801,
          Duration = 3.5,
          GUID = "19519F7A",
          Subtitle = "Quest Completed",
          VoiceName = "voice/$Locale$/story/1002/101138/19519F7A"
        },
        [10113901] = {
          Content = "本次技术性测试剧情流程已结束。",
          DialogueId = 10113901,
          Duration = 5,
          GUID = "1951AFE2",
          VoiceName = "voice/$Locale$/story/1002/101139/1951AFE2"
        },
        [10114001] = {
          ContentFR = "Déjà de retour ? Vous n’étiez pas censés suivre Henrik ?",
          DialogueId = 10114001,
          GUID = "1951C04A",
          SpeakNpcId = 200021,
          Subtitle = "Back already? Shouldn't you be following Henrik?",
          VoiceName = "voice/$Locale$/story/1002/101140/1951C04A"
        },
        [10114201] = {
          ContentFR = "Il vaut mieux aller dormir tôt... sinon vous serez fatigué demain.",
          DialogueId = 10114201,
          GUID = "1951E11A",
          SpeakNpcId = 200020,
          Subtitle = "Rest early when you're done.",
          VoiceName = "voice/$Locale$/story/1002/101142/1951E11A"
        },
        [10114301] = {
          ContentFR = "Si Monsieur Henrik est d’accord, tu pourrais revenir passer un peu de temps avec moi ?",
          DialogueId = 10114301,
          GUID = "1951F182",
          SpeakNpcId = 200006,
          Subtitle = "If it's okay with Mr Henrik, could you come visit me again?",
          VoiceName = "voice/$Locale$/story/1002/101143/1951F182"
        },
        [10114401] = {
          ContentFR = "Reste tranquille et ne te mêle pas de ce qui ne te regarde pas.",
          DialogueId = 10114401,
          GUID = "195201EA",
          SpeakNpcId = 200005,
          Subtitle = "Keep your nose out of things that don't concern you.",
          VoiceName = "voice/$Locale$/story/1002/101144/195201EA"
        },
        [10114501] = {
          Camera = "-36.346924,180.007812,144.75769,0.000186,-6.600435,-88.992912,25.0,418.354095,false,Manual,3.0",
