          DialogueId = 10115403,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1952A64E",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "...Hang in there, Psyche. I'm coming.",
          VoiceName = "voice/$Locale$/story/1002/101154/1952A64E"
        },
        [10115501] = {
