          Duration = 4,
          GUID = "1952B662",
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
          Subtitle = "Meanwhile, in Dismania, the Imperial Capital...",
          VoiceName = "voice/$Locale$/story/1002/101155/1952B662"
        },
        [10115601] = {
          Content = "突然，恩里克出现了",
          DialogueId = 10115601,
          GUID = "1952C6CA",
          VoiceName = "voice/$Locale$/story/1002/101156/1952C6CA"
        },
        [10115701] = {
          Content = "一个熟悉的少女叫住了一行人",
          DialogueId = 10115701,
          GUID = "1952D732",
          VoiceName = "voice/$Locale$/story/1002/101157/1952D732"
        },
        [10115801] = {
          ContentFR = "<I>J’ai déjà mis au courant l’Étranger et Snow de tout ce qui s’est passé aujourd’hui.</>",
          DialogueId = 10115801,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1952E79A",
          IsBlack = 1,
          NextDialogue = 10115802,
          SpeakNpcId = 100001,
          Subtitle = "(I've filled in Outsider and Snow on everything that happened today.)",
          VoiceName = "voice/$Locale$/story/1002/101158/1952E79A"
        },
        [10115802] = {
          ContentFR = "<I>À présent, il ne reste plus qu’à attendre au point de rendez-vous... avec patience.</>",
          DialogueId = 10115802,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1952E7C4",
          IsBlack = 1,
          SpeakNpcId = 100001,
          Subtitle = "(Now, all that's left to do is get to the meeting spot... and wait.)",
          VoiceName = "voice/$Locale$/story/1002/101158/1952E7C4"
        },
        [10116701] = {
