        [10116801] = {
          Content = "我们开始狩猎吧！",
          DialogueId = 10116801,
          GUID = "19538BAA",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1002/101168/19538BAA"
        },
        [10116901] = {
          ContentFR = "Ces choses par terre... ce doivent être les pièges de l’Étranger.",
          DialogueId = 10116901,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19539C12",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10116902,
          SpeakNpcId = 100001,
          Subtitle = "These things on the ground... must be Outsider's traps.",
          VoiceName = "voice/$Locale$/story/1002/101169/19539C12"
        },
        [10116902] = {
          ContentFR = "... Pas mal du tout. Je ne pensais pas que l’Étranger avait ce genre de talent.",
          DialogueId = 10116902,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19539C3C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "...This is really something. I didn't know Outsider had such a knack for this.",
          VoiceName = "voice/$Locale$/story/1002/101169/19539C3C"
        },
        [10117001] = {
          ContentFR = "Qu’est-ce qui se passe ici ?",
          DialogueId = 10117001,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1953AC7A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10117002,
          SpeakNpcId = 100001,
          Subtitle = "What's going on here?",
          VoiceName = "voice/$Locale$/story/1002/101170/1953AC7A"
        },
        [10117002] = {
          ContentFR = "Ah ah... Pas de chance, j’ai fait un peu de bruit en bidouillant cette chose, et voilà que ces petits monstres sont venus me chercher...",
          DialogueId = 10117002,
          Duration = 6,
          GUID = "1953ACA4",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10117003,
          SpeakNpcId = 200021,
          Subtitle = "Ah, well, I made a bit of noise while tweaking that thing and these little critters just came at me...",
          VoiceName = "voice/$Locale$/story/1002/101170/1953ACA4"
        },
        [10117003] = {
          ContentFR = "Allez, mon {性别:ami|amie}, viens me filer un coup de main !",
          DialogueId = 10117003,
          Duration = 4,
          GUID = "1953ACCE",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10117004,
          SpeakNpcId = 200021,
          Subtitle = "Come on, my friend, help me out here!",
          VoiceName = "voice/$Locale$/story/1002/101170/1953ACCE"
        },
        [10117004] = {
          ContentFR = "C’est bien fait pour toi ! ... Bon, allez.",
          DialogueId = 10117004,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "1953ACF8",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "Serves you right! ...Fine.",
          VoiceName = "voice/$Locale$/story/1002/101170/1953ACF8"
        },
        [10117101] = {
          ContentFR = "Commençons par chercher vers l’ouest !",
          DialogueId = 10117101,
          Duration = 3,
          GUID = "1953BCE2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10117102,
          SpeakNpcId = 200011,
          Subtitle = "Let's start by searching to the west.",
          VoiceName = "voice/$Locale$/story/1002/101171/1953BCE2"
        },
        [10117102] = {
          ContentFR = "Le voleur a les cheveux noirs et portait... un haut bleu ? Je crois. ",
