        [10117302] = {
          Camera = "-192.958298,199.304382,104.51123,0.000078,1.000431,-68.603432,43.300995,474.195221,false,Manual,2.6",
          ContentFR = "Oh ! Mais c’est notre petite Princesse des Déchets ! Aujourd’hui, tu as amené deux acolytes pour t’aider ?",
