        [10120401] = {
          ContentFR = "Hé, là-bas c’est le Lac du Deuil ! On n’avait pas dit qu’on allait en ville ?",
          DialogueId = 10120401,
          GUID = "1955DA4A",
          NextDialogue = 10120402,
          SpeakNpcId = 200002,
          Subtitle = "Hey, that's Lamenting Lake. The city's this way!",
          VoiceName = "voice/$Locale$/story/1002/101204/1955DA4A"
        },
        [10120402] = {
          ContentFR = "Errer {性别:tout seul|toute seule} comme ça, c’est dangereux ! Reviens vite, Snow t’attend ici !",
          DialogueId = 10120402,
          GUID = "1955DA74",
          SpeakNpcId = 200002,
          Subtitle = "Wandering off alone is dangerous. Come this way, I'll wait for you here.",
          VoiceName = "voice/$Locale$/story/1002/101204/1955DA74"
        },
        [10120501] = {
          ContentFR = "Hé, où tu vas ? La ville, c’est de ce côté !",
          DialogueId = 10120501,
          GUID = "1955EAB2",
          NextDialogue = 10120502,
          SpeakNpcId = 200002,
          Subtitle = "Where are you going? The city's this way!",
          VoiceName = "voice/$Locale$/story/1002/101205/1955EAB2"
        },
        [10120502] = {
          ContentFR = "Là-bas, c’est infesté de Souillés, ils vont t’avaler tout cru ! Viens vite par ici !",
          DialogueId = 10120502,
          GUID = "1955EADC",
          SpeakNpcId = 200002,
          Subtitle = "It's crawling with Filthoids over there. Come back here if you don't want to be their snacks!",
          VoiceName = "voice/$Locale$/story/1002/101205/1955EADC"
        },
        [10120601] = {
          ContentFR = "<I>Alors c’est ça, une \"cité\"... Je n’en avais jamais vu avant.</>",
          DialogueId = 10120601,
          DisableMouth = 1,
          GUID = "1955FB1A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10120602,
          SpeakNpcId = 100001,
          Subtitle = "(So... this is a \"city\"? Never seen or been to one before...)",
          VoiceName = "voice/$Locale$/story/1002/101206/1955FB1A"
        },
        [10120602] = {
          ContentFR = "<I>Mais où aller maintenant ?... Je ferais mieux de retrouver Snow et cette Madame Camilla.</>",
          DialogueId = 10120602,
          DisableMouth = 1,
          GUID = "1955FB44",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "(But I have no idea where to go... Guess I should find Snow and the lady called Camilla first.)",
          VoiceName = "voice/$Locale$/story/1002/101206/1955FB44"
        },
        [10120701] = {
          Content = "呜哇哇，过不去了！怎么回事，连下水道也在和我们作对……",
          DialogueId = 10120701,
          GUID = "19560B82",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10120702,
          SpeakNpcId = 200002,
          Subtitle = "Whoa! Now we're stuck!? Even the sewer's giving us trouble...",
          VoiceName = "voice/$Locale$/story/1002/101207/19560B82"
        },
        [10120702] = {
          Content = "让“缄默侦探”看看——这里有个水阀！他一定对水阀做了手脚！",
          DialogueId = 10120702,
          GUID = "19560BAC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10120703,
          SpeakNpcId = 200011,
          Subtitle = "Let this Reticent Detective take a look... Huh, there's a water valve here! He must've done something to it!",
          VoiceName = "voice/$Locale$/story/1002/101207/19560BAC"
        },
        [10120703] = {
          Content = "也就是说，这里的水位是<H>水阀</>控制的……",
          DialogueId = 10120703,
          GUID = "19560BD6",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "So the water level here is controlled by these valves...",
          VoiceName = "voice/$Locale$/story/1002/101207/19560BD6"
        },
        [10120801] = {
          Content = "前面还有个水阀！",
          DialogueId = 10120801,
          GUID = "19561BEA",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          Subtitle = "I see another valve up ahead!",
          VoiceName = "voice/$Locale$/story/1002/101208/19561BEA"
        },
        [10120901] = {
          Content = "那个坏蛋刚刚就是钻到这个洞里去了，我们也跟上！",
          DialogueId = 10120901,
          GUID = "19562C52",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10120902,
          SpeakNpcId = 200002,
          Subtitle = "That sneaky thief just slipped through this hole — come on, we're not letting him get away!",
          VoiceName = "voice/$Locale$/story/1002/101209/19562C52"
        },
        [10120902] = {
          ContentFR = "Oh, ça me revient ! Dans le <I>Guide d’entretien des égouts</> trouvé dans la poubelle n° 8, il est écrit que les égouts attirent parfois des Souillés qui aiment la chaleur et l’humidité.",
          DialogueId = 10120902,
          GUID = "19562C7C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10118603,
          SpeakNpcId = 200011,
          Subtitle = "Wait... \"Sewers tend to attract Filthoids that love warm, damp places\" — I read about this in the Sewer Maintenance Manual from Bin No. 8.",
          VoiceName = "voice/$Locale$/story/1002/101209/19562C7C"
        },
        [10121001] = {
          Camera = "218.365723,-14.279999,113.666016,0.000055,-2.933532,120.000008,25.0,100000.0,false,Manual,2.8",
          CameraBlendCurve = "easeInQuad",
          Content = "他……怎么突然停下了？",
          DialogueId = 10121001,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          FinalCamera = "222.279785,-12.18045,113.666016,0.000055,-2.933566,118.199425,25.0,100000.0,false,Manual,2.8",
