CameraMoveTo{_delay{1.6},TargetPosition{"63.706055,-264.857666,137.854614,0.000088,-8.200714,112.800194,30.0,264.0513,false,Manual,3.0"},duration{2.5}},
TurnTo{_delay{0.5},TurnToDescription{"100001:p(-120)"}},
MoveTo{ActorId{200002},TargetPoint{"200059Bai1"},MoveSpeed{220},Visibility{"Show"}},
