          Subtitle = "It's okay. I'll teach you next time — it's so much fun! I could sit and fish all day.",
          TalkActionId = {
            [1] = "100001:Explain02_Start",
            [2] = "200006:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101248/1958AC7E"
        },
        [10124804] = {
          Camera = "717.636719,237.269531,92.487305,0.000039,0.000007,-165.6008,40.0,199.075928,false,Manual,4.533308",
          ContentFR = "D’accord... alors, c’est promis.",
          DialogueId = 10124804,
          FinalCamera = "718.5625,233.65625,92.487305,0.000039,0.000007,-165.6008,40.0,583.132141,false,Manual,3.808652",
          GUID = "1958ACA8",
          SpeakNpcId = 200006,
          Subtitle = "Sounds fun... I'd love to try.",
          TalkActionId = {
            [1] = "200006:AgreeHead"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101248/1958ACA8"
        },
        [10124901] = {
          ContentFR = "Quand j’étais petite, je croyais que si je courais assez loin, je pourrais quitter Givrelac.",
          DialogueId = 10124901,
          GUID = "1958BC92",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10124902,
          SpeakNpcId = 200006,
          Subtitle = "When I was little, I thought if I just kept running, I'd leave Icelake behind.",
          VoiceName = "voice/$Locale$/story/1002/101249/1958BC92"
        },
        [10124902] = {
          ContentFR = "Mais plus je courais, plus je me retrouvais devant le même lac... comme derrière une montagne, il y a toujours une autre montagne.",
          DialogueId = 10124902,
          GUID = "1958BCBC",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "But no matter how far I ran, the lake never ended, and the mountains always led to more mountains.",
          VoiceName = "voice/$Locale$/story/1002/101249/1958BCBC"
        },
        [10125001] = {
          Camera = "187.345703,453.548828,53.723633,0.0,0.0,-113.610939,25.0,3663.129883,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Cette fleur me dit quelque chose...",
          DialogueId = 10125001,
          FinalCamera = "183.400391,455.277344,53.723633,0.0,0.0,-113.610863,25.0,425.805145,false,Manual,2.325369",
          GUID = "1958CCFA",
          LookAt = {
            [1] = "100001:p(P101250Flower)",
            [2] = "200006:p(P101250Flower)"
          },
          NextDialogue = 10125002,
          SpeakNpcId = 100001,
          Subtitle = "This flower looks familiar.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101250/1958CCFA"
        },
        [10125002] = {
          Camera = "-5.208984,20.542969,81.288086,0.000032,-7.199948,52.000679,30.0,79.292412,false,Manual,4.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Vraiment ? Laisse-moi la toucher... Oui, c’est un Lys givre-étoilé. Les pétales sont plus petits, le parfum plus léger... mais c’est bien la même espèce que celle dans ma chambre.",
          DialogueId = 10125002,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "3.671875,19.353516,80.720703,0.000016,-7.199975,54.899391,30.0,182.280197,false,Manual,4.0",
          GUID = "1958CD24",
          NextDialogue = 10125003,
          Scripts = [[
PARA{
MoveTo{ActorId{200006},MoveSpeed{120},TargetPoint{"P101250Saiqi"}}
}]],
          SpeakNpcId = 200006,
          Subtitle = "Really? Let me feel it... Ah, it's a Starfrost. Though the petals are smaller and the scent fainter, it's the same kind as the pot of flowers in my room.",
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101250/1958CD24"
        },
        [10125003] = {
          Camera = "153.019531,416.476562,54.358398,0.000051,4.999835,-100.502174,30.0,326.873077,false,Manual,22",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Tu veux en cueillir une, comme souvenir ?",
          DialogueId = 10125003,
          FinalCamera = "160.480469,456.728516,50.777344,0.000051,4.999835,-100.502174,30.0,326.873077,false,Manual,22",
          GUID = "1958CD4E",
          NextDialogue = 10125004,
          SpeakNpcId = 100001,
          Subtitle = "Would you like to pick it as a keepsake?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101250/1958CD4E"
        },
        [10125004] = {
          Camera = "1505.365234,-1424.457031,158.464844,0.000052,7.500012,126.697205,20.0,139.363022,false,Manual,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Non... pas besoin. Savoir qu’elle est ici me suffit.",
          DialogueId = 10125004,
          FacialId = {
            [1] = "200006:Satisfy01"
          },
          FinalCamera = "1505.365234,-1424.457031,241.649414,0.000052,7.500012,126.697205,20.0,139.363022,false,Manual,4.0",
          GUID = "1958CD78",
          SpeakNpcId = 200006,
          Subtitle = "No... just knowing it's here is enough for me.",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101250/1958CD78"
        },
        [10125101] = {
          Camera = "60.023438,191.382812,59.332031,-0.001495,9.036367,-164.419235,50.0,144.456711,false,Manual,5.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Comment ça ?",
          DialogueId = 10125101,
          FacialId = {
            [1] = "100001:Unacceptable01"
          },
          FinalCamera = "60.53125,189.535156,59.238281,-0.001495,9.036367,-164.41864,50.0,144.456711,false,Manual,5.0",
          GUID = "1958DD62",
          NextDialogue = 10125102,
          SpeakNpcId = 100001,
          Subtitle = "What do you mean?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101251/1958DD62"
        },
        [10125102] = {
          Camera = "-157.761719,270.34375,84.228516,0.000002,-1.300195,-48.197968,50.0,243.327423,false,Manual,8.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Désolée. Disons que... c’est mon petit secret égoïste.",
          DialogueId = 10125102,
          FacialId = {
            [1] = "200027:Ahaha02"
          },
          FinalCamera = "-157.390625,270.679688,84.509766,0.000002,-1.300195,-47.997818,50.0,243.327423,false,Manual,8.0",
          GUID = "1958DD8C",
          NextDialogue = 10125103,
          SpeakNpcId = 200027,
          Subtitle = "Sorry, I can't tell you. Let's just say... it's my little secret to keep.",
          TalkActionId = {
            [1] = "100001:Explain02_End",
            [2] = "200027:DisagreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101251/1958DD8C"
        },
        [10125103] = {
          Camera = "-383.175781,979.316406,15.928711,0.000024,1.699392,-58.39698,30.0,937.541016,false,Manual,1.2",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Allez, {nickname}, prends encore une photo de moi. Mais veille à ce que Givrelac soit dans le cadre.",
          DialogueId = 10125103,
          FacialId = {
            [1] = "200027:Smile01"
          },
          FinalCamera = "-383.175781,979.316406,35.485352,0.000037,3.600001,-55.999863,30.000002,923.619934,false,Manual,1.2",
          GUID = "1958DDB6",
          LookAt = {
            [1] = "200027:n(100001)"
          },
          NextDialogue = 10125104,
          SpeakNpcId = 200027,
          Subtitle = "Could you take another photo of me, ? And make sure Icelake's in the frame?",
          ToFinalCameraBlendTime = 7.5,
          TurnTo = {
            [1] = "200027:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1002/101251/1958DDB6"
        },
        [10125104] = {
          Camera = "-2408.292969,-1634.121094,1839.698242,0.000074,24.496656,-29.79982,15.0,937.541016,false,DoNotOverride,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Je n’aime pas cette ville. Je déteste l’odeur métallique qui flotte dans l’air, ses murailles hautes comme des montagnes, les lourdes bottes des gardes... et les sanglots qui résonnent à chaque coin de rue.",
          DialogueId = 10125104,
          FacialId = {
            [1] = "200027:None"
          },
          FinalCamera = "-3675.546875,-915.507812,781.563477,0.000088,25.896593,-29.799929,15.0,937.541016,false,DoNotOverride,1.2",
          GUID = "1958DDE0",
          LookAt = {
            [1] = "200027:n(200027)"
          },
          NextDialogue = 10125105,
          SpeakNpcId = 200027,
          Subtitle = "I don't like this city. I hate the ever-present smell of blood in the air, the towering walls, the guards' heavy boots... and the endless whimpers that fill every alleyway.",
          ToFinalCameraBlendTime = 14,
          TurnTo = {
            [1] = "200027:p(-120)"
          },
          VoiceName = "voice/$Locale$/story/1002/101251/1958DDE0"
        },
        [10125105] = {
          Camera = "93.558594,213.8125,52.767578,0.00006,13.824869,-124.447884,50.0,134.6604,false,Manual,5.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "... Mais c’est aussi l’endroit où j’ai grandi. <H>Mon seul et unique foyer</>.",
          DialogueId = 10125105,
          FinalCamera = "89.410156,207.765625,54.574219,0.000061,13.824869,-124.447868,50.0,126.754227,false,Manual,5.0",
          GUID = "1958DE0A",
          NextDialogue = 10125106,
          SpeakNpcId = 200027,
          Subtitle = "...But it's still where I grew up. My one and only home.",
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1002/101251/1958DE0A"
        },
        [10125106] = {
          Camera = "-124.773438,102.035156,16.120117,0.000002,25.225302,-10.450226,20.000008,91.0,false,DoNotOverride,5.0",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Alors, je voudrais prendre une dernière photo avec elle.",
          DialogueId = 10125106,
          FacialId = {
            [1] = "200027:Satisfy01"
          },
          FinalCamera = "-149.609375,81.59375,-7.086914,7.00087,29.425505,-7.648393,20.000008,91.0,false,DoNotOverride,5.0",
          GUID = "1958DE34",
          LookAt = {
            [1] = "200027:p(P101251Saiqi)"
          },
          SpeakNpcId = 200027,
          Subtitle = "So... I'd like to take a picture with it.",
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "200027:p(-60)"
          },
          VoiceName = "voice/$Locale$/story/1002/101251/1958DE34"
        },
        [10125107] = {
          ContentFR = "Par ici—",
