          SpeakNpcId = 100001,
          Subtitle = "Let's take another one. Three, two, one—",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101251/1958DEB2"
        },
        [10125201] = {
          ContentFR = "<I>Cette personne... j’ai l’impression de l’avoir déjà vu quelque part...</>",
          DialogueId = 10125201,
          DisableMouth = 1,
          GUID = "1958EDCA",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "(That guy over there looks familiar... Have I met him before?)",
          VoiceName = "voice/$Locale$/story/1002/101252/1958EDCA"
        },
        [10125301] = {
          ContentFR = "Je vais vraiment tirer ! Je ne plaisante pas !",
          DialogueId = 10125301,
          GUID = "1958FE32",
          Subtitle = "I swear, I'll do it! I'm not bluffing!!",
          VoiceName = "voice/$Locale$/story/1002/101253/1958FE32"
        },
        [10125401] = {
          ContentFR = "Waaah ! Vite, courez ! Cette glace va céder !",
          DialogueId = 10125401,
          GUID = "19590E9A",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Whoa! Get off it now! The ice is cracking!",
          VoiceName = "voice/$Locale$/story/1002/101254/19590E9A"
        },
        [10125501] = {
          ContentFR = "La glace est trop fragile. On devrait d’abord gagner une plate-forme plus solide.",
          DialogueId = 10125501,
          GUID = "19591F02",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200021,
          Subtitle = "The ice won't hold. Maybe we should move to a more stable platform first.",
          VoiceName = "voice/$Locale$/story/1002/101255/19591F02"
        },
        [10125601] = {
          ContentFR = "<I>C’est sûrement le dernier passage...</>",
          DialogueId = 10125601,
          DisableMouth = 1,
          GUID = "19592F6A",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10125602,
          SpeakNpcId = 100001,
          Subtitle = "(This should be the final stretch...)",
          VoiceName = "voice/$Locale$/story/1002/101256/19592F6A"
        },
        [10125602] = {
          ContentFR = "<I>Psyche, attends-moi... Je viens te ramener à la maison.</>",
          DialogueId = 10125602,
          DisableMouth = 1,
          GUID = "19592F94",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          Subtitle = "(Psyche, wait for me... I'm bringing you home.)",
          VoiceName = "voice/$Locale$/story/1002/101256/19592F94"
        },
        [10125701] = {
          ContentFR = "{nickname}, où es-tu ?",
          DialogueId = 10125701,
          GUID = "19593FD2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = ", where are you?",
          VoiceName = "voice/$Locale$/story/1002/101257/19593FD2"
        },
        [10125702] = {
          ContentFR = "Tu t’es déjà éloigné ? Je vais t’attendre ici...",
          DialogueId = 10125702,
          GUID = "19593FFC",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "Have you wandered off? I'll wait for you here...",
          VoiceName = "voice/$Locale$/story/1002/101257/19593FFC"
        },
        [10125801] = {
          ContentFR = "Rentre te reposer un peu. Je sais que tu n’arriveras pas à dormir, mais même une pause te fera du bien.",
          DialogueId = 10125801,
          GUID = "1959503A",
          NextDialogue = 10125802,
          SpeakNpcId = 200021,
          Subtitle = "Go back and catch some Z's. I know you probably won't be able to fall asleep, but at least it helps refresh you.",
          VoiceName = "voice/$Locale$/story/1002/101258/1959503A"
        },
        [10125802] = {
          ContentFR = "Non, merci. J’ai envie de marcher {性别:seul|seule} un moment.",
          DialogueId = 10125802,
          GUID = "19595064",
          NextDialogue = 10125803,
          SpeakNpcId = 100001,
          Subtitle = "Thanks, but I want to take a walk by myself for a while.",
          VoiceName = "voice/$Locale$/story/1002/101258/19595064"
        },
        [10125803] = {
          ContentFR = "... Très bien. Mais la nuit est longue à Givrelac. Reste sur tes gardes.",
          DialogueId = 10125803,
          GUID = "1959508E",
          SpeakNpcId = 200021,
          Subtitle = "...Okay. The nights in Icelake are long. Be careful when you're out there.",
          VoiceName = "voice/$Locale$/story/1002/101258/1959508E"
        },
        [10125901] = {
          Camera = "454.923828,1684.220703,-255.024414,8.000015,2.99999,-111.999702,35.0,320.217255,false,Manual,4.0",
          ContentFR = "Que ton âme trouve la paix... au plus profond de la Mer du Silence...",
          DialogueId = 10125901,
          GUID = "195960A2",
          LookAt = {
            [1] = "200076:n(200076)",
            [2] = "100001:n(200076)"
          },
          NextOptions = {
