CameraMoveTo{_delay{2},TargetPosition{"459.208008,1670.798828,-255.015625,7.204637,13.598475,-112.975624,35.0,1885.852173,false,Manual,4.0"},blend{"easeInOutQuad"},duration{3.5}}
}]],
          SpeakNpcId = 200076,
          Subtitle = "May your soul find peace in the depths of the Misty Sea...",
          VoiceName = "voice/$Locale$/story/1002/101259/195960A2"
        },
        [10125902] = {
          Camera = "143.350586,113.806641,100.092773,-15.001924,4.999999,-149.999969,35.0,181.272781,false,Manual,3.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Te voilà, mon enfant... Attends un instant, le temps que j’achève ce dernier rite.",
          DialogueId = 10125902,
          FinalCamera = "143.849609,101.626953,103.511719,-15.001992,4.999999,-152.5,35.0,181.272781,false,Manual,3.0",
