        [10129701] = {
          Camera = "98.882812,336.099609,13.861816,0.00006,13.998199,-124.392242,15.0,100000.0,false,Disable,2.8",
          CameraBlendCurve = "easeInOutQuad",
          DialogueId = 10129701,
          FinalCamera = "176.5,102.359375,-7.201416,0.000064,19.197878,-143.98999,15.0,100000.0,false,Disable,2.8",
          GUID = "195BD012",
          ToFinalCameraBlendTime = 3
        },
        [10129801] = {
          ContentFR = "Le voleur est juste devant ! Oh non... il affronte des Souillés !",
          DialogueId = 10129801,
          GUID = "195BD013",
          NextDialogue = 10129802,
          SpeakNpcId = 200011,
          Subtitle = "The thief's up ahead! Oh no... he's in a fight with Filthoids!",
          VoiceName = "voice/$Locale$/story/1002/101298/195BD013"
        },
        [10129802] = {
          ContentFR = "Écartons les Souillés, et attrapons-le.",
          DialogueId = 10129802,
          GUID = "195BD014",
          SpeakNpcId = 100001,
          Subtitle = "Let's drive away the Filthoids and get him.",
          VoiceName = "voice/$Locale$/story/1002/101298/195BD014"
        },
        [10129901] = {
          ContentFR = "On raconte que, chaque nuit, des sanglots s’en échappent... et parfois, qu’une odeur étrange flotte dans l’air.",
          DialogueId = 10129901,
          GUID = "195BD015",
          Subtitle = "They say you can hear sobbing every night — and now and then, there's this strange smell drifting from the windows.",
          VoiceName = "voice/$Locale$/story/1002/101299/195BD015"
        },
        [10130001] = {
          ContentFR = "Quoi qu’il en soit, les histoires d’Henrik ne me concernent pas directement. Mais... si elles sont vraies, je crains pour la sécurité de Psyche.",
          DialogueId = 10130001,
          GUID = "195BD016",
          NextDialogue = 10106325,
          SpeakNpcId = 100001,
          Subtitle = "Whatever's going on with Henrik — that's not my business. But if he's really up to something... I'm worried Psyche might get hurt.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101300/195BD016"
        },
        [10130101] = {
          Camera = "17.943359,4617.524414,902.814453,0.000375,15.299773,-91.196564,30.0,5448.511719,false,DoNotOverride,22.0",
          ContentFR = "Si nous {性别:le|la} retrouvons... l’hôte de la Résonance, que comptez-vous en faire ?",
          DialogueId = 10130101,
          Duration = 8,
          FinalCamera = "37.016602,4939.133301,642.138672,0.000375,15.299773,-91.196564,30.0,5448.511719,false,DoNotOverride,22.0",
          GUID = "195BD017",
          NextDialogue = 10130102,
          SpeakNpcId = 100006,
          Subtitle = "If we do find {性别:him|her}... the host of Resonance — what's the plan, Chief?",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/101301/195BD017"
        },
        [10130102] = {
          ContentFR = "Un pouvoir de Résonance totalement éveillé peut influer sur tous les Daimons... mais ce pouvoir dépend entièrement de la volonté de son détenteur.",
          DialogueId = 10130102,
          Duration = 8,
          GUID = "195BD018",
          NextDialogue = 10130103,
          SpeakNpcId = 100006,
          Subtitle = "A fully awakened Resonance can exert control over any Daimon. But that power hinges entirely on the host's will.",
          VoiceName = "voice/$Locale$/story/1002/101301/195BD018"
        },
        [10130103] = {
          Camera = "-1576.924561,1990.549316,316.099609,0.000029,-7.400209,-45.991081,35.000008,2186.29834,false,Manual,1.2",
          ContentFR = "Autrement dit, à moins {性别:qu’il|qu’elle} ne coopère, {性别:le|la} capturer n’apporterait rien à l’Empire. Pire encore, cela pourrait devenir une menace. Comme autrefois...",
          DialogueId = 10130103,
          Duration = 8,
          FinalCamera = "-1587.533691,2001.532227,318.089844,0.000029,-7.400209,-45.991081,35.000008,2186.29834,false,Manual,1.2",
          GUID = "195BD019",
          NextDialogue = 10130104,
          SpeakNpcId = 100006,
          Subtitle = "Which means: if {性别:he|she} won't cooperate, then capturing {性别:him|her} does the Empire no good. Worse — it could become a threat. Just like last—",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101301/195BD019"
        },
        [10130104] = {
          Camera = "-40.981445,48.569336,104.802734,0.000054,3.698834,-87.387604,35.0,198.622971,false,DoNotOverride,3.0",
          ContentFR = "Alors on l’efface. Comme autrefois. Quoi qu’il en soit, ce pouvoir ne doit jamais tomber hors des mains de l’Empire, et surtout pas dans celles d’Élysium. Bon, et l’autre mauvaise nouvelle ?",
          DialogueId = 10130104,
          Duration = 10,
          FinalCamera = "-42.826172,89.025879,102.189453,0.000054,3.698834,-87.387604,35.0,198.622971,false,DoNotOverride,3.0",
          GUID = "195BD020",
          NextDialogue = 10108013,
          SpeakNpcId = 100005,
          Subtitle = "Then we do what we did before. Wipe it out. That power cannot fall outside Imperial hands — least of all into Elysium's. Now, the other bad news?",
          TalkActionId = {
            [1] = "100005:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101301/195BD020"
        },
        [10130201] = {
          ContentFR = "« Fleur du Souvenir »... c’est une boutique ! Eh ? Il a rendez-vous avec quelqu’un ?",
          DialogueId = 10130201,
          GUID = "195BD021",
          NextDialogue = 10130202,
          SpeakNpcId = 200002,
          Subtitle = "\"Flowers of Solicitude\"... It's a flower shop! Wait... is he going on a date!?",
          VoiceName = "voice/$Locale$/story/1002/101302/195BD021"
        },
        [10130202] = {
          ContentFR = "On va s’asseoir en face et attendre qu’il ressorte !",
          DialogueId = 10130202,
          GUID = "195BD022",
          SpeakNpcId = 200002,
          Subtitle = "Let's grab a seat across the street and wait for him to come out!",
          VoiceName = "voice/$Locale$/story/1002/101302/195BD022"
        },
        [10130301] = {
          Camera = "216.478516,-137.633301,117.546875,0.000164,-6.198915,127.211983,35.0,407.218628,false,DoNotOverride,4.0",
          ContentFR = "Il est là !",
          DialogueId = 10130301,
          GUID = "195BD023",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "100001:p(LC_EnterFlow)"
          },
          NextDialogue = 10130302,
          Scripts = "MoveTo{ActorId{200002},MoveSpeed{220},TargetPoint{\"P1190930Bai1\"}}",
          SpeakNpcId = 200002,
          Subtitle = "There he is!",
          VoiceName = "voice/$Locale$/story/1002/101303/195BD023"
        },
        [10130302] = {
          Camera = "-353.71582,-276.680176,199.59375,0.000172,-9.398859,23.610058,20.0,407.218628,false,DoNotOverride,4.0",
          ContentFR = "Puis-je vous offrir quelque chose à boire ?",
          DialogueId = 10130302,
          GUID = "195BD024",
          NextDialogue = 10130303,
          Scripts = "MoveTo{ActorId{200097},MoveSpeed{80},TargetPoint{\"P1190930Boy1\"}}",
          SpeakNpcId = 200097,
          Subtitle = "Can I get you two something to drink?",
          VoiceName = "voice/$Locale$/story/1002/101303/195BD024"
        },
        [10130303] = {
          Camera = "105.118164,-51.828613,93.718262,0.0,-2.999962,129.999985,30.0,118.813644,false,Manual,4.0",
          ContentFR = "Oh non, merci ! On va juste s’asseoir un peu, profiter du paysage ! Tu vois ce beau soleil ce soir, hé hé...",
          DialogueId = 10130303,
          GUID = "195BD025",
          NextDialogue = 10130304,
          SpeakNpcId = 200002,
          Subtitle = "Oh, we're good! Just, uh... hanging out and enjoying the view! Isn't the sunlight lovely tonight? Heehee...",
          TalkActionId = {
            [1] = "200002:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1002/101303/195BD025"
        },
        [10130304] = {
          Camera = "-353.71582,-276.680176,199.59375,0.000172,-9.398859,23.610058,20.0,407.218628,false,DoNotOverride,4.0",
          ContentFR = "Eh bien, rien ne va mieux avec un joli paysage qu’une bonne boisson ! Nous avons toutes sortes de cafés, le jus de Baie boréale de Givrelac... Oh ! Ou que diriez-vous de notre toute dernière spécialité : un potage au hareng mariné, riche et crémeuse ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10130304,
          GUID = "195BD026",
          NextDialogue = 10130305,
          SpeakNpcId = 200097,
          Subtitle = "Well, nothing pairs with a good view like a good drink! We've got all kinds of coffee, Icelake's own Borealberry Juice... Oh! And how about our newest special — rich, creamy Pickled Herring Soup?",
          TalkActionId = {
            [1] = "200097:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101303/195BD026"
        },
        [10130305] = {
          Camera = "126.273438,-640.34082,115.856201,0.000007,0.0,89.999985,20.0,118.813644,false,Manual,4.0",
          ContentFR = "Non merci, on a des choses à faire... Attends, Henrik ?",
          DialogueId = 10130305,
          GUID = "195BD027",
          NextDialogue = 10130306,
          SpeakNpcId = 100001,
          Subtitle = "No thanks, we've got someth— ...Wait, where's Henrik?",
          VoiceName = "voice/$Locale$/story/1002/101303/195BD027"
        },
        [10130306] = {
          Camera = "48.96875,256.841797,105.016113,-1.5,-4.999971,-84.999916,30.0,169.724716,false,Manual,4.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Oups... on dirait qu’on l’a perdu...",
          DialogueId = 10130306,
          FinalCamera = "48.96875,256.841797,105.016113,-1.5,-4.999971,-84.999916,30.0,680.897827,false,Manual,1.2",
          GUID = "195BD028",
          LookAt = {
            [1] = "200002:p(LC_EnterFlow)",
            [2] = "100001:p(LC_EnterFlow)"
          },
          NextDialogue = 10130307,
          SpeakNpcId = 200002,
          Subtitle = "Aww, I think we lost him...",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/story/1002/101303/195BD028"
        },
        [10130307] = {
          Camera = "-31.876953,-170.957031,169.342773,0.0,-14.000125,51.202343,30.0,155.608383,false,Manual,3.0",
          ContentFR = "... Allons demander au fleuriste et tenter notre chance.",
          DialogueId = 10130307,
          GUID = "195BD029",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          SpeakNpcId = 100001,
          Subtitle = "...Let's ask the florist and try our luck.",
          VoiceName = "voice/$Locale$/story/1002/101303/195BD029"
        },
        [10130401] = {
          Camera = "-137.371094,-123.811035,229.291016,0.000012,-12.600093,90.599869,16.000004,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Le fourneau est immense. Le feu est éteint depuis longtemps, mais les cendres à l’intérieur montrent qu’il a été utilisé récemment.",
          DialogueId = 10130401,
          DisableMouth = 1,
          FinalCamera = "-132.40625,-283.590576,87.898438,0.000034,13.599972,91.399513,16.000004,100000.0,false,DoNotOverride,2.8",
          GUID = "195BD030",
          LookAt = {
            [1] = "200021:n(200021)"
          },
          NextDialogue = 10130402,
          Scripts = "TurnTo{_delay{1},TurnToDescription{\"200021:p(-180)\"}}",
          Subtitle = "(The furnace is massive. The fire's long out, but the ashes inside suggest recent usage.)",
          TalkActionId = {
            [1] = "200021:Confident_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101304/195BD030"
        },
        [10130402] = {
          ContentFR = "Un fourneau de cette taille... ce n’est pas pour cuisiner, ni pour se chauffer. Alors... qu’est-ce qu’on y brûlait ? ... Ça ne serait pas... ?",
          DialogueId = 10130402,
          GUID = "195BD031",
          NextOptions = {
            [1] = 101089041
          },
          SpeakNpcId = 200021,
          Subtitle = "A furnace this big... No way it's for cooking. And it doesn't look like a heater, either. So what was it burning? ...Could it be...?",
          VoiceName = "voice/$Locale$/story/1002/101304/195BD031"
        },
        [10130403] = {
          Camera = "347.035156,-42.462402,107.822266,0.000021,10.600562,131.583298,50.000008,244.668961,false,Manual,8.0",
          ContentFR = "... Hunt ? Impossible...",
          DialogueId = 10130403,
          FacialId = {
            [1] = "200021:Sad01"
          },
          GUID = "195BD032",
          NextDialogue = 10108907,
          SpeakNpcId = 200021,
          Subtitle = "...Hunt? Don't tell me he's already...!",
          VoiceName = "voice/$Locale$/story/1002/101304/195BD032"
        },
        [10130404] = {
          Camera = "-129.605469,-339.571289,61.544922,-0.0,12.49999,90.0,20.0,137.182159,false,Manual,5.0",
          ContentFR = "Le fourneau est immense. Le feu est éteint depuis longtemps, mais les cendres à l’intérieur montrent qu’il a été utilisé récemment.",
          DialogueId = 10130404,
          DisableMouth = 1,
          FinalCamera = "-129.605469,-227.858643,81.646484,-0.0,12.49999,90.0,20.0,137.182159,false,Manual,5.0",
          GUID = "194E7CBC",
          NextDialogue = 10130405,
          SpeakNpcId = 200021,
          Subtitle = "(The furnace is massive. The fire's long out, but the ashes inside suggest recent usage.)",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101304/195BD030"
        },
        [10130405] = {
          ContentFR = "Un fourneau de cette taille... ce n’est pas pour cuisiner, ni pour se chauffer. Alors... qu’est-ce qu’on y brûlait ? ... Ça ne serait pas... ?",
          DialogueId = 10130405,
          GUID = "194E7CBD",
          SpeakNpcId = 200021,
          Subtitle = "A furnace this big... No way it's for cooking. And it doesn't look like a heater, either. So what was it burning? ...Could it be...?",
          VoiceName = "voice/$Locale$/story/1002/101304/195BD031"
        },
        [10130406] = {
          Camera = "347.035156,-42.462402,107.822266,0.000021,10.600562,131.583298,50.000008,244.668961,false,Manual,8.0",
          ContentFR = "... Hunt ? Impossible...",
          DialogueId = 10130406,
          FacialId = {
            [1] = "200021:Sad01"
          },
          GUID = "194E7CBF",
          NextDialogue = 10108912,
          SpeakNpcId = 200021,
          Subtitle = "...Hunt? Don't tell me he's already...!",
          VoiceName = "voice/$Locale$/story/1002/101304/195BD032"
        },
        [10130501] = {
          ContentFR = "Cible manquée. À cette distance, impossible de confirmer l’état de la cible ou de l’otage.",
          DialogueId = 10130501,
          GUID = "195BD033",
          NextDialogue = 10130502,
          Subtitle = "Target missed. Unable to confirm the status of either target or hostage from this range.",
          VoiceName = "voice/$Locale$/story/1002/101305/195BD033"
        },
        [10130502] = {
          ContentFR = "... Préparez-vous au combat frontal !",
          DialogueId = 10130502,
          GUID = "195BD034",
          Subtitle = "...Prepare for direct engagement!",
          VoiceName = "voice/$Locale$/story/1002/101305/195BD034"
        },
        [10130601] = {
          Camera = "-90.074219,755.777344,469.635742,0.000111,-25.499575,-93.596069,25.0,467.444916,false,Manual,22.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "... Madame, le Dégradé... il est déjà... !",
          DialogueId = 10130601,
          FacialId = {
            [1] = "100001:Shock02",
            [2] = "200002:Shock02",
            [3] = "200021:Angry01",
            [4] = "2000581:Close"
          },
          FinalCamera = "-95.249023,668.898438,428.417969,0.000102,-26.099579,-95.596054,25.0,467.444916,false,Manual,22.0",
          GUID = "195BD035",
          LookAt = {
            [1] = "100001:n(2000581)"
          },
          NextDialogue = 10130602,
          Scripts = "PlayAnimation{ActorId{2000581},AnimationId{\"BossSaiqi_Story_Die\"},Sync{true}}",
          SpeakNpcId = 700065,
          Subtitle = "...Ma'am, the Deteriorator — it's already...!",
          TalkActionId = {
            [1] = "100001:Crouch_Loop",
            [2] = "2000581:BossSaiqi_Story_Die"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/101306/195BD035"
        },
        [10130602] = {
          ContentFR = "... Quelque chose ne va pas. Mais au moins, les otages sont indemnes.",
          DialogueId = 10130602,
          GUID = "195BD036",
          NextDialogue = 10130603,
          SpeakNpcId = 100304,
          SpeakNpcName = "UI_Npc_Name_FemaleOfficer",
          Subtitle = "...Something's off. But the hostages are safe, at least.",
          VoiceName = "voice/$Locale$/story/1002/101306/195BD036"
        },
        [10130603] = {
          Camera = "82.416016,128.960938,14.348633,-3.000001,-0.400782,-132.985641,30.000002,214.526855,false,Manual,3.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Rhythm Fischer, adjudante des Veilleurs de la région de Cocytus, VIᵉ Légion.",
          DialogueId = 10130603,
          FacialId = {
            [1] = "100304:Confident01"
          },
          FinalCamera = "67.181641,112.957031,9.427734,-3.0,9.399194,-131.986374,30.000002,821.013916,false,Manual,3.0",
          GUID = "195BD037",
          LookAt = {
            [1] = "100304:n(100001)",
            [2] = "200002:n(100304)",
            [3] = "200021:n(100304)"
          },
          NextDialogue = 10130604,
          RelatedWikiId = {
            [1] = 201011
          },
          Scripts = [[
PARA{
LookAt{_delay{1},LookAtDescription{"100001:n(100304)"}},
CameraMoveTo{_delay{5},TargetPosition{"-171.574219,-159.355469,93.070312,-3.000002,14.99738,-143.982834,30.000002,169.915115,false,Manual,3.0"},duration{0}}
}]],
          SpeakNpcId = 100304,
          Subtitle = "Rhythm Fischer, Warrant Officer of the Cocytus Escort, 6th Legion.",
          TalkActionId = {
            [1] = "100304:Talk02_Start"
          },
          ToFinalCameraBlendTime = 4.5,
          VoiceName = "voice/$Locale$/story/1002/101306/195BD037"
        },
        [10130604] = {
          ContentFR = "Le Souillé est extrêmement dangereux. Même s’il a cessé d’attaquer, il pourrait simplement être en sommeil. Allez vite vous réfugier dans la cité. Les Veilleurs se chargeront du reste.",
          DialogueId = 10130604,
          GUID = "195BD038",
          NextDialogue = 10113038,
          SpeakNpcId = 100304,
          Subtitle = "The Filthoid is highly dangerous. Although it's ceased attacking, it may only be in temporary dormancy. Return to the city immediately — the Escort will take it from here.",
          TalkActionId = {
            [1] = "100304:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101306/195BD038"
        },
        [10130605] = {
          Camera = "-161.636719,-90.765625,127.488281,0.00052,4.203223,-9.400385,35.0,132.664047,false,Manual,3.0",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Inutile, Madame. Avant que vous n’arriviez, nous l’avions déjà neutralisée. Elle est bel et bien morte, vous n’avez plus à gaspiller vos balles.",
          DialogueId = 10130605,
          FacialId = {
            [1] = "200021:Angry01"
          },
          FinalCamera = "-161.636719,-90.765625,127.488281,0.000524,4.003215,-14.402719,35.0,319.412994,false,Manual,3.0",
          GUID = "195BD039",
          LookAt = {
            [1] = "200021:n(200021)",
            [2] = "100304:n(200021)"
          },
          NextDialogue = 10113039,
          Scripts = [[
PARA{
PlayAnimation{_delay{0.5},ActorId{200021},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{3},ActorId{200021},AnimationId{"Talk02_Start"},Duration{1}},
LookAt{_delay{1},LookAtDescription{"100001:n(200021)"}},
CameraMoveTo{_delay{3},TargetPosition{"-42.216797,-134.367188,154.807617,0.000533,-0.196989,-13.007848,35.0,126.183968,false,Manual,3.0"},duration{0}}
}]],
          SpeakNpcId = 200021,
          Subtitle = "No need, ma'am. We took care of it before you got here. No point wasting more bullets.",
          TalkActionId = {
            [1] = "100304:Explain01_End"
          },
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1002/101306/195BD039"
        },
        [10130606] = {
          Camera = "-201.873047,-180.394531,124.880859,0.00054,2.802508,-144.973618,25.0,115.146286,false,Manual,22.0",
          ContentFR = "... Effectivement. Voilà qui explique pourquoi cette cible était bien plus stable que la plupart des Souillés.",
          DialogueId = 10130606,
          GUID = "195BD040",
          NextDialogue = 10113008,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"100304:n(2000581)"}},
CameraMoveTo{TargetPosition{"-276.560547,-230.78125,137.651367,0.00053,-23.796835,47.828102,50.0,371.84317,false,Manual,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"-281.869141,-238.039062,141.693359,0.000539,-23.996824,53.828442,50.0,371.84317,false,Manual,22.0"},duration{3}},
StopTalkGroup{ActorId{100304},Duration{0.5}}
}]],
          SpeakNpcId = 100304,
          Subtitle = "...I see. That would explain why the target was more stable than a typical Filthoid.",
          TalkActionId = {
            [1] = "100304:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101306/195BD040"
        },
        [10130701] = {
          ContentFR = "Hé, regardez ! Un carnet ! Et si c’était le journal d’un aventurier légendaire ?!",
          DialogueId = 10130701,
          GUID = "195BD041",
          Subtitle = "A notebook's here! Could it be some legendary adventurer's journal?!",
          VoiceName = "voice/$Locale$/story/1002/101307/195BD041"
        },
        [10130800] = {
          DialogueId = 10130800,
          DialoguePanelType = "{type:showtext;topic:Reading_Title_101223;content:Reading_Content_101223}",
          GUID = "195BD04A",
          NextDialogue = 10130801
        },
        [10130801] = {
          Camera = "50.077148,-329.630371,240.10498,0.000162,-26.599609,119.809021,50.0,292.198273,false,Manual,7.759425",
          ContentFR = "Petit larbin, regarde ! Il y a plein de <H>barils de poudre</> juste à côté !",
          DialogueId = 10130801,
          Duration = 10,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "195BD042",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 10130802,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{1.5},TargetPosition{"50.077148,-329.630371,240.10498,0.000162,-26.599609,119.809021,50.0,292.198273,false,Manual,7.759425"},duration{0}},
CameraMoveTo{TargetPosition{"50.077148,-329.630371,240.10498,0.000181,-16.799314,101.009155,50.0,292.198273,false,Manual,7.759425"},Blend{"easeInOutQuad"},duration{8}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Look over there, Little Minion. There are several powder kegs.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101308/195BD042"
        },
        [10130802] = {
          Camera = "-137.248779,-3.609863,123.338379,0.000239,6.000567,-59.584656,35.0,167.968307,false,Manual,7.759425",
          ContentFR = "Oui... Le carnet parle justement de poudre explosive. On devrait pouvoir les utiliser pour <H>faire sauter ces cristaux jaunes</>.",
          DialogueId = 10130802,
          Duration = 10,
          FinalCamera = "-127.740967,-19.807373,125.3125,0.000239,6.400563,-58.98452,35.0,167.968307,false,Manual,7.759425",
          GUID = "195BD043",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextDialogue = 10130803,
          SpeakNpcId = 100001,
          Subtitle = "I see. The journal also mentioned gunpowder. Maybe we can use the kegs to blow up the yellow crystals.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101308/195BD043"
        },
        [10130803] = {
          Camera = "269.530029,368.111084,118.398438,0.000066,-2.199314,-128.599228,30.0,619.991211,false,Manual,1.2",
          ContentFR = "Alors prenons-les ! On n’est jamais trop préparé quand on part à l’aventure !",
          DialogueId = 10130803,
          Duration = 10,
          FinalCamera = "257.802246,377.4729,118.398438,0.000066,-2.199314,-128.599228,30.0,274.965851,false,Manual,1.2",
          GUID = "195BD044",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          SpeakNpcId = 200002,
          Subtitle = "Let's take them with us then. You can never be too prepared when you're adventuring!",
          TalkActionId = {
            [1] = "200002:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101308/195BD044"
        },
        [10130901] = {
          ContentFR = "Argh ! La route est bouchée par ces horribles pics de cristal jaunes !",
          DialogueId = 10130901,
          GUID = "195BD045",
          NextDialogue = 10130902,
          SpeakNpcId = 200002,
          Subtitle = "Argh, those nasty yellow crystal spikes block our way!",
          VoiceName = "voice/$Locale$/story/1002/101309/195BD045"
        },
        [10130902] = {
          ContentFR = "Ces barils de poudre devraient faire l’affaire.",
          DialogueId = 10130902,
          GUID = "195BD046",
          SpeakNpcId = 100001,
          Subtitle = "The powder kegs we just found can be of great help now.",
          VoiceName = "voice/$Locale$/story/1002/101309/195BD046"
        },
        [10130903] = {
          ContentFR = "<I>Mieux vaut reculer un peu, et tirer dessus pour déclencher l’explosion.</>",
          DialogueId = 10130903,
          GUID = "195BD047",
          IsBlack = 1,
          SpeakNpcId = 100001,
          Subtitle = "(Might as well stay far and shoot to detonate them.)",
          VoiceName = "voice/$Locale$/story/1002/101309/195BD047"
        },
        [10131001] = {
          ContentFR = "Ça a marché ! ... Oh ! Tu vas bien ? Roi Démon, pourquoi tu t’accroupis comme ça ? Tu es blessée ?",
          DialogueId = 10131001,
          GUID = "195BD048",
          NextDialogue = 10131002,
          SpeakNpcId = 200006,
          Subtitle = "It works! ...Oh, are you okay? Why are you squatting on the ground, Demon King? Are you hurt?",
          VoiceName = "voice/$Locale$/story/1002/101310/195BD048"
        },
        [10131002] = {
          ContentFR = "Hein ?! N... non ! Ce n’était qu’une petite e-explosion ! J’étais... en train d’étudier le terrain ! Hé hé...",
          DialogueId = 10131002,
          GUID = "195BD049",
          NextDialogue = 10131003,
          SpeakNpcId = 200002,
          Subtitle = "Ah?! I...I'm fine, it was j...just a small blast! I was just... um... checking out the ground... Hehe...",
          VoiceName = "voice/$Locale$/story/1002/101310/195BD049"
        },
        [10131003] = {
          ContentFR = "Chut !",
          DialogueId = 10131003,
          GUID = "195BD050",
          NextDialogue = 10131004,
          SpeakNpcId = 100001,
          Subtitle = "Ssh!",
          VoiceName = "voice/$Locale$/story/1002/101310/195BD050"
        },
        [10131004] = {
          ContentFR = "<I>Grrrroaaar—</>",
          DialogueId = 10131004,
          GUID = "195BD051",
          NextDialogue = 10131005,
          SpeakNpcName = "MESSAGE_TITLE_LOADING_14_PC",
          Subtitle = "*Roar—*",
          VoiceName = "voice/$Locale$/story/1002/101310/195BD051"
        },
        [10131005] = {
          ContentFR = "... On dirait qu’il y a quelque chose au fond de la fosse.",
          DialogueId = 10131005,
          GUID = "195BD052",
          NextDialogue = 10131006,
          SpeakNpcId = 200006,
          Subtitle = "...There seems to be somthing deep in the pit.",
          VoiceName = "voice/$Locale$/story/1002/101310/195BD052"
        },
        [10131006] = {
          ContentFR = "Le carnet parlait d’un Souillé spécial, tapi dans ces galeries... Restons {性别:prudents|prudentes} et ne nous éparpillons pas.",
          DialogueId = 10131006,
          GUID = "195BD053",
          SpeakNpcId = 100001,
          Subtitle = "The journal mentioned that there could be a special Filthoid down there... We should be careful and stay close.",
          VoiceName = "voice/$Locale$/story/1002/101310/195BD053"
        },
        [10131101] = {
          ContentFR = "Regardez ! Ce gros cristal au milieu... il brille ! Et si c’était l’Éclat stellaire qu’on cherche ?!",
          DialogueId = 10131101,
          GUID = "195BD054",
          SpeakNpcId = 200002,
          Subtitle = "Look, a giant crystal in the middle is glowing. Could it be that the Crystallo of Stella we're looking for is inside?",
          VoiceName = "voice/$Locale$/story/1002/101311/195BD054"
        },
        [10131201] = {
          ContentFR = "<I>Grrrroaaar—</>",
          DialogueId = 10131201,
          GUID = "195BD055",
          NextDialogue = 10131202,
          SpeakNpcName = "MESSAGE_TITLE_LOADING_14_PC",
          Subtitle = "*Roar—*",
          VoiceName = "voice/$Locale$/story/1002/101312/195BD055"
        },
        [10131202] = {
          ContentFR = "C’est encore ce bruit !",
          DialogueId = 10131202,
          GUID = "195BD056",
          NextDialogue = 10131203,
          SpeakNpcId = 200006,
          Subtitle = "That voice again!",
          VoiceName = "voice/$Locale$/story/1002/101312/195BD056"
        },
        [10131203] = {
          ContentFR = "Waaah ! Mais pourquoi y en a-t-il autant d’un coup ?! ... Euh... euh-euhhh...",
          DialogueId = 10131203,
          GUID = "195BD057",
          NextDialogue = 10131204,
          SpeakNpcId = 200002,
          Subtitle = "Ahhh— How come there are so many Filthoids coming at us out of nowhere?! ...Uh... Uh-oh...",
          VoiceName = "voice/$Locale$/story/1002/101312/195BD057"
        },
        [10131204] = {
          ContentFR = "Ce sont sûrement les détonations qui les ont attirés...",
          DialogueId = 10131204,
          GUID = "195BD058",
          NextDialogue = 10120102,
          SpeakNpcId = 200006,
          Subtitle = "Perhaps they were attracted by the explosion...",
          VoiceName = "voice/$Locale$/story/1002/101312/195BD058"
        },
        [10131301] = {
          Camera = "775.768799,-65.358398,179.694336,0.000056,-1.399676,-179.401596,20.0,100000.0,false,Disable,2.8",
          ContentFR = "Bombe de Lumière Radieuse — Laissez le Rédempteur Immaculé sauver le monde ! BOUM !",
          DialogueId = 10131301,
          GUID = "195BD059",
          NextDialogue = 10131302,
          SpeakNpcId = 200002,
          Subtitle = "Take my Shiny Bomb! Let the Pure-White Redeemer save the world! Boom!",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD059"
        },
        [10131302] = {
          ContentFR = "Pas besoin de « boum », les Souillés sont déjà morts.",
          DialogueId = 10131302,
          GUID = "195BD060",
          NextDialogue = 10131303,
          SpeakNpcId = 200006,
          Subtitle = "It's okay. The Filthoids have been taken care of.",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD060"
        },
        [10131303] = {
          ContentFR = "Oh... vraiment ? Alors, montre au Roi Démon ses glorieux butins !",
          DialogueId = 10131303,
          GUID = "195BD061",
          NextDialogue = 10131304,
          SpeakNpcId = 200002,
          Subtitle = "Oh really? Show this Demon King the loot then—",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD061"
        },
        [10131304] = {
          ContentFR = "Camilla disait que l’Éclat stellaire est un cristal bleu-violet parcouru de nébuleuses en mouvement... Celui-ci ressemble plutôt à une simple Argentite.",
          DialogueId = 10131304,
          GUID = "195BD062",
          NextDialogue = 10131305,
          SpeakNpcId = 100001,
          Subtitle = "Camilla once mentioned that Crystallo of Stella is a blue-violet crystal with \"nebulae swirling in it.\" This one is more like a chunk of Silverite.",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD062"
        },
        [10131305] = {
          ContentFR = "Pff... nul.",
          DialogueId = 10131305,
          GUID = "195BD063",
          NextDialogue = 10131307,
          SpeakNpcId = 200002,
          Subtitle = "Argh... That's lame.",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD063"
        },
        [10131306] = {
          ContentFR = "De l’<H>Argentite</> ? Quand j’étais petite, le tailleur d’à côté me disait qu’on pouvait l’utiliser pour des pigments ou des <H>teintures</>.",
          DialogueId = 10131306,
          GUID = "195BD064",
          SpeakNpcId = 200006,
          Subtitle = "Silverite? When I was little, the tailor next door mentioned that this kind of mineral can be used to make pigments or dyes.",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD064"
        },
        [10131307] = {
          ContentFR = "Petit larbin, montre-la à <H>Luno, la forgeronne</> quand tu auras le temps ! Mais pour l’instant, laissez le Roi Démon vous guider toujours plus loin dans les profondeurs !",
          DialogueId = 10131307,
          GUID = "195BD065",
          NextDialogue = 10131308,
          SpeakNpcId = 200002,
          Subtitle = "Then bring it back to Lunosmith, Little Minion. As for now, let this Demon King continue to lead you deeper into the pit!",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD065"
        },
        [10131308] = {
          ContentFR = "Oui, oui... À vos ordres, Roi Démon.",
          DialogueId = 10131308,
          GUID = "195BD066",
          SpeakNpcId = 200006,
          Subtitle = "Hehe... Yes, Your Majesty.",
          VoiceName = "voice/$Locale$/story/1002/101313/195BD066"
        },
        [10131401] = {
          ContentFR = "Ces pics de cristal jaunes... ils renfermaient plein de pierres étincelantes !",
          DialogueId = 10131401,
          GUID = "195BD067",
          NextDialogue = 10131402,
          SpeakNpcId = 200002,
          Subtitle = "These yellow crystal spikes actually have so many glittering stones inside!",
          VoiceName = "voice/$Locale$/story/1002/101314/195BD067"
        },
        [10131402] = {
          ContentFR = "On dirait presque qu’elles avaient été soigneusement cachées là, comme de précieux trésors...",
          DialogueId = 10131402,
          GUID = "195BD068",
          NextDialogue = 10131403,
          SpeakNpcId = 200006,
          Subtitle = "They seem to have been carefully hidden away like cherished treasures...",
          VoiceName = "voice/$Locale$/story/1002/101314/195BD068"
        },
        [10131403] = {
          ContentFR = "Hé hé, Psyche, tu cacherais pas toi aussi des trésors quelque part ?",
          DialogueId = 10131403,
          GUID = "195BD069",
          NextDialogue = 10131404,
          SpeakNpcId = 200002,
          Subtitle = "Heh heh, could you be hiding some treasures too, Psyche?",
          VoiceName = "voice/$Locale$/story/1002/101314/195BD069"
        },
        [10131404] = {
          ContentFR = "Hé hé... c’est un secret.",
          DialogueId = 10131404,
          GUID = "195BD070",
          SpeakNpcId = 200006,
