        [11010209] = {
          ContentFR = "<I>– Tais-toi ! Ce n’est pas ce que je ressens !</>",
          DialogueId = 11010209,
          GUID = "1B901A6A",
          NextDialogue = 11010210,
          Subtitle = "(Shut up! That was not how I felt!)"
