        },
        [11010216] = {
          ContentFR = "Je ferais mieux de vérifier ce qui est arrivé aux autres.",
          DialogueId = 11010216,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B901B90",
          SpeakNpcId = 110022,
          Subtitle = "I should go check on the others.",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901B90"
        },
        [11010221] = {
          ContentFR = "Hfff... Docteur Daphne, on peut considérer notre mission terminée, non ? ",
          DialogueId = 11010221,
          Duration = 3,
          GUID = "1B901C62",
          SpeakNpcId = 110019,
          Subtitle = "Hssss... Dr Daphne, we've completed our mission, right?",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901C62"
        },
        [11010222] = {
          ContentFR = "... Non, tant qu’on ne rentre pas vivant, la mission n’est pas finie !",
          DialogueId = 11010222,
          Duration = 3,
          GUID = "1B901C8C",
          SpeakNpcId = 110005,
          Subtitle = "...No, not until when we get back alive.",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901C8C"
        },
        [11010223] = {
          ContentFR = "Ça va, Daphne. Calme-toi... ça va aller, respire...",
          DialogueId = 11010223,
          Duration = 3,
          GUID = "1B901CB6",
          SpeakNpcId = 110005,
          Subtitle = "It's alright, Daphne. Calm down. Everything's going to be okay. Calm down.",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901CB6"
        },
        [11010224] = {
          ContentFR = "Ah ! Vous êtes revenu !",
          DialogueId = 11010224,
          Duration = 3,
          GUID = "1B901CE0",
          SpeakNpcId = 110005,
          Subtitle = "You're back!",
          VoiceName = "voice/$Locale$/story/1002/110102/1B901CE0"
        },
        [11010225] = {
          ContentFR = "... Vite, réveille-toi ! Si ça continue, tu vas mourir !",
          DialogueId = 11010225,
          Duration = 3,
          GUID = "1B90191A",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Wake up!! Or you'll die!",
          VoiceName = "voice/$Locale$/story/1002/110102/1B90191A"
        },
        [11010226] = {
          ContentFR = "Capitaine !",
          DialogueId = 11010226,
          Duration = 3,
          GUID = "1B901944",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
