        },
        [11010901] = {
          ContentFR = "Des Souillés !",
          DialogueId = 11010901,
          Duration = 3,
          GUID = "1B908BF2",
          SpeakNpcId = 110005,
          Subtitle = "Filthoids!",
          VoiceName = "voice/$Locale$/story/1002/110109/1B908BF2"
        },
        [11010902] = {
          ContentFR = "Daphne, protégez les blessés.",
          DialogueId = 11010902,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B908C1C",
          SpeakNpcId = 110022,
          Subtitle = "Daphne, protect the wounded.",
          VoiceName = "voice/$Locale$/story/1002/110109/1B908C1C"
        },
        [11010903] = {
          ContentFR = "Oui, Capitaine !",
          DialogueId = 11010903,
          Duration = 3,
          GUID = "1B908C46",
          SpeakNpcId = 110005,
          Subtitle = "Yes, Captain!",
          VoiceName = "voice/$Locale$/story/1002/110109/1B908C46"
        },
        [11011001] = {
          ContentFR = "Tenez bon ! J’essaie encore de contacter les Loups Blancs !",
          DialogueId = 11011001,
          Duration = 3,
          GUID = "1B909C5A",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 11011002,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"},RelatedRegionId{102101}}",
          SnapShot = "OUTDOOR",
          SpeakNpcId = 110005,
          Subtitle = "Hang in there, I'll try contacting the Snow Wolves!",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909C5A"
        },
        [11011002] = {
          ContentFR = "Rien... toujours aucun retour...",
          DialogueId = 11011002,
          Duration = 3,
          GUID = "1B909C84",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 11011003,
          SnapShot = "OUTDOOR",
          SpeakNpcId = 110005,
          Subtitle = "Still... got nothing...",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909C84"
        },
        [11011003] = {
          ContentFR = "Allô ? Vous me recevez ?",
          DialogueId = 11011003,
          Duration = 3,
          GUID = "1B909CAE",
          NextDialogue = 11011004,
          Scripts = "PlayNormalSound{EventPath{\"event:/snapshot/story/ex01_vo_behind_door\"},PlayAs2D{true}}",
          SnapShot = "OUTDOOR",
          SpeakNpcId = 110010,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Copy? Do you copy?",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909CAE"
        },
        [11011004] = {
          ContentFR = "La liaison... enfin !",
          DialogueId = 11011004,
          Duration = 3,
          GUID = "1B909CD8",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 11011005,
          SnapShot = "OUTDOOR",
          SpeakNpcId = 110005,
          Subtitle = "We've got a response...!",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909CD8"
        },
        [11011005] = {
          ContentFR = "<H>Quel temps fait-il aujourd’hui en Hyperborea ?</>",
          DialogueId = 11011005,
          Duration = 3,
          GUID = "1B909D02",
          NextDialogue = 11011006,
          SnapShot = "OUTDOOR",
          SpeakNpcId = 110010,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "What's the weather like in Hyperborea today?",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909D02"
        },
        [11011006] = {
          ContentFR = "<H>Il pleut ce soir sur Dismania.</>",
          DialogueId = 11011006,
          Duration = 3,
          GUID = "1B909D2C",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 11011007,
          SnapShot = "OUTDOOR",
          SpeakNpcId = 110005,
          Subtitle = "It's raining tonight in Dismania.",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909D2C"
        },
        [11011007] = {
          ContentFR = "Ici le lieutenant-colonel Avar Hrodland. Des Griffons, donnez votre position.",
          DialogueId = 11011007,
