        [11011331] = {
          Camera = "6.71582,-172.675781,139.699112,0.000306,0.19813,66.419029,35.000015,178.050125,false,Manual,22.0",
          ContentFR = "<I>Hum.</> Ce {性别2:qu’il|qu’elle} veut dire, c’est que Simon est blessé, mais vivant. Il se repose à un poste de secours, sous la surveillance des médecins. Ne vous inquiétez pas.",
          DialogueId = 11011331,
          FacialId = {
            [1] = "110010:Unhappy01"
          },
          GUID = "1B90D27E",
          NextDialogue = 11011332,
          SpeakNpcId = 110010,
          Subtitle = "Ahem, he means Simon's got some injuries, but the medic is taking care of him in a temporary shelter. There's no need to worry about him.",
          VoiceName = "voice/$Locale$/story/1002/110113/1B90D27E"
        },
        [11011332] = {
          ContentFR = "Je comprends. Merci, mon commandant.",
          DialogueId = 11011332,
          DialoguePanelType = "{type:Guide;style:Communicator}",
