        [11012435] = {
          Camera = "24.656494,7.404297,190.805542,-0.002769,-61.608364,102.005478,15.610328,100000.0,false,Manual,22.0",
          ContentFR = "W>Ta tête te fait mal, pas vrai ? Écoute... Les paroles de cette folle grouillent dans ton crâne comme des sangsues affamées, rongeant ton crâne, suçotant ta cervelle.</>",
          DialogueId = 11012435,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "0.038208,11.194824,204.206421,-5.00001,-64.807861,70.004921,15.610328,100000.0,false,Manual,22.0",
          GUID = "1B91879E",
          NextDialogue = 11012436,
          Scripts = [[
PARA{PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/evilvo"},PlayAs2D{true}},
PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'"}}
}]],
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Your head hurts, right? The jabbering of this mad girl is worming through your skull like a leech sucking at your brains.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110124/1B91879E"
        },
        [11012436] = {
          Camera = "36.141357,29.718262,149.925659,-0.002777,-12.206906,146.405396,15.610331,100000.0,false,Manual,22.0",
          ContentFR = "<W>Regarde. Dans ta main, ton épée... oui, ta fidèle lame. La garde est encore tiède de ta paume. Tu connais par cœur la sensation, la chair qui cède, la résistance infime quand l’acier s’enfonce.</>",
          DialogueId = 11012436,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "19.049377,14.672852,139.228333,-0.002778,11.392994,99.206146,15.610331,100000.0,false,Manual,22.0",
          GUID = "1B9187C8",
          NextDialogue = 11012437,
          Scripts = [[
PARA{PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/evilvo"},PlayAs2D{true}},
PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'"}}
}]],
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "See, you have a sword in your hand. That's right — it's the one you've wielded in countless battles. The hilt still carries your warmth. You're familiar with the slick feeling and the subtle tug of resistance when its blade slices through flesh.",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1002/110124/1B9187C8"
        },
        [11012437] = {
          Camera = "21.503967,-78.260254,143.286499,-10.000029,-24.608084,-64.792946,15.610331,100000.0,false,Manual,22.0",
          ContentFR = "<W>Un geste, et tu pourrais lui trancher la gorge. Sa bouche immonde ne vomirait plus que des gargouillis de douleur.</>",
          DialogueId = 11012437,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "36.730774,-74.067871,146.035278,-10.002868,-12.007807,-82.793266,15.610331,100000.0,false,Manual,22.0",
          GUID = "1B9187F2",
          NextDialogue = 11012438,
          Scripts = [[
PARA{PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/evilvo"},PlayAs2D{true}},
PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'"}}
}]],
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "You can easily slit this creature's throat and make its detestable lips gurgle and whimper in pain.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110124/1B9187F2"
        },
        [11012438] = {
          Camera = "12.627441,-61.455566,63.949219,-24.997759,29.588535,90.003098,15.610331,100000.0,false,Manual,22.0",
          ContentFR = "<I>Encore... cette voix ! Pourquoi maintenant...</>",
          DialogueId = 11012438,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Pain01"
          },
