          NextDialogue = 11012447,
          Scripts = "PostProcess{MaterailInstance{\"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'\"}}",
          SpeakNpcId = 110009,
          Subtitle = "Go on, make your guess — any guess would do, because I won't tell you the truth anyway!",
          TalkActionId = {
