          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "<W>Ne tergiverse plus ! Ton épée t’appelle ! Elle réclame la douce ivresse que seule la chair et le sang peuvent lui offrir.</>",
          DialogueId = 11012447,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "17.73999,15.974609,99.406067,-0.002779,-48.007011,-78.395638,15.610328,100000.0,false,Manual,22.0",
          GUID = "1B918996",
          NextDialogue = 11012448,
          Scripts = [[
