PostProcess{MaterailInstance{"MaterialInstanceConstant'/Game/Asset/Scene/common/PP/MI_PP_Demon_01.MI_PP_Demon_01'"}}
}]],
          SnapShot = "MONSTER",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Do not hesitate! Use your sword! It's calling to you! It thirsts for the sweet joy that can only be sated by flesh and blood.",
