          Duration = 3,
          GUID = "1B918D32",
          SpeakNpcId = 110009,
          Subtitle = "But I'm just a poor little captive now, not in the mood to talk.",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918D32"
        },
        [11012501] = {
          ContentFR = "<W>Oui... c’est bien... serre fort la garde de ton épée. Voilà, comme ça. Maintenant, vise sa gorge...</>",
