          VoiceName = "voice/$Locale$/story/1002/110127/1B91B3EA"
        },
        [11012706] = {
          ContentFR = "Soldats de la XIIIᵉ Légion ! Devant nous se trouve la salle de commande centrale de la Forteresse de Lonza, l’objectif final de cette mission... et l’occasion d’apporter gloire à Hyperborea.",
          DialogueId = 11012706,
          Duration = 3,
          GUID = "1B91B414",
          LookAt = {
            [1] = "110010:n(110015)"
          },
          NextDialogue = 11012707,
          Scripts = [[
PARA{
LookAt{_delay{9},LookAtDescription{"110010:n(110010)"},duration{5}},
SEQ{
CameraMoveTo{_delay{5},TargetPosition{"-56.254089,-809.466797,-42.738403,0.000177,9.001827,84.490524,35.000008,579.363892,false,DoNotOverride,5.0"},duration{0}},
CameraMoveTo{TargetPosition{"-68.660049,-808.27002,-42.991699,0.000177,9.001827,84.490524,35.000008,579.363892,false,DoNotOverride,5.0"},duration{8}}
}}
]],
          SpeakNpcId = 110010,
          Subtitle = "Soldiers of the 13th Legion! Before us lies the central control room of Lonza Fortress, the ultimate goal of this mission. This is our chance to claim glory for Hyperborea.",
          TalkActionId = {
            [1] = "110010:Think_End",
            [2] = "110022:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B414"
        },
        [11012707] = {
          Camera = "36.30703,124.842285,141.383301,0.000053,-12.199592,84.602554,55.000011,817.298035,false,DoNotOverride,2.8",
          ContentFR = "Mais désolé, je ne vous laisserai pas le plus grand mérite.",
          DialogueId = 11012707,
          Duration = 3,
          GUID = "1B91B43E",
          NextDialogue = 11012708,
          SpeakNpcId = 110010,
          Subtitle = "However, I must apologize, as I won't be giving you the lion's share of this victory.",
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B43E"
        },
        [11012708] = {
          Camera = "61.15564,453.617188,198.150452,0.000026,-19.79916,-92.999207,30.0,344.311523,false,DoNotOverride,6.0",
          ContentFR = "... Hein ?",
          DialogueId = 11012708,
          Duration = 6,
          FinalCamera = "70.893509,639.473633,265.152496,0.000026,-19.79916,-92.999207,30.0,344.311523,false,DoNotOverride,6.0",
          GUID = "1B91B468",
          LookAt = {
            [1] = "110015:n(110010)"
          },
          NextDialogue = 11012709,
          SpeakNpcId = 110015,
          Subtitle = "...Huh?",
          ToFinalCameraBlendTime = 0.2,
          TurnTo = {
            [1] = "110015:n(110010)"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B468"
        },
        [11012709] = {
          Camera = "36.496845,123.416016,88.121643,0.0,13.999503,86.565399,35.000008,817.298035,false,DoNotOverride,2.8",
          ContentFR = "Dans cette opération, gloire et danger vont de pair, mais le danger est toujours plus grand.",
          DialogueId = 11012709,
          Duration = 3,
          FinalCamera = "37.052647,132.677246,90.414429,0.0,13.999503,86.565399,35.000008,817.298035,false,DoNotOverride,2.8",
          GUID = "1B91B492",
          LookAt = {
            [1] = "110010:n(110010)"
          },
          NextDialogue = 11012710,
          SpeakNpcId = 110010,
          Subtitle = "With glory comes great danger, and this action is more dangerous than ever.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B492"
        },
        [11012710] = {
          Camera = "-12.165825,-818.205078,237.788666,0.000159,-10.198333,88.291573,35.0,579.363892,false,DoNotOverride,5.0",
          ContentFR = "Vous êtes jeunes, la route est encore longue, et vous aurez de nombreuses occasions de briller. Alors ce mérite, je ne vous le laisserai pas. Laissez-moi décrocher cette médaille.",
          DialogueId = 11012710,
          Duration = 3,
          FinalCamera = "-27.306183,-817.759277,237.788666,0.000159,-10.198333,88.291573,35.0,579.363892,false,DoNotOverride,5.0",
          GUID = "1B91B4BC",
          LookAt = {
            [1] = "110010:n(110020)"
          },
          NextDialogue = 11012711,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{10},TargetPosition{"-49.806252,74.208496,38.168884,-3.000001,19.199593,63.080681,30.000008,138.022522,false,Manual,8.0"},duration{0}},
CameraMoveTo{TargetPosition{"-45.084969,94.379395,45.618835,-3.0,19.59967,60.480312,30.000008,138.022522,false,Manual,8.0"},duration{8}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "You're young, with many years ahead. There will be other opportunities for glory. But today, the old man here will seek one more medal, and he isn't keen on sharing it with any of you.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B4BC"
        },
        [11012711] = {
          Camera = "-791.496155,210.537109,527.647827,0.0002,-28.798002,-13.499554,30.000002,517.956055,false,DoNotOverride,2.8",
          ContentFR = "Restez à la tourelle. Si vous perdez le contact avec moi, continuez à bombarder la salle de commande, mais ne vous exposez pas inutilement. Attendez les renforts.",
          DialogueId = 11012711,
          Duration = 3,
          FinalCamera = "-775.113831,278.776367,527.647827,0.0002,-28.798002,-13.499554,30.000002,517.956055,false,DoNotOverride,2.8",
          GUID = "1B91B4E6",
          NextDialogue = 11012712,
          SpeakNpcId = 110010,
          Subtitle = "Stay at your posts by the turret. If you lose contact with me, continue to shell the control room from a distance and wait for reinforcements. Do not assault it directly.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B4E6"
        },
        [11012712] = {
          Camera = "4.667221,273.677246,128.522583,0.000149,-7.797876,-58.891384,35.0,280.465454,false,DoNotOverride,5.0",
          ContentFR = "Commandant Avar, vous n’y arriverez pas seul... Je sais que vous ne pensiez pas ce que vous venez de dire.",
          DialogueId = 11012712,
          Duration = 3,
          GUID = "1B91B510",
          LookAt = {
            [1] = "110016:n(110010)"
          },
          NextDialogue = 11012713,
          SpeakNpcId = 110016,
          Subtitle = "Commander Avar, you can't do this alone... I know you didn't mean what you just said.",
          TalkActionId = {
            [1] = "110016:Talk01_Start"
          },
          TurnTo = {
            [1] = "110016:n(110010)"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B510"
        },
        [11012713] = {
          Camera = "131.189819,-166.486328,116.257446,0.000163,-1.198357,98.096161,60.000004,380.104767,false,DoNotOverride,2.8",
          ContentFR = "De quoi parles-tu ? Ce sont mes ordres.",
          DialogueId = 11012713,
          Duration = 3,
          GUID = "1B91B53A",
          LookAt = {
            [1] = "110010:n(110016)"
          },
          NextDialogue = 11012714,
          SpeakNpcId = 110010,
          Subtitle = "What are you talking about? I just simply gave you orders.",
          TalkActionId = {
            [1] = "110010:Talk03_Start"
          },
          TurnTo = {
            [1] = "110022:n(110016)"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B53A"
        },
        [11012714] = {
          Camera = "1154.470581,-1654.519531,133.795654,0.000014,-1.999872,117.791336,50.0,361.840546,false,Manual,3.5",
          ContentFR = "Tss... fais le malin.",
          DialogueId = 11012714,
          Duration = 3,
          GUID = "1B91B564",
          NextDialogue = 11012715,
          Scripts = "PlayAnimation{_delay{2},ActorId{110009},AnimationId{\"Talk03_Start\"},Duration{1}}",
          SpeakNpcId = 110009,
          Subtitle = "Tsk, pretentious old geezer.",
          TalkActionId = {
            [1] = "110016:Talk01_End"
          },
          TurnTo = {
            [1] = "110009:p(90)"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B564"
        },
        [11012715] = {
          Camera = "129.785309,-187.855957,83.321777,0.000001,2.199894,107.199677,35.0,406.942047,false,Manual,2.8",
          ContentFR = "Je comprends vos inquiétudes, mais j’ai vécu beaucoup de situations similaires. J’étais autrefois comme vous, jeune et larmoyant, pensant que mon commandant avait des envies suicidaires.",
          DialogueId = 11012715,
          Duration = 3,
          FinalCamera = "121.234055,-190.50293,83.321777,0.000001,2.199894,107.199677,35.0,406.942047,false,Manual,2.8",
          GUID = "1B91B58E",
          NextDialogue = 11012716,
          Scripts = [[
PARA{
PlayAnimation{_delay{3},ActorId{110010},AnimationId{"Confident_End"},Duration{3}},
LookAt{_delay{5},LookAtDescription{"110010:n(110015)"},duration{5}},
PlayAnimation{_delay{8},ActorId{110010},AnimationId{"Talk01_Start"},Duration{3}},
LookAt{_delay{9},LookAtDescription{"110010:n(110020)"},duration{5}},
SEQ{
CameraMoveTo{_delay{9},TargetPosition{"68.149689,606.824707,269.340637,0.000024,-22.399134,-92.588158,25.000002,847.801208,false,DoNotOverride,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"56.547432,607.355469,269.340637,0.000025,-22.399134,-92.588173,25.000006,847.801208,false,DoNotOverride,2.8"},duration{8}}
}}]],
          SpeakNpcId = 110010,
          Subtitle = "I understand your concerns, but I've been through a lot things like this. I was once like you, young and tearful, thinking my commanding officer had a death wish.",
          TalkActionId = {
            [1] = "110010:Confident_Start",
            [2] = "110022:Talk03_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B58E"
        },
        [11012716] = {
          Camera = "99.497269,128.321777,127.789551,0.000096,-7.798484,120.205383,30.0,847.801208,false,DoNotOverride,2.8",
          ContentFR = "Mais il revenait toujours sain et sauf. Alors ne vous inquiétez pas. Pensez à vos mères, probablement près du feu, tricotant un pull, attendant votre retour.",
          DialogueId = 11012716,
          Duration = 3,
          FinalCamera = "93.344849,138.890625,126.369141,0.000097,-7.798484,120.205383,30.0,847.801208,false,DoNotOverride,2.8",
          GUID = "1B91B5B8",
          LookAt = {
            [1] = "110020:n(110010)"
          },
          NextDialogue = 11012717,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8},TargetPosition{"181.160461,469.915527,106.445618,0.000085,-3.998837,-110.197327,30.0,847.801208,false,DoNotOverride,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"193.050568,465.540527,106.445618,0.000085,-3.998837,-110.197327,30.0,847.801208,false,DoNotOverride,2.8"},duration{8}}
}
]],
          SpeakNpcId = 110010,
          Subtitle = "But he always returned safely. So I'm telling you that there's no need to worry. Think of your mother, probably by the fireplace knitting a sweater, waiting for you to come home.",
          TalkActionId = {
            [1] = "110010:Talk01_End"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "110020:n(110010)"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B5B8"
        },
        [11012717] = {
          Camera = "57.001575,280.910156,125.013489,0.000079,-7.598968,-87.998039,40.0,847.801208,false,DoNotOverride,2.8",
          ContentFR = "Commandant, vous avez toujours veillé sur moi, et vous venez de me sauver la vie. Même si ma mère était ici, elle dirait : « Suis ton commandant, ne crains pas la mort. Tu es un guerrier hyperboréen et tu es censé défendre l’Empire au péril de ta vie. »",
          DialogueId = 11012717,
          Duration = 3,
          GUID = "1B91B5E2",
          NextDialogue = 11012718,
          Scripts = "CameraMoveTo{_delay{7},TargetPosition{\"77.976013,62.661133,89.001038,0.000089,1.400619,-94.583221,70.0,559.908325,false,DoNotOverride,12.0\"},duration{0}}",
          SpeakNpcId = 110020,
          Subtitle = "Commander Avar, you've always looked out for me, and you just saved my life. Even if my mother were here, she would say, \"Follow your officer, do not fear death. You're a Hyperborean warrior and you're supposed to defend the Empire with your life.\"",
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B5E2"
        },
        [11012718] = {
          Camera = "93.908615,56.692871,81.890564,0.0,10.799786,107.816833,70.000015,559.908325,false,DoNotOverride,12.0",
          ContentFR = "Il ne s’agit pas de craindre la mort. Je ne veux simplement pas que des vies soient perdues en vain.",
          DialogueId = 11012718,
          Duration = 3,
          GUID = "1B91B60C",
          NextDialogue = 11012719,
          SpeakNpcId = 110010,
          Subtitle = "It's not about fearing death. I just don't want any lives lost in vain.",
          TalkActionId = {
            [1] = "110022:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B60C"
        },
        [11012719] = {
          Camera = "313.871033,357.636719,159.137878,0.000087,-8.999512,-150.398483,70.000015,501.809082,false,DoNotOverride,5.0",
          ContentFR = "Elle ne sera pas inutile. Chaque pas en avant fait avancer notre ligne.",
          DialogueId = 11012719,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91B636",
          NextDialogue = 11012720,
          Scripts = [[
PARA{
LookAt{_delay{1},LookAtDescription{"110010:n(110022)"},duration{1}},
PlayAnimation{_delay{2},ActorId{110022},AnimationId{"Explain01_Start"},Duration{1}}
}]],
          SpeakNpcId = 110022,
          Subtitle = "It won't be in vain. Every step we take pushes the frontline forward.",
          TurnTo = {
            [1] = "110022:n(110010)"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B636"
        },
        [11012720] = {
          Camera = "109.233757,251.400879,166.836914,0.000057,-18.199524,-142.201279,70.0,501.809082,false,DoNotOverride,5.0",
          ContentFR = "Et puisqu’on ignore ce qu’il y a devant nous, alors survivre reste une possibilité.",
          DialogueId = 11012720,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "97.862839,242.581543,163.439758,0.000057,-18.199524,-142.201279,70.0,501.809082,false,DoNotOverride,5.0",
          GUID = "1B91B660",
          NextDialogue = 11012721,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"110022:n(110016)"},duration{4}},
LookAt{LookAtDescription{"110022:n(110010)"}}
}]],
          SpeakNpcId = 110022,
          Subtitle = "And since we don't know what lies before us, it means that survival is also a possibility.",
          TalkActionId = {
            [1] = "110022:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B660"
        },
        [11012721] = {
          Camera = "-73.181671,-68.665527,108.543274,0.000075,-0.19992,17.39048,55.000008,211.021881,false,DoNotOverride,2.8",
          ContentFR = "Je fais partie des Griffons et je me range derrière {性别2:le|la} Capitaine {nickname2}.",
          DialogueId = 11012721,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91B68A",
          NextDialogue = 11012722,
          SpeakNpcId = 110016,
          Subtitle = "I'm a Griffin and I stand with Captain .",
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B68A"
        },
        [11012722] = {
          Camera = "297.05957,-251.103027,69.405334,0.000077,3.999868,153.994812,55.000008,847.801147,false,DoNotOverride,2.8",
          ContentFR = "Bien reçu ! Moi aussi je me range derrière {性别2:le|la} Capitaine {nickname2} !",
          DialogueId = 11012722,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91B6B4",
          NextDialogue = 11012723,
          SpeakNpcId = 110015,
          Subtitle = "Yeah! I heard that loud and clear this time! I stand with Captain !",
          TurnTo = {
            [1] = "110016:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B6B4"
        },
        [11012723] = {
