        [11012724] = {
          Camera = "126.617424,279.261719,136.483887,0.000116,-9.399658,-142.796799,55.0,217.025711,false,Manual,10.0",
          ContentFR = "... Bien, avec {nickname2} et sa puissance, la victoire n’est peut-être pas impossible.",
          DialogueId = 11012724,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91B708",
          LookAt = {
