          VoiceName = "voice/$Locale$/story/1002/110127/1B91B732"
        },
        [11012726] = {
          Camera = "-63.863312,-10.899902,107.139404,0.000003,-2.600307,74.596085,35.0,306.210999,false,DoNotOverride,2.8",
          ContentFR = "Eh bien... tu as même appris à couper la parole de ton commandant.",
          DialogueId = 11012726,
          Duration = 3,
          GUID = "1B91B75C",
          NextDialogue = 11012727,
          SpeakNpcId = 110010,
          Subtitle = "Heh, you've even learned how to take over your commander's speech.",
          TalkActionId = {
            [1] = "110010:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B75C"
        },
        [11012727] = {
          Camera = "-50.857063,330.249512,125.597046,0.000164,-5.998163,-55.303593,40.0,517.956055,false,DoNotOverride,2.8",
          ContentFR = "On pourrait peut-être attendre un peu pour recueillir plus d'informations auprès de cette fille d’abord...",
          DialogueId = 11012727,
          Duration = 3,
          FinalCamera = "-40.529282,315.225098,133.052124,0.000164,-5.998163,-55.90337,40.0,517.956055,false,DoNotOverride,2.8",
          GUID = "1B91B786",
          LookAt = {
            [1] = "110010:n(110009)"
          },
          NextDialogue = 11012728,
          SpeakNpcId = 110016,
          Subtitle = "Maybe we could wait for a while to gather more intel from this lass first—",
          TalkActionId = {
            [1] = "110016:Explain01_Start",
            [2] = "110010:Talk03_End"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "110016:n(110010)"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B786"
        },
        [11012728] = {
          Camera = "945.344116,-1229.479492,133.784607,18.00058,3.599988,-54.103123,40.0,517.956055,false,DoNotOverride,2.8",
          ContentFR = "Hein ? Vous comptez m’interroger encore ?",
          DialogueId = 11012728,
          Duration = 3,
          FinalCamera = "947.904724,-1227.703125,128.575073,18.001308,3.599988,-54.103092,40.000011,517.956055,false,DoNotOverride,2.8",
          GUID = "1B91B7B0",
          LookAt = {
            [1] = "110009:n(110010)"
          },
          NextDialogue = 11012729,
          SpeakNpcId = 110009,
          Subtitle = "Oh? Are you going to interrogate me?",
          TalkActionId = {
            [1] = "110022:Explain01_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B7B0"
        },
        [11012729] = {
          Camera = "118.784447,-241.756836,89.649658,0.000005,-0.800109,96.800201,40.0,306.210999,false,DoNotOverride,2.8",
          ContentFR = "Non. On a vu combien elle est rusée. Ses informations ne feraient que brouiller notre jugement.",
          DialogueId = 11012729,
          Duration = 3,
          GUID = "1B91B7DA",
          NextDialogue = 11012730,
          SpeakNpcId = 110010,
          Subtitle = "No. I've seen how crafty this girl is. Her \"intel\" will only mess with our judgment.",
          TalkActionId = {
            [1] = "110010:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B7DA"
        },
        [11012730] = {
          Camera = "-789.535461,-296.212402,464.083984,0.000203,-23.79784,22.699654,30.0,517.956055,false,DoNotOverride,2.8",
          ContentFR = "Voici le plan : on se sépare en deux groupes. {nickname2} et moi partons en reconnaissance. Les autres se préparent et attaquent sur signal. Si on recule, retournez à la tourelle 4. Leon, tu restes en arrière pour surveiller les prisonniers.",
          DialogueId = 11012730,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-781.463074,-320.651367,464.959229,0.000203,-23.79784,22.699654,30.0,517.956055,false,DoNotOverride,2.8",
          GUID = "1B91B804",
          NextDialogue = 11012731,
          Scripts = "CameraMoveTo{_delay{12},TargetPosition{\"-17.339386,56.376953,117.153992,0.000212,-6.797513,-111.697014,30.0,162.966705,false,Manual,2.8\"},duration{0}}",
          SpeakNpcId = 110010,
          Subtitle = "Here's the plan: we split into two groups.  and I will scout ahead. The rest prepare and initiate the assault upon our signal. If we call it off, retreat to Turret 4. Leon, you stay back and guard the captives.",
          TalkActionId = {
            [1] = "110010:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B804"
        },
        [11012731] = {
          Camera = "-98.234558,-1429.317871,556.726807,0.999999,-18.052231,84.232918,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui, commandant !",
          DialogueId = 11012731,
          Duration = 3,
          GUID = "1B91B82E",
          NextDialogue = 11012732,
          SpeakNpcName = "UI_Npc_All",
          Subtitle = "Yes, sir!",
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B82E"
        },
        [11012732] = {
          Camera = "-256.189758,59.020996,94.610657,0.000061,0.40014,23.996672,45.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Allons-y. Voyons quelles surprises Les Déchus nous ont préparées.",
          DialogueId = 11012732,
          Duration = 3,
          GUID = "1B91B858",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          Scripts = "TurnTo{TurnToDescription{\"110010:p(-90)\"}}\n",
          SpeakNpcId = 110010,
          Subtitle = "Let's move, and see what surprises The Forsakens have prepared for us.",
          TalkActionId = {
            [1] = "110010:Explain01_End",
            [2] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110127/1B91B858"
        },
        [11012801] = {
          Camera = "-28.373993,232.864197,143.277283,0.000001,-0.799959,-78.595703,40.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vous êtes blessé, ça va ?",
          DialogueId = 11012801,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-30.631805,244.058456,143.436707,0.000001,-0.799959,-78.59536,40.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91C3AA",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11012802,
          SpeakNpcId = 110022,
          Subtitle = "You're injured, are you alright?",
          TalkActionId = {
            [1] = "110022:Explain01_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C3AA"
        },
        [11012802] = {
          Camera = "188.697754,-74.170662,131.45105,0.0,0.200022,129.200867,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une égratignure, rien de plus. Avec un peu de repos, ça ira. Cette gamine faisait semblant d’être menaçante, un chat de gouttière se serait mieux défendu.",
          DialogueId = 11012802,
          Duration = 3,
          FinalCamera = "162.229492,-95.300224,131.45105,-0.0,-0.199947,123.201126,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91C3D4",
          NextDialogue = 11012803,
          Scripts = "SEQ{PlayAnimation{ActorId{110010},AnimationId{\"Talk03_Start\"},Duration{3}},PlayAnimation{ActorId{110010},AnimationId{\"Talk03_End\"},Duration{1}}}",
          SpeakNpcId = 110010,
          Subtitle = "Just a scratch; it'll heal soon. That little girl was just bluffing. Even a stray cat would've put up a better fight.",
          TalkActionId = {
            [1] = "110022:Explain01_End"
          },
          ToFinalCameraBlendTime = 7,
          TurnTo = {
            [1] = "110010:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C3D4"
        },
        [11012803] = {
          Camera = "-27.459442,206.711151,132.750061,0.000008,12.399866,105.204865,35.000015,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mince... où est-ce que je l’ai mise... Je l’avais laissée ici pourtant...",
          DialogueId = 11012803,
          Duration = 3,
          FinalCamera = "-25.208466,200.122574,131.222473,0.000008,12.399866,105.204865,35.000015,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91C3FE",
          NextDialogue = 11012804,
          SpeakNpcId = 110010,
          Subtitle = "Ugh, where did it go? I thought I had it right here...",
          TalkActionId = {
            [1] = "110010:Think_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C3FE"
        },
        [11012804] = {
          Camera = "-40.992615,407.549622,173.946289,0.000029,-9.399583,-88.996246,40.000011,313.388489,false,Manual,5.0",
          ContentFR = "Vous avez perdu quelque chose ?",
          DialogueId = 11012804,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-36.485291,407.628601,173.946289,0.000029,-9.399583,-88.996254,40.000011,313.388489,false,Manual,5.0",
          GUID = "1B91C428",
          NextDialogue = 11012805,
          SpeakNpcId = 110022,
          Subtitle = "Lost something important?",
          TalkActionId = {
            [1] = "110010:Think_End",
            [2] = "110022:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C428"
        },
        [11012805] = {
          Camera = "-21.258774,236.389862,150.315674,0.00003,6.399894,112.800598,35.000023,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas grand-chose. Juste une photo. File donc interroger cette femme, elle avait plutôt l’air de s’intéresser à toi.",
          DialogueId = 11012805,
          Duration = 3,
          FinalCamera = "-18.376434,229.534744,148.295166,0.00003,6.399894,112.800598,35.000023,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91C452",
          NextDialogue = 11012806,
          SpeakNpcId = 110010,
          Subtitle = "Just a mere photo. Why don't you go interrogate that girl? She seems to be after you.",
          TalkActionId = {
            [1] = "110010:DisagreeHead",
            [2] = "110022:Talk02_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C452"
        },
        [11012806] = {
          Camera = "-28.373978,232.86409,146.405701,0.000001,-1.199982,-76.594246,40.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "<I>Une photo ? Je devrais peut-être la chercher quand j’aurai le temps.</>",
          DialogueId = 11012806,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-28.373978,232.86409,145.438354,0.000001,-1.199982,-76.593987,40.000023,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91C47C",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(A photo? Maybe I should have a look around for it when I can.)",
          TalkActionId = {
            [1] = "110022:Think_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C47C"
        },
        [11012807] = {
          ContentFR = "Où est-ce qu’elle a bien pu tomber... ?",
          DialogueId = 11012807,
          Duration = 3,
          GUID = "1B91C4A6",
          NextDialogue = 11012808,
          SpeakNpcId = 110010,
          Subtitle = "Where could it be...?",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C4A6"
        },
        [11012808] = {
          ContentFR = "Hein ? Ce truc par terre, ce ne serait pas... ?",
          DialogueId = 11012808,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C4D0",
          SpeakNpcId = 110022,
          Subtitle = "Hmm? What's that on the floor...?",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C4D0"
        },
        [11012809] = {
          ContentFR = "C’est le Commandant Avar plus jeune avec... Daphne ?",
          DialogueId = 11012809,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Ex01_Pic.T_Guide_Ex01_Pic'}",
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C4FA",
          NextDialogue = 11012810,
          SpeakNpcId = 110022,
          Subtitle = "It's a younger Sir Avar with… Daphne?",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C4FA"
        },
        [11012810] = {
          ContentFR = "Il faut que je rende cette photo au Commandant Avar.",
          DialogueId = 11012810,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C524",
          SpeakNpcId = 110022,
          Subtitle = "I should take it back to Sir Avar.",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C524"
        },
        [11012811] = {
          Camera = "-265.872223,895.02594,147.338562,0.0,-4.599914,-87.177261,40.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Tenez, je viens de trouver ceci...",
          DialogueId = 11012811,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C54E",
          LookAt = {
            [1] = "110022:n(110010)"
          },
          NextDialogue = 11012812,
          SpeakNpcId = 110022,
          Subtitle = "Sir, I found this...",
          TalkActionId = {
            [1] = "110022:Give"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C54E"
        },
        [11012812] = {
          Camera = "-328.606415,569.80426,140.777832,0.000147,1.196164,62.629292,45.000027,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Oh ! Tu l’as retrouvée, merci.",
          DialogueId = 11012812,
          Duration = 0,
          GUID = "1B91C578",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11012813,
          SpeakNpcId = 110010,
          Subtitle = "Oh, you found it! Thanks for bringing it back.",
          TalkActionId = {
            [1] = "110010:AgreeHead"
          },
          TurnTo = {
            [1] = "110010:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C578"
        },
        [11012813] = {
          Camera = "-260.496735,740.469788,158.7724,0.0,-7.403351,-102.964378,45.000023,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Alors... Daphne, c’est... votre... ?",
          DialogueId = 11012813,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C5A2",
          NextDialogue = 11012814,
          SpeakNpcId = 110022,
          Subtitle = "So, is Daphne your...",
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C5A2"
        },
        [11012814] = {
          Camera = "-338.607697,582.601135,144.446533,0.00001,-0.600339,55.421577,30.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Ah, oh... c’est juste la petite fille du voisin, haha...",
          DialogueId = 11012814,
          Duration = 0,
          GUID = "1B91C5CC",
          NextDialogue = 11012815,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{110010},AnimationId{"Talk01_Start"},Duration{3}},
PlayAnimation{ActorId{110010},AnimationId{"Talk01_End"},Duration{2}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "Oh, ah... She is just my neighbour's little girl. Haha...",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C5CC"
        },
        [11012815] = {
          Camera = "-886.352966,1603.910889,46.242737,0.000051,3.001615,-53.771996,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "... Bon je suppose qu’il est temps de dire la vérité. Tu as raison. Daphne est ma fille.",
          DialogueId = 11012815,
          Duration = 3,
          FinalCamera = "-876.272766,1611.296143,46.242737,0.000051,3.001615,-53.771996,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C5F6",
          NextDialogue = 11012816,
          Scripts = "PlayAnimation{_delay{2},ActorId{110010},AnimationId{\"Talk01_End\"},Duration{0}}",
          SpeakNpcId = 110010,
          Subtitle = "...I suppose it's time for the truth — You're right. Daphne is my daughter.",
          TalkActionId = {
            [1] = "110010:Talk01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C5F6"
        },
        [11012816] = {
          Camera = "-579.131714,395.651031,126.424561,0.000006,0.999987,44.224258,45.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "À vrai dire... c’est un peu embarrassant. C’est la dernière photo que j’ai prise avec elle. Peu de temps après, sa mère l’a emmenée et elles sont parties. Le nom de famille \"Theodore\", c’est celui de sa mère.",
          DialogueId = 11012816,
          Duration = 3,
          FinalCamera = "-587.124695,403.863434,126.424561,0.000006,0.999987,44.224018,45.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C620",
          LookAt = {
            [1] = "110010:n(110010)"
          },
          NextDialogue = 11012817,
          Scripts = [[
SEQ{
PlayAnimation{_delay{6},ActorId{110010},AnimationId{"Sigh_End"},Duration{0}},
PlayAnimation{_delay{2},ActorId{110010},AnimationId{"Talk01_Start"},Duration{4}},
PlayAnimation{ActorId{110010},AnimationId{"Talk01_End"},Duration{0}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "This is the last photo we took together before she and her mother left. Daphne took the last name \"Theodore\" from her mother.",
          TalkActionId = {
            [1] = "110010:Sigh_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C620"
        },
        [11012817] = {
          Camera = "-280.927521,1211.751587,190.038452,0.000039,-7.600156,-85.574547,45.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Mais promets-moi de ne rien répéter. On a divorcé justement pour que personne ne sache que Daphne est ma fille.",
          DialogueId = 11012817,
          Duration = 3,
          FinalCamera = "-270.015259,1212.595337,190.038452,0.000039,-7.600156,-85.574547,45.000011,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C64A",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11012818,
          Scripts = "PlayAnimation{_delay{4},ActorId{110010},AnimationId{\"Talk02_End\"},Duration{0}}",
          SpeakNpcId = 110010,
          Subtitle = "Don't tell anyone about this. We divorced specifically to keep people from knowing that Daphne is my daughter.",
          TalkActionId = {
            [1] = "110010:Talk02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C64A"
        },
        [11012818] = {
          Camera = "-331.020386,571.073792,139.486084,0.000067,0.800628,61.435661,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "À l’époque, la Première Alchimiste l’adorait. Elle disait que Daphne deviendrait un jour la meilleure de l’Empire. Elle avait cessé de prendre des apprentis depuis longtemps... et pourtant, pour elle, elle a fait une exception.",
          DialogueId = 11012818,
          Duration = 3,
          FinalCamera = "-324.280945,583.456116,139.682922,0.000067,0.800628,61.435661,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C674",
          NextDialogue = 11012819,
          SpeakNpcId = 110010,
          Subtitle = "Back then, the chief alchemist thought the world of Daphne. She believed Daphne had what it took to become the Empire's finest. She'd long since stopped taking apprentices — but for Daphne, she made an exception.",
          TalkActionId = {
            [1] = "110022:Talk03_End",
            [2] = "110010:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C674"
        },
        [11012819] = {
          Camera = "-256.828491,929.640686,152.787537,-0.0,-5.799807,-88.576996,40.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "À cause du talent de Daphne ?",
          DialogueId = 11012819,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C69E",
          NextDialogue = 11012820,
          SpeakNpcId = 110022,
          Subtitle = "Because of Daphne's talent?",
          TalkActionId = {
            [1] = "110022:Talk02_Start",
            [2] = "110010:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C69E"
        },
        [11012820] = {
          Camera = "-350.142548,666.156311,140.458618,0.000062,2.999812,49.027782,45.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Oui, elle a du talent... mais là-bas, aux Spathatoi, les génies, il y en a à foison.\nCe qui la rend spéciale, c’est ce qu’elle possède et que les autres n’ont pas, c’est ce que la Première Alchimiste disait, en tout cas.",
          DialogueId = 11012820,
          Duration = 3,
          FinalCamera = "-340.031555,677.799377,141.266479,0.000062,2.999812,49.027782,45.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C6C8",
          NextDialogue = 11012821,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8},TargetPosition{"-1224.551514,-56.273621,90.468933,-1.0,0.200131,36.623306,35.0,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"-1236.708984,-39.920101,90.824463,-1.0,0.200131,36.623306,35.0,100000.0,false,DoNotOverride,22.0"},duration{8}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "She's talented, but it's more than that. The Spathatoi is never short on talent. The chief alchemist said Daphne has a unique gift that sets her apart.",
          TalkActionId = {
            [1] = "110010:Talk03_Start",
            [2] = "110022:Talk02_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C6C8"
        },
        [11012821] = {
          Camera = "-386.329163,1674.61145,67.646606,0.0,4.599599,-79.570862,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Je n’ai jamais très bien compris, mais une chose est sûre, elle a de l’avenir. Et il ne fallait surtout pas qu’un père Charon lui barre la route.",
          DialogueId = 11012821,
          Duration = 3,
          FinalCamera = "-386.329163,1674.61145,41.897461,0.0,4.599599,-79.570862,35.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C6F2",
          NextDialogue = 11012834,
          Scripts = [[
SEQ{
PlayAnimation{_delay{2},ActorId{110010},AnimationId{"Talk03_End"},Duration{2}},
PlayAnimation{_delay{4},ActorId{110010},AnimationId{"Talk02_Start"},Duration{6}},
PlayAnimation{ActorId{110010},AnimationId{"Talk02_End"},Duration{0}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "I never quite understood what she meant, but it's clear Daphne has a bright future ahead of her. And having a Charon for a father shouldn't be what holds her back.",
          TalkActionId = {
            [1] = "110022:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C6F2"
        },
        [11012822] = {
          Camera = "-616.148438,313.40152,101.787903,0.000002,0.999468,49.427162,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Et... Daphne, elle le sait ?",
          DialogueId = 11012822,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-576.944153,359.186676,102.839539,0.000002,0.999468,49.42717,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C71C",
          NextDialogue = 11012823,
          SpeakNpcId = 110022,
          Subtitle = "Does Daphne know?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C71C"
        },
        [11012823] = {
          Camera = "-319.142975,642.300842,140.458618,0.00007,3.399658,61.429241,45.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Non. Elle a toujours été trop candide, trop attachée à son vieux père. Comment lui dire ça ?",
          DialogueId = 11012823,
          Duration = 3,
          FinalCamera = "-305.392487,667.551331,142.16687,0.00007,3.399658,61.429241,45.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C746",
          NextDialogue = 11012824,
          SpeakNpcId = 110010,
          Subtitle = "No. She has a heart of gold and adores her old man. How can I tell her?",
          TalkActionId = {
            [1] = "110010:DisagreeHead"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C746"
        },
        [11012824] = {
          ContentFR = "Je joue donc le rôle d’un mauvais père qui en a fini avec la vie de famille. Et quand Daphne m’appelait papa, je lui répondais : « Tais-toi. Je ne suis pas ton père. Je suis ton supérieur hiérarchique. »",
          DialogueId = 11012824,
          Duration = 3,
          GUID = "1B91C770",
          NextDialogue = 11012825,
          Scripts = [[
PARA{
PlayAnimation{_delay{15},ActorId{110022},AnimationId{"Talk03_End"},Duration{0}},
SEQ{
CameraMoveTo{_delay{6},TargetPosition{"-256.828491,929.640686,152.787537,-0.0,-5.799807,-88.576996,40.0,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"-256.535095,917.831116,151.587341,-0.0,-5.799807,-88.576996,40.0,100000.0,false,DoNotOverride,22.0"},duration{8}}
}}]],
          SpeakNpcId = 110010,
          Subtitle = "So, I play the part of a bad father who's done with family life. And when Daphne calls me dad, I tell her, \"Zip it. I'm not your father. Address me as your superior officer.\"",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C770"
        },
        [11012825] = {
          Camera = "-288.338318,672.926819,122.673157,0.000056,11.399967,65.427414,45.000023,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Mais Daphne est une enfant tellement adorable. Elle n’arrivait pas à m’insulter et finissait toujours par se blâmer elle-même à la place.",
          DialogueId = 11012825,
          Duration = 3,
          GUID = "1B91C79A",
          LookAt = {
            [1] = "110010:n(110010)"
          },
          NextOptions = {
            [1] = 11012826,
            [2] = 11012829
          },
          SpeakNpcId = 110010,
          Subtitle = "But Daphne's such a sweet kid. She couldn't bring herself to curse at me, and always ended up blaming herself instead.",
          TalkActionId = {
            [1] = "110010:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C79A"
        },
        [11012826] = {
          ContentFR = "<I>En réalité, elle n’aime pas l’Académie d’Alchimie. Vous et madame devriez prendre en compte ses préférences.</>",
          DialogueId = 11012826,
          GUID = "1B91C7C4",
          NextDialogue = 11012827,
          Subtitle = "Actually, she doesn't like the Academy. Perhaps you and the missus should also take her preferences into consideration."
        },
        [11012827] = {
          Camera = "-604.107727,306.536285,101.833496,0.000002,0.999468,49.42717,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Je le savais déjà. Cette fois, elle a tenu à rejoindre l’opération spéciale sur la Forteresse de Lonza, et elle a même soumis sa demande directement à Fulvis, sans prévenir sa mère ni moi. C’est évident qu’elle ne voulait vraiment plus y rester.",
          DialogueId = 11012827,
          Duration = 3,
          FinalCamera = "-622.919128,319.203278,101.787903,0.000002,0.999468,49.42717,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C7EE",
          NextDialogue = 11012828,
          SpeakNpcId = 110010,
          Subtitle = "I knew about that already. She volunteered for the Lonza Fortress op — even went straight to Fulvis with the paperwork, without telling either of us. That girl had her mind made up from the start.",
          TalkActionId = {
            [1] = "110010:AgreeHead",
            [2] = "110010:Sigh_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C7EE"
        },
        [11012828] = {
          Camera = "-264.298615,914.238342,151.455444,0.000002,-5.799711,-85.974731,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "... On en discutera calmement avec sa mère une fois de retour.",
          DialogueId = 11012828,
          Duration = 3,
          GUID = "1B91C818",
          NextDialogue = 11012830,
          SpeakNpcId = 110010,
          Subtitle = "...I'll talk to her mother about this when we return.",
          TalkActionId = {
            [1] = "110010:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C818"
        },
        [11012829] = {
          ContentFR = "<I>Vous avez aussi beaucoup sacrifié... Vous êtes un vrai père.</>",
          DialogueId = 11012829,
          GUID = "1B91C842",
          NextDialogue = 11012830,
          Subtitle = "You've made a huge sacrifice... You're a good father."
        },
        [11012830] = {
          Camera = "-288.338318,672.926819,122.673157,0.000055,11.399967,65.427475,45.000023,100000.0,false,DoNotOverride,22.0",
          ContentFR = "... J’aimerais qu’elle m’en veuille un peu plus, au moins ça lui épargnerait un peu de peine.",
          DialogueId = 11012830,
          Duration = 3,
          GUID = "1B91C86C",
          NextDialogue = 11012831,
          SpeakNpcId = 110010,
          Subtitle = "...I'd rather she resent me if it spares her any pain.",
          TalkActionId = {
            [1] = "110010:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C86C"
        },
        [11012831] = {
          Camera = "-604.107727,306.536285,101.833496,0.000002,0.999468,49.42717,35.000008,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Si nous y arrivons, je l’emmènerai à l’opéra. Quand je n’étais qu’un simple soldat, je n’ai jamais eu l’occasion de l’emmener dans des endroits chics. Je pense qu’il est temps de me rattraper.",
          DialogueId = 11012831,
          Duration = 3,
          FinalCamera = "-622.919128,319.203278,101.787903,0.000002,0.999468,49.42717,35.000008,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C896",
          NextDialogue = 11012832,
          Scripts = "PlayAnimation{_delay{7},ActorId{110010},AnimationId{\"Confident_End\"},Duration{0}}",
          SpeakNpcId = 110010,
          Subtitle = "If we make it back, I'll take her to the opera house. When I was just a grunt, I never got the chance to take her to any fancy places. I guess it's time to make it up to her.",
          TalkActionId = {
            [1] = "110010:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C896"
        },
        [11012832] = {
          Camera = "-324.594086,581.971741,140.384827,0.000062,1.799953,62.62788,45.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "J’ai entendu qu’une nouvelle pièce passait à Dismania, venue du nord, de la région de Cocytus, intitulée quelque chose... <I>du blizzard</>. Tu sais quoi ? Pourquoi tu ne viendrais pas avec moi ? Je prendrai un billet en plus.",
          DialogueId = 11012832,
          Duration = 3,
          FinalCamera = "-320.052155,590.743225,140.695251,0.000062,1.799953,62.62788,45.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1B91C8C0",
          NextDialogue = 11012833,
          SpeakNpcId = 110010,
          Subtitle = "I heard there's a new show in Dismania, coming from the northern province of Cocytus. It's called \"something... from the Snowfield\"... You know what — why don't you come along? I'll buy an extra ticket.",
          TalkActionId = {
            [1] = "110022:Talk03_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C8C0"
        },
        [11012833] = {
          Camera = "-258.992004,740.77594,158.750488,1.000006,-7.603387,-103.364433,45.000011,100000.0,false,DoNotOverride,22.0",
          ContentFR = "D’accord.",
          DialogueId = 11012833,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C8EA",
          SpeakNpcId = 110022,
          Subtitle = "Sure.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C8EA"
        },
        [11012834] = {
          ContentFR = "Mais... vous n’êtes pas n’importe quel Charon, vous êtes un <H>Charon Couronné</>.",
          DialogueId = 11012834,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91C6F3",
          NextDialogue = 11012835,
          RelatedWikiId = {
            [1] = 407003
          },
          SpeakNpcId = 110022,
          Subtitle = "But Sir Avar... you're not just any Charon — you're a Laurelled Charon.",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C6F3"
        },
        [11012835] = {
          ContentFR = "Ça ne change rien. Les temps ont changé, au Sénat, dans la Légion, partout, on commence à douter de la loyauté des Charons Couronnés.",
          DialogueId = 11012835,
          Duration = 3,
          GUID = "1B91C6F4",
          NextDialogue = 11012836,
          SpeakNpcId = 110010,
          Subtitle = "Doesn't make much difference these days. Even in the Senate, even in the Legion — people have started to question where our loyalties lie.",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C6F4"
        },
        [11012836] = {
          ContentFR = "Un jour ou l’autre, un décret pourrait tomber et nous renvoyer tous d’où l’on vient. Et ce jour-là, l’avenir de Daphne tomberait avec moi. C’est ce que craignait sa mère.",
          DialogueId = 11012836,
          Duration = 3,
          GUID = "1B91C6F5",
          NextDialogue = 11012822,
          SpeakNpcId = 110010,
          Subtitle = "Wouldn't surprise me if one day an edict comes down and we all get sent back where we came from. If it comes to that... Daphne's future might go down with mine. Or so her mother feared.",
          VoiceName = "voice/$Locale$/story/1002/110128/1B91C6F5"
        },
        [11012901] = {
          ContentFR = "Un adversaire redoutable. Restez sur vos gardes !",
          DialogueId = 11012901,
          Duration = 3,
          GUID = "1B91D412",
          SpeakNpcId = 110010,
          Subtitle = "This one is tough to deal with. Be cautious!",
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D412"
        },
        [11012902] = {
          Camera = "355.686127,-321.117188,61.902191,0.000327,6.602033,105.412376,28.000011,288.624115,false,Manual,6.072517",
          ContentFR = "Une embuscade ! Défendez-vous !",
          DialogueId = 11012902,
          FacialId = {
            [1] = "110010:Unhappy01"
          },
          FinalCamera = "317.624207,-183.041016,86.944946,0.000327,6.602033,105.412376,28.000011,139.773468,false,Manual,6.072517",
          GUID = "1B91D43C",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 11012903,
          SpeakNpcId = 110010,
          Subtitle = "It's an ambush! Defend yourselves!",
          TalkActionId = {
            [1] = "110010:Angry02_Start",
            [2] = "110022:Explain02_Start"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D43C"
        },
        [11012903] = {
          Camera = "-1147.589233,1035.804688,431.601532,0.000327,-8.59737,-43.590466,28.000006,667.895142,false,DoNotOverride,6.072517",
          ContentFR = "Attendez... Les défenses n’ont pas été activées ?",
          DialogueId = 11012903,
          FinalCamera = "-1147.589233,1035.804688,431.601532,0.000338,-9.796847,-36.989296,28.000006,667.895142,false,DoNotOverride,6.072517",
          GUID = "1B91D466",
          LookAt = {
            [1] = "110010:p(fix17_3)",
            [2] = "110022:p(fix1703)"
          },
          NextDialogue = 11012904,
          SpeakNpcId = 110010,
          Subtitle = "Wait... The defence system here is off?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D466"
        },
        [11012904] = {
          Camera = "-1936.596191,338.285156,1372.406128,0.000417,-36.596905,43.408157,14.543221,667.895142,false,DoNotOverride,6.072517",
          ContentFR = "La salle de commande est vide... Le Messager des Déchus aurait déjà fui ?",
          DialogueId = 11012904,
          FinalCamera = "-1936.596191,338.285156,1245.097656,0.000417,-36.596905,43.408157,14.543221,667.895142,false,DoNotOverride,6.072517",
          GUID = "1B91D490",
          LookAt = {
            [1] = "110010:n(110010)",
            [2] = "110022:n(110022)"
          },
          NextDialogue = 11012905,
          SpeakNpcId = 110010,
          Subtitle = "The central control room is empty... Has the Messenger left already?",
          TalkActionId = {
            [1] = "110010:Angry02_End",
            [2] = "110022:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D490"
        },
        [11012905] = {
          Camera = "-465.542786,485.144531,216.598389,0.000173,-9.999267,-36.987988,28.000008,667.895142,false,Manual,6.072517",
          ContentFR = "{nickname2}, quelque chose cloche. D’après les plans originaux de la forteresse, la salle de commande centrale devait posséder les meilleures défenses, voire un dispositif d’autodestruction.",
          DialogueId = 11012905,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "-487.617737,455.832031,216.598389,0.000173,-9.999267,-36.987988,28.000008,667.895142,false,Manual,6.072517",
          GUID = "1B91D4BA",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11012906,
          Scripts = "PlayAnimation{_delay{2},ActorId{110010},AnimationId{\"Think_Start\"},Duration{2}}",
          SpeakNpcId = 110010,
          Subtitle = ", something's off here. The original blueprints of the fortress show this room should have the strongest defence system, including a self-destruct mechanism.",
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "110010:n(110022)",
            [2] = "110022:n(110010)"
          },
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D4BA"
        },
        [11012906] = {
          Camera = "27.647247,-73.736328,81.884186,0.000202,3.20034,2.81273,28.000008,239.526123,false,Manual,10.489336",
          ContentFR = "Mais là... à part la porte verrouillée, rien n’est activé. Qu’en penses-tu ?",
          DialogueId = 11012906,
          GUID = "1B91D4E4",
          NextOptions = {
            [1] = 11012907,
            [2] = 11012910
          },
          SpeakNpcId = 110010,
          Subtitle = "But they've only locked the door, and there's no sign of any defence systems engaging. What do you make of this?",
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D4E4"
        },
        [11012907] = {
          ContentFR = "<I>Probablement une ruse pour nous faire baisser la garde. Il doit y avoir d’autres pièges.</>",
          DialogueId = 11012907,
          GUID = "1B91D50E",
          NextDialogue = 11012908,
          Subtitle = "Probably a ruse to lower our guard. There might be other traps."
        },
        [11012908] = {
          Camera = "331.160645,61.759766,124.87442,0.0002,-8.599856,-136.788193,28.000008,242.574921,false,Manual,10.489336",
          ContentFR = "Ou alors, ils savaient qu’on serait très méfiants ici, et ils ont dissimulé les pièges avec soin.",
          DialogueId = 11012908,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91D538",
          NextDialogue = 11012909,
          SpeakNpcId = 110022,
          Subtitle = "They probably predicted we would be extra cautious around this place, so they cleverly concealed their real traps.",
          TalkActionId = {
            [1] = "110022:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D538"
        },
        [11012909] = {
          Camera = "27.647247,-73.736328,81.884186,0.000202,3.20034,2.81273,28.000008,239.526123,false,Manual,10.489336",
          ContentFR = "Exact. Après tous les dispositifs que nous avons traversés, il serait illogique qu’ils abandonnent la dernière ligne de défense.",
          DialogueId = 11012909,
          GUID = "1B91D562",
          NextDialogue = 11012913,
          SpeakNpcId = 110010,
          Subtitle = "True. The central control room is key to regaining control of the fortress. It doesn't add up that they'd leave it undefended after all the elaborate traps we've encountered.",
          TalkActionId = {
            [1] = "110022:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D562"
        },
        [11012910] = {
          ContentFR = "<I>À moins que nous n’imaginions trop... Peut-être que les Déchus ne savent tout simplement pas manipuler les commandes de cette salle.</>",
          DialogueId = 11012910,
          GUID = "1B91D58C",
          NextDialogue = 11012911,
          Subtitle = "Maybe we're overthinking it. Perhaps The Forsakens never figured out how to operate the controls in this room."
        },
        [11012911] = {
          Camera = "27.647247,-73.736328,81.884186,0.000202,3.20034,2.81273,28.000008,239.526123,false,Manual,10.489336",
          ContentFR = "Mais compte tenu du nombre de pièges qu’ils ont installés tout au long du chemin, il semble peu probable qu’ils ignorent cette zone cruciale.",
          DialogueId = 11012911,
          GUID = "1B91D5B6",
          NextDialogue = 11012912,
          SpeakNpcId = 110010,
          Subtitle = "But given the number of traps they've set up along the way, it seems unlikely they'd ignore this crucial area.",
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D5B6"
        },
        [11012912] = {
          Camera = "141.658112,-34.873047,95.20993,0.000202,4.799984,-8.390281,28.000008,123.13105,false,Manual,10.489336",
          ContentFR = "Quoi qu’il en soit, même si c’est un piège, nous avons déjà mis le pied dedans. Restons concentrés sur notre mission.",
          DialogueId = 11012912,
          GUID = "1B91D5E0",
          NextDialogue = 11012913,
          SpeakNpcId = 110010,
          Subtitle = "Trap or not, we have our objectives. Proceed with caution and stay mission-focused.",
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D5E0"
        },
        [11012913] = {
          Camera = "-398.193848,144.386719,348.024841,0.000283,-26.79845,-15.198461,17.000002,215.162598,false,DoNotOverride,2.8",
          ContentFR = "Je vais utiliser ma clé pour prendre le contrôle de la console de commande. Nous sommes à deux doigts d’achever l’opération.",
          DialogueId = 11012913,
          FinalCamera = "-334.236298,127.009766,314.548828,0.000283,-26.798424,-15.198519,17.000006,215.162598,false,DoNotOverride,2.8",
          GUID = "1B91D60A",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11012914,
          SpeakNpcId = 110010,
          Subtitle = "I'm about to access the fortress's control panel with my key. If all goes well, that should complete our mission.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "110010:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D60A"
        },
        [11012914] = {
          Camera = "409.771362,295.126953,174.385681,0.000203,-15.199752,-119.982185,28.000006,496.513092,false,Manual,10.489336",
          ContentFR = "Compris. Je vais faire un tour et vérifier s’il n’y a rien de suspect.",
          DialogueId = 11012914,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91D634",
          SpeakNpcId = 110022,
          Subtitle = "Understood. I'll take a look around for anything suspicious.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D634"
        },
        [11012915] = {
          ContentFR = "Attention, il pourrait rester des ennemis à l’intérieur.",
          DialogueId = 11012915,
          Duration = 3,
          GUID = "1B91D65E",
          SpeakNpcId = 110010,
          Subtitle = "Be careful, there may be more enemies inside.",
          VoiceName = "voice/$Locale$/story/1002/110129/1B91D65E"
        },
        [11013001] = {
          ContentFR = "« La XIIIᵉ Légion lancera son assaut dans deux jours. Antonius Fulvis a juré devant Sibylle que si ses canons ne parviennent pas à briser les murs de la forteresse, il se tirerait une balle dans la tête. Sibylle lui a donc confié une troupe d’élite. »",
          DialogueId = 11013001,
          Duration = 3,
          GUID = "1B91E47A",
          NextDialogue = 11013002,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/poweron\"},PlayAs2D{true}}",
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_CalmVoice",
          Subtitle = "\"The 13th Legion will attack in two days. Antonius Fulvis has vowed before Sibylle that if his forces fail to breach the fortress, he would shoot himself with his own gun. Sibylle then assigned him the best troops.\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E47A"
        },
        [11013002] = {
          ContentFR = "« La Légion reprendra la Forteresse de Lonza, c’est une certitude. Il est inutile de songer à la défendre. Ce qui importe maintenant, c’est d’évacuer au plus vite et de préserver les forces des Déchus. »",
          DialogueId = 11013002,
          Duration = 3,
          GUID = "1B91E4A4",
          NextDialogue = 11013003,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_CalmVoice",
          Subtitle = "\"The Legion will do everything they can to take Lonza Fortress back. We should not attempt to defend the Fortress against such odds. Withdraw our forces and ensure the survival of The Forsakens.\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E4A4"
        },
        [11013003] = {
          ContentFR = "« Se retirer, comme ça ? Ce serait du gâchis. Il faut au moins que ces chiens d’Hyperboréens goûtent à notre venin. »",
          DialogueId = 11013003,
          Duration = 3,
          GUID = "1B91E4CE",
          NextDialogue = 11013004,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_UnsatisfiedVoice",
          Subtitle = "\"Merely retreating would squander a perfect opportunity. We should make the Hyperboreans pay dearly.\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E4CE"
        },
        [11013004] = {
          ContentFR = "« C’est facile à arranger. Laissez cela à Avar : il est chargé de deux escouades, et cette bande d’imbéciles lui obéit aveuglément. »",
          DialogueId = 11013004,
          Duration = 3,
          GUID = "1B91E4F8",
          NextDialogue = 11013005,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_CalmVoice",
          Subtitle = "\"Easy. Leave it to Avar. He'll be commanding two vanguard squads in the operation. Those fools always listen to him.\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E4F8"
        },
        [11013005] = {
          ContentFR = "« Préparez vos dispositifs à l’avance. Avar ralentira leur progression, et ils finiront tous par laisser leur peau ici. »",
          DialogueId = 11013005,
          Duration = 3,
          GUID = "1B91E522",
          NextDialogue = 11013006,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_CalmVoice",
          Subtitle = "\"Avar will hold off their assault. Use this time to lay traps and fortify our defences. The fortress will become their graveyard.\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E522"
        },
        [11013006] = {
          ContentFR = "« Bientôt, nous lirons dans les journaux un titre de ce genre... »",
          DialogueId = 11013006,
          Duration = 3,
          GUID = "1B91E54C",
          NextDialogue = 11013007,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_CalmVoice",
          Subtitle = "\"We'll soon read this headline in the news—\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E54C"
        },
        [11013007] = {
          ContentFR = "« Lors de la bataille de la Forteresse de Lonza, la XIIIᵉ Légion a héroïquement défendu les terres sacrées de l’Empereur. Plus de 90 % des officiers de l’avant-garde ont péri dans le combat. »",
          DialogueId = 11013007,
          Duration = 3,
          GUID = "1B91E576",
          NextDialogue = 11013008,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_CalmVoice",
          Subtitle = "\"'During the battle in Lonza Fortress, the 13th Legion valiantly defended the Emperor's lands. The vanguard suffered ninety percent casualties in the fierce conflict...'\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E576"
        },
        [11013008] = {
          ContentFR = "« Le lieutenant-colonel Avar, l’un des survivants, a salué la mémoire de ces soldats et leur a rendu les plus grands honneurs. »",
          DialogueId = 11013008,
          Duration = 3,
          GUID = "1B91E5A0",
          NextDialogue = 11013009,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_CalmVoice",
          Subtitle = "\"'Lieutenant Colonel Avar, one of the survivors, mourned the fallen and delivered a eulogy of unmatched honour.'\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E5A0"
        },
        [11013009] = {
          ContentFR = "« Sacré Avar ! Alors faisons comme ça. Dommage seulement que ces porcs d’Hyperboréens héritent d’une gloire posthume qu’ils ne méritent pas. »",
          DialogueId = 11013009,
          Duration = 3,
          GUID = "1B91E5CA",
          NextDialogue = 11013010,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/poweron\"},PlayAs2D{true}}",
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_UnsatisfiedVoice",
          Subtitle = "\"Good for Avar! Let's go with this plan then. Shame those dead dogs will receive posthumous honours, though.\"",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E5CA"
        },
        [11013010] = {
          ContentFR = "... Avar ?",
          DialogueId = 11013010,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91E5F4",
          SpeakNpcId = 110022,
          Subtitle = "...Avar?",
          VoiceName = "voice/$Locale$/story/1002/110130/1B91E5F4"
        },
        [11013101] = {
          ContentFR = "« Nous, peuple Charon, ne pouvons plus supporter la tyrannie hyperboréenne. »",
          DialogueId = 11013101,
          Duration = 3,
          GUID = "1B91F4E2",
          NextDialogue = 11013102,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/poweron\"},PlayAs2D{true}}",
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_Docs",
          Subtitle = "\"Charons like us can no longer stand Hyperborean tyranny.\"",
          VoiceName = "voice/$Locale$/story/1002/110131/1B91F4E2"
        },
        [11013102] = {
          ContentFR = "« J’offre ma loyauté aux Déchus. L’Empire doit payer pour ses crimes. »",
          DialogueId = 11013102,
          Duration = 3,
          GUID = "1B91F50C",
          NextDialogue = 11013103,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_Docs",
          Subtitle = "\"I hereby pledge my allegiance to The Forsakens. The Empire must be held accountable for its actions.\"",
          VoiceName = "voice/$Locale$/story/1002/110131/1B91F50C"
        },
        [11013103] = {
          ContentFR = "« — Avar Hrodland »",
          DialogueId = 11013103,
          Duration = 3,
          GUID = "1B91F536",
          NextDialogue = 11013104,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/poweron\"},PlayAs2D{true}}",
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_Docs",
          Subtitle = "\"—Avar Hrodland\"",
          VoiceName = "voice/$Locale$/story/1002/110131/1B91F536"
        },
        [11013104] = {
          ContentFR = "... ?!",
          DialogueId = 11013104,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B91F560",
          SpeakNpcId = 110022,
          Subtitle = "...!?",
          VoiceName = "voice/$Locale$/story/1002/110131/1B91F560"
        },
