          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(The recording, the signed document, Katya's words... and this man in front of me — my mentor on hand-to-hand combat and battle tactics, my superior who always looks out for me...)",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110134/1B92298C"
        },
