        [11013426] = {
          Camera = "-1498.460449,-3943.126953,1169.687256,0.000274,-16.394106,64.205383,26.362551,84.929626,false,DoNotOverride,22.0",
          ContentFR = "Et toi, tu as trouvé quelque chose ?",
          DialogueId = 11013426,
          Duration = 1,
          GUID = "1B9226EF",
