          },
          GUID = "1B9247BC",
          NextDialogue = 11013607,
          Scripts = "LookAt{_delay{1},LookAtDescription{\"110012:n(110011)\"}}",
          SpeakNpcId = 110012,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110136/1B9247BC"
        },
        [11013607] = {
          Camera = "23.118408,168.939453,59.625854,-0.001587,2.603798,-68.594788,35.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Sors, Falsi. Pas de danger. Toute la forteresse est à nous, il n’osera pas bouger.",
          DialogueId = 11013607,
          Duration = 3,
          GUID = "1B9247E6",
          LookAt = {
            [1] = "110011:n(110012)"
          },
          NextDialogue = 11013608,
          RelatedWikiId = {
            [1] = 201016
          },
          Scripts = "PlayAnimation{_delay{4},ActorId{110011},AnimationId{\"Talk02_End\"},Duration{3}}",
          SpeakNpcId = 110011,
          Subtitle = "Off you go, Falsi. It's alright, the entire fortress is in our hands. This old man dares not make a move.",
          TalkActionId = {
            [1] = "110011:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110136/1B9247E6"
        },
        [11013608] = {
          Camera = "45.629196,-553.193359,13.620331,0.000056,8.603962,74.588776,20.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Reçu. Je vous attends derrière la porte.",
          DialogueId = 11013608,
          FinalCamera = "45.629196,-553.193359,-7.81955,0.000056,8.603962,74.588776,20.0,100000.0,false,DoNotOverride,22.0",
