          ContentFR = "{nickname2}, la Geôlière Vulcera a donné l’ordre d’amener Mademoiselle Theodore.",
          DialogueId = 11016801,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9453EA",
          LookAt = {
            [1] = "110021:n(110040)",
            [2] = "110040:n(110021)",
