          SpeakNpcId = 110041,
          Subtitle = "...?!",
          VoiceName = "voice/$Locale$/story/1002/110169/1B94647C"
        },
        [11016903] = {
          Camera = "-349.862305,123.099609,120.742188,0.000104,1.202755,26.777416,35.000019,509.385437,false,Manual,22.0",
          ContentFR = "Une directive visant à accélérer toutes les révisions procédurales a été émise par la hiérarchie. Le seul document que j’ai reçu est un mandat ordonnant votre exécution immédiate.",
          DialogueId = 11016903,
          FacialId = {
            [1] = "110032:Angry01"
          },
          GUID = "1B9464A6",
          LookAt = {
            [1] = "110041:n(110032)",
            [2] = "110040:n(110032)"
          },
          NextDialogue = 11016904,
          Scripts = [[
SEQ{
SetLocation{ActorId{110032},TargetPoint{"28Point2"},Visibility{"Show"}}
}]],
          SpeakNpcId = 110032,
          Subtitle = "A directive to expedite all procedural reviews has been issued from above. The only document I received is a writ demanding your immediate execution.",
          TalkActionId = {
            [1] = "110032:Explain01_Start",
            [2] = "110041:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110169/1B9464A6"
        },
        [11016904] = {
          Camera = "-189.967773,373.448242,157.484375,0.000144,1.603148,-97.005592,40.0,193.921936,false,Manual,22.0",
          ContentFR = "Madame la Geôlière, ce n’est pas normal, cela ne suit pas le protocole judiciaire !",
          DialogueId = 11016904,
          Duration = 2,
          FacialId = {
            [1] = "110041:Angry01"
          },
          GUID = "1B9464D0",
          NextDialogue = 11016905,
          Scripts = [[
SEQ{
SetLocation{ActorId{110041},TargetPoint{"fx28_dafuStand"},Visibility{"Show"}},
PlayAnimation{ActorId{110041},AnimationId{"Sit_Idle_End"},Duration{2}},
TurnTo{TurnToDescription{"110041:n(110032)"}},
PlayAnimation{ActorId{110041},AnimationId{"Angry01_Start"},Duration{2}},
CameraMoveTo{TargetPosition{"246.750977,635.553711,145.472656,0.000125,-0.197017,-132.803497,35.000008,662.207397,false,Manual,22.0"},duration{0}}
}]],
          SpeakNpcId = 110041,
          Subtitle = "Ma'am, this is not right — it goes against the standard procedures of interrogation.",
          VoiceName = "voice/$Locale$/story/1002/110169/1B9464D0"
        },
        [11016905] = {
          Camera = "-650.21875,847.072266,405.632812,0.000051,-26.194887,-39.601955,26.0,530.095764,false,DoNotOverride,22.0",
          ContentFR = "Regardez ce mandat, et cette série de signatures à la fin. Même le Ministre Suprême de la Justice l’a signé. Même la Commandante Sibylle ne peut l’arrêter. Vous êtes vraiment pris dans quelque chose de bien plus grand que vous.",
          DialogueId = 11016905,
          FacialId = {
            [1] = "110041:Unacceptable01"
          },
          FinalCamera = "-650.21875,847.072266,405.632812,0.000047,-22.794765,-43.20211,26.0,530.095764,false,DoNotOverride,22.0",
          GUID = "1B9464FA",
          NextDialogue = 11016906,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{110032},AnimationId{"Explain01_End"},Duration{2}},
PlayAnimation{_delay{4},ActorId{110032},AnimationId{"DisagreeHead"},Duration{2}}
}]],
          SpeakNpcId = 110032,
          Subtitle = "Take a look at the writ and the signatures at the bottom. Even the Supreme Minister of Justice has signed it. Not even Chief Sibylle can stop it. Your case has grown beyond anyone's control.",
          TalkActionId = {
            [1] = "110041:Angry01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110169/1B9464FA"
        },
        [11016906] = {
          Camera = "-89.286133,352.804688,215.699219,0.000116,-15.397158,119.181168,35.000011,262.747772,false,Manual,22.0",
          ContentFR = "Et Falsi ? Tant qu’on retrouve Falsi et l’enregistreur, la vérité... !",
          DialogueId = 11016906,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110040:Angry01"
          },
          GUID = "1B946524",
          NextDialogue = 11016907,
          Scripts = [[
SEQ{
SetLocation{ActorId{110040},TargetPoint{"fx28_nanzhuStand"},Visibility{"Show"}},
PlayAnimation{ActorId{110040},AnimationId{"Sit_Idle_End"},Duration{2}},
PlayAnimation{ActorId{110040},AnimationId{"Explain01_Start"},Duration{2}}
}]],
          SpeakNpcId = 110040,
          Subtitle = "What about Falsi? As long as we find Falsi and the recording device, we can prove that...",
          VoiceName = "voice/$Locale$/story/1002/110169/1B946524"
        },
        [11016907] = {
          Camera = "-119.676758,376.845703,212.484375,0.000182,-19.996178,5.170751,35.000015,530.095764,false,Manual,22.0",
          ContentFR = "Elle a disparu.",
          DialogueId = 11016907,
          FacialId = {
            [1] = "110032:None"
          },
          GUID = "1B94654E",
          LookAt = {
            [1] = "110032:n(110040)"
          },
          NextDialogue = 11016908,
          SpeakNpcId = 110032,
          Subtitle = "She's missing.",
          TalkActionId = {
            [1] = "110040:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110169/1B94654E"
        },
        [11016908] = {
          ContentFR = "Lors d’une explosion à la Forteresse de Lonza, elle est tombée hors de la structure. Les soldats ont retrouvé son pistolet ensanglanté sur la rive. Le régiment cherche encore, mais d’après ce que l’on suppose, elle est probablement morte.",
          DialogueId = 11016908,
          GUID = "1B946578",
          NextDialogue = 11016909,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{110032},AnimationId{"Talk01_Start"},Duration{2}},
PlayAnimation{_delay{2},ActorId{110032},AnimationId{"Talk01_End"},Duration{2}},
CameraMoveTo{_delay{1},TargetPosition{"-537.025391,515.268555,271.632812,0.000282,-18.459036,-12.635934,15.000007,100000.0,false,Manual,22.0"},duration{0}},
CameraMoveTo{_delay{0},TargetPosition{"-564.171875,461.899414,229.765625,0.000282,-18.459036,-12.635994,15.000007,100000.0,false,Manual,22.0"},duration{15}}
}]],
          SpeakNpcId = 110032,
          Subtitle = "An explosion occurred during the battle. Falsi was last seen outside the fortress. Her bloodstained pistol was found along the riverbank. Although the Legion continues to search, it is likely that she is deceased.",
          VoiceName = "voice/$Locale$/story/1002/110169/1B946578"
        },
        [11016909] = {
          Camera = "-167.293945,332.791992,154.449219,0.000129,2.60293,-109.422783,35.000011,159.827057,false,Manual,22.0",
          ContentFR = "... Madame la Geôlière, vous croyez vraiment à une telle coïncidence ?",
          DialogueId = 11016909,
          GUID = "1B9465A2",
          LookAt = {
            [1] = "110032:n(110041)"
          },
          NextDialogue = 11016910,
          SpeakNpcId = 110041,
          Subtitle = "...Ma'am, do you really believe in such a coincidence?",
          TalkActionId = {
            [1] = "110041:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110169/1B9465A2"
        },
        [11016910] = {
          Camera = "-82.495117,382.399414,154.101562,0.000099,-3.197143,-0.828277,35.000008,169.37561,false,Manual,22.0",
          ContentFR = "...",
          DialogueId = 11016910,
          Duration = 2,
          GUID = "1B9465CC",
          NextDialogue = 11017001,
          SpeakNpcId = 110032,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110041:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110169/1B9465CC"
        },
        [11017001] = {
          ContentFR = "Votre Altesse Prince Vergilius ! Cet endroit n’est pas approprié pour votre rang, je vous en prie, ne vous attardez pas ici !",
          DialogueId = 11017001,
          GUID = "1B9474BA",
          Scripts = "LookAt{_delay{0.6},LookAtDescription{\"110032:p(28Point3)\"}}",
          SnapShot = "OUTDOOR",
          SpeakNpcName = "UI_Npc_EnemySoldier",
          Subtitle = "Your Royal Highness Prince Vergilius! This place isn't fitting for someone of your stature. Please don't proceed any further!",
          VoiceName = "voice/$Locale$/story/1002/110170/1B9474BA"
        },
        [11017003] = {
          ContentFR = "Rassembler autant de signatures n’a pas dû être facile.",
          DialogueId = 11017003,
          Duration = 3,
          GUID = "1B94750E",
          SpeakNpcId = 110018,
          Subtitle = "Gathering so many signatures must have been quite the feat.",
          VoiceName = "voice/$Locale$/story/1002/110170/1B94750E"
        },
        [11017004] = {
          ContentFR = "Mais toutes ces signatures... elles pèsent moins que celle que j’ai en main, n’est-ce pas ?",
          DialogueId = 11017004,
          Duration = 4,
          GUID = "1B947538",
          SpeakNpcId = 110018,
          Subtitle = "Yet, these signatures might weigh less than the one in my hand, I suppose?",
          VoiceName = "voice/$Locale$/story/1002/110170/1B947538"
        },
        [11017005] = {
          ContentFR = "...",
          DialogueId = 11017005,
          Duration = 3,
          GUID = "1B947562",
          SpeakNpcId = 110032,
          Subtitle = "Your Highness.",
          VoiceName = "voice/$Locale$/story/1002/110170/1B947562"
        },
        [11017006] = {
          ContentFR = "Votre Altesse, la famille royale compte-t-elle intervenir dans l’affaire d’espionnage à Lonza ?",
          DialogueId = 11017006,
          Duration = 4,
          GUID = "1B94758C",
          SpeakNpcId = 110032,
          Subtitle = "Does the royal family intend to intervene in this military case?",
          VoiceName = "voice/$Locale$/story/1002/110170/1B94758C"
        },
        [11017007] = {
          ContentFR = "Intervenir ? Madame la Geôlière, appelez-vous \"intervenir\" le fait que Sa Majesté signe elle-même une grâce royale ? La Prison Militaire Royale n’est donc plus sous l’autorité de la couronne ?",
          DialogueId = 11017007,
          Duration = 10,
          GUID = "1B9475B6",
          SpeakNpcId = 110018,
          Subtitle = [[
Intervene? I must ask, do you view His Majesty's decree of pardon as an "intervention"?
Is the Royal Military Prison no longer under the crown's jurisdiction?]],
          VoiceName = "voice/$Locale$/story/1002/110170/1B9475B6"
        },
        [11017008] = {
          ContentFR = "...",
          DialogueId = 11017008,
          Duration = 3,
          GUID = "1B9475E0",
          SpeakNpcId = 110018,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110170/1B9475E0"
        },
        [11017009] = {
          ContentFR = "Je souhaite m’entretenir seul avec {nickname2}. Que tous les autres quittent la pièce.",
          DialogueId = 11017009,
          Duration = 4,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94760A",
          SpeakNpcId = 110018,
          Subtitle = "I need to speak with  alone. Everyone else may leave.",
          VoiceName = "voice/$Locale$/story/1002/110170/1B94760A"
        },
        [11017010] = {
          ContentFR = "... Enfin partis.",
          DialogueId = 11017010,
          Duration = 3,
          GUID = "1B947634",
          SpeakNpcId = 110018,
          Subtitle = "...Phew, they're finally gone.",
          VoiceName = "voice/$Locale$/story/1002/110170/1B947634"
        },
        [11017101] = {
          Camera = "266.088867,42.083984,149.292969,0.000127,-0.000061,19.197737,45.000023,400.044037,false,DoNotOverride,22.0",
          ContentFR = "C’était juste, un instant de retard et j’aurais dû parler à ta pierre tombale.",
          DialogueId = 11017101,
          FinalCamera = "261.737305,56.924805,149.292969,0.000127,0.399955,13.99701,45.000023,400.044037,false,DoNotOverride,22.0",
          GUID = "1B948522",
          LookAt = {
            [1] = "110018:n(110018)",
            [2] = "110022:n(110018)"
          },
          NextDialogue = 11017102,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 201014,
            [5] = 201019,
            [6] = 201020
          },
          Scripts = [[
SEQ{PlayAnimation{ActorId{110018},AnimationId{"DisagreeHead"},Duration{3}},
TurnTo{_delay{0.5},TurnToDescription{"110018:n(110022)"}},
LookAt{LookAtDescription{"110018:n(110022)"}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "Thank goodness. One moment later and I might have to talk to your headstone instead.",
          ToFinalCameraBlendTime = 18,
          VoiceName = "voice/$Locale$/story/1002/110171/1B948522"
        },
        [11017102] = {
          Camera = "38.443359,-115.731445,90.113281,0.000127,6.999892,36.203079,35.0,400.044037,false,DoNotOverride,22.0",
          ContentFR = "Mon {性别2:ami|amie}, tu as vraiment mis les pieds dans un sacré pétrin. Tu sais combien il est difficile de voir mon frère, et combien je touche rarement aux affaires politiques. Mais ce matin, j’ai été convoqué pour autre chose et j’en ai profité pour obtenir cette grâce royale.",
          DialogueId = 11017102,
          FinalCamera = "33.347656,-115.939453,81.179688,0.000127,6.999892,36.203079,35.0,400.044037,false,DoNotOverride,22.0",
          GUID = "1B94854C",
          LookAt = {
            [1] = "110018:n(110022)",
            [2] = "110022:n(110018)"
          },
          NextDialogue = 11017103,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.5},ActorId{110018},AnimationId{"Talk02_End"},Duration{5}},
SEQ{
CameraMoveTo{_delay{7.5},TargetPosition{"509.366211,-103.800781,280.621094,0.000228,-31.400387,130.990356,18.000004,254.013382,false,DoNotOverride,7.801928"},duration{0}},
CameraMoveTo{TargetPosition{"499.982422,-111.956055,283.566406,0.000228,-31.400387,130.990356,18.000004,254.013382,false,DoNotOverride,7.801928"},duration{15}}
}
}]],
          SpeakNpcId = 110018,
          Subtitle = "By all that is holy, my friend, you've really landed yourself in some serious trouble. You know how hard it is to meet my brother, and how rarely I get involved with politicians. But fortune favours you today — I was summoned for a different matter and seized the opportunity to secure your pardon.",
          TalkActionId = {
            [1] = "110018:Talk02_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94854C"
        },
        [11017103] = {
          ContentFR = "Enfin, nous pouvons respirer l’air libre, où veux-tu aller ? Musée, opéra, taverne de l’Avenue du Triomphe, ou simplement te promener le long de la Rivière des Murmures ?",
          DialogueId = 11017103,
          Duration = 2,
          GUID = "1B948576",
          NextDialogue = 11017104,
          RelatedWikiId = {
            [1] = 408008,
            [2] = 408009
          },
          Scripts = [[
PARA{
SEQ{
PlayAnimation{ActorId{110018},AnimationId{"Talk01_Start"},Duration{2}},
PlayAnimation{_delay{3},ActorId{110018},AnimationId{"Talk01_End"},Duration{0}},
PlayAnimation{ActorId{110018},AnimationId{"Talk02_Start"},Duration{5}},
PlayAnimation{ActorId{110018},AnimationId{"Talk02_End"},Duration{5}}
},
SEQ{
CameraMoveTo{_delay{5.01},TargetPosition{"329.342773,-782.536133,108.894531,0.000158,2.99986,91.395897,28.0,400.044037,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"329.342773,-782.536133,84.554688,0.000158,2.99986,91.395897,28.0,400.044037,false,DoNotOverride,22.0"},duration{40}}
}
}]],
          SpeakNpcId = 110018,
          Subtitle = "Things have finally blown over. You're free at last. Where do you want to go, the art gallery, the opera house, or just a simple stroll along Whisper River for fresh air?",
          VoiceName = "voice/$Locale$/story/1002/110171/1B948576"
        },
        [11017104] = {
          Camera = "541.608398,60.505859,169.71875,0.000138,-8.399841,172.791351,35.0,282.239868,false,Manual,5.900274",
          ContentFR = "... Merci... mais pas pour l’instant.",
          DialogueId = 11017104,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9485A0",
          NextDialogue = 11017105,
          SpeakNpcId = 110022,
          Subtitle = "...Thanks, but no thanks.",
          TalkActionId = {
            [1] = "110022:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110171/1B9485A0"
        },
        [11017105] = {
          Camera = "261.737305,56.924805,149.292969,0.000127,0.399955,13.99701,45.000023,400.044037,false,DoNotOverride,22.0",
          ContentFR = "... Tu as mauvaise mine. On t’a {性别2:malmené|malmenée}. Viens chez moi, je ferai examiner tes blessures par mes médecins.",
          DialogueId = 11017105,
          Duration = 1,
          GUID = "1B9485CA",
          NextDialogue = 11017106,
          Scripts = [[
SEQ{PlayAnimation{_delay{1.5},ActorId{110018},AnimationId{"Explain02_Start"},Duration{2}},
PlayAnimation{_delay{1},ActorId{110018},AnimationId{"Explain02_End"},Duration{2}},
PlayAnimation{_delay{2},ActorId{110018},AnimationId{"Talk02_Start"},Duration{2}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "...You... look pale. They did go rough on you. Why don't you come to my place? My personal physicians will tend to your wounds.",
          VoiceName = "voice/$Locale$/story/1002/110171/1B9485CA"
        },
        [11017106] = {
          ContentFR = "Un millénaire s’est écoulé, et les prisons d’Hyperborea utilisent encore des tortures aussi primitives et inhumaines... Les écrivains flatteurs parlent du « plus grand et prospère des temps », quelle comédie !",
          DialogueId = 11017106,
          GUID = "1B9485F4",
          NextDialogue = 11017107,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6.01},TargetPosition{"640.131836,164.128906,414.648438,0.0001,-25.800047,-120.799606,20.0,400.044037,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"691.962891,133.231445,414.648438,0.0001,-25.800047,-120.799606,20.0,400.044037,false,DoNotOverride,22.0"},duration{20}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "A millennium has passed, and still, the prisons of Hyperborea cling to such crude, barbaric, and wholly inhumane forms of torture... Those sycophantic chroniclers call this \"the greatest and most prosperous of times” — what a most exquisite farce.",
          TalkActionId = {
            [1] = "110018:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110171/1B9485F4"
        },
        [11017107] = {
          Camera = "358.598633,12.164062,188.667969,0.000165,-23.000387,156.785355,28.000008,310.596832,false,DoNotOverride,7.801928",
          ContentFR = "Ne parlons pas de ça... et Daphne ?",
          DialogueId = 11017107,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "360.378906,16.311523,188.667969,0.000165,-23.000387,156.785355,28.000008,310.596832,false,DoNotOverride,7.801928",
          GUID = "1B94861E",
          NextDialogue = 11017108,
          SpeakNpcId = 110022,
          Subtitle = "Let's not dwell on that... How's Daphne?",
          TalkActionId = {
            [1] = "110022:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94861E"
        },
        [11017108] = {
          Camera = "169.751953,12.941406,146.257812,0.000181,-0.200685,23.989719,45.0,254.013382,false,Manual,7.801928",
          ContentFR = "Ne t’inquiète pas. J’ai entendu parler de tes efforts pour la protéger, cette grâce la couvre aussi.",
          DialogueId = 11017108,
          FinalCamera = "159.480469,8.374023,146.257812,0.000181,-0.200685,23.989157,45.0,254.013382,false,Manual,7.801928",
          GUID = "1B948648",
          NextDialogue = 11017112,
          SpeakNpcId = 110018,
          Subtitle = "I heard about your efforts to ensure her safety. Fear not, the pardon includes her as well.",
          TalkActionId = {
            [1] = "110018:AgreeHead"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110171/1B948648"
        },
        [11017109] = {
          Camera = "626.061523,-377.210938,104.453125,0.000161,-1.200583,124.384415,28.000006,310.596832,false,DoNotOverride,7.801928",
          ContentFR = "... {性别2:Désolé|Désolée}, je n’ai rien pour te remercier pour le moment.",
          DialogueId = 11017109,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "640.552734,-398.384766,104.984375,0.000161,-1.200583,124.384415,28.000006,310.596832,false,DoNotOverride,7.801928",
          GUID = "1B948672",
          NextDialogue = 11017110,
          Scripts = [[
SEQ{
PlayAnimation{_delay{4},ActorId{110022},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{1},ActorId{110022},AnimationId{"Explain02_Start"},Duration{5}}
}]],
          SpeakNpcId = 110022,
          Subtitle = "Thank you, and... sorry, I don't have anything to repay your kindness at the moment.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110171/1B948672"
        },
        [11017110] = {
          Camera = "-224.194336,-243.641602,117.367188,0.000243,-0.000792,28.586721,45.000011,741.075867,false,Manual,7.801928",
          ContentFR = "Remercier ? Hmm... que dirais-tu de me servir comme garde du corps pendant six mois ?",
          DialogueId = 11017110,
          FacialId = {
            [1] = "110018:Smile01"
          },
          FinalCamera = "-230.798828,-231.524414,117.367188,0.000243,-0.000792,28.586721,45.000023,717.293152,false,Manual,6.911264",
          GUID = "1B94869C",
          NextDialogue = 11017111,
          Scripts = [[

PlayAnimation{_delay{2},ActorId{110018},AnimationId{"Talk03_Start"},Duration{2}}]],
          SpeakNpcId = 110018,
          Subtitle = "Repay me? Hmm... How about serving as my bodyguard for six months?",
          TalkActionId = {
            [1] = "110022:Explain02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94869C"
        },
        [11017111] = {
          Camera = "499.02832,79.253906,163.570312,0.000184,-5.80075,178.390396,45.0,254.013382,false,Manual,7.801928",
          ContentFR = "Garde du corps ?",
          DialogueId = 11017111,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "498.866211,73.417969,163.570312,0.000184,-5.80075,178.390396,45.0,254.013382,false,Manual,7.801928",
          GUID = "1B9486C6",
          NextDialogue = 11019105,
          SpeakNpcId = 110022,
          Subtitle = "Bodyguard?",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1002/110171/1B9486C6"
        },
        [11017112] = {
          Camera = "34.15918,-378.791016,351.042969,0.000214,-23.400875,60.993435,35.0,254.013382,false,DoNotOverride,7.801928",
          ContentFR = "Encore une chose...",
          DialogueId = 11017112,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "56.49707,-391.176758,351.042969,0.000214,-23.400875,60.993435,35.0,254.013382,false,DoNotOverride,7.801928",
          GUID = "1B94871B",
          NextDialogue = 11017114,
          SpeakNpcId = 110022,
          Subtitle = "One more thing...",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110171/1B94871B"
        },
        [11017113] = {
          Camera = "3.826172,76.46582,165.292969,0.000128,-0.600066,-114.184586,31.194523,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Pour le moment, tu ne pourras pas retourner à la Légion. Ton statut reste délicat, y revenir maintenant serait compliqué.",
          DialogueId = 11017113,
          Duration = 3,
          GUID = "1B94871A",
          NextDialogue = 11019115,
          Scripts = [[
PARA{
PlayAnimation{_delay{3},ActorId{110018},AnimationId{"Think_End"},Duration{3}},
PlayFacial{ActorId{110022},FacialId{"Think01"}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "And staying away from the Legion might be wise for now. The stigma of a criminal charge lingers. Going back to the Legion at this point could be awkward.",
          TalkActionId = {
            [1] = "110018:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110171/1B94871A"
        },
        [11017114] = {
          ContentFR = "Falsi, l’adjudante de Fulvis. Sa disparition n’est pas simple, elle détient la clé de la vérité. Si possible, j’aimerais que tu enquêtes sur son sort, vivante ou morte.",
          DialogueId = 11017114,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94871C",
          NextDialogue = 11017115,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"346.420898,18.442383,147.914062,0.000204,-2.60082,157.593735,35.0,254.013382,false,DoNotOverride,7.801928"},duration{0}},
CameraMoveTo{TargetPosition{"348.020508,22.321289,147.914062,0.000204,-2.60082,157.593735,35.0,254.013382,false,DoNotOverride,7.801928"},duration{8}}
},
SEQ{
PlayAnimation{ActorId{110022},AnimationId{"Talk02_End"},Duration{2}},
PlayAnimation{ActorId{110022},AnimationId{"Think_Start"},Duration{5}},
PlayAnimation{ActorId{110022},AnimationId{"Think_End"},Duration{2}}
}
}]],
          SpeakNpcId = 110022,
          Subtitle = "Fulvis's adjutant, Falsi — I don't think her disappearance was what it seemed. She holds the key to the truth behind all this. If it's not too much to ask... could I trouble you to look into her whereabouts? Dead or alive — I need to know.",
          VoiceName = "voice/$Locale$/story/1002/110171/1B94871C"
        },
        [11017115] = {
          Camera = "315.612305,27.775391,111.347656,0.000177,18.198792,35.193779,45.000011,254.013382,false,DoNotOverride,7.801928",
          ContentFR = "L’adjudante disparue de Fulvis... ? Bien, je m’en occuperai.",
          DialogueId = 11017115,
          GUID = "1B94871D",
          NextDialogue = 11017109,
          SpeakNpcId = 110018,
          Subtitle = "Fulvis's missing adjutant... I see. I'll look into it.",
          VoiceName = "voice/$Locale$/story/1002/110171/1B94871D"
        },
        [11017116] = {
          Camera = "211.03125,373.930664,131.835938,0.000081,2.000002,-130.801483,31.194527,100000.0,false,Manual,22.0",
          ContentFR = "Oui. Pense aux signatures sur ce mandat, combien de regards invisibles te surveillent à Dismania. Ton arme peut tuer les Souillés, mais elle ne peut pas arrêter les balles tirées dans le dos.",
          DialogueId = 11017116,
          Duration = 3,
          FinalCamera = "215.617188,369.973633,131.835938,0.000081,1.999995,-130.801483,31.194527,100000.0,false,Manual,22.0",
          GUID = "1B948798",
          NextDialogue = 11017117,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"118.792969,12.256836,231.714844,0.000107,-21.599482,-163.622894,45.0,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"130.400391,15.670898,236.511719,0.000107,-21.599482,-163.622894,45.0,100000.0,false,DoNotOverride,22.0"},duration{8}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "Yes. Just think of those signatures — how many people are watching you in Dismania. Your prowess may deter approaching Filthoids, but not hidden assassins.",
          TalkActionId = {
            [1] = "110022:Talk01_End",
            [2] = "110018:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110171/1B948798"
        },
        [11017117] = {
          Camera = "-38.605469,-123.583984,167.742188,0.000094,-5.999843,78.991455,31.194527,446.287842,false,Manual,11.834087",
          ContentFR = "Je sais ce qui te préoccupe. Sibylle Mason a des liens anciens avec Daphne, et dans cette affaire, elle croit manifestement en votre innocence. Elle veillera donc, au minimum, à ce que Daphne soit en sécurité.",
          DialogueId = 11017117,
          Duration = 3,
          FinalCamera = "-45.6875,-122.178711,167.742188,0.000092,-6.199858,78.391617,31.194527,446.287842,false,Manual,11.834087",
          GUID = "1B9487C2",
          NextDialogue = 11019119,
          SpeakNpcId = 110018,
          Subtitle = "I know what you're worried about. Sibylle Mason is an old friend of Daphne. She is obviously inclined to your innocence, so she will at least ensure Daphne's safety.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110171/1B9487C2"
        },
        [11017119] = {
          Camera = "653.830078,-1243.886719,875.824219,0.000136,-26.201082,109.391876,31.194523,1682.25708,false,Manual,1.2",
          ContentFR = "... Allez, tu sais bien que je déteste ces coutumes et ces règles de bienséance inutiles. Mais tu es d’humeur à plaisanter maintenant, ce qui est bon signe.",
          DialogueId = 11017119,
          Duration = 3,
          FacialId = {
            [1] = "110018:Smile01"
          },
          FinalCamera = "619.453125,-1255.985352,875.824219,0.000136,-26.201082,109.391876,31.194523,1682.25708,false,Manual,1.2",
          GUID = "1B948816",
          NextDialogue = 11019121,
          Scripts = "PlayAnimation{_delay{3},ActorId{110022},AnimationId{\"Explain02_End\"},Duration{3}}",
          SpeakNpcId = 110018,
          Subtitle = "...Come on, you know there's nothing I hate more than these pointless customs and etiquette. But you're in the mood for jokes now, which is a good sign.",
          TalkActionId = {
            [1] = "110018:Talk03_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110171/1B948816"
        },
        [11017201] = {
          ContentFR = "{nickname2}, tu ne comptes vraiment rien me demander ?",
          DialogueId = 11017201,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9488C0",
          NextDialogue = 11017202,
          SpeakNpcId = 110010,
          Subtitle = ", so you're not going to ask me anything?",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C0"
        },
        [11017202] = {
          ContentFR = "Vous venez de dire qu’un soldat doit obéir sans condition.",
          DialogueId = 11017202,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9488C1",
          NextDialogue = 11017203,
          SpeakNpcId = 110022,
          Subtitle = "You just said soldiers must obey.",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C1"
        },
        [11017203] = {
          ContentFR = "Après tout ça, tu restes toujours aussi raide... comme un fichu morceau de bois.",
          DialogueId = 11017203,
          Duration = 3,
          GUID = "1B9488C2",
          NextDialogue = 11017204,
          SpeakNpcId = 110010,
          Subtitle = "Given what we've been through, are you really going to be as rigid as a piece of wood?",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C2"
        },
        [11017204] = {
          ContentFR = "Vous avez aussi dit qu’en combat, il faut rester concentré.",
          DialogueId = 11017204,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9488C3",
          NextDialogue = 11017205,
          SpeakNpcId = 110022,
          Subtitle = "You also said that one must fully concentrate when engaging in combat.",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C3"
        },
        [11017205] = {
          ContentFR = "La situation n’est pas sûre. Si vous perdez du temps à me faire des reproches, vous augmentez vos chances d’être touché.",
          DialogueId = 11017205,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9488C4",
          NextDialogue = 11017206,
          SpeakNpcId = 110022,
          Subtitle = "The current circumstances are perilous; being sidetracked by criticism might lead to casualties.",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C4"
        },
        [11017206] = {
          ContentFR = "{性别2:Petit insolent|Petite insolente} !",
          DialogueId = 11017206,
          Duration = 3,
          GUID = "1B9488C5",
          SpeakNpcId = 110010,
          Subtitle = "You sharp-tongued brat!",
          VoiceName = "voice/$Locale$/story/1002/110172/1B9488C5"
        },
        [11017301] = {
          ContentFR = "Ne me dis pas qu’il ne reste plus que toi des Griffons. Où est le reste de ton escouade ?",
          DialogueId = 11017301,
          Duration = 3,
          GUID = "1B909E29",
          NextDialogue = 11017302,
          SpeakNpcId = 110010,
          Subtitle = "Don't tell me you're the only Griffin left alive. Where are the rest of your squad?",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909E29"
        },
        [11017302] = {
          ContentFR = "Ils sont plus loin. La plupart sont grièvement blessés. Suivez-moi.",
          DialogueId = 11017302,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B909E30",
          NextDialogue = 11011013,
          SpeakNpcId = 110022,
          Subtitle = "They're right ahead. Most of them are heavily injured. Please follow me.",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909E30"
        },
        [11017401] = {
          DialogueId = 11017401,
          Duration = 2,
          GUID = "1B94B65A",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B65A"
        },
        [11017402] = {
          ContentFR = "Daphne a soigné les blessés.",
          DialogueId = 11017402,
          Duration = 2,
          GUID = "1B94B684",
          Subtitle = "Daphne treated the wounded.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B684"
        },
        [11017403] = {
          ContentFR = "Tu emmènes Katya et les autres loin de cet endroit...",
          DialogueId = 11017403,
          Duration = 2,
          GUID = "1B94B6AE",
          Subtitle = "You take Katya and the guys and leave this place...",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B6AE"
        },
        [11017404] = {
          ContentFR = "<I>Un... relais ? Quoi qu’il en soit, commençons par en couper un.</>",
          DialogueId = 11017404,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B6D8",
          SpeakNpcId = 110022,
          Subtitle = "This is... a relay. Anyway, just turn off one first.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B6D8"
        },
        [11017405] = {
          DialogueId = 11017405,
          Duration = 2,
          GUID = "1B94B702",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B702"
        },
        [11017406] = {
          ContentFR = "Pas un geste !",
          DialogueId = 11017406,
          Duration = 2,
          GUID = "1B909E34",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 110005,
          Subtitle = "Freeze!",
          VoiceName = "voice/$Locale$/story/1002/110110/1B909E34"
        },
        [11017407] = {
          ContentFR = "L’eau ne descend pas !",
          DialogueId = 11017407,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B756",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 11017408,
          SpeakNpcId = 110022,
          Subtitle = "The water won't go down!",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B756"
        },
        [11017408] = {
          ContentFR = "Contournons par le côté.",
          DialogueId = 11017408,
          Duration = 2,
          GUID = "1B94B780",
          SpeakNpcId = 110005,
          Subtitle = "Let's get through from the side.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B780"
        },
        [11017409] = {
          DialogueId = 11017409,
          Duration = 2,
          GUID = "1B94B7AA",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B7AA"
        },
        [11017410] = {
          Camera = "402.354004,84.89209,149.571686,0.000074,4.19976,-153.080948,21.458063,100000.0,false,Manual,22.0",
          ContentFR = "Accès autorisé. Veuillez poursuivre.",
          DialogueId = 11017410,
          Duration = 3,
          FinalCamera = "353.715454,60.211914,153.577911,0.000074,4.19976,-153.080948,21.458063,100000.0,false,Manual,22.0",
          GUID = "1B94B7D4",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Access granted. Please proceed.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B7D4"
        },
        [11017411] = {
          Content = "好，月髓连接上了【废弃】",
          DialogueId = 11017411,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B94B7FE",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B7FE"
        },
        [11017412] = {
          ContentFR = "Hein ? Bloqué. Il faudra faire un détour...",
          DialogueId = 11017412,
          Duration = 5,
          GUID = "1B94B828",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "Eh? It's blocked. Seems like we need to take a detour...",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B828"
        },
        [11017413] = {
          ContentFR = "L’interrupteur ne fonctionne pas encore. Je devrais peut-être d’abord activer la roue connectée.",
          DialogueId = 11017413,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B852",
          SpeakNpcId = 110022,
          Subtitle = "The switch doesn't work, maybe I should activate the connected Phoxynamo Wheel first.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B852"
        },
        [11017414] = {
          ContentFR = "<I>... Il faut vite activer l’interrupteur.</>",
          DialogueId = 11017414,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B87C",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(...Gotta turn it on quickly.)",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B87C"
        },
        [11017415] = {
          Content = "炮台的能源已经全部连通，回来汇合吧。【废弃】",
          DialogueId = 11017415,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 5,
          GUID = "1B94B8A6",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B8A6"
        },
        [11017416] = {
          Content = "准备好了，就激活髓动轮出发吧。",
          DialogueId = 11017416,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94B8D0",
          SpeakNpcId = 110010,
          Subtitle = "Go activate the Phoxynamo Wheels once you're ready.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B8D0"
        },
        [11017417] = {
          ContentFR = "<I>Suivons ces câbles jusqu’aux Roues Phoxynamo.</>",
          DialogueId = 11017417,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B8FA",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(These cables should lead me to the Phoxynamo Wheels.)",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B8FA"
        },
        [11017418] = {
          ContentFR = "Impressionnant...",
          DialogueId = 11017418,
          GUID = "1B94B924",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "That's amazing...",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B924"
        },
        [11017419] = {
          ContentFR = "<I>Trouvé... activons-la.</>",
          DialogueId = 11017419,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B94E",
          SpeakNpcId = 110022,
          Subtitle = "(Found it. Gotta activate it now.)",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B94E"
        },
        [11017420] = {
          ContentFR = "Ils appellent ça le « Champ de Bataille Simulé », et ils disent... « Cette fois, le thème est la défense de la cité de Givrelac ».",
          DialogueId = 11017420,
          GUID = "1B94B978",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017421,
          SpeakNpcId = 110034,
          Subtitle = "They refer to this place as a \"Simulated Battlefield,\" saying that... \"The theme this time is the Defence of Icelake City.\"",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B978"
        },
        [11017421] = {
          ContentFR = "J’ai entendu que cette cité était recouverte de neige. Je n’ai jamais vu de neige... J’aimerais tellement...",
          DialogueId = 11017421,
          GUID = "1B94B9A2",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017422,
          SpeakNpcId = 110034,
          Subtitle = "I heard that this Icelake City is covered in snow, something that I've never seen in my entire life... How I wish I could go there and see it myself!",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B9A2"
        },
        [11017422] = {
          ContentFR = "... Enfin, si j’arrive à rentrer vivante.",
          DialogueId = 11017422,
          GUID = "1B94B9CC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "...I mean, if, by any chance, I could make it out alive.",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B9CC"
        },
        [11017423] = {
          ContentFR = "<I>C’est fait.</>",
          DialogueId = 11017423,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94B9F6",
          SpeakNpcId = 110022,
          Subtitle = "(Done.)",
          VoiceName = "voice/$Locale$/story/1002/110174/1B94B9F6"
        },
        [11017501] = {
          ContentFR = "La salle des machines est le \"cœur\" de toute la forteresse. Toute l’énergie qui la maintient en fonctionnement vient du réservoir de Phoxichor.",
          DialogueId = 11017501,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C6C2",
          NextDialogue = 11017502,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_on\"},PlayAs2D{true}}",
          SpeakNpcId = 110010,
          Subtitle = "The engine room is the \"heart\" of the entire fortress, and all the power that keeps the fortress running comes from the Phoxichor tank in there.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C6C2"
        },
        [11017502] = {
          ContentFR = "Mais attaquer directement le réservoir provoquerait une explosion. Tu dois d’abord désactiver les <H>Roues Phoxynamo</> autour.",
          DialogueId = 11017502,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C6EC",
          SpeakNpcId = 110010,
          Subtitle = "But a direct attack would only lead to explosion, so you need to shut down the Phoxynamo Wheels around it first.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C6EC"
        },
        [11017503] = {
          Camera = "804.818848,157.511719,744.295471,0.000002,-8.800173,-4.800692,23.868748,100000.0,false,Manual,22.0",
          ContentFR = "Regarde ces roues, les bleues. Tu sais ce que tu as à faire : les passer au jaune.",
          DialogueId = 11017503,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C716",
          NextDialogue = 11017504,
          SpeakNpcId = 110010,
          Subtitle = "You should be able to recognise those wheels, aka the blue ones, right? What you need to do is turn them yellow.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C716"
        },
        [11017504] = {
          ContentFR = "Commandant, maîtriser les bases, ça fait longtemps que je sais faire, pas besoin de me tenir la main à chaque étape.",
          DialogueId = 11017504,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C740",
          NextDialogue = 11017505,
          SpeakNpcId = 110022,
          Subtitle = "I graduated a long time ago, Sir. You don't have to lead me through all the basic steps.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C740"
        },
        [11017505] = {
          ContentFR = "... {性别2:Petit impertinent|Petite impertinente} ! Alors débrouille-toi, je te contacterai si besoin.",
          DialogueId = 11017505,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C76A",
          SpeakNpcId = 110010,
          Subtitle = "...Alright kid, play it by ear then. I'll contact you if necessary.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C76A"
        },
        [11017506] = {
          ContentFR = "<I>Suivant les câbles au sol, je devrais pouvoir atteindre les Roues Phoxynamo. Espérons qu’elles ne soient pas trop bien cachées.</>",
          DialogueId = 11017506,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C794",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Following the cables on the ground may help me get to the Phoxynamo Wheels. I hope they're not too tricky to be found.)",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C794"
        },
        [11017507] = {
          ContentFR = "<I>Je commence par celle-ci.</>",
          DialogueId = 11017507,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C7BE",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(I'll shut down this one first.)",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C7BE"
        },
        [11017508] = {
          ContentFR = "<I>Bien, celle-ci est désactivée. Allons chercher les autres.</>",
          DialogueId = 11017508,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C7E8",
          NextDialogue = 11018203,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Alright, that's one down. Time to find the rest.)",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C7E8"
        },
        [11017509] = {
          ContentFR = "La porte à l’est est maintenant ouverte. Tu peux passer.",
          DialogueId = 11017509,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C812",
          SpeakNpcId = 110010,
          Subtitle = "The door due east is now open. You can go that way.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C812"
        },
        [11017510] = {
          ContentFR = "<I>Ils ont mis ces Roues Phoxynamo dans des endroits complètement tordus... Ces ingénieurs ne font jamais simple.</>",
          DialogueId = 11017510,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C83C",
          SpeakNpcId = 110022,
          Subtitle = "(Put the Phoxynamo Wheel in such a weird place... Those engineers sure know how to make things involved.)",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C83C"
        },
        [11017511] = {
          ContentFR = "<I>Celle-ci est désactivée.</>",
          DialogueId = 11017511,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C866",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(That should work.)",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C866"
        },
        [11017512] = {
          ContentFR = "<I>Encore trois à faire...</>",
          DialogueId = 11017512,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C890",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(That was complicated...)",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C890"
        },
        [11017513] = {
          ContentFR = "C’est quoi ce bruit... Tout va bien ?",
          DialogueId = 11017513,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94C8BA",
          NextDialogue = 11017514,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110010,
          Subtitle = "What's the noise... Everthing okay?",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C8BA"
        },
        [11017514] = {
          ContentFR = "<W>AVERTISSEMENT : Arrêt anormal détecté d’une Roue Phoxynamo. Redémarrage en cours.</>",
          DialogueId = 11017514,
          GUID = "1B94C8E4",
          NextDialogue = 11017515,
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "WARNING: Abnormal Phoxynamo Wheel shutdown detected. Re-activating Phoxynamo Wheels now.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C8E4"
        },
        [11017515] = {
          ContentFR = "... !",
          DialogueId = 11017515,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94C90E",
          SpeakNpcId = 110022,
          Subtitle = "...!",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C90E"
        },
        [11017516] = {
          Camera = "575.257935,395.707031,134.359619,-2.0,2.398653,-35.984066,35.000008,298.368286,false,Manual,20.0",
          ContentFR = "Nom d’un...",
          DialogueId = 11017516,
          Duration = 2,
          FinalCamera = "577.483826,398.757812,134.490234,-2.0,2.398653,-35.984066,35.000008,296.709473,false,Manual,20.0",
          GUID = "1B94C938",
          LookAt = {
            [1] = "110020:n(110010)"
          },
          NextDialogue = 11017517,
          SpeakNpcId = 110010,
          Subtitle = "Damn it!",
          TalkActionId = {
            [1] = "110010:Angry02_Start"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "110020:n(110010)"
          },
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C938"
        },
        [11017517] = {
          Camera = "692.426941,-1076.996094,583.005127,0.000022,-22.399378,90.009674,25.0,100000.0,false,DoNotOverride,20.0",
          ContentFR = "<W>AVERTISSEMENT : Risque de surcharge du réservoir de Phoxichor. Vérifiez si trop de Roues Phoxynamo ont été activées.</>",
          DialogueId = 11017517,
          Duration = 3,
          FinalCamera = "692.404907,-946.121094,529.065308,0.000022,-22.399378,90.009674,25.0,100000.0,false,DoNotOverride,20.0",
          GUID = "1B94C962",
          NextDialogue = 11017518,
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "WARNING: Phoxichor tank overload risk detected. Please check if more than required Phoxynamo Wheels have been activated.",
          TalkActionId = {
            [1] = "110010:Angry02_End"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C962"
        },
        [11017518] = {
          Camera = "728.906677,389.238281,185.978882,0.000161,-10.402897,-58.577694,50.000008,188.75177,false,Manual,22.0",
          ContentFR = "Risque de surcharge ?",
          DialogueId = 11017518,
          Duration = 3,
          FinalCamera = "740.300293,370.589844,181.966675,0.000161,-10.402897,-58.577694,50.000011,164.805725,false,Manual,22.0",
          GUID = "1B94C98C",
          NextDialogue = 11017519,
          Scripts = "PlayAnimation{_delay{3},ActorId{110010},AnimationId{\"Call_Start\"},Duration{1}}",
          SpeakNpcId = 110010,
          Subtitle = "Overload risk?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C98C"
        },
        [11017519] = {
          Camera = "538.932007,61.714844,122.000732,-2.0,2.799223,36.418335,35.000008,100000.0,false,DoNotOverride,20.0",
          ContentFR = "... Écoute, {nickname2}, va au sous-sol de la salle des machines, active toutes les Roues Phoxynamo de secours, puis évacue immédiatement.",
          DialogueId = 11017519,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "542.133667,57.402344,121.813232,-2.0,2.799223,36.418335,35.000008,100000.0,false,DoNotOverride,20.0",
          GUID = "1B94C9B6",
          NextDialogue = 11017520,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/signal_on\"},PlayAs2D{true}}",
          SpeakNpcId = 110010,
          Subtitle = "Listen, . I need you to go to the lower floor of the engine room, activate all the back-up Phoxynamo Wheels, then evacuate immediately.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C9B6"
        },
        [11017520] = {
          Camera = "699.135376,388.0625,157.425171,10.009494,-3.598785,-51.594585,40.0,100000.0,false,DoNotOverride,20.0",
          ContentFR = "Puisque les moyens conventionnels ne suffisent pas, laisse le réservoir se surcharger et s’auto-détruire.",
          DialogueId = 11017520,
          Duration = 3,
          FacialId = {
            [1] = "110010:Angry01"
          },
          FinalCamera = "699.135376,388.0625,156.380249,10.010453,-3.598785,-51.595715,40.0,100000.0,false,DoNotOverride,20.0",
          GUID = "1B94C9E0",
          NextDialogue = 11017521,
          SpeakNpcId = 110010,
          Subtitle = "Since we can't shut them down our way, we can let them do it in a self-destructive way.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110175/1B94C9E0"
        },
        [11017521] = {
          Camera = "992.544189,397.238281,178.074951,-0.0,-8.599126,-138.38974,40.000011,100000.0,false,DoNotOverride,20.0",
          ContentFR = "Vous voulez dire... provoquer l’explosion du réservoir par surcharge ? Compris.",
          DialogueId = 11017521,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94CA0A",
          Scripts = "PlayNormalSound{_delay{5},EventPath{\"event:/sfx/common/story/ex01/signal_off\"},PlayAs2D{true}}",
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110022,
          Subtitle = "You mean... exploding the Phoxichor tank by overloading it? Got it.",
          VoiceName = "voice/$Locale$/story/1002/110175/1B94CA0A"
        },
        [11017601] = {
          ContentFR = "La Roue Phoxynamo de secours n° 1 est prête. Active-la.",
          DialogueId = 11017601,
          GUID = "1B94D72A",
          SpeakNpcId = 110010,
          Subtitle = "Back-up Phoxynamo Wheel No.1 is ready. Now activate it.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D72A"
        },
        [11017602] = {
          ContentFR = "Bien joué. Je débloque les trois autres Roues Phoxynamo de secours.",
          DialogueId = 11017602,
          GUID = "1B94D754",
          NextDialogue = 11017603,
          SpeakNpcId = 110010,
          Subtitle = "Well done. I'll unlock the control authority for the remaining three Phoxynamo Wheels.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D754"
        },
        [11017603] = {
          ContentFR = "Quand la lumière jaune s’allume, tu les actives.",
          DialogueId = 11017603,
          GUID = "1B94D77E",
          SpeakNpcId = 110010,
          Subtitle = "Activate them once the yellow light is on.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D77E"
        },
        [11017604] = {
          ContentFR = "<I>La lumière est allumée. Apparemment, le Commandant Avar a réussi de son côté.</>",
          DialogueId = 11017604,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94D7A8",
          SpeakNpcId = 110022,
          Subtitle = "(The light is on. Looks like Sir Avar has made it on his side.)",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D7A8"
        },
        [11017605] = {
          ContentFR = "<W>AVERTISSEMENT : Surcharge du réservoir de Phoxichor à 50 %. Arrêtez immédiatement l’utilisation des Roues Phoxynamo, départ non autorisé interdit.</>",
          DialogueId = 11017605,
          GUID = "1B94D7D2",
          NextDialogue = 11017606,
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "WARNING: Phoxichor tank is overloaded by 50%. Please shut down the Phoxynamo Wheels immediately; unauthorized departure is not permitted.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D7D2"
        },
        [11017606] = {
          ContentFR = "<I>... Il faut que je me dépêche.</>",
          DialogueId = 11017606,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94D7FC",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(...I need to hurry up.)",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D7FC"
        },
        [11017607] = {
          ContentFR = "La n° 3 est prête, vas-y !",
          DialogueId = 11017607,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94D826",
          SpeakNpcId = 110010,
          Subtitle = "No.3 is also ready. Go get it!",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D826"
        },
        [11017608] = {
          ContentFR = "<I>Pfiou...</>",
          DialogueId = 11017608,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94D850",
          NextDialogue = 11017609,
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Phew...)",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D850"
        },
        [11017609] = {
          ContentFR = "Net et rapide, bien joué, {性别2:petit|petite} !",
          DialogueId = 11017609,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94D87A",
          SpeakNpcId = 110010,
          Subtitle = "Quick and clean! Well done, kid.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D87A"
        },
        [11017610] = {
          ContentFR = "L’autorité de contrôle est déverrouillée. La dernière roue est prête !",
          DialogueId = 11017610,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94D8A4",
          SpeakNpcId = 110010,
          Subtitle = "The control authority is unlocked. This is the last one!",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D8A4"
        },
        [11017611] = {
          ContentFR = "<W>AVERTISSEMENT : Sabotage du réservoir de Phoxichor détecté. Toute personne responsable doit se dénoncer.</>",
          DialogueId = 11017611,
          GUID = "1B94D8CE",
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "WARNING: Phoxichor tank sabotage detected. Anyone held responsible should confess your crime.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D8CE"
        },
        [11017612] = {
          ContentFR = "Vite ! Mets-toi derrière la porte de sécurité !",
          DialogueId = 11017612,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B94D8F8",
          NextDialogue = 11017613,
          SpeakNpcId = 110010,
          Subtitle = "Run! Get behind the safety door!",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D8F8"
        },
        [11017613] = {
          ContentFR = "<W>AVERTISSEMENT : Sabotage du réservoir de Phoxichor détecté. Toute personne responsable doit se dénoncer.</>",
          DialogueId = 11017613,
          GUID = "1B94D922",
          SnapShot = "BROADCAST",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "WARNING: Phoxichor tank sabotage detected. Anyone held responsible should confess your crime.",
          VoiceName = "voice/$Locale$/story/1002/110176/1B94D922"
        },
        [11017701] = {
          ContentFR = "Capitaine, suivez-moi par ici...",
          DialogueId = 11017701,
          GUID = "1B94E792",
          SpeakNpcId = 110017,
          Subtitle = "This way, sir...",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E792"
        },
        [11017702] = {
          ContentFR = "Capitaine, par ici... on peut descendre dans les égouts.",
          DialogueId = 11017702,
          GUID = "1B94E7BC",
          NextDialogue = 11017703,
          SpeakNpcId = 110017,
          Subtitle = "Sir, we can get into the sewer tunnels from here.",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E7BC"
        },
        [11017703] = {
          ContentFR = "Vas-y en premier, Charon.",
          DialogueId = 11017703,
          GUID = "1B94E7E6",
          NextDialogue = 11017704,
          SpeakNpcId = 110016,
          Subtitle = "You go first, Charon.",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E7E6"
        },
        [11017704] = {
          ContentFR = "O-Oui...",
          DialogueId = 11017704,
          GUID = "1B94E810",
          SpeakNpcId = 110017,
          Subtitle = "Yes, sir...",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E810"
        },
        [11017705] = {
          ContentFR = "Cette vapeur...",
          DialogueId = 11017705,
          GUID = "1B94E83A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017706,
          SpeakNpcId = 110034,
          Subtitle = "The hot steam...",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E83A"
        },
        [11017706] = {
          ContentFR = "Attention ! Il y a un condenseur devant. Trop près, vous risquez de vous blesser !",
          DialogueId = 11017706,
          GUID = "1B94E864",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "Watch out! There's a condenser up ahead. You'll get hurt if you get too close!",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E864"
        },
        [11017707] = {
          ContentFR = "Capitaine... La vapeur du condenseur est très dangereuse. Nous ne devons pas y rester trop longtemps.",
          DialogueId = 11017707,
          GUID = "1B94E88E",
          SpeakNpcId = 110017,
          Subtitle = "Sir... Steam produced by the condenser is dangerous. We should not stay too long.",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E88E"
        },
        [11017708] = {
          ContentFR = "Haa... haa... Il fait tellement chaud... Capitaine, vous allez bien ?",
          DialogueId = 11017708,
          GUID = "1B94E8B8",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "Huff, huff... It's so hot... Are you okay, sir?",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E8B8"
        },
        [11017709] = {
          ContentFR = "Capitaine, par ici...",
          DialogueId = 11017709,
          GUID = "1B94E8E2",
          NextDialogue = 11017710,
          SpeakNpcId = 110017,
          Subtitle = "This way, sir...",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E8E2"
        },
        [11017710] = {
          ContentFR = "Des So-Souillés... !",
          DialogueId = 11017710,
          GUID = "1B94E90C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017711,
          SpeakNpcId = 110034,
          Subtitle = "Fil...Filthoids!",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E90C"
        },
        [11017711] = {
          ContentFR = "Les civils derrière moi.",
          DialogueId = 11017711,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94E936",
          SpeakNpcId = 110022,
          Subtitle = "The unarmed retreat behind me.",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E936"
        },
        [11017712] = {
          ContentFR = "Merci de nous avoir sauvés ! Finalement, tous les soldats impériaux ne sont pas...",
          DialogueId = 11017712,
          GUID = "1B94E960",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 11017713,
          SpeakNpcId = 110034,
          Subtitle = "Thank you for saving our lives! It turned out not all the Imperial soldiers are...",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E960"
        },
        [11017713] = {
          ContentFR = "Ah, pardon ! Je voulais dire, je pensais autrefois que les soldats impériaux étaient aussi brutaux que les Déchus. Mais maintenant, je sais que je me trompais !",
          DialogueId = 11017713,
          GUID = "1B94E98A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 110034,
          Subtitle = "Ah, sorry! I mean, I used to think that Imperial soldiers were no different from those Forsaken rotters. But now I know I was wrong!",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E98A"
        },
        [11017714] = {
          ContentFR = "Là-bas... c’est le Commandant Avar !",
          DialogueId = 11017714,
          GUID = "1B94E9B4",
          NextDialogue = 11017715,
          SpeakNpcId = 110015,
          Subtitle = "Over there is... Sir Avar!",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E9B4"
        },
        [11017715] = {
          ContentFR = "<I>Bien, nous voilà enfin tous réunis et sains et saufs.</>",
          DialogueId = 11017715,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94E9DE",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Nice, we can safely join forces with them.)",
          VoiceName = "voice/$Locale$/story/1002/110177/1B94E9DE"
        },
        [11017801] = {
          ContentFR = "Halte.",
          DialogueId = 11017801,
          GUID = "1B94F7FA",
          SpeakNpcId = 110010,
          Subtitle = "Here it is.",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F7FA"
        },
        [11017802] = {
          ContentFR = "Belle vue... C’est l’endroit parfait pour ouvrir le feu sur la salle de commande centrale.",
          DialogueId = 11017802,
          GUID = "1B94F824",
          SpeakNpcId = 110010,
          Subtitle = "The view is good. Let's bombard the central control room from here.",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F824"
        },
        [11017803] = {
          ContentFR = "Mince...",
          DialogueId = 11017803,
          GUID = "1B94F84E",
          SpeakNpcId = 110010,
          Subtitle = "Damn it...",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F84E"
        },
        [11017804] = {
          ContentFR = "Occupe-toi des Souillés d’abord ! Ne les laisse pas te gêner !",
          DialogueId = 11017804,
          GUID = "1B94F878",
          SpeakNpcId = 110010,
          Subtitle = "Take down the Filthoids first. Don't let them distract you!",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F878"
        },
        [11017805] = {
          ContentFR = "Bien. Le secteur est sûr.",
          DialogueId = 11017805,
          GUID = "1B94F8A2",
          NextDialogue = 11017806,
          SpeakNpcId = 110010,
          Subtitle = "Alright, all cleared out.",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F8A2"
        },
        [11017806] = {
          ContentFR = "Maintenant, concentrons le tir sur la <H>porte latérale</>, elle est plus fragile.",
          DialogueId = 11017806,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94F8CC",
          SpeakNpcId = 110010,
          Subtitle = "Next, let's start with the relatively thin side door.",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F8CC"
        },
        [11017807] = {
          ContentFR = "Continue ! Utilise les Obus explosifs !",
          DialogueId = 11017807,
          GUID = "1B94F8F6",
          SpeakNpcId = 110010,
          Subtitle = "Keep it up! Use the High-Explosive Shells!",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F8F6"
        },
        [11017808] = {
          ContentFR = "Ça suffit ! Allons-y.",
          DialogueId = 11017808,
          GUID = "1B94F920",
          SpeakNpcId = 110010,
          Subtitle = "That's our cue — move in.",
          VoiceName = "voice/$Locale$/story/1002/110186/1B957C0C"
        },
        [11017809] = {
          ContentFR = "Ne reste pas planté là ! Tire !",
          DialogueId = 11017809,
          GUID = "1B94F94A",
          SpeakNpcId = 110010,
          Subtitle = "Snap out of it! Keep firing!",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F94A"
        },
        [11017810] = {
          ContentFR = "Tout va bien ? Tu es {性别2:blessé|blessée} ?",
          DialogueId = 11017810,
          GUID = "1B94F974",
          SpeakNpcId = 110010,
          Subtitle = "Are you okay? Did you get hurt?",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F974"
        },
        [11017811] = {
          ContentFR = "Si tu continues comme ça, ma fille sera grand-mère avant que tu ne l’aies ouverte ! Retourne au canon.",
          DialogueId = 11017811,
          GUID = "1B94F99E",
          SpeakNpcId = 110010,
          Subtitle = "I'll be an old man by the time you break the door with that! Go back to the cannon.",
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F99E"
        },
        [11017812] = {
          DialogueId = 11017812,
          GUID = "1B94F9C8",
          IsBlack = 1,
          VoiceName = "voice/$Locale$/story/1002/110178/1B94F9C8"
        },
        [11017901] = {
          ContentFR = "Allez. Restez en contact et soyez prudent.",
          DialogueId = 11017901,
          GUID = "1B950862",
          SpeakNpcId = 110010,
          Subtitle = "Go, stay in touch, and be careful.",
          VoiceName = "voice/$Locale$/story/1002/110179/1B950862"
        },
        [11017902] = {
          ContentFR = "Vic...",
          DialogueId = 11017902,
          GUID = "1B95088C",
          SpeakNpcId = 110020,
          Subtitle = "Vic...",
          VoiceName = "voice/$Locale$/story/1002/110179/1B95088C"
        },
        [11017903] = {
          ContentFR = "Dès que vous êtes {性别2:prêt|prête}, activez les Roues Phoxynamo et on se met en route.",
          DialogueId = 11017903,
          GUID = "1B9508B6",
          SpeakNpcId = 110010,
          Subtitle = "Activate the Phoxynamo Wheels and set off whenever you're ready.",
          VoiceName = "voice/$Locale$/story/1002/110179/1B9508B6"
        },
        [11018001] = {
          Camera = "-1102.632935,-197.335449,128.499756,0.000169,-1.399683,12.991217,50.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Attends.",
          DialogueId = 11018001,
          GUID = "1B9518CA",
          LookAt = {
            [1] = "110022:n(110010)",
            [2] = "110034:n(110010)",
            [3] = "110015:n(110010)",
            [4] = "110017:n(110010)"
          },
