        },
        [11018203] = {
          Content = "（好，关停了。去找其他几台髓动轮吧。）",
          DialogueId = 11018203,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9539EE",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Alright, that's one down. Time to find the rest.)",
          VoiceName = "voice/$Locale$/story/1002/110182/1B9539EE"
        },
        [11018204] = {
          ContentFR = "L’uniforme de l’homme, flambant neuf, est en lambeaux. Sous le tissu déchiré, les griffures et morsures sont nombreuses. Il a clairement été déchiqueté par une horde de Souillés. Ses mains crispées sur la lame brisée témoignent qu’il s’est battu jusqu’au bout.",
          DialogueId = 11018204,
          GUID = "1B953A18",
          NextDialogue = 11018205,
          Subtitle = "His uniform — freshly issued — is in tatters. Beneath the torn fabric, claw slashes and bite marks mar his body. He was clearly ripped apart by a swarm of Filthoids. In his lifeless grasp, a broken blade — knuckles pale and stiff — a silent testament that he fought to the bitter end.",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953A18"
        },
        [11018205] = {
          ContentFR = "À côté de lui, une plaque d’identité repose silencieusement. Tu la reconnais immédiatement : standard pour les nouvelles recrues. Au recto, son nom : Vic Girard. Au verso, un message gravé au couteau : « Monica, la prochaine fois, je te bats au concours de tir. »",
          DialogueId = 11018205,
          GUID = "1B953A42",
          Subtitle = "Beside him, an identity disc lies quietly. You recognise it instantly — standard issue for fresh recruits. The front reads: Vic Girard. On the back, a message scratched in with a blade: \"Monica — next time, I'm beating you at the shooting range.\"",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953A42"
        },
        [11018206] = {
          ContentFR = "<I>On dirait que la destruction du réservoir Phoxichor a tout mis hors service.</>",
          DialogueId = 11018206,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953A6C",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Looks like destroying the Phoxichor tank knocked everything offline.)",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953A6C"
        },
        [11018207] = {
          ContentFR = "Ces monstres... ce sont eux qui... !",
          DialogueId = 11018207,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953A96",
          NextDialogue = 11018208,
          SpeakNpcId = 110022,
          Subtitle = "These beasts... They killed everyone...",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953A96"
        },
        [11018208] = {
          ContentFR = "<W>Oui... exactement. Laisse la haine brûler ton cœur. Tu n’as jamais désiré le sang comme aujourd’hui.</>",
          DialogueId = 11018208,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953AC0",
          NextDialogue = 11018209,
          SnapShot = "MONSTER",
          Subtitle = "Yes... let that hatred fester. You've never craved blood like this before, have you?",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953AC0"
        },
        [11018209] = {
          ContentFR = "<W>Ils ne pleurent pas. Ils ne sentent rien. Mais toi, tu veux leur faire payer...</>",
          DialogueId = 11018209,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953AEA",
          NextDialogue = 11018210,
          SnapShot = "MONSTER",
          Subtitle = "If only they could bleed. If only they could weep. Then maybe they'd understand the fire roaring in your chest.",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953AEA"
        },
        [11018210] = {
          ContentFR = "<W>Alors frappe. Encore... et encore... et encore...</>",
          DialogueId = 11018210,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953B14",
          NextDialogue = 11018211,
          SnapShot = "MONSTER",
          Subtitle = "But none of that matters now. Just raise your blade. Swing it. Again — and again.",
          VoiceName = "voice/$Locale$/story/1002/110182/1B953B14"
        },
        [11018211] = {
          ContentFR = "<I>Non ! Je ne peux pas...</>",
          DialogueId = 11018211,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B953B3E",
          NextDialogue = 11018212,
