SEQ{
CameraMoveTo{_delay{0.5},TargetPosition{"-44.542969,-185.030273,185.652344,0.000056,-10.200437,87.394356,31.194523,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"-44.542969,-185.030273,185.652344,0.000056,-9.600492,81.393951,31.194523,100000.0,false,DoNotOverride,22.0"},duration{8}}
}
}
]],
          SpeakNpcId = 110018,
          Subtitle = "That last piece, Children From the Snowfield, was composed by Cavaradossi. It was inspired by a folktale in his hometown, Icelake — one about a mystical creature that roams the snowy wilderness... You're not really listening, are you, ?",
          TalkActionId = {
            [1] = "110018:Talk03_Start",
            [2] = "110022:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CE92"
        },
        [11019110] = {
          Camera = "98.070312,162.706055,155.070312,0.00008,-5.000156,83.993164,40.0,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Ah ? Oui, tu parlais d’une créature mystérieuse ? À Givrelac ?",
          DialogueId = 11019110,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95CEBC",
          LookAt = {
            [1] = "110022:n(110018)"
          },
          NextDialogue = 11019111,
          SpeakNpcId = 110022,
          Subtitle = "Huh? Yeah... something about a mystical creature? In Icelake?",
          TalkActionId = {
            [1] = "110022:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CEBC"
        },
        [11019111] = {
          Camera = "265.580078,432.883789,136.324219,0.000048,-0.600217,-131.199738,31.194523,532.562439,false,Manual,4.15071",
          ContentFR = "... Je vois que tu es toujours {性别2:préoccupé|préoccupée}. J’espérais que cela te changerait un peu les idées. ",
          DialogueId = 11019111,
          FinalCamera = "272.865234,426.507812,136.324219,0.000048,-0.600217,-131.199738,31.194523,532.562439,false,Manual,4.15071",
          GUID = "1B95CEE6",
          LookAt = {
            [1] = "110018:n(110018)"
          },
          NextDialogue = 11019112,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{4.01},TargetPosition{"-63.695312,-164.354492,174.359375,0.000116,-5.400268,75.38089,45.0,135.993378,false,Manual,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"-56.982422,-166.160156,174.359375,0.000117,-5.600284,76.579796,45.0,479.429016,false,Manual,22.0"},duration{8}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "Thought so. Still carrying the weight, I see. I'd hoped this might offer a brief escape.",
          TalkActionId = {
            [1] = "110018:DisagreeHead"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CEE6"
        },
        [11019112] = {
          ContentFR = "À propos du rôle de \"garde du corps\"... je dois savoir ce que cela implique. J’ai quelque chose à faire, je dois savoir si ça gênera.",
          DialogueId = 11019112,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95CF10",
          NextDialogue = 11019113,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{6.01},TargetPosition{"212.978516,356.34375,65.824219,0.000064,10.1995,-132.999237,31.194523,532.562439,false,Manual,4.15071"},duration{0}},
CameraMoveTo{TargetPosition{"212.978516,356.34375,65.824219,0.000064,10.1995,-132.999237,31.194523,105.220139,false,Manual,22.0"},duration{2}}
},
PlayAnimation{_delay{4.5},ActorId{110022},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{_delay{6.5},ActorId{110022},AnimationId{"Fist02_Start"},Duration{1}}
}]],
          SpeakNpcId = 110022,
          Subtitle = "About that \"bodyguard\" role you mentioned... I need to know what it actually entails. There's something I have to deal with — I need to know if this gets in the way.",
          TalkActionId = {
            [1] = "110022:Talk02_Start",
            [2] = "110018:Talk03_End"
          },
          TurnTo = {
            [1] = "110018:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CF10"
        },
        [11019113] = {
          Camera = "150.314453,114.749023,93.257812,0.000076,12.398924,-146.393463,31.194523,265.276245,false,Manual,2.500234",
          ContentFR = "C’est justement ce dont je voulais te parler aujourd’hui. Je dois me rendre à Rougerive, dans la province de Flagson, pour environ six mois. Pendant ce temps, tu seras à mes côtés comme garde rapprochée.",
          DialogueId = 11019113,
          FacialId = {
            [1] = "110022:None"
          },
          FinalCamera = "157.380859,103.807617,93.257812,0.000082,12.39891,-147.592407,31.194523,265.276245,false,Manual,2.500234",
          GUID = "1B95CF3A",
          NextDialogue = 11017113,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"98.070312,162.706055,155.070312,0.00008,-5.000156,83.993126,40.0,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"89.480469,163.738281,155.070312,0.000084,-4.600125,78.992691,40.0,100000.0,false,DoNotOverride,22.0"},duration{10}}
},
PlayAnimation{_delay{9.01},ActorId{110018},AnimationId{"Confident_End"},Duration{1}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "That's what I wanted to talk to you about. So, I've been assigned to Scarletriver on royal orders — a six-month posting, give or take. It would ease my mind to have you accompany me.",
          TalkActionId = {
            [1] = "110022:Fist02_End",
            [2] = "110018:Confident_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CF3A"
        },
        [11019115] = {
          Camera = "27.921875,-356.951172,536.433594,0.000073,-35.199646,124.770035,45.0,100000.0,false,Manual,22.0",
          ContentFR = "Il y a cinq jours, mon frère aîné m’a convoqué pour une audience, afin que j’effectue une visite à Rougerive au nom de la couronne. J’en ai profité pour lui proposer de t’avoir comme garde rapproché à mes côtés, et il a accepté.",
          DialogueId = 11019115,
          FinalCamera = "-9.732422,-383.087891,536.433594,0.000073,-35.199646,124.770035,45.0,100000.0,false,Manual,22.0",
          GUID = "1B95CF8E",
          NextDialogue = 11019116,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6.01},TargetPosition{"143.337891,24.485352,118.726562,0.000105,12.600271,-165.22699,45.0,100000.0,false,DoNotOverride,22.0"},duration{0}},
CameraMoveTo{TargetPosition{"144.664062,19.453125,118.726562,0.000105,12.600271,-165.227493,45.0,100000.0,false,DoNotOverride,22.0"},duration{8}}
}]],
          SpeakNpcId = 110018,
          Subtitle = "I submitted your name as my aide when I met with my brother five days ago. He approved.",
          TalkActionId = {
            [1] = "110018:Talk03_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CF8E"
        },
        [11019116] = {
          Camera = "154.613281,113.302734,105.09375,0.000112,9.199677,106.796791,31.194523,100000.0,false,DoNotOverride,22.0",
          ContentFR = "Tu veux que je quitte Dismania pour aller à Rougerive ?",
          DialogueId = 11019116,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95CFB8",
          NextDialogue = 11017116,
          SpeakNpcId = 110022,
          Subtitle = "So you're asking me to leave Dismania... and head for Scarletriver, Flagson?",
          TalkActionId = {
            [1] = "110022:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110191/1B95CFB8"
        },
        [11019119] = {
          Camera = "207.460938,360.240234,139.1875,0.000101,-0.600462,-130.806396,31.194527,446.287842,false,Manual,11.834087",
          ContentFR = "Je comprends. Alors, j’y vais. Ce que je cherche est sur le chemin de toute façon. Dois-je vous prêter serment, Votre Altesse ?",
          DialogueId = 11019119,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95D036",
          NextDialogue = 11017119,
          Scripts = [[
PARA{
PlayAnimation{_delay{8},ActorId{110022},AnimationId{"Explain02_Start"},Duration{3}},
CameraMoveTo{_delay{7.5},TargetPosition{"149.958984,156.460938,171.972656,0.000133,-12.599397,104.987122,35.000008,506.425873,false,DoNotOverride,22.0"},duration{0}}
}]],
          SpeakNpcId = 110022,
          Subtitle = "Understood. Then I'll go. What I'm looking for lies in the same direction anyway. Shall I swear an oath of service, Your Highness?",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110191/1B95D036"
        },
        [11019121] = {
          ContentFR = "Prépare tes affaires, nous partons dans trois jours.",
          DialogueId = 11019121,
          GUID = "1B95D08A",
          LookAt = {
            [1] = "110018:n(110018)"
          },
          NextDialogue = 11019122,
          Scripts = "MoveTo{ActorId{110022},TargetPoint{\"BP_EX01_FixSimple_29_nanzhu02\"},MoveSpeed{75},Visibility{\"Show\"}}",
          SpeakNpcId = 110018,
          Subtitle = "Pack your things. We'll leave in three days.",
          TurnTo = {
            [1] = "110018:p(-170)"
          },
          VoiceName = "voice/$Locale$/story/1002/110191/1B95D08A"
        },
        [11019122] = {
          ContentFR = "Bien.",
          DialogueId = 11019122,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95D0B4",
          SpeakNpcId = 110022,
          Subtitle = "Sure.",
          TalkActionId = {
            [1] = "110022:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110191/1B95D0B4"
        },
        [11019123] = {
          ContentFR = "<I>Flagson...</>",
          DialogueId = 11019123,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95D0DE",
          NextDialogue = 11019124,
          SpeakNpcId = 110022,
          Subtitle = "(Flagson...)",
          VoiceName = "voice/$Locale$/story/1002/110191/1B95D0DE"
        },
        [11019124] = {
          ContentFR = "<I>Il y a quelque chose là-bas... que je n’ai pas dit à la Geôlière...</>",
          DialogueId = 11019124,
          ExStoryInfo = "EXPlayer",
          GUID = "1B9488BE",
          NextDialogue = 11019125,
          SpeakNpcId = 110022,
          Subtitle = "(There is something there... that I didn't even tell the Warden...)",
          VoiceName = "voice/$Locale$/story/1002/110171/1B9488BE"
        },
        [11019125] = {
          ContentFR = "<I>L’autre pièce du Projet Nouvel Héritier, le Catalyseur de n° 0...</>",
          DialogueId = 11019125,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95D132",
          SpeakNpcId = 110022,
          Subtitle = "(The other piece of the Second Scion Program — the catalyst of No. 0...)",
          VoiceName = "voice/$Locale$/story/1002/110191/1B95D132"
        },
        [11019201] = {
          ContentFR = "Eh, qu’est-ce que tu fais là ? Pourquoi tu t’accroupis ?",
          DialogueId = 11019201,
          GUID = "1B95DDAA",
          IsBlack = 1,
          NextDialogue = 11019202,
          SpeakNpcId = 110015,
          Subtitle = "Hey, what's wrong? Why are you squatting down?",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDAA"
        },
        [11019202] = {
          ContentFR = "Arrête ton numéro, je n’entrerai pas dans ton jeu ! Lève-toi et viens !",
          DialogueId = 11019202,
          GUID = "1B95DDD4",
          IsBlack = 1,
          NextDialogue = 11012303,
          SpeakNpcId = 110015,
          Subtitle = "Don't you play the victim here! I won't buy it! Get up and go!",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD4"
        },
        [11019203] = {
          ContentFR = "Par ici !",
          DialogueId = 11019203,
          GUID = "1B95DDD5",
          SpeakNpcId = 110034,
          Subtitle = "This way!",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD5"
        },
        [11019204] = {
          ContentFR = "...",
          DialogueId = 11019204,
          GUID = "1B95DDD6",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD6"
        },
        [11019205] = {
          ContentFR = "<I>C’est un monte-charge... je pourrais peut-être récupérer des provisions. Mais je dois rester sur mes gardes, une embuscade est possible.</>",
          DialogueId = 11019205,
          DisableMouth = 1,
          GUID = "1B95DDD7",
          SnapShot = "HEART",
          Subtitle = "(A cargo lift. Could be a good chance to resupply... but I'd better stay alert. Could be an ambush.)",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD7"
        },
        [11019206] = {
          ContentFR = "Pour l’instant la zone est sûre. Je peux accéder au terminal.",
          DialogueId = 11019206,
          GUID = "1B95DDD8",
          Subtitle = "Room's clear for now. Time to access the control panel.",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD8"
        },
        [11019207] = {
          ContentFR = "Autorisation en cours. Veuillez patienter...",
          DialogueId = 11019207,
          GUID = "1B95DDD9",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Authorising access. Please wait...",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD9"
        },
        [11019208] = {
          ContentFR = "<I>La salle de commande centrale est alimentée séparément... Les Roues Phoxynamo n’ont donc pas été affectées par l’explosion de la salle des machines.</>",
          DialogueId = 11019208,
          GUID = "1B95DDDA",
          Subtitle = "(So the Central Control Room runs on a separate grid... That's why the blast didn't reach this part.)",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDDA"
        },
        [11019209] = {
          ContentFR = "Erreur de flux énergétique. Le terminal est passé en mode de protection. Veuillez désactiver les Roues Phoxynamo pour lever le verrouillage.",
          DialogueId = 11019209,
          GUID = "1B95DDDB",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Power flow error detected. Control panel locked for protection. Please shut down all Phoxynamo Wheels to lift the lock.",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDDB"
        },
        [11019301] = {
          ContentFR = "...",
          DialogueId = 11019301,
          GUID = "1B95EE12",
          IsBlack = 1,
          NextDialogue = 11019302,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/searchcloth\"},PlayAs2D{true}}",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110193/1B95EE12"
        },
        [11019302] = {
          ContentFR = "Falsi... fais... sauter... salle... commande...",
          DialogueId = 11019302,
          GUID = "1B95EE3C",
          IsBlack = 1,
          NextDialogue = 11019303,
          Scripts = [[
SEQ{
PlayNormalSound{EventPath{"event:/sfx/common/story/ex01/signal_on"},PlayAs2D{true}},
PlayNormalSound{_delay{4},EventPath{"event:/sfx/common/story/ex01/signal_off"},PlayAs2D{true}}			
}	]],
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "Falsi... blow up... control room...",
          VoiceName = "voice/$Locale$/story/1002/110193/1B95EE3C"
        },
        [11019303] = {
          ContentFR = "À vos ordres.",
          DialogueId = 11019303,
          GUID = "1B95EE66",
          IsBlack = 1,
          NextDialogue = 11019304,
          SpeakNpcId = 110012,
          Subtitle = "Yes, sir.",
          VoiceName = "voice/$Locale$/story/1002/110193/1B95EE66"
        },
        [11019304] = {
          ContentFR = "...",
          DialogueId = 11019304,
          GUID = "1B95EE90",
          IsBlack = 1,
          NextDialogue = 11013705,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/searchcloth\"},PlayAs2D{true}}",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/110193/1B95EE90"
        },
        [11019305] = {
          Camera = "-116.337891,3.070312,10.207031,0.000024,-24.999084,-96.199112,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Avar ne montre plus aucun signe de vie. Sur lui : une dague réglementaire, une lampe tactique, un communicateur brisé et une dose d’adrénaline.",
          DialogueId = 11019305,
          FinalCamera = "-92.930893,-64.451172,22.968384,0.000019,-34.599201,-103.998398,25.000002,100000.0,false,DoNotOverride,2.8",
          GUID = "1B95EEBA",
          NextDialogue = 11014002,
          Subtitle = "(Avar shows no signs of life. All he has on him are a standard-issue combat knife, a tactical flashlight, a broken comms terminal, and one dose of adrenaline.)",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110193/1B95EEBA"
        },
        [11019306] = {
          Camera = "-179.412964,-186.140625,-9.101074,0.000056,9.994964,89.912399,35.000011,76.53801,false,Manual,22.0",
          ContentFR = "<I>Je n’ai plus de temps...</>",
          DialogueId = 11019306,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95EEE4",
          NextOptions = {
            [1] = 11019307
          },
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(Time's running out...)",
          VoiceName = "voice/$Locale$/story/1002/110193/1B95EEE4"
        },
        [11019307] = {
          ContentFR = "<I>S’injecter la dose d’adrénaline</>",
          DialogueId = 11019307,
          GUID = "1B95EF0E",
          NextDialogue = 11019308,
          Subtitle = "Inject adrenaline"
        },
        [11019308] = {
          ContentFR = "<I>Ça devrait me maintenir debout un moment... Je dois sortir d’ici, vite !</>",
          DialogueId = 11019308,
          DisableMouth = 1,
          ExStoryInfo = "EXPlayer",
          GUID = "1B95EF38",
          SnapShot = "HEART",
          SpeakNpcId = 110022,
          Subtitle = "(This should keep me going for a while... I need to get out of here now!)",
          VoiceName = "voice/$Locale$/story/1002/110193/1B95EF38"
        },
        [11019309] = {
          ContentFR = "Voilà... le saignement s’est enfin arrêté.",
          DialogueId = 11019309,
          GUID = "1B95EF62",
          NextDialogue = 11014202,
          SpeakNpcId = 110005,
          Subtitle = "There... The bleeding's finally stopped.",
          TalkActionId = {
            [1] = "110022:Weita_Story_Hurt_End",
            [2] = "110005:Dafu_Story_Cure_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110193/1B95EF62"
        },
        [11019310] = {
          Camera = "215.741455,377.273804,510.410156,0.000119,-47.785801,-115.977509,12.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Expliquez ceci, pourquoi les Narvals ont-ils trouvé dans la forteresse un serment d’allégeance aux Déchus, signé de la main d’Avar Hrodland ? L’écriture comme les empreintes digitales correspondent parfaitement.",
          DialogueId = 11019310,
          Duration = 2,
          FinalCamera = "215.741455,377.273804,510.410156,0.00011,-50.585533,-115.377106,12.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B95EF8C",
          NextDialogue = 11019311,
          SpeakNpcId = 110039,
          Subtitle = "Explain this: why was a signed oath of allegiance to The Forsakens recovered from the fortress by the Narwhals? One bearing Avar Hrodland's handwriting and fingerprints — both verified with full precision?",
          TalkActionId = {
            [1] = "110039:Sit_Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "110039:n(110022)"
          },
          VoiceName = "voice/$Locale$/story/1002/110193/1B95EF8C"
        },
        [11019311] = {
          Camera = "435.564819,270.374847,32.574219,0.000075,-1.999838,-147.992447,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "On peut trouver mille faussaires capables d’imiter une écriture. Quant aux empreintes, n’importe qui ayant côtoyé régulièrement le Commandant Avar au sein de la Légion aurait pu les relever et les reproduire.",
          DialogueId = 11019311,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "431.525818,276.837738,32.574219,0.000075,-1.999838,-147.992447,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B95EFB6",
          NextDialogue = 11019312,
          SpeakNpcId = 110022,
          Subtitle = "Handwriting and signatures can be forged. It's not that difficult. As for fingerprints — anyone in the Legion with regular access to Sir Avar could've lifted and replicated them.",
          TalkActionId = {
            [1] = "110039:Sit_Talk02_End",
            [2] = "110022:Talk01_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110193/1B95EFB6"
        },
        [11019312] = {
          Camera = "149.849487,49.180954,-22.058594,0.000007,19.398439,-34.200615,35.000015,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 11019312,
          Duration = 4,
          FacialId = {
            [1] = "110039:Unhappy02"
          },
          FinalCamera = "150.602432,49.510048,-22.019531,-2.999999,20.199039,-32.200417,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1B95EFE0",
          NextDialogue = 11019313,
          SpeakNpcId = 110039,
          Subtitle = "...",
          TalkActionId = {
            [1] = "110022:Talk02_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1002/110193/1B95EFE0"
        },
        [11019313] = {
          Camera = "-68.800133,168.857269,475.46875,-2.999996,-69.999832,-56.789295,15.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Les rapports d’autopsie montrent que nombre de soldats sont morts, blessés par les mécanismes de la forteresse. Et les registres chiffrés de la salle de commande centrale ne mentionnent que deux opérateurs : Avar Hrodland... et vous. Comment expliquez-vous cela ?",
          DialogueId = 11019313,
          Duration = 2,
          FinalCamera = "-90.44854,156.158005,475.027344,-2.999996,-69.999832,-56.789295,15.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B95F00A",
          NextDialogue = 11019314,
          SpeakNpcId = 110039,
          Subtitle = "Autopsy reports show multiple casualties caused by the fortress's own defence systems. And the encrypted logs from the central control room list only two active operators: Avar Hrodland — and you. How do you explain that?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110193/1B95F00A"
        },
        [11019314] = {
          Camera = "0.64937,21.817383,42.609375,5.00035,-6.998867,-165.187607,15.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Nous avons pris le contrôle des systèmes, non pas pour activer les défenses, mais pour les désactiver.",
          DialogueId = 11019314,
          Duration = 2,
          ExStoryInfo = "EXPlayer",
