          SpeakNpcId = 200002,
          Subtitle = "Oh, how about this— Little Minion and I will help out at the tavern! The Pure-White Redeemer ☆ Demon King of Light will bring an awesome energy that'll brighten up the whole place!",
          ToFinalCameraBlendTime = 0.3,
          VoiceName = "voice/$Locale$/story/1200/120004/1E0AB144"
        },
        [12000411] = {
          Camera = "737.55481,-122.510742,51.755859,-2.0,13.199094,-8.80547,35.000011,137.990356,false,DoNotOverride,18.0",
          ContentFR = "Mais attention, cette œuvre de charité exceptionnelle mérite un paiement comptant, à la journée !",
          DialogueId = 12000411,
          FacialId = {
            [1] = "200002:Smile01"
          },
          FinalCamera = "704.252686,-117.352539,17.382812,-1.999999,19.798962,-7.606063,35.000011,137.990356,false,DoNotOverride,18.0",
          GUID = "1E0AB16E",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextDialogue = 12000412,
          SpeakNpcId = 200002,
          Subtitle = "And this rare act of charity absolutely calls for same-day payment!",
          TalkActionId = {
