          ContentFR = "Pas question.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000412,
          GUID = "1E0AB198",
          NextDialogue = 12000413,
          SpeakNpcId = 200003,
          Subtitle = "Not happening.",
          VoiceName = "voice/$Locale$/story/1200/120004/1E0AB198"
        },
        [12000413] = {
          ContentFR = "Aujourd’hui j’ai une cliente importante. Si tu restes là à gesticuler, elle va croire que j’ai transformé ma taverne en garderie.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000413,
          FacialId = {
            [1] = "200003:Uninterested01"
          },
          GUID = "1E0AB1C2",
          NextDialogue = 12000414,
          SpeakNpcId = 200003,
          Subtitle = "I've got an important client to entertain today. If you stick around, they'll think I've turned my tavern into a nursery.",
          TalkActionId = {
            [1] = "200003:Talk03_End",
            [2] = "100001:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1200/120004/1E0AB1C2"
        },
        [12000414] = {
          Camera = "719.914917,-228.804688,96.634766,-2.0,-2.801607,32.384254,45.000023,171.47702,false,Manual,18.0",
          ContentFR = "<I>Ouin ouin !</> À peine quelques jours d’absence, et voilà que Camilla ne m’aime plus !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000414,
          FacialId = {
            [1] = "200002:Sad01"
          },
          FinalCamera = "728.670654,-242.667969,96.0625,-2.0,-2.801607,32.385002,45.000023,165.913345,false,Manual,18.0",
          GUID = "1E0AB1EC",
          NextDialogue = 12000415,
          SpeakNpcId = 200002,
          Subtitle = "Waaah! I've only been away for a few days, and now Camilla doesn't like me anymore! Waaah!",
          TalkActionId = {
            [1] = "200002:Talk01_Start",
            [2] = "200002:Talk03_End",
            [3] = "200003:Talk03_End"
          },
          ToFinalCameraBlendTime = 2.5,
