        },
        [12000415] = {
          Camera = "215.504517,220.833984,112.722656,0.000129,10.599026,104.21505,35.000011,150.0,false,Manual,10.0",
          ContentFR = "Tes larmes n’impressionnent personne. Ici, à la taverne, c’est bien la monnaie la plus sans valeur.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000415,
          FinalCamera = "215.504517,220.833984,94.533203,0.000106,17.199236,104.613319,35.000008,150.0,false,Manual,10.0",
          GUID = "1E0AB216",
          NextDialogue = 12000416,
          SpeakNpcId = 200003,
          Subtitle = "Nice try. Tears are the most useless thing in this tavern — they won't get you anywhere.",
          TalkActionId = {
            [1] = "200003:Angry01_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1200/120004/1E0AB216"
