        [12000417] = {
          Camera = "529.599609,-210.112305,387.076172,0.000033,-20.599514,122.809799,45.0,768.236572,false,Manual,10.0",
          ContentFR = "<I>Soupir,</> tu es incorrigible. Tiens, deux billets d’opéra. Va donc te distraire ailleurs.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000417,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_TwoTicketes.T_Guide_Chapter_TwoTicketes'}",
