LookAt{LookAtDescription{"200003:n(100001)"}},
LookAt{_delay{1.1},LookAtDescription{"200003:n(200002)"}},
}]],
          SpeakNpcId = 200003,
          Subtitle = "Rhythm? You mean Rhythm Fischer, that young Legion officer? She dropped by yesterday.",
          TalkActionId = {
            [1] = "200003:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120004/1E0AB312"
        },
        [12000422] = {
          Camera = "454.580322,142.229492,148.949219,0.000098,-0.399197,139.819107,55.0,768.236572,false,DoNotOverride,16.14603",
          ContentFR = "La dernière fois qu’elle est venue, elle débordait d’énergie, jurant qu’elle mettrait la main sur le coupable. Mais hier... on aurait dit une ivrogne, les yeux rouges, chancelante, comme si elle allait s’effondrer à chaque pas.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000422,
          FinalCamera = "424.985596,167.219727,148.683594,0.000098,-0.399197,139.819107,55.0,768.236572,false,DoNotOverride,16.14603",
          GUID = "1E0AB33C",
          NextDialogue = 12000423,
          Scripts = [[
PARA{
PlayAnimation{_delay{1.8},ActorId{200003},AnimationId{"Confident_Start"},Duration{1}},
PlayAnimation{_delay{8.1},ActorId{200003},AnimationId{"ConfidentLToTalk_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "The last time I saw her before that, she was all fired up and raring to go, swearing up and down she'd catch the culprit. But yesterday... she looked like one of those hopeless drunks — bloodshot eyes, barely steady on her feet. I was half afraid she'd trip over her own boots.",
          TalkActionId = {
            [1] = "200002:Think_End",
            [2] = "200003:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1200/120004/1E0AB33C"
        },
        [12000423] = {
          Camera = "638.014893,-223.125,152.609375,0.000098,-4.598903,0.220902,55.000008,768.236572,false,DoNotOverride,16.14603",
          ContentFR = "Elle m’a même dit avoir quitté la Légion, et qu’elle voulait tenter sa chance comme Chasseuse de Phoxène... Qu’est-ce qui a bien pu lui arriver ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000423,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          FinalCamera = "656.093018,-223.05957,151.164062,0.000098,-4.598903,0.220902,55.000008,768.236572,false,DoNotOverride,16.14603",
          GUID = "1E0AB366",
          NextDialogue = 12000424,
          Scripts = "PlayAnimation{_delay{3.1},ActorId{100001},AnimationId{\"Think_End\"},Duration{1}}",
          SpeakNpcId = 200003,
          Subtitle = "She even told me she'd quit the Legion and wanted to try her hand at being a Phoxhunter. What's gotten into her?",
          TalkActionId = {
            [1] = "200003:Talk02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1200/120004/1E0AB366"
        },
        [12000424] = {
          Camera = "656.093018,-223.05957,151.164062,0.000098,-4.598903,0.220902,55.000008,768.236572,false,DoNotOverride,16.14603",
          ContentFR = "...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000424,
          DisableMouth = 1,
          Duration = 5,
          FinalCamera = "713.606934,-256.619141,175.96875,0.000149,-21.799675,26.014124,40.000023,119.993713,false,DoNotOverride,10.0",
          GUID = "1E0AB390",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 12000425,
          Scripts = "PlayFacial{_delay{1.5},ActorId{200002},FacialId{\"Unhappy01\"}}",
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "200002:Think_End",
            [2] = "200002:Talk03_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120004/1E0AB390"
        },
        [12000425] = {
          Camera = "876.919189,-283.1875,139.324219,0.0002,-2.281304,140.793442,45.0,390.38385,false,Manual,10.0",
          ContentFR = "Pas besoin d’en dire plus. Ton visage dit déjà que c’est un secret qui doit rester enfoui. Je ne poserai pas de questions.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000425,
          FinalCamera = "887.011963,-270.8125,139.324219,0.0002,-2.281304,140.793442,45.0,390.38385,false,Manual,10.0",
          GUID = "1E0AB3BA",
          NextDialogue = 12000426,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.1},ActorId{200003},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{_delay{6.1},ActorId{200003},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Alright, I get it. That look on your face tells me it's one of those secrets best left buried. I won't pry.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1200/120004/1E0AB3BA"
        },
        [12000426] = {
          Camera = "374.74707,257.083008,157.611328,0.000212,-3.799245,-43.97263,55.0,596.864319,false,Manual,10.0",
          ContentFR = "Donc... elle est Chasseuse de Phoxène maintenant ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000426,
          FinalCamera = "357.435913,273.78125,159.208984,0.000212,-3.799224,-43.97253,55.000008,596.864319,false,Manual,10.0",
          GUID = "1E0AB3E4",
          LookAt = {
            [1] = "200002:n(200003)"
          },
          NextDialogue = 12000427,
          SpeakNpcId = 100001,
          Subtitle = "So... she's a Phoxhunter now?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120004/1E0AB3E4"
        },
        [12000427] = {
          Camera = "431.327637,-96.431641,251.515625,0.000202,-12.081361,120.381516,55.0,562.867737,false,Manual,1.876",
          ContentFR = "Non. J’en ai vu beaucoup vouloir le devenir, certains pour vivre, d’autres pour le frisson. Mais elle... non.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000427,
          FinalCamera = "417.21106,-72.352539,245.552734,0.000202,-12.081361,120.381516,55.0,547.460266,false,Manual,1.876",
          GUID = "1E0AB40E",
          NextDialogue = 12000428,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{7},TargetPosition{"642.629761,-103.764648,140.650391,0.000179,-1.480894,-34.413567,55.0,210.932327,false,Manual,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"653.20459,-111.006836,140.316406,0.000179,-1.480894,-34.413567,55.0,190.854584,false,Manual,10.0"},duration{5}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "No. I've seen my fair share of people signing up to be Phoxhunters. Most of them are looking for a way to earn a living. Some are thrill-seekers chasing an adrenaline rush.",
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1200/120004/1E0AB40E"
        },
        [12000428] = {
          Camera = "300.418823,176.767578,131.841797,0.000208,4.918733,119.785431,55.0,260.314423,false,Manual,10.0",
          ContentFR = "Elle cherche juste à se noyer dans le travail pour fuir quelque chose. Alors je lui ai dit : « Reviens me voir quand tu sauras enfin ce que signifie vraiment être Chasseur de Phoxène ».",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000428,
          FinalCamera = "306.989624,165.288086,130.277344,0.000208,4.918733,119.785431,55.0,262.523438,false,Manual,10.0",
          GUID = "1E0AB438",
          NextDialogue = 12000429,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.1},ActorId{200003},AnimationId{"Talk01_Start"},Duration{1}},
PlayAnimation{_delay{8.1},ActorId{200003},AnimationId{"Talk01_End"},Duration{1}},
SEQ{
CameraMoveTo{_delay{10},TargetPosition{"715.241211,-180.469727,111.201172,0.000155,16.600317,-24.175522,40.000011,119.993706,false,DoNotOverride,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"730.302856,-187.232422,116.123047,0.000156,16.600317,-24.174397,40.000011,119.993706,false,DoNotOverride,10.0"},duration{8}}
}
}]],
          SpeakNpcId = 200003,
          Subtitle = "But she's different. She's... just trying to drown herself in work to escape something entirely. So I told her, \"Come back when you've truly figured out what being a Phoxhunter means to you.\"",
          TalkActionId = {
            [1] = "200003:Talk03_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120004/1E0AB438"
        },
        [12000429] = {
          Camera = "327.690063,109.425781,321.199219,0.000199,-21.199301,-29.376642,46.8032,596.864319,false,DoNotOverride,10.0",
          ContentFR = "... Je vois. Espérons qu’avec le temps, elle se relèvera.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000429,
          FacialId = {
            [1] = "200002:None"
          },
          FinalCamera = "309.0177,119.938477,329.513672,0.000199,-21.199301,-29.376642,46.8032,596.864319,false,DoNotOverride,10.0",
          GUID = "1E0AB462",
          NextDialogue = 12000430,
          Scripts = "LookAt{_delay{2.1},LookAtDescription{\"100001:n(200002)\"}}",
          SpeakNpcId = 100001,
          Subtitle = "I see. Well, let's hope with time, she'll get back on her feet.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120004/1E0AB462"
        },
        [12000430] = {
          Camera = "881.35376,-986.795898,277.859375,0.000175,-8.797884,103.629845,30.71941,949.918335,false,DoNotOverride,10.0",
          ContentFR = "Bon, assez parlé. L’heure approche, vous devriez filer. Snow, garde bien ces billets. Pas question de refaire un avion en papier cette fois ! S’ils s’envolent, viens pas pleurer.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000430,
          FinalCamera = "862.850342,-991.27832,296.121094,0.000176,-9.597904,103.630203,30.71941,949.918335,false,DoNotOverride,10.0",
          GUID = "1E0AB48C",
          NextDialogue = 12000431,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.1},ActorId{200003},AnimationId{"Talk01_End"},Duration{1}},
PlayAnimation{_delay{5.1},ActorId{200003},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Alright, the show's about to start. You'd better get going. And Snow, keep those tickets safe this time — no more folding them into paper planes, okay? If they fly off, don't come crying to me.",
          TalkActionId = {
            [1] = "200003:Talk01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1200/120004/1E0AB48C"
        },
        [12000431] = {
          Camera = "597.27478,165.592773,255.558594,0.000195,-18.799616,-54.777325,46.8032,596.864319,false,DoNotOverride,10.0",
          ContentFR = "Je sais, je sais ! T’inquiète ! Je les serrerai bien fort ! Petit larbin, on y va !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000431,
          FacialId = {
            [1] = "200002:Smile01"
          },
          FinalCamera = "597.27478,165.592773,255.558594,0.000191,-19.799488,-54.377277,46.8032,596.864319,false,DoNotOverride,10.0",
          GUID = "1E0AB4B6",
          Scripts = "LookAt{_delay{3.1},LookAtDescription{\"200002:n(100001)\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Uh-huh! Relax, I'll take good care of them! Come on, Little Minion, let's go!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 3,
          TurnTo = {
            [1] = "200003:p(-90)"
          },
          VoiceName = "voice/$Locale$/story/1200/120004/1E0AB4B6"
        },
        [12000501] = {
          ContentFR = "Mais... il n’y a que deux billets ! Alors, petit larbin, tu accompagnes ton Roi Démon, ou j’invite Rhythm à la place ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000501,
          GUID = "1E0AC032",
          NextDialogue = 12000502,
          SpeakNpcId = 200002,
          Subtitle = "There are only two tickets. So, Little Minion, are you coming with your Demon King, or should I invite Rhythm instead?",
          VoiceName = "voice/$Locale$/story/1200/120005/1E0AC032"
        },
        [12000502] = {
          ContentFR = "Est-ce que tu as vraiment besoin de poser la question ? Évidemment que j’y vais.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000502,
          GUID = "1E0AC05C",
          NextDialogue = 12000503,
          SpeakNpcId = 100001,
          Subtitle = "Need you ask? I'm going, obviously.",
          VoiceName = "voice/$Locale$/story/1200/120005/1E0AC05C"
        },
        [12000503] = {
          ContentFR = "Ouah, si direct ! Je croyais que tu dirais quelque chose comme : « Je cède mon billet à Rhythm. »",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000503,
          GUID = "1E0AC086",
          NextDialogue = 12000504,
          SpeakNpcId = 200002,
          Subtitle = "Whoa, that was blunt! I thought you'd say something noble like, \"I'll let Rhythm have my ticket.\"",
          VoiceName = "voice/$Locale$/story/1200/120005/1E0AC086"
        },
        [12000504] = {
          ContentFR = "Pas dans son état actuel. Ça ne ferait que rouvrir ses blessures. Laissons-lui le temps de guérir. Nous l’inviterons plus tard, quand elle ira mieux.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000504,
          GUID = "1E0AC0B0",
          SpeakNpcId = 100001,
          Subtitle = "Not when she's like this. Taking her along now might just reopen her old wounds. Let's give her some time to heal. We can invite her another day.",
          VoiceName = "voice/$Locale$/story/1200/120005/1E0AC0B0"
        },
        [12000505] = {
          Camera = "-3094.28418,465.570312,149.697754,0.000075,6.001161,-5.012456,30.0,100000.0,false,Manual,10.0",
          Content = "…………",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000505,
          Duration = 8,
          FinalCamera = "-3147.636719,627.79248,203.036865,0.000075,6.001161,-5.012456,30.0,100000.0,false,Manual,10.0",
          GUID = "1E0AC0B1",
          ToFinalCameraBlendTime = 8
        },
        [12000506] = {
          Content = "开个车，提示去聊一下",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000506,
          GUID = "1E0AC0B2",
          NextDialogue = 12000507
        },
        [12000507] = {
          Content = "开个车，提示去聊一下+1",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000507,
          GUID = "1E0AC0B3"
        },
        [12000601] = {
          ContentFR = "Avec la voix enchanteresse de Madame Violetta, ses aigus purs et puissants, sa maîtrise des vocalises, elle incarnera la fée à la perfection et portera cette œuvre intemporelle vers de nouveaux sommets !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000601,
          GUID = "1E0AD09A",
          NextDialogue = 12000602,
          SpeakNpcId = 220003,
          Subtitle = "With Lady Violetta's mesmerising voice — those pure, resonant high notes and her artistic mastery of coloratura — she's bound to bring the fairy character to life and elevate this timeless opera to dazzling new heights!",
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD09A"
        },
        [12000602] = {
          ContentFR = "Mouais... Si tu veux mon avis, la troupe décline d’année en année. Aujourd’hui, leurs performances sont à peine écoutables.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000602,
          GUID = "1E0AD0C4",
          NextDialogue = 12000603,
          SpeakNpcId = 220004,
          Subtitle = "Hmm... I don't know. If you ask me, this opera troupe gets worse every year. These days, their performances are barely passable at best.",
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD0C4"
        },
        [12000603] = {
          ContentFR = "Alors pourquoi tu continues à acheter une place à chaque représentation ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000603,
          GUID = "1E0AD0EE",
          NextDialogue = 12000604,
          SpeakNpcId = 220003,
          Subtitle = "Oh, really? Then why do you still buy tickets to every show?",
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD0EE"
        },
        [12000604] = {
          ContentFR = "On ne peut juger qu’en venant écouter, non ? Et puis... c’est la seule distraction qui me reste dans la vie.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000604,
          GUID = "1E0AD118",
          SpeakNpcId = 220004,
          Subtitle = "Well, you can't judge a show without actually watching it, can you? Besides, it's the only thing that keeps life bearable for me these days.",
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD118"
        },
        [12000605] = {
          ContentFR = "Papa ! On va bientôt pouvoir entendre la magie des grandes sœurs avec leurs voix féeriques !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000605,
          GUID = "1E0AD142",
          NextDialogue = 12000606,
          SpeakNpcId = 220005,
          Subtitle = "Daddy! We're about to hear the ladies' magical singing!",
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD142"
        },
        [12000606] = {
          ContentFR = "Regarder l’opéra avec Papa, et puis un grand dîner après... Aujourd’hui, c’est le plus beau jour de ma vie !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000606,
          GUID = "1E0AD16C",
          SpeakNpcId = 220005,
          Subtitle = "Watching the opera with Daddy and then going out for a fancy dinner — today is officially the happiest day of my life!",
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD16C"
        },
        [12000607] = {
          ContentFR = "Hé, t’as entendu ? Pendant la Fête de la Chandelle d’Argent, il y a eu un meurtre dans l’opéra même ! La Légion a dû intervenir !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000607,
          GUID = "1E0AD196",
          NextDialogue = 12000608,
          SpeakNpcId = 220006,
          Subtitle = "Hey, did you hear? A few days ago, during the Silvercandle Carnival, someone committed a murder right in the opera house! Things got so bad the Legion had to step in!",
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD196"
        },
        [12000608] = {
          ContentFR = "Certains parlent de fantômes, d’autres de Déchus... ou même du monstre de la \"Traque aux Charons\" revenu à la vie. Mais tous ceux qui ont voulu enquêter se sont retrouvés bâillonnés par un ordre de silence !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000608,
          GUID = "1E0AD1C0",
          SpeakNpcId = 220006,
          Subtitle = "Some say it was a ghost, others say it was the Forsakens, or maybe even the monster behind the \"Charon Hunt\" coming back to life... Whatever it was, anyone who tried to dig deeper got slapped with a gag order!",
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD1C0"
        },
        [12000701] = {
          Camera = "-677.66748,25.194824,133.280273,0.000017,-4.400049,-14.604745,35.000008,576.302551,false,Manual,10.0",
          ContentFR = "Billets ! Tarif spécial, ça vous dit ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000701,
          FinalCamera = "-678.432617,22.252441,133.280273,0.000017,-4.400049,-14.604682,35.000008,576.302551,false,Manual,10.0",
          GUID = "1E0AE12C",
          NextOptions = {
            [1] = 120007021,
            [2] = 120007061
          },
          SpeakNpcId = 220007,
          Subtitle = "Tickets! Special staff discounts — interested?",
          TalkActionId = {
            [1] = "220007:Talk02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE12C"
        },
        [12000703] = {
          Camera = "-185.232178,-210.383789,145.779785,0.000017,-7.80054,-4.40427,55.0,256.924988,false,Manual,10.0",
          ContentFR = "Facile ! Pour seulement cinq cents pièces d’argent, vous avez la meilleure place de la salle, premier rang, plein centre.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000703,
          FinalCamera = "-185.018555,-207.601074,145.779785,0.000017,-7.80054,-4.40427,55.0,252.039459,false,Manual,10.0",
          GUID = "1E0AE156",
          NextDialogue = 12000704,
          SpeakNpcId = 220007,
          Subtitle = "Only 500 silver coins for the best seat in the house — front row, dead centre, prime viewing.",
          TalkActionId = {
            [1] = "220007:Talk03_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE156"
        },
        [12000704] = {
          Camera = "115.702637,-202.392578,120.842041,0.000035,-11.799862,158.595566,35.000008,235.652527,false,Manual,10.0",
          ContentFR = "Cinq cents !? C’est scandaleux !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000704,
          FacialId = {
            [1] = "200002:Shock02"
          },
          FinalCamera = "135.201538,-210.22168,125.230957,0.000036,-11.799862,158.195572,35.000011,253.026947,false,Manual,10.0",
          GUID = "1E0AE180",
          NextDialogue = 12000705,
          SpeakNpcId = 200002,
          Subtitle = "Five hundred!? That's outrageous!",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE180"
        },
        [12000705] = {
          Camera = "-311.203369,-50.041016,41.681152,0.000108,8.198399,-25.589983,40.0,265.472382,false,DoNotOverride,10.0",
          ContentFR = "Mais c’est une affaire ! De là, vous verrez chaque éclat sur la robe de Madame Violetta, chaque frémissement de ses lèvres... Une expérience inoubliable !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000705,
          FinalCamera = "-314.26416,-56.431641,41.681152,0.000109,8.198385,-25.589556,40.0,265.472382,false,DoNotOverride,10.0",
          GUID = "1E0AE1AA",
          NextDialogue = 12000706,
          Scripts = [[
PARA{
PlayAnimation{_delay{2},ActorId{220007},AnimationId{"Explain01_Start"},Duration{1}},
LookAt{_delay{5},LookAtDescription{"220007:n(100001)"}},
SEQ{
CameraMoveTo{_delay{6.2},TargetPosition{"-662.359863,40.922852,147.54834,0.000017,-5.199618,-22.006809,40.0,576.302551,false,Manual,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"-672.477295,45.274414,148.549316,0.000017,-5.199618,-22.006809,40.0,576.302551,false,Manual,10.0"},duration{8}}
}}]],
          SpeakNpcId = 220007,
          Subtitle = "But it's worth every coin! From that seat, you'll see every sparkle on Lady Violetta's gown, every subtle movement of her lips. It's absolutely a once-in-a-lifetime experience!",
          TalkActionId = {
            [1] = "220007:Talk02_End"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "220007:n(200002)"
          },
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE1AA"
        },
        [12000706] = {
          Camera = "-41.440186,-178.4375,124.235352,0.000064,8.399623,-139.188477,22.448526,74.47065,false,Manual,10.0",
          ContentFR = "Non merci. Nous avons déjà nos billets.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000706,
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "1E0AE1D4",
          NextDialogue = 12000710,
          SpeakNpcId = 100001,
          Subtitle = "Thanks, but we've already got our tickets.",
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE1D4"
        },
        [12000707] = {
          Camera = "-9.883545,-151.188477,118.235596,0.000066,5.399599,-137.188034,22.448524,115.360046,false,Manual,10.0",
          ContentFR = "Non merci. Nous avons déjà nos billets.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000707,
          FacialId = {
            [1] = "100001:Smile02"
          },
          GUID = "1E0AE1FE",
          NextDialogue = 12000708,
          SpeakNpcId = 100001,
          Subtitle = "Thanks, but we've already got our tickets.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE1FE"
        },
        [12000708] = {
          Camera = "-192.296631,-210.211426,150.428711,0.000017,-10.000517,-1.204193,55.0,264.948456,false,Manual,10.0",
          ContentFR = "Dans ce cas... je rachète aussi. Vous pourriez repartir avec une belle poignée d’argent en me cédant vos billets. Qu’en dites-vous ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000708,
          FinalCamera = "-192.321045,-211.428223,150.428711,0.000017,-10.000517,-1.204193,55.0,267.196838,false,Manual,10.0",
          GUID = "1E0AE228",
          NextDialogue = 12000709,
          SpeakNpcId = 220007,
          Subtitle = "Well then... I also buy tickets. If you're willing to sell, you could walk away with a pocketful of shiny silver coins. What do you say?",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE228"
        },
        [12000709] = {
          Camera = "-41.440186,-178.4375,124.235352,0.000064,8.399623,-139.188477,22.448526,74.47065,false,Manual,10.0",
          ContentFR = "{性别:Désolé|Désolée}. Ce sont des cadeaux, je ne peux pas les revendre.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000709,
          FacialId = {
            [1] = "100001:Unhappy02"
          },
          GUID = "1E0AE252",
          NextDialogue = 12000710,
          SpeakNpcId = 100001,
          Subtitle = "Sorry, these were a gift. I wouldn't feel right selling them.",
          TalkActionId = {
            [1] = "100001:Disagree"
          },
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE252"
        },
        [12000710] = {
          Camera = "-89.339111,-5.74707,150.428711,0.00002,-10.800386,-53.803547,55.000008,267.196838,false,Manual,10.0",
          ContentFR = "Fallait le dire plus tôt ! Tu m’as fait perdre mon temps. Quelle poisse.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000710,
          GUID = "1E0AE27C",
          SpeakNpcId = 220007,
          Subtitle = "...You should've said that earlier! What a bummer.",
          TalkActionId = {
            [1] = "220007:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE27C"
        },
        [12000711] = {
          ContentFR = "Le garçon partit en rage. Pour bien montrer sa frustration, il vous heurta violemment de l’épaule en passant.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000711,
          Duration = 3,
          GUID = "1E0AE2A6",
          Subtitle = "The boy stomped off. As if to prove his frustration, he deliberately shoved his shoulder into you and Snow as he passed.",
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE2A6"
        },
        [12000712] = {
          Camera = "845.068359,-789.42041,503.364258,0.000063,-17.000237,141.195328,35.000015,110.475266,false,DoNotOverride,10.0",
          ContentFR = "Aïe !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000712,
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          FinalCamera = "838.580688,-797.487793,503.364258,0.000062,-17.000231,141.195358,35.000015,110.475266,false,DoNotOverride,10.0",
          GUID = "1E0AE2D0",
          NextDialogue = 12000713,
          Scripts = "PlayAnimation{_delay{5},ActorId{200002},AnimationId{\"Bai_Circle_End\"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "...Ow!",
          TalkActionId = {
            [1] = "200002:Bai_Circle_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE2D0"
        },
        [12000713] = {
          Camera = "26.616211,-179.427246,129.529297,0.000066,-20.999989,149.799927,27.779789,225.734268,false,DoNotOverride,10.0",
          ContentFR = "C’est lui qui nous a arrêtés, et maintenant il nous bouscule ?! Mais quel culot !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000713,
          FacialId = {
            [1] = "200002:Angry01"
          },
          FinalCamera = "25.078735,-182.069336,129.529297,0.000066,-20.999989,149.799927,27.779789,225.734268,false,DoNotOverride,10.0",
          GUID = "1E0AE2FA",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 12000714,
          SpeakNpcId = 200002,
          Subtitle = "He was the one who stopped us! What's his problem?",
          TalkActionId = {
            [1] = "200002:Angry01_Start",
            [2] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE2FA"
        },
        [12000714] = {
          Camera = "63.332153,50.858887,56.778564,0.00008,10.199091,-126.595093,45.0,333.098724,false,Manual,10.0",
          ContentFR = "Petit larbin, vite ! Allons au contrôle des billets, sinon on va rater le début !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000714,
          FacialId = {
            [1] = "100001:Think01"
          },
          FinalCamera = "82.113281,76.152832,51.111572,0.00008,10.199091,-126.595093,45.0,360.627472,false,Manual,10.0",
          GUID = "1E0AE324",
          Scripts = [[
