LookAt{LookAtDescription{"200002:n(200002)"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Forget him. Let's hurry to the ticket booth before the show starts. Wouldn't want to miss the opening!",
          TalkActionId = {
            [1] = "200002:Angry01_End"
          },
          ToFinalCameraBlendTime = 5,
