        [12000801] = {
          Camera = "-170.109375,317.277344,120.285156,0.000179,8.798184,-120.996368,35.0,1500.0,false,DoNotOverride,10.0",
          ContentFR = "Elle reste plantée là depuis un moment... Elle attend quelqu’un ?",
          DialogueId = 12000801,
          FinalCamera = "-170.007812,317.214844,125.261719,0.000179,8.798184,-120.996368,35.0,1500.0,false,DoNotOverride,10.0",
          GUID = "1E0AF16A",
          SpeakNpcId = 200002,
          Subtitle = "That lady's been standing there forever... Is she expecting someone?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120008/1E0AF16A"
        },
        [12000901] = {
          Camera = "447.142578,-1718.275391,230.304688,0.000094,0.799959,98.196053,35.000008,500.702026,false,Manual,10.0",
          ContentFR = "Monsieur, voici votre billet. Votre siège se trouve à gauche en entrant. Passez une excellente soirée.",
          DialogueId = 12000901,
          FinalCamera = "467.927734,-1842.345215,228.707031,0.000094,-0.999905,95.795494,33.0,500.702026,false,Manual,10.0",
          GUID = "1E0B01D2",
          LookAt = {
            [1] = "220010:n(220046)",
            [2] = "220046:n(220046)"
          },
          NextDialogue = 12000902,
          Scripts = [[
PARA{
PlayAnimation{_delay{2},ActorId{220010},AnimationId{"Talk01_Start"},Duration{1}},
PlayAnimation{_delay{5},ActorId{220010},AnimationId{"Talk01_End"},Duration{1}},
MoveTo{_delay{0.5},ActorId{220046},TargetPoint{"BP_NewTargetPoint112000201xiansheng"},MoveSpeed{35},Visibility{"Hide"}},
TurnTo{_delay{7.5},TurnToDescription{"220010:n(200002)"}}
}]],
          SpeakNpcId = 220010,
          Subtitle = "Good day, sir. Here is your ticket. Your seat is just to the left. Have a wonderful evening.",
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "220010:n(220046)"
          },
          VoiceName = "voice/$Locale$/story/1200/120009/1E0B01D2"
        },
        [12000902] = {
          Camera = "304.976562,-1287.830078,283.621094,0.000145,-15.79839,19.40465,28.000006,500.702026,false,Manual,10.0",
          ContentFR = "Tenez ! Voilà les billets de Snow et de son petit larbin.",
          DialogueId = 12000902,
          FacialId = {
            [1] = "200002:Smile02"
          },
          FinalCamera = "304.976562,-1287.830078,283.621094,0.000138,-17.998436,17.204498,28.000006,500.702026,false,Manual,10.0",
          GUID = "1E0B01FC",
          NextDialogue = 12000903,
          SpeakNpcId = 200002,
          Subtitle = "Here you go! These are our tickets.",
          TalkActionId = {
            [1] = "200002:Give",
            [2] = "100001:Confident_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1200/120009/1E0B01FC"
        },
        [12000903] = {
          Camera = "782.886719,-1307.572754,160.4375,0.000041,8.400169,167.798965,30.0,500.702026,false,Manual,10.0",
          ContentFR = "Et depuis quand les sales Charons se croient les bienvenus ici ? Dehors ! Avant que vous ne salissiez nos tapis.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000903,
          FinalCamera = "805.789062,-1312.524902,156.980469,0.000031,8.400169,167.798874,30.000002,500.702026,false,Manual,10.0",
          GUID = "1E0B0226",
          NextOptions = {
            [1] = 12000904,
            [2] = 12000905
          },
          Scripts = "PlayAnimation{_delay{1},ActorId{200002},AnimationId{\"Shock_Start\"},Duration{1}}",
          SpeakNpcId = 220010,
          Subtitle = "And where does a filthy Charon like you think you're going? Get out of here before you stain our carpets.",
          TalkActionId = {
            [1] = "220010:Angry01_Start",
            [2] = "100001:Confident_End"
          },
          ToFinalCameraBlendTime = 0.2,
          VoiceName = "voice/$Locale$/story/1200/120009/1E0B0226"
        },
        [12000904] = {
          ContentFR = "Votre règlement dit clairement : l’entrée se fait sur présentation de billets. Je n’ai rien lu sur l’exclusion de certains groupes.",
          DialogueId = 12000904,
          GUID = "1E0B0250",
          ImprPlusId = 1008,
          NextDialogue = 12000906,
          Subtitle = "Your own rules state admission is ticket-based. I don't see anything about excluding specific groups. "
        },
        [12000905] = {
          ContentFR = "C’est quoi cette attitude ? Je vais en référer à votre supérieur.",
          DialogueId = 12000905,
          GUID = "1E0B027A",
          ImprPlusId = 1010,
          NextDialogue = 12000906,
          Subtitle = "What kind of attitude is that? I'm reporting you to your manager!"
        },
        [12000906] = {
          Camera = "863.048828,-1966.588867,802.714844,3.000484,-35.395828,125.389961,30.0,500.702026,false,Manual,10.0",
          ContentFR = "Hmpf... À mon avis, le plus ridicule, c’est que ce théâtre n’ait pas encore gravé noir sur blanc : interdit aux Charons et aux Souillés.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000906,
          FinalCamera = "854.712891,-1972.905762,802.285156,3.000485,-35.39579,125.389961,30.0,500.702026,false,Manual,10.0",
          GUID = "1E0B02A4",
          NextDialogue = 12000907,
          Scripts = [[
PARA{
PlayAnimation{_delay{1},ActorId{220010},AnimationId{"Talk01_Start"},Duration{1}},
PlayAnimation{_delay{3},ActorId{100001},AnimationId{"Talk03_Start"},Duration{1}},
PlayAnimation{_delay{6},ActorId{220010},AnimationId{"Talk01_End"},Duration{1}}
}]],
          SpeakNpcId = 220010,
          Subtitle = "...Honestly, the fact that \"No Charons or Filthoids Allowed\" isn't in the theatre's policies is beyond ridiculous.",
          TalkActionId = {
            [1] = "220010:Angry01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1200/120009/1E0B02A4"
        },
        [12000907] = {
          Camera = "492.046875,-1336.085938,227.90625,0.000058,5.800442,163.211411,35.000011,240.0,false,Manual,10.0",
          ContentFR = "Bon. Montrez-moi ces billets.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000907,
          GUID = "1E0B02CE",
          SpeakNpcId = 220010,
          Subtitle = "Fine. Lemme see them.",
          TalkActionId = {
            [1] = "220010:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120009/1E0B02CE"
        },
        [12001101] = {
          ContentFR = "Le contrôleur ajuste lentement son monocle, inspecte les deux billets sous toutes les coutures.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001101,
          Duration = 3,
          GUID = "1E0B22A2",
          Subtitle = "The ticket collector donned his monocle with deliberate slowness, scrutinising the two flimsy tickets in his hand from every angle.",
          VoiceName = "voice/$Locale$/story/1200/120011/1E0B22A2"
        },
        [12001102] = {
          Camera = "472.220703,-1396.854004,227.90625,0.00006,5.200376,142.810028,35.000015,240.0,false,Manual,10.0",
          ContentFR = "Ha... Je le savais.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001102,
          FacialId = {
            [1] = "220010:CM_Ahaha01"
          },
          FinalCamera = "497.951172,-1415.679199,170.234375,0.000072,16.800051,143.810089,35.000015,240.0,false,Manual,10.0",
          GUID = "1E0B22CC",
          NextDialogue = 12001103,
          SpeakNpcId = 220010,
          Subtitle = "Ha — busted!",
          TalkActionId = {
            [1] = "220010:Talk01_Start"
          },
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1200/120011/1E0B22CC"
        },
        [12001103] = {
          Camera = "219.5,-1363.567383,271.265625,0.000139,-9.198488,34.811485,30.0,240.0,false,Manual,10.0",
          ContentFR = "Vous pensiez berner qui ? Retracer une date à l’encre et passer avec des billets périmés ? Des petites frappes comme vous, je les repère à des kilomètres.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001103,
          FacialId = {
            [1] = "220010:CM_Idle",
            [2] = "200002:Angry01",
            [3] = "100001:Unhappy01"
          },
          FinalCamera = "236.039062,-1352.068359,268.0,0.000141,-9.198488,34.811592,30.0,240.0,false,Manual,10.0",
          GUID = "1E0B22F6",
          LookAt = {
            [1] = "220010:n(200002)"
          },
          NextDialogue = 12001104,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{5},TargetPosition{"717.859375,-1293.508789,158.734375,0.000039,7.399963,167.795471,30.0,500.702026,false,Manual,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"714.375,-1309.625,158.734375,0.000039,7.39995,167.795395,30.0,500.702026,false,Manual,10.0"},duration{10}}
},
PlayAnimation{_delay{2.5},ActorId{220010},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 220010,
          Subtitle = "Did you really think you could scribble over the dates and sneak in with expired tickets? You filthy lowlifes! I can spot cheap tricks like this a mile away!",
          TalkActionId = {
            [1] = "220010:Talk01_End",
            [2] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "220010:n(200002)"
          },
          VoiceName = "voice/$Locale$/story/1200/120011/1E0B22F6"
        },
        [12001104] = {
          ContentFR = "Devant ces \"preuves\", vous restez sans voix.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001104,
          Duration = 3,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1E0B2320",
          NextDialogue = 12001105,
          Subtitle = "(Faced with undeniable evidence, you're left speechless.)",
          VoiceName = "voice/$Locale$/story/1200/120011/1E0B2320"
        },
        [12001105] = {
          Camera = "419.865234,-1179.731934,285.492188,0.000074,-32.19841,-16.777586,30.000002,240.0,false,DoNotOverride,10.0",
          ContentFR = "Attends... Petit larbin ! Le dessin sur ce billet n’est pas le même que celui que j’avais tout à l’heure !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001105,
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          GUID = "1E0B234A",
          LookAt = {
            [1] = "100001:p(BP_12000201in_nvzhu)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 12001106,
          SpeakNpcId = 200002,
          Subtitle = "Wait a second, Little Minion — the picture on these tickets is different from the ones I had!",
          TalkActionId = {
            [1] = "200002:Shock_Start",
            [2] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120011/1E0B234A"
        },
        [12001106] = {
          Camera = "427.664062,-1314.868652,193.546875,0.00007,14.599891,52.018433,38.0,240.0,false,DoNotOverride,10.0",
          ContentFR = "Ne me dis pas que... ce garçon a échangé nos billets quand il nous a bousculés ?!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001106,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "1E0B2374",
          NextDialogue = 12001107,
          SpeakNpcId = 100001,
          Subtitle = "Could it be... that boy swapped our tickets when he bumped into us!?",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200002:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120011/1E0B2374"
        },
        [12001107] = {
          Camera = "293.919922,-1303.304199,263.761719,0.000144,-10.997807,22.19919,30.000002,240.0,false,Manual,10.0",
          ContentFR = "Alors il n’a pas pu aller bien loin ! Retrouvons-le et faisons-lui ravaler son sourire !",
          DialogueId = 12001107,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "1E0B239E",
          NextDialogue = 12001108,
          Scripts = [[
