SEQ{
CameraMoveTo{_delay{2},TargetPosition{"293.919922,-1303.304199,263.761719,0.000144,-10.997807,22.19919,30.000002,240.0,false,Manual,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"293.919922,-1303.304199,263.761719,0.000144,-12.797854,21.199633,30.000002,240.0,false,Manual,10.0"},duration{0.8}}
}
}]],
          SpeakNpcId = 200002,
          Subtitle = "He can't have gone far! Let's find him and set this straight!",
          VoiceName = "voice/$Locale$/story/1200/120011/1E0B239E"
        },
        [12001108] = {
          Camera = "432.458984,-1299.610352,214.050781,0.000149,15.399015,172.204926,30.000013,240.0,false,DoNotOverride,10.0",
          ContentFR = "Pas si vite. Pas question de fuir. Des petites canailles comme vous, je vous livre directement au Bureau de la Sécurité !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001108,
          GUID = "1E0B23C8",
          LookAt = {
            [1] = "220010:n(100001)"
          },
          NextOptions = {
            [1] = 120011081,
            [2] = 120011082
          },
          Scripts = "PlayAnimation{_delay{5},ActorId{220010},AnimationId{\"Talk03_End\"},Duration{1}}",
          SpeakNpcId = 220010,
          Subtitle = "Trying to run off now? Thieving little brats like you aren't going anywhere. I'm hauling you both straight to the Security Bureau!",
          VoiceName = "voice/$Locale$/story/1200/120011/1E0B23C8"
        },
        [12001109] = {
          Camera = "281.349609,-1300.533691,262.660156,0.00015,-20.798916,18.815952,30.000008,240.0,false,Manual,10.0",
          ContentFR = "Hé ! C'était méchant ! Je vais te maudire, vraiment, vraiment méchamment !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001109,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "1E0B23F2",
          LookAt = {
            [1] = "200002:n(220010)"
          },
          NextDialogue = 12001110,
          SpeakNpcId = 200002,
          Subtitle = "Hey! That was mean! I'm going to curse you — really, really badly!",
          TalkActionId = {
            [1] = "200002:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120011/1E0B23F2"
        },
        [12001110] = {
          Camera = "392.619141,-754.603516,240.878906,0.000185,-0.000792,69.414879,30.000008,240.0,false,DoNotOverride,5.274955",
          ContentFR = "Madame, toutes mes excuses pour ce désagrément. Ce n’est qu’un malentendu sans importance entre eux, vous n’avez pas à vous en mêler...",
          DialogueId = 12001110,
          GUID = "1E0B241C",
          NextDialogue = 12001111,
          Scripts = [[
