        [12001302] = {
          Camera = "460.166016,-1490.179199,238.054688,0.000203,2.199983,118.812393,35.000008,257.958527,false,Manual,10.0",
          ContentFR = "... Madame, êtes-vous certaine de vouloir laisser des vauriens de leur espèce salir votre loge ? Ne vous laissez pas tromper par leurs airs innocents !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001302,
          FacialId = {
            [1] = "220010:CM_Angry01"
