          GUID = "1E0B439C",
          LookAt = {
            [1] = "220010:n(210004)"
          },
          NextDialogue = 12001303,
          Scripts = "PlayAnimation{_delay{4},ActorId{220010},AnimationId{\"Think_End\"},Duration{1}}",
          SpeakNpcId = 220010,
          Subtitle = "...Ma'am, are you sure you want shady little punks like them to dirty your private suite? Don't be fooled by their innocent appearances!",
