          SpeakNpcId = 210004,
          Subtitle = "Watch your words. You never know what misfortune they might bring upon you.",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B44C2"
        },
        [12001310] = {
          Camera = "31.415039,981.577148,873.933594,0.000125,-35.994133,-75.767517,25.0,30.607483,false,DoNotOverride,4.569996",
          ContentFR = "Madame, merci de nous avoir aidés tout à l’heure.",
          DialogueId = 12001310,
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "-24.272461,967.451172,851.3125,0.000125,-35.994137,-75.768639,25.0,30.607483,false,DoNotOverride,4.569996",
          GUID = "1E0B44EC",
          LookAt = {
            [1] = "210004:n(100001)",
            [2] = "100001:n(210004)",
            [3] = "200002:n(210004)"
          },
          NextDialogue = 12001311,
          SpeakNpcId = 100001,
          Subtitle = "Thank you for stepping in to help us earlier, ma'am.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B44EC"
        },
        [12001311] = {
          Camera = "-76.600586,-142.378418,145.878906,0.000066,2.400094,55.591667,35.000011,210.0,false,Manual,10.0",
          ContentFR = "Héhé... Inutile d’être si cérémonieux. Appelle-moi simplement Zhiliu.",
          DialogueId = 12001311,
          FacialId = {
            [1] = "210004:Smile01"
          },
          FinalCamera = "-73.668945,-138.096191,146.089844,0.000078,2.400094,55.59174,35.000008,210.0,false,Manual,10.0",
          GUID = "1E0B4516",
          NextDialogue = 12001312,
          Scripts = "PlayAnimation{_delay{3.3},ActorId{210004},AnimationId{\"Explain02_End\"},Duration{1}}",
          SpeakNpcId = 210004,
          Subtitle = "Hehe... No need to be so formal. Just call me by my name.",
          TalkActionId = {
            [1] = "210004:Explain02_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4516"
        },
        [12001312] = {
          Camera = "30.446289,185.356934,190.074219,0.000055,-11.799342,-98.808578,35.000008,267.576447,false,DoNotOverride,4.724111",
          ContentFR = "Alors... Dame Zhiliu... ?",
          DialogueId = 12001312,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "1E0B4540",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 12001313,
          SpeakNpcId = 100001,
          Subtitle = "...Lady Zhiliu, then?",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4540"
        },
        [12001313] = {
          Camera = "-64.051758,0.427246,155.0625,0.000095,4.200347,23.600756,35.000008,201.567627,false,DoNotOverride,10.0",
          ContentFR = "« Dame », encore une tournure de l’Empire, n’est-ce pas ? Je n’y ai jamais pris goût.",
          DialogueId = 12001313,
          GUID = "1E0B456A",
          NextDialogue = 12001314,
          Scripts = "PlayAnimation{_delay{3},ActorId{210004},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 210004,
          Subtitle = "...That's not much of an improvement. \"Lady\" is more of an Empire term, isn't it? I've never really grown used to it.",
          TalkActionId = {
            [1] = "210004:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B456A"
        },
        [12001314] = {
          ContentFR = "Je voyage depuis des années comme commerçante, et je possède quelques commerces. Si tu tiens à m’affubler d’un titre, \"Patronne\" serait plus approprié.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001314,
          GUID = "1E0B4594",
          NextDialogue = 12001315,
          Scripts = [[
PARA{
CameraMoveTo{_delay{5},TargetPosition{"24.381836,149.445801,168.28125,0.000089,-6.799255,-100.405937,35.000008,201.567627,false,Manual,10.0"},duration{0}},
LookAt{_delay{6.1},LookAtDescription{"200002:n(210004)"}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "I've spent years travelling these lands as a merchant, overseeing a few shops of my own. If you feel you must use a title, perhaps \"proprietress\" would be more fitting.",
          TalkActionId = {
            [1] = "210004:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4594"
        },
        [12001315] = {
          Camera = "-228.251953,-342.149658,218.3125,0.000205,-10.998899,54.599339,35.0,210.445709,false,DoNotOverride,10.0",
          ContentFR = "Alors... Patronne Zhiliu, vous attendiez quelqu’un, n’est-ce pas ? Nous n’allons pas vous déranger ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001315,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E0B45BE",
          NextDialogue = 12001316,
          Scripts = [[
PARA{
LookAt{_delay{5.1},LookAtDescription{"100001:n(200002)"}},
LookAt{_delay{6.1},LookAtDescription{"200002:n(210004)"}},
PlayAnimation{_delay{5},ActorId{100001},AnimationId{"Talk03_End"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Alright then... Proprietress Zhiliu, were you expecting someone? I hope we're not intruding.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B45BE"
        },
        [12001316] = {
          Camera = "22.512695,93.567383,162.910156,0.000092,-4.399099,-96.009109,35.000008,201.567627,false,Manual,10.0",
          ContentFR = "Oh, c’est donc ça qui te tracassait ? Que c’est adorablement attentionné de ta part.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001316,
          GUID = "1E0B45E8",
          LookAt = {
            [1] = "210004:n(200002)",
            [2] = "100001:n(210004)"
          },
          NextDialogue = 12001317,
          SpeakNpcId = 210004,
          Subtitle = "That's what you've been worrying about? How adorably considerate of you.",
          TalkActionId = {
            [1] = "210004:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B45E8"
        },
        [12001317] = {
          Camera = "-95.72168,25.02832,164.125,0.000175,-0.798128,7.808278,43.803249,210.445709,false,DoNotOverride,10.0",
          ContentFR = "Rassure-toi. Je ne pense pas que cette personne viendra.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001317,
          FinalCamera = "-108.598633,23.216797,163.859375,0.000175,1.201922,8.00806,43.803249,210.445709,false,DoNotOverride,10.0",
          GUID = "1E0B4612",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 12001318,
          Scripts = [[
PARA{
TurnTo{_delay{3},TurnToDescription{"210004:p(130)"}},
LookAt{_delay{3},LookAtDescription{"210004:n(210004)"}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "It's okay. I don't think that person will be coming.",
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "200002:n(210004)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4612"
        },
        [12001318] = {
          Camera = "-724.288086,-392.508057,357.445312,0.000203,-15.398278,26.595276,30.000002,210.445709,false,DoNotOverride,10.0",
          ContentFR = "Un spectacle en solitaire peut sembler bien morne. Avec vous deux, cette loge s’est déjà remplie de chaleur et de vie. C’est à moi de vous remercier, en réalité.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001318,
          FinalCamera = "-722.753906,-375.015869,367.042969,0.000203,-15.398278,26.595276,30.0,210.445709,false,DoNotOverride,10.0",
          GUID = "1E0B463C",
          NextDialogue = 12001319,
          Scripts = [[
PARA{
LookAt{_delay{9},LookAtDescription{"210004:n(100001)"}},
PlayAnimation{_delay{7},ActorId{210004},AnimationId{"Talk02_Start"},Duration{1}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "Watching a show on one's own can feel a bit lonely. Having you two here has brightened this suite considerably. If anything, I should be the one thanking you.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B463C"
        },
        [12001319] = {
          Camera = "-39.875977,-172.393066,112.152344,0.000143,-4.597844,106.196785,30.000008,106.771988,false,Manual,10.0",
          ContentFR = "Petit larbin ! Tu te rends compte ? Quel idiot faut-il être pour laisser tomber une dame aussi belle, aussi riche et aussi généreuse... et la laisser se morfondre ?!",
          DialogueId = 12001319,
          FacialId = {
            [1] = "200002:Doubt01"
          },
          GUID = "1E0B4666",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 12001320,
          Scripts = [[
PARA{
PlayAnimation{_delay{3},ActorId{200002},AnimationId{"Confident_Start"},Duration{1}},
TurnTo{_delay{0.1},TurnToDescription{"100001:n(200002)"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, can you believe someone would stand up such a rich, generous, and gorgeous lady? What a fool!",
          TalkActionId = {
            [1] = "210004:Talk02_End"
          },
          TurnTo = {
            [1] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4666"
        },
        [12001320] = {
          Camera = "-157.03418,-238.744385,135.445312,0.000194,-1.198671,55.205051,29.855673,334.603516,false,DoNotOverride,10.0",
          ContentFR = "Dans mon pays, les rencontres entre les personnes sont ce qu’on appelle le destin. Ces instants sont rares et précieux, et lorsqu’ils se présentent, il convient de les chérir. Qu’en penses-tu ? ",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001320,
          FinalCamera = "2.482422,-380.777344,275.316406,0.000165,-21.198877,95.206535,29.855673,334.603516,false,DoNotOverride,10.0",
          GUID = "1E0B4690",
          LookAt = {
            [1] = "200002:n(210004)",
            [2] = "100001:n(210004)",
            [3] = "210004:n(210004)"
          },
          NextOptions = {
            [1] = 120013201,
            [2] = 120013202
          },
          Scripts = [[
PARA{
PlayAnimation{_delay{9},ActorId{210004},AnimationId{"Zhiliu_Story_Special02_Start"},Duration{1}},
LookAt{_delay{6},LookAtDescription{"210004:n(100001)"}},
TurnTo{_delay{6.5},TurnToDescription{"210004:n(100001)"}}
}]],
          SpeakNpcId = 210004,
          Subtitle = "In my homeland, we refer to the chance encounters between people as \"fate.\" Such moments are rare and precious. When it happens, we believe it's worth cherishing — wouldn't you agree?",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "100001:n(210004)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4690"
        },
        [12001321] = {
          Camera = "130.839844,-87.01416,151.46875,0.00015,-13.198083,176.609421,43.803253,210.445709,false,Manual,10.0",
          ContentFR = "Snow est tout à fait d’accord avec la grande sœur Zhiliu ! Alors, Snow et {nickname} resteront avec plaisir, merci beaucoup !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001321,
          FacialId = {
            [1] = "200002:Smile02"
          },
          GUID = "1E0B46BA",
          LookAt = {
            [1] = "210004:n(210004)"
          },
          NextDialogue = 12001322,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"200002:n(210004)\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Snow thinks this nice, pretty lady is absolutely right! So, Snow and  will stay! Thank you for having us~",
          TalkActionId = {
            [1] = "200002:Talk03_Start",
            [2] = "210004:Zhiliu_Story_Special02_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B46BA"
        },
        [12001322] = {
          Camera = "-29.191406,-99.70166,165.839844,0.000196,-0.599062,67.805344,43.803253,150.779633,false,DoNotOverride,10.0",
          ContentFR = "{nickname}... C’est bien ton nom ? Comme il sonne joliment.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001322,
          GUID = "1E0B46E4",
          LookAt = {
            [1] = "210004:n(100001)"
          },
          NextDialogue = 12001323,
          SpeakNpcId = 210004,
          Subtitle = "... Is that your name? It has such a lovely ring to it.",
          TalkActionId = {
            [1] = "200002:Talk03_End"
          },
          TurnTo = {
            [1] = "210004:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B46E4"
        },
        [12001323] = {
          Camera = "1200.097656,198.318848,530.671875,0.000285,-18.998676,-169.598007,35.0,150.779633,false,DoNotOverride,10.0",
          ContentFR = "Allez, asseyez-vous.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001323,
          FinalCamera = "1201.771484,189.229004,530.671875,0.000285,-18.998676,-169.598007,35.0,150.779633,false,DoNotOverride,10.0",
          GUID = "1E0B470E",
          LookAt = {
            [1] = "100001:n(210004)"
          },
          Scripts = "PlayAnimation{_delay{0.3},ActorId{210004},AnimationId{\"Give\"},Duration{1}}",
          SpeakNpcId = 210004,
          Subtitle = "Come, have a seat.",
          ToFinalCameraBlendTime = 4,
          TurnTo = {
            [1] = "200002:n(210004)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B470E"
        },
        [12001324] = {
          Camera = "4572.582031,245.40918,-1846.019531,0.000001,19.997604,-90.387962,20.000008,878.773254,false,Manual,1.2",
          ContentFR = "Mesdames et messieurs, le spectacle va commencer. Les retardataires, merci de prendre rapidement place.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001324,
          FinalCamera = "4562.724609,-667.667236,-1513.722656,0.000001,19.997604,-90.387962,20.000008,878.773254,false,Manual,1.2",
          GUID = "1E0B4738",
          NextDialogue = 12001325,
          Subtitle = "Ladies and gentlemen, the performance is about to begin. Kindly take your seats at your earliest convenience.",
          TalkActionId = {
            [1] = "220041:Sit_Idle_Start",
            [2] = "220042:Sit_Talk03_Loop"
          },
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4738"
        },
        [12001325] = {
          ContentFR = "Et maintenant, profitez du magnifique spectacle présenté par la troupe d’opéra de Galea !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001325,
          GUID = "1E0B4762",
          NextDialogue = 12001326,
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
          Subtitle = "Up next, we are delighted to present a magnificent performance by the Galea Opera Troupe.",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4762"
        },
        [12001326] = {
          Camera = "-213.078125,597.674805,707.015625,0.000202,-11.600912,-178.603836,40.000023,1102.562866,false,Manual,1.2",
          ContentFR = "Il y a bien longtemps... dans un château de glace, au cœur d’un pays enneigé...\nUne fée des neiges s’éveilla au rire de deux enfants.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001326,
          FinalCamera = "-211.563477,535.948242,707.015625,0.000202,-11.600912,-178.603836,40.000023,1102.562866,false,Manual,1.2",
          GUID = "1E0B478C",
          NextDialogue = 12001327,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt03/0069_boss_devil_linen\"}}",
          Subtitle = "Once upon a time, in a frosted castle in the Snowfield, a slumbering frost fairy was awakened by the laughter of two children...",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B478C"
        },
        [12001327] = {
          Camera = "7325.71875,5494.020508,541.855469,0.000293,22.789042,-159.560425,20.0,500.0,false,Manual,10.0",
          ContentFR = "Alors, la frêle fée s’élança contre les monstres...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001327,
          FinalCamera = "7183.162109,5440.892578,605.769531,0.000291,26.788889,-155.961044,20.0,500.0,false,Manual,10.0",
          GUID = "1E0B47B6",
          NextDialogue = 12001328,
          Subtitle = "The tiny fairy flew towards the monstrous creature...",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B47B6"
        },
        [12001328] = {
          ContentFR = "Mais leurs griffes brisèrent d’un rien ses membres fragiles.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001328,
          FacialId = {
            [1] = "220041:Sad03"
          },
          GUID = "1E0B47E0",
          LookAt = {
            [1] = "220041:n(220041)",
            [2] = "220042:n(220042)"
          },
          NextDialogue = 12001329,
          Subtitle = "...only for its delicate limbs to snap beneath its might.",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B47E0"
        },
        [12001329] = {
          Camera = "32.304688,240.658203,114.476562,0.000086,-2.603053,-135.186905,30.000002,132.470917,false,Manual,6.527582",
          ContentFR = "Pourtant, pour la toute première fois... son cœur battit. Il battit... il hurla son propre destin !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001329,
          Duration = 5,
          FinalCamera = "41.55957,229.902832,114.476562,0.000085,-3.003077,-141.986862,30.000002,132.470917,false,Manual,6.527582",
          GUID = "1E0B480A",
          NextDialogue = 12001370,
          Subtitle = "The fairy's frozen heart pulsed for the first time — beating, screaming its own destiny—",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B480A"
        },
        [12001330] = {
          Camera = "52.354492,214.417969,109.269531,0.0,-0.001434,-142.205307,45.0,101.750626,false,Manual,5.456383",
          ContentFR = "...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001330,
          DisableMouth = 1,
          FinalCamera = "105.552734,256.467773,109.492188,0.0,-1.201505,-144.205154,45.0,173.6642,false,Manual,5.456383",
          GUID = "1E0B4834",
          NextOptions = {
            [1] = 120013301,
            [2] = 120013321
          },
          Scripts = "LookAt{_delay{8},LookAtDescription{\"220042:n(220041)\"}}",
          SpeakNpcId = 220041,
          Subtitle = "...",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4834"
        },
        [12001331] = {
          ContentFR = "Vous semblez un peu touchée...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001331,
          GUID = "1E0B485E",
          NextDialogue = 12001332,
          SpeakNpcId = 100001,
          Subtitle = "You seem a little upset.",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B485E"
        },
        [12001332] = {
          ContentFR = "Ce n’est rien, juste quelques émotions.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001332,
          FacialId = {
            [1] = "220041:Close"
          },
          GUID = "1E0B4888",
          NextDialogue = 12001334,
          SpeakNpcId = 220041,
          Subtitle = "Something in the story struck a chord with me, that's all.",
          TalkActionId = {
            [1] = "220041:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4888"
        },
        [12001333] = {
          ContentFR = "...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001333,
          DisableMouth = 1,
          FinalCamera = "617.853516,615.266602,211.964844,0.00002,-9.801267,-144.203323,50.0,799.630554,false,Manual,1.2",
          GUID = "1E0B48B2",
          NextDialogue = 12001334,
          SpeakNpcId = 220041,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B48B2"
        },
        [12001334] = {
          Camera = "617.853516,615.266602,211.964844,0.00002,-9.801267,-144.203323,50.0,799.630554,false,Manual,1.2",
          ContentFR = "Peu importe le lieu, peu importe l’époque, la même histoire se répète. Les héros échangent leur vie et leur sacrifice pour quelque chose de plus grand, de plus noble.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001334,
          FacialId = {
            [1] = "220041:Zhiliu_SpecialSad"
          },
          FinalCamera = "728.994141,695.423828,235.628906,0.00002,-9.801267,-144.203323,50.0,930.356812,false,Manual,1.2",
          GUID = "1E0B48DC",
          LookAt = {
            [1] = "200002:n(220041)"
          },
          NextDialogue = 12001335,
          Scripts = [[
PARA{
PlayAnimation{_delay{5},ActorId{220041},AnimationId{"Sit_Talk02_End"},Duration{1}},
PlayAnimation{_delay{3},ActorId{200002},AnimationId{"Talk03_Start"},Duration{1}}
}
]],
          SpeakNpcId = 220041,
          Subtitle = "Across every time and place, the same stories are told — tales of those who sacrifice their lives for something greater.",
          TalkActionId = {
            [1] = "220041:Sit_Talk02_Start"
          },
          ToFinalCameraBlendTime = 15,
          TurnTo = {
