            [1] = "220041:Smile01"
          },
          FinalCamera = "728.994141,695.423828,235.628906,0.00002,-9.801267,-144.203323,50.0,930.356812,false,Manual,1.2",
          GUID = "1E0B4930",
          LookAt = {
            [1] = "220041:n(220042)"
          },
          NextDialogue = 12001337,
          SpeakNpcId = 220041,
          Subtitle = "Hehe... Look at me, waxing sentimental all of a sudden.",
