        },
        [12001337] = {
          ContentFR = "Bon, il est temps de partir.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001337,
          GUID = "1E0B495A",
          SpeakNpcId = 220041,
          Subtitle = "Come now. It's time we left.",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B495A"
        },
        [12001338] = {
          Camera = "-880.464844,-749.638672,655.234375,0.000083,-24.798613,55.190041,35.000011,259.125397,false,DoNotOverride,5.0",
          ContentFR = "Pas si vite. Notre patron dit que vous allez nulle part pour l’instant.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001338,
          FinalCamera = "-825.736328,-670.879883,610.957031,0.000083,-24.798613,55.190041,35.000011,259.125397,false,DoNotOverride,5.0",
          GUID = "1E0B4984",
          NextDialogue = 12001339,
          Scripts = [[
SEQ
{
