PlayAnimation{ActorId{220017},AnimationId{"Talk03_Start"},Duration{1.5}}
}]],
          SpeakNpcId = 220017,
          Subtitle = "Not so fast. Our boss says you're not going anywhere yet.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4984"
        },
        [12001339] = {
          Camera = "-57.685547,314.981934,-15.996094,0.000085,3.003138,-74.771889,45.0,229.807159,false,Manual,8.0",
          ContentFR = "Qui es‑tu ? Et pourquoi ce ton si sec... C’est ainsi qu’on traite le Grand Roi Démon de la Lumière ?",
          DialogueId = 12001339,
          FacialId = {
            [1] = "200002:Angry01"
          },
          FinalCamera = "-60.181641,324.171875,-16.488281,0.000087,3.003138,-74.771553,45.0,229.807159,false,Manual,8.0",
          GUID = "1E0B49AE",
          NextDialogue = 12001340,
          SpeakNpcId = 200002,
          Subtitle = "Who are you? And why so rude? Is this how you treat the great Demon King of Light?",
          TalkActionId = {
            [1] = "200002:Talk03_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B49AE"
        },
        [12001340] = {
          Camera = "-98.828125,412.249512,33.292969,1.999976,16.400875,81.608185,20.000008,81.737244,false,DoNotOverride,5.0",
          ContentFR = "Le Roi Démon... qu’est-ce que c’est que ce délire ? Écarte-toi !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001340,
          FinalCamera = "-107.564453,352.935547,6.128906,1.999978,16.400875,81.608223,20.000008,81.737244,false,DoNotOverride,5.0",
          GUID = "1E0B49D8",
          LookAt = {
            [1] = "220017:n(200002)"
          },
          NextDialogue = 12001341,
          SpeakNpcId = 220017,
          Subtitle = "Huh? What's that...? Move it, kiddo.",
          TalkActionId = {
            [1] = "220017:Angry01_Start"
          },
          ToFinalCameraBlendTime = 0.4,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B49D8"
        },
        [12001341] = {
          Camera = "-57.962891,2658.119141,479.070312,0.000044,-10.596129,-90.182518,55.000008,789.111267,false,Manual,5.0",
          ContentFR = "Vous êtes Madame Zhiliu, non ? Notre patron vous attend. Avant que la salle ne soit vide, vous devez patienter ici un instant.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001341,
          FinalCamera = "-57.917969,2674.333984,482.085938,0.000044,-10.596129,-90.182518,55.000008,2602.976562,false,Manual,5.0",
          GUID = "1E0B4A02",
          LookAt = {
            [1] = "220017:n(220014)"
          },
          NextDialogue = 12001342,
          SpeakNpcId = 220017,
          Subtitle = "Ms Zhiliu, right? My boss has an appointment with you. Before the area is cleared, I'll need you to wait here for a moment.",
          TalkActionId = {
            [1] = "220017:Angry01_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4A02"
        },
        [12001342] = {
          Camera = "-87.818359,443.974121,52.113281,0.000121,1.803375,-87.158249,50.0,81.737244,false,DoNotOverride,5.0",
          ContentFR = "Le spectacle est terminé, et il n’est toujours pas là... Voilà donc ce qu’on appelle l’hospitalité impériale.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001342,
          FacialId = {
            [1] = "220014:Unhappy01",
            [2] = "100001:Unhappy01"
          },
          FinalCamera = "-88.287109,453.520996,51.832031,0.000122,2.003349,-87.158119,50.0,81.737244,false,DoNotOverride,5.0",
          GUID = "1E0B4A2C",
          NextDialogue = 12001343,
          SpeakNpcId = 220014,
          Subtitle = "The performance has finished, and your boss is still nowhere to be seen. Is this considered proper business etiquette here in Hyperborea?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4A2C"
        },
        [12001343] = {
          Camera = "-773.867188,-573.074219,376.890625,0.000148,-17.397453,52.037464,35.000008,81.737244,false,DoNotOverride,5.0",
          ContentFR = "Je peux patienter, mais ces deux petits... Pouvez-vous les laisser partir ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001343,
          FinalCamera = "-793.013672,-558.131348,376.890625,0.000151,-17.397453,52.038574,35.000008,81.737244,false,DoNotOverride,5.0",
          GUID = "1E0B4A56",
          NextDialogue = 12001344,
          SpeakNpcId = 220014,
          Subtitle = "I can wait, but what about these two? Surely you can let the young ones leave.",
          TalkActionId = {
            [1] = "220014:Sigh_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4A56"
        },
        [12001344] = {
          Camera = "-122.492188,200.228027,-8.191406,-1.999999,11.002273,75.213051,40.000023,302.271698,false,Manual,5.0",
          ContentFR = "Ne me suis-je pas fait comprendre ? J’ai dit qu’avant que la salle ne se vide, personne ne bouge ! Pas un seul !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001344,
          FinalCamera = "-128.132812,178.830078,-12.46875,-2.0,11.00228,75.213005,40.000023,302.271698,false,Manual,5.0",
          GUID = "1E0B4A80",
          NextDialogue = 12001345,
          SpeakNpcId = 220017,
          Subtitle = "Didn't I make myself clear? I said no one leaves until the place is cleared. Not a single one of you!",
          TalkActionId = {
            [1] = "220017:Talk03_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4A80"
        },
        [12001345] = {
          Camera = "-123.167969,340.399414,92.625,0.00017,-21.796923,-52.159969,40.000011,81.737244,false,DoNotOverride,5.0",
          ContentFR = "...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001345,
          DisableMouth = 1,
          GUID = "1E0B4AAA",
          SpeakNpcId = 220014,
          Subtitle = "...",
          TalkActionId = {
            [1] = "220014:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4AAA"
        },
        [12001346] = {
          ContentFR = "La salle se vide peu à peu, vous laissant seuls face à l’homme devant vous.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001346,
          Duration = 2,
          GUID = "1E0B4AD4",
          NextDialogue = 12001347,
          SpeakNpcId = 100001,
          Subtitle = "The audience gradually disperses, leaving the once-bustling theatre empty. You stand in tense silence, facing the man before you.",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4AD4"
        },
        [12001347] = {
          ContentFR = "Dans le théâtre vide, des pas nets et décidés résonnent...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001347,
          Duration = 2,
          GUID = "1E0B4AFE",
          SpeakNpcId = 100001,
          Subtitle = "The sound of sharp, deliberate footsteps echoes through the hall.",
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4AFE"
        },
        [12001348] = {
          Camera = "-97.597656,490.723633,-6.394531,0.000057,9.200121,87.800667,30.0,300.0,false,Manual,10.0",
          ContentFR = "Désolé pour l’attente, Patronne Zhiliu. Les endroits bondés ne sont pas vraiment mon domaine... un lieu calme se prête bien mieux aux affaires, vous ne trouvez pas ?",
          DialogueId = 12001348,
          FacialId = {
            [1] = "220018:CM_Ahaha01"
          },
          FinalCamera = "-119.839844,234.390137,-6.265625,0.000041,13.800294,88.201004,35.0,300.0,false,Manual,10.0",
          GUID = "1E0B4B28",
          LookAt = {
            [1] = "100001:n(220018)"
          },
          NextDialogue = 12001349,
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0043_story_empire"},RelatedRegionId{"101901"}},
SetLocation{ActorId{220017},TargetPoint{"TargetPointbaobiao"},Visibility{"Show"}},
MoveTo{_delay{1},ActorId{220017},TargetPoint{"TargetPointbaobiao2"},MoveSpeed{55},Visibility{"Show"}},
MoveTo{_delay{1.1},ActorId{220018},TargetPoint{"TargetPointheishang"},MoveSpeed{110},Visibility{"Show"}},
MoveTo{_delay{1.2},ActorId{220045},TargetPoint{"TargetPointbaobiao3"},MoveSpeed{110},Visibility{"Show"}},
PlayAnimation{_delay{5},ActorId{220018},AnimationId{"Talk01_Start"},Duration{1.5}}
}]],
          SpeakNpcId = 220018,
          Subtitle = "Sorry about the wait, Ms Zhiliu. Crowded places aren't really my thing. A quiet space is far more suited for business, don't you agree?",
          TalkActionId = {
            [1] = "200002:Confident_Start",
            [2] = "100001:Confident_Start"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "100001:n(220018)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4B28"
        },
        [12001349] = {
          Camera = "-61.787109,560.610352,42.621094,0.000029,-2.997223,-101.179504,25.0,332.928833,false,Manual,3.5",
          ContentFR = "Oh... un petit avertissement, hein ? Assez avec les excuses. Alors, où est la marchandise que j’ai demandée ?",
          DialogueId = 12001349,
          FacialId = {
            [1] = "220014:Unhappy01",
            [2] = "100001:Unhappy01",
            [3] = "200002:Angry01"
          },
          GUID = "1E0B4B52",
          LookAt = {
            [1] = "220017:n(220014)",
            [2] = "220045:n(220014)"
          },
          NextDialogue = 12001350,
          SpeakNpcId = 220014,
          Subtitle = "Heh, a little power play, was it? Enough with the excuses. Show me the goods.",
          TalkActionId = {
            [1] = "220014:Talk03_Start",
            [2] = "220018:Talk01_End"
          },
          TurnTo = {
            [1] = "220017:n(220014)",
            [2] = "220045:n(220014)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4B52"
        },
        [12001350] = {
          Camera = "144.626953,288.033691,17.613281,0.000053,6.199516,141.999878,35.000008,313.697113,false,Manual,3.5",
          ContentFR = "Le Phoxichor que vous avez demandé... je l’ai apporté.",
          DialogueId = 12001350,
          FacialId = {
            [1] = "220018:CM_Idle"
          },
          GUID = "1E0B4B7C",
          NextDialogue = 12001351,
          SpeakNpcId = 220018,
          Subtitle = "The Phoxichor you asked for — I have it.",
          TalkActionId = {
            [1] = "220018:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4B7C"
        },
        [12001351] = {
          Camera = "-38.164062,434.716309,-32.25,0.0,4.803002,-86.580322,40.000011,316.356659,false,DoNotOverride,10.0",
          ContentFR = "Je crois reconnaître ce type... Camilla m’en a parlé. C’est le fameux marchand d’armes du marché noir ici. Ses produits sont toujours douteux, et il cherche toujours à gruger tout le monde !",
          DialogueId = 12001351,
          FacialId = {
            [1] = "220014:None"
          },
          GUID = "1E0B4BA6",
          NextDialogue = 12001352,
          Scripts = [[
SEQ{
LookAt{_delay{4},LookAtDescription{"200002:n(220014)"}},
LookAt{_delay{3.5},LookAtDescription{"200002:n(100001)"}},
PlayAnimation{_delay{1},ActorId{200002},AnimationId{"Talk01_Start"},Duration{1}},
LookAt{_delay{0.1},LookAtDescription{"200002:n(220018)"}},
}]],
          SpeakNpcId = 200002,
          Subtitle = "Wait, I know that guy... Camilla told me all about him. He's a notorious underground arms dealer around here. The stuff he peddles is always subpar, and he's always scheming to rip people off!",
          TalkActionId = {
            [1] = "200002:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4BA6"
        },
        [12001352] = {
          Camera = "63.847656,460.318359,7.578125,0.000011,9.802803,-126.5784,40.000011,240.677155,false,Manual,4.0",
          ContentFR = "Laissez-moi clarifier un point. Je ne veux pas n’importe quel Phoxichor que l’on trouve dans la rue. Je veux le plus pur, pas moins de 95 % de pureté. C’est bien clair ?",
          DialogueId = 12001352,
          GUID = "1E0B4BD0",
          NextDialogue = 12001353,
          SpeakNpcId = 220014,
          Subtitle = "Allow me to confirm one last time. I am not seeking just any common Phoxichor that can be procured from a street vendor. My requirement is for the highest grade, with a purity of no less than 95%. Is that understood?",
          TalkActionId = {
            [1] = "220014:Talk03ToTalkR_Start",
            [2] = "200002:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4BD0"
        },
        [12001353] = {
          Camera = "-44.837891,371.257324,-0.773438,0.000035,26.402218,125.022018,25.0,158.270889,false,Manual,10.0",
          ContentFR = "Vous pouvez vérifier vous-même... mais ici, la règle est claire : paiement d’abord, inspection après. Alors, payez, Madame, et après vous pourrez toucher votre marchandise.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001353,
          GUID = "1E0B4BFA",
          NextOptions = {
            [1] = 12001354,
            [2] = 12001355,
            [3] = 12001356
          },
          Scripts = [[
SEQ{
CameraMoveTo{_delay{5},TargetPosition{"637.140625,977.703125,1000.703125,-1.999998,-48.797268,-147.182938,35.000008,158.270889,false,Manual,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"661.132812,993.179199,1033.300781,-1.999999,-48.79726,-147.18251,35.000008,158.270889,false,Manual,10.0"},duration{8}}
}]],
          SpeakNpcId = 220018,
          Subtitle = "You're free to inspect it yourself. But let me make one thing clear — our policy is payment first. Pay up, ma'am, and then it's all yours to examine.",
          TalkActionId = {
            [1] = "220018:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4BFA"
        },
        [12001354] = {
          ContentFR = "<I>Et si ce n’est pas à la hauteur ? Vous offrez un service après-vente ?</>",
          DialogueId = 12001354,
          GUID = "1E0B4C24",
          ImprPlusId = 1008,
          NextDialogue = 12001357,
          Subtitle = "But what if it's not good enough? Do you offer after-sale service?"
        },
        [12001355] = {
          ContentFR = "<I>Cela va à l’encontre des règles commerciales les plus élémentaires...</>",
          DialogueId = 12001355,
          GUID = "1E0B4C4E",
          ImprPlusId = 1007,
          NextDialogue = 12001357,
          Subtitle = "That goes against the most basic rules of fair trade."
        },
        [12001356] = {
          ContentFR = "<I>Vous nous prenez pour des idiots ?</>",
          DialogueId = 12001356,
          GUID = "1E0B4C78",
          ImprPlusId = 1010,
          NextDialogue = 12001357,
          Subtitle = "How gullible do you think we are?"
        },
        [12001357] = {
          Camera = "-75.988281,358.869629,53.726562,0.000057,3.402465,-176.978516,25.000006,158.270889,false,Manual,10.0",
          ContentFR = "Patron ! On est en supériorité... pourquoi faire semblant ? On la frappe et on prend l’argent direct !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001357,
          FinalCamera = "-75.574219,350.87207,53.726562,0.000057,3.402465,-176.978516,25.000006,158.270889,false,Manual,10.0",
          GUID = "1E0B4CA2",
          LookAt = {
            [1] = "220017:n(220018)",
            [2] = "220018:n(220017)"
          },
          NextDialogue = 12001358,
          Scripts = "PlayAnimation{_delay{3},ActorId{220017},AnimationId{\"Angry01_Start\"},Duration{1}}",
          SpeakNpcId = 220017,
          Subtitle = "Boss, why bother with this act? We've got the numbers — let's just beat her up and take the money!",
          TalkActionId = {
            [1] = "220014:Talk03ToTalkR_End"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "220017:n(220018)"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4CA2"
        },
        [12001358] = {
          ContentFR = "<I>Haa... </>Vous vous êtes déjà demandé pourquoi je viens seule, sachant parfaitement que c’était un piège ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001358,
          FacialId = {
            [1] = "220014:Unhappy01"
          },
          GUID = "1E0B4CCC",
          LookAt = {
            [1] = "220017:n(220014)",
            [2] = "220014:n(220014)"
          },
          NextDialogue = 12001359,
          Scripts = [[
PARA{
TurnTo{_delay{3},TurnToDescription{"220014:p(-90)"}},
PlayAnimation{_delay{7},ActorId{220014},AnimationId{"Zhiliu_Story_Special01_Start"},Duration{1}},
SEQ{
CameraMoveTo{_delay{2},TargetPosition{"417.058594,-480.313965,322.75,0.000088,-18.600859,121.800911,35.0,300.0,false,DoNotOverride,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"442.078125,-520.646973,338.714844,0.000088,-18.600859,121.800911,35.0,300.0,false,DoNotOverride,10.0"},duration{8}}
}}]],
          SpeakNpcId = 220014,
          Subtitle = "Have you paused to wonder why I would come here alone, fully aware this was a setup?",
          TalkActionId = {
            [1] = "220017:Angry01_End",
            [2] = "220014:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120013/1E0B4CCC"
        },
        [12001359] = {
          Camera = "-113.576172,153.044434,12.664062,-2.999998,19.998232,75.598701,45.0,118.744087,false,Manual,5.0",
          ContentFR = "Il y a deux possibilités. Soit je suis naïve et je pensais que la transaction se passerait bien... soit je sais très bien que, peu importe le nombre d’hommes que tu as amenés, je sortirai d’ici indemne.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001359,
          FinalCamera = "-111.560547,160.901367,15.617188,-3.0,19.998232,75.598267,45.0,118.744087,false,Manual,5.0",
          GUID = "1E0B4CF6",
