        [12001502] = {
          Camera = "127.935547,523.036133,-20.207031,0.000092,7.799284,-141.520447,15.726627,200.0,false,Manual,10.0",
          ContentFR = "On essayait juste de gagner notre vie... Alors voilà, considérez ce Phoxichor comme un petit cadeau. Une personne aussi généreuse et compréhensive que vous ne nous tiendra pas rigueur, n’est-ce pas ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001502,
          FinalCamera = "134.429688,514.882812,-20.207031,0.000092,7.799284,-141.520447,15.726627,200.0,false,Manual,10.0",
          GUID = "1E0B646C",
          LookAt = {
            [1] = "220018:n(220014)",
            [2] = "220045:n(220014)"
          },
          NextDialogue = 12001503,
          SpeakNpcId = 220018,
          Subtitle = "We're just trying to make ends meet, ma'am... How about this: consider the Phoxichor a little gift from us. Someone as understanding and big-hearted as you wouldn't hold this against a few small-timers like us, right?",
          TalkActionId = {
            [1] = "220045:Shock_Start",
            [2] = "220018:Sigh_Start"
          },
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "100001:n(220018)"
          },
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B646C"
        },
        [12001503] = {
