        [12001545] = {
          ContentFR = "Sans attendre ta réponse, Snow te fourre le journal dans les mains.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001545,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_NewsPaper.T_Guide_Chapter_NewsPaper'}",
          Duration = 4,
          GUID = "1E0B6B51",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 12001546,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{200002},AnimationId{\"Give\"},Duration{1}}",
          Subtitle = "(Without waiting for a response, Snow shoves the newspaper into your hands.)"
        },
        [12001546] = {
          ContentFR = "Haha... Snow, regarde mieux le titre, c’est juste un roman-feuilleton !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001546,
          GUID = "1E0B6B7A",
          NextDialogue = 12001547,
          SpeakNpcId = 220019,
          Subtitle = "Hahaha... Snow, take a closer look at the title. That's a serialised novel!",
          VoiceName = "voice/$Locale$/story/1200/120015/1E0B6B7A"
        },
        [12001547] = {
          Camera = "-648.699707,388.334961,113.205078,0.00046,8.223841,127.532356,35.000008,130.0,false,Manual,10.0",
          ContentFR = "Tu feuilletes distraitement le journal. Soudain, une petite annonce dans un coin attire ton regard.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001547,
          GUID = "1E0B6B7B",
          LookAt = {
            [1] = "100001:p(paper)"
          },
          NextDialogue = 12001548,
          Subtitle = "(You flip through the newspaper absentmindedly. Suddenly, a small ad tucked into the corner catches your eye.)",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [12001548] = {
          Camera = "-711.610291,408.392578,108.566406,0.000428,19.023422,99.934525,45.0,93.029449,false,Manual,10.0",
          ContentFR = "... !",
          DefaultLookAt = "TalkNpc",
