        [12001727] = {
          Camera = "154.790344,-112.125488,118.466553,0.000068,-1.600703,-177.594879,30.0,310.297974,false,Manual,10.0",
          ContentFR = "Petit larbin ! Regarde ! Dans cette cabine rouge, il y a quelqu’un ! Ce serait la personne que tu cherches ?",
