          },
          FinalCamera = "112.303345,-113.901733,117.278809,0.000068,-1.600675,-177.394882,30.0,282.072601,false,Manual,10.0",
          GUID = "1E0B8956",
          LookAt = {
            [1] = "200002:n(220022)",
            [2] = "100001:n(220022)"
          },
          NextDialogue = 12001728,
          Scripts = "TurnTo{_delay{0.5},TurnToDescription{\"100001:p(-90)\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Look, Little Minion! There's someone in that red phone booth! Could that be the person you're looking for?",
