          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8956"
        },
        [12001728] = {
          ContentFR = "De dos, ça lui ressemble... mais je ne peux pas être {性别:sûr|sûre}... je ne vois pas son visage.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001728,
          GUID = "1E0B8980",
          LookAt = {
