          Scripts = "PlayAnimation{_delay{3.5},ActorId{100001},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "It does look like her from behind. But I'm not certain... I can't see her face.",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8980"
        },
        [12001729] = {
          Camera = "65.932007,301.697998,280.254395,0.000109,-22.599722,-120.592827,35.000008,273.028198,false,DoNotOverride,10.0",
          ContentFR = "Alors ! La destination officielle de notre aventure est cette cabine rouge ! Que ce soit elle ou pas, on va vite le savoir !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001729,
          FacialId = {
            [1] = "200002:Confident02"
          },
          FinalCamera = "204.727112,536.455078,393.775391,0.000109,-22.599722,-120.592827,35.000008,273.028198,false,DoNotOverride,10.0",
          GUID = "1E0B89AA",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 12001730,
          SpeakNpcId = 200002,
          Subtitle = "Well then! I hereby declare that the destination of our adventure is that red phone booth right ahead! Whether it's her or not, we'll soon find out!",
