        },
        [12001735] = {
          ContentFR = "Je suis en mission, ne me dérange pas !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001735,
          GUID = "1E0B8AA6",
          NextDialogue = 12001736,
          SpeakNpcId = 220022,
