          NextDialogue = 12001740,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 220023,
          Subtitle = "Understood. Any other unusual activity?",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8B4E"
        },
        [12001740] = {
          ContentFR = "Il y a quatre minutes, une Lunarien est venu quémander une pièce... je l’ai renvoyé.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001740,
          GUID = "1E0B8B78",
          NextDialogue = 12001741,
          SpeakNpcId = 220022,
          SpeakNpcName = "UI_DGNpc_Name_FakeHeitao2",
          Subtitle = "About four minutes ago, a Lunarian approached me asking for a coin. I sent her away.",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8B78"
        },
        [12001741] = {
          Camera = "-114.015625,76.95343,113.664062,0.000097,26.599056,151.814087,40.0,113.044205,false,Manual,10.0",
          ContentFR = "Quoi !? Tu as laissé partir cette Lunarien !?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001741,
          GUID = "1E0B8BA2",
          NextDialogue = 12001742,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 220023,
          Subtitle = "—What!? You just let the Lunarian go!?",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8BA2"
        },
        [12001742] = {
          Camera = "300.930908,-19.562271,574.639893,0.000066,-41.399651,163.008118,35.000011,93.635254,false,DoNotOverride,10.0",
          ContentFR = "... Y a-t-il un problème, Commandant ? La cible est {性别:un jeune homme|une jeune femme} Charon d’environ 18 ans. Il est improbable {性别:qu’il|qu’elle} se soit {性别:déguisé|déguisée} en Lunarien...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001742,
          FacialId = {
            [1] = "220022:CM_Shock01"
          },
          FinalCamera = "274.928467,-11.616699,550.669922,0.000066,-41.399651,163.008118,35.000011,93.635254,false,DoNotOverride,10.0",
          GUID = "1E0B8BCC",
          NextDialogue = 12001743,
          SpeakNpcId = 220022,
          SpeakNpcName = "UI_DGNpc_Name_FakeHeitao2",
          Subtitle = "...Is there a problem, Commander? The target is supposed to be a Charon {性别:young man|young woman} around eighteen years old. It seems highly unlikely {性别:he|she} would disguise {性别:himself|herself} as a Lunarian...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8BCC"
        },
        [12001743] = {
          Camera = "-123.799805,44.557205,158.783203,0.000074,3.399173,132.815735,35.000008,104.267975,false,Manual,10.0",
          ContentFR = "Idiote ! Une personne adulte ne peut pas se transformer en Lunarien, c’est sûr, mais... et si la cible avait une complice ? {性别:Il|Elle} pourrait se cacher à proximité, observant chacun de nos mouvements.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001743,
          GUID = "1E0B8BF6",
          NextDialogue = 12001744,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 220023,
          Subtitle = "Fool! A full-grown person can't turn into a Lunarian, sure, but did it ever occur to you the target might have an accomplice? They could be hiding nearby, watching our every move.",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8BF6"
        },
        [12001744] = {
          Camera = "-4712.811523,-5129.952148,-449.893555,3.000004,7.998759,-159.590851,15.610398,132.488495,false,Manual,10.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "À toutes les unités ! Bloquez immédiatement la place et les zones environnantes. Arrêtez tout ce qui bouge ! Ce soir, même un hibou ne doit pas franchir les murailles de Givrelac !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001744,
          FinalCamera = "-4657.364258,-5152.696777,-458.228516,3.000002,7.998759,-159.590851,15.610398,132.488495,false,Manual,10.0",
          GUID = "1E0B8C20",
          Scripts = [[
PARA{
MoveTo{_delay{0.5},ActorId{220035},MoveSpeed{240},TargetPoint{"point12000305shib3"}},
MoveTo{_delay{0.1},ActorId{220036},MoveSpeed{250},TargetPoint{"point12000305shib4"}}
}]],
          SnapShot = "TELEPHONE",
          SpeakNpcId = 220023,
          Subtitle = "All units, listen up! Lock down the square and the surrounding areas immediately. Detain every living thing in sight! Tonight, not even a night owl escapes Icelake's city walls!",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8C20"
        },
        [12001745] = {
          Camera = "-913.310852,-235.847763,232.883545,0.000173,-9.599646,25.59882,35.0,250.0,false,DoNotOverride,10.0",
          ContentFR = "Alors, petit larbin ? Sans la bravoure et l’ingéniosité du Roi Démon de la Lumière, tu serais tombé dans leur piège !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001745,
          FinalCamera = "-913.310852,-235.847763,202.733154,0.000173,-9.599646,25.598848,35.000008,250.0,false,DoNotOverride,10.0",
          GUID = "1E0B8C4A",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextOptions = {
            [1] = 120017451,
            [2] = 120017461
          },
          SpeakNpcId = 200002,
          Subtitle = "Well, Little Minion? How does it feel to be saved by the brave and brilliant Demon King? Without me, you'd have walked straight into their trap!",
          TalkActionId = {
            [1] = "200002:Alright_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8C4A"
        },
        [12001746] = {
          Camera = "-425.98642,47.386562,174.56543,0.000182,-22.600637,6.394048,40.0,241.074173,false,Manual,10.0",
          ContentFR = "Hum hum ! Continue, j’adore entendre à quel point je suis géniale !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001746,
          FacialId = {
            [1] = "200002:Happy02"
          },
          GUID = "1E0B8C74",
          NextDialogue = 12001748,
          Scripts = "PlayAnimation{_delay{3},ActorId{200002},AnimationId{\"Confident_End\"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "Uh-huh, uh-huh! Keep it coming — I love hearing how awesome I am!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8C74"
        },
        [12001747] = {
          Camera = "-425.98642,47.386562,174.56543,0.000182,-22.600637,6.394048,40.0,241.074173,false,Manual,10.0",
          ContentFR = "Quoi !? Où trouverais-tu une alliée aussi efficace, talentueuse... et surtout aussi mignonne que moi !?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001747,
          FacialId = {
            [1] = "200002:Doubt01"
          },
          GUID = "1E0B8C9E",
          NextDialogue = 12001748,
          Scripts = "PlayAnimation{_delay{3},ActorId{200002},AnimationId{\"Confident_End\"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "What!? Where else would you find a helper as efficient, talented, and — most importantly — adorable as me!?",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8C9E"
        },
        [12001748] = {
          ContentFR = "Sérieusement, ces gens ont vraiment dépassé les bornes en utilisant le nom de Berry comme appât—",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001748,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "1E0B8CC8",
          NextDialogue = 12001749,
          SpeakNpcId = 200002,
          Subtitle = "Seriously though, those people were way out of line, using Berry's name as bait—",
          TalkActionId = {
            [1] = "200002:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8CC8"
        },
        [12001749] = {
          Camera = "-204.335724,17.72283,99.355469,0.000096,16.797182,138.987656,35.000008,90.0,false,DoNotOverride,10.0",
          ContentFR = "Chut... doucement...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001749,
          FacialId = {
            [1] = "100001:Angry01"
          },
          GUID = "1E0B8CF2",
          NextDialogue = 12001750,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"DisagreeHead"},Duration{1}},
LookAt{LookAtDescription{"100001:p(P306)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Shh, keep it down...",
          TalkActionId = {
            [1] = "200002:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8CF2"
        },
        [12001750] = {
          Camera = "-1022.552795,-126.818176,848.524902,0.000189,-8.400995,-9.012328,25.000002,226.894241,false,DoNotOverride,10.0",
          ContentFR = "Au loin, le martèlement des bottes se mêle aux cris perçants d’un commandant donnant ses ordres.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001750,
          Duration = 5,
          FinalCamera = "-1022.552795,-126.818176,848.524902,0.000189,-4.600952,-1.212657,25.000002,226.894241,false,DoNotOverride,10.0",
          GUID = "1E0B8D1C",
          NextDialogue = 12001751,
          Subtitle = "(In the distance, you can hear the rhythmic thud of marching boots and the sharp bark of a commander's orders.)",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8D1C"
        },
        [12001751] = {
          Camera = "-164.022278,-22.917461,79.288574,0.000097,15.397349,134.987732,35.000011,185.594742,false,Manual,10.0",
          ContentFR = "Ils ont capté ! On doit sortir avant qu’ils ne nous encerclent.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001751,
          GUID = "1E0B8D46",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextDialogue = 12001752,
          SpeakNpcId = 100001,
          Subtitle = "Sounds like they've caught on. We need to get out of here before they surround the area.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8D46"
        },
        [12001752] = {
          Camera = "175.55986,-692.047791,275.229248,0.000189,-11.40188,120.590401,35.0,112.434975,false,DoNotOverride,10.0",
          ContentFR = "Reste près de moi, Snow. Allons-y.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001752,
          FinalCamera = "222.318008,-771.149719,293.76001,0.000187,-11.40188,120.590263,35.0,112.434975,false,DoNotOverride,10.0",
          GUID = "1E0B8D70",
          SpeakNpcId = 100001,
          Subtitle = "Stick close to me, Snow. Let's move.",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8D70"
        },
        [12001753] = {
          Camera = "175.711914,-2.875854,107.7854,0.00008,8.799318,-81.197479,35.000008,124.760086,false,Manual,10.0",
          ContentFR = "Toutes les autres issues sont bloquées... sauf cette bouche d’égout.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001753,
          FacialId = {
            [1] = "100001:Angry01",
            [2] = "200002:Sad01"
          },
          FinalCamera = "176.76123,-2.717285,112.566406,0.00008,8.59931,-81.397446,35.000008,124.760086,false,Manual,10.0",
          GUID = "1E0B8D9A",
          LookAt = {
            [1] = "200002:n(200002)"
          },
          NextDialogue = 12001754,
          Scripts = [[
SEQ{
SetLocation{ActorId{210004},TargetPoint{"ZhiliuMove"},Visibility{"Hide"}},
CameraMoveTo{_delay{5},TargetPosition{"369.375488,-400.375,165.608887,0.000044,-8.800562,111.786736,20.216679,130.0,false,DoNotOverride,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"339.014648,-324.414429,152.944336,0.000044,-8.800562,111.786736,20.216679,130.0,false,DoNotOverride,10.0"},duration{6}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Every other escape route has been sealed off and is heavily guarded... except for that manhole over there.",
          TalkActionId = {
            [1] = "200002:BaiTX_Story_Tired_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8D9A"
        },
        [12001754] = {
          Camera = "375.109375,67.12085,53.858154,0.000092,2.599358,-116.196808,48.590485,160.792343,false,Manual,10.0",
          ContentFR = "Haa... encore les égouts... combien de fois faudra-t-il passer par là... Laisse-moi souffler un peu.",
          DialogueId = 12001754,
          GUID = "1E0B8DC4",
          NextDialogue = 12001755,
          Scripts = [[
SEQ{
PlayNormalSound{EventPath{"event:/sfx/common/story/east/intro_carstop"},PlayAs2D{true}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Huff... huff... How many times... do we have to crawl through... the sewers...? Let me... catch my breath first...",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8DC4"
        },
        [12001755] = {
          Camera = "413.716309,-139.636719,9.746826,0.00015,3.035042,107.779106,48.911961,100.0,false,DoNotOverride,10.0",
          ContentFR = "Si tu te faufiles dans cette bouche d’égout, tu tombes droit dans leur piège.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001755,
          FinalCamera = "363.199219,-155.83606,9.746826,0.00015,3.035042,107.779106,48.911961,100.0,false,DoNotOverride,10.0",
          GUID = "1E0B8DEE",
          LookAt = {
            [1] = "100001:n(210004)",
            [2] = "210004:n(100001)"
          },
          NextDialogue = 12001756,
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/mute"}},
MoveTo{ActorId{210004},MoveSpeed{80},TargetPoint{"ZhiliuMove2"}}
}]],
          SpeakNpcId = 210004,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "If you flee into that manhole, you'll be playing right into their hands.",
          ToFinalCameraBlendTime = 5.5,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8DEE"
        },
        [12001756] = {
          Camera = "294.581543,-15.141602,118.058594,0.00012,-10.000578,114.177353,36.7794,100.0,false,DoNotOverride,10.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Dans le traité militaire de Huaxu, il est dit : « Quand tu encercles ton ennemi, laisse toujours une issue. Crée une fausse route pour mieux le piéger. » À l’instant même, qui sait combien de soldats impériaux se cachent dans les égouts ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001756,
          FacialId = {
            [1] = "100001:Shock01"
          },
          FinalCamera = "294.581543,-15.141602,118.058594,0.000118,6.999502,115.174156,36.779404,100.0,false,DoNotOverride,10.0",
          GUID = "1E0B8E18",
          NextDialogue = 12001757,
          SpeakNpcId = 210004,
          Subtitle = "There's a saying in Huaxu's ancient art of war: \"When thou dost besiege thy foe, leaveth an opening; a feigned escape, a snare in disguise.\" It means forging a false escape route to lure the enemy into your trap. Right now, there should be countless Imperial soldiers lying in wait down there.",
          TalkActionId = {
            [1] = "210004:Talk03_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8E18"
        },
        [12001757] = {
          Camera = "212.067383,-7.164917,141.246582,0.000089,-0.600524,85.404076,35.000008,138.40242,false,Manual,10.0",
          ContentFR = "Allez, monte !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001757,
          FacialId = {
            [1] = "210004:Smile01"
          },
          GUID = "1E0B8E42",
          NextDialogue = 12001758,
          SpeakNpcId = 210004,
          Subtitle = "Come on, get in.",
          TalkActionId = {
            [1] = "210004:Talk03ToTalkL_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8E42"
        },
        [12001758] = {
          Camera = "262.360352,20.961182,141.071045,0.000118,-4.199665,-113.39299,35.000011,152.94194,false,Manual,10.0",
          ContentFR = "Madame... euh, Patronne Zhiliu ! Que faites-vous ici ?",
          DialogueId = 12001758,
          FacialId = {
            [1] = "100001:Shock02"
          },
          GUID = "1E0B8E6C",
          LookAt = {
            [1] = "100001:n(210004)",
            [2] = "200002:n(210004)"
          },
          NextDialogue = 12001759,
          SpeakNpcId = 100001,
          Subtitle = "Lady Zhiliu... No, Proprietress Zhiliu— what are you doing here?",
          TalkActionId = {
            [1] = "100001:Talk02_Start",
            [2] = "200002:BaiTX_Story_Tired_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8E6C"
        },
        [12001759] = {
          Camera = "263.743164,-274.392456,127.796387,0.00015,-2.60013,101.20816,35.0,400.0,false,Manual,10.0",
          ContentFR = "Je venais pour te dire au revoir... mais il semble que ce ne soit plus nécessaire.",
          DialogueId = 12001759,
          FacialId = {
            [1] = "100001:None",
            [2] = "200002:None"
          },
          GUID = "1E0B8E96",
          NextDialogue = 12001760,
          SpeakNpcId = 210004,
          Subtitle = "I came to bid you farewell. But apparently, that's unnecessary now.",
          TalkActionId = {
            [1] = "210004:Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8E96"
        },
        [12001760] = {
          Camera = "267.479004,9.616211,119.475098,0.000074,9.399432,110.6063,35.000011,124.361229,false,Manual,10.0",
          ContentFR = "Tu comptes rester là à bavarder, ou tu préfères qu’on parte avant qu’ils t’attrapent ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001760,
          GUID = "1E0B8EC0",
          NextDialogue = 12001761,
          SpeakNpcId = 210004,
          Subtitle = "So, what will it be? Do you want to stay here exchanging pleasantries, or shall we depart before they catch you?",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8EC0"
        },
        [12001761] = {
          Camera = "217.206543,35.907349,156.063477,0.000065,-9.400607,-97.392738,35.000015,163.255356,false,Manual,15.0",
          ContentFR = "... Compris !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001761,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1E0B8EEA",
          SpeakNpcId = 100001,
          Subtitle = "...Understood!",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8EEA"
        },
        [12001762] = {
          Camera = "55.601562,-74.976562,92.190918,0.000011,13.599883,168.789474,35.000019,257.48999,false,Manual,10.0",
          ContentFR = "Qui va là ? Halte !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001762,
          GUID = "1E0B8F14",
          NextDialogue = 12001763,
          SpeakNpcId = 220025,
          Subtitle = "Halt! Who goes there?",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8F14"
        },
        [12001763] = {
          ContentFR = "Ordres venus d’en haut, ce soir, aucun individu suspect ne doit passer. Merci de votre coopération. ",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001763,
          GUID = "1E0B8F3E",
          LookAt = {
            [1] = "220025:n(220014)"
          },
          NextDialogue = 120017641,
          SpeakNpcId = 220025,
          Subtitle = "Orders from above — no suspicious individuals are allowed through tonight. I'm going to need your full cooperation.",
          TalkActionId = {
            [1] = "220025:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8F3E"
        },
        [12001764] = {
          Camera = "-462.479492,486.855469,394.952148,0.000034,-20.000547,-54.008591,35.000008,100000.0,false,DoNotOverride,10.0",
          ContentFR = "Eh bien... En venant, j’ai croisé de nombreuses patrouilles dans les rues. Pourrais-je savoir ce qu’il en est ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001764,
          FinalCamera = "-462.479492,486.855469,339.495117,0.000034,-20.000547,-54.008591,35.000008,100000.0,false,DoNotOverride,10.0",
          GUID = "1E0B8F68",
          LookAt = {
            [1] = "220014:n(220025)",
            [2] = "100001:n(220025)",
            [3] = "200002:n(220025)"
          },
          NextDialogue = 12001765,
          Scripts = [[
PARA{
MoveTo{ActorId{220014},MoveSpeed{80},TargetPoint{"ZhiliuMove_309"}},
MoveTo{ActorId{200002},MoveSpeed{80},TargetPoint{"BaiMove_309"}},
MoveTo{ActorId{100001},MoveSpeed{80},TargetPoint{"ZhujueMove_309"}},
StopNormalSound{EventKey{"carplay"}}
}]],
          SpeakNpcId = 220014,
          Subtitle = "Oh my, I noticed quite a few patrols on the streets earlier. May I ask if something has happened?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8F68"
        },
        [12001765] = {
          Camera = "194.37793,-166.161133,140.183105,0.000003,-1.799557,152.996048,37.747215,362.031006,false,Manual,10.0",
          ContentFR = "En quoi ça te regarde ? C’est une information classifiée—",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001765,
          GUID = "1E0B8F92",
          NextDialogue = 12001766,
          SpeakNpcId = 220025,
          Subtitle = "What business is that of yours? That's classified information—",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8F92"
        },
        [12001766] = {
          Camera = "-108.702148,25.432129,82.476562,0.000077,13.598018,-45.800716,51.545876,204.890732,false,Manual,3.882469",
          ContentFR = "La réprimande du soldat s’interrompt brusquement. Du coin de l’œil, tu vois Zhiliu lui remettre un petit sac lourd. Le soldat l’évalue d’un geste discret et le glisse dans sa manche sans un mot.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001766,
          Duration = 5,
          GUID = "1E0B8FBC",
          NextDialogue = 12001767,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"100001:p(Nvzhu_Look_309)\"}}",
          Subtitle = "(The soldier's outburst stops short. Out of the corner of your eye, you see Zhiliu hand him a small, weighty pouch. The soldier weighs it in his hand before discreetly slipping it into his sleeve.)",
          TalkActionId = {
            [1] = "220014:Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8FBC"
        },
        [12001767] = {
          Camera = "355.125,200.536621,154.582031,0.000034,-5.1997,-148.204956,35.000011,100000.0,false,DoNotOverride,10.0",
          ContentFR = "Eh bien... il n’y a pas de mal à partager un peu. Ce soir, nous devons arrêter {性别:un fugitif|une fugitive} de grande importance. Toutes les forces de la cité ont été mobilisées pour la recherche.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001767,
          GUID = "1E0B8FE6",
          LookAt = {
            [1] = "100001:n(220025)"
          },
          NextDialogue = 12001768,
          SpeakNpcId = 220025,
          Subtitle = "Well... I suppose there's no harm in sharing a little. We've been told to catch a high-profile fugitive tonight. Every guard in the city has been called in for the search.",
          TalkActionId = {
            [1] = "220014:Talk02R_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8FE6"
        },
        [12001768] = {
          ContentFR = "Le problème, c’est que personne ne sait où se cache {性别:ce fugitif|cette fugitive}... ni à quoi {性别:il|elle} ressemble.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001768,
          GUID = "1E0B9010",
          NextDialogue = 12001769,
          SpeakNpcId = 220025,
          Subtitle = "Problem is, nobody seems to know where this fugitive is hiding — or what they even look like.",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9010"
        },
        [12001769] = {
          Camera = "-270.78418,255.63623,167.03418,0.000086,-8.000794,-55.608383,35.000011,100000.0,false,DoNotOverride,10.0",
          ContentFR = "Hmm... c’est ennuyeux... Vous voyez, je suis une commerçante de Huaxu. Mon dirigeable privé est amarré juste à l’extérieur de la cité. Dans six heures, j’ai un rendez-vous commercial très important.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001769,
          GUID = "1E0B903A",
          LookAt = {
            [1] = "100001:n(220025)",
            [2] = "200002:n(220025)"
          },
          NextDialogue = 12001770,
          SpeakNpcId = 220014,
          Subtitle = "Ah, that's unfortunate... You see, I'm a merchant from Huaxu, and my private airship is docked just outside the city. In six hours, I have an important business meeting that I simply cannot miss.",
          TalkActionId = {
            [1] = "220014:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B903A"
        },
        [12001770] = {
          ContentFR = "Tous les membres à bord, moi y comprise, sommes des citoyens respectables, avec tous les papiers de sortie officiels. Ne pourrait-on pas faire une exception ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001770,
          GUID = "1E0B9064",
          NextDialogue = 12001771,
          SpeakNpcId = 220014,
          Subtitle = "Everyone aboard, myself included, is a law-abiding citizen with all the proper exit permits. Surely you could find it in your heart to make an exception?",
          TalkActionId = {
            [1] = "220014:Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9064"
        },
        [12001771] = {
          Camera = "-90.224609,27.822266,129.658691,0.000123,-0.199885,-48.183372,51.572987,182.084885,false,Manual,10.0",
          ContentFR = "En observant les documents que Zhiliu présente, tu remarques ta propre photo soigneusement apposée. Ton expression légèrement sérieuse sur cette photo te paraît étrange.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001771,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_Passport.T_Guide_Chapter_Passport'}",
          Duration = 5,
          FinalCamera = "-83.21582,19.981934,129.623047,0.000123,-0.199885,-48.18306,51.572987,171.736893,false,Manual,10.0",
          GUID = "1E0B908E",
          NextDialogue = 12001772,
          Subtitle = "(Among the documents Zhiliu presents, you spot your own photograph neatly attached in the designated section. The stern expression in the picture feels oddly unfamiliar.)",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B908E"
        },
        [12001772] = {
          ContentFR = "<I>Quand est-ce qu’elle a préparé tout ça... ?</>",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001772,
          DisableMouth = 1,
          Duration = 5,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E0B90B8",
          LookAt = {
            [1] = "220014:n(220025)"
          },
          NextDialogue = 12001773,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...When did she prepare these documents?)",
          TalkActionId = {
            [1] = "220014:Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B90B8"
        },
        [12001773] = {
          Camera = "100.349609,-20.827148,139.20459,0.000054,-0.000246,-172.803757,35.000011,264.540283,false,Manual,6.124233",
          ContentFR = "Madame... ce n’est pas pour vous mettre des bâtons dans les roues, mais nos ordres sont stricts : personne ne passe par ici ce soir.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001773,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1E0B90E2",
          LookAt = {
            [1] = "220025:n(220014)"
          },
          NextDialogue = 12001774,
          SpeakNpcId = 220025,
          Subtitle = "Ma'am... It's not my intention to give you a hard time, but our orders are clear — no one is allowed through here tonight.",
          TalkActionId = {
            [1] = "220025:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B90E2"
        },
        [12001774] = {
          Camera = "-410.826172,260.788574,156.883301,0.000045,-3.800918,-40.007858,60.419567,100000.0,false,DoNotOverride,10.0",
          ContentFR = "Oh ? Dans ce cas, donnez-moi donc le numéro de votre régiment et le nom de votre supérieur. Je trouverai bien un moyen de régler ça moi-même.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001774,
          GUID = "1E0B910C",
          NextDialogue = 12001775,
          SpeakNpcId = 220014,
          Subtitle = "Oh? I see. Then perhaps you could tell me your regiment number and the name of your commanding officer. I may be able to sort this out myself.",
          TalkActionId = {
            [1] = "220014:Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B910C"
        },
        [12001775] = {
          Camera = "-60.169922,20.828613,119.424805,0.000075,12.599663,-45.606236,46.428596,118.094795,false,Manual,10.0",
          ContentFR = "Si Luciana Loretto venait à apprendre que je suis retenue par un simple soldat et que j’ai manqué une négociation capitale, imaginez donc comme l’histoire ferait sourire à l’heure du goûter.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001775,
          GUID = "1E0B9136",
          NextDialogue = 12001776,
          SpeakNpcId = 220014,
          Subtitle = "After all, if Luciana Loretto were to hear that I was detained by a foot soldier and missed a crucial business engagement, wouldn't that make for quite the amusing tale over afternoon tea?",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9136"
        },
        [12001776] = {
          Camera = "24.524414,3.004395,148.750488,0.000044,-2.599973,-158.404205,35.000008,100000.0,false,DoNotOverride,10.0",
          ContentFR = "Luciana Loretto... attendez, c’est bien la Ministre Impériale des Finances !?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001776,
          GUID = "1E0B9160",
          LookAt = {
            [1] = "220026:n(220025)",
            [2] = "220025:n(220026)"
          },
          NextDialogue = 12001777,
          SpeakNpcId = 220026,
          Subtitle = "Luciana Loretto... Wait, isn't that the Imperial Minister of Finance!?",
          TalkActionId = {
            [1] = "220025:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9160"
        },
        [12001777] = {
          ContentFR = "Hé, regarde ! Le document porte vraiment sa signature personnelle !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001777,
          GUID = "1E0B918A",
          NextDialogue = 12001778,
          SpeakNpcId = 220026,
          Subtitle = "Hey, look — this document actually bears her personal signature!",
          TalkActionId = {
            [1] = "220014:Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B918A"
        },
        [12001778] = {
          ContentFR = "Euh...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001778,
          GUID = "1E0B91B4",
          LookAt = {
            [1] = "220025:n(220014)"
          },
          NextDialogue = 12001779,
          SpeakNpcId = 220025,
          Subtitle = "Er...",
          TalkActionId = {
            [1] = "220025:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B91B4"
        },
        [12001779] = {
          Camera = "-491.920898,478.322754,448.695801,0.000088,-10.999807,-47.399258,9.196175,100000.0,false,DoNotOverride,10.0",
          ContentFR = "À toutes les unités ! La cible a été repérée près du théâtre, armée, en tentative de fuite. Les escouades proches doivent converger immédiatement. Je répète : convergez sans délai vers le théâtre !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001779,
          FinalCamera = "-491.920898,478.322754,448.695801,0.000088,-1.599603,-42.39946,9.196175,100000.0,false,DoNotOverride,10.0",
          GUID = "1E0B91DE",
          NextDialogue = 12001780,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/intro_crowdcombat\"},PlayAs2D{true}}",
          Subtitle = "Attention, all units! The target is believed to have been sighted near the theatre, armed and attempting to escape. Nearby squads, proceed to the location immediately. I repeat — nearby squads, converge on the theatre for support!",
          TalkActionId = {
            [1] = "220025:Shock_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B91DE"
        },
        [12001780] = {
          Camera = "-245.133789,192.716309,132.871094,0.00009,-3.199267,-51.80265,30.0,100000.0,false,DoNotOverride,10.0",
          ContentFR = "On dirait que votre {性别:fugitif|fugitive} s’est enfin montré. Alors, messieurs, comptez-vous encore nous retenir ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001780,
          FacialId = {
            [1] = "220014:Smile01"
          },
          GUID = "1E0B9208",
          LookAt = {
            [1] = "220014:n(220025)",
            [2] = "100001:n(220025)",
            [3] = "200002:n(220025)"
          },
          NextDialogue = 12001781,
          SpeakNpcId = 220014,
          Subtitle = "It seems your fugitive has finally turned up. So, what now? Do you still intend to detain us?",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9208"
        },
        [12001781] = {
          Camera = "259.166016,139.326172,124.026855,0.0001,-2.599324,-148.204941,30.000002,100000.0,false,DoNotOverride,10.0",
          ContentFR = "... Très bien, madame. Nous ne vous retarderons pas davantage. Mais une escouade vous accompagnera pour garantir votre départ sans encombre.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001781,
          GUID = "1E0B9232",
          NextDialogue = 12001782,
          SpeakNpcId = 220025,
          Subtitle = "...How about this, ma'am: we won't delay your journey any further, but we'll assign personnel to escort you and ensure safe passage out of the city.",
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9232"
        },
        [12001782] = {
          ContentFR = "Jusqu’au décollage de votre dirigeable, vous et vos compagnons resterez dans notre champ de vision. Tout mouvement suspect sera interprété comme une provocation envers l’Empire. Cela vous convient-il ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001782,
          GUID = "1E0B925C",
          NextDialogue = 12001783,
          SpeakNpcId = 220025,
          Subtitle = "Until your airship departs, you and your party must remain in our line of sight. Any unusual behaviour will be treated as an act of provocation against the Empire. Does that sound acceptable?",
          TalkActionId = {
            [1] = "220014:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B925C"
        },
        [12001783] = {
          Camera = "-247.888672,60.718262,171.297363,0.000116,-9.999724,-29.603325,35.000011,298.698639,false,Manual,10.0",
          ContentFR = "Héhé... mais bien sûr. Faciliter le travail d’autrui, c’est aussi se faciliter la vie. Comptez sur ma coopération.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001783,
          GUID = "1E0B9286",
          LookAt = {
            [1] = "100001:n(220025)"
          },
          NextDialogue = 12001784,
          SpeakNpcId = 220014,
          Subtitle = "Hehe... That's perfectly fine. Helping others, as they say, is helping oneself. Rest assured, I'll cooperate fully.",
          TalkActionId = {
            [1] = "220014:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9286"
        },
        [12001784] = {
          Camera = "-459.007812,408.505859,307.084473,0.000125,-16.999718,-52.801178,21.614788,100000.0,false,DoNotOverride,10.0",
          ContentFR = "Merci de votre compréhension... Laissez-les passer !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001784,
          FinalCamera = "-534.192383,507.5625,345.104492,0.000125,-16.999718,-52.801178,21.614788,100000.0,false,DoNotOverride,10.0",
          GUID = "1E0B92B0",
          SpeakNpcId = 220025,
          Subtitle = "Thank you for your understanding, ma'am. Let them through!",
          TalkActionId = {
            [1] = "220014:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B92B0"
        },
        [12001785] = {
          ContentFR = "Snow s’éloigne en bougonnant.",
          DialogueId = 12001785,
          GUID = "1E0B8AD1",
          Subtitle = "Snow stormed off in a huff."
        },
        [12001801] = {
          Camera = "26.581055,-95.871094,153.29248,0.000088,-8.170654,-51.38456,12.0,60.0,false,Manual,10.0",
          ContentFR = "Bien, nous pouvons parler librement à présent. Gardez seulement un visage impassible : les soldats sont toujours derrière, et ils font leur devoir avec zèle.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001801,
          FinalCamera = "1.03418,-98.566895,152.582031,0.000092,-8.970668,-40.585316,12.0,100.0,false,Manual,10.0",
          GUID = "1E0B957A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001830,
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/1_0/0085_scene_icelake"}},
PlayNormalSound{EventKey{"car2drive"},EventPath{"event:/sfx/common/story/yinru/car_drive"},PlayAs2D{true}}
}]],
          SpeakNpcId = 220014,
          Subtitle = "Alright, we can speak freely now. Just be sure to keep your expressions in check — those soldiers are still dutifully trailing behind us.",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B957A",
          bNotRecall = 1
        },
        [12001802] = {
          ContentFR = "Ah, ça ? Juste un Chasseur de Phoxène que j’ai engagé.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001802,
          GUID = "1E0B95A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001803,
          SpeakNpcId = 220014,
          Subtitle = "Ah, that would be a Phoxhunter I hired.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B95A4"
        },
        [12001803] = {
          ContentFR = "Il n’a fallu qu’une maigre récompense pour qu’il accepte ce risque. Une somme si dérisoire qu’elle ne suffirait même pas à payer le chien de chasse d’une ministre impériale dans sa résidence de campagne.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001803,
          GUID = "1E0B95CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001804,
          SpeakNpcId = 220014,
          Subtitle = "It required very little — just a modest sum of money to entice someone into taking the risk. The amount was so minimal, it wouldn't even cover the cost of a single hunting hound owned by the Finance Minister at her countryside estate.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B95CE"
        },
        [12001804] = {
          ContentFR = "Mais grâce à lui, nous avons pu traverser cette crise sans encombre.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001804,
          GUID = "1E0B95F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001830,
          SpeakNpcId = 220014,
          Subtitle = "And yet, that small investment was all it took to steer us safely through tonight's crisis.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B95F8"
        },
        [12001805] = {
          ContentFR = "Veux-tu entendre une histoire intéressante ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001805,
          GUID = "1E0B9622",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001806,
          SpeakNpcId = 220014,
          Subtitle = "Would you like to hear something intriguing?",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9622"
        },
        [12001806] = {
          ContentFR = "<I>Le Journal Impérial</> est distribué dans tout l’Empire. Et, comme par hasard, chaque grande cité possède une cabine téléphonique rouge en plein cœur de sa place centrale.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001806,
          GUID = "1E0B964C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001807,
          SpeakNpcId = 220014,
          Subtitle = "The Hyperborea Daily is a newspaper sold throughout the entire Empire. And, as it happens, every major city in Hyperborea has... a red phone booth in its central square.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B964C"
        },
        [12001807] = {
          ContentFR = "Ce matin, Camilla m’a rapporté toute l’affaire autour de cet article. Alors, par précaution, j’ai envoyé quelques télégrammes supplémentaires.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001807,
          GUID = "1E0B9676",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001808,
          SpeakNpcId = 220014,
          Subtitle = "This morning, Camilla shared the story behind that article with me. After hearing the details, I decided to take precautions and sent out a few extra telegrams.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9676"
        },
        [12001808] = {
          ContentFR = "Et voici la bonne nouvelle : ce soir, dans chacune de ces villes, une femme aux cheveux blancs attend patiemment dans une cabine rouge... une \"famille perdue depuis longtemps\" qui n’arrivera jamais.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001808,
          GUID = "1E0B96A0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001809,
          SpeakNpcId = 220014,
          Subtitle = "Here's some good news for you: tonight, in each of those cities, a white-haired woman is standing inside a red phone booth, patiently awaiting a \"long-lost family\" who will never arrive.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B96A0"
        },
        [12001809] = {
          ContentFR = "Hein ? Pourquoi c’est une bonne nouvelle, ça ? Je ne comprend pas...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001809,
          GUID = "1E0B96CA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001810,
          SpeakNpcId = 200002,
          Subtitle = "Why is that good news? I don't get it...",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B96CA"
        },
        [12001810] = {
          ContentFR = "Je pense que la Patronne Zhiliu veut dire qu’ils ignorent où je me trouve. Peut-être même qu’ils ne savent pas si je suis encore en vie. Du coup, ils ont dû disperser des leurres un peu partout pour tenter de me faire sortir...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001810,
          GUID = "1E0B96F4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001811,
          SpeakNpcId = 100001,
          Subtitle = "I think Proprietress Zhiliu means they aren't sure where I am — or even if I'm still alive. So, they had to scatter their bait across multiple cities to draw me out...",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B96F4"
        },
        [12001811] = {
          ContentFR = "Exactement. Quelle perspicacité.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001811,
          GUID = "1E0B971E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001812,
          SpeakNpcId = 220014,
          Subtitle = "Precisely. You're quite the clever one.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B971E"
        },
        [12001812] = {
          ContentFR = "<I>Qui, dans la Légion, a pu monter un stratagème aussi vaste... juste pour moi ?</>",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001812,
          GUID = "1E0B9748",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001830,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(They know I exist, and they've gone to such lengths to set such a complicated trap... Who in the Legion could be behind this?)",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9748"
        },
        [12001813] = {
          ContentFR = "Dans l’état actuel des choses, tu ne pourras sans doute pas quitter le véhicule avant le décollage. Pardonne-moi... mais il semblerait que tu doives m’accompagner jusqu’à Huaxu.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001813,
          GUID = "1E0B9772",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001814,
          RelatedWikiId = {
            [1] = 203001,
            [2] = 408010
          },
          SpeakNpcId = 220014,
          Subtitle = "Given the current circumstances, I'm afraid you can't leave the car until the airship departs. My apologies — it appears I'll have to take you to Huaxu with me.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9772"
        },
        [12001814] = {
          ContentFR = "Patronne Zhiliu, vous m’avez déjà tiré d’affaire plusieurs fois. Je ne sais même pas comment vous remercier...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001814,
          GUID = "1E0B979C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001815,
          SpeakNpcId = 100001,
          Subtitle = "Proprietress Zhiliu, you've saved me from trouble on multiple occasions. I don't even know how to begin repaying you.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B979C"
        },
        [12001815] = {
          ContentFR = "Mmh... remercier, dis-tu ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001815,
          GUID = "1E0B97C6",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001816,
          SpeakNpcId = 220014,
          Subtitle = "Repay me? Hmm...",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B97C6"
        },
        [12001816] = {
          ContentFR = "Ça tombe bien, j’ai justement un petit travail qui manque de bras. Le dirigeable de Huaxu retournera à Hyperborea dans sept jours. En attendant, si tu ne vois pas d’inconvénient à rester à mes côtés, tu pourrais me prêter main-forte.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001816,
          GUID = "1E0B97F0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001817,
          SpeakNpcId = 220014,
          Subtitle = "As it happens, there is a task that would benefit from an extra pair of capable hands. The airship returning from Huaxu to Hyperborea departs in seven days. If you don't mind staying with me until then, perhaps you could assist me.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B97F0"
        },
        [12001817] = {
          ContentFR = "Qu’en dis-tu, {性别:petit prodige|petite prodige} ? Rassure-toi, la rémunération sera à la hauteur.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001817,
          GUID = "1E0B981A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001818,
          SpeakNpcId = 220014,
          Subtitle = "What do you say, my clever one? Of course, the compensation will be more than fair.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B981A"
        },
        [12001818] = {
          ContentFR = "<I>Comme je m’en doutais... ce n’est pas un hasard.</>",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001818,
          GUID = "1E0B9844",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextOptions = {
            [1] = 12001819,
            [2] = 12001820
          },
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(I knew it... This was far too convenient to be a mere coincidence.)",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9844"
        },
        [12001819] = {
          ContentFR = "<I>Maintenant que je suis montée à bord, refuser n’est plus vraiment une option, n’est-ce pas ?</>",
          DialogueId = 12001819,
          GUID = "1E0B986E",
          ImprPlusId = 1006,
          NextDialogue = 12001821,
          Subtitle = "Now that I'm in this car... I suppose refusing isn't really an option, is it?"
        },
        [12001820] = {
          ContentFR = "<I>Vous m’avez tant aidé... je serais {性别:heureux|heureuse} de vous rendre la pareille.</>",
          DialogueId = 12001820,
          GUID = "1E0B9898",
          ImprPlusId = 1007,
          NextDialogue = 12001821,
          Subtitle = "You've helped me plenty of times — I'd be more than happy to return the favour."
        },
        [12001821] = {
          ContentFR = "Voyager jusqu’à un pays lointain, goûter à des plats inconnus, et en plus gagner une belle récompense... Petit larbin, ça sonne comme une super aventure, pas vrai ?!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001821,
          GUID = "1E0B98C2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001822,
          SpeakNpcId = 200002,
          Subtitle = "Travelling to a far-off country, trying foods we've never seen before, and earning a hefty reward on top of it... Little Minion, doesn't that sound like the perfect adventure?",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B98C2"
        },
        [12001822] = {
          ContentFR = "Avant de partir... pourrais-je vous demander encore un service ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001822,
          GUID = "1E0B98EC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001823,
          SpeakNpcId = 100001,
          Subtitle = "By the way, before we leave... may I ask one more favour?",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B98EC"
        },
        [12001823] = {
          ContentFR = "Pas d’inquiétude. J’ai engagé d’autres petites mains dans les autres villes. Avec autant de \"poissons\" qui mordent à l’hameçon, les soldats hyperboréens ne pourront rien conclure ce soir. Ils n’auront jamais la moindre idée que tu étais à Givrelac.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001823,
          GUID = "1E0B9916",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001824,
          SpeakNpcId = 220014,
          Subtitle = "There's no need to worry. I've hired temporary workers in other cities as well. With so many \"fish\" taking the bait across the country, the Hyperborean soldiers will be kept busy tonight and come up empty-handed — they won't have a clue you're actually here in Icelake.",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9916"
        },
        [12001824] = {
          ContentFR = "<I>Elle avait même prévu ça... Mais qu’est-ce que cette femme de Huaxu attend réellement de moi ?</>",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001824,
          GUID = "1E0B9940",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001825,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(She even accounted for that... Just what does this Huaxu lady really want from me...?)",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9940"
        },
        [12001825] = {
          ContentFR = "<I>Enfin... à ce stade, je n’ai plus vraiment le choix. Sept jours, c’est encore raisonnable.</>",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001825,
          GUID = "1E0B996A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001826,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(But at this point, there's really no other way. Seven days... that should be manageable.)",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B996A"
        },
        [12001826] = {
          ContentFR = "Très bien ! Nous acceptons cette mission !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001826,
          GUID = "1E0B9994",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          Scripts = "StopNormalSound{EventKey{\"car2drive\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Alright! We'll take on this commission!",
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9994"
        },
        [12001830] = {
          DialogueId = 12001830,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 12001813,
          GUID = "1E0B957B",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextOptions = {
            [1] = 120018011,
            [2] = 120018041
          }
        },
        [12001901] = {
          Content = "假装这里非常热闹、节日氛围",
          DialogueId = 12001901,
          GUID = "1E0BA5E2"
        },
        [12002001] = {
