        },
        [12002100] = {
          Content = "假装潜行玩法",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12002100,
          GUID = "1E0BC688"
        },
        [12003001] = {
          Content = "假装这里坐下来了，后面k一个Sequence",
          DialogueId = 12003001,
          GUID = "1E0C5A5A"
        },
        [12003101] = {
          Content = "假装把止流带走",
          DialogueId = 12003101,
          GUID = "1E0C6AC2"
        },
        [12003201] = {
          Content = "假装2D图",
          DialogueId = 12003201,
          GUID = "1E0C7B2A"
        },
        [12003301] = {
          Content = "这里就把玩家传到东国了",
          DialogueId = 12003301,
          GUID = "1E0C8B92"
        },
        [12003401] = {
          Content = "假装开车出城的Sequence",
          DialogueId = 12003401,
          GUID = "1E0C9BFA"
        },
        [12004001] = {
          Camera = "127.357666,-54.3125,106.762451,0.000013,7.799898,-163.400085,35.0,100000.0,False,Manual,10.0",
          Content = "选A还是B",
          DialogueId = 12004001,
          GUID = "1E0CFE6A",
          SpeakNpcId = 100001
        },
        [12004002] = {
          Content = "A",
          DialogueId = 12004002,
          GUID = "1E0CFE94",
          SpeakNpcId = 100001
        },
        [12004003] = {
          Content = "B",
          DialogueId = 12004003,
          GUID = "1E0CFEBE",
          SpeakNpcId = 200002
        },
        [12004101] = {
          ContentFR = "Ouah... Il y a tellement de monde ! Tout ça, c’est pour le spectacle ?",
          DialogueId = 12004101,
          GUID = "1E0AE102",
          NextDialogue = 12004102,
          SpeakNpcId = 200002,
          Subtitle = "Wow... Look at all these people. Are they all here for the show?",
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE102"
        },
        [12004102] = {
          ContentFR = "Ils ont l’air de discuter de choses passionnantes. Petit larbin, allons écouter !",
          DialogueId = 12004102,
          GUID = "1E0D0EFC",
          SpeakNpcId = 200002,
          Subtitle = "They seem to be talking about something interesting. Little Minion, let's go check it out.",
          VoiceName = "voice/$Locale$/story/1200/120041/1E0D0EFC"
        },
        [12004201] = {
          ContentFR = "Dis, grande sœur Zhiliu... tu vas aux Asphodèles pour voir quelqu’un, pas vrai ?",
          DialogueId = 12004201,
          GUID = "1E0D1F3A",
          NextDialogue = 12004202,
          SpeakNpcId = 200002,
          Subtitle = "Are you going to The Asphodel to meet someone?",
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1F3A"
        },
        [12004202] = {
          ContentFR = "Laisse-moi deviner... ce ne serait pas une patronne aux cheveux blonds bouclés, avec une langue bien acérée ?",
          DialogueId = 12004202,
          GUID = "1E0D1F64",
          NextDialogue = 12004203,
          SpeakNpcId = 200002,
          Subtitle = "Hmm... Let me guess... Could it be a boss lady with golden curls and a sharp tongue?",
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1F64"
        },
        [12004203] = {
          ContentFR = "Héhé... tu as visé juste.",
          DialogueId = 12004203,
          GUID = "1E0D1F8E",
          NextDialogue = 12004204,
          SpeakNpcId = 220014,
          Subtitle = "Hehe, you got that right.",
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1F8E"
        },
        [12004204] = {
          ContentFR = "Évidemment ! Le Roi Démon ne se trompe jamais.",
          DialogueId = 12004204,
          GUID = "1E0D1FB8",
          NextDialogue = 12004205,
          SpeakNpcId = 200002,
          Subtitle = "This Demon King just never misses a guess!",
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1FB8"
        },
        [12004205] = {
          ContentFR = "Ah, mais... surtout, ne répète pas ce que je viens de dire à Camilla, d’accord ? Sinon, adieu mon argent de poche...",
          DialogueId = 12004205,
          GUID = "1E0D1FE2",
          SpeakNpcId = 200002,
          Subtitle = "Oh, but please don't tell Camilla about the sharp tongue part, or my allowance for today would be gone forever...",
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1FE2"
        },
        [12004206] = {
          ContentFR = "Voilà, on est arrivés !",
          DialogueId = 12004206,
          GUID = "1E0D200C",
          SpeakNpcId = 200002,
          Subtitle = "Here we are— ",
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D200C"
        },
        [12004301] = {
          ContentFR = "Snow s’éloigne en bougonnant.",
          DialogueId = 12004301,
          Duration = 2,
          GUID = "1E0D2FA2",
          Subtitle = "Snow stormed off in a huff.",
          VoiceName = "voice/$Locale$/story/1200/120043/1E0D2FA2"
        },
        [12004401] = {
          ContentFR = "Ces machines là-bas ont l’air bizarres... Hum, vaut mieux qu’on les évite !",
          DialogueId = 12004401,
          GUID = "1E0D400A",
          SpeakNpcId = 200002,
          Subtitle = "The machines over there look weird... Um, we'd better stay away from them!",
          VoiceName = "voice/$Locale$/story/1200/120044/1E0D400A"
        },
        [12004402] = {
          ContentFR = "Elles se sont tournées ! Maintenant !",
          DialogueId = 12004402,
          GUID = "1E0D4034",
          SpeakNpcId = 200002,
          Subtitle = "It turned away! Now's the time!",
          VoiceName = "voice/$Locale$/story/1200/120044/1E0D4034"
        },
        [12004501] = {
          ContentFR = "<W>Cible repérée. Cible repérée.</>",
          DialogueId = 12004501,
          GUID = "1E0D5072",
          NextDialogue = 12004502,
          SnapShot = "BROADCAST",
          Subtitle = "Target detected. Target detected.",
          VoiceName = "voice/$Locale$/story/1200/120045/1E0D5072"
        },
        [12004502] = {
          ContentFR = "Aaah... on s’est fait repérer !",
          DialogueId = 12004502,
          GUID = "1E0D509C",
          SpeakNpcId = 200002,
          Subtitle = "Whoa... I think we've been spotted!",
          VoiceName = "voice/$Locale$/story/1200/120045/1E0D509C"
        },
        [12004503] = {
          ContentFR = "Échec de la quête. Veuillez recommencer.",
          DialogueId = 12004503,
          GUID = "1E0D509D",
          SpeakNpcId = 200002,
          Subtitle = "Quest failed, please try again."
        },
        [12004504] = {
          Content = "被动失败",
          DialogueId = 12004504,
          GUID = "1E0D509E",
          SpeakNpcId = 200002,
          Subtitle = "Target Lost."
        },
        [12010000] = {
          ContentFR = "Affalez les voiles — on entre au port !",
          DialogueId = 12010000,
          Duration = 5,
          GUID = "1E10D6A0",
          Subtitle = "Sails down — coming into port—!",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D6A0"
        },
        [12010001] = {
          ContentFR = "Entre la calèche, le dirigeable et maintenant le bateau... j’ai les fesses en compote...",
          DialogueId = 12010001,
          GUID = "1E10D6CA",
          NextDialogue = 12010002,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 408011,
            [3] = 203001
          },
          SpeakNpcId = 200002,
          Subtitle = "Ugh... we've been on a cart, an airship, and now a boat — my poor buns are squished as flat as a pancake...",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D6CA"
        },
        [12010002] = {
          ContentFR = "Héhé... De Huaxu jusqu’à Hyperborea, la distance se compte en milliers de lieues. Réduire un tel voyage à une seule journée est déjà une prouesse — celle de la technologie Phoxichorique.",
          DialogueId = 12010002,
          GUID = "1E10D6F4",
          NextDialogue = 12010003,
          SpeakNpcId = 210004,
          Subtitle = "Hehe... The journey from Huaxu to Hyperborea spans hundreds — maybe even thousands — of miles. To think we've crossed that distance in just one day... that's the power of Phoxene-based technology.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D6F4"
        },
        [12010003] = {
          ContentFR = "Vu comme ça... C’est vrai que je n’ai jamais voyagé aussi loin !",
          DialogueId = 12010003,
          GUID = "1E10D71E",
          NextDialogue = 12010004,
          SpeakNpcId = 200002,
          Subtitle = "You're right... Heh, this is the farthest I've ever gone!",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D71E"
        },
        [12010004] = {
          ContentFR = "Ces montagnes toutes vertes... et ces arbres rouges et dorés... On a bien fait de venir ! À Givrelac, je n’aurais eu que les loups des neiges pour me tenir compagnie.",
          DialogueId = 12010004,
          GUID = "1E10D748",
          NextDialogue = 12010005,
          SpeakNpcId = 200002,
          Subtitle = "Look at those green mountains, totally worth it! If I were still stuck in Icelake, I'd just be staring at snow wolves all day — not cute at all.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D748"
        },
        [12010005] = {
          ContentFR = "Petit larbin, c’est donc ça, le « sud » dont tu parles tout le temps ? Ça ressemble à ton pays ?",
          DialogueId = 12010005,
          GUID = "1E10D772",
          NextDialogue = 12010006,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, this is the \"south\" you're always going on about, isn't it? Does it look anything like your hometown?",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D772"
        },
        [12010006] = {
          ContentFR = "Un peu... mais c’est très différent, aussi.",
          DialogueId = 12010006,
          GUID = "1E10D79C",
          NextDialogue = 12010007,
          SpeakNpcId = 100001,
          Subtitle = "A little... but there are lots of differences too.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D79C"
        },
        [12010007] = {
          ContentFR = "L’Île du Purgatoire est minuscule. Même son point culminant, un enfant peut l’escalader d’une traite... Et tout en haut, il n’y a que le bleu de l’océan à perte de vue.",
          DialogueId = 12010007,
          GUID = "1E10D7C6",
          NextDialogue = 12010008,
          SpeakNpcId = 100001,
          Subtitle = "Purgatorio Island is tiny. Even its tallest hill — if a kid really puts their mind to it, they could sprint all the way up in one go. And from up there, the deep blue sea stretches out forever...",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D7C6"
        },
        [12010008] = {
          ContentFR = "Patronne Zhiliu, comment est Huaxu, en tant que nation ?",
          DialogueId = 12010008,
          GUID = "1E10D7F0",
          NextDialogue = 12010009,
          SpeakNpcId = 100001,
          Subtitle = "Proprietress Zhiliu, what's Huaxu like?",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D7F0"
        },
        [12010009] = {
          ContentFR = "Voyons voir... Ce que vous avez aperçu n’en est qu’une infime parcelle.",
          DialogueId = 12010009,
          GUID = "1E10D81A",
          NextDialogue = 12010010,
          SpeakNpcId = 210004,
          Subtitle = "Let me think... what you've seen so far is only a small corner of Huaxu.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D81A"
        },
        [12010010] = {
          ContentFR = "Autrefois, nos ancêtres ont uni leurs forces pour mettre fin aux ravages des Souillés.\nIls se sont ensuite enracinés ici, se sont multipliés... et ont étendu leurs frontières.",
          DialogueId = 12010010,
          GUID = "1E10D844",
          NextDialogue = 12010011,
          SpeakNpcId = 210004,
          Subtitle = "In ancient times, our ancestors united their strength to drive out the monstrous Filthoids that once plagued these lands. They settled here, their numbers grew, and so too did their domain.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D844"
        },
        [12010011] = {
          ContentFR = "Aujourd’hui, cet estuaire est devenu l’ancienne capitale. Une simple fraction du territoire de Huaxu, certes... mais une fraction à l’influence considérable.",
          DialogueId = 12010011,
          GUID = "1E10D86E",
          NextDialogue = 12010012,
          SpeakNpcId = 210004,
          Subtitle = "Today, this estuary has become what we call the Old Capital. It may be but a fraction of Huaxu's vast expanse, but its influence is anything but small.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D86E"
        },
        [12010012] = {
          ContentFR = "Dans l’ensemble, Huaxu est une terre fertile, verdoyante toute l’année, où le commerce prospère sous l’égide des Tisse-Étoiles...",
          DialogueId = 12010012,
          GUID = "1E10D898",
          NextDialogue = 12010013,
          RelatedWikiId = {
            [1] = 405007
          },
          SpeakNpcId = 210004,
          Subtitle = "Huaxu is lush and scenic — evergreen throughout the year. With the Starweavers leading the way, trade and commerce here are positively thriving...",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D898"
        },
        [12010013] = {
          ContentFR = "Héhé... Pourquoi cet air si sérieux ? Mon discours était-il trop... officiel ?",
          DialogueId = 12010013,
          GUID = "1E10D8C2",
          NextOptions = {
            [1] = 120100131,
            [2] = 120100132
          },
          SpeakNpcId = 210004,
          Subtitle = "Hehe... you're looking rather serious — was that all a bit too formal for your liking?",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D8C2"
        },
        [12010014] = {
          ContentFR = "Dans ce cas, parlons de quelque chose de plus marquant. Huaxu est un pays où <H>nul ne lève l’arme, et où les conflits n’ont pas droit de cité</>.",
          DialogueId = 12010014,
          GUID = "1E10D8EC",
          NextDialogue = 12010015,
          SpeakNpcId = 210004,
          Subtitle = "Very well, then. Let me share something more to your taste: Huaxu is a realm of peace — where no blade is ever unsheathed in wrath, nor discord allowed to sully the land.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D8EC"
        },
        [12010015] = {
          ContentFR = "Lever quoi... et quel conflit ? Euh... je n’ai rien compris !",
          DialogueId = 12010015,
          GUID = "1E10D916",
          NextDialogue = 12010016,
          SpeakNpcId = 200002,
          Subtitle = "No blades something... nor what now? I've no clue what those fancy words are supposed to mean...",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D916"
        },
        [12010016] = {
          ContentFR = "Elle veut dire... qu’ici, il n’y a pas de guerre. Et que les gens ne se battent pas à tout bout de champ, comme à Givrelac.",
          DialogueId = 12010016,
          GUID = "1E10D940",
          NextDialogue = 12010017,
          SpeakNpcId = 100001,
          Subtitle = "I think she means... there's no war here. People don't go around picking fights like in Icelake.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D940"
        },
        [12010017] = {
          ContentFR = "Exactement. Même les larcins et les méfaits les plus insignifiants ont disparu depuis longtemps.",
          DialogueId = 12010017,
          GUID = "1E10D96A",
          NextDialogue = 12010018,
          SpeakNpcId = 210004,
          Subtitle = "Exactly. Even petty theft and underhanded dealings have long been stamped out here.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D96A"
        },
        [12010018] = {
          ContentFR = "Attends, attends... Tu veux dire qu’il n’y a aucun crime à Huaxu ? Ça ressemble plutôt à une histoire pour enfants !",
          DialogueId = 12010018,
          GUID = "1E10D994",
          NextDialogue = 12010019,
          SpeakNpcId = 200002,
          Subtitle = "Hold on — you're trying to tell us there's not a single crime in all of Huaxu? Now you're just making stuff up!",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D994"
        },
        [12010019] = {
          ContentFR = "Héhé... Vraiment ?",
          DialogueId = 12010019,
          GUID = "1E10D9BE",
          NextDialogue = 12010020,
          SpeakNpcId = 210004,
          Subtitle = "Hehe... Do you think so?",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D9BE"
        },
        [12010020] = {
          ContentFR = "Patronne Zhiliu — !",
          DialogueId = 12010020,
          GUID = "1E10D9E8",
          NextDialogue = 12010021,
          SpeakNpcName = "UI_Npc_Name_FarawayVoice",
          Subtitle = "Miss Zhiliu—!",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10D9E8"
        },
        [12010021] = {
          ContentFR = "On dirait que quelqu’un vous appelle depuis le quai.",
          DialogueId = 12010021,
          GUID = "1E10DA12",
          NextDialogue = 12010022,
          SpeakNpcId = 100001,
          Subtitle = "Sounds like someone's calling for you from the dock.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10DA12"
        },
        [12010022] = {
          ContentFR = "Oui. Allons voir.",
          DialogueId = 12010022,
          GUID = "1E10DA3C",
          SpeakNpcId = 210004,
          Subtitle = "Indeed. Let's head down and see what's the matter.",
          VoiceName = "voice/$Locale$/story/1201/120100/1E10DA3C"
        },
        [12010101] = {
          ContentFR = "Patronne Zhiliu. Pour la liste de déchargement, à qui devons-nous confier la vérification ?",
          DialogueId = 12010101,
          GUID = "1E10E732",
          NextDialogue = 12010102,
          SpeakNpcId = 210030,
          Subtitle = "Miss Zhiliu, about the cargo list — who should we have check and verify the goods?",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10E732"
        },
        [12010102] = {
          ContentFR = "Du Li n’est pas venu ? Je lui avais pourtant demandé d’arriver en avance.",
          DialogueId = 12010102,
          GUID = "1E10E75C",
          NextDialogue = 12010103,
          SpeakNpcId = 210004,
          Subtitle = "Du Li hasn't shown up? I distinctly told him to come early and handle the transfer.",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10E75C"
        },
        [12010103] = {
          ContentFR = "Cette cargaison contient plusieurs marchandises précieuses. Certaines exigent des conditions de stockage particulières. Sa présence m’aurait rassurée.",
          DialogueId = 12010103,
          GUID = "1E10E786",
          NextDialogue = 12010104,
          SpeakNpcId = 210004,
          Subtitle = "There are some particularly valuable items in this shipment. A few require special storage and handling procedures. I'd feel more at ease with him overseeing it.",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10E786"
        },
        [12010104] = {
          ContentFR = "Nous avons interrogé tout le quai... Personne n’a vu l’intendant Du aujourd’hui.",
          DialogueId = 12010104,
          GUID = "1E10E7B0",
          NextDialogue = 12010105,
          SpeakNpcId = 210030,
          Subtitle = "We've asked around, but no one at the docks has seen Mr Du today.",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10E7B0"
        },
        [12010105] = {
          ContentFR = "Je vois... Il a sans doute été retenu. Attendons ici pour le moment.",
          DialogueId = 12010105,
          GUID = "1E10E7DA",
          NextDialogue = 12010106,
          SpeakNpcId = 210004,
          Subtitle = "I see... He's probably been delayed. For now, let's wait here.",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10E7DA"
        },
        [12010106] = {
          ContentFR = "Poisson grillé tout juste sorti du feu — pas satisfait, pas payé !",
          DialogueId = 12010106,
          GUID = "1E10E804",
          NextDialogue = 12010107,
          SpeakNpcId = 210031,
          Subtitle = "Freshly grilled fish! Hot and tasty — or your money back!",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10E804"
        },
        [12010107] = {
          ContentFR = "Ouaaah — ça sent trop bon !",
          DialogueId = 12010107,
          GUID = "1E10E82E",
          NextDialogue = 12010108,
          SpeakNpcId = 200002,
          Subtitle = "Whoa—! It smells amazing!",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10E82E"
        },
        [12010108] = {
          ContentFR = "Tu as mangé il y a à peine un instant sur le bateau...",
          DialogueId = 12010108,
          GUID = "1E10E858",
          NextDialogue = 12010109,
          SpeakNpcId = 100001,
          Subtitle = "You just had snacks on the boat, and you're feeling peckish already?",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10E858"
        },
        [12010109] = {
          ContentFR = "Le poisson, oui ! Mais il y a autre chose dans l’air... Un parfum étrange...",
          DialogueId = 12010109,
          GUID = "1E10E882",
          NextDialogue = 12010110,
          SpeakNpcId = 200002,
          Subtitle = "Well, the fish does smell great! But there's another scent too... I can't quite put my finger on it.",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10E882"
        },
        [12010110] = {
          ContentFR = "Un peu floral... un peu comme le givre du matin... Bref, ça sent merveilleusement bon !",
          DialogueId = 12010110,
          GUID = "1E10E8AC",
          NextDialogue = 12010111,
          SpeakNpcId = 200002,
          Subtitle = "Like flowers... or maybe the crisp air of dawn... Whatever it is, it smells wonderful!",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10E8AC"
        },
        [12010111] = {
          ContentFR = "Une coïncidence opportune. Puisque notre contact se fait attendre, je vais vous accompagner. Après tout, vous venez à peine d’arriver à Huaxu, {nickname}.",
          DialogueId = 12010111,
          GUID = "1E10E8D6",
          NextDialogue = 12010112,
          SpeakNpcId = 210004,
          Subtitle = "As luck would have it, our contact here is running late. Since this is your first visit to Huaxu, , allow me to show you around a little.",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10E8D6"
        },
        [12010112] = {
          ContentFR = "Youpi ! Alors je veux voir ces échoppes là-bas ! Et ce tambourin ! Et... hé, c’est quoi, ça ?!",
          DialogueId = 12010112,
          GUID = "1E10E900",
          SpeakNpcId = 200002,
          Subtitle = "Yay! Then I wanna check out those food stalls! Ooh, and that rattle drum looks fun... Whoa! What's that over there!?",
          VoiceName = "voice/$Locale$/story/1201/120101/1E10E900"
        }
      }
    end
  },
