          VoiceName = "voice/$Locale$/story/1201/120107/1E114E10"
        },
        [12010801] = {
          Camera = "304.855316,544.535767,34.631836,0.000097,7.994593,-130.562805,50.0,100000.0,false,Manual,22",
          ContentFR = "Vous voilà. Alors... comment s’est déroulée votre promenade ?",
          DialogueId = 12010801,
