        },
        [12011801] = {
          ContentFR = "Qu... que faites-vous ici ?! C’est dangereux—",
          DialogueId = 12011801,
          Duration = 3,
          GUID = "1E11FE1A",
          Subtitle = "What are you doing here...? It's dangerous—",
          VoiceName = "voice/$Locale$/story/1201/120118/1E11FE1A"
        },
        [12011802] = {
          ContentFR = "Je viens t’aider !",
          DialogueId = 12011802,
          Duration = 2,
          GUID = "1E11FE44",
          Subtitle = "We're here to help you!",
          VoiceName = "voice/$Locale$/story/1201/120118/1E11FE44"
        },
        [12011901] = {
          ContentFR = "Vous êtes des étrangers. Cette bataille ne vous concerne pas. Laissez-moi faire.",
          DialogueId = 12011901,
          Duration = 3,
          GUID = "1E120E82",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 12011902,
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "This fight doesn't concern you outsiders. Just leave. I'll deal with them myself.",
          VoiceName = "voice/$Locale$/story/1201/120119/1E120E82"
        },
        [12011902] = {
          ContentFR = "Face à l’ennemi, on ne bavarde pas. C’est toi qui l’as dit.",
          DialogueId = 12011902,
          Duration = 2,
          GUID = "1E120EAC",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 12011903,
          SpeakNpcId = 100001,
          Subtitle = "No time for idle chatter with danger still looming — your words.",
          VoiceName = "voice/$Locale$/story/1201/120119/1E120EAC"
        },
        [12011903] = {
          ContentFR = "Exactement ! Et vu ton état, arrête de jouer les durs et accepte notre aide !",
          DialogueId = 12011903,
          Duration = 3,
          GUID = "1E120ED6",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 12011904,
          SpeakNpcId = 200002,
          Subtitle = "Exactly! And look at you — you're hurt so bad already. Stop playing the hero and let us help!",
          VoiceName = "voice/$Locale$/story/1201/120119/1E120ED6"
        },
        [12011904] = {
          ContentFR = "... Très bien.",
          DialogueId = 12011904,
          Duration = 2,
          GUID = "1E120F00",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "...Alright.",
          VoiceName = "voice/$Locale$/story/1201/120119/1E120F00"
        },
        [12012001] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ces créatures... ont enfin été éradiquées. Merci à vous deux pour votre soutien.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012001,
          GUID = "1E121EEA",
          NextDialogue = 12012002,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003
          },
          SpeakNpcId = 210007,
          SpeakNpcName = "UI_Npc_Name_Yingtianwei",
          Subtitle = "These vile beasts... finally cleansed. Thank you both for your aid.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E121EEA"
        },
        [12012002] = {
          ContentFR = "Pardonnez mon manque de courtoisie plus tôt. Nous n’avons pas encore échangé nos noms. Je me nomme Yuming. Et vous êtes... ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012002,
          GUID = "1E121F14",
          NextDialogue = 12012003,
          RelatedWikiId = {
            [1] = 203004
          },
          SpeakNpcId = 210007,
          Subtitle = "Forgive my earlier rudeness. We never properly exchanged names. I am Yuming. May I ask who you are?",
          VoiceName = "voice/$Locale$/story/1201/120120/1E121F14"
        },
        [12012003] = {
          ContentFR = "Je suis {nickname}, {性别:un Chasseur de Phoxène venu|une Chasseuse de Phoxène venue} d’ailleurs. Et voici—",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012003,
          GUID = "1E121F3E",
          NextOptions = {
            [1] = 120120031,
            [2] = 120120032
          },
          SpeakNpcId = 100001,
          Subtitle = "I'm a Phoxhunter from a foreign land, . And this is...",
          VoiceName = "voice/$Locale$/story/1201/120120/1E121F3E"
        },
        [12012005] = {
          ContentFR = "Héhé, exact ! Rédempteur Immaculé ☆ Roi Démon de la Lumière, c’est moi !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012005,
          GUID = "1E121F92",
          NextDialogue = 12012009,
          SpeakNpcId = 200002,
          Subtitle = "Uh-huh, uh-huh! And you can call me — the Pure-White Redeemer ☆ Demon King of Light!",
          VoiceName = "voice/$Locale$/story/1201/120120/1E121F92"
        },
        [12012007] = {
          ContentFR = "Les cultures étrangères... sont décidément d’une profondeur insondable...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012007,
          GUID = "1E121FE6",
          NextDialogue = 12012008,
          SpeakNpcId = 210007,
          Subtitle = "The culture of foreign lands is... truly mystifying.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E121FE6"
        },
        [12012008] = {
          ContentFR = "N-Non mais... quand ça sort de la bouche de quelqu’un d’autre, c’est super gênant ! Appelle-moi juste Snow !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012008,
          GUID = "1E122010",
          NextDialogue = 12012009,
          SpeakNpcId = 200002,
          Subtitle = "H—How come it sounds so much more embarrassing when someone else says it out loud...? Ugh, forget it — just call me Snow!",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122010"
        },
        [12012009] = {
          ContentFR = "Au fait... tu disais ne pas avoir le temps de bavarder. Et pourtant, te voilà bien loquace.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012009,
          GUID = "1E12203A",
          NextDialogue = 12012010,
          SpeakNpcId = 200002,
          Subtitle = "And what happened to \"No time for idle chatter,\" huh?",
          VoiceName = "voice/$Locale$/story/1201/120120/1E12203A"
        },
        [12012010] = {
          ContentFR = "J’étais trop absorbé par l’éradication de l’ennemi et ai manqué aux usages. J’en éprouve quelque honte... veuillez me pardonner.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012010,
          GUID = "1E122064",
          NextDialogue = 12012011,
          SpeakNpcId = 210007,
          Subtitle = "I was focused on eliminating the enemy and neglected proper manners. I ask your forgiveness.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122064"
        },
        [12012011] = {
          ContentFR = "Bon, bon. Le Roi Démon est magnanime. Je te pardonne !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012011,
          GUID = "1E12208E",
          NextDialogue = 12012012,
          SpeakNpcId = 200002,
          Subtitle = "Alright then. I have a big heart — so you're forgiven!",
          VoiceName = "voice/$Locale$/story/1201/120120/1E12208E"
        },
        [12012012] = {
          ContentFR = "Ça va aller ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012012,
          GUID = "1E1220B8",
          NextDialogue = 12012013,
          SpeakNpcId = 100001,
          Subtitle = "You okay?",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1220B8"
        },
        [12012013] = {
          ContentFR = "... Ce n’est rien. J’ai simplement dû faire face à trop d’ennemis à la fois. Quelques blessures superficielles.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012013,
          GUID = "1E1220E2",
          NextDialogue = 12012014,
          SpeakNpcId = 210007,
          Subtitle = "...It's okay. I fought off too many Bi'an earlier and ended up a bit off balance — just some surface wounds.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1220E2"
        },
        [12012014] = {
          ContentFR = "Superficielles ?! Ça ne ressemble pas du tout à juste quelques égratignures !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012014,
          GUID = "1E12210C",
          NextDialogue = 12012015,
          SpeakNpcId = 200002,
          Subtitle = "That doesn't look like \"just some surface wounds\" to me!",
          VoiceName = "voice/$Locale$/story/1201/120120/1E12210C"
        },
        [12012015] = {
          ContentFR = "Tiens. J’ai pris des bandages et des remèdes à Givrelac, au cas où.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012015,
          GUID = "1E122136",
          NextDialogue = 12012016,
          SpeakNpcId = 100001,
          Subtitle = "Here — take this. I brought some bandages and healing potions from Icelake, just in case.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122136"
        },
        [12012016] = {
          ContentFR = "Merci... Je suis désolé de vous avoir inquiétés. Un peu de repos suffira. Ces blessures guériront.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012016,
          GUID = "1E122160",
          NextDialogue = 12012017,
          SpeakNpcId = 210007,
          Subtitle = "Thank you for your kindness. I didn't mean to worry you... Truly, all I need is to sit and rest awhile. These injuries will mend soon enough.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122160"
        },
        [12012017] = {
          ContentFR = "Tu es sûr ? On dirait que ça a touché aux muscles, voire aux os. Peut-être qu’un médecin—",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012017,
          GUID = "1E12218A",
          NextDialogue = 12012018,
          SpeakNpcId = 100001,
          Subtitle = "You sure? That looks pretty bad... Maybe we should have a doctor take a look?",
          VoiceName = "voice/$Locale$/story/1201/120120/1E12218A"
        },
        [12012018] = {
          ContentFR = "Les Magistrats de Yingtian ont conclu un pacte avec les Neuf Chapitres de Dafeng. Notre force ne relève pas uniquement du corps.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012018,
          GUID = "1E1221B4",
          NextDialogue = 12012019,
          SpeakNpcId = 210007,
          Subtitle = "As a Magistrate of Yingtian, my strength does not come solely from flesh and bone — it draws upon the Nine Chapters of Dafeng.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1221B4"
        },
        [12012019] = {
          ContentFR = "Tant que la colonne n’est pas brisée, même les blessures les plus graves peuvent lentement se résorber, en puisant dans l’énergie des Neuf Chapitres... Il faut simplement endurer la douleur.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012019,
          GUID = "1E1221DE",
          NextDialogue = 12012020,
          RelatedWikiId = {
            [1] = 405010
          },
          SpeakNpcId = 210007,
          Subtitle = "So long as my spine remains unbroken, even the gravest wounds can mend with the Nine Chapters' energy. It's slow and painful, but certain.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1221DE"
        },
        [12012020] = {
          ContentFR = "Ça a l’air incroyable... C’est comme le « corps indestructible » des romans ! Ça me donne presque envie !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012020,
          GUID = "1E122208",
          NextDialogue = 12012021,
          SpeakNpcId = 200002,
          Subtitle = "Whoa, that's amazing... like something out of a story — the \"unbreakable body\"! Now I'm a little jealous!",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122208"
        },
        [12012021] = {
          ContentFR = "Ce n’est que le bon côté.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012021,
          GUID = "1E122232",
          NextDialogue = 12012022,
          SpeakNpcId = 210007,
          Subtitle = "That's merely the bright side.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122232"
        },
        [12012022] = {
          ContentFR = "Il y a donc un mauvais côté ?",
          DialogueId = 12012022,
          GUID = "1E12225C",
          NextDialogue = 12012023,
          SpeakNpcId = 200002,
          Subtitle = "Oh? So there's a downside?",
          VoiceName = "voice/$Locale$/story/1201/120120/1E12225C"
        },
        [12012023] = {
          ContentFR = "...",
          DialogueId = 12012023,
          GUID = "1E122286",
          NextDialogue = 12012024,
          SpeakNpcId = 210007,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122286"
        },
        [12012024] = {
          ContentFR = "Ce n’est rien. J’ai parlé à tort.",
          DialogueId = 12012024,
          GUID = "1E1222B0",
          NextDialogue = 12012025,
          SpeakNpcId = 210007,
          Subtitle = "It's nothing. I spoke out of turn.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1222B0"
        },
        [12012025] = {
          ContentFR = "J’ai autrefois été un pécheur. Malgré mes armes et mon armure, je n’ai protégé personne. Servir aujourd’hui les Neuf Chapitres... est pour moi une façon d’expier.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012025,
          GUID = "1E1222DA",
          NextDialogue = 12012026,
          SpeakNpcId = 210007,
          Subtitle = "I was once a condemned soul. Looking back... though clad in armour and armed with blade, I failed to save a single life. To serve the Nine Chapters now... it is my chance to atone.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1222DA"
        },
        [12012026] = {
          ContentFR = "Merci encore de votre sollicitude. Je resterai ici pour récupérer. Je ne pourrai vous raccompagner davantage.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012026,
          GUID = "1E122304",
          NextDialogue = 12012027,
          SpeakNpcId = 210007,
          Subtitle = "Thank you both once again. I must remain here to recover — forgive me that I cannot see you off properly.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122304"
        },
        [12012027] = {
          ContentFR = "Votre valeur au combat est indéniable. Mais le Fléau de Zhuyin est dangereux. Soyez prudents.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012027,
          GUID = "1E12232E",
          NextDialogue = 12012028,
          SpeakNpcId = 210007,
          Subtitle = "You both fight well. But the threat of Zhuyin is not to be underestimated. Take care.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E12232E"
        },
        [12012028] = {
          ContentFR = "Ne t’inquiète pas. Nous le serons.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012028,
          GUID = "1E122358",
          NextDialogue = 12012029,
          SpeakNpcId = 100001,
          Subtitle = "We will. Don't worry.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122358"
        },
        [12012029] = {
          ContentFR = "... Cela me rassure.",
          DialogueId = 12012029,
          GUID = "1E122382",
          NextDialogue = 12012030,
          SpeakNpcId = 210007,
          Subtitle = "Such a relief... to hear that...",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122382"
        },
        [12012030] = {
          ContentFR = "...",
          DialogueId = 12012030,
          GUID = "1E1223AC",
          NextDialogue = 12012031,
          SpeakNpcId = 210007,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1223AC"
        },
        [12012031] = {
          ContentFR = "... Il s’est endormi ?",
          DialogueId = 12012031,
          GUID = "1E1223D6",
          NextDialogue = 12012032,
          SpeakNpcId = 200002,
          Subtitle = "...Did he... fall asleep?",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1223D6"
        },
        [12012032] = {
          ContentFR = "Sans doute d’épuisement. J’ai vérifié les alentours : il n’y a plus de Bi’an obscurs ici.\nMettons-le à l’abri.",
          DialogueId = 12012032,
          GUID = "1E122400",
          SpeakNpcId = 100001,
          Subtitle = "Probably just exhausted. I did a quick sweep — there aren't any more Sable Bi'an around, so it should be safe for now. Let's find something to cover him up.",
          VoiceName = "voice/$Locale$/story/1201/120120/1E122400"
        },
        [12012033] = {
          Camera = "-211.635849,61.618118,96.055908,0.000228,-13.199524,1.187723,50.000008,78.880096,false,Manual,6.0",
          ContentFR = "Et voilà ! Mission accomplie !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012033,
          FacialId = {
            [1] = "200002:Happy02"
          },
          FinalCamera = "-209.995361,89.062073,96.055908,0.000229,-12.999502,-3.412318,50.000008,384.850891,false,Manual,6.0",
          GUID = "1E12242A",
          LookAt = {
            [1] = "100001:n(200002)",
            [2] = "200002:p(baitx_20_lookat)"
          },
          NextDialogue = 12012034,
          Scripts = "SetLocation{ActorId{210007},TargetPoint{\"baitx_20_lookat\"},Visibility{\"Hide\"}}",
          SpeakNpcId = 200002,
          Subtitle = "There we go — mission accomplished!",
          TalkActionId = {
            [1] = "200002:Excited02_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1201/120120/1E12242A"
        },
        [12012034] = {
          Camera = "-97.596481,177.937027,64.957031,0.0003,-8.801279,-14.827387,35.000011,109.451584,false,Manual,12.0",
          ContentFR = "Avec ces feuilles, personne ne le remarquera. Il pourra se reposer tranquillement.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012034,
          FacialId = {
            [1] = "200002:Happy01"
          },
          GUID = "1E122454",
          LookAt = {
            [1] = "100001:p(baitx_20_lookat)"
          },
          NextDialogue = 12012035,
          SpeakNpcId = 100001,
          Subtitle = "With all these leaves for camouflage, no one will spot him easily. He can rest here in peace.",
          TalkActionId = {
            [1] = "200002:Excited02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120120/1E122454"
        },
        [12012035] = {
          Camera = "-151.535309,-23.62561,138.090088,0.000041,-27.197224,38.974789,25.000006,288.727173,false,Manual,6.0",
          ContentFR = "Une œuvre du Roi Démon ! Héhé... Ajoutons encore deux-trois détails !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012035,
          FacialId = {
            [1] = "200002:Happy02"
          },
          GUID = "1E12247E",
          LookAt = {
            [1] = "100001:p(baitx_20_lookat)",
            [2] = "200002:p(baitx_20_lookat)"
          },
          NextDialogue = 12012036,
          Scripts = "PlayAnimation{_delay{1},ActorId{200002},AnimationId{\"Confident_Start\"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "What a masterpiece! I'm so talented! Lemme add a few final touches — teehee!",
          VoiceName = "voice/$Locale$/story/1201/120120/1E12247E"
        },
        [12012036] = {
          ContentFR = "Ce graffiti Luno... n’importe qui saura que c’est toi. Si on nous cherche, je ne te couvrirai pas.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012036,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "1E1224A8",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "200002:n(100001)"
          },
          NextDialogue = 12012037,
          Scripts = [[
PARA{
CameraMoveTo{_delay{1},TargetPosition{"103.637772,32.494957,29.010498,0.000046,6.000567,116.789314,35.000008,181.183746,false,Manual,6.0"},duration{0}},
PlayAnimation{_delay{1},ActorId{100001},AnimationId{"DisagreeHead"},Duration{2}},
SEQ{
PlayAnimation{_delay{3},ActorId{100001},AnimationId{"Talk01_Start"},Duration{1}},
LookAt{LookAtDescription{"100001:n(200002)"}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Those Luno doodles are a dead giveaway. If someone comes asking, don't expect me to cover for you.",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120120/1E1224A8"
        },
        [12012037] = {
          ContentFR = "Il se fait tard. Allons au marché noir.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012037,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1E1224D2",
          SpeakNpcId = 100001,
          Subtitle = "It's getting late. Let's head to the black market.",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120120/1E1224D2"
        },
        [12012040] = {
          ContentFR = "Petit larbin ! Cet endroit est parfait. Cachons-le ici !",
          DialogueId = 12012040,
          Duration = 3,
          GUID = "1E1224D3",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, this places looks perfect, let's hide him here!",
          VoiceName = "voice/$Locale$/story/1201/120120/1E1224D3"
        },
        [12012101] = {
          Camera = "1756.186523,733.326172,500.082031,0.000011,-8.799899,-159.191101,28.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors, alors... {性别:deux gamins qui se sont perdus|deux gamines qui se sont perdues} ? Ce n’est pas un endroit pour vous. Rentrez donc retrouver votre maman.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012101,
          FacialId = {
            [1] = "100001:Curious",
            [2] = "200002:Doubt01"
          },
