        [12012104] = {
          Camera = "14.870117,-147.639648,182.657715,0.000098,-17.999447,89.194046,40.000031,430.950531,false,Manual,2.8",
          ContentFR = "On n’a pas dit que sortir de la grotte avec le pendentif suffisait pour être des vôtres ? Là-dedans, c’était blindé de Bi’an obscurs — on a vraiment galéré pour arriver jusqu’ici. Un peu d’accueil ne serait pas du luxe !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12012104,
          FacialId = {
            [1] = "200002:Shock01",
            [2] = "100001:Doubt01"
          },
          FinalCamera = "20.652344,-147.723633,182.657715,0.000098,-17.999447,89.194046,40.000031,430.950531,false,Manual,2.8",
          GUID = "1E122FD0",
          LookAt = {
            [1] = "100001:n(210008)",
            [2] = "200002:n(210008)",
            [3] = "210008:n(200002)"
          },
          NextDialogue = 12012105,
          Scripts = [[
PARA{
PlayAnimation{_delay{4},ActorId{100001},AnimationId{"TilteHead_End"},Duration{1}},
