PARA{
PlayAnimation{ActorId{200002},AnimationId{"Talk03_Start"},Duration{1}},
LookAt{LookAtDescription{"200002:p(BP_FixSimple_37_bai01)"}}
}
}
}]],
          SpeakNpcId = 200002,
          Subtitle = "That's still not okay! Ugh, you're so stubborn — it's like talking to a brick wall!",
          TalkActionId = {
            [1] = "200002:Angry01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136806"
        },
        [12014008] = {
          Camera = "-220.412903,-680.490723,295.292969,0.000105,-16.397665,79.819618,30.000002,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu avais dit qu’en acceptant ma flûte, tu me devais une faveur... n’est-ce pas ?",
          DialogueId = 12014008,
          FinalCamera = "-256.274719,-674.050476,295.292969,0.000105,-16.397665,79.819618,30.000002,100000.0,false,DoNotOverride,2.8",
          GUID = "1E136830",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 12014009,
          Scripts = [[
SEQ{
MoveTo{_delay{1},ActorId{100001},TargetPoint{"BP_FixSimple_37_nvzhu02"},MoveSpeed{75},Visibility{"Show"}},
PlayAnimation{ActorId{100001},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "You said before that by taking my bamboo flute, you owed me a favour — didn't you?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136830"
        },
        [12014009] = {
          ContentFR = "C’est exact.",
          DialogueId = 12014009,
          Duration = 1,
          GUID = "1E13685A",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "210013:n(100001)"
          },
          NextDialogue = 12014010,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.1},ActorId{100001},AnimationId{"Talk03_End"},Duration{1}},
PlayAnimation{_delay{0.5},ActorId{210013},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 210013,
          Subtitle = "I did.",
          VoiceName = "voice/$Locale$/story/1201/120140/1E13685A"
        },
        [12014010] = {
          Camera = "-8.599365,-111.106323,114.814453,0.000091,8.002468,157.225708,40.000011,192.971207,false,Manual,8.0",
          ContentFR = "Alors je te demande ceci : prends soin de toi.",
          DialogueId = 12014010,
          Duration = 3,
          FacialId = {
            [1] = "210013:None"
          },
          FinalCamera = "-12.785553,-121.060074,114.814453,0.000092,8.002468,157.225403,40.0,190.094833,false,Manual,8.0",
          GUID = "1E136884",
          NextDialogue = 12014011,
          Scripts = "PlayFacial{_delay{3.1},ActorId{210013},FacialId{\"Shock01\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Then here's my request: take good care of yourself.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136884"
        },
        [12014011] = {
          Camera = "212.972397,181.786407,310.055664,0.000055,-23.796507,-148.173798,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Une requête aussi insignifiante ne mérite pas d’être appelée une faveur.",
          DialogueId = 12014011,
          FacialId = {
            [1] = "210013:None"
          },
          FinalCamera = "285.723572,226.953049,347.814453,0.000055,-23.796507,-148.173798,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E1368AE",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12014012,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.1},ActorId{210013},AnimationId{"Talk02R_Start"},Duration{1}},
PlayAnimation{_delay{6.1},ActorId{210013},AnimationId{"Talk02R_End"},Duration{1}}
}]],
          SpeakNpcId = 210013,
          Subtitle = "...Such a trifling matter hardly counts as a request. You shouldn't squander a favour on that.",
          ToFinalCameraBlendTime = 20,
          TurnTo = {
            [1] = "210013:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E1368AE"
        },
        [12014012] = {
          ContentFR = "J’ai quelqu’un de très cher... Elle te ressemble beaucoup. Toujours à négliger sa propre santé, quoi qu’il lui arrive. Je n’aime pas la voir ainsi.",
          DialogueId = 12014012,
          FacialId = {
            [1] = "100001:Sad03"
          },
          GUID = "1E1368D8",
          LookAt = {
            [1] = "100001:n(100001)"
          },
          NextDialogue = 12014013,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{4.01},TargetPosition{"-194.399475,-247.132721,132.933594,0.000073,-0.39764,77.026947,40.0,173.23349,false,Manual,6.0"},duration{0}},
CameraMoveTo{TargetPosition{"-198.07663,-263.094513,133.046875,0.000073,-0.39764,77.026947,40.0,189.931564,false,Manual,6.0"},duration{8}}
},
PlayAnimation{_delay{5.01},ActorId{100001},AnimationId{"Please01_Start"},Duration{1}},
PlayAnimation{_delay{7.01},ActorId{210013},AnimationId{"Baiheng_Story_Special03_Start"},Duration{1}},
LookAt{_delay{14.01},LookAtDescription{"100001:p(BP_FixSimple_37_nvzhu04)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "There's someone very dear to me. She's just like you — never takes care of herself. No matter how much she's hurt, or how others treat her, she always pretends it doesn't matter. I hate that about her.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E1368D8"
        },
        [12014013] = {
          Camera = "-3558.072266,-1192.942871,267.723633,0.000177,19.579582,18.021456,25.0,100000.0,false,Manual,2.8",
          ContentFR = "Imaginer qu’elle puisse être blessée quelque part... Ça m’empêche de dormir.",
          DialogueId = 12014013,
          FinalCamera = "-3558.072266,-1192.942871,267.723633,0.00018,25.379478,14.420898,25.0,100000.0,false,Manual,2.8",
          GUID = "1E136902",
          NextDialogue = 12014014,
          SpeakNpcId = 100001,
          Subtitle = "Just thinking she might be out there, somewhere... suffering, in pain... it keeps me up at night.",
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special03_End"
          },
          ToFinalCameraBlendTime = 16,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136902"
        },
        [12014014] = {
          Camera = "-195.013611,-319.483887,133.03418,0.000073,-0.997713,80.626976,40.0,272.017151,false,Manual,10.0",
          ContentFR = "Il existe forcément quelqu’un qui s’inquiète pour toi de la même façon. Alors... ne lui inflige pas cette peine.",
          DialogueId = 12014014,
          Duration = 1,
          FacialId = {
            [1] = "210013:Sad03"
          },
          FinalCamera = "-208.24704,-317.102356,133.03418,0.000073,-0.397701,79.626984,40.0,257.81076,false,Manual,10.0",
          GUID = "1E13692C",
          LookAt = {
            [1] = "100001:n(100001)",
            [2] = "210013:n(210013)"
          },
          NextDialogue = 12014015,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{5.3},TargetPosition{"-283.799866,-6.647125,141.072266,0.000081,-3.397951,-23.168659,40.0,154.231232,false,Manual,6.0"},duration{0}},
CameraMoveTo{TargetPosition{"-282.389771,-3.36795,141.072266,0.000081,-3.397951,-23.168659,40.0,154.818222,false,Manual,6.0"},duration{8}}
},
TurnTo{_delay{2.01},TurnToDescription{"100001:n(210013)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "There must be someone who worries about you the way I worry about her. Don't make that person suffer. Please, Fushu — take care of yourself.",
          TalkActionId = {
            [1] = "100001:Please01_End",
            [2] = "210013:Think_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120140/1E13692C"
        },
        [12014015] = {
          Camera = "-160.908493,-160.138596,126.569336,0.000092,7.202004,94.83432,45.000023,134.189529,false,Manual,10.0",
          ContentFR = "... Pardonne-moi. Je n’ai pas voulu raviver une douleur.",
          DialogueId = 12014015,
          FinalCamera = "-169.812134,-160.684509,126.569336,0.000095,7.202011,90.234421,45.000023,134.189529,false,Manual,10.0",
          GUID = "1E136956",
          NextDialogue = 12014016,
          SpeakNpcId = 210013,
          Subtitle = "...Forgive me. I didn't mean to stir old grief.",
          TalkActionId = {
            [1] = "210013:Think_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136956"
        },
        [12014016] = {
          ContentFR = "Je comprends. Je réfléchirai sérieusement à ce que tu as dit.",
          DialogueId = 12014016,
          FacialId = {
            [1] = "210013:SpecialSmile"
          },
          GUID = "1E136980",
          NextDialogue = 12014017,
          SpeakNpcId = 210013,
          Subtitle = "I understand. I'll take your words to heart.",
          TalkActionId = {
            [1] = "210013:AgreeHead",
            [2] = "200002:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136980"
        },
        [12014017] = {
          Camera = "-333.198242,-92.549561,186.976562,0.000109,-17.397945,13.034511,40.000011,340.723328,false,Manual,8.0",
          ContentFR = "Voilà qui est mieux ! Petit larbin, je ne savais pas que tu parlais si bien ! Tu es vraiment digne d’être le bras droit du Roi Démon !",
          DialogueId = 12014017,
          FacialId = {
            [1] = "200002:Confident02"
          },
          FinalCamera = "-335.535034,-82.232544,186.976562,0.000107,-17.197903,11.034736,40.000011,340.337952,false,Manual,8.0",
          GUID = "1E1369AA",
          LookAt = {
            [1] = "210013:n(200002)",
            [2] = "100001:n(200002)"
          },
          NextDialogue = 12014018,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"200002:n(210013)"}},
LookAt{_delay{1.1},LookAtDescription{"200002:n(100001)"}},
PlayAnimation{_delay{4.1},ActorId{200002},AnimationId{"Excited03_End"},Duration{1}},
PlayAnimation{_delay{7},ActorId{200002},AnimationId{"Excited02_Start"},Duration{1}},
PlayFacial{_delay{7.5},ActorId{200002},FacialId{"Happy02"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Now that's more like it! Didn't know you had the gift of gab, Little Minion — no wonder you're my number-one sidekick!",
          TalkActionId = {
            [1] = "200002:Excited03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120140/1E1369AA"
        },
        [12014018] = {
          Camera = "-530.71698,-475.512299,272.475586,0.000107,-15.798446,48.637161,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mm...",
          DialogueId = 12014018,
          FacialId = {
            [1] = "210013:Sad03",
            [2] = "210056:Cin_Pain01"
          },
          FinalCamera = "-530.71698,-475.512299,272.475586,0.000108,-19.598326,51.03717,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E1369D4",
          LookAt = {
            [1] = "200002:p(BP_FixSimple_37_fushu02)",
