          },
          NextDialogue = 12014019,
          Scripts = "LookAt{_delay{1.1},LookAtDescription{\"100001:p(BP_FixSimple_37_fushu02)\"}}",
          SpeakNpcId = 210056,
          Subtitle = "...",
          TalkActionId = {
            [1] = "200002:Excited02_End"
