          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "210013:n(210056)"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E1369D4"
        },
        [12014019] = {
          ContentFR = "Elle se réveille ?!",
          DialogueId = 12014019,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "1E1369FE",
          NextDialogue = 12014020,
          SpeakNpcId = 200002,
          Subtitle = "Is she waking up?",
          TalkActionId = {
            [1] = "200002:Shock03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E1369FE"
        },
        [12014020] = {
          Camera = "-304.054077,-171.641968,145.578125,5.001599,-42.596004,111.247818,40.0,126.781067,false,Manual,6.839206",
          ContentFR = "Maman... tu es revenue... ? J’ai froid...",
          DialogueId = 12014020,
          FinalCamera = "-308.513123,-160.168503,134.261719,5.001599,-42.596004,111.247818,40.0,111.219002,false,Manual,6.839206",
          GUID = "1E136A28",
          NextDialogue = 12014021,
          SpeakNpcId = 210056,
          Subtitle = "Mama... is that you? I'm so cold...",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136A28"
        },
        [12014021] = {
          Camera = "-66.014252,-35.105202,167.732422,5.00001,-18.596672,-167.155045,30.0,268.570251,false,Manual,6.839206",
          ContentFR = "... Ce n’est qu’un rêve.",
          DialogueId = 12014021,
          FinalCamera = "-63.524422,-45.636681,166.837891,5.000161,-18.996737,-171.154877,30.0,268.570251,false,Manual,6.839206",
          GUID = "1E136A52",
          NextDialogue = 12014022,
          SpeakNpcId = 210013,
          Subtitle = "...Just a dream, it seems.",
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special03_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136A52"
        },
        [12014022] = {
          ContentFR = "Comment va-t-elle ?",
          DialogueId = 12014022,
          GUID = "1E136A7C",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12014023,
          SpeakNpcId = 100001,
          Subtitle = "How is she doing?",
          VoiceName = "voice/$Locale$/story/1201/120140/1E136A7C"
        },
        [12014023] = {
          Camera = "-72.462227,-96.764427,124.28125,0.000125,9.403216,154.049149,35.000008,137.232391,false,Manual,6.0",
          ContentFR = "Son état est stable. Mais l’influence du Bi’an continue de ronger ses méridiens. Elle ne se réveillera pas de sitôt.",
          DialogueId = 12014023,
          FacialId = {
            [1] = "210013:Sad03"
          },
          FinalCamera = "-74.948547,-101.871399,124.28125,0.000135,9.403216,152.449646,35.000011,127.589622,false,Manual,6.0",
          GUID = "1E136AA6",
          LookAt = {
            [1] = "210013:n(100001)"
          },
          NextDialogue = 12014024,
          SpeakNpcId = 210013,
          Subtitle = "She's stable for now. But the Bi'an's power still gnaws at her meridians. I fear it will be some time before she wakes.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136AA6"
        },
        [12014024] = {
          ContentFR = "Dans les notes de ma sœur, j’ai trouvé mention d’une plante appelée Herbe de l’Oubli. Elle pousse à la frontière entre ce monde et l’autre, et sa nature douce contrebalance la brutalité du Bi’an.",
          DialogueId = 12014024,
          GUID = "1E136AD0",
          NextDialogue = 12014025,
          RelatedWikiId = {
            [1] = 301009
          },
          Scripts = [[
SEQ{
CameraMoveTo{_delay{3.5},TargetPosition{"-1772.944702,-1120.462158,-1462.329102,0.000139,3.182055,123.224609,25.0,3248.383545,false,Manual,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"-1772.944702,-1120.462158,-1462.329102,0.000142,-9.617889,115.826202,25.0,570.544434,false,Manual,2.8"},duration{20}}
}]],
          SpeakNpcId = 210013,
          Subtitle = "In my sister's pharmic notes, there was mention of a herb called Wangyou. It grows at the liminal crossing of this world and the next — its gentle essence said to be the perfect foil for the Bi'an's brutal energy.",
          VoiceName = "voice/$Locale$/story/1201/120140/1E136AD0"
        },
        [12014025] = {
          ContentFR = "Si nous l’utilisons comme remède, son état pourrait s’améliorer.",
          DialogueId = 12014025,
          GUID = "1E136AFA",
          LookAt = {
            [1] = "210013:n(210056)"
          },
          NextDialogue = 12014026,
          SpeakNpcId = 210013,
          Subtitle = "If we use this herb in her treatment, it may soothe the violent currents within her and steady her condition.",
          TalkActionId = {
            [1] = "200002:Shock03_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136AFA"
        },
        [12014026] = {
          Camera = "-511.522827,-152.21167,61.43457,0.000145,8.602684,16.252649,35.000008,335.979614,false,Manual,8.60223",
          ContentFR = "Ma sœur suivait la voie des remèdes et des plantes, tandis que j’ai été formée à l’Art de l’Éphémère. Je connais mal ses méthodes... mais c’est notre seule option.",
          DialogueId = 12014026,
          FinalCamera = "-513.789429,-144.432739,61.43457,0.000145,8.602684,16.252649,35.000008,335.979614,false,Manual,8.60223",
          GUID = "1E136B24",
          LookAt = {
            [1] = "200002:n(210056)"
          },
          NextDialogue = 12014027,
          Scripts = "LookAt{_delay{11.8},LookAtDescription{\"210013:n(100001)\"}}",
          SpeakNpcId = 210013,
          Subtitle = "While my sister devoted her life to the study of herbs and medicines, I was raised in the Art of Ephemerality. Our ways share a purpose, but the paths diverge. I know little of her methods... but for now, this is the only path left to try.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136B24"
        },
        [12014027] = {
          Camera = "-226.133133,-85.315811,163.748047,0.000056,-21.196583,11.054746,40.0,85.401657,false,Manual,10.0",
          ContentFR = "Alors qu’est-ce qu’on attend ? En route !",
          DialogueId = 12014027,
          FinalCamera = "-226.133133,-85.315811,163.748047,0.000056,-21.196583,11.054746,40.0,230.872345,false,Manual,10.0",
          GUID = "1E136B4E",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 12014028,
          Scripts = "LookAt{_delay{1.8},LookAtDescription{\"100001:n(200002)\"}}",
          SpeakNpcId = 200002,
          Subtitle = "Then what are we waiting for? Let's go find it!",
          TalkActionId = {
            [1] = "200002:Confident_Start",
            [2] = "100001:Think_Start",
            [3] = "210013:Baiheng_Story_Special03_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136B4E"
        },
        [12014028] = {
          Camera = "166.755264,-67.873413,51.71582,0.000071,12.00366,172.654205,40.0,353.210052,false,Manual,6.0",
          ContentFR = "Votre arrivée tombe à point nommé. J’allais justement partir récolter cette plante.",
          DialogueId = 12014028,
          FacialId = {
            [1] = "200002:Nervous",
            [2] = "210013:Smile01"
          },
          FinalCamera = "165.051727,-80.381683,51.71582,0.000071,11.803659,170.854324,40.0,352.896423,false,Manual,6.0",
          GUID = "1E136B78",
          LookAt = {
            [1] = "210013:n(200002)",
            [2] = "100001:n(100001)"
          },
          NextDialogue = 12014029,
          Scripts = "PlayAnimation{_delay{3.01},ActorId{210013},AnimationId{\"Baiheng_Story_Special02_Start\"},Duration{1}}",
          SpeakNpcId = 210013,
          Subtitle = "You arrived at just the right moment. I was about to set out to find it myself. Had you come any later... you might have missed me altogether.",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "210013:n(200002)"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136B78"
        },
        [12014029] = {
          Camera = "-121.7556,4.822418,91.928711,0.000113,-4.796657,-10.953535,35.0,104.130783,false,Manual,8.0",
          ContentFR = "Euh... au fait... Ce lieu entre deux mondes, là... il est où, déjà ?",
          DialogueId = 12014029,
          GUID = "1E136BA2",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12014030,
          SpeakNpcId = 200002,
          Subtitle = "So — where's that place again? The one that's supposed to be between two worlds or something?",
          TalkActionId = {
            [1] = "200002:Shy03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136BA2"
        },
        [12014030] = {
          Camera = "719.884644,1403.09314,144.785156,0.000114,-2.598074,-112.95311,35.000011,1652.77417,false,Manual,2.8",
          ContentFR = "Il se nomme la Source de Yu. Même parmi les natifs de Huaxu, rares sont ceux qui y ont jamais mis les pieds.",
          DialogueId = 12014030,
          FinalCamera = "784.508057,1375.722168,144.785156,0.000115,-2.598074,-112.953705,35.000011,755.125061,false,Manual,2.8",
          GUID = "1E136BCC",
          NextDialogue = 12014031,
          RelatedWikiId = {
            [1] = 408013
          },
          Scripts = [[
PARA{
LookAt{LookAtDescription{"210013:n(200002)"}},
LookAt{_delay{4.1},LookAtDescription{"210013:n(100001)"}},
}]],
          SpeakNpcId = 210013,
          Subtitle = "It's called the Spring of Yu. Even those born and raised in Huaxu may never see it for themselves — let alone newcomers like you.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136BCC"
        },
        [12014031] = {
          Camera = "59.27887,-13.943413,132.957031,0.00012,0.601726,-170.552292,35.000011,234.540634,false,Manual,6.397604",
          ContentFR = "Ce lieu est nourri par les eaux et les terres singulières de Huaxu. Portés par les encens omniprésents, certains attachements laissés par les mourants se transforment alors en des entités particulières appelées Wishen.",
          DialogueId = 12014031,
          FinalCamera = "60.464428,-21.080315,132.957031,0.00012,0.601726,-170.552292,35.000011,234.540634,false,Manual,6.397604",
          GUID = "1E136BF6",
          NextDialogue = 12014032,
          RelatedWikiId = {
            [1] = 303012
          },
          SpeakNpcId = 210013,
          Subtitle = "It is nurtured by Huaxu's unique soil and water. When mortals perish with lingering attachments in their hearts, the ever-present perfume acts as a conduit. Those yearnings give birth to spirits known as Wishen.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136BF6"
        },
        [12014032] = {
          Camera = "-147.81781,5.32869,142.967773,0.000243,-4.796145,-93.967758,35.000011,86.214539,false,Manual,7.41853",
          ContentFR = "La Source de Yu est précisément le sanctuaire où ces Wishen trouvent demeure. Seuls les enfants au cœur limpide — ou les humains qu’ils consentent à inviter — peuvent franchir les frontières de son domaine.",
          DialogueId = 12014032,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "-147.885712,4.413391,142.889648,0.000242,-4.796145,-93.967621,35.000008,80.332993,false,Manual,7.41853",
          GUID = "1E136C20",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12014033,
          SpeakNpcId = 210013,
          Subtitle = "The Spring of Yu is their resting ground. Only children with a pure heart — or those they choose to invite — may step into its realm.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120140/1E136C20"
        },
        [12014033] = {
          Camera = "-294.044525,50.440552,165.479492,0.000202,-16.597221,-20.770725,40.0,289.488281,false,Manual,6.491352",
          ContentFR = "C’est incroyable... Alors le petit larbin et moi, on peut y aller ?",
          DialogueId = 12014033,
          FacialId = {
            [1] = "200002:Happy02"
          },
          FinalCamera = "-294.044525,50.440552,165.479492,0.000197,-17.597284,-17.170553,40.0,289.488281,false,Manual,6.491352",
          GUID = "1E136C4A",
          LookAt = {
            [1] = "210013:n(200002)",
            [2] = "200002:n(210013)"
          },
          NextDialogue = 12014034,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.1},ActorId{200002},AnimationId{"SpecialHappy_Start"},Duration{1}},
PlayFacial{_delay{2.5},ActorId{100001},FacialId{"Happy01"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "Wow... that sounds so mysterious! So... can my Little Minion and I get in there?",
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special03_End"
          },
          ToFinalCameraBlendTime = 3,
          TurnTo = {
            [1] = "100001:p(-75)"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136C4A"
        },
        [12014034] = {
          Camera = "139.226379,128.650238,49.652344,0.000156,11.202827,-146.769257,40.0,369.932373,false,Manual,6.0",
          ContentFR = "Bien sûr. Restez près de moi. Je vous guiderai.",
          DialogueId = 12014034,
          GUID = "1E136C74",
          LookAt = {
            [1] = "210013:n(200002)"
          },
          Scripts = [[
SEQ{
LookAt{_delay{0.5},LookAtDescription{"210013:n(100001)"}},
PlayAnimation{_delay{1.1},ActorId{210013},AnimationId{"Baiheng_Story_Special01_Start"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 210013,
          Subtitle = "Of course. Stay close. I shall lead the way.",
          TalkActionId = {
            [1] = "200002:SpecialHappy_End",
            [2] = "100001:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120140/1E136C74"
        },
        [12014201] = {
          ContentFR = "... Je ne m’attendais pas à ce que la Poussière-corrompue atteigne même cet endroit.",
          DialogueId = 12014201,
          Duration = 3,
          GUID = "1E1387DA",
          NextDialogue = 12014202,
          SpeakNpcId = 210013,
          Subtitle = "...I hadn't foreseen that the Gritblight would touch even this sanctuary.",
          VoiceName = "voice/$Locale$/story/1201/120142/1E1387DA"
        },
        [12014202] = {
          ContentFR = "Ne t’inquiète pas. Je sais comment m’en occuper.",
          DialogueId = 12014202,
          Duration = 2,
          GUID = "1E138804",
          NextDialogue = 12014203,
          SpeakNpcId = 100001,
          Subtitle = "Don't worry. I've got this.",
          VoiceName = "voice/$Locale$/story/1201/120142/1E138804"
        },
        [12014203] = {
          ContentFR = "Héhé... Après tout, Snow et le petit larbin sont désormais de véritables Apprentis d’honneur de la Secte Jishu ! Regarde bien !",
          DialogueId = 12014203,
          Duration = 2,
          GUID = "1E13882E",
          NextDialogue = 12014204,
          SpeakNpcId = 200002,
          Subtitle = "Uh-huh! After all, the great Demon King and her Little Minion are now proud honorary learners of the Jishu Sect! Just watch us!",
          VoiceName = "voice/$Locale$/story/1201/120142/1E13882E"
        },
        [12014204] = {
          ContentFR = "La Secte Jishu... ? Voilà un nom que l’on n’entend plus depuis bien longtemps. Comment avez-vous croisé leur chemin ?",
          DialogueId = 12014204,
          Duration = 2,
          GUID = "1E138858",
          NextDialogue = 12014205,
          SpeakNpcId = 210013,
          Subtitle = "The Jishu Sect...? That name has all but faded from memory. How did you come to be involved with them?",
          VoiceName = "voice/$Locale$/story/1201/120142/1E138858"
        },
        [12014205] = {
          ContentFR = "Héhé ! Voilà ce que les romans appellent une \"rencontre du destin\", rien que ça !",
          DialogueId = 12014205,
          Duration = 3,
          GUID = "1E138882",
          SpeakNpcId = 200002,
          Subtitle = "Heh! Just like one of those wild tales you hear in old legends — pure luck, I'd say!",
          VoiceName = "voice/$Locale$/story/1201/120142/1E138882"
        },
        [12014301] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah ! Des monstres blancs !",
          DialogueId = 12014301,
          GUID = "1E139842",
          NextDialogue = 12014302,
          RelatedWikiId = {
            [1] = 408013,
            [2] = 303012,
            [3] = 203006
          },
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ah! White monsters!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139842"
        },
        [12014302] = {
          ContentFR = "Ou— ouah— ! Qui a parlé ?! Un fantôme ?! À l’aide, petit larbin !",
          DialogueId = 12014302,
          GUID = "1E13986C",
          NextDialogue = 12014303,
          SpeakNpcId = 200002,
          Subtitle = "Eek! Wh—Who's talking!? A ghost!? Little Minion, help!!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E13986C"
        },
        [12014303] = {
          ContentFR = "Inutile de paniquer, Snow. C’est l’un des Wishen dont je t’ai parlé. Ceux qui n’ont pas reçu leur invitation ne peuvent pas voir leur véritable forme.",
          DialogueId = 12014303,
          GUID = "1E139896",
          NextDialogue = 12014304,
          SpeakNpcId = 210013,
          Subtitle = "Calm yourself, Snow. This is a Wishen I spoke of. Those who have not been invited cannot see their form.",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139896"
        },
        [12014304] = {
          ContentFR = "Wei Shen, ces deux-là sont mes amis. Nous souhaitons rencontrer l’Ainé. Pourrais-tu te montrer et leur indiquer le chemin ?",
          DialogueId = 12014304,
          GUID = "1E1398C0",
          NextDialogue = 12014305,
          SpeakNpcId = 210013,
          Subtitle = "Wei Shen, these two are my friends. We seek an audience with Elder Wishen. Could you reveal yourself and show them the way?",
          VoiceName = "voice/$Locale$/story/1201/120143/1E1398C0"
        },
        [12014305] = {
          ContentFR = "Les amis de Fushu sont aussi les amis de Wei Shen !",
          DialogueId = 12014305,
          GUID = "1E1398EA",
          NextDialogue = 12014306,
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "Sure! Friends of Fushu are friends of mine!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E1398EA"
        },
        [12014306] = {
          ContentFR = "Ouah... alors c’est ça, un Wishen ? Il est tout rond... et plutôt mignon !",
          DialogueId = 12014306,
          GUID = "1E139914",
          NextDialogue = 12014307,
          SpeakNpcId = 200002,
          Subtitle = "Whoa... so this is a Wishen? It's all round and puffy — kinda cute, actually!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139914"
        },
        [12014307] = {
          ContentFR = "Pourquoi n’étais-tu pas à l’autel ? Que faisais-tu ici ?",
          DialogueId = 12014307,
          GUID = "1E13993E",
          NextDialogue = 12014308,
          SpeakNpcId = 210013,
          Subtitle = "Why aren't you at the altar? What are you doing out here?",
          VoiceName = "voice/$Locale$/story/1201/120143/1E13993E"
        },
        [12014308] = {
          ContentFR = "La Poussière-corrompue... elle est sortie de la terre... Elle a coincé les pieds de Wei Shen... Je ne pouvais plus marcher... ni courir...",
          DialogueId = 12014308,
          GUID = "1E139968",
          NextDialogue = 12014309,
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "The Gritblight... it rose up from the ground... now my feet are stuck. I can't walk or run at all...",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139968"
        },
        [12014309] = {
          ContentFR = "Je ne suis pas rentré avant la nuit... Maman doit s’inquiéter...",
          DialogueId = 12014309,
          GUID = "1E139992",
          NextDialogue = 12014310,
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "I didn't make it home before dark... and Mama must be so worried...",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139992"
        },
        [12014310] = {
          ContentFR = "Ne t’en fais pas ! On va te ramener chez toi. Laisse ça à Snow !",
          DialogueId = 12014310,
          GUID = "1E1399BC",
          NextDialogue = 12014311,
          SpeakNpcId = 200002,
          Subtitle = "Don't worry! We'll get you home safe and sound!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E1399BC"
        },
        [12014311] = {
          ContentFR = "Chez moi... la maison de Wei Shen a disparu... Je ne trouve plus Maman... Je n’ai nulle part où aller...",
          DialogueId = 12014311,
          GUID = "1E1399E6",
          NextDialogue = 12014312,
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "Home... I've lost it. I looked everywhere, but I can't find Mama... I don't have anywhere to go anymore!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E1399E6"
        },
        [12014312] = {
          ContentFR = "Oh non... pourquoi il s’énerve d’un coup ?",
          DialogueId = 12014312,
          GUID = "1E139A10",
          NextDialogue = 12014313,
          SpeakNpcId = 200002,
          Subtitle = "Uh-oh... why did it get so upset all of a sudden?",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139A10"
        },
        [12014313] = {
          ContentFR = "Snow, laisse-moi faire.",
          DialogueId = 12014313,
          GUID = "1E139A3A",
          NextDialogue = 12014314,
          SpeakNpcId = 210013,
          Subtitle = "Snow, let me handle this.",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139A3A"
        },
        [12014314] = {
          ContentFR = "Tu es resté dehors bien trop longtemps. Tu dois être épuisé. Revenons d’abord à l’autel, d’accord ?",
          DialogueId = 12014314,
          GUID = "1E139A64",
          NextDialogue = 12014315,
          SpeakNpcId = 210013,
          Subtitle = "You've lingered here far too long — you must be weary. Let us return to the altar, so you may find a moment of rest.",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139A64"
        },
        [12014315] = {
          ContentFR = "... D’accord !",
          DialogueId = 12014315,
          GUID = "1E139A8E",
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "...Okay!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139A8E"
        },
        [12014316] = {
          ContentFR = "Wei Shen rentre à la maison !",
          DialogueId = 12014316,
          GUID = "1E139A8F",
          Subtitle = "Wei Shen is going home!",
          VoiceName = "voice/$Locale$/story/1201/120143/1E139A8F"
        },
        [12014401] = {
          Camera = "787.018799,197.117432,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Merci à vous !",
          DialogueId = 12014401,
          FinalCamera = "789.158203,179.179382,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1E13A8AA",
          NextDialogue = 12014402,
          SnapShot = "WUYOU",
          SpeakNpcId = 210016,
          Subtitle = "—Thank you!",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A8AA"
        },
        [12014402] = {
          Camera = "154.71994,121.273628,111.300293,0.000013,4.39925,164.604019,35.000008,170.252457,false,Manual,3.826119",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Les Wishen sont des êtres nés d’attachements persistants.",
          DialogueId = 12014402,
          FacialId = {
            [1] = "210013:Sad03"
          },
          FinalCamera = "148.449249,101.440178,111.300293,0.000014,4.799225,156.803726,35.000011,170.252457,false,Manual,3.826119",
          GUID = "1E13A8D4",
          LookAt = {
            [1] = "210013:n(100001)",
            [2] = "200002:n(210013)",
            [3] = "100001:n(210013)"
          },
          NextDialogue = 12014403,
          RelatedWikiId = {
            [1] = 303012
          },
          SpeakNpcId = 210013,
          Subtitle = "The Wishens are spirits woven from unfulfilled longings.",
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "200002:n(210013)"
          },
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A8D4"
        },
        [12014403] = {
          ContentFR = "Celui-ci devait être un enfant qui s’était enfui de chez lui pour jouer... Puis il a chuté, et a perdu la vie. Depuis lors, « rentrer à la maison » est devenu son obsession.",
          DialogueId = 12014403,
          Duration = 1,
          GUID = "1E13A8FE",
          NextDialogue = 12014404,
          SpeakNpcId = 210013,
          Subtitle = "This little one was likely a child who slipped away to play... and met a sudden end. Ever since, \"going home\" has lingered as its last, unfulfilled wish.",
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A8FE"
        },
        [12014404] = {
          Camera = "69.47644,193.072845,103.465088,0.000062,22.596144,-171.999283,45.000023,78.807327,false,Manual,7.461847",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Hélas, il était trop jeune pour se souvenir du chemin. Et avec le temps... sa famille est sans doute introuvable désormais.",
          DialogueId = 12014404,
          Duration = 1,
          FinalCamera = "66.714828,163.37291,100.481201,0.000061,24.395912,161.600143,45.000027,78.807327,false,Manual,7.461847",
          GUID = "1E13A928",
          LookAt = {
            [1] = "210013:p(BP_FixSimple_39_fushu)"
          },
          NextDialogue = 12014405,
          SpeakNpcId = 210013,
          Subtitle = "Sadly, it was far too young to remember where home lay. And now... so many seasons have passed, its family... is likely long gone.",
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A928"
        },
        [12014405] = {
          Camera = "95.111908,170.19989,184.635742,0.000034,-28.601601,178.796585,35.000011,248.150375,false,Manual,10.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Alors les Wishen sont vraiment des fantômes... Mais ils ne font pas peur comme dans les livres. Ils font plutôt... de la peine.",
          DialogueId = 12014405,
          FacialId = {
            [1] = "200002:Curious"
          },
          FinalCamera = "94.933746,161.763794,184.635742,0.000033,-28.801596,176.59642,35.000011,248.150375,false,Manual,10.0",
          GUID = "1E13A952",
          LookAt = {
            [1] = "210013:n(200002)"
          },
          NextDialogue = 12014406,
          Scripts = "PlayFacial{_delay{4.5},ActorId{200002},FacialId{\"Sad01\"}}",
          SpeakNpcId = 200002,
          Subtitle = "So Wishens really are ghosts... but not the scary kind from old stories. If anything... they're a little bit sad.",
          TalkActionId = {
            [1] = "200002:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A952"
        },
        [12014406] = {
          Camera = "787.018799,197.117432,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Il devrait encore y avoir deux autres Wishen. Ils ont sans doute, eux aussi, été affectés par la Poussière-corrompue. Allons chercher leur trace.",
          DialogueId = 12014406,
          FinalCamera = "789.158203,179.179382,202.770752,0.000005,-7.400913,-173.19368,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1E13A97C",
          LookAt = {
            [1] = "210013:n(100001)"
          },
          Scripts = "PlayAnimation{_delay{4.5},ActorId{210013},AnimationId{\"Explain01_Start\"},Duration{1}}",
          SpeakNpcId = 210013,
          Subtitle = "There should be two more nearby. I fear the Gritblight has found them too. Come — let us search for their traces.",
          TalkActionId = {
            [1] = "200002:Explain02_End",
            [2] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120144/1E13A97C"
        },
        [12014501] = {
          ContentFR = "« Un, deux, trois... on ne bouge plus... »",
          DialogueId = 12014501,
          Duration = 2,
          GUID = "1E13B912",
          NextDialogue = 12014502,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_CMName_Name_WuyouShengSY",
          Subtitle = "\"One, two, three... Red Light!\"",
          VoiceName = "voice/$Locale$/story/1201/120145/1E13B912"
        },
        [12014502] = {
          ContentFR = "Il y a un Wishen à l’intérieur... mais l’accès est bloqué.",
          DialogueId = 12014502,
          Duration = 3,
          GUID = "1E13B93C",
          NextDialogue = 12014503,
          SpeakNpcId = 210013,
          Subtitle = "There lies a little Wishen within the cave, yet the way has been sealed by fallen rocks...",
          VoiceName = "voice/$Locale$/story/1201/120145/1E13B93C"
        },
        [12014503] = {
          ContentFR = "Reçu ! Équipe de démolition du Roi Démon, en action !",
          DialogueId = 12014503,
          Duration = 2,
          GUID = "1E13B966",
          SpeakNpcId = 200002,
          Subtitle = "Got it! Time for the Demon King's demolition crew to work their magic!",
          VoiceName = "voice/$Locale$/story/1201/120145/1E13B966"
        },
        [12014601] = {
          ContentFR = "« On est tous des statues... pas le droit de parler, pas le droit de bouger... »",
          DialogueId = 12014601,
          Duration = 3,
          GUID = "1E13C97A",
          NextDialogue = 12014602,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "\"We're all statues... no talking, no moving...\"",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13C97A"
        },
        [12014602] = {
          ContentFR = "Il est où, alors ?",
          DialogueId = 12014602,
          Duration = 1,
          GUID = "1E13C9A4",
          NextDialogue = 12014605,
          SpeakNpcId = 200002,
          Subtitle = "Where could it be?",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13C9A4"
        },
        [12014603] = {
          ContentFR = "L’odeur étrangère le rend méfiant... il refuse de se montrer.",
          DialogueId = 12014603,
          Duration = 3,
          GUID = "1E13C9CE",
          SpeakNpcId = 210013,
          Subtitle = "Maybe the unfamiliar scents here make it wary, so it hides away.",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13C9CE"
        },
        [12014604] = {
          ContentFR = "Allumons l’encens. Le parfum familier devrait le rassurer.",
          DialogueId = 12014604,
          Duration = 2,
          GUID = "1E13C9F8",
          SpeakNpcId = 210013,
          Subtitle = "Let's light the incense. The familiar fragrance may soothe it...",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13C9F8"
        },
        [12014605] = {
          ContentFR = "... Ces bourgeons ont été contaminés par la Poussière-corrompue. Ils dégagent une odeur inhabituelle. Cela doit l’effrayer.",
          DialogueId = 12014605,
          GUID = "1E13C9F9",
          NextDialogue = 12014606,
          SpeakNpcId = 210013,
          Subtitle = "These buds have been tainted, giving off unfamiliar scents. That might be why it refuses to show itself.",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13C9F9"
        },
        [12014606] = {
          ContentFR = "Essayons de les éliminer.",
          DialogueId = 12014606,
          GUID = "1E13CA11",
          SpeakNpcId = 210013,
          Subtitle = "Let's clear out these buds.",
          VoiceName = "voice/$Locale$/story/1201/120146/1E13CA11"
        },
        [12014701] = {
          ContentFR = "Tu m’as trouvé !",
          DialogueId = 12014701,
          Duration = 2,
          GUID = "1E13D9E2",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "You found me!",
          VoiceName = "voice/$Locale$/story/1201/120147/1E13D9E2"
        },
        [12014801] = {
          ContentFR = "« ... Je— je suis une statue ! Tu ne peux pas me voir... ni me frapper ! »",
          DialogueId = 12014801,
          Duration = 3,
          GUID = "1E13EA4A",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "\"I—I'm a statue! You can't see me, and you can't hit me either!\"",
          VoiceName = "voice/$Locale$/story/1201/120148/1E13EA4A"
        },
        [12014802] = {
          ContentFR = "Je reconnais le chemin... l’autel est juste devant. Merci !",
          DialogueId = 12014802,
          GUID = "1E13EA4B",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "I know the way... the altar is up ahead, thank you!",
          VoiceName = "voice/$Locale$/story/1201/120148/1E13EA4B"
        },
        [12014901] = {
          ContentFR = "Hé ! Il y a quelque chose d’écrit sur cette stèle !",
          DialogueId = 12014901,
          Duration = 2,
          GUID = "1E13FAB2",
          SpeakNpcId = 200002,
          Subtitle = "Hey! There's something written on that stone tablet!",
          VoiceName = "voice/$Locale$/story/1201/120149/1E13FAB2"
        },
        [12014902] = {
          ContentFR = "<H>Haut dans les cieux</>, il observe les vivants. <H>Peu à peu plus bas</>, il retourne à la poussière. Silencieux, invisible, porté par le vent... Qui peut retrouver sa trace ?",
          DialogueId = 12014902,
          GUID = "1E13FADC",
          Subtitle = "Lofty above, watching all below. Drifting down, returning to soil. Silent and unseen, swept away on the wind... Tell me — can you find its trail?",
          VoiceName = "voice/$Locale$/story/1201/120149/1E13FADC"
        },
        [12015001] = {
          ContentFR = "Allez, assez joué ! On rentre !",
          DialogueId = 12015001,
          Duration = 2,
          GUID = "1E140B1A",
          NextDialogue = 12015002,
          SpeakNpcId = 200002,
          Subtitle = "Come on, playtime's over! Let's go back!",
          VoiceName = "voice/$Locale$/story/1201/120150/1E140B1A"
        },
        [12015002] = {
          ContentFR = "Non ! Pas encore ! Il faut d’abord résoudre l’énigme !",
          DialogueId = 12015002,
          Duration = 3,
          GUID = "1E140B44",
          NextDialogue = 12015003,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Uh-uh! Not until you solve my riddle!",
          VoiceName = "voice/$Locale$/story/1201/120150/1E140B44"
        },
        [12015003] = {
          ContentFR = "Argh... qu’est-ce que ça veut dire, {nickname} ?",
          DialogueId = 12015003,
          Duration = 2,
          GUID = "1E140B6E",
          NextDialogue = 12015004,
          SpeakNpcId = 200002,
          Subtitle = "Ugh, this is giving me a headache... , any idea?",
          VoiceName = "voice/$Locale$/story/1201/120150/1E140B6E"
        },
        [12015004] = {
          ContentFR = "« Haut dans les cieux, peu à peu plus bas »... Peut-être faut-il activer ces bourgeons de haut en bas.",
          DialogueId = 12015004,
          GUID = "1E140B6F",
          NextDialogue = 12015005,
          SpeakNpcId = 210013,
          Subtitle = "\"Lofty above, drifting down\"... I suppose, maybe we need to hit the buds from top to bottom?",
          VoiceName = "voice/$Locale$/story/1201/120150/1E140B6F"
        },
        [12015005] = {
          ContentFR = "Bonne idée ! Essayons vite, petit larbin !",
          DialogueId = 12015005,
          GUID = "1E140B71",
          SpeakNpcId = 200002,
          Subtitle = "Ooh, that makes sense! Let's try it, Little Minion!",
          VoiceName = "voice/$Locale$/story/1201/120150/1E140B71"
        },
        [12015101] = {
          Camera = "428.628632,87.300842,126.54541,0.0,0.0,-179.794601,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors ? Vous avez trouvé la réponse ?",
          DialogueId = 12015101,
          FinalCamera = "427.964111,58.333099,126.54541,0.0,0.0,178.205566,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E141B82",
          LookAt = {
            [1] = "100001:n(210013)",
            [2] = "100001:n(210039)"
          },
          NextDialogue = 12015102,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Do you have the answer for me now?",
          TalkActionId = {
            [1] = "210039:Wuyou_Born"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120151/1E141B82"
        },
        [12015102] = {
          Camera = "-296.378662,-545.068665,191.578613,0.000033,-5.400473,67.00705,40.000023,644.465149,false,Manual,8.26397",
          ContentFR = "Observer d’en haut, disparaître sans laisser de trace, retourner à la poussière... Tu parles sans doute des nuages.",
          DialogueId = 12015102,
          FinalCamera = "-331.210388,-529.07074,191.578613,0.000035,-5.400439,63.406521,40.000023,644.465149,false,Manual,8.26397",
          GUID = "1E141BAC",
          LookAt = {
            [1] = "210013:n(100001)"
          },
          NextDialogue = 12015103,
          Scripts = "LookAt{_delay{3.1},LookAtDescription{\"210013:n(210039)\"}}",
          SpeakNpcId = 210013,
          Subtitle = "Gazing down from above, yet returning to the soil without a trace... I would say you speak of the clouds.",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "210013:Shy03_Start",
            [3] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120151/1E141BAC"
        },
        [12015103] = {
          Camera = "428.628632,87.300842,126.54541,0.0,0.0,-179.794601,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hihi ! La grande sœur est trop forte ! J’ai bien joué, on peut rentrer !",
          DialogueId = 12015103,
          FinalCamera = "427.964111,58.333099,126.54541,0.0,0.0,178.205566,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E141BD6",
          LookAt = {
            [1] = "100001:n(210039)"
          },
          Scripts = "PlayAnimation{_delay{4.1},ActorId{210039},AnimationId{\"Wuyou_Disappear\"},Duration{1}}",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Heehee! You're really smart, Miss Fushu! That was fun — okay, let's head back!",
          TalkActionId = {
            [1] = "100001:Think_End",
            [2] = "210039:Wuyou_Agree",
            [3] = "200002:Think_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120151/1E141BD6"
        },
        [12015201] = {
          Camera = "920.312744,232.194031,104.525879,0.000081,-0.59857,-171.306732,30.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Enfin... on a retrouvé les trois petits Wishen. Même le Roi Démon est épuisé !",
          DialogueId = 12015201,
          FacialId = {
            [1] = "200002:Syouganai01"
          },
          FinalCamera = "935.710205,90.954773,104.525879,0.000081,-0.59857,-176.506149,30.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E142BEA",
          NextDialogue = 12015202,
          Scripts = "PlayAnimation{_delay{3.01},ActorId{200002},AnimationId{\"BaiTX_Story_Tired_End\"},Duration{1}},\n",
          SpeakNpcId = 200002,
          Subtitle = "Finally found all three of the little Wishens... This Demon King's worn out!",
          TalkActionId = {
            [1] = "200002:BaiTX_Story_Tired_Loop"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120152/1E142BEA"
        },
        [12015202] = {
          Camera = "38.708542,27.845192,156.223022,0.000037,4.201495,162.893906,30.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Écoutez bien ! À partir de maintenant, vous restez ici, sans bavarder ni partir en cachette !",
          DialogueId = 12015202,
          FacialId = {
            [1] = "200002:Angry01"
          },
          FinalCamera = "99.139954,-31.090532,153.350342,0.000036,2.801416,161.096512,30.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E142C14",
          LookAt = {
            [1] = "200002:n(210038)"
          },
          NextDialogue = 12015203,
          SpeakNpcId = 200002,
          Subtitle = "Listen up, you three! From now on — no more chattering or sneaking off! Stay right here, got it?",
          TalkActionId = {
            [1] = "200002:Confident_Start",
            [2] = "100001:Confident_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120152/1E142C14"
        },
        [12015203] = {
          ContentFR = "Allons, Snow. Ne les embête pas davantage. S’ils se fâchent, ils pourraient refuser d’ouvrir la porte menant à la Source de Yu.",
          DialogueId = 12015203,
          FacialId = {
            [1] = "200002:None"
          },
          GUID = "1E142C3E",
          LookAt = {
            [1] = "200002:n(210013)"
          },
          NextDialogue = 12015204,
          SpeakNpcId = 210013,
          Subtitle = "Do not tease them further, Snow. If you upset them, they may refuse to open the gate to the Spring of Yu for you.",
          TalkActionId = {
            [1] = "200002:Confident_End",
            [2] = "210013:Explain01_Start",
            [3] = "100001:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120152/1E142C3E"
        },
        [12015204] = {
          Camera = "133.228226,-647.736572,205.264771,0.000173,-8.198883,105.089806,30.000002,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Hein ?! Attends... tu veux dire qu’on n’y est pas encore ?",
          DialogueId = 12015204,
          FacialId = {
            [1] = "200002:Think01"
          },
          FinalCamera = "155.219604,-729.304077,217.437256,0.000173,-8.198883,105.089806,30.000002,100000.0,false,DoNotOverride,2.8",
          GUID = "1E142C68",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "100001:n(200002)"
          },
          SpeakNpcId = 200002,
          Subtitle = "Wait, what!? You mean... we're not there yet?",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200002:Shy03_Start",
            [3] = "210013:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120152/1E142C68"
        },
        [12015301] = {
          ContentFR = "Ouah... !",
          DialogueId = 12015301,
          GUID = "1E143C52",
          SpeakNpcId = 200002,
          Subtitle = "Whoa...!",
          VoiceName = "voice/$Locale$/story/1201/120153/1E143C52"
        },
        [12015401] = {
          ContentFR = "<I>Bouh...</> grande sœur... grande sœur a disparu...",
          DialogueId = 12015401,
          GUID = "1E144CBA",
          SnapShot = "WUYOU",
          SpeakNpcId = 210019,
          Subtitle = "*sobbing*... Big sis... where are you...?",
          VoiceName = "voice/$Locale$/story/1201/120154/1E144CBA"
        },
        [12015402] = {
          ContentFR = "Devant vous se déploie lentement un monde étrange et chatoyant... Un royaume appartenant aux Wishen, dissimulé au regard ordinaire.",
          DialogueId = 12015402,
          GUID = "1E144CBB",
          Subtitle = "Before you unfolds a realm both strange and wondrous — a world that belongs to Wishen, veiled yet vast."
        },
        [12015501] = {
          Camera = "362.349304,617.265076,20.103271,0.000049,3.644691,-117.98333,30.0,50.546654,false,Manual,13.930334",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Ah... tant qu’il nous reste des jours assez longs pour sentir le soleil sur notre peau, le bonheur finit toujours par revenir, et les sourires aussi.",
          DialogueId = 12015501,
          FinalCamera = "379.79364,607.996277,20.103271,0.000049,3.644691,-117.983383,30.000002,548.337769,false,Manual,13.930334",
          GUID = "1E145D22",
          LookAt = {
            [1] = "200002:n(210040)",
            [2] = "100001:n(210040)",
            [3] = "210013:n(210040)"
          },
          NextDialogue = 12015502,
          RelatedWikiId = {
            [1] = 408013,
            [2] = 303012,
            [3] = 203006
          },
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Ah... so long as we can keep basking in the sun, the days will stay warm, and our smiles will never fade.",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120155/1E145D22"
        },
        [12015502] = {
          Camera = "63.533028,163.058304,86.610718,0.000035,20.601974,-118.808426,35.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Que ces vieux os puissent revoir une connaissance d’autrefois... ça valait le coup. Dame Zhuyou, et deux hôtes venus d’au-delà. Soyez les bienvenus.",
          DialogueId = 12015502,
          FinalCamera = "80.940094,151.962341,86.610718,0.000031,20.202141,-123.608315,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E145D4C",
          NextDialogue = 12015503,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "To behold an old friend once more — such fortune in this lifetime. Lady Zhuyou. Travellers from beyond. Welcome.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120155/1E145D4C"
        },
        [12015503] = {
          Camera = "-357.707886,104.663635,262.303223,0.000057,-18.755178,-8.789527,30.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Vous êtes trop aimable. Je ne mérite pas un tel titre.",
          DialogueId = 12015503,
          FinalCamera = "-357.707886,104.663635,262.303223,0.000051,-20.955013,-7.790245,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E145D76",
          NextDialogue = 12015504,
          SpeakNpcId = 210013,
          Subtitle = "You honour me too greatly, Elder — I am unworthy of such a title.",
          TalkActionId = {
            [1] = "210013:Baiheng_Story_Special01_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120155/1E145D76"
        },
        [12015504] = {
          ContentFR = "Héhé... lors de l’épidémie d’il y a cent ans, j’ai reçu les bienfaits de vos soins. Je ne l’ai jamais oublié. Dites-moi donc ce dont vous avez besoin.",
          DialogueId = 12015504,
          FacialId = {
            [1] = "200002:Nervous"
          },
          GUID = "1E145DA0",
          NextDialogue = 12015505,
          RelatedWikiId = {
            [1] = 401004
          },
          Scripts = [[
SEQ{
LookAt{_delay{6.1},LookAtDescription{"200002:n(210013)"}},
LookAt{_delay{2.1},LookAtDescription{"200002:n(210040)"}},
PlayAnimation{delay{1.5},ActorId{200002},AnimationId{"Think_End"},Duration{1}}
}]],
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Hehe... A century ago, in the days of pestilence, it was your healing hands that spared my life. That kindness has never faded from my heart, Lady Zhuyou. Pray, tell me what you would ask of me.",
          TalkActionId = {
            [1] = "200002:Think_Start",
            [2] = "210013:Baiheng_Story_Special01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145DA0"
        },
        [12015505] = {
          Camera = "115.516785,197.20285,91.707275,0.000133,-32.198425,-53.396206,30.0,140.374573,false,Manual,8.366085",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Attends, petit larbin... tu trouves pas qu’il y a un truc qui cloche dans ce qu’ils viennent de dire ?!",
          DialogueId = 12015505,
          FinalCamera = "105.107033,219.02327,94.781616,0.000144,-27.398195,-54.795994,30.0,166.458572,false,Manual,11.745219",
          GUID = "1E145DCA",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "100001:n(200002)"
          },
          NextOptions = {
            [1] = 120155051,
            [2] = 120155052
          },
          SpeakNpcId = 200002,
          Subtitle = "Wait a second, Little Minion... did you hear what he said? Notice anything weird!?",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200002:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145DCA"
        },
        [12015507] = {
          ContentFR = "Mais tu n’as pas compris ?! D’après ce qu’il dit, Fushu a au moins cent ans !",
          DialogueId = 12015507,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "1E145E1E",
          NextDialogue = 12015509,
          SpeakNpcId = 200002,
          Subtitle = "Didn't you catch that!? He said Fushu's been around for over a hundred years!",
          VoiceName = "voice/$Locale$/story/1201/120155/1E145E1E"
        },
        [12015509] = {
          Camera = "105.107033,219.02327,94.781616,0.000144,-27.398195,-54.795994,30.0,166.458572,false,Manual,11.745219",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Ça ne se voit absolument pas ! Ne me dis pas que la médecine de Huaxu a déjà percé le secret de l’immortalité ?!",
          DialogueId = 12015509,
          FinalCamera = "131.587952,179.929916,89.484497,0.000167,-4.597933,-58.195728,30.0,166.458572,false,Manual,11.745219",
          GUID = "1E145E72",
          LookAt = {
            [1] = "200002:n(210013)",
            [2] = "100001:n(210013)"
          },
          NextDialogue = 12015510,
          Scripts = [[
SEQ{
LookAt{delay{2.5},LookAtDescription{"210013:n(100001)"}},
TurnTo{TurnToDescription{"210013:n(100001)"}},
PlayAnimation{delay{2.5},ActorId{210013},AnimationId{"Explain02_Start"},Duration{1}},
}]],
          SpeakNpcId = 200002,
          Subtitle = "She doesn't look it at all! Don't tell me Huaxu medicine's already reached the level of immortality!",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200002:n(210013)"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145E72"
        },
        [12015510] = {
          ContentFR = "... Ce n’est pas ce que vous imaginez.",
          DialogueId = 12015510,
          GUID = "1E145E9C",
          LookAt = {
            [1] = "210013:n(100001)"
          },
          NextDialogue = 12015511,
          Scripts = "PlayAnimation{delay{2.5},ActorId{210013},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 210013,
          Subtitle = "...It is not as you might think.",
          TalkActionId = {
            [1] = "210013:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145E9C"
        },
        [12015511] = {
          ContentFR = "L’immortalité n’appartient à personne : aux yeux du monde, nous ne sommes que des éphémères. J’ai seulement appris l’Art de l’Éphémère... sans pouvoir échapper aux lois naturelles de la naissance, de l’âge et de la mort.",
          DialogueId = 12015511,
          GUID = "1E145EC6",
          NextDialogue = 12015512,
          Scripts = [[
SEQ{
PlayAnimation{delay{0.5},ActorId{210013},AnimationId{"Talk01_Start"},Duration{3}},
PlayAnimation{ActorId{210013},AnimationId{"Talk01_End"},Duration{5}},
PlayAnimation{delay{0.5},ActorId{210013},AnimationId{"DisagreeHead"},Duration{3}},
LookAt{LookAtDescription{"210013:p(BP_FixSimple_42_fushu01)"}}
}]],
          SpeakNpcId = 210013,
          Subtitle = "Immortality is but an illusion — across this world, life flits by like the mayfly's shadow. Though I have mastered the Art of Ephemerality, I too remain bound to the cycle of birth, aging, and death.",
          VoiceName = "voice/$Locale$/story/1201/120155/1E145EC6"
        },
        [12015512] = {
          Camera = "113.025772,32.107635,18.959473,0.000157,29.397686,10.806211,30.000008,12977.529297,false,Manual,12.571992",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Lors de la Grande Épidémie, il y a cent ans... en soignant les malades, j’ai été imprudente et j’ai... contracté un mal terrible. Ma sœur a figé mon corps par un procédé qui lui était propre, afin de ralentir la progression de la maladie.",
          DialogueId = 12015512,
          Duration = 2,
          FinalCamera = "177.948578,52.488884,107.528198,0.000187,49.996937,27.204828,30.000013,12977.529297,false,Manual,12.571992",
          GUID = "1E145EF0",
          NextDialogue = 12015513,
          SpeakNpcId = 210013,
          Subtitle = "During the great plague a hundred years past, I... fell ill while tending to the sick. My sister, using a secret art, placed me in stasis to halt the disease's advance.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120155/1E145EF0"
        },
        [12015513] = {
          Camera = "117.45327,198.753036,53.425415,0.000171,6.802288,-52.19939,30.000008,184.001556,false,Manual,14.564116",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Ce n’est que récemment qu’un disciple de ma sœur m’a tirée de ce long sommeil. À l’aide d’un remède nouvellement mis au point, il a purgé la maladie de mon corps… et j’ai pu revenir parmi les vivants.",
          DialogueId = 12015513,
          FinalCamera = "99.263199,221.05603,50.602173,0.000163,5.602271,-50.799461,30.000008,246.6875,false,Manual,14.564116",
          GUID = "1E145F1A",
          LookAt = {
            [1] = "210013:n(100001)"
          },
          NextDialogue = 12015514,
          SpeakNpcId = 210013,
          Subtitle = "It was only recently that her disciples woke me, armed with a new remedy to purge the illness at last. And thus, I returned to the world once more.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "100001:n(210013)"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145F1A"
        },
        [12015514] = {
          Camera = "193.710571,70.915855,75.647705,0.000229,-10.198722,104.400436,30.000023,100.823143,false,Manual,12.571992",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Je comprends mieux pourquoi ton pavillon était si impeccablement rangé... on aurait dit qu’il n’avait jamais été habité.",
          DialogueId = 12015514,
          FacialId = {
            [1] = "100001:Shy"
          },
          FinalCamera = "191.586731,79.1856,74.111816,0.000238,-10.198688,104.400826,30.000023,79.899963,false,Manual,12.571992",
          GUID = "1E145F44",
          NextDialogue = 12015515,
          SpeakNpcId = 100001,
          Subtitle = "That explains why your home felt so neat... as if no one's ever lived there.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120155/1E145F44"
        },
        [12015515] = {
          ContentFR = "Cent ans ont passé... et ta sœur ? Est-elle encore en vie ?",
          DialogueId = 12015515,
          FacialId = {
            [1] = "100001:Sad03"
          },
          GUID = "1E145F6E",
          LookAt = {
            [1] = "210013:n(210013)"
          },
          NextDialogue = 12015516,
          SpeakNpcId = 100001,
          Subtitle = "After all these years, your sister... is she still alive?",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145F6E"
        },
        [12015516] = {
          Camera = "141.07724,117.392189,94.321289,0.000034,-5.756408,-48.184006,40.0,105.288483,false,Manual,8.191999",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Après mon réveil, j’ai cherché, longtemps... J’ai appris que ma sœur s’était éteinte, il y a déjà quelques années.",
          DialogueId = 12015516,
          FacialId = {
            [1] = "210013:Sad03"
          },
          FinalCamera = "137.903931,114.5532,94.321289,0.000034,-5.756408,-48.184006,40.0,105.288483,false,Manual,8.191999",
          GUID = "1E145F98",
          NextDialogue = 12015517,
          SpeakNpcId = 210013,
          Subtitle = "After I awoke, I searched far and wide... only to learn she had already passed on, some years ago.",
          TalkActionId = {
            [1] = "210013:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120155/1E145F98"
        },
        [12015517] = {
          Camera = "528.575195,399.370605,61.019653,0.000049,2.244195,-139.985504,30.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Oh, ce n’est rien de tragique. Les gens meurent, comme les plantes se fanent et refleurissent, comme les nuages se lèvent et se dissipent. Vous autres, les vivants, n’avez pas à en porter le chagrin.",
          DialogueId = 12015517,
          FinalCamera = "555.92688,361.963898,61.019653,0.000049,2.644185,-144.785583,30.000002,100000.0,false,DoNotOverride,2.8",
          GUID = "1E145FC2",
          LookAt = {
            [1] = "200002:n(210040)",
            [2] = "100001:n(210040)",
            [3] = "210013:n(210040)"
          },
          NextDialogue = 12015518,
          Scripts = "TurnTo{delay{3},TurnToDescription{\"210013:n(210040)\"}}",
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Death comes to all — like the withering of leaves, like clouds that rise and drift away. You who still draw breath — there is no need to burden your hearts with it.",
          TalkActionId = {
            [1] = "210013:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200002:n(210040)"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145FC2"
        },
        [12015518] = {
          Camera = "41.130356,69.325104,81.061401,0.000038,-30.356098,-0.185585,30.000002,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah oui, j’avais oublié... Les Wishen, eux aussi, sont des morts...",
          DialogueId = 12015518,
          FacialId = {
            [1] = "200002:Nervous"
          },
          GUID = "1E145FEC",
          NextDialogue = 12015519,
          SpeakNpcId = 200002,
          Subtitle = "Right... Wishens are the dead, too.",
          TalkActionId = {
            [1] = "200002:Shock03_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E145FEC"
        },
        [12015519] = {
          Camera = "41.130356,69.325104,81.061401,0.000038,-30.356098,-0.185532,30.000002,148.839142,false,Manual,5.737342",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Oui. Ma sœur a obtenu ce qu’elle désirait de son vivant. Son étude des remèdes et des plantes s’est transmise, a prospéré, et compte désormais de nombreux disciples... Il n’y a donc pas lieu de la regretter.",
          DialogueId = 12015519,
          FacialId = {
            [1] = "210013:None"
          },
          FinalCamera = "41.130405,69.32515,81.061401,0.000048,-0.555725,-10.785604,30.000008,173.391495,false,Manual,4.750704",
          GUID = "1E146016",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12015520,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"200002:n(210013)"}},
LookAt{_delay{5.1},LookAtDescription{"210013:n(100001)"}},
PlayAnimation{delay{0.5},ActorId{210013},AnimationId{"Shy02_End"},Duration{1}},
PlayAnimation{delay{0.5},ActorId{210013},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{ActorId{210013},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{ActorId{210013},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 210013,
          Subtitle = "Indeed. In life, my sister fulfilled her aspirations. Her devotion to the study of herbs took root and flourished — now a cherished tradition of Huaxu. There's no need to grieve for her.",
          TalkActionId = {
            [1] = "200002:Shock03_End",
            [2] = "210013:Shy02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120155/1E146016"
        },
        [12015520] = {
          Camera = "177.72258,-25.978163,61.251343,0.000003,-3.754999,86.220833,35.0,175.973785,false,Manual,4.137168",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Mais... toutes les personnes que tu connaissais ont disparu de ce monde...",
          DialogueId = 12015520,
          FinalCamera = "181.986115,-26.260483,61.251343,0.000003,-3.754999,86.220833,35.0,175.973785,false,Manual,4.137168",
          GUID = "1E146040",
          LookAt = {
            [1] = "210013:n(100001)"
          },
          NextDialogue = 12015521,
          SpeakNpcId = 100001,
          Subtitle = "But... all those you once knew are gone. You're the only one left in this world.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "210013:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E146040"
        },
        [12015521] = {
          ContentFR = "Vivre seule, ainsi... tu ne te sens pas... isolée ?",
          DialogueId = 12015521,
          GUID = "1E14606A",
          LookAt = {
            [1] = "200002:n(210013)"
          },
          NextDialogue = 12015522,
          SpeakNpcId = 100001,
          Subtitle = "Don't you feel lonely?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          TurnTo = {
            [1] = "200002:n(210013)"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E14606A"
        },
        [12015522] = {
          Camera = "141.07724,117.392189,94.321289,0.000034,-5.756408,-48.184006,40.0,105.288483,false,Manual,8.191999",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "...",
          DialogueId = 12015522,
          Duration = 3,
          FacialId = {
            [1] = "210013:Sad03"
          },
          FinalCamera = "137.903931,114.5532,94.321289,0.000034,-5.756408,-48.184006,40.0,105.288483,false,Manual,8.191999",
          GUID = "1E146094",
          NextDialogue = 12015523,
          SpeakNpcId = 210013,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "210013:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120155/1E146094"
        },
        [12015523] = {
          Camera = "188.509262,31.106506,50.589233,0.000078,-30.155823,110.398247,40.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Hé, ça va ! Maintenant, t’as Snow et le petit larbin pour te protéger ! Ça te fait deux {性别:amis|amies}, voilà !",
          DialogueId = 12015523,
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "181.691696,60.230335,63.322021,0.000088,-1.155688,96.397728,40.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1E1460BE",
          NextDialogue = 12015524,
          Scripts = "PlayAnimation{delay{1.5},ActorId{100001},AnimationId{\"AgreeHead\"},Duration{1}}",
          SpeakNpcId = 200002,
          Subtitle = "Hey, you're not alone! Not anymore — you've got this Demon King and her Little Minion watching your back now!",
          TalkActionId = {
            [1] = "200002:Excited02_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1201/120155/1E1460BE"
        },
        [12015524] = {
          Camera = "141.07724,117.392189,94.321289,0.000034,-5.756408,-48.184006,40.0,105.288483,false,Manual,8.191999",
          ContentFR = "Merci. Je m’en remets à vous, mes {性别:amis|amies}.",
          DialogueId = 12015524,
          FacialId = {
            [1] = "100001:None",
            [2] = "210013:Smile01"
          },
          GUID = "1E1460E8",
          LookAt = {
            [1] = "100001:n(210013)"
          },
          NextDialogue = 12015525,
          SpeakNpcId = 210013,
          Subtitle = "Then I shall rely on you, my friends. Thank you.",
          TalkActionId = {
            [1] = "200002:Excited02_End",
            [2] = "210013:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E1460E8"
        },
        [12015525] = {
          Camera = "-171.576187,16.046459,219.450195,0.000053,-24.99765,-0.400124,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vous n’êtes sûrement pas {性别:venus|venues} jusqu’ici juste pour bavarder avec un vieux spectre, hm ?",
          DialogueId = 12015525,
          FacialId = {
            [1] = "200002:None"
          },
          FinalCamera = "-237.973511,24.827023,258.312012,0.000038,-26.797733,2.000224,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E146112",
          LookAt = {
            [1] = "200002:n(210040)",
            [2] = "100001:n(210040)",
            [3] = "210013:n(210040)"
          },
          NextDialogue = 12015526,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Now, I suspect you didn't come all this way merely to reminisce with an old spectre.",
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "200002:n(210040)",
            [2] = "100001:n(210040)",
            [3] = "210013:n(210040)"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E146112"
        },
        [12015526] = {
          ContentFR = "Oui... Nous cherchons une plante mentionnée dans les anciens textes : l’Herbe de l’Oubli. Sauriez-vous où elle pousse ?",
          DialogueId = 12015526,
          GUID = "1E14613C",
          NextDialogue = 12015527,
          SpeakNpcId = 210013,
          Subtitle = "You're right. We seek a plant known in the old records as \"Wangyou.\" Do you know where it might still grow?",
          TalkActionId = {
            [1] = "210013:Shy03_Start",
            [2] = "100001:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E14613C"
        },
        [12015527] = {
          Camera = "784.648315,1688.77478,793.957031,0.000106,-20.798943,-107.790878,30.000013,212.18367,false,DoNotOverride,11.418732",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Oh oh... l’Herbe de l’Oubli... Dans ma jeunesse, elle couvrait les montagnes. À présent, on n’en voit plus que quelques touffes, près de la cascade, derrière la colline.",
          DialogueId = 12015527,
          FinalCamera = "784.648315,1688.77478,793.957031,0.000117,-5.398848,-81.190453,30.000013,212.18367,false,DoNotOverride,11.418732",
          GUID = "1E146166",
          NextDialogue = 12015528,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Ah, Wangyou... In my younger days, it blanketed every hill. But now, you'll find only a few sparse clusters near the waterfall beyond the rear mountain.",
          TalkActionId = {
            [1] = "210013:Shy03_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120155/1E146166"
        },
        [12015528] = {
          Camera = "97.456741,233.233795,41.130371,0.000063,8.802215,-50.793129,35.000008,224.867065,false,Manual,6.960648",
          ContentFR = "La cascade... Je vois. Merci pour ces indications.",
          DialogueId = 12015528,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          FinalCamera = "92.520905,229.20755,41.130371,0.000063,8.802215,-50.793156,35.000008,224.867065,false,Manual,6.960648",
          GUID = "1E146190",
          NextDialogue = 12015529,
          Scripts = [[
PARA{
LookAt{delay{0.5},LookAtDescription{"210013:n(100001)"}},
LookAt{delay{1.5},LookAtDescription{"100001:n(210013)"}},
LookAt{_delay{3.1},LookAtDescription{"210013:n(210040)"}},
}]],
          SpeakNpcId = 210013,
          Subtitle = "I see. Thank you for sharing your knowledge.",
          TalkActionId = {
            [1] = "210013:Think_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120155/1E146190"
        },
        [12015529] = {
          Camera = "63.533028,163.058304,86.610718,0.000035,20.601974,-118.808426,35.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Au fait, puisque vous prenez ce chemin... pourrais-je vous demander une chose ?",
          DialogueId = 12015529,
          FinalCamera = "80.940094,151.962341,86.610718,0.000031,20.202141,-123.608315,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E1461BA",
          NextDialogue = 12015530,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "One more thing — if you're heading that way, may I trouble you to watch for something on my behalf?",
          TalkActionId = {
            [1] = "210013:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120155/1E1461BA"
        },
        [12015530] = {
          ContentFR = "Je vous écoute.",
          DialogueId = 12015530,
          GUID = "1E1461E4",
          LookAt = {
            [1] = "100001:n(210040)"
          },
          NextDialogue = 12015531,
          SpeakNpcId = 100001,
          Subtitle = "Sure. What is it?",
          TalkActionId = {
            [1] = "100001:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E1461E4"
        },
        [12015531] = {
          Camera = "506.800385,633.872742,77.709961,0.000065,0.602477,-123.397171,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Peu avant votre arrivée, la Poussière-corrompue a atteint la Source de Yu. Certains Wishen ont disparu. On les a aperçus pour la dernière fois près de la cascade.",
          DialogueId = 12015531,
          FinalCamera = "543.195251,689.077759,77.014893,0.000065,0.60247,-123.397171,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E14620E",
          NextDialogue = 12015532,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Not long before you arrived, the Gritblight reached the Spring of Yu. Some of the little ones vanished — last seen near the waterfall.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1201/120155/1E14620E"
        },
        [12015532] = {
          Camera = "81.046371,94.984283,109.258301,0.000053,-23.95587,34.01368,45.000011,118.771225,false,Manual,8.928488",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Si vous les voyez en difficulté... je vous en prie, venez-leur en aide. Là-bas, un petit Wishen ne cesse d’en pleurer, jour et nuit.",
          DialogueId = 12015532,
          FinalCamera = "81.046371,94.984283,109.258301,0.000052,-25.15588,33.813671,45.000011,118.771225,false,Manual,8.928488",
          GUID = "1E146238",
          NextDialogue = 12015533,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Should you come across any of them trapped... please lend your aid. They have been weeping for days on end.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120155/1E146238"
        },
        [12015533] = {
          ContentFR = "Nous y veillerons.",
          DialogueId = 12015533,
          GUID = "1E146262",
          NextDialogue = 12015534,
          SpeakNpcId = 100001,
          Subtitle = "We'll keep an eye out.",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E146262"
        },
        [12015534] = {
          Camera = "121.226036,125.787674,88.543091,0.000051,19.601719,-140.008881,35.000015,480.381531,false,DoNotOverride,2.8",
          ContentFR = "Ha ha... alors filez. Le temps des vivants est précieux.",
          DialogueId = 12015534,
          FinalCamera = "146.449402,146.941391,76.819092,0.000051,19.601719,-140.008881,35.000015,480.381531,false,DoNotOverride,2.8",
          GUID = "1E14628C",
          NextDialogue = 12015535,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "Thank you. Then be on your way. The living mustn't squander their fleeting hours.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120155/1E14628C"
        },
        [12015535] = {
          Camera = "1428.752563,1073.151489,38.327271,0.000178,-0.197604,-141.396988,30.000002,1974.44458,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Quand cent ans auront passé... vous pourrez toujours revenir bavarder ici. Moi, j’ai tout mon temps. Je saurai attendre.",
          DialogueId = 12015535,
          FinalCamera = "1560.888916,1093.783447,38.735229,0.000178,-0.197604,-144.99707,30.000002,1974.44458,false,Manual,1.2",
          GUID = "1E1462B6",
          NextDialogue = 12015536,
          SnapShot = "WUYOU",
          SpeakNpcId = 210018,
          Subtitle = "When your time in the mortal world is done, you can always return — I will be waiting still for a proper catch-up.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120155/1E1462B6"
        },
        [12015536] = {
          Camera = "203.142548,172.754639,84.036987,0.000236,-41.194706,-124.995682,30.000013,127.563431,false,Manual,8.594169",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Il a peut-être raison, mais... pourquoi j’ai soudain la chair de poule ?! Ça me donne des frissons partout !",
          DialogueId = 12015536,
          FacialId = {
            [1] = "200002:Shock02"
          },
          FinalCamera = "215.009399,189.70047,102.144897,0.000229,-41.194721,-124.995827,30.000013,163.501831,false,Manual,8.594169",
          GUID = "1E1462E0",
          LookAt = {
            [1] = "200002:n(100001)",
            [2] = "100001:n(200002)"
          },
          NextDialogue = 12015537,
          SpeakNpcId = 200002,
          Subtitle = "Okay, that was... kind of spooky, even though he's got a point...",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "200002:n(100001)",
            [2] = "100001:n(200002)"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E1462E0"
        },
        [12015537] = {
          ContentFR = "Allez, petit larbin... on ne traîne pas !",
          DialogueId = 12015537,
          GUID = "1E14630A",
          SpeakNpcId = 200002,
          Subtitle = "Let's get going, Little Minion...!",
          TalkActionId = {
            [1] = "200002:Shy01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120155/1E14630A"
        },
        [12015601] = {
          Camera = "77.056641,185.4375,189.325562,0.000108,-31.7983,-71.775475,35.000011,290.254242,false,Manual,6.747885",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Tige pourpre, feuilles opposées, petites fleurs blanches... Oui. C’est bien elle.",
          DialogueId = 12015601,
          FinalCamera = "63.588379,226.34082,216.024658,0.000108,-31.798326,-71.775505,35.000011,290.254242,false,Manual,6.747885",
          GUID = "1E146D8A",
          NextDialogue = 12015602,
          Scripts = [[
SEQ{
LookAt{_delay{4.1},LookAtDescription{"210013:n(100001)"}},
TurnTo{TurnToDescription{"210013:n(100001)"}}
}]],
          SpeakNpcId = 210013,
          Subtitle = "Crimson stalks, paired leaves, tiny white blossoms... Yes. This is Wangyou.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120156/1E146D8A"
        },
        [12015602] = {
          Camera = "1049.913574,-119.71582,311.329102,0.0001,-14.398373,162.820862,30.0,248.711517,false,DoNotOverride,6.747885",
          ContentFR = "{nickname}, Snow... vous me donnez un coup de main ? Avant que la rosée ne se dissipe, il me faut dix brins d’Herbe de l’Oubli.",
          DialogueId = 12015602,
          Duration = 1,
          FinalCamera = "1015.789062,-208.617188,311.329102,0.000098,-13.998349,157.021118,30.0,248.711517,false,DoNotOverride,6.747885",
          GUID = "1E146DB4",
          NextDialogue = 12015603,
          Scripts = [[
PARA{
PlayAnimation{_delay{4.1},ActorId{210013},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{_delay{1.1},ActorId{100001},AnimationId{"Shy02_Start"},Duration{1}}
}]],
          SpeakNpcId = 210013,
          Subtitle = ", Snow — could you lend a hand? Before the dew vanishes, I need ten fresh sprigs of Wangyou.",
          TalkActionId = {
            [1] = "210013:Talk02_Start"
          },
          ToFinalCameraBlendTime = 18,
          VoiceName = "voice/$Locale$/story/1201/120156/1E146DB4"
        },
        [12015603] = {
          Camera = "60.763,225.503906,204.802368,0.000088,-28.598343,-74.769676,30.0,117.073692,false,Manual,6.747885",
          ContentFR = "Choisis celles qui sont en pleine floraison, avec des racines vives : leur vertu sera meilleure.",
          DialogueId = 12015603,
          FinalCamera = "73.483093,228.381836,204.802368,0.000087,-28.798365,-81.168892,30.0,117.073692,false,Manual,6.747885",
          GUID = "1E146DDE",
          LookAt = {
            [1] = "210013:n(200002)"
          },
          NextDialogue = 12015604,
          SpeakNpcId = 210013,
          Subtitle = "Focus on the ones in full bloom, with vibrant roots — they will be the most potent.",
          TalkActionId = {
            [1] = "210013:Shy03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120156/1E146DDE"
        },
        [12015604] = {
          Camera = "315.013123,-16.664062,87.76709,0.000089,7.94519,113.863701,40.000011,248.711517,false,DoNotOverride,6.747885",
          ContentFR = "Bien reçu ! Compte sur nous !",
          DialogueId = 12015604,
          FinalCamera = "307.165344,-20.133789,87.76709,0.000089,7.94519,113.863922,40.000011,248.711517,false,DoNotOverride,6.747885",
          GUID = "1E146E08",
          Scripts = [[
PARA{
LookAt{_delay{1.1},LookAtDescription{"100001:n(200002)"}},
LookAt{_delay{2.1},LookAtDescription{"200002:n(100001)"}},
PlayAnimation{_delay{2.5},ActorId{100001},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "You got it!",
          TalkActionId = {
            [1] = "200002:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120156/1E146E08"
        },
        [12015701] = {
          ContentFR = "Hé— ! Petit larbin, viens vite voir par ici !",
          DialogueId = 12015701,
          Duration = 3,
          GUID = "1E147DF2",
          SpeakNpcId = 200002,
          Subtitle = "Hey— Little Minion! Come over here a sec!",
          VoiceName = "voice/$Locale$/story/1201/120157/1E147DF2"
        },
        [12015801] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dis donc, est-ce que c’est moi qui hallucine ? Petit larbin, viens confirmer pour moi... Tu n’entends rien, par ici ?",
          DialogueId = 12015801,
          GUID = "1E148E5A",
          NextDialogue = 12015802,
          RelatedWikiId = {
            [1] = 408013,
            [2] = 303012,
            [3] = 203006
          },
          SpeakNpcId = 200002,
          Subtitle = "...Am I hearing things? Little Minion, come here and check — did a voice come from this way?",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148E5A"
        },
        [12015802] = {
          ContentFR = "D’accord.",
          DialogueId = 12015802,
          GUID = "1E148E84",
          NextDialogue = 12015803,
          SpeakNpcId = 100001,
          Subtitle = "Alright.",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148E84"
        },
        [12015803] = {
          ContentFR = "... À l’aide... à l’aide...",
          DialogueId = 12015803,
          GUID = "1E148EAE",
          NextDialogue = 12015804,
          SnapShot = "MEMORY",
          SpeakNpcId = 210028,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Save me... save me...",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148EAE"
        },
        [12015804] = {
          ContentFR = "J’entends quelqu’un. On dirait une personne qui appelle à l’aide.",
          DialogueId = 12015804,
          GUID = "1E148ED8",
          NextDialogue = 12015805,
          SpeakNpcId = 100001,
          Subtitle = "There is a voice — someone calling for help.",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148ED8"
        },
        [12015805] = {
          ContentFR = "Elle a dit... « tonton » ? Elle cherche sa famille, elle aussi ?",
          DialogueId = 12015805,
          GUID = "1E148F02",
          NextDialogue = 12015806,
          SpeakNpcId = 200002,
          Subtitle = "Did she say... \"Baby\"? ...Is she calling out for someone she loves?",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148F02"
        },
        [12015806] = {
          ContentFR = "Je ne peux pas... disparaître... Il me reste...",
          DialogueId = 12015806,
          GUID = "1E148F2C",
          NextDialogue = 12015807,
          SnapShot = "MEMORY",
          SpeakNpcId = 210028,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Can't disappear... I still have to...",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148F2C"
        },
        [12015807] = {
          ContentFR = "Avant... que... laisse-moi...",
          DialogueId = 12015807,
          GUID = "1E148F56",
          NextDialogue = 12015808,
          SnapShot = "MEMORY",
          SpeakNpcId = 210028,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Before it's too late... let me...",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148F56"
        },
        [12015808] = {
          ContentFR = "Tu vois, tu vois ! Je n’ai pas rêvé ! Évidemment ! Les oreilles du grand Roi Démon captent même les murmures les plus discrets des Asphodèles !",
          DialogueId = 12015808,
          GUID = "1E148F80",
          NextDialogue = 12015809,
          SpeakNpcId = 200002,
          Subtitle = "See? I knew I wasn't hearing things! Ha — never doubt this Demon King's ears. Sharp enough to catch whispers in every corner of The Asphodel!",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148F80"
        },
        [12015809] = {
          ContentFR = "Je prends note. La prochaine fois que j’aurai un secret, je t’enverrai marcher très loin devant.",
          DialogueId = 12015809,
          GUID = "1E148FAA",
          NextDialogue = 12015810,
          SpeakNpcId = 100001,
          Subtitle = "Duly noted. Next time I've got a secret to keep, I'll make sure you're nowhere nearby.",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148FAA"
        },
        [12015810] = {
          ContentFR = "Hé ! C’est vraiment méchant !",
          DialogueId = 12015810,
          GUID = "1E148FD4",
          NextDialogue = 12015811,
          SpeakNpcId = 200002,
          Subtitle = "Hey! Not cool, Little Minion!",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148FD4"
        },
        [12015811] = {
          ContentFR = "Mais au fait, cette voix... d’où elle vient ? Et comment est-ce qu’on est censés la retrouver ?",
          DialogueId = 12015811,
          GUID = "1E148FFE",
          SpeakNpcId = 200002,
          Subtitle = "Still... where's that voice coming from? And how do we even start looking for them?",
          VoiceName = "voice/$Locale$/story/1201/120158/1E148FFE"
        },
        [12015901] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Petit larbin ! C’était quoi, ce bruit ?!",
          DialogueId = 12015901,
          GUID = "1E149EC2",
          NextDialogue = 12015902,
          RelatedWikiId = {
            [1] = 408013,
            [2] = 303012,
            [3] = 203006
          },
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, what was that noise?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149EC2"
        },
        [12015902] = {
          ContentFR = "Petit larbin ? ... Petit larbin ?! ... {nickname} ?!",
          DialogueId = 12015902,
          GUID = "1E149EEC",
          NextDialogue = 12015903,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion...? Little Minion!  — what's wrong!?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149EEC"
        },
        [12015903] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hé— hé, parle-moi... !",
          DialogueId = 12015903,
          GUID = "1E149F16",
          NextDialogue = 12015904,
          SpeakNpcId = 200002,
          Subtitle = "Say something...!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149F16"
        },
        [12015904] = {
          ContentFR = "Qu’est-ce que je fais... Fushu ! Fushu, catastrophe— !",
          DialogueId = 12015904,
          GUID = "1E149F40",
          NextDialogue = 12015905,
          SpeakNpcId = 200002,
          Subtitle = "Oh no... oh no — Fushu! Fushu, something's really wrong—!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149F40"
        },
        [12015905] = {
          ContentFR = "Que se passe-t-il ?",
          DialogueId = 12015905,
          GUID = "1E149F6A",
          NextDialogue = 12015906,
          SpeakNpcId = 210013,
          Subtitle = "What happened?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149F6A"
        },
        [12015906] = {
          ContentFR = "Bouhou... Il y avait quelqu’un qui parlait d’un endroit invisible... On est allés voir, et là— un flash ! « <I>Ziiip</> » ! Et mon petit larbin est devenu tout... tout figé !",
          DialogueId = 12015906,
          GUID = "1E149F94",
          NextDialogue = 12015907,
          SpeakNpcId = 200002,
          Subtitle = "Waaah... There was a voice, coming from somewhere we couldn't see, so we went to look... and then all of a sudden — there was this flash and a fwoosh, and my Little Minion just... froze up!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149F94"
        },
        [12015907] = {
          ContentFR = "J’ai beau l’appeler, {性别:il|elle} ne répond pas... Comme si son âme avait été arrachée !",
          DialogueId = 12015907,
          GUID = "1E149FBE",
          NextDialogue = 12015908,
          SpeakNpcId = 200002,
          Subtitle = "I called {性别:his|her} name many times, but {性别:he|she} just stood there like a statue — like {性别:his|her} soul's been snatched away!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149FBE"
        },
        [12015908] = {
          ContentFR = "Snow, calme-toi. L’agitation n’aidera en rien. Respire. Je suis là.",
          DialogueId = 12015908,
          GUID = "1E149FE8",
          NextDialogue = 12015910,
          SpeakNpcId = 210013,
          Subtitle = "Take a breath, Snow. Panic will only cloud your thoughts. Don't worry, I'm here with you.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E149FE8"
        },
        [12015910] = {
          ContentFR = "Tu dis que... la dernière fois que {nickname} allait bien, c’était ici ?",
          DialogueId = 12015910,
          GUID = "1E14A03C",
          NextDialogue = 12015912,
          SpeakNpcId = 210013,
          Subtitle = "So... the last place you saw  before {性别:he|she} froze — was right here?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A03C"
        },
        [12015912] = {
          ContentFR = "C’est quoi, ce truc ?! {nickname} n’est pas en danger, hein ?!",
          DialogueId = 12015912,
          GUID = "1E14A090",
          NextDialogue = 12015913,
          SpeakNpcId = 200002,
          Subtitle = "What is that!? Is  going to be okay!?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A090"
        },
        [12015913] = {
          ContentFR = "Si je ne me trompe pas... son esprit a été englouti par la <H>Faille de l’Oubli</>.",
          DialogueId = 12015913,
          GUID = "1E14A0BA",
          NextDialogue = 12015914,
          RelatedWikiId = {
            [1] = 304008
          },
          SpeakNpcId = 210013,
          Subtitle = "If I'm not mistaken, {性别:his|her} spirit has been swallowed by a place known as the Oblivion Rift.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A0BA"
        },
        [12015914] = {
          ContentFR = "La Faille de l’Oubli... ?! Rien que le nom fait peur ! C’est quoi, exactement ?",
          DialogueId = 12015914,
          GUID = "1E14A0E4",
          NextDialogue = 12015915,
          SpeakNpcId = 200002,
          Subtitle = "The Oblivion Rift...? That sounds awful! What is it?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A0E4"
        },
        [12015915] = {
          ContentFR = "Si la Source de Yu est un monde tissé des attachements humains... alors, corrompue par le Fléau de Zhuyin, elle engendre la Faille de l’Oubli. Un lieu sans lumière, où souvenirs et conscience se dissolvent.",
          DialogueId = 12015915,
          GUID = "1E14A10E",
          NextDialogue = 12015916,
          SpeakNpcId = 210013,
          Subtitle = "The Spring of Yu is a realm woven from human yearning, and the Oblivion Rift is its shadow — born of Zhuyin's corruption. It is a lightless void where all memory is consumed and undone.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A10E"
        },
        [12015916] = {
          ContentFR = "Quiconque y chute doit en ressortir dans l’heure suivant son apparition. Passé ce délai... l’âme s’y perd à jamais, sans retour possible.",
          DialogueId = 12015916,
          GUID = "1E14A138",
          NextDialogue = 12015917,
          SpeakNpcId = 210013,
          Subtitle = "Anyone who falls in must find their way out within one hour of the Rift's birth. If they do not... their soul will be lost forever, with no path home.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A138"
        },
        [12015917] = {
          ContentFR = "Alors... alors qu’est-ce qu’on fait ?!",
          DialogueId = 12015917,
          GUID = "1E14A162",
          NextDialogue = 12015918,
          SpeakNpcId = 200002,
          Subtitle = "Then what do we do...!?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A162"
        },
        [12015918] = {
          ContentFR = "Ne panique pas. J’y vais maintenant pour {性别:le|la} ramener. Reste ici et attends-nous.",
          DialogueId = 12015918,
          GUID = "1E14A18C",
          NextDialogue = 12015919,
          SpeakNpcId = 210013,
          Subtitle = "Don't be afraid. I will go in and bring {性别:him|her} back. Stay here and wait for us.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A18C"
        },
        [12015919] = {
          ContentFR = "... Je viens avec toi !",
          DialogueId = 12015919,
          GUID = "1E14A1B6",
          NextDialogue = 12015920,
          SpeakNpcId = 200002,
          Subtitle = "...I'm coming with you!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A1B6"
        },
        [12015920] = {
          ContentFR = "Non. La Faille est extrêmement dangereuse. Si toi aussi tu t’y perds, la situation deviendra incontrôlable.",
          DialogueId = 12015920,
          GUID = "1E14A1E0",
          NextDialogue = 12015921,
          SpeakNpcId = 210013,
          Subtitle = "No, it's far too perilous. If you were to be lost as well... it would only make things worse.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A1E0"
        },
        [12015921] = {
          ContentFR = "Mais... mais rester ici à attendre, sans rien savoir... sans savoir comment va mon petit larbin... c’est insupportable...",
          DialogueId = 12015921,
          GUID = "1E14A20A",
          NextDialogue = 12015922,
          SpeakNpcId = 200002,
          Subtitle = "But... but I don't want to just wait here doing nothing! Not knowing what's happening in there... or if my Little Minion is safe...",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A20A"
        },
        [12015922] = {
          ContentFR = "<I>Bouhou...</> c’est trop dur...",
          DialogueId = 12015922,
          GUID = "1E14A234",
          NextDialogue = 12015923,
          SpeakNpcId = 200002,
          Subtitle = "I can't take it... Waaaah!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A234"
        },
        [12015923] = {
          ContentFR = "Snow... viens. Donne-moi la main.",
          DialogueId = 12015923,
          GUID = "1E14A25E",
          NextDialogue = 12015924,
          SpeakNpcId = 210013,
          Subtitle = "Snow, come here. Give me your hand.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A25E"
        },
        [12015924] = {
          ContentFR = "Hein ? C’est quoi, ça... ?",
          DialogueId = 12015924,
          GUID = "1E14A288",
          NextDialogue = 12015925,
          SpeakNpcId = 200002,
          Subtitle = "Huh? What is this?",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A288"
        },
        [12015925] = {
          ContentFR = "Ma sœur disait toujours : « Quand un remède est amer, une douceur aide à le supporter. » Je pense que pour le cœur, c’est pareil.",
          DialogueId = 12015925,
          GUID = "1E14A2B2",
          NextDialogue = 12015926,
          SpeakNpcId = 210013,
          Subtitle = "My sister once said, \"When potion is bitter, chase it with something sweet.\" I believe hearts work the same way.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A2B2"
        },
        [12015926] = {
          ContentFR = "Ne pleure plus, d’accord ? Je te promets de revenir avec {nickname}, {性别:sain et sauf|saine et sauve}. C’est une promesse.",
          DialogueId = 12015926,
          GUID = "1E14A2DC",
          NextDialogue = 12015927,
          SpeakNpcId = 210013,
          Subtitle = "So no more tears, alright? I'll bring {性别:him|her} back safe and sound. I promise.",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A2DC"
        },
        [12015927] = {
          ContentFR = "A-alors... dépêche-toi ! Je surveille cette vilaine fissure ! Pas question qu’elle se referme !",
          DialogueId = 12015927,
          GUID = "1E14A306",
          NextDialogue = 12015928,
          SpeakNpcId = 200002,
          Subtitle = "Then... then go already! I'll keep an eye on this creepy rift — no way I'm letting it shut!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A306"
        },
        [12015928] = {
          ContentFR = "Je passe mon temps à dire que je suis le Roi Démon... et je n’arrive même pas à protéger mon petit larbin...",
          DialogueId = 12015928,
          GUID = "1E14A330",
          NextDialogue = 12015929,
          SpeakNpcId = 200002,
          Subtitle = "I go around telling everyone I'm the Demon King... and I can't even protect my own Little Minion...",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A330"
        },
        [12015929] = {
          ContentFR = "Espèce de truc moche ! Je te surveille, alors ne bouge pas d’un poil !",
          DialogueId = 12015929,
          GUID = "1E14A35A",
          NextDialogue = 12015930,
          SpeakNpcId = 200002,
          Subtitle = "You evil rift thing — don't you dare close up! I'm watching you!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A35A"
        },
        [12015930] = {
          ContentFR = "Et toi, imbécile de larbin... reviens-moi en pleine forme ! Sinon je te condamne à travailler pour Camilla pendant un an— non, dix— non, cent ans !",
          DialogueId = 12015930,
          GUID = "1E14A384",
          SpeakNpcId = 200002,
          Subtitle = "And you — stupid Little Minion — you'd better come back in one piece! Or else I'll have you waiting tables for Camilla for a year — no, ten — no, a hundred years!",
          VoiceName = "voice/$Locale$/story/1201/120159/1E14A384"
        },
        [12016001] = {
          ContentFR = "<I>Où suis-je... ?</>",
          DialogueId = 12016001,
          Duration = 2,
          GUID = "1E14AF2A",
          NextDialogue = 12016002,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Where... am I?)",
          VoiceName = "voice/$Locale$/story/1201/120160/1E14AF2A"
        },
        [12016002] = {
          ContentFR = "<I>Il n’y a personne. Aucun bruit. Un silence si profond que je n’entends plus que les battements de mon propre cœur...</>",
          DialogueId = 12016002,
          Duration = 3,
          GUID = "1E14AF54",
          NextDialogue = 12016003,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(No one's here. Not a sound. It's so still I can hear my own heartbeat...)",
          VoiceName = "voice/$Locale$/story/1201/120160/1E14AF54"
        },
        [12016003] = {
          ContentFR = "<I>Comme si j’étais revenu à l’origine même où le sable blanc s’écoule... comme si rien de tout cela n’avait jamais existé.</>",
          DialogueId = 12016003,
          Duration = 3,
          GUID = "1E14AF7E",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(It's as if... I'm back where it all began. Where the white sand flows from the sky. As though nothing ever happened.)",
          VoiceName = "voice/$Locale$/story/1201/120160/1E14AF7E"
        },
        [12016101] = {
          ContentFR = "{nickname}... Est-ce que tu entends ma voix ?",
          DialogueId = 12016101,
          Duration = 3,
          GUID = "1E14BF92",
          NextDialogue = 12016102,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Can you hear me, ?",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14BF92"
        },
        [12016102] = {
          ContentFR = "Fushu ? C’est toi ? Où est-ce que tu te trouves ?!",
          DialogueId = 12016102,
          Duration = 2,
          GUID = "1E14BFBC",
          NextDialogue = 12016103,
          SpeakNpcId = 100001,
          Subtitle = "Fushu? Is that you? Where are you!?",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14BFBC"
        },
        [12016103] = {
          ContentFR = "Il y a une distance entre nous. Mais cet endroit est un domaine particulier : ici, les pensées peuvent se rejoindre, au-delà des corps. C’est ainsi que je peux te voir... et te parler.",
          DialogueId = 12016103,
          Duration = 5,
          GUID = "1E14BFE6",
          NextDialogue = 12016104,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "There lies a distance between us in the mortal realm. Yet this place is not bound by such constraints. Here, thoughts connect — I can see you, and my voice may find you.",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14BFE6"
        },
        [12016104] = {
          ContentFR = "N’aie crainte. Tout va bien désormais. Je vais te guider hors d’ici, et te ramener vers un lieu sûr.",
          DialogueId = 12016104,
          Duration = 4,
          GUID = "1E14C010",
          NextDialogue = 12016105,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Do not fear. You are safe here. I shall guide you back to where you belong.",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14C010"
        },
        [12016105] = {
          ContentFR = "... D’accord. Je comprends.",
          DialogueId = 12016105,
          Duration = 2,
          GUID = "1E14C03A",
          SpeakNpcId = 100001,
          Subtitle = "...Okay. I understand.",
          VoiceName = "voice/$Locale$/story/1201/120161/1E14C03A"
        },
        [12016201] = {
          ContentFR = "Vois-tu ces Fleurs-lanternes ? Les vivants confient leurs prières à des lanternes flottantes, qu’ils laissent dériver sur des eaux profondes et silencieuses, dans l’espoir que leurs pensées atteignent le royaume des morts.",
          DialogueId = 12016201,
          Duration = 4,
          GUID = "1E14CFFA",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Do you see those lantern blossoms? The living send forth their prayers upon them, setting them adrift in deep, silent waters — hoping they might reach those who have departed.",
          VoiceName = "voice/$Locale$/story/1201/120162/1E14CFFA"
        },
        [12016202] = {
          ContentFR = "La lueur de ces flammes te protégera... et empêchera la Faille de l’Oubli de t’éroder.",
          DialogueId = 12016202,
          Duration = 3,
          GUID = "1E14D024",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Their gentle light shall shield you from the oblivion's creeping grasp.",
          VoiceName = "voice/$Locale$/story/1201/120162/1E14D024"
        },
        [12016251] = {
          ContentFR = "Fushu... comment est-ce que je peux sortir d’ici ?",
          DialogueId = 12016251,
          Duration = 3,
          GUID = "1E14D026",
          NextDialogue = 12016303,
          SpeakNpcId = 100001,
          Subtitle = "How am I supposed to leave here, Fushu?",
          VoiceName = "voice/$Locale$/story/1201/120162/1E14D026"
        },
        [12016301] = {
          ContentFR = "Prends garde à la rivière qui t’entoure. C’est le Fleuve de l’Oubli — celui qui efface l’existence. Si ses eaux te touchent, ton être s’amenuisera peu à peu... et ton désir de vivre s’éteindra.",
          DialogueId = 12016301,
          Duration = 3,
          GUID = "1E14E062",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Beware the river that lies close at hand. That is Lethe — the River of Forgetting. Should its waters touch you, your sense of self will begin to fade, and your will to live shall wane.",
          VoiceName = "voice/$Locale$/story/1201/120163/1E14E062"
        },
        [12016302] = {
          ContentFR = "... Mais il n’y a que de l’eau autour de moi. Il n’y a plus de chemin. Que dois-je faire ?",
          DialogueId = 12016302,
          Duration = 3,
          GUID = "1E14E08C",
          SpeakNpcId = 100001,
          Subtitle = "...But there's water everywhere. There's no path forward. What do I do?",
          VoiceName = "voice/$Locale$/story/1201/120163/1E14E08C"
        },
        [12016303] = {
          ContentFR = "{nickname}, existe-t-il un vœu que tu dois absolument accomplir, quoi qu’il arrive ?",
          DialogueId = 12016303,
          Duration = 3,
          GUID = "1E14E0B6",
          NextDialogue = 12016401,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = ", do you bear a wish that you must see fulfilled, no matter the cost?",
          VoiceName = "voice/$Locale$/story/1201/120163/1E14E0B6"
        },
        [12016304] = {
          ContentFR = "C’est ce vœu qui te relie encore à ce monde. Fais face au Carillon des Vents devant toi... et murmure-le en silence.",
          DialogueId = 12016304,
          Duration = 3,
          GUID = "1E14E0E0",
          NextDialogue = 12016305,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "That wish is your tether to this world. Face the Aeolian Chime that stands before you, and let that wish take shape upon your mind.",
          VoiceName = "voice/$Locale$/story/1201/120163/1E14E0E0"
        },
        [12016305] = {
          ContentFR = "Il appellera le vent, portera ton attachement vers des hauteurs lointaines... et t’aidera à regagner le monde des vivants.",
          DialogueId = 12016305,
          Duration = 3,
          GUID = "1E14E10A",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "It shall call to the wind — carrying your wish to the heights, and guiding you back to the land of the living.",
          VoiceName = "voice/$Locale$/story/1201/120163/1E14E10A"
        },
        [12016401] = {
          ContentFR = "<I>Quelque chose que je dois accomplir... coûte que coûte.</>",
          DialogueId = 12016401,
          Duration = 2,
          GUID = "1E14F0CA",
          NextDialogue = 12016402,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Something I must do no matter the cost...)",
          VoiceName = "voice/$Locale$/story/1201/120164/1E14F0CA"
        },
        [12016402] = {
          ContentFR = "<I>Berry m’attend encore... Je dois la sauver. Je ne peux pas m’arrêter ici.</>",
          DialogueId = 12016402,
          Duration = 3,
          GUID = "1E14F0F4",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Berry is still waiting for me... I have to bring her back. I can't stop here!)",
          VoiceName = "voice/$Locale$/story/1201/120164/1E14F0F4"
        },
        [12016501] = {
          ContentFR = "... Les lumières s’allument. C’est... magnifique.",
          DialogueId = 12016501,
          Duration = 2,
          GUID = "1E150132",
          NextDialogue = 12016502,
          SpeakNpcId = 100001,
          Subtitle = "...! The lanterns lit up. How beautiful.",
          VoiceName = "voice/$Locale$/story/1201/120165/1E150132"
        },
        [12016502] = {
          ContentFR = "Les flammes des Lanternes célestes devraient pouvoir éveiller les Fleurs-lanternes... et ouvrir devant toi un nouveau passage.",
          DialogueId = 12016502,
          Duration = 3,
          GUID = "1E15015C",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "The flames of the sky lanterns shall awaken the blossoms ahead, lighting the path for your return.",
          VoiceName = "voice/$Locale$/story/1201/120165/1E15015C"
        },
        [12016601] = {
          ContentFR = "{nickname}... c’est toi ?",
          DialogueId = 12016601,
          Duration = 2,
          GUID = "1E15119A",
          NextDialogue = 12016602,
          SnapShot = "ECHO",
          SpeakNpcId = 210024,
          Subtitle = ", is that you?",
          TalkActionId = {
            [1] = "210024:Explain01_Start"
          },
          TurnTo = {
            [1] = "210024:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1201/120166/1E15119A"
        },
        [12016602] = {
          ContentFR = "... Berry !",
          DialogueId = 12016602,
          Duration = 2,
          GUID = "1E1511C4",
          NextDialogue = 12016603,
          SpeakNpcId = 100001,
          Subtitle = "...Berry!",
          TalkActionId = {
            [1] = "210024:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120166/1E1511C4"
        },
        [12016603] = {
          ContentFR = "Nous nous reverrons. J’en suis certaine. D’ici là... prends soin de toi. Ne te blesse pas.",
          DialogueId = 12016603,
          Duration = 3,
          GUID = "1E1511EE",
          NextDialogue = 12016604,
          SnapShot = "ECHO",
          SpeakNpcId = 210024,
          Subtitle = "We'll definitely meet again. Until then, take good care of yourself and stay safe.",
          TalkActionId = {
            [1] = "210024:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120166/1E1511EE"
        },
        [12016604] = {
          ContentFR = "Avance maintenant. Ne t’arrête pas. Je veillerai toujours sur ton chemin.",
          DialogueId = 12016604,
          Duration = 3,
          GUID = "1E151218",
          SnapShot = "ECHO",
          SpeakNpcId = 210024,
          Subtitle = "Keep going forward now. I'll always be watching over you.",
          TalkActionId = {
            [1] = "210024:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120166/1E151218"
        },
        [12016701] = {
          ContentFR = "C’est elle... la « famille » dont tu m’as parlé.",
          DialogueId = 12016701,
          Duration = 2,
          GUID = "1E152202",
          NextDialogue = 12016702,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "She is the family you have sought so long to find, right?",
          VoiceName = "voice/$Locale$/story/1201/120167/1E152202"
        },
        [12016702] = {
          ContentFR = "Je dois toutefois te prévenir : ce que tu viens de voir n’est qu’une forme née du vœu et du souvenir... pas la véritable personne.",
          DialogueId = 12016702,
          Duration = 3,
          GUID = "1E15222C",
          NextDialogue = 12016703,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Yet I must tell you this — what you beheld was but a wisp of longing, not her true form.",
          VoiceName = "voice/$Locale$/story/1201/120167/1E15222C"
        },
        [12016703] = {
          ContentFR = "Je le sais.",
          DialogueId = 12016703,
          Duration = 2,
          GUID = "1E152256",
          NextDialogue = 12016704,
          SpeakNpcId = 100001,
          Subtitle = "I understand.",
          VoiceName = "voice/$Locale$/story/1201/120167/1E152256"
        },
        [12016704] = {
          ContentFR = "Même ainsi... la voir ici, croire qu’elle m’attend quelque part dans ce monde... ça m’apaise. Ça me donne la force d’avancer.",
          DialogueId = 12016704,
          Duration = 4,
          GUID = "1E152280",
          SpeakNpcId = 100001,
          Subtitle = "But even so... to see her here, to believe she is waiting for me somewhere in this world... it brings me solace. It gives me strength.",
          VoiceName = "voice/$Locale$/story/1201/120167/1E152280"
        },
        [12016801] = {
          ContentFR = "Encore un Carillon des Vents. Tu sais ce qu’il te reste à faire, {nickname}.",
          DialogueId = 12016801,
          Duration = 3,
          GUID = "1E15326A",
          NextDialogue = 12016802,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "Another Aeolian Chime. You know what must be done, .",
          VoiceName = "voice/$Locale$/story/1201/120168/1E15326A"
        },
        [12016802] = {
          ContentFR = "<I>Je dois rentrer {性别:sain et sauf|saine et sauve} à Givrelac... Tout le monde m’y attend. Je ne peux pas m’arrêter maintenant.</>",
          DialogueId = 12016802,
          Duration = 3,
          GUID = "1E153294",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(I must make it back to Icelake safely. Everyone's still waiting for me. I can't stop now!)",
          VoiceName = "voice/$Locale$/story/1201/120168/1E153294"
        }
      }
    end
  },
  {
    MinKey = 12016901,
    MaxKey = 12019305,
    Loader = function()
      return {
        [12016901] = {
          ContentFR = "Ça fait longtemps, {nickname}.",
          DialogueId = 12016901,
          Duration = 2,
          GUID = "1E1542D2",
          NextDialogue = 12016902,
          SnapShot = "ECHO",
          SpeakNpcId = 210025,
          Subtitle = "It's been a long time, .",
          TalkActionId = {
            [1] = "210024:Explain02_Start"
          },
          TurnTo = {
            [1] = "210025:n(0)"
          },
          VoiceName = "voice/$Locale$/story/1201/120169/1E1542D2"
        },
        [12016902] = {
          ContentFR = "Tu es allé loin, n’est-ce pas ? Un endroit étrange, nouveau... que je ne connaîtrai sans doute jamais.",
          DialogueId = 12016902,
          Duration = 3,
          GUID = "1E1542FC",
          NextDialogue = 12016903,
          SnapShot = "ECHO",
          SpeakNpcId = 210025,
          Subtitle = "Have you gone somewhere new and different? A place that I've never heard of?",
          TalkActionId = {
            [1] = "210024:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120169/1E1542FC"
        },
        [12016903] = {
          ContentFR = "Quand tu reviendras à Givrelac... si tu en as envie... tu me raconteras ?",
          DialogueId = 12016903,
          Duration = 3,
          GUID = "1E154326",
          NextDialogue = 12016904,
          SnapShot = "ECHO",
          SpeakNpcId = 210025,
          Subtitle = "Could you tell me about it when you come back to Icelake?",
          TalkActionId = {
            [1] = "210024:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120169/1E154326"
        },
        [12016904] = {
          ContentFR = "Je sais que c’est peut-être égoïste... mais s’il te plaît, ne m’oublie pas.",
          DialogueId = 12016904,
          GUID = "1E154350",
          SnapShot = "ECHO",
          SpeakNpcId = 210025,
          Subtitle = "I know it's kind of way too much to ask, but... please don't forget about me.",
          VoiceName = "voice/$Locale$/story/1201/120169/1E154350"
        },
        [12017001] = {
          ContentFR = "Petit larbin ! Dépêche-toi ! Pourquoi tu traînes comme ça ? Le Roi Démon a encore un monde entier à conquérir avec toi !",
          DialogueId = 12017001,
          Duration = 4,
          GUID = "1E15533A",
          NextDialogue = 12017002,
          SnapShot = "MEMORY",
          SpeakNpcId = 200002,
          SpeakNpcName = "UI_CMName_Name_BaiPhantom",
          Subtitle = "Hurry up, Little Minion! The Demon King still needs your help to conquer the world!",
          VoiceName = "voice/$Locale$/story/1201/120170/1E15533A"
        },
        [12017002] = {
          ContentFR = "Où est-ce que tu t’es encore {性别:fourré|fourrée} ? Reviens vite... Fina attend toujours tes histoires.",
          DialogueId = 12017002,
          GUID = "1E155364",
          SnapShot = "MEMORY",
          SpeakNpcId = 100401,
          SpeakNpcName = "UI_CMName_Name_AotePhantom",
          Subtitle = "Where on earth have you gone? It's making it so hard to find you. Come back soon — Fina still wants to hear stories from you.",
          VoiceName = "voice/$Locale$/story/1201/120170/1E155364"
        },
        [12017003] = {
          ContentFR = "Ne va pas te casser une jambe dehors. Quand tu auras fini ton travail, rentre aux Asphodèles. Je t’ai gardé une boisson chaude — mais elle ne t’attendra pas éternellement.",
          DialogueId = 12017003,
          Duration = 3,
          GUID = "1E15538E",
          NextDialogue = 12017004,
          SnapShot = "MEMORY",
          SpeakNpcId = 200003,
          SpeakNpcName = "UI_CMName_Name_KamiPhantom",
          Subtitle = "Mind you don't go breaking a leg out there. I've saved you a hot drink, but it won't stay warm forever. Just head back to The Asphodel once you're done with your business.",
          VoiceName = "voice/$Locale$/story/1201/120170/1E15538E"
        },
        [12017004] = {
          ContentFR = "Gagner sa vie, c’est important. Mais si on a l’argent sans le temps de le vivre... à quoi bon ?",
          DialogueId = 12017004,
          Duration = 3,
          GUID = "1E1553B8",
          SnapShot = "MEMORY",
          SpeakNpcId = 200003,
          Subtitle = "Earning your keep's one thing, but it's pointless if you don't have the time to enjoy it.",
          VoiceName = "voice/$Locale$/story/1201/120170/1E1553B8"
        },
        [12017005] = {
          ContentFR = "On dirait que beaucoup de personnes tiennent à toi... que tu as tissé de nombreux liens. C’est une belle chose.",
          DialogueId = 12017005,
          Duration = 3,
          GUID = "1E1553E2",
          NextDialogue = 12017006,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "It seems there are many who care for you, who've formed bonds of rare and precious worth. This is nice.",
          VoiceName = "voice/$Locale$/story/1201/120170/1E1553E2"
        },
        [12017006] = {
          ContentFR = "La sortie est juste devant. Traverse le Fleuve de l’Oubli... puis emprunte le Pont du Retour. Il te ramènera sur l’autre rive.",
          DialogueId = 12017006,
          GUID = "1E15540C",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "The way out lies just ahead. Cross the Lethe, then step onto the Bridge of Forgetfulness — it will carry you back to the living world.",
          VoiceName = "voice/$Locale$/story/1201/120170/1E15540C"
        },
        [12017101] = {
          ContentFR = "... Ouf. {nickname} est {性别:sain et sauf|saine et sauve}.",
          DialogueId = 12017101,
          Duration = 3,
          GUID = "1E1563A2",
          NextDialogue = 12017102,
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "...Phew.  is safe now.",
          VoiceName = "voice/$Locale$/story/1201/120171/1E1563A2"
        },
        [12017102] = {
          ContentFR = "Le lien entre la Faille de l’Oubli et ce monde est en train de se refermer... je dois sortir au plus vite.",
          DialogueId = 12017102,
          Duration = 3,
          GUID = "1E1563CC",
          SnapShot = "MEMORY",
          SpeakNpcId = 210013,
          Subtitle = "The link between the Oblivion Rift and this world is growing faint... I must hurry and leave.",
          VoiceName = "voice/$Locale$/story/1201/120171/1E1563CC"
        },
        [12017201] = {
          ContentFR = "Yi.... ya...",
          DialogueId = 12017201,
          GUID = "1E15740A",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee-ee-ya—",
          VoiceName = "voice/$Locale$/story/1201/120172/1E15740A"
        },
        [12017202] = {
          ContentFR = "Petit être... que fais-tu ici... ?",
          DialogueId = 12017202,
          GUID = "1E157434",
          NextDialogue = 12017203,
          SpeakNpcId = 210013,
          Subtitle = "Little one, what brings you here...?",
          VoiceName = "voice/$Locale$/story/1201/120172/1E157434"
        },
        [12017203] = {
          ContentFR = "Yi-ya... yi !",
          DialogueId = 12017203,
          GUID = "1E15745E",
          NextDialogue = 12017204,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee-ya, ee!",
          VoiceName = "voice/$Locale$/story/1201/120172/1E15745E"
        },
        [12017204] = {
          ContentFR = "... Être resté trop longtemps dans ce monde t’a privé de la parole... le pauvre.",
          DialogueId = 12017204,
          GUID = "1E157488",
          NextDialogue = 12017205,
          SpeakNpcId = 210013,
          Subtitle = "...You've lingered in this realm too long, and have lost even the power of speech. How pitiful.",
          VoiceName = "voice/$Locale$/story/1201/120172/1E157488"
        },
        [12017205] = {
          ContentFR = "Reste près de moi. Je te conduirai, toi aussi, en lieu sûr.",
          DialogueId = 12017205,
          GUID = "1E1574B2",
          SpeakNpcId = 210013,
          Subtitle = "Stay close to me. I will guide you to safety as well.",
          VoiceName = "voice/$Locale$/story/1201/120172/1E1574B2"
        },
        [12017206] = {
          ContentFR = "Yi !",
          DialogueId = 12017206,
          GUID = "1E1574DC",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee!",
          VoiceName = "voice/$Locale$/story/1201/120172/1E1574DC"
        },
        [12017301] = {
          ContentFR = "<I>Le seul vœu de toute ma vie fut d’user de l’Art de l’Éphémère pour sauver les êtres. Ce serment — jamais je n’ai osé le trahir.</>",
          DialogueId = 12017301,
          Duration = 3,
          GUID = "1E158472",
          NextDialogue = 12017302,
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(In this fleeting life, my sole resolve is to wield the Art of Ephemerality — to heal all who suffer. That resolve, I shall never forsake.)",
          VoiceName = "voice/$Locale$/story/1201/120173/1E158472"
        },
        [12017302] = {
          ContentFR = "La couleur de la flamme, elle n’est pas normale...",
          DialogueId = 12017302,
          Duration = 2,
          GUID = "1E15849C",
          SpeakNpcId = 210013,
          Subtitle = "The colour of the flame... it's not as it should be.",
          VoiceName = "voice/$Locale$/story/1201/120173/1E15849C"
        },
        [12017401] = {
          ContentFR = "J’ai si mal... mes plaies suppurent... la douleur m’empêche de dormir, nuit après nuit..",
          DialogueId = 12017401,
          Duration = 2,
          GUID = "1E1594DA",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_CMName_Name_HuanzhePhantom",
          Subtitle = "It hurts so much... My wounds are festering — I haven't known sleep in days...",
          VoiceName = "voice/$Locale$/story/1201/120174/1E1594DA"
        },
        [12017402] = {
          ContentFR = "Je n’ai plus d’issue, n’est-ce pas... Dame Zhuyou... accordez-moi une fin...",
          DialogueId = 12017402,
          Duration = 3,
          GUID = "1E159504",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_CMName_Name_HuanzhePhantom",
          Subtitle = "There's no hope left, is there? Lady Zhuyou... please, put me out of my misery...",
          VoiceName = "voice/$Locale$/story/1201/120174/1E159504"
        },
        [12017403] = {
          ContentFR = "Mon enfant vient de naître... elle n’a même pas encore appelé « maman » une seule fois ! Je vous en supplie — sauvez-la ! Sauvez-la !",
          DialogueId = 12017403,
          Duration = 3,
          GUID = "1E15952E",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_CMName_Name_HuanzhePhantom",
          Subtitle = "My baby... she's just come into the world, and hasn't even called me \"Mama\" yet! Please, I beg you — save her. Save her!",
          VoiceName = "voice/$Locale$/story/1201/120174/1E15952E"
        },
        [12017404] = {
          ContentFR = "On dit que les Fushu guérissent tout d’un geste ! Alors pourquoi hésites-tu ? Tu refuses d’aider ?!",
          DialogueId = 12017404,
          Duration = 4,
          GUID = "1E159558",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_CMName_Name_HuanzhePhantom",
          Subtitle = "They say the House of Zhuyou can heal any affliction — so why won't you help us? Don't you care!?",
          VoiceName = "voice/$Locale$/story/1201/120174/1E159558"
        },
        [12017405] = {
          ContentFR = "... C’était la Grande Épidémie d’il y a cent ans.",
          DialogueId = 12017405,
          Duration = 1,
          GUID = "1E159582",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 12017406,
          SpeakNpcId = 210013,
          Subtitle = "This was... the plague that ravaged our lands a century ago.",
          VoiceName = "voice/$Locale$/story/1201/120174/1E159582"
        },
        [12017406] = {
          ContentFR = "Je courais sans relâche, jusqu’à l’épuisement... Et malgré tout, je ne pouvais que regarder les malades mourir — consumés par la douleur et le désespoir.",
          DialogueId = 12017406,
          Duration = 3,
          GUID = "1E1595AC",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 210013,
          Subtitle = "I ran from dawn to dusk, doing all I could... yet still, all I could do was watch them die, one by one — helpless in their agony.",
          VoiceName = "voice/$Locale$/story/1201/120174/1E1595AC"
        },
        [12017407] = {
          ContentFR = "<I>La réaction de la flamme... Alors mon cœur vacillait déjà à cette époque...</>",
          DialogueId = 12017407,
          Duration = 2,
          GUID = "1E1595D6",
          NextDialogue = 12017501,
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(Such is the flame's response... So my heart had wavered, after all?)",
          VoiceName = "voice/$Locale$/story/1201/120174/1E1595D6"
        },
        [12017501] = {
          ContentFR = "<I>Ce qui me hante... n’est-ce vraiment que la souffrance des autres ?</>",
          DialogueId = 12017501,
          Duration = 3,
          GUID = "1E15A542",
          NextDialogue = 12017502,
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(Is it only the pain of others I grieve... or is it something I've long kept hidden?)",
          VoiceName = "voice/$Locale$/story/1201/120175/1E15A542"
        },
        [12017502] = {
          ContentFR = "Tout ce que j’ai appris, tout ce que j’ai pratiqué, n’a toujours été que l’Art de l’Éphémère. Si mon cœur n’est plus en paix... comment pourrais-je quitter cet endroit...",
          DialogueId = 12017502,
          Duration = 4,
          GUID = "1E15A56C",
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(Yet all I have known, all I have ever offered, is the Art of Ephemerality. If my heart wavers... how can I find a way back?)",
          VoiceName = "voice/$Locale$/story/1201/120175/1E15A56C"
        },
        [12017601] = {
          ContentFR = "... Comme je m’y attendais.",
          DialogueId = 12017601,
          Duration = 1,
          GUID = "1E15B5AA",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 12017602,
          SpeakNpcId = 210013,
          Subtitle = "...As I feared.",
          VoiceName = "voice/$Locale$/story/1201/120176/1E15B5AA"
        },
        [12017602] = {
          ContentFR = "Pardonne-moi. Je t’avais promis de te mener hors d’ici... Il semble que je ne pourrai pas tenir parole.",
          DialogueId = 12017602,
          Duration = 2,
          GUID = "1E15B5D4",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 210013,
          Subtitle = "Forgive me... I promised to lead you out. But now... it seems I must break that promise.",
          VoiceName = "voice/$Locale$/story/1201/120176/1E15B5D4"
        },
        [12017701] = {
          ContentFR = "Yi—ya... yi-yi—ya... yi !",
          DialogueId = 12017701,
          Duration = 1,
          GUID = "1E15C612",
          NextDialogue = 12017702,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee-ya, ee-ee-ya, ee!",
          VoiceName = "voice/$Locale$/story/1201/120177/1E15C612"
        },
        [12017702] = {
          ContentFR = "... ! Tu te consumes comme combustible ? Si tu continues... tu disparaîtras entièrement, sans laisser de trace...",
          DialogueId = 12017702,
          Duration = 3,
          GUID = "1E15C63C",
          NextDialogue = 12017703,
          SpeakNpcId = 210013,
          Subtitle = "...! You would burn yourself as fuel? If you continue, your form will fade into nothingness...",
          VoiceName = "voice/$Locale$/story/1201/120177/1E15C63C"
        },
        [12017703] = {
          ContentFR = "Yi !",
          DialogueId = 12017703,
          Duration = 1,
          GUID = "1E15C666",
          NextDialogue = 12017704,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee!",
          VoiceName = "voice/$Locale$/story/1201/120177/1E15C666"
        },
        [12017704] = {
          ContentFR = "... J’ai compris. Je ferai tout pour te protéger.",
          DialogueId = 12017704,
          Duration = 2,
          GUID = "1E15C690",
          SpeakNpcId = 210013,
          Subtitle = "...I understand. Then I shall shield you with all that I am.",
          VoiceName = "voice/$Locale$/story/1201/120177/1E15C690"
        },
        [12017801] = {
          ContentFR = "Fushu... j’ai appris que tu t’étais effondrée en soignant des malades. J’ai traversé mille lieues pour te voir... Tu dois arrêter l’Art de l’Éphémère.",
          DialogueId = 12017801,
          GUID = "1E15D67A",
          NextDialogue = 12017802,
          SnapShot = "ECHO",
          SpeakNpcId = 210028,
          Subtitle = "Fushu, I heard you collapsed while treating the sick — I travelled far to see you... You must stop using the Art of Ephemerality.",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D67A"
        },
        [12017802] = {
          ContentFR = "Merci de t’inquiéter pour moi. Je vais bien désormais. S’il te plaît, rentre chez toi, grande sœur.",
          DialogueId = 12017802,
          GUID = "1E15D6A4",
          NextDialogue = 12017803,
          SnapShot = "ECHO",
          SpeakNpcId = 210029,
          Subtitle = "Thank you for your concern. But I am well now, Sister. You should return.",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D6A4"
        },
        [12017803] = {
          ContentFR = "« Bien » ?! Tu te détruis toi-même — attends-tu vraiment de perdre la vie pour t’arrêter ?",
          DialogueId = 12017803,
          GUID = "1E15D6CE",
          NextDialogue = 12017804,
          SnapShot = "ECHO",
          SpeakNpcId = 210028,
          Subtitle = "Well? You call this \"well\"? You're harming your own life, Fushu — can't you see that?",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D6CE"
        },
        [12017804] = {
          ContentFR = "Sauver les êtres est la mission que les Neuf Chapitres de Dafeng ont confiée à notre lignée. Devrais-je détourner le regard pendant que les gens souffrent ?",
          DialogueId = 12017804,
          GUID = "1E15D6F8",
          NextDialogue = 12017805,
          SnapShot = "ECHO",
          SpeakNpcId = 210029,
          Subtitle = "Saving lives is the mission the Nine Chapters gave to us. Should I stand idle as others suffer in agony?",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D6F8"
        },
        [12017805] = {
          ContentFR = "Si tu n’avais pas insisté pour abandonner l’art ancestral au profit de la <H>médecine des remèdes</>, aurais-je seulement été contrainte de me pousser à une telle extrémité ?",
          DialogueId = 12017805,
          GUID = "1E15D722",
          NextDialogue = 12017806,
          SnapShot = "ECHO",
          SpeakNpcId = 210029,
          Subtitle = "Had you not forsaken our ancestral art to pursue pharmacology, I wouldn't have pushed myself this far!",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D722"
        },
        [12017806] = {
          ContentFR = "Pardonne-moi... mais je ne peux pas chérir ma propre vie comme tu le fais.",
          DialogueId = 12017806,
          GUID = "1E15D74C",
          NextDialogue = 12017901,
          SnapShot = "ECHO",
          SpeakNpcId = 210029,
          Subtitle = "Forgive me, Sister... but I cannot bring myself to cherish my own life above others', as you do.",
          VoiceName = "voice/$Locale$/story/1201/120178/1E15D74C"
        },
        [12017901] = {
          ContentFR = "... Fushu. Ainsi, voilà ce que tu pensais de moi.",
          DialogueId = 12017901,
          Duration = 2,
          GUID = "1E15E6E2",
          SnapShot = "ECHO",
          SpeakNpcId = 210028,
          Subtitle = "...So this is how you see me, Fushu.",
          VoiceName = "voice/$Locale$/story/1201/120179/1E15E6E2"
        },
        [12017902] = {
          ContentFR = "<I>Ces paroles n’étaient pas ce que je voulais dire. Mais une fois prononcées, elles ont jailli — cruelles, incontrôlables.</>",
          DialogueId = 12017902,
          Duration = 3,
          GUID = "1E15E70C",
          NextDialogue = 12017903,
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(Those words... they were never what I meant. But once I spoke, the bitterness surged forth like a flood I couldn't hold back.)",
          VoiceName = "voice/$Locale$/story/1201/120179/1E15E70C"
        },
        [12017903] = {
          ContentFR = "<I>Je n’ai pas su lui faire face. J’ai fui. Ce fut notre dernière conversation.</>",
          DialogueId = 12017903,
          Duration = 3,
          GUID = "1E15E736",
          SnapShot = "HEART",
          SpeakNpcId = 210013,
          Subtitle = "(In the end, I didn't know how to face her... so I left. That was the last time we ever spoke.)",
          VoiceName = "voice/$Locale$/story/1201/120179/1E15E736"
        },
        [12018001] = {
          Camera = "-361.291565,868.035156,176.938965,0.000062,-2.401447,-174.821503,35.0,506.121063,false,Manual,2.8",
          ContentFR = "Fushu... tu es encore jeune. Je ne te laisserai pas mourir ainsi.",
          DialogueId = 12018001,
          Duration = 3,
          GUID = "1E15F74A",
          NextDialogue = 12018002,
          SnapShot = "ECHO",
          SpeakNpcId = 210028,
          Subtitle = "Fushu... You're still in the prime of your life. I will not stand by and watch you die.",
          VoiceName = "voice/$Locale$/story/1201/120180/1E15F74A"
        },
        [12018002] = {
          ContentFR = "Je créerai un remède pour te sauver. Même si cela me coûte le reste de ma vie... je le ferai. Attends-moi.",
          DialogueId = 12018002,
          Duration = 2,
          GUID = "1E15F774",
          SnapShot = "ECHO",
          SpeakNpcId = 210028,
          Subtitle = "I will find a cure for you. Even if it costs me everything — my life, my years — I will not rest until I do. Wait for me.",
          VoiceName = "voice/$Locale$/story/1201/120180/1E15F774"
        },
        [12018003] = {
          ContentFR = "...",
          DialogueId = 12018003,
          GUID = "1E15F775",
          SpeakNpcId = 210013,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120180/1E15F775"
        },
        [12018004] = {DialogueId = 12018004, GUID = "1E15F776"},
        [12018101] = {
          ContentFR = "... Grande sœur...",
          DialogueId = 12018101,
          Duration = 2,
          GUID = "1E1607B2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 12018102,
          SpeakNpcId = 210013,
          Subtitle = "...Sister...",
          VoiceName = "voice/$Locale$/story/1201/120181/1E1607B2"
        },
        [12018102] = {
          ContentFR = "Elle m’a toujours offert son cœur avec sincérité... Et je n’ai pas su en reconnaître la valeur.",
          DialogueId = 12018102,
          Duration = 3,
          GUID = "1E1607DC",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 12018103,
          SpeakNpcId = 210013,
          Subtitle = "She gave her whole heart to me, and I was blind to it.",
          VoiceName = "voice/$Locale$/story/1201/120181/1E1607DC"
        },
        [12018103] = {
          ContentFR = "Je voudrais la revoir une fois encore... Ne serait-ce que pour lui dire « pardon »...",
          DialogueId = 12018103,
          Duration = 2,
          GUID = "1E160806",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 210013,
          Subtitle = "All I want is to see her again. To say that \"I'm sorry.\"",
          VoiceName = "voice/$Locale$/story/1201/120181/1E160806"
        },
        [12018201] = {
          ContentFR = "Yi ! Yi !",
          DialogueId = 12018201,
          Duration = 1,
          GUID = "1E16181A",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_CMName_Name_WuyouWuyan",
          Subtitle = "Ee-ee! Ee!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E16181A"
        },
        [12018202] = {
          ContentFR = "Fushu ! J’ai cru que tu...",
          DialogueId = 12018202,
          GUID = "1E161844",
          NextDialogue = 12018203,
          SpeakNpcId = 100001,
          Subtitle = "Fushu! I thought...",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161844"
        },
        [12018203] = {
          ContentFR = "Pardonne-moi de t’avoir inquiété.",
          DialogueId = 12018203,
          GUID = "1E16186E",
          NextDialogue = 12018204,
          SpeakNpcId = 210013,
          Subtitle = "I am well. Forgive me for worrying you.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E16186E"
        },
        [12018204] = {
          ContentFR = "C’est grâce à l’aide de ce Wishen sans nom que je ne me suis pas égarée dans la Faille de l’Oubli. Sauver autrui, c’est aussi se sauver soi-même... Les anciens ne mentaient donc pas.",
          DialogueId = 12018204,
          GUID = "1E161898",
          NextDialogue = 12018205,
          SpeakNpcId = 210013,
          Subtitle = "Thanks to this nameless little one, I did not lose myself in the Oblivion Rift. As the old saying goes: \"By guiding others, we find our own path as well.\" Once again, these words have proven true.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161898"
        },
        [12018205] = {
          ContentFR = "Yi ! Yi-ya-yi !",
          DialogueId = 12018205,
          GUID = "1E1618C2",
          NextDialogue = 12018206,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Ee, ee-ya-ee, ee!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E1618C2"
        },
        [12018206] = {
          ContentFR = "Tant mieux... Te retrouver saine et sauve me rassure vraiment.",
          DialogueId = 12018206,
          GUID = "1E1618EC",
          NextDialogue = 12018207,
          SpeakNpcId = 100001,
          Subtitle = "I'm glad you're safe. That's a big relief.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E1618EC"
        },
        [12018207] = {
          ContentFR = "Nous ne sommes pas encore hors de danger. Le pire est derrière nous, mais ce n’est pas le moment de relâcher notre vigilance. Viens — quittons cet endroit au plus vite et regagnons ce monde.",
          DialogueId = 12018207,
          GUID = "1E161916",
          NextDialogue = 12018208,
          SpeakNpcId = 210013,
          Subtitle = "We are not yet free of peril. Though we have emerged from the deepest shadow, we must not let caution slip. Come — let us return to the world of the living.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161916"
        },
        [12018208] = {
          ContentFR = "Oui. Je te suis.",
          DialogueId = 12018208,
          GUID = "1E161940",
          NextDialogue = 12018209,
          SpeakNpcId = 100001,
          Subtitle = "Right. I'm ready.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161940"
        },
        [12018209] = {
          ContentFR = "Suis ces Jades lumineux. Ils indiquent la voie du retour.",
          DialogueId = 12018209,
          GUID = "1E16196A",
          SpeakNpcId = 210013,
          Subtitle = "Follow the Luminous Jades. They shall illuminate the path ahead.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E16196A"
        },
        [12018210] = {
          ContentFR = "Fushu... tout à l’heure, dans le Fleuve de l’Oubli... qu’as-tu vu ?",
          DialogueId = 12018210,
          GUID = "1E161994",
          NextDialogue = 12018211,
          SpeakNpcId = 100001,
          Subtitle = "Fushu, what did you see in the River of Forgetting?",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161994"
        },
        [12018211] = {
          ContentFR = "Des fragments du passé. Des visages, des instants déjà emportés par le temps.",
          DialogueId = 12018211,
          GUID = "1E1619BE",
          NextDialogue = 12018212,
          SpeakNpcId = 210013,
          Subtitle = "Just echoes of the past... people and moments long since gone.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E1619BE"
        },
        [12018212] = {
          ContentFR = "Ce n’étaient pas de bons souvenirs, on dirait...",
          DialogueId = 12018212,
          GUID = "1E1619E8",
          NextDialogue = 12018213,
          SpeakNpcId = 100001,
          Subtitle = "Doesn't sound like they were happy memories...",
          VoiceName = "voice/$Locale$/story/1201/120182/1E1619E8"
        },
        [12018213] = {
          ContentFR = "À l’aide— !",
          DialogueId = 12018213,
          GUID = "1E161A12",
          NextDialogue = 12018214,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Help—!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161A12"
        },
        [12018214] = {
          ContentFR = "Yi-ya ! Yi !",
          DialogueId = 12018214,
          GUID = "1E161A3C",
          NextDialogue = 12018215,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_CMName_Name_WuyouWuyan",
          Subtitle = "Ee-ya, ee!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161A3C"
        },
        [12018215] = {
          ContentFR = "J’ai entendu un appel ! Allons voir !",
          DialogueId = 12018215,
          GUID = "1E161A66",
          SpeakNpcId = 100001,
          Subtitle = "Someone's calling for help — let's move!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161A66"
        },
        [12018216] = {
          ContentFR = "Merci... merci, âme bienveillante !",
          DialogueId = 12018216,
          GUID = "1E161A90",
          NextDialogue = 12018217,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Thank you, kind soul!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161A90"
        },
        [12018217] = {
          ContentFR = "D’autres... d’autres compagnons sont encore dispersés...",
          DialogueId = 12018217,
          GUID = "1E161ABA",
          NextDialogue = 12018218,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Others... more of us, still trapped.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161ABA"
        },
        [12018218] = {
          ContentFR = "Cet endroit est mauvais. Il faut partir. Pour s’enfuir... il faut unir nos forces !",
          DialogueId = 12018218,
          GUID = "1E161AE4",
          NextDialogue = 12018219,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "This place... feels wrong. Must leave. Need everyone's strength, to escape!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161AE4"
        },
        [12018219] = {
          ContentFR = "Il y a donc encore des Wishen prisonniers... D’accord. Je resterai attentif.",
          DialogueId = 12018219,
          GUID = "1E161B0E",
          NextDialogue = 12018220,
          SpeakNpcId = 100001,
          Subtitle = "You mean there are still more of you trapped here? Got it. I'll keep an eye out.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161B0E"
        },
        [12018220] = {
          ContentFR = "Merci ! Merci ! Prends... ma force !",
          DialogueId = 12018220,
          GUID = "1E161B38",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Thank you, thank you! My strength... take it!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161B38"
        },
        [12018221] = {
          ContentFR = "Pierres ternes... avec la force... briller !",
          DialogueId = 12018221,
          GUID = "1E161B62",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Dim stones... with strength, and they glow!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161B62"
        },
        [12018222] = {
          ContentFR = "Le passage est bloqué...",
          DialogueId = 12018222,
          GUID = "1E161B8C",
          NextDialogue = 12018223,
          SpeakNpcId = 100001,
          Subtitle = "The road ahead is blocked by a stone gate..."
        },
        [12018223] = {
          ContentFR = "Observons les alentours. Il doit y avoir un mécanisme dissimulé.",
          DialogueId = 12018223,
          GUID = "1E161BB6",
          SpeakNpcId = 210013,
          Subtitle = "Let us take a closer look around. There might be some hidden mechanism or clue.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161BB6"
        },
        [12018224] = {
          ContentFR = "Pierres ternes... toutes... briller ensemble !",
          DialogueId = 12018224,
          GUID = "1E161BE0",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Dim stones... light up, all at once!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161BE0"
        },
        [12018225] = {
          ContentFR = "Ouah... ! Dame Zhuyou ! Et... {性别:un humain inconnu|une humaine inconnue} !",
          DialogueId = 12018225,
          GUID = "1E161C0A",
          NextDialogue = 12018226,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Whoa...! It's Lady Zhuyou! And... another human!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161C0A"
        },
        [12018226] = {
          ContentFR = "La sortie vers la Source de Yu semble si loin. Je suis épuisé... je n’arrive plus à avancer...",
          DialogueId = 12018226,
          GUID = "1E161C34",
          NextDialogue = 12018227,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "The exit to the Spring of Yu looks so, so far away... I'm so tired... I don't think I can keep going...",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161C34"
        },
        [12018227] = {
          ContentFR = "Parfois, j’ai envie de m’endormir ici... D’oublier... et de disparaître...",
          DialogueId = 12018227,
          GUID = "1E161C5E",
          NextDialogue = 12018228,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "I just want to curl up here, forget everything... and let myself fade away...",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161C5E"
        },
        [12018228] = {
          ContentFR = "Mais puisque nos compagnons sont là, nous devons continuer à marcher !",
          DialogueId = 12018228,
          GUID = "1E161C88",
          NextDialogue = 12018229,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "But now that our friends are here, we can't just give up. Let's keep going!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161C88"
        },
        [12018229] = {
          ContentFR = "Vous avez longtemps foulé le Fleuve de l’Oubli... Vos âmes sont lourdes, n’est-ce pas ? Laisse-moi les alléger — vous serez légers comme le vent !",
          DialogueId = 12018229,
          GUID = "1E161CB2",
          NextDialogue = 12018230,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "You've walked the River of Forgetting for so long... Are your souls feeling heavy? Let me lighten them — make you as swift as the wind!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161CB2"
        },
        [12018230] = {
          ContentFR = "Et moi, je balaierai les obstacles devant vous ! Vous avancerez sans entrave !",
          DialogueId = 12018230,
          GUID = "1E161CDC",
          NextDialogue = 12018231,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "Then let me clear the path ahead — no more obstacles in your way!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161CDC"
        },
        [12018231] = {
          ContentFR = "Yi-ya ! Parfait ! En route !",
          DialogueId = 12018231,
          GUID = "1E161D06",
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_Npc_Name_WuyoushengA&B",
          Subtitle = "Ee-ya! Now we're all set — let's go!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161D06"
        },
        [12018232] = {
          ContentFR = "Yi-ya ! Ya !",
          DialogueId = 12018232,
          GUID = "1E161D30",
          NextDialogue = 12018233,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_Npc_Name_WuyoushengShoukun",
          Subtitle = "Ee-ee, ya!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161D30"
        },
        [12018233] = {
          ContentFR = "Les mauvaises fleurs ont capturé nos amis ! Aidez-les !",
          DialogueId = 12018233,
          GUID = "1E161D5A",
          NextDialogue = 12018234,
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          Subtitle = "The mean flowers have trapped my friends! Please, help them!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161D5A"
        },
        [12018234] = {
          ContentFR = "J’ai déjà vu ce type de fleur dans les anciens écrits. Lorsque ses pétales sont fermés, rien ne peut les entamer. Il faut attendre le moment où elle s’ouvrira.",
          DialogueId = 12018234,
          GUID = "1E161D84",
          SpeakNpcId = 210013,
          Subtitle = "I have seen this kind of flower in the old records. When its petals are shut, no blade can cut it. We must wait for it to bloom.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161D84"
        },
        [12018235] = {
          ContentFR = "Le cœur est à découvert — maintenant !",
          DialogueId = 12018235,
          GUID = "1E161DAE",
          SpeakNpcId = 210013,
          Subtitle = "The core is exposed — strike now!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161DAE"
        },
        [12018236] = {
          ContentFR = "Dame Zhuyou ! Et {性别:le vaillant guerrier|la vaillante guerrière} aux cheveux blancs ! Merci !",
          DialogueId = 12018236,
          GUID = "1E161DD8",
          NextDialogue = 12018237,
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_Npc_Name_WuyoushengShoukun",
          Subtitle = "Lady Zhuyou! And the white-haired stranger — thank you both!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161DD8"
        },
        [12018237] = {
          ContentFR = "Je viens aussi prêter main-forte ! Mon coup de tête d’acier peut fendre la terre !",
          DialogueId = 12018237,
          GUID = "1E161E02",
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_Npc_Name_WuyoushengShoukun",
          Subtitle = "Let me lend a hand too! My iron headbutt can even crack the earth!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161E02"
        },
        [12018238] = {
          ContentFR = "Les derniers compagnons ! Les derniers !",
          DialogueId = 12018238,
          GUID = "1E161E2C",
          NextDialogue = 12018239,
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_Npc_Name_WuyoushengA",
          Subtitle = "The last ones! Friends still trapped!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161E2C"
        },
        [12018239] = {
          ContentFR = "Encore cette fleur souillée. {nickname}, attends qu’elle s’épanouisse, puis élimine d’un seul coup le cœur et les lianes.",
          DialogueId = 12018239,
          GUID = "1E161E56",
          SpeakNpcId = 210013,
          Subtitle = "It is the same kind of flower as before. , wait for it to bloom fully — then strike the core and all the vines in one stroke.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161E56"
        },
        [12018240] = {
          ContentFR = "Avec toute mon expérience martiale... j’ai bien failli périr ici. Quelle honte...",
          DialogueId = 12018240,
          GUID = "1E161E80",
          NextDialogue = 12018241,
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_CMName_Name_MatureWuyou",
          Subtitle = "With all my years of martial skill, I nearly met my end here... How shameful...",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161E80"
        },
        [12018241] = {
          ContentFR = "Cette fois, tout le monde est là ! Personne n’a été laissé derrière !",
          DialogueId = 12018241,
          GUID = "1E161EAA",
          NextDialogue = 12018242,
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_Npc_Name_WuyoushengA",
          Subtitle = "Now we're all here — no one left behind, not a single one!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161EAA"
        },
        [12018242] = {
          ContentFR = "Un immense Souillé bloque la sortie vers ce monde. Laissez-moi combattre à vos côtés et purifiez cet endroit !",
          DialogueId = 12018242,
          GUID = "1E161ED4",
          SnapShot = "WUYOU",
          SpeakNpcName = "UI_CMName_Name_MatureWuyou",
          Subtitle = "The final path is blocked by a monstrous Filthoid flower. Let me stand with you. Together, we shall cut it down and restore this place!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161ED4"
        },
        [12018243] = {
          ContentFR = "{nickname} ! Le Fleuve de l’Oubli s’effondre — il faut en finir !",
          DialogueId = 12018243,
          GUID = "1E161EFE",
          Subtitle = ", the River of Forgetting is about to collapse! We must end this now!",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161EFE"
        },
        [12018244] = {
          ContentFR = "Maintenant. Donne-moi la main.",
          DialogueId = 12018244,
          GUID = "1E161F28",
          Subtitle = "Now — take my hand.",
          VoiceName = "voice/$Locale$/story/1201/120182/1E161F28"
        },
        [12018300] = {
          ContentFR = "Merci pour nous avoir sauvés. Nous n’oublierons jamais cette dette. À bientôt !",
          DialogueId = 12018300,
          GUID = "1E162858",
          NextDialogue = 12018301,
          RelatedWikiId = {
            [1] = 408013,
            [2] = 303012,
            [3] = 203006
          },
          SnapShot = "WUYOU",
          SpeakNpcId = 210017,
          SpeakNpcName = "UI_Npc_Name_Wuyoushengmen",
          Subtitle = "Thank you, both of you! We'll never forget this kindness. Goodbye for now!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162858"
        },
        [12018301] = {
          ContentFR = "<I>Bouhou...</> Fushu ! {nickname} ! Vous êtes enfin revenus ! J’étais morte d’inquiétude !",
          DialogueId = 12018301,
          GUID = "1E162882",
          NextDialogue = 12018302,
          SpeakNpcId = 200002,
          Subtitle = "Waaah... Fushu! ! You're finally back! I was worried sick...",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162882"
        },
        [12018302] = {
          ContentFR = "J’ai cru que vous alliez... non non non ! Si je ne le dis pas, ça n’arrivera pas !",
          DialogueId = 12018302,
          GUID = "1E1628AC",
          NextDialogue = 12018303,
          SpeakNpcId = 200002,
          Subtitle = "I thought you were... uh-uh! If I don't say it out loud, those bad things will never happen to you!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E1628AC"
        },
        [12018303] = {
          ContentFR = "Fushu... merci d’avoir pris tous ces risques pour me ramener.",
          DialogueId = 12018303,
          GUID = "1E1628D6",
          NextDialogue = 12018304,
          SpeakNpcId = 100001,
          Subtitle = "Fushu, thank you for risking your own life to bring me back.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E1628D6"
        },
        [12018304] = {
          ContentFR = "C’était mon devoir.",
          DialogueId = 12018304,
          GUID = "1E162900",
          NextDialogue = 12018305,
          SpeakNpcId = 210013,
          Subtitle = "It was what I had to do.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162900"
        },
        [12018305] = {
          ContentFR = "Tu es sûre que ça va ? Tu es toute pâle...",
          DialogueId = 12018305,
          GUID = "1E16292A",
          NextDialogue = 12018306,
          SpeakNpcId = 100001,
          Subtitle = "Are you okay? You look pale...",
          VoiceName = "voice/$Locale$/story/1201/120183/1E16292A"
        },
        [12018306] = {
          ContentFR = "Mon corps va bien. C’est mon esprit qui a besoin de calme... et d’un peu d’ordre.",
          DialogueId = 12018306,
          GUID = "1E162954",
          NextDialogue = 12018307,
          SpeakNpcId = 210013,
          Subtitle = "My body is unharmed. It's only my thoughts — still tangled and unclear. I need a moment to gather them.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162954"
        },
        [12018307] = {
          ContentFR = "D’accord. Si tu as besoin de parler, je serai là.",
          DialogueId = 12018307,
          GUID = "1E16297E",
          NextDialogue = 12018308,
          SpeakNpcId = 100001,
          Subtitle = "Alright... But if you ever need someone to talk to — I'm always here for you.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E16297E"
        },
        [12018308] = {
          ContentFR = "Évidemment. Après ce que nous avons traversé... vous êtes mes deux {性别:seuls amis|seules amies} en ce monde.",
          DialogueId = 12018308,
          GUID = "1E1629A8",
          NextDialogue = 12018309,
          SpeakNpcId = 210013,
          Subtitle = "Sure. After all we have endured together... you and Snow are the only companions I hold dear in this world.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E1629A8"
        },
        [12018309] = {
          ContentFR = "<I>Bouhou...</> Fushu...",
          DialogueId = 12018309,
          GUID = "1E1629D2",
          NextDialogue = 12018310,
          SpeakNpcId = 200002,
          Subtitle = "Aww, Fushu...",
          VoiceName = "voice/$Locale$/story/1201/120183/1E1629D2"
        },
        [12018310] = {
          ContentFR = "Bien. Malgré les détours, nous avons récolté les herbes nécessaires. Je dois rentrer avant que la rosée ne s’évapore, pour les préparer.",
          DialogueId = 12018310,
          GUID = "1E1629FC",
          NextDialogue = 12018311,
          SpeakNpcId = 210013,
          Subtitle = "Well then. Though it was a harrowing journey, we have managed to gather the herbs we needed. I must see them safely home, so I can begin refining them before the dew fades.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E1629FC"
        },
        [12018311] = {
          ContentFR = "Yi !",
          DialogueId = 12018311,
          GUID = "1E162A26",
          NextDialogue = 12018312,
          SnapShot = "WUYOU",
          SpeakNpcId = 210036,
          Subtitle = "Ee!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162A26"
        },
        [12018312] = {
          ContentFR = "Aaah ! D’où tu sors, toi ?! Tu m’as fait peur !",
          DialogueId = 12018312,
          GUID = "1E162A50",
          NextDialogue = 12018313,
          SpeakNpcId = 200002,
          Subtitle = "Ahh! Where did you pop out from!? You nearly gave me a heart attack!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162A50"
        },
        [12018313] = {
          ContentFR = "Tu n’es pas parti avec les autres...",
          DialogueId = 12018313,
          GUID = "1E162A7A",
          NextDialogue = 12018314,
          SpeakNpcId = 210013,
          Subtitle = "You did not depart with the others...",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162A7A"
        },
        [12018314] = {
          ContentFR = "Je l’ai rencontré au plus profond de la Faille de l’Oubli. Je l’ai ramené avec moi... une rencontre fugace, mais précieuse.",
          DialogueId = 12018314,
          GUID = "1E162AA4",
          NextDialogue = 12018315,
          SpeakNpcId = 210013,
          Subtitle = "I came across this little one deep within the Oblivion Rift and brought it back with me. A chance encounter... or perhaps that, too, is fate.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162AA4"
        },
        [12018315] = {
          ContentFR = "Yi ! Yi !",
          DialogueId = 12018315,
          GUID = "1E162ACE",
          NextDialogue = 12018316,
          SnapShot = "WUYOU",
          SpeakNpcId = 210036,
          SpeakNpcName = "UI_CMName_Name_WuyouWuyan",
          Subtitle = "Ee-ee! Ee!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162ACE"
        },
        [12018316] = {
          ContentFR = "Il a l’air très attaché à toi.",
          DialogueId = 12018316,
          GUID = "1E162AF8",
          NextDialogue = 12018317,
          SpeakNpcId = 100001,
          Subtitle = "It seems really attached to you.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162AF8"
        },
        [12018317] = {
          ContentFR = "Voilà qui est un peu délicat... Je vais devoir me concentrer pleinement sur le traitement du patient. Durant les soins, je ne peux me permettre d’être dérangée.",
          DialogueId = 12018317,
          GUID = "1E162B22",
          NextDialogue = 12018318,
          SpeakNpcId = 210013,
          Subtitle = "That may be a problem... I will need complete focus and peace to tend to the patient.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162B22"
        },
        [12018318] = {
          ContentFR = "{nickname}, pourrais-tu t’occuper de lui un moment ?",
          DialogueId = 12018318,
          GUID = "1E162B4C",
          NextDialogue = 12018319,
          SpeakNpcId = 210013,
          Subtitle = ", might I trouble you to watch over it for a while?",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162B4C"
        },
        [12018319] = {
          ContentFR = "Le petit larbin... du petit larbin ? Alors tu seras le petit larbin numéro deux !",
          DialogueId = 12018319,
          GUID = "1E162B76",
          NextDialogue = 12018320,
          SpeakNpcId = 200002,
          Subtitle = "So now my Little Minion has a little minion of their own? Guess that makes you Minion #2!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162B76"
        },
        [12018320] = {
          ContentFR = "Yi-ya-yi ! Yi-yi !",
          DialogueId = 12018320,
          GUID = "1E162BA0",
          NextDialogue = 12018321,
          SnapShot = "WUYOU",
          SpeakNpcId = 210036,
          SpeakNpcName = "UI_CMName_Name_WuyouWuyan",
          Subtitle = "Ee-ya-ee! Ee-ee!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162BA0"
        },
        [12018321] = {
          ContentFR = "On dirait qu’il n’aime pas trop cette idée...",
          DialogueId = 12018321,
          GUID = "1E162BCA",
          NextDialogue = 12018322,
          SpeakNpcId = 100001,
          Subtitle = "It doesn't look happy with that arrangement.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162BCA"
        },
        [12018322] = {
          ContentFR = "... Pardonne-moi. J’ai été maladroite. Puisque le destin nous a liés, reste avec moi. Je ne t’abandonnerai pas. D’accord ?",
          DialogueId = 12018322,
          GUID = "1E162BF4",
          NextDialogue = 12018323,
          SpeakNpcId = 210013,
          Subtitle = "...My apologies. That was thoughtless of me. Since fate has brought us together, stay with me. I promise I won't turn you away. Will that suffice?",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162BF4"
        },
        [12018323] = {
          ContentFR = "Yi !",
          DialogueId = 12018323,
          GUID = "1E162C1E",
          NextDialogue = 12018324,
          SnapShot = "WUYOU",
          SpeakNpcId = 210036,
          SpeakNpcName = "UI_CMName_Name_WuyouWuyan",
          Subtitle = "Ee!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162C1E"
        },
        [12018324] = {
          ContentFR = "{nickname}, je te confie aussi un message pour l’Aîné Wishen. Quand la patiente ira mieux, nous nous reverrons.",
          DialogueId = 12018324,
          GUID = "1E162C48",
          NextDialogue = 12018325,
          SpeakNpcId = 210013,
          Subtitle = ", could I trouble you to report to Elder Wishen? Once the patient is resting more easily, I will meet with you again.",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162C48"
        },
        [12018325] = {
          ContentFR = "Marché conclu !",
          DialogueId = 12018325,
          GUID = "1E162C72",
          SpeakNpcId = 100001,
          Subtitle = "It's a promise!",
          VoiceName = "voice/$Locale$/story/1201/120183/1E162C72"
        },
        [12018401] = {
          Camera = "-82.743599,-22.173996,191.510315,0.000107,-18.000362,104.812141,25.000002,269.56311,false,Manual,6.0",
          ContentFR = "Ah... te voilà, {性别:mon jeune ami|ma jeune amie}. Allons-y.",
          DialogueId = 12018401,
          FacialId = {
            [1] = "210012:Smile01"
          },
          FinalCamera = "-85.275848,-12.593918,188.29126,0.000105,-18.000381,104.811234,25.000002,269.806946,false,Manual,6.0",
          GUID = "1E1638EA",
          LookAt = {
            [1] = "100001:n(210012)",
            [2] = "210012:n(100001)",
            [3] = "200002:n(100001)"
          },
          NextDialogue = 12018402,
          RelatedWikiId = {
            [1] = 203005
          },
          SpeakNpcId = 210012,
          Subtitle = "Ah, you've arrived, young friend. Come — let us not keep the day waiting.",
          TalkActionId = {
            [1] = "210012:Talk03_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1201/120184/1E1638EA"
        },
        [12018402] = {
          Camera = "31.293282,90.810593,118.199219,0.000119,3.198878,148.801849,35.000008,243.817368,false,Manual,6.0",
          ContentFR = "On part ? Où ça ? Vous pourriez au moins m’expliquer clairement.",
          DialogueId = 12018402,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E163914",
          NextDialogue = 12018403,
          SpeakNpcId = 100001,
          Subtitle = "We're leaving? Where are we going? Don't you think you owe me some kind of explanation?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120184/1E163914"
        },
        [12018403] = {
          Camera = "17.345215,243.589844,108.354248,0.000138,7.597834,-130.80278,35.000008,255.516861,false,Manual,6.0",
          ContentFR = "... Des explications ?",
          DialogueId = 12018403,
          FacialId = {
            [1] = "210012:Think01"
          },
          FinalCamera = "17.345215,243.589844,108.354248,0.000137,10.997827,-130.802673,35.000008,255.516861,false,Manual,6.0",
          GUID = "1E16393E",
          NextDialogue = 12018404,
          SpeakNpcId = 210012,
          Subtitle = "An explanation? ...Heh.",
          TalkActionId = {
            [1] = "210012:Talk03ToThink_Start",
            [2] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1201/120184/1E16393E"
        },
        [12018404] = {
          Camera = "-52.819229,197.234238,148.239014,0.000148,5.597148,-120.211037,35.000011,164.675781,false,Manual,6.0",
          ContentFR = "En toute chose, la vitesse est primordiale. S’attarder en paroles inutiles, c’est laisser filer la meilleure occasion... et voir la proie s’échapper.",
          DialogueId = 12018404,
          FacialId = {
            [1] = "210012:Doubt01"
          },
          GUID = "1E163968",
          NextDialogue = 12018405,
          Scripts = "PlayAnimation{_delay{1},ActorId{210012},AnimationId{\"Talk03ToThink_End\"},Duration{2}},",
          SpeakNpcId = 210012,
          Subtitle = "Timing is everything. Idle chatter can cost us dearly — and once lost, the prey may never be seen again.",
          VoiceName = "voice/$Locale$/story/1201/120184/1E163968"
        },
        [12018405] = {
          Camera = "-63.644783,133.544785,118.57605,0.000155,11.196975,138.185074,35.000011,122.361931,false,Manual,6.0",
          ContentFR = "Ça, c’est votre problème. Ce que je veux savoir, c’est si cette opération est dangereuse — et surtout... si elle est légitime.",
          DialogueId = 12018405,
          FacialId = {
            [1] = "100001:Angry01"
          },
          FinalCamera = "-63.644783,133.544785,118.57605,0.000169,16.996433,-169.21553,35.000011,122.361931,false,Manual,6.0",
          GUID = "1E163992",
          LookAt = {
            [1] = "100001:n(210012)",
            [2] = "210012:n(100001)",
            [3] = "200002:n(100001)"
          },
          NextDialogue = 12018406,
          Scripts = [[
PARA{
PlayAnimation{_delay{0.5},ActorId{210012},AnimationId{"Angry01_Start"},Duration{2}},
CameraMoveTo{_delay{1.8},TargetPosition{"111.541771,105.213097,52.417542,0.000211,17.193266,-176.41481,25.000002,279.10498,false,Manual,6.0"},duration{0}},
SEQ{
MoveTo{ActorId{100001},MoveSpeed{120},TargetPoint{"nvzhu_47_duizhi"}},
PlayAnimation{_delay{2},ActorId{100001},AnimationId{"Nvzhu_Story_Angry02_Start"},Duration{2}},
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "That's your problem. What matters to me is whether this mission is dangerous — and whether it's even legitimate.",
          TalkActionId = {
            [1] = "210012:Talk03_End"
          },
          ToFinalCameraBlendTime = 0.9,
          VoiceName = "voice/$Locale$/story/1201/120184/1E163992"
        },
        [12018406] = {
          Camera = "-113.994232,54.671646,165.879028,0.000155,-25.60232,96.198647,25.000002,113.956665,false,DoNotOverride,22.0",
          ContentFR = "O-ouh... l’ambiance est super lourde... Petit larbin, on ferait peut-être mieux de laisser tomber, non... ?",
          DialogueId = 12018406,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "1E1639BC",
          LookAt = {
            [1] = "100001:n(210012)",
            [2] = "210012:n(210012)",
            [3] = "200002:n(100001)"
          },
          NextDialogue = 12018407,
          SpeakNpcId = 200002,
          Subtitle = "Uwah, the tension is unreal... Little Minion, maybe we should just let it go?",
          TalkActionId = {
            [1] = "200002:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120184/1E1639BC"
        },
        [12018407] = {
          Camera = "295.454956,542.930176,371.227875,0.000125,-26.204176,-133.401733,24.0,113.956657,false,DoNotOverride,22.0",
          ContentFR = "Ha ha... Voilà une attitude qui force le respect. Ni soumission, ni arrogance — tu défends ta position avec raison. Ça me rappelle ma jeunesse. J’apprécie beaucoup.",
          DialogueId = 12018407,
          FacialId = {
            [1] = "210012:Ahaha01"
          },
          GUID = "1E1639E6",
          NextDialogue = 12018408,
          SpeakNpcId = 210012,
          Subtitle = "Haha... Calm yet assertive. Standing your ground with reason — reminds me of my own youthful days. I admire that.",
          TalkActionId = {
            [1] = "210012:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120184/1E1639E6"
        },
        [12018408] = {
          Camera = "-125.168137,93.99778,144.010498,0.000147,-24.602682,79.995262,25.000002,166.176483,false,Manual,6.0",
          ContentFR = "... Il a changé de visage en une seconde ?!",
          DialogueId = 12018408,
          GUID = "1E163A10",
          NextDialogue = 12018409,
          SpeakNpcId = 200002,
          Subtitle = "...He put on a new face just like that!?",
          TalkActionId = {
            [1] = "200002:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120184/1E163A10"
        },
        [12018409] = {
          Camera = "-95.768387,166.50177,121.84198,0.000135,-26.202879,76.599541,24.0,113.956657,false,DoNotOverride,22.0",
          ContentFR = "Attends, mais personne ne complimente les autres en se complimentant soi-même ! Quel ego surdimensionné !",
          DialogueId = 12018409,
          FacialId = {
            [1] = "200002:Angry01"
          },
          GUID = "1E163A3A",
          NextDialogue = 12018410,
          SpeakNpcId = 200002,
          Subtitle = "Hold on — who compliments others like that? This man's so full of himself!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120184/1E163A3A"
        },
        [12018410] = {
          Camera = "64.890961,321.150482,91.39502,0.000176,5.395296,-137.398178,24.0,297.770538,false,Manual,6.0",
          ContentFR = "Nous en reparlerons en chemin. Les questions qui vous préoccupent... je tâcherai d’y répondre.",
          DialogueId = 12018410,
          FacialId = {
            [1] = "210012:None"
          },
          GUID = "1E163A64",
          LookAt = {
            [1] = "100001:n(210012)",
            [2] = "210012:n(200002)",
            [3] = "200002:n(100001)"
          },
          SpeakNpcId = 210012,
          Subtitle = "Come, then. Let us speak as we walk. I shall do my best to answer what questions weigh upon your mind.",
          TalkActionId = {
            [1] = "210012:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120184/1E163A64"
        },
        [12018501] = {
          ContentFR = "Dis-moi, {性别:mon jeune ami|ma jeune amie}... ne t’es-tu jamais demandé pourquoi le Fléau de Zhuyin prend l’apparence d’un Bi’an obscur?",
          DialogueId = 12018501,
          Duration = 3,
          GUID = "1E164952",
          NextDialogue = 12018502,
          SpeakNpcId = 210012,
          Subtitle = "Tell me, young friend — have you ever wondered why the Scourge of Zhuyin takes the form of Sable Bi'an?",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164952"
        },
        [12018502] = {
          ContentFR = "À Huaxu, le Bi’an est une créature vénérée. Mais ailleurs, il n’est qu’un Souillé, porteur de calamités. La différence réside dans une seule chose : les entraves imposées par les Neuf Chapitres de Dafeng.",
          DialogueId = 12018502,
          Duration = 5,
          GUID = "1E16497C",
          SpeakNpcId = 210012,
          Subtitle = "The Bi'an, revered in Huaxu, is elsewhere known as a Filthoid — a harbinger of calamity and dread. The difference lies in the constraints imposed by the Nine Chapters of Dafeng.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E16497C"
        },
        [12018503] = {
          ContentFR = "L’apparition de Bi’an obscurs ne laisse place qu’à une hypothèse... les Neuf Chapitres sont en train de perdre le contrôle.",
          DialogueId = 12018503,
          Duration = 3,
          GUID = "1E1649A6",
          NextDialogue = 12018504,
          SpeakNpcId = 210012,
          Subtitle = "The emergence of these Sable Bi'an suggests but one troubling possibility: that the Nine Chapters are beginning to waver.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E1649A6"
        },
        [12018504] = {
          ContentFR = "Mais la Patronne Zhiliu a dit que si l’on réglait le Fléau de Zhuyin, tout rentrerait dans l’ordre.",
          DialogueId = 12018504,
          Duration = 3,
          GUID = "1E1649D0",
          NextDialogue = 12018505,
          SpeakNpcId = 100001,
          Subtitle = "But Proprietress Zhiliu said once we resolve the Scourge of Zhuyin, everything will go back to normal.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E1649D0"
        },
        [12018505] = {
          ContentFR = "C’est vrai. Mais cela ne ferait que retarder l’inévitable.",
          DialogueId = 12018505,
          Duration = 2,
          GUID = "1E1649FA",
          NextDialogue = 12018506,
          SpeakNpcId = 210012,
          Subtitle = "Indeed. But that would be a temporary reprieve at best.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E1649FA"
        },
        [12018506] = {
          ContentFR = "Et si le fléau revenait encore et encore ? Si, à force, il épuisait lentement les peuples et leur subsistance ?",
          DialogueId = 12018506,
          Duration = 3,
          GUID = "1E164A24",
          NextDialogue = 12018507,
          SpeakNpcId = 210012,
          Subtitle = "What if it returns, again and again, steadily hollowing out the people's strength?",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164A24"
        },
        [12018507] = {
          ContentFR = "Zhiliu a ses propres calculs. Certaines suppositions... elle ne les partagera pas forcément avec toi.",
          DialogueId = 12018507,
          Duration = 3,
          GUID = "1E164A4E",
          NextDialogue = 12018508,
          SpeakNpcId = 210012,
          Subtitle = "The Proprietress has her own considerations — some suspicions she may not yet share with you.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164A4E"
        },
        [12018508] = {
          ContentFR = "À mes yeux, si les fondations mêmes des Neuf Chapitres de Dafeng sont fissurées, toute réparation ne sera qu’un pansement de surface.",
          DialogueId = 12018508,
          Duration = 3,
          GUID = "1E164A78",
          NextDialogue = 12018509,
          SpeakNpcId = 210012,
          Subtitle = "From my perspective... if the very foundations of the Nine Chapters are compromised, no amount of patchwork can truly cure the rot.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164A78"
        },
        [12018509] = {
          ContentFR = "Donc... depuis le début, vous ne faites pas confiance aux Neuf Chapitres de Dafeng ?",
          DialogueId = 12018509,
          Duration = 2,
          GUID = "1E164AA2",
          NextDialogue = 12018510,
          SpeakNpcId = 100001,
          Subtitle = "So you're saying... you've never really believed in the Nine Chapters?",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164AA2"
        },
        [12018510] = {
          ContentFR = "Allons, inutile d’être aussi catégorique. Comme le dit l’adage : connaître l’autre, c’est se donner les moyens de vaincre.",
          DialogueId = 12018510,
          Duration = 4,
          GUID = "1E164ACC",
          NextDialogue = 12018511,
          SpeakNpcId = 210012,
          Subtitle = "Haha... No need to be so categorical, young friend. As the saying goes: Know yourself, know your enemy, and you shall never taste defeat.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164ACC"
        },
        [12018511] = {
          ContentFR = "Le but de cette expédition est simple : capturer un Bi’an et l’ajouter à ma « collection ». L’étudier en profondeur... afin de ne pas être pris au dépourvu.",
          DialogueId = 12018511,
          Duration = 5,
          GUID = "1E164AF6",
          NextDialogue = 12018512,
          SpeakNpcId = 210012,
          Subtitle = "This trip's purpose is to capture a Bi'an for my \"collection.\" I intend to study it thoroughly — a form of insurance against the worst.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164AF6"
        },
        [12018512] = {
          ContentFR = "Alors ? Cette raison te paraît-elle suffisante ?",
          DialogueId = 12018512,
          Duration = 2,
          GUID = "1E164B20",
          NextDialogue = 12018513,
          SpeakNpcId = 210012,
          Subtitle = "So — does this reasoning satisfy you?",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164B20"
        },
        [12018513] = {
          ContentFR = "... S’opposer à un Bi’an ne risque-t-il pas d’attirer la colère des Neuf Chapitres ?",
          DialogueId = 12018513,
          Duration = 5,
          GUID = "1E164B4A",
          NextDialogue = 12018514,
          SpeakNpcId = 100001,
          Subtitle = "...Won't turning against a Bi'an bring punishment from the Nine Chapters?",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164B4A"
        },
        [12018514] = {
          ContentFR = "Hm... nous autres, gens du marché noir, évoluons depuis longtemps à la lisière de leurs lois. Nous savons jusqu’où aller — et où nous arrêter.",
          DialogueId = 12018514,
          Duration = 2,
          GUID = "1E164B74",
          SpeakNpcId = 210012,
          Subtitle = "Heh. We in the black market have long walked the knife's edge of the Nine Chapters. We know well how to stay within bounds.",
          VoiceName = "voice/$Locale$/story/1201/120185/1E164B74"
        },
        [12018601] = {
          Camera = "24.121033,469.795776,75.995605,0.000102,15.589243,-120.015869,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Chef ! Vous êtes là !",
          DialogueId = 12018601,
          FacialId = {
            [1] = "210010:CM_Smile01"
          },
          FinalCamera = "24.121033,469.795776,75.995605,0.00012,7.589159,-99.01458,25.0,100000.0,false,DoNotOverride,22.0",
          GUID = "1E1659BA",
          NextDialogue = 12018602,
          RelatedWikiId = {
            [1] = 203005
          },
          SpeakNpcId = 210010,
          SpeakNpcName = "UI_CMName_Name_HeiShiXiaoDi",
          Subtitle = "Boss!",
          TalkActionId = {
            [1] = "210010:Agree"
          },
          ToFinalCameraBlendTime = 2.5,
          VoiceName = "voice/$Locale$/story/1201/120186/1E1659BA"
        },
        [12018602] = {
          Camera = "-136.252167,91.878937,113.345459,0.000122,16.784575,27.185421,35.000011,182.757812,false,Manual,4.0",
          ContentFR = "Faites le point.",
          DialogueId = 12018602,
          FacialId = {
            [1] = "210012:Doubt01"
          },
          GUID = "1E1659E4",
          NextDialogue = 12018603,
          SpeakNpcId = 210012,
          Subtitle = "How is everything going?",
          VoiceName = "voice/$Locale$/story/1201/120186/1E1659E4"
        },
        [12018603] = {
          Camera = "32.268948,257.847717,186.833252,0.00014,-8.414738,-115.807419,35.000011,279.251068,false,Manual,6.0",
          ContentFR = "Comme vous l’aviez prévu, la proie est blessée. Nous l’avons acculée dans la Plaine des Corbeaux. La zone est cernée par la mer — une île naturelle. Elle n’a nulle part où fuir. Il ne reste plus qu’à refermer le piège.",
          DialogueId = 12018603,
          FacialId = {
            [1] = "210010:CM_Idle"
          },
          GUID = "1E165A0E",
          NextDialogue = 12018604,
          SpeakNpcId = 210010,
          SpeakNpcName = "UI_CMName_Name_HeiShiXiaoDi",
          Subtitle = "Just as you foresaw — the prey's been wounded and driven into Crowsong Hollow. The place is ringed by the sea — like an island cut off from the world. There's no way out for it. Now we've only to close the net.",
          TalkActionId = {
            [1] = "210010:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165A0E"
        },
        [12018604] = {
          Camera = "-13.461863,151.743454,164.995361,0.000152,9.581034,39.99184,24.0,21.207821,false,Manual,6.0",
          ContentFR = "La Plaine des Corbeaux ? Qui a pris cette décision ?",
          DialogueId = 12018604,
          FacialId = {
            [1] = "210012:Angry01"
          },
          GUID = "1E165A38",
          NextDialogue = 12018605,
          RelatedWikiId = {
            [1] = 408014,
            [2] = 401003
          },
          Scripts = [[
PARA{
CameraMoveTo{_delay{4},TargetPosition{"-105.969948,58.336342,92.497803,0.000142,18.781393,43.997467,24.0,197.430618,false,Manual,6.0"},duration{0.5}},
PlayAnimation{_delay{0},ActorId{210012},AnimationId{"Angry01_Start"},Duration{2}}
}]],
          SpeakNpcId = 210012,
          Subtitle = "Crowsong Hollow? Whose idea was that?",
          TalkActionId = {
            [1] = "210010:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165A38"
        },
        [12018605] = {
          Camera = "-107.528519,199.333679,246.244141,0.000131,-27.816887,-94.392662,35.0,212.235535,false,Manual,6.0",
          ContentFR = "...",
          DialogueId = 12018605,
          FacialId = {
            [1] = "210010:CM_Shock01"
          },
          GUID = "1E165A62",
          NextDialogue = 12018606,
          SpeakNpcId = 210010,
          Subtitle = "...",
          TalkActionId = {
            [1] = "210010:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165A62"
        },
        [12018606] = {
          Camera = "-103.426682,207.213165,221.943604,0.000147,-24.816774,-27.574326,35.000008,245.026596,false,Manual,22.0",
          ContentFR = "Cet endroit pose problème ?",
          DialogueId = 12018606,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E165A8C",
          LookAt = {
            [1] = "100001:n(210012)"
          },
          NextDialogue = 12018607,
          SpeakNpcId = 100001,
          Subtitle = "Is there something wrong with that place?",
          VoiceName = "voice/$Locale$/story/1201/120186/1E165A8C"
        },
        [12018607] = {
          Camera = "-14.455,160.474716,158.683838,0.000099,-0.817505,-128.967682,35.0,196.648346,false,Manual,6.0",
          ContentFR = "Eh bien... c’est un ancien champ de bataille. Le vent y gémit sans cesse, personne n’ose s’y aventurer... On pensait que ça éviterait les interférences...",
          DialogueId = 12018607,
          FacialId = {
            [1] = "210010:CM_Sad01"
          },
          GUID = "1E165AB6",
          NextDialogue = 12018608,
          SpeakNpcId = 210010,
          Subtitle = "Well, sir... it's part of the ancient battlefield — cold winds, eerie as can be. Nobody goes near it, so we thought it would be safer — less chance of interruption...",
          TalkActionId = {
            [1] = "210010:Shock_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165AB6"
        },
        [12018608] = {
          Camera = "-208.853943,31.453308,168.279785,0.00011,-6.41742,16.636448,25.0,316.576935,false,Manual,6.0",
          ContentFR = "C’est bien là que s’est déroulée la Bataille de Shuli. Mais sais-tu ce que cet endroit était auparavant ?",
          DialogueId = 12018608,
          GUID = "1E165AE0",
          LookAt = {
            [1] = "100001:n(210010)"
          },
          NextDialogue = 12018609,
          SpeakNpcId = 210012,
          Subtitle = "This was indeed the site of the Battle of Shuli. But do you know what it was before that?",
          TalkActionId = {
            [1] = "210012:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165AE0"
        },
        [12018609] = {
          ContentFR = "Euh... non, chef. J’ignore tout de ça.",
          DialogueId = 12018609,
          GUID = "1E165B0A",
          NextDialogue = 12018610,
          SpeakNpcId = 210010,
          Subtitle = "Uh... no, sir. Please, enlighten us.",
          TalkActionId = {
            [1] = "210010:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165B0A"
        },
        [12018610] = {
          Camera = "-2403.743896,115.38797,1248.473267,0.00005,-28.217525,2.442638,25.0,316.576935,false,Manual,22.0",
          ContentFR = "Autrefois, ce lieu était un centre de recherche majeur de la Secte Jishu. Il y a quelques siècles, la Secte Xuanheng, soupçonnant une rébellion, y envoya de lourdes troupes pour mater toute résistance.",
          DialogueId = 12018610,
          FinalCamera = "-2292.674805,-508.969971,1248.90564,0.000039,-28.817556,18.043545,25.0,316.576935,false,Manual,22.0",
          GUID = "1E165B34",
          LookAt = {
            [1] = "210012:p(48_lookat)"
          },
          NextDialogue = 12018611,
          Scripts = [[
PARA{
CameraMoveTo{_delay{4},TargetPosition{"101.46463,2433.009766,1018.791992,0.000078,-9.019374,-144.965591,14.0,316.576935,false,Manual,22.0"},duration{0}},
CameraMoveTo{_delay{4.1},TargetPosition{"-306.286438,2143.177002,1099.884155,0.000079,19.780664,-144.165909,14.0,316.576935,false,Manual,22.0"},duration{10}}
}]],
          SpeakNpcId = 210012,
          Subtitle = "Long ago, this place served as a key research ground for the Jishu Sect — until a few centuries past, when the Xuanheng Sect grew suspicious of rebellion and sent in a heavy force to put it down.",
          TalkActionId = {
            [1] = "210012:Talk03_Start",
            [2] = "210010:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120186/1E165B34"
        },
        [12018611] = {
          Camera = "-92.525726,134.76416,116.622314,0.000168,23.376129,15.452583,25.000002,141.235916,false,Manual,22.0",
          ContentFR = "Les deux camps furent anéantis. Pas un survivant. La Secte Jishu sombra alors dans l’oubli.",
          DialogueId = 12018611,
          GUID = "1E165B5E",
          LookAt = {
            [1] = "210012:n(210012)"
          },
          NextDialogue = 12018612,
          SpeakNpcId = 210012,
          Subtitle = "In the end, both sides were lost — no survivors. From then on, the Jishu Sect faded into obscurity.",
          TalkActionId = {
            [1] = "210012:Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120186/1E165B5E"
        },
        [12018612] = {
          Camera = "-182.100525,11.012974,170.185303,0.000135,-6.422201,31.032133,25.0,57.624985,false,Manual,6.0",
          ContentFR = "Les hommes disparaissent... mais leurs œuvres demeurent.",
          DialogueId = 12018612,
          FinalCamera = "-182.100525,11.012974,170.185303,0.000135,-6.422201,31.032133,25.0,257.755127,false,Manual,6.0",
          GUID = "1E165B88",
          LookAt = {
            [1] = "210012:p(48_lookat)"
          },
          NextDialogue = 12018613,
          Scripts = "LookAt{_delay{3},LookAtDescription{\"210012:n(210010)\"}}",
          SpeakNpcId = 210012,
          Subtitle = "Those who vanished into the mists of history... left behind what they had crafted.",
          TalkActionId = {
            [1] = "210012:Talk03ToThink_End"
          },
          ToFinalCameraBlendTime = 1.2,
          VoiceName = "voice/$Locale$/story/1201/120186/1E165B88"
        },
        [12018613] = {
          ContentFR = "Les mécanismes de ce lieu sont perdus depuis longtemps. S’ils venaient à s’activer par inadvertance... les conséquences seraient imprévisibles.",
          DialogueId = 12018613,
          GUID = "1E165BB2",
          LookAt = {
            [1] = "210012:n(210010)"
          },
          NextDialogue = 12018614,
          SpeakNpcId = 210012,
          Subtitle = "The mechanisms here have long been concealed by time. Should any be carelessly triggered... the consequences could be unpredictable.",
          VoiceName = "voice/$Locale$/story/1201/120186/1E165BB2"
        },
