        },
        [12019501] = {
          ContentFR = "Ha ! Enfin l’occasion de dérouiller un peu mes muscles !",
          DialogueId = 12019501,
          GUID = "1E16ED62",
          NextDialogue = 12019502,
          SpeakNpcId = 210021,
          Subtitle = "Finally — time to limber up!",
          VoiceName = "voice/$Locale$/story/1201/120195/1E16ED62"
        },
        [12019502] = {
          ContentFR = "Être coincé ici m’a complètement rouillé... Mais dès qu’il s’agit de se battre, je ne connais plus la fatigue ! Regarde bien, {nickname} !",
          DialogueId = 12019502,
          GUID = "1E16ED8C",
          SpeakNpcId = 210021,
          Subtitle = "I've been cooped up here so long I couldn't even get a proper swing in... but now? A fight's just the thing to wake me up! Watch close,  — this is what I'm made of!",
          VoiceName = "voice/$Locale$/story/1201/120195/1E16ED8C"
        },
        [12019601] = {
          ContentFR = "Ces configurations deviennent de plus en plus complexes... Ça me donne le tournis.",
          DialogueId = 12019601,
          GUID = "1E16FDCA",
          NextDialogue = 12019602,
          SpeakNpcId = 210021,
          Subtitle = "These arrangements are getting more and more complicated... I can't make heads or tails of them anymore.",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FDCA"
        },
        [12019602] = {
          ContentFR = "Hmph ! Les grands costauds ne savent que cogner — pour réfléchir, il faut notre petit larbin !",
          DialogueId = 12019602,
          GUID = "1E16FDF4",
          NextDialogue = 12019603,
          SpeakNpcId = 200002,
          Subtitle = "Hmph! Big guys like you are only muscles — this kind of brain work? Leave it to my Little Minion!",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FDF4"
        },
        [12019603] = {
          ContentFR = "Exactement, exactement ! On compte sur toi, {nickname} !",
          DialogueId = 12019603,
          GUID = "1E16FE1E",
          NextDialogue = 12019604,
          SpeakNpcId = 210021,
          Subtitle = "Right, right... we're counting on you, !",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FE1E"
        },
        [12019604] = {
          ContentFR = "... Vous êtes insortables.",
          DialogueId = 12019604,
          GUID = "1E16FE48",
          SpeakNpcId = 100001,
          Subtitle = "...Fine.",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FE48"
        },
        [12019605] = {
          ContentFR = "Petit larbin, tu vois cette sphère suspendue dans les airs ? Elle a l’air louche... Et si on essayait avec le Nexus mécanique ?",
          DialogueId = 12019605,
          GUID = "1E16FE72",
          SpeakNpcId = 200002,
          Subtitle = "Hey, Little Minion — look at that orb floating up there. It's kinda suspicious, don't you think? Maybe try using the Mechanical Nexus on it?",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FE72"
        },
        [12019606] = {
          ContentFR = "Oh ! D’un coup, on est déjà de l’autre côté — quel pied !",
          DialogueId = 12019606,
          GUID = "1E16FE9C",
          SpeakNpcId = 210021,
          Subtitle = "What a leap! That was thrilling!",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FE9C"
        },
        [12019610] = {
          ContentFR = "Mais... Ce mécanisme me dit quelque chose... Ce n’est pas celui que Maître Gongshang nous avait enseigné ?",
          DialogueId = 12019610,
          GUID = "1E16FE9F",
          NextDialogue = 12019611,
