          GUID = "1E16FF11",
          NextDialogue = 12019612,
          SpeakNpcId = 200002,
          Subtitle = "Let's try using that Mechanical Nexus right now!",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FF11"
        },
        [12019612] = {
          ContentFR = "Le... Nexus méca-quoi ? Ce serait pas le nom d’une épée légendaire, par hasard ?",
          DialogueId = 12019612,
          GUID = "1E16FF12",
          NextDialogue = 12019613,
          SpeakNpcId = 210021,
          Subtitle = "The... Mechanical what? Is that the name of some top-tier sword?",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FF12"
        },
        [12019613] = {
          ContentFR = "Inculte ! C’est la toute dernière invention de la Secte Jishu ! Contente-toi de regarder !",
          DialogueId = 12019613,
          GUID = "1E16FF13",
          SpeakNpcId = 200002,
          Subtitle = "So uncultured! It's the hottest invention from Jishu Sect! Just stand back and watch!",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FF13"
        },
        [12019616] = {
