          GUID = "1E16FF16",
          NextDialogue = 12019619,
          SpeakNpcId = 200002,
          Subtitle = "Big guy, you'd better stick close. If you get lost, you're on your own!",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FF16"
        },
        [12019619] = {
          ContentFR = "<I>Pas bon... Snow prend clairement confiance. Un peu trop, même.</>",
          DialogueId = 12019619,
          GUID = "1E16FF17",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(Yikes, Snow's getting a bit full of herself... She's practically floating on air!)",
          VoiceName = "voice/$Locale$/story/1201/120196/1E16FF17"
        },
        [12019701] = {
          ContentFR = "Encore ces Stèles de l’Éveil... Il faudra que deux personnes les frappent en même temps. Ensuite, la plateforme se retournera et nous dispersera.",
          DialogueId = 12019701,
          GUID = "1E170E32",
          NextDialogue = 12019702,
          SpeakNpcId = 100001,
          Subtitle = "It's those Steles again... here's how it works: we'll have to strike them both at once. Then the platform will flip, dropping us in different places.",
