          DialogueId = 12019702,
          GUID = "1E170E5C",
          SpeakNpcId = 210021,
          Subtitle = "Then this is goodbye. Thank you both for the company — until we cross paths again!",
          VoiceName = "voice/$Locale$/story/1201/120197/1E170E5C"
        },
        [12019800] = {
          Content = "虬先生就在前面。【废弃】",
          DialogueId = 12019800,
          GUID = "1E170E5D",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1201/120198/1E170E5D"
        },
        [12019801] = {
          ContentFR = "Vous racontez à Maître Qiu ce qui s’est passé pendant votre séparation.",
          DialogueId = 12019801,
          GUID = "1E171E9A",
          SpeakNpcId = 100001,
          Subtitle = "You recount to Mr Qiu everything that happened while you were separated.",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171E9A"
        },
        [12019802] = {
          ContentFR = "Encore des imprévus, à ce que je vois... Hm. Cette chasse devient de plus en plus savoureuse.",
          DialogueId = 12019802,
          GUID = "1E171EC4",
          NextDialogue = 12019803,
          SpeakNpcId = 210012,
          Subtitle = "So... even more twists to our little hunt... Heh. It grows more and more intriguing.",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171EC4"
        },
        [12019803] = {
          ContentFR = "J’ai passé assez de temps dans cet endroit. Continuons d’avancer — quittons ces ruines au plus vite.",
          DialogueId = 12019803,
          GUID = "1E171EEE",
          SpeakNpcId = 210012,
          Subtitle = "I've had my fill of this place. Let's keep moving and be done with it.",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171EEE"
        },
        [12019804] = {
          ContentFR = "Ha ha... Vous maniez de mieux en mieux les jouets de la Secte Jishu. Alors ? Toujours aussi divertissant ?",
          DialogueId = 12019804,
          Duration = 3,
          GUID = "1E171F18",
          SpeakNpcId = 210012,
          Subtitle = "Heh... you're getting rather good with these Jishu Sect trinkets. Quite the amusement, wouldn't you say?",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171F18"
        },
        [12019805] = {
          ContentFR = "Il semble que nous soyons arrivés à l’épreuve ultime. Allons-y, {nickname}. Il est temps d’en finir.",
          DialogueId = 12019805,
          Duration = 2,
          GUID = "1E171F42",
          SpeakNpcId = 210012,
          Subtitle = "Looks like this is the final trial. Come,  — it is time to bring it all to an end.",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171F42"
        },
        [12019810] = {
          ContentFR = "C’est quoi... ce gigantesque colosse de bronze ?!",
          DialogueId = 12019810,
          GUID = "1E171F43",
          SpeakNpcId = 100001,
          Subtitle = "What's this giant bronze guy?!",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171F43"
        },
        [12019811] = {
          ContentFR = "Voici le <H>Terracolosse</> — une création antique de la Secte Jishu.",
          DialogueId = 12019811,
          GUID = "1E171F44",
          SpeakNpcId = 210012,
          Subtitle = "This is Terracolossus, the ancient creation of Jishu Sect.",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171F44"
        },
        [12019812] = {
          ContentFR = "On raconte que la Secte Jishu tenta jadis de concevoir des automates humanoïdes géants pilotables par l’homme. Terracolosse est l’un des vestiges de cette ambition.",
          DialogueId = 12019812,
          GUID = "1E171F45",
          SpeakNpcId = 210012,
          Subtitle = "Legends say the Jishu Sect once sought to develop giant, humanoid-shaped mechapuppets pilotable for humans. I assume this thing witnessed that piece of history.",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171F45"
        },
        [12019813] = {
          ContentFR = "Eh... Ça a l’air plutôt stylé, en fait...",
          DialogueId = 12019813,
          GUID = "1E171F46",
          SpeakNpcId = 200002,
          Subtitle = "Hey, that actually sounds kinda cool...",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171F46"
        },
        [12019814] = {
          ContentFR = "S’il existe vraiment des machines que l’on peut piloter, le Roi Démon aimerait beaucoup essayer !",
          DialogueId = 12019814,
          GUID = "1E171F47",
          SpeakNpcId = 200002,
          Subtitle = "If such mechapuppets really exist, the Demon King would want to try!",
          VoiceName = "voice/$Locale$/story/1201/120198/1E171F47"
        },
        [12019901] = {
          ContentFR = "Cette petite partie de chasse... touche à sa fin. N’est-ce pas, Magistrat de Yingtian ?",
          DialogueId = 12019901,
          GUID = "1E172F02",
          NextDialogue = 12019902,
          RelatedWikiId = {
            [1] = 203005,
            [2] = 203004
          },
          SpeakNpcId = 210012,
          Subtitle = "This little game of cat and mouse... it ends here. Wouldn't you agree, dear Magistrate of Yingtian?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172F02"
        },
        [12019902] = {
          ContentFR = "...",
          DialogueId = 12019902,
          GUID = "1E172F2C",
          NextDialogue = 12019903,
          SpeakNpcId = 210007,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172F2C"
        },
        [12019903] = {
          ContentFR = "Yuming... ?",
          DialogueId = 12019903,
          GUID = "1E172F56",
          NextDialogue = 12019904,
          SpeakNpcId = 100001,
          Subtitle = "Yuming!?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172F56"
        },
        [12019904] = {
          ContentFR = "Le \"Bi’an\" dont vous parliez... C’était lui, depuis le début ?",
          DialogueId = 12019904,
          GUID = "1E172F80",
          NextDialogue = 12019905,
          SpeakNpcId = 100001,
          Subtitle = "The \"Bi'an\" you've been talking about — you meant him all along?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172F80"
        },
        [12019905] = {
          ContentFR = "Encore un tour de passe-passe verbal. {性别:Désolé|Désolée}, mais moi, j’arrête là.",
          DialogueId = 12019905,
          GUID = "1E172FAA",
          NextDialogue = 12019906,
          SpeakNpcId = 100001,
          Subtitle = "That's it. I'm out.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172FAA"
        },
        [12019906] = {
          ContentFR = "Même un Roi Démon a ses limites !",
          DialogueId = 12019906,
          GUID = "1E172FD4",
          NextDialogue = 12019907,
          SpeakNpcId = 200002,
          Subtitle = "Even the Demon King has lines she won't cross!",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172FD4"
        },
        [12019907] = {
          ContentFR = "Du calme, {性别:mon jeune ami|ma jeune amie}.",
          DialogueId = 12019907,
          GUID = "1E172FFE",
          NextDialogue = 12019908,
          SpeakNpcId = 210012,
          Subtitle = "Easy now, young friend.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E172FFE"
        },
        [12019908] = {
          ContentFR = "Pourquoi réagissez-vous comme si je voulais lui ôter la vie ? C’est tout l’inverse. Je souhaite lui offrir une chance de se libérer des chaînes des Neuf Chapitres de Dafeng.",
          DialogueId = 12019908,
          GUID = "1E173028",
          NextDialogue = 12019909,
          SpeakNpcId = 210012,
          Subtitle = "Why do you both act as though I intend to kill him? Quite the opposite — I mean to offer him a chance to break free of the Nine Chapters' shackles.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E173028"
        },
        [12019909] = {
          ContentFR = "Et vous lui avez demandé son avis ?",
          DialogueId = 12019909,
          GUID = "1E173052",
          NextDialogue = 12019910,
          SpeakNpcId = 100001,
          Subtitle = "And did you ever ask him if he wanted that?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E173052"
        },
        [12019910] = {
          ContentFR = "Ce que vous faites met déjà en péril les peuples et l’équilibre du monde. Je vous en prie... renoncez.",
          DialogueId = 12019910,
          GUID = "1E17307C",
          NextDialogue = 12019911,
          SpeakNpcId = 210007,
          Subtitle = "Your actions have already endangered the people and the realm. I ask that you stand down.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E17307C"
        },
        [12019911] = {
          ContentFR = "Hm... Suis-je vraiment celui qui met ce monde en danger ? Ou bien est-ce ce monde lui-même qui est déjà en train de se disloquer ? Les dérives causées par les Neuf Chapitres... peux-tu vraiment les ignorer ?",
          DialogueId = 12019911,
          GUID = "1E1730A6",
          NextDialogue = 12019912,
          SpeakNpcId = 210012,
          Subtitle = "Hehe... tell me — am I the one endangering the realm, or is it the manners and morals of the age? Will you pretend not to see the cracks the Nine Chapters have wrought?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E1730A6"
        },
        [12019912] = {
          ContentFR = "Si je pouvais comprendre le mécanisme qui t’a transformé en Magistrat de Yingtian,\nj’obtiendrais un moyen de contrer les Bi’an obscurs... et peut-être même de te rendre ta liberté. N’est-ce pas une issue idéale pour tous ?",
          DialogueId = 12019912,
          GUID = "1E1730D0",
          NextDialogue = 12019913,
          SpeakNpcId = 210012,
          Subtitle = "If I could decipher the means by which you became a Magistrate of Yingtian, I might forge a counter to the Sable Bi'an — and perhaps grant you the freedom you seek. Would that not be a fitting outcome for all?",
          VoiceName = "voice/$Locale$/story/1201/120199/1E1730D0"
        },
        [12019913] = {
          ContentFR = "... Ce n’est pas à vous de décider cela.",
          DialogueId = 12019913,
          GUID = "1E1730FA",
          NextDialogue = 12019914,
          SpeakNpcId = 210007,
          Subtitle = "...This is not your burden to bear.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E1730FA"
        },
        [12019914] = {
          ContentFR = "Il a dit non. Alors je ne vous aiderai pas.",
          DialogueId = 12019914,
          GUID = "1E173124",
          NextDialogue = 12019915,
          SpeakNpcId = 100001,
          Subtitle = "He's made himself clear. I won't help you.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E173124"
        },
        [12019915] = {
          ContentFR = "Toujours cette morale ennuyeuse... <I>Tss.</> J’espérais éviter d’en arriver là.",
          DialogueId = 12019915,
          GUID = "1E17314E",
          SpeakNpcId = 210012,
          Subtitle = "Still clinging to your tiresome pretence of duty and honour, I see... Tsk. I had hoped it wouldn't come to this.",
          VoiceName = "voice/$Locale$/story/1201/120199/1E17314E"
        },
        [12020001] = {
          ContentFR = "Hé— ! Qu’est-ce que tu fais ?!",
          DialogueId = 12020001,
          Duration = 2,
          GUID = "1E173F6A",
          SpeakNpcId = 200002,
          Subtitle = "Wh—What are you doing!?",
          VoiceName = "voice/$Locale$/story/1201/120200/1E173F6A"
        },
        [12020002] = {
          ContentFR = "{nickname}. Tu refuses de lever la main sur lui... mais lui n’a pas hésité à retourner son arme contre toi.",
          DialogueId = 12020002,
          Duration = 3,
          GUID = "1E173F94",
          SpeakNpcId = 210012,
          Subtitle = ", you wouldn't raise your blade against him — but he was all too ready to strike at you.",
          VoiceName = "voice/$Locale$/story/1201/120200/1E173F94"
        },
        [12020003] = {
          ContentFR = "Alors ? Magistrat de Yingtian. La victime est là, sous tes yeux. Vas-tu rester spectateur ? Ce ne serait guère conforme aux règles des Neuf Chapitres, n’est-ce pas ?",
          DialogueId = 12020003,
          Duration = 5,
          GUID = "1E173FBE",
          SpeakNpcId = 210012,
          Subtitle = "Well then, Magistrate of Yingtian — your victim stands before you. Will you stand by and do nothing? That is not what the Nine Chapters dictates.",
          VoiceName = "voice/$Locale$/story/1201/120200/1E173FBE"
        },
        [12020004] = {
          ContentFR = "... Honte à toi ! C’est toi qui as attaqué en premier !",
          DialogueId = 12020004,
          Duration = 3,
          GUID = "1E173FE8",
          SpeakNpcId = 200002,
          Subtitle = "...Shame on you!! You attacked my Little Minion first!",
          VoiceName = "voice/$Locale$/story/1201/120200/1E173FE8"
        },
        [12020005] = {
          ContentFR = "Ha ha ha ! Vous ne jugez que la blessure... jamais l’intention, ni la justice. Est-ce donc cela que tu protèges, Magistrat ? Une loi morte, vidée de sens ?",
          DialogueId = 12020005,
          Duration = 5,
          GUID = "1E174012",
          SpeakNpcId = 210012,
          Subtitle = "Hahaha...! Exactly. Punishing only those who have drawn blood, without regard for motive or for justice. Is this blind dogma what you fight to uphold?",
          VoiceName = "voice/$Locale$/story/1201/120200/1E174012"
        },
        [12020006] = {
          ContentFR = "... {nickname}, pardonne-moi. Ce n’est pas ma volonté.",
          DialogueId = 12020006,
          Duration = 2,
          GUID = "1E17403C",
          SpeakNpcId = 210007,
          Subtitle = "...Forgive me, . This is not my will.",
          VoiceName = "voice/$Locale$/story/1201/120200/1E17403C"
        },
        [12020101] = {
          ContentFR = "Observe bien mes mouvements. Esquive avec soin.",
          DialogueId = 12020101,
          Duration = 2,
          GUID = "1E174FD2",
          NextDialogue = 12020102,
          SpeakNpcId = 210007,
          Subtitle = "Watch my moves closely — and dodge carefully.",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174FD2"
        },
        [12020102] = {
          ContentFR = "Je ferai tout pour résister aux Neuf Chapitres de Dafeng... Ne te blesse pas.",
          DialogueId = 12020102,
          Duration = 3,
          GUID = "1E174FFC",
          SpeakNpcId = 210007,
          Subtitle = "I'll resist the Nine Chapters' commands with all I have... Please — don't let yourself be hurt.",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174FFC"
        },
        [12020103] = {
          ContentFR = "{nickname}... la prochaine attaque arrive. Prudence.",
          DialogueId = 12020103,
          GUID = "1E174FFD",
          NextDialogue = 12020104,
          SpeakNpcId = 210007,
          Subtitle = ", the next strike... Be wary.",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174FFD"
        },
        [12020104] = {
          ContentFR = "Son offensive est beaucoup trop violente ! Alors voilà le véritable pouvoir des Neuf Chapitres...",
          DialogueId = 12020104,
          GUID = "1E174FFF",
          NextDialogue = 12020105,
          SpeakNpcId = 200002,
          Subtitle = "The assault is too fierce! So this is the power of the Nine Chapters...",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174FFF"
        },
        [12020105] = {
          ContentFR = "Petit larbin ! Tu tiens le coup ?!",
          DialogueId = 12020105,
          GUID = "1E174111",
          NextDialogue = 12020106,
          SpeakNpcId = 200002,
          Subtitle = "What do we do, Little Minion? Are you alright?!",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174111"
        },
        [12020106] = {
          ContentFR = "Ça va. Yuming... et toi ?",
          DialogueId = 12020106,
          GUID = "1E174112",
          NextDialogue = 12020107,
          SpeakNpcId = 100001,
          Subtitle = "Don't worry, I can handle it. Yuming, are you okay?",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174112"
        },
        [12020107] = {
          ContentFR = "... Ne t’inquiète pas pour moi. Je mettrai fin à cette folie au plus vite.",
          DialogueId = 12020107,
          GUID = "1E174113",
          SpeakNpcId = 210007,
          Subtitle = "Do not concern yourself with me. I shall put an end to this with all haste.",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174113"
        },
        [12020108] = {
          ContentFR = "Arrêtez... s’il vous plaît...",
          DialogueId = 12020108,
          GUID = "1E174114",
          NextDialogue = 12020109,
          SpeakNpcId = 200002,
          Subtitle = "Stop it, please...",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174114"
        },
        [12020109] = {
          ContentFR = "Mais pourquoi vous vous battez ?! Ça m’énerve !",
          DialogueId = 12020109,
          GUID = "1E174115",
          NextDialogue = 12020110,
          SpeakNpcId = 200002,
          Subtitle = "Why do you two have to fight like this? It's so frustrating!",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174115"
        },
        [12020110] = {
          ContentFR = "C’est la faute des Neuf Chapitres, ils sont nuls... Non— ce type est encore pire !",
          DialogueId = 12020110,
          GUID = "1E174116",
          NextDialogue = 12020111,
          SpeakNpcId = 200002,
          Subtitle = "Stupid Nine Chapters... No, wait! That despicable guy is definitely worse!",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174116"
        },
        [12020111] = {
          ContentFR = "Ha ha... Puis-je prendre cela pour un compliment ?",
          DialogueId = 12020111,
          GUID = "1E174117",
          SpeakNpcId = 210012,
          Subtitle = "Heh. May I take that as a compliment?",
          VoiceName = "voice/$Locale$/story/1201/120201/1E174117"
        },
        [12020201] = {
          ContentFR = "Hé ! Vous avez perdu la tête ou quoi ?! À plusieurs contre mon frère d’armes ?!",
          DialogueId = 12020201,
          Duration = 2,
          GUID = "1E17603A",
          SpeakNpcId = 210021,
          Subtitle = "Hey! You lot - what the hell are you all doing here, ganging up on my shixiong!?",
          VoiceName = "voice/$Locale$/story/1201/120202/1E17603A"
        },
        [12020202] = {
          ContentFR = "Chef ! Il essaie de fuir... !",
          DialogueId = 12020202,
          Duration = 2,
          GUID = "1E176064",
          Subtitle = "Boss, he's trying to get away...!",
          VoiceName = "voice/$Locale$/story/1201/120202/1E176064"
        },
        [12020203] = {
          ContentFR = "Baissez vos armes.",
          DialogueId = 12020203,
          Duration = 2,
          GUID = "1E17608E",
          SpeakNpcId = 210012,
          Subtitle = "Stand down.",
          VoiceName = "voice/$Locale$/story/1201/120202/1E17608E"
        },
        [12020204] = {
          ContentFR = "Mais alors tout ce qu’on a fait—",
          DialogueId = 12020204,
          Duration = 2,
          GUID = "1E1760B8",
          Subtitle = "If we let him—",
          VoiceName = "voice/$Locale$/story/1201/120202/1E1760B8"
        },
        [12020205] = {
          ContentFR = "Ce n’est pas grave.",
          DialogueId = 12020205,
          Duration = 1,
          GUID = "1E1760E2",
          SpeakNpcId = 210012,
          Subtitle = "It's alright.",
          VoiceName = "voice/$Locale$/story/1201/120202/1E1760E2"
        },
        [12020301] = {
          Camera = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Quelle poisse. J’avais enfin retrouvé mon frère d’armes... et voilà qu’on me l’arrache encore.",
          DialogueId = 12020301,
          GUID = "1E1770A2",
          NextDialogue = 12020302,
          RelatedWikiId = {
            [1] = 203007,
            [2] = 203004,
            [3] = 203005
          },
          SpeakNpcId = 210021,
          Subtitle = "Finally got to see my shixiong again, only for you lot to ruin everything. Now he's slipped away once more.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1770A2"
        },
        [12020302] = {
          ContentFR = "Ces gâteaux à l’osmanthe... Je les gardais sur moi depuis si longtemps qu’ils sont devenus froids et durs. Qui sait quand il pourra enfin y goûter...",
          DialogueId = 12020302,
          GUID = "1E1770CC",
          NextDialogue = 12020303,
          SpeakNpcId = 210021,
          Subtitle = "This osmanthus cake... I've been carrying it around for so long, it's gone cold and hard. Who knows when I'll ever get to give it to him?",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1770CC"
        },
        [12020303] = {
          ContentFR = "Alors... la personne que tu cherchais, c’était Yuming.",
          DialogueId = 12020303,
          GUID = "1E1770F6",
          NextDialogue = 12020304,
          SpeakNpcId = 100001,
          Subtitle = "So the one you've been looking for was Yuming.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1770F6"
        },
        [12020304] = {
          ContentFR = "Dis-moi plutôt — qu’est-ce que tu faisais ici ? Avant que j’arrive, il s’est passé quoi, exactement ?",
          DialogueId = 12020304,
          GUID = "1E177120",
          NextDialogue = 12020305,
          SpeakNpcId = 210021,
          Subtitle = "Say... what are you doing here? What exactly happened here before I came?",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177120"
        },
        [12020305] = {
          ContentFR = "<I>Raconter ce qui s’est passé</>",
          DialogueId = 12020305,
          GUID = "1E17714A",
          IsBlack = 1,
          NextDialogue = 12020306,
          Subtitle = "(Fill him in)",
          VoiceName = "voice/$Locale$/story/1201/120203/1E17714A"
        },
        [12020306] = {
          ContentFR = "Mais c’est quoi ce type ?! Il t’a manipulé comme un pion ! Dis-moi que tu n’es pas {性别:blessé|blessée}, {nickname} ?!",
          DialogueId = 12020306,
          GUID = "1E177174",
          NextDialogue = 12020307,
          SpeakNpcId = 210021,
          Subtitle = "That bastard — he set you up, didn't he!? , are you hurt?",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177174"
        },
        [12020307] = {
          ContentFR = "Ça m’énerve... Mon frère d’armes est ligoté par toutes ces règles absurdes. Moi, je n’ai aucune chaîne. Quiconque s’en prend à lui... je lui ferai payer.",
          DialogueId = 12020307,
          GUID = "1E17719E",
          NextDialogue = 12020308,
          SpeakNpcId = 210021,
          Subtitle = "Damn it... my shixiong's tied down by those nonsense rules, but I'm not. Anyone who messes with him — I'll make sure they pay for it!",
          VoiceName = "voice/$Locale$/story/1201/120203/1E17719E"
        },
        [12020308] = {
          ContentFR = "Ça fait longtemps que cette bande me sort par les yeux aussi ! On pourrait tout raser ensemble, non ?!",
          DialogueId = 12020308,
          GUID = "1E1771C8",
          NextDialogue = 12020309,
          SpeakNpcId = 200002,
          Subtitle = "I've had it with those people too! Let's team up and turn this whole place upside down!",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1771C8"
        },
        [12020309] = {
          ContentFR = "Allons, allons... inutile de vous emporter. J’ai parfaitement entendu votre conversation. Si des excuses peuvent apaiser les choses, je vous les présente.",
          DialogueId = 12020309,
          GUID = "1E1771F2",
          NextDialogue = 12020310,
          SpeakNpcId = 210012,
          Subtitle = "Alright, alright — no need for all this fuss. I heard every word, clear as day. Consider this my most humble apology.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1771F2"
        },
        [12020310] = {
          ContentFR = "Gardez-les. Je n’ai pas encore digéré ce que vous avez fait.",
          DialogueId = 12020310,
          GUID = "1E17721C",
          NextDialogue = 12020311,
          SpeakNpcId = 100001,
          Subtitle = "You'd better keep your mouth shut. I'm still mad at you.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E17721C"
        },
        [12020311] = {
          ContentFR = "Si je ne vous attaque pas, ce n’est pas par clémence. C’est parce que je refuse de devenir quelqu’un comme vous.",
          DialogueId = 12020311,
          GUID = "1E177246",
          NextDialogue = 12020312,
          SpeakNpcId = 100001,
          Subtitle = "The only reason I'm not coming after you right now is because I refuse to stoop to your level.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177246"
        },
        [12020312] = {
          ContentFR = "Très bien, très bien. Quelle grandeur d’âme.",
          DialogueId = 12020312,
          GUID = "1E177270",
          NextDialogue = 12020313,
          SpeakNpcId = 210012,
          Subtitle = "Fair enough. Such magnanimity is admirable, young friend.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177270"
        },
        [12020313] = {
          ContentFR = "Ta loyauté est sincère, et elle force le respect. Je consens donc à assumer l’échec de cette mission... et à relâcher la proie. Quant à Zhiliu, je m’en expliquerai moi-même.",
          DialogueId = 12020313,
          GUID = "1E17729A",
          NextDialogue = 12020314,
          SpeakNpcId = 210012,
          Subtitle = "And your loyalty... truly stirring. You have my respect. I'll gladly shoulder the blame for this failure: I'll let the \"prey\" go out of deference to you. As for Proprietress Zhiliu, I'll explain to her myself.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E17729A"
        },
        [12020314] = {
          ContentFR = "C’est vraiment ce que voulait Zhiliu ? Je ne vous crois pas. Et cessez de l’appeler « la proie ».",
          DialogueId = 12020314,
          GUID = "1E1772C4",
          NextDialogue = 12020315,
          SpeakNpcId = 100001,
          Subtitle = "Are you saying this is all Proprietress Zhiliu's idea? I don't buy it. And another thing — stop calling him the \"prey.\"",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1772C4"
        },
        [12020315] = {
          ContentFR = "Ha ha... Comme je vous l’ai déjà dit, Zhiliu a ses propres raisons.",
          DialogueId = 12020315,
          GUID = "1E1772EE",
          NextDialogue = 12020316,
          SpeakNpcId = 210012,
          Subtitle = "Haha... as I told you before, the Proprietress has her own designs.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1772EE"
        },
        [12020316] = {
          ContentFR = "Sans votre intervention, j’aurais déjà retrouvé mon frère d’armes ! Alors dis-moi, vieux renard... comment comptes-tu réparer ça ?",
          DialogueId = 12020316,
          GUID = "1E177318",
          NextDialogue = 12020317,
          SpeakNpcId = 210021,
          Subtitle = "If it weren't for you lot butting in, I'd have had a proper reunion with my shixiong! Old Fox — how exactly are you planning to make this right?",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177318"
        },
        [12020317] = {
          ContentFR = "Oh ? À mon avis, le Magistrat de Yingtian vous évite délibérément. S’il était resté, et que vous aviez uni vos forces... qui ici aurait pu vous arrêter ?",
          DialogueId = 12020317,
          GUID = "1E177342",
          NextDialogue = 12020318,
          SpeakNpcId = 210012,
          Subtitle = "Oh? From what I saw, that Magistrate of Yingtian is avoiding you quite deliberately. If he'd stayed behind, and the two of you joined forces — who here could possibly stand in your way?",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177342"
        },
        [12020318] = {
          ContentFR = "La ferme ! Un mot de plus—",
          DialogueId = 12020318,
          GUID = "1E17736C",
          NextDialogue = 12020319,
          SpeakNpcId = 210021,
          Subtitle = "Shut it! Another word and I'll shut it for you myself!",
          VoiceName = "voice/$Locale$/story/1201/120203/1E17736C"
        },
        [12020319] = {
          ContentFR = "Ha ha ha !",
          DialogueId = 12020319,
          GUID = "1E177396",
          NextDialogue = 12020320,
          SpeakNpcId = 210012,
          Subtitle = "Hahahaha!",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177396"
        },
        [12020320] = {
          ContentFR = "J’ai d’autres affaires à régler. Je vous laisse.",
          DialogueId = 12020320,
          GUID = "1E1773C0",
          NextDialogue = 12020321,
          SpeakNpcId = 210012,
          Subtitle = "But enough chatter. I have other matters to attend to. I'll take my leave for now.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1773C0"
        },
        [12020321] = {
          ContentFR = "Un dernier conseil : votre frère d’armes est parti par là. Si vous tardez, vous le perdrez encore.",
          DialogueId = 12020321,
          GUID = "1E1773EA",
          NextDialogue = 12020322,
          SpeakNpcId = 210012,
          Subtitle = "A small piece of advice — Yuming slipped off that way. If you don't hurry, you'll lose him yet again.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E1773EA"
        },
        [12020322] = {
          ContentFR = "Et pour toi, un avertissement. Tout le monde n’agit pas avec la franchise que tu me prêtes. On peut connaître le visage d’un homme... sans jamais connaître son cœur.",
          DialogueId = 12020322,
          GUID = "1E177414",
          SpeakNpcId = 210012,
          Subtitle = "And one last word for you, young friend — not everyone is as candid as I am. You may know a man's face... but never assume you know his heart.",
          VoiceName = "voice/$Locale$/story/1201/120203/1E177414"
        },
        [12020401] = {
          ContentFR = "<I>Pff... </>Son ego vient encore de gagner des niveaux !",
          DialogueId = 12020401,
          Duration = 2,
          GUID = "1E17810A",
          NextDialogue = 12020402,
          SpeakNpcId = 200002,
          Subtitle = "There he goes again — so full of himself!",
          VoiceName = "voice/$Locale$/story/1201/120204/1E17810A"
        },
        [12020402] = {
          ContentFR = "Et sa dernière phrase, là... Ça voulait dire quoi, hein ? Il parle toujours comme s’il cachait quelque chose !",
          DialogueId = 12020402,
          Duration = 3,
          GUID = "1E178134",
          SpeakNpcId = 200002,
          Subtitle = "And what was that last thing he said supposed to mean, anyway? Talking in riddles, that guy...",
          VoiceName = "voice/$Locale$/story/1201/120204/1E178134"
        },
        [12020501] = {
          Camera = "-8.78125,29.299316,151.603027,0.000004,-2.785276,-161.556458,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "<I>Ha...</>",
          DialogueId = 12020501,
          FacialId = {
            [1] = "210021:Unhappy01"
          },
          FinalCamera = "-39.296875,19.130371,149.838379,0.000004,-2.785276,-161.556458,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1E179172",
          LookAt = {
            [1] = "100001:n(210021)",
            [2] = "210021:n(100001)"
          },
          NextDialogue = 12020502,
          SpeakNpcId = 210021,
          Subtitle = "...",
          TalkActionId = {
            [1] = "210021:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120205/1E179172"
        },
        [12020502] = {
          ContentFR = "Dis-moi, {nickname}... Tu étais proche de mon frère d’armes, pas vrai ?",
          DialogueId = 12020502,
          FacialId = {
            [1] = "210021:Think01"
          },
          GUID = "1E17919C",
          NextDialogue = 12020503,
          SpeakNpcId = 210021,
          Subtitle = ", you seem to know my shixiong pretty well.",
          TalkActionId = {
            [1] = "210021:ScratchHead_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120205/1E17919C"
        },
        [12020503] = {
          ContentFR = "Il est devenu Magistrat de Yingtian à cause d’un accident. Mais je le sens... il n’est pas heureux.",
          DialogueId = 12020503,
          FacialId = {
            [1] = "210021:Angry01"
          },
          GUID = "1E1791C6",
          NextDialogue = 12020504,
          SpeakNpcId = 210021,
          Subtitle = "I don't know if you've heard this — he became a Magistrate of Yingtian because of... an accident, a twist of fate. But I can tell — he's not at peace with it.",
          TalkActionId = {
            [1] = "210021:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120205/1E1791C6"
        },
        [12020504] = {
          Camera = "-64.742188,5.019531,189.497314,0.000005,-11.785204,-158.356918,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Si tu le revois, passe-lui un message. Dis-lui que ce qui s’est passé à l’époque... ce n’était pas sa faute. Tout le monde, aux Pics Extérieurs, espère encore son retour.",
          DialogueId = 12020504,
          GUID = "1E1791F0",
          NextDialogue = 12020505,
          SpeakNpcId = 210021,
          Subtitle = "When you meet him again, tell him something for me, will you? Tell him... what happened back then wasn't his fault. Everyone from the Outer Peaks misses him and hopes he'll come back home.",
          VoiceName = "voice/$Locale$/story/1201/120205/1E1791F0"
        },
        [12020505] = {
          Camera = "-286.9375,-213.182617,178.568115,0.000013,-9.985319,62.043591,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "À l’époque... ? Que s’est-il passé ?",
          DialogueId = 12020505,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E17921A",
          NextDialogue = 12020506,
          SpeakNpcId = 100001,
          Subtitle = "What happened back then?",
          TalkActionId = {
            [1] = "210021:Talk02_End",
            [2] = "100001:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1201/120205/1E17921A"
        },
        [12020506] = {
          Camera = "-64.742188,5.019531,189.497314,0.000005,-11.785204,-158.356918,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est compliqué. Impossible à résumer en quelques mots. Je dois le rattraper — on en reparlera une autre fois.",
          DialogueId = 12020506,
          FacialId = {
            [1] = "210021:Uninterested01"
          },
          GUID = "1E179244",
          NextDialogue = 12020507,
          SpeakNpcId = 210021,
          Subtitle = "Uh... it's a long story — too much to explain here. I've got to go after him. I'll tell you another time.",
          TalkActionId = {
            [1] = "210021:Talk01_Start",
            [2] = "100001:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120205/1E179244"
        },
        [12020507] = {
          Camera = "254.949219,-102.718262,275.353027,0.000008,-18.585285,170.644135,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dis-moi... pourquoi est-ce si difficile de vivre comme on l’entend ? Pourquoi faut-il toujours obéir, se contraindre, se retenir ?",
          DialogueId = 12020507,
          FacialId = {
            [1] = "210021:Unhappy01"
          },
          FinalCamera = "465.136719,-137.344727,314.913086,0.000008,-18.585264,170.644104,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1E17926E",
          NextDialogue = 12020508,
          SpeakNpcId = 210021,
          Subtitle = "Tell me,  — why is it so hard for people just to follow their hearts? Why is it that every time we want to act on a whim, we're tied down by all sorts of rules?",
          TalkActionId = {
            [1] = "210021:DisagreeHead"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1201/120205/1E17926E"
        },
        [12020508] = {
          Camera = "-8.78125,29.299316,151.603027,0.000004,-2.785276,-161.556458,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je dois y aller. N’oublie pas notre promesse. La prochaine fois, on boira jusqu’à l’aube... et on parlera jusqu’à plus soif.",
          DialogueId = 12020508,
          FacialId = {
            [1] = "210021:Smile01"
          },
          GUID = "1E179298",
          SpeakNpcId = 210021,
          Subtitle = "I have to go. But don't you forget — next time we meet, we'll drink until dawn and talk till we drop!",
          TalkActionId = {
            [1] = "210021:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1201/120205/1E179298"
        },
        [12020601] = {
          ContentFR = "On a l’impression de vagabonder depuis une éternité... Je me demande comment ça se passe du côté de Zhiliu...",
          DialogueId = 12020601,
          Duration = 3,
          GUID = "1E17A1DA",
          NextDialogue = 12020602,
          SpeakNpcId = 200002,
          Subtitle = "Feels like we've been wandering around forever... I wonder how Proprietress Zhiliu is doing.",
          VoiceName = "voice/$Locale$/story/1201/120206/1E17A1DA"
        },
        [12020602] = {
          ContentFR = "Petit larbin, et si on retournait faire un tour à Éternel Printemps ?",
          DialogueId = 12020602,
          Duration = 2,
          GUID = "1E17A204",
          SpeakNpcId = 200002,
          Subtitle = "C'mon, Little Minion! Let's head back to EverSpring and check in!",
          VoiceName = "voice/$Locale$/story/1201/120206/1E17A204"
        },
        [12020701] = {
          Camera = "428.589844,98.277344,126.54541,0.0,0.0,-179.794739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce bruit... Il s’est passé quelque chose ?",
          DialogueId = 12020701,
          GUID = "1E17B242",
          NextDialogue = 12020702,
          SpeakNpcId = 100001,
          Subtitle = "What was that noise...? What's going on?",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B242"
        },
        [12020702] = {
          ContentFR = "On dirait que la Patronne a achevé les préparatifs à l’Autel de Zhuyin.",
          DialogueId = 12020702,
          GUID = "1E17B26C",
          NextDialogue = 12020703,
          RelatedWikiId = {
            [1] = 408015,
            [2] = 303011
          },
          SpeakNpcId = 210022,
          Subtitle = "It seems that Miss Zhiliu has completed her preparations at the Zhuyin Altar.",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B26C"
        },
        [12020703] = {
          ContentFR = "Elle m’a demandé de vous faire attendre dans le hall si vous veniez la chercher. Une fois le rituel terminé, elle reviendra vous voir en personne.",
          DialogueId = 12020703,
          GUID = "1E17B296",
          NextDialogue = 12020704,
          SpeakNpcId = 210022,
          Subtitle = "She left word — if you came looking for her, you're to wait here in the main hall. Once the ritual is complete, she'll return to meet you.",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B296"
        },
        [12020704] = {
          ContentFR = "Attends— quoi ?! On n’a même pas besoin d’y aller pour aider ?!",
          DialogueId = 12020704,
          GUID = "1E17B2C0",
          NextDialogue = 12020705,
          SpeakNpcId = 200002,
          Subtitle = "Wait, what!? We're just supposed to sit here and do nothing!?",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B2C0"
        },
        [12020705] = {
          ContentFR = "Le scellement de Zhuyin est extrêmement dangereux... Si vous vous y rendez, vous risquez d’être blessés...",
          DialogueId = 12020705,
          GUID = "1E17B2EA",
          NextDialogue = 12020706,
          SpeakNpcId = 210022,
          Subtitle = "Sealing Zhuyin is no simple task. If you go, you could be seriously hurt...",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B2EA"
        },
        [12020706] = {
          ContentFR = "Rooooaaar— !",
          DialogueId = 12020706,
          GUID = "1E17B314",
          NextDialogue = 12020707,
          Subtitle = "Roaaaar—!",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B314"
        },
        [12020707] = {
          ContentFR = "Ça n’a pas l’air de très bien se passer là-bas. Allons-y. Une aide de plus peut faire la différence.",
          DialogueId = 12020707,
          GUID = "1E17B33E",
          NextDialogue = 12020708,
          SpeakNpcId = 100001,
          Subtitle = "That doesn't sound good. We should go — every extra hand could make the difference.",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B33E"
        },
        [12020708] = {
          ContentFR = "Mais... les instructions de la Patronne...",
          DialogueId = 12020708,
          GUID = "1E17B368",
          NextDialogue = 12020709,
          SpeakNpcId = 210022,
          Subtitle = "But... Miss Zhiliu said—",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B368"
        },
        [12020709] = {
          ContentFR = "Allons ! À ce stade, tu hésites encore pour ça ?!",
          DialogueId = 12020709,
          GUID = "1E17B392",
          NextDialogue = 12020710,
          SpeakNpcId = 200002,
          Subtitle = "Oh, come on! In a situation this critical, you can't seriously be fussing over your boss's orders!",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B392"
        },
        [12020710] = {
          ContentFR = "... Très bien. Rendez-vous au point culminant de la Mer de Poussière. Une voie temporaire menant à l’Autel de Zhuyin y a été aménagée.",
          DialogueId = 12020710,
          GUID = "1E17B3BC",
          NextDialogue = 12020711,
          SpeakNpcId = 210022,
          Subtitle = "...Very well. Head to the highest point of the Gritblight Expanse. A temporary path to the Zhuyin Altar has already been prepared.",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B3BC"
        },
        [12020711] = {
          ContentFR = "Hmmm... Je sens l’odeur d’un affrontement final contre un dragon maléfique... Attends— depuis quand c’est une mission de Roi Démon, ça ?!",
          DialogueId = 12020711,
          GUID = "1E17B3E6",
          NextDialogue = 12020712,
          SpeakNpcId = 200002,
          Subtitle = "I can already smell the final showdown with an evil loong— wait, this doesn't sound like a quest for the Demon King...",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B3E6"
        },
        [12020712] = {
          ContentFR = "... Allons-y vite.",
          DialogueId = 12020712,
          GUID = "1E17B410",
          SpeakNpcId = 100001,
          Subtitle = "...Let's get going.",
          VoiceName = "voice/$Locale$/story/1201/120207/1E17B410"
        },
        [12020901] = {
          Camera = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pfiou... C’était vraiment moins une.",
          DialogueId = 12020901,
          GUID = "1E17D312",
          NextDialogue = 12020902,
          RelatedWikiId = {
            [1] = 408015,
            [2] = 303011
          },
          SpeakNpcId = 210005,
          SpeakNpcName = "UI_Npc_Name_Goodshangren",
          Subtitle = "Whew... that was way too close.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D312"
        },
        [12020902] = {
          ContentFR = "Ne relâchez pas votre vigilance. Le sceau supérieur reste instable — je le sens.",
          DialogueId = 12020902,
          GUID = "1E17D33C",
          NextDialogue = 12020903,
          SpeakNpcId = 210004,
          Subtitle = "Do not let your guard down. The upper seal is still unstable — I can feel it shifting.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D33C"
        },
        [12020903] = {
          ContentFR = "Je dois maintenir le point de formation du rituel. Je ne peux pas m’éloigner. Quelqu’un peut-il monter vérifier là-haut ?",
          DialogueId = 12020903,
          GUID = "1E17D366",
          NextDialogue = 12020904,
          SpeakNpcId = 210004,
          Subtitle = "I must maintain the formation here — I cannot leave my post. Can any of you go up and inspect the situation?",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D366"
        },
        [12020904] = {
          ContentFR = "Patronne Zhiliu, je m’en charge.",
          DialogueId = 12020904,
          GUID = "1E17D390",
          NextDialogue = 12020905,
          SpeakNpcId = 100001,
          Subtitle = "Leave it to me, Proprietress Zhiliu.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D390"
        },
        [12020905] = {
          ContentFR = "...{nickname} ? Que fais-tu ici ?",
          DialogueId = 12020905,
          GUID = "1E17D3BA",
          NextDialogue = 12020906,
          SpeakNpcId = 210004,
          Subtitle = "...? What are you doing here?",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D3BA"
        },
        [12020906] = {
          ContentFR = "Votre mission était pourtant achevée. J’avais bien demandé à Wangchun de vous faire patienter à la chambre de commerce.",
          DialogueId = 12020906,
          GUID = "1E17D3E4",
          NextDialogue = 12020907,
          SpeakNpcId = 210004,
          Subtitle = "Your commission was already completed. I explicitly told Wangchun to have you wait in the chamber until I returned.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D3E4"
        },
        [12020907] = {
          ContentFR = "Vu l’ampleur de ce qui se passe ici... Je ne pouvais pas rester sans rien faire. Je voulais voir si je pouvais aider.",
          DialogueId = 12020907,
          GUID = "1E17D40E",
          NextDialogue = 12020908,
          SpeakNpcId = 100001,
          Subtitle = "Things seem heated in here — I couldn't just sit and do nothing. I had to see if there was anything I could help with.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D40E"
        },
        [12020908] = {
          ContentFR = "Service après-vente premium des Chasseurs de Phoxène ! Satisfaction garantie, madame la Patronne !",
          DialogueId = 12020908,
          GUID = "1E17D438",
          NextDialogue = 12020909,
          SpeakNpcId = 200002,
          Subtitle = "Consider it premium after-sales service — Phoxhunter style! And we're good!",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D438"
        },
        [12020909] = {
          ContentFR = "Ne t’inquiète pas, Patronne Zhiliu ! {nickname} est super agile — sa spécialité, c’est tourner, bondir, virevolter ! Aucune hauteur ne lui fait peur !",
          DialogueId = 12020909,
          GUID = "1E17D462",
          NextDialogue = 12020910,
          SpeakNpcId = 200002,
          Subtitle = "You can count on us, Proprietress Zhiliu!  is nimble as can be — spins, flips, leaps — no obstacle too high for my Little Minion!",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D462"
        },
        [12020910] = {
          ContentFR = "... Si vous y tenez.",
          DialogueId = 12020910,
          GUID = "1E17D48C",
          NextDialogue = 12020911,
          SpeakNpcId = 210004,
          Subtitle = "...If you insist.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D48C"
        },
        [12020911] = {
          ContentFR = "{nickname}, prends cette pièce de cuivre. Place-la sur le front de Zhuyin. Je m’occuperai du reste.",
          DialogueId = 12020911,
          GUID = "1E17D4B6",
          NextDialogue = 12020912,
          SpeakNpcId = 210004,
          Subtitle = ", take this copper coin. Place it on Zhuyin's forehead — I'll handle the rest.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D4B6"
        },
        [12020912] = {
          ContentFR = "Fais attention. Ne te blesse pas.",
          DialogueId = 12020912,
          GUID = "1E17D4E0",
          SpeakNpcId = 210004,
          Subtitle = "Be careful. Don't let yourself get hurt.",
          VoiceName = "voice/$Locale$/story/1201/120209/1E17D4E0"
        },
        [12020913] = {
          ContentFR = "Du Li. Emmenez d’abord les blessés à l’abri.",
          DialogueId = 12020913,
          GUID = "1E13468F",
          SpeakNpcId = 210004,
          Subtitle = "Du Li, take the wounded and leave first.",
          VoiceName = "voice/$Locale$/story/1201/120138/1E13468F"
        },
        [12020914] = {
          ContentFR = "À vos ordres, Patronne Zhiliu !",
          DialogueId = 12020914,
          GUID = "1E134691",
          SpeakNpcId = 210004,
          SpeakNpcName = "UI_CMNpc_Name_Duli",
          Subtitle = "Yes, Miss Zhiliu!",
          VoiceName = "voice/$Locale$/story/1201/120138/1E134691"
        },
        [12021001] = {
          ContentFR = "Âme errante... chassée vers le nord, traquant la corruption dans les terres dévastées... Toi et moi, liés par Zhuyin, portons ce malheur pour mille années...",
          DialogueId = 12021001,
          Duration = 2,
          GUID = "1E17E37A",
          NextDialogue = 12021002,
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "O soul adrift, to the north thou stray; to hunt the blight where shadows lay. Bound by Zhuyin, thee and I; bear the doom till time should die...",
          VoiceName = "voice/$Locale$/story/1201/120210/1E17E37A"
        },
        [12021002] = {
          ContentFR = "<I>... ! Encore cette voix. La même que dans la Mer de Poussière.</>",
          DialogueId = 12021002,
          Duration = 2,
          GUID = "1E17E3A4",
          NextDialogue = 12021003,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(...! That voice again. The same one I heard back in the Gritblight Expanse.)",
          VoiceName = "voice/$Locale$/story/1201/120210/1E17E3A4"
        },
        [12021003] = {
          ContentFR = "<I>C’était donc bien le murmure de Zhuyin...</>",
          DialogueId = 12021003,
          Duration = 2,
          GUID = "1E17E3CE",
          NextDialogue = 12021004,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(So it really was the whispers of Zhuyin...)",
          VoiceName = "voice/$Locale$/story/1201/120210/1E17E3CE"
        },
        [12021004] = {
          ContentFR = "Quelque chose ne va pas, {nickname} ?",
          DialogueId = 12021004,
          Duration = 2,
          GUID = "1E17E3F8",
          NextDialogue = 12021005,
          SpeakNpcId = 210004,
          Subtitle = "What is it, ?",
          VoiceName = "voice/$Locale$/story/1201/120210/1E17E3F8"
        },
        [12021005] = {
          ContentFR = "Non... rien du tout.",
          DialogueId = 12021005,
          Duration = 2,
          GUID = "1E17E422",
          SpeakNpcId = 100001,
          Subtitle = "...Nothing.",
          VoiceName = "voice/$Locale$/story/1201/120210/1E17E422"
        },
        [12021201] = {
          ContentFR = "Âmes dispersées... vestiges d’un passé effondré... Quand tout s’éteint, quand l’errance atteint son terme, le temps seul... montre la voie du retour...",
          DialogueId = 12021201,
          Duration = 2,
          GUID = "1E18044A",
          NextDialogue = 12021202,
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "O scattered soul, the past doth wane; foundations crumble, lost in bane. Through realms forlorn, thine end awaits; Yet Time shall guide thee back to Fate.",
          VoiceName = "voice/$Locale$/story/1201/120212/1E18044A"
        },
        [12021202] = {
          ContentFR = "<I>Sa voix... devient de plus en plus claire.</>",
          DialogueId = 12021202,
          Duration = 2,
          GUID = "1E180474",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "(That voice... it's getting clearer.)",
          VoiceName = "voice/$Locale$/story/1201/120212/1E180474"
        },
        [12021301] = {
          ContentFR = "... Qui es-tu ?",
          DialogueId = 12021301,
          Duration = 2,
          GUID = "1E1814B2",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Who art thou?",
          VoiceName = "voice/$Locale$/story/1201/120213/1E1814B2"
        },
        [12021302] = {
          ContentFR = "Es-tu... {性别:venu|venue} toi aussi pour me nuire ?",
          DialogueId = 12021302,
          Duration = 2,
          GUID = "1E1814DC",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Dost thou, too, come to bring me harm...?",
          VoiceName = "voice/$Locale$/story/1201/120213/1E1814DC"
        },
        [12021303] = {
          ContentFR = "Oh non ! Il devient incontrôlable ! Petit larbin !",
          DialogueId = 12021303,
          Duration = 2,
          GUID = "1E181506",
          SpeakNpcId = 200002,
          Subtitle = "It's going berserk! Little Minion, watch out!!",
          VoiceName = "voice/$Locale$/story/1201/120213/1E181506"
        },
        [12021304] = {
          ContentFR = "Tu m’entends ? Tu voulais nous dire quelque chose... n’est-ce pas ?",
          DialogueId = 12021304,
          Duration = 4,
          GUID = "1E181530",
          SpeakNpcId = 100001,
          Subtitle = "Can you hear me? You were trying to say something to us, weren't you?",
          VoiceName = "voice/$Locale$/story/1201/120213/1E181530"
        },
        [12021305] = {
          ContentFR = "Rooooaaar— !",
          DialogueId = 12021305,
          Duration = 2,
          GUID = "1E18155A",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Rrrrroaaaarrrrr—!",
          VoiceName = "voice/$Locale$/story/1201/120213/1E18155A"
        },
        [12021306] = {
          ContentFR = "Zhuyin est à bout de forces.",
          DialogueId = 12021306,
          Duration = 2,
          GUID = "1E181584",
          SpeakNpcId = 210004,
          Subtitle = "Zhuyin is spent — its power's almost gone.",
          VoiceName = "voice/$Locale$/story/1201/120213/1E181584"
        },
        [12021307] = {
          ContentFR = "La dernière frappe... Je compte sur toi, {nickname}.",
          DialogueId = 12021307,
          Duration = 4,
          GUID = "1E1815AE",
          SpeakNpcId = 210004,
          Subtitle = "We will be counting on you to deliver the final strike, .",
          VoiceName = "voice/$Locale$/story/1201/120213/1E1815AE"
        },
        [12022001] = {
          ContentFR = "Ainsi sont achevés les Neuf Chapitres de Dafeng !",
          DialogueId = 12022001,
          GUID = "1E18878A",
          NextDialogue = 12022002,
          RelatedWikiId = {
            [1] = 304003,
            [2] = 303008,
            [3] = 303011
          },
          SnapShot = "MEMORY",
          Subtitle = "Henceforth, the Nine Chapters of Dafeng stand complete!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E18878A"
        },
        [12022002] = {
          ContentFR = "Désormais, le peuple de Huaxu sera à jamais délivré des tourments de la guerre, et préservé des ravages de la discorde !",
          DialogueId = 12022002,
          GUID = "1E1887B4",
          NextDialogue = 12022003,
          SnapShot = "MEMORY",
          Subtitle = "The folk of Huaxu shall dwell in peace — free from war's cruel hand and spared the scourge of strife!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E1887B4"
        },
        [12022003] = {
          ContentFR = "Taihao rendra la Loi. Zhuyin gardera le Cœur.",
          DialogueId = 12022003,
          GUID = "1E1887DE",
          NextDialogue = 12022004,
          SnapShot = "MEMORY",
          Subtitle = "Taihao shall govern the law. Zhuyin shall govern the mind.",
          VoiceName = "voice/$Locale$/story/1201/120220/1E1887DE"
        },
        [12022004] = {
          ContentFR = "Ô vénérables divinités, unies pour gouverner les Neuf Chapitres de Dafeng... protégez les êtres, et garantissez la paix des âges à venir —",
          DialogueId = 12022004,
          GUID = "1E188808",
          NextDialogue = 12022005,
          SnapShot = "MEMORY",
          Subtitle = "Two revered deities, bound by covenant — together, ye shall watch o'er the Nine Chapters of Dafeng, safeguard the myriad beings, and shield the ages to come.",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188808"
        },
        [12022005] = {
          ContentFR = "Le cœur est la source de tout chaos !",
          DialogueId = 12022005,
          GUID = "1E188832",
          NextDialogue = 12022006,
          SnapShot = "MEMORY",
          Subtitle = "The mind is the root of all chaos!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188832"
        },
        [12022006] = {
          ContentFR = "Si notre grand Huaxu s’est enlisé dans le fracas des armes, c’est parce que les hommes ont laissé leurs cœurs sombrer dans la confusion !",
          DialogueId = 12022006,
          GUID = "1E18885C",
          NextDialogue = 12022007,
          SnapShot = "MEMORY",
          Subtitle = "'Tis the turmoil within men's hearts that hath plunged Huaxu into unending war!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E18885C"
        },
        [12022007] = {
          ContentFR = "Aujourd’hui, Zhuyin doit être exilé... et scellé.",
          DialogueId = 12022007,
          GUID = "1E188886",
          NextDialogue = 12022008,
          SnapShot = "MEMORY",
          Subtitle = "Upon this day, shall Zhuyin be sealed.",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188886"
        },
        [12022008] = {
          ContentFR = "Seule une Loi indemne de toute émotion est digne de porter l’ordre du monde !",
          DialogueId = 12022008,
          GUID = "1E1888B0",
          NextDialogue = 12022009,
          SnapShot = "MEMORY",
          Subtitle = "Only a law unswayed by mortal sentiment is fit to hold dominion o'er the world!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E1888B0"
        },
        [12022009] = {
          ContentFR = "Non ! Vous ne devez pas ! Si le Cœur et la Loi se brisent l’un contre l’autre... les conséquences seront sans fin !",
          DialogueId = 12022009,
          GUID = "1E1888DA",
          NextDialogue = 12022010,
          SnapShot = "MEMORY",
          Subtitle = "Nay! Ye must not! When mind and law stand sundered, ruin shall know no end!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E1888DA"
        },
        [12022010] = {
          ContentFR = "Recule ! Ne viens pas gâcher l’essentiel !",
          DialogueId = 12022010,
          GUID = "1E188904",
          NextDialogue = 12022011,
          SnapShot = "MEMORY",
          Subtitle = "Back off! This rite must not be marred!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188904"
        },
        [12022011] = {
          ContentFR = "Pendant des siècles... les Bi’an obscurs sont nés, et le malheur a pris racine dans l’ombre... Le fruit d’aujourd’hui... n’est que la graine d’autrefois !",
          DialogueId = 12022011,
          GUID = "1E18892E",
          NextDialogue = 12022012,
          SnapShot = "MEMORY",
          Subtitle = "For centuries thereafter, the Sable Bi'an arose — calamity blooming in the shadows... The ruin we see today was sown in that distant hour!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E18892E"
        },
        [12022012] = {
          ContentFR = "Car Zhuyin naît du cœur. Tant que le cœur des hommes ne s’éteint pas... comment Zhuyin pourrait-il s’éteindre ?",
          DialogueId = 12022012,
          GUID = "1E188958",
          NextDialogue = 12022013,
          SnapShot = "MEMORY",
          Subtitle = "Zhuyin springs from the depths of the mortal heart. So long as human desire endures, how can Zhuyin be truly undone?",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188958"
        },
        [12022013] = {
          ContentFR = "Le sceller par quelque art secret, c’est comme tenter d’éteindre l’ébullition à coups de louche... Le jour où Zhuyin brisera ses chaînes, ce mal, incrusté jusqu’à l’os, engendrera immanquablement un désastre.",
          DialogueId = 12022013,
          GUID = "1E188982",
          NextDialogue = 12022014,
          SnapShot = "MEMORY",
          Subtitle = "To seal it by secret arts is but to ladle water upon a boiling pot — once spent, it shall rise anew, a hidden canker in the bone, sure to fester into grievous affliction!",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188982"
        },
        [12022014] = {
          ContentFR = "... Qui décide des séparations et des retrouvailles ? Qui demeure en exil, prisonnier d’une autre terre... ?",
          DialogueId = 12022014,
          GUID = "1E1889AC",
          NextDialogue = 12022015,
          SnapShot = "ECHO",
          SpeakNpcName = "UI_CMName_Name_ZhuYing",
          Subtitle = "...Who might decree the weaving of fates, of sunderings and partings? Who roves forlorn, tarrying in lands beyond all chartings?",
          VoiceName = "voice/$Locale$/story/1201/120220/1E1889AC"
        },
        [12022015] = {
          ContentFR = "Zhuyin... c’était tes souvenirs, à l’instant ?! Qu’est-ce que tu essaies de me dire ?!",
          DialogueId = 12022015,
          GUID = "1E1889D6",
          NextDialogue = 12022016,
          SpeakNpcId = 100001,
          Subtitle = "Zhuyin! Were those your memories!? What is it you're trying to tell me!?",
          VoiceName = "voice/$Locale$/story/1201/120220/1E1889D6"
        },
        [12022016] = {
          ContentFR = "Tout est déjà accompli... et nul ne peut le défaire. Le monde marche vers un grand malheur... qu’on ne pourra éviter...",
          DialogueId = 12022016,
          GUID = "1E188A00",
          SnapShot = "ECHO",
          SpeakNpcName = "UI_CMName_Name_ZhuYing",
          Subtitle = "All is done... beyond recall... A doom shall befall the world, inescapable, unbound...",
          VoiceName = "voice/$Locale$/story/1201/120220/1E188A00"
        },
        [12022101] = {
          Camera = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Petit larbin ! Ça va ?!",
          DialogueId = 12022101,
          GUID = "1E1897F2",
          NextDialogue = 12022102,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion! You alright?",
          VoiceName = "voice/$Locale$/story/1201/120221/1E1897F2"
        },
        [12022102] = {
          ContentFR = "Ça va... J’ai juste vu... des images. Comme des fragments de mémoire.",
          DialogueId = 12022102,
          GUID = "1E18981C",
          NextDialogue = 12022103,
          SpeakNpcId = 100001,
          Subtitle = "I'm fine... I think I just saw... something. Like... memory fragments.",
          VoiceName = "voice/$Locale$/story/1201/120221/1E18981C"
        },
        [12022103] = {
          ContentFR = "Tout le monde — frappez, pendant qu’il est encore entravé ! C’est maintenant ou jamais !",
          DialogueId = 12022103,
          GUID = "1E189846",
          SpeakNpcId = 210004,
          Subtitle = "Everyone — strike now, while it's still restrained! This is our only chance to bring it down!",
          VoiceName = "voice/$Locale$/story/1201/120221/1E189846"
        },
        [12022201] = {
          ContentFR = "Attendez !",
          DialogueId = 12022201,
          GUID = "1E18A85A",
          NextDialogue = 12022202,
          SpeakNpcId = 100001,
          Subtitle = "Wait!",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A85A"
        },
        [12022202] = {
          ContentFR = "Je viens de voir quelque chose... dans les souvenirs de Zhuyin. Des fragments de vérité sur les Neuf Chapitres... et peut-être l’origine du Fléau de Zhuyin !",
          DialogueId = 12022202,
          GUID = "1E18A884",
          NextDialogue = 12022203,
          SpeakNpcId = 100001,
          Subtitle = "I saw something just now — in Zhuyin's memories. Fragments of the truth about the Nine Chapters... It might have something to do with the Scourge of Zhuyin!",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A884"
        },
        [12022203] = {
          ContentFR = "On peut peut-être lui parler ! Si on apaise sa colère... on n’est pas obligés d’être ses ennemis !",
          DialogueId = 12022203,
          GUID = "1E18A8AE",
          NextDialogue = 12022204,
          SpeakNpcId = 100001,
          Subtitle = "Maybe we can talk to it! If we can calm its wrath, we might not have to fight!",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A8AE"
        },
        [12022204] = {
          ContentFR = "Inutile.",
          DialogueId = 12022204,
          GUID = "1E18A8D8",
          NextDialogue = 12022205,
          SpeakNpcId = 210004,
          Subtitle = "That won't be necessary.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A8D8"
        },
        [12022205] = {
          ContentFR = "À votre réaction... vous le saviez déjà ?",
          DialogueId = 12022205,
          GUID = "1E18A902",
          NextDialogue = 12022206,
          SpeakNpcId = 100001,
          Subtitle = "Zhiliu... you knew this all along, didn't you?",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A902"
        },
        [12022206] = {
          ContentFR = "Ce que tu as vu est peut-être vrai... et alors ?",
          DialogueId = 12022206,
          GUID = "1E18A92C",
          NextDialogue = 12022207,
          SpeakNpcId = 210004,
          Subtitle = "Perhaps what you saw is true. But what of it?",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A92C"
        },
        [12022207] = {
          ContentFR = "L’ère du <H>Seigneur Dragon d’Argent</> doit prendre fin. Et moi... j’en saisirai l’autorité.",
          DialogueId = 12022207,
          GUID = "1E18A956",
          NextDialogue = 12022208,
          SpeakNpcId = 210004,
          Subtitle = "The age of the Lord Argent Sovereign ends here. And I shall claim Their mantle.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A956"
        },
        [12022208] = {
          ContentFR = "Qu... quoi...?",
          DialogueId = 12022208,
          GUID = "1E18A980",
          SpeakNpcId = 100001,
          Subtitle = "What...?",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A980"
        },
        [12022209] = {
          ContentFR = "Quel regret... Si la situation n’était pas si pressante, je n’aurais pas eu à employer ce genre de moyens.",
          DialogueId = 12022209,
          GUID = "1E18A9AA",
          NextDialogue = 12022210,
          SpeakNpcId = 210004,
          Subtitle = "A pity... Were the hour less dire, I would not resort to such measures.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A9AA"
        },
        [12022210] = {
          ContentFR = "... Zhiliu ! Laissez-moi sortir !",
          DialogueId = 12022210,
          GUID = "1E18A9D4",
          NextDialogue = 12022211,
          SpeakNpcId = 100001,
          Subtitle = "...Zhiliu! Let me out!",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A9D4"
        },
        [12022211] = {
          ContentFR = "Qin Qiu m’a prévenue : ton cœur est trop pur. Il aurait entravé l’exécution du plan.",
          DialogueId = 12022211,
          GUID = "1E18A9FE",
          NextDialogue = 12022212,
          SpeakNpcId = 210004,
          Subtitle = "Qin Qiu once warned me that your heart is too pure. It would have gotten in the way.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18A9FE"
        },
        [12022212] = {
          ContentFR = "Je t’ai délibérément envoyé loin... je ne pensais pas que tu viendrais quand même.",
          DialogueId = 12022212,
          GUID = "1E18AA28",
          NextDialogue = 12022213,
          SpeakNpcId = 210004,
          Subtitle = "So I sent you away... yet still you returned.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AA28"
        },
        [12022213] = {
          ContentFR = "Ces jours à Givrelac, à tes côtés... c’était une rare parenthèse. Un rêve trop bref.",
          DialogueId = 12022213,
          GUID = "1E18AA52",
          NextDialogue = 12022214,
          SpeakNpcId = 210004,
          Subtitle = "Those days in Icelake with you... they were a rare respite, as fleeting as a dream.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AA52"
        },
        [12022214] = {
          ContentFR = "Si seulement tu n’étais pas {性别:apparu|apparue} ici... nous aurions pu continuer à parler et rire comme avant.",
          DialogueId = 12022214,
          GUID = "1E18AA7C",
          NextDialogue = 12022215,
          SpeakNpcId = 210004,
          Subtitle = "If only you had not shown up here — we could have gone on as ever before — sharing idle words and quiet mirth.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AA7C"
        },
        [12022215] = {
          ContentFR = "Mais dans les règles d’un marchand... il n’existe pas de « si ».",
          DialogueId = 12022215,
          GUID = "1E18AAA6",
          NextDialogue = 12022216,
          SpeakNpcId = 210004,
          Subtitle = "But merchants have no \"if only.\"",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AAA6"
        },
        [12022216] = {
          ContentFR = "Qu’est-ce que vous cherchez à faire... ?",
          DialogueId = 12022216,
          GUID = "1E18AAD0",
          NextDialogue = 12022217,
          SpeakNpcId = 100001,
          Subtitle = "What are you trying to do...?",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AAD0"
        },
        [12022217] = {
          ContentFR = "Chut— C’est pour ton bien. Même si... ce n’est pas la manière qui te plairait.",
          DialogueId = 12022217,
          GUID = "1E18AAFA",
          SpeakNpcId = 210004,
          Subtitle = "Ssh... It is for your own good — though perhaps not in the way you would choose.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AAFA"
        },
        [12022219] = {
          ContentFR = "(hurlement qui se déforme)",
          DialogueId = 12022219,
          GUID = "1E18AB4E",
          Subtitle = "(Voice warping into twisted screams)",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AB4E"
        },
        [12022220] = {
          ContentFR = "Hé ! Qu’est-ce qui s’est passé ici ?! Relâchez-{性别:le|la} !",
          DialogueId = 12022220,
          GUID = "1E18AB78",
          SpeakNpcId = 210021,
          Subtitle = "Hey! What the hell happened here!? Let {性别:him|her} go!",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AB78"
        },
        [12022221] = {
          ContentFR = "<I>Tss.</> Repli.",
          DialogueId = 12022221,
          GUID = "1E18AB79",
          Subtitle = "Tsk. Retreat.",
          VoiceName = "voice/$Locale$/story/1201/120222/1E18AB79"
        },
        [12022250] = {
          Content = "一段时间后……",
          DialogueId = 12022250,
          GUID = "1E18AB8A",
          Subtitle = "After a while…"
        },
        [12022301] = {
          Camera = "-78.574219,498.462891,113.020996,0.000014,-0.99994,-74.596542,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{nickname}... tu es {性别:blessé|blessée} ?",
          DialogueId = 12022301,
          GUID = "1E18B8C2",
          NextDialogue = 12022302,
          RelatedWikiId = {
            [1] = 203001,
            [2] = 203006,
            [3] = 203007
          },
          SpeakNpcId = 210013,
          Subtitle = ", are you hurt?",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B8C2"
        },
        [12022302] = {
          ContentFR = "Respire. Vide ton esprit. Je vais t’aider à retrouver tes forces.",
          DialogueId = 12022302,
          GUID = "1E18B8EC",
          NextDialogue = 12022303,
          SpeakNpcId = 210013,
          Subtitle = "Steady now. Take a breath, and let your thoughts settle. I will help restore your energy.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B8EC"
        },
        [12022303] = {
          ContentFR = "Je vais bien... juste un peu la tête qui tourne... Fushu, n’use plus de ta force pour ça. Tu me l’as promis....",
          DialogueId = 12022303,
          GUID = "1E18B916",
          NextDialogue = 12022304,
          SpeakNpcId = 100001,
          Subtitle = "I'm fine... just a little dizzy. Fushu, please — no more straining yourself to heal others. You promised me, remember?",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B916"
        },
        [12022304] = {
          ContentFR = "Rassure-toi. Je connais mes limites. Là, c’est ta sécurité qui compte.",
          DialogueId = 12022304,
          GUID = "1E18B940",
          NextDialogue = 12022305,
          SpeakNpcId = 210013,
          Subtitle = "Worry not — I know my limits. In this moment, your safety is what matters most.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B940"
        }
      }
    end
  },
  {
    MinKey = 12022305,
    MaxKey = 12025407,
    Loader = function()
      return {
        [12022305] = {
          ContentFR = "<I>Rah...</> pourquoi je débarque toujours trop tard, aujourd’hui ?! Si seulement j’avais pas glandé quand j’apprenais la technique de légèreté... Tout ça parce que monsieur se réveillait toujours quand le soleil était déjà haut !",
          DialogueId = 12022305,
          GUID = "1E18B96A",
          NextDialogue = 12022306,
          SpeakNpcId = 210021,
          Subtitle = "Damn it... Why am I always a step too late today!? If only I hadn't slacked off so much during lightfoot training back then... serves me right!",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B96A"
        },
        [12022306] = {
          ContentFR = "Je vais bien... Mais comment ça se fait que vous soyez là, tous les deux ?",
          DialogueId = 12022306,
          GUID = "1E18B994",
          NextDialogue = 12022307,
          SpeakNpcId = 100001,
          Subtitle = "I'm okay, don't worry... But how come you two came together?",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B994"
        },
        [12022307] = {
          ContentFR = "J’ai compris certaines choses... et je voulais t’en parler.",
          DialogueId = 12022307,
          GUID = "1E18B9BE",
          NextDialogue = 12022308,
          SpeakNpcId = 210013,
          Subtitle = "I came to a realisation... and I wished to share it with you.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B9BE"
        },
        [12022308] = {
          ContentFR = "Je t’ai cherché à Éternel Printemps, sans te trouver. On m’a dit que tu étais {性别:venu|venue} ici... alors j’ai tenté ma chance. Et sur la route, j’ai croisé cet homme.",
          DialogueId = 12022308,
          GUID = "1E18B9E8",
          NextDialogue = 12022309,
          SpeakNpcId = 210013,
          Subtitle = "I looked for you at EverSpring, but you were not there. Someone mentioned you had come this way — so I followed, hoping to catch up. Along the road, I happened upon this swordsman.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18B9E8"
        },
        [12022309] = {
          ContentFR = "Après la Plaine des Corbeaux, je me suis dit que mon frère d’armes filerait vers la Mer de Poussière... Alors j’ai traîné dans le coin, à l’affût.",
          DialogueId = 12022309,
          GUID = "1E18BA12",
          NextDialogue = 12022310,
          SpeakNpcId = 210021,
          Subtitle = "After we parted ways at Crowsong Hollow, I figured my shixiong might have headed towards the Gritblight Expanse, so I hung around the area, wandering and keeping watch.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BA12"
        },
        [12022310] = {
          ContentFR = "Puis l’autel s’est mis à souffler comme une tempête, et la terre a tremblé... Je suis venu voir, et je t’ai trouvé. Si seulement j’étais arrivé plus tôt !",
          DialogueId = 12022310,
          GUID = "1E18BA3C",
          NextDialogue = 12022311,
          SpeakNpcId = 210021,
          Subtitle = "Then all of a sudden, the winds rose up and the ground itself began to quake near the altar. I came running to see what was going on... and there you were. If only I'd gotten here sooner!",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BA3C"
        },
        [12022311] = {
          ContentFR = "Je te jure, ce qui vient d’arriver était trop flippant ! Même si vous aviez été dix comme toi, ça n’aurait servi à rien !",
          DialogueId = 12022311,
          GUID = "1E18BA66",
          NextDialogue = 12022312,
          SpeakNpcId = 200002,
          Subtitle = "Nah — what just happened was way too scary! Even if there'd been ten of you, it wouldn't have made a difference!",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BA66"
        },
        [12022312] = {
          ContentFR = "Cette femme... elle a enfermé le Roi Démon et son petit larbin... et en plus, elle a avalé un dragon ! Un vrai !",
          DialogueId = 12022312,
          GUID = "1E18BA90",
          NextDialogue = 12022313,
          SpeakNpcId = 200002,
          Subtitle = "That woman — she trapped me and my Little Minion in some magic cage... and she ate a whole loong! A real one!",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BA90"
        },
        [12022313] = {
          ContentFR = "Rien que d’y penser, j’ai encore des frissons... Dire qu’on a traîné avec quelqu’un comme ça si longtemps !",
          DialogueId = 12022313,
          GUID = "1E18BABA",
          NextDialogue = 12022314,
          SpeakNpcId = 200002,
          Subtitle = "I'm still getting chills just thinking about it... I can't believe we spent so long hanging around a creepy character like her!",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BABA"
        },
        [12022314] = {
          ContentFR = "{nickname}... c’est vrai ?",
          DialogueId = 12022314,
          GUID = "1E18BAE4",
          NextOptions = {
            [1] = 12022315
          },
          SpeakNpcId = 210013,
          Subtitle = ", is that true?",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BAE4"
        },
        [12022315] = {
          ContentFR = "<I>Raconter ce qui s’est passé</>",
          DialogueId = 12022315,
          GUID = "1E18BB0E",
          NextDialogue = 12022327,
          Subtitle = "(Tell them what happened)"
        },
        [12022316] = {
          ContentFR = "Mais elle fait tout ça... dans quel but ?",
          DialogueId = 12022316,
          GUID = "1E18BB38",
          NextDialogue = 12022317,
          SpeakNpcId = 210021,
          Subtitle = "But why go so far — what's she really after?",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BB38"
        },
        [12022317] = {
          ContentFR = "Je... je ne sais pas...",
          DialogueId = 12022317,
          GUID = "1E18BB62",
          NextDialogue = 12022318,
          SpeakNpcId = 100001,
          Subtitle = "I don't know...",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BB62"
        },
        [12022318] = {
          ContentFR = "Moi, je vois très bien : elle veut voler la puissance de Zhuyin, conquérir le monde, et devenir le Super Méga Roi Démon !",
          DialogueId = 12022318,
          GUID = "1E18BB8C",
          NextDialogue = 12022319,
          SpeakNpcId = 200002,
          Subtitle = "If you ask me, she's out to grab that loong's power, take over the world, and crown herself as the ultimate Demon Lord!",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BB8C"
        },
        [12022319] = {
          ContentFR = "Conquérir le monde... ?",
          DialogueId = 12022319,
          GUID = "1E18BBB6",
          NextDialogue = 12022320,
          SpeakNpcId = 100001,
          Subtitle = "Take over the world... huh.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BBB6"
        },
        [12022320] = {
          ContentFR = "C’est vrai... elle a dit quelque chose comme ça...",
          DialogueId = 12022320,
          GUID = "1E18BBE0",
          NextDialogue = 12022321,
          SpeakNpcId = 100001,
          Subtitle = "She did say something like that...",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BBE0"
        },
        [12022321] = {
          ContentFR = "L’ère du <H>Seigneur Dragon d’Argent</> doit prendre fin. Et moi... j’en saisirai l’autorité.",
          DialogueId = 12022321,
          GUID = "1E18BC0A",
          NextDialogue = 12022322,
          SpeakNpcId = 210004,
          Subtitle = "The age of the Lord Argent Sovereign ends here. And I shall claim Their mantle.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BC0A"
        },
        [12022322] = {
          ContentFR = "Elle... elle veut <H>devenir une divinité</> ?",
          DialogueId = 12022322,
          GUID = "1E18BC34",
          NextDialogue = 12022323,
          SpeakNpcId = 100001,
          Subtitle = "She... she's trying to become a god?",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BC34"
        },
        [12022323] = {
          ContentFR = "Si Zhiliu a commencé à tisser sa toile dès Givrelac... alors son plan est sans doute bien plus rigoureux que tout ce que nous pouvons imaginer.",
          DialogueId = 12022323,
          GUID = "1E18BC5E",
          NextDialogue = 12022324,
          SpeakNpcId = 210013,
          Subtitle = "Given what you have shared... if she has indeed been weaving these designs since Icelake, then her machinations likely run deeper than any of us might fathom.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BC5E"
        },
        [12022324] = {
          ContentFR = "Bon, on va pas refaire le monde ici. Le mieux, c’est de rentrer et de rassembler des infos. <I>Soupir...</> Je voulais juste retrouver mon frère d’armes... et me voilà embarqué dans une affaire monstrueuse.",
          DialogueId = 12022324,
          GUID = "1E18BC88",
          NextDialogue = 12022325,
          SpeakNpcId = 210021,
          Subtitle = "Bah — no point racking our brains over this now. Let's head back and dig up what we can. Oof... I only meant to track down my shixiong — never thought I'd stumble into a mess like this!",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BC88"
        },
        [12022325] = {
          ContentFR = "Je dois retourner aux Pics Extérieurs et les prévenir. Comme ça, si la situation empire... ils auront de quoi réagir.",
          DialogueId = 12022325,
          GUID = "1E18BCB2",
          NextDialogue = 12022326,
          SpeakNpcId = 210021,
          Subtitle = "I'm going back to the Outer Peaks to warn them. If worse comes to worst, they'll need to be ready.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BCB2"
        },
        [12022326] = {
          ContentFR = "Je vais aussi interroger les Wishen. Certains sont nés dans des temps immémoriaux... ils connaissent peut-être des vérités perdues.",
          DialogueId = 12022326,
          GUID = "1E18BCDC",
          NextDialogue = 12022328,
          SpeakNpcId = 210013,
          Subtitle = "I shall seek out the Wishen. Some among them have witnessed the turnings of many ages... they may hold truths long since lost to memory.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BCDC"
        },
        [12022327] = {
          ContentFR = "... Je le savais. Tous ceux qui traînent avec ce vieux renard ne valent pas mieux !",
          DialogueId = 12022327,
          GUID = "120223151.0",
          NextDialogue = 12022316,
          SpeakNpcId = 210021,
          Subtitle = "...I knew it. Anyone who throws in with that Old Fox is bound to be trouble.",
          VoiceName = "voice/$Locale$/story/1201/120223/120223151"
        },
        [12022328] = {
          ContentFR = "Et toi, {nickname}... tu comptes faire quoi ?",
          DialogueId = 12022328,
          GUID = "1E18BD30",
          NextOptions = {
            [1] = 120223281,
            [2] = 120223282
          },
          SpeakNpcId = 210021,
          Subtitle = "And what about you, ?",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BD30"
        },
        [12022329] = {
          ContentFR = "Eh ben... {性别:mon ami|mon amie}... T’as du cœur... J’ai bien fait de te prendre en estime !",
          DialogueId = 12022329,
          GUID = "1E18BD5A",
          NextDialogue = 12022331,
          SpeakNpcId = 210021,
          Subtitle = "So you've got a heart for the world, too — I've got to say, I really admire that, my friend!",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BD5A"
        },
        [12022330] = {
          ContentFR = "Tu as déjà porté bien trop de choses sur tes épaules. Repose-toi un peu.",
          DialogueId = 12022330,
          GUID = "1E18BD84",
          NextDialogue = 12022331,
          SpeakNpcId = 210013,
          Subtitle = "You have already borne so much. You deserve a moment's respite.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BD84"
        },
        [12022331] = {
          ContentFR = "Le soleil va disparaître. On descend. La nuit, ici, ça mord jusqu’aux os — et rester ne servira à rien.",
          DialogueId = 12022331,
          GUID = "1E18BDAE",
          NextDialogue = 12022332,
          SpeakNpcId = 210021,
          Subtitle = "Heh, sun's nearly gone. Let's get off this mountain before it gets cold enough to bite. No sense in hanging around here any longer.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BDAE"
        },
        [12022332] = {
          ContentFR = "Partons.",
          DialogueId = 12022332,
          GUID = "1E18BDD8",
          SpeakNpcId = 210013,
          Subtitle = "Let us leave this place.",
          VoiceName = "voice/$Locale$/story/1201/120223/1E18BDD8"
        },
        [12022401] = {
          ContentFR = "Attends ! Et notre récompense, alors ?! Elle va pas oser nous la voler aussi, si ?!",
          DialogueId = 12022401,
          Duration = 3,
          GUID = "1E18C92A",
          NextDialogue = 12022402,
          SpeakNpcId = 200002,
          Subtitle = "Wait a second... What about the pay we were promised? Do you think she's planning to stiff us?",
          VoiceName = "voice/$Locale$/story/1201/120224/1E18C92A"
        },
        [12022402] = {
          ContentFR = "La mission a capoté... Petit larbin, on a fait tout ce chemin jusqu’à Huaxu pour rien ou quoi ?!",
          DialogueId = 12022402,
          Duration = 4,
          GUID = "1E18C954",
          NextDialogue = 12022403,
          SpeakNpcId = 200002,
          Subtitle = "So much for the commission, I guess... Little Minion, looks like our grand journey to Huaxu was all for nothing!",
          VoiceName = "voice/$Locale$/story/1201/120224/1E18C954"
        },
        [12022403] = {
          ContentFR = "Bon... elle nous a quand même filé une somme monstrueuse. On n’est pas perdus... Mais si j’avais su, j’en aurais demandé encore plus !",
          DialogueId = 12022403,
          Duration = 4,
          GUID = "1E18C97E",
          SpeakNpcId = 200002,
          Subtitle = "Well... at least we got that giant pocket money from her. Hmph... if I'd known it'd end like this, I'd have asked for even more!",
          VoiceName = "voice/$Locale$/story/1201/120224/1E18C97E"
        },
        [12022501] = {
          ContentFR = "La grande vertu du Ciel porte le nom de Vie ;\nAttenter au corps ou ôter la vie — cela est proscrit.",
          DialogueId = 12022501,
          GUID = "1E18D992",
          NextDialogue = 12022502,
          SnapShot = "ECHO",
          Subtitle = "Heaven's great virtue bears the name of Life;\nTo wound or kill — this must not be done.",
          VoiceName = "voice/$Locale$/story/1201/120225/1E18D992"
        },
        [12022502] = {
          ContentFR = "La parole fonde l’homme et établit la confiance ;\nRompre un serment ou trahir une alliance — cela est proscrit.",
          DialogueId = 12022502,
          GUID = "1E18D9BC",
          NextDialogue = 12022503,
          SnapShot = "ECHO",
          Subtitle = "A man is measured by the strength of his word;\nTo break faith or betray a vow — this must not be done.",
          VoiceName = "voice/$Locale$/story/1201/120225/1E18D9BC"
        },
        [12022503] = {
          ContentFR = "Faire triompher le vrai et écarter le faux, agir avec un cœur sincère ;\nTromper les foules par des paroles mensongères — cela est proscrit.",
          DialogueId = 12022503,
          GUID = "1E18D9E6",
          SnapShot = "ECHO",
          Subtitle = "Let truth be manifest and falsehood driven out;\nTo deceive and mislead the many — this must not be done.",
          VoiceName = "voice/$Locale$/story/1201/120225/1E18D9E6"
        },
        [12022504] = {
          ContentFR = "Se gouverner avec humilité, se contenir par la modestie ;\nSe livrer à l’arrogance et à la brutalité — cela est proscrit.",
          DialogueId = 12022504,
          GUID = "1E18DA10",
          NextDialogue = 12022505,
          SnapShot = "ECHO",
          Subtitle = "Govern the self with humility, bind conduct to modesty;\nTo indulge in arrogance and tyranny — this must not be done.",
          VoiceName = "voice/$Locale$/story/1201/120225/1E18DA10"
        },
        [12022505] = {
          ContentFR = "Honorer les sages, traiter autrui avec respect, préserver l’ordre et la bienséance ;\nAgir sans retenue ni mesure — cela est proscrit.",
          DialogueId = 12022505,
          GUID = "1E18DA3A",
          NextDialogue = 12022506,
          SnapShot = "ECHO",
          Subtitle = "Honour the worthy, extend courtesy, and let order be the measure of propriety;\nTo act with wanton excess and unbridled abandon — this must not be done.",
          VoiceName = "voice/$Locale$/story/1201/120225/1E18DA3A"
        },
        [12022506] = {
          ContentFR = "Étendre à autrui ce que l’on exige de soi, agir selon la juste mesure ;\nAbuser de sa force pour opprimer les faibles — cela est proscrit.",
          DialogueId = 12022506,
          GUID = "1E18DA64",
          SnapShot = "ECHO",
          Subtitle = "Let compassion and righteousness guide your mind and every deed;\nTo oppress the weak by force — this must not be done.",
          VoiceName = "voice/$Locale$/story/1201/120225/1E18DA64"
        },
        [12022507] = {
          ContentFR = "Purifier son cœur, discipliner sa conduite, rester droit pour être intègre ;\nCourber la loi par avidité ou cruauté — cela est proscrit.",
          DialogueId = 12022507,
          GUID = "1E18DA8E",
          NextDialogue = 12022508,
          SnapShot = "ECHO",
          Subtitle = "Let your heart be pure, your conduct restrained, and uprightness be the mark of integrity;\nTo bend the law for greed or cruelty — this must not be done.",
          VoiceName = "voice/$Locale$/story/1201/120225/1E18DA8E"
        },
        [12022508] = {
          ContentFR = "Distinguer clairement le juste de l’injuste, savoir discerner avec lucidité ;\nConfondre le vrai et le faux — cela est proscrit.",
          DialogueId = 12022508,
          GUID = "1E18DAB8",
          NextDialogue = 12022509,
          SnapShot = "ECHO",
          Subtitle = "Let clarity be your unwavering guide in discerning right from wrong;\nTo confuse truth and falsehood — this must not be done.",
          VoiceName = "voice/$Locale$/story/1201/120225/1E18DAB8"
        },
        [12022509] = {
          ContentFR = "Écouter les décrets du Ciel avec respect et solennité ;\nS’écarter de la voie et renier l’ordre sacré — cela est proscrit.",
          DialogueId = 12022509,
          GUID = "1E18DAE2",
          SnapShot = "ECHO",
          Subtitle = "Attend to Heaven's edict with a reverent mind and a solemn heart;\nTo rebel against the sacred order — this must not be done.",
          VoiceName = "voice/$Locale$/story/1201/120225/1E18DAE2"
        },
        [12022510] = {
          ContentFR = "Continuons d’avancer.",
          DialogueId = 12022510,
          GUID = "1E18DAE3",
          SpeakNpcId = 210013,
          Subtitle = "We may continue.",
          VoiceName = "voice/$Locale$/story/1201/120225/1E18DAE3"
        },
        [12022511] = {
          Content = "让开，让我来解决祂。",
          DialogueId = 12022511,
          Duration = 4,
          GUID = "1E18DB36",
          Subtitle = "Step aside. I will end this."
        },
        [12022512] = {
          Content = "等等！",
          DialogueId = 12022512,
          Duration = 4,
          GUID = "1E18DB60",
          Subtitle = "Wait!"
        },
        [12022513] = {
          Content = "喂，这里发生什么了？——放开{性别：他|她}！",
          DialogueId = 12022513,
          Duration = 4,
          GUID = "1E18DB8A",
          Subtitle = "Hey! What the hell happened here!? Let {性别:him|her} go!"
        },
        [12022514] = {
          ContentFR = "On est arrivés !",
          DialogueId = 12022514,
          Duration = 4,
          GUID = "1E18DBB4",
          Subtitle = "Here we are!"
        },
        [12022515] = {
          Content = "啧，撤。",
          DialogueId = 12022515,
          Duration = 4,
          GUID = "1E18DBDE",
          Subtitle = "Tsk. Retreat."
        },
        [12022516] = {
          Content = "SC006】扶疏咳血",
          DialogueId = 12022516,
          Duration = 4,
          GUID = "1E18DC08"
        },
        [12022517] = {
          Content = "SC007】白龙横扫黑狼灵",
          DialogueId = 12022517,
          Duration = 4,
          GUID = "1E18DC32"
        },
        [12022518] = {
          Content = "SC008】无由生营地开启",
          DialogueId = 12022518,
          Duration = 4,
          GUID = "1E18DC5C"
        },
        [12022519] = {
          Content = "SC009】黑市小弟触发机关",
          DialogueId = 12022519,
          Duration = 4,
          GUID = "1E18DC86"
        },
        [12022520] = {
          Content = "SC010】虬先生袭击玩家",
          DialogueId = 12022520,
          Duration = 4,
          GUID = "1E18DCB0"
        },
        [12022521] = {
          Content = "sc011】刻舟登场",
          DialogueId = 12022521,
          Duration = 4,
          GUID = "1E18DCDA"
        },
        [12022522] = {
          Content = "SC012】抵达黑龙祭坛",
          DialogueId = 12022522,
          Duration = 4,
          GUID = "1E18DD04"
        },
        [12022523] = {
          Content = "SC013】黑龙祭坛跑酷QTE+处决黑龙",
          DialogueId = 12022523,
          Duration = 4,
          GUID = "1E18DD2E"
        },
        [12022524] = {
          Content = "SC014】黑龙祭坛跑酷QTE+处决黑龙",
          DialogueId = 12022524,
          Duration = 4,
          GUID = "1E18DD58"
        },
        [12022525] = {
          Content = "SC015】黑龙祭坛跑酷QTE+处决黑龙",
          DialogueId = 12022525,
          Duration = 4,
          GUID = "1E18DD82"
        },
        [12022526] = {
          Content = "SC016】黑龙BOSS战后",
          DialogueId = 12022526,
          Duration = 4,
          GUID = "1E18DDAC"
        },
        [12022527] = {
          Content = "SC017】止流囚禁玩家",
          DialogueId = 12022527,
          Duration = 4,
          GUID = "1E18DDD6"
        },
        [12022528] = {
          Content = "SC018】止流吸取黑龙力量",
          DialogueId = 12022528,
          Duration = 4,
          GUID = "1E18DE00"
        },
        [12022529] = {
          Content = "SC019】主角被止流催眠",
          DialogueId = 12022529,
          Duration = 4,
          GUID = "1E18DE2A"
        },
        [12022530] = {
          Content = "SC020】扶疏幻境过场",
          DialogueId = 12022530,
          Duration = 4,
          GUID = "1E18DE54"
        },
        [12022601] = {
          ContentFR = "Il y a des traces de combat... et des cadavres de Bi’an obscurs...",
          DialogueId = 12022601,
          GUID = "1E18E9FA",
          NextDialogue = 12022602,
          SpeakNpcId = 100001,
          Subtitle = "There are signs of battle here — scorched earth, and the bodies of Sable Bi'an...",
          VoiceName = "voice/$Locale$/story/1201/120226/1E18E9FA"
        },
        [12022602] = {
          ContentFR = "Petit larbin, la prophétie que tu as entendue, elle s’est réalisée. Mais alors… qu’essayait-elle vraiment de nous dire ?",
          DialogueId = 12022602,
          GUID = "1E18EA24",
          NextDialogue = 12022603,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, that prophecy you heard — it's come true! But what do you think it was really trying to tell us?",
          VoiceName = "voice/$Locale$/story/1201/120226/1E18EA24"
        },
        [12022603] = {
          ContentFR = "Écoute ! Il y a encore des combats devant. Allons voir !",
          DialogueId = 12022603,
          GUID = "1E18EA4E",
          SpeakNpcId = 200002,
          Subtitle = "Do you hear that? There's fighting up ahead — let's go!",
          VoiceName = "voice/$Locale$/story/1201/120226/1E18EA4E"
        },
        [12022701] = {
          ContentFR = "{nickname} ! C’est toi !",
          DialogueId = 12022701,
          GUID = "1E18FA62",
          NextDialogue = 12022702,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "! You're here!",
          VoiceName = "voice/$Locale$/story/1201/120227/1E18FA62"
        },
        [12022702] = {
          ContentFR = "Mademoiselle Yusheng ! Tout le monde va bien ?",
          DialogueId = 12022702,
          GUID = "1E18FA8C",
          NextDialogue = 12022703,
          SpeakNpcId = 200002,
          Subtitle = "Miss Yusheng! Is everyone all right?",
          VoiceName = "voice/$Locale$/story/1201/120227/1E18FA8C"
        },
        [12022703] = {
          ContentFR = "Ne t’inquiète pas. Nous tenons bon pour l’instant. Avec ton aide, je me sens d’autant plus rassurée.",
          DialogueId = 12022703,
          GUID = "1E18FAB6",
          NextDialogue = 12022704,
          SpeakNpcId = 210033,
          Subtitle = "We're holding our ground for now. With you here, I trust we have nothing to fear.",
          VoiceName = "voice/$Locale$/story/1201/120227/1E18FAB6"
        },
        [12022704] = {
          ContentFR = "Mais sois prudent. Même toi, tu ne dois pas baisser ta garde.",
          DialogueId = 12022704,
          GUID = "1E18FAE0",
          SpeakNpcId = 210033,
          Subtitle = "But stay sharp — even you can't afford to be careless.",
          VoiceName = "voice/$Locale$/story/1201/120227/1E18FAE0"
        },
        [12022801] = {
          Camera = "-320.599609,416.605225,161.329102,0.000033,-0.027915,-41.556793,11.88,100000.0,false,Manual,2.8",
          ContentFR = "J’ai entendu dire que les Bi’an obscurs attaqueraient Éternel Printemps, alors nous sommes revenus en toute hâte. Quelle est la situation maintenant ?",
          DialogueId = 12022801,
          GUID = "1E190ACA",
          NextDialogue = 12022802,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003,
            [3] = 304004,
            [4] = 303010,
            [5] = 406004
          },
          SpeakNpcId = 100001,
          Subtitle = "I heard the Sable Bi'an were heading for EverSpring, so we came as quickly as we could. What's the situation now?",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190ACA"
        },
        [12022802] = {
          ContentFR = "Comme toujours, la maîtrise de {nickname} est d’une efficacité remarquable. C’est digne d’admiration.",
          DialogueId = 12022802,
          GUID = "1E190AF4",
          NextDialogue = 12022803,
          SpeakNpcId = 210033,
          Subtitle = "I've seen your skill before, , but it never ceases to amaze me. Truly remarkable.",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190AF4"
        },
        [12022803] = {
          ContentFR = "Hé hé ! Pour mon petit larbin, ce n’était qu’une formalité !",
          DialogueId = 12022803,
          GUID = "1E190B1E",
          NextDialogue = 12022804,
          SpeakNpcId = 200002,
          Subtitle = "Hah! For my Little Minion, this was child's play!",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190B1E"
        },
        [12022804] = {
          ContentFR = "Mais vous... depuis quand vous battez-vous, vous aussi ?",
          DialogueId = 12022804,
          GUID = "1E190B48",
          NextDialogue = 12022805,
          SpeakNpcId = 200002,
          Subtitle = "But what about you? Since when did you guys start picking up weapons?",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190B48"
        },
        [12022805] = {
          ContentFR = "Dès que la Patronne Zhiliu a anticipé l’offensive des Bi’an obscurs, elle a organisé la défense. Les plus robustes ont été envoyés en première ligne. Je me suis portée volontaire.",
          DialogueId = 12022805,
          GUID = "1E190B72",
          NextDialogue = 12022806,
          SpeakNpcId = 210033,
          Subtitle = "Once Miss Zhiliu caught wind of the Sable Bi'an's approach, she wasted no time rallying everyone strong enough to stand guard. I volunteered, too.",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190B72"
        },
        [12022806] = {
          ContentFR = "Je n’avais jamais manié d’armes auparavant... Mais en gardant l’esprit calme et en repoussant la peur, ce n’est finalement pas si terrible.",
          DialogueId = 12022806,
          GUID = "1E190B9C",
          NextDialogue = 12022807,
          SpeakNpcId = 210033,
          Subtitle = "I'd never held a weapon before, but as long as you keep your mind calm and your fear in check... it's really not as frightening as it seems.",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190B9C"
        },
        [12022807] = {
          ContentFR = "Et grâce aux bénédictions des encens, nous n’avons pour l’instant subi aucune perte.",
          DialogueId = 12022807,
          GUID = "1E190BC6",
          NextDialogue = 12022808,
          SpeakNpcId = 210033,
          Subtitle = "And thanks to the blessings of the incense, we haven't suffered any casualties so far.",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190BC6"
        },
        [12022808] = {
          ContentFR = "C’est rassurant... Le pire que je redoutais ne s’est pas produit. Tant mieux.",
          DialogueId = 12022808,
          GUID = "1E190BF0",
          NextDialogue = 12022809,
          SpeakNpcId = 100001,
          Subtitle = "That's a relief... I was worried we'd be too late, but it looks like you're all holding up well.",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190BF0"
        },
        [12022809] = {
          ContentFR = "Merci de ta sollicitude.",
          DialogueId = 12022809,
          GUID = "1E190C1A",
          NextDialogue = 12022810,
          SpeakNpcId = 210033,
          Subtitle = "Thank you — truly.",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190C1A"
        },
        [12022810] = {
          ContentFR = "La Patronne Zhiliu mobilise encore davantage de monde pour mettre fin à cette crise. Si vous en avez la capacité, allez la voir — toute aide sera précieuse.",
          DialogueId = 12022810,
          GUID = "1E190C44",
          NextDialogue = 12022811,
          SpeakNpcId = 210033,
          Subtitle = "Miss Zhiliu is gathering more allies to deal with this crisis. If you still have the strength, seek her out — she would welcome your aid.",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190C44"
        },
        [12022811] = {
          ContentFR = "Petit larbin, allons retrouver Zhiliu !",
          DialogueId = 12022811,
          GUID = "1E190C6E",
          NextDialogue = 12022812,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, let's go find Zhiliu!",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190C6E"
        },
        [12022812] = {
          ContentFR = "D’accord. Prenez soin de vous.",
          DialogueId = 12022812,
          GUID = "1E190C98",
          SpeakNpcId = 100001,
          Subtitle = "Right. We're off. Stay safe, everyone.",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190C98"
        },
        [12022813] = {
          ContentFR = "Les barricades au centre de la route sont-elles en place ?",
          DialogueId = 12022813,
          GUID = "1E190C99",
          NextDialogue = 12022814,
          Subtitle = "Are the barricades set in the road?",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190C99"
        },
        [12022814] = {
          ContentFR = "Une nouvelle vague de Bi’an obscurs arrive ! Tout le monde, restez sur vos gardes !",
          DialogueId = 12022814,
          GUID = "1E190CA1",
          NextDialogue = 12022815,
          Subtitle = "Here comes another wave! Stay alert, everyone!",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190CA1"
        },
        [12022815] = {
          ContentFR = "Surveillez vos alentours ! Cette fois, personne ne doit être blessé !",
          DialogueId = 12022815,
          GUID = "1E190CA2",
          Subtitle = "Watch each other's backs! No one gets hurt this time!",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190CA2"
        },
        [12022816] = {
          ContentFR = "Petit larbin... même si ta prophétie s’est réalisée, la situation n’a pas l’air désespérée, non ?",
          DialogueId = 12022816,
          GUID = "1E190CA3",
          NextDialogue = 12022817,
          SpeakNpcId = 200002,
          Subtitle = "Little Minion, even though the vision you saw came true, things don't seem too bad, right?",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190CA3"
        },
        [12022817] = {
          ContentFR = "Oui. On peut dire que c’est un moindre mal. Allons voir où nous pouvons encore être utiles.",
          DialogueId = 12022817,
          GUID = "1E190CA4",
          SpeakNpcId = 100001,
          Subtitle = "Yes. It could've been much worse. Let's see what we can do to help.",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190CA4"
        },
        [12022818] = {
          ContentFR = "Étranger, es-tu blessé ? Dépêche-toi d’entrer à Éternel Printemps !",
          DialogueId = 12022818,
          GUID = "1E190CA5",
          Subtitle = "Are you injured, outsider? Get inside EverSpring, quickly!",
          VoiceName = "voice/$Locale$/story/1201/120228/1E190CA5"
        },
        [12022901] = {
          Camera = "445.980469,604.601562,199.662109,0.000176,-24.689903,-3.124238,11.88,100000.0,false,Manual,2.8",
          ContentFR = "Patronne Zhiliu. Plusieurs fortifications temporaires ont déjà été mises en place. Les Bi’an obscurs ont lancé plusieurs assauts, mais tous ont été repoussés.",
          DialogueId = 12022901,
          GUID = "1E191B32",
          NextDialogue = 12022902,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003,
            [3] = 304004,
            [4] = 303010,
            [5] = 406004
          },
          SpeakNpcId = 210022,
          Subtitle = "Miss Zhiliu, the temporary fortifications are complete. The Sable Bi'an have attacked in several waves, but we have held them off.",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191B32"
        },
        [12022902] = {
          ContentFR = "Grâce à votre commandement, la situation est désormais stable. Le moral de tout le monde est au beau fixe !",
          DialogueId = 12022902,
          GUID = "1E191B5C",
          NextDialogue = 12022903,
          SpeakNpcId = 210022,
          Subtitle = "Thanks to your leadership, the situation is under control, and everyone's spirits are high.",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191B5C"
        },
        [12022903] = {
          ContentFR = "Les bêtes ont goûté à la résistance et ont cessé leur offensive. Elles rôdent maintenant à la périphérie, comme si elles attendaient une opportunité... Quelle est la prochaine étape selon vous ?",
          DialogueId = 12022903,
          GUID = "1E191B86",
          NextDialogue = 12022904,
          SpeakNpcId = 210022,
          Subtitle = "Those beasts seem to have sensed our strength and are now loitering at the perimeter, biding their time. What would you have us do next?",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191B86"
        },
        [12022904] = {
          ContentFR = "Très bien. Vous avez agi avec efficacité.",
          DialogueId = 12022904,
          GUID = "1E191BB0",
          NextDialogue = 12022905,
          SpeakNpcId = 210004,
          Subtitle = "Well done. It's your swift and steady efforts that made this possible.",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191BB0"
        },
        [12022905] = {
          ContentFR = "Renforcez les patrouilles. Surveillez attentivement les angles morts dans les collines. Ne leur laissez aucune ouverture.",
          DialogueId = 12022905,
          GUID = "1E191BDA",
          NextDialogue = 12022906,
          SpeakNpcId = 210004,
          Subtitle = "Next, assign extra patrols. Keep a close watch on the blind spots in the hills — do not let the beasts find any opening.",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191BDA"
        },
        [12022906] = {
          ContentFR = "En ces temps troublés, l’installation des vieillards, des femmes et des enfants ne doit pas être négligée. Vérifiez les registres un par un. Faites-leur porter du thé au gingembre bien chaud — cela réchauffera les corps autant que les cœurs.",
          DialogueId = 12022906,
          GUID = "1E191C04",
          NextDialogue = 12022907,
          SpeakNpcId = 210004,
          Subtitle = "We must not neglect the elderly and the vulnerable, especially now. Go through the registry name by name, ensure everyone is safe. And bring them hot ginger tea — it will warm them inside and out.",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191C04"
        },
        [12022907] = {
          ContentFR = "Les munitions louées au marché noir sont en place. Distribuez-les au front. Qu’ils opèrent par binômes et se couvrent mutuellement.",
          DialogueId = 12022907,
          GUID = "1E191C2E",
          NextDialogue = 12022908,
          SpeakNpcId = 210004,
          Subtitle = "The ammunition we secured from the black market is ready. Distribute it to the front lines — pair them off, each watching the other's back.",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191C2E"
        },
        [12022908] = {
          ContentFR = "À vos ordres, Patronne Zhiliu !",
          DialogueId = 12022908,
          GUID = "1E191C58",
          NextDialogue = 12022909,
          Subtitle = "Yes, Miss Zhiliu!",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191C58"
        },
        [12022909] = {
          ContentFR = "Les officiants d’encens de la Secte Xuanheng achèvent leurs préparatifs. Tenez encore un peu — cette crise sera bientôt résolue.",
          DialogueId = 12022909,
          GUID = "1E191C82",
          NextDialogue = 12022910,
          SpeakNpcId = 210004,
          Subtitle = "The incense wardens of the Xuanheng Sect are making their final preparations. Hold fast a little longer — this crisis will soon pass.",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191C82"
        },
        [12022910] = {
          ContentFR = "Qu’aucune vie ne soit perdue. Éternel Printemps peut être reconquis... mais une vie fauchée ne revient jamais.",
          DialogueId = 12022910,
          GUID = "1E191CAC",
          NextDialogue = 12022911,
          SpeakNpcId = 210004,
          Subtitle = "Let no one come to harm. EverSpring can be rebuilt if need be, but a lost life... cannot be reclaimed.",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191CAC"
        },
        [12022911] = {
          ContentFR = "Ce n’est pas possible, Patronne Zhiliu — !",
          DialogueId = 12022911,
          GUID = "1E191CD6",
          NextDialogue = 12022912,
          SpeakNpcId = 210031,
          SpeakNpcName = "UI_CMName_Name_ZhongNianNan",
          Subtitle = "Please, Miss Zhiliu — this is wrong!",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191CD6"
        },
        [12022912] = {
          ContentFR = "Ah... c’est vous.",
          DialogueId = 12022912,
          GUID = "1E191D00",
          NextDialogue = 12022913,
          SpeakNpcId = 210004,
          Subtitle = "Ah... it's you.",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191D00"
        },
        [12022913] = {
          ContentFR = "Puis-je connaître votre opinion éclairée ? Je vous écoute.",
          DialogueId = 12022913,
          GUID = "1E191D2A",
          NextDialogue = 12022914,
          SpeakNpcId = 210004,
          Subtitle = "Pray tell — what sage counsel would you share with us?",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191D2A"
        },
        [12022914] = {
          ContentFR = "« Tuer et piller attire la colère du Ciel » — tel est l’antique précepte des Neuf Chapitres de Dafeng !",
          DialogueId = 12022914,
          GUID = "1E191D54",
          NextDialogue = 12022915,
          SpeakNpcId = 210031,
          SpeakNpcName = "UI_CMName_Name_ZhongNianNan",
          Subtitle = "\"To kill or steal is to be forsaken by Heaven\" — this is an ancient tenet of the Nine Chapters!",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191D54"
        },
        [12022915] = {
          ContentFR = "... Mais attaquer des Bi’an obscurs n’entraîne pourtant aucune sanction, non ?",
          DialogueId = 12022915,
          GUID = "1E191D7E",
          NextDialogue = 12022916,
          SpeakNpcId = 210077,
          SpeakNpcName = "UI_CMName_Name_WeiGuanZhe",
          Subtitle = "...But attacking the Sable Bi'an — surely that's no crime?",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191D7E"
        },
        [12022916] = {
          ContentFR = "Les Neuf Chapitres de Dafeng ne sauraient être interprétés avec une telle légèreté !",
          DialogueId = 12022916,
          GUID = "1E191DA8",
          NextDialogue = 12022917,
          SpeakNpcId = 210031,
          SpeakNpcName = "UI_CMName_Name_ZhongNianNan",
          Subtitle = "The Nine Chapters of Dafeng are not so shallow as that!",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191DA8"
        },
        [12022917] = {
          ContentFR = "Tout commence dans le cœur et se manifeste dans les actes. Une fois les armes levées, l’âme se corrompt. Qu’elles soient tournées vers un allié ou un ennemi, leur nature demeure identique ! C’est aller à l’encontre de la volonté céleste !",
          DialogueId = 12022917,
          GUID = "1E191DD2",
          NextDialogue = 12022918,
          SpeakNpcId = 210031,
          SpeakNpcName = "UI_CMName_Name_ZhongNianNan",
          Subtitle = "It begins in the heart and takes shape in one's deeds. Once a blade is drawn, the heart is changed — no matter if that blade is turned on friend or foe, the nature of it is the same. In the end... it defies the will of Heaven!",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191DD2"
        },
        [12022918] = {
          ContentFR = "Selon vous, nous devrions donc rester immobiles, ne rien faire, et attendre d’être dévorés... est-ce bien cela ?",
          DialogueId = 12022918,
          GUID = "1E191DFC",
          NextDialogue = 12022919,
          SpeakNpcId = 210004,
          Subtitle = "So you're saying we should stand idle, do nothing — and let them devour us? Is that it?",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191DFC"
        },
        [12022919] = {
          ContentFR = "Le Seigneur Dragon d’Argent chassera le mal pour nous ! Si nous provoquons Son courroux et perdons Sa protection, ce serait là la véritable ruine. Je vous en prie, réfléchissez !",
          DialogueId = 12022919,
          GUID = "1E191E26",
          NextDialogue = 12022920,
          SpeakNpcId = 210031,
          SpeakNpcName = "UI_CMName_Name_ZhongNianNan",
          Subtitle = "Lord Argent will drive this evil away for us! If we provoke Their wrath and lose Their protection, that would be our true ruin. I beg you — please reconsider!",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191E26"
        },
        [12022920] = {
          ContentFR = "Le précédent de la Bataille de Shuli ne nous a-t-il donc rien appris ?!",
          DialogueId = 12022920,
          GUID = "1E191E50",
          NextDialogue = 12022921,
          RelatedWikiId = {
            [1] = 401003
          },
          SpeakNpcId = 210031,
          SpeakNpcName = "UI_CMName_Name_ZhongNianNan",
          Subtitle = "Have we learned nothing from the lesson of the Battle of Shuli!?",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191E50"
        },
        [12022921] = {
          ContentFR = "Il n’a peut-être pas tort...",
          DialogueId = 12022921,
          GUID = "1E191E7A",
          NextDialogue = 12022922,
          SpeakNpcId = 210077,
          SpeakNpcName = "UI_CMName_Name_WeiGuanZhe",
          Subtitle = "He has a point...",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191E7A"
        },
        [12022922] = {
          ContentFR = "Vraiment ? Alors dites-moi : maintenant que les Bi’an obscurs assiègent Éternel Printemps, où se trouve la protection du Seigneur Dragon d’Argent ?",
          DialogueId = 12022922,
          GUID = "1E191EA4",
          NextDialogue = 12022923,
          SpeakNpcId = 210004,
          Subtitle = "Oh? Then enlighten me — now that these Sable Bi'an are tearing through our gates, where is Lord Argent's protection?",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191EA4"
        },
        [12022923] = {
          ContentFR = "Les Bi’an et les Magistrats de Yingtian arriveront bientôt. Il suffit d’attendre encore un peu...",
          DialogueId = 12022923,
          GUID = "1E191ECE",
          NextDialogue = 12022924,
          SpeakNpcId = 210031,
          SpeakNpcName = "UI_CMName_Name_ZhongNianNan",
          Subtitle = "The argent Bi'an and the Magistrates of Yingtian will come. We only have to endure a little longer...",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191ECE"
        },
        [12022924] = {
          ContentFR = "Et s’ils arrivent trop tard ? Que ferez-vous alors ?",
          DialogueId = 12022924,
          GUID = "1E191EF8",
          NextDialogue = 12022925,
          SpeakNpcId = 210004,
          Subtitle = "And if they come too late — what then?",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191EF8"
        },
        [12022925] = {
          ContentFR = "Eh bien...",
          DialogueId = 12022925,
          GUID = "1E191F22",
          NextDialogue = 12022926,
          SpeakNpcId = 210031,
          SpeakNpcName = "UI_CMName_Name_ZhongNianNan",
          Subtitle = "Well...",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191F22"
        },
        [12022926] = {
          ContentFR = "Si vous placez réellement les dogmes divins au-dessus de votre propre vie, je respecte cette droiture. Du Li, raccompagnez ce monsieur.",
          DialogueId = 12022926,
          GUID = "1E191F4C",
          NextDialogue = 12022927,
          SpeakNpcId = 210004,
          Subtitle = "If you truly place divine law above your own life — such devotion is admirable. Du Li, see this gentleman out.",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191F4C"
        },
        [12022927] = {
          ContentFR = "Nos voies divergent. Mon Éternel Printemps, si éloigné des orthodoxies, n’est sans doute pas un lieu fait pour vous.",
          DialogueId = 12022927,
          GUID = "1E191F76",
          NextDialogue = 12022928,
          SpeakNpcId = 210004,
          Subtitle = "It seems we do not share the same mind. My EverSpring may be too unorthodox a place for you to remain.",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191F76"
        },
        [12022928] = {
          ContentFR = "Mais... Patronne Zhiliu, les Bi’an obscurs sévissent encore dehors. Le renvoyer seul pourrait être dangereux...",
          DialogueId = 12022928,
          GUID = "1E191FA0",
          NextDialogue = 12022929,
          SpeakNpcId = 210032,
          Subtitle = "But... Miss Zhiliu, the Sable Bi'an are still outside. Sending him away now could be dangerous...",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191FA0"
        },
        [12022929] = {
          ContentFR = "Comment ? Mes ordres ne seraient-ils plus dignes d’être suivis ?",
          DialogueId = 12022929,
          GUID = "1E191FCA",
          NextDialogue = 12022930,
          SpeakNpcId = 210004,
          Subtitle = "Oh? Are you defying my orders now?",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191FCA"
        },
        [12022930] = {
          ContentFR = "... À vos ordres !",
          DialogueId = 12022930,
          GUID = "1E191FF4",
          SpeakNpcId = 210032,
          Subtitle = "...No, Miss Zhiliu! I'll do it right away!",
          VoiceName = "voice/$Locale$/story/1201/120229/1E191FF4"
        },
        [12023001] = {
          Camera = "197.917969,691.520508,260.698242,0.000206,-17.289721,-77.722221,11.88,100000.0,false,Manual,2.8",
          ContentFR = "Patronne Zhiliu...",
          DialogueId = 12023001,
          GUID = "1E192B9A",
          NextDialogue = 12023002,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003,
            [3] = 304004,
            [4] = 303010,
            [5] = 406004,
            [6] = 401003
          },
          SpeakNpcId = 100001,
          Subtitle = "Proprietress Zhiliu...",
          VoiceName = "voice/$Locale$/story/1201/120230/1E192B9A"
        },
        [12023002] = {
          ContentFR = "... {nickname}. Tu as tout vu, n’est-ce pas ?",
          DialogueId = 12023002,
          GUID = "1E192BC4",
          NextOptions = {
            [1] = 120230021,
            [2] = 120230022,
            [3] = 120230023,
            [4] = 120230024
          },
          SpeakNpcId = 210004,
          Subtitle = "...You heard everything, didn't you, ?",
          VoiceName = "voice/$Locale$/story/1201/120230/1E192BC4"
        },
        [12023003] = {
          ContentFR = "... L’homme doit d’abord se sauver lui-même avant d’espérer l’aide du Ciel.",
          DialogueId = 12023003,
          GUID = "1E192BEE",
          NextDialogue = 12023004,
          SpeakNpcId = 210004,
          Subtitle = "...One must first help oneself — only then will Heaven be moved to help in turn.",
          VoiceName = "voice/$Locale$/story/1201/120230/1E192BEE"
        },
        [12023004] = {
          ContentFR = "Mais l’urgence ne nous permet pas de philosopher davantage.",
          DialogueId = 12023004,
          GUID = "1E192C18",
          NextDialogue = 12023005,
          SpeakNpcId = 210004,
          Subtitle = "But there's no time to linger on philosophy now. The situation is urgent.",
          VoiceName = "voice/$Locale$/story/1201/120230/1E192C18"
        },
        [12023005] = {
          ContentFR = "{nickname}, puis-je te confier le renfort du front devant le Temple du Dragon d’Argent ?",
          DialogueId = 12023005,
          GUID = "1E192C42",
          NextDialogue = 12023006,
          SpeakNpcId = 210004,
          Subtitle = ", can I entrust you with reinforcing the front plaza by the Argent Loong Temple?",
          VoiceName = "voice/$Locale$/story/1201/120230/1E192C42"
        },
        [12023006] = {
          ContentFR = "Il suffit de tenir encore un moment. Une fois les préparatifs des officiants d’encens achevés, cette crise sera définitivement résolue. Ta rémunération sera ajustée en conséquence.",
          DialogueId = 12023006,
          GUID = "1E192C6C",
          NextDialogue = 12023007,
          SpeakNpcId = 210004,
          Subtitle = "Hold out just a little longer. Once the incense wardens have completed their preparations, this crisis will be fully resolved. As for your pay — there will be extra compensation on top of what we agreed before.",
          VoiceName = "voice/$Locale$/story/1201/120230/1E192C6C"
        },
        [12023007] = {
          ContentFR = "Je comprends.",
          DialogueId = 12023007,
          GUID = "1E192C96",
          SpeakNpcId = 100001,
          Subtitle = "Understood. Leave it to me.",
          VoiceName = "voice/$Locale$/story/1201/120230/1E192C96"
        },
        [12023101] = {
          ContentFR = "Les préparatifs sont achevés —",
          DialogueId = 12023101,
          GUID = "1E193C02",
          Subtitle = "The rites are complete—",
          VoiceName = "voice/$Locale$/story/1201/120231/1E193C02"
        },
        [12023102] = {
          ContentFR = "Huaxu resplendit, ses lois demeurent. Nous implorons les cieux, et l’ordre répond.",
          DialogueId = 12023102,
          GUID = "1E193C2C",
          NextDialogue = 12023103,
          Subtitle = "Huaxu gleams resplendent, its laws unshaken; Heaven hearkens our plea, order shall awaken.",
          VoiceName = "voice/$Locale$/story/1201/120231/1E193C2C"
        },
        [12023103] = {
          ContentFR = "Les encens s’élèvent, les parfums se rassemblent. Les souillures s’effacent, la grâce se répand.",
          DialogueId = 12023103,
          GUID = "1E193C56",
          NextDialogue = 12023104,
          Subtitle = "Incense coils in solemn flight, blessings rise; cleanse foulness' blight.",
          VoiceName = "voice/$Locale$/story/1201/120231/1E193C56"
        },
        [12023104] = {
          ContentFR = "Peuple de Huaxu, marche droit et respecte la loi. Que les conflits cessent, que l’ordre perdure.",
          DialogueId = 12023104,
          GUID = "1E193C80",
          Subtitle = "Ye folk of Huaxu's hallowed sod — walk in virtue, heed the creed; justice binds, let peace and concord ever lead.",
          VoiceName = "voice/$Locale$/story/1201/120231/1E193C80"
        },
        [12023201] = {
          ContentFR = "Pfiou... enfin terminé.",
          DialogueId = 12023201,
          GUID = "1E194C6A",
          NextDialogue = 12023202,
          SpeakNpcId = 200002,
          Subtitle = "Phew... Finally done with all that!",
          VoiceName = "voice/$Locale$/story/1201/120232/1E194C6A"
        },
        [12023202] = {
          ContentFR = "Petit larbin ! Avec tout ça, on n’a même pas encore remis les Écailles de Zhuyin à Zhiliu ! Allons vite la retrouver !",
          DialogueId = 12023202,
          GUID = "1E194C94",
          SpeakNpcId = 200002,
          Subtitle = "And with all this craziness, we didn't even get a chance to give Zhiliu those Zhuyin Scales yet! C'mon, Little Minion — let's go find her and hand them over!",
          VoiceName = "voice/$Locale$/story/1201/120232/1E194C94"
        },
        [12023301] = {
          Camera = "212.574219,845.443359,223.21582,0.0,-10.914123,-63.608265,11.88,100000.0,false,Manual,2.8",
          ContentFR = "La crise d’Éternel Printemps est enfin passée. Quel soulagement...",
          DialogueId = 12023301,
          GUID = "1E195CD2",
          NextDialogue = 12023302,
          RelatedWikiId = {
            [1] = 408010,
            [2] = 304003,
            [3] = 304004,
            [4] = 303010,
            [5] = 406004
          },
          SpeakNpcId = 100001,
          Subtitle = "EverSpring's safe again. That's great.",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195CD2"
        },
        [12023302] = {
          ContentFR = "Patronne Zhiliu ! Voilà les Écailles de Zhuyin que tu voulais ! Alors ? Avoue que Snow et le petit larbin sont impressionnants !",
          DialogueId = 12023302,
          GUID = "1E195CFC",
          NextDialogue = 12023303,
          SpeakNpcId = 200002,
          Subtitle = "Miss Zhiliu, we got those Zhuyin Scales you wanted! Aren't we awesome? C'mon, a little praise would be nice~!",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195CFC"
        },
        [12023303] = {
          ContentFR = "Hm. Vous avez bien travaillé. Merci.",
          DialogueId = 12023303,
          GUID = "1E195D26",
          NextDialogue = 12023304,
          SpeakNpcId = 210004,
          Subtitle = "Well done. I truly appreciate it.",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195D26"
        },
        [12023304] = {
          ContentFR = "Patronne Zhiliu... vous semblez épuisée. Tout va bien ?",
          DialogueId = 12023304,
          GUID = "1E195D50",
          NextDialogue = 12023305,
          SpeakNpcId = 100001,
          Subtitle = "Proprietress Zhiliu... are you alright?",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195D50"
        },
        [12023305] = {
          ContentFR = "Je n’imaginais pas que le Fléau de Zhuyin frapperait avec une telle rapidité. Ces derniers jours ont été éprouvants, voilà tout.",
          DialogueId = 12023305,
          GUID = "1E195D7A",
          NextDialogue = 12023306,
          SpeakNpcId = 210004,
          Subtitle = "I did not expect the Scourge of Zhuyin to strike so swiftly. Days of unbroken effort... I confess, I am a little weary — nothing more.",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195D7A"
        },
        [12023306] = {
          ContentFR = "Heureusement, grâce aux Écailles de Zhuyin que vous avez rapportées, les choses avancent à nouveau. Une fois le sceau rétabli, cette épreuve prendra fin.",
          DialogueId = 12023306,
          GUID = "1E195DA4",
          NextDialogue = 12023307,
          SpeakNpcId = 210004,
          Subtitle = "But with these scales, the path ahead is clear again. Once the Zhuyin is sealed, this ordeal will be behind us.",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195DA4"
        },
        [12023307] = {
          ContentFR = "Ton intervention a été décisive, {nickname}. Tu es arrivé à temps.",
          DialogueId = 12023307,
          GUID = "1E195DCE",
          NextDialogue = 12023308,
          SpeakNpcId = 210004,
          Subtitle = "Your presence was a timely boon, . I could not have weathered this alone.",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195DCE"
        },
        [12023308] = {
          ContentFR = "Nous avons perçu le danger depuis le sommet de la Mer de Poussière et sommes revenus en toute hâte. Heureusement, il n’était pas trop tard.",
          DialogueId = 12023308,
          GUID = "1E195DF8",
          NextDialogue = 12023309,
          SpeakNpcId = 100001,
          Subtitle = "We sensed the danger at the top of the Gritblight Expanse. That's why we came rushing back — I'm just glad we made it in time.",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195DF8"
        },
        [12023309] = {
          ContentFR = "Dis, petit larbin... la voix que tu as entendue quand tu ramassais les Écailles de Zhuyin, tu ne devrais pas aussi en parler à Zhiliu ?",
          DialogueId = 12023309,
          GUID = "1E195E22",
          NextDialogue = 12023310,
          SpeakNpcId = 200002,
          Subtitle = "Hey, Little Minion — shouldn't you tell Zhiliu about the voice you heard when we were gathering those scales?",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195E22"
        },
        [12023310] = {
          ContentFR = "Une voix ?",
          DialogueId = 12023310,
          GUID = "1E195E4C",
          NextOptions = {
            [1] = 120233101
          },
          SpeakNpcId = 210004,
          Subtitle = "A voice?",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195E4C"
        },
        [12023311] = {
          ContentFR = "Lorsque j’ai touché les Écailles de Zhuyin, j’ai entendu une voix... Elle semblait liée aux Bi’an obscurs et connaître leurs mouvements.",
          DialogueId = 12023311,
          GUID = "1E195E76",
          NextDialogue = 12023312,
          SpeakNpcId = 100001,
          Subtitle = "When I touched the Zhuyin Scales, I suddenly heard a voice in my head. It felt like it was connected to the Sable Bi'an — like it was tracking them and knew where they'd attack next.",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195E76"
        },
        [12023312] = {
          ContentFR = "Si nous pouvions entrer en contact avec elle, nous obtiendrions peut-être davantage d’informations.",
          DialogueId = 12023312,
          GUID = "1E195EA0",
          NextDialogue = 12023313,
          SpeakNpcId = 100001,
          Subtitle = "If we could find a way to talk to it, maybe we could learn more.",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195EA0"
        },
        [12023313] = {
          ContentFR = "... Tu as sans doute mal interprété les choses.",
          DialogueId = 12023313,
          GUID = "1E195ECA",
          NextOptions = {
            [1] = 120233131
          },
          SpeakNpcId = 210004,
          Subtitle = "...You were likely just imagining things.",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195ECA"
        },
        [12023314] = {
          ContentFR = "Mais cette voix a prédit l’attaque d’Éternel Printemps. C’est grâce à elle que nous sommes revenus à temps. Cela ne prouve-t-il pas qu’elle n’est pas hostile ?",
          DialogueId = 12023314,
          GUID = "1E195EF4",
          NextDialogue = 12023315,
          SpeakNpcId = 100001,
          Subtitle = "But it warned me about the attack on EverSpring — that's how I knew to come back in time. Doesn't that mean it isn't hostile?",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195EF4"
        },
        [12023315] = {
          ContentFR = "J’ai entendu dire qu’au plus profond de la Mer de Poussière subsiste un miasme trouble. Ceux qui y sont exposés souffrent parfois d’hallucinations — sons, visions, souvenirs erronés. Un peu de repos suffit généralement à dissiper ces effets.",
          DialogueId = 12023315,
          GUID = "1E195F1E",
          NextDialogue = 12023316,
          SpeakNpcId = 210004,
          Subtitle = "I've heard of a strange miasma deep within the Gritblight Expanse. Exposure can bring hallucinations — voices, visions, even false memories. Usually, a proper rest is needed to dispel it.",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195F1E"
        },
        [12023316] = {
          ContentFR = "Vous avez déjà beaucoup accompli. Le voyage, les combats, la collecte des Écailles... À présent que le calme est revenu, prenez le temps de souffler.",
          DialogueId = 12023316,
          GUID = "1E195F48",
          NextDialogue = 12023317,
          SpeakNpcId = 210004,
          Subtitle = "You've already done much: travelling without pause, gathering these scales for me... Now that things are calm, take some time to rest. Walk around, catch your breath.",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195F48"
        },
        [12023317] = {
          ContentFR = "Ah, et à propos de la jeune femme que vous avez secourue au marché noir : son état a évolué. Fushu, praticienne du Zhuyou, m’a demandé de vous transmettre un message. Elle souhaite vous voir au Pavillon de l’Éphémère pour décider de la suite.",
          DialogueId = 12023317,
          GUID = "1E195F72",
          NextDialogue = 12023318,
          SpeakNpcId = 210004,
          Subtitle = "Oh, and the young lady you rescued from the black market. Her condition seems to have taken a turn. Miss Fushu, the Zhuyou therapy user, asked me to pass on a message — she'd like you to visit the Hall of Ephemerality so that you can make further plans.",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195F72"
        },
        [12023318] = {
          ContentFR = "En quittant Éternel Printemps, empruntez le sentier sinueux sur la gauche. Le pavillon se trouve au cœur d’un bosquet d’abricotiers.",
          DialogueId = 12023318,
          GUID = "1E195F9C",
          NextDialogue = 12023319,
          SpeakNpcId = 210004,
          Subtitle = "Leave through EverSpring's main gate, then take the small winding path to your left. You'll find the Hall there — a quiet place among the blossoms.",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195F9C"
        },
        [12023319] = {
          ContentFR = "Je comprends.",
          DialogueId = 12023319,
          GUID = "1E195FC6",
          NextDialogue = 12023320,
          SpeakNpcId = 100001,
          Subtitle = "Mm... Got it.",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195FC6"
        },
        [12023320] = {
          ContentFR = "Patronne Zhiliu... aurez-vous encore besoin de notre aide pour sceller Zhuyin ?",
          DialogueId = 12023320,
          GUID = "1E195FF0",
          NextDialogue = 12023321,
          SpeakNpcId = 100001,
          Subtitle = "Proprietress Zhiliu, will you still need our help with the Zhuyin sealing later?",
          VoiceName = "voice/$Locale$/story/1201/120233/1E195FF0"
        },
        [12023321] = {
          ContentFR = "Héhé... sois tranquille. Si une situation dépasse mes moyens, je ferai de nouveau appel à vous.",
          DialogueId = 12023321,
          GUID = "1E19601A",
          SpeakNpcId = 210004,
          Subtitle = "Hehe... rest assured. Should anything prove too troublesome for me alone, I'll be sure to call on you again.",
          VoiceName = "voice/$Locale$/story/1201/120233/1E19601A"
        },
        [12023401] = {
          ContentFR = "Snow... n’as-tu pas l’impression que Zhiliu cherchait surtout à nous écarter ?",
          DialogueId = 12023401,
          GUID = "1E196D3A",
          NextDialogue = 12023402,
          SpeakNpcId = 100001,
          Subtitle = "Is it just me, or was Zhiliu trying to brush us off just now?",
          VoiceName = "voice/$Locale$/story/1201/120234/1E196D3A"
        },
        [12023402] = {
          ContentFR = "Hein ?! Maintenant que tu le dis... peut-être bien. Mais pourquoi ferait-elle ça ?",
          DialogueId = 12023402,
          GUID = "1E196D64",
          NextDialogue = 12023403,
          SpeakNpcId = 200002,
          Subtitle = "Huh!? Now that you mention it... yeah, I kinda felt that too. But... why would she want to do that?",
          VoiceName = "voice/$Locale$/story/1201/120234/1E196D64"
        },
        [12023403] = {
          ContentFR = "... Bof ! Tant pis ! Allons-y ! Ce qui compte, c’est la récompense qui nous attend, pas vrai ?",
          DialogueId = 12023403,
          GUID = "1E196D8E",
          SpeakNpcId = 200002,
          Subtitle = "...Eh, whatever! No point guessing. Let's just focus on what really matters: the payment we're about to get!",
          VoiceName = "voice/$Locale$/story/1201/120234/1E196D8E"
        },
        [12023500] = {
          Content = "无由生很感谢，给了你好东西。【待包装】",
          DialogueId = 12023500,
          GUID = "1E197D78",
          NextDialogue = 12023501,
          SpeakNpcId = 210041
        },
        [12023501] = {
          Content = "介绍无由生被困的缘由（叙事向）【待包装】",
          DialogueId = 12023501,
          GUID = "1E197DA2",
          SpeakNpcId = 210041
        },
        [12023510] = {
          Content = "无由生很感谢，给了你好东西。【待包装】",
          DialogueId = 12023510,
          GUID = "1E197F1C",
          NextDialogue = 12023511,
          SpeakNpcId = 210042
        },
        [12023511] = {
