            [5] = 12025422
          }
        },
        [12025501] = {
          ContentFR = "Vous êtes donc l’illustre {性别:invité|invitée} que la Patronne Zhiliu a fait venir d’Hyperborea, au prix d’un long voyage... Je ne m’attendais pas à ce que vous soyez si jeune et si {性别:élégant... ah— non, pardon, si jeune et si accompli !|élégante... ah— non, pardon, si jeune et si accomplie !}",
          DialogueId = 12025501,
          GUID = "1E1AC5C2",
          NextDialogue = 12025502,
          SpeakNpcId = 210116,
          Subtitle = "You must be the honoured guest Miss Zhiliu invited all the way from Hyperborea. I didn't expect you to be so young and so good-loo— ahem... I mean, so accomplished!"
        },
        [12025502] = {
          ContentFR = "La Patronne Zhiliu est habituellement très occupée, toujours prise par les affaires, et elle a rarement un moment de répit. Si jamais quelque chose vous semble manquer ou vous cause le moindre désagrément, venez me voir : je m’en chargerai personnellement.",
          DialogueId = 12025502,
          GUID = "1E1AC5EC",
          NextDialogue = 12025521,
          SpeakNpcId = 210116,
          Subtitle = "Proprietress Zhiliu is often occupied, with very little time to spare. If there's anything we may have overlooked, please let me know — I'll attend to it immediately."
        },
        [12025503] = {
          ContentFR = "<I>Quel genre de guilde est Éternel Printemps ?</>",
          DialogueId = 12025503,
          GUID = "1E1AC616",
          NextDialogue = 12025504,
          Subtitle = "What kind of guild is EverSpring?"
        },
        [12025504] = {
          ContentFR = "Non seulement à Port-des-Brumes, mais dans toute Haojing, Éternel Printemps est la plus grande des chambres de commerce.",
          DialogueId = 12025504,
          GUID = "1E1AC640",
          NextDialogue = 12025505,
          SpeakNpcId = 210116,
          Subtitle = "EverSpring isn't just the biggest guild around Mistwharf — it's the largest in all of Haojing."
        },
        [12025505] = {
          ContentFR = "La vie des habitants de Huaxu en dépend profondément : qu’il s’agisse de produits du quotidien, de marchandises rares venues d’outre-mer, de l’acheminement des épices, ou même des démarches pour devenir Tisse-Étoiles... tout passe par Éternel Printemps.",
          DialogueId = 12025505,
          GUID = "1E1AC66A",
          NextDialogue = 12025506,
          SpeakNpcId = 210116,
          Subtitle = "The people of Huaxu rely on EverSpring for almost everything — from everyday necessities and rare imports to the transport and distribution of incense, and even the procedures for becoming a Starweaver. All of it is handled through us."
        },
        [12025506] = {
          ContentFR = "Comme vous pouvez le constater, les étals devant nous proposent des marchandises venues des quatre coins du monde. Vous êtes libre d’y faire vos achats. Toutes les transactions sont garanties par le Bureau de la Fortune Céleste et les Neuf Chapitres de Dafeng.",
          DialogueId = 12025506,
          GUID = "1E1AC694",
          NextDialogue = 12025507,
          SpeakNpcId = 210116,
          Subtitle = "As you can see, the stalls outside EverSpring offer goods from all across the land. You're welcome to browse freely. Every transaction here is supervised by the Ministry of Fortune and governed by the Nine Chapters of Dafeng."
        },
        [12025507] = {
          ContentFR = "Et si vous souhaitez devenir Tisse-Étoiles, un guichet se trouve juste à côté pour déposer votre dossier. Nous proposons de nombreux programmes de soutien : prêts de départ, formations complètes à la navigation commerciale... le tout sans frais.",
          DialogueId = 12025507,
          GUID = "1E1AC6BE",
          NextDialogue = 12025521,
          SpeakNpcId = 210116,
          Subtitle = "If you're interested in becoming a Starweaver, you may submit your application at the window over there. We also provide comprehensive support — from start-up loans to full, complimentary training in navigation across international trade routes."
        },
        [12025508] = {
          ContentFR = "<I>Le Décret d’Interdiction a-t-il eu un fort impact sur la population ?</>",
          DialogueId = 12025508,
          GUID = "1E1AC6E8",
          NextDialogue = 12025509,
          Subtitle = "How badly has the lockdown affected everyone here?"
        },
        [12025509] = {
          ContentFR = "Il a certes causé quelques désagréments... mais c’était inévitable. Il vise principalement les régions intérieures affectées par les Bi’an obscurs.",
          DialogueId = 12025509,
          GUID = "1E1AC712",
          NextDialogue = 12025510,
          SpeakNpcId = 210116,
          Subtitle = "It has caused some inconvenience, that's true... but it was unavoidable. The restrictions mainly apply to the inland regions affected by Sable Bi'an."
        },
        [12025510] = {
          ContentFR = "Après tout, la sécurité de chacun est la priorité absolue d’Éternel Printemps. Je suis convaincue que, lorsque la patronne aura trouvé un moyen de sceller de nouveau Zhuyin, la vie reprendra rapidement son cours normal.",
          DialogueId = 12025510,
          GUID = "1E1AC73C",
          NextDialogue = 12025511,
          SpeakNpcId = 210116,
          Subtitle = "After all, the safety of everyone is what EverSpring must prioritise above all else. I'm confident that once Miss Zhiliu finds a way to seal Zhuyin again, things will return to normal soon enough."
        },
        [12025511] = {
          ContentFR = "Avec votre aide, ce jour arrivera sans doute bien plus tôt.",
          DialogueId = 12025511,
          GUID = "1E1AC766",
          NextDialogue = 12025521,
          SpeakNpcId = 210116,
          Subtitle = "And with your help, I believe that day will come all the sooner."
        },
        [12025512] = {
          ContentFR = "<I>Comment est la Patronne Zhiliu, au juste ?</>",
          DialogueId = 12025512,
          GUID = "1E1AC790",
          NextDialogue = 12025513,
          Subtitle = "What's Proprietress Zhiliu like?"
        },
        [12025513] = {
          ContentFR = "Oh, la patronne est... incroyable ! Peu importe la difficulté, elle trouve toujours une solution, et sans jamais perdre son sang-froid.",
          DialogueId = 12025513,
          GUID = "1E1AC7BA",
          NextDialogue = 12025514,
          SpeakNpcId = 210116,
          Subtitle = "She's incredible! No matter how difficult the situation, she handles it with effortless composure."
        },
        [12025514] = {
          ContentFR = "Elle est le Haut Chancelier de Longyuan, assiste le Bureau de la Fortune Céleste, et dirige Éternel Printemps... Rien que d’y penser, on peine à imaginer tout ce qu’elle doit gérer. À la place de quiconque d’autre, le poids serait déjà écrasant.",
          DialogueId = 12025514,
          GUID = "1E1AC7E4",
          NextDialogue = 12025515,
          SpeakNpcId = 210116,
          Subtitle = "She serves as the High Chancellor of Loongyuan, assists the Ministry of Fortune, and still oversees EverSpring. It's difficult for people like us to imagine just how much she manages — anyone else would have been overwhelmed long ago."
        },
        [12025515] = {
          ContentFR = "Mais pour elle, tout cela semble aller de soi. Chaque fois que je la vois, elle est calme, assurée, parfaitement maîtresse de la situation. Rien que sa présence apaise les esprits.",
          DialogueId = 12025515,
          GUID = "1E1AC80E",
          NextDialogue = 12025516,
          SpeakNpcId = 210116,
          Subtitle = "But none of it ever seems to weigh on her. Whenever you see her, she is so calm and assured that her presence alone puts you at ease."
        },
        [12025516] = {
          ContentFR = "Ah... je me rends compte que je parle sans m’arrêter.",
          DialogueId = 12025516,
          GUID = "1E1AC838",
          NextDialogue = 12025517,
          SpeakNpcId = 210116,
          Subtitle = "Ah... listen to me, going on like this."
        },
        [12025517] = {
          ContentFR = "C’est un peu embarrassant à admettre, mais... j’admire profondément la patronne.",
          DialogueId = 12025517,
          GUID = "1E1AC862",
          NextDialogue = 12025518,
          SpeakNpcId = 210116,
          Subtitle = "It's a little embarrassing to say out loud, but I truly admire Miss Zhiliu..."
        },
        [12025518] = {
          ContentFR = "Elle semble d’ailleurs vous porter une attention toute particulière. Or, les invités de la patronne sont les invités d’Éternel Printemps. Alors n’hésitez pas : si vous avez besoin de quoi que ce soit, je ferai tout mon possible pour vous aider.",
          DialogueId = 12025518,
          GUID = "1E1AC88C",
          NextDialogue = 12025521,
          SpeakNpcId = 210116,
          Subtitle = "She seems to hold you in especially high regard. And her guest is EverSpring's guest. If you need anything, simply let me know — I'll do everything within my power to assist."
        },
        [12025519] = {
          ContentFR = "<I>Je n’ai plus de questions.</>",
          DialogueId = 12025519,
          GUID = "1E1AC8B6",
          NextDialogue = 12025520,
          Subtitle = "That's all for now."
        },
        [12025520] = {
          ContentFR = "Si jamais vous avez besoin de quoi que ce soit, revenez me voir. Je serai toujours ici pour vous assister.",
          DialogueId = 12025520,
          GUID = "1E1AC8E0",
          SpeakNpcId = 210116,
          Subtitle = "If you ever need anything, feel free to come find me — I'll be here."
        },
        [12025521] = {
          DialogueId = 12025521,
          DialoguePanelType = "None",
          Duration = 0,
          FinalDialogueId = 12025520,
          GUID = "1E1AC8E1",
          NextOptions = {
            [1] = 12025503,
            [2] = 12025508,
            [3] = 12025512,
            [4] = 12025519
          }
        },
        [12025601] = {
          ContentFR = "...",
          DialogueId = 12025601,
          GUID = "1E1AD62A",
          NextDialogue = 12025602,
          SpeakNpcId = 210117,
          Subtitle = "..."
        },
        [12025602] = {
          ContentFR = "N’ayant plus la force de lutter, le Magistrat de Yingtian grièvement blessé s’endort profondément sous vos yeux. Son front reste crispé : il semble peu probable qu’il se réveille de sitôt...",
          DialogueId = 12025602,
          GUID = "1E1AD654",
          NextDialogue = 12025603,
          Subtitle = "(Before you, the wounded Magistrate of Yingtian sinks into a deep sleep, his brow tightly furrowed. He doesn't seem to be waking anytime soon...)"
        },
        [12025603] = {
          ContentFR = "Les Magistrats de Yingtian rêvent-ils eux aussi ? Que peut-il bien voir, prisonnier de ses songes ? Malgré vous, la question s’impose à votre esprit.",
          DialogueId = 12025603,
          GUID = "1E1AD67E",
          NextDialogue = 12025604,
          Subtitle = "(Do Magistrates of Yingtian dream as well? What does he see in his dreams? You can't help wondering.)"
        },
        [12025604] = {
          ContentFR = "Alors, petit larbin... tu admires l’œuvre magistrale de ton Roi Démon ?",
          DialogueId = 12025604,
          GUID = "1E1AD6A8",
          NextDialogue = 12025605,
          SpeakNpcName = "UI_Npc_Name_Bai",
          Subtitle = "Whatcha doing, little minion? Admiring my masterpiece?"
        },
        [12025605] = {
          ContentFR = "Si tu veux, je peux aussi te dessiner un magnifique graffiti Luno sur le visage ! Après tout, tant que ça vient de mon petit larbin, aucun souhait n’est trop extravagant !",
          DialogueId = 12025605,
          GUID = "1E1AD6D2",
          NextDialogue = 12025606,
          SpeakNpcName = "UI_Npc_Name_Bai",
          Subtitle = "If you like it, I can doodle something cute on your face too! Perks of being my minion!"
        },
        [12025606] = {
          ContentFR = "... Merci, Snow. Allons-y maintenant. Il vaut mieux ne pas traîner.",
          DialogueId = 12025606,
          GUID = "1E1AD6FC",
          SpeakNpcId = 100001,
          Subtitle = "...Thanks, Snow. Come on, we should get moving."
        },
        [12025701] = {
          ContentFR = "Hé, vous deux... Alors comme ça, vous êtes vraiment des {性别:invités|invitées} de la Patronne Zhiliu.",
          DialogueId = 12025701,
          GUID = "1E1AE692",
          NextDialogue = 12025702,
          SpeakNpcId = 210118,
          Subtitle = "Hey, you two — so you really are Proprietress Zhiliu's guests, huh."
        },
        [12025702] = {
          ContentFR = "Je monte la garde ici tous les jours. Des gens qui essaient de s’infiltrer au marché noir, j’en vois à la pelle — j’ai entendu toutes les excuses possibles. Mais des gens aussi téméraires que vous, c’est une première.",
          DialogueId = 12025702,
          GUID = "1E1AE6BC",
          NextDialogue = 12025703,
          SpeakNpcId = 210118,
          Subtitle = "I'm on the lookout here every day. People try to sneak into the market all the time — I've heard every excuse under the sun. But I've never seen anyone as reckless as you two."
        },
        [12025703] = {
          ContentFR = "Puisque vous êtes désormais des hôtes de marque de Maître Qiu... héhé... Vous pourriez pas glisser un petit mot en ma faveur auprès du patron ? Dites-lui que Zhang San, l’un de ses hommes, est prêt à se dévouer corps et âme pour lui !",
          DialogueId = 12025703,
          GUID = "1E1AE6E6",
          NextDialogue = 12025704,
          SpeakNpcId = 210118,
          Subtitle = "Since you're Mr Qiu's honoured guests now... heh, could you put in a good word for me with the boss? Just tell him that his man Zhang San is ready to work himself to the bone to serve him!"
        },
        [12025704] = {
          ContentFR = "Ça fait des lustres que je monte la garde ici, à fixer l’entrée de Chant-des-Marées jusqu’à en avoir les yeux qui brûlent. Avec la roue du destin qui tourne, ça devrait bien être mon tour de décrocher un poste un peu plus... rentable, non ?",
          DialogueId = 12025704,
          GUID = "1E1AE710",
          NextDialogue = 12025705,
          SpeakNpcId = 210118,
          Subtitle = "I'm stuck keeping watch here every damn day — staring so long I'm starting to see the other side of Tidesong Cavern in my sleep. And hey, luck's supposed to turn, right? Shouldn't it be my turn to land a gig with some actual payoff?"
        },
        [12025705] = {
          ContentFR = "On ne va quand même pas me refiler tout le sale boulot éternellement... pas vrai ?",
          DialogueId = 12025705,
          GUID = "1E1AE73A",
          SpeakNpcId = 210118,
          Subtitle = "You can't keep dumping all the dirty work on one poor man, right? I mean, tell me I'm not wrong here."
        },
        [12025801] = {
          ContentFR = "Ah... te voilà, {性别:mon jeune ami|ma jeune amie}. Assieds-toi.",
          DialogueId = 12025801,
          GUID = "1E1AF6FA",
          NextDialogue = 12025802,
          SpeakNpcId = 210119,
          Subtitle = "Ah, you're here. Sit down, my young friend."
        },
        [12025802] = {
          ContentFR = "De l’écorce de mandarine affinée cent ans, tout juste infusée. Humecte-toi la gorge, puis raconte-moi ton voyage.",
          DialogueId = 12025802,
          GUID = "1E1AF724",
          NextDialogue = 12025828,
          SpeakNpcId = 210119,
          Subtitle = "I've just brewed a cup of tangerine peel tea, aged for centuries. Let it soothe your throat, then indulge me with tales of your travels."
        },
        [12025803] = {
          ContentFR = "<I>Pourquoi collectionnez-vous autant d’antiquités ?</>",
          DialogueId = 12025803,
          GUID = "1E1AF74E",
          NextDialogue = 12025804,
          Subtitle = "Why surround yourself with so many antiques?"
        },
        [12025804] = {
          ContentFR = "Le désir est une chose profonde. Vouloir, c’est chercher à posséder — c’est l’instinct le plus sincère de toute forme de vie.",
          DialogueId = 12025804,
          GUID = "1E1AF778",
          NextDialogue = 12025805,
          SpeakNpcId = 210119,
          Subtitle = "Desire shapes the very core of life. To yearn is to seek, and to seek is to claim — a drive as old as existence itself."
        },
        [12025805] = {
          ContentFR = "Et puis, les antiquités ne sont pas de simples objets inertes. Chacune a vécu dans l’histoire de quelqu’un. Dire qu’elles portent en elles des siècles entiers n’a rien d’exagéré.",
          DialogueId = 12025805,
          GUID = "1E1AF7A2",
          NextDialogue = 12025806,
          SpeakNpcId = 210119,
          Subtitle = "And these so-called \"antiques\" are far from mere lifeless trinkets. Each one has breathed another's story, a thread woven into countless ages of history."
        },
        [12025806] = {
          ContentFR = "C’est... assez abstrait. Pas facile à saisir.",
          DialogueId = 12025806,
          GUID = "1E1AF7CC",
          NextDialogue = 12025807,
          SpeakNpcId = 100001,
          Subtitle = "That sounds awfully abstract and cryptic."
        },
        [12025807] = {
          ContentFR = "Cette dague, par exemple : elle a repoussé des envahisseurs, assassiné un souverain, puis suivi son maître dans la mort.\nEt ce bol fêlé : il a accueilli un voyageur, vu partir un être cher, avant d’être renversé lors d’un pari littéraire.",
          DialogueId = 12025807,
          GUID = "1E1AF7F6",
          NextDialogue = 12025808,
          SpeakNpcId = 210119,
          Subtitle = "Take this dagger, for instance. It once repelled invaders, cut down monarchs, and ultimately perished by its master's side. And this cracked teacup? It welcomed weary travellers and saw off loved ones, only to be toppled in a wager of wit and verse."
        },
        [12025808] = {
          ContentFR = "Quand je touche ces objets, j’ai l’impression que nous ne sommes pas seuls ici.\nSept ou huit scènes, une douzaine de visages, des siècles entiers réunis dans une même pièce. Voilà pourquoi je les collectionne. Et pourquoi je ne m’arrêterai jamais.",
          DialogueId = 12025808,
          GUID = "1E1AF820",
          NextDialogue = 12025828,
          SpeakNpcId = 210119,
          Subtitle = "When I hold these relics, it feels as though we're no longer alone in this room. Figures from ages past seem to gather with us — seven or eight scenes, each carrying centuries of memories. That, my young friend, is why I gather them... and why I shall never stop."
        },
        [12025809] = {
          ContentFR = "<I>On dit que vous êtes d’une avidité sans bornes.</>",
          DialogueId = 12025809,
          GUID = "1E1AF84A",
          NextDialogue = 12025810,
          Subtitle = "I've heard you're quite insatiable."
        },
        [12025810] = {
          ContentFR = "Sans bornes ? J’aime beaucoup ce qualificatif.",
          DialogueId = 12025810,
          GUID = "1E1AF874",
          NextDialogue = 12025811,
          SpeakNpcId = 210119,
          Subtitle = "Insatiable? I must say, I find that rather flattering."
        },
        [12025811] = {
          ContentFR = "Si je n’étais pas avide, ce serait un gâchis. D’innombrables trésors et secrets resteraient enfouis dans le passé, à jamais oubliés.",
          DialogueId = 12025811,
          GUID = "1E1AF89E",
          NextDialogue = 12025812,
          SpeakNpcId = 210119,
          Subtitle = "Were I not \"insatiable,\" I'd be forsaking all the treasures this world holds. Countless relics and untold secrets would remain entombed in time, never to grace the light of day again."
        },
        [12025812] = {
          ContentFR = "Refuser le désir, c’est nier la loi la plus simple de ce monde : le désir fait avancer l’homme, il est le moteur même de l’évolution.",
          DialogueId = 12025812,
          GUID = "1E1AF8C8",
          NextDialogue = 12025813,
          SpeakNpcId = 210119,
          Subtitle = "And if one suppresses desire, doesn't that defy the most fundamental truth of life? Desire propels us forward; it spurs every inch of progress."
        },
        [12025813] = {
          ContentFR = "Tout le monde ne partage pas ce point de vue.",
          DialogueId = 12025813,
          GUID = "1E1AF8F2",
          NextDialogue = 12025814,
          SpeakNpcId = 100001,
          Subtitle = "Not everyone sees it that way."
        },
        [12025814] = {
          ContentFR = "Peu importe. Tu peux appeler cela une justification éhontée. Moi, j’y vois simplement une fidélité à soi-même, une liberté assumée.",
          DialogueId = 12025814,
          GUID = "1E1AF91C",
          NextDialogue = 12025815,
          SpeakNpcId = 210119,
          Subtitle = "It matters little. Call it brazen sophistry if you wish — I prefer to call it embracing one's nature and living true to oneself."
        },
        [12025815] = {
          ContentFR = "Beaucoup rêvent de devenir comme moi... mais n’osent pas l’être. À force de se cacher derrière règles et principes, ils ne deviennent même plus eux-mêmes. Ils préfèrent m’insulter de loin. Pathétique.",
          DialogueId = 12025815,
          GUID = "1E1AF946",
          NextDialogue = 12025802,
          SpeakNpcId = 210119,
          Subtitle = "Many wish to become like me, yet lack the courage to take the first step, let alone follow through. In their fear, they fail even to become their truest selves, hiding behind the safety of rules and morals while hurling insults my way from the shadows. Pitiful, isn't it?"
        },
        [12025816] = {
          ContentFR = "<I>Qui est Maître Gongshang ?</>",
          DialogueId = 12025816,
          GUID = "1E1AF970",
          NextDialogue = 12025817,
          Subtitle = "Who is Master Gongshang?"
        },
        [12025817] = {
          ContentFR = "Un prodige excentrique de la Secte Jishu... que je soutiens financièrement.",
          DialogueId = 12025817,
          GUID = "1E1AF99A",
          NextDialogue = 12025818,
          SpeakNpcId = 210119,
          Subtitle = "A most singular craftsman of the Jishu Sect — one whom I now patronise."
        },
        [12025818] = {
          ContentFR = "On dit qu’un homme sans obsession n’est pas digne de compagnie. Et lui est, de tous ceux que j’ai rencontrés, le plus obsessionnel... et le plus déviant.",
          DialogueId = 12025818,
          GUID = "1E1AF9C4",
          NextDialogue = 12025819,
          SpeakNpcId = 210119,
          Subtitle = "There's a saying: a man without his peculiarities is hardly worth keeping company with. And among all the people I've met, his obsessions run the deepest, and his manner is the most unconventional."
        },
        [12025819] = {
          ContentFR = "L’excentricité ne me dérange pas. La médiocrité, si. Son talent en matière de mécanismes est sans égal. S’il n’avait pas méprisé les méthodes du Bureau des Travaux, il n’aurait jamais quitté leurs rangs... ni eu besoin de moi.",
          DialogueId = 12025819,
          GUID = "1E1AF9EE",
          NextDialogue = 12025820,
          SpeakNpcId = 210119,
          Subtitle = "Strange temperaments don't trouble me — mediocrity does. In craftsmanship, there are few today who can match his skill. Had he not taken issue with the Ministry of Works' methods, he wouldn't have left their ranks, nor would he have needed my support."
        },
        [12025820] = {
          ContentFR = "Un homme comme lui pourrait m’insulter en face que je n’en rirais que davantage.",
          DialogueId = 12025820,
          GUID = "1E1AFA18",
          NextDialogue = 12025828,
          SpeakNpcId = 210119,
          Subtitle = "A character like that... he could hurl insults right to my face, and I'd simply laugh them off."
        },
        [12025821] = {
          ContentFR = "<I>Êtes-vous allié à la Patronne Zhiliu ?</>",
          DialogueId = 12025821,
          GUID = "1E1AFA42",
          NextDialogue = 12025822,
          Subtitle = "Are you and Proprietress Zhiliu partners?"
        },
        [12025822] = {
          ContentFR = "Si tu appelles « alliance » une relation fondée sur l’intérêt mutuel... alors oui.",
          DialogueId = 12025822,
          GUID = "1E1AFA6C",
          NextDialogue = 12025823,
          SpeakNpcId = 210119,
          Subtitle = "If you wish to call a relationship built on mutual interest a partnership, then yes."
        },
        [12025823] = {
          ContentFR = "Et si un jour elle ne pouvait plus vous offrir ce que vous cherchez... la trahiriez-vous ?",
          DialogueId = 12025823,
          GUID = "1E1AFA96",
          NextDialogue = 12025824,
          SpeakNpcId = 100001,
          Subtitle = "And if one day she couldn't give you what you wanted anymore... would you betray her?"
        },
        [12025824] = {
          ContentFR = "Ha ha ! Voilà une question bien naïve, {性别:mon jeune ami|ma jeune amie}. Il n’existe ni amis éternels, ni ennemis éternels. Les positions changent sans cesse. Parler de trahison n’a donc guère de sens.",
          DialogueId = 12025824,
          GUID = "1E1AFAC0",
          NextDialogue = 12025825,
          SpeakNpcId = 210119,
          Subtitle = "Hah. My young friend, that is a rather naive question. There are no eternal friends, nor eternal enemies. People's ties shift constantly — so what does \"betrayal\" really amount to?"
        },
        [12025825] = {
          ContentFR = "Mais sois rassuré : ta Patronne Zhiliu est une femme avisée. Elle sait lier les autres à elle par l’intérêt, solidement, sur un même navire. Le jour que tu évoques n’arrivera probablement jamais.",
          DialogueId = 12025825,
          GUID = "1E1AFAEA",
          NextDialogue = 12025828,
          SpeakNpcId = 210119,
          Subtitle = "Still, this is not something you need worry about. Proprietress Zhiliu is a shrewd woman. She binds people to her through shared interests — firmly enough that the day you speak of is unlikely ever to come."
        },
        [12025826] = {
          ContentFR = "<I>Je vais y aller.</>",
          DialogueId = 12025826,
          GUID = "1E1AFB14",
          NextDialogue = 12025827,
          Subtitle = "I should get going."
        },
        [12025827] = {
          ContentFR = "Va. Je ne te raccompagne pas.",
          DialogueId = 12025827,
          GUID = "1E1AFB3E",
          SpeakNpcId = 210119,
          Subtitle = "Go on, then. I won't see you out."
        },
        [12025828] = {
          DialogueId = 12025828,
          DialoguePanelType = "None",
          Duration = 0,
          FinalDialogueId = 12025827,
          GUID = "1E1AFB3F",
          NextOptions = {
            [1] = 12025803,
            [2] = 12025809,
            [3] = 12025816,
            [4] = 12025821,
            [5] = 51155701,
            [6] = 12025826
          }
        },
        [12025901] = {
          ContentFR = "Merci... merci...",
          DialogueId = 12025901,
          GUID = "1E1B0762",
          NextDialogue = 12025902,
          SpeakNpcId = 210120,
          Subtitle = "Th—Thank you... for saving my life..."
        },
        [12025902] = {
          ContentFR = "La jeune femme devant vous est d’une pâleur extrême. De grosses gouttes de sueur perlent sur son front, et pourtant, elle s’efforce encore de vous remercier. Après avoir subi le châtiment du Bi’an, elle a manifestement besoin de repos.",
          DialogueId = 12025902,
          GUID = "1E1B078C",
          NextDialogue = 12025903,
          Subtitle = "(The young woman before you is pale as a ghost, sweat beading on her brow. Even so, she forces herself to thank you. After the Bi'an's punishment, she clearly needs rest.)"
        },
        [12025903] = {
          ContentFR = "Rassurez-vous, rassurez-vous ! Ici, on est entre amis ! Je veillerai sur elle comme sur la prunelle de mes yeux, pas un cheveu ne sera déplacé, je vous le jure !",
          DialogueId = 12025903,
          GUID = "1E1B07B6",
          NextDialogue = 12025904,
          SpeakNpcName = "UI_Npc_Name_Badshangren",
          Subtitle = "Don't worry, {性别：sir|ma'am} — we're all friends here! I'll take good care of her, not a single hair out of place! I swear it!"
        },
        [12025904] = {
          ContentFR = "Oh, par pitié, je vous en supplie... allez donc voir Maître Qiu. Ne le faites pas attendre trop longtemps. Tant que vous restez ici, elle n’arrivera pas à se reposer tranquillement.",
          DialogueId = 12025904,
          GUID = "1E1B07E0",
          SpeakNpcName = "UI_Npc_Name_Badshangren",
          Subtitle = "Please... {性别：sir|ma'am}, I'm begging you here — please go see Mr Qiu first! Don't keep him waiting. With you standing here, the girl just can't calm down and rest, can she?"
        },
        [12026001] = {
          ContentFR = "Alors, honorable {性别:apprenti|apprentie}, qu’est-ce que tu souhaites me demander ?",
          DialogueId = 12026001,
          GUID = "1E1B17CA",
          NextDialogue = 12026025,
          SpeakNpcId = 210121,
          Subtitle = "So, my honorary learner — what is it you want to ask?"
        },
        [12026002] = {
          ContentFR = "<I>Peux-tu m’expliquer à nouveau ce qu’est la Poussière-corrompue ?</>",
          DialogueId = 12026002,
          GUID = "1E1B17F4",
          NextDialogue = 12026003,
          Subtitle = "Could you explain what Gritblight is again?"
        },
        [12026003] = {
          ContentFR = "Ah... autrefois, une mémoire infaillible était la base même pour entrer dans la Secte Jishu. Les esprits trop lents étaient recalés dès l’enfance.",
          DialogueId = 12026003,
          GUID = "1E1B181E",
          NextDialogue = 12026004,
          SpeakNpcId = 210121,
          Subtitle = "Ah... back in my day, a good memory was the most basic requirement for joining the Jishu Sect. The slow-witted were weeded out while they were still toddlers."
        },
        [12026004] = {
          ContentFR = "Enfin... inutile de s’acharner. On ne force pas le talent. Ta soif de savoir n’est pas chose commune. Je vais donc te l’expliquer une fois encore.",
          DialogueId = 12026004,
          GUID = "1E1B1848",
          NextDialogue = 12026005,
          SpeakNpcId = 210121,
          Subtitle = "Ah, never mind. Talent can't be forced. Since you're willing to learn, that's good enough. I'll explain it once more."
        },
        [12026005] = {
          ContentFR = "L’air est imprégné d’une substance appelée Taixu, invisible et intangible. Et naturellement, tu te demandes : puisqu’on ne peut ni la voir ni la toucher, comment être certain qu’elle existe ?",
          DialogueId = 12026005,
          GUID = "1E1B1872",
          NextDialogue = 12026006,
          SpeakNpcId = 210121,
          Subtitle = "The air is suffused with something called Taixu, an unseen, intangible substance. And naturally, you'll ask: \"If we can't see it or touch it, how do we know it exists?\""
        },
        [12026006] = {
          ContentFR = "Nous, chercheurs, disposons de méthodes pour l’observer indirectement. Et la Poussière-corrompue en est la preuve la plus manifeste—",
          DialogueId = 12026006,
          GUID = "1E1B189C",
          NextDialogue = 12026007,
          SpeakNpcId = 210121,
          Subtitle = "Those of us who study it have ways to observe it indirectly. And Gritblight is the clearest proof that Taixu is real."
        },
        [12026007] = {
          ContentFR = "Sous l’influence du Fléau de Zhuyin, le Taixu présent dans l’air se transforme, se solidifie, et devient cette fine poudre qui se dépose à la surface des objets. Cette substance, nocive pour la plupart des formes de vie, voilà ce que nous appelons la Poussière-corrompue. Est-ce plus clair, à présent ?",
          DialogueId = 12026007,
          GUID = "1E1B18C6",
          NextDialogue = 12026025,
          SpeakNpcId = 210121,
          Subtitle = "When the Taixu in the air is disturbed by the Scourge of Zhuyin, its nature changes. It hardens into a fine powder that settles over everything — and that powder, harmful to ordinary life, is what we call Gritblight. Does it make sense to you now?"
        },
        [12026008] = {
          ContentFR = "<I>Peux-tu réexpliquer comment utiliser le Nexus mécanique ?</>",
          DialogueId = 12026008,
          GUID = "1E1B18F0",
          NextDialogue = 12026009,
          Subtitle = "Could you go over how to use the Mechanical Nexus again?"
        },
        [12026009] = {
          ContentFR = "Hmm ? J’ai rédigé des centaines de pages de manuel, conservées avec le Nexus mécanique chez Qin Qiu. Il ne vous les a pas transmises ?",
          DialogueId = 12026009,
          GUID = "1E1B191A",
          NextDialogue = 12026010,
          SpeakNpcId = 210121,
          Subtitle = "Hm? I hand-wrote hundreds of pages of instructions and left them with the device at Qin Qiu's place. He didn't give them to you?"
        },
        [12026010] = {
          ContentFR = "Non. Il m’a simplement envoyé te poser la question.",
          DialogueId = 12026010,
          GUID = "1E1B1944",
          NextDialogue = 12026011,
          SpeakNpcId = 100001,
          Subtitle = "No. He just sent me to ask you."
        },
        [12026011] = {
          ContentFR = "... Ce vieux renard. Je le savais. Il s’est sans doute dit que tu ne lirais pas un manuel aussi long, et qu’il était inutile de te le donner. Comme si {性别:un apprenti d’honneur de la Secte Jishu pouvait être aussi peu sérieux|une apprentie d’honneur de la Secte Jishu pouvait être aussi peu sérieuse} !",
          DialogueId = 12026011,
          GUID = "1E1B196E",
          NextDialogue = 12026012,
          SpeakNpcId = 210121,
          Subtitle = "...That old bastard. I knew it. He must've figured you wouldn't bother reading a manual that long, so he simply kept it from you. As if the Jishu Sect's honorary learner were so impatient and careless."
        },
        [12026012] = {
          ContentFR = "Peu importe. Je vais faire simple. C’est très facile : tu appuies sur ce bouton, tu vises la Poussière-corrompue... et tu aspires. Voilà.",
          DialogueId = 12026012,
          GUID = "1E1B1998",
          NextDialogue = 12026013,
          SpeakNpcId = 210121,
          Subtitle = "Forget it. I'll make it simple for you. It's easy — press this button, point it at the Gritblight, and it'll suck it in. That's all."
        },
        [12026013] = {
          ContentFR = "C’est tout ?",
          DialogueId = 12026013,
          GUID = "1E1B19C2",
          NextDialogue = 12026014,
          SpeakNpcId = 100001,
          Subtitle = "That's it?"
        },
        [12026014] = {
          ContentFR = "C’est tout. Tu t’attendais à ce que je t’explique aussi les principes théoriques, peut-être ?",
          DialogueId = 12026014,
          GUID = "1E1B19EC",
          NextDialogue = 12026015,
          SpeakNpcId = 210121,
          Subtitle = "That's it. Or did you expect me to start explaining the theory behind it as well?"
        },
        [12026015] = {
          ContentFR = "Non, non, ça me va très bien comme ça. Merci, maître !",
          DialogueId = 12026015,
          GUID = "1E1B1A16",
          NextDialogue = 12026025,
          Subtitle = "No, no — this is perfect. Thank you, shifu!"
        },
        [12026016] = {
          ContentFR = "<I>Pourquoi la Secte Jishu a-t-elle décliné ?</>",
          DialogueId = 12026016,
          GUID = "1E1B1A40",
          NextDialogue = 12026017,
          Subtitle = "Why has the Jishu Sect declined?"
        },
        [12026017] = {
          ContentFR = "Dans la Secte Jishu, la première chose que l’on apprend, c’est à observer le monde avec un esprit dialectique. Dis-moi donc : qu’appelles-tu un déclin ?",
          DialogueId = 12026017,
          GUID = "1E1B1A6A",
          NextDialogue = 12026018,
          SpeakNpcId = 210121,
          Subtitle = "We in the Jishu Sect are taught to look at things from more than one angle. So — what exactly do you mean by \"decline\"?"
        },
        [12026018] = {
          ContentFR = "Nos créations sont disséminées dans tout Huaxu, du sud au nord. Quel port n’emploie pas des chevaux mécaniques pour le transport des marchandises ? Et le Bureau des Travaux demeure l’un des trois grands bureaux de l’Empire. Appelles-tu cela un déclin ?",
          DialogueId = 12026018,
          GUID = "1E1B1A94",
          NextDialogue = 12026019,
          SpeakNpcId = 210121,
          Subtitle = "Our creations are found everywhere in Huaxu. At every dock you'll see wooden steeds hauling cargo. The Ministry of Works is still one of the three great ministries of Huaxu. And you call that \"decline\"?"
        },
        [12026019] = {
          ContentFR = "Euh... mais n’est-ce pas toi qui m’as dit que la Secte Jishu peinait à recruter de nouveaux disciples ?",
          DialogueId = 12026019,
          GUID = "1E1B1ABE",
          NextDialogue = 12026020,
          SpeakNpcId = 100001,
          Subtitle = "Um... but didn't you tell me the Jishu Sect had fallen on hard times and couldn't attract any new apprentices?"
        },
        [12026020] = {
          ContentFR = "Bien vu. Voilà l’autre facette du raisonnement dialectique.",
          DialogueId = 12026020,
          GUID = "1E1B1AE8",
          NextDialogue = 12026021,
          SpeakNpcId = 210121,
          Subtitle = "Sharp kid — from that angle, you're not wrong."
        },
        [12026021] = {
          ContentFR = "Le monde a perdu son désir d’apprendre. Plus personne ne souhaite rejoindre la Secte Jishu. Quant aux vieillards du Bureau des Travaux, ils se contentent de travailler en vase clos, sans plus chercher à comprendre les lois ultimes des choses... voilà le véritable déclin.",
          DialogueId = 12026021,
          GUID = "1E1B1B12",
          NextDialogue = 12026022,
          SpeakNpcId = 210121,
          Subtitle = "People have lost their desire to learn. No one wants to join the Jishu Sect anymore, and those hidebound old men in the Ministry of Works shut themselves away, tinkering all day but no longer seeking the highest principles — that, now, is decline."
        },
        [12026022] = {
          ContentFR = "Alors, pourquoi la Secte Jishu a-t-elle décliné ? À cause de la Secte Xuanheng. Ils redoutent que la puissance née du savoir échappe à leur contrôle. Ils ont donc affaibli la Secte Jishu. C’est aussi simple que cela.",
          DialogueId = 12026022,
          GUID = "1E1B1B3C",
          NextDialogue = 12026025,
          SpeakNpcId = 210121,
          Subtitle = "Now then, to answer your question: why has the Jishu Sect declined? Because of the Xuanheng Sect. They fear the power that comes with knowledge may slip beyond their control, so they suppressed the Jishu Sect until it weakened. It's as simple as that."
        },
        [12026023] = {
          ContentFR = "<I>J’ai encore beaucoup de questions... laisse-moi réfléchir.</>",
          DialogueId = 12026023,
          GUID = "1E1B1B66",
          NextDialogue = 12026024,
          Subtitle = "I've still got loads of questions... let me think."
        },
        [12026024] = {
          ContentFR = "Tu ne lâches pas prise tant que tu n’as pas compris le fond des choses... voilà un bon potentiel. Bien. J’ai à faire, et toi, n’oublie pas tes exercices quotidiens.",
          DialogueId = 12026024,
          GUID = "1E1B1B90",
          SpeakNpcId = 210121,
          Subtitle = "You keep digging until you truly grasp something — that's what I like to see. Now, I've work to do. Make sure you keep up with your daily practice."
        },
        [12026025] = {
          DialogueId = 12026025,
          DialoguePanelType = "None",
          Duration = 0,
          FinalDialogueId = 12026024,
          GUID = "1E1B1B91",
          NextOptions = {
            [1] = 12026002,
            [2] = 12026008,
            [3] = 12026016,
            [4] = 12026023
          }
        },
        [12026101] = {
          ContentFR = "Eh bien, qui voilà — {性别:le grand héros {nickname}, celui|la grande héroïne {nickname}, celle} qui a aidé Éternel Printemps à traverser la crise !",
          DialogueId = 12026101,
          GUID = "1E1B2832",
          NextDialogue = 12026102,
          SpeakNpcId = 210122,
          Subtitle = "Look who it is — , the hero who helped lead EverSpring through the crisis!"
        },
        [12026102] = {
          ContentFR = "Allons, allons... je n’ai fait que peu de chose. Le mérite revient surtout à la Patronne Zhiliu et à tout le monde ici.",
          DialogueId = 12026102,
          GUID = "1E1B285C",
          NextDialogue = 12026103,
          SpeakNpcId = 100001,
          Subtitle = "You flatter me. I only played a small part — most of the credit goes to Proprietress Zhiliu and everyone else."
        },
        [12026103] = {
          ContentFR = "Et toi ? Après tout ce qui s’est passé, comment te sens-tu ?",
          DialogueId = 12026103,
          GUID = "1E1B2886",
          NextDialogue = 12026104,
          SpeakNpcId = 100001,
          Subtitle = "And you? After all that's happened, how have you been?"
        },
        [12026104] = {
          ContentFR = "Ha ha... ça va peut-être te faire rire, mais au lieu d’être effrayée après coup, je ressens surtout une étrange exaltation. Avoir pu défendre notre foyer m’a donné l’impression qu’une force nouvelle s’était éveillée en moi.",
          DialogueId = 12026104,
          GUID = "1E1B28B0",
          NextDialogue = 12026105,
          SpeakNpcId = 210122,
          Subtitle = "It may sound a little silly, but instead of feeling shaken afterward, I actually felt... exhilarated. There was a quiet thrill in being able to protect our home, as though a steady strength had taken root within me."
        },
        [12026105] = {
          ContentFR = "J’envisage même d’apprendre quelques techniques de défense, histoire de ne plus dépendre uniquement des gardes lorsque je voyagerai dans des régions dangereuses.",
          DialogueId = 12026105,
          GUID = "1E1B28DA",
          NextDialogue = 12026106,
          SpeakNpcId = 210122,
          Subtitle = "I even found myself thinking about learning some basic self-defense, so that when I travel to more perilous regions for trade, I won't have to rely entirely on my escorts."
        },
        [12026106] = {
          ContentFR = "Mais... ce genre de pensée n’est sans doute pas conforme aux Neuf Chapitres de Dafeng...",
          DialogueId = 12026106,
          GUID = "1E1B2904",
          SpeakNpcId = 210122,
          Subtitle = "Although... thoughts like these do stray from the teachings of the Nine Chapters of Dafeng..."
        },
        [12026201] = {
          ContentFR = "Que se passe-t-il, {nickname} ? Tu voulais me parler ?",
          DialogueId = 12026201,
          GUID = "1E1B389A",
          NextDialogue = 12026202,
          SpeakNpcId = 210123,
          Subtitle = "What is it, ? Was there something you wished to discuss?"
        },
        [12026202] = {
          ContentFR = "L’attitude de Zhiliu ne diffère guère de l’ordinaire. Et pourtant, vous croyez percevoir chez elle une fatigue subtile... Est-ce seulement votre imagination ?",
          DialogueId = 12026202,
          GUID = "1E1B38C4",
          NextDialogue = 12026213,
          Subtitle = "(Her composure seems unchanged, yet you sense a faint weariness beneath it — something easy to overlook. Perhaps it is only your imagination.)"
        },
        [12026203] = {
          ContentFR = "<I>Patronne Zhiliu, quels sont vos projets à présent ?</>",
          DialogueId = 12026203,
          GUID = "1E1B38EE",
          NextDialogue = 12026204,
          Subtitle = "Proprietress Zhiliu, what will you do next?"
        },
        [12026204] = {
          ContentFR = "Grâce aux Écailles de Zhuyin que tu as rapportées, les préparatifs pour le scellement sont achevés. Je dois désormais m’y consacrer pleinement. Il se peut donc que je ne puisse pas vous recevoir pendant un temps. Permets-moi de m’en excuser par avance.",
          DialogueId = 12026204,
          GUID = "1E1B3918",
          NextDialogue = 12026205,
          SpeakNpcId = 210123,
          Subtitle = "With the Zhuyin scales you recovered, the preparations for the sealing are complete. I must now turn to the matters that follow, and may not be able to receive you for a while. Allow me to offer my apologies in advance."
        },
        [12026205] = {
          ContentFR = "Êtes-vous certaine de ne pas avoir besoin de mon aide ?",
          DialogueId = 12026205,
          GUID = "1E1B3942",
          NextDialogue = 12026206,
          SpeakNpcId = 100001,
          Subtitle = "Are you sure you don't need my help?"
        },
        [12026206] = {
          ContentFR = "Hé hé... ton intention est louable. Mais je ne peux pas te laisser tout assumer seul.\nSi une situation réellement épineuse se présente, je ferai de nouveau appel à vous.",
          DialogueId = 12026206,
          GUID = "1E1B396C",
          NextDialogue = 12026213,
          SpeakNpcId = 210123,
          Subtitle = "Heh... your offer is appreciated. But I cannot allow you to shoulder everything on your own. If a matter arises that truly requires your strength, I will seek your aid again."
        },
        [12026207] = {
          ContentFR = "<I>La crise qu’a traversée Éternel Printemps était vraiment dangereuse.</>",
          DialogueId = 12026207,
          GUID = "1E1B3996",
          NextDialogue = 12026208,
          Subtitle = "It was really dangerous back there."
        },
        [12026208] = {
          ContentFR = "En effet. Et tu y as largement contribué. Je te remercie, {nickname}.",
          DialogueId = 12026208,
          GUID = "1E1B39C0",
          NextDialogue = 12026209,
          SpeakNpcId = 210123,
          Subtitle = "Indeed. You played a part in resolving it as well. My thanks to you, ."
        },
        [12026209] = {
          ContentFR = "Je n’ai pas fait grand-chose. C’est vous qui avez su rassembler tout le monde, et réagir avec une telle rapidité.",
          DialogueId = 12026209,
          GUID = "1E1B39EA",
          NextDialogue = 12026210,
          SpeakNpcId = 100001,
          Subtitle = "I didn't do much. You were the one who brought everyone together — you handled everything so quickly and calmly."
        },
        [12026210] = {
          ContentFR = "Hé hé... hésiter à chaque pas, craindre d’agir... comment pourrait-on alors répondre aux attentes de tous ?",
          DialogueId = 12026210,
          GUID = "1E1B3A14",
          NextDialogue = 12026213,
          SpeakNpcId = 210123,
          Subtitle = "Heh... if one hesitates at every turn, forever weighing each step, how could one hope to shoulder the expectations and responsibilities placed upon them?"
        },
        [12026211] = {
          ContentFR = "<I>...</>",
          DialogueId = 12026211,
          GUID = "1E1B3A3E",
          NextDialogue = 12026212
        },
        [12026212] = {
          ContentFR = "Je vais maintenant m’occuper des dernières étapes du scellement de Zhuyin. Tu es libre pour le moment : va donc te promener. Tout ce que tu dépenseras sera porté à mon compte. N’aie aucune retenue.",
          DialogueId = 12026212,
          GUID = "1E1B3A68",
          SpeakNpcId = 210123,
          Subtitle = "I must see to the remaining preparations for the sealing. You have some time to yourself now — feel free to look around as you wish. Should you incur any expenses, have them charged to my account; think nothing of the cost."
        },
        [12026213] = {
          DialogueId = 12026213,
          DialoguePanelType = "None",
          Duration = 0,
          FinalDialogueId = 12026212,
          GUID = "1E1B3A69",
          NextOptions = {
            [1] = 12026203,
            [2] = 12026207,
            [3] = 12026211
          }
        },
        [12026301] = {
          ContentFR = "Merci... m-merci... Vous êtes venu me voir...",
          DialogueId = 12026301,
          GUID = "1E1B4902",
          NextDialogue = 12026302,
          SpeakNpcId = 210124,
          Subtitle = "You... my lifesaver... you came to see me..."
        },
        [12026302] = {
          ContentFR = "Vous sentez-vous un peu mieux ?",
          DialogueId = 12026302,
          GUID = "1E1B492C",
          NextDialogue = 12026303,
          SpeakNpcId = 100001,
          Subtitle = "Are you feeling any better now?"
        },
        [12026303] = {
          ContentFR = "Grâce aux remèdes que vous et Dame Fushu avez rapportés pour moi, mon état s’est stabilisé. D’ici un jour ou deux, je pourrai même me lever et marcher un peu.",
          DialogueId = 12026303,
          GUID = "1E1B4956",
          NextDialogue = 12026304,
          SpeakNpcId = 210124,
          Subtitle = "Thanks to the herbs you and Lady Fushu brought back for me, my injuries have started to settle. In another day or two, I might even be able to get out of bed and walk."
        },
        [12026304] = {
          ContentFR = "Après tout ce que j’ai traversé... j’ai reçu tant de bonté de votre part... Je... je ne sais pas comment vous rendre la pareille. Si jamais vous avez besoin de moi, dites-le-moi. Je ferai tout ce qui est en mon pouvoir.",
          DialogueId = 12026304,
          GUID = "1E1B4980",
          SpeakNpcId = 210124,
          Subtitle = "After everything that's happened, you've shown me more kindness than I can even put into words... I... I really don't know how to repay you. If there's ever anything I can do for you, just say the word. I'll do my best."
        },
        [12026401] = {
          ContentFR = "Si vous croisez des Wishen coincés près de la cascade, je vous en prie, portez-leur secours... Je vous remercie tous les deux.",
          DialogueId = 12026401,
          GUID = "1E1B596A",
          SpeakNpcId = 210125,
          Subtitle = "If you come across any Wishen stranded near the waterfall, please lend them your aid. My thanks to both of you."
        },
        [12026501] = {
          ContentFR = "Merci infiniment. Tous les Wishen disparus ont été sauvés, sains et saufs. Nous vous en sommes profondément reconnaissants.",
          DialogueId = 12026501,
          GUID = "1E1B69D2",
          SpeakNpcId = 210126,
          Subtitle = "My heartfelt thanks. With all the missing Wishen safely returned, we are deeply grateful for your help."
        },
        [12026601] = {
          ContentFR = "{nickname}, te voilà.",
          DialogueId = 12026601,
          GUID = "1E1B7A3A",
          NextDialogue = 12026602,
          SpeakNpcId = 210127,
          Subtitle = ", you've come."
        },
        [12026602] = {
          ContentFR = "J’ai toujours préféré le calme. En ces lieux du Pavillon de l’Éphémère, je n’ai rien de bien luxueux pour te recevoir : quelques traités médicaux, une théière... J’espère que cela ne t’ennuiera pas.",
          DialogueId = 12026602,
          GUID = "1E1B7A64",
          NextDialogue = 12026603,
          SpeakNpcId = 210127,
          Subtitle = "I am accustomed to quietude, and here in the Hall of Ephemerality I have little with which to receive you — only these shelves of medical texts and a pot of tea. I hope it does not strike you as too dull."
        },
        [12026603] = {
          ContentFR = "Tu peux te promener librement. Considère cet endroit comme ta propre demeure.",
          DialogueId = 12026603,
          GUID = "1E1B7A8E",
          NextDialogue = 12026640,
          SpeakNpcId = 210127,
          Subtitle = "You may move about as you please. Please make yourself at ease here."
        },
        [12026604] = {
          ContentFR = "<I>En dehors de soigner les gens, que fais-tu pendant ton temps libre ?</>",
          DialogueId = 12026604,
          GUID = "1E1B7AB8",
          NextDialogue = 12026605,
          Subtitle = "Apart from healing people, what do you do in your spare time?"
        },
        [12026605] = {
          ContentFR = "Prendre soin des patients occupe la majeure partie de mes journées. Si, par hasard, il m’arrive de voler quelques instants de répit... je relis les ouvrages médicaux que ma sœur a laissés derrière elle.",
          DialogueId = 12026605,
          GUID = "1E1B7AE2",
          NextDialogue = 12026606,
          SpeakNpcId = 210127,
          Subtitle = "Most of my days are taken up with tending to patients. Should I chance upon a rare moment of leisure... I would likely spend it reading the medical texts my elder sister left behind."
        },
        [12026606] = {
          ContentFR = "Mais... c’est encore soigner des gens, non ?",
          DialogueId = 12026606,
          GUID = "1E1B7B0C",
          NextDialogue = 12026607,
          SpeakNpcId = 100001,
          Subtitle = "Wouldn't that be basically the same as working?"
        },
        [12026607] = {
          ContentFR = "Lorsque le malade est devant moi, mon esprit s’agite et peine à se poser. Il m’est alors difficile d’étudier sereinement les liens subtils entre les remèdes. En revanche, ouvrir un livre au hasard, m’attarder sur ses passages obscurs... et soudain comprendre — cette sensation-là est une joie à part entière.",
          DialogueId = 12026607,
          GUID = "1E1B7B36",
          NextDialogue = 12026608,
          SpeakNpcId = 210127,
          Subtitle = "When a patient stands before me, my mind is seldom still, and I cannot quite settle myself to study the subtleties of medicine. Yet when I turn to some page of an old text and take my time with its more difficult passages, there often comes a moment of clarity — a quiet joy in its own right."
        },
        [12026608] = {
          ContentFR = "Tu n’as vraiment pas d’autres loisirs ?",
          DialogueId = 12026608,
          GUID = "1E1B7B60",
          NextDialogue = 12026609,
          SpeakNpcId = 100001,
          Subtitle = "So you don't have any hobbies besides that?"
        },
        [12026609] = {
          ContentFR = "Laisse-moi réfléchir... jouer quelques airs au qin, ou passer du temps à m’amuser avec Yunchi. C’étaient là les plaisirs de ma jeunesse.",
          DialogueId = 12026609,
          GUID = "1E1B7B8A",
          NextDialogue = 12026610,
          SpeakNpcId = 210127,
          Subtitle = "Let me think... Perhaps playing the zheng, or whiling away a little time with Yunchi — such were the quiet pleasures of my youth."
        },
        [12026610] = {
          ContentFR = "Alors, la prochaine fois, joue-moi un morceau.",
          DialogueId = 12026610,
          GUID = "1E1B7BB4",
          NextDialogue = 12026611,
          SpeakNpcId = 100001,
          Subtitle = "Then can you play a piece for me next time?"
        },
        [12026611] = {
          ContentFR = "... Oui. Comment ai-je pu l’oublier ? Le plus grand des plaisirs reste finalement la compagnie d’un ami. Qu’il s’agisse d’écouter de la musique ou de discuter librement, tout cela a une saveur particulière.",
          DialogueId = 12026611,
          GUID = "1E1B7BDE",
          NextDialogue = 12026612,
          SpeakNpcId = 210127,
          Subtitle = "...Indeed. How could I have forgotten? The greatest pleasure, I find, lies in the company of friends — whether we share music or speak at ease, there is a quiet delight in it."
        },
        [12026612] = {
          ContentFR = "{nickname}, tu peux venir me rendre visite ici quand tu le souhaites. Ta présence me fera plaisir.",
          DialogueId = 12026612,
          GUID = "1E1B7C08",
          NextDialogue = 12026613,
          SpeakNpcId = 210127,
          Subtitle = ", you are welcome to visit the Hall of Ephemerality whenever you have a moment to spare. Your company would be most welcome."
        },
        [12026613] = {
          ContentFR = "Marché conclu !",
          DialogueId = 12026613,
          GUID = "1E1B7C32",
          NextDialogue = 12026640,
          SpeakNpcId = 100001,
          Subtitle = "Then it's settled!"
        },
        [12026614] = {
          ContentFR = "<I>Ces derniers temps, je ne me sens pas très bien.</>",
          DialogueId = 12026614,
          GUID = "1E1B7C5C",
          NextDialogue = 12026615,
          Subtitle = "I've been feeling off lately."
        },
        [12026615] = {
          ContentFR = "Que se passe-t-il ? As-tu mal quelque part ? Te serais-tu {性别:blessé|blessée} en courant dans Port-des-Brumes ? Donne-moi ta main, je vais examiner cela attentivement.",
          DialogueId = 12026615,
          GUID = "1E1B7C86",
          NextDialogue = 12026616,
          SpeakNpcId = 210127,
          Subtitle = "What troubles you? Do you feel pain anywhere — or did you perhaps injure yourself while making your way through Mistwharf? Let me see your hand. I shall examine it carefully."
        },
        [12026616] = {
          ContentFR = "Haha... Fushu, tu es vraiment tendue.",
          DialogueId = 12026616,
          GUID = "1E1B7CB0",
          NextDialogue = 12026617,
          SpeakNpcId = 100001,
          Subtitle = "Haha... Fushu, you're so tense — you really do worry about me, don't you?"
        },
        [12026617] = {
          ContentFR = "Rien de grave, je me réveille juste souvent avec le dos et les épaules endoloris.",
          DialogueId = 12026617,
          GUID = "1E1B7CDA",
          NextDialogue = 12026618,
          SpeakNpcId = 100001,
          Subtitle = "It's nothing serious. I just wake up with a stiff back and aching shoulders, that's all."
        },
        [12026618] = {
          ContentFR = "La santé est une affaire sérieuse. Même les petits maux ne doivent pas être négligés. Je peux t’enseigner les Cinq Jeux des Animaux, une pratique qui assouplit le corps et renforce la vitalité.",
          DialogueId = 12026618,
          GUID = "1E1B7D04",
          NextDialogue = 12026619,
          SpeakNpcId = 210127,
          Subtitle = "Health is no trifling matter; even minor discomforts should not be overlooked. I can instruct you in the Five-Animal Frolics, which help loosen the limbs and fortify the body."
        },
        [12026619] = {
          ContentFR = "Pour en saisir pleinement l’esprit, cet exercice doit commencer à l’aube, lorsque les coqs chantent et que la nuit n’a pas encore tout à fait cédé sa place. Quand le soleil se lèvera et que la brise du matin effleurera ton visage, tu ressentiras un bien-être profond, du corps comme de l’esprit...",
          DialogueId = 12026619,
          GUID = "1E1B7D2E",
          NextDialogue = 12026620,
          SpeakNpcId = 210127,
          Subtitle = "To grasp the essence of the Five Animals, practice should begin at cockcrow, while the world is still dim with the last of night. As the morning light strengthens and a gentle breeze stirs, you will feel the ease and clarity this training brings to both body and mind."
        },
        [12026620] = {
          ContentFR = "N-non, ça ira !",
          DialogueId = 12026620,
          GUID = "1E1B7D58",
          NextDialogue = 12026621,
          SpeakNpcId = 100001,
          Subtitle = "I—I'm okay!"
        },
        [12026621] = {
          ContentFR = "En y repensant, je vais très bien. Même mieux que jamais ! Je n’ai jamais été aussi en forme de toute ma vie. Alors... merci pour ta proposition, mais inutile de la mettre en pratique !",
          DialogueId = 12026621,
          GUID = "1E1B7D82",
          NextDialogue = 12026622,
          SpeakNpcId = 100001,
          Subtitle = "You know what — I just realised I'm actually fine, perfectly fine. I've never been this healthy in my life! Thank you for your kind advice, but there's really no need to put it into action..."
        },
        [12026622] = {
          ContentFR = "<I>Soupir...</> franchement.",
          DialogueId = 12026622,
          GUID = "1E1B7DAC",
          NextDialogue = 12026623,
          SpeakNpcId = 210127,
          Subtitle = "*sigh*... ."
        },
        [12026623] = {
          ContentFR = "Très bien, pour cette fois, je te laisse t’en tirer ainsi. Mais si tu te sens de nouveau mal, ne fais pas preuve d’un courage inutile. Viens me voir, je m’en occuperai.",
          DialogueId = 12026623,
          GUID = "1E1B7DD6",
          NextDialogue = 12026640,
          SpeakNpcId = 210127,
          Subtitle = "I shall let it pass this time. But should you feel unwell again, do not force yourself to bear it alone. Come to me, and I shall ease your troubles."
        },
        [12026624] = {
          ContentFR = "<I>Depuis que tu es revenue de la Faille de l’Oubli, quelque chose semble te tracasser.</>",
          DialogueId = 12026624,
          GUID = "1E1B7E00",
          NextDialogue = 12026625,
          Subtitle = "You've seemed a bit off since you left the Oblivion Rift. Is something bothering you?"
        },
        [12026625] = {
          ContentFR = "Tu l’as remarqué... Merci de t’en soucier.",
          DialogueId = 12026625,
          GUID = "1E1B7E2A",
          NextDialogue = 12026626,
          SpeakNpcId = 210127,
          Subtitle = "You perceived it... Thank you for your concern."
        },
        [12026626] = {
          ContentFR = "{nickname}, toi aussi, tu as sans doute des proches qui comptent plus que tout pour toi. Si, par maladresse, tu disais quelque chose qui blessait l’un d’eux... que ferais-tu ?",
          DialogueId = 12026626,
          GUID = "1E1B7E54",
          NextDialogue = 12026627,
          SpeakNpcId = 210127,
          Subtitle = ", you too must have family who are dear to you. If you had, in a moment of carelessness, said something that caused them hurt... what would you do?"
        },
        [12026627] = {
          ContentFR = "Quand il s’agit de la famille, aucun conflit n’est impossible à résoudre. Si cela arrivait, je ferais tout pour m’excuser. Je suis {性别:sûr|sûre} qu’elle finirait par me pardonner.",
          DialogueId = 12026627,
          GUID = "1E1B7E7E",
          NextDialogue = 12026628,
          SpeakNpcId = 100001,
          Subtitle = "If it's family, there's nothing you can't work out. If something like that happened, I'd try my best to apologise — I'm sure she'd forgive me."
        },
        [12026628] = {
          ContentFR = "Et si cette personne n’était plus de ce monde... si tes excuses n’avaient plus d’oreille pour les entendre... que ferais-tu alors ?",
          DialogueId = 12026628,
          GUID = "1E1B7EA8",
          NextDialogue = 12026629,
          SpeakNpcId = 210127,
          Subtitle = "But if that person had already passed on, and there was no one left to hear your apology... what then?"
        },
        [12026629] = {
          ContentFR = "Fushu...",
          DialogueId = 12026629,
          GUID = "1E1B7ED2",
          NextDialogue = 12026630,
          SpeakNpcId = 100001,
          Subtitle = "Fushu..."
        },
        [12026630] = {
          ContentFR = "Pardonne-moi. Je n’aurais pas dû t’imposer mes propres tourments.",
          DialogueId = 12026630,
          GUID = "1E1B7EFC",
          NextDialogue = 12026631,
          SpeakNpcId = 210127,
          Subtitle = "Forgive me. I did not mean to burden you with my own sorrow."
        },
        [12026631] = {
          ContentFR = "Ce n’est rien. Si quelque chose te pèse, viens m’en parler. Je serai toujours là.",
          DialogueId = 12026631,
          GUID = "1E1B7F26",
          NextDialogue = 12026640,
          SpeakNpcId = 100001,
          Subtitle = "It's okay. If anything's ever bothering you, just come talk to me. I'm always there for you."
        },
        [12026632] = {
          ContentFR = "<I>Tu viens vraiment d’il y a cent ans ?</>",
          DialogueId = 12026632,
          GUID = "1E1B7F50",
          NextDialogue = 12026633,
          Subtitle = "So you really are from a hundred years ago?"
        },
        [12026633] = {
          ContentFR = "Oui... Comme je te l’ai déjà expliqué, afin de ralentir l’évolution de ma maladie, ma sœur a scellé mon corps dans le sommeil. Ce n’est que récemment que je me suis éveillée après cent années de torpeur.",
          DialogueId = 12026633,
          GUID = "1E1B7F7A",
          NextDialogue = 12026634,
          SpeakNpcId = 210127,
          Subtitle = "Mm... As I mentioned before, my elder sister placed my body in a deep sleep to arrest the course of my illness. Only recently was I awakened from that century of sleep."
        },
        [12026634] = {
          ContentFR = "Ce monde te paraît-il étranger, désormais ?",
          DialogueId = 12026634,
          GUID = "1E1B7FA4",
          NextDialogue = 12026635,
          SpeakNpcId = 100001,
          Subtitle = "Does the world feel strange to you now?"
        },
        [12026635] = {
          ContentFR = "Peut-être. À mon réveil, j’avais l’impression que les nuages, les herbes, chaque chose sous le ciel... n’avaient plus rien à voir avec moi.",
          DialogueId = 12026635,
          GUID = "1E1B7FCE",
          NextDialogue = 12026636,
          SpeakNpcId = 210127,
          Subtitle = "Perhaps. When I first awoke, the world felt distant — as though all things beneath the sky no longer concerned me."
        },
        [12026636] = {
          ContentFR = "Mais avec le temps, j’ai fini par rencontrer des {性别:amis|amies} comme toi.",
          DialogueId = 12026636,
          GUID = "1E1B7FF8",
          NextDialogue = 12026637,
          SpeakNpcId = 210127,
          Subtitle = "But as time passed, I came to meet companions such as yourself."
        },
        [12026637] = {
          ContentFR = "Les multiples visages du monde actuel, tout comme les progrès de la médecine, éveillent en moi une certaine curiosité. En y regardant autrement... c’est aussi une chance.",
          DialogueId = 12026637,
          GUID = "1E1B8022",
          NextDialogue = 12026640,
          SpeakNpcId = 210127,
          Subtitle = "The many changes in the world today, and the advances in medicine, are all new to me. In another light, that too may be considered a small blessing."
        },
        [12026638] = {
          ContentFR = "<I>Je vais y aller.</>",
          DialogueId = 12026638,
          GUID = "1E1B804C",
          NextDialogue = 12026639,
          Subtitle = "I should get going."
        },
        [12026639] = {
          ContentFR = "Va t’occuper de tes affaires. Et prends soin de ta santé.",
          DialogueId = 12026639,
          GUID = "1E1B8076",
          SpeakNpcId = 210127,
          Subtitle = "Go and see to your affairs — and take care of your health."
        },
        [12026640] = {
          DialogueId = 12026640,
          DialoguePanelType = "None",
          Duration = 0,
          FinalDialogueId = 12026639,
          GUID = "1E1B8077",
          NextOptions = {
            [1] = 12026604,
            [2] = 12026614,
            [3] = 12026624,
            [4] = 12026632,
            [5] = 12026638
          }
        },
        [12026701] = {
          ContentFR = "Yi—ya... yi-yi—ya... yi !",
          DialogueId = 12026701,
          GUID = "1E1B8AA2",
          NextDialogue = 12026702,
          SpeakNpcId = 210128,
          Subtitle = "Eee-ya... eeee-ya, eee!"
        },
        [12026702] = {
          ContentFR = "<I>Il flotte près de Fushu, l’air visiblement heureux.</>",
          DialogueId = 12026702,
          GUID = "1E1B8ACC",
          SpeakNpcId = 100001,
          Subtitle = "(It drifts beside Fushu, looking content.)"
        },
        [12026801] = {
          ContentFR = "La proie est déjà prise au filet. À partir de maintenant, chaque geste doit être mesuré. Surtout, ne l’alarmez pas.",
          DialogueId = 12026801,
          GUID = "1E1B9B0A",
          NextDialogue = 12026802,
          Subtitle = "The prey is already in the net. From here on, be doubly cautious — nothing that might alert them."
        },
        [12026802] = {
          ContentFR = "{nickname}, si tu es {性别:prêt|prête}, poursuivons.",
          DialogueId = 12026802,
          GUID = "1E1B9B34",
          Subtitle = "When you're ready, , we proceed."
        },
        [12026901] = {
          ContentFR = "Si mon intuition est juste, cette antique formation mécanique porte le nom de Formation des Mille-Serrures. Mille pivots pour amorcer le piège, dix mille interstices pour emprisonner jusqu’à la lumière elle-même.",
          DialogueId = 12026901,
          GUID = "1E1BAB72",
          NextDialogue = 12026902,
          Subtitle = "If I'm not mistaken, this ancient array's true name is the Myriad-Snare Hunting Array — crafted with countless snares that close in on the prey, and with gaps so fine they shut out even the faintest trace of light."
        },
        [12026902] = {
          ContentFR = "Voir une relique antique reprendre vie sous nos yeux... n’est-ce pas un spectacle grandiose ?",
          DialogueId = 12026902,
          GUID = "1E1BAB9C",
          Subtitle = "To witness such a relic awaken before our very eyes... quite a sight, wouldn't you say?"
        },
        [12027001] = {
          ContentFR = "Vous pouvez vous rendre au point culminant de la Mer de Poussière. La voie provisoire menant à l’Autel de Zhuyin est désormais achevée.",
          DialogueId = 12027001,
          GUID = "1E1BBBDA",
          NextDialogue = 12027002,
          SpeakNpcId = 210129,
          Subtitle = "You may proceed to the highest point of the Gritblight Expanse. The temporary path to the Zhuyin Altar has already been completed."
        },
        [12027002] = {
          ContentFR = "Une fois le rituel de scellement engagé, Zhuyin risque d’entrer en frénésie. Les abords de l’autel seront extrêmement dangereux. Soyez sur vos gardes.",
          DialogueId = 12027002,
          GUID = "1E1BBC04",
          NextDialogue = 12027003,
          SpeakNpcId = 210129,
          Subtitle = "Once the rite begins, Zhuyin may grow agitated and lash out. The area around the altar will be extremely dangerous, so please be very careful."
        },
        [12027003] = {
          ContentFR = "{性别:Chasseur de Phoxène|Chasseuse de Phoxène}, prenez soin de vous. Votre sécurité est notre priorité absolue. Je resterai ici et attendrai votre retour sain et sauf.",
          DialogueId = 12027003,
          GUID = "1E1BBC2E",
          SpeakNpcId = 210129,
          Subtitle = "Phoxhunter, please take care. Your safety is our utmost priority. I'll remain here and await your return."
        },
        [12027101] = {
          ContentFR = "Ma sœur n’est plus auprès de Lingsheng... Mais elle est heureuse, maintenant. Lingsheng peut le sentir.",
          DialogueId = 12027101,
          GUID = "1E1BCC42",
          SpeakNpcId = 210130,
          Subtitle = "Sister Feng is no longer with me... but she's happy now. I can feel it."
        },
        [12030001] = {
          ContentFR = "Il n’y a pas si longtemps, à Givrelac, une petite histoire a pris racine...",
          DialogueId = 12030001,
          Duration = 4,
          GUID = "1E1DA80A",
          NextDialogue = 12030002,
          Subtitle = "Not long ago, in the frost-kissed city of Icelake, a small tale began to unfold...",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA80A"
        },
        [12030002] = {
          ContentFR = "Celle d’un rossignol minuscule, qui, un jour, trouva le courage de quitter son nid chaud et étroit... pour s’élancer dans le vaste monde.",
          DialogueId = 12030002,
          Duration = 4,
          GUID = "1E1DA834",
          Subtitle = "It was the story of a little nightingale, who one day left her warm little nest... and flew into the wide, wide world.",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA834"
        },
        [12030003] = {
          Content = "菲娜坐在家里，看着故事书",
          DialogueId = 12030003,
          GUID = "1E1DA85E",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA85E"
        },
        [12030101] = {
          Content = "菲娜，晚上光线太暗，看书伤眼睛，还是早点睡吧。",
          DialogueId = 12030101,
          GUID = "1E1DB872",
          NextDialogue = 12030102,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB872"
        },
        [12030102] = {
          Content = "唔……",
          DialogueId = 12030102,
          GUID = "1E1DB89C",
          NextDialogue = 12030103,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB89C"
        },
        [12030103] = {
          Content = "怎么了？",
          DialogueId = 12030103,
          GUID = "1E1DB8C6",
          NextDialogue = 12030104,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB8C6"
        },
        [12030104] = {
          Content = "奥特赛德，菲娜……菲娜有一个愿望！",
          DialogueId = 12030104,
          GUID = "1E1DB8F0",
          NextDialogue = 12030105,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB8F0"
        },
        [12030105] = {
          Content = "是吗？你说，是什么愿望？",
          DialogueId = 12030105,
          GUID = "1E1DB91A",
          NextDialogue = 12030106,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB91A"
        },
        [12030106] = {
          Content = "菲娜想出去看看。",
          DialogueId = 12030106,
          GUID = "1E1DB944",
          NextDialogue = 12030107,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB944"
        },
        [12030107] = {
          Content = "出去……？现在吗？",
          DialogueId = 12030107,
          GUID = "1E1DB96E",
          NextDialogue = 12030108,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB96E"
        },
        [12030108] = {
          Content = "不是的，菲娜的意思是，菲娜也想像你和独角兽{性别：先生|小姐}一样，去外面的世界，认识很多的新朋友……",
          DialogueId = 12030108,
          GUID = "1E1DB998",
          NextDialogue = 12030109,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB998"
        },
        [12030109] = {
          Content = "这可不行，外面很危险的。我和{nickname}大多数时候遇到的都不是朋友，而是秽——怪兽，和很多坏——坏巫师，对，那些坏巫师可吓人了。",
          DialogueId = 12030109,
          GUID = "1E1DB9C2",
          NextDialogue = 12030110,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB9C2"
        },
        [12030110] = {
          Content = "所以，你还是待在家里最安全。",
          DialogueId = 12030110,
          GUID = "1E1DB9EC",
          NextDialogue = 12030111,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB9EC"
        },
        [12030111] = {
          Content = "呜……",
          DialogueId = 12030111,
          GUID = "1E1DBA16",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DBA16"
        },
        [12030112] = {
          ContentFR = "Nuit — Intérieur de la maison de Fina.\nFina dort paisiblement. L’Étranger remarque sur la table un livre d’histoires ouvert, laissé par Fina.",
          DialogueId = 12030112,
          GUID = "1E1DBA40",
          Subtitle = [[
At night, in Fina's home.
Fina sleeps peacefully. Outsider notices an open storybook on her desk.]],
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DBA40"
        },
        [12030201] = {
          Camera = "-345.501678,523.378906,124.574219,0.000322,-4.833527,90.822472,35.000008,77.550713,false,Manual,4.0",
          ContentFR = "« Le Grand Magicien répétait sans cesse : le monde au-delà du nid est rempli de dangers, rester à l’intérieur est la seule sécurité. Mais ce nid, aussi chaud soit-il, n’offrait qu’un carré de ciel. »",
          DialogueId = 12030201,
          FinalCamera = "-351.068237,428.320312,123.277344,0.000143,-3.242031,91.01268,35.000008,212.663025,false,Manual,2.8",
          GUID = "1E1DC8DA",
          LookAt = {
            [1] = "211002:p(pFeina_FixSimple02_LookAt01)"
          },
          NextDialogue = 12030202,
          Subtitle = "\"The Great Magician always said the world beyond the nest was dangerous — that only inside could the Little Nightingale be truly safe... But the nest, though warm and snug, held only a sliver of sky.\"",
          TalkActionId = {
            [1] = "211024:Feina_Story_Lieidle"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DC8DA"
        },
        [12030202] = {
          Camera = "-351.068237,428.320312,123.277344,0.000143,-3.242031,91.01268,35.000008,212.663025,false,Manual,2.8",
          ContentFR = "« Un jour, {性别:Monsieur|Mademoiselle} Licorne venue de contrées lointaines vint rendre visite au Rossignol, lui apportant des récits des horizons perdus... »",
          DialogueId = 12030202,
          FinalCamera = "-445.522095,482.669922,106.667969,0.000118,8.757859,54.209782,35.000008,212.663025,false,Manual,2.8",
          GUID = "1E1DC904",
          NextDialogue = 12030203,
          Subtitle = "\"Then one day, {性别:Mr|Miss} Unicorn came visiting — all the way from a faraway land — and spoke of wonders beyond the horizon...\"",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DC904"
        },
        [12030203] = {
          Camera = "-93.792816,296.109375,123.785156,0.000262,-14.836967,-25.180407,28.0,180.0,false,Manual,3.5",
          ContentFR = "« Un monde immense où des arbres dressaient leurs branches jusqu’à accrocher la lune, et où l’océan portait cent îles dans son étreinte... »",
          DialogueId = 12030203,
          FinalCamera = "-93.792816,296.109375,123.785156,0.000261,-34.236603,-38.179943,28.000006,63.699184,false,Manual,3.5",
          GUID = "1E1DC92E",
          NextDialogue = 12030204,
          Subtitle = "\"Of towering trees whose branches brushed the moon... Of oceans cradling a hundred islands in their arms...\"",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DC92E"
        }
      }
    end
  },
  {
    MinKey = 12030204,
