PlayAnimation{ActorId{211002},AnimationId{"Talk03_End"},Duration{1}},
PlayFacial{ActorId{100001},FacialId{"None"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "What a pity. I was hoping to polish up my animal training skills.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DEB24"
        },
        [12030411] = {
          ContentFR = "Tu ne me lâcheras donc jamais avec ça...",
          DialogueId = 12030411,
          GUID = "1E1DEB4E",
          NextDialogue = 12030412,
          Scripts = [[
