          GUID = "1E1E0CC6",
          Subtitle = "Point of Interest #2",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E0CC6"
        },
        [12030620] = {
          ContentFR = "Hein ? Petite, tu veux quelque chose ?",
          DialogueId = 12030620,
          GUID = "1E1E0D98",
          NextDialogue = 12030621,
          SpeakNpcId = 211016,
          Subtitle = "Hm? Something wrong, miss?",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E0D98"
        },
        [12030621] = {
          ContentFR = "Ah ! Désolée... je t’ai pris pour une patate grillée...",
          DialogueId = 12030621,
          GUID = "1E1E0DC2",
          SpeakNpcId = 211001,
          Subtitle = "Oops, sorry! I thought you were a roasted potato...",
