}
}]],
          SpeakNpcId = 211001,
          Subtitle = "That's it — friends! Maybe one of my magical friends can help! The Great Magician has the sharpest nose in the whole wide world... He'll sniff out those potatoes in no time!",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E3BDC"
        },
        [12030903] = {
