}]],
          SpeakNpcId = 211002,
          Subtitle = "...Alright, alright. As long as it makes you happy.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1E6DE6"
        },
        [12031301] = {
          ContentFR = "Aujourd’hui, c’est le deuxième jour de la grande aventure de Fina... Cette fois, je vais explorer un nouveau royaume !",
          DialogueId = 12031301,
          GUID = "1E1E7D52",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 211001,
          Subtitle = "Day two of Fina's grand adventure... Today, I'm gonna explore a whole new kingdom!",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7D52"
        },
        [12031302] = {
          Content = "前往冰湖城广场的垃圾桶附近",
          DialogueId = 12031302,
          GUID = "1E1E7D7C",
          VoiceName = "voice/$Locale$/story/1201/120112/1E1E7D7C"
        },
        [12031303] = {
          Camera = "85.892578,-283.888184,72.099121,0.000112,3.99984,115.145454,35.000015,231.188461,false,DoNotOverride,4.5",
          ContentFR = "Ouah, une feuille d’emballage si propre et si épaisse ! Parfait pour bricoler un nouveau plateau de jeu pour Freda et les autres...",
          DialogueId = 12031303,
          GUID = "1E1E7DA6",
          NextDialogue = 12031304,
          Scripts = [[
PARA{
MoveTo{ActorId{211001},TargetPoint{"feinafx12_moveto02"},MoveSpeed{100},Visibility{"Show"}},
PARA{
CameraMoveTo{_delay{4.01},TargetPosition{"-268.510742,359.411621,112.427979,0.000042,2.200202,-57.851643,35.000008,431.40448,false,DoNotOverride,2.8"},duration{0}},
SEQ{
