        [12031401] = {
          Camera = "-222.93663,-4.119965,77.036377,0.000147,5.602271,18.947176,35.000008,242.208893,false,DoNotOverride,2.8",
          ContentFR = "Beurk... que des déchets... Mais non, je ne dois pas avoir peur ! Je suis le courageux Petit Assistant de la grande Détective Taciturne. Je dois être forte et accomplir ma mission !",
          DialogueId = 12031401,
          GUID = "1E1E8DBA",
          NextDialogue = 12031402,
          Scripts = [[
