        [12032020] = {
          Camera = "38.812233,650.129028,234.697266,0.0001,-10.600248,-91.879105,35.000008,647.849792,false,Manual,2.8",
          ContentFR = "Bonjour, petite demoiselle. Tu voulais me parler ?",
          DialogueId = 12032020,
          FinalCamera = "-164.201019,591.00769,194.100586,0.000074,-10.800263,-73.479187,35.000008,647.849792,false,Manual,2.8",
          GUID = "1E1EF348",
          NextDialogue = 12032021,
          Scripts = [[
