]],
          SpeakNpcId = 211001,
          Subtitle = "Um... hello, little girl. Did you need something?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF348"
        },
        [12032021] = {
          Camera = "217.323044,-39.272888,141.890625,0.000088,-4.199924,169.11882,35.000011,350.246948,false,Manual,2.8",
          ContentFR = "« Petite » ?! Pour qui tu me prends ?! ... Peu importe. Réponds plutôt, tu sais utiliser la magie ?",
          DialogueId = 12032021,
          FinalCamera = "207.430786,-37.371925,141.150879,0.000088,-4.199924,169.11882,35.000011,350.246948,false,Manual,2.8",
          GUID = "1E1EF372",
          NextDialogue = 12032022,
          SpeakNpcId = 211012,
          Subtitle = "Excuse me!? Who are you calling little? Ugh, whatever. Just answer me — can you do magic?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF372"
        },
        [12032022] = {
          Camera = "-149.126572,195.659912,131.557373,0.0001,-1.999934,-51.077328,35.000008,335.198914,false,Manual,2.8",
          ContentFR = "Euh... un petit peu, oui.",
          DialogueId = 12032022,
          FinalCamera = "-140.549088,185.037964,131.080566,0.0001,-1.999934,-51.077328,35.000011,335.198914,false,Manual,2.8",
          GUID = "1E1EF39C",
          NextDialogue = 12032023,
          Scripts = [[
PARA{
PlayFacial{ActorId{211001},FacialId{"None"}},
PlayAnimation{ActorId{211001},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Mmm... a little, yes.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF39C"
        },
        [12032023] = {
          Camera = "112.474983,29.235161,104.275879,0.00011,2.399992,175.923996,35.000011,175.784409,false,Manual,2.8",
          ContentFR = "Parfait ! Euh... hum... Très bien. Écoute-moi bien, Charon : j’ai besoin de toi pour quelque chose. Rien de compliqué, il suffira que tu fasses exactement ce que je dis avec ta magie.",
          DialogueId = 12032023,
          FinalCamera = "92.418343,30.663937,105.118408,0.00011,2.399992,175.924088,35.000011,175.784409,false,Manual,2.8",
          GUID = "1E1EF3C6",
          NextDialogue = 12032024,
          Scripts = "PlayAnimation{ActorId{211012},AnimationId{\"Talk02_Start\"},Duration{1}}",
          SpeakNpcId = 211012,
          Subtitle = "That's so great! Ahem... I mean, okay. Listen up, Charon — I need your help with something. It's simple. Just follow my instructions and use your magic.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF3C6"
        },
        [12032024] = {
          Camera = "215.516998,-32.253654,134.083496,0.00012,-1.199907,171.523682,35.000011,270.662476,false,Manual,2.8",
          ContentFR = "Et pour ta récompense... tiens, regarde ! Ça devrait te suffire pour manger pendant une année entière, non ?",
          DialogueId = 12032024,
          FinalCamera = "215.516998,-32.253654,134.083496,0.00012,-1.199907,171.523682,35.000011,270.662476,false,Manual,2.8",
          GUID = "1E1EF3F0",
          NextDialogue = 12032025,
          SpeakNpcId = 211012,
          Subtitle = "And your payment... Look — I can give you this much! Bet that's enough to keep you fed for a whole year, huh?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF3F0"
        },
        [12032025] = {
          Camera = "-62.110943,89.735397,140.243164,0.000095,-4.800018,-40.882198,35.000011,172.116272,false,Manual,8.0",
          ContentFR = "Hein... ?",
          DialogueId = 12032025,
          FinalCamera = "-51.623528,80.655716,139.078857,0.000095,-4.800018,-40.882198,35.000011,172.116272,false,Manual,8.0",
          GUID = "1E1EF41A",
          NextDialogue = 12032026,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{211001},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{ActorId{211001},AnimationId{"Think_Start"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Huh...?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF41A"
        },
        [12032026] = {
          Camera = "238.118057,-42.286388,133.163086,0.000128,-0.999817,168.524857,35.000008,348.288422,false,Manual,2.8",
          ContentFR = "Quoi, c’est pas assez ? Pas grave, je peux encore ajouter. Tu n’as qu’à—",
          DialogueId = 12032026,
          GUID = "1E1EF444",
          NextDialogue = 12032027,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{211012},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{ActorId{211001},AnimationId{"Think_End"},Duration{1}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "What? Not enough? Fine, I'll throw in more. Just—",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF444"
        },
        [12032027] = {
          Camera = "238.118057,-42.286388,133.163086,0.000128,-0.999817,168.524857,35.000008,348.288422,false,Manual,2.8",
          ContentFR = "Dis donc, jeune fille. Ton professeur ne t’a jamais appris qu’on demande les choses poliment ?",
          DialogueId = 12032027,
          FinalCamera = "137.708801,24.175247,113.700439,0.000129,0.600141,-157.080948,35.000008,593.061584,false,Manual,2.8",
          GUID = "1E1EF46E",
          NextDialogue = 12032028,
          Scripts = "LookAt{LookAtDescription{\"100001:n(211012)\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Hey there, missy. Didn't anyone ever teach you how to ask nicely when you want a favour?",
          ToFinalCameraBlendTime = 1,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF46E"
        },
        [12032028] = {
          Camera = "285.149689,84.910515,130.34668,0.000105,-1.19988,-161.280563,35.000011,438.518188,false,Manual,8.0",
          ContentFR = "Ouaaah ! Mais... t’es qui, toi ?",
          DialogueId = 12032028,
          FinalCamera = "270.333191,79.889786,130.019287,0.000105,-1.19988,-161.280563,35.000011,438.518188,false,Manual,8.0",
          GUID = "1E1EF498",
          NextDialogue = 12032029,
          SpeakNpcId = 211012,
          Subtitle = "Whoa—! Wh—Who are you!?",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "211001:p(40)",
            [2] = "211012:p(-110)"
          },
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF498"
        },
        [12032029] = {
          Camera = "-136.98381,-96.949409,138.581787,0.00012,-0.998656,-161.679504,28.0,218.307404,false,Manual,8.0",
          ContentFR = "Je suis son {性别:ami|amie}. Et accessoirement un {性别:Chasseur de Phoxène|Chasseuse de Phoxène}.",
          DialogueId = 12032029,
          FinalCamera = "-210.195267,-120.908394,151.526123,0.000123,-2.198658,-161.879517,28.0,123.901291,false,Manual,2.8",
          GUID = "1E1EF4C2",
          NextDialogue = 12032101,
          Scripts = [[
PARA{
PlayFacial{ActorId{100001},FacialId{"Happy02"}},
PlayAnimation{ActorId{100001},AnimationId{"Wave02_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "A friend of hers. And a Phoxhunter, for the record.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF4C2"
        },
        [12032030] = {
          ContentFR = "Cassandra jette un œil inquiet à l’arme du protagoniste.",
          DialogueId = 12032030,
          GUID = "1E1EF4EC",
          NextDialogue = 12032101,
          Subtitle = "Cassandra eyes the protagonist's weapon",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1EF4EC"
        },
        [12032101] = {
          Camera = "-234.579056,-133.042816,122.354248,0.000082,-2.599946,47.71814,35.000008,210.94072,false,Manual,2.8",
          ContentFR = "Et alors ? Tu es juste {性别:un Charon|une Charon} ! Je te préviens : moi, je viens de la cité intérieure !",
          DialogueId = 12032101,
          GUID = "1E1F0092",
          NextDialogue = 12032102,
          SpeakNpcId = 211012,
          Subtitle = "So what? You're just a Charon! And I'll have you know I'm from the inner city!",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F0092"
        },
        [12032102] = {
          Camera = "-193.513412,-117.182365,150.495117,0.000083,-0.599943,-161.482178,35.000008,151.270233,false,Manual,2.8",
          ContentFR = "Ah oui ? Tant mieux pour toi.",
          DialogueId = 12032102,
          GUID = "1E1F00BC",
          NextDialogue = 12032103,
          Scripts = [[
PARA{
PlayFacial{ActorId{100001},FacialId{"Smile02"}},
PlayAnimation{ActorId{100001},AnimationId{"Wave02_End"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Good for you.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F00BC"
        },
        [12032103] = {
          Camera = "-503.357483,-430.700165,180.279785,0.000079,-6.800013,47.918465,35.000008,1134.2052,false,Manual,8.0",
          ContentFR = "Pff... Très bien ! Si vous ne voulez pas m’aider, je trouverai bien quelqu’un d’autre !",
          DialogueId = 12032103,
          GUID = "1E1F00E6",
          Scripts = "MoveTo{_delay{2},ActorId{211012},TargetPoint{\"Kashandela01\"},MoveSpeed{250},Visibility{\"Show\"}}",
          SpeakNpcId = 211012,
          Subtitle = "Tch—! Fine! If you won't help, I'll find someone else!",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F00E6"
        },
        [12032104] = {
          ContentFR = "Elle tourne les talons et s’éloigne rapidement.",
          DialogueId = 12032104,
          GUID = "1E1F0110",
          Subtitle = "Cassandra huffs and runs off",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F0110"
        },
        [12032201] = {
          Camera = "-262.630035,518.570374,384.213135,0.00006,-27.400436,-73.273003,28.000008,252.567276,false,Manual,10.0",
          ContentFR = "Fina, ça va ?",
          DialogueId = 12032201,
          FinalCamera = "-233.775208,527.242126,384.213135,0.00006,-27.400436,-73.273003,28.000008,252.567276,false,Manual,10.0",
          GUID = "1E1F10FA",
          NextDialogue = 12032202,
          Scripts = [[
PARA{
MoveTo{ActorId{100001},MoveSpeed{75},TargetPoint{"Nvzhu02"}},
LookAt{LookAtDescription{"100001:n(211001)"}},
LookAt{LookAtDescription{"211001:n(100001)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "You alright, Fina?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F10FA"
        },
        [12032202] = {
          Camera = "-297.106384,-36.227322,125.762207,0.000083,2.59916,-5.271038,35.0,296.228882,false,Manual,1.4",
          ContentFR = "Oui, merci de t’inquiéter ! Mais cette fille...",
          DialogueId = 12032202,
          GUID = "1E1F1124",
          NextDialogue = 12032203,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"},Duration{1}},
LookAt{_delay{3.5},LookAtDescription{"211001:p(Kashandela01)"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "I'm fine. Thanks for looking out for me! But... that girl—",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F1124"
        },
        [12032203] = {
          Camera = "-2.594985,-240.799469,116.917969,0.000117,5.19819,119.91935,35.000008,206.443939,false,Manual,2.8",
          ContentFR = "Elle est déjà loin. Des Solariens arrogants comme elle, j’en ai vu à la pelle. Beaucoup de bruit, mais rien derrière.",
          DialogueId = 12032203,
          GUID = "1E1F114E",
          NextDialogue = 12032204,
          Scripts = "PlayAnimation{ActorId{100001},AnimationId{\"Talk02R_Start\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "She's long gone. I've met plenty of puffed-up Solarians — all bark, no bite.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F114E"
        },
        [12032204] = {
          Camera = "44.288864,-68.407341,133.100342,0.000122,1.398044,-174.282288,35.000008,159.098145,false,Manual,2.8",
          ContentFR = "Cela dit, Fina, fais plus attention. Tu ne peux pas être gentille avec tout le monde, il y a des gens dangereux dehors, et nous, on s’inquiète pour toi.",
          DialogueId = 12032204,
          GUID = "1E1F1178",
          NextDialogue = 12032205,
          Scripts = "PlayAnimation{ActorId{100001},AnimationId{\"Talk02R_End\"},Duration{1}}",
          SpeakNpcId = 100001,
          Subtitle = "Still, you've got to be careful. Don't go being kind to just anyone... There are bad people out there.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F1178"
        },
        [12032205] = {
          Camera = "-95.046806,-140.193008,140.690674,0.000125,-4.602113,49.317894,35.0,159.098129,false,Manual,2.8",
          ContentFR = "Mais... quand j’ai dit que je savais faire un peu de magie, elle a souri. Et je l’ai bien vu, c’était un vrai sourire. Un sourire sincère. Les mauvais sorciers, eux, ne sourient jamais comme ça.",
          DialogueId = 12032205,
          FinalCamera = "-82.042175,-125.063324,139.085938,0.000125,-4.602113,49.317894,35.000008,159.098129,false,Manual,2.8",
          GUID = "1E1F11A2",
          NextDialogue = 12032206,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"211001:n(211001)"}},
PlayAnimation{ActorId{211001},AnimationId{"Think_Start"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"Think01"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "But when I said I could do magic... she smiled. And I could see it — it was a real smile. Honest, and innocent. Bad sorcerers don't smile like that.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F11A2"
        },
        [12032206] = {
          Camera = "-82.042175,-125.063324,139.085938,0.000125,-4.602113,49.317894,35.000008,159.098129,false,Manual,2.8",
          ContentFR = "Et puis... elle est une enfant, non ? Quand j’avais son âge, un grand frère inconnu m’a tendu la main et m’a aidée...",
          DialogueId = 12032206,
          GUID = "1E1F11CC",
          NextDialogue = 12032207,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Think_End"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"None"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "And... she's just a child. When I was her age, a kind-hearted stranger once helped me...",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F11CC"
        },
        [12032207] = {
          Camera = "6.907836,-321.75943,129.159912,0.000122,-0.802151,102.716034,24.0,159.098129,false,Manual,10.0",
          ContentFR = "À ce moment-là, je m’étais promis qu’une fois grande, si je rencontrais un enfant dans le besoin, je ferais la même chose que lui.",
          DialogueId = 12032207,
          GUID = "1E1F11F6",
          NextDialogue = 12032208,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Talk03_Start"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"Sad01"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "I promised myself then: When I grow up, I'll help any child in need — just like that big brother helped me.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F11F6"
        },
        [12032208] = {
          Camera = "-217.036926,-261.586731,133.03418,0.000126,0.197871,53.31599,35.000011,311.586395,false,Manual,2.8",
          ContentFR = "Alors... je veux la retrouver, et savoir pourquoi elle avait besoin d’aide. Si elle est vraiment en difficulté, je ne peux pas détourner les yeux.",
          DialogueId = 12032208,
          GUID = "1E1F1220",
          NextDialogue = 12032209,
          Scripts = [[
PARA{
PlayAnimation{ActorId{211001},AnimationId{"Talk03_End"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"None"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "So... I want to find that girl. Ask if she's alright. And if she's really in trouble... I want to help.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F1220"
        },
        [12032209] = {
          Camera = "173.914368,-27.305672,142.411133,0.000137,-3.602255,-174.485565,35.000008,1783.921265,false,Manual,10.0",
          ContentFR = "Hmm... D’accord. Puisque c’est comme ça, je viens avec toi. Si quelque chose arrive, {性别:ton grand frère|ta grande sœur} sera là pour protéger la petite Fina.",
          DialogueId = 12032209,
          GUID = "1E1F124A",
          NextDialogue = 12032210,
          Scripts = [[
PARA{
PlayAnimation{_delay{1.2},ActorId{100001},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{ActorId{100001},AnimationId{"DisagreeHead"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Alright. Then let's go together. If anything happens, this {性别:big brother|big sister} will be right there to back you up.",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F124A"
        },
        [12032210] = {
          Camera = "-184.001755,-162.542816,152.971924,0.000154,-4.801753,40.315285,35.000023,249.784531,false,Manual,2.8",
          ContentFR = "Héhé, merci, {性别:Monsieur|Mademoiselle} Licorne ! Avec toi à mes côtés, je n’ai peur de rien !",
          DialogueId = 12032210,
          GUID = "1E1F1274",
          NextDialogue = 12032211,
          Scripts = [[
PARA{

PlayAnimation{ActorId{211001},AnimationId{"Feina_Story_Wish_Start"},Duration{1}},
PlayAnimation{ActorId{211001},AnimationId{"AgreeHead"},Duration{1}},
PlayFacial{ActorId{211001},FacialId{"Happy02"}},
PlayAnimation{ActorId{100001},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Hehe... Thank you, {性别:Mr|Miss} Unicorn! With you by my side, I'm not afraid of anything!",
          VoiceName = "voice/$Locale$/story/1201/120113/1E1F1274"
        },
        [12032211] = {
          Camera = "-184.001755,-162.542816,152.971924,0.000154,-4.801753,40.315285,35.000023,249.784531,false,Manual,2.8",
          ContentFR = "Alors allons-y. Je l’ai vue partir vers la place.",
          DialogueId = 12032211,
          FinalCamera = "40.894524,-343.161194,107.66748,0.000154,2.797645,109.714264,20.000008,139.632568,false,Manual,10.0",
          GUID = "1E1F129E",
          Scripts = [[
