          GUID = "1E1F7394",
          NextDialogue = 12032803,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0},ActorId{211012},AnimationId{"Confident_Start"}},
PlayAnimation{_delay{2},ActorId{211012},AnimationId{"Confident_End"}}
}]],
          SpeakNpcId = 211012,
          Subtitle = "Okay, let's run through the ruse. You two pretend to be some travellers who saw a Butterfly Fairy. Bring my friend into a quiet alley — and say it's going to appear there.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1F7394"
        },
        [12032803] = {
