          DialogueId = 12032803,
          GUID = "1E1F73BE",
          NextDialogue = 12032804,
          SpeakNpcId = 211012,
          Subtitle = "Then once we're in position, Fina — you sneak behind and summon the Butterfly Fairy!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1F73BE"
        },
        [12032804] = {
          ContentFR = "\"Témoignage\" ? Tu veux plutôt dire \"plan\", non ?",
          DialogueId = 12032804,
          GUID = "1E1F73E8",
          NextDialogue = 12032805,
          SpeakNpcId = 100001,
          Subtitle = "\"Ruse\"...? Don't you mean \"plan\"?",
