        },
        [12033501] = {
          ContentFR = "Chercher au hasard, ça ne servira à rien... Cassandra, as-tu une idée d’où Savio pourrait aller ? Ou pourquoi il aurait quitté la cité ?",
          DialogueId = 12033501,
          GUID = "1E1FE642",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 12033502,
          SpeakNpcId = 100001,
          Subtitle = "Searching blindly won't help... Cassandra, can you think of anywhere Savio might go? Why would he even leave the city?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE642"
        },
        [12033502] = {
          ContentFR = "Hmm... Peut-être qu’il est parti chercher des papillons. L’autre jour, en classe, le maître a dit qu’il y en avait près du Lac du Deuil. Il n’arrêtait pas de poser des questions à ce sujet...",
          DialogueId = 12033502,
          GUID = "1E1FE66C",
          NextDialogue = 12033503,
          SpeakNpcId = 211012,
          Subtitle = "Umm... maybe he went to look for butterflies. A few days ago in class, the teacher said they live near Lamenting Lake. He wouldn't stop asking about it...",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE66C"
        },
        [12033503] = {
          ContentFR = "Il est vraiment obsédé par les papillons... C’est à cause d’un conte ?",
          DialogueId = 12033503,
          GUID = "1E1FE696",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 12033504,
          SpeakNpcId = 100001,
          Subtitle = "Why's he so obsessed with butterflies? Is there a fairy tale behind it or something?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE696"
        },
        [12033504] = {
          ContentFR = "Non... C’est à cause d’un souvenir. Il me l’a raconté plein de fois. Quand il était petit, un jour ses parents ont disparu. Il les cherchait partout, en pleurant.",
          DialogueId = 12033504,
          GUID = "1E1FE6C0",
          NextDialogue = 12033505,
          SpeakNpcId = 211012,
          Subtitle = "It's because of something that happened when he was little. He told me the story a bunch of times... One day, his mum and dad disappeared. He was scared and cried a lot.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE6C0"
        },
        [12033505] = {
          ContentFR = "Et c’est alors que des Fées-Papillons sont apparues. Elles ont joué avec lui, lui ont tenu compagnie... jusqu’à ce que ses parents rentrent enfin.",
          DialogueId = 12033505,
          GUID = "1E1FE6EA",
          NextDialogue = 12033506,
          SpeakNpcId = 211012,
          Subtitle = "Then the Butterfly Fairies came. They played with him, kept him company until his parents came home.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE6EA"
        },
        [12033506] = {
          ContentFR = "Alors... je crois qu’il espère qu’en les retrouvant, ses parents reviendront aussi...",
          DialogueId = 12033506,
          GUID = "1E1FE714",
          NextDialogue = 12033507,
          SpeakNpcId = 211012,
          Subtitle = "I think... maybe he believes if he finds them again, they'll bring his parents back...",
          VoiceName = "voice/$Locale$/story/1201/120114/1E1FE714"
        },
        [12033507] = {
          ContentFR = "...",
          DialogueId = 12033507,
