        },
        [12034215] = {
          Camera = "-791.641052,842.650452,140.891602,0.000069,-7.345704,-66.589088,30.0,319.085938,false,DoNotOverride,8.0",
          ContentFR = "Ne pleure pas ! Tu as plein d’amis maintenant, tu n’as plus rien à craindre. Et si des garnements ou des bandits s’avisent encore de t’embêter, Fina invoquera un gros monstre qui leur fera peur, pas vrai ?",
          DialogueId = 12034215,
          FinalCamera = "-791.641052,842.650452,110.082031,0.000073,-4.745547,-67.189018,30.0,319.085938,false,DoNotOverride,8.0",
          GUID = "1E205B66",
          NextDialogue = 12034216,
          SpeakNpcId = 211012,
          Subtitle = "Don't cry! You've got loads of friends now — no one's going to hurt you. And if any bullies or bandits show up again? Fina will just summon a giant monster to chase them off!",
          TalkActionId = {
            [1] = "211015:Sigh_End",
            [2] = [[

