        },
        [12034716] = {
          Camera = "404.343994,-127.544922,169.554688,0.000054,-7.335021,141.091019,28.0,100000.0,false,Manual,22.0",
          ContentFR = "Fina ? Je suis de ret—... Hein ?! Mais... c’est quoi tout ce troupeau de gamins ?!",
          DialogueId = 12034716,
          GUID = "1E20AD98",
          NextDialogue = 12034717,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{1},TargetPosition{"266.347015,82.261719,168.210938,0.000058,-4.935057,-70.909439,28.0,100000.0,false,Manual,22.0"},duration{0}},
PlayAnimation{ActorId{211002},AnimationId{"Shock_Start"},Duration{0}},
PlayAnimation{ActorId{211002},AnimationId{"Shock_Start"},Duration{1}},
CameraMoveTo{_delay{1},TargetPosition{"-402.170105,604.082031,299.925781,0.000145,-18.428335,-34.480679,24.0,179.263412,false,Manual,22.0"},duration{0}}
}]],
          SpeakNpcId = 211002,
          Subtitle = "Fina? I'm home— whoa...!? Why are there so many kids in here?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20AD98"
        },
        [12034717] = {
          ContentFR = "Tu arrives pile au bon moment ! Viens te joindre au goûter de Fina, Grand Magi-Chien... euh, pardon, Grand Magicien !",
          DialogueId = 12034717,
          GUID = "1E20ADC2",
          NextDialogue = 12034718,
          Scripts = [[
PARA{
CameraMoveTo{_delay{2},TargetPosition{"173.317947,116.496094,135.746094,0.000113,-0.134766,116.682274,28.0,100000.0,false,Manual,22.0"},duration{0}},
LookAt{LookAtDescription{"211001:n(211002)"}},
LookAt{LookAtDescription{"100001:n(211002)"}},
LookAt{LookAtDescription{"211012:n(211002)"}},
LookAt{LookAtDescription{"211015:n(211002)"}},
PlayFacial{_delay{5},ActorId{100001},FacialId{"Smile02"}},
PlayAnimation{ActorId{100001},AnimationId{"Confident_Start"},Duration{1}},
PlayAnimation{ActorId{211002},AnimationId{"Shock_End"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Perfect timing! Come and join the tea party, Great MagicMutt— I mean, Great Magician.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20ADC2"
        },
        [12034718] = {
          ContentFR = "... Tu l’as fait exprès !",
          DialogueId = 12034718,
          GUID = "1E20ADEC",
          NextDialogue = 12034719,
          Scripts = "PlayAnimation{ActorId{211002},AnimationId{\"Sigh_Start\"},Duration{1}}",
          SpeakNpcId = 211002,
          Subtitle = "You totally did that on purpose!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20ADEC"
        },
        [12034719] = {
          ContentFR = "L’Étranger, tu es rentré ! Laisse-moi te présenter mes nouveaux amis !",
          DialogueId = 12034719,
          GUID = "1E20AE16",
          Scripts = [[
PARA{
CameraMoveTo{_delay{3},TargetPosition{"190.968307,160.283203,134.253906,0.000142,-4.628075,112.713974,35.0,117.253952,false,Manual,1.4"},duration{0}},
PlayAnimation{ActorId{211001},AnimationId{"Feina_Story_Wish_Start"},Duration{1}},
PlayFacial{_delay{0},ActorId{211001},FacialId{"Happy01"}},
PlayFacial{_delay{3},ActorId{211001},FacialId{"Happy02"}},
PlayAnimation{_delay{3},ActorId{211001},AnimationId{"TilteHead_Start"},Duration{1}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Outsider, you're back! These are my new friends — come meet them!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20AE16"
        },
        [12034720] = {
          Content = "下面这段茶会剧情希望能用动画的形式制作，但并不需要额外动作资源，打一个慢慢移动的全景镜头，五个角色站在一起做说话动作即可（效果不好的话也可以打空镜头放个暖色灯光）\n角色台词不显示在对话框里，作为背景音播放，每两句一组",
          DialogueId = 12034720,
          GUID = "1E20AE40",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20AE40"
        },
        [12034801] = {
          ContentFR = "Grand Magi-Chien ? C’est quoi ça ?",
          DialogueId = 12034801,
          GUID = "1E20BB8A",
          NextDialogue = 12034802,
          SpeakNpcId = 211012,
          Subtitle = "What's a MagicMutt?",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20BB8A"
        },
        [12034802] = {
          ContentFR = "Non non, c’est Grand Magicien !",
          DialogueId = 12034802,
          GUID = "1E20BBB4",
          NextDialogue = 12034803,
          SpeakNpcId = 211001,
          Subtitle = "No no — he's the Great Magician!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20BBB4"
        },
        [12034803] = {
          ContentFR = "Kof, kof...",
          DialogueId = 12034803,
          GUID = "1E20BBDE",
          NextDialogue = 12034804,
          SpeakNpcId = 211015,
          Subtitle = "*coughs*",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20BBDE"
        },
        [12034804] = {
          ContentFR = "Ça va ? Bois un peu d’eau !",
          DialogueId = 12034804,
          GUID = "1E20BC08",
          NextDialogue = 12034805,
          SpeakNpcId = 100001,
          Subtitle = "You okay? Here, drink some water.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20BC08"
        },
        [12034805] = {
          ContentFR = "Piou-piou ! Je suis Monsieur l’Oiseau blanc !",
          DialogueId = 12034805,
          GUID = "1E20BC32",
          NextDialogue = 12034806,
          SpeakNpcId = 211001,
          Subtitle = "Chirp-chirp, I'm Mr White Bird!",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20BC32"
        },
        [12034806] = {
          ContentFR = "Ouah... il est énorme !",
          DialogueId = 12034806,
          GUID = "1E20BC5C",
          SpeakNpcId = 211002,
          Subtitle = "Whoa, he's a big guy for sure...",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20BC5C"
        },
        [12034807] = {
          Content = "转场，茶会结束后，菲娜一个人坐在家里",
          DialogueId = 12034807,
          GUID = "1E20BC86",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20BC86"
        },
        [12034901] = {
          Camera = "-16.293289,323.111328,136.453125,0.000086,-7.199647,126.990501,35.0,69.843971,false,DoNotOverride,12.0",
          ContentFR = "« Le petit Rossignol quitta son nid et s’envola vers l’inconnu... En chemin, il rencontra l’ingénieuse Détective Taciturne, les joyeuses Patates magiques grillées, et plein, plein de nouveaux amis... »",
          DialogueId = 12034901,
          FinalCamera = "-29.425766,297.828125,134.542969,0.000094,-5.599942,111.788467,35.0,90.44413,false,DoNotOverride,12.0",
          GUID = "1E20CBF2",
          NextDialogue = 12034902,
          Scripts = [[
PARA{
CameraMoveTo{_delay{8.01},TargetPosition{"-42.475677,435.521484,112.582031,0.000114,6.399675,-88.810791,35.0,244.499649,false,DoNotOverride,12.0"},duration{0}},
CameraMoveTo{_delay{8.01},TargetPosition{"-44.494888,523.302734,101.164062,0.000112,9.799627,-88.410698,35.0,244.499649,false,DoNotOverride,12.0"},duration{12}},
PARA{
PlayFacial{_delay{2.5},ActorId{211001},FacialId{"Smile01"}}
}
}]],
          SpeakNpcId = 211001,
          Subtitle = "\"The little nightingale left her nest and flew into the unknown... On her journey, she met the clever Reticent Detective, cheerful Magic Roasted Potatoes, and many, many new friends...\"",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120114/1E20CBF2"
        },
        [12034902] = {
          Camera = "65.885368,364.457031,142.957031,0.000107,-13.200897,166.389648,35.0,111.809486,false,DoNotOverride,12.0",
          ContentFR = "« Le Rossignol n’avait plus peur des mauvais sorciers, ni des bêtes sauvages qui le poursuivaient. »",
          DialogueId = 12034902,
          GUID = "1E20CC1C",
          NextDialogue = 12034903,
          Scripts = "PlayAnimation{ActorId{211001},AnimationId{\"Feina_Story_Wish_Start\"},Duration{1}}",
          SpeakNpcId = 211001,
          Subtitle = "\"She was no longer afraid of bad sorcerers, or the beasts that once chased her...\"",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20CC1C"
        },
        [12034903] = {
          Camera = "-31.965088,301.212891,134.277344,0.000101,-7.000998,109.790298,35.0,90.981918,false,DoNotOverride,12.0",
          ContentFR = "« Car maintenant, il savait que, même si le monde dehors pouvait être sombre et effrayant... tant qu’il tenait la main de ses amis, il trouverait toujours le chemin vers un rêve aux mille couleurs. »",
          DialogueId = 12034903,
          FinalCamera = "-35.076675,309.947266,133.269531,0.000102,-5.800961,109.79023,35.0,70.654915,false,DoNotOverride,12.0",
          GUID = "1E20CC46",
          Scripts = [[
PARA{
PlayFacial{_delay{2.5},ActorId{211001},FacialId{"Satisfy01"}},
PlayFacial{_delay{5.5},ActorId{211001},FacialId{"Smile02"}},
PlayFacial{_delay{8.5},ActorId{211001},FacialId{"Smile01"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "\"Because now, she knew — no matter how dark or scary the world might seem... as long as she held hands with her friends, she could always find her way to a rainbow-coloured dream.\"",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1201/120114/1E20CC46"
        },
        [12034904] = {
          ContentFR = "(Quatrième mini-jeu débloqué. Terminez le jeu pour continuer.)",
          DialogueId = 12034904,
          GUID = "1E20CC70",
          NextDialogue = 12034905,
          Subtitle = "Fourth mini-game unlocks. Completes the game to proceed.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20CC70"
        },
        [12034905] = {
          ContentFR = "(La complétion mène à la cinématique de fin.)",
          DialogueId = 12034905,
          GUID = "1E20CC9A",
          NextDialogue = 12034906,
          Subtitle = "Completion leads to the ending cutscene",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20CC9A"
        },
        [12034906] = {
          ContentFR = "Fina, un grimoire entre les mains, referme doucement le livre avec un sourire. Autour d’elle, ses quatre compagnons invoqués l’entourent encore un instant... puis disparaissent dans la nuit.",
          DialogueId = 12034906,
          GUID = "1E20CCC4",
          Subtitle = "Fina, smiling gently, closes her spellbook. Around her, her four summoned companions linger a moment... then quietly fade into the night.",
          VoiceName = "voice/$Locale$/story/1201/120114/1E20CCC4"
        },
        [12034910] = {
