          VoiceName = "voice/$Locale$/story/2001/200005/3211B8CA"
        },
        [20000529] = {
          Camera = "-69.666748,-17.761719,56.248047,0.000116,1.798375,-8.383431,50.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu peux être {性别:rassuré|rassurée}. « Une Luno ne blesse jamais volontairement autrui » — tout Atlasia connaît ce proverbe.",
          DialogueId = 20000529,
          Duration = 2,
          FacialId = {
