          SpeakNpcId = 200027,
          Subtitle = "...Thank you for saying that to make me feel better, but...",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211E834"
        },
        [20000819] = {
          Camera = "10.355469,-77.708008,125.386719,0.000002,-1.399991,143.804291,35.0,144.500336,false,Manual,4.079638",
          ContentFR = "En touchant les pétales, j’ai senti qu’ils se plissaient déjà. La fleur ne va pas très bien...",
          DialogueId = 20000819,
          Duration = 3,
          FacialId = {
            [1] = "200027:None"
          },
          GUID = "3211E85E",
          NextDialogue = 20000820,
          Scripts = "SEQ{PlayAnimation{ActorId{200027},AnimationId{\"Explain02_Start\"},Duration{3}},PlayAnimation{ActorId{200027},AnimationId{\"Explain02_End\"},Duration{1}}}",
          SpeakNpcId = 200027,
          Subtitle = "I touched it and the petals felt wrinkled. I don't think the flowers are doing well.",
          VoiceName = "voice/$Locale$/story/2001/200008/3211E85E"
        },
        [20000820] = {
          Camera = "245.671875,83.657959,99.515625,0.000001,-2.499965,-159.999985,30.0,295.581177,false,DoNotOverride,1.2",
          ContentFR = "Peux-tu l’observer encore un peu, s’il te plaît ? C’est important pour bien en prendre soin.",
          DialogueId = 20000820,
          Duration = 3,
          FinalCamera = "223.863281,75.722168,99.199219,0.000001,-2.499965,-159.999985,30.0,295.581177,false,DoNotOverride,1.2",
          GUID = "3211E888",
          NextDialogue = 20000848,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"100001:p(50)\"}}}",
          SpeakNpcId = 200027,
          Subtitle = "Could you take a closer look? The well-being of flowers hinges on careful observation, but I can't do that now...",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200008/3211E888"
        },
        [20000821] = {
          Camera = "27.541016,-42.623047,120.214844,0.000004,-1.200071,-161.593994,25.0,104.410446,false,Manual,1.989418",
          ContentFR = "Elle est d’un jaune vif... une couleur pleine de vie.",
          DialogueId = 20000821,
          Duration = 3,
          ExStoryInfo = "Player",
          FinalCamera = "26.746094,-40.242188,120.214844,0.000004,-1.200071,-161.593994,25.0,160.037735,false,Manual,4.199908",
          GUID = "3211E8B2",
          LookAt = {
            [1] = "100001:p(TargetPonit_Flower)"
          },
          NextDialogue = 20000822,
          SpeakNpcId = 100001,
          Subtitle = "The flowers are bright yellow... A very vibrant hue.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200008/3211E8B2"
        },
        [20000822] = {
          Camera = "94.091797,-182.063965,121.216797,0.000011,-1.600306,145.798538,35.0,269.380554,false,Manual,1.695109",
          ContentFR = "Oui... J’adore les fleurs jaunes. Elles me rappellent le soleil, elles réchauffent le cœur...",
          DialogueId = 20000822,
          Duration = 3,
          FacialId = {
            [1] = "200027:Satisfy01"
          },
          GUID = "3211E8DC",
          LookAt = {
            [1] = "100001:n(200027)"
          },
          NextDialogue = 20000848,
          SpeakNpcId = 200027,
          Subtitle = "Mm, I love yellow flowers. They remind me of the sun and warm my heart...",
          TurnTo = {
            [1] = "100001:n(200027)"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211E8DC"
        },
        [20000823] = {
          Camera = "27.541016,-42.623047,120.214844,0.000004,-1.200071,-161.593994,25.0,104.410446,false,Manual,1.989418",
          ContentFR = "Le bord des pétales n’est pas lisse... Il y a plein de petites entailles irrégulières.",
          DialogueId = 20000823,
          Duration = 3,
          ExStoryInfo = "Player",
          FinalCamera = "26.746094,-40.242188,120.214844,0.000004,-1.200071,-161.593994,25.0,160.037735,false,Manual,4.199908",
          GUID = "3211E906",
          LookAt = {
            [1] = "100001:p(TargetPonit_Flower)"
          },
          NextDialogue = 20000824,
          SpeakNpcId = 100001,
          Subtitle = "The petals don't have smooth edges. Instead, there are plenty of irregular gaps running along the margins.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200008/3211E906"
        },
        [20000824] = {
          Camera = "94.091797,-182.063965,121.216797,0.000011,-1.600306,145.798538,35.0,269.380554,false,Manual,1.695109",
          ContentFR = "Exactement... Tu devrais les toucher doucement. J’aime effleurer leurs contours : chaque pétale raconte une histoire différente au bout de mes doigts...",
          DialogueId = 20000824,
          Duration = 3,
          FacialId = {
            [1] = "200027:Satisfy01"
          },
          GUID = "3211E930",
          LookAt = {
            [1] = "100001:n(200027)"
          },
          NextDialogue = 20000825,
          SpeakNpcId = 200027,
          Subtitle = "Right... Try touching the petals softly. I love running my fingers along the edges of petals. Every petal feels different as if they have their own story to tell...",
          TurnTo = {
            [1] = "100001:n(200027)"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211E930"
        },
        [20000825] = {
          Camera = "-154.173828,40.040039,119.296875,0.0,0.0,-106.185913,17.5,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais ceux-ci ont perdu leur éclat. Leurs bords sont assombris, recroquevillés... comme brûlés.",
          DialogueId = 20000825,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200027:None"
          },
          FinalCamera = "-167.962891,43.33374,117.626953,0.0,0.0,-100.000061,17.5,100000.0,false,DoNotOverride,2.8",
          GUID = "3211E95A",
          NextDialogue = 20000826,
          SpeakNpcId = 100001,
          Subtitle = "But these petals seem to have lost their shine. The edges are dark and curled, as though they've been burnt...",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/2001/200008/3211E95A"
        },
        [20000826] = {
          Camera = "10.355469,-77.708008,125.386719,0.000002,-1.399991,143.804291,35.0,144.500336,false,Manual,4.079638",
          ContentFR = "Hmm... sans doute qu’elles manquent d’eau.",
          DialogueId = 20000826,
          Duration = 3,
          FacialId = {
            [1] = "200027:Sad01"
          },
          GUID = "3211E984",
          NextDialogue = 20000848,
          SpeakNpcId = 200027,
          Subtitle = "Hmm... I believe the flowers are thirsting for some water.",
          VoiceName = "voice/$Locale$/story/2001/200008/3211E984"
        },
        [20000827] = {
          Camera = "27.541016,-42.623047,120.214844,0.000004,-1.200071,-161.593994,25.0,104.410446,false,Manual,1.989418",
          ContentFR = "On distingue de fines stries, qui partent du cœur vers l’extérieur... un peu comme les nervures d’une feuille. Mais elles paraissent fragiles...",
          DialogueId = 20000827,
          Duration = 3,
          ExStoryInfo = "Player",
          FinalCamera = "26.746094,-40.242188,120.214844,0.000004,-1.200071,-161.593994,25.0,160.037735,false,Manual,4.199908",
          GUID = "3211E9AE",
          LookAt = {
            [1] = "100001:p(TargetPonit_Flower)"
          },
          NextDialogue = 20000828,
          SpeakNpcId = 100001,
          Subtitle = "The petals have soft stripes that radiate from the center outward, somewhat resembling the veins of the leaves. However, they seem not to be very plump...",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200008/3211E9AE"
        },
        [20000828] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ces lignes transportent les nutriments, comme les nervures d’une feuille.",
          DialogueId = 20000828,
          Duration = 3,
          FacialId = {
            [1] = "200027:Smile01"
          },
          GUID = "3211E9D8",
          LookAt = {
            [1] = "100001:n(200027)"
          },
          NextDialogue = 20000829,
          SpeakNpcId = 200027,
          Subtitle = "The stripes deliver nutrients and function just like the veins of the leaves.",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          TurnTo = {
            [1] = "100001:n(200027)"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211E9D8"
        },
        [20000829] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "On remarque toujours la fleur, mais en réalité, fleurs et feuilles respirent et grandissent de la même façon.",
          DialogueId = 20000829,
          Duration = 3,
          GUID = "3211EA02",
          NextDialogue = 20000830,
          SpeakNpcId = 200027,
          Subtitle = "Although the flowers usually steal our attention, they're not that different when compared to leaves. Both parts of the plant are doing their best to respire and grow.",
          TalkActionId = {
            [1] = "200027:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EA02"
        },
        [20000830] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Si elles sont trop fines... c’est peut-être un manque de nutriments.",
          DialogueId = 20000830,
          Duration = 3,
          FacialId = {
            [1] = "200027:Sad01"
          },
          GUID = "3211EA2C",
          NextDialogue = 20000848,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{200027},AnimationId{\"Think_Start\"},Duration{2}}",
          SpeakNpcId = 200027,
          Subtitle = "Let me see... If they look shrivelled, they may be low on nutrients.",
          TalkActionId = {
            [1] = "200027:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EA2C"
        },
        [20000831] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci, {nickname}. Je crois comprendre ce qu’il leur manque.",
          DialogueId = 20000831,
          Duration = 3,
          FacialId = {
            [1] = "200027:None"
          },
          GUID = "3211EA56",
          NextDialogue = 20000832,
          SpeakNpcId = 200027,
          Subtitle = "I think I understand the issue now, thank you.",
          TalkActionId = {
            [1] = "200027:Think_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EA56"
        },
        [20000832] = {
          Camera = "-99.587891,5.36792,111.048828,0.000001,1.399991,-66.587082,22.803864,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Cette plante est difficile à entretenir ?",
          DialogueId = 20000832,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211EA80",
          NextDialogue = 20000833,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Hide\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Is this kind of flower hard to care for?",
          VoiceName = "voice/$Locale$/story/2001/200008/3211EA80"
        },
        [20000833] = {
          Camera = "-147.613281,70.731934,123.0,0.000019,0.0,-105.39399,35.0,200.0,false,DoNotOverride,2.8",
          ContentFR = "Non... C’est une espèce robuste. Même à Givrelac, où l’hiver est éternel, elle peut survivre.",
          DialogueId = 20000833,
          Duration = 3,
          FinalCamera = "-147.613281,70.731934,134.0,0.000019,0.0,-105.39399,35.0,200.0,false,DoNotOverride,2.8",
          GUID = "3211EAAA",
          NextDialogue = 20000834,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200027,
          Subtitle = "No, it's quite resilient actually — it can even thrive in places with long winters, like Icelake.",
          TalkActionId = {
            [1] = "200027:DisagreeHead"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200008/3211EAAA"
        },
        [20000834] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.403259,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Avec la bonne taille, un peu d’engrais, de l’humidité et de la chaleur, elle devrait fleurir longtemps... Mais je n’ai pas su m’en occuper. Je suis encore loin d’égaler mes parents, de vrais fleuristes.",
          DialogueId = 20000834,
          Duration = 3,
          GUID = "3211EAD4",
          NextOptions = {
            [1] = 200008341,
            [2] = 200008342
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200027},AnimationId{"Explain02_Start"},Duration{3}},
PlayAnimation{ActorId{200027},AnimationId{"Explain02_End"},Duration{1}},
PlayAnimation{ActorId{200027},AnimationId{"DisagreeHead"},Duration{1}}
}]],
          SpeakNpcId = 200027,
          Subtitle = "As long as it is well trimmed, fertilised, and given the proper humidity and temperature, it can bloom beautifully for weeks on end... But I didn't do it well. I'm far from being as good a florist as my parents.",
          VoiceName = "voice/$Locale$/story/2001/200008/3211EAD4"
        },
        [20000835] = {
          Camera = "6.158203,-97.895752,117.539062,0.0,0.200002,136.802826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est vrai... Mais, attends... {nickname}, je crois que j’ai trouvé !",
          DialogueId = 20000835,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211EAFE",
          NextDialogue = 20000837,
          SpeakNpcId = 200027,
          Subtitle = "You might be right, but... oh, wait, ! Something just occurred to me.",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EAFE"
        },
        [20000836] = {
          Camera = "6.158203,-97.895752,117.539062,0.0,0.200002,136.802826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non, je fais comme mes parents, et nous sommes toujours à Givrelac... Mais, oh ! Oui, je me souviens !",
          DialogueId = 20000836,
          Duration = 3,
          GUID = "3211EB28",
          NextDialogue = 20000837,
          SpeakNpcId = 200027,
          Subtitle = "I've grown it the same way as my parents did, and it's always been in Icelake, so the environment should be consistent... Ah, I get it!",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EB28"
        },
        [20000837] = {
          Camera = "-364.001953,-139.020996,113.833984,0.0,-0.399996,20.204187,35.0,150.0,false,Manual,2.8",
          ContentFR = "Peut-être que le problème vient du <H>sol</>...",
          DialogueId = 20000837,
          Duration = 3,
          GUID = "3211EB52",
          LookAt = {
            [1] = "200027:p(TargetPonit_Flower)",
            [2] = "100001:p(TargetPonit_Flower)"
          },
          NextDialogue = 20000838,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"200027:p(-70)\"}},TurnTo{TurnToDescription{\"100001:p(50)\"}}}",
          SpeakNpcId = 200027,
          Subtitle = "Maybe it's the soil...",
          VoiceName = "voice/$Locale$/story/2001/200008/3211EB52"
        },
        [20000838] = {
          Camera = "-99.587891,5.36792,111.048828,0.000001,1.399991,-66.58712,22.803864,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Le sol ?",
          DialogueId = 20000838,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211EB7C",
          LookAt = {
            [1] = "100001:n(200027)"
          },
          NextDialogue = 20000839,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Hide\"}}",
          SpeakNpcId = 100001,
          Subtitle = "The soil?",
          VoiceName = "voice/$Locale$/story/2001/200008/3211EB7C"
        },
        [20000839] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui. Papa utilisait une terre spéciale, qu’il rapportait d’une grotte à l’extérieur de Givrelac.",
          DialogueId = 20000839,
          Duration = 3,
          GUID = "3211EBA6",
          LookAt = {
            [1] = "200027:n(100001)"
          },
          NextDialogue = 20000840,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200027,
          Subtitle = "Yes. Dad used to gather special soil from a cave beyond Icelake for our plants.",
          VoiceName = "voice/$Locale$/story/2001/200008/3211EBA6"
        },
        [20000840] = {
          Camera = "6.158203,-97.895752,117.539062,0.0,0.200002,136.802826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Il disait que cette terre était plus fertile que les autres... Peut-être que je devrais aller en chercher...",
          DialogueId = 20000840,
          Duration = 3,
          FacialId = {
            [1] = "200027:Sad01"
          },
          GUID = "3211EBD0",
          NextDialogue = 20000841,
          SpeakNpcId = 200027,
          Subtitle = "He mentioned that the special soil is more fertile than the others. Perhaps I can go there and—",
          VoiceName = "voice/$Locale$/story/2001/200008/3211EBD0"
        },
        [20000841] = {
          Camera = "6.158203,-97.895752,117.539062,0.0,0.200002,136.802826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Non. Pas pour l’instant. Je devrai attendre que ma vue s’améliore.",
          DialogueId = 20000841,
          Duration = 3,
          GUID = "3211EBFA",
          NextOptions = {
            [1] = 200008411,
            [2] = 200008412
          },
          SpeakNpcId = 200027,
          Subtitle = "...Um, forget it. I'll worry about this later...",
          TalkActionId = {
            [1] = "200027:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EBFA"
        },
        [20000842] = {
          Camera = "-99.587891,5.36792,111.048828,0.000001,1.399991,-66.58712,22.803864,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est simple. Je peux aller t’en chercher.",
          DialogueId = 20000842,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200027:None"
          },
          GUID = "3211EC24",
          NextDialogue = 20000843,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Hide\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Don't worry, I can collect some for you.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EC24"
        },
        [20000843] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu n’as pas besoin d’en faire autant... Me tenir compagnie me suffit déjà.",
          DialogueId = 20000843,
          Duration = 3,
          FacialId = {
            [1] = "200027:Smile01"
          },
          GUID = "3211EC4E",
          NextDialogue = 20000844,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200027,
          Subtitle = "You don't have to do that... Just coming here and talking with me is already—",
          TalkActionId = {
            [1] = "200027:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EC4E"
        },
        [20000844] = {
          Camera = "-99.587891,5.36792,111.048828,0.000001,1.399991,-66.58712,22.803864,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ne t’inquiète pas. Je dois de toute façon sortir de la cité pour des missions, ce n’est pas compliqué d’aller chercher un peu de terre. Alors... où se trouve cette grotte ?",
          DialogueId = 20000844,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "3211EC78",
          NextDialogue = 20000845,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Hide\"}}",
          SpeakNpcId = 100001,
          Subtitle = "It's okay, I'll have to leave town for the commissions anyway. Gathering soil isn't that hard. So where's that cave you mentioned?",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211EC78"
        },
        [20000845] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je... Merci...",
          DialogueId = 20000845,
          Duration = 3,
          FacialId = {
            [1] = "200027:Happy01"
          },
          GUID = "3211ECA2",
          NextDialogue = 20000846,
          Scripts = "SetLocation{ActorId{200027},TargetPoint{\"P_200103Saiqi2\"},Visibility{\"Show\"}}",
          SpeakNpcId = 200027,
          Subtitle = "...Thank y... um, no.",
          TalkActionId = {
            [1] = "100001:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211ECA2"
        },
        [20000846] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non. Je ne devrais plus te remercier comme si tu étais un étranger. Entre nous, ce n’est plus nécessaire.",
          DialogueId = 20000846,
          Duration = 3,
          GUID = "3211ECCC",
          NextDialogue = 20000847,
          SpeakNpcId = 200027,
          Subtitle = "I was about to say thank you, but I think we're beyond such formalities with each other.",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211ECCC"
        },
        [20000847] = {
          Camera = "87.441406,-169.119629,114.539062,0.0,0.0,145.40329,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Laisse-moi t’indiquer où se trouve la grotte...",
          DialogueId = 20000847,
          Duration = 3,
          GUID = "3211ECF6",
          SpeakNpcId = 200027,
          Subtitle = "Let me give you the location of the cave.",
          TalkActionId = {
            [1] = "200027:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200008/3211ECF6"
        },
        [20000848] = {
          DialogueId = 20000848,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 20000831,
          GUID = "3211E889",
          NextOptions = {
            [1] = 200008201,
            [2] = 200008202,
            [3] = 200008203
          }
        },
        [20000901] = {
          Camera = "-140.695312,18.599854,123.658203,0.0,0.200002,-41.587856,30.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Psyche, voici la terre de la grotte. C’est bien ce que tu voulais ?",
          DialogueId = 20000901,
          Duration = 3,
          ExStoryInfo = "Player",
          FinalCamera = "-133.978516,27.376221,123.658203,0.0,0.200002,-36.587448,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "3211F5D2",
          NextDialogue = 20000902,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"StoryCustom\"},SoundType{\"SOUND_BGM\"},SoundUnitKey{\"sidestory_huaqiweizhi\"},EventPath{\"event:/bgm/cbt02/0050_story_saiqi_grow_flower\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Psyche, here's the soil from that cave. Does it look right?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          ToFinalCameraBlendTime = 3,
          TurnTo = {
            [1] = "200027:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F5D2"
        },
        [20000902] = {
          Camera = "208.482422,-19.678467,129.025391,0.0,0.0,-157.197144,35.0,208.263901,false,Manual,6.0",
          ContentFR = "Hmm... ce toucher... c’est exactement la même terre que papa utilisait autrefois.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000902,
          Duration = 3,
          GUID = "3211F5FC",
          NextDialogue = 20000903,
          SpeakNpcId = 200027,
          Subtitle = "Hmm... Its touch is exactly like that of the soil Dad used to grow flowers with.",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F5FC"
        },
        [20000903] = {
          Camera = "134.650391,-45.876221,128.087891,0.0,0.0,-169.994003,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu en as pris beaucoup... Avec ça, toutes les fleurs ici pourront s’épanouir pleinement.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000903,
          Duration = 3,
          GUID = "3211F626",
          NextOptions = {
            [1] = 20000904
          },
          SpeakNpcId = 200027,
          Subtitle = "And there's so much of it... This should be enough to help every plant thrive here.",
          TalkActionId = {
            [1] = "200027:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F626"
        },
        [20000904] = {
          ContentFR = "<I>Tant que tu es heureuse, ça valait bien le détour.</>",
          DialogueId = 20000904,
          GUID = "3211F650",
          NextDialogue = 20000905,
          Subtitle = "I'm glad you're happy. This trip was totally worth it."
        },
        [20000905] = {
          Camera = "-152.634766,127.236084,85.355469,0.000004,4.999999,-59.59177,30.0,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeOutQuad",
          ContentFR = "Psyche caresse la terre, épanouie. Tu te souviens soudain de la fleur, celle qu’elle t’avait donnée.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000905,
          DisableMouth = 1,
          Duration = 3,
          FacialId = {
            [1] = "200027:Happy01",
            [2] = "100001:Happy02"
          },
          FinalCamera = "-155.263672,125.692383,85.355469,0.000004,4.999999,-61.591789,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "3211F67A",
          LookAt = {
            [1] = "200027:p(TargetPonit_Flower)"
          },
          NextDialogue = 20000906,
          Scripts = "CameraMoveTo{_delay{3},TargetPosition{\"36.587891,-51.674805,131.013672,0.000006,0.999926,-10.192198,30.0,103.831886,false,Manual,2.984025\"},duration{0}}",
          Subtitle = "(Psyche is lost in happiness as she feels the soil in her hand. You suddenly remember the flower — the one that Psyche gave you.)",
          TalkActionId = {
            [1] = "200027:Explain02_End",
            [2] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 2.5,
          TurnTo = {
            [1] = "200027:p(130)"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F67A"
        },
        [20000906] = {
          Camera = "36.587891,-51.674805,131.013672,0.000006,0.999926,-10.192198,30.0,103.831886,false,Manual,2.984025",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Tu la sors. Bien qu’un certain temps soit passé, le bouton floral reste intact et repose paisiblement dans ta paume.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000906,
          DisableMouth = 1,
          Duration = 3,
          FacialId = {
            [1] = "100001:Happy01"
          },
          FinalCamera = "-6.515625,-43.923828,124.070312,0.000006,0.999926,-10.192293,30.0,148.292877,false,Manual,2.984025",
          GUID = "3211F6A4",
          NextDialogue = 20000907,
          Scripts = "PlayAnimation{ActorId{100001},AnimationId{\"Give\"},Duration{1}}",
          Subtitle = "(You take out the flower and it rests peacefully on your palm. Though much time has passed since you received it, its petals remain immaculate.)",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/2001/200009/3211F6A4"
        },
        [20000907] = {
          Camera = "55.597656,319.302246,78.720703,0.0,0.0,-87.5,25.0,295.179138,false,DoNotOverride,1.2",
          ContentFR = "Oh, c’est la fleur que je t’ai donnée... tu l’as gardée tout ce temps !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000907,
          Duration = 3,
          FinalCamera = "57.142578,283.636963,78.720703,0.0,0.0,-87.5,25.0,291.235352,false,DoNotOverride,1.2",
          GUID = "3211F6CE",
          LookAt = {
            [1] = "200027:n(100001)"
          },
          NextDialogue = 20000908,
          Scripts = "PlayAnimation{_delay{2.5},ActorId{200027},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 200027,
          Subtitle = "Aww, it's that flower I gave you... And you've been carrying it around all this time.",
          ToFinalCameraBlendTime = 6,
          TurnTo = {
            [1] = "200027:p(-90)"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F6CE"
        },
        [20000908] = {
          Camera = "-6.515625,-43.923828,124.070312,0.000006,0.999926,-10.192293,30.0,147.70752,false,Manual,2.984025",
          ContentFR = "C’est un précieux cadeau après tout. Mais tu chéris tellement ces fleurs... ça ne t’a pas fait mal de l’enlever pour me l’offrir ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000908,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211F6F8",
          NextDialogue = 20000909,
          SpeakNpcId = 100001,
          Subtitle = "Of course, it's a precious gift. You love these flowers, don't you? Is it okay for you to pluck one from the plant and give it away?",
          TalkActionId = {
            [1] = "200027:Explain02_End",
            [2] = "100001:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F6F8"
        },
        [20000909] = {
          Camera = "216.292969,-11.74585,132.582031,0.000009,-2.600034,-158.592346,30.0,215.0,false,Manual,2.984025",
          ContentFR = "Oui... j’étais un peu triste à l’époque, quand j’étais petite.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000909,
          Duration = 3,
          FacialId = {
            [1] = "200027:Sad01"
          },
          GUID = "3211F722",
          NextDialogue = 20000910,
          SpeakNpcId = 200027,
          Subtitle = "Hmm... I was not, when I was little.",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F722"
        },
        [20000910] = {
          Camera = "125.662109,-37.871582,125.59375,0.0,0.599998,-165.793549,25.0,127.299126,false,DoNotOverride,1.2",
          ContentFR = "Tu as déjà vu des fleurs coupées dans les magasins ? Quand j’étais enfant, je n’aimais pas ça... Je trouvais ça cruel.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000910,
          Duration = 3,
          FacialId = {
            [1] = "100001:Smile02"
          },
          FinalCamera = "125.382812,-36.4729,125.59375,0.0,0.599998,-168.793213,25.0,147.010483,false,DoNotOverride,1.8",
          GUID = "3211F74C",
          NextDialogue = 20000911,
          Scripts = "SEQ{PlayAnimation{ActorId{200027},AnimationId{\"Explain01_Start\"},Duration{4}},PlayAnimation{ActorId{200027},AnimationId{\"Explain01_End\"},Duration{1}},PlayAnimation{ActorId{200027},AnimationId{\"DisagreeHead\"},Duration{1}}}",
          SpeakNpcId = 200027,
          Subtitle = "Have you seen freshly cut flowers sold at the florists? I never liked that practice... It always made me feel sorry for the flowers.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200009/3211F74C"
        },
        [20000911] = {
          Camera = "-6.826172,100.584717,97.013672,0.000043,9.999396,-119.386726,25.0,118.235596,false,DoNotOverride,1.2",
          ContentFR = "Les fleurs, les racines, les tiges et les feuilles font toutes partie de la plante. Mais on ne garde que la fleur pour la regarder, la séparant de son pied, seule jusqu’à sa fin...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000911,
          Duration = 3,
          FinalCamera = "-38.798828,43.810303,123.986328,0.000043,9.999396,-119.386726,25.0,118.235596,false,DoNotOverride,1.2",
          GUID = "3211F776",
          NextOptions = {
            [1] = 200009111,
            [2] = 200009112
          },
          SpeakNpcId = 200027,
          Subtitle = "Flowers, stems, and leaves all belong to the same plant, yet people cut the flowers to admire their beauty, leaving them to wilt and die alone.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/2001/200009/3211F776"
        },
        [20000912] = {
          Camera = "278.988281,10.379639,123.230469,0.0,0.0,-157.596741,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui, de notre point de vue, c’est vrai...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000912,
          Duration = 3,
          GUID = "3211F7A0",
          NextDialogue = 20000913,
          SpeakNpcId = 200027,
          Subtitle = "It does seem so, from our perspective...",
          VoiceName = "voice/$Locale$/story/2001/200009/3211F7A0"
        },
        [20000913] = {
          Camera = "-76.474609,-28.993408,129.525391,0.000001,-2.400053,-20.986586,33.0,211.485077,false,Manual,4.671381",
          ContentFR = "Tu as parlé de quand tu étais petite... est-ce que tu penses différemment maintenant ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000913,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211F7CA",
          NextDialogue = 20000914,
          SpeakNpcId = 100001,
          Subtitle = "You said when you were little... Does that mean you feel differently now?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F7CA"
        },
        [20000914] = {
          Camera = "216.292969,-11.74585,132.582031,0.000009,-2.600034,-158.592346,30.0,219.542435,false,Manual,2.984025",
          ContentFR = "Pas complètement. Juste...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000914,
          Duration = 3,
          GUID = "3211F7F4",
          NextDialogue = 20000915,
          SpeakNpcId = 200027,
          Subtitle = "Not entirely. But...",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "200027:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F7F4"
        },
        [20000915] = {
          Camera = "216.292969,-11.74585,132.582031,0.000009,-2.600034,-158.592346,30.0,219.542435,false,Manual,2.984025",
          ContentFR = "Puis-je te poser une question ? Que penses-tu des fleurs qu’on coupe ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000915,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211F81E",
          NextOptions = {
            [1] = 200009151,
            [2] = 200009152,
            [3] = 200009153
          },
          Scripts = "SEQ{PlayAnimation{ActorId{200027},AnimationId{\"Explain01_Start\"},Duration{4}},PlayAnimation{ActorId{200027},AnimationId{\"Explain01_End\"},Duration{1}}}",
          SpeakNpcId = 200027,
          Subtitle = "Can I ask you something first? What do you think about flowers that are plucked from their plants?",
          VoiceName = "voice/$Locale$/story/2001/200009/3211F81E"
        },
        [20000916] = {
          Camera = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
          ContentFR = "Hmm... je suis contente de t’avoir offerte cette fleur, je savais que tu en prendrais soin.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000916,
          Duration = 3,
          GUID = "3211F848",
          NextDialogue = 20000919,
          SpeakNpcId = 200027,
          Subtitle = "I'm glad I gave you the flower. I knew you'd take good care of it.",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F848"
        },
        [20000917] = {
          Camera = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
          ContentFR = "Oui... je comprends, moi aussi je le pense.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000917,
          Duration = 3,
          FacialId = {
            [1] = "200027:Smile01"
          },
          GUID = "3211F872",
          NextDialogue = 20000919,
          SpeakNpcId = 200027,
          Subtitle = "Hmm... I understand. That's what I thought.",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F872"
        },
        [20000918] = {
          Camera = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
          ContentFR = "Tu penses comme moi quand j’étais petite.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000918,
          Duration = 3,
          FacialId = {
            [1] = "200027:Smile01"
          },
          GUID = "3211F89C",
          NextDialogue = 20000919,
          SpeakNpcId = 200027,
          Subtitle = "You feel the same way I did when I was little.",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F89C"
        },
        [20000919] = {
          Camera = "624.845703,-2701.800537,279.474609,0.0,0.0,-89.999985,25.0,147.010483,false,DoNotOverride,1.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Aujourd’hui, voir une fleur coupée me rend encore triste. Mais je commence à voir combien elles sont incroyables, plus que je ne l’imaginais.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000919,
          Duration = 3,
          FinalCamera = "624.845703,-2600.36084,279.474609,0.0,0.0,-89.999985,25.0,147.010483,false,DoNotOverride,1.8",
          GUID = "3211F8C6",
          NextDialogue = 20000920,
          SpeakNpcId = 200027,
          Subtitle = "Now, when I see cut flowers, I still feel a bit sad. But over the years, I've come to realise that they are amazing — far more amazing than I thought.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200009/3211F8C6"
        },
        [20000920] = {
          Camera = "260.572266,-2538.362549,380.068359,0.0,-7.500005,90.0,15.0,147.010483,false,DoNotOverride,1.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Dès qu’elles sont coupées, elles sont destinées à ne plus donner de fruit et à faner lentement...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000920,
          Duration = 3,
          FinalCamera = "260.572266,-2339.146973,232.763672,0.0,-2.499965,90.0,17.5,147.010483,false,DoNotOverride,1.8",
          GUID = "3211F8F0",
          NextDialogue = 20000921,
          SpeakNpcId = 200027,
          Subtitle = "A plucked flower would no longer bear fruit. It's fated to perish in a slow, wilting death...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200009/3211F8F0"
        },
        [20000921] = {
          Camera = "454.208984,234.598389,25.705078,0.000022,5.099815,-140.996017,30.0,147.010483,false,DoNotOverride,1.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Pourtant, elles continuent à absorber l’eau de toutes leurs forces et, même pour un temps si court, s’épanouissent pleinement, comme si elles avaient encore leurs racines, comme si elles n’avaient jamais été coupées. ",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000921,
          Duration = 3,
          FinalCamera = "428.185547,247.284424,26.796875,0.000022,5.099815,-136.996017,30.0,147.010483,false,DoNotOverride,1.8",
          GUID = "3211F91A",
          NextDialogue = 20000922,
          SpeakNpcId = 200027,
          Subtitle = "Yet it tries to absorb water, as if still rooted, blooming fully before its brief life fades.",
          TalkActionId = {
            [1] = "100001:Think_End",
            [2] = "200027:Talk02_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/2001/200009/3211F91A"
        },
        [20000922] = {
          Camera = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
          ContentFR = "Maintenant, je ne les plains plus. Je les admire.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000922,
          Duration = 3,
          GUID = "3211F944",
          NextOptions = {
            [1] = 200009221,
            [2] = 200009222
          },
          SpeakNpcId = 200027,
          Subtitle = "I no longer pity them — I'm impressed by them.",
          TalkActionId = {
            [1] = "200027:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F944"
        },
        [20000923] = {
          Camera = "104.851562,-52.04541,128.546875,0.0,1.599992,-165.590759,25.0,95.278557,false,Manual,1.8",
          ContentFR = "Toi aussi, tu penses comme moi, hein ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000923,
          Duration = 3,
          FacialId = {
            [1] = "200027:Happy01"
          },
          GUID = "3211F96E",
          NextDialogue = 20000925,
          SpeakNpcId = 200027,
          Subtitle = "You feel the same, right?",
          TalkActionId = {
            [1] = "200027:AgreeHead"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F96E"
        },
        [20000924] = {
          Camera = "104.851562,-52.04541,128.546875,0.0,1.599992,-165.590759,25.0,95.278557,false,Manual,1.8",
          ContentFR = "Tu es vraiment {性别:gentil|gentille}... oui, tu as raison, ce serait mieux si elles n’étaient jamais coupées.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000924,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211F998",
          NextDialogue = 20000925,
          SpeakNpcId = 200027,
          Subtitle = "You have a kind soul... And yes, you're right — it might be best not to cut them at all.",
          VoiceName = "voice/$Locale$/story/2001/200009/3211F998"
        },
        [20000925] = {
          Camera = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
          ContentFR = "Ah... je ne voulais pas, mais je crois que j’ai un peu alourdi la conversation, pardon, pardon...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000925,
          Duration = 3,
          FacialId = {
            [1] = "200027:Sad02"
          },
          GUID = "3211F9C2",
          NextDialogue = 20000926,
          SpeakNpcId = 200027,
          Subtitle = "Oh, just listen to how sombre and heavy our conversation has become. That wasn't my intention...",
          TalkActionId = {
            [1] = "200027:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F9C2"
        },
        [20000926] = {
          Camera = "125.382812,-36.4729,125.59375,-0.0,0.599998,-168.793137,25.0,147.010483,false,DoNotOverride,1.8",
          ContentFR = "Merci pour la terre, son humidité et sa texture sont parfaites... Peut-être que tu as un talent pour le jardinage !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000926,
          Duration = 3,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200027:Smile01"
          },
          GUID = "3211F9EC",
          NextOptions = {
            [1] = 200009261,
            [2] = 200009262
          },
          SpeakNpcId = 200027,
          Subtitle = "Anyway, the soil you brought back is great. The wetness and softness are perfect... You might have a real knack for gardening!",
          TalkActionId = {
            [1] = "200027:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200009/3211F9EC"
        },
        [20000927] = {
          Camera = "106.785156,-624.62207,37.896484,0.0,2.399917,5.600382,30.0,352.267853,false,Manual,1.2",
          ContentFR = "Bien sûr ! Je te transmettrai tous mes secrets... si j’ai le temps.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000927,
          Duration = 3,
          FinalCamera = "106.785156,-624.62207,56.728516,0.000001,0.0,5.600479,30.0,352.267853,false,Manual,1.2",
          GUID = "3211FA16",
          NextDialogue = 20000928,
          SpeakNpcId = 200027,
          Subtitle = "Certainly! I'd be delighted to share all the gardening secrets I know! ...If time allows.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/2001/200009/3211FA16"
        },
        [20000928] = {
          Camera = "-73.154297,-38.155029,129.271484,0.000001,-2.400053,-18.186663,33.0,255.978088,false,Manual,4.671381",
          ContentFR = "Parfait, c’est une promesse. ",
          DefaultLookAt = "TalkNpc",
          DialogueId = 20000928,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "3211FA40",
          NextDialogue = 20000929,
