          ExStoryInfo = "Player",
          GUID = "32132DDE",
          SpeakNpcId = 100001,
          Subtitle = "Thank you...",
          VoiceName = "voice/$Locale$/story/2001/200028/32132DDE"
        },
        [20002901] = {
          ContentFR = "<I>J’ai déjà mis au courant l’Étranger et Snow de tout ce qui s’est passé aujourd’hui.</>",
          DialogueId = 20002901,
          DisableMouth = 1,
          Duration = 3,
          GUID = "32133DF2",
          NextDialogue = 20002902,
          Subtitle = "(I've filled in Outsider and Snow on everything that happened today.)"
        },
        [20002902] = {
