        [20004201] = {DialogueId = 20004201, GUID = "3214133A"},
        [20004301] = {
          Camera = "101.757812,-139.77832,28.292236,0.000069,0.600367,129.191574,12.5,133.732285,false,DoNotOverride,2.0",
          DialogueId = 20004301,
          GUID = "321423A2"
        },
        [20004501] = {
          ContentFR = "Mon enfant chéri... merci d’être venue au monde.",
          DialogueId = 20004501,
          Duration = 4,
          GUID = "32144472",
          NextDialogue = 20004502,
          SnapShot = "HEART",
          Subtitle = "My dearest child, thank you for coming into the world.",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA87"
        },
        [20004502] = {
          ContentFR = "Tu es la fierté de notre vie.",
          DialogueId = 20004502,
          Duration = 3,
          GUID = "3214449C",
          NextDialogue = 20004503,
          SnapShot = "HEART",
          Subtitle = "You are the pride of our lives.",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA88"
        },
        [20004503] = {
          ContentFR = "Psyche, viens, jurons-le sur nos petits doigts ! Nous serons amies pour la vie !",
          DialogueId = 20004503,
          Duration = 5,
          GUID = "321444C6",
          NextDialogue = 20004504,
          SnapShot = "HEART",
          Subtitle = "Psyche, pinky promise. We'll be best friends for life!",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA89"
        },
        [20004504] = {
          ContentFR = "Je me souviendrai que tu as vraiment vécu.",
          DialogueId = 20004504,
          Duration = 3,
          GUID = "321444F0",
          NextDialogue = 20004505,
          SnapShot = "HEART",
          Subtitle = "I'll remember that you've lived in this world.",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA90"
        },
        [20004505] = {
          ContentFR = "Nous t’attendrons... jusqu’à ton retour.",
          DialogueId = 20004505,
          Duration = 3,
          GUID = "3214451A",
          NextDialogue = 20004506,
          SnapShot = "HEART",
          Subtitle = "We'll wait for your return.",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA91"
        },
        [20004506] = {
          ContentFR = "Ô destin, pour une seule fois... aie pitié de moi. Permets que je l’aide à accomplir ce vœu...",
          DialogueId = 20004506,
          Duration = 5,
          GUID = "32144544",
          NextDialogue = 20004507,
          SnapShot = "HEART",
          Subtitle = "Fate, please have mercy on me. Let me help her fulfil this wish.",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA92"
        },
        [20004507] = {
          ContentFR = "Prends cette fleur. Elle te portera bonheur.",
          DialogueId = 20004507,
          Duration = 4,
          GUID = "3214456E",
          NextDialogue = 20004508,
          SnapShot = "HEART",
          Subtitle = "Take this flower with you. It will bring you good luck.",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA93"
        },
        [20004508] = {
          ContentFR = "Tu pourras aller sur une petite île, bâtir une maison au bord de la mer, planter autour d’elle des fleurs blanches...",
          DialogueId = 20004508,
          Duration = 5,
          GUID = "32144598",
          NextDialogue = 20004509,
          SnapShot = "HEART",
          Subtitle = "You'll go to a small island, where you can build a house by the sea and grow white flowers around it.",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA94"
        },
        [20004509] = {
          ContentFR = "Psyche, je suis venu te ramener à la maison.",
          DialogueId = 20004509,
          Duration = 3,
          GUID = "321445C2",
          SnapShot = "HEART",
          Subtitle = "Psyche, I'm here to take you home.",
          VoiceName = "voice/$Locale$/story/1002/200045/1950CA95"
        },
        [20004601] = {
          Camera = "-6070.914062,904.957031,49.383179,-0.002747,-10.099882,-52.562939,15.0,78.914192,false,Manual,1.2",
