          GUID = "32146542",
          NextDialogue = 20004702,
          SpeakNpcId = 100001,
          Subtitle = "Er, it broke.",
          VoiceName = "voice/$Locale$/story/1002/101137/19518F12"
        },
        [20004702] = {
          ContentFR = "C’est fait avec de la récup’ ! Qu’il fonctionne déjà, c’est un miracle.",
          DialogueId = 20004702,
          Duration = 3,
          GUID = "3214656C",
          SpeakNpcId = 200021,
          Subtitle = "Well, it is made from scrap, after all. I was surprised that it would work!",
          VoiceName = "voice/$Locale$/story/1002/101137/19518F3C"
        },
        [20004801] = {
