        [20004802] = {
          Camera = "-202.353943,-345.827148,123.976562,-0.001007,-12.607087,71.399368,35.0,153.157944,false,Manual,2.188727",
          ContentFR = "Je ne l’ai pas encore vu de mes propres yeux... mais rien qu’à l’idée que ce soit vrai, j’en ai des frissons partout !",
          DialogueId = 20004802,
          GUID = "321475D4",
          LookAt = {
            [1] = "200002:n(100001)"
          },
          NextDialogue = 20004803,
          Scripts = "PlayFacial{_delay{4},ActorId{200002},FacialId{\"Shock01\"}}",
          SpeakNpcId = 200002,
          Subtitle = "I haven't seen it yet, but just thinking about it — ooh, I'm getting goosebumps already!",
          TalkActionId = {
            [1] = "200002:SpecialConfident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200048/321475D4"
        },
        [20004803] = {
          Camera = "-578.413757,-1981.769775,101.114594,0.0,0.0,76.99968,25.0,198.283234,false,Manual,3.328919",
          ContentFR = "Calme-toi et explique. Qu’est-ce qu’il se passe ?",
          DialogueId = 20004803,
          FinalCamera = "-564.10083,-1919.769043,101.114594,0.0,0.0,76.999603,25.0,198.283234,false,Manual,3.328919",
          GUID = "321475FE",
          NextDialogue = 20004804,
          Scripts = "PlayFacial{_delay{1},ActorId{200002},FacialId{\"None\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Calm down and take a breath. What's going on?",
          TalkActionId = {
            [1] = "200002:SpecialConfident_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200048/321475FE"
        },
        [20004804] = {
          Camera = "-143.963196,-59.587891,62.005508,0.000066,10.798099,-99.194954,35.0,379.954346,false,Manual,3.328919",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Impossible de rester calme ! J’ai entendu dire qu’à l’extérieur de Givrelac, une créature titanesque a été aperçue, un cochon plus grand que toi, avec une tête grosse comme une forteresse ! D’un seul coup de sabot, il pourrait réduire les murailles de la cité en miettes !",
          DialogueId = 20004804,
          FinalCamera = "-140.150818,-60.366699,62.005493,0.000062,10.798099,-101.595215,35.0,379.954346,false,Manual,3.328919",
          GUID = "32147628",
