CameraMoveTo{_delay{4},TargetPosition{"-183.687469,-544.837402,154.855408,0.000067,-7.500012,100.000069,35.0,229.363983,false,Manual,1.6"},duration{0}},
CameraMoveTo{_delay{4.1},TargetPosition{"-183.685608,-544.995117,154.855408,0.000067,-7.500005,105.000092,35.0,481.79422,false,Manual,2.023338"},duration{2.5}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "No time to breathe! Listen, someone spotted a GIGANTIC pig outside Icelake! And it's taller than you, with a head the size of a van. And if it stomps its hoof — Bam! The city walls will come down!",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200048/32147628"
        },
        [20004805] = {
          Camera = "-662.342529,29.628418,112.909363,0.000096,-2.999962,-41.401596,25.0,161.861893,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Hein ?! Mais de quoi tu parles ! Ton estomac te fait encore perdre la raison !",
          DialogueId = 20004805,
          FinalCamera = "-660.245789,32.00293,112.909363,0.000096,-2.999962,-41.401596,25.0,824.858765,false,Manual,1.2",
          GUID = "32147652",
          NextDialogue = 20004807,
          Scripts = [[
PARA{
SetRotation{SetRotationDescription{"100001:p(30)"}},
MoveTo{_delay{0.1},ActorId{100001},TargetPoint{"P200048Nvzhu2"},MoveSpeed{50},Visibility{"Show"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "What are you talking about? Are you thinking with your stomach again?",
          TalkActionId = {
            [1] = "200002:Bai_Circle_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/2001/200048/32147652"
        },
        [20004806] = {
          Camera = "-662.342529,29.628418,112.909363,0.000096,-2.999962,-41.401596,25.0,161.861893,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Bien sûr que non ! Tu me prends pour qui ? En tant que Roi Démon, j’ai affronté tempêtes et cataclysmes, je ne m’affole pas pour un simple cochon !",
          DialogueId = 20004806,
          FinalCamera = "-660.245789,32.00293,112.909363,0.000096,-2.999962,-41.401596,25.0,824.858765,false,Manual,1.2",
          GUID = "3214767C",
          NextDialogue = 20004807,
          Scripts = [[
PARA{
SetRotation{SetRotationDescription{"100001:p(30)"}},
MoveTo{_delay{0.1},ActorId{100001},TargetPoint{"P200048Nvzhu2"},MoveSpeed{50},Visibility{"Show"}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "...Of course it's more than that. As the mighty Demon King, I don't just freak out over a big pig.",
          TalkActionId = {
            [1] = "200002:Bai_Circle_End"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/2001/200048/3214767C"
        },
        [20004807] = {
          Camera = "-992.792297,-208.039062,42.167068,0.000105,1.999995,-0.499939,32.5,507.776001,false,Manual,1.2",
          CameraBlendCurve = "easeInQuad",
          ContentFR = "Bref ! Viens, viens ! De toute façon tu n’es pas si {性别:occupé|occupée}, hein ? Alors accompagne-moi dans cette quête périlleuse !",
          DialogueId = 20004807,
          FinalCamera = "-920.479614,-208.66748,44.692398,0.000105,1.999995,-0.499969,35.0,507.776001,false,Manual,1.2",
          GUID = "321476A6",
          Scripts = [[
