PlayFacial{_delay{2.1},ActorId{200074},FacialId{"Confident01"}}
},
PlayAnimation{_delay{5.1},ActorId{200074},AnimationId{"Explain02_End"}}
}
}]],
          SpeakNpcId = 200074,
          Subtitle = "Oh! Speaking of which, we've got bad guys to catch! Icelake is WAY bigger than I expected — we need to hurry!",
          VoiceName = "voice/$Locale$/story/2001/200057/32150C9A"
        },
        [20005722] = {
          Camera = "345.16864,317.928711,137.46875,-0.000763,1.607089,136.417633,35.0,169,false,Manual,12.0",
          ContentFR = "Tu as un plan ?",
          DialogueId = 20005722,
          FinalCamera = "311.653595,331.706055,134.34375,-0.000763,4.806766,132.015808,35.0,169.08606,false,Manual,12.0",
          GUID = "32150CC4",
          NextDialogue = 20005723,
          SpeakNpcId = 100001,
          Subtitle = "Do you have any idea?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200057/32150CC4"
        },
        [20005723] = {
          Camera = "427.671539,393.154297,128.347656,-0.000763,-6.992433,-162.983078,35.000008,216.630737,false,Manual,12.0",
          ContentFR = "J’ai l’unique Filbert ! Son flair est incroyable, elle peut sentir les Géniemon aux alentours et repérer les chasseurs !",
          DialogueId = 20005723,
          FinalCamera = "427.671539,393.154297,128.347656,-0.000763,-8.192443,-154.983536,35.000008,216.630737,false,Manual,12.0",
          GUID = "32150CEE",
          LookAt = {
            [1] = "200074:n(200086)"
          },
          Scripts = [[
PARA{
PlayFacial{_delay{2.1},ActorId{200074},FacialId{"Happy01"}},
PlayAnimation{_delay{4.1},ActorId{200074},AnimationId{"Confident_Start"}}
}]],
          SpeakNpcId = 200074,
          Subtitle = "I have my dear — Filbert! Filbert's nose is incredible — she can sniff out Geniemons from miles away! And those bad hunters must be around!",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "200074:p(45)"
          },
          VoiceName = "voice/$Locale$/story/2001/200057/32150CEE"
        },
        [20005801] = {
          ContentFR = "Allons en hauteur, là où l’odeur se répand le mieux.",
          DialogueId = 20005801,
          GUID = "321519BA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "Alright, let's go higher. The scent spreads farther up there.",
          VoiceName = "voice/$Locale$/story/2001/200058/321519BA"
        },
        [20005802] = {
          ContentFR = "Ah ! Filbert a flairé quelque chose, regardez par là !",
          DialogueId = 20005802,
          GUID = "321519E4",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "Oh! Filbert's onto something — over there!",
          VoiceName = "voice/$Locale$/story/2001/200058/321519E4"
        },
        [20005803] = {
          ContentFR = "C’est bien ici... mais aucun Géniemon à l’horizon, seulement...",
          DialogueId = 20005803,
          GUID = "32151A0E",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "This should be the place. Strange, I don't see any Geniemons but—",
          VoiceName = "voice/$Locale$/story/2001/200058/32151A0E"
        },
        [20005804] = {
          ContentFR = "Oh non ! Leurs pièges... Ces vilains sont déjà partis !",
          DialogueId = 20005804,
          GUID = "32151A38",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005805,
          SpeakNpcId = 200074,
          Subtitle = "The trap they set up! Those baddies must have been here moments ago.",
          VoiceName = "voice/$Locale$/story/2001/200058/32151A38"
        },
        [20005805] = {
          ContentFR = "Allons un peu plus loin, là où il y a moins de monde, l’odeur sera plus facile à suivre.",
          DialogueId = 20005805,
          GUID = "32151A62",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "Alright, let's try somewhere quieter. The scent will stand out more where there are fewer people.",
          VoiceName = "voice/$Locale$/story/2001/200058/32151A62"
        },
        [20005901] = {
          ContentFR = "Ici, ici, {性别:Monsieur|Mademoiselle}, doucement, marche lentement, fais attention à ne pas glisser.",
          DialogueId = 20005901,
          GUID = "32152A22",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "This way! Careful, {性别:Sir|Miss} — it's slippery here.",
          VoiceName = "voice/$Locale$/story/2001/200059/32152A22"
        },
        [20005902] = {
          ContentFR = "Euh... ici aussi, il y a un piège.",
          DialogueId = 20005902,
          GUID = "32152A4C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005903,
          SpeakNpcId = 200074,
          Subtitle = "Ugh... Another trap here.",
          VoiceName = "voice/$Locale$/story/2001/200059/32152A4C"
        },
        [20005903] = {
          ContentFR = "<I>Groin…</>",
          DialogueId = 20005903,
          GUID = "32152A76",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20005904,
          SpeakNpcId = 200086,
          Subtitle = "Oink...",
          VoiceName = "voice/$Locale$/story/2001/200059/32152A76"
        },
        [20005904] = {
          ContentFR = "Allez, Filbert, ne te décourage pas, on essaie l’endroit suivant.",
          DialogueId = 20005904,
          GUID = "32152AA0",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "It's okay, Filbert. Let's try another spot.",
          VoiceName = "voice/$Locale$/story/2001/200059/32152AA0"
        },
        [20006001] = {
          Camera = "606.297791,-918.271484,784.640625,0.000207,-7.459188,79.056267,35.000015,174.116943,false,Manual,12.0",
          ContentFR = "C’est... l’entrée des égouts ?",
          DialogueId = 20006001,
          FinalCamera = "541.89978,-1160.757812,832.416992,0.000208,-8.459162,77.455727,35.000015,174.116943,false,Manual,12.0",
          GUID = "32153A8A",
          NextDialogue = 20006002,
          SpeakNpcId = 100001,
          Subtitle = "Is this... the entrance to the sewers?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153A8A"
        },
        [20006002] = {
          Camera = "-38.9104,-306.495117,391.232422,0.000209,-8.45895,-1.344757,35.000015,174.116943,false,Manual,12.0",
          ContentFR = "Oui. Il y a beaucoup d’humidité et peu de monde ici, c’est un bon endroit pour que des Géniemon apparaissent.",
          DialogueId = 20006002,
          FinalCamera = "-508.082397,-300.290039,450.730469,0.000209,-7.058932,-0.744781,35.000019,174.116943,false,Manual,12.0",
          GUID = "32153AB4",
          NextDialogue = 20006003,
          SpeakNpcId = 200074,
          Subtitle = "Yes. The water vapor and quietness here make this a perfect spot for Geniemons.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153AB4"
        },
        [20006003] = {
          Camera = "-768.485962,-608.558594,293.948242,0.000155,-2.058947,167.054123,35.000015,174.116943,false,Manual,12.0",
          ContentFR = "Mais aux deux autres endroits, les Géniemon ont déjà été capturés. J’ai un mauvais pressentiment pour celui-ci aussi....",
          DialogueId = 20006003,
          FinalCamera = "-796.652222,-602.085938,292.908691,0.000155,-0.458948,167.453751,35.000015,174.116943,false,Manual,12.0",
          GUID = "32153ADE",
          NextDialogue = 20006004,
          SpeakNpcId = 200074,
          Subtitle = "But... the two previous spots were already wiped clean. I've got a bad feeling about this one too...",
          TalkActionId = {
            [1] = "200074:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153ADE"
        },
        [20006004] = {
          Camera = "-913.889771,-785.241211,282.312012,0.000156,-6.059081,28.454039,35.000015,174.116943,false,Manual,12.0",
          ContentFR = "Ah ! Un piège encore intact ! Il y a un Géniemon à l’intérieur !",
          DialogueId = 20006004,
          FinalCamera = "-932.27832,-741.113281,282.15332,0.000157,-6.459043,18.853708,35.000015,174.116943,false,Manual,12.0",
          GUID = "32153B08",
          NextDialogue = 20006005,
          SpeakNpcId = 200002,
          Subtitle = "Look! They haven't taken this trap yet — and there's a Geniemon inside!",
          TalkActionId = {
            [1] = "200074:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153B08"
        },
        [20006005] = {
          Camera = "-264.765686,-875.787109,308.994629,0.000174,-6.859033,150.453903,35.000015,733.116943,false,Manual,22.0",
          ContentFR = "Super, cette fois on est arrivés à temps. D’abord on le libère, puis on attend que les chasseurs apparaissent.",
          DialogueId = 20006005,
          FinalCamera = "-222.946228,-1021.376953,416.390625,0.000172,-15.459046,141.053696,35.000015,733.116943,false,Manual,22.0",
          GUID = "32153B32",
          SpeakNpcId = 200074,
          Subtitle = "Finally! We made it in time for once. Let's get it out first, then wait for those baddies to show up.",
          TalkActionId = {
            [1] = "200002:SpecialHappy_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153B32"
        },
        [20006006] = {
          ContentFR = "Après quelques instants d’agitation, le Géniemon pris au piège est délivré. Toutefois... son attitude paraît... peu accueillante.",
          DialogueId = 20006006,
          GUID = "32153B5C",
          Subtitle = "After some scrambling, the trapped Geniemon is freed. However... it doesn't seem very friendly.",
          VoiceName = "voice/$Locale$/story/2001/200060/32153B5C"
        },
        [20006007] = {
          Camera = "-348.273315,-725.485352,348.286133,0.000093,-9.591675,168.57576,35.0,1674.542114,false,Manual,22.0",
          ContentFR = "Ne crains rien, petit Géniemon. Le Grand Roi Démon, mon petit larbin et la Chasseuse de Chasseurs de Géniemon sommes venus te sauver ! Maintenant file, mets-toi à l’abri !",
          DialogueId = 20006007,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "32153B86",
          LookAt = {
            [1] = "200002:n(820000)"
          },
          NextDialogue = 20006008,
          SpeakNpcId = 200002,
          Subtitle = "Don't be scared, little one~ The great Demon King and my loyal Little Minion, and the Geniemon Hunter Hunter, are here to save you! Now, off you go — get out of here and take care!",
          TalkActionId = {
            [1] = "200002:SpecialConfident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153B86"
        },
        [20006008] = {
          Camera = "-1100.135376,-637.394531,335.55957,0.000086,-3.391571,1.375749,35.0,1674.542114,false,Manual,6.0",
          ContentFR = "<I>Yiip— !</>",
          DialogueId = 20006008,
          GUID = "32153BB0",
          NextDialogue = 20006009,
          SpeakNpcId = 820000,
          SpeakNpcName = "UI_Npc_Name_PanTuokun",
          Subtitle = "Yip—!",
          TalkActionId = {
            [1] = "200002:SpecialConfident_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153BB0"
        },
        [20006009] = {
          Camera = "-619.304932,-686.379883,266.316895,0.000167,1.568205,-159.823883,35.000019,174.116943,false,Manual,12.0",
          ContentFR = "Pas besoin d’être si excité, c’est normal. Attends... j’ai l’impression de l’avoir déjà vu. Est-ce qu’on ne l’aurait pas sauvé une fois dehors, près de Givrelac ?",
          DialogueId = 20006009,
          FinalCamera = "-646.760498,-696.469727,267.117676,0.000167,1.568205,-159.823883,35.000019,174.116943,false,Manual,12.0",
          GUID = "32153BDA",
          NextDialogue = 20006010,
          SpeakNpcId = 200002,
          Subtitle = "You're welcome. We're happy to help... Wait, this one looks kind of familiar. Did we save it once outside the city?",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153BDA"
        },
        [20006010] = {
          Camera = "-422.686035,-758.615234,323.150879,0.000171,-5.031971,158.176743,35.000019,294.116943,false,Manual,12.0",
          ContentFR = "Rentre vite chez toi et fais attention, surtout, ne te laisse plus attraper par ces chasseurs. Tant que je ne serai pas une vraie Chasseuse de Chasseurs de Géniemon, sois prudent !",
          DialogueId = 20006010,
          GUID = "32153C04",
          LookAt = {
            [1] = "200074:n(820000)"
          },
          NextDialogue = 20006011,
          SpeakNpcId = 200074,
          Subtitle = "Now go home, and stay safe! Don't let those mean hunters catch you again. Until I'm a true, capable Geniemon Hunter Hunter, you'd better be extra careful.",
          TalkActionId = {
            [1] = "200074:Explain02_Start",
            [2] = "200002:Think_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153C04"
        },
        [20006011] = {
          Camera = "-781.993408,-607.023438,317.071777,0.00017,-1.2322,-155.023941,35.000019,174.116943,false,Manual,12.0",
          ContentFR = "On dirait bien que si.",
          DialogueId = 20006011,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "32153C2E",
          NextDialogue = 20006012,
          SpeakNpcId = 100001,
          Subtitle = "I think we did.",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "200074:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153C2E"
        },
        [20006012] = {
          Camera = "-823.676147,-643.197266,314.435547,0.00011,-1.391562,0.574502,35.000008,242.039719,false,Manual,3.5",
          ContentFR = "<I>Yiiiip— !</>",
          DialogueId = 20006012,
          GUID = "32153C58",
          NextDialogue = 20006013,
          SpeakNpcId = 820000,
          SpeakNpcName = "UI_Npc_Name_PanTuokun",
          Subtitle = "Yiiiip—!",
          VoiceName = "voice/$Locale$/story/2001/200060/32153C58"
        },
        [20006013] = {
          Camera = "-383.416382,-617.654297,369.226074,0.000175,-13.632108,-162.021347,35.000019,314.116943,false,Manual,2.8",
          ContentFR = "Allez, arrête de piailler maintenant et pars vite. La prochaine fois, tu n’auras peut-être pas autant de chance.",
          DialogueId = 20006013,
          FacialId = {
            [1] = "200002:Confident01"
          },
          FinalCamera = "-444.914062,-637.505859,353.714355,0.000175,-13.432099,-162.221298,35.000019,324.116943,false,Manual,2.8",
          GUID = "32153C82",
          NextDialogue = 20006014,
          SpeakNpcId = 200002,
          Subtitle = "Alright, alright, enough yipping. Just go! You might not be this lucky next time.",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153C82"
        },
        [20006014] = {
          Camera = "-615.953979,-649.889648,308.302246,0.000101,-13.6588,-149.769836,35.000023,174.116943,false,Manual,12.0",
          ContentFR = "Hmmm... je crois que ce Géniemon n’est pas très futé, on lui explique tout, et il ne veut quand même pas partir.",
          DialogueId = 20006014,
          FacialId = {
            [1] = "200002:Unhappy02"
          },
          FinalCamera = "-644.868896,-667.681641,299.754395,0.000098,-11.858697,-147.368286,35.000023,174.116943,false,Manual,12.0",
          GUID = "32153CAC",
          SpeakNpcId = 200002,
          Subtitle = "Hmm... I don't think this one is very bright. We explained everything, but it just won't leave.",
          TalkActionId = {
            [1] = "200002:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153CAC"
        },
        [20006015] = {
          ContentFR = "<I>clac—</>",
          DialogueId = 20006015,
          GUID = "32153CD6",
          Subtitle = "*clack*—",
          VoiceName = "voice/$Locale$/story/2001/200060/32153CD6"
        },
        [20006016] = {
          Camera = "-828.218018,-695.823242,274.558105,0.0,-10.196652,12.391548,11.88,174.116943,false,Manual,12.0",
          ContentFR = "Hein ? Il s’est recaché dans le piège ? Est-ce qu’il a tellement peur de nous qu’il croit être en sécurité là-dedans ?",
          DialogueId = 20006016,
          FinalCamera = "-812.047607,-692.268555,271.699219,0.0,-9.796662,12.39166,11.88,174.116943,false,Manual,12.0",
          GUID = "32153D00",
          NextDialogue = 20006017,
          SpeakNpcId = 200002,
          Subtitle = "Wait... Did it just slip back into the trap!? Is it so scared of us that it thinks the trap is safer?",
          TalkActionId = {
            [1] = "200002:SpecialConfident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D00"
        },
        [20006017] = {
          Camera = "-760.560303,-565.728516,290.460938,0.000099,-1.191192,-176.627136,35.000011,174.459366,false,Manual,2.8",
          ContentFR = "Non, ça ne colle pas. On l’a déjà sauvé, et on n’a montré aucune hostilité. Les Géniemons ne parlent pas, mais ils savent distinguer qui leur veut du bien et qui leur veut du mal.",
          DialogueId = 20006017,
          FacialId = {
            [1] = "200074:Sad01"
          },
          FinalCamera = "-784.401123,-567.131836,289.964355,0.000099,-1.191192,-176.427139,35.000011,138.232086,false,Manual,2.8",
          GUID = "32153D2A",
          NextDialogue = 20006018,
          SpeakNpcId = 200074,
          Subtitle = "That doesn't make sense... We rescued it, and we didn't do anything bad to it. Geniemons might not talk, but they can tell good from bad.",
          TalkActionId = {
            [1] = "200074:Think_Start",
            [2] = "200002:SpecialConfident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D2A"
        },
        [20006018] = {
          Camera = "-538.68689,-695.786133,229.021973,0.000027,5.603125,151.387604,35.000008,345.779022,false,Manual,12.0",
          ContentFR = "Hmm... Filbert a-t-elle déjà fait des choses que je ne comprenais pas, au début ?",
          DialogueId = 20006018,
          FinalCamera = "-556.785034,-685.914062,231.044922,0.000028,5.603125,151.387619,35.000008,278.757599,false,Manual,12.0",
          GUID = "32153D54",
          NextDialogue = 20006019,
          SpeakNpcId = 200074,
          Subtitle = "Hmm... let me think — has Filbert ever done something that didn't make sense to me at first...?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D54"
        },
        [20006019] = {
          Camera = "-152.133362,-1170.719727,714.169434,0.000035,-27.996868,146.383102,35.0,674.116943,false,Manual,22.0",
          ContentFR = "Une fois, elle a absolument voulu aller dans une vallée qui paraissait toute vide... et en fait, il y avait plein de baies cachées ! Une autre fois, elle est restée bloquée devant une boutique de fleurs, alors je lui en ai acheté une... et elle l’a engloutie d’un seul coup !",
          DialogueId = 20006019,
          FinalCamera = "-66.008728,-699.472656,615.159668,0.000042,-26.596804,175.382294,35.0,671.116943,false,Manual,22.0",
          GUID = "32153D7E",
          NextDialogue = 20006020,
          SpeakNpcId = 200074,
          Subtitle = "There was that one time she insisted on going into a valley that looked barren — turns out she'd sniffed out a hidden patch of berries deep inside. Then there was the time she wouldn't budge from a flower shop until I bought some flowers — just so she could eat them in one bite.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/2001/200060/32153D7E"
        },
        [20006020] = {
          ContentFR = "Et puis il y a eu la fois où elle m’a laissée pour filer en haut d’une colline, il y avait un serpent dans les herbes, et elle voulait l’éloigner.",
          DialogueId = 20006020,
          GUID = "32153DA8",
          NextDialogue = 20006021,
          SpeakNpcId = 200074,
          Subtitle = "And that other time, when she suddenly took off, sprinting straight up a hill without looking back at me for once. Then I realised there was a snake in the grass, and she was leading it away.",
          VoiceName = "voice/$Locale$/story/2001/200060/32153DA8"
        },
        [20006021] = {
          Camera = "-854.367188,-711.143555,293.184082,0.000106,-12.591494,30.173449,35.000008,1674.542114,false,Manual,8.0",
          ContentFR = "Hum... à chaque fois, c’était parce qu’elle avait senti quelque chose d’important... Qu’est-ce qui compte pour un Géniemon ? La nourriture... et les amis !",
          DialogueId = 20006021,
          FinalCamera = "-942.035889,-762.558594,315.785645,0.000113,-12.391452,31.173887,35.000008,1674.542114,false,Manual,8.0",
          GUID = "32153DD2",
          NextDialogue = 20006022,
          SpeakNpcId = 200074,
          Subtitle = "Every time she acted strange, it was because of something really important to her... What's important to a Geniemon? Food? And perhaps... their friends!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153DD2"
        },
        [20006022] = {
          Camera = "-800.104004,-669.561523,327.374512,0.000095,-2.797638,176.175522,35.000008,104.665184,false,Manual,12.0",
          ContentFR = "Les amis... je vois ! Si je ne me trompe pas, la cachette des chasseurs doit être dans les égouts.",
          DialogueId = 20006022,
          FacialId = {
            [1] = "100001:Satisfy01"
          },
          GUID = "32153DFC",
          NextDialogue = 20006023,
          Scripts = "SEQ{CameraMoveTo{_delay{6},TargetPosition{\"535.722229,-1070.53125,709.230469,0.000068,-6.997009,79.177307,35.0,174.116943,false,Manual,12.0\"},duration{0}},CameraMoveTo{_delay{0.5},TargetPosition{\"868.026001,153.00293,482.812988,0.000102,-2.791628,85.174393,35.000008,1674.542114,false,Manual,2.8\"},duration{5}}}",
          SpeakNpcId = 100001,
          Subtitle = "Friends... That's it! If I'm right, those Geniemon hunters must be hiding in the sewers.",
          TalkActionId = {
            [1] = "200074:Think_End",
            [2] = "100001:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153DFC"
        },
        [20006023] = {
          Camera = "-687.931763,-671.883789,322.655273,0.000069,-2.197053,176.775879,35.0,174.116943,false,Manual,12.0",
          ContentFR = "Ici, il sent l’odeur des autres Géniemon capturés, c’est pour ça qu’il refuse de s’éloigner.",
          DialogueId = 20006023,
          FacialId = {
            [1] = "100001:Confident02"
          },
          FinalCamera = "-771.952148,-667.40625,310.516113,0.000069,5.202958,177.175873,35.0,174.116943,false,Manual,12.0",
          GUID = "32153E26",
          NextDialogue = 20006024,
          SpeakNpcId = 100001,
          Subtitle = "This Geniemon can smell the scent of its captured friends from here — that's why it won't leave.",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153E26"
        },
        [20006024] = {
          Camera = "-821.866577,-728.666992,342.821289,0.000095,-11.597776,130.969742,35.000008,178.123947,false,Manual,2.8",
          ContentFR = "Très probable ! Alors on attend ici. Si les chasseurs viennent récupérer le Géniemon, on les suit et on leur donnera une bonne leçon !",
          DialogueId = 20006024,
          FacialId = {
            [1] = "200074:Confident01"
          },
          FinalCamera = "-828.375366,-721.172852,340.748047,0.000093,-11.797785,130.969742,35.000008,178.123947,false,Manual,2.8",
          GUID = "32153E50",
          NextDialogue = 20006025,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"200074:n(100001)"}},
LookAt{LookAtDescription{"100001:n(200074)"}},
PlayAnimation{ActorId{200074},AnimationId{"AgreeHead"},Duration{1}},
PlayAnimation{_delay{5},
ActorId{200074},AnimationId{"Angry01_Start"},Duration{2}}}]],
          SpeakNpcId = 200074,
          Subtitle = "That makes so much sense! In that case, we can wait right here. And as long as those bad hunters show up, we can follow them and teach them a good lesson!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153E50"
        },
        [20006025] = {
          Camera = "-788.137817,-637.754883,224.224121,0.000072,-2.597166,-0.625336,35.0,174.116943,false,Manual,12.0",
          ContentFR = "<I>Yiip—!</>",
          DialogueId = 20006025,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "-756.913574,-638.139648,223.32666,0.000072,-3.397097,-1.225342,35.0,174.116943,false,Manual,12.0",
          GUID = "32153E7A",
          NextDialogue = 20006026,
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_PanBeikun",
          Subtitle = "Yiip—!",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200060/32153E7A"
        },
        [20006026] = {
          Camera = "-412.370728,-629.598633,225.119141,0.000073,3.802544,-175.221069,28.0,265.494751,false,Manual,12.0",
          ContentFR = "Hmm, alors ce Géniemon est intelligent ou stupide ? Car il a l’intelligence de vouloir qu’on sauve ses amis, mais il vient aussi de retourner dans un piège...",
          DialogueId = 20006026,
          FinalCamera = "-412.370728,-629.598633,241.541992,0.000073,0.002452,-175.420853,28.0,265.494751,false,Manual,12.0",
          GUID = "32153EA4",
          LookAt = {
            [1] = "200002:n(700251)"
          },
          NextDialogue = 20006027,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"200074:n(200074)"}},
LookAt{LookAtDescription{"100001:n(100001)"}},
PlayAnimation{ActorId{200074},AnimationId{"Angry01_End"},Duration{1}}
}]],
          SpeakNpcId = 200002,
          Subtitle = "So, is this Geniemon smart or dumb? I mean, it's got the brains to want us to save its friends, but it also just walked right back into a trap...",
          TalkActionId = {
            [1] = "200002:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153EA4"
        },
        [20006027] = {
          Camera = "-700.815918,-705.999023,263.483887,0.000069,3.402636,153.177032,35.0,174.116943,false,Manual,12.0",
          ContentFR = "Peut-être qu’il est revenu exprès dans le piège pour qu’on puisse le suivre jusqu’au repaire des chasseurs.",
          DialogueId = 20006027,
          FinalCamera = "-755.168457,-688.192383,266.806152,0.000068,3.602624,148.576843,35.0,174.116943,false,Manual,12.0",
          GUID = "32153ECE",
          NextDialogue = 20006028,
          SpeakNpcId = 200074,
          Subtitle = "Maybe it did that on purpose? That way we can just follow the bad guys who come to collect the trapped Geniemon to their hideout.",
          TalkActionId = {
            [1] = "200074:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153ECE"
        },
        [20006028] = {
          Camera = "-486.203613,-623.530273,240.246582,0.000087,2.002625,-162.023193,35.0,174.116943,false,Manual,12.0",
          ContentFR = "Oh, vraiment ? C’est—",
          DialogueId = 20006028,
          FacialId = {
            [1] = "200002:Shock02"
          },
          FinalCamera = "-531.324463,-638.469727,243.410156,0.000087,4.602584,-160.822952,35.0,174.116943,false,Manual,12.0",
          GUID = "32153EF8",
          NextDialogue = 20006029,
          SpeakNpcId = 200002,
          Subtitle = "Oh, really? That's—",
          TalkActionId = {
            [1] = "200074:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153EF8"
        },
        [20006029] = {
          ContentFR = "Hé ? Pas mal, on en a attrapé un autre.",
          DialogueId = 20006029,
          GUID = "32153F22",
          NextDialogue = 20006030,
          SpeakNpcId = 200075,
          Subtitle = "Oh? Not bad. Looks like we caught another one.",
          VoiceName = "voice/$Locale$/story/2001/200060/32153F22"
        },
        [20006030] = {
          Camera = "-647.833496,-724.029297,337.969727,0.000094,-6.997679,159.175262,35.0,324.116943,false,Manual,12.0",
          ContentFR = "Ce sont les chasseurs de Géniemon. Cachez-vous !",
          DialogueId = 20006030,
          GUID = "32153F4C",
          NextDialogue = 20006031,
          SpeakNpcId = 100001,
          Subtitle = "It's the Geniemon hunters! Quick, hide!",
          TurnTo = {
            [1] = "100001:n(200074)",
            [2] = "200074:n(100001)"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32153F4C"
        },
        [20006031] = {
          ContentFR = "D’accord !",
          DialogueId = 20006031,
          GUID = "32153F76",
          SpeakNpcId = 200074,
          Subtitle = "Got it!",
          VoiceName = "voice/$Locale$/story/2001/200060/32153F76"
        },
        [20006032] = {
          Camera = "-593.543457,-336.325195,269.372559,0.000176,-9.390683,-128.619858,35.000008,268.984894,false,Manual,12.0",
          ContentFR = "J’ai bien envie de leur casser la figure tout de suite, mais bon, on gardera ça pour plus tard !",
          DialogueId = 20006032,
          FacialId = {
            [1] = "200002:Angry01"
          },
          FinalCamera = "-632.141357,-384.262695,260.398438,0.000174,-8.190715,-130.618393,35.000008,268.984894,false,Manual,12.0",
          GUID = "32153FA0",
          NextDialogue = 20006033,
          SpeakNpcId = 200002,
          Subtitle = "Ugh, I really want to punch 'em... Let's just take notes for now and settle the score with them later!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153FA0"
        },
        [20006033] = {
          Camera = "-1663.477051,-843.626953,503.279785,0.000179,-12.99065,25.976145,35.0,1674.542114,false,Manual,2.8",
          ContentFR = "Je pensais que nous avions déjà capturé tous les Géniemon de Givrelac, mais il semble que nous en ayons attrapé un autre...",
          DialogueId = 20006033,
          GUID = "32153FCA",
          NextDialogue = 20006034,
          SpeakNpcId = 200075,
          Subtitle = "I thought we'd already captured all the Geniemons in Icelake, but looks like we scored another one.",
          VoiceName = "voice/$Locale$/story/2001/200060/32153FCA"
        },
        [20006034] = {
          Camera = "-468.823608,196.549805,329.405273,0.000182,-6.590613,-5.024419,35.000008,1033.678345,false,Manual,22.0",
          ContentFR = "Nous devons encore sortir de la cité, c’est là qu’on en attrape le plus. Mais cette gamine qui monte sur son cochon, quand est-ce qu’elle va enfin bouger ?",
          DialogueId = 20006034,
          FinalCamera = "-443.855225,194.355469,326.509277,0.000182,-6.590613,-5.024419,35.000008,1033.678345,false,Manual,22.0",
          GUID = "32153FF4",
          NextDialogue = 20006035,
          SpeakNpcId = 200087,
          Subtitle = "We still need to head out of the city — that's where the real haul is. But that pig-riding brat is always out there messing with us.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200060/32153FF4"
        },
        [20006035] = {
          ContentFR = "T’inquiète pas, elle partira. Elle ne va pas pouvoir rester bien longtemps devant la cité.",
          DialogueId = 20006035,
          GUID = "3215401E",
          NextDialogue = 20006036,
          SpeakNpcId = 200075,
          Subtitle = "Don't worry, she'll leave. No way she's gonna camp out there forever.",
          TalkActionId = {
            [1] = "200075:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/3215401E"
        },
        [20006036] = {
          ContentFR = "Ouais, avec le froid et les Souillés, elle risque de bien vite rentrer en pleurant.",
          DialogueId = 20006036,
          GUID = "32154048",
          NextDialogue = 20006037,
          SpeakNpcId = 200087,
          Subtitle = "Right. With the cold and the Filthoids, I'd bet she'll be crying her way home in a day or two.",
          TalkActionId = {
            [1] = "200075:Talk02_End",
            [2] = "200087:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32154048"
        },
        [20006037] = {
          ContentFR = "Tant mieux !",
          DialogueId = 20006037,
          GUID = "32154072",
          SpeakNpcId = 200075,
          Subtitle = "Yeah! She better be!",
          TalkActionId = {
            [1] = "200075:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200060/32154072"
        },
        [20006101] = {
          Camera = "-1302.360229,-832.505859,345.045898,0.000178,-0.789761,21.978495,35.0,1674.542114,false,Manual,2.8",
          ContentFR = "Ils retournent dans les égouts ! Allez, on les suit vite !",
          DialogueId = 20006101,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "32154AF2",
          NextDialogue = 20006102,
          Scripts = "PARA{SEQ{TurnTo{TurnToDescription{\"200002:n(100001)\"}},PlayAnimation{_delay{0.1},ActorId{200002},AnimationId{\"Confident_Start\"},Duration{1}}},CameraMoveTo{_delay{2},TargetPosition{\"-840.86145,-688.524414,290.947754,0.000184,-10.389148,-19.824919,35.000008,95.310921,false,Manual,2.8\"},duration{0}}}",
          SpeakNpcId = 200002,
          Subtitle = "They're slipping back into the sewers! Come on, let's go!",
          VoiceName = "voice/$Locale$/story/2001/200061/32154AF2"
        },
        [20006102] = {
          Camera = "-691.08667,-817.638672,263.54541,0.000229,8.209702,133.76033,35.000011,242.476578,false,Manual,2.8",
          ContentFR = "Chut, parle moins fort. Si nous nous faisons repérer, ce Géniemon que nous venons de sauver te traitera sûrement d’idiote.",
          DialogueId = 20006102,
          FinalCamera = "-710.927734,-796.919922,267.683105,0.000229,8.209702,133.76033,35.000011,242.476578,false,Manual,2.8",
          GUID = "32154B1C",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          NextDialogue = 20006103,
          Scripts = "LookAt{LookAtDescription{\"200074:n(200002)\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Shh, keep it down. If we give ourselves away, that Geniemon we just saved would probably call you an idiot in its Geniemon language.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200061/32154B1C"
        },
        [20006103] = {
          Camera = "-840.86145,-688.524414,290.947754,0.000184,-10.389148,-19.824919,35.000008,95.310921,false,Manual,2.8",
          ContentFR = "Hmpf, impossible ! J’ai été si gentille avec lui que je lui ai laissé une impression divine.",
          DialogueId = 20006103,
          FacialId = {
            [1] = "200002:Confident01"
          },
          GUID = "32154B46",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20006104,
          SpeakNpcId = 200002,
          Subtitle = "Hmph! No way. I was so nice to it — I must have made a good impression.",
          VoiceName = "voice/$Locale$/story/2001/200061/32154B46"
        },
        [20006104] = {
          Camera = "-832.142822,-728.967773,342.387207,0.000241,-11.390535,127.158501,35.000011,192.086792,false,Manual,2.8",
          ContentFR = "Haha... vous deux... Même si je suis petite, j’ai beaucoup voyagé avec Filbert et j’ai rencontré plein de gens, mais peu se soucient vraiment de ce que ressentent les Géniemon.",
          DialogueId = 20006104,
          FinalCamera = "-837.814453,-721.487305,340.496582,0.000241,-11.390535,127.158501,35.000011,192.086792,false,Manual,2.8",
          GUID = "32154B70",
          LookAt = {
            [1] = "100001:n(200074)"
          },
          NextDialogue = 20006105,
          SpeakNpcId = 200074,
          Subtitle = "Haha... You two really are something. I've met plenty of people travelling with Filbert, but few people genuinely care about what Geniemons think.",
          TalkActionId = {
            [1] = "200074:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200061/32154B70"
        },
        [20006105] = {
          ContentFR = "Si tout le monde pensait comme vous, que les Géniemon ont leurs propres pensées et sentiments, il n’y aurait pas de chasseurs de Géniemon.",
          DialogueId = 20006105,
          GUID = "32154B9A",
          NextDialogue = 20006106,
          SpeakNpcId = 200074,
          Subtitle = "If more people understood that Geniemons have their own thoughts and feelings, just like you do, we wouldn't have Geniemon hunters in the first place!",
          TalkActionId = {
            [1] = "200074:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200061/32154B9A"
        },
        [20006106] = {
          Camera = "-809.379883,-578.354492,277.954102,0.000212,5.809533,178.160782,35.000011,115.034302,false,Manual,2.8",
          ContentFR = "Allez, on y va ! Cette fois, je leur ferai comprendre leur erreur !",
          DialogueId = 20006106,
          FinalCamera = "-822.223877,-577.945312,279.260742,0.000213,5.809533,178.160782,35.000011,110.479393,false,Manual,2.8",
          GUID = "32154BC4",
          LookAt = {
            [1] = "200074:n(200074)"
          },
          SpeakNpcId = 200074,
          Subtitle = "Let's go. This time, I'll make sure they learn their lesson once and for all!",
          TalkActionId = {
            [1] = "200074:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200061/32154BC4"
        },
        [20006201] = {
          Camera = "-287.4375,38.861328,166.546265,0.000031,-8.400183,-1.804748,18.000004,100000.0,false,Manual,2.8",
          ContentFR = "Oh, les égouts sont vraiment compliqués. Filbert, tu sens quelque chose ?",
          DialogueId = 20006201,
          GUID = "32155B5A",
          NextDialogue = 20006202,
          SpeakNpcId = 200074,
          Subtitle = "I didn't realise there would be so many tunnels in the sewers... Filbert, can you pick up a Geniemon's scent?",
          VoiceName = "voice/$Locale$/story/2001/200062/32155B5A"
        },
        [20006202] = {
          ContentFR = "<I>Groin...</>",
          DialogueId = 20006202,
          GUID = "32155B84",
          NextDialogue = 20006203,
          SpeakNpcId = 200086,
          Subtitle = "Oink...",
          VoiceName = "voice/$Locale$/story/2001/200062/32155B84"
        },
        [20006203] = {
          ContentFR = "Il y a tellement d’odeurs mélangées qu’on n’arrive pas à s’orienter. Bon, avançons quand même.",
          DialogueId = 20006203,
          GUID = "32155BAE",
          NextDialogue = 20006204,
          SpeakNpcId = 200074,
          Subtitle = "Too many overlapping smells? Hmm... Let's just keep moving then.",
          VoiceName = "voice/$Locale$/story/2001/200062/32155BAE"
        },
        [20006204] = {
          ContentFR = "Suivez-moi, je connais bien ce terrain.",
          DialogueId = 20006204,
          GUID = "32155BD8",
          NextDialogue = 20006205,
          SpeakNpcId = 200002,
          Subtitle = "Just follow me. I know my way around here.",
          VoiceName = "voice/$Locale$/story/2001/200062/32155BD8"
        },
        [20006205] = {
          ContentFR = "Hein ? Tu habites dans des endroits comme ça, Snow ?",
          DialogueId = 20006205,
          GUID = "32155C02",
          NextDialogue = 20006206,
          SpeakNpcId = 200074,
          Subtitle = "Huh? Why? Is this where you live?",
          VoiceName = "voice/$Locale$/story/2001/200062/32155C02"
        },
        [20006206] = {
          ContentFR = "B-Bien sûr que non. Mais en tant que Roi Démon, j’ai déjà inspecté ces tunnels plusieurs fois. Suis-moi, Chasseuse de Chasseurs de Géniemon venue de loin !",
          DialogueId = 20006206,
          GUID = "32155C2C",
          NextDialogue = 20006207,
          SpeakNpcId = 200002,
          Subtitle = "O...Of course not. But as the great Demon King, I've inspected these tunnels many times. Now, keep up, foreign Geniemon Hunter Hunter!",
          VoiceName = "voice/$Locale$/story/2001/200062/32155C2C"
        },
        [20006207] = {
          ContentFR = "D’accord !",
          DialogueId = 20006207,
          GUID = "32155C56",
          SpeakNpcId = 200074,
          Subtitle = "Okay~",
          VoiceName = "voice/$Locale$/story/2001/200062/32155C56"
        },
        [20006301] = {
          ContentFR = "Ah, cette marque, je ne l’avais pas vue lors de mes précédentes patrouilles.",
          DialogueId = 20006301,
          GUID = "32156BC2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 20006302,
          SpeakNpcId = 200002,
          Subtitle = "Ah, this mark wasn't here last time I checked.",
          VoiceName = "voice/$Locale$/story/2001/200063/32156BC2"
        },
        [20006302] = {
          ContentFR = "On dirait la trace laissée par le Géniemon qu’on a sauvé. Suivons-la.",
          DialogueId = 20006302,
          GUID = "32156BEC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          Subtitle = "Looks like something the Geniemon we just saved might have left behind. Let's follow it.",
          VoiceName = "voice/$Locale$/story/2001/200063/32156BEC"
        },
        [20006401] = {
          ContentFR = "Les traces sont de plus en plus fraîches, on doit être proches...",
          DialogueId = 20006401,
          GUID = "32157C2A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20006402,
          SpeakNpcId = 200074,
          Subtitle = "The marks are getting fresher... It shouldn't be far.",
          VoiceName = "voice/$Locale$/story/2001/200064/32157C2A"
        },
        [20006402] = {
          ContentFR = "J’entends des voix—",
          DialogueId = 20006402,
          GUID = "32157C54",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Wait— I think I hear voices...",
          VoiceName = "voice/$Locale$/story/2001/200064/32157C54"
        }
      }
    end
  },
  {
    MinKey = 20006501,
    MaxKey = 50103601,
    Loader = function()
      return {
        [20006501] = {
          Camera = "802.462891,37.094727,399.100616,0.000002,-18.600189,1.600099,35.000011,403.34671,false,Manual,12.0",
          ContentFR = "On a touché le gros lot, tu sais, celui-ci est spécial ! C’est le Paniemon, ils disent que c’est le plus intelligent, le plus rare et la forme originale de tous les Géniemon.",
          DialogueId = 20006501,
          FinalCamera = "559.453125,30.306641,481.861816,0.000002,-18.800184,1.600099,35.000011,403.34671,false,Manual,12.0",
          GUID = "32158C92",
          NextDialogue = 20006502,
          SpeakNpcId = 200075,
          Subtitle = "We hit the jackpot, you know — this one's special! It's called Paniemon, and they say it's the smartest, rarest, and the original form of all Geniemon.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200065/32158C92"
        },
        [20006502] = {
          ContentFR = "Le plus intelligent ? Sérieux ? S’il est si malin, comment a-t’il pu finir dans notre piège ?",
          DialogueId = 20006502,
          GUID = "32158CBC",
          NextDialogue = 20006503,
          SpeakNpcId = 200087,
          Subtitle = "The smartest? Seriously? If it's so smart, how'd it end up in our trap?",
          TalkActionId = {
            [1] = "200087:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158CBC"
        },
        [20006503] = {
          Camera = "565.943359,-554.305664,435.741028,0.000025,-6.400112,56.795567,35.000008,100000.0,false,Manual,22.0",
          ContentFR = "Qu’est-ce que tu insinues ? Tu veux dire qu’on est trop stupides pour attraper le plus malin des Géniemon ?",
          DialogueId = 20006503,
          FinalCamera = "586.517578,-522.865234,431.526306,0.000026,-6.400112,56.795399,35.000008,100000.0,false,Manual,22.0",
          GUID = "32158CE6",
          LookAt = {
            [1] = "200075:n(200087)"
          },
          NextDialogue = 20006504,
          SpeakNpcId = 200075,
          Subtitle = "What do you mean? Are you saying we're too dumb to catch the smartest Geniemon?",
          TalkActionId = {
            [1] = "200075:Talk03_Start",
            [2] = "200087:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200065/32158CE6"
        },
        [20006504] = {
          Camera = "485.179688,62.989258,489.663513,0.000012,-12.999386,-2.199652,35.000008,450.0,false,Manual,6.0",
          ContentFR = "N-Non, je ne voulais pas dire ça. Patron, t’es un génie ! Sans tes pièges, on n’en aurait jamais capturé autant.",
          DialogueId = 20006504,
          FinalCamera = "610.728516,58.283203,460.538757,0.000012,-13.199401,-1.999653,35.000008,450.0,false,Manual,6.0",
          GUID = "32158D10",
          LookAt = {
            [1] = "200087:n(200075)"
          },
          NextDialogue = 20006505,
          SpeakNpcId = 200087,
          Subtitle = "O...Of course not, Boss! You're a genius! If it weren't for your traps, we wouldn't have caught half as many.",
          TalkActionId = {
            [1] = "200087:Shock_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/2001/200065/32158D10"
        },
        [20006505] = {
          ContentFR = "Exactement. Avec tout ce qu’on a rassemblé, on finira par percer la méthode d’extraction du Phoxène. J’en ferai une thèse.",
          DialogueId = 20006505,
          GUID = "32158D3A",
          LookAt = {
            [1] = "200075:n(200075)"
          },
          NextDialogue = 20006506,
          SpeakNpcId = 200075,
          Subtitle = "It's true. Now, with all the Geniemons we've rounded up, it's only a matter of time before I crack the secret to extracting Phoxene from them. And once I finish my thesis on it...",
          TalkActionId = {
            [1] = "200087:Shock_End",
            [2] = "200075:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158D3A"
        },
        [20006506] = {
          ContentFR = "Ensuite, qui osera encore se moquer de moi pour avoir abandonné l’Académie d’Alchimie ?",
          DialogueId = 20006506,
          GUID = "32158D64",
          NextDialogue = 20006507,
          SpeakNpcId = 200075,
          Subtitle = "I'd like to see who dares laugh at me for dropping out of the Alchemy Academy again!",
          TalkActionId = {
            [1] = "200075:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158D64"
        },
        [20006507] = {
          ContentFR = "Patron, je me fiche de toutes ces histoires de thèse. Je veux juste avoir ma part des pièces d’argent.",
          DialogueId = 20006507,
          GUID = "32158D8E",
          NextDialogue = 20006508,
          SpeakNpcId = 200087,
          Subtitle = "Boss, I don't care much about all that thesis stuff. I just want to get my share of the silver coins.",
          TalkActionId = {
            [1] = "200075:Angry01_End",
            [2] = "200087:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158D8E"
        },
        [20006508] = {
          ContentFR = "Bien sûr, ne t’inquiète pas.",
          DialogueId = 20006508,
          GUID = "32158DB8",
          LookAt = {
            [1] = "200087:n(200087)"
          },
          NextDialogue = 20006509,
          SpeakNpcId = 200075,
          Subtitle = "Sure, easy.",
          TalkActionId = {
            [1] = "200087:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158DB8"
        },
        [20006509] = {
          Camera = "0.919922,-0.328125,154.78241,0.000047,-0.999783,-169.994827,35.000008,147.718536,false,Manual,8.0",
          ContentFR = "Cela ne sera pas aussi simple.",
          DialogueId = 20006509,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "32158DE2",
          NextDialogue = 20006510,
          SpeakNpcId = 100001,
          Subtitle = "It won't be that easy from now on.",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158DE2"
        },
        [20006510] = {
          Camera = "460.484375,70.31543,355.815216,0.000048,1.599391,-2.995058,35.000008,300.0,false,Manual,8.0",
          ContentFR = "Vous êtes qui, vous... ?",
          DialogueId = 20006510,
          FinalCamera = "525.451172,67.851562,357.435608,0.000048,1.39939,-2.39505,35.000008,300.0,false,Manual,8.0",
          GUID = "32158E0C",
          NextDialogue = 20006511,
          Scripts = "PARA{TurnTo{TurnToDescription{\"200075:p(-150)\"}},TurnTo{TurnToDescription{\"200087:p(150)\"}}}",
          SpeakNpcId = 200075,
          Subtitle = "Who are you...?",
          TalkActionId = {
            [1] = "100001:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200065/32158E0C"
        },
        [20006511] = {
          Camera = "47.310547,-89.34375,82.346375,0.000071,6.199694,-170.591293,35.000011,184.872482,false,Manual,8.0",
          ContentFR = "Je suis le Rédempteur Immaculé ☆ Roi Démon de la Lumière !",
          DialogueId = 20006511,
          FacialId = {
            [1] = "200002:Confident01"
          },
          FinalCamera = "33.654297,-91.604492,83.850006,0.000072,8.199676,-167.790817,35.000011,131.269821,false,Manual,8.0",
          GUID = "32158E36",
          NextDialogue = 20006512,
          SpeakNpcId = 200002,
          Subtitle = "I am the Pure-White Redeemer ☆ Demon King of Light!",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200065/32158E36"
        },
        [20006512] = {
          Camera = "13.498047,83.051758,121.173889,0.000102,-0.000096,-173.797699,35.000008,145.105087,false,Manual,8.0",
          ContentFR = "Je... je suis la Chasseuse de Chasseurs de Géniemon, Commissaire au Ravitaillement Truffle ! Et Filbert, Commissaire d’élite au Ravitaillement !",
          DialogueId = 20006512,
          FinalCamera = "2.105469,81.813477,121.173889,0.000102,-0.000096,-173.797699,35.000008,145.105087,false,Manual,8.0",
          GUID = "32158E60",
          NextDialogue = 20006513,
          Scripts = [[
PARA{
CameraMoveTo{_delay{6.01},TargetPosition{"150.591797,30.707031,123.61908,0.000102,-6.400208,141.202621,35.0,300.0,false,Manual,8.0"},duration{0}},
SEQ{
PlayFacial{_delay{3.5},ActorId{200074},FacialId{"Confident01"}},
PlayAnimation{_delay{3.1},ActorId{200074},AnimationId{"Confident_Start"}}
}
}]],
          SpeakNpcId = 200074,
          Subtitle = "I... I am the Geniemon Hunter Hunter, Commissary Truffle! And Filbert, the Special Commissary!",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200065/32158E60"
        },
        [20006513] = {
          Camera = "150.591797,30.707031,123.61908,0.000102,-6.400208,141.202621,35.0,300.0,false,Manual,8.0",
          ContentFR = "<I>Groin, groin !</>",
          DialogueId = 20006513,
          FinalCamera = "134.871094,118.75,17.023186,0.000235,24.799322,157.617859,35.0,628.586243,false,Manual,12.0",
          GUID = "32158E8A",
          NextDialogue = 200065130,
          SpeakNpcId = 200086,
          Subtitle = "Oink, oink!",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/2001/200065/32158E8A"
        },
        [20006514] = {
          Camera = "292.925781,74.748047,369.465027,0.000041,-0.400365,-1.603272,35.000008,300.0,false,Manual,16.0",
          ContentFR = "Je vois, vous êtes des comédiens du Théâtre Galea.",
          DialogueId = 20006514,
          GUID = "32158EB4",
          NextDialogue = 20006515,
          SpeakNpcId = 200075,
          Subtitle = "Oh, I get it. You're performers from the Galea Theatre.",
          TalkActionId = {
            [1] = "200075:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158EB4"
        },
        [20006515] = {
          Camera = "-26.337891,71.758789,115.010025,0.000102,5.001563,-179.000427,35.000019,100.535843,false,Manual,8.0",
          ContentFR = "Non... pas du tout ! Relâchez ces Géniemon ! Sinon, Filbert va vous envoyer valser !",
          DialogueId = 20006515,
          GUID = "32158EDE",
          Scripts = [[
SEQ{
PlayFacial{_delay{0.1},ActorId{200074},FacialId{"Unacceptable01"}},
PlayFacial{_delay{0.6},ActorId{200074},FacialId{"Smile02"}}
}]],
          SpeakNpcId = 200074,
          Subtitle = "That's not it...! Let the Geniemons go, or Filbert will knock you flying!",
          TalkActionId = {
            [1] = "200074:Confident_End",
            [2] = "200074:Disagree"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158EDE"
        },
        [20006516] = {
          Camera = "292.925781,74.748047,369.465027,0.000041,-0.400365,-1.603272,35.000008,300.0,false,Manual,8.0",
          ContentFR = "Ce n’était pas vous, avec ce... Roi Démon de je-ne-sais-quoi, qui avez fichu en l’air nos plans hors de la cité ?",
          DialogueId = 20006516,
          GUID = "32158F08",
          NextDialogue = 20006517,
          SpeakNpcId = 200075,
          Subtitle = "Wasn't it you and that Demon King of something or other who ruined our hunt outside the city?",
          TalkActionId = {
            [1] = "200075:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158F08"
        },
        [20006517] = {
          Camera = "-27.242188,73.443359,154.929871,0.00007,-15.000351,-177.200226,35.000015,130.614029,false,Manual,8.0",
          ContentFR = "C’est le Grand Roi Démon de la Lumière ! C’est malpoli de ne pas retenir un nom ! Filbert va te faire retenir la leçon !",
          DialogueId = 20006517,
          FacialId = {
            [1] = "200074:Confident02"
          },
          GUID = "32158F32",
          LookAt = {
            [1] = "200074:n(200075)"
          },
          SpeakNpcId = 200074,
          Subtitle = "It's the Demon King of Light! It's very rude to get someone's name wrong! You'll get rammed by Filbert for that!",
          VoiceName = "voice/$Locale$/story/2001/200065/32158F32"
        },
        [20006518] = {
          Camera = "292.925781,74.748047,369.465027,0.000041,-0.400365,-1.603272,35.000008,300.0,false,Manual,8.0",
          ContentFR = "Dans tes rêves !",
          DialogueId = 20006518,
          GUID = "32158F5C",
          NextDialogue = 20006519,
          SpeakNpcId = 200075,
          Subtitle = "In — your— dreams!",
          TalkActionId = {
            [1] = "200075:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158F5C"
        },
        [20006519] = {
          Camera = "9.128906,71.000977,164.786407,0.000102,-18.198389,-178.600586,35.000008,450.0,false,Manual,6.0",
          ContentFR = "Si c’est comme ça... Filbert, fonce !",
          DialogueId = 20006519,
          FinalCamera = "-9.466797,68.333008,115.745117,0.000102,3.801383,-177.600464,35.000011,131.004227,false,Manual,6.0",
          GUID = "32158F86",
          LookAt = {
            [1] = "200074:n(200075)"
          },
          Scripts = [[
SEQ{
PlayFacial{_delay{0.1},ActorId{200074},FacialId{"Confident02"}},
PlayFacial{_delay{1.6},ActorId{200074},FacialId{"Doubt01"}}
}]],
          SpeakNpcId = 200074,
          Subtitle = "If that's how you want it... Filbert, charge!",
          TalkActionId = {
            [1] = "200074:Confident_End",
            [2] = "200074:Think_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/2001/200065/32158F86"
        },
        [20006601] = {
          ContentFR = "Pff, et puis quoi encore ? Vous croyez que j’ai peur d’une bande de gamins et de leur tas de lard ambulant ?",
          DialogueId = 20006601,
          GUID = "32159CFA",
          NextDialogue = 20006602,
          SpeakNpcId = 200087,
          Subtitle = "Pfft, what's the holdup? You think I'd be scared of a few kids and their walking pile of bacon?",
          VoiceName = "voice/$Locale$/story/2001/200066/32159CFA"
        },
        [20006602] = {
          ContentFR = "On n’insulte pas Filbert comme ça ! Excuse-toi auprès d’elle, tout de suite !",
          DialogueId = 20006602,
          GUID = "32159D24",
          NextDialogue = 20006603,
          SpeakNpcId = 200074,
          Subtitle = "You take that back! Apologize to Filbert now!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159D24"
        },
        [20006603] = {
          ContentFR = "Faut déjà réussir à me battre !",
          DialogueId = 20006603,
          GUID = "32159D4E",
          SpeakNpcId = 200087,
          Subtitle = "Oh yeah? Make me!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159D4E"
        },
        [20006604] = {
          ContentFR = "<I>Yiip— !</>",
          DialogueId = 20006604,
          GUID = "32159D78",
          NextDialogue = 20006605,
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_Pan_Common",
          Subtitle = "Yip—!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159D78"
        },
        [20006605] = {
          ContentFR = "P-Patron ! Ce Géniemon... il a libéré tous les autres !",
          DialogueId = 20006605,
          GUID = "32159DA2",
          NextDialogue = 20006606,
          SpeakNpcId = 200075,
          Subtitle = "B—Boss! That Geniemon — it released all the other ones!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159DA2"
        },
        [20006606] = {
          ContentFR = "Piou— !",
          DialogueId = 20006606,
          GUID = "32159DCC",
          NextDialogue = 20006607,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Chirp—!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159DCC"
        },
        [20006607] = {
          ContentFR = "Bêê— !",
          DialogueId = 20006607,
          GUID = "32159DF6",
          NextDialogue = 20006608,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Baa—!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159DF6"
        },
        [20006608] = {
          ContentFR = "Ploc— !",
          DialogueId = 20006608,
          GUID = "32159E20",
          NextDialogue = 20006609,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ding-dong—!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159E20"
        },
        [20006609] = {
          ContentFR = "Aïe, c’est brûlant ! Ouille ça pique ! J’ai froid, trop froid !",
          DialogueId = 20006609,
          GUID = "32159E4A",
          NextDialogue = 20006610,
          SpeakNpcId = 200087,
          Subtitle = "Aghhh—! Too hot— Too tingly— No, too cold—!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159E4A"
        },
        [20006610] = {
          ContentFR = "Je me rends ! Pitié !",
          DialogueId = 20006610,
          GUID = "32159E74",
          SpeakNpcId = 200087,
          Subtitle = "I'm sorry! I SURRENDER! PLEASE!",
          VoiceName = "voice/$Locale$/story/2001/200066/32159E74"
        },
        [20006701] = {
          Camera = "-939.216797,26.854492,320.087097,0.0,-13.407927,0.807412,35.000008,450.0,false,Manual,6.0",
          ContentFR = "{性别:Seigneur|Dame} {nickname}, ô Grande Chasseuse de Chasseurs de Géniemon, et Ô Grand Roi Démon de la Lumière, pardonnez-nous ! On a eu tort ! On renonce à tous ces Géniemon, épargnez-nous !",
          DialogueId = 20006701,
          GUID = "3215AD62",
          NextDialogue = 20006702,
          SpeakNpcId = 200087,
          Subtitle = "Lord , Great Geniemon Hunter Hunter, and mighty Demon King of Light — have mercy! We're sorry! We'll leave the Geniemons alone!",
          TalkActionId = {
            [1] = "200075:Avoid",
            [2] = "200087:Avoid"
          },
          VoiceName = "voice/$Locale$/story/2001/200067/3215AD62"
        },
        [20006702] = {
          ContentFR = "Hé, pas besoin d’être aussi paniqués. Si vous promettez de ne plus jamais attraper de Géniemon, Filbert et moi ne vous ferons rien.",
          DialogueId = 20006702,
          GUID = "3215AD8C",
          NextDialogue = 20006703,
          SpeakNpcId = 200074,
          Subtitle = "Well, no need to be so terrified. As long as you promise you'll never lay a hand on Geniemons again, Filbert and I won't hurt you.",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AD8C"
        },
        [20006703] = {
          ContentFR = "Oui, oui, promis !",
          DialogueId = 20006703,
          GUID = "3215ADB6",
          NextDialogue = 20006704,
          SpeakNpcId = 200075,
          Subtitle = "I promise... I swear...",
          VoiceName = "voice/$Locale$/story/2001/200067/3215ADB6"
        },
        [20006704] = {
          ContentFR = "Moi aussi, je promets de ne plus attraper de Géniemon ! Et je surveillerai le patron, si jamais il recommence, je vous le dirai en premier !",
          DialogueId = 20006704,
          GUID = "3215ADE0",
          NextDialogue = 20006705,
          SpeakNpcId = 200087,
          Subtitle = "Same here! And I'll keep an eye on Boss — if he so much as thinks about catching another Geniemon, I'll turn him in myself!",
          VoiceName = "voice/$Locale$/story/2001/200067/3215ADE0"
        },
        [20006705] = {
          ContentFR = "Bien. Alors vous devez aussi aller leur présenter des excuses.",
          DialogueId = 20006705,
          GUID = "3215AE0A",
          NextDialogue = 20006706,
          SpeakNpcId = 200074,
          Subtitle = "Alright, then. But you also owe them an apology.",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AE0A"
        },
        [20006706] = {
          ContentFR = "Je suis profondément désolé ! L’avidité m’a aveuglé... Je voulais étudier les Géniemon, mais je n’arrivais pas à rédiger de thèse, alors j’ai pris le mauvais chemin... Allez-y ! Vengez-vous ! Chassez-moi comme je vous ai chassés...",
          DialogueId = 20006706,
          GUID = "3215AE34",
          NextDialogue = 20006708,
          SpeakNpcId = 200075,
          Subtitle = "I—I'm truly sorry! I let greed get the best of me. I wanted to study Geniemons, but I couldn't even write a proper research paper, that's why I turned to this... Go ahead. Take your revenge — hunt me like how I did to you...",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AE34"
        },
        [20006707] = {
          ContentFR = "J’ai été idiot d’avoir douté de la sagesse du Seigneur Paniemon. Le Seigneur Paniemon est plus intelligent que moi... même plus que mon patron ! Dès aujourd’hui, je jure allégeance à vous, Seigneur Paniemon !",
          DialogueId = 20006707,
          GUID = "3215AE5E",
          SpeakNpcId = 200087,
          Subtitle = "I was such a fool to question Lord Paniemon's intelligence — Lord Paniemon is smarter than me... smarter than my boss even! From today onward, I pledge my loyalty to you, Lord Paniemon!",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AE5E"
        },
        [20006708] = {
          ContentFR = "<I>Yiip !</>",
          DialogueId = 20006708,
          GUID = "3215AE88",
          NextDialogue = 20006709,
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_Pan_Common",
          Subtitle = "Yip.",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AE88"
        },
        [20006709] = {
          Camera = "35.800781,50.916992,117.894058,0.000003,-4.407924,143.206772,35.000011,450.0,false,Manual,6.0",
          ContentFR = "Hum... vous avez l’air sincères, on va vous croire pour l’instant. Alors, {性别:Monsieur|Mademoiselle}, Snow, que fait-on de tous ces Géniemon ?",
          DialogueId = 20006709,
          FinalCamera = "140.537109,-26.151367,129.112198,0.000003,-5.407959,144.206726,35.000011,450.0,false,Manual,6.0",
          GUID = "3215AEB2",
          NextDialogue = 20006710,
          SpeakNpcId = 200074,
          Subtitle = "Well, you do seem genuinely sorry. We'll believe you for now. Alright, {性别:Sir|Miss}, Snow, what should we do with the Geniemons?",
          TalkActionId = {
            [1] = "200074:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215AEB2"
        },
        [20006710] = {
          Camera = "-101.119141,154.260742,108.99675,0.000025,3.592208,132.807907,35.000015,110.824821,false,Manual,6.0",
          ContentFR = "Ils sont bien trop nombreux pour les faire sortir discrètement de Givrelac. Et si on les relâche ici, ils ne trouveront pas assez de Phoxène pour survivre...",
          DialogueId = 20006710,
          FacialId = {
            [1] = "200074:Unhappy01"
          },
          GUID = "3215AEDC",
          NextDialogue = 20006711,
          SpeakNpcId = 200074,
          Subtitle = "There are so many of them, it'd be impossible to sneak them out of Icelake. But we can't just release them here — there's no steady source of Phoxene energy for them to survive...",
          TalkActionId = {
            [1] = "200074:Confident_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200067/3215AEDC"
        },
        [20006711] = {
          Camera = "6.857422,-38.206055,107.53566,0.000019,-3.007906,-59.192425,35.000015,161.420593,false,Manual,6.0",
          ContentFR = "Comment ça... ? Tu veux dire que, même en les sauvant, on ne peut pas garantir qu’ils s’en tireront tous ?",
          DialogueId = 20006711,
          FacialId = {
            [1] = "200002:Unacceptable01"
          },
          FinalCamera = "6.857422,-38.206055,107.53566,0.000019,-3.007906,-59.192459,35.000011,450.0,false,Manual,6.0",
          GUID = "3215AF06",
          NextDialogue = 20006712,
          SpeakNpcId = 200002,
          Subtitle = "How can this be...? Are you saying, that even though we saved them from the poachers, we still can't make sure they all survive?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215AF06"
        },
        [20006712] = {
          Camera = "-64.103516,31.655273,119.67865,0.000029,-4.808036,119.607536,35.000011,450.0,false,Manual,6.0",
          ContentFR = "Oui. Sauf si on a suffisamment de Phoxène... mais pour en avoir assez pour tous, il faudrait qu’un fragment de Phoxène provienne de chaque foyer de Givrelac... or la plupart des gens ont peur des Géniemon. Ils ne voudront jamais aider.",
          DialogueId = 20006712,
          FinalCamera = "14.46875,-50.96875,106.754761,0.000019,-3.007906,-59.192356,35.000015,134.451996,false,Manual,6.0",
          GUID = "3215AF30",
          NextDialogue = 20006713,
          SpeakNpcId = 200074,
          Subtitle = "That's right. Unless we can get enough Phoxene for all of them... That would require every household in Icelake to chip in at least one piece. But most people are afraid of Geniemons. There's no way they'd agree to help...",
          TalkActionId = {
            [1] = "200074:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215AF30"
        },
        [20006713] = {
          Camera = "-108.800781,-45.291992,165.959991,0.000029,-12.807772,59.206985,35.000008,450.0,false,Manual,6.0",
          ContentFR = "<I>Groin groin...</>",
          DialogueId = 20006713,
          GUID = "3215AF5A",
          NextDialogue = 20006714,
          SpeakNpcId = 200086,
          Subtitle = "Oink, oink...",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AF5A"
        },
        [20006714] = {
          Camera = "-112.921875,-23.537109,160.274353,0.000064,1.1921,-114.590996,35.000011,159.3237,false,Manual,6.0",
          ContentFR = "Hmm... il va falloir trouver une solution...",
          DialogueId = 20006714,
          FacialId = {
            [1] = "100001:Think01"
          },
          FinalCamera = "-122.841797,-45.224609,160.77063,0.000065,2.392089,-114.590553,35.000011,142.061966,false,Manual,6.0",
          GUID = "3215AF84",
          NextDialogue = 20006715,
          SpeakNpcId = 100001,
          Subtitle = "Hmm... We need a plan...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215AF84"
        },
        [20006715] = {
          Camera = "-20.984375,-89.079102,120.151733,0.000088,-7.208342,-37.78812,35.000015,123.723419,false,Manual,6.0",
          ContentFR = "Je n’ai pas encore vu tout ça de mes propres yeux, et rien que d’y penser, ça me donne des frissons...",
          DialogueId = 20006715,
          FacialId = {
            [1] = "200002:Shock02"
          },
          FinalCamera = "-40.863281,-87.678711,84.628616,0.000085,7.591741,-32.988117,35.000015,161.950012,false,Manual,6.0",
          GUID = "3215AFAE",
          NextDialogue = 20006716,
          SpeakNpcId = 200002,
          Subtitle = "I haven't seen it yet, but just thinking about it — ooh, I'm getting goosebumps already!",
          TalkActionId = {
            [1] = "200002:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215AFAE"
        },
        [20006716] = {
          Camera = "-92.931641,513.984375,128.895233,0.000055,-1.407743,-97.792145,35.000008,450.0,false,Manual,6.0",
          ContentFR = "Truffle, dans ton village, les gens avaient peur de Filbert ?",
          DialogueId = 20006716,
          GUID = "3215AFD8",
          LookAt = {
            [1] = "100001:n(200074)"
          },
          NextDialogue = 20006717,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0.1},ActorId{100001},AnimationId{"Think_End"}},
PARA{
PlayFacial{_delay{0.5},ActorId{100001},FacialId{"Confident01"}},
PlayAnimation{_delay{2.1},ActorId{100001},AnimationId{"Talk02_Start"}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Truffle, back in your hometown, are people scared of Filbert?",
          VoiceName = "voice/$Locale$/story/2001/200067/3215AFD8"
        },
        [20006717] = {
          Camera = "-130.119141,-252.262695,186.619904,0.00007,-10.007689,106.210793,35.000011,450.0,false,Manual,6.0",
          ContentFR = "Hein ? Au début, oui. Personne n’avait jamais vu un cochon si énorme, ça fait peur. Mais quand ils ont vu que Filbert m’aidait à trouver de la nourriture, qu’elle était intelligente et débrouillarde, ils n’ont plus eu peur.",
          DialogueId = 20006717,
          FacialId = {
            [1] = "200074:Smile01"
          },
          GUID = "3215B002",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20006718,
          SpeakNpcId = 200074,
          Subtitle = "Well, at first, yeah. No one had ever seen a pig this big before, so they were a little scared. But once they saw how she helped me find food, how smart and hardworking she is — they weren't scared anymore.",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "200074:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200067/3215B002"
        },
        [20006718] = {
          Camera = "-143.039062,97.484375,110.879364,0.000087,0.791714,106.205078,35.000015,140.05127,false,Manual,6.0",
          ContentFR = "Exactement. La peur vient de l’ignorance. Si les gens voient ce que peuvent faire les Géniemon et qu’ils reçoivent leur aide, la peur finira par disparaître.",
          DialogueId = 20006718,
          FacialId = {
            [1] = "100001:Smile01"
          },
          FinalCamera = "-146.861328,105.399414,111.090088,0.000087,1.391712,107.405457,35.000015,140.05127,false,Manual,6.0",
          GUID = "3215B02C",
          NextDialogue = 20006719,
          SpeakNpcId = 100001,
          Subtitle = "Right. Fear comes from not knowing. But if people see what Geniemons are capable of — how they can help — then maybe that fear will disappear.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B02C"
        },
        [20006719] = {
          ContentFR = "Truffle, Snow, on va les emmener aux Asphodèles.",
          DialogueId = 20006719,
          GUID = "3215B056",
          SpeakNpcId = 100001,
          Subtitle = "Truffle, Snow — let's take them to The Asphodel.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200067/3215B056"
        },
        [20006720] = {
          Camera = "390.472656,-23.833008,76.522202,0.000054,0.592102,149.805954,35.000011,450.0,false,Manual,6.0",
          ContentFR = "D’accord ! Filbert, assieds-toi. On va charger les Géniemon sur ton dos et tous les emmener d’un seul coup !",
          DialogueId = 20006720,
          FinalCamera = "290.703125,34.223633,80.627289,0.000054,2.592091,149.805908,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B080",
          LookAt = {
            [1] = "200074:n(200086)"
          },
          NextDialogue = 20006721,
          SpeakNpcId = 200074,
          Subtitle = "Alright! Filbert, sit down — let's load them onto your back and take them all in one trip!",
          TalkActionId = {
            [1] = "200074:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B080"
        },
        [20006721] = {
          ContentFR = "Hein ? Encore Camilla ? Elle fera sa tête de mule et dira non... puis elle finira par trouver la solution parfaite, comme d’habitude.",
          DialogueId = 20006721,
          FacialId = {
            [1] = "200002:Confident02"
          },
          GUID = "3215B0AA",
          NextDialogue = 20006722,
          SpeakNpcId = 200002,
          Subtitle = "Huh? We're going to Camilla again? She's totally going to wear a big frown and act like she doesn't want to get involved... then come up with a perfect idea to help us.",
          TalkActionId = {
            [1] = "200002:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200067/3215B0AA"
        },
        [20006722] = {
          ContentFR = "Je viens aussi !",
          DialogueId = 20006722,
          GUID = "3215B0D4",
          NextDialogue = 20006723,
          SpeakNpcId = 200087,
          Subtitle = "I'll help too!",
          VoiceName = "voice/$Locale$/story/2001/200067/3215B0D4"
        },
        [20006723] = {
          ContentFR = "Moi aussi, moi aussi !",
          DialogueId = 20006723,
          GUID = "3215B0FE",
          NextDialogue = 20006724,
          SpeakNpcId = 200075,
          Subtitle = "Me too!",
          VoiceName = "voice/$Locale$/story/2001/200067/3215B0FE"
        },
        [20006724] = {
          Camera = "25.234375,43.664062,76.073486,0.000057,-10.207888,-1.19403,35.000011,450.0,false,Manual,6.0",
          ContentFR = "<I>Yiip !</>",
          DialogueId = 20006724,
          FinalCamera = "-37.855469,44.204102,84.949371,0.000057,-8.007871,-0.194,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B128",
          NextDialogue = 20006725,
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_Pan_Common",
          Subtitle = "Yip.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B128"
        },
        [20006725] = {
          Camera = "447.40625,104.102539,80.368851,0.000072,-1.207823,-159.593887,35.000011,450.0,false,Manual,6.0",
          ContentFR = "Hein ? Tu ne viens pas avec nous ?",
          DialogueId = 20006725,
          FinalCamera = "483.496094,102.482422,81.651184,0.000072,-3.00781,-160.39386,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B152",
          LookAt = {
            [1] = "100001:n(700251)"
          },
          NextDialogue = 20006726,
          SpeakNpcId = 100001,
          Subtitle = "Huh? You're not coming with us?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B152"
        },
        [20006726] = {
          Camera = "45.181641,44.441406,28.436035,0.000076,6.992051,-0.794525,35.000011,450.0,false,Manual,6.0",
          ContentFR = "Le Seigneur Paniemon a l’habitude de garder ses distances avec les gens. Il est probablement venu juste pour que vous aidiez à libérer les autres Géniemon.",
          DialogueId = 20006726,
          FinalCamera = "-94.589844,48.933594,37.514648,0.000076,0.791967,-1.194519,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B17C",
          NextDialogue = 20006727,
          SpeakNpcId = 200075,
          Subtitle = "Paniemon usually keeps its distance from people. It probably just showed up to get you to help free the other Geniemons.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B17C"
        },
        [20006727] = {
          Camera = "-76.480469,-72.768555,129.284988,0.000097,13.191738,-135.390411,35.000015,137.250519,false,Manual,6.0",
          ContentFR = "D’accord. Alors prends soin de toi, Paniemon.",
          DialogueId = 20006727,
          FinalCamera = "-99.601562,-95.574219,136.62146,0.000099,15.191671,-135.990753,35.000015,105.456551,false,Manual,6.0",
          GUID = "3215B1A6",
          NextDialogue = 20006728,
          SpeakNpcId = 100001,
          Subtitle = "I see. Alright, take care, Paniemon.",
          TalkActionId = {
            [1] = "100001:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B1A6"
        },
        [20006728] = {
          Camera = "-854.189453,515.839844,461.855774,0.000065,-20.40831,-29.192192,35.000011,450.0,false,Manual,6.0",
          ContentFR = "<I>Yiiip !</>",
          DialogueId = 20006728,
          FinalCamera = "-854.189453,515.839844,461.855774,0.000065,-20.40831,-29.192192,35.000011,450.0,false,Manual,6.0",
          GUID = "3215B1D0",
          SpeakNpcId = 700251,
          SpeakNpcName = "UI_Npc_Name_Pan_Common",
          Subtitle = "Yiiiip~",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200067/3215B1D0"
        },
        [20006801] = {
          ContentFR = "Finalement, les Géniemon furent conduits jusqu’aux Asphodèles, les clients de la taverne prirent la fuite, renversant chaises et verres dans la précipitation. Camilla fronça les sourcils et se demanda si laisser {nickname} entrer en ville n’avait pas été une énorme erreur.",
          DialogueId = 20006801,
          Duration = 5,
          GUID = "3215BDCA",
          Subtitle = [[
And so, the Geniemons were successfully brought to The Asphodel.
The moment they arrived, the tavern customers scrambled for the exits, knocking over chairs in their haste.
Camilla did frown, pinching the bridge of her nose as she reconsidered whether bringing  into the city had been a terrible mistake.]],
          VoiceName = "voice/$Locale$/story/2001/200068/3215BDCA"
        },
        [20006901] = {
          ContentFR = "Puis, au fil des jours, le froncement de sourcils de Camilla finit par s’adoucir...",
          DialogueId = 20006901,
          Duration = 3,
          GUID = "3215CE32",
          Subtitle = "But as the days passed, Camilla's frown began to ease...",
          VoiceName = "voice/$Locale$/story/2001/200069/3215CE32"
        },
        [20006902] = {
          Camera = "-77.774261,-546.844727,210.810547,-0.000763,-8.992114,80.412018,35.0,369.08606,false,Manual,12.0",
          ContentFR = "Eh bien, Camilla, sers-moi un Spécial Piquero. Par ce froid, un petit remontant chauffé par de vraies flammes, c’est ce qu’il nous faut.",
          DialogueId = 20006902,
          GUID = "3215CE5C",
          LookAt = {
            [1] = "700253:n(700248)",
            [2] = "700254:n(700253)"
          },
          NextDialogue = 20006903,
          Scripts = [[
PARA{
PlayFacial{_delay{3.5},ActorId{700248},FacialId{"Confident01"}},
PlayAnimation{_delay{3.1},ActorId{700248},AnimationId{"Talk03_Start"}}
}]],
          SpeakNpcId = 700253,
          Subtitle = "Camilla, I'll have a Zippyro Special. Nothing beats a drink warmed by real flames on a freezing day like this.",
          VoiceName = "voice/$Locale$/story/2001/200069/3215CE5C"
        },
        [20006903] = {
          ContentFR = "Au début, je pensais que cette petite chose était maléfique... mais sa flamme est parfaite pour chauffer une bonne boisson, c’est génial !",
          DialogueId = 20006903,
          GUID = "3215CE86",
          LookAt = {
            [1] = "700253:n(700253)"
          },
          NextDialogue = 20006904,
          SpeakNpcId = 700253,
          Subtitle = "Gotta admit, when I first saw this little thing, I thought it was evil with that weird flame. But turns out that flame's perfect for heating a nice drink. Hah — who'd have thought!",
          TalkActionId = {
            [1] = "700253:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CE86"
        },
        [20006904] = {
          Camera = "-270.673706,295.446289,221.228516,-0.000763,-10.792361,-56.385796,35.000008,369.08606,false,Manual,12.0",
          ContentFR = "Triste sort, Wells, ô triste sort, Wells.",
          DialogueId = 20006904,
          GUID = "3215CEB0",
          NextDialogue = 20006905,
          SpeakNpcId = 700254,
          Subtitle = "Oh, the folly, Wells! The wretched, wretched folly!",
          TalkActionId = {
            [1] = "700254:Sigh_Start",
            [2] = "700253:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CEB0"
        },
        [20006905] = {
          Camera = "-37.503937,-47.555664,133.710938,-0.000763,-2.992312,-78.38279,35.000008,369.08606,false,Manual,12.0",
          ContentFR = "Toi qui vois seulement que le feu du Piquero réchauffe la boisson et réconforte le ventre, tu ignores sa vraie valeur : il fend l’obscurité, éclaire mes écrits la nuit et m’inspire !",
          DialogueId = 20006905,
          GUID = "3215CEDA",
          NextDialogue = 20006906,
          SpeakNpcId = 700254,
          Subtitle = "You see only the fleeting comfort of a warm drink! But Zippyro's flame — it doesn't merely warm the body! It carves through the abyss! It ignites the eternal night! It is the fire of my muse!",
          TalkActionId = {
            [1] = "700254:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CEDA"
        },
        [20006906] = {
          Camera = "-89.716675,175.708008,152.642578,-0.000763,-3.992218,-88.380859,35.000008,369.08606,false,Manual,12.0",
          ContentFR = "Pi-que-ro. Trois syllabes sublimes : la lumière de ma plume, l’ardeur de ma création ! Mon péché, mon salut !",
          DialogueId = 20006906,
          GUID = "3215CF04",
          SpeakNpcId = 700254,
          Subtitle = "Zippyro! Three syllables of pure poetry! The spark of my words, the pyre of my soul, my sin, and my salvation!",
          TalkActionId = {
            [1] = "700254:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200069/3215CF04"
        },
        [20007001] = {
          Camera = "410.60437,303.494141,154.748047,0.000089,0.396813,37.710804,35.0,369.08606,false,Manual,12.0",
          ContentFR = "Certains arrosent leurs fleurs avec des Gouttines, d’autres s’endorment grâce à M. Bonne Nuit... et maintenant, même mon commerce dépend d’un Piquero.",
          DialogueId = 20007001,
          FinalCamera = "262.071167,223.890625,147.691406,0.000094,-1.403686,36.110554,35.000011,369.08606,false,Manual,12.0",
          GUID = "3215DE9A",
          NextDialogue = 20007002,
          Scripts = [[
PARA{
SEQ{
TurnTo{_delay{2},TurnToDescription{"700248:p(180)"}},
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Confident_Start"},Duration{1}}
},
PlayFacial{_delay{0.5},ActorId{700248},FacialId{"Smile01"}}
}]],
          SpeakNpcId = 700248,
          Subtitle = "Some people use Dripplet to water their plants. Others rely on Mr Goodnight for sleep. And now, even my business depends on a Zippyro.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DE9A"
        },
        [20007002] = {
          ContentFR = "C’est drôle comme les choses changent. Hier encore, on parlait d’extraire le Phoxène des Géniemon, et maintenant, les gens en achètent exprès pour les nourrir et mieux s’en faire des amis.",
          DialogueId = 20007002,
          GUID = "3215DEC4",
          LookAt = {
            [1] = "100001:n(200074)",
            [2] = "200002:n(200074)"
          },
          NextDialogue = 20007003,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1},ActorId{700248},AnimationId{"Confident_End"},Duration{1}},
PARA{
PlayAnimation{_delay{1.5},ActorId{700248},AnimationId{"Talk02_Start"},Duration{1}},
PlayFacial{_delay{7.5},ActorId{700248},FacialId{"Smile02"}}
},
PlayFacial{_delay{1.0},ActorId{700248},FacialId{"None"}}
}]],
          SpeakNpcId = 700248,
          Subtitle = "Funny how things turn around. Not long ago, people were all about extracting Phoxene from Geniemons — now they're buying it just to keep them around.",
          VoiceName = "voice/$Locale$/story/2001/200070/3215DEC4"
        },
        [20007003] = {
          Camera = "855.156494,437.582031,235.363281,-0.000335,-12.202781,-167.746658,35.000008,369.08606,false,Manual,12.0",
          ContentFR = "C’est grâce à Truffle et Filbert. Si Filbert sait vivre avec les humains, les Géniemon aussi le peuvent.",
          DialogueId = 20007003,
          GUID = "3215DEEE",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20007004,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1},ActorId{700248},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "That all thanks to Truffle and Filbert. If Filbert can live peacefully with humans, then so can Geniemons.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DEEE"
        },
        [20007004] = {
          Camera = "385.531738,327.31543,122.824219,-0.000336,8.596824,174.251282,35.0,169.08606,false,Manual,12.0",
          ContentFR = "Et si les Géniemon peuvent coexister avec nous, peut-être qu’un jour Charons et Solariens trouveront aussi un terrain d’entente.",
          DialogueId = 20007004,
          GUID = "3215DF18",
          NextDialogue = 20007005,
          Scripts = "PlayFacial{_delay{0.5},ActorId{700248},FacialId{\"Smile01\"}}",
          SpeakNpcId = 100001,
          Subtitle = "And if Geniemons and humans can get along, maybe one day Charons and Solarians will too.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF18"
        },
        [20007005] = {
          Camera = "271.747681,244.423828,145.421875,0.000091,0.396629,32.112232,35.0,369.08606,false,Manual,12.0",
          ContentFR = "Haha, je ne sais pas si tu es {性别:naïf|naïve} ou simplement {性别:porteur|porteuse} d’une grande vision. En tout cas, j’attends ce jour avec curiosité. Mais pour l’instant... il est temps de dire au revoir à cette petite voyageuse.",
          DialogueId = 20007005,
          FinalCamera = "134.401306,153.286133,129.798828,-0.000336,-0.203833,31.850718,35.000008,369.08606,false,Manual,12.0",
          GUID = "3215DF42",
          NextDialogue = 20007006,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Sigh_Start"},Duration{2}},
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Sigh_End"},Duration{1}}}]],
          SpeakNpcId = 700248,
          Subtitle = "Haha, I can't decide if you're just naive or a true visionary. Either way, I'll be looking forward to that day. But for now... it's time to say goodbye to a certain little traveller.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF42"
        },
        [20007006] = {
          Camera = "721.993774,408.491211,205.130859,0.00002,-14.403127,-165.088608,35.0,369.08606,false,Manual,12.0",
          ContentFR = "<I>Ouinnn...</> Truffle, tu ne peux pas rester à Givrelac ? Le Roi Démon de la Lumière a enfin trouvé quelqu’un pour scander ses titres ensemble !",
          DialogueId = 20007006,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "3215DF6C",
          NextDialogue = 20007007,
          SpeakNpcId = 200002,
          Subtitle = "Boohoo... Truffle, can't you just stay? As the Demon King of Light, I finally found someone who would chant the title I gave them aloud with me, and now you're leaving so soon... Waaah!",
          TurnTo = {
            [1] = "200074:p(30)"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF6C"
        },
        [20007007] = {
          ContentFR = "Ne pleure pas, Snow. Ça fait longtemps que je suis partie à l’aventure, il est temps de rentrer. Puis ces anciens chasseurs se sont reconvertis en chercheurs sur les Géniemon, tu peux leur demander de chanter tes titres avec toi.",
          DialogueId = 20007007,
          GUID = "3215DF96",
          NextDialogue = 20007008,
          SpeakNpcId = 200074,
          Subtitle = "Aww, don't cry, Snow. I've been away for so long — it's time for me to go home. Besides, those ex-poachers are now Geniemon researchers. You can always ask them to chant with you.",
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF96"
        },
        [20007008] = {
          Camera = "428.352539,486.96582,156.205078,0.000078,-8.003704,-124.08696,35.0,369.08606,false,Manual,12.0",
          ContentFR = "Non, ils n’ont pas ta voix, et ils ne peuvent pas me faire faire un tour sur Filbert comme toi. {nickname}, bouge-toi et aide-moi à convaincre Truffle de rester !",
          DialogueId = 20007008,
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          GUID = "3215DFC0",
          NextOptions = {
            [1] = 200070081
          },
          SpeakNpcId = 200002,
          Subtitle = "Nah-uh, it's not the same. They're not as sweet as you... And they definitely can't carry me on Filbert for a ride! , don't just stand there — help me convince Truffle to stay!",
          TalkActionId = {
            [1] = "700248:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DFC0"
        },
        [20007009] = {
          Camera = "322.5,503.43457,157.886719,0.000066,-8.003506,-99.487526,35.000008,369.08606,false,Manual,12.0",
          ContentFR = "Héhé, je reviendrai de temps en temps, promis. Et laisse-moi te dire un petit secret, l’endroit lointain où je retourne, c’est en fait l’Église Élyséenne.",
          DialogueId = 20007009,
          FacialId = {
            [1] = "200002:CM_Idle"
          },
          FinalCamera = "316.476074,471.517578,153.757812,0.000067,-8.603483,-101.087669,35.000008,369.08606,false,Manual,12.0",
          GUID = "3215DFEA",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20007010,
          SpeakNpcId = 200074,
          Subtitle = "Hehe, I'll be back to visit, I promise. And let me secretly tell you something— the faraway place I'm returning to is actually the Elysian Church.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DFEA"
        },
        [20007010] = {
          Camera = "-189.593018,180.383789,233.115234,0.000085,-10.602577,9.713165,35.0,369.08606,false,Manual,12.0",
          ContentFR = "Quand Filbert et moi cherchons de la nourriture, on traverse parfois, par des montagnes non gardées pour atteindre l’Hyperborea. Au début, j'avais un peu peur, après tout, l’Église et l’Empire ont toujours été en guerre...",
          DialogueId = 20007010,
          GUID = "3215E014",
          NextDialogue = 20007011,
          SpeakNpcId = 200074,
          Subtitle = "When Filbert and I forage for food, we sometimes cross the unguarded mountain border to reach Hyperborea. At first, I was a little scared — after all, the Church and the Empire have always been at war...",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E014"
        },
        [20007011] = {
          ContentFR = "Mais après vous avoir rencontré, je n’ai plus peur.",
          DialogueId = 20007011,
          GUID = "3215E03E",
          NextDialogue = 20007012,
          SpeakNpcId = 200074,
          Subtitle = "But after meeting you, I'm not scared anymore.",
          TalkActionId = {
            [1] = "200074:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215E03E"
        },
        [20007012] = {
          ContentFR = "Parce que si tu peux trouver un moyen pour que les Géniemon et les humains vivent ensemble en amis, alors je crois qu’un jour, tu sauras aussi rapprocher les Charons et les Solariens, et peut-être même faire en sorte que l’Empire et l’Église cessent enfin de se battre.",
          DialogueId = 20007012,
          GUID = "3215E068",
          NextDialogue = 20007013,
          SpeakNpcId = 200074,
          Subtitle = "Because if you can find a way for Geniemons and humans to become friends, then I believe one day, you'll also figure out how to make Charons and Solas friends — and maybe even the Empire and the Church too!",
          TalkActionId = {
            [1] = "200074:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215E068"
        },
        [20007013] = {
          ContentFR = "Comme ça, plus personne n’aura faim !",
          DialogueId = 20007013,
          GUID = "3215E092",
          NextDialogue = 20007014,
          SpeakNpcId = 200074,
          Subtitle = "And once the war stops, there will be no more hunger!",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E092"
        },
        [20007014] = {
          ContentFR = "Et quand ce jour viendra, viens me voir au sud avec Snow et Madame Camilla. On mangera des Chapeaux-de-Rubis tout roses, on sentira la brise chaude de la mer et on regardera plein d’étoiles qu’on ne voit pas ici. Ce sera trop bien, comme quand je suis venue ici ! Je vous attendrai !",
          DialogueId = 20007014,
          GUID = "3215E0BC",
          NextDialogue = 20007015,
          SpeakNpcId = 200074,
          Subtitle = "When that day comes, please come and visit me in the South with Snow and Ms Camilla. I'll treat you to our pink-red mushroom called Russula, and we'll go to the beach and feel the warmth of the sea breeze, and look up at stars you can't see from here. You'll have a great time, just like I did here!",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E0BC"
        },
        [20007015] = {
          ContentFR = "D’accord, je vais faire de mon mieux.",
          DialogueId = 20007015,
          GUID = "3215E0E6",
          NextDialogue = 20007016,
          SpeakNpcId = 100001,
          Subtitle = "That sounds wonderful. I'll try my best to make that happen.",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E0E6"
        },
        [20007016] = {
          ContentFR = "On se le jure sur le petit doigt !",
          DialogueId = 20007016,
          GUID = "3215E110",
          NextOptions = {
            [1] = 200070161
          },
          SpeakNpcId = 200074,
          Subtitle = "Pinky swear~",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E110"
        },
        [20007017] = {
          ContentFR = "Et avec Filbert aussi !",
          DialogueId = 20007017,
          GUID = "3215E13A",
          NextDialogue = 20007018,
          SpeakNpcId = 200074,
          Subtitle = "And Filbert too!",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E13A"
        },
        [20007018] = {
          ContentFR = "Les sabots de Filbert sont trop gros pour un petit doigt...",
          DialogueId = 20007018,
          GUID = "3215E164",
          NextDialogue = 20007019,
          SpeakNpcId = 100001,
          Subtitle = "Uh, her hooves seem a little too big for a pinky swear.",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E164"
        },
        [20007019] = {
          ContentFR = "Alors tiens juste son sabot, ça marche quand même ! Allez, ensemble : promis sur le petit doigt, pour toujours !",
          DialogueId = 20007019,
          GUID = "3215E18E",
          NextDialogue = 20007020,
          SpeakNpcId = 200074,
          Subtitle = "Then just hold onto her hoof — it still counts! Okay, together — cross my heart, hope to die, stick a needle in my eye!",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E18E"
        },
        [20007020] = {
          ContentFR = "<I>Groin !</>",
          DialogueId = 20007020,
          GUID = "3215E1B8",
          SpeakNpcId = 200086,
          Subtitle = "Oink!",
          VoiceName = "voice/$Locale$/story/2001/200070/3215E1B8"
        },
        [20007101] = {
          ContentFR = "Je suis... le premier chercheur en Géniemon de Givrelac ! Si vous avez des questions sur ces créatures, vous pouvez me demander — Ah, c’est toi... Euh, je peux t’aider ?",
          DialogueId = 20007101,
          GUID = "3215EF02",
          NextOptions = {
            [1] = 200071011,
            [2] = 200071012,
            [3] = 200071013
          },
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "I am Icelake's foremost Geniemon scholar! If you have any questions about them, feel free to— Oh, it's you. Uh, is—is there anything I can help you with?",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF02"
        },
        [20007102] = {
          ContentFR = "Tu veux parler de ce Géniemon réputé pour son intelligence ?",
          DialogueId = 20007102,
          GUID = "3215EF2C",
          NextDialogue = 20007103,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "You mean that incredibly intelligent Geniemon?",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF2C"
        },
        [20007103] = {
          ContentFR = "Les archives sont très maigres. Je ne l’ai vu qu’une seule fois. On raconte qu’il ne se montre qu’à ceux qu’il juge dignes.",
          DialogueId = 20007103,
          GUID = "3215EF56",
          NextDialogue = 20007104,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "There's very little documented about it. I've only ever seen it once myself. They say it doesn't reveal itself to just anyone. Only those it deems worthy ever get to meet it.",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF56"
        },
        [20007104] = {
          ContentFR = "En revanche, tu devrais pouvoir le localiser en suivant les traces qu’il laisse.",
          DialogueId = 20007104,
          GUID = "3215EF80",
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "But you might be able to track it down by following the traces it leaves behind.",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF80"
        },
        [20007105] = {
          ContentFR = "Bien mieux que celle d’un chasseur de Géniemon. Maintenant, des gens viennent me poser des questions, j’ai l’air d’un vrai savant.",
          DialogueId = 20007105,
          GUID = "3215EFAA",
          NextDialogue = 20007106,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "Much better than being a Geniemon hunter, that's for sure. People actually come to me for advice now. I almost feel like a real academic.",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EFAA"
        },
        [20007106] = {
          ContentFR = "Merci d’avoir été indulgent avec moi, toi et Truffle. Vraiment, merci.",
          DialogueId = 20007106,
          GUID = "3215EFD4",
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          Subtitle = "Speaking of which, I really appreciate that you and Truffle went easy on me back then.",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EFD4"
        },
        [20007107] = {
          ContentFR = "Plusieurs profondes entailles, laissées, semble-t-il, par un objet particulièrement tranchant.",
          DialogueId = 20007107,
          GUID = "3215EFD5",
          Subtitle = "Several deep gouges, as if left by some jagged object."
        },
        [20007108] = {
          ContentFR = "Un panneau indiquant : « Zone dangereuse — Accès strictement interdit ». Plusieurs avis ont été superposés, comme si un nouveau venait recouvrir l’ancien dès qu’il se dégradait. Le plus récent est daté de l’an 1004 du nouveau calendrier — il y a une vingtaine d’années. C’est sans doute à cette époque que la Fosse de Glevum a été définitivement abandonnée.",
          DialogueId = 20007108,
          GUID = "3215EFD6",
          Subtitle = "A sign reading \"Danger: No Entry\" was piled up with multiple layers, as if a new one was posted each time the old one faded. The latest was dated 1004  — twenty years ago — suggesting Glevum Pit was abandoned around that time."
        },
        [21000101] = {
          Content = "背白白进场台词（测试用）",
          DialogueId = 21000101,
          GUID = "34925112",
          TalkActionId = {
            [1] = "900005:Beibao_Start"
          }
        },
        [21000102] = {
          Content = "背白白退场台词（测试用）",
          DialogueId = 21000102,
          GUID = "3492513C",
          TalkActionId = {
            [1] = "900005:Beibao_Finish"
          }
        },
        [50000101] = {
          ContentFR = "Hé, c’est à toi que je parle ! Tu as bien ton permis sur toi ?",
          DialogueId = 50000101,
          Duration = 3,
          GUID = "7D2B8592",
          SpeakNpcId = 700111,
          Subtitle = "Travel permit check — oi, I'm talking to you! Got your travel permit on you?",
          VoiceName = "voice/$Locale$/env/700002/7D2B8592"
        },
        [50000201] = {
          ContentFR = "{性别:Un Chasseur de Phoxène|Une Chasseuse de Phoxène} ? Je n’aurais jamais cru que l’un d’eux atteindrait cet endroit... Tu dois avoir, toi aussi, ce qu’il faut pour devenir {性别:un héros|une héroïne}.",
          DialogueId = 50000201,
          Duration = 4,
          GUID = "7D2B95FA",
          SpeakNpcId = 700003,
          Subtitle = "A Phoxhunter? Can't believe anyone would still make it here. You've got what it takes to be a hero like them, I guess.",
          VoiceName = "voice/$Locale$/env/700003/7D2B95FA"
        },
        [50000301] = {
          ContentFR = "Tout ça, c’est la faute de Grandet ! Qu’est-ce que je suis censé faire maintenant... Hein ? Qu’est-ce que tu regardes ? Je n’ai aucune mission pour toi aujourd’hui !",
          DialogueId = 50000301,
          Duration = 3,
          GUID = "7D2BA662",
          SpeakNpcId = 700004,
          Subtitle = "D*mn it, it's all Grandet's fault! What am I supposed to do now... Hm? What are you looking at? I've got no work for you today!",
          VoiceName = "voice/$Locale$/env/700004/7D2BA662"
        },
        [50000401] = {
          ContentFR = "Je suis... Annie ?",
          DialogueId = 50000401,
          Duration = 3,
          GUID = "7D2BB6CA",
          SpeakNpcId = 700032,
          Subtitle = "My name is... Annie?",
          TalkActionId = {
            [1] = "700032:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700032/7D2BB6CA"
        },
        [50000501] = {
          ContentFR = "Dès que je serai rétablie, je reprendrai la route pour une nouvelle aventure.",
          DialogueId = 50000501,
          Duration = 3,
          GUID = "7D2BC732",
          SpeakNpcId = 700005,
          Subtitle = "As soon as I'm back in form, I'm off on another adventure.",
          TalkActionId = {
            [1] = "700032:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700005/7D2BC732"
        },
        [50000601] = {
          ContentFR = "Qu’est-ce que je pourrais offrir à maman... ? Elle doit être impatiente de me revoir.",
          DialogueId = 50000601,
          Duration = 3,
          GUID = "7D2BD79A",
          SpeakNpcId = 700005,
          Subtitle = "What gift should I get for mother... She must've missed me terribly.",
          TalkActionId = {
            [1] = "700005:Think_Start"
          },
          VoiceName = "voice/$Locale$/env/700005/7D2BD79A"
        },
        [50000701] = {
          ContentFR = "Annie... Annie !",
          DialogueId = 50000701,
          Duration = 3,
          GUID = "7D2BE802",
          SpeakNpcId = 700006,
          Subtitle = "Annie... Annie!",
          VoiceName = "voice/$Locale$/env/700006/7D2BE802"
        },
        [50000801] = {
          ContentFR = "Les fleurs sont magnifiques aujourd’hui... Je devrais en garder quelques-unes pour cette enfant.",
          DialogueId = 50000801,
          Duration = 3,
          GUID = "7D2BF86A",
          SpeakNpcId = 700007,
          Subtitle = "The flowers today are quite lovely. I should save a few for that kid.",
          TalkActionId = {
            [1] = "700007:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700007/7D2BF86A"
        },
        [50000901] = {
          ContentFR = "Bonjour. Cette fleur s’accorde parfaitement avec votre tenue... Si elle était encore là, elle aurait dit la même chose.",
          DialogueId = 50000901,
          Duration = 5,
          GUID = "7D2C08D2",
          SpeakNpcId = 700203,
          Subtitle = "Good day, you look great with this flower... That kid would have said so, if she were still here.",
          VoiceName = "voice/$Locale$/env/700007/7D2C08D2"
        },
        [50001001] = {
          ContentFR = "Avec votre allure, ce serait un crime de ne pas porter mes créations.",
          DialogueId = 50001001,
          Duration = 3,
          GUID = "7D2C193A",
          SpeakNpcId = 700008,
          Subtitle = "Hello, gorgeous! I bet you'd be a vision in our apparel.",
          VoiceName = "voice/$Locale$/env/700008/7D2C193A"
        },
        [50001101] = {
          ContentFR = "Les meilleurs fruits de notre domaine ! Nulle part ailleurs vous ne trouverez un savoir-faire aussi raffiné !",
          DialogueId = 50001101,
          Duration = 3,
          GUID = "7D2C29A2",
          SpeakNpcId = 700009,
          Subtitle = "Try these fine fruits from our orchard — grown with unmatched cultivation techniques!",
          TalkActionId = {
            [1] = "700009:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700009/7D2C29A2"
        },
        [50001201] = {
          ContentFR = "Ah... O-Oh, je... euh...",
          DialogueId = 50001201,
          Duration = 2,
          GUID = "7D2C3A0A",
          SpeakNpcId = 700010,
          Subtitle = "Ah... whoa, I... um...",
          VoiceName = "voice/$Locale$/env/700010/7D2C3A0A"
        },
        [50001301] = {
          ContentFR = "Hmm... j’ai décidé, toi, tu seras le sujet d’expérience n° 1 !",
          DialogueId = 50001301,
          Duration = 3,
          GUID = "7D2C4A72",
          SpeakNpcId = 700011,
          Subtitle = "Hmm... I've made up my mind — hello, Test subject No. 1!",
          TalkActionId = {
            [1] = "700011:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700011/7D2C4A72"
        },
        [50001401] = {
          ContentFR = "{nickname} ! Je suis content de te voir ! Moi, je continue à apprendre plein de nouvelles choses tous les jours. Alors... on continue à progresser ensemble, d’accord ?",
          DialogueId = 50001401,
          Duration = 4,
          GUID = "7D2C5ADA",
          SpeakNpcId = 700011,
          Subtitle = ", lovely to see you again! I'm trying my best to learn new things every day, let's keep at it!",
          TalkActionId = {
            [1] = "700011:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700011/7D2C5ADA"
        },
        [50001501] = {
          ContentFR = "Tu... Charon... un des miens...",
          DialogueId = 50001501,
          Duration = 6,
          GUID = "7D2C6B42",
          SpeakNpcId = 700012,
          Subtitle = "You... Charon... You're one of us...",
          VoiceName = "voice/$Locale$/env/700012/7D2C6B42"
        },
        [50001601] = {
          ContentFR = "J’en ai vu, des choses qu’on préfère cacher dans l’ombre... Et les \"démons\" ne sont pas toujours ceux qu’on croit.\n... Parfois, entre les Solariens et les Charons, je ne sais plus lesquels sont les véritables démons.",
          DialogueId = 50001601,
          Duration = 4,
          GUID = "7D2C7BAA",
          SpeakNpcId = 700013,
          Subtitle = [[
I've witnessed deeds that daylight never sees, and not all are the work of "demons".
...Sometimes, between Solas and Charons, I can't tell which is the true demon.]],
          VoiceName = "voice/$Locale$/env/700013/7D2C7BAA"
        },
        [50001701] = {
          ContentFR = "Pff ! Sale idiote ! On verra bien combien de temps encore tu pourras jouer les fortes têtes !",
          DialogueId = 50001701,
          Duration = 4,
          GUID = "7D2C8C12",
          SpeakNpcId = 700014,
          Subtitle = "Pah! Stupid hag! Let's see how long you can keep this charade up!",
          TalkActionId = {
            [1] = "700014:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/env/700014/7D2C8C12"
        },
        [50001801] = {
          ContentFR = "Par tous les Cieux ! Comment un être aussi doux que moi a-t-il pu tomber victime d’un spectre voleur d’inspiration ?! Une telle injustice ferait pleurer même les cieux !",
          DialogueId = 50001801,
          Duration = 4,
          GUID = "7D2C9C7A",
          SpeakNpcId = 700015,
          Subtitle = "Good grief! Who'd have thought a gentle soul like myself would be beset by an inspiration-stealing spectre?! Such wretchedness would surely draw heaven's own tears!",
          VoiceName = "voice/$Locale$/env/700015/7D2C9C7A"
        },
        [50001901] = {
          ContentFR = "Quelle perte de temps ! Organiser des évènements aussi creux... On ferait mieux d’avoir une demi-journée de repos !",
          DialogueId = 50001901,
          Duration = 3,
          GUID = "7D2CACE2",
          SpeakNpcId = 700016,
          Subtitle = "What a drag! Who arranged these pointless events? I'd rather have half a day off!",
          VoiceName = "voice/$Locale$/env/700016/7D2CACE2"
        },
        [50002001] = {
          ContentFR = "« Sous la pluie, les fleurs de maman se sont fanées... Alors le ciel a semé de petites fleurs dans les flaques, pour lui présenter ses excuses. »",
          DialogueId = 50002001,
          Duration = 3,
          GUID = "7D2CBD4A",
          NextDialogue = 50002002,
          SpeakNpcId = 700017,
          Subtitle = "\"The rain hurt Mum's flowers, so the sky said sorry by leaving her lots of tiny flowers in the puddles.\"",
          VoiceName = "voice/$Locale$/env/700017/7D2CBD4A"
        },
        [50002002] = {
          ContentFR = "Vous savez ? Ce petit poème s’intitule <I>Excuses</>, et il a été écrit par l’un de mes élèves... il n’a que six ans.",
          DialogueId = 50002002,
          Duration = 3,
          GUID = "7D2CBD74",
          SpeakNpcId = 700017,
          Subtitle = "You know what, this little verse is called \"Apology\", and it's written by a six-year-old student of mine.",
          TalkActionId = {
            [1] = "700017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700017/7D2CBD74"
        },
        [50002101] = {
          ContentFR = "Les pierres jetées contre les lois de la nature finissent toujours par retomber sur celui qui les lance.",
          DialogueId = 50002101,
          Duration = 3,
          GUID = "7D2CCDB2",
          SpeakNpcId = 700018,
          Subtitle = "The rocks cast against the laws of nature will inevitably fall back on one's own head.",
          TalkActionId = {
            [1] = "700018:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/env/700018/7D2CCDB2"
        },
        [50002201] = {
          ContentFR = "Où a-t-il bien pu disparaître...",
          DialogueId = 50002201,
          Duration = 3,
          GUID = "7D2CDE1A",
          SpeakNpcId = 700019,
          Subtitle = "Where could he have gone off to...",
          TalkActionId = {
            [1] = "700019:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700019/7D2CDE1A"
        },
        [50002301] = {
          ContentFR = "J’espère que la crème de champignons préparée ce soir réchauffera un peu le cœur de Madame.",
          DialogueId = 50002301,
          Duration = 4,
          GUID = "7D2CEE82",
          SpeakNpcId = 700020,
          Subtitle = "I hope tonight's creamy mushroom soup will bring some comfort to her ladyship.",
          TalkActionId = {
            [1] = "700020:Agree"
          },
          VoiceName = "voice/$Locale$/env/700020/7D2CEE82"
        },
        [50002401] = {
          ContentFR = "Pauvre femme... Elle a complètement perdu la tête.",
          DialogueId = 50002401,
          Duration = 3,
          GUID = "7D2CFEEA",
          NextDialogue = 50002402,
          SpeakNpcId = 700023,
          Subtitle = "Poor thing, having lost her mind like that.",
          VoiceName = "voice/$Locale$/env/700023/7D2CFEEA"
        },
        [50002402] = {
          ContentFR = "Pas étonnant que sa fille ait fini par partir.",
          DialogueId = 50002402,
          Duration = 3,
          GUID = "7D2CFF14",
          SpeakNpcId = 700024,
          Subtitle = "No wonder her daughter had left.",
          VoiceName = "voice/$Locale$/env/700024/7D2CFF14"
        },
        [50002501] = {
          ContentFR = "Toutes les poubelles de la cité sont sous ma garde. Et crois-moi, on y trouve de tout ! Des bottes en daim portées à peine deux fois, des lys encore frais... et même les fragments de rêves brisés de quelqu’un.",
          DialogueId = 50002501,
          Duration = 3,
          GUID = "7D2D0F52",
          SpeakNpcId = 700115,
          Subtitle = "I oversee all the rubbish bins around the city, and oh, the treasures to be found in each of them! Nearly new deerskin boots, still-fresh lilies, and the fragments of someone's shattered dreams...",
          TalkActionId = {
            [1] = "700115:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700022/7D2D0F52"
        },
        [50002601] = {
          ContentFR = "Le train pour la prochaine station va partir. Billets en vente ici — Quoi ? Pas d’argent ? Alors cessez de rêver et dégagez d’ici !",
          DialogueId = 50002601,
          Duration = 5,
          GUID = "7D2D0F53",
          SpeakNpcId = 700021,
          Subtitle = "The train to the next station is about to depart. Please process your ticket purchase here — What's that? You've got no money? Then less dreaming, more moving, if you please!",
          TalkActionId = {
            [1] = "700021:Confident_Start"
          }
        },
        [50002701] = {
          ContentFR = "La canalisation n° 13 est en réparation. Bon sang... il y a bien trop de rats là-dedans.",
          DialogueId = 50002701,
          Duration = 4,
          GUID = "7D2D3022",
          SpeakNpcId = 700069,
          Subtitle = "Pipe No. 13 is under repair — blimey, it's swarming with rats in there.",
          TalkActionId = {
            [1] = "700069:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700069/7D2D3022"
        },
        [50002801] = {
          ContentFR = "Dégage, sale Charon !",
          DialogueId = 50002801,
          DialoguePanelType = "{type:Bubble;style:ExcitedBubble}",
          Duration = 3,
          GUID = "7D2D408A",
          SpeakNpcId = 700068,
          Subtitle = "Beat it, dirty Charon!",
          VoiceName = "voice/$Locale$/env/700068/7D2D408A"
        },
        [50002901] = {
          ContentFR = "Argh... pourquoi ces taches de sang ne veulent-elles pas partir ?",
          DialogueId = 50002901,
          Duration = 3,
          GUID = "7D2D50F2",
          SpeakNpcId = 700067,
          Subtitle = "Ugh... these bloodstains just won't come off!",
          TalkActionId = {
            [1] = "700067:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700067/7D2D50F2"
        },
        [50003001] = {
          Content = "凶猛的狼咆哮着 撕咬着狡猾的狗",
          DialogueId = 50003001,
          Duration = 3,
          GUID = "7D2D615A",
          NextDialogue = 50003002,
          SpeakNpcId = 700071,
          TalkActionId = {
            [1] = "700071:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700071/7D2D615A"
        },
        [50003002] = {
          Content = "狡猾的狗呜咽着 啃食着腐朽的肉",
          DialogueId = 50003002,
          Duration = 3,
          GUID = "7D2D6184",
          SpeakNpcId = 700071,
          TalkActionId = {
            [1] = "700071:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700071/7D2D6184"
        },
        [50003101] = {
          Content = "您也喜欢这些百合吗？",
          DialogueId = 50003101,
          Duration = 3,
          GUID = "7D2D71C2",
          SpeakNpcId = 700072,
          TalkActionId = {
            [1] = "700072:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700072/7D2D71C2"
        },
        [50003201] = {
          ContentFR = "« Hors de la ville, les Souillés nous dévorent, en ville, les fermiers nous tondent sans répit. Les chiens festoient de pain blanc, les moutons Charon broutent l’herbe jaunie... »",
          DialogueId = 50003201,
          Duration = 3,
          GUID = "7D2D822A",
          NextDialogue = 50003202,
          SpeakNpcId = 700073,
          Subtitle = "♪ \"Monsters beyond the walls feast on our flesh; the ones within shear our fleece. While the hounds dine on fine white loaves; we lowly sheep are content with chewing grass...\"",
          TalkActionId = {
            [1] = "700073:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700073/7D2D822A"
        },
        [50003202] = {
          ContentFR = "Bon sang ! Où as-tu appris cette chanson... ? Un jour, elle va nous faire exécuter tous les deux !",
          DialogueId = 50003202,
          Duration = 3,
          GUID = "7D2D8254",
          NextDialogue = 50003203,
          SpeakNpcId = 700074,
          Subtitle = "Whoa, whoa! Where did you learn that ditty... you're going to get us both killed one of these days!",
          TalkActionId = {
            [1] = "700074:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700074/7D2D8254"
        },
        [50003203] = {
          ContentFR = "Oh ! {性别:Cher client|Chère cliente}, désirez-vous acheter quelque chose ? Tout ici est fait main par mes soins, qualité irréprochable garantie !",
          DialogueId = 50003203,
          Duration = 3,
          GUID = "7D2D827E",
          SpeakNpcId = 700074,
          Subtitle = "Ah, welcome! What can I get you, dear customer? Each piece here is crafted by my own hands, top-notch quality guaranteed!",
          TalkActionId = {
            [1] = "700074:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700074/7D2D827E"
        },
        [50003301] = {
          Content = "真好呀！真好！生活这么美好，怎么大家都愁眉苦脸的呢？我们生活在一个幸福的世界里，多么幸运！",
          DialogueId = 50003301,
          Duration = 3,
          GUID = "7D2D9292",
          SpeakNpcId = 700075,
          TalkActionId = {
            [1] = "700075:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/env/700075/7D2D9292"
        },
        [50003401] = {
          Content = "呜呜……爸爸妈妈，你们在哪里……我好想你们……",
          DialogueId = 50003401,
          Duration = 3,
          GUID = "7D2DA2FA",
          SpeakNpcId = 700076,
          TalkActionId = {
            [1] = "700076:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700076/7D2DA2FA"
        },
        [50003501] = {
          Content = "这是我在广场那边买的纪念品！他们说来冰湖城绝不能错过……",
          DialogueId = 50003501,
          Duration = 3,
          GUID = "7D2DB362",
          SpeakNpcId = 700077,
          TalkActionId = {
            [1] = "700077:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700077/7D2DB362"
        },
        [50003601] = {
          Content = "求您了……再多给两个子儿吧，只给这个数，我连过冬的炭火都买不起啊……",
          DialogueId = 50003601,
          Duration = 3,
          GUID = "7D2DC3CA",
          NextDialogue = 50003602,
          SpeakNpcId = 700078,
          TalkActionId = {
            [1] = "700078:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700078/7D2DC3CA"
        },
        [50003602] = {
          Content = "子爵大人要最好的皮料！要从最健壮的头狼身上剥下的顶级货！懂了吗蠢蛋！你的这些残次品只配给乞丐穿！",
          DialogueId = 50003602,
          Duration = 3,
          GUID = "7D2DC3F4",
          SpeakNpcId = 700079,
          TalkActionId = {
            [1] = "700079:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700079/7D2DC3F4"
        },
        [50003701] = {
          ContentFR = "Pop-corn ! Cigarettes ! Breuvages forts ! Vous avez perdu quelque chose ? J’ai rien vu, moi ! Je le jure !",
          DialogueId = 50003701,
          Duration = 4,
          GUID = "7D2DD432",
          SpeakNpcId = 700080,
          Subtitle = "Popcorn! Cigs! Booze! Lost something, you say? Didn't see it! I swear!",
          VoiceName = "voice/$Locale$/env/700080/7D2DD432"
        },
        [50003801] = {
          ContentFR = "Si chaque Charon pouvait vivre aussi longtemps que moi... je ne serais pas aussi seule.",
          DialogueId = 50003801,
          Duration = 7,
          GUID = "7D2DE49A",
          SpeakNpcId = 700081,
          Subtitle = "If every Charon could live as long as I have, I wouldn't feel so alone.",
          VoiceName = "voice/$Locale$/env/700081/7D2DE49A"
        },
        [50003901] = {
          ContentFR = "Ne vous fiez pas à mon bras cassé, je peux encore transporter des marchandises. Qu’est-ce qu’il vous faut ?",
          DialogueId = 50003901,
          Duration = 3,
          GUID = "7D2DF502",
          SpeakNpcId = 700082,
          Subtitle = "Welcome! And don't worry about my broken arm — I can still get you anything you need. So, what will it be?",
          TalkActionId = {
            [1] = "700082:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700082/7D2DF502"
        },
        [50004001] = {
          ContentFR = "... (Lunoeggy griffonne rapidement « Salut » sur sa petite ardoise.)",
          DialogueId = 50004001,
          Duration = 3,
          GUID = "7D2E056A",
          SpeakNpcId = 900008,
          Subtitle = "... (Lunoeggy quickly scribbles \"Hello\" on the board.)",
          VoiceName = "voice/$Locale$/env/900008/7D2E056A"
        },
        [50004101] = {
          ContentFR = "J’ai accepté une nouvelle mission récemment. Comme d’habitude : 80 pour toi, 20 pour moi. On part dès que j’ai fini cette bouteille, ça te va ?",
          DialogueId = 50004101,
          Duration = 3,
          GUID = "7D2E15D2",
          SpeakNpcId = 200015,
          Subtitle = "I've yet again been commissioned recently. Let's go with the usual 80-20 split and head out after I finish this bottle. What do you say?",
          TalkActionId = {
            [1] = "200015:Agree"
          },
          VoiceName = "voice/$Locale$/env/200015/7D2E15D2"
        },
        [50004201] = {
          ContentFR = "Envie d’un verre ?",
          DialogueId = 50004201,
          Duration = 3,
          GUID = "7D2E263A",
          SpeakNpcId = 200003,
          Subtitle = "Care for a drink?",
          VoiceName = "voice/$Locale$/char/Kami/vo_npc_01"
        },
        [50004301] = {
          ContentFR = "« ♪ Rossignol aux ailes brisées, ne pleure plus... »",
          DialogueId = 50004301,
          Duration = 3,
          GUID = "7D2E36A2",
          NextDialogue = 50004302,
          SpeakNpcId = 700142,
          Subtitle = "♪ \"Nightingale, broken wings, you can weep you can sleep...\"",
          TalkActionId = {
            [1] = "700142:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/200020/7D2E36A2"
        },
        [50004302] = {
          ContentFR = "« ♪ Cher petit rossignol, ne t’endors pas pour toujours... »",
          DialogueId = 50004302,
          Duration = 3,
          GUID = "7D2E36CC",
          SpeakNpcId = 700142,
          Subtitle = "♪ \"Nightingale, rise above, you will free you will see...\"",
          TalkActionId = {
            [1] = "700142:Explain02_End"
          },
          VoiceName = "voice/$Locale$/env/200020/7D2E36CC"
        },
        [50004401] = {
          ContentFR = "Va... va-t’en... si tu n’achètes pas de Phoxène, ne reste pas ici... et n’attire pas ces foutus soldats sur moi...",
          DialogueId = 50004401,
          Duration = 4,
          GUID = "7D2E470A",
          SpeakNpcId = 700113,
          Subtitle = "S-Scoot if you ain't buying any Phoxene... Lest your presence draws the soldiers' attention to us...",
          TalkActionId = {
            [1] = "700113:Disagree"
          },
          VoiceName = "voice/$Locale$/env/700113/7D2E470A"
        },
        [50004501] = {
          ContentFR = "Danse ! Allez, danse ! La vie n’a pas de sens, alors balance toutes tes préoccupations à la poubelle et danse avec moi jusqu’au matin !",
          DialogueId = 50004501,
          Duration = 3,
          GUID = "7D2E5772",
          SpeakNpcId = 700129,
          Subtitle = "Dance! Find your own groove! What's the meaning of life, you ask? Into the bin with all the stress and the fuss, and let's dance the night away!",
          VoiceName = "voice/$Locale$/env/700129/7D2E5772"
        },
        [50004601] = {
          ContentFR = "Monsieur... L’allocation impériale de ce mois-ci... Ah, elle n’a toujours pas été approuvée... <I>kof kof...</> Ce n’est rien, je vais avancer l’argent de ma poche... Désolé pour le dérangement...",
          DialogueId = 50004601,
          Duration = 4,
          GUID = "7D2E67DA",
          SpeakNpcId = 700070,
          Subtitle = "Sir, about this month's Imperial pension... Oh, you haven't received approval for that yet? *cough* *cough*... It's okay, I'll put my own money down first... Sorry to trouble you...",
          TalkActionId = {
            [1] = "700070:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700070/7D2E67DA"
        },
        [50004701] = {
          ContentFR = "Des infos sur des trésors... à ne manquer sous aucun prétexte !",
          DialogueId = 50004701,
          Duration = 3,
          GUID = "7D2E7842",
          SpeakNpcId = 700048,
          Subtitle = "Treasure the intel, never miss the thrill!",
          TalkActionId = {
            [1] = "700048:Agree"
          },
          VoiceName = "voice/$Locale$/env/700048/7D2E7842"
        },
        [50004801] = {
          ContentFR = "L’association des pêcheurs recrute ! Viens jeter l’hameçon avec nous !",
          DialogueId = 50004801,
          Duration = 3,
          GUID = "7D2E88AA",
          SpeakNpcId = 700048,
          Subtitle = "Come join the Fishermen's Mutual Aid Society, let's hook the fun!",
          TalkActionId = {
            [1] = "700048:Agree"
          },
          VoiceName = "voice/$Locale$/env/700048/7D2E88AA"
        },
        [50004901] = {
          ContentFR = "Tant que c’est bien désinfecté, ça fera un plat savoureux !",
          DialogueId = 50004901,
          Duration = 3,
          GUID = "7D2E9912",
          SpeakNpcId = 700116,
          Subtitle = "Properly disinfected, it can become a delicious dish!",
          TalkActionId = {
            [1] = "700116:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700116/7D2E9912"
        },
        [50005001] = {
          ContentFR = "Pff. Une nouvelle tête.",
          DialogueId = 50005001,
          Duration = 3,
          GUID = "7D2EA97A",
          SpeakNpcId = 700096,
          Subtitle = "Ugh, new face.",
          TalkActionId = {
            [1] = "700096:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700096/7D2EA97A"
        },
        [50005101] = {
          ContentFR = "Qu’est-ce que tu veux ?",
          DialogueId = 50005101,
          Duration = 3,
          GUID = "7D2EB9E2",
          SpeakNpcId = 700096,
          Subtitle = "What do you want?",
          TalkActionId = {
            [1] = "700096:Agree"
          },
          VoiceName = "voice/$Locale$/env/700096/7D2EB9E2"
        },
        [50005201] = {
          ContentFR = "Être fidèle à ses désirs... fidèle à ses désirs... fidèle à ses désirs... Mais qu’est-ce que ça veut dire, exactement, être fidèle à ses désirs...",
          DialogueId = 50005201,
          Duration = 4,
          GUID = "7D2ECA4A",
          SpeakNpcId = 700077,
          Subtitle = "Stay true to yourself. stay true to yourself... Ugh, what am I supposed to do to stay true to myself... ",
          TalkActionId = {
            [1] = "700077:Disagree"
          },
          VoiceName = "voice/$Locale$/env/700077/7D2ECA4A"
        },
        [50005301] = {
          Content = "开往下一站的列车即将出发，如有购票需求请您在此处办理——什么？没钱？那就一边儿去！",
          DialogueId = 50005301,
          Duration = 4,
          GUID = "7D2D1FBA",
          SpeakNpcId = 700147,
          Subtitle = "The train to the next station is about to depart. Please process your ticket purchase here — What's that? You've got no money? Then less dreaming, more moving, if you please!",
          TalkActionId = {
            [1] = "700147:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700021/7D2D1FBA"
        },
        [50005401] = {
          ContentFR = "Hahaha ! Elle court plus vite qu’une souris, dis donc !",
          DialogueId = 50005401,
          Duration = 3,
          GUID = "7D2EEB1A",
          SpeakNpcId = 700089,
          Subtitle = "Hahaha, she's running so fast, faster than a mouse!"
        },
        [50005501] = {
          ContentFR = "Eh, sale Charon, t’attends quoi ? Va donc rattraper ton petit morveux !",
          DialogueId = 50005501,
          Duration = 3,
          GUID = "7D2EFB82",
          SpeakNpcId = 700088,
          Subtitle = "Stinky Charon, what are you waiting for? Go after your little brat!",
          TalkActionId = {
            [1] = "700088:Confident_Start"
          }
        },
        [50005601] = {
          ContentFR = "Peut-être qu’il faudrait une planche un peu plus grande, non... ?",
          DialogueId = 50005601,
          Duration = 3,
          GUID = "7D2F0BEA",
          SpeakNpcId = 700143,
          Subtitle = "Should we get a bigger board..."
        },
        [50100101] = {
          Content = "针头线脑，香脂香囊，走过路过不要错过——",
          DialogueId = 50100101,
          GUID = "7D6B9BD2",
          Subtitle = "Needles, thread, balsams and sachets — does anything catch your eye?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6B9BD2"
        },
        [50100201] = {
          ContentFR = "Souvenirs typiques de Huaxu ! Ramenez-en pour vos proches !",
          DialogueId = 50100201,
          GUID = "7D6BAC3A",
          Subtitle = "Come, have a look! Fine souvenirs of Huaxu — take one home for your dear ones!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BAC3A"
        },
        [50100301] = {
          ContentFR = "De l’autre côté de la mer... à quoi ressemble donc le monde ?",
          DialogueId = 50100301,
          GUID = "7D6BBCA2",
          Subtitle = "I wonder... what the world beyond the sea is like.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BBCA2"
        },
        [50100311] = {
          ContentFR = "Le contremaître était d’humeur joyeuse hier, il nous a même donné une prime.",
          DialogueId = 50100311,
          GUID = "7D6BBE46",
          Subtitle = "The foreman was in a good mood yesterday — he even slipped us a little bonus.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BBE46"
        },
        [50100312] = {
          ContentFR = "Bah ! Avant de prendre la mer, le patron nous a offert le thé.",
          DialogueId = 50100312,
          GUID = "7D6BBE70",
          Subtitle = "Ha! That's nothing — the boss treated us to tea before we set off.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BBE70"
        },
        [50100401] = {
          ContentFR = "J’ai le dos en compote... faudrait vraiment que quelqu’un me fasse un bon massage...",
          DialogueId = 50100401,
          GUID = "7D6BCD0A",
          Subtitle = "Ugh, my back's killing me. Gotta get someone to work the knots out one of these days...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BCD0A"
        },
        [50100501] = {
          ContentFR = "Cette caisse est précieuse. Enveloppez-la d’un rembourrage avant de la déplacer.",
          DialogueId = 50100501,
          GUID = "7D6BDD72",
          Subtitle = "Careful with that crate — it's pricey. Wrap it in something soft before we move it.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BDD72"
        },
        [50100601] = {
          ContentFR = "Ces épingles et ornements sont magnifiques... mais je ne saurais même pas comment les porter.",
          DialogueId = 50100601,
          GUID = "7D6BEDDA",
          Subtitle = "These embossed hairpins are gorgeous... but I've no idea how to wear them right.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BEDDA"
        },
        [50100701] = {
          ContentFR = "Épices, soieries, thés, huiles, onguents, vaisselle... il y a trop de choix !",
          DialogueId = 50100701,
          GUID = "7D6BFE42",
          Subtitle = "Incense, silks, teas, oils, salves, fine wares... where do I even start?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6BFE42"
        },
        [50100801] = {
          ContentFR = "Plus de Lune Profonde ? Impossible ! La livraison date d’hier !",
          DialogueId = 50100801,
          GUID = "7D6C0EAA",
          Subtitle = "Out of Lunarose already? That can't be right — it just came in yesterday!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C0EAA"
        },
        [50100901] = {
          ContentFR = "Comptes vérifiés, marchandises rangées... la journée commence sans souci~",
          DialogueId = 50100901,
          GUID = "7D6C1F12",
          Subtitle = "All tallied, all tidy — looks like a smooth start today~",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C1F12"
        },
        [50101001] = {
          ContentFR = "Ainsi donc, la patrie des Tisse-Étoiles... Huaxu mérite vraiment sa réputation.",
          DialogueId = 50101001,
          GUID = "7D6C2F7A",
          Subtitle = "So this is where the Starweavers hail from... Huaxu really does live up to its name.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C2F7A"
        },
        [50101101] = {
          ContentFR = "Montagnes limpides, eaux claires... savourer un thé parfumé ici serait un pur bonheur~",
          DialogueId = 50101101,
          GUID = "7D6C3FE2",
          Subtitle = "Such a fine view... a cup of fragrant tea here would be pure delight.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C3FE2"
        },
        [50101201] = {
          ContentFR = "On avait dit que si tu perdais, tu me devais trois brochettes de tanghulu. Pas de triche !",
          DialogueId = 50101201,
          GUID = "7D6C504A",
          Subtitle = "A bet's a bet! You lost, so you owe me three tanghulu skewers. No backsies!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C504A"
        },
        [50101202] = {
          ContentFR = "D’accord ! Demain, quand maman me donnera de l’argent, je t’invite !",
          DialogueId = 50101202,
          GUID = "7D6C5074",
          Subtitle = "All right, all right — I'll get them for you when I've got my spending money tomorrow!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C5074"
        },
        [50101203] = {
          ContentFR = "Quai-aux-Étoiles devient de plus en plus animé chaque année...",
          DialogueId = 50101203,
          GUID = "7D6C509E",
          Subtitle = "Starwharf grows busier by the year.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C509E"
        },
        [50101301] = {
          ContentFR = "<I>Aïe !</> Tu m’as bousculée, ma coiffure est toute défaite !",
          DialogueId = 50101301,
          GUID = "7D6C60B2",
          Subtitle = "Oof! You knocked my hair loose!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C60B2"
        },
        [50101401] = {
          ContentFR = "Hé, jeune {性别:homme|femme}, regarde où tu marches. Heurter les gens, ce n’est pas bien.",
          DialogueId = 50101401,
          GUID = "7D6C711A",
          Subtitle = "Watch where you're going, young friend — don't go barging into people like that.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C711A"
        },
        [50101501] = {
          ContentFR = "Soieries rangées, grains stockés... alors seulement le cœur est en paix...",
          DialogueId = 50101501,
          GUID = "7D6C8182",
          Subtitle = "Silks in place, grain stacked neatly — only then can a man rest easy.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C8182"
        },
        [50101601] = {
          ContentFR = "Ginseng de lignée ancienne, gélatine d’âne centenaire ! Marchandise de choix, prix honnêtes !",
          DialogueId = 50101601,
          GUID = "7D6C91EA",
          Subtitle = "Finest ginseng and aged donkey-hide gelatin — fair prices! Come have a look!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6C91EA"
        },
        [50101701] = {
          ContentFR = "Les bonnes choses ne se bradent pas. Les connaisseurs savent reconnaître leur valeur.",
          DialogueId = 50101701,
          GUID = "7D6CA252",
          Subtitle = "Quality doesn't come cheap — those with taste know it's worth the coin.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CA252"
        },
        [50101801] = {
          ContentFR = "Porcelaine fragile, doucement, s’il vous plaît~",
          DialogueId = 50101801,
          GUID = "7D6CB2BA",
          Subtitle = "Careful now — fine porcelain. Easy does it, dear customer.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CB2BA"
        },
        [50101901] = {
          ContentFR = "Faites-moi encore un petit prix, et je la prends tout de suite.",
          DialogueId = 50101901,
          GUID = "7D6CC322",
          Subtitle = "Knock a little off and I'll take it right now.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CC322"
        },
        [50102001] = {
          ContentFR = "Ce vase est élégant... aucune fissure, n’est-ce pas ?",
          DialogueId = 50102001,
          GUID = "7D6CD38A",
          Subtitle = "Lovely vase... no cracks or chips, right?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CD38A"
        },
        [50102101] = {
          ContentFR = "Un peu de gâteau à l’osmanthe, s’il vous plaît. C’est pour ma femme~",
          DialogueId = 50102101,
          GUID = "7D6CE3F2",
          Subtitle = "A few osmanthus cakes, please. They're my wife's favorite.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CE3F2"
        },
        [50102201] = {
          ContentFR = "Ce tissu est si doux... parfait pour des sous-vêtements confortables.",
          DialogueId = 50102201,
          GUID = "7D6CF45A",
          Subtitle = "This fabric's soft and smooth — it'll make a fine lining, that's for sure.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6CF45A"
        },
        [50102301] = {
          ContentFR = "Par le regard du Seigneur Dragon, moi, Xueji, je fais le serment de ne jamais trahir Chuqing, sinon...",
          DialogueId = 50102301,
          GUID = "7D6D04C2",
          Subtitle = "By Lord Argent as my witness, I, Xueji, swear never to fail Chuqing, or I'll—",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D04C2"
        },
        [50102401] = {
          ContentFR = "Chut ! Ne dis pas la suite ! Je comprends...",
          DialogueId = 50102401,
          GUID = "7D6D152A",
          Subtitle = "Uh-uh! Don't say it! I know...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D152A"
        },
        [50102501] = {
          ContentFR = "Que le Seigneur Dragon d’Argent bénisse cette traversée et nous accorde une navigation sans heurts !",
          DialogueId = 50102501,
          GUID = "7D6D2592",
          Subtitle = "May Lord Argent grant this voyage fair winds and safe seas!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D2592"
        },
        [50102601] = {
          ContentFR = "Je prie pour que les anciens de ma famille restent en bonne santé, et que leur vie soit longue et paisible.",
          DialogueId = 50102601,
          GUID = "7D6D35FA",
          Subtitle = "May Lord Argent bless my family with good health and long, peaceful years.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D35FA"
        },
        [50102701] = {
          ContentFR = "Alors, Monsieur Ming, on dirait que les affaires ont été florissantes ces derniers temps ?",
          DialogueId = 50102701,
          GUID = "7D6D4662",
          Subtitle = "It's been a while, Ming. Been turning a decent profit lately?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D4662"
        },
        [50102702] = {
          ContentFR = "Oh, rien que de la chance ! Vos affaires à vous sont bien plus solides, Monsieur Jiang.",
          DialogueId = 50102702,
          GUID = "7D6D468C",
          Subtitle = "Ha! Pure luck, that's all. Your business runs steadier than mine any day.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D468C"
        },
        [50102801] = {
          ContentFR = "La prochaine expédition devrait pousser un peu plus au nord de Khemet...",
          DialogueId = 50102801,
          GUID = "7D6D56CA",
          Subtitle = "Next trip, I'll head a bit farther north of Khemet — see what's there.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D56CA"
        },
        [50102901] = {
          ContentFR = "J’ai pourtant consenti de très larges concessions... pourquoi les ventes ne décollent-elles toujours pas ?",
          DialogueId = 50102901,
          GUID = "7D6D6732",
          Subtitle = "I've slashed prices to the bone — why aren't sales picking up...?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D6732"
        },
        [50103001] = {
          ContentFR = "Je viens à peine de rejoindre les Tisse-Étoiles. J’espère pouvoir compter sur les conseils de mes aînés.",
          DialogueId = 50103001,
          GUID = "7D6D779A",
          Subtitle = "I'm new to the Starweavers — I'll be relying on your guidance.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D779A"
        },
        [50103002] = {
          ContentFR = "Nul besoin de tant de politesses. Si vous avez des questions, posez-les sans hésiter.",
          DialogueId = 50103002,
          GUID = "7D6D77C4",
          Subtitle = "You're too kind. Feel free to ask anything.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D77C4"
        },
        [50103003] = {
          ContentFR = "Selon vous, vaut-il mieux continuer à investir... ou se retirer pendant qu’il en est encore temps ?",
          DialogueId = 50103003,
          GUID = "7D6D77EE",
          Subtitle = "What do you think, then — double down, or cut my losses while I still can?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D77EE"
        },
        [50103101] = {
          ContentFR = "Le nouveau, là... tu crois qu’il est bien chargé ?",
          DialogueId = 50103101,
          GUID = "7D6D8802",
          Subtitle = "New face, eh? Do you think he's got any silver?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D8802"
        },
        [50103201] = {
          ContentFR = "Il vient d’un coin misérable. À mon avis, il n’a pas grand-chose sur lui.",
          DialogueId = 50103201,
          GUID = "7D6D986A",
          Subtitle = "From a poor patch, him. Don't think he can rub two coins together.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6D986A"
        },
        [50103301] = {
          ContentFR = "Venez jeter un œil, cher client. De véritables antiquités, tout juste sorties des collines.",
          DialogueId = 50103301,
          GUID = "7D6DA8D2",
          Subtitle = "Have a look, friend — authentic antiques, fresh off the dig.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DA8D2"
        },
        [50103401] = {
          ContentFR = "Avant, tout ça partait directement vers l’étranger. Ça nous a coûté cher de les rapatrier au pays !",
          DialogueId = 50103401,
          GUID = "7D6DB93A",
          Subtitle = "These pieces once went straight to foreign buyers. Took work and coin to bring them back!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DB93A"
        },
        [50103501] = {
          ContentFR = "Le vent porte la volonté de Taihao... Il suffit de calmer son esprit pour la ressentir.",
          DialogueId = 50103501,
          GUID = "7D6DC9A2",
          Subtitle = "The wind carries Taihao's will. Be still, and you'll feel it.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DC9A2"
        },
        [50103601] = {
          ContentFR = "Cinquante livres de Givrefeuille, trente de Printemps d’Excellence... Hé, hé, doucement par là-bas ! Les épices sont des denrées rares, manipulez-les avec soin !",
          DialogueId = 50103601,
          GUID = "7D6DDA0A",
          SpeakNpcId = 701039,
          Subtitle = "Fifty catties of Frostleaf, thirty of Vernal Prime — whoa, easy there! Those aromatics are rare stuff!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DDA0A"
        }
      }
    end
  },
  {
    MinKey = 50103701,
    MaxKey = 50107215,
    Loader = function()
      return {
        [50103701] = {
          ContentFR = "Souvenirs pour voyageurs étrangers ! À Huaxu, nul visiteur ne devrait passer à côté ! Sachets parfumés, éventails de soie, antiquités, trésors rares... tout ce que vous désirez !",
          DialogueId = 50103701,
          GUID = "7D6DEA72",
          SpeakNpcId = 701040,
          Subtitle = "Souvenirs for travellers! First time to Huaxu? Don't pass me by — sachets, folding fans, curios, trinkets, all the little treasures you could want!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DEA72"
        },
        [50103801] = {
          ContentFR = "Voyageurs venus du sud comme du nord, accordez-moi un instant. Laissez-moi vous conter les mille ans d’histoire de notre Quai-aux-Étoiles. En affaires, on aime que tout soit clair et net... eh bien, il en va de même pour notre passé.",
          DialogueId = 50103801,
          GUID = "7D6DFADA",
          SpeakNpcId = 701041,
          Subtitle = "Folks, lend me your ears for a moment — let me tell you the thousand-year tale of our very own Starwharf! Just as trade should be fair and square, so too should our past — plain and open for all to see.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6DFADA"
        },
        [50103901] = {
          ContentFR = "Écoutez bien. Le premier précepte des Neuf Chapitres de Dafeng énonce ceci : « Attenter au corps ou ôter la vie — cela est proscrit. »",
          DialogueId = 50103901,
          GUID = "7D6E0B42",
          SpeakNpcId = 701044,
          Subtitle = "Listen well. The first of the Nine Chapters says: \"To wound or kill — this must not be done.\"",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E0B42"
        },
        [50104001] = {
          ContentFR = "Comment on fait pour faire pousser des cornes... si je tire un peu... je tire... <I>aïe !</> Ça fait mal...",
          DialogueId = 50104001,
          GUID = "7D6E1BAA",
          SpeakNpcId = 701045,
          Subtitle = "How do I make my horns grow? Maybe if I give them a little tug... ow! That hurts!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E1BAA"
        },
        [50104101] = {
          ContentFR = "Je ne pensais pas que devenir Tisse-Étoiles offrait autant d’avantages ! Éternel Printemps a vraiment des moyens impressionnants.",
          DialogueId = 50104101,
          GUID = "7D6E2C12",
          SpeakNpcId = 701046,
          Subtitle = "I never realized being a Starweaver came with so many perks. EverSpring truly is remarkable.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E2C12"
        },
        [50104201] = {
          ContentFR = "Et si on ajoutait une salle de réception ? Ou même une petite cuisine ?",
          DialogueId = 50104201,
          GUID = "7D6E3C7A",
          SpeakNpcId = 701048,
          Subtitle = "How about adding a reception hall? Or perhaps a small kitchen?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E3C7A"
        },
        [50104301] = {
          ContentFR = "Grimper jusqu’à la lune ? Mais... c’est impossible, non ?",
          DialogueId = 50104301,
          GUID = "7D6E4CE2",
          SpeakNpcId = 701050,
          Subtitle = "Climb all the way to the moon? There's no way we can do that!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E4CE2"
        },
        [50104401] = {
          ContentFR = "Oh ! Ce Panneau aux Mille Étoiles a vraiment de l’âge !",
          DialogueId = 50104401,
          GUID = "7D6E5D4A",
          SpeakNpcId = 701051,
          Subtitle = "Ah... this Stellapass — now that's a piece of history!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E5D4A"
        },
        [50104501] = {
          ContentFR = "Ne pas se glorifier de la richesse, mais de la droiture ; ne pas se prévaloir du faste, mais de la vertu...",
          DialogueId = 50104501,
          GUID = "7D6E6DB2",
          SpeakNpcId = 701052,
          Subtitle = "Count not profit but righteousness as honour; count not splendour but virtue as nobility...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E6DB2"
        },
        [50104601] = {
          ContentFR = "Si vous avez la moindre question concernant les services d’Éternel Printemps, vous pouvez vous adresser à moi ici.",
          DialogueId = 50104601,
          GUID = "7D6E7E1A",
          SpeakNpcId = 701054,
          Subtitle = "If you have any enquiries regarding EverSpring's services, you may speak to me here.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E7E1A"
        },
        [50104701] = {
          ContentFR = "La confiture de Baies Boréales arrivée hier... pourquoi n’a-t-elle toujours pas passé l’inspection ? Rendez-moi ma marchandise !",
          DialogueId = 50104701,
          GUID = "7D6E8E82",
          SpeakNpcId = 701057,
          Subtitle = "The Borealberry jam that came in yesterday — why is it still held up in inspection? I need my goods, and I need them now!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E8E82"
        },
        [50104801] = {
          ContentFR = "Rentrer chez moi... mais où est ma maison, au juste ? Et ici... quel est donc cet endroit ?",
          DialogueId = 50104801,
          GUID = "7D6E9EEA",
          SpeakNpcId = 701059,
          Subtitle = "Home... but where is it? And where am I...?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6E9EEA"
        },
        [50104901] = {
          ContentFR = "« Âmes errantes, par décret et par vœu, quittez la confusion sans tarder. Hâtez-vous — selon la Loi céleste — vers la Terre de Félicité. »",
          DialogueId = 50104901,
          GUID = "7D6EAF52",
          SpeakNpcId = 701060,
          Subtitle = "By vow and decree we summon the lost: Cease your wandering; hasten unto the Realm of Bliss...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6EAF52"
        },
        [50105001] = {
          ContentFR = "Grand-père ! Si tu es revenu me voir, fais tomber une feuille sur ma tête !",
          DialogueId = 50105001,
          GUID = "7D6EBFBA",
          SpeakNpcId = 701061,
          Subtitle = "Grandpa! If you're really back, make a leaf fall on my head!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6EBFBA"
        },
        [50105101] = {
          ContentFR = "Cet arbre... il parle sans cesse !",
          DialogueId = 50105101,
          GUID = "7D6ED022",
          SpeakNpcId = 701063,
          Subtitle = "This tree! It keeps talking!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6ED022"
        },
        [50105201] = {
          ContentFR = "Toi aussi... tu viens de l’extérieur ?",
          DialogueId = 50105201,
          GUID = "7D6EE08A",
          SpeakNpcId = 701065,
          Subtitle = "You're from outside too... aren't you?",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6EE08A"
        },
        [50105301] = {
          ContentFR = "Hé, {性别:gamin|gamine}. Le Marché Voilé, c’est pas un endroit où on se promène au hasard.",
          DialogueId = 50105301,
          GUID = "7D6EF0F2",
          SpeakNpcId = 701066,
          Subtitle = "Oi, kid — Haze Market isn't the sort of place you just stroll into for fun.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6EF0F2"
        },
        [50105401] = {
          ContentFR = "Cette fissure, faut la colmater vite. Si le bois trempe encore quelques mois, le cœur va pourrir complètement.",
          DialogueId = 50105401,
          GUID = "7D6F015A",
          SpeakNpcId = 701067,
          Subtitle = "Best patch that seam up soon... leave her soaking a few more months and the core'll rot clean through.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F015A"
        },
        [50105501] = {
          ContentFR = "<I>Hrr... hrr...</>",
          DialogueId = 50105501,
          GUID = "7D6F11C2",
          SpeakNpcId = 701071,
          Subtitle = "Huff... Huff...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F11C2"
        },
        [50105601] = {
          ContentFR = "Un coup froid, un coup chaud... Dire que mon arrière-grand-mère racontait qu’ici, c’était un endroit doux, où les fleurs s’épanouissaient au printemps !",
          DialogueId = 50105601,
          GUID = "7D6F222A",
          SpeakNpcId = 701072,
          Subtitle = "Hot one minute, freezing the next... My great-grandmother always said it used to be spring all year round.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F222A"
        },
        [50105701] = {
          ContentFR = "C’est ici que je vais allumer l’encens. Le Seigneur Dragon d’Argent se dressera comme dans les mythes, et il exterminera cette bête immonde jusqu’au dernier souffle !",
          DialogueId = 50105701,
          GUID = "7D6F3292",
          SpeakNpcId = 701073,
          Subtitle = "Here we are! Once I light the incense, Lord Argent will surely descend and wipe that wicked beast out for good — just like in the old tales!",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F3292"
        },
        [50105801] = {
          ContentFR = "Le Panneau aux Mille Étoiles fonctionne normalement... À bien y réfléchir, l’échéance de la prochaine maintenance approche.",
          DialogueId = 50105801,
          GUID = "7D6F42FA",
          SpeakNpcId = 701042,
          Subtitle = "The Stellapass is running fine. Come to think of it, it's about due for its next maintenance...",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F42FA"
        },
        [50105901] = {
          ContentFR = "Hé, Patron Long, ça faisait longtemps ! Tu veux goûter le nouveau thé Aiguilles d’argent ? Il est délicieusement parfumé~",
          DialogueId = 50105901,
          GUID = "7D6F5362",
          SpeakNpcId = 701055,
          Subtitle = "Long, it's been a while. Care to try the new Silver Needle? The fragrance is exquisite~",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F5362"
        },
        [50106001] = {
          ContentFR = "Depuis quand ce grand arbre se dresse-t-il ici... ?",
          DialogueId = 50106001,
          GUID = "7D6F63CA",
          SpeakNpcId = 701062,
          Subtitle = "Hmm... I wonder how long this tree has been standing here.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F63CA"
        },
        [50106101] = {
          ContentFR = "Ces derniers temps, pas mal de nouvelles têtes traînent au Marché Voilé. Quand ils marchandent, ils bavardent trop... ça manque sérieusement de tenue.",
          DialogueId = 50106101,
          GUID = "7D6F7432",
          SpeakNpcId = 701068,
          Subtitle = "Quite a few new faces in Haze Market of late — far too chatty when they trade. No class whatsoever.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F7432"
        },
        [50106201] = {
          ContentFR = "La prochaine fois que je rencontrerai Maître Qiu, ce sera dans un salon de thé élégant. Pas dans un endroit... comme celui-ci.",
          DialogueId = 50106201,
          GUID = "7D6F849A",
          SpeakNpcId = 701070,
          Subtitle = "Next time I meet Mr Qiu, it'll have to be somewhere respectable — a proper teahouse, not... whatever this place is.",
          VoiceName = "voice/$Locale$/env/Ver0101/7D6F849A"
        },
        [50106301] = {
          ContentFR = "Les Œufs porte-bonheur ont de nouveaux modèles ! Ça te dit d’en tenter un ?",
          DialogueId = 50106301,
          Duration = 5,
          GUID = "7D6F9502",
          SpeakNpcId = 900012,
          Subtitle = "New Lucky Egg variants just dropped! Fancy giving one a spin?"
        },
        [50107001] = {
          Content = "我的钱袋子呢？我的钱袋子怎么不见了？",
          DialogueId = 50107001,
          GUID = "7D7007DA",
          Subtitle = "Where's my purse!? I had it a second ago..."
        },
        [50107002] = {
          Content = "定是那油嘴滑舌的小贩子偷的！",
          DialogueId = 50107002,
          GUID = "7D700804",
          Subtitle = "I'll wager it was that fast-talking hawker."
        },
        [50107003] = {
          Content = "诶？怎么就是找不到呢？",
          DialogueId = 50107003,
          GUID = "7D70082E",
          Subtitle = "Hmm... where could it be?"
        },
        [50107004] = {
          Content = "我早跟你说了这街上有贼，之前有人看到了，一个小女孩，皮肤黑黢黢的！",
          DialogueId = 50107004,
          GUID = "7D700858",
          Subtitle = "Told you — there are pickpockets about on this street. Someone saw a little girl earlier — face all smeared with grime."
        },
        [50107005] = {
          Content = "博山香行周年店庆，来店订购香料满十赠五~",
          DialogueId = 50107005,
          GUID = "7D700882",
          Subtitle = "Boshan Incense House anniversary offer! Buy ten, get five free!"
        },
        [50107006] = {
          Content = "你要知道一点——我对香料品质的要求很高，晒得太干我不要，香味散得太过我也不要。",
          DialogueId = 50107006,
          GUID = "7D7008AC",
          Subtitle = "Just so we're clear: I'm very particular about incense. If it's too dry, I won't take it. And if the scent fades too fast, I'm not interested either."
        },
        [50107007] = {
          Content = "之前定的那批香料，品质相当不错，这次就按原先的订单再来一批，还是送到我家中。",
          DialogueId = 50107007,
          GUID = "7D7008D6",
          Subtitle = "The incense you sent last time was excellent. I'll have more of the same — delivered to my house again."
        },
        [50107008] = {
          Content = "噫！好酸的果干！",
          DialogueId = 50107008,
          GUID = "7D700900",
          Subtitle = "Ugh! That's really sour!"
        },
        [50107009] = {
          Content = "为什么没人来试试我做的糕点呢……难道是卖相不太好？可是味道很香呀……",
          DialogueId = 50107009,
          GUID = "7D70092A",
          Subtitle = "Why won't anyone try my pastries...? Is it the way they look? But they smell amazing..."
        },
        [50107010] = {
          Content = "华胥特色小吃，吃一口念一年！",
          DialogueId = 50107010,
          GUID = "7D700954",
          Subtitle = "Huaxu special snacks! One bite and you'll be back for more!"
        },
        [50107011] = {
          Content = "各色果干，酸甜可口，欢迎试吃品尝~",
          DialogueId = 50107011,
          GUID = "7D70097E",
          Subtitle = "Candied fruit! Sweet and tangy — plenty to choose from! Free samples — have a taste!"
        },
        [50107012] = {
          Content = "那里曾是家布鞋店，现在却已经改成了木雕摊……东市啊，大变样咯！",
          DialogueId = 50107012,
          GUID = "7D7009A8",
          Subtitle = "That used to be a little cloth-shoe shop. Now look at it — a woodcarver's stall... East Market's changed so much."
        },
        [50107013] = {
          Content = "这位客人，看你身材匀称，要不要来试试我们千绣阁里的成衣？",
          DialogueId = 50107013,
          GUID = "7D7009D2",
          Subtitle = "Good day! You'd look lovely in our designs. Fancy trying something on at Qianxiu Pavilion?"
        },
        [50107014] = {
          Content = "同福饭馆菜品上新，外域高人指点，香料入菜，佳肴更添新风味。",
          DialogueId = 50107014,
          GUID = "7D7009FC",
          Subtitle = "New dishes at Tongfu Eatery! Incense in the cooking — an aroma you've never tasted before! A secret technique taught by a master chef from distant lands!"
        },
        [50107015] = {
          Content = "香料做菜？听起来奇奇怪怪的，这做出来的东西能好吃吗？",
          DialogueId = 50107015,
          GUID = "7D700A26",
          Subtitle = "Incense... in food? That can't be right. Who'd think that tastes good?"
        },
        [50107016] = {
          Content = "同福饭馆的厨子发了疯，居然把莞婆娘碾碎包进丸子里！",
          DialogueId = 50107016,
          GUID = "7D700A50",
          Subtitle = "The chef at Tongfu Eatery's lost his mind! He's crushed up Wan Beetles and stuffed them into the meatballs!"
        },
        [50107017] = {
          Content = "一天到晚就知道折腾看似新颖实则无用的花招，可别忘了华胥美食的精髓是什么！",
          DialogueId = 50107017,
          GUID = "7D700A7A",
          Subtitle = "All sparkle, no substance. Have they forgotten what Huaxu cooking's really about!?"
        },
        [50107018] = {
          Content = "秀芳……不要离开我……秀芳……",
          DialogueId = 50107018,
          GUID = "7D700AA4",
          Subtitle = "Xiufang... don't leave me... Xiufang..."
        },
        [50107019] = {
          Content = "把翠屏雀搬来了皓京城？！还有此等奇事！",
          DialogueId = 50107019,
          GUID = "7D700ACE",
          Subtitle = "They brought Emeraldfinches to Haojing!? That's unbelievable!"
        },
        [50107020] = {
          Content = "雀翎茗轩……是在这里吗？",
          DialogueId = 50107020,
          GUID = "7D700AF8",
          Subtitle = "Trailing Glory Teahouse... is it round here somewhere?"
        },
        [50107021] = {
          Content = "东市雀翎茗轩开张，凡携亲眷者入座，皆送花茶一壶。",
          DialogueId = 50107021,
          GUID = "7D700B22",
          Subtitle = "Trailing Glory Teahouse — now open in East Market! Bring the family — free pot of flower tea!"
        },
        [50107022] = {
          Content = "呜呜……龙君不公啊！这茶舍还未开张，怎料运来的雀儿都不见踪影，我该如何是好……",
          DialogueId = 50107022,
          GUID = "7D700B4C",
          Subtitle = "(sobbing) No... Lord Argent, it's not fair... My teahouse hasn't even opened yet, and the finches we ordered have vanished without a trace... What am I supposed to do...?"
        },
        [50107023] = {
          Content = "游船游船，十文一趟，排队购票，客满即发。",
          DialogueId = 50107023,
          GUID = "7D700B76",
          Subtitle = "Boat rides! Ten coins a trip! Tickets here — line up! Once the boat's full, we're off!"
        },
        [50107024] = {
          Content = "这皓京城的地形，怎么看怎么觉得邪乎呢……",
          DialogueId = 50107024,
          GUID = "7D700BA0",
          Subtitle = "Something's off about Haojing's layout... the more I look, the stranger it feels."
        },
        [50107025] = {
          Content = "想当初咱这湖边多清净？钓竿一放，不消半个时辰就能钓上好几尾大鱼。",
          DialogueId = 50107025,
          GUID = "7D700BCA",
          Subtitle = "Remember when it used to be quiet round here? Drop a line and you'd pull up a couple of big ones in under half an hour."
        },
        [50107026] = {
          Content = "若是能把这五禽戏练好，你平日的那些小病小灾，都可一并消弭！",
          DialogueId = 50107026,
          GUID = "7D700BF4",
          Subtitle = "If you really commit to practising the Five-Animal Frolics, all those little aches and everyday niggles will ease on their own."
        },
        [50107027] = {
          Content = "他们还真把那五禽戏当真了不成？",
          DialogueId = 50107027,
          GUID = "7D700C1E",
          Subtitle = "They don't seriously believe in that Five-Animal Frolics stuff, do they?"
        },
        [50107028] = {
          Content = "自己要早起练功也便罢了，为何还要拖着我早起……呵欠……",
          DialogueId = 50107028,
          GUID = "7D700C48",
          Subtitle = "If you want to get up early and practise, fine... but why drag me out of bed too? Yaaawn..."
        },
        [50107029] = {
          Content = "这皓京城还没有我说不成的媒！",
          DialogueId = 50107029,
          GUID = "7D700C72",
          Subtitle = "In Haojing, there isn't a match I can't make!"
        },
        [50107030] = {
          Content = "我这般主动找人说亲，会不会……被他看出来了？",
          DialogueId = 50107030,
          GUID = "7D700C9C",
          Subtitle = "If I bring up the match... will he see right through me?"
        },
        [50107031] = {
          Content = "咱皓京人，除了吃就是喝，没别的~",
          DialogueId = 50107031,
          GUID = "7D700CC6",
          Subtitle = "Us Haojing lot — apparently all we do is eat and drink. That's our life~"
        },
        [50107032] = {
          Content = "瞧你这孩子，走起路来慌慌张张，留心点别踩到路上的石子了！",
          DialogueId = 50107032,
          GUID = "7D700CF0",
          Subtitle = "Look at you, rushing about. Careful now — don't go tripping on the stones."
        },
        [50107033] = {
          Content = "什么？涨了这么多？我没看错吧？",
          DialogueId = 50107033,
          GUID = "7D700D1A",
          Subtitle = "What!? It's gone up that much!? You can't be serious."
        },
        [50107034] = {
          Content = "父亲向来放不下娘亲，想必在天上也是不愿看见娘亲落泪的。",
          DialogueId = 50107034,
          GUID = "7D700D44",
          Subtitle = "Ma... Pa loved you so much. Wherever he is, he wouldn't want to see you in tears."
        },
        [50107035] = {
          Content = "现在都什么年代了，哪有在丧礼上请乐队的人家！",
          DialogueId = 50107035,
          GUID = "7D700D6E",
          Subtitle = "What were you thinking? Who books a band for a funeral these days!?"
        },
        [50107036] = {
          Content = "林兄，昔日你我诗会相逢，一见如故。高山流水，难遇知音，这杯，我敬你！",
          DialogueId = 50107036,
          GUID = "7D700D98",
          Subtitle = "Lin... from the moment we met at that poetry gathering, it felt like we'd known each other for years. You don't come by friends like that often. Here's to you, brother."
        },
        [50107037] = {
          Content = "草木深胡同……是在这里？还是……",
          DialogueId = 50107037,
          GUID = "7D700DC2",
          Subtitle = "Overgrown Hutong... should be this way...? Or..."
        },
        [50107038] = {
          Content = "你说那家私房菜？我是听说过，但那家地方小，难订座，现下去问恐怕是吃不上了。",
          DialogueId = 50107038,
          GUID = "7D700DEC",
          Subtitle = "That little tucked-away place? Yeah, I've heard of it. It's tiny — hard to get a table. If we go now, we'll probably be out of luck."
        },
        [50107039] = {
          Content = "若非有仙人指路，怎知这小巷深处竟藏着这庖厨圣地！",
          DialogueId = 50107039,
          GUID = "7D700E16",
          Subtitle = "Must be a miracle I found this place. Who knew there'd be food this good hidden down a little alley like this?"
        },
        [50107040] = {
          Content = "老张啊，你那只八哥，今日居然念了几句诗，是不是你孙子整日在家背书被它听着学了去？",
          DialogueId = 50107040,
          GUID = "7D700E40",
          Subtitle = "Zhang, your mynah was rattling off a few lines of poetry today. Been listening to your grandson practising at home, has it?"
        },
        [50107041] = {
          Content = "凡夫俗子溜凡羽俗鸟，他们那些鸟，能有我这只厉害吗？",
          DialogueId = 50107041,
          GUID = "7D700E6A",
          Subtitle = "Common folk, showing off their plain little birds, as if any of them could hold a candle to mine."
        },
        [50107042] = {
          Content = "车三进六，将军！老友，这局棋，你该怎么破？",
          DialogueId = 50107042,
          GUID = "7D700E94",
          Subtitle = "Right... chariot. Check! Go on then — how are you getting out of this, my friend?"
        },
        [50107043] = {
          Content = "叫上陈老太太，咱们也在家里聚上一聚，打打骨牌？",
          DialogueId = 50107043,
          GUID = "7D700EBE",
          Subtitle = "Shall we invite Mrs Chen round? Have a little get-together at ours — play a bit of dominoes."
        },
        [50107044] = {
          Content = "我看你是蹬鼻子上脸，三天不打上房揭瓦！给我回去复习功课！",
          DialogueId = 50107044,
          GUID = "7D700EE8",
          Subtitle = "You're really asking for it! I turn my back for five minutes and look at you! Home. Now. And do your homework!"
        },
        [50107045] = {
          Content = "我来了！不好意思，今天翻墙出来被阿娘逮到了……",
          DialogueId = 50107045,
          GUID = "7D700F12",
          Subtitle = "Sorry I'm late... I tried to sneak out, but Mum caught me..."
        },
        [50107046] = {
          Content = "三……二……一……躲好了吗？无由生马上要出来抓你们咯？",
          DialogueId = 50107046,
          GUID = "7D700F3C",
          Subtitle = "Three... two... one... Ready or not — here comes Wishen!"
        },
        [50107047] = {
          Content = "今年的税账至今还在统计之中，明年的汇算眼见着也要来了……真是忙到头晕眼花。",
          DialogueId = 50107047,
          GUID = "7D700F66",
          Subtitle = "We're still balancing this year's tax ledgers, and next year's audit's already looming... I'm run off my feet."
        },
        [50107048] = {
          Content = "昨夜通宵整理典籍，今日双眼昏花，恐一蹬腿就要去往虞泉了！",
          DialogueId = 50107048,
          GUID = "7D700F90",
          Subtitle = "I was up all night poring over the old texts. My eyes are shot — at this rate, I'll be at the Spring of Yu before long."
        },
        [50107049] = {
          Content = "奉香大典意味着什么？意味着休假呀！我一直想去海伯利亚看雪……",
          DialogueId = 50107049,
          GUID = "7D700FBA",
          Subtitle = "You know what the Grand Incense Rite means? Time off! I've always wanted to go to Hyperborea and see the snow..."
        },
        [50107050] = {
          Content = "这般数据出现在这栏不太应当，莫非是填错了？",
          DialogueId = 50107050,
          GUID = "7D700FE4",
          Subtitle = "These numbers shouldn't be in this column... did I put that in wrong?"
        },
        [50107051] = {
          Content = "最近的日子，真是难得的清闲啊~",
          DialogueId = 50107051,
          GUID = "7D70100E",
          Subtitle = "Lately, it's been a rare spell of peace and quiet."
        },
        [50107052] = {
          Content = "下次遇到这种事情记得早些来泉通司，硬拖只会让事态恶化。",
          DialogueId = 50107052,
          GUID = "7D701038",
          Subtitle = "Next time this happens, come to the Hall of Founts straight away. Letting it drag on will only make things worse."
        },
        [50107053] = {
          Content = "祀香阁今年为何额外申请了一笔经费，是作何用处的？",
          DialogueId = 50107053,
          GUID = "7D701062",
          Subtitle = "The Hall of Incense is requesting additional funding this year — what's it for?"
        },
        [50107054] = {
          Content = "搭台子，修香炉，后续还有各种开销，我都递交申请了，只是拨款何时能来？",
          DialogueId = 50107054,
          GUID = "7D70108C",
          Subtitle = "There's the stage to build, the censer to repair — and that's just the start. I've filed all the requests, so when's the funding coming through?"
        },
        [50107055] = {
          Content = "是，就是往西郊那个方向，鬼鬼祟祟的，看起来不像什么好人。",
          DialogueId = 50107055,
          GUID = "7D7010B6",
          Subtitle = "Yeah — out west, near the outskirts. Just hanging around, acting shifty. Doesn't look like a decent sort."
        },
        [50107056] = {
          Content = "西郊西郊西郊，为何几封投诉信，来来回回都在提西郊？",
          DialogueId = 50107056,
          GUID = "7D7010E0",
          Subtitle = "The western outskirts again? Why is it always the western outskirts with these complaints?"
        },
        [50107057] = {
          Content = "快给我来碗茶水，刚从西郊回来，渴死我了！",
          DialogueId = 50107057,
          GUID = "7D70110A",
          Subtitle = "Quick — get me some tea! I've just come back from the western outskirts. I'm dying of thirst!"
        },
        [50107058] = {
          Content = "嗯，是说您负责运输的一船货物在码头丢失了……不是货物？那是……翠屏雀？！",
          DialogueId = 50107058,
          GUID = "7D701134",
          Subtitle = "Right. So the shipment you were carrying went missing at the docks. Not cargo? Then what was it— a whole boatload of Emeraldfinches!?"
        },
        [50107059] = {
          Content = "它到底是怎么跑出去的呢？",
          DialogueId = 50107059,
          GUID = "7D70115E",
          Subtitle = "How on earth did it get out?"
        },
        [50107060] = {
          Content = "找不回来了……一切努力都付之东流了……",
          DialogueId = 50107060,
          GUID = "7D701188",
          Subtitle = "They're gone... I'm done. All that work, down the drain..."
        },
        [50107061] = {
          Content = "已经找到一只了？在民居的屋顶上？到底是怎么飞上去的？！",
          DialogueId = 50107061,
          GUID = "7D7011B2",
          Subtitle = "They've already found one? On someone's roof? How on earth did it get up there!?"
        },
        [50107062] = {
          Content = "千绣阁今年的订货量又涨了许多，咱们的绣品在皓京城里很受欢迎呢~",
          DialogueId = 50107062,
          GUID = "7D7011DC",
          Subtitle = "Qianxiu Pavilion's orders are up again this year... Our embroidery's doing really well in Haojing."
        },
        [50107063] = {
          Content = "此趟运输甜果只有百分之三损毁？甚好甚好~",
          DialogueId = 50107063,
          GUID = "7D701206",
          Subtitle = "Only three per cent loss on this fruit shipment? Good. Very good."
        },
        [50107064] = {
          Content = "太皓神君的纹样大家早就看腻啦~一点新意也没有。",
          DialogueId = 50107064,
          GUID = "7D701230",
          Subtitle = "Aw, it's that same Lord Argent motif again. Nothing fresh about it."
        },
        [50107065] = {
          Content = "各位好姐姐好哥哥们，现在呢就已经到了咱们皓京，也是咱们华胥呢，最繁华的地方~",
          DialogueId = 50107065,
          GUID = "7D70125A",
          Subtitle = "And here we are — Haojing at last! This is the busiest, most vibrant part of Huaxu~"
        },
        [50107066] = {
          Content = "三百九十九？！皓京三天两晚包吃包住包来回船票只需要三百九十九？",
          DialogueId = 50107066,
          GUID = "7D701284",
          Subtitle = "399!? Three days and two nights in Haojing, full board, plus return boat fare — the whole package for 399!?"
        },
        [50107067] = {
          Content = "恁大一个皓京城，比我屋头看着气派多了哟！",
          DialogueId = 50107067,
          GUID = "7D7012AE",
          SpecialConversation = "偏川普",
          Subtitle = "Cor, Haojing's huge! Makes my place back home look tiny."
        },
        [50107068] = {
          Content = "别靠过来！我……呕……我……头好晕……怎么有三个太阳……呕！",
          DialogueId = 50107068,
          GUID = "7D7012D8",
          Subtitle = "Don't come any closer... I... ugh... my head's spinning. Why are there three suns? ...Bleurgh."
        },
        [50107069] = {
          Content = "水龙车我先带走了。不知道哪个龟孙以为是普通木桶，居然往里面放香油，被老鼠啃得面目全非。",
          DialogueId = 50107069,
          GUID = "7D701302",
          Subtitle = "I'll take the fire pump cart with me for now. Some bloody idiot thought it was a wooden barrel and poured sesame oil into it. Now the rats have got into it, and it's a right mess."
        },
        [50107070] = {
          Content = "匠矩阁的师傅已经来将水龙车全部取走了吗？太麻烦他们了。",
          DialogueId = 50107070,
          GUID = "7D70132C",
          Subtitle = "The artisans from the Hall of Craft have already collected all the fire pump carts? Sorry. I didn't mean to make extra work for them."
        },
        [50107071] = {
          Content = "为何匠矩阁的人回回要来参商港跑个好几趟，来回拉扯不嫌麻烦吗？",
          DialogueId = 50107071,
          GUID = "7D701356",
          Subtitle = "Why do the Hall of Craft lot keep going back and forth to the Port of Parting Stars? Don't they ever get tired of it?"
        },
        [50107072] = {
          Content = "凌波微步，且看我腾空起，驾云去，身似飞雁过南关，蜻蜓点水不留痕！嘿！哈！",
          DialogueId = 50107072,
          GUID = "7D701380",
          Subtitle = "Ripple-Step! Watch this — up I go, and off I fly! Riding the clouds! Fast as a swallow, light as a dragonfly on water. You won't even see me! Hah! Hyah!"
        },
        [50107073] = {
          Content = "天一热，潮一涨，这浸在水中的部分就开始疯狂长苔，转动都费劲……",
          DialogueId = 50107073,
          GUID = "7D7013AA",
          Subtitle = "Soon as it gets hot and the tide comes in, the parts sitting in the water get coated in algae. Then it's a struggle just to get the thing turning."
        },
        [50107074] = {
          Content = "要不是他们把水车停了下来，怎会有这多事端？",
          DialogueId = 50107074,
          GUID = "7D7013D4",
          Subtitle = "If they hadn't stopped the waterwheel, we wouldn't be dealing with this mess."
        },
        [50107075] = {
          Content = "你需谨记六字——明法、公心、勤谨。",
          DialogueId = 50107075,
          GUID = "7D7013FE",
          Subtitle = "Remember these three virtues: respect the law, uphold fairness, and practise diligence."
        },
        [50107076] = {
          Content = "每至夜半三更，船舶抵港，那船工吆喝声、铁链撞击声、货箱搬运声，直吵得人不得安睡！",
          DialogueId = 50107076,
          GUID = "7D701428",
          SpecialConversation = "该npc为一期印象npc",
          Subtitle = "Every night, well past midnight, the ships come in. Dockhands shouting, chains clanking, crates scraping along... It's so loud I can't get a wink of sleep!"
        },
        [50107077] = {
          Content = "游船游船，十文一趟，排队购票，客满即发。",
          DialogueId = 50107077,
          GUID = "7D701452",
          SpecialConversation = "该npc与刘福最好为一人",
          Subtitle = "Boat rides! Ten coins a trip! Tickets here — line up! Once the boat's full, we're off!"
        },
        [50107078] = {
          Content = "稍……稍等一下……我查一下刚买的《华胥问候语录大全》。",
          DialogueId = 50107078,
          GUID = "7D70147C",
          SpecialConversation = "外国人",
          Subtitle = "J—Just a moment... let me check this guide to Huaxu greetings I just bought."
        },
        [50107079] = {
          Content = "他大舅母，晚上做了什么好吃的？可是来这儿散散步，消消食？",
          DialogueId = 50107079,
          GUID = "7D7014A6",
          Subtitle = "Evening. Had something nice for dinner? Out for a little stroll to walk it off?"
        },
        [50107080] = {
          Content = "一，二，三，铁柱呢？铁柱为何不在？你们来的时候看到他了吗？",
          DialogueId = 50107080,
          GUID = "7D7014D0",
          Subtitle = "One, two, three... Where's Tiezhu? Why isn't he here? Did you see him on the way?"
        },
        [50107081] = {
          Content = "尘香袅袅龙君现，典前争辉竞纷纭。奉香大典特别活动——灯谜会，待君赏玩！",
          DialogueId = 50107081,
          GUID = "7D7014FA",
          Subtitle = "\"Where incense hangs on the air, Lord Argent descends; on the eve of the Rite, the forecourt is awash with light.\" In honour of the Rite, we present a special event: the Lantern Riddle Fair. Do come and enjoy it."
        },
        [50107082] = {
          Content = "妈妈我到皓京了……",
          DialogueId = 50107082,
          GUID = "7D701524",
          Subtitle = "Mum... I made it to Haojing..."
        },
        [50107083] = {
          Content = "这里面不能进去吗？我买票也不行？那有什么办法能进去看看？我想见白龙神君。",
          DialogueId = 50107083,
          GUID = "7D70154E",
          Subtitle = "What d'you mean I can't go in? I'll buy a ticket! No? So how do I get in, then? I want to see Lord Argent."
        },
        [50107084] = {
          Content = "你看！只要内心足够虔诚，望向执律阁顶之时，就会看到白龙神君在云间遨游。",
          DialogueId = 50107084,
          GUID = "7D701578",
          Subtitle = "Look over there, above the Hall of Adjudication. See? If you're truly devout, you'll see Lord Argent coiling through the clouds."
        },
        [50107085] = {
          Content = "朝报朝报，茶不思饭不想只想看朝报，皓京独家新闻，绝对真实绝对劲爆！",
          DialogueId = 50107085,
          GUID = "7D7015A2",
          Subtitle = "Morning Paper! Morning Paper! Fresh off the press! Haojing exclusives — spicy stuff, and all true!"
        },
        [50107086] = {
          Content = "这字乍一看好似和海伯利亚那边没什么区别，可凑在一起为什么完全看不懂……",
          DialogueId = 50107086,
          GUID = "7D7015CC",
          SpecialConversation = "外国人",
          Subtitle = "At first glance, these characters look a lot like the ones back home in Hyperborea. So why can't I make head nor tail of it once they're put together?"
        },
        [50107087] = {
          Content = "您听我说，您去一个地方，吃什么玩什么，都是次要，主要的是要来感受当地的氛围，您说对不对？",
          DialogueId = 50107087,
          GUID = "7D7015F6",
          Subtitle = "Hear me out. When you go somewhere, the food and sights come second. It's the atmosphere that matters. You've got to get a feel for the place. Right?"
        },
        [50107088] = {
          Content = "退一万步说，在人家办事处门口宣传这些也不合适吧……",
          DialogueId = 50107088,
          GUID = "7D701620",
          Subtitle = "Even if you mean well, it's a bit much to be hawking that right outside the offices..."
        },
        [50107089] = {
          Content = "我家老婆子好好地走在街上，他路也不看，直接推着车撞了过来。",
          DialogueId = 50107089,
          GUID = "7D70164A",
          Subtitle = "My wife was just walking down the street, minding her own business. Then this bloke comes barreling along, not looking where he's going, and rams his cart straight into her."
        },
        [50107090] = {
          Content = "以香论道法，坐实众生象，天地为共生，万物与我一……",
          DialogueId = 50107090,
          GUID = "7D701674",
          Subtitle = "Through incense, the Way is spoken; the forms of all beings take shape. Heaven and earth breathe in unison. All things and I, as one..."
        },
        [50107091] = {
          Content = "为人在世，奉天命当如沙洲，勤而学当如竹溪先生。",
          DialogueId = 50107091,
          GUID = "7D70169E",
          Subtitle = "To live well, keep to Heaven's Mandate, steadfast as Mr Shazhou. To learn well, keep to your studies, diligent as Master Zhuxi."
        },
        [50107092] = {
          Content = "我何时曾说我亲眼见过竹溪先生？我说的是父亲年幼之时，曾在学院听竹溪先生传授最后一课。",
          DialogueId = 50107092,
          GUID = "7D7016C8",
          Subtitle = "When did I ever say I met Master Zhuxi in person? What I said was this: when my father was young, he heard Master Zhuxi give his final lecture at the academy."
        },
        [50107093] = {
          Content = "吵死了……这怎么让人背书！",
          DialogueId = 50107093,
          GUID = "7D7016F2",
          Subtitle = "They're too loud... How's anyone meant to learn like this!?"
        },
        [50107094] = {
          Content = "所谓理一，即天地万物都只有一个理，所谓分殊，即千差万殊的事物都是一个理的体现。",
          DialogueId = 50107094,
          GUID = "7D70171C",
          Subtitle = "\"One principle\" is the idea that heaven, earth, and all things share a single underlying truth. \"Many expressions\" means that the countless differences we see are simply manifestations of that same truth."
        },
        [50107095] = {
          Content = "五味万殊，而大同于美；曲变虽众，亦大同于和；子性各异，但大同于敏；教术众多，然大同于情。",
          DialogueId = 50107095,
          GUID = "7D701746",
          Subtitle = "Flavours may differ a thousand ways, yet all tend towards the good. Tunes may change without end, yet all return to harmony. The young may vary in temperament, yet all share a quickness of wit. Methods of teaching may be many, yet all come back to the heart."
        },
        [50107096] = {
          Content = "这万事万物，道理总是只有一个，但一个道理却可涵盖了世间万物，所以理一定是在前面的！",
          DialogueId = 50107096,
          GUID = "7D701770",
          Subtitle = "There's one principle behind everything. If it encompasses all things, it must come before all else!"
        },
        [50107097] = {
          Content = "今天该轮到你执勤了吧，之前你说你娘风寒，我可帮你顶了三天，夫子都起疑了！",
          DialogueId = 50107097,
          GUID = "7D70179A",
          Subtitle = "Wasn't it your turn on duty today? You said your mum had a cold, so I covered for you for three days. Now even the teacher's starting to get suspicious!"
        },
        [50107098] = {
          Content = "奉香大典期间放假，你们都去哪玩？我哥从外地回来了，说要给我带外国的新奇玩具呢。",
          DialogueId = 50107098,
          GUID = "7D7017C4",
          Subtitle = "School's off for the Grand Incense Rite. Where are you guys going? My brother's just got back, and he says he's bringing me some cool stuff from abroad."
        },
        [50107099] = {
          Content = "下午的蹴球赛，咱们队还差一人，你问过樾山哥没有？他要是肯来，咱们定能踢得对面满地找牙！",
          DialogueId = 50107099,
          GUID = "7D7017EE",
          Subtitle = "We're one short for the football match this afternoon. Have you checked with Yueshan yet? If he can make it, we'll absolutely wipe the floor with them."
        },
        [50107100] = {
          Content = "按这个势头算下去，岂不是又要扩张？可这又还能往哪里扩呢？",
          DialogueId = 50107100,
          GUID = "7D701818",
          Subtitle = "At this rate, it's bound to expand again... but where can it possibly go from here?"
        },
        [50107101] = {
          Content = "是了，来年开春便要递上辞函，到时候自然是会念着大家的，放心！",
          DialogueId = 50107101,
          GUID = "7D701842",
          Subtitle = "That's right. Come spring, I'll hand in my resignation. And when the time comes, I won't forget any of you, so don't worry."
        },
        [50107102] = {
          Content = "若华胥的安宁和平需要人们以不同的努力去守护，那为何飘零人的行为不能算是一种独特的方式？",
          DialogueId = 50107102,
          GUID = "7D70186C",
          Subtitle = "If Huaxu's peace is upheld by all sorts of people, in all sorts of ways, then why doesn't the Drifters' way count too?"
        },
        [50107103] = {
          Content = "好啊，今天的辩题有趣，我在学院许久没见过这么有意思的辩题了。",
          DialogueId = 50107103,
          GUID = "7D701896",
          Subtitle = "Now that's a debate topic. I haven't heard one this interesting at the academy in ages."
        },
        [50107104] = {
          Content = "空口说白话，不亚于纸上谈兵。有这闲工夫，不如多读些书！",
          DialogueId = 50107104,
          GUID = "7D7018C0",
          Subtitle = "All talk, no action. If you've got time to spare, go and read a book."
        },
        [50107105] = {
          Content = "椒兰村的香料自然是地道，处理方式也多样，只是要论品质，外面的许多园子都不遑多让。",
          DialogueId = 50107105,
          GUID = "7D7018EA",
          Subtitle = "Jiaolan Village's incense is certainly authentic, and it is processed in a variety of ways. That said, many incense gardens beyond the village produce incense of comparable quality."
        },
        [50107106] = {
          Content = "敢问祀烟阁的管事香官现在何处？鄙人自氤园而来，与他有约。",
          DialogueId = 50107106,
          GUID = "7D701914",
          Subtitle = "May I ask where the incense warden is? I've come from Yinyuan, and I have an appointment with him."
        },
        [50107107] = {
          Content = "今日怎得是你来奉香，你哥又回烟津渡了？",
          DialogueId = 50107107,
          GUID = "7D70193E",
          Subtitle = "How come you're the one offering incense today? Has your brother gone back to Mistwharf again?"
        },
        [50107108] = {
          Content = "伏惟上苍垂佑，神君护持，愿家父身体健康，百病不侵。",
          DialogueId = 50107108,
          GUID = "7D701968",
          Subtitle = "May Heaven bless us, and may Lord Argent watch over us. May my father be in good health, and kept safe from illness."
        },
        [50107109] = {
          Content = "唔……我的愿望是，长高一点，也不用太高，像一个正常的抟土氏就好。",
          DialogueId = 50107109,
          GUID = "7D701992",
          Subtitle = "Mm... I just want to be taller. Just a bit. Like everyone else..."
        },
        [50107110] = {
          Content = "奉香大典今年比往年都热闹许多呢！香官跟我说的。",
          DialogueId = 50107110,
          GUID = "7D7019BC",
          Subtitle = "This year's Grand Incense Rite's meant to be far livelier than usual. That's what the incense warden said."
        },
        [50107111] = {
          Content = "往年到了奉香大典期间，总是需要许多帮工入阁，今年怎得没动静了？",
          DialogueId = 50107111,
          GUID = "7D7019E6",
          Subtitle = "In past years, they always needed plenty of extra hands at the Hall of Incense during the Rite. So why's it gone so quiet there this year?"
        },
        [50107112] = {
          Content = "全城的香炉都要仔细查验香料储备，尤其是中心广场水上的那个炉子，务必不能有疏漏。",
          DialogueId = 50107112,
          GUID = "7D701A10",
          Subtitle = "Inspect the incense reserves in every censer across the city. Be thorough. Pay special attention to the one on the water in the central square. Don't miss a thing."
        },
        [50107113] = {
          Content = "难不成真是我思维迟缓，想不出新颖独特的香方了？",
          DialogueId = 50107113,
          GUID = "7D701A3A",
          Subtitle = "Has my mind really gone dull? Can't I come up with any new incense recipes any more?"
        },
        [50107114] = {
          Content = "不同的香方自然作用也不相同，你初来乍到，不了解也很正常。",
          DialogueId = 50107114,
          GUID = "7D701A64",
          Subtitle = "Different incense recipes have different effects. You're new here, so it's no wonder you don't know."
        },
        [50107115] = {
          Content = "听说了吗？祀香阁今年招了一位特殊香官，据说是……一位皎皎之民！",
          DialogueId = 50107115,
          GUID = "7D701A8E",
          Subtitle = "Have you heard? The Hall of Incense has brought in a special incense warden this year. They say it's... a Lunarian!"
        },
        [50107116] = {
          Content = "皎皎之民？！那矮冬瓜大头鱼一样的家伙，如何能担任香官一职？",
          DialogueId = 50107116,
          GUID = "7D701AB8",
          Subtitle = "A Lunarian!? Those stunted, big-headed little creatures? How could one of them possibly be fit to serve as an incense warden?"
        },
        [50107117] = {
          Content = "去泉通司问过了吗？奉香大典前事务繁杂，那批拨款要早点讨过来才好做事。",
          DialogueId = 50107117,
          GUID = "7D701AE2",
          Subtitle = "Have you asked at the Hall of Founts? It's always hectic before the Grand Incense Rite. Best to chase that allocation up early, or you won't get much done."
        },
        [50107118] = {
          Content = "师傅，我就是想来问问，这炉灶为何总是出问题，我这几番叨扰，自己都有点过意不去了。",
          DialogueId = 50107118,
          GUID = "7D701B0C",
          Subtitle = "Any idea why this burner keeps acting up? Sorry to trouble you again, but it won't behave."
        },
        [50107119] = {
          Content = "过两天不是休息了吗？你准备回家？还是带妻子出门逛逛？",
          DialogueId = 50107119,
          GUID = "7D701B36",
          Subtitle = "We've got a couple of days off soon. Any plans? Heading home, or taking your wife out somewhere?"
        },
        [50107120] = {
          Content = "来奉香也有这么多嘁嘁喳喳嘟嘟囔囔，要么就是嘀嘀咕咕哼哼唧唧，这要我们如何兢兢业业干活？",
          DialogueId = 50107120,
          GUID = "7D701B60",
          Subtitle = "We can't even offer incense in peace. Nothing but whispering, sniggering, and yapping. How are we supposed to get any proper work done?"
        },
        [50107121] = {
          Content = "你这关节做的根本不行！偶人要做抬手、转腰的动作，反复受力下来，榫头迟早开裂！",
          DialogueId = 50107121,
          GUID = "7D701B8A",
          Subtitle = "The joint you've made won't hold. With the puppet lifting its arms and twisting at the waist all the time, that tenon's going to split sooner or later."
        },
        [50107122] = {
          Content = "你瞧瞧，这是咱们新研究的木头珍猪，上了发条后一下便能冲出十米，想学的话来机枢派报个名？",
          DialogueId = 50107122,
          GUID = "7D701BB4",
          Subtitle = "Check this out — our new wind-up wooden Petit Boar. Wind it up and it'll dash ten metres in a flash. Want to learn how to make one? Sign up as an apprentice with the Jishu Sect!"
        },
        [50107123] = {
          Content = "叔叔，这是什么？看着好可爱，可以送给我吗？",
          DialogueId = 50107123,
          GUID = "7D701BDE",
          Subtitle = "Sir, what's that? It's so cute! Can I have it?"
        },
        [50107124] = {
          Content = "年年招新，年年没人，与其把心思放在拉人进阁，还不如多花些时间造个惊天动地的大工程出来！",
          DialogueId = 50107124,
          GUID = "7D701C08",
          Subtitle = "Year after year we recruit, year after year nobody comes. Instead of trying to rope people in, we'd be better off pouring that effort into a project that'll shake the world."
        },
        [50107126] = {
          Content = "民以食为天，食以香为先，香……这香……香啊……香。",
          DialogueId = 50107126,
          GUID = "7D701C5C",
          Subtitle = "\"Food is the first necessity\"... and when it comes to food, it's all about the smell. And this... this smell... mm... that's the stuff."
        },
        [50107127] = {
          Content = "这就是华胥风格的服饰吗？嘶……我怎么觉得穿起来哪里怪怪的呢？",
          DialogueId = 50107127,
          GUID = "7D701C86",
          Subtitle = "So this is Huaxu clothing? Hmm... why does it feel a bit off on me?"
        },
        [50107128] = {
          Content = "青青子衿，悠悠我心，在这苍茫人世间，难道我真就无法找到相伴一生之人？",
          DialogueId = 50107128,
          GUID = "7D701CB0",
          SpecialConversation = "该角色不怎么着调，可以跳脱一点",
          Subtitle = "Ah... my poor, lonely heart. In a world this vast, am I truly doomed to be alone forever?"
        },
        [50107129] = {
          Content = "要是我把这个人杀了……大家的反响一定很好，要是再把这个也顺便刀了……",
          DialogueId = 50107129,
          GUID = "7D701CDA",
          Subtitle = "If I kill him... people will love it. And if I take that one out as well, while I'm at it..."
        },
        [50107130] = {
          Content = "天气大好啊，等开春，去收两斤新茶泡来喝！",
          DialogueId = 50107130,
          GUID = "7D701D04",
          Subtitle = "Lovely weather today! Come spring, I'll buy some fresh tea and brew a pot."
        },
        [50107131] = {
          Content = "瞧见那远处的楼没？我啊，小时候曾听老人说，其实它根本不存在，都是假的！",
