        },
        [51000111] = {
          ContentFR = "Oui... son état empire de jour en jour. Mais elle a refusé de rester à Rougerive, et s’est obstinée à venir vivre dans ces contrées glacées. Rien n’a pu la retenir.",
          DialogueId = 51000111,
          GUID = "7FAC65B6",
          NextDialogue = 51000112,
          SpeakNpcId = 700020,
          Subtitle = "Yeah, she's getting worse day by day... *sigh* She left the comforts of Scarletriver for this frozen wasteland, and I couldn't persuade her to go home no matter what."
        },
        [51000112] = {
          ContentFR = "Elle ressasse sans cesse un vieux souvenir, remontant à quarante ans... Chaque jour, elle interroge les passants, et me défend d’intervenir.",
          DialogueId = 51000112,
          GUID = "7FAC65E0",
          NextDialogue = 51000190,
          SpeakNpcId = 700020,
          Subtitle = "She's still obsessed with something that happened forty years ago, asking around town every day, and she won't let me help her."
        },
        [51000113] = {
