          DialogueId = 51000401,
          GUID = "7FAC954A",
          NextDialogue = 51000402,
          SpeakNpcId = 700006,
          Subtitle = "Annie... Annie!",
          TalkActionId = {
            [1] = "700006:Shock_Start"
          }
        },
        [51000402] = {
