        },
        [51001609] = {
          ContentFR = "Depuis que je suis gamin, je m’impose les standards des Solariens. Je n’ai jamais traîné avec les autres Charons. Tu en connais beaucoup, toi, des Charons qui parlent comme moi ? Je te le dis : c’est un accent dismanien parfait.",
          DialogueId = 51001609,
          GUID = "7FAD5B7A",
          NextDialogue = 51001691,
          SpeakNpcId = 700068,
          Subtitle = "Since I was a kid, I've held myself to Sola standards, and never mingled with other Charons. Ever met a Charon who speaks like I do? Just so you know, this is a standard Dismania accent!"
        },
        [51001610] = {
          ContentFR = "Tu es {性别:jaloux|jalouse}, hein ? C’est bien mérité !",
          DialogueId = 51001610,
          GUID = "7FAD5BA4",
          NextDialogue = 51001692,
          SpeakNpcId = 700068,
          Subtitle = "Jealous, huh? Well, I've earned this!"
        },
        [51001611] = {
          ContentFR = "Tu comprends maintenant ? Je suis bien plus Sola que n’importe lequel d’entre vous. C’est pour ça que je suis devenu officier, pendant que toi, tu traînes en haillons comme {性别:un mendiant|une mendiante}.",
          DialogueId = 51001611,
          GUID = "7FAD5BCE",
          NextDialogue = 51001612,
          SpeakNpcId = 700068,
          Subtitle = "Got it? I'm more Sola than any of you could ever be, that's why I've become an officer, while you roam around in rags like a beggar."
        },
        [51001612] = {
          ContentFR = "Allez, assez perdu de temps. Si je discute avec toi, c’est uniquement parce que j’ai le cœur aussi noble que celui d’un Sola. Considère ça comme une leçon gratuite. Maintenant, dégage et va mendier ailleurs, je ne veux plus te voir, tu me portes malheur.",
          DialogueId = 51001612,
          GUID = "7FAD5BF8",
          NextOptions = {
            [1] = 510016121
          },
          RestartTag = 51001612,
          SpeakNpcId = 700068,
          Subtitle = "Alright, I've indulged you this long only because my heart's as big as any Sola's. Consider this as a gratis lesson for you Charons. Now shoo, take your lowlife vibes away from me.",
          bForbidSkipOptions = true
        },
        [51001613] = {
          ContentFR = "Hein ? Qu’est-ce que tu viens de dire ?",
          DialogueId = 51001613,
          GUID = "7FAD5C22",
          NextDialogue = 51001614,
          SpeakNpcId = 700068,
          Subtitle = "Huh? What did you say?"
        },
        [51001614] = {
          ContentFR = "J’ai entendu dire qu’Hyperborea décernait un titre prestigieux, celui de Charon Couronné, aux plus méritants.",
          DialogueId = 51001614,
          GUID = "7FAD5C4C",
          NextDialogue = 51001615,
          SpeakNpcId = 100001,
          Subtitle = "I've heard about this \"Laurelled Charon\" medal that Hyperborea grants to the most distinguished Charons."
        },
        [51001615] = {
          ContentFR = "Un officier aussi vaillant, loyal et à l’accent irréprochable que toi doit forcément en avoir une. J’aimerais tellement la voir de mes propres yeux.",
          DialogueId = 51001615,
          GUID = "7FAD5C76",
          NextDialogue = 51001616,
          SpeakNpcId = 100001,
          Subtitle = "Someone as brave, loyal, and with an impeccable accent like you must have one. I'd be thrilled to finally see it!"
        },
        [51001616] = {
