          DialogueId = 51001616,
          GUID = "7FAD5CA0",
          NextDialogue = 51001617,
          SpeakNpcId = 700068,
          Subtitle = "...I... must've left it at home! Maybe next time!"
        },
        [51001617] = {
          ContentFR = "Vraiment ? Je vous admire, mon officier !",
          DialogueId = 51001617,
          GUID = "7FAD5CCA",
          NextDialogue = 51001693,
          SpeakNpcId = 100001,
          Subtitle = "Is that so? I truly admire you, sir!"
        },
        [51001618] = {
