        [51001690] = {
          ContentFR = "Quoi ? Encore toi ? Je t’ai pourtant dit de déguerpir !",
          DialogueId = 51001690,
          GUID = "7FAD68C4",
          SpeakNpcId = 700068,
          Subtitle = "What, you again? Didn't I tell you to get out of my sight?"
        },
        [51001691] = {
          ContentFR = "Mes amis Solariens disent qu’à m’entendre, ils ne devineraient jamais que je suis un Charon. Ils disent que je parle exactement comme eux.",
          DialogueId = 51001691,
          GUID = "7FAD68EE",
          NextDialogue = 51001610,
          SpeakNpcId = 700068,
          Subtitle = "My Sola friends all say they can't tell that I'm actually a Charon from the way I speak. They say I sound just like one of them."
        },
        [51001692] = {
          ContentFR = "Pendant trois ans, tous les matins, je lisais <I>L’Actualité d’Hyperborea</> pendant deux heures, à corriger mon accent... et à lire les horreurs commises par ces minables Charons, ces incapables que nous sommes censés être.",
          DialogueId = 51001692,
          GUID = "7FAD6918",
          NextDialogue = 51001611,
          SpeakNpcId = 700068,
          Subtitle = "For three years straight, I'd start every morning reading \"Hyperborean News\" for two hours, fine-tuning my accent while cringing at the crimes some Charon had disgracefully committed."
        },
        [51001693] = {
          ContentFR = "On raconte que les Charons Couronnés ont le droit de résider dans la cité intérieure. Tu dois sûrement y posséder un manoir splendide, comme dans les contes — avec des majordomes et des domestiques par dizaines !",
          DialogueId = 51001693,
          GUID = "7FAD6942",
          NextDialogue = 51001618,
          SpeakNpcId = 100001,
          Subtitle = "I've heard that Laurelled Charons are entitled to live in the inner city. You must own a splendid mansion there, like something out of a storybook — with legions of butlers and servants!"
        },
        [51001701] = {
          ContentFR = "La canalisation n° 13 est en réparation. Bon sang... il y a bien trop de rats là-dedans.",
          DialogueId = 51001701,
          GUID = "7FAD6A92",
          NextDialogue = 51001702,
          SpeakNpcId = 700069,
          Subtitle = "Pipe No. 13 is under repair — blimey, it's swarming with rats in there.",
          TalkActionId = {
            [1] = "700069:Sigh_Start"
          }
        },
        [51001702] = {
          ContentFR = "Dutton lève les yeux vers toi. Une odeur nauséabonde s’échappe de ses vêtements, si forte que tu recules instinctivement d’un pas, luttant contre la nausée.",
          DialogueId = 51001702,
          GUID = "7FAD6ABC",
          NextDialogue = 51001703,
          Subtitle = "(Dutton looks up, reeking so strongly that you're forced to step back. You manage to stifle a gag.)",
          TalkActionId = {
            [1] = "700069:Sigh_End"
          }
        },
        [51001703] = {
          ContentFR = "Hé ! Pourquoi tu t’éloignes ? Quand on bosse dans les égouts, c’est normal de sentir un peu fort.",
          DialogueId = 51001703,
          GUID = "7FAD6AE6",
          NextOptions = {
            [1] = 510017031,
            [2] = 510017032,
            [3] = 510017033
          },
          SpeakNpcId = 700069,
          Subtitle = "Hey! That was a bit uncalled for. Comes with the territory when you work in sewers, doesn't it?",
          bForbidSkipOptions = true
        },
        [51001704] = {
          ContentFR = "Ne te fie pas à ce que tu vois. Il y a encore quelques années, la plupart des gens m’appelaient avec respect « Docteur Dutton ».",
          DialogueId = 51001704,
          GUID = "7FAD6B10",
          NextDialogue = 51001705,
          SpeakNpcId = 700069,
          Subtitle = "You might not believe it, but there was a time people respectfully addressed me as \"Doctor Dutton\"."
        },
        [51001705] = {
          ContentFR = "Tu comprends sans doute ce que ce titre représentait pour un Charon né dans les taudis.",
          DialogueId = 51001705,
          GUID = "7FAD6B3A",
          NextDialogue = 51001706,
          SpeakNpcId = 700069,
          Subtitle = "You get what that title means to a Charon who's come up from the slums, right?"
        },
        [51001706] = {
          ContentFR = "J’ai soigné d’innombrables Charons à l’hôpital central... même des nobles faisaient le déplacement pour une consultation.",
          DialogueId = 51001706,
          GUID = "7FAD6B64",
          NextDialogue = 51001707,
          SpeakNpcId = 700069,
          Subtitle = "I've treated countless Charons at the central hospital; even the nobility sought me out for consultations.",
          TalkActionId = {
            [1] = "700069:Explain02_Start"
          }
        },
        [51001707] = {
          ContentFR = "Si tu ne me crois pas, demande donc aux jeunes Charons : leurs parents leur répétaient sans cesse de prendre exemple sur moi.",
          DialogueId = 51001707,
          GUID = "7FAD6B8E",
          NextDialogue = 51001708,
          SpeakNpcId = 700069,
          Subtitle = "Don't take my word for it — go ask the younger Charons. Their folks always told them to model themselves on me.",
          TalkActionId = {
            [1] = "700069:Explain02_End"
          }
        },
        [51001708] = {
          ContentFR = "À l’époque, j’étais un vrai maniaque de la propreté... le moindre grain de poussière entre deux carreaux me rendait fou.",
          DialogueId = 51001708,
          GUID = "7FAD6BB8",
          NextOptions = {
            [1] = 510017081
          },
          RestartTag = 51001708,
          SpeakNpcId = 700069,
          Subtitle = "I was quite a stickler for cleanliness back then; a single speck of dust between the tiles would drive me nuts...",
          bForbidSkipOptions = true
        },
        [51001709] = {
          ContentFR = "Je réparais des gens, aujourd’hui je répare des tuyaux... au fond, ça revient au même, non ?",
          DialogueId = 51001709,
          GUID = "7FAD6BE2",
          NextDialogue = 51001710,
          SpeakNpcId = 700069,
          Subtitle = "I used to patch up people, and now I patch up pipes. Not much difference, eh?",
          TalkActionId = {
            [1] = "700069:Think_Start"
          }
        },
        [51001710] = {
          ContentFR = "Dutton esquisse un sourire tranquille, comme s’il tournait sans rancune la page d’un passé douloureux.",
          DialogueId = 51001710,
          GUID = "7FAD6C0C",
          Subtitle = "(Dutton gave a serene smile, seemingly turning a page on some tough memories without a grudge.)",
          TalkActionId = {
            [1] = "700069:Think_End"
          }
        },
        [51001711] = {
          ContentFR = "Imagine la scène : un passant s’effondre, frappé par une urgence vitale, juste devant un médecin... et ce médecin choisit bravement de le sauver.",
          DialogueId = 51001711,
          GUID = "7FAD6C36",
          NextDialogue = 51001712,
          SpeakNpcId = 700069,
          Subtitle = "Picture this: a pedestrian collapsed from an acute condition right in front of a doctor, who heroically opted to save him.",
          TalkActionId = {
            [1] = "700069:Explain01_Start"
          }
        },
        [51001712] = {
          ContentFR = "Tu veux connaître la suite ? Passe-moi plutôt cette clé à molette.",
          DialogueId = 51001712,
          GUID = "7FAD6C60",
          NextDialogue = 51001713,
          SpeakNpcId = 700069,
          Subtitle = "Curious about what happened next? Hand me that wrench first—"
        },
        [51001713] = {
          ContentFR = "Le miracle n’a pas eu lieu. Ce qui est arrivé, c’est un procès colossal pour faute médicale. Pour préserver sa réputation, l’hôpital a dû licencier un employé.",
          DialogueId = 51001713,
          GUID = "7FAD6C8A",
          NextDialogue = 51001714,
          SpeakNpcId = 700069,
          Subtitle = "No miracle happened, just a massive lawsuit for medical malpractice. For the sake of the hospital's reputation, an employee had to be fired.",
          TalkActionId = {
            [1] = "700069:Explain01_End"
          }
        },
        [51001714] = {
          ContentFR = "Et cet homme-là, qui ne savait rien faire d’autre que soigner... s’est retrouvé dans les égouts.",
          DialogueId = 51001714,
          GUID = "7FAD6CB4",
          NextDialogue = 51001715,
          SpeakNpcId = 700069,
          Subtitle = "Imagine that—someone who knew nothing but how to heal, ending up in the sewer pipes.",
          TalkActionId = {
            [1] = "700069:Sigh_Start"
          }
        },
        [51001715] = {
          ContentFR = "Au moins, ce passage ici a guéri ma vieille obsession de la propreté en quelques mois. C’est déjà ça.",
          DialogueId = 51001715,
          GUID = "7FAD6CDE",
          NextDialogue = 51001716,
          SpeakNpcId = 700069,
          Subtitle = "Funny enough, a few months down here cured me of that intense fixation with cleanliness. A silver lining, am I right?",
          TalkActionId = {
            [1] = "700069:Sigh_End"
          }
        },
        [51001716] = {
          ContentFR = "Et puis bon... ce boulot me permet de ne pas mourir de faim dans la rue. Je devrai juste rembourser mes dettes jusqu’à ce qu’on me mette en terre.",
          DialogueId = 51001716,
          GUID = "7FAD6D08",
          NextOptions = {
            [1] = 510017161
          },
          SpeakNpcId = 700069,
          Subtitle = "At least this gig keeps me from starving on the streets, though I'll be paying debts till I'm six feet under.",
          bForbidSkipOptions = true
        },
        [51001717] = {
          ContentFR = "Dutton tourne le dos et resserre consciencieusement les nouvelles vis de la canalisation. Il balance ses bras avec habitude et énergie, comme s’il n’avait même pas entendu ta question.",
          DialogueId = 51001717,
          GUID = "7FAD6D32",
          NextDialogue = 51001718,
          Subtitle = "(Dutton turns, focusing on tightening the screws of the replacement pipe with his wrench, his arms swinging skillfully, seemingly oblivious to your question.)"
        },
        [51001718] = {
          ContentFR = "Dans le silence assourdissant qui suit, la réponse est pourtant évidente pour vous deux.",
          DialogueId = 51001718,
          GUID = "7FAD6D5C",
          Subtitle = "(Yet, in the echoing silence that ensues, the answer is clear to both of you without a word spoken.)"
        },
        [51001719] = {
          ContentFR = "Aïe... ! Il y a vraiment trop de rats, là-dedans !",
          DialogueId = 51001719,
          GUID = "7FAD6D86",
          SpeakNpcId = 700069,
          Subtitle = "Ow...! The rats are taking over down here!"
        },
        [51001801] = {
          ContentFR = "Eh, j’ai entendu dire que tu t’étais bien débrouillé à la Fosse de Glevum. Avec un tel talent, ça te dirait qu’on fasse un boulot ensemble ? Tu prends 80 %, je prends 20. Qu’en dis-tu ?",
          DialogueId = 51001801,
          GUID = "7FAD7AFA",
          NextOptions = {
            [1] = 510018011,
            [2] = 510018012
          },
          SpeakNpcId = 200015,
          Subtitle = "Hey, kid! Word's got around about your big score at Glevum Pit. Really impressive, I'd say! How about you and I team up for a gig? I'll take a 20% cut, you keep 80%. What do you say?",
          bForbidSkipOptions = true
        },
        [51001802] = {
          ContentFR = "Parfait, on y va alors.",
          DialogueId = 51001802,
          GUID = "7FAD7B24",
          NextDialogue = 51001803,
          SpeakNpcId = 200015,
          Subtitle = "Alright, let's get going then.",
          TalkActionId = {
            [1] = "200015:Agree"
          }
        },
        [51001803] = {
          ContentFR = "Camilla, mets-moi ça sur ta note, je te rembourse quand j’aurai la récompense.",
          DialogueId = 51001803,
          GUID = "7FAD7B4E",
          LookAt = {
            [1] = "200015:n(200003)",
            [2] = "200003:n(200015)"
          },
          NextDialogue = 51001804,
          SpeakNpcId = 200015,
          Subtitle = "Camilla, put the drink on my tab. I'll pay you back once I get the reward.",
          TurnTo = {
            [1] = "200015:n(200003)",
            [2] = "200003:n(200015)"
          }
        },
        [51001804] = {
          ContentFR = "Comme d’habitude, alors ta montre reste ici en garantie.",
          DialogueId = 51001804,
          GUID = "7FAD7B78",
          NextDialogue = 51001805,
          SpeakNpcId = 200003,
          Subtitle = "Same as always then, your pocket watch stays here as collateral."
        },
        [51001805] = {
          ContentFR = "Pas de souci. {nickname}, on y va et on revient vite.",
          DialogueId = 51001805,
          GUID = "7FAD7BA2",
          SpeakNpcId = 200015,
          Subtitle = "Sure, sure. , let's make short work of this.",
          TurnTo = {
            [1] = "200015:n(0)"
          }
        },
        [51001901] = {
          ContentFR = "Avant même d’entrer aux Asphodèles, tu entends déjà des jurons résonner à travers la salle, comme si toute la cité devait entendre sa colère.",
          DialogueId = 51001901,
          GUID = "7FAD8B62",
          NextDialogue = 51001902,
          Subtitle = "(Before even enter The Asphodel, you already hear the echoing curse words, as if wanting the whole city to listen to his rage.)"
        },
        [51001902] = {
          ContentFR = "Tu as encore le culot de montrer ta tête ! J’ai été si stupide... j’aurais dû faire plus que te chasser !",
          DialogueId = 51001902,
          GUID = "7FAD8B8C",
          LookAt = {
            [1] = "200015:n(700047)"
          },
          NextDialogue = 51001903,
          SpeakNpcId = 700047,
          Subtitle = "How dare you show yourself in front of my face! I was such a fool. I should have done more than just kick you out!",
          TalkActionId = {
            [1] = "700047:Angry01_Start"
          }
        },
        [51001903] = {
          ContentFR = "Tu parades avec notre nom depuis des années... et mes lettres de mise en garde ? Tu les as brûlées ?",
          DialogueId = 51001903,
          GUID = "7FAD8BB6",
          NextDialogue = 51001904,
          SpeakNpcId = 700047,
          Subtitle = "You paraded around with our family name for so many years. Did you use my warning letters as kindling?",
          TalkActionId = {
            [1] = "700047:Angry01_End"
          }
        },
        [51001904] = {
          ContentFR = "Oui, oui... vous avez raison, mais ce nom, après tout, c’est ce que vous...",
          DialogueId = 51001904,
          GUID = "7FAD8BE0",
          NextDialogue = 51001905,
          SpeakNpcId = 200015,
          Subtitle = "Yes, yes, you are right, but after all, that surname is what you...",
          TalkActionId = {
            [1] = "200015:Shock_Start"
          }
        },
        [51001905] = {
          ContentFR = "Wells, tête baissée comme un enfant puni, reste immobile tandis que l’homme le pointe du doigt.",
          DialogueId = 51001905,
          GUID = "7FAD8C0A",
          NextDialogue = 51001906,
          Subtitle = "(Wells, like a child who's misbehaved, stands with his head bowed in front of an old man, allowing the latter's finger to jab at him.)"
        },
        [51001906] = {
          ContentFR = "Ferme-la ! Tu n’as aucun talent et tu prétends être un Chasseur de Phoxène ? L’argent et la renommée ? Tu ne les mérites pas ! Tu cours partout comme un chien... maintenant toute la cité intérieure prend les Wells pour une blague !",
          DialogueId = 51001906,
          GUID = "7FAD8C34",
          NextDialogue = 51001907,
          SpeakNpcId = 700047,
          Subtitle = "Shut up! You have no talent, yet you try to be a Phoxhunter. Do you really think you deserve this money and fame? Running around like a dog for others. The inner city now sees the Wells family as a joke!",
          TalkActionId = {
            [1] = "200015:Shock_End"
          }
        },
        [51001907] = {
          ContentFR = "Je pensais juste... si je réussis un jour, peut-être que vous reverrez votre jugement sur Sara et moi...",
          DialogueId = 51001907,
          GUID = "7FAD8C5E",
          NextDialogue = 51001908,
          SpeakNpcId = 200015,
          Subtitle = "I was just thinking, if I make something of myself someday, maybe you'll reconsider things about me and Sara—",
          TalkActionId = {
            [1] = "200015:Explain02_Start"
          }
        },
        [51001908] = {
          ContentFR = "Comment oses-tu prononcer son nom ! Oublie-la ! Toi et ma fille, il n’y aura jamais de retour possible ! Jamais !",
          DialogueId = 51001908,
          GUID = "7FAD8C88",
          NextDialogue = 51001909,
          SpeakNpcId = 700047,
          Subtitle = "How dare you mention her name! Forget about it. You and my daughter will never get back together, never!",
          TalkActionId = {
            [1] = "700047:Angry01_Start"
          }
        },
        [51001909] = {
          ContentFR = "Et ne dis pas que je ne t’ai pas prévenu : si tu poses un pied dans la cité intérieure, je te brise les jambes.",
          DialogueId = 51001909,
          GUID = "7FAD8CB2",
          NextDialogue = 51001910,
          SpeakNpcId = 700047,
          Subtitle = "Don't say I didn't warn you. If you dare step foot in the inner city, I'll break your legs.",
          TalkActionId = {
            [1] = "700047:Angry01_End"
          }
        },
        [51001910] = {
          ContentFR = "Oui, oui...",
          DialogueId = 51001910,
          GUID = "7FAD8CDC",
          NextDialogue = 51001911,
          SpeakNpcId = 200015,
          Subtitle = "Yeah, yeah...",
          TalkActionId = {
            [1] = "200015:Explain02_End"
          }
        },
        [51001911] = {
          ContentFR = "L’homme, voyant Wells hocher la tête sans fin, devient encore plus furieux. Son regard se pose finalement sur toi qui vient d’entrer dans les Asphodèles.",
          DialogueId = 51001911,
          GUID = "7FAD8D06",
          NextDialogue = 51001912,
          Subtitle = "(The old man, glaring at the nodding Wells, grows even more infuriated, looking around and finally setting his eyes on you, who just enters The Asphodel.)"
        },
        [51001912] = {
          ContentFR = "Et toi, Charon ? J’en ai vu des comme toi, rêvant de gloire en tant que Chasseur de Phoxène, pour ensuite espérer devenir un Charon Couronné...",
          DialogueId = 51001912,
          GUID = "7FAD8D30",
          NextDialogue = 51001990,
          SpeakNpcId = 700047,
          Subtitle = "And you, a Phoxhunter? I've seen many like you, dreaming of making a name for yourself as a Phoxhunter, and becoming a laurelled Charon.",
          TalkActionId = {
            [1] = "700047:Explain01_Start"
          }
        },
        [51001913] = {
          ContentFR = "Vous avez raison... mais {nickname} est vraiment capable, pas comme moi...",
          DialogueId = 51001913,
          GUID = "7FAD8D5A",
          NextDialogue = 51001914,
          SpeakNpcId = 200015,
          Subtitle = "Father-in-law,  is a capable one, not a loser like me..."
        },
        [51001914] = {
          ContentFR = "Ferdinand Wells, ce qui s’est passé entre vous deux ne me regarde pas. Mais si vous continuez à déranger nos invités pour rien, je devrai vous faire sortir.",
          DialogueId = 51001914,
          GUID = "7FAD8D84",
          NextDialogue = 51001915,
          SpeakNpcId = 200003,
          Subtitle = "Mr. Ferdinand Wells, I had no right to interfere what happened between you two. But if you keep harassing my other guests for no reason like this, The Asphodel might have to show you the door.",
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51001915] = {
          ContentFR = "Camilla, assise derrière le comptoir, souffle un anneau de fumée. Ses paroles désinvoltes résonnent pourtant avec force dans la salle vide.",
          DialogueId = 51001915,
          GUID = "7FAD8DAE",
          NextDialogue = 51001991,
          Subtitle = "(Camilla, sitting behind the counter, puffs out a ring of smoke. Her casual words echoing powerfully in the empty tavern.)",
          TalkActionId = {
            [1] = "200003:Talk03_End"
          }
        },
        [51001916] = {
          ContentFR = "<I>Hmpf.</>",
          DefaultLookAt = "TalkNpc",
          DialogueId = 51001916,
          GUID = "7FAD8DD8",
          LookAt = {
            [1] = "200015:n(700047)"
          },
          NextDialogue = 51001917,
          SpeakNpcId = 700047,
          Subtitle = "Hmph.",
          TalkActionId = {
            [1] = "700047:Disagree"
          }
        },
        [51001917] = {
          ContentFR = "Le vieil homme continue de pointer Wells et de jurer. Peut-être vaut-il mieux attendre qu’il se calme pour parler à nouveau.",
          DialogueId = 51001917,
          GUID = "7FAD8E02",
          Subtitle = "(The elder didn't quite catch what you said, and continued to curse Wells. Maybe it's better to wait a bit for him to calm down.)"
        },
        [51001918] = {
          ContentFR = "<I>... Hmpf.</>",
          DefaultLookAt = "TalkNpc",
          DialogueId = 51001918,
          GUID = "7FAD8E2C",
          LookAt = {
            [1] = "200015:n(700047)"
          },
          NextDialogue = 51001919,
          SpeakNpcId = 700047,
          Subtitle = "...Hmph.",
          TalkActionId = {
            [1] = "700047:Disagree"
          }
        },
        [51001919] = {
          ContentFR = "L’homme, réduit au silence par tes paroles, jette un dernier regard noir et sort en claquant la porte.",
          DialogueId = 51001919,
          GUID = "7FAD8E56",
          NextDialogue = 51001920,
          Scripts = "MoveTo{ActorId{700047},TargetPoint{\"TargetPoint_LeaveTavern\"},MoveSpeed{90},Visibility{\"Hide\"}}",
          Subtitle = "(The elder is left speechless by your words, and glares fiercely before storming out.)"
        },
        [51001920] = {
          ContentFR = "Désolé pour tout ce remue-ménage... Mon beau-père... Monsieur Ferdinand Wells n’était pas venu dans la cité extérieure depuis des années.",
          DialogueId = 51001920,
          GUID = "7FAD8E80",
          LookAt = {
            [1] = "200015:n(0)"
          },
          NextDialogue = 51001992,
          SpeakNpcId = 200015,
          Subtitle = "Sorry for causing everyone so much trouble. Well, my father-in-law... I mean Mr. Ferdinand Wells hasn't been to the outer city for years.",
          TalkActionId = {
            [1] = "200015:Sigh_Start"
          }
        },
        [51001921] = {
          ContentFR = "Pas grave. Si quelques insultes pouvaient nous abattre, nous ne serions pas ici. On m’a dit que vous aviez été blessé pendant une mission. Ça va ?",
          DialogueId = 51001921,
          GUID = "7FAD8EAA",
          NextDialogue = 51001922,
          SpeakNpcId = 100001,
          Subtitle = "It's alright. We wouldn't be here today if we gave in to every slight or insult. Anyway, I heard you were injured recently during a commission. Are you okay?"
        },
        [51001922] = {
          ContentFR = "Ce n’est rien. Heureusement, cette montre m’a protégé d’une blessure mortelle.",
          DialogueId = 51001922,
          GUID = "7FAD8ED4",
          NextDialogue = 51001923,
          SpeakNpcId = 200015,
          Subtitle = "It's nothing. Luckily this thing saved me from being fatally injured.",
          TalkActionId = {
            [1] = "200015:Explain01_Start"
          }
        },
        [51001923] = {
          ContentFR = "Wells sort une montre de poche finement travaillée, le cadran fissuré, les aiguilles tordues de façon exagérée, au point qu’il est devenu impossible de refermer le boîtier.",
          DialogueId = 51001923,
          GUID = "7FAD8EFE",
          NextOptions = {
            [1] = 510019231,
            [2] = 510019232
          },
          Subtitle = "(Wells takes out a finely crafted pocket watch from his chest. The dial is covered in cracks, and the hands are twisted upwards in an exaggerated manner, making closing the watch cover a mere wish.)",
          TalkActionId = {
            [1] = "200015:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51001924] = {
          ContentFR = "Il l’a faite lui-même. Il y a dix ans, tout le monde connaissait Todd Wells, le prodige horloger. Il était presque devenu un Charon Couronné grâce à son talent.",
          DialogueId = 51001924,
          GUID = "7FAD8F28",
          NextDialogue = 51001925,
          SpeakNpcId = 200003,
          Subtitle = "He made it himself. Over a decade ago, there wasn't a soul who hadn't heard of Todd Wells, the prodigy clockmaker. Back then, his craftsmanship almost won him the title of Laurelled Charon.",
          TalkActionId = {
            [1] = "200003:Explain01_Start"
          }
        },
        [51001925] = {
          ContentFR = "Une pièce magnifique... dommage qu’elle soit cassée.",
          DialogueId = 51001925,
          GUID = "7FAD8F52",
          NextDialogue = 51001926,
          SpeakNpcId = 100001,
          Subtitle = "Such a beautifully crafted watch. It's a pity it cracked like that.",
          TalkActionId = {
            [1] = "200003:Explain01_End"
          }
        },
        [51001926] = {
          ContentFR = "Haha, oui, mais les aiguilles étaient déjà cassées depuis longtemps. Je la garde juste comme souvenir.",
          DialogueId = 51001926,
          GUID = "7FAD8F7C",
          NextDialogue = 51001927,
          SpeakNpcId = 200015,
          Subtitle = "Haha. Actually the hands had been broken for a long time, you know. I just keep it with me as a memento.",
          TalkActionId = {
            [1] = "200015:Sigh_Start"
          }
        },
        [51001927] = {
          ContentFR = "Pourquoi ne pas essayer de la réparer ?",
          DialogueId = 51001927,
          GUID = "7FAD8FA6",
          NextDialogue = 51001928,
          SpeakNpcId = 100001,
          Subtitle = "Why don't you try to fix it then?"
        },
        [51001928] = {
          ContentFR = "Mon beau-père a coupé l’accès aux outils et matériaux, impossible de la réparer.",
          DialogueId = 51001928,
          GUID = "7FAD8FD0",
          NextDialogue = 51001929,
          SpeakNpcId = 200015,
          Subtitle = "The tools and materials needed for repairs were cut off by my father-in-law, so even if I wanted to fix it, I just couldn't.",
          TalkActionId = {
            [1] = "200015:Sigh_End"
          }
        },
        [51001929] = {
          ContentFR = "... Tout ne se répare pas juste parce qu’on veut et qu’on y met de la force.",
          DialogueId = 51001929,
          GUID = "7FAD8FFA",
          NextDialogue = 51001930,
          SpeakNpcId = 200015,
          Subtitle = "...It's the way it is. Not everything can be fixed just because you want to and put effort into it.",
          TalkActionId = {
            [1] = "200015:Talk01_Start"
          }
        },
        [51001930] = {
          Content = "……",
          DialogueId = 51001930,
          GUID = "7FAD9024",
          NextDialogue = 51001931,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [51001931] = {
          ContentFR = "Bref, merci d’être intervenu. Sans toi, mes oreilles n’y auraient pas résisté.",
          DialogueId = 51001931,
          GUID = "7FAD904E",
          NextDialogue = 51001932,
          SpeakNpcId = 200015,
          Subtitle = "Anyway! Enough about that. Thanks again for stepping in — if you hadn't, I'd be half-deaf by now from all that yelling.",
          TalkActionId = {
            [1] = "200015:Talk01_End"
          }
        },
        [51001932] = {
          ContentFR = "Allez, ce soir c’est moi qui régale. Tu ouvres ces fûts là-bas, je m’occupe de ceux-ci !",
          DialogueId = 51001932,
          GUID = "7FAD9078",
          NextDialogue = 51001934,
          SpeakNpcId = 200015,
          Subtitle = "Come on, drinks are on me tonight! I'll crack open these kegs — you handle those ones over there!",
          TalkActionId = {
            [1] = "200015:Explain02_Start"
          }
        },
        [51001933] = {
          ContentFR = "Allez, bois ! À la tienne !",
          DialogueId = 51001933,
          GUID = "7FAD90A2",
          SpeakNpcId = 200015,
          Subtitle = "Come on, let's drink and party all night!"
        },
        [51001934] = {
          ContentFR = "...",
          DialogueId = 51001934,
          GUID = "7FAD9079",
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "200015:Explain02_End"
          }
        },
        [51001935] = {
          Camera = "122.0,278.0,139.0,0.000007,0.0,-95.0,35.0,200.0,false,Manual,2.8",
          ContentFR = "Tu ouvres tous les fûts, te retournes et vois Wells lever son verre, le sourire large et familier.",
          DialogueId = 51001935,
          FinalCamera = "102.0,278.0,139.0,0.000007,0.0,-95.0,35.0,350.0,false,Manual,2.8",
          GUID = "7FAD907A",
          Scripts = "TurnTo{_delay{1.5},TurnToDescription{\"100001:n(700207)\"}}",
          Subtitle = "(You pop open the last keg. Glancing back, you see Wells already raising a glass, his grin wide and familiar as ever.)",
          TalkActionId = {
            [1] = "700207:Angry01_Start"
          },
          ToFinalCameraBlendTime = 7
        },
        [51001936] = {
          ContentFR = "Pourtant, sous ce rire, ses doigts serrent la montre à gousset brisée, une pointe de mélancolie qui semble, tout comme la montre elle-même, impossible à réparer facilement.",
          DialogueId = 51001936,
          Duration = 4,
          GUID = "7FAD907B",
          Subtitle = [[
(And yet... beneath the laughter, his fingers curl around the broken pocket watch, a quiet sorrow flickering beneath the surface.)
(Like the shattered timepiece, a part of him is no longer easily mended.) ]]
        },
        [51001990] = {
          ContentFR = "Laisse-moi te dire quelque chose. <H>Givrelac n’a pas eu beaucoup de Charons Couronnés vivants depuis des années.</> Les Charons finissent seulement par pourrir dans une ruelle sombre !",
          DialogueId = 51001990,
          GUID = "7FAD99FC",
          NextDialogue = 51001913,
          SpeakNpcId = 700047,
          Subtitle = "Let me tell you something. Icelake hasn't had many living laurelled Charons for years. Charons only end up rotting in some dark alley!",
          TalkActionId = {
            [1] = "700047:Explain01_End"
          }
        },
        [51001991] = {
          ContentFR = "On a l’impression que la température de la pièce monte légèrement à cause de la fumée.",
          DialogueId = 51001991,
          GUID = "7FAD9A26",
          NextOptions = {
            [1] = 510019911,
            [2] = 510019912,
            [3] = 510019913
          },
          RestartTag = 51001915,
          Subtitle = "(As if the temperature in The Asphodel rose significantly in the smoke.)",
          bForbidSkipOptions = true
        },
        [51001992] = {
          ContentFR = "Il est un peu... attaché aux traditions. Ne prends pas ses paroles trop à cœur.",
          DialogueId = 51001992,
          GUID = "7FAD9A50",
          NextDialogue = 51001921,
          SpeakNpcId = 200015,
          Subtitle = "Let's just say he's more... traditional. Don't take his words to heart.",
          TalkActionId = {
            [1] = "200015:Sigh_End"
          }
        },
        [51002001] = {
          ContentFR = "Amis de passage, arrêtez-vous un instant ! Contre quelques pièces, vous repartirez avec un indice menant au fabuleux trésor caché d’une île du sud !",
          DialogueId = 51002001,
          GUID = "7FAD9BCA",
          NextDialogue = 51002002,
          SpeakNpcId = 700048,
          Subtitle = "Ladies and gentlemen, drop by and drop a few coins, and you will get something unimaginable! Yes, the clue to the secret treasure of a southern island!",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002002] = {
          ContentFR = "Quoi, vous comptez vraiment vous contenter chaque jour de pain rassis et de vin éventé ? Lancez-vous donc dans l’aventure, saisissez votre chance, changez votre destin !",
          DialogueId = 51002002,
          GUID = "7FAD9BF4",
          NextDialogue = 51002003,
          SpeakNpcId = 700048,
          Subtitle = "Are you really content with cold bread and stale wine every day? Why not embark on an adventure, seize the opportunity, and change your life!",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002003] = {
          ContentFR = "L’homme qui t’interpelle, un vieillard en haillons au ton exalté, respire l’opportunisme. Mais son assurance excessive le rend plutôt suspect.",
          DialogueId = 51002003,
          GUID = "7FAD9C1E",
          NextOptions = {
            [1] = 510020031,
            [2] = 510020032,
            [3] = 510020033
          },
          Subtitle = "(The old man before you is dressed in rags, but his eyes gleam with fiery conviction. Still, all that grand talk only makes him seem... less than trustworthy.)",
          bForbidSkipOptions = true
        },
        [51002004] = {
          ContentFR = "Ah, mais regardez-moi... je ne suis plus qu’un tas de vieilles guibolles. Autant laisser cette chance à la jeunesse !",
          DialogueId = 51002004,
          GUID = "7FAD9C48",
          NextDialogue = 51002005,
          SpeakNpcId = 700048,
          Subtitle = "Oh, I'm just an old man. I'd rather give the opportunity to the younger generation.",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002005] = {
          ContentFR = "Hé, si j’avais encore votre âge, j’aurais déjà empaqueté mes affaires et pris la mer !",
          DialogueId = 51002005,
          GUID = "7FAD9C72",
          NextDialogue = 51002010,
          SpeakNpcId = 700048,
          Subtitle = "If I were your age, I'd surely be packing my stuff and setting off right now."
        },
        [51002006] = {
          ContentFR = "Tiens donc, vous êtes {性别:intéressé|intéressée} ? Vous savez reconnaître une occasion quand elle se présente.",
          DialogueId = 51002006,
          GUID = "7FAD9C9C",
          NextDialogue = 51002007,
          SpeakNpcId = 700048,
          Subtitle = "What, you are interested? You do know how to seize opportunities.",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002007] = {
          ContentFR = "J’aime les jeunes {性别:futés|futées} comme vous. Alors, pour vous, je peux bien lâcher un petit indice... gratuitement.",
          DialogueId = 51002007,
          GUID = "7FAD9CC6",
          NextDialogue = 51002010,
          SpeakNpcId = 700048,
          Subtitle = "I like smart kids like you, so I can indeed reveal a thing or two for free.",
          TalkActionId = {
            [1] = "700048:Agree"
          }
        },
        [51002008] = {
          ContentFR = "Comment pouvez-vous dire ça ? Vous ne m’avez même pas écouté ! Quelle impolitesse !",
          DialogueId = 51002008,
          GUID = "7FAD9CF0",
          NextDialogue = 51002009,
          SpeakNpcId = 700048,
          Subtitle = "What are you talking about? You accuse me of defraudation without even hearing me out. Where are your manners?",
          TalkActionId = {
            [1] = "700048:Disagree"
          }
        },
        [51002009] = {
          ContentFR = "Puisque vous m’accusez d’être un escroc, laissez-moi au moins vous ouvrir les yeux.",
          DialogueId = 51002009,
          GUID = "7FAD9D1A",
          NextDialogue = 51002010,
          SpeakNpcId = 700048,
          Subtitle = "Since you think I'm a swindler, let me tell you a few things to set things straight."
        },
        [51002010] = {
          ContentFR = "Je ne suis pas natif de Givrelac. Je suis né sur une île au sud de l’Empire.",
          DialogueId = 51002010,
          GUID = "7FAD9D44",
          NextDialogue = 51002011,
          SpeakNpcId = 700048,
          Subtitle = "Actually, I'm not a local from Icelake. I was born on an island in the southern part of the Empire.",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002011] = {
          ContentFR = "Notre île était dominée par un immense Arbre Céleste, invisible sur la plupart des cartes.",
          DialogueId = 51002011,
          GUID = "7FAD9D6E",
          NextDialogue = 51002012,
          SpeakNpcId = 700048,
          Subtitle = "Our island was covered by a giant Heaventree, that you couldn't find on any ordinary map."
        },
        [51002012] = {
          ContentFR = "Dans une grotte secrète, il y avait la statue d’une déesse plus belle que toutes les femmes de ce monde ! On dit que le trésor repose juste derrière elle.",
          DialogueId = 51002012,
          GUID = "7FAD9D98",
          NextDialogue = 51002013,
          SpeakNpcId = 700048,
          Subtitle = "There's a secret cave on the island with a statue of a goddess more beautiful than any woman you've ever seen! Legend has it that the treasure is hidden right behind this goddess statue.",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002013] = {
          ContentFR = "Mais... pour savoir en quoi consiste ce trésor exactement, il faudra m’offrir quelques pièces de plus.",
          DialogueId = 51002013,
          GUID = "7FAD9DC2",
          NextOptions = {
            [1] = 510020131
          },
          RestartTag = 51002013,
          SpeakNpcId = 700048,
          Subtitle = "As for what this treasure is, if you want to hear more, just a few silver coins will suffice.",
          bForbidSkipOptions = true
        },
        [51002014] = {
          ContentFR = "<I>Ça ressemble fort à l’Île du Purgatoire. Cet homme est sûrement un escroc. Inutile de perdre plus de temps.</>",
          DialogueId = 51002014,
          GUID = "7FAD9DEC",
          NextDialogue = 51002015,
          SpeakNpcId = 100001,
          Subtitle = "(It sounds a lot like Purgatorio Island. This guy is probably a swindler. Best not to waste any time on him.)"
        },
        [51002015] = {
          ContentFR = "Laissez tomber. Je n’ai pas assez de pièces pour les jeter à la première fable venue.",
          DialogueId = 51002015,
          GUID = "7FAD9E16",
          SpeakNpcId = 100001,
          Subtitle = "Forget it. My coins are in short supply so I can't throw them around just to hear something."
        },
        [51002016] = {
          ContentFR = "<I>Cet îlot du sud... il est bien dominé par un Arbre Céleste gigantesque ? On l’appelle l’Île du Purgatoire, n’est-ce pas ?</>",
          DialogueId = 51002016,
          GUID = "7FAD9E40",
          NextDialogue = 51002017,
          SpeakNpcId = 100001,
          Subtitle = "This southern island you're talking about, does it have a giant Heaventree near it, and do they call it Purgatorio Island?"
        },
        [51002017] = {
          ContentFR = "... !",
          DialogueId = 51002017,
          GUID = "7FAD9E6A",
          NextDialogue = 51002018,
          SpeakNpcId = 700048,
          Subtitle = "!!!"
        },
        [51002018] = {
          ContentFR = "Comment connais-tu ce nom ?",
          DialogueId = 51002018,
          GUID = "7FAD9E94",
          NextDialogue = 51002019,
          SpeakNpcId = 700048,
          Subtitle = "How do you know that name?",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002019] = {
          ContentFR = "C’était chez moi.",
          DialogueId = 51002019,
          GUID = "7FAD9EBE",
          NextDialogue = 51002020,
          SpeakNpcId = 100001,
          Subtitle = "That was my home."
        },
        [51002020] = {
          ContentFR = "... Toi aussi tu viens de là-bas ? Attends... ils laissent désormais les villageois partir ?",
          DialogueId = 51002020,
          GUID = "7FAD9EE8",
          NextDialogue = 51002021,
          SpeakNpcId = 700048,
          Subtitle = "...You're from there too? Have they stopped preventing villagers from leaving?",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002021] = {
          ContentFR = "Bon, inutile de te mentir. À vingt ans, je suis parti pêcher au large. En voyant la côte de l’Empire, sinueuse comme les châteaux et les selles de mes livres, j’ai eu un déclic.",
          DialogueId = 51002021,
          GUID = "7FAD9F12",
          NextDialogue = 51002022,
          SpeakNpcId = 700048,
          Subtitle = "Tell you what, when I was twenty, I went out to fish on the sea. I looked at the coastline of the Empire, which was winding like the saddles and castles I'd read about in books."
        },
        [51002022] = {
          ContentFR = "Au lieu de rentrer avec ma pêche, j’ai continué vers l’est, jusqu’à atteindre ce rivage. Mais la vie ici n’était pas vraiment ce que j’avais imaginé...",
          DialogueId = 51002022,
          GUID = "7FAD9F3C",
          NextDialogue = 51002023,
          SpeakNpcId = 700048,
          Subtitle = "So, instead of taking my catch home as usual, I kept heading east, to this side of the coast. But life here turned out to be a bit different from what I had imagined..."
        },
        [51002023] = {
          ContentFR = "Ça fait plus de dix ans. Et maintenant, je n’ai même plus de quoi payer le voyage du retour. Alors je me débrouille avec mon éloquence...",
          DialogueId = 51002023,
          GUID = "7FAD9F66",
          NextDialogue = 51002024,
          SpeakNpcId = 700048,
          Subtitle = "It's been over a decade, and now I can't even scrape together enough for the fare back. I can only make ends meet with my eloquence.",
          TalkActionId = {
            [1] = "700048:Sigh_Start"
          }
        },
        [51002024] = {
          ContentFR = "Puisque tu viens de l’île aussi... dis-moi, la maison tout à l’est du village, est-ce que tu sais si ses habitants vont bien ?",
          DialogueId = 51002024,
          GUID = "7FAD9F90",
          NextDialogue = 51002025,
          SpeakNpcId = 700048,
          Subtitle = "So, since you're also from Purgatorio Island, do you know how the family at the easternmost part of the village is doing?",
          TalkActionId = {
            [1] = "700048:Sigh_End"
          }
        },
        [51002025] = {
          ContentFR = "Tu lui racontes l’attaque des Souillés et la fuite des villageois par bateau.",
          DialogueId = 51002025,
          GUID = "7FAD9FBA",
          NextDialogue = 51002026,
          SpeakNpcId = 100001,
          Subtitle = "(You told him about the village being attacked by Filthoids, with most villagers escaping by boat.)"
        },
        [51002026] = {
          ContentFR = "Quoi... ?!",
          DialogueId = 51002026,
          GUID = "7FAD9FE4",
          NextDialogue = 51002027,
          SpeakNpcId = 700048,
          Subtitle = "What the..."
        },
        [51002027] = {
          ContentFR = "Mais... d’après toi, ils ont réussi à s’échapper ? Alors tant mieux... tant mieux...",
          DialogueId = 51002027,
          GUID = "7FADA00E",
          NextDialogue = 51002028,
          SpeakNpcId = 700048,
          Subtitle = "But you just said they all escaped, right? Thank god... As long as they've got away...",
          TalkActionId = {
            [1] = "700048:Agree"
          }
        },
        [51002028] = {
          ContentFR = "Dis, si jamais tu retournes sur l’Île du Purgatoire, pourrais-tu jeter un œil près de ma vieille maison ? Voir s’il reste quelque chose...",
          DialogueId = 51002028,
          GUID = "7FADA038",
          NextDialogue = 51002029,
          SpeakNpcId = 700048,
          Subtitle = "By the way, if you ever get a chance to go back to Purgatorio Island, could you check near my old house to see if there's anything left?"
        },
        [51002029] = {
          ContentFR = "Et s’il n’y a vraiment rien, rapporte-moi n’importe quoi. Même un brin d’herbe ferait l’affaire.",
          DialogueId = 51002029,
          GUID = "7FADA062",
          NextDialogue = 51002030,
          SpeakNpcId = 700048,
          Subtitle = "If you can't find anything, just bring back something for me. Anything will do, even a blade of grass.",
          TalkActionId = {
            [1] = "700048:Explain02_Start"
          }
        },
        [51002030] = {
          ContentFR = "D’accord.",
          DialogueId = 51002030,
          GUID = "7FADA08C",
          SpeakNpcId = 100001,
          Subtitle = "Sure."
        },
        [51002031] = {
          ContentFR = "Ah... quand j’étais jeune, partir était si difficile, et maintenant, quand j’aimerais rentrer, je n’en ai plus la possibilité...",
          DialogueId = 51002031,
          GUID = "7FADA0B6",
          NextDialogue = 51002032,
          SpeakNpcId = 700048,
          Subtitle = "It was so hard to leave when I was young, and now I can't go back...",
          TalkActionId = {
            [1] = "700048:Explain02_End"
          }
        },
        [51002032] = {
          ContentFR = "Prends soin de toi.",
          DialogueId = 51002032,
          GUID = "7FADA0E0",
          SpeakNpcId = 100001,
          Subtitle = "Take care."
        },
        [51002101] = {
          ContentFR = "Ça doit être ici, la maison de Brunetto. Voyons s’il reste quelque chose que je puisse lui rapporter.",
          DialogueId = 51002101,
          Duration = 3,
          GUID = "7FADAC32",
          NextDialogue = 51002102,
          SpeakNpcId = 100001,
          Subtitle = "This should be it — Brunetto's old place."
        },
        [51002102] = {
          ContentFR = "Tiens... un coffre. Peut-être qu’il contient un souvenir à lui ramener.",
          DialogueId = 51002102,
          Duration = 4,
          GUID = "7FADAC5C",
          NextDialogue = 51002103,
          SpeakNpcId = 100001,
          Subtitle = "There's a chest here. Might be something inside I can bring back for him."
        },
        [51002103] = {
          ContentFR = "Pas de chance, il est fermé... Allons chercher la clé dans les environs.",
          DialogueId = 51002103,
          Duration = 2.5,
          GUID = "7FADAC86",
          SpeakNpcId = 100001,
          Subtitle = "No key, though... I'll have a look around. Maybe it's nearby."
        },
        [51002104] = {
          ContentFR = "Vu la forme, cette clé devrait convenir. Essayons.",
          DialogueId = 51002104,
          Duration = 2,
          GUID = "7FADAC87",
          SpeakNpcId = 100001,
          Subtitle = "Looks like this fits. Let's give it a try."
        },
        [51002105] = {
          Camera = "183.0,143.319336,121.0,0.0,-0.99996,-114.999725,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "La clé tourne lentement. Le barillet rouillé résiste, grinçant d’un bruit strident. Quand le couvercle s’ouvre enfin, le vacarme attire aussitôt une meute de Souillés qui te barre le passage.",
          DialogueId = 51002105,
          FinalCamera = "186.0,143.319336,121.0,0.0,-0.99996,-114.999725,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC88",
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Think_Start"},Duration{2}},
CameraMoveTo{_delay{3},TargetPosition{"-55.90625,-613.697266,78.0,0.0,0.0,72.803268,35.0,100000.0,false,DoNotOverride,2.8"},duration{0}},
PARA{
CameraMoveTo{_delay{3},TargetPosition{"-127.292969,-843.583984,77.028931,0.0,0.0,72.203499,35.0,100000.0,false,DoNotOverride,2.8"},duration{7}},
SetLocation{ActorId{700208},TargetPoint{"MovePoint_700208"},Visibility{"Show"}},
SetLocation{ActorId{700209},TargetPoint{"MovePoint_700209"},Visibility{"Show"}},
SEQ{
PlayAnimation{_delay{1},ActorId{100001},AnimationId{"Think_End"},Duration{1}},
TurnTo{_delay{2},TurnToDescription{"100001:p(-130)"}}
}
}
}]],
          Subtitle = "(The key scrapes against the rusted lock, screeching sharp and loud. As the chest creaks open, the noise cuts through the silence, and from the shadows, a pack of Filthoids comes swarming, blocking your way out.)",
          ToFinalCameraBlendTime = 3
        },
        [51002106] = {
          Camera = "-160.396484,-385.0,156.553223,0.0,-14.799763,65.201347,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Les Souillés ne t’ont pas posé de réelle difficulté. Pourtant, ce bref affrontement a réveillé en toi une étrange familiarité. Un souvenir ancien refait surface : tu entends presque deux enfants se chamailler devant cette maison.",
          DialogueId = 51002106,
          FinalCamera = "-160.396484,-404.0,156.553223,0.0,-14.799763,65.201347,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC89",
          NextDialogue = 51002107,
          Subtitle = "(The Filthoids weren't much trouble — but something about the scuffle tugs at your memory. You catch a flash of a distant summer afternoon: two kids scrapping in front of this very house.)",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          },
          ToFinalCameraBlendTime = 7
        },
        [51002107] = {
          Camera = "119.585938,-26.257812,128.0,-0.0,-9.999997,-145.798935,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ça me revient... Quand j’étais gosse, je me suis {性别:battu|battue} avec l’enfant qui vivait ici. Son nom m’échappe... mais en y repensant, ça devait être le petit-fils de Brunetto.",
          DialogueId = 51002107,
          FinalCamera = "119.585938,-26.257812,128.0,0.0,-9.999997,-138.598923,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8A",
          NextDialogue = 51002108,
          Scripts = "TurnTo{_delay{3},TurnToDescription{\"100001:n(700211)\"}}",
          SpeakNpcId = 100001,
          Subtitle = "It's coming back to me now. I once got into a fight with the boy who lived here. Can't quite remember his name... but he must've been Brunetto's grandson.",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          ToFinalCameraBlendTime = 7
        },
        [51002108] = {
          Camera = "-180.842773,-670.0,18.0,0.000018,4.000004,83.599602,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je ne sais plus ce qui avait déclenché la bagarre. Mais je me souviens encore de nos dernières piques avant d’en venir aux poings... Ce garnement m’a traité de cyclope, et moi je l’ai traité de crapaud aux yeux globuleux.",
          DialogueId = 51002108,
          GUID = "7FADAC8B",
          NextDialogue = 51002109,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Think_Start"},Duration{2}},
CameraMoveTo{_delay{3},TargetPosition{"88.632812,-31.105469,133.52002,0.000039,-12.79989,-135.199905,35.0,100000.0,false,DoNotOverride,2.8"},duration{0}},
PlayAnimation{_delay{1},ActorId{700211},AnimationId{"Angry01_Start"},Duration{1}},
}]],
          SpeakNpcId = 100001,
          Subtitle = "I don't even recall what started it. But I do remember the last thing we said before it turned physical — he called me \"One-Eye,\" and I shot back with \"googly-eyed toad.\""
        },
        [51002109] = {
          Camera = "-143.595703,-312.263672,94.0,0.0,0.0,57.398624,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Haha... J’étais sacrément {性别:insolent|insolente}. Pourtant, je crois que je n’étais même pas si en colère. J’avais encore Berry à mes côtés, après tout...",
          DialogueId = 51002109,
          GUID = "7FADAC8C",
          NextDialogue = 51002110,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{100001},AnimationId{"Sigh_Start"},Duration{3}},
PlayAnimation{ActorId{100001},AnimationId{"Sigh_End"},Duration{2}},
PlayAnimation{ActorId{100001},AnimationId{"Explain02_Start"},Duration{2}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Heh... I was kinda mean back then. Funny thing is, I don't think I was actually mad. I still had Berry with me, after all..."
        },
        [51002110] = {
          Camera = "70.748047,32.113281,1751.04126,0.000001,-10.799894,-176.601151,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et plus tard... je crois qu’on s’est réconciliés. J’ai le souvenir de nous deux perchés sur le toit de la maison...",
          DialogueId = 51002110,
          FinalCamera = "70.748047,32.113281,1859.0,0.000001,-10.799894,-176.601151,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8D",
          SpeakNpcId = 100001,
          Subtitle = "And later... I think we made up. I remember the two of us climbing up to the roof...",
          ToFinalCameraBlendTime = 7
        },
        [51002111] = {
          Camera = "51.001041,365.471497,103.367798,0.000078,-11.300083,-137.003372,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah, oui, c’était là. Quelques jours plus tard, il est revenu avec un sac de provisions pour s’excuser. J’étais prêt à l’envoyer balader... mais quand j’ai vu ce pain énorme, assez pour trois, j’ai laissé tomber ma fierté.",
          DialogueId = 51002111,
          FinalCamera = "14.224466,404.913452,103.367798,0.000078,-11.300083,-137.003372,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8E",
          NextDialogue = 51002112,
          SpeakNpcId = 700210,
          Subtitle = "Yeah — this spot. Right here. A few days later, he came back with food to apologise. I was all ready to yell at him... but when I saw that bread in his hands — big enough for the three of us to eat our fill — well, my stomach won that battle over my pride.",
          ToFinalCameraBlendTime = 7
        },
        [51002112] = {
          Camera = "-78.281792,63.089108,96.67688,0.000094,-0.099919,90.79702,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors, on est restés là, tous les trois, à mâcher ce pain dur et brûlé, en regardant le soleil décliner et les pêcheurs rentrer au village.",
          DialogueId = 51002112,
          FinalCamera = "-123.657745,62.460995,96.67688,0.000094,-0.099919,90.797005,20.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC8F",
          NextDialogue = 51002113,
          SpeakNpcId = 700210,
          Subtitle = "So we sat up here, the three of us. Quietly chewing on that tough, burnt bread, watching the sun dip low while the grown-ups hauled in the day's catch.",
          ToFinalCameraBlendTime = 7
        },
        [51002113] = {
          Camera = "-182.640976,408.587311,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et puis, ce petit morveux s’est mis à s’étouffer, enchaînant les hoquets. On a éclaté de rire. La dispute s’est terminée comme ça.",
          DialogueId = 51002113,
          FacialId = {
            [1] = "700210:Ahaha02"
          },
          FinalCamera = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC90",
          NextDialogue = 51002114,
          SpeakNpcId = 700210,
          Subtitle = "And then... with one massive bite, he started hiccuping like crazy. We couldn't stop laughing — and just like that, the fight was forgotten.",
          ToFinalCameraBlendTime = 7
        },
        [51002114] = {
          Camera = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Au final... on peux dire que je connais Brunetto depuis ce jour-là, en quelque sorte.",
          DialogueId = 51002114,
          FacialId = {
            [1] = "700210:Smile02"
          },
          GUID = "7FADAC91",
          NextDialogue = 51002115,
          SpeakNpcId = 700210,
          Subtitle = "...Huh. Guess I've known Brunetto — sort of — since way back then."
        },
        [51002115] = {
          Camera = "-172.15773,415.39325,62.499023,0.000002,0.0,-57.003651,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et s’il n’y a vraiment rien, rapporte-moi n’importe quoi. Même un brin d’herbe ferait l’affaire.",
          DialogueId = 51002115,
          GUID = "7FADAC92",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030106.T_Story_Recall_10030106'",
          NextDialogue = 51002116,
          SpeakNpcId = 700048,
          Subtitle = "If you can't find anything, just bring back something for me. Anything will do, even a blade of grass."
        },
        [51002116] = {
          Camera = "167.319687,115.790215,166.645142,0.000015,-18.599697,145.793152,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Il voulait que je lui rapporte n’importe quoi... Peut-être que je pourrais ajouter quelque chose de plus. Les poissons de ce coin sont bien dodus en cette saison.",
          DialogueId = 51002116,
          FinalCamera = "181.948135,137.309357,166.645142,0.000015,-18.599697,145.793152,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FADAC93",
          SpeakNpcId = 700210,
          Subtitle = "Maybe I'll bring him a little extra, too. If I remember right, the fish are nice and plump this time of year.",
          ToFinalCameraBlendTime = 7
        },
        [51002117] = {
          ContentFR = "Voilà. Avec ça, son mal du pays devrait être un peu apaisé.",
          DialogueId = 51002117,
          Duration = 3,
          GUID = "7FADAC94",
          NextDialogue = 51002118,
          SpeakNpcId = 100001,
          Subtitle = "Alright — time to head back. This should help ease a bit of that homesickness."
        },
        [51002118] = {
          ContentFR = "Le petit-fils, je l’ai connu en me battant... et le grand-père, en me faisant arnaquer. Ah... quelle drôle de destinée.",
          DialogueId = 51002118,
          Duration = 4,
          GUID = "7FADAC95",
          SpeakNpcId = 100001,
          Subtitle = "Huh. Got to know the grandson through a fistfight... and the grandfather through a street scam. Heh. Life really does have a funny way of looping people together, doesn't it?"
        },
        [51002201] = {
          ContentFR = "Amis de passage ! Pour quelques pièces, rejoignez l’Association des pêcheurs de Givrelac et profitez de conseils de maîtres avec des décennies d’expérience— Ah ! C’est toi...",
          DialogueId = 51002201,
          GUID = "7FADBC9A",
          NextDialogue = 51002202,
          SpeakNpcId = 700048,
          Subtitle = "Ladies and gentlemen, drop by and drop a few coins, and you can join The Fisheries in Icelake to get the best and latest— Oh! It's you..."
        },
        [51002202] = {
          ContentFR = "Ceci devrait t’appartenir, non ?",
          DialogueId = 51002202,
          GUID = "7FADBCC4",
          NextDialogue = 51002203,
          SpeakNpcId = 100001,
          Subtitle = "Is this yours?"
        },
        [51002203] = {
          ContentFR = "Ah ! ... Oui ! C’est bien ce vieux livre que je lisais sans cesse étant enfant. C’est en feuilletant ces pages que j’ai rêvé de quitter notre îlot minuscule...",
          DialogueId = 51002203,
          GUID = "7FADBCEE",
          NextDialogue = 51002204,
          SpeakNpcId = 700048,
          Subtitle = "Ah! That's it! The book I used to pore over for hours as a kid. I'd sit there staring at the pictures, dreaming of life beyond our tiny island...",
          TalkActionId = {
            [1] = "700048:Agree"
          }
        },
        [51002204] = {
          ContentFR = "Merci. Merci infiniment. Ce soir, je vais le relire d’un bout à l’autre. Mais pour l’instant... <I>soupir,</> il faut bien continuer à gagner sa croûte.",
          DialogueId = 51002204,
          GUID = "7FADBD18",
          NextDialogue = 51002205,
          SpeakNpcId = 700048,
          Subtitle = "Thank you. Thank you so much. I need to give it a good read tonight. But for now, *sigh* making a living is more important.",
          TalkActionId = {
            [1] = "700048:Explain01_Start"
          }
        },
        [51002205] = {
          ContentFR = "Prends soin de toi. Et évite d’arnaquer les gens, d’accord ? Tiens, prends aussi ça, du poisson séché de l’Île du Purgatoire.",
          DialogueId = 51002205,
          GUID = "7FADBD42",
          NextDialogue = 51002206,
          SpeakNpcId = 100001,
          Subtitle = "Take care. And no more scamming people, alright? Oh, and here — some dried fish, caught off Purgatorio Island.",
          TalkActionId = {
            [1] = "700048:Explain01_End"
          }
        },
        [51002206] = {
          ContentFR = "... Oh. Merci. Merci du fond du cœur...",
          DialogueId = 51002206,
          GUID = "7FADBD6C",
          SpeakNpcId = 700048,
          Subtitle = "Oh, wow... Thank you. Really. Thank you so much..."
        },
        [51002207] = {
          ContentFR = "Amis de passage ! L’Association des pêcheurs de Givrelac recrute. Que ce soit par passion ou pour le métier, la pêche, c’est le bonheur garanti !",
          DialogueId = 51002207,
          GUID = "7FADBD96",
          NextDialogue = 51002208,
          SpeakNpcId = 700048,
          Subtitle = "Ladies and gentlemen, those who are interested in Icelake Fishermen's Mutual Aid Society can learn more about it. We have decades of fishing experience from veteran fishermen. Fishing is great either serving as a hobby or a job!"
        },
        [51002208] = {
          ContentFR = "Tiens donc, {nickname} ! Ça fait plaisir de croiser {性别:un|une} compatriote. On échangera nos techniques de pêche à l’occasion ?",
          DialogueId = 51002208,
          GUID = "7FADBD97",
          NextDialogue = 51002209,
          SpeakNpcId = 700048,
          Subtitle = "Ah, {Nickname}! Great to see you again! Us old island folk ought to swap fishing tricks sometime, eh?"
        },
        [51002209] = {
          ContentFR = "Avec plaisir, une prochaine fois.",
          DialogueId = 51002209,
          GUID = "7FADBDC0",
          SpeakNpcId = 100001,
          Subtitle = "Maybe next time."
        },
        [51002301] = {
          ContentFR = "{性别:Jeune homme|Jeune femme}, as-tu des nouvelles de Hamel Dickinson ?",
          DialogueId = 51002301,
          GUID = "7FADCD02",
          NextOptions = {
            [1] = 510023011
          },
          SpeakNpcId = 700019,
          Subtitle = "Young one, any news of Hamel Dickinson?"
        },
        [51002302] = {
          ContentFR = "Le journal découvert dans la Fosse de Glevum porte ce nom : Hamel Dickinson.",
          DialogueId = 51002302,
          GUID = "7FADCD2C",
          NextDialogue = 51002303,
          Subtitle = "(Indeed, it is the same name on the title page of the journal you retrieved from Glevum Pit.)"
        },
        [51002303] = {
          ContentFR = "Si vous ne vous trompez pas, alors le monstre qui hante les profondeurs de la mine... n’est autre que lui.",
          DialogueId = 51002303,
          GUID = "7FADCD56",
          NextDialogue = 51002304,
          Subtitle = "(If your guess is correct, then the monster haunting the depths of the pit might just be...)"
        },
        [51002304] = {
          ContentFR = "À l’évocation de ce nom, un éclat traverse les yeux ternis de la vieille femme. Pour Dame Hilin, Hamel Dickinson n’est pas un simple souvenir : ce nom porte un poids immense. Elle attend votre réponse, animée d’une lueur d’espoir fébrile.",
          DialogueId = 51002304,
          GUID = "7FADCD80",
          NextOptions = {
            [1] = 510023041,
            [2] = 510023042
          },
          Subtitle = "(Her cloudy eyes brighten slightly at the mention of that man. The name Hamel Dickinson clearly holds great significance for her. She is awaiting an answer.)",
          bForbidSkipOptions = true
        },
        [51002305] = {
          ContentFR = "...",
          DialogueId = 51002305,
          GUID = "7FADCDAA",
          NextDialogue = 51002306,
          SpeakNpcId = 700019,
          Subtitle = "..."
        },
        [51002306] = {
          ContentFR = "Elle le lit en silence, mot après mot. Des larmes coulent de ses yeux plissés.",
          DialogueId = 51002306,
          GUID = "7FADCDD4",
          NextDialogue = 51002307,
          Subtitle = "(Word by word, she silently reads through the journal. Tears stream down her deeply lined cheeks.)"
        },
        [51002307] = {
          ContentFR = "Puis elle serre le journal contre sa poitrine, comme pour enlacer un amour perdu.",
          DialogueId = 51002307,
          GUID = "7FADCDFE",
          NextDialogue = 51002308,
          Subtitle = "(She then clasps the journal to her chest, as if embracing a long-lost beloved.)"
        },
        [51002308] = {
          ContentFR = "... Merci, {性别:jeune homme|jeune femme}. Merci de m’avoir rendu ce secret enfoui depuis quarante ans.",
          DialogueId = 51002308,
          GUID = "7FADCE28",
          NextDialogue = 51002309,
          SpeakNpcId = 700019,
          Subtitle = "...Thank you, young one. Thank you for uncovering this secret that's been buried for forty years.",
          TalkActionId = {
            [1] = "700019:Explain02_Start"
          }
        },
        [51002309] = {
          ContentFR = "S’il te plaît, va voir ma servante Sally pour ta récompense. J’aimerais rester seule un moment...",
          DialogueId = 51002309,
          GUID = "7FADCE52",
          NextDialogue = 51002310,
          SpeakNpcId = 700019,
          Subtitle = "Please see my maid Sally for your reward. I'd like some time alone."
        },
        [51002310] = {
          ContentFR = "Elle tourne le dos. Sa silhouette voûtée se perd dans la lumière froide.",
          DialogueId = 51002310,
          GUID = "7FADCE7C",
          Subtitle = "(She turns away, her frail, stooped back towards you.)"
        },
        [51002311] = {
          ContentFR = "...",
          DialogueId = 51002311,
          GUID = "7FADCEA6",
          SpeakNpcId = 700019,
          Subtitle = "..."
        },
        [51002312] = {
          ContentFR = "Je suis {性别:désolé|désolée}, ce nom ne me dit rien. Si jamais j’obtiens des informations, je reviendrai vous voir.",
          DialogueId = 51002312,
          GUID = "7FADCED0",
          NextDialogue = 51002313,
          SpeakNpcId = 100001,
          Subtitle = "Sorry, I've never heard that name. If I get any news, I will get back to you."
        },
        [51002313] = {
          ContentFR = "Très bien... très bien. Merci à toi, {性别:jeune homme|jeune femme}.",
          DialogueId = 51002313,
          GUID = "7FADCEFA",
          NextDialogue = 51002314,
          SpeakNpcId = 700019,
          Subtitle = "Okay, okay... Thank you."
        },
        [51002314] = {
          ContentFR = "J’ai préparé une modeste récompense. Rends-toi à ma demeure et adresse-toi à ma servante, Sally. Dis-lui que c’est Dame Hilin qui t’envoie.",
          DialogueId = 51002314,
          GUID = "7FADCF24",
          NextDialogue = 51002315,
          SpeakNpcId = 700019,
          Subtitle = "I've prepared a gift. Please go to my house and ask for my maid, Sally, and tell her that Lady Hilin sent you."
        },
        [51002315] = {
          ContentFR = "Va maintenant... que ta route soit paisible.",
          DialogueId = 51002315,
          GUID = "7FADCF4E",
          SpeakNpcId = 700019,
          Subtitle = "Just go. May you have a smooth journey."
        },
        [51002320] = {
          ContentFR = "Mon enfant, tu es donc {性别:ce Chasseur de Phoxène nommé|cette Chasseuse de Phoxène nommée} {nickname} ? Dame Hilin m’a demandé de te remettre ta récompense en avance.",
          DialogueId = 51002320,
          GUID = "7FADD020",
          NextDialogue = 51002321,
          SpeakNpcId = 700020,
          Subtitle = "Child, you're , the Phoxhunter, aren't you? Lady Hilin told me to pay you in advance.",
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002321] = {
          ContentFR = "Si jamais tu entends parler de Hamel Dickinson, n’hésite pas à le dire rapidement à Dame Hilin.",
          DialogueId = 51002321,
          GUID = "7FADD04A",
          NextDialogue = 51002322,
          SpeakNpcId = 700020,
          Subtitle = "Should you hear anything about Hamel Dickinson, please do tell her ladyship as soon as possible.",
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002322] = {
          ContentFR = "<I>Soupir. </>Depuis l’année dernière, sa santé décline de plus en plus... Je crains qu’il ne lui reste plus beaucoup de temps. La question de Hamel est son ultime souci...",
          DialogueId = 51002322,
          GUID = "7FADD074",
          NextOptions = {
            [1] = 51002323
          },
          SpeakNpcId = 700020,
          Subtitle = "*sigh* She's been really going downhill since last year, and now I'm afraid she doesn't have much time left. Information about Hamel is the last remaining thing weighing on her mind.",
          TalkActionId = {
            [1] = "700020:Sigh_End"
          }
        },
        [51002323] = {
          ContentFR = "Pouvez-vous me raconter ce qui s’est passé avec Hamel Dickinson ?",
          DialogueId = 51002323,
          GUID = "51002323.0",
          NextDialogue = 51002404,
          Subtitle = "Could you tell me more about Mr Dickinson?"
        },
        [51002401] = {
          ContentFR = "Merci, mon enfant. Voilà une petite récompense pour tout ce que tu as fait pour nous.",
          DialogueId = 51002401,
          GUID = "7FADDD6A",
          NextDialogue = 51002402,
          SpeakNpcId = 700020,
          Subtitle = "Child, thank you for all your help. Here's a little something for you.",
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002402] = {
          ContentFR = "Hélas... Sa Seigneurie dépérit depuis l’an dernier. Elle n’a plus beaucoup de jours devant elle. L’histoire de Monsieur Dickinson ... c’était sa dernière préoccupation.",
          DialogueId = 51002402,
          GUID = "7FADDD94",
          NextDialogue = 51002403,
          SpeakNpcId = 700020,
          Subtitle = "*sigh* Her ladyship's health has worsened since last year, and I fear she doesn't have much time left. Her past with Mr Dickinson was the last thing on her mind...",
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002403] = {
          ContentFR = "Ce n’est certes pas la bonne nouvelle que nous espérions, mais Tante Sally tient quand même à te remercier, tu as comblé son dernier souhait.",
          DialogueId = 51002403,
          GUID = "7FADDDBE",
          NextOptions = {
            [1] = 510024031
          },
          SpeakNpcId = 700020,
          Subtitle = "Though it wasn't the news we hoped for, I still want to thank you for helping her retrieve this final piece of her past.",
          TalkActionId = {
            [1] = "700020:Sigh_End"
          }
        },
        [51002404] = {
          ContentFR = "Hélas... je suppose qu’il n’y a plus de raison de garder des secrets maintenant.",
          DialogueId = 51002404,
          GUID = "7FADDDE8",
          NextDialogue = 51002405,
          SpeakNpcId = 700020,
          Subtitle = "Well... I suppose there's no point in keeping secrets now.",
          TalkActionId = {
            [1] = "700020:Explain01_Start"
          }
        },
        [51002405] = {
          ContentFR = "Tu l’auras peut-être deviné, mais Monsieur Dickinson était le grand amour de Dame Hilin il y a quarante ans. À l’époque, elle n’était pas encore \"dame\", on l’appelait Mademoiselle Hilin, une jeune fille vive et passionnée.",
          DialogueId = 51002405,
          GUID = "7FADDE12",
          NextDialogue = 51002406,
          SpeakNpcId = 700020,
          Subtitle = "You might have guessed — Mr Dickinson was her ladyship's beau forty years ago. At that time, her ladyship... well, it was Miss Hilin back then — was a cheerful, lively girl.Hamel Dickinson was a miner of her age, working at her father's Glevum Pit."
        },
        [51002406] = {
          ContentFR = "Comme dans toutes ces histoires, plus la différence de rang était grande, plus leur attachement était obstiné. Ils s’accrochaient l’un à l’autre contre l’avis du monde entier.",
          DialogueId = 51002406,
          GUID = "7FADDE3C",
          NextDialogue = 51002407,
          SpeakNpcId = 700020,
          Subtitle = "As it often goes in such stories, the greater their social divide, the more stubbornly they clung to each other against all odds.",
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51002407] = {
          ContentFR = "On raconte que l’amour est comme une flamme : plus on tente de l’éteindre, plus il s’enflamme. Mais ces histoires ne disent pas à quel point, face à la dure réalité, quand la digue cède, cette flamme peut devenir dérisoire.",
          DialogueId = 51002407,
          GUID = "7FADDE66",
          NextDialogue = 51002408,
          SpeakNpcId = 700020,
          Subtitle = "They say love burns brighter under opposition, but those stories don't tell you how quickly it can be extinguished by harsh reality!"
        },
        [51002408] = {
          ContentFR = "Quand la nouvelle parvint aux oreilles du maître, le directeur de la Fosse de Glevum, nommé par les Éolipyliens, Hamel Dickinson n’eut pas de bénédiction. Il reçut une raclée.",
          DialogueId = 51002408,
          GUID = "7FADDE90",
          NextDialogue = 51002409,
          SpeakNpcId = 700020,
          Subtitle = "When the master, who was the director of Glevum Pit appointed by the Aeolipile, learned about their relationship, Hamel Dickinson received a terrible thrashing instead of the master's blessing."
        },
        [51002409] = {
          ContentFR = "Ce n’était pas seulement à cause de sa condition sociale : le maître avait déjà arrangé pour Mademoiselle un mariage de convenance, avec un noble de la province de Flagson, une alliance parfaite entre nouveaux riches et vieille noblesse déclinante, où chacun y trouvait son compte.",
          DialogueId = 51002409,
          GUID = "7FADDEBA",
          NextDialogue = 51002410,
          SpeakNpcId = 700020,
          Subtitle = "It was not just because of his background — the master had already arranged a politically advantageous marriage for Miss Hilin. She was supposed to marry a noble from Flagson — a perfect match that would benefit both a new money family and a declining noble line.",
          TalkActionId = {
            [1] = "700020:Explain01_Start"
          }
        },
        [51002410] = {
          ContentFR = "Pourtant, elle n’abandonna pas. Elle me confia une lettre pour Hamel Dickinson, lui donnant rendez-vous le 26 avril, à minuit, sur la Place de la Paix d’Argent.",
          DialogueId = 51002410,
          GUID = "7FADDEE4",
          NextDialogue = 51002411,
          SpeakNpcId = 700020,
          Subtitle = "But Miss Hilin didn't give up. She was such a brave and assertive young lady back then. She secretly asked me to deliver a letter to Mr Dickinson, asking him to meet her at midnight on April 26th at the Silverpeace Square."
        },
        [51002411] = {
          ContentFR = "C’était le jour de l’anniversaire de son père, la maison entière serait absorbée par la fête, et elle comptait s’échapper.",
          DialogueId = 51002411,
          GUID = "7FADDF0E",
          NextDialogue = 51002412,
          SpeakNpcId = 700020,
          Subtitle = "That day happened to be the master's birthday, and all hands would be busy preparing for the celebration. Miss Hilin saw it as her only chance to escape her father's control.",
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51002412] = {
          ContentFR = "Elle était prête à tout quitter, du moment qu’Hamel venait.",
          DialogueId = 51002412,
          GUID = "7FADDF38",
          NextOptions = {
            [1] = 510024141
          },
          SpeakNpcId = 700020,
          Subtitle = "She made up her mind that if he showed up, she would run away with him, no matter the destination."
        },
        [51002415] = {
          ContentFR = "Non. Elle l’attendit jusqu’à l’aube. Et à la place, ce fut son père furieux qui l’y trouva. Peu après, elle fut mariée de force à Flagson.",
          DialogueId = 51002415,
          GUID = "7FADDFB6",
          NextDialogue = 51002416,
          SpeakNpcId = 700020,
          Subtitle = "That's right. Miss Hilin waited there till dawn, but only her furious father showed up. Soon after, she was sent away like a parcel to Flagson.",
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002416] = {
          ContentFR = "Heureusement, son mari s’avéra bon avec elle. Elle vécut quarante années paisibles. Comme si Hamel Dickinson n’avait jamais existé.",
          DialogueId = 51002416,
          GUID = "7FADDFE0",
          NextDialogue = 51002417,
          SpeakNpcId = 700020,
          Subtitle = "Thank goodness that her husband — his lordship — treated her well, and she spent forty peaceful years with him. She never mentioned those days again, as if Hamel Dickinson had never existed."
        },
        [51002417] = {
          ContentFR = "Jusqu’à ce qu’il y a un an, son mari décède... Et depuis, la santé de Madame n’a cessé de décliner. Un jour, elle m’a confié qu’avant de quitter ce monde, elle voulait revenir à Givrelac... pour chercher une réponse qu’elle n’avait jamais obtenue. C’est là que j’ai compris : elle n’avait en réalité jamais oublié Hamel Dickinson. Il était devenu comme une écharde plantée dans son cœur.",
          DialogueId = 51002417,
          GUID = "7FADE00A",
          NextDialogue = 51002418,
          SpeakNpcId = 700020,
          Subtitle = "A year ago, his lordship passed away, and her ladyship's health began to fail. One day, she suddenly told me she wanted to return to Icelake in her final days, to find the answer she deserved. That's when I realised, she had never forgotten Hamel Dickinson — he had become a missing piece of her heart."
        },
        [51002418] = {
          ContentFR = "Nous nous sommes installées ici, à Givrelac. Mais nul ici ne se souvenait de lui. Quelques vieux mineurs se rappelaient seulement l’avoir aperçu... il y a quarante ans.",
          DialogueId = 51002418,
          GUID = "7FADE034",
          NextDialogue = 51002419,
          SpeakNpcId = 700020,
          Subtitle = "So we moved back to Icelake, but no one knew of Hamel Dickinson's whereabouts. We managed to track down a few old miners, but after racking their memories, the last time they remembered seeing Mr Dickinson was forty years ago...",
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002419] = {
          ContentFR = "<I>Soupir.</> Je me demande si Dame Hilin pourra voir s’accomplir son dernier souhait de son vivant.",
          DialogueId = 51002419,
          GUID = "7FADE05E",
          NextDialogue = 51002420,
          SpeakNpcId = 700020,
          Subtitle = "*sigh* I wonder if her ladyship will see her final wish come true."
        },
        [51002420] = {
          ContentFR = "Ce ne sont que de vieux souvenirs... Je t’ai peut-être parlé trop longtemps, ça me rappelle que je commence à vieillir.",
          DialogueId = 51002420,
          GUID = "7FADE088",
          NextDialogue = 51002421,
          SpeakNpcId = 700020,
          Subtitle = "Well, it's all in the past. I've been talking your ear off for so long... Guess I'm getting on in years."
        }
      }
    end
  },
  {
    MinKey = 51002421,
    MaxKey = 51003815,
    Loader = function()
      return {
        [51002421] = {
          ContentFR = "Tu es un {性别:Chasseur de Phoxène|Chasseuse de Phoxène}, tu dois être très {性别:occupé|occupée} par tes missions, je ne vais donc pas te retenir plus longtemps.",
          DialogueId = 51002421,
          GUID = "7FADE0B2",
          NextDialogue = 51002422,
          SpeakNpcId = 700020,
          Subtitle = "You're a Phoxhunter, must be quite busy with your commissions. I won't keep you any longer."
        },
        [51002422] = {
          ContentFR = "Elle n’obtiendra probablement jamais la réponse.",
          DialogueId = 51002422,
          GUID = "7FADE0DC",
          NextDialogue = 51002423,
          Subtitle = "(She will probably not get the answer.)"
        },
        [51002423] = {
          ContentFR = "Hamel s’est aventuré dans les profondeurs de la Fosse de Glevum pour Dame Hilin, où il est devenu un Souillé, une créature si terrifiante qu’elle est devenue une légende pendant quarante ans. Il a fini par être tué, une vérité bien trop cruelle pour une vieille femme dont le temps est compté.",
          DialogueId = 51002423,
          GUID = "7FADE106",
          NextDialogue = 51002424,
          Subtitle = "(Hamel ventured deep into the pit for Hilin, where he became a Filthoid — a creature so terrifying it became a legend over forty years. His fate was sealed when he was finally slain, a truth too harsh for an old lady with little time left.)"
        },
        [51002424] = {
          ContentFR = "Cette vérité cruelle restera à jamais enfouie dans les profondeurs de la fosse, tandis que Dame Hilin poursuivra sa vie avec espoir jusqu’à ses derniers jours. Peut-être est-ce là la fin la plus heureuse que l’on puisse espérer.",
          DialogueId = 51002424,
          GUID = "7FADE130",
          Subtitle = "(The cruel truth would remain buried forever in the depths of the pit, with Lady Hilin carrying on with hope until her last days. Perhaps this is as close to a good ending as one might hope for.)"
        },
        [51002425] = {
          ContentFR = "Nous n’aurions jamais imaginé... qu’il avait tenté de la rejoindre. C’est précisément parce qu’il voulait honorer sa promesse qu’il est descendu dans cette fosse... Je ne sais pas si, pour elle, c’est une forme de réconfort... ou une cruauté de plus.",
          DialogueId = 51002425,
          GUID = "7FADE15A",
          NextDialogue = 51002426,
          SpeakNpcId = 700020,
          Subtitle = "...I never expected the truth to be like this! Turns out Mr Dickinson didn't stand her up, and it was because of Lady Hilin that he went to that pit... I don't know if this means consolation or more pain to her."
        },
        [51002426] = {
          ContentFR = "... Et maintenant, voyant Dame Hilin dans cet état, je ne sais vraiment pas comment la consoler...",
          DialogueId = 51002426,
          GUID = "7FADE184",
          NextDialogue = 51002427,
          SpeakNpcId = 700020,
          Subtitle = "...I really don't know how to console her ladyship at the moment..."
        },
        [51002427] = {
          ContentFR = "Bon... je vais préparer le dîner. J’espère juste que ma soupe pourra la faire se sentir un peu mieux.",
          DialogueId = 51002427,
          GUID = "7FADE1AE",
          NextDialogue = 51002428,
          SpeakNpcId = 700020,
          Subtitle = "Ugh, my head hurts! I should go prepare dinner now. I just hope my soup might make her feel a little better."
        },
        [51002428] = {
          ContentFR = "Ainsi, même si la vérité fut implacable, Dame Hilin a pu trouver sa réponse avant de s’éteindre. Plutôt que d’emporter le doute dans la tombe. Peut-être était-ce, malgré tout, la seule fin possible... et la plus douce qu’elle pouvait espérer.",
          DialogueId = 51002428,
          GUID = "7FADE1D8",
          Subtitle = "(Although the truth is harsh, in her final days, she has finally found the answer that was forty years late. At least, she won't have to step into the grave with doubts and regrets. Perhaps this is as close to a good ending as one might hope for.)"
        },
        [51002432] = {
          ContentFR = "Hélas... je suppose qu’il n’y a plus de raison de garder des secrets maintenant.",
          DialogueId = 51002432,
          GUID = "51002432.0",
          NextDialogue = 51002433,
          SpeakNpcId = 700020,
          Subtitle = "Well... I suppose there's no point in keeping secrets now.",
          TalkActionId = {
            [1] = "700020:Explain01_Start"
          }
        },
        [51002433] = {
          ContentFR = "Tu l’auras peut-être deviné, mais Monsieur Dickinson était le grand amour de Dame Hilin il y a quarante ans. À l’époque, elle n’était pas encore \"dame\", on l’appelait Mademoiselle Hilin, une jeune fille vive et passionnée.",
          DialogueId = 51002433,
          GUID = "51002433.0",
          NextDialogue = 51002434,
          SpeakNpcId = 700020,
          Subtitle = "You might have guessed — Mr Dickinson was her ladyship's beau forty years ago. At that time, her ladyship... well, it was Miss Hilin back then — was a cheerful, lively girl.Hamel Dickinson was a miner of her age, working at her father's Glevum Pit."
        },
        [51002434] = {
          ContentFR = "Comme dans toutes ces histoires, plus la différence de rang était grande, plus leur attachement était obstiné. Ils s’accrochaient l’un à l’autre contre l’avis du monde entier.",
          DialogueId = 51002434,
          GUID = "51002434.0",
          NextDialogue = 51002435,
          SpeakNpcId = 700020,
          Subtitle = "As it often goes in such stories, the greater their social divide, the more stubbornly they clung to each other against all odds.",
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51002435] = {
          ContentFR = "On raconte que l’amour est comme une flamme : plus on tente de l’éteindre, plus il s’enflamme. Mais ces histoires ne disent pas à quel point, face à la dure réalité, quand la digue cède, cette flamme peut devenir dérisoire.",
          DialogueId = 51002435,
          GUID = "51002435.0",
          NextDialogue = 51002436,
          SpeakNpcId = 700020,
          Subtitle = "They say love burns brighter under opposition, but those stories don't tell you how quickly it can be extinguished by harsh reality!"
        },
        [51002436] = {
          ContentFR = "Quand la nouvelle parvint aux oreilles du maître, le directeur de la Fosse de Glevum, nommé par les Éolipyliens, Hamel Dickinson n’eut pas de bénédiction. Il reçut une raclée.",
          DialogueId = 51002436,
          GUID = "51002436.0",
          NextDialogue = 51002437,
          SpeakNpcId = 700020,
          Subtitle = "When the master, who was the director of Glevum Pit appointed by the Aeolipile, learned about their relationship, Hamel Dickinson received a terrible thrashing instead of the master's blessing."
        },
        [51002437] = {
          ContentFR = "Ce n’était pas seulement à cause de sa condition sociale : le maître avait déjà arrangé pour Mademoiselle un mariage de convenance, avec un noble de la province de Flagson, une alliance parfaite entre nouveaux riches et vieille noblesse déclinante, où chacun y trouvait son compte.",
          DialogueId = 51002437,
          GUID = "51002437.0",
          NextDialogue = 51002438,
          SpeakNpcId = 700020,
          Subtitle = "It was not just because of his background — the master had already arranged a politically advantageous marriage for Miss Hilin. She was supposed to marry a noble from Flagson — a perfect match that would benefit both a new money family and a declining noble line.",
          TalkActionId = {
            [1] = "700020:Explain01_Start"
          }
        },
        [51002438] = {
          ContentFR = "Pourtant, elle n’abandonna pas. Elle me confia une lettre pour Hamel Dickinson, lui donnant rendez-vous le 26 avril, à minuit, sur la Place de la Paix d’Argent.",
          DialogueId = 51002438,
          GUID = "51002438.0",
          NextDialogue = 51002439,
          SpeakNpcId = 700020,
          Subtitle = "But Miss Hilin didn't give up. She was such a brave and assertive young lady back then. She secretly asked me to deliver a letter to Mr Dickinson, asking him to meet her at midnight on April 26th at the Silverpeace Square."
        },
        [51002439] = {
          ContentFR = "C’était le jour de l’anniversaire de son père, la maison entière serait absorbée par la fête, et elle comptait s’échapper.",
          DialogueId = 51002439,
          GUID = "51002439.0",
          NextDialogue = 51002440,
          SpeakNpcId = 700020,
          Subtitle = "That day happened to be the master's birthday, and all hands would be busy preparing for the celebration. Miss Hilin saw it as her only chance to escape her father's control.",
          TalkActionId = {
            [1] = "700020:Explain01_End"
          }
        },
        [51002440] = {
          ContentFR = "Elle était prête à tout quitter, du moment qu’Hamel venait.",
          DialogueId = 51002440,
          GUID = "51002440.0",
          NextOptions = {
            [1] = 51002441
          },
          SpeakNpcId = 700020,
          Subtitle = "She made up her mind that if he showed up, she would run away with him, no matter the destination."
        },
        [51002441] = {
          ContentFR = "Mais... il n’est jamais venu ?",
          DialogueId = 51002441,
          GUID = "51002441.0",
          NextDialogue = 51002442,
          Subtitle = "He didn't show up?"
        },
        [51002442] = {
          ContentFR = "Non. Elle l’attendit jusqu’à l’aube. Et à la place, ce fut son père furieux qui l’y trouva. Peu après, elle fut mariée de force à Flagson.",
          DialogueId = 51002442,
          GUID = "51002442.0",
          NextDialogue = 51002443,
          SpeakNpcId = 700020,
          Subtitle = "That's right. Miss Hilin waited there till dawn, but only her furious father showed up. Soon after, she was sent away like a parcel to Flagson.",
          TalkActionId = {
            [1] = "700020:Agree"
          }
        },
        [51002443] = {
          ContentFR = "Heureusement, son mari s’avéra bon avec elle. Elle vécut quarante années paisibles. Comme si Hamel Dickinson n’avait jamais existé.",
          DialogueId = 51002443,
          GUID = "51002443.0",
          NextDialogue = 51002444,
          SpeakNpcId = 700020,
          Subtitle = "Thank goodness that her husband — his lordship — treated her well, and she spent forty peaceful years with him. She never mentioned those days again, as if Hamel Dickinson had never existed."
        },
        [51002444] = {
          ContentFR = "Jusqu’à ce qu’il y a un an, son mari décède... Et depuis, la santé de Madame n’a cessé de décliner. Un jour, elle m’a confié qu’avant de quitter ce monde, elle voulait revenir à Givrelac... pour chercher une réponse qu’elle n’avait jamais obtenue. C’est là que j’ai compris : elle n’avait en réalité jamais oublié Hamel Dickinson. Il était devenu comme une écharde plantée dans son cœur.",
          DialogueId = 51002444,
          GUID = "51002444.0",
          NextDialogue = 51002445,
          SpeakNpcId = 700020,
          Subtitle = "A year ago, his lordship passed away, and her ladyship's health began to fail. One day, she suddenly told me she wanted to return to Icelake in her final days, to find the answer she deserved. That's when I realised, she had never forgotten Hamel Dickinson — he had become a missing piece of her heart."
        },
        [51002445] = {
          ContentFR = "Nous nous sommes installées ici, à Givrelac. Mais nul ici ne se souvenait de lui. Quelques vieux mineurs se rappelaient seulement l’avoir aperçu... il y a quarante ans.",
          DialogueId = 51002445,
          GUID = "51002445.0",
          NextDialogue = 51002425,
          SpeakNpcId = 700020,
          Subtitle = "So we moved back to Icelake, but no one knew of Hamel Dickinson's whereabouts. We managed to track down a few old miners, but after racking their memories, the last time they remembered seeing Mr Dickinson was forty years ago...",
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51002501] = {
          ContentFR = "Va... va-t’en... si tu n’achètes pas de Phoxène, ne reste pas ici... et n’attire pas ces foutus soldats sur moi...",
          DialogueId = 51002501,
          GUID = "7FADEDD2",
          NextDialogue = 51002502,
          SpeakNpcId = 700113,
          Subtitle = "S—Scoot if you ain't buying any Phoxene... Stop drawing the soldiers' attention to me...",
          TalkActionId = {
            [1] = "700113:Shock_Start"
          }
        },
        [51002502] = {
          ContentFR = "L’homme, pourtant bâti comme un colosse, se recroqueville dans un coin. Son regard fuyant trahit sa nervosité. À ses côtés, un sac rempli de Phoxènes qu’il semble vouloir vendre à tout prix... mais il hésite encore à demander de l’aide.",
          DialogueId = 51002502,
          GUID = "7FADEDFC",
          Subtitle = "(Despite his strong, powerful build, the man cowers in the corner. His shifty gaze and the bag of Phoxene by his side suggest he's desperate to rid himself of it but hesitant to ask for help.)",
          TalkActionId = {
            [1] = "700113:Shock_End"
          },
          TalkOptions = {
            [1] = 510025021,
            [2] = 510025022,
            [3] = 510025023,
            [4] = 510025024
          }
        },
        [51002503] = {
          ContentFR = "Ayez pitié... Faites comme si je n’existais pas... Dès que j’ai vendu ce Phoxène, je quitte Givrelac pour de bon, je le jure !",
          DialogueId = 51002503,
          GUID = "7FADEE26",
          SpeakNpcId = 700113,
          Subtitle = "Show some mercy and look the other way, please. Once I sell this load of Phoxene I'll leave Icelake at once and never ever come back."
        },
        [51002504] = {
          ContentFR = "À ces mots, l’homme agrippe son sac et s’enfuit. Tu parviens à l’arrêter de justesse et, après lui avoir expliqué qu’il s’agissait d’une plaisanterie, il t’avoue à voix basse ses véritables difficultés.",
          DialogueId = 51002504,
          GUID = "7FADEE50",
          Subtitle = "(The man grabs his bag and bolts. After a breathless chase, you manage to tell him who you really are and convince him you were joking. In a hushed voice, he reveals his dire circumstances.)"
        },
        [51002505] = {
          ContentFR = "Trouve-moi un acheteur et je te laisse 70 %... Non, 80 % ! Je t’en supplie, aide-moi !",
          DialogueId = 51002505,
          GUID = "7FADEE7A",
          SpeakNpcId = 700113,
          Subtitle = "Find me a buyer and I'll let you take 70 percents! No, 80! Please! I really need the help!",
          TalkActionId = {
            [1] = "700113:Sigh_Start"
          }
        },
        [51002506] = {
          ContentFR = "Tu acceptes sa requête, mais son attitude nerveuse et les traces rouge sombre séchées sur son sac ne laissent guère de doute : cette cargaison de Phoxène n’a pas une origine très nette.",
          DialogueId = 51002506,
          GUID = "7FADEEA4",
          Subtitle = "(You've agreed to the man's request. But the way his eyes dart about — and the dried streaks of crimson on the sack he's hauling — hint that there's more to this Phoxene than he's letting on.)",
          TalkActionId = {
            [1] = "700113:Sigh_End"
          }
        },
        [51002601] = {
          ContentFR = "Magnifique, {nickname} n’est pas là aujourd’hui...",
          DialogueId = 51002601,
          GUID = "7FADFE3A",
          NextDialogue = 51002602,
          SpeakNpcId = 700111,
          Subtitle = "Great,  isn't around today...",
          TalkActionId = {
            [1] = "700111:Think_Start"
          }
        },
        [51002602] = {
          ContentFR = "Tu me cherchais ?",
          DialogueId = 51002602,
          GUID = "7FADFE64",
          NextDialogue = 51002603,
          SpeakNpcId = 100001,
          Subtitle = "Looking for me?",
          TalkActionId = {
            [1] = "700111:Think_End"
          }
        },
        [51002603] = {
          ContentFR = "... Hein ?! Ah ! Tu tombes toujours du ciel, toi !",
          DialogueId = 51002603,
          GUID = "7FADFE8E",
          NextOptions = {
            [1] = 510026031
          },
          SpeakNpcId = 700111,
          Subtitle = "...Whoa! Speak of the devil!",
          TurnTo = {
            [1] = "700111:n(0)"
          },
          bForbidSkipOptions = true
        },
        [51002604] = {
          ContentFR = "Quoi... tu te fiches de moi ? Tu veux juste me balancer une corvée dans les pattes, hein ?",
          DialogueId = 51002604,
          GUID = "7FADFEB8",
          SpeakNpcId = 700111,
          Subtitle = "Huh, this must be a trap. You're trying to distract me with an errand, aren't you?",
          TalkActionId = {
            [1] = "700111:Disagree"
          }
        },
        [51002605] = {
          ContentFR = "Près du portail, le téléphone sonne brusquement. Kevin sursaute comme un lapin effarouché et se précipite pour décrocher.",
          DialogueId = 51002605,
          GUID = "7FADFEE2",
          NextDialogue = 51002606,
          Subtitle = "(The phone by the gate suddenly rings. Kevin leaps up like a startled hare and quickly picks up the phone.)",
          TurnTo = {
            [1] = "700111:p(90)"
          }
        },
        [51002606] = {
          ContentFR = "Ici Kevin... Quoi ? Des mouvements suspects en ville ? Compris, j’arrive !",
          DialogueId = 51002606,
          GUID = "7FADFF0C",
          NextDialogue = 51002607,
          SpeakNpcId = 700111,
          Subtitle = "Kevin speaking. What? Suspicious guy in the city? Got it. I'm on my way.",
          TalkActionId = {
            [1] = "700111:Agree"
          }
        },
        [51002607] = {
          ContentFR = "... Ça doit être le type dont tu me parlais. Allez, montre-moi le chemin.",
          DialogueId = 51002607,
          GUID = "7FADFF36",
          Scripts = "SEQ{TurnTo{TurnToDescription{\"700111:n(0)\"}},PlayAnimation{ActorId{700111},AnimationId{\"Think_Start\"},Duration{2}}}",
          SpeakNpcId = 700111,
          Subtitle = "...Probably the one you just mentioned. Could you lead the way?"
        },
        [51002701] = {
          Camera = "221.641602,5.540039,120.836426,0.000002,0.200002,-178.397919,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tiens donc... mais c’est pas notre ancien mineur modèle, Larry ? T’étais toujours entouré de tes copains. Où sont-ils passés, aujourd’hui ?",
          DialogueId = 51002701,
          GUID = "7FAE0EA2",
          NextDialogue = 51002702,
          SpeakNpcId = 700112,
          Subtitle = "Oh, isn't this Larry, our former model miner? Why are you here all by yourself? You've always got buddies hanging around with you — where are they today?",
          TalkActionId = {
            [1] = "700112:Talk01_Start",
            [2] = "100001:Confident_Start"
          },
          TurnTo = {
            [1] = "700114:n(700112)"
          }
        },
        [51002702] = {
          Camera = "11.023438,10.769531,127.256836,0.0,0.0,8.403177,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Les... Veilleurs ?!",
          DialogueId = 51002702,
          FinalCamera = "39.697266,15.063477,127.256836,0.0,0.0,8.403239,25.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAE0ECC",
          NextDialogue = 51002703,
          SpeakNpcId = 700114,
          Subtitle = "...The Escort!?",
          TalkActionId = {
            [1] = "700114:Shock_Start",
            [2] = "700112:Talk01_End",
            [3] = "100001:Confident_End"
          },
          ToFinalCameraBlendTime = 1
        },
        [51002703] = {
          Camera = "221.641602,5.540039,120.836426,0.000002,0.200002,-178.397919,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Peu importe. Toi, en revanche... tu sais que l’extraction et la vente clandestine de Phoxène sont interdites, pas vrai ? J’ai reçu l’ordre de— Attends... qu’est-ce que c’est que ces taches de sang sur ton sac ?",
          DialogueId = 51002703,
          GUID = "7FAE0EF6",
          NextDialogue = 51002704,
          SpeakNpcId = 700112,
          Subtitle = "Well, doesn't matter where they are. Actually, I came to warn you that unauthorised mining and sales of Phoxene are illegal. The brass wants me to... Oooh! What's up with the blood on this bag of yours?",
          TalkActionId = {
            [1] = "700114:Shock_End",
            [2] = "700112:Talk01_Start"
          }
        },
        [51002704] = {
          Camera = "-24.264648,5.625977,122.256836,0.0,0.0,8.403694,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je... je...",
          DialogueId = 51002704,
          GUID = "7FAE0F20",
          NextDialogue = 51002705,
          Scripts = "SEQ{LookAt{LookAtDescription{\"700114:n(100001)\"}},LookAt{LookAtDescription{\"700114:n(700114)\"}}}",
          SpeakNpcId = 700114,
          Subtitle = "I, uh... I...",
          TalkActionId = {
            [1] = "700112:Talk01_End"
          }
        },
        [51002705] = {
          Camera = "121.136719,-1.510742,123.537598,0.000002,0.399996,-168.191696,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas un geste ! {nickname}, aide-moi !",
          DialogueId = 51002705,
          GUID = "7FAE0F4A",
          Scripts = "SEQ{PlayAnimation{ActorId{700112},AnimationId{\"Angry01_Start\"},Duration{2}},LookAt{LookAtDescription{\"700112:n(100001)\"}},PlayAnimation{ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{1}}}",
          SpeakNpcId = 700112,
          Subtitle = "Freeze! , a little help!"
        },
        [51002801] = {
          Camera = "-297.869141,-392.973633,116.237793,0.000001,0.0,37.400127,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Toi... espèce de traître ! Tu m’as vendu aux soldats !",
          DialogueId = 51002801,
          GUID = "7FAE1F0A",
          NextDialogue = 51002802,
          SpeakNpcId = 700114,
          Subtitle = "You friggin' liar! Why did you bring the soldiers over?",
          TalkActionId = {
            [1] = "700114:Sigh_Start"
          }
        },
        [51002802] = {
          Camera = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Silence ! Les mains bien visibles... tiens-les bien écartées et lâche ce sac !",
          DialogueId = 51002802,
          GUID = "7FAE1F34",
          NextDialogue = 51002803,
          SpeakNpcId = 700112,
          Subtitle = "Shut up and put your hands where I can see them... Hands open wide, and drop that bag!",
          TalkActionId = {
            [1] = "700112:Angry01_Start"
          }
        },
        [51002803] = {
          Camera = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Le canon braqué contre son front, Larry hésite. Puis ses doigts se desserrent et le sac s’écrase au sol. Le Phoxène s’en échappe, luisant... et couvert de sang.",
          DialogueId = 51002803,
          GUID = "7FAE1F5E",
          NextDialogue = 51002804,
          Subtitle = "(With a gun barrel pointed straight at his head, Larry hesitates shortly before letting go of the bag. The bag drops to the ground and bloodstained Phoxene scatter all over the place.)",
          TalkActionId = {
            [1] = "700114:Sigh_End",
            [2] = "700112:Angry01_End"
          }
        },
        [51002804] = {
          Camera = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Bon sang. Tu les as tués à coups de pierres ? Tes propres compagnons ?",
          DialogueId = 51002804,
          GUID = "7FAE1F88",
          NextDialogue = 51002805,
          SpeakNpcId = 700112,
          Subtitle = "...Gosh. Did you kill your buddies by bashing them with those rocks?"
        },
        [51002805] = {
          Camera = "-297.869141,-392.973633,116.237793,0.000001,0.0,37.400127,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est eux qui ont attaqué les premiers ! Je... je me suis défendu !",
          DialogueId = 51002805,
          GUID = "7FAE1FB2",
          NextDialogue = 51002806,
          SpeakNpcId = 700114,
          Subtitle = "They attacked me first... It... It was all self-defence!",
          TalkActionId = {
            [1] = "700114:Sigh_Start"
          }
        },
        [51002806] = {
          Camera = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Peu importe que tu t’en défendes ou non, ça ne dépend pas de moi. Tu viens avec nous.",
          DialogueId = 51002806,
          GUID = "7FAE1FDC",
          NextDialogue = 51002807,
          SpeakNpcId = 700112,
          Subtitle = "Well, none of us can be the judge of that! Alright, you need to come with us!",
          TalkActionId = {
            [1] = "700114:Sigh_End",
            [2] = "700112:Talk01_Start"
          }
        },
        [51002807] = {
          Camera = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce n’est pas ma faute... pas ma faute ! C’est ce sac de Phoxène, tout est de sa faute ! Si on ne l’avait pas trouvé, on serait encore ensemble... tous vivants... tous...",
          DialogueId = 51002807,
          GUID = "7FAE2006",
          NextDialogue = 51002808,
          SpeakNpcId = 700114,
          Subtitle = "It wasn't me! Wasn't my fault...! It's the bag of Phoxene! If we never opened this damned bag, all of us would still be around! We'd all be alive!",
          TalkActionId = {
            [1] = "700114:Disagree",
            [2] = "700112:Talk01_End"
          }
        },
        [51002808] = {
          Camera = "121.290039,-83.856445,144.21875,0.000003,-0.999905,-165.995453,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "<I>Soupir...</>",
          DialogueId = 51002808,
          GUID = "7FAE2030",
          NextDialogue = 51002809,
          SpeakNpcId = 700112,
          Subtitle = "*sigh*",
          TalkActionId = {
            [1] = "700112:Disagree"
          }
        },
        [51002809] = {
          Camera = "-3.327148,-490.567383,115.4375,0.000011,0.0,94.803833,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Avant que j’oublie, merci, {nickname}, d’avoir aidé les Veilleurs. Voici ta récompense.",
          DialogueId = 51002809,
          GUID = "7FAE205A",
          Scripts = "SEQ{PARA{TurnTo{TurnToDescription{\"700112:n(100001)\"}},TurnTo{TurnToDescription{\"100001:n(700112)\"}}},PlayAnimation{ActorId{700112},AnimationId{\"Agree\"},Duration{1}},PlayAnimation{ActorId{700112},AnimationId{\"Talk01_Start\"},Duration{1}}}",
          SpeakNpcId = 700112,
          Subtitle = "Oh, before I forget — Thank you, , for assisting the Escort. Here's your reward."
        },
        [51002810] = {
          ContentFR = "Kevin s’éloigne, emmenant Larry à travers la neige.",
          DialogueId = 51002810,
          Duration = 2,
          GUID = "7FAE2084",
          NextDialogue = 51002811,
          Subtitle = "Kevin drags Larry away, disappearing into the distance."
        },
        [51002811] = {
          ContentFR = "Les \"pierres ensanglantées\" tombent dans le silence, leur histoire macabre bientôt recouverte par un autre flocon de Givrelac.",
          DialogueId = 51002811,
          Duration = 4,
          GUID = "7FAE20AE",
          Subtitle = " The bloody story of the \"bloodstained stones\" became yet another tale buried under the Icelake snow."
        },
        [51002901] = {
          ContentFR = "Un homme à la voix puissante tient l’assemblée captive. Ses récitations théâtrales arrachent des rires aux habitués.",
          DialogueId = 51002901,
          GUID = "7FAE2F72",
          NextDialogue = 51002902,
          Subtitle = "(A loud man is holding court, his dramatic recitations drawing bursts of laughter from the patrons.)"
        },
        [51002902] = {
          ContentFR = "Des spectres surgis des montagnes profondes ! Des fantômes échappés du lac de glace lui-même !",
          DialogueId = 51002902,
          GUID = "7FAE2F9C",
          NextDialogue = 51002903,
          SpeakNpcId = 700015,
          Subtitle = "Phantoms from the deep mountains, ghosts from the Icelake itself!"
        },
        [51002903] = {
          ContentFR = "Ils approchent ! Ils se rapprochent !",
          DialogueId = 51002903,
          GUID = "7FAE2FC6",
          NextDialogue = 51002904,
          SpeakNpcId = 700015,
          Subtitle = "They're pressing in! They're getting closer!"
        },
        [51002904] = {
          ContentFR = "Ah, te voilà.",
          DialogueId = 51002904,
          GUID = "7FAE2FF0",
          NextOptions = {
            [1] = 510029041
          },
          SpeakNpcId = 200003,
          Subtitle = "Hey, you're here."
        },
        [51002905] = {
          ContentFR = "Pour le moment, je n’ai pas de contrat officiel pour toi, mais...",
          DialogueId = 51002905,
          GUID = "7FAE301A",
          NextDialogue = 51002906,
          SpeakNpcId = 200003,
          Subtitle = "I don't have any proper jobs for you at the moment, but..."
        },
        [51002906] = {
          ContentFR = "... Vous ne pouvez pas imaginer !",
          DialogueId = 51002906,
          GUID = "7FAE3044",
          NextDialogue = 51002907,
          SpeakNpcId = 700015,
          Subtitle = "...You can hardly imagine!"
        },
        [51002907] = {
          ContentFR = "Un spectre ! Une ombre muette qui traverse les portes comme si elles n’existaient pas !",
          DialogueId = 51002907,
          GUID = "7FAE306E",
          NextDialogue = 51002908,
          SpeakNpcId = 700015,
          Subtitle = "A phantom!!! A silent stalker that ignores the doors!!!"
        },
        [51002908] = {
          ContentFR = "Comme tu peux l’entendre, il y en a toujours un qui se met dans de beaux draps...",
          DialogueId = 51002908,
          GUID = "7FAE3098",
          NextOptions = {
            [1] = 510029081
          },
          SpeakNpcId = 200003,
          Subtitle = "As you can see, we've got a bit of a situation here."
        },
        [51002909] = {
          ContentFR = "Monsieur Buck. Incapable de tenir l’alcool... alors il se gave de lait et de jus de fruits. Son métier ? Dramaturge raté. Mais pour bavarder, il mérite la palme. Regarde-le, il marmonne sans s’arrêter.",
          DialogueId = 51002909,
          GUID = "7FAE30C2",
          NextDialogue = 51002910,
          SpeakNpcId = 200003,
          Subtitle = "Mr Buck. Can't handle even a drop of alcohol — so it's always fruit juice or milk for him. Profession... third-rate playwright, first-rate producer of mumble-jumble. He's been spinning his yarns for a while now."
        },
        [51002910] = {
          ContentFR = "Tu le vois bien, il est incapable d’être clair. Peut-être que toi, tu arriveras à décoder ses balivernes.",
          DialogueId = 51002910,
          GUID = "7FAE30EC",
          NextOptions = {
            [1] = 510029101
          },
          RestartTag = 51002910,
          SpeakNpcId = 200003,
          Subtitle = "As you can see, the man struggles to convey his thoughts clearly. Could you help by translating his flamboyant narratives?",
          bForbidSkipOptions = true
        },
        [51002911] = {
          ContentFR = "Ne sois pas déçu. À Givrelac, pas plus de cinq personnes comprennent un mot de ses délires.",
          DialogueId = 51002911,
          GUID = "7FAE3116",
          SpeakNpcId = 200003,
          Subtitle = "It's okay. I doubt there are more than five people in Icelake who can understand his words."
        },
        [51002912] = {
          ContentFR = "Avec ton esprit vif, tu dois bien être la seule personne ici capable de comprendre ce qu’il raconte.",
          DialogueId = 51002912,
          GUID = "7FAE3140",
          SpeakNpcId = 200003,
          Subtitle = "Only a sharp mind like yours is suited for this task."
        },
        [51003001] = {
          ContentFR = "Tu tends l’oreille pour écouter les envolées lyriques du dramaturge.",
          DialogueId = 51003001,
          GUID = "7FAE3FDA",
          NextDialogue = 51003002,
          Subtitle = "(You tune into the playwright's bombastic musings.)"
        },
        [51003002] = {
          ContentFR = "Les nuits des poètes sont interminables... et celles des dramaturges ne font pas exception ! Nos plumes tracent le rythme des hommes, et nos cœurs battent à l’unisson avec la lune et la marée !",
          DialogueId = 51003002,
          GUID = "7FAE4004",
          NextDialogue = 51003003,
          SpeakNpcId = 700015,
          Subtitle = "Nights can be particularly long for poets... and playwrights! Our pens track the vibe amongst people, and our hearts naturally rise and fall with the moon and tide!",
          TalkActionId = {
            [1] = "700015:Talk01_Start"
          }
        },
        [51003003] = {
          ContentFR = "Quand tombent les ténèbres, je rejette l’éclat aveuglant du soleil, le vacarme du monde et les pensées agitées. Alors seulement vient l’heure où je puis converser intimement avec l’univers !",
          DialogueId = 51003003,
          GUID = "7FAE402E",
          NextOptions = {
            [1] = 510030031,
            [2] = 510030032
          },
          SpeakNpcId = 700015,
          Subtitle = "When the night falls, we can cast away the blinding sun, the worldly voices, and the unsettled thoughts and reflections. It is the hour when I can truly commune with the cosmos itself!",
          TalkActionId = {
            [1] = "700015:Talk01_End"
          },
          bForbidSkipOptions = true
        },
        [51003004] = {
          ContentFR = "Ah ! Peut-être ai-je offensé, sans le savoir, la déesse de l’inspiration... soit le dieu du sommeil a décidé de se jouer de moi ! Autrement, comment aurais-je pu laisser filer le temps sans même m’en rendre compte ?",
          DialogueId = 51003004,
          GUID = "7FAE4058",
          NextDialogue = 51003005,
          SpeakNpcId = 700015,
          Subtitle = "Alas! Either my unwitting arrogance has peeved the goddess of inspiration, or the deity of sleep has played his cruel tricks on me! Otherwise, I would have noticed the sands of time trickling by!",
          TalkActionId = {
            [1] = "700015:Sigh_Start"
          }
        },
        [51003005] = {
          ContentFR = "J’aurais dû accueillir l’aube avec des pages couvertes de mots et de vers. Mais au lieu de cela, je me suis réveillé... reposé, certes, mais l’âme vide, et devant moi, des feuillets vierges !",
          DialogueId = 51003005,
          GUID = "7FAE4082",
          NextOptions = {
            [1] = 510030051,
            [2] = 510030052
          },
          SpeakNpcId = 700015,
          Subtitle = "I ought to have greeted dawn with pages filled with prose and stanzas. Instead, I awoke refreshed with an empty soul, and my sheets of paper blank!",
          TalkActionId = {
            [1] = "700015:Sigh_End"
          },
          bForbidSkipOptions = true
        },
        [51003006] = {
          ContentFR = "Dans mes songes enivrants, j’ai entendu des pas discrets, légers comme la danse des fées. Et un parfum de fruits mûrs nappés de miel m’a caressé les sens !",
          DialogueId = 51003006,
          GUID = "7FAE40AC",
          NextDialogue = 51003007,
          SpeakNpcId = 700015,
          Subtitle = "In my enthralling dreams, I heard gentle footsteps, light as the dance of fairies. The scent of ripe fruits slathered in sweet honey wafted through the air!",
          TalkActionId = {
            [1] = "700015:Explain01_Start"
          }
        },
        [51003007] = {
          ContentFR = "Peut-être étais-je perdu dans mes rêves... Mais ces sons et ces senteurs m’ont ramené à la réalité. Ils étaient insaisissables, flottant tout autour de moi... et pourtant, j’en suis certain : ils existaient vraiment !",
          DialogueId = 51003007,
          GUID = "7FAE40D6",
          NextOptions = {
            [1] = 510030071,
            [2] = 510030072
          },
          SpeakNpcId = 700015,
          Subtitle = "Perhaps I was lost in my dreams, but those sounds and smells brought me back to reality! They are ephemeral, lingering by my side. Yet I am certain of their existence...",
          TalkActionId = {
            [1] = "700015:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51003008] = {
          ContentFR = "Ce ne sont pas des hallucinations ! Mais je n’arrive pas à en saisir les traces, à percer ce mystère... Fantômes ? Spectres ? Illusions ?",
          DialogueId = 51003008,
          GUID = "7FAE4100",
          NextDialogue = 51003009,
          SpeakNpcId = 700015,
          Subtitle = "They are not hallucinations, yet I fail to grasp their trails. I cannot fathom these strange incidents. Are they phantoms? Ghosts? Or mere illusions?",
          TalkActionId = {
            [1] = "700015:Disagree"
          }
        },
        [51003009] = {
          ContentFR = "Ma pauvre bicoque n’a pas changé d’un poil... Pourtant, on m’a volé ce que j’ai de plus précieux : mon inspiration, ma raison de vivre ! À ce rythme, mes rêves vont s’écrouler...",
          DialogueId = 51003009,
          GUID = "7FAE412A",
          NextOptions = {
            [1] = 510030091,
            [2] = 510030092
          },
          SpeakNpcId = 700015,
          Subtitle = "My dilapidated abode remained untouched. This spirit stole nothing but my inspiration, which I cherish as dearly as life itself! It threatens to shatter my dreams...",
          bForbidSkipOptions = true
        },
        [51003010] = {
          ContentFR = "Les nuits d’un dramaturge ne sauraient être sacrifiées au sommeil ! Qui parmi vous répondra à mon appel ? Qui pourchassera ce voleur d’inspiration, afin que mon chef-d’œuvre voie le jour ?",
          DialogueId = 51003010,
          GUID = "7FAE4154",
          NextDialogue = 51003011,
          SpeakNpcId = 700015,
          Subtitle = "A playwright's night cannot be squandered on sleep! I implore any of you to heed my plea! Banish this vile burglar of inspiration so that my magnum opus may yet be completed!",
          TalkActionId = {
            [1] = "700015:Talk03_Start"
          }
        },
        [51003011] = {
          ContentFR = "Je vous offrirai la gloire... Peut-être même le rôle du héros dans ma prochaine pièce ! Montrez-moi votre talent, et je chanterai vos exploits, ô Chasseur de Phoxène !",
          DialogueId = 51003011,
          GUID = "7FAE417E",
          NextOptions = {
            [1] = 510030111,
            [2] = 510030112
          },
          SpeakNpcId = 700015,
          Subtitle = "I shall bestow upon you the honour and perhaps grant you the role of the hero in my next epic! Demonstrate your unmatched skills to me so that I may dedicate myself to chronicling the biography of the great Phoxhunter, my saviour!",
          TalkActionId = {
            [1] = "700015:Talk03_End"
          },
          bForbidSkipOptions = true
        },
        [51003012] = {
          ContentFR = "Ça n’aura sans doute aucun profit, mais c’est divertissant. Tu t’en charges ou pas ?",
          DialogueId = 51003012,
          GUID = "7FAE41A8",
          NextOptions = {
            [1] = 510030121,
            [2] = 510030122
          },
          SpeakNpcId = 200003,
          Subtitle = "So this appears to be a pro bono commission. It sounds interesting, though. Are you willing to take it?",
          bForbidSkipOptions = true
        },
        [51003013] = {
          ContentFR = "Oh ! {性别:Un champion|Une championne} répond à mon appel ! Voilà peut-être le prélude d’une nouvelle épopée !",
          DialogueId = 51003013,
          GUID = "7FAE41D2",
          NextDialogue = 51003014,
          SpeakNpcId = 700015,
          Subtitle = "Oh! A champion has answered my call for help! Perhaps this marks the beginning of a new epic odyssey!",
          TalkActionId = {
            [1] = "700015:Talk01_Start"
          },
          TurnTo = {
            [1] = "700015:n(0)"
          }
        },
        [51003014] = {
          ContentFR = "Je suis avide de savoir ce que vous allez découvrir... Revenez me conter vos aventures !",
          DialogueId = 51003014,
          GUID = "7FAE41FC",
          SpeakNpcId = 700015,
          Subtitle = "I am exceedingly curious about the adventures you will undertake. Please, do share your story with me once you return!",
          TalkActionId = {
            [1] = "700015:Talk01_End"
          }
        },
        [51003101] = {
          ContentFR = "Camila a dit que Monsieur Buck ne boit jamais... Alors ? Quelqu’un a mis de l’alcool dans son lait ?",
          DialogueId = 51003101,
          GUID = "7FAE5042",
          NextDialogue = 51003102,
          SpeakNpcId = 100001,
          Subtitle = "Camila said Mr Buck can't handle alcohol — he never drinks. So... someone must've spiked the milk."
        },
        [51003102] = {
          ContentFR = "Mmmh... Il y a une empreinte collante sur la bouteille. Elle est minuscule... On dirait une main d’enfant.",
          DialogueId = 51003102,
          GUID = "7FAE506C",
          SpeakNpcId = 100001,
          Subtitle = "Wait — there's a sticky fingerprint on the jug. Small... child-sized, even."
        },
        [51003103] = {
          ContentFR = "Ces traces vont de la rue jusqu’à la fenêtre. Et à l’intérieur, la neige a fondu... Aucun effort pour dissimuler les preuves. C’était juste un enfant.",
          DialogueId = 51003103,
          GUID = "7FAE5096",
          SpeakNpcId = 100001,
          Subtitle = "The prints lead from the street right up to the window. And there's melted snow inside... No attempt to cover their tracks — looks like it really was just a kid."
        },
        [51003104] = {
          ContentFR = "On dirait bien qu’un enfant a mis de l’alcool dans le lait pour saouler Monsieur Buck. Cherchons d’autres indices.",
          DialogueId = 51003104,
          Duration = 4,
          GUID = "7FAE50C0",
          SpeakNpcId = 100001,
          Subtitle = "So a kid poured booze into Buck's milk and knocked him out cold. Better have another look around, see what else I can dig up."
        },
        [51003105] = {
          ContentFR = "Excusez-moi... Est-ce que des enfants viennent parfois voir Monsieur Buck ?",
          DialogueId = 51003105,
          GUID = "7FAE50EA",
          NextDialogue = 51003106,
          SpeakNpcId = 100001,
          Subtitle = "Excuse me — do any kids ever visit Mr Buck?"
        },
        [51003106] = {
          ContentFR = "Des enfants ? Chez Buck ? Allons donc ! Ce type passe son temps <H>entre sa maison, la taverne et le théâtre</>. Et quand il ouvre la bouche, c’est un charabia de théâtre de seconde zone !",
          DialogueId = 51003106,
          GUID = "7FAE5114",
          NextDialogue = 51003107,
          SpeakNpcId = 700213,
          Subtitle = "Kids? Visiting Buck? You're kidding, right? What kid would wanna hang around him? The guy barely leaves the house — unless it's the tavern or the theatre. And when he talks, it's like listening to a bad play in reverse."
        },
        [51003107] = {
          ContentFR = "Pas que les enfants, hein. Nous non plus, on n’a pas envie de lui parler. On n’y comprend rien et il nous tape sur les nerfs. Il a fait quelque chose de mal ? Je le savais, je l’ai toujours trouvé louche !",
          DialogueId = 51003107,
          GUID = "7FAE513E",
          NextDialogue = 51003108,
          SpeakNpcId = 700213,
          Subtitle = "Not just kids — we hardly speak to him either. He's a nuisance. No one can understand a word he says. He hasn't done anything illegal, has he? 'Cause I always said there was something off about that man."
        },
        [51003108] = {
          ContentFR = "La vieille femme enchaîne les reproches : trop vieux pour ne pas avoir de vrai métier, cloîtré chez lui, pas de femme, pas d’amis... Tu ne parviens à t’éclipser qu’une fois qu’elle est complètement à bout de souffle.",
          DialogueId = 51003108,
          GUID = "7FAE5168",
          NextDialogue = 51003109,
          Subtitle = "(The old woman rattles off a list of Buck's \"crimes\" — too old to be jobless, never leaves the house, no wife, no friends... It isn't until she's talked herself hoarse that you finally manage to slip away.)"
        },
        [51003109] = {
          ContentFR = "Il vit reclus, personne ne sait rien de lui. Si un enfant a découvert qu’il s’endormait facilement avec de l’alcool... c’est qu’il l’a appris ailleurs.",
          DialogueId = 51003109,
          GUID = "7FAE5192",
          NextDialogue = 51003110,
          SpeakNpcId = 100001,
          Subtitle = "(Mr Buck rarely leaves home and keeps to himself — most people hardly know a thing about him. So if a kid somehow knew about his weakness for alcohol... they must've picked it up somewhere.)"
        },
        [51003110] = {
          ContentFR = "Pas d’enfants aux Asphodèles, ni autour de sa maison... Il reste une possibilité, le théâtre.",
          DialogueId = 51003110,
          GUID = "7FAE51BC",
          SpeakNpcId = 100001,
          Subtitle = "(The Asphodel's no place for kids, and no one's seen any near Buck's house. That leaves one place: the theatre. I should check it out.)"
        },
        [51003111] = {
          ContentFR = "Un jeune Charon frissonne près du guichet, vendant affiches, billets, bières et pop-corn.",
          DialogueId = 51003111,
          GUID = "7FAE51E6",
          NextDialogue = 51003112,
          Subtitle = "(A young Charon boy huddles near the ticket booth, shivering in the cold. He calls out to passersby, trying to sell tickets, posters, beer, and popcorn.)"
        },
        [51003112] = {
          ContentFR = "<I>Un enfant qui vend du pop-corn... Et si c’était lui qui avait saoulé Buck ?</>",
          DialogueId = 51003112,
          GUID = "7FAE5210",
          SpeakNpcId = 100001,
          Subtitle = "(A kid selling popcorn outside the theatre... Could he have been the one who spiked Buck's milk?)"
        },
        [51003113] = {
          ContentFR = "Monsieur Buck passe tout son temps au théâtre. Il a forcément croisé cet enfant plus d’une fois. Il a probablement refusé qu’on lui vendre de la bière à chaque fois...",
          DialogueId = 51003113,
          Duration = 3,
          GUID = "7FAE523A",
          NextDialogue = 51003114,
          SpeakNpcId = 100001,
          Subtitle = "Mr Buck spends plenty of time at the theatre — he's bound to have crossed paths with that kid more than once. Probably turned down his beer sales every time..."
        },
        [51003114] = {
          ContentFR = "Et ce pop-corn sur la manche de l’enfant ? Ils correspondent exactement à ce que j’ai trouvé sous la fenêtre de Monsieur Buck. Tout l’accuse. Il est temps de discuter.",
          DialogueId = 51003114,
          Duration = 4,
          GUID = "7FAE5264",
          SpeakNpcId = 100001,
          Subtitle = "And those popcorn kernels on the kid's sleeve? They match exactly with what I found under Buck's window. Everything's pointing to him. Time to have a chat."
        },
        [51003115] = {
          ContentFR = "Hic ! Encore une ! Pff, vingt bouteilles, c’est rien du tout ! Allez, servez !",
          DialogueId = 51003115,
          GUID = "7FAE528E",
          NextDialogue = 51003116,
          SpeakNpcId = 700214,
          Subtitle = "Gimme another bottle! I'm not drunk... Twenty beers? Barely a warm-up! C'mon, keep 'em coming!"
        },
        [51003116] = {
          ContentFR = "<I>Un ivrogne... Et si c’était lui qui avait saoulé Buck ?</>",
          DialogueId = 51003116,
          GUID = "7FAE52B8",
          SpeakNpcId = 100001,
          Subtitle = "(This guy reeks of booze... Could he have been the one who spiked Buck's milk?)"
        },
        [51003117] = {
          ContentFR = "Papa, ça a quel goût, le pop-corn ? Je peux goûter ?",
          DialogueId = 51003117,
          GUID = "7FAE52E2",
          LookAt = {
            [1] = "700215:n(700219)",
            [2] = "700219:n(700215)"
          },
          NextDialogue = 51003118,
          SpeakNpcId = 700215,
          Subtitle = "What does popcorn taste like, Papa? Can I try some, please?"
        },
        [51003118] = {
          ContentFR = "Non, ma fille. Une demoiselle ne mange pas de cochonneries. Après l’opéra, je t’emmènerai dîner au restaurant Paix d’Argent.",
          DialogueId = 51003118,
          GUID = "7FAE530C",
          NextDialogue = 51003119,
          SpeakNpcId = 700219,
          Subtitle = "A proper young lady doesn't eat junk like that. After the opera, Papa will take you to Silverpeace for a proper meal.",
          TalkActionId = {
            [1] = "700219:Talk03_Start"
          }
        },
        [51003119] = {
          ContentFR = "D’accord...",
          DialogueId = 51003119,
          GUID = "7FAE5336",
          NextDialogue = 51003120,
          SpeakNpcId = 700215,
          Subtitle = "Aww... okay...",
          TalkActionId = {
            [1] = "700219:Talk03_End"
          }
        },
        [51003120] = {
          ContentFR = "<I>Une gamine qui rêvait de pop-corn. Et si c’était elle ?</>",
          DialogueId = 51003120,
          GUID = "7FAE5360",
          SpeakNpcId = 100001,
          Subtitle = "(A kid outside the theatre, eyeing popcorn longingly... Could she have been the one who spiked Buck's milk?)"
        },
        [51003301] = {
          ContentFR = "<I>Atchoum !</> On dirait qu’il fait encore plus froid...",
          DialogueId = 51003301,
          GUID = "7FAE7112",
          NextDialogue = 51003302,
          SpeakNpcId = 700080,
          Subtitle = "Achoo! It's getting colder...",
          TalkActionId = {
            [1] = "700080:Sigh_Start"
          }
        },
        [51003302] = {
          ContentFR = "Même pour un Charon, il y a des limites au froid. Ce soir, il fera au moins vingt degrés de moins... Et sûrement des enfants vont encore mourir de froid... <I>Soupir...</>",
          DialogueId = 51003302,
          GUID = "7FAE713C",
          NextDialogue = 51003303,
          SpeakNpcId = 700080,
          Subtitle = "Even a Charon has limits on cold tolerance... The temperature will be down by twenty degrees this evening. We might lose a few kids to the cold. *sigh*...",
          TalkActionId = {
            [1] = "700080:Sigh_End"
          }
        },
        [51003303] = {
          ContentFR = "Bonjour.",
          DialogueId = 51003303,
          GUID = "7FAE7166",
          NextDialogue = 51003304,
          SpeakNpcId = 100001,
          Subtitle = "Hello."
        },
        [51003304] = {
          ContentFR = "Bienvenue, honorable {性别:spectateur|spectatrice} ! Après trois heures d’opéra, vous devez avoir faim ! Voulez-vous quelque chose à grignoter et à boire ?",
          DialogueId = 51003304,
          GUID = "7FAE7190",
          NextDialogue = 51003305,
          SpeakNpcId = 700080,
          Subtitle = "Greetings, my dear patron! Did you enjoy the play? You must be hungry after sitting through the show for three hours! Would you like some snacks and drinks?",
          TalkActionId = {
            [1] = "700080:Explain02_Start"
          }
        },
        [51003305] = {
          ContentFR = "Ou peut-être avez-vous été {性别:ému|émue} par la performance exceptionnelle et aimeriez-vous jeter un coup d’œil à une affiche signée par les comédiens ?",
          DialogueId = 51003305,
          GUID = "7FAE71BA",
          NextOptions = {
            [1] = 510033051,
            [2] = 510033052
          },
          SpeakNpcId = 700080,
          Subtitle = "Or perhaps you were captivated by the thrilling performance — how about a poster with the thespians' signatures?",
          TalkActionId = {
            [1] = "700080:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51003306] = {
          ContentFR = "Montre-moi ce que tu vends.",
          DialogueId = 51003306,
          GUID = "7FAE71E4",
          NextDialogue = 51003307,
          SpeakNpcId = 100001,
          Subtitle = "Okay, let's see what you've got."
        },
        [51003307] = {
          ContentFR = "Une affiche dédicacée par Vitti, des albums souvenirs des <I>Contes de Givrelac</>, de l’eau glacée des glaciers, du pop-corn édition spéciale théâtre... et de la bière rafraîchissante !",
          DialogueId = 51003307,
          GUID = "7FAE720E",
          NextDialogue = 51003308,
          SpeakNpcId = 700080,
          Subtitle = "A special edition poster signed by Vitti, Tales of Icelake souvenir albums, glacial meltwater, theatre-themed popcorn... and refreshing beer!",
          TalkActionId = {
            [1] = "700080:Explain01_Start"
          }
        },
        [51003308] = {
          ContentFR = "Pas d’inquiétude ! Cela ne contient presque pas d’alcool et ne vous rendra pas ivre !",
          DialogueId = 51003308,
          GUID = "7FAE7238",
          NextDialogue = 51003309,
          SpeakNpcId = 700080,
          Subtitle = "Don't you worry! This barely contains any alcohol and won't get you drunk!",
          TalkActionId = {
            [1] = "700080:Explain01_End"
          }
        },
        [51003309] = {
          ContentFR = "Ça, j’en doute... Tu connais Monsieur Buck ?",
          DialogueId = 51003309,
          GUID = "7FAE7262",
          NextDialogue = 51003310,
          SpeakNpcId = 100001,
          Subtitle = "That's hard to say... Do you happen to know Mr Buck the playwright?"
        },
        [51003310] = {
          ContentFR = "Bien sûr ! C’est un habitué. Un noble, mais respectueux des enfants Charons comme moi. Un homme bien, croyez-moi.",
          DialogueId = 51003310,
          GUID = "7FAE728C",
          NextDialogue = 51003311,
          SpeakNpcId = 700080,
          Subtitle = "Of course I do! Mr Buck frequents the theatre and is one of my most cherished patrons! Despite being a noble, he actually respects Charon kids like me. Mr Buck is one fine gentleman!",
          TalkActionId = {
            [1] = "700080:Agree"
          }
        },
        [51003311] = {
          ContentFR = "Je sais que certains se moquent de lui. Mais comparé à ces gens-là, Monsieur Buck mérite vraiment le respect.",
          DialogueId = 51003311,
          GUID = "7FAE72B6",
          NextDialogue = 51003312,
          SpeakNpcId = 700080,
          Subtitle = "I know people make fun of Mr Buck, but unlike most people, he genuinely deserves respect."
        },
        [51003312] = {
          ContentFR = "C’est peut-être vrai, mais je doute que cela te donne le droit de t’introduire chez lui par la fenêtre et verser de la bière dans son lait.",
          DialogueId = 51003312,
          GUID = "7FAE72E0",
          NextDialogue = 51003313,
          SpeakNpcId = 100001,
          Subtitle = "That may be true, but I doubt it gives you the right to sneak into his house through the window and pour beer into his milk."
        },
        [51003313] = {
          ContentFR = "Qu... Comment tu sais ça... ?",
          DialogueId = 51003313,
          GUID = "7FAE730A",
          NextDialogue = 51003321,
          SpeakNpcId = 700080,
          Subtitle = "H—How did you know?",
          TalkActionId = {
            [1] = "700080:Shock_Start"
          }
        },
        [51003314] = {
          ContentFR = "Monsieur Buck a l’habitude d’écrire ses œuvres la nuit. Tes actions ont fait qu’il n’a rien écrit depuis un mois, alors il m’a engagé pour trouver le \"voleur d’inspiration\".",
          DialogueId = 51003314,
          GUID = "7FAE7334",
          NextOptions = {
            [1] = 510033141
          },
          SpeakNpcId = 100001,
          Subtitle = "Mr Buck has a habit of writing his works at night. Your actions have delayed his progress for a month, so he hired me to find the mysterious \"Inspiration Stealer\".",
          TalkActionId = {
            [1] = "700080:Shock_End"
          },
          bForbidSkipOptions = true
        },
        [51003315] = {
          ContentFR = "Tu hésites, tes mots se brouillent. Il te faut reformuler ta pensée.",
          DialogueId = 51003315,
          GUID = "7FAE735E",
          Subtitle = "(You formulate a theory but pause before articulating it, needing to organise your thoughts more clearly.)"
        },
        [51003316] = {
          ContentFR = "Tes ventes ne suffisent pas à couvrir tes besoins pendant l’hiver. Monsieur Buck, même pauvre, reste un noble, sa maison est chauffée. Alors tu t’y es introduit pour survivre au froid.",
          DialogueId = 51003316,
          GUID = "7FAE7388",
          NextDialogue = 51003317,
          SpeakNpcId = 100001,
          Subtitle = "Your business income isn't enough to cover your needs through the winter. Mr Buck might not be wealthy, but he is a noble and his house is warm enough. So, you sneaked into Mr Buck's home for the heating."
        },
        [51003317] = {
          ContentFR = "Quant à savoir pourquoi tu as choisi Monsieur Buck, c’est parce que tu savais qu’une goutte d’alcool suffisait à l’endormir. Tu pourrais alors dormir chez lui sans avoir peur de mourir de froid. Ai-je raison ?",
          DialogueId = 51003317,
          GUID = "7FAE73B2",
          NextDialogue = 51003318,
          SpeakNpcId = 100001,
          Subtitle = "As for why you chose Mr Buck — even the smallest amount of alcohol makes him doze off. You could then sleep in his house without the fear of freezing to death. Am I right?"
        },
        [51003318] = {
          ContentFR = "... Vous êtes {性别:un vrai|une vraie} détective. Tout est vrai.",
          DialogueId = 51003318,
          GUID = "7FAE73DC",
          NextDialogue = 51003319,
          SpeakNpcId = 700080,
          Subtitle = "Ugh... You are indeed a great detective. You've got every detail right.",
          TalkActionId = {
            [1] = "700080:Explain02_Start"
          }
        },
        [51003319] = {
          ContentFR = "Vous pouvez m’arrêter. Je suis vraiment désolé pour ce que j’ai fait. Mais si je ne l’avais pas fait, je serais mort dehors.",
          DialogueId = 51003319,
          GUID = "7FAE7406",
          NextDialogue = 51003320,
          SpeakNpcId = 700080,
          Subtitle = "You might as well arrest me. I'm truly sorry for what I did. Though if I hadn't done it, I wouldn't be here for you to arrest...",
          TalkActionId = {
            [1] = "700080:Explain02_End"
          }
        },
        [51003320] = {
          ContentFR = "Ce n’est pas à moi d’en décider. Je vais te conduire à mon client.",
          DialogueId = 51003320,
          GUID = "7FAE7430",
          SpeakNpcId = 100001,
          Subtitle = "I don't get to decide what to do with you. I'm taking you to my client."
        },
        [51003321] = {
          ContentFR = "<I>Comme je le pensais.</>",
          DialogueId = 51003321,
          GUID = "7FAE730B",
          NextDialogue = 51003314,
          SpeakNpcId = 100001,
          Subtitle = "(Just as I thought.)"
        },
        [51003401] = {
          Camera = "98.558472,-67.410156,133.285156,0.0,-1.600033,173.800858,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai trouvé le coupable.",
          DialogueId = 51003401,
          GUID = "7FAE817A",
          LookAt = {
            [1] = "700102:n(100001)",
            [2] = "100001:n(700102)"
          },
          SpeakNpcId = 100001,
          Subtitle = "I found the perpetrator.",
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51003402] = {
          ContentFR = "Tu transmets tes découvertes à Monsieur Buck.",
          DialogueId = 51003402,
          Duration = 3,
          GUID = "7FAE81A4",
          Subtitle = "(You relay your findings to Mr Buck.)"
        },
        [51003403] = {
          Camera = "-262.830322,120.149414,121.775391,0.000007,-0.200008,-45.795547,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh ! Mon {性别:héros|héroïne}, mille mercis ! Ce soir, la déesse de l’inspiration m’accordera à nouveau ses faveurs !",
          DialogueId = 51003403,
          GUID = "7FAE81CE",
          LookAt = {
            [1] = "700102:n(100001)"
          },
          NextDialogue = 51003404,
          SpeakNpcId = 700015,
          Subtitle = "Oh! My brave saviour! Allow me to express my gratitude a millionfold! From this evening forth, I shall once again be graced by the goddess of inspiration!",
          TalkActionId = {
            [1] = "700102:Agree"
          },
          TurnTo = {
            [1] = "700103:n(700102)"
          }
        },
        [51003404] = {
          Camera = "-73.412354,63.213867,126.775391,0.000008,0.200002,-62.796665,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quant à toi... petit voleur de mes songes, tu m’as réservé une surprise des plus inattendues !",
          DialogueId = 51003404,
          GUID = "7FAE81F8",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003405,
          SpeakNpcId = 700015,
          Subtitle = "As for you... the little thief in my dreams, you have given me a most unexpected surprise!",
          TurnTo = {
            [1] = "700102:n(700103)"
          }
        },
        [51003405] = {
          Camera = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je suis vraiment désolé, Monsieur Buck... mais croyez-moi, je n’ai jamais voulu vous faire de mal...",
          DialogueId = 51003405,
          GUID = "7FAE8222",
          LookAt = {
            [1] = "700103:n(700102)"
          },
          NextDialogue = 51003406,
          SpeakNpcId = 700080,
          Subtitle = "I'm very sorry, Mr Buck... But please believe me, I never intended to hurt you...",
          TalkActionId = {
            [1] = "700103:Explain02_Start"
          }
        },
        [51003406] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah, petit filou, je sais comment l’on se moque de moi dans l’ombre, on m’insulte, on me traite de dramaturge sans valeur dont les œuvres ne voient jamais la lumière.",
          DialogueId = 51003406,
          GUID = "7FAE824C",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003407,
          SpeakNpcId = 700015,
          Subtitle = "Oh, my little burglar. I'm well aware of how people scoff and snicker about me behind my back. They label me a third-rate playwright whose works never see the light of success.",
          TalkActionId = {
            [1] = "700103:Explain02_End"
          }
        },
        [51003407] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Même en parant mes phrases des plus belles parures, je n’ai pas su gagner leur estime, ils refusent d’écouter, refusent de comprendre... Pourtant, qui donc parle encore vrai de nos jours ?",
          DialogueId = 51003407,
          GUID = "7FAE8276",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003408,
          SpeakNpcId = 700015,
          Subtitle = "Adorning my prose with the most exquisite words hasn't made them appreciate my efforts. They close their ears and their hearts... From what I see, someone who truly speaks from the heart is indeed a rare gem.",
          TalkActionId = {
            [1] = "700102:Talk03_Start"
          }
        },
        [51003408] = {
          Camera = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Monsieur, je ne saisis pas ce que vous voulez dire.",
          DialogueId = 51003408,
          GUID = "7FAE82A0",
          LookAt = {
            [1] = "700103:n(700102)"
          },
          NextDialogue = 51003409,
          SpeakNpcId = 700080,
          Subtitle = "Sir... I don't really follow.",
          TalkActionId = {
            [1] = "700102:Talk03_End",
            [2] = "700103:Disagree"
          }
        },
        [51003409] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je veux dire que toi, tu ne m’as jamais pris pour un rêveur idiot, pour cela, tu as mon respect. Si l’hiver t’a été si cruel, pourquoi ne pas être venu me voir plus tôt ?",
          DialogueId = 51003409,
          GUID = "7FAE82CA",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003410,
          SpeakNpcId = 700015,
          Subtitle = "What I mean is that you, unlike others, have never seen me as a fool chasing impossible dreams. Therefore, I hold great respect for you, my young friend. If the winter proved too harsh, why didn't you come to me sooner?",
          TalkActionId = {
            [1] = "700102:Agree"
          }
        },
        [51003410] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je te préparerai une chambre. Si tu le souhaites, prends mes manuscrits pour histoires du soir, même si je ne garantis pas qu’elles te feront dormir.",
          DialogueId = 51003410,
          GUID = "7FAE82F4",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003411,
          SpeakNpcId = 700015,
          Subtitle = "I would gladly prepare a room for you. And if you wish, you may even peruse some of my manuscripts as bedtime stories. Though, I can't guarantee they will help you sleep.",
          TalkActionId = {
            [1] = "700102:Explain01_Start"
          }
        },
        [51003411] = {
          Camera = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vous voulez vraiment m’héberger... ? Je ne mérite pas tant, mais je peux vous rendre service, faire des petites tâches, payer ma dette en travaillant pour vous...",
          DialogueId = 51003411,
          GUID = "7FAE831E",
          LookAt = {
            [1] = "700103:n(700102)"
          },
          NextDialogue = 51003412,
          SpeakNpcId = 700080,
          Subtitle = "What...? You'd really let me stay at your place...? Sir, you don't have to do that... But I can help with chores around the house. Please let me do this to make up for the delay I caused.",
          TalkActionId = {
            [1] = "700102:Explain01_End",
            [2] = "700103:Explain02_Start"
          }
        },
        [51003412] = {
          Camera = "-143.197754,12.932617,126.775391,0.000008,0.0,-32.595322,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci pour tout ce que vous avez fait, noble {性别:Chasseur de Phoxène|Chasseuse de Phoxène} ! Détective averti de Givrelac, vous êtes sans pareil, j’y gagne une histoire touchante et, mieux encore, deux véritables amis.",
          DialogueId = 51003412,
          GUID = "7FAE8348",
          LookAt = {
            [1] = "700102:n(100001)"
          },
          NextDialogue = 51003413,
          SpeakNpcId = 700015,
          Subtitle = "Thank you for everything you've done, my dear Phoxhunter! You are indeed the most meticulous detective in all of Icelake. This tale of unexpected kindness has given me much inspiration and forged a friendship between two kind souls.",
          TalkActionId = {
            [1] = "700103:Explain02_End"
          },
          TurnTo = {
            [1] = "700102:n(100001)"
          }
        },
        [51003413] = {
          Camera = "-143.197754,12.932617,126.775391,0.000008,0.0,-32.595322,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah ! L’inspiration me submerge ! Il me faut noter tout cela sur-le-champ, et si mes vers voyagent, votre nom sera loué à travers les siècles !",
          DialogueId = 51003413,
          GUID = "7FAE8372",
          LookAt = {
            [1] = "700102:n(100001)"
          },
          SpeakNpcId = 700015,
          Subtitle = "Ah! I am brimming with inspiration! I must hurry and pen this down! If my prose achieves fame, your name shall be celebrated for centuries to come!",
          TalkActionId = {
            [1] = "700102:Talk01_Start"
          }
        },
        [51003414] = {
          ContentFR = "Les deux s’en vont ensemble, chacun a obtenu ce qu’il souhaitait. Reste à voir si la prochaine pièce de Monsieur Buck tiendra les promesses de son enthousiasme.",
          DialogueId = 51003414,
          Duration = 4,
          GUID = "7FAE839C",
          Subtitle = [[
The two of them depart, each with their desires fulfiled.
However, you remain skeptical about whether Mr Buck's forthcoming work
will be as thrilling as he predicts.]]
        },
        [51003501] = {
          Camera = "-813.361816,168.229736,207.784668,0.000003,-6.799986,-16.405685,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Gloire au sacrifice, hommage à la compassion, et louange à la Paix d’Argent, gardienne qui nous protégea de la peste, de l’ignorance et de la menace des démons.",
          DialogueId = 51003501,
          GUID = "7FAE91E2",
          NextDialogue = 51003520,
          SpeakNpcId = 700086,
          Subtitle = "We thank thee for the sacrifice, mercy, and the Silverpeace that kept the plague, ignorance, and demons far from us...",
          TalkActionId = {
            [1] = "700086:Explain02_Start"
          }
        },
        [51003502] = {
          Camera = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Emma ? Emma !? À quoi penses-tu encore ?",
          DialogueId = 51003502,
          GUID = "7FAE920C",
          LookAt = {
            [1] = "700016:n(700086)"
          },
          NextDialogue = 51003503,
          SpeakNpcId = 700086,
          Subtitle = "Emma? Emma!? Snap out of it.",
          TalkActionId = {
            [1] = "700086:Explain02_End",
            [2] = "700086:Confident_Start"
          }
        },
        [51003503] = {
          Camera = "-344.113281,-49.567139,176.708252,0.000003,-0.399996,158.596222,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh, pardon maîtresse ! J’y vais tout de suite !",
          DialogueId = 51003503,
          GUID = "7FAE9236",
          SpeakNpcId = 700016,
          Subtitle = "Sorry, Miss Lisse! Coming!",
          TalkActionId = {
            [1] = "700086:Confident_End",
            [2] = "700016:Shock_Start"
          }
        },
        [51003504] = {
          Camera = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu es ailleurs ces temps-ci. La prochaine fois, tâche de rester concentrée.",
          DialogueId = 51003504,
          GUID = "7FAE9260",
          NextDialogue = 510035041,
          SpeakNpcId = 700086,
          Subtitle = "Emma, you have been distracted lately. Focus, will you?",
          TalkActionId = {
            [1] = "700086:Sigh_Start"
          }
        },
        [51003505] = {
          ContentFR = "Pff... c’est trop ennuyeux... Je me demande ce que Mamie est en train de faire...",
          DialogueId = 51003505,
          GUID = "7FAE928A",
          NextOptions = {
            [1] = 510035051,
            [2] = 510035052,
            [3] = 510035053
          },
          SpeakNpcId = 700016,
          Subtitle = "Ugh... This is so boring... I wonder how Granny's doing.",
          bForbidSkipOptions = true
        },
        [51003506] = {
          ContentFR = "Enfin bon... j’ai mes raisons. Je peux te les dire, mais tu dois promettre de ne rien répéter.",
          DialogueId = 51003506,
          GUID = "7FAE92B4",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextOptions = {
            [1] = 510035061
          },
          RestartTag = 51003506,
          SpeakNpcId = 700016,
          Subtitle = "Well, I have my reasons. I can tell you about it, but you must promise to keep it a secret.",
          bForbidSkipOptions = true
        },
        [51003507] = {
          ContentFR = "Franchement, un peu oui.",
          DialogueId = 51003507,
          GUID = "7FAE92DE",
          SpeakNpcId = 700016,
          Subtitle = "Well, yeah!"
        },
        [51003508] = {
          ContentFR = "Bon... d’accord, je vais te le dire.",
          DialogueId = 51003508,
          GUID = "7FAE9308",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextDialogue = 51003509,
          SpeakNpcId = 700016,
          Subtitle = "Alright, I'll tell you.",
          TalkActionId = {
            [1] = "700016:Confident_Start"
          }
        },
        [51003509] = {
          ContentFR = "Le mois dernier, je me suis faufilée dans les taudis. Et là, dans une ruelle, j’ai rencontré une vieille dame mystérieuse ! Elle s’appelle Belinda.",
          DialogueId = 51003509,
          GUID = "7FAE9332",
          NextDialogue = 51003510,
          SpeakNpcId = 700016,
          Subtitle = "Last month, I sneaked out to the slums and ran into a mysterious old lady called Belinda in an alleyway!"
        },
        [51003510] = {
          ContentFR = "Elle a des doigts magiques, elle sait tresser des coiffures incroyables, colorer mes ongles avec des fleurs fraîches, et elle connaît des histoires que je n’avais jamais entendues de ma vie !",
          DialogueId = 51003510,
          GUID = "7FAE935C",
          NextDialogue = 51003511,
          SpeakNpcId = 700016,
          Subtitle = "And she's got magic hands — she can braid all sorts of pretty pigtails and dye my nails with fresh flowers! She even told me stories I'd never heard before!",
          TalkActionId = {
            [1] = "700016:Confident_End"
          }
        },
        [51003511] = {
          ContentFR = "Elle ne me fait jamais la leçon, elle ne me prend pas de haut. La première fois déjà, quand elle m’a serrée dans ses bras, j’ai eu l’impression de retrouver ma propre grand-mère...",
          DialogueId = 51003511,
          GUID = "7FAE9386",
          NextDialogue = 51003512,
          SpeakNpcId = 700016,
          Subtitle = "Ms Belinda never nagged at me nor treated me like a child. Though it was the first time I met her, she felt like my own granny when she held me in her arms..."
        },
        [51003512] = {
          ContentFR = "Alors où est le problème ? Pourquoi ne pas dire simplement à tout le monde que tu as une nouvelle amie ?",
          DialogueId = 51003512,
          GUID = "7FAE93B0",
          NextDialogue = 51003513,
          SpeakNpcId = 100001,
          Subtitle = "That sounds really beautiful. Why do you want to keep it a secret?"
        },
        [51003513] = {
          ContentFR = "Parce que... Mamie Belinda a des cornes. Si mes parents, mes camarades ou les professeurs l’apprenaient, elle risquerait d’avoir des ennuis...",
          DialogueId = 51003513,
          GUID = "7FAE93DA",
          NextDialogue = 51003514,
          SpeakNpcId = 700016,
          Subtitle = "Because Ms Belinda has horns... She might get into trouble if I tell my parents, classmates, or teachers about her...",
          TalkActionId = {
            [1] = "700016:Explain02_Start"
          }
        },
        [51003514] = {
          ContentFR = "On devait se voir aujourd’hui, mais l’école a ajouté cette commémoration au dernier moment. Du coup je ne peux pas y aller... Est-ce que tu pourrais lui apporter cette poupée à ma place ?",
          DialogueId = 51003514,
          GUID = "7FAE9404",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextOptions = {
            [1] = 510035141,
            [2] = 51000002
          },
          SpeakNpcId = 700016,
          Subtitle = "We were supposed to meet today. But I can't make it anymore because the school suddenly added this memorial event. If you have the time, could you bring this doll to her?",
          TalkActionId = {
            [1] = "700016:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51003515] = {
          ContentFR = "Mince, je dois y aller, la maîtresse m’attend... Tu me promets de lui donner ? Merci !",
          DialogueId = 51003515,
          GUID = "7FAE942E",
          SpeakNpcId = 700016,
          Subtitle = "I gotta go meet my classmates. Please make sure you give the doll to Ms Belinda. Thank you!"
        },
        [51003520] = {
          ContentFR = "Et maintenant, qu’Emma vienne offrir les fleurs du souvenir...",
          DialogueId = 51003520,
          GUID = "7FAE9500",
          NextDialogue = 51003502,
          SpeakNpcId = 700086,
          Subtitle = "May our student, Emma, offer the floral tribute..."
        },
        [51003601] = {
          Camera = "-59.474121,-281.53418,130.205078,0.000004,0.0,71.19751,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci, Madame Belinda... Je me sens déjà mieux. Si c’est ce que Robb voulait, alors je vais vivre bravement... pour lui.",
          DialogueId = 51003601,
          GUID = "7FAEA24A",
          NextDialogue = 51003602,
          SpeakNpcId = 700087,
          Subtitle = "Thank you, Ms Belinda. I feel a lot better. If this is the wish of Robb, then I'll be brave and live on... for his sake.",
          TalkActionId = {
            [1] = "700087:Explain02_Start"
          }
        },
        [51003602] = {
          Camera = "-83.495605,207.759766,134.179199,0.000004,-0.199981,-68.802429,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Courage, mon enfant. Nous sommes à tes côtés. Et si besoin est, la tente de Belinda te sera toujours ouverte.",
          DialogueId = 51003602,
          GUID = "7FAEA274",
          SpeakNpcId = 700081,
          Subtitle = "May you find the strength to leave your sadness behind. We are always with you, kid. Belinda's hut is always open if you need anything.",
          TalkActionId = {
            [1] = "700087:Explain02_End",
            [2] = "700081:Explain01_Start"
          }
        },
        [51003604] = {
          ContentFR = "Bonjour ! Je ne t’ai jamais vu par ici. Tu viens d’arriver à Givrelac, peut-être ? Qu’est-ce qui t’amène chez la vieille Belinda ?",
          DialogueId = 51003604,
          GUID = "7FAEA2C8",
          NextOptions = {
            [1] = 510036041
          },
          SpeakNpcId = 700081,
          Subtitle = "Greetings. I haven't seen you around before. Have you just arrived at Icelake? Is there anything you seek from this old lady?",
          TalkActionId = {
            [1] = "700081:Explain01_Start"
          }
        },
        [51003605] = {
          ContentFR = "La poupée est rudimentaire, mais on y devine les traits de Belinda. La vieille dame s’en empare avec une joie visible, la caressant avec tendresse.",
          DialogueId = 51003605,
          GUID = "7FAEA2F2",
          NextDialogue = 51003606,
          Subtitle = "(The doll, though crudely made, captures Belinda's essence. The old Charon lady's eyes light up with joy as she gently caresses the doll.)",
          TalkActionId = {
            [1] = "700081:Explain01_End"
          }
        },
        [51003606] = {
          ContentFR = "Je sens encore l’odeur de la place sur ce jouet... Ah ! mais oui, c’est la semaine commémorative ! Comme le temps passe vite...",
          DialogueId = 51003606,
          GUID = "7FAEA31C",
          NextDialogue = 51003607,
          SpeakNpcId = 700081,
          Subtitle = "I can feel the plaza's essence in this doll... Ah, my memory eludes me! It's Memorial Week, filled with all sorts of events...",
          TalkActionId = {
            [1] = "700081:Agree"
          }
        },
        [51003607] = {
          ContentFR = "Merci, mon enfant.",
          DialogueId = 51003607,
          GUID = "7FAEA346",
          NextDialogue = 51003608,
          SpeakNpcId = 700081,
          Subtitle = "Thank you very much, {性别:young man|young lady}."
        },
        [51003608] = {
          ContentFR = "Belinda te fixe longuement, sans un mot.",
          DialogueId = 51003608,
          GUID = "7FAEA370",
          NextDialogue = 51003609,
          Subtitle = "(She observes you silently for a long moment.)"
        },
        [51003609] = {
          ContentFR = "Tu portes un grand fardeau. Je sens sur toi l’odeur de la mer, l’étreinte des vagues... et la chaleur d’une main aimée, qui peu à peu s’éteint.",
          DialogueId = 51003609,
          GUID = "7FAEA39A",
          NextDialogue = 51003610,
          SpeakNpcId = 700081,
          Subtitle = "You seem to be carrying a heavy burden. I smell the ocean's breeze and tides on you, and the lingering warmth in your palm... it is fading...",
          TalkActionId = {
            [1] = "700081:Explain02_Start"
          }
        },
        [51003610] = {
          ContentFR = "Depuis ton arrivée ici, confusion et chagrin t’accompagnent. Tu caches tout ça au fond de ton cœur...",
          DialogueId = 51003610,
          GUID = "7FAEA3C4",
          NextDialogue = 51003611,
          SpeakNpcId = 700081,
          Subtitle = "Every moment you spend in this city is entwined in confusion and sorrow. You try to hide your pain, keeping your sorrows buried deep away from others...",
          TalkActionId = {
            [1] = "700081:Explain02_End"
          }
        },
        [51003611] = {
          ContentFR = "Pardonne ma franchise, mais... as-tu perdu quelqu’un de cher ?",
          DialogueId = 51003611,
          GUID = "7FAEA3EE",
          NextOptions = {
            [1] = 510036111,
            [2] = 510036112,
            [3] = 510036113
          },
          SpeakNpcId = 700081,
          Subtitle = "Pardon me for this intrusion, but have you recently lost someone dear?",
          bForbidSkipOptions = true
        },
        [51003612] = {
          ContentFR = "En effet. Il est rare que les Charons atteignent mon âge.",
          DialogueId = 51003612,
          GUID = "7FAEA418",
          NextDialogue = 51003615,
          SpeakNpcId = 700081,
          Subtitle = "Indeed. It is rare for Charons to reach my age."
        },
        [51003613] = {
          ContentFR = "Tu es triste, mon enfant.",
          DialogueId = 51003613,
          GUID = "7FAEA442",
          NextDialogue = 51003615,
          SpeakNpcId = 700081,
          Subtitle = "Your soul is in pain."
        },
        [51003614] = {
          ContentFR = "Tu souffres, mon enfant. Pas besoin de le nier, je le vois.",
          DialogueId = 51003614,
          GUID = "7FAEA46C",
          NextDialogue = 51003615,
          SpeakNpcId = 700081,
          Subtitle = "You don't have to put on an act. I see the pain you hide."
        },
        [51003615] = {
          ContentFR = "Hélas, je n’ai pas de remède à t’offrir. Mais voici des paroles anciennes, peut-être t’apporteront-elles un peu de réconfort...",
          DialogueId = 51003615,
          GUID = "7FAEA496",
          NextDialogue = 51003616,
          SpeakNpcId = 700081,
          Subtitle = "Though I'm unsure how to ease your suffering, an old saying might provide some comfort..."
        },
        [51003616] = {
          ContentFR = "« Le voyageur chausse ses bottes et s’avance tandis que le fuseau de la Déesse du Destin resserre ses fils. Quand mille chemins se rejoignent, ce qui a été perdu revient doucement à portée de main. »",
          DialogueId = 51003616,
          GUID = "7FAEA4C0",
          NextOptions = {
            [1] = 510036161
          },
          RestartTag = 51003616,
          SpeakNpcId = 700081,
          Subtitle = "\"They don their boots to traverse as Fate retracts her spindle. Doubt and uncertainty dost confound, but what is lost may come around.\"",
          TalkActionId = {
            [1] = "700081:Agree"
          },
          bForbidSkipOptions = true
        },
        [51003617] = {
          ContentFR = "Va, mon enfant. Tu retrouveras sur ta route tout ce qui t’a été arraché.",
          DialogueId = 51003617,
          GUID = "7FAEA4EA",
          SpeakNpcId = 700081,
          Subtitle = "You may leave. You shall find everything you've lost on your journey, {性别:young man|young lady}."
        },
        [51003618] = {
          ContentFR = "C’est la fin de <I>Le Fuseau de la Déesse du Destin</>. Le héros y retrouve, dans le Royaume des Reflets, tout ce qu’il avait perdu... Tu veux dire que nous nous reverrons ?",
          DialogueId = 51003618,
          GUID = "7FAEA514",
          NextDialogue = 51003619,
          SpeakNpcId = 100001,
          Subtitle = "It's the epilogue from The Spindle of the Goddess of Fate... The hero, having lost everything, reunites with all they had lost in the realm of duality... Are you suggesting we'll meet again?"
        },
        [51003619] = {
          ContentFR = "Considère ces mots comme un remerciement pour la poupée. Tu es {性别:intelligent|intelligente}, je le vois bien. Tu trouveras toi-même la réponse.",
          DialogueId = 51003619,
          GUID = "7FAEA53E",
          NextDialogue = 51003620,
          SpeakNpcId = 700081,
          Subtitle = "Consider it a token of gratitude for bringing the doll. You are clever, as I've seen... You'll unravel the meaning on your own.",
          TalkActionId = {
            [1] = "700081:Agree"
          }
        },
        [51003620] = {
          ContentFR = "Et puis... chaque personne qui parvient jusqu’ici pour la première fois reçoit un petit présent de ma part. Il me suffira d’un simple fil de fer portant ton empreinte... Pas besoin de se presser, je t’attendrai ici.",
          DialogueId = 51003620,
          GUID = "7FAEA568",
          NextDialogue = 51003621,
          SpeakNpcId = 700081,
          Subtitle = "And one more thing — every soul who finds their way here gets a little gift from me. Just bring me a piece of wire that's been touched by your presence. No rush. I'll be here.",
          TalkActionId = {
            [1] = "700081:Explain02_Start"
          }
        },
        [51003621] = {
          ContentFR = "Mon empreinte... ? Je ne suis pas {性别:sûr|sûre} de comprendre, mais ça doit vouloir dire n’importe quel objet que j’ai touché ou porté, non ?",
          DialogueId = 51003621,
          GUID = "7FAEA592",
          NextDialogue = 51003622,
          SpeakNpcId = 100001,
          Subtitle = "Touched by my presence...? Hmm. Not exactly sure what that means... But anything I've worn or handled should count, right?",
          TalkActionId = {
            [1] = "700081:Explain02_End"
          }
        },
        [51003622] = {
          ContentFR = "Dans la Fosse de Glevum, il doit y avoir plein de morceaux de fils de fer. J’irai voir.",
          DialogueId = 51003622,
          Duration = 3,
          GUID = "7FAEA5BC",
          SpeakNpcId = 100001,
          Subtitle = "There should be plenty of scrap wire lying around in Glevum Pit. I'll try my luck there."
        },
        [51003630] = {
          ContentFR = "Le jeune Charon, les yeux encore humides, repart avec hésitation. Mais dans son regard brille désormais une volonté nouvelle.",
          DialogueId = 51003630,
          Duration = 4,
          GUID = "7FAEA70C",
          NextDialogue = 51003631,
          Subtitle = "You can see tear marks on the Charon's face, but his eyes now glimmer with hope and a will to live on. "
        },
        [51003631] = {
          ContentFR = "Après avoir serré Belinda dans ses bras, il s’éloigne à contrecœur.",
          DialogueId = 51003631,
          Duration = 2,
          GUID = "7FAEA736",
          Subtitle = "Belinda gives him a hug and he leaves with some hesitation."
        },
        [51003701] = {
          ContentFR = "Belinda prend le fil entre ses doigts et le tord jusqu’à en faire un délicat profil de jeune fille. Il ressemble étrangement à Berenica.",
          DialogueId = 51003701,
          GUID = "7FAEB2B2",
          NextDialogue = 51003702,
          Subtitle = "(Belinda takes the wires from you and crafts it into a girl's silhouette. You can see that the handicraft resembles Berenica.)"
        },
        [51003702] = {
          ContentFR = "Je ne vois que des ombres... Je ne sais pas si cela ressemble à celle que tu chéris. Mais j’espère que cela t’apaisera un peu.",
          DialogueId = 51003702,
          GUID = "7FAEB2DC",
          NextDialogue = 51003703,
          SpeakNpcId = 700081,
          Subtitle = "My skills are modest. I see only shadows and cannot be sure if this resembles the one you yearn for. I hope it brings you comfort.",
          TalkActionId = {
            [1] = "700081:Disagree"
          }
        },
        [51003703] = {
          ContentFR = "Je souhaite de tout cœur que vous vous retrouviez.",
          DialogueId = 51003703,
          GUID = "7FAEB306",
          NextDialogue = 51003704,
          SpeakNpcId = 700081,
          Subtitle = "It is my sincere wish that you are reunited."
        },
        [51003704] = {
          ContentFR = "Tu quittes sa tente, comprenant mieux pourquoi Emma tient tant à elle. Ses pouvoirs ne sont pas immenses, mais elle guérit les cœurs et console les âmes.",
          DialogueId = 51003704,
          GUID = "7FAEB330",
          Subtitle = "(You leave Belinda's tent, now understanding why Emma treasures this place. Belinda's powers may be limited, but she uses them to mend souls and soothe wounds.)"
        },
        [51003705] = {
          Camera = "-279.652405,-157.0,151.0,0.000004,-6.0,21.800476,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bon... ça devrait faire l’affaire !",
          DialogueId = 51003705,
          FinalCamera = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAEA5BD",
          NextDialogue = 51003706,
          SpeakNpcId = 100001,
          Subtitle = "Hmm... this should do the trick.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 5
        },
        [51003706] = {
          Camera = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "H-H-H-Halte-là ! Ce trésor est à moi maintenant !",
          DialogueId = 51003706,
          GUID = "7FAEA5BE",
          NextDialogue = 51003707,
          Scripts = "SEQ{PlayAnimation{ActorId{100001},AnimationId{\"Think_End\"},Duration{1}},TurnTo{_delay{1},TurnToDescription{\"100001:p(180)\"}}}",
          SpeakNpcId = 700206,
          Subtitle = "H-H-H-H-Hands in the air! Whatever that is — it's mine now!"
        },
        [51003707] = {
          Camera = "128.007935,301.234375,103.0,0.000009,0.0,-108.798302,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "D’un bond, la petite Luno surgit de nulle part, arrache le fil de fer de tes mains et s’enfuit en ricanant.",
          DialogueId = 51003707,
          GUID = "7FAEA5BF",
          NextDialogue = 51003708,
          Scripts = "MoveTo{ActorId{700206},TargetPoint{\"QuestPoint_DJMove\"},MoveSpeed{200},Visibility{\"Show\"}}",
          Subtitle = "(With a swoosh, a small figure leaps out of nowhere, snatches the wire from your hand, and bolts — cackling madly as she goes.)"
        },
        [51003708] = {
          Camera = "21.397217,106.074219,131.0,0.00001,0.0,-116.797485,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hahaha ! J’ai enfin réussie ! Cette fois c’est moi la gagnante !",
          DialogueId = 51003708,
          GUID = "7FAEA5C0",
          NextDialogue = 51003709,
          SpeakNpcId = 700206,
