        [51004106] = {
          ContentFR = "Les élèves détalent aussitôt.",
          DialogueId = 51004106,
          GUID = "7FAEF524",
          Subtitle = "(The students scamper off quickly.)"
        },
        [51004107] = {
          ContentFR = "Tu vois ? Ce n’est que du vent.",
          DialogueId = 51004107,
          GUID = "7FAEF54E",
          NextDialogue = 51004108,
          SpeakNpcId = 100001,
          Subtitle = "See? That's all they can do."
        },
        [51004108] = {
          ContentFR = "... Oui !",
          DialogueId = 51004108,
          GUID = "7FAEF578",
          NextDialogue = 51004109,
          SpeakNpcId = 700105,
          Subtitle = "...Yeah!",
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004109] = {
          ContentFR = "Merci... {性别:Quand tu t’es battu, tu avais l’air tellement puissant !|Quand tu t’es battue, tu avais l’air tellement puissante !}",
          DialogueId = 51004109,
          GUID = "7FAEF5A2",
          NextOptions = {
            [1] = 510041091,
            [2] = 510041092
          },
          SpeakNpcId = 700105,
          Subtitle = "Thanks for helping me... You looked really cool throwing those punches!",
          bForbidSkipOptions = true
        },
        [51004110] = {
          ContentFR = "Hein... Vraiment ? Je... J’ai seulement dit tout haut ce que je pensais en silence.",
          DialogueId = 51004110,
          GUID = "7FAEF5CC",
          NextDialogue = 51004111,
          SpeakNpcId = 700105,
          Subtitle = "R—Really? I... I just said the things that I'd wanted to say but couldn't.",
          TalkActionId = {
            [1] = "700105:Shock_Start"
          }
        },
        [51004111] = {
          ContentFR = "Merci ! C’est la première fois que je me sens aussi soulagée et libre !",
          DialogueId = 51004111,
          GUID = "7FAEF5F6",
          NextDialogue = 51004112,
          SpeakNpcId = 700105,
          Subtitle = "Thank you so much. I've never felt so relieved and happy in my life!",
          TalkActionId = {
            [1] = "700105:Shock_End"
          }
        },
        [51004112] = {
          ContentFR = "Pas de quoi. Ils ne t’approcheront pas avant longtemps. Je vais te raccompagner. Voilà mon adresse, s’ils reviennent, viens me trouver.",
          DialogueId = 51004112,
          GUID = "7FAEF620",
          NextDialogue = 51004113,
          SpeakNpcId = 100001,
          Subtitle = "You're welcome. Your classmates should leave you alone for a while. I'll walk you home. Here, this is my address — come find me if they give you trouble again."
        },
        [51004113] = {
          ContentFR = "Je ne veux pas rentrer... !",
          DialogueId = 51004113,
          GUID = "7FAEF64A",
          NextDialogue = 51004114,
          SpeakNpcId = 700105,
          Subtitle = "I don't want to go home...!",
          TalkActionId = {
            [1] = "700105:Disagree"
          }
        },
        [51004114] = {
          ContentFR = "Je suis une Charon. Je veux rester avec les miens...",
          DialogueId = 51004114,
          GUID = "7FAEF674",
          NextOptions = {
            [1] = 510041141
          },
          RestartTag = 51004114,
          SpeakNpcId = 700105,
          Subtitle = "I'm a Charon and I want to stay with my people...",
          TalkActionId = {
            [1] = "700105:Agree"
          },
          bForbidSkipOptions = true
        },
        [51004115] = {
          ContentFR = "La fille boude avec entêtement. Tes paroles ne l’ont pas touchée.",
          DialogueId = 51004115,
          GUID = "7FAEF69E",
          Subtitle = "(The girl gives you a stubborn pout, clearly unconvinced.)"
        },
        [51004116] = {
          ContentFR = "Tu n’as pas remarqué ? Ils jouent les durs, mais dès qu’ils tombent sur plus fort, ils fuient.",
          DialogueId = 51004116,
          GUID = "7FAEF6C8",
          NextDialogue = 51004117,
          SpeakNpcId = 100001,
          Subtitle = "Don't you see that? They acted all tough and mighty towards you, but once someone stronger shows up, they just run away.",
          TalkActionId = {
            [1] = "700105:Think_Start"
          }
        },
        [51004117] = {
          ContentFR = "Ils ne sont pas aussi puissants qu’ils le prétendent. Alors, pourquoi leurs mots seraient-ils vrais ? Faye, tu es une Sola, ne te laisse pas avoir par leurs minables mensonges.",
          DialogueId = 51004117,
          GUID = "7FAEF6F2",
          NextDialogue = 51004118,
          SpeakNpcId = 100001,
          Subtitle = "They're not as strong as they pretend to be. Likewise, their words are not as truthful as they seem. Faye, don't listen to them. You're a hundred percent Sola."
        },
        [51004118] = {
          ContentFR = "Souviens-toi, ne doute jamais de toi à cause de la méchanceté des autres. Ne te reproche rien... C’est ma famille qui me l’a appris, et aujourd’hui je te transmets cette leçon.",
          DialogueId = 51004118,
          GUID = "7FAEF71C",
          NextDialogue = 51004119,
          SpeakNpcId = 100001,
          Subtitle = "Remember, never doubt yourself just because someone says bad things about you... My family taught me this, and I hope you'll keep it in mind too."
        },
        [51004119] = {
          ContentFR = "La fille bat des cils, un peu perdue. Elle ne comprend pas tout, mais son visage s’apaise.",
          DialogueId = 51004119,
          GUID = "7FAEF746",
          NextDialogue = 51004120,
          Subtitle = "(The girl blinks her eyes in confusion. She probably doesn't understand everything you just said, but her expression softens.)"
        },
        [51004120] = {
          ContentFR = "D’accord... puisque tu le dis, je vais essayer ! Mais avant... j’ai une dernière petite demande...",
          DialogueId = 51004120,
          GUID = "7FAEF770",
          NextDialogue = 51004121,
          SpeakNpcId = 700105,
          Subtitle = "Okay... If that's what you say, I'll try my best! But before I leave, I still have a teensy-weensy request...",
          TalkActionId = {
            [1] = "700105:Think_End"
          }
        },
        [51004121] = {
          ContentFR = "Est-ce que je peux toucher ta corne ?",
          DialogueId = 51004121,
          GUID = "7FAEF79A",
          NextOptions = {
            [1] = 510041211,
            [2] = 510041212
          },
          SpeakNpcId = 700105,
          Subtitle = "May I touch your horn?",
          TalkActionId = {
            [1] = "700105:Explain02_Start"
          },
          bForbidSkipOptions = true
        },
        [51004122] = {
          ContentFR = "Merci !",
          DialogueId = 51004122,
          GUID = "7FAEF7C4",
          NextDialogue = 51004123,
          SpeakNpcId = 700105,
          Subtitle = "Thank you!",
          TalkActionId = {
            [1] = "700105:Explain02_End"
          }
        },
        [51004123] = {
          ContentFR = "La fille tend une main délicate et touche prudemment la corne sur ta tête.",
          DialogueId = 51004123,
          GUID = "7FAEF7EE",
          NextDialogue = 51004126,
          Subtitle = "(The girl carefully extends her frail hand and touches the horn on your head.)"
        },
        [51004124] = {
          ContentFR = "Bon... alors, laisse-moi au moins la regarder de près...",
          DialogueId = 51004124,
          GUID = "7FAEF818",
          NextDialogue = 51004125,
          SpeakNpcId = 700105,
          Subtitle = "Alright then. I won't touch it. But can I at least get a better look...?",
          TalkActionId = {
            [1] = "700105:Explain02_End"
          }
        },
        [51004125] = {
          ContentFR = "La fille s’approche et observe attentivement ta corne.",
          DialogueId = 51004125,
          GUID = "7FAEF842",
          NextDialogue = 51004126,
          Subtitle = "(She carefully approaches you and studies the horn on your head.)"
        },
        [51004126] = {
          ContentFR = "Alors c’est ça, une vraie corne de Charon...",
          DialogueId = 51004126,
          GUID = "7FAEF86C",
          NextDialogue = 51004127,
          SpeakNpcId = 700105,
          Subtitle = "So this is what a real Charon horn looks like..."
        },
        [51004127] = {
          ContentFR = "Rouge, fine... Elle brille au soleil... Elle est bien plus jolie que mes tresses.",
          DialogueId = 51004127,
          GUID = "7FAEF896",
          NextOptions = {
            [1] = 510041271
          },
          SpeakNpcId = 700105,
          Subtitle = "It's red and really delicate... it even reflects the sunlight. It looks way cuter than my pigtails.",
          bForbidSkipOptions = true
        },
        [51004128] = {
