          DialogueId = 51004128,
          GUID = "7FAEF8C0",
          NextDialogue = 51004129,
          SpeakNpcId = 700105,
          Subtitle = "You're the first to tell me that. But my pigtails are all messed up now... I have to braid them again.",
          TalkActionId = {
            [1] = "700105:Explain01_Start"
          }
        },
        [51004129] = {
          ContentFR = "Elle sort un peigne, refait soigneusement ses deux tresses, puis les soulève pour les faire ressembler à des cornes.",
          DialogueId = 51004129,
          GUID = "7FAEF8EA",
          NextDialogue = 51004130,
          Subtitle = "(The girl takes out a comb from her bag. She then carefully combs and re-braids her pigtails. Once she's done, she lifts them up.)",
          TalkActionId = {
            [1] = "700105:Explain01_End"
          }
        },
        [51004130] = {
          ContentFR = "Comme ça, ça fait cornes de démon ?",
          DialogueId = 51004130,
          GUID = "7FAEF914",
          NextOptions = {
            [1] = 510041301,
            [2] = 510041302
          },
          SpeakNpcId = 700105,
          Subtitle = "Now, do they look like demon horns?",
          bForbidSkipOptions = true
        },
        [51004131] = {
          ContentFR = "Héhé.",
          DialogueId = 51004131,
          GUID = "7FAEF93E",
          NextDialogue = 51004133,
          SpeakNpcId = 700105,
          Subtitle = "Heheh."
        },
        [51004132] = {
          ContentFR = "Haha, c’est bien aussi.",
          DialogueId = 51004132,
          GUID = "7FAEF968",
          NextDialogue = 51004133,
          SpeakNpcId = 700105,
          Subtitle = "Haha. That's good, too.",
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004133] = {
          ContentFR = "Oh ! J’ai encore des élastiques. Je peux te faire une petite tresse ?",
          DialogueId = 51004133,
          GUID = "7FAEF992",
          NextOptions = {
            [1] = 510041331,
            [2] = 510041332
          },
          SpeakNpcId = 700105,
          Subtitle = "I have plenty of hairbands in my pocket. Can I braid a pigtail for you?",
          bForbidSkipOptions = true
        },
        [51004134] = {
          ContentFR = "Allez, juste un essai !",
          DialogueId = 51004134,
          GUID = "7FAEF9BC",
          NextDialogue = 51004135,
          SpeakNpcId = 700105,
          Subtitle = "Please! I wanna see how it looks!"
        },
        [51004135] = {
          ContentFR = "La fille se met sur la pointe des pieds pour atteindre tes cheveux. Elle paraît nettement plus joyeuse.",
          DialogueId = 51004135,
          GUID = "7FAEF9E6",
          NextDialogue = 51004136,
          Subtitle = "(The girl stands on her toes and pushes you down to reach your hair. She seems a lot more positive and energetic than before.)"
        },
        [51004136] = {
          ContentFR = "Accroupis-toi un peu...",
          DialogueId = 51004136,
          GUID = "7FAEFA10",
          NextDialogue = 51004137,
          SpeakNpcId = 700105,
          Subtitle = "Come on, just squat down a little...",
          TalkActionId = {
            [1] = "700105:Explain01_Start"
          }
        },
        [51004137] = {
          ContentFR = "Tu sens une légère traction sur ta nuque. Elle coiffe avec douceur, rien à craindre pour ta chevelure.",
          DialogueId = 51004137,
          GUID = "7FAEFA3A",
          NextDialogue = 51004138,
          Subtitle = "(You feel the girl slightly tugging your hair. She combs your hair very gently. You don't have to worry about losing any.)",
          TalkActionId = {
            [1] = "700105:Explain01_End"
          }
        },
        [51004138] = {
          ContentFR = "Voilà ! Ouah, tu es tellement {性别:mignon|mignonne} avec des tresses !",
          DialogueId = 51004138,
          GUID = "7FAEFA64",
          NextDialogue = 51004139,
          SpeakNpcId = 700105,
          Subtitle = "Done! Wow, you look so pretty with pigtails!",
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004139] = {
          ContentFR = "Dommage, je n’ai pas de miroir...",
          DialogueId = 51004139,
          GUID = "7FAEFA8E",
          NextDialogue = 51004140,
          SpeakNpcId = 700105,
          Subtitle = "Too bad I don't have a mirror...",
          TalkActionId = {
            [1] = "700105:Think_Start"
          }
        },
        [51004140] = {
          ContentFR = "Oh ! Je sais ! Je vais te dessiner.",
          DialogueId = 51004140,
          GUID = "7FAEFAB8",
          NextDialogue = 51004141,
          SpeakNpcId = 700105,
          Subtitle = "Ah...! I know! I can draw a picture of you.",
          TalkActionId = {
            [1] = "700105:Think_End"
          }
        },
        [51004141] = {
          ContentFR = "Elle sort un cahier de son sac et esquisse ton portrait.",
          DialogueId = 51004141,
          GUID = "7FAEFAE2",
          NextDialogue = 51004142,
          Subtitle = "(The girl opens her backpack and takes out a notebook. She then tries to draw a nice picture of you.)"
        },
        [51004142] = {
          ContentFR = "Au fait... comment tu t’appelles ?",
          DialogueId = 51004142,
          GUID = "7FAEFB0C",
          NextOptions = {
            [1] = 510041421
          },
          SpeakNpcId = 700105,
          Subtitle = "Oh, I forgot to ask — what's your name?",
          bForbidSkipOptions = true
        },
        [51004143] = {
          ContentFR = "Très bien ! {nickname}, je n’oublierai jamais ton nom. Tiens, garde ce dessin de toi que j’ai fait. À bientôt !",
          DialogueId = 51004143,
          GUID = "7FAEFB36",
          NextDialogue = 51004144,
          SpeakNpcId = 700105,
          Subtitle = "Okay, ! I'll always remember you. Here, keep this picture I drew of you. See you around!",
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004144] = {
          ContentFR = "... Mmmh... C’est donc ça l’art abstrait.",
          DialogueId = 51004144,
          GUID = "7FAEFB60",
          NextDialogue = 51004145,
          SpeakNpcId = 100001,
