        },
        [51004145] = {
          ContentFR = "Alors qu’elle s’éloigne, la fille se retourne soudain, le regard grave.",
          DialogueId = 51004145,
          GUID = "7FAEFB8A",
          NextDialogue = 51004146,
          Subtitle = "(The girl is about to leave but she suddenly turns around and gives you a serious gaze.)"
        },
        [51004146] = {
          ContentFR = "Au fait... Quand je t’ai coiffé, j’ai repensé à quelque chose.",
          DialogueId = 51004146,
          GUID = "7FAEFBB4",
          NextDialogue = 51004147,
          SpeakNpcId = 700105,
          Subtitle = "Oh yeah... While I was combing your hair, I suddenly remembered something."
        },
        [51004147] = {
          ContentFR = "On m’a toujours répété que les Charons étaient des enfants de démons, stupides, perfides, toujours à faire le mal...",
          DialogueId = 51004147,
          GUID = "7FAEFBDE",
          NextDialogue = 51004148,
          SpeakNpcId = 700105,
          Subtitle = "They kept telling me that Charons are demon's children who are stupid, evil, and are always doing bad things...",
          TalkActionId = {
            [1] = "700105:Explain01_Start"
          }
        },
        [51004148] = {
          ContentFR = "Mais ce n’est pas vrai, pas vrai ?",
          DialogueId = 51004148,
          GUID = "7FAEFC08",
          NextDialogue = 51004149,
          SpeakNpcId = 700105,
          Subtitle = "I don't think those words are true.",
          TalkActionId = {
            [1] = "700105:Explain01_End"
          }
        },
        [51004149] = {
          ContentFR = "C’est juste un prétexte pour vous harceler... n’est-ce pas ?",
          DialogueId = 51004149,
          GUID = "7FAEFC32",
          NextOptions = {
            [1] = 510041491,
            [2] = 510041492
          },
          SpeakNpcId = 700105,
          Subtitle = "They were just lies made up as an excuse to bully your kind, right?",
          TalkActionId = {
            [1] = "700105:Confident_Start"
          },
          bForbidSkipOptions = true
        },
        [51004150] = {
          ContentFR = "Alors vous avez sûrement... souffert bien plus que moi.",
          DialogueId = 51004150,
          GUID = "7FAEFC5C",
          NextDialogue = 51004151,
          SpeakNpcId = 700105,
          Subtitle = "You must have... suffered way more pain than I ever have.",
          TalkActionId = {
            [1] = "700105:Confident_End"
          }
        },
        [51004151] = {
          ContentFR = "Désormais, si je peux faire quoi que ce soit pour aider, je le ferai. Pas parce que nous sommes pareils... mais parce que nous sommes {性别:amis|amies}.",
          DialogueId = 51004151,
          GUID = "7FAEFC86",
          SpeakNpcId = 700105,
          Subtitle = "If there's anything I can do to help in the future, please do let me know... It's not because we're the same kind, but because we're friends.",
          TalkActionId = {
            [1] = "700105:Explain02_Start"
          }
        },
        [51004152] = {
          ContentFR = "Mes camarades ne m’aiment toujours pas... mais je n’ai plus peur d’eux ! Tout ça, c’est grâce à toi !",
          DialogueId = 51004152,
          GUID = "7FAEFCB0",
          SpeakNpcId = 700105,
          Subtitle = "My classmates still don't like me, but I'm not afraid of them anymore! All thanks to you!"
        },
        [51004201] = {
          ContentFR = "Pff. Une nouvelle tête.",
          DialogueId = 51004201,
          GUID = "7FAF04BA",
          NextDialogue = 51004202,
          SpeakNpcId = 700096,
          Subtitle = "Tsk. A new face.",
          TalkActionId = {
            [1] = "700096:Talk03_Start"
          }
        },
        [51004202] = {
          ContentFR = "L’homme en face de toi plisse les yeux, ses lèvres fendues et sèches s’étirent tandis qu’il recrache des mots arides.",
          DialogueId = 51004202,
          GUID = "7FAF04E4",
          NextDialogue = 51004203,
          Subtitle = "(The man before you squints, his lips cracked and dry, as he gruffly spits out his words.)"
        },
        [51004203] = {
          ContentFR = "Alors, dis-moi. Qui t’envoie ici ?",
          DialogueId = 51004203,
          GUID = "7FAF050E",
          NextOptions = {
            [1] = 510042031,
            [2] = 510042032,
            [3] = 510042033
          },
          SpeakNpcId = 700096,
          Subtitle = "Tell me. Who sent you here?",
          TalkActionId = {
            [1] = "700096:Talk03_End"
          },
          bForbidSkipOptions = true
        },
        [51004204] = {
          ContentFR = "Une nouvelle question est parfois la meilleure des réponses.",
          DialogueId = 51004204,
          GUID = "7FAF0538",
          NextDialogue = 51004207,
          Subtitle = "(Answering a question with another question always works.)"
        },
        [51004205] = {
          ContentFR = "Il est évident qu’il attend quelqu’un.",
          DialogueId = 51004205,
          GUID = "7FAF0562",
          NextDialogue = 51004207,
          Subtitle = "(It is obvious that he's waiting for someone.)"
        },
        [51004206] = {
          ContentFR = "Tu ignores ce qu’il voulait entendre, mais personne ne refuse jamais ce genre de réponse.",
          DialogueId = 51004206,
          GUID = "7FAF058C",
          NextDialogue = 51004207,
          Subtitle = "(I don't know what he meant, but that's an answer that no one will refuse.)"
        },
        [51004207] = {
          ContentFR = "L’homme reste un instant silencieux, puis lève les yeux pour t’observer. Tu entends presque ses vertèbres craquer sous l’effort.",
          DialogueId = 51004207,
          GUID = "7FAF05B6",
          NextDialogue = 51004208,
          Subtitle = "(The man broods silently for a while, assessing you. His posture decrepit as he raises his head with an audible creak.)"
        },
        [51004208] = {
          ContentFR = "{性别:Beau parleur|Fine parleuse}.",
          DialogueId = 51004208,
          GUID = "7FAF05E0",
          NextDialogue = 51004209,
          SpeakNpcId = 700096,
          Subtitle = "You smooth talker.",
          TalkActionId = {
            [1] = "700096:Disagree"
          }
        },
        [51004209] = {
          ContentFR = "Il émet un bref grognement, mais son expression semble trahir une certaine satisfaction.",
          DialogueId = 51004209,
          GUID = "7FAF060A",
          NextDialogue = 51004210,
          Subtitle = "(He snorted, but he seemed to be satisfied with your answer.)"
        },
        [51004210] = {
          ContentFR = "Peu importe qui t’a recommandé. De toute façon, tu es là pour ce que j’ai dans ma poche, pas vrai ?",
          DialogueId = 51004210,
          GUID = "7FAF0634",
          NextDialogue = 51004211,
          SpeakNpcId = 700096,
          Subtitle = "I don't care who the fixer is. You're here for the stuff in my pocket, ain't that right?",
          TalkActionId = {
            [1] = "700096:Confident_Start"
          }
        },
        [51004211] = {
          ContentFR = "Il entrouvre son col, laissant entrevoir le reflet terne d’un canon métallique.",
          DialogueId = 51004211,
          GUID = "7FAF065E",
          NextDialogue = 51004212,
          Subtitle = "(He opens his collar to reveal a dull iron piece.)",
          TalkActionId = {
            [1] = "700096:Confident_End"
          }
        },
        [51004212] = {
          ContentFR = "Il resserre aussitôt son manteau et jette un regard méfiant autour de lui.",
          DialogueId = 51004212,
          GUID = "7FAF0688",
          NextDialogue = 51004213,
          Subtitle = "(After showing it, he quickly conceals it again, looking around warily.)"
        },
        [51004213] = {
          ContentFR = "Calibre 4. Double canon, un seul tir. Qu’il s’agisse d’un Charon ou d’un Souillé, personne ne résiste à ça.",
          DialogueId = 51004213,
          GUID = "7FAF06B2",
          NextDialogue = 51004214,
          SpeakNpcId = 700096,
          Subtitle = "Calibre 4. Double barrelled. Single shot. No Charon or Filthoid can survive a blast from this baby."
        },
        [51004214] = {
          ContentFR = "Ses lèvres se tordent, comme s’il parlait d’un banal pesticide.",
          DialogueId = 51004214,
          GUID = "7FAF06DC",
          NextDialogue = 51004215,
          Subtitle = "(His lip curls, as if he's just discussing the uses of a pesticide.)"
        },
        [51004215] = {
          ContentFR = "Cette fois, pas besoin d’argent. Mais tu vas devoir faire quelque chose pour moi.",
          DialogueId = 51004215,
          GUID = "7FAF0706",
          NextOptions = {
            [1] = 510042151,
            [2] = 510042152
          },
          SpeakNpcId = 700096,
          Subtitle = "You can have it for free, but I'll need you to do something for me.",
          bForbidSkipOptions = true
        },
        [51004216] = {
          ContentFR = "Qu’est-ce que tu bafouilles ? T’es venu pour ce joujou, non ?",
          DialogueId = 51004216,
          GUID = "7FAF0730",
          NextDialogue = 51004217,
          SpeakNpcId = 700096,
          Subtitle = "Cut the crap. You're here for this piece of metal, ain't that right?",
          TalkActionId = {
            [1] = "700096:Explain01_Start"
          }
        },
        [51004217] = {
          ContentFR = "Si tu t’acquittes de la tâche, il est à toi. Et je rajoute même une prime.",
          DialogueId = 51004217,
          GUID = "7FAF075A",
          NextOptions = {
            [1] = 510042171,
            [2] = 510042172
          },
          RestartTag = 51004216,
          SpeakNpcId = 700096,
          Subtitle = "Do the job, and it's yours. I can even give you extra money.",
          TalkActionId = {
            [1] = "700096:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51004218] = {
          ContentFR = "Dépêche-toi. J’ai pas toute la journée.",
          DialogueId = 51004218,
          GUID = "7FAF0784",
          SpeakNpcId = 700096,
          Subtitle = "Are you in or what? I ain't got all day."
        },
        [51004219] = {
          ContentFR = "Bon, d’accord. Qu’est-ce que tu veux que je fasse ?",
          DialogueId = 51004219,
          GUID = "7FAF07AE",
          NextDialogue = 51004220,
          SpeakNpcId = 100001,
          Subtitle = "Fine, I'm in. What's the deal?"
        },
        [51004220] = {
          ContentFR = "Parfait. Je vais te donner un lieu. Là-bas, dégomme tout le monde sauf la femme.",
          DialogueId = 51004220,
          GUID = "7FAF07D8",
          NextDialogue = 51004221,
          SpeakNpcId = 700096,
          Subtitle = "Good. I'll give you a location. Kill everything there except for a woman.",
          TalkActionId = {
            [1] = "700096:Agree"
          }
        },
        [51004221] = {
          ContentFR = "... Une histoire de cœur ?",
          DialogueId = 51004221,
          GUID = "7FAF0802",
          NextDialogue = 51004222,
          SpeakNpcId = 100001,
          Subtitle = "So... A bad romance, huh?"
        },
        [51004222] = {
          ContentFR = "Mêle-toi de tes affaires. Fais juste le travail.",
          DialogueId = 51004222,
          GUID = "7FAF082C",
          NextDialogue = 51004223,
          SpeakNpcId = 700096,
          Subtitle = "None of your beeswax. Just get it done.",
          TalkActionId = {
            [1] = "700096:Disagree"
          }
        },
        [51004223] = {
          ContentFR = "Il resserre son col et pince ses lèvres sèches, refusant de dire un mot de plus.",
          DialogueId = 51004223,
          GUID = "7FAF0856",
          Subtitle = "(The man tightens his collar and licks his dried lips, unwilling to utter another word.)"
        },
        [51004301] = {
          ContentFR = "Bien joué. Prends ton argent et pars. Je ne veux plus te voir dans le coin.",
          DialogueId = 51004301,
          GUID = "7FAF1522",
          NextDialogue = 51004302,
          SpeakNpcId = 700101,
          Subtitle = "That was impressive. Now, take the quid and leave. Don't want to see you around here again.",
          TalkActionId = {
            [1] = "700101:Agree"
          }
        },
        [51004302] = {
          ContentFR = "Tout ça, c’était juste pour que je nettoie les Souillés du coin ? Même sans moi, quelqu’un aurait fini par s’en occuper.",
          DialogueId = 51004302,
          GUID = "7FAF154C",
          NextDialogue = 51004303,
          SpeakNpcId = 100001,
          Subtitle = "You just wanted the Filthoids cleared? You didn't need to hire me for that. Someone would have handled it eventually."
        },
        [51004303] = {
          ContentFR = "Quelqu’un ? Tu veux dire ces pourritures en uniforme, qui traitent les Charons comme des chiens ?",
          DialogueId = 51004303,
          GUID = "7FAF1576",
          NextDialogue = 51004304,
          SpeakNpcId = 700101,
          Subtitle = "Someone? You mean those bloody uniformed buggers treating Charons like trash?",
          TalkActionId = {
            [1] = "700101:Angry01_Start"
          }
        },
        [51004304] = {
          ContentFR = "Imagine-les découvrir qu’ici vit une femme Charon, seule, frêle. Tu crois qu’ils feraient quoi ?",
          DialogueId = 51004304,
          GUID = "7FAF15A0",
          NextDialogue = 51004305,
          SpeakNpcId = 700101,
          Subtitle = "What do you think happens when they find a frail Charon woman alone in there?",
          TalkActionId = {
            [1] = "700101:Angry01_End"
          }
        },
        [51004305] = {
          ContentFR = "Soudain, il porte la main à sa poitrine. Son corps tremble, comme si une vieille blessure s’était réveillée. Après de longues secondes, il reprend son souffle, détourne la tête et crache au sol.",
          DialogueId = 51004305,
          GUID = "7FAF15CA",
          NextDialogue = 51004306,
          Subtitle = "(The man suddenly clutches his chest, shaking and wincing as if a deep, old wound has flared. He stops shaking after a while, and then turns his head to spit on the ground.)"
        },
        [51004306] = {
          ContentFR = "Une femme Charon, compatissante, qui a lancé des pierres sur un molosse échappé de la cité intérieure pour protéger un étranger blessé.",
          DialogueId = 51004306,
          GUID = "7FAF15F4",
          NextDialogue = 51004307,
          SpeakNpcId = 700101,
          Subtitle = "A kind Charon woman once threw stones at a hound that ran out of the inner city to save an injured stranger."
        },
        [51004307] = {
          ContentFR = "Pour ça, ils l’ont battue à mort, traînée jusqu’aux portes de Givrelac et jetée ici, dans cette terre désolée.",
          DialogueId = 51004307,
          GUID = "7FAF161E",
          NextDialogue = 51004308,
          SpeakNpcId = 700101,
          Subtitle = "For that, they flogged her, dragged her bleeding body outside Icelake, and left her in this wilderness."
        },
        [51004308] = {
          ContentFR = "... Tu pourrais peut-être trouver un moyen de la faire partir, lui offrir une autre vie loin d’ici.",
          DialogueId = 51004308,
          GUID = "7FAF1648",
          NextDialogue = 51004309,
          SpeakNpcId = 100001,
          Subtitle = "...Maybe you can figure out a way to get her out of Icelake and live somewhere else."
        },
        [51004309] = {
          ContentFR = "... Bientôt. Je touche au but. Bientôt j’aurai assez d’argent.",
          DialogueId = 51004309,
          GUID = "7FAF1672",
          NextDialogue = 51004310,
          SpeakNpcId = 700101,
          Subtitle = "...I'm working on it. Soon I'll have enough cash.",
          TalkActionId = {
            [1] = "700101:Agree"
          }
        },
        [51004310] = {
          ContentFR = "Il se tourne vers la tente. Ses lèvres raides se soulèvent l’espace d’un instant, esquissant un sourire rare.",
          DialogueId = 51004310,
          GUID = "7FAF169C",
          LookAt = {
            [1] = "700101:n(700100)"
          },
          NextDialogue = 51004311,
          Subtitle = "(The man turns around to face the tent. His stiff lips open into what seems to be a smile, a rare expression for this man.)",
          TurnTo = {
            [1] = "700101:n(700100)"
          }
        },
        [51004311] = {
          ContentFR = "Il te semble entendre le craquement sec du bois mort qui se redresse.",
          DialogueId = 51004311,
          GUID = "7FAF16C6",
          Subtitle = "(You thought you heard the cracks made by dead wood being straightened out.)"
        },
        [51004401] = {
          ContentFR = "Qu’est-ce qui ne disparaît jamais dans les égouts ?",
          DialogueId = 51004401,
          GUID = "7FAF258A",
          NextOptions = {
            [1] = 510044011,
            [2] = 510044012,
            [3] = 510044013
          },
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "What's in the sewers that never goes away?",
          bForbidSkipOptions = true
        },
        [51004402] = {
          ContentFR = "Entre.",
          DialogueId = 51004402,
          GUID = "7FAF25B4",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Come on in."
        },
        [51004403] = {
          ContentFR = "Ici, ce n’est pas un endroit pour les {性别:idiots|idiotes} qui ne savent rien.",
          DialogueId = 51004403,
          GUID = "7FAF25DE",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "This is no place for a clueless fool like you."
        },
        [51004501] = {
          Camera = "-234.128906,122.0,168.883789,0.0,-11.799739,-20.999071,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas de femme, seulement des Souillés. Tout est réglé. Ou tu voulais que je laboure le sol en plus ?",
          DialogueId = 51004501,
          FinalCamera = "-234.128906,132.925781,168.883789,0.0,-11.799766,-20.999094,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF35F2",
          LookAt = {
            [1] = "700101:n(100001)",
            [2] = "100001:n(700101)"
          },
          NextDialogue = 51004502,
          SpeakNpcId = 100001,
          Subtitle = "No woman — just Filthoids. They're all down. Or was I supposed to polish the ground for you too?",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          },
          ToFinalCameraBlendTime = 7
        },
        [51004502] = {
          Camera = "265.636719,135.800781,103.029297,0.00002,1.999995,-157.798172,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "T’as la langue bien pendue. Pas {性别:curieux|curieuse} qu’elle n’y soit pas ?",
          DialogueId = 51004502,
          GUID = "7FAF361C",
          NextDialogue = 51004503,
          SpeakNpcId = 700101,
          Subtitle = "Heh. Sharp tongue, huh? Not even curious why she wasn't there?",
          TalkActionId = {
            [1] = "100001:Confident_End",
            [2] = "700101:Talk03_Start"
          }
        },
        [51004503] = {
          Camera = "-234.128906,132.925781,168.883789,0.0,-11.799766,-20.999094,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu m’as donné un lieu, j’ai tout nettoyé. La mission s’arrêtait là.",
          DialogueId = 51004503,
          GUID = "7FAF3646",
          NextDialogue = 51004504,
          SpeakNpcId = 100001,
          Subtitle = "You gave me a location. I cleared it. That's the job.",
          TalkActionId = {
            [1] = "700101:Talk03_End",
            [2] = "100001:Explain01_Start"
          }
        },
        [51004504] = {
          Camera = "265.636719,135.800781,103.029297,0.00002,1.999995,-157.798172,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{性别:Professionnel|Professionnelle}. Voilà ce que doit être un Chasseur de Phoxène. Excuse ma petite mise à l’épreuve... Dans notre métier, il faut apprendre à se méfier.",
          DialogueId = 51004504,
          GUID = "7FAF3670",
          NextDialogue = 51004505,
          SpeakNpcId = 700101,
          Subtitle = "Now that's professional. Thing is — this wasn't the spot. Had to throw out a few false leads. In our line of work, you learn to trust slow and lie fast.",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700101:Agree"
          }
        },
        [51004505] = {
          Camera = "265.636719,135.800781,103.029297,0.00002,1.999995,-157.798172,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tiens, cette fois c’est le vrai lieu. Comme avant, tu élimines tout sauf la femme.",
          DialogueId = 51004505,
          GUID = "7FAF369A",
          SpeakNpcId = 700101,
          Subtitle = "Here. This is the real location. Same deal — clear out everything except the woman.",
          TalkActionId = {
            [1] = "700101:Give"
          }
        },
        [51004901] = {
          Content = "（街边一位拿着一叠纸的女人吸引了你的注意：你留意到纸上罗列着一些药剂。也许这个女人与<H>玛尔洁给的某个线索</>有关。）",
          DialogueId = 51004901,
          GUID = "7FAF7792",
          LookAt = {
            [1] = "700010:n(0)"
          }
        },
        [51004902] = {
          ContentFR = "Tu décides de lui montrer l’un des indices que Margie t’a donnés.",
          DialogueId = 51004902,
          FinalDialogueId = 51004905,
          GUID = "7FAF77BC",
          NextOptions = {
            [1] = 510049021,
            [2] = 510049022,
            [3] = 510049023
          },
          Subtitle = "You decide to show her one thing you got from Margie.",
          bForbidSkipOptions = true
        },
        [51004903] = {
          ContentFR = "La femme reste silencieuse, te regarde avec méfiance et secoue la tête. Apparemment, ce n’est pas ce qu’elle a perdu.",
          DialogueId = 51004903,
          GUID = "7FAF77E6",
          NextOptions = {
            [1] = 510049031,
            [2] = 510049032
          },
          Subtitle = "(The woman remains silent. She looks at you warily and shakes her head. Perhaps what you showed her isn't something she lost.)",
          TalkActionId = {
            [1] = "700010:Disagree"
          },
          bForbidSkipOptions = true
        },
        [51004905] = {
          ContentFR = "Docteur Luna, n’est-ce pas ? Cette ordonnance, c’est bien vous qui l’avez écrite ?",
          DialogueId = 51004905,
          GUID = "7FAF783A",
          NextDialogue = 51004906,
          SpeakNpcId = 100001,
          Subtitle = "Dr Luna, is it? Did you write this prescription?"
        },
        [51004906] = {
          ContentFR = "Tu tends l’ordonnance devant elle, pour qu’elle puisse lire les mots dangereux.",
          DialogueId = 51004906,
          GUID = "7FAF7864",
          NextDialogue = 51004907,
          Subtitle = "(You present the prescription in your hand and show Luna the dangerous lines.)"
        },
        [51004907] = {
          ContentFR = "Hors de la ville, les Souillés nous dévorent,\nEn ville, les fermiers nous tondent sans répit.\nLes chiens festoient de pain blanc,\nLes moutons Charon broutent l’herbe jaunie.\nOn rampe, on traîne, on bêle, on flatte,\nPour un sourire des maîtres.\nIls rient de nos corps, de nos âmes,\nEt nous... nous subissons, toujours.",
          DialogueId = 51004907,
          GUID = "7FAF788E",
          NextDialogue = 51004908,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"Wild Filthoids gorge on our flesh, city lords shear our fleece. The hounds dine on fine white loaves, while lowly Charon sheep chew yellowed grass. We roll and we crawl, we baa and we fawn. The masters laugh, while we bear it all.\""
        },
        [51004908] = {
          ContentFR = "Ah... O-Oh, je... euh...",
          DialogueId = 51004908,
          GUID = "7FAF78B8",
          NextDialogue = 51004909,
          SpeakNpcId = 700010,
          Subtitle = "Ah... Uhm... I...",
          TalkActionId = {
            [1] = "700010:Shock_Start"
          }
        },
        [51004909] = {
          ContentFR = "En voyant l’ordonnance, Luna commence immédiatement à bafouiller, gesticulant nerveusement avec ses mains. Son écriture et sa réaction prouvent que tu as trouvé la bonne personne.",
          DialogueId = 51004909,
          GUID = "7FAF78E2",
          NextOptions = {
            [1] = 510049091,
            [2] = 510049092
          },
          Subtitle = "(Luna starts to stammer and gesture wildly with her hands. Her handwriting and reactions prove that you have found the right person.)",
          TalkActionId = {
            [1] = "700010:Shock_Loop"
          }
        },
        [51004910] = {
          ContentFR = "Tes mots semblent calmer un peu Luna.",
          DialogueId = 51004910,
          GUID = "7FAF790C",
          NextDialogue = 51004912,
          Subtitle = "(Your words seem to calm Luna down a little.)",
          TalkActionId = {
            [1] = "700010:Shock_End"
          }
        },
        [51004911] = {
          ContentFR = "Tes actions semblent la rendre plus anxieuse.",
          DialogueId = 51004911,
          GUID = "7FAF7936",
          NextDialogue = 51004912,
          Subtitle = "(Your actions seem to make her more anxious.)",
          TalkActionId = {
            [1] = "700010:Shock_End"
          }
        },
        [51004912] = {
          ContentFR = "Si ce papier tombe entre de mauvaises mains, vous pourriez avoir de gros ennuis, non ?",
          DialogueId = 51004912,
          GUID = "7FAF7960",
          NextDialogue = 51004913,
          SpeakNpcId = 100001,
          Subtitle = "If this piece of paper falls into the hands of someone else, you might get into some serious trouble."
        },
        [51004913] = {
          ContentFR = "Luna pointe sa gorge, puis prend une feuille vierge et écrit rapidement.",
          DialogueId = 51004913,
          GUID = "7FAF798A",
          NextDialogue = 51004914,
          Subtitle = "(Luna points at her throat, then grabs a blank sheet and scribbles at speed.)",
          TalkActionId = {
            [1] = "700010:Explain02_Start"
          }
        },
        [51004914] = {
          ContentFR = "« J’étais une ménestrelle itinérante. Des personnes qui haïssaient les Charons m’ont kidnappée. Ils se sont moqués de moi, m’ont frappée, rasé les cheveux, lacéré la peau. »",
          DialogueId = 51004914,
          GUID = "7FAF79B4",
          NextDialogue = 510049141,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"I used to be a wandering bard. Then they came — those thugs who hate the Charon. They dragged me away. Mocked me. Beat me. Shaved my head. Tore my skin.\"",
          TalkActionId = {
            [1] = "700010:Explain02_End"
          }
        },
        [51004915] = {
          ContentFR = "Alors pourquoi continuez-vous d’écrire ?",
          DialogueId = 51004915,
          GUID = "7FAF79DE",
          NextDialogue = 51004916,
          SpeakNpcId = 100001,
          Subtitle = "Then... why do you keep writing these?"
        },
        [51004916] = {
          ContentFR = "Luna baisse la tête et continue d’écrire.",
          DialogueId = 51004916,
          GUID = "7FAF7A08",
          NextDialogue = 51004917,
          Subtitle = "(Luna lowers her head and keeps on writing.)"
        },
        [51004917] = {
          ContentFR = "« Garder tout cela en moi me fait trop mal. »",
          DialogueId = 51004917,
          GUID = "7FAF7A32",
          NextOptions = {
            [1] = 510049171,
            [2] = 510049172,
            [3] = 510049173
          },
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"Keeping it bottled up inside hurts a lot.\"",
          TalkActionId = {
            [1] = "700010:Disagree"
          },
          bForbidSkipOptions = true
        },
        [51004918] = {
          ContentFR = "« Oui... ça ne change rien. Je n’ose même pas montrer ce que j’écris, mais je ne peux pas m’empêcher d’écrire quelque chose. »",
          DialogueId = 51004918,
          GUID = "7FAF7A5C",
          NextDialogue = 51004919,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"I know. I can't even show others what I wrote. But I just can't help it.\""
        },
        [51004919] = {
          ContentFR = "« Je ne peux plus chanter, et si je cessais d’écrire un jour, je perdrais la dernière chose précieuse que j’ai alors... je n’aurais plus rien. »",
          DialogueId = 51004919,
          GUID = "7FAF7A86",
          NextDialogue = 51004920,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"I can't sing anymore. And if I give up writing too, I'll lose the last valuable thing I have. When that happens, I'll truly have nothing to call my own.\""
        },
        [51004920] = {
          ContentFR = "Si vous ne vous sentez pas bien, occupez-vous avec quelque chose de concret. Ça vous fera du bien. Et vous pouvez continuer d’écrire, mais la prochaine fois, veillez à ne pas perdre vos feuilles.",
          DialogueId = 51004920,
          GUID = "7FAF7AB0",
          NextDialogue = 51004921,
          SpeakNpcId = 100001,
          Subtitle = "You can find something else to keep yourself occupied. That should make you feel better. You can also keep writing if it helps, just don't lose your work again."
        },
        [51004921] = {
          ContentFR = "La femme réfléchit un long moment, puis hoche la tête.",
          DialogueId = 51004921,
          GUID = "7FAF7ADA",
          NextDialogue = 51004922,
          Subtitle = "(The woman thinks for a while and then nods.)",
          TalkActionId = {
            [1] = "700010:Agree"
          }
        },
        [51004922] = {
          ContentFR = "« Merci de me l’avoir rendu, âme bienveillante. Voici un petit quelque chose en guise de remerciement. »",
          DialogueId = 51004922,
          GUID = "7FAF7B04",
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"Thank you for returning this to me, gentle soul. Please accpet this as a thank-you gift.\"",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004923] = {
          ContentFR = "« Merci, mais je ne suis qu’une lâche qui se plaint sur des bouts de papier. Je n’ai pas le courage de montrer ça à quelqu’un. »",
          DialogueId = 51004923,
          GUID = "7FAF7B2E",
          NextDialogue = 51004924,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"You flatter me. I'm just a coward whose complaints remain on useless pieces of scrap. I don't even have the courage to show them to anyone.\"",
          TalkActionId = {
            [1] = "700010:Disagree"
          }
        },
        [51004924] = {
          ContentFR = "Être capable d’exprimer vos véritables sentiments sur papier, c’est déjà plus courageux que la plupart des gens. Mais veillez à ne pas perdre vos feuilles.",
          DialogueId = 51004924,
          GUID = "7FAF7B58",
          NextDialogue = 51004925,
          SpeakNpcId = 100001,
          Subtitle = "Expressing your true feelings in writing already makes you braver than most people. Just try to keep your work safe and don't lose it again."
        },
        [51004925] = {
          ContentFR = "Un léger sourire se dessine sur les lèvres de la femme. Elle hoche la tête, et ses yeux sont humides.",
          DialogueId = 51004925,
          GUID = "7FAF7B82",
          NextDialogue = 51004926,
          Subtitle = "(The lady gives a faint smile and nods. You can see tears welling in her eyes.)"
        },
        [51004926] = {
          ContentFR = "« Merci de me l’avoir rendu, âme bienveillante. Voici un petit quelque chose en guise de remerciement. »",
          DialogueId = 51004926,
          GUID = "7FAF7BAC",
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"Thank you for returning this to me, gentle soul. Please accpet this as a thank-you gift.\"",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004927] = {
          ContentFR = "La femme pousse un gémissement rauque, cachant son visage dans ses mains. Après un long moment, elle ouvre son sac en tremblant et te donne de l’argent.",
          DialogueId = 51004927,
          GUID = "7FAF7BD6",
          NextDialogue = 51004928,
          Subtitle = "(The lady gives a raspy wail and buries her sad face in her hands. After a long time, she finally opens her purse and gives you some money while quaking in fear.)",
          TalkActionId = {
            [1] = "700010:Sigh_Start"
          }
        },
        [51004928] = {
          ContentFR = "« Tout ceci est pour toi. S’il te plaît, rends-moi ce papier. »",
          DialogueId = 51004928,
          GUID = "7FAF7C00",
          NextDialogue = 51004929,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"This is all yours. Just give me back that piece of paper.\"",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004929] = {
          ContentFR = "Tu hoches la tête avec satisfaction, si ce papier tombait entre de mauvaises mains, elle perdrait bien plus que de l’argent. Tu l’as protégée et mérites ta récompense.",
          DialogueId = 51004929,
          GUID = "7FAF7C2A",
          Subtitle = "(You give a satisfied nod — if the poetry falls into the wrong hands, she would lose more than just a wad of cash. You saved her from that fate and deserve the payment.)"
        },
        [51004930] = {
          ContentFR = "Hngh... ouuuaah...",
          DialogueId = 51004930,
          GUID = "7FAF7C54",
          NextDialogue = 51004931,
          SpeakNpcId = 700010,
          Subtitle = "Hngh... Waaahh..."
        },
        [51004931] = {
          ContentFR = "Comme toujours, elle marmonne des mots incompréhensibles, évitant ton regard.",
          DialogueId = 51004931,
          GUID = "7FAF7C7E",
          Subtitle = "(Luna still mumbles unintelligibly. Her eyes dart about to avoid your gaze.)"
        },
        [51004935] = {
          Camera = "-843.349854,-34.817383,370.464844,0.000092,-16.799791,-21.997007,35.0,100000.0,false,Manual,2.8",
          ContentFR = "Tu veux mourir ou quoi ? Donne-moi ça !",
          DialogueId = 51004935,
          FinalCamera = "-635.633789,-118.727051,302.828857,0.000092,-16.799791,-21.997007,35.0,100000.0,false,Manual,2.8",
          GUID = "7FAF7C7F",
          NextDialogue = 51004936,
          SpeakNpcId = 700225,
          Subtitle = "Got a death wish, have you? Hand it over!",
          ToFinalCameraBlendTime = 10
        },
        [51004936] = {
          ContentFR = "Laisse-moi voir ce que tu as encore écrit, qu’est-ce que tu caches, hein ?",
          DialogueId = 51004936,
          GUID = "7FAF7C80",
          NextDialogue = 51004937,
          SpeakNpcId = 700226,
          Subtitle = "Let's see what you've scribbled this time — what're you hiding, huh?"
        },
        [51004937] = {
          ContentFR = "La dernière fois c’était ta gorge qui n’obéissait pas... cette fois quoi ? Tes yeux ? Tes mains ? Les deux peut-être ?",
          DialogueId = 51004937,
          GUID = "7FAF7C81",
          NextDialogue = 51004938,
          SpeakNpcId = 700225,
          Subtitle = "Last time it was your throat — what now? Your eyes? Hands? Maybe both?"
        },
        [51004938] = {
          ContentFR = "A... aah !",
          DialogueId = 51004938,
          GUID = "7FAF7C82",
          NextDialogue = 51004939,
          SpeakNpcId = 700010,
          Subtitle = "Aargh... aaaargh!"
        },
        [51004939] = {
          ContentFR = "La femme, entourée par les malfrats, se précipite pour ramasser les papiers éparpillés, mordant sa lèvre inférieure, le visage pâle, les yeux remplis de peur. Tu ignores la relation exacte qu’elle a avec eux, mais tu sais qu’elle est en danger.",
          DialogueId = 51004939,
          GUID = "7FAF7C83",
          Subtitle = "(The woman scrambles to scoop up her scattered notes. Her lips press tight, her face ghost-pale. Fear blazes in her eyes as the thugs close in. You're not sure what they're after — but one thing's clear: she's in danger.)"
        },
        [51004941] = {
          ContentFR = "Luna te fait une petite révérence, peut-être pour te remercier, puis se remet rapidement à ramasser les papiers.",
          DialogueId = 51004941,
          GUID = "7FAF7C84",
          NextDialogue = 51004942,
          Subtitle = "(Luna gives you a quick bow — perhaps a gesture of thanks — then hastily drops down to gather the remaining papers.)"
        },
        [51004942] = {
          ContentFR = "Ça va ? Que sont ces papiers ?",
          DialogueId = 51004942,
          GUID = "7FAF7C85",
          NextDialogue = 51004943,
          SpeakNpcId = 100001,
          Subtitle = "You all right? What are these papers?"
        },
        [51004943] = {
          ContentFR = "A... ouuuh !",
          DialogueId = 51004943,
          GUID = "7FAF7C86",
          NextDialogue = 51004944,
          SpeakNpcId = 700010,
          Subtitle = "Ah... u-uh...!"
        },
        [51004944] = {
          ContentFR = "Tu remarques que certains papiers portent le mot \"Ordonnance\"... Peut-être que cette femme est liée à <H>un indice que Margie t’a donné</> ?",
          DialogueId = 51004944,
          GUID = "7FAF7C87",
          NextOptions = {
            [1] = 510049011,
            [2] = 510049012
          },
          Subtitle = "(Your eyes flick over one of the sheets — you spot the word \"prescription.\" Could this woman be linked to one of the items Margie gave you?)",
          bForbidSkipOptions = true
        },
        [51004945] = {
          ContentFR = "Mm... mmm.",
          DialogueId = 51004945,
          GUID = "7FAF7C88",
          NextDialogue = 51004946,
          SpeakNpcId = 700010,
          Subtitle = "Mm... mmm."
        },
        [51004946] = {
          ContentFR = "Elle sourit doucement, comme pour te remercier.",
          DialogueId = 51004946,
          GUID = "7FAF7C89",
          NextDialogue = 51004947,
          SpeakNpcId = 700010,
          Subtitle = "(She gives a quiet nod and a faint smile — her way of saying thank you.)"
        },
        [51004947] = {
          ContentFR = "Je connaissais un médecin. Il n’est plus à Givrelac, mais je peux vérifier son ancien domicile. Peut-être y trouverons-nous un remède pour votre gorge.",
          DialogueId = 51004947,
          GUID = "7FAF7C8A",
          NextDialogue = 51004948,
          SpeakNpcId = 100001,
          Subtitle = "I knew a doctor. He's not in Icelake anymore, but I can check the place where he used to stay. There might be something there that could help your throat."
        },
        [51004948] = {
          ContentFR = "Mm...",
          DialogueId = 51004948,
          GUID = "7FAF7C8B",
          NextDialogue = 51004949,
          SpeakNpcId = 700010,
          Subtitle = "Mm..."
        },
        [51004949] = {
          ContentFR = "Luna baisse la tête, sachant que sa voix est probablement perdue. Mais en levant les yeux, une lueur d’espoir brille, comme pour dire : « Et si... ? »",
          DialogueId = 51004949,
          GUID = "7FAF7C8C",
          Subtitle = "(She lowers her head. She knows her voice may be gone for good — but when she looks up again, there's a flicker of hope in her eyes, as if to say: \"But what if...?\")"
        },
        [51004950] = {
          ContentFR = "Hngh... ouaaah !",
          DialogueId = 51004950,
          GUID = "7FAF7C8D",
          NextDialogue = 51004951,
          SpeakNpcId = 700010,
          Subtitle = "Hngh... wwryaa..."
        },
        [51004951] = {
          ContentFR = "Elle te regarde avec méfiance, secouant la tête en panique, comme pour dire « Je n’ai vraiment plus rien ! »",
          DialogueId = 51004951,
          GUID = "7FAF7C8E",
          NextDialogue = 51004952,
          SpeakNpcId = 700010,
          Subtitle = "(She stares at you warily, shaking her head in panic. You can almost hear the words she's unable to speak: \"I don't have anything left!\")"
        },
        [51004952] = {
          ContentFR = "Ne vous inquiétez pas. Cette fois, je suis là pour aider, pas pour vous prendre votre argent.",
          DialogueId = 51004952,
          GUID = "7FAF7C8F",
          NextDialogue = 51004953,
          SpeakNpcId = 100001,
          Subtitle = "Easy. I'm actually here to help this time. Didn't plan to just take your stuff and walk away for free."
        },
        [51004953] = {
          ContentFR = "Je connaissais un médecin. Il n’est plus à Givrelac, mais je peux vérifier son ancien domicile. Peut-être y trouverons-nous un remède pour votre gorge.",
          DialogueId = 51004953,
          GUID = "7FAF7C90",
          NextDialogue = 51004954,
          SpeakNpcId = 100001,
          Subtitle = "I knew a doctor. He's not in Icelake anymore, but I can check the place where he used to stay. There might be something there that could help your throat."
        },
        [51004954] = {
          ContentFR = "Luna semble encore hésitante, elle ne te fait pas pleinement confiance.",
          DialogueId = 51004954,
          GUID = "7FAF7C91",
          Subtitle = "(Doubt lingers in her eyes. She doesn't really trust you at the moment.)"
        },
        [51004955] = {
          ContentFR = "Sur une étagère :",
          DialogueId = 51004955,
          GUID = "7FAF7C92",
          Subtitle = "(On a bookshelf)"
        },
        [51004956] = {
          ContentFR = "À Givrelac, certains rhumes étranges frappent rapidement comme le vent d’hiver, disparaissant tout aussi vite, mais les enfants en souffrent toujours.\n\n<I>Soulagement Rapide : Remède contre le rhume</>",
          DialogueId = 51004956,
          Duration = 4,
          GUID = "7FAF7C93",
          IsBlack = 1,
          NextDialogue = 51004957,
          Subtitle = "(Icelake knows all too well the strange seasonal colds that sweep in like winter winds— \nstriking fast, and vanishing just as quickly. Even so, they're always hard on the little ones.\n\n—Rapid Relief: Cold Remedy)"
        },
        [51004957] = {
          ContentFR = "Ce n’est pas ça.",
          DialogueId = 51004957,
          Duration = 3,
          GUID = "7FAF7C94",
          SpeakNpcId = 100001,
          Subtitle = "Doesn't feel like the right one."
        },
        [51004958] = {
          ContentFR = "Sur une autre étagère :",
          DialogueId = 51004958,
          GUID = "7FAF7C95",
          Subtitle = "(On a bookshelf)"
        },
        [51004959] = {
          ContentFR = "Une étrange ordonnance, à l’origine un traitement contre la Dégradation qui a raté. Des tests ultérieurs ont révélé des effets surprenants sur certaines maladies chroniques.",
          DialogueId = 51004959,
          Duration = 4,
          GUID = "7FAF7C96",
          IsBlack = 1,
          NextDialogue = 51004960,
          Subtitle = "(A curious formula — originally a failed anti-Deterioration treatment. Later trials revealed unexpected effects on certain chronic conditions.)"
        },
        [51004960] = {
          ContentFR = "Ce n’est pas ça.",
          DialogueId = 51004960,
          Duration = 3,
          GUID = "7FAF7C97",
          SpeakNpcId = 100001,
          Subtitle = "Doesn't feel like the right one."
        },
        [51004961] = {
          ContentFR = "Par terre :",
          DialogueId = 51004961,
          GUID = "7FAF7C98",
          Subtitle = "(On the floor)"
        },
        [51004962] = {
          ContentFR = "Certains, par faim, ont mangé du Lotus d’hiver par erreur. Si le poison n’est pas trop fort, ce remède peut neutraliser les toxines.\n\n<I>Antidote au Lotus d’hiver</>",
          DialogueId = 51004962,
          Duration = 5,
          GUID = "7FAF7C99",
          IsBlack = 1,
          Subtitle = [[
(Some, driven by hunger, have mistaken Eclipta Grass for food.)
(If the poison hasn't set in too deep, this compound can help neutralise the toxins.)]]
        },
        [51004963] = {
          ContentFR = "Comment est-ce tombé par terre ? Cela pourrait aider Luna !",
          DialogueId = 51004963,
          Duration = 4,
          GUID = "7FAF7C9A",
          SpeakNpcId = 100001,
          Subtitle = "What's this doing on the floor? This might actually help Luna!"
        },
        [51004964] = {
          ContentFR = "Tu as obtenu une recette d’un remède qui pourrait aider avec la gorge de Luna.",
          DialogueId = 51004964,
          Duration = 3,
          GUID = "7FAF7C9B",
          Subtitle = "(You've obtained a remedy that might help with Luna's throat)"
        },
        [51004965] = {
          ContentFR = "Si un jour votre voix revient... que chanterez-vous ?",
          DialogueId = 51004965,
          GUID = "7FAF7C9C",
          NextDialogue = 51004966,
          SpeakNpcId = 100001,
          Subtitle = "If your voice came back... what would you want to sing?"
        },
        [51004966] = {
          ContentFR = "Luna baisse la tête, plongée dans une longue réflexion.",
          DialogueId = 51004966,
          GUID = "7FAF7C9D",
          NextDialogue = 51004967,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "(She lowers her head, falling into deep thought.)"
        },
        [51004967] = {
          ContentFR = "« Je chanterais ce que j’ai dans le cœur, même si cela me coûte de nouveau ma voix. »",
          DialogueId = 51004967,
          GUID = "7FAF7C9E",
          NextDialogue = 51004968,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"I'd sing what's in my heart — even if it costs me my voice all over again.\""
        },
        [51004968] = {
          ContentFR = "Tu réalises que si ce remède fonctionne, il pourrait ramener la voix de la ménestrelle... et avec elle, le danger qui l’a privée de sa voix.",
          DialogueId = 51004968,
          GUID = "7FAF7C9F",
          NextOptions = {
            [1] = 51004969,
            [2] = 51004970
          },
          Subtitle = "(It dawns on you: if this remedy really works, it could bring back a bard's voice — and with it, the very danger that stole it away.)"
        },
        [51004969] = {
          ContentFR = "<I>Donner le remède</>",
          DialogueId = 51004969,
          GUID = "7FAF7CA0",
          NextDialogue = 51004972,
          Subtitle = "Hand her the remedy."
        },
        [51004970] = {
          ContentFR = "<I>Garder le remède</>",
          DialogueId = 51004970,
          GUID = "7FAF7CA1",
          NextDialogue = 51004979,
          Subtitle = "Keep it to yourself."
        }
      }
    end
  },
