        [51006901] = {
          Camera = "475.811523,676.893555,129.602295,0.000004,0.0,-119.200165,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Le guichet du train attire ton regard : tu te rappelles des objets confiés par Margie, l’un d’eux était lié aux billets de train.",
          DialogueId = 51006901,
          FinalCamera = "475.811523,694.0,129.602295,0.000004,0.0,-119.200157,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB0BFB2",
          LookAt = {
            [1] = "700147:n(700148)",
            [2] = "700148:n(700147)"
          },
          NextDialogue = 51006902,
          Subtitle = "(The train ticket booth catches your eye, reminding you of an item you got from Margie — an item related to \"tickets.\")",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 5
        },
        [51006902] = {
          Camera = "475.811523,694.0,129.602295,0.000004,0.0,-119.200157,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas de chance, un Charon aux habits étrangers est en pleine dispute avec la guichetière.",
          DialogueId = 51006902,
          GUID = "7FB0BFDC",
          NextDialogue = 51006903,
          Subtitle = "(You've come at a bad time — a foreign-looking Charon is in a heated argument with the ticket seller.)",
          TalkActionId = {
            [1] = "700147:Confident_Start",
            [2] = "100001:Think_End"
          }
        },
        [51006903] = {
          Camera = "50.741211,214.74707,179.342529,0.000012,-8.799981,-110.198242,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas d’argent ? Dégage !",
          DialogueId = 51006903,
          GUID = "7FB0C006",
          NextDialogue = 51006904,
          SpeakNpcId = 700147,
          Subtitle = "Get lost if you have no money!"
        },
        [51006904] = {
          Camera = "70.262695,-223.553711,140.896484,0.00001,0.0,109.401634,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bon sang ! J’ai juste posé une question ! Pourquoi tant de colère ?",
          DialogueId = 51006904,
          GUID = "7FB0C030",
          NextDialogue = 51006905,
          SpeakNpcId = 700148,
          Subtitle = "Goodness, I just asked a simple question! Why so angry!?",
          TalkActionId = {
            [1] = "700147:Confident_End",
            [2] = "700148:Shock_Start"
          }
        },
        [51006905] = {
          Camera = "50.741211,214.74707,179.342529,0.000012,-8.799981,-110.198242,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah, d’accord... Monsieur \"accent bizarre\", après que je t’ai poliment donné le prix du billet, tu comptes faire quoi ? Fouiller tes poches vides et me donner des ordres ?",
          DialogueId = 51006905,
          GUID = "7FB0C05A",
          NextDialogue = 51006906,
          SpeakNpcId = 700147,
          Subtitle = "Alright, Mr Quirky Accent — after I've politely told you the fare, what's your plan? To fumble through those empty pockets and then boss me around?",
          TalkActionId = {
            [1] = "700147:Talk03_Start",
            [2] = "700148:Shock_End"
          }
        },
        [51006906] = {
          Camera = "33.833008,-38.410156,159.227783,0.00001,0.999987,101.202133,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quoi ? Comment tu sais que—",
          DialogueId = 51006906,
          GUID = "7FB0C084",
          NextDialogue = 51006907,
          SpeakNpcId = 700148,
          Subtitle = "What you say? How you know me no—",
          TalkActionId = {
            [1] = "700148:Explain01_Start",
            [2] = "700147:Talk03_End"
          }
        },
        [51006907] = {
          Camera = "8.34668,69.227539,155.484863,0.000015,-7.799837,-93.597458,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Savoir quoi ? Comme si un Charon pouvait avoir plus de cinq pièces ! Ici, c’est réservé aux riches, aux nobles et aux grands fonctionnaires. Pas aux clochards.",
          DialogueId = 51006907,
          GUID = "7FB0C0AE",
          NextDialogue = 51006908,
          SpeakNpcId = 700147,
          Subtitle = "What's there to know? Like a Charon would have more than five coins in their pocket! This place is reserved for the rich and the powerful — not penniless wanderers like you!",
          TalkActionId = {
            [1] = "700148:Explain01_End",
            [2] = "700147:Confident_Start"
          }
        },
        [51006908] = {
          Camera = "70.262695,-223.553711,140.896484,0.00001,0.0,109.401634,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Le marchand bredouille un peu dans sa langue maternelle, mais la guichetière lui lance un regard dédaigneux et l’ignore. Vexé, il s’éloigne.",
          DialogueId = 51006908,
          GUID = "7FB0C0D8",
          Scripts = "PARA{MoveTo{_delay{2},ActorId{700148},MoveSpeed{75},TargetPoint{\"QuestPoint_20021901Move\"}},CameraMoveTo{_delay{2},TargetPosition{\"479.638672,673.591797,127.602295,0.000004,-0.600005,-125.400406,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}}",
          Subtitle = "(The foreigner fumbles a retort in his mother tongue, but the ticket seller, not understanding a word, merely gives him a scornful glance before turning away. The man leaves, crestfallen.)"
        },
        [51006921] = {
          ContentFR = "Tiens, tiens... Regardez-moi ça. La peau bien propre, le manteau bien repassé. Qu’est-ce que tu viens faire à fouiller les poubelles avec nous ?",
          DialogueId = 51006921,
          GUID = "7FB0C0D9",
          NextOptions = {
            [1] = 51006922,
            [2] = 51006923
          },
          SpeakNpcId = 700230,
          Subtitle = "Well, well — look at you. Clean skin, tidy coat. What're you doing digging through trash with the likes of us?"
        },
        [51006922] = {
          ContentFR = "<I>Je n’ai encore rien touché !</>",
          DialogueId = 51006922,
          GUID = "7FB0C0DA",
          NextDialogue = 51006924,
          Subtitle = "I haven't even touched anything!"
        },
        [51006923] = {
          ContentFR = "<I>Je n’ai pas vraiment le goût des poubelles, merci bien.</>",
          DialogueId = 51006923,
          GUID = "7FB0C0DB",
          NextDialogue = 51006924,
          Subtitle = "Bin diving's not really my thing, thanks."
        },
        [51006924] = {
          ContentFR = "Fais pas {性别:l’innocent, gamin|l’innocente, gamine}. Je t’ai vu.",
          DialogueId = 51006924,
          GUID = "7FB0C0DC",
          NextDialogue = 51006925,
          SpeakNpcId = 700230,
          Subtitle = "Don't play dumb, kid."
        },
        [51006925] = {
          ContentFR = "Hier, y avait une femme en uniforme qui est venue par ici, les larmes aux yeux. Elle a balancé une boîte dans la benne. Une vieille qui fouillait gentiment l’a interrogée, et la furie l’a incendiée, en lui disant de se mêler de ses affaires.",
          DialogueId = 51006925,
          GUID = "7FB0C0DD",
          NextDialogue = 51006926,
          SpeakNpcId = 700230,
          Subtitle = "Yesterday, some woman in uniform came by — sobbing her eyes out. She chucked a box right into the bin. Some nice old lady picking through scraps tried to ask if she was okay... got yelled at, real nasty. Told her to shove off and mind her own business."
        },
        [51006926] = {
          ContentFR = "Et devine quoi ? La boîte que t’as dans les mains, c’est celle-là. Alors, toujours {性别:sûr|sûre} de pas l’avoir pêchée dans la poubelle ?",
          DialogueId = 51006926,
          GUID = "7FB0C0DE",
          NextDialogue = 51006927,
          SpeakNpcId = 700230,
          Subtitle = "And that box you're holding? Yeah, that one. So... still wanna say you didn't dig through the bin?"
        },
        [51006927] = {
          ContentFR = "Ce n’est pas moi... enfin peu importe, pas envie d’entrer dans les détails. Merci de m’avoir donné un indice sur sa propriétaire.",
          DialogueId = 51006927,
          GUID = "7FB0C0DF",
          NextDialogue = 51006928,
          SpeakNpcId = 100001,
          Subtitle = "It wasn't— ...you know what, forget it. Thanks for the info anyway."
        },
        [51006928] = {
          ContentFR = "<I>Une femme en uniforme... Est-ce que ça aurait un lien avec les objets de Margie ?</>",
          DialogueId = 51006928,
          GUID = "7FB0C0E0",
          SpeakNpcId = 100001,
          Subtitle = "(A woman in uniform... Could she have something to do with one of the items Margie gave me?)"
        },
        [51006931] = {
          ContentFR = "Après un an et huit mois travaillant en tant que guichetière, j’ai enfin réuni assez d’argent pour acheter un billet jusqu’à Rougerive, dans le sud.",
          DialogueId = 51006931,
          GUID = "7FB0C49E",
          NextDialogue = 51006932,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          Subtitle = "One year and eight months into the job, I finally saved enough for a single fare to Scarletriver — one of the big southern cities."
        },
        [51006932] = {
          ContentFR = "C’est une victoire, non ? Tu avances vers ton rêve.",
          DialogueId = 51006932,
          GUID = "7FB0C4C8",
          NextDialogue = 51006933,
          SpeakNpcId = 100001,
          Subtitle = "Isn't that exciting? You're getting closer to your dream."
        },
        [51006933] = {
          ContentFR = "Avancer ? Tu oublies les <H>taxes de surveillance</> imposées aux Charons ? Le billet, c’était rien comparé à ça. Pour espérer rejoindre le sud, il m’aurait fallu cinq ans d’économie... sans manger ni boire. Et j’ai une famille à nourrir.",
          DialogueId = 51006933,
          GUID = "7FB0C4F2",
          NextDialogue = 51007147,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          Subtitle = "Closer? Have you forgotten about the supervision levies they slap on Charons? The ticket itself is nothing compared to the fees we have to pay just to be allowed to buy one! To afford a ticket to where he went, I'd have to starve myself for five whole years. And even if I managed that... I still have a family to feed."
        },
        [51007001] = {
          ContentFR = "Toi, venu pour infos sur train ? Attention, méchante guichetière, garde amère !",
          DialogueId = 51007001,
          GUID = "7FB0D01A",
          LookAt = {
            [1] = "700149:n(0)"
          },
          NextOptions = {
            [1] = 510070011,
            [2] = 510070012
          },
          SpeakNpcId = 700149,
          Subtitle = "You here, ask about trains? Careful, mean gatekeeper girl here!",
          TurnTo = {
            [1] = "700149:n(0)"
          },
          bForbidSkipOptions = true
        }
      }
    end
  },
