        },
        [51007102] = {
          ContentFR = "Encore {性别:un Charon fauché|une Charon fauchée} ?",
          DialogueId = 51007102,
          GUID = "7FB0E0AC",
          LookAt = {
            [1] = "700147:n(0)",
            [2] = "700148:n(700147)"
          },
          NextDialogue = 51007103,
          SpeakNpcId = 700147,
          Subtitle = "Who's this? Another broke Charon?",
          TalkActionId = {
            [1] = "700147:Talk01_Start"
          },
          TurnTo = {
            [1] = "700147:n(0)"
          }
        },
        [51007103] = {
          ContentFR = "Surveille ton langage. Je ne suis pas {性别:un \"fauché\"|une \"fauchée\"}. Tu connais la Maison d’Hypnos ? Eh bien, c’est moi qui loue une de ses propriétés.",
          DialogueId = 51007103,
          GUID = "7FB0E0D6",
          NextDialogue = 51007104,
          SpeakNpcId = 100001,
          Subtitle = "Mind your tone. I'm not some broke Charon. Heard of the owner of the Hypnos' House? I'm leasing another property of his.",
          TalkActionId = {
            [1] = "700147:Talk01_End"
          }
        },
        [51007104] = {
          ContentFR = "Quoi ? Tout le monde sait que ce vieux grincheux déteste les étrangers. Tu devrais faire quelques recherches avant d’essayer d’impressionner des gens avec ton mensonge. Allez, enferme-toi dans ton \"manoir\" et épargne-nous tes délires.",
          DialogueId = 51007104,
          GUID = "7FB0E100",
          NextDialogue = 51007105,
          SpeakNpcId = 700147,
          Subtitle = "Hah? Everyone knows that grump hates outsiders. Do some research before you try to impress people with a lie. Since you're so delusional, you should lock yourself up in that \"mansion\" and stay out of sight!",
          TalkActionId = {
            [1] = "700147:Confident_Start"
          }
        },
        [51007105] = {
          ContentFR = "C’est trop ! Dis-lui, fais-la taire !",
          DialogueId = 51007105,
          GUID = "7FB0E12A",
          LookAt = {
            [1] = "700147:n(700148)"
          },
          NextOptions = {
            [1] = 51007106
          },
          SpeakNpcId = 700148,
          Subtitle = "That's mean! Please, speak, make her stop mean talk!",
          TalkActionId = {
            [1] = "700147:Confident_End",
            [2] = "700148:Talk03_Start"
          }
        },
        [51007106] = {
          ContentFR = "<I>Poser la boîte d’étoiles en papier donnée par Margie sur le comptoir</>",
          DialogueId = 51007106,
          GUID = "7FB0E154",
          NextDialogue = 51007107,
          Subtitle = "(Place the box of paper stars you got from Margie on the desk.)"
        },
        [51007107] = {
          ContentFR = "En voyant les étoiles, Jessica a une seconde d’hésitation, mais se reprend vite et t’adresse un regard dédaigneux.",
          DialogueId = 51007107,
          GUID = "7FB0E17E",
          NextDialogue = 51007108,
          Subtitle = "(At the sight of the paper stars, the ticket seller's expression softens for a moment, but she quickly resumes her earlier demeanour, eyeing you with disdain.)",
          TalkActionId = {
            [1] = "700148:Talk03_End"
          }
        },
        [51007108] = {
          ContentFR = "Et c’est quoi, ça ? De la camelote sortie d’une poubelle ? Tu crois que je suis aussi un centre de recyclage ? Dégage ça d’ici !",
          DialogueId = 51007108,
          GUID = "7FB0E1A8",
          LookAt = {
            [1] = "700147:n(0)"
          },
          NextDialogue = 51007109,
          SpeakNpcId = 700147,
          Subtitle = "Why did you put this rubbish on my desk? This isn't a recycling centre! Get them outta here!",
          TalkActionId = {
            [1] = "700147:Angry01_Start"
          }
        },
        [51007109] = {
          ContentFR = "Pourquoi \"camelote\" ? Moi, j’y vois un travail minutieux, plein de sincérité et de sentiment.",
          DialogueId = 51007109,
          GUID = "7FB0E1D2",
          NextDialogue = 51007110,
          SpeakNpcId = 100001,
          Subtitle = "Why call them rubbish? To me, these are delicate handicrafts. You can tell the maker must've put a lot of effort and feelings into them.",
          TalkActionId = {
            [1] = "700147:Angry01_End"
          }
        },
        [51007110] = {
          ContentFR = "Chez nous aussi, à Huaxu, on plie étoiles de papier. On dit : plus tu en fais, plus tes rêves se réalisent.",
          DialogueId = 51007110,
          GUID = "7FB0E1FC",
          LookAt = {
            [1] = "700148:n(0)"
          },
          NextDialogue = 51007111,
          SpeakNpcId = 700148,
          Subtitle = "Paper stars, Huaxu tradition too. People say, make many, dreams come true.",
          TalkActionId = {
            [1] = "700148:Think_Start"
          }
        },
        [51007111] = {
          ContentFR = "Je comprends mieux... J’ai voulu en déplier une, pour comprendre le pliage, et j’ai trouvé des mots écrits à l’intérieur.",
          DialogueId = 51007111,
          GUID = "7FB0E226",
          NextDialogue = 51007112,
          SpeakNpcId = 100001,
          Subtitle = "That explains it... I was curious about how they were made, so I unfolded one and found something written inside.",
          TalkActionId = {
            [1] = "700148:Think_End"
          }
        },
        [51007112] = {
          ContentFR = "C’était... comme un vœu ?",
