          SpeakNpcId = 700147,
          Subtitle = "You... you opened them!?",
          TalkActionId = {
            [1] = "700147:Sigh_Start"
          }
        },
        [51007114] = {
          ContentFR = "Juste un. J’ai vu que c’était plié dans un billet de train, avec un message lié au voyage. Alors je suis venu ici, pensant retrouver le propriétaire.",
          DialogueId = 51007114,
          GUID = "7FB0E2A4",
          NextDialogue = 51007115,
