          GUID = "7FB1367A",
          NextDialogue = 51007626,
          SpeakNpcId = 700204,
          Subtitle = "Once, right here, I spotted this huge, impressive-looking rat. It reminded me of the \"Rat Warrior\" from those old legends."
        },
        [51007626] = {
