          DialogueId = 51007626,
          GUID = "7FB136A4",
          NextDialogue = 51007627,
          SpeakNpcId = 700204,
          Subtitle = "The Rat Warrior was born a scrawny little mouse, but he overcame every hardship, fought bravely, and became a hero who protected his kind!",
          TalkActionId = {
            [1] = "700204:Angry01_Start"
          }
        },
        [51007627] = {
          ContentFR = "Le rat que j’ai vu avait beaucoup de cicatrices, preuve de ses combats. Et il portait une petite bouteille bizarre sur le dos... peut-être un équipement spécial ?",
          DialogueId = 51007627,
