          SpeakNpcId = 700204,
          Subtitle = "The rat I saw had tons of scars — proof of all its battles, I bet. And it was carrying this weird little bottle on its back... maybe it was some kind of special gear?"
        },
        [51007628] = {
          ContentFR = "<I>Peut-être un outil pour des expériences.</>",
          DialogueId = 51007628,
          GUID = "7FB136F8",
          ImprPlusId = 1003,
          NextDialogue = 51007629,
          Subtitle = "Maybe it was a sample bottle or something used for experiments."
