        },
        [51007683] = {
          ContentFR = "Ouah, tu connais plein de gens... Comment tu fais pour communiquer ? Apprends-moi !",
          DialogueId = 51007683,
          GUID = "7FB13FFE",
          NextOptions = {
            [1] = 51007684,
            [2] = 51007686
          },
          SpeakNpcId = 700204,
          Subtitle = "Whoa! You know so many people! How do you do that!? Can you teach me how to talk to people better?"
        },
        [51007684] = {
          ContentFR = "<I>Parle à beaucoup de personnes différentes. Tu t’amélioreras avec la pratique.</>",
          DialogueId = 51007684,
          GUID = "7FB14028",
          NextDialogue = 51007685,
          Subtitle = "Talk to lots of different people. You'll get better with practice."
        },
        [51007685] = {
          ContentFR = "Theo note dans son carnet : « Le secret de communication de {$XiAoTag(Value_1,Value_2)$|性别(Purginou|Purginette):Sibylle} : parler avec différentes personnes pour accumuler de l’expérience. »",
          DialogueId = 51007685,
          GUID = "7FB14052",
          NextDialogue = 51007688,
          Subtitle = "(Theo scribbles in his notebook: \"{性别:Mr|Miss} {$XiAoTag(Value_1,Value_2)$|Purr:Sibylle}'s communication tip: Talk to lots of different people and learn from each conversation.\")"
        },
        [51007686] = {
          ContentFR = "<I>Quand les mots ne suffisent pas, utiliser la force.</>",
          DialogueId = 51007686,
          GUID = "7FB1407C",
          NextDialogue = 51007687,
          Subtitle = "When words don't cut it, use your fists."
        },
        [51007687] = {
          ContentFR = "Theo note : « Le secret de communication de {$XiAoTag(Value_1,Value_2)$|性别(Purginou|Purginette):Sibylle} : quand les mots ne suffisent pas, utiliser la force. Note : cette méthode n’est probablement pas pour moi. »",
          DialogueId = 51007687,
          GUID = "7FB140A6",
          NextDialogue = 51007688,
          Subtitle = "(Theo scribbles in his notebook: \"{性别:Mr|Miss} {$XiAoTag(Value_1,Value_2)$|Purr:Sibylle}'s communication tip: When words don't cut it, use fists. Note: Probably not a method that suits me.\")"
        },
        [51007688] = {
          ContentFR = "Bien, j’ai noté !",
          DialogueId = 51007688,
          GUID = "7FB140D0",
          NextDialogue = 51007689,
          SpeakNpcId = 700204,
          Subtitle = "Got it... I've made notes!",
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007689] = {
          ContentFR = "Des pas précipités résonnent, une femme bien habillée arrive, furieuse.",
          DialogueId = 51007689,
          GUID = "7FB140FA",
          IsBlack = 1,
          Subtitle = "(Suddenly, you hear hurried footsteps — a well-dressed woman storms over, anger flashing across her face.)"
        },
        [51007690] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentFR = "Theo ! Où étais-tu encore ? Et regarde-toi, tout sale !",
          DefaultLookAt = "1.0",
          DialogueId = 51007690,
          GUID = "7FB14124",
          NextDialogue = 51007691,
          SpeakNpcId = 700205,
          SpeakNpcName = "UI_CMNpc_Name_DeTiWoman",
          Subtitle = "Theo! Where have you been this time!? And just look at you — you're filthy!",
          TurnTo = {
            [1] = "700204:n(700205)",
            [2] = "100001:n(700205)",
            [3] = "700205:n(700204)"
          }
        },
        [51007691] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentFR = "Maman... on observait juste les rats dans les égouts.",
          DefaultLookAt = "1.0",
          DialogueId = 51007691,
          GUID = "7FB1414E",
          NextDialogue = 51007692,
          SpeakNpcId = 700204,
          Subtitle = "Oh, hey, mum...! We were just studying the rats in the sewers.",
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007692] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentFR = "Quoi ? Ces créatures dégoûtantes ? Pourquoi tu perds ton temps à les observer ?",
          DefaultLookAt = "1.0",
          DialogueId = 51007692,
          GUID = "7FB14178",
          NextDialogue = 51007693,
          SpeakNpcId = 700205,
          Subtitle = "WHAT!? Why would you waste your time on disgusting creatures like that!?"
        },
        [51007693] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentFR = "Toujours à faire des bêtises, mais quand il s’agit de s’asseoir en classe et d’apprendre correctement ? Aucun intérêt. Cet enfant va me rendre folle...",
          DefaultLookAt = "1.0",
          DialogueId = 51007693,
          GUID = "7FB141A2",
          NextDialogue = 51007694,
          SpeakNpcId = 700205,
          Subtitle = "Always fooling around with weird nonsense — but when it comes to sitting in class and learning properly? No interest at all. This kid's going to be the death of me...",
          TalkActionId = {
            [1] = "700205:Sigh_Start"
          }
        },
        [51007694] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentFR = "Après sa réprimande, elle te remarque enfin et tire Theo derrière elle.",
          DefaultLookAt = "1.0",
          DialogueId = 51007694,
          GUID = "7FB141CC",
          NextDialogue = 51007695,
          Subtitle = "(After giving her boy a thorough scolding, the woman finally notices you. Her eyes narrow, and she quickly yanks Theo behind her, shielding him protectively.)",
          TurnTo = {
            [1] = "700204:n(100001)",
            [2] = "700205:n(100001)"
          }
        },
        [51007695] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentFR = "Et toi, qui es-tu ? C’est toi qui remplis la tête de mon garçon de bêtises, n’est-ce pas ?",
          DefaultLookAt = "1.0",
          DialogueId = 51007695,
          GUID = "7FB141F6",
          NextOptions = {
            [1] = 51007696,
            [2] = 51007698
          },
          SpeakNpcId = 700205,
          Subtitle = "And who are you? You're the one who's been filling my boy's head with nonsense, aren't you?"
        },
        [51007696] = {
          ContentFR = "<I>S’il vous plaît, ne faites pas d’accusations sans preuves.</>",
          DialogueId = 51007696,
          GUID = "7FB14220",
          ImprPlusId = 1002,
          NextDialogue = 51007697,
          Subtitle = "Please don't throw accusations around without any proof."
        },
        [51007697] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentFR = "Ah ! Et depuis quand les Charons méritent-ils le bénéfice du doute ?",
          DefaultLookAt = "1.0",
          DialogueId = 51007697,
          GUID = "7FB1424A",
          NextDialogue = 51007700,
          SpeakNpcId = 700205,
          Subtitle = "Hah! Since when do Charons deserve the benefit of the doubt?"
        },
        [51007698] = {
          ContentFR = "<I>Oui, c’est moi. Bravo, vous avez deviné !</>",
          DialogueId = 51007698,
          GUID = "7FB14274",
          ImprPlusId = 1005,
          NextDialogue = 51007699,
          Subtitle = "Bingo! Yeah, it's me. You're welcome."
        },
        [51007699] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentFR = "Toi... !",
          DefaultLookAt = "1.0",
          DialogueId = 51007699,
          GUID = "7FB1429E",
          NextDialogue = 51007700,
          SpeakNpcId = 700205,
          Subtitle = "You...!"
        },
        [51007700] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentFR = "Theo... combien de fois dois-je te dire de ne pas traîner avec des Charons ! Rien de bon ne vient jamais d’eux !",
          DefaultLookAt = "1.0",
          DialogueId = 51007700,
          GUID = "7FB142C8",
          NextDialogue = 51007701,
          SpeakNpcId = 700205,
          Subtitle = "Theo, how many times have I told you? Stay away from Charons! Nothing good ever comes from them!",
          TurnTo = {
            [1] = "700204:n(700205)",
            [2] = "100001:n(700205)",
            [3] = "700205:n(700204)"
          }
        },
        [51007701] = {
          ContentFR = "Elle arrache Theo et s’éloigne. Avant de disparaître, Theo se retourne et mime avec ses lèvres « À la prochaine » et te lance un petit paquet.",
          DialogueId = 51007701,
          GUID = "7FB142F2",
          IsBlack = 1,
          Subtitle = "(She grabs Theo by the arm and drags him away. But just before they disappear around the corner, Theo looks back at you — he mouths, \"See you next time,\" and tosses a small bundle your way.)"
        },
        [51007702] = {
          ContentFR = "{$XiAoTag(Value_1,Value_2)$|性别(Purginou|Purginette):Sibylle}, {$XiAoTag(Value_1,Value_2)$|性别(Purginou|Purginette):Sibylle}, je suis là !",
          DialogueId = 51007702,
          GUID = "7FB1431C",
          NextDialogue = 51007703,
          SpeakNpcId = 700204,
          Subtitle = "{性别:Mr|Miss} {$XiAoTag(Value_1,Value_2)$|Purr:Sibylle}, {性别:Mr|Miss} {$XiAoTag(Value_1,Value_2)$|Purr:Sibylle}, over here!"
        },
        [51007703] = {
          ContentFR = "Le garçon se cache dans l’ombre du bâtiment et te fait signe avec excitation.",
          DialogueId = 51007703,
          GUID = "7FB14346",
          NextDialogue = 51007704,
          Subtitle = "(The boy waves at you excitedly from the shadows of a nearby building.)"
        },
        [51007704] = {
          ContentFR = "On se revoit enfin !",
          DialogueId = 51007704,
          GUID = "7FB14370",
          NextDialogue = 51007705,
          SpeakNpcId = 700204,
          Subtitle = "Hey, we meet again!"
        },
        [51007705] = {
          ContentFR = "Devine quoi ? J’ai un peu enquêté après notre dernière rencontre, ton vrai nom est bien {nickname}, n’est-ce pas ? Vraiment... mentir à un enfant, c’est pas bien !",
          DialogueId = 51007705,
          GUID = "7FB1439A",
          NextDialogue = 51007706,
          SpeakNpcId = 700204,
          Subtitle = "Guess what? I did a bit of digging after we parted ways — your real name is , isn't it? Seriously! Lying to a kid like me — shame on you!",
          TalkActionId = {
            [1] = "700204:Talk03_Start"
          }
        },
        [51007706] = {
          ContentFR = "Désolé pour la dernière fois, ma maman a juste... très peur des Charons.",
          DialogueId = 51007706,
          GUID = "7FB143C4",
          NextDialogue = 51007707,
          SpeakNpcId = 700204,
          Subtitle = "Anyway... sorry about last time. My mum's just... really scared of Charons.",
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007707] = {
          ContentFR = "Quand nous sommes rentrés, elle n’arrêtait pas de dire des choses comme « Les Charons sont paresseux, des criminels de naissance, dangereux... »",
          DialogueId = 51007707,
          GUID = "7FB143EE",
          NextDialogue = 51007708,
          SpeakNpcId = 700204,
          Subtitle = "When we got home, she wouldn't stop going on and on: \"Charons are lazy by nature,\" \"born criminals,\" \"dangerous and untrustworthy\"..."
        },
        [51007708] = {
          ContentFR = "Les autres adultes disent à peu près la même chose. Mais plus j’y pense, plus ça me paraît bizarre !",
          DialogueId = 51007708,
          GUID = "7FB14418",
          NextDialogue = 51007709,
          SpeakNpcId = 700204,
          Subtitle = "Most grown-ups say the same stuff. But... the more I thought about it, the less it made sense!",
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007709] = {
          ContentFR = "Je veux vraiment mieux comprendre les Charons... mais soit je deviens trop nerveux pour leur parler, soit ils ne veulent tout simplement pas me parler. Alors... pourrais-tu m’en dire plus sur eux ?",
          DialogueId = 51007709,
          GUID = "7FB14442",
          NextDialogue = 51007710,
          SpeakNpcId = 700204,
          Subtitle = "I really want to understand Charons better... but either I get too nervous to talk to them, or they just don't want to talk to me. So... could you tell me more about them?"
        },
        [51007710] = {
          ContentFR = "Que dirais-tu que je te montre ? J’ai un appareil photo. Tu peux prendre des photos pour y repenser et y réfléchir plus tard.",
          DialogueId = 51007710,
          GUID = "7FB1446C",
          NextDialogue = 51007711,
          SpeakNpcId = 100001,
          Subtitle = "How about I show you? I've got a camera. You can take some photos to look back on and think about later.",
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007711] = {
          ContentFR = "Vraiment ? Merci !",
          DialogueId = 51007711,
          GUID = "7FB14496",
          SpeakNpcId = 700204,
          Subtitle = "Really? Thank you so much!",
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007712] = {
          Camera = "-329.898193,-397.409424,278.790771,0.000011,-19.79974,48.99963,22.97237,100000.0,false,Manual,22.0",
          ContentFR = "Regarde ces petits étals usés... ils s’installent avant l’aube tous les jours. C’est ainsi que la plupart des Charons gagnent leur vie. Si tu apprends à les connaître, ils pourraient même te faire une petite réduction.",
          DialogueId = 51007712,
          GUID = "7FB144C0",
          NextDialogue = 51007713,
          SpeakNpcId = 100001,
          Subtitle = "See these worn-out little stalls? They're set up before dawn every single day. That's how most Charons make a living. If you get to know them, they might even give you a little discount."
        },
        [51007713] = {
          Camera = "-329.898193,-397.409424,278.790771,0.000011,-19.79974,48.99963,22.97237,100000.0,false,Manual,22.0",
          ContentFR = "Tout le monde... semble très fatigué et travaille dur...",
          DialogueId = 51007713,
          GUID = "7FB144EA",
          SpeakNpcId = 700204,
          Subtitle = "They look... tired. And everyone seems to be working really hard..."
        },
        [51007714] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentFR = "Voici où vivent la plupart des Charons à Givrelac.",
          DialogueId = 51007714,
          GUID = "7FB14514",
          NextDialogue = 51007715,
          SpeakNpcId = 100001,
          Subtitle = "This is where most of the Charons in Icelake live."
        },
        [51007715] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentFR = "Hmm... les maisons sont vraiment délabrées... Ah ! C’est le vieux monsieur grincheux, il aide son voisin à réparer le toit ! Et ces enfants jouent aux mêmes jeux que nous jouons dans la cité intérieure !",
          DialogueId = 51007715,
          GUID = "7FB1453E",
          NextDialogue = 51007716,
          SpeakNpcId = 700204,
          Subtitle = "Hmm... the houses look really run-down... Ah! I've seen that man before — the grumpy-looking one helping his neighbour fix the roof! And those kids — they're playing the exact same games we play back in the inner city!"
        },
        [51007716] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentFR = "Je comprends maintenant... ce n’est pas comme ce que dit maman. Certes, certains Charons sont rudes ou étranges... mais chez les Solariens, il y a aussi des gens comme ça.",
          DialogueId = 51007716,
          GUID = "7FB14568",
          NextDialogue = 51007717,
          SpeakNpcId = 700204,
          Subtitle = "I get it now... It's not like what Mum says at all. Sure, some Charons are rude or mean... but we've got plenty of Solas like that too."
        },
        [51007717] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentFR = "À part les cornes sur la tête... je ne vois pas de grande différence entre les Charons et Solariens.",
          DialogueId = 51007717,
          GUID = "7FB14592",
          NextDialogue = 51007718,
          SpeakNpcId = 700204,
          Subtitle = "Aside from the horns... I don't really see much difference between Charons and Solas at all.",
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007718] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentFR = "Quand on regarde bien, ça se voit tout de suite... Alors pourquoi les gens s’accrochent-ils à des idées fausses, même quand la vérité est sous leurs yeux ?",
          DialogueId = 51007718,
          GUID = "7FB145BC",
          NextOptions = {
            [1] = 51007719,
            [2] = 51007720
          },
          SpeakNpcId = 700204,
          Subtitle = "It's so obvious once you take a little time to actually observe... So why do people stick to the wrong ideas, even when the truth is right in front of them?",
          TalkActionId = {
            [1] = "700204:Think_Start"
          }
        },
        [51007719] = {
          ContentFR = "<I>Parce que le préjugé est souvent plus fort que la vérité.</>",
          DialogueId = 51007719,
          GUID = "7FB145E6",
          NextDialogue = 51007721,
          Subtitle = "Because prejudice is stronger than truth."
        },
        [51007720] = {
          ContentFR = "<I>Peut-être qu’ils choisissent simplement de fermer les yeux.</>",
          DialogueId = 51007720,
          GUID = "7FB14610",
          NextDialogue = 51007721,
          Subtitle = "Maybe they choose to turn a blind eye to it."
        },
        [51007721] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentFR = "Vraiment ? C’est compliqué... Il y a des problèmes dans le monde que même la recherche ne peut résoudre...",
          DialogueId = 51007721,
          GUID = "7FB1463A",
          NextDialogue = 51007722,
          SpeakNpcId = 700204,
          Subtitle = "Hmm... is that so...? Wow... the world's even more complicated than I thought. I guess... there are some problems even research can't solve..."
        },
        [51007722] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentFR = "Bon, oublions ça pour l’instant. Avec l’appareil photo, allons prendre des photos de la jolie maison au nord, la Maison d’Hypnos ! Je t’attends là-bas !",
          DialogueId = 51007722,
          GUID = "7FB14664",
          SpeakNpcId = 700204,
          Subtitle = "...Well, I'll think about all that later. Now — since you've brought your camera, let's go snap some photos of that pretty house up north too. Uh, what was it called again... Hypnos' House? Yeah! See you there!",
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007723] = {
          ContentFR = "Tu es là ! Héhé, en fait j’ai déjà observé discrètement cette maison auparavant, il y avait des jeunes Charons dedans. Après tout ce que j’ai appris aujourd’hui... je veux vraiment leur parler !",
          DialogueId = 51007723,
          GUID = "7FB1468E",
          NextDialogue = 51007724,
          SpeakNpcId = 700204,
          Subtitle = "Hey, you made it~! Hehe, I've peeked in before — the people living here were all young Charons — not much older than me. After everything I learned today... I... I really want to talk to them!"
        },
        [51007724] = {
          ContentFR = "{nickname}, tu viens avec moi ?",
          DialogueId = 51007724,
          GUID = "7FB146B8",
          NextDialogue = 51007725,
          SpeakNpcId = 700204,
          Subtitle = ", would you come with me?"
        },
        [51007725] = {
          ContentFR = "...",
          DialogueId = 51007725,
          GUID = "7FB146E2",
          NextOptions = {
            [1] = 51007726,
            [2] = 51007727
          },
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [51007726] = {
          ContentFR = "<I>Dire la vérité</>",
          DialogueId = 51007726,
          GUID = "7FB1470C",
          ImprPlusId = 1002,
          NextDialogue = 51007728,
          Subtitle = "(Tell him the truth)"
        },
        [51007727] = {
          ContentFR = "<I>Hésiter à dire la vérité</>",
          DialogueId = 51007727,
          GUID = "7FB14736",
          ImprPlusId = 1004,
          NextDialogue = 51007728,
          Subtitle = "(Hesitate whether to tell him the truth)"
        },
        [51007728] = {
          ContentFR = "Ils... ne sont peut-être pas disponibles maintenant.",
          DialogueId = 51007728,
          GUID = "7FB14760",
          NextDialogue = 51007729,
          SpeakNpcId = 100001,
          Subtitle = "They... might not be able to talk right now.",
          TalkActionId = {
            [1] = "0:Disagree"
          }
        },
        [51007729] = {
          ContentFR = "Hein... ? D’accord...",
          DialogueId = 51007729,
          GUID = "7FB1478A",
          NextDialogue = 51007730,
          SpeakNpcId = 700204,
          Subtitle = "Huh...? Oh... okay..."
        },
        [51007730] = {
          ContentFR = "Euh... Je peux au moins frapper à la porte ? Peut-être qu’ils ont un peu de temps !",
          DialogueId = 51007730,
          GUID = "7FB147B4",
          NextDialogue = 51007731,
          SpeakNpcId = 700204,
          Subtitle = "Um... can I at least knock? Maybe they just happen to have some free time!"
        },
        [51007731] = {
          ContentFR = "... En fait, la maison est vide maintenant.",
          DialogueId = 51007731,
          GUID = "7FB147DE",
          NextDialogue = 51007732,
          SpeakNpcId = 100001,
          Subtitle = "...Actually, there's no one left inside. The house is empty now.",
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007732] = {
          ContentFR = "Hein ? Mais la dernière fois, il y avait plein d’enfants plus vieux que moi dedans !",
          DialogueId = 51007732,
          GUID = "7FB14808",
          NextDialogue = 51007733,
