          LookAt = {
            [1] = "100001:n(230002)"
          },
          NextDialogue = 51009222,
          SpeakNpcId = 100001,
          Subtitle = "You're not offended?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
