        },
        [51009222] = {
          Camera = "302.543945,-108.304688,186.282227,0.000152,-9.201569,139.426468,25.000002,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas le moins du monde. Sa réponse est surprenante, mais il n’a pas tort. La teinte, le fini, ça compte aussi pour beaucoup.",
