        },
        [51009236] = {
          Camera = "50.263702,-171.348389,180.614441,0.00006,-22.054018,109.22464,35.000015,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hmmm... pas mal du tout. La couche est lisse, l’adhérence est bonne... mais je trouve quand même que...",
          DialogueId = 51009236,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "40.829468,-144.295166,169.006805,0.00006,-22.054018,109.22464,35.000015,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23EC8",
          LookAt = {
            [1] = "100001:n(230002)"
          },
          NextDialogue = 51009237,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"StoryCustom\"},SoundType{\"SOUND_BGM\"},SoundUnitKey{\"sidestory_tiejiangjiaojiao\"},EventPath{\"event:/bgm/cbt02/0041_story_jiaojiao_tiejiang\"}}",
          SpeakNpcId = 230002,
          Subtitle = "Hm... not bad at all. Smooth finish, good adhesion... though I must say—",
          ToFinalCameraBlendTime = 30
        },
        [51009237] = {
          ContentFR = "Que... quoi ?",
          DialogueId = 51009237,
          GUID = "7FB23EF2",
          NextDialogue = 51009238,
          SpeakNpcId = 100001,
          Subtitle = "What is it?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009238] = {
          Camera = "6.65741,-50.126221,134.693878,0.000072,-23.202663,92.203529,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Que la couleur est un peu... tape-à-l’œil, non ?",
          DialogueId = 51009238,
          FinalCamera = "6.295074,-32.139404,126.282524,0.000077,-21.25412,91.423836,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23F1C",
          LookAt = {
            [1] = "230002:n(100001)"
          },
          NextOptions = {
            [1] = 510092381,
            [2] = 510092382
          },
          SpeakNpcId = 230002,
          Subtitle = "Isn't this shade a bit... over-the-top?",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          ToFinalCameraBlendTime = 5
        },
        [51009239] = {
          Camera = "38.538757,-183.397461,161.428268,0.000042,-13.602649,100.809677,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bah... je ne comprends pas toujours vos goûts, vous les jeunes. Mais si ça te plaît, gardons-la ainsi.",
          DialogueId = 51009239,
          FinalCamera = "27.600983,-132.857178,154.2789,0.000026,-18.804384,103.619179,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23F46",
          NextDialogue = 51009240,
          SpeakNpcId = 230002,
          Subtitle = "Hmm. I'll never quite understand you young folk... but if you're set on it, then so be it.",
          ToFinalCameraBlendTime = 30
        },
        [51009240] = {
          ContentFR = "Et si jamais tu veux essayer une autre teinte, rapporte-moi les bons matériaux et je m’en occuperai.",
          DialogueId = 51009240,
          GUID = "7FB23F70",
          NextDialogue = 51009242,
          SpeakNpcId = 230002,
          Subtitle = "If you fancy another palette later on, just bring me the right materials and we'll have another go."
        },
        [51009241] = {
          Camera = "38.538757,-183.397461,161.428268,0.000042,-13.602649,100.809677,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas besoin de te presser, d’ailleurs. Peut-être qu’une autre couleur t’ira mieux. Reviens me voir une fois décidé.",
          DialogueId = 51009241,
          FinalCamera = "27.600983,-132.857178,154.2789,0.000026,-18.804384,103.619179,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23F9A",
          NextDialogue = 51009242,
          SpeakNpcId = 230002,
          Subtitle = "No need to decide in haste. Try a few other shades — see how they suit you. Come find me once you've made up your mind.",
          ToFinalCameraBlendTime = 30
        },
        [51009242] = {
          ContentFR = "L’esthétique des couleurs... il me reste encore beaucoup à apprendre dans ce domaine.",
          DialogueId = 51009242,
          GUID = "7FB23FC4",
          SpeakNpcId = 230002,
          Subtitle = "The aesthetics of colour, eh...? Looks like I've still got a fair bit to learn on that front."
        },
        [51009243] = {
          ContentFR = "Vous là-bas ! {性别:Héros immaculé, tout de blanc vêtu|Héroïne immaculée, tout de blanc vêtue}, accordez-moi un instant !",
          DialogueId = 51009243,
          GUID = "7FB23FEE",
          SpeakNpcId = 230003,
          Subtitle = "You there — the hero in immaculate white! A moment, if you please!"
        },
        [51009244] = {
          ContentFR = "Oui, vous ! Si vous êtes {性别:venu|venue} jusqu’à moi, c’est que nous partageons forcément une résonance... une communion esthétique !",
          DialogueId = 51009244,
          GUID = "7FB24018",
          SpeakNpcId = 230003,
          Subtitle = "Yes, yes — you! The very fact you've made it to me can mean only one thing: resonance. A deep, aesthetic bond between us!"
        },
        [51009301] = {
          ContentFR = "Cette fois, je vais choisir des fleurs roses !",
          DialogueId = 51009301,
          GUID = "7FB24972",
          NextDialogue = 51009302,
          SpeakNpcId = 700247,
          Subtitle = "This time, I'll go with pink ones!"
        },
        [51009302] = {
          ContentFR = "La jeune femme sourit en prenant les fleurs roses qu’elle a soigneusement choisies. Lorsqu’elle relève la tête, elle vous remarque.",
          DialogueId = 51009302,
          GUID = "7FB2499C",
          NextDialogue = 51009303,
          Subtitle = "(The woman smiles as she picks up the carefully chosen pink blooms. Looking up, she notices you.)"
        },
        [51009303] = {
          ContentFR = "Bonjour. Vous venez aussi acheter des fleurs ?",
          DialogueId = 51009303,
          GUID = "7FB249C6",
          NextDialogue = 51009304,
          SpeakNpcId = 700247,
          Subtitle = "Hello there. Are you here to buy flowers too?"
        },
        [51009304] = {
          ContentFR = "Que diriez-vous de celles-ci ? Les fleurs roses sont plutôt rares, vous savez.",
          DialogueId = 51009304,
          GUID = "7FB249F0",
          NextOptions = {
            [1] = 51009305,
            [2] = 51009310,
            [3] = 51009313
          },
          SpeakNpcId = 700247,
          Subtitle = "Take a look? Pink flowers like these are quite rare, you know."
        },
        [51009305] = {
          ContentFR = "<I>Vous pourriez me les offrir ?</>",
          DialogueId = 51009305,
          GUID = "7FB24A1A",
          ImprPlusId = 1001,
          NextDialogue = 51009306,
          Subtitle = "Could I have them?"
        },
        [51009306] = {
          ContentFR = "Héhé, bien sûr !",
          DialogueId = 51009306,
          GUID = "7FB24A44",
          NextDialogue = 51009307,
          SpeakNpcId = 700247,
          Subtitle = "Hehe, of course!"
        },
        [51009307] = {
          ContentFR = "Elle tend la main, prend quelques tiges supplémentaires sur l’étagère, les règle avec les siennes, puis vous les tend.",
          DialogueId = 51009307,
          GUID = "7FB24A6E",
          NextDialogue = 51009308,
          Subtitle = "(She reaches out, deftly takes a few more stems from the shelf, pays for them along with her own, and hands them to you.)"
        },
        [51009308] = {
          ContentFR = "Tenez, prenez-les.",
          DialogueId = 51009308,
          GUID = "7FB24A98",
          NextDialogue = 51009309,
          SpeakNpcId = 700247,
          Subtitle = "Here you are."
        },
        [51009309] = {
          ContentFR = "Inutile de me remercier. Disons que vous profitez un peu de sa chance.",
          DialogueId = 51009309,
          GUID = "7FB24AC2",
          NextDialogue = 51009317,
          SpeakNpcId = 700247,
          Subtitle = "No need to thank me. Just think of it as you sharing in his good fortune."
        },
        [51009310] = {
          ContentFR = "<I>Merci. Je les trouve très belles aussi.</>",
          DialogueId = 51009310,
          GUID = "7FB24AEC",
          ImprPlusId = 1004,
          NextDialogue = 51009311,
          Subtitle = "Thank you, I think they're lovely too."
        },
        [51009311] = {
          ContentFR = "Si elles vous plaisent, je peux vous les donner.",
          DialogueId = 51009311,
          GUID = "7FB24B16",
          NextDialogue = 51009312,
          Subtitle = "You can have them if you like."
        },
        [51009312] = {
          ContentFR = "Il n’y verrait sûrement aucun inconvénient.",
          DialogueId = 51009312,
          GUID = "7FB24B40",
          NextDialogue = 51009317,
          Subtitle = "I'm sure he wouldn't have minded either."
        },
        [51009313] = {
          ContentFR = "<I>Oh non, je déteste le rose !</>",
          DialogueId = 51009313,
          GUID = "7FB24B6A",
          ImprPlusId = 1005,
          NextDialogue = 51009314,
          Subtitle = "Oh no, I can't stand pink!"
        },
        [51009314] = {
          ContentFR = "Oh... je suis désolée.",
          DialogueId = 51009314,
          GUID = "7FB24B94",
          NextDialogue = 51009315,
          SpeakNpcId = 700247,
          Subtitle = "Oh dear, I'm so sorry to hear that."
        },
        [51009315] = {
          ContentFR = "C’est vrai, tout le monde n’aime pas le rose...",
          DialogueId = 51009315,
          GUID = "7FB24BBE",
          NextDialogue = 51009316,
          SpeakNpcId = 700247,
          Subtitle = "Well, it's true. Not everyone likes pink, I suppose..."
        },
        [51009316] = {
          ContentFR = "À bien y penser, peut-être que lui non plus... Mais ce n’est pas grave ! Disons qu’il aimait.",
          DialogueId = 51009316,
          GUID = "7FB24BE8",
          NextDialogue = 51009317,
          SpeakNpcId = 700247,
          Subtitle = "Now that you mention it, perhaps he didn't either... But never mind! Let's just pretend he did."
        },
        [51009317] = {
          ContentFR = "Ces fleurs sont pour quelqu’un ?",
          DialogueId = 51009317,
          GUID = "7FB24C12",
          NextDialogue = 51009318,
          SpeakNpcId = 100001,
          Subtitle = "Are these flowers for someone?"
        },
        [51009318] = {
          ContentFR = "Oui. J’ai une amie fée, avec des cornes comme les vôtres. Ces fleurs sont pour lui.",
          DialogueId = 51009318,
          GUID = "7FB24C3C",
          NextOptions = {
            [1] = 51009319,
            [2] = 51009321
          },
          SpeakNpcId = 700247,
          Subtitle = "Yes. I have a faerie friend, much like you with horns, and these are for him."
        },
        [51009319] = {
          ContentFR = "<I>« Une fée » ?</>",
          DialogueId = 51009319,
          GUID = "7FB24C66",
          NextDialogue = 51009320,
          Subtitle = "Faerie?"
        },
        [51009320] = {
          ContentFR = "Héhé, c’est ainsi qu’il se présentait.",
          DialogueId = 51009320,
          GUID = "7FB24C90",
          NextDialogue = 51009323,
          SpeakNpcId = 700247,
          Subtitle = "Oh, that's what he called himself."
        },
        [51009321] = {
          ContentFR = "<I>Je suis {性别:un Charon|une Charon}.</>",
          DialogueId = 51009321,
          GUID = "7FB24CBA",
          NextDialogue = 51009322,
          Subtitle = "I'm Charon."
        },
        [51009322] = {
          ContentFR = "Oui... « fée », c’était son mot à lui.",
          DialogueId = 51009322,
          GUID = "7FB24CE4",
          NextDialogue = 51009323,
          SpeakNpcId = 700247,
          Subtitle = "Well, \"faerie\" was his word for it."
        },
        [51009323] = {
          ContentFR = "Dites-moi, le vent s’est-il levé dehors ?",
          DialogueId = 51009323,
          GUID = "7FB24D0E",
          NextOptions = {
            [1] = 51009324,
            [2] = 51009326,
            [3] = 51009328
          },
          SpeakNpcId = 700247,
          Subtitle = "Speaking of which,has the wind picked up outside?"
        },
        [51009324] = {
          ContentFR = "<I>Je n’y ai pas fait attention.</>",
          DialogueId = 51009324,
          GUID = "7FB24D38",
          NextDialogue = 51009325,
          Subtitle = "I didn't notice."
        },
        [51009325] = {
          ContentFR = "Je vois... Ce n’est pas grave, j’irai vérifier moi-même tout à l’heure.",
          DialogueId = 51009325,
          GUID = "7FB24D62",
          NextDialogue = 51009330,
          SpeakNpcId = 700247,
          Subtitle = "I see... No matter, I'll check for myself later."
        },
        [51009326] = {
          ContentFR = "<I>Le vent souffle fort.</>",
          DialogueId = 51009326,
          GUID = "7FB24D8C",
          NextDialogue = 51009327,
          Subtitle = "It's quite windy."
        },
        [51009327] = {
          ContentFR = "Alors c’est parfait.",
          DialogueId = 51009327,
          GUID = "7FB24DB6",
          NextDialogue = 51009330,
          SpeakNpcId = 700247,
          Subtitle = "That's wonderful."
        },
        [51009328] = {
          ContentFR = "<I>Même sans vent, je peux en créer.</>",
          DialogueId = 51009328,
          GUID = "7FB24DE0",
          NextDialogue = 51009329,
          Subtitle = "I can make wind, even if there isn't any."
        },
        [51009329] = {
          ContentFR = "Vraiment ? Vous êtes donc si {性别:puissant|puissante}... merci de votre intention.",
          DialogueId = 51009329,
          GUID = "7FB24E0A",
          NextDialogue = 51009330,
          SpeakNpcId = 700247,
          Subtitle = "Really? You're that powerful? That's very kind of you."
        },
        [51009330] = {
          ContentFR = "Je dois attendre que le vent se lève pour lui offrir les fleurs.",
          DialogueId = 51009330,
          GUID = "7FB24E34",
          NextOptions = {
            [1] = 51009331,
            [2] = 51009333,
            [3] = 51009335
          },
          SpeakNpcId = 700247,
          Subtitle = "I need to wait for the wind to pick up before I can give him the flowers."
        },
        [51009331] = {
          ContentFR = "<I>Pourquoi attendre le vent ?</>",
          DialogueId = 51009331,
          GUID = "7FB24E5E",
          NextDialogue = 51009332,
          Subtitle = "Why do you need the wind?"
        },
        [51009332] = {
          ContentFR = "Parce que lorsque le vent souffle, les fleurs peuvent s’élever dans le ciel.",
          DialogueId = 51009332,
          GUID = "7FB24E88",
          NextDialogue = 51009337,
          SpeakNpcId = 700247,
          Subtitle = "Because when the wind blows, the flowers can float up into the sky."
        },
        [51009333] = {
          ContentFR = "<I>Votre ami serait-il une fée du vent ?</>",
          DialogueId = 51009333,
          GUID = "7FB24EB2",
          NextDialogue = 51009334,
          Subtitle = "Is your friend a wind faerie, by any chance?"
        },
        [51009334] = {
          ContentFR = "Héhé, c’est une idée charmante. Qui sait, peut-être bien.",
          DialogueId = 51009334,
          GUID = "7FB24EDC",
          NextDialogue = 51009337,
          SpeakNpcId = 700247,
          Subtitle = "An interesting thought! Perhaps he is."
        },
        [51009335] = {
          ContentFR = "<I>Est-ce une sorte de rituel ?</>",
          DialogueId = 51009335,
          GUID = "7FB24F06",
          NextDialogue = 51009336,
          Subtitle = "Is this some special kind of ritual?"
        },
        [51009336] = {
          ContentFR = "Oui... Un rituel pour transmettre mes pensées.",
          DialogueId = 51009336,
          GUID = "7FB24F30",
          NextDialogue = 51009337,
          SpeakNpcId = 700247,
          Subtitle = "Well... it's a ritual for sending thoughts to someone."
        },
        [51009337] = {
          ContentFR = "Cet ami... Il est parti vers le ciel il y a plusieurs années.",
          DialogueId = 51009337,
          GUID = "7FB24F5A",
          NextDialogue = 51009338,
          SpeakNpcId = 700247,
          Subtitle = "That friend of mine... he went up to the sky several years ago."
        },
        [51009338] = {
          ContentFR = "Aujourd’hui est l’anniversaire de sa disparition.",
          DialogueId = 51009338,
          GUID = "7FB24F84",
          NextOptions = {
            [1] = 51009339
          },
          RestartTag = 51009338,
          SpeakNpcId = 700247,
          Subtitle = "Today is the annual day of remembrance."
        },
        [51009339] = {
          ContentFR = "<I>Rappeler les coutumes des Charons</>",
          DialogueId = 51009339,
          FailDialogue = 51009340,
          GUID = "7FB24FAE",
          ImprCheckId = 1071,
          NextDialogue = 51009341,
          Subtitle = "(Remind her of Charon customs.)"
        },
        [51009340] = {
          ContentFR = "Un instant, vous ne parvenez plus à vous souvenir des détails du rituel.",
          DialogueId = 51009340,
          GUID = "7FB24FD8",
          Subtitle = "(For a moment, you can't quite recall the details of the custom.)"
        },
        [51009341] = {
          ContentFR = "Selon les croyances des Charons, la Mer du Silence est le lieu où retournent les âmes. Si vous souhaitez lui rendre hommage, confier les fleurs à l’eau serait plus approprié.",
          DialogueId = 51009341,
          GUID = "7FB25002",
          NextDialogue = 51009342,
          SpeakNpcId = 100001,
          Subtitle = "In Charon belief, the Misty Sea is where souls go. If you wish to remember him, sending the flowers onto the water would make more sense."
        },
        [51009342] = {
          ContentFR = "Oui... je le sais. Mais lui... il était différent.",
          DialogueId = 51009342,
          GUID = "7FB2502C",
          NextDialogue = 51009343,
          SpeakNpcId = 700247,
          Subtitle = "Well... I know. But he was different."
        },
        [51009343] = {
          ContentFR = "Elle se tait un instant, puis tourne les yeux vers la fenêtre. Une douce nostalgie affleure dans son regard.",
          DialogueId = 51009343,
          GUID = "7FB25056",
          NextDialogue = 51009344,
          Subtitle = "(The woman falls silent, gazing out the window, her eyes filled with a gentle nostalgia.)"
        },
        [51009344] = {
          ContentFR = "Je l’ai rencontré pour la première fois hors de la ville. Nous avions le même âge, des caractères très proches... Nous sommes vite devenus amis.",
          DialogueId = 51009344,
          GUID = "7FB25080",
          NextDialogue = 51009345,
          SpeakNpcId = 700247,
          Subtitle = "I first met him outside the city. We were the same age, and our personalities just clicked, so we became fast friends."
        },
        [51009345] = {
          ContentFR = "Il me disait venir du ciel, être une « fée »... Héhé, en vérité, j’ai toujours su qu’il était un Charon. Mais le voir s’évertuer à maintenir son histoire... je n’ai jamais eu le cœur de la briser.",
          DialogueId = 51009345,
          GUID = "7FB250AA",
          NextDialogue = 51009346,
          SpeakNpcId = 700247,
          Subtitle = "He told me he was a \"faerie\" from the sky... Hehe, truthfully, I knew all along he was Charon. But every time I saw him trying so hard to keep up the story, I couldn't bear to spoil it for him."
        },
        [51009346] = {
          ContentFR = "Et puis, il ressemblait vraiment à une fée de conte. Il savait tant de choses que j’ignorais, et avait toujours mille récits nouveaux à raconter.",
          DialogueId = 51009346,
          GUID = "7FB250D4",
          NextOptions = {
            [1] = 51009347,
            [2] = 51009349
          },
          SpeakNpcId = 700247,
          Subtitle = "Besides, he really was just like a faerie from the stories — he knew so many things I didn't, and always had endless fascinating tales to tell."
        },
        [51009347] = {
          ContentFR = "<I>On dirait un ami merveilleux.</>",
          DialogueId = 51009347,
          GUID = "7FB250FE",
          NextDialogue = 51009348,
          Subtitle = "Sounds like a wonderful friend."
        },
        [51009348] = {
          ContentFR = "Oui ! C’était le meilleur des amis.",
          DialogueId = 51009348,
          GUID = "7FB25128",
          NextDialogue = 51009351,
          SpeakNpcId = 700247,
          Subtitle = "Yes! He's the best friend ever."
        },
        [51009349] = {
          ContentFR = "<I>Il a donc joué à être une fée toute sa vie ?</>",
          DialogueId = 51009349,
          GUID = "7FB25152",
          NextDialogue = 51009350,
          Subtitle = "So he was playing the part of a faerie his whole life?"
        },
        [51009350] = {
          ContentFR = "Héhé... dit comme ça, c’est un peu enfantin, non ?",
          DialogueId = 51009350,
          GUID = "7FB2517C",
          NextDialogue = 51009351,
          SpeakNpcId = 700247,
          Subtitle = "Sounds a bit childish when you put it like that, doesn't it?"
        },
        [51009351] = {
          ContentFR = "Je m’en suis longtemps inquiétée — le jour où nous aurions grandi, dépassé l’âge où l’on croit naturellement aux contes... Comment en parler sans malaise ?",
          DialogueId = 51009351,
          GUID = "7FB251A6",
          NextDialogue = 51009352,
          SpeakNpcId = 700247,
          Subtitle = "It always bothered me a little... wondering how we would finally talk about it, once we grew up and passed the age where believing in fairy tales came naturally."
        },
        [51009352] = {
          ContentFR = "Que ce soit lui ou moi qui abordions le sujet, rien que d’y penser, c’était embarrassant...",
          DialogueId = 51009352,
          GUID = "7FB251D0",
          NextDialogue = 51009353,
          SpeakNpcId = 700247,
          Subtitle = "Whether I brought it up or he did, just imagining it felt so awkward..."
        },
        [51009353] = {
          ContentFR = "Mais nous n’avons jamais atteint ce moment-là. Il est parti avant d’atteindre l’âge adulte.",
          DialogueId = 51009353,
          GUID = "7FB251FA",
          NextDialogue = 51009354,
          SpeakNpcId = 700247,
          Subtitle = "But in the end, we never reached that point. He left before we came of age."
        },
        [51009354] = {
          ContentFR = "Pensez-vous... qu’il ait choisi ce moment précisément pour cela ? Quel être si doux...",
          DialogueId = 51009354,
          GUID = "7FB25224",
          NextDialogue = 51009355,
          SpeakNpcId = 700247,
          Subtitle = "Do you think... he might have chosen to leave at that precise time because he knew? What a gentle soul he was..."
        },
        [51009355] = {
          ContentFR = "Elle caresse les pétales soyeux et baisse doucement les yeux. Il est impossible de lire l’émotion sur son visage.",
          DialogueId = 51009355,
          GUID = "7FB2524E",
          NextOptions = {
            [1] = 51009356,
            [2] = 51009358,
            [3] = 51009360
          },
          Subtitle = "(The woman strokes the soft petals, gently lowering her gaze. You can't quite decipher the emotion on her face.)"
        },
        [51009356] = {
          ContentFR = "<I>Je suis {性别:désolé|désolée}. Toutes mes condoléances...</>",
          DialogueId = 51009356,
          GUID = "7FB25278",
          ImprPlusId = 1002,
          NextDialogue = 51009357,
          Subtitle = "Sorry for your loss."
        },
        [51009357] = {
          ContentFR = "Ce n’est rien. Cela fait déjà de nombreuses années.",
          DialogueId = 51009357,
          GUID = "7FB252A2",
          NextDialogue = 51009362,
          SpeakNpcId = 700247,
          Subtitle = "It's okay. It's been years."
        },
        [51009358] = {
          ContentFR = "<I>Vous étiez tous les deux d’une grande douceur.</>",
          DialogueId = 51009358,
          GUID = "7FB252CC",
          ImprPlusId = 1004,
          NextDialogue = 51009359,
          Subtitle = "You're both incredibly kind people."
        },
        [51009359] = {
          ContentFR = "Héhé... merci.",
          DialogueId = 51009359,
          GUID = "7FB252F6",
          NextDialogue = 51009362,
          SpeakNpcId = 700247,
          Subtitle = "Then... thank you."
        },
        [51009360] = {
          ContentFR = "<I>L’âge adulte... Aurait-il montré des signes de Dégradation ?</>",
          DialogueId = 51009360,
          GUID = "7FB25320",
          ImprPlusId = 1003,
          NextDialogue = 51009361,
          Subtitle = "Coming of age... Did he start showing signs of Deterioration?"
        },
        [51009361] = {
          ContentFR = "Oui... c’est aussi ce que j’ai pensé. Il est parti juste avant ses dix-huit ans.",
          DialogueId = 51009361,
          GUID = "7FB2534A",
          NextDialogue = 51009362,
          SpeakNpcId = 700247,
          Subtitle = "Well, that's what I thought. After all, he left just before he turned eighteen."
        },
        [51009362] = {
          ContentFR = "Il avait déjà pressenti sa fin. La dernière fois que nous nous sommes vus, il m’a dit qu’il retournait dans sa patrie céleste, et qu’il ne pourrait plus jamais venir me voir.",
          DialogueId = 51009362,
          GUID = "7FB25374",
          NextDialogue = 51009363,
          SpeakNpcId = 700247,
          Subtitle = "He had foreseen his own fate. The last time we met, he told me he was returning to his homeland in the sky and wouldn't be able to visit me anymore."
        },
        [51009363] = {
          ContentFR = "C’était le mensonge le plus maladroit qu’il ait jamais raconté... Les larmes lui montaient déjà aux yeux, mais il forçait un sourire et me parlait d’une voix enjouée —",
          DialogueId = 51009363,
          GUID = "7FB2539E",
          NextDialogue = 51009364,
          SpeakNpcId = 700247,
          Subtitle = "It was the most poorly told lie of his life... His eyes were already brimming with tears, yet he forced a smile and said to me in the cheeriest voice—"
        },
        [51009364] = {
          ContentFR = "« Ne sois pas triste. Même si je ne peux plus venir te voir, je veillerai toujours sur toi, là-haut, au-dessus des nuages... »",
          DialogueId = 51009364,
          GUID = "7FB253C8",
          NextDialogue = 51009365,
          SpeakNpcId = 700247,
          Subtitle = "\"Please don't be sad. Even though I can't come to see you anymore, I'll be watching over you from above the clouds, always...\""
        },
        [51009365] = {
          ContentFR = "« Chaque fois que tu lèveras les yeux vers le ciel, tes pensées me parviendront portées par le vent. »",
          DialogueId = 51009365,
          GUID = "7FB253F2",
          NextDialogue = 51009366,
          SpeakNpcId = 700247,
          Subtitle = "\"Whenever you look up at the sky, your thoughts will reach me on the wind.\""
        },
        [51009366] = {
          ContentFR = "En prononçant ces mots, elle sourit. Est-ce une illusion ? Une lueur traverse ses yeux — est-ce une larme, ou le reflet du soleil sur la vitre ?",
          DialogueId = 51009366,
          GUID = "7FB2541C",
          NextDialogue = 51009367,
          Subtitle = "(As she says this, the woman smiles. Is it a trick of the light, or is there a faint glimmer in her eyes—a tear, or perhaps a reflection from the sun through the window pane?)"
        },
        [51009367] = {
          ContentFR = "C’est pour cela que vous jetez les fleurs dans le ciel... ?",
          DialogueId = 51009367,
          GUID = "7FB25446",
          NextDialogue = 51009368,
          SpeakNpcId = 100001,
          Subtitle = "So, that's why you cast the flowers into the sky?"
        },
        [51009368] = {
          ContentFR = "Oui. Puisque c’est l’histoire qu’il voulait me raconter, je choisis de croire que sa destination n’était pas la Mer du Silence, mais le vaste ciel azuré.",
          DialogueId = 51009368,
          GUID = "7FB25470",
          NextDialogue = 51009369,
          SpeakNpcId = 700247,
          Subtitle = "Indeed. Since that was the story he wanted to tell me, I choose to believe that his final resting place isn't the Misty Sea, but the vast blue sky."
        },
        [51009369] = {
          ContentFR = "Tant que je confierai les pétales au vent, il pourra sentir mes pensées.",
          DialogueId = 51009369,
          GUID = "7FB2549A",
          NextOptions = {
            [1] = 51009370,
            [2] = 51009371
          },
          SpeakNpcId = 700247,
          Subtitle = "As long as I scatter the petals to the wind, he'll feel my thoughts."
        },
        [51009370] = {
          ContentFR = "<I>J’espère qu’il recevra vos fleurs.</>",
          DialogueId = 51009370,
          GUID = "7FB254C4",
          NextDialogue = 51009372,
          Subtitle = "I hope he receives your flowers."
        },
        [51009371] = {
          ContentFR = "<I>Il les recevra, j’en suis{性别:certain|certaine}.</>",
          DialogueId = 51009371,
          GUID = "7FB254EE",
          NextDialogue = 51009372,
          Subtitle = "I'm sure he will receive them."
        },
        [51009372] = {
          ContentFR = "... Merci.",
          DialogueId = 51009372,
          GUID = "7FB25518",
          NextDialogue = 51009373,
          SpeakNpcId = 700247,
          Subtitle = "...Thank you."
        },
        [51009373] = {
          ContentFR = "Avec le recul, il savait sans doute déjà que j’avais percé son mensonge.",
          DialogueId = 51009373,
          GUID = "7FB25542",
          NextDialogue = 51009374,
          SpeakNpcId = 700247,
          Subtitle = "Looking back now, I think he probably knew all along that I had seen through his little charade."
        },
        [51009374] = {
          ContentFR = "Une histoire tissée de mensonges, qui s’achève par un mensonge... N’est-ce pas, d’une certaine manière, une fin appropriée ?",
          DialogueId = 51009374,
          GUID = "7FB2556C",
          NextDialogue = 51009375,
          SpeakNpcId = 700247,
          Subtitle = "A story woven from lies, ending with a lie... doesn't that seem rather fitting, in a way?"
        },
        [51009375] = {
          ContentFR = "Bien. Je dois me rendre hors de la ville avant que la nuit ne tombe, pour tenir la promesse que je lui ai faite.",
          DialogueId = 51009375,
          GUID = "7FB25596",
          NextDialogue = 51009376,
          SpeakNpcId = 700247,
          Subtitle = "Right, I'd best be off outside the city walls to keep my promise to him before it gets dark."
        },
        [51009376] = {
          ContentFR = "Adieu, petite fée. Puisse votre histoire connaître une fin vraie et heureuse.",
          DialogueId = 51009376,
          GUID = "7FB255C0",
          SpeakNpcId = 700247,
          Subtitle = "Goodbye, little faerie. May your own story have a true and happy ending."
        },
        [51009377] = {
          ContentFR = "Oh... petite fée, nous nous retrouvons encore. Le ciel est magnifique aujourd’hui, n’est-ce pas ?",
          DialogueId = 51009377,
          GUID = "7FB255EA",
          SpeakNpcId = 700247,
          Subtitle = "Hello again, little faerie. Lovely weather we're having, isn't it?"
        },
        [51009401] = {
          ContentFR = "Veuillez patienter un instant, {性别:honorable monsieur|gracieuse demoiselle} !",
          DialogueId = 51009401,
          GUID = "7FB259DA",
          NextDialogue = 51009402,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "A moment of your time, {性别:good sir|fair lady}!",
          TalkActionId = {
            [1] = "700306:Talk01_Start"
          }
        },
        [51009402] = {
          ContentFR = "Ah... comment pourrais-je seulement décrire votre beauté ?",
          DialogueId = 51009402,
          GUID = "7FB25A04",
          NextDialogue = 51009403,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ah... how does one even begin to capture your beauty?"
        },
        [51009403] = {
          ContentFR = "Un tanuki muet compose des poèmes en votre honneur, la lune verdoyante vous drape d’un éclat d’or. Une lièvre de mer vous couronne de gemmes taillées dans des fruits de palmier... et moi, près d’une benne oubliée, je chante votre nom aux étoiles —",
          DialogueId = 51009403,
          GUID = "7FB25A2E",
          NextDialogue = 51009404,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "A mute tanuki pens sonnets in your name; the verdant moon casts gold across your form. A sea hare crowns you with palmfruit jewels... while I, by a forgotten bin, sing your name to the stars—"
        },
        [51009404] = {
          ContentFR = "Que mes louanges atteignent ou non votre regard, je vous en prie... je vous en conjure...",
          DialogueId = 51009404,
          GUID = "7FB25A58",
          NextDialogue = 51009405,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Even if my words fall short of your splendour, I beg you... I implore you..."
        },
        [51009405] = {
          ContentFR = "Oh ! Quelle allure remarquable ! Vous devez être {性别:le célèbre Chasseur|la célèbre Chasseuse} de Phoxène, {性别:Monsieur|Mademoiselle} {nickname} !",
          DialogueId = 51009405,
          GUID = "7FB25A82",
          NextDialogue = 51009406,
          SpeakNpcId = 700306,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ah! Such poise, such presence! You must be the illustrious Phoxhunter — {性别:Mr|Miss} !",
          TalkActionId = {
            [1] = "700306:Talk01_End"
          }
        },
        [51009406] = {
          ContentFR = "Je suis aussi {性别:connu|connue} que ça ? ... Non, j’ai comme l’impression que ça ne va rien annoncer de bon...",
          DialogueId = 51009406,
          GUID = "7FB25AAC",
          NextDialogue = 51009407,
          SpeakNpcId = 100001,
          Subtitle = "(Am I actually that well-known around here...? No — this is definitely heading somewhere strange...)"
        },
        [51009407] = {
          ContentFR = "Enchanté de faire votre connaissance — je m’appelle Fane. Mon professeur vous attend depuis longtemps. Veuillez me suivre.",
          DialogueId = 51009407,
          GUID = "7FB25AD6",
          NextDialogue = 51009408,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700306,
          Subtitle = "A pleasure to meet you — I'm Fane. My teacher has been awaiting your arrival. This way, please.",
          TalkActionId = {
            [1] = "700306:Talk02_Start"
          }
        },
        [51009408] = {
          ContentFR = "« Professeur » ?",
          DialogueId = 51009408,
          GUID = "7FB25B00",
          NextDialogue = 51009409,
          SpeakNpcId = 100001,
          Subtitle = "Teacher?",
          TalkActionId = {
            [1] = "700306:Talk02_End"
          }
        },
        [51009409] = {
          ContentFR = "Ah... c’est vrai, elle m’a demandé de ne pas l’appeler ainsi en public. Mais je suppose que pour vous, cela ne posera pas de problème... je vous serais reconnaissant de garder cela pour vous.",
          DialogueId = 51009409,
          GUID = "7FB25B2A",
          Scripts = "PlayOrStopBGM{_delay{8},PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0033_story_humour\"}}",
          SpeakNpcId = 700306,
          Subtitle = "Oh — right... She asked me not to call her that in public. But I doubt she'll mind if it's you. Still... I'd appreciate it if you kept it just between us."
        },
        [51009410] = {
          Camera = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Professeur, j’ai amené {性别:Monsieur|Mademoiselle} {nickname}.",
          DialogueId = 51009410,
          GUID = "7FB25B54",
          LookAt = {
            [1] = "700306:n(700300)"
          },
          NextDialogue = 51009411,
          SpeakNpcId = 700306,
          Subtitle = "Ms Violetta, I've brought ."
        },
        [51009411] = {
          Camera = "-398.734863,102.79834,140.336914,0.000002,-0.59967,-17.199116,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Te voilà donc, jeune {性别:Chasseur de Phoxène|Chasseuse de Phoxène}.",
          DialogueId = 51009411,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB25B7E",
          LookAt = {
            [1] = "700306:n(100001)"
          },
          NextDialogue = 51009412,
          SpeakNpcId = 700300,
          Subtitle = "You've come, young Phoxhunter.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009412] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh, quel adorable enfant. Ton visage me rappelle les premiers flocons de Givrelac — purs et cristallins — et les grenats rouges qui s’y déposent, si délicats qu’on ne peut s’empêcher de vouloir les effleurer...",
          DialogueId = 51009412,
          GUID = "7FB25BA8",
          NextDialogue = 51009413,
          SpeakNpcId = 700300,
          Subtitle = "Ah... such a darling child. Your beauty reminds me of Icelake's first snow — that flawless glisten... and those garnets scattered across it, red as pigeon blood... so tender, one's hand longs to—",
          TalkActionId = {
            [1] = "700300:Explain02_End"
          }
        },
        [51009413] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Attends... ne t’approche pas de moi !",
          DialogueId = 51009413,
          FacialId = {
            [1] = "100001:Shock01"
          },
          FinalCamera = "-93.166504,20.057129,149.304932,-1.999999,-3.400054,-165.189987,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB25BD2",
          NextDialogue = 51009414,
          SpeakNpcId = 100001,
          Subtitle = "Wait — don't come any closer!",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          },
          ToFinalCameraBlendTime = 1
        },
        [51009414] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Haha... Je vois que tu n’apprécies pas trop les gestes d’affection. Mes excuses — tout cela doit te sembler bien étrange. Permets-moi de me présenter convenablement.",
          DialogueId = 51009414,
          GUID = "7FB25BFC",
          NextDialogue = 51009415,
          SpeakNpcId = 700300,
          Subtitle = "Hehe, not a fan of warm greetings, I see. My apologies — this must all seem terribly dubious. Allow me to introduce myself properly.",
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009415] = {
          ContentFR = "Je m’appelle Violetta. Je suis une chanteuse d’opéra.",
          DialogueId = 51009415,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB25C26",
          NextDialogue = 51009416,
          SpeakNpcId = 700300,
          Subtitle = "I'm Violetta — an opera singer.",
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009416] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "<I>Pourquoi tous les chanteurs d’opéra parlent-ils de façon aussi bizarre... ?</>",
          DialogueId = 51009416,
          GUID = "7FB25C50",
          NextDialogue = 51009417,
          SpeakNpcId = 100001,
          Subtitle = "(Why do you opera singers talk like that...?)",
          TalkActionId = {
            [1] = "100001:Shock_End"
          }
        },
        [51009417] = {
          Camera = "-142.214844,78.577148,148.40918,0.000003,-0.599971,-20.395008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Si mon visage te dit quelque chose, c’est sûrement que tu m’as déjà aperçue sur scène... ou sur une affiche de spectacle dans les environs.",
          DialogueId = 51009417,
          GUID = "7FB25C7A",
          NextOptions = {
            [1] = 510093271,
            [2] = 510093272
          },
          SpeakNpcId = 700300,
          Subtitle = "If I seem familiar, perhaps you've seen me on stage... or glimpsed one of my posters nearby."
        },
        [51009418] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je m’en souviens. « La voix onirique venue de Luca, le visage aux mille métamorphoses »... C’était bien ça, le slogan ?",
          DialogueId = 51009418,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "7FB25CA4",
          NextDialogue = 51009420,
          SpeakNpcId = 100001,
          Subtitle = "I remember now — \"A dream-born voice from Luca, a visage that shifts like mist.\" That's what the posters said, right?",
          TalkActionId = {
            [1] = "100001:Agree"
          }
        },
        [51009419] = {
          Camera = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "« La voix onirique venue de Luca, le visage aux mille métamorphoses » — voilà comment on la décrit. Professeur Violetta est la chanteuse la plus en vue de tout Givrelac. On peut voir d’immenses affiches à son effigie au Théâtre Galea.",
          DialogueId = 51009419,
          GUID = "7FB25CCE",
          LookAt = {
            [1] = "100001:n(700306)"
          },
          NextDialogue = 51009420,
          SpeakNpcId = 700306,
          Subtitle = "\"A dream-born voice from Luca, a visage that shifts like mist\" — that's her. Ms Violetta is the most sought-after diva in Icelake. You'll find her posters all over the Galea Theatre.",
          TalkActionId = {
            [1] = "700306:Talk01_Start"
          }
        },
        [51009420] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors c’est ainsi qu’on me présente... Un brin exagéré, certes, mais je dois dire que ça me plaît.",
          DialogueId = 51009420,
          FacialId = {
            [1] = "700300:CM_Happy01"
          },
          GUID = "7FB25CF8",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009421,
          SpeakNpcId = 700300,
          Subtitle = "So that's what they say about me. A bit extravagant... but I rather like the sound of it.",
          TalkActionId = {
            [1] = "700306:Talk01_End",
            [2] = "700300:Confident_Start"
          }
        },
        [51009421] = {
          ContentFR = "J’adore voir les foules acclamer mes performances, entendre leurs conversations passionnées sur tel ou tel passage chanté.",
          DialogueId = 51009421,
          GUID = "7FB25D22",
          NextDialogue = 51009422,
          SpeakNpcId = 700300,
          Subtitle = "I love the applause — and the chatter my performances stir in every corner of the city."
        },
        [51009422] = {
          ContentFR = "Chaque rôle, chaque improvisation spontanée devient, pendant des semaines, le sujet de tous les journaux mondains — et je savoure cette attention.",
          DialogueId = 51009422,
          GUID = "7FB25D4C",
          NextDialogue = 51009423,
          SpeakNpcId = 700300,
          Subtitle = "Every role I play, every off-script whim... they ignite the gossip columns for weeks. I thrive on that kind of attention."
        },
        [51009423] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{性别:Désolé|Désolée} de t’interrompre... mais en quoi consiste exactement ta mission ?",
          DialogueId = 51009423,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB25D76",
          NextDialogue = 51009424,
          SpeakNpcId = 100001,
          Subtitle = "Sorry to interrupt... but what's the job, exactly?",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009424] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah... je me laisse emporter par mes paroles, comme toujours.",
          DialogueId = 51009424,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB25DA0",
          NextDialogue = 51009425,
          SpeakNpcId = 700300,
          Subtitle = "Ah, forgive me — I've let my flourishes run away with me again.",
          TalkActionId = {
            [1] = "100001:Talk01_End",
            [2] = "700300:Explain02_Start"
          }
        },
        [51009425] = {
          Camera = "-437.178223,124.364746,139.453369,0.000004,-1.399676,-18.998108,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "En vérité, même si j’aime être sous les projecteurs — et que j’y suis plus qu’habituée — certaines situations demeurent... délicates à gérer.",
          DialogueId = 51009425,
          GUID = "7FB25DCA",
          NextDialogue = 51009426,
          SpeakNpcId = 700300,
          Subtitle = "Truth is, while I do enjoy being the centre of attention — and have grown quite used to it — there are... certain situations even I find troublesome.",
          TalkActionId = {
            [1] = "700300:Explain02_End"
          }
        },
        [51009426] = {
          ContentFR = "Regarde ceci.",
          DialogueId = 51009426,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Letter.T_Guide_ChapterFire_Letter'}",
          GUID = "7FB25DF4",
          NextDialogue = 51009427,
          SpeakNpcId = 700300,
          Subtitle = "Here — take a look at this.",
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51009427] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une lettre d’amour ? On dirait qu’elle vient d’un de tes admirateurs.",
          DialogueId = 51009427,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB25E1E",
          NextDialogue = 51009428,
          SpeakNpcId = 100001,
          Subtitle = "A love letter? Looks like it's from one of your fans.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009428] = {
          Camera = "-216.009766,106.786621,145.499023,0.000003,1.000056,-22.195528,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Être trop adulée peut parfois devenir un fardeau. Je comprends leur passion, même si je ne peux la partager, je fais toujours de mon mieux pour y répondre avec politesse.",
          DialogueId = 51009428,
          GUID = "7FB25E48",
          NextDialogue = 51009429,
          SpeakNpcId = 700300,
          Subtitle = "Popularity can be a heavy crown. I understand their affection — and while I can't reciprocate those feelings, I do my best to respond with kindness.",
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          }
        },
        [51009429] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce n’est pas la première fois que je reçois ce genre de lettres... et j’ai toujours tenté d’y répondre. Mais cette fois-ci... j’en ai reçu une caisse entière.",
          DialogueId = 51009429,
          GUID = "7FB25E72",
          NextDialogue = 51009430,
          SpeakNpcId = 700300,
          Subtitle = "I've received such letters before — many, in fact — and I've replied where I could. But this time, I've been sent an entire box.",
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009430] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une... caisse entière !?",
          DialogueId = 51009430,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB25E9C",
          NextDialogue = 51009431,
          SpeakNpcId = 100001,
          Subtitle = "An entire box of letters...!?",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          }
        },
        [51009431] = {
          Camera = "-437.178223,124.364746,139.453369,0.000004,-1.399676,-18.998108,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui. Et toutes viennent de la même personne. D’abord la boîte aux lettres... puis ma calèche, le cadre de ma porte, les pots de fleurs, les rebords de fenêtres...",
          DialogueId = 51009431,
          GUID = "7FB25EC6",
          NextDialogue = 51009432,
          SpeakNpcId = 700300,
          Subtitle = "Yes — all from the same admirer. It began with the mailbox... then my carriage, then the doorframe, flowerpots, windowsills...",
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "100001:Shock_End"
          }
        },
        [51009432] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Chaque recoin de ma demeure se retrouve rempli de lettres dès que j’ai le dos tourné.",
          DialogueId = 51009432,
          GUID = "7FB25EF0",
          NextDialogue = 51009433,
          SpeakNpcId = 700300,
          Subtitle = "They slip them in wherever they can — whenever my back is turned.",
          TalkActionId = {
            [1] = "700300:Talk01_End"
          }
        },
        [51009433] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce n’est pas aux Veilleurs de s’occuper de ce genre d’affaires ?",
          DialogueId = 51009433,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "7FB25F1A",
          NextDialogue = 51009434,
          SpeakNpcId = 100001,
          Subtitle = "Shouldn't this be something for the Escort to deal with?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51009434] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est ce que j’ai pensé moi aussi, au début. Mais les personnalités publiques doivent toujours marcher sur des œufs...",
          DialogueId = 51009434,
          GUID = "7FB25F44",
          NextDialogue = 51009435,
          SpeakNpcId = 700300,
          Subtitle = "That was my first thought as well. But public figures... walk a fine line.",
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009435] = {
          ContentFR = "Une petite anecdote peut bien faire de moi le sujet favori des commérages... mais en tant qu’artiste, j’aimerais que l’on parle de mon art sur scène, pas de mes affaires de cœur. J’espère que tu comprends.",
          DialogueId = 51009435,
          GUID = "7FB25F6E",
          NextDialogue = 51009436,
          SpeakNpcId = 700300,
          Subtitle = "A bit of harmless gossip might make me the talk of teatimes... but as a performer, I'd rather the town whisper about my stagecraft — not my romances.",
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009436] = {
          Camera = "124.308105,149.785156,166.572021,0.000009,-4.799984,-153.390015,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "D’accord, je vois. As-tu des pistes concernant l’expéditeur ?",
          DialogueId = 51009436,
          GUID = "7FB25F98",
          NextDialogue = 51009437,
          SpeakNpcId = 100001,
          Subtitle = "Fair enough. Do you have any clues about the sender?"
        },
        [51009437] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai oublié de le préciser tout à l’heure : je sais en réalité où il habite. Les lettres sont anonymes, mais il n’a pas vraiment cherché à dissimuler son identité.",
          DialogueId = 51009437,
          GUID = "7FB25FC2",
          NextDialogue = 51009438,
          SpeakNpcId = 700300,
          Subtitle = "Ah, yes — I forgot to mention. I actually do know where he lives. The letters are unsigned, but he's made no real effort to hide his identity.",
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009438] = {
          ContentFR = "Après tout, si l’on doit cacher son nom même dans une déclaration d’amour... comment espérer une réponse ?",
          DialogueId = 51009438,
          FacialId = {
            [1] = "700300:CM_Angry01"
          },
          GUID = "7FB25FEC",
          NextDialogue = 51009439,
          SpeakNpcId = 700300,
          Subtitle = "If one must hide even their name in a love letter... what hope is there for a reply?"
        },
        [51009439] = {
          Camera = "-642.584961,260.924316,353.573975,0.000005,-21.200073,-26.393641,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tout ce que je te demande, c’est de le trouver... et de lui adresser un petit \"avertissement\".",
          DialogueId = 51009439,
          GUID = "7FB26016",
          NextOptions = {
            [1] = 510093491,
            [2] = 510093492
          },
          SpeakNpcId = 700300,
          Subtitle = "I only ask that you find him... and deliver a gentle \"warning.\""
        },
        [51009440] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je savais que je pouvais compter sur toi.",
          DialogueId = 51009440,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB26040",
          NextDialogue = 51009444,
          SpeakNpcId = 700300,
          Subtitle = "How reassuring. I knew you were the right one to ask.",
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009441] = {
          Camera = "-216.009766,106.786621,145.499023,0.000003,1.000056,-22.195528,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu sais... ce genre de personne pourrait mal interpréter la moindre attention. Cela pourrait même l’encourager à aller plus loin.",
          DialogueId = 51009441,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2606A",
          NextDialogue = 51009442,
          SpeakNpcId = 700300,
          Subtitle = "You see, someone like that... even a moment of attention might feel like victory. And that can turn dangerous.",
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51009442] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vu comme ça, je comprends mieux.",
          DialogueId = 51009442,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB26094",
          NextDialogue = 51009443,
          SpeakNpcId = 100001,
          Subtitle = "I see. That makes sense."
        },
        [51009443] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Très bien, je te laisse t’en occuper.",
          DialogueId = 51009443,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB260BE",
          NextDialogue = 51009444,
          SpeakNpcId = 700300,
          Subtitle = "Then I'll leave it in your hands.",
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009444] = {
          ContentFR = "Ah, j’allais oublier. Prends ceci, cela pourrait t’être utile.",
          DialogueId = 51009444,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
          GUID = "7FB260E8",
          NextDialogue = 51009445,
          SpeakNpcId = 700300,
          Subtitle = "Oh — and before you go, take this. It may come in handy.",
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51009445] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce ruban...",
          DialogueId = 51009445,
          FacialId = {
            [1] = "100001:Think01"
          },
          GUID = "7FB26112",
          NextDialogue = 51009446,
          SpeakNpcId = 100001,
          Subtitle = "This ribbon...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009446] = {
          Camera = "-129.929688,39.647461,146.497803,0.000003,-0.399962,-5.996194,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quelque chose ne va pas ?",
          DialogueId = 51009446,
          GUID = "7FB2613C",
          NextDialogue = 51009447,
          SpeakNpcId = 700300,
          Subtitle = "Is something wrong?"
        },
        [51009447] = {
          Camera = "-59.057617,29.076172,151.400146,0.000007,-3.400054,-165.190826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non... rien du tout. Je reviendrai bientôt.",
          DialogueId = 51009447,
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "7FB26166",
          SpeakNpcId = 100001,
          Subtitle = "No... it's nothing. I'll be back soon.",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009448] = {
          Camera = "695.307617,-554.236328,471.275024,0.000054,-20.794161,139.593384,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "L’adresse que m’a donnée Madame Violetta devrait être ici... Pourtant, il n’y a pas vraiment de logements dans le coin.",
          DialogueId = 51009448,
          GUID = "7FB26190",
          NextDialogue = 51009449,
          SpeakNpcId = 100001,
          Subtitle = "This is the address Ms Violetta gave me. Doesn't exactly look like a residential area, though...",
          TalkActionId = {
            [1] = "700313:Think_Start"
          }
        },
        [51009449] = {
          ContentFR = "Il y a un soldat pas loin. Allons lui poser quelques questions.",
          DialogueId = 51009449,
          GUID = "7FB261BA",
          NextDialogue = 51009450,
          SpeakNpcId = 100001,
          Subtitle = "There's a guard nearby — maybe he'll know something."
        },
        [51009450] = {
          Camera = "232.955078,593.629395,162.682861,0.000058,-3.794279,-115.003006,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bonjour, j’aimerais vous demander quelque chose.",
          DialogueId = 51009450,
          GUID = "7FB261E4",
          NextDialogue = 51009451,
          Scripts = "MoveTo{ActorId{100001},TargetPoint{\"Questpoint_Nvzhu_20023002\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 100001,
          Subtitle = "Hey — mind if I ask you something?"
        },
        [51009451] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je suis occupé, revenez plus tard... C’est étrange, ça devrait marcher... Qu’est-ce qui arrive à ce vieux phonographe ?",
          DialogueId = 51009451,
          GUID = "7FB2620E",
          NextDialogue = 51009452,
          SpeakNpcId = 700313,
          Subtitle = "Bit tied up right now — can it wait? ...Huh, that's odd. What's up with this phonograph?"
        },
        [51009452] = {
          Camera = "408.029297,-87.160217,216.346191,0.000075,-13.994142,150.79335,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Le soldat s’agite, visiblement contrarié, en manipulant un vieux phonographe posé à ses pieds.",
          DialogueId = 51009452,
          GUID = "7FB26238",
          NextDialogue = 51009453,
          Subtitle = "(The soldier frowns at an old phonograph at his feet, fiddling with the dials in frustration.)"
        },
        [51009453] = {
          ContentFR = "Il est cassé ?",
          DialogueId = 51009453,
          GUID = "7FB26262",
          NextDialogue = 51009454,
          SpeakNpcId = 100001,
          Subtitle = "Is it broken?"
        },
        [51009454] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas vraiment cassé... mais il commence à dater, alors il fonctionne parfois de travers. Je suis pourtant sûr qu’un petit coup suffisait à le remettre en marche...",
          DialogueId = 51009454,
          GUID = "7FB2628C",
          NextOptions = {
            [1] = 510093641
          },
          SpeakNpcId = 700313,
          Subtitle = "Not broken, exactly... just old. Sometimes it acts up. I swear a good smack used to fix it...",
          TalkActionId = {
            [1] = "700313:Talk01_Start"
          }
        },
        [51009455] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu sais bricoler ce genre de choses ? Très bien. Si tu arrives à le réparer, je te dirai tout ce que je sais.",
          DialogueId = 51009455,
          GUID = "7FB262B6",
          NextDialogue = 51009456,
          SpeakNpcId = 700313,
          Subtitle = "You know how to work these? Alright — fix it for me, and I'll answer whatever you need.",
          TalkActionId = {
            [1] = "700313:Talk01_End"
          }
        },
        [51009456] = {
          Camera = "96.858398,213.679291,148.014893,0.00006,-3.794279,-114.800949,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Marché conclu.",
          DialogueId = 51009456,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "7FB262E0",
          SpeakNpcId = 100001,
          Subtitle = "Deal.",
          TalkActionId = {
            [1] = "100001:Talk02_Start",
            [2] = "700313:Talk01_End"
          }
        },
        [51009457] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Voilà, ça devrait fonctionner maintenant.",
          DialogueId = 51009457,
          FacialId = {
            [1] = "100001:Ahaha02"
          },
          GUID = "7FB2630A",
          NextDialogue = 51009458,
          SpeakNpcId = 100001,
          Subtitle = "There — that should do it.",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009458] = {
          Camera = "490.863281,-71.149292,246.487061,0.000077,-14.394158,157.593735,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas mal ! Je vais enfin pouvoir écouter mes cassettes. Ah, la voix de Violetta... quel délice...",
          DialogueId = 51009458,
          GUID = "7FB26334",
          NextDialogue = 51009459,
          SpeakNpcId = 700313,
          Subtitle = "Not bad! Now I can finally enjoy my tapes again... Ahh, Ms Violetta's voice — it's just—",
          TalkActionId = {
            [1] = "100001:Talk01_End",
            [2] = "700313:Shock_Start"
          }
        },
        [51009459] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Connaissez-vous Madame Violetta ?",
          DialogueId = 51009459,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2635E",
          NextDialogue = 51009460,
          SpeakNpcId = 100001,
          Subtitle = "Wait — you know Violetta?",
          TalkActionId = {
            [1] = "100001:Talk02_Start",
            [2] = "700313:Shock_End"
          }
        },
        [51009460] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Qui à Givrelac ne la connaît pas ? Son premier disque vaut une fortune ! J’économise depuis trois mois et je ne peux toujours pas me le payer... Alors je me rabats sur ces enregistrements bon marché.",
          DialogueId = 51009460,
          GUID = "7FB26388",
          NextDialogue = 51009461,
          SpeakNpcId = 700313,
          Subtitle = "Who in Icelake doesn't? Her debut album's a collector's item! I've been saving for three months and still can't afford one... Guess these budget tapes will have to do for now.",
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "700313:Confident_Start"
          }
        },
        [51009461] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Parfait. Justement, ce que je voulais vous demander concerne Madame Violetta.",
          DialogueId = 51009461,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB263B2",
          SpeakNpcId = 100001,
          Subtitle = "Perfect. Because what I wanted to ask is actually about Ms Violetta.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009462] = {
          ContentFR = "Après lui avoir fait promettre de garder le secret, tu lui expliques la situation : Violetta reçoit depuis quelque temps des lettres non désirées d’un admirateur trop insistant.)",
          DialogueId = 51009462,
          GUID = "7FB263DC",
          Subtitle = "(After swearing the guard to secrecy, you explain the situation: Ms Violetta has been receiving unwanted letters from an obsessed admirer.)"
        },
        [51009463] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quoi !? C’est scandaleux ! S’il se cache dans ce quartier, je vais le sortir de là et lui apprendre les bonnes manières !",
          DialogueId = 51009463,
          GUID = "7FB26406",
          NextDialogue = 51009464,
          SpeakNpcId = 700313,
          Subtitle = "What!? That's outrageous! If that creep's squatting on my beat, I'll drag him out myself — give him a piece of my mind!",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700313:Angry01_Start"
          }
        },
        [51009464] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce ne sera peut-être pas nécessaire...",
          DialogueId = 51009464,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB26430",
          NextDialogue = 51009465,
          SpeakNpcId = 100001,
          Subtitle = "That... won't be necessary.",
          TalkActionId = {
            [1] = "100001:ScratchHead_Start"
          }
        },
        [51009465] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Comment ça, pas nécessaire ? Je déteste ce genre d’individus qui troublent l’ordre public. Je connais pratiquement tous les habitants du coin. Donne-moi un indice, et je le retrouverai.",
          DialogueId = 51009465,
          GUID = "7FB2645A",
          NextDialogue = 51009466,
          SpeakNpcId = 700313,
          Subtitle = "Sure it is! I can't stand lowlifes who disrupt public peace. I know every face on this block — just give me something to go on, and I'll smoke him out.",
          TalkActionId = {
            [1] = "100001:ScratchHead_End",
            [2] = "700313:Confident_Start"
          }
        },
        [51009466] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un indice, hein... Regardez plutôt cette lettre. Est-ce que cela vous dit quelque chose ?",
          DialogueId = 51009466,
          GUID = "7FB26484",
          NextDialogue = 51009467,
          SpeakNpcId = 100001,
          Subtitle = "I've got this letter here... See if anything jumps out?",
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51009467] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une lettre ? Fais voir ça.",
          DialogueId = 51009467,
          GUID = "7FB264AE",
          NextDialogue = 51009468,
          SpeakNpcId = 700313,
          Subtitle = "A letter? Alright, let's take a look.",
          TalkActionId = {
            [1] = "700313:Confident_End"
          }
        },
        [51009468] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51009468,
          FinalCamera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB264D8",
          NextDialogue = 51009469,
          SpeakNpcId = 700313,
          Subtitle = "...",
          ToFinalCameraBlendTime = 1
        },
        [51009469] = {
          Camera = "92.020508,225.958801,156.641846,0.000078,-5.994201,-113.997604,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51009469,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB26502",
          NextDialogue = 51009470,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51009470] = {
          ContentFR = "... Qu’y a-t-il ? Pourquoi ne dites-vous rien ?",
          DialogueId = 51009470,
          GUID = "7FB2652C",
          NextDialogue = 51009471,
          SpeakNpcId = 100001,
          Subtitle = "What's with the sudden silence?"
        },
        [51009471] = {
          Camera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est... c’est vraiment ça ? Non, impossible. Cette lettre est sincère, pleine de passion et d’émotion ! Rien à voir avec du harcèlement !",
          DialogueId = 51009471,
          GUID = "7FB26556",
          NextDialogue = 51009472,
          SpeakNpcId = 700313,
          Subtitle = "No... no way. This letter — it's heartfelt and... sincere! How could this be harassment?",
          TalkActionId = {
            [1] = "700313:Talk01_Start"
          }
        },
        [51009472] = {
          Camera = "224.37207,502.975342,173.965332,0.000078,-3.594175,-121.197639,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "On dirait bien que j’ai trouvé le coupable. Vous ne parliez pas de lui « apprendre les bonnes manières », tout à l’heure ?",
          DialogueId = 51009472,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB26580",
          NextDialogue = 51009473,
          SpeakNpcId = 100001,
          Subtitle = "Looks like we've found our guy. Weren't you just going on about giving someone a piece of your mind?"
        },
        [51009473] = {
          Camera = "28.276367,114.675842,163.198242,0.000057,-8.794093,105.195099,12.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est un malentendu, forcément un malentendu ! Je jure que mes sentiments pour Violetta sont réels ! Et puis, n’est-ce pas bien connu qu’elle aime les déclarations enflammées ? Pourquoi verrait-elle ça comme du harcèlement ?",
          DialogueId = 51009473,
          GUID = "7FB265AA",
          NextDialogue = 51009474,
          SpeakNpcId = 700313,
          Subtitle = "This is all a huge misunderstanding! It was all from the heart! I swear — my feelings for Ms Violetta are real! Ms Violetta adores bold declarations of love — why would she see this as anything but romantic!?"
        },
        [51009474] = {
          ContentFR = "... Attends une seconde. <H>Est-ce que ce {性别:Chasseur de Phoxène|Chasseuse de Phoxène} m’aurait menti</>... ?",
          DialogueId = 51009474,
          GUID = "7FB265D4",
          NextDialogue = 51009475,
          SpeakNpcId = 700313,
          Subtitle = "Wait a sec... was I tricked by that Phoxhunter...?"
        },
        [51009475] = {
          ContentFR = "Je comprends maintenant ! C’est toi ! Tu n’as jamais été envoyé par Violetta, tu veux simplement nous séparer !",
          DialogueId = 51009475,
          GUID = "7FB265FE",
          NextDialogue = 51009476,
          SpeakNpcId = 700313,
          Subtitle = "Oh, I get it now — it's you! You're not here on Ms Violetta's behalf — you're trying to drive a wedge between us!",
          TalkActionId = {
            [1] = "700313:Angry01_Start"
          }
        },
        [51009476] = {
          ContentFR = "As-tu seulement la moindre preuve qu’elle t’a demandé de venir ? À mon avis, tu veux juste semer la discorde !",
          DialogueId = 51009476,
          GUID = "7FB26628",
          NextDialogue = 51009477,
          SpeakNpcId = 700313,
          Subtitle = "Got any proof she sent you? I bet you're just here to stir the pot!"
        },
        [51009477] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tenter de briser le lien sacré qui unit Violetta à ses admirateurs ? Jamais ! Je vais t’apprendre à regretter ce que tu as fait !",
          DialogueId = 51009477,
          GUID = "7FB26652",
          NextDialogue = 51009478,
          SpeakNpcId = 700313,
          Subtitle = "Trying to poison the sacred bond between Ms Violetta and her loyal fans!? Not on my watch — I'll make you regret it!"
        },
        [51009478] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais qu’est-ce que vous racontez... ?",
          DialogueId = 51009478,
          GUID = "7FB2667C",
          NextDialogue = 51009479,
          SpeakNpcId = 100001,
          Subtitle = "What's your problem...?",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          }
        },
        [51009479] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "<I>Mieux vaut calmer ce fan délirant avant que les choses ne dégénèrent.</>",
          DialogueId = 51009479,
          GUID = "7FB266A6",
          SpeakNpcId = 100001,
          Subtitle = "(Alright. Best calm this delusional man down first.)"
        },
        [51009480] = {
          Camera = "112.706055,-213.83313,198.990479,0.000058,-8.794134,109.594849,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Violetta... Je suis désolé... Je suis trop faible pour te protéger...",
          DialogueId = 51009480,
          GUID = "7FB266D0",
          NextDialogue = 51009481,
          SpeakNpcId = 700313,
          Subtitle = "Ms Violetta... I'm sorry... I was just... not strong enough to protect you...",
          TalkActionId = {
            [1] = "700313:Stop01_Start"
          }
        },
        [51009481] = {
          Camera = "172.162109,534.255371,170.810547,0.000068,-3.594264,-113.598976,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est bon, vous avez fini ? Regardez plutôt ceci.",
          DialogueId = 51009481,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
          FacialId = {
            [1] = "100001:Angry01"
          },
          GUID = "7FB266FA",
          NextDialogue = 51009482,
          SpeakNpcId = 100001,
          Subtitle = "Are you done? Here. Take a look at this.",
          TalkActionId = {
            [1] = "100001:Give",
            [2] = "700313:Stop01_End"
          }
        },
        [51009482] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est... c’est le ruban de Violetta ? Celui qu’elle porte depuis sa première représentation, il y a plus de dix ans...",
          DialogueId = 51009482,
          GUID = "7FB26724",
          NextDialogue = 51009483,
          SpeakNpcId = 700313,
          Subtitle = "This... this is her ribbon. She's worn it since her debut, over ten years ago...",
          TalkActionId = {
            [1] = "700313:Shock_Start"
          }
        },
        [51009483] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vous arrivez à le reconnaître aussi vite ?",
          DialogueId = 51009483,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB2674E",
          NextDialogue = 51009484,
          SpeakNpcId = 100001,
          Subtitle = "You recognised it that quickly?",
          TalkActionId = {
            [1] = "100001:Disagree"
          }
        },
        [51009484] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bien sûr que oui... Pourquoi est-ce que je raconte tout ça, d’ailleurs...",
          DialogueId = 51009484,
          GUID = "7FB26778",
          NextDialogue = 51009485,
          SpeakNpcId = 700313,
          Subtitle = "Of course I did... Ugh. Why am I even wasting my breath?",
          TalkActionId = {
            [1] = "700313:Shock_End"
          }
        },
        [51009485] = {
          ContentFR = "Si c’est toi qui le portes, alors ça veut dire que j’ai vraiment été rejeté. Je ne la dérangerai plus. Je vous souhaite tout le bonheur du monde.",
          DialogueId = 51009485,
          GUID = "7FB267A2",
          NextOptions = {
            [1] = 510093951,
            [2] = 510093952
          },
          SpeakNpcId = 700313,
          Subtitle = "If she gave you this... then I guess I've got no chance. I won't bother her again. Hope you two are happy together."
        },
        [51009486] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Inutile d’en dire plus... Laisse donc un cœur brûlant pleurer seul dans l’ombre...",
          DialogueId = 51009486,
          GUID = "7FB267CC",
          NextDialogue = 51009487,
          SpeakNpcId = 700313,
          Subtitle = "Say no more. Let a broken heart weep alone in the dark...",
          TalkActionId = {
            [1] = "700313:Stop01_Start"
          }
        },
        [51009487] = {
          Camera = "92.173828,227.503815,153.63623,0.000067,-3.594264,-113.599007,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Le soldat ne dit plus rien. Il se contente de pleurer en silence... Mieux vaut le laisser tranquille un moment.",
          DialogueId = 51009487,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB267F6",
          SpeakNpcId = 100001,
          Subtitle = "(He won't say another word... just keeps sobbing. Best to give him some space.)"
        },
        [51009488] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Madame Violetta, me revoilà.",
          DialogueId = 51009488,
          GUID = "7FB26820",
          NextDialogue = 51009489,
          SpeakNpcId = 100001,
          Subtitle = "Ms Violetta — I'm back.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009489] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196657,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci pour ton aide. J’en déduis que l’affaire est réglée ?",
          DialogueId = 51009489,
          FacialId = {
            [1] = "700300:CM_Happy01"
          },
          GUID = "7FB2684A",
          NextDialogue = 51009490,
          SpeakNpcId = 700300,
          Subtitle = "Thank you. I take it the matter's been settled?",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700300:Talk02_Start"
          }
        },
        [51009490] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui. Il ne viendra plus t’importuner. Voici ton ruban — sans lui, j’aurais probablement été coincé dans cette histoire encore un bon moment.",
          DialogueId = 51009490,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon01.T_Guide_ChapterFire_Ribbon01'}",
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "7FB26874",
          NextDialogue = 51009491,
          SpeakNpcId = 100001,
          Subtitle = "Yeah. He won't be bothering you again. Here's your ribbon — I doubt it would've gone so smoothly without it.",
          TalkActionId = {
            [1] = "700300:Talk02_End",
            [2] = "100001:Give"
          }
        },
        [51009491] = {
          ContentFR = "J’ai entendu dire que tu le portes depuis tes débuts... il y a plus de dix ans ?",
          DialogueId = 51009491,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2689E",
          NextDialogue = 51009492,
          SpeakNpcId = 100001,
          Subtitle = "I heard you've worn this since your debut... over a decade ago?",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009492] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196719,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est exact. C’est un souvenir qu’une amie très chère m’a laissé. Elle était brillante, mais le destin ne l’a pas épargnée...",
          DialogueId = 51009492,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB268C8",
          NextDialogue = 51009493,
          SpeakNpcId = 700300,
          Subtitle = "Yes. It was a keepsake from a dear friend of mine. She was brilliant, yet ill-favoured by fate...",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700300:Sigh_Start"
          }
        },
        [51009493] = {
          ContentFR = "Pour certaines raisons, elle n’a jamais pu accomplir son rêve. Moi, en revanche, j’en ai eu l’opportunité, alors j’ai voulu qu’elle brille à mes côtés, sur scène.",
          DialogueId = 51009493,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB268F2",
          NextDialogue = 51009494,
          SpeakNpcId = 700300,
          Subtitle = "She never got the chance to realise her dream... but I did. I only hoped to share the spotlight with her.",
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009494] = {
          ContentFR = "C’est pourquoi, lors de ma toute première représentation, j’ai conçu moi-même l’affiche : une image en noir et blanc, traversée d’un unique éclat de violet.",
          DialogueId = 51009494,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2691C",
          NextDialogue = 51009495,
          SpeakNpcId = 700300,
          Subtitle = "When I debuted, I designed my own poster — black and white, save for one vivid streak of violet.",
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009495] = {
          ContentFR = "Tu as sans doute déjà entendu ce surnom — « Violetta aux mille visages ». Grâce à mon talent pour le maquillage, je peux me transformer entièrement et incarner chaque rôle avec un visage différent.",
          DialogueId = 51009495,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB26946",
          NextDialogue = 51009496,
          SpeakNpcId = 700300,
          Subtitle = "You've likely heard the name \"Violetta of a Thousand Faces.\" With my skills in makeup, I can become anyone for the stage — taking on a different face for every role I play."
        },
        [51009496] = {
          ContentFR = "Mais il y a une chose qui ne change jamais : ce ruban. Je le porte à chacune de mes représentations. <H>Il est devenu ma signature.</>",
          DialogueId = 51009496,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB26970",
          NextDialogue = 51009497,
          SpeakNpcId = 700300,
          Subtitle = "But one thing never changes: this ribbon. I wear it every time. It's become my signature.",
          TalkActionId = {
            [1] = "700300:Talk02_End"
          }
        },
        [51009497] = {
          Camera = "6.950195,47.361328,152.822266,0.000007,-4.600037,-165.990051,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je vois...",
          DialogueId = 51009497,
          FacialId = {
            [1] = "100001:Unhappy02"
          },
          GUID = "7FB2699A",
          NextDialogue = 51009498,
          SpeakNpcId = 100001,
          Subtitle = "I see..."
        },
        [51009498] = {
          ContentFR = "Professeur !",
          DialogueId = 51009498,
          GUID = "7FB269C4",
          LookAt = {
            [1] = "100001:n(700306)",
            [2] = "700300:n(700306)"
          },
          NextDialogue = 51009499,
          SpeakNpcId = 700306,
          Subtitle = "Ms Violetta!"
        },
        [51009499] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196657,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Fane, je t’ai déjà dit de ne pas crier ainsi.",
          DialogueId = 51009499,
          FacialId = {
            [1] = "700300:CM_Angry01"
          },
          GUID = "7FB269EE",
          NextDialogue = 51009500,
          SpeakNpcId = 700300,
          Subtitle = "Fane — have I not taught you to mind your volume?",
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009500] = {
          Camera = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je suis désolé... mais tu dois absolument voir ça !",
          DialogueId = 51009500,
          GUID = "7FB26A18",
          NextDialogue = 51009501,
          Scripts = [[
PARA{
PlayOrStopBGM{PlayType{"Play"},SoundType{"SOUND_BGM"},EventPath{"event:/bgm/cbt02/0043_story_empire"}},
SEQ{
MoveTo{ActorId{700306},TargetPoint{"QuestPoint_Fane_2002300701"},MoveSpeed{250},Visibility{"Show"}},
MoveTo{ActorId{700306},TargetPoint{"QuestPoint_Fane_2002300702"},MoveSpeed{250},Visibility{"Show"}},
TurnTo{TurnToDescription{"700306:n(700300)"}}
}
}]],
          SpeakNpcId = 700306,
          Subtitle = "Sorry... but you have to see this!"
        },
        [51009501] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Encore une lettre ? Pourtant, je l’avais bien averti...",
          DialogueId = 51009501,
          FacialId = {
            [1] = "700300:CM_Angry01",
            [2] = "100001:Angry01"
          },
          GUID = "7FB26A42",
          NextDialogue = 51009502,
          SpeakNpcId = 100001,
          Subtitle = "Another letter? I thought I'd already scared him off...",
          TalkActionId = {
            [1] = "700306:Give",
            [2] = "100001:Think_Start",
            [3] = "700300:Confident_End"
          }
        },
        [51009502] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196719,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51009502,
          FacialId = {
            [1] = "700300:CM_Shock01"
          },
          GUID = "7FB26A6C",
          NextDialogue = 51009503,
          SpeakNpcId = 700300,
          Subtitle = "..."
        },
        [51009503] = {
          ContentFR = "Madame Violetta ?",
          DialogueId = 51009503,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB26A96",
          LookAt = {
            [1] = "100001:n(700300)",
            [2] = "700300:n(100001)"
          },
          NextDialogue = 51009504,
          SpeakNpcId = 100001,
          Subtitle = "Ms Violetta?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009504] = {
          ContentFR = "Seize ans... Cela fait déjà seize ans... Mais pourquoi... pourquoi s’en prendre à des innocents ?",
