          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB26AC0",
          NextDialogue = 51009505,
          SpeakNpcId = 700300,
          Subtitle = "I didn't realise it's been sixteen years... But why? Why hurt someone who had nothing to do with it...?",
