          SpeakNpcId = 700301,
          Subtitle = "Ah... Lars, was it? That boy's a worrier.",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009635] = {
          ContentFR = "Je voulais simplement revoir cet endroit... Autrefois, les Souillés l’infestaient et on ne pouvait pas approcher.",
          DialogueId = 51009635,
          FacialId = {
            [1] = "700301:CM_Idle"
          },
          GUID = "7FB2803E",
          NextDialogue = 51009636,
          SpeakNpcId = 700301,
          Subtitle = "I just... wanted to revisit this old pit. I remember it swarming with monsters — no way to get near."
        },
        [51009636] = {
          ContentFR = "Mais j’ai entendu dire {性别:qu’un Chasseur de Phoxène très talentueux|qu’une Chasseuse de Phoxène très talentueuse} les avait éliminés... Alors j’ai profité de l’occasion pour revenir.",
          DialogueId = 51009636,
          GUID = "7FB28068",
          NextOptions = {
            [1] = 510096361,
            [2] = 510096362
          },
          SpeakNpcId = 700301,
          Subtitle = "Then I heard a skilled Phoxhunter had cleared them out, so... I figured it was safe enough to come back.",
          TalkActionId = {
            [1] = "700301:Explain02_End"
          }
        },
        [51009637] = {
          ContentFR = "Vraiment... ? Je te remercie — <I>kof, kof !</>",
          DialogueId = 51009637,
          GUID = "7FB28092",
          NextDialogue = 51009638,
          SpeakNpcId = 700301,
          Subtitle = "Is that so...? Thank you, truly—*cough*"
        },
        [51009638] = {
          ContentFR = "Désolé... Je dois aller un peu plus loin. Merci d’être venu jusqu’ici, mais dis à Lars que tout va bien. Je laisserai ta récompense aux Asphodèles plus tard. <I>Kof...</>",
          DialogueId = 51009638,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB280BC",
          NextDialogue = 51009639,
          SpeakNpcId = 700301,
          Subtitle = "Sorry... I need to press on a bit further in. Thank you for coming all this way. Please tell Lars I'm okay. I'll leave your reward for the commission at The Asphodel later... *cough*"
        },
        [51009639] = {
          ContentFR = "Je n’ai éliminé que le plus gros des Souillés. Il pourrait encore en rester. Dans ton état, tu ne devrais pas avancer seul. Où veux-tu aller ? Je vais t’accompagner.",
          DialogueId = 51009639,
          GUID = "7FB280E6",
          NextDialogue = 51009640,
          SpeakNpcId = 100001,
          Subtitle = "I've only taken care of the largest one. There might still be Filthoids inside. You're not in any shape to explore alone. Where were you headed? Let me walk with you."
        },
        [51009640] = {
          ContentFR = "Tu... ferais ça ?",
          DialogueId = 51009640,
          FacialId = {
            [1] = "700301:CM_Shock01"
          },
          GUID = "7FB28110",
          NextDialogue = 51009641,
          SpeakNpcId = 700301,
          Subtitle = "You'd... do that?",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009641] = {
          ContentFR = "Oui. J’ai promis à Lars de te ramener sain et sauf.",
          DialogueId = 51009641,
          GUID = "7FB2813A",
          NextDialogue = 51009642,
          SpeakNpcId = 100001,
          Subtitle = "I promised Lars I'd bring you home safely."
        },
        [51009642] = {
          ContentFR = "Merci... merci, jeune {性别:ami|amie}.",
          DialogueId = 51009642,
          FacialId = {
            [1] = "700301:CM_Smile01"
          },
          GUID = "7FB28164",
          SpeakNpcId = 700301,
          Subtitle = "Thank you... thank you, kind soul.",
          TalkActionId = {
            [1] = "700301:Explain02_End"
          }
        },
        [51009643] = {
          Camera = "-375.460938,260.694336,170.375488,0.000148,-11.001406,-38.598434,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci, {性别:jeune homme|jeune femme}...",
          DialogueId = 51009643,
          FacialId = {
            [1] = "700301:CM_Smile01"
          },
          GUID = "7FB2818E",
          NextDialogue = 51009644,
          SpeakNpcId = 700301,
          Subtitle = "Thank you, young one...",
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009644] = {
          Camera = "704.804688,1549.59082,762.798828,0.000162,-10.801759,-103.40123,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est encore plus délabré que dans mes souvenirs...",
          DialogueId = 51009644,
          FinalCamera = "704.804688,1549.59082,762.798828,0.000163,-10.801759,-103.401352,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB281B8",
          NextDialogue = 51009645,
          SpeakNpcId = 700301,
          Subtitle = "It's even more run-down than I'd imagined...",
          ToFinalCameraBlendTime = 5
        },
        [51009645] = {
          Camera = "949.248047,585.90332,736.995117,0.000167,0.198089,-138.598633,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "La porte principale est verrouillée. Heureusement, on peut encore passer par ce tuyau...",
          DialogueId = 51009645,
          GUID = "7FB281E2",
          SpeakNpcId = 700301,
          Subtitle = "Main gate's locked, too. Good thing this pipe still lets us through..."
        },
        [51009646] = {
          ContentFR = "<I>Kof... kof... kof...</>",
          DialogueId = 51009646,
          GUID = "7FB2820C",
          NextDialogue = 51009647,
          SpeakNpcId = 700301,
          Subtitle = "*cough* *cough* *cough*..."
        },
        [51009647] = {
          ContentFR = "Ça va ?",
          DialogueId = 51009647,
          GUID = "7FB28236",
          NextDialogue = 51009648,
          SpeakNpcId = 100001,
          Subtitle = "You alright?"
        },
        [51009648] = {
          ContentFR = "Je... <I>kof</> ça va... Continuons. L’endroit que je cherche est tout près.",
          DialogueId = 51009648,
          GUID = "7FB28260",
          NextDialogue = 51009649,
          SpeakNpcId = 700301,
          Subtitle = "I'm f—*cough*—fine... Let's keep moving. The place I'm looking for is just ahead."
        },
        [51009649] = {
          ContentFR = "Tu sembles bien connaître les lieux.",
          DialogueId = 51009649,
          GUID = "7FB2828A",
          NextDialogue = 51009650,
          SpeakNpcId = 100001,
          Subtitle = "You seem to know this place well."
        },
        [51009650] = {
          ContentFR = "Oui... J’étais mineur ici. Il y a seize ans, je marchais chaque jour dans ces galeries.",
          DialogueId = 51009650,
          GUID = "7FB282B4",
          NextDialogue = 51009651,
          SpeakNpcId = 700301,
          Subtitle = "I do... I used to be a miner here. Sixteen years ago, I walked this path every day."
        },
        [51009651] = {
          ContentFR = "On passait dix, douze heures par jour là-dessous... Je connaissais chaque recoin par cœur, même les yeux fermés.",
          DialogueId = 51009651,
          GUID = "7FB282DE",
          SpeakNpcId = 700301,
          Subtitle = "Back then, we'd spend ten, twelve hours down here... I knew every turn — even with my eyes closed."
        },
        [51009652] = {
          ContentFR = "Mince... Il y a des Souillés tout autour...",
          DialogueId = 51009652,
          GUID = "7FB28308",
          SpeakNpcId = 700301,
          Subtitle = "Darn it... it's surrounded by Filthoids..."
        },
        [51009653] = {
          Camera = "-273.187012,-303.795898,131.41748,0.000022,-13.001005,53.600559,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Heureusement... Elle n’a pas été endommagée. Merci, vraiment.",
          DialogueId = 51009653,
          GUID = "7FB28332",
          NextDialogue = 51009654,
          SpeakNpcId = 700301,
          Subtitle = "Thank goodness... It's still intact. Thank you, truly."
        },
        [51009654] = {
          Camera = "-273.187012,-303.795898,131.41748,0.000022,-13.001005,53.600559,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Sig... mon vieil ami. Je suis venu te voir...",
          DialogueId = 51009654,
          FinalCamera = "-61.812988,-45.275879,85.529785,0.000021,-12.800989,58.799252,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2835C",
          NextDialogue = 51009655,
          SpeakNpcId = 700301,
          Subtitle = "Sig... my old friend. I've come to see you...",
          ToFinalCameraBlendTime = 5
        },
        [51009655] = {
          ContentFR = "C’est... une tombe ?",
          DialogueId = 51009655,
          GUID = "7FB28386",
          NextDialogue = 51009656,
          SpeakNpcId = 100001,
          Subtitle = "Is this... a grave?"
        },
        [51009656] = {
          ContentFR = "On dirait un triste tas de pierres, hein ?",
          DialogueId = 51009656,
          GUID = "7FB283B0",
          NextDialogue = 51009657,
          SpeakNpcId = 700301,
          Subtitle = "Doesn't look like much, does it?"
        },
        [51009657] = {
          Camera = "391.647461,354.068359,51.502441,0.000019,-5.200888,-159.003296,40.0,565.324158,false,Manual,2.8",
          ContentFR = "Il disait que j’étais son meilleur ami... et tout ce que j’ai pu lui offrir, c’est ce petit lopin de terre misérable.",
          DialogueId = 51009657,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB283DA",
          NextDialogue = 51009658,
          SpeakNpcId = 700301,
          Subtitle = "He called me his best mate... and this — this sorry little spot — is all I could manage for him.",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009658] = {
          ContentFR = "Attends... c’est... Non... Pourquoi... ?",
          DialogueId = 51009658,
          FacialId = {
            [1] = "700301:CM_Shock01"
          },
          GUID = "7FB28404",
          NextDialogue = 51009659,
          SpeakNpcId = 700301,
          Subtitle = "Wait... is that—!? No... Why...?",
          TalkActionId = {
            [1] = "700301:Shock_Start"
          }
        },
        [51009659] = {
          ContentFR = "Le visage de Donat, livide quelques instants plus tôt, se crispe soudain. Ses veines ressortent, son regard empli de choc et de douleur. Tu suis ses yeux — et vois, posé contre la pierre, un ruban violet.",
          DialogueId = 51009659,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon02.T_Guide_ChapterFire_Ribbon02'}",
          GUID = "7FB2842E",
          NextDialogue = 51009660,
          Subtitle = "(The sick man's face — ashen moments ago — suddenly stiffens, veins standing taut beneath his skin, his eyes locked in shock and disbelief. Following his gaze, you spot it: a violet ribbon, lying untouched beside the gravestone.)"
        },
        [51009660] = {
          Camera = "-61.812988,-45.275879,85.529785,0.000021,-12.800989,58.799252,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Violette... pourquoi es-tu revenue ?",
          DialogueId = 51009660,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB28458",
          NextDialogue = 51009661,
          SpeakNpcId = 700301,
          Subtitle = "Violet... why have you come back?",
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          },
          TurnTo = {
            [1] = "100001:n(700301)"
          }
        },
        [51009661] = {
          Camera = "-160.715332,330.500977,58.830566,0.00003,-6.800997,-43.798355,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Violette... ? Qui est-ce ?",
          DialogueId = 51009661,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28482",
          NextDialogue = 51009662,
          SpeakNpcId = 100001,
          Subtitle = "Violet? Who's that?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009662] = {
          Camera = "201.632812,149.822754,39.556641,0.000044,-1.60086,173.405228,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "<I>Soupir...</> {性别:Jeune ami|Jeune amie}, accepterais-tu d’écouter quelques histoires d’un autre temps ?",
          DialogueId = 51009662,
          GUID = "7FB284AC",
          NextDialogue = 51009663,
          SpeakNpcId = 700301,
          Subtitle = "Ah... would you humour an old man for a moment? I've a few old stories to tell.",
          TalkActionId = {
            [1] = "700301:Sigh_End",
            [2] = "100001:Talk02_End"
          },
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009663] = {
          Camera = "-160.715332,330.500977,58.830566,0.00003,-6.800997,-43.798355,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Avec plaisir. Mais rentrons d’abord, d’accord ? Lars doit encore s’inquiéter.",
          DialogueId = 51009663,
          GUID = "7FB284D6",
          NextDialogue = 51009664,
          SpeakNpcId = 100001,
          Subtitle = "I'd love to. But let's head back first, alright? Lars must be worried sick."
        },
        [51009664] = {
          Camera = "201.632812,149.822754,39.556641,0.000044,-1.60086,173.405228,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui... oui, tu as raison. Allons-y.",
          DialogueId = 51009664,
          GUID = "7FB28500",
          SpeakNpcId = 700301,
          Subtitle = "Yes... yes, you're right. Let's go.",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009665] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oncle Donat, enfin te voilà !",
          DialogueId = 51009665,
          GUID = "7FB2852A",
          NextDialogue = 51009666,
          SpeakNpcId = 700303,
          Subtitle = "Uncle Donat — you're back!",
          TurnTo = {
            [1] = "700303:n(700301)",
            [2] = "700301:n(700303)",
            [3] = "100001:n(700303)"
          }
        },
        [51009666] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Désolé, petit... Je t’ai encore inquiété — <I>kof... kof kof...</>",
          DialogueId = 51009666,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB28554",
          NextDialogue = 51009667,
          SpeakNpcId = 700301,
          Subtitle = "Sorry, lad... made you worry again — *cough*",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009667] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu tousses encore ! Viens, je vais t’emmener chez le médecin.",
          DialogueId = 51009667,
          GUID = "7FB2857E",
          NextDialogue = 51009668,
          SpeakNpcId = 700303,
          Subtitle = "You're coughing again! Come on — let me take you to a doctor.",
          TalkActionId = {
            [1] = "700303:Talk02_Start"
          }
        },
        [51009668] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non... inutile... C’est ma punition. Rien ne pourra la soigner.",
          DialogueId = 51009668,
          GUID = "7FB285A8",
          NextDialogue = 51009669,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 700301,
          Subtitle = "No, no need... This is what I deserve. No cure's going to fix it.",
          TalkActionId = {
            [1] = "700303:Talk02_End"
          }
        },
        [51009669] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ne dis pas ça, Oncle Donat...",
          DialogueId = 51009669,
          GUID = "7FB285D2",
          NextDialogue = 51009670,
          SpeakNpcId = 700303,
          Subtitle = "Don't say that, Uncle Donat...",
          TalkActionId = {
            [1] = "700303:Confident_Start"
          }
        },
        [51009670] = {
          ContentFR = "Tu te souviens ? Cet hiver particulièrement froid, où je devais dormir près des conduits d’évacuation de l’usine pour ne pas geler... Toi aussi tu grelottais de froid, mais tu m’as donné ton unique manteau.",
          DialogueId = 51009670,
          GUID = "7FB285FC",
          NextDialogue = 51009671,
          SpeakNpcId = 700303,
          Subtitle = "Remember that winter, when I had to sleep next to the factory vents just to stay warm? You were freezing too — and still gave me the only padded coat you had."
        },
        [51009671] = {
          ContentFR = "Tout le monde dans la rue sait à quel point tu es quelqu’un de bien ! Alors pourquoi répètes-tu toujours que tu mérites ce qui t’arrive ? C’est faux !",
          DialogueId = 51009671,
          GUID = "7FB28626",
          LookAt = {
            [1] = "100001:n(700301)"
          },
          NextDialogue = 51009672,
          SpeakNpcId = 700303,
          Subtitle = "Everyone round here knows what a good person you are! So why do you keep saying you deserve this? It's just not true!"
        },
        [51009672] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Est-ce que ça a un rapport avec les « vieilles histoires » dont tu voulais me parler ?",
          DialogueId = 51009672,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28650",
          LookAt = {
            [1] = "700301:n(100001)"
          },
          NextDialogue = 51009673,
          SpeakNpcId = 100001,
          Subtitle = "...Does this have to do with the \"old stories\" you wanted to tell?",
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "700301:Explain02_End"
          }
        },
        [51009673] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui... Tout a commencé il y a seize ans.",
          DialogueId = 51009673,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB2867A",
          NextDialogue = 51009674,
          SpeakNpcId = 700301,
          Subtitle = "Mm. Sixteen years back...",
          TalkActionId = {
            [1] = "700301:Talk02_Start",
            [2] = "700303:Confident_End"
          }
        },
        [51009674] = {
          Camera = "51.153076,68.407227,128.048828,0.000057,-5.000518,-77.201683,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Comme bien des chapitres ennuyeux de ma vie, mes années de mineur n’étaient pas les pires, mais elles n’avaient rien de glorieux non plus. Des journées longues à s’en épuiser, juste de quoi mettre du pain sur la table.",
          DialogueId = 51009674,
          GUID = "7FB286A4",
          NextDialogue = 51009675,
          SpeakNpcId = 700301,
          Subtitle = "Like every other dreary chapter of my life, the years I spent as a miner weren't good, but they weren't the worst either. Long days of grind, just enough to wear you down, just enough to put bread on the table."
        },
        [51009675] = {
          ContentFR = "Quand j’y repense... Même si les grands pontes ne nous traitaient jamais avec justice, c’étaient peut-être les jours les plus paisibles de mon existence...",
          DialogueId = 51009675,
          GUID = "7FB286CE",
          NextDialogue = 51009676,
          SpeakNpcId = 700301,
          Subtitle = "Looking back... even though the bigwigs never treated us fairly, those might've been the least troubled days I ever had..."
        },
        [51009676] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais mon ami Sig, lui, n’a pas eu cette chance. Sa sœur Violette — sa seule famille — est tombée malade. Elle n’avait que dix-huit ans.",
          DialogueId = 51009676,
          GUID = "7FB286F8",
          NextDialogue = 51009677,
          SpeakNpcId = 700301,
          Subtitle = "But my friend Sig... he wasn't so lucky. His little sister, Violet — the only family he had — fell ill. Only eighteen, that girl..."
        },
        [51009677] = {
          ContentFR = "Et quand tu crois que les choses ne peuvent pas empirer... elles le font toujours.",
          DialogueId = 51009677,
          GUID = "7FB28722",
          NextDialogue = 51009678,
          SpeakNpcId = 700301,
          Subtitle = "And just when you think things can't get worse... they usually do."
        },
        [51009678] = {
          ContentFR = "La production de Phoxène à la Fosse de Glevum diminuait de jour en jour... et nos salaires fondaient avec elle. Le pain blanc est devenu gris, puis noir... jusqu’à être mélangé de son et de sciure.",
          DialogueId = 51009678,
          GUID = "7FB2874C",
          NextDialogue = 51009679,
          SpeakNpcId = 700301,
          Subtitle = "Phoxene from Glevum Pit grew scarcer by the day — and so did our wages. White bread became dust-stained bread... then even that was bulked with husks and sawdust."
        },
        [51009679] = {
          ContentFR = "Pour Sig, qui vivait déjà au jour le jour, la maladie de Violette sonnait comme un arrêt de mort.",
          DialogueId = 51009679,
          GUID = "7FB28776",
          NextDialogue = 51009680,
          SpeakNpcId = 700301,
          Subtitle = "For Sig — barely making ends meet — Violet falling ill was like hearing her death sentence out loud.",
          TalkActionId = {
            [1] = "700301:Talk02_End"
          }
        },
        [51009680] = {
          ContentFR = "Je me souviens encore de cette aube. Sig avait réussi à récupérer de l’alcool bon marché auprès des ouvriers, et nous étions assis sur les pierres devant la mine, à boire bouteille après bouteille.",
          DialogueId = 51009680,
          GUID = "7FB287A0",
          NextDialogue = 51009681,
          SpeakNpcId = 700301,
          Subtitle = "I still remember that dawn. Sig scrounged up cheap liquor from the lads, and we sat on the stone outside the pit, knocking them back one bottle at a time.",
          TalkActionId = {
            [1] = "700301:Talk01_Start"
          }
        },
        [51009681] = {
          ContentFR = "Il pleurait comme un enfant, racontant comment ils avaient toujours compté l’un sur l’autre. Parfois il fredonnait les chansons préférées de Violette... parfois il jurait à voix basse contre Fabrice Ruthford.",
          DialogueId = 51009681,
          GUID = "7FB287CA",
          NextDialogue = 51009682,
          SpeakNpcId = 700301,
          Subtitle = "He cried like a child, rambling on about how the two of them had always relied on each other. One moment he was softly humming her favourite songs... the next, muttering curses at Fabrice Ruthford through gritted teeth."
        },
        [51009682] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Fabrice Ruthford ? C’est qui ?",
          DialogueId = 51009682,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB287F4",
          NextDialogue = 51009683,
          SpeakNpcId = 100001,
          Subtitle = "Who's that?",
          TalkActionId = {
            [1] = "100001:Talk03_Start",
            [2] = "700301:Talk01_End"
          }
        },
        [51009683] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Le responsable de la Fosse de Glevum, un haut gradé des Éolipyliens.",
          DialogueId = 51009683,
          GUID = "7FB2881E",
          NextDialogue = 51009684,
          SpeakNpcId = 700301,
          Subtitle = "An officer at The Aeolipile, the one who ran Glevum Pit back then.",
          TalkActionId = {
            [1] = "700301:Talk02_Start"
          }
        },
        [51009684] = {
          ContentFR = "Je lui ai tapé sur l’épaule et j’ai dit : « À quoi bon le maudire ? On n’est que des moins que rien. Si t’as du cran, pourquoi ne pas l’enlever et lui prendre son argent toi-même ? »",
          DialogueId = 51009684,
          GUID = "7FB28848",
          NextDialogue = 51009685,
          SpeakNpcId = 700301,
          Subtitle = "I remember clapping him on the shoulder and saying, \"What good does cursing him do? We're just nobodies. If you've got guts, why not grab the man himself and get the money straight from his pocket?\"",
          TalkActionId = {
            [1] = "700301:Talk02_End"
          }
        },
        [51009685] = {
          ContentFR = "... Seize ans ont passé, et je me demande toujours : si je n’avais pas été ivre ce jour-là, si je n’avais pas sorti de telles idioties... tout cela serait-il arrivé ?",
          DialogueId = 51009685,
          GUID = "7FB28872",
          NextDialogue = 51009686,
          SpeakNpcId = 700301,
          Subtitle = "...Sixteen years on, I still ask myself — if I hadn't been drunk and mouthing off like that, would any of this have happened?",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009686] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu veux dire... que Sig l’a vraiment fait ?",
          DialogueId = 51009686,
          GUID = "7FB2889C",
          NextDialogue = 51009687,
          SpeakNpcId = 700303,
          Subtitle = "You mean... Sig actually did it?",
          TalkActionId = {
            [1] = "700301:Explain02_End"
          },
          TurnTo = {
            [1] = "700301:n(700303)"
          }
        },
        [51009687] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui. Un jour, il a quitté la fosse sans prévenir. Quand je suis allé chez lui, il avait disparu... et Violette aussi.",
          DialogueId = 51009687,
          GUID = "7FB288C6",
          NextDialogue = 51009688,
          SpeakNpcId = 700301,
          Subtitle = "Yes. One day, he quit the mine without a word. When I went to his house to check on him, both he and Violet were gone.",
          TalkActionId = {
            [1] = "700301:Agree"
          }
        },
        [51009688] = {
          ContentFR = "Au début, j’ai cru qu’il l’avait emmenée ailleurs pour la soigner... Jusqu’à ce qu’une semaine plus tard, je reçoive une lettre de Violette.",
          DialogueId = 51009688,
          GUID = "7FB288F0",
          NextDialogue = 51009689,
          SpeakNpcId = 700301,
          Subtitle = "I thought he'd taken her elsewhere for treatment... until a week later, I received a letter from Violet."
        },
        [51009689] = {
          ContentFR = "Sig et moi étions proches, mais je connaissais à peine sa sœur — elle était toujours clouée au lit. Elle avait dépensé ses dernières pièces pour faire remettre la lettre à la fosse par un Chasseur de Phoxène de passage.",
          DialogueId = 51009689,
          GUID = "7FB2891A",
          NextDialogue = 51009690,
          SpeakNpcId = 700301,
          Subtitle = "Sig and I were close back then, but I hardly knew his sister. She was always bedridden. She spent her last coins getting that letter delivered to the mine via a passing Phoxhunter."
        },
        [51009690] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dans cette lettre, elle expliquait que Sig avait enlevé la fille de l’officier pour obtenir une rançon. Elle me suppliait de l’arrêter avant qu’il ne soit trop tard.",
          DialogueId = 51009690,
          GUID = "7FB28944",
          NextDialogue = 51009691,
          SpeakNpcId = 700301,
          Subtitle = "She said Sig had kidnapped Officer Ruthford's daughter, demanding ransom. She begged me to stop him before it was too late."
        },
        [51009691] = {
          ContentFR = "Il la retenait dans une vieille maison à la périphérie de la cité. Quand je l’ai retrouvé, il était choqué... mais il a tout avoué.",
          DialogueId = 51009691,
          GUID = "7FB2896E",
          NextDialogue = 51009692,
          SpeakNpcId = 700301,
          Subtitle = "He was holding the girl in an old house on the outskirts. When I found him, he was stunned... but he owned up to it."
        },
        [51009692] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je savais que c’était mes paroles qui avaient ouvert la porte à cette folie. J’étais rongé par le remords. J’ai voulu l’arrêter — vraiment — mais en voyant Violette, si faible qu’elle ne pouvait plus parler... j’ai hésité.",
          DialogueId = 51009692,
          GUID = "7FB28998",
          NextDialogue = 51009693,
          SpeakNpcId = 700301,
          Subtitle = "My drunken rant that night opened a door to a nightmare. I was consumed by regret. I wanted to stop him — I truly did... but when I saw Violet, so frail she could barely speak... I hesitated."
        },
        [51009693] = {
          ContentFR = "Sig m’a supplié d’oublier ce que j’avais vu. Mais l’enquête se resserrait... et la peur... la peur me paralysait.",
          DialogueId = 51009693,
          GUID = "7FB289C2",
          NextDialogue = 51009694,
          SpeakNpcId = 700301,
          Subtitle = "He begged me to pretend nothing had happened. But the investigation was tightening... and the fear... it shook me to my bones."
        },
        [51009694] = {
          ContentFR = "Finalement... finalement...",
          DialogueId = 51009694,
          GUID = "7FB289EC",
          NextDialogue = 51009695,
          SpeakNpcId = 700301,
          Subtitle = "In the end... I—"
        },
        [51009695] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu les as... dénoncés ?",
          DialogueId = 51009695,
          GUID = "7FB28A16",
          NextDialogue = 51009696,
          SpeakNpcId = 100001,
          Subtitle = "You... turned them in?",
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009696] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je n’aurais jamais dû... jamais...",
          DialogueId = 51009696,
          GUID = "7FB28A40",
          NextDialogue = 51009697,
          SpeakNpcId = 700301,
          Subtitle = "I shouldn't have... I never should have!",
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          }
        },
        [51009697] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et ensuite ? Qu’est-ce qui leur est arrivé ?",
          DialogueId = 51009697,
          GUID = "7FB28A6A",
          LookAt = {
            [1] = "700301:n(700303)"
          },
          NextDialogue = 51009698,
          SpeakNpcId = 700303,
          Subtitle = "What happened after that?",
          TalkActionId = {
            [1] = "700301:Sigh_End"
          }
        },
        [51009698] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "L’officier est venu en personne diriger l’arrestation. Sig a résisté... et a accidentellement mis le feu à la maison.",
          DialogueId = 51009698,
          GUID = "7FB28A94",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009699,
          SpeakNpcId = 700301,
          Subtitle = "The officer came himself, leading the arrest. During the struggle, Sig accidentally set the house on fire.",
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009699] = {
          ContentFR = "J’ai foncé à l’intérieur pour les sauver... mais dans la confusion, je n’ai réussi qu’à tirer Violette de là. Son visage était noirci par la suie... seules deux traînées pâles coulaient de ses yeux en larmes.",
          DialogueId = 51009699,
          GUID = "7FB28ABE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009700,
          SpeakNpcId = 700301,
          Subtitle = "I rushed in, trying to save them — but in the chaos, I only managed to get Violet out. Her face was black with soot... only her tears had carved two pale trails down her cheeks."
        },
        [51009700] = {
          ContentFR = "J’avais peur qu’elle soit jugée complice. Alors je l’ai cachée dans un tonneau d’eau, espérant que la Légion ne la trouverait pas.",
          DialogueId = 51009700,
          GUID = "7FB28AE8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009701,
          SpeakNpcId = 700301,
          Subtitle = "I was terrified she'd be punished for her brother's crime. So I hid her in a water barrel, hoping the Legion wouldn't find her."
        },
        [51009701] = {
          ContentFR = "Sig a été arrêté. Quant à la fille de l’officier... il ne restait d’elle qu’un corps calciné dans les décombres.",
          DialogueId = 51009701,
          GUID = "7FB28B12",
          NextDialogue = 51009702,
          SpeakNpcId = 700301,
          Subtitle = "In the end, Sig was caught. And the officer's daughter... all they found was her charred remains in the rubble."
        },
        [51009702] = {
          ContentFR = "Fou de rage, l’officier a ignoré toute procédure judiciaire. Il a exécuté Sig de ses propres mains. Quant à Violette... je lui ai donné toute la prime pour la dénonciation et je l’ai fait sortir clandestinement de Givrelac. J’espérais qu’elle pourrait refaire sa vie ailleurs.",
          DialogueId = 51009702,
          GUID = "7FB28B3C",
          NextDialogue = 51009703,
          SpeakNpcId = 700301,
          Subtitle = "The officer was enraged. He didn't even wait for a trial — he executed Sig with his own hands. As for Violet... I gave her all the bounty money and smuggled her out of Icelake, praying she'd get away from all this."
        },
        [51009703] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je revois encore son visage au moment du départ — marqué par la maladie, mais brûlant de colère. Ce jour-là, elle portait ce ruban violet...",
          DialogueId = 51009703,
          GUID = "7FB28B66",
          NextDialogue = 51009704,
          SpeakNpcId = 700301,
          Subtitle = "I still remember her face when she left — worn thin by sickness, but her eyes were burning with fury. She was wearing this violet ribbon that day..."
        },
        [51009704] = {
          ContentFR = "Elle a dit qu’elle quitterait Givrelac pour toujours. Qu’elle ne voulait plus jamais me revoir.",
          DialogueId = 51009704,
          GUID = "7FB28B90",
          NextDialogue = 51009705,
          SpeakNpcId = 700301,
          Subtitle = "She said she'd leave Icelake for good. Said she never wanted to see me again."
        },
        [51009705] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et comment lui en vouloir ? J’étais l’ivrogne qui a poussé un ami au crime, et le lâche dont la peur a coûté deux vies. Qui voudrait revoir un tel homme ?",
          DialogueId = 51009705,
          FinalCamera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB28BBA",
          LookAt = {
            [1] = "700301:n(100001)"
          },
          NextOptions = {
            [1] = 510095461,
            [2] = 510095462
          },
          SpeakNpcId = 700301,
          Subtitle = "And who could blame her? I was the drunk who doomed a friend and the coward whose fear cost two innocent lives. Why would anyone want to see me again?",
          TalkActionId = {
            [1] = "700301:Explain02_End"
          }
        },
        [51009706] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu as raison.",
          DialogueId = 51009706,
          GUID = "7FB28BE4",
          NextDialogue = 51009709,
          SpeakNpcId = 700301,
          Subtitle = "You're right.",
          TalkActionId = {
            [1] = "700301:Agree"
          }
        },
        [51009707] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est vrai, Oncle Donat, tu as juste fait ce que tu pensais être juste !",
          DialogueId = 51009707,
          GUID = "7FB28C0E",
          NextDialogue = 51009708,
          SpeakNpcId = 700303,
          Subtitle = "Yeah! You just did what you thought was right, Uncle Donat!",
          TalkActionId = {
            [1] = "700303:Angry01_Start"
          }
        },
        [51009708] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est ce que tout le monde me dit... Mais cela ne change rien : deux vies innocentes ont été perdues à cause de moi.",
          DialogueId = 51009708,
          GUID = "7FB28C38",
          NextDialogue = 51009709,
          SpeakNpcId = 700301,
          Subtitle = "That's what they all say. But it doesn't change the fact that two innocent lives were gone because of me.",
          TalkActionId = {
            [1] = "700301:Disagree",
            [2] = "700303:Angry01_End"
          }
        },
        [51009709] = {
          ContentFR = "Je suis tombé gravement malade. Depuis, je n’ai cessé d’aider les autres. Je me suis dit qu’à chaque bonne action, j’expiais un peu plus mes fautes.",
          DialogueId = 51009709,
          GUID = "7FB28C62",
          NextDialogue = 51009710,
          SpeakNpcId = 700301,
          Subtitle = "After that, I got really sick. Then I started doing what I could to help others, trying to make things right. I thought... maybe each good deed could chip away at my sins.",
          TalkActionId = {
            [1] = "700301:Explain01_Start"
          }
        },
        [51009710] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais je vois encore Sig dans mes cauchemars, me fixant de ses yeux emplis de haine. J’entends encore la pauvre Enola hurler dans les flammes. On dit qu’aucune bonté envers les vivants n’obtient le pardon des morts.",
          DialogueId = 51009710,
          GUID = "7FB28C8C",
          NextDialogue = 51009711,
          SpeakNpcId = 700301,
          Subtitle = "But still... I see Sig in my dreams, glaring at me in rage. I hear poor Enola screaming as the fire takes her. They say no kindness to the living will ever buy forgiveness from the dead."
        },
        [51009711] = {
          ContentFR = "Ah... Violette... Est-ce pour ça que tu es revenue à Givrelac ? Parce que, comme moi, tu ne peux pas me pardonner ?",
          DialogueId = 51009711,
          GUID = "7FB28CB6",
          NextDialogue = 51009712,
          SpeakNpcId = 700301,
          Subtitle = "Violet... is that why you came back to Icelake? Because you still can't forgive me... just like I never could?",
          TalkActionId = {
            [1] = "700301:Disagree"
          }
        },
        [51009712] = {
          ContentFR = "Es-tu venue... pour me délivrer de mon fardeau... ?",
          DialogueId = 51009712,
          GUID = "7FB28CE0",
          SpeakNpcId = 700301,
          Subtitle = "Have you come to put me out of my misery...?",
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          }
        },
        [51009713] = {
          ContentFR = "La voix de Donat s’éteint peu à peu. Il s’effondre.",
          DialogueId = 51009713,
          GUID = "7FB28D0A",
          Subtitle = "(His voice trails off. He collapses.)"
        },
        [51009714] = {
          Camera = "564.476807,-378.041016,169.732422,0.00009,-13.999387,141.803299,30.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oncle Donat ?! Réponds-moi !",
          DialogueId = 51009714,
          GUID = "7FB28D34",
          NextDialogue = 51009715,
          Scripts = [[
PARA{
SEQ{
TurnTo{TurnToDescription{"700303:n(700301)"}},
PlayAnimation{ActorId{700303},AnimationId{"Angry01_Start"},Duration{1}}
},
SEQ{
TurnTo{TurnToDescription{"100001:n(700301)"}},
PlayAnimation{ActorId{100001},AnimationId{"Shock_Start"},Duration{1}}
}
}]],
          SpeakNpcId = 700303,
          Subtitle = "Uncle Donat!? Are you alright!?",
          TalkActionId = {
            [1] = "700301:Onground02"
          }
        },
        [51009715] = {
          ContentFR = "Ouf... Il va bien. Il s’est simplement évanoui à cause de l’épuisement et du stress. Reste près de lui — ne le laisse pas repartir.",
          DialogueId = 51009715,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "7FB28D5E",
          LookAt = {
            [1] = "700303:n(100001)"
          },
          NextDialogue = 51009716,
          SpeakNpcId = 100001,
          Subtitle = "Whew... he's fine. Looks like he just fainted from exhaustion and stress. Keep an eye on him — don't let him wander off again.",
          TalkActionId = {
            [1] = "100001:Shock_End",
            [2] = "700303:Angry01_End"
          }
        },
        [51009716] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui... Je vais prévenir tout le monde, on s’occupera de lui ensemble.",
          DialogueId = 51009716,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB28D88",
          NextDialogue = 51009717,
          SpeakNpcId = 700303,
          Subtitle = "Mm. I'll get the others — we'll take care of him together.",
          TalkActionId = {
            [1] = "700303:Talk02_Start"
          },
          TurnTo = {
            [1] = "100001:n(700303)"
          }
        },
        [51009717] = {
          Camera = "391.665527,-299.712891,111.20166,0.000034,-4.800045,133.394577,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dis... je peux te demander quelque chose ?",
          DialogueId = 51009717,
          GUID = "7FB28DB2",
          NextDialogue = 51009718,
          SpeakNpcId = 700303,
          Subtitle = "Um... can I ask you something, {性别:sir|miss}?",
          TalkActionId = {
            [1] = "700303:Talk02_End"
          },
          TurnTo = {
            [1] = "700303:n(100001)"
          }
        },
        [51009718] = {
          Camera = "-204.549316,-144.984375,111.20166,0.000049,-3.59994,24.790976,40.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Qu’y a-t-il ?",
          DialogueId = 51009718,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28DDC",
          NextDialogue = 51009719,
          SpeakNpcId = 100001,
          Subtitle = "What is it?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009719] = {
          Camera = "391.665527,-299.712891,111.20166,0.000034,-4.800045,133.394577,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dis... est-ce que tu crois qu’Oncle Donat est une \"mauvaise\" personne ?",
          DialogueId = 51009719,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB28E06",
          NextOptions = {
            [1] = 510096291,
            [2] = 510096292,
            [3] = 510096293,
            [4] = 510096294
          },
          SpeakNpcId = 700303,
          Subtitle = "Do you think... Uncle Donat is a bad person?",
          TalkActionId = {
            [1] = "700303:Explain02_Start"
          }
        },
        [51009720] = {
          Camera = "174.810547,-35.033203,84.850098,0.000033,-4.400117,168.992874,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... D’accord, c’est ce que tu penses. Je comprends. Merci... Tiens, prends ça — j’ai mis très longtemps à économiser cet argent !",
          DialogueId = 51009720,
          GUID = "7FB28E30",
          NextDialogue = 51009721,
          SpeakNpcId = 700303,
          Subtitle = "So that's what you think... I see. Thank you, {性别:sir|miss}! This is for you — I saved it up for a long time!",
          TalkActionId = {
            [1] = "700303:Give",
            [2] = "100001:Talk02_End"
          }
        },
        [51009721] = {
          Camera = "34.74585,-46.004883,96.84375,0.000042,-1.400134,16.193537,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "<I>Ce ruban violet... il a sans doute été laissé par Violette sur la tombe de Sig.</>",
          DialogueId = 51009721,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28E5A",
          NextDialogue = 51009722,
          SpeakNpcId = 100001,
          Subtitle = "(That violet ribbon... it must've been left by Violet at Sig's grave.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009722] = {
          ContentFR = "<I>Cette jeune fille de dix-huit ans doit désormais être une femme d’âge mûr. Est-elle vraiment revenue à Givrelac ? Il faudrait peut-être se renseigner...</>",
          DialogueId = 51009722,
          GUID = "7FB28E84",
          Scripts = "PlayOrStopBGM{_delay{10},PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 100001,
          Subtitle = "(Sixteen years... she'd be in her thirties by now. Has she really returned? Maybe I should ask around when I get the chance.)"
        },
        [51009723] = {
          Camera = "-1245.721924,-374.627869,402.247803,-8.001631,-17.80077,20.798534,23.337744,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Encore une nuit sans repos... impossible de trouver la paix !",
          DialogueId = 51009723,
          FinalCamera = "-1026.618896,-291.636963,327.767822,-8.001973,-14.000665,19.198555,23.337744,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB28EAE",
          NextDialogue = 51009724,
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{"NvzhuPoint_20023200"}},
PlayFacial{ActorId{100001},FacialId{"Angry01"}}
}]],
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Another restless night... no peace for the weary!",
          ToFinalCameraBlendTime = 3
        },
        [51009724] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ô pauvre âme... es-tu comme moi ? À errer dans ces couloirs glacés, le regard tourné vers l’horizon, cherchant l’éclat d’une étoile née de l’amour et de l’espérance...",
          DialogueId = 51009724,
          GUID = "7FB28ED8",
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "O, wretched soul — do you too wander these icy halls, chasing the distant gleam, yearning for love and a starlit dream?"
        },
        [51009725] = {
          ContentFR = "Tu entends une voix chanter à l’angle d’une rue. Tu regardes autour de toi, mais il n’y a personne. Veux-tu continuer à chercher ?",
          DialogueId = 51009725,
          GUID = "7FB28F02",
          Subtitle = "(From a quiet street corner, you hear a melodic voice — but there's no one in sight. Should you keep looking?)"
        },
        [51009726] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Da... da da...",
          DialogueId = 51009726,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB28F2C",
          NextDialogue = 51009727,
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Da... Da da...",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          }
        },
        [51009727] = {
          ContentFR = "Qui est là ?!",
          DialogueId = 51009727,
          GUID = "7FB28F56",
          NextDialogue = 51009728,
          SpeakNpcId = 100001,
          Subtitle = "Who's there!?"
        },
        [51009728] = {
          ContentFR = "Oh, pardon... je t’ai fait peur ? Je suis là, à cinq pas devant toi. Oui, par ici.",
          DialogueId = 51009728,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB28F80",
          NextDialogue = 51009729,
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Oh — pardon me. I didn't mean to startle you. I'm right here — five steps ahead. Yes, just here.",
          TalkActionId = {
            [1] = "100001:Shock_End"
          }
        },
        [51009729] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bonsoir à toi, âme en peine qui ne trouve pas le sommeil.",
          DialogueId = 51009729,
          GUID = "7FB28FAA",
          NextOptions = {
            [1] = 510096391,
            [2] = 510096392,
            [3] = 510096393
          },
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{"NvzhuPoint_20023201"}},
TurnTo{TurnToDescription{"100001:n(700309)"}}
}]],
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "A good evening to you, sleepless one."
        },
        [51009730] = {
          ContentFR = "Non, tu ne rêves pas. C’est bien moi qui te parle.",
          DialogueId = 51009730,
          GUID = "7FB28FD4",
          NextDialogue = 51009733,
          SpeakNpcId = 700309,
          Subtitle = "It's not just you. I really am talking."
        },
        [51009731] = {
          ContentFR = "Et pourquoi faudrait-il absolument que quelqu’un soit caché ici ? Ne puis-je pas simplement... parler, moi, une humble caisse ?",
          DialogueId = 51009731,
          GUID = "7FB28FFE",
          NextDialogue = 51009733,
          SpeakNpcId = 700309,
          Subtitle = "Must there be someone hiding inside? Can't a crate simply... talk?"
        },
        [51009732] = {
          ContentFR = "Désolée de te décevoir, mais je ne réalise pas de vœux. Je ne suis qu’une simple caisse ordinaire.",
          DialogueId = 51009732,
          GUID = "7FB29028",
          NextDialogue = 51009733,
          SpeakNpcId = 700309,
          Subtitle = "Sorry — I'm just a plain old crate. I don't grant wishes."
        },
        [51009733] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais... comment une caisse peut-elle parler ?",
          DialogueId = 51009733,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29052",
          NextDialogue = 51009734,
          SpeakNpcId = 100001,
          Subtitle = "But... how can a crate talk?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009734] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dis-moi... qu’est-ce qui est le plus difficile, selon toi : chanter ou parler ?",
          DialogueId = 51009734,
          GUID = "7FB2907C",
          NextDialogue = 51009735,
          SpeakNpcId = 700309,
          Subtitle = "If you must ask — tell me this: what's harder, singing or speaking?"
        },
        [51009735] = {
          ContentFR = "Chanter, je suppose.",
          DialogueId = 51009735,
          GUID = "7FB290A6",
          NextDialogue = 51009736,
          SpeakNpcId = 100001,
          Subtitle = "Singing, I suppose."
        },
        [51009736] = {
          ContentFR = "Et pourtant, il existe de petites boîtes à musique qui chantent dès qu’on tourne leur clé. Parler est bien plus simple que chanter, non ? Et moi, je suis bien plus grande et plus robuste qu’une boîte à musique.",
          DialogueId = 51009736,
          GUID = "7FB290D0",
          NextDialogue = 51009737,
          SpeakNpcId = 700309,
          Subtitle = "Little music boxes can sing — simply wind a key and out comes a melody. Since speaking's easier than singing, and I'm larger and better made than any music box..."
        },
        [51009737] = {
          ContentFR = "Alors pourquoi ne pourrais-je pas te parler, tout comme toi, tu me parles en ce moment ?",
          DialogueId = 51009737,
          GUID = "7FB290FA",
          NextDialogue = 51009738,
          SpeakNpcId = 700309,
          Subtitle = "Why shouldn't I be able to talk to you, just as you're talking to me?",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009738] = {
          ContentFR = "Mais...",
          DialogueId = 51009738,
          GUID = "7FB29124",
          NextDialogue = 51009739,
          SpeakNpcId = 100001,
          Subtitle = "But...",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009739] = {
          ContentFR = "Je sais, cela te semble étrange.",
          DialogueId = 51009739,
          GUID = "7FB2914E",
          NextDialogue = 51009740,
          SpeakNpcId = 700309,
          Subtitle = "I understand — you're confused."
        },
        [51009740] = {
          ContentFR = "Tout le monde pense qu’une caisse ne devrait pas parler — tout comme un vieux tronc d’arbre ne devrait que renvoyer l’écho de ta voix. Mais, au fond, dis-moi honnêtement... qui n’a jamais rêvé d’une caisse qui lui répondrait vraiment ?",
          DialogueId = 51009740,
          GUID = "7FB29178",
          NextDialogue = 51009741,
          SpeakNpcId = 700309,
          Subtitle = "People think crates shouldn't talk — like hollow trees, only echoing back your voice. But be honest with yourself: wouldn't you want a crate that actually answers?"
        },
        [51009741] = {
          ContentFR = "Et puis... tu ne m’as pas ouvert tout de suite. Ce qui veut dire qu’au fond de toi, tu voulais peut-être que je te parle, pas vrai ?",
          DialogueId = 51009741,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB291A2",
          NextDialogue = 51009742,
          SpeakNpcId = 700309,
          Subtitle = "You didn't pry me open straight away. That means... part of you wanted me to speak, didn't it?",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          }
        },
        [51009742] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51009742,
          GUID = "7FB291CC",
          NextDialogue = 51009743,
          SpeakNpcId = 100001,
          Subtitle = "...",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009743] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentFR = "On dirait que tu commences à accepter l’idée. Alors... veux-tu bien rester un peu pour discuter ?",
          DialogueId = 51009743,
          GUID = "7FB291F6",
          NextDialogue = 51009744,
          SpeakNpcId = 700309,
          Subtitle = "Seems like you've come to terms with it. So — will you stay a while and talk?",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009744] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "De quoi veux-tu parler ?",
          DialogueId = 51009744,
          FacialId = {
            [1] = "100001:Uninterested01"
          },
          GUID = "7FB29220",
          NextDialogue = 51009745,
          SpeakNpcId = 100001,
          Subtitle = "What do you want to talk about?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009745] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hmm... que dirais-tu de l’opéra donné avant-hier au Théâtre Galea ?",
          DialogueId = 51009745,
          GUID = "7FB2924A",
          NextDialogue = 51009746,
          SpeakNpcId = 700309,
          Subtitle = "Hmm... how about the opera at the Galea Theatre, two nights ago?",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009746] = {
          ContentFR = "Il s’appelait <I>Putini</>. Tu l’as vu ? Qu’as-tu pensé de la voix de la chanteuse principale ?",
          DialogueId = 51009746,
          GUID = "7FB29274",
          NextDialogue = 51009747,
          SpeakNpcId = 700309,
          Subtitle = "It was called Putini. Did you see it? What did you think of the lead's voice?"
        },
        [51009747] = {
          ContentFR = "Tu sais, je ne peux pas aller au théâtre... je ne suis qu’une caisse, après tout.",
          DialogueId = 51009747,
          GUID = "7FB2929E",
          NextDialogue = 51009748,
          SpeakNpcId = 700309,
          Subtitle = "I'm just a crate, after all. I can't go to the theatre."
        },
        [51009748] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{性别:Désolé|Désolée}, je ne l’ai pas vu.",
          DialogueId = 51009748,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB292C8",
          NextDialogue = 51009749,
          SpeakNpcId = 100001,
          Subtitle = "Sorry, I didn't see it.",
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          }
        },
        [51009749] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce n’est pas grave. Personne ne t’en voudra. Mais si un jour tu en as l’occasion, va le voir — c’est une œuvre magnifique. L’héroïne, Putini, est belle, généreuse... et surtout, elle a le courage de poursuivre sa liberté.",
          DialogueId = 51009749,
          GUID = "7FB292F2",
          NextDialogue = 51009750,
          SpeakNpcId = 700309,
          Subtitle = "That's all right. No one's blaming you. But you should see it someday — it's a beautiful piece. The heroine, Putini — she's radiant, kind... and brave enough to chase her freedom."
        },
        [51009750] = {
          ContentFR = "Moi aussi, j’aimerais être comme elle. Mais je ne suis qu’une simple caisse.",
          DialogueId = 51009750,
          GUID = "7FB2931C",
          NextDialogue = 51009751,
          SpeakNpcId = 700309,
          Subtitle = "I want to be like her. But I'm just a crate."
        },
        [51009751] = {
          ContentFR = "Alors j’ai pris une décision.",
          DialogueId = 51009751,
          GUID = "7FB29346",
          NextDialogue = 51009752,
          SpeakNpcId = 700309,
          Subtitle = "So, I made a decision."
        },
        [51009752] = {
          ContentFR = "Quelle décision ?",
          DialogueId = 51009752,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29370",
          NextDialogue = 51009753,
          SpeakNpcId = 100001,
          Subtitle = "What is it?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009753] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je veux partir en mer. Qui a décrété qu’une caisse devait rester dans un coin de rue ? Elle peut devenir un bateau, voguer au gré des flots... Je veux sentir le vent marin, chargé de sel et de sable.",
          DialogueId = 51009753,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2939A",
          NextDialogue = 51009754,
          SpeakNpcId = 700309,
          Subtitle = "I want to set sail. Who says crates must stay on street corners? A crate could become a boat, drifting on the tide... I want to feel the sea wind — rough with salt and sand.",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009754] = {
          ContentFR = "Mais quitter cet endroit signifie aussi tout perdre.",
          DialogueId = 51009754,
          GUID = "7FB293C4",
          NextDialogue = 51009755,
          SpeakNpcId = 700309,
          Subtitle = "But leaving here means losing everything I have."
        },
        [51009755] = {
          ContentFR = "Se libérer de sa cage, c’est aussi perdre son abri. Obtenir la liberté, c’est aussi affronter l’inconnu.",
          DialogueId = 51009755,
          GUID = "7FB293EE",
          NextDialogue = 51009756,
          SpeakNpcId = 700309,
          Subtitle = "To leave the cage... is to leave the shelter. And freedom — well, that means stepping into the unknown."
        },
        [51009756] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors, mon {性别:ami|amie}... dis-moi. Que devrais-je faire ?",
          DialogueId = 51009756,
          GUID = "7FB29418",
          NextOptions = {
            [1] = 510096661,
            [2] = 510096662
          },
          SpeakNpcId = 700309,
          Subtitle = "So tell me, my friend... what do you think I should do?"
        },
        [51009757] = {
          ContentFR = "... Tu as raison.",
          DialogueId = 51009757,
          GUID = "7FB29442",
          NextDialogue = 51009758,
          SpeakNpcId = 700309,
          Subtitle = "...You're right."
        },
        [51009758] = {
          ContentFR = "Merci d’avoir parlé avec une simple caisse, toi, l’âme bienveillante. L’aube approche... et avec elle, la magie qui anime ce vieux bois disparaît.",
          DialogueId = 51009758,
          GUID = "7FB2946C",
          NextDialogue = 51009759,
          SpeakNpcId = 700309,
          Subtitle = "Thank you for keeping a lonely crate company, kind soul. Dawn is close... and with it, the magic in these old timbers begins to fade."
        },
        [51009759] = {
          ContentFR = "Je te souhaite, non pas des nuits d’insomnie moins pénibles... mais que toutes tes nuits soient peuplées de doux rêves.",
          DialogueId = 51009759,
          GUID = "7FB29496",
          SpeakNpcId = 700309,
          Subtitle = "May every sleepless night you face... no — may all your nights be filled with peaceful dreams."
        },
        [51009760] = {
          ContentFR = "Tu entends un léger frémissement — comme une petite fée qui s’envole de la chambre d’un enfant avant le lever du jour. Quand tu reprends tes esprits, Mademoiselle Caisse a disparu.",
          DialogueId = 51009760,
          GUID = "7FB294C0",
          Subtitle = "(You hear a faint tremble — like a pixie slipping from a child's bedside just before dawn.)\n(And when you come back to your senses, Miss Crate is gone.)"
        },
        [51009761] = {
          Camera = "181.495728,-78.722099,88.629395,0.000093,-3.999294,136.804047,30.022871,100000.0,false,DoNotOverride,2.8",
          ContentFR = "<I>Cette voix dans la caisse... Je ne sais pas pourquoi, mais j’ai fini par me laisser entraîner dans sa conversation.</>",
          DialogueId = 51009761,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB294EA",
          NextDialogue = 51009762,
          SpeakNpcId = 100001,
          Subtitle = "(What just happened...? That voice in the crate somehow steered the whole conversation.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009762] = {
          Camera = "-5654.617676,-3244.824707,4837.760742,0.000161,-38.599369,19.822903,27.283031,100000.0,false,DoNotOverride,2.8",
          ContentFR = "<I>C’est sans doute un enfant du quartier qui s’amusait. Je ne peux pas laisser ça sans suite — je devrais poser quelques questions autour de moi.</>",
          DialogueId = 51009762,
          GUID = "7FB29514",
          SpeakNpcId = 100001,
          Subtitle = "(It's probably some local kid messing around... but I can't just leave it. I should ask around.)"
        },
        [51009763] = {
          ContentFR = "Excuse-moi... qui es-tu ? Je t’ai vu tourner dans le coin depuis un moment.",
          DialogueId = 51009763,
          GUID = "7FB2953E",
          NextDialogue = 51009764,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Excuse me... who are you? You've been hanging around my place for a while."
        },
        [51009764] = {
          ContentFR = "Tu cherches à passer une mission ? Suivi, collecte, livraison... j’accepte toutes sortes de missions — tant qu’elles sont légales.",
          DialogueId = 51009764,
          GUID = "7FB29568",
          NextDialogue = 51009765,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Looking to hire someone? I take all kinds of commissions — tracking, foraging, courier work — so long as it's legal."
        },
        [51009765] = {
          ContentFR = "Une mission ?",
          DialogueId = 51009765,
          GUID = "7FB29592",
          NextDialogue = 51009766,
          SpeakNpcId = 100001,
          Subtitle = "Commission?"
        },
        [51009766] = {
          ContentFR = "Hein ? Tu n’es pas là pour m’en confier une ?",
          DialogueId = 51009766,
          GUID = "7FB295BC",
          NextDialogue = 51009767,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Huh? So you're not here to hire me?"
        },
        [51009767] = {
          ContentFR = "Bon... on dirait que la renommée de « Giselle la Chasseuse de Phoxène » n’est pas aussi éclatante que Camilla le prétendait.",
          DialogueId = 51009767,
          GUID = "7FB295E6",
          NextDialogue = 51009768,
          SpeakNpcId = 700302,
          Subtitle = "Alright. I guess Camilla oversold it — \"Giselle the Phoxhunter\" isn't exactly a household name."
        },
        [51009768] = {
          ContentFR = "Giselle la Chasseuse de Phoxène... Oui, ce nom me dit quelque chose.",
          DialogueId = 51009768,
          GUID = "7FB29610",
          NextDialogue = 51009769,
          SpeakNpcId = 100001,
          Subtitle = "Giselle the Phoxhunter... yeah, that does sound familiar."
        },
        [51009769] = {
          ContentFR = "Pas besoin de me flatter pour me faire plaisir.",
          DialogueId = 51009769,
          GUID = "7FB2963A",
          NextDialogue = 51009770,
          SpeakNpcId = 700302,
          Subtitle = "Thanks, but you don't have to say that just to make me feel better."
        },
        [51009770] = {
          ContentFR = "Non... je le pense vraiment.",
          DialogueId = 51009770,
          GUID = "7FB29664",
          NextDialogue = 51009771,
          SpeakNpcId = 100001,
          Subtitle = "No no, I mean it—"
        },
        [51009771] = {
          ContentFR = "Tu racontes à Giselle l’histoire de la caisse qui parlait derrière sa maison.",
          DialogueId = 51009771,
          GUID = "7FB2968E",
          NextDialogue = 51009772,
          Subtitle = "(You tell Giselle about the talking crate behind her house.)"
        },
        [51009772] = {
          ContentFR = "Donc... une caisse derrière chez moi t’a parlé, et t’a conseillé d’aller à l’opéra. Très bien, j’ai compris.",
          DialogueId = 51009772,
