          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "7FB29BCE",
          NextDialogue = 51009804,
          SpeakNpcId = 200003,
          Subtitle = "Looks like you made an interesting friend. I bet there's a good story there.",
          TalkActionId = {
            [1] = "200003:Talk02_Start"
          }
        },
        [51009804] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,false,DoNotOverride,2.8",
