        [51009815] = {
          ContentFR = "Mais... si tu as un peu de temps devant toi, ça vaudrait peut-être le coup d’aller gratter plus loin. Moi aussi, j’aimerais bien connaître le fin mot de l’histoire.",
          DialogueId = 51009815,
          GUID = "7FB29DC6",
          NextDialogue = 51009816,
