          GUID = "7FB29E6E",
          NextDialogue = 51009820,
          SpeakNpcId = 700307,
          Subtitle = "I told you so — I've been saying this from the start!",
          TalkActionId = {
            [1] = "700307:Angry01_Start"
          }
        },
        [51009820] = {
          ContentFR = "On n’aurait jamais dû engager cette femme louche comme préceptrice ! On n’aurait jamais dû laisser Rosalind suivre ces fichus cours de chant !",
          DialogueId = 51009820,
          GUID = "7FB29E98",
          NextDialogue = 51009821,
          SpeakNpcId = 700307,
          Subtitle = "We never should've hired that dubious woman as a tutor! And we never should've let Rosalind take those blasted singing lessons!"
        },
        [51009821] = {
          ContentFR = "C’est toi qui disais qu’il lui fallait une activité pour qu’elle arrête de traîner dehors toute la journée !",
          DialogueId = 51009821,
          FacialId = {
            [1] = "700308:CM_Sad01"
          },
          GUID = "7FB29EC2",
          NextDialogue = 51009822,
          SpeakNpcId = 700308,
          Subtitle = "You were the one who said she needed something to keep her busy — so she wouldn't be out roaming around all day!",
          TalkActionId = {
            [1] = "700308:Explain01_Start"
          }
        },
        [51009822] = {
          ContentFR = "Oui, je voulais qu’elle reste tranquille à la maison — pas qu’elle recommence à courir partout jusqu’à attirer l’attention de ravisseurs !",
          DialogueId = 51009822,
          GUID = "7FB29EEC",
          NextDialogue = 51009823,
          SpeakNpcId = 700307,
          Subtitle = "I meant something to keep her home — not something that'd send her running off again and getting herself kidnapped!",
          TalkActionId = {
            [1] = "700307:Angry01_End",
            [2] = "700308:Explain01_End"
          }
        },
        [51009823] = {
          ContentFR = "Et vous, bande d’incapables ! Vous appelez ça des Veilleurs ? On avait enfin une piste, et parce que vous êtes trop lents, les kidnappeurs se sont enfuis !",
          DialogueId = 51009823,
          GUID = "7FB29F16",
          NextDialogue = 51009824,
          Scripts = [[
PARA{
TurnTo{TurnToDescription{"700307:n(700313)"}},
TurnTo{TurnToDescription{"700308:n(700313)"}}
}]],
          SpeakNpcId = 700307,
          Subtitle = "And you Escort grunts — what use are you!? We finally had a lead, and you lot were too slow — now the kidnappers are gone!"
        },
        [51009824] = {
          ContentFR = "...",
          DialogueId = 51009824,
          GUID = "7FB29F40",
          NextDialogue = 51009825,
          SpeakNpcId = 700313,
          Subtitle = "..."
        },
        [51009825] = {
          ContentFR = "Pff... pourquoi est-ce que je perds mon temps à crier sur des imbéciles pareils ! Je vais retrouver ma fille moi-même !",
          DialogueId = 51009825,
          GUID = "7FB29F6A",
          NextDialogue = 51009826,
          Scripts = [[
PARA{
LookAt{LookAtDescription{"700307:n(700307)"}},
LookAt{LookAtDescription{"700308:n(700308)"}},
MoveTo{ActorId{700307},MoveSpeed{150},TargetPoint{"MagnusMPoint_20023205"}},
MoveTo{ActorId{700308},MoveSpeed{150},TargetPoint{"MagnusFPoint_20023205"}}
}]],
          SpeakNpcId = 700307,
          Subtitle = "Ugh — why am I even wasting my breath on imbeciles like you? I'll find my daughter myself!"
        },
        [51009826] = {
          Camera = "-238.418213,-514.537842,220.403809,0.000037,-12.999988,72.598557,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Ouf. Enfin parti.",
          DialogueId = 51009826,
          GUID = "7FB29F94",
          NextDialogue = 51009827,
          SpeakNpcId = 700313,
          Subtitle = "...Phew. He's finally gone."
        },
        [51009827] = {
          Camera = "77.355469,-517.516235,186.296875,0.000047,-11.199768,98.997734,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Veuillez rester à l’écart, s’il vous plaît. Cet endroit est interdit au public.",
          DialogueId = 51009827,
          GUID = "7FB29FBE",
          NextDialogue = 51009828,
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{"NvzhuPoint_20023205"}},
TurnTo{TurnToDescription{"100001:n(700313)"}}
}]],
          SpeakNpcId = 700313,
          Subtitle = "Please stay back — this area's off-limits."
        },
        [51009828] = {
          Camera = "-445.371338,-206.447021,167.490234,0.00006,-10.999575,13.197603,28.570547,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{性别:Désolé|Désolée}, j’ai entendu des cris... Que se passe-t-il ici ?",
          DialogueId = 51009828,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB29FE8",
          NextDialogue = 51009829,
          SpeakNpcId = 100001,
          Subtitle = "Sorry, I heard yelling. Is everything okay?",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009829] = {
          ContentFR = "Nous avons reçu un signalement : une personne aurait été kidnappée et retenue ici. Mais quand nous sommes arrivés, les lieux étaient déjà vides.",
          DialogueId = 51009829,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2A012",
          NextDialogue = 51009830,
          SpeakNpcId = 700313,
          Subtitle = "We received a report of a kidnapping. The victim was supposedly held here, but the place was already empty when we arrived.",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51009830] = {
          ContentFR = "Cette maison est désormais sous scellés. Si tu es simplement venu par curiosité, je te demanderai de ne pas t’approcher davantage.",
          DialogueId = 51009830,
          GUID = "7FB2A03C",
          NextDialogue = 51009831,
          SpeakNpcId = 700313,
          Subtitle = "This property's on lockdown. If you're just here out of curiosity, I'll have to ask you to move along."
        },
        [51009831] = {
          ContentFR = "D’accord... Et ces deux personnes, c’était qui ?",
          DialogueId = 51009831,
          GUID = "7FB2A066",
          NextDialogue = 51009832,
          SpeakNpcId = 100001,
          Subtitle = "Who were those two just now?",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009832] = {
          ContentFR = "Le Comte Magnus et son épouse — les parents de la victime. Je comprends qu’ils soient inquiets, mais... disons qu’ils sont fidèles à leur réputation.",
          DialogueId = 51009832,
          GUID = "7FB2A090",
          NextDialogue = 51009833,
          SpeakNpcId = 700313,
          Subtitle = "The victim's parents — the Earl and Countess of Magnus. I get that they're worried, but they really do live up to their reputation...",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009833] = {
          ContentFR = "On raconte qu’ils étaient très autoritaires avec leur fille. Peut-être que Mademoiselle Rosalind a fui pour échapper à leur emprise...",
          DialogueId = 51009833,
          GUID = "7FB2A0BA",
          NextDialogue = 51009834,
          SpeakNpcId = 700313,
          Subtitle = "Word is they were always breathing down their daughter's neck. Maybe Miss Rosalind ran off just to get some air..."
        },
        [51009834] = {
          ContentFR = "<I>Hum hum.</> Assez bavardé. Si tu obtiens la moindre information, transmets-la aux Veilleurs.",
          DialogueId = 51009834,
          GUID = "7FB2A0E4",
          NextDialogue = 51009835,
          SpeakNpcId = 700313,
          Subtitle = "Ahem... that's enough gossip. If you have any information, please report it to the Escort."
        },
        [51009835] = {
          Camera = "-99.088623,-74.42334,133.572266,0.000056,-4.199521,-40.602531,28.570547,100000.0,false,DoNotOverride,2.8",
          ContentFR = "<I>Giselle... et Mademoiselle Caisse... ne sont plus là.</>",
          DialogueId = 51009835,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2A10E",
          NextDialogue = 51009836,
          SpeakNpcId = 100001,
          Subtitle = "(Giselle and Miss Crate... they're both gone.)",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009836] = {
          ContentFR = "<I>Un enlèvement ? Est-ce que cela pourrait avoir un lien avec la lettre laissée à la taverne ?</>",
          DialogueId = 51009836,
          GUID = "7FB2A138",
          NextDialogue = 51009837,
          SpeakNpcId = 100001,
          Subtitle = "(A kidnapping... could it have something to do with that letter Giselle left at the tavern?)"
        },
        [51009837] = {
          ContentFR = "<I>Je n’ai aucune piste pour l’instant... Autant rester vigilant et voir ce qui se passera.</>",
          DialogueId = 51009837,
          GUID = "7FB2A162",
          SpeakNpcId = 100001,
          Subtitle = "(No leads for now. Guess I'll just have to stay sharp and see what turns up.)"
        },
        [51009838] = {
          ContentFR = "Da... da da...",
          DialogueId = 51009838,
          GUID = "7FB2A163",
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Da... Da da..."
        },
        [51009850] = {
          Camera = "-1567.962891,-185.177612,2329.811035,0.000069,-20.199333,74.602768,20.0,100000.0,false,Manual,2.8",
          ContentFR = "<I>Ces derniers jours à Givrelac ont été bien mouvementés... et maintenant, une affaire d’enlèvement est venue s’ajouter au chaos.</>",
          DialogueId = 51009850,
          FinalCamera = "-1614.97168,-559.773193,2467.275635,0.000069,-20.199333,74.602768,20.0,100000.0,false,Manual,2.8",
          GUID = "7FB2A384",
          NextDialogue = 51009851,
          Scripts = "SetTag{Tag{\"Huozai04Tag\"},Value{\"Value_1\"}}",
          SpeakNpcId = 100001,
          Subtitle = "(So much has happened in Icelake these past few days... and now, there's even been a kidnapping.)",
          ToFinalCameraBlendTime = 5
        },
        [51009851] = {
          Camera = "389.291016,-7961.245117,-744.026855,0.000091,3.00055,131.807861,20.0,100000.0,false,Manual,2.8",
          ContentFR = "<I>En y repensant bien, plusieurs événements semblent liés d’une manière ou d’une autre.</>",
          DialogueId = 51009851,
          FinalCamera = "712.783569,-8322.950195,-679.47168,0.000091,3.00055,131.807861,20.0,100000.0,false,Manual,2.8",
          GUID = "7FB2A3AE",
          NextDialogue = 51009852,
          SpeakNpcId = 100001,
          Subtitle = "(Now that I think about it, some of these events might be more closely connected than they seemed.)",
          ToFinalCameraBlendTime = 5
        },
        [51009852] = {
          Camera = "1489.815308,3777.302246,3313.351074,0.000015,-35.199669,-107.997414,20.0,100000.0,false,Manual,2.8",
          ContentFR = "<I>Mieux vaut faire le point... et essayer d’assembler les morceaux.</>",
          DialogueId = 51009852,
          FinalCamera = "1806.783691,4752.98291,4037.017334,0.000015,-35.199627,-107.997398,20.0,100000.0,false,Manual,2.8",
          GUID = "7FB2A3D8",
          SpeakNpcId = 100001,
          Subtitle = "(Time to lay everything out... and start connecting the dots.)",
          ToFinalCameraBlendTime = 5
        },
        [51009853] = {
          Camera = "1806.783691,4752.98291,4037.017334,0.000015,-35.199627,-107.997398,20.0,100000.0,false,Manual,2.8",
          ContentFR = "<I>Il y avait plus dans cette affaire que ce que l’on croyait. Et Violetta... elle connaît sûrement la vérité. Giselle a enlevé son élève pour la forcer à se montrer.</>",
          DialogueId = 51009853,
          GUID = "7FB2A402",
          NextDialogue = 51009854,
          SpeakNpcId = 100001,
          Subtitle = "(There was more to the kidnapping sixteen years ago... and Violetta may be the one who knows the truth. Giselle took her student just to force a meeting.)"
        },
        [51009854] = {
          ContentFR = "<I>Si j’ai raison, elles doivent être ensemble en ce moment.</>",
          DialogueId = 51009854,
          GUID = "7FB2A42C",
          NextDialogue = 51009855,
          SpeakNpcId = 100001,
          Subtitle = "(If my deductions are right, she should be with Violetta right now.)"
        },
        [51009855] = {
          ContentFR = "<I>Je dois me rendre sur place au plus vite... en espérant qu’il ne soit pas trop tard.</>",
          DialogueId = 51009855,
          GUID = "7FB2A456",
          SpeakNpcId = 100001,
          Subtitle = "(The letter mentioned the location. I need to hurry... let's hope I'm not too late.)"
        },
        [51009856] = {
          Camera = "-1404.640625,-280.359375,849.211426,0.00002,-23.200226,22.597872,35.0,100000.0,false,Manual,2.8",
          ContentFR = "Tiens, t’es à l’heure finalement.",
          DialogueId = 51009856,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2A480",
          NextDialogue = 51009857,
          SpeakNpcId = 700302,
          Subtitle = "Right on time, huh.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51009857] = {
          ContentFR = "...",
          DialogueId = 51009857,
          GUID = "7FB2A4AA",
          NextDialogue = 51009858,
          SpeakNpcId = 700300,
          Subtitle = "..."
        },
        [51009858] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quoi, tu comptes garder le silence ? Ce n’est pas un tribunal ici. Si tu attends qu’on te lise tes droits, tu risques d’attendre longtemps.",
          DialogueId = 51009858,
          GUID = "7FB2A4D4",
          NextDialogue = 51009859,
          SpeakNpcId = 700302,
          Subtitle = "What's with the silence? This isn't a courtroom. If you're waiting for a \"You have the right to remain silent,\" don't hold your breath."
        },
        [51009859] = {
          ContentFR = "Et qu’est-ce que tu veux que je dise ? Vas-y, je t’écoute. Après un coup aussi bas, quelle réponse attends-tu exactement ?",
          DialogueId = 51009859,
          FacialId = {
            [1] = "700300:CM_Angry01"
          },
          GUID = "7FB2A4FE",
          NextDialogue = 51009860,
          SpeakNpcId = 700300,
          Subtitle = "And what would you have me say? Go on, enlighten me. After a despicable stunt like this, what kind of answer do you expect to hear?"
        },
        [51009860] = {
          Camera = "148.300781,-316.230469,157.037598,0.999999,-5.400179,115.588638,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu te fous de moi ? Ou tu crois vraiment que tes crimes peuvent se maquiller aussi facilement que ton visage ? Tu penses qu’un peu de poudre peut tout effacer ?",
          DialogueId = 51009860,
          GUID = "7FB2A528",
          NextDialogue = 51009861,
          SpeakNpcId = 700302,
          Subtitle = "Still playing dumb, are we? Or do you actually believe your crimes are as easy to cover up as your real face? You really think a bit of powder and paint can hide everything?"
        },
        [51009861] = {
          ContentFR = "Très bien... Laisse-moi rafraîchir ta mémoire.",
          DialogueId = 51009861,
          GUID = "7FB2A552",
          NextDialogue = 51009862,
          SpeakNpcId = 700302,
          Subtitle = "Fine. Then let me jog your memory."
        },
        [51009862] = {
          Camera = "-1404.640625,-280.359375,849.211426,0.00002,-23.200226,22.597872,35.0,100000.0,false,Manual,2.8",
          ContentFR = "Il y a seize ans, à Givrelac, un jeune homme nommé Sig a enlevé Enola Ruthford, la fille de Fabrice Ruthford, responsable de la Fosse de Glevum.",
          DialogueId = 51009862,
          GUID = "7FB2A57C",
          NextDialogue = 51009863,
          SpeakNpcId = 700302,
          Subtitle = "Sixteen years ago, in Icelake, a young man named Sig kidnapped the daughter of Fabrice Ruthford — then overseer of Glevum Pit. Her name was Enola."
        },
        [51009863] = {
          ContentFR = "Lorsqu’il a été acculé par les Veilleurs, Sig a résisté... et a accidentellement mis le feu à la maison. Enola est morte dans l’incendie, et Sig a été condamné à mort.",
          DialogueId = 51009863,
          GUID = "7FB2A5A6",
          NextDialogue = 51009864,
          SpeakNpcId = 700302,
          Subtitle = "When the Escort cornered him, he resisted — and accidentally set the house on fire in the struggle. Enola died in the flames. And Sig was sentenced to death."
        },
        [51009864] = {
          Camera = "-314.688477,142.042969,142.037598,1.000012,-0.599793,-21.008369,40.559872,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui, j’ai entendu parler de cette tragédie. Une histoire lamentable... que cette pauvre fille repose en paix.",
          DialogueId = 51009864,
          GUID = "7FB2A5D0",
          NextDialogue = 51009865,
          SpeakNpcId = 700300,
          Subtitle = "I've heard of that tragedy. A pity, truly. May that poor girl rest in peace.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009865] = {
          ContentFR = "Mais je ne suis arrivée à Givrelac que bien plus tard. En quoi cela me concerne-t-il ?",
          DialogueId = 51009865,
          GUID = "7FB2A5FA",
          NextDialogue = 51009866,
          SpeakNpcId = 700300,
          Subtitle = "But I only arrived in Icelake a few years ago. What could any of this possibly have to do with me?"
        },
        [51009866] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Parce qu’il y a eu une survivante.",
          DialogueId = 51009866,
          GUID = "7FB2A624",
          NextDialogue = 51009867,
          SpeakNpcId = 700302,
          Subtitle = "Because someone survived that fire.",
          TalkActionId = {
            [1] = "700300:Explain02_End"
          }
        },
        [51009867] = {
          ContentFR = "Un témoin affirme qu’il y avait trois personnes dans la maison ce soir-là : Sig, Enola... et la sœur de Sig, Violette, une fille du même âge qu’Enola.",
          DialogueId = 51009867,
          GUID = "7FB2A64E",
          NextDialogue = 51009868,
          SpeakNpcId = 700302,
          Subtitle = "A witness said there were three people in the house that night — Sig, Enola... and Sig's sister, Violet. A girl around the same age as Enola."
        },
        [51009868] = {
          ContentFR = "Dans le chaos, ce témoin a sorti une jeune fille des flammes — une fille qu’il croyait être Violette. Mais l’était-elle vraiment ?",
          DialogueId = 51009868,
          GUID = "7FB2A678",
          NextDialogue = 51009869,
          SpeakNpcId = 700302,
          Subtitle = "In the chaos, that witness managed to pull a girl from the flames — a girl he thought was Violet. But was she really?"
        },
        [51009869] = {
          ContentFR = "Arrête-moi si je me trompe : tu as tué Violette ce soir-là... puis tu as pris son nom pour tromper Donat et t’échapper de Givrelac, n’est-ce pas, Enola Ruthford ?",
          DialogueId = 51009869,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2A6A2",
          NextDialogue = 51009870,
          SpeakNpcId = 700302,
          Subtitle = "Tell me I'm wrong. Sixteen years ago, you killed Violet in that fire — then took her name, and tricked Donat into helping you escape Icelake. Didn't you, Enola Ruthford?",
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009870] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Ah ! Intéressant scénario. Un polar de ce genre, c’est plutôt rare.",
          DialogueId = 51009870,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB2A6CC",
          NextDialogue = 51009871,
          SpeakNpcId = 700300,
          Subtitle = "...Heh. Now there's a compelling tale. Good mysteries are so rare these days.",
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Angry01_End"
          }
        },
        [51009871] = {
          ContentFR = "Continue, j’aime bien les histoires.",
          DialogueId = 51009871,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2A6F6",
          NextDialogue = 51009872,
          SpeakNpcId = 700300,
          Subtitle = "Please, do go on. I'm dying to hear how it ends.",
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51009872] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai passé des années à enquêter sur cette affaire. Un corps méconnaissable... une seule survivante... trop de coïncidences.",
          DialogueId = 51009872,
          GUID = "7FB2A720",
          NextDialogue = 51009873,
          SpeakNpcId = 700302,
          Subtitle = "I spent years combing through that case. A body burnt beyond recognition... a lone survivor... it was all just a little too convenient.",
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009873] = {
          ContentFR = "Toutes les pièces étaient là, mais il manquait le fil conducteur.",
          DialogueId = 51009873,
          GUID = "7FB2A74A",
          NextDialogue = 51009874,
          SpeakNpcId = 700302,
          Subtitle = "All the pieces were there, but the thread connecting them all together was missing."
        },
        [51009874] = {
          ContentFR = "Si je n’avais pas été assignée à la protection de Fabrice Ruthford à l’époque — si je n’avais pas entendu sa fille chanter —",
          DialogueId = 51009874,
          GUID = "7FB2A774",
          NextDialogue = 51009875,
          SpeakNpcId = 700302,
          Subtitle = "As luck would have it, back when I was assigned to guard Fabrice Ruthford, I once heard his daughter sing."
        },
        [51009875] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "je n’aurais jamais fait le lien. Cette voix... je la reconnaîtrais entre mille. Voilà comment j’ai su qui tu étais vraiment, « Violetta aux mille visages ».",
          DialogueId = 51009875,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2A79E",
          NextDialogue = 51009876,
          SpeakNpcId = 700302,
          Subtitle = "That voice... I'd recognise it anywhere. And that's when I knew who you really were, \"Violetta of a Thousand Faces.\""
        },
        [51009876] = {
          ContentFR = "J’ai même trouvé des moyens d’étudier tes habitudes... par exemple en envoyant quelqu’un t’apporter de fausses lettres pour t’observer.",
          DialogueId = 51009876,
          GUID = "7FB2A7C8",
          NextDialogue = 51009877,
          SpeakNpcId = 700302,
          Subtitle = "I tried to study your habits — even arranged for false letters to be delivered, just to keep tabs on you.",
          TalkActionId = {
            [1] = "700302:Explain01_Start"
          }
        },
        [51009877] = {
          ContentFR = "Donc ce soldat, c’était toi qui l’avais envoyé.",
          DialogueId = 51009877,
          GUID = "7FB2A7F2",
          NextDialogue = 51009878,
          SpeakNpcId = 700300,
          Subtitle = "Ah, so he was one of yours.",
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Explain01_End"
          }
        },
        [51009878] = {
          ContentFR = "Pas exactement. C’était vraiment un de tes admirateurs. Je n’ai fait que le pousser un peu dans cette direction. Grâce à lui, j’ai eu la confirmation.",
          DialogueId = 51009878,
          GUID = "7FB2A81C",
          NextDialogue = 51009879,
          SpeakNpcId = 700302,
          Subtitle = "Not quite. He really was a fan. I just gave him a gentle nudge. And thanks to him, I got the answer I needed."
        },
        [51009879] = {
          Camera = "127.291016,-233.679688,146.983398,1.000008,-1.000206,118.987587,38.469608,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais il reste une chose que je ne comprends pas.",
          DialogueId = 51009879,
          GUID = "7FB2A846",
          NextDialogue = 51009880,
          SpeakNpcId = 700302,
          Subtitle = "Still, there's one thing I don't understand."
        },
        [51009880] = {
          ContentFR = "Changer d’identité avec Violette n’aurait pas été possible sans leur coopération. Comment les as-tu convaincus ?",
          DialogueId = 51009880,
          GUID = "7FB2A870",
          NextDialogue = 51009881,
          SpeakNpcId = 700302,
          Subtitle = "Swapping places with Violet — it couldn't have been possible unless both Sig and the girl went along with it. How did you convince them?",
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009881] = {
          Camera = "-294.663086,168.334961,176.219727,1.000005,-6.799897,-27.606359,56.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je croyais que tu allais poser une question difficile... La réponse est simple.",
          DialogueId = 51009881,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A89A",
          NextDialogue = 51009882,
          SpeakNpcId = 700300,
          Subtitle = "That's your big mystery? The answer's simple.",
          TalkActionId = {
            [1] = "700300:Sigh_Start",
            [2] = "700302:Think_End"
          }
        },
        [51009882] = {
          ContentFR = "J’étais la fille de Fabrice Ruthford. Et tu sais ce que cela signifie de s’opposer à lui.",
          DialogueId = 51009882,
          GUID = "7FB2A8C4",
          NextDialogue = 51009883,
          SpeakNpcId = 700300,
          Subtitle = "You used to serve under my father. Then you should know what it meant to defy him.",
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009883] = {
          ContentFR = "Le pauvre Sig savait déjà qu’il n’en sortirait pas vivant... et connaissant mon père, Violette non plus n’avait aucune chance.",
          DialogueId = 51009883,
          GUID = "7FB2A8EE",
          NextDialogue = 51009884,
          SpeakNpcId = 700300,
          Subtitle = "Poor Sig was already prepared to throw his life away — but knowing my father, Violet was as good as dead too."
        },
        [51009884] = {
          ContentFR = "Je leur ai proposé une solution : après avoir reçu la rançon, ils n’avaient qu’à gagner du temps, créer la confusion, et donner à Violette une chance de s’échapper.",
          DialogueId = 51009884,
          GUID = "7FB2A918",
          NextDialogue = 51009885,
          SpeakNpcId = 700300,
          Subtitle = "So I offered them a way out: Once the ransom was collected, stall as long as possible while creating a distraction to buy some time for Violet."
        },
        [51009885] = {
          ContentFR = "Pathétique, non ? Dans sa panique, il a affronté les Veilleurs seul, espérant qu’une fillette malade s’échapperait d’une maison en feu...",
          DialogueId = 51009885,
          GUID = "7FB2A942",
          NextDialogue = 51009886,
          SpeakNpcId = 700300,
          Subtitle = "Pathetic, isn't it? In his panic, he actually ran off on his own to hold off the Escort, hoping that a sickly little girl might somehow escape a blazing house...",
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009886] = {
          ContentFR = "J’ai saisi ma chance. J’ai tué cette pauvre enfant qui se trouvait sur mon chemin. J’ai pris son nom. J’ai laissé derrière moi cette maison pourrie... et mon père. J’ai laissé derrière moi tout ce qui m’empêchait de monter sur scène.",
          DialogueId = 51009886,
          GUID = "7FB2A96C",
          NextDialogue = 51009887,
          SpeakNpcId = 700300,
          Subtitle = "I took my chance. Killed that poor wretch who stood in my way. Took her name, left behind the dump — and my father. Left behind everything that ever stood between me and the stage."
        },
        [51009887] = {
          Camera = "96.022461,-329.655273,121.388672,0.999973,0.800034,107.991287,33.074104,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51009887,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2A996",
          NextDialogue = 51009888,
          SpeakNpcId = 700302,
          Subtitle = "..."
        },
        [51009888] = {
          ContentFR = "Qu’y a-t-il, Giselle ? Tu poursuis cette vérité depuis des années... et maintenant que tu l’as, tu ne sembles pas ravie.",
          DialogueId = 51009888,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A9C0",
          NextDialogue = 51009889,
          SpeakNpcId = 700300,
          Subtitle = "What's the matter, Giselle? You've chased this truth for years... and now that you have it, you don't look the least bit satisfied."
        },
        [51009889] = {
          ContentFR = "T’es complètement folle... Tout ça, juste pour les projecteurs ?! Tu as tué deux personnes innocentes !",
          DialogueId = 51009889,
          GUID = "7FB2A9EA",
          NextDialogue = 51009890,
          SpeakNpcId = 700302,
          Subtitle = "You're insane... All of this — just for the spotlight!? You killed two people! Two innocent lives!",
          TalkActionId = {
            [1] = "700302:Angry01_Start",
            [2] = "700300:Talk02_End"
          }
        },
        [51009890] = {
          ContentFR = "Alors, que vas-tu faire ? Révéler mes crimes au grand jour pour ruiner ma réputation ? Ou bien... venger leur mort ici et maintenant ?",
          DialogueId = 51009890,
          GUID = "7FB2AA14",
          NextDialogue = 51009891,
          SpeakNpcId = 700300,
          Subtitle = "So what will it be? Drag my sins into the light? Or take your revenge, right here and now?",
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009891] = {
          ContentFR = "... Je voulais seulement révéler la vérité... et te livrer aux Veilleurs.",
          DialogueId = 51009891,
          GUID = "7FB2AA3E",
          NextDialogue = 51009892,
          SpeakNpcId = 700302,
          Subtitle = "...I only ever meant to reveal the truth... and turn you in to the Escort."
        },
        [51009892] = {
          ContentFR = "Giselle dégaine un poignard. La tension est palpable. Tu entends presque le cuir craquer sous la force de sa poigne, et le grincement de ses dents serrées.",
          DialogueId = 51009892,
          GUID = "7FB2AA68",
          IsBlack = 1,
          NextDialogue = 51009893,
          Subtitle = "(Giselle draws a dagger. Her fury thickens the air — you can almost hear her teeth grinding, the hilt creaking under the pressure of her grip.)",
          TalkActionId = {
            [1] = "700302:Angry01_End"
          }
        },
        [51009893] = {
          ContentFR = "Si personne ne l’arrête, cette lame mettra bientôt fin à la plus belle voix de Givrelac... Quoi qu’il en soit, tu ne peux pas rester là à regarder quelqu’un commettre un meurtre.",
          DialogueId = 51009893,
          GUID = "7FB2AA69",
          IsBlack = 1,
          Subtitle = "(If no one stops her, that dagger will silence the finest voice in Icelake. Whatever the truth... you can't just stand by and watch someone commit murder.)"
        },
        [51009894] = {
          ContentFR = "{nickname}... ? Qu’est-ce que tu fais ici ?",
          DialogueId = 51009894,
          GUID = "7FB2AABC",
          NextDialogue = 51009895,
          SpeakNpcId = 700300,
          Subtitle = "? What are you doing here?"
        },
        [51009895] = {
          ContentFR = "Écarte-toi. Je ne laisserai pas une ordure comme elle vivre une minute de plus !",
          DialogueId = 51009895,
          GUID = "7FB2AAE6",
          NextDialogue = 51009896,
          SpeakNpcId = 700302,
          Subtitle = "Get out of my way. I won't let a monster like her walk free!",
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009896] = {
          ContentFR = "<I>Elle a complètement perdu les pédales... Je dois trouver un moyen de la calmer.</>",
          DialogueId = 51009896,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2AB10",
          SpeakNpcId = 100001,
          Subtitle = "(She's lost it... I have to bring her back to her senses.)"
        },
        [51009897] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Calme-toi, Giselle. Il y a peut-être plus dans cette histoire que ce que tu crois.",
          DialogueId = 51009897,
          GUID = "7FB2AB3A",
          NextDialogue = 51009898,
          SpeakNpcId = 100001,
          Subtitle = "Giselle, calm down. There might be more to this than you think.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009898] = {
          ContentFR = "Tu as entendu ce qu’elle vient d’avouer ?! Tu crois vraiment que je peux rester calme après ça ?!",
          DialogueId = 51009898,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2AB64",
          NextDialogue = 51009899,
          SpeakNpcId = 700302,
          Subtitle = "Did you not hear what she just said!? How am I supposed to calm down!?",
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009899] = {
          ContentFR = "Elle ne s’échappera pas, pas avec nous deux ici. Alors souffle un bon coup... et laisse-moi lui poser quelques questions.",
          DialogueId = 51009899,
          GUID = "7FB2AB8E",
          NextDialogue = 51009900,
          SpeakNpcId = 100001,
          Subtitle = "She's not going anywhere — not with us here. Just take a breath. I have a few questions for her."
        },
        [51009900] = {
          Camera = "157.706055,-54.485352,141.052246,0.0001,-1.599849,150.594193,53.202648,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51009900,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2ABB8",
          NextDialogue = 51009901,
          SpeakNpcId = 700302,
          Subtitle = "...",
          TalkActionId = {
            [1] = "700302:Angry01_End"
          }
        },
        [51009901] = {
          ContentFR = "Très bien. Vas-y, pose-les.",
          DialogueId = 51009901,
          GUID = "7FB2ABE2",
          NextDialogue = 51009902,
          SpeakNpcId = 700302,
          Subtitle = "Fine. Go ahead.",
          TalkActionId = {
            [1] = "700302:Talk03_Start",
            [2] = "100001:Talk02R_End"
          },
          TurnTo = {
            [1] = "100001:n(700300)",
            [2] = "700300:n(100001)"
          }
        },
        [51009902] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Avant toute chose... Madame Violetta, est-ce que cet objet te dit quelque chose ?",
          DialogueId = 51009902,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon02.T_Guide_ChapterFire_Ribbon02'}",
          GUID = "7FB2AC0C",
          NextDialogue = 51009903,
          SpeakNpcId = 100001,
          Subtitle = "Before that — Ms Violetta, does this look familiar?",
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51009903] = {
          ContentFR = "C’est...",
          DialogueId = 51009903,
          FacialId = {
            [1] = "700300:CM_Shock01"
          },
          GUID = "7FB2AC36",
          NextDialogue = 51009904,
          SpeakNpcId = 700300,
          Subtitle = "That's...",
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          }
        },
        [51009904] = {
          ContentFR = "Violetta lève instinctivement la main vers l’arrière de sa tête. Ses doigts frôlent une texture familière... puis elle se fige, comme frappée par la réalité.",
          DialogueId = 51009904,
          GUID = "7FB2AC60",
          NextDialogue = 51009905,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          Subtitle = "(Violetta's hand drifts instinctively to the back of her head. Her fingers find the familiar texture — and she freezes.)"
        },
        [51009905] = {
          ContentFR = "Vu ta réaction, je ne me trompais pas... C’est toi qui as déposé ce ruban sur la tombe de Sig, n’est-ce pas ?",
          DialogueId = 51009905,
          GUID = "7FB2AC8A",
          NextDialogue = 51009906,
          SpeakNpcId = 100001,
          Subtitle = "Huh... just as I thought. You left this ribbon at Sig's grave, didn't you?"
        },
        [51009906] = {
          ContentFR = "Tu m’avais dit qu’il appartenait à une amie très chère, et que si tu avais choisi de monter sur scène, c’était pour accomplir son rêve.",
          DialogueId = 51009906,
          GUID = "7FB2ACB4",
          NextDialogue = 51009907,
          SpeakNpcId = 100001,
          Subtitle = "You once told me it belonged to a dear friend — and that you took to the stage to fulfil her dream.",
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009907] = {
          ContentFR = "Tu es vraiment {性别:un idiot naïf|une idiote naïve}. Je n’aurais jamais cru que tu pourrais gober une histoire aussi mielleuse.",
          DialogueId = 51009907,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2ACDE",
          NextDialogue = 51009908,
          SpeakNpcId = 700300,
          Subtitle = "You're a naive fool. I can't believe you actually fell for such sentimental drivel."
        },
        [51009908] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Peut-être bien. C’est pour ça que je suis allé demander la vérité à Donat — en lui empruntant ce ruban.",
          DialogueId = 51009908,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2AD08",
          NextDialogue = 51009909,
          SpeakNpcId = 100001,
          Subtitle = "Maybe. Which is why I borrowed this ribbon from Donat — to find out the truth.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009909] = {
          ContentFR = "Il m’a parlé de Violette. Il a dit que c’était une fille incroyablement talentueuse. Sans la pauvreté ni la maladie, elle serait sans doute devenue une grande dramaturge.",
          DialogueId = 51009909,
          GUID = "7FB2AD32",
          NextDialogue = 51009910,
          SpeakNpcId = 100001,
          Subtitle = "He told me about Violet. About how gifted she was. If not for poverty and illness, she might've been a great playwright."
        },
        [51009910] = {
          ContentFR = "Le destin ne lui a pas souri, mais elle n’a jamais abandonné. Même clouée au lit, elle a continué à poursuivre son rêve, à sa façon.",
          DialogueId = 51009910,
          GUID = "7FB2AD5C",
          NextDialogue = 51009911,
          SpeakNpcId = 100001,
          Subtitle = "Fate dealt her a cruel hand, but she never gave up. Even when she could barely leave her bed, she still found a way to pursue her dream."
        },
        [51009911] = {
          ContentFR = "Elle voulait que la plus grande comédienne du monde joue son œuvre, et que l’histoire qu’elle avait écrite, la dernière et la plus belle, fasse le tour de tout Atlasia.",
          DialogueId = 51009911,
          GUID = "7FB2AD86",
          NextDialogue = 51009912,
          SpeakNpcId = 100001,
          Subtitle = "She dreamed of the world's greatest actor performing her work — of her final, proudest piece reaching every corner of Atlasia."
        },
        [51009912] = {
          ContentFR = "Cette œuvre, c’était—",
          DialogueId = 51009912,
          GUID = "7FB2ADB0",
          NextDialogue = 51009913,
          SpeakNpcId = 100001,
          Subtitle = "And that piece was—",
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51009913] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... <I>Putini</>. Une pièce en trois actes. Elle a ensuite été adaptée en opéra.",
          DialogueId = 51009913,
          GUID = "7FB2ADDA",
          NextDialogue = 51009914,
          SpeakNpcId = 700300,
          Subtitle = "...Putini. A three-act play. Later adapted into the opera.",
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009914] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Exactement. Tu comprends maintenant que mentir davantage ne ferait qu’aggraver ta situation. Alors...",
          DialogueId = 51009914,
          GUID = "7FB2AE04",
          NextOptions = {
            [1] = 510098241,
            [2] = 510098242
          },
          SpeakNpcId = 100001,
          Subtitle = "Good. You get it now — lying any further would only make things worse. So...",
          TalkActionId = {
            [1] = "100001:ConfidentLR_Start"
          }
        },
        [51009915] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu as raison... toute pièce mérite une fin.",
          DialogueId = 51009915,
          GUID = "7FB2AE2E",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          Subtitle = "I suppose you're right. Every play must end eventually.",
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009916] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Vraiment ? C’est le moment que tu choisis pour citer un polar ?",
          DialogueId = 51009916,
          GUID = "7FB2AE58",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          Subtitle = "...Is this really the time for theatrics?",
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51009917] = {
          ContentFR = "Si tous les spectateurs étaient aussi perspicaces que toi, les dramaturges n’auraient plus besoin de se casser la tête à rendre leurs intrigues plus simples.",
          DialogueId = 51009917,
          GUID = "7FB2AE82",
          NextDialogue = 51009918,
          SpeakNpcId = 700300,
          Subtitle = "Well, if every audience were as sharp as you, mystery playwrights wouldn't have to twist themselves in knots to dumb things down."
        },
        [51009918] = {
          Camera = "167.182617,-305.451172,119.724609,0.000095,2.599987,124.794083,44.87347,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Qu’est-ce que vous racontez tous les deux ? Que signifie tout ça ?",
          DialogueId = 51009918,
          GUID = "7FB2AEAC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009919,
          SpeakNpcId = 700302,
          Subtitle = "What are you two talking about? What's going on here?",
          TalkActionId = {
            [1] = "100001:ConfidentLR_End"
          },
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009919] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est très simple, Giselle. Si Violetta avait vraiment considéré Violette comme un simple outil à jeter, pourquoi aurait-elle choisi un nom si proche du sien ?",
          DialogueId = 51009919,
          GUID = "7FB2AED6",
          NextDialogue = 51009920,
          SpeakNpcId = 100001,
          Subtitle = "It's simple, Giselle. If she really saw Violet as nothing but a pawn, why would she take a name so close to hers?",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009920] = {
          Camera = "-1216.617188,-202.104492,761.92041,0.000021,-23.200226,22.597822,35.0,100000.0,false,Manual,2.8",
          ContentFR = "Laisse-moi te raconter ce que je crois : il y a seize ans, Sig a enlevé Enola Ruthford — celle qui se fait appeler aujourd’hui Violetta — pour réunir de quoi soigner sa sœur.",
          DialogueId = 51009920,
          FinalCamera = "-1418.189453,-286.000977,855.499756,0.000021,-23.200226,22.597822,35.0,100000.0,false,Manual,2.8",
          GUID = "7FB2AF00",
          NextDialogue = 51009921,
          SpeakNpcId = 100001,
          Subtitle = "Let me tell you the version I see: Sixteen years ago, Sig kidnapped Enola Ruthford — the girl who would one day call herself Violetta — to raise money for his sister's treatment.",
          ToFinalCameraBlendTime = 10
        },
        [51009921] = {
          ContentFR = "Pendant sa captivité, Enola a rencontré Violette, malade et alitée. Et pendant ce court laps de temps, elles sont devenues amies.",
          DialogueId = 51009921,
          GUID = "7FB2AF2A",
          NextDialogue = 51009922,
          SpeakNpcId = 100001,
          Subtitle = "While she was held captive, Enola met the bedridden Violet. And somewhere in that brief time, the two became close friends."
        },
        [51009922] = {
          ContentFR = "Mais leur bonheur n’a pas duré...",
          DialogueId = 51009922,
          GUID = "7FB2AF54",
          NextDialogue = 51009923,
          SpeakNpcId = 100001,
          Subtitle = "But it didn't last long."
        },
        [51009923] = {
          ContentFR = "Violette savait que ses jours étaient comptés. Elle ne voulait pas que son frère s’enfonce plus profondément dans l’erreur. Alors elle a écrit à Donat, l’ami de Sig, pour lui demander d’intervenir.",
          DialogueId = 51009923,
          GUID = "7FB2AF7E",
          NextDialogue = 51009924,
          SpeakNpcId = 100001,
          Subtitle = "Violet knew her time was running out. She didn't want her brother sinking deeper down the wrong path. So she wrote to Donat — a trusted friend of Sig's — hoping he'd intervene."
        },
        [51009924] = {
          ContentFR = "Comme elle l’espérait, Donat a fini par venir te trouver, Giselle, et t’a dénoncé l’enlèvement d’Enola. Mais à ce moment-là, je suppose que Violette était déjà...",
          DialogueId = 51009924,
          GUID = "7FB2AFA8",
          NextDialogue = 51009925,
          SpeakNpcId = 100001,
          Subtitle = "And Donat did. He reported the kidnapping... to you, Giselle. But by then, I suspect Violet was already—"
        },
        [51009925] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah... ironique, n’est-ce pas ? J’étais censée être une otage, et pourtant... ce furent les jours les plus heureux de ma vie.",
          DialogueId = 51009925,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          FinalCamera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2AFD2",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009926,
          SpeakNpcId = 700300,
          Subtitle = "Ah... strange, isn't it? I was kidnapped, yet somehow... those were the happiest days of my life.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15
        },
        [51009926] = {
          ContentFR = "Sig m’avait attachée dans une pièce, mais il n’avait aucune intention de me faire du mal. Il ne faisait que marcher nerveusement de long en large.",
          DialogueId = 51009926,
          GUID = "7FB2AFFC",
          NextDialogue = 51009927,
          SpeakNpcId = 700300,
          Subtitle = "Sig kept me tied up in a room, but he never meant me harm. He barely paid me any attention — just paced endlessly around the house."
        },
        [51009927] = {
          ContentFR = "Je savais qu’il y avait une autre personne dans la maison — une jeune fille. Je l’entendais fredonner doucement, les jours où elle se sentait bien...",
          DialogueId = 51009927,
          GUID = "7FB2B026",
          NextDialogue = 51009928,
          SpeakNpcId = 700300,
          Subtitle = "I knew there was someone else — a girl — in the house. I could hear her humming softly, on days when her mood was light..."
        },
        [51009928] = {
          ContentFR = "Peut-être a-t-il compris qu’il ne pouvait pas s’occuper de deux personnes à la fois. Quelques jours plus tard, il m’a détachée et m’a laissée me déplacer librement au rez-de-chaussée.",
          DialogueId = 51009928,
          GUID = "7FB2B050",
          NextDialogue = 51009929,
          SpeakNpcId = 700300,
          Subtitle = "Perhaps Sig realised he couldn't possibly tend to two helpless people at once. So a few days in, he untied me — let me move around the ground floor as I pleased."
        },
        [51009929] = {
          Camera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Chaque fois qu’il sortait, je montais discrètement voir Violette à l’étage. Elle me lisait ses histoires, et moi, je les jouais — je leur donnais vie.",
          DialogueId = 51009929,
          GUID = "7FB2B07A",
          NextDialogue = 51009930,
          SpeakNpcId = 700300,
          Subtitle = "And whenever he left the house, I'd steal upstairs to see Violet. She'd tell me the stories she was writing... and I'd act them out — bringing the characters to life."
        },
        [51009930] = {
          ContentFR = "« Mon bien-aimé, ne pleure pas pour moi ! En cette nuit sans sommeil, je mets les voiles sous la lumière argentée — »",
          DialogueId = 51009930,
          GUID = "7FB2B0A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009931,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "\"My dearest, weep no tears for me — on this sleepless night, I set off in silver light.\""
        },
        [51009931] = {
          ContentFR = "« Le vent gonfle ma voile, la marée embrasse mon aviron... le phare s’illumine dans la mer, et la lune brille si fort ! »",
          DialogueId = 51009931,
          GUID = "7FB2B0CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009932,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "\"The wind fills my sail, the tide kisses my oar. The lighthouse aglow, 'neath the moon — oh, so bright!\""
        },
        [51009932] = {
          ContentFR = "Merci, Enola... C’était magnifique. Dans mon esprit, Putini t’a toujours ressemblé : passionnée, courageuse, toujours en quête de liberté...",
          DialogueId = 51009932,
          GUID = "7FB2B0F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009933,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "Thank you, Enola... that was beautiful. Truly. Hehe... Whenever I imagined Putini, she always looked like you — bold, radiant, and forever chasing her freedom..."
        },
        [51009933] = {
          ContentFR = "Merci ! J’ai un peu improvisé... Mais je connais un compositeur talentueux, Cavaradossi. Peut-être pourrait-il adapter <I>Putini</> en opéra...",
          DialogueId = 51009933,
          GUID = "7FB2B122",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009934,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "Thanks! I did a bit of improvising... But I know a brilliant composer — his name's Cavaradossi. Maybe we could ask him to adapt Putini into an opera—"
        },
        [51009934] = {
          ContentFR = "... Mais je n’aurai sans doute jamais l’occasion de la chanter.",
          DialogueId = 51009934,
          GUID = "7FB2B14C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009935,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "...Not that I'll ever get the chance to sing it."
        },
        [51009935] = {
          ContentFR = "J’ai dix-huit ans. Mon père m’a déjà trouvé un mari, un jeune officier de l’Académie d’Alchimie. Le mariage est dans deux mois.",
          DialogueId = 51009935,
          GUID = "7FB2B176",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009936,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "I'm eighteen now. My father's already arranged my marriage — two months from now, to some young officer from the Alchemy Academy."
        },
        [51009936] = {
          ContentFR = "Je suppose que je finirai ma vie en poupée de porcelaine dans un salon... ou les mains plongées à jamais dans ces maudits flacons de Phoxichor.",
          DialogueId = 51009936,
          GUID = "7FB2B1A0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009937,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora",
          Subtitle = "Guess I'll spend the rest of my life as a pretty trophy collecting dust in a parlour... or elbow-deep in those wretched Phoxichor canisters."
        },
        [51009937] = {
          ContentFR = "Non... non, Enola, ce n’est pas ce qui doit t’arriver. Ta voix est celle d’une alouette... Tu n’es pas faite pour un petit salon. Tu es faite pour la scène — la plus grande de toutes.",
          DialogueId = 51009937,
          GUID = "7FB2B1CA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009938,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "No, no... Enola, this isn't how it should be. You have a voice as sweet as a lark's... You don't belong in some parlour... You belong on a grand stage — the grandest there is."
        },
        [51009938] = {
          ContentFR = "Chaque personne qui aime chanter mérite de briller sous les projecteurs — qu’elle soit Sola ou Charon, riche ou pauvre...",
          DialogueId = 51009938,
          GUID = "7FB2B1F4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009939,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "Everyone who loves to sing... deserves their moment in the spotlight... Solarian or Charon, rich or poor..."
        },
        [51009939] = {
          ContentFR = "Je trouverai un moyen pour que mon frère te laisse partir. Mon corps me lâche déjà... Je ne sais pas si j’aurai le temps d’écrire la dernière scène de <I>Putini</>...",
          DialogueId = 51009939,
          GUID = "7FB2B21E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009940,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "I'll talk to my brother. I'll find a way to help you escape. My body's already giving out... and I may never finish the final act of Putini..."
        },
        [51009940] = {
          ContentFR = "Mais Enola... promets-moi que tu monteras sur scène. Que tu feras entendre notre <I>Putini</> au monde entier...",
          DialogueId = 51009940,
          GUID = "7FB2B248",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009941,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet",
          Subtitle = "But Enola — promise me that you'll take the stage, and share our Putini with the world..."
        },
        [51009941] = {
          ContentFR = "« Chaque personne qui aime chanter mérite de briller sous les projecteurs. » C’était la dernière volonté de Violette... et c’est devenu ma raison de vivre.",
          DialogueId = 51009941,
          GUID = "7FB2B272",
          NextDialogue = 51009942,
          SpeakNpcId = 700300,
          Subtitle = "\"Everyone who loves to sing deserves their moment in the spotlight. Solarian or Charon, rich or poor...\" That was Violet's final wish — and it became the truth I live by."
        },
        [51009942] = {
          ContentFR = "... Quand elle est morte, j’ai chanté le dernier acte de <I>Putini</> devant Sig. Il était vidé par la douleur... mais dans ses yeux, j’ai vu une étincelle renaître des cendres.",
          DialogueId = 51009942,
          GUID = "7FB2B29C",
          NextDialogue = 51009943,
          SpeakNpcId = 700300,
          Subtitle = "...After she passed, I sang the finished final act of Putini for Sig. He was hollowed by grief — but when he heard it, his eyes lit with disbelief... and for a moment, I saw hope flicker in the ashes."
        },
        [51009943] = {
          ContentFR = "Nous avions encore une chance de faire vivre Violette à travers son œuvre. Sa joie, sa tristesse, son espoir, sa nostalgie — tout est dans cette pièce. Je voulais la faire connaître au monde. Je devais le faire.",
          DialogueId = 51009943,
          GUID = "7FB2B2C6",
          NextDialogue = 51009944,
          SpeakNpcId = 700300,
          Subtitle = "We still have a chance to honour her. Violet poured her joy, sorrow, hope, and longing into that script. I want the world to hear it — I need to make sure they do."
        },
        [51009944] = {
          ContentFR = "Nous étions toutes deux nées pour la scène. La maladie l’a emportée trop tôt, mais je porterai son âme sur chaque scène, dans chaque lumière.",
          DialogueId = 51009944,
          GUID = "7FB2B2F0",
          NextDialogue = 51009945,
          SpeakNpcId = 700300,
          Subtitle = "We were both born for the stage. Illness took her far too soon, but I'll carry her soul in every role I play — in every spotlight I step into."
        },
        [51009945] = {
          ContentFR = "Alors, pour t’aider à échapper au contrôle de ton père... et pour accomplir la dernière volonté de Violette... Sig a accepté de jouer son rôle dans cette mise en scène.",
          DialogueId = 51009945,
          GUID = "7FB2B31A",
          NextDialogue = 51009946,
          SpeakNpcId = 100001,
          Subtitle = "So to help you escape your father's grip — and to fulfil Violet's last wish — Sig agreed to play his part in the act."
        },
        [51009946] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non... impossible. Si tout cela est vrai, alors pourquoi a-t-elle dit tout ce qu’elle vient d’avouer... ?",
          DialogueId = 51009946,
          FacialId = {
            [1] = "700302:CM_Shock01"
          },
          GUID = "7FB2B344",
          NextDialogue = 51009947,
          SpeakNpcId = 700302,
          Subtitle = "No... That can't be... If that's true, then why did she just—?",
          TalkActionId = {
            [1] = "700302:Shock_Start"
          }
        },
        [51009947] = {
          ContentFR = "Parce que tu es venue ici avec ta version des faits déjà décidée, Giselle. Et Madame Violetta avait peur qu’en te contredisant, elle mette la vie de son élève Rosalind en danger.",
          DialogueId = 51009947,
          GUID = "7FB2B36E",
          NextDialogue = 51009948,
          SpeakNpcId = 100001,
          Subtitle = "You came here convinced of her guilt, Giselle. And Ms Violetta couldn't risk provoking you — not with her student Rosalind's safety at stake."
        },
        [51009948] = {
          ContentFR = "Qu... Quoi... ?",
          DialogueId = 51009948,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2B398",
          NextDialogue = 51009949,
          SpeakNpcId = 700302,
          Subtitle = "What—?",
          TalkActionId = {
            [1] = "700302:Shock_End"
          }
        },
        [51009949] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai une requête... Je ne m’enfuirai pas, je te le promets. Mais accompagne-moi. J’aimerais te montrer un endroit.",
          DialogueId = 51009949,
          GUID = "7FB2B3C2",
          NextOptions = {
            [1] = 510098591
          },
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 700300,
          Subtitle = "I have a request... I won't run, I promise. Just — come with me. There's somewhere I need to go."
        },
        [51009950] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,false,DoNotOverride,2.8",
          ContentFR = "D’accord. Mais mieux vaut pour toi ne pas essayer de jouer à un petit jeu.",
          DialogueId = 51009950,
          GUID = "7FB2B3EC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          SpeakNpcId = 700302,
          Subtitle = "Fine. But don't think you can pull any tricks.",
          TalkActionId = {
            [1] = "700302:Agree"
          }
        },
        [51009951] = {
          Camera = "-257.950684,511.992188,553.037598,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tout a été reconstruit... Et pourtant, à mes yeux, chaque brique, chaque pierre est restée figée dans son état d’il y a seize ans.",
          DialogueId = 51009951,
          FinalCamera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2B416",
          LookAt = {
            [1] = "100001:n(700300)",
            [2] = "700302:n(700300)"
          },
          NextDialogue = 51009952,
          SpeakNpcId = 700300,
          Subtitle = "It's all been rebuilt... But to me, every brick, every stone still looks just as it did back then.",
          ToFinalCameraBlendTime = 5
        },
        [51009952] = {
          ContentFR = "Violette... je suis revenue te voir. Et j’ai apporté avec moi notre œuvre.",
          DialogueId = 51009952,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2B440",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009953,
          SpeakNpcId = 700300,
          Subtitle = "Violet... I came back to see you. And I brought our work with me.",
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009953] = {
          ContentFR = "Quelqu’un a fini par comprendre notre histoire... Et étrangement, ça ne m’effraie pas. Je me sens presque soulagée. Peut-être parce que je peux enfin te le dire comme il faut... Pour Sig... je suis désolée.",
          DialogueId = 51009953,
          GUID = "7FB2B46A",
          NextDialogue = 51009954,
          SpeakNpcId = 700300,
          Subtitle = "Someone with a sharp eye pieced together our story. Strangely, I'm not scared. I feel... relieved. Maybe because, at long last, I can say this to you properly: I'm sorry. About Sig."
        },
        [51009954] = {
          ContentFR = "Violetta fit glisser ses doigts sur le mur, comme si elle confiait ses souvenirs à une amie disparue depuis longtemps. Peut-être avait-elle simplement senti que le moment des adieux était venu.",
          DialogueId = 51009954,
          GUID = "7FB2B494",
          NextDialogue = 51009955,
          Subtitle = "(Violetta's fingers graze the wall, as if sharing memories with an old friend she hasn't seen in years. Perhaps the time for farewell has come, and that's what brought her back here.)",
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009955] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci... de m’avoir laissée suivre mes caprices jusqu’au bout.",
          DialogueId = 51009955,
          GUID = "7FB2B4BE",
          NextDialogue = 51009956,
          SpeakNpcId = 700300,
          Subtitle = "Thank you... for indulging me.",
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009956] = {
          ContentFR = "Alors, Violetta... si tu as accepté de porter seule la faute, c’est aussi parce que la mort de Sig n’était pas prévue, n’est-ce pas ?",
          DialogueId = 51009956,
          GUID = "7FB2B4E8",
          NextDialogue = 51009957,
          SpeakNpcId = 100001,
          Subtitle = "So, Violetta... You went along with the accusations for another reason, didn't you? Because Sig's death — that wasn't part of your plan.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009957] = {
          ContentFR = "... Fabrice Ruthford. C’était un homme froid et impitoyable. Les mineurs sous ses ordres mouraient presque de faim. Même les Veilleurs souffraient sous sa poigne de fer.",
          DialogueId = 51009957,
          GUID = "7FB2B512",
          NextDialogue = 51009958,
          SpeakNpcId = 700300,
          Subtitle = "Fabrice Ruthford... He was a ruthless, heartless man. The miners under him starved. His Escort officers weren't much better off.",
          TalkActionId = {
            [1] = "700300:Disagree",
            [2] = "100001:Explain01_End"
          }
        },
        [51009958] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Même envers sa propre fille, il ne faisait preuve d’aucune tendresse. Il rejetait tout ce qu’elle était, piétinait ses rêves, emprisonnait sa liberté... Il voulait la façonner selon la vie sans éclat qu’il avait planifiée pour elle.",
          DialogueId = 51009958,
          FinalCamera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2B53C",
          NextDialogue = 51009959,
          SpeakNpcId = 700300,
          Subtitle = "He showed no mercy — not even to his own daughter. He dismissed everything she was, crushed her dreams, caged her spirit... and forced her into the lifeless future he had planned.",
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10
        },
        [51009959] = {
          ContentFR = "Et pourtant... quand sa fille est \"morte\", cet homme cruel a ignoré toute procédure judiciaire pour exécuter lui-même l’auteur de l’enlèvement — quitte à offrir à ses ennemis l’arme pour le destituer.",
          DialogueId = 51009959,
          GUID = "7FB2B566",
          NextDialogue = 51009960,
          SpeakNpcId = 700300,
          Subtitle = "And yet... when his daughter \"died,\" the same heartless man threw aside all legal procedure and executed the kidnapper with his own hands — knowing full well it would cost him his career."
        },
        [51009960] = {
          ContentFR = "J’avais imaginé mille plans pour envoyer une lettre au tribunal après m’être enfuie... Assez pour innocenter Sig. Mais ce à quoi je n’avais jamais pensé —",
          DialogueId = 51009960,
          GUID = "7FB2B590",
          NextDialogue = 51009961,
          SpeakNpcId = 700300,
          Subtitle = "I thought of countless ways to slip the truth to the court once I was free. I thought I could save Sig in secret. But the one thing I never imagined—"
        },
        [51009961] = {
          ContentFR = "... C’est que ton père t’aimait bien plus que tu ne le croyais.",
          DialogueId = 51009961,
          GUID = "7FB2B5BA",
          NextDialogue = 51009962,
          SpeakNpcId = 700302,
          Subtitle = "...Was that your father loved you more than you ever knew.",
          TalkActionId = {
            [1] = "700302:Talk02_Start"
          }
        },
        [51009962] = {
          ContentFR = "... Il y a eu tant de fois où j’ai voulu tout avouer. Mais Hyperborea n’était que le point de départ : son œuvre devait voyager à travers le monde. Je devais tenir ma promesse... ou du moins essayer.",
          DialogueId = 51009962,
          GUID = "7FB2B5E4",
          NextDialogue = 51009963,
          SpeakNpcId = 700300,
          Subtitle = "...There were so many times I wanted to reveal the truth. But Hyperborea was only the beginning — her story needed to reach the world. I had to keep my promise... or at least, keep trying.",
          TalkActionId = {
            [1] = "700300:Sigh_End",
            [2] = "700302:Talk02_End"
          }
        },
        [51009963] = {
          ContentFR = "Alors quand tu es venue me trouver, Giselle... j’ai ressenti un étrange soulagement. J’ai formé de nombreux enfants talentueux, et eux pourront porter <I>Putini</> encore plus loin que moi.",
          DialogueId = 51009963,
          GUID = "7FB2B60E",
          LookAt = {
            [1] = "700300:n(700302)"
          },
          NextDialogue = 51009964,
          SpeakNpcId = 700300,
          Subtitle = "So when you came to me, Giselle... I felt oddly relieved. I've trained many gifted children over the years. They can carry Putini farther and wider than I ever could.",
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009964] = {
          ContentFR = "Et il te suffisait... d’endosser la culpabilité aux yeux de Giselle, pour laver Sig d’un crime qui n’était pas le sien.",
          DialogueId = 51009964,
          GUID = "7FB2B638",
          NextDialogue = 51009965,
          SpeakNpcId = 100001,
          Subtitle = "And all you had to do... was let Giselle believe it was true. So you could finally clear Sig's name."
        },
        [51009965] = {
          ContentFR = "... Je te suivrai, Giselle. Mais seulement si tu libères Rosalind Magnus.",
          DialogueId = 51009965,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB2B662",
          NextDialogue = 51009966,
          SpeakNpcId = 700300,
          Subtitle = "...I'll go with you, Giselle. But only after you release Rosalind Magnus."
        },
        [51009966] = {
          ContentFR = "Pour moi... pour Sig et pour Violette... il ne doit rien lui arriver.",
          DialogueId = 51009966,
          GUID = "7FB2B68C",
          NextDialogue = 51009967,
          SpeakNpcId = 700300,
          Subtitle = "For my sake... and for Sig and Violet... she must not come to harm."
        },
        [51009967] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Elle a déjà quitté Givrelac.",
          DialogueId = 51009967,
          GUID = "7FB2B6B6",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009968,
          SpeakNpcId = 700302,
          Subtitle = "...She's already left Icelake.",
          TalkActionId = {
            [1] = "700302:Talk01_Start",
            [2] = "700300:Talk02_End"
          }
        },
        [51009968] = {
          Camera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quoi ?!",
          DialogueId = 51009968,
          FacialId = {
            [1] = "700300:CM_Shock01"
          },
          GUID = "7FB2B6E0",
          NextDialogue = 51009969,
          SpeakNpcId = 700300,
          Subtitle = "What?",
          TalkActionId = {
            [1] = "700300:Shock_Start"
          }
        },
        [51009969] = {
          Camera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu étais son professeur de chant, tu sais donc ce qu’elle affrontait.",
          DialogueId = 51009969,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2B70A",
          NextDialogue = 51009970,
          SpeakNpcId = 700302,
          Subtitle = "You were her vocal teacher. You should know what she was up against."
        },
        [51009970] = {
          ContentFR = "Une oiselle prête à se briser les ailes pour s’échapper de sa cage... Vous deux, vous vous ressemblez énormément.",
          DialogueId = 51009970,
          GUID = "7FB2B734",
          NextDialogue = 51009971,
          SpeakNpcId = 700302,
          Subtitle = "A fledgling willing to break her own wings just to escape the cage... The two of you really are cut from the same cloth."
        },
        [51009971] = {
          ContentFR = "Alors tout ce temps... tu me mentais.",
          DialogueId = 51009971,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2B75E",
          NextDialogue = 51009972,
          SpeakNpcId = 700300,
          Subtitle = "So all this time... you were lying to me.",
          TalkActionId = {
            [1] = "700300:Shock_End"
          }
        },
        [51009972] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce n’était pas prévu. Je ne pensais pas que quelqu’un d’aussi proche de toi viendrait m’engager pour la \"kidnapper\". J’ai simplement... profité de l’occasion.",
          DialogueId = 51009972,
          GUID = "7FB2B788",
          NextDialogue = 51009973,
          SpeakNpcId = 700302,
          Subtitle = "It wasn't my plan. I didn't expect someone close to you would come to hire me to \"kidnap\" her. I just... took the chance when it came.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51009973] = {
          ContentFR = "Alors ? Mon jeu d’actrice était convaincant, non ? Peut-être que je devrais songer à changer de métier.",
          DialogueId = 51009973,
          GUID = "7FB2B7B2",
          NextDialogue = 51009974,
          SpeakNpcId = 700302,
          Subtitle = "Pretty convincing performance, wasn't it? Maybe it's time I tried the stage."
        },
        [51009974] = {
          Camera = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu ne veux plus être une Chasseuse de Phoxène ?",
          DialogueId = 51009974,
          FacialId = {
            [1] = "100001:Happy01"
          },
          GUID = "7FB2B7DC",
          NextDialogue = 51009975,
          SpeakNpcId = 100001,
          Subtitle = "You don't want to be a Phoxhunter anymore?",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009975] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Eh bien. Avec tout ce vacarme autour de \"l’enlèvement\" de la demoiselle Magnus, je vais devoir disparaître quelque temps de toute façon.",
          DialogueId = 51009975,
          GUID = "7FB2B806",
          NextDialogue = 51009976,
          SpeakNpcId = 700302,
          Subtitle = "Heh. Thanks to the big stir over Lady Magnus's kidnapping, I'll be laying low for a good while anyway."
        },
        [51009976] = {
          ContentFR = "Quant à Violetta...",
          DialogueId = 51009976,
          GUID = "7FB2B830",
          NextDialogue = 51009977,
          SpeakNpcId = 700302,
          Subtitle = "As for Violetta...",
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51009977] = {
          Camera = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{nickname}, c’est toi qui vas décider. Puisque tu as découvert la vérité avant moi, c’est à toi de choisir ce qu’il adviendra d’elle.",
          DialogueId = 51009977,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2B85A",
          LookAt = {
            [1] = "700300:n(100001)"
          },
          NextDialogue = 51009978,
          SpeakNpcId = 700302,
          Subtitle = "It's your call, . You uncovered the truth before I could — so you get to decide what happens next.",
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51009978] = {
          ContentFR = "Tu es sûre, Giselle ?",
          DialogueId = 51009978,
          GUID = "7FB2B884",
          NextDialogue = 51009979,
          SpeakNpcId = 100001,
          Subtitle = "Are you sure, Giselle?",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009979] = {
          Camera = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je n’en sais rien. <H>Si nous révélons la vérité, elle pourrait tout perdre — son nom, son rêve. Mais si nous gardons le silence... le nom de Sig ne sera jamais lavé.</>",
          DialogueId = 51009979,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2B8AE",
          NextDialogue = 51009980,
          SpeakNpcId = 700302,
          Subtitle = "I don't know. If we tell the world, she could lose everything — her name, her dream, all of it. But if we keep it quiet... then Sig's name will never be cleared."
        },
        [51009980] = {
          ContentFR = "Je ne sais plus quoi penser. Peut-être qu’il vaut mieux que ce soit toi qui décides.",
          DialogueId = 51009980,
          GUID = "7FB2B8D8",
          NextDialogue = 51009981,
          SpeakNpcId = 700302,
          Subtitle = "I can't think straight right now. Maybe handing the choice to you really is best."
        },
        [51009981] = {
          ContentFR = "Si c’est toi qui fais ce choix... je l’accepterai.",
          DialogueId = 51009981,
          GUID = "7FB2B902",
          NextOptions = {
            [1] = 510098911,
            [2] = 510098912
          },
          SpeakNpcId = 700300,
          Subtitle = "If it's your decision... I'll readily accept it.",
          TalkActionId = {
            [1] = "700300:Agree"
          },
          bForbidSkipOptions = true
        },
        [51009982] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Giselle.",
          DialogueId = 51009982,
          GUID = "7FB2B92C",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009983,
          SpeakNpcId = 100001,
          Subtitle = "Giselle.",
          TalkActionId = {
            [1] = "700302:Talk03_Start"
          }
        },
        [51009983] = {
          ContentFR = "Je t’écoute.",
          DialogueId = 51009983,
          GUID = "7FB2B956",
          NextDialogue = 51009984,
          SpeakNpcId = 700302,
          Subtitle = "I'm listening."
        },
        [51009984] = {
          Camera = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Est-ce qu’on ne pourrait pas simplement... ne rien dire ? Ne pas révéler toute cette histoire ?",
          DialogueId = 51009984,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "7FB2B980",
          NextDialogue = 51009985,
          SpeakNpcId = 100001,
          Subtitle = "Can we... keep it quiet? Not bring this all to light?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          }
        },
        [51009985] = {
          Camera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Sig a donné sa vie et son honneur pour que Violetta fasse vivre <I>Putini</>. Je ne crois pas que ce soit ainsi qu’il voudrait que ça se termine.",
          DialogueId = 51009985,
          GUID = "7FB2B9AA",
          NextDialogue = 51009986,
          SpeakNpcId = 100001,
          Subtitle = "Sig bore the blame — and even gave his life — so Ms Violetta could share Putini with the world. I don't think this is how he'd want things to end."
        },
        [51009986] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... D’accord. Je comprends.",
          DialogueId = 51009986,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2B9D4",
          NextDialogue = 51009987,
          SpeakNpcId = 700302,
          Subtitle = "...All right. I understand.",
          TalkActionId = {
            [1] = "700302:Agree",
            [2] = "100001:Explain02_End"
          }
        },
        [51009987] = {
          ContentFR = "Giselle ?",
          DialogueId = 51009987,
          GUID = "7FB2B9FE",
          NextDialogue = 51009988,
          SpeakNpcId = 700300,
          Subtitle = "Giselle?"
        },
        [51009988] = {
          ContentFR = "C’est toi qui choisis. Alors je respecterai ta décision.",
          DialogueId = 51009988,
          GUID = "7FB2BA28",
          NextDialogue = 51009989,
          SpeakNpcId = 700302,
          Subtitle = "I left the choice to you. So I'll respect your decision."
        },
        [51009989] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je t’en suis profondément reconnaissante.",
          DialogueId = 51009989,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2BA52",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009990,
          SpeakNpcId = 700300,
          Subtitle = "I'm truly grateful.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009990] = {
          ContentFR = "Dans ce cas, nous sommes d’accord.",
          DialogueId = 51009990,
          GUID = "7FB2BA7C",
          NextDialogue = 51009991,
          SpeakNpcId = 700302,
          Subtitle = "Then it's settled, I suppose.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51009991] = {
          Camera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh, et... accepteriez-vous de venir à la représentation dans deux jours ? Je vous réserverai les meilleures places.",
          DialogueId = 51009991,
          GUID = "7FB2BAA6",
          NextDialogue = 51009992,
          SpeakNpcId = 700300,
          Subtitle = "In that case... would you both honour me with your presence at the performance two days from now? I'll have the finest seats in the house prepared."
        },
        [51009992] = {
          ContentFR = "Une représentation... ?",
          DialogueId = 51009992,
          GUID = "7FB2BAD0",
          NextDialogue = 51009993,
          SpeakNpcId = 700302,
          Subtitle = "A performance...?"
        },
        [51009993] = {
          ContentFR = "Oui, <I>Putini</>. Considère-la comme une représentation d’adieu pour Rosalind. C’est sa pièce préférée.",
          DialogueId = 51009993,
          GUID = "7FB2BAFA",
          NextDialogue = 51010006,
          SpeakNpcId = 700300,
          Subtitle = "Yes — Putini. Think of it as a send-off for Rosalind... It's her favourite play."
        },
        [51009994] = {
          Camera = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je comprends ce que tu as fait, Violetta. Mais on ne peut pas laisser un homme être considéré comme un meurtrier, même après sa mort.",
          DialogueId = 51009994,
          GUID = "7FB2BB24",
          LookAt = {
            [1] = "700300:n(100001)"
          },
          NextDialogue = 51009995,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"100001:n(700300)"}},
PlayAnimation{ActorId{100001},AnimationId{"Talk01_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "I understand why you did it, Ms Violetta. But we can't let an innocent man be remembered as a murderer even in death."
        },
        [51009995] = {
          ContentFR = "Sig n’est plus là. Mais nous avons encore la possibilité de laver son nom.",
          DialogueId = 51009995,
          GUID = "7FB2BB4E",
          NextDialogue = 51009996,
          SpeakNpcId = 100001,
          Subtitle = "Sig's gone. But we still have a chance to clear his name."
        },
        [51009996] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{nickname}... Merci.",
          DialogueId = 51009996,
          GUID = "7FB2BB78",
          NextDialogue = 51009997,
          SpeakNpcId = 700302,
          Subtitle = "...Thank you, .",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51009997] = {
          ContentFR = "Sig t’a enlevée pour l’argent, oui. Mais ce n’est pas un meurtrier. La vérité doit être révélée.",
          DialogueId = 51009997,
          GUID = "7FB2BBA2",
          NextDialogue = 51009998,
          SpeakNpcId = 100001,
          Subtitle = "Sig did kidnap you for money. But that doesn't make him a murderer. The truth deserves to be heard."
        },
        [51009998] = {
          Camera = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Violetta... une fois que ce sera public, tu risques de tout perdre : ta réputation, ta carrière...",
          DialogueId = 51009998,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2BBCC",
          NextDialogue = 51009999,
          SpeakNpcId = 100001,
          Subtitle = "Ms Violetta... once this is made public, it may cost you everything. Your reputation, your career..."
        },
        [51009999] = {
          ContentFR = "Je comprends. Mais c’est très bien ainsi... Pardon, Violette. Notre rêve devra continuer à vivre à travers ces enfants.",
          DialogueId = 51009999,
          GUID = "7FB2BBF6",
          NextDialogue = 51010000,
          SpeakNpcId = 700300,
          Subtitle = "I understand. But that's all right. I'm sorry, Violet. Our dream... will have to live on through the children now."
        },
        [51010000] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dans ce cas, nous sommes d’accord.",
          DialogueId = 51010000,
          GUID = "7FB2BC20",
          LookAt = {
            [1] = "700300:n(700302)"
          },
          NextDialogue = 51010001,
          SpeakNpcId = 700302,
          Subtitle = "Then it's settled, I suppose."
        },
        [51010001] = {
          ContentFR = "Une dernière chose...",
          DialogueId = 51010001,
          GUID = "7FB2BC4A",
          NextDialogue = 51010002,
          SpeakNpcId = 700300,
          Subtitle = "One last thing..."
        },
        [51010002] = {
          ContentFR = "Hmm ? Il est un peu tard pour changer d’avis.",
          DialogueId = 51010002,
          GUID = "7FB2BC74",
          NextDialogue = 51010003,
          SpeakNpcId = 700302,
          Subtitle = "Hm? If you're thinking of backing out, it's a bit late for that.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010003] = {
          Camera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh non. Je voulais simplement vous inviter à une représentation, dans deux jours. Considérez-la comme mon chant du cygne. Je préparerai les meilleures places pour vous deux.",
          DialogueId = 51010003,
          GUID = "7FB2BC9E",
          NextDialogue = 51010004,
          SpeakNpcId = 700300,
          Subtitle = "Nothing of the sort. I'd simply like to invite you both to a performance — two nights from now. Think of it as my swan song. I'll make sure the best seats are ready.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010004] = {
          ContentFR = "Ton chant du cygne, hein... ?",
          DialogueId = 51010004,
          GUID = "7FB2BCC8",
          NextDialogue = 51010005,
          SpeakNpcId = 700302,
          Subtitle = "Your swan song...?"
        },
        [51010005] = {
          ContentFR = "Oui. <I>Putini</>. Tout a commencé avec cette pièce — et c’est ainsi que cela doit se terminer.",
          DialogueId = 51010005,
          GUID = "7FB2BCF2",
          NextDialogue = 51010006,
          SpeakNpcId = 700300,
          Subtitle = "Yes. Putini. It all began with this play — and it's only right it ends with it too."
        }
      }
    end
  },
