          DialogueId = 51010006,
          GUID = "7FB2BD1C",
          NextDialogue = 51010007,
          SpeakNpcId = 100001,
          Subtitle = "I'll be there.",
          TalkActionId = {
            [1] = "100001:Agree"
          }
        },
        [51010007] = {
          ContentFR = "Une seule place suffira.",
          DialogueId = 51010007,
          GUID = "7FB2BD46",
          NextDialogue = 51010008,
          SpeakNpcId = 700302,
          Subtitle = "One good seat will do."
        },
        [51010008] = {
          ContentFR = "...",
          DialogueId = 51010008,
          GUID = "7FB2BD70",
          NextDialogue = 51010009,
          SpeakNpcId = 700300,
          Subtitle = "..."
        },
        [51010009] = {
          ContentFR = "Ne te méprends pas, je viendrai. Mais disons que pour une \"demi-fugitive\", mieux vaut ne pas trop se faire remarquer.",
          DialogueId = 51010009,
          GUID = "7FB2BD9A",
          NextDialogue = 51010010,
          SpeakNpcId = 700302,
          Subtitle = "Don't get me wrong — I'll be there. But considering I'm technically wanted at the moment, best I keep a low profile."
        },
        [51010010] = {
          ContentFR = "Très bien. Je vais prévenir la troupe.",
          DialogueId = 51010010,
          GUID = "7FB2BDC4",
          NextDialogue = 51010011,
          SpeakNpcId = 700300,
          Subtitle = "Very well. I'll speak to the troupe and have the seats arranged."
        },
        [51010011] = {
          ContentFR = "Dans ce cas... rendez-vous dans deux jours.",
          DialogueId = 51010011,
          GUID = "7FB2BDEE",
          SpeakNpcId = 700300,
          Subtitle = "Then... I'll see you both in two days."
        },
        [51010012] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bonjour, Violetta.",
          DialogueId = 51010012,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2BE18",
          NextDialogue = 51010013,
          SpeakNpcId = 100001,
          Subtitle = "Good morning, Ms Violetta.",
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51010013] = {
          ContentFR = "Vous voilà. Tenez, voici vos billets.",
          DialogueId = 51010013,
          GUID = "7FB2BE42",
          NextDialogue = 51010014,
          SpeakNpcId = 700300,
          Subtitle = "You made it. Here — your tickets.",
          TalkActionId = {
            [1] = "700300:Give",
            [2] = "100001:Talk02_End"
          }
        },
        [51010014] = {
          ContentFR = "Eh bien, je ne vais pas me faire prier.",
          DialogueId = 51010014,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2BE6C",
          NextDialogue = 51010015,
          SpeakNpcId = 700302,
          Subtitle = "Thanks.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010015] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,false,Manual,2.8",
          ContentFR = "Allez-y. Faire voyager <I>Putini</> à travers le monde était le dernier vœu de Violette. Elle ne m’en voudra pas d’offrir deux places.",
          DialogueId = 51010015,
          GUID = "7FB2BE96",
          NextDialogue = 51010016,
          SpeakNpcId = 700300,
          Subtitle = "Be my guest. Sharing Putini with the world was Violet's dream. She wouldn't mind a pair of seats given freely.",
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51010016] = {
          ContentFR = "C’est juste que...",
          DialogueId = 51010016,
          GUID = "7FB2BEC0",
          NextDialogue = 51010017,
          SpeakNpcId = 700300,
          Subtitle = "It's just...",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010017] = {
          ContentFR = "... Tu penses à Mademoiselle Rosalind, n’est-ce pas ?",
          DialogueId = 51010017,
          GUID = "7FB2BEEA",
          NextDialogue = 51010018,
          SpeakNpcId = 100001,
          Subtitle = "You're thinking of Miss Rosalind?"
        },
        [51010018] = {
          ContentFR = "Mmh. C’était censé être sa représentation d’adieu. Mais j’ignore même si elle est toujours à Givrelac... ou si elle pourra assister à sa pièce préférée.",
          DialogueId = 51010018,
          GUID = "7FB2BF14",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700300:n(700302)"
          },
          NextDialogue = 51010019,
          SpeakNpcId = 700300,
          Subtitle = "Mm. I meant this to be her send-off... but I don't even know if she's still in Icelake. Or if she'll get to see the play she loves most."
        },
        [51010019] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001564,38.587292,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ne me regarde pas. Pour éviter que ses parents ne la retrouvent, j’ai moi-même préféré ne pas connaître sa cachette.",
          DialogueId = 51010019,
          FacialId = {
            [1] = "700302:CM_Shock01"
          },
          GUID = "7FB2BF3E",
          NextOptions = {
            [1] = 510099291,
            [2] = 510099292
          },
          SpeakNpcId = 700302,
          Subtitle = "Don't look at me. I've no clue where she is now either. Figured the less I know, the harder it is for her parents to track her down."
        },
        [51010020] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,false,Manual,2.8",
          ContentFR = "Espérons-le... Oh, {nickname}.",
          DialogueId = 51010020,
          FacialId = {
            [1] = "700302:CM_Idle",
            [2] = "700300:CM_Smile01"
          },
          GUID = "7FB2BF68",
          SpeakNpcId = 700300,
          Subtitle = "Let's hope so... Oh, ."
        },
        [51010021] = {
          ContentFR = "Tu as relié entre eux trois événements qui semblaient sans lien... pour en faire une histoire à la fin heureuse. Ton esprit et ta détermination m’impressionnent.",
          DialogueId = 51010021,
          GUID = "7FB2BF92",
          NextDialogue = 51010022,
          SpeakNpcId = 700300,
          Subtitle = "You tied together three threads no one thought related... and led them to a joyful ending. Your sharp mind and resolve are remarkable."
        },
        [51010022] = {
          ContentFR = "J’ai donc une autre mission à te proposer — elle concerne l’un de mes élèves. La récompense n’est pas un souci. Passe me voir au théâtre quand tu auras le temps.",
          DialogueId = 51010022,
          GUID = "7FB2BFBC",
          NextDialogue = 51010023,
          SpeakNpcId = 700300,
          Subtitle = "Which brings me to another request — it concerns another of my students. I hope you'll take the case. The fee will be fair, of course. Just visit me at the theatre when you have a moment."
        },
        [51010023] = {
          ContentFR = "Mais pas ce soir — ce soir appartient à la musique, et au grand départ. Laisse tes soucis derrière toi... et profite de cette nuit inoubliable.",
          DialogueId = 51010023,
          GUID = "7FB2BFE6",
          SpeakNpcId = 700300,
          Subtitle = "But not tonight — tonight is for music, and voyage. Leave your burdens behind — and let this be a night to remember."
        },
        [51010024] = {
          ContentFR = "Tu trouves les places réservées par Violetta et t’installes, attendant que le rideau se lève.",
          DialogueId = 51010024,
          GUID = "7FB2C010",
          NextDialogue = 51010025,
          Subtitle = "You find the seats Violetta reserved for you and settle in, waiting for the curtain to rise."
        },
        [51010025] = {
          ContentFR = "Alors que les lumières s’éteignent peu à peu, une puissante voix de soprano s’élève derrière le rideau, emplissant la salle d’une magie indicible.",
          DialogueId = 51010025,
          GUID = "7FB2C03A",
          NextDialogue = 51010026,
          Subtitle = "As the house lights dim, a powerful soprano unfurls from behind the curtain, flooding the theatre with wonder."
        },
        [51010026] = {
          ContentFR = "Le public retient son souffle. Ce silence profond te met presque mal à l’aise.",
          DialogueId = 51010026,
          GUID = "7FB2C064",
          NextDialogue = 51010027,
          Subtitle = "The audience holds its breath. The silence is so deep, it unsettles you."
        },
        [51010027] = {
          ContentFR = "Il est difficile de retenir tes exclamations face aux scènes les plus spectaculaires — tu crains qu’un soupir d’admiration n’interrompe l’enchantement.",
          DialogueId = 51010027,
          GUID = "7FB2C08E",
          NextDialogue = 51010028,
          Subtitle = "It's hard to hold back a gasp at the dazzling moments — you're almost afraid the sound of your spontaneous awe might spoil the magic."
        },
        [51010028] = {
          ContentFR = "Mais cette crainte s’évanouit vite — tant et si bien qu’au moment où le dernier son s’éteint, tu en oublies même d’applaudir.",
          DialogueId = 51010028,
          GUID = "7FB2C0B8",
          Subtitle = "But your worries melt away — by the time the final note falls, you're so mesmerised, you've forgotten even to applaud."
        },
        [51010029] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ouf... C’était vraiment une pièce magnifique. J’en ai presque oublié à quel point je déteste les endroits clos et bondés.",
          DialogueId = 51010029,
          GUID = "7FB2C0E2",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010030,
          SpeakNpcId = 700302,
          Subtitle = "Whew. That was quite the show. Almost made me forget how much I hate crowded, enclosed spaces."
        },
        [51010030] = {
          ContentFR = "Je crois que je comprends enfin pourquoi la scène fascine autant les gens.",
          DialogueId = 51010030,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2C10C",
          NextDialogue = 51010031,
          SpeakNpcId = 100001,
          Subtitle = "I think I finally get why the stage holds such magic for people.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010031] = {
          ContentFR = "Espérons simplement que les gens arrêteront de me donner du fil à retordre... Je ne veux plus jamais avoir à \"kidnapper\" mes propres clients.",
          DialogueId = 51010031,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2C136",
          NextDialogue = 51010032,
          SpeakNpcId = 700302,
          Subtitle = "I just hope folks stop asking me to kidnap themselves. Not exactly the career path I had in mind.",
          TalkActionId = {
            [1] = "700302:Confident_Start",
            [2] = "100001:Talk02R_End"
          }
        },
        [51010032] = {
          ContentFR = "Même si, pour être honnête, je ne suis pas mieux. Moi aussi, je me suis enfermée dans mes obsessions pendant des années.",
          DialogueId = 51010032,
          GUID = "7FB2C160",
          NextDialogue = 51010033,
          SpeakNpcId = 700302,
          Subtitle = "Then again, who am I to judge? I've spent half my life stuck in my own mess."
        },
        [51010033] = {
          ContentFR = "Je suis {性别:curieux|curieuse}... pourquoi cette affaire te tenait-elle autant à cœur ?",
          DialogueId = 51010033,
          GUID = "7FB2C18A",
          NextDialogue = 51010034,
          SpeakNpcId = 100001,
          Subtitle = "Can I ask... why are you so invested in this case?"
        },
        [51010034] = {
          ContentFR = "... Je peux ne pas répondre à ça ?",
          DialogueId = 51010034,
          GUID = "7FB2C1B4",
          NextDialogue = 51010035,
          SpeakNpcId = 700302,
          Subtitle = "...Do I have to answer that?"
        },
        [51010035] = {
          ContentFR = "Tu n’es pas obligée d’en parler.",
          DialogueId = 51010035,
          GUID = "7FB2C1DE",
          NextDialogue = 51010036,
          SpeakNpcId = 100001,
          Subtitle = "Only if you want to.",
          TalkActionId = {
            [1] = "100001:AgreeHead",
            [2] = "700302:Confident_End"
          }
        },
        [51010036] = {
          ContentFR = "D’accord... inutile de faire des mystères avec quelqu’un d’aussi sincère que toi.",
          DialogueId = 51010036,
          GUID = "7FB2C208",
          NextDialogue = 51010037,
          SpeakNpcId = 700302,
          Subtitle = "...Okay. No point playing coy with someone as sincere and kind as you.",
          TalkActionId = {
            [1] = "700302:Talk02_Start"
          }
        },
        [51010037] = {
          ContentFR = "Donat t’a sûrement raconté qu’il avait dénoncé Sig. Eh bien, la personne à qui il s’est adressé... c’était moi.",
          DialogueId = 51010037,
          FacialId = {
            [1] = "700302:CM_Sad01"
          },
          GUID = "7FB2C232",
          NextDialogue = 51010038,
          SpeakNpcId = 700302,
          Subtitle = "Donat told you he turned Sig in, right? The person he came to... was me."
        },
        [51010038] = {
          ContentFR = "Au départ, pour ne pas l’effrayer, je voulais aller négocier seule, libérer l’otage sans faire de vagues. Mais quand j’ai réalisé qu’il s’agissait de la fille de mon supérieur, j’ai hésité... et j’ai fini par faire un rapport.",
          DialogueId = 51010038,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2C25C",
          NextDialogue = 51010039,
          SpeakNpcId = 700302,
          Subtitle = "At first, to avoid tipping off the culprit, I planned to go in alone, talk Sig down, and get the hostage out safely. But when I realised who she was — my superior's daughter — I hesitated. Ended up reporting it up the chain instead."
        },
        [51010039] = {
          ContentFR = "La suite, tu la connais. Son père a refusé mon plan, a perdu son sang-froid, et a lancé l’assaut.",
          DialogueId = 51010039,
          GUID = "7FB2C286",
          NextDialogue = 51010040,
          SpeakNpcId = 700302,
          Subtitle = "And... you know the rest. Her father lost it, rejected my proposal, and launched a full-on raid."
        },
        [51010040] = {
          ContentFR = "Si j’avais suivi mon instinct... peut-être que rien de tout cela ne serait arrivé.",
          DialogueId = 51010040,
          GUID = "7FB2C2B0",
          NextDialogue = 51010041,
          SpeakNpcId = 700302,
          Subtitle = "If I'd just stuck to my plan... maybe none of this would've happened."
        },
        [51010041] = {
          ContentFR = "Même si cela aurait rendu les choses plus difficiles pour Violetta, au moins Sig n’aurait pas été exécuté pour un crime qu’il n’avait pas commis.",
          DialogueId = 51010041,
          GUID = "7FB2C2DA",
          NextDialogue = 51010042,
          SpeakNpcId = 700302,
          Subtitle = "It might've made things a bit harder for Violetta... but at least Sig wouldn't have died for something he didn't do."
        },
        [51010042] = {
          ContentFR = "Giselle...",
          DialogueId = 51010042,
          GUID = "7FB2C304",
          NextDialogue = 51010043,
          SpeakNpcId = 100001,
          Subtitle = "Giselle...",
          TalkActionId = {
            [1] = "700302:Talk02_End"
          }
        },
        [51010043] = {
          ContentFR = "Je comprends sa réaction. Aucun parent ne supporterait la mort de son enfant. Mais je ne peux pas approuver qu’on rende justice avant d’avoir découvert toute la vérité.",
          DialogueId = 51010043,
          GUID = "7FB2C32E",
          NextDialogue = 51010044,
          SpeakNpcId = 700302,
          Subtitle = "I get why he did it — any parent who lost their child would. But justice should come after the full truth comes to light, not before.",
          TalkActionId = {
            [1] = "700302:Sigh_Start"
          }
        },
        [51010044] = {
          ContentFR = "Ce n’est pas pour ça que j’ai rejoint les Veilleurs.",
          DialogueId = 51010044,
          GUID = "7FB2C358",
          NextDialogue = 51010045,
          SpeakNpcId = 700302,
          Subtitle = "I didn't join the Escort for that."
        },
        [51010045] = {
          ContentFR = "Les Veilleurs ont perdu quelqu’un qui représentait vraiment la justice.",
          DialogueId = 51010045,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2C382",
          NextDialogue = 51010046,
          SpeakNpcId = 100001,
          Subtitle = "Then the Escort was a fool to lose someone who actually stood for justice.",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51010046] = {
          ContentFR = "... Est-ce que c’était un compliment ?",
          DialogueId = 51010046,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2C3AC",
          NextDialogue = 51010047,
          SpeakNpcId = 700302,
          Subtitle = "Was that a compliment?",
          TalkActionId = {
            [1] = "700302:Sigh_End"
          }
        },
        [51010047] = {
          ContentFR = "Quoi qu’il en soit, c’est du passé. Maintenant que tout est terminé, je vais voir si je peux rendre publique une partie de la vérité sur l’affaire — tout en gardant secrète l’identité de Violetta.",
          DialogueId = 51010047,
          GUID = "7FB2C3D6",
          NextDialogue = 51010048,
          SpeakNpcId = 700302,
          Subtitle = "Anyway, what's done is done. I'll see if I can reveal part of the truth — without exposing Violetta, of course.",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51010048] = {
          ContentFR = "Sans Enola, tu n’auras aucune preuve pour convaincre les Veilleurs de rouvrir l’enquête.",
          DialogueId = 51010048,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2C400",
          NextDialogue = 51010049,
          SpeakNpcId = 100001,
          Subtitle = "But without Enola herself, there's no solid proof. The Escort wouldn't reopen a case over just hearsay.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51010049] = {
          ContentFR = "Les Veilleurs ? Inutile. Je vais tout raconter à la presse. La rumeur est un juge bien plus puissant que des archives poussiéreuses.",
          DialogueId = 51010049,
          GUID = "7FB2C42A",
          NextDialogue = 51010050,
          SpeakNpcId = 700302,
          Subtitle = "The Escort? Nah, I'm not going to them. I'll tell the local papers. Let the story spread. The public makes a better jury than some dusty court records.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010050] = {
          ContentFR = "Tu crois que ça marchera vraiment... ?",
          DialogueId = 51010050,
          GUID = "7FB2C454",
          NextDialogue = 51010051,
          SpeakNpcId = 100001,
          Subtitle = "Will that really work...?"
        },
        [51010051] = {
          ContentFR = "Les gens adorent les secrets cachés. Croire qu’ils ont découvert ce qui se cache derrière les apparences les fait se sentir intelligents. Je vais juste... exploiter ça un peu.",
          DialogueId = 51010051,
          GUID = "7FB2C47E",
          NextDialogue = 51010052,
          SpeakNpcId = 700302,
          Subtitle = "People love hidden truths. Believing they know more than others about what's beneath the surface makes them feel smart. I'm just going to take advantage of that."
        },
        [51010052] = {
          ContentFR = "... Ah !",
          DialogueId = 51010052,
          GUID = "7FB2C4A8",
          IsBlack = 1,
          NextDialogue = 51010053,
          Scripts = [[
SEQ{
MoveTo{ActorId{700305},TargetPoint{"RosalindPoint1_20023305"},MoveSpeed{250},Visibility{"Show"}},
PARA{
LookAt{LookAtDescription{"100001:n(700305)"}},
LookAt{LookAtDescription{"700302:n(700305)"}},
TurnTo{TurnToDescription{"700305:n(100001)"}}
},
PARA{
PlayAnimation{ActorId{100001},AnimationId{"Shock_Start"},Duration{1}},
PlayAnimation{ActorId{700302},AnimationId{"Angry01_Start"},Duration{1}},
PlayAnimation{ActorId{700305},AnimationId{"Explain02_Start"},Duration{1}}
}}]],
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "...Whoops!"
        },
        [51010053] = {
          Camera = "-442.745117,136.447266,137.21167,0.000002,-3.200169,-35.40036,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "P-Pardon, je ne regardais pas devant moi ! Tu vas bien ? Je ne t’ai pas fait mal ?",
          DialogueId = 51010053,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2C4D2",
          NextDialogue = 51010054,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "S—Sorry! I didn't see you! Are you okay? Did I hurt you?"
        },
        [51010054] = {
          ContentFR = "Je vais bien. Faites juste attention, d’accord ?",
          DialogueId = 51010054,
          GUID = "7FB2C4FC",
          NextDialogue = 51010055,
          SpeakNpcId = 100001,
          Subtitle = "I'm fine. Just be more careful next time, alright?",
          TalkActionId = {
            [1] = "100001:Shock_End",
            [2] = "700302:Angry01_End"
          }
        },
        [51010055] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mmm...",
          DialogueId = 51010055,
          GUID = "7FB2C526",
          NextDialogue = 51010056,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "Mm...",
          TalkActionId = {
            [1] = "700305:Think_Start"
          }
        },
        [51010056] = {
          Camera = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai quelque chose sur le visage ?",
          DialogueId = 51010056,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "7FB2C550",
          NextDialogue = 51010057,
          SpeakNpcId = 100001,
          Subtitle = "What? Something on my face?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51010057] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non, rien du tout... Hihi... Merci pour les herbes ! Oh non, je vais être en retard !",
          DialogueId = 51010057,
          FacialId = {
            [1] = "700305:CM_Happy01"
          },
          GUID = "7FB2C57A",
          NextDialogue = 51010058,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "Nope! Hehe... Thanks for the herbs! Oh no, I'm gonna be late!",
          TalkActionId = {
            [1] = "700305:Think_End"
          }
        },
        [51010058] = {
          ContentFR = "Des herbes... ? Attendez, vous avez fait tomber quelque chose !",
          DialogueId = 51010058,
          GUID = "7FB2C5A4",
          NextDialogue = 51010059,
          Scripts = [[
SEQ{
MoveTo{ActorId{700305},TargetPoint{"RosalindPoint2_20023305"},MoveSpeed{250},Visibility{"Hide"}},
PlayAnimation{ActorId{100001},AnimationId{"Nvzhu_Story_StretchHand_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Herbs...? Wait— You dropped something!"
        },
        [51010059] = {
          ContentFR = "Garde-le ! C’est pour toi !",
          DialogueId = 51010059,
          GUID = "7FB2C5CE",
          NextDialogue = 51010060,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "You can keep it!!!"
        },
        [51010060] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Sérieusement... les jeunes, aujourd’hui, sont toujours aussi pressés.",
          DialogueId = 51010060,
          GUID = "7FB2C5F8",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010061,
          SpeakNpcId = 700302,
          Subtitle = "Seriously. Kids these days — always a whirlwind.",
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_End"
          }
        },
        [51010061] = {
          ContentFR = "Pourquoi m’a-t-elle laissé ça... ? Il y a une broderie dessus... C’est son nom ?",
          DialogueId = 51010061,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2C622",
          NextDialogue = 51010062,
          SpeakNpcId = 100001,
          Subtitle = "Why'd she leave this...? Huh, there's embroidery — is this her name...?"
        },
        [51010062] = {
          ContentFR = "... Putini ?",
          DialogueId = 51010062,
          GUID = "7FB2C64C",
          NextDialogue = 51010063,
          SpeakNpcId = 100001,
          Subtitle = "...Putini?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51010063] = {
          ContentFR = "« Si un jour tu rencontres une fille qui s’appelle Putini... j’espère que tu me reconnaîtras. Moi, je te reconnaîtrai. »",
          DialogueId = 51010063,
          GUID = "7FB2C676",
          IsBlack = 1,
          NextDialogue = 51010064,
          Subtitle = "If one day, you meet a girl named Putini... I hope you'll recognise me. And I promise — I'll recognise you."
        },
        [51010064] = {
          ContentFR = "Qu’est-ce qui te fait sourire comme ça ?",
          DialogueId = 51010064,
          FacialId = {
            [1] = "100001:Happy02"
          },
          GUID = "7FB2C6A0",
          NextDialogue = 51010065,
          SpeakNpcId = 700302,
          Subtitle = "What's so funny?",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51010065] = {
          ContentFR = "Si même toi tu ne l’as pas reconnue... peut-être que Violetta n’est pas la seule à avoir mille visages.",
          DialogueId = 51010065,
          GUID = "7FB2C6CA",
          NextDialogue = 51010066,
          SpeakNpcId = 100001,
          Subtitle = "If even you didn't recognise her... maybe Violetta's not the only one with a thousand faces.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010066] = {
          ContentFR = "La vie ne se joue jamais en un seul acte. Nous nous reverrons sur une nouvelle scène. D’ici là... bon voyage à toi, Mademoiselle Caisse.",
          DialogueId = 51010066,
          GUID = "7FB2C6F4",
          IsBlack = 1,
          SpeakNpcId = 100001,
          Subtitle = "Life's a play with more than one act. We'll meet again — on a new stage. Until then... safe travels, Miss Crate."
        },
        [51010067] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51010067,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "7FB2C71E",
          NextDialogue = 51010068,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [51010068] = {
          ContentFR = "Bonjour, {nickname}. Pourquoi cette mine triste ?",
          DialogueId = 51010068,
          GUID = "7FB2C748",
          NextDialogue = 51010069,
          SpeakNpcId = 700300,
          Subtitle = "Morning, . Why the gloomy face?"
        },
        [51010069] = {
          ContentFR = "Violetta...",
          DialogueId = 51010069,
          GUID = "7FB2C772",
          NextDialogue = 51010070,
          SpeakNpcId = 100001,
          Subtitle = "Ms Violetta..."
        },
        [51010070] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,false,Manual,2.8",
          ContentFR = "Allons, pas besoin d’en dire plus. C’est moi qui prends ma retraite, pas toi. Inutile d’avoir de la peine pour moi.",
          DialogueId = 51010070,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2C79C",
          NextDialogue = 51010071,
          SpeakNpcId = 700300,
          Subtitle = "Now, now — no need to feel sorry for me. I'm stepping down, not dying.",
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51010071] = {
          ContentFR = "Tu n’as fait que ce que ferait toute personne fidèle à ses principes. Ne porte pas ce poids sur tes épaules. Dis-toi simplement que tu as aidé une fugueuse à rentrer chez elle.",
          DialogueId = 51010071,
          GUID = "7FB2C7C6",
          NextDialogue = 51010072,
          SpeakNpcId = 700300,
          Subtitle = "You simply did what anyone with a conscience would. Don't let it weigh on you. Think of it this way: you just helped a runaway find her way home, that's all."
        },
        [51010072] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,false,DoNotOverride,2.8",
          ContentFR = "On dirait que tout le monde est là.",
          DialogueId = 51010072,
          GUID = "7FB2C7F0",
          NextDialogue = 51010073,
          Scripts = "MoveTo{ActorId{700302},TargetPoint{\"GisellePoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 700302,
          Subtitle = "Looks like everyone's here."
        },
        [51010073] = {
          ContentFR = "Parfait, Giselle, tiens — voici vos billets.",
          DialogueId = 51010073,
          GUID = "7FB2C81A",
          NextDialogue = 51010074,
          SpeakNpcId = 700300,
          Subtitle = "Miss Giselle — perfect timing. Here are your tickets.",
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51010074] = {
          ContentFR = "Merci. J’ai déjà contacté mes anciens collègues des Veilleurs : ils n’interviendront pas avant la fin du spectacle.",
          DialogueId = 51010074,
          GUID = "7FB2C844",
          NextDialogue = 51010075,
          SpeakNpcId = 700302,
          Subtitle = "Thanks. I've spoken to my old Escort contacts — they'll hold off until the curtain falls.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010075] = {
          ContentFR = "Je t’en suis très reconnaissante. La représentation va commencer, je dois aller en coulisses.",
          DialogueId = 51010075,
          GUID = "7FB2C86E",
          NextDialogue = 51010076,
          SpeakNpcId = 700300,
          Subtitle = "Much appreciated. The show's about to start — I'd better get backstage.",
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010076] = {
          ContentFR = "Allons-y aussi. Même si c’est en partie de ma faute, j’avoue que j’attends avec impatience cette représentation d’adieu.",
          DialogueId = 51010076,
          GUID = "7FB2C898",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010077,
          SpeakNpcId = 700302,
          Subtitle = "Let's head in too, then. I may have played a part in ending her stage career... but I've got to admit, I'm looking forward to her swan song."
        },
        [51010077] = {
          ContentFR = "Allons-y.",
          DialogueId = 51010077,
          GUID = "7FB2C8C2",
          SpeakNpcId = 100001,
          Subtitle = "Let's."
        },
        [51010078] = {
          ContentFR = "Tu trouves les places réservées par Violetta et t’installes, attendant que le rideau se lève.",
          DialogueId = 51010078,
          GUID = "7FB2C8EC",
          NextDialogue = 51010079,
          Subtitle = "You find the seats Violetta reserved for you and settle in, waiting for the curtain to rise."
        },
        [51010079] = {
          ContentFR = "Alors que les lumières s’éteignent peu à peu, une puissante voix de soprano s’élève derrière le rideau, emplissant la salle d’une magie indicible.",
          DialogueId = 51010079,
          GUID = "7FB2C916",
          NextDialogue = 51010080,
          Subtitle = "As the house lights dim, a powerful soprano unfurls from behind the curtain, flooding the theatre with wonder."
        },
        [51010080] = {
          ContentFR = "Le public retient son souffle. Ce silence profond te met presque mal à l’aise.",
          DialogueId = 51010080,
          GUID = "7FB2C940",
          NextDialogue = 51010081,
          Subtitle = "The audience holds its breath. The silence is so deep, it unsettles you."
        },
        [51010081] = {
          ContentFR = "Il est difficile de retenir tes exclamations face aux scènes les plus spectaculaires — tu crains qu’un soupir d’admiration n’interrompe l’enchantement.",
          DialogueId = 51010081,
          GUID = "7FB2C96A",
          NextDialogue = 51010082,
          Subtitle = "It's hard to hold back a gasp at the dazzling moments — you're almost afraid the sound of your spontaneous awe might spoil the magic."
        },
        [51010082] = {
          ContentFR = "Mais cette crainte s’évanouit vite —",
          DialogueId = 51010082,
          GUID = "7FB2C994",
          NextDialogue = 51010083,
          Subtitle = "But your worries melt away —"
        },
        [51010083] = {
          ContentFR = "Tant et si bien qu’au moment où le dernier son s’éteint, tu en oublies même d’applaudir.",
          DialogueId = 51010083,
          GUID = "7FB2C9BE",
          Subtitle = "By the time the final note falls, you're so mesmerised, you've forgotten even to applaud."
        },
        [51010084] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Giselle ! Tu me dois des explications !",
          DialogueId = 51010084,
          FacialId = {
            [1] = "700304:CM_Angry01"
          },
          GUID = "7FB2C9E8",
          NextDialogue = 51010085,
          SpeakNpcId = 700304,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Giselle — you owe me an explanation!",
          TalkActionId = {
            [1] = "700304:Angry01_Start"
          }
        },
        [51010085] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh ? Et que pourrait bien vouloir savoir le grand Fabrice Ruthford ?",
          DialogueId = 51010085,
          GUID = "7FB2CA12",
          NextDialogue = 51010086,
          SpeakNpcId = 700302,
          Subtitle = "Oh? And what could the all-knowing Lord Ruthford possibly need me to explain?",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010086] = {
          ContentFR = "Tu as signalé que Violetta était Enola, mais quand je suis arrivé en coulisses avec mes hommes... il n’y avait plus personne !",
          DialogueId = 51010086,
          GUID = "7FB2CA3C",
          NextDialogue = 51010087,
          SpeakNpcId = 700304,
          Subtitle = "You told the Escort Violetta was Enola — but when I brought my men backstage, there was no one there!"
        },
        [51010087] = {
          ContentFR = "Ah, ça. Je ne m’attendais pas à ce que tu viennes en personne. Quelle implication, vraiment.",
          DialogueId = 51010087,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2CA66",
          NextDialogue = 51010088,
          SpeakNpcId = 700302,
          Subtitle = "Ah, that. Didn't think you'd come in person. Very hands-on of you, sir."
        },
        [51010088] = {
          ContentFR = "Ne joue pas au plus malin ! Je t’ordonne de me conduire à Enola, tout de suite !",
          DialogueId = 51010088,
          GUID = "7FB2CA90",
          NextDialogue = 51010089,
          SpeakNpcId = 700304,
          Subtitle = "Don't get clever with me! Take me to Enola — now!"
        },
        [51010089] = {
          ContentFR = "Il semble que tu oublies un détail : je ne fais plus partie des Veilleurs. Et toi non plus. J’ai simplement transmis une information... en tant que simple citoyenne.",
          DialogueId = 51010089,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2CABA",
          NextDialogue = 51010090,
          SpeakNpcId = 700302,
          Subtitle = "I think you're forgetting something — I'm not with the Escort anymore. And neither are you. I just passed on a tip... as a civilian."
        },
        [51010090] = {
          ContentFR = "Je ne suis donc pas tenue d’obéir à tes ordres. Par contre... tu peux toujours engager « Giselle la Chasseuse de Phoxène ».",
          DialogueId = 51010090,
          GUID = "7FB2CAE4",
          NextDialogue = 51010091,
          SpeakNpcId = 700302,
          Subtitle = "So no, I don't take orders from you. But hey — you could always file a commission with Giselle the Phoxhunter."
        },
        [51010091] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Très bien ! Alors je vais t’engager !",
          DialogueId = 51010091,
          GUID = "7FB2CB0E",
          NextDialogue = 51010092,
          SpeakNpcId = 700304,
          Subtitle = "Tch... Fine! Then I'll file one!",
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51010092] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Parfait. Je refuse la mission.",
          DialogueId = 51010092,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2CB38",
          NextDialogue = 51010093,
          SpeakNpcId = 700302,
          Subtitle = "Great. I refuse to take the job.",
          TalkActionId = {
            [1] = "700302:Talk01_Start"
          }
        },
        [51010093] = {
          ContentFR = "Tu te moques de moi !?",
          DialogueId = 51010093,
          GUID = "7FB2CB62",
          NextDialogue = 51010094,
          SpeakNpcId = 700304,
          Subtitle = "You messing with me!?"
        },
        [51010094] = {
          ContentFR = "Disons que, puisque je suis actuellement suspectée d’avoir \"kidnappé\"la fille d’un comte, mon activité est suspendue.",
          DialogueId = 51010094,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2CB8C",
          NextDialogue = 51010095,
          SpeakNpcId = 700302,
          Subtitle = "Well, seeing as I'm currently a suspect in the kidnapping of an earl's daughter, let's just say my services are temporarily suspended."
        },
        [51010095] = {
          ContentFR = "Au fond, si tu avais accepté la solution pacifique que je proposais à l’époque, tout ceci n’aurait jamais eu lieu.",
          DialogueId = 51010095,
          GUID = "7FB2CBB6",
          NextDialogue = 51010096,
          SpeakNpcId = 700302,
          Subtitle = "Truth is, if you'd listened back then and gone with the peaceful route I proposed, none of this would've happened."
        },
        [51010096] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Je n’aurais jamais dû croire que tu pouvais retrouver Enola.",
          DialogueId = 51010096,
          GUID = "7FB2CBE0",
          NextDialogue = 51010097,
          SpeakNpcId = 700304,
          Subtitle = "You... I was a fool to ever believe you'd find Enola.",
          TalkActionId = {
            [1] = "700302:Talk01_End"
          }
        },
        [51010097] = {
          ContentFR = "Enola... ma fille... Je te retrouverai moi-même. Et toi, je ne veux plus jamais te revoir !",
          DialogueId = 51010097,
          GUID = "7FB2CC0A",
          NextDialogue = 51010098,
          SpeakNpcId = 700304,
          Subtitle = "Enola... my daughter... I'll find you myself. And you — don't ever show your face again!"
        },
        [51010098] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Avec plaisir.",
          DialogueId = 51010098,
          GUID = "7FB2CC34",
          NextDialogue = 51010099,
          Scripts = "MoveTo{ActorId{700304},TargetPoint{\"FabricePoint_20023305\"},MoveSpeed{150},Visibility{\"Hide\"}}",
          SpeakNpcId = 700302,
          Subtitle = "Gladly.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010099] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Giselle, ça va ?",
          DialogueId = 51010099,
          FinalCamera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB2CC5E",
          NextDialogue = 51010100,
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},TargetPoint{"NvzhuPoint_20023305"},MoveSpeed{150},Visibility{"Show"}},
PARA{
LookAt{LookAtDescription{"100001:n(700302)"}},
LookAt{LookAtDescription{"700302:n(100001)"}}
}
}]],
          SpeakNpcId = 100001,
          Subtitle = "You alright, Giselle?",
          ToFinalCameraBlendTime = 5
        },
        [51010100] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Très bien. Je n’aurais jamais pu lui parler ainsi quand j’étais chez les Veilleurs. Ça fait un bien fou.",
          DialogueId = 51010100,
          GUID = "7FB2CC88",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010101,
          SpeakNpcId = 700302,
          Subtitle = "Never better. Couldn't talk to him like that when I was in the Escort. Felt pretty darn good."
        },
        [51010101] = {
          ContentFR = "C’était qui, exactement ?",
          DialogueId = 51010101,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2CCB2",
          NextDialogue = 51010102,
          SpeakNpcId = 100001,
          Subtitle = "Who was that, anyway?",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010102] = {
          ContentFR = "Fabrice Ruthford. Le père de Violetta. Toujours aussi impulsif qu’il y a seize ans.",
          DialogueId = 51010102,
          GUID = "7FB2CCDC",
          NextDialogue = 51010103,
          SpeakNpcId = 700302,
          Subtitle = "Fabrice Ruthford. Violetta's father. Still as hot-headed as he was sixteen years ago.",
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51010103] = {
          ContentFR = "Et Violetta ?",
          DialogueId = 51010103,
          GUID = "7FB2CD06",
          NextDialogue = 51010104,
          SpeakNpcId = 100001,
          Subtitle = "Then where's Ms Violetta?"
        },
        [51010104] = {
          ContentFR = "Disparue. Quand Fabrice a débarqué, les coulisses étaient déjà vides.",
          DialogueId = 51010104,
          GUID = "7FB2CD30",
          NextDialogue = 51010105,
          SpeakNpcId = 700302,
          Subtitle = "Gone. Backstage was already empty by the time he barged in."
        },
        [51010105] = {
          ContentFR = "... Ah !",
          DialogueId = 51010105,
          GUID = "7FB2CD5A",
          IsBlack = 1,
          NextDialogue = 51010106,
          Scripts = [[
SEQ{
MoveTo{ActorId{700305},TargetPoint{"RosalindPoint1_20023305"},MoveSpeed{250},Visibility{"Show"}},
PARA{
LookAt{LookAtDescription{"100001:n(700305)"}},
LookAt{LookAtDescription{"700302:n(700305)"}},
TurnTo{TurnToDescription{"700305:n(100001)"}}
},
PARA{
PlayAnimation{ActorId{100001},AnimationId{"Shock_Start"},Duration{1}},
PlayAnimation{ActorId{700302},AnimationId{"Angry01_Start"},Duration{1}},
PlayAnimation{ActorId{700305},AnimationId{"Explain02_Start"},Duration{1}}
}}]],
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "...Whoops!"
        },
        [51010106] = {
          Camera = "-442.745117,136.447266,137.21167,0.000002,-3.200169,-35.40036,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "P-Pardon, je ne regardais pas devant moi ! Tu vas bien ? Je ne t’ai pas fait mal ?",
          DialogueId = 51010106,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2CD84",
          NextDialogue = 51010107,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "S—Sorry! I didn't see you! Are you okay? Did I hurt you?"
        },
        [51010107] = {
          ContentFR = "Je vais bien. Faites juste attention, d’accord ?",
          DialogueId = 51010107,
          GUID = "7FB2CDAE",
          NextDialogue = 51010108,
          SpeakNpcId = 100001,
          Subtitle = "I'm fine. Just be more careful next time, alright?",
          TalkActionId = {
            [1] = "100001:Shock_End",
            [2] = "700302:Angry01_End"
          }
        },
        [51010108] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mmm...",
          DialogueId = 51010108,
          GUID = "7FB2CDD8",
          NextDialogue = 51010109,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "Mm...",
          TalkActionId = {
            [1] = "700305:Think_Start"
          }
        },
        [51010109] = {
          Camera = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai quelque chose sur le visage ?",
          DialogueId = 51010109,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "7FB2CE02",
          NextDialogue = 51010110,
          SpeakNpcId = 100001,
          Subtitle = "What? Something on my face?",
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51010110] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non, rien du tout... Hihi... Merci pour les herbes ! ",
          DialogueId = 51010110,
          FacialId = {
            [1] = "700305:CM_Happy01"
          },
          GUID = "7FB2CE2C",
          NextDialogue = 51010111,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "Nothing! Hehe... Thanks for the herbs!",
          TalkActionId = {
            [1] = "700305:Think_End"
          }
        },
        [51010111] = {
          ContentFR = "L’heure tourne ! Tu vas être en retard !",
          DialogueId = 51010111,
          GUID = "7FB2CE56",
          NextDialogue = 51010112,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Time's ticking. Hurry or you'll miss it."
        },
        [51010112] = {
          ContentFR = "Oh non ! Je dois filer ! J’arrive, attendez-moi !",
          DialogueId = 51010112,
          GUID = "7FB2CE80",
          NextDialogue = 51010113,
          Scripts = "MoveTo{ActorId{700305},TargetPoint{\"RosalindPoint2_20023305\"},MoveSpeed{250},Visibility{\"Hide\"}}",
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "Oh no... Sorry! I gotta go! I'm coming — wait for me!"
        },
        [51010113] = {
          ContentFR = "Des herbes... ? Attendez, vous avez fait tomber quelque chose !",
          DialogueId = 51010113,
          GUID = "7FB2CEAA",
          NextDialogue = 51010114,
          SpeakNpcId = 100001,
          Subtitle = "Herbs...? Wait — you dropped something!",
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_Start"
          }
        },
        [51010114] = {
          ContentFR = "Garde-le ! C’est pour toi !",
          DialogueId = 51010114,
          GUID = "7FB2CED4",
          NextDialogue = 51010115,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          Subtitle = "You can keep it!!!",
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_End"
          }
        },
        [51010115] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Sérieusement... les jeunes, aujourd’hui, sont toujours aussi pressés.",
          DialogueId = 51010115,
          GUID = "7FB2CEFE",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010116,
          SpeakNpcId = 700302,
          Subtitle = "Seriously. Kids these days — always a whirlwind."
        },
        [51010116] = {
          ContentFR = "Pourquoi m’a-t-elle laissé ça... ?",
          DialogueId = 51010116,
          FacialId = {
            [1] = "100001:Doubt01",
            [2] = "700302:CM_Idle"
          },
          GUID = "7FB2CF28",
          NextDialogue = 51010117,
          SpeakNpcId = 100001,
          Subtitle = "Why'd she leave this...?"
        },
        [51010117] = {
          ContentFR = "Une courageuse chenille s’est changée en papillon et s’est envolée vers le ciel. Elle a disparu dans le vent... comme une violette perdue dans une mer de fleurs.",
          DialogueId = 51010117,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2CF52",
          NextDialogue = 51010118,
          Scripts = "MoveTo{ActorId{700311},TargetPoint{\"ViolettePoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "A brave butterfly has broken free of her cocoon and taken wing. She's vanished into the wind — like a violet in a sea of blooms."
        },
        [51010118] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Elle ne reviendra peut-être pas avant longtemps... alors prends ceci, un cadeau d’adieu de la part d’une amie précieuse.",
          DialogueId = 51010118,
          GUID = "7FB2CF7C",
          LookAt = {
            [1] = "100001:n(700311)",
            [2] = "700302:n(700311)"
          },
          NextDialogue = 51010119,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "She may not return for some time. So take it — a parting gift, from someone who held you dear."
        },
        [51010119] = {
          Camera = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un cadeau d’adieu... ? Il y a une broderie dessus... C’est son nom ?",
          DialogueId = 51010119,
          GUID = "7FB2CFA6",
          NextDialogue = 51010120,
          SpeakNpcId = 100001,
          Subtitle = "A parting gift...? Hmm, there's embroidery on it... Is this her name?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51010120] = {
          ContentFR = "... Putini ?",
          DialogueId = 51010120,
          GUID = "7FB2CFD0",
          NextDialogue = 51010121,
          SpeakNpcId = 100001,
          Subtitle = "...Putini?"
        },
        [51010121] = {
          ContentFR = "Si un jour tu rencontres une fille qui s’appelle Putini... j’espère que tu me reconnaîtras. Moi, je te reconnaîtrai.",
          DialogueId = 51010121,
          GUID = "7FB2CFFA",
          IsBlack = 1,
          NextDialogue = 51010122,
          Subtitle = "If one day, you meet a girl named Putini... I hope you'll recognise me. And I promise — I'll recognise you."
        },
        [51010122] = {
          ContentFR = "Je vois... Alors, Mademoiselle Caisse a pris son envol en toute sécurité. Ce qui veut dire que tu es—",
          DialogueId = 51010122,
          GUID = "7FB2D024",
          NextDialogue = 51010123,
          SpeakNpcId = 100001,
          Subtitle = "Ah, I see. So Miss Crate made it out safe and sound. Which would make you—",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51010123] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Chut... Même si je respecte ta décision de révéler la vérité, ceux qui savent garder un secret sont toujours les plus charmants.",
          DialogueId = 51010123,
          GUID = "7FB2D04E",
          NextDialogue = 51010124,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Shhh — I respect your choice to reveal the truth, but those who know how to keep a secret are always the most charming.",
          TalkActionId = {
            [1] = "700311:Disagree"
          }
        },
        [51010124] = {
          ContentFR = "Tu n’as pas peur que je revienne te chercher ?",
          DialogueId = 51010124,
          GUID = "7FB2D078",
          NextDialogue = 51010125,
          SpeakNpcId = 700302,
          Subtitle = "Aren't you afraid I'll come after you again?"
        },
        [51010125] = {
          ContentFR = "« Violetta » ne remontera plus jamais sur scène. Mais je ne suis pas prête à partir. Même si tu me dénonces à nouveau, je n’en voudrais à personne. J’ai encore un élève que je ne peux pas abandonner.",
          DialogueId = 51010125,
          GUID = "7FB2D0A2",
          NextDialogue = 51010126,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "\"Violetta\" won't return to the stage — but I'm not quite ready to leave. Even if you turn me in again, I won't blame you. There's still another student I have to protect."
        },
        [51010126] = {
          ContentFR = "...",
          DialogueId = 51010126,
          GUID = "7FB2D0CC",
          NextDialogue = 51010127,
          SpeakNpcId = 700302,
          Subtitle = "..."
        },
        [51010127] = {
          ContentFR = "Merci... pour ton silence.",
          DialogueId = 51010127,
          FacialId = {
            [1] = "700311:CM_Happy01"
          },
          GUID = "7FB2D0F6",
          NextDialogue = 51010128,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "...Thank you for your silence.",
          TalkActionId = {
            [1] = "700311:Agree"
          }
        },
        [51010128] = {
          ContentFR = "Sur ce, je vous laisse. Je vous souhaite à tous deux une très belle soirée.",
          DialogueId = 51010128,
          GUID = "7FB2D120",
          NextDialogue = 51010129,
          Scripts = "MoveTo{ActorId{700311},TargetPoint{\"RosalindPoint2_20023305\"},MoveSpeed{150},Visibility{\"Hide\"}}",
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Then I'll take my leave. Wishing you both a lovely evening."
        },
        [51010129] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah. Je le savais. Une femme comme elle n’allait jamais se laisser attraper si facilement.",
          DialogueId = 51010129,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2D14A",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010130,
          SpeakNpcId = 700302,
          Subtitle = "Hah. Knew it. A woman like her was never going to let herself get caught that easily.",
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010130] = {
          ContentFR = "On dirait que ça te réjouit presque ?",
          DialogueId = 51010130,
          GUID = "7FB2D174",
          NextDialogue = 51010131,
          SpeakNpcId = 100001,
          Subtitle = "You seem... almost pleased.",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010131] = {
          ContentFR = "Vraiment ? Pour être honnête, j’ai longtemps hésité : fallait-il détruire la vie d’une femme talentueuse pour laver l’honneur d’un mort... ?",
          DialogueId = 51010131,
          GUID = "7FB2D19E",
          NextDialogue = 51010132,
          SpeakNpcId = 700302,
          Subtitle = "Do I? To be honest, I wrestled with the choice — whether it was worth ruining a gifted woman's future just to clear a dead man's name...",
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51010132] = {
          ContentFR = "Mais j’ai fait mon choix. Têtue comme toujours.",
          DialogueId = 51010132,
          GUID = "7FB2D1C8",
          NextDialogue = 51010133,
          SpeakNpcId = 700302,
          Subtitle = "But I made my choice. Stubborn as ever, I guess."
        },
        [51010133] = {
          ContentFR = "Et si je peux aujourd’hui accepter une fin ouverte, c’est bien la preuve que j’ai changé en seize ans, non ?",
          DialogueId = 51010133,
          FacialId = {
            [1] = "700302:CM_Sad01"
          },
          GUID = "7FB2D1F2",
          NextDialogue = 51010134,
          SpeakNpcId = 700302,
          Subtitle = "Still... maybe being at peace with an open ending means I've grown."
        },
        [51010134] = {
          ContentFR = "Si j’avais compris cela il y a seize ans... peut-être que personne n’aurait eu à mourir.",
          DialogueId = 51010134,
          GUID = "7FB2D21C",
          NextDialogue = 51010135,
          SpeakNpcId = 700302,
          Subtitle = "If I'd understood that sixteen years ago... maybe no one would've had to die."
        },
        [51010135] = {
          ContentFR = "Ce n’était pas ta faute, Giselle.",
          DialogueId = 51010135,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2D246",
          NextDialogue = 51010136,
          SpeakNpcId = 100001,
          Subtitle = "It wasn't your fault, Giselle.",
          TalkActionId = {
            [1] = "100001:Disagree"
          }
        },
        [51010136] = {
          ContentFR = "Je sais. Je ne suis pas triste. Je me demande juste ce que je vais faire maintenant que « Giselle la Chasseuse de Phoxène » a pris sa retraite.",
          DialogueId = 51010136,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2D270",
          NextDialogue = 51010137,
          SpeakNpcId = 700302,
          Subtitle = "I know. I'm not sad. Just... wondering what comes next, now that \"Giselle the Phoxhunter\" is off the case."
        },
        [51010137] = {
          ContentFR = "J’abandonne l’idée de devenir comédienne. Après avoir vu Violetta sur scène, difficile de me comparer...",
          DialogueId = 51010137,
          GUID = "7FB2D29A",
          NextOptions = {
            [1] = 510100471,
            [2] = 510100472
          },
          SpeakNpcId = 700302,
          Subtitle = "Acting's off the table. After watching Violetta perform, I realised the stage really isn't for me..."
        },
        [51010138] = {
          ContentFR = "Oui... parce que ça paye bien.",
          DialogueId = 51010138,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2D2C4",
          NextDialogue = 51010140,
          SpeakNpcId = 700302,
          Subtitle = "Well, I thought acting paid well."
        },
        [51010139] = {
          ContentFR = "D’accord, d’accord... pas la peine d’en rajouter, Détective {nickname}.",
          DialogueId = 51010139,
          GUID = "7FB2D2EE",
          NextDialogue = 51010140,
          SpeakNpcId = 700302,
          Subtitle = "Alright, alright — no need to rub it in, Detective ."
        },
        [51010140] = {
          ContentFR = "Et maintenant ? Tu as un nouveau plan ?",
          DialogueId = 51010140,
          GUID = "7FB2D318",
          NextDialogue = 51010141,
          SpeakNpcId = 100001,
          Subtitle = "So, what now? Got a new plan?",
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010141] = {
          ContentFR = "Hmm... pas encore. Mais j’ai du temps. J’y réfléchirai tranquillement.",
          DialogueId = 51010141,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2D342",
          NextDialogue = 51010142,
          SpeakNpcId = 700302,
          Subtitle = "Hmm... not yet. But there's time. I'll figure something out."
        },
        [51010142] = {
          ContentFR = "Après tout, la scène est vaste. Je finirai bien par trouver mon rôle.",
          DialogueId = 51010142,
          GUID = "7FB2D36C",
          SpeakNpcId = 700302,
          Subtitle = "It's a big stage. I'll find my part eventually."
        },
        [51010143] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Attends !",
          DialogueId = 51010143,
          FacialId = {
            [1] = "700300:CM_Smile01",
            [2] = "700302:CM_Angry01",
            [3] = "100001:Angry01"
          },
          GUID = "7FB2AA92",
          NextDialogue = 51009894,
          SpeakNpcId = 100001,
          Subtitle = "Wait — stop!",
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_Start"
          }
        },
        [51010201] = {
          ContentFR = "♪ Le feu de la forge embrase l’aube, érigeant une forteresse de neige et de fer... ♪",
          DialogueId = 51010201,
          GUID = "7FB2DD1A",
          SpeakNpcId = 700342,
          Subtitle = "♪ Furnace-fire burns the dawn, tipping out the fortress of iron 'n' snow...",
          VoiceName = "voice/$Locale$/env/700342/7FB2DD1A"
        },
        [51010202] = {
          ContentFR = "♪ Le feu de la forge embrase l’aube, érigeant une forteresse de neige et de fer...\nLes rouages entonnent leur chant, engloutissant l’étoile du matin, célébrant l’âge glorieux du Nord... ♪",
          DialogueId = 51010202,
          GUID = "7FB2DD44",
          NextDialogue = 51010203,
          SpeakNpcId = 700342,
          Subtitle = "♪ Furnace-fire burns the dawn, tipping out the fortress of iron 'n' snow.\nGears sing in hymns, devour the stars, hailing the great age of ice in north—",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DD44"
        },
        [51010203] = {
          ContentFR = "Hmm ? Tu m’as appelé... ?",
          DialogueId = 51010203,
          GUID = "7FB2DD6E",
          LookAt = {
            [1] = "700342:n(0)"
          },
          NextOptions = {
            [1] = 510102031,
            [2] = 510102032
          },
          SpeakNpcId = 700342,
          Subtitle = "Hmm? Were you talking to me...?",
          TalkActionId = {
            [1] = "700342:Lilikou_Story_Playlyre_End"
          },
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DD6E"
        },
        [51010204] = {
          ContentFR = "Merci, {性别:voyageur inconnu|voyageuse inconnue} ! Mais cette chanson n’est pas encore achevée... Peut-être pourrais-tu m’aider à en trouver la fin ?",
          DialogueId = 51010204,
          GUID = "7FB2DD98",
          NextDialogue = 51010206,
          SpeakNpcId = 700342,
          Subtitle = "Thank you, kind traveller! But the song's not quite finished yet... Perhaps we could find its ending together?",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DD98"
        },
        [51010205] = {
          ContentFR = "Oh... pardon de t’avoir dérangé ! Mais j’ai demandé au soldat là-bas : aucune loi n’interdit à un ménestrel de chanter sur cette place.",
          DialogueId = 51010205,
          GUID = "7FB2DDC2",
          NextDialogue = 51010206,
          SpeakNpcId = 700342,
          Subtitle = "Oh — apologies if I disturbed you! Though I did check with the guard over there, and he said there's no law against bards singing in the square.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DDC2"
        },
        [51010206] = {
          ContentFR = "Hmm... quelle devrait être la dernière ligne... ?",
          DialogueId = 51010206,
          GUID = "7FB2DDEC",
          NextDialogue = 51010207,
          SpeakNpcId = 700342,
          Subtitle = "Now, how should the final line go...?",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DDEC"
        },
        [51010207] = {
          ContentFR = "Je pense qu’elle devrait parler du vent... Chaque endroit a son propre souffle...",
          DialogueId = 51010207,
          GUID = "7FB2DE16",
          NextDialogue = 51010208,
          SpeakNpcId = 700342,
          Subtitle = "I think it should be about the wind. Every place has its own wind...",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE16"
        },
        [51010208] = {
          ContentFR = "À Élysium, le vent sent l’encens fondu dans les prières du soir. À Luca, il porte l’odeur de l’essence de pin des ateliers de peinture et du caramel des cafés. À Aethyrie, il se mêle à l’encre et à la menthe sauvage...",
          DialogueId = 51010208,
          GUID = "7FB2DE40",
          NextDialogue = 51010209,
          SpeakNpcId = 700342,
          Subtitle = "The wind in Elysium smells of frankincense, melting into evening prayers. In Luca, it's turpentine from painter's lofts, and caramel wafting from cafés. In Aethyrie, the scent is ink laced with wild mint...",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE40"
        },
        [51010209] = {
          ContentFR = "Et ici, en Hyperborea... à quoi ressemble le vent ?",
          DialogueId = 51010209,
          GUID = "7FB2DE6A",
          NextOptions = {
            [1] = 510102091,
            [2] = 510102092,
            [3] = 510102093
          },
          SpeakNpcId = 700342,
          Subtitle = "So — what does the wind smell like, here in Hyperborea?",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE6A"
        },
        [51010210] = {
          ContentFR = "Hmm... tu n’as pas tort. Cette cité est née de l’acier — une forêt forgée plutôt que semée.",
          DialogueId = 51010210,
          GUID = "7FB2DE94",
          NextDialogue = 51010211,
          SpeakNpcId = 700342,
          Subtitle = "Hmm... you may be right. This city was born of steel — a forest forged, not grown.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DE94"
        },
        [51010211] = {
          ContentFR = "Le vent est glacial, oui... mais il transporte le grondement des engrenages et le souffle brûlant des forges. Et lorsque tu tends la main... il te brûle la peau.",
          DialogueId = 51010211,
          GUID = "7FB2DEBE",
          NextDialogue = 51010212,
          SpeakNpcId = 700342,
          Subtitle = "The wind may sting with cold, but it hums with gears and hisses with flame. And when you touch it... it burns.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DEBE"
        },
        [51010212] = {
          ContentFR = "Comme le canon d’un fusil de soldat : brûlant, même quand le visage qui le tient reste de pierre.",
          DialogueId = 51010212,
          GUID = "7FB2DEE8",
          NextDialogue = 51010220,
          SpeakNpcId = 700342,
          Subtitle = "Like the barrel of a soldier's rifle — even when their face is cold as stone.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DEE8"
        },
        [51010213] = {
          ContentFR = "Oui ! On dit que les trois quarts de cette cité sont faits de neige. Les habitants racontent qu’à Givrelac, il neige presque toute l’année — la fonte ne dure que trois mois.",
          DialogueId = 51010213,
          GUID = "7FB2DF12",
          NextDialogue = 51010214,
          SpeakNpcId = 700342,
          Subtitle = "So true! They say three-quarters of this city is made of snow. Locals told me it's always snowing in Icelake — only thaws three months a year.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF12"
        },
        [51010214] = {
          ContentFR = "Et le vent et la neige sont inséparables. C’est le duo éternel que la nature nous offre.",
          DialogueId = 51010214,
          GUID = "7FB2DF3C",
          NextDialogue = 51010220,
          SpeakNpcId = 700342,
          Subtitle = "And snow always has its partner: the wind. They dance together — nature's perfect duet!",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF3C"
        },
        [51010215] = {
          ContentFR = "Des larmes... Voilà une image que je n’ai pas encore employée...",
          DialogueId = 51010215,
          GUID = "7FB2DF66",
          NextDialogue = 51010216,
          SpeakNpcId = 700342,
          Subtitle = "\"Tears?\" Hmm... That's a line I haven't used yet...",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF66"
        },
        [51010216] = {
          ContentFR = "...",
          DialogueId = 51010216,
          GUID = "7FB2DF90",
          NextDialogue = 51010217,
          SpeakNpcId = 700342,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DF90"
        },
        [51010217] = {
          ContentFR = "Le premier jour où je suis venu sur cette place, j’ai vu un bouffon aveugle donner un spectacle. Il disait que ses yeux avaient été brûlés par la vapeur d’une chaudière, des années plus tôt. Un enfant riait à s’en rouler par terre, et son serviteur a jeté une pièce d’argent.",
          DialogueId = 51010217,
          GUID = "7FB2DFBA",
          NextDialogue = 51010218,
          SpeakNpcId = 700342,
          Subtitle = "On my first day in this square, I saw a blind jester performing. He said his eyes were burned by boiler fumes years ago. A child laughed wildly at his tricks, and the servant beside him tossed down a silver coin.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DFBA"
        },
        [51010218] = {
          ContentFR = "Sur ce même banc où je suis assis, un ancien soldat hurlait en essayant de vendre sa dernière médaille. Sur le banc voisin, une mère amaigrie tirait quelques maigres gouttes de lait de son corps épuisé pour nourrir son enfant gravement malade.",
          DialogueId = 51010218,
          GUID = "7FB2DFE4",
          NextDialogue = 51010219,
          SpeakNpcId = 700342,
          Subtitle = "On this very bench I'm sitting on now, a retired soldier cried out, trying to sell his last medal. Beside him, a frail mother coaxed out the last of her milk to feed her sick child.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2DFE4"
        },
        [51010219] = {
          ContentFR = "... Ce jour-là, le vent qui traversait la place portait avec lui le goût des larmes.",
          DialogueId = 51010219,
          GUID = "7FB2E00E",
          NextDialogue = 51010220,
          SpeakNpcId = 700342,
          Subtitle = "That day, the wind drifting through this square... it felt like it was weeping too.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2E00E"
        },
        [51010220] = {
          ContentFR = "Merci pour ton inspiration, {性别:monsieur|mademoiselle}... une rose éclose au cœur de la toundra. Grâce à toi, je crois que ma chanson touche enfin à sa fin.",
          DialogueId = 51010220,
          GUID = "7FB2E038",
          SpeakNpcId = 700342,
          Subtitle = "Thank you, dear {性别:sir|miss} — you've given me the line I needed. You're a rose blooming on the tundra. I think I can finally finish this song.",
          TalkActionId = {
            [1] = "700342:Lilikou_Story_Playlyre_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2E038"
        },
        [51010221] = {
          ContentFR = "Merci, {性别:monsieur|mademoiselle}. Grâce à toi, j’ai trouvé la dernière strophe. Tu es comme une rose qui fleurit sur la toundra glacée.",
          DialogueId = 51010221,
          GUID = "7FB2E062",
          SpeakNpcId = 700342,
          Subtitle = "Thank you, dear {性别:sir|miss}, for giving me the line I needed. You're a rose blooming on the tundra.",
          VoiceName = "voice/$Locale$/story/1002/510102/7FB2E062"
        },
        [51010301] = {
          ContentFR = "Les anciens mythes des Charons...",
          DialogueId = 51010301,
          GUID = "7FB2ED82",
          SpeakNpcId = 700342,
          Subtitle = "The Misty Sea myths of the Charon...",
          VoiceName = "voice/$Locale$/env/700342/7FB2ED82"
        },
        [51010302] = {
          ContentFR = "... celui-ci est particulièrement fascinant : il raconte que, dans la Mer du Silence, toutes choses sont prises dans un cycle infini de vie et de mort. Qu’en penses-tu, Idy—",
          DialogueId = 51010302,
          GUID = "7FB2EDAC",
          NextDialogue = 51010303,
          SpeakNpcId = 700342,
          Subtitle = "This one's the most fascinating — it says everything in the Misty Sea is caught in an endless cycle of life and death. What do you think, Idy—",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EDAC"
        },
        [51010303] = {
          ContentFR = "Ah, c’est toi ! Je me souviens de toi — nous avons parlé ici même, la dernière fois.",
          DialogueId = 51010303,
          GUID = "7FB2EDD6",
          NextDialogue = 51010304,
          SpeakNpcId = 700342,
          Subtitle = "Ah! It's you! I remember — we spoke right here, didn't we?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EDD6"
        },
        [51010304] = {
          ContentFR = "As-tu vu mon amie ? Une jeune fille aux cheveux rouges, insaisissable comme le vent... Elle était là il y a un instant.",
          DialogueId = 51010304,
          GUID = "7FB2EE00",
          NextOptions = {
            [1] = 51010305
          },
          SpeakNpcId = 700342,
          Subtitle = "Have you seen my friend? Red hair, always drifting in and out like the wind... She was just here a moment ago.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE00"
        },
        [51010305] = {
          ContentFR = "<I>Non, je n’ai vu personne comme ça.</>",
          DialogueId = 51010305,
          GUID = "7FB2EE2A",
          NextDialogue = 51010306,
          Subtitle = "I haven't seen anyone like that around."
        },
        [51010306] = {
          ContentFR = "Merci ! Je vais l’attendre encore un peu. Elle a l’habitude de disparaître sans prévenir... pour réapparaître tout aussi soudainement.",
          DialogueId = 51010306,
          GUID = "7FB2EE54",
          NextDialogue = 51010307,
          SpeakNpcId = 700342,
          Subtitle = "Thanks anyway. I'll wait a bit — she has a habit of vanishing... then turning up out of nowhere.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE54"
        },
        [51010307] = {
          ContentFR = "Ces derniers jours, nous avons collecté de nombreux mythes Charons. Je suis surpris de voir à quel point les gens ici en parlent librement.",
          DialogueId = 51010307,
          GUID = "7FB2EE7E",
          NextDialogue = 51010308,
          SpeakNpcId = 700342,
          Subtitle = "We've been gathering Charon myths these past few days. It's surprising how openly people speak of them here.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EE7E"
        },
        [51010308] = {
          ContentFR = "Dans mon pays, à Élysium, les Charons sont bien plus vénérés : ils siègent dans des temples élevés, dialoguent avec les dieux et détiennent l’autorité. Mais là-bas, évoquer les anciens mythes est dangereux.",
          DialogueId = 51010308,
          GUID = "7FB2EEA8",
          NextDialogue = 51010309,
          SpeakNpcId = 700342,
          Subtitle = "Charons are shunned here in Hyperborea, but back in my homeland, Elysium, they're venerated as divine messengers enthroned in sacred halls. But to speak those old myths aloud... is dangerous there.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EEA8"
        },
        [51010309] = {
          ContentFR = "Dis-moi, connais-tu ces mythes Charons ?",
          DialogueId = 51010309,
          GUID = "7FB2EED2",
          NextOptions = {
            [1] = 51010310,
            [2] = 51010311
          },
          SpeakNpcId = 700342,
          Subtitle = "Do you know much about the myths of the Charon?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EED2"
        },
        [51010310] = {
          ContentFR = "<I>Un peu.</>",
          DialogueId = 51010310,
          GUID = "7FB2EEFC",
          NextDialogue = 51010312,
          Subtitle = "A little."
        },
        [51010311] = {
          ContentFR = "<I>Pas vraiment.</>",
          DialogueId = 51010311,
          GUID = "7FB2EF26",
          NextDialogue = 51010312,
          Subtitle = "Not really."
        },
        [51010312] = {
          ContentFR = "Charon signifie « ceux qui viennent de la Mer du Silence »...",
          DialogueId = 51010312,
          GUID = "7FB2EF50",
          NextDialogue = 51010313,
          SpeakNpcId = 700342,
          Subtitle = "\"Charon\" means \"those who came from the Misty Sea\"...",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EF50"
        },
        [51010313] = {
          ContentFR = "La mer est l’origine de tout. De ses profondeurs a surgi l’Arbre Sacré. Son feuillage s’est étendu jusqu’aux cieux, et chacune de ses branches devint un Arbre Céleste. Ses racines, elles, ont donné naissance au monde.",
          DialogueId = 51010313,
          GUID = "7FB2EF7A",
          NextDialogue = 51010314,
          SpeakNpcId = 700342,
          Subtitle = "The Misty Sea is the origin of all things. From it rose the Sacred Tree. Its canopy stretched across the heavens — and each of its branches became a Heaventree. Its roots, meanwhile, cradled the world.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EF7A"
        },
        [51010314] = {
          ContentFR = "L’Arbre Sacré fleurit de fleurs blanches, et de ces fleurs naquit la Mère — Embla. Elle créa toutes choses, et de son essence naquit le Père — Ask. Ensemble, ils engendrèrent les ancêtres des Charons.",
          DialogueId = 51010314,
          GUID = "7FB2EFA4",
          NextDialogue = 51010315,
          SpeakNpcId = 700342,
          Subtitle = "The tree bloomed with white flowers, and from them stepped forth Mother Embla. She created all things — and from her came Father Ask. Together, they gave birth to the first of the Charons.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFA4"
        },
        [51010315] = {
          ContentFR = "Mais Ask, porteur du <W>Pouvoir de la Mort</>, devint l’incarnation du désastre, et finit par précipiter la fin du monde — l’apocalypse que l’on nomme Ragnarök.",
          DialogueId = 51010315,
          GUID = "7FB2EFCE",
          NextDialogue = 51010316,
          SpeakNpcId = 700342,
          Subtitle = "Yet Ask, bearer of the power of death, became a vessel of calamity. In the end, it was he who brought ruin to the world — the cataclysm we call Ragnarok.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFCE"
        },
        [51010316] = {
          ContentFR = "Dans cette heure sombre, Embla, gardienne du <H>Pouvoir de la Vie</>, protégea ses enfants. Son âme se fragmenta et se dispersa dans la mer... jusqu’à revenir à la Mer du Silence.",
          DialogueId = 51010316,
          GUID = "7FB2EFF8",
          NextDialogue = 51010317,
          SpeakNpcId = 700342,
          Subtitle = "In that final hour, Mother Embla — keeper of the power of life — gathered her children and sheltered them. Her soul scattered into the sea... and at last, returned to the Misty Sea.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2EFF8"
        },
        [51010317] = {
          ContentFR = "Le corps d’Ask devint la terre, et ses bras levés, les montagnes, tendues vers des dieux qui ne reviendraient jamais.",
          DialogueId = 51010317,
          GUID = "7FB2F022",
          NextOptions = {
            [1] = 51010318
          },
          SpeakNpcId = 700342,
          Subtitle = "Ask's body became the land and his arms, upraised, became the mountains, still reaching for the gods... who no longer come.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F022"
        },
        [51010318] = {
          ContentFR = "<I>C’est... une histoire plutôt triste.</>",
          DialogueId = 51010318,
          GUID = "7FB2F04C",
          NextDialogue = 51010319,
          Subtitle = "That's... kind of a sad story."
        },
        [51010319] = {
          ContentFR = "Oui, mais il existe une autre version fascinante.",
          DialogueId = 51010319,
          GUID = "7FB2F076",
          NextDialogue = 51010320,
          SpeakNpcId = 700342,
          Subtitle = "Mm... but there's another thread in the myths that caught my ear.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F076"
        },
        [51010320] = {
          ContentFR = "Elle raconte qu’Ask et Embla ont été réincarnés dans le nouveau monde, sous de nouvelles formes.",
          DialogueId = 51010320,
          GUID = "7FB2F0A0",
          NextDialogue = 51010321,
          SpeakNpcId = 700342,
          Subtitle = "It says Ask and Embla were reborn after the world's end — in new forms, walking again in a new world.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0A0"
        },
        [51010321] = {
          ContentFR = "Et que leurs nouveaux avatars provoqueront un autre crépuscule — suivi d’une autre aube.",
          DialogueId = 51010321,
          GUID = "7FB2F0CA",
          NextDialogue = 51010322,
          SpeakNpcId = 700342,
          Subtitle = "And that their reborn selves would one day bring about another ending — and another beginning.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0CA"
        },
        [51010322] = {
          ContentFR = "Ainsi tourne le monde, dans un cycle sans fin. Vie et mort, encore et encore.",
          DialogueId = 51010322,
          GUID = "7FB2F0F4",
          NextOptions = {
            [1] = 51010323
          },
          SpeakNpcId = 700342,
          Subtitle = "Thus the world turns, ever in circles. Life and death, again and again.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F0F4"
        },
        [51010323] = {
          ContentFR = "<I>On dirait que même les anciens n’aimaient pas les fins tragiques.</>",
          DialogueId = 51010323,
          GUID = "7FB2F11E",
          NextDialogue = 51010324,
          Subtitle = "Seems that the ancients didn't like tragic endings either."
        },
        [51010324] = {
          ContentFR = "Et pourtant… je me demande : pourquoi l’auteur croyait-il si fermement à leur renaissance ? Ou plutôt... qu’est-ce qui définit l’essence d’Ask et d’Embla ?",
          DialogueId = 51010324,
          GUID = "7FB2F148",
          NextDialogue = 51010325,
          SpeakNpcId = 700342,
          Subtitle = "But... what I keep wondering is — why was the storyteller so sure that the gods were reborn? Or rather... what makes Embla and Ask who they are?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F148"
        },
        [51010325] = {
          ContentFR = "Leur corps ? Leur âme ? ... Ou tout autre chose ?",
          DialogueId = 51010325,
          GUID = "7FB2F172",
          NextDialogue = 51010326,
          SpeakNpcId = 700342,
          Subtitle = "Is it their bodies? Their souls? ...Or something else entirely?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F172"
        },
        [51010326] = {
          ContentFR = "Imaginons... juste pour un instant... qu’un grand mage transforme la terre sous nos pieds pour lui redonner la forme d’Ask. Lequel serait alors le vrai Père ? Celui fait de l’ancien sol, ou celui qui porte son âme ?",
          DialogueId = 51010326,
          GUID = "7FB2F19C",
          NextOptions = {
            [1] = 510103261,
            [2] = 510103262,
            [3] = 510103263,
            [4] = 510103264
          },
          SpeakNpcId = 700342,
          Subtitle = "Imagine this — just for a moment — that a great mage turned the land beneath our feet back into Ask's original form... Then who would truly be Father Ask? The one made of ancient earth? Or the one who bears his soul reborn?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F19C"
        },
        [51010327] = {
          ContentFR = "Ah... je vois. Merci, ta réponse m’apporte une nouvelle perspective.",
          DialogueId = 51010327,
          GUID = "7FB2F1C6",
          NextDialogue = 51010329,
          SpeakNpcId = 700342,
          Subtitle = "Ah... so that's how you see it. Thank you. You've given me something new to ponder.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F1C6"
        },
        [51010328] = {
          ContentFR = "La plupart des créations commencent par une question absurde, tu ne crois pas ?",
          DialogueId = 51010328,
          GUID = "7FB2F1F0",
          NextDialogue = 51010329,
          SpeakNpcId = 700342,
          Subtitle = "Most songs begin with a question that sounds pointless, don't they?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F1F0"
        },
        [51010329] = {
          ContentFR = "Merci, {性别:monsieur|mademoiselle}, flamme vive sur une chandelle glacée. J’aime ces mythes... et je crois que j’y ai enfin trouvé ma chanson.",
          DialogueId = 51010329,
          GUID = "7FB2F21A",
          SpeakNpcId = 700342,
          Subtitle = "Thank you for your time, dear {性别:sir|miss}. You're a spark on a cold wick. I've come to love these myths. I think... I've found a song inside them, at last.",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F21A"
        },
        [51010330] = {
          ContentFR = "Qu’est-ce qui fait de nous ce que nous sommes ?",
          DialogueId = 51010330,
          GUID = "7FB2F244",
          SpeakNpcId = 700342,
          Subtitle = "What made us who we are?",
          VoiceName = "voice/$Locale$/story/1002/510103/7FB2F244"
        },
        [51010401] = {
          ContentFR = "Le Théâtre Galea...",
          DialogueId = 51010401,
          GUID = "7FB2FDEA",
          SpeakNpcId = 700342,
          Subtitle = "The Galea Theatre...",
          VoiceName = "voice/$Locale$/env/700342/7FB2FDEA"
        },
        [51010402] = {
          ContentFR = "Nous revoilà réunis, {性别:monsieur|mademoiselle}, tel un grenat posé sur le sable blanc. Tu sembles apprécier cet endroit... moi aussi.",
          DialogueId = 51010402,
          GUID = "7FB2FE14",
          NextDialogue = 51010403,
          SpeakNpcId = 700342,
          Subtitle = "We meet again, dear {性别:sir|miss}. You're a garnet on white sand. You must like it here. I do too.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE14"
        },
        [51010403] = {
          ContentFR = "As-tu déjà mis les pieds à l’intérieur du Théâtre Galea ?",
          DialogueId = 51010403,
          GUID = "7FB2FE3E",
          NextOptions = {
            [1] = 510104031,
            [2] = 510104032,
            [3] = 510104033
          },
          SpeakNpcId = 700342,
          Subtitle = "Have you ever been inside the Galea Theatre?",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE3E"
        },
        [51010404] = {
          ContentFR = "Oh ! Quelle chance... Tu dois être quelqu’un d’aisé.",
          DialogueId = 51010404,
          GUID = "7FB2FE68",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          Subtitle = "Oh! How enviable... You must be well-off.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE68"
        },
        [51010405] = {
          ContentFR = "Ah... alors je ne suis pas le seul à être tenu à l’écart de ses portes.",
          DialogueId = 51010405,
          GUID = "7FB2FE92",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          Subtitle = "Ah... then I'm not the only one kept outside the gates.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FE92"
        },
        [51010406] = {
          ContentFR = "Combattu la Légion ? Incroyable... Tu dois avoir des histoires plein les poches, comme autant de partitions oubliées.",
          DialogueId = 51010406,
          GUID = "7FB2FEBC",
          NextDialogue = 51010407,
          SpeakNpcId = 700342,
          Subtitle = "You fought the Legion? Remarkable... You must have stories tucked away like old sheet music.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FEBC"
        },
        [51010407] = {
          ContentFR = "J’ai visité toutes sortes d’opéras à Luca, mais ici, à Hyperborea, les théâtres m’en ont toujours refusé l’entrée.",
          DialogueId = 51010407,
          GUID = "7FB2FEE6",
          NextDialogue = 51010408,
          SpeakNpcId = 700342,
          Subtitle = "I've visited opera houses across Luca, but here in Hyperborea... they always turn me away.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FEE6"
        },
        [51010408] = {
          ContentFR = "Je savais que les Charons n’avaient pas la vie facile dans cette cité, mais je n’imaginais pas que les taxes de surveillance des lieux publics puissent être aussi exorbitants...",
          DialogueId = 51010408,
          GUID = "7FB2FF10",
          NextDialogue = 51010409,
          SpeakNpcId = 700342,
          Subtitle = "I knew Charons had it rough in this city, but I never imagined the supervision levies for public spaces would be so steep...",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF10"
        },
        [51010409] = {
          ContentFR = "J’ai eu la chance d’arriver à temps pour la Fête de la Chandelle d’Argent, ce jour unique où même les plus pauvres peuvent franchir les portes du théâtre sans payer. Malheureusement... il y a eu une fusillade à l’intérieur. Quelle tragédie.",
          DialogueId = 51010409,
          GUID = "7FB2FF3A",
          NextDialogue = 51010410,
          SpeakNpcId = 700342,
          Subtitle = "Still — I was lucky to arrive just in time for the Silvercandle Carnival. It's the city's one day when even paupers like me can step through the theatre doors for free. Tragic, though... to hear there'd been a shootout inside. Absolutely dreadful.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF3A"
        },
        [51010410] = {
          ContentFR = "Au moins, j’ai réussi à rassembler beaucoup de partitions ! Les prix des librairies étaient raisonnables, certains ont même accepté d’échanger des pages contre une chanson, et... une personne mystérieuse m’a appris un air très célèbre.",
          DialogueId = 51010410,
          GUID = "7FB2FF64",
          NextOptions = {
            [1] = 510104101
          },
          SpeakNpcId = 700342,
          Subtitle = "Even so, I gathered plenty of sheet music! The bookshop prices were fair, and a few kind souls let me trade verses for pages. And one mysterious person... even taught me a famous aria.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF64"
        },
        [51010411] = {
          ContentFR = "Une nuit, adossé à un mur sous la lumière de la lune, je fredonnais un air appris dans une vieille partition. La mélodie n’était pas compliquée, facile à mémoriser.",
          DialogueId = 51010411,
          GUID = "7FB2FF8E",
          NextDialogue = 51010412,
          SpeakNpcId = 700342,
          Subtitle = "A few nights ago, I was leaning against a wall under the moonlight, humming a melody I'd picked up from a second-hand score. It was simple enough — soft, easy to carry on the wind.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FF8E"
        }
      }
    end
  },
  {
    MinKey = 51010412,
    MaxKey = 51011314,
    Loader = function()
      return {
        [51010412] = {
          ContentFR = "Mais lorsque j’ai terminé, j’ai entendu frapper de l’autre côté du mur... Des coups réguliers, délibérés. Tu sais, les ménestrels ont l’oreille fine : ce n’était pas du hasard.",
          DialogueId = 51010412,
          GUID = "7FB2FFB8",
          NextDialogue = 51010413,
          SpeakNpcId = 700342,
          Subtitle = "When I finished, I heard knocking — on the other side of the wall. Rhythmic. Intentional. Bards are always sensitive to rhythm... I knew it wasn't random.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FFB8"
        },
        [51010413] = {
          ContentFR = "J’ai analysé ce rythme. C’était un ancien code, transmis depuis longtemps — deux types de frappes suffisaient à faire passer un message.",
          DialogueId = 51010413,
          GUID = "7FB2FFE2",
          NextDialogue = 51010414,
          SpeakNpcId = 700342,
          Subtitle = "It was code — old knock code, passed down long ago. Just two kinds of taps, but enough to send meaning through stone.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB2FFE2"
        },
        [51010414] = {
          ContentFR = "La personne derrière le mur m’a dit que je m’étais trompé. C’était un air d’opéra très célèbre ici... mais, n’ayant pas lu le livret, j’étais passé à côté de l’émotion que la chanson voulait transmettre.",
          DialogueId = 51010414,
          GUID = "7FB3000C",
          NextDialogue = 51010415,
          SpeakNpcId = 700342,
          Subtitle = "They told me I'd sung it wrong. It was a well-known operatic piece here — but I hadn't read the libretto, so I'd missed its feeling and heart.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB3000C"
        },
        [51010415] = {
          ContentFR = "Cette personne, pour une raison que j’ignore, ne pouvait ni parler ni chanter. Mais elle a utilisé ce langage pour m’apprendre à chanter correctement.",
          DialogueId = 51010415,
          GUID = "7FB30036",
          NextDialogue = 51010416,
          SpeakNpcId = 700342,
          Subtitle = "They couldn't speak or sing. I don't know why. But they used that rhythm to teach me how to sing it true.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30036"
        },
        [51010416] = {
          ContentFR = "Et quand enfin j’ai maîtrisé l’air, je me suis précipité de l’autre côté pour la remercier... Elle avait déjà disparu.",
          DialogueId = 51010416,
          GUID = "7FB30060",
          NextOptions = {
            [1] = 510104161,
            [2] = 510104162
          },
          SpeakNpcId = 700342,
          Subtitle = "And when I had finally mastered the song, I ran to the other side of the wall to thank them... Only to find they were already gone.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30060"
        },
        [51010417] = {
          ContentFR = "Oh, quelle coïncidence !",
          DialogueId = 51010417,
          GUID = "7FB3008A",
          NextDialogue = 51010418,
          SpeakNpcId = 700342,
          Subtitle = "Oh, how lucky!",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB3008A"
        },
        [51010418] = {
          ContentFR = "Si tu peux, remercie-la de ma part — et transmets-lui tous mes vœux. J’ignore pourquoi elle ne peut pas chanter, mais je suis certain qu’elle aime la musique... profondément.",
          DialogueId = 51010418,
          GUID = "7FB300B4",
          NextDialogue = 51010419,
          SpeakNpcId = 700342,
          Subtitle = "If it's not too much trouble... would you thank them for me? And send them my best wishes, too. I don't know why they couldn't sing — but I'm sure they loved music, deeply.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB300B4"
        },
        [51010419] = {
          ContentFR = "... D’accord, je le ferai.",
          DialogueId = 51010419,
          GUID = "7FB300DE",
          NextDialogue = 51010421,
          SpeakNpcId = 100001,
          Subtitle = "...Sure, I will.",
          TalkActionId = {
            [1] = "0:Agree"
          },
          VoiceName = "voice/$Locale$/story/1002/510104/7FB300DE"
        },
        [51010420] = {
          ContentFR = "C’est vrai... et d’histoires étranges, aussi.",
          DialogueId = 51010420,
          GUID = "7FB30108",
          NextDialogue = 51010421,
          SpeakNpcId = 700342,
          Subtitle = "That it is... and full of kooky tales, too.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30108"
        },
        [51010421] = {
          ContentFR = "D’ailleurs, l’opéra d’ici est très différent de celui de Luca...",
          DialogueId = 51010421,
          GUID = "7FB30132",
          NextDialogue = 51010422,
          SpeakNpcId = 700342,
          Subtitle = "The opera here is quite unlike Luca's.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30132"
        },
        [51010422] = {
          ContentFR = "L’opéra de Luca est un feu d’artifice. Celui d’Aethyrie est le vent.",
          DialogueId = 51010422,
          GUID = "7FB3015C",
          NextDialogue = 51010423,
          SpeakNpcId = 700342,
          Subtitle = "Luca's opera is fire. Aethyrie's — wind.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB3015C"
        },
        [51010423] = {
          ContentFR = "Mais ici... l’opéra est la terre. Large, lourde, empreinte de douleur...",
          DialogueId = 51010423,
          GUID = "7FB30186",
          NextDialogue = 51010424,
          SpeakNpcId = 700342,
          Subtitle = "But Hyperborea... its opera is the earth itself. Heavy, vast, and full of pain...",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30186"
        },
        [51010424] = {
          ContentFR = "Mon amie et moi quitterons bientôt cet endroit. Mais avant cela... je veux écrire une dernière chanson pour cette cité.",
          DialogueId = 51010424,
          GUID = "7FB301B0",
          SpeakNpcId = 700342,
          Subtitle = "My friend and I will be leaving soon. But before that... I want to write one last song for this place.",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB301B0"
        },
        [51010425] = {
          ContentFR = "♪ La neige blanche est son eau matricielle, la ligne de l’aube et du crépuscule son cordon ombilical... ♪",
          DialogueId = 51010425,
          GUID = "7FB301DA",
          SpeakNpcId = 700342,
          Subtitle = "♪ White snow is her birth-flow, and twilight her warm cord aglow...",
          VoiceName = "voice/$Locale$/env/700342/7FB301DA"
        },
        [51010426] = {
          ContentFR = "♪ La neige blanche est son eau matricielle, la ligne de l’aube et du crépuscule son cordon ombilical...\nElle enfante grandeur et souffrance, versant sa progéniture dans un berceau de fer noir, sous la montagne enneigée... ♪",
          DialogueId = 51010426,
          GUID = "7FB30204",
          SpeakNpcId = 700342,
          Subtitle = "♪ White snow is her birth-flow, and twilight her warm cord aglow.\nShe bears grand and pain to iron cradle — beneath the mountain, in the cold...",
          VoiceName = "voice/$Locale$/story/1002/510104/7FB30204"
        },
        [51010501] = {
          ContentFR = "Hé, c’est à toi que je parle ! Tu as bien ton permis sur toi ?",
          DialogueId = 51010501,
          GUID = "7FB30E52",
          NextOptions = {
