        [51010705] = {
          ContentFR = "Elle redresse brusquement la tête. Ses yeux brillent d’un éclat inquiétant, et les mots jaillissent comme une crue incontrôlable.",
          DialogueId = 51010705,
          GUID = "7FB32FCA",
          NextDialogue = 51010706,
