            [1] = "700329:n(700331)"
          }
        },
        [51105080] = {
          Camera = "-229.480469,380.837891,167.714844,0.000062,-7.000151,-60.003906,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J... je t’ai attendue si longtemps... Pingping, le matin est déjà là. Allons cueillir des Lys célestes pour les mettre dans un vase.",
          DialogueId = 51105080,
          GUID = "7FEF5FB8",
          NextDialogue = 51105081,
          SpeakNpcId = 700331,
          Subtitle = "I... I've been waiting so long... Pingping, the sun's come out — let's pick some Skylilies to put in the vase."
        },
        [51105081] = {
          Camera = "-132.632812,-149.719727,173.525391,0.00008,-14.200147,49.79491,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mamie... c’est Lingling... Qui est Ping—",
          DialogueId = 51105081,
          GUID = "7FEF5FE2",
          NextDialogue = 51105082,
          SpeakNpcId = 700329,
          Subtitle = "Nana? It's me — Lingling! Who's P—"
        },
        [51105082] = {
          Camera = "81.421875,127.240234,138.922852,0.000058,-3.399966,-141.004761,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pingping, c’est déjà midi. Lisons un peu ensemble.",
          DialogueId = 51105082,
          GUID = "7FEF600C",
          NextDialogue = 51105083,
          SpeakNpcId = 700331,
          Subtitle = "Pingping... it's noon now. Let's read for a while."
        },
        [51105083] = {
          Camera = "81.421875,127.240234,138.922852,0.000058,-3.399966,-141.004761,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pingping, l’après-midi est arrivé. Allons nous promener. Tu aimes les Grillons du métier, n’est-ce pas ?",
          DialogueId = 51105083,
          GUID = "7FEF6036",
          NextDialogue = 51105084,
          SpeakNpcId = 700331,
          Subtitle = "Pingping, it's afternoon... Let's take a walk. You like Loomhoppers, don't you?"
        },
        [51105084] = {
          Camera = "81.421875,127.240234,138.922852,0.000058,-3.399966,-141.004761,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pingping s’est blessée au genou... Ça fait mal ? Grand-père va souffler dessus... <I>fwooo, fwooo... </>Voilà, voilà... ça ne fait plus mal...",
          DialogueId = 51105084,
          GUID = "7FEF6060",
          NextDialogue = 51105085,
          SpeakNpcId = 700331,
          Subtitle = "Pingping, you scraped your knee? Does it hurt? Grandpa will give it some fwoo fwoo — pain, pain, go away... there, all better now."
        },
        [51105085] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce n’est pas... ce n’est pas Mamie... Et Lingling n’aime pas les Grillons du métier...",
          DialogueId = 51105085,
          FacialId = {
            [1] = "700329:Shy"
          },
          GUID = "7FEF608A",
          LookAt = {
            [1] = "700329:n(700329)"
          },
          NextDialogue = 51105086,
          SpeakNpcId = 700329,
          Subtitle = "No... this isn't right. That's not Nana... And I don't even like Loomhoppers..."
        },
        [51105086] = {
          Camera = "-749.443359,813.657715,264.467773,0.000045,-6.800218,-50.603058,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Attends... ta mamie aimait les Grillons du métier ?",
          DialogueId = 51105086,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FEF60B4",
          LookAt = {
            [1] = "100001:n(700329)"
          },
          NextDialogue = 51105087,
          SpeakNpcId = 100001,
          Subtitle = "Hold on — did your Nana like Loomhoppers?"
        },
        [51105087] = {
          Camera = "-1365.160156,-105.44873,321.923828,0.000059,-6.199885,0.00011,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mamie en attrapait parfois pour amuser Lingling... Mais Lingling criait de peur, alors Mamie a arrêté... je pense que... Mamie devait les aimer.",
          DialogueId = 51105087,
          GUID = "7FEF60DE",
          NextDialogue = 51105088,
          SpeakNpcId = 700329,
          Subtitle = "Nana used to catch them to cheer me up, but I was so scared I screamed, so she never did that again... I think maybe she did like them.",
          TurnTo = {
            [1] = "700329:n(100001)"
          }
        },
        [51105088] = {
          Camera = "-8.46875,144.892578,124.898438,0.000009,2.799899,-77.20108,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu te souviens du nom de ta mamie ?",
          DialogueId = 51105088,
          GUID = "7FEF6108",
          NextDialogue = 51105089,
          SpeakNpcId = 100001,
          Subtitle = "Do you remember what your Nana's name was?",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          }
        },
        [51105089] = {
          Camera = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah... Lingling s’en souvient ! Mamie s’appelait Siping !",
          DialogueId = 51105089,
          FacialId = {
            [1] = "700329:Shock02"
          },
          GUID = "7FEF6132",
          NextDialogue = 51105090,
          SpeakNpcId = 700329,
          Subtitle = "Oh! I remember now! Her name was Siping!"
        },
        [51105090] = {
          Camera = "-93.003906,-42.301758,148.769531,0.000082,-13.200105,37.594505,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pingping... quand es-tu revenue ?",
          DialogueId = 51105090,
          GUID = "7FEF615C",
          NextDialogue = 51105091,
          SpeakNpcId = 700331,
          Subtitle = "Pingping, when did you come home?",
          TurnTo = {
            [1] = "700329:n(700331)"
          }
        },
        [51105091] = {
          Camera = "-93.003906,-42.301758,148.769531,0.000082,-13.200105,37.594505,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J... je t’ai attendue si longtemps... Pingping, le matin est déjà là. Allons cueillir des Lys célestes pour les mettre dans un vase.",
          DialogueId = 51105091,
          GUID = "7FEF6186",
          NextDialogue = 51105092,
          SpeakNpcId = 700331,
          Subtitle = "I... I've been waiting so long... Pingping, the sun's come out — let's pick some Skylilies to put in the vase."
        },
        [51105092] = {
          Camera = "-93.003906,-42.301758,148.769531,0.000082,-13.200105,37.594505,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pingping, c’est déjà midi. Lisons un peu ensemble.",
          DialogueId = 51105092,
          GUID = "7FEF61B0",
          NextDialogue = 51105093,
          SpeakNpcId = 700331,
          Subtitle = "Pingping... it's noon now. Let's read for a while."
        },
        [51105093] = {
          Camera = "-8.46875,144.892578,124.898438,0.000009,2.799899,-77.20108,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Il semble t’avoir prise pour Siping... Cela voudrait dire que c’est sans doute le grand-père de ta mamie. Ce qui ferait de lui ton... ?",
          DialogueId = 51105093,
          GUID = "7FEF61DA",
          NextDialogue = 51105094,
          SpeakNpcId = 100001,
          Subtitle = "Looks like he mistook you for your Nana. He must be your Nana's grandfather, which makes him your...?",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          TurnTo = {
            [1] = "700329:n(100001)"
          }
        },
        [51105094] = {
          Camera = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mon... arrière-arrière-grand-père ! Mamie disait souvent que Lingling lui ressemblait quand elle était petite... Alors c’était vrai...",
          DialogueId = 51105094,
          GUID = "7FEF6204",
          NextDialogue = 51105095,
          SpeakNpcId = 700329,
          Subtitle = "My great-great-grandfather! Nana always said I looked just like her when she was little... So it really was true!",
          TalkActionId = {
            [1] = "700329:Explain01_Start"
          }
        },
        [51105095] = {
          Camera = "-91.40625,-207.694824,175.608398,0.000038,-12.000027,61.9986,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Donc Mamie n’était pas née Mamie... Elle aussi avait des aînés qui prenaient soin d’elle...",
          DialogueId = 51105095,
          GUID = "7FEF622E",
          NextDialogue = 51105096,
          SpeakNpcId = 700329,
          Subtitle = "Ah, so Nana wasn't born a Nana... She was a kid who had grown-ups who loved her, too...",
          TalkActionId = {
            [1] = "700329:Explain01_End"
          }
        },
        [51105096] = {
          Camera = "-93.003906,-42.301758,148.769531,0.000082,-13.200105,37.594505,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pingping... quand es-tu revenue ?",
          DialogueId = 51105096,
          GUID = "7FEF6258",
          NextDialogue = 51105097,
          SpeakNpcId = 700331,
          Subtitle = "Pingping, when did you come home?",
          TurnTo = {
            [1] = "700329:n(700331)"
          }
        },
        [51105097] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Lingling ne l’a jamais rencontré... On disait qu’il était mort quand Mamie était jeune, juste après qu’ils avaient déménagé à Haojing. La nouvelle est arrivée trop tard... Mamie n’a jamais pu lui dire adieu...",
          DialogueId = 51105097,
          FacialId = {
            [1] = "700329:Sad01"
          },
          GUID = "7FEF6282",
          NextDialogue = 51105098,
          SpeakNpcId = 700329,
          Subtitle = "I never met him... Nana said he passed away when she was young, when she just moved to Haojing. She didn't get the news in time because of the move... so she never got to say goodbye..."
        },
        [51105098] = {
          Camera = "-8.46875,144.892578,124.898438,0.000009,2.799899,-77.20108,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Voilà pourquoi il est devenu un Wishen... Il attendait que Siping rentre chez elle.",
          DialogueId = 51105098,
          GUID = "7FEF62AC",
          NextDialogue = 51105099,
          SpeakNpcId = 100001,
          Subtitle = "That's why he became a Wishen — waiting for Siping to come home, even now.",
          TurnTo = {
            [1] = "700329:n(100001)"
          }
        },
        [51105099] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Oui. C’est sûrement ça.",
          DialogueId = 51105099,
          GUID = "7FEF62D6",
          NextOptions = {
            [1] = 51105100
          },
          SpeakNpcId = 700329,
          Subtitle = "That must be it..."
        },
        [51105100] = {
          ContentFR = "Ce n’était pas ta mamie qui était à tes côtés... tu te sens déçue ?",
          DialogueId = 51105100,
          GUID = "7FEF6300",
          ImprPlusId = 1209,
          NextDialogue = 51105101,
          Subtitle = "Are you sad it wasn't Nana?"
        },
        [51105101] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Oui. Un petit peu.",
          DialogueId = 51105101,
          GUID = "7FEF632A",
          LookAt = {
            [1] = "700329:n(700329)"
          },
          NextDialogue = 51105102,
          SpeakNpcId = 700329,
          Subtitle = "...A little, I guess.",
          TalkActionId = {
            [1] = "700329:Think_Start"
          }
        },
        [51105102] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais en voyant arrière-arrière-grand-papa comme ça... Lingling ne voudrait pas que Mamie finisse pareille. Rester ici à errer, pleine de regrets...",
          DialogueId = 51105102,
          GUID = "7FEF6354",
          NextDialogue = 51105103,
          SpeakNpcId = 700329,
          Subtitle = "But... seeing Great-Great-Grandpa like this — I don't want Nana to end up the same... Stuck here, full of regrets..."
        },
        [51105103] = {
          Camera = "-333.121094,-499.869141,192.47168,0.000051,-9.400239,56.996445,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Maintenant, Lingling se dit même que c’est une bonne chose... Mamie a sûrement accompli tous ses souhaits avant de devenir une étoile...",
          DialogueId = 51105103,
          GUID = "7FEF637E",
          NextDialogue = 51105104,
          SpeakNpcId = 700329,
          Subtitle = "Now I'm almost glad — Nana's wishes must've all come true before she became a star..."
        },
        [51105104] = {
          Camera = "-333.121094,-499.869141,192.47168,0.000051,-9.400239,56.996445,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Peut-être que Mamie espérait aussi... qu’en devenant une étoile, elle pourrait retrouver son grand-père et attraper des Grillons du métier avec lui. Mais au final... ils sont toujours séparés, chacun de leur côté...",
          DialogueId = 51105104,
          GUID = "7FEF63A8",
          NextDialogue = 51105105,
          SpeakNpcId = 700329,
          Subtitle = "Maybe... she became a star so she could find her grandpa again. Maybe she wanted to chase Loomhoppers with him, like they used to... But even now, they still can't be together...",
          TalkActionId = {
            [1] = "700329:Think_End"
          }
        },
        [51105105] = {
          Camera = "-8.46875,144.892578,124.898438,0.000009,2.799899,-77.20108,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu aimerais l’aider à se libérer de son attachement ?",
          DialogueId = 51105105,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FEF63D2",
          NextDialogue = 51105106,
          SpeakNpcId = 100001,
          Subtitle = "Do you want to help him let go?"
        },
        [51105106] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui ! Lingling veut absolument le faire !",
          DialogueId = 51105106,
          GUID = "7FEF63FC",
          LookAt = {
            [1] = "700329:n(700331)"
          },
          SpeakNpcId = 700329,
          Subtitle = "Absolutely!",
          TalkActionId = {
            [1] = "700329:Explain02_Start"
          }
        },
        [51105107] = {
          Camera = "-229.480469,380.837891,167.714844,0.000062,-7.000151,-60.003906,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Grand-papa, regarde ! Lingling t’a apporté des Grillons du métier !",
          DialogueId = 51105107,
          GUID = "7FEF6D02",
          NextDialogue = 51105108,
          Scripts = [[
SEQ{
TurnTo{TurnToDescription{"700329:n(700331)"}},
PlayAnimation{ActorId{700329},AnimationId{"Give"},Duration{2}},
}]],
          SpeakNpcId = 700329,
          Subtitle = "Look, Grandpa — I brought you Loomhoppers!"
        },
        [51105108] = {
          Camera = "-132.632812,-149.719727,173.525391,0.00008,-14.200147,49.79491,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pingping... quand es-tu revenue ?",
          DialogueId = 51105108,
          GUID = "7FEF6D2C",
          NextDialogue = 51105109,
          SpeakNpcId = 700331,
          Subtitle = "Pingping, when did you come home?"
        },
        [51105109] = {
          Camera = "-333.121094,-499.869141,192.47168,0.000051,-9.400239,56.996445,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ça fait déjà un moment que Lingling est revenue ! On est restés ensemble plusieurs jours... tu t’en souviens, Grand-papa ?",
          DialogueId = 51105109,
          GUID = "7FEF6D56",
          NextDialogue = 51105110,
          SpeakNpcId = 700329,
          Subtitle = "I've been back a while! We've spent so many days together — do you remember, Grandpa?",
          TalkActionId = {
            [1] = "700329:Confident_Start"
          }
        },
        [51105110] = {
          Camera = "-265.007812,-512.92627,1311.914062,0.000054,-24.599936,45.398846,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "À partir de maintenant, Grand-papa n’aura plus jamais à attraper des Grillons du métier tout seul ! Lingling ira avec toi cueillir des Lys célestes, lire des livres... et faire plein de choses ensemble !",
          DialogueId = 51105110,
          GUID = "7FEF6D80",
          NextDialogue = 51105111,
          SpeakNpcId = 700329,
          Subtitle = "From now on, you won't have to catch Loomhoppers all by yourself! I'll pick Skylilies with you, read with you — we'll do all sorts of things together!"
        },
        [51105111] = {
          Camera = "-333.121094,-499.869141,192.47168,0.000051,-9.400239,56.996445,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Lingling ne laissera plus jamais Grand-papa tout seul !",
          DialogueId = 51105111,
          GUID = "7FEF6DAA",
          NextDialogue = 51105112,
          SpeakNpcId = 700329,
          Subtitle = "You don't have to be alone ever again!",
          TalkActionId = {
            [1] = "700329:Confident_End"
          }
        },
        [51105112] = {
          Camera = "-132.632812,-149.719727,173.525391,0.00008,-14.200147,49.79491,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh... oh... Pingping est revenue... Pingping est vraiment rentrée à la maison...",
          DialogueId = 51105112,
          GUID = "7FEF6DD4",
          NextDialogue = 51105113,
          SpeakNpcId = 700331,
          Subtitle = "Oh... Pingping's back... Pingping really came home..."
        },
        [51105113] = {
          Camera = "-229.480469,380.837891,167.714844,0.000062,-7.000151,-60.003906,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Grand-papa croyait qu’il ne reverrait plus jamais Pingping... Mais je le savais... Pingping reviendrait me voir...",
          DialogueId = 51105113,
          GUID = "7FEF6DFE",
          NextDialogue = 51105114,
          SpeakNpcId = 700331,
          Subtitle = "I thought... I'd never see her again. But I knew she'd come back... my dear Pingping..."
        },
        [51105114] = {
          Camera = "81.421875,127.240234,138.922852,0.000058,-3.399966,-141.004761,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Si Pingping n’était pas là avant... C’est sûrement qu’elle n’avait pas trouvé le chemin du retour...",
          DialogueId = 51105114,
          GUID = "7FEF6E28",
          NextDialogue = 51105115,
          SpeakNpcId = 700331,
          Subtitle = "She must've lost her way... That's why it took her so long to come back..."
        },
        [51105115] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui ! Ces derniers jours, Lingling jouait juste à cache-cache avec toi ! Maintenant que Grand-papa m’a trouvée, bien sûr que Lingling va rester avec toi ! Lingling habitera ici très, très longtemps...",
          DialogueId = 51105115,
          GUID = "7FEF6E52",
          NextDialogue = 51105116,
          SpeakNpcId = 700329,
          Subtitle = "That's right! I was just playing hide-and-seek with you, Grandpa! And now that you've found me, I'm not going anywhere. I'll be by your side for a long, long time...",
          TalkActionId = {
            [1] = "700329:Talk02_Start"
          }
        },
        [51105116] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Grand-papa pourra voir Lingling tous les jours !",
          DialogueId = 51105116,
          GUID = "7FEF6E7C",
          NextDialogue = 51105117,
          SpeakNpcId = 700329,
          Subtitle = "Now you can see me every single day!",
          TalkActionId = {
            [1] = "700329:Talk02_End"
          }
        },
        [51105117] = {
          Camera = "81.421875,127.240234,138.922852,0.000058,-3.399966,-141.004761,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vraiment... quelle merveille... Quelle merveille... j’ai enfin attendu assez longtemps...",
          DialogueId = 51105117,
          GUID = "7FEF6EA6",
          NextDialogue = 51105118,
          SpeakNpcId = 700331,
          Subtitle = "Is that so...? How wonderful... Finally..."
        },
        [51105118] = {
          Camera = "-460.025391,-656.214355,288.115234,0.000004,-13.200009,55.399296,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci... Merci à vous deux...",
          DialogueId = 51105118,
          GUID = "7FEF6ED0",
          NextOptions = {
            [1] = 51105119,
            [2] = 51105121,
            [3] = 51105123
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{700331},AnimationId{"Wuyou_Disappear01"},Duration{1.5}},
SetVisibility{ActorId{700331},Visibility{"Hide"}}
}]],
          SpeakNpcId = 700331,
          Subtitle = "Thank you... both of you..."
        },
        [51105119] = {
          ContentFR = "<I>Tu n’avais pas peur des Grillons du métier ?</>",
          DialogueId = 51105119,
          GUID = "7FEF6EFA",
          ImprPlusId = 1208,
          NextDialogue = 51105120,
          Subtitle = "I thought you were scared of Loomhoppers."
        },
        [51105120] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Lingling a très peur des insectes... Ils ont plein de pattes qui bougent, et quand on les tient, ça chatouille et ça pique. Mais en pensant que c’était un souvenir partagé entre arrière-arrière-grand-papa et Mamie, Lingling a l’impression que ce n’est plus aussi effrayant qu’avant.",
          DialogueId = 51105120,
          GUID = "7FEF6F24",
          NextDialogue = 51105126,
          SpeakNpcId = 700329,
          Subtitle = "I am! They've got so many legs and they prickle my fingers... But if they meant something special to Great-Great-Grandpa and Nana... then I guess they're not that scary after all.",
          TurnTo = {
            [1] = "700329:n(100001)"
          }
        },
        [51105121] = {
          ContentFR = "<I>Faire semblant d’être Pingping, c’est mentir ?</>",
          DialogueId = 51105121,
          GUID = "7FEF6F4E",
          ImprPlusId = 1210,
          NextDialogue = 51105122,
          Subtitle = "Does pretending to be Pingping count as lying?"
        },
        [51105122] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Lingling n’a jamais dit qu’elle était Pingping ! C’est arrière-arrière-grand-papa qui s’est trompé tout seul ! Lingling ne ferait jamais quelque chose qui va contre les Neuf Chapitres !",
          DialogueId = 51105122,
          GUID = "7FEF6F78",
          NextDialogue = 51105126,
          SpeakNpcId = 700329,
          Subtitle = "I never said I was! Great-Great-Grandpa just thought I was! I'd never break the Nine Chapters!",
          TurnTo = {
            [1] = "700329:n(100001)"
          }
        },
        [51105123] = {
          ContentFR = "<I>Maintenant que Mamie et arrière-arrière-grand-papa ne sont plus là... tu te sens seule ?</>",
          DialogueId = 51105123,
          GUID = "7FEF6FA2",
          ImprPlusId = 1209,
          NextDialogue = 51105124,
          Subtitle = "Now that they're both gone... do you feel lonely?"
        },
        [51105124] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non ! Le cœur de Lingling est tout chaud. Même s’ils sont partis... leur affection s’est sûrement transformée en une autre façon de protéger Lingling.",
          DialogueId = 51105124,
          GUID = "7FEF6FCC",
          NextDialogue = 51105125,
          SpeakNpcId = 700329,
          Subtitle = "Not at all! I feel all warm inside. Even if they're gone, their love for me is still here — I can feel it."
        },
        [51105125] = {
          Camera = "-49.523438,-67.03125,140.350586,0.000003,-9.599905,56.198746,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et puis... Ils ont sûrement fini par se retrouver dans le ciel, non ?",
          DialogueId = 51105125,
          GUID = "7FEF6FF6",
          NextDialogue = 51105126,
          SpeakNpcId = 700329,
          Subtitle = "And I bet they've already found each other up there!",
          TalkActionId = {
            [1] = "700329:Confident_Start"
          }
        },
        [51105126] = {
          Camera = "-702.90625,168.117188,149.791992,0.000007,-3.799948,-12.6027,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tiens ! Tout ça, c’est l’argent de poche de Lingling !",
          DialogueId = 51105126,
          GUID = "7FEF7020",
          NextDialogue = 51105127,
          SpeakNpcId = 700329,
          Subtitle = "Here! This is all of my pocket money — take it!"
        },
        [51105127] = {
          Camera = "-702.90625,168.117188,149.791992,0.000007,-3.799948,-12.6027,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "« Paiement et service réglés », <I>hum hum...</> Papa et Maman disent toujours ça. C’est une belle tradition des Tisse-Étoiles !",
          DialogueId = 51105127,
          FacialId = {
            [1] = "700329:Smile01"
          },
          GUID = "7FEF704A",
          NextDialogue = 51105128,
          SpeakNpcId = 700329,
          Subtitle = "\"Money for service,\" ahem, that's what Mum and Dad always say. It's a proud Starweaver tradition!",
          TalkActionId = {
            [1] = "700329:Confident_Start"
          }
        },
        [51105128] = {
          Camera = "-1365.160156,-105.44873,321.923828,0.000059,-6.199885,0.00011,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pour Lingling, tout ce qui s’est passé ici n’a pas de prix... Alors Lingling te donne tout ce qu’elle a ! J’espère que {性别:Monsieur|Mademoiselle} ne trouvera pas que c’est trop peu !",
          DialogueId = 51105128,
          GUID = "7FEF7074",
          SpeakNpcId = 700329,
          Subtitle = "This whole thing means more to me than anything... so I want you to have all I've got! I hope that's enough, {性别:sir|miss}!",
          TalkActionId = {
            [1] = "700329:Confident_End"
          }
        },
        [51105129] = {
          ContentFR = "Tu crois que Lingling devrait aller cueillir des lys célestes pour les mettre dans un vase ?",
          DialogueId = 51105129,
          GUID = "7FEF709E",
          SpeakNpcId = 700361,
          Subtitle = "Should I go pick some Skylilies to put in the vase?"
        },
        [51105201] = {
          ContentFR = "La Fête de la Chandelle d’Argent s’achève une fois encore. En apparence, le calme est revenu, et les Asphodèles devraient retrouver leur tumulte habituel.",
          DialogueId = 51105201,
          GUID = "7FEFBF0A",
          NextDialogue = 51105202,
          Subtitle = "The annual Silvercandle Carnival has come to a close. Silence has returned, and the Asphodel should be settling back into its usual rhythm."
        },
        [51105202] = {
          ContentFR = "Mais la réalité est tout autre... Une succession d’incidents imprévus a jeté une ombre sur ce qui devait être une célébration sans retenue.",
          DialogueId = 51105202,
          GUID = "7FEFBF34",
          NextDialogue = 51105203,
          Subtitle = "Yet, that's not quite the case. A string of unexpected events has cast a shadow over what was supposed to be a fun-filled celebration."
        },
        [51105203] = {
          ContentFR = "Ainsi, quelques jours après la fin des festivités, un léger remous éclot en silence.",
          DialogueId = 51105203,
          GUID = "7FEFBF5E",
          Subtitle = "And so, on the day after the festivities, a small ruckus quietly unfolds..."
        },
        [51105204] = {
          Camera = "122.45166,-377.09082,180.578125,0.000048,-8.599699,81.995476,35.0,219.013687,false,Manual,2.8",
          ContentFR = "... <I>Pff.</> J’ai l’impression qu’il manque quelque chose. Comme si je n’avais pas assez profité.",
          DialogueId = 51105204,
          GUID = "7FEFBF88",
          NextDialogue = 51105205,
          SpeakNpcId = 700349,
          Subtitle = "Ugh... Something's missing... It feels like I didn't get enough out of it.",
          TalkActionId = {
            [1] = "700349:Talk01_Start"
          }
        },
        [51105205] = {
          Camera = "391.339111,-304.583008,188.128906,0.00004,-11.199583,155.19725,35.0,305.677551,false,Manual,2.8",
          ContentFR = "La Fête de la Chandelle d’Argent s’est terminée comme ça, sans éclat... Quelle déception. Toute mon inspiration s’est envolée.",
          DialogueId = 51105205,
          GUID = "7FEFBFB2",
          LookAt = {
            [1] = "700350:n(700349)",
            [2] = "700349:n(700350)"
          },
          NextDialogue = 51105206,
          SpeakNpcId = 700350,
          Subtitle = "The Silvercandle Carnival just... fizzled out. It was so anticlimactic that I've lost all my inspiration.",
          TalkActionId = {
            [1] = "700350:Explain01_Start",
            [2] = "700349:Talk01_End"
          }
        },
        [51105206] = {
          Camera = "240.266602,24.936523,161.671875,0.000056,-2.399227,52.196819,35.0,204.573959,false,Manual,2.8",
          ContentFR = "...",
          DialogueId = 51105206,
          FacialId = {
            [1] = "200003:Syouganai01"
          },
          GUID = "7FEFBFDC",
          NextDialogue = 51105207,
          SpeakNpcId = 200003,
          Subtitle = "…"
        },
        [51105207] = {
          Camera = "-408.350037,74.383789,220.105469,0.00001,-11.599511,-24.20009,35.0,717.932434,false,Manual,2.8",
          ContentFR = "Qu’est-ce qui se passe ? Pourquoi tout le monde a l’air si abattu ? Normalement, Camilla aurait déjà commencé à vous dire d’arrêter de traîner et de reprendre le travail.",
          DialogueId = 51105207,
          FacialId = {
            [1] = "700352:Doubt01"
          },
          GUID = "7FEFC006",
          LookAt = {
            [1] = "700352:n(700350)",
            [2] = "700349:n(700352)",
            [3] = "700350:n(700352)"
          },
          NextDialogue = 51105208,
          SpeakNpcId = 700352,
          Subtitle = "What's going on? Why the long faces? And Camilla too. Shouldn't she be the first one telling us to stop lounging around and get back to work?",
          TalkActionId = {
            [1] = "700352:Think_Start"
          }
        },
        [51105208] = {
          Camera = "-408.350037,74.383789,220.105469,0.00001,-11.599511,-24.20009,35.0,717.932434,false,Manual,2.8",
          ContentFR = "Et pourtant... même Camilla ne dit rien.",
          DialogueId = 51105208,
          GUID = "7FEFC030",
          NextDialogue = 51105209,
          SpeakNpcId = 700352,
          Subtitle = "Even she's gone quiet."
        },
        [51105209] = {
          Camera = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
          ContentFR = "Ah ! Je sais ! Vous avez tous trop donné pendant la fête, voilà tout. Vous êtes épuisés, c’est normal ! Il vous faut un peu de repos !",
          DialogueId = 51105209,
          FacialId = {
            [1] = "700352:Confident01"
          },
          GUID = "7FEFC05A",
          LookAt = {
            [1] = "700352:n(700349)"
          },
          NextDialogue = 51105210,
          SpeakNpcId = 700352,
          Subtitle = "Ah, I see! You guys must be feeling worn out from all the hustle and bustle of the carnival, right? You need a break!",
          TalkActionId = {
            [1] = "700352:Think_End"
          }
        },
        [51105210] = {
          Camera = "122.45166,-377.09082,180.578125,0.000048,-8.599699,81.995476,35.0,219.013687,false,Manual,2.8",
          ContentFR = "Pas vraiment... c’est même l’inverse. Cette année, la fête s’est arrêtée brutalement à cause de l’incident au théâtre. Il n’y a même pas eu de final.",
          DialogueId = 51105210,
          GUID = "7FEFC084",
          LookAt = {
            [1] = "700349:n(700352)"
          },
          NextDialogue = 51105211,
          SpeakNpcId = 700349,
          Subtitle = "Not really, quite the opposite. This year's carnival was abruptly cut short due to the accident at the theatre. There wasn't a big finale... it just... ended.",
          TalkActionId = {
            [1] = "700349:Disagree"
          }
        },
        [51105211] = {
          Camera = "122.45166,-377.09082,180.578125,0.000048,-8.599699,81.995476,35.0,219.013687,false,Manual,2.8",
          ContentFR = "Tout s’est interrompu avant que l’ambiance ne prenne vraiment. Franchement... c’est pire que si la fête n’avait jamais commencé.",
          DialogueId = 51105211,
          GUID = "7FEFC0AE",
          NextDialogue = 51105212,
          SpeakNpcId = 700349,
          Subtitle = "It's like the fun stopped before it even got started. Honestly, it's worse than if we'd never celebrated at all."
        },
        [51105212] = {
          Camera = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
          ContentFR = "Je comprends... C’est comme quand je veux aider quelqu’un, et qu’à mi-chemin je découvre que tout est déjà réglé. Ça coupe toute motivation !",
          DialogueId = 51105212,
          FacialId = {
            [1] = "700352:Think02"
          },
          GUID = "7FEFC0D8",
          NextDialogue = 51105213,
          SpeakNpcId = 700352,
          Subtitle = "I get it now. It's like when I try to help someone, but halfway through, I realize they've already figured it out. It's kind of a letdown!"
        },
        [51105213] = {
          Camera = "353.20105,-320.401367,139.5,0.000096,-2.398947,159.395554,35.0,253.984177,false,Manual,2.8",
          ContentFR = "Exactement ! Comme une idée géniale dans un rêve qui disparaît au réveil... ou un éternuement qui n’arrive jamais ! J’arrive même pas à trouver un troisième exemple.",
          DialogueId = 51105213,
          GUID = "7FEFC102",
          LookAt = {
            [1] = "700350:n(700352)"
          },
          NextDialogue = 51105214,
          SpeakNpcId = 700350,
          Subtitle = "Exactly! It's like having a brilliant idea in a dream, only for it to vanish the moment you wake up. Or a sneeze that never comes out! I don't even know how to describe it."
        },
        [51105214] = {
          Camera = "353.20105,-320.401367,139.5,0.000096,-2.398947,159.395554,35.0,253.984177,false,Manual,2.8",
          ContentFR = "Bref... tout paraît sans vie.",
          DialogueId = 51105214,
          GUID = "7FEFC12C",
          NextDialogue = 51105215,
          SpeakNpcId = 700350,
          Subtitle = "It all just feels... pointless.",
          TalkActionId = {
            [1] = "700350:Explain01_End"
          }
        },
        [51105215] = {
          Camera = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
          ContentFR = "Ça a l’air plus grave que je ne le pensais...",
          DialogueId = 51105215,
          FacialId = {
            [1] = "700352:Sad01"
          },
          GUID = "7FEFC156",
          LookAt = {
            [1] = "700352:n(700350)"
          },
          NextDialogue = 51105216,
          SpeakNpcId = 700352,
          Subtitle = "That sounds pretty serious...",
          TalkActionId = {
            [1] = "700352:Think_Start"
          }
        },
        [51105216] = {
          Camera = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
          ContentFR = "Non, ça ne va pas du tout. Il faut absolument que je trouve une solution, sinon tout Givrelac va rester comme ça !",
          DialogueId = 51105216,
          GUID = "7FEFC180",
          LookAt = {
            [1] = "700352:n(700352)"
          },
          NextDialogue = 51105217,
          SpeakNpcId = 700352,
          Subtitle = "This won't do. I've got to think of something. Maybe I could get some help from someone else. Otherwise, we'll never get back to normal!",
          TalkActionId = {
            [1] = "700352:Think_End"
          }
        },
        [51105217] = {
          Camera = "65.352905,-133.640625,128.195312,0.000014,-13.199456,-33.401524,35.0,191.233246,false,Manual,2.8",
          ContentFR = "Qui pourrait m’aider... Oh ! Elles ! Bien sûr ! Elles restent toujours calmes, quoi qu’il arrive.",
          DialogueId = 51105217,
          FacialId = {
            [1] = "700352:None"
          },
          GUID = "7FEFC1AA",
          NextDialogue = 51105218,
          SpeakNpcId = 700352,
          Subtitle = "Who should I talk to...? Oh, I know! I'll ask them! They're always so composed and unfazed.",
          TalkActionId = {
            [1] = "700352:Bai_Think2Confident"
          }
        },
        [51105218] = {
          Camera = "-310.544434,-605.483398,200.802734,0.000083,-9.19898,40.997597,35.0,588.773376,false,Manual,2.8",
          ContentFR = "Si je découvre comment elles gardent leur motivation sans se laisser influencer, je pourrai redonner de l’élan à toute la cité !",
          DialogueId = 51105218,
          GUID = "7FEFC1D4",
          SpeakNpcId = 700352,
          Subtitle = "I just need to figure out how they stay so motivated and focused. I'm sure we could use their advice to snap everyone out of this funk!"
        },
        [51105301] = {
          Camera = "457.37326,-586.730225,248.960373,0.000032,-15.000139,121.598587,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vénérables aînées ! Pour redonner vie à Givrelac, je compte sur vous !",
          DialogueId = 51105301,
          GUID = "7FEFCF72",
          NextDialogue = 51105302,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0041_story_jiaojiao_tiejiang\"},RelatedRegionId{\"210101\"}}",
          SpeakNpcId = 700352,
          Subtitle = "I'm really counting on you three. Please bring some energy back to Icelake!"
        },
        [51105302] = {
          Camera = "272.063049,-136.137207,110.183517,0.000049,-7.200071,139.397171,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh... Même si la vieille que je suis ne connaît que l’art de la forge, face à tant d’enthousiasme, il m’est difficile de refuser.",
          DialogueId = 51105302,
          FacialId = {
            [1] = "700353:Happy02"
          },
          GUID = "7FEFCF9C",
          NextDialogue = 51105303,
          SpeakNpcId = 700353,
          Subtitle = "Well, I'm just a blacksmith, but it's hard to sit back and watch when Snow's so fired up about this."
        },
        [51105303] = {
          Camera = "272.063049,-136.137207,110.183517,0.000049,-7.200071,139.397171,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je veille d’ordinaire à servir boissons et ravitaillement pendant les pauses... mais si tout le monde se repose sans fin, ce n’est pas mieux.",
          DialogueId = 51105303,
          GUID = "7FEFCFC6",
          NextDialogue = 51105304,
          SpeakNpcId = 700354,
          Subtitle = "I've been serving drinks and supplies during breaks, but if everyone keeps resting... that's not good either."
        },
        [51105304] = {
          Camera = "272.063049,-136.137207,110.183517,0.000049,-7.200071,139.397171,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mm-hmm, l’intention de Snow est louable. Dans mes chroniques, Givrelac est la grande cité du Nord... Si tout le monde manque d’énergie, je vais devoir la rebaptiser « la Dormiville du Nord ».",
          DialogueId = 51105304,
          GUID = "7FEFCFF0",
          NextDialogue = 51105305,
          SpeakNpcId = 700355,
          Subtitle = "Mm-hmm, Snow's heart is in the right place. Icelake's always been known as the great northern metropolis in my records, but if the citizens don't get their energy back, I might have to start calling it \"Great Somnopolis.\""
        },
        [51105305] = {
          Camera = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Voilà ! C’est exactement ce que je pense ! Alors trouvons ensemble un moyen de réveiller tout le monde !",
          DialogueId = 51105305,
          GUID = "7FEFD01A",
          NextDialogue = 51105306,
          SpeakNpcId = 700352,
          Subtitle = "Right? That's exactly what I think. So, let's come up with something to help everyone snap out of it!",
          TalkActionId = {
            [1] = "700352:Talk02_Start"
          }
        },
        [51105306] = {
          Camera = "135.03241,-10.31543,93.88092,0.000073,-4.399932,146.59407,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Selon moi, la solution est simple —",
          DialogueId = 51105306,
          FacialId = {
            [1] = "700353:Happy01"
          },
          GUID = "7FEFD044",
          NextDialogue = 51105307,
          SpeakNpcId = 700353,
          Subtitle = "Well, from my perspective, the answer is simple—"
        },
        [51105307] = {
          Camera = "130.178741,-15.803711,93.827461,0.000077,-0.999905,121.994286,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Il n’existe qu’un seul véritable remède, à savoir —",
          DialogueId = 51105307,
          GUID = "7FEFD06E",
          NextDialogue = 51105308,
          SpeakNpcId = 700354,
          Subtitle = "There's only one true solution, and that is—",
          TalkActionId = {
            [1] = "700352:Talk02_End"
          }
        },
        [51105308] = {
          Camera = "132.125397,17.031494,91.702133,0.000075,-2.599946,-177.40564,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui, j’y ai pensé immédiatement —",
          DialogueId = 51105308,
          GUID = "7FEFD098",
          NextDialogue = 51105309,
          SpeakNpcId = 700355,
          Subtitle = "Yeah, I know exactly what to do—",
          TalkActionId = {
            [1] = "700355:Confident_Start"
          }
        },
        [51105309] = {
          Camera = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Lequel ?!",
          DialogueId = 51105309,
          GUID = "7FEFD0C2",
          NextDialogue = 51105310,
          SpeakNpcId = 700352,
          Subtitle = "What is it?!",
          TalkActionId = {
            [1] = "700352:Excited01_Start"
          }
        },
        [51105310] = {
          Camera = "618.50708,-678.68042,180.93396,0.000092,-5.799923,127.191681,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = [[
Forger !
Commercer !
Explorer !]],
          DialogueId = 51105310,
          FacialId = {
            [1] = "700353:Smile02"
          },
          GUID = "7FEFD0EC",
          NextDialogue = 51105311,
          SpeakNpcName = "UI_CMName_Name_SanRenTongShi",
          Subtitle = "FORGING! TRADING! ADVENTURE!"
        },
        [51105311] = {
          Camera = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce sont trois choses complètement différentes !",
          DialogueId = 51105311,
          FacialId = {
            [1] = "700352:Unhappy01"
          },
          GUID = "7FEFD116",
          NextDialogue = 51105312,
          SpeakNpcId = 700352,
          Subtitle = "Those are three totally different things!",
          TalkActionId = {
            [1] = "700352:Excited01_End"
          }
        },
        [51105312] = {
          Camera = "429.908936,-169.867676,216.608871,0.000088,-20.19973,151.389633,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et ce ne sont pas des solutions, mais simplement ce que chacune de vous sait faire !",
          DialogueId = 51105312,
          GUID = "7FEFD140",
          NextDialogue = 51105313,
          SpeakNpcId = 700352,
          Subtitle = "More like what each of you specializes in, not actual solutions!",
          TalkActionId = {
            [1] = "700352:Sigh_Start"
          }
        },
        [51105313] = {
          Camera = "214.145203,-52.911133,124.187378,0.000093,-10.999684,148.988251,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh ? Voilà qui est inattendu.",
          DialogueId = 51105313,
          FacialId = {
            [1] = "700353:Shock01"
          },
          GUID = "7FEFD16A",
          NextDialogue = 51105314,
          SpeakNpcId = 700353,
          Subtitle = "Well, I didn't see that coming."
        },
        [51105314] = {
          Camera = "214.145203,-52.911133,124.187378,0.000093,-10.999684,148.988251,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je pensais pourtant que nous avions exactement la même idée.",
          DialogueId = 51105314,
          GUID = "7FEFD194",
          LookAt = {
            [1] = "700354:n(700353)"
          },
          NextDialogue = 51105315,
          SpeakNpcId = 700355,
          Subtitle = "I thought you two would be on the same page as I am."
        },
        [51105315] = {
          Camera = "214.145203,-52.911133,124.187378,0.000093,-10.999684,148.988251,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Donc si vous ne vendez rien, c’est parce que vous pensez vraiment que le commerce n’est pas essentiel. Je suis un peu déçue.",
          DialogueId = 51105315,
          GUID = "7FEFD1BE",
          LookAt = {
            [1] = "700355:n(700353)"
          },
          NextDialogue = 51105316,
          SpeakNpcId = 700354,
          Subtitle = "Hmm, so that's why you two never sell anything. Now I'm a little disappointed."
        },
        [51105316] = {
          Camera = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Attendez, attendez ! Bon... Puisque chacune de vous est convaincue que son activité redonne de l’énergie, alors je vais tout essayer, une par une !",
          DialogueId = 51105316,
          GUID = "7FEFD1E8",
          LookAt = {
            [1] = "700354:n(700352)",
            [2] = "700355:n(700352)"
          },
          NextDialogue = 51105317,
          SpeakNpcId = 700352,
          Subtitle = "Wait, wait, hold on! I've got an idea. Since you all think your work can help lift everyone's spirits, I'll try each of your ideas, one by one.",
          TalkActionId = {
            [1] = "700352:Sigh_End"
          }
        },
        [51105317] = {
          Camera = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Allons-y, commençons par moi. Prends un marteau, et tu verras : l’ardeur reviendra d’elle-même.",
          DialogueId = 51105317,
          FacialId = {
            [1] = "700353:Confident02"
          },
          GUID = "7FEFD212",
          NextDialogue = 51105318,
          SpeakNpcId = 700353,
          Subtitle = "Alright, let's start with me! Grab a hammer, and I'll show you how to get fired up!"
        },
        [51105318] = {
          Camera = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "D’accord. Je n’ai jamais fait ça... Vous pouvez m’apprendre ?",
          DialogueId = 51105318,
          FacialId = {
            [1] = "700353:CM_Idle"
          },
          GUID = "7FEFD23C",
          NextDialogue = 51105319,
          SpeakNpcId = 700352,
          Subtitle = "You got it! But I've never done this before. Can you teach me the ropes?",
          TalkActionId = {
            [1] = "700352:AgreeHead"
          }
        },
        [51105319] = {
          Camera = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est très simple. Prends le marteau, inspire profondément... et frappe —",
          DialogueId = 51105319,
          FacialId = {
            [1] = "700353:Smile02"
          },
          GUID = "7FEFD266",
          NextDialogue = 51105320,
          SpeakNpcId = 700353,
          Subtitle = "It's simple, really. Just grab the hammer, take a deep breath, and... smash—"
        },
        [51105320] = {
          Camera = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "En imaginant le sourire de ceux qui verront ton œuvre achevée. C’est ainsi que naît la motivation.",
          DialogueId = 51105320,
          GUID = "7FEFD290",
          NextDialogue = 51105321,
          SpeakNpcId = 700353,
          Subtitle = "Hit it while imagining how happy people will be when they see what you've made. That's the motivation you need."
        },
        [51105321] = {
          Camera = "-202.37793,93.230225,130.826981,0.000078,-8.999676,-11.213411,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et puis, frapper avec rythme, voir jaillir les étincelles... Chaque coup apporte son lot de satisfaction.",
          DialogueId = 51105321,
          GUID = "7FEFD2BA",
          NextDialogue = 51105322,
          SpeakNpcId = 700353,
          Subtitle = "And on top of that, seeing the sparks fly with every rhythmic strike will give you a real sense of accomplishment."
        },
        [51105322] = {
          Camera = "-5.819641,123.071289,115.489243,0.000093,-10.599607,-37.011742,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hmm... je crois comprendre. En résumé, manier un marteau rend enthousiaste.",
          DialogueId = 51105322,
          FacialId = {
            [1] = "700352:Happy02"
          },
          GUID = "7FEFD2E4",
          NextDialogue = 51105323,
          SpeakNpcId = 700352,
          Subtitle = "Okay... I think I get it now. So, swinging a giant hammer makes you feel powerful.",
          TalkActionId = {
            [1] = "700352:SpecialConfident_Start"
          }
        },
        [51105323] = {
          Camera = "-5.819641,123.071289,115.489243,0.000093,-10.599607,-37.011742,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Allez, c’est mon tour... Ouaaah ! C’est lourd !",
          DialogueId = 51105323,
          FacialId = {
            [1] = "700352:Shock02"
          },
          GUID = "7FEFD30E",
          NextDialogue = 51105324,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/jiaojiao/hammer\"},PlayAs2D{true}}",
          SpeakNpcId = 700352,
          Subtitle = "Let me give it a try... Whoa, this thing's heavy...",
          TalkActionId = {
            [1] = "700352:SpecialConfident_End"
          }
        },
        [51105324] = {
          ContentFR = "Snow lève le marteau et l’abat de toutes ses forces.",
          DialogueId = 51105324,
          GUID = "7FEFD338",
          IsBlack = 1,
          NextDialogue = 51105325,
          Subtitle = "Snow lifted the hammer and swung it with all her might."
        },
        [51105325] = {
          Camera = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh... C’est vrai... On sent la puissance jaillir du corps en maniant un tel marteau...",
          DialogueId = 51105325,
          FacialId = {
            [1] = "700352:Confident02"
          },
          GUID = "7FEFD362",
          NextDialogue = 51105326,
          SpeakNpcId = 700352,
          Subtitle = "Hmm, yeah… swinging this hammer really does make me feel... like there's power flowing through me.",
          TalkActionId = {
            [1] = "700352:SpecialHappy_Start"
          }
        },
        [51105326] = {
          Camera = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Peut-être que si tout le monde forgeait ensemble, ils retrouveraient le sourire !",
          DialogueId = 51105326,
          GUID = "7FEFD38C",
          NextDialogue = 51105327,
          SpeakNpcId = 700352,
          Subtitle = "Maybe I could get everyone to try forging. It could be fun!"
        },
        [51105327] = {
          ContentFR = "Mais à mesure que Snow continue, ses gestes se font de plus en plus lents...",
          DialogueId = 51105327,
          GUID = "7FEFD3B6",
          IsBlack = 1,
          NextDialogue = 51105328,
          Subtitle = "As Snow continued to swing the hammer, her movements began to slow.",
          TalkActionId = {
            [1] = "700352:SpecialHappy_End"
          }
        },
        [51105328] = {
          Camera = "31.725586,31.275146,96.110329,0.000056,-5.000033,-13.205209,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je... suis épuisée... Je n’y arrive plus...",
          DialogueId = 51105328,
          FacialId = {
            [1] = "700352:Sad03"
          },
          GUID = "7FEFD3E0",
          NextDialogue = 51105329,
          SpeakNpcId = 700352,
          Subtitle = "So... tired... Can't swing... anymore...",
          TalkActionId = {
            [1] = "700352:BaiTX_Story_Cry_Start"
          }
        },
        [51105329] = {
          Camera = "-1.381409,25.406982,97.682739,0.000088,-5.599846,-10.014951,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non... c’est trop... Je dois dormir tout de suite... Bonne nuit...",
          DialogueId = 51105329,
          GUID = "7FEFD40A",
          NextDialogue = 51105330,
          SpeakNpcId = 700352,
          Subtitle = "No good. I'm wiped out. I need to sleep... Goodnight..."
        },
        [51105330] = {
          Camera = "-1.381409,25.406982,97.682739,0.000088,-5.599846,-10.014951,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et je peux déjà tirer une conclusion... Cette méthode n’est pas vraiment adaptée pour redonner de l’énergie à tout le monde...",
          DialogueId = 51105330,
          FacialId = {
            [1] = "700352:Syouganai01"
          },
          GUID = "7FEFD434",
          NextDialogue = 51105331,
          SpeakNpcId = 700352,
          Subtitle = "And I don't think this is the best way to motivate people..."
        },
        [51105331] = {
          Camera = "203.842834,-65.611328,97.294655,0.000084,-5.799711,133.783813,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Voilà pourquoi cela ne fonctionne pas. Travailler à l’excès ne fait qu’aggraver la fatigue.",
          DialogueId = 51105331,
          GUID = "7FEFD45E",
          NextDialogue = 51105332,
          SpeakNpcId = 700354,
          Subtitle = "Told you. Overworking just makes everyone more tired."
        },
        [51105332] = {
          Camera = "203.842834,-65.611328,97.294655,0.000084,-5.799711,133.783813,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "La fête existait pour permettre aux gens de se reposer. Le bruit des marteaux devrait rester une musique de fond, pas l’activité principale.",
          DialogueId = 51105332,
          GUID = "7FEFD488",
          NextDialogue = 51105333,
          SpeakNpcId = 700354,
          Subtitle = "The carnival was supposed to help people relax, not turn into a workout. The clanging of hammers should've been the background noise, not the main event."
        },
        [51105333] = {
          Camera = "390.128845,-909.648804,240.500732,0.000087,-4.799129,103.981491,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vraiment ? Eh bien, servir de musique d’ambiance me va très bien. À ton tour, alors. Voyons comment le commerce peut insuffler de la vitalité.",
          DialogueId = 51105333,
          FacialId = {
            [1] = "700353:Happy01"
          },
          GUID = "7FEFD4B2",
          NextDialogue = 51105334,
          SpeakNpcId = 700353,
          Subtitle = "Is that so? Well, being in the background is fine by me. Your turn! Let's see how \"trading\" is supposed to lift spirits."
        },
        [51105334] = {
          Camera = "390.128845,-909.648804,240.500732,0.000087,-4.799129,103.981491,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "<I>Hmpf. </>Tu passes trop de temps enfermée à forger. Tu n’as aucune idée de ce qui se passe dehors.",
          DialogueId = 51105334,
          GUID = "7FEFD4DC",
          NextDialogue = 51105335,
          SpeakNpcId = 700354,
          Subtitle = "Hmph, you've been stuck in that forge for too long. You clearly have no idea what's been going on outside."
        },
        [51105335] = {
          Camera = "390.128845,-909.648804,240.500732,0.000087,-4.799129,103.981491,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Suivez-moi. Et tant qu’à faire, emportez aussi Snow... elle dort déjà.",
          DialogueId = 51105335,
          GUID = "7FEFD506",
          SpeakNpcId = 700354,
          Subtitle = "Follow me. And don't forget to bring that sleepyhead along."
        },
        [51105401] = {
          Camera = "-1078.888672,-652.357727,332.403564,0.000018,-12.600039,32.600487,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hein ? Pourquoi est-ce que je me retrouve sur la place ? Ne me dis pas que j’ai frappé trop fort et que je me suis moi-même projetée jusqu’ici...",
          DialogueId = 51105401,
          FacialId = {
            [1] = "700352:Shock02"
          },
          GUID = "7FEFDFDA",
          NextDialogue = 51105402,
          SpeakNpcId = 700352,
          Subtitle = "Huh? How did I end up in the plaza? Did I swing the hammer so hard I flung myself across the city?",
          TalkActionId = {
            [1] = "700352:SpecialLook01_Start"
          },
          TurnTo = {
            [1] = "700360:n(700352)"
          }
        },
        [51105402] = {
          Camera = "-1078.888672,-652.357727,332.403564,0.000018,-12.600039,32.600487,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et vous, ça va ? Personne n’est blessé, au moins ?",
          DialogueId = 51105402,
          GUID = "7FEFE004",
          LookAt = {
            [1] = "700352:n(700355)"
          },
          NextDialogue = 51105403,
          SpeakNpcId = 700352,
          Subtitle = "Are you guys okay? I didn't hurt anyone, did I?"
        },
        [51105403] = {
          Camera = "-158.35083,-438.890656,112.984375,0.000041,-9.199888,76.798775,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non, rassure-toi. Tu as simplement trop forcé... et tu t’es épuisée.",
          DialogueId = 51105403,
          GUID = "7FEFE02E",
          LookAt = {
            [1] = "700354:n(700352)"
          },
          NextDialogue = 51105404,
          SpeakNpcId = 700354,
          Subtitle = "No, you just wore yourself out.",
          TurnTo = {
            [1] = "700352:n(700354)"
          }
        },
        [51105404] = {
          Camera = "-255.641846,4.335266,87.516602,0.000049,-5.799889,-10.203091,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je vois... Mais alors... qu’est-ce que je devais faire, déjà ?",
          DialogueId = 51105404,
          FacialId = {
            [1] = "700352:CM_Idle"
          },
          GUID = "7FEFE058",
          NextDialogue = 51105405,
          SpeakNpcId = 700352,
          Subtitle = "Oh, I see... but what was I supposed to be doing again?",
          TalkActionId = {
            [1] = "700352:Think_Start"
          }
        },
        [51105405] = {
          Camera = "19.978271,-270.103577,92.347168,0.000058,-6.999878,105.596878,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu comptais redonner de l’élan à Givrelac par le commerce.",
          DialogueId = 51105405,
          GUID = "7FEFE082",
          NextDialogue = 51105406,
          SpeakNpcId = 700354,
          Subtitle = "To breathe life back into Icelake through trading."
        },
        [51105406] = {
          Camera = "-255.641846,4.335266,87.516602,0.000049,-5.799889,-10.203091,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah oui ! Ça me revient ! Alors... comment on s’y prend, exactement ? S’il vous plaît, expliquez-moi !",
          DialogueId = 51105406,
          GUID = "7FEFE0AC",
          NextDialogue = 51105407,
          SpeakNpcId = 700352,
          Subtitle = "Oh, right! I remember now! So, what exactly do we need to do? Teach me the ropes!",
          TalkActionId = {
            [1] = "700352:Excited01_Start"
          }
        },
        [51105407] = {
          Camera = "19.978271,-270.103577,92.347168,0.000058,-6.999878,105.596878,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Eh bien, en réalité, c’est assez simple. Il faut créer des opportunités, entretenir le mystère, lancer une tendance... Quand on sait éveiller le désir, l’enthousiasme suit naturellement.",
          DialogueId = 51105407,
          GUID = "7FEFE0D6",
          NextDialogue = 51105408,
          SpeakNpcId = 700354,
          Subtitle = "Hmm… it's actually pretty simple. Create opportunities, build some suspense, start a trend. If you bait the hook right, you can reel in the passion."
        },
        [51105408] = {
          Camera = "19.978271,-270.103577,92.347168,0.000058,-6.999878,105.596878,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et lorsque l’envie de posséder, d’acheter, emplit le cœur, les gens se remettent à travailler avec entrain. C’est ainsi que l’énergie renaît.",
          DialogueId = 51105408,
          GUID = "7FEFE100",
          NextDialogue = 51105409,
          SpeakNpcId = 700354,
          Subtitle = "Once people feel that buy-it rush, they'll work hard for it. That's how you get the energy back.",
          TalkActionId = {
            [1] = "700352:Excited01_End"
          }
        },
        [51105409] = {
          Camera = "-698.29834,-1511.247803,548.52002,0.000096,-3.199643,-79.40123,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Regarde, par exemple : j’ai préparé ici une boisson exclusive de clôture de la Fête de la Chandelle d’Argent. Chaque achat donne droit à un tampon.",
          DialogueId = 51105409,
          GUID = "7FEFE12A",
          NextDialogue = 51105410,
          SpeakNpcId = 700354,
          Subtitle = "Less talk, more action. For example, I've prepared an exclusive drink just for the Silvercandle Carnival. And every purchase earns a stamp."
        },
        [51105410] = {
          Camera = "-60.891846,1.497742,78.666992,0.0,-1.200105,-41.399494,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "En réunissant cinq tampons, on obtient un chandelier d’argent en édition limitée. Il existe cinq couleurs... et une version noire irisée secrète.",
          DialogueId = 51105410,
          FacialId = {
            [1] = "700352:Shock02"
          },
          GUID = "7FEFE154",
          NextDialogue = 51105411,
          SpeakNpcId = 700354,
          Subtitle = "Collect five stamps, and you can win a limited-edition silver candlestick! There are five colors, plus a secret black version."
        },
        [51105411] = {
          Camera = "-211.238281,484.548462,133.915771,0.000002,-6.80019,-72.198151,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Allez, Snow, à toi de jouer ! Si suffisamment de gens répondent à l’appel, Givrelac retrouvera sa vitalité !",
          DialogueId = 51105411,
          GUID = "7FEFE17E",
          NextDialogue = 51105412,
          SpeakNpcId = 700354,
          Subtitle = "Come on, Snow, start shouting and get the word out! If enough people buy it, we'll bring Icelake back to life!"
        },
        [51105412] = {
          Camera = "-165.009277,12.943481,86.168457,0.000005,-5.000094,-19.198158,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh ! D’accord ! S’il faut crier pour redonner vie à la cité, alors je crierai !",
          DialogueId = 51105412,
          FacialId = {
            [1] = "700352:Happy02"
          },
          GUID = "7FEFE1A8",
          NextDialogue = 51105413,
          SpeakNpcId = 700352,
          Subtitle = "Oh, yeah! I'll do anything to bring life back to Icelake!"
        },
        [51105413] = {
          Camera = "-377.683594,-687.164856,156.533447,0.000002,-4.600002,62.002022,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Boisson exclusive de clôture de la Fête de la Chandelle d’Argent ! Achetez-en une et recevez un chandelier d’argent en édition limitée ! Et il existe même une version secrète !",
          DialogueId = 51105413,
          GUID = "7FEFE1D2",
          LookAt = {
            [1] = "700352:n(700360)"
          },
          NextDialogue = 51105414,
          SpeakNpcId = 700352,
          Subtitle = "Silvercandle Carnival exclusive drink! Get your limited-edition silver candlestick! And don't miss the secret version!",
          TalkActionId = {
            [1] = "700352:BaiTX_Story_Shout_Start"
          }
        },
        [51105414] = {
          Camera = "-377.683594,-687.164856,156.533447,0.000002,-4.600002,62.002022,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Disponible un seul jour ! Aujourd’hui seulement ! Sinon, il faudra attendre l’année prochaine ! Venez voir !",
          DialogueId = 51105414,
          GUID = "7FEFE1FC",
          LookAt = {
            [1] = "700352:n(700355)"
          },
          NextDialogue = 51105415,
          SpeakNpcId = 700352,
          Subtitle = "One day only! Get it today or wait till next year! Come one, come all!"
        },
        [51105415] = {
          Camera = "-32.104248,371.151123,518.605469,0.000011,-3.999909,-83.395515,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Les appels de Luno, la servante, et de Snow se mêlent sur la place. De nombreux passants s’arrêtent, observent... puis secouent la tête avant de repartir.",
          DialogueId = 51105415,
          GUID = "7FEFE226",
          NextDialogue = 51105416,
          Subtitle = "Snow's and Lunotress's shouts echoed across the plaza, drawing the attention of many curious onlookers. But after a quick glance, they shook their heads and walked away."
        },
        [51105416] = {
          Camera = "-107.829102,-165.86377,117.956055,0.000013,-16.999786,49.203773,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hmm... Peut-être que je ne crie pas assez fort... ?",
          DialogueId = 51105416,
          FacialId = {
            [1] = "700352:Sad03"
          },
          GUID = "7FEFE250",
          NextDialogue = 51105417,
          SpeakNpcId = 700352,
          Subtitle = "Hmm... Maybe I'm not shouting loud enough?",
          TalkActionId = {
            [1] = "700352:BaiTX_Story_Shout_End"
          }
        },
        [51105417] = {
          Camera = "-107.829102,-165.86377,117.956055,0.000013,-16.999786,49.203773,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non... ce n’est pas ça. C’est juste que... à l’entendre, ça ne me donne plus vraiment envie.",
          DialogueId = 51105417,
          FacialId = {
            [1] = "700352:CM_Idle"
          },
          GUID = "7FEFE27A",
          NextDialogue = 51105418,
          SpeakNpcId = 700360,
          Subtitle = "Na, it's not that... it's just... not really exciting...",
          TurnTo = {
            [1] = "700352:n(700360);700355:n(700360)"
          }
        },
        [51105418] = {
          Camera = "-154.719238,-781.528137,203.725098,0.000044,-10.999541,77.402351,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Comment ça ? Les boissons sont délicieuses, les chandeliers raffinés... Pourquoi dire que l’envie n’y est plus ?",
          DialogueId = 51105418,
          FacialId = {
            [1] = "700352:Shock01"
          },
          GUID = "7FEFE2A4",
          LookAt = {
            [1] = "700354:n(700360)"
          },
          NextDialogue = 51105419,
          SpeakNpcId = 700354,
          Subtitle = "What? Why not? We've got great drinks, and those candlesticks are super stylish. What's not exciting?",
          TalkActionId = {
            [1] = "700352:Shock_Start"
          }
        },
        [51105419] = {
          Camera = "-59.487549,298.752197,127.998779,0.000024,-5.399681,-87.594635,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Parce que chez moi, j’ai déjà sept ou huit chandeliers... Sans compter une dizaine de plaques commémoratives et plus de vingt insignes de la fête.",
          DialogueId = 51105419,
          GUID = "7FEFE2CE",
          NextDialogue = 51105420,
          SpeakNpcId = 700360,
          Subtitle = "Well, I've already got like seven or eight candlesticks at home... plus a dozen carnival limited-edition plaques, and maybe two dozen badges or more.",
          TalkActionId = {
            [1] = "700360:Sigh_Start"
          }
        },
        [51105420] = {
          Camera = "-59.487549,298.752197,127.998779,0.000024,-5.399681,-87.594635,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pendant la Fête de la Chandelle d’Argent, tous les commerçants semblaient s’être donné le mot. Chaque boutique proposait ses objets commémoratifs... et ils étaient tous réussis.",
          DialogueId = 51105420,
          FacialId = {
            [1] = "700352:CM_Idle"
          },
          GUID = "7FEFE2F8",
          NextDialogue = 51105421,
          SpeakNpcId = 700360,
          Subtitle = "During the carnival, every shop in the city had something special and limited, and the thing is, they were all great.",
          TalkActionId = {
            [1] = "700352:Shock_End"
          }
        },
        [51105421] = {
          Camera = "-59.487549,298.752197,127.998779,0.000024,-5.399681,-87.594635,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Sans s’en rendre compte, on a trop acheté... Et maintenant, les portefeuilles sont vides, et les regrets bien présents.",
          DialogueId = 51105421,
          GUID = "7FEFE322",
          NextDialogue = 51105422,
          SpeakNpcId = 700360,
          Subtitle = "Everyone got carried away and bought tons of stuff... now we're all broke and full of regret."
        },
        [51105422] = {
          Camera = "-98.028564,-609.098694,176.426514,0.000047,-11.999569,80.00383,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors vous entendre vendre encore, une fois la fête terminée... Ça ravive surtout la culpabilité et l’amertume.",
          DialogueId = 51105422,
          GUID = "7FEFE34C",
          NextDialogue = 51105423,
          SpeakNpcId = 700360,
          Subtitle = "Hearing you still pushing sales after the carnival just brings back that guilt and pain...",
          TalkActionId = {
            [1] = "700360:Sigh_End"
          }
        },
        [51105423] = {
          Camera = "-98.028564,-609.098694,176.426514,0.000047,-11.999569,80.00383,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh... Je suis désolée... Je ne voulais pas...",
          DialogueId = 51105423,
          GUID = "7FEFE376",
          NextDialogue = 51105424,
          SpeakNpcId = 700352,
          Subtitle = "Oh... I'm sorry, I didn't mean to..."
        },
        [51105424] = {
          Camera = "-32.595215,-176.400818,129.296143,0.000064,-0.199523,-85.395256,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ne vous en faites pas. Ce n’est pas un reproche. Au contraire, on apprécie vraiment que vous essayiez tant de choses pour nous redonner le sourire.",
          DialogueId = 51105424,
          FacialId = {
            [1] = "700360:Smile01"
          },
          GUID = "7FEFE3A0",
          NextDialogue = 51105425,
          SpeakNpcId = 700360,
          Subtitle = "No hard feelings. Honestly, we appreciate that you're trying so many different ways to lift our spirits.",
          TalkActionId = {
            [1] = "700360:Explain01_Start"
          }
        },
        [51105425] = {
          Camera = "-32.595215,-176.400818,129.296143,0.000064,-0.199523,-85.395256,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Courage. Je suis sûr que vous trouverez la solution.",
          DialogueId = 51105425,
          GUID = "7FEFE3CA",
          NextDialogue = 51105426,
          SpeakNpcId = 700360,
          Subtitle = "Keep at it! I'm sure you'll figure it out!",
          TalkActionId = {
            [1] = "700360:Explain01_End",
            [2] = "700352:BaiTX_Story_RubForehead_End"
          }
        },
        [51105426] = {
          Camera = "-234.385498,-112.179077,73.116211,0.000055,-1.799529,18.207968,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui ! Alors c’est décidé ! Luno, l’exploratrice, tout repose sur vous !",
          DialogueId = 51105426,
          GUID = "7FEFE3F4",
          NextDialogue = 51105427,
          SpeakNpcId = 700352,
          Subtitle = "Right! Well, you're our last hope, Lunoxplorer.",
          TurnTo = {
            [1] = "700352:n(700355);700355:n(700352)"
          }
        },
        [51105427] = {
          Camera = "18.141846,-75.220642,83.042236,0.000054,-7.999667,171.60376,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hmm. Il est vrai que le moment est venu pour moi d’intervenir.",
          DialogueId = 51105427,
          GUID = "7FEFE41E",
          LookAt = {
            [1] = "700354:n(700355)"
          },
          NextDialogue = 51105428,
          SpeakNpcId = 700355,
          Subtitle = "Well, I guess it's my turn now.",
          TalkActionId = {
            [1] = "700355:Agree"
          }
        },
        [51105428] = {
          Camera = "18.141846,-75.220642,83.042236,0.000054,-7.999667,171.60376,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ma réponse est simple : l’aventure.",
          DialogueId = 51105428,
          GUID = "7FEFE448",
          NextDialogue = 51105429,
          SpeakNpcId = 700355,
          Subtitle = "My answer is simple— adventure!"
        },
        [51105429] = {
          Camera = "122.499512,-108.44696,348.161377,0.000066,2.39976,-124.394104,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pendant la Fête de la Chandelle d’Argent, tout le monde est resté à festoyer dans Givrelac. Il est donc logique de penser que les gens ont fini par étouffer entre ces murs.",
          DialogueId = 51105429,
          GUID = "7FEFE472",
          NextDialogue = 51105430,
          SpeakNpcId = 700355,
          Subtitle = "Everyone spent the carnival partying inside the city, but I bet they're all suffering from major cabin fever. The walls have been keeping everyone's spirits down.",
          TalkActionId = {
            [1] = "700355:Explain02_Start"
          }
        },
        [51105430] = {
          Camera = "-5.647949,-37.965942,63.306885,0.000058,-1.398379,-172.39415,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Si chacun sort de la ville, se rapproche de la nature, respire l’air libre... Alors l’esprit s’allégera à coup sûr.",
          DialogueId = 51105430,
          GUID = "7FEFE49C",
          NextDialogue = 51105431,
          SpeakNpcId = 700355,
          Subtitle = "So, if we can just get people outside, surrounded by nature, breathing fresh air... I'm sure it'll lift everyone's mood!"
        },
        [51105431] = {
          Camera = "-234.385498,-112.179077,73.116211,0.000055,-1.799529,18.207968,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh ! Ça paraît très sensé ! Dans ce cas, il suffit de trouver un endroit magnifique près du Lac du Deuil, et d’y emmener tout le monde, non ?",
          DialogueId = 51105431,
          GUID = "7FEFE4C6",
          NextDialogue = 51105432,
          SpeakNpcId = 700352,
          Subtitle = "Oh! That makes perfect sense. So, if we find the best spot near Lamenting Lake and let everyone enjoy the view, that'll do the trick, right?",
          TalkActionId = {
            [1] = "700352:RaiseHand_Start"
          }
        },
        [51105432] = {
          Camera = "-87.131836,-425.705322,92.41748,0.000067,-8.799558,88.407211,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Exactement. Tu comprends vite, Snow. Tu sais déjà ce que j’ai en tête.",
          DialogueId = 51105432,
          GUID = "7FEFE4F0",
          NextDialogue = 51105433,
          SpeakNpcId = 700355,
          Subtitle = "Exactly, you're catching on fast, Snow!",
          TalkActionId = {
            [1] = "700355:Explain02_End",
            [2] = "700352:RaiseHand_End"
          }
        },
        [51105433] = {
          Camera = "-123.174316,-60.997009,67.639648,0.000072,4.20047,5.206679,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Parfait ! Alors, en route !",
          DialogueId = 51105433,
          FacialId = {
            [1] = "700352:Happy02"
          },
          GUID = "7FEFE51A",
          SpeakNpcId = 700352,
          Subtitle = "Alright, let's go!",
          TalkActionId = {
            [1] = "700352:SpecialHappy_Start"
          }
        },
        [51105501] = {
          Camera = "913.757812,-865.021484,276.827148,0.00001,-4.399905,137.398376,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui, c’est ici. L’espace est vaste, sans entraves... parfait pour se détendre et respirer.",
          DialogueId = 51105501,
          GUID = "7FEFF042",
          NextDialogue = 51105502,
          SpeakNpcId = 700352,
          Subtitle = "Yep, this is the spot! The view is completely open and unobstructed. It's perfect for relaxing and unwinding.",
          TalkActionId = {
            [1] = "700356:Avoid",
            [2] = "700357:Avoid"
          }
        },
        [51105502] = {
          Camera = "913.757812,-865.021484,276.827148,0.00001,-4.399905,137.398376,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je suis d’accord. À chaque fois que je viens ici, j’ai l’impression que mon cœur se régénère. Je suis certaine que les autres ressentiraient la même chose.",
          DialogueId = 51105502,
          GUID = "7FEFF06C",
          NextDialogue = 51105503,
          SpeakNpcId = 700355,
          Subtitle = "You're right. Every time I come here, I feel completely recharged. I'm sure others will feel the same way and be energized by this place."
        },
        [51105503] = {
          Camera = "-157.613281,-2017.939453,386.613281,0.000007,-21.999744,146.197006,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "À l’aide ! À l’aide—",
          DialogueId = 51105503,
          GUID = "7FEFF096",
          NextDialogue = 51105504,
          SpeakNpcName = "UI_CMName_Name_FuJinChuanLai",
          Subtitle = "Help! Someone, help!"
        },
        [51105504] = {
          Camera = "-292.320312,132.621094,98.302734,0.000022,-9.399808,-35.402294,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quelqu’un appelle au secours. Allons voir.",
          DialogueId = 51105504,
          GUID = "7FEFF0C0",
          SpeakNpcId = 700355,
          Subtitle = "Sounds like someone's in trouble. Let's go check it out!",
          TalkActionId = {
            [1] = "700355:Explain01_Start"
          }
        },
        [51105505] = {
          Camera = "468.472656,-386.455078,184.522461,0.000007,-11.999959,151.198257,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci... merci de nous avoir sauvés...",
          DialogueId = 51105505,
          FacialId = {
            [1] = "700356:Sad01",
            [2] = "700357:Sad01"
          },
          GUID = "7FEFF0EA",
          LookAt = {
            [1] = "700356:n(700352);700357:n(700352);700352:n(700356);700355:n(700356)"
          },
          NextDialogue = 51105506,
          SpeakNpcId = 700356,
          Subtitle = "Th-thank you! Thank you for saving us!",
          TalkActionId = {
            [1] = "700356:Explain01_Start"
          }
        },
        [51105506] = {
          Camera = "145.941406,-168.082031,122.435547,0.000021,-0.999502,157.595932,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Sans vous, nous n’aurions jamais pu rentrer à Givrelac... <I>ouin...</>",
          DialogueId = 51105506,
          GUID = "7FEFF114",
          NextDialogue = 51105507,
          SpeakNpcId = 700357,
          Subtitle = "If you hadn't shown up, we never would've made it back to Icelake... Boohoo.",
          TalkActionId = {
            [1] = "700357:Sigh_Start"
          }
        },
        [51105507] = {
          Camera = "-72.996094,-151.029297,122.46875,0.000014,-5.599703,-1.403595,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tout va bien maintenant, vous êtes en sécurité. Mais... pourquoi étiez-vous ici ?",
          DialogueId = 51105507,
          GUID = "7FEFF13E",
          NextDialogue = 51105508,
          SpeakNpcId = 700352,
          Subtitle = "It's okay, you're safe now! But... what were you two doing all the way out here?",
          TalkActionId = {
            [1] = "700352:Confident_Start"
          }
        },
        [51105508] = {
          Camera = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est ma faute... Ma sœur et moi vivons dans Brumelac. Nos parents nous interdisent de quitter la cité.",
          DialogueId = 51105508,
          GUID = "7FEFF168",
          NextDialogue = 51105509,
          SpeakNpcId = 700356,
          Subtitle = "It's all my fault. My sister and I live in Mist Aken, and our parents never let us leave the city."
        },
        [51105509] = {
          Camera = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors, pendant la fête, quand les gardes se sont relâchés pour participer aux célébrations... Nous avons profité de l’occasion pour sortir voir l’extérieur.",
          DialogueId = 51105509,
          GUID = "7FEFF192",
          NextDialogue = 51105510,
          SpeakNpcId = 700356,
          Subtitle = "So, we thought, with everyone relaxing during the carnival, the guards wouldn't be around. We snuck out to see what the world beyond the city was like."
        },
        [51105510] = {
          Camera = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais à peine le pont traversé, nous sommes tombés sur des Souillés. On a essayé de se cacher... et plus on fuyait, plus on s’enfonçait loin...",
          DialogueId = 51105510,
          GUID = "7FEFF1BC",
          NextDialogue = 51105511,
          SpeakNpcId = 700356,
          Subtitle = "But as soon as we crossed the bridge, we ran into some Filthoids. We had to hide, and the further we went, the worse it got...",
          TalkActionId = {
            [1] = "700357:Sigh_End"
          }
        },
        [51105511] = {
          Camera = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ils ont fini par nous encercler. Sans vous...",
          DialogueId = 51105511,
          GUID = "7FEFF1E6",
          NextDialogue = 51105512,
          SpeakNpcId = 700356,
          Subtitle = "We eventually got cornered, and if it wasn't for you...",
          TalkActionId = {
            [1] = "700356:Explain01_End"
          }
        },
        [51105512] = {
          Camera = "328.121094,-260.578125,135.602539,0.00002,-5.399599,159.79628,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Grand frère... c’est ma faute. Je n’aurais pas dû insister pour sortir. Rentrons... Je ne veux plus jamais quitter Givrelac...",
          DialogueId = 51105512,
          GUID = "7FEFF210",
          LookAt = {
            [1] = "700357:n(700356)"
          },
          NextDialogue = 51105513,
          SpeakNpcId = 700357,
          Subtitle = "I'm sorry too. I shouldn't have insisted on leaving the city. Let's go back. I never want to leave the city again...",
          TalkActionId = {
            [1] = "700357:Explain02_Start"
          }
        },
        [51105513] = {
          Camera = "-72.996094,-151.029297,122.46875,0.000014,-5.599703,-1.403595,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui... Pour beaucoup de gens, le monde au-delà des murs reste bien trop dangereux...",
          DialogueId = 51105513,
          GUID = "7FEFF23A",
          LookAt = {
            [1] = "700357:n(700352)"
          },
          NextDialogue = 51105514,
          SpeakNpcId = 700352,
          Subtitle = "Hmm, for most people, the world beyond the walls is still too dangerous...",
          TalkActionId = {
            [1] = "700357:Explain02_End",
            [2] = "700352:Think_Start"
          }
        },
        [51105514] = {
          Camera = "-51.9375,-57.070312,124.332031,0.000017,-6.39975,-57.802399,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est moi qui ai manqué de discernement. Le désir d’horizons lointains peut éveiller l’enthousiasme... mais il ne convient pas à tous. Rentrons.",
          DialogueId = 51105514,
          GUID = "7FEFF264",
          SpeakNpcId = 700355,
          Subtitle = "I should've thought this through. The desire to explore can fuel excitement, but it's not for everyone. Let's head back.",
          TalkActionId = {
            [1] = "700352:Think_End",
            [2] = "700355:Agree"
          }
        },
        [51105515] = {
          ContentFR = "Des bruits de combat, vifs mais sans réelle gravité.",
          DialogueId = 51105515,
          GUID = "7FEFF28E",
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/jiaojiao/fight\"},PlayAs2D{true}}",
          Subtitle = "(The sound of a scuffle — coming from a fight that couldn't quite commit to being serious.)"
        },
        [51105601] = {
          Camera = "164.716797,101.845215,126.411133,0.000016,-13.399744,-142.802551,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors... même la méthode de Luno, l’exploratrice n’a pas fonctionné...",
          DialogueId = 51105601,
          GUID = "7FF000AA",
          LookAt = {
            [1] = "700352:n(700355);700355:n(700352)"
          },
          NextDialogue = 51105602,
          SpeakNpcId = 700352,
          Subtitle = "So, even Lunoxplorer's idea didn't work...",
          TalkActionId = {
