        },
        [51105607] = {
          Camera = "-279.733398,363.849609,151.888672,0.000033,-5.399538,-40.201584,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "À l’extérieur ?! Mais que faisaient les gardes à l’entrée... enfin... peu importe. L’essentiel, c’est que vous alliez bien.",
