        [51105839] = {
          ContentFR = "L’événement spécial va bientôt commencer. Êtes-vous prêts ?",
          DialogueId = 51105839,
          Duration = 28,
          GUID = "7FF027B6",
          Subtitle = "The event is about to begin — is everyone ready?"
        },
        [51105840] = {
          ContentFR = "Succès total ! Merci à toutes et à tous d’être venus !",
          DialogueId = 51105840,
          Duration = 5,
          GUID = "7FF027E0",
          Subtitle = "Wonderful — thank you all for coming!"
        },
        [51105900] = {
          ContentFR = "Maître ! Vous êtes sans doute la rencontre providentielle que j’attendais !",
          DialogueId = 51105900,
          GUID = "7FF031B8",
          LookAt = {
            [1] = "701005:n(0)"
          },
          NextOptions = {
            [1] = 51105901,
            [2] = 51105905,
            [3] = 51105909
          },
          SpeakNpcId = 701005,
          Subtitle = "Master! You must be the fated encounter I've been waiting for!"
        },
        [51105901] = {
          ContentFR = "<I>Quelle rencontre providentielle ? Et... j’y gagne quelque chose, moi aussi ?</>",
          DialogueId = 51105901,
          GUID = "7FF031E2",
          ImprPlusId = 1206,
          NextDialogue = 51105902,
          Subtitle = "What \"fated encounter\"? Am I supposed to get something out of this?"
        },
        [51105902] = {
          ContentFR = "Hein ? Non, non ! Personne n’a jamais dit qu’on pouvait partager les bénéfices d’une rencontre du destin !",
          DialogueId = 51105902,
          GUID = "7FF0320C",
          NextDialogue = 51105903,
          SpeakNpcId = 701005,
          Subtitle = "Huh? Of course not... The gains from a fated encounter aren't something you can share.",
          TalkActionId = {
            [1] = "701005:Talk01_Start"
          }
        },
        [51105903] = {
          ContentFR = "<I>Hss...</> attendez… je comprends ! Vous mettez mon cœur à l’épreuve !",
          DialogueId = 51105903,
          GUID = "7FF03236",
          NextDialogue = 51105904,
          SpeakNpcId = 701005,
          Subtitle = "Ah— wait. I get it. You're testing my character!"
        },
        [51105904] = {
          ContentFR = "Quelle stupidité de ma part... J’ai failli me laisser aveugler par un maigre profit. Un art divin est fait pour sauver le monde, comment pourrais-je le garder pour moi seul ?",
          DialogueId = 51105904,
          GUID = "7FF03260",
          NextDialogue = 51105913,
          SpeakNpcId = 701005,
          Subtitle = "My mistake. I almost let a little greed cloud my mind. True martial skill should serve the world — how could I keep it to myself?",
          TalkActionId = {
            [1] = "701005:Talk01_End"
          }
        },
        [51105905] = {
          ContentFR = "<I>C’est... une sorte de jeu de rôle ?</>",
          DialogueId = 51105905,
          GUID = "7FF0328A",
          ImprPlusId = 1208,
          NextDialogue = 51105906,
          Subtitle = "Is this... some kind of role-playing?"
        },
        [51105906] = {
          ContentFR = "Un jeu de quoi ?",
          DialogueId = 51105906,
          GUID = "7FF032B4",
          NextDialogue = 51105907,
          SpeakNpcId = 701005,
          Subtitle = "Huh? What's that supposed to mean?",
          TalkActionId = {
            [1] = "701005:Talk02_Start"
          }
        },
        [51105907] = {
          ContentFR = "Disons... une forme de jeu où l’on incarne des personnages d’une histoire, et où l’on joue des scènes ensemble. Tu n’as jamais fait ça, enfant ?",
          DialogueId = 51105907,
          GUID = "7FF032DE",
          NextDialogue = 51105908,
          SpeakNpcId = 100001,
          Subtitle = "Uh... it's a kind of game. People pretend to be characters in a story and act things out. You never did that as a kid?"
        },
        [51105908] = {
          ContentFR = "Incarner ? Non, non, non. Quitte à faire quelque chose, autant que ce soit réel. Faire semblant, quel intérêt ?",
          DialogueId = 51105908,
          GUID = "7FF03308",
          NextDialogue = 51105913,
          SpeakNpcId = 701005,
          Subtitle = "Pretend? No way. If we're doing something, we do it for real. Pretending is dull.",
          TalkActionId = {
            [1] = "701005:Talk02_End"
          }
        },
        [51105909] = {
          ContentFR = "<I>Exactement. Rien qu’à te regarder, on voit bien que tu es un prodige des arts martiaux, un talent que l’on ne voit qu’une fois par siècle.</>",
          DialogueId = 51105909,
          GUID = "7FF03332",
          ImprPlusId = 1210,
          NextDialogue = 51105910,
          Subtitle = "Right — one look at you and I can tell you're a once-in-a-century martial prodigy."
        },
        [51105910] = {
          ContentFR = "Vraiment ?! Je le savais ! J’étais certain d’être porteur d’un grand destin !",
          DialogueId = 51105910,
          GUID = "7FF0335C",
          NextDialogue = 51105911,
          SpeakNpcId = 701005,
          Subtitle = "Really?! I knew I was destined for greatness!"
        },
        [51105911] = {
          ContentFR = "A-ah, non, non ! Regardez-moi... je m’emporte tout seul, c’est d’un manque de savoir-vivre... Maître, permettez à votre humble disciple de vous saluer !",
          DialogueId = 51105911,
          GUID = "7FF03386",
          NextDialogue = 51105912,
          SpeakNpcId = 701005,
          Subtitle = "Wait— no, no, I'm getting carried away. I'm shouting like a madman... how rude of me. Master, please allow me to bow to you!",
          TalkActionId = {
            [1] = "701005:Salute_Start"
          }
        },
        [51105912] = {
          ContentFR = "Attends ! Je n’ai encore rien accepté !",
          DialogueId = 51105912,
          GUID = "7FF033B0",
          NextDialogue = 51105913,
          SpeakNpcId = 100001,
          Subtitle = "Hold on — I never agreed to be your master!",
          TalkActionId = {
            [1] = "701005:Salute_End"
          }
        },
        [51105913] = {
          ContentFR = "Alors, cette fameuse rencontre providentielle... de quoi s’agit-il exactement ?",
          DialogueId = 51105913,
          GUID = "7FF033DA",
          NextDialogue = 51105914,
          SpeakNpcId = 100001,
          Subtitle = "So what exactly is this \"fated encounter\" you keep mentioning?"
        },
        [51105914] = {
          ContentFR = "Laissez-moi vous expliquer. Il y a quelques jours, j’ai vu deux anciens des arts martiaux pourchassés par une bête féroce. J’ai voulu leur porter secours, mais j’étais trop faible… je n’ai même pas réussi à les rattraper.",
          DialogueId = 51105914,
          GUID = "7FF03404",
          NextDialogue = 51105915,
          SpeakNpcId = 701005,
          Subtitle = "Let me explain. A few days ago, I spotted two seasoned martial artists being chased by some vicious beast. I wanted to help, but I was too weak — I couldn't even catch up to them.",
          TalkActionId = {
            [1] = "701005:Explain01_Start"
          }
        },
        [51105915] = {
          ContentFR = "Cependant, sur leur passage, j’ai trouvé ce manuscrit incomplet. Il doit forcément renfermer un secret capable d’ébranler le monde martial ! Leur poursuite était sûrement liée à cela !",
          DialogueId = 51105915,
          GUID = "7FF0342E",
          NextDialogue = 51105916,
          SpeakNpcId = 701005,
          Subtitle = "After they ran past, I found this torn manual on the ground. I figured it had to contain some secret technique powerful enough to shake the martial world. Their trouble must've been because of it!"
        },
        [51105916] = {
          ContentFR = "Je comptais en parler à mon maître, mais son attitude a soudain changé. Il s’est mis dans une colère noire, disant que je ne pensais qu’à des choses violentes et déraisonnables, que je négligeais mes études... et il m’a exilé dans ces montagnes pour réfléchir à mes fautes.",
          DialogueId = 51105916,
          GUID = "7FF03458",
          NextDialogue = 51105917,
          SpeakNpcId = 701005,
          Subtitle = "I tried telling my shifu, but he completely lost it — said I was wasting my time on violent nonsense instead of studying. Then he sent me out to these barren hills to \"reflect on my actions\".",
          TalkActionId = {
            [1] = "701005:Explain01_End"
          }
        },
        [51105917] = {
          ContentFR = "Négliger tes études... ? Attends. Ton maître est un érudit, pas un combattant ?",
          DialogueId = 51105917,
          GUID = "7FF03482",
          NextDialogue = 51105918,
          SpeakNpcId = 100001,
          Subtitle = "Studying...? So your shifu teaches literature, not martial arts?"
        },
        [51105918] = {
          ContentFR = "C’est... embarrassant à admettre. J’ai toujours aspiré aux arts martiaux, mais dès que j’en parle, on me regarde comme un monstre, en répétant des phrases poussiéreuses du genre : « Attenter au corps ou ôter la vie — cela est proscrit. »",
          DialogueId = 51105918,
          GUID = "7FF034AC",
          NextDialogue = 51105919,
          SpeakNpcId = 701005,
          Subtitle = "I admit it — my heart's always been set on the martial path. But every time I bring up martial arts, people get all tense and start quoting things like \"To wound or kill — this must not be done.\"",
          TalkActionId = {
            [1] = "701005:Talk01_Start"
          }
        },
        [51105919] = {
          ContentFR = "Ma famille n’a engagé qu’un précepteur lettré. Un véritable maître des arts martiaux... je n’en ai encore jamais rencontré.",
          DialogueId = 51105919,
          GUID = "7FF034D6",
          NextDialogue = 51105920,
          SpeakNpcId = 701005,
          Subtitle = "My family only hired a scholar to teach me. I've never even seen a real martial arts master."
        },
        [51105920] = {
          ContentFR = "Mon maître ignore tout du combat, mais il m’a toujours traité avec bonté. Avec le recul, il a sans doute jugé ce manuscrit suspect... c’est sûrement ce malentendu qui m’a valu cette punition.",
          DialogueId = 51105920,
          GUID = "7FF03500",
          NextDialogue = 51105921,
          SpeakNpcId = 701005,
          Subtitle = "My shifu doesn't know any martial arts himself, but he's always treated me kindly. Thinking back now, he must've thought the manual looked suspicious — that's probably why he was so upset."
        },
        [51105921] = {
          ContentFR = "Vous jetez un coup d’œil au « manuscrit incomplet ». Peu importe l’angle sous lequel vous l’examinez, il s’agit clairement d’une bande dessinée de combat, avec le mot « INTERDIT » imprimé en gros sur la couverture.",
          DialogueId = 51105921,
          GUID = "7FF0352A",
          NextDialogue = 51105922,
          Subtitle = "(You take a look at the \"manual\". No matter how you look at it, it's just a martial-arts comic book — with BANNED stamped loudly across the cover.)"
        },
        [51105922] = {
          ContentFR = "En y réfléchissant un instant, tout devient clair : un passant a probablement été attaqué dans la nature par un Bi’an obscur, laissant tomber cette bande dessinée, que le jeune homme a ramassée.",
          DialogueId = 51105922,
          GUID = "7FF03554",
          NextDialogue = 51105923,
          Subtitle = "(With a bit of deduction, the whole situation becomes clear: someone out in the wild got attacked by a Sable Bi'an, dropped their comic, and this young man happened to pick it up.)"
        },
        [51105923] = {
          ContentFR = "Mais vous rencontrer, Maître, est malgré tout une bénédiction déguisée. Grâce à vos enseignements, lorsque j’aurai maîtrisé les arts divins, je défendrai la justice, sauverai le monde martial... et empêcherai Huaxu de sombrer !",
          DialogueId = 51105923,
          GUID = "7FF0357E",
          NextDialogue = 51105924,
          SpeakNpcId = 701005,
          Subtitle = "Still, meeting you turned my bad luck around. With your guidance, once I master great skills, I'll fight for justice, save the martial world, and stop Huaxu from falling apart!",
          TalkActionId = {
            [1] = "701005:Talk01_End"
          }
        },
        [51105924] = {
          ContentFR = "Donc... tu as ramassé le livre de quelqu’un, ton maître a paniqué, et te voilà envoyé ici pour réfléchir ?",
          DialogueId = 51105924,
          GUID = "7FF035A8",
          NextDialogue = 51105925,
          SpeakNpcId = 100001,
          Subtitle = "So... you picked up a random book, your teacher panicked, and now you're stuck out here doing \"self-reflection\"?"
        },
        [51105925] = {
          ContentFR = "Votre esprit est d’une clarté remarquable. C’est exactement cela, Maître.",
          DialogueId = 51105925,
          GUID = "7FF035D2",
          NextDialogue = 51105926,
          SpeakNpcId = 701005,
          Subtitle = "Exactly. You truly are perceptive, master.",
          TalkActionId = {
            [1] = "701005:Sigh_Start"
          }
        },
        [51105926] = {
          ContentFR = "Je ne vous cacherai rien : tout ce que le livre mentionnait — tomber d’une falaise, découvrir une grotte, déclencher des mécanismes secrets, pénétrer dans un tombeau ancien — j’ai tout essayé. Rien ne s’est produit.",
          DialogueId = 51105926,
          GUID = "7FF035FC",
          NextDialogue = 51105927,
          SpeakNpcId = 701005,
          Subtitle = "I even tried everything the book said about fated encounters — throwing myself off cliffs to find hidden caves, triggering traps to stumble into ancient tombs... none of it worked.",
          TalkActionId = {
            [1] = "701005:Sigh_End"
          }
        },
        [51105927] = {
          ContentFR = "Il ne restait plus qu’une méthode à tenter. J’ai donc suivi l’indication du livre et attendu ici... espérant qu’une rencontre providentielle se produise. Et vous êtes {性别:apparu|apparue}.",
          DialogueId = 51105927,
          GUID = "7FF03626",
          NextDialogue = 51105928,
          SpeakNpcId = 701005,
          Subtitle = "This was the last method I hadn't tried yet, so I came to the spot mentioned in the book to wait for one... and then you appeared."
        },
        [51105928] = {
          ContentFR = "{性别:Vêtu de blanc, tel un immortel descendu|Vêtue de blanc, telle une immortelle descendue} des cieux... vous êtes forcément un être d’exception ! Et cet œil que vous dissimulez... il doit renfermer une puissance hors du commun, n’est-ce pas ? Je vous en prie, acceptez mon salut !",
          DialogueId = 51105928,
          GUID = "7FF03650",
          NextDialogue = 51105929,
          SpeakNpcId = 701005,
          Subtitle = "Dressed in pristine white, drifting in like an immortal — you must be a true master! Your eyes must be hiding some extraordinary power — that's why you keep one concealed, isn't it? Please, allow me to bow to you!",
          TalkActionId = {
            [1] = "701005:Salute_Start"
          }
        },
        [51105929] = {
          ContentFR = "Le jeune homme semble complètement absorbé par son propre monde... Falaises, tombeaux, hasards du destin : sa vision de la réalité redéfinit le mot « rocambolesque ».",
          DialogueId = 51105929,
          GUID = "7FF0367A",
          NextDialogue = 51105930,
          Subtitle = "(He's completely swept up in his own fantasy — cliffs, caves, tombs... this is a whole new level of absurd.)"
        },
        [51105930] = {
          ContentFR = "Des lecteurs incapables de décrocher de leurs livres, vous en avez déjà croisé. Mais quelqu’un qui confond à ce point la fiction et le réel... c’est une première.",
          DialogueId = 51105930,
          GUID = "7FF036A4",
          NextDialogue = 51105931,
          Subtitle = "(You've met people who are obsessed with stories before, but someone who mixes fiction with reality this thoroughly... that's a first.)",
          TalkActionId = {
            [1] = "701005:Salute_End"
          }
        },
        [51105931] = {
          ContentFR = "Face à un être aussi déroutant que sincère, vous ne savez s’il faut en rire... ou simplement le laisser dérouler.",
          DialogueId = 51105931,
          GUID = "7FF036CE",
          NextOptions = {
            [1] = 51105932,
            [2] = 51105941
          },
          RestartTag = 51105931,
          Subtitle = "(Faced with someone this ridiculous yet oddly sincere, the best approach might be to just...)"
        },
        [51105932] = {
          ContentFR = "<I>Les maîtres hors du monde sont libres et indisciplinés. Puisqu’il est si singulier, lui enseigner deux ou trois gestes ne ferait de mal à personne.</>",
          DialogueId = 51105932,
          FailDialogue = 51105933,
          GUID = "7FF036F8",
          ImprCheckId = 1115,
          NextDialogue = 51105934,
          Subtitle = "Masters who walk outside worldly norms don't fuss over rules anyway — and he is quite a character. What's the harm in teaching him a move or two?"
        },
        [51105933] = {
          ContentFR = "<I>Un véritable maître ne prend pas de disciple à la légère. Mieux vaut réfléchir encore un peu.</>",
          DialogueId = 51105933,
          GUID = "7FF03722",
          Subtitle = "(Real masters don't just accept disciples on a whim — better think it through.)"
        },
        [51105934] = {
          ContentFR = "Dans ce cas... commence donc par trancher cette cascade.",
          DialogueId = 51105934,
          GUID = "7FF0374C",
          NextDialogue = 51105935,
          SpeakNpcId = 100001,
          Subtitle = "In that case... why don't you start by cutting that waterfall in half?"
        },
        [51105935] = {
          ContentFR = "Qu-quoi ?! M-Maître... couper une cascade, n’est-ce pas un peu excessif pour débuter ?",
          DialogueId = 51105935,
          GUID = "7FF03776",
          NextDialogue = 51105936,
          SpeakNpcId = 701005,
          Subtitle = "Huh? M—Master, isn't cutting a waterfall a bit too much for a starter like me...?"
        },
        [51105936] = {
          ContentFR = "<I>Hum.</> Crois-tu que les arts divins s’apprennent facilement ? Si tu recules dès le premier obstacle, que feras-tu face aux véritables épreuves ?",
          DialogueId = 51105936,
          GUID = "7FF037A0",
          NextDialogue = 51105937,
          SpeakNpcId = 100001,
          Subtitle = "Ahem. Training in the great arts is never easy. If you back down at the first step, what will you do when things actually get difficult?"
        },
        [51105937] = {
          ContentFR = "V-vous avez raison, mais... mais quand même...",
          DialogueId = 51105937,
          GUID = "7FF037CA",
          NextDialogue = 51105938,
          SpeakNpcId = 701005,
          Subtitle = "Y—You're right, but...",
          TalkActionId = {
            [1] = "701005:Talk02_Start"
          }
        },
        [51105938] = {
          ContentFR = "Avec une volonté aussi tremblante, comment espères-tu maîtriser quoi que ce soit ? En pleurnichant ?",
          DialogueId = 51105938,
          GUID = "7FF037F4",
          NextDialogue = 51105939,
          SpeakNpcId = 100001,
          Subtitle = "Look at you — all hesitation and no resolve. How are you supposed to learn anything formidable like this? By whining?"
        },
        [51105939] = {
          ContentFR = "J’avais songé à t’accorder quelques enseignements, par égard pour ta sincérité. Mais ta volonté... est bien trop ordinaire.",
          DialogueId = 51105939,
          GUID = "7FF0381E",
          NextDialogue = 51105940,
          SpeakNpcId = 100001,
          Subtitle = "I was ready to make an exception and give you a little guidance because you seemed sincere — but your willpower is disappointingly mediocre."
        },
        [51105940] = {
          ContentFR = "... Vous avez raison, Maître. Je n’aurais pas dû craindre la difficulté. Je pars m’entraîner dans la montagne sur-le-champ !",
          DialogueId = 51105940,
          GUID = "7FF03848",
          NextDialogue = 51105950,
          SpeakNpcId = 701005,
          Subtitle = "...You're right, master. I shouldn't shy away just because it's difficult. I'll head into the mountains and start training right now!",
          TalkActionId = {
            [1] = "701005:Talk02_End"
          }
        },
        [51105941] = {
          ContentFR = "<I>Il est temps de le ramener à la réalité.</>",
          DialogueId = 51105941,
          FailDialogue = 51105942,
          GUID = "7FF03872",
          ImprCheckId = 1116,
          NextDialogue = 51105943,
          Subtitle = "Time to drag him back to reality."
        },
        [51105942] = {
          ContentFR = "<I>Briser un rêve est toujours douloureux... mieux vaut lui laisser encore un peu de temps.</>",
          DialogueId = 51105942,
          GUID = "7FF0389C",
          SpeakNpcId = 100001,
          Subtitle = "(Shattering someone's dream is always rough... better ease into it.)"
        },
        [51105943] = {
          ContentFR = "Je pense que ton maître avait raison.",
          DialogueId = 51105943,
          GUID = "7FF038C6",
          NextDialogue = 51105944,
          SpeakNpcId = 100001,
          Subtitle = "I think your shifu had a point."
        },
        [51105944] = {
          ContentFR = "Pardon ? Que voulez-vous dire, Maître ?",
          DialogueId = 51105944,
          GUID = "7FF038F0",
          NextDialogue = 51105945,
          SpeakNpcId = 701005,
          Subtitle = "Huh? Master, what do you mean...?",
          TalkActionId = {
            [1] = "701005:Talk02_Start"
          }
        },
        [51105945] = {
          ContentFR = "Si tu veux réellement progresser, il te faut travailler dur. Attendre qu’un miracle tombe du ciel ne mène nulle part.",
          DialogueId = 51105945,
          GUID = "7FF0391A",
          NextDialogue = 51105946,
          SpeakNpcId = 100001,
          Subtitle = "If you truly want to master great skills, you need real training. Sitting around waiting for miracles won't get you anywhere."
        },
        [51105946] = {
          ContentFR = "De plus, Huaxu interdit la violence. Même si tu maîtrisais mille techniques, où pourrais-tu les utiliser ? Si tu dépasses les limites, un Bi’an viendra te châtier.",
          DialogueId = 51105946,
          GUID = "7FF03944",
          NextDialogue = 51105947,
          SpeakNpcId = 100001,
          Subtitle = "Besides, Huaxu forbids violence. Even if you learned a whole arsenal of techniques, where would you use them? Push things too far and a Bi'an will show up to punish you."
        },
        [51105947] = {
          ContentFR = "Mieux vaut rendre cette bande dessinée à son propriétaire, expliquer le malentendu à ton maître, et te consacrer sérieusement à tes études. C’est la seule leçon que je puisse t’offrir.",
          DialogueId = 51105947,
          GUID = "7FF0396E",
          NextDialogue = 51105948,
          SpeakNpcId = 100001,
          Subtitle = "Channel that energy into studying instead. Return the comic, clear things up with your shifu, and focus on your lessons. That's as much guidance as I can offer."
        },
        [51105948] = {
          ContentFR = "C’est... exactement ce que mon maître m’a dit... Alors tout ce qui est écrit dans ce livre est vraiment faux ?",
          DialogueId = 51105948,
          GUID = "7FF03998",
          NextDialogue = 51105949,
          SpeakNpcId = 701005,
          Subtitle = "That's exactly what my shifu said... so everything in the book really is made up?",
          TalkActionId = {
            [1] = "701005:Talk02_End"
          }
        },
        [51105949] = {
          ContentFR = "M-mais... même si c’est le cas... ce n’était pas nécessaire d’être aussi dur...",
          DialogueId = 51105949,
          GUID = "7FF039C2",
          NextDialogue = 51105950,
          SpeakNpcId = 701005,
          Subtitle = "But... but even if that's true... did you have to say it that harshly...?"
        },
        [51105950] = {
          ContentFR = "Vous observez le jeune homme s’éloigner en courant, puis hochez la tête avec satisfaction. S’il devait un jour accomplir de grandes choses, il se souviendrait sans doute du mystérieux sage qui l’a éclairé dans ces montagnes.",
          DialogueId = 51105950,
          GUID = "7FF039EC",
          LookAt = {
            [1] = "701005:n(701005)"
          },
          NextDialogue = 51105951,
          Scripts = "MoveTo{ActorId{701005},TargetPoint{\"LinghuNing_Target\"},MoveSpeed{200},Visibility{\"Hide\"}}",
          Subtitle = "(You watch the young man run off and give a small, satisfied nod. If he ever becomes someone remarkable, he'll probably remember the \"master\" who set him straight in these mountains.)"
        },
        [51105951] = {
          ContentFR = "Comme d'habitude... fidèle à vous-même.",
          DialogueId = 51105951,
          GUID = "7FF03A16",
          Subtitle = "(In short... well done, you.)"
        },
        [51106000] = {
          ContentFR = "Continuons à chercher... Il doit bien y avoir quelque chose qui m’a échappé.",
          DialogueId = 51106000,
          GUID = "7FF04220",
          LookAt = {
            [1] = "701006:n(0)"
          },
          NextDialogue = 51106001,
          SpeakNpcId = 701006,
          Subtitle = "Keep looking... there must be something I've overlooked."
        },
        [51106001] = {
          ContentFR = "On dirait que vous cherchez quelque chose ?",
          DialogueId = 51106001,
          GUID = "7FF0424A",
          NextDialogue = 51106002,
          SpeakNpcId = 100001,
          Subtitle = "Are you searching for something?"
        },
        [51106002] = {
          ContentFR = "Hm ? Oh... je n’avais pas remarqué que quelqu’un était arrivé.",
          DialogueId = 51106002,
          GUID = "7FF04274",
          NextDialogue = 51106003,
          SpeakNpcId = 701006,
          Subtitle = "Hm? I didn't realise anyone else was nearby."
        },
        [51106003] = {
          ContentFR = "Mon {性别:ami|amie}, des Bi’an obscurs apparaissent fréquemment dans cette zone. Les voyageurs ordinaires feraient mieux de ne pas s’en approcher.",
          DialogueId = 51106003,
          GUID = "7FF0429E",
          NextDialogue = 51106004,
          SpeakNpcId = 701006,
          Subtitle = "Friend, Sable Bi'an appear in this area rather frequently. It's not a place ordinary travellers should approach without caution."
        },
        [51106004] = {
          ContentFR = "Merci pour l’avertissement. Je suis déjà {性别:venu|venue} ici, je pense pouvoir faire face à la situation.",
          DialogueId = 51106004,
          GUID = "7FF042C8",
          NextDialogue = 51106005,
          SpeakNpcId = 100001,
          Subtitle = "Thanks for the warning. I've been here before — I can take care of myself."
        },
        [51106005] = {
          ContentFR = "Et vous, alors ? Pourquoi prendre le risque de rôder dans un endroit pareil ?",
          DialogueId = 51106005,
          GUID = "7FF042F2",
          NextDialogue = 51106006,
          SpeakNpcId = 100001,
          Subtitle = "And you? Why take the risk of walking around here?"
        },
        [51106006] = {
          ContentFR = "Prospection, enquête, archéologie... appelez cela comme vous voulez. En résumé, je cherche à déterminer s’il reste ici quelque chose de valeur.",
          DialogueId = 51106006,
          GUID = "7FF0431C",
          NextDialogue = 51106007,
          SpeakNpcId = 701006,
          Subtitle = "Exploring, investigating, searching for archaeological clues... call it what you will. In essence, I'm examining whether anything of historical value remains here.",
          TalkActionId = {
            [1] = "701006:Talk01_Start"
          }
        },
        [51106007] = {
          ContentFR = "Quelque chose de valeur... Vous êtes venu chercher un trésor pour faire fortune ?",
          DialogueId = 51106007,
          GUID = "7FF04346",
          NextDialogue = 51106008,
          SpeakNpcId = 100001,
          Subtitle = "Something valuable? So you're treasure-hunting for money?"
        },
        [51106008] = {
          ContentFR = "Ha ha. Beaucoup en font effectivement leur gagne-pain, mais ne me confondez pas avec eux. Ce que je poursuis n’est pas l’argent, mais bien autre chose : l’information.",
          DialogueId = 51106008,
          GUID = "7FF04370",
          NextDialogue = 51106009,
          SpeakNpcId = 701006,
          Subtitle = "Haha. Many people do make a living that way, but please don't mistake me for one of them. I'm not seeking wealth. What I'm after is insight."
        },
        [51106009] = {
          ContentFR = "Qu’il s’agisse d’inscriptions fragmentaires ou de débris de mécanismes, ces vestiges peuvent sembler sans valeur aux yeux des autres. Pourtant, les informations qu’ils recèlent me permettent de comprendre ce qui s’est réellement produit ici.",
          DialogueId = 51106009,
          GUID = "7FF0439A",
          NextDialogue = 51106010,
          SpeakNpcId = 701006,
          Subtitle = "Fragments of old writings, components from ancient mechanisms... things others dismiss as worthless often contain hints. They help me piece together what might have taken place here.",
          TalkActionId = {
            [1] = "701006:Talk01_End"
          }
        },
        [51106010] = {
          ContentFR = "Dites-moi... connaissez-vous l’histoire de cet endroit ?",
          DialogueId = 51106010,
          GUID = "7FF043C4",
          NextOptions = {
            [1] = 51106011
          },
          RestartTag = 51106010,
          SpeakNpcId = 701006,
          Subtitle = "So, friend — do you know anything about the history of this place?"
        },
        [51106011] = {
          ContentFR = "<I>Ce qui s’est passé ici... il vous semble que quelqu’un vous en a déjà parlé.</>",
          DialogueId = 51106011,
          FailDialogue = 51106012,
          GUID = "7FF043EE",
          ImprCheckId = 1117,
          NextDialogue = 51106013,
          Subtitle = "(What happened here? You feel like someone mentioned it to you before.)"
        },
        [51106012] = {
          ContentFR = "À bien y réfléchir, l’histoire ancienne vous intéresse nettement moins que les trésors tangibles.",
          DialogueId = 51106012,
          GUID = "7FF04418",
          Subtitle = "(If you're being honest, ancient history interests you far less than any treasure you can actually pick up.)"
        },
        [51106013] = {
          ContentFR = "J’ai un vague souvenir... Ce lieu ne serait-il pas un ancien champ de bataille ? Il me semble que deux camps s’y sont affrontés, avec de nombreuses pertes. C’est pour cela que l’endroit devient sinistre la nuit, et qu’on y raconte toutes sortes d’histoires de fantômes...",
          DialogueId = 51106013,
          GUID = "7FF04442",
          NextDialogue = 51106014,
          SpeakNpcId = 100001,
          Subtitle = "I vaguely remember — this used to be a battlefield, right? Two groups fought here and a lot of people died. That's why it gets so creepy at night... and all those ghost-story rumours."
        },
        [51106014] = {
          ContentFR = "Exactement.",
          DialogueId = 51106014,
          GUID = "7FF0446C",
          NextDialogue = 51106015,
          SpeakNpcId = 701006,
          Subtitle = "Precisely.",
          TalkActionId = {
            [1] = "701006:Talk02_Start"
          }
        },
        [51106015] = {
          ContentFR = "Je ne m’attendais pas à ce qu’{性别:un étranger|une étrangère} connaisse le passé de ces terres. Soit votre mémoire est remarquable, soit vous nourrissez vous aussi un certain intérêt pour ces événements anciens. Voyez-vous... l’histoire exerce souvent une attraction silencieuse sur les gens.",
          DialogueId = 51106015,
          GUID = "7FF04496",
          NextDialogue = 51106016,
          SpeakNpcId = 701006,
          Subtitle = "I didn't expect an outlander to know anything about this place. Either your memory is impressive, or you have a genuine interest in these old events. See? People are drawn to history without even noticing it."
        },
        [51106016] = {
          ContentFR = "Alors, que s’est-il réellement passé ici ?",
          DialogueId = 51106016,
          GUID = "7FF044C0",
          NextDialogue = 51106017,
          SpeakNpcId = 100001,
          Subtitle = "So what actually happened here?"
        },
        [51106017] = {
          ContentFR = "Cet endroit est le théâtre de la Bataille de Shuli. Il y a plusieurs siècles, la Secte Jishu y déclencha une rébellion. La Secte Xuanheng mena une répression armée. Aucun survivant, d’un côté comme de l’autre.",
          DialogueId = 51106017,
          GUID = "7FF044EA",
          NextDialogue = 51106018,
          SpeakNpcId = 701006,
          Subtitle = "This is where the Battle of Shuli took place. Several centuries ago, the Jishu Sect rose in revolt here, and the Xuanheng Sect sent forces to suppress them. In the end, none of them survived."
        },
        [51106018] = {
          ContentFR = "Cette guerre a profondément marqué l’histoire de Huaxu et influencé de nombreuses décisions ultérieures... du moins, selon les archives officielles.",
          DialogueId = 51106018,
          GUID = "7FF04514",
          NextDialogue = 51106019,
          SpeakNpcId = 701006,
          Subtitle = "It left a considerable mark on Huaxu's history, influencing many decisions in the ages that followed — or so the official records state."
        },
        [51106019] = {
          ContentFR = "Ce qui est intéressant, en revanche, c’est que l’origine même du conflit y est souvent traitée de façon vague, expédiée en quelques lignes.",
          DialogueId = 51106019,
          GUID = "7FF0453E",
          NextOptions = {
            [1] = 51106020,
            [2] = 51106022
          },
          SpeakNpcId = 701006,
          Subtitle = "But the curious thing is that those records are rather vague about how it all began — almost as though something has been deliberately glossed over.",
          TalkActionId = {
            [1] = "701006:Talk02_End"
          }
        },
        [51106020] = {
          ContentFR = "<I>Vous voulez dire que les archives officielles ne disent pas toute la vérité ?</>",
          DialogueId = 51106020,
          GUID = "7FF04568",
          ImprPlusId = 1208,
          NextDialogue = 51106021,
          Subtitle = "So you think the official record isn't telling the whole truth?"
        },
        [51106021] = {
          ContentFR = "Ha ha ! Plutôt que de parler de doute, je préfère employer le terme d’« hypothèse ».",
          DialogueId = 51106021,
          GUID = "7FF04592",
          NextDialogue = 51106024,
          SpeakNpcId = 701006,
          Subtitle = "Hah! I wouldn't frame it as doubt — I'd call it a hypothesis."
        },
        [51106022] = {
          ContentFR = "<I>À trop en savoir, on finit réduit au silence. C’est comme ça dans les romans.</>",
          DialogueId = 51106022,
          GUID = "7FF045BC",
          ImprPlusId = 1210,
          NextDialogue = 51106023,
          Subtitle = "Dig too deeply and you'll get silenced — that's how these stories usually go."
        },
        [51106023] = {
          ContentFR = "Ha ha ! Vous plaisantez. Sous l’autorité des Neuf Chapitres de Dafeng, nul n’a à craindre ce genre de choses à Huaxu. Les Bi’an et les Magistrats de Yingtian veillent à ma sécurité.",
          DialogueId = 51106023,
          GUID = "7FF045E6",
          NextDialogue = 51106024,
          SpeakNpcId = 701006,
          Subtitle = "Haha. You jest. Under the Nine Chapters of Dafeng, no one in Huaxu has to worry about matters like that — the Bi'an and the Magistrates of Yingtian will see to my safety.",
          TalkActionId = {
            [1] = "701006:Explain01_Start"
          }
        },
        [51106024] = {
          ContentFR = "Cela dit... si la vérité se résumait toujours à ce que racontent les livres, elle ne serait guère aussi fascinante.",
          DialogueId = 51106024,
          GUID = "7FF04610",
          NextDialogue = 51106025,
          SpeakNpcId = 701006,
          Subtitle = "Even so, if the truth really were just what the official records claim, it wouldn't be nearly as intriguing."
        },
        [51106025] = {
          ContentFR = "L’histoire ne montre souvent que ce qu’elle consent à révéler. Avec le temps, la vérité se déforme, façonnée selon ce qui sert le mieux ceux qui l’écrivent.",
          DialogueId = 51106025,
          GUID = "7FF0463A",
          NextDialogue = 51106026,
          SpeakNpcId = 701006,
          Subtitle = "History shows only what it chooses to. Over time, the truth becomes distorted — shaped to serve the interests of whoever is recording it."
        },
        [51106026] = {
          ContentFR = "C’est pourquoi je préfère user d’un soupçon d’imagination, aussi modeste soit-il, afin de redessiner ce que l’histoire aurait pu être. Dites-moi, mon {性别:ami|amie}... quelles autres possibilités voyez-vous pour cette guerre ?",
          DialogueId = 51106026,
          GUID = "7FF04664",
          NextOptions = {
            [1] = 51106027,
            [2] = 51106029,
            [3] = 51106031
          },
          SpeakNpcId = 701006,
          Subtitle = "So I prefer to take what little imagination I have and picture how events might actually have unfolded. Tell me, friend — what possibilities do you think there are?",
          TalkActionId = {
            [1] = "701006:Explain01_End"
          }
        },
        [51106027] = {
          ContentFR = "<I>Je préfère faire confiance aux autres, tant qu’aucune preuve ne démontre qu’ils ont tort.</>",
          DialogueId = 51106027,
          GUID = "7FF0468E",
          ImprPlusId = 1207,
          NextDialogue = 51106028,
          Subtitle = "I'd sooner trust the records — unless there's clear evidence they're wrong."
        },
        [51106028] = {
          ContentFR = "Une posture prudente. Elle a le mérite de limiter les erreurs.",
          DialogueId = 51106028,
          GUID = "7FF046B8",
          NextDialogue = 51106033,
          SpeakNpcId = 701006,
          Subtitle = "A prudent and measured stance."
        },
        [51106029] = {
          ContentFR = "<I>Qui dit hypothèse audacieuse dit supposition inverse. Ce serait donc la Secte Xuanheng qui aurait frappé la première.</>",
          DialogueId = 51106029,
          GUID = "7FF046E2",
          ImprPlusId = 1206,
          NextDialogue = 51106030,
          Subtitle = "If we're making bold guesses... I'd say Xuanheng started it."
        },
        [51106030] = {
          ContentFR = "Heh... certains érudits friands de théories alternatives partagent effectivement cet avis.",
          DialogueId = 51106030,
          GUID = "7FF0470C",
          NextDialogue = 51106033,
          SpeakNpcId = 701006,
          Subtitle = "Heh... there are scholars with a conspiratorial bent who think along those lines."
        },
        [51106031] = {
          ContentFR = "<I>Ce sont des extraterrestres déguisés en humains qui ont tout déclenché !</>",
          DialogueId = 51106031,
          GUID = "7FF04736",
          ImprPlusId = 1210,
          NextDialogue = 51106032,
          Subtitle = "It was aliens disguised as humans who started it!"
        },
        [51106032] = {
          ContentFR = "Ha ha ! Voilà qui reste une hypothèse comme une autre.",
          DialogueId = 51106032,
          GUID = "7FF04760",
          NextDialogue = 51106033,
          SpeakNpcId = 701006,
          Subtitle = "Hah! Well, that's a possibility too."
        },
        [51106033] = {
          ContentFR = "Mais les conjectures ne sont que la première étape. Pour lever le voile sur l’histoire, il faut ensuite passer à la seconde : la preuve.",
          DialogueId = 51106033,
          GUID = "7FF0478A",
          NextDialogue = 51106034,
          SpeakNpcId = 701006,
          Subtitle = "But speculation is only the first step. To lift the veil, you need the second step — evidence.",
          TalkActionId = {
            [1] = "701006:Think_Start"
          }
        },
        [51106034] = {
          ContentFR = "Afin de vérifier mes hypothèses, j’ai intégré le Bureau des Travaux, dans l’espoir de mieux comprendre le fonctionnement des méchapoupées. C’est ainsi que j’ai pu accéder à davantage d’informations sur cette période.",
          DialogueId = 51106034,
          GUID = "7FF047B4",
          NextDialogue = 51106035,
          SpeakNpcId = 701006,
          Subtitle = "To test my hypothesis, I joined the Ministry of Works. It allowed me to gain a deeper understanding of how the mechapuppets function and to learn more about what truly happened back then."
        },
        [51106035] = {
          ContentFR = "Lorsque j’ai exposé mes intentions à mes maîtres, ils ne se sont pas fâchés. Ils ont même déclaré que la Secte Jishu manquait cruellement de jeunes gens comme moi... et m’ont retenu sans autre forme de procès.",
          DialogueId = 51106035,
          GUID = "7FF047DE",
          NextDialogue = 51106036,
          SpeakNpcId = 701006,
          Subtitle = "The masters there didn't take offence when I told them my intentions. Instead, they said the Jishu Sect is short on young people like me these days — and so they simply kept me.",
          TalkActionId = {
            [1] = "701006:Think_End"
          }
        },
        [51106036] = {
          ContentFR = "Tout cela, simplement pour comprendre l’histoire ?",
          DialogueId = 51106036,
          GUID = "7FF04808",
          NextDialogue = 51106037,
          SpeakNpcId = 100001,
          Subtitle = "You've done all this just to study the past?"
        },
        [51106037] = {
          ContentFR = "Je ne saurais dire quelle en est la véritable finalité. Mais une fois lancé, il m’est devenu impossible de m’arrêter. Les indices se répondent, s’entrecroisent... peut-être mèneront-ils à une vérité, peut-être pas. Quoi qu’il en soit, ma curiosité ne me laisse aucun répit.",
          DialogueId = 51106037,
          GUID = "7FF04832",
          NextDialogue = 51106038,
          SpeakNpcId = 701006,
          Subtitle = "I can't say what any of it will ultimately amount to, but once I began, I simply couldn't stop. Different clues link together in ways you wouldn't expect. Perhaps they'll lead to the truth, perhaps not — but my curiosity won't let me ignore them.",
          TalkActionId = {
            [1] = "701006:Explain01_Start"
          }
        },
        [51106038] = {
          ContentFR = "Bien. Je vais reprendre ma recherche d’informations. Cette conversation fut fort agréable.",
          DialogueId = 51106038,
          GUID = "7FF0485C",
          NextDialogue = 51106039,
          SpeakNpcId = 701006,
          Subtitle = "Well then, I should get back to searching for clues. It was a pleasure speaking with you."
        },
        [51106039] = {
          ContentFR = "Je compte rester dans les environs encore un bon moment. Si vous découvrez quoi que ce soit, n’hésitez pas à venir m’en informer.",
          DialogueId = 51106039,
          GUID = "7FF04886",
          SpeakNpcId = 701006,
          Subtitle = "I'll be staying in this area for a good while. If you come across anything, do let me know.",
          TalkActionId = {
            [1] = "701006:Explain01_End"
          }
        },
        [51106040] = {
          ContentFR = "Ah, c’est vous. Avez-vous fait de nouvelles découvertes ?",
          DialogueId = 51106040,
          GUID = "7FF048B0",
          LookAt = {
            [1] = "701006:n(0)"
          },
          SpeakNpcId = 701006,
          Subtitle = "Ah, it's you. Have you discovered anything new?"
        },
        [51107000] = {
          ContentFR = "Ce pot de sucre d’orge... son goût... j’aimerais savoir.",
          DialogueId = 51107000,
          GUID = "7FF0E630",
          NextDialogue = 51107001,
          SpeakNpcId = 701007,
          Subtitle = "That jar... the barley sugar inside... I'm... curious about the taste."
        },
        [51107001] = {
          ContentFR = "Le regard du Wishen est perdu au loin. Il ne semble pas avoir conscience de votre présence.",
          DialogueId = 51107001,
          GUID = "7FF0E65A",
          NextOptions = {
            [1] = 51107002,
            [2] = 51107006
          },
          Subtitle = "(The Wishen stares into the distance, unaware that you're standing nearby.)"
        },
        [51107002] = {
          ContentFR = "<I>Partir discrètement</>",
          DialogueId = 51107002,
          GUID = "7FF0E684",
          ImprPlusId = 1206,
          NextDialogue = 51107003,
          Subtitle = "Leave quietly"
        },
        [51107003] = {
          ContentFR = "Le bruit de vos pas attire sans doute son attention. Lentement, il dérive jusqu’à vous et vous salue.",
          DialogueId = 51107003,
          GUID = "7FF0E6AE",
          NextDialogue = 51107004,
          Subtitle = "(Perhaps the sound of your footsteps catches its attention. It drifts towards you and offers a greeting.)"
        },
        [51107004] = {
          ContentFR = "Bonjour... {性别:étranger|étrangère}.",
          DialogueId = 51107004,
          GUID = "7FF0E6D8",
          NextDialogue = 51107005,
          SpeakNpcId = 701007,
          Subtitle = "Hello... stranger."
        },
        [51107005] = {
          ContentFR = "Euh... bonjour. Je ne voulais pas te déranger...",
          DialogueId = 51107005,
          GUID = "7FF0E702",
          NextDialogue = 51107009,
          SpeakNpcId = 100001,
          Subtitle = "Uh... hello. I didn't mean to disturb you..."
        },
        [51107006] = {
          ContentFR = "<I>S’approcher et lui parler</>",
          DialogueId = 51107006,
          GUID = "7FF0E72C",
          ImprPlusId = 1209,
          NextDialogue = 51107007,
          Subtitle = "Approach and speak"
        },
        [51107007] = {
          ContentFR = "Bonjour... ?",
          DialogueId = 51107007,
          GUID = "7FF0E756",
          NextDialogue = 51107008,
          SpeakNpcId = 100001,
          Subtitle = "Hello?"
        },
        [51107008] = {
          ContentFR = "Ah... vous m’avez surpris. J’étais... en train de penser. Je n’avais pas remarqué.",
          DialogueId = 51107008,
          GUID = "7FF0E780",
          NextDialogue = 51107009,
          SpeakNpcId = 701007,
          Subtitle = "Ah... you startled me... I was lost in thought... didn't notice."
        },
        [51107009] = {
          ContentFR = "Vous pouvez me voir ? C’est rare... Je suis... heureux.",
          DialogueId = 51107009,
          GUID = "7FF0E7AA",
          NextDialogue = 51107010,
          SpeakNpcId = 701007,
          Subtitle = "You... can see me? That's rare... makes me happy."
        },
        [51107010] = {
          ContentFR = "Je veux parler... avec tout le monde. S’il vous plaît... aidez-moi. Ils ne me voient pas... c’est triste.",
          DialogueId = 51107010,
          GUID = "7FF0E7D4",
          NextDialogue = 51107011,
          SpeakNpcId = 701007,
          Subtitle = "I want to talk... To everyone. Please... help me. They can't see me... feels lonely."
        },
        [51107011] = {
          ContentFR = "Tu as besoin de l’aide de quelqu’un ? Peut-être que je peux faire quelque chose pour toi.",
          DialogueId = 51107011,
          GUID = "7FF0E7FE",
          NextDialogue = 51107012,
          SpeakNpcId = 100001,
          Subtitle = "You need help with something? Maybe I can."
        },
        [51107012] = {
          ContentFR = "Vous êtes une bonne personne. Merci. Au marché... le sucre d’orge... je suis curieux de son goût. J’aimerais en manger.",
          DialogueId = 51107012,
          GUID = "7FF0E828",
          NextOptions = {
            [1] = 51107013
          },
          RestartTag = 51107012,
          SpeakNpcId = 701007,
          Subtitle = "You're kind. Thank you. At the market... the barley sugar... curious about the taste."
        },
        [51107013] = {
          ContentFR = "Vous vous souvenez qu’il vous reste quelques morceaux de sucre d’orge dans votre sac. Peut-être pourriez-vous lui en offrir.",
          DialogueId = 51107013,
          FailDialogue = 51107014,
          GUID = "7FF0E852",
          ImprCheckId = 1118,
          NextDialogue = 51107015,
          Subtitle = "You recall that you still have a few pieces of barley sugar in your pack. You could share one with it."
        },
        [51107014] = {
          ContentFR = "Vous décidez finalement de garder le sucre pour vous. Après tout, difficile de résister à une douceur pareille.",
          DialogueId = 51107014,
          GUID = "7FF0E87C",
          Subtitle = "(You decide to keep the barley sugar for yourself — a bit of sweetness is hard to part with.)"
        },
        [51107015] = {
          ContentFR = "Il m’en reste justement un peu. Tu veux goûter ?",
          DialogueId = 51107015,
          GUID = "7FF0E8A6",
          NextDialogue = 51107016,
          SpeakNpcId = 100001,
          Subtitle = "I've got a few with me — would you like to try one?"
        },
        [51107016] = {
          ContentFR = "Oh... vraiment ? Merci... merci beaucoup...",
          DialogueId = 51107016,
          GUID = "7FF0E8D0",
          NextDialogue = 51107017,
          SpeakNpcId = 701007,
          Subtitle = "Wow... Thank you... truly..."
        },
        [51107017] = {
          ContentFR = "Le Wishen accepte la friandise avec une infinie précaution et la porte à l’endroit où se trouvait autrefois sa bouche —",
          DialogueId = 51107017,
          GUID = "7FF0E8FA",
          NextDialogue = 51107018,
          Subtitle = "(The Wishen accepts the sweet with a gentle, careful motion and lifts it towards what might once have been its mouth.)"
        },
        [51107018] = {
          ContentFR = "Son corps, semblable à un mirage, peine à être qualifié de forme vivante. Vous ignorez s’il possède encore une bouche... peut-être ne fait-il que reproduire un geste gravé dans sa mémoire.",
          DialogueId = 51107018,
          GUID = "7FF0E924",
          NextDialogue = 51107019,
          Subtitle = "(Its mirage-like form can hardly be called a body. You can't tell whether this gesture counts as eating — perhaps it's simply copying something it remembers from when it was alive.)"
        },
        [51107019] = {
          ContentFR = "Comme on pouvait s’y attendre, le sucre traverse son corps et tombe dans la poussière, emportant avec lui la faible lueur d’espoir qui venait de naître.",
          DialogueId = 51107019,
          GUID = "7FF0E94E",
          NextDialogue = 51107020,
          Subtitle = "(As expected, the sweet slips straight through its form and falls into the dust below, taking with it the faint flicker of hope you saw a moment ago.)"
        },
        [51107020] = {
          ContentFR = "Manger... impossible. Goût... absent. Je suis... triste...",
          DialogueId = 51107020,
          GUID = "7FF0E978",
          NextOptions = {
            [1] = 51107021
          },
          SpeakNpcId = 701007,
          Subtitle = "Can't eat... can't taste... it feels sad..."
        },
        [51107021] = {
          ContentFR = "<I>Essayer de lui décrire le goût du sucre d’orge</>",
          DialogueId = 51107021,
          GUID = "7FF0E9A2",
          ImprPlusId = 1208,
          NextDialogue = 51107022,
          Subtitle = "Describe the taste of barley sugar for the Wishen."
        },
        [51107022] = {
          ContentFR = "Quand on le met en bouche, il est d’abord tendre. Puis, en le mâchant, il devient élastique. La douceur se répand lentement, suivie d’un parfum léger, comme celui du grain mûr.",
          DialogueId = 51107022,
          GUID = "7FF0E9CC",
          NextDialogue = 51107023,
          SpeakNpcId = 100001,
          Subtitle = "It feels soft at first, but becomes chewy when you bite into it. As the sweetness melts, there's a light, grain-like aroma that follows."
        },
        [51107023] = {
          ContentFR = "Ce n’est pas un sucre agressif. Sa saveur est douce, discrète... Un peu comme marcher au bord des rizières, à l’approche de l’automne. Le vent fait frémir les épis, et apporte avec lui l’odeur de la terre.",
          DialogueId = 51107023,
          GUID = "7FF0E9F6",
          NextDialogue = 51107024,
          SpeakNpcId = 100001,
          Subtitle = "It's not as heavy or sugary as other sweets. It tastes gentle — like standing beside rice fields in early autumn, with the wind brushing through the stalks and carrying a faint scent of earth."
        },
        [51107024] = {
          ContentFR = "Je... ne comprends pas le goût. Mais... ça a l’air... apaisant. Alors... c’est bon ?",
          DialogueId = 51107024,
          GUID = "7FF0EA20",
          NextDialogue = 51107025,
          SpeakNpcId = 701007,
          Subtitle = "I don't understand... But it sounds... nice. So... it's good?"
        },
        [51107025] = {
          ContentFR = "Oui. C’est un goût très agréable.",
          DialogueId = 51107025,
          GUID = "7FF0EA4A",
          NextDialogue = 51107026,
          SpeakNpcId = 100001,
          Subtitle = "Yeah. It's a lovely taste."
        },
        [51107026] = {
          ContentFR = "Mes souvenirs... sont flous. Quand j’étais enfant... les autres mangeaient des sucreries. Ils riaient. Moi aussi, j’en voulais... mais je n’avais pas d’argent.",
          DialogueId = 51107026,
          GUID = "7FF0EA74",
          NextDialogue = 51107027,
          SpeakNpcId = 701007,
          Subtitle = "My memories... blurry. When I was little, the other children ate sweets... and laughed. I wanted one too... but I had no money."
        },
        [51107027] = {
          ContentFR = "En grandissant... le travail, la famille... plus de temps. Je me disais toujours : « la prochaine fois ».",
          DialogueId = 51107027,
          GUID = "7FF0EA9E",
          NextDialogue = 51107028,
          SpeakNpcId = 701007,
          Subtitle = "When I grew up, there was work... a family to care for... no time. I kept thinking, \"next time... next time\"."
        },
        [51107028] = {
          ContentFR = "Quand je suis devenu vieux... mes dents sont tombées. Je ne pouvais plus manger de sucre... Je ne pouvais qu’en acheter pour les enfants.",
          DialogueId = 51107028,
          GUID = "7FF0EAC8",
          NextDialogue = 51107029,
          SpeakNpcId = 701007,
          Subtitle = "When I got old, my teeth were gone... I couldn't eat sweets anymore... I could only buy them for the children."
        },
        [51107029] = {
          ContentFR = "J’en avais envie, mais... chacun avait ses devoirs. Je ne pouvais pas être égoïste... Les bonbons, pour les enfants. Les adultes... devaient travailler.",
          DialogueId = 51107029,
          GUID = "7FF0EAF2",
          NextDialogue = 51107030,
          SpeakNpcId = 701007,
          Subtitle = "I wanted to try them... but everyone had duties. I couldn't be selfish... Sweets were for children... grown-ups had to work... keep going."
        },
        [51107030] = {
          ContentFR = "Mais à la fin... je n’ai jamais oublié. Toujours curieux... de ce goût.",
          DialogueId = 51107030,
          GUID = "7FF0EB1C",
          NextDialogue = 51107031,
          SpeakNpcId = 701007,
          Subtitle = "But even then... I never forgot. Still curious... what it tasted like."
        },
        [51107031] = {
          ContentFR = "Tout le monde en mangeait... et souriait. Ça doit être... un goût qui rend heureux...",
          DialogueId = 51107031,
          GUID = "7FF0EB46",
          NextDialogue = 51107032,
          SpeakNpcId = 701007,
          Subtitle = "Everyone ate them... and smiled. It must be a taste... that makes people happy..."
        },
        [51107032] = {
          ContentFR = "Tu n’avais pas à tout porter seul. Si tu avais voulu en manger, tu aurais pu. Personne ne t’en aurait voulu.",
          DialogueId = 51107032,
          GUID = "7FF0EB70",
          NextDialogue = 51107033,
          SpeakNpcId = 100001,
          Subtitle = "You didn't have to shoulder everything alone. If you wanted a sweet, you could've just had one. No one would've blamed you."
        },
        [51107033] = {
          ContentFR = "Vraiment... ? C’était... permis ?",
          DialogueId = 51107033,
          GUID = "7FF0EB9A",
          NextDialogue = 51107034,
          SpeakNpcId = 701007,
          Subtitle = "I... could? I was... allowed?"
        },
        [51107034] = {
          ContentFR = "Bien sûr. Ce n’était qu’un petit sucre. Si même ce bonheur infime était interdit... alors ce monde aurait été bien cruel.",
          DialogueId = 51107034,
          GUID = "7FF0EBC4",
          NextDialogue = 51107035,
          SpeakNpcId = 100001,
          Subtitle = "Of course. It's just a tiny treat. If even that little bit of happiness isn't allowed... that'd be far too cruel."
        },
        [51107035] = {
          ContentFR = "Il ne dit plus rien. Un désir longtemps étouffé, né au cours d’une vie entière, tremble doucement devant vous.",
          DialogueId = 51107035,
          GUID = "7FF0EBEE",
          NextDialogue = 51107036,
          Subtitle = "(The Wishen falls silent. A lifetime of quiet longing seems to tremble faintly within its fading form.)"
        },
        [51107036] = {
          ContentFR = "Des émotions oubliées refont surface, lentement. Vous savez pourtant que cet instant ne durera pas.",
          DialogueId = 51107036,
          GUID = "7FF0EC18",
          NextDialogue = 51107037,
          Subtitle = "(Feelings long forgotten drift back to it for a moment, though you know they won't stay.)"
        },
        [51107037] = {
          ContentFR = "Le corps du Wishen ondule faiblement, devenant peu à peu plus transparent.",
          DialogueId = 51107037,
          GUID = "7FF0EC42",
          NextDialogue = 51107038,
          Subtitle = "(Its outline ripples gently, turning a little more transparent.)"
        },
        [51107038] = {
          ContentFR = "S’il existe une autre vie... puisse cet inconnu y goûter enfin le sucre qui lui revenait.",
          DialogueId = 51107038,
          GUID = "7FF0EC6C",
          Subtitle = "(If another life awaits it... may it finally taste a piece of sweetness of its own.)"
        },
        [51108000] = {
          ContentFR = "À votre allure, on dirait bien que vous êtes {性别:un étranger|une étrangère}. Bonjour, je m’appelle Ramon.",
          DialogueId = 51108000,
          GUID = "7FF18A40",
          LookAt = {
            [1] = "701008:n(0)"
          },
          NextDialogue = 51108001,
          SpeakNpcId = 701008,
          Subtitle = "Hey there — I'm Ramon. You don't look local.",
          TalkActionId = {
            [1] = "701008:Talk01_Start"
          }
        },
        [51108001] = {
          ContentFR = "Un homme d’une amabilité presque excessive vous interpelle. Après avoir jeté un coup d’œil autour de vous, vous réalisez qu’en parlant d’« {性别:étranger|étrangère} », il s’adresse bien à vous.",
          DialogueId = 51108001,
          GUID = "7FF18A6A",
          NextDialogue = 51108002,
