          NextDialogue = 51108018,
          SpeakNpcId = 701008,
          Subtitle = "No need to be that wary. With the Nine Chapters of Dafeng watching over Huaxu, I couldn't harm you even if I wanted to."
        },
        [51108018] = {
          ContentFR = "Quant à la raison... ha ha, il suffit de me regarder : comme vous, je suis un étranger. Je viens d’Aethyrie. Ce nom vous dit quelque chose ?",
          DialogueId = 51108018,
          GUID = "7FF18D34",
          NextOptions = {
            [1] = 51108019,
            [2] = 51108022
          },
          SpeakNpcId = 701008,
          Subtitle = "And as for why I'm offering to help... well, look at me — I'm a foreigner too, just like you. I'm from Aethyrie. Heard of it?",
          TalkActionId = {
            [1] = "701008:Talk01_End"
