        },
        [51109009] = {
          ContentFR = "Oui... Alors, quand un enfant devient Bi’an, tout le monde considère cela comme un immense honneur.",
          DialogueId = 51109009,
          GUID = "7FF22FCA",
          NextDialogue = 51109010,
          SpeakNpcId = 701009,
          Subtitle = "Aye. So when someone becomes one, it's something their parents should be proud of.",
          TalkActionId = {
            [1] = "701009:Talk01_Start"
          }
        },
        [51109010] = {
          ContentFR = "Chez nous, l’aîné a suivi cette voie. Les voisins sont venus nous féliciter, et mon épouse comme moi en étions très fiers.",
          DialogueId = 51109010,
          GUID = "7FF22FF4",
          NextDialogue = 51109011,
          SpeakNpcId = 701009,
          Subtitle = "Our firstborn became one. The neighbours all came round to congratulate us, and the missus and I were proud as anything."
        },
        [51109011] = {
          ContentFR = "Mais qui aurait cru que, passé son rite de majorité, notre second fils deviendrait lui aussi un Bi’an ?",
          DialogueId = 51109011,
          GUID = "7FF2301E",
          NextDialogue = 51109012,
          SpeakNpcId = 701009,
          Subtitle = "But who'd have thought that when our second lad came of age, he'd become a Bi'an as well."
        },
        [51109012] = {
          ContentFR = "Deux Bi’an dans une même famille... Les gens nous enviaient, et lors du banquet, nous avions le sourire jusqu’aux oreilles.",
          DialogueId = 51109012,
          GUID = "7FF23048",
          NextDialogue = 51109013,
          SpeakNpcId = 701009,
          Subtitle = "Two Bi'an from the same household... folk were full of envy, and we were smiling all through the celebration.",
          TalkActionId = {
            [1] = "701009:Talk01_End"
          }
        },
        [51109013] = {
          ContentFR = "Mais une fois rentrés à la maison... En voyant leurs chambres vides, il ne restait plus qu’un sentiment : le silence. Un silence assourdissant...",
          DialogueId = 51109013,
          GUID = "7FF23072",
          NextDialogue = 51109014,
          SpeakNpcId = 701010,
          Subtitle = "But once we came home and saw their rooms standing empty... there was only one thing I could feel — the place was just too quiet...",
          TalkActionId = {
            [1] = "701010:Explain01_Start"
          }
        },
        [51109014] = {
          ContentFR = "Parfois, allongé dans la cour, il me semble encore les entendre : « Papa, ne somnole pas devant la porte. Maman t’appelle pour manger. »",
          DialogueId = 51109014,
          GUID = "7FF2309C",
          NextDialogue = 51109015,
          SpeakNpcId = 701009,
          Subtitle = "Sometimes, when I'm lying out in the yard, I can almost hear the boys again... telling me not to nod off by the door, saying their mother's calling me in for dinner.",
          TalkActionId = {
            [1] = "701010:Explain01_End"
          }
        },
        [51109015] = {
          ContentFR = "Puis je me relève... et il n’y a personne. Seulement les cheveux de mon épouse, chaque jour un peu plus blancs... et son dos, chaque jour un peu plus voûté.",
          DialogueId = 51109015,
          GUID = "7FF230C6",
          NextDialogue = 51109016,
          SpeakNpcId = 701009,
          Subtitle = "But when I get up, there's no one there. All I see is my wife's hair growing greyer by the day... and her eyes dimming with the years.",
          TalkActionId = {
            [1] = "701009:Talk02_Start"
          }
        },
        [51109016] = {
          ContentFR = "Notre seul réconfort, à l’époque, c’était le plus jeune... notre troisième fils.",
          DialogueId = 51109016,
          GUID = "7FF230F0",
          NextDialogue = 51109017,
          SpeakNpcId = 701009,
          Subtitle = "In those days, our only comfort was our youngest — our third son."
        },
        [51109017] = {
          ContentFR = "Il voyait bien notre peine. Alors un jour, il aidait sa mère à ranger la maison ; le lendemain, il sortait marcher avec moi. Grâce à lui, ce foyer trop silencieux retrouvait un peu de chaleur.",
          DialogueId = 51109017,
          GUID = "7FF2311A",
          NextDialogue = 51109018,
          SpeakNpcId = 701009,
          Subtitle = "He knew how much we missed his brothers, so he'd go out of his way to make things easier for us — help his mother tidy the house, take a walk with me, little things like that. He's the only reason this cold, quiet shack ever felt like a home again."
        },
        [51109018] = {
          ContentFR = "Avec lui, la vie restait supportable. Peu à peu, nous avons accepté que nos deux aînés ne reviendraient jamais.",
          DialogueId = 51109018,
          GUID = "7FF23144",
          NextDialogue = 51109019,
          SpeakNpcId = 701009,
          Subtitle = "With him around, we could still carry on. Bit by bit, we made our peace with the fact that the older two were never coming back.",
          TalkActionId = {
            [1] = "701009:Talk02_End"
          }
        },
        [51109019] = {
          ContentFR = "Mais voilà que cette maudite « bonne nouvelle » a de nouveau frappé notre famille !",
          DialogueId = 51109019,
          GUID = "7FF2316E",
          NextDialogue = 51109020,
          SpeakNpcId = 701010,
          Subtitle = "But then that cursed \"good news\" came to this house again!",
          TalkActionId = {
            [1] = "701010:Talk01_Start"
          }
        },
        [51109020] = {
          ContentFR = "Qui peut nous dire quel crime nous avons commis... pour que notre dernier enfant nous soit, lui aussi, arraché ?",
          DialogueId = 51109020,
          GUID = "7FF23198",
          NextDialogue = 51109021,
          SpeakNpcId = 701010,
          Subtitle = "What have we done to deserve this... that even our last child must be taken from us..."
        },
        [51109021] = {
          ContentFR = "Il y a un mois... notre troisième fils est devenu un Bi’an...",
          DialogueId = 51109021,
          GUID = "7FF231C2",
          NextDialogue = 51109022,
          SpeakNpcId = 701010,
          Subtitle = "A month ago, our third became a Bi'an as well...",
          TalkActionId = {
            [1] = "701010:Talk01_End"
          }
        },
        [51109022] = {
          ContentFR = "Nous savons... Devenir Bi’an est censé être un immense honneur... Mais face à cette gloire que l’on ne peut ni voir ni toucher, ce que nous désirions vraiment, c’était une maison ordinaire... vivante... remplie de rires...",
          DialogueId = 51109022,
          GUID = "7FF231EC",
          NextDialogue = 51109023,
          SpeakNpcId = 701009,
          Subtitle = "We know... becoming a Bi'an is meant to be an honour... but if we had a choice, we'd rather have our sons here with us...",
          TalkActionId = {
            [1] = "701009:Sigh_Start"
          }
        },
        [51109023] = {
          ContentFR = "À ces mots, le vieil homme ne parvient plus à retenir ses larmes et se couvre le visage en sanglotant.",
          DialogueId = 51109023,
          GUID = "7FF23216",
          NextDialogue = 51109024,
          Subtitle = "(At that, the old man can't hold it in any longer. He covers his face with one hand and weeps.)"
        },
        [51109024] = {
          ContentFR = "Pardonnez-moi... Vous montrer une telle faiblesse... ce n’est pas digne...",
          DialogueId = 51109024,
          GUID = "7FF23240",
          NextDialogue = 51109025,
          SpeakNpcId = 701009,
          Subtitle = "Sorry, youngster... letting you see an old man cry like a child...",
          TalkActionId = {
            [1] = "701009:Sigh_End"
          }
        },
        [51109025] = {
          ContentFR = "Ce n’est rien. Pleurer permet parfois de libérer ce que l’on garde trop longtemps en soi.",
          DialogueId = 51109025,
          GUID = "7FF2326A",
          NextDialogue = 51109026,
          SpeakNpcId = 100001,
          Subtitle = "It's all right. Letting it out helps."
        },
        [51109026] = {
          ContentFR = "Merci... vraiment. Après avoir pleuré, je me sens un peu plus léger.",
          DialogueId = 51109026,
          GUID = "7FF23294",
          NextDialogue = 51109027,
          SpeakNpcId = 701009,
          Subtitle = "Thank you... truly. I do feel a bit steadier now."
        },
        [51109027] = {
          ContentFR = "Le vieil homme essuie ses larmes et relève vers vous un regard las.",
          DialogueId = 51109027,
          GUID = "7FF232BE",
          NextDialogue = 51109028,
          Subtitle = "(He wipes his face and looks up at you, eyes worn and tired.)"
        },
        [51109028] = {
          ContentFR = "Navré de vous avoir retenu avec les lamentations de deux vieux. Allez donc vaquer à vos affaires. Je vais emmener mon épouse faire quelques pas... changer d’air.",
          DialogueId = 51109028,
          GUID = "7FF232E8",
          NextDialogue = 51109029,
          SpeakNpcId = 701009,
          Subtitle = "Thank you so much for listening, kiddo. We won't keep you any longer. I'll take the missus out for a little walk... might do her some good."
        },
        [51109029] = {
          ContentFR = "... Très bien.",
          DialogueId = 51109029,
          GUID = "7FF23312",
          NextDialogue = 51109030,
          SpeakNpcId = 100001,
          Subtitle = "Okay..."
        },
        [51109030] = {
          ContentFR = "Le Vieux Cheng soutient Madame Cheng tandis qu’ils s’éloignent ensemble, semblables à deux feuilles desséchées portées vers l’horizon, jusqu’à disparaître de votre champ de vision.",
          DialogueId = 51109030,
          GUID = "7FF2333C",
          Subtitle = "(Old Man Cheng steadies Mrs Cheng, and the two of them drift off into the distance — like withered leaves carried gently on the wind — until they fade from sight.)"
        },
        [51109031] = {
          ContentFR = "Avec le temps... Je sais bien que, raisonnablement, nous ne devrions pas être aussi égoïstes... Mais cette peine, ce n’est pas en se répétant des principes qu’on parvient à l’effacer...",
          DialogueId = 51109031,
          GUID = "7FF23366",
          SpeakNpcId = 701009,
          Subtitle = "I know we shouldn't be this selfish... but it still hurts, no matter how much we tell ourselves otherwise..."
        },
        [51110000] = {
          ContentFR = "Ahouuu— grrr... ahooooou !",
          DialogueId = 51110000,
          GUID = "7FF2D260",
          NextOptions = {
            [1] = 51110001,
            [2] = 51110002,
            [3] = 51110003
          },
          SpeakNpcId = 701011,
          Subtitle = "Awoo— rrrh— awooo-wooo!"
        },
        [51110001] = {
          ContentFR = "<I>Un bon enfant ne mord pas les gens au hasard.</>",
          DialogueId = 51110001,
          GUID = "7FF2D28A",
          ImprPlusId = 1207,
          NextDialogue = 51110004,
          Subtitle = "Good kids don't just go around biting people, you know."
        },
        [51110002] = {
          ContentFR = "<I>– Mieux vaut garder ses distances... sait-on jamais.</>",
          DialogueId = 51110002,
          GUID = "7FF2D2B4",
          ImprPlusId = 1206,
          NextDialogue = 51110004,
          Subtitle = "(Best keep my distance... who knows if he's carrying something.)"
        },
        [51110003] = {
          ContentFR = "<I>Ahou ! Ahouuuuu !</>",
          DialogueId = 51110003,
          GUID = "7FF2D2DE",
          ImprPlusId = 1210,
          NextDialogue = 51110004,
          Subtitle = "Awoo! Awooooo!"
        },
        [51110004] = {
          ContentFR = "Hé ! Mais qu’est-ce que vous faites ? C’est un entraînement ! Je m’entraîne pour devenir un Bi’an !",
          DialogueId = 51110004,
          GUID = "7FF2D308",
          LookAt = {
            [1] = "701011:n(0)"
          },
          NextOptions = {
            [1] = 51110005
          },
          RestartTag = 51110004,
          SpeakNpcId = 701011,
          Subtitle = "Nah-uh! I'm training so I can be a Bi'an!"
        },
        [51110005] = {
          ContentFR = "Tu... n’es pas un Descendant draconique, n’est-ce pas ? Les Enfants de la Terre ne peuvent pas devenir des Bi’an.",
          DialogueId = 51110005,
          FailDialogue = 51110006,
          GUID = "7FF2D332",
          ImprCheckId = 1121,
          NextDialogue = 51110008,
          Subtitle = "You... you're not a Loongscion, are you? Earthborns can't become Bi'an."
        },
        [51110006] = {
          ContentFR = "Ahouuu— !",
          DialogueId = 51110006,
          GUID = "7FF2D35C",
          NextDialogue = 51110007,
          SpeakNpcId = 701011,
          Subtitle = "Awooo—!",
          TalkActionId = {
            [1] = "701011:Angry01_Start"
          }
        },
        [51110007] = {
          ContentFR = "L’enfant semble ne pas avoir entendu un mot de ce que vous avez dit. Il reste à quatre pattes et continue de hurler.",
          DialogueId = 51110007,
          GUID = "7FF2D386",
          Subtitle = "(He doesn't seem to hear a word you said — still on all fours, howling away.)",
          TalkActionId = {
            [1] = "701011:Angry01_End"
          }
        },
        [51110008] = {
          ContentFR = "À Huaxu, il y a un vieux dicton : les efforts sincères finissent toujours par payer ! Si le Seigneur Dragon d’Argent voit à quel point je m’entraîne dur, il ne me laissera pas tomber !",
          DialogueId = 51110008,
          GUID = "7FF2D3B0",
          NextDialogue = 51110009,
          SpeakNpcId = 701011,
          Subtitle = "There's an old saying in Huaxu: if you put your heart into something, it'll pay off! Lord Argent can see how hard I'm training — he definitely won't turn me away!",
          TalkActionId = {
            [1] = "701011:Talk01_Start"
          }
        },
        [51110009] = {
          ContentFR = "...",
          DialogueId = 51110009,
          GUID = "7FF2D3DA",
          NextDialogue = 51110010,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [51110010] = {
          ContentFR = "Quand je serai devenu un Bi’an imposant et majestueux, je patrouillerai tous les jours à Port-des-Brumes, et j’arrêterai tous les méchants ! Rien que d’y penser, c’est trop stylé !",
          DialogueId = 51110010,
          GUID = "7FF2D404",
          NextDialogue = 51110011,
          SpeakNpcId = 701011,
          Subtitle = "When I become a proper, mighty Bi'an, I'll patrol all of Mistwharf every day and catch every bad guy! Just thinking about it gets me all fired up!"
        },
        [51110011] = {
          ContentFR = "... Hé, vous ne me faites pas la morale comme les autres adultes. Vous êtes quelqu’un de bien, vous. Alors venez voir mes progrès !",
          DialogueId = 51110011,
          GUID = "7FF2D42E",
          NextDialogue = 51110012,
          SpeakNpcId = 701011,
          Subtitle = "...Wow, you're not telling me off like the other grown-ups. You must be a good person. Come on, I'll show you how my training's going!"
        },
        [51110012] = {
          ContentFR = "D’abord, pour devenir un Bi’an et combattre les méchants, il faut de beaux muscles. Regardez un peu... qu’est-ce que vous en pensez ?",
          DialogueId = 51110012,
          GUID = "7FF2D458",
          NextDialogue = 51110013,
          SpeakNpcId = 701011,
          Subtitle = "First off — if you want to fight bad guys as a Bi'an, you need strong muscles. Look! How do mine look?"
        },
        [51110013] = {
          ContentFR = "L’enfant serre les poings et contracte les bras. À travers ses vêtements, vous ne distinguez qu’un très léger relief.",
          DialogueId = 51110013,
          GUID = "7FF2D482",
          NextOptions = {
            [1] = 51110014,
            [2] = 51110015,
            [3] = 51110016
          },
          Subtitle = "(He tries to flex, but you can only spot the slightest little bump under his shirt.)",
          TalkActionId = {
            [1] = "701011:Talk01_End"
          }
        },
        [51110014] = {
          ContentFR = "<I>Hm... de très beaux biceps.</>",
          DialogueId = 51110014,
          GUID = "7FF2D4AC",
          ImprPlusId = 1209,
          NextDialogue = 51110017,
          Subtitle = "Mm... impressive biceps."
        },
        [51110015] = {
          ContentFR = "<I>Il faut encore s’entraîner.</>",
          DialogueId = 51110015,
          GUID = "7FF2D4D6",
          ImprPlusId = 1207,
          NextDialogue = 51110017,
          Subtitle = "Still needs work."
        },
        [51110016] = {
          ContentFR = "<I>Pff...</>",
          DialogueId = 51110016,
          GUID = "7FF2D500",
          ImprPlusId = 1210,
          NextDialogue = 51110017,
          Subtitle = "Ahahaha!"
        },
        [51110017] = {
          ContentFR = "J-je suis encore petit ! Les muscles, ça viendra plus tard ! En ce moment, je m’entraîne surtout à la vitesse. Regardez bien !",
          DialogueId = 51110017,
          GUID = "7FF2D52A",
          NextDialogue = 51110018,
          SpeakNpcId = 701011,
          Subtitle = "I—I'm still growing! I'll have muscles one day! Besides, most of my training's for agility — watch this!",
          TalkActionId = {
            [1] = "701011:Talk02_Start"
          }
        },
        [51110018] = {
          ContentFR = "Sans prévenir, l’enfant se jette au sol et se met à courir à quatre pattes, soulevant des nuages de poussière.",
          DialogueId = 51110018,
          GUID = "7FF2D554",
          NextDialogue = 51110019,
          Subtitle = "(He suddenly drops forward and scampers off on hands and feet, kicking up a cloud of dust.)"
        },
        [51110019] = {
          ContentFR = "<I>... Kof, kof.</>",
          DialogueId = 51110019,
          GUID = "7FF2D57E",
          NextDialogue = 51110020,
          SpeakNpcId = 100001,
          Subtitle = "Cough— cough."
        },
        [51110020] = {
          ContentFR = "Alors ? C’est ma technique secrète : Bi’an porté par le vent ! On s’y croirait, non ?",
          DialogueId = 51110020,
          GUID = "7FF2D5A8",
          NextOptions = {
            [1] = 51110021,
            [2] = 51110022,
            [3] = 51110023
          },
          SpeakNpcId = 701011,
          Subtitle = "Well? That's my special move — Bi'an Riding the Wind! I look the part, right?",
          TalkActionId = {
            [1] = "701011:Talk02_End"
          }
        },
        [51110021] = {
          ContentFR = "<I>Hm... si rapide qu’on en perd la trace.</>",
          DialogueId = 51110021,
          GUID = "7FF2D5D2",
          ImprPlusId = 1209,
          NextDialogue = 51110024,
          Subtitle = "Mm... so fast you're almost a blur."
        },
        [51110022] = {
          ContentFR = "<I>Il faut encore s’entraîner.</>",
          DialogueId = 51110022,
          GUID = "7FF2D5FC",
          ImprPlusId = 1207,
          NextDialogue = 51110024,
          Subtitle = "Still needs work."
        },
        [51110023] = {
          ContentFR = "<I>Pff... excuse-moi, je pensais à quelque chose de drôle.</>",
          DialogueId = 51110023,
          GUID = "7FF2D626",
          ImprPlusId = 1210,
          NextDialogue = 51110024,
          Subtitle = "Ahaha— ahem. I... just thought of something funny, sorry."
        },
        [51110024] = {
          ContentFR = "<I>Hmpf ! </>Et ce n’est pas tout ! Je m’entraîne aussi au cri du Bi’an. Ahouuu !",
          DialogueId = 51110024,
          GUID = "7FF2D650",
          NextDialogue = 51110025,
          SpeakNpcId = 701011,
          Subtitle = "Hmph! And I've been practising the Bi'an's roar as well. Awoo—!",
          TalkActionId = {
            [1] = "701011:Confident_Start"
          }
        },
        [51110025] = {
          ContentFR = "L’enfant se met soudain à hurler à pleins poumons. Voilà donc ce qu’il faisait tout à l’heure, allongé par terre.",
          DialogueId = 51110025,
          GUID = "7FF2D67A",
          NextDialogue = 51110026,
          Subtitle = "(He suddenly lets out a long howl — so that's what he was doing on the ground earlier.)"
        },
        [51110026] = {
          ContentFR = "Ahouuu... ahoooo...",
          DialogueId = 51110026,
          GUID = "7FF2D6A4",
          NextDialogue = 51110027,
          SpeakNpcId = 701011,
          Subtitle = "Awooo... awoooo..."
        },
        [51110027] = {
          ContentFR = "Je voulais dire...",
          DialogueId = 51110027,
          GUID = "7FF2D6CE",
          NextDialogue = 51110028,
          SpeakNpcId = 100001,
          Subtitle = "Well...",
          TalkActionId = {
            [1] = "701011:Confident_End"
          }
        },
        [51110028] = {
          ContentFR = "Ahouooooooo... !",
          DialogueId = 51110028,
          GUID = "7FF2D6F8",
          NextDialogue = 51110029,
          SpeakNpcId = 701011,
          Subtitle = "Awo... awooooo...",
          TalkActionId = {
            [1] = "701011:Angry01_Start"
          }
        },
        [51110029] = {
          ContentFR = "Totalement absorbé par ses hurlements, l’enfant ne répond plus à rien. Vous finissez par vous éloigner discrètement, jugeant préférable de laisser ce \"petit Bi’an\" à son entraînement.",
          DialogueId = 51110029,
          GUID = "7FF2D722",
          Subtitle = "(He's completely absorbed in his howling and won't respond to you at all. In the end, you slip away quietly — probably best to give the little \"Bi'an\" some space.)",
          TalkActionId = {
            [1] = "701011:Angry01_End"
          }
        },
        [51110030] = {
          ContentFR = "Ahouuu— alors ? Vous y avez cru, hein ? On aurait dit qu’un vrai Bi’an arrivait !",
          DialogueId = 51110030,
          GUID = "7FF2D74C",
          SpeakNpcId = 701011,
          Subtitle = "Awoo— Well? Sounded just like a real Bi'an, didn't it?"
        },
        [51111000] = {
          ContentFR = "Urrh— urrh... n-non, ça suffit... vraiment, je ne peux plus avaler une bouchée...",
          DialogueId = 51111000,
          GUID = "7FF37670",
          NextDialogue = 51111001,
          SpeakNpcId = 701012,
          Subtitle = "Urgh— urgh... n—no more... I really can't take another mouthful...",
          TalkActionId = {
            [1] = "701012:Sigh_Start"
          }
        },
        [51111001] = {
          ContentFR = "Pfiou... vous m’avez fait peur. J’ai cru que vous étiez un Tisse-Étoiles.",
          DialogueId = 51111001,
          GUID = "7FF3769A",
          NextOptions = {
            [1] = 51111002,
            [2] = 51111004
          },
          SpeakNpcId = 701012,
          Subtitle = "Phew... you gave me a fright — thought you were a Starweaver."
        },
        [51111002] = {
          ContentFR = "<I>Les Tisse-Étoiles... manger... Ils vous ont forcé à avaler quelque chose ?</>",
          DialogueId = 51111002,
          GUID = "7FF376C4",
          ImprPlusId = 1208,
          NextDialogue = 51111003,
          Subtitle = "Starweaver...? Did they force you to eat something?"
        },
        [51111003] = {
          ContentFR = "N-non, pas du tout... c’était entièrement volontaire...",
          DialogueId = 51111003,
          GUID = "7FF376EE",
          NextDialogue = 51111006,
          SpeakNpcId = 701012,
          Subtitle = "No no, all by my own choice..."
        },
        [51111004] = {
          ContentFR = "<I>Bonjour. Je suis </>{性别:<I>un</>|<I>une</>} <I>Tisse-Étoiles d’Hyperborea.</>",
          DialogueId = 51111004,
          GUID = "7FF37718",
          ImprPlusId = 1210,
          NextDialogue = 51111005,
          Subtitle = "Hello. I'm a Starweaver from Hyperborea."
        },
        [51111005] = {
          ContentFR = "Ugh... tant que vous ne me parlez pas de manger, on peut discuter de tout ce que vous voulez...",
          DialogueId = 51111005,
          GUID = "7FF37742",
          NextDialogue = 51111006,
          SpeakNpcId = 701012,
          Subtitle = "Ugh... anything you want — except having dinner with me!",
          TalkActionId = {
            [1] = "701012:Sigh_End"
          }
        },
        [51111006] = {
          ContentFR = "Alors... que s’est-il passé exactement ?",
          DialogueId = 51111006,
          GUID = "7FF3776C",
          NextDialogue = 51111007,
          SpeakNpcId = 100001,
          Subtitle = "So what's going on here?"
        },
        [51111007] = {
          ContentFR = "Je m’appelle Sammy. Je suis un marchand itinérant de Khemet, et je suis venu à Huaxu avec les Tisse-Étoiles.",
          DialogueId = 51111007,
          GUID = "7FF37796",
          NextDialogue = 51111008,
          SpeakNpcId = 701012,
          Subtitle = "I'm Sammy — a merchant from Khemet. I came to Huaxu with the Starweavers."
        },
        [51111008] = {
          ContentFR = "À l’origine, je voulais négocier un commerce d’épices avec eux. Résultat : plus d’une semaine passée à Port-des-Brumes, presque pas de discussions... et uniquement des repas. Tous les jours.",
          DialogueId = 51111008,
          GUID = "7FF377C0",
          NextDialogue = 51111009,
          SpeakNpcId = 701012,
          Subtitle = "I was meant to be discussing incense trade with them, but after more than a week in Mistwharf, I've barely touched any business — it's just been meals. Every. Single. Day.",
          TalkActionId = {
            [1] = "701012:Explain01_Start"
          }
        },
        [51111009] = {
          ContentFR = "Franchement, les gens de Huaxu sont beaucoup trop passionnés par la nourriture !\nÀ peine réveillés, c’est le petit-déjeuner. Puis une théière qui s’étire jusqu’à midi... et hop, le déjeuner s’enchaîne sans pause.",
          DialogueId = 51111009,
          GUID = "7FF377EA",
          NextDialogue = 51111010,
          SpeakNpcId = 701012,
          Subtitle = "People in Huaxu are far too obsessed with food! Open your eyes in the morning — a huge breakfast. Then a pot of tea that somehow drifts straight into lunch."
        },
        [51111010] = {
          ContentFR = "À peine le déjeuner terminé, je me dis : « Enfin un moment de répit ». Et là, quelqu’un arrive avec un plateau gigantesque de pâtisseries et de fruits. Une fois fini... c’est déjà l’heure du dîner.",
          DialogueId = 51111010,
          GUID = "7FF37814",
          NextDialogue = 51111011,
          SpeakNpcId = 701012,
          Subtitle = "After lunch I think, \"Finally, a break\" — but no, someone appears with a huge tray of pastries and fruit. Finish that, and it's supper already."
        },
        [51111011] = {
          ContentFR = "Et quand je crois enfin pouvoir aller dormir, quelqu’un frappe à la porte pour m’emmener manger un encas nocturne.",
          DialogueId = 51111011,
          GUID = "7FF3783E",
          NextDialogue = 51111012,
          SpeakNpcId = 701012,
          Subtitle = "After supper, just when I'm ready for bed, someone knocks again — dragging me out for late-night bites.",
          TalkActionId = {
            [1] = "701012:Explain01_End"
          }
        },
        [51111012] = {
          ContentFR = "Urrk... rien que d’y penser, j’ai envie de vomir...",
          DialogueId = 51111012,
          GUID = "7FF37868",
          NextDialogue = 51111013,
          SpeakNpcId = 701012,
          Subtitle = "Urgh... just thinking about it makes me retch...",
          TalkActionId = {
            [1] = "701012:Sigh_Start"
          }
        },
        [51111013] = {
          ContentFR = "Pourquoi ne pas leur avoir dit tout simplement que vous n’en pouviez plus ?",
          DialogueId = 51111013,
          GUID = "7FF37892",
          NextDialogue = 51111014,
          SpeakNpcId = 100001,
          Subtitle = "Why didn't you just say you were full?"
        },
        [51111014] = {
          ContentFR = "Au début, je n’osais pas. Après tout, c’était Huaxu, leur territoire. Mais après avoir vomi plusieurs fois, j’ai compris que ça devenait sérieux. Alors j’ai pris mon courage à deux mains et j’ai dit que j’étais vraiment rassasié. Et là... quelque chose d’encore plus terrible s’est produit...",
          DialogueId = 51111014,
          GUID = "7FF378BC",
          NextDialogue = 51111015,
          SpeakNpcId = 701012,
          Subtitle = "At first I couldn't bring myself to say it — didn't want to offend Huaxu's Starweavers. After throwing up a few times, I just couldn't take it anymore, so I finally worked up the courage to tell them I was full. And then... something worse happened..."
        },
        [51111015] = {
          ContentFR = "Les Tisse-Étoiles ont aussitôt commencé à me remplir le bol. « C’est nourrissant », « Ne vous gênez pas », « Surtout pas de manières »... Résultat : j’ai mangé trois bols de plus à ce repas-là.",
          DialogueId = 51111015,
          GUID = "7FF378E6",
          NextDialogue = 51111016,
          SpeakNpcId = 701012,
          Subtitle = "The Starweavers instantly started piling more food into my bowl — \"nutritious\", \"go on, help yourself\", that sort of thing... and I ended up eating three extra bowls!"
        },
        [51111016] = {
          ContentFR = "Ugh... c’est trop... je vais aller vomir encore un peu par là-bas... L’hospitalité de Huaxu... c’est... beaucoup trop lourd... urrh...",
          DialogueId = 51111016,
          GUID = "7FF37910",
          SpeakNpcId = 701012,
          Subtitle = "Urk... I can't— I need to go and be sick again... Huaxu's hospitality is just too much for me to handle... urgh...",
          TalkActionId = {
            [1] = "701012:Sigh_End"
          }
        },
        [51111017] = {
          ContentFR = "Urrk... huff.... huff...",
          DialogueId = 51111017,
          GUID = "7FF3793A",
          SpeakNpcId = 701012,
          Subtitle = "Urk... huff... huff..."
        },
        [51112000] = {
          ContentFR = "Prenez vos affaires. On y va.",
          DialogueId = 51112000,
          GUID = "7FF41A80",
          NextDialogue = 51112001,
          SpeakNpcId = 701013,
          Subtitle = "Grab your gear. We're moving."
        },
        [51112001] = {
          ContentFR = "À peine avez-vous mis le pied au marché noir qu’une foule compacte en surgit.",
          DialogueId = 51112001,
          GUID = "7FF41AAA",
          NextDialogue = 51112002,
          Subtitle = "(No sooner have you stepped into the black market than a crowd spills out.)"
        },
        [51112002] = {
          ContentFR = "Derrière eux gît un marchand du marché noir, à l’agonie. En y regardant de plus près, vous reconnaissez l’homme qui avait utilisé un faux contrat pour escroquer une jeune femme innocente, avant de tricher lors de leur duel.",
          DialogueId = 51112002,
          GUID = "7FF41AD4",
          NextOptions = {
            [1] = 51112003,
            [2] = 51112004,
            [3] = 51112005
          },
          Subtitle = "(A black marketeer lies behind them, barely clinging to life. A closer look — it's the very man who doctored a loan contract to trick an innocent girl, then cheated in a duel with her.)"
        },
        [51112003] = {
          ContentFR = "<I>Vous vous armez pour aller semer le trouble ?</>",
          DialogueId = 51112003,
          GUID = "7FF41AFE",
          ImprPlusId = 1207,
          NextDialogue = 51112006,
          Subtitle = "You lot — arming yourselves to stir up trouble!?"
        },
        [51112004] = {
          ContentFR = "<I>Leur cible ne semble pas être vous. Mieux vaut s’écarter.</>",
          DialogueId = 51112004,
          GUID = "7FF41B28",
          ImprPlusId = 1206,
          NextDialogue = 51112006,
          Subtitle = "(They're not after you. Best keep out of their way.)"
        },
        [51112005] = {
          ContentFR = "<I>Eh bien... ça fait quelques jours. On dirait que ça ne s’est pas arrangé.</>",
          DialogueId = 51112005,
          GUID = "7FF41B52",
          ImprPlusId = 1210,
          NextDialogue = 51112006,
          Subtitle = "Well, haven't seen him for a few days — look at him now."
        },
        [51112006] = {
          ContentFR = "Ah... l’{性别:invité|invitée} de Maître Qiu. Veuillez excuser cet accueil bien peu cérémonieux.",
          DialogueId = 51112006,
          GUID = "7FF41B7C",
          LookAt = {
            [1] = "701013:n(0)"
          },
          NextDialogue = 51112007,
          SpeakNpcId = 701013,
          Subtitle = "Ah — Mr Qiu's honoured guest. Forgive me for not offering a proper greeting."
        },
        [51112007] = {
          ContentFR = "L’homme de tête incline légèrement la tête vers vous, faisant preuve d’une courtoisie qui tranche avec l’atmosphère du marché noir.",
          DialogueId = 51112007,
          GUID = "7FF41BA6",
          NextDialogue = 51112008,
          Subtitle = "(The leader dips his head — a courtesy entirely out of place in the black market.)"
        },
        [51112008] = {
          ContentFR = "Puisque vous nous avez surpris, autant dissiper tout malentendu.",
          DialogueId = 51112008,
          GUID = "7FF41BD0",
          NextDialogue = 51112009,
          SpeakNpcId = 701013,
          Subtitle = "Since you've crossed paths with us, I'd best be clear — save you from any misunderstanding.",
          TalkActionId = {
            [1] = "701013:Explain01_Start"
          }
        },
        [51112009] = {
          ContentFR = "Percevant votre hésitation, il se décale légèrement et désigne l’homme étendu au sol.",
          DialogueId = 51112009,
          GUID = "7FF41BFA",
          NextDialogue = 51112010,
          Subtitle = "(Seeing the doubt in your eyes, Li Shi nods towards the man lying on the ground.)"
        },
        [51112010] = {
          ContentFR = "Il a récemment subi une lourde perte dans une transaction. Pris de rage lors de la dispute qui a suivi, il a recouru à des procédés interdits... et s’est attiré la sanction d’un Bi’an. Le voilà réduit à cet état, entre la vie et la mort.",
          DialogueId = 51112010,
          GUID = "7FF41C24",
          NextOptions = {
            [1] = 51112011
          },
          RestartTag = 51112011,
          SpeakNpcId = 701013,
          Subtitle = "Not long ago he took a heavy loss in a deal. In the quarrel that followed, he lost his temper and lashed out — so he drew a Bi'an's punishment, and ended up half-dead like this."
        },
        [51112011] = {
          ContentFR = "Alors... vous emmenez tout ce monde pour vous venger ?",
          DialogueId = 51112011,
          FailDialogue = 51112012,
          GUID = "7FF41C4E",
          ImprCheckId = 1122,
          NextDialogue = 51112013,
          Subtitle = "So... you're bringing your men to take revenge?"
        },
        [51112012] = {
          ContentFR = "Je crains que cela ne vous regarde pas.",
          DialogueId = 51112012,
          GUID = "7FF41C78",
          SpeakNpcId = 701013,
          Subtitle = "I'm afraid that's not something I can comment on."
        },
        [51112013] = {
          ContentFR = "Héhé. Le marché noir ne se venge pour personne. Ici, on accepte les règles du jeu — c’est la loi établie par Maître Qiu, et il en a toujours répondu lui-même.",
          DialogueId = 51112013,
          GUID = "7FF41CA2",
          NextDialogue = 51112014,
          SpeakNpcId = 701013,
          Subtitle = "Heh. The black market doesn't take revenge for anyone. You place your stake, you shoulder the consequences — Mr Qiu's rule. So the man swallows that bitter pill himself."
        },
        [51112014] = {
          ContentFR = "Perdre signifie assumer seul les conséquences. Survivre ou non, et ce que l’on fait ensuite... cela ne concerne personne d’autre.",
          DialogueId = 51112014,
          GUID = "7FF41CCC",
          NextDialogue = 51112015,
          SpeakNpcId = 701013,
          Subtitle = "Lose, and you bear the cost yourself. Whether you survive, and what you choose to do afterwards — that's no one else's concern.",
          TalkActionId = {
            [1] = "701013:Explain01_End"
          }
        },
        [51112015] = {
          ContentFR = "Je vous imaginais plus... extrêmes.",
          DialogueId = 51112015,
          GUID = "7FF41CF6",
          NextDialogue = 51112016,
          SpeakNpcId = 100001,
          Subtitle = "I thought you lot were the radical sort."
        },
        [51112016] = {
          ContentFR = "Beaucoup nourrissent cette fausse idée. Mais en réalité, le marché noir n’est qu’une organisation lâchement structurée.",
          DialogueId = 51112016,
          GUID = "7FF41D20",
          NextDialogue = 51112017,
          SpeakNpcId = 701013,
          Subtitle = "Many hold that same mistaken view. But the black market is, at its core, only loosely bound.",
          TalkActionId = {
            [1] = "701013:Talk01_Start"
          }
        },
        [51112017] = {
          ContentFR = "Ceux qui y restent sont ceux qui refusent les chaînes de l’ordre établi — et qui ont les moyens d’en payer le prix.",
          DialogueId = 51112017,
          GUID = "7FF41D4A",
          NextDialogue = 51112018,
          SpeakNpcId = 701013,
          Subtitle = "Those who remain here are the ones who answer to no outside rules — and can afford the cost of that freedom."
        },
        [51112018] = {
          ContentFR = "Nous n’avons pas peur de perdre. On encaisse, puis on se relève. Ce que nous ne tolérons pas, ce sont ceux qui ne supportent pas l’échec : arrogants quand le vent leur est favorable, mais prompts à implorer la protection de l’ordre dès que la situation se retourne. Le marché noir n’ouvre pas ses portes à ce genre de faiblesse.",
          DialogueId = 51112018,
          GUID = "7FF41D74",
          NextDialogue = 51112019,
          SpeakNpcId = 701013,
          Subtitle = "We're not afraid of losing. You take the blow, you get back up. What we can't stand are the sore losers — bold and swaggering when things go their way, then crying for protection the moment they don't. There's no room for that sort of weakness here."
        },
        [51112019] = {
          ContentFR = "À ce stade, vous comprenez donc que nous ne partons pas régler des comptes.",
          DialogueId = 51112019,
          GUID = "7FF41D9E",
          NextDialogue = 51112020,
          SpeakNpcId = 701013,
          Subtitle = "So, I trust you see what I'm saying — we're not out to avenge anyone."
        },
        [51112020] = {
          ContentFR = "Quant à ce que nous allons faire exactement... le Fléau de Zhuyin s’apaise. Nous allons simplement récupérer quelques bénéfices dans les ombres laissées par la catastrophe.",
          DialogueId = 51112020,
          GUID = "7FF41DC8",
          NextDialogue = 51112021,
          SpeakNpcId = 701013,
          Subtitle = "As for what we are doing... with the Scourge of Zhuyin ebbing, we're heading into the shadows it leaves behind — to take whatever profit's there. Nothing more.",
          TalkActionId = {
            [1] = "701013:Talk01_End"
          }
        },
        [51112021] = {
          ContentFR = "Après ces mots, l’homme s’éloigne avec les siens. Puis, après quelques pas, il s’arrête et se retourne vers vous.",
          DialogueId = 51112021,
          GUID = "7FF41DF2",
          NextDialogue = 51112022,
          Subtitle = "(He moves off with his men, but after only a few steps he pauses and glances back.)"
        },
        [51112022] = {
          ContentFR = "Puisque vous êtes l’{性别:invité|invitée} de Maître Qiu, permettez-moi de vous offrir un conseil — sans contrepartie.",
          DialogueId = 51112022,
          GUID = "7FF41E1C",
          NextDialogue = 51112023,
          SpeakNpcId = 701013,
          Subtitle = "Since you're Mr Qiu's guest, here's a piece of advice — free of charge.",
          TalkActionId = {
            [1] = "701013:Talk02_Start"
          }
        },
        [51112023] = {
          ContentFR = "Certaines choses n’appartiennent à personne. À ceux qui en ont la capacité, il revient de les saisir. Gardez l’œil ouvert : vous pourriez bien dénicher quelques trouvailles intéressantes à Port-des-Brumes. Je vous souhaite bonne route.",
          DialogueId = 51112023,
          GUID = "7FF41E46",
          SpeakNpcId = 701013,
          Subtitle = "Some things belong to no one. Those with the strength to claim them... may. Keep your eyes open — you might spot something worthwhile in Mistwharf. Farewell.",
          TalkActionId = {
            [1] = "701013:Talk02_End"
          }
        },
        [51112024] = {
          ContentFR = "Veuillez excuser mon manque d’égards. Êtes-vous ici pour affaires ?",
          DialogueId = 51112024,
          GUID = "7FF41E70",
          SpeakNpcId = 701013,
          Subtitle = "My apologies for not greeting you properly. What brings you to the market today?"
        },
        [51113000] = {
          ContentFR = "Hmm... attaque rude, finale persistante... C’est bien l’encens d’Éternel Printemps. Authentique.",
          DialogueId = 51113000,
          GUID = "7FF4BE90",
          NextDialogue = 51113001,
          SpeakNpcId = 701014,
          Subtitle = "Mmm — rough on the first whiff, smooth on the finish... now that's proper EverSpring incense.",
          TalkActionId = {
            [1] = "701014:Confident_Start"
          }
        },
        [51113001] = {
          ContentFR = "Après ces mots, l’homme porte un faisceau d’encens à son nez, inspire profondément, puis affiche une expression de pur ravissement.",
          DialogueId = 51113001,
          GUID = "7FF4BEBA",
          NextDialogue = 51113002,
          Subtitle = "(He lifts the sticks to his nose, inhales sharply, and savours the scent with unrestrained delight.)"
        },
        [51113002] = {
          ContentFR = "Hmm~ Quel délice, quel délice... Une pureté rare !",
          DialogueId = 51113002,
          GUID = "7FF4BEE4",
          NextOptions = {
            [1] = 51113003,
            [2] = 51113004
          },
          SpeakNpcId = 701014,
          Subtitle = "Ahhh~ That hits the spot! Pure as they come.",
          TalkActionId = {
            [1] = "701014:Confident_End"
          }
        },
        [51113003] = {
          ContentFR = "<I>– Cet individu a l’air un peu dérangé. Mieux vaut éviter de s’en mêler.</>",
          DialogueId = 51113003,
          GUID = "7FF4BF0E",
          ImprPlusId = 1207,
          NextDialogue = 51113005,
          Subtitle = "(He's clearly not quite right. Best not get involved.)"
        },
        [51113004] = {
          ContentFR = "<I>Vous avez un problème. Je devrais prévenir les Magistrats de Yingtian.</>",
          DialogueId = 51113004,
          GUID = "7FF4BF38",
          ImprPlusId = 1208,
          NextDialogue = 51113005,
          Subtitle = "There's something seriously wrong with you — I'm reporting you to the Magistrates of Yingtian."
        },
        [51113005] = {
          ContentFR = "Hé, hé ! Quel étrange jeune {性别:homme|femme}. Vous voilà face au célèbre maître parfumeur de Huaxu, et au lieu de faire preuve de respect... vous réagissez ainsi ? Quelle grossièreté.",
          DialogueId = 51113005,
          GUID = "7FF4BF62",
          LookAt = {
            [1] = "701014:n(0)"
          },
          NextOptions = {
            [1] = 51113006,
            [2] = 51113007
          },
          SpeakNpcId = 701014,
          Subtitle = "Oi, what an odd youngster you are. You meet Huaxu's famed incense master — me — and instead of offering respect, you carry on like that. Terribly uncouth."
        },
        [51113006] = {
          ContentFR = "<I>Voilà qu’il se croit supérieur, en plus.</>",
          DialogueId = 51113006,
          GUID = "7FF4BF8C",
          ImprPlusId = 1210,
          NextDialogue = 51113008,
          Subtitle = "Someone's full of themselves."
        },
        [51113007] = {
          ContentFR = "<I>On dirait exactement le discours d’un escroc.</>",
          DialogueId = 51113007,
          GUID = "7FF4BFB6",
          ImprPlusId = 1206,
          NextDialogue = 51113008,
          Subtitle = "That's exactly what a swindler would say."
        },
        [51113008] = {
          ContentFR = "Hé, permettez que je vous éclaire un instant.",
          DialogueId = 51113008,
          GUID = "7FF4BFE0",
          NextDialogue = 51113009,
          SpeakNpcId = 701014,
          Subtitle = "Now, now — let's set a few things straight.",
          TalkActionId = {
            [1] = "701014:Talk01_Start"
          }
        },
        [51113009] = {
          ContentFR = "Pour la plupart des gens, allumer de l’encens n’est qu’un rituel vide de sens. Ils oublient que l’encens, en lui-même, est une véritable œuvre d’art.",
          DialogueId = 51113009,
          GUID = "7FF4C00A",
          NextDialogue = 51113010,
          SpeakNpcId = 701014,
          Subtitle = "Most people burn incense just to go through the motions, never realising the incense itself is an art."
        },
        [51113010] = {
          ContentFR = "Prenez celui d’Éternel Printemps... Laissez-moi encore en humer une bouffée...",
          DialogueId = 51113010,
          GUID = "7FF4C034",
          NextDialogue = 51113011,
          SpeakNpcId = 701014,
          Subtitle = "Take these EverSpring sticks, for instance... hold on, another sniff..."
        },
        [51113011] = {
          ContentFR = "Hmm~ Sans aucun doute : du Bois de santal émeraude récolté autour du Quai-aux-Étoiles, relevé d’Armoise des Nuages-Verts et d’Herbe rosée-flottante.",
          DialogueId = 51113011,
          GUID = "7FF4C05E",
          NextDialogue = 51113012,
          SpeakNpcId = 701014,
          Subtitle = "Mmm~ That's got to be Emerald Sandalwood from around Starwharf, with a touch of Azure Mugwort and a bit of Dewgrass in the mix."
        },
        [51113012] = {
          ContentFR = "Depuis des temps immémoriaux, Port-des-Brumes est un nœud vital du transport à Huaxu. Ses eaux nourrissent les hommes... et façonnent un écosystème exceptionnel. Éternel Printemps utilise les ressources locales pour ses encens : admirable, tout simplement.",
          DialogueId = 51113012,
          GUID = "7FF4C088",
          NextDialogue = 51113013,
          SpeakNpcId = 701014,
          Subtitle = "Mistwharf's been Huaxu's harbour since forever. The waters here nurture people — and plants — like nowhere else. EverSpring incense uses whatever grows nearby. Brilliant work, truly."
        },
        [51113013] = {
          ContentFR = "Allez, sentez. Percevez-vous cette rudesse du bois, ce picotement presque agressif ?",
          DialogueId = 51113013,
          GUID = "7FF4C0B2",
          NextDialogue = 51113014,
          SpeakNpcId = 701014,
          Subtitle = "Go on, have a sniff. Feel that rough, prickly bite in the wood?",
          TalkActionId = {
            [1] = "701014:Talk01_End"
          }
        },
        [51113014] = {
          ContentFR = "Non.",
          DialogueId = 51113014,
          GUID = "7FF4C0DC",
          NextDialogue = 51113015,
          SpeakNpcId = 100001,
          Subtitle = "No."
        },
        [51113015] = {
          ContentFR = "Très bien, très bien... Alors essayez celui-ci, venu de Haojing. Sentez-vous une différence ?",
          DialogueId = 51113015,
          GUID = "7FF4C106",
          NextDialogue = 51113016,
          SpeakNpcId = 701014,
          Subtitle = "Right then. Try this one from Haojing — notice anything different?",
          TalkActionId = {
            [1] = "701014:Give"
          }
        },
        [51113016] = {
          ContentFR = "L’homme sort un bâton d’encens de sa manche, l’allume, puis vous le tend.",
          DialogueId = 51113016,
          GUID = "7FF4C130",
          NextDialogue = 51113017,
          Subtitle = "(He pulls out another stick, lights it, and offers it to you.)"
        },
        [51113017] = {
          ContentFR = "Toujours pas.",
          DialogueId = 51113017,
          GUID = "7FF4C15A",
          NextDialogue = 51113018,
          SpeakNpcId = 100001,
          Subtitle = "Still nothing."
        },
        [51113018] = {
          ContentFR = "Haojing est entourée de montagnes. Les artisans y utilisent des ingrédients cueillis sur les pentes, ce qui confère à leurs encens une amertume caractéristique.",
          DialogueId = 51113018,
          GUID = "7FF4C184",
          NextDialogue = 51113019,
          SpeakNpcId = 701014,
          Subtitle = "Haojing sits cradled by mountains. Incense-makers there work with whatever the hills provide, so their sticks always open with a hint of bitterness.",
          TalkActionId = {
            [1] = "701014:Confident_Start"
          }
        },
        [51113019] = {
          ContentFR = "Mais passé ce premier goût âpre, une fragrance subtile émerge, comme l’effort d’une ascension qui s’efface aussitôt le sommet atteint.",
          DialogueId = 51113019,
          GUID = "7FF4C1AE",
          NextDialogue = 51113020,
          SpeakNpcId = 701014,
          Subtitle = "But just after the bitter comes a whisper of sweetness — like the slog of climbing a mountain, wiped clean the moment you reach the summit."
        },
        [51113020] = {
          ContentFR = "Si un jour vous foulez les cimes de Haojing, vous comprendrez sans peine ce que j’essaie de vous décrire.",
          DialogueId = 51113020,
          GUID = "7FF4C1D8",
          NextDialogue = 51113021,
          SpeakNpcId = 701014,
          Subtitle = "Stand on Haojing's peaks one day and you'll know exactly what I'm talking about."
        },
        [51113021] = {
          ContentFR = "Soudain, l’homme tourne la tête et inspire vivement l’air autour de lui.",
          DialogueId = 51113021,
          GUID = "7FF4C202",
          NextDialogue = 51113022,
          Subtitle = "(Suddenly, he turns his head and sharply inhales towards the distance.)"
        },
        [51113022] = {
          ContentFR = "<I>Hss...</> Il y a là-bas... une senteur différente...",
          DialogueId = 51113022,
          GUID = "7FF4C22C",
          NextDialogue = 51113023,
          SpeakNpcId = 701014,
          Subtitle = "Mmm... there's a unique scent over that way..."
        },
        [51113023] = {
          ContentFR = "Bien. Assez bavardé. Je dois poursuivre ma quête olfactive. Si le destin le veut... nous nous reverrons~",
          DialogueId = 51113023,
          GUID = "7FF4C256",
          LookAt = {
            [1] = "701014:n(701014)"
          },
          NextDialogue = 51113024,
          SpeakNpcId = 701014,
          Subtitle = "Right, enough chatter. More scents to chase. If fate's willing, we'll meet again~",
          TalkActionId = {
            [1] = "701014:Confident_End"
          }
        },
        [51113024] = {
          ContentFR = "Sur ces mots, il s’élance à toute allure vers l’horizon. Même lorsqu’il n’est plus qu’un point au loin, son « quel délice, quel délice ! » résonne encore à vos oreilles.",
          DialogueId = 51113024,
          GUID = "7FF4C280",
          Scripts = "MoveTo{ActorId{701014},TargetPoint{\"WuYe_Target\"},MoveSpeed{120},Visibility{\"Hide\"}}",
          Subtitle = "(With that, he darts off. Even from afar, you can still hear his ecstatic \"Ahhh~ That hits the spot!\" echoing down the road.)"
        },
        [51114000] = {
          Camera = "-272.671875,-120.883789,144.290039,0.000001,-3.199971,23.596222,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hé, jeune {性别:homme|demoiselle}, un instant, je vous prie ! Accepteriez-vous de me rendre un petit service ?",
          DialogueId = 51114000,
          GUID = "7FF562A0",
          LookAt = {
            [1] = "701015:n(100001)",
            [2] = "701016:n(100001)",
            [3] = "100001:n(701015)"
          },
          NextDialogue = 51114001,
          SpeakNpcId = 701015,
          Subtitle = "Excuse me, young {性别：man|lady} — could you lend me a hand?",
          TalkActionId = {
            [1] = "701015:Talk01_Start"
          }
        },
        [51114001] = {
          ContentFR = "Mon enfant insiste pour manger une poire, mais je ne peux pas m’éloigner pour l’instant. Pourriez-vous nous en acheter deux ? Rassurez-vous, votre aide sera récompensée.",
          DialogueId = 51114001,
          GUID = "7FF562CA",
          LookAt = {
            [1] = "701015:n(701016)",
            [2] = "701016:n(701015)"
          },
          NextOptions = {
            [1] = 51114002
          },
          RestartTag = 51114001,
          SpeakNpcId = 701015,
          Subtitle = "My boy's set on having a pear, but I can't step away just now. Could you buy two for us? Don't worry, I'll pay you properly."
        },
        [51114002] = {
          ContentFR = "<I>Une récompense, hein...</>",
          DialogueId = 51114002,
          FailDialogue = 51114003,
          GUID = "7FF562F4",
          ImprCheckId = 1123,
          NextDialogue = 51114004,
          Subtitle = "Oh? He's paying..."
        },
        [51114003] = {
          ContentFR = "Même avec de l’argent en jeu, vous n’avez pas envie de vous en mêler.",
          DialogueId = 51114003,
          GUID = "7FF5631E",
          LookAt = {
            [1] = "701015:n(100001)",
            [2] = "701016:n(100001)"
          },
          Subtitle = "(Even for money, you can't be bothered.)",
          TalkActionId = {
            [1] = "701015:Talk01_End"
          }
        },
        [51114004] = {
          Camera = "5.535156,127.534668,137.970703,0.000004,-1.200132,-101.204422,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Très bien, je m’en charge.",
          DialogueId = 51114004,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FF56348",
          LookAt = {
            [1] = "701015:n(100001)",
            [2] = "701016:n(100001)"
          },
          SpeakNpcId = 100001,
          Subtitle = "Sure, I'll get them.",
          TalkActionId = {
            [1] = "701015:Talk01_End",
            [2] = "100001:AgreeHead"
          }
        },
        [51114005] = {
          ContentFR = "Vous suivez les indications de l’homme et achetez deux poires à l’étal de fruits voisin.",
          DialogueId = 51114005,
          GUID = "7FF56372",
          NextDialogue = 51114006,
          Subtitle = "You follow his directions to a nearby fruit stall and buy two pears."
        },
        [51114006] = {
          ContentFR = "Lorsque vous revenez à l’endroit convenu, quelque chose vous surprend : sans que vous sachiez quand ni comment, la scène semble s’être dupliquée. Il y a désormais deux pères et deux enfants.",
          DialogueId = 51114006,
          GUID = "7FF5639C",
          IsBlack = 1,
          Subtitle = "When you return, the father-and-son pair seems to have multiplied — now there are two sets."
        },
        [51114007] = {
          Camera = "70.517578,-345.901733,138.587891,0.000038,-2.400115,100.211617,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai rapporté les poires.",
          DialogueId = 51114007,
          GUID = "7FF563C6",
          LookAt = {
            [1] = "701015:n(100001)",
            [2] = "701016:n(100001)",
            [3] = "701017:n(100001)",
            [4] = "701018:n(100001)",
            [5] = "100001:n(701015)"
          },
          NextDialogue = 51114008,
          SpeakNpcId = 100001,
          Subtitle = "I've brought the pears.",
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51114008] = {
          Camera = "-51.375,-217.30188,136.371094,0.000038,-0.000157,60.812229,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci beaucoup, jeune {性别:homme|demoiselle} !",
          DialogueId = 51114008,
          GUID = "7FF563F0",
          NextDialogue = 51114009,
          SpeakNpcId = 701015,
          Subtitle = "Thank you, young {性别：man|lady}!",
          TalkActionId = {
            [1] = "701015:Talk02_Start"
          }
        },
        [51114009] = {
          ContentFR = "Ouah ! Des poires !",
          DialogueId = 51114009,
          GUID = "7FF5641A",
          NextDialogue = 51114010,
          SpeakNpcId = 701016,
          Subtitle = "Hooray — pears!",
          TalkActionId = {
            [1] = "701015:Talk02_End",
            [2] = "701016:Huanhu_Nan_Start"
          }
        },
        [51114010] = {
          Camera = "114.041016,-238.422974,146.254883,0.000062,-1.999872,116.998978,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Des poires... moi aussi, j’en veux...",
          DialogueId = 51114010,
          GUID = "7FF56444",
          LookAt = {
            [1] = "100001:n(701018)"
          },
          NextDialogue = 51114011,
          SpeakNpcId = 701018,
          Subtitle = "Pears... I want one too...",
          TalkActionId = {
            [1] = "701018:Explain02_Start"
          }
        },
        [51114011] = {
          ContentFR = "Allons, voyons ! On ne convoite pas ce qui appartient aux autres.",
          DialogueId = 51114011,
          GUID = "7FF5646E",
          LookAt = {
            [1] = "701015:n(701017)",
            [2] = "701016:n(701017)",
            [3] = "701017:n(701018)",
            [4] = "701018:n(701017)",
            [5] = "100001:n(701017)"
          },
          NextDialogue = 51114012,
          SpeakNpcId = 701017,
          Subtitle = "Don't drool over someone else's food! That's not polite.",
          TalkActionId = {
            [1] = "701018:Explain02_End"
          }
        },
        [51114012] = {
          Camera = "70.517578,-345.901733,138.587891,0.000038,-2.400115,100.211617,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce n’est rien. Il y en a justement deux. Donnez-en une à chaque enfant.",
          DialogueId = 51114012,
          GUID = "7FF56498",
          LookAt = {
            [1] = "701015:n(701017)",
            [2] = "701016:n(701015)",
            [3] = "701017:n(701015)",
            [4] = "701018:n(701015)",
            [5] = "100001:n(701015)"
          },
          NextDialogue = 51114013,
          SpeakNpcId = 701015,
          Subtitle = "It's all right — there are two. Let the boys have one each.",
          TalkActionId = {
            [1] = "701015:Give"
          }
        },
        [51114013] = {
          ContentFR = "Yang attrape aussitôt la plus grosse poire.",
          DialogueId = 51114013,
          GUID = "7FF564C2",
          NextDialogue = 51114014,
          Subtitle = "(Yang immediately reaches for the larger pear.)"
        },
        [51114014] = {
          ContentFR = "Allons, regarde-toi ! Zhang est notre invité. Tu devrais lui laisser la plus grosse.",
          DialogueId = 51114014,
          GUID = "7FF564EC",
          LookAt = {
            [1] = "701015:n(701016)"
          },
          NextDialogue = 51114015,
          SpeakNpcId = 701015,
          Subtitle = "Now, now — Zhang's our guest. You should give him the bigger one.",
          TalkActionId = {
            [1] = "701015:Explain01_Start"
          }
        },
        [51114015] = {
          Camera = "-14.386719,-150.782349,116.589844,0.000093,-4.200163,89.193451,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tiens... prends-la...",
          DialogueId = 51114015,
          GUID = "7FF56516",
          LookAt = {
            [1] = "701016:n(701018)",
            [2] = "701017:n(701016)",
            [3] = "701018:n(701016)",
            [4] = "100001:n(701016)"
          },
          NextDialogue = 51114016,
          SpeakNpcId = 701016,
          Subtitle = "...All right. Here you go...",
          TalkActionId = {
            [1] = "701015:Explain01_End",
            [2] = "701016:Give"
          }
        },
        [51114016] = {
          ContentFR = "À contrecœur, il tend la grosse poire à Zhang, qui la reçoit avec enthousiasme.",
          DialogueId = 51114016,
          GUID = "7FF56540",
          NextDialogue = 51114017,
          Subtitle = "(With obvious reluctance, he hands the larger pear to Zhang, who accepts it with delight.)"
        },
        [51114017] = {
          Camera = "114.041016,-238.422974,146.254883,0.000062,-1.999872,116.998978,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh non, ce n’est pas convenable ! Yang est plus jeune, tu devrais lui laisser la plus grosse.",
          DialogueId = 51114017,
          GUID = "7FF5656A",
          LookAt = {
            [1] = "701015:n(701017)",
            [2] = "701016:n(701017)",
            [3] = "701017:n(701018)",
            [4] = "701018:n(701017)",
            [5] = "100001:n(701017)"
          },
          NextDialogue = 51114018,
          SpeakNpcId = 701017,
          Subtitle = "Oh no, we can't take that! Yang's younger — you ought to be kind to a little brother. Come on, give the larger one back to him."
        },
        [51114018] = {
          Camera = "-14.386719,-150.782349,116.589844,0.000093,-4.200163,89.193451,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors... garde-la...",
          DialogueId = 51114018,
          GUID = "7FF56594",
          LookAt = {
            [1] = "701015:n(701018)",
            [2] = "701016:n(701018)",
            [3] = "701017:n(701018)",
            [4] = "701018:n(701016)",
            [5] = "100001:n(701018)"
          },
          NextDialogue = 51114019,
          SpeakNpcId = 701018,
          Subtitle = "You have it, little brother...",
          TalkActionId = {
            [1] = "701018:Give"
          }
        },
        [51114019] = {
          ContentFR = "Il rend la grosse poire. Le sourire quitte son visage pour illuminer aussitôt celui de Yang.",
          DialogueId = 51114019,
          GUID = "7FF565BE",
          NextDialogue = 51114020,
          Subtitle = "(He returns the larger pear, and Yang's smile immediately reappears.)"
        },
        [51114020] = {
          Camera = "-51.375,-217.30188,136.371094,0.000038,-0.000157,60.812229,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Allons, inutile d’être si poli. À son âge, Zhang est en pleine croissance. Il a besoin de bien manger.",
          DialogueId = 51114020,
          GUID = "7FF565E8",
          LookAt = {
            [1] = "701015:n(701017)",
            [2] = "701016:n(701015)",
            [3] = "701017:n(701015)",
            [4] = "701018:n(701015)",
            [5] = "100001:n(701015)"
          },
          NextDialogue = 51114021,
          SpeakNpcId = 701015,
          Subtitle = "It's all right. Your lad's in a growth spurt — he needs the extra bit more.",
          TalkActionId = {
            [1] = "701015:Talk01_Start"
          }
        },
        [51114021] = {
          Camera = "114.041016,-238.422974,146.254883,0.000062,-1.999872,116.998978,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais vous les avez achetées ! Nous sommes déjà bien embarrassés d’en accepter une... comment pourrions-nous encore choisir la plus grosse ?",
          DialogueId = 51114021,
          GUID = "7FF56612",
          LookAt = {
            [1] = "701015:n(701017)",
            [2] = "701016:n(701017)",
            [3] = "701017:n(701015)",
            [4] = "701018:n(701017)",
            [5] = "100001:n(701017)"
          },
          NextDialogue = 51114022,
          SpeakNpcId = 701017,
          Subtitle = "But you bought them. We already feel guilty taking one for nothing — we can't possibly take the bigger one as well...",
          TalkActionId = {
            [1] = "701015:Talk01_End",
            [2] = "701017:Talk02_Start"
          }
        },
        [51114022] = {
          Camera = "-14.386719,-150.782349,116.589844,0.000093,-4.200163,89.193451,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51114022,
          GUID = "7FF5663C",
          LookAt = {
            [1] = "701016:n(701018)",
            [2] = "701018:n(701016)"
          },
          NextDialogue = 51114023,
          SpeakNpcName = "UI_CMNpc_Yanjindu_Name_YangJRAndZhangJR",
          Subtitle = "...",
          TalkActionId = {
            [1] = "701017:Talk02_End"
          }
        },
        [51114023] = {
          ContentFR = "Les deux enfants vous regardent avec insistance, espérant visiblement que vous mettiez fin à cet interminable échange de politesses.",
          DialogueId = 51114023,
          GUID = "7FF56666",
          LookAt = {
            [1] = "701015:n(100001)",
            [2] = "701016:n(100001)",
            [3] = "701017:n(100001)",
            [4] = "701018:n(100001)"
          },
          NextOptions = {
            [1] = 51114024,
            [2] = 51114026,
            [3] = 51114028
          },
          Subtitle = "(The two boys stare at you, silently begging you to stop this endless back-and-forth.)",
          TalkActionId = {
            [1] = "701016:Explain02_Start",
            [2] = "701018:Think_Start"
          }
        },
        [51114024] = {
          ContentFR = "<I>Et si j’allais en racheter deux exactement de la même taille ?</>",
          DialogueId = 51114024,
          GUID = "7FF56690",
          ImprPlusId = 1207,
          NextDialogue = 51114025,
          Subtitle = "How about I go and buy another two the same size?"
        },
        [51114025] = {
          Camera = "70.517578,-345.901733,138.587891,0.000038,-2.400115,100.211617,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non, non... ce serait vraiment vous donner trop de peine...",
          DialogueId = 51114025,
          GUID = "7FF566BA",
          NextDialogue = 51114030,
          SpeakNpcId = 701015,
          Subtitle = "No, no — we couldn't trouble you again...",
          TalkActionId = {
            [1] = "701016:Explain02_End",
            [2] = "701018:Think_End"
          }
        },
        [51114026] = {
          ContentFR = "<I>Pourquoi ne pas les couper en morceaux et les partager ?</>",
          DialogueId = 51114026,
          GUID = "7FF566E4",
          ImprPlusId = 1208,
          NextDialogue = 51114027,
          Subtitle = "Why not slice them and share?"
        },
        [51114027] = {
          Camera = "70.517578,-345.901733,138.587891,0.000038,-2.400115,100.211617,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah surtout pas ! Ici, couper une poire signifie « séparation ». C’est de mauvais augure.",
          DialogueId = 51114027,
          GUID = "7FF5670E",
          NextDialogue = 51114030,
          SpeakNpcId = 701015,
          Subtitle = "Goodness, no — in Huaxu, cutting a pear means parting ways. It's bad luck.",
          TalkActionId = {
            [1] = "701016:Explain02_End",
            [2] = "701018:Think_End"
          }
        },
        [51114028] = {
          ContentFR = "<I>Je suis {性别:un étranger|une étrangère}, moi aussi je grandis. Donnez-les-moi toutes les deux.</>",
          DialogueId = 51114028,
          GUID = "7FF56738",
          ImprPlusId = 1210,
          NextDialogue = 51114029,
          Subtitle = "I'm a foreigner, and I'm in a growth spurt too. Best give both to me."
        },
        [51114029] = {
          Camera = "70.517578,-345.901733,138.587891,0.000038,-2.400115,100.211617,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ha ha ! Vous êtes très drôle, jeune {性别:homme|demoiselle}...",
          DialogueId = 51114029,
          GUID = "7FF56762",
          NextDialogue = 51114030,
          SpeakNpcId = 701015,
          Subtitle = "Ha! This young {性别：man|lady} has quite the sense of humour...",
          TalkActionId = {
            [1] = "701016:Explain02_End",
            [2] = "701018:Think_End"
          }
        },
        [51114030] = {
          Camera = "-51.375,-217.30188,136.371094,0.000038,-0.000157,60.812229,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pardonnez-nous. À force de nous faire des politesses, nous vous avons laissé de côté.",
          DialogueId = 51114030,
          GUID = "7FF5678C",
          LookAt = {
            [1] = "701015:n(100001)",
            [2] = "701016:n(100001)",
            [3] = "701017:n(100001)",
            [4] = "701018:n(100001)",
            [5] = "100001:n(701015)"
          },
          NextDialogue = 51114031,
          SpeakNpcId = 701015,
          Subtitle = "My apologies — we got so caught up that we kept you waiting.",
          TalkActionId = {
            [1] = "701015:Explain01_Start"
          }
        },
        [51114031] = {
          ContentFR = "Tenez, jeune {性别:homme|demoiselle}, voici votre récompense.",
          DialogueId = 51114031,
          GUID = "7FF567B6",
          LookAt = {
            [1] = "701015:n(701017)",
