            [3] = "701017:n(701015)",
            [4] = "701018:n(701015)",
            [5] = "100001:n(701015)"
          },
          NextDialogue = 51114032,
          SpeakNpcId = 701015,
          Subtitle = "Here, young {性别：man|lady} — please take your payment.",
          TalkActionId = {
            [1] = "701015:Explain01_End"
