            [2] = "701016:n(701017)",
            [3] = "701017:n(701015)",
            [4] = "701018:n(701017)",
            [5] = "100001:n(701017)"
          },
          NextDialogue = 51114033,
          SpeakNpcId = 701017,
          Subtitle = "Oh, let me!",
          TalkActionId = {
            [1] = "701017:Talk01_Start"
          }
