          SpeakNpcId = 701019,
          Subtitle = "I've got it! I'll put chilli powder in their pillows... heehee..."
        },
        [51116000] = {
          ContentFR = "{性别:Monsieur|Mademoiselle}, un instant, je vous prie ! J’aurais une requête à vous soumettre !",
          DialogueId = 51116000,
          GUID = "7FF6AAC0",
          LookAt = {
            [1] = "701020:n(0)"
          },
          NextOptions = {
            [1] = 51116001
          },
          SpeakNpcId = 701020,
          Subtitle = "Good {性别：sir|lady}, pray wait a moment — I have a favour to ask."
        },
        [51116001] = {
          ContentFR = "<I>Qu’y a-t-il ?</>",
          DialogueId = 51116001,
          GUID = "7FF6AAEA",
          NextDialogue = 51116002,
          Subtitle = "What is it?"
        },
        [51116002] = {
          ContentFR = "Pourriez-vous m’aider à attraper quelques petits animaux ?",
          DialogueId = 51116002,
          GUID = "7FF6AB14",
          NextDialogue = 51116003,
          SpeakNpcId = 701020,
          Subtitle = "Could you help me catch a few small animals?",
          TalkActionId = {
            [1] = "701020:Talk01_Start"
          }
        },
        [51116003] = {
          ContentFR = "Des petits animaux... ? Pour quoi faire ?",
          DialogueId = 51116003,
          GUID = "7FF6AB3E",
          NextDialogue = 51116004,
          SpeakNpcId = 100001,
          Subtitle = "Small animals...? What exactly are you planning?"
        },
        [51116004] = {
          ContentFR = "Rassurez-vous, {性别:Monsieur|Mademoiselle} ! Je n’ai aucune intention de nuire à des êtres innocents. Aujourd’hui, je joue ici du qin et j’aimerais que quelques animaux me servent d’auditoire.",
          DialogueId = 51116004,
          GUID = "7FF6AB68",
          NextDialogue = 51116005,
          SpeakNpcId = 701020,
          Subtitle = "Rest assured, good {性别：sir|lady} — I've no wish to harm a single living creature. I'm to perform on the zither here today, and hoped the little animals might be my audience."
        },
        [51116005] = {
          ContentFR = "Pourquoi absolument des animaux ?",
          DialogueId = 51116005,
          GUID = "7FF6AB92",
          NextDialogue = 51116006,
          SpeakNpcId = 100001,
          Subtitle = "Why animals, specifically?"
        },
        [51116006] = {
          ContentFR = "Vous l’ignorez peut-être, mais dans l’antique Huaxu vivait une musicienne dont la renommée traversait le monde. On raconte que lorsque ses doigts effleuraient les cordes, même les bêtes sauvages s’arrêtaient pour écouter.",
          DialogueId = 51116006,
          GUID = "7FF6ABBC",
          NextDialogue = 51116007,
          SpeakNpcId = 701020,
          Subtitle = "Perhaps you've not heard — in ancient Huaxu there lived a zither-master celebrated across the land. It's said that when she performed, even wild beasts would stop and listen.",
          TalkActionId = {
            [1] = "701020:Talk01_End"
          }
        },
        [51116007] = {
          ContentFR = "Atteindre un tel niveau... voilà l’aspiration de toute ma vie !",
          DialogueId = 51116007,
          GUID = "7FF6ABE6",
          NextDialogue = 51116008,
          SpeakNpcId = 701020,
          Subtitle = "It has long been my aspiration to reach such heights!",
          TalkActionId = {
            [1] = "701020:Confident_Start"
          }
        },
        [51116008] = {
          ContentFR = "Hélas, les animaux aux alentours du Port-des-Brumes sont d’une timidité extrême. À peine me suis-je assis qu’ils prennent déjà la fuite, avant même que je ne commence à jouer.",
          DialogueId = 51116008,
          GUID = "7FF6AC10",
          NextDialogue = 51116009,
          SpeakNpcId = 701020,
          Subtitle = "But the little creatures around Mistwharf are dreadfully timid. I had barely sat down — hadn't so much as touched the strings — before they all fled."
        },
        [51116009] = {
          ContentFR = "Ainsi, jamais ils n’ont pu entendre l’œuvre que j’ai composée avec tant de soin... quel regret.",
          DialogueId = 51116009,
          GUID = "7FF6AC3A",
          NextDialogue = 51116010,
          SpeakNpcId = 701020,
          Subtitle = "So I've never once had the chance to let them hear the piece I composed with such devotion. A pity... truly a pity.",
          TalkActionId = {
            [1] = "701020:Confident_End"
          }
        },
        [51116010] = {
          ContentFR = "Si vous pouvez les amener jusqu’ici et m’aider à réaliser ce rêve, je saurais me montrer généreux !",
          DialogueId = 51116010,
          GUID = "7FF6AC64",
          NextOptions = {
            [1] = 51116011
          },
          RestartTag = 51116010,
          SpeakNpcId = 701020,
          Subtitle = "If you could bring them here and help me realise this wish, I'd be deeply grateful — and of course, you shall be handsomely rewarded."
        },
        [51116011] = {
          ContentFR = "Très bien... je vais réfléchir à une solution.",
          DialogueId = 51116011,
          FailDialogue = 51116012,
          GUID = "7FF6AC8E",
          ImprCheckId = 1124,
          NextDialogue = 51116013,
          Subtitle = "All right then — I'll see what I can do."
        },
        [51116012] = {
          ContentFR = "Comment attirer des animaux jusqu’ici, au juste... ?",
          DialogueId = 51116012,
          GUID = "7FF6ACB8",
          SpeakNpcId = 100001,
          Subtitle = "(Now... how am I supposed to get animals to come over here?)"
        },
        [51116013] = {
          ContentFR = "Vous réfléchissez un instant, puis décidez d’utiliser de la nourriture pour attirer les animaux.",
          DialogueId = 51116013,
          GUID = "7FF6ACE2",
          IsBlack = 1,
          NextDialogue = 51116014,
          Subtitle = "After giving it some thought, you decide to attract them with food."
        },
        [51116014] = {
          ContentFR = "Grâce à vos efforts, quelques oiseaux et un cerf s’approchent de Ju Mu, guidés par l’odeur des vivres.",
          DialogueId = 51116014,
          GUID = "7FF6AD0C",
          IsBlack = 1,
          NextDialogue = 51116015,
          Subtitle = "Soon enough, a few birds and a deer follow the scent and draw near to Ju Mu."
        },
        [51116015] = {
          ContentFR = "Quelle idée ingénieuse ! {性别:Monsieur|Mademoiselle}, vous êtes d’une intelligence remarquable ! Voici la récompense promise, je vous en prie, acceptez-la.",
          DialogueId = 51116015,
          GUID = "7FF6AD36",
          NextDialogue = 51116016,
          SpeakNpcId = 701020,
          Subtitle = "What a clever idea — truly ingenious, good {性别：sir|lady}! Your reward is prepared; please, accept it.",
          TalkActionId = {
            [1] = "701020:Give"
          }
        },
        [51116016] = {
          ContentFR = "Sans plus tarder, je vais commencer à jouer. Si le cœur vous en dit, restez donc écouter.",
          DialogueId = 51116016,
          GUID = "7FF6AD60",
          NextDialogue = 51116017,
          SpeakNpcId = 701020,
          Subtitle = "I shall begin at once. If you've the leisure, you are most welcome to stay and listen."
        },
        [51116017] = {
          ContentFR = "Ju Mu s’assied avec un sérieux solennel, remonte ses manches, lève les poignets... et entame son interprétation.",
          DialogueId = 51116017,
          GUID = "7FF6AD8A",
          NextDialogue = 51116018,
          Subtitle = "(Ju Mu settles himself with great ceremony, rolls up his sleeves, raises his hands — and begins to play...)"
        },
        [51116018] = {
          ContentFR = "... Vous comprenez enfin d’où provenait l’étrange vacarme entendu plus tôt.",
          DialogueId = 51116018,
          GUID = "7FF6ADB4",
          NextDialogue = 51116019,
          Subtitle = "(...And at last you discover the source of that strange noise from earlier.)"
        },
        [51116019] = {
          ContentFR = "Cui-cui ?!",
          DialogueId = 51116019,
          GUID = "7FF6ADDE",
          NextDialogue = 51116020,
          SpeakNpcName = "UI_CMNpc_Yanjindu_Name_Bird",
          Subtitle = "Cheep!?"
        },
        [51116020] = {
          ContentFR = "Hiiiin !",
          DialogueId = 51116020,
          GUID = "7FF6AE08",
          NextDialogue = 51116021,
          SpeakNpcName = "UI_CMNpc_Yanjindu_Name_Deer",
          Subtitle = "Brrh—!!"
        },
        [51116021] = {
          ContentFR = "Les animaux prennent la fuite dans toutes les directions, abandonnant leur nourriture à peine entamée.",
          DialogueId = 51116021,
          GUID = "7FF6AE32",
          NextOptions = {
            [1] = 51116022,
            [2] = 51116023,
            [3] = 51116024
          },
          Subtitle = "(The animals scatter at once, abandoning their food mid-bite.)"
        },
        [51116022] = {
          ContentFR = "<I>On dirait que vous avez encore besoin de vous entraîner.</>",
          DialogueId = 51116022,
          GUID = "7FF6AE5C",
          ImprPlusId = 1207,
          NextDialogue = 51116025,
          Subtitle = "Looks like you've got a lot more practising to do."
        },
        [51116023] = {
          ContentFR = "<I>Vous devriez me payer pour avoir enduré une telle prestation.</>",
          DialogueId = 51116023,
          GUID = "7FF6AE86",
          ImprPlusId = 1206,
          NextDialogue = 51116025,
          Subtitle = "You should be paying me for sitting through that."
        },
        [51116024] = {
          ContentFR = "<I>Incroyable ! Vous jouez si bien qu’ils en ont perdu la tête !</>",
          DialogueId = 51116024,
          GUID = "7FF6AEB0",
          ImprPlusId = 1210,
          NextDialogue = 51116025,
          Subtitle = "Good heavens — you played so well the animals are all fired up!"
        },
        [51116025] = {
          ContentFR = "C... comment cela a-t-il pu arriver... ? Quelle en est la raison... ?",
          DialogueId = 51116025,
          GUID = "7FF6AEDA",
          NextDialogue = 51116026,
          SpeakNpcId = 701020,
          Subtitle = "H—How could this happen...? Why would it turn out like this...?"
        },
        [51116026] = {
          ContentFR = "Êtes-vous certain que ce que vous jouez puisse être qualifié de musique ?",
          DialogueId = 51116026,
          GUID = "7FF6AF04",
          NextDialogue = 51116027,
          SpeakNpcId = 100001,
          Subtitle = "Are you sure that even counts as music?"
        },
        [51116027] = {
          ContentFR = "Une œuvre dite « transcendante » ne saurait ressembler à de la musique ordinaire.",
          DialogueId = 51116027,
          GUID = "7FF6AF2E",
          NextDialogue = 51116028,
          SpeakNpcId = 701020,
          Subtitle = "A piece meant to transcend the ordinary naturally sounds different from common tunes.",
          TalkActionId = {
            [1] = "701020:Talk02_Start"
          }
        },
        [51116028] = {
          ContentFR = "Puisqu’elle devait être appréciée même par les animaux, j’ai pensé qu’il fallait puiser directement dans la nature... Ainsi, ce morceau mêlait le craquement des branches, le bourdonnement des insectes, le grattement des chiens errants...",
          DialogueId = 51116028,
          GUID = "7FF6AF58",
          NextDialogue = 51116029,
          SpeakNpcId = 701020,
          Subtitle = "As it was meant to delight even animals, I thought it best to draw inspiration from nature. For instance, the piece I played included the snap of breaking branches, the buzz of insects' wings, and the sound of stray dogs scratching at the ground..."
        },
        [51116029] = {
          ContentFR = "Je croyais cette composition parfaite... et pourtant, tout cela n’a servi à rien...",
          DialogueId = 51116029,
          GUID = "7FF6AF82",
          NextOptions = {
            [1] = 51116030
          },
          SpeakNpcId = 701020,
          Subtitle = "I truly believed I'd poured my heart into a flawless composition... Never did I imagine all that effort would amount to nothing...",
          TalkActionId = {
            [1] = "701020:Talk02_End"
          }
        },
        [51116030] = {
          ContentFR = "<I>Et si ces sons n’étaient tout simplement... pas agréables à l’oreille ?</>",
          DialogueId = 51116030,
          GUID = "7FF6AFAC",
          NextDialogue = 51116031,
          Subtitle = "Is it possible that the sounds you chose are just... not very pleasant to begin with?"
        },
        [51116031] = {
          ContentFR = "... !",
          DialogueId = 51116031,
          GUID = "7FF6AFD6",
          NextDialogue = 51116032,
          SpeakNpcId = 701020,
          Subtitle = "...!"
        },
        [51116032] = {
          ContentFR = "{性别:Monsieur|Mademoiselle}, votre remarque m’éclaire comme un éclair dans la nuit !",
          DialogueId = 51116032,
          GUID = "7FF6B000",
          NextDialogue = 51116033,
          SpeakNpcId = 701020,
          Subtitle = "Good {性别：sir|lady}, you have enlightened me — with a single remark!",
          TalkActionId = {
            [1] = "701020:Sigh_Start"
          }
        },
        [51116033] = {
          ContentFR = "Voilà donc l’erreur... le choix des sons ! Je vais rentrer et recomposer aussitôt ! Voyons... le croassement des corbeaux, le grignotement des souris, le frottement du métal contre la pierre... oui, cela devrait être parfait !",
          DialogueId = 51116033,
          GUID = "7FF6B02A",
          NextDialogue = 51116034,
          SpeakNpcId = 701020,
          Subtitle = "I see... the choice of sounds was at fault. I must go home and start afresh! Let me think... the cawing of crows, the gnawing of field mice, the scrape of metal on stone... yes, that should do nicely!",
          TalkActionId = {
            [1] = "701020:Sigh_End"
          }
        },
        [51116034] = {
          ContentFR = "Ju Mu semble désormais entièrement absorbé par son « art ». Quoi qu’il en soit, vous avez reçu votre récompense ; mieux vaut vous éclips­er rapidement et préserver vos oreilles.",
          DialogueId = 51116034,
          GUID = "7FF6B054",
          Subtitle = "(Ju Mu is utterly absorbed in his \"art\". Well, you've received your reward — best slip away now and spare your ears while you can.)"
        },
        [51116035] = {
          ContentFR = "Petits oiseaux, renards, chatons sauvages ! Ne fuyez pas ! Écoutez encore un morceau !",
          DialogueId = 51116035,
          GUID = "7FF6B07E",
          SpeakNpcId = 701020,
          Subtitle = "Little birds, little foxes, wild kittens — do not flee! Stay for just one more piece!"
        },
        [51117000] = {
          Camera = "-56.007812,179.976562,127.53125,0.000043,-7.60004,-107.399704,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est forcément un Wishen !",
          DialogueId = 51117000,
          GUID = "7FF74ED0",
          LookAt = {
            [1] = "701021:n(701022)",
            [2] = "701022:n(701021)",
            [3] = "100001:n(701021)"
          },
          NextDialogue = 51117001,
          SpeakNpcId = 701021,
          Subtitle = "It must be a Wishen!",
          TalkActionId = {
            [1] = "701021:Angry01_Start"
          }
        },
        [51117001] = {
          Camera = "-175.459961,-170.417969,118.708984,0.000063,-4.799348,68.995163,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pas du tout ! C’est forcément un Bi’an !",
          DialogueId = 51117001,
          GUID = "7FF74EFA",
          NextDialogue = 51117002,
          SpeakNpcId = 701022,
          Subtitle = "Nah-uh! It's a Bi'an!",
          TalkActionId = {
            [1] = "701022:Angry01_Start"
          }
        },
        [51117002] = {
          Camera = "-102.625977,389.867188,178.47168,0.000117,-10.004881,-94.054535,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "À l’extérieur du Pavillon de l’Éphémère, deux enfants se disputent bruyamment à propos de quelque chose. Vous ralentissez machinalement le pas, attirant leur attention —",
          DialogueId = 51117002,
          GUID = "7FF74F24",
          NextDialogue = 51117003,
          Subtitle = "(Outside the Hall of Ephemerality, two children are loudly arguing about something. You slow your steps without meaning to — and they spot you.)",
          TalkActionId = {
            [1] = "701021:Angry01_End",
            [2] = "701022:Angry01_End"
          }
        },
        [51117003] = {
          ContentFR = "Hé ! {性别:Monsieur|Mademoiselle} ! Vous en pensez quoi ?",
          DialogueId = 51117003,
          GUID = "7FF74F4E",
          LookAt = {
            [1] = "701021:n(100001)",
            [2] = "701022:n(100001)"
          },
          NextOptions = {
            [1] = 51117004
          },
          SpeakNpcId = 701021,
          Subtitle = "{性别：Sir|Miss}! What do you think?"
        },
        [51117004] = {
          ContentFR = "<I>De quoi exactement ?</>",
          DialogueId = 51117004,
          GUID = "7FF74F78",
          NextDialogue = 51117005,
          Subtitle = "Huh?"
        },
        [51117005] = {
          ContentFR = "De cette ombre blanche !",
          DialogueId = 51117005,
          GUID = "7FF74FA2",
          NextDialogue = 51117006,
          SpeakNpcId = 701021,
          Subtitle = "What do you think the white shadow is?",
          TalkActionId = {
            [1] = "701021:Think_Start"
          }
        },
        [51117006] = {
          ContentFR = "Quelle ombre blanche ?",
          DialogueId = 51117006,
          GUID = "7FF74FCC",
          NextDialogue = 51117007,
          SpeakNpcId = 100001,
          Subtitle = "What white shadow?",
          TalkActionId = {
            [1] = "701021:Think_End"
          }
        },
        [51117007] = {
          Camera = "807.511719,-81.339844,690.010742,0.000093,5.194338,77.734879,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Celle qui apparaît dans la maison juste à côté ! On l’a tous vue !",
          DialogueId = 51117007,
          GUID = "7FF74FF6",
          NextDialogue = 51117008,
          SpeakNpcId = 701021,
          Subtitle = "The one that shows up in that house! We all saw it."
        },
        [51117008] = {
          ContentFR = "Elle vole, elle flotte dans les airs, elle apparaît et disparaît d’un coup... À votre avis, c’est quoi ?",
          DialogueId = 51117008,
          GUID = "7FF75020",
          NextDialogue = 51117009,
          SpeakNpcId = 701021,
          Subtitle = "It flies about, floats in mid-air — comes and goes in a flash. What do you think it is?"
        },
        [51117009] = {
          Camera = "-102.625977,389.867188,178.47168,0.000117,-10.004881,-94.054535,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Moi je dis que c’est un Bi’an ! En tant qu’exécuteurs de la loi, ils doivent toujours rester dignes quand il y a du monde. Mais à force, ça doit être épuisant ! Alors ils se faufilent sûrement dans cette maison vide pour jouer un peu.",
          DialogueId = 51117009,
          GUID = "7FF7504A",
          LookAt = {
            [1] = "701021:n(701022)",
            [2] = "701022:n(701021)",
            [3] = "100001:n(701022)"
          },
          NextDialogue = 51117010,
          SpeakNpcId = 701022,
          Subtitle = "I think it's a Bi'an! They're law-keepers, right? They have to act all serious in front of people — must be exhausting! So maybe they sneak into this empty house to run around and play.",
          TalkActionId = {
            [1] = "701022:Talk01_Start"
          }
        },
        [51117010] = {
          ContentFR = "N’importe quoi ! Les Bi’an sont les émissaires des Neuf Chapitres de Dafeng, pas des chiens de compagnie ! Et puis cette maison n’est plus vide, quelqu’un y vit maintenant.",
          DialogueId = 51117010,
          GUID = "7FF75074",
          LookAt = {
            [1] = "100001:n(701021)"
          },
          NextDialogue = 51117011,
          SpeakNpcId = 701021,
          Subtitle = "No way! A Bi'an's an enforcer of the Nine Chapters — it's not your pet dog. They don't need to play! And someone lives in that house now — it's not empty anymore.",
          TalkActionId = {
            [1] = "701022:Talk01_End"
          }
        },
        [51117011] = {
          ContentFR = "Moi, je pense que c’est forcément un Wishen. Peut-être l’ancien propriétaire de la maison... Trop attaché à cet endroit pour accepter de partir.",
          DialogueId = 51117011,
          GUID = "7FF7509E",
          NextDialogue = 51117012,
          SpeakNpcId = 701021,
          Subtitle = "I think the white shadow must be a Wishen! Maybe the last owner turned into one — they loved the house so much they never wanted to leave...",
          TalkActionId = {
            [1] = "701021:Talk02_Start"
          }
        },
        [51117012] = {
          ContentFR = "Si c’était vraiment l’ancien propriétaire, pourquoi il n’apparaîtrait que maintenant ?",
          DialogueId = 51117012,
          GUID = "7FF750C8",
          LookAt = {
            [1] = "100001:n(701022)"
          },
          NextDialogue = 51117013,
          SpeakNpcId = 701022,
          Subtitle = "If it really was the owner, why would it only show up now?",
          TalkActionId = {
            [1] = "701021:Talk02_End"
          }
        },
        [51117013] = {
          ContentFR = "Les Wishen peuvent vivre très, très longtemps ! Peut-être qu’il était simplement parti se promener avant !",
          DialogueId = 51117013,
          GUID = "7FF750F2",
          LookAt = {
            [1] = "100001:n(701021)"
          },
          NextDialogue = 51117014,
          SpeakNpcId = 701021,
          Subtitle = "Wishen can live for ages — maybe it was just out playing before!"
        },
        [51117014] = {
          ContentFR = "Mais les Wishen ne sont pas blancs !",
          DialogueId = 51117014,
          GUID = "7FF7511C",
          LookAt = {
            [1] = "100001:n(701022)"
          },
          NextDialogue = 51117015,
          SpeakNpcId = 701022,
          Subtitle = "But Wishen aren't even white!",
          TalkActionId = {
            [1] = "701022:Explain01_Start"
          }
        },
        [51117015] = {
          ContentFR = "Et comment tu sais qu’il n’existe pas de Wishen blancs ? Les Wishen peuvent voler, les Bi’an non !",
          DialogueId = 51117015,
          GUID = "7FF75146",
          LookAt = {
            [1] = "100001:n(701021)"
          },
          NextDialogue = 51117016,
          SpeakNpcId = 701021,
          Subtitle = "How do you know there aren't white Wishen? Wishen can fly — Bi'an can't!",
          TalkActionId = {
            [1] = "701022:Explain01_End"
          }
        },
        [51117016] = {
          ContentFR = "Et comment tu sais qu’il n’existe pas de Bi’an qui volent ?",
          DialogueId = 51117016,
          GUID = "7FF75170",
          LookAt = {
            [1] = "100001:n(701022)"
          },
          NextDialogue = 51117017,
          SpeakNpcId = 701022,
          Subtitle = "Then how do you know there aren't flying Bi'an?"
        },
        [51117017] = {
          ContentFR = "... <I>Hmpf !</> {性别:Monsieur|Mademoiselle}, dites-nous : Wishen ou Bi’an ?",
          DialogueId = 51117017,
          GUID = "7FF7519A",
          LookAt = {
            [1] = "701021:n(100001)",
            [2] = "701022:n(100001)"
          },
          NextOptions = {
            [1] = 51117018
          },
          RestartTag = 51117017,
          SpeakNpcId = 701021,
          Subtitle = "...Hmph! {性别：Sir|Miss}, what do you think? Wishen or Bi'an?"
        },
        [51117018] = {
          ContentFR = "<I>Une ombre blanche... qu’est-ce que ça pourrait bien être ?</>",
          DialogueId = 51117018,
          FailDialogue = 51117019,
          GUID = "7FF751C4",
          ImprCheckId = 1125,
          NextDialogue = 51117020,
          Subtitle = "(A white shadow... what could it be?)"
        },
        [51117019] = {
          ContentFR = "Aucune idée ne vous vient.",
          DialogueId = 51117019,
          GUID = "7FF751EE",
          Subtitle = "(Nothing comes to mind.)"
        },
        [51117020] = {
          ContentFR = "Je pense que vous avez tous les deux tort. À mon avis, c’est simplement le petit animal de compagnie de la personne qui habite ici.",
          DialogueId = 51117020,
          GUID = "7FF75218",
          NextDialogue = 51117021,
          SpeakNpcId = 100001,
          Subtitle = "I don't think either of you got it right. My guess? It's just the resident's pet.",
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51117021] = {
          ContentFR = "Hein... ?",
          DialogueId = 51117021,
          GUID = "7FF75242",
          NextDialogue = 51117022,
          SpeakNpcId = 701021,
          Subtitle = "Huh...?"
        },
        [51117022] = {
          ContentFR = "Un animal de compagnie ? Comme un chat ou un chien ? Mais cette ombre disparaît instantanément !",
          DialogueId = 51117022,
          GUID = "7FF7526C",
          NextDialogue = 51117023,
          SpeakNpcId = 701021,
          Subtitle = "A pet? Like a cat or a dog? But the shadow disappears so fast!",
          TalkActionId = {
            [1] = "701021:Talk02_Start"
          }
        },
        [51117023] = {
          ContentFR = "Oui ! Et parfois elle va super vite, encore plus vite que notre chat quand il sursaute à cause du rouleau à pâtisserie !",
          DialogueId = 51117023,
          GUID = "7FF75296",
          NextDialogue = 51117024,
          SpeakNpcId = 701022,
          Subtitle = "Yeah! And sometimes it moves even faster than our cat when it leaps up after getting scared by the rolling pin!",
          TalkActionId = {
            [1] = "701022:Think_Start",
            [2] = "701021:Talk02_End"
          }
        },
        [51117024] = {
          ContentFR = "Si vous ne me croyez pas, vous n’avez qu’à aller frapper à la porte et demander.",
          DialogueId = 51117024,
          GUID = "7FF752C0",
          NextDialogue = 51117025,
          SpeakNpcId = 100001,
          Subtitle = "If you don't believe me, you could always knock on the door and ask.",
          TalkActionId = {
            [1] = "701022:Think_End"
          }
        },
        [51117025] = {
          ContentFR = "M-Mais... la personne qui habite là est une inconnue...",
          DialogueId = 51117025,
          GUID = "7FF752EA",
          NextDialogue = 51117026,
          SpeakNpcId = 701021,
          Subtitle = "B—But the person inside is a stranger...",
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51117026] = {
          ContentFR = "Ma grand-mère dit que c’est quelqu’un de très important. Et si on la mettait en colère ?",
          DialogueId = 51117026,
          GUID = "7FF75314",
          NextDialogue = 51117028,
          SpeakNpcId = 701022,
          Subtitle = "My gran says someone really important lives in there. What if they get angry with us?"
        },
        [51117027] = {
          ContentFR = "Un troisième enfant s’approche.",
          DialogueId = 51117027,
          GUID = "7FF7533E",
          Subtitle = "(A third child trots over.)"
        },
        [51117028] = {
          Camera = "-183.449219,717.648438,135.62793,0.000058,-3.004539,-77.045387,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh ? Lan Ye, Wang Nan, qu’est-ce que vous faites ici ?",
          DialogueId = 51117028,
          GUID = "7FF75368",
          LookAt = {
