        [51117043] = {
          ContentFR = "Alors on avait tous raison ! Trop bien~",
          DialogueId = 51117043,
          GUID = "7FF755DE",
          LookAt = {
            [1] = "701021:n(701022)",
            [2] = "701022:n(701022)",
