          NextDialogue = 51117048,
          SpeakNpcId = 701022,
          Subtitle = "Then we were all right! Yay~!",
          TalkActionId = {
            [1] = "701021:Talk01_End"
          }
        },
        [51117044] = {
          ContentFR = "<I>Héhé, c’est ça la puissance des adultes.</>",
          DialogueId = 51117044,
          GUID = "7FF75608",
          ImprPlusId = 1210,
          NextDialogue = 51117045,
          Subtitle = "Heh-heh~ I know that because I'm a smart grown-up."
        },
        [51117045] = {
          ContentFR = "Quand je serai grand, je serai aussi intelligent !",
          DialogueId = 51117045,
          GUID = "7FF75632",
          LookAt = {
            [1] = "701021:n(701022)",
            [2] = "701022:n(701022)",
            [3] = "100001:n(701022)",
            [4] = "701023:n(701022)"
          },
          NextDialogue = 51117046,
