            [1] = "701022:Talk01_Start"
          }
        },
        [51117046] = {
          ContentFR = "Moi, je serai encore plus intelligent que {性别:ce Monsieur|cette Mademoiselle} !",
          DialogueId = 51117046,
          GUID = "7FF7565C",
          LookAt = {
            [1] = "701021:n(701022)",
            [2] = "701022:n(701022)",
            [3] = "100001:n(701022)",
            [4] = "701023:n(701022)"
          },
          NextDialogue = 51117047,
          SpeakNpcId = 701021,
          Subtitle = "Then I'll be even smarter!",
          TalkActionId = {
            [1] = "701022:Talk01_End"
          }
        },
        [51117047] = {
          ContentFR = "Dans ce cas, pourquoi vous traînez encore ici ? Allez faire vos devoirs ! Rester à bavarder ne vous rendra pas plus malins.",
          DialogueId = 51117047,
          GUID = "7FF75686",
          LookAt = {
            [1] = "701021:n(701023)",
            [2] = "701022:n(701023)",
            [3] = "100001:n(701023)",
            [4] = "701023:n(701023)"
          },
          NextDialogue = 51117048,
          SpeakNpcId = 701023,
          Subtitle = "Then what are the two of you still standing here for? Messing about won't make you smarter. Go on — get your homework done!"
        },
        [51117048] = {
          ContentFR = "Les enfants s’en vont en riant. Peut-être que la prochaine fois que vous verrez Fushu, vous pourrez lui raconter cette amusante anecdote.",
          DialogueId = 51117048,
          GUID = "7FF756B0",
          Scripts = [[
