        [51118024] = {
          ContentFR = "D’accord, je m’en souviendrai.",
          DialogueId = 51118024,
          GUID = "7FF7F6D0",
          NextDialogue = 51118025,
          SpeakNpcId = 100001,
          Subtitle = "Got it."
        },
        [51118025] = {
          ContentFR = "La fillette se frotte les yeux et rentre en titubant à l’intérieur. Vous vous placez dans un coin et observez discrètement.",
          DialogueId = 51118025,
          GUID = "7FF7F6FA",
          Subtitle = "(Nodding drowsily, she totters indoors. You move to a corner and watch in silence.)"
        },
        [51118026] = {
          ContentFR = "Comme prévu, peu de temps après son départ, un jeune homme apparaît. Il regarde autour de lui, dépose rapidement un paquet devant la porte, puis s’apprête à partir.",
          DialogueId = 51118026,
          GUID = "7FF7F724",
          Subtitle = "(And sure enough — not long after she leaves, a young man appears. He glances around, sets a parcel at the door in haste, and turns to go.)"
        },
        [51118027] = {
          ContentFR = "Attendez !",
          DialogueId = 51118027,
          GUID = "7FF7F74E",
          LookAt = {
            [1] = "701025:n(0)"
          },
          NextDialogue = 51118028,
          SpeakNpcId = 100001,
          Subtitle = "Wait!"
        },
        [51118028] = {
          ContentFR = "Hein ?!",
          DialogueId = 51118028,
          GUID = "7FF7F778",
          NextDialogue = 51118029,
          SpeakNpcId = 701025,
          Subtitle = "Huh!?",
          TalkActionId = {
            [1] = "701025:Shock_Start"
          }
        },
        [51118029] = {
          ContentFR = "Vous êtes Zhaoyu, n’est-ce pas ?",
          DialogueId = 51118029,
          GUID = "7FF7F7A2",
          NextDialogue = 51118030,
          SpeakNpcId = 100001,
          Subtitle = "You're Zhaoyu, aren't you?"
        },
        [51118030] = {
          ContentFR = "À l’évocation de ce nom, l’homme se fige. Après un long silence, il prend la parole.",
          DialogueId = 51118030,
          GUID = "7FF7F7CC",
          NextDialogue = 51118031,
          Subtitle = "(He freezes at the name, then after a long silence finally speaks.)",
          TalkActionId = {
            [1] = "701025:Shock_End"
          }
        },
        [51118031] = {
          ContentFR = "Non... je ne suis pas Zhaoyu.",
          DialogueId = 51118031,
          GUID = "7FF7F7F6",
          NextDialogue = 51118032,
          SpeakNpcId = 701025,
          Subtitle = "No... I'm not Zhaoyu.",
          TalkActionId = {
            [1] = "701025:Talk01_Start"
          }
        },
        [51118032] = {
          ContentFR = "Pourquoi connaissez-vous ce nom ? Le connaissez-vous ?",
          DialogueId = 51118032,
          GUID = "7FF7F820",
          NextDialogue = 51118033,
          SpeakNpcId = 701025,
          Subtitle = "How did you know that name? Do you know him?"
        },
        [51118033] = {
          ContentFR = "Je connais sa petite sœur. Elle l’attend ici depuis des heures.",
          DialogueId = 51118033,
          GUID = "7FF7F84A",
          NextDialogue = 51118034,
          SpeakNpcId = 100001,
          Subtitle = "I know his little sister. She's been expecting him."
        },
        [51118034] = {
          ContentFR = "... Je vois. Alors Qingqing attendait son frère.",
          DialogueId = 51118034,
          GUID = "7FF7F874",
          NextDialogue = 51118035,
          SpeakNpcId = 701025,
          Subtitle = "...So Qingqing sat here because she wanted to see her brother. I see.",
          TalkActionId = {
            [1] = "701025:Talk01_End"
          }
        },
        [51118035] = {
          ContentFR = "Mais... elle ne pourra plus l’attendre.",
          DialogueId = 51118035,
          GUID = "7FF7F89E",
          NextDialogue = 51118036,
          SpeakNpcId = 701025,
          Subtitle = "But... she won't be able to."
        },
        [51118036] = {
          ContentFR = "Pourquoi ? Qui êtes-vous ?",
          DialogueId = 51118036,
          GUID = "7FF7F8C8",
          NextDialogue = 51118037,
          SpeakNpcId = 100001,
          Subtitle = "Why? Who are you?"
        },
        [51118037] = {
          ContentFR = "Je suis un vieil ami de Zhaoyu. Il y a quelques années, nous faisions partie du même convoi marchand en mer... Nous avons fait naufrage. Zhaoyu est mort en essayant de me sauver. Je ne savais pas nager.",
          DialogueId = 51118037,
          GUID = "7FF7F8F2",
          NextDialogue = 51118038,
          SpeakNpcId = 701025,
          Subtitle = "An old friend of his. Years ago, our caravan took ship for an overseas trade. The ship went down, and... Zhaoyu died saving me. I couldn't swim.",
          TalkActionId = {
            [1] = "701025:Talk02_Start"
          }
        },
        [51118038] = {
          ContentFR = "Je ne pourrai jamais lui rendre cette dette... Mais je ne supportais pas l’idée que la petite sœur qu’il chérissait vive dans le chagrin.",
          DialogueId = 51118038,
          GUID = "7FF7F91C",
          NextDialogue = 51118039,
          SpeakNpcId = 701025,
          Subtitle = "I can never repay him. But I couldn't bear the thought of the little sister he cherished falling into grief. So I started doing this."
        },
        [51118039] = {
          ContentFR = "Alors j’ai décidé de prendre sa place. Jusqu’à ce que Qingqing devienne adulte, je lui apporterai chaque année des cadeaux et des lettres, comme s’il était encore en vie.",
          DialogueId = 51118039,
          GUID = "7FF7F946",
          NextDialogue = 51118040,
          SpeakNpcId = 701025,
          Subtitle = "Until she grows up, I'll bring gifts and letters in his place. Every year."
        },
        [51118040] = {
          ContentFR = "... Je comprends.",
          DialogueId = 51118040,
          GUID = "7FF7F970",
          NextDialogue = 51118041,
          SpeakNpcId = 100001,
          Subtitle = "...I see."
        },
        [51118041] = {
          ContentFR = "Alors, je vous en prie... gardez le secret pour elle.",
          DialogueId = 51118041,
          GUID = "7FF7F99A",
          NextDialogue = 51118042,
          SpeakNpcId = 701025,
          Subtitle = "So please — don't tell her.",
          TalkActionId = {
            [1] = "701025:Talk02_End"
          }
        },
        [51118042] = {
          ContentFR = "Je le ferai.",
          DialogueId = 51118042,
          GUID = "7FF7F9C4",
          SpeakNpcId = 100001,
          Subtitle = "I understand."
        },
        [51118043] = {
          Camera = "-82.615234,229.359375,122.754883,0.0,-0.800191,-69.000504,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Après un instant de réflexion, vous frappez doucement à la porte.",
          DialogueId = 51118043,
          GUID = "7FF7F9EE",
          IsBlack = 1,
          LookAt = {
            [1] = "701024:n(100001)",
            [2] = "100001:n(701024)"
          },
          NextDialogue = 51118062,
          Subtitle = "(After thinking for a moment, you knock gently on the door.)"
        },
        [51118044] = {
          ContentFR = "<I>Qingqing ?</>",
          DialogueId = 51118044,
          GUID = "7FF7FA18",
          IsBlack = 1,
          NextDialogue = 51118045,
          Subtitle = "Qingqing?"
        },
        [51118045] = {
          ContentFR = "Oui ? {性别:Monsieur|Mademoiselle} ? Eh ? C’est quoi, ce paquet... ? Mon frère est venu ? Où est-il ?",
          DialogueId = 51118045,
          GUID = "7FF7FA42",
          NextDialogue = 51118046,
          SpeakNpcId = 701024,
          Subtitle = "What is it, {性别：sir|miss}? Eh — what's that in your hands...? Did my brother come? Where is he?",
          TalkActionId = {
            [1] = "701024:Talk01_Start"
          }
        },
        [51118046] = {
          ContentFR = "Il est déjà reparti.",
          DialogueId = 51118046,
          GUID = "7FF7FA6C",
          NextDialogue = 51118047,
          SpeakNpcId = 100001,
          Subtitle = "He's already gone.",
          TalkActionId = {
            [1] = "701024:Talk01_End",
            [2] = "100001:Talk02_Start"
          }
        },
        [51118047] = {
          ContentFR = "Quoi ?! Mais tu avais promis de l’arrêter... <I>snif...</>",
          DialogueId = 51118047,
          GUID = "7FF7FA96",
          NextOptions = {
            [1] = 51118048,
            [2] = 51118052
          },
          SpeakNpcId = 701024,
          Subtitle = "What!? But you said you'd stop him... sniff...",
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51118048] = {
          ContentFR = "<I>Ton frère travaille très dur. Il ne voulait pas t’inquiéter.</>",
          DialogueId = 51118048,
          GUID = "7FF7FAC0",
          ImprPlusId = 1209,
          NextDialogue = 51118049,
          Subtitle = "Your brother's working hard and doesn't want you to worry."
        },
        [51118049] = {
          ContentFR = "Il m’a dit qu’il vivait dehors depuis longtemps, qu’il avait beaucoup maigri... Il avait peur que tu t’inquiètes en le voyant. Il avait l’air très fatigué, alors je ne l’ai pas retenu.",
          DialogueId = 51118049,
          GUID = "7FF7FAEA",
          NextDialogue = 51118050,
          SpeakNpcId = 100001,
          Subtitle = "He said he's out in all weathers and has grown thin — he didn't want you to see him like that. He looked exhausted, so I didn't force him to stay.",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51118050] = {
          ContentFR = "Vraiment... ? Mais ne pas le voir m’inquiète encore plus... quel idiot...",
          DialogueId = 51118050,
          GUID = "7FF7FB14",
          NextDialogue = 51118051,
          SpeakNpcId = 701024,
          Subtitle = "Is that so...? But not seeing him makes me worry even more... He's so silly...",
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "701024:Think_Start"
          }
        },
        [51118051] = {
          ContentFR = "Il a dit que lorsqu’il irait un peu mieux, il reviendrait te voir. En attendant, tu dois bien prendre soin de toi.",
          DialogueId = 51118051,
          GUID = "7FF7FB3E",
          NextDialogue = 51118058,
          SpeakNpcId = 100001,
          Subtitle = "He said once he's better, he'll come back to see you. Until then, make sure you look after yourself.",
          TalkActionId = {
            [1] = "701024:Think_End"
          }
        },
        [51118052] = {
          ContentFR = "<I>Ton frère participe à une grande « guerre commerciale ». Chaque seconde compte !</>",
          DialogueId = 51118052,
          GUID = "7FF7FB68",
          ImprPlusId = 1208,
          NextDialogue = 51118053,
          Subtitle = "Your brother's in a big business war — every second counts!"
        },
        [51118053] = {
          ContentFR = "Une... guerre commerciale ? C’est quoi ?",
          DialogueId = 51118053,
          GUID = "7FF7FB92",
          NextDialogue = 51118054,
          SpeakNpcId = 701024,
          Subtitle = "A... business war? What's that?",
          TalkActionId = {
            [1] = "701024:Think_Start"
          }
        },
        [51118054] = {
          ContentFR = "C’est un jeu pour savoir qui gagne le plus d’argent, le plus vite. Ton frère veut arriver premier, alors il ne peut pas perdre une seule seconde.",
          DialogueId = 51118054,
          GUID = "7FF7FBBC",
          NextDialogue = 51118055,
          SpeakNpcId = 100001,
          Subtitle = "A game to see who can earn the most money the fastest. He wants first place — he can't spare even a second!",
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51118055] = {
          ContentFR = "Il a déposé le cadeau et est reparti aussitôt. Ce sont ses collègues qui me l’ont expliqué.",
          DialogueId = 51118055,
          GUID = "7FF7FBE6",
          NextDialogue = 51118056,
          SpeakNpcId = 100001,
          Subtitle = "He dropped the present and rushed off — I only learned what happened from his colleague.",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          }
        },
        [51118056] = {
          ContentFR = "Ah d’accord ! Alors je vais l’encourager !",
          DialogueId = 51118056,
          GUID = "7FF7FC10",
          NextDialogue = 51118057,
          SpeakNpcId = 701024,
          Subtitle = "I see! Then I'll go cheer him on!",
          TalkActionId = {
            [1] = "701024:Think_End"
          }
        },
        [51118057] = {
          ContentFR = "Il a dit que tu devais simplement bien prendre soin de toi. Quand il gagnera, il reviendra te voir.",
          DialogueId = 51118057,
          GUID = "7FF7FC3A",
          NextDialogue = 51118058,
          SpeakNpcId = 100001,
          Subtitle = "He said you just need to take good care of yourself. When he wins, he'll come home to see you."
        }
      }
    end
  },
  {
    MinKey = 51118058,
    MaxKey = 51125007,
    Loader = function()
      return {
        [51118058] = {
          ContentFR = "Alors je vais rentrer dormir un peu... sinon, il va s’inquiéter...",
          DialogueId = 51118058,
          GUID = "7FF7FC64",
          NextDialogue = 51118059,
          SpeakNpcId = 701024,
          Subtitle = "Okay! I'll go sleep a little... or he'll worry...",
          TalkActionId = {
            [1] = "701024:Talk02_Start"
          }
        },
        [51118059] = {
          ContentFR = "Merci pour ton aide, {性别:Monsieur|Mademoiselle}... à bientôt... <I>haaawn...</>",
          DialogueId = 51118059,
          GUID = "7FF7FC8E",
          NextDialogue = 51118060,
          SpeakNpcId = 701024,
          Subtitle = "Thank you for helping me, {性别：sir|miss}! See you... yaaawn...",
          TalkActionId = {
            [1] = "701024:Talk02_End"
          }
        },
        [51118060] = {
          ContentFR = "La fillette vous remet votre récompense, prend son cadeau avec un sourire apaisé, puis rentre à l’intérieur.",
          DialogueId = 51118060,
          GUID = "7FF7FCB8",
          NextDialogue = 51118061,
          Subtitle = "(She pays you, takes her gift with a contented smile, and slips inside.)"
        },
        [51118061] = {
          ContentFR = "Lorsque la vérité éclatera un jour... pourra-t-elle encore sourire ainsi ?",
          DialogueId = 51118061,
          GUID = "7FF7FCE2",
          Subtitle = "(When she learns the truth one day... may it not take that smile from her...)"
        },
        [51118062] = {
          Content = "（青青打着哈欠走了出来。）",
          DialogueId = 51118062,
          GUID = "7FF7FD0C",
          IsBlack = 1,
          NextOptions = {
            [1] = 51118044
          },
          Subtitle = "(Qingqing walks out, yawning.)"
        },
        [51119000] = {
          ContentFR = "D’un mot, le Dragon d’Argent descend, d’un éventail, l’histoire prend son élan. Chers voisins, honorables anciens, voyageurs venus de loin jusqu’à Huaxu, accordez-moi un instant !",
          DialogueId = 51119000,
          GUID = "7FF896F0",
          NextDialogue = 51119001,
          SpeakNpcId = 701026,
          Subtitle = "A flick of the fan, and a tale flies on the wind! Good folks, neighbours, travellers from near and far — gather round and lend an ear!",
          TalkActionId = {
            [1] = "701026:Talk01_Start"
          }
        },
        [51119001] = {
          ContentFR = "Je me nomme Quan Doutong. Il fut un temps où le Seigneur Dragon d’Argent me gratifia d’un titre — Maître-Qui-Sait-Tout. J’ai pour plaisir de partager avec mes proches et amis les mille curiosités du monde, et justement, aujourd’hui, j’ai une anecdote savoureuse à vous conter.",
          DialogueId = 51119001,
          GUID = "7FF8971A",
          NextDialogue = 51119002,
          SpeakNpcId = 701026,
          Subtitle = "Name's Quan Doutong — yes, the very man Lord Argent once honoured with the title \"Mr Knows-It-All\". I enjoy sharing a story or two with anyone willing to listen — and today I've a fresh one."
        },
        [51119002] = {
          ContentFR = "Mais hélas... la chaleur est étouffante, et ma gorge est aussi sèche qu’un parchemin ancien. Si quelques âmes généreuses consentaient à me donner un peu d’argent\npour acheter une théière et m’humecter le gosier, alors ce récit n’en serait que meilleur.",
          DialogueId = 51119002,
          GUID = "7FF89744",
          LookAt = {
            [1] = "701026:n(0)"
          },
          NextOptions = {
            [1] = 51119003,
            [2] = 51119005,
            [3] = 51119007
          },
          SpeakNpcId = 701026,
          Subtitle = "Only thing is... the heat's fierce today, and my throat's dry as an old scroll. If a few kind souls could spare a bit of silver for a pot of tea, the tale would flow a good deal smoother.",
          TalkActionId = {
            [1] = "701026:Talk01_End"
          }
        },
        [51119003] = {
          ContentFR = "<I>Le Seigneur Dragon d’Argent t’aurait accordé un titre ? Tu inventes, non ?</>",
          DialogueId = 51119003,
          GUID = "7FF8976E",
          ImprPlusId = 1208,
          NextDialogue = 51119004,
          Subtitle = "Lord Argent granted you a title? Yeah, right."
        },
        [51119004] = {
          ContentFR = "Certes, ce titre est une invention — le Seigneur Dragon d’Argent ne m’a jamais honoré ainsi. Mais sans un peu d’emphase, comment espérer retenir votre attention ? Et même s’il l’apprenait, j’ose croire qu’il ne m’en tiendrait pas rigueur.",
          DialogueId = 51119004,
          GUID = "7FF89798",
          NextDialogue = 51119009,
          SpeakNpcId = 701026,
          Subtitle = "Aye, fine — I made it up. Lord Argent's never said a word to me. But if I don't dress things up a bit, who's going to stop and listen? And should Lord Argent catch wind of it, I reckon he'll forgive a storyteller his little embellishments."
        },
        [51119005] = {
          ContentFR = "<I>Encore faut-il que l’histoire en vaille la peine.</>",
          DialogueId = 51119005,
          GUID = "7FF897C2",
          ImprPlusId = 1206,
          NextDialogue = 51119006,
          Subtitle = "Then you'd better earn it with a decent tale."
        },
        [51119006] = {
          ContentFR = "L’{性别:étranger|étrangère} a raison. Tout ceci repose sur le volontariat, jamais sur la contrainte. Je me demande seulement si quelques respectables habitants souhaitent offrir une gorgée d’eau à un conteur dévoué au Dragon d’Argent, afin d’apaiser sa gorge en feu.",
          DialogueId = 51119006,
          GUID = "7FF897EC",
          NextDialogue = 51119009,
          SpeakNpcId = 701026,
          Subtitle = "True enough! I'm only asking for a small donation out of goodwill — no one's twisting arms here. Just seeing whether anyone's kind enough to help a thirsty storyteller — one favoured by Lord Argent — wet his throat."
        },
        [51119007] = {
          ContentFR = "<I>Donner quelques pièces pour acheter du thé</>",
          DialogueId = 51119007,
          GUID = "7FF89816",
          ImprPlusId = 1209,
          NextDialogue = 51119008,
          Subtitle = "(Give him some silver for tea.)"
        },
        [51119008] = {
          ContentFR = "Mille mercis, {性别:étranger|étrangère}. Je n’oublierai pas cette générosité.",
          DialogueId = 51119008,
          GUID = "7FF89840",
          NextDialogue = 51119009,
          SpeakNpcId = 701026,
          Subtitle = "Many thanks, traveller — I'll remember the kindness."
        },
        [51119009] = {
          ContentFR = "Quelques spectateurs aisés tendent des pièces. Un porteur de thé accourt depuis le fond de la rue. Quan Doutong saisit la théière de terre cuite, en boit une longue gorgée, puis reprend son récit.",
          DialogueId = 51119009,
          GUID = "7FF8986A",
          NextDialogue = 51119010,
          Subtitle = "(A few generous onlookers toss over some silver coins. Before long, a tea-seller trots up with a clay pot. Quan Doutong snatches it up, takes a long, satisfied gulp, wipes his mouth, and carries on.)"
        },
        [51119010] = {
          ContentFR = "Merci de votre confiance. Aujourd’hui, moi, Quan Doutong, vais vous conter une histoire que j’ai entendue tout récemment.",
          DialogueId = 51119010,
          GUID = "7FF89894",
          NextDialogue = 51119011,
          SpeakNpcId = 701026,
          Subtitle = "Right then! Thanks for the tea. Now gather close — I've a brand-new tale fresh from the streets.",
          TalkActionId = {
            [1] = "701026:Talk02_Start"
          }
        },
        [51119011] = {
          ContentFR = "À Huaxu, quel lieu est le plus florissant ? Haojing, bien sûr. Et c’est précisément là-bas que notre histoire commence. Dans Haojing, il existait une ruelle étroite. De chaque côté vivaient deux familles : l’une se nommait Lü, l’autre Ma.",
          DialogueId = 51119011,
          GUID = "7FF898BE",
          NextDialogue = 51119012,
          SpeakNpcId = 701026,
          Subtitle = "Where's the busiest place in all Huaxu? Haojing, of course — and that's where our story begins. Tucked away in one of its narrow little lanes lived two households: the Lyus on one side, the Mas on the other."
        },
        [51119012] = {
          ContentFR = "Ces deux foyers vivaient d’ordinaire en parfaite harmonie, se respectant comme de véritables invités l’un envers l’autre. Mais le temps changea, et le Bureau de la Fortune Céleste de Haojing, souhaitant restaurer de nombreuses habitations délabrées, exigea que chaque famille déclare la superficie de son logement.",
          DialogueId = 51119012,
          GUID = "7FF898E8",
          NextDialogue = 51119013,
          SpeakNpcId = 701026,
          Subtitle = "They usually rubbed along well enough — polite, neighbourly, never a harsh word. But then the Ministry of Fortune announced that, with so many old houses falling into disrepair, they were organising restoration works — which meant every household now had to report the size of its property."
        },
        [51119013] = {
          ContentFR = "Or, la surface déclarée déterminait la somme que le Bureau de la Fortune Céleste devait verser. Désireuses d’attirer davantage de faveur, les familles Lü et Ma se mirent, sans se concerter, à envisager un agrandissement.",
          DialogueId = 51119013,
          GUID = "7FF89912",
          NextDialogue = 51119014,
          SpeakNpcId = 701026,
          Subtitle = "And that, dear guests, is where things took a turn. The larger the area you reported, the more silver the Ministry would hand out for repairs. So both families — without comparing notes — began thinking the same thought: \"What if we just stretched the numbers a touch?\""
        },
        [51119014] = {
          ContentFR = "Mais le terrain situé entre les deux maisons n’appartenait officiellement à aucune d’elles, et aucun document n’en précisait la propriété. Ainsi, la situation se retrouva dans une impasse.",
          DialogueId = 51119014,
          GUID = "7FF8993C",
          NextDialogue = 51119015,
          SpeakNpcId = 701026,
          Subtitle = "The snag was that the strip of ground in the lane belonged to no one — not a single record said whose it was. And just like that, they were at a standstill."
        },
        [51119015] = {
          ContentFR = "La famille Lü déclara qu’un poirier poussait dans sa cour et que son ombre couvrait déjà la ruelle : le terrain devait donc lui revenir.",
          DialogueId = 51119015,
          GUID = "7FF89966",
          NextDialogue = 51119016,
          SpeakNpcId = 701026,
          Subtitle = "The Lyus said, \"Our pear tree throws its shade over the lane — so the land must be ours!\""
        },
        [51119016] = {
          ContentFR = "La famille Ma répliqua qu’elle y faisait sécher ses épices depuis des années, sans jamais rencontrer d’opposition — preuve que cette terre était la sienne.",
          DialogueId = 51119016,
          GUID = "7FF89990",
          NextDialogue = 51119017,
          SpeakNpcId = 701026,
          Subtitle = "The Mas shot back, \"We've dried our spices there for years, and you never complained! That makes it ours!\""
        },
        [51119017] = {
          ContentFR = "Chacun campait sur ses positions, et la dispute devint si violente que, sans la présence des Neuf Chapitres de Dafeng, ils en seraient venus aux mains.",
          DialogueId = 51119017,
          GUID = "7FF899BA",
          NextDialogue = 51119018,
          SpeakNpcId = 701026,
          Subtitle = "Soon enough they were bickering loud enough to shake the roof tiles loose. If not for the Nine Chapters of Dafeng, they'd have been rolling on the ground wrestling like street dogs.",
          TalkActionId = {
            [1] = "701026:Talk02_End"
          }
        },
        [51119018] = {
          ContentFR = "Mais puisque chacun avait ses raisons, fallait-il vraiment admettre qu’il n’existait aucune solution ?",
          DialogueId = 51119018,
          GUID = "7FF899E4",
          NextDialogue = 51119019,
          SpeakNpcId = 701026,
          Subtitle = "Each side had its reasons — so how could the dispute be settled?"
        },
        [51119019] = {
          ContentFR = "Quan Doutong marque volontairement une pause, entretenant le suspense.",
          DialogueId = 51119019,
          GUID = "7FF89A0E",
          NextDialogue = 51119020,
          Subtitle = "(He pauses dramatically, milking the moment.)"
        },
        [51119020] = {
          ContentFR = "N’oubliez pas : nous sommes à Haojing, où ne manquent pas les médiateurs chargés\nde régler les conflits de voisinage.",
          DialogueId = 51119020,
          GUID = "7FF89A38",
          NextDialogue = 51119021,
          SpeakNpcId = 701026,
          Subtitle = "Now, remember — this is Haojing, a city full of folk who make their living sorting out neighbourly quarrels.",
          TalkActionId = {
            [1] = "701026:Explain01_Start"
          }
        },
        [51119021] = {
          ContentFR = "L’un d’eux, averti de l’affaire, accourut sans tarder. Après avoir écouté les deux parties, il esquissa un sourire discret et improvisa un poème :",
          DialogueId = 51119021,
          GUID = "7FF89A62",
          NextDialogue = 51119022,
          SpeakNpcId = 701026,
          Subtitle = "So one such mediator caught wind of the fuss and hurried over at once. He hears them out, smiles, and rattles off a verse on the spot:"
        },
        [51119022] = {
          ContentFR = "« Le dragon noir attise les pensées mauvaises, la colère du Dragon d’Argent tranche l’avidité. Les querelles vaines sèment le chaos — céder trois pas, n’est-ce pas sagesse ? »",
          DialogueId = 51119022,
          GUID = "7FF89A8C",
          NextDialogue = 51119023,
          SpeakNpcId = 701026,
          Subtitle = "\"The black loong stirs up the worst in men; Lord Argent's wrath checks greed and pain. Rows flare bright then fade in vain — yield three feet, and peace shall remain.\""
        },
        [51119023] = {
          ContentFR = "Voyez-vous le sens de ces vers ? Il comparait les deux familles au dragon noir malfaisant des légendes, s’opposant aux enseignements bienveillants du Dragon d’Argent.",
          DialogueId = 51119023,
          GUID = "7FF89AB6",
          NextDialogue = 51119024,
          SpeakNpcId = 701026,
          Subtitle = "Aha! See his point, good folk? He likened the two families to that wicked black loong of legend — saying they'd forgotten Lord Argent's teachings!"
        },
        [51119024] = {
          ContentFR = "Le monstre Zhuyin, rongé par la malveillance, fut jadis scellé dans les terres sauvages par le Dragon d’Argent. Alors pourquoi, en cette noble Huaxu, laisser naître l’avidité et la colère ? À ces mots, les deux familles, honteuses, cessèrent leur querelle et rentrèrent chez elles.",
          DialogueId = 51119024,
          GUID = "7FF89AE0",
          NextDialogue = 51119025,
          SpeakNpcId = 701026,
          Subtitle = "Even Zhuyin was sealed away by Lord Argent for its wickedness — so why should decent folk in fair Huaxu behave with such greed and temper today? Hearing that, both families fell silent. Their faces went red as cooked prawns, and they slunk back home without another word."
        },
        [51119025] = {
          ContentFR = "Pour prouver leur sincérité, la famille Lü démolit son mur d’enceinte et le recula de trois pas, érigeant à l’entrée une statue du Dragon d’Argent. La famille Ma, voyant cela, fit de même.",
          DialogueId = 51119025,
          GUID = "7FF89B0A",
          NextDialogue = 51119026,
          SpeakNpcId = 701026,
          Subtitle = "To show they truly meant to make peace, the Lyus pulled down their front wall and rebuilt it three feet further in — even set up a little statue of Lord Argent by the gate. The Mas saw that and did exactly the same."
        },
        [51119026] = {
          ContentFR = "Quelle joie ! Quelle paix retrouvée ! Par la suite, cette ruelle devint le lieu où les voisins se rendaient lors de tout différend, afin de laisser le Dragon d’Argent témoigner de leur bonne foi.",
          DialogueId = 51119026,
          GUID = "7FF89B34",
          NextDialogue = 51119027,
          SpeakNpcId = 701026,
          Subtitle = "And just like that — harmony restored! In time, that very lane became the place neighbours went whenever a quarrel arose, letting Lord Argent witness their goodwill for themself."
        },
        [51119027] = {
          ContentFR = "Aujourd’hui, permettez-moi d’adapter ces vers : « Comment prouver un cœur tourné vers le bien ? Dans trois pas cédés, se révèle la sincérité. » Qu’en pensez-vous, chers spectateurs ?",
          DialogueId = 51119027,
          GUID = "7FF89B5E",
          NextDialogue = 51119028,
          SpeakNpcId = 701026,
          Subtitle = "And today, allow me to tweak that verse a touch — like so: \"To show that virtue dwells within the heart — yield three feet, and goodwill speaks for itself.\" What say you, folks?",
          TalkActionId = {
            [1] = "701026:Explain01_End"
          }
        },
        [51119028] = {
          ContentFR = "La foule applaudit chaleureusement et loue le Dragon d’Argent. Quan Doutong reçoit encore plusieurs offrandes, puis les passants se dispersent peu à peu.",
          DialogueId = 51119028,
          GUID = "7FF89B88",
          Scripts = [[
PARA{
MoveTo{ActorId{701081},TargetPoint{"quandoutong_show1"},MoveSpeed{100},Visibility{"Hide"}},
MoveTo{ActorId{701082},TargetPoint{"quandoutong_show2"},MoveSpeed{100},Visibility{"Hide"}},
MoveTo{ActorId{701083},TargetPoint{"quandoutong_show3"},MoveSpeed{100},Visibility{"Hide"}},
MoveTo{ActorId{701084},TargetPoint{"quandoutong_show4"},MoveSpeed{100},Visibility{"Hide"}},
MoveTo{ActorId{701085},TargetPoint{"quandoutong_show5"},MoveSpeed{100},Visibility{"Hide"}},
MoveTo{ActorId{701086},TargetPoint{"quandoutong_show6"},MoveSpeed{100},Visibility{"Hide"}}
}]],
          Subtitle = "(The crowd breaks into cheerful applause, praising Lord Argent. A fresh handful of coins slips into Quan Doutong's palms as people wander off in twos and threes.)"
        },
        [51119029] = {
          ContentFR = "Les riches peuvent donner de l’argent, les autres n’ont qu’à faire acte de présence !",
          DialogueId = 51119029,
          GUID = "7FF89BB2",
          SpeakNpcId = 701026,
          Subtitle = "If you've got a few coins to spare, toss them in. If not, a bit of applause'll do!"
        },
        [51120000] = {
          ContentFR = "Apothicaire Huang, après avoir pris ce remède... y a-t-il des précautions à prendre ? Des aliments à éviter ?",
          DialogueId = 51120000,
          GUID = "7FF93B00",
          LookAt = {
            [1] = "701028:n(701027)",
            [2] = "701027:n(701028)"
          },
          NextDialogue = 51120001,
          SpeakNpcId = 701028,
          Subtitle = "Apothecary Huang, is there anything I need to watch out for after taking this? Any foods I should avoid?",
          TalkActionId = {
            [1] = "701028:Talk01_Start"
          }
        },
        [51120001] = {
          ContentFR = "Bien sûr que oui. Et retiens bien ceci : l’efficacité du traitement dépend entièrement de ta capacité à suivre ce que je vais te dire.",
          DialogueId = 51120001,
          GUID = "7FF93B2A",
          NextDialogue = 51120002,
          SpeakNpcId = 701027,
          Subtitle = "Of course there are. And mind you — whether it works or not depends entirely on how well you follow what I'm about to tell you.",
          TalkActionId = {
            [1] = "701028:Talk01_End"
          }
        },
        [51120002] = {
          ContentFR = "Premièrement : ce remède ne doit jamais être pris à jeun. Sinon, non seulement tu ne maigriras pas, mais tu risques même de prendre du poids. Tu devras donc manger trois repas par jour, au moins jusqu’à être à moitié rassasiée, avant chaque prise.",
          DialogueId = 51120002,
          GUID = "7FF93B54",
          NextDialogue = 51120003,
          SpeakNpcId = 701027,
          Subtitle = "First, don't take it on an empty stomach. Do that, and you'll end up putting on weight instead of losing it. You must eat three proper meals a day — at least enough so you're not hungry — before taking it.",
          TalkActionId = {
            [1] = "701027:Talk02_Start"
          }
        },
        [51120003] = {
          ContentFR = "Deuxièmement : les effets secondaires sont puissants. Il te faudra donc faire de l’exercice. Tiens, je vais te donner un livret : suis les exercices indiqués et entraîne-toi chaque jour pendant une heure entière, jusqu’à transpirer abondamment. Ce n’est qu’ainsi que les effets indésirables pourront être évacués.",
          DialogueId = 51120003,
          GUID = "7FF93B7E",
          NextDialogue = 51120004,
          SpeakNpcId = 701027,
          Subtitle = "Second, the side effects are strong, so you'll need to exercise properly. I'll give you a booklet. Follow the routine in it and work out for an hour every day, until you're sweating. That's the only way to clear the side effects."
        },
        [51120004] = {
          ContentFR = "Troisièmement : il est absolument interdit d’interrompre le traitement. Tu n’as acheté qu’un mois de remèdes ; une fois ce mois écoulé, tu devras revenir immédiatement pour le suivant. Si tu arrêtes en cours de route, tous les efforts du premier mois seront réduits à néant.",
          DialogueId = 51120004,
          GUID = "7FF93BA8",
          NextDialogue = 51120005,
          SpeakNpcId = 701027,
          Subtitle = "Third, don't stop midway. You only bought one month's supply. Once you finish it, come straight back for the next batch. If you interrupt the course, everything you achieved in the first month will be wasted, and you'll have to start from scratch!"
        },
        [51120005] = {
          ContentFR = "Voilà les trois règles. Tu les as bien retenues ?",
          DialogueId = 51120005,
          GUID = "7FF93BD2",
          NextDialogue = 51120006,
          SpeakNpcId = 701027,
          Subtitle = "That's all. Understood?",
          TalkActionId = {
            [1] = "701027:Talk02_End"
          }
        },
        [51120006] = {
          ContentFR = "Je... oui, je crois. Mais avec des conditions aussi strictes... pouvez-vous vraiment garantir que je serai mince comme l’éclair en trois mois ?",
          DialogueId = 51120006,
          GUID = "7FF93BFC",
          NextDialogue = 51120007,
          SpeakNpcId = 701028,
          Subtitle = "I... I think so. But with rules this strict... can you really guarantee I'll be as thin as a whip in three months?",
          TalkActionId = {
            [1] = "701028:Think_Start"
          }
        },
        [51120007] = {
          ContentFR = "Ah, Yan, Yan... est-ce que je t’ai déjà menti, ne serait-ce qu’une fois ? Si mes remèdes n’étaient pas efficaces, comment aurais-tu seulement entendu parler de moi ?",
          DialogueId = 51120007,
          GUID = "7FF93C26",
          NextDialogue = 51120008,
          SpeakNpcId = 701027,
          Subtitle = "Ah, Yan, when have I ever lied to anyone? If my remedies didn't work wonders, how would you have found your way to me?"
        },
        [51120008] = {
          ContentFR = "E-Eh bien... c’est vrai... Je comprends. Cette fois, je vais vraiment maigrir !",
          DialogueId = 51120008,
          GUID = "7FF93C50",
          NextDialogue = 51120009,
          SpeakNpcId = 701028,
          Subtitle = "W—Well... that's true... I get it now. I will lose weight this time!",
          TalkActionId = {
            [1] = "701028:Think_End"
          }
        },
        [51120009] = {
          ContentFR = "La jeune fille nommée Yan serre son flacon contre elle et s’en va en courant, pleine d’enthousiasme.",
          DialogueId = 51120009,
          GUID = "7FF93C7A",
          NextDialogue = 51120010,
          Scripts = "MoveTo{ActorId{701028},TargetPoint{\"LuoYan_Target\"},MoveSpeed{200},Visibility{\"Hide\"}}",
          Subtitle = "(Clutching the phial to her chest, the girl called Yan dashed off, full of excitement.)"
        },
        [51120010] = {
          ContentFR = "{性别:Vous êtes patient, cher client, d’avoir attendu si longtemps. J’imagine que vous êtes venu|Vous êtes patiente, chère cliente, d’avoir attendue si longtemps. J’imagine que vous êtes venue} chercher un remède ? Pour la santé du corps... ou pour une silhouette plus élancée, comme cette jeune fille ?",
          DialogueId = 51120010,
          GUID = "7FF93CA4",
          LookAt = {
            [1] = "701027:n(0)"
          },
          NextOptions = {
            [1] = 51120011,
            [2] = 51120013,
            [3] = 51120015
          },
          SpeakNpcId = 701027,
          Subtitle = "You're a patient one, guest — waiting here all this time. So then, what sort of draught are you after? A tonic for your health? Or, like that girl just now, something to slim the figure?"
        },
        [51120011] = {
          ContentFR = "<I>Avec vos conditions, elle pourrait maigrir sans même prendre de médicament...</>",
          DialogueId = 51120011,
          GUID = "7FF93CCE",
          ImprPlusId = 1208,
          NextDialogue = 51120012,
          Subtitle = "She could lose weight without the medicine if she really follows your rules, couldn't she?"
        },
        [51120012] = {
          ContentFR = "Oh ? Vous avez l’œil. En effet, si elle suivait strictement mes recommandations, deux mois suffiraient sans doute — trois au grand maximum.",
          DialogueId = 51120012,
          GUID = "7FF93CF8",
          NextDialogue = 51120017,
          SpeakNpcId = 701027,
          Subtitle = "Oh? Sharp, aren't you. You're right — if she truly sticks to the instructions, she'll see results in two months, three at most."
        },
        [51120013] = {
          ContentFR = "<I>Vous ne seriez pas en train de vendre de faux remèdes, par hasard ?</>",
          DialogueId = 51120013,
          GUID = "7FF93D22",
          ImprPlusId = 1207,
          NextDialogue = 51120014,
          Subtitle = "You'd better not be flogging quack medicine to rip people off."
        },
        [51120014] = {
          ContentFR = "Des faux remèdes ? Sur quoi vous basez-vous ? Elle n’a pas encore avalé une seule dose, et vous n’avez vu aucun résultat. N’est-ce pas un peu hâtif de m’accuser ?",
          DialogueId = 51120014,
          GUID = "7FF93D4C",
          NextDialogue = 51120017,
          SpeakNpcId = 701027,
          Subtitle = "Quack? Now why jump to that? She hasn't even taken a single dose yet, and you've seen no results. Isn't it a bit early to start throwing accusations?"
        },
        [51120015] = {
          ContentFR = "<I>Il va falloir me payer pour que je garde le silence.</>",
          DialogueId = 51120015,
          GUID = "7FF93D76",
          ImprPlusId = 1206,
          NextDialogue = 51120016,
          Subtitle = "Sounds like you owe me some hush money."
        },
        [51120016] = {
          ContentFR = "Du silence ? Pourquoi donc ? Ici, je fais commerce librement, sans enfreindre les Neuf Chapitres de Dafeng. Pourquoi aurais-je besoin de soudoyer qui que ce soit ?",
          DialogueId = 51120016,
          GUID = "7FF93DA0",
          NextDialogue = 51120017,
          SpeakNpcId = 701027,
          Subtitle = "Hush money? For what, exactly? I'm running an honest business, nothing against the Nine Chapters of Dafeng. Why would I have to pay anyone to keep quiet?"
        },
        [51120017] = {
          ContentFR = "Alors... qu’est-ce que vous lui avez vraiment vendu ?",
          DialogueId = 51120017,
          GUID = "7FF93DCA",
          NextDialogue = 51120018,
          SpeakNpcId = 100001,
          Subtitle = "So what exactly did you sell her?"
        },
        [51120018] = {
          ContentFR = "Puisque vous avez déjà compris, inutile de feindre l’ignorance. Je lui ai vendu un remède qui exauce les souhaits — celui qui lui permettra d’atteindre ce qu’elle désire au fond d’elle-même.",
          DialogueId = 51120018,
          GUID = "7FF93DF4",
          NextDialogue = 51120019,
          SpeakNpcId = 701027,
          Subtitle = "Since you've already figured it out, why bother asking? I sold her a draught to make her wish come true — one that'll bring about exactly what her heart desires.",
          TalkActionId = {
            [1] = "701027:Explain01_Start"
          }
        },
        [51120019] = {
          ContentFR = "... Donc c’est bien un faux remède ? Et si elle tombait malade ?",
          DialogueId = 51120019,
          GUID = "7FF93E1E",
          NextDialogue = 51120020,
          SpeakNpcId = 100001,
          Subtitle = "...So it is quack medicine, then? What if she gets sick from it?"
        },
        [51120020] = {
          ContentFR = "Heh. Vous avez bon cœur. Mais je ne suis pas un escroc qui joue avec la vie des gens. Cette jeune fille est en parfaite santé, pourtant elle s’obstinait à vouloir maigrir par la faim et les potions — ce qui est profondément déraisonnable.",
          DialogueId = 51120020,
          GUID = "7FF93E48",
          NextDialogue = 51120021,
          SpeakNpcId = 701027,
          Subtitle = "Heh, you've a kind heart, I'll give you that. But I'm no cut-throat poisoning people for profit. The young lady's perfectly healthy — yet she's determined to starve herself and gulp down potions to lose weight. Not wise.",
          TalkActionId = {
            [1] = "701027:Explain01_End"
          }
        },
        [51120021] = {
          ContentFR = "Je lui ai donc conseillé de manger correctement, et je lui ai donné des compléments contenant les nutriments nécessaires à son corps, afin qu’elle ne s’effondre pas après l’exercice.",
          DialogueId = 51120021,
          GUID = "7FF93E72",
          NextDialogue = 51120022,
          SpeakNpcId = 701027,
          Subtitle = "So I told her to keep a proper diet, and gave her some supplements to prevent her from fainting after her workouts.",
          TalkActionId = {
            [1] = "701027:Talk01_Start"
          }
        },
        [51120022] = {
          ContentFR = "Vous vous y connaissez, finalement.",
          DialogueId = 51120022,
          GUID = "7FF93E9C",
          NextDialogue = 51120023,
          SpeakNpcId = 100001,
          Subtitle = "You really do know your stuff, huh?"
        },
        [51120023] = {
          ContentFR = "Oh, je n’oserais pas dire cela. Disons simplement que je m’y connais un peu. Je ne suis qu’un humble apothicaire, survivant tant bien que mal dans ce marché noir.",
          DialogueId = 51120023,
          GUID = "7FF93EC6",
          NextDialogue = 51120024,
          SpeakNpcId = 701027,
          Subtitle = "Me? I'd hardly claim that. I'm just a small-time apothecary making ends meet in this black market.",
          TalkActionId = {
            [1] = "701027:Talk01_End"
          }
        },
        [51120024] = {
          ContentFR = "Vous procédez de la même manière pour vos autres remèdes ? Des compléments à la place de médicaments ?",
          DialogueId = 51120024,
          GUID = "7FF93EF0",
          NextDialogue = 51120025,
          SpeakNpcId = 100001,
          Subtitle = "So you do this with your other medicines too? Just hand out supplements instead?"
        },
        [51120025] = {
          ContentFR = "Vous aimez vraiment fouiller jusqu’au bout, vous autres. Certaines choses méritent qu’on ferme un œil. Je n’ai jamais fait de mal à personne — je les aide simplement à atteindre leurs objectifs par les bons moyens.",
          DialogueId = 51120025,
          GUID = "7FF93F1A",
          NextDialogue = 51120026,
          SpeakNpcId = 701027,
          Subtitle = "You people do love digging until you hit the bottom, don't you? Some things don't need such close inspection. I've never harmed anyone — I'm simply helping them take the right approach.",
          TalkActionId = {
            [1] = "701027:Talk02_Start"
          }
        },
        [51120026] = {
          ContentFR = "Qui cherche la longévité doit bien dormir et bien manger. Qui cherche la beauté doit prendre soin de soi et ménager ses efforts. Votre définition du mot « remède » n’est-elle pas un peu trop étroite ?",
          DialogueId = 51120026,
          GUID = "7FF93F44",
          NextDialogue = 51120027,
          SpeakNpcId = 701027,
          Subtitle = "Those who seek longevity should rest well and eat well. Those who hope for beauty should mind their skin, keep themselves pleasant, and not push too hard. Guest, you're taking the word \"medicine\" far too rigidly."
        },
        [51120027] = {
          ContentFR = "Un remède peut être une potion à avaler... mais aussi une manière de vivre. En apparence, je vends des médicaments ; en réalité, j’enseigne comment vivre correctement.",
          DialogueId = 51120027,
          GUID = "7FF93F6E",
          NextDialogue = 51120028,
          SpeakNpcId = 701027,
          Subtitle = "Medicine can be a decoction you swallow... but it can just as well be a way of living. It may look as though I'm handing out potions, but really, I'm teaching them how to look after themselves."
        },
        [51120028] = {
          ContentFR = "À ce titre, l’argent que je reçois n’est-il pas parfaitement légitime ?",
          DialogueId = 51120028,
          GUID = "7FF93F98",
          NextDialogue = 51120029,
          SpeakNpcId = 701027,
          Subtitle = "So tell me — doesn't that make the money they pay me quite fair?",
          TalkActionId = {
            [1] = "701027:Talk02_End"
          }
        },
        [51120029] = {
          ContentFR = "<I>... Il n’a peut-être pas tort.</>",
          DialogueId = 51120029,
          GUID = "7FF93FC2",
          NextDialogue = 51120030,
          SpeakNpcId = 100001,
          Subtitle = "(...He does have a point.)"
        },
        [51120030] = {
          ContentFR = "Ainsi, ne vous tourmentez pas davantage. Si je faisais réellement du tort, le Magistrat de Yingtian serait déjà venu me chercher. Comment pourrais-je encore être ici autrement ?",
          DialogueId = 51120030,
          GUID = "7FF93FEC",
          NextDialogue = 51120031,
          SpeakNpcId = 701027,
          Subtitle = "Don't overthink it. If I were actually harming people, the Magistrates of Yingtian would've hauled me off long ago. How else would I still be here?",
          TalkActionId = {
            [1] = "701027:Explain01_Start"
          }
        },
        [51120031] = {
          ContentFR = "Et si vous ne comptez rien acheter, pourriez-vous vous pousser un peu ? Laissez la place à ceux qui ont vraiment besoin de mes remèdes.",
          DialogueId = 51120031,
          GUID = "7FF94016",
          SpeakNpcId = 701027,
          Subtitle = "If you're not buying anything, step aside, will you? Let the ones who truly need my remedies come through.",
          TalkActionId = {
            [1] = "701027:Explain01_End"
          }
        },
        [51120032] = {
          ContentFR = "Contempler monts et rivières vaut moins que guérir les misères ! Manger maigre ou gras n’y changera rien — venez goûter aux élixirs de votre apothicaire~",
          DialogueId = 51120032,
          GUID = "7FF94040",
          SpeakNpcId = 701027,
          Subtitle = "Forget the mountain view, forget the meat. Come, let my remedies bring you back to your feet."
        },
        [51121000] = {
          ContentFR = "Quoi qu’il arrive, aujourd’hui tu vas me donner une explication !",
          DialogueId = 51121000,
          GUID = "7FF9DF10",
          LookAt = {
            [1] = "701029:n(701030)",
            [2] = "701030:n(701029)"
          },
          NextDialogue = 51121001,
          SpeakNpcId = 701029,
          Subtitle = "One way or another, I'm getting an explanation today!",
          TalkActionId = {
            [1] = "701029:Talk01_Start",
            [2] = "701030:Talk02_Start"
          }
        },
        [51121001] = {
          ContentFR = "Une explication ? Pour quoi faire ? Ne sois pas ridicule...",
          DialogueId = 51121001,
          GUID = "7FF9DF3A",
          NextOptions = {
            [1] = 51121002,
            [2] = 51121003,
            [3] = 51121004
          },
          SpeakNpcId = 701030,
          Subtitle = "An explanation? For what? Don't be absurd...",
          TalkActionId = {
            [1] = "701029:Talk01_End",
            [2] = "701030:Talk02_End"
          }
        },
        [51121002] = {
          ContentFR = "<I>Ils ont l’air de vraiment s’emporter... Autant essayer de calmer le jeu.</>",
          DialogueId = 51121002,
          GUID = "7FF9DF64",
          ImprPlusId = 1207,
          NextDialogue = 51121005,
          Subtitle = "Looks like they're really at each other's throats... Best go over and calm them down."
        },
        [51121003] = {
          ContentFR = "<I>Bagarre ! Bagarre !</>",
          DialogueId = 51121003,
          GUID = "7FF9DF8E",
          ImprPlusId = 1210,
          NextDialogue = 51121005,
          Subtitle = "Fight! Fight!"
        },
        [51121004] = {
          ContentFR = "<I>Qu’est-ce qui peut bien provoquer une dispute pareille... ?</>",
          DialogueId = 51121004,
          GUID = "7FF9DFB8",
          ImprPlusId = 1209,
          NextDialogue = 51121005,
          Subtitle = "What on earth are they arguing about...?"
        },
        [51121005] = {
          ContentFR = "Hé, toi ! Oui, toi, avec ta tignasse blanche — {性别:le vieux|la vieille} ! Approche donc, et dis-nous qui a raison !",
          DialogueId = 51121005,
          GUID = "7FF9DFE2",
          LookAt = {
            [1] = "701029:n(0)",
            [2] = "701030:n(0)"
          },
          NextDialogue = 51121006,
          SpeakNpcId = 701029,
          Subtitle = "Oi — you! Yes, you, the silver-haired {性别：old fellow|old lady}! Come here and settle this for us!"
        },
        [51121006] = {
          ContentFR = "Ouvre un peu les yeux. {性别:Un jeune homme|Une jeune femme} en pleine forme, et tu {性别:le prends pour un vieux|la prends pour une vieille} ? Tu te couvres de ridicule. Rentre donc chez toi dormir.",
          DialogueId = 51121006,
          GUID = "7FF9E00C",
          LookAt = {
            [1] = "701029:n(701030)",
            [2] = "701030:n(701029)"
          },
          NextDialogue = 51121007,
          SpeakNpcId = 701030,
          Subtitle = "Are you blind? A perfectly decent young {性别：man|woman}, and you call {性别：him|her} old. You're making a fool of yourself. Best go home and have a lie-down.",
          TalkActionId = {
            [1] = "701030:Talk01_Start"
          }
        },
        [51121007] = {
          ContentFR = "Tu oses encore parler ! C’est bien de ta faute ! Si tu ne passais pas tes nuits à rôder dehors pour dormir le jour, je pourrais fermer l’œil ! Mes idées s’épuisent, mon inspiration est à sec — c’est toi qui as tout brouillé !",
          DialogueId = 51121007,
          GUID = "7FF9E036",
          NextDialogue = 51121008,
          SpeakNpcId = 701029,
          Subtitle = "The audacity! You sleep through the day and stomp around all night — how am I meant to get any rest? No wonder I've run out of ideas for my writing!",
          TalkActionId = {
            [1] = "701030:Talk01_End"
          }
        },
        [51121008] = {
          ContentFR = "Tu n’as pas encore fini ? À quelle heure je sors ou je rentre, ça me regarde. Je ne frappe pas à ta porte, je ne claque pas la mienne. En quoi est-ce que je te dérange ?",
          DialogueId = 51121008,
          GUID = "7FF9E060",
          NextDialogue = 51121009,
          SpeakNpcId = 701030,
          Subtitle = "There you go again. When I go out and when I come back is my business. I don't hammer on your door, and I don't slam mine. How exactly have I disturbed you?"
        },
        [51121009] = {
          ContentFR = "Le vacarme que tu fais, c’est tout comme ! Tes bottes lourdes et maladroites martèlent le sol, <I>clac clac clac,</> et chaque soir avant de dormir tu les balances par terre — <I>boum, boum !</>",
          DialogueId = 51121009,
          GUID = "7FF9E08A",
          NextDialogue = 51121010,
          SpeakNpcId = 701029,
          Subtitle = "The racket you make is as bad as a slamming door! Those heavy boots of yours clomp all over the place, and before bed you always kick them off — thud, thud!",
          TalkActionId = {
            [1] = "701029:Explain01_Start"
          }
        },
        [51121010] = {
          ContentFR = "Arrête un peu. Tu t’es déjà plaint une fois, et depuis je fais attention, non ?",
          DialogueId = 51121010,
          GUID = "7FF9E0B4",
          NextDialogue = 51121011,
          SpeakNpcId = 701030,
          Subtitle = "Rubbish. You complained before, didn't you? Since then I've been taking them off quietly.",
          TalkActionId = {
            [1] = "701030:Talk02_Start"
          }
        },
        [51121011] = {
          ContentFR = "Justement ! Tu penses à poser doucement la deuxième botte... mais tu oublies la première ! Elle me réveille, et ensuite j’attends la seconde... qui ne vient jamais. Résultat : je reste éveillé jusqu’à l’aube !",
          DialogueId = 51121011,
          GUID = "7FF9E0DE",
          NextDialogue = 51121012,
          SpeakNpcId = 701029,
          Subtitle = "Exactly! You set the second boot down softly but forget the first! It jolts me awake, and then I lie there waiting for the second one to drop. But it never does — so I'm awake till sunrise!",
          TalkActionId = {
            [1] = "701029:Explain01_End"
          }
        },
        [51121012] = {
          ContentFR = "Mais... c’est encore ma faute, ça ? Et depuis, je fais pourtant attention ! Je marche, je me lave, rien de plus. Aucun autre voisin ne se plaint.",
          DialogueId = 51121012,
          GUID = "7FF9E108",
          NextDialogue = 51121013,
          SpeakNpcId = 701030,
          Subtitle = "How's that my fault? I've been careful since your last rant. I just move about my own home and wash up, as anyone would. And no one else has complained.",
          TalkActionId = {
            [1] = "701030:Talk02_End"
          }
        },
        [51121013] = {
          ContentFR = "Si tu ne supportes pas le moindre bruit, c’est peut-être ton oreille le problème. Si tu es malade, va te faire soigner — mais arrête d’embêter les autres.",
          DialogueId = 51121013,
          GUID = "7FF9E132",
          NextDialogue = 51121014,
          SpeakNpcId = 701030,
          Subtitle = "If the tiniest sound bothers you, maybe your ears are the problem. If something's wrong, get it looked at — just don't make it everyone else's burden."
        },
        [51121014] = {
          ContentFR = "Toi... tu dépasses les bornes !",
          DialogueId = 51121014,
          GUID = "7FF9E15C",
          NextOptions = {
            [1] = 51121015
          },
          RestartTag = 51121014,
          SpeakNpcId = 701029,
          Subtitle = "You—! You're impossible!"
        },
        [51121015] = {
          ContentFR = "<I>Tenter de calmer la dispute</>",
          DialogueId = 51121015,
          FailDialogue = 51121016,
          GUID = "7FF9E186",
          ImprCheckId = 1127,
          NextDialogue = 51121017,
          Subtitle = "Try calming them down."
        },
        [51121016] = {
          ContentFR = "<I>Ils sont bien trop en colère. Ma voix se perd complètement dans leurs cris...</>",
          DialogueId = 51121016,
          GUID = "7FF9E1B0",
          Subtitle = "(They're too worked up to hear a word...)"
        },
        [51121017] = {
          ContentFR = "Ça suffit. Arrêtez tous les deux.",
          DialogueId = 51121017,
          GUID = "7FF9E1DA",
          LookAt = {
            [1] = "701029:n(0)",
            [2] = "701030:n(0)"
          },
          NextDialogue = 51121018,
          SpeakNpcId = 100001,
          Subtitle = "All right, enough — stop it, both of you."
        },
        [51121018] = {
          ContentFR = "Vous avez entendu ! Il vit à contretemps, m’empêche de dormir. J’écris chez moi, l’esprit épuisé, déjà au bord de la rupture — et son bruit m’empêche même de me reposer !",
          DialogueId = 51121018,
          GUID = "7FF9E204",
          NextDialogue = 51121019,
          SpeakNpcId = 701029,
          Subtitle = "You heard him, didn't you? Sleeps through the day, clatters about all night — I never get any rest! I'm at home trying to write, my head's empty, my nerves are shot — and still his noise keeps me awake!",
          TalkActionId = {
            [1] = "701029:Talk01_Start"
          }
        },
        [51121019] = {
          ContentFR = "Quel vacarme monumental, hein ? Je ne pourrais même plus marcher chez moi ? Tu veux que je me déplace comme un voleur ?",
          DialogueId = 51121019,
          GUID = "7FF9E22E",
          NextDialogue = 51121020,
          SpeakNpcId = 701030,
          Subtitle = "What earth-shattering racket did I supposedly make? You're trying to police how I walk in my own home. Do you expect me to tiptoe around like a thief for your sake?",
          TalkActionId = {
            [1] = "701029:Talk01_End",
            [2] = "701030:Talk02_Start"
          }
        },
        [51121020] = {
          ContentFR = "D’accord... Commençons par toi. Pourquoi ce rythme nocturne ?",
          DialogueId = 51121020,
          GUID = "7FF9E258",
          NextDialogue = 51121021,
          SpeakNpcId = 100001,
          Subtitle = "All right, all right... let me ask you first: why are you out at night and sleeping during the day?",
          TalkActionId = {
            [1] = "701030:Talk02_End"
          }
        },
        [51121021] = {
          ContentFR = "Moi ? Je n’ai pas le choix. Je travaille sur les quais. Le patron fixe l’heure, je bosse. Ces temps-ci, tout se fait de nuit. Quand je rentre, le jour se lève.",
          DialogueId = 51121021,
          GUID = "7FF9E282",
          NextDialogue = 51121022,
          SpeakNpcId = 701030,
          Subtitle = "Me? I've got no choice. I'm a dock worker. The boss tells me when to shift cargo, and off I go. Lately all the jobs are at night. By the time we finish and I drag home, day's breaking.",
          TalkActionId = {
            [1] = "701030:Explain01_Start"
          }
        },
        [51121022] = {
          ContentFR = "Pourquoi accepter des contrats à des heures pareilles ?",
          DialogueId = 51121022,
          GUID = "7FF9E2AC",
          LookAt = {
            [1] = "701029:n(701030)",
            [2] = "701030:n(701029)"
          },
          NextDialogue = 51121023,
          SpeakNpcId = 701029,
          Subtitle = "Why take jobs at those dreadful hours?",
          TalkActionId = {
            [1] = "701029:Talk02_Start"
          }
        },
        [51121023] = {
          ContentFR = "Ha... Tu crois que tout le monde peut rester chez soi et manger à sa faim ? Si je ne travaille pas, je ne mange pas. Et les nuits, ça rapporte plus.",
          DialogueId = 51121023,
          GUID = "7FF9E2D6",
          NextDialogue = 51121024,
          SpeakNpcId = 701030,
          Subtitle = "Hah... you think the rest of us can sit about at home like you and still put food on the table? If I don't work, I don't earn — and the night shifts pay more.",
          TalkActionId = {
            [1] = "701030:Explain01_End"
          }
        },
        [51121024] = {
          ContentFR = "« Rester chez soi » ? Tu crois qu’écrire, c’est du repos ? Je me saigne l’esprit chaque jour ! Tu crois que l’inspiration ne fatigue pas ?",
          DialogueId = 51121024,
          GUID = "7FF9E300",
          NextDialogue = 51121025,
          SpeakNpcId = 701029,
          Subtitle = "\"Sit about at home,\" you say? I spend every day wracking my brains over each word! Do you have the faintest clue how exhausting that is?!",
          TalkActionId = {
            [1] = "701029:Talk02_End"
          }
        },
        [51121025] = {
          ContentFR = "À vous entendre... vous avez tous les deux vos raisons.",
          DialogueId = 51121025,
          GUID = "7FF9E32A",
          NextDialogue = 51121026,
          SpeakNpcId = 100001,
          Subtitle = "Honestly... you both have a point."
        },
        [51121026] = {
          ContentFR = "Je m’en moque ! Il m’empêche de dormir. Tranche donc !",
          DialogueId = 51121026,
          GUID = "7FF9E354",
          NextDialogue = 51121027,
          SpeakNpcId = 701029,
          Subtitle = "I don't care — he's ruining my sleep. You've seen how he is. Go on, be the judge — who's at fault here?"
        },
        [51121027] = {
          ContentFR = "Dépêchons-nous... <I>haaah...</> j’ai besoin de dormir avant de repartir bosser.",
          DialogueId = 51121027,
          GUID = "7FF9E37E",
          NextOptions = {
            [1] = 51121028,
            [2] = 51121034
          },
          SpeakNpcId = 701030,
          Subtitle = "Can we wrap this up? Yawn... I need to get home and sleep. Got another night shift later."
        },
        [51121028] = {
          ContentFR = "<I>Soutenir Yu Xia</>",
          DialogueId = 51121028,
          GUID = "7FF9E3A8",
          NextDialogue = 51121029,
          Subtitle = "Back Yu Xia."
        },
        [51121029] = {
          ContentFR = "Ton rythme est effectivement atypique, et cela le dérange. Essaie encore de marcher plus doucement.",
          DialogueId = 51121029,
          GUID = "7FF9E3D2",
          LookAt = {
            [1] = "701029:n(0)",
            [2] = "701030:n(0)"
          },
          NextDialogue = 51121030,
          SpeakNpcId = 100001,
          Subtitle = "Your routine really isn't like most people's, and you have disturbed his sleep. Try to keep your steps even quieter."
        },
        [51121030] = {
          ContentFR = "Tu vois ! Cette personne sait juger avec justesse !",
          DialogueId = 51121030,
          GUID = "7FF9E3FC",
          NextDialogue = 51121031,
          SpeakNpcId = 701029,
          Subtitle = "See? This sensible youngster gets it!",
          TalkActionId = {
            [1] = "701029:Explain01_Start"
          }
        },
        [51121031] = {
          ContentFR = "Même toi... <I>tss.</>",
          DialogueId = 51121031,
          GUID = "7FF9E426",
          NextDialogue = 51121032,
          SpeakNpcId = 701030,
          Subtitle = "So you're taking his side... tch."
        },
        [51121032] = {
          ContentFR = "Merci infiniment ! Quelle droiture, quelle noblesse ! Vous m’avez rendu justice !",
          DialogueId = 51121032,
          GUID = "7FF9E450",
          NextDialogue = 51121033,
          SpeakNpcId = 701029,
          Subtitle = "Thank you, truly! You're a hero — righteous and fair! Thanks for speaking up for me!",
          TalkActionId = {
            [1] = "701029:Explain01_End"
          }
        },
        [51121033] = {
          ContentFR = "Il ne le fait pas par malveillance. Essayez tous deux de faire preuve de compréhension entre voisins.",
          DialogueId = 51121033,
          GUID = "7FF9E47A",
          NextDialogue = 51121040,
          SpeakNpcId = 100001,
          Subtitle = "He only makes noise because of his shifts. He's not doing it on purpose. You're neighbours — try to meet each other halfway."
        },
        [51121034] = {
          ContentFR = "<I>Soutenir Dong Zhu</>",
          DialogueId = 51121034,
          GUID = "7FF9E4A4",
          NextDialogue = 51121035,
          Subtitle = "Back Dong Zhu."
        },
        [51121035] = {
          ContentFR = "Si les autres voisins ne sont pas dérangés, peut-être es-tu simplement trop sensible. As-tu essayé de boucher tes oreilles avec du coton ?",
          DialogueId = 51121035,
          GUID = "7FF9E4CE",
          LookAt = {
            [1] = "701029:n(0)",
            [2] = "701030:n(0)"
          },
          NextDialogue = 51121036,
          SpeakNpcId = 100001,
          Subtitle = "If none of the other neighbours are bothered, perhaps you're simply a bit too sensitive to noise. Maybe try stuffing cotton in your ears?"
        },
        [51121036] = {
          ContentFR = "Tu entends ? Même {性别:un passant|une passante} est d’accord. Mets du coton au lieu de hurler.",
          DialogueId = 51121036,
          GUID = "7FF9E4F8",
          NextDialogue = 51121037,
          SpeakNpcId = 701030,
          Subtitle = "See? Even a stranger thinks you're being dramatic. Just use some cotton instead of making a scene.",
          TalkActionId = {
            [1] = "701030:Talk01_Start"
          }
        },
        [51121037] = {
          ContentFR = "Toi... tu n’as donc ni yeux ni jugeote ? C’est clairement sa faute, et c’est encore moi qui devrais encaisser ? Vous dépassez les bornes !",
          DialogueId = 51121037,
          GUID = "7FF9E522",
          NextDialogue = 51121038,
          SpeakNpcId = 701029,
          Subtitle = "You—! Are you really that thick? It's clearly his fault, and you tell me to put up with it? You're impossible!"
        },
        [51121038] = {
          ContentFR = "Quand mon livre sera publié, j’irai m’acheter une grande maison à Haojing et je quitterai ce quartier à jamais !",
          DialogueId = 51121038,
          GUID = "7FF9E54C",
          NextDialogue = 51121039,
          SpeakNpcId = 701029,
          Subtitle = "Once my book's published and I earn real money, I'll buy a proper house in Haojing and move out at once. I'm never living next to someone like you again!",
          TalkActionId = {
            [1] = "701030:Talk01_End"
          }
        },
        [51121039] = {
          ContentFR = "Si les Bi’an ne sont pas venus pour moi, c’est que je suis en règle. Mais toi... continue comme ça, et qui sait.",
          DialogueId = 51121039,
          GUID = "7FF9E576",
          NextDialogue = 51121040,
          SpeakNpcId = 701030,
          Subtitle = "Since Bi'an hasn't come to fetch me, I'm clearly not the problem. But if you keep this up... who knows, maybe they'll come for you."
        },
        [51121040] = {
          ContentFR = "Bon. Cela s’arrête ici. Essayez de vivre en bonne entente à l’avenir.",
          DialogueId = 51121040,
          GUID = "7FF9E5A0",
          NextDialogue = 51121041,
          SpeakNpcId = 100001,
          Subtitle = "Right, that's my good deed for the day. I'm off — you two try not to start another row, yeah?"
        },
        [51121041] = {
          ContentFR = "Yu Xia s’éloigne en trombe. Dong Zhu se gratte la tête, claque la langue et ne dit rien.",
          DialogueId = 51121041,
          GUID = "7FF9E5CA",
          NextDialogue = 51121042,
          Subtitle = "(Yu Xia stormed off. Dong Zhu scratched his head, clicked his tongue, and said nothing.)"
        },
        [51121042] = {
          ContentFR = "Ils ne deviendront sans doute pas amis grâce à une simple médiation... mais au moins, pour l’instant, le calme est revenu.",
          DialogueId = 51121042,
          GUID = "7FF9E5F4",
          Subtitle = "(They won't be friends overnight, but at least they've stopped yelling at each other for now.)"
        },
        [51122000] = {
          ContentFR = "Hé, {性别:p’tit ! P’tit|p’tite ! P’tite} ! Viens par ici !",
          DialogueId = 51122000,
          GUID = "7FFA8320",
          LookAt = {
            [1] = "701031:n(0)"
          },
          NextDialogue = 51122001,
          SpeakNpcId = 701031,
          Subtitle = "Oi, kid! You there!"
        },
        [51122001] = {
          ContentFR = "Vous regardez autour de vous. Personne d’autre en vue. Vous pointez prudemment votre doigt vers votre poitrine.",
          DialogueId = 51122001,
          GUID = "7FFA834A",
          NextDialogue = 51122002,
          Subtitle = "(You glance round, see no one else, and cautiously point at yourself.)"
        },
        [51122002] = {
          ContentFR = "Oui, toi ! C’est bien à toi que je parle, {性别:p’tit|p’tite} ! Approche donc !",
          DialogueId = 51122002,
          GUID = "7FFA8374",
          NextDialogue = 51122003,
          NextOptions = {
            [1] = 51122003,
            [2] = 51122004,
            [3] = 51122005
          },
          SpeakNpcId = 701031,
          Subtitle = "Aye, you. Come on over!"
        },
        [51122003] = {
          ContentFR = "<I>S’approcher sans méfiance</>",
          DialogueId = 51122003,
          GUID = "7FFA839E",
          ImprPlusId = 1207,
          NextDialogue = 51122006,
          Subtitle = "(Go over to him.)"
        },
        [51122004] = {
          ContentFR = "<I>– Il veut sûrement me vendre quelque chose...</>",
          DialogueId = 51122004,
          GUID = "7FFA83C8",
          ImprPlusId = 1206,
          NextDialogue = 51122006,
          Subtitle = "(Is he trying to sell me something?)"
        },
        [51122005] = {
          ContentFR = "<I>Faire comme si de rien n’était et s’éloigner</>",
          DialogueId = 51122005,
          GUID = "7FFA83F2",
          ImprPlusId = 1210,
          NextDialogue = 51122006,
          Subtitle = "(Ignore him and walk off.)"
        },
        [51122006] = {
          ContentFR = "Ah là là... {性别:quel gamin|quelle gamine} difficile à appeler. Je t’ai repéré de loin, tu sais. J’ai beau t’appeler encore et encore, pas la moindre réaction. J’ai fini par me dire : « Ça alors, serait-il déjà dur d’oreille à cet âge-là ? »",
          DialogueId = 51122006,
          GUID = "7FFA841C",
          NextDialogue = 51122007,
          SpeakNpcId = 701031,
          Subtitle = "Good grief, kid, you're a difficult one to flag down. I'd had my eye on you from way off, hollering and hollering, and not a peep back. Had me thinking you'd gone deaf at your age.",
          TalkActionId = {
            [1] = "701031:Talk01_Start"
          }
        },
        [51122007] = {
          ContentFR = "Mais à te voir de près... l’œil vif, l’air alerte. Non, rien de travers, finalement.",
          DialogueId = 51122007,
          GUID = "7FFA8446",
          NextDialogue = 51122008,
          SpeakNpcId = 701031,
          Subtitle = "But seeing you up close — bright as a button — nothing wrong with you after all.",
          TalkActionId = {
            [1] = "701031:Talk01_End"
          }
        },
        [51122008] = {
          ContentFR = "Alors... qu’est-ce que vous me voulez ?",
          DialogueId = 51122008,
          GUID = "7FFA8470",
          NextDialogue = 51122009,
          SpeakNpcId = 100001,
          Subtitle = "So... what do you want?"
        },
        [51122009] = {
          ContentFR = "Du calme, {性别:p’tit|p’tite}. À Huaxu, y a pas vraiment de mauvaises personnes. C’est juste que j’ai brassé une nouvelle cuvée, et j’aimerais que tu m’en donnes ton avis.",
          DialogueId = 51122009,
          GUID = "7FFA849A",
          NextDialogue = 51122010,
          SpeakNpcId = 701031,
          Subtitle = "Easy, kid. Huaxu's not the sort of place that attracts shady types. I've just brewed a new jug and wanted someone to give it a taste.",
          TalkActionId = {
            [1] = "701031:Talk02_Start"
          }
        },
        [51122010] = {
          ContentFR = "Oh, je vois bien ton regard méfiant. Écoute donc. Moi, je suis marchand d’alcool. Va te renseigner en ville : le nom de Vieux Pichet, tous les amateurs d’un bon coup le connaissent.",
          DialogueId = 51122010,
          GUID = "7FFA84C4",
          NextDialogue = 51122011,
          SpeakNpcId = 701031,
          Subtitle = "Oh, I know that look. Let me explain — I'm a proper wine-seller. Go ask round town for Old Jug. Anyone who enjoys a decent drink will know the name."
        },
        [51122011] = {
          ContentFR = "Mais récemment, j’ai reçu une commande d’un Tisse-Étoiles. Il veut exporter une cargaison d’alcool doux jusqu’à l’autre bout du continent, en Hyperborea.",
          DialogueId = 51122011,
          GUID = "7FFA84EE",
          NextDialogue = 51122012,
          SpeakNpcId = 701031,
          Subtitle = "Thing is, I've had an order in from a Starweaver — wants a whole batch of sweet rice wine sent all the way to Hyperborea, right on the far end of the continent."
        },
        [51122012] = {
          ContentFR = "Et là, vois-tu, j’ai été bien embêté. Il exige un alcool léger, doux, sucré sans excès... Rien à voir avec les alcools puissants que je fais d’ordinaire. Mais la bourse, elle, est sacrément généreuse...",
          DialogueId = 51122012,
          GUID = "7FFA8518",
          NextDialogue = 51122013,
          SpeakNpcId = 701031,
          Subtitle = "But the moment I read it, I was stumped. It's got to be light, gentle, properly sweet... nothing like the strong, fiery stuff I usually brew. But the payment's generous — very generous.",
          TalkActionId = {
            [1] = "701031:Talk02_End"
          }
        },
        [51122013] = {
          ContentFR = "Donc vous avez créé un nouvel alcool et vous cherchez quelqu’un pour en tester le goût.",
          DialogueId = 51122013,
          GUID = "7FFA8542",
          NextDialogue = 51122014,
          SpeakNpcId = 100001,
          Subtitle = "So you made a new brew and now you need someone to test it."
        },
        [51122014] = {
          ContentFR = "{性别:Futé, le p’tit|Futée, la p’tite} ! Voilà exactement. Aucune arrière-pensée, je te l’assure. Pour cet alcool épicé, j’ai choisi du riz gluant bien rond, ajouté de la cannelle à la cuisson pour une douceur chaleureuse, puis rehaussé l’arôme avec des feuilles de thé.",
          DialogueId = 51122014,
          GUID = "7FFA856C",
          NextDialogue = 51122015,
          SpeakNpcId = 701031,
          Subtitle = "Sharp kid! Exactly. Nothing dodgy. As for this spiced rice wine, I used a special sticky rice, steamed it with cinnamon for a warm sweetness, then added tea leaves to lift the aroma and round out the flavour.",
          TalkActionId = {
            [1] = "701031:Explain01_Start"
          }
        },
        [51122015] = {
          ContentFR = "Ensuite, j’ai fait venir des fruits sucrés des monts du Sud. La pulpe a été broyée, mélangée à de l’eau de source fraîchement puisée, et travaillée durant trois jours entiers.",
          DialogueId = 51122015,
          GUID = "7FFA8596",
          NextDialogue = 51122016,
          SpeakNpcId = 701031,
          Subtitle = "And to finish, I had some sweet fruit from the southern hills brought in — crushed the pulp into juice, mixed it with fresh spring water, and spent three full days bringing the brew together."
        },
        [51122016] = {
          ContentFR = "Les vieux bougres que je connais ne boivent que des alcools brûlants. Leur langue est émoussée. À chaque fois, ils disent juste : « Trop sucré ». Ne sachant plus vers qui me tourner, j’ai attendu ici... qu’un esprit affiné passe par là.",
          DialogueId = 51122016,
          GUID = "7FFA85C0",
          NextDialogue = 51122017,
          SpeakNpcId = 701031,
          Subtitle = "The old codgers I know drink nothing but burning spirits all day — their tongues can't taste a thing any more. I asked them, and all they said was \"too sweet\". With no one else to turn to, I've been waiting here for fate to send along someone with a proper palate."
        },
        [51122017] = {
          ContentFR = "Alors ? {性别:P’tit|P’tite}, ça te dirait de goûter ? Rassure-toi, le degré est très bas. Une ou deux gorgées, et tu pourras repartir l’esprit clair.",
          DialogueId = 51122017,
          GUID = "7FFA85EA",
          NextDialogue = 51122018,
          SpeakNpcId = 701031,
          Subtitle = "So, kid — will you try it? Don't fret, it's barely alcoholic. If you've things to do later, a sip won't muddle your head.",
          TalkActionId = {
            [1] = "701031:Explain01_End"
          }
        },
        [51122018] = {
          ContentFR = "D’accord, je goûte.",
          DialogueId = 51122018,
          GUID = "7FFA8614",
          NextOptions = {
            [1] = 51122019
          },
          RestartTag = 51122018,
          SpeakNpcId = 100001,
          Subtitle = "All right. I'll give it a try."
        },
        [51122019] = {
          ContentFR = "Vous prenez la coupe et en buvez une petite gorgée.",
          DialogueId = 51122019,
          FailDialogue = 51122020,
          GUID = "7FFA863E",
          ImprCheckId = 1128,
          NextDialogue = 51122021,
          Subtitle = "(You take the cup from him and sip cautiously.)"
        },
        [51122020] = {
          ContentFR = "<I>Difficile à cerner...</>",
          DialogueId = 51122020,
          GUID = "7FFA8668",
          SpeakNpcId = 100001,
          Subtitle = "(I... can't quite place the flavour.)"
        },
        [51122021] = {
          ContentFR = "Doux à l’entrée, presque comme du miel... Et lorsqu’il glisse dans la gorge, un parfum discret se révèle. C’est un très bon breuvage.",
          DialogueId = 51122021,
          GUID = "7FFA8692",
          NextDialogue = 51122022,
          SpeakNpcId = 100001,
          Subtitle = "It's sweet on the tongue, almost like honey, and there's a faint fragrance as it goes down... a lovely brew."
        },
        [51122022] = {
          ContentFR = "Ha ! Voilà une langue plus douce encore que mon breuvage. À t’entendre, le cœur m’en devient léger. Tous ces jours à me creuser la tête n’auront pas été vains.",
          DialogueId = 51122022,
          GUID = "7FFA86BC",
          NextDialogue = 51122023,
          SpeakNpcId = 701031,
          Subtitle = "Ha! You're sweeter than the wine, kid. Hearing that warms my heart. Makes all those days of fretting over the order worth it.",
          TalkActionId = {
            [1] = "701031:Confident_Start"
          }
        },
        [51122023] = {
          ContentFR = "Pourquoi ne pas simplement utiliser l’un de vos alcools habituels pour la vente ?",
          DialogueId = 51122023,
          GUID = "7FFA86E6",
          NextDialogue = 51122024,
          SpeakNpcId = 100001,
          Subtitle = "Why not just give the client something you already make?"
        },
        [51122024] = {
          ContentFR = "Réfléchis. Hyperborea est si loin... Et pourtant, cette jeune étrangère a passé commande sans hésiter. C’est qu’elle a foi en mon savoir-faire.",
          DialogueId = 51122024,
          GUID = "7FFA8710",
          NextDialogue = 51122025,
          SpeakNpcId = 701031,
          Subtitle = "Think about it — Hyperborea's a world away, yet that lass sent an order from across half the continent. She must trust my brewing."
        },
        [51122025] = {
          ContentFR = "Si je bâclais le travail, je trahirais cette confiance... et ruinerais la réputation de mon échoppe.",
          DialogueId = 51122025,
          GUID = "7FFA873A",
          NextDialogue = 51122026,
          SpeakNpcId = 701031,
          Subtitle = "If I fobbed her off with any old brew, I'd only let her down — and drag my shop's good name through the mud."
        },
        [51122026] = {
          ContentFR = "Mais grâce à ton avis, me voilà rassuré. Je suis certain que cette demoiselle étrangère — Camil, ou quelque chose comme ça — aimera cet alcool doux spécialement conçu.",
          DialogueId = 51122026,
          GUID = "7FFA8764",
          NextDialogue = 51122027,
          SpeakNpcId = 701031,
          Subtitle = "But hearing your kind words takes a load off my mind. I reckon that foreign lass — Cami... something — will fancy this sweet brew."
        },
        [51122027] = {
          ContentFR = "Merci, {性别:p’tit|p’tite}. Si un jour l’envie te prend de boire un bon cru, reviens me voir. Je te brasserai une bouteille rien que pour toi.",
          DialogueId = 51122027,
          GUID = "7FFA878E",
          SpeakNpcId = 701031,
          Subtitle = "Thanks, kid. If you're ever craving a drink, come find Old Jug. I'll brew a fine jug just for you.",
          TalkActionId = {
            [1] = "701031:Confident_End"
          }
        },
        [51122028] = {
          ContentFR = "Un bon breuvage n’a pas besoin d’enseigne pour être trouvé.",
          DialogueId = 51122028,
          GUID = "7FFA87B8",
          SpeakNpcId = 701031,
          Subtitle = "Good wine needs no bush."
        },
        [51123000] = {
          ContentFR = "À l’aube je coupe le blé, les champs s’étendent à perte de vue. Je m’affaire du matin au soir sans jamais souffler, puis je rentre boire un petit verre.",
          DialogueId = 51123000,
          GUID = "7FFB2730",
          LookAt = {
            [1] = "701032:n(0)"
          },
          NextDialogue = 51123001,
          SpeakNpcId = 701032,
          Subtitle = "Up at dawn to cut the wheat, reaping till the fields run further than the eye can see; I work all day without a break, then head home for a little drink.",
          TalkActionId = {
            [1] = "701032:Confident_Start"
          }
        },
        [51123001] = {
          ContentFR = "Souffler, boire... ça ne rime pas vraiment, hein... Par quoi je pourrais remplacer ça ?",
          DialogueId = 51123001,
          GUID = "7FFB275A",
          NextOptions = {
            [1] = 51123002
          },
          RestartTag = 51123001,
          SpeakNpcId = 701032,
          Subtitle = "...Hmm. That first half doesn't quite rhyme, does it? What should I change it to?",
          TalkActionId = {
            [1] = "701032:Confident_End"
          }
        },
        [51123002] = {
          ContentFR = "<I>Donner un coup de main</>",
          DialogueId = 51123002,
          FailDialogue = 51123003,
          GUID = "7FFB2784",
          ImprCheckId = 1129,
          NextDialogue = 51123004,
          Subtitle = "Lend him a hand."
        },
        [51123003] = {
          ContentFR = "<I>Rien ne me vient... réfléchissons encore.</>",
          DialogueId = 51123003,
          GUID = "7FFB27AE",
          SpeakNpcId = 100001,
          Subtitle = "(Nothing's coming yet... need a moment to think.)"
        },
        [51123004] = {
          ContentFR = "Je m’affaire du matin au soir sans jamais souffler, puis je rentre poser les plats sur le vaisselier. Là, ça rime, non ?",
          DialogueId = 51123004,
          GUID = "7FFB27D8",
          NextDialogue = 51123005,
          SpeakNpcId = 100001,
          Subtitle = "Up at dawn to cut wheat; reaping on and on in the midday heat — that rhymes now, doesn't it?"
        },
        [51123005] = {
          ContentFR = "Souffler... vaisselier... oui, ça rime bien, en effet. Mais ce n’est toujours pas très joli à l’oreille. C’est sûrement moi qui ai mal posé la question. Un vrai lettré ferait bien mieux que ce vieux paysan.",
          DialogueId = 51123005,
          GUID = "7FFB2802",
          NextDialogue = 51123006,
          SpeakNpcId = 701032,
          Subtitle = "Wheat, heat... aye, that rhymes well enough. Still doesn't sound very polished, though. Probably because the line itself isn't much to work with. If proper scholars were writing it, they'd make something decent of it. Not like this old farmer.",
          TalkActionId = {
            [1] = "701032:Think_Start"
          }
        },
        [51123006] = {
          ContentFR = "Cela dit... {性别:jeune homme|jeune femme}, tu ne sembles pas être de Huaxu, et pourtant tu t’y connais un peu en vers ?",
          DialogueId = 51123006,
          GUID = "7FFB282C",
          NextDialogue = 51123007,
          SpeakNpcId = 701032,
          Subtitle = "Anyway — you don't look like someone from Huaxu, {性别：lad|lass}, yet you seem to know a thing or two about verse, eh?",
          TalkActionId = {
            [1] = "701032:Think_End"
          }
        },
        [51123007] = {
          ContentFR = "J’ai juste dit ça au hasard. Ce n’est pas fameux non plus.",
          DialogueId = 51123007,
          GUID = "7FFB2856",
          NextDialogue = 51123008,
          SpeakNpcId = 100001,
          Subtitle = "Not really. Just a bit of clumsy phrasing."
        },
        [51123008] = {
          ContentFR = "Hahahaha ! Tu es bien modeste. C’est déjà bien meilleur que ce que j’ai pondu. Dis-moi, {性别:jeune homme|jeune femme}, qu’est-ce qui t’amène à traîner par ici, sur ces talus ?",
          DialogueId = 51123008,
          GUID = "7FFB2880",
          NextOptions = {
            [1] = 51123009,
            [2] = 51123011
          },
          SpeakNpcId = 701032,
          Subtitle = "Hahaha! You're being too modest — that's miles better than anything I thought of. Tell me, {性别：lad|lass}, what brings you out to these fields?"
        },
        [51123009] = {
          ContentFR = "<I>Te voir seul ici m’a un peu inquiété.</>",
          DialogueId = 51123009,
          GUID = "7FFB28AA",
          ImprPlusId = 1209,
          NextDialogue = 51123010,
          Subtitle = "I saw you out here alone and got a bit worried."
        },
        [51123010] = {
          ContentFR = "Bah ! Inutile de s’en faire. Nous sommes à Huaxu, sous la protection du Seigneur Dragon d’Argent. Mais ton attention me touche, {性别:jeune homme|jeune femme}.",
          DialogueId = 51123010,
          GUID = "7FFB28D4",
          NextDialogue = 51123014,
          SpeakNpcId = 701032,
          Subtitle = "What's there to worry about? This is Huaxu — a good place under Lord Argent's blessing. Still, thank you for the thought, {性别：lad|lass}."
        },
        [51123011] = {
          ContentFR = "<I>Rien de spécial, je me promenais.</>",
          DialogueId = 51123011,
          GUID = "7FFB28FE",
          ImprPlusId = 1210,
          NextDialogue = 51123012,
          Subtitle = "Nothing much — just taking a walk."
        },
        [51123012] = {
          ContentFR = "Te promener ? Tu ne serais pas {性别:perdu et trop fier|perdue et trop fière} pour l’admettre ? Pense à garder ton sachet sur toi... On ne sait jamais, avec les Bi’an obscurs.",
          DialogueId = 51123012,
          GUID = "7FFB2928",
          NextDialogue = 51123013,
          SpeakNpcId = 701032,
          Subtitle = "A walk, eh? You're sure you're not lost and too embarrassed to say so? Keep your sachet close, mind — you wouldn't want to bump into a Sable Bi'an."
        },
        [51123013] = {
          ContentFR = "Alors... tu serais une sorte de ménestrel itinérant ?",
          DialogueId = 51123013,
          GUID = "7FFB2952",
          NextDialogue = 51123014,
          SpeakNpcId = 100001,
          Subtitle = "So... are you some sort of wandering bard?"
        },
        [51123014] = {
          ContentFR = "Ménestrel itinérant ? Voilà un titre bien élégant. Mais non, pas du tout. Je suis cultivateur. Regarde : tous ces champs, là, ce sont les miens.",
          DialogueId = 51123014,
          GUID = "7FFB297C",
          NextDialogue = 51123015,
          SpeakNpcId = 701032,
          Subtitle = "A wandering bard? That's a new one. No, nothing like that — I'm just a farmer. Look — this whole stretch is my family's land.",
          TalkActionId = {
            [1] = "701032:Talk01_Start"
          }
        },
        [51123015] = {
          ContentFR = "Pour un vieux fermier comme moi, rimer deux phrases n’est qu’un passe-temps. Un loisir, comme admirer les fleurs ou regarder un spectacle.",
          DialogueId = 51123015,
          GUID = "7FFB29A6",
          NextDialogue = 51123016,
          SpeakNpcId = 701032,
          Subtitle = "For an old farmer like me, spinning a few lines of verse is just something to pass the time. Same as admiring flowers or watching a show."
        },
        [51123016] = {
          ContentFR = "Cela dit... quand j’étais jeune, j’ai vraiment étudié quelques années. Je rêvais d’entrer un jour dans les Trois Bureaux pour servir le Seigneur Dragon d’Argent. Ah... quel beau rêve c’était.",
          DialogueId = 51123016,
          GUID = "7FFB29D0",
          NextDialogue = 51123017,
          SpeakNpcId = 701032,
          Subtitle = "Mind you, when I was young I did study hard for a few years, dreaming I might one day join one of the ministries and serve Lord Argent. Just thinking about it felt like a fine dream back then."
        },
        [51123017] = {
          ContentFR = "Et pourquoi cela ne s’est-il pas fait ?",
          DialogueId = 51123017,
          GUID = "7FFB29FA",
          NextDialogue = 51123018,
          SpeakNpcId = 701032,
          Subtitle = "And what stopped you?"
        },
        [51123018] = {
          ContentFR = "À l’aube je coupe le blé, les champs s’étendent à perte de vue. Je m’affaire du matin au soir sans jamais souffler, puis je rentre boire un petit verre. Cultiver la terre, je sais faire. Mais dès qu’il s’agit de paperasse et d’affaires compliquées... je sèche.",
          DialogueId = 51123018,
          GUID = "7FFB2A24",
          NextDialogue = 51123019,
          SpeakNpcId = 701032,
          Subtitle = "Up at dawn to cut the wheat, reaping till the fields run further than the eye can see; I work all day without a break, then head home for a little drink. I know my way round the fields — but ministry paperwork? I'd be staring at it till sundown."
        },
        [51123019] = {
          ContentFR = "Les débats du Bureau des Rites, les comptes du Bureau de la Fortune Céleste,\nles mécanismes du Bureau des Travaux... Je n’y comprends strictement rien. Si quelqu’un comme moi entrait en fonction, les Neuf Chapitres de Dafeng deviendraient vite les Neuf Bourrasques du Désordre !",
          DialogueId = 51123019,
          GUID = "7FFB2A4E",
          NextDialogue = 51123020,
          SpeakNpcId = 701032,
          Subtitle = "I can't make head nor tail of any of it — the debates in the Ministry of Rites, the bookkeeping in the Ministry of Fortune, the gadgets they fiddle with in the Ministry of Works. They'd never take someone like me — and even if they did, I'd be more trouble than help.",
          TalkActionId = {
            [1] = "701032:Talk01_End"
          }
        },
        [51123020] = {
          ContentFR = "Je comprends mieux.",
          DialogueId = 51123020,
          GUID = "7FFB2A78",
          NextDialogue = 51123021,
          SpeakNpcId = 100001,
          Subtitle = "I see."
        },
        [51123021] = {
          ContentFR = "Mais au fond, ma vie actuelle me convient bien. Quelques vers improvisés, une discussion avec les jeunes, puis le soir, un peu de viande braisée du marché, deux gorgées de breuvages avec mon grand gaillard de fils... C’est une bonne vie, non ?",
          DialogueId = 51123021,
          GUID = "7FFB2AA2",
          NextDialogue = 51123022,
          SpeakNpcId = 701032,
          Subtitle = "Still, I've no real complaints — making up a clumsy verse or two when I've got a moment, shooting the breeze with young folk, then heading home for some braised meat and a cup of rice wine with my lad... that's a fine enough life.",
          TalkActionId = {
            [1] = "701032:Talk02_Start"
          }
        },
        [51123022] = {
          ContentFR = "Oh là là, il se fait tard ! {性别:jeune homme|jeune femme}, parlons-en une autre fois ! Je vais ranger mes outils et rentrer savourer quelques verres !",
          DialogueId = 51123022,
          GUID = "7FFB2ACC",
          SpeakNpcId = 701032,
          Subtitle = "Ah, look at the time. Good talking with you, {性别：lad|lass}. I'd better finish up and get myself home for a few drinks!",
          TalkActionId = {
            [1] = "701032:Talk02_End"
          }
        },
        [51123023] = {
          ContentFR = "Sarcler sous le soleil de midi, la sueur tombe sur la terre... Quelle poésie, quelle poésie !",
          DialogueId = 51123023,
          GUID = "7FFB2AF6",
          SpeakNpcId = 701032,
          Subtitle = "Hoeing in the noonday heat, sweat falls to the earth at my feet... Now that's a poem!"
        },
        [51124000] = {
          ContentFR = "<I>Bouh !</>",
          DialogueId = 51124000,
          FacialId = {
            [1] = "701033:Smile01"
          },
          GUID = "7FFBCB40",
          LookAt = {
            [1] = "701033:n(0)"
          },
          NextDialogue = 51124001,
          SpeakNpcId = 701033,
          Subtitle = "Boo!"
        },
        [51124001] = {
          ContentFR = "Sans que vous sachiez d’où elle sort, une Luno surgit soudain devant vous... l’air féroce, gesticulant de toutes ses forces.",
          DialogueId = 51124001,
          GUID = "7FFBCB6A",
          NextDialogue = 51124002,
          Subtitle = "(A Luno bursts out of nowhere — arms flailing wildly, teeth bared in an exaggerated attempt to scare you.)"
        },
        [51124002] = {
          ContentFR = "Pourquoi tu ne dis rien ? Pourquoi tu ne cries pas ?! Ne me dis pas que je t’ai tellement effrayé que tu en es resté figé, ahahahaha ! On dirait bien que mes talents pour faire peur sont arrivés à maturité !",
          DialogueId = 51124002,
          GUID = "7FFBCB94",
          NextOptions = {
            [1] = 51124003,
            [2] = 51124004
          },
          SpeakNpcId = 701033,
          Subtitle = "What, nothing? No scream? Don't tell me I've scared you stiff — ahahahaha! My scaring technique really is flawless!",
          TalkActionId = {
            [1] = "701033:Confident_Start"
          }
        },
        [51124003] = {
          ContentFR = "<I>Pourquoi faire peur aux gens ici ?</>",
          DialogueId = 51124003,
          GUID = "7FFBCBBE",
          ImprPlusId = 1209,
          NextDialogue = 51124005,
          Subtitle = "Why are you jumping out at people like that?"
        },
        [51124004] = {
          ContentFR = "<I>Tu trouves ça amusant ?</>",
          DialogueId = 51124004,
          GUID = "7FFBCBE8",
          ImprPlusId = 1207,
          NextDialogue = 51124005,
          Subtitle = "You think this is funny?"
        },
        [51124005] = {
          ContentFR = "Hein ?! Tu parles ?! Alors tu n’es pas terrorisé à ce point-là !",
          DialogueId = 51124005,
          FacialId = {
            [1] = "701033:Shock01"
          },
          GUID = "7FFBCC12",
          NextDialogue = 51124006,
          SpeakNpcId = 701033,
          Subtitle = "Huh!? You can still talk!? So you weren't scared stiff after all!",
          TalkActionId = {
            [1] = "701033:Confident_End"
          }
        },
        [51124006] = {
          ContentFR = "Je suis en pleine recherche ! En train d’étudier comment une créature typique de Huaxu mène ses activités quotidiennes... et d’en reproduire quelques comportements simples !",
          DialogueId = 51124006,
          GUID = "7FFBCC3C",
          NextOptions = {
            [1] = 51124007,
            [2] = 51124009
          },
          SpeakNpcId = 701033,
          Subtitle = "I'm studying! Studying how one of Huaxu's special creatures lives day-to-day — and trying a little mimicry!",
          TalkActionId = {
            [1] = "701033:Excited01_Start"
          }
        },
        [51124007] = {
          ContentFR = "<I>Tu parles des Wishen ?</>",
          DialogueId = 51124007,
          GUID = "7FFBCC66",
          NextDialogue = 51124008,
          Subtitle = "You mean the Wishen?"
        },
        [51124008] = {
          ContentFR = "Quoi ?! Tu sais ce que sont les Wishen ?! Attends... ne me dis pas que—",
          DialogueId = 51124008,
          GUID = "7FFBCC90",
          NextDialogue = 51124011,
          SpeakNpcId = 701033,
          Subtitle = "What!? You actually know about them? I can't believe this...",
          TalkActionId = {
            [1] = "701033:Excited01_End"
          }
        },
        [51124009] = {
          ContentFR = "<I>Les Wishen n’agissent pas vraiment comme ça...</>",
          DialogueId = 51124009,
          GUID = "7FFBCCBA",
          NextDialogue = 51124010,
          Subtitle = "I don't think a Wishen moves like that, though..."
        },
        [51124010] = {
          ContentFR = "Hein ?! À t’entendre, on dirait presque que tu en as déjà vu de tes propres yeux ! Ne me dis pas que—",
          DialogueId = 51124010,
          GUID = "7FFBCCE4",
          NextDialogue = 51124011,
          SpeakNpcId = 701033,
          Subtitle = "Hmm!? You make it sound like you've actually seen one! I can't believe this..."
        },
        [51124011] = {
          ContentFR = "Ne me dis pas que mes recherches sur les Wishen ont fuité... que tous les habitants de Huaxu savent déjà ce que sont les Wishen... et que je ne suis plus la seule Luno à les étudier... ?!",
          DialogueId = 51124011,
          GUID = "7FFBCD0E",
          NextDialogue = 51124012,
          SpeakNpcId = 701033,
          Subtitle = "Don't tell me my precious research on the Wishen has leaked... that everyone in Huaxu already knows about them... and I'm no longer the only Luno studying them...!?",
          TalkActionId = {
            [1] = "701033:Shock03_Start"
          }
        },
        [51124012] = {
          ContentFR = "Si je ne suis plus la seule à étudier les Wishen, alors je perds ce qui me rend unique ! Je deviendrai une Luno comme les autres !",
          DialogueId = 51124012,
          GUID = "7FFBCD38",
          NextDialogue = 51124013,
          RestartTag = 51124012,
          SpeakNpcId = 701033,
          Subtitle = "If I'm not the only Luno studying the Wishen, what makes me special is gone — I'll just be another ordinary Luno!",
          TalkActionId = {
            [1] = "701033:Shock03_End"
          }
        },
        [51124013] = {
          ContentFR = "Non ! Je refuse absolument ça !",
          DialogueId = 51124013,
          GUID = "7FFBCD62",
          NextOptions = {
            [1] = 51124014,
            [2] = 51124016
          },
          SpeakNpcId = 701033,
          Subtitle = "No! Absolutely not! I refuse!"
        },
        [51124014] = {
          ContentFR = "<I>Ne pense pas comme ça. Tu es une Luno vraiment unique — au moins quand il s’agit de faire peur...</>",
          DialogueId = 51124014,
          GUID = "7FFBCD8C",
          ImprPlusId = 1209,
          NextDialogue = 51124015,
          Subtitle = "Don't say that. You are one of a kind — especially when it comes to giving people a proper scare..."
        },
        [51124015] = {
          ContentFR = "Hmm... Vu comme ça, ce n’est pas faux. Très bien ! Alors à partir d’aujourd’hui, j’abandonne le nom de « Luno, la spectrale » ! Désormais, je m’appellerai... Luno, la terrifiante !",
          DialogueId = 51124015,
          GUID = "7FFBCDB6",
          NextOptions = {
            [1] = 51124018
          },
          SpeakNpcId = 701033,
          Subtitle = "Mmm... you've got a point! Right then — I'm ditching the title Lunophantom this instant! From today on, I'll be... Lunohorror!"
        },
        [51124016] = {
          ContentFR = "<I>Je suis un Wishen.</>",
          DialogueId = 51124016,
          GUID = "7FFBCDE0",
          ImprPlusId = 1210,
          NextDialogue = 51124017,
          Subtitle = "I am a Wishen."
        },
        [51124017] = {
          ContentFR = "N’importe quoi ! Même si mes recherches ne sont plus uniques, je sais au moins une chose : les Wishen n’ont pas de corps matériel ! Et toi, tu es bien droit là, devant moi...",
          DialogueId = 51124017,
          GUID = "7FFBCE0A",
          NextOptions = {
            [1] = 51124018
          },
          SpeakNpcId = 701033,
          Subtitle = "As if! My research might not be one-of-a-kind any more, but I do know Wishen don't have solid bodies! And look at you — solid as anything!"
        },
        [51124018] = {
          ContentFR = "<I>Alors... si elle fait peur aux gens, c’est parce que...</>",
          DialogueId = 51124018,
          FailDialogue = 51124019,
          GUID = "7FFBCE34",
          ImprCheckId = 1130,
          NextDialogue = 51124020,
          Subtitle = "(So the reason she's scaring people out here is...)"
        },
        [51124019] = {
          ContentFR = "<I>Pourquoi tient-elle tant à effrayer les passants, au juste... ?</>",
          DialogueId = 51124019,
          GUID = "7FFBCE5E",
          SpeakNpcId = 100001,
          Subtitle = "(What's she doing out here trying to scare people?)"
        },
        [51124020] = {
          ContentFR = "Donc, au fond, peu importe ton titre... ce que tu veux vraiment, c’est être une Luno unique.",
          DialogueId = 51124020,
          GUID = "7FFBCE88",
          NextDialogue = 51124021,
          SpeakNpcId = 100001,
          Subtitle = "So it's not really about the title — you just want to be one of a kind."
        },
        [51124021] = {
          ContentFR = "Eeeeh ! Démasquée ! Tu m’as percée à jour ! Ahahaha ! Exactement ! Peu importe comment on m’appelle, je suis unique, moi !",
          DialogueId = 51124021,
          FacialId = {
            [1] = "701033:Happy02"
          },
          GUID = "7FFBCEB2",
          NextDialogue = 51124022,
          SpeakNpcId = 701033,
          Subtitle = "Eeee! You've seen straight through me! Haha! Exactly — I'm one of a kind, no matter what!",
          TalkActionId = {
            [1] = "701033:Explain01_Start"
          }
        },
        [51124022] = {
          ContentFR = "En tout cas, pour moi, tu es déjà une Luno très spéciale.",
          DialogueId = 51124022,
          GUID = "7FFBCEDC",
          NextDialogue = 51124023,
          SpeakNpcId = 100001,
          Subtitle = "Well, you're already pretty special to me.",
          TalkActionId = {
            [1] = "701033:Explain01_End"
          }
        },
        [51124023] = {
          ContentFR = "Vraiment ? Alors tu ne me confondras pas avec une autre Luno, hein ?",
          DialogueId = 51124023,
          GUID = "7FFBCF06",
          NextDialogue = 51124024,
          SpeakNpcId = 701033,
          Subtitle = "Really? You won't mix me up with other Lunos, right?",
          TalkActionId = {
            [1] = "701033:Shy03_Start"
          }
        },
        [51124024] = {
          ContentFR = "Je ne pense pas.",
          DialogueId = 51124024,
          GUID = "7FFBCF30",
          NextDialogue = 51124025,
          SpeakNpcId = 100001,
          Subtitle = "I don't think so.",
          TalkActionId = {
            [1] = "701033:Shy03_End"
          }
        },
        [51124025] = {
          ContentFR = "Héhé~ C’est mieux comme ça. Mais attention : si un jour tu me confonds avec une autre, je me fâcherai !",
          DialogueId = 51124025,
          FacialId = {
            [1] = "701033:Smile01"
          },
          GUID = "7FFBCF5A",
          NextDialogue = 51124026,
          SpeakNpcId = 701033,
          Subtitle = "Heehee~ That's better! But if you ever do mix me up with another Luno, I'll get really mad!",
          TalkActionId = {
            [1] = "701033:Explain01_Start"
          }
        },
        [51124026] = {
          ContentFR = "Bon, on va s’arrêter là pour aujourd’hui. Tu es {性别:un très gentil Descendant draconique|une très gentille Descendante draconique}. Mais moi, je dois continuer mes recherches sur les Wishen ! Et prouver que je suis la Luno la plus unique dans ce domaine !",
          DialogueId = 51124026,
          GUID = "7FFBCF84",
          SpeakNpcId = 701033,
          Subtitle = "Right! That's enough chatting for today! You're a lovely Loongscion. But I've still got more Wishen to study — I've got to prove my research is the most special of all!",
          TalkActionId = {
            [1] = "701033:Explain01_End"
          }
        },
        [51124027] = {
          ContentFR = "Je suis la plus unique des Luno... pas vrai ?",
          DialogueId = 51124027,
          GUID = "7FFBCFAE",
          SpeakNpcId = 701033,
          Subtitle = "I'm one of a kind, right?"
        },
        [51125000] = {
          ContentFR = "Quoi ?! Miaoqu est encore indisponible ?! Ça fait combien de jours que ça dure, cette histoire de mauvaise acclimatation ?! Pff... mais comment voulez-vous qu’on tourne les scènes de Port-des-Brumes dans ces conditions...",
