          GUID = "7FFC6F50",
          NextOptions = {
            [1] = 51125001,
            [2] = 51125002
          },
          SpeakNpcId = 700365,
          Subtitle = "What?! Miaoqu's still out? How many days has he had the trots? Ugh... How are we supposed to shoot all those Mistwharf scenes...",
          TalkActionId = {
            [1] = "700365:Angry01_Start"
          }
        },
        [51125001] = {
          ContentFR = "<I>Cet homme semble en difficulté. Allons voir s’il a besoin d’aide.</>",
