        [51125032] = {
          ContentFR = "<I>Attends... le script parlait vraiment d’une « Aiguille Empoisonnée de la Justice » ?</>",
          DialogueId = 51125032,
          GUID = "7FFC7490",
          SpeakNpcId = 100001,
          Subtitle = "(Wait, does the script actually say \"righteous poison needle\"?)"
        },
        [51125033] = {DialogueId = 51125033, GUID = "7FFC74BA"},
        [51125034] = {
          Camera = "-352.015625,-106.05957,152.610352,0.017523,-3.999574,17.508425,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "<I>Hmpf hmpf... </>Grand Magistrat, aussi héroïque soyez-vous, vous n’avez pas su voir l’aiguille dans votre dos.",
          DialogueId = 51125034,
          GUID = "7FFC74E4",
          NextDialogue = 51125035,
          SpeakNpcId = 700366,
          Subtitle = "Heh. Your Honour, for all your prowess, you never stood a chance against a needle in the back.",
          TalkActionId = {
            [1] = "700366:Talk03_Start"
          }
        },
        [51125035] = {
          Camera = "12.683594,-11.320312,144.433594,0.017532,-2.598996,1.708115,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Toi... ta famille a servi, génération après génération—",
          DialogueId = 51125035,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FFC750E",
          NextDialogue = 51125036,
          SpeakNpcId = 100001,
          Subtitle = "Your... your family for generations—"
        },
        [51125036] = {
          Camera = "43.136719,-3.177734,147.396484,0.017532,-2.399165,-177.490891,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et alors ?!",
          DialogueId = 51125036,
          GUID = "7FFC7538",
          NextDialogue = 51125037,
          SpeakNpcId = 700366,
          Subtitle = "So what!"
        },
        [51125037] = {
          Camera = "7.867188,-1148.030273,172.847656,0.017538,-3.199889,90.504539,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Attends, je n’ai pas fini ma réplique...",
          DialogueId = 51125037,
          GUID = "7FFC7562",
          NextDialogue = 51125038,
          SpeakNpcId = 100001,
          Subtitle = "Wait, let me finish my line.",
          TalkActionId = {
            [1] = "100001:RaiseHand_Start"
          }
        },
        [51125038] = {
          ContentFR = "Oh ! Ah ah, désolé, désolé. Je me suis laissé emporter. On recommence.",
          DialogueId = 51125038,
          GUID = "7FFC758C",
          NextDialogue = 51125039,
          SpeakNpcId = 700366,
          Subtitle = "Whoops, my bad — got a bit carried away. Let's take it from the top.",
          TalkActionId = {
            [1] = "100001:RaiseHand_End"
          }
        },
        [51125039] = {
          Camera = "-63.742188,-75.883789,146.362305,0.017534,-2.399595,19.908815,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Toi...  ta famille a servi, génération après génération, comme Officiants de l’Encens de la Secte Xuanheng, fidèles et irréprochables... comment a-t-elle pu engendrer—",
          DialogueId = 51125039,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FFC75B6",
          NextDialogue = 51125040,
          SpeakNpcId = 100001,
          Subtitle = "Your... your family for generations served as incense wardens of Xuanheng Sect, all loyal and honourable. How could they produce a scoundrel like—"
        },
        [51125040] = {
          Camera = "43.136719,-3.177734,147.396484,0.017532,-2.399165,-177.490891,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et alors ?!",
          DialogueId = 51125040,
          GUID = "7FFC75E0",
          NextDialogue = 51125041,
          SpeakNpcId = 700366,
          Subtitle = "So what!"
        },
        [51125041] = {
          Camera = "12.683594,-11.320312,144.433594,0.017532,-2.598996,1.708115,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je n’ai pas fini !",
          DialogueId = 51125041,
          GUID = "7FFC760A",
          NextDialogue = 51125042,
          SpeakNpcId = 100001,
          Subtitle = "Hey, what's wrong with you?",
          TalkActionId = {
            [1] = "100001:Sigh_Start"
          }
        },
        [51125042] = {
          Camera = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah... pardon, vraiment pardon. Je jouais trop sérieusement. Reprenons.",
          DialogueId = 51125042,
          GUID = "7FFC7634",
          NextDialogue = 51125043,
          SpeakNpcId = 700366,
          Subtitle = "Ah, blast — sorry, sorry! Really got into the moment there. Again, from the top.",
          TalkActionId = {
            [1] = "100001:Sigh_End"
          }
        },
        [51125043] = {
          Camera = "12.683594,-11.320312,144.433594,0.017532,-2.598996,1.708115,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Avant que je termine la phrase « Ta famille a servi, génération après génération, comme Officiants de l’Encens de la Secte Xuanheng, fidèles et irréprochables, comment a-t-elle pu engendrer une ordure comme toi », tu ne dis rien. Compris ?",
          DialogueId = 51125043,
          GUID = "7FFC765E",
          NextDialogue = 51125044,
          SpeakNpcId = 100001,
          Subtitle = "Do not speak your line — at all — until I finish: \"Your family for generations served as incense wardens of Xuanheng Sect, all loyal and honourable. How could they produce a scoundrel like you?\" Understood?"
        },
        [51125044] = {
          Camera = "325.265625,-73.105469,141.634766,0.017556,-1.600095,166.905365,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Compris ! Cette fois, promis !",
          DialogueId = 51125044,
          GUID = "7FFC7688",
          NextDialogue = 51125045,
          SpeakNpcId = 700366,
          Subtitle = "Understood! Won't happen this time!",
          TalkActionId = {
            [1] = "700366:Talk03_End"
          }
        },
        [51125045] = {
          DialogueId = 51125045,
          GUID = "7FFC76B2",
          IsBlack = 1,
          NextDialogue = 51125046
        },
        [51125046] = {
          ContentFR = "<I>Hmpf hmpf... </>Grand Magistrat, aussi héroïque soyez-vous, vous n’avez pas su voir l’aiguille dans votre dos.",
          DialogueId = 51125046,
          GUID = "7FFC76DC",
          NextDialogue = 51125047,
          SpeakNpcId = 700366,
          Subtitle = "Heh. Your Honour, for all your prowess, you never stood a chance against a needle in the back.",
          TalkActionId = {
            [1] = "700366:Talk03_Start"
          }
        },
        [51125047] = {
          Camera = "-63.742188,-75.883789,146.362305,0.017534,-2.399595,19.908815,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Toi... ta famille a servi, génération après génération, comme Officiants de l’Encens de la Secte Xuanheng, fidèles et irréprochables... comment a-t-elle pu engendrer une ordure comme toi ?!",
          DialogueId = 51125047,
          GUID = "7FFC7706",
          NextDialogue = 51125048,
          SpeakNpcId = 100001,
          Subtitle = "Your... your family for generations served as incense wardens of Xuanheng Sect, all loyal and honourable. How could they produce a scoundrel like you?"
        },
        [51125048] = {
          Camera = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et alors ?!",
          DialogueId = 51125048,
          GUID = "7FFC7730",
          NextDialogue = 51125049,
          SpeakNpcId = 700366,
          Subtitle = "So what!"
        },
        [51125049] = {
          ContentFR = "Tu sais ce que c’était, travailler pour la Secte Xuanheng ? Une paie misérable, de l’encens à respirer toute la journée, et presque aucun jour de repos !",
          DialogueId = 51125049,
          GUID = "7FFC775A",
          NextDialogue = 51125050,
          SpeakNpcId = 700366,
          Subtitle = "What did we even get out of working for the Xuanheng Sect, huh? Barely any pay, breathing in incense ash all day, hardly any days off."
        },
        [51125050] = {
          Camera = "12.683594,-11.320312,144.433594,0.017532,-2.598996,1.708115,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Toujours enchaînés aux règles des Neuf Chapitres de Dafeng. Même donner un coup de pied à un chien dans la rue était interdit ! Et si le chien avait un maître ? On risquait d’être accusés de violence !",
          DialogueId = 51125050,
          GUID = "7FFC7784",
          NextDialogue = 51125051,
          SpeakNpcId = 700366,
          Subtitle = "And we were always bound by the Nine Chapters — couldn't even kick a dog on the street! What if it had an owner? We'd be punished by Bi'an!"
        },
        [51125051] = {
          Camera = "43.136719,-3.177734,147.396484,0.017532,-2.399165,-177.490891,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Attends une seconde...",
          DialogueId = 51125051,
          GUID = "7FFC77AE",
          NextDialogue = 51125052,
          SpeakNpcId = 100001,
          Subtitle = "Wait a minute...",
          TalkActionId = {
            [1] = "100001:RaiseHand_Start"
          }
        },
        [51125052] = {
          ContentFR = "Quand tout allait bien, c’était « Toute gloire au Seigneur Dragon d’Argent » ! Mais dès que ça tournait mal, c’était notre faute ! Plutôt que ça, autant devenir un Vagabond, libre et sans chaînes ! Je suis... un... Va—gabond— !",
          DialogueId = 51125052,
          GUID = "7FFC77D8",
          NextDialogue = 51125053,
          SpeakNpcId = 700366,
          Subtitle = "None of the credit, either — when things went well, it was \"All praise to Lord Argent\" When they went south, it was our fault! I'd rather be a Drifter — free as the wind! I! Am! A! Drifter—!"
        },
        [51125053] = {
          Camera = "-352.015625,-106.05957,152.610352,0.017523,-3.999574,17.508425,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Stop ! Dis-moi... tout ça, c’est vraiment dans le script ?!",
          DialogueId = 51125053,
          GUID = "7FFC7802",
          NextDialogue = 51125054,
          SpeakNpcId = 100001,
          Subtitle = "Stop! Is any of this in the script?!",
          TalkActionId = {
            [1] = "100001:RaiseHand_End"
          }
        },
        [51125054] = {
          ContentFR = "Normalement, après ton « Et alors », tu devais me charger, et moi, malgré la douleur, vous terrasser tous...",
          DialogueId = 51125054,
          GUID = "7FFC782C",
          NextDialogue = 51125055,
          SpeakNpcId = 100001,
          Subtitle = "According to the script, after \"So what!\", you're supposed to rush me. Then I fight through the pain and take all you Drifters down..."
        },
        [51125055] = {
          Camera = "-183.84375,271.606445,161.805664,0.017533,-4.59964,-29.49268,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Réalisateur ! Ça ne va pas du tout !",
          DialogueId = 51125055,
          GUID = "7FFC7856",
          SpeakNpcId = 100001,
          Subtitle = "Director! This can't be right!"
        },
        [51125056] = {
          Camera = "2.65625,-886.189453,212.766602,0.017553,-6.600674,89.711586,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Coupez ! Coupez !",
          DialogueId = 51125056,
          GUID = "7FFC7880",
          NextDialogue = 51125057,
          SpeakNpcId = 700365,
          Subtitle = "Cut! Cut!",
          TalkActionId = {
            [1] = "700366:Talk03_End",
            [2] = "700365:Talk03_Start"
          }
        },
        [51125057] = {
          Camera = "520.042969,-611.853516,206.539062,0.01755,-6.400604,132.109695,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hengsheng... je comprends mieux maintenant. Quand Miaoqu était là, il te retenait. Maintenant qu’il est absent, tu te lâches complètement, hein ?",
          DialogueId = 51125057,
          GUID = "7FFC78AA",
          LookAt = {
            [1] = "700365:n(700366)"
          },
          NextDialogue = 51125058,
          SpeakNpcId = 700365,
          Subtitle = "Hengsheng, I know now — when Miaoqu was here, he kept you in check. Now that he's gone, you're just running wild, aren't you?",
          TalkActionId = {
            [1] = "700365:Talk03_End"
          }
        },
        [51125058] = {
          ContentFR = "Mais c’est vous qui nous l’avez appris, non ? Qu’un bon acteur devait savoir offrir à son rôle un moment fort !",
          DialogueId = 51125058,
          GUID = "7FFC78D4",
          LookAt = {
            [1] = "700366:n(700365)"
          },
          NextDialogue = 51125059,
          SpeakNpcId = 700366,
          Subtitle = "But Director, didn't you teach us that a good actor should always \"find the character's spotlight\"?"
        },
        [51125059] = {
          ContentFR = "<I>Tss...</> C’est vrai... j’ai bien dit ça.",
          DialogueId = 51125059,
          GUID = "7FFC78FE",
          NextDialogue = 51125060,
          SpeakNpcId = 700365,
          Subtitle = "Great... I did say that.",
          TalkActionId = {
            [1] = "700365:Think_Start"
          }
        },
        [51125060] = {
          ContentFR = "Vous voyez !",
          DialogueId = 51125060,
          GUID = "7FFC7928",
          NextDialogue = 51125061,
          SpeakNpcId = 700366,
          Subtitle = "See?"
        },
        [51125061] = {
          ContentFR = "Mais enfin ! Tu joues un antagoniste ! Un antagoniste qui doit se faire trancher en deux par le Magistrat ! Pourquoi un méchant aurait-il droit à un moment fort ?!",
          DialogueId = 51125061,
          GUID = "7FFC7952",
          NextDialogue = 51125062,
          SpeakNpcId = 700365,
          Subtitle = "No — you're playing the villain! You're supposed to be cut down by the Magistrate in the next scene! What \"spotlight\" does a villain need?",
          TalkActionId = {
            [1] = "700365:Think_End"
          }
        },
        [51125062] = {
          ContentFR = "Toujours les méchants ! Ça fait des années que je tourne avec vous, et vous ne me confiez que des rôles de méchants ! Même quand Miaoqu est absent, vous préférez donner le rôle du Magistrat à {性别:un inconnu|une inconnue} plutôt que de me laisser essayer !",
          DialogueId = 51125062,
          FacialId = {
            [1] = "700366:CM_Angry01"
          },
          GUID = "7FFC797C",
          NextDialogue = 51125063,
          SpeakNpcId = 700366,
          Subtitle = "Always a villain — I've been with your team for years, and you always stick me with the villains! Even with Miaoqu out, you'd rather give the Magistrate part to some stranger than let me have a go!"
        },
        [51125063] = {
          Camera = "43.136719,-3.177734,147.396484,0.017532,-2.399165,-177.490891,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Regarde-toi, avec cet air sournois ! Qui croirait qu’un Magistrat ressemble à ça ?",
          DialogueId = 51125063,
          GUID = "7FFC79A6",
          NextDialogue = 51125064,
          SpeakNpcId = 700365,
          Subtitle = "Just look at that smug face of yours! Who'd believe a Magistrate looks like that?"
        },
        [51125064] = {
          Camera = "127.339844,-18.349609,122.799805,0.017557,2.000023,179.711273,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pourquoi pas ? Vous disiez bien qu’un grand acteur avait une interprétation transformatrice ! Laissez-moi enfiler le costume du Magistrat, et je jouerai aussi bien que Miaoqu ! Au fond, vous ne faites juste pas confiance à mon jeu.",
          DialogueId = 51125064,
          GUID = "7FFC79D0",
          NextDialogue = 51125065,
          SpeakNpcId = 700366,
          Subtitle = "Why not? You also said a great actor should have \"transformative acting skills\". If you'd just let me suit up as a Magistrate, I'd play it just as well as Miaoqu! You just don't trust me."
        },
        [51125065] = {
          Camera = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ça suffit. Aujourd’hui, je ne joue plus. Je m’en vais !",
          DialogueId = 51125065,
          GUID = "7FFC79FA",
          NextDialogue = 51125066,
          SpeakNpcId = 700366,
          Subtitle = "You know what? I'm done for today! I'm out!"
        },
        [51125066] = {
          ContentFR = "Hé ! Attends ! Calme-toi ! On est sur la dernière ligne droite !",
          DialogueId = 51125066,
          GUID = "7FFC7A24",
          NextDialogue = 51125067,
          SpeakNpcId = 700365,
          Subtitle = "Hey — oi! Cool off! We're up against the clock today!"
        },
        [51125067] = {
          Camera = "-40.277344,-15.838867,165.15625,0.017561,-8.200645,2.511383,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{性别:Jeune homme|Jeune femme}, qu’en penses-tu ? Comme ça, on n’ira nulle part. Et si vous échangiez vos rôles ?",
          DialogueId = 51125067,
          GUID = "7FFC7A4E",
          LookAt = {
            [1] = "700365:n(100001)"
          },
          NextOptions = {
            [1] = 51125068,
            [2] = 51125069
          },
          SpeakNpcId = 700365,
          Subtitle = "...What do you think? This isn't working. How about... we swap your roles?",
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51125068] = {
          ContentFR = "<I>Puisqu’il y tient tant, laissons-lui le rôle.</>",
          DialogueId = 51125068,
          GUID = "7FFC7A78",
          ImprPlusId = 1209,
          NextDialogue = 51125070,
          Subtitle = "If he wants the part that badly, let him have it."
        },
        [51125069] = {
          ContentFR = "<I>D’accord... mais il faudra payer plus.</>",
          DialogueId = 51125069,
          GUID = "7FFC7AA2",
          ImprPlusId = 1201,
          NextDialogue = 51125070,
          Subtitle = "Fine. But it'll cost you extra."
        },
        [51125070] = {
          ContentFR = "Très bien. On fait comme ça.",
          DialogueId = 51125070,
          GUID = "7FFC7ACC",
          NextDialogue = 51125071,
          SpeakNpcId = 700365,
          Subtitle = "Done.",
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51125071] = {
          ContentFR = "Quelques minutes plus tard...",
          DialogueId = 51125071,
          GUID = "7FFC7AF6",
          IsBlack = 1,
          NextDialogue = 51125072,
          Subtitle = "A few minutes later..."
        },
        [51125072] = {
          Camera = "246.074219,-350.594727,117.375,0.01754,0.797944,105.297958,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51125072,
          GUID = "7FFC7B20",
          NextDialogue = 51125073,
          SpeakNpcId = 700365,
          Subtitle = "..."
        },
        [51125073] = {
          ContentFR = "...",
          DialogueId = 51125073,
          GUID = "7FFC7B4A",
          LookAt = {
            [1] = "100001:n(700365)"
          },
          NextDialogue = 51125074,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [51125074] = {
          ContentFR = "... Tu es {性别:sûr|sûre} de pouvoir jouer un antagoniste ? Avec cette aura, tu ressembles plutôt à ces héros de romans interdits, comment déjà... le « Justicier des Pics Extérieurs »...",
          DialogueId = 51125074,
          GUID = "7FFC7B74",
          NextDialogue = 51125075,
          SpeakNpcId = 700365,
          Subtitle = "Are you sure you can pull off a villain? You still look more like one of those \"Outer Peaks Swordsmen\" from those banned romance novels.."
        },
        [51125075] = {
          ContentFR = "Enfin... peu importe. Allons voir si Hengsheng est prêt de son côté.",
          DialogueId = 51125075,
          GUID = "7FFC7B9E",
          SpeakNpcId = 700365,
          Subtitle = "Never mind. Let's see if Hengsheng's ready."
        },
        [51125076] = {
          DialogueId = 51125076,
          GUID = "7FFC7BC8",
          IsBlack = 1
        },
        [51125077] = {
          Camera = "-515.558594,-201.037109,125.110352,0.017539,0.198321,23.096621,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Après plus de dix ans à jouer les antagonistes, c’est enfin mon tour d’incarner un héros ! Ha ha ha ha ha !",
          DialogueId = 51125077,
          GUID = "7FFC7BF2",
          NextDialogue = 51125078,
          SpeakNpcId = 700379,
          Subtitle = "After all these years, it's finally my turn to be the hero! Ahahahaha!"
        },
        [51125078] = {
          ContentFR = "Hé, regarde un peu ! Maintenant, je suis le Magistrat de Yingtian, rien que ça ! Alors, je suis classe, non ? <I>Fchhh — shaa — zhouh zhouh —</> ah !",
          DialogueId = 51125078,
          GUID = "7FFC7C1C",
          NextDialogue = 51125079,
          SpeakNpcId = 700379,
          Subtitle = "Hey, look at me now, I'm a Magistrate! Cool, right? Swoosh —  zing — Aiyah!"
        },
        [51125079] = {
          ContentFR = "Réalisateur, vous voyez ? Avouez que j’ai tout d’un véritable Magistrat !",
          DialogueId = 51125079,
          GUID = "7FFC7C46",
          NextDialogue = 51125080,
          SpeakNpcId = 700379,
          Subtitle = "See, Director? What did I tell you? Don't I look every bit the Magistrate now?"
        },
        [51125080] = {
          ContentFR = "Ça peut vraiment fonctionner, ça... ? Enfin... qui sait, une fois lancé, il sera peut-être plus sérieux. Allez, allez, tout le monde en place ! On tourne !",
          DialogueId = 51125080,
          GUID = "7FFC7C70",
          SpeakNpcId = 700365,
          Subtitle = "Is this really going to work?... Ah, forget about it. Maybe he'll settle into the role once we start rolling... Alright everyone, positions! Let's shoot this!"
        },
        [51125081] = {
          DialogueId = 51125081,
          GUID = "7FFC7C9A",
          IsBlack = 1
        },
        [51125082] = {
          ContentFR = "Maudit soit… je n’ai plus de forces !",
          DialogueId = 51125082,
          GUID = "7FFC7CC4",
          NextDialogue = 51125083,
          SpeakNpcId = 700379,
          Subtitle = "Blast it... I'm out of strength!"
        },
        [51125083] = {
          ContentFR = "Tous ensemble !",
          DialogueId = 51125083,
          GUID = "7FFC7CEE",
          SpeakNpcName = "UI_CMNpc_Name_QunYan",
          Subtitle = "Let's get him, lads!"
        },
        [51125084] = {
          DialogueId = 51125084,
          GUID = "7FFC7D18",
          IsBlack = 1
        },
        [51125085] = {
          ContentFR = "<I>Hmpf—</> Vermine ! Hah— Disparaissez !",
          DialogueId = 51125085,
          GUID = "7FFC7D42",
          NextDialogue = 51125086,
          SpeakNpcId = 700379,
          Subtitle = "Hmph — be gone! Hah — you villains!"
        },
        [51125086] = {
          ContentFR = "Incroyable... même entravé par la Corde, il tient encore ! Retraite, vite !",
          DialogueId = 51125086,
          GUID = "7FFC7D6C",
          NextDialogue = 51125087,
          SpeakNpcName = "UI_CMNpc_Name_QunYan",
          Subtitle = "He's still standing even bound by the Rope! Fall back, now!"
        },
        [51125087] = {
          ContentFR = "Hah ! Où croyez-vous fuir ?!",
          DialogueId = 51125087,
          GUID = "7FFC7D96",
          NextDialogue = 51125088,
          SpeakNpcId = 700379,
          Subtitle = "Hah! You think you can escape?!"
        },
        [51125088] = {
          ContentFR = "Prends ça !",
          DialogueId = 51125088,
          GUID = "7FFC7DC0",
          NextDialogue = 51125089,
          SpeakNpcId = 100001,
          Subtitle = "Take my poison needle!"
        },
        [51125089] = {
          ContentFR = "<I>Hmpf !</> Une simple aiguille empoisonnée ? J’en évite le tranchant sans difficulté !",
          DialogueId = 51125089,
          GUID = "7FFC7DEA",
          SpeakNpcId = 700379,
          Subtitle = "A mere poison needle? I'll simply evade its sting!"
        },
        [51125090] = {
          DialogueId = 51125090,
          GUID = "7FFC7E14",
          IsBlack = 1
        },
        [51125091] = {
          ContentFR = "Attends... Ça, ce n’était pas dans le script.",
          DialogueId = 51125091,
          GUID = "7FFC7E3E",
          NextDialogue = 51125092,
          SpeakNpcId = 100001,
          Subtitle = "Wait — that wasn't in the script."
        },
        [51125092] = {
          ContentFR = "Hi hi hi hi hi... Ton petit poison, ce n’est rien du tout. Regarde plutôt cette lame que je tiens : une épée imprégnée d’un poison mortel~",
          DialogueId = 51125092,
          GUID = "7FFC7E68",
          NextDialogue = 51125093,
          SpeakNpcId = 700379,
          Subtitle = "Ee-hee-hee... What's a little needle to me? This blade in my hand — is drenched in deadly poison."
        },
        [51125093] = {
          ContentFR = "<I>Il recommence à improviser...</>",
          DialogueId = 51125093,
          GUID = "7FFC7E92",
          SpeakNpcId = 100001,
          Subtitle = "(He's improvising again!)"
        },
        [51125094] = {
          DialogueId = 51125094,
          GUID = "7FFC7EBC",
          IsBlack = 1
        },
        [51125095] = {
          Camera = "493.785156,-135.24707,12.011719,0.017552,14.799428,162.905365,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Grand Magistrat, aussi héroïque soyez-vous, vous n’avez pas su voir l’aiguille dans votre dos.",
          DialogueId = 51125095,
          GUID = "7FFC7EE6",
          NextDialogue = 51125096,
          SpeakNpcId = 100001,
          Subtitle = "Heh. Your Honour, for all your prowess, you never stood a chance against a needle in the back."
        },
        [51125096] = {
          Camera = "43.136719,-3.177734,147.396484,0.017532,-2.399165,-177.490891,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 51125096,
          GUID = "7FFC7F10",
          NextDialogue = 51125097,
          SpeakNpcId = 700379,
          Subtitle = "..."
        },
        [51125097] = {
          Camera = "-63.742188,-75.883789,146.362305,0.017534,-2.399595,19.908815,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dis ta réplique !",
          DialogueId = 51125097,
          GUID = "7FFC7F3A",
          NextDialogue = 51125098,
          SpeakNpcId = 100001,
          Subtitle = "Your line!"
        },
        [51125098] = {
          Camera = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’était quoi, déjà ?",
          DialogueId = 51125098,
          GUID = "7FFC7F64",
          NextDialogue = 51125099,
          SpeakNpcId = 700379,
          Subtitle = "What was it?"
        },
        [51125099] = {
          Camera = "-40.277344,-15.838867,165.15625,0.017561,-8.200645,2.511383,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "« Toi... ta famille a servi, génération après génération, comme Officiants de l’Encens de la Secte Xuanheng, fidèles et irréprochables... comment a-t-elle pu engendrer une ordure comme toi ?! »",
          DialogueId = 51125099,
          GUID = "7FFC7F8E",
          NextDialogue = 51125100,
          SpeakNpcId = 100001,
          Subtitle = "\"Your family for generations served as incense wardens of Xuanheng Sect, all loyal and honourable. How could they produce a scoundrel like you?\""
        },
        [51125100] = {
          Camera = "7.867188,-1148.030273,172.847656,0.017538,-3.199889,90.504539,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hé, qui traites-tu d’ordure, exactement ? Pourquoi ce serait une ordure, hein ? Réfléchis un peu : tu sais ce que c’était, travailler pour la Secte Xuanheng ? Une paie misérable, de l’encens à respirer toute la journée, et presque aucun jour de repos !",
          DialogueId = 51125100,
          GUID = "7FFC7FB8",
          NextDialogue = 51125101,
          SpeakNpcId = 700379,
          Subtitle = "Hey, who are you calling a scoundrel? Think about it — what did we even get out of working for the Xuanheng Sect, huh? Barely any pay, breathing in incense ash all day, hardly any days off."
        },
        [51125101] = {
          ContentFR = "Toujours enchaînés aux règles des Neuf Chapitres de Dafeng. Même donner un coup de pied à un chien dans la rue était interdit ! Et si le chien avait un maître ? On risquait d’être accusés de violence !",
          DialogueId = 51125101,
          GUID = "7FFC7FE2",
          NextDialogue = 51125102,
          SpeakNpcId = 700379,
          Subtitle = "And we were always bound by the Nine Chapters — couldn't even kick a dog on the street! What if it had an owner? We'd be punished by Bi'an!"
        },
        [51125102] = {
          Camera = "-40.277344,-15.838867,165.15625,0.017561,-8.200645,2.511383,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Attends une seconde...",
          DialogueId = 51125102,
          GUID = "7FFC800C",
          NextDialogue = 51125103,
          SpeakNpcId = 100001,
          Subtitle = "Wait...",
          TalkActionId = {
            [1] = "100001:RaiseHand_Start"
          }
        },
        [51125103] = {
          Camera = "55.546875,-172.925781,148.643555,0.017533,-2.399322,141.50882,45.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quand tout allait bien, c’était « Toute gloire au Seigneur Dragon d’Argent » ! Mais dès que ça tournait mal, c’était notre faute ! Plutôt que ça, autant devenir un Vagabond, libre et sans chaînes !",
          DialogueId = 51125103,
          GUID = "7FFC8036",
          NextDialogue = 51125104,
          SpeakNpcId = 700379,
          Subtitle = "None of the credit, either — when things went well, it was \"All praise to Lord Argent\" When they went south, it was our fault!"
        },
        [51125104] = {
          ContentFR = "Hé hé... On va voir si la vie du Magistrat est plus solide que la lame d’un Vagabond ! Goûte à mon Aiguille Empoisonnée de la Justice !",
          DialogueId = 51125104,
          GUID = "7FFC8060",
          SpeakNpcId = 700379,
          Subtitle = "Heheh... We'll see what's harder — the Magistrate's life, or my blade!"
        },
        [51125105] = {DialogueId = 51125105, GUID = "7FFC808A"},
        [51125106] = {
          Camera = "2.65625,-886.189453,212.766602,0.017553,-6.600674,89.711586,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Magnifique ! Fluide, percutant, sans la moindre hésitation ! Hengsheng, tu es vraiment un antagoniste né, unique en son genre !",
          DialogueId = 51125106,
          FacialId = {
            [1] = "700365:CM_Happy01"
          },
          GUID = "7FFC80B4",
          NextDialogue = 51125107,
          SpeakNpcId = 700365,
          Subtitle = "Brilliant! Smooth as silk, flawless from start to finish! Hengsheng, you were born to play the villain!"
        },
        [51125107] = {
          ContentFR = "On arrête là ! C’est fini pour aujourd’hui, on plie ! Pour les scènes du Port-des-Brumes, je vais devoir compter sur mon montage de réalisateur pour sauver ce qui peut l’être...",
          DialogueId = 51125107,
          GUID = "7FFC80DE",
          LookAt = {
            [1] = "700365:n(700379)"
          },
          NextDialogue = 51125108,
          SpeakNpcId = 700365,
          Subtitle = "That's a wrap! We're done here! I'll just have to save the Mistwharf scenes in the editing room."
        },
        [51125108] = {
          ContentFR = "{性别:Jeune homme|Jeune femme}, voilà ta rémunération pour aujourd’hui. C’est amplement mérité.",
          DialogueId = 51125108,
          GUID = "7FFC8108",
          LookAt = {
            [1] = "700365:n(100001)"
          },
          NextDialogue = 51125109,
          SpeakNpcId = 700365,
          Subtitle = "Here {性别:brother|lass}, your pay for today. You've earned it."
        },
        [51125109] = {
          ContentFR = "Cette farce aussi absurde qu’improbable touche enfin à sa fin. Hengsheng a obtenu ce qu’il désirait tant : son moment de gloire... du moins, en apparence.",
          DialogueId = 51125109,
          GUID = "7FFC8132",
          IsBlack = 1,
          Subtitle = "(And so, this utterly absurd farce finally came to a close. Hengsheng had gotten his wish — his moment in the spotlight… or so it seemed.)"
        },
        [51125201] = {
          ContentFR = "<I>Hrr...</> enfin terminé. Rien d’oublié, cette fois ?",
          DialogueId = 51125201,
          GUID = "7FFC904A",
          NextDialogue = 51125202,
          SpeakNpcId = 701034,
          Subtitle = "Phew... that's the last of it. We're not short of anything, are we?"
        },
        [51125202] = {
          ContentFR = "Pas encore. Zhuang est en congé aujourd’hui, il faut aussi transporter sa part.",
          DialogueId = 51125202,
          GUID = "7FFC9074",
          NextDialogue = 51125203,
          SpeakNpcId = 701035,
          Subtitle = "Zhuang's off today — we've got to finish his load too."
        },
        [51125203] = {
          ContentFR = "Pourquoi ne vient-il pas demain s’en charger lui-même ?",
          DialogueId = 51125203,
          GUID = "7FFC909E",
          NextDialogue = 51125204,
          SpeakNpcId = 701034,
          Subtitle = "And why can't he haul it himself tomorrow?"
        },
        [51125204] = {
          ContentFR = "Il a une bonne nouvelle à la maison. Il a promis de nous inviter à boire le thé à son retour !",
          DialogueId = 51125204,
          GUID = "7FFC90C8",
          NextDialogue = 51125205,
          SpeakNpcId = 701035,
          Subtitle = "Says there's good news at home. When he's back, he's treating us to tea."
        },
        [51125205] = {
          ContentFR = "Hé ! Fêter sans nous ? Il nous devra au moins une bonne théière de son meilleur Bimao !",
          DialogueId = 51125205,
          GUID = "7FFC90F2",
          SpeakNpcId = 701034,
          Subtitle = "Ha! Celebrating without us, is he? I'll make him cough up a pot of his finest!"
        },
        [51125301] = {
          ContentFR = "Franchement, Huaxu est l’un des endroits les plus sûrs. Tu vois ces Bi’an en patrouille ? Au moindre méfait, ils interviennent aussitôt.",
          DialogueId = 51125301,
          GUID = "7FFCA0B2",
          NextDialogue = 51125302,
          SpeakNpcId = 701036,
          Subtitle = "You've got to admit, Huaxu's one of the safest places around. See those Bi'an patrols everywhere? The moment someone stirs up trouble, they pounce and bring them down."
        },
        [51125302] = {
          ContentFR = "<I>Hmpf.</> Hyperborea est tout aussi sûr. Tu connais la réputation de la Légion ? La cavalerie de l’Empire écrase toute rébellion.",
          DialogueId = 51125302,
          GUID = "7FFCA0DC",
          NextDialogue = 51125303,
          SpeakNpcId = 701037,
          Subtitle = "Hmph. Hyperborea's just as safe, I'll have you know. Ever heard of the Hyperborean Legion? The Empire's cavalry silences any whisper of rebellion."
        },
        [51125303] = {
          ContentFR = "Tu plaisantes ? Tous les Tisse-Étoiles revenus de l’étranger disent qu’Hyperborea est sans cesse en guerre au sud. C’est ça, la sécurité ?",
          DialogueId = 51125303,
          GUID = "7FFCA106",
          NextDialogue = 51125304,
          SpeakNpcId = 701036,
          Subtitle = "Oh, come off it. Every Starweaver back from abroad says Hyperborea's always at war with the south. You call that safe?"
        },
        [51125304] = {
          ContentFR = "La guerre... c’est la force de l’Empire... on combat pour la paix !",
          DialogueId = 51125304,
          GUID = "7FFCA130",
          NextDialogue = 51125305,
          SpeakNpcId = 701037,
          Subtitle = "Uh... well, that's how the Empire shows its might. We fight for peace, don't you see?"
        },
        [51125305] = {
          ContentFR = "Alors pourquoi vouloir vivre à Huaxu ? Ici, tant que tu agis avec droiture, le Seigneur Dragon d’Argent veille sur toi jour après jour.",
          DialogueId = 51125305,
          GUID = "7FFCA15A",
          SpeakNpcId = 701036,
          Subtitle = "Pfft. Then why did you come all the way to move to Huaxu, eh? Trust me, mate — keep a good heart here and Lord Argent will see you safe day in, day out."
        },
        [51125401] = {
          ContentFR = "Cette tour en ruine a de l’âge... elle devait être jadis une œuvre de la Secte Jishu. La laisser ainsi aux intempéries, sans entretien...",
          DialogueId = 51125401,
          GUID = "7FFCB11A",
          NextOptions = {
            [1] = 51125402
          },
          SpeakNpcId = 701038,
          Subtitle = "This old tower's seen better days. I'd wager it was fine work of our sect once. Hard to watch it left to wind and rain, with no one to tend it..."
        },
        [51125402] = {
          ContentFR = "<I>À quoi servait-elle ?</>",
          DialogueId = 51125402,
          GUID = "7FFCB144",
          NextDialogue = 51125403,
          Subtitle = "What was it for?"
        },
        [51125403] = {
          ContentFR = "Autrefois, c’était une Tour de Divination, construite par notre secte pour les Tisse-Étoiles. Aujourd’hui... plus que du métal rouillé abandonné.",
          DialogueId = 51125403,
          GUID = "7FFCB16E",
          NextOptions = {
            [1] = 51125404
          },
          SpeakNpcId = 701038,
          Subtitle = "Back in the day, our sect built it for the Starweavers — they called it a Tower of Divination. These days it's just forgotten scrap and rust."
        },
        [51125404] = {
          ContentFR = "<I>Tour de Divination ?</>",
          DialogueId = 51125404,
          GUID = "7FFCB198",
          NextDialogue = 51125405,
          Subtitle = "Tower of Divination?"
        },
        [51125405] = {
          ContentFR = "Elle servait à observer les cieux, à estimer auspices et calamités. Rien de mystique : elle permettait surtout d’étudier les étoiles et de prévoir la météo.",
          DialogueId = 51125405,
          GUID = "7FFCB1C2",
          NextOptions = {
            [1] = 51125406
          },
          SpeakNpcId = 701038,
          Subtitle = "Right — for reading the heavens and charting omens and fortunes, or so they said. In truth, nothing so mystical: it helped them study the stars and forecast the days ahead."
        },
        [51125406] = {
          ContentFR = "<I>Pourquoi a-t-elle été abandonnée ?</>",
          DialogueId = 51125406,
          GUID = "7FFCB1EC",
          NextDialogue = 51125407,
          Subtitle = "Why was it abandoned?"
        },
        [51125407] = {
          ContentFR = "... C’est une longue histoire. La Secte Jishu déclina, plus personne pour l’entretenir, et les mesures perdirent en précision.",
          DialogueId = 51125407,
          GUID = "7FFCB216",
          NextDialogue = 51125408,
          SpeakNpcId = 701038,
          Subtitle = "Ah, that's a long one. It began when the Jishu Sect fell on hard times — few were left to tend the towers, and the readings grew increasingly unreliable."
        },
        [51125408] = {
          ContentFR = "Plus tard, les Tisse-Étoiles perfectionnèrent les Panneaux aux Mille Étoiles, rendant ces tours inutiles.",
          DialogueId = 51125408,
          GUID = "7FFCB240",
          NextDialogue = 51125409,
          SpeakNpcId = 701038,
          Subtitle = "Later, the Starweavers refined their Stellapasses — clever things. They could forecast the weather well enough on their own, so the towers were no longer needed."
        },
        [51125409] = {
          ContentFR = "À mon avis, si la secte avait conservé son éclat d’il y a cent ans, cette tour aurait trouvé un nouvel usage.",
          DialogueId = 51125409,
          GUID = "7FFCB26A",
          NextDialogue = 51125410,
          SpeakNpcId = 701038,
          Subtitle = "Still, if you ask me — had the Jishu Sect been what it was a century ago, these towers would have found new purposes by now."
        },
        [51125410] = {
          ContentFR = "Hélas... tout cela appartient au passé. À quoi bon remuer la poussière...",
          DialogueId = 51125410,
          GUID = "7FFCB294",
          SpeakNpcId = 701038,
          Subtitle = "*sigh* It's long past now. No sense raking through the dust. Let it be."
        },
        [51125501] = {
          ContentFR = "{性别:Ami venu|Amie venue} de loin, pourriez-vous vous décaler un instant ?",
          DialogueId = 51125501,
          GUID = "7FFCC182",
          NextOptions = {
            [1] = 51125502,
            [2] = 51125505
          },
          SpeakNpcId = 701039,
          Subtitle = "Hey there, friend from afar — give us a bit of space, yeah?"
        },
        [51125502] = {
          ContentFR = "{性别:Désolé|Désolée}.",
          DialogueId = 51125502,
          GUID = "7FFCC1AC",
          ImprPlusId = 1207,
          NextDialogue = 51125503,
          Subtitle = "Ah, my bad."
        },
        [51125503] = {
          ContentFR = "Ce n’est rien. Vous venez d’arriver à Huaxu, j’imagine ? Il est normal de ne pas connaître les lieux. Si quelque chose vous intrigue, n’hésitez pas à venir me voir.",
          DialogueId = 51125503,
          GUID = "7FFCC1D6",
          NextDialogue = 51125504,
          SpeakNpcId = 701039,
          Subtitle = "No worries at all. First time in Huaxu, eh? It's normal not to know your way around. If there's anything you don't get, just holler."
        },
        [51125504] = {
          ContentFR = "Même si j’ai l’air tout à fait ordinaire, je compte tout de même parmi les meilleurs commis au comptage du Quai-aux-Étoiles. Astronomie, géographie, coutumes locales... je pourrais vous en parler pendant des heures.",
          DialogueId = 51125504,
          GUID = "7FFCC200",
          SpeakNpcId = 701039,
          Subtitle = "I might not look like much, but I'm one of the best tallymen on Starwharf. Ask me anything — from the skies above to life on the streets — I've got it all down pat."
        },
        [51125505] = {
          ContentFR = "<I>Cette route ne vous appartient pas, si ?</>",
          DialogueId = 51125505,
          GUID = "7FFCC22A",
          ImprPlusId = 1210,
          NextDialogue = 51125506,
          Subtitle = "You don't own this road."
        },
        [51125506] = {
          ContentFR = "Oh là, {性别:ami venu|amie venue} de loin, inutile de vous emporter ! Je vous prévenais par gentillesse. Le port est constamment traversé par des manutentionnaires chargés de lourds fardeaux. Un faux pas, et vous pourriez vous blesser.",
          DialogueId = 51125506,
          GUID = "7FFCC254",
          NextDialogue = 51125507,
          SpeakNpcId = 701039,
          Subtitle = "Whoa there, friend from afar — no need to get all worked up! I'm just looking out for you. Porters come and go here all day, hauling heavy stuff. One wrong bump and you'll get hurt."
        },
        [51125507] = {
          ContentFR = "Quand on arrive à Huaxu, tout cela peut sembler déroutant. Si quelque chose vous échappe, venez me demander. Je ne suis qu’un commis au comptage, certes, mais je suis né et j’ai grandi ici.",
          DialogueId = 51125507,
          GUID = "7FFCC27E",
          SpeakNpcId = 701039,
          Subtitle = "First time in Huaxu, eh? It's normal not to know your way around. If there's anything you don't get, just holler. I may just be a tallyman, but hey — I grew up here."
        },
        [51125508] = {
          ContentFR = "Cinquante livres de Givrefeuille, trente de Printemps d’Excellence... Hé, hé, doucement par là-bas ! Les épices sont des denrées rares, manipulez-les avec soin !",
          DialogueId = 51125508,
          GUID = "7FFCC2A8",
          NextDialogue = 51125509,
          Subtitle = "Fifty catties of Frostleaf, thirty of Vernal Prime — whoa, easy there! Those aromatics are rare stuff!"
        },
        [51125509] = {
          ContentFR = "Tiens donc, vous êtes encore là ? L’{性别:ami étranger|amie étrangère} fraîchement arrivé à Huaxu... Seriez-vous en réalité {性别:un petit marchand venu|une petite marchande venue} observer le quotidien d’un humble commis au comptage ?",
          DialogueId = 51125509,
          GUID = "7FFCC2D2",
          NextOptions = {
            [1] = 51125510,
            [2] = 51125527
          },
          SpeakNpcId = 701039,
          Subtitle = "Hey, look who it is! Still hanging around Starwharf, huh? What's this then — come to trade, young merchant? Or just curious to see how we tallymen earn our rice?"
        },
        [51125510] = {
          ContentFR = "<I>J’ai quelque chose à vous demander.</>",
          DialogueId = 51125510,
          GUID = "7FFCC2FC",
          NextDialogue = 51125511,
          Subtitle = "I have something to ask you."
        },
        [51125511] = {
          ContentFR = "Je vous écoute. Tout ce que je sais, je vous le dirai.",
          DialogueId = 51125511,
          GUID = "7FFCC326",
          NextOptions = {
            [1] = 51125512,
            [2] = 51125516
          },
          SpeakNpcId = 701039,
          Subtitle = "Ask away, friend! Anything I know, I'll share."
        },
        [51125512] = {
          ContentFR = "<I>En quoi consiste le travail de commis au comptage ?</>",
          DialogueId = 51125512,
          GUID = "7FFCC350",
          NextDialogue = 51125513,
          Subtitle = "What's a tallyman do?"
        },
        [51125513] = {
          ContentFR = "Commis au comptage... comme le nom l’indique, nous aidons les Tisse-Étoiles à recenser leurs marchandises.",
          DialogueId = 51125513,
          GUID = "7FFCC37A",
          NextDialogue = 51125514,
          SpeakNpcId = 701039,
          Subtitle = "Pretty much what the name says — we help the Starweavers keep track of their cargo."
        },
        [51125514] = {
          ContentFR = "Le Quai-aux-Étoiles voit passer un nombre incalculable de navires chaque jour. Si les Tisse-Étoiles devaient tout vérifier eux-mêmes, ils n’auraient plus une minute de répit.",
          DialogueId = 51125514,
          GUID = "7FFCC3A4",
          NextDialogue = 51125515,
          SpeakNpcId = 701039,
          Subtitle = "You see, Starwharf's busy every day — ships coming and going nonstop. If the Starweavers had to handle all the counting, they'd never get a break."
        },
        [51125515] = {
          ContentFR = "Nous sommes donc là pour comptabiliser les cargaisons entrant et sortant du port, afin d’éviter tout manque. Sans quoi il serait difficile de rendre des comptes aux acheteurs étrangers.",
          DialogueId = 51125515,
          GUID = "7FFCC3CE",
          NextOptions = {
            [1] = 51125516,
            [2] = 51125527
          },
          SpeakNpcId = 701039,
          Subtitle = "That's where we tallymen come in. We check what's coming and going, make sure nothing's short — otherwise the Starweavers would have a hard time explaining it to their buyers in distant lands."
        },
        [51125516] = {
          ContentFR = "<I>Les Tisse-Étoiles doivent donc tout déclarer ?</>",
          DialogueId = 51125516,
          GUID = "7FFCC3F8",
          NextDialogue = 51125517,
          Subtitle = "So the Starweavers here have to log everything coming in and out?"
        },
        [51125517] = {
          ContentFR = "Bien entendu. Le commerce de Huaxu est florissant, et le Bureau de la Fortune Céleste applique une gestion rigoureuse. Toute marchandise importée ou exportée est soumise à taxation.",
          DialogueId = 51125517,
          GUID = "7FFCC422",
          NextDialogue = 51125518,
          SpeakNpcId = 701039,
          Subtitle = "Naturally! Trade's booming here in Huaxu, and the Ministry of Fortune's got rules — whatever comes in or goes out gets taxed."
        },
        [51125518] = {
          ContentFR = "Par ailleurs, certaines épices font l’objet de quotas très stricts. Prenez le Lys céleste : la demande locale est énorme. Si les Tisse-Étoiles l’exportaient sans limite, que nous resterait-il ?",
          DialogueId = 51125518,
          GUID = "7FFCC44C",
          NextDialogue = 51125519,
          SpeakNpcId = 701039,
          Subtitle = "And some of the key incense materials — they've got strict limits. Take Skylilies, for instance: folks here burn a lot of it. If the Starweavers ship it all overseas, what are we supposed to do when we run short?"
        },
        [51125519] = {
          ContentFR = "Quant aux marchandises entrant à Huaxu, la vigilance est encore plus grande. D’Hyperborea arrivent parfois armes et mécanismes... laisser passer cela sans contrôle sèmerait le chaos.",
          DialogueId = 51125519,
          GUID = "7FFCC476",
          NextOptions = {
            [1] = 51125520,
            [2] = 51125524,
            [3] = 51125527
          },
          SpeakNpcId = 701039,
          Subtitle = "And what's coming in needs even tighter checks! Take Hyperborea — blades, firearms, that sort of stuff. Let all that in unchecked and Huaxu'd be a madhouse!"
        },
        [51125520] = {
          ContentFR = "<I>Et si des marchandises interdites se glissaient dans les cargaisons ?</>",
          DialogueId = 51125520,
          GUID = "7FFCC4A0",
          NextDialogue = 51125521,
          Subtitle = "So what happens if something illegal slips through?"
        },
        [51125521] = {
          ContentFR = "Ah, ce n’est pas si simple, mon {性别:ami|amie}. Les commis au comptage expérimentés reconnaissent une cargaison d’un coup d’œil... ou à son parfum.",
          DialogueId = 51125521,
          GUID = "7FFCC4CA",
          NextDialogue = 51125522,
          SpeakNpcId = 701039,
          Subtitle = "Ha! My friend, it's not that easy. We tallymen've been at this forever — one look, one sniff, and we know what's in the crate."
        },
        [51125522] = {
          ContentFR = "Et voyez ces Bi’an qui patrouillent le port. Ce que nous détectons, ils le confirment. Et ce que nous manquons... ne leur échappe jamais.",
          DialogueId = 51125522,
          GUID = "7FFCC4F4",
          NextDialogue = 51125523,
          SpeakNpcId = 701039,
          Subtitle = "See those Bi'an patrolling the docks? What we catch, they spot — and what we don't, ha, they still will."
        },
        [51125523] = {
          ContentFR = "Ils arpentent le quai jour et nuit. Leur flair est infaillible : une seule inspiration, et ils savent qui cache quoi.",
          DialogueId = 51125523,
          GUID = "7FFCC51E",
          SpeakNpcId = 701039,
          Subtitle = "Those Bi'an keep watch day and night to stop anything shady from getting into Huaxu. Their noses? Sharp as can be — one sniff and they'll know exactly who's hiding what."
        },
        [51125524] = {
          ContentFR = "<I>Vous n’êtes donc pas un Tisse-Étoiles ?</>",
          DialogueId = 51125524,
          GUID = "7FFCC548",
          NextDialogue = 51125525,
          Subtitle = "Oh, so you're not a Starweaver?"
        },
        [51125525] = {
          ContentFR = "Oui... et non. À Huaxu, devenir Tisse-Étoiles est simple, mais ce n’est pas une obligation.",
          DialogueId = 51125525,
          GUID = "7FFCC572",
          NextDialogue = 51125526,
          SpeakNpcId = 701039,
          Subtitle = "Yes and no. In Huaxu, anyone can be a Starweaver if they want — but why bother?"
        },
        [51125526] = {
          ContentFR = "Le commerce a ses hauts et ses bas. Moi, je préfère une vie tranquille : un travail stable, une paie régulière. Pourquoi partir en mer pendant des mois et délaisser son foyer ?",
          DialogueId = 51125526,
          GUID = "7FFCC59C",
          SpeakNpcId = 701039,
          Subtitle = "You know how it is for traders — sometimes they make a fortune, sometimes they lose their shirts. Me, I keep it simple — easy job, steady coin. Why run off to sea like them and barely ever see home?"
        },
        [51125527] = {
          ContentFR = "<I>Je vais poursuivre ma route.</>",
          DialogueId = 51125527,
          GUID = "7FFCC5C6",
          NextDialogue = 51125528,
          Subtitle = "I should get going."
        },
        [51125528] = {
          ContentFR = "Bonne promenade ! Revenez me voir si une question vous traverse l’esprit.",
          DialogueId = 51125528,
          GUID = "7FFCC5F0",
          SpeakNpcId = 701039,
          Subtitle = "Have a nice day, friend! If you've got questions, you know where to find me!"
        },
        [51125601] = {
          ContentFR = "Approchez, {性别:cher client|chère cliente}. Ici, nous vendons l’indispensable du voyage à Huaxu. Et surtout ces sachets de Lune Profonde : pour recevoir la bénédiction du Dragon d’Argent, nul ne saurait s’en passer !",
          DialogueId = 51125601,
          GUID = "7FFCD1EA",
          NextOptions = {
            [1] = 51125602,
            [2] = 51125604
          },
          SpeakNpcId = 701040,
          Subtitle = "Good taste, my friend — Huaxu's finest, right here. These Lunarose sachets above all: if you'd seek Lord Argent's favour, you'll want one."
        },
        [51125602] = {
          ContentFR = "<I>Quelqu’un m’en a déjà offert un.</>",
          DialogueId = 51125602,
          GUID = "7FFCD214",
          ImprPlusId = 1209,
          NextDialogue = 51125603,
          Subtitle = "Someone already gave me one."
        },
        [51125603] = {
          ContentFR = "Oh ? Vous venez rendre visite à un ami à Huaxu ? Un Tisse-Étoiles, peut-être ? Aucun souci ! J’ai bien d’autres merveilles. Que diriez-vous d’un éventail de soie ? Ou d’un miroir laqué aux motifs dorés ?",
          DialogueId = 51125603,
          GUID = "7FFCD23E",
          SpeakNpcId = 701040,
          Subtitle = "Oh? So you've friends in Huaxu — maybe a Starweaver brought you? No matter! I've plenty besides sachets — a silk fan, perhaps, or an embossed gilt-lacquered mirror?"
        },
        [51125604] = {
          ContentFR = "<I>Je n’ai pas d’argent. Vous pourriez m’en offrir un ?</>",
          DialogueId = 51125604,
          GUID = "7FFCD268",
          ImprPlusId = 1210,
          NextDialogue = 51125605,
          Subtitle = "I'm short on cash — any chance I could get a freebie?"
        },
        [51125605] = {
          ContentFR = "Ha ha ! Vous avez le sens de l’humour. Mais après tout... pourquoi pas ? Les sachets de Lune Profonde sont courants ici. Choisissez-en un, je vous l’offre.",
          DialogueId = 51125605,
          GUID = "7FFCD292",
          NextDialogue = 51125606,
          SpeakNpcId = 701040,
          Subtitle = "Ha! You jest — but why not? Lunarose sachets are common enough here. Go on, take whichever you fancy!"
        },
        [51125606] = {
          ContentFR = "Et quand la fortune vous sourira à Huaxu, revenez donc m’acheter quelques souvenirs pour vos proches.",
          DialogueId = 51125606,
          GUID = "7FFCD2BC",
          SpeakNpcId = 701040,
          Subtitle = "One day, when you've coin to spare, come back and take a few souvenirs for your friends and family."
        },
        [51125607] = {
          ContentFR = "Souvenirs pour voyageurs étrangers ! À Huaxu, nul visiteur ne devrait passer à côté ! Sachets parfumés, éventails de soie, antiquités, trésors rares... tout ce que vous désirez !",
          DialogueId = 51125607,
          GUID = "7FFCD2E6",
          NextDialogue = 51125608,
          SpeakNpcId = 701040,
          Subtitle = "Souvenirs for travellers! First time in Huaxu? Don't pass me by — sachets, folding fans, curios, trinkets, all the little treasures you could want!"
        },
        [51125608] = {
          ContentFR = "Bienvenue ! Regardez à votre guise. Si quelque chose vous plaît, parlons-en : les prix se négocient.",
          DialogueId = 51125608,
          GUID = "7FFCD310",
          NextOptions = {
            [1] = 51125609,
            [2] = 51125620,
            [3] = 51125622
          },
          SpeakNpcId = 701040,
          Subtitle = "Ah, welcome! Take your time — see what takes your fancy. If something catches your eye, just give me a word and we'll talk price."
        },
        [51125609] = {
          ContentFR = "<I>Avez-vous des objets vraiment indispensables ? En dehors des sachets.</>",
          DialogueId = 51125609,
          GUID = "7FFCD33A",
          NextDialogue = 51125610,
          Subtitle = "Any must-haves besides the sachets?"
        },
        [51125610] = {
          ContentFR = "Bien sûr ! Voyez ce rouleau des Neuf Chapitres de Dafeng. Tout y est consigné avec clarté. Ainsi, de retour dans votre patrie, vous pourrez en parler preuves à l’appui.",
          DialogueId = 51125610,
          GUID = "7FFCD364",
          NextDialogue = 51125611,
          SpeakNpcId = 701040,
          Subtitle = "Of course! Here — this hanging scroll, every verse of the Nine Chapters of Dafeng laid out clear as day. Take it home, and you'll have the perfect piece to show your friends."
        },
        [51125611] = {
          ContentFR = "Et ces bijoux typiques de Huaxu : des modèles appréciés aussi bien des anciens que des enfants. Des classiques intemporels.",
          DialogueId = 51125611,
          GUID = "7FFCD38E",
          NextDialogue = 51125612,
          SpeakNpcId = 701040,
          Subtitle = "And take a look at our Huaxu exclusives — traditional pieces, well loved by both young and old."
        },
        [51125612] = {
          ContentFR = "Pour quelque chose de plus singulier, nous avons aussi des pièces inspirées des insectes, idéales pour affirmer un goût hors du commun.",
          DialogueId = 51125612,
          GUID = "7FFCD3B8",
          NextDialogue = 51125613,
          SpeakNpcId = 701040,
          Subtitle = "If you fancy something a bit different, we've insect-motif pieces too — just the thing for a unique taste."
        },
        [51125613] = {
          ContentFR = "Ah ! Et ne manquez pas nos nouvelles bougies parfumées. Une senteur propre à Huaxu — les voyageurs en redemandent toujours.",
          DialogueId = 51125613,
          GUID = "7FFCD3E2",
          NextOptions = {
            [1] = 51125614,
            [2] = 51125618
          },
          SpeakNpcId = 701040,
          Subtitle = "Oh, and don't miss our new scented candles: a breath of Huaxu in each — travellers from abroad always come back for more!"
        },
        [51125614] = {
          ContentFR = "<I>Ce n’est pas mon style. Auriez-vous quelque chose de plus pratique ?</>",
          DialogueId = 51125614,
          GUID = "7FFCD40C",
          NextDialogue = 51125615,
          Subtitle = "Not my thing. Anything more practical — something for day-to-day use?"
        },
        [51125615] = {
          ContentFR = "Ah, {性别:cher client|chère cliente}... je ne vends que des souvenirs. Leur vocation n’est pas l’utilité, mais le plaisir et la mémoire.",
          DialogueId = 51125615,
          GUID = "7FFCD436",
          NextDialogue = 51125616,
          SpeakNpcId = 701040,
          Subtitle = "Ah, dear guest, I'm but a peddler of souvenirs. Such things are for delight and remembrance, not for use."
        },
        [51125616] = {
          ContentFR = "Les étrangers viennent ici pour voyager ou commercer, et souhaitent emporter un souvenir pour ceux restés au pays. Les objets réellement utiles... ils auraient du mal à s’y habituer.",
          DialogueId = 51125616,
          GUID = "7FFCD460",
          NextDialogue = 51125617,
          SpeakNpcId = 701040,
          Subtitle = "Guests from abroad — travellers and traders alike — carry a token home for those left behind. As for things of real use... truth be told, our everyday wares seldom suit their habits."
        },
        [51125617] = {
          ContentFR = "Et puis, si un bien était véritablement indispensable, les Tisse-Étoiles l’auraient déjà diffusé dans tous les royaumes. Il ne serait pas exclusif à Huaxu.",
          DialogueId = 51125617,
          GUID = "7FFCD48A",
          NextOptions = {
            [1] = 51125622
          },
          SpeakNpcId = 701040,
          Subtitle = "And if something were truly needed, the Starweavers would've made it common long ago — sold everywhere. It wouldn't be a Huaxu exclusive."
        },
        [51125618] = {
          ContentFR = "<I>Je voudrais tout, mais je n’ai pas d’argent. Puis-je acheter à crédit ?</>",
          DialogueId = 51125618,
          GUID = "7FFCD4B4",
          NextDialogue = 51125619,
          Subtitle = "I want the lot, but I've no money — could I have them on tick?"
        },
        [51125619] = {
          ContentFR = "Ah... pardonnez-moi. Mon échoppe est modeste, je ne peux me le permettre. Mais si vous cherchez du travail, je peux vous orienter : les Tisse-Étoiles recrutent souvent des manutentionnaires au port.",
          DialogueId = 51125619,
          GUID = "7FFCD4DE",
          NextOptions = {
            [1] = 51125622
          },
          SpeakNpcId = 701040,
          Subtitle = "AAh... sorry, no can do for a small stall like mine. But if you're looking to earn a bit of coin, I can put in a word with the Starweavers down at the docks — they're always hiring porters."
        },
        [51125620] = {
          ContentFR = "<I>Vous n’arnaquez pas les étrangers sur les prix, au moins ?</>",
          DialogueId = 51125620,
          GUID = "7FFCD508",
          NextDialogue = 51125621,
          Subtitle = "You don't fleece tourists, do you?"
        },
        [51125621] = {
          ContentFR = "Quelle idée ! Cela fait presque dix ans que je tiens ce stand. Ma réputation est irréprochable, et je fais toujours de mon mieux pour offrir les meilleurs prix.",
          DialogueId = 51125621,
          GUID = "7FFCD532",
          NextOptions = {
            [1] = 51125609,
            [2] = 51125622
          },
          SpeakNpcId = 701040,
          Subtitle = "Wouldn't dream of it! I've been at this stall for nearly ten years — folk round here know I give a fair deal. Ask around if you like."
        },
        [51125622] = {
          ContentFR = "<I>Je n’ai plus de questions. Je m’en vais.</>",
          DialogueId = 51125622,
          GUID = "7FFCD55C",
          NextDialogue = 51125623,
          Subtitle = "That's all I needed to know. See you."
        },
        [51125623] = {
          ContentFR = "Bonne route ! Revenez quand vous voulez — vous trouverez forcément quelque chose à votre goût.",
          DialogueId = 51125623,
          GUID = "7FFCD586",
          SpeakNpcId = 701040,
          Subtitle = "Take care! Pop by again — sure to be something you'll fancy."
        },
        [51125701] = {
          ContentFR = "Vous l’ignorez peut-être, mais aujourd’hui, le Quai-aux-Étoiles n’est plus qu’un modeste port où transitent les marchandises des Tisse-Étoiles. Rien d’extraordinaire en apparence. Pourtant, il y a mille ans, un personnage illustre est parti d’ici.",
          DialogueId = 51125701,
          GUID = "7FFCE252",
          NextDialogue = 51125702,
          SpeakNpcId = 701041,
          Subtitle = "You lot might not know this, but this humble wharf of ours wasn't always so quiet. A thousand years ago, a great man once set sail from right here!"
        },
        [51125702] = {
          ContentFR = "Qui donc ? Vous avez tous déjà entendu son nom : l’un des fondateurs des Neuf Chapitres de Dafeng, l’ancêtre de la Secte Jishu... Ju !",
          DialogueId = 51125702,
          GUID = "7FFCE27C",
          NextOptions = {
            [1] = 51125703,
            [2] = 51125720
          },
          SpeakNpcId = 701041,
          Subtitle = "And who was that great man, you ask? You all know his name — Ju, co-founder of the Nine Chapters, and the forefather of the Jishu Sect!"
        },
        [51125703] = {
          ContentFR = "<I>Continuer à écouter</>",
          DialogueId = 51125703,
          GUID = "7FFCE2A6",
          NextDialogue = 51125704,
          Subtitle = "Listen on."
        },
        [51125704] = {
          ContentFR = "Voyageurs venus du sud comme du nord, accordez-moi un instant. Laissez-moi vous conter les mille ans d’histoire de notre Quai-aux-Étoiles. En affaires, on aime que tout soit clair et net... eh bien, il en va de même pour notre passé.",
          DialogueId = 51125704,
          GUID = "7FFCE2D0",
          NextDialogue = 51125705,
          SpeakNpcId = 701041,
          Subtitle = "Folks, lend me your ears for a moment — let me tell you the thousand-year tale of our very own Starwharf! Just as trade should be fair and square, so too should our past — plain and open for all to see."
        },
        [51125705] = {
          ContentFR = "À cette époque, Huaxu ne bénéficiait pas encore de la protection des Neuf Chapitres de Dafeng. Les Souillés erraient partout, attaquant les innocents. Pour survivre, qu’on soit vieux ou enfant, il fallait lutter sans cesse contre ces bêtes féroces.",
          DialogueId = 51125705,
          GUID = "7FFCE2FA",
          NextDialogue = 51125706,
          SpeakNpcId = 701041,
          Subtitle = "Before the Nine Chapters came to guard us, old Huaxu was a hard place to live. Back then, the Filthoids ran wild, feasting on the helpless. To stay alive, every man, woman, and child had to fight or flee — no exceptions."
        },
        [51125706] = {
          ContentFR = "Là où il y a lutte, il y a morts. La population de Huaxu était alors extrêmement réduite : bien peu d’enfants parvenaient à survivre dans ce chaos. Afin de trouver un moyen d’apporter la paix au territoire, les Descendants draconiques cherchèrent sans relâche une solution.",
          DialogueId = 51125706,
          GUID = "7FFCE324",
          NextDialogue = 51125707,
          SpeakNpcId = 701041,
          Subtitle = "And where there's strife, there are graves. People dwindled, babies rarely saw their first spring. Even the proud Loongscions were at their wits' end, searching high and low for a way to bring peace back to the land."
        },
        [51125707] = {
          ContentFR = "Ju, lui, parcourut toute Huaxu... sans jamais trouver de lieu véritablement paisible. Alors il se dit : puisque la paix n’est nulle part ici, pourquoi ne pas aller voir ailleurs ? Observer comment font les autres, apprendre de leurs forces, et revenir enrichi de ce savoir.",
          DialogueId = 51125707,
          GUID = "7FFCE34E",
          NextOptions = {
            [1] = 51125708
          },
          SpeakNpcId = 701041,
          Subtitle = "Among them was Ju. He roamed every corner of Huaxu, seeking peace and finding none. At last, he thought: If peace can't be found on our shores, maybe it lies beyond the sea — in what others know, in what we've yet to learn."
        },
        [51125708] = {
          ContentFR = "<I>Continuer à écouter</>",
          DialogueId = 51125708,
          GUID = "7FFCE378",
          NextDialogue = 51125709,
          Subtitle = "Listen on."
        },
        [51125709] = {
          ContentFR = "À l’époque, il n’existait ni navires aussi robustes qu’aujourd’hui, ni Tisse-Étoiles pour guider les traversées. Prendre la mer relevait du pur hasard. Avec de la chance, on échouait sur une île déserte à observer les oiseaux. Sans elle... on finissait au fond de l’océan, nourriture pour les poissons.",
          DialogueId = 51125709,
          GUID = "7FFCE3A2",
          NextDialogue = 51125710,
          SpeakNpcId = 701041,
          Subtitle = "Back in those days, there were no great ships — not a single Starweaver to be seen. To set sail was a pure gamble: with luck, you might wash ashore on some lonely isle, counting seabirds to pass the days; without it, you'd be fish food at the bottom of the sea."
        },
        [51125710] = {
          ContentFR = "Mais Ju, animé d’un ardent désir d’apporter la paix à tous, construisit lui-même un bateau. Refusant d’impliquer qui que ce soit, il prit la mer seul... depuis ce même Quai-aux-Étoiles.",
          DialogueId = 51125710,
          GUID = "7FFCE3CC",
          NextDialogue = 51125711,
          SpeakNpcId = 701041,
          Subtitle = "But Ju, bent on peace for all, built a boat with his own hands — asking help from no one — and pushed off alone from this very Starwharf!"
        },
        [51125711] = {
          ContentFR = "Par la grâce du Seigneur Dragon d’Argent, Ju survécut aux tempêtes et atteignit le mystérieux pays de la Tour. Hélas, là-bas non plus, la paix n’existait pas. Convaincu que les peuples étrangers ne pouvaient offrir l’espoir à Huaxu, Ju reprit la route du retour... accompagné d’autres âmes en quête de stabilité.",
          DialogueId = 51125711,
          GUID = "7FFCE3F6",
          NextDialogue = 51125712,
          SpeakNpcId = 701041,
          Subtitle = "By Lord Argent's grace, Ju braved every storm the sea could throw at him, till at last he reached a hidden land where a sacred tower rose into the clouds. But peace? Not a trace of it there, either. So he turned his prow homeward once more — and with him came others who, like him, longed for peace."
        },
        [51125712] = {
          ContentFR = "Les années passèrent. Tous pensaient Ju mort depuis longtemps. Et pourtant... il revint, bien vivant, ramenant avec lui de nombreux survivants jusqu’au Quai-aux-Étoiles.",
          DialogueId = 51125712,
          GUID = "7FFCE420",
          NextOptions = {
            [1] = 51125713
          },
          SpeakNpcId = 701041,
          Subtitle = "Seasons passed, years slipped away... and folks here thought Ju had long been claimed by the sea. Then one day — from the horizon he came sailing back, right into Starwharf's arms, a handful of weary souls at his side."
        },
        [51125713] = {
          ContentFR = "<I>Continuer à écouter</>",
          DialogueId = 51125713,
          GUID = "7FFCE44A",
          NextDialogue = 51125714,
          Subtitle = "Listen on."
        },
        [51125714] = {
          ContentFR = "Vous vous demandez sans doute comment Ju parvint à naviguer avec une telle précision. Était-ce la bénédiction des dieux ? Ou bien la foi et l’instinct ?",
          DialogueId = 51125714,
          GUID = "7FFCE474",
          NextDialogue = 51125715,
          SpeakNpcId = 701041,
          Subtitle = "You might be wondering — how did Ju find his way across that endless sea? Was it the gods who guided him? Or sheer guts and blind faith?"
        },
        [51125715] = {
          ContentFR = "Non, ni l’un ni l’autre ! Et je ne vais pas faire durer : l’outil qui guide aujourd’hui les Tisse-Étoiles en mer, on l’appelle bien le Panneau aux Mille Étoiles, n’est-ce pas ? Ju utilisait le même... sauf que le sien, c’était le tout premier.",
          DialogueId = 51125715,
          GUID = "7FFCE49E",
          NextDialogue = 51125716,
          SpeakNpcId = 701041,
          Subtitle = "Neither! All right, I won't keep you guessing — you know that Stellapass the Starweavers use to find their way at sea? Well, Ju's was the very first — built with his own hands."
        },
        [51125716] = {
          ContentFR = "À l’aide de simples planches de bois, il observa les étoiles, consigna les routes, et put ainsi parcourir l’océan librement, sans entraves.",
          DialogueId = 51125716,
          GUID = "7FFCE4C8",
          NextDialogue = 51125717,
          SpeakNpcId = 701041,
          Subtitle = "With plain old planks, he charted the stars, found his bearings, and sailed wherever his heart pleased."
        },
        [51125717] = {
          ContentFR = "Le voyage de Ju, son départ et son retour, libérèrent les Descendants draconiques de Huaxu de leur peur de la mer. La prospérité actuelle du Quai-aux-Étoiles et l’essor des Tisse-Étoiles, nous les devons à ce pas qu’il osa faire le premier.",
          DialogueId = 51125717,
          GUID = "7FFCE4F2",
          NextDialogue = 51125718,
          SpeakNpcId = 701041,
          Subtitle = "It was Ju's voyage — out into the unknown and back again — that freed the Loongscions of Huaxu from their fear of the sea. For Starwharf's prosperity and the Starweavers' success today, we owe our thanks to Ju — the first soul brave enough to face the waves."
        },
        [51125718] = {
          ContentFR = "Voilà pourquoi Ju et Yang sont à jamais nos sages fondateurs. Sans eux, Huaxu n’existerait pas telle que nous la connaissons aujourd’hui. N’oubliez jamais leurs noms, ni leurs actes. Compris ?",
          DialogueId = 51125718,
          GUID = "7FFCE51C",
          NextDialogue = 51125719,
          SpeakNpcId = 701041,
          Subtitle = "And remember this, folks — Ju and Yang, founders side by side, names we must never let fade. Without them, there'd be no Huaxu as we know it today. So keep their names close, keep their deeds alive — and pass them on!"
        },
        [51125719] = {
          ContentFR = "Une vague d’acclamations s’élève parmi la foule.",
          DialogueId = 51125719,
          GUID = "7FFCE546",
          Subtitle = "(The crowd bursts into cheers.)"
        },
        [51125720] = {
          ContentFR = "<I>Ne plus écouter</>",
          DialogueId = 51125720,
          GUID = "7FFCE570",
          NextDialogue = 51125721,
          Subtitle = "That's enough for now."
        },
        [51125721] = {
          ContentFR = "Dans votre dos, la voix du Vieux Liu continue de vanter les exploits des deux fondateurs de Huaxu, tandis que la foule applaudit en buvant son thé...",
          DialogueId = 51125721,
          GUID = "7FFCE59A",
          Subtitle = "(Behind you, Old Man Liu's voice carries on — still praising Huaxu's two founders as the onlookers clap along...)"
        },
        [51125801] = {
          ContentFR = "Le Panneau aux Mille Étoiles fonctionne normalement... À bien y réfléchir, l’échéance de la prochaine maintenance approche.",
          DialogueId = 51125801,
          GUID = "7FFCF2BA",
          NextDialogue = 51125802,
          SpeakNpcId = 701042,
          Subtitle = "The Stellapass is running fine. Come to think of it, it's about due for its next maintenance..."
        },
        [51125802] = {
          ContentFR = "Cela fait à peine trois ans qu’il a été installé à bord... Comment se fait-il qu’il faille déjà l’envoyer en maintenance ? J’espère qu’ils n’ont pas oublié de prendre rendez-vous avec la Secte Jishu... Voyons si les graduations ne sont pas trop usées.",
          DialogueId = 51125802,
          GUID = "7FFCF2E4",
          NextDialogue = 51125803,
          SpeakNpcId = 701042,
          Subtitle = "It's been less than three years since we installed this Stellapass. Why does it need maintenance already? I just hope they remembered to call in a craftsman from the Jishu Sect... Better check whether the calibration marks have faded."
        },
        [51125803] = {
          ContentFR = "Ah ! Vous m’avez fait peur. Vous n’êtes pas d’ici, hein ? Que faites-vous sur notre navire ?",
          DialogueId = 51125803,
          GUID = "7FFCF30E",
          NextOptions = {
            [1] = 51125804,
            [2] = 51125807
          },
          SpeakNpcId = 701042,
          Subtitle = "Whoa! You scared me! You're not from around here, are you? What are you doing on our ship?"
        },
        [51125804] = {
          ContentFR = "<I>Je suis </>{性别:<I>curieux</>|<I>curieuse</>} <I>de savoir ce que vous faites.</>",
          DialogueId = 51125804,
          GUID = "7FFCF338",
          ImprPlusId = 1208,
          NextDialogue = 51125805,
          Subtitle = "Just curious what you're doing."
        },
        [51125805] = {
          ContentFR = "Moi ? Je vérifie l’état du Panneau aux Mille Étoiles. Je suis l’artisan affecté à ce navire, chargé de son entretien quotidien. Sans lui, le bateau serait incapable de prendre la mer.",
          DialogueId = 51125805,
          GUID = "7FFCF362",
          NextDialogue = 51125806,
          SpeakNpcId = 701042,
          Subtitle = "Me? I'm just checking the ship's Stellapass. I'm the mechanic in charge of its maintenance. Without it, the ship wouldn't be able to leave port."
        },
        [51125806] = {
          ContentFR = "Si vous avez besoin de quelque chose, revenez plus tard. Je dois encore contrôler les risques de surchauffe...",
          DialogueId = 51125806,
          GUID = "7FFCF38C",
          SpeakNpcId = 701042,
          Subtitle = "If you need anything, come back later — I still need to check for overheating."
        }
      }
    end
