          NextDialogue = 51125820,
          SpeakNpcId = 701042,
          Subtitle = "Maintenance? It just means having the Jishu Sect masters inspect it, to see if any parts have come loose. Usually it's fine — but out at sea, with all the pitching and rolling, a few bumps are hard to avoid."
        },
        [51125820] = {
          ContentFR = "Nous, simples artisans, pouvons détecter les anomalies, mais pas les réparer. Seuls les maîtres de la Secte disposent des instruments nécessaires. Une vérification tous les quatre ou cinq ans suffit amplement.",
          DialogueId = 51125820,
