        [51125822] = {
          ContentFR = "<I>Où se trouve le Panneau aux Mille Étoiles ? Je ne le vois pas.</>",
          DialogueId = 51125822,
          GUID = "7FFCF62C",
          NextDialogue = 51125823,
          Subtitle = "Where's the Stellapass? I don't see it."
        },
        [51125823] = {
          ContentFR = "Ha ha ! Juste sous vos pieds, voyons. Sur les grands navires de haute mer, le Panneau est installé dans la cale. Seule la plaque principale est inversée vers le ciel pour observer les étoiles.",
          DialogueId = 51125823,
          GUID = "7FFCF656",
          NextDialogue = 51125824,
          SpeakNpcId = 701042,
          Subtitle = "Ha! It's right beneath our feet, silly. On ships like this, the Stellapass is built into the hold — only the main plate is turned upward to face the sky, so it can read the stars."
