        [51125824] = {
          ContentFR = "Pour que vous compreniez avec vos références étrangères... disons que cela ressemble à un immense lustre. En mer, quelqu’un doit surveiller en permanence ses mouvements, sous peine de dévier de la trajectoire.",
          DialogueId = 51125824,
          GUID = "7FFCF680",
          SpeakNpcId = 701042,
          Subtitle = "If I had to put it in your terms, it's a bit like a massive chandelier. Out at sea, there's always someone below keeping watch on how it turns — otherwise, we'd drift off course."
        },
        [51125825] = {
          ContentFR = "<I>Je n’ai plus de questions.</>",
          DialogueId = 51125825,
          GUID = "7FFCF6AA",
          NextDialogue = 51125826,
          Subtitle = "That's all I wanted to ask."
