          DialogueId = 51125903,
          GUID = "7FFD0376",
          NextDialogue = 51125904,
          SpeakNpcId = 701043,
          Subtitle = "Right... so, no shooting anyone. I can manage that."
        },
        [51125904] = {
          ContentFR = "... Disons que vous pouvez le comprendre ainsi. En résumé, à Huaxu, toute forme de violence est proscrite. C’est pourquoi les armes que vous avez apportées seront mises sous scellés et vous seront rendues à votre départ.",
