          GUID = "7FFD03A0",
          NextDialogue = 51125905,
          SpeakNpcId = 701044,
          Subtitle = "Good. Since you are in Huaxu, we shall keep the firearms you brought for safekeeping, and return them once you depart."
        },
        [51125905] = {
