          NextDialogue = 51125912,
          SpeakNpcId = 701044,
          Subtitle = "And should either side break their oath... Bi'an will come for them."
        },
        [51125912] = {
          ContentFR = "Les Bi’an ? Les gros chiens de Huaxu ? Je connais !",
          DialogueId = 51125912,
          GUID = "7FFD04F0",
          NextDialogue = 51125913,
          SpeakNpcId = 701043,
          Subtitle = "Bi'an? The great hound of Huaxu — I've heard of it!"
        },
        [51125913] = {
          ContentFR = "Quelle impolitesse ! Ne vous permettez pas d’appeler les Bi’an ainsi !",
          DialogueId = 51125913,
          GUID = "7FFD051A",
          SpeakNpcId = 701044,
          Subtitle = "Mind your tongue! Speak not of Bi'an so lightly!"
        },
        [51126001] = {
          ContentFR = "Maman me ment, c’est sûr. Elle disait que quand je serais grand, j’en aurais. L’an dernier elle disait « l’an prochain », et avant encore « l’an prochain »... et toujours rien...",
          DialogueId = 51126001,
          GUID = "7FFD138A",
          NextDialogue = 51126002,
          SpeakNpcId = 701045,
          Subtitle = "Mum keeps saying I'll get horns when I'm older. Year before last she said \"next year\", and last year she said \"next year\" again... still nothing!"
        },
        [51126002] = {
          ContentFR = "Et si elles ne poussent pas ? Non... je ne veux pas être un Enfant de la Terre. Je veux devenir un glorieux Descendant draconique !",
