        },
        [51126003] = {
          ContentFR = "<I>Être un Enfant de la Terre, c’est si mal que ça ?</>",
          DialogueId = 51126003,
          GUID = "7FFD13DE",
          ImprPlusId = 1207,
          NextDialogue = 51126004,
          Subtitle = "What's wrong with being an Earthborn?"
