        [51127605] = {
          ContentFR = "<I>Tu répares un bateau ?</>",
          DialogueId = 51127605,
          GUID = "7FFE1AB2",
          NextDialogue = 51127606,
          Subtitle = "You're fixing this boat?"
        },
        [51127606] = {
          ContentFR = "Ouais. Maître Qiu m’a engagé pour remettre en état cette vieille carcasse. L’argent qu’il a sur lui suffirait à en construire trois cents comme ça... et pourtant, il s’obstine à garder celle-ci.",
