          GUID = "7FFE1ADC",
          NextDialogue = 51127607,
          SpeakNpcId = 701067,
          Subtitle = "Aye. Mr Qiu brought me in to patch this old tub up a bit. Man like him could build a few hundred new ones, yet he clings to this battered heap — funny thing, that."
        },
        [51127607] = {
          ContentFR = "Bon, je vais devoir scier cette partie pourrie. Recule un peu, ça fait du bruit. Je voudrais pas t’abîmer les oreilles.",
          DialogueId = 51127607,
          GUID = "7FFE1B06",
          SpeakNpcId = 701067,
