        },
        [51127611] = {
          ContentFR = "<I>Qu’a-t-il de spécial, ce bateau ?</>",
          DialogueId = 51127611,
          GUID = "7FFE1BAE",
          NextDialogue = 51127612,
          Subtitle = "What's so special about this boat?"
        },
        [51127612] = {
          ContentFR = "Son âge. C’est ça, sa valeur. Parmi les antiquités de Maître Qiu, ce n’est peut-être pas la plus ancienne... mais c’est sûrement la plus grande.",
          DialogueId = 51127612,
          GUID = "7FFE1BD8",
          NextDialogue = 51127613,
          SpeakNpcId = 701067,
          Subtitle = "Her age — that's what makes her special. Among all Mr Qiu's antiques, she may not be the oldest, but she's surely the biggest."
        },
        [51127613] = {
          ContentFR = "On raconte qu’il était déjà là avant même la fondation du Marché Voilé. Il aurait dérivé jusqu’ici, échoué sur la rive. Puis, avec le temps, les gens se sont installés, et on l’a réutilisé.",
          DialogueId = 51127613,
          GUID = "7FFE1C02",
          NextDialogue = 51127614,
          SpeakNpcId = 701067,
          Subtitle = "Funny thing about her, though — she's got history. Word is, this boat drifted in long before Haze Market even existed. She ran aground by the shore, and folk settled nearby, hauled her ashore, and put her to use again."
        },
        [51127614] = {
          ContentFR = "Il semble avoir appartenu aux Tisse-Étoiles. Ils avaient l’habitude d’installer un immense Panneau aux Mille Étoiles sur le pont. Celui-ci a été retiré, par quelqu’un.",
          DialogueId = 51127614,
          GUID = "7FFE1C2C",
          NextDialogue = 51127615,
          SpeakNpcId = 701067,
          Subtitle = "Seems she once belonged to the Starweavers. They used to mount a great Stellapass over the hold — but this one's been stripped off, looks like."
