        [51127620] = {
          ContentFR = "<I>Quel âge a ce bateau ?</>",
          DialogueId = 51127620,
          GUID = "7FFE1D28",
          NextDialogue = 51127621,
          Subtitle = "How old would you say this ship is?"
        },
        [51127621] = {
          ContentFR = "Je ne me suis jamais penché dessus de très près, mais à en juger par l’état du bois, elle doit bien avoir une centaine d’années... au bas mot. Après, ce genre de chose, ça reste difficile à affirmer.",
          DialogueId = 51127621,
          GUID = "7FFE1D52",
          NextDialogue = 51127622,
          SpeakNpcId = 701067,
          Subtitle = "Never studied her up close, but by the timber, I'd say she's a hundred years old — give or take. Hard to be sure."
        },
        [51127622] = {
          ContentFR = "Avant Maître Qiu, il y a sûrement eu d’autres amateurs d’antiquités qui l’ont restauré de fond en comble.",
          DialogueId = 51127622,
          GUID = "7FFE1D7C",
          NextDialogue = 51127623,
          SpeakNpcId = 701067,
          Subtitle = "Maybe before Mr Qiu got her, some eccentric with a soft spot for antiques refitted her inside and out. Wouldn't surprise me."
