        [51127624] = {
          ContentFR = "D’où vient-il ?",
          DialogueId = 51127624,
          GUID = "7FFE1DD0",
          NextDialogue = 51127625,
          Subtitle = "Where did this ship come from?"
        },
        [51127625] = {
          ContentFR = "Difficile à dire. Si on écarte les histoires de fantômes... ou celles, tout aussi invraisemblables, d’arrangements secrets entre le Bureau de la Fortune Céleste et le Marché Voilé... deux versions tiennent la route.",
          DialogueId = 51127625,
          GUID = "7FFE1DFA",
          NextDialogue = 51127626,
          SpeakNpcId = 701067,
          Subtitle = "Hmm... can't say for sure. Put aside all that mythical nonsense — or those wild tales about the Ministry of Fortune scheming with Haze Market — there are two stories folk reckon might hold water."
        },
        [51127626] = {
          ContentFR = "La première dit que, lors du chaos causé par le Dragon Noir, le Seigneur Dragon d’Argent l’a écrasé. À ce moment-là, un navire de Tisse-Étoiles, de retour au port, se trouvait dans les parages — et n’a pas résisté à la colère divine.",
          DialogueId = 51127626,
          GUID = "7FFE1E24",
          NextDialogue = 51127627,
          SpeakNpcId = 701067,
          Subtitle = "First one goes back a hundred years. When the Dark Loong ran wild, Lord Argent struck it down. A Starweaver ship happened to be nearby, homeward bound, and couldn't withstand his fury."
        },
        [51127627] = {
          ContentFR = "Une vague colossale l’a retournée. Tout l’équipage est mort. Le navire a dérivé jusqu’à s’échouer ici.",
          DialogueId = 51127627,
          GUID = "7FFE1E4E",
          NextDialogue = 51127628,
          SpeakNpcId = 701067,
          Subtitle = "A great surge overturned the ship, killed everyone aboard, and she drifted on the currents till she ran aground here."
        },
        [51127628] = {
          ContentFR = "L’autre version... tu sais que les gens d’ici ne sont pas tendres, hein ?",
          DialogueId = 51127628,
          GUID = "7FFE1E78",
          NextDialogue = 51127629,
          SpeakNpcId = 701067,
          Subtitle = "The other tale is... (lowers his voice) you know the folk round here aren't ones to mess with, right?"
        },
        [51127629] = {
          ContentFR = "On dit qu’un homme d’une cruauté extrême se serait infiltré parmi les Tisse-Étoiles... et aurait massacré tout l’équipage, maquillant le tout en naufrage.",
          DialogueId = 51127629,
          GUID = "7FFE1EA2",
          NextDialogue = 51127630,
          SpeakNpcId = 701067,
          Subtitle = "(whispering) They say some cruel, cunning soul wormed his way into the Starweavers' crew — killed the lot, then staged the wreck himself."
        },
        [51127630] = {
          ContentFR = "Bah... des histoires pour passer le temps. En réalité, ce n’est sans doute que la collection d’un ancien.",
          DialogueId = 51127630,
          GUID = "7FFE1ECC",
          NextDialogue = 51127633,
          SpeakNpcId = 701067,
          Subtitle = "(regular voice) Ah, just stories to pass the time. Truth's probably duller — someone's old collection, nothing more."
        },
        [51127631] = {
