          DialogueId = 51127631,
          GUID = "7FFE1EF6",
          NextDialogue = 51127632,
          Subtitle = "That's all I needed to know."
        },
        [51127632] = {
          ContentFR = "Tu t’en vas, {性别:gamin|gamine} ? Reviens me voir à l’occasion. À mon âge, on aime bien discuter avec les jeunes.",
          DialogueId = 51127632,
          GUID = "7FFE1F20",
          SpeakNpcId = 701067,
          Subtitle = "Heading off, kiddo? Drop by again sometime — old folks like me don't mind a bit of chatter with you fresh-faced kids."
