          DialogueId = 60149014,
          Duration = 4.8,
          GUID = "9693A59C",
          SpeakNpcId = 920001,
          Subtitle = "Hmph, this Lulu Lunoloot is not someone you can mess with!",
          VoiceName = "voice/$Locale$/char/Dajiebai/vo_Run_r03"
        },
        [60149015] = {
