        [70010100] = {
          Camera = "6426.663086,7746.713379,-121.966454,0.253341,0.343415,-129.197754,35.0,350.0,false,Manual,2.8",
          Content = "TalkMechanism测试",
          DialogueId = 70010100,
          GUID = "AF435008",
          SpeakNpcId = 10201
        },
        [70010101] = {
          Camera = "240.799805,-19.96875,71.943665,0.000028,-8.199457,146.99736,18.0,100000,false,Manual,2.8",
          ContentFR = "Ces derniers jours, les Souillés se montrent de plus en plus agitées sur l’île. Les habitants préparent bateaux et provisions, prêts à prendre la mer au moindre danger.",
          DialogueId = 70010101,
          Duration = 5,
          GUID = "AF435032",
          SpeakNpcId = 102011,
          Subtitle = "Recently, the Filthoids on the island have become increasingly active. All residents are preparing boats and supplies, ready to set sail and escape at any time."
        },
        [70010201] = {
          Camera = "299.416992,-190.118652,-59.832947,0.000008,10.199979,140.800186,20.0,100000.0,false,Manual,2.8",
          ContentFR = "« Résidents, souvenez-vous : pour éviter d’être repérés par les autorités hyperboréennes, éloignez-vous des navires inconnus lorsque vous partez pêcher.\nNos ancêtres ont fui jusqu’ici pour échapper à des guerres inutiles — suivons leur sagesse et respectons cet avertissement. »",
          DialogueId = 70010201,
          Duration = 5,
          GUID = "AF43609A",
          SpeakNpcId = 102012,
          Subtitle = [[
Residents, remember to stay away from unidentified ships when fishing at sea to avoid being detected by the Hyperborean authorities. 
 Our ancestors fled here to avoid getting involved in meaningless wars. We must adhere to their ways.]]
        },
        [70010301] = {
          Camera = "-364.107666,1506.973633,120.13916,0.000131,13.391685,87.755157,18.0,100000.0,false,Manual,18.0",
          ContentFR = "Les villageois ont sans doute déjà fui le village ravagé par les Souillés. Au loin, l’Arbre Céleste sert de phare naturel pour ceux qui ont pris la mer.",
          DialogueId = 70010301,
          Duration = 5,
          GUID = "AF437102",
          SpeakNpcId = 102013,
          Subtitle = "The villagers must've fled the Filthoid-ravaged village by now. The distant \"Heaventree\" serves as their natural lighthouse when out at sea."
        },
        [70010401] = {
          Camera = "-564.918457,-24.525635,71.417542,0.000015,34.991844,0.800468,18.0,1932.963745,false,Manual,2.8",
          ContentFR = "Une statue inconnue, dédiée à une divinité sans nom... Sans doute une relique d’un autre âge...",
          DialogueId = 70010401,
          Duration = 5,
          GUID = "AF43816A",
          SpeakNpcId = 102014,
          Subtitle = "A never-before-seen statue, dedicated to an unnamed deity. It's an artefact from an unknown era..."
        },
        [70010501] = {
          Camera = "-33.021576,347.337158,98.72699,0.000062,6.798647,-91.995422,18.0,100000.0,false,Manual,2.8",
          ContentFR = "Une inscription gravée à la lame — seuls quelques fragments sont encore lisibles :\n...\nGalas de Gralenia accompagna le général Brendan lors de son expédition en ces terres, chassant tous les fidèles aveugles du faux culte Élyséen.\n...\nEffacez toute trace de la fausse divinité.\n...\nJ’aimerais rester ici, mais l’île est stérile. Je doute de pouvoir m’y établir durablement.\n...",
          DialogueId = 70010501,
          Duration = 5,
          GUID = "AF4391D2",
          SpeakNpcId = 102015,
          Subtitle = [[
Some inscriptions have been carved into it with a blade. Only some of the content is discernible: 
 ...
Gralenia's Galas accompanied General Brendan's expeditionary forces here, expelling all the blind followers of the false goddess, Elysia. 
 ...
Do everything you can to erase all traces of the false god. 
 ...
Although I wish to remain here, the island is barren, so I don't think I can stay here permanently. 
 ...]]
        },
        [70010601] = {
          Camera = "-1111.150024,-564.398438,447.803864,0.000071,30.199543,17.596375,15.0,100000.0,false,Manual,2.8",
          ContentFR = "À en juger par l’immense statue et les ruines bordant les falaises, il s’agissait autrefois d’un temple.",
          DialogueId = 70010601,
          Duration = 5,
          GUID = "AF43A23A",
          SpeakNpcId = 102016,
          Subtitle = "Judging from the huge statue and the ruined buildings at the edge of the cliff, it appears that this place was once a temple a long time ago."
        },
        [70010701] = {
          Camera = "507.757812,-5157.005371,-457.544922,0.000083,-13.799645,-41.00135,20.0,511.06842,false,Manual,2.8",
          ContentFR = "Des restes de Souillé, encore tièdes... Une bataille a eu lieu ici il y a peu.",
          DialogueId = 70010701,
          Duration = 5,
          GUID = "AF43B2A2",
          SpeakNpcId = 102017,
          Subtitle = "The remains of a Filthoid. Its lingering warmth proves that there was a fierce battle here not long ago."
        },
        [70010801] = {
          Camera = "454.451172,-463.453125,534.632812,0.000046,-15.999574,138.796616,15.0,100000.0,false,Manual,8.0",
          ContentFR = "Une statue peinte, bien conservée, mais entourée de murs en ruine — preuve qu’un pillage important eut lieu il y a fort longtemps.",
          DialogueId = 70010801,
          Duration = 5,
          GUID = "AF43C30A",
          SpeakNpcId = 102018,
          Subtitle = "The painted statue, though well-preserved, is surrounded by ruins, indicating that this place was looted a long time ago."
        },
        [70010901] = {
          Camera = "-742.34668,128.554199,307.391235,0.000063,-10.999725,71.996475,15.0,100000.0,false,Manual,2.8",
          ContentFR = "Un dispositif alchimique, dont la présence dans ces ruines reste inexpliquée.",
          DialogueId = 70010901,
          Duration = 5,
          GUID = "AF43D372",
          SpeakNpcId = 102019,
          Subtitle = "It appears to be an alchemical device, but it's unclear why it's in these temple ruins."
        },
        [70011001] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.8",
          ContentFR = "Une photo prise il y a plus de dix ans. Le verre du cadre est couvert de traces de doigts.\nOn y voit une jeune Charon souriante, les cheveux caressés par le vent.\nAu dos, une inscription à l’encre :\n« Ma fille — Hayley. Prise à Rougerive. »\nElle ne ressemble pas vraiment à Psyche, et pourtant... son sourire limpide évoque irrésistiblement son souvenir.",
          DialogueId = 70011001,
          Duration = 5,
          GUID = "AF43E3DA",
          SpeakNpcId = 102020,
          Subtitle = "An old photograph, taken more than a decade ago. The glass is clouded with fingerprints. In the picture, a Charon girl smiles softly as the breeze toys with her hair.\n\nOn the back, written in fountain pen:\n\"My daughter — Hayley. Taken in Scarletriver.\"\n\nShe doesn't much resemble Psyche... and yet, something in that innocent smile calls her to mind all the same."
        },
        [70011101] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          ContentFR = "(De hautes armoires de dossiers se dressent, classées avec un soin impeccable selon l’ordre alphabétique. Chaque fiche contient la photo d’un enfant, et le récit minutieux de chacune de leurs journées passées à la Maison d’Hypnos.)\n\nNom : Psyche Frey\nÂge : 17 ans\nSymptômes : cécité intermittente\n\n...\nLorsque Psyche est arrivée, sa Dégradation en était déjà à un stade avancé. Pourtant, elle saluait chacun avec cette chaleur qui lui est propre.\nComme j’aimerais croire que le diagnostic était erroné — qu’elle n’était pas atteinte, et que sa vie pouvait encore suivre son cours.\n...\nElle garde toujours, sur sa table de chevet, les fleurs offertes par ses parents, réduisant à peine l’espace qu’il lui reste pour dormir ou poser les pieds.\n...\nJ’ai libéré une chambre plus lumineuse à l’étage. Psyche et ses fleurs y seront sans doute plus à l’aise.\n...\nElle aime vraiment les fleurs. Chaque jour, elle en prend soin avec minutie avant d’en offrir aux autres enfants.\nSans la Dégradation, elle aurait sans doute su entretenir les Fleurs de sollicitude encore mieux que ses parents.\n...\nAujourd’hui, Psyche m’a offert une fleur, elle aussi. En voyant son sourire paisible, j’ai cru entrevoir ton visage... Hayley...\n...\nElle m’a surpris, l’air soucieux, penché sur le registre des comptes. Elle n’a pas cessé d’insister jusqu’à ce que je lui révèle les difficultés financières de la Maison d’Hypnos.\n(Note : Je dois répondre rapidement à l’acheteur. Il ne faut pas que les enfants s’inquiètent davantage.)\n...\nPsyche a nettoyé l’ancien manoir et l’a même loué à {性别:un petit vaurien venu|une petite vaurienne venue} de nulle part... Espérons que {性别:ce gamin|cette gamine} ne causera pas d’ennuis à la Maison d’Hypnos.\n...\n<H>Elle m’a dit vouloir vivre, même un seul jour de plus, tant qu’elle pouvait rester humaine.\nÀ ces mots, j’ai ressenti à la fois du soulagement et de la colère.</>\n<H>Du soulagement, car elle s’est enfin confiée après avoir fait semblant d’être forte si longtemps.</>\n<H>De la colère, à cause de {性别:ce petit vaurien|cette petite vaurienne} !\nJe ne sais pas ce {性别:qu’il|qu’elle} lui a dit, mais donner l’espoir de vivre à une âme condamnée... c’est d’une cruauté sans nom.</>\n<H>Si l’on ne peut sauver quelqu’un, alors mieux vaut ne pas lui offrir une illusion de salut.</>\n<H>(Note : Mais si tel est le vœu de Psyche... alors je dois accélérer mes recherches sur l’opération de suppression de la Dégradation. Pour elle. Pour les enfants.)</>",
          DialogueId = 70011101,
          Duration = 5,
          GUID = "AF43F442",
          SpeakNpcId = 102021,
          Subtitle = "(Tall file cabinets, neatly arranged in alphabetical order, hold the files of the \"lodgers.\" Each file, besides a photo of the child, clearly documents every day the children spent at the Hypnos' House.)\n\nPsyche's Profile\nAge: 17\nSymptoms: Blindness, Deafness\n\nWhen Psyche arrived, her Deterioration had already progressed to the mid-stage. Yet, she greeted everyone with such warmth. I wish I could believe the diagnosis was wrong — that she wasn't suffering from Deterioration, and that her life could somehow get back on track.\n...\nShe keeps the flowers her parents brought her by her bedside, even though it leaves her barely any space to sleep or even stand.\n...\nI cleared out a better-lit room on the second floor. Hopefully, Psyche and her flowers will be more comfortable there.\n...\nShe really loves flowers. Every day, she tends to them with care and shares them with the other children. If it weren't for the shadow of Deterioration, she would have taken care of Flower of Solicitude even better than her parents ever did.\n...\nToday, Psyche gave me a flower too. Her peaceful smile reminded me of you, Hayley...\n...\nPsyche saw me frowning over the finances today and wouldn't stop pestering me until I told her about Hypnos' House's financial struggles.\n(Note: Must reply to the buyer soon. Can't let the children keep worrying about this.)\n...\nPsyche cleaned out the old house and even rented it to some kid with a shady background... I just hope that kid doesn't stir up trouble for Hypnos' House.\n...\nShe told me she wished to live longer as a human — even if just for one more day. I was both relieved and furious to hear that.\nI felt relieved because Psyche finally opened up. She's been putting on a brave face and acting like she doesn't care about life or death for far too long.\nI felt furious because of that blasted kid! I don't know what that little rascal said to her, but giving false hope to someone who's destined to leave the world soon — that's the cruellest thing one could do.\n...\n(Note: But if that's what Psyche wants... I must speed up the research on the anti-Deterioration drug... For Psyche, and for other kids.)"
        },
        [70011201] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          ContentFR = "Nom : Ike\nÂge : 19 ans\nSymptôme : cécité\n\n...\nIke est arrivé seul à la Maison d’Hypnos.\nJe ne sais pas si ses parents n’ont pas eu la force d’affronter son destin... ou s’ils ont simplement fermé les yeux. Laisser un enfant aveugle voyager jusqu’à Givrelac, seul... C’est une pensée qui me serre encore le cœur.\n...\nIl m’a dit vouloir lire. Hélas, je n’avais ici que d’interminables traités médicaux sans le moindre attrait. Pourtant, il n’a rien dit. Alors j’ai lu à voix haute, et il est resté là, calmement assis à m’écouter. Ainsi s’est déroulée notre journée.\n...\nCette nuit, j’ai entendu Ike murmurer le nom de son père dans son sommeil.\n...\nJ’ai fini par retrouver son père, dans la province de Flagson. Il ne m’a pas remarqué : il berçait un nourrisson Sola en fredonnant une berceuse, absorbé par une douceur inattendue.\n...\nJ’ai acheté quelques ouvrages en braille. Ike les a effleurés du bout des doigts et a murmuré : « Merci, père. » J’ai voulu lui dire que je n’étais pas...\nMais au final, je n’ai pu laisser échapper qu’un « mmh... » étouffé avant de quitter la chambre en hâte.\n...",
          DialogueId = 70011201,
          Duration = 5,
          GUID = "AF4404AA",
          SpeakNpcId = 102022,
          Subtitle = [[
Ike's Profile
Age: 19
Symptom: Blindness

Ike came to the Hypnos' House alone. It's unclear whether his parents couldn't bear to see his fate or were simply heartless. They just let a blind kid come to Icelake by himself.
...
He said he wanted to read books, but all I had were dull, lengthy medical books. Even so, he didn't mind. So I read while he sat there listening, and that's how we spent the day.
...
I heard Ike calling for his father in his dreams.
...
I found Ike's father in the Flagson Province, but he didn't notice me. He was just focused on humming a lullaby to the sola baby in his arms.
...
I bought some books written in Braille. Ike was so happy. "Thank you, Father", he said. I wanted to tell him I wasn't his father, but in the end, I could only manage a strained "Mm" and hurried out of the ward.
...]]
        },
        [70011301] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          ContentFR = "Nom : Robie\nÂge : 18 ans\nSymptôme : ostéogenèse imparfaite\n\n...\nLorsque Robie est arrivé, son corps n’était plus qu’un assemblage fragile, entièrement enveloppé de bandages. Le moindre heurt pouvait briser ses os — parfois même simplement se lever.\n...\nJe lui ai installé un lit près de la fenêtre, pour qu’il puisse profiter de la lumière.\nIl souriait, comme si ce simple rayon de soleil suffisait à le réchauffer.\n...\nLa rééducation a porté ses fruits, et les repas de Madame Lina l’ont aidé à reprendre des forces. Désormais, Robie peut parcourir la Maison d’Hypnos, appuyé sur une canne.\n...\nAujourd’hui, sa jambe s’est fracturée à nouveau — plus gravement encore que lors de son arrivée. Il est tombé dans l’escalier sans même appeler à l’aide, de peur de m’inquiéter...\nJe dois avoir l’air bien épuisé pour que les enfants en viennent à protéger mes sentiments au lieu des leurs.\n...\nIl voulait cueillir une fleur pour remercier Psyche. Je l’ai accompagné.\nNous n’avons trouvé que quelques brindilles desséchées... mais cela lui suffisait.\nIl riait comme s’il tenait un trésor.\n...",
          DialogueId = 70011301,
          Duration = 5,
          GUID = "AF441512",
          SpeakNpcId = 102023,
          Subtitle = [[
Robie's Profile
Age: 18
Symptom: Osteogenesis Imperfecta

When Robie was sent to the Hypnos' House, he was wrapped in bandages from head to toe. Even the slightest bump could cause a severe fracture, and even getting out of bed was a struggle for him.
...
I moved his bed to the window so he could get more sunlight.
...
The rehabilitation training was a success. Lady Lina's cooking provided Robie with enough nutrition, and now he can walk around the Hypnos' House with a cane.
...
Today, Robie's leg fractured again, even more severely than when he arrived. He fell down the stairs but didn't want to cause me any trouble, so he didn't even cry out... Looks like I've been too haggard recently, making the kids start worrying about me.
...
He wanted to go out and pick a flower as a return gift for Psyche, and I agreed. Although we only found a few dry branches in the end, he still smiled happily.
...]]
        },
        [70011401] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          ContentFR = "Nom : Josephine\nÂge : 17 ans\nSymptômes : déformation des organes, détresse respiratoire\n\n...\nSa Marque de Dégradation est apparu sur son cou. La voir courir partout avec tant d’énergie me donnait un mauvais pressentiment, que je n’osais formuler.\n...\nElle s’est soudain effondrée, haletante.\nLes examens ont été catégoriques : ses organes sont gravement déformés.\nElle devra rester dans la salle d’opération plusieurs jours.\n...\nSon état est un peu plus stable, mais elle ne peut toujours pas se passer du respirateur. Chaque nuit, je reste à son chevet, maintenant l’appareil en place, épongeant la sueur qui perle sur son front.\nHeureusement, les réserves de café suffisent encore... je tiendrai le temps qu’il faudra.\n...",
          DialogueId = 70011401,
          Duration = 5,
          GUID = "AF44257A",
          SpeakNpcId = 102024,
          Subtitle = [[
Josephine's Profile
Age: 17
Symptoms: Organ Deformation, Difficult Breathing

Her Deterioration mark appeared on her neck. Seeing her running around so energetically, I actually got a bad feeling.
...
She suddenly collapsed, gasping for breath. The results of her full-body check-up were not good at all, saying her organs were severely deformed. She had to stay in the operating room for the next few days.
...
Her condition improves a bit, but she still can't do without the respirator. To make sure nothing happened to her while she's sleeping, I have to stay by her bedside every night to hold the respirator steady and wipe away her cold sweat. Fortunately, there is still enough coffee to keep me going.
...]]
        },
        [70011501] = {
          Camera = "589.100586,92.850586,87.400391,0.000028,0.0,-178.390396,22.0,400.0,false,DoNotOverride,2.8",
          ContentFR = "En raison de conditions météorologiques extrêmes, un grave accident de renversement s’est produit sur la route principale, à l’extérieur de la cité.\nLes Veilleurs de la VIᵉ Légion sont déjà sur place pour réparer d’urgence les infrastructures endommagées.\nLes résidents sont invités à limiter leurs déplacements et à prendre toutes les mesures nécessaires pour éviter les glissades lors de leurs trajets.",
          DialogueId = 70011501,
          Duration = 5,
          GUID = "AF4435E2",
          SpeakNpcId = 102025,
          Subtitle = "Due to adverse weather conditions, a major rollover accident has occurred on the primary highway outside the city. The 6th Legion's Escort is currently undertaking emergency repair work. Residents are advised to minimise travel and take necessary anti-slip measures when venturing out."
        },
        [70011601] = {
          Camera = "-83.132812,-721.489746,92.419189,0.000006,-0.600217,80.994888,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "La porte bloquée coupe désormais tout accès à la mine. À vos oreilles résonne une voix mécanique, glaciale, répétant par bribes l’annonce diffusée lorsque le puits fut scellé...\n« Les veines de Phoxène sont épuisées... À compter de ce jour, le site est déclaré zone abandonnée... Les Éolipyliens n’assureront plus aucune garantie de sécurité... Tout incident survenant lors d’une intrusion non autorisée ne saurait engager notre responsabilité... »",
          DialogueId = 70011601,
          Duration = 5,
          GUID = "AF44464A",
          SpeakNpcId = 102026,
          Subtitle = [[
The jammed gate has severed access to the pit. A cold, mechanical voice intermittently repeats the notice issued when the pit was closed. 

The Phoxene veins have been depleted... Effective immediately, the pit is designated as abandoned...
The Legion will no longer ensure security in this area... 
Individuals assume all responsibility for any incidents resulting from unauthorised entry...]]
        },
        [70011701] = {
          ContentFR = "Une voix mécanique, froide et inflexible, répète sans relâche les instructions de relocalisation édictées par la Légion.\n\n« Les troupes stationnées de la VIᵉ Légion escorteront les mineurs inscrits sur la liste vers la province de Flagson, où ils poursuivront leur labeur. Le convoi ferroviaire partira exactement trois heures avant la fermeture officielle de la Fosse de Glevum.\nLes mineurs concernés sont priés de respecter les consignes suivantes :\n1) Tout bien personnel dépassant cinq kilogrammes : exécution immédiate.\n2) Absence lors de l’embarquement à l’heure fixée : exécution immédiate.\n3) Toute contestation relative à la liste nominative : exécution immédiate. »",
          DialogueId = 70011701,
          Duration = 5,
          GUID = "AF4456B2",
          SpeakNpcId = 102027,
          Subtitle = [[
A cold, mechanical voice relentlessly repeats the Legion's relocation instructions for miners. 

The 6th Legion's Garrison will escort miners on the list for relocation to the Flagson Province for continued labour. The transfer train will depart precisely three hours before the closure of Glevum Pit. Miners on the list must observe the following: 
1. Those carrying over five kilograms of personal belongings will face execution.
2. Those failing to board at the designated time will face execution.
3. Those questioning the list will face execution.]]
        },
        [70011801] = {
          Camera = "-415.066528,-79.582031,152.246094,0.000006,0.599875,-0.799286,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vieille photographie jaunie par les années, immortalisant l’effervescence de l’ouverture des Asphodèles. Citoyens modestes, marchands fortunés et même quelques dignitaires de la cité intérieure s’étaient rassemblés pour offrir leurs vœux à cette jeune taverne.",
          DialogueId = 70011801,
          Duration = 5,
          GUID = "AF44671A",
          SpeakNpcId = 102028,
          Subtitle = "(A yellowed photo capturing the grand opening of The Asphodel. Commoners, merchant princes and even some officials from the inner city gathered here to offer their best wishes to this newly opened tavern.)"
        },
        [70011901] = {
          Camera = "-652.218567,-446.646545,311.657959,0.000055,7.500012,42.603733,10.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une immense affiche, du type que l’on croise partout dans l’Empire, arborant des slogans tels que : « Toute gloire à l’Empereur ».",
          DialogueId = 70011901,
          Duration = 5,
          GUID = "AF447782",
          SpeakNpcId = 102029,
          Subtitle = "(A large poster, commonly seen throughout the Empire, bearing slogans like \"All glory to our Emperor\".)"
        },
        [70012001] = {
          Camera = "251.815674,-114.571671,67.927124,0.000047,-3.399658,170.391632,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "« La nouvelle session d’évaluation de la VIᵉ Légion, destinée aux citoyens Charons remplissant les conditions requises, va débuter sous peu.\nLes candidats peuvent se présenter au Bureau de la Sécurité pour déposer leur dossier.\nLe moment est venu de changer votre destin.\nSous la Bannière du Loup Noir, invoquez la puissance de l’Empereur Julius et offrez votre loyauté à l’Empire Hyperboréen !\n\nNotes :\nLes candidates et candidats faisant preuve d’une excellence exceptionnelle recevront la Médaille des Charons Couronnés, ouvrant droit à une résidence dans la cité Intérieure.\nCelles et ceux qui, sans obtenir la Médaille, se distingueront néanmoins par leurs performances seront incorporés parmi les Veilleurs de la cité extérieure.\nL’interprétation finale du règlement relève de la garnison provinciale de Cocytus, VIᵉ Légion.\nToute responsabilité liée aux incidents survenant au cours de l’évaluation incombe au participant. »",
          DialogueId = 70012001,
          Duration = 5,
          GUID = "AF4487EA",
          SpeakNpcId = 102030,
          Subtitle = [[
The latest 6th Legion recruitment (Charon Special) are set to commence shortly. Eligible Charons can proceed to the Security Bureau to submit their applications. Seize the moment to change your destiny. Under the flag of the Black Wolves, invoke the might of Emperor Julius and pledge your allegiance to Hyperborea! 
Note: 
1. Those with exceptional performance may earn the Laurelled Charon Medal, granting the privilege to be stationed in the Inner City.

2. Those who do not receive the Laurelled Charon Medal but show outstanding performance will be conscripted into the Outer City Escort. 
3. Final interpretation rights of the recruitment belong to the 6th Legion's Cocytus Province Garrison; participants assume all responsibility for any incidents that occur during the assessment.]]
        },
        [70012101] = {
          Camera = "-413.806396,24.681641,230.520782,0.000089,-29.19894,-18.408882,35.0,400.0,false,DoNotOverride,2.8",
          ContentFR = "Un conteneur bleu pâle porte l’inscription « Phoxichor ». Ce terme apparaît sur de nombreux dispositifs de transport, d’éclairage et d’énergie à travers l’Empire.\nD’après son nom, il s’agirait d’un dérivé raffiné du Phoxène.",
          DialogueId = 70012101,
          Duration = 5,
          GUID = "AF449852",
          SpeakNpcId = 102031,
          Subtitle = "A pale blue canister labelled \"Phoxichor\". This term is visible on a variety of items related to transportation and lighting across the Empire. The name itself suggests it is a derivative of Phoxene."
        },
        [70012201] = {
          Camera = "-829.676514,67.595215,115.704071,0.000047,28.996904,-8.414193,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Chaque fois que les aiguilles de l’horloge franchissent le chiffre douze, le nom Todd Wells apparaît fugitivement sur le cadran.\nAssocier ainsi mécanismes ingénieux et optique subtile pour dissimuler une signature témoigne, sans nul doute, du talent d’un horloger d’exception.",
          DialogueId = 70012201,
          Duration = 5,
          GUID = "AF44A8BA",
          SpeakNpcId = 102032,
          Subtitle = "Each time the clock hands pass 12, the name \"Todd Wells\" briefly appears on the dial. Combining mechanical ingenuity with optical principles to subtly incorporate his name into his work, Mr. Wells must be a master clockmaker."
        },
        [70012301] = {
          Camera = "576.424805,22.139282,190.283051,0.000035,-16.800291,175.187546,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "En vous approchant du véhicule, une voix surexcitée vous surprend :\n« Hé, hé, hé ! Vous aussi, vous vous intéressez à ce PRT20A, n’est-ce pas ? Rien d’étonnant ! Nous parlons tout de même d’un modèle civil de seconde génération, dérivé du militaire, doté d’une Roue Phoxynamo... Le fruit d’une sagesse transmise depuis des générations ! Certes, il n’égale pas la vitesse des modèles militaires, mais entendre le grondement de la Roue Phoxynamo d’aussi près, le conduire sur la route... c’est déjà un symbole de prestige ! »\nL’homme poursuit sans reprendre son souffle : histoire du modèle, structure interne, mécanisme de la roue, composition de la carrosserie, jusqu’aux nervures des pneus — rien n’échappe à son bavardage intarissable, qui dure des heures.\nQuand enfin le silence retombe, votre esprit bourdonne encore de termes obscurs sur des cylindres, des rotations et quantité d’autres mécaniques.\nEn levant les yeux pour comprendre pourquoi soudain tout s’est calmé, vous réalisez que le passionné s’est déjà rué vers un autre passant infortuné pour lui infliger à son tour le même discours enflammé.",
          DialogueId = 70012301,
          Duration = 5,
          GUID = "AF44B922",
          SpeakNpcId = 102033,
          Subtitle = "(Upon approaching the vehicle, you're greeted by an excited shout, \"Hey, there! You're also fascinated by this PRT20A, aren't you? I know, right?! I mean, this one here is the second-gen civilian model adapted from military use, powered by a Phoxynamo Wheel—a true epitome of wisdom passed down through the ages!)\n(Sure, it's not as speedy as the military versions, but just being able to hear the Phoxynamo Wheel purring up close while driving it around, that's a status symbol in itself...\", the speaker goes on and on, covering everything from the car's history, its engineering, the wheel, the body, down to the very treads on the tyres, talking your ear off for hours.)\n(When things finally quieten down, your head's still spinning with all sorts of technical jargon about cylinders and rotations. Looking around to find out why it's gone quiet, you see that the car fanatic has already scooted off to start up the same spiel with another poor soul passing by.)"
        },
        [70012401] = {
          Camera = "-712.020264,-289.200195,10.626465,0.000082,16.793509,22.182402,10.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un imposant mémorial, dont l’arrière est couvert de noms de citoyens de l’Empire. Sur la face avant, une phrase profondément gravée :\n\n« À la mémoire des soldats qui ont donné leur vie pour offrir à cette terre une paix durable. Toute gloire à l’Empereur. »",
          DialogueId = 70012401,
          Duration = 5,
          GUID = "AF44C98A",
          SpeakNpcId = 102034,
          Subtitle = [[
A towering monument, its back inscribed with names of the Empire's people, and on the front deeply engraved with a brief inscription: 
In memory of the soldiers who sacrificed themselves for the lasting peace on this land. 
All glory to our Emperor.]]
        },
        [70012501] = {
          Camera = "-593.807617,-151.208984,181.682983,0.000059,-13.99979,25.798237,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce n’est pas la première fois que vous apercevez des lampes de mineur, des pioches et des wagonnets dans les rues de Givrelac. La quantité même de ces outils annonce la grandeur qu’a jadis connue la cité lorsque l’extraction de Phoxène battait son plein.\nMais les voir abandonnés près des poubelles, recouverts de poussière... il est clair pour quiconque que la gloire des mineurs appartient désormais au passé.",
          DialogueId = 70012501,
          Duration = 5,
          GUID = "AF44D9F2",
          SpeakNpcId = 102035,
          Subtitle = "(In Icelake, the multitude of mining lamps, pickaxes, and minecarts is striking. The abundance of these mining tools speaks volumes of the city's once thriving Phoxene ore mining era. Yet, now they lie discarded beside rubbish bins, coated in dust, a poignant testament that the miners' days of glory have faded into history.)"
        },
        [70012601] = {
          Camera = "-429.546875,-25.467529,208.017578,0.000075,25.39749,-29.411985,20.0,100000.0,false,Manual,2.8",
          ContentFR = "L’ombre titanesque de l’usine s’étend sur la cité, telle un géant dominant la foule, enveloppant de sa présence de frêles existences. Chaque jour, des milliers d’ouvriers franchissent ses portes.\nMême à plusieurs centaines de mètres, on perçoit encore le grondement incessant de ce colosse métallique.",
          DialogueId = 70012601,
          Duration = 5,
          GUID = "AF44EA5A",
          SpeakNpcId = 102036,
          Subtitle = "The factory's immense shadow sprawls across the city, engulfing innumerable puny lives, like a giant looming over ants. Thousands of workers come and leave every day, and even from hundreds of metres away, one can hear the relentless rumble of this behemoth."
        },
        [70012701] = {
          Camera = "7.69043,-170.557617,63.654785,0.0,0.0,-89.999939,10.0,100000.0,false,DoNotOverride,2.24",
          ContentFR = "Le barrage routier interdit tout passage.\nUn panneau bien visible précise que la zone située au-delà est désormais placée sous l’autorité des Veilleurs de la VIᵉ Légion.",
          DialogueId = 70012701,
          Duration = 5,
          GUID = "AF44FAC2",
          SpeakNpcId = 102037,
          Subtitle = "The roadblock prohibits any passage. The prominent sign nearby indicates that the area ahead is now under the control of the 6th Legion's Escort."
        },
        [70012801] = {
          Camera = "902.932129,1093.807129,22.332031,0.000012,7.59978,-122.402924,35.0,100000.0,false,Manual,2.8",
          ContentFR = "Une installation de chauffage alimentée au Phoxichor, diffusant une chaleur douce et réconfortante pour quiconque s’assied à proximité.\nSa pose sommaire et son emplacement approximatif laissent supposer l’œuvre d’un habitant non professionnel — l’Empire n’ayant aucune intention de fournir un système de chauffage aux Charons.",
          DialogueId = 70012801,
          Duration = 5,
          GUID = "AF450B2A",
          SpeakNpcId = 102038,
          Subtitle = "A heating facility powered by Phoxichor, providing a comforting warmth to those nearby. Its makeshift installation and placement, however, hint at the handiwork of a local amateur, as the Empire deems the provision of heating for Charons utterly unnecessary."
        },
        [70012901] = {
          Camera = "538.746094,139.100586,83.406647,0.000042,-10.399529,-172.984406,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Des graffitis grossiers, griffonnés à la hâte, saturés d’injures adressées aux Charons.",
          DialogueId = 70012901,
          Duration = 5,
          GUID = "AF451B92",
          SpeakNpcId = 102039,
          Subtitle = "Messy graffiti crammed with insults to Charons."
        },
        [70013001] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.27",
          ContentFR = "Une tombe minuscule, assez grande pour un petit oiseau.\nLa stèle ne porte aucun nom, seulement l’inscription :\n\n« Ici repose mon compagnon éternel, le héros qui m’a aidé à fuir la mine. — Conon »",
          DialogueId = 70013001,
          Duration = 5,
          GUID = "AF452BFA",
          SpeakNpcId = 102040,
          Subtitle = "A tiny grave, barely large enough to accommodate a bird. The headstone is bereft of names, inscribed only with, \"Here lies my constant companion, the hero who helped me escape from the mine. — Conon\"."
        },
        [70013101] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.28",
          ContentFR = "Un sac tissé diffusant une lueur jaune pâle. À ses formes anguleuses, on devine qu’il est rempli de Phoxène.\nLa base du sac est maculée de traces de sang séché.",
          DialogueId = 70013101,
          Duration = 5,
          GUID = "AF453C62",
          SpeakNpcId = 102041,
          Subtitle = "A woven bag emitting a soft yellow glow, its bulging corners indicating it is filled with Phoxene, with the bottom marked by stains of blood."
        },
        [70013201] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.29",
          ContentFR = "Blocs de construction\nDe simples blocs de construction, autrefois très prisés des enfants, mais qui paraissent aujourd’hui dépassés et vieillots.",
          DialogueId = 70013201,
          Duration = 5,
          GUID = "AF454CCA",
          SpeakNpcId = 102042,
          Subtitle = [[
Building Blocks
(Simple building blocks, once popular among children but now seeming outdated and worn.)]]
        },
        [70013301] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.30",
          ContentFR = "Chambre de Psyche\nUne planche décorée d’un papillon vert pend à la porte, ornée d’un gribouillage enfantin : « Chambre de Psyche ». C’est ici que la petite Psyche vivait autrefois.\nAujourd’hui, la porte est verrouillée — sans doute une décision de sa mère, Daisy.",
          DialogueId = 70013301,
          Duration = 5,
          GUID = "AF455D32",
          SpeakNpcId = 102043,
          Subtitle = [[
Psyche's Room
(A green butterfly drawing board hangs on the door, with childish scribble spelling out "Psyche's Room". This must have been where Psyche lived. But now the door is locked, presumably at her mother Daisy's behest.)]]
        },
        [70013401] = {
          Camera = "-274.459961,499.943848,20.897705,0.000001,4.999999,-79.999969,16.0,100000.0,false,Manual,2.8",
          ContentFR = "À travers la vitrine de la boutique des Cent Visages, vous apercevez une robe longue au goût exquis.\nChaque pli, chaque couture est parfaitement ajusté, mettant en valeur la silhouette tout en reflétant l’élégance naturelle de celle qui la porterait.\nUn vêtement taillé sur mesure pour l’élégance naturelle d’Harlan.",
          DialogueId = 70013401,
          Duration = 5,
          GUID = "AF456D9A",
          SpeakNpcId = 102044,
          Subtitle = "(Through the window of the boutique named Looks Galore, one can see an elegant long dress. Each piece of fabric is expertly tailored, accentuating the wearer's beautiful figure and grace, perfectly suited for someone like Harlan.)"
        },
        [70013501] = {
          Camera = "36.606445,286.352539,23.979492,0.000003,-8.400025,-108.599854,15.0,100000.0,false,Manual,2.32",
          ContentFR = "Un seau et une serpillière posés près de Lio.\nCes outils sont manifestement destinés à nettoyer les taches rouge sombre à proximité — preuve silencieuse qu’un affrontement sanglant s’est joué ici peu de temps auparavant.",
          DialogueId = 70013501,
          Duration = 5,
          GUID = "AF457E02",
          SpeakNpcId = 102045,
          Subtitle = "(A bucket and mop set beside Lio, presumably for cleaning the ominous dark red stains nearby. A brutal confrontation might have occurred here.)"
        },
        [70013601] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.33",
          ContentFR = "Une vieille affiche jaunie, dont on peine à déchiffrer le contenu :\n\n...\nLe récital de la célèbre chanteuse Violetta commencera dès la semaine prochaine !\nLe classique Né du Blizzard renaît sur scène, et sa voix céleste résonnera dans toute Givrelac !\nUne semaine entière de représentations immanquables ! À ne manquer sous aucun prétexte !\nContre rémunération, possibilité de vous faire entrer clandestinement dans la cité intérieure !\nVenez goûter à une fête musicale réservée à l’élite !\n...\nContact : Monsieur Jack\nPoint de rendez-vous : chaque nuit, à minuit, près de la bouche d’égout.\nCode à transmettre à l’homme roux : « Coucou, coucou ».",
          DialogueId = 70013601,
          Duration = 5,
          GUID = "AF458E6A",
          SpeakNpcId = 102046,
          Subtitle = [[
A faded, barely legible old poster reads:
...
Lead vocalist Ms. Violetta's performance coming next week!
Children From the Snowfield makes a classic return, with her ethereal voice set to resonate throughout Icelake!
A full week of unmissable performances! Absolutely not to be missed!
Pay for an exclusive opportunity to be smuggled into the Inner City! A glimpse into a musical feast for the elite!
...
Contact: Mr. Jack
Meeting Point: Every midnight by the sewer manhole. Signal to the red-haired man with the code word "Cuckoo, Cuckoo".]]
        },
        [70013701] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.34",
          ContentFR = "Un manuel scolaire en lambeaux.\nLes espaces vierges ont été recouverts de gribouillages grossiers. On y voit Faye représentée en démon cornue, jetant des sortilèges inquiétants d’un geste de la main.",
          DialogueId = 70013701,
          Duration = 5,
          GUID = "AF459ED2",
          SpeakNpcId = 102047,
          Subtitle = "(A tattered textbook, its blank spaces filled with crude doodles. In these scribbles, Fahy is portrayed as a horned demon practising sinister dark magic.)"
        },
        [70013801] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.35",
          ContentFR = "On aperçoit parfois, à la Maison d’Hypnos, une femme au visage grave.\nElle passe le balai, prépare un repas chaud pour les enfants, puis s’en va discrètement.\n\nQuand on lui demande pourquoi, elle répond simplement :\n« Monsieur Henrik m’a engagée, alors je fais mon travail. C’est comme ça que va le monde. »\n\nSa voix trahit une lassitude silencieuse — de quoi décourager toute insistance.\n\nMais tous les enfants de la Maison d’Hypnos le savent : Madame Lina n’a jamais accepté le moindre sou de la part de Monsieur Henrik.",
          DialogueId = 70013801,
          Duration = 5,
          GUID = "AF45AF3A",
          SpeakNpcId = 102048,
          Subtitle = "A stern-faced woman is often seen at Hypnos' House, sweeping the halls and cooking warm meals for the children.\n\nWhen asked why she's there, she simply replies:\n\"Mr Henrik hired me, so I do the job. That's just how the world turns.\"\n\nHer voice carries a quiet weariness — enough to dissuade further questions.\n\nBut every child at Hypnos' House knows the truth: Ms Lina has never taken a single coin from Mr Henrik."
        },
        [70013901] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.36",
          ContentFR = "Un assemblage hétéroclite d’objets abandonnés. Difficile de comprendre les critères de sélection de Martin. Qui pouvaient bien être leurs anciens propriétaires ?",
          DialogueId = 70013901,
          Duration = 5,
          GUID = "AF45BFA2",
          SpeakNpcId = 102049,
          Subtitle = "(An eclectic array of abandoned items, leaving one to wonder about Martin's criteria for selection. Who might their previous owners have been?)"
        },
        [70014001] = {
          Camera = "-394.105225,225.10498,147.011475,0.00004,-19.999113,-46.394775,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Des boissons alcoolisées que Camilla a refusé de servir. Impossible de deviner où elles finiront leur route.",
          DialogueId = 70014001,
          Duration = 5,
          GUID = "AF45D00A",
          SpeakNpcId = 102050,
          Subtitle = "(The alcoholic beverages rejected by Camilla. No one knows where they will end up next.)"
        },
        [70014101] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.38",
          ContentFR = "Empreintes\nDes empreintes de pas à la taille d’un enfant. Elles doivent être celles qu’a entendues Buck.",
          DialogueId = 70014101,
          Duration = 5,
          GUID = "AF45E072",
          SpeakNpcId = 102051,
          Subtitle = [[
Footprints
(Child-sized footprints. These likely belong to the footsteps Buck heard.)]]
        },
        [70014201] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.39",
          ContentFR = "Popcorn\nOn dirait que le sac du coupable s’est percé d’un minuscule trou, semant du popcorn tout au long de sa fuite.\n« Un parfum de fruits mûrs »... tout s’explique désormais.",
          DialogueId = 70014201,
          Duration = 5,
          GUID = "AF45F0DA",
          SpeakNpcId = 102052,
          Subtitle = [[
Popcorn
(It appears that a small hole in the perpetrator's backpack left a trail of popcorn. "The scent of ripe fruit"... now it all adds up.)]]
        },
        [70014301] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.40",
          ContentFR = "Une petite tente rudimentaire où Belinda vit depuis longtemps.\nElle y tient aussi une sorte de boutique de conseils — sans enseigne, sans domaine clairement défini.\nLes visiteurs qui passent semblent tous porter un secret lourd à confier.",
          DialogueId = 70014301,
          Duration = 5,
          GUID = "AF460142",
          SpeakNpcId = 102053,
          Subtitle = "A humble tent where Belinda has made her home and runs a small advisory shop, with no sign nor a clear business scope. Her clients seem to bring with them their own unspoken woes."
        },
        [70014401] = {
          Camera = "-277.21875,1095.014038,199.530029,0.000023,24.997671,-88.593628,15.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une gigantesque grue alimentée au Phoxichor.\nGrâce aux améliorations des Éolipyliens, il n’est plus nécessaire qu’un opérateur soit assis au sommet de la machine : depuis une simple salle de contrôle, une pression sur un levier suffit désormais à manipuler plusieurs grues à la fois, décuplant l’efficacité.\nMais ce progrès a brisé les rêves de nombreux enfants fascinés par ces colosses de métal... et supprimé tout autant de postes pour les ouvriers.",
          DialogueId = 70014401,
          Duration = 5,
          GUID = "AF4611AA",
          SpeakNpcId = 102054,
          Subtitle = "A gigantic crane powered by Phoxichor. With modifications by the Aeolipile, these cranes no longer require operators to be stationed atop them. A mere push of a joystick in the control room can now simultaneously manage multiple cranes, greatly enhancing efficiency. However, this advancement has also shattered the dreams of many young boys once enamoured with these colossal machines, along with numerous job opportunities for workers."
        },
        [70014501] = {
          Camera = "-553.419922,-854.08313,145.091064,0.000012,-2.200284,52.400944,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une foreuse mobile militaire abandonnée, identifié comme modèle PRT05MV.\nLe temps a laissé ses marques : rouille, traces d’usure, peinture écaillée.\nPersonne ne le surveille, personne ne vient le récupérer.\nEst-ce la confiance de l’Empire quant à la sécurité de ses machines... ou la simple crainte de la Légion, qui dissuade tout être vivant d’approcher cette carcasse désertée ?",
          DialogueId = 70014501,
          Duration = 5,
          GUID = "AF462212",
          SpeakNpcId = 102055,
          Subtitle = "(An abandoned military drilling vehicle labelled PRT05MV. Its body bears the scars of time with weathering and patchy rust. Left unattended and unreclaimed, it is unclear whether this is due to the Empire's confidence in its vehicle security or the Legion's daunting presence deterring any creature from approaching this forsaken vehicle.)"
        },
        [70014601] = {
          Camera = "18.892578,-214.330688,159.580475,0.000026,-31.400263,99.99868,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un morceau de pain noir moisi, enveloppé dans une vieille feuille de journal.\nLe pain est immangeable, mais en dépliant le papier et en nettoyant la moisissure, on distingue une édition d’il y a plus de dix ans, relatant l’accord conclu entre la VIᵉ Légion et les anciens propriétaires de la Fosse de Glevum.\n...\nDans l’intérêt des mineurs et pour le développement futur de Givrelac, la Fosse de Glevum cesse à partir de ce jour toute exploitation privée. Toutes les opérations seront désormais placées sous la gestion directe de la Légion.\n...\nL’article est accompagné de photographies de la cérémonie.\nPourtant, sur ces clichés en noir et blanc, seuls l’officier brandissant l’accord et les mineurs acclamant sont visibles. Les anciens propriétaires de la Fosse n’apparaissent pas une seule fois — était-ce par refus... ou parce qu’ils n’étaient déjà plus en état d’assister à la scène ?",
          DialogueId = 70014601,
          Duration = 5,
          GUID = "AF46327A",
          SpeakNpcId = 102056,
          Subtitle = "A mouldy piece of rye bread encased in old newspaper. The bread is surely inedible now. Smoothing out the newspaper and brushing off the mould, one can find it is an edition from over a decade ago, featuring a report about the 6th Legion's agreement with the original owners of Glevum Pit.\n\n...\nIn the interest of the miners and for the betterment of Icelake, Glevum Pit will henceforth cease private mining operations, with all affairs to be managed by the Legion.\n...\n\nThe report includes several black and white photographs of the celebration ceremony. Oddly though, in these images, only the officer brandishing the agreement and the jubilant workers are visible. The pit's original owners are conspicuously absent — whether by choice or circumstance, one cannot tell."
        },
        [70014701] = {
          ContentFR = "Une lettre froissée, à l’évidence imprimée en masse et non écrite à la main :\n\n« Bonjour, citoyens de l’Empire. Je suis Dis Ier, fondateur de l’Empire Hyperboréen, et je vous écris depuis la Capitale Impériale de Dismania.\nOui, vous avez bien lu : je ne suis pas mort. J’ai survécu grâce à des arts occultes.\n\nJe m’apprête à reprendre notre grande campagne contre Élysium.\nMalheureusement, mes fonds de guerre sont actuellement déposés à Givrelac, et mon état m’empêche de m’y rendre.\n\nSi vous avez encore l’honneur et le sang d’un vrai fils de l’Empire, envoyez vos contributions au 233, Avenue du Triomphe, dans la Capitale Impériale.\nJe vous jure que lorsque j’aurai retrouvé mes forces et récupéré l’intégralité des fonds militaires, je vous rembourserai le double.\n\nSouvenez-vous : la guerre est imminente. N’attendez pas !\nJe compte sur votre soutien. Lorsque le moment viendra, je reviendrai tel l’éclair ! »\n\n(Une arnaque grossière, manifestement destinée aux crédules.)",
          DialogueId = 70014701,
          Duration = 5,
          GUID = "AF4642E2",
          SpeakNpcId = 102057,
          Subtitle = "A crumpled letter, evidently mass-printed rather than handwritten, reads: \n\nDear People of the Empire,\n\nGreetings from your greatest Dis I, the founder of the Hyperborea Empire, in Dismania, the imperial capital.\nAstonishing as it may seem, I am very much alive, having mastered the art of longevity.\nI am now gearing up to resume my great quest against Elysium.\nHowever, a small hitch — my required funds are all tied up in Icelake, and my current condition precludes me from accessing them personally. \nIf you still have the honor and courage of being a man of the Empire, do send your sponsorship to No. 233, Triumph Street in the imperial capital.\nRest assured, once I've bounced back and retrieved the full war funds, your investment will be returned twofold. \n\nRemember, the war is coming, so please act swiftly! Your sponsorship is eagerly anticipated!\nOnce I'm ready, I will return like lightning!"
        },
        [70014801] = {
          Camera = "-233.383423,129.945312,39.479553,0.000071,26.799578,-19.787138,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une boisson fermentée nommée Contes de Givrelac. Un simple tour de valve suffit à remplir son verre. Sa teinte rappelle le Phoxène ; son premier goût, mentholé, évoque la brise glacée du lac.\nEn descendant, elle révèle une douceur miellée, comme l’éclat jadis glorieux de l’industrie minière.\nPuis vient l’amertume tourbée, profonde, persistante — une saveur qui s’accroche à l’âme.\n(Contes de Givrelac porte bien son nom. Pas étonnant qu’elle soit la boisson la plus prisée aux Asphodèles.)",
          DialogueId = 70014801,
          Duration = 5,
          GUID = "AF46534A",
          SpeakNpcId = 102058,
          Subtitle = [[
(A fermented beverage known as "Tales of Icelake", just a valve turn away from filling your cup. Its hue resembles Phoxene, with an initial refreshing minty taste reminiscent of a brisk Icelake breeze. When swallowed, it leaves a honeyed sweetness akin to the glory of the Phoxene mining industry.)

(Finally, a lingering peaty bitterness fills the senses, leaving an indelible aftertaste. True to its name, Tales of Icelake is unsurprisingly the most popular beverage at The Asphodel.)]]
        },
        [70014901] = {
          Camera = "144.133301,295.799561,71.270615,0.000111,5.599437,-116.392715,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un mécanisme d’engrenages d’une finesse remarquable.\nPeu importe sa rotation, rien ne semble changer dans les Asphodèles, mais les légers cliquetis provenant de l’arrière du comptoir révèlent que ce dispositif n’a rien d’une simple décoration.",
          DialogueId = 70014901,
          Duration = 5,
          GUID = "AF4663B2",
          NextDialogue = 70014902,
          SpeakNpcId = 102059,
          Subtitle = "(An intricate gear mechanism that, despite its movements, leaves The Asphodel unchanged. However, the subtle mechanical sounds from behind the bar hint at a purpose beyond mere decoration.)"
        },
        [70014902] = {
          ContentFR = "Comme Camilla le disait si bien :\n« Pour une poignée de pièces, un marchand monterait volontiers à l’échafaud. »\nLes Asphodèles ne se résument peut-être pas à une modeste échoppe vendant des boissons fermentées...",
          DialogueId = 70014902,
          GUID = "AF4663B3",
          SpeakNpcId = 102059,
          Subtitle = "(Perhaps, just like Camilla once remarked, \"for a sliver of profit, merchants would go to the gallows\" — and The Asphodel may well be more than just a hut selling fermented drinks.)"
        },
        [70015001] = {
          Camera = "267.163086,229.933594,218.354156,0.000008,-28.000093,-144.996719,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un des nombreux usages de la technologie à base de Phoxène dans la vie quotidienne des citoyens de l’Empire.\nBien que la puissance d’éclairage reste moyenne, sa faible consommation, son coût réduit et sa longue durée de vie en ont fait la lampe la plus couramment utilisée à Givrelac.\nLa VIᵉ Légion en avait également installé un grand nombre lors de l’agrandissement de la Fosse de Glevum.",
          DialogueId = 70015001,
          Duration = 5,
          GUID = "AF46741A",
          SpeakNpcId = 102060,
          Subtitle = "One example of Phoxene technology application in the everyday lives of Imperial citizens. While the lighting is average, its excellent efficiency, low cost, and longevity have made it the primary lighting choice in Icelake. In the past, during the expansion of Glevum Pit by the 6th Legion, these lamps were also used extensively."
        },
        [70015101] = {
          Camera = "-293.902832,-246.538574,58.947754,0.000011,22.198734,42.000011,35.0,100000.0,false,Manual,2.8",
          ContentFR = "Un encadrement on ne peut plus banal, typique de l’Empire. Pourtant, en fixant ces deux petits carrés, impossible de ne pas y voir un visage grimaçant qui semble dire :\n« Quoi ?! Qu’est-ce que tu regardes, toi ?! »",
          DialogueId = 70015101,
          Duration = 5,
          GUID = "AF46741B",
          SpeakNpcId = 102061,
          Subtitle = "At first glance, it seems like just an ordinary doorframe, the kind you'd see anywhere in the Empire. Yet, those two square panels strangely resemble a face, almost as if it's snarling, \"What are you looking at!?\""
        },
        [70015201] = {
          ContentFR = "Des ossements, des armes et des provisions à moitié consommées, écrasés sous une pile de sacs usés — vestiges muets des Chasseurs de Phoxène disparus au fond de la mine abandonnée.\nVieilles ou neuves, ces besaces appartenaient à ceux qui étaient venus avec le même rêve : ressortir riches et victorieux.\nTous ont finalement trouvé la même fin misérable.",
          DialogueId = 70015201,
          GUID = "AF4694EA",
          Subtitle = "Beneath a pile of worn backpacks lie bones, weapons, and unfinished provisions — silent evidence of the grim fate that has claimed many a Phoxhunter who dared to descend into the forsaken pit.\nNew or old, these backpacks once belonged to those chasing the same rags-to-riches dream, each believing they would escape such a fate, only to meet the same tragic end."
        },
        [70015301] = {
          ContentFR = "Leur journal, froissé, et les morceaux de Phoxène ternis racontent une autre histoire : s’il leur avait été accordé un peu plus de temps... peut-être leur avenir aurait-il été tout autre.",
          DialogueId = 70015301,
          GUID = "AF46A552",
          Subtitle = "Tattered diaries and faded Phoxene cubes suggest that, had luck favoured them, their owners might have carved out a much brighter future."
        },
        [70015401] = {
          ContentFR = "Un faux <I>Écho de Givrelac</> gît dans une poubelle — une contrefaçon évidente, truffée d’erreurs d’impression.\nEn l’ouvrant, on tombe sur une succession d’histoires sensationnalistes :",
          DialogueId = 70015401,
          Duration = 5,
          GUID = "AF46B5BA",
          NextDialogue = 70015402,
          SpeakNpcId = 102064,
          Subtitle = "An old copy of the Icelake Daily, discarded in a rubbish bin, catches your eye. Upon closer inspection, you spot a few typos — it's clearly a knockoff. As you leaf through it, you come across some sensational stories:"
        },
        [70015402] = {
          ContentFR = "Les Secrets de Morris Glenville\n\nTout le monde connaît l’ascension fulgurante — puis la chute brutale — des Glenville : le jeune Morris, né dans la pauvreté, devenu magnat de l’acier, avant que la famille ne soit frappée par la folie, les morts accidentelles et les disparitions. Mais posons une autre question : pourquoi Morris tenait-il tant à conserver le souvenir de ses origines misérables ?",
          DialogueId = 70015402,
          Duration = 5,
          GUID = "AF46B5E4",
          NextDialogue = 70015403,
          SpeakNpcId = 102064,
          Subtitle = "Morris Glenville's Hidden Past\nEvery citizen of Icelake is familiar with the meteoric rise and sudden downfall of the Glenville family — how Morris Glenville, once a man of humble origins, became a steel magnate, only for his family to be plagued by madness, mysterious deaths, and disappearances. But today, we ask a different question — why did Mr Glenville choose to preserve his modest past?"
        },
        [70015403] = {
          ContentFR = "Peu savent que sa première fortune, Morris la gagna adolescent, sous les ordres d’un haut responsable des Éolipyliens — un Charon Couronné.\nSachant qu’il deviendrait plus tard un farouche anti-Charon, on peut se demander : quel secret enfoui reliait donc Morris à cet ancien supérieur ?",
          DialogueId = 70015403,
          Duration = 5,
          GUID = "AF46B60E",
          NextDialogue = 70015404,
          SpeakNpcId = 102064,
          Subtitle = "Few know that in his youth, Morris Glenville earned his seed money working under a high-ranking officer at the Aeolipile Alchademy, who was, in fact, a Laurelled Charon. Given Glenville's later vehement anti-Charon stance, one might wonder — what hidden history lies between him and his former Charon boss?"
        },
        [70015404] = {
          ContentFR = "Incroyable ! L’Empereur Julius est-il... un imposteur ?!?\nLes archives et les témoins de l’époque décrivent tous le prince Julius, avant son couronnement, comme un homme calme, courtois, d’une élégance discrète.\nPourquoi, alors, un changement si radical une fois devenu Empereur ?\nIl n’existe qu’une seule explication : le véritable Julius a été assassiné — et celui qui siège aujourd’hui au Palais de Bellona n’est qu’un usurpateur !",
          DialogueId = 70015404,
          Duration = 5,
          GUID = "AF46B638",
          NextDialogue = 70015405,
          SpeakNpcId = 102064,
          Subtitle = "The True Identity of Emperor Julius Revealed!!!\nHistorical records and accounts from those who served at the royal palace consistently portrayed Prince Julius, before his ascension to the throne, as a humble, graceful, and cautious gentleman. So, what caused his drastic change in demeanour upon taking the throne? There's only one plausible explanation — the real Julius was assassinated, and the man now in the Palace of Belloona is an imposter!"
        },
        [70015405] = {
          ContentFR = "Un frisson vous parcourt : vous en avez déjà trop lu. Vous remettez aussitôt le faux journal dans la poubelle.",
          DialogueId = 70015405,
          Duration = 5,
          GUID = "AF46B662",
          SpeakNpcId = 102064,
          Subtitle = "Realising you may have stumbled onto something you shouldn't, you quickly toss the knockoff newspaper back into the bin."
        },
        [70015501] = {
          Camera = "382.455078,-10.461182,127.896484,0.000083,-5.801112,-108.595062,30.0,96.67099,false,Manual,4.0",
          ContentFR = "Une photo prise il y a plus de dix ans. Le verre du cadre est couvert de traces de doigts.\nOn y voit une jeune Charon souriante, les cheveux caressés par le vent.\nAu dos, une inscription à l’encre :\n« Ma fille — Hayley. Prise à Rougerive. »\nElle ne ressemble pas vraiment à Psyche, et pourtant... son sourire limpide évoque irrésistiblement son souvenir.",
          DialogueId = 70015501,
          Duration = 5,
          GUID = "AF46C622",
          Subtitle = "An old photograph, taken more than a decade ago. The glass is clouded with fingerprints. In the picture, a Charon girl smiles softly as the breeze toys with her hair.\n\nOn the back, written in fountain pen:\n\"My daughter — Hayley. Taken in Scarletriver.\"\n\nShe doesn't much resemble Psyche... and yet, something in that innocent smile calls her to mind all the same."
        },
        [70015601] = {
          Camera = "-277.050781,-1.119873,213.634766,0.0,0.0,-179.999985,10.0,100000.0,false,Manual,2.8",
          ContentFR = "Sur la couverture épaisse du journal, une simple phrase : « Que leurs âmes reposent dans la Mer du Silence. »\nEn l’ouvrant, vous trouvez pages après pages des dates et des noms... terriblement familiers.",
          DialogueId = 70015601,
          Duration = 5,
          GUID = "AF46D68A",
          NextDialogue = 70015602,
          Subtitle = "The cover of the heavy journal bears a simple inscription: \"May their souls rest in the Misty Sea.\" As you flip through the pages, you recognise names and dates that are all too familiar."
        },
        [70015602] = {
          Camera = "-277.050781,-1.119873,213.634766,0.0,0.0,-179.999985,10.0,100000.0,false,Manual,2.8",
          ContentFR = [[
...
3 septembre, Carolina Brown.
...
29 octobre, Hunt Clark.
...
25 novembre, Psyche Frey.]],
          DialogueId = 70015602,
          Duration = 5,
          GUID = "AF46D6B4",
          Subtitle = [[
...
September 3, Carolina Brown.
...
October 29, Hunt Clark.
...
November 25, Psyche Frey.]]
        },
        [70015701] = {
          Camera = "-746.286377,-2980.045654,256.510742,0.000001,14.999996,-44.999969,18.0,100000.0,false,Disable,2.8",
          ContentFR = "Un cristal semblable au Phoxène — du moins, de loin.\nDe près, ses veines et sa texture ne trompent pas : juste une simple pierre lumineuse, sans valeur.",
          DialogueId = 70015701,
          Duration = 5,
          GUID = "AF46E6F2",
          NextDialogue = 70015702,
          Subtitle = "A crystal that resembles Phoxene at first glance, but a closer inspection reveals its texture and pattern are entirely different — just an ordinary glowing rock."
        },
        [70015702] = {
          Camera = "-746.286377,-2980.045654,256.510742,0.000001,14.999996,-44.999969,18.0,100000.0,false,Disable,2.8",
          ContentFR = "L’humanité classe les minerais selon leur utilité. Le Phoxène est précieux ; ces pierres-là, méprisées.\nC’est ainsi que le Phoxène a été extrait, brisé, broyé, raffiné jusqu’à devenir du Phoxichor glacé dans les usines rugissantes — tandis que ces petites pierres sans importance sont restées intactes, préservées par leur inutilité même.",
          DialogueId = 70015702,
          Duration = 5,
          GUID = "AF46E71C",
          Subtitle = [[
Humans rank minerals by their usefulness, and while Phoxene is a highly coveted resource, these stones are deemed worthless.
As a result, while Phoxene ore was mined to exhaustion, shattered, and refined into cold Phoxichor in roaring factories, these unassuming rocks remain untouched, preserved in their natural state.]]
        },
        [70015801] = {
          Camera = "492.773438,-508.054688,926.297363,0.000004,-0.000096,143.197693,11.88,100000.0,false,DoNotOverride,2.8",
          ContentFR = "De vastes dispositifs de levage sont visibles un peu partout sur les quais. À la différence du style froid de l’Empire, fait d’assemblages de métal et de rivets, les installations de Huaxu reposent principalement sur des structures en bois à tenons et mortaises.\nEn observant de plus près leur base, on distingue une discrète inscription gravée :\n« Fabriqué par le Bureau des Travaux ».",
          DialogueId = 70015801,
          Duration = 5,
          GUID = "AF46F75A",
          Subtitle = "Large cranes are commonly found across the docks. Unlike the Empire's cold constructions of riveted metal, those in Huaxu are built mainly with wooden mortise-and-tenon joints. A closer look reveals a small inscription at the base: Made by the Ministry of Works."
        },
        [70015901] = {
          Camera = "-447.582031,-536.535156,268.742676,0.000001,5.399906,55.198711,11.88,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vestige d’une méchapoupée antique, depuis longtemps privée de ses fonctions originelles par l’érosion du temps.\nSes composants sont aujourd’hui dispersés aux quatre coins de Port-des-Brumes, dissimulés sous une végétation abondante.",
          DialogueId = 70015901,
          Duration = 5,
          GUID = "AF4707C2",
          Subtitle = "The remains of an ancient automaton have long been stripped of their original function by the passage of time. Its parts now lie scattered across Mistwharf, many of them half-buried beneath overgrown vegetation."
        },
        [70016001] = {
          ContentFR = "La <H>Fête de la Chandelle d’Argent</> aura lieu comme prévu au Théâtre Galea. Préparez la tenue de votre choix et le rôle que vous désirez incarner.\nOublions nos métiers, nos races et nos conflits pour nous rassembler sous la grâce de l’Empereur.\nEnsemble, louons sa bienveillance et proclamons : Toute gloire à l’Empereur !",
          DialogueId = 70016001,
          GUID = "AF47182A",
          Subtitle = [[
The Silvercandle Carnival will proceed as scheduled at Galea Theatre. Participants are encouraged to prepare their finest attire and select the role they wish to embody. 
Let us set aside professions, races, and conflicts, and gather under the Emperor's grace. Together, we shall bask in His Majesty's benevolence and proclaim: All glory to our Emperor!]]
        },
        [70016002] = {
          ContentFR = "Un registre épais où chaque membre du personnel voit son emploi du temps consigné dans le moindre détail : répétitions, repas, sommeil, même les passages aux toilettes.\nOn ignore si la directrice du théâtre a véritablement \"enfermé\" ses comédiens avec une sévérité impitoyable, ou si elle n’a fait que les surveiller de près pour mieux les protéger.",
          DialogueId = 70016002,
          GUID = "AF471854",
          Subtitle = [[
A thick attendance log that meticulously records every staff member's daily schedule, tracking everything from rehearsals to meals, sleeping hours, and even bathroom breaks.
It's hard to tell whether the director is ruthlessly "imprisoning" everyone in the theatre or simply keeping a vigilant watch to protect her performers.]]
        },
        [70016003] = {
          ContentFR = "Une médaille entièrement forgée en or pur. D’après la lettre d’éloge jointe, cette distinction n’est remise qu’aux soldats dont les services rendus à l’Empire dépassent toute mesure d’excellence.",
          DialogueId = 70016003,
          GUID = "AF47187E",
          Subtitle = "A medal forged entirely of pure gold. According to the accompanying commendation letter, this honour is reserved for soldiers whose contributions to the Empire are deemed exceptional beyond measure."
        },
        [70016004] = {
          ContentFR = "Enfoui sous un tas d’objets oubliés, ce vieux quotidien jauni relate un tragique accident survenu il y a bien longtemps.",
          DialogueId = 70016004,
          GUID = "AF4718A8",
          Subtitle = "Buried beneath a pile of old clutter, this yellowed newspaper recounts a tragic incident from years ago."
        },
        [70016005] = {
          ContentFR = "Une boîte simple, ornée d’un nœud de ruban maladroit, posée à côté d’une fiole du meilleur analgésique impérial. À côté, une carte non glissée dans le paquet :\n« Rétablis-toi vite. »",
          DialogueId = 70016005,
          GUID = "AF4718D2",
          Subtitle = "A plain gift box with a clumsily made ribbon bow, accompanied by a bottle of the Empire's finest painkiller. Next to it is an unsent note that reads: \"Get well soon.\""
        },
        [70016006] = {
          Camera = "-35.015625,151.625,225.035156,0.000034,-14.798724,-71.592674,35.0,100000.0,false,Manual,22.0",
          ContentFR = "<I>Une photo d’un frère et une sœur sous les murailles de la cité. En haut à droite, les noms « Rhythm Fischer » et « Blues Fischer », avec un mot de félicitations pour la réussite de Blues à l’examen de la VIᵉ Légion.</>",
          DialogueId = 70016006,
          GUID = "AF4718FC",
          Subtitle = "(A photo of a brother and sister standing under the inner city wall. Scribbled in the top-right corner are the names \"Rhythm Fischer\" and \"Blues Fischer,\" along with a congratulatory note celebrating Blues' passing the 6th Legion's entrance tests.)"
        },
        [70016007] = {
          Camera = "36.316406,112.411133,226.279297,0.00002,-31.198172,-98.592926,35.0,100000.0,false,Manual,22.0",
          ContentFR = "<I>Un vieil harmonica, inutilisé depuis longtemps. Il ressemble plus à un cadeau précieux qu’à un passe-temps de Rhythm.</>",
          DialogueId = 70016007,
          GUID = "AF471926",
          Subtitle = "(A harmonica that looks like it hasn't been used in a long time. Its condition suggests it's more of a cherished gift than a personal hobby of Rhythm's.)"
        },
        [70016008] = {
          ContentFR = "Dans un coin du mur chaulé, des mots gravés à la pointe d’un couteau se répètent, tantôt maladroits comme une écriture d’enfant, tantôt fermes comme une main adulte. Toujours la même phrase :\n\n« Je ne regarderai plus jamais quelqu’un mourir à cause d’un Souillé. »",
          DialogueId = 70016008,
          GUID = "AF471950",
          Subtitle = "One corner of the limewashed wall is covered in countless etched words. Some are crooked and childlike, while others are firm and deliberate, clearly written by an adult hand. All of them repeat the same sentence: \"I'll never let anyone die to Filthoids again.\""
        },
        [70016009] = {
          ContentFR = "Inventaire des accessoires – Théâtre Galea\n\nPlusieurs membres de l’équipe en coulisse tiennent ce registre, qui détaille avec précision la gestion des accessoires du théâtre sur les deux dernières semaines.\n\n08 oct.\nPréparés : costumes et sacs de couchage.\nConfirmé par : Mondry\n(Note : Les réserves de nourriture s’épuisent. <H>Pour le mois intensif de répétitions à venir, il faudra demander une nouvelle livraison.</>)\n...\n12 nov.\nRemplacés : trois microphones.\nConfirmé par : Grinde\n(Note : L’un d’eux émet un son beaucoup trop fort, mais la directrice Putsch a insisté pour le garder tel quel.)\n14 nov.\nInstallé : rideau rouge. Le rideau doré a été renvoyé à l’entrepôt.\nConfirmé par : Bell\n...\n24 nov.\nRetrouvés : cinq perruques égarées.\nConfirmé par : Bell\n(Note : Les coins de la loge accumulent toutes sortes d’objets. Je vais tout vider aujourd’hui.)\n25 nov.\nPréparés : quinze couronnes de fleurs, neuf paires de bottes de cavalier.\nConfirmé par : Mondry",
          DialogueId = 70016009,
          GUID = "AF47197A",
          Subtitle = [[
Galea Theatre Props Inventory

A detailed log maintained by the backstage crew, documenting the management of props at Galea Theatre over the past two weeks.

8-Oct
Organized: Costumes and sleeping bags.
Logged by: Mondry
(Note: Food supplies are running low. We'll need to bring in another batch soon to prepare for the upcoming month-long intensive rehearsals.)
...
12-Nov
Replaced: Three new microphones.
Logged by: Grinde
(Note: One microphone produces an unusually loud sound, but Director Putsch insisted that it remain as is.)
14-Nov
Updated: Red curtain installed; gold curtain returned to storage.
Logged by: Bell
...
24-Nov
Retrieved: Five missing wigs.
Logged by: Bell
(Note: The dressing room corners are cluttered and seem to hide all sorts of things. I'll clean them out today.)
25-Nov
Organized: Fifteen flower crowns; nine pairs of riding boots.
Logged by: Mondry]]
        },
        [70016010] = {
          Content = "与剧院帷幕材质十分接近的布料，虽然老旧但十分整洁，显然经过什么人的认真打理。\n仔细观察和触摸会发现，和袭击现场发现的帷幕是同一块布料。",
          DialogueId = 70016010,
          GUID = "AF4719A4",
          Subtitle = [[
A piece of fabric resembling theatre curtain material. Though old and worn, it is impeccably clean, clearly maintained with care.
Upon closer inspection, it matches the fabric found at the crime scene.]]
        },
        [70016011] = {
          ContentFR = "Malgré leur ancienneté, ils ont été disposés et habillés avec soin. Leur attitude évoque la grâce d’acteurs livrés à leur art.",
          DialogueId = 70016011,
          GUID = "AF4719CE",
          Subtitle = "Though worn with age, the mannequin has clearly been posed and styled with care, exuding a graceful elegance, — like a performer lost in the moment on stage."
        },
        [70016012] = {
          ContentFR = "D’énormes marques, denses et chaotiques, gravées dans la pierre comme dans une transe de douleur et de folie.",
          DialogueId = 70016012,
          GUID = "AF4719F8",
          Subtitle = "Huge claw marks slash across the walls — dense, erratic, as if left in a frenzy of agony and madness."
        },
        [70016013] = {
          ContentFR = "Un fragment de la complexe cartographie des égouts de Givrelac reliant les différents quartiers de la cité. De vastes sections sont marquées d’un avertissement : \n« Interdit d’entrer sans autorisation des Veilleurs. »",
          DialogueId = 70016013,
          GUID = "AF471A22",
          Subtitle = "A partial map of Icelake's sewer system. Its tangled network of pipes connects the city's many districts. Numerous sections are marked \"Do Not Enter Without Escort Authorisation.\""
        },
        [70016101] = {
          Camera = "-15.959961,1605.265137,1322.948242,0.000059,-29.399687,-89.596825,20.875948,100000.0,false,Manual,22.0",
          ContentFR = "Rétablir l’alimentation du système de transport de tourelles nécessite la connexion de quatre câbles.",
          DialogueId = 70016101,
          GUID = "AF472892",
          NextDialogue = 70016102,
          Subtitle = "(Restoring power to the turret transport system requires four cables to be connected.)"
        },
        [70016102] = {
          Camera = "224.294922,655.639038,672.151611,0.000109,-27.999538,-125.796112,20.875948,100000.0,false,Manual,22.0",
          ContentFR = "L’un d’eux est déjà alimenté.",
          DialogueId = 70016102,
          GUID = "AF4728BC",
          NextDialogue = 70016103,
          Subtitle = "(One is already in place.)"
        },
        [70016103] = {
          Camera = "-1774.869141,-1374.734619,1171.844727,0.000131,-33.399078,23.004192,20.875948,100000.0,false,Manual,22.0",
          ContentFR = "Il en reste trois à connecter. Suis les câbles pour trouver les Roues Phoxynamo correspondantes.",
          DialogueId = 70016103,
          GUID = "AF4728E6",
          Subtitle = "(Three to go. Follow the cables to locate the remaining Phoxynamo Wheels.)"
        },
        [70016104] = {
          Camera = "-5344.007812,-255.292114,647.478394,0.000156,-14.998623,83.199738,20.875948,100000.0,false,Manual,22.0",
          ContentFR = "Ceci est <H>un ensemble</> de Roues Phoxynamo, et il semble devoir être activé dans un <H>délai précis</>.",
          DialogueId = 70016104,
          GUID = "AF472910",
          Subtitle = "(This set of Phoxynamo Wheels appears to be on a timer. Activate them quickly!)"
        },
        [70016105] = {
          Camera = "5543.811523,-2108.574219,180.364319,0.000151,-3.998317,-104.994102,20.875948,100000.0,false,Manual,22.0",
          ContentFR = "L’accès est bloqué... Y aurait-il un moyen d’activer les Roues Phoxynamo <H>à distance</> ?",
          DialogueId = 70016105,
          GUID = "AF47293A",
          Subtitle = "(The path is blocked. Is there a way to trigger the Phoxynamo Wheels from a distance?)"
        },
        [70016106] = {
          Camera = "157.341797,-91.314453,242.558594,0.0,-60.19952,101.398407,16.122608,100000.0,false,Manual,22.0",
          ContentFR = "Un visage inconnu.",
          DialogueId = 70016106,
          GUID = "AF472964",
          Subtitle = "(This isn't Avar. It's a complete stranger.)"
        },
        [70016107] = {
          Camera = "-71.794922,628.722656,135.195312,0.000076,12.199674,-90.596268,17.78793,100000.0,false,Manual,22.0",
          ContentFR = "※ Témoignage de Calem (unité des Narvals)\n« J’ai vu {性别2:le|la} Capitaine {nickname2} des Griffons sortir {性别2:seul|seule} de ████, le torse couvert de ████. »\n\n« {性别2:Il|Elle} nous a ordonné de rester en position, affirmant qu’{性别2:il|elle} allait vérifier ████ pour repérer d’éventuels Déchus cachés. »\n\n« Deux minutes plus tard, l’alarme s’est déclenchée. La Capitaine Falsi et moi avons accouru : le Capitaine Avar des Loups Blancs gisait dans une mare de sang. ████ était déjà enclenché. »",
          DialogueId = 70016107,
          GUID = "AF47298E",
          Subtitle = "※ Testimony from Calem (Narwhals unit) \nStatements as follows:\n• \"I saw Captain  of the Griffins exit the ▇▇▇ ▇▇▇▇ alone — there was ▇▇▇ ▇▇▇▇ {性别2:his|her} chest.\"\n• \"{性别2:He|She} told us to hold position while {性别2:he|she} went to check the ▇▇▇▇ for any remaining Forsakens personnel.\"\n• \"Two minutes later, the alarm sounded. Captain Falsi and I rushed in — found Captain Avar of the Snow Wolves lying in a pool of blood. The ▇▇▇▇ ▇▇▇▇ had already been triggered.\""
        },
        [70016108] = {
          ContentFR = "Aucun signe de vie parmi les soldats.",
          DialogueId = 70016108,
          GUID = "AF4729B8",
          Subtitle = "(No trace of life remains among the soldiers.)"
        },
        [70016109] = {
          ContentFR = "Des carcasses de Souillés jonchent le sol — ce sont ces créatures qui ont fauché la jeunesse des soldats. Mais, jusqu’à leur dernier souffle, ces derniers ont riposté : leurs balles mortelles ont percé les monstres qui les ont emportés.",
          DialogueId = 70016109,
          GUID = "AF4729E2",
          Subtitle = "(The Filthoid corpses nearby tell the tale: it was these beasts that ended them. And yet, even in death, the soldiers did not go quietly — their final rounds left lethal wounds in the Filthoids that claimed them.)"
        },
        [70016110] = {
          Camera = "129.879883,311.569336,152.664062,0.000072,3.399556,-2.996889,17.78793,100000.0,false,Manual,22.0",
          ContentFR = "※ Enquête sur les origines de {nickname2}\n{nickname2} a été {性别2:identifié comme l’un des survivants|identifiée comme l’une des survivantes} du ████, survenu il y a trois ans lors de ████.\n\nD’après ses propres déclarations, {nickname2} souffre d’amnésie partielle, bien que ses facultés cognitives demeurent intactes et son jugement, stable.\n\nIl est à noter que, selon les témoignages d’autres rescapés, {nickname2} ne figurait pas sur la liste des passagers enregistrés à ████. Autrement dit, <H>{性别2:il était bel et bien un \"passager fantôme\"|elle était bel et bien une \"passagère fantôme\"}</>.\n\nÀ l’époque, la XIIIᵉ Légion mena une enquête approfondie sur son identité sans parvenir à l’authentifier, tout en écartant définitivement l’hypothèse ████.\n\nL’explication la plus plausible suggère {性别2:qu’il aurait été un civil local|qu’elle aurait été une civile locale} ayant cherché refuge dans ████ pour échapper aux bombardements, subissant alors un traumatisme crânien responsable de sa perte de mémoire.",
          DialogueId = 70016110,
          GUID = "AF47298F",
          Subtitle = "※ Investigation into the Family Background of \n is a confirmed survivor of the ▇▇▇ ▇▇▇▇, which occurred three years ago during a military operation against ▇▇▇ ▇▇▇ ▇▇▇. According to , {性别2:he|she} suffers from memory loss, though exhibits no signs of cognitive dysfunction.\nNotably, eyewitness accounts from other survivors confirm that  was not listed among the original passengers on ▇▇▇ ▇▇▇. In other words, {性别2:he|she} was a bona fide \"ghost passenger.\"\nAt the time, the 13th Legion conducted a comprehensive investigation into 's background but was unable to verify {性别2:his|her} identity. However, the possibility of {性别2:him|her} being ▇▇▇ ▇▇▇▇ ▇▇▇ was definitively ruled out. A leading theory suggests that {性别2:he|she} may have been a local civilian who sought shelter in ▇▇ ▇▇▇▇ during the bombing and suffered a head injury, resulting in partial amnesia."
        },
        [70016111] = {
          ContentFR = "Un petit cairn de pierres a été dressé ici, accompagné d’un bouquet de fleurs blanches — un signe discret de recueillement.\nEn y regardant de plus près, on distingue sur l’une des pierres un nom gravé, commençant par la lettre « H », presque entièrement effacé par le temps.",
          DialogueId = 70016111,
          GUID = "AF4729E3",
          Subtitle = "A small cairn has been set here, white flowers laid gently beside it — a quiet sign of remembrance. Look closely, and you can just make out a name beginning with \"H\" carved into one of the stones, its letters worn to near nothing by time."
        },
        [70016201] = {
          Camera = "-979.316406,765.861328,939.019043,0.000035,6.200213,-41.002151,11.880002,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une imposante stèle de pierre sur laquelle sont gravées les Neuf Chapitres de Dafeng, érigée afin d’avertir et d’éveiller les consciences.\nLes préceptes qui y sont inscrits doivent impérativement être respectés sur l’ensemble du territoire de Huaxu.",
          DialogueId = 70016201,
          Duration = 5,
          GUID = "AF4738FA",
          NextDialogue = 70016202,
          Subtitle = "This large stone stele, inscribed with the Nine Chapters of Dafeng, was set in place to warn all who pass. The admonitions carved upon it are to be strictly observed within the borders of Huaxu."
        },
        [70016202] = {
          Camera = "-979.316406,765.861328,939.019043,0.000035,6.200213,-41.002151,11.880002,100000.0,false,DoNotOverride,2.8",
          ContentFR = "La grande vertu du Ciel porte le nom de Vie ;\nAttenter au corps ou ôter la vie — cela est proscrit.\n \nLa parole fonde l’homme et établit la confiance ;\nRompre un serment ou trahir une alliance — cela est proscrit.\n \nFaire triompher le vrai et écarter le faux, agir avec un cœur sincère ;\nTromper les foules par des paroles mensongères — cela est proscrit.",
          DialogueId = 70016202,
          Duration = 5,
          GUID = "AF473924",
          NextDialogue = 70016203,
          Subtitle = "Heaven's great virtue bears the name of Life;\nTo wound or kill — this must not be done.\nA man is measured by the strength of his word;\nTo break faith or betray a vow — this must not be done.\nLet truth be manifest and falsehood driven out;\nTo deceive and mislead the many — this must not be done."
        },
        [70016203] = {
          Camera = "-979.316406,765.861328,939.019043,0.000035,6.200213,-41.002151,11.880002,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Se gouverner avec humilité, se contenir par la modestie ;\nSe livrer à l’arrogance et à la brutalité — cela est proscrit.\n \nHonorer les sages, traiter autrui avec respect, préserver l’ordre et la bienséance ;\nAgir sans retenue ni mesure — cela est proscrit.\n \nÉtendre à autrui ce que l’on exige de soi, agir selon la juste mesure ;\nAbuser de sa force pour opprimer les faibles — cela est proscrit.",
          DialogueId = 70016203,
          Duration = 5,
          GUID = "AF47394E",
          NextDialogue = 70016204,
          Subtitle = "Govern the self with humility, bind conduct to modesty;\nTo indulge in arrogance and tyranny — this must not be done.\nHonour the worthy, extend courtesy, and let order be the measure of propriety;\nTo act with wanton excess and unbridled abandon — this must not be done.\nLet compassion and righteousness guide your mind and every deed;\nTo oppress the weak by force — this must not be done."
        }
      }
    end
  },
  {
    MinKey = 70016204,
    MaxKey = 71002508,
    Loader = function()
      return {
        [70016204] = {
          Camera = "-979.316406,765.861328,939.019043,0.000035,6.200213,-41.002151,11.880002,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Purifier son cœur, discipliner sa conduite, rester droit pour être intègre ;\nCourber la loi par avidité ou cruauté — cela est proscrit.\n \nDistinguer clairement le juste de l’injuste, savoir discerner avec lucidité ;\nConfondre le vrai et le faux — cela est proscrit.\n \nÉcouter les décrets du Ciel avec respect et solennité ;\nS’écarter de la voie et renier l’ordre sacré — cela est proscrit.",
          DialogueId = 70016204,
          Duration = 5,
          GUID = "AF473978",
          Subtitle = "Let your heart be pure, your conduct restrained, and uprightness be the mark of integrity;\nTo bend the law for greed or cruelty — this must not be done.\nLet clarity be your unwavering guide in discerning right from wrong;\nTo confuse truth and falsehood — this must not be done.\nAttend to Heaven's edict with a reverent mind and a solemn heart;\nTo rebel against the sacred order — this must not be done."
        },
        [70016301] = {
          Camera = "11.238281,-188.23291,625.148438,0.000004,-3.799989,-98.400398,13.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Statue représentant Taihao, le Dragon d’Argent, divinité vénérée et pilier de la foi spirituelle du peuple de Huaxu.",
          DialogueId = 70016301,
          Duration = 5,
          GUID = "AF474962",
          NextDialogue = 70016302,
          Subtitle = "A statue of Taihao — known as Lord Argent, who is revered by the people of Huaxu."
        },
        [70016302] = {
          Camera = "11.238281,-188.23291,625.148438,0.000004,-3.799989,-98.400398,13.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "La statue dresse fièrement sa tête draconique sur la rive extérieure d’Éternel Printemps, veillant en silence sur cette terre préservée.\nSon rôle ne semble pas se limiter à un simple symbole spirituel : selon la légende, lorsque le danger approche, Taihao, le Dragon d’Argent, peut se manifester à travers cette statue, répondre aux prières et balayer toute corruption.",
          DialogueId = 70016302,
          Duration = 5,
          GUID = "AF47498C",
          Subtitle = "It stands upon the riverbank outside EverSpring, its mighty head held high as it watches silently over the realm. Yet its role seems to reach beyond mere symbolism. Legend holds that, in times of crisis, Lord Argent may manifest through the statue itself, answering prayers and purging all that is foul."
        },
        [70016401] = {
          Camera = "2886.273438,2012.956055,3502.893555,0.000015,5.199823,-141.799973,13.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "De loin, il évoque une lune brillante suspendue derrière Éternel Printemps.\nCe n’est qu’en s’en approchant que l’on distingue les motifs propres à un mécanisme, accompagnés d’un parfum d’encens riche et enveloppant.",
          DialogueId = 70016401,
          Duration = 5,
          GUID = "AF4759CA",
          NextDialogue = 70016402,
          Subtitle = "From afar, it resembles a bright moon looming above the rear of EverSpring. Only up close do its mechanical patterns emerge, together with a rich, lingering plume of incense."
        },
        [70016402] = {
          Camera = "2886.273438,2012.956055,3502.893555,0.000015,5.199823,-141.799973,13.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Cette « lune » est l’aboutissement des savoirs conjugués des Sectes Xuanheng et Jishu. Il s’agit en réalité du dispositif à propulsion d’encens de la région de Port-des-Brumes.\nL’encens s’y consume et se diffuse, porté aux quatre vents, afin de maintenir l’ordre établi par les Neuf Chapitres de Dafeng.",
          DialogueId = 70016402,
          Duration = 5,
          GUID = "AF4759F4",
          Subtitle = "This \"moon\" draws upon the finest techniques of both the Xuanheng and Jishu sects, and is in truth the Incense-Powered Device of Mistwharf. Incense vapour is released within and channelled outward, its influence carried across the land to uphold the order of the Nine Chapters of Dafeng."
        },
        [70016501] = {
          Camera = "29.942383,-19.513672,525.364014,0.000019,28.799376,-80.196136,15.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Dans les profondeurs obscures de Chant-des-Marées, privées de toute lumière naturelle, s’épanouit pourtant une immense plante luminescente. Serait-ce là le témoignage du désir éternel de la vie de tendre vers la lumière ?",
          DialogueId = 70016501,
          Duration = 5,
          GUID = "AF476A32",
          NextDialogue = 70016502,
          Subtitle = "In the lightless depths of Tidesong Cavern, a great luminous plant somehow flourishes — perhaps a quiet testament to life's eternal yearning for the light."
        },
        [70016502] = {
          Camera = "29.942383,-19.513672,525.364014,0.000019,28.799376,-80.196136,15.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Suspendue au plafond rocheux, elle diffuse une lueur douce et pâle à travers la caverne, offrant un repère lumineux aux rares voyageurs de passage.",
          DialogueId = 70016502,
          Duration = 5,
          GUID = "AF476A5C",
          Subtitle = "Suspended from the cavern ceiling, it spills a soft, pale glow into the darkness, guiding any traveller who passes below."
        },
        [70016601] = {
          Camera = "745.375,17.552734,2003.395996,0.000002,7.399881,175.19902,13.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une gigantesque épave échouée dans le Marché Voilé. Vue de l’extérieur, elle semble délabrée et inerte, mais son intérieur recèle un tout autre monde.\nSon propriétaire, Maître Qiu, l’a transformée en demeure personnelle, qu’il a baptisée la Demeure du Dragon Caché.",
          DialogueId = 70016601,
          Duration = 5,
          GUID = "AF477A9A",
          Subtitle = "A large shipwreck that lies stranded in Haze Market. Its hull appears decayed and lifeless, yet its interior hides a world of its own. Its owner, Mr Qiu, has refashioned it into his dwelling, naming it \"The Hidden Loong\"."
        },
        [70016701] = {
          Camera = "909.160156,-79.808594,2942.352051,0.000001,-4.80014,-178.998611,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Le temps érode la plupart des choses, leur faisant perdre leur fonction première.\nPourtant, certaines créations éternelles semblent capables de transcender les âges.",
          DialogueId = 70016701,
          Duration = 5,
          GUID = "AF478B02",
          NextDialogue = 70016702,
          Subtitle = "Time wears down most things, stripping them of their purpose, yet some creations endure beyond the grasp of ages."
        },
        [70016702] = {
          Camera = "909.160156,-79.808594,2942.352051,0.000001,-4.80014,-178.998611,20.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Des siècles après la destruction du centre de recherche de la Secte Jishu, le Noyau de la Formation des Mille-Serrures demeure suspendu au-dessus de la Plaine des Corbeaux, repoussant toute intrusion — bien que ses créateurs aient depuis longtemps disparu dans la poussière de l’Histoire.",
          DialogueId = 70016702,
          Duration = 5,
          GUID = "AF478B2C",
          Subtitle = "Centuries after the Jishu Sect's research grounds fell to ruin, the array's core still hangs above Crowsong Hollow, driving back all intruders long after its creators have vanished from history."
        },
        [70016801] = {
          Camera = "1339.019531,976.865234,1511.71582,0.000001,3.999799,-138.800369,11.88,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une tour d’encens dressée au cœur de la Mer de Poussière, construite lors du précédent Fléau de Zhuyin. Elle servait autrefois à purifier l’air environnant et à ralentir l’expansion de la Poussière-corrompue.",
          DialogueId = 70016801,
          Duration = 5,
          GUID = "AF479B6A",
          NextDialogue = 70016802,
          Subtitle = "An Incense Tower that stands within the heart of the Gritblight Expanse. Built during the last occurrence of the Scourge of Zhuyin, it once served to purify the air and slow the advance of Gritblight."
        },
        [70016802] = {
          Camera = "1339.019531,976.865234,1511.71582,0.000001,3.999799,-138.800369,11.88,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Aujourd’hui effondrée au milieu de cette étendue désertique, son état parle de lui-même quant à son destin.",
          DialogueId = 70016802,
          Duration = 5,
          GUID = "AF479B94",
          Subtitle = "Now collapsed into the sands, its condition speaks for itself."
        },
        [70016901] = {
          Camera = "-970.289062,2657.070312,1862.426758,0.000044,17.199194,-63.00082,11.88,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un arbre colossal qui prospérait jadis en ces lieux, mais qui, frappé par le Fléau de Zhuyin, voit désormais son écorce recouverte d’une épaisse couche cristallisée de Poussière-corrompue.",
          DialogueId = 70016901,
          Duration = 5,
          GUID = "AF47ABD2",
          NextDialogue = 70016902,
          Subtitle = "A giant tree that once thrived here, but was ultimately corrupted by the Scourge of Zhuyin. Its bark is now sealed beneath a thick crust of crystallised Gritblight."
        },
        [70016902] = {
          Camera = "-970.289062,2657.070312,1862.426758,0.000044,17.199194,-63.00082,11.88,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Sa vie s’est figée à cet instant précis. Ses branches ne s’étendront plus jamais, offrant par leur silence une mise en garde à tous les êtres vivants : ne vous aventurez pas ici.",
          DialogueId = 70016902,
          Duration = 5,
          GUID = "AF47ABFC",
          Subtitle = "Its life has been frozen in this final moment. Its leaves will never rustle again, offering a silent warning to all living things not to set foot here."
        },
        [70017001] = {
          Camera = "-194.170898,571.792969,277.285156,0.000037,16.40015,-66.80262,15.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un autel autrefois utilisé pour repousser Zhuyin. Sous l’effet de l’énergie qui s’en est échappée, des mirages distordus persistent en ces lieux. Les lamentations et rugissements de Zhuyin s’impriment dans l’esprit de chaque visiteur, tels des douleurs fantomatiques.",
          DialogueId = 70017001,
          Duration = 5,
          GUID = "AF47BC3A",
          Subtitle = "An altar once used to repel Zhuyin. Its runaway energies have left distorted mirages lingering here. Zhuyin's wails and roars echo like a phantom ache in the minds of all who draw near."
        },
        [70017101] = {
          Camera = "233.236328,49.142578,328.026367,0.000006,-47.99913,-169.796097,35.0,404.294037,false,DoNotOverride,2.8",
          ContentFR = "Des notes médicales éparpillées sur un bureau. Le papier, jauni par le temps, porte les traces de nombreuses consultations. Les marges sont couvertes d’annotations serrées, écrites d’une écriture minuscule.\nEn y regardant attentivement, on distingue deux graphies différentes : les plus récentes semblent appartenir à un apprenti en pharmacologie.",
          DialogueId = 70017101,
          Duration = 5,
          GUID = "AF47CCA2",
          NextDialogue = 70017102,
          Subtitle = "Medical notes that lie scattered across the desk. The pages are visibly aged and well-thumbed, with cramped annotations crowding every blank space. A closer look reveals two distinct hands — the newer notes appear to belong to a novice in pharmacology."
        },
        [70017102] = {
          Camera = "233.236328,49.142578,328.026367,0.000006,-47.99913,-169.796097,35.0,404.294037,false,DoNotOverride,2.8",
          ContentFR = "À la fin des notes, un nom est inscrit d’une écriture élégante : « Fufeng ».",
          DialogueId = 70017102,
          Duration = 5,
          GUID = "AF47CCCC",
          Subtitle = "At the end of the notes, the signature \"Fufeng\" is written in an elegant hand."
        },
        [70017201] = {
          Camera = "-86.421875,207.039062,257.314453,0.000016,-39.599575,-81.797188,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un guzheng est disposé à l’extérieur du Pavillon de l’Éphémère, face à la cour.\nIl suffit d’observer cette scène pour imaginer la maîtresse des lieux, un après-midi paisible, jouant quelques notes tandis qu’une brise légère effleure son visage.",
          DialogueId = 70017201,
          Duration = 5,
          GUID = "AF47DD0A",
          Subtitle = "A zheng that stands outdoors in the Hall of Ephemerality's courtyard. One glance at it is enough to evoke the image of its owner playing a quiet melody here on a gentle afternoon, the breeze brushing softly past."
        },
        [70017301] = {
          Camera = "-356.626953,463.605469,232.6875,0.000018,-4.400076,-38.39875,15.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Une armoire à remèdes compartimentée, remplie d’herbes médicinales, qui semble rarement utilisée. Une odeur amère et pénétrante s’en dégage, éveillant instantanément les sens.",
          DialogueId = 70017301,
          Duration = 5,
          GUID = "AF47ED72",
          Subtitle = "A medicine cabinet stocked with herbs divided into neat compartments. It appears rarely used. A sharp, astringent scent rises from within, clearing the mind of anyone who comes near."
        },
        [70017401] = {
          Camera = "-423.304688,2.398438,413.355469,0.000008,-43.799706,9.802094,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un lit de malade destiné au repos des patients, impeccablement propre. Les couvertures sont soigneusement pliées, et une fragrance subtile flotte dans l’air, en parfaite harmonie avec le tempérament de la maîtresse des lieux.",
          DialogueId = 70017401,
          Duration = 5,
          GUID = "AF47FDDA",
          Subtitle = "A spotless sickbed kept ready for any patient in need. The bed is made with meticulous care. A faint, lingering fragrance hangs in the air around it, wholly in keeping with its owner's temperament."
        },
        [70017501] = {
          Camera = "641.003906,-32.821289,236.93042,0.0,-0.200043,179.599518,15.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Un petit autel où les habitants de Huaxu viennent honorer leurs proches disparus et déposer de modestes offrandes.",
          DialogueId = 70017501,
          Duration = 5,
          GUID = "AF480E42",
          NextDialogue = 70017502,
          Subtitle = "This small altar is where the people of Huaxu come to honour lost loved ones and offer simple tributes."
        },
        [70017502] = {
          Camera = "641.003906,-32.821289,236.93042,0.0,-0.200043,179.599518,15.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "À l’abri des regards, des Wishen ont depuis longtemps élu domicile en ces lieux. Quant à ces offrandes chargées de souvenirs et de nostalgie... nous les accepterons en leur nom.",
          DialogueId = 70017502,
          Duration = 5,
          GUID = "AF480E6C",
          Subtitle = "Unseen by them, a group of Wishen have long since taken up residence here, quietly claiming the place as their own. As for this offering, left in remembrance of the departed... we shall accept it in their stead."
        },
        [71000000] = {
          ContentFR = "Miaou...",
          DialogueId = 71000000,
          Duration = 3,
          GUID = "B1BDB580",
          SpeakNpcId = 800002,
          Subtitle = "Meow..."
        },
        [71000100] = {
          ContentFR = "Un chat errant miaule tristement, comme s’il cherchait à attirer l’attention d’une âme charitable.",
          DialogueId = 71000100,
          GUID = "B1BDC5E8",
          SpeakNpcId = 800006,
          Subtitle = "(A stray cat meows forlornly, as if hoping to catch the attention of a kind-hearted passer-by.)"
        },
        [71000200] = {
          ContentFR = "Excusez-moi, vous vendez de la nourriture pour chat ?",
          DialogueId = 71000200,
          GUID = "B1BDD650",
          NextDialogue = 710002001,
          SpeakNpcId = 100001,
          Subtitle = "Hello, do you sell cat food here?"
        },
        [71000210] = {
          ContentFR = "Excusez-moi, vous auriez de la nourriture pour chat ?  ",
          DialogueId = 71000210,
          GUID = "B1BDD7F4",
          NextDialogue = 710002101,
          SpeakNpcId = 100001,
          Subtitle = "Excuse me, do you sell cat food here?"
        },
        [71000220] = {
          ContentFR = "Vous disposez la nourriture devant le chat.",
          DialogueId = 71000220,
          GUID = "B1BDD998",
          NextDialogue = 710002201,
          SpeakNpcId = 100001,
          Subtitle = "(Put down some cat food)"
        },
        [71000300] = {
          ContentFR = "Le chat bondit, s’éloigne de quelques pas, puis s’arrête pour vous regarder, comme s’il vous invitait à le suivre.",
          DialogueId = 71000300,
          Duration = 3,
          GUID = "B1BDE6B8",
          SpeakNpcId = 800006,
          Subtitle = "(The cat bounds away but pauses and glances back at you, as if urging you to follow.)"
        },
        [71000310] = {
          ContentFR = "Le chat bondit, s’éloigne de quelques pas, puis s’arrête pour vous regarder, comme s’il vous invitait à le suivre.",
          DialogueId = 71000310,
          Duration = 3,
          GUID = "B1BDE85C",
          SpeakNpcId = 800006,
          Subtitle = "(The cat bounds away but pauses and glances back at you, as if urging you to follow.)"
        },
        [71000320] = {
          ContentFR = "Le chat bondit, s’éloigne de quelques pas, puis s’arrête pour vous regarder, comme s’il vous invitait à le suivre.",
          DialogueId = 71000320,
          Duration = 3,
          GUID = "B1BDEA00",
          SpeakNpcId = 800006,
          Subtitle = "(The cat bounds away but pauses and glances back at you, as if urging you to follow.)"
        },
        [71000330] = {
          ContentFR = "Le chat tourne joyeusement autour de vos pieds. Son air satisfait réchauffe votre âme et vous emplit d’une étrange sérénité.",
          DialogueId = 71000330,
          GUID = "B1BDEBA4",
          SpeakNpcId = 800006,
          Subtitle = "(The cat circles around your feet, obviously happy and content. A warm sense of peace and joy fills your heart.)"
        },
        [71000501] = {
          ContentFR = "Hé, arrêtez ! Sinon je vais devoir sortir ma botte secrète... Bon, vous l’aurez voulu— À L’AIDE !",
          DialogueId = 71000501,
          Duration = 3,
          GUID = "B1BE07B2",
          SpeakNpcId = 800005,
          Subtitle = "Hey, stop it! Or I'll have to pull out my secret weapon... Alright, you asked for this — HELP! AAHHH!!!"
        },
        [71000502] = {
          ContentFR = "Bouaaah !",
          DialogueId = 71000502,
          Duration = 3,
          GUID = "B1BE07DC",
          SpeakNpcId = 800005,
          Subtitle = "Waaahhh..."
        },
        [71000503] = {
          ContentFR = "Voilà, c’était le dernier.",
          DialogueId = 71000503,
          GUID = "B1BE0806",
          SpeakNpcId = 818014,
          Subtitle = "That was the last of them. All clear."
        },
        [71000504] = {
          ContentFR = "Je vais vérifier si d’autres ennemis rôdent dans le coin. Sois prudent.  ",
          DialogueId = 71000504,
          GUID = "B1BE0830",
          NextDialogue = 71000505,
          SpeakNpcId = 818014,
          Subtitle = "I'll go check if there are any more enemies nearby. Be careful on your own."
        },
        [71000505] = {
          ContentFR = "Reçu, reçu ! Je ferai attention !  ",
          DialogueId = 71000505,
          GUID = "B1BE085A",
          NextDialogue = 71000506,
          SpeakNpcId = 818015,
          Subtitle = "Got it! I'll stay sharp!"
        },
        [71000506] = {
          ContentFR = "Oh, toi aussi tu es venu... <I>Snif...</> Je ne pensais pas qu’autant de monde viendrait m’aider... Voici un petit présent pour vous remercier. Comptez sur moi à l’avenir !  ",
          DialogueId = 71000506,
          GUID = "B1BE0884",
          Scripts = "TurnTo{TurnToDescription{\"818015:n(0)\"}}",
          SpeakNpcId = 818015,
          Subtitle = "Aww, you're here too... *sob*... I can't believe so many people are willing to help me. Here's a little something for your trouble. Thanks, everyone! You guys are the best!"
        },
        [71000511] = {
          Camera = "182.995117,-239.510742,101.057129,0.000077,-2.797147,129.385254,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci ! Me voilà tiré d’affaire... On repart à l’aventure !",
          DialogueId = 71000511,
          GUID = "B1BE0956",
          SpeakNpcId = 800005,
          Subtitle = "Thank you, I'm safe now! On to more adventures!",
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000512] = {
          Camera = "125.800781,-57.036377,76.0,0.000008,0.0,155.202805,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Merci ! Me voilà tiré d’affaire... On repart à l’aventure !",
          DialogueId = 71000512,
          GUID = "B1BE0980",
          SpeakNpcId = 800005,
          Subtitle = "Thank you, I'm safe now! On to more adventures!",
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000601] = {
          ContentFR = "Des tonneaux rejetés par les vagues s’entassent sur la plage. En fouillant, vous pourriez y trouver quelque chose d’utile.",
          DialogueId = 71000601,
          Duration = 3,
          GUID = "B1BE181A",
          SpeakNpcId = 800006,
          Subtitle = "(Barrels washed ashore line the beach. Maybe they hold something useful.)"
        },
        [71000612] = {
          ContentFR = "Le fond de ce tonneau est éventré. Quelles que soient les richesses qu’il contenait autrefois, il n’est plus qu’un débris inutile. Mieux vaut en examiner un autre.",
          DialogueId = 71000612,
          GUID = "B1BE19E8",
          Subtitle = "(This barrel has a gaping hole in the bottom. Whatever treasure it once held is long gone. Better try another.)"
        },
        [71000613] = {
          ContentFR = "Ce tonneau ne renferme rien d’autre que des poissons et des crevettes pourris. Mieux vaut en examiner un autre.",
          DialogueId = 71000613,
          GUID = "B1BE1A12",
          Subtitle = "(Nothing but rotten fish and shrimp in this one. Better try another.)"
        },
        [71000615] = {
          ContentFR = "La persévérance finit par payer : en fouillant avec soin, vous découvrez dans une cache dissimulée quelques ressources encore utilisables.",
          DialogueId = 71000615,
          GUID = "B1BE1A66",
          Subtitle = "(Patience pays off. After a meticulous search, you spot a hidden compartment — and inside, a stash of usable supplies.)"
        },
        [71000701] = {
          ContentFR = "Quelle galère... il ne me restait plus que quelques conduites à vérifier.",
          DialogueId = 71000701,
          Duration = 3,
          GUID = "B1BE2882",
          SpeakNpcId = 800007,
          Subtitle = "Dang it! Just a few more to go, and now this."
        },
        [71000710] = {
          ContentFR = "Que se passe-t-il ?",
          DialogueId = 71000710,
          GUID = "B1BE29FC",
          NextDialogue = 71000711,
          SpeakNpcId = 100001,
          Subtitle = "What happened?"
        },
        [71000711] = {
          ContentFR = "Je dois inspecter les conduites de Phoxichor qui alimentent la cité.",
          DialogueId = 71000711,
          Duration = 3,
          GUID = "B1BE2A26",
          NextDialogue = 71000721,
          SpeakNpcId = 800007,
          Subtitle = "I was checking the condition of the Phoxichor pipes that connect the city."
        },
        [71000721] = {
          ContentFR = "Mais ma corde de sécurité a lâché à la conduite précédente… Peux-tu grimper vérifier les dernières à ma place ?",
          DialogueId = 71000721,
          Duration = 3,
          GUID = "B1BE2BCA",
          NextOptions = {
            [1] = 710007210,
            [2] = 710007211
          },
          SpeakNpcId = 800007,
          Subtitle = "I've only got a few left, but my safety rope just snapped. Could you go check the rest of the pipes for me?"
        },
        [71000741] = {
          ContentFR = "J’ai marqué les conduites restantes, tu me sauves la mise !",
          DialogueId = 71000741,
          Duration = 3,
          GUID = "B1BE2F12",
          SpeakNpcId = 800007,
          Subtitle = "I've marked the remaining pipes for you. I'm counting on you!"
        },
        [71000751] = {
          ContentFR = "Cette conduite n’a aucun dégât. Autant passer à la suivante.",
          DialogueId = 71000751,
          Duration = 2,
          GUID = "B1BE30B6",
          SpeakNpcId = 800006,
          Subtitle = "(This pipe's in good shape. Let's go check the next one.)"
        },
        [71000761] = {
          ContentFR = "La dernière est intacte. Il est temps d’aller prévenir l’ouvrier.",
          DialogueId = 71000761,
          GUID = "B1BE325A",
          SpeakNpcId = 800006,
          Subtitle = "(The last one looks good too. Time to go back and inform the fitter.)"
        },
        [71000771] = {
          ContentFR = "Toutes intactes ? Parfait ! Merci infiniment !",
          DialogueId = 71000771,
          GUID = "B1BE33FE",
          SpeakNpcId = 800007,
          Subtitle = "All good? That's great news! Thank you so much!"
        },
        [71000780] = {
          ContentFR = "Cette conduite présente une légère fissure. Autant en avertir l’ouvrier.",
          DialogueId = 71000780,
          GUID = "B1BE3578",
          SpeakNpcId = 800006,
          Subtitle = "(This pipe has been slightly damaged. Better inform the fitter.)"
        },
        [71000781] = {
          ContentFR = "Pff... encore des heures sup’. Je vais chercher mes outils. Tiens, prends ma clé et va fermer la vanne principale de Phoxichor en attendant.",
          DialogueId = 71000781,
          GUID = "B1BE35A2",
          SpeakNpcId = 800007,
          Subtitle = "Oof... Looks like I'll be working overtime again. Here, take my key and shut off the main Phoxichor valve while I grab my tools."
        },
        [71000782] = {
          ContentFR = "Merci, je prends le relais.",
          DialogueId = 71000782,
          GUID = "B1BE35CC",
          SpeakNpcId = 800007,
          Subtitle = "Thank you. I'll take it from here."
        },
        [71000801] = {
          ContentFR = "{nickname}, {nickname}, vite ! J’ai trouvé un nouveau sujet de recherche !",
          DialogueId = 71000801,
          Duration = 3,
          GUID = "B1BE38EA",
          SpeakNpcId = 800011,
          Subtitle = "Hey, ! Come quick — I've found something amazing! A brand new research subject!"
        },
        [71000802] = {
          ContentFR = "Cette fois, le matériel se trouve de l’autre côté du lac. Tu peux m’aider à le récupérer ?",
          DialogueId = 71000802,
          Duration = 3,
          GUID = "B1BE3914",
          NextOptions = {
            [1] = 710008021,
            [2] = 710008022
          },
          SpeakNpcId = 800011,
          Subtitle = "The material I need is way across the lake. Would you mind helping me grab some?"
        },
        [71000803] = {
          ContentFR = "Voici le matériel que Theo voulait. Je vais le lui rapporter.",
          DialogueId = 71000803,
          Duration = 2,
          GUID = "B1BE393E",
          SpeakNpcId = 100001,
          Subtitle = "This should be what Theo's looking for. Time to bring it back."
        },
        [71000804] = {
          ContentFR = "Merci ! Pour devenir un grand alchimiste, il y a encore tellement de choses à apprendre... mais j’y arriverai !",
          DialogueId = 71000804,
          Duration = 2,
          GUID = "B1BE3968",
          SpeakNpcId = 800011,
          Subtitle = "Thank you! To become a great alchemist, there's still sooo much I've got to learn... But I'll get there!"
        },
        [71000805] = {
          ContentFR = "Ah, je vois ! La première leçon pour devenir un grand alchimiste : trouver ses matériaux par soi-même !",
          DialogueId = 71000805,
          GUID = "B1BE3992",
          SpeakNpcId = 800011,
          Subtitle = "Oh... I see. Well, I guess that's lesson number one for any great alchemist — gather your own materials! Got it!"
        },
        [71000901] = {
          ContentFR = "Cache-cache ! Cache-cache ! Viens jouer avec nous !",
          DialogueId = 71000901,
          Duration = 3,
          GUID = "B1BE4952",
          SpeakNpcId = 800008,
          Subtitle = "Hide and seek! Come and play hide and seek!"
        },
        [71000902] = {
          ContentFR = "Cache-cache ! Cache-cache ! Viens jouer avec nous !",
          DialogueId = 71000902,
          GUID = "B1BE497C",
          NextDialogue = 71000903,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"800008:n(0)\"}},LookAt{LookAtDescription{\"800008:n(0)\"}},PlayAnimation{ActorId{800008},AnimationId{\"Explain02_Start\"},Duration{1}}}",
          SpeakNpcId = 800008,
          Subtitle = "Hide and seek! Come and play hide and seek!",
          TurnTo = {
            [1] = "800009:n(0)",
            [2] = "800010:n(0)"
          }
        },
        [71000903] = {
          ContentFR = "D’accord ! Mais je ne veux pas chercher, je veux me cacher !",
          DialogueId = 71000903,
          Duration = 3,
          GUID = "B1BE49A6",
          NextDialogue = 71000904,
          SpeakNpcId = 800009,
          Subtitle = "I'm in! But I don't want to be the seeker, I want to hide!",
          TalkActionId = {
            [1] = "800009:Explain01_Start"
          }
        },
        [71000904] = {
          ContentFR = "Moi aussi ! J’ai trouvé une super cachette... C’est sûr, cette fois je vais gagner !",
          DialogueId = 71000904,
          Duration = 3,
          GUID = "B1BE49D0",
          NextDialogue = 71000905,
          SpeakNpcId = 800010,
          Subtitle = "Me too! I've found a super secret spot. I'm sure to win this time!",
          TalkActionId = {
            [1] = "800010:Talk03_Start"
          }
        },
        [71000905] = {
          ContentFR = "Mais qui va chercher ? ... Est-ce que quelqu’un veut jouer avec nous ?",
          DialogueId = 71000905,
          Duration = 3,
          GUID = "B1BE49FA",
          NextDialogue = 71000906,
          SpeakNpcId = 800009,
          Subtitle = "But we need a seeker... Anyone else up for a game with us?"
        },
        [71000906] = {
          ContentFR = "Les enfants t’aperçoivent en passant et te fixent, plein d’espoir, attendant ta réponse.",
          DialogueId = 71000906,
          Duration = 3,
          GUID = "B1BE4A24",
          SpeakNpcId = 800006,
          Subtitle = "(The kids notice you passing by, their eyes wide with hope, eagerly waiting for your response.)"
        },
        [71000907] = {
          ContentFR = "Les enfants sautent de joie, puis disparaissent au coin de la rue en un éclair. Il est temps de réfléchir à l’endroit où ils ont bien pu se cacher.",
          DialogueId = 71000907,
          GUID = "B1BE4A4E",
          Subtitle = "(The children cheer excitedly and vanish around the corner in the blink of an eye. Time to find them!)"
        },
        [71000908] = {
          ContentFR = "Ouaaah, déjà trouvée ?",
          DialogueId = 71000908,
          GUID = "B1BE4A78",
          SpeakNpcId = 800008,
          Subtitle = "Wow, that was quick!"
        },
        [71000909] = {
          ContentFR = "Tu es trop {性别:fort|forte} !",
          DialogueId = 71000909,
          Duration = 2,
          GUID = "B1BE4AA2",
          SpeakNpcId = 800009,
          Subtitle = "You're really good at this!"
        },
        [71000910] = {
          ContentFR = "Oh non, j’ai perdu...",
          DialogueId = 71000910,
          Duration = 2,
          GUID = "B1BE4ACC",
          SpeakNpcId = 800010,
          Subtitle = "Ugh, can't believe I lost..."
        },
        [71000911] = {
          ContentFR = "Bon d’accord, j’ai perdu, c’est le jeu... Tiens, voilà ta récompense. La prochaine fois, tu joues encore avec nous, promis ?",
          DialogueId = 71000911,
          Duration = 2,
          GUID = "B1BE4AF6",
          SpeakNpcId = 800008,
          Subtitle = "Alright, you win. Here's your prize. Come play with us again sometime!"
        },
        [71001001] = {
          ContentFR = "Une voiture flambant neuve est là, abandonnée. Serait-ce... une occasion en or ?",
          DialogueId = 71001001,
          Duration = 3,
          GUID = "B1BE59BA",
          SpeakNpcId = 800006,
          Subtitle = "(A brand-new vehicle sits unattended. Could this be... a golden opportunity?)"
        },
        [71001002] = {
          ContentFR = "Le réservoir de Phoxichor est rempli à ras bord... Voilà bien une aubaine !",
          DialogueId = 71001002,
          GUID = "B1BE59E4",
          SpeakNpcId = 800006,
          Subtitle = "(The car's got a full canister of Phoxichor — jackpot!)"
        },
        [71001003] = {
          ContentFR = "Hé ! Que fais-tu ?! Vite, du renfort !",
          DialogueId = 71001003,
          Duration = 2,
          GUID = "B1BE5A0E",
          SpeakNpcId = 818010,
          Subtitle = "What do you think you're doing!? Guys, I need support!"
        },
        [71001004] = {
          ContentFR = "Plus personne ne peut t’arrêter. Tu ouvres la portière, récupères le réservoir de Phoxichor et pars avec un joli pactole. Tout se déroule comme prévu... quelle journée agréable !",
          DialogueId = 71001004,
          Duration = 4,
          GUID = "B1BE5A38",
          SpeakNpcId = 800006,
          Subtitle = "(With no one left to stop you, you pry open the door, grab the Phoxichor Canister, and walk away with a small fortune. Everything's going smooth. What a lucky day.)"
        },
        [71001005] = {
          ContentFR = "Finalement, ta conscience l’emporte. Tu décides de signaler aux gardes de la porte de la cité la faille de sécurité.",
          DialogueId = 71001005,
          Duration = 3,
          GUID = "B1BE5A62",
          SpeakNpcId = 800006,
          Subtitle = "(Your better angels prevail. You decide to report the security lapse to the guards at the city gate.)"
        },
        [71001006] = {
          ContentFR = "Merci de nous avoir prévenus. Nous allons renforcer les patrouilles immédiatement. Accepte ce petit cadeau comme gage de notre gratitude.",
          DialogueId = 71001006,
          GUID = "B1BE5A8C",
          SpeakNpcId = 818010,
          Subtitle = "Thank you for bringing this to our attention. I'll send more patrols right away. Please accept this small gift as a gesture of gratitude from us."
        },
        [71001101] = {
          ContentFR = "Des Souillés arrivent ! Repousse-les !",
          DialogueId = 71001101,
          Duration = 3,
          GUID = "B1BE6A22",
          SpeakNpcId = 800006,
          Subtitle = "(Filthoids incoming! Dispel them!)"
        },
        [71001201] = {
          ContentFR = "Les mauvaises herbes ont recouvert les traces que toi et Berry aviez laissées ici. Il serait peut-être temps de dégager les alentours de la statue.",
          DialogueId = 71001201,
          Duration = 2,
          GUID = "B1BE7A8A",
          SpeakNpcId = 800006,
          Subtitle = "(Overgrown weeds have swallowed the traces of the memories you once shared here with Berry. Perhaps it's time to clear the shrine's surroundings.)"
        },
        [71001202] = {
          ContentFR = "Grâce à tes efforts, la statue retrouve sa pureté, telle qu’elle apparaît encore dans ta mémoire.",
          DialogueId = 71001202,
          GUID = "B1BE7AB4",
          SpeakNpcId = 800006,
          Subtitle = "(The weeds are gone. The shrine stands pristine once more — just as you remember it.)"
        },
        [71001301] = {
          ContentFR = "D’après Berry, c’est ici que nous vivions autrefois... mais je n’ai aucun souvenir.",
          DialogueId = 71001301,
          GUID = "B1BE8AF2",
          NextDialogue = 71001302,
          SpeakNpcId = 100001,
          Subtitle = "Berry said this is where we used to live, but I can't remember a thing..."
        },
        [71001302] = {
          ContentFR = "Je devrais peut-être explorer un peu les environs. Avec un peu de chance, quelque chose me reviendra.",
          DialogueId = 71001302,
          GUID = "B1BE8B1C",
          SpeakNpcId = 100001,
          Subtitle = "Maybe if I look around, something will jog my memory."
        },
        [71001303] = {
          ContentFR = "Le mobilier est très rudimentaire. De nombreux clous ont été enfoncés profondément dans le bois, exactement comme les poignées des portes de notre village. Berry devait déjà avoir une sacrée force, même enfant.",
          DialogueId = 71001303,
          GUID = "B1BE8B46",
          Subtitle = "The furniture looks pretty rough — lots of nails hammered deep into the wood, just like the door handles back in the village. Berry must have been incredibly strong even as a kid."
        },
        [71001304] = {
          ContentFR = "Tiens... un livre d’histoires sur l’alchimie ? Alors, tous ces drôles de contes qu’elle me racontait avant de dormir venaient de là.",
          DialogueId = 71001304,
          GUID = "B1BE8B70",
          NextDialogue = 71001305,
          Subtitle = "Wait, is this... an alchemy storybook? So all those weird bedtime stories Berry told me when we were little came from this."
        },
        [71001305] = {
          ContentFR = "Mais ces annotations dans les marges sont bien plus soignées que l’écriture de Berry. Qui a bien pu les rédiger ?",
          DialogueId = 71001305,
          GUID = "B1BE8B9A",
          Subtitle = "But these notes in the margins are much neater than Berry's handwriting. Who could've written them?"
        },
        [71001306] = {
          ContentFR = "Je me rappelle plein de choses sur Berry... mais de cet endroit, rien ne me revient.",
          DialogueId = 71001306,
          GUID = "B1BE8BC4",
          NextDialogue = 71001307,
          SpeakNpcId = 100001,
          Subtitle = "Mm, I'm recalling a lot about Berry, but still nothing about this place."
        },
        [71001307] = {
          ContentFR = "Tant pis. Peut-être qu’un jour, ça reviendra tout seul.",
          DialogueId = 71001307,
          GUID = "B1BE8BEE",
          SpeakNpcId = 100001,
          Subtitle = "Never mind. Maybe it'll come back to me someday."
        },
        [71001401] = {
          ContentFR = "L’odeur des Baies boréales te parvient de loin. Si tu en cueilles quelques-unes, tu pourrais les vendre à bon prix.",
          DialogueId = 71001401,
          Duration = 4,
          GUID = "B1BE9B5A",
          SpeakNpcId = 800006,
          Subtitle = "(You catch the fragrant aroma of Borealberries from afar. If you pick some, you could make a small fortune.)"
        },
        [71001402] = {
          ContentFR = "Ces Baies boréales sont éclatantes et bien charnues. Nul doute que ces spécialités se vendront facilement.",
          DialogueId = 71001402,
          Duration = 4,
          GUID = "B1BE9B84",
          SpeakNpcId = 800006,
          Subtitle = "(These Borealberries are vibrant and plump. It's clear these seasonal delights will fetch a good price anywhere.)"
        },
        [71001403] = {
          ContentFR = "Deux autres marchands s’activent au loin, cherchant eux aussi à acheter des Baies boréales. Peut-être vaut-il mieux parler à chacun avant de décider à qui vendre.",
          DialogueId = 71001403,
          Duration = 4,
          GUID = "B1BE9BAE",
          SpeakNpcId = 800006,
          Subtitle = "(You notice two traders nearby looking to buy Borealberries. Maybe it's worth talking to them both before deciding who to sell to.)"
        },
        [71001404] = {
          ContentFR = "Mon étal est à Givrelac depuis des années. Les profits sont modestes, mais tous mes clients sont des habitués. Je prends toute ta récolte, ça fera notre affaire, et on pourra se rendre service à l’avenir.",
          DialogueId = 71001404,
          GUID = "B1BE9BD8",
          NextOptions = {
            [1] = 710014041,
            [2] = 710014042
          },
          SpeakNpcId = 818002,
          Subtitle = "I've been running this little stall in Icelake for years. Just a small business — it makes more friends than money. I mean, we can look out for each other in this city, am I right?"
        },
        [71001405] = {
          ContentFR = "Hé, je vois tes Baies boréales. Je peux payer bien plus que les marchands locaux radins. On fait une belle affaire ensemble ?",
          DialogueId = 71001405,
          GUID = "B1BE9C02",
          NextOptions = {
            [1] = 710014051,
            [2] = 710014052
          },
          SpeakNpcId = 818003,
          Subtitle = "Hey there, I see you've got some Borealberries. I can pay way more than those penny-pinching local traders. How about we make some serious cash together, huh?"
        },
        [71001406] = {
          ContentFR = "Même si le profit est moindre, tu privilégies les relations durables et conclus l’affaire avec le marchand local.",
          DialogueId = 71001406,
          Duration = 3,
          GUID = "B1BE9C2C",
          SpeakNpcId = 800006,
          Subtitle = "(Prioritising long-term connections, you make the deal with the local trader despite the lower profit.)"
        },
        [71001407] = {
          ContentFR = "Les promesses d’avenir sont moins fiables que les gains immédiats. Tu conclus donc l’affaire avec le marchand extérieur et empoches une belle somme.",
          DialogueId = 71001407,
          Duration = 4,
          GUID = "B1BE9C56",
          SpeakNpcId = 800006,
          Subtitle = "(Promises of future benefits aren't as reliable as immediate gains. You make the deal with the out-of-town trader and walk away with a hefty sum.)"
        },
        [71001501] = {
          ContentFR = "Pff... cette vieille machine est encore en panne...",
          DialogueId = 71001501,
          Duration = 3,
          GUID = "B1BEABC2",
          SpeakNpcId = 818006,
          Subtitle = "Ugh... not this again."
        },
        [71001502] = {
          ContentFR = "Que se passe-t-il ?",
          DialogueId = 71001502,
          GUID = "B1BEABEC",
          NextDialogue = 71001503,
          SpeakNpcId = 100001,
          Subtitle = "What happened?"
        },
        [71001503] = {
          ContentFR = "Je n’arrive jamais à la faire marcher. Essaie donc, pour voir si c’est la machine ou moi le problème.",
          DialogueId = 71001503,
          GUID = "B1BEAC16",
          SpeakNpcId = 818006,
          Subtitle = "I can't seem to get this machine working properly. Why don't you give it a try? Let's see if it's the machine or just me."
        },
        [71001504] = {
          ContentFR = "Merci.",
          DialogueId = 71001504,
          Duration = 2,
          GUID = "B1BEAC40",
          SpeakNpcId = 818006,
          Subtitle = "Thank you."
        },
        [71001505] = {
          ContentFR = "Pas mal ! <I>Hum...</> alors c’est moi le problème...",
          DialogueId = 71001505,
          GUID = "B1BEAC6A",
          SpeakNpcId = 818006,
          Subtitle = "Impressive! Looks like I'm the problem then..."
        },
        [71001506] = {
          ContentFR = "Hein... ça a marché ?",
          DialogueId = 71001506,
          Duration = 2,
          GUID = "B1BEAC94",
          SpeakNpcId = 818006,
          Subtitle = "That actually worked?"
        },
        [71001507] = {
          ContentFR = "Euh... ça va vraiment marcher juste en tapant ?",
          DialogueId = 71001507,
          Duration = 2,
          GUID = "B1BEACBE",
          SpeakNpcId = 818006,
          Subtitle = "Um... are you sure a smack would work?"
        },
        [71001508] = {
          ContentFR = "Hé, attends... il n’y a pas un morceau qui vient de s’envoler là ?",
          DialogueId = 71001508,
          Duration = 2,
          GUID = "B1BEACE8",
          SpeakNpcId = 818006,
          Subtitle = "Wait, did a part just fly off?"
        },
        [71001509] = {
          ContentFR = "Incroyable... ça a vraiment marché !",
          DialogueId = 71001509,
          GUID = "B1BEAD12",
          SpeakNpcId = 818006,
          Subtitle = "Wow, you've got the magic touch!"
        },
        [71001601] = {
          ContentFR = "Tant de Souillés... que vais-je faire... ?",
          DialogueId = 71001601,
          Duration = 3,
          GUID = "B1BEBC2A",
          SpeakNpcId = 818004,
          Subtitle = "So many Filthoids... What am I going to do...?"
        },
        [71001602] = {
          ContentFR = "Que se passe-t-il ?",
          DialogueId = 71001602,
          GUID = "B1BEBC54",
          NextDialogue = 71001603,
          SpeakNpcId = 100001,
          Subtitle = "What's wrong?"
        },
        [71001603] = {
          ContentFR = "Ouah, avec ton équipement, tu dois être un {性别:Chasseur de Phoxène|Chasseuse de Phoxène} vraiment redoutable, non ? En fait... je suis aussi une Chasseuse de Phoxène, mais je suis beaucoup trop faible...",
          DialogueId = 71001603,
          GUID = "B1BEBC7E",
          NextDialogue = 71001604,
          SpeakNpcId = 818004,
          Subtitle = "Wow, judging by your gear, you must be a really skilled Phoxhunter, right? Actually... I'm a Phoxhunter myself, but I'm not very strong..."
        },
        [71001604] = {
          ContentFR = "Tu pourrais m’aider à récupérer mon arme au milieu de ces Souillés ? Sinon, je ne pourrai même pas accepter ma prochaine mission...",
          DialogueId = 71001604,
          GUID = "B1BEBCA8",
          NextDialogue = 71001605,
          SpeakNpcId = 818004,
          Subtitle = "Could you help me retrieve my weapon from those Filthoids? If I don't get it back, I won't be able to take on my next commission..."
        },
        [71001605] = {
          ContentFR = "<I>... Je vais t’aider.</>",
          DialogueId = 71001605,
          GUID = "B1BEBCD2",
          NextDialogue = 71001606,
          SpeakNpcId = 100001,
          Subtitle = "...Sure, I'll help you out."
        },
        [71001606] = {
          ContentFR = "Merci infiniment !",
          DialogueId = 71001606,
          GUID = "B1BEBCFC",
          SpeakNpcId = 818004,
          Subtitle = "Thank you so much!"
        },
        [71001607] = {
          ContentFR = "Les Souillés sont juste devant. Fais attention.",
          DialogueId = 71001607,
          Duration = 3,
          GUID = "B1BEBD26",
          SpeakNpcId = 818004,
          Subtitle = "They're just up ahead. Be careful!"
        },
        [71001608] = {
          ContentFR = "<I>Snif...</> si je ne peux pas la récupérer, que vais-je devenir ? Je n’ai presque rien mangé depuis plusieurs jours...",
          DialogueId = 71001608,
          GUID = "B1BEBD50",
          NextOptions = {
            [1] = 710016081,
            [2] = 710016082
          },
          SpeakNpcId = 818004,
          Subtitle = "*sob* If I can't take it back, how am I supposed to make a living...? I haven't had a proper meal in days..."
        },
        [71001609] = {
          ContentFR = "Merci ! Je file faire ma mission. À bientôt !",
          DialogueId = 71001609,
          GUID = "B1BEBD7A",
          SpeakNpcId = 818004,
          Subtitle = "Thank you! I'm off to my next commission. Take care!"
        },
        [71001610] = {
          ContentFR = "Je sais tout. Tu es sûr que c’est une bonne idée de rendre son arme à cette jeune Chasseuse de Phoxène ? Avec sa force, elle pourrait mourir lors de sa prochaine mission. Au lieu de cela, pourquoi ne pas me vendre son arme ? Ce serait plus sûr pour tout le monde.",
          DialogueId = 71001610,
          GUID = "B1BEBDA4",
          NextOptions = {
            [1] = 710016101,
            [2] = 710016102
          },
          SpeakNpcId = 818005,
          Subtitle = "I know the whole story. Are you sure it's a good idea to give her the weapon back? With her strength, she might just die on her next commission. So, why not sell the weapon to me? It's the safer option for everyone."
        },
        [71001611] = {
          ContentFR = "Une excellente transaction ! J’espère que nous ferons encore des affaires ensemble.",
          DialogueId = 71001611,
          GUID = "B1BEBDCE",
          SpeakNpcId = 818005,
          Subtitle = "Thank you! Looking forward to our next deal!"
        },
        [71001701] = {
          ContentFR = "Eh, mais c’est {nickname} ! Viens vite !",
          DialogueId = 71001701,
          GUID = "B1BECC92",
          SpeakNpcId = 818012,
          Subtitle = "Oh, hey! Isn't that ? Come here!"
        },
        [71001702] = {
          ContentFR = "<I>Hum, </>j’ai des recherches importantes à faire ici. Protège-moi pendant que je bosse, d’accord ?",
          DialogueId = 71001702,
          GUID = "B1BECCBC",
          NextOptions = {
            [1] = 710017021,
            [2] = 710017022
          },
          SpeakNpcId = 818012,
          Subtitle = "I've got some serious research to do here. Can you protect me while I work?"
        },
        [71001703] = {
          ContentFR = "Pourquoi est-ce que des gêneurs apparaissent toujours quand je suis en pleine étude ? À toi de jouer ! Je suis sur le point de faire une découverte cruciale.",
          DialogueId = 71001703,
          GUID = "B1BECCE6",
          SpeakNpcId = 818012,
          Subtitle = "Why do baddies always show up when I'm in the middle of research? I'm counting on you! I'm just getting to the bottom of it."
        },
        [71001704] = {
          ContentFR = "Alors, ici comme ça... et là... Hmm... Oui, presque... Encore un peu de patience !",
          DialogueId = 71001704,
          GUID = "B1BECD10",
          SpeakNpcId = 818012,
          Subtitle = "Let's see... Hmm... Huh... Almost there! Hang in there!"
        },
        [71001705] = {
          ContentFR = "Parfait, c’est ça ! Recherche terminée ! Youpi !",
          DialogueId = 71001705,
          GUID = "B1BECD3A",
          SpeakNpcId = 818012,
          Subtitle = "That's a wrap! Research successfully complete! Hooray!"
        },
        [71001706] = {
          ContentFR = "Heureusement que tu étais là. Mon expédition est un vrai succès grâce à toi. Tiens, un petit cadeau en remerciement. La prochaine fois, je compte encore sur toi !",
          DialogueId = 71001706,
          GUID = "B1BECD64",
          SpeakNpcId = 818012,
          Subtitle = "I couldn't have done it without you! Here's a little something for your trouble~ Let's team up again next time!"
        },
        [71001707] = {
          ContentFR = "Oh... si tu ne restes pas avec moi, je ferais mieux de vite partir. Cet endroit me file un peu la chair de poule...",
          DialogueId = 71001707,
          GUID = "B1BECD8E",
          SpeakNpcId = 818012,
          Subtitle = "Oh... Well, if you won't stick around, I'd better leave. This place gives me the creeps..."
        },
        [71001801] = {
          ContentFR = "Allez, monsieur, tout va bien ! Vous exagérez.",
          DialogueId = 71001801,
          GUID = "B1BEDCFA",
          NextDialogue = 71001802,
          SpeakNpcId = 818059,
          Subtitle = "Come on, sir — it's not that deep. You're reading too much into it."
        },
        [71001802] = {
          ContentFR = "Exagérer ? Vous ne voyez donc pas le danger qui rôde dans l’ombre ? Confier Givrelac à votre génération, c’est la condamner !",
          DialogueId = 71001802,
          GUID = "B1BEDD24",
          SpeakNpcId = 818009,
          Subtitle = "Reading too much? You lot can't see the danger crawling right under your noses! Icelake's done for with your lot in charge!"
        },
        [71001803] = {
          ContentFR = "Calmez-vous, monsieur. Je peux vous aider d’une façon ou d’une autre ?",
          DialogueId = 71001803,
          GUID = "B1BEDD4E",
          NextDialogue = 71001804,
          SpeakNpcId = 100001,
          Subtitle = "Easy, sir. Is there something I can help you with?"
        },
        [71001804] = {
          ContentFR = "Les vauriens pullulent partout dans Givrelac... ah, vraiment, chaque génération vaut moins que la précédente !",
          DialogueId = 71001804,
          GUID = "B1BEDD78",
          NextDialogue = 71001805,
          SpeakNpcId = 818009,
          Subtitle = "Criminals — swarming out of the cracks, I tell you! Tch — kids these days, all spineless!"
        },
        [71001805] = {
          ContentFR = "Puisque le Bureau de la Sécurité préfère flemmarder, je vais m’en occuper moi-même ! Et toi, {性别:gamin|gamine}, tu as l’air volontaire, viens donc me prêter main-forte !",
          DialogueId = 71001805,
          GUID = "B1BEDDA2",
          SpeakNpcId = 818009,
          Subtitle = "If the lazy pups at the Security Bureau won't act, then I will! And you — {性别:lad|lass} — you look sharp. Feel like lending an old soldier a hand?"
        },
        [71001806] = {
          ContentFR = "Hmpf...",
          DialogueId = 71001806,
          GUID = "B1BEDDCC",
          SpeakNpcId = 818009,
          Subtitle = "Hmph..."
        },
        [71001807] = {
          ContentFR = "Pff...",
          DialogueId = 71001807,
          GUID = "B1BEDDF6",
          SpeakNpcId = 818009,
          Subtitle = "Tch..."
        },
        [71001808] = {
          ContentFR = "Pff... bien cachés cette fois, hein ? Mais je n’abandonnerai pas ! Vous, les déchets, vous ne perdez rien pour attendre...",
          DialogueId = 71001808,
          GUID = "B1BEDE20",
          SpeakNpcId = 818009,
          Subtitle = "Hmph, sneaky little devils... But I'm not done. This city needs justice — and I won't stop till it gets it. You lot better watch your backs..."
        },
        [71001809] = {
          ContentFR = "À l’attaque !",
          DialogueId = 71001809,
          GUID = "B1BEDE4A",
          NextDialogue = 71001810,
          SpeakNpcId = 818011,
          Subtitle = "Now!"
        },
        [71001810] = {
          ContentFR = "Ah ! Les rats sortent de leur trou ! Tu vois ? Givrelac n’a jamais été sûr ! Ces vieux os vont vous rappeler ce qu’est la justice !",
          DialogueId = 71001810,
          GUID = "B1BEDE74",
          NextDialogue = 71001813,
          SpeakNpcId = 818009,
          Subtitle = "Ha! The rats are out of hiding! Told you — Icelake's never been safe! Time for these old bones to dish out some justice!"
        },
        [71001811] = {
          ContentFR = "Merci, {性别:gamin|gamine}. La sécurité de Givrelac ne repose plus que sur toi et moi désormais.",
          DialogueId = 71001811,
          GUID = "B1BEDE9E",
          SpeakNpcId = 818009,
          Subtitle = "You did good, kid. The safety of Icelake rests on shoulders like ours."
        },
        [71001812] = {
          ContentFR = "Pff ! Je n’attendais rien de personne de toute façon. Va-t’en.",
          DialogueId = 71001812,
          GUID = "B1BEDEC8",
          SpeakNpcId = 818009,
          Subtitle = "Hmph. Figures. Should've known better than to count on anyone. Off with you, then."
        },
        [71001813] = {
          ContentFR = "Avant même que tu réagisses, le vieil homme fonce droit sur eux. Tu ferais mieux de le suivre avant que cela tourne au bain de sang.",
          DialogueId = 71001813,
          GUID = "B1BEDE75",
          SpeakNpcId = 800006,
          Subtitle = "(Before you can stop him, the old man charges straight in. You'd better follow — before this turns into a bloodbath.)"
        },
        [71001901] = {
          ContentFR = "Alors... est-ce que ça change vraiment quelque chose ou pas ?",
          DialogueId = 71001901,
          GUID = "B1BEED62",
          SpeakNpcId = 818016,
          Subtitle = "Hmm... I wonder if that tweak actually made any difference..."
        },
        [71001902] = {
          ContentFR = "Ah, tu tombes bien ! Je viens de bricoler l’ascenseur. Tu pourrais l’essayer et me dire si tu le trouves plus rapide ? J’ai tellement fait d’allers-retours que je n’arrive plus à sentir la différence.",
          DialogueId = 71001902,
          GUID = "B1BEED8C",
          SpeakNpcId = 818016,
          Subtitle = "Ah — good timing. I just finished adjusting the lift again. Could you give it a quick ride and tell me if it feels any faster? I've been up and down so many times I honestly can't tell anymore."
        },
        [71001903] = {
          ContentFR = "C’est allé si vite ? Hein... peut-être que j’ai raté quelque chose. On dirait que je vais devoir refaire un diagnostic complet. Merci de m’avoir aidé avec les données, tiens, prends ça pour la peine.",
          DialogueId = 71001903,
          GUID = "B1BEEDB6",
          SpeakNpcId = 818016,
          Subtitle = "It went that fast? Huh... maybe I missed something. Looks like I'll have to do a full diagnostic again. Thanks for helping with the data — here, take this for your trouble."
        },
        [71001904] = {
          ContentFR = "Franchement, je n’ai pas senti de différence.",
          DialogueId = 71001904,
          GUID = "B1BEEDE0",
          NextDialogue = 71001905,
          SpeakNpcId = 100001,
          Subtitle = "Didn't really feel any different."
        },
        [71001905] = {
          ContentFR = "Je m’en doutais... À force de régler encore et encore, c’est juste pour me rassurer moi-même. Merci pour les données quand même, tiens, prends ça.",
          DialogueId = 71001905,
          GUID = "B1BEEE0A",
          SpeakNpcId = 818016,
          Subtitle = "Yeah... figures. Maybe I'm just tweaking it for peace of mind at this point. Still — appreciate the feedback. Here, something for your time."
        },
        [71002001] = {
          ContentFR = "Jerry, où es-tu encore passé... ? <I>snif snif</>",
          DialogueId = 71002001,
          GUID = "B1BEFDCA",
          SpeakNpcId = 818017,
          Subtitle = "Jerry! Where did you run off to again...? *sniffles*"
        },
        [71002002] = {
          ContentFR = "Peux-tu m’aider à retrouver mon <H>chat</> ? Il devrait être dans les parages...",
          DialogueId = 71002002,
          GUID = "B1BEFDF4",
          SpeakNpcId = 818017,
          Subtitle = "Could you help me look for my cat? He should still be around here somewhere..."
        },
        [71002003] = {
          ContentFR = "Tu finis par apercevoir un petit chat recroquevillé au sol, tremblant de peur et refusant tout contact humain.",
          DialogueId = 71002003,
          GUID = "B1BEFE1E",
          SpeakNpcId = 800006,
          Subtitle = "(You soon spot a small cat curled up on the ground, trembling. He looks terrified of human contact.)"
        },
        [71002004] = {
          ContentFR = "Te voilà enfin, Jerry ! Merci, merci infiniment !",
          DialogueId = 71002004,
          GUID = "B1BEFE48",
          NextDialogue = 71002005,
          SpeakNpcId = 818018,
          Subtitle = "Oh, Jerry, there you are! Thank you so much!"
        },
        [71002005] = {
          ContentFR = "La jeune fille serre Jerry contre elle et l’inonde de baisers. Tu feins d’ignorer le pauvre animal qui se débat de terreur, acceptes ta récompense et t’éclipses.",
          DialogueId = 71002005,
          GUID = "B1BEFE72",
          SpeakNpcId = 800006,
          Subtitle = "(The girl scoops Jerry into her arms and buries him in kisses. You try not to notice the poor thing wriggling in panic as you quietly accept your reward and slip away.)"
        },
        [71002006] = {
          ContentFR = "Toi non plus tu ne l’as pas trouvé... ? Tant pis ! Ce chat errant qui court partout ne peut pas être mon Jerry. Je dirai à maman de m’acheter un autre chat, plus sage et plus mignon !",
          DialogueId = 71002006,
          GUID = "B1BEFE9C",
          SpeakNpcId = 818018,
          Subtitle = "You couldn't find him either...? Tch, whatever. I don't want a scruffy stray to be my Jerry anyway. I'll just have Mum get me a better cat — even cuter and well-behaved!"
        },
        [71002007] = {
          ContentFR = "Merci ! Jerry... mon petit Jerry...",
          DialogueId = 71002007,
          GUID = "B1BEFEC6",
          SpeakNpcId = 818017,
          Subtitle = "Thank you! Oh, Jerry... please be okay..."
        },
        [71002101] = {
          ContentFR = "Ah, {nickname} ! {性别:Mon sauveur|Ma sauveuse}, viens vite m’aider !",
          DialogueId = 71002101,
          GUID = "B1BF0E32",
          SpeakNpcId = 818007,
          Subtitle = "! Thank goodness you're here! I need your help!"
        },
        [71002102] = {
          ContentFR = "Je dois livrer cette caisse de matériel à mes collègues de l’autre côté du Lac du Deuil, mais j’ai soudain une affreuse douleur au ventre. Peux-tu la livrer à ma place ? Je t’en supplie !",
          DialogueId = 71002102,
          GUID = "B1BF0E5C",
          SpeakNpcId = 818007,
          Subtitle = "I was supposed to deliver this crate of supplies to my colleagues across the Lamenting Lake, but I've suddenly got this terrible stomachache. Could you deliver it for me? Please, I'm begging you!"
        },
        [71002103] = {
          ContentFR = "Bonjour, voici les fournitures que Kevin m’a chargé de vous remettre.",
          DialogueId = 71002103,
          GUID = "B1BF0E86",
          NextDialogue = 71002104,
          SpeakNpcId = 100001,
          Subtitle = "Hello, Kevin asked me to bring these supplies to you."
        },
        [71002104] = {
          ContentFR = "Minute... il manque deux chargeurs et un fusil. Avoue, tu les as pris !",
          DialogueId = 71002104,
          GUID = "B1BF0EB0",
          SpeakNpcId = 818008,
          Subtitle = "Wait a minute... The crate is missing two clips and a rifle. You took them, didn't you?"
        },
        [71002105] = {
          ContentFR = "Le détournement de matériel impérial est une grave infraction ! Tu viens avec moi !",
          DialogueId = 71002105,
          GUID = "B1BF0EDA",
          SpeakNpcId = 818008,
          Subtitle = "Embezzling imperial property is a serious offence. You're coming with me!"
        },
        [71002106] = {
          ContentFR = "Hein ? J’étais aux toilettes une minute, et vous êtes déjà en train de vous battre !",
          DialogueId = 71002106,
          GUID = "B1BF0F04",
          NextDialogue = 71002107,
          SpeakNpcId = 818007,
          Subtitle = "Whoa! I was in the bathroom for a minute, and you're already at each other's throats!"
        },
        [71002107] = {
          ContentFR = "C’est eux qui ont commencé.",
          DialogueId = 71002107,
          GUID = "B1BF0F2E",
          NextDialogue = 71002108,
          SpeakNpcId = 100001,
          Subtitle = "They started it."
        },
        [71002108] = {
          ContentFR = "Regarde ce que {性别:ce vaurien|cette vaurienne} a fait, {性别:il|elle} a même eu le culot de voler des fournitures de la légion !",
          DialogueId = 71002108,
          GUID = "B1BF0F58",
          NextDialogue = 71002109,
          SpeakNpcId = 818008,
          Subtitle = "Look what this crook did — even had the nerve to steal legion supplies!"
        },
        [71002109] = {
          ContentFR = "Hein ? Oh ! Deux chargeurs et un fusil ? C’est moi, je les avais déjà pris pour ma part.",
          DialogueId = 71002109,
          GUID = "B1BF0F82",
          NextDialogue = 71002110,
          SpeakNpcId = 818007,
          Subtitle = "Huh? Oh, you mean two clips and a rifle? That's on me. I already took my share earlier."
        },
        [71002110] = {
          ContentFR = "Tu n’es pas sérieux... Remettre des fournitures de la Légion au premier venu ? Et si c’était {性别:un|une} Déchu ?!",
          DialogueId = 71002110,
          GUID = "B1BF0FAC",
          NextDialogue = 71002111,
          SpeakNpcId = 818008,
