        [71002202] = {
          ContentFR = "Le patron a encore eu une de ses idées géniales : « Que les plats du restaurant de la Paix d’Argent arrivent dans chaque foyer ! » Comme si nous, les pauvres livreurs, on allait se transformer en héros à sa place...",
          DialogueId = 71002202,
          GUID = "B1BF1EC4",
          NextDialogue = 71002203,
          SpeakNpcId = 818019,
          Subtitle = "The boss and his \"brilliant\" ideas again. \"Bringing Silverpeace flavours to every household,\" he says. Did he ever stop to think about us poor delivery grunts!?"
        },
        [71002203] = {
          ContentFR = "Besoin d’un coup de main ?",
          DialogueId = 71002203,
          GUID = "B1BF1EEE",
          NextDialogue = 71002204,
          SpeakNpcId = 100001,
          Subtitle = "Need a hand?"
        },
        [71002204] = {
          ContentFR = "Absolument ! Si quelqu’un pouvait bosser à ma place, et sans rien demander en retour, ce serait le rêve ! Mais bon... on sait tous que ça n’arrive jamais...",
          DialogueId = 71002204,
          GUID = "B1BF1F18",
          NextDialogue = 71002205,
          SpeakNpcId = 818019,
          Subtitle = "Desperately! Ideally, someone to cover my shift — for free. But hey, when does that ever happen?"
        },
        [71002205] = {
          ContentFR = "Bon, si tu veux vraiment m’aider, prends juste quelques plats. Je ne pourrai que te remercier... et te laisser boire autant d’eau que tu veux au Lac du Deuil !",
          DialogueId = 71002205,
          GUID = "B1BF1F42",
          SpeakNpcId = 818019,
          Subtitle = "If you're really up for it, mind carrying a few things for me? I can't pay you, but hey, I'll treat you to all the water you can drink by Lamenting Lake."
        },
        [71002206] = {
          ContentFR = "Hé ! Regardez ce qu’on a là, quelqu’un qui transporte un festin. On va se régaler aujourd’hui, les gars !",
          DialogueId = 71002206,
          GUID = "B1BF1F6C",
          NextDialogue = 71002207,
          SpeakNpcId = 818057,
          Subtitle = "Oi! Look what we've got here — someone carrying a feast. Lucky day, boys!"
        },
        [71002207] = {
          ContentFR = "Pas touche ! Ces plats sont pour les clients ! S’ils ne reçoivent pas leur nourriture, toute ma journée de salaire s’envole !",
          DialogueId = 71002207,
          GUID = "B1BF1F96",
          NextDialogue = 71002208,
          SpeakNpcId = 818019,
          Subtitle = "No! These are for customers! If they don't get their food, my whole day's pay goes poof!"
        },
        [71002208] = {
          ContentFR = "On s’en fiche, file-les nous !",
          DialogueId = 71002208,
          GUID = "B1BF1F97",
          NextDialogue = 71002209,
          SpeakNpcId = 818057,
          Subtitle = "Not our problem. Now hand it over."
        },
        [71002209] = {
          ContentFR = "Arrêtez !",
          DialogueId = 71002209,
          GUID = "B1BF1F98",
          SpeakNpcId = 100001,
          Subtitle = "Back off."
        },
        [71002210] = {
          ContentFR = "Ouf... la soupe n’a pas coulé ! Allez, on continue la livraison avant que ça parte en vrille...",
          DialogueId = 71002210,
          GUID = "B1BF1FC0",
          SpeakNpcId = 818019,
          Subtitle = "Whew... thank goodness the soup didn't spill. C'mon, let's finish this delivery before anything else goes wrong..."
        },
        [71002211] = {
          ContentFR = "Allez, presque fini... plus qu’une dernière livraison ! Sérieusement, le patron pourrait se calmer avec ses idées farfelues...",
          DialogueId = 71002211,
          GUID = "B1BF20BC",
          SpeakNpcId = 818019,
          Subtitle = "That's another one down! One more to go... Seriously, can't the boss go five minutes without a \"visionary new idea\"?"
        },
        [71002212] = {
          ContentFR = "Qu’est-ce que c’est que ce bazar au milieu de la route... Tout me tombe dessus aujourd’hui !",
          DialogueId = 71002212,
          GUID = "B1BF1FEA",
          NextDialogue = 71002218,
          SpeakNpcId = 818019,
          Subtitle = "Ugh — what is all this stuff!? Who even leaves this kind of mess in the middle of the road!?"
        },
        [71002213] = {
          ContentFR = "Tiens, garde les plats. Je m’occupe de tout ce bazar.",
          DialogueId = 71002213,
          GUID = "B1BF2014",
          SpeakNpcId = 100001,
          Subtitle = "Here. You hold the food. I'll clear the path."
        },
        [71002214] = {
          ContentFR = "Quoi ? Tout est dégagé ? On est encore dans les temps ! Allez, en route, en route !",
          DialogueId = 71002214,
          GUID = "B1BF2015",
          SpeakNpcId = 818019,
          Subtitle = "Wait — you cleared it all? We can still make it! GO GO GO!"
        },
        [71002215] = {
          ContentFR = "Enfin, tout livré... sans toi, je n’aurais rien gagné. Bon... pause terminée, il faut retourner bosser...",
          DialogueId = 71002215,
          GUID = "B1BF203E",
          NextDialogue = 71002216,
          SpeakNpcId = 818019,
          Subtitle = "Phew... all delivered. If it weren't for you, I wouldn't have earned a single coin today. Okay... break's over. Time to get back to work."
        },
        [71002216] = {
          ContentFR = "Mais tu disais que tu arrêtais ?",
          DialogueId = 71002216,
          GUID = "B1BF2068",
          NextDialogue = 71002217,
          SpeakNpcId = 100001,
          Subtitle = "Weren't you just quitting?"
        },
        [71002217] = {
          ContentFR = "Luno, le livreur secoue la poussière de ses vêtements et s’éloigne. La réponse à ta question se perd dans le petit soupir las qu’il laisse derrière lui...",
          DialogueId = 71002217,
          GUID = "B1BF2092",
          SpeakNpcId = 800006,
          Subtitle = "(The Lunodeliverer brushes off her coat and walks away. The only answer is a long, weary sigh tossed over her shoulder.)"
        },
        [71002218] = {
          ContentFR = "J’en ai marre ! Cette fois, je le dis au patron, ce boulot, je le REFUSE !",
          DialogueId = 71002218,
          GUID = "B1BF1FEB",
          NextDialogue = 71002213,
          SpeakNpcId = 818019,
          Subtitle = "That's it! I quit! I'm going back to tell the boss I'm DONE with this nonsense!"
        },
        [71002301] = {
          ContentFR = "Ouf... je n’ai pas tout cassé, j’espère...",
          DialogueId = 71002301,
          GUID = "B1BF2F02",
          SpeakNpcId = 818020,
          Subtitle = "Oof... Please tell me I didn't just break it..."
        },
        [71002302] = {
          ContentFR = "Qui est là... !?",
          DialogueId = 71002302,
          GUID = "B1BF2F2C",
          NextDialogue = 71002303,
          SpeakNpcId = 818020,
          Subtitle = "Who's there!?"
        },
        [71002303] = {
          ContentFR = "Oh... juste {性别:un Chasseur de Phoxène|une Chasseuse de Phoxène} de passage. Euh... dis, tu veux pas me filer un coup de main ? Il faut juste tester ce truc, c’est super facile ! Je te donnerai une récompense.",
          DialogueId = 71002303,
          GUID = "B1BF2F56",
          SpeakNpcId = 818020,
          Subtitle = "Oh... just a passing Phoxhunter. Ahem... Say, how about lending me a hand? Just help me test this thing. It won't bite, promise! I'll even toss you a reward for the trouble."
        },
        [71002304] = {
          ContentFR = "Tiens bon 15 secondes, et c’est fini ! Allez, courage !",
          DialogueId = 71002304,
          GUID = "B1BF2F80",
          SpeakNpcId = 818020,
          Subtitle = "Just hang in there for 15 seconds — that's all. You've got this!"
        },
        [71002305] = {
          ContentFR = "Tous les tirs ont raté... Ils disaient que c’était un bijou militaire d’Élysium ? Franchement, ça ressemble plus à un tas de ferraille... Ah, oublie ce que je viens de dire. Tiens, voilà ta paye. Et, euh... gardons ça entre nous, hein ?",
          DialogueId = 71002305,
          GUID = "B1BF2FAA",
          SpeakNpcId = 818020,
          Subtitle = "Wait, every shot missed!? No way... They swore this thing was top-grade Elysian military issue! Ugh, probably just some fancy-looking scrap. Ah — forget what I just said. Here's your payment. And, uh... let's keep this between us, yeah?"
        },
        [71002306] = {
          ContentFR = "Tous les tirs ont touché, et tu es toujours debout !? Mais c’était censé être un bijou militaire d’Élysium ! Bon... sûrement juste un truc hors de prix... Ah, oublie ce que je viens de dire. Tiens, voilà ta paye. Et, euh... gardons ça entre nous, hein ?",
          DialogueId = 71002306,
          GUID = "B1BF2FD4",
          SpeakNpcId = 818020,
          Subtitle = "Wait, it landed every shot — and you're still standing!? But they swore this thing was top-grade Elysian military issue! Tch. Probably just some overpriced junk... Ah — forget what I just said. Here's your payment. And, uh... let's keep this between us, yeah?"
        },
        [71002401] = {
          ContentFR = "Argh... cet excavateur est déjà en panne alors qu’il n’a même pas commencé à travailler ! Mais... où est passé mon kit de réparation ?",
          DialogueId = 71002401,
          GUID = "B1BF3F6A",
          SpeakNpcId = 818015,
          Subtitle = "Ugh... why'd the excavator break before it even started working!? Where did I put that toolkit..."
        },
        [71002402] = {
          ContentFR = "Ouaah ! On se retrouve dans un endroit pareil, c’est un sacré hasard ! Puisque tu es là, tu ne veux pas jeter un œil à mon précieux excavateur pendant que je vais chercher mes outils ?",
          DialogueId = 71002402,
          GUID = "B1BF3F94",
          SpeakNpcId = 818015,
          Subtitle = "Whoa — fancy seeing you here! This has to be fate, right? Say, could you do me a teeny favour and keep an eye on my precious detector while I run back and grab my kit?"
        },
        [71002403] = {
          ContentFR = "Youpi ! Super, reste juste à côté et ne le perds pas de vue, d’accord ? Je reviens tout de suite !",
          DialogueId = 71002403,
          GUID = "B1BF3FBE",
          NextDialogue = 71002404,
          SpeakNpcId = 818015,
          Subtitle = "Yay, you're a lifesaver! Just stay close and don't let it out of your sight, okay? Be right back~!"
        },
        [71002404] = {
          ContentFR = "<I>Hmm... quelques pièces sont coincées. Si je les débloque un peu, ça devrait être plus facile à réparer ensuite.</>",
          DialogueId = 71002404,
          GUID = "B1BF3FE8",
          SpeakNpcId = 100001,
          Subtitle = "Hm... looks like some parts are jammed. If I loosen them a bit, it might make things easier to fix later."
        },
        [71002405] = {
          ContentFR = "L’excavateur fait du bruit et attire les Souillés aux alentours. Il faut les repousser avant qu’ils s’approchent trop.",
          DialogueId = 71002405,
          GUID = "B1BF4012",
          SpeakNpcId = 800006,
          Subtitle = "(The excavator's beeping is attracting nearby Filthoids. Better drive them off before they get too close.)"
        },
        [71002406] = {
          ContentFR = "Eh... tu as même débloqué les pièces coincées ? Tu es trop {性别:fort|forte}, merci beaucoup !",
          DialogueId = 71002406,
          GUID = "B1BF403C",
          SpeakNpcId = 818015,
          Subtitle = "Aww... you even unjammed the parts!? You're the best!"
        },
        [71002407] = {
          ContentFR = "Ça y est, je suis de retour ! Je savais que je pouvais compter sur toi !",
          DialogueId = 71002407,
          GUID = "B1BF4066",
          SpeakNpcId = 818015,
          Subtitle = "I'm back! Thanks — I knew I could count on you!"
        },
        [71002501] = {
          ContentFR = "Bon... ce fichu égout est encore bouché...",
          DialogueId = 71002501,
          GUID = "B1BF4FD2",
          SpeakNpcId = 818021,
          Subtitle = "Ugh... sewer's clogged again..."
        },
        [71002502] = {
          ContentFR = "Que se passe-t-il ?",
          DialogueId = 71002502,
          GUID = "B1BF4FFC",
          NextDialogue = 71002503,
          SpeakNpcId = 100001,
          Subtitle = "What's going on?"
        },
        [71002503] = {
          ContentFR = "Tout ce secteur est bloqué. Mon supérieur m’a filé un manuel en me disant de « suivre les instructions », mais je n’y comprends rien... Tu pourrais m’aider ?",
          DialogueId = 71002503,
          GUID = "B1BF5026",
          NextOptions = {
            [1] = 710025041,
            [2] = 710025042
          },
          SpeakNpcId = 818021,
          Subtitle = "Whole drain's backed up. My superior tossed me this manual — said to \"follow the steps,\" but I can't make heads or tails of it... Mind lending a hand?"
        },
        [71002505] = {
          ContentFR = "D’après le manuel, il suffit d’ouvrir trois vannes pour créer un fort courant et tout évacuer.",
          DialogueId = 71002505,
          GUID = "B1BF507A",
          NextDialogue = 71002511,
          SpeakNpcId = 100001,
          Subtitle = "It says here you just need to open three sluice gates to flush it out."
        },
        [71002507] = {
          ContentFR = "Super ! La deuxième est par là-bas.",
          DialogueId = 71002507,
          GUID = "B1BF50CE",
          SpeakNpcId = 818021,
          Subtitle = "Nice! Second one's just over there."
        },
        [71002508] = {
          ContentFR = "Et la troisième... voyons voir... oui, la voilà !",
          DialogueId = 71002508,
          GUID = "B1BF50F8",
          SpeakNpcId = 818021,
          Subtitle = "And the third... right, there it is!"
        }
      }
    end
