          GUID = "B1BF60E2",
          SpeakNpcId = 818023,
          Subtitle = "Thanks for the help. Here's your cut."
        },
        [71002701] = {
          ContentFR = "Des barils dérivent au fil du canal, certains émettant de drôles de sons. Si tu les ouvres prudemment, tu pourrais y trouver quelque chose d’utile.",
          DialogueId = 71002701,
          GUID = "B1BF70A2",
          SpeakNpcId = 800006,
          Subtitle = "(A few barrels bob along the waterway, some giving off eerie noises. If you open them carefully, you might just find something useful.)"
        },
        [71002702] = {
          ContentFR = "Le fond de ce baril est percé. À part le sifflement du vent, rien d’intéressant. Mieux vaut regarder ailleurs.",
          DialogueId = 71002702,
          GUID = "B1BF70CC",
          SpeakNpcId = 800006,
          Subtitle = "(This barrel has a gaping hole at the bottom. Nothing inside — just the wind whistling through. Better try another.)"
        },
        [71002703] = {
