          DialogueId = 71002703,
          GUID = "B1BF70F6",
          SpeakNpcId = 800006,
          Subtitle = "(This barrel is stuffed with rotting household waste, creating revolting gurgling sounds and a nauseating stench. Better try another.)"
        },
        [71002704] = {
          ContentFR = "La persévérance finit par payer : en fouillant soigneusement, tu découvres des fournitures dissimulées dans une double paroi.",
          DialogueId = 71002704,
          GUID = "B1BF7120",
          SpeakNpcId = 800006,
          Subtitle = "(Patience pays off. After a meticulous search, you spot a hidden compartment — and inside, a stash of usable supplies.)"
        },
        [71002705] = {
          ContentFR = "Le vieux baril s’écroule d’un coup avec fracas, attirant les Souillés alentour. Débarrasse-toi d’eux et empare-toi de ton butin !",
          DialogueId = 71002705,
          GUID = "B1BF714A",
          SpeakNpcId = 800006,
