        },
        [71002801] = {
          ContentFR = "Un éboulement bloque le passage devant toi. Dégage les rochers pour continuer.",
          DialogueId = 71002801,
          GUID = "B1BF810A",
          SpeakNpcId = 800006,
          Subtitle = "(A landslide blocks the path ahead. Clear the rubble to proceed.)"
        },
        [71002802] = {
