        [71005141] = {
          ContentFR = "Je crois que j’en ai assez entendu. Il est temps d’avouer la vérité.",
          DialogueId = 71005141,
          GUID = "B1C0FF78",
          SpeakNpcId = 100001,
          Subtitle = "I think I've heard enough. Time to reel the truth out of you."
        },
        [71005142] = {
          ContentFR = "D’accord, d’accord ! Tu m’as eu... J’ai vu comment certains se font avoir par quelques mots et un peu de mise en scène, alors... j’ai voulu voir si ça marchait vraiment sur quelqu’un.",
          DialogueId = 71005142,
          GUID = "B1C0FFA2",
          NextDialogue = 71005143,
          SpeakNpcId = 818045,
          Subtitle = "Alright, alright! You got me. I've seen how folks fall for a few smooth words and a bit of showmanship... So I figured — why not give it a try myself?"
        },
        [71005143] = {
          ContentFR = "Bref, désolé pour le dérangement. Tiens, c’est pour toi. Considère ça comme des excuses.",
          DialogueId = 71005143,
          GUID = "B1C0FFCC",
