        [71006514] = {
          ContentFR = "Écoutez bien la question ! Un Tisse-Étoiles a perdu une marchandise. Après enquête, trois suspects sont identifiés : A, B et C.\nA accuse B : « C’est B qui a volé l’objet ! » B accuse C : « C’est C le voleur ! » C affirme : « C’est bien moi qui l’ai volé ! » Une seule personne dit la vérité. Alors... qui a réellement volé la marchandise ?",
          DialogueId = 71006514,
          GUID = "B1C1E234",
          NextOptions = {
            [1] = 710065141,
            [2] = 710065142,
            [3] = 710065143
          },
          SpeakNpcId = 818060,
          Subtitle = "Right then, here's the question! A Starweaver lost something from their stall, and they've narrowed it down to three suspects: A, B, and C.\n A says B stole it.\n B says C stole it.\n C admits it — says he's the guilty one.\n Only one of them is telling the truth... so who actually took it?",
          bForbidSkipOptions = true
        },
        [71006515] = {
          ContentFR = "Écoutez bien ! Une amie de Luno, la carpe, a trois amies Lunariens. La première s’appelle Luno, la dorée, la deuxième Luno, l’argentée... Comment s’appelle la troisième ?",
          DialogueId = 71006515,
          GUID = "B1C1E25E",
          NextOptions = {
            [1] = 710065151,
            [2] = 710065152,
            [3] = 710065153
          },
          SpeakNpcId = 818060,
          Subtitle = "Right then, here's the question! A friend of Lunocarp's has three Luno friends. The first is called Lunogold, the second is Lunosilver — so what's the third one called?",
          bForbidSkipOptions = true
        },
        [71006516] = {
          ContentFR = "Troisième question ! Trois personnes font la queue, chacune portant un chapeau dont la couleur peut être rouge, jaune ou bleu.\nLa dernière voit les deux chapeaux devant elle. Celle du milieu ne voit que le chapeau de la première. La dernière se tait. Puis celle du milieu se tait également.\nAlors, la première annonce : « Je porte un chapeau jaune. »\nSachant qu’au moins une personne porte un chapeau jaune... Laquelle de ces affirmations est correcte ?",
          DialogueId = 71006516,
          GUID = "B1C1E288",
          NextOptions = {
            [1] = 710065161,
            [2] = 710065162,
            [3] = 710065163
          },
          SpeakNpcId = 818060,
          Subtitle = "Right then, here's the question! Three people are standing in a line, each wearing a hat that could be red, yellow, or blue. The one at the back can see the two hats ahead. The one in the middle can only see the hat of the person in front.\n At first, the person at the back stays quiet. And the one in the middle stays quiet too. And that's when the person at the front suddenly pipes up and says they're wearing a yellow hat.\n We also know at least one of the hats is yellow.\n So — which of these statements is correct?",
          bForbidSkipOptions = true
        },
        [71006517] = {
          ContentFR = "Félicitations, bonne réponse ! Voici le prix de luxe que nous avions préparé pour vous. Tenez !",
          DialogueId = 71006517,
          GUID = "B1C1E2B2",
          SpeakNpcId = 818060,
          Subtitle = "Congratulations — you got it right! Here's your deluxe prize~"
        },
        [71006518] = {
          ContentFR = "Dommage... Voici tout de même un lot de consolation. N’hésitez pas à revenir tenter votre chance !",
          DialogueId = 71006518,
          GUID = "B1C1E2DC",
          SpeakNpcId = 818060,
          Subtitle = "Not quite. Here's your consolation prize — come back and try again next time!"
        },
        [71006519] = {
          ContentFR = "Eh bien, eh bien... la jeunesse a de l’entrain. Bonne chance, alors.",
          DialogueId = 71006519,
          GUID = "B1C1E306",
          SpeakNpcId = 818061,
          Subtitle = "All right, all right — youngsters do have some spirit. Good luck, then."
        },
        [71006520] = {
          ContentFR = "Très bien. Revenez me voir quand vous serez {性别:prêt|prête} !",
          DialogueId = 71006520,
          GUID = "B1C1E330",
          SpeakNpcId = 818060,
          Subtitle = "Mm-hm. Come find me again whenever you're ready!"
        },
        [71006601] = {
          ContentFR = "J’aimerais tellement des petites grenouilles... Tellement... <I>croa, croa...</>",
          DialogueId = 71006601,
          GUID = "B1C1F07A",
          SpeakNpcId = 818062,
          Subtitle = "I want little frogs... want them so much... croak, croak..."
        },
        [71006602] = {
          ContentFR = "Des petites grenouilles... J’en veux tant... des petites grenouilles, des petites grenouilles, des petites grenouilles...",
          DialogueId = 71006602,
          GUID = "B1C1F0A4",
          NextOptions = {
            [1] = 710066021,
            [2] = 710066022
          },
          SpeakNpcId = 818062,
          Subtitle = "Little frogs... I want little frogs... little frogs, little frogs, little frogs...",
          bForbidSkipOptions = true
        },
        [71006603] = {
          ContentFR = "<I>Il semble nourrir une obsession étrange pour les grenouilles... Essayons de lui en trouver.</>",
          DialogueId = 71006603,
          GUID = "B1C1F0CE",
          SpeakNpcId = 100001,
          Subtitle = "(It seems strangely fixated on frogs... let's see if we can find some for it.)"
        },
        [71006604] = {
          ContentFR = "Cela devrait suffire. Retournons les lui donner.",
          DialogueId = 71006604,
          GUID = "B1C1F0F8",
          SpeakNpcId = 100001,
          Subtitle = "These should be enough. Let's take them back to it."
        },
        [71006605] = {
          ContentFR = "Des petites grenouilles ! Youpi ! Des petites grenouilles~ <I>Croa, croa...</>",
          DialogueId = 71006605,
          GUID = "B1C1F122",
          NextDialogue = 71006606,
          SpeakNpcId = 818062,
          Subtitle = "Little frogs! Yay! Little frogs~ Croak, croak..."
        },
        [71006606] = {
          ContentFR = "Ainsi, le Wishen disparut sous vos yeux.",
          DialogueId = 71006606,
          GUID = "B1C1F14C",
          SpeakNpcId = 800006,
          Subtitle = "(And with that, the Wishen faded from sight before your eyes.)"
        },
        [71006701] = {
          ContentFR = "Si tu te trompes encore sur une question aussi simple, tu resteras ce soir à recopier cent fois.",
          DialogueId = 71006701,
          GUID = "B1C200E2",
          NextDialogue = 71006702,
          SpeakNpcId = 818064,
          Subtitle = "Get this simple question wrong again, and you'll stay behind tonight to copy it out a hundred times."
        },
        [71006702] = {
          ContentFR = "Une voix courroucée résonne au loin. Allons voir ce qu’il se passe.",
          DialogueId = 71006702,
          GUID = "B1C2010C",
          SpeakNpcId = 800006,
          Subtitle = "(An angry voice echoes in the distance. Better go and see what's going on.)"
        },
        [71006703] = {
          ContentFR = "Que se passe-t-il ici ?",
          DialogueId = 71006703,
          GUID = "B1C20136",
          NextDialogue = 71006704,
          SpeakNpcId = 100001,
          Subtitle = "What's going on here?"
        },
        [71006704] = {
          ContentFR = "Hmpf... Cet enfant est incapable de réciter de mémoire les Neuf Chapitres de Dafeng. Avec si peu de rigueur, comment espérer progresser dans ses études ?",
          DialogueId = 71006704,
          GUID = "B1C20160",
          NextDialogue = 71006705,
          SpeakNpcId = 818064,
          Subtitle = "Hmph... the kid can't even write out the Nine Chapters of Dafeng from memory. With so little self-discipline, how will he ever get anywhere with his studies?"
        },
        [71006705] = {
          ContentFR = "Non... plus j’y pense, plus cela m’agace. Je vais boire un thé pour me calmer. Pourriez-vous le surveiller un instant ?",
          DialogueId = 71006705,
          GUID = "B1C2018A",
          NextOptions = {
            [1] = 710067051,
            [2] = 710067052
          },
          SpeakNpcId = 818064,
          Subtitle = "Ugh, I can't take this. The more I think about it, the angrier I get. I'm stepping away for a moment — keep an eye for me, will you?",
          bForbidSkipOptions = true
        },
        [71006706] = {
          ContentFR = "Je vous remercie. Je reviens très vite.",
          DialogueId = 71006706,
          GUID = "B1C201B4",
          SpeakNpcId = 818064,
          Subtitle = "Thank you. I won't be long."
        },
        [71006707] = {
          ContentFR = "<I>Snif... snif...</> c’était quoi déjà, la phrase d’après... ?",
          DialogueId = 71006707,
          GUID = "B1C201DE",
          NextDialogue = 71006708,
          SpeakNpcId = 818063,
          Subtitle = "*sniffle*... I can't remember the next line at all..."
        },
        [71006708] = {
          ContentFR = "Euh... Vous pourriez m’aider, s’il vous plaît... ?",
          DialogueId = 71006708,
          GUID = "B1C20208",
          SpeakNpcId = 818063,
          Subtitle = "Um... could you help me, please...?"
        },
        [71006709] = {
          ContentFR = "J’ai écrit jusqu’à : « Faire triompher le vrai et écarter le faux, agir avec un cœur sincère. » Mais impossible de me souvenir de la suite... Pourriez-vous regarder dans le livre ?",
          DialogueId = 71006709,
          GUID = "B1C20232",
          NextOptions = {
            [1] = 710067091,
            [2] = 710067092
          },
          SpeakNpcId = 818063,
          Subtitle = "I've written up to \"Let truth be manifest and falsehood driven out,\" but I just can't recall what comes next. Could you check the notebook for me?",
          bForbidSkipOptions = true
        },
        [71006711] = {
          ContentFR = "Non... Je voulais juste aller jouer dehors...",
          DialogueId = 71006711,
          GUID = "B1C20286",
          SpeakNpcId = 818063,
          Subtitle = "Aww... I'm going to get detention... I just want to go out and play..."
        },
        [71006712] = {
          ContentFR = "Vous me sauvez la vie ! Merci, merci infiniment !",
          DialogueId = 71006712,
          GUID = "B1C202B0",
          SpeakNpcId = 818063,
          Subtitle = "You're a lifesaver! Thank you so much!"
        },
        [71006713] = {
          ContentFR = "Vous ouvrez le carnet recopié des Neuf Chapitres de Dafeng. Après « Faire triompher le vrai et écarter le faux, agir avec un cœur sincère », vient la phrase :\n« Tromper les foules par des paroles mensongères — cela est proscrit. »",
          DialogueId = 71006713,
          GUID = "B1C202DA",
          NextDialogue = 71006714,
          SpeakNpcId = 800006,
          Subtitle = "(You open the notebook, filled with copied passages from the statutes of the Nine Chapters of Dafeng. The line after \"Let truth be manifest and falsehood driven out\" reads: \"To deceive and mislead the many — this must not be done.\")"
        },
        [71006714] = {
          ContentFR = "Voilà, j’ai trouvé. Allons lui donner la réponse.",
          DialogueId = 71006714,
          GUID = "B1C20304",
          SpeakNpcId = 100001,
          Subtitle = "Found it. Time to go back."
        },
        [71006715] = {
          ContentFR = "Vous êtes enfin {性别:revenu|revenue} ! Vite, vite, quelle est la phrase suivante ?",
          DialogueId = 71006715,
          GUID = "B1C2032E",
          SpeakNpcId = 818063,
          Subtitle = "You're finally back! What's the next line? Quick!"
        },
        [71006717] = {
          ContentFR = "Hmph ! Même ça, tu arrives à te tromper ! Ce soir, tu recopieras encore cinq cents fois — pas une de moins, et tu ne partiras pas avant d’avoir fini !",
          DialogueId = 71006717,
          GUID = "B1C20382",
          NextDialogue = 71006718,
          SpeakNpcId = 818064,
          Subtitle = "You've still got it wrong? Tonight, you'll copy it out another five hundred times — and you're not leaving until every last one is done!"
        },
        [71006718] = {
          ContentFR = "Nooooon— !",
          DialogueId = 71006718,
          GUID = "B1C203AC",
          NextDialogue = 71006719,
          SpeakNpcId = 818063,
          Subtitle = "Nooo—!"
        },
        [71006719] = {
          ContentFR = "Merci d’avoir veillé sur lui. Voici votre récompense, veuillez l’accepter.",
          DialogueId = 71006719,
          GUID = "B1C203D6",
          SpeakNpcId = 818064,
          Subtitle = "Thank you for helping me. Please, take this as a small token of thanks."
        },
        [71006720] = {
          ContentFR = "Tu vois ? En te concentrant et en réfléchissant posément, tu y arrives très bien.",
          DialogueId = 71006720,
          GUID = "B1C20400",
          NextDialogue = 71006721,
          SpeakNpcId = 818064,
          Subtitle = "See? Steady your mind and think it through, and the words will come."
        },
        [71006721] = {
          ContentFR = "Génial ! Je peux enfin aller jouer !",
          DialogueId = 71006721,
          GUID = "B1C2042A",
          NextDialogue = 71006722,
          SpeakNpcId = 818063,
          Subtitle = "Great! I can finally go out and play!"
        },
        [71006722] = {
          ContentFR = "Halte-là ! Puisque ta récitation est correcte aujourd’hui, tu n’auras plus qu’à recopier cinquante fois. Tu partiras après.",
          DialogueId = 71006722,
          Duration = 3,
          GUID = "B1C20454",
          NextDialogue = 71006723,
          SpeakNpcId = 818064,
          Subtitle = "Not so fast! That will do for today — you only need to copy it fifty more times. Finish that, then you can go."
        },
        [71006723] = {
          ContentFR = "Nooooon— !",
          DialogueId = 71006723,
          GUID = "B1C2047E",
          NextDialogue = 71006724,
          SpeakNpcId = 818063,
          Subtitle = "Nooo—!"
        },
        [71006724] = {
          ContentFR = "Merci d’avoir veillé sur lui. Voici votre récompense, veuillez l’accepter.",
          DialogueId = 71006724,
          GUID = "B1C204A8",
          SpeakNpcId = 818064,
          Subtitle = "Thank you for helping me. Please, take this as a small token of thanks."
        },
        [71006801] = {
          ContentFR = "Hé, vous là-bas ! Pourriez-vous me prendre en photo ?",
          DialogueId = 71006801,
          GUID = "B1C2114A",
          SpeakNpcId = 818041,
          Subtitle = "Hey! Could you take a few photos for me?"
        },
        [71006802] = {
          ContentFR = "Dites-moi, accepteriez-vous de me prendre quelques clichés ? Je ne viens pas souvent à Éternel Printemps, ce serait vraiment dommage de repartir sans souvenir.",
          DialogueId = 71006802,
          GUID = "B1C21174",
          NextOptions = {
            [1] = 710068021,
            [2] = 710068022
          },
          SpeakNpcId = 818041,
          Subtitle = "Hi there, could you take a few photos for me? I don't get to come to EverSpring often, and it'd be a shame to leave without any pictures.",
          bForbidSkipOptions = true
        },
        [71006804] = {
          ContentFR = "Formidable ! Pensez bien à inclure la statue de ce dragon blanc derrière moi, j’adore son allure.",
          DialogueId = 71006804,
          GUID = "B1C211C8",
          SpeakNpcId = 818041,
          Subtitle = "Great! Make sure you get that argent loong behind me as well. I really like the way it looks."
        },
        [71006805] = {
          ContentFR = "Elles sont superbes, vraiment ! Vous avez l’œil, merci mille fois.",
          DialogueId = 71006805,
          GUID = "B1C211F2",
          SpeakNpcId = 818041,
          Subtitle = "These came out great. You're really good at this — thanks a lot!"
        },
        [71006901] = {
          ContentFR = "Oh là là... c’est une catastrophe...",
          DialogueId = 71006901,
          GUID = "B1C221B2",
          SpeakNpcId = 818065,
          Subtitle = "Oh no, oh no... this isn't good..."
        },
        [71006902] = {
          ContentFR = "Vous là, j’ai fait tomber mon outre d’alcool, mes appâts et même ma canne à pêche dans l’eau... Pourriez-vous m’aider à attraper quelques poissons ? Si je rentre encore bredouille, tout le monde va se moquer de moi...",
          DialogueId = 71006902,
          GUID = "B1C221DC",
          NextOptions = {
            [1] = 710069021,
            [2] = 710069022
          },
          SpeakNpcId = 818065,
          Subtitle = "Hey there, I've gone and dropped my wine flask, my bait, and even my rod into the water... Could you catch a few fish for me? If I go back empty-handed again, they'll all laugh at me."
        },
        [71006903] = {
          ContentFR = "Parfait... je vous en prie, aidez-moi.",
          DialogueId = 71006903,
          GUID = "B1C22206",
          SpeakNpcId = 818065,
          Subtitle = "Thank you so much. You're a lifesaver."
        },
        [71006904] = {
          ContentFR = "Comment ai-je pu attraper un poisson pareil… Vous croyez que mon outre d’alcool l’a attiré ? Bah... j’y réfléchirai plus tard.",
          DialogueId = 71006904,
          GUID = "B1C22230",
          NextDialogue = 71006905,
          SpeakNpcId = 818065,
          Subtitle = "How did you even catch something like this...? Could my wine flask have drawn it here? Ah, never mind. I'll figure it out later."
        },
        [71006905] = {
          ContentFR = "Merci infiniment pour ces poissons, vous m’avez vraiment tiré d’affaire aujourd’hui !",
          DialogueId = 71006905,
          GUID = "B1C2225A",
          SpeakNpcId = 818065,
          Subtitle = "Thanks a ton for catching all these fish. You really saved me today!"
        },
        [71007001] = {
          ContentFR = "Que vais-je faire... Seigneur Dragon d’Argent, je vous en supplie, envoyez-moi quelqu’un pour m’aider !",
          DialogueId = 71007001,
          GUID = "B1C2321A",
          SpeakNpcId = 818066,
          Subtitle = "Oh no... what do I do? Lord Argent, please, send someone to help me!"
        },
        [71007002] = {
          ContentFR = "Que se passe-t-il ?",
          DialogueId = 71007002,
          GUID = "B1C23244",
          NextDialogue = 71007003,
          SpeakNpcId = 100001,
          Subtitle = "What's going on?"
        },
        [71007003] = {
          ContentFR = "Je dois retrouver la personne que j’aime ici, mais je n’ai pas encore tout préparé. Pourriez-vous aller m’acheter un cadeau, s’il vous plaît ?",
          DialogueId = 71007003,
          GUID = "B1C2326E",
          NextOptions = {
            [1] = 710070031,
            [2] = 710070032
          },
          SpeakNpcId = 818066,
          Subtitle = "I'm supposed to meet the girl I love here, but I haven't even finished getting everything ready. Could you make a quick trip to buy a present for me?",
          bForbidSkipOptions = true
        },
        [71007004] = {
          ContentFR = "Je vous en suis profondément reconnaissant ! Ah, une chose encore : elle est allergique aux fleurs. Surtout, n’achetez rien qui en contienne.",
          DialogueId = 71007004,
          GUID = "B1C23298",
          SpeakNpcId = 818066,
          Subtitle = "Thank you — truly. One more thing: she's allergic to flowers, so whatever you do, don't get anything with flowers in it."
        },
        [71007005] = {
          ContentFR = "Bonjour, je cherche un cadeau à offrir.",
          DialogueId = 71007005,
          GUID = "B1C232C2",
          NextDialogue = 71007006,
          SpeakNpcId = 100001,
          Subtitle = "Hello, I'd like to pick out a gift."
        },
        [71007006] = {
          ContentFR = "Très bien ! Ces trois articles sont les plus appréciés en ce moment. Laissez-moi vous les présenter.",
          DialogueId = 71007006,
          GUID = "B1C232EC",
          NextDialogue = 71007007,
          SpeakNpcId = 818067,
          Subtitle = "All right. These three are our most popular at the moment — let me show them to you."
        },
        [71007007] = {
          ContentFR = "Le premier : des Lys célestes fraîchement cueillies à la Baie des Roseaux-Pâles, encore couvertes de rosée matinale. Un choix sûr pour une jeune femme.",
          DialogueId = 71007007,
          GUID = "B1C23316",
          NextDialogue = 71007008,
          SpeakNpcId = 818067,
          Subtitle = "First, Skylilies freshly picked from Reedshore, still with the morning's dew on them. You can't go wrong giving these to a young lady."
        },
        [71007008] = {
          ContentFR = "Le deuxième : un pendentif en bronze, façonné par un maître artisan de la Secte Jishu. Le travail est soigné, les détails raffinés.",
          DialogueId = 71007008,
          GUID = "B1C23340",
          NextDialogue = 71007009,
          SpeakNpcId = 818067,
          Subtitle = "Second, a bronze pendant crafted by a renowned artisan of the Jishu Sect, finely worked with exquisite detail."
        },
        [71007009] = {
          ContentFR = "Le troisième : une figurine du Seigneur Dragon d’Argent, réalisée spécialement par la Secte Xuanheng. La finesse d’exécution la rend presque vivante.",
          DialogueId = 71007009,
          GUID = "B1C2336A",
          NextDialogue = 71007010,
          SpeakNpcId = 818067,
          Subtitle = "Third, a special Lord Argent figurine made by the Xuanheng Sect. The craftsmanship is so fine it looks almost alive."
        },
        [71007010] = {
          ContentFR = "Alors, lequel choisissez-vous ?",
          DialogueId = 71007010,
          GUID = "B1C23394",
          NextOptions = {
            [1] = 710070101,
            [2] = 710070102,
            [3] = 710070103
          },
          SpeakNpcId = 818067,
          Subtitle = "Which one would you like?",
          bForbidSkipOptions = true
        },
        [71007011] = {
          ContentFR = "Parfait, je vous emballe cela immédiatement. Revenez quand vous voulez.",
          DialogueId = 71007011,
          GUID = "B1C233BE",
          SpeakNpcId = 818067,
          Subtitle = "All right, I'll get that wrapped up for you. Do come again."
        },
        [71007012] = {
          ContentFR = "Le cadeau est là ! Allez, ouvre-le vite, dis-moi s’il te plaît !",
          DialogueId = 71007012,
          GUID = "B1C233E8",
          NextDialogue = 71007013,
          SpeakNpcId = 818066,
          Subtitle = "Here it is! Quick, open it — see if you like it!"
        },
        [71007013] = {
          ContentFR = "<I>Atchoum ! A... atchoum...</> P-pourquoi des fleurs... ? Je me sens mal... j’ai... du mal à respirer...",
          DialogueId = 71007013,
          GUID = "B1C23412",
          NextDialogue = 71007014,
          SpeakNpcId = 818068,
          Subtitle = "Achoo! Ah... ah-choo... Wh—Why would you get me flowers...? I'm feeling awful... I... I can't breathe..."
        },
        [71007014] = {
          ContentFR = "Voyant la réaction, l’homme prend aussitôt sa bien-aimée sur son dos et part en hâte chercher de l’aide, vous laissant seul sur place.",
          DialogueId = 71007014,
          GUID = "B1C2343C",
          NextDialogue = 71007015,
          SpeakNpcId = 800006,
          Subtitle = "(As soon as he sees her allergy acting up, he lifts her onto his back and dashes off for help, leaving you behind.)"
        },
        [71007015] = {
          ContentFR = "Tout est désormais réglé. Vous pouvez partir.",
          DialogueId = 71007015,
          GUID = "B1C23466",
          SpeakNpcId = 800006,
          Subtitle = "(Everything here is taken care of. You can be on your way.)"
        },
        [71007016] = {
          ContentFR = "Le cadeau est arrivé ! Allez, ouvre-le vite, dis-moi s’il te plaît !",
          DialogueId = 71007016,
          GUID = "B1C23490",
          NextDialogue = 71007017,
          SpeakNpcId = 818066,
          Subtitle = "Here it is! Quick, open it — see if you like it!"
        },
        [71007017] = {
          ContentFR = "Merci... Tout ce que tu me donnes me fait plaisir.",
          DialogueId = 71007017,
          GUID = "B1C234BA",
          NextDialogue = 71007018,
          SpeakNpcId = 818068,
          Subtitle = "Thank you! I love it. I'd love anything you gave me, honestly."
        },
        [71007018] = {
          ContentFR = "En voyant le sourire radieux de sa bien-aimée, l’homme vous adresse discrètement un signe de pouce levé.",
          DialogueId = 71007018,
          GUID = "B1C234E4",
          NextDialogue = 71007019,
          SpeakNpcId = 800006,
          Subtitle = "(Seeing her smile, he slips you a quick thumbs-up.)"
        },
        [71007019] = {
          ContentFR = "Tout est désormais réglé. Vous pouvez partir.",
          DialogueId = 71007019,
          GUID = "B1C2350E",
          SpeakNpcId = 800006,
          Subtitle = "(Everything here is taken care of. You can be on your way.)"
        },
        [71007101] = {
          ContentFR = "Ah... pourquoi tout devait-il tomber le même jour...",
          DialogueId = 71007101,
          GUID = "B1C24282",
          SpeakNpcId = 818069,
          Subtitle = "Ugh... why did everything have to land on the same day..."
        },
        [71007103] = {
          ContentFR = "Oh, vous tombez à point. Pourriez-vous faire la queue là-bas et m’acheter un sablé aux noix ?",
          DialogueId = 71007103,
          GUID = "B1C242D6",
          NextDialogue = 71007104,
          SpeakNpcId = 818069,
          Subtitle = "Ah, sorry to bother you, but could you queue up over there and get me a walnut shortbread?"
        },
        [71007104] = {
          ContentFR = "J’ai encore un rendez-vous d’affaires après, je n’ai vraiment pas le temps d’attendre.",
          DialogueId = 71007104,
          GUID = "B1C24300",
          NextOptions = {
            [1] = 710071041,
            [2] = 710071042
          },
          SpeakNpcId = 818069,
          Subtitle = "I've got a business meeting coming up, so I really don't have time to stand in a queue.",
          bForbidSkipOptions = true
        },
        [71007105] = {
          ContentFR = "Merci, je vous laisse faire. Je dois y aller.",
          DialogueId = 71007105,
          GUID = "B1C2432A",
          SpeakNpcId = 818069,
          Subtitle = "Cheers. I'll head off, then."
        },
        [71007106] = {
          ContentFR = "Un certain temps plus tard...",
          DialogueId = 71007106,
          GUID = "B1C24354",
          SpeakNpcId = 800006,
          Subtitle = "(Some time later...)"
        },
        [71007107] = {
          ContentFR = "Au moment où vous récupérez le sablé, un enfant vous observe derrière vous, le regard plein d’espoir.",
          DialogueId = 71007107,
          GUID = "B1C2437E",
          SpeakNpcId = 800006,
          Subtitle = "(Just as you collect the snack, you notice a child behind you gazing at it longingly.)"
        },
        [71007108] = {
          ContentFR = "Euh... Est-ce que je pourrais vous acheter votre sablé aux noix avec cet argent ? Ma maman adore ceux d’ici, mais elle est malade en ce moment... J’aimerais lui en rapporter un...",
          DialogueId = 71007108,
          GUID = "B1C243A8",
          NextOptions = {
            [1] = 710071081,
            [2] = 710071082
          },
          SpeakNpcId = 818070,
          Subtitle = "Um... could you sell yours to me? My mum really likes their walnut shortbread, but she's been ill lately... I wanted to take some home for her...",
          bForbidSkipOptions = true
        },
        [71007109] = {
          ContentFR = "Dans ce cas, prends-le. J’espère que ta maman ira vite mieux.",
          DialogueId = 71007109,
          GUID = "B1C243D2",
          NextDialogue = 710071091,
          SpeakNpcId = 100001,
          Subtitle = "In that case, you should take it. I hope your mum gets better soon."
        },
        [71007110] = {
          ContentFR = "Ah, vous voilà ! Alors, où est le sablé ?",
          DialogueId = 71007110,
          GUID = "B1C243FC",
          NextDialogue = 71007111,
          SpeakNpcId = 818069,
          Subtitle = "Ah, there you are — where is it?"
