        [71007201] = {
          ContentFR = "Hmm.. laquelle choisir...",
          DialogueId = 71007201,
          GUID = "B1C252EA",
          SpeakNpcId = 818074,
          Subtitle = "Hmm... which one should I go for...?"
        },
        [71007203] = {
          ContentFR = "Oh ! Vous arrivez à point. J’ai toujours du mal à me décider quand j’achète quelque chose. Pourriez-vous m’aider à comparer et me donner votre avis ?",
          DialogueId = 71007203,
          GUID = "B1C2533E",
          NextOptions = {
            [1] = 710072031,
            [2] = 710072032
          },
          SpeakNpcId = 818074,
          Subtitle = "Oh — sorry to bother you. I can never decide what to buy. Could I trouble you to take a look and give me a bit of advice?",
          bForbidSkipOptions = true
        },
        [71007204] = {
          ContentFR = "Un grand merci. Je vous attends ici.",
          DialogueId = 71007204,
          GUID = "B1C25368",
          SpeakNpcId = 818074,
          Subtitle = "Thank you so much. I'll wait right here."
        },
        [71007206] = {
          ContentFR = "Tout ce que je vends est de première qualité, transporté depuis les lieux d’origine, avec la certification officielle d’Éternel Printemps. C’est un peu plus cher, certes, mais chaque pièce vaut son prix.",
          DialogueId = 71007206,
          GUID = "B1C253BC",
          SpeakNpcId = 818072,
          Subtitle = "Everything I sell is premium stock, brought in directly from its place of origin. Most of it has travelled thousands of miles before reaching my stall, and every item comes with EverSpring's official certification. They may cost a little more, but you really do get what you pay for."
        },
        [71007207] = {
          ContentFR = "Bah, ce sont des objets du quotidien. Haut de gamme ou pas, quelle différence ?\nLes miens sont moins chers et plus rentables. Vous ne trouvez pas ?",
          DialogueId = 71007207,
          GUID = "B1C253E6",
          SpeakNpcId = 818073,
          Subtitle = "It's all everyday necessities — \"premium\" doesn't really mean a thing. My goods are much cheaper, and that makes them the better deal. Don't you agree?"
        },
        [71007208] = {
          ContentFR = "Après avoir soigneusement observé les marchandises, vous avez fait votre choix. Il est temps de retourner donner votre avis au voyageur indécis.",
          DialogueId = 71007208,
          GUID = "B1C25410",
          SpeakNpcId = 800006,
          Subtitle = "(After looking everything over, you've made your choice. Time to head back and tell the indecisive traveller what you think.)"
        },
        [71007209] = {
          ContentFR = "Alors ? Selon vous, lequel vend les meilleurs produits ?",
          DialogueId = 71007209,
          GUID = "B1C2543A",
          NextOptions = {
            [1] = 710072091,
            [2] = 710072092
          },
          SpeakNpcId = 818074,
          Subtitle = "Well? Which one do you think is the better buy?",
          bForbidSkipOptions = true
        },
        [71007210] = {
          ContentFR = "Très bien, je vais suivre votre conseil ! Merci beaucoup !",
          DialogueId = 71007210,
          GUID = "B1C25464",
          SpeakNpcId = 818074,
          Subtitle = "Right then, I'll go with him! Thanks for the advice!"
        },
        [71007301] = {
          ContentFR = "Les ennemis errants affluent de toutes parts. Repoussez-les avant de libérer le Géniemon.",
          DialogueId = 71007301,
          GUID = "B1C26352",
          SpeakNpcId = 800006,
