          DialogueId = 71007302,
          GUID = "B1C2637C",
          SpeakNpcId = 800006,
          Subtitle = "(The sounds of battle have drawn in additional enemies.)"
        },
        [71007303] = {
          ContentFR = "La zone est temporairement sécurisée. Profitez-en pour libérer le Géniemon.",
          DialogueId = 71007303,
          GUID = "B1C263A6",
          SpeakNpcId = 800006,
          Subtitle = "(The area is clear for the moment. Now's your chance to free the Geniemon.)"
        },
        [71007401] = {
          Content = "（周围突然出现了应天侍，准备应敌）（待包装）",
          DialogueId = 71007401,
          GUID = "B1C273BA",
          SpeakNpcId = 800006
        },
        [71007501] = {
          ContentFR = "Hé ! Arrêtez, arrêtez ! Vous avez tout raflé ! Qu’est-ce que je vais vendre, moi ? Quelqu’un... quelqu’un pourrait m’aider ?",
          DialogueId = 71007501,
          GUID = "B1C28422",
          SpeakNpcId = 818078,
          Subtitle = "Hey— stop! Quit it! If you clear me out, what am I supposed to sell? Someone— anyone— give me a hand!"
        },
        [71007502] = {
          ContentFR = "En vous approchant, vous découvrez un homme abattu, accroupi au sol. Autour de lui, des lambeaux de pommes de terre sont éparpillés partout.",
          DialogueId = 71007502,
          GUID = "B1C2844C",
          NextDialogue = 71007503,
          SpeakNpcId = 800006,
          Subtitle = "(As you draw nearer, you find a miserable-looking man slumped on the ground, shreds of potato scattered all around him.)"
        },
        [71007503] = {
          ContentFR = "Vous avez l’air de savoir vous débrouiller... Aidez-moi un peu, je vous en prie !",
          DialogueId = 71007503,
          GUID = "B1C28476",
          NextOptions = {
            [1] = 710075031,
            [2] = 710075032
          },
          SpeakNpcId = 818078,
          Subtitle = "Sorry to trouble you — but you look like someone dependable. Could you give me a hand?"
        },
        [71007504] = {
          ContentFR = "Mille mercis, mille mercis ! Voilà le problème : dès que je mets un peu de pommes de terre sur mon étal, les Mouettes nuageuses du port deviennent complètement folles et se ruent dessus. Regardez... comme ça...",
          DialogueId = 71007504,
          GUID = "B1C284A0",
          SpeakNpcId = 818078,
          Subtitle = "Thanks — really. Here's the situation: every time I put out so much as a handful of shredded potato, the Skywing Gulls down by the docks absolutely lose their minds and mob the stall. Watch — like this..."
        },
        [71007505] = {
          ContentFR = "L’homme ramasse avec précaution quelques filaments de pommes de terre. Aussitôt, plusieurs Mouettes nuageuses battent des ailes et commencent à tournoyer autour de vous.",
          DialogueId = 71007505,
          GUID = "B1C284CA",
          SpeakNpcId = 800006,
          Subtitle = "(He gingerly gathers a few stray shreds. Almost at once, several Skywing Gulls swoop in, circling overhead.)"
        },
        [71007506] = {
          ContentFR = "Aaaah... Vous voyez, vous voyez ? Elles reviennent ! Vite, aidez-moi à les chasser, je vous en supplie...",
          DialogueId = 71007506,
          GUID = "B1C284F4",
          NextDialogue = 71007507,
          SpeakNpcId = 818078,
          Subtitle = "Ahhhh—! See? See!? They're back again! Please... help me chase them off!"
        },
        [71007507] = {
          ContentFR = "Les mouettes tournoient sans relâche, se rapprochant à la moindre ouverture. On dirait que leur raison d’être se résume aux pommes de terre, et que leur unique but dans la vie est de les arracher des mains de l’homme.",
          DialogueId = 71007507,
          GUID = "B1C2851E",
          SpeakNpcId = 800006,
          Subtitle = "(The Skywing Gulls wheel above you in tight circles, edging closer whenever they think they can snatch a bite— as if their entire existence revolved around shredded potatoes.)"
        },
        [71007508] = {
          ContentFR = "Ouf... Vendre des pommes de terre sur les quais, c’est bien plus dangereux que je ne l’imaginais. Merci... vraiment merci.",
          DialogueId = 71007508,
          GUID = "B1C28548",
          SpeakNpcId = 818078,
          Subtitle = "Whew... selling potatoes on the docks is far more dangerous than I thought. Thank you so much..."
        },
        [71007601] = {
          Content = "鱼怎么还不上钩，难道是我刚买的鱼竿的问题吗（待包装）",
          DialogueId = 71007601,
          GUID = "B1C2948A",
          SpeakNpcId = 818079
        },
        [71007602] = {
          Content = "这位朋友你会钓鱼吗，我在这怎么也钓不到鱼，你能在一旁给我演示一下吗（待包装）",
          DialogueId = 71007602,
          GUID = "B1C294B4",
          NextOptions = {
