        },
        [71007801] = {
          ContentFR = "Toi, là-bas... {性别:Chasseur de Phoxène|Chasseuse de Phoxène}. Pourrais-tu t’approcher un instant ?",
          DialogueId = 71007801,
          GUID = "B1C2B55A",
          SpeakNpcId = 818082,
          Subtitle = "Hey — Phoxhunter. Have you a moment to spare?"
        },
        [71007802] = {
          ContentFR = "J’ai récemment mis au point un nouvel encens capable d’éveiller l’inconscient enfoui dans l’esprit. Accepterais-tu de m’aider à mener une expérience ? Il te suffira de l’allumer, puis de me décrire ce que tu verras.",
          DialogueId = 71007802,
          GUID = "B1C2B584",
          NextOptions = {
            [1] = 710078021,
            [2] = 710078022
          },
          SpeakNpcId = 818082,
          Subtitle = "I've been working on a new incense that awakens what lies buried in the mind. Would you help me test it? Just light it, and then tell me what you see.",
          bForbidSkipOptions = true
        },
        [71007803] = {
          ContentFR = "Parfait. Va donc allumer l’encens dans ce brûle-parfum.",
          DialogueId = 71007803,
          GUID = "B1C2B5AE",
          SpeakNpcId = 818082,
          Subtitle = "Good. You can start by lighting the incense in the censer over there."
        },
        [71007804] = {
          ContentFR = "Une fragrance étrange s’insinue dans vos narines. Vos pensées se dispersent, se fondant peu à peu dans l’environnement qui vous entoure.",
          DialogueId = 71007804,
          GUID = "B1C2B5D8",
          NextDialogue = 71007805,
          SpeakNpcId = 800006,
          Subtitle = "(A strange fragrance threads into your senses. Your thoughts begin to drift outward, scattering across the world around you.)"
        },
        [71007805] = {
          ContentFR = "Une question émerge au plus profond de votre esprit — qu’est-ce que vous désirez le plus en cet instant ?",
          DialogueId = 71007805,
          GUID = "B1C2B602",
          NextOptions = {
            [1] = 710078051,
            [2] = 710078052,
            [3] = 710078053
          },
          SpeakNpcId = 800006,
          Subtitle = "(A question rises within you — what is it you desire most in this moment?)",
          bForbidSkipOptions = true
        },
        [71007806] = {
          ContentFR = "Des coffres surgissent soudainement tout autour de vous.",
          DialogueId = 71007806,
          GUID = "B1C2B62C",
          SpeakNpcId = 800006,
          Subtitle = "(Chests appear around you in an instant.)"
        },
        [71007807] = {
