            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F5934",
          NextDialogue = 72001203,
          SpeakNpcId = 820000,
          Subtitle = "This tree looks tired... It's just lying down for a nap."
        },
        [72001203] = {
          ContentFR = "Alors... la neige tombée au sol... peut-être qu’elle aussi a fini par se lasser de voler, et s’est posée pour se reposer ?",
          DialogueId = 72001203,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F595E",
          NextDialogue = 72001204,
          SpeakNpcId = 820000,
          Subtitle = "Do you think the snow on the ground is tired too? Maybe it just wanted a little rest."
