          bAllowClickSkipScript = false
        },
        [72001602] = {
          ContentFR = "Cette montagne est si haute ! Si brillante ! Et moi, tout en haut ! Je suis incroyable !",
          DialogueId = 72001602,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F9AD4",
          NextDialogue = 72001603,
          SpeakNpcId = 820000,
          Subtitle = "This mountain is so tall! So bright! Look at me — on the top! I'm amazing!"
        },
        [72001603] = {
          ContentFR = "<I>Yiiiip ! </>Ce n’est pas une montagne ? Mais alors... ?",
          DialogueId = 72001603,
          FacialId = {
            [1] = "820000:PetPan_Speechless"
          },
          GUID = "B43F9AFE",
          NextDialogue = 72001604,
          SpeakNpcId = 820000,
          Subtitle = "Eeya? This isn't a mountain? Uh-uh!"
        },
        [72001604] = {
          ContentFR = "C’est grand, c’est pointu... donc c’est une montagne !",
          DialogueId = 72001604,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43F9B28",
          NextDialogue = 72001605,
          SpeakNpcId = 820000,
          Subtitle = "It's tall and pointy... totally a mountain!"
