          bAllowClickSkipScript = false
        },
        [72001702] = {
          ContentFR = "Si tu vois bien le chemin sous tes pieds... tu n’auras plus peur des Souillés, pas vrai ?",
          DialogueId = 72001702,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43FAB3C",
          NextDialogue = 72001703,
          SpeakNpcId = 820000,
          Subtitle = "If you can see the path right under your feet... Would you still be less scared of the Filthoids?"
        },
        [72001703] = {
          ContentFR = "Tadaa ! Voilà, tout est illuminé.",
          DialogueId = 72001703,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B43FAB66",
