        [72002301] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72002301,
          DialoguePanelType = "AllHide",
          FacialId = {
