          },
          GUID = "B4400D82",
          NextDialogue = 72002302,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72002302] = {
          ContentFR = "Les fleurs sont si généreuses... Tous ceux qui les reçoivent sourient.",
          DialogueId = 72002302,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4400DAC",
          NextDialogue = 72002303,
          SpeakNpcId = 820000,
          Subtitle = "Flowers are so kind. They always make people smile."
        },
        [72002303] = {
          ContentFR = "Et si, en secret... elles chuchotaient des mots doux à leurs destinataires ?",
          DialogueId = 72002303,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4400DD6",
          NextDialogue = 72002304,
          SpeakNpcId = 820000,
          Subtitle = "Do you think they whisper little secrets to them when we're not looking?"
        },
        [72002304] = {
          DialogueId = 72002304,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4400E00",
