          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72002602] = {
          ContentFR = "Mmh... Merci de m’avoir construit une maison.",
          DialogueId = 72002602,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4403EE4",
          NextDialogue = 72002603,
          SpeakNpcId = 820000,
          Subtitle = "Mm~ Thank you for building a cabin for me."
        },
        [72002603] = {
          ContentFR = "Si un jour tu grandis assez pour m’arriver à l’épaule, je t’invite à venir vivre ici. On sera voisins.",
          DialogueId = 72002603,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4403F0E",
          NextDialogue = 72002604,
          SpeakNpcId = 820000,
          Subtitle = "If you ever grow as tall as me, you can move in too — and we'll be neighbours."
        },
        [72002604] = {
