          bAllowClickSkipScript = false
        },
        [72002802] = {
          ContentFR = "<I>Cling cling ! Clang clang !</>",
          DialogueId = 72002802,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4405FB4",
          NextDialogue = 72002803,
          SpeakNpcId = 820000,
          Subtitle = "Ding ding ding~! Clink clink clink!"
        },
        [72002803] = {
          ContentFR = "C’est ainsi que chantent les bouteilles ! Alors ? Est-ce que je les imite bien ?",
          DialogueId = 72002803,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4405FDE",
          NextDialogue = 72002804,
          SpeakNpcId = 820000,
          Subtitle = "That's how the bottles sing! ...Well? Did I get it right?"
        },
        [72002804] = {
