          },
          GUID = "B44090C2",
          NextDialogue = 72002902,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72002902] = {
          Content = "咿呀——！请不要拿走这个宝箱。",
          DialogueId = 72002902,
          FacialId = {
            [1] = "820000:PetPan_Wink"
          },
          GUID = "B44090C3",
          NextDialogue = 72002903,
          SpeakNpcId = 820000,
          Subtitle = "Eek! Please don't take that treasure chest!"
        },
        [72002903] = {
          Content = "我的家被坏老鼠占领了，我正打算用这些钱去雇一只勇敢的小猫，帮我赶跑老鼠。",
          DialogueId = 72002903,
          FacialId = {
            [1] = "820000:PetPan_Dizzy"
          },
          GUID = "B44090C4",
          NextDialogue = 72002904,
          SpeakNpcId = 820000,
          Subtitle = "My home's been taken over by nasty rats! I was gonna use these coins to hire a brave little cat to chase them away."
        },
        [72002904] = {
          DialogueId = 72002904,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B44090C5",
          Scripts = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72003001] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72003001,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440805A",
          NextDialogue = 72003002,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72003002] = {
          Content = "哇，你好厉害，唰唰——咻咻——几下就把附近的老鼠全消灭了。",
          DialogueId = 72003002,
          FacialId = {
            [1] = "820000:PetPan_Smile"
          },
          GUID = "B4408084",
          NextDialogue = 72003003,
          SpeakNpcId = 820000,
          Subtitle = "Whoa, you're amazing! Whoosh—swish—BAM! You wiped out all the rats!"
        },
        [72003003] = {
          Content = "那么，这个宝箱就送给你啦。",
          DialogueId = 72003003,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B44080AE",
          NextDialogue = 72003004,
          SpeakNpcId = 820000,
          Subtitle = "Thank you, you can have this chest!"
        },
        [72003004] = {
          DialogueId = 72003004,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B44080D8",
          Scripts = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72003101] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72003101,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B44090EB",
          NextDialogue = 72003102,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72003102] = {
          ContentFR = "Que cherches-tu ?",
          DialogueId = 72003102,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B44090EC",
          NextDialogue = 72003103,
          SpeakNpcId = 820000,
          Subtitle = "What are you looking for?"
        },
        [72003103] = {
          ContentFR = "Si ce n’est pas moi, je peux t’aider à trouver.",
          DialogueId = 72003103,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4409116",
          NextDialogue = 72003104,
          SpeakNpcId = 820000,
          Subtitle = "If you're not looking for me, I can help."
        },
        [72003104] = {
          DialogueId = 72003104,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B4409140",
          Scripts = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72003301] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72003301,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440B192",
          NextDialogue = 72003302,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72003302] = {
          ContentFR = "Beaucoup sont venus... Beaucoup sont repartis.",
          DialogueId = 72003302,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440B1BC",
          NextDialogue = 72003303,
          SpeakNpcId = 820000,
          Subtitle = "So many people came, and so many left."
        },
        [72003303] = {
          ContentFR = "Trop d’odeurs, je n’arrive pas à toutes les retenir... Et toi, tu t’en souviens ?",
          DialogueId = 72003303,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440B1E6",
          NextDialogue = 72003304,
          SpeakNpcId = 820000,
          Subtitle = "So many scents lingering... I can't remember them all. Can you?"
        },
        [72003304] = {
          DialogueId = 72003304,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440B210",
          Scripts = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72003401] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72003401,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C223",
          NextDialogue = 72003402,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{820000},AnimationId{\"Wuyou_Born\"}}",
          bAllowClickSkipScript = false
        },
        [72003402] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Voici mon trésor ! Seuls ceux qui triomphent de l’épreuve de sagesse peuvent entrer !",
          DialogueId = 72003402,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C224",
          NextDialogue = 72003403,
          SpeakNpcId = 820000,
          Subtitle = "This is my treasure trove! Only those who pass the trial of wisdom may enter!"
        },
        [72003403] = {
          ContentFR = "Alors dis-moi... ici, dans cette forteresse... quelle couleur te laisse passer ?",
          DialogueId = 72003403,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C24E",
          SpeakNpcId = 820000,
          Subtitle = "So tell me — here, in this fortress... What colour lets you through?",
          TalkOptions = {
            [1] = 72003404,
            [2] = 72003405,
            [3] = 72003406
          }
        },
        [72003404] = {
          ContentFR = "<I>Bleu !</>",
          DialogueId = 72003404,
          GUID = "B440C278",
          ImprPlusId = 1003,
          Subtitle = "Blue!"
        },
        [72003405] = {
          ContentFR = "<I>Rouge !</>",
          DialogueId = 72003405,
          GUID = "B440C2A2",
          ImprPlusId = 1016,
          Subtitle = "Red!"
        },
        [72003406] = {
          ContentFR = "<I>Orange !</>",
          DialogueId = 72003406,
          GUID = "B440C2CC",
          ImprPlusId = 1016,
          Subtitle = "Orange!"
        },
        [72003407] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Exact ! Tu as choisi la couleur du passage ! Alors je t’ouvre la voie !",
          DialogueId = 72003407,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C2F6",
          NextDialogue = 72003409,
          SpeakNpcId = 820000,
          Subtitle = "That's right! You picked the right colour — so in you go!"
        },
        [72003408] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non... réfléchis encore. Plus fort, bien plus fort !",
          DialogueId = 72003408,
          FacialId = {
            [1] = "820000:PetPan_Common"
          },
          GUID = "B440C320",
          NextDialogue = 72003409,
          Scripts = "PlayAnimation{ActorId{820000},AnimationId{\"Wuyou_Disagree\"}}",
          SpeakNpcId = 820000,
          Subtitle = "Nope! Have another think. A really good one this time!",
          bAllowClickSkipScript = false
