        },
        [72100102] = {
          ContentFR = "Quand les faux-semblants s’effacent, le cœur véritable apparaît.\nPréservé de la poussière du monde, il demeure clair, tel qu’à l’origine.",
          DialogueId = 72100102,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EBAFC",
          NextDialogue = 72100103,
          SpeakNpcId = 830001,
          Subtitle = [[
Strip away the fleeting fame, and the true heart is revealed.
Untouched by worldly dust, its original clarity remains.]]
        },
        [72100103] = {
          ContentFR = "{性别:Ami venu|Amie venue} de loin, en écartant les fleurs écloses, as-tu entrevu la limpidité de ton propre cœur ?",
          DialogueId = 72100103,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EBB26",
          NextDialogue = 72100104,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Traveler from afar, as you brush aside the blossoms of your past, have you glimpsed your own bright and clear heart?",
          bAllowClickSkipScript = false
        },
        [72100104] = {
          DialogueId = 72100104,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
