          GUID = "B47ECB3A",
          NextDialogue = 72100202,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100202] = {
          ContentFR = "On dirait que j’ai fait un rêve ancien... Un très beau rêve.",
          DialogueId = 72100202,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47ECB64",
          NextDialogue = 72100203,
          SpeakNpcId = 830001,
          Subtitle = "Feels like I had a long, beautiful dream..."
        },
        [72100203] = {
          ContentFR = "Je rêvais de mon enfance... Ma mère me tenait la main, nous allions au débarcadère acheter des figurines en sucre.",
          DialogueId = 72100203,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47ECB8E",
          NextDialogue = 72100204,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "I dreamed of when I was a child, holding my mother's hand, going to the wharf to buy a sugar figurine.",
          bAllowClickSkipScript = false
        },
        [72100204] = {
          DialogueId = 72100204,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
