          GUID = "B47EDBA2",
          NextDialogue = 72100302,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100302] = {
          ContentFR = "Le soleil va m’attraper ! C’est de ta faute, je me suis fait attraper par le soleil !",
          DialogueId = 72100302,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EDBCC",
          NextDialogue = 72100303,
          SpeakNpcId = 830001,
          Subtitle = "The sun's gonna catch me! It's all your fault — I‘ve been caught by the sun!"
        },
        [72100303] = {
          ContentFR = "Hmm... Plutôt que d’être attrapé par le soleil, je préférerais l’être par toi...",
          DialogueId = 72100303,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EDBF6",
          NextDialogue = 72100304,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Hmm... I'd rather be caught by you than by the sun...",
          bAllowClickSkipScript = false
