          NextDialogue = 72100402,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100402] = {
          ContentFR = "Quel est ce parfum qui flotte dans l’air ? Du Lys céleste... ou peut-être du Printemps d’Excellence ?",
          DialogueId = 72100402,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EEC34",
          NextDialogue = 72100403,
          SpeakNpcId = 830001,
          Subtitle = "What's that scent drifting on the air? Skylily? Or perhaps Vernal Prime?"
        },
        [72100403] = {
          ContentFR = "Ce n’est pas aussi bon que ma propre composition... Quel dommage... Je ne pourrai plus jamais la recréer.",
          DialogueId = 72100403,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EEC5E",
          NextDialogue = 72100404,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Not as good as my own blend. A pity... I can't make it anymore.",
          bAllowClickSkipScript = false
