          GUID = "B47EFC72",
          NextDialogue = 72100502,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100502] = {
          ContentFR = "Liang Qing, mon enfant ! Te portes-tu bien ?",
          DialogueId = 72100502,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EFC9C",
          NextDialogue = 72100503,
          SpeakNpcId = 830001,
          Subtitle = "Liang Qing, my child! Are you well?"
        },
        [72100503] = {
          ContentFR = "Hein... ? Ce n’est pas mon enfant ? Alors... qui es-tu ?",
          DialogueId = 72100503,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47EFCC6",
          NextDialogue = 72100504,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Oh? Not my child? Then who... are you?",
          bAllowClickSkipScript = false
        },
        [72100504] = {
          DialogueId = 72100504,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
