          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100602] = {
          ContentFR = "Si je grimpe jusqu’au sommet d’un arbre immense, pourrai-je me rapprocher de Taihao ?",
          DialogueId = 72100602,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F0D04",
          NextDialogue = 72100603,
          SpeakNpcId = 830001,
          Subtitle = "If I climb a tall tree all the way up, can I get closer to Lord Taihao?"
        },
        [72100603] = {
          ContentFR = "Combien de temps faudrait-il ? Dix ans... cent ans... Est-ce que cela suffirait ?",
          DialogueId = 72100603,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F0D2E",
          NextDialogue = 72100604,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "How long would it take? Ten years? A hundred? Would that be enough?",
          bAllowClickSkipScript = false
        },
        [72100604] = {
          DialogueId = 72100604,
          DialoguePanelType = "AllHide",
