          },
          GUID = "B47F3E12",
          NextDialogue = 72100902,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72100902] = {
          ContentFR = "Quelle couleur préfères-tu ? Vert fève... ou gris grue ?",
          DialogueId = 72100902,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F3E3C",
          NextDialogue = 72100903,
          SpeakNpcId = 830001,
          Subtitle = "What's your favourite colour? Light green, or crane-gray?"
        },
        [72100903] = {
          ContentFR = "Moi ? J’aime le bleu des nuages et de l’eau. Bleu... comme mon corps.",
          DialogueId = 72100903,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F3E66",
          NextDialogue = 72100904,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "I love cloud-water blue. Just like my... body.",
          bAllowClickSkipScript = false
