          GUID = "B47F4E7A",
          NextDialogue = 72101002,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101002] = {
          ContentFR = "La Poussière-corrompue recouvre tout, elle engloutit le ciel. Impossible de distinguer la direction, ni même le chemin parcouru...",
          DialogueId = 72101002,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F4EA4",
          NextDialogue = 72101003,
          SpeakNpcId = 830001,
          Subtitle = "The Gritblight blots out the sky. No sense of direction, can't even tell where I came from..."
        },
        [72101003] = {
          ContentFR = "Heureusement que tu es là pour me guider. Merci à toi, {性别:ami venu|amie venue} de loin.",
          DialogueId = 72101003,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F4ECE",
          NextDialogue = 72101004,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Lucky to have you show me the way. Thank you, friend from afar.",
          bAllowClickSkipScript = false
        },
        [72101004] = {
          DialogueId = 72101004,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
