          },
          GUID = "B47F5EE2",
          NextDialogue = 72101102,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101102] = {
          ContentFR = "Eh hé hé ! Tu m’as trouvé ! Tout se déroule exactement selon mon plan !",
          DialogueId = 72101102,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F5F0C",
          NextDialogue = 72101103,
          SpeakNpcId = 830001,
          Subtitle = "E-hehe! You found me! All according to my grand scheme!"
        },
        [72101103] = {
          ContentFR = "Conformément au plan, l’étape suivante consiste à te remettre ceci !",
          DialogueId = 72101103,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F5F36",
          NextDialogue = 72101104,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "As planned, the next step is to give you this!",
          bAllowClickSkipScript = false
