          NextDialogue = 72101303,
          SpeakNpcId = 830001,
          Subtitle = "Water strikes stone, soaks the earth, and gives life to all things."
        },
        [72101303] = {
          ContentFR = "On dit qu’à la fin, tout le monde se rend en un lieu appelé le Fleuve de l’Oubli... Dis-moi, est-ce aussi un ruisseau comme celui-ci ?",
          DialogueId = 72101303,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F8006",
          NextDialogue = 72101304,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "I've heard that in the end, everyone goes to a place called the River of Forgetting. Is this river... a stream like this one too?",
          bAllowClickSkipScript = false
        },
        [72101304] = {
          DialogueId = 72101304,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F8030",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72101401] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72101401,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F901A",
          NextDialogue = 72101402,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101402] = {
          ContentFR = "Les roseaux sont hauts, si hauts, ils cachent tout à l’intérieur, on ne voit rien.",
          DialogueId = 72101402,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F9044",
          NextDialogue = 72101403,
          SpeakNpcId = 830001,
          Subtitle = "Reeds so tall, tall and deep. Hide inside, secrets keep."
        },
        [72101403] = {
          ContentFR = "Hihi~ Sans cette clairière dégarnie dans les roseaux, comment aurais-tu pu me trouver ?",
          DialogueId = 72101403,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F906E",
          NextDialogue = 72101404,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Hehe, if not for this bald patch in the reeds, how could you ever have found me?",
          bAllowClickSkipScript = false
        },
        [72101404] = {
          DialogueId = 72101404,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47F9098",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72101501] = {
          Camera = "196.204834,-2.952158,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72101501,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FA082",
          NextDialogue = 72101502,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101502] = {
          ContentFR = "Comment cette pierre pointue s’est-elle formée ? Je l’observe depuis si longtemps...",
          DialogueId = 72101502,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FA0AC",
          NextDialogue = 72101503,
          SpeakNpcId = 830001,
          Subtitle = "How was this sharp stone formed? I've been watching it for so long."
        },
        [72101503] = {
          ContentFR = "Elle est si effilée... Elle ferait une lance parfaitement acérée.",
          DialogueId = 72101503,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FA0D6",
          NextDialogue = 72101504,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "It's so sharp. It would make a perfect, keen spear.",
          bAllowClickSkipScript = false
        },
        [72101504] = {
          DialogueId = 72101504,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FA100",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72101601] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72101601,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FB0EA",
          NextDialogue = 72101602,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101602] = {
          ContentFR = "La pente ! La pente ! Porté par le vent, foulant les fleurs, je dévale la pente à toute allure !",
          DialogueId = 72101602,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FB114",
          NextDialogue = 72101603,
          SpeakNpcId = 830001,
          Subtitle = "The slope calls! I ride the wind, tread the blooms, and race it to the bottom!"
        },
        [72101603] = {
          ContentFR = "Youhou ! Ne m’arrête pas !",
          DialogueId = 72101603,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FB13E",
          NextDialogue = 72101604,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "Woo-hoo! Don't try to stop me!",
          bAllowClickSkipScript = false
        },
        [72101604] = {
          DialogueId = 72101604,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FB168",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72101701] = {
          Camera = "196.204834,-2.952148,87.243896,0.0,-7.999989,179.200043,35.0,100000.0,false,DoNotOverride,2.8",
          DialogueId = 72101701,
          DialoguePanelType = "AllHide",
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FC152",
          NextDialogue = 72101702,
          Scripts = "PlayAnimation{Sync{true},Duration{1},ActorId{830001},AnimationId{\"Wuyou_Born\"}}"
        },
        [72101702] = {
          ContentFR = "Ces teintes jaune éclatant... Sont-ce des feuilles mortes, ou des pétales ?",
          DialogueId = 72101702,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FC17C",
          NextDialogue = 72101703,
          SpeakNpcId = 830001,
          Subtitle = "These bright yellow colours... Are they fallen leaves, or petals?"
        },
        [72101703] = {
          ContentFR = "Je ne sais pas... Mais ce qui m’enveloppe est rose et violet. Tu m’as repéré au premier regard, n’est-ce pas ?",
          DialogueId = 72101703,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FC1A6",
          NextDialogue = 72101704,
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Agree\"}}",
          SpeakNpcId = 830001,
          Subtitle = "I don't know... But what envelops me is pink and purple. You must have spotted that right away, didn't you?",
          bAllowClickSkipScript = false
        },
        [72101704] = {
          DialogueId = 72101704,
          DialoguePanelType = "AllHide",
          Duration = 0.63,
          FacialId = {
            [1] = "830001:PetPan_Common"
          },
          GUID = "B47FC1D0",
          Scripts = "PlayAnimation{ActorId{830001},AnimationId{\"Wuyou_Disappear\"}}",
          bAllowClickSkipScript = false
        },
        [72999999] = {
          DialogueId = 72999999,
          DialoguePanelType = "AllHide",
          Duration = 1.4,
          GUID = "B6BF7256"
        },
        [73000201] = {
          ContentFR = "J’ai amélioré ce dispositif. Allez, essaie encore, aide-moi à tester ces réglages. Ça m’a coûté une fortune de le faire venir d’Élysium... Cette fois, tu n’y échapperas pas !",
          DialogueId = 73000201,
          GUID = "B6BF937A",
          SpeakNpcId = 818022,
          Subtitle = "I gave this thing another upgrade — go on, give it a whirl and help me test the tweaks. Cost me a fortune to smuggle in from Elysium, y'know. No way you're getting through this time!"
        },
        [73000202] = {
          ContentFR = "Tu veux retenter ? D’accord. Tsss... vous, les acrobates, vous adorez bondir partout.",
          DialogueId = 73000202,
          GUID = "B6BF93A4",
          SpeakNpcId = 818022,
          Subtitle = "You wanna go again? Sure, why not. You nimble types really love bouncing around, huh?"
        },
        [73000203] = {
          ContentFR = "Hein ? Tu as encore réussi ?! Échoue au moins une fois... Non, il faut que je l’optimise davantage.",
          DialogueId = 73000203,
          GUID = "B6BF93CE",
          SpeakNpcId = 818022,
          Subtitle = "What!? Again...? Can't you just fail once? Fine, fine... guess it still needs a bit more work."
        },
        [73000204] = {
          ContentFR = "Oui, voilà, c’est l’effet que je voulais ! Même si, honnêtement... je ne sais pas encore vraiment à quoi ça sert. Mais ça trouvera bien une utilité !",
          DialogueId = 73000204,
          GUID = "B6BF93F8",
          SpeakNpcId = 818022,
          Subtitle = "Yep, that's more like it! Honestly? Still not sure what practical use it has... but hey, gotta be good for something."
        },
        [73000301] = {
          ContentFR = "Te revoilà... pile quand je venais d’apporter une nouvelle amélioration. La dernière version était trop facile, mais cette fois... je parie que tu vas trébucher.",
          DialogueId = 73000301,
          GUID = "B6BFA3E2",
          SpeakNpcId = 818022,
          Subtitle = "You're back. Good timing — I gave it another upgrade. Last one was way too easy. But this time? I bet you'll trip at least once."
        },
        [73000302] = {
          ContentFR = "Tu veux retenter ? D’accord. Tsss... vous, les acrobates, vous adorez bondir partout.",
          DialogueId = 73000302,
          GUID = "B6BFA40C",
          SpeakNpcId = 818022,
          Subtitle = "You wanna go again? Sure, why not. You nimble types really love bouncing around, huh?"
        },
        [73000303] = {
          ContentFR = "Quoi ?! Tu as encore réussi ? Impossible... J’ai dépensé des tas de pièces pour l’améliorer, je n’abandonnerai pas. Attends un peu, la prochaine fois je t’aurai !",
          DialogueId = 73000303,
          GUID = "B6BFA436",
          SpeakNpcId = 818022,
          Subtitle = "Again!? Seriously!? I've poured so much into upgrading this thing... But I'm not giving up! Just you wait — I'll get you next time!"
        },
        [73000304] = {
          ContentFR = "Héhé... en te voyant gesticuler comme ça, j’ai eu une idée. Je vais en parler à mon supérieur : installer ce dispositif aux portes de Givrelac, pour empêcher toute intrusion...",
          DialogueId = 73000304,
          GUID = "B6BFA460",
          SpeakNpcId = 818022,
          Subtitle = "Hah! Watching you flail around just now gave me an idea. I'll pitch it to my superior — slap this baby on the Icelake gates and stop anyone from barging in!"
        },
        [73000401] = {
          ContentFR = "Enfin te voilà ! Je t’attendais. Cette fois, j’ai investi toutes mes économies pour rendre ce mécanisme dévastateur. Il est parfait désormais... tu n’as aucune chance de passer !",
          DialogueId = 73000401,
          GUID = "B6BFB44A",
          SpeakNpcId = 818022,
          Subtitle = "There you are! I've been waiting. I poured every last coin into this baby — she's a beast now. No way you're getting through this time."
        },
        [73000402] = {
          ContentFR = "Tu veux retenter ? D’accord. Tsss... vous, les acrobates, vous adorez bondir partout.",
          DialogueId = 73000402,
          GUID = "B6BFB474",
          SpeakNpcId = 818022,
          Subtitle = "You wanna go again? Sure, why not. You nimble types really love bouncing around, huh?"
        },
        [73000403] = {
          ContentFR = "Encore... encore raté ?! Assez ! J’aurais dû savoir qu’on ne peut rien attendre de la camelote d’Élysium. Voilà le prix de ma désobéissance à Sa Majesté...",
          DialogueId = 73000403,
          GUID = "B6BFB49E",
          SpeakNpcId = 818022,
          Subtitle = "Again!? Are you kidding me!? Ugh... Y'know what, forget it. I should've known better than to trust Elysian tech. This is what I get for smuggling their junk behind His Majesty's back."
        },
        [73000404] = {
          ContentFR = "Bah ! Je laisse ce truc ici. Amuse-toi avec si ça te chante... On dirait que ça t’amuse de toute façon.",
          DialogueId = 73000404,
          GUID = "B6BFB4C8",
          SpeakNpcId = 818022,
          Subtitle = "Fine. I'm leaving this thing right here. Do what you want with it. Not like you're not having fun anyway."
        },
        [73000405] = {
          ContentFR = "Eh bah alors ? Tu as goûté à sa puissance ? Héhé... Je pourrais même l’offrir à Sa Majesté, proposer de l’utiliser pour former et sélectionner les recrues. Avec la prime, je pourrai enfin rembourser toutes les dettes que j’ai contractées pour l’améliorer.",
          DialogueId = 73000405,
          GUID = "B6BFB4F2",
          SpeakNpcId = 818022,
          Subtitle = "Ha! Gotcha at last! This thing's a masterpiece — I oughta present it to His Majesty himself. Perfect for screening recruits. I'll finally rake in a fat bonus and pay off all the debt I racked up building it."
        },
        [73000502] = {
          ContentFR = "La machine vibre doucement. Un cadran grossier y est fixé, gravé de trois options : Facile, Difficile et Extrême. Tout indique que c’est l’œuvre de ce soldat bavard.",
          DialogueId = 73000502,
          GUID = "B6BFC4DC",
          SpeakNpcId = 818022,
          Subtitle = "(The machine hums softly. A crude dial sits atop it, etched with three labels: Easy, Hard, and Extremely Hard. Looks like the handiwork of that overly chatty soldier.)"
        },
        [73000601] = {
          ContentFR = "<I>C’est un monte-charge... je pourrais peut-être récupérer des provisions. Mais je dois rester sur mes gardes, une embuscade est possible.</>",
          DialogueId = 73000601,
          ExStoryInfo = "EXPlayer",
          GUID = "B6BFD51A",
          SpeakNpcId = 110022,
          Subtitle = "(A cargo lift. Could be a good chance to resupply... but I'd better stay alert. Could be an ambush.)",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD7"
        },
        [73000701] = {
          ContentFR = "Pour l’instant la zone est sûre. Je peux accéder au terminal.",
          DialogueId = 73000701,
          ExStoryInfo = "EXPlayer",
          GUID = "B6BFE582",
          SpeakNpcId = 110022,
          Subtitle = "Room's clear for now. Time to access the control panel.",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD8"
        },
        [73000801] = {
          ContentFR = "Autorisation en cours. Veuillez patienter...",
          DialogueId = 73000801,
          GUID = "B6BFF5EA",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Authorising access. Please wait...",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD9"
        },
        [73000901] = {
          ContentFR = "<I>La salle de commande centrale est alimentée séparément... Les Roues Phoxynamo n’ont donc pas été affectées par l’explosion de la salle des machines.</>",
          DialogueId = 73000901,
          ExStoryInfo = "EXPlayer",
          GUID = "B6C00652",
          SpeakNpcId = 110022,
          Subtitle = "(So the Central Control Room runs on a separate grid... That's why the blast didn't reach this part.)",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDDA"
        },
        [73001001] = {
          ContentFR = "Erreur de flux énergétique. Le terminal est passé en mode de protection. Veuillez désactiver les Roues Phoxynamo pour lever le verrouillage.",
          DialogueId = 73001001,
          GUID = "B6C016BA",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Power flow error detected. Control panel locked for protection. Please shut down all Phoxynamo Wheels to lift the lock.",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDDB"
        },
        [80001001] = {
          ContentFR = "Oh ! Je suis devant la maison du Grand Magicien ! Toc, toc, toc... Grand Magicien, tu es là ?",
          DialogueId = 80001001,
          GUID = "C8462C3A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Wow, I'm at the door of the Great Magician's house! Knock, knock~ Great Magician, are you home?",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462C3A"
        },
        [80001002] = {
          ContentFR = "Hmm... Pas de réponse. On dirait qu’il est sorti. Allons voir dehors si on peut le retrouver !",
          DialogueId = 80001002,
          GUID = "C8462C64",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Hmm, no response... Looks like he went out. Let's go and look for him then!",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462C64"
        },
        [80001003] = {
          ContentFR = "Oh... l’histoire devant moi n’a même pas de couleurs... Mais ce n’est pas grave, j’ai mon pinceau magique ! Je vais colorier l’histoire au fur et à mesure que j’avance.",
          DialogueId = 80001003,
          GUID = "C8462C8E",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Oh, the story ahead has no colour... That's okay, I can paint the story with my magic brush while I go forward.",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462C8E"
        },
        [80001004] = {
          ContentFR = "Allez, empruntons ce chemin et partons sur les traces du Grand Magicien.",
          DialogueId = 80001004,
          GUID = "C8462CB8",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Let's go along this path to find the Great Magician.",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462CB8"
        },
        [80001005] = {
          ContentFR = "Hein ? Mais... il n’y a pas une seule fleur dans le jardin...",
          DialogueId = 80001005,
          GUID = "C8462CE2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 80001006,
          SpeakNpcId = 700142,
          Subtitle = "How come? There isn't a single flower in the garden...",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462CE2"
        },
        [80001006] = {
          ContentFR = "Je vais faire apparaître de jolies fleurs ici !",
          DialogueId = 80001006,
          GUID = "C8462D0C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Let me sprinkle some beautiful flowers here!",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D0C"
        },
        [80001007] = {
          ContentFR = "Voilà ! C’est bien plus joli comme ça. Continuons notre aventure !",
          DialogueId = 80001007,
          GUID = "C8462D36",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Now, the garden looks much prettier. Let's continue the journey~",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D36"
        },
        [80001008] = {
          ContentFR = "Oh... C’est une plume laissée par le petit Rossignol !",
          DialogueId = 80001008,
          GUID = "C8462D60",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80001009,
          SpeakNpcId = 700142,
          Subtitle = "Wait, these are... feathers from the Little Nightingale!",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D60"
        },
        [80001009] = {
          ContentFR = "Vite, ramassons-la. Ça nous portera sûrement bonheur.",
          DialogueId = 80001009,
          GUID = "C8462D8A",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Let's gather the feathers — It will bring us good luck.",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D8A"
        },
        [80001010] = {
          ContentFR = "Le chemin est bloqué... Comment faire pour que ces lianes me laissent passer ?",
          DialogueId = 80001010,
          GUID = "C8462DB4",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "The road ahead is blocked... What should I do to ask the vines to make way?",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462DB4"
        },
        [80001011] = {
          ContentFR = "Super ! Je peux avancer !",
          DialogueId = 80001011,
          GUID = "C8462DDE",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Great! Now I can keep going~",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462DDE"
        },
        [80001012] = {
          ContentFR = "Peut-être que le Grand Magicien est là-bas...",
          DialogueId = 80001012,
          GUID = "C8462E08",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Would the Great Magician be there?",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E08"
        },
        [80001013] = {
          ContentFR = "Oh ? Le feu brûle encore... On dirait qu’il vient juste de partir.",
          DialogueId = 80001013,
          GUID = "C8462E32",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Oh? The bonfire is still burning — looks like the Great Magician left only moments ago.",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E32"
        },
        [80001014] = {
          ContentFR = "Ouaaah... les lucioles brillent comme des petites étoiles qui volent !",
          DialogueId = 80001014,
          GUID = "C8462E5C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Whoa, the moment the fireflies scattered... It's like the stars had suddenly grown wings.",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E5C"
        },
        [80001015] = {
          ContentFR = "Ici aussi, de jolies fleurs ont éclos.",
          DialogueId = 80001015,
          GUID = "C8462E86",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 80001016,
