          GUID = "C8462EDA",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Didn't expect to see a treasure chest here. Could it be the Great Magician's secret hoard?",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462EDA"
        },
        [80001018] = {
          ContentFR = "Il n’y a plus de chemin devant... Comment je vais faire pour traverser ?",
