          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "There's no way ahead. How can I get through?",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462F04"
        },
        [80001019] = {
          ContentFR = "Ouaah... Vous êtes adorables, les petits champignons ! Vous êtes venus pour m’aider ?",
