          GUID = "C8462F2E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 80001020,
          SpeakNpcId = 700142,
          Subtitle = "Wow...! Lovely mushrooms! Are you here to help me?",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462F2E"
        },
        [80001020] = {
          ContentFR = "Merci à vous ! Comme ça, je peux sauter de l’autre côté !",
          DialogueId = 80001020,
          GUID = "C8462F58",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Thank you. This way, I can just jump to the other side.",
          VoiceName = "voice/$Locale$/story/1201/120111/C8462F58"
        },
        [80001021] = {
          ContentFR = "Oh ! Ici aussi il y a un coffre... C’est le Grand Magicien qui l’a laissé exprès pour moi ?",
