          Subtitle = "Hmm, it's blocked on this side. Looks like I have to deal with it on the other side.",
          VoiceName = "voice/$Locale$/story/1201/120112/C846D0F2"
        },
        [80002006] = {
          ContentFR = "{性别:Monsieur|Mademoiselle} Licorne s’était déjà réfugié dans une grotte étroite avec sa famille... pour échapper aux monstres.",
          DialogueId = 80002006,
          GUID = "C846D11C",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
