          GUID = "C846D170",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "But just when they finally drove away the Filthoids and broke through their ring...",
          VoiceName = "voice/$Locale$/story/1201/120112/C846D170"
        },
        [80002009] = {
