CameraMoveTo{_delay{0},TargetPosition{"-305.245117,-66.450867,94.986893,0.000031,4.817004,-15.060312,35.000008,196.78035,false,Manual,12.0"},duration{10}},
PlayFacial{_delay{1},ActorId{211001},FacialId{"Happy01"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Looks like this is the end of the story!",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483AB4"
        },
        [80004211] = {
          Camera = "24.198242,-211.033997,120.143204,0.000097,-11.183887,164.535263,14.0,425.896759,false,Manual,12.0",
          ContentFR = "Grâce à vous tous, j’ai pu résoudre toutes les énigmes et vivre cette belle aventure... Merci !",
          DialogueId = 80004211,
          GUID = "C8483ADE",
          NextDialogue = 80004212,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{4},TargetPosition{"-368.462891,-132.922058,107.473412,0.000134,-1.085023,3.706975,35.000019,221.963821,false,Manual,20.0"},duration{0}},
CameraMoveTo{_delay{0},TargetPosition{"-535.898438,-133.140198,75.268944,0.000129,1.615558,2.007271,35.000019,206.559311,false,Manual,20.0"},duration{8}}
},
SEQ{
PlayAnimation{_delay{1},ActorId{211001},AnimationId{"Explain02_Start"}},
PlayAnimation{_delay{5},ActorId{211001},AnimationId{"Explain02_End"}}
},
PlayFacial{_delay{1},ActorId{211001},FacialId{"Smile01"}},
PlayFacial{_delay{3},ActorId{211001},FacialId{"Satisfy01"}},
}]],
          SpeakNpcId = 211001,
          Subtitle = "I never could've solved every puzzle without you — thank you, everyone, for guiding me all the way to the end.",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483ADE"
        },
        [80004212] = {
          Camera = "-772.461914,-661.862793,33.008789,0.000118,3.216575,64.14006,35.000011,2400.0,false,Manual,20.0",
          ContentFR = "Tu as vu ? L’herbe est toute douce sous nos pieds, il y a des fleurs de toutes les couleurs, et un vent chaud qui caresse nos joues... Organisons un joyeux pique-nique, et donnons à ce conte une fin heureuse !",
          DialogueId = 80004212,
          GUID = "C8483B08",
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{0},TargetPosition{"-609.772461,-758.210938,32.1493,0.000122,3.01656,58.740654,35.000011,2400.0,false,Manual,20.0"},duration{10}},
CameraMoveTo{_delay{10.01},TargetPosition{"-254.532227,-124.837219,119.342606,0.000121,-2.983181,2.740541,35.000011,247.487625,false,Manual,20.0"},duration{0}},
CameraMoveTo{_delay{0.01},TargetPosition{"-233.603516,-126.783081,110.153168,0.000123,0.016741,3.740588,35.000011,93.779053,false,Manual,20.0"},duration{6}}
},
PlayFacial{_delay{10},ActorId{211001},FacialId{"Satisfy01"}},
PlayAnimation{_delay{4},ActorId{211001},AnimationId{"Feina_Story_Wish_Start"}}
}]],
          SpeakNpcId = 211001,
          Subtitle = "Look — soft grass beneath us, flowers splashed in every color, and a warm breeze brushing our cheeks… Let's lay out a cheerful picnic right here to draw a happy ending to this story!",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B08"
        },
        [80004250] = {
          ContentFR = "Hmm... Ce n’était sûrement pas la bonne couleur... Essayons un autre pigment !",
          DialogueId = 80004250,
          Duration = 3,
          GUID = "C8483B09",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "Hmm… maybe this wasn't the right color — let's swap the pigment and try again!",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B09"
        },
        [80004251] = {
          ContentFR = "On dirait que ça irait mieux avec une autre couleur...",
          DialogueId = 80004251,
          Duration = 3,
          GUID = "C8483B0A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "It looks like it's longing for a different colour.",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0A"
        },
        [80004252] = {
          ContentFR = "Oh non... La couleur que j’avais mise a disparu...",
          DialogueId = 80004252,
          Duration = 3,
          GUID = "C8483B0B",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80004253,
          SpeakNpcId = 700142,
          Subtitle = "Oh no, the colour I just painted is gone...",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0B"
        },
        [80004253] = {
          ContentFR = "Il va falloir que je sois plus rapide, sinon ça s’efface !",
          DialogueId = 80004253,
          Duration = 3,
          GUID = "C8483B0C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          Subtitle = "I'll have to paint faster before the next vanish!",
          VoiceName = "voice/$Locale$/story/1201/120114/C8483B0C"
        },
        [80004254] = {
          Camera = "-4.021118,-147.850586,140.854248,0.000064,-3.469995,89.231857,35.0,160.025635,false,Manual,12.0",
          ContentFR = "<I>... Il me manque encore quelques plumes du petit rossignol... Peut-être devrais-je retourner les chercher ?</>",
          DialogueId = 80004254,
          Duration = 12,
          GUID = "C8483B0D",
          Scripts = [[
PARA{
CameraMoveTo{_delay{6.5},TargetPosition{"-130.023865,-580.916016,82.43866,0.000115,4.930222,79.821289,35.000011,872.114136,false,Manual,12.0"},duration{8}},
SEQ{
PARA{
PlayAnimation{_delay{0.5},ActorId{211001},AnimationId{"Think_Start"},Duration{1}},
PlayFacial{_delay{0.5},ActorId{211001},FacialId{"Think01"}}
},
PlayAnimation{_delay{2.5},ActorId{211001},AnimationId{"Think_End"},Duration{1}},
TurnTo{_delay{1},TurnToDescription{"211001:p(180)"}},
PlayFacial{_delay{0.5},ActorId{211001},FacialId{"Smile01"}}
}
}]],
          SpeakNpcId = 211001,
          Subtitle = "(Still missing some feathers... Should we head back and search again?)"
        },
        [80010100] = {
          Content = "嗯，荣幸之至。",
          DialogueId = 80010100,
          GUID = "C84C0108",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0108"
        },
        [80010101] = {
          Content = "这是为了维系您与我之间的友谊，而有意为之的邀约，对吗？",
          DialogueId = 80010101,
          GUID = "C84C0132",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0132"
        },
        [80010102] = {
          Content = "好，那么我愿与您共饮。",
          DialogueId = 80010102,
          GUID = "C84C015C",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C015C"
        },
        [80010103] = {
          Content = "唔，咳……",
          DialogueId = 80010103,
          GUID = "C84C0186",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0186"
        },
        [80010104] = {
          Content = "没什么，请继续讲吧。",
          DialogueId = 80010104,
          GUID = "C84C01B0",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C01B0"
        },
        [80010105] = {
          Content = "不，只是……",
          DialogueId = 80010105,
          GUID = "C84C01DA",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C01DA"
        },
        [80010106] = {
          Content = "嗯。被您看穿了呢。",
          DialogueId = 80010106,
          GUID = "C84C0204",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0204"
        },
        [80010107] = {
          Content = "酒的味道，颇有些……浓烈。长久以来，受到家族较多管束的缘故，我极少品尝这种饮品。",
          DialogueId = 80010107,
          GUID = "C84C022E",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C022E"
        },
        [80010108] = {
          Content = "但既然您饱含诚意的邀请了，那回绝就过于失礼。",
          DialogueId = 80010108,
          GUID = "C84C0258",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0258"
        },
        [80010109] = {
          Content = "您不必为此介怀。对宾客投其所好或许是尽地主之谊的必要礼节，但适逢其时的好意本身已经足以慰藉风尘。",
          DialogueId = 80010109,
          GUID = "C84C0282",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0282"
        },
        [80010110] = {
          Content = "而且，我也在逐步学会适应“外面的一切”。",
          DialogueId = 80010110,
          GUID = "C84C02AC",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C02AC"
        },
        [80010111] = {
          Content = "第一次抵达北境的时候，在冰天雪地的荒原上，也曾有一位年迈的猎人给了我同样的东西。",
          DialogueId = 80010111,
          GUID = "C84C02D6",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C02D6"
        },
        [80010112] = {
          Content = "“烈酒”。",
          DialogueId = 80010112,
          GUID = "C84C0300",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0300"
        },
        [80010113] = {
          Content = "远比您调制的这杯更辛辣，更苦涩，甚至让人难以保持清醒的意志。",
          DialogueId = 80010113,
          GUID = "C84C032A",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C032A"
        },
        [80010114] = {
          Content = "但却非常温暖。像一小簇火苗，让几乎冻僵的我们再次有了活着的知觉。",
          DialogueId = 80010114,
          GUID = "C84C0354",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0354"
        },
        [80010115] = {
          Content = "是的，这没什么值得隐瞒的。",
          DialogueId = 80010115,
          GUID = "C84C037E",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C037E"
        },
        [80010116] = {
          Content = "您这个玩笑……我并不觉得非常有趣。",
          DialogueId = 80010116,
          GUID = "C84C03A8",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C03A8"
        },
        [80010117] = {
          Content = "我是一名漂泊之人，如您所见。",
          DialogueId = 80010117,
          GUID = "C84C03D2",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C03D2"
        },
        [80010118] = {
          Content = "也许您已经从希尔妲那里听说过，我们的故土，是迪斯玛尼亚——也许您会更加熟悉它的另一个称呼，“皇都”。",
          DialogueId = 80010118,
          GUID = "C84C03FC",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C03FC"
        },
        [80010119] = {
          Content = "在那里，我和家族发生了一些冲突，致使流落至此。",
          DialogueId = 80010119,
          GUID = "C84C0426",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0426"
        },
        [80010120] = {
          Content = "请谅解。您是与我订立过重要契约的人，按照礼节，我本应坦诚以待。",
          DialogueId = 80010120,
          GUID = "C84C0450",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C0450"
        },
        [80010121] = {
          Content = "但关于这件事，请容许我保守秘密——",
          DialogueId = 80010121,
          GUID = "C84C047A",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C047A"
        },
        [80010122] = {
          Content = "我对您虽无戒备之心，但出于对您安全的顾虑，还是建议您不要牵涉过深为好。",
          DialogueId = 80010122,
          GUID = "C84C04A4",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C04A4"
        },
        [80010123] = {
          Content = "时间有些迟了，谢谢您今日的邀请。回见。",
          DialogueId = 80010123,
          GUID = "C84C04CE",
          VoiceName = "voice/$Locale$/inv/Fuluo/001/C84C04CE"
        },
        [80010201] = {
          Content = "与您共度的时光称得上令人欢悦，虽然我还不能很好地适应它的味道。",
          DialogueId = 80010201,
          GUID = "C84C119A",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C119A"
        },
        [80010202] = {
          Content = "嗯……的确没有呢。",
          DialogueId = 80010202,
          GUID = "C84C11C4",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C11C4"
        },
        [80010203] = {
          Content = "请不要误会，我并非在对您的邀约敷衍了事。",
          DialogueId = 80010203,
          GUID = "C84C11EE",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C11EE"
        },
        [80010204] = {
          Content = "只是希尔妲不允许我对食物拥有偏好。她每日都会要求厨师奉上和此前完全不同的菜肴，而这些餐点里，喜爱的也好，厌弃的也好，她都会要求我一视同仁地品尝。",
          DialogueId = 80010204,
          GUID = "C84C1218",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1218"
        },
        [80010205] = {
          Content = "久而久之，我也就没有什么“喜爱的味道”了。",
          DialogueId = 80010205,
          GUID = "C84C1242",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1242"
        },
        [80010206] = {
          Content = "呵呵……您或许误解她了。她不是无礼之徒，此举也绝非傲慢地越俎代庖。",
          DialogueId = 80010206,
          GUID = "C84C126C",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C126C"
        },
        [80010207] = {
          Content = "呵呵……如果您是我，想必就不会说出这样的话了。",
          DialogueId = 80010207,
          GUID = "C84C1296",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1296"
        },
        [80010208] = {
          Content = "希尔妲是个敏锐的姑娘。她非常清楚，对我而言，拥有喜好，便意味着危险。",
          DialogueId = 80010208,
          GUID = "C84C12C0",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C12C0"
        },
        [80010209] = {
          Content = "比如……我来问您一个问题。您看这杯酒——",
          DialogueId = 80010209,
          GUID = "C84C12EA",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C12EA"
        },
        [80010210] = {
          Content = "假设我喜爱浸泡了罗勒叶和迷迭香的酒，每次都会一饮而尽，",
          DialogueId = 80010210,
          GUID = "C84C1314",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1314"
        },
        [80010211] = {
          Content = "而您又是一名受雇于主，混迹于一众家仆之中，想要夺取我性命的“窥伺者”，",
          DialogueId = 80010211,
          GUID = "C84C133E",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C133E"
        },
        [80010212] = {
          Content = "您要如何忍住，不把那漂亮而致命的毒液涂抹在罗勒叶之上呢？",
          DialogueId = 80010212,
          GUID = "C84C1368",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1368"
        },
        [80010213] = {
          Content = "哦？我只是做个简单的比喻。难道您真的……",
          DialogueId = 80010213,
          GUID = "C84C1392",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1392"
        },
        [80010214] = {
          Content = "呵呵，别太紧张。我不会怀疑您。",
          DialogueId = 80010214,
          GUID = "C84C13BC",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C13BC"
        },
        [80010215] = {
          Content = "的确……",
          DialogueId = 80010215,
          GUID = "C84C13E6",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C13E6"
        },
        [80010216] = {
          Content = "在我身边环绕着的人……或许更应该称呼他们是兽群。",
          DialogueId = 80010216,
          GUID = "C84C1410",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1410"
        },
        [80010217] = {
          Content = "他们像是一群秃鹫，随时在等待着我停止挣扎的一刻，然后分食。",
          DialogueId = 80010217,
          GUID = "C84C143A",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C143A"
        },
        [80010218] = {
          Content = "迪斯玛尼亚的每一粒灵魂，包括我自己，都是污浊的。",
          DialogueId = 80010218,
          GUID = "C84C1464",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1464"
        },
        [80010219] = {
          Content = "呵呵……也许对您而言，漂泊在外意味着异邦的风土，喧哗而有趣的人们，焕然一新的人生。但至于我……",
          DialogueId = 80010219,
          GUID = "C84C148E",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C148E"
        },
        [80010220] = {
          Content = "陌生的土地给了我片刻喘息，但我终究要到故乡。不过，并非因为我有多怀念它。",
          DialogueId = 80010220,
          GUID = "C84C14B8",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C14B8"
        },
        [80010221] = {
          Content = "而是我全部的爱与憎恨，思念与愤怒，都在那个地方。",
          DialogueId = 80010221,
          GUID = "C84C14E2",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C14E2"
        },
        [80010222] = {
          Content = "我该走了。还有……",
          DialogueId = 80010222,
          GUID = "C84C150C",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C150C"
        },
        [80010223] = {
          Content = "尝得出，相比上次，您在调和时有意减淡了口味。",
          DialogueId = 80010223,
          GUID = "C84C1536",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1536"
        },
        [80010224] = {
          Content = "多谢您，将我的无意之言记挂在心。",
          DialogueId = 80010224,
          GUID = "C84C1560",
          VoiceName = "voice/$Locale$/inv/Fuluo/002/C84C1560"
        },
        [80010301] = {
          Content = "尝得出，您调制饮品的手艺愈发娴熟，甚至达到了希尔妲五成的水准。",
          DialogueId = 80010301,
          GUID = "C84C2202",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2202"
        },
        [80010302] = {
          Content = "我不像希尔妲那样，擅长社交上的体面辞令。我的意思是，以她为基准的话，五成也已经很了不起了。",
          DialogueId = 80010302,
          GUID = "C84C222C",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C222C"
        },
        [80010303] = {
          Content = "如果说有什么值得特别留意的……",
          DialogueId = 80010303,
          GUID = "C84C2256",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2256"
        },
        [80010304] = {
          Content = "那就是您过于平等地糅合了所有原料，反而让人无法品尝出它的基底——也就是，调制者最想要呈现的味道。",
          DialogueId = 80010304,
          GUID = "C84C2280",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2280"
        },
        [80010305] = {
          Content = "您近日心绪也有些乱。也许，忧虑太多纷杂的事，不如选择一件最重要的，细细研磨。",
          DialogueId = 80010305,
          GUID = "C84C22AA",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C22AA"
        },
        [80010306] = {
          Content = "啊……",
          DialogueId = 80010306,
          GUID = "C84C22D4",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C22D4"
        },
        [80010307] = {
          Content = "杯子……粘上了……抱歉，我并非有意弄脏它。",
          DialogueId = 80010307,
          GUID = "C84C22FE",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C22FE"
        },
        [80010308] = {
          Content = "只是赴约之前，我刚刚完成那幅画。没有希尔妲提醒，我忘记手指沾了些颜料。",
          DialogueId = 80010308,
          GUID = "C84C2328",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2328"
        },
        [80010309] = {
          Content = "…………",
          DialogueId = 80010309,
          GUID = "C84C2352",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2352"
        },
        [80010310] = {
          Content = "是您的话，倒无妨。",
          DialogueId = 80010310,
          GUID = "C84C237C",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C237C"
        },
        [80010311] = {
          Content = "过去吗？呵呵……如果这是真正的过去，就好了。",
          DialogueId = 80010311,
          GUID = "C84C23A6",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C23A6"
        },
        [80010312] = {
          Content = "父亲、母亲……",
          DialogueId = 80010312,
          GUID = "C84C23D0",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C23D0"
        },
        [80010313] = {
          Content = "其实我从未见过他们。",
          DialogueId = 80010313,
          GUID = "C84C23FA",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C23FA"
        },
        [80010314] = {
          Content = "在我的居所，他们存在过的痕迹——连同他们的画像——都已经被残忍粗暴地抹去了。我只能通过老仆人的只言片语，去想象他们的样子。",
          DialogueId = 80010314,
          GUID = "C84C2424",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2424"
        },
        [80010315] = {
          Content = "年岁尚小的时候啊，我每天都在想，我总会与他们相见的。就在未来的某一天……",
          DialogueId = 80010315,
          GUID = "C84C244E",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C244E"
        },
        [80010316] = {
          Content = "到那天，我们就可以像这样，邀来最优秀的画师，来为我们画一幅家族肖像。像那些可爱的三口之家一样。",
          DialogueId = 80010316,
          GUID = "C84C2478",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2478"
        },
        [80010317] = {
          Content = "但真正到了我能够把心中所思绘制在画布上的年纪，我才知道，我画的不是过去，亦非未来。",
          DialogueId = 80010317,
          GUID = "C84C24A2",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C24A2"
        },
        [80010318] = {
          Content = "而是从未存在过，将来也不会存在的……",
          DialogueId = 80010318,
          GUID = "C84C24CC",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C24CC"
        },
        [80010319] = {
          Content = "“泡影”。",
          DialogueId = 80010319,
          GUID = "C84C24F6",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C24F6"
        },
        [80010320] = {
          Content = "嗯。也许您早已猜到，在我记事之前，他们已经是墓园的白骨。",
          DialogueId = 80010320,
          GUID = "C84C2520",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2520"
        },
        [80010321] = {
          Content = "抱歉，我不小心自顾自地说起来了，连带您的心情也变糟糕了吧。",
          DialogueId = 80010321,
          GUID = "C84C254A",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C254A"
        },
        [80010322] = {
          Content = "您认真地准备了饮品和茶点，想必并非打算听我喋喋不休地叨念些不快的旧事。",
          DialogueId = 80010322,
          GUID = "C84C2574",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C2574"
        },
        [80010323] = {
          Content = "我们来聊些其他的吧，比如珀西·巴莱德的诗集。",
          DialogueId = 80010323,
          GUID = "C84C259E",
          VoiceName = "voice/$Locale$/inv/Fuluo/003/C84C259E"
        },
        [80010401] = {
          Content = "……您又邀请了我呢。真是奇怪。",
          DialogueId = 80010401,
          GUID = "C84C326A",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C326A"
        },
        [80010402] = {
          Content = "我认为，我并不是一个可以给您带来欢愉的攀谈对象。",
          DialogueId = 80010402,
          GUID = "C84C3294",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3294"
        },
        [80010403] = {
          Content = "我今天读了一句诗：“好奇心会杀死一只知更鸟”……",
          DialogueId = 80010403,
          GUID = "C84C32BE",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C32BE"
        },
        [80010404] = {
          Content = "罢了，既然您再度问起，那么我讲一个故事吧。",
          DialogueId = 80010404,
          GUID = "C84C32E8",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C32E8"
        },
        [80010405] = {
          Content = "很久很久之前，有一个年轻的姑娘，她从出生起就住在一座黄金的牢笼里……",
          DialogueId = 80010405,
          GUID = "C84C3312",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3312"
        },
        [80010406] = {
          Content = "她似乎拥有世上的一切：她有一百顶镶着璀璨钻石的冠冕，有一百件皎洁珍珠编织的衣衫，有一百名仆人每天献上沾着晨露的鲜花……",
          DialogueId = 80010406,
          GUID = "C84C333C",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C333C"
        },
        [80010407] = {
          Content = "但有一件东西是她始终得不到的：那就是黄金牢笼外的任何事物，哪怕是一滴雨，一缕风。",
          DialogueId = 80010407,
          GUID = "C84C3366",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3366"
        },
        [80010408] = {
          Content = "一个夜晚，一条陌生的龙闯进了黄金的牢笼。",
          DialogueId = 80010408,
          GUID = "C84C3390",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3390"
        },
        [80010409] = {
          Content = "她不知道那条龙硕大的身躯是如何钻进狭窄的栅栏，只知道它带来了她梦寐以求的一切——诗集，油彩，琴弦，剑术……以及她日思夜想的，牢笼之外的故事。",
          DialogueId = 80010409,
          GUID = "C84C33BA",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C33BA"
        },
        [80010410] = {
          Content = "虽然身在牢笼之中，但她却从龙带来的故事里，看到了广阔的天空，触摸到旷野的清风，奔跑在金色的麦田，听到了广场上吟游诗人的歌谣。",
          DialogueId = 80010410,
          GUID = "C84C33E4",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C33E4"
        },
        [80010411] = {
          Content = "她是如此感谢龙带给她的一切……",
          DialogueId = 80010411,
          GUID = "C84C340E",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C340E"
        },
        [80010412] = {
          Content = "直到有一天，她无意间从传言中得知，正是那条龙，在她还在襁褓中时，灭亡了她的城市，杀死了她的亲生父亲……是的，它是一条恶龙。",
          DialogueId = 80010412,
          GUID = "C84C3438",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3438"
        },
        [80010413] = {
          Content = "然后，恶龙将她锁进了这座黄金的监牢。",
          DialogueId = 80010413,
          GUID = "C84C3462",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3462"
        },
        [80010414] = {
          Content = "少女将愤怒熔铸成刺剑，等待着恶龙再次踏着月色来访，她发誓将以利刃贯穿恶龙的心脏。但最后，她却犹疑了。她颤抖着询问传言的虚实，她渴望得到错误的答案。",
          DialogueId = 80010414,
          GUID = "C84C348C",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C348C"
        },
        [80010415] = {
          Content = "但恶龙却亲口承认了一切。最后，她的剑只触及恶龙坚硬的鳞片。",
          DialogueId = 80010415,
          GUID = "C84C34B6",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C34B6"
        },
        [80010416] = {
          Content = "不久之后，黄金囚笼里的吃穿用度，全部变了模样。每日奉上的鲜花，花蕾中再也不是晨露，而是毒刺。",
          DialogueId = 80010416,
          GUID = "C84C34E0",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C34E0"
        },
        [80010417] = {
          Content = "终于有一天，一位聪明的女仆想方设法找到黄金的钥匙，打开了囚笼的门……女仆对少女说，她自由了。",
          DialogueId = 80010417,
          GUID = "C84C350A",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C350A"
        },
        [80010418] = {
          Content = "但是少女知道，恶龙焚城的火焰在她的心底燃烧着，记忆的余烬环绕着她，将她投入深渊。她永远不会得到自由了。",
          DialogueId = 80010418,
          GUID = "C84C3534",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3534"
        },
        [80010419] = {
          Content = "嗯，很久之后我才得知，那两场<C=#FF0000>盛大的谋杀</C>。",
          DialogueId = 80010419,
          GUID = "C84C355E",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C355E"
        },
        [80010420] = {
          Content = "从那之后，我的梦中永远是鲜血淋漓的身体，痛苦扭曲的面庞……每一晚，每一晚。",
          DialogueId = 80010420,
          GUID = "C84C3588",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3588"
        },
        [80010421] = {
          Content = "在用小刀划破自己皮肤的时候，我已经是那么痛了。那么被利剑贯穿的父亲，被埋在废墟中的母亲，该有多痛啊……",
          DialogueId = 80010421,
          GUID = "C84C35B2",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C35B2"
        },
        [80010422] = {
          Content = "呵呵，您知道吗？您眼前的芙罗拉，并不是什么优雅高贵的贵族小姐……",
          DialogueId = 80010422,
          GUID = "C84C35DC",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C35DC"
        },
        [80010423] = {
          Content = "她只是一个献祭生命也在所不惜的，复仇的恶鬼啊。",
          DialogueId = 80010423,
          GUID = "C84C3606",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3606"
        },
        [80010424] = {
          Content = "呵呵……呵呵呵。",
          DialogueId = 80010424,
          GUID = "C84C3630",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3630"
        },
        [80010425] = {
          Content = "{NickName}，我想，您拥有一位过于优秀的骑士。",
          DialogueId = 80010425,
          GUID = "C84C365A",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C365A"
        },
        [80010426] = {
          Content = "贝蕾妮卡小姐，她把您护佑得多周全啊，无论是身体，还是灵魂。",
          DialogueId = 80010426,
          GUID = "C84C3684",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3684"
        },
        [80010427] = {
          Content = "“新的人生”……好漂亮的愿望，就像孩子们吹出的肥皂泡……",
          DialogueId = 80010427,
          GUID = "C84C36AE",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C36AE"
        },
        [80010428] = {
          Content = "呵呵……呵呵呵。",
          DialogueId = 80010428,
          GUID = "C84C36D8",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C36D8"
        },
        [80010429] = {
          Content = "{NickName}，您真的是一个过于天真的家伙。",
          DialogueId = 80010429,
          GUID = "C84C3702",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3702"
        },
        [80010430] = {
          Content = "以至于，您可以笃定地认为，您有资格对抗我所对抗的东西。",
          DialogueId = 80010430,
          GUID = "C84C372C",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C372C"
        },
        [80010431] = {
          Content = "您不知道，那是一个怎样的<C=#FF0000>“怪物”</C>……",
          DialogueId = 80010431,
          GUID = "C84C3756",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3756"
        },
        [80010432] = {
          Content = "…………",
          DialogueId = 80010432,
          GUID = "C84C3780",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3780"
        },
        [80010433] = {
          Content = "失礼了，我今天说了太多错误的言辞。",
          DialogueId = 80010433,
          GUID = "C84C37AA",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C37AA"
        },
        [80010434] = {
          Content = "把这一切都忘了吧。或者，请您只当它是从某本小说里读来的传奇故事。",
          DialogueId = 80010434,
          GUID = "C84C37D4",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C37D4"
        },
        [80010435] = {
          Content = "以及，不要再邀请我赴约了。这样，我还可以视您为一名值得尊敬的受托人。",
          DialogueId = 80010435,
          GUID = "C84C37FE",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C37FE"
        },
        [80010436] = {
          Content = "只是这样……就好。",
          DialogueId = 80010436,
          GUID = "C84C3828",
          VoiceName = "voice/$Locale$/inv/Fuluo/004/C84C3828"
        },
        [80010501] = {
          Content = "我应该说过，请您不要再邀请我。",
          DialogueId = 80010501,
          GUID = "C84C42D2",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C42D2"
        },
        [80010502] = {
          Content = "如果事关我们的契约，谈判桌远比这里更加合适。",
          DialogueId = 80010502,
          GUID = "C84C42FC",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C42FC"
        },
        [80010503] = {
          Content = "呵……",
          DialogueId = 80010503,
          GUID = "C84C4326",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4326"
        },
        [80010504] = {
          Content = "我想，上次我已经给了您清楚的回答。",
          DialogueId = 80010504,
          GUID = "C84C4350",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4350"
        },
        [80010505] = {
          Content = "回去吧。我的前路没有过去，也没有未来。只有紧紧闭锁的漆黑深渊。",
          DialogueId = 80010505,
          GUID = "C84C437A",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C437A"
        },
        [80010506] = {
          Content = "即使是您放声呼喊，也无法将我从那里带回。",
          DialogueId = 80010506,
          GUID = "C84C43A4",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C43A4"
        },
        [80010507] = {
          Content = "…………",
          DialogueId = 80010507,
          GUID = "C84C43CE",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C43CE"
        },
        [80010508] = {
          Content = "…………",
          DialogueId = 80010508,
          GUID = "C84C43F8",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C43F8"
        },
        [80010509] = {
          Content = "你……",
          DialogueId = 80010509,
          GUID = "C84C4422",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4422"
        },
        [80010510] = {
          Content = "哪来的笨蛋{性别：先生|小姐}，幼稚鬼，秽兽一样的脑袋！你以为你是什么人？传奇小说里的屠龙勇士，神眷之子？少做白日梦了！我们的契约只是要你帮我找东西，可没约定过这种事！",
          DialogueId = 80010510,
          GUID = "C84C444C",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C444C"
        },
        [80010511] = {
          Content = "你知道我的仇人是什么家伙吗？别犯蠢了，他一秒钟，一句话，就足以要你的命。",
          DialogueId = 80010511,
          GUID = "C84C4476",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4476"
        },
        [80010512] = {
          Content = "……失礼了。",
          DialogueId = 80010512,
          GUID = "C84C44A0",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44A0"
        },
        [80010513] = {
          Content = "您……在说些什么。",
          DialogueId = 80010513,
          GUID = "C84C44CA",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44CA"
        },
        [80010514] = {
          Content = "我希望可以成为芙罗拉的朋友，而非仅仅是受托人。不……甚至不只是朋友，而是可以共享哀乐，共享命运的人。",
          DialogueId = 80010514,
          GUID = "C84C44CB",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44CB"
        },
        [80010515] = {
          Content = "所以，如果我没有可以将芙罗拉带回的绳索，那就让我也一起跳下去吧。",
          DialogueId = 80010515,
          GUID = "C84C44CC",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44CC"
        },
        [80010516] = {
          Content = "我不是什么诸神眷顾的屠龙勇者，但我可以和你一起战斗至最后一刻。",
          DialogueId = 80010516,
          GUID = "C84C44CD",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44CD"
        },
        [80010517] = {
          Content = "哪怕最终你的剑折断了，至少还有人可以陪你一起躺在血泊里，而不是让你孤独一人面对死亡。",
          DialogueId = 80010517,
          GUID = "C84C44CE",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44CE"
        },
        [80010518] = {
          Content = "…………",
          DialogueId = 80010518,
          GUID = "C84C44F4",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C44F4"
        },
        [80010519] = {
          Content = "真是……愚蠢啊。",
          DialogueId = 80010519,
          GUID = "C84C451E",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C451E"
        },
        [80010520] = {
          Content = "说到这份上，我要用什么办法才能甩掉你呢……",
          DialogueId = 80010520,
          GUID = "C84C4548",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4548"
        },
        [80010521] = {
          Content = "我没有过去，也没有未来。",
          DialogueId = 80010521,
          GUID = "C84C4572",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C4572"
        },
        [80010522] = {
          Content = "除了千疮百孔的灵魂，一无所有。",
          DialogueId = 80010522,
          GUID = "C84C459C",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C459C"
        },
        [80010523] = {
          Content = "既然你来了……那就和我一起，行走在鲜血淋漓的“现在”吧。",
          DialogueId = 80010523,
          GUID = "C84C45C6",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C45C6"
        },
        [80010524] = {
          Content = "直到那漆黑之物杀死我们，或者我们杀死它。",
          DialogueId = 80010524,
          GUID = "C84C45F0",
          VoiceName = "voice/$Locale$/inv/Fuluo/005/C84C45F0"
        },
        [80020100] = {
          ContentFR = "À moins que vous n’ayez une mission pour moi, inutile de bavarder. Mais si votre requête consiste à simplement discuter, un petit tarif pour mes services et je vous tiendrai compagnie.",
          DialogueId = 80020100,
          GUID = "C85269A8",
          SpeakNpcId = 93102,
          Subtitle = "Unless you have a task for me, we don't need to engage in much small talk. However, if your task is to have a chat, then a small service fee will buy my temporary companionship.",
          VoiceName = "voice/$Locale$/inv/Xier/001/C85269A8"
        },
        [80020201] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
          ContentFR = "Hmpf, je vous envie. Avoir le loisir d’inviter quelqu’un pour prendre un verre...",
          DialogueId = 80020201,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8527A3A",
          LookAt = {
            [1] = "93102:p(18000P1)"
          },
          NextDialogue = 80020202,
          SpeakNpcId = 93102,
          Subtitle = "I must say, I envy you for having the leisure to throw a little tea party.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527A3A"
        },
        [80020202] = {
          ContentFR = "Je reviens à peine d’une mission dans le grand nord. J’ai l’impression que mes os vont se désarticuler. Il me faudra une nuit entière, et toute la journée suivante, pour m’en remettre.",
          DialogueId = 80020202,
          GUID = "C8527A64",
          NextOptions = {
            [1] = 800202021,
            [2] = 800202022
          },
          SpeakNpcId = 93102,
          Subtitle = "I've just completed a grueling assignment up north and feel like I'm falling apart. I'll probably need a full night and day of sleep to recover.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527A64"
        },
        [80020203] = {
          ContentFR = "Ce n’est pas la peine, je suis déjà installée. Autant boire un verre avant d’aller dormir.",
          DialogueId = 80020203,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527A8E",
          NextDialogue = 80020205,
          SpeakNpcId = 93102,
          Subtitle = "It's fine. I'm already seated — might as well have a drink with you before heading to bed.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527A8E"
        },
        [80020204] = {
          ContentFR = "Peut-être. Ou alors vous pourriez prendre en charge une de mes prochaines missions ?",
          DialogueId = 80020204,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527AB8",
          NextDialogue = 80020205,
          SpeakNpcId = 93102,
          Subtitle = "Perhaps you can handle a commission for me next time.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527AB8"
        },
        [80020205] = {
          ContentFR = "Eh bien, la prochaine fois que ce client me propose une mission, je la refuserai carrément. Même si la paye est bonne, c’est quand même un peu trop risqué.",
          DialogueId = 80020205,
          GUID = "C8527AE2",
          NextDialogue = 80020206,
          SpeakNpcId = 93102,
          Subtitle = "Mm, maybe I should just reject further commissions from this client. The pay is good but hardly worth the danger.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527AE2"
        },
        [80020206] = {
          ContentFR = "Elle m’a fait livrer une lettre, plutôt insultante, à ses proches amateurs de violence, juste pour les mettre en colère.",
          DialogueId = 80020206,
          GUID = "C8527B0C",
          NextDialogue = 80020207,
          SpeakNpcId = 93102,
          Subtitle = "She had me deliver a rather colourful letter to her violence-prone relatives back home, designed to make them see red.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527B0C"
        },
        [80020207] = {
          ContentFR = "En tant que messagère, il fallait que je me sauve aussitôt après la livraison, sinon ces brutes, qui n’ont sûrement jamais été insultées, m’auraient tiré dessus.",
          DialogueId = 80020207,
          FacialId = {
            [1] = "93102:Uninterested01"
          },
          GUID = "C8527B36",
          NextDialogue = 80020208,
          SpeakNpcId = 93102,
          Subtitle = "I had to bolt the second I delivered the letter; otherwise, the phrase \"shoot the messenger\" might have become more than just metaphorical — I bet those savages have never been on the receiving end of the kind words used in that letter.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527B36"
        },
        [80020208] = {
          ContentFR = "Puis, j’ai dû passer une nuit entière à marcher dans la neige pour éviter leurs embuscades. Évidemment, les éliminer serait facile, mais personne ne paie pour ça...",
          DialogueId = 80020208,
          GUID = "C8527B60",
          NextDialogue = 80020209,
          SpeakNpcId = 93102,
          Subtitle = "Then it was a whole night's trekking through the snow to dodge ambushes. Sure, I could easily handle them, but there's no extra pay for that...",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527B60"
        },
        [80020209] = {
          ContentFR = "Hein ? Pourquoi cet air si surpris ?",
          DialogueId = 80020209,
          FacialId = {
            [1] = "93102:Shock02"
          },
          GUID = "C8527B8A",
          NextOptions = {
            [1] = 800202091,
            [2] = 800202092
          },
          SpeakNpcId = 93102,
          Subtitle = "Hmm? You look astonished. What's wrong?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527B8A"
        },
        [80020210] = {
          ContentFR = "Bien sûr, du moins pour le moment.",
          DialogueId = 80020210,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527BB4",
          NextDialogue = 80020212,
          SpeakNpcId = 93102,
          Subtitle = "Of course, at least for now.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527BB4"
        },
        [80020211] = {
          ContentFR = "J’ai connu pire.",
          DialogueId = 80020211,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527BDE",
          NextDialogue = 80020212,
          SpeakNpcId = 93102,
          Subtitle = "Not really. I've been through worse.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527BDE"
        },
        [80020212] = {
          ContentFR = "Avant de devenir la servante de Mlle Flora, j’ai eu un autre métier, bref mais intense. Beaucoup de mes compétences viennent de cette époque.",
          DialogueId = 80020212,
          GUID = "C8527C08",
          NextDialogue = 80020213,
          SpeakNpcId = 93102,
          Subtitle = "Before I was Miss Flora's maid, I briefly held a different position where I acquired many of the skills I use today, whether necessary or not.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527C08"
        },
        [80020213] = {
          ContentFR = "Par exemple, démonter rapidement une arme à feu, extraire des poisons des plantes, ou neutraliser quelqu’un en trois secondes sans le tuer...",
          DialogueId = 80020213,
          GUID = "C8527C32",
          NextDialogue = 80020214,
          SpeakNpcId = 93102,
          Subtitle = "Like how to swiftly dismantle firearms, extract poison from plants, or knock someone out in three seconds without serious harm...",
          TalkActionId = {
            [1] = "93102:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527C32"
        },
        [80020214] = {
          ContentFR = "Puisque vous êtes un client fidèle, je peux vous l’avouer : j’étais agent.",
          DialogueId = 80020214,
          FacialId = {
            [1] = "93102:Confident02"
          },
          GUID = "C8527C5C",
          NextDialogue = 80020215,
          SpeakNpcId = 93102,
          Subtitle = "Well, you are my long-term client, so I'll just be upfront with you — I used to be an agent.",
          TalkActionId = {
            [1] = "93102:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527C5C"
        },
        [80020215] = {
          ContentFR = "Certains nous appellent espions ou agents secrets, mais peu importe le titre. Nous sommes ces ombres furtives que personne ne remarque vraiment.",
          DialogueId = 80020215,
          GUID = "C8527C86",
          NextDialogue = 80020216,
          SpeakNpcId = 93102,
          Subtitle = "Some called us spies. But the title doesn't matter. Essentially, we were a nameless group, always cloaked in disguise and shadow.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527C86"
        },
        [80020216] = {
          ContentFR = "Vous pourriez croiser l’un d’entre nous dans la rue sans le remarquer, alors qu’il est en route pour semer le chaos ou transmettre un secret.",
          DialogueId = 80020216,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527CB0",
          NextOptions = {
            [1] = 800202161,
            [2] = 800202162
          },
          SpeakNpcId = 93102,
          Subtitle = "You might brush past one on the street, thinking they're just an ordinary passerby, when in reality, they could be on their way to create chaos or deliver secret messages.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527CB0"
        },
        [80020217] = {
          ContentFR = "J’ai eu cette illusion aussi, mais la réalité est bien différente.",
          DialogueId = 80020217,
          FacialId = {
            [1] = "93102:Sad01"
          },
          GUID = "C8527CDA",
          NextDialogue = 80020219,
          SpeakNpcId = 93102,
          Subtitle = "I once romanticised it as well, but reality is another story.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527CDA"
        },
        [80020218] = {
          ContentFR = "En effet, cela peut sembler passionnant, mais en réalité, cela comporte de nombreux défis et risques.",
          DialogueId = 80020218,
          FacialId = {
            [1] = "93102:Sad01"
          },
          GUID = "C8527D04",
          NextDialogue = 80020219,
          SpeakNpcId = 93102,
          Subtitle = "Indeed, it may sound exciting, but it's actually packed with challenges and risks.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527D04"
        },
        [80020219] = {
          ContentFR = "La plupart des espions dépendent de leur légion, prisonniers de leurs ordres, parfois contraints de tuer même leurs proches.",
          DialogueId = 80020219,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527D2E",
          NextDialogue = 80020220,
          SpeakNpcId = 93102,
          Subtitle = "Most agents are stuck with their legion, forced to follow orders — some even involve killing their own family.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527D2E"
        },
        [80020220] = {
          ContentFR = "Je ne supportais plus toutes ces règles et restrictions, alors j’ai trouvé un moyen de m’en libérer.",
          DialogueId = 80020220,
          GUID = "C8527D58",
          NextDialogue = 80020221,
          SpeakNpcId = 93102,
          Subtitle = "I couldn't stand all those rules and restrictions, so I figured out a way to break free.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527D58"
        },
        [80020221] = {
          ContentFR = "Mon évasion fut épique, mais je doute qu’un verre suffise à vous raconter ça.",
          DialogueId = 80020221,
          FacialId = {
            [1] = "93102:Syouganai01"
          },
          GUID = "C8527D82",
          NextDialogue = 80020222,
          SpeakNpcId = 93102,
          Subtitle = "The escape was another heart-stopping story. This drink's not enough for me to share it, though.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527D82"
        },
        [80020222] = {
          ContentFR = "Il est temps pour moi d’aller dormir. Demain, je dois préparer le petit-déjeuner de Mlle Flora. Elle n’a pas goûté à mes desserts depuis plusieurs jours.",
          DialogueId = 80020222,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527DAC",
          NextDialogue = 80020223,
          SpeakNpcId = 93102,
          Subtitle = "I should go to bed now. I'll need to prepare breakfast for Miss Flora tomorrow. It's been days since she had my dessert.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527DAC"
        },
        [80020223] = {
          ContentFR = "En échange de ce verre, je vous garderai une part de gâteau.",
          DialogueId = 80020223,
          FacialId = {
            [1] = "93102:Satisfy01"
          },
          GUID = "C8527DD6",
          NextDialogue = 80020224,
          SpeakNpcId = 93102,
          Subtitle = "And as a thank-you for this drink, I'll save a piece of cake for you.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527DD6"
        },
        [80020224] = {
          ContentFR = "Sur ce, bonne nuit.",
          DialogueId = 80020224,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8527E00",
          SpeakNpcId = 93102,
          Subtitle = "Good night, then.",
          VoiceName = "voice/$Locale$/inv/Xier/002/C8527E00"
        },
        [80020301] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
          ContentFR = "Aujourd’hui, j’ai enfin un peu de temps libre. Je peux vous tenir compagnie pour quelques verres de plus.",
          DialogueId = 80020301,
          FacialId = {
            [1] = "93102:Satisfy01"
          },
          GUID = "C8528AA2",
          LookAt = {
            [1] = "93102:p(18000P1)"
          },
          NextDialogue = 80020302,
          SpeakNpcId = 93102,
          Subtitle = "I've finally got some free time today. I'm all yours if you're up for a few more drinks.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528AA2"
        },
        [80020302] = {
          ContentFR = "Après ça, je comptais faire un tour en ville. Avec toutes les missions que j’ai remplies dernièrement, il me reste quelques pièces d’argent à dépenser.",
          DialogueId = 80020302,
          GUID = "C8528ACC",
          NextOptions = {
            [1] = 800203021,
            [2] = 800203022
          },
          SpeakNpcId = 93102,
          Subtitle = "And after we're done here, I'm going to hit the shops — I've got some extra silver coins to squander from all those commissions I took.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528ACC"
        },
        [80020303] = {
          ContentFR = "Bien sûr. Je pourrai même vous aider à choisir quelques tenues qui vous iraient bien.",
          DialogueId = 80020303,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528AF6",
          NextDialogue = 80020305,
          SpeakNpcId = 93102,
          Subtitle = "Sure, I can help pick out something that suits you.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528AF6"
        },
        [80020304] = {
          ContentFR = "Évidemment. Je mange, je dors, je respire aussi, rien de plus normal.",
          DialogueId = 80020304,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528B20",
          NextDialogue = 80020305,
          SpeakNpcId = 93102,
          Subtitle = "Like I'd breathe, have meals, and sleep.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528B20"
        },
        [80020305] = {
          ContentFR = "Faire les boutiques, pour moi, c’est la manière la plus simple et directe de me détendre : pas besoin de réfléchir, je prends l’air, et je peux enfin porter ce qui me plaît, ce qui n’arrive pas souvent.",
          DialogueId = 80020305,
          GUID = "C8528B4A",
          NextDialogue = 80020306,
          SpeakNpcId = 93102,
          Subtitle = "Shopping is my way to unwind. It's thoughtless, gets me some fresh air, and I can wear what I like — a rare opportunity for me.",
          TalkActionId = {
            [1] = "93102:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528B4A"
        },
        [80020306] = {
          ContentFR = "En mission, je porte soit ma tenue de servante, soit un long manteau épais rempli de poches, pour y glisser tous les petits outils dont je pourrais avoir besoin.",
          DialogueId = 80020306,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528B74",
          NextDialogue = 80020307,
          SpeakNpcId = 93102,
          Subtitle = "At work, I'm typically in my maid's uniform or a bulky trench coat filled with pockets for various mission-essential gadgets.",
          TalkActionId = {
            [1] = "93102:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528B74"
        },
        [80020307] = {
          ContentFR = "Et pour ne pas attirer l’attention, j’attache toujours mes cheveux. Vous le savez, une chevelure rouge, ça se remarque très vite.",
          DialogueId = 80020307,
          GUID = "C8528B9E",
          NextDialogue = 80020308,
          SpeakNpcId = 93102,
          Subtitle = "And to keep a low profile during a mission, I'd tie up my hair. You know, red hair tends to draw unnecessary attention.",
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528B9E"
        },
        [80020308] = {
          ContentFR = "Mais pour flâner en ville, je peux me permettre un peu plus de liberté. J’opte alors pour des tuniques claires.",
          DialogueId = 80020308,
          FacialId = {
            [1] = "93102:Happy01"
          },
          GUID = "C8528BC8",
          NextDialogue = 80020309,
          SpeakNpcId = 93102,
          Subtitle = "But when I'm out shopping, I can let loose a bit and wear lighter-coloured clothes.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528BC8"
        },
        [80020309] = {
          ContentFR = "Les tons clairs mettent bien en valeur mes cheveux. Même si, lorsque je sors avec Mlle Flora, je préfère quand même porter un chapeau.",
          DialogueId = 80020309,
          GUID = "C8528BF2",
          NextDialogue = 80020310,
          SpeakNpcId = 93102,
          Subtitle = "Light colours really complement my hair. Though when I'm out with Miss Flora, I still tend to wear a hat.",
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528BF2"
        },
        [80020310] = {
          ContentFR = "Quant aux chaussures, je choisis toujours du rouge sombre. Un peu comme un gâteau au velours rouge : il faut bien quelques fruits rouges pour le parfaire.",
          DialogueId = 80020310,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528C1C",
          NextDialogue = 80020311,
          SpeakNpcId = 93102,
          Subtitle = "I always wear dark red shoes. You know, like a red velvet cake needs to be topped with red berries.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528C1C"
        },
        [80020311] = {
          ContentFR = "J’ajoute à ça un peu de parfum des Tisse-Étoiles, et quelques bijoux aux motifs venus d’ailleurs, de quoi me mettre de bonne humeur pour la journée.",
          DialogueId = 80020311,
          GUID = "C8528C46",
          NextDialogue = 80020312,
          SpeakNpcId = 93102,
          Subtitle = "I'd also dab on some fragrances and wear exotic accessories from the Starweavers — they really lift my spirits.",
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528C46"
        },
        [80020312] = {
          ContentFR = "Avec vos cheveux argentés, porter des tons lumineux vous donnerait sans doute un air plus vif et énergique.",
          DialogueId = 80020312,
          GUID = "C8528C70",
          NextOptions = {
            [1] = 800203121,
            [2] = 800203122
          },
          SpeakNpcId = 93102,
          Subtitle = "With your light silver hair, you'd look more vibrant in bright colours too.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528C70"
        },
        [80020313] = {
          ContentFR = "Hein ? Je pensais que c’était évident.",
          DialogueId = 80020313,
          FacialId = {
            [1] = "93102:Shock02"
          },
          GUID = "C8528C9A",
          NextDialogue = 80020315,
          SpeakNpcId = 93102,
          Subtitle = "Hmm? I thought it was pretty straightforward.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528C9A"
        },
        [80020314] = {
          ContentFR = "N’est-ce pas ? Vous devriez essayer aussi.",
          DialogueId = 80020314,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528CC4",
          NextDialogue = 80020315,
          SpeakNpcId = 93102,
          Subtitle = "Right? You should try it too.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528CC4"
        },
        [80020315] = {
          ContentFR = "En fait, à l’origine, si je fais attention à tout ça, c’est à cause de mon ancien travail. Un bon agent doit savoir se transformer en quelqu’un d’autre.",
          DialogueId = 80020315,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8528CEE",
          NextDialogue = 80020316,
          SpeakNpcId = 93102,
          Subtitle = "Actually, my fascination with this started during my career as an agent. We had to master the art of disguise, looking completely unlike ourselves.",
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528CEE"
        }
      }
    end
  },
  {
    MinKey = 80020316,
    MaxKey = 80040115,
    Loader = function()
      return {
        [80020316] = {
          ContentFR = "Alors j’ai commencé par les bases : une petite marchande de fleurs, une noble couverte de bijoux, une vieille femme chancelante... ou même, parfois, un \"prince\" ou une \"princesse\".",
          DialogueId = 80020316,
          FacialId = {
            [1] = "93102:Confident01"
          },
          GUID = "C8528D18",
          NextOptions = {
            [1] = 800203161
          },
          SpeakNpcId = 93102,
          Subtitle = "I started with the basics: playing a street flower girl, a heavy-jewelled lady, an elderly woman teetering in the breeze, and even a \"prince\" or \"princess\" at times.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528D18"
        },
        [80020317] = {
          ContentFR = "Oui. Tant que je ne parlais pas, personne ne remarquait rien. Il y a même eu quelques demoiselles de bonne famille qui m’ont offert leurs mouchoirs... C’était plutôt amusant.",
          DialogueId = 80020317,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8528D42",
          NextDialogue = 80020318,
          SpeakNpcId = 93102,
          Subtitle = "Mm-hmm, it was quite convincing as long as I remained silent. There were even a few noble ladies who gave me their handkerchiefs — it was adorable.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528D42"
        },
        [80020318] = {
          ContentFR = "Et à force de changer d’apparence, j’ai remarqué que mon humeur changeait aussi. Une robe, une paire de boucles d’oreilles... parfois, il ne faut pas plus pour vous redonner le sourire.",
          DialogueId = 80020318,
          GUID = "C8528D6C",
          NextDialogue = 80020319,
          SpeakNpcId = 93102,
          Subtitle = "Over time, I realised that disguising myself as someone else could also change my mood. Even a dress or a piece of jewellery can be a factor in brightening my day.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528D6C"
        },
        [80020319] = {
          ContentFR = "Depuis, je prends plaisir à faire du shopping et à m’acheter quelques tenues.",
          DialogueId = 80020319,
          GUID = "C8528D96",
          NextDialogue = 80020320,
          SpeakNpcId = 93102,
          Subtitle = "So, after that, I fell in love with shopping for new outfits.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528D96"
        },
        [80020320] = {
          ContentFR = "Bon, j’ai terminé mon verre. Allons-y. Je vais vous aider à choisir une tenue, pour vous remercier de ce verre.",
          DialogueId = 80020320,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8528DC0",
          SpeakNpcId = 93102,
          Subtitle = "Well, I've finished my drink. Let's go hit the shops. I'll help you put together an outfit as a thank-you.",
          VoiceName = "voice/$Locale$/inv/Xier/003/C8528DC0"
        },
        [80020401] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
          ContentFR = "Merci pour l’invitation... Mmh, vraiment, merci.",
          DialogueId = 80020401,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8529B0A",
          LookAt = {
            [1] = "93102:p(18000P1)"
          },
          NextDialogue = 80020402,
          SpeakNpcId = 93102,
          Subtitle = "Thanks for inviting me... Mm, thank you.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529B0A"
        },
        [80020402] = {
          ContentFR = "Une fois ce verre terminé, je comptais aller tailler quelques fleurs.",
          DialogueId = 80020402,
          GUID = "C8529B34",
          NextOptions = {
            [1] = 800204021,
            [2] = 800204022
          },
          SpeakNpcId = 93102,
          Subtitle = "After this drink, I'm off to trim the flowers.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529B34"
        },
        [80020403] = {
          ContentFR = "Pas vraiment. C’est justement parce que je suis de mauvaise humeur que j’ai envie de prendre les ciseaux.",
          DialogueId = 80020403,
          FacialId = {
            [1] = "93102:Disappoint01"
          },
          GUID = "C8529B5E",
          NextDialogue = 80020405,
          SpeakNpcId = 93102,
          Subtitle = "Quite the opposite, actually. I want to pick up the shears precisely because I'm not in the best spirits.",
          TalkActionId = {
            [1] = "93102:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529B5E"
        },
        [80020404] = {
          ContentFR = "Oh, ce n’est pas pour le travail, c’est ma façon de me détendre.",
          DialogueId = 80020404,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529B88",
          NextDialogue = 80020405,
          SpeakNpcId = 93102,
          Subtitle = "It's not about work, actually; it's more about stress relief.",
          TalkActionId = {
            [1] = "93102:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529B88"
        },
        [80020405] = {
          ContentFR = "Quand je suis trop stressée, j’ai ce réflexe étrange : je coupe les fleurs qui commencent à faner. Comme si, en taillant ce qui dépérit, je pouvais aussi trancher mes émotions négatives.",
          DialogueId = 80020405,
          GUID = "C8529BB2",
          NextDialogue = 80020406,
          SpeakNpcId = 93102,
          Subtitle = "When I feel the pressure mounting, I find snipping away at dying flowers quite cathartic — as if I'm trimming away my own gloom.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529BB2"
        },
        [80020406] = {
          ContentFR = "Quoi ? Cela vous paraît étrange ? C’est juste une manière de relâcher la pression. Après tout, je ne remplis pas mes missions juste en papotant.",
          DialogueId = 80020406,
          GUID = "C8529BDC",
          NextDialogue = 80020407,
          SpeakNpcId = 93102,
          Subtitle = "I hope you wouldn't find that strange. It's just my way of blowing off steam. After all, the assignments I take normally require much more than making conversations.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529BDC"
        },
        [80020407] = {
          ContentFR = "Quand j’étais encore agent, j’ai vu des collègues gérer leur stress de manière... disons, beaucoup plus malsaine.",
          DialogueId = 80020407,
          FacialId = {
            [1] = "93102:Unhappy02"
          },
          GUID = "C8529C06",
          NextDialogue = 80020408,
          SpeakNpcId = 93102,
          Subtitle = "Back when I was an agent, some of my colleagues had... let's say, darker ways of unwinding.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529C06"
        },
        [80020408] = {
          ContentFR = "Un assassinat qui ne prend qu’une seconde peut exiger un mois de préparation, une semaine de repérage, et une journée entière d’attente... Et si tu rates, tu peux dire adieu à ta liberté pour le reste de ta vie.",
          DialogueId = 80020408,
          GUID = "C8529C30",
          NextDialogue = 80020409,
          SpeakNpcId = 93102,
          Subtitle = "An assassination that lasts only seconds might require a month of planning, a week of prep, and a whole day of agonising wait — and failure could mean a lifetime behind bars.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529C30"
        },
        [80020409] = {
          ContentFR = "Dans ces conditions, couper deux ou trois fleurs au hasard, c’est plutôt inoffensif, non ?",
          DialogueId = 80020409,
          FacialId = {
            [1] = "93102:Iyada01"
          },
          GUID = "C8529C5A",
          NextOptions = {
            [1] = 800204091,
            [2] = 800204092
          },
          SpeakNpcId = 93102,
          Subtitle = "Considering that kind of pressure, randomly cutting several flowers seems quite mild, doesn't it?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529C5A"
        },
        [80020410] = {
          ContentFR = "Ce n’est pas vraiment un tracas, en fait.",
          DialogueId = 80020410,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529C84",
          NextDialogue = 80020412,
          SpeakNpcId = 93102,
          Subtitle = "Well, it's not really a bother.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529C84"
        },
        [80020411] = {
          ContentFR = "Il me semble que vous passez à côté du vrai sujet, non ?",
          DialogueId = 80020411,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529CAE",
          NextDialogue = 80020412,
          SpeakNpcId = 93102,
          Subtitle = "It seems you're missing the point of this conversation, aren't you?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529CAE"
        },
        [80020412] = {
          ContentFR = "Je pensais juste à quelqu’un... quelqu’un d’important.",
          DialogueId = 80020412,
          GUID = "C8529CD8",
          NextDialogue = 80020413,
          SpeakNpcId = 93102,
          Subtitle = "I was just thinking of... um, someone important.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529CD8"
        },
        [80020413] = {
          ContentFR = "Elle était agent, comme moi. Mais elle a toujours pensé que je n’étais pas faite pour ça. Alors, à l’époque, je voulais lui prouver que je pouvais non seulement faire le job, mais être la meilleure.",
          DialogueId = 80020413,
          GUID = "C8529D02",
          NextDialogue = 80020414,
          SpeakNpcId = 93102,
          Subtitle = "She was a fellow agent, but she always thought I wasn't cut out for the job. So I made so much effort trying to prove to her that I was not only competent but exceptional.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D02"
        },
        [80020414] = {
          ContentFR = "Finalement... elle avait raison.",
          DialogueId = 80020414,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C8529D2C",
          NextDialogue = 80020415,
          SpeakNpcId = 93102,
          Subtitle = "In the end, it turned out she was right.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D2C"
        },
        [80020415] = {
          ContentFR = "Je n’ai jamais su, comme elle, faire passer les missions avant tout le reste.",
          DialogueId = 80020415,
          GUID = "C8529D56",
          NextDialogue = 80020416,
          SpeakNpcId = 93102,
          Subtitle = "I couldn't put missions above all else like she could.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D56"
        },
        [80020416] = {
          ContentFR = "Mais au fond, je suis presque soulagée de ne pas avoir suivi exactement le même chemin.",
          DialogueId = 80020416,
          FacialId = {
            [1] = "93102:Happy01"
          },
          GUID = "C8529D80",
          NextDialogue = 80020417,
          SpeakNpcId = 93102,
          Subtitle = "Yet, there's a part of me that's relieved that I didn't end up walking her path.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529D80"
        },
        [80020417] = {
          ContentFR = "Quand j’ai quitté la Légion, on a perdu contact. Maintenant que ma vie est plus calme ici, je me demande parfois... si elle va bien.",
          DialogueId = 80020417,
          GUID = "C8529DAA",
          NextOptions = {
            [1] = 800204171
          },
          SpeakNpcId = 93102,
          Subtitle = "We lost touch when I left the Legion. Now that I'm settling in here, I find myself... wondering how she's doing.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529DAA"
        },
        [80020418] = {
          ContentFR = "Hein ? Hmm...",
          DialogueId = 80020418,
          FacialId = {
            [1] = "93102:Shock02"
          },
          GUID = "C8529DD4",
          NextDialogue = 80020419,
          SpeakNpcId = 93102,
          Subtitle = "Huh? Well...",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529DD4"
        },
        [80020419] = {
          ContentFR = "Vous avez raison. Plutôt que de rester là à couper des fleurs, autant aller la voir.",
          DialogueId = 80020419,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C8529DFE",
          SpeakNpcId = 93102,
          Subtitle = "You're right. Instead of trimming flowers here, perhaps I should just go see her in person.",
          VoiceName = "voice/$Locale$/inv/Xier/004/C8529DFE"
        },
        [80020501] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.196014,30.0,125.0,false,Manual,2.8",
          ContentFR = "Dès mon retour ici, vous êtes {性别:venu|venue} m’inviter à boire un verre. Dites-moi franchement, avez-vous appris quelques-uns de mes vieux tours d’agent et m’espionnez-vous en secret ?",
          DialogueId = 80020501,
          FacialId = {
            [1] = "93102:Confident02"
          },
          GUID = "C852AB72",
          LookAt = {
            [1] = "93102:p(18000P1)"
          },
          NextOptions = {
            [1] = 800205011,
            [2] = 800205012
          },
          SpeakNpcId = 93102,
          Subtitle = "You approached me as soon as I returned, inviting me for a drink. Please be honest with me — have you picked up some of my old agent tricks and been keeping tabs on me?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AB72"
        },
        [80020503] = {
          ContentFR = "Je ne faisais que plaisanter. En fait, vous êtes {性别:venu|venue} parce que vous vouliez savoir si j’avais retrouvé cette personne importante pour moi, n’est-ce pas ?",
          DialogueId = 80020503,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852ABC6",
          NextDialogue = 80020504,
          SpeakNpcId = 93102,
          Subtitle = "I was only teasing you. You came over because you're curious if I've met that lady who's important to me, aren't you?",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ABC6"
        },
        [80020504] = {
          ContentFR = "Pour être honnête, non. Elle a été mutée loin de la capitale pour certaines raisons, donc je n’ai entendu parler d’elle que par des bribes venant d’autres personnes.",
          DialogueId = 80020504,
          GUID = "C852ABF0",
          NextDialogue = 80020505,
          SpeakNpcId = 93102,
          Subtitle = "Truth be told, no. She was reassigned away from the capital for certain reasons, so I've only caught snippets about her from others.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ABF0"
        },
        [80020505] = {
          ContentFR = "Elle est dans une petite ville du sud, très différente d’ici où la glace et la neige règnent. Là-bas, elle peut profiter du soleil et écouter de la musique régulièrement.",
          DialogueId = 80020505,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C852AC1A",
          NextDialogue = 80020506,
          SpeakNpcId = 93102,
          Subtitle = "She's in a small town in the south — nothing like the icy grip here, but a place where she can enjoy bright sunlight and some music often.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC1A"
        },
        [80020506] = {
          ContentFR = "Je dois avouer que ça m’a un peu soulagée, car je ne savais pas trop comment la revoir... Mais savoir qu’elle va bien me rassure.",
          DialogueId = 80020506,
          GUID = "C852AC44",
          NextDialogue = 80020507,
          SpeakNpcId = 93102,
          Subtitle = "To be honest, I was relieved. Because I wasn't sure how I would face her... But knowing she's doing well gives me some peace of mind.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC44"
        },
        [80020507] = {
          ContentFR = "Cela signifie que le dernier lien entre moi, la Légion et mon passé d’agent est enfin coupé.",
          DialogueId = 80020507,
          GUID = "C852AC6E",
          NextOptions = {
            [1] = 800205071,
            [2] = 800205072
          },
          SpeakNpcId = 93102,
          Subtitle = "This means the last ties between me, the Legion, and my past life as an agent have finally been severed.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC6E"
        },
        [80020508] = {
          ContentFR = "Oui, enfin.",
          DialogueId = 80020508,
          GUID = "C852AC98",
          NextDialogue = 80020510,
          SpeakNpcId = 93102,
          Subtitle = "Yes, finally.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AC98"
        },
        [80020509] = {
          ContentFR = "Avant oui, mais plus maintenant.",
          DialogueId = 80020509,
          GUID = "C852ACC2",
          NextDialogue = 80020510,
          SpeakNpcId = 93102,
          Subtitle = "The old me would, but no, not anymore.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ACC2"
        },
        [80020510] = {
          ContentFR = "C’est en fait un membre proche de ma famille. C’est elle qui m’a poussée à rejoindre la Légion... et c’est aussi à cause d’elle que j’en suis partie.",
          DialogueId = 80020510,
          FacialId = {
            [1] = "93102:Iyada01"
          },
          GUID = "C852ACEC",
          NextDialogue = 80020511,
          SpeakNpcId = 93102,
          Subtitle = "She's actually a close family member of mine. She was the reason that I joined the Legion, and the reason I decided to leave.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ACEC"
        },
        [80020511] = {
          ContentFR = "Elle ne voulait pas que je fasse ce métier dangereux, mais j’ai tout fait pour lui prouver que j’étais capable, et que je pouvais partager certains de ses fardeaux.",
          DialogueId = 80020511,
          GUID = "C852AD16",
          NextDialogue = 80020512,
          SpeakNpcId = 93102,
          Subtitle = "She never wanted me to stay in such a dangerous profession, but I was desperate to show her that I could handle it — maybe even share some of her burdens.",
          TalkActionId = {
            [1] = "93102:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD16"
        },
        [80020512] = {
          ContentFR = "Le comble, c’est qu’elle et moi avons eu des missions opposées, elle devait éliminer Mlle Flora, moi, la protéger.",
          DialogueId = 80020512,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852AD40",
          NextDialogue = 800205121,
          SpeakNpcId = 93102,
          Subtitle = "It was the irony of fate that she and I received conflicting missions — hers to eliminate Miss Flora, mine to protect her.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD40"
        },
        [80020513] = {
          ContentFR = "Alors j’ai fui avec Mlle Flora avant que son plan d’assassinat ne démarre. Je n’avais ni le temps ni l’envie de repenser à mes jours dans la Légion ni à elle.",
          DialogueId = 80020513,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C852AD6A",
          NextDialogue = 80020514,
          SpeakNpcId = 93102,
          Subtitle = "So I took Miss Flora and fled before her assassination attempt could commence. At that time, I didn't have the leisure to dwell on my days in the Legion or anything related to her.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD6A"
        },
        [80020514] = {
          ContentFR = "C’est seulement maintenant, que tout est un peu plus calme, et que vous êtes là pour écouter mes histoires, que tout ça m’a pesé au point de me faire perdre pied il y a peu.",
          DialogueId = 80020514,
          GUID = "C852AD6B",
          NextOptions = {
            [1] = 800205141,
            [2] = 800205142
          },
          SpeakNpcId = 93102,
          Subtitle = "It's only because things have settled down recently, and you've been there for me to unload these old stories, that this whole thing had become a thorn in my heart, which led to my recent discomposure.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD6B"
        },
        [80020515] = {
          ContentFR = "La seule chose dont je suis sûre, c’est qu’un jour je devrai lui dire un adieu définitif. Avant, j’essayais de fuir cette réalité.",
          DialogueId = 80020515,
          GUID = "C852ADBE",
          NextDialogue = 80020516,
          SpeakNpcId = 93102,
          Subtitle = "What I knew for sure was that eventually, I had to confront a complete farewell with her, which was something I had been trying to run away from.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ADBE"
        },
        [80020516] = {
          ContentFR = "Maintenant que c’est arrivé, ça ne fait pas si mal. Je suis même soulagée de ne plus être hantée par ça.",
          DialogueId = 80020516,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852ADE8",
          NextDialogue = 80020517,
          SpeakNpcId = 93102,
          Subtitle = "Now that it's finally happened, it doesn't feel so bad. I'm even relieved that it'll no longer haunt me.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852ADE8"
        },
        [80020517] = {
          ContentFR = "J’ai plein de choses que je veux faire : tailler des fleurs, préparer des pâtisseries, m’acheter quelques nouvelles tenues, et peut-être même danser un peu.",
          DialogueId = 80020517,
          FacialId = {
            [1] = "93102:Smile02"
          },
          GUID = "C852AE12",
          NextDialogue = 80020518,
          SpeakNpcId = 93102,
          Subtitle = "I've got so much I want to do now — trim flowers, bake a cake, shop for new outfits, maybe even dance a little.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE12"
        },
        [80020518] = {
          ContentFR = "Mais ce que je veux surtout, c’est vous remercier. Vous m’avez vraiment aidée à tourner la page sur ce qui me pesait le plus.",
          DialogueId = 80020518,
          GUID = "C852AE3C",
          NextOptions = {
            [1] = 800205181,
            [2] = 800205182
          },
          SpeakNpcId = 93102,
          Subtitle = "But what I want to do most at the moment is thank you for helping me truly move on.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE3C"
        },
        [80020519] = {
          ContentFR = "Mais je dois aussi vous prévenir : maintenant que vous connaissez mon passé, cela veut dire qu’un jour, quand la Légion viendra pour moi et Mlle Flora, vous ne pourrez plus rester en dehors de tout ça.",
          DialogueId = 80020519,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852AE66",
          NextDialogue = 80020520,
          SpeakNpcId = 93102,
          Subtitle = "But I must also remind you: now that you know my past, it means that one day when the Legion comes after me and Miss Flora, you won't be able to stay out of it.",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE66"
        },
        [80020520] = {
          ContentFR = "J’espère que vous n’êtes pas trop effrayé. On dirait que je vous ai tendu un bonbon empoisonné, non ?",
          DialogueId = 80020520,
          FacialId = {
            [1] = "93102:Confident01"
          },
          GUID = "C852AE90",
          NextDialogue = 80020521,
          SpeakNpcId = 93102,
          Subtitle = "I hope you're not too scared. Do you feel like I've handed you a sugar-coated poison?",
          TalkActionId = {
            [1] = "93102:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE90"
        },
        [80020521] = {
          ContentFR = "Rassurez-vous, moi, Hilda, la servante capable de tout, je prendrai mes responsabilités et resterai toujours à vos côtés pour vous protéger.",
          DialogueId = 80020521,
          FacialId = {
            [1] = "93102:None"
          },
          GUID = "C852AEBA",
          SpeakNpcId = 93102,
          Subtitle = "Please rest assured that, I, Hilda, the all-capable maid, will always ensure your safety.",
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AEBA"
        },
        [80020522] = {
          ContentFR = "Merci, ça vous semble bizarre que je vous remercie ? C’est sincère.",
          DialogueId = 80020522,
          FacialId = {
            [1] = "93102:Happy02"
          },
          GUID = "C852AE65",
          NextDialogue = 80020519,
          SpeakNpcId = 93102,
          Subtitle = "Thank you — is it so strange to hear that from me? I mean it sincerely.",
          TalkActionId = {
            [1] = "93102:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AE65"
        },
        [80030100] = {
          ContentFR = "Les vacances, c’est précieux. Et les passer avec toi, c’est presque aussi bien que de dormir.",
          DialogueId = 80030100,
          GUID = "C878DD68",
          Subtitle = "This holiday is precious, and spending it with you is just as enjoyable as sleeping.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C878DD68"
        },
        [80030101] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentFR = "Après une bonne sieste, un petit verre... Ah, rien de mieux que de ne pas bosser, c’est la vraie vie !",
          DialogueId = 80030101,
          GUID = "C858D272",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030102,
          SpeakNpcId = 94202,
          Subtitle = "Nothing beats having a refreshing drink after a good rest. It's so wonderful to have a break from work!",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D272"
        },
        [80030102] = {
          ContentFR = "Ah, au fait, on m’a refilé un colis juste avant que je vienne. Je l’ai même pas encore ouvert, voyons un peu...",
          DialogueId = 80030102,
          GUID = "C858D29C",
          NextDialogue = 80030103,
          SpeakNpcId = 94202,
          Subtitle = "Speaking of which, I got a package before I came here. Let me take a look.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D29C"
        },
        [80030103] = {
          ContentFR = "Ça doit être le pyjama et l’encens pour dormir que j’ai demandé à mes gars... Parfait, je vais pouvoir faire une sieste tranquille après.",
          DialogueId = 80030103,
          GUID = "C858D2C6",
          NextDialogue = 80030104,
          SpeakNpcId = 94202,
          Subtitle = "This must be the pyjamas and incense my subordinate bought me as a sleep aid. Perfect, I'll go back home and take another rest.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D2C6"
        },
        [80030104] = {
          ContentFR = "Hein ? C’est quoi ça... « Proposition pour optimiser les plantes décoratives de la XIIIᵉ Légion » ? « Demande d’achat d’installations de loisirs pour booster le moral des soldats » ?",
          DialogueId = 80030104,
          GUID = "C858D2F0",
          NextDialogue = 80030105,
          SpeakNpcId = 94202,
          Subtitle = "Huh? \"Proposal on the Optimisation of Ornamental Plants of the 13th Legion\"? \"Application for Purchasing Recreational Facilities to Enhance Soldiers' Morale\"?",
          TalkActionId = {
            [1] = "94202:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D2F0"
        },
        [80030105] = {
          ContentFR = "Ah, boulot, boulot... Ça a l’air ok, mais on en reparlera plus tard. Personne ne va me gâcher mes vacances. Peut-être la commandante, mais elle viendra pas ici.",
          DialogueId = 80030105,
          GUID = "C858D31A",
          NextOptions = {
            [1] = 800301051,
            [2] = 800301052
          },
          SpeakNpcId = 94202,
          Subtitle = "Urgh, it's always about work. Let's talk about this later. I won't let my holiday be spoiled by anything or anyone, except the Chief. But I doubt she'll show up here.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D31A"
        },
        [80030106] = {
          ContentFR = "Trouver des règles aussi pratiques, ça s’invente pas tout seul, hein.",
          DialogueId = 80030106,
          GUID = "C858D344",
          NextDialogue = 80030108,
          SpeakNpcId = 94202,
          Subtitle = "It's not easy to come up with such practical principles as these.",
          TalkActionId = {
            [1] = "94202:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D344"
        },
        [80030107] = {
          ContentFR = "Hé, t’appelles ça glander ? Pas du tout.",
          DialogueId = 80030107,
          FacialId = {
            [1] = "94202:Blink"
          },
          GUID = "C858D36E",
          NextDialogue = 80030108,
          SpeakNpcId = 94202,
          Subtitle = "Whoa, how could you call this \"slacking off\"?",
          TalkActionId = {
            [1] = "94202:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D36E"
        },
        [80030108] = {
          ContentFR = "C’est mon fameux \"Mode Howard énergie optimale\" que j’ai inventé, un vrai boulot de titan.",
          DialogueId = 80030108,
          GUID = "C858D398",
          NextDialogue = 80030109,
          SpeakNpcId = 94202,
          Subtitle = "This is the \"Howard High-Efficiency Energy-Saving Mode\", created by yours truly, Randy Howard.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D398"
        },
        [80030109] = {
          ContentFR = "Quand je me repose, je débranche complètement la tête du boulot, comme ça je redémarre sans stresser.",
          DialogueId = 80030109,
          GUID = "C858D3C2",
          NextDialogue = 80030110,
          SpeakNpcId = 94202,
          Subtitle = "When you take a break, clear your mind of all work so that you can start working again in a good mood. That way, you won't dread getting back to work.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D3C2"
        },
        [80030110] = {
          ContentFR = "Après des années à peaufiner ça, c’est devenu redoutablement efficace.",
          DialogueId = 80030110,
          GUID = "C858D3EC",
          NextDialogue = 80030111,
          SpeakNpcId = 94202,
          Subtitle = "After years of practising and optimising this method, I've got it working perfectly.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D3EC"
        },
        [80030111] = {
          ContentFR = "Ça me permet de trouver la solution la plus \"économe\" en énergie pour n’importe quel problème, en un clin d’œil.",
          DialogueId = 80030111,
          GUID = "C858D416",
          NextDialogue = 80030112,
          SpeakNpcId = 94202,
          Subtitle = "This has helped me to figure out the most energy-saving solution to different problems in seconds.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D416"
        },
        [80030112] = {
          ContentFR = "Comme cette conversation qui cache un double jeu.",
          DialogueId = 80030112,
          GUID = "C858D417",
          NextDialogue = 80030113,
          SpeakNpcId = 94202,
          Subtitle = "Such as this conversation with an ulterior motive.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D417"
        },
        [80030113] = {
          ContentFR = "<I>Hein ? Je ne comprends pas.</>",
          DialogueId = 80030113,
          GUID = "80030113.0",
          NextDialogue = 80030114,
          SpeakNpcId = 790008,
          Subtitle = "Huh? I'm not following."
        },
        [80030114] = {
          ContentFR = "C’est un peu tard pour faire l’{性别:innocent|innocente}, non ?",
          DialogueId = 80030114,
          GUID = "C858D418",
          NextDialogue = 80030115,
          SpeakNpcId = 94202,
          Subtitle = "A bit too late to play dumb, don't you think?",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D418"
        },
        [80030115] = {
          ContentFR = "<I>... Dis-moi, Berenica va bien, oui ou non ?</>",
          DialogueId = 80030115,
          GUID = "80030115.0",
          NextDialogue = 80030116,
          SpeakNpcId = 790008,
          Subtitle = "...Tell me, how's Berenica doing now?!"
        },
        [80030116] = {
          ContentFR = "Alors c’est comme ça que s’appelle n° 0... Berenica, hein.",
          DialogueId = 80030116,
          GUID = "C858D419",
          NextDialogue = 80030117,
          SpeakNpcId = 94202,
          Subtitle = "Hah, so that's No. 0's name — Berenica.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D419"
        },
        [80030117] = {
          ContentFR = "<I>Un peu tard pour faire le naïf.</>",
          DialogueId = 80030117,
          GUID = "80030117.0",
          NextDialogue = 80030118,
          SpeakNpcId = 790008,
          Subtitle = "A bit late to play dumb too, I'd say."
        },
        [80030118] = {
          ContentFR = "Les gens malins savent qu’il faut toujours commencer par faire un peu le naïf.",
          DialogueId = 80030118,
          GUID = "C858D41A",
          NextDialogue = 80030119,
          SpeakNpcId = 94202,
          Subtitle = "Well, playing dumb is how smart people start a conversation.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41A"
        },
        [80030119] = {
          ContentFR = "Mais franchement, tu peux me poser la question, ça changera rien. Même si je te disais, tu pourrais pas vérifier.",
          DialogueId = 80030119,
          GUID = "C858D41B",
          NextDialogue = 80030120,
          SpeakNpcId = 94202,
          Subtitle = "But honestly, your question's moot. For starters, even if I did tell you something, there's no way you could verify it.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41B"
        },
        [80030120] = {
          ContentFR = "Deuxièmement, avec mon \"Mode Howard énergie optimale\", le boulot c’est le boulot, la vie c’est la vie.",
          DialogueId = 80030120,
          GUID = "C858D41C",
          NextDialogue = 80030121,
          SpeakNpcId = 94202,
          Subtitle = "Secondly, in the principle of the \"Howard High-Efficiency Energy-Saving Mode\", I keep work and life separate.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41C"
        },
        [80030121] = {
          ContentFR = "La vie peut s’immiscer dans le boulot, mais pas l’inverse. Là, je suis en congé, donc je fais comme si on se voyait en pause. C’est la manière la plus \"éco-énergétique\" de gérer ça.",
          DialogueId = 80030121,
          GUID = "C858D41D",
          NextDialogue = 80030122,
          SpeakNpcId = 94202,
          Subtitle = "Life might blend into work, but work must never intrude on my life. Right now, I'm technically on vacation, and that's the most \"energy-efficient\" way I operate.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41D"
        },
        [80030122] = {
          ContentFR = "Du coup, aujourd’hui ou plus tard, les discussions sur n° 0 n’avanceront pas, mais si c’est pour parler de la vie, là, je suis tout ouïe.",
          DialogueId = 80030122,
          GUID = "C858D41E",
          NextDialogue = 80030123,
          SpeakNpcId = 94202,
          Subtitle = "So, this conversation and any future talks about No. 0 aren't gonna get anywhere; but if you want to chat about life and other fun stuff, I'm all ears.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41E"
        },
        [80030123] = {
          ContentFR = "<I>Bon, on n’a plus rien à se dire, tu peux y aller.</>",
          DialogueId = 80030123,
          GUID = "C858D41F",
          NextDialogue = 80030124,
          SpeakNpcId = 790008,
          Subtitle = "Then it seems we're done here. You can leave.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D41F"
        },
        [80030124] = {
          ContentFR = "Je peux pas te dire où elle est, mais je garantis qu’elle est en sécurité.",
          DialogueId = 80030124,
          GUID = "C858D421",
          NextDialogue = 80030125,
          SpeakNpcId = 94202,
          Subtitle = "While I can't disclose her whereabouts, I can assure you, she's safe.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D421"
        },
        [80030125] = {
          ContentFR = "<I>Je peux pas vraiment croire à ta garantie.</>",
          DialogueId = 80030125,
          GUID = "C858D422",
          NextDialogue = 80030126,
          SpeakNpcId = 790008,
          Subtitle = "There's no way I could verify that.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D422"
        },
        [80030126] = {
          ContentFR = "Haha, les malins apprennent vite !",
          DialogueId = 80030126,
          GUID = "C858D423",
          NextDialogue = 80030127,
          SpeakNpcId = 94202,
          Subtitle = "Hahaha, smart people are all quick learners.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D423"
        },
        [80030127] = {
          ContentFR = "Bon, j’ai été sympa, c’est triste que ça ne soit pas apprécié... Je vais sûrement pas bien dormir demain...",
          DialogueId = 80030127,
          GUID = "C858D4BE",
          NextDialogue = 80030128,
          SpeakNpcId = 94202,
          Subtitle = "*sigh* It's sad to see good intentions go unappreciated — so much so that I might not be able to rest properly tomorrow...",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D4BE"
        },
        [80030128] = {
          ContentFR = "Ah, je devrais essayer un congé maladie pendant mes vacances : je suis trop malade pour me reposer, donc j’allonge mes congés, ça tient la route, non ?!",
          DialogueId = 80030128,
          GUID = "C858D4E8",
          NextDialogue = 80030129,
          SpeakNpcId = 94202,
          Subtitle = "Oh, wait! Maybe I should try to extend my holiday by taking sick leave. Like, I need a prolonged holiday 'cause my illness had prevented me from getting proper rest. That makes perfect sense, doesn't it?!",
          TalkActionId = {
            [1] = "94202:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D4E8"
        },
        [80030129] = {
          ContentFR = "Et comme raison... je dirais que j’ai des douleurs un peu partout, surtout au niveau du cœur.",
          DialogueId = 80030129,
          GUID = "C858D512",
          NextDialogue = 80030130,
          SpeakNpcId = 94202,
          Subtitle = "And the reason I'll use will be... I feel achy all over, especially in my heart.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D512"
        },
        [80030130] = {
          ContentFR = "Je dirai que c’est à cause d’un conflit lors d’une enquête d’opinion, mais que ça s’est arrangé en privé. Peut-être que je toucherai une indemnité... Aujourd’hui a été une bonne journée.",
          DialogueId = 80030130,
          GUID = "C858D53C",
          NextDialogue = 80030131,
          SpeakNpcId = 94202,
          Subtitle = "Because of a conflict during a public opinion survey... but it has been resolved through private negotiations. Maybe I'll even get compensation out of it. Today has been very fruitful.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D53C"
        },
        [80030131] = {
          ContentFR = "En deux secondes, t’as réussi à me prolonger les vacances. T’es vraiment {性别:un|une} super pote !",
          DialogueId = 80030131,
          GUID = "C858D566",
          NextDialogue = 80030132,
          SpeakNpcId = 94202,
          Subtitle = "You just extended my holiday in mere seconds. My friend, you're the best!",
          TalkActionId = {
            [1] = "94202:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D566"
        },
        [80030132] = {
          ContentFR = "J’attends avec impatience ma prochaine excuse pour... enfin, notre prochaine rencontre.",
          DialogueId = 80030132,
          GUID = "C858D590",
          SpeakNpcId = 94202,
          Subtitle = "I'm looking forward to my next excuse for... Ahem... I mean, our next meeting.",
          VoiceName = "voice/$Locale$/inv/Landi/001/C858D590"
        },
        [80030201] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentFR = "On dirait que tu es enfin {性别:prêt|prête} à papoter un peu de la vie, hein ?",
          DialogueId = 80030201,
          GUID = "C858E2DA",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030202,
          SpeakNpcId = 94202,
          Subtitle = "Looks like you're finally up for some casual chats, huh?",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E2DA"
        },
        [80030202] = {
          ContentFR = "Bon, même si je suis en mission à Givrelac, cette rencontre, c’est pas du boulot. Faut pas croire que je suis juste de passage. J’ai pris un congé exprès pour venir boire un verre avec toi.",
          DialogueId = 80030202,
          GUID = "C858E304",
          NextDialogue = 80030203,
          SpeakNpcId = 94202,
          Subtitle = "I'm still on a mission, so I couldn't meet up with you during working hours. I requested leave especially to grab a drink with you.",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E304"
        },
        [80030203] = {
          ContentFR = "Comme excuse, j’ai dit que j’avais été invité à danser par une jeune noble de la cité intérieure.",
          DialogueId = 80030203,
          GUID = "C858E32E",
          NextDialogue = 80030204,
          SpeakNpcId = 94202,
          Subtitle = "And my reason for this leave... I told them I was invited to a dance by a young lady of nobility.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E32E"
        },
        [80030204] = {
          ContentFR = "Faut pas être surpris, c’est pas la première fois qu’un jeune officier et une dame de la noblesse s’amusent un peu ensemble. Le commandement ferme les yeux là-dessus. Et puis si ça marche, ça renforce le poids de la Légion, alors ce n’est pas si mal.",
          DialogueId = 80030204,
          GUID = "C858E358",
          NextDialogue = 80030205,
          SpeakNpcId = 94202,
          Subtitle = "Oh don't be surprised. It's quite common for young officers and noble ladies to have romantic affairs. The Legion turns a blind eye to them. After all, having relations with \"the nobility\" can bolster the Legion's influence.",
          VoiceName = "voice/$Locale$/inv/Landi/0/C858E358"
        },
        [80030205] = {
          ContentFR = "En tant que vrai gentleman, c’est tout à fait normal que je prolonge mes congés pour ce genre de motifs.",
          DialogueId = 80030205,
          GUID = "C858E382",
          NextOptions = {
            [1] = 800302051,
            [2] = 800302052
          },
          SpeakNpcId = 94202,
          Subtitle = "As a gentleman, I had to take longer leave for this reason. I think it makes perfect sense.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E382"
        },
        [80030206] = {
          ContentFR = "Tu me brises le cœur... Je vais devoir prolonger mon congé pour m’en remettre.",
          DialogueId = 80030206,
          GUID = "C858E3AC",
          NextDialogue = 80030208,
          SpeakNpcId = 94202,
          Subtitle = "Your words are like a dagger in my heart. I might have to extend my leave to recover from that burn.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E3AC"
        },
        [80030207] = {
          ContentFR = "Ah, je vais faire comme si c’était sincère. Merci !",
          DialogueId = 80030207,
          GUID = "C858E3D6",
          NextDialogue = 80030208,
          SpeakNpcId = 94202,
          Subtitle = "Thank you, I'll take that as a compliment.",
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E3D6"
        },
        [80030208] = {
          ContentFR = "Avec le temps, j’ai compris qu’on utilise surtout \"gentleman\" pour taquiner, rarement pour vraiment complimenter.",
          DialogueId = 80030208,
          GUID = "C858E400",
          NextDialogue = 80030209,
          SpeakNpcId = 94202,
          Subtitle = "I'm aware by the way, that \"gentleman\" is often used sarcastically, not as praise.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E400"
        },
        [80030209] = {
          ContentFR = "Quand j’étais petit, mes sœurs me disaient que devenir un gentleman, c’était le but ultime pour un garçon, le sens de la vie.",
          DialogueId = 80030209,
          GUID = "C858E42A",
          NextOptions = {
            [1] = 800302091,
            [2] = 800302092
          },
          SpeakNpcId = 94202,
          Subtitle = "When I was little, my sisters told me that being a gentleman is the ultimate goal for a man.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E42A"
        },
        [80030210] = {
          ContentFR = "Peut-être que tu dis ça parce que t’as une bonne image de moi... mais non, c’étaient tout sauf des dames.",
          DialogueId = 80030210,
          GUID = "C858E454",
          NextDialogue = 80030212,
          SpeakNpcId = 94202,
          Subtitle = "Maybe you're making that assumption based on your high opinion of me, but unfortunately, they're not lovely ladies, not at all.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E454"
        },
        [80030211] = {
          ContentFR = "On est tous passés par là, naïf et mignon.",
          DialogueId = 80030211,
          GUID = "C858E47E",
          NextDialogue = 80030212,
          SpeakNpcId = 94202,
          Subtitle = "I was just like any ordinary kid. Dumb and naive.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E47E"
        },
        [80030212] = {
          ContentFR = "C’est un vieux souvenir d’enfance qui fait encore un peu mal... mais puisqu’on est potes de vacances, je peux bien t’en parler.",
          DialogueId = 80030212,
          GUID = "C858E4A8",
          NextDialogue = 80030213,
          SpeakNpcId = 94202,
          Subtitle = "Look, I really don't feel like talking about my sisters. They tormented me during my childhood. But since you're my holiday buddy, I will tell you this.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E4A8"
        },
        [80030213] = {
          ContentFR = "J’ai grandi sous la \"bienveillance\" de mes sœurs ! Pour survivre à leurs griffes... euh, à leur attention, j’ai dû développer des talents...",
          DialogueId = 80030213,
          GUID = "C858E4D2",
          NextOptions = {
            [1] = 800302131,
            [2] = 800302132
          },
          SpeakNpcId = 94202,
          Subtitle = "I grew up with their \"love\". To survive their clutches... ahem, I mean love, I had to develop many skills.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E4D2"
        },
        [80030214] = {
          ContentFR = "Oui, bienveillance... mais pas beaucoup.",
          DialogueId = 80030214,
          GUID = "C858E4FC",
          NextDialogue = 80030216,
          SpeakNpcId = 94202,
          Subtitle = "Yeah, love. Tough love.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E4FC"
        },
        [80030215] = {
          ContentFR = "C’est pas que j’ai souffert, c’est la vie qui m’a malmené.",
          DialogueId = 80030215,
          GUID = "C858E526",
          NextDialogue = 80030216,
          SpeakNpcId = 94202,
          Subtitle = "Yeah, it was rather bitter.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E526"
        },
        [80030216] = {
          ContentFR = "Elles me répétaient sans arrêt qu’un gentleman devait embrasser l’ourlet de la robe d’une dame quand ils se rencontraient, respecter les règles et cacher ses vrais sentiments.",
          DialogueId = 80030216,
          GUID = "C858E550",
          NextDialogue = 80030217,
          SpeakNpcId = 94202,
          Subtitle = "Back then, they told me that a gentleman should kiss a lady's dress when they meet, and that one should adhere to principles and etiquette to conceal their true thoughts and feelings.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E550"
        },
        [80030217] = {
          ContentFR = "J’avais à peine cinq ou six ans, j’étais pas hyper motivé, mais pour devenir un vrai gentleman, je parlais à toutes les dames que je croisais.",
          DialogueId = 80030217,
          GUID = "C858E57A",
          NextDialogue = 80030218,
          SpeakNpcId = 94202,
          Subtitle = "When I was five or six years old, I acted like a gentleman to every woman I met, even though I didn't want to.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E57A"
        },
        [80030218] = {
          ContentFR = "Tu peux imaginer leurs rires derrière moi. Heureusement, le lendemain, elles m’ont dit qu’un gentleman n’avait pas besoin d’aller aussi loin.",
          DialogueId = 80030218,
          GUID = "C858E5A4",
          NextDialogue = 80030219,
          SpeakNpcId = 94202,
          Subtitle = "You can imagine how my sisters watched me and laughed. Later on, they told me that gentlemen didn't really have to do that.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E5A4"
        },
        [80030219] = {
          ContentFR = "Enfin, elles m’ont ensuite dit que c’était plutôt la main qu’il fallait embrasser, pas la robe.",
          DialogueId = 80030219,
          GUID = "C858E5CE",
          NextDialogue = 80030220,
          SpeakNpcId = 94202,
          Subtitle = "They should actually kiss the back of a lady's hand. Not her dress.",
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E5CE"
        },
        [80030220] = {
          ContentFR = "Bon, plus j’y pense, plus ça me fait mal au cœur. Allez, on boit un coup à mon enfance traumatisante.",
          DialogueId = 80030220,
          GUID = "C858E5F8",
          SpeakNpcId = 94202,
          Subtitle = "Anyway, let's not talk about this. Here's a toast to my miserable childhood.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/002/C858E5F8"
        },
        [80030401] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentFR = "Je suis là, je ne pouvais pas te poser un lapin, quand même ?",
          DialogueId = 80030401,
          GUID = "C85903AA",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextDialogue = 80030402,
          SpeakNpcId = 94202,
          Subtitle = "I'm here. I couldn't stand you up now, could I?",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85903AA"
        },
        [80030402] = {
          ContentFR = "Tiens, voilà le \"Conteneur militaire à régulation thermique\" amélioré. Je l’ai déjà testé, aucun souci... <I>bâille</>...",
          DialogueId = 80030402,
          GUID = "C85903D4",
          NextDialogue = 80030403,
          SpeakNpcId = 94202,
          Subtitle = "Check this out. The Military Alloy Temperature Control Vessel - Ultimate Type. I've tried it, and it works like a charm... *yawn*",
          TalkActionId = {
            [1] = "94202:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85903D4"
        },
        [80030403] = {
          ContentFR = "Mais là, je suis crevé, il faut que je trouve un endroit pour pioncer un peu. Mes congés sont presque finis, demain je peux pas aller voir la commandante Sibylle avec des cernes.",
          DialogueId = 80030403,
          GUID = "C85903FE",
          NextOptions = {
            [1] = 800304031,
            [2] = 800304032
          },
          SpeakNpcId = 94202,
          Subtitle = "I'm feeling a bit drowsy at the moment, I need to find a place to get some shut-eye. I've nearly run out of annual leave, and I can't report to Chief Sibylle tomorrow with dark rings around my eyes.",
          TalkActionId = {
            [1] = "94202:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85903FE"
        },
        [80030404] = {
          ContentFR = "T’as l’œil, oui, il y a un truc qui me chiffonne.",
          DialogueId = 80030404,
          GUID = "C8590428",
          NextDialogue = 80030405,
          SpeakNpcId = 94202,
          Subtitle = "You're very perceptive. Yes, there's something on my mind.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590428"
        },
        [80030405] = {
          ContentFR = "Puisque tu l’as remarqué, je vais pas te le cacher : j’ai fait un cauchemar.",
          DialogueId = 80030405,
          GUID = "C8590452",
          NextOptions = {
            [1] = 800304071
          },
          SpeakNpcId = 94202,
          Subtitle = "I won't keep it from you. Basically, I had a nightmare.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590452"
        },
        [80030406] = {
          ContentFR = "Bien sûr que non. Tu sais combien je suis paresseux. Je refuse la plupart des invitations.",
          DialogueId = 80030406,
          GUID = "C859047C",
          NextDialogue = 80030407,
          SpeakNpcId = 94202,
          Subtitle = "Of course not. You know how lazy I am. I turn most invitations down.",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C859047C"
        },
        [80030407] = {
          ContentFR = "Pour être honnête, j’ai fait un cauchemar cette nuit, alors je ne me sens pas très bien aujourd'hui.",
          DialogueId = 80030407,
          GUID = "C85904A6",
          NextOptions = {
            [1] = 800304071
          },
          SpeakNpcId = 94202,
          Subtitle = "To be honest, I had a nightmare last night, so I'm feeling a bit off today.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85904A6"
        },
        [80030408] = {
          ContentFR = "Comme beaucoup d’autres, c’était encore au sujet de mon père, ce casse-pieds...",
          DialogueId = 80030408,
          GUID = "C85904D0",
          NextOptions = {
            [1] = 800304081
          },
          SpeakNpcId = 94202,
          Subtitle = "Well, like many of my nightmares, this one was about my dad.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85904D0"
        },
        [80030409] = {
          ContentFR = "Oui, c’était aussi un soldat de l’Empire. Mais maintenant... il est alité depuis plusieurs années.",
          DialogueId = 80030409,
          GUID = "C85904FA",
          NextDialogue = 80030410,
          SpeakNpcId = 94202,
          Subtitle = "He used to be a soldier in the Empire, but... he's been bedridden for years now.",
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85904FA"
        },
        [80030410] = {
          ContentFR = "À l’époque où mes sœurs me dupaient pour que je devienne un gentleman, lui, il était déjà sergent dans la Légion. Il passait plus de temps au front qu’à la maison, un peu comme moi aujourd’hui.",
          DialogueId = 80030410,
          GUID = "C8590524",
          NextDialogue = 80030411,
          SpeakNpcId = 94202,
          Subtitle = "Back when I was tricked by my sisters into becoming a gentleman, he was a sergeant in the Legion. He spent more time on the front lines than at home, just like me now.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590524"
        },
        [80030411] = {
          ContentFR = "Mais à la différence de moi, il était fier de son uniforme. Pour lui, la Légion était sa vraie maison, et notre foyer n’était qu’un hôtel où il pouvait se plaindre à sa guise.",
          DialogueId = 80030411,
          GUID = "C859054E",
          NextDialogue = 80030412,
          SpeakNpcId = 94202,
          Subtitle = "But the difference between us is that he was proud of being a soldier. He treated the Legion as his home and his actual home as nothing more than a hotel where he could complain as much as he liked.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859054E"
        },
        [80030412] = {
          ContentFR = "À chaque retour, il râlait. La photo de l’Empereur était mal accrochée. Mes sœurs rentraient trop tard...",
          DialogueId = 80030412,
          GUID = "C8590578",
          NextDialogue = 80030413,
          SpeakNpcId = 94202,
          Subtitle = "Whenever he came home, he'd complain about something or other, like the Emperor's portrait not being hung up properly, or my sisters coming home too late.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590578"
        },
        [80030413] = {
          ContentFR = "Mais il y avait toujours un rituel. Il m’inspectait.",
          DialogueId = 80030413,
          GUID = "C85905A2",
          NextDialogue = 80030414,
          SpeakNpcId = 94202,
          Subtitle = "And he'd always check up on me last.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85905A2"
        },
        [80030414] = {
          ContentFR = "Il mesurait ma taille, comptait mes lectures, vérifiait si je connaissais les noms des forteresses, et demandait mes nouvelles compétences de survie.",
          DialogueId = 80030414,
          GUID = "C85905CC",
          NextDialogue = 80030415,
          SpeakNpcId = 94202,
          Subtitle = "He'd check how much taller I'd got, how many books I'd read, how many forts I'd learned the names of, and what new survival skills I'd acquired.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85905CC"
        },
        [80030415] = {
          ContentFR = "J’ai essayé de parler d’autre chose, mais rien ne l’intéressait en dehors d’être \"soldat\".",
          DialogueId = 80030415,
          GUID = "C85905F6",
          NextDialogue = 80030416,
          SpeakNpcId = 94202,
          Subtitle = "I tried talking to him about other things, but he wasn't interested in anything other than \"being a soldier.\"",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85905F6"
        },
        [80030416] = {
          ContentFR = "Un jour, pour lui faire plaisir, j’ai sculpté une petite arme en bois, comme mes gadgets actuels, tout fier d’attendre ses compliments.",
          DialogueId = 80030416,
          GUID = "C8590620",
          NextDialogue = 80030417,
          SpeakNpcId = 94202,
          Subtitle = "Once, to try to please him, I painstakingly carved a wooden pistol for him and eagerly awaited his praise.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590620"
        },
        [80030417] = {
          ContentFR = "Mais il l’a juste jetée sur la table en disant d’un ton sévère : « Arrête ces bêtises et concentre-toi sur comment devenir un bon soldat. »",
          DialogueId = 80030417,
          GUID = "C859064A",
          NextDialogue = 80030418,
          SpeakNpcId = 94202,
          Subtitle = "But with a stren face he just snatched it from me, \"Don't waste your time on things like this. Think about how you can become a better soldier from now on.\"",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859064A"
        },
        [80030418] = {
          ContentFR = "À ce moment-là, j’ai ressenti un froid, une douleur tranchante comme le vent dehors, invisible et insupportable.",
          DialogueId = 80030418,
          GUID = "C8590674",
          NextDialogue = 80030419,
          SpeakNpcId = 94202,
          Subtitle = "At that moment, I felt something change within me. Something cold, bitter, intangible and unstoppable, like the howling wind outside our home.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590674"
        },
        [80030419] = {
          ContentFR = "Avec le temps, j’ai compris que c’était de la haine, pas très forte, mais suffisante pour voir cet homme comme un inconnu détestable.",
          DialogueId = 80030419,
          GUID = "C859069E",
          NextDialogue = 80030420,
          SpeakNpcId = 94202,
          Subtitle = "Later, I gradually realised that it was hatred. Although it was weak to begin with, it was still strong enough to make me feel that the person in front of me was nothing more than a stranger.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859069E"
        },
        [80030420] = {
          ContentFR = "Après ça, j’ai arrêté de chercher à lui plaire, ignoré ses inspections, et ses insultes.",
          DialogueId = 80030420,
          GUID = "C85906C8",
          NextDialogue = 80030421,
          SpeakNpcId = 94202,
          Subtitle = "So after that, I stopped trying to be the son he wanted me to be. I ignored his check-ups on me, no matter how much he scolded me.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85906C8"
        },
        [80030421] = {
          ContentFR = "Puis un jour, il est revenu, blessé à la tête en protégeant ses hommes. Il était vivant, mais inconscient.",
          DialogueId = 80030421,
          GUID = "C85906F2",
          NextDialogue = 80030422,
          SpeakNpcId = 94202,
          Subtitle = "Years passed... He was shot in the head while protecting one of his subordinates. He was sent home with a purple heart. Although he was still alive, he had fallen into a coma.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85906F2"
        },
        [80030422] = {
          ContentFR = "Il n’avait pas d’économies, avait envoyé tout son salaire à la maison, et la seule chose qui l’accompagnait, c’était une médaille brillante... et une arme en bois cassée en deux.",
          DialogueId = 80030422,
          GUID = "C859071C",
          NextDialogue = 80030423,
          SpeakNpcId = 94202,
          Subtitle = "When he came back, he had nothing but shiny medals, his slender savings, and a wooden pistol that was broken in two.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859071C"
        },
        [80030423] = {
          ContentFR = "Je pensais que c’était parce qu’il était déçu de moi, mais ses hommes m’ont dit qu’il gardait toujours cette arme sur lui, et qu’elle s’est cassée quand il est tombé.",
          DialogueId = 80030423,
          GUID = "C8590746",
          NextDialogue = 80030424,
          SpeakNpcId = 94202,
          Subtitle = "I thought he was disappointed in me because of that broken pistol, but his subordinates told me that he carried it with him at all times and that it broke when he fell on the battlefield.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590746"
        },
        [80030424] = {
          ContentFR = "Au fond, il m’aimait, mais sa façon de le montrer m’était insupportable.",
          DialogueId = 80030424,
          GUID = "C8590770",
          NextDialogue = 80030425,
          SpeakNpcId = 94202,
          Subtitle = "It seems that he did love me after all. But his way of expressing it was unrecognisable. Maddening.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590770"
        },
        [80030425] = {
          ContentFR = "S’il avait été fier, j’aurais préféré qu’il le dise clairement, un simple encouragement aurait suffi, plutôt que de me forcer à faire ce que je n’aimais pas.",
          DialogueId = 80030425,
          GUID = "C859079A",
          NextDialogue = 80030426,
          SpeakNpcId = 94202,
          Subtitle = "If he was proud of me, he should've told me. A few words of encouragement would've been enough, but instead, he just forced me to do things I didn't enjoy.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859079A"
        },
        [80030426] = {
          ContentFR = "Même s’il ne me pousse plus, j’ai quand même rejoint la Légion comme il le voulait.",
          DialogueId = 80030426,
          GUID = "C85907C4",
          NextDialogue = 80030427,
          SpeakNpcId = 94202,
          Subtitle = "Although he'd never push me to do anything again, I still joined the army, just like he wanted.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85907C4"
        },
        [80030427] = {
          ContentFR = "Je voulais comprendre cet endroit qui a fait de lui un homme taciturne, et prouver que je pouvais m’en sortir, même sans ses reproches.",
          DialogueId = 80030427,
          GUID = "C85907EE",
          NextDialogue = 80030428,
          SpeakNpcId = 94202,
          Subtitle = "I was curious about the Legion, the place that had turned my father into a detached man. I also wanted to prove that I could live a great life without his scolding.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85907EE"
        },
        [80030428] = {
          ContentFR = "Mais malheureusement, quand j’ai rejoint la Légion, j’ai compris qu’il avait raison, il voulait me protéger.",
          DialogueId = 80030428,
          GUID = "C8590818",
          NextDialogue = 80030429,
          SpeakNpcId = 94202,
          Subtitle = "Unfortunately for both of us, I found out that he was right all along. He was protecting me.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590818"
        },
        [80030429] = {
          ContentFR = "Nous ne sommes pas comme les autres dans la Légion. On s’est traînés hors des charniers, à genoux pour recevoir des médailles balancées comme une aumône.",
          DialogueId = 80030429,
          GUID = "C8590842",
          NextDialogue = 80030430,
          SpeakNpcId = 94202,
          Subtitle = "We're unlike most people in the Legion. We crawled out of piles of corpses on the battlefield, and kneel down to receive the medals they bestowed upon us like charity.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590842"
        },
        [80030430] = {
          ContentFR = "Un boulot digne, une vie confortable, notre survie même, tout dépend de ces petites médailles. Mon père a tout donné pour notre famille.",
          DialogueId = 80030430,
          GUID = "C859086C",
          NextDialogue = 80030431,
          SpeakNpcId = 94202,
          Subtitle = "A decent job, a great life, and a means of survival. Everything about us is determined by those small medals. For the sake of our family, my dad devoted himself to them.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859086C"
        },
        [80030431] = {
          ContentFR = "Il a obéi, supporté, caché ses émotions, s’est habitué à la douleur et aux pleurs, et s’est fait une carapace.",
          DialogueId = 80030431,
          GUID = "C8590896",
          NextDialogue = 80030432,
          SpeakNpcId = 94202,
          Subtitle = "He obeyed, endured, suppressed his feelings, pushed back the tears, and turned himself into a husk of a man.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590896"
        },
        [80030432] = {
          ContentFR = "Moi, je ne peux pas faire ça. Mais j’ai besoin d’argent pour vivre et maintenir la dignité de ma famille. Du coup, je reste là, suspendu entre deux mondes, un raté heureux.",
          DialogueId = 80030432,
          GUID = "C85908C0",
          NextOptions = {
            [1] = 800304321
          },
          SpeakNpcId = 94202,
          Subtitle = "I can't do that, but I need money to support myself and maintain my family's decent lifestyle. So, I'm a happy loser now, as you can see.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85908C0"
        },
        [80030433] = {
          ContentFR = "...",
          DialogueId = 80030433,
          GUID = "C85908EA",
          NextDialogue = 80030434,
          SpeakNpcId = 94202,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Landi/004/C85908EA"
        },
        [80030434] = {
          ContentFR = "Tu es vraiment perspicace. Pour être honnête, j’ai longtemps été perdu.",
          DialogueId = 80030434,
          GUID = "C8590914",
          NextDialogue = 80030435,
          SpeakNpcId = 94202,
          Subtitle = "You have a keen eye. But to be frank, I have no idea what I want to do. After a long bout of depression, I've finally realised that —",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590914"
        },
        [80030435] = {
          ContentFR = "Même si mon choix diffère de ce qu’il voulait, je ne regrette pas ma vie.",
          DialogueId = 80030435,
          GUID = "C859093E",
          NextOptions = {
            [1] = 800304351,
            [2] = 800304352
          },
          SpeakNpcId = 94202,
          Subtitle = "Even though I haven't lived up to my dad's expectations, I'm happy with the life I have.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C859093E"
        },
        [80030436] = {
          ContentFR = "J’espère bien. Si ça arrive, mes cauchemars pourront enfin s’arrêter.",
          DialogueId = 80030436,
          GUID = "C8590968",
          NextDialogue = 80030438,
          SpeakNpcId = 94202,
          Subtitle = "I hope so. If that happens, my nightmares may finally end.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590968"
        },
        [80030437] = {
          ContentFR = "Excellent, avec ça je devrais enfin dormir sans cauchemars.",
          DialogueId = 80030437,
          GUID = "C8590992",
          NextDialogue = 80030438,
          SpeakNpcId = 94202,
          Subtitle = "That tastes good. This will help me sleep without nightmares.",
          VoiceName = "voice/$Locale$/inv/Landi/004/C8590992"
        },
        [80030438] = {
          ContentFR = "Merci, {性别:mon|ma} pote de vacances, mais maintenant je dois dormir un peu, sinon je vais devoir demander un autre jour de congé demain.",
          DialogueId = 80030438,
          GUID = "C85909BC",
          NextDialogue = 80030439,
          SpeakNpcId = 94202,
          Subtitle = "Thanks, holiday buddy, but I need some sleep now, or else I'll have to take more leave tomorrow.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85909BC"
        },
        [80030439] = {
          ContentFR = "T’inquiète, la prochaine fois qu’on se voit, je serai le Randy que tu connais. Et si je fais encore un cauchemar, je compte sur toi pour me préparer un autre verre.",
          DialogueId = 80030439,
          GUID = "C85909E6",
          SpeakNpcId = 94202,
          Subtitle = "Don't worry, I'll be the regular Randy you know the next time we meet. And if I have another nightmare, please make me one more cup of this delicious drink.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/004/C85909E6"
        },
        [80030501] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentFR = "Un petit remontant, bien sucré s’il te plaît. Et tiens, j’ai ramené quelques douceurs de l’Empire. J’ai fait la queue pendant mon jour de repos... Goûte-moi ça.",
          DialogueId = 80030501,
          GUID = "C8591412",
          LookAt = {
            [1] = "94202:p(18000P1)"
          },
          NextOptions = {
            [1] = 800305011,
            [2] = 800305012
          },
          SpeakNpcId = 94202,
          Subtitle = "A hot drink with extra sugar, please. I brought some desserts from the Imperial Capital. I queued up to buy them during my break. Want to try some?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591412"
        },
        [80030502] = {
          ContentFR = "Exactement. Une boisson sucrée, pour adoucir... une petite requête.",
          DialogueId = 80030502,
          GUID = "C859143C",
          NextDialogue = 80030504,
          SpeakNpcId = 94202,
          Subtitle = "I sure am. I'm in the mood for a sweet drink as a prelude to my invitation.",
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C859143C"
        },
        [80030503] = {
          ContentFR = "Quoi ?! Pas du tout ! Bon... ok, j’ai bel et bien une petite faveur à te demander. Mais c’est pas un piège, promis.",
          DialogueId = 80030503,
          GUID = "C8591466",
          NextDialogue = 80030504,
          SpeakNpcId = 94202,
          Subtitle = "Ooh! I want to ask a small favour of you, but I wouldn't call it a \"plan.\"",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591466"
        },
        [80030504] = {
          ContentFR = "<I>Ahem...</> Je sais que ça sort de nulle part, mais... ça te dirait de m’accompagner au bal ?",
          DialogueId = 80030504,
          GUID = "C8591490",
          NextDialogue = 80030505,
          SpeakNpcId = 94202,
          Subtitle = "Ahem... Maybe this is a little sudden, but do you want to attend a dance with me?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591490"
        },
        [80030505] = {
          ContentFR = "Tu sais, ces soirées diplomatiques dans la cité intérieure, avec la noblesse et tout le cirque, des événements indispensables pour que la Légion conserve de bonnes relations avec les pouvoirs locaux.",
          DialogueId = 80030505,
          GUID = "C85914BA",
          NextDialogue = 80030506,
          SpeakNpcId = 94202,
          Subtitle = "Like I mentioned to you before, the Legion needs to maintain ties with local nobility. So, I need to attend annoying social balls in the inner city from time to time.",
          TalkActionId = {
            [1] = "94202:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85914BA"
        },
        [80030506] = {
          ContentFR = "Franchement, j’ai zéro envie d’y aller. Même en mission officielle, devoir sourire à la noblesse, c’est juste insupportable.",
          DialogueId = 80030506,
          GUID = "C85914E4",
          NextDialogue = 80030507,
          SpeakNpcId = 94202,
          Subtitle = "I really don't want to go. The trip is paid for, but dealing with nobility is such a headache.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85914E4"
        },
        [80030507] = {
          ContentFR = "Du coup, j’ai eu une idée de génie : Y aller au bras d’une partenaire splendide.",
          DialogueId = 80030507,
          GUID = "C859150E",
          NextDialogue = 80030508,
          SpeakNpcId = 94202,
          Subtitle = "So, I have a perfect solution. I can take a gorgeous lady with me as my partner.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C859150E"
        },
        [80030508] = {
          ContentFR = "Comme ça, personne n’osera m’interrompre pour me présenter leurs cousines célibataires qu’ils ont vues trois fois dans leur vie.",
          DialogueId = 80030508,
          GUID = "C8591538",
          NextOptions = {
            [1] = 800305081,
            [2] = 800305082
          },
          SpeakNpcId = 94202,
          Subtitle = "That way, no one will try to introduce me to a female relative I've never met before.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591538"
        },
        [80030509] = {
          ContentFR = "Eh bien... je me disais... peut-être... tu pourrais envisager un petit déguisement ?",
          DialogueId = 80030509,
          GUID = "C8591562",
          NextOptions = {
            [1] = 800305091,
            [2] = 800305092
          },
          SpeakNpcId = 94202,
          Subtitle = "Well... I was thinking... maybe... you could try to disguise yourself as a lady.",
          TalkActionId = {
            [1] = "94202:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591562"
        },
        [80030510] = {
          ContentFR = " Je ne peux pas. C’est moi l’invité, après tout.",
          DialogueId = 80030510,
          GUID = "C859158C",
          NextDialogue = 80030512,
          SpeakNpcId = 94202,
          Subtitle = "I can't. I'm the one who's been invited.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C859158C"
        },
        [80030511] = {
          ContentFR = "Je t’en prie, j’ai épuisé toutes mes options. T’es ma dernière chance.",
          DialogueId = 80030511,
          GUID = "C85915B6",
          NextDialogue = 80030512,
          SpeakNpcId = 94202,
          Subtitle = "Sorry, but you're my last hope. I'm really clutching at straws here!",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85915B6"
        },
        [80030512] = {
          ContentFR = "On a bu combien de fois ensemble, hein ? Pour moi, t’es déjà plus proche que mes propres sœurs ! C’est justement parce que t’es mon meilleur pote que je te le demande.",
          DialogueId = 80030512,
          GUID = "C85915E0",
          NextDialogue = 80030513,
          SpeakNpcId = 94202,
          Subtitle = "We've had so many drinks together, and you're my closest friend. I'm even closer to you than my siblings, so I'm begging you for help.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85915E0"
        },
        [80030513] = {
          ContentFR = "Allez, arrête de faire cette tête. Si tu m’aides, je te file la moitié de mon salaire pendant six mois ! Et si la commandante Sibylle essaie encore de t’arrêter, je me sacrifierai pour te couvrir !",
          DialogueId = 80030513,
          GUID = "C859160A",
          NextDialogue = 80030514,
          SpeakNpcId = 94202,
          Subtitle = "If you help me in my time of need, I'll give you half of my salary for the next six months. And, if Chief Sibylle tries to arrest you next time, I'll come forward and protect you!",
          VoiceName = "voice/$Locale$/inv/Landi/005/C859160A"
        },
        [80030514] = {
          ContentFR = "Et si ça ne te suffit pas, je me mettrai moi-même en robe après le bal, rien que pour toi. Ça te va ?",
          DialogueId = 80030514,
          GUID = "C8591634",
          NextOptions = {
            [1] = 800305141,
            [2] = 800305142
          },
          SpeakNpcId = 94202,
          Subtitle = "If that's not enough, I'll dress up like a lady and entertain you after the ball. What do you say?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591634"
        },
        [80030515] = {
          ContentFR = "Non, non, non ! Tu te méprends complètement, c’est pas du tout ce que tu crois !",
          DialogueId = 80030515,
          GUID = "C859165E",
          NextDialogue = 80030516,
          SpeakNpcId = 94202,
          Subtitle = "No, no, no! You've got the wrong idea! What makes you think that?",
          TalkActionId = {
            [1] = "94202:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C859165E"
        },
        [80030516] = {
          ContentFR = "Je veux dire, c’est normal, non ? Entre vrais potes, on fait tout ensemble : sortir, manger, aller aux toilettes et essayer des robes. C’est ça, l’amitié !",
          DialogueId = 80030516,
          GUID = "C8591688",
          NextOptions = {
            [1] = 800305161
          },
          SpeakNpcId = 94202,
          Subtitle = "I mean, it's normal, right? Best buds do everything together — hang out, share meals, hit the restroom, try on dresses...",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591688"
        },
        [80030517] = {
          ContentFR = "Allez, rigole pas... je suis vraiment en détresse là. Dis-moi juste si t’acceptes, sinon je vais devoir me creuser la tête pour un autre plan...",
          DialogueId = 80030517,
          GUID = "C85916B2",
          NextOptions = {
            [1] = 800305171,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          Subtitle = "Hey, don't laugh at me. I'm really in a bind here. Please just give me your answer. If you say \"no,\" I'll have to find another solution.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85916B2"
        },
        [80030518] = {
          ContentFR = "Réfléchis encore un peu, hein...",
          DialogueId = 80030518,
          GUID = "C85916DC",
          NextDialogue = 80030519,
          SpeakNpcId = 94202,
          Subtitle = "Just think about it...",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85916DC"
        },
        [80030519] = {
          ContentFR = "Attends... tu dis que tu acceptes ? Sérieux ? T’es un vrai frère, même si on est pas de la même famille !",
          DialogueId = 80030519,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C8591706",
          NextDialogue = 80030520,
          SpeakNpcId = 94202,
          Subtitle = "Huh? Really? That's fantastic! You're a lifesaver!",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591706"
        },
        [80030520] = {
          ContentFR = "Je te dois une fière chandelle. Je vais devoir me creuser la tête pour te la rendre.",
          DialogueId = 80030520,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591730",
          NextDialogue = 80030521,
          SpeakNpcId = 94202,
          Subtitle = "You've done me a huge favour. I'll repay you however I can.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591730"
        },
        [80030521] = {
          ContentFR = "Mais bon, on verra ça après le bal. Pour l’instant, faut que je file préparer ma tenue avant que tu reviennes sur ta décision. ",
          DialogueId = 80030521,
          GUID = "C859175A",
          NextDialogue = 80030522,
          SpeakNpcId = 94202,
          Subtitle = "But let's talk about this after the ball. I need to go home and prepare my outfit before you change your mind.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C859175A"
        },
        [80030522] = {
          ContentFR = "Allez, à plus, mon complice de pause, mon partenaire de galère, et la raison de toutes mes aventures jusqu’à maintenant.",
          DialogueId = 80030522,
          GUID = "C8591784",
          SpeakNpcId = 94202,
          Subtitle = "I'll see you later, my holiday buddy, break-time pal, and the target of my pursuits to this very day.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591784"
        },
        [80030523] = {
          ContentFR = "Je comprends. Mais n’oublie pas. Après le bal, je trouverai toutes sortes de façons créatives pour te rendre la pareille, comme quand je cherche des excuses pour poser des congés.",
          DialogueId = 80030523,
          GUID = "C85917AE",
          NextDialogue = 80030524,
          SpeakNpcId = 94202,
          Subtitle = "Please give it plenty of consideration. After the ball, I'll find many creative ways to repay you, just like how I come up with excuses to take time off.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85917AE"
        },
        [80030524] = {
          ContentFR = "Pour l’instant, je vais me calmer un peu et te laisser de l’espace pour y penser. Cela dit, j’espère vraiment que tu accepteras, et je suis sûr que tu le feras !",
          DialogueId = 80030524,
          GUID = "C85917D8",
          NextDialogue = 80030525,
          SpeakNpcId = 94202,
          Subtitle = "Take as much time as you need. I really need your help, and I'm certain that you'll come through for me.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85917D8"
        },
        [80030525] = {
          ContentFR = "Bon, je file alors. J’attends de tes nouvelles, mon complice de pause, mon partenaire de galère, et la raison de toutes mes aventures jusqu’à maintenant.",
          DialogueId = 80030525,
          GUID = "C8591802",
          SpeakNpcId = 94202,
          Subtitle = "I'll be awaiting your answer. See you later, my holiday buddy, break-time pal, and the target of my pursuits to this very day.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591802"
        },
        [80030526] = {
          ContentFR = "Exact. Tu es clairement la meilleure partenaire pour ce bal... Alors, tu veux bien me filer un coup de main et me sortir de ce pétrin ?",
          DialogueId = 80030526,
          GUID = "C8591856",
          NextOptions = {
            [1] = 800305261
          },
          SpeakNpcId = 94202,
          Subtitle = "Yes, you're my best dancing partner, after all. The question is, are you willing to do me this favour?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591856"
        },
        [80030527] = {
          ContentFR = "Hein ?",
          DialogueId = 80030527,
          GUID = "C8591880",
          NextDialogue = 80030528,
          SpeakNpcId = 94202,
          Subtitle = "What?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591880"
        },
        [80030528] = {
          ContentFR = "Quoi ?! Comment tu peux penser ça ? Si je voulais vraiment t’arrêter, je l’aurais déjà fait la première fois qu’on s’est vus !",
          DialogueId = 80030528,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C85918AA",
          NextDialogue = 80030529,
          SpeakNpcId = 94202,
          Subtitle = "Why on earth would you think that? If I really wanted to arrest you, I could've done that the first time we met.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85918AA"
        },
        [80030529] = {
          ContentFR = "Pas besoin de poser mes précieux jours de congé juste pour organiser une \"soirée piège\".",
          DialogueId = 80030529,
          GUID = "C85918D4",
          NextDialogue = 80030530,
          SpeakNpcId = 94202,
          Subtitle = "I don't see the point in using my precious leave to come here and organise something like a \"secret arrest ball\".",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85918D4"
        },
        [80030530] = {
          ContentFR = "Et puis, même si je voulais te piéger, t’inviter à danser, ce serait bizarre, non ? Et si tu disais non ?",
          DialogueId = 80030530,
          GUID = "C85918FE",
          NextDialogue = 80030531,
          SpeakNpcId = 94202,
          Subtitle = "And what if you turn me down? How would my plan work in that case?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85918FE"
        },
        [80030531] = {
          ContentFR = "Rassure-moi, c’était une blague ? Sinon, tu me prends vraiment pour un idiot sans scrupules, prêt à trahir mes amis pour avancer...",
          DialogueId = 80030531,
          GUID = "C8591928",
          NextOptions = {
            [1] = 800305311,
            [2] = 800305312
          },
          SpeakNpcId = 94202,
          Subtitle = "You must be kidding. Do you seriously think I'm a scheming fool like that?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591928"
        },
        [80030532] = {
          ContentFR = "Ouf... Parce que si tu pensais vraiment ça de moi, je crois que je prendrais un mois d’arrêt maladie juste pour m’en remettre.",
          DialogueId = 80030532,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591952",
          NextDialogue = 80030534,
          SpeakNpcId = 94202,
          Subtitle = "Alright then. If you really did misunderstand me and think I was a shameless jerk who'd betray his friends like that, I'd need a month's leave to recover from such heartbreak.",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591952"
        },
        [80030533] = {
          ContentFR = "Hé, au moins nie la partie où je trahis mes amis pour une promotion, ça ferait moins mal à mon petit cœur !",
          DialogueId = 80030533,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C859197C",
          NextDialogue = 80030534,
          SpeakNpcId = 94202,
          Subtitle = "Hey, at least deny that I betrayed my friends for personal gain, or else you'll hurt my feelings!",
          TalkActionId = {
            [1] = "94202:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C859197C"
        },
        [80030534] = {
          ContentFR = "Mais maintenant, une chose est sûre : tu n’as jamais vraiment eu peur du danger.",
          DialogueId = 80030534,
          GUID = "C85919A6",
          NextDialogue = 80030535,
          SpeakNpcId = 94202,
          Subtitle = "But now there's one thing I'm sure of — You're not afraid of risk at all.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C85919A6"
        },
        [80030535] = {
          ContentFR = "Tu faisais juste une blague, en imaginant le pire scénario, pour voir ma réaction.",
          DialogueId = 80030535,
          GUID = "C85919D0",
          NextOptions = {
            [1] = 800305351,
            [2] = 800305352
          },
          SpeakNpcId = 94202,
          Subtitle = "So, you were messing with me to see my reaction.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85919D0"
        },
        [80030536] = {
          ContentFR = "Je croyais que j’étais le seul à être aussi joueur et taquin, mais toi aussi, hein ? D’où tu sors ça ?",
          DialogueId = 80030536,
          GUID = "C85919FA",
          NextDialogue = 80030537,
          SpeakNpcId = 94202,
          Subtitle = "I didn't know you love mean tricks like me. Where did you pick that up?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C85919FA"
        },
        [80030537] = {
          ContentFR = "J’avoue, j’ai eu un moment de doute. Même si je savais que c’était impossible, au fond, j’ai flippé, et si c’était vrai ?",
          DialogueId = 80030537,
          GUID = "C8591A24",
          NextDialogue = 80030538,
          SpeakNpcId = 94202,
          Subtitle = "I panicked for a moment then. Although deep down I knew it was impossible, I was still worried. What if you really thought that way?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591A24"
        },
        [80030538] = {
          ContentFR = "Alors, pour compenser ta blague, tu dois accepter mon invitation.",
          DialogueId = 80030538,
          GUID = "C8591A4E",
          NextOptions = {
            [1] = 800305431,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          Subtitle = "So, to make up for your trick, you must help me.",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591A4E"
        },
        [80030539] = {
          ContentFR = "Quoi ?!",
          DialogueId = 80030539,
          FacialId = {
            [1] = "94202:Shock01"
          },
          GUID = "C8591A78",
          NextDialogue = 80030540,
          SpeakNpcId = 94202,
          Subtitle = "What?!",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591A78"
        },
        [80030540] = {
          ContentFR = "Bon, tu as raison ! J’ai toujours voulu t’arrêter, matin et soir, dès que mon cerveau était réveillé, j’y pensais ! Mais je procrastine tellement que je n’ai jamais passé à l’acte.",
          DialogueId = 80030540,
          FacialId = {
            [1] = "94202:None"
          },
          GUID = "C8591AA2",
          NextDialogue = 80030541,
          SpeakNpcId = 94202,
          Subtitle = "Okay, fine, you're right. I've been wanting to arrest you for ages. Every morning, I wake up and think about how to carry out my devious plan, but I procrastinate too much to actually do it.",
          TalkActionId = {
            [1] = "94202:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591AA2"
        },
        [80030541] = {
          ContentFR = "Cette fois, je voulais vraiment faire le boulot, mais tu m’as démasqué... Que faire ?",
          DialogueId = 80030541,
          GUID = "C8591ACC",
          NextDialogue = 80030542,
          SpeakNpcId = 94202,
          Subtitle = "This time, I was hoping to fulfil my duty but failed. What do I do?",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591ACC"
        },
        [80030542] = {
          ContentFR = "Je finirai par me faire virer de la Légion, à errer dans les rues glaciales de Givrelac, seul, affamé, sans abri...",
          DialogueId = 80030542,
          GUID = "C8591AF6",
          NextDialogue = 80030543,
          SpeakNpcId = 94202,
          Subtitle = "One day, I'll be fired by the Legion and end up homeless and destitute on the cold streets of Icelake.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591AF6"
        },
        [80030543] = {
          ContentFR = "Tu veux vraiment me voir finir en statue de glace sur le trottoir ?",
          DialogueId = 80030543,
          GUID = "C8591B20",
          NextOptions = {
            [1] = 800305431,
            [2] = 800305172
          },
          SpeakNpcId = 94202,
          Subtitle = "Do you really want to see me turn into an ice sculpture on the street?",
          TalkActionId = {
            [1] = "94202:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591B20"
        },
        [80030544] = {
          ContentFR = "Réfléchis encore un peu, hein...",
          DialogueId = 80030544,
          GUID = "C8591B4A",
          NextDialogue = 80030545,
          SpeakNpcId = 94202,
          Subtitle = "Maybe you can think twice before answering me...",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591B4A"
        },
        [80030545] = {
          ContentFR = "Attends... tu dis que tu acceptes ? Sérieux ? T’es une vraie sœur, même si on n’est pas de la même famille !",
          DialogueId = 80030545,
          GUID = "C8591B74",
          NextDialogue = 80030546,
          SpeakNpcId = 94202,
          Subtitle = "... Huh? Really? That's fantastic! You're my lifesaver!",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591B74"
        },
        [80030546] = {
          ContentFR = "Je te dois une fière chandelle. Je vais devoir me creuser la tête pour te la rendre.",
          DialogueId = 80030546,
          GUID = "C8591B9E",
          NextDialogue = 80030547,
          SpeakNpcId = 94202,
          Subtitle = "You've done me a huge favour. I'll repay you however I can.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591B9E"
        },
        [80030547] = {
          ContentFR = "Mais bon, on verra ça après le bal. Pour l’instant, faut que je file préparer ma tenue avant que tu ne reviennes sur ta décision.",
          DialogueId = 80030547,
          GUID = "C8591BC8",
          NextDialogue = 80030548,
          SpeakNpcId = 94202,
          Subtitle = "But let's talk about this after the ball. I need to go home and prepare my outfit before you change your mind.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591BC8"
        },
        [80030548] = {
          ContentFR = "Allez, à plus, ma complice de pause, ma partenaire de galère, et la raison de toutes mes aventures jusqu’à maintenant.",
          DialogueId = 80030548,
          GUID = "C8591BF2",
          SpeakNpcId = 94202,
          Subtitle = "I'll see you later, my holiday buddy, break-time pal, and the target of my pursuits to this very day.",
          VoiceName = "voice/$Locale$/inv/Landi/005/C8591BF2"
        },
        [80040101] = {
          Camera = "-52.422852,-88.373047,123.091431,0.000216,-4.998045,54.58065,40.000011,196.024292,false,Manual,4.967944",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Voilà, c’est prêt. Vas-y, dis-moi ce que tu en penses, Berry.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040101,
          Duration = 8,
          FacialId = {
