          GUID = "C85F3B3C",
          NextDialogue = 80040103,
          SpeakNpcId = 790007,
          Subtitle = "Hmm, okay...",
          TalkActionId = {
            [1] = "790007:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3B3C"
        },
        [80040103] = {
          Camera = "-199.146484,-426.681641,234.483765,0.000222,-15.191071,70.673798,35.000008,269.311096,false,DoNotOverride,3.045305",
          ContentFR = "Au fait, pourquoi t’as voulu absolument prendre la louche ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040103,
          FinalCamera = "-186.857422,-430.990479,234.483765,0.000221,-15.191064,70.673798,35.000008,269.311096,false,DoNotOverride,3.045305",
          GUID = "C85F3B66",
          NextDialogue = 80040104,
          SpeakNpcId = 790007,
          Subtitle = "So, why were you so eager to take the ladle from me earlier?",
          TalkActionId = {
            [1] = "790007:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3B66"
        },
        [80040104] = {
          Camera = "-24.671387,-68.66333,139.902344,0.000222,-5.191469,35.319683,35.000008,269.311096,false,DoNotOverride,3.045305",
          ContentFR = "Parce que t’étais sur le point de mélanger des grenades à la soupe de poisson !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040104,
          FacialId = {
            [1] = "790008:Smile02"
          },
          FinalCamera = "-24.671387,-68.66333,139.902344,0.000222,-4.591458,35.919678,35.000008,269.311096,false,DoNotOverride,3.045305",
          GUID = "C85F3B90",
          NextDialogue = 80040105,
          SpeakNpcId = 790008,
          Subtitle = "Because you were about to add pomegranates to the fish soup!",
          TalkActionId = {
            [1] = "790007:Explain02_End",
            [2] = "790008:Disagree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3B90"
        },
        [80040105] = {
          ContentFR = "Et alors ? Je me souviens que tu adorais les grenades, avant.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040105,
          FacialId = {
            [1] = "790007:Shock02"
          },
          GUID = "C85F3BBA",
          NextDialogue = 80040106,
          Scripts = "SEQ{PlayAnimation{ActorId{790007},AnimationId{\"Shock_Start\"},Duration{2}},PlayAnimation{ActorId{790007},AnimationId{\"Shock_End\"},Duration{1}}}",
          SpeakNpcId = 790007,
          Subtitle = "What's wrong with that? I remember you used to love pomegranates when you were little.",
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3BBA"
        },
        [80040106] = {
          Camera = "98.562256,-40.027588,134.129395,-0.000519,-2.40243,174.925446,40.0,252.474731,false,Manual,18.208658",
          ContentFR = "L’an dernier, quand on a croisé ce grand grenadier, tu en as cueilli un sac entier... puis tout est tombé dans la vallée. Tu avais dit : « Quel gâchis ».",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040106,
          FacialId = {
            [1] = "790007:None"
          },
          FinalCamera = "104.528809,-40.557373,134.380737,-0.000519,-2.40243,174.925446,40.0,252.474731,false,Manual,18.208658",
          GUID = "C85F3BE4",
          NextDialogue = 80040107,
          Scripts = [[
PARA{
SEQ{PlayAnimation{ActorId{790007},AnimationId{"Explain01_Start"},Duration{2}},PlayAnimation{ActorId{790007},AnimationId{"Explain01_End"},Duration{1}},PlayAnimation{ActorId{790007},AnimationId{"Disagree"},Duration{1}}},
SEQ{
CameraMoveTo{_delay{10},TargetPosition{"-29.085938,-97.268799,147.981201,0.00019,-9.592303,149.532562,45.0,100.552406,false,Manual,4.024786"},duration{0}},
CameraMoveTo{TargetPosition{"-29.085938,-97.268799,150.180298,0.00019,-9.592303,149.532562,45.0,100.552406,false,Manual,4.024786"},duration{8}}
}
}]],
          SpeakNpcId = 790007,
          Subtitle = "Remember last year when we walked past that big pomegranate tree? You picked a whole bag of them. Too bad they all rolled down the hill when you slipped. You said it was such a waste.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3BE4"
        },
        [80040107] = {
          ContentFR = "Alors cette fois, j’en ai pris exprès rien que pour toi... Tu n’aimes plus ça, maintenant ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040107,
          FacialId = {
            [1] = "790008:Smile01"
          },
          GUID = "C85F3C0E",
          NextDialogue = 80040108,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{8.01},TargetPosition{"-187.269043,-90.881348,151.269409,-0.000519,-4.804505,21.10494,55.0,247.23613,false,Manual,7.567205"},duration{0}},
CameraMoveTo{TargetPosition{"-178.94751,-87.67041,150.519897,-0.000519,-4.804505,21.10494,55.0,247.23613,false,Manual,7.567205"},duration{8}}
}]],
          SpeakNpcId = 790007,
          Subtitle = "So this time, I picked some just for you... Don't you like them anymore?",
          TalkActionId = {
            [1] = "790007:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3C0E"
        },
        [80040108] = {
          ContentFR = "Ce n’est pas ça. C’est juste que poisson et fruit... niveau goût, c’est un peu étrange, non ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040108,
          GUID = "C85F3C38",
          NextDialogue = 80040109,
          SpeakNpcId = 790008,
          Subtitle = "It's not about the pomegranates. It's just that pomegranates and fish might not taste good together, don't you think?",
          TalkActionId = {
            [1] = "790007:Explain02_End",
            [2] = "790008:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3C38"
        },
        [80040109] = {
          Camera = "21.563721,-75.783936,229.640259,-0.000637,-35.195148,81.889259,40.0,256.07196,false,DoNotOverride,3.614923",
          ContentFR = "Mais tu disais que les baies trempées dans du lait, c’était délicieux... Comme c’est dur de trouver du lait sur l’île, j’ai essayé avec de la soupe. Je me suis dit... pourquoi pas.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040109,
          FacialId = {
            [1] = "790007:Shock01"
          },
          FinalCamera = "10.167236,-74.255371,229.640259,-0.000639,-35.195141,79.688759,40.0,256.07196,false,DoNotOverride,3.614923",
          GUID = "C85F3C62",
          NextDialogue = 80040110,
          SpeakNpcId = 790007,
          Subtitle = "But you like berries dipped in milk... It's hard to buy milk here on this island, so I thought soup would work just as well.",
          TalkActionId = {
            [1] = "790007:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3C62"
        },
        [80040110] = {
          Camera = "-37.483398,2.658447,166.522949,-0.00064,-21.195223,-16.305603,35.0,310.796967,false,DoNotOverride,3.614923",
          ContentFR = "Ça n’a rien à voir. Le goût salé et prononcé de la soupe de poisson écrase la douceur acidulée des fruits. Et puis, un fruit perd toute sa magie quand il est cuit, il devient mou, sans éclat. Mieux vaut le croquer frais, à pleines dents.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040110,
          FacialId = {
            [1] = "790007:None"
          },
          FinalCamera = "-35.881348,8.803955,166.522949,-0.000641,-21.195223,-19.305702,35.0,310.796967,false,DoNotOverride,3.614923",
          GUID = "C85F3C8C",
          NextDialogue = 80040111,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-485.556885,386.265381,18.750732,-0.000641,6.804555,-44.504627,35.0,680.101196,false,Manual,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-473.364258,398.938477,18.750732,-0.000641,6.804555,-47.504635,35.0,680.101196,false,Manual,1.2\"},duration{15}}}",
          SpeakNpcId = 790008,
          Subtitle = "{性别:It's not really the same|It's really not the same}. Fish soup has a strong salty, fishy taste, so it doesn't go well with sweet fruits. Plus, fruits are best eaten fresh; they'd lose their crunch if boiled.",
          TalkActionId = {
            [1] = "790007:Think_End",
            [2] = "790008:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3C8C"
        },
        [80040111] = {
          ContentFR = "Et puis... au minimum, tu aurais pu enlever la peau des grenades !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040111,
          FacialId = {
            [1] = "790008:Doubt01"
          },
          GUID = "C85F3CB6",
          NextDialogue = 80040112,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-107.39624,20.544678,102.665894,-0.000641,6.403753,-15.313855,35.0,680.101196,false,DoNotOverride,1.2\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-107.39624,20.544678,102.665894,-0.000641,7.603742,-15.313935,35.0,680.101196,false,DoNotOverride,1.2\"},duration{5}}}",
          SpeakNpcId = 790008,
          Subtitle = "And even if you were to cook pomegranates, you should at least peel them first...",
          TalkActionId = {
            [1] = "790008:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3CB6"
        },
        [80040112] = {
          Camera = "146.959473,123.187256,110.276123,-0.000641,2.803786,-132.900482,30.0,296.883026,false,Manual,4.419911",
          ContentFR = "Vraiment ? Tout ça juste pour une soupe...",
          DialogueId = 80040112,
          FacialId = {
            [1] = "790008:None"
          },
          FinalCamera = "146.959473,123.187256,110.276123,-0.000641,1.803771,-138.500198,30.0,296.883026,false,Manual,4.419911",
          GUID = "C85F3CE0",
          LookAt = {
            [1] = "790007:n(790007)"
          },
          NextDialogue = 80040113,
          SpeakNpcId = 790007,
          Subtitle = "Uh... this is way more complicated than I thought.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3CE0"
        },
        [80040113] = {
          Camera = "-204.043701,-27.717529,129.719727,-0.000641,-3.196262,-3.505373,40.0,272.0336,false,Manual,4.253633",
          ContentFR = "« Le lien entre les ingrédients, c’est une vraie alchimie. Il faut les marier avec soin pour révéler leurs saveurs. » C’est ce que dit le livre <I>L’Art de la cuisine</>.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040113,
          FacialId = {
            [1] = "790008:Confident02"
          },
          FinalCamera = "-203.907471,-22.408691,129.719727,-0.000641,-3.196262,-4.905429,40.0,272.0336,false,Manual,4.253633",
          GUID = "C85F3D0A",
          NextDialogue = 80040114,
          Scripts = "SEQ{CameraMoveTo{_delay{5},TargetPosition{\"-446.700195,12.999023,96.138916,-0.000764,-28.59417,61.790634,40.0,83.322594,false,Manual,4.253633\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-446.700195,12.999023,96.138916,-0.000764,-26.594084,57.189995,40.0,83.322594,false,Manual,4.253633\"},duration{5}}}",
          SpeakNpcId = 790008,
          Subtitle = "It is. \"The interplay of ingredients is a culinary art. Only the right combinations bring out the best in each\" — That's what they say in \"The Art of Cooking\".",
          TalkActionId = {
            [1] = "790008:Agree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3D0A"
        },
        [80040114] = {
          Camera = "129.349609,136.292236,117.841675,-0.000763,-6.194333,-148.003448,40.0,307.750519,false,Manual,4.253633",
          ContentFR = "Alors le goût bizarre de la dernière fois, c’est à cause des fruits rouges que j’avais ajoutés ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040114,
          FacialId = {
            [1] = "790008:Smile02"
          },
          FinalCamera = "129.349609,136.292236,117.841675,-0.000763,-0.593967,-144.001602,40.0,307.750519,false,Manual,4.253633",
          GUID = "C85F3D34",
          NextDialogue = 80040115,
          SpeakNpcId = 790007,
          Subtitle = "So, the funny sour taste in that stew last time was because I added berries?",
          TalkActionId = {
            [1] = "790007:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3D34"
        },
        [80040115] = {
          Camera = "-106.879639,23.383789,104.29187,-0.000763,8.005849,-17.003693,40.0,161.222946,false,Manual,4.253633",
          ContentFR = "... Probablement, oui.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040115,
          FinalCamera = "-108.938721,15.510498,104.29187,-0.000763,8.005849,-14.003182,40.0,168.337234,false,Manual,4.253633",
          GUID = "C85F3D5E",
          NextDialogue = 80040116,
          SpeakNpcId = 790008,
          Subtitle = "...I think so.",
          TalkActionId = {
            [1] = "790007:Explain01_End",
            [2] = "790008:Agree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3D5E"
        }
      }
    end
  },
  {
    MinKey = 80040116,
    MaxKey = 80050304,
    Loader = function()
      return {
        [80040116] = {
          Camera = "102.477051,17.33667,128.960815,-0.000763,-1.39398,-157.204117,40.0,236.074478,false,Manual,5.549016",
          ContentFR = "Et l’autre fois, les crevettes... C’est le miel à la place du sel qui a tout gâché ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040116,
          FinalCamera = "100.242676,22.411133,128.960815,-0.000763,-1.39398,-155.404724,40.0,236.074478,false,Manual,5.549016",
          GUID = "C85F3D88",
          NextDialogue = 80040117,
          SpeakNpcId = 790007,
          Subtitle = "And the time you said the shrimp was too rich, was it because I used honey instead of salt? I thought honey was better since it's more expensive...",
          TalkActionId = {
            [1] = "790007:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3D88"
        },
        [80040117] = {
          Camera = "-613.929688,596.478516,1.145264,-0.000762,7.205514,-48.996006,40.0,888.444336,false,Manual,1.2",
          ContentFR = "… Exactement.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040117,
          FacialId = {
            [1] = "790008:None"
          },
          GUID = "C85F3DB2",
          NextDialogue = 80040118,
          SpeakNpcId = 790008,
          Subtitle = "...That's right.",
          TalkActionId = {
            [1] = "790007:Explain02_End",
            [2] = "790008:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3DB2"
        },
        [80040118] = {
          Camera = "-613.929688,596.478516,1.145264,-0.000762,7.205514,-48.996006,40.0,888.444336,false,Manual,1.2",
          ContentFR = "Ah... Tout ça, c’est de ma faute, alors...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040118,
          FacialId = {
            [1] = "790007:Sad01"
          },
          GUID = "C85F3DDC",
          NextDialogue = 80040119,
          SpeakNpcId = 790007,
          Subtitle = "Ah... So I messed up all those times...",
          TalkActionId = {
            [1] = "790007:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3DDC"
        },
        [80040119] = {
          Camera = "149.739502,109.71582,98.639771,-0.000763,2.205229,-149.394455,40.0,306.072357,false,Manual,1.2",
          ContentFR = "On m’a toujours dit que le miel est sucré, et que le sucré est bon, que la chicorée est amère, et que l’amer est mauvais. Mais au fond, ce que ces sensations signifient, je l’ignore.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040119,
          FacialId = {
            [1] = "790007:None"
          },
          FinalCamera = "154.841553,101.091064,98.639771,-0.000763,2.205229,-150.194366,40.0,306.072357,false,Manual,1.2",
          GUID = "C85F3E06",
          NextDialogue = 80040120,
          Scripts = "SEQ{PlayAnimation{ActorId{790007},AnimationId{\"Sigh_End\"},Duration{1}},PlayAnimation{ActorId{790007},AnimationId{\"Think_Start\"},Duration{2}}}",
          SpeakNpcId = 790007,
          Subtitle = "I've heard that honey is sweet, and sweetness is good; while bitterness, like in chicory, is bad. But I can't really tell what sweet or bitter tastes like.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3E06"
        },
        [80040120] = {
          Camera = "-13.283691,10.45752,179.854492,-0.000762,-22.994616,-151.191467,40.0,306.072357,false,DoNotOverride,1.2",
          ContentFR = "Quand j’étais petite, on m’a enseigné que la nourriture n’est rien d’autre qu’un moyen de remplir l’estomac. Les plats savoureux ne font que plonger les gens dans un plaisir futile, inutile, et je n’avais pas besoin de ce genre de sensation.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040120,
          FinalCamera = "-15.179199,13.904297,179.854492,-0.000763,-22.994589,-148.191116,40.0,306.072357,false,DoNotOverride,1.2",
          GUID = "C85F3E30",
          NextDialogue = 80040121,
          SpeakNpcId = 790007,
          Subtitle = "I was taught very young that food is just a means of filling the stomach; tasty food is a distraction from what's important and might lead to indulgence, so I wouldn't need a sense of taste.",
          TalkActionId = {
            [1] = "790007:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3E30"
        },
        [80040121] = {
          Camera = "196.114258,78.616211,212.851562,7.204445,-23.193695,-151.182739,40.0,306.072357,false,DoNotOverride,1.2",
          ContentFR = "On m’a fait boire une potion. Depuis, je ne ressens plus rien quand je mange.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040121,
          FinalCamera = "196.114258,78.616211,212.851562,7.204649,-19.193562,-151.58284,40.0,306.072357,false,DoNotOverride,1.2",
          GUID = "C85F3E5A",
          NextDialogue = 80040122,
          SpeakNpcId = 790007,
          Subtitle = "They made me drink a potion; and ever since then, I haven't been able to taste anything.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3E5A"
        },
        [80040122] = {
