        [80040123] = {
          Camera = "15.265137,-28.532227,112.855957,0.000011,7.606453,-170.384079,40.0,142.232559,false,Manual,5.845709",
          ContentFR = "Désolée, je t’ai fait manger n’importe quoi...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040123,
          FacialId = {
            [1] = "790008:None"
          },
          FinalCamera = "26.493164,-26.630127,111.335571,0.000011,7.606453,-170.384079,40.0,152.783508,false,Manual,5.845709",
          GUID = "C85F3EAE",
          NextDialogue = 80040124,
          SpeakNpcId = 790007,
          Subtitle = "Sorry, I've made you eat so much awful food...",
          TalkActionId = {
