          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/001/C85F3EAE"
        },
        [80040124] = {
          ContentFR = "...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040124,
          GUID = "C85F3ED8",
          NextDialogue = 80040125,
          SpeakNpcId = 790008,
          Subtitle = "...",
          TalkActionId = {
