        },
        [80040302] = {
          Camera = "61.605896,-83.226074,114.584412,0.000097,-3.400635,163.425278,30.0,100000.0,false,DoNotOverride,1.2",
          ContentFR = "Ouf... tu vas bien.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040302,
          FinalCamera = "63.103333,-78.19458,114.584412,0.000097,-2.600492,166.623718,30.0,100000.0,false,DoNotOverride,1.2",
          GUID = "C85F5C0C",
          NextDialogue = 80040303,
          SpeakNpcId = 790007,
          Subtitle = "Phew... you're okay.",
          TalkActionId = {
            [1] = "790007:Explain01_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5C0C"
        },
        [80040303] = {
          Camera = "5.873901,-28.824463,117.54126,0.000119,-3.800781,-52.607815,40.0,344.90097,false,DoNotOverride,3.390253",
          ContentFR = "Berry ! Tu es couverte de sang... C’est les monstres ? Ils t’ont blessée ?!",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040303,
          FacialId = {
            [1] = "790008:Unacceptable01"
          },
          FinalCamera = "7.942322,-27.24292,117.54126,0.000119,-3.800781,-52.607845,40.0,344.90097,false,DoNotOverride,3.390253",
          GUID = "C85F5C36",
          NextDialogue = 80040304,
          Scripts = [[
PARA{
PlayAnimation{_delay{3},ActorId{790008},AnimationId{"Explain02_Start"},Duration{1}},
SEQ{
CameraMoveTo{_delay{4.01},TargetPosition{"-140.954956,196.943115,194.864258,-1.999998,-17.801022,-59.404312,30.0,344.90097,false,DoNotOverride,3.390253"},duration{0}},
CameraMoveTo{TargetPosition{"-147.953125,208.777832,193.795288,-1.999998,-17.801022,-59.404312,30.0,344.90097,false,DoNotOverride,3.390253"},duration{12}}
}
}]],
          SpeakNpcId = 790008,
          Subtitle = "Berry! You're covered in blood... What happened?! Did those monsters hurt you?!",
          TalkActionId = {
            [1] = "790007:Explain01_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5C36"
        },
        [80040304] = {
          ContentFR = "C’est pas le mien, c’est celui des Souillés. Ils ont attaqué le village.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040304,
          FacialId = {
            [1] = "790008:None"
          },
          GUID = "C85F5C60",
          NextDialogue = 80040305,
          SpeakNpcId = 790007,
          Subtitle = "It's Filthoid blood, not mine. They've attacked the village.",
          TalkActionId = {
            [1] = "790008:Explain02_End",
            [2] = "790007:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5C60"
        },
        [80040305] = {
          Camera = "146.374084,-92.182617,100.776611,0.000141,2.595035,174.804932,40.000011,144.593307,false,Manual,14.002915",
          ContentFR = "Je m’en doutais. J’étais {性别:caché|cachée} ici, j’ai entendu ces monstres dévaler la pente comme des fous.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040305,
          FacialId = {
            [1] = "790007:Think01"
          },
          FinalCamera = "145.919434,-95.889893,100.776611,0.000141,2.595035,173.005188,40.000011,144.593307,false,Manual,14.002915",
          GUID = "C85F5C8A",
          NextDialogue = 80040306,
          SpeakNpcId = 790008,
          Subtitle = "I figured as much. I was hiding here and heard those beasts charging like mad down the mountain.",
          TalkActionId = {
            [1] = "790008:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5C8A"
        },
        [80040306] = {
          Camera = "-310.138062,758.431641,72.251099,0.000105,7.197291,-65.395607,40.0,344.90097,false,DoNotOverride,3.390253",
          ContentFR = "C’est bizarre... Les Souillés restent d’habitude retranchés dans les montagnes. On les voit à peine. Qu’est-ce qui a bien pu les faire sortir et attaquer comme ça, d’un coup ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040306,
          FacialId = {
            [1] = "790008:None"
          },
          FinalCamera = "-310.138062,758.431641,72.251099,0.000105,0.997201,-69.995949,40.0,344.90097,false,DoNotOverride,3.390253",
          GUID = "C85F5CB4",
          NextDialogue = 80040307,
          SpeakNpcId = 790008,
          Subtitle = "It's weird... Those Filthoids usually keep to the deep woods. We barely see them. What drove them to suddenly come out and attack people?",
          TalkActionId = {
            [1] = "790008:Talk03_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5CB4"
        },
        [80040307] = {
          ContentFR = "Tout ça n’avait aucun sens pour moi. J’ai voulu venir te chercher tout de suite, puis je me suis dit qu’avec tes compétences au combat, tu serais peut-être plus à même de t’en sortir seule.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040307,
          GUID = "C85F5CDE",
          NextDialogue = 80040308,
          Scripts = "SEQ{CameraMoveTo{TargetPosition{\"-10.239319,53.23584,112.147522,0.000116,-2.402888,-63.800766,40.0,344.90097,false,DoNotOverride,3.390253\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-3.182373,56.603516,112.147522,0.000117,-2.402888,-67.002014,40.0,344.90097,false,DoNotOverride,3.390253\"},duration{15}}}",
          SpeakNpcId = 790008,
          Subtitle = "It didn't make sense to me. I wanted to come find you right away, but then I thought with your combat skills, you might handle things better on your own.",
          TalkActionId = {
            [1] = "790008:Talk03_End",
            [2] = "790007:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5CDE"
        },
        [80040308] = {
          Camera = "228.27594,-79.832764,112.051331,0.000002,-2.599536,-178.415939,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui... Tu as bien fait d’attendre ici.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040308,
          FinalCamera = "228.469727,-89.364258,112.051331,0.000002,-2.599536,179.184113,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C85F5D08",
          NextDialogue = 80040309,
          SpeakNpcId = 790007,
          Subtitle = "Mm, you did the right thing staying put and waiting for me.",
          TalkActionId = {
            [1] = "790007:AgreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5D08"
        },
        [80040309] = {
          ContentFR = "Le village grouille de Souillés. Heureusement, cette zone est encore sûre. J’ai pris assez de nourriture pour qu’on tienne quelques jours.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040309,
          FacialId = {
            [1] = "790007:None"
          },
          GUID = "C85F5D32",
          NextDialogue = 80040310,
          Scripts = "SEQ{PlayAnimation{ActorId{790007},AnimationId{\"Disagree\"},Duration{1}},PlayAnimation{ActorId{790007},AnimationId{\"Talk02_Start\"},Duration{2}}},\n",
          SpeakNpcId = 790007,
          Subtitle = "The village is crawling with Filthoids. Thankfully, it's still safe around here. Let's hole up for now. I've brought enough food to last a few days.",
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5D32"
        },
        [80040310] = {
          Camera = "-35.126404,-5.090088,104.664551,0.000137,1.795281,-49.795879,40.000011,144.593307,false,Manual,14.002915",
          ContentFR = "Et les villageois, ils ont pu s’enfuir ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040310,
          FacialId = {
            [1] = "790008:Unhappy01"
          },
          FinalCamera = "-31.541321,-2.060547,104.664551,0.000137,1.995269,-52.196728,40.000011,144.593307,false,Manual,14.002915",
          GUID = "C85F5D5C",
          NextDialogue = 80040311,
          SpeakNpcId = 790008,
          Subtitle = "What about the villagers?",
          TalkActionId = {
            [1] = "790007:Talk02_End",
            [2] = "790008:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5D5C"
        },
        [80040311] = {
          Camera = "848.746765,1916.216797,294.125,0.000126,-17.203968,55.999088,40.0,1090.520996,false,DoNotOverride,3.390253",
          ContentFR = "Ils se dirigeaient vers les quais quand je suis partie, sans doute pour fuir par bateau. Pas le temps de s’inquiéter pour eux maintenant, on doit vite trouver un abri.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040311,
          FacialId = {
            [1] = "790008:None"
          },
          FinalCamera = "848.746765,1916.216797,294.125,0.000126,-13.803914,59.39856,40.0,1090.520996,false,DoNotOverride,3.390253",
          GUID = "C85F5D86",
          NextDialogue = 80040312,
          SpeakNpcId = 790007,
          Subtitle = "They were heading to the docks when I left, probably trying to escape by boat. No time to worry about them now, we need to find shelter quickly.",
          TalkActionId = {
            [1] = "790007:Explain02_Start",
            [2] = "790008:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5D86"
        },
        [80040312] = {
          Camera = "-795.770142,2170.109863,379.106812,0.000087,-3.000078,-69.003471,40.0,9539.805664,false,Manual,2.935241",
          ContentFR = "Allons à la grotte où je me suis {性别:réfugié|réfugiée}.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040312,
          FacialId = {
            [1] = "790008:Confident01"
          },
          FinalCamera = "-795.770142,2170.109863,379.106812,0.000089,-4.400049,-71.20343,40.0,9539.805664,false,Manual,2.935241",
          GUID = "C85F5DB0",
          SpeakNpcId = 790008,
          Subtitle = "Let's go back to the cave I was hiding in.",
          TalkActionId = {
            [1] = "790008:Agree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5DB0"
        },
        [80040314] = {
          Camera = "494.918945,-114.393555,39.148193,-0.007568,6.005095,168.165497,35.000011,603.602356,false,Manual,1.2",
          ContentFR = "Tu as peur, {nickname} ?",
          DialogueId = 80040314,
          FacialId = {
            [1] = "790007:Satisfy01"
          },
          FinalCamera = "488.651367,-144.644531,39.151978,-0.007568,4.605104,163.564682,35.000011,603.602356,false,Manual,1.2",
          GUID = "C85F5E04",
          NextDialogue = 80040315,
          SpeakNpcId = 790007,
          Subtitle = ", are you scared?",
          TalkActionId = {
            [1] = "790007:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "790008:n(790007)"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5E04"
        },
        [80040315] = {
          ContentFR = "Avec toi, je n’ai pas peur. Au contraire, je suis... un peu {性别:excité|excitée}. Ça pourrait être notre <H>chance</>",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040315,
          FacialId = {
            [1] = "790008:Smile02",
            [2] = "790007:None"
          },
          GUID = "C85F5E2E",
          NextDialogue = 80040316,
          SpeakNpcId = 790008,
          Subtitle = "I'm not scared when you're with me. If anything, I'm a bit... excited. This could be our chance.",
          TalkActionId = {
            [1] = "790007:Explain01_End",
            [2] = "790008:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5E2E"
        },
        [80040316] = {
          Camera = "-129.611816,-150.831055,133.16095,0.000035,-0.999755,57.580574,35.000011,249.625748,false,Manual,3.333226",
          ContentFR = "J’y pense souvent… Peut-être qu’un jour, on pourra quitter l'Île du Purgatoire. Qu’est-ce que t’en penses ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040316,
          FacialId = {
            [1] = "790008:Happy01"
          },
          FinalCamera = "-124.529297,-154.021484,133.16095,0.000035,-0.999755,58.780304,35.000011,249.625748,false,Manual,3.333226",
          GUID = "C85F5E58",
          NextDialogue = 80040317,
          SpeakNpcId = 790008,
          Subtitle = "I've been thinking... maybe we can leave Purgatorio Island someday. What do you think?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5E58"
        },
        [80040317] = {
          Camera = "41.899414,-44.078125,124.430054,0.000096,3.199786,-166.207977,35.000011,249.625748,false,DoNotOverride,3.333226",
          ContentFR = "Partir ? Pourquoi ? Tu n’es pas {性别:heureux|heureuse} ici ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040317,
          FacialId = {
            [1] = "790007:Shock01"
          },
          FinalCamera = "43.626465,-50.854492,124.430054,0.000096,3.199786,-169.207458,35.000011,249.625748,false,DoNotOverride,3.333226",
          GUID = "C85F5E82",
          NextDialogue = 80040318,
          SpeakNpcId = 790007,
          Subtitle = "Leave? Why, aren't you happy here?",
          TalkActionId = {
            [1] = "790008:Explain02_End",
            [2] = "790007:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5E82"
        },
        [80040318] = {
          Camera = "-137.877441,-191.841797,125.066162,0.000112,-0.799549,59.789917,35.000011,298.327271,false,Manual,3.333226",
          ContentFR = "Ce n’est pas ça. C’est juste... cette île est tellement petite qu’on peut en faire le tour en moins d’une journée.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040318,
          FacialId = {
            [1] = "790007:None"
          },
          FinalCamera = "-127.499512,-197.882812,125.066162,0.000112,-0.799549,63.990067,35.000011,298.327271,false,Manual,3.333226",
          GUID = "C85F5EAC",
          NextDialogue = 80040319,
          SpeakNpcId = 790008,
          Subtitle = "It's not that. It's just... this island is so small — you can circle it in less than a day.",
          TalkActionId = {
            [1] = "790007:Talk02_End",
            [2] = "790008:Disagree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5EAC"
        },
        [80040319] = {
          Camera = "94.589355,-561.801758,16.744385,0.000086,7.600457,102.791916,35.000015,612.552734,false,Manual,3.333226",
          ContentFR = "Ici, les gens croient que cette minuscule île est le monde entier. À leurs yeux, la mer et les cieux tournent autour de ce rocher, encore et encore.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040319,
          FacialId = {
            [1] = "790008:Smile01"
          },
          GUID = "C85F5ED6",
          NextDialogue = 80040320,
          Scripts = "SEQ{PlayAnimation{ActorId{790008},AnimationId{\"Explain01_Start\"},Duration{2}},PlayAnimation{ActorId{790008},AnimationId{\"Explain01_End\"},Duration{1}}}",
          SpeakNpcId = 790008,
          Subtitle = "The people here think this tiny island is the whole world. They believe the ocean and the cosmos just revolve around this rock, day after day.",
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5ED6"
        },
        [80040320] = {
          Camera = "-17.905273,-67.693359,139.75769,-0.00003,-1.597929,60.590927,35.000011,298.327271,false,DoNotOverride,3.333226",
          ContentFR = "Mais moi, je sais que c’est faux ! Tu te souviens de ce livre, <I>Feuilles et Lune ?</>",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040320,
          FinalCamera = "-13.446777,-70.423828,139.75769,-0.000031,-1.597929,63.591003,35.000011,298.327271,false,DoNotOverride,3.333226",
          GUID = "C85F5F00",
          NextDialogue = 80040321,
          SpeakNpcId = 790008,
          Subtitle = "But I know that's not true! Remember that book, \"Betwixt Leaves And Branches\"?",
          TalkActionId = {
            [1] = "790008:Disagree"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5F00"
        },
        [80040321] = {
          Camera = "125.270584,60.271973,128.062073,0.000109,-1.20046,-154.825882,40.0,263.170776,false,Manual,2.791607",
          ContentFR = "Oui, les pêcheurs l’avaient rapporté d’Hyperborea. Les enfants du village s’étaient partagé les friandises, et le livre avait été jeté dans la cale comme une vieille ordure. Toi, tu l’as ramassé... comme un trésor.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040321,
          FinalCamera = "127.792831,55.563568,128.062073,0.000109,-1.20046,-156.425735,40.0,263.170776,false,Manual,2.791607",
          GUID = "C85F5F2A",
          NextDialogue = 80040322,
          Scripts = "SEQ{PlayAnimation{ActorId{790007},AnimationId{\"Agree\"},Duration{2}},PlayAnimation{ActorId{790007},AnimationId{\"Think_Start\"},Duration{1}}}",
          SpeakNpcId = 790007,
          Subtitle = "Yeah, it was brought back from Hyperborea by the fishermen. The kids took all the snacks, and that book was tossed aside in the cabin like rubbish. You picked it up and brought it back like it was treasure.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5F2A"
        },
        [80040322] = {
          Camera = "-6.626953,-30.28125,169.040344,0.000142,-19.999695,57.369331,40.000011,97.307968,false,DoNotOverride,2.791607",
          ContentFR = "Exact. Ce livre m’a ouvert les yeux. L’Île du Purgatoire n’est pas le centre du monde, c’est juste un point minuscule sur la carte, plus petit qu’une fourmi. De l’autre côté de la mer, bien au-delà de l’Arbre Céleste, il y a un continent immense...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040322,
          FinalCamera = "-1.369629,-33.611328,169.040344,0.000141,-19.999695,60.569077,40.000011,97.307968,false,DoNotOverride,2.791607",
          GUID = "C85F5F54",
          NextDialogue = 80040323,
          SpeakNpcId = 790008,
          Subtitle = "Right. That book was a real eye-opener. It showed me that Purgatorio Island isn't the centre of the world — it's merely a speck on the map, tinier than an ant. Across the sea, far beyond the Heaventree, lies a vast continent...",
          TalkActionId = {
            [1] = "790007:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5F54"
        },
        [80040323] = {
          Camera = "-1.369629,-33.611328,169.040344,0.000141,-19.999695,60.569077,40.000011,97.307968,false,DoNotOverride,2.791607",
          ContentFR = "On l’appelle \"Atlasia\".",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040323,
          FacialId = {
            [1] = "790008:Smile02"
          },
          GUID = "C85F5F7E",
          NextDialogue = 80040324,
          SpeakNpcId = 790008,
          Subtitle = "And its name is \"Atlasia.\"",
          TalkActionId = {
            [1] = "790008:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5F7E"
        },
        [80040324] = {
          Camera = "70.407005,-505.911072,84.270142,0.00011,2.600219,101.967049,40.0,97.307968,false,DoNotOverride,2.791607",
          ContentFR = "Au nord, il y a l’Empire Hyperboréen, la patrie des ancêtres du village. C’est un pays immense, qui s’étend des côtes du sud jusqu’aux plaines enneigées du nord, relié par de très longs trains.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040324,
          FinalCamera = "88.478951,-502.081146,84.270142,0.000111,2.600219,103.966965,40.0,97.307968,false,DoNotOverride,2.791607",
          GUID = "C85F5FA8",
          NextDialogue = 80040325,
          Scripts = "SEQ{PlayAnimation{ActorId{790008},AnimationId{\"Explain01_End\"},Duration{1}},PlayAnimation{ActorId{790008},AnimationId{\"Talk02_Start\"},Duration{1}}}",
          SpeakNpcId = 790008,
          Subtitle = "North of us is the Hyperborean Empire, where the ancestors of the villagers come from. It's a vast land that stretches from the southern coasts to the northern snowfields, all connected by long trains.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5FA8"
        },
        [80040325] = {
          Camera = "-129.753418,-153.637695,148.01416,0.000119,-5.599703,54.163155,40.000011,251.651398,false,Manual,2.791607",
          ContentFR = "Encore plus au nord, au-delà d’Hyperborea, s’étendent des montagnes sans fin et une mer de glace flottante. Là-bas, il y a d’innombrables petits villages, chacun avec ses coutumes étranges et fascinantes.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040325,
          FacialId = {
            [1] = "790008:Happy01"
          },
          FinalCamera = "-124.568848,-157.458008,148.01416,0.000119,-5.599703,56.762924,40.000011,251.651398,false,Manual,2.791607",
          GUID = "C85F5FD2",
          NextDialogue = 80040326,
          Scripts = "SEQ{PlayAnimation{ActorId{790008},AnimationId{\"Talk02_End\"},Duration{1}},PlayAnimation{ActorId{790008},AnimationId{\"Talk01_Start\"},Duration{1}}}",
          SpeakNpcId = 790008,
          Subtitle = "Even further north, beyond Hyperborea, lie endless mountains and seas of floating ice, home to countless small settlements, each with its own fascinating customs.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5FD2"
        },
        [80040326] = {
          Camera = "-393.785614,-480.069183,305.096741,0.000103,-19.798573,51.166595,40.0,703.010681,false,Manual,1.2",
          ContentFR = "Au sud, il y a l’Église Élyséenne, la plus ancienne civilisation humaine ! C’est un royaume divin où les dieux vivent dans une tour immense, plus haute que le ciel. Et à l’est...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040326,
          FacialId = {
            [1] = "790008:Confident02"
          },
          FinalCamera = "-373.000397,-454.251862,293.164307,0.000103,-19.798573,51.166759,40.0,703.010681,false,Manual,1.2",
          GUID = "C85F5FFC",
          NextDialogue = 80040327,
          Scripts = "SEQ{PlayAnimation{ActorId{790008},AnimationId{\"Talk01_End\"},Duration{1}},PlayAnimation{ActorId{790008},AnimationId{\"Angry01_Start\"},Duration{1}}}",
          SpeakNpcId = 790008,
          Subtitle = "To the south is the Elysian Church, the oldest civilization. It's a divine realm where gods live in a tower high above the sky. And to the east—",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F5FFC"
        },
        [80040327] = {
          Camera = "-373.000397,-454.251862,293.164307,0.000103,-19.798573,51.166759,40.0,703.010681,false,Manual,1.2",
          ContentFR = "Berry ? Quelque chose ne va pas ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040327,
          FacialId = {
            [1] = "790008:None"
          },
          GUID = "C85F6026",
          NextDialogue = 80040328,
          SpeakNpcId = 790008,
          Subtitle = "What's wrong, Berry? Are you alright?",
          TalkActionId = {
            [1] = "790008:Angry01_End",
            [2] = "790007:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F6026"
        },
        [80040328] = {
          Camera = "113.435013,55.193058,124.11676,0.000158,1.00147,-153.830154,40.0,258.197296,false,Manual,4.11031",
          ContentFR = "Ce n’est rien, juste un peu fatiguée. On arrête de parler de tout ça pour l’instant, d’accord ?",
          DialogueId = 80040328,
          FacialId = {
            [1] = "790007:Sad01"
          },
          FinalCamera = "115.40287,51.259754,124.11676,0.000158,1.00147,-155.030075,40.0,258.197296,false,Manual,4.11031",
          GUID = "C85F6050",
          LookAt = {
            [1] = "790008:n(790008)"
          },
          NextDialogue = 80040329,
          SpeakNpcId = 790007,
          Subtitle = "I'm fine, just a bit tired. Let's not talk about this for now, okay?",
          TalkActionId = {
            [1] = "790007:Sigh_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F6050"
        },
        [80040329] = {
          Camera = "-17.905273,-67.693359,139.75769,-0.00003,-1.597929,60.590927,35.000011,298.327271,false,DoNotOverride,3.333226",
          ContentFR = "Oui, tu as raison, tu es épuisée, et moi je n’arrête pas de parler. Allons plutôt dans la grotte, on se reposera là-bas.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040329,
          FacialId = {
            [1] = "790008:Satisfy01"
          },
          FinalCamera = "-13.446777,-70.423828,139.75769,-0.000031,-1.597929,63.591003,35.000011,298.327271,false,DoNotOverride,3.333226",
          GUID = "C85F607A",
          NextDialogue = 80040331,
          Scripts = "SEQ{PlayAnimation{ActorId{790008},AnimationId{\"Disagree\"},Duration{1}},TurnTo{TurnToDescription{\"790008:p(180)\"}},PARA{CameraMoveTo{TargetPosition{\"252.946289,40.415039,104.7854,0.000012,0.199844,-171.002213,35.000008,100000.0,false,DoNotOverride,2.8\"},duration{0}},MoveTo{ActorId{790008},MoveSpeed{75},TargetPoint{\"TargetPoint_110103\"}},PlayAnimation{ActorId{790007},AnimationId{\"Explain02_Start\"},Duration{1}}}}",
          SpeakNpcId = 790008,
          Subtitle = "Right, you must be exhausted, and here I am going on and on. Let's go to the cave and have some rest.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Heitao/003/C85F607A"
        },
        [80040331] = {
          Camera = "853.37207,-1200.737305,85.389404,-0.000213,2.185353,123.806267,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Tu as raison. Cette île est une prison et nous nous sommes coupés du monde.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80040331,
          FinalCamera = "827.745117,-1217.97168,85.389404,-0.000213,2.185353,122.20639,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C85F60CE",
          NextDialogue = 80040332,
          SpeakNpcId = 790007,
          Subtitle = "...You're right. This island is a prison, and we've shut the world out.",
          TalkActionId = {
            [1] = "790007:Explain02_End"
          },
