          },
          FinalCamera = "-21.044922,-372.557251,86.48877,0.000079,4.397842,110.200386,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C865C4AC",
          NextOptions = {
            [1] = 80050303
          },
          SpeakNpcId = 790017,
          Subtitle = "Huff... huff... huff... huff...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C4AC"
        },
        [80050303] = {
