          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C998"
        },
        [80050333] = {
          ContentFR = "Quand tu penses à eux, souris-leur dans la nuit étoilée.",
          DialogueId = 80050333,
          GUID = "C865C9C2",
          NextDialogue = 80050334,
          SpeakNpcId = 100001,
          Subtitle = "So, whenever you miss them, just smile at the night sky.",
          TalkActionId = {
            [1] = "100001:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C9C2"
        },
        [80050334] = {
          Camera = "-101.089844,-114.304626,115.5979,0.000041,2.199259,-98.406013,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui... d’accord... je vais essayer.",
          DialogueId = 80050334,
          FacialId = {
            [1] = "790017:Satisfy01",
            [2] = "100001:Sad01"
          },
          GUID = "C865C9EC",
          NextDialogue = 80050335,
          SpeakNpcId = 790017,
          Subtitle = "Thank you... I'll do that.",
          TalkActionId = {
            [1] = "790017:AgreeHead",
            [2] = "100001:Sad02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/003/C865C9EC"
        },
        [80050335] = {
          Camera = "-64.15625,-266.238037,110.220703,0.000082,-0.001892,107.984558,35.000015,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ne t’inquiète pas, ne sois pas triste pour moi. Parce que maintenant, j’ai un nouveau foyer.",
          DialogueId = 80050335,
          GUID = "C865CA16",
          NextDialogue = 80050336,
          SpeakNpcId = 790017,
          Subtitle = "It's okay, don't feel bad for me, because I have a new home now.",
          TalkActionId = {
            [1] = "790017:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Feina/003/C865CA16"
        },
        [80050336] = {
          Camera = "-109.111328,-35.609192,129.727539,0.000115,-9.201903,-90.815498,35.000015,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai le Grand Magicien, et puis toi. Je suis déjà comblée.",
          DialogueId = 80050336,
          FacialId = {
            [1] = "790017:Happy02"
          },
          FinalCamera = "-109.111328,-35.609192,129.727539,0.000117,-6.401854,-90.81559,35.000015,100000.0,false,DoNotOverride,2.8",
          GUID = "C865CA40",
          SpeakNpcId = 790017,
          Subtitle = "I have the Great Magician, and I have you. I am more than content now.",
          TalkActionId = {
            [1] = "100001:Sad02_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Feina/003/C865CA40"
        },
        [80050401] = {
          Camera = "111.911438,2.710388,118.670654,0.000003,0.0,-152.600952,35.0,160.0,false,Manual,2.8",
          ContentFR = "Te voilà, {性别:Monsieur|Mademoiselle} Licorne !",
          DialogueId = 80050401,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865D4EA",
          NextOptions = {
            [1] = 80050402
          },
          SpeakNpcId = 790017,
          Subtitle = "There you are, {性别:Mr|Miss} Unicorn!",
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D4EA"
        },
        [80050402] = {
          ContentFR = "<I>C’est ton dernier vœu, non ? Où veux-tu aller cette fois, Fina ?</>",
          DialogueId = 80050402,
          GUID = "C865D514",
          NextDialogue = 80050403,
          Subtitle = "Only one wish to go. Where do you want to go this time, Fina?"
        },
        [80050403] = {
          ContentFR = "Hmm... cette fois, on n’ira nulle part. Parce que mon dernier vœu... est déjà ici, avec toi.",
          DialogueId = 80050403,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865D53E",
          NextDialogue = 80050404,
          SpeakNpcId = 790017,
          Subtitle = "This time, we're not going anywhere because my last wish is already here with us.",
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D53E"
        },
        [80050404] = {
          ContentFR = "Regarde, j’ai apporté mon nouveau livre d’histoires !",
          DialogueId = 80050404,
          FacialId = {
            [1] = "790017:Happy01"
          },
          GUID = "C865D568",
          NextDialogue = 80050405,
          SpeakNpcId = 790017,
          Subtitle = "Look, I've brought my new storybook!",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D568"
        },
        [80050405] = {
          ContentFR = "Ah, c’est un recueil d’histoires écrites par toi... ? Hmm ? Mais... les pages sont toutes blanches ?",
          DialogueId = 80050405,
          GUID = "C865D592",
          NextDialogue = 80050406,
          SpeakNpcId = 100001,
          Subtitle = "Oh, it's a collection of stories by Fina... wait, why are all the pages blank?",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D592"
        },
        [80050406] = {
          ContentFR = "Parce que je veux qu’on écrive ensemble une toute nouvelle histoire... C’est ça, mon quatrième vœu.",
          DialogueId = 80050406,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865D5BC",
          NextOptions = {
            [1] = 80050407,
            [2] = 80050408
          },
          SpeakNpcId = 790017,
          Subtitle = "Because I want to write a new storybook with you — that's my fourth wish.",
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D5BC"
        },
        [80050407] = {
          ContentFR = "<I>Un vœu si simple... Bien sûr, avec plaisir.</>",
          DialogueId = 80050407,
          GUID = "C865D5E6",
          NextDialogue = 80050411,
          Subtitle = "Oh, that's a rather simple wish... Absolutely, we can do that."
        },
        [80050408] = {
          ContentFR = "<I>Mais je ne sais pas écrire d’histoires, moi !</>",
          DialogueId = 80050408,
          GUID = "C865D610",
          NextDialogue = 80050409,
          Subtitle = "But I'm not good at writing stories."
        },
        [80050409] = {
          ContentFR = "Ce n’est pas grave... Je peux t’apprendre !",
          DialogueId = 80050409,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865D63A",
          NextDialogue = 80050410,
          SpeakNpcId = 790017,
          Subtitle = "That's okay, I'll teach you!",
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D63A"
        },
        [80050410] = {
          ContentFR = "Ne t’en fais pas. On prendra le temps d’y réfléchir ensemble.",
          DialogueId = 80050410,
          FacialId = {
            [1] = "790017:Confident02"
          },
          GUID = "C865D664",
          NextDialogue = 80050411,
          SpeakNpcId = 790017,
          Subtitle = "No pressure, we'll figure it out together.",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D664"
        },
        [80050411] = {
          ContentFR = "Et la première histoire... on pourrait commencer par une petite aventure, toute simple.",
          DialogueId = 80050411,
          GUID = "C865D68E",
          NextDialogue = 80050412,
          SpeakNpcId = 790017,
          Subtitle = "Let's start the first story with a simple adventure~",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D68E"
        },
        [80050412] = {
          ContentFR = "Un jour, le petit Rossignol et {性别:Monsieur|Mademoiselle} Licorne sont partis ensemble pour une grande aventure...",
          DialogueId = 80050412,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865D6B8",
          NextDialogue = 80050413,
          SpeakNpcId = 790017,
          Subtitle = "One day, Little Nightingale and {性别:Mr|Miss} Unicorn embarked on an adventure together...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D6B8"
        },
        [80050413] = {
          ContentFR = "... Est-ce qu’ils étaient juste tous les deux, ou bien il y avait d’autres compagnons ?",
          DialogueId = 80050413,
          GUID = "C865D6E2",
          NextOptions = {
            [1] = 80050414,
            [2] = 80050416,
            [3] = 80050418
          },
          SpeakNpcId = 790017,
          Subtitle = "Was it just the two of them, or were there other friends?",
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D6E2"
        },
        [80050414] = {
          ContentFR = "<I>Juste eux deux.</>",
          DialogueId = 80050414,
          GUID = "C865D70C",
          NextDialogue = 80050415,
          Subtitle = "Just the two of them."
        },
        [80050415] = {
          ContentFR = "Alors, ce sera leur aventure secrète, rien qu’à eux.",
          DialogueId = 80050415,
          GUID = "C865D736",
          NextDialogue = 80050420,
          SpeakNpcId = 790017,
          Subtitle = "Then it'd be their very own secret adventure.",
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D736"
        },
        [80050416] = {
          ContentFR = "<I>Avec le Grand Magicien.</>",
          DialogueId = 80050416,
          GUID = "C865D760",
          NextDialogue = 80050417,
          Subtitle = "Plus the Great Magician."
        },
        [80050417] = {
          ContentFR = "Oh, avec le Grand Magicien, ce sera un voyage encore plus amusant !",
          DialogueId = 80050417,
          GUID = "C865D78A",
          NextDialogue = 80050420,
          SpeakNpcId = 790017,
          Subtitle = "Right, with the Great Magician along, it'd surely be a wonderful trip.",
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D78A"
        },
        [80050418] = {
          ContentFR = "<I>Et Mademoiselle Papillon.</>",
          DialogueId = 80050418,
          GUID = "C865D7B4",
          NextDialogue = 80050419,
          Subtitle = "Plus Miss Butterfly."
        },
        [80050419] = {
          ContentFR = "Hihi, Mademoiselle Papillon pourrait voler avec le petit Rossignol dans le ciel !",
          DialogueId = 80050419,
          GUID = "C865D7DE",
          NextDialogue = 80050420,
          SpeakNpcId = 790017,
          Subtitle = "Hehe, Miss Butterfly and Little Nightingale could fly in the sky together then.",
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D7DE"
        },
        [80050420] = {
          ContentFR = "Très bien... Alors tout le monde s’est mis en route, et ils sont arrivés...",
          DialogueId = 80050420,
          FacialId = {
            [1] = "790017:Smile01"
          },
          GUID = "C865D808",
          NextOptions = {
            [1] = 80050421,
            [2] = 80050423,
            [3] = 80050425
          },
          SpeakNpcId = 790017,
          Subtitle = "Alright, so they set off together. They arrived at...",
          TalkActionId = {
            [1] = "790017:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D808"
        },
        [80050421] = {
          ContentFR = "<I>Dans une terre gelée, couverte de givre.</>",
          DialogueId = 80050421,
          GUID = "C865D832",
          NextDialogue = 80050422,
          Subtitle = "A frozen land covered in ice."
        },
        [80050422] = {
          ContentFR = "Hmm... Ça me rappelle un peu Givrelac.",
          DialogueId = 80050422,
          GUID = "C865D85C",
          NextDialogue = 80050427,
          SpeakNpcId = 790017,
          Subtitle = "Hmm, sounds a lot like Icelake.",
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D85C"
        },
        [80050423] = {
          ContentFR = "<I>Sur des îles dispersées au milieu de la mer.</>",
          DialogueId = 80050423,
          GUID = "C865D886",
          NextDialogue = 80050424,
          Subtitle = "A cluster of small islands at sea."
        },
        [80050424] = {
          ContentFR = "Alors, ils pourraient voguer sur un petit bateau magique, bercés par les vagues joyeuses.",
          DialogueId = 80050424,
          GUID = "C865D8B0",
          NextDialogue = 80050427,
          SpeakNpcId = 790017,
          Subtitle = "Right, so they set sail in a magical boat, carried away by playful waves.",
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D8B0"
        },
        [80050425] = {
          ContentFR = "<I>Dans un royaume lointain de l’est.</>",
          DialogueId = 80050425,
          GUID = "C865D8DA",
          NextDialogue = 80050426,
          Subtitle = "A faraway realm in the east."
        },
        [80050426] = {
          ContentFR = "Hmm... peut-être qu’ils y rencontreront la gracieuse Dame Dragon ?",
          DialogueId = 80050426,
          GUID = "C865D904",
          NextDialogue = 80050427,
          SpeakNpcId = 790017,
          Subtitle = "Hmm... Perhaps then, they'd meet the elegant Lady Dragon there?",
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D904"
        },
        [80050427] = {
          ContentFR = "Ensuite, ils...",
          DialogueId = 80050427,
          FacialId = {
            [1] = "790017:Satisfy01"
          },
          GUID = "C865D92E",
          NextOptions = {
            [1] = 80050428,
            [2] = 80050430,
            [3] = 80050432
          },
          SpeakNpcId = 790017,
          Subtitle = "After that, they...",
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D92E"
        },
        [80050428] = {
          ContentFR = "<I>Ont découvert un coffre au trésor mystérieux.</>",
          DialogueId = 80050428,
          GUID = "C865D958",
          NextDialogue = 80050429,
          Subtitle = "Discovered a mysterious treasure chest."
        },
        [80050429] = {
          ContentFR = "Un coffre ? Qu’est-ce qu’il y avait dedans ? Des pièces d’argent ? Des fleurs ? Des petits blocs mignons ?",
          DialogueId = 80050429,
          GUID = "C865D982",
          NextDialogue = 80050434,
          SpeakNpcId = 790017,
          Subtitle = "A chest...? What could be in it? Silver coins, pretty flowers, or finely made building blocks?",
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D982"
        },
        [80050430] = {
          ContentFR = "<I>Ont rencontré des amis venus d’ailleurs.</>",
          DialogueId = 80050430,
          GUID = "C865D9AC",
          NextDialogue = 80050431,
          Subtitle = "Made new friends in a foreign land."
        },
        [80050431] = {
          ContentFR = "Oh, ça veut dire plus de compagnons de voyage ! Ce sera encore plus joyeux...",
          DialogueId = 80050431,
          GUID = "C865D9D6",
          NextDialogue = 80050434,
          SpeakNpcId = 790017,
          Subtitle = "That means more companions for the journey — the more, the merrier!",
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865D9D6"
        },
        [80050432] = {
          ContentFR = "<I>Se sont émerveillés devant des paysages magnifiques.</>",
          DialogueId = 80050432,
          GUID = "C865DA00",
          NextDialogue = 80050433,
          Subtitle = "Revelled in the spectacular scenery."
        },
        [80050433] = {
          ContentFR = "Eh oui... L’une des raisons de partir à l’aventure, c’est pour voir les plus beaux endroits du monde.",
          DialogueId = 80050433,
          GUID = "C865DA2A",
          NextDialogue = 80050434,
          SpeakNpcId = 790017,
          Subtitle = "Right, going on an adventure is about seeing all those wonderful places in the world.",
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DA2A"
        },
        [80050434] = {
          ContentFR = "Et pour finir, ils...",
          DialogueId = 80050434,
          FacialId = {
            [1] = "790017:Confident01"
          },
          GUID = "C865DA54",
          NextOptions = {
            [1] = 80050435,
            [2] = 80050436,
            [3] = 80050437
          },
          SpeakNpcId = 790017,
          Subtitle = "In the end, they...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DA54"
        },
        [80050435] = {
          ContentFR = "<I>Sont rentrés chez eux les bras pleins de trésors.</>",
          DialogueId = 80050435,
          GUID = "C865DA7E",
          NextDialogue = 80050438,
          Subtitle = "Returned home with a wealth of treasures."
        },
        [80050436] = {
          ContentFR = "<I>Ont trouvé un pays prospère, où ils ont vécu heureux.</>",
          DialogueId = 80050436,
          GUID = "C865DAA8",
          NextDialogue = 80050438,
          Subtitle = "Settled down in another prosperous land and lived happily ever after."
        },
        [80050437] = {
          ContentFR = "<I>Ont vaincu le terrible Roi Démon et sont devenus des héros légendaires.</>",
          DialogueId = 80050437,
          GUID = "C865DAD2",
          NextDialogue = 80050438,
          Subtitle = "Defeated the evil Demon Lord and became celebrated folk heroes."
        },
        [80050438] = {
          ContentFR = "Oui ! Et comme ça, l’histoire...",
          DialogueId = 80050438,
          GUID = "C865DAFC",
          NextDialogue = 80050439,
          SpeakNpcId = 790017,
          Subtitle = "Right! So this is how the story...",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DAFC"
        },
        [80050439] = {
          ContentFR = " ... Hmm...",
          DialogueId = 80050439,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865DB26",
          NextOptions = {
            [1] = 80050440
          },
          SpeakNpcId = 790017,
          Subtitle = "Hmm...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DB26"
        },
        [80050440] = {
          ContentFR = "<I>Qu’est-ce qu’il y a ?</>",
          DialogueId = 80050440,
          GUID = "C865DB50",
          NextDialogue = 80050441,
          Subtitle = "What's wrong?"
        },
        [80050441] = {
          ContentFR = "J’ai l’impression… qu’il manque quelque chose dans notre histoire…",
          DialogueId = 80050441,
          FacialId = {
            [1] = "790017:Iyada01"
          },
          GUID = "C865DB7A",
          NextDialogue = 80050442,
          SpeakNpcId = 790017,
          Subtitle = "I just feel like... there's something missing from our story...",
          TalkActionId = {
            [1] = "790017:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DB7A"
        },
        [80050442] = {
          ContentFR = "...",
          DialogueId = 80050442,
          GUID = "C865DBA4",
          NextDialogue = 80050443,
          SpeakNpcId = 100001,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DBA4"
        },
        [80050443] = {
          ContentFR = "On a pourtant écrit une fin parfaite... Tout le monde est heureux... Alors, qu’est-ce qu’il manque ?",
          DialogueId = 80050443,
          GUID = "C865DBCE",
          NextDialogue = 80050444,
          SpeakNpcId = 790017,
          Subtitle = "It's such a perfect story, with a happy ending for everyone... What could possibly be missing?",
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DBCE"
        },
        [80050444] = {
          ContentFR = "...",
          DialogueId = 80050444,
          GUID = "C865DBF8",
          NextDialogue = 80050445,
          SpeakNpcId = 100001,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DBF8"
        },
        [80050445] = {
          ContentFR = "... Je crois que je sais.",
          DialogueId = 80050445,
          GUID = "C865DC22",
          NextOptions = {
            [1] = 80050446,
            [2] = 80050447
          },
          SpeakNpcId = 100001,
          Subtitle = "I think I know.",
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DC22"
        },
        [80050446] = {
          ContentFR = "<I>Parce qu’elle est \"trop parfaite\".</>",
          DialogueId = 80050446,
          GUID = "C865DC4C",
          NextDialogue = 80050448,
          Subtitle = "The problem with this story is just being \"perfect.\""
        },
        [80050447] = {
          ContentFR = "<I>Ce qui manque, c’est un peu de tristesse... un \"regret\".</>",
          DialogueId = 80050447,
          GUID = "C865DC76",
          NextDialogue = 80050448,
          Subtitle = "What's missing from the story is \"regrets.\""
        },
        [80050448] = {
          ContentFR = "Tout s’est passé trop facilement, tu ne trouves pas ? Pas de tempêtes à traverser, pas de larmes à verser... Ça paraît un peu irréel.",
          DialogueId = 80050448,
          GUID = "C865DCA0",
          NextDialogue = 80050449,
          SpeakNpcId = 100001,
          Subtitle = "Everything in this story goes perfectly, doesn't it? Without any real challenges or regrets, it all feels almost unreal.",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DCA0"
        },
        [80050449] = {
          ContentFR = "...",
          DialogueId = 80050449,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865DCCA",
          NextDialogue = 80050450,
          SpeakNpcId = 790017,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DCCA"
        },
        [80050450] = {
          ContentFR = "Tu as peut-être raison... Dans les histoires que maman me racontait, il n’y avait pas que des choses heureuses. Il y avait aussi... des choses tristes, des malheurs.",
          DialogueId = 80050450,
          GUID = "C865DCF4",
          NextDialogue = 80050451,
          SpeakNpcId = 790017,
          Subtitle = "Right... When I was little, the stories my mother told weren't just about happiness and laughter. There would also be bad things and tears:",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DCF4"
        },
        [80050451] = {
          ContentFR = "La belle princesse tombait dans un sommeil éternel... Le prince courageux devenait une bête... Les enfants étaient enlevés par des sorciers... Un petit oiseau maladroit se figeait dans le ciel nocturne...",
          DialogueId = 80050451,
          FacialId = {
            [1] = "790017:Sad01"
          },
          GUID = "C865DD1E",
          NextDialogue = 80050452,
          SpeakNpcId = 790017,
          Subtitle = "Beautiful princesses fell into deep slumbers, enchanted princes turned into beasts, children were taken by evil sorcerers, and little birds froze in the night sky...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DD1E"
        },
        [80050452] = {
          ContentFR = "Même si la fin était souvent heureuse... pourquoi fallait-il qu’ils vivent tant de tristesse ? Pourquoi tout le monde ne pourrait pas être heureux pour toujours ?",
          DialogueId = 80050452,
          GUID = "C865DD48",
          NextOptions = {
            [1] = 80050453
          },
          SpeakNpcId = 790017,
          Subtitle = "Even though the endings were normally good... why must they experience sadness first? Why couldn't they be happy all the time?",
          TalkActionId = {
            [1] = "790017:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DD48"
        },
        [80050453] = {
          ContentFR = "<I>Parce que la vie est faite comme ça.</>",
          DialogueId = 80050453,
          GUID = "C865DD72",
          NextDialogue = 80050454,
          Subtitle = "Because that's just how life is."
        },
        [80050454] = {
          ContentFR = "C’est un peu comme tes guimauves préférées. Dans le pot, il y en a de toutes sortes, sucrées, acidulées... et parfois, même un peu amères.",
          DialogueId = 80050454,
          GUID = "C865DD9C",
          NextDialogue = 80050455,
          SpeakNpcId = 100001,
          Subtitle = "Well, take your favourite marshmallows for example: They come in different flavours — some are sweet, some are sour, and some are even a bit bitter.",
          TalkActionId = {
            [1] = "790017:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DD9C"
        },
        [80050455] = {
          ContentFR = "Oui ! Moi, j’adore les sucrées, et je déteste les amères... Enfin, surtout celles à la moutarde. Pourquoi quelqu’un a mis de la moutarde dans une guimauve, sérieusement ?",
          DialogueId = 80050455,
          FacialId = {
            [1] = "790017:Smile01"
          },
          GUID = "C865DDC6",
          NextDialogue = 80050456,
          SpeakNpcId = 790017,
          Subtitle = "Right! I love those sweet ones, and hate the bitter ones... no, the mustard flavour is the worst. Why would anyone put mustard in marshmallows!?",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DDC6"
        },
        [80050456] = {
          ContentFR = "Chaque fois que j’en mange une par erreur, ça me pique les yeux... Alors je prends une sucrée tout de suite après. Et là, elle me paraît encore plus délicieuse.",
          DialogueId = 80050456,
          FacialId = {
            [1] = "790017:Syouganai01"
          },
          GUID = "C865DDF0",
          NextDialogue = 80050457,
          SpeakNpcId = 790017,
          Subtitle = "Every time I had one of those by mistake, it'd bring tears to my eyes, and I had to find a sweet one to get rid of the mustard taste in my mouth. What's funny is that the sweet taste would seem stronger—",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DDF0"
        },
        [80050457] = {
          ContentFR = "Ah... Je crois que je comprends... C’est justement parce qu’il y a des guimauves piquantes ou amères... que les sucrées sont si bonnes.",
          DialogueId = 80050457,
          FacialId = {
            [1] = "790017:Smile01"
          },
          GUID = "C865DE1A",
          NextDialogue = 80050458,
          SpeakNpcId = 790017,
          Subtitle = "Ah, I get it now... It's precisely because of the bitter and mustard-flavored ones that the sweet ones taste so good.",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DE1A"
        },
        [80050458] = {
          ContentFR = "...",
          DialogueId = 80050458,
          GUID = "C865DE44",
          NextDialogue = 80050459,
          SpeakNpcId = 790017,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DE44"
        },
        [80050459] = {
          ContentFR = "C’est pareil pour les histoires, alors... ? S’il n’y a ni tristesse ni regrets, alors le bonheur perd un peu de sa valeur...",
          DialogueId = 80050459,
          FacialId = {
            [1] = "790017:Shock02"
          },
          GUID = "C865DE6E",
          NextDialogue = 80050460,
          SpeakNpcId = 790017,
          Subtitle = "And it's the same with the stories, right? If there's no sadness or regrets, then happiness wouldn't feel as precious...",
          TalkActionId = {
            [1] = "790017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DE6E"
        },
        [80050460] = {
          ContentFR = "Je vois... C’est pour ça... Maintenant, je comprends tout.",
          DialogueId = 80050460,
          FacialId = {
            [1] = "790017:None"
          },
          GUID = "C865DE98",
          NextDialogue = 80050461,
          SpeakNpcId = 790017,
          Subtitle = "So that's how it is... I see.",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DE98"
        },
        [80050461] = {
          ContentFR = "L’histoire qu’on vient d’écrire, c’est comme notre vœu le plus cher... Mais une vraie histoire, c’est un mélange de rires et de larmes... comme notre vie à nous.",
          DialogueId = 80050461,
          FacialId = {
            [1] = "790017:Satisfy01"
          },
          GUID = "C865DEC2",
          NextDialogue = 80050462,
          SpeakNpcId = 790017,
          Subtitle = "The story we just wrote stands for our fondest wish. But a real story, like our lives, has both laughter and tears...",
          TalkActionId = {
            [1] = "790017:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DEC2"
        },
        [80050462] = {
          ContentFR = "Merci, {性别:Monsieur|Mademoiselle} Licorne. Je crois que j’aurai besoin de plus de temps...",
          DialogueId = 80050462,
          GUID = "C865DEEC",
          NextDialogue = 80050463,
          SpeakNpcId = 790017,
          Subtitle = "Thank you, {性别:Mr|Miss} Unicorn. I think I'll need more time...",
          TalkActionId = {
            [1] = "790017:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DEEC"
        },
        [80050463] = {
          ContentFR = "Il faut que je grandisse encore... que j’apprenne, que je découvre le monde, avant de pouvoir vraiment écrire cette histoire.",
          DialogueId = 80050463,
          GUID = "C865DF16",
          NextDialogue = 80050464,
          SpeakNpcId = 790017,
          Subtitle = "To grow, to live, to learn, and to travel — before I can finish this storybook.",
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DF16"
        },
        [80050464] = {
          ContentFR = "Alors, {性别:Monsieur|Mademoiselle} Licorne... tu me dois encore ce vœu-là, d’accord ?",
          DialogueId = 80050464,
          FacialId = {
            [1] = "790017:Confident01"
          },
          GUID = "C865DF40",
          NextOptions = {
            [1] = 80050465,
            [2] = 80050466
          },
          SpeakNpcId = 790017,
          Subtitle = "So, {性别:Mr|Miss} Unicorn, you still owe me that wish!",
          TalkActionId = {
            [1] = "790017:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DF40"
        },
        [80050465] = {
          ContentFR = "<I>D’accord, je te le promets.</>",
          DialogueId = 80050465,
          GUID = "C865DF6A",
          NextDialogue = 80050467,
          Subtitle = "Sure, whenever you feel ready."
        },
        [80050466] = {
          ContentFR = "<I>... Je me suis fait piéger, pas vrai ?</>",
          DialogueId = 80050466,
          GUID = "C865DF94",
          NextDialogue = 80050467,
          Subtitle = "Oof, I walked right into this, didn't I?"
        },
        [80050467] = {
          ContentFR = "Hihi... Alors, un jour, on écrira cette histoire ensemble. D’accord ?",
          DialogueId = 80050467,
          FacialId = {
            [1] = "790017:Happy02"
          },
          GUID = "C865DFBE",
          SpeakNpcId = 790017,
          Subtitle = "Hehe, let's fill this book with wonderful stories in the future!",
          TalkActionId = {
            [1] = "790017:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Feina/004/C865DFBE"
        },
        [80060100] = {
          ContentFR = "Rien de plus important qu’un bon repas ! Allez, montre-moi si ton ventre est bien rempli !",
          DialogueId = 80060100,
          GUID = "C86C0C28",
          Subtitle = "Nothing's more important than having a good meal! Lemme see if you've had your fill!",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0C28"
        },
        [80060101] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentFR = "Mmh, ça sent drôlement bon, ce pain à boire ! C’est toi qui l’as fait ? Trop fort !",
          DialogueId = 80060101,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C0C52",
          LookAt = {
            [1] = "95101:p(18000P3)"
          },
          NextDialogue = 80060102,
          SpeakNpcId = 95101,
          Subtitle = "Mmm — this bread drink smells amazing! Did you make it yourself? You've really got a knack for this!",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0C52"
        },
        [80060102] = {
          ContentFR = "Pendant une distribution de vivres, une dame adorable a amené du pain à boire fait maison. Elle disait que c’était super long à préparer !",
          DialogueId = 80060102,
          GUID = "C86C0C7C",
          NextDialogue = 80060103,
          SpeakNpcId = 95101,
          Subtitle = "At one of our food drives, a kind-hearted lady brought along her homemade bread drink. She said it was quite the project!",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0C7C"
        },
        [80060103] = {
          ContentFR = "Faut d’abord couper le pain en petits morceaux, saupoudrer de sucre de malt tout doux, passer le tout au four pour que ce soit bien chaud, puis le faire tremper pour le laisser fermenter... glou glou glou.",
          DialogueId = 80060103,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C0CA6",
          NextDialogue = 80060104,
          SpeakNpcId = 95101,
          Subtitle = "You gotta chop up bread into bits, sprinkle on some sweet malt sugar, toast it till it's nice and warm, then soak it to let it ferment into a bubbly delight...",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0CA6"
        },
        [80060104] = {
          ContentFR = "Mmh... Le tien est aussi bon que celui qu’elle avait préparé !",
          DialogueId = 80060104,
          GUID = "C86C0CD0",
          NextOptions = {
            [1] = 80060105
          },
          Subtitle = "Mmm... this tastes just as good as the bread drink she made!",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0CD0"
        },
        [80060105] = {
          ContentFR = "<I>Tu sais même faire ça ?</>",
          DialogueId = 80060105,
          GUID = "C86C0CFA",
          NextDialogue = 80060106,
          Subtitle = "Wow, you know how to make this? It's not a common drink."
        },
        [80060106] = {
          ContentFR = "Évidemment ! Je sais tout ce qu’il faut pour bien remplir les ventres !",
          DialogueId = 80060106,
          GUID = "C86C0D24",
          NextDialogue = 80060107,
          SpeakNpcId = 95101,
          Subtitle = "Mm-hmm, I know everything about keeping bellies full!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0D24"
        },
        [80060107] = {
          ContentFR = "C’est pas pour frimer, mais je suis carrément l’encyclopédie vivante de la bouffe d’Élysium. Y’a pas un ingrédient que Commissaire Truffle ne connaisse pas !",
          DialogueId = 80060107,
          FacialId = {
            [1] = "95101:Confident02"
          },
          GUID = "C86C0D4E",
          NextDialogue = 80060108,
          SpeakNpcId = 95101,
          Subtitle = "I'm not bragging, you know — I'm like Elysium's walking encyclopedia of food! There's nothing about food that Commissary Truffle doesn't know!",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0D4E"
        },
        [80060108] = {
          ContentFR = "Alors si t’as la moindre question sur la bouffe, genre, quels légumes sont les meilleurs en ce moment, ou ce qu’il y a dans ce plat-là, viens me voir !",
          DialogueId = 80060108,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C0D78",
          NextOptions = {
            [1] = 80060109
          },
          SpeakNpcId = 95101,
          Subtitle = "So, any questions you've got about food — like where to find the best veggies in season right now, or what's in a certain dish — I've got all the answers!",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0D78"
        },
        [80060109] = {
          ContentFR = "Vraiment ? Tu peux deviner les fruits que t’as bus à l’instant ?",
          DialogueId = 80060109,
          GUID = "C86C0DA2",
          NextDialogue = 80060110,
          Subtitle = "Really? Can you guess which fruits are in this drink?"
        },
        [80060110] = {
          ContentFR = "Bien sûr, laisse-moi regoûter ! Mmh... C’est de la Baie boréale ! Mais un peu trop acide. Si tu les avais cueillies dans deux-trois jours, elles auraient été plus grosses et bien plus sucrées.",
          DialogueId = 80060110,
          FacialId = {
            [1] = "95101:Happy01"
          },
          GUID = "C86C0DCC",
          NextOptions = {
            [1] = 80060111
          },
          SpeakNpcId = 95101,
          Subtitle = "Challenge accepted~ Lemme have another sip! ...Mmm, borealberries! Though they are a bit tart right now; they'd become sweeter and juicier a couple of days later.",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0DCC"
        },
        [80060111] = {
          ContentFR = "<I>Il t’en manque une. Une autre baie.</>",
          DialogueId = 80060111,
          GUID = "C86C0DF6",
          NextDialogue = 80060112,
          Subtitle = "You missed another berry, though."
        },
        [80060112] = {
          ContentFR = "Oui, y’a un autre goût... super familier... Attends, attends, je l’ai presque...",
          DialogueId = 80060112,
          GUID = "C86C0E20",
          NextOptions = {
            [1] = 80060113
          },
          SpeakNpcId = 95101,
          Subtitle = "I know... Mmm, this taste is so familiar... just give me a moment...",
          TalkActionId = {
            [1] = "95101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0E20"
        },
        [80060113] = {
          ContentFR = "<I>Tu veux un indice ? C’est...</>",
          DialogueId = 80060113,
          GUID = "C86C0E4A",
          NextDialogue = 80060114,
          Subtitle = "Need a hint? It's—"
        },
        [80060114] = {
          ContentFR = "... des Larmes vermillon ! Tu les as cueillies ce matin, hein ? Fraîchement sorties de la forêt !",
          DialogueId = 80060114,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C0E74",
          NextOptions = {
            [1] = 80060115
          },
          SpeakNpcId = 95101,
          Subtitle = "—Vermilion Teardrops! Freshly picked this morning from the wild, right?",
          TalkActionId = {
            [1] = "95101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0E74"
        },
        [80060115] = {
          ContentFR = "Exactement...",
          DialogueId = 80060115,
          GUID = "C86C0E9E",
          NextDialogue = 80060116,
          Subtitle = "Exactly right..."
        },
        [80060116] = {
          ContentFR = "Hé hé, t’as l’air {性别:surpris|surprise} ! Faut pas sous-estimer mon palais. Moi et Filbert, on a goûté à TOUT. Les Larmes vermillon, c’est rien du tout !",
          DialogueId = 80060116,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C0EC8",
          NextDialogue = 80060117,
          SpeakNpcId = 95101,
          Subtitle = "Haha, why so surprised? It's no big deal. Filbert and I have tried EVERYTHING you can imagine — there's nothing unfamiliar to my taste buds.",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0EC8"
        },
        [80060117] = {
          ContentFR = "Elles sont un peu acides, un peu comme les prunes, alors elles vont super bien avec des fruits bien sucrés. Les méga-pignons, eux, ont une coque ultra épaisse, mais à l’intérieur c’est croquant, doux et super bon !",
          DialogueId = 80060117,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C0EF2",
          NextDialogue = 80060118,
          SpeakNpcId = 95101,
          Subtitle = "Now, Vermilion Teardrops are a bit sour, like plums, so they go well with sweet berries; giant pine cones have tough shells, but the nuts inside are tender, crunchy, and sweet!",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0EF2"
        },
        [80060118] = {
          ContentFR = "Les Vrilles rampantes, c’est tout noir et moche, et devine quoi ? C’est aussi mauvais que ça en a l’air. Et les pots de mastic isolant, on dirait du lait, ça sent bon, mais tu finis plié en deux si t’en manges. Goûte pas à ça, jamais jamais jamais !",
          DialogueId = 80060118,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C0F1C",
          NextOptions = {
            [1] = 80060119,
            [2] = 80060122
          },
          SpeakNpcId = 95101,
          Subtitle = "Creeping Tendrils taste just as awful as they look; insulating sealant looks like milk and smells fruity, but if you eat it, you'll get a tummy ache... so never try it!",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0F1C"
        },
        [80060119] = {
          ContentFR = "<I>Me dis pas que t’as déjà goûté des tentacules de Souillés...</>",
          DialogueId = 80060119,
          GUID = "C86C0F46",
          NextDialogue = 80060120,
          Subtitle = "...Please tell me you've never tried Filthoid tentacles..."
        },
        [80060120] = {
          ContentFR = "Ah, non, pas encore. Ça a quel goût, tu crois ? Ça doit être gluant... bien élastique... Peut-être que je pourrais tester avec Filbert, la prochaine fois...",
          DialogueId = 80060120,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C0F70",
          NextDialogue = 80060121,
          SpeakNpcId = 95101,
          Subtitle = "Nope, haven't gotten around to those. Wonder how they taste? Probably very slimy and chewy... Should Filbert and I try them out sometime...",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0F70"
        },
        [80060121] = {
          ContentFR = "Ah non, mauvaise idée ! Filbert peut cogner les petits Souillés, mais les gros sont hyper dangereux ! Je vais pas risquer la vie de Filbert pour ça.",
          DialogueId = 80060121,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C0F9A",
          NextOptions = {
            [1] = 80060125
          },
          SpeakNpcId = 95101,
          Subtitle = "Mm, pass! Though Filbert can knock over small Filthoids, those big ones are quite violent. I can't put Filbert in danger!",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0F9A"
        },
        [80060122] = {
          ContentFR = "<I>Franchement, que t’aies réussi à rester en bonne santé jusqu’à maintenant, c’est un miracle...</>",
          DialogueId = 80060122,
          GUID = "C86C0FC4",
          NextDialogue = 80060123,
          Subtitle = "It's a miracle you've managed to stay healthy growing up..."
        },
        [80060123] = {
          ContentFR = "Ouais... quand j’étais petite et que je vagabondais avec Filbert, des fois on tombait sur des trucs toxiques. Le ventre faisait super mal...",
          DialogueId = 80060123,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C0FEE",
          NextDialogue = 80060124,
          SpeakNpcId = 95101,
          Subtitle = "Uh-huh. When I was little and wandering with Filbert, we occasionally nibbled on something poisonous and got sick.",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C0FEE"
        },
        [80060124] = {
          ContentFR = "Mais t’inquiète pas ! Maintenant, dès que je vois ou je sens une plante, je sais tout de suite si on peut la manger ou pas !",
          DialogueId = 80060124,
          GUID = "C86C1018",
          NextOptions = {
            [1] = 80060125
          },
          SpeakNpcId = 95101,
          Subtitle = "But don't worry! Now I'm quite the expert at identifying which plants are safe to munch on.",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1018"
        },
        [80060125] = {
          ContentFR = "<I>Mais t’as goûté tout ça comment, au juste ?</>",
          DialogueId = 80060125,
          GUID = "C86C1042",
          NextDialogue = 80060126,
          Subtitle = "How come you've tried so many different \"foods\"?"
        },
        [80060126] = {
          ContentFR = "Parce qu’on n’avait rien à manger. Toute petite, j’étais déjà seule dans la rue.",
          DialogueId = 80060126,
          FacialId = {
            [1] = "95101:Iyada01"
          },
          GUID = "C86C106C",
          NextDialogue = 80060127,
          SpeakNpcId = 95101,
          Subtitle = "Because there was nothing much to eat. I started wandering alone at a very young age.",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C106C"
        },
        [80060127] = {
          ContentFR = "Et en plus, j’ai toujours eu un gros appétit. Même quand des gens sympas me donnaient un petit gâteau ou un morceau de pain, j’avais encore faim. Tout le temps, tout le temps...",
          DialogueId = 80060127,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C1096",
          NextDialogue = 80060128,
          SpeakNpcId = 95101,
          Subtitle = "I've always been a big eater, so even though kind people sometimes gave me food, it was never enough — I was always hungry...",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1096"
        },
        [80060128] = {
          ContentFR = "Mais t’inquiète pas, j’en fais plus une montagne. Parce qu’un jour, j’ai rencontré Filbert.",
          DialogueId = 80060128,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C10C0",
          NextDialogue = 80060129,
          SpeakNpcId = 95101,
          Subtitle = "Aww, don't feel bad for me! I'm not upset about it, because I met Filbert soon after.",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C10C0"
        },
        [80060129] = {
          ContentFR = "Ce jour-là, j’avais super faim. Et Filbert aussi. Elle était toute petite à l’époque. Mais elle m’a quand même donné le seul morceau de pain qu’elle avait trouvé dans une poubelle.",
          DialogueId = 80060129,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C10EA",
          NextDialogue = 80060130,
          SpeakNpcId = 95101,
          Subtitle = "That day, I was super hungry, and so was Filbert. She was just a tiny piglet then, but she gave me the only piece of bread she had found in a bin.",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C10EA"
        },
        [80060130] = {
          ContentFR = "Je me souviens plus trop ce que je pensais à ce moment-là. Juste que je me suis penchée vers son oreille et j’ai dit : « Allez, on quitte cette ville ensemble. On part chercher à manger ailleurs, d’accord ? »",
          DialogueId = 80060130,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C1114",
          NextOptions = {
            [1] = 80060131
          },
          SpeakNpcId = 95101,
          Subtitle = "I don't quite remember what I was thinking back then, just that I whispered into her ear, \"Let's leave the city and find food in the wild together!\"",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1114"
        },
        [80060131] = {
          ContentFR = "<I>Un cochon qui comprend les humains... eh ben.</>",
          DialogueId = 80060131,
          GUID = "C86C113E",
          NextDialogue = 80060132,
          Subtitle = "Wow, a pig that understands human speech..."
        },
        [80060132] = {
          ContentFR = "Incroyable, hein ? Moi je suis sûre que Filbert m’a été envoyée par les dieux.",
          DialogueId = 80060132,
          GUID = "C86C1168",
          NextDialogue = 80060133,
          SpeakNpcId = 95101,
          Subtitle = "Uh-huh, amazing, right? Filbert must be a gift from the gods.",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1168"
        },
        [80060133] = {
          ContentFR = "Depuis ce jour-là, elle me porte sur son dos. On va dans les champs, les forêts... On n’a plus jamais eu faim. Et on a même parfois assez pour partager avec d’autres qui ont très faim",
          DialogueId = 80060133,
          GUID = "C86C1192",
          NextDialogue = 80060134,
          SpeakNpcId = 95101,
          Subtitle = "Ever since that day, Filbert has carried me to fields and forests to find food... We never went hungry again, and we've even been able to share extra food with other starving people.",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1192"
        },
        [80060134] = {
          ContentFR = "Ah... Filbert... Elle doit avoir faim, toute seule dehors. Dis, je peux emporter la moitié de la boisson que tu m’as donnée, pour lui en faire goûter ?",
          DialogueId = 80060134,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C11BC",
          NextOptions = {
            [1] = 80060135,
            [2] = 80060138
          },
          SpeakNpcId = 95101,
          Subtitle = "Ah... I wonder if Filbert's hungry out there on her own. Can I take the rest of this drink to share with her?",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C11BC"
        },
        [80060135] = {
          ContentFR = "<I>Bien sûr, vas-y.</>",
          DialogueId = 80060135,
          GUID = "C86C11E6",
          NextDialogue = 80060136,
          Subtitle = "Of course."
        },
        [80060136] = {
          ContentFR = "Ouaaah, t’es trop {性别:gentil|gentille} ! Y’en a toujours pour râler parce que Filbert ressemble à un cochon, et ils comprennent pas pourquoi je partage avec elle. Mais pour moi, c’est plus qu’un animal...",
          DialogueId = 80060136,
          FacialId = {
            [1] = "95101:Happy01"
          },
          GUID = "C86C1210",
          NextDialogue = 80060137,
          SpeakNpcId = 95101,
          Subtitle = "Aww, you're so kind-hearted! Some people frown upon me sharing treats with Filbert, just because she looks like a pig. But to me, Filbert is a dear friend...",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C1210"
        },
        [80060137] = {
          ContentFR = "Merci de ne pas la rejeter, ça compte beaucoup pour moi !",
          DialogueId = 80060137,
          GUID = "C86C123A",
          NextDialogue = 80060141,
          SpeakNpcId = 95101,
          Subtitle = "Anyway, thank you so much for not judging!",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C123A"
        },
        [80060138] = {
          ContentFR = "<I>Partager ma boisson avec un cochon, non merci...</>",
          DialogueId = 80060138,
          GUID = "C86C1264",
          NextDialogue = 80060139,
          Subtitle = "I'd rather not share my drink with a pig..."
        },
        [80060139] = {
          ContentFR = "Oh... bon, alors j’en boirai pas non plus.",
          DialogueId = 80060139,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C128E",
          NextDialogue = 80060140,
          SpeakNpcId = 95101,
          Subtitle = "Oh...Okay. Then I won't drink it either.",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C128E"
        },
        [80060140] = {
          ContentFR = "Filbert, c’est ma meilleure amie. Si tu la rejettes, c’est comme si tu me rejetais moi aussi. Ça lui ferait de la peine... et à moi aussi. Mais merci quand même pour la boisson.",
          DialogueId = 80060140,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C12B8",
          NextDialogue = 80060141,
          SpeakNpcId = 95101,
          Subtitle = "Filbert is my best friend; rejecting her is the same as rejecting me... it'd hurt her feelings, and mine too. But still, thank you for the bread drink.",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C12B8"
        },
        [80060141] = {
          ContentFR = "J’ai bien bu. À la prochaine !",
          DialogueId = 80060141,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C12E2",
          SpeakNpcId = 95101,
          Subtitle = "I'm full now. See you around!",
          VoiceName = "voice/$Locale$/inv/Songlu/001/C86C12E2"
        },
        [80060201] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentFR = "Mmh... mmmh...",
          DialogueId = 80060201,
          GUID = "C86C1CBA",
          LookAt = {
            [1] = "95101:p(18000P3)"
          },
          NextDialogue = 80060202,
          SpeakNpcId = 95101,
          Subtitle = "Hmm... ugh...",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1CBA"
        },
        [80060202] = {
          ContentFR = "<I>Soupir...</>",
          DialogueId = 80060202,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C1CE4",
          NextOptions = {
            [1] = 80060203
          },
          SpeakNpcId = 95101,
          Subtitle = "*sigh*",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1CE4"
        },
        [80060203] = {
          ContentFR = "Tu as l’air contrariée, qu’est-ce qu’il y a ?",
          DialogueId = 80060203,
          GUID = "C86C1D0E",
          NextDialogue = 80060204,
          Subtitle = "You seem upset. What's wrong?"
        },
        [80060204] = {
          ContentFR = "Hein ? Non, non, pas du tout... Je vais bien... Hé hé, hé hé hé !",
          DialogueId = 80060204,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C1D38",
          NextOptions = {
            [1] = 80060205
          },
          SpeakNpcId = 95101,
          Subtitle = "Huh? Oh, I'm fine... Hehe, hehehe!",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1D38"
        },
        [80060205] = {
          ContentFR = "<I>Arrête de faire semblant, t’avais les joues toutes gonflées, on aurait dit que t’avais planqué du pain dedans.</>",
          DialogueId = 80060205,
          GUID = "C86C1D62",
          NextDialogue = 80060206,
          Subtitle = "Come on, I could spot that pout from a mile away."
        },
        [80060206] = {
          ContentFR = "Ah, tu m’as bien démasquée... Bon, c’est vrai, partager le pain c’est chouette, partager les soucis c’est moins cool. Mais puisque tu me demandes, viens m’aider à comprendre !",
          DialogueId = 80060206,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C1D8C",
          NextDialogue = 80060207,
          SpeakNpcId = 95101,
          Subtitle = "Ah, you saw through me... Well, they say sharing bread is good and sharing troubles is bad, but since you asked... maybe you can help me figure this out!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1D8C"
        },
        [80060207] = {
          ContentFR = "Y’a quelques jours, j’ai rencontré un type vraiment pénible... Il semblait être le majordome d’une famille noble, et il voulait acheter plein de noisettes chez nous, les commissaires.",
          DialogueId = 80060207,
          FacialId = {
            [1] = "95101:Unacceptable01"
          },
          GUID = "C86C1DB6",
          NextDialogue = 80060208,
          SpeakNpcId = 95101,
          Subtitle = "A few days ago, I met a really obnoxious guy... He seemed to be a butler for some noble family, and he wanted to buy loads of nuts from us commissaries.",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1DB6"
        },
        [80060208] = {
          ContentFR = "Il est venu avec ses serviteurs, sept gros sacs entiers, et la paye sur la commande, c’était une vraie fortune !",
          DialogueId = 80060208,
          GUID = "C86C1DE0",
          NextDialogue = 80060209,
          SpeakNpcId = 95101,
          Subtitle = "He and his men brought seven big bags, and the payment offered was all zeros and commas!",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1DE0"
        },
        [80060209] = {
          ContentFR = "Comme dit toujours la prêtresse : « Un sou non gagné, c’est un sou perdu ! » Alors Filbert et moi, on a trimé toute la journée pour cette commande.",
          DialogueId = 80060209,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C1E0A",
          NextOptions = {
            [1] = 80060210
          },
          SpeakNpcId = 95101,
          Subtitle = "As a priestess in the church always says, \"A coin not earned is a coin lost!\" So, Filbert and I worked our tails off all day for this order.",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1E0A"
        },
        [80060210] = {
          ContentFR = "<I>Tu veux dire... il a pris la commande sans la payer ?</>",
          DialogueId = 80060210,
          GUID = "C86C1E34",
          NextDialogue = 80060211,
          Subtitle = "Did he stiff you on the payment for those nuts?"
        },
        [80060211] = {
          ContentFR = "C’est même pas ça, au contraire, il a tout payé, et en plus, il a donné un bonus parce qu’on a été rapides. C’était parfait, normalement...",
          DialogueId = 80060211,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C1E5E",
          NextDialogue = 80060212,
          SpeakNpcId = 95101,
          Subtitle = "It was the opposite. He paid in full and even added a bonus for our quick service — it should've been a great deal.",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1E5E"
        },
        [80060212] = {
          ContentFR = "Mais j’ai l’œil, tu sais. Quand ils sont partis, j’ai vu le majordome sortir plusieurs noisettes fraîches des sacs et les jeter à la poubelle.",
          DialogueId = 80060212,
          GUID = "C86C1E88",
          NextDialogue = 80060213,
          SpeakNpcId = 95101,
          Subtitle = "But as they were leaving, I noticed the butler picking out some fresh Twisty Pods from the bags and throwing them away.",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1E88"
        },
        [80060213] = {
          ContentFR = "Je l’ai arrêté net, et je lui ai dit que ces noisettes étaient délicieuses, que leur pellicule blanche, c’était juste du duvet naturel, pas de la moisissure !",
          DialogueId = 80060213,
          GUID = "C86C1EB2",
          NextDialogue = 80060214,
          SpeakNpcId = 95101,
          Subtitle = "I stopped him right there and explained those were perfectly good nuts — the white stuff was their natural fuzz, not mould.",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1EB2"
        },
        [80060214] = {
          ContentFR = "Et tu devineras jamais ce qu’il m’a répondu : il savait très bien qu’elles n’étaient pas abîmées, mais comme elles ne donnaient pas beaucoup d’huile, il les jetait !",
          DialogueId = 80060214,
          FacialId = {
            [1] = "95101:Unacceptable01"
          },
          GUID = "C86C1EDC",
          NextOptions = {
            [1] = 80060215
          },
          SpeakNpcId = 95101,
          Subtitle = "And guess what, he said he knew they weren't mouldy, but they weren't good for extracting oil, so he didn't want them!",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1EDC"
        },
        [80060215] = {
          ContentFR = "<I>Beaucoup d’huile... ?</>",
          DialogueId = 80060215,
          GUID = "C86C1F06",
          NextDialogue = 80060216,
          Subtitle = "Extracting oil...?"
        },
        [80060216] = {
          ContentFR = "Oui, ils ne voulaient pas ces noisettes pour manger ! Tu vas halluciner...",
          DialogueId = 80060216,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C1F30",
          NextDialogue = 80060217,
          SpeakNpcId = 95101,
          Subtitle = "Uh-huh! They didn't buy those nuts to eat! You won't believe this—",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1F30"
        },
        [80060217] = {
          ContentFR = "Le patron de ce majordome se baignait tous les jours dans du lait chaud, et le lait, c’était celui des plus grosses vaches du pâturage !",
          DialogueId = 80060217,
          FacialId = {
            [1] = "95101:Unacceptable01"
          },
          GUID = "C86C1F5A",
          NextDialogue = 80060218,
          SpeakNpcId = 95101,
          Subtitle = "He said his master's family bathe in boiled milk every day! And they only use milk from the healthiest cows on the farm!",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1F5A"
        },
        [80060218] = {
          ContentFR = "Et en plus, ils mettaient des parfums frais dans le bain au lait. Avant, c’était des pétales de tulipes, maintenant, ils veulent utiliser des huiles essentielles de noisettes !",
          DialogueId = 80060218,
          GUID = "C86C1F84",
          NextDialogue = 80060219,
          SpeakNpcId = 95101,
          Subtitle = "And that's not all — they'd add fresh perfume to the bath milk. They used to use tulip petals for the fragrance, and now they're switching to essential oil from nuts!",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1F84"
        },
        [80060219] = {
          ContentFR = "Les noisettes qu’on peut pas utiliser pour l’huile ? Direct à la poubelle, tu te rends compte !",
          DialogueId = 80060219,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C1FAE",
          NextOptions = {
            [1] = 80060220,
            [2] = 80060222
          },
          SpeakNpcId = 95101,
          Subtitle = "As for the nuts that couldn't be used for oil? Straight into the bin!",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C1FAE"
        },
        [80060220] = {
          ContentFR = "<I>Quel gâchis...</>",
          DialogueId = 80060220,
          GUID = "C86C1FD8",
          NextDialogue = 80060221,
          Subtitle = "That's so wasteful..."
        },
        [80060221] = {
          ContentFR = "Voilà, même si j’avais voulu fermer les yeux, Filbert aurait jamais accepté !",
          DialogueId = 80060221,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C2002",
          NextDialogue = 80060224,
          SpeakNpcId = 95101,
          Subtitle = "Exactly! And even if I could look the other way, Filbert wouldn't be okay with it!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2002"
        },
        [80060222] = {
          ContentFR = "<I>Ouah, se baigner dans du lait... la classe quand même...</>",
          DialogueId = 80060222,
          GUID = "C86C202C",
          NextDialogue = 80060223,
          Subtitle = "Hmm, bathe in milk... must be nice..."
        },
        [80060223] = {
          ContentFR = "Non, tu ne dois pas être {性别:jaloux|jalouse} ! Dans nos textes saints, gaspiller la nourriture, c’est un énorme péché ! Ils vont sûrement le payer cher !",
          DialogueId = 80060223,
          FacialId = {
            [1] = "95101:Confident01"
          },
          GUID = "C86C2056",
          NextDialogue = 80060224,
          SpeakNpcId = 95101,
          Subtitle = "Ah, don't say that! Our scriptures say wasting food is a huge sin! They'll get their comeuppance!",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2056"
        },
        [80060224] = {
          ContentFR = "J’ai balancé sa monnaie à la figure et j’ai récupéré mes noisettes. Je pouvais pas les laisser gaspiller ! Pour les dieux, le pire péché, c’est le gaspillage !",
          DialogueId = 80060224,
          GUID = "C86C2080",
          NextOptions = {
            [1] = 80060225,
            [2] = 80060227
          },
          SpeakNpcId = 95101,
          Subtitle = "I threw his money right back at him and took back my nuts. I just couldn't watch them waste food like that! According to the divine teachings, the worst sin is waste!",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2080"
        },
        [80060225] = {
          ContentFR = "<I>Tu as raison, Truffle. Gaspiller de la nourriture, c’est vraiment pas bien.</>",
          DialogueId = 80060225,
          GUID = "C86C20AA",
          NextDialogue = 80060226,
          Subtitle = "You're absolutely right, Truffle. Wasting food is bad."
        },
        [80060226] = {
          ContentFR = "Tu vois ! Gaspiller un seul petit truc, c’est un ventre de plus qui reste vide. Même un seul, c’est trop !",
          DialogueId = 80060226,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C20D4",
          NextDialogue = 80060231,
          SpeakNpcId = 95101,
          Subtitle = "Right? Every bit of wasted food could have filled a hungry belly. I can't let food go to waste! Not even a little bit!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C20D4"
        },
        [80060227] = {
          ContentFR = "<I>S’ils ont déjà payé, c’est leur droit de faire ce qu’ils veulent, non ?</>",
          DialogueId = 80060227,
          GUID = "C86C20FE",
          NextDialogue = 80060228,
          Subtitle = "But if they've already paid, isn't it their right to do as they please with their own stuff?"
        },
        [80060228] = {
          ContentFR = "Hein ? Ce n’est pas ce que les dieux enseignent... Mais ce que tu dis a du sens aussi... Pourtant, ça me chiffonne quand même...",
          DialogueId = 80060228,
          GUID = "C86C2128",
          NextDialogue = 80060229,
          SpeakNpcId = 95101,
          Subtitle = "Huh? That's not what the gods teach... Though what you said does make sense... But something still doesn't feel right...",
          TalkActionId = {
            [1] = "95101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2128"
        },
        [80060229] = {
          ContentFR = "Pfiou, c’est compliqué. S’ils ont le droit de gaspiller, alors j’ai le droit de ne pas leur vendre !",
          DialogueId = 80060229,
          FacialId = {
            [1] = "95101:Confident01"
          },
          GUID = "C86C2152",
          NextDialogue = 80060230,
          SpeakNpcId = 95101,
          Subtitle = "Ugh, so complicated. Well, if they have the right to waste their own food, then I have the right not to sell food to them!",
          TalkActionId = {
            [1] = "95101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2152"
        },
        [80060230] = {
          ContentFR = "Si ceux qui ont toujours à manger savaient qu’il y a encore des tas de gens qui vont se coucher le ventre vide...",
          DialogueId = 80060230,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C217C",
          NextDialogue = 80060231,
          SpeakNpcId = 95101,
          Subtitle = "If only those who never have to worry about food could see that there are still people starving out there...",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C217C"
        },
        [80060231] = {
          ContentFR = "Au final, j’ai peut-être perdu la commande et reçu une sacrée leçon de la prêtresse, mais j’ai donné toutes ces noisettes aux pauvres.",
          DialogueId = 80060231,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C21A6",
          NextDialogue = 80060232,
          SpeakNpcId = 95101,
          Subtitle = "Anyway — in the end, I got a lecture from a priestess for losing that order, but I still gave all those nuts to people in need.",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C21A6"
        },
        [80060232] = {
          ContentFR = "Je sais ce que ça fait d’avoir faim... c’est affreux ! Je veux plus jamais avoir faim, et je veux pas voir les autres souffrir comme ça.",
          DialogueId = 80060232,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C21D0",
          NextOptions = {
            [1] = 80060233
          },
          SpeakNpcId = 95101,
          Subtitle = "I know what starving feels like — it's awful! I never want that again, and I don't want to see anyone else starve.",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C21D0"
        },
        [80060233] = {
          ContentFR = "<I>Tu es vraiment gentille, Truffle.</>",
          DialogueId = 80060233,
          GUID = "C86C21FA",
          NextDialogue = 80060234,
          Subtitle = "You have a kind heart, Truffle."
        },
        [80060234] = {
          ContentFR = "<I>Soupir. </>J’ai l’impression qu’on est encore très loin, moi et Filbert, de notre rêve, que tout le monde ait enfin assez à manger...",
          DialogueId = 80060234,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C2224",
          NextDialogue = 80060235,
          SpeakNpcId = 95101,
          Subtitle = "*sigh*... It feels like there's still a loooong way to go before Filbert and I can achieve our dream of feeding everyone in the world.",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C2224"
        },
        [80060235] = {
          ContentFR = "Bon, pas le temps de traîner ! On repart avec Filbert chercher à manger ! On se revoit bientôt, et toi, n’oublie pas de bien manger, hein !",
          DialogueId = 80060235,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C224E",
          SpeakNpcId = 95101,
          Subtitle = "Well, I guess I should try even harder! I'm off to gather food with Filbert now! See you around — and don't forget to eat well!",
          VoiceName = "voice/$Locale$/inv/Songlu/002/C86C224E"
        },
        [80060301] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentFR = "Hé hé, le jus de Baies boréales en cette saison est vraiment le meilleur, pas du tout acide, tout doux, un vrai délice !",
          DialogueId = 80060301,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C2D22",
          LookAt = {
            [1] = "95101:p(18000P3)"
          },
          NextOptions = {
            [1] = 80060302
          },
          SpeakNpcId = 95101,
          Subtitle = "Hehe, borealberry juice is just the best this season — so sweet and refreshing, not sour at all. Yum yum!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2D22"
        },
        [80060302] = {
          ContentFR = "<I>Tant mieux si ça te plaît.</>",
          DialogueId = 80060302,
          GUID = "C86C2D4C",
          NextDialogue = 80060303,
          Subtitle = "Glad you like it."
        },
        [80060303] = {
          ContentFR = "Tu pourrais aussi me donner la recette ? Filbert serait tellement contente, elle sauterait de joie si elle pouvait goûter !",
          DialogueId = 80060303,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C2D76",
          NextOptions = {
            [1] = 80060304
          },
          SpeakNpcId = 95101,
          Subtitle = "Can I have the recipe? Filbert would love this too!",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2D76"
        },
        [80060304] = {
          ContentFR = "<I>Bien sûr.</>",
          DialogueId = 80060304,
          GUID = "C86C2DA0",
          NextDialogue = 80060305,
          Subtitle = "Sure."
        },
        [80060305] = {
          ContentFR = "{性别:Merci ! T’es vraiment trop... gentil, gé-né-reux, phil-an... philan-trope ? C’est comme ça qu’on dit ? En tout cas, t’es un vrai ange !|Merci ! T’es vraiment trop... gentille, gé-né-reuse, phil-an... philan-trope ? C’est comme ça qu’on dit ? En tout cas, t’es une vraie ange !}",
          DialogueId = 80060305,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C2DCA",
          NextDialogue = 80060306,
          SpeakNpcId = 95101,
          Subtitle = "Thank you! You're so benevolent and phillan... phillan-thropic — did I get that right? Anyway, you're an angel!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2DCA"
        },
        [80060306] = {
          ContentFR = "Avant, Filbert et moi, on allait souvent cueillir des Baies boréales. Il suffisait de les tordre doucement, et elles tombaient dans la paume de la main. Je remplissais toujours plusieurs grands paniers, et Filbert était toute joyeuse de les rapporter.",
          DialogueId = 80060306,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C2DF4",
          NextDialogue = 80060307,
          SpeakNpcId = 95101,
          Subtitle = "Filbert and I used to pick borealberries very often. Just a little twist, and they'd fall into my hands. I'd fill baskets full of them, and Filbert was always so happy hauling them back.",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2DF4"
        },
        [80060307] = {
          ContentFR = "Une fois, on en a mangé tellement que nos langues et nos lèvres sont devenues toutes violettes. On a essayé de se rincer à la rivière, mais ça ne partait pas.",
          DialogueId = 80060307,
          GUID = "C86C2E1E",
          NextDialogue = 80060308,
          SpeakNpcId = 95101,
          Subtitle = "One time, we ate so many our tongues and lips turned purple! We spent a lot of time washing our mouths by the stream, but the colour just wouldn't come off.",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2E1E"
        },
        [80060308] = {
          ContentFR = "Filbert, paniquée, a sauté dans la rivière pour se laver, et un crabe caché sous un caillou lui a pincé la patte, elle a eu super mal et elle a gémi. Je me suis précipitée pour la sauver, et là, surprise, un autre crabe énorme nous attendait sous les pierres...",
          DialogueId = 80060308,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C2E48",
          NextDialogue = 80060309,
          SpeakNpcId = 95101,
          Subtitle = "Filbert got so upset she jumped into the stream to wash up, and then a crab under the pebbles pinched her foot — it hurt so much she whimpered. So I jumped right in to save her, and guess what — there was another crab, a really big one...",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2E48"
        },
        [80060309] = {
          ContentFR = "Au final, on est rentrées toutes trempées, en boitant, avec nos visages tachés de violet. La prêtresse McGuffin nous a soignées en nous grondant sévèrement.",
          DialogueId = 80060309,
          GUID = "C86C2E72",
          NextDialogue = 80060310,
          SpeakNpcId = 95101,
          Subtitle = "We both ended up soaking wet, limping back with teary, purple-stained faces. Priestess McGuffin patched us up, all the while giving us a good scolding.",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2E72"
        },
        [80060310] = {
          ContentFR = "Depuis ce jour, chaque fois que Filbert passe près d’un buisson à baies, elle les regarde avec envie, mais elle n’ose plus jamais en manger.",
          DialogueId = 80060310,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C2E9C",
          NextOptions = {
            [1] = 80060311
          },
          SpeakNpcId = 95101,
          Subtitle = "Since then, every time Filbert passes a berry bush, she just eyes those borealberries eagerly but never dares to nibble at one.",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2E9C"
        },
        [80060311] = {
          ContentFR = "<I>Cette prêtresse McGuffin... vous avez peur d’elle ?</>",
          DialogueId = 80060311,
          GUID = "C86C2EC6",
          NextDialogue = 80060312,
          Subtitle = "Are you two scared of Priestess McGuffin?"
        },
        [80060312] = {
          ContentFR = "Moi pas trop ! Mais Filbert, chaque fois qu’elle la voit, elle tremble. Je crois que c’est parce qu’au début, elle la menaçait souvent de la mettre dehors.",
          DialogueId = 80060312,
          FacialId = {
            [1] = "95101:Iyada01"
          },
          GUID = "C86C2EF0",
          NextDialogue = 80060313,
          SpeakNpcId = 95101,
          Subtitle = "I'm not. But Filbert shivers whenever she's around, probably because she threatened to kick her out when we first came.",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2EF0"
        },
        [80060313] = {
          ContentFR = "Quand la prêtresse McGuffin m’a prise sous son aile, elle craignait que Filbert ne dévore toute la nourriture de l’église et laisse les autres sans rien à manger.",
          DialogueId = 80060313,
          GUID = "C86C2F1A",
          NextDialogue = 80060340,
          SpeakNpcId = 95101,
          Subtitle = "When Priestess McGuffin first took me in, she was worried that Filbert would eat up all the food in the church and leave everyone else hungry.",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2F1A"
        },
        [80060314] = {
          ContentFR = "Prêtresse McGuffin a fini par accepter de la garder, mais elle ne cesse de se plaindre que Filbert n’est pas assez cool. Elle dit des trucs comme...",
          DialogueId = 80060314,
          GUID = "C86C2F44",
          NextDialogue = 80060315,
          SpeakNpcId = 95101,
          Subtitle = "Priestess McGuffin eventually agreed to keep Filbert, though she still complains Filbert isn't cool enough. She'd say things like—",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2F44"
        },
        [80060315] = {
          ContentFR = "« Petite Truffle, regarde ce roman hyperboréen. Il raconte l’histoire d’un héros qui se lie d’amitié avec un dragon. Pourquoi leurs compagnons animaux sont-ils tous si impressionnants, alors que toi, tu n’as qu’un simple cochon ? »",
          DialogueId = 80060315,
          GUID = "C86C2F6E",
          NextDialogue = 80060316,
          SpeakNpcId = 95101,
          Subtitle = "\"Little Truffle, have you read this Hyperborean novel about a hero who befriends a dragon? Why do they get such cool animal friends, and we just have a pig?\"",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2F6E"
        },
        [80060316] = {
          ContentFR = "« Et ce livre, écrit par un auteur de Huaxu, bien qu’il ait aussi un cochon... le leur est un général céleste venu du paradis, capable d’aider à combattre les monstres. Notre cochon a-t-il des pouvoirs spéciaux ? »",
          DialogueId = 80060316,
          GUID = "C86C2F98",
          NextOptions = {
            [1] = 80060317,
            [2] = 80060319,
            [3] = 80060320
          },
          SpeakNpcId = 95101,
          Subtitle = "\"And here's another novel by a Huaxu writer — they have a pig too, but theirs is a celestial general who fights monsters! Does our pig have any special powers?\"",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2F98"
        },
        [80060317] = {
          ContentFR = "<I>Elle n’a pas tort, tu devrais trouver un compagnon plus cool.</>",
          DialogueId = 80060317,
          GUID = "C86C2FC2",
          NextDialogue = 80060318,
          Subtitle = "Maybe she has a point. You should find a cooler companion."
        },
        [80060318] = {
          ContentFR = "Non, non ! Je ne pourrais jamais abandonner Filbert !",
          DialogueId = 80060318,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C2FEC",
          NextOptions = {
            [1] = 80060322
          },
          SpeakNpcId = 95101,
          Subtitle = "Nuh-uh! I would never leave Filbert!",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2FEC"
        },
        [80060319] = {
          ContentFR = "<I>Elle se trompe, Filbert est irremplaçable.</>",
          DialogueId = 80060319,
          GUID = "C86C3016",
          NextDialogue = 80060321,
          Subtitle = "She's wrong. Filbert is irreplaceable."
        },
        [80060320] = {
          ContentFR = "<I>Ne l’écoute pas, c’est super cool de monter un cochon !</>",
          DialogueId = 80060320,
          GUID = "C86C3040",
          NextDialogue = 80060321,
          Subtitle = "Don't listen to her — riding a pig is super cool!"
        },
        [80060321] = {
          ContentFR = "Ouah, toi aussi tu le penses ? Tu es trop {性别:génial|géniale}, que les dieux de la vie, de l’abondance, des baies boréales, des patates... enfin tous les dieux te bénissent !",
          DialogueId = 80060321,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C306A",
          NextOptions = {
            [1] = 80060322
          },
          SpeakNpcId = 95101,
          Subtitle = "Wow, you really think so? You're the best! May the Gods of Life, Bounty, Borealberry, Burrowing Botato — any gods there are — bless you!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C306A"
        },
        [80060322] = {
          ContentFR = "<I>Tu aimes vraiment Filbert, elle doit être très spéciale.</>",
          DialogueId = 80060322,
          GUID = "C86C3094",
          NextDialogue = 80060323,
          Subtitle = "You really like Filbert. She must be very special."
        },
        [80060323] = {
          ContentFR = "Spéciale ? Oui, c’est sûr. Mais dis-moi, {nickname}, pourquoi penses-tu ça, toi ?",
          DialogueId = 80060323,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C30BE",
          NextOptions = {
            [1] = 80060324,
            [2] = 80060326
          },
          SpeakNpcId = 95101,
          Subtitle = "Special? She sure is! But I'm curious — why would you think so, ?",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C30BE"
        },
        [80060324] = {
          ContentFR = "<I>Parce que Filbert court très vite.</>",
          DialogueId = 80060324,
          GUID = "C86C30E8",
          NextDialogue = 80060325,
          Subtitle = "Because Filbert runs very fast."
        }
      }
    end
  },
  {
    MinKey = 80060325,
    MaxKey = 80080124,
    Loader = function()
      return {
        [80060325] = {
          ContentFR = "En fait, beaucoup de Géniemon courent vite, et plein de vrais cochons aussi. Filbert est loin d’être la plus rapide.",
          DialogueId = 80060325,
          FacialId = {
            [1] = "95101:Smile01"
          },
          GUID = "C86C3112",
          NextDialogue = 80060328,
          SpeakNpcId = 95101,
          Subtitle = "Actually, all Geniemons are pretty fast. Many wild pigs can also do the same. And compared to them, Filbert isn't even close.",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C3112"
        },
        [80060326] = {
          ContentFR = "<I>Parce que Filbert sait trouver de la nourriture.</>",
          DialogueId = 80060326,
          GUID = "C86C313C",
          NextDialogue = 80060327,
          Subtitle = "Because Filbert can find lots of food."
        },
        [80060327] = {
          ContentFR = "Elle utilise son nez pour chercher les Chapeaux-de-Rubis. En fait, beaucoup de Géniemon ont un bon flair, si on leur demande gentiment, ils peuvent aussi t’aider à trouver de la nourriture.",
          DialogueId = 80060327,
          FacialId = {
            [1] = "95101:Smile01"
          },
          GUID = "C86C3166",
          NextDialogue = 80060328,
          SpeakNpcId = 95101,
          Subtitle = "She uses her nose to sniff out food in the wild. Actually, all Geniemons have sharp noses. If you ask them nicely, they could help you find food too.",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C3166"
        },
        [80060328] = {
          ContentFR = "J’ai beaucoup réfléchi à cette question, surtout après que la prêtresse McGuffin me l’ait posée.",
          DialogueId = 80060328,
          GUID = "C86C3190",
          NextDialogue = 80060329,
          SpeakNpcId = 95101,
          Subtitle = "Actually, I've really thought about this after Priestess McGuffin asked me.",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C3190"
        },
        [80060329] = {
          ContentFR = "Dans ce monde, il y a tellement de Géniemon, beaux, mignons... alors pourquoi Filbert ?",
          DialogueId = 80060329,
          GUID = "C86C31BA",
          NextDialogue = 80060330,
          SpeakNpcId = 95101,
          Subtitle = "I once wondered, among all Geniemons out there, why must it be Filbert?",
          TalkActionId = {
            [1] = "95101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C31BA"
        },
        [80060330] = {
          ContentFR = "Mais je n’y ai pensé qu’une nuit. Le lendemain matin, quand Filbert a frotté son nez contre mon visage pour me réveiller, j’ai tout compris.",
          DialogueId = 80060330,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C31E4",
          NextDialogue = 80060331,
          SpeakNpcId = 95101,
          Subtitle = "But I only thought about it for one night. The next morning, when Filbert nuzzled my face to wake me up, it suddenly all made sense.",
          TalkActionId = {
            [1] = "95101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C31E4"
        },
        [80060331] = {
          ContentFR = "Parce que c’est seulement Filbert... ma Filbert ! Celle qui m’aide à creuser les champignons dans la boue, qui porte les lourdes provisions à distribuer, qui me suit pour remettre les méchants à leur place...",
          DialogueId = 80060331,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C320E",
          NextDialogue = 80060332,
          SpeakNpcId = 95101,
          Subtitle = "Because only Filbert... is my Filbert! The one who helps me dig for mushrooms, carry bags of food handouts, and fight against bullies...",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C320E"
        },
        [80060332] = {
          ContentFR = "Celle qui récite avec moi les écritures que j’arrive jamais à mémoriser, qui me console quand je suis malade, et qui court avec moi au petit matin ou au crépuscule.",
          DialogueId = 80060332,
          GUID = "C86C3238",
          NextOptions = {
            [1] = 80060333
          },
          SpeakNpcId = 95101,
          Subtitle = "She's always been there for me — when I stumble through scriptures, when I get sick, and when I run around on errands.",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C3238"
        },
        [80060333] = {
          ContentFR = "<I>C’est parce que vous avez partagé plein de petits moments ensemble qu’elle est spéciale ?</>",
          DialogueId = 80060333,
          GUID = "C86C3262",
          NextDialogue = 80060334,
          Subtitle = "So it's the many little moments you've shared together that make Filbert so special?"
        },
        [80060334] = {
          ContentFR = "Oui ! Même si beaucoup pensent que Filbert n’est pas cool, même s’il y a plein d’autres Géniemon qui courent plus vite, sont plus jolis, ou ramassent plus de champignons... même si Filbert n’est qu’un simple petit cochon ordinaire...",
          DialogueId = 80060334,
          FacialId = {
            [1] = "95101:Happy01"
          },
          GUID = "C86C328C",
          NextDialogue = 80060335,
          SpeakNpcId = 95101,
          Subtitle = "Exactly! Even though many people think Filbert is not cool, and even though there are many Geniemons in this world that run faster, look cuter, and dig up more mushrooms than Filbert... even if Filbert is just an ordinary pig...",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C328C"
        },
        [80060335] = {
          ContentFR = "Filbert reste la seule et unique Filbert au monde, et la meilleure partenaire de Truffle, la Commissaire au Ravitaillement !",
          DialogueId = 80060335,
          GUID = "C86C32B6",
          NextOptions = {
            [1] = 80060336
          },
          SpeakNpcId = 95101,
          Subtitle = "Filbert is still the one and only in the world — Commissary Truffle's best partner!",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C32B6"
        },
        [80060336] = {
          ContentFR = "<I>Ah oui, je me souviens, c’est la \"Commissaire d’élite au Ravitaillement\".</>",
          DialogueId = 80060336,
          GUID = "C86C32E0",
          NextDialogue = 80060337,
          Subtitle = "Right, I remember she's the Special Commissary."
        },
        [80060337] = {
          ContentFR = "Exact ! Truffle et Filbert ensemble, pour chasser la faim...",
          DialogueId = 80060337,
          GUID = "C86C330A",
          NextDialogue = 80060338,
          SpeakNpcId = 95101,
          Subtitle = "Right! Truffle and Filbert together, fighting hunger—",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C330A"
        },
        [80060338] = {
          ContentFR = "Ah ! J’ai failli oublier, je n’ai pas encore distribué les vivres collectées aujourd’hui...",
          DialogueId = 80060338,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C3334",
          NextDialogue = 80060339,
          SpeakNpcId = 95101,
          Subtitle = "Ah! I almost forgot — I haven't divvied up today's food.",
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C3334"
        },
        [80060339] = {
          ContentFR = "Je dois filer, {nickname}. À la prochaine !",
          DialogueId = 80060339,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C335E",
          SpeakNpcId = 95101,
          Subtitle = "I have to go now, . See you next time!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C335E"
        },
        [80060340] = {
          ContentFR = "Mais ils ont vite réalisé que même si Filbert ressemble à un cochon, elle n’a pas un appétit démesuré et ne mange pas beaucoup.",
          DialogueId = 80060340,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C2F1B",
          NextDialogue = 80060314,
          SpeakNpcId = 95101,
          Subtitle = "But it didn't take long for them to realize that she didn't share a pig's voracious appetite and wouldn't devour large amounts of food.",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/003/C86C2F1B"
        },
        [80060401] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentFR = "{nickname} ! Euh... j’ai une question super importante ! Tu peux me répondre tout de suite ?",
          DialogueId = 80060401,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C3D8A",
          LookAt = {
            [1] = "95101:p(18000P3)"
          },
          NextOptions = {
            [1] = 80060402
          },
          SpeakNpcId = 95101,
          Subtitle = "! I... I have a really important question! Can you answer it right now?",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3D8A"
        },
        [80060402] = {
          ContentFR = "<I>Bien sûr. Qu'y a-t-il ?</>",
          DialogueId = 80060402,
          GUID = "C86C3DB4",
          NextDialogue = 80060403,
          Subtitle = "Sure. What is it?"
        },
        [80060403] = {
          ContentFR = "Je me demande... si on peut manger à sa faim tous les jours, est-ce qu’on est forcément heureux ?",
          DialogueId = 80060403,
          GUID = "C86C3DDE",
          NextOptions = {
            [1] = 80060404,
            [2] = 80060405
          },
          SpeakNpcId = 95101,
          Subtitle = "I'm wondering — would you be happy if you get to fill yourself up every day?",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3DDE"
        },
        [80060404] = {
          ContentFR = "<I>Bien sûr !</>",
          DialogueId = 80060404,
          GUID = "C86C3E08",
          NextDialogue = 80060406,
          Subtitle = "Of course."
        },
        [80060405] = {
          ContentFR = "<I>Je sais pas trop...</>",
          DialogueId = 80060405,
          GUID = "C86C3E32",
          NextDialogue = 80060406,
          Subtitle = "Mm, I don't know."
        },
        [80060406] = {
          ContentFR = "Alors... est-ce que, pour toi, manger à ta faim chaque jour suffit à te rendre {性别:heureux|heureuse} ?",
          DialogueId = 80060406,
          FacialId = {
            [1] = "95101:Satisfy01"
          },
          GUID = "C86C3E5C",
          NextOptions = {
            [1] = 80060407,
            [2] = 80060409
          },
          SpeakNpcId = 95101,
          Subtitle = "Then I have another question — is just being able to fill yourself up every day enough to make you happy?",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3E5C"
        },
        [80060407] = {
          ContentFR = "<I>Bah oui, quand on est rassasié, pourquoi être malheureux ?</>",
          DialogueId = 80060407,
          GUID = "C86C3E86",
          NextDialogue = 80060408,
          Subtitle = "Uh-huh. What's there to be upset about when you're full?"
        },
        [80060408] = {
          ContentFR = "C’est ça, c’est ça ! Remplir son ventre, c’est la chose la plus importante.",
          DialogueId = 80060408,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C3EB0",
          NextDialogue = 80060411,
          SpeakNpcId = 95101,
          Subtitle = "Exactly! There's nothing more important than a full belly!",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3EB0"
        },
        [80060409] = {
          ContentFR = "<I>Pas vraiment, y’a plein d’autres choses qui posent problème.</>",
          DialogueId = 80060409,
          GUID = "C86C3EDA",
          NextDialogue = 80060410,
          Subtitle = "Nah, there's plenty of stuff to worry about."
        },
        [80060410] = {
          ContentFR = "Ah bon ? Alors on est un peu différents, non ? ",
          DialogueId = 80060410,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C3F04",
          NextDialogue = 80060411,
          SpeakNpcId = 95101,
          Subtitle = "Huh? Really? We might be different then.",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3F04"
        },
        [80060411] = {
          ContentFR = "Moi, tant que je mange à ma faim tous les jours, ça me rend heureuse. Mais j’ai deux amis qui sont complètement différents, et ça me rend un peu confuse.",
          DialogueId = 80060411,
          GUID = "C86C3F2E",
          NextDialogue = 80060412,
          SpeakNpcId = 95101,
          Subtitle = "For me, as long as I get to fill my belly every day, I'm happy. But I have two friends who don't feel the same way at all, so I'm a bit confused.",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3F2E"
        },
        [80060412] = {
          ContentFR = "Il y en a une qui vient d’une riche famille de marchands, elle habite à la campagne, avec plein de bijoux brillants qui valent plein d’argent. Elle peut se payer des tas de chefs extraordinaires qui lui préparent une montagne de bons petits plats.",
          DialogueId = 80060412,
          FacialId = {
            [1] = "95101:Doubt01"
          },
          GUID = "C86C3F58",
          NextDialogue = 80060413,
          SpeakNpcId = 95101,
          Subtitle = "One is a lady from a rich merchant family. She lives out in the suburbs, and has loads of shiny gems that can be traded for tons of silver coins; she can easily afford to hire lots of amazing chefs to make as much delicious food as she wants.",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3F58"
        },
        [80060413] = {
          ContentFR = "Mais même comme ça, elle n’est pas joyeuse. La prêtresse m’a dit que c’est parce qu’elle doit déménager loin, dans une ville qu’elle n’aime pas, pour vivre avec quelqu’un qu’elle ne connaît pas.",
          DialogueId = 80060413,
          GUID = "C86C3F82",
          NextDialogue = 80060414,
          SpeakNpcId = 95101,
          Subtitle = "But she's still not happy. One priestess told me it's because she has to move far away to a city she doesn't like, to live with someone she doesn't even know.",
          TalkActionId = {
            [1] = "95101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3F82"
        },
        [80060414] = {
          ContentFR = "Et puis il y a un autre ami, le plus fervent croyant de notre église. Il a échangé tout ce qu’il avait économisé en nourriture pendant un mois contre un nouveau recueil de textes sacrés à l’autel.",
          DialogueId = 80060414,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C3FAC",
          NextDialogue = 80060415,
          SpeakNpcId = 95101,
          Subtitle = "And the other one's the most devout follower in our church. He traded all the food he saved up for a month for a new set of scriptures at the shrine.",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3FAC"
        },
        [80060415] = {
          ContentFR = "Je veux dire... ça ne le fait pas mourir de faim ? Il est tout maigre, on dirait que le vent pourrait l’emporter comme une feuille ! Mais lui, il dit que lire ces textes « nourrit son âme » !",
          DialogueId = 80060415,
          GUID = "C86C3FD6",
          NextDialogue = 80060416,
          SpeakNpcId = 95101,
          Subtitle = "I mean, isn't that crazy? Wouldn't he end up starving because of that? He's always been so thin — the wind can easily carry him away like a leaf! But he says that reading the scriptures \"feeds his soul\"!",
          TalkActionId = {
            [1] = "95101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C3FD6"
        },
        [80060416] = {
          ContentFR = "Je ne comprends pas... pourquoi ils sont si différents de moi ?",
          DialogueId = 80060416,
          FacialId = {
            [1] = "95101:Iyada01"
          },
          GUID = "C86C4000",
          NextDialogue = 80060417,
          SpeakNpcId = 95101,
          Subtitle = "I just don't get it... Why are they so different from me?",
          TalkActionId = {
            [1] = "95101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4000"
        },
        [80060417] = {
          ContentFR = "Pourquoi certaines personnes ne sont pas heureuses même en étant rassasiées, et d’autres trouvent le bonheur même quand elles ont faim ?",
          DialogueId = 80060417,
          GUID = "C86C402A",
          NextDialogue = 80060418,
          SpeakNpcId = 95101,
          Subtitle = "Why are some people still upset even when they're full? And why are some happy even when they're starving?",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C402A"
        },
        [80060418] = {
          ContentFR = "Dans les textes sacrés, les dieux disent qu’on doit tous essayer de rendre les autres heureux... mais comment faire pour que tout le monde soit content ?",
          DialogueId = 80060418,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C4054",
          NextOptions = {
            [1] = 80060419,
            [2] = 80060420
          },
          SpeakNpcId = 95101,
          Subtitle = "The scriptures say we should all try to make others happy... but how can I make EVERYONE happy?",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4054"
        },
        [80060419] = {
          ContentFR = "<I>Les cœurs humains sont compliqués, chacun pense différemment.</>",
          DialogueId = 80060419,
          GUID = "C86C407E",
          NextDialogue = 80060421,
          Subtitle = "Human hearts are quite complicated. Everyone feels different."
        },
        [80060420] = {
          ContentFR = "<I>Tu ne peux pas rendre tout le monde heureux, les textes sacrés sont absurdes.</>",
          DialogueId = 80060420,
          GUID = "C86C40A8",
          NextDialogue = 80060421,
          Subtitle = "You can't make everyone happy; that's just nonsense in the scriptures."
        },
        [80060421] = {
          ContentFR = "Comment ça ? Je comprends pas trop...",
          DialogueId = 80060421,
          FacialId = {
            [1] = "95101:Iyada01"
          },
          GUID = "C86C40D2",
          NextDialogue = 80060422,
          SpeakNpcId = 95101,
          Subtitle = "What do you mean? I don't get it...",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C40D2"
        },
        [80060422] = {
          ContentFR = "Quand les gens sont tristes, ils pleurent, quand ils sont heureux, ils rient, quand ils sont en colère, ils râlent, et quand ils ont faim, ils mangent... c’est pas compliqué, non ?",
          DialogueId = 80060422,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C40FC",
          NextOptions = {
            [1] = 80060423
          },
          SpeakNpcId = 95101,
          Subtitle = "People cry when they're sad, laugh when they're happy, yell when they're upset, and eat when they're hungry... What's so complicated about that?",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C40FC"
        },
        [80060423] = {
          ContentFR = "<I>Filbert aime bien boire du jus de coriandre, non ?</>",
          DialogueId = 80060423,
          GUID = "C86C4126",
          NextDialogue = 80060424,
          Subtitle = "Filbert loves coriander juice, right?"
        },
        [80060424] = {
          ContentFR = "Oui ! La prêtresse lui prépare du jus de coriandre frais tous les jours !",
          DialogueId = 80060424,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C4150",
          NextOptions = {
            [1] = 80060425
          },
          SpeakNpcId = 95101,
          Subtitle = "Mm-hmm! The priestesses make fresh coriander juice for Filbert every day!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4150"
        },
        [80060425] = {
          ContentFR = "<I>Et toi, tu aimes la coriandre ?</>",
          DialogueId = 80060425,
          GUID = "C86C417A",
          NextDialogue = 80060426,
          Subtitle = "What about you, Truffle? Do you like coriander?"
        },
        [80060426] = {
          ContentFR = "La coriandre, c’est bizarre... ça fait un goût amer au fond de la langue, mais ça sent aussi un truc étrange... si je me pince le nez, ça va... Ah, je comprends maintenant !",
          DialogueId = 80060426,
          FacialId = {
            [1] = "95101:Sad01"
          },
          GUID = "C86C41A4",
          NextDialogue = 80060427,
          SpeakNpcId = 95101,
          Subtitle = "Mmm, coriander tastes weird — bitter on the tongue but strangely fragrant... I can only eat it if I hold my nose... Ah, I get it now!",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C41A4"
        },
        [80060427] = {
          ContentFR = "Il y en a qui adorent le goût du lait de noisette, d’autres qui ne peuvent pas le sentir, Filbert aime la coriandre mais moi non... Du coup, ce qui rend les gens heureux, ça n’est pas pareil pour tout le monde.",
          DialogueId = 80060427,
          GUID = "C86C41CE",
          NextDialogue = 80060428,
          SpeakNpcId = 95101,
          Subtitle = "Some people love hazelnut milk, but others hate its smell; Filbert loves coriander, but I don't... Our happiness comes from different things...",
          TalkActionId = {
            [1] = "95101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C41CE"
        },
        [80060428] = {
          ContentFR = "Je comprends... mes amis riches doivent être comme ça aussi, il y a des choses plus importantes que de bien manger pour eux, alors ils peuvent même supporter la faim.",
          DialogueId = 80060428,
          FacialId = {
            [1] = "95101:Unhappy01"
          },
          GUID = "C86C41F8",
          NextDialogue = 80060429,
          SpeakNpcId = 95101,
          Subtitle = "I see... For the two friends of mine, there are things that make them much happier than a full belly makes them, so they don't mind starving.",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C41F8"
        },
        [80060429] = {
          ContentFR = "Alors... qu’est-ce que je peux faire, moi ?",
          DialogueId = 80060429,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C4222",
          NextOptions = {
            [1] = 80060430,
            [2] = 80060434
          },
          SpeakNpcId = 95101,
          Subtitle = "Then... what can I do for everyone?",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4222"
        },
        [80060430] = {
          ContentFR = "<I>Tu remplis déjà plein de ventres, c’est un travail formidable.</>",
          DialogueId = 80060430,
          GUID = "C86C424C",
          NextDialogue = 80060431,
          Subtitle = "You're already doing an amazing thing by filling so many people's bellies."
        },
        [80060431] = {
          ContentFR = "Vraiment ? Est-ce que j’ai déjà rendu beaucoup de gens heureux ?",
          DialogueId = 80060431,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C4276",
          NextDialogue = 80060432,
          SpeakNpcId = 95101,
          Subtitle = "Really? Have I already made a lot of people happy?",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4276"
        },
        [80060432] = {
          ContentFR = "Oui. Pour beaucoup, manger à sa faim ne suffit pas forcément à être heureux, mais avoir faim, c’est sûr que c’est malheureux.",
          DialogueId = 80060432,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C42A0",
          NextDialogue = 80060433,
          SpeakNpcId = 10001,
          Subtitle = "Yes. Being full might not necessarily mean happiness for everyone, but starving certainly means misery.",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C42A0"
        },
        [80060433] = {
          ContentFR = "Merci ! Tu es tellement {性别:gentil|gentille} ! Même si aujourd’hui je suis tombée d’un arbre en cueillant des fruits, ça ne me fait plus mal grâce à toi !",
          DialogueId = 80060433,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C42CA",
          NextDialogue = 80060438,
          SpeakNpcId = 95101,
          Subtitle = "Thank you! You're so sweet! I fell from a tree picking plums today, but your nice words just made the pain go away!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C42CA"
        },
        [80060434] = {
          ContentFR = "<I>Tu ne peux pas rendre tout le monde heureux, commence déjà par être heureuse toi-même.</>",
          DialogueId = 80060434,
          GUID = "C86C42F4",
          NextDialogue = 80060435,
          Subtitle = "You can't attend to everyone; just focus on making yourself happy."
        },
        [80060435] = {
          ContentFR = "Moi, être heureuse ? Voyons voir...",
          DialogueId = 80060435,
          GUID = "C86C431E",
          NextDialogue = 80060436,
          SpeakNpcId = 95101,
          Subtitle = "Stuff that makes me happy? Hmm, let's see...",
          TalkActionId = {
            [1] = "95101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C431E"
        },
        [80060436] = {
          ContentFR = "Je suis contente quand je vois tout le monde manger à sa faim, quand la prêtresse me félicite et me caresse la tête, quand Filbert me frotte le nez, et... et... parler avec toi, ça me rend aussi heureuse !",
          DialogueId = 80060436,
          FacialId = {
            [1] = "95101:Happy01"
          },
          GUID = "C86C4348",
          NextDialogue = 80060437,
          SpeakNpcId = 95101,
          Subtitle = "I feel happy when I see everyone well-fed, when some priestess pats my head and says I did a good job, when Filbert nuzzles me with her snout, and... oh! Sitting here chatting with you makes me happy too!",
          TalkActionId = {
            [1] = "95101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4348"
        },
        [80060437] = {
          ContentFR = "Alors, si c’est ça... je peux juste continuer à faire ce que je fais ?",
          DialogueId = 80060437,
          GUID = "C86C4372",
          NextDialogue = 80060438,
          SpeakNpcId = 95101,
          Subtitle = "So you're saying... I just keep doing what I'm already doing, and that's enough?",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4372"
        },
        [80060438] = {
          ContentFR = "...",
          DialogueId = 80060438,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C439C",
          NextDialogue = 80060439,
          SpeakNpcId = 95101,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C439C"
        },
        [80060439] = {
          ContentFR = "Tu es quelqu’un de très {性别:intelligent|intelligente}, et moi je suis un peu bête. Si toi tu ne sais pas comment rendre tout le monde heureux, je ne trouverai jamais.",
          DialogueId = 80060439,
          FacialId = {
            [1] = "95101:Sad02"
          },
          GUID = "C86C43C6",
          NextDialogue = 80060440,
          SpeakNpcId = 95101,
          Subtitle = "Well... you're smart, and I'm just silly. If even you don't know how to make everyone happy, then I certainly can't figure it out.",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C43C6"
        },
        [80060440] = {
          ContentFR = "Mais j’ai décidé de continuer à être la meilleure commissaire au ravitaillement !",
          DialogueId = 80060440,
          FacialId = {
            [1] = "95101:None"
          },
          GUID = "C86C43F0",
          NextDialogue = 80060441,
          SpeakNpcId = 95101,
          Subtitle = "But I've made up my mind — I'll keep doing my best as a commissary!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C43F0"
        },
        [80060441] = {
          ContentFR = "Peut-être que je ne peux pas rendre tout le monde heureux, mais si en remplissant leur ventre, je peux leur apporter un peu plus de bonheur, alors je n’aurai pas déçu les dieux, non ?",
          DialogueId = 80060441,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C441A",
          NextOptions = {
            [1] = 80060442
          },
          SpeakNpcId = 95101,
          Subtitle = "Maybe I can't make everyone happy. But if filling their bellies makes them even a tiny bit happier, then I'm not failing the teachings of the gods, am I?",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C441A"
        },
        [80060442] = {
          ContentFR = "<I>Oui, c’est une noble mission.</>",
          DialogueId = 80060442,
          GUID = "C86C4444",
          NextDialogue = 80060443,
          Subtitle = "Right, it's a noble cause."
        },
        [80060443] = {
          ContentFR = "Hé hé... merci ! Il y a tant de choses que je ne comprends pas dans ce monde. Si je suis perdue, je peux toujours venir te demander de l’aide, hein ?",
          DialogueId = 80060443,
          GUID = "C86C446E",
          NextOptions = {
            [1] = 80060444,
            [2] = 80060446
          },
          SpeakNpcId = 95101,
          Subtitle = "Hehe... Thank you! There's so much in this world I don't understand. If I ever get confused about anything, can I still come to you?",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C446E"
        },
        [80060444] = {
          ContentFR = "<I>Bien sûr !</>",
          DialogueId = 80060444,
          GUID = "C86C4498",
          NextDialogue = 80060445,
          Subtitle = "Any time."
        },
        [80060445] = {
          ContentFR = "Youpi !",
          DialogueId = 80060445,
          FacialId = {
            [1] = "95101:Happy02"
          },
          GUID = "C86C44C2",
          NextDialogue = 80060449,
          SpeakNpcId = 95101,
          Subtitle = "You're the best!",
          TalkActionId = {
            [1] = "95101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C44C2"
        },
        [80060446] = {
          ContentFR = "<I>Une question, une noisette !</>",
          DialogueId = 80060446,
          GUID = "C86C44EC",
          NextDialogue = 80060447,
          Subtitle = "Then I want one filbert for one question."
        },
        [80060447] = {
          ContentFR = "Hein ? Mais je peux pas te donner Filbert ! Elle est pas comestible, même avec du sucre dessus...",
          DialogueId = 80060447,
          FacialId = {
            [1] = "95101:Shock01"
          },
          GUID = "C86C4516",
          NextDialogue = 80060448,
          SpeakNpcId = 95101,
          Subtitle = "Ah, I can't do that. Filbert would be scared without me by her side...",
          TalkActionId = {
            [1] = "95101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4516"
        },
        [80060448] = {
          ContentFR = "Aaaah, tu parlais d’une vraie noisette ? Pas de souci ! Je t’en apporterai plein, pour que ton ventre soit bien rempli !",
          DialogueId = 80060448,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C4540",
          NextDialogue = 80060449,
          SpeakNpcId = 95101,
          Subtitle = "Oh, you meant the nut — sure! I'll bring you loads of filberts to fill you up!",
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C4540"
        },
        [80060449] = {
          ContentFR = "Alors, c’est un marché ! Tu seras {性别:le consultant officiel|la consultante officielle} de la grande mission de Truffle et Filbert, petit doigt levé, on scelle le pacte !",
          DialogueId = 80060449,
          FacialId = {
            [1] = "95101:Smile02"
          },
          GUID = "C86C456A",
          SpeakNpcId = 95101,
          Subtitle = "It's a deal then. You'll be the official consultant for the great cause of Truffle and Filbert — pinky promise!",
          TalkActionId = {
            [1] = "95101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Songlu/004/C86C456A"
        },
        [80070101] = {
          Camera = "-108.692429,383.760162,74.947266,0.000002,8.799756,-69.59346,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Commandante Sibylle, j’ai nettoyé le bureau que vous utilisiez auparavant.",
          DialogueId = 80070101,
          GUID = "C87274F2",
          NextDialogue = 80070102,
          SpeakNpcId = 790014,
          Subtitle = "Chief Sibylle, I've cleaned up the office you were using before.",
          TalkActionId = {
            [1] = "790014:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87274F2"
        },
        [80070102] = {
          ContentFR = "Hum. Considère ça comme l’un des avantages de ta promotion au grade de major. Ce sera désormais ton bureau.",
          DialogueId = 80070102,
          GUID = "C872751C",
          NextDialogue = 80070103,
          SpeakNpcId = 790013,
          Subtitle = "Consider it one of the perks of your promotion to Major. That's your workspace now.",
          TalkActionId = {
            [1] = "790014:Explain01_End",
            [2] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872751C"
        },
        [80070103] = {
          ContentFR = "C’est aussi la volonté de Sa Majesté. Tes succès, comme capturer les espions de l’Église Élyséenne, éradiquer les Déchus et éliminer les Souillés de grande taille, n’ont pas échappé à son attention.",
          DialogueId = 80070103,
          GUID = "C8727546",
          LookAt = {
            [1] = "790013:n(790014)"
          },
          NextDialogue = 80070104,
          SpeakNpcId = 790013,
          Subtitle = "His Majesty himself approves. Your achievements — capturing spies from the Elysian Church, suppressing The Forsakens, and neutralising large Filthoids — haven't gone unnoticed by His Majesty.",
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727546"
        },
        [80070104] = {
          Camera = "-27.108675,189.212509,103.496094,0.000003,3.399535,-80.992088,45.0,357.136719,false,Manual,9.443032",
          ContentFR = " ... Tout ça, c’est grâce à votre encadrement, commandante.",
          DialogueId = 80070104,
          GUID = "C8727570",
          LookAt = {
            [1] = "790013:n(790013)"
          },
          NextDialogue = 80070105,
          SpeakNpcId = 790014,
          Subtitle = "...I owe it all to your leadership, Chief.",
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727570"
        },
        [80070105] = {
          ContentFR = "Arrête ces flatteries inutiles. La XIIIᵉ Légion n’a pas besoin de ça. Ce que Randy t’a appris, tu dois le comprendre par toi-même, savoir trier et appliquer intelligemment.",
          DialogueId = 80070105,
          GUID = "C872759A",
          NextDialogue = 80070106,
          SpeakNpcId = 790013,
          Subtitle = "Save it. We don't entertain sycophants in the 13th Legion. Use your head, be smart with what Randy taught you.",
          TalkActionId = {
            [1] = "790013:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872759A"
        },
        [80070106] = {
          ContentFR = "Put***, il m’a encore eu.",
          DialogueId = 80070106,
          GUID = "C87275C4",
          NextDialogue = 80070107,
          SpeakNpcId = 790014,
          Subtitle = "D**n it, he's duped me again.",
          TalkActionId = {
            [1] = "790014:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87275C4"
        },
        [80070107] = {
          Camera = "-118.393959,-109.984428,23.003906,0.000025,18.800102,61.800278,35.000008,369.962646,false,Manual,9.880018",
          ContentFR = "Bien. Puisque tu es venue spécialement pour faire ton rapport, c’est que tu as des doutes, même à ton rang. Parle donc.",
          DialogueId = 80070107,
          GUID = "C87275EE",
          NextDialogue = 80070108,
          SpeakNpcId = 790013,
          Subtitle = "Since you're here, it's clear you have uncertainties, even as a Major. Let's hear them.",
          TalkActionId = {
            [1] = "790014:Sigh_End"
          },
          TurnTo = {
            [1] = "790013:n(790014)"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87275EE"
        },
        [80070108] = {
          Camera = "-16.022058,-23.41791,119.476562,0.000012,4.399871,-83.797165,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui, en rangeant le bureau, j’ai retrouvé quelques affaires personnelles à vous, et je me suis dit que vous voudriez jeter un œil.",
          DialogueId = 80070108,
          GUID = "C8727618",
          NextDialogue = 80070109,
          SpeakNpcId = 790014,
          Subtitle = "Right, I've come across some of your personal items while clearing out the office, and I thought you might wanna have a look, Chief.",
          TalkActionId = {
            [1] = "790014:Give"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727618"
        },
        [80070109] = {
          ContentFR = "D’abord, ces documents portant le sceau des Spathatoi... Ils ont l’air anciens.",
          DialogueId = 80070109,
          GUID = "C8727642",
          NextDialogue = 80070110,
          SpeakNpcId = 790014,
          Subtitle = "These documents have the Spathatoi crest on them. They seem quite old.",
          TalkActionId = {
            [1] = "790014:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727642"
        },
        [80070110] = {
          ContentFR = "Les affaires des Spathatoi ont toujours été de votre ressort, je n’ai pas osé fouiller. Que voulez-vous faire de ces papiers, commandante ?",
          DialogueId = 80070110,
          GUID = "C872766C",
          NextDialogue = 80070111,
          SpeakNpcId = 790014,
          Subtitle = "You've always dealt with matters related to the Spathatoi personally, so I didn't pry. How would you like to proceed with these documents, Chief?",
          TalkActionId = {
            [1] = "790014:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872766C"
        },
        [80070111] = {
          Camera = "-29.486694,-231.213272,139.712891,0.000004,-3.599571,79.597282,45.0,369.962646,false,Manual,9.880018",
          ContentFR = "Ce sont... des listes de contrebande datant de plusieurs années, réunies par Randy à l’époque. Elles peuvent être jetées.",
          DialogueId = 80070111,
          GUID = "C8727696",
          NextDialogue = 80070112,
          SpeakNpcId = 790013,
          Subtitle = "These are... just some old lists of smuggled items from the Spathatoi that Randy put together for the case years ago. They can be discarded now.",
          TalkActionId = {
            [1] = "790013:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727696"
        },
        [80070112] = {
          Camera = "-18.71162,-52.899345,121.708984,0.000012,4.399871,-83.797165,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Des listes de contrebande... Ce ne sont pas des preuves importantes ?",
          DialogueId = 80070112,
          GUID = "C87276C0",
          NextDialogue = 80070113,
          SpeakNpcId = 790014,
          Subtitle = "Lists of smuggled items... Aren't these vital evidence?",
          TalkActionId = {
            [1] = "790013:Explain01_End",
            [2] = "790014:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87276C0"
        },
        [80070113] = {
          Camera = "-87.774124,-53.601727,54.482422,0.000029,17.19998,61.800571,35.000008,369.962646,false,Manual,9.880018",
          ContentFR = "La XIIIᵉ Légion, en tant qu’armée directe de Sa Majesté, agit selon des objectifs, pas selon des preuves.",
          DialogueId = 80070113,
          FinalCamera = "-84.453262,-36.544121,59.619141,0.000028,17.19998,61.800621,35.000008,369.962646,false,Manual,9.880018",
          GUID = "C87276EA",
          NextDialogue = 80070114,
          SpeakNpcId = 790013,
          Subtitle = "The 13th Legion operates directly under His Majesty's command — our actions are guided by objectives, not by evidence.",
          TalkActionId = {
            [1] = "790014:Explain02_End",
            [2] = "790013:Talk03_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87276EA"
        },
        [80070114] = {
          ContentFR = "Je comprends ta confusion. Jusqu’ici, tu as combattu des ennemis externes, mais tu n’as pas encore affronté les machinations internes. Profite de cette occasion pour comprendre.",
          DialogueId = 80070114,
          GUID = "C8727714",
          NextDialogue = 80070115,
          SpeakNpcId = 790013,
          Subtitle = "Your confusion is understandable. Until now, your enemies have been external, and you've yet to witness the internal machinations. Let's take this chance to bring you up to speed.",
          TalkActionId = {
            [1] = "790013:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727714"
        },
        [80070115] = {
          ContentFR = "Quand nos opérations croisent d’autres institutions impériales, le \"comment\" importe peu. La XIIIᵉ ne regarde que les \"résultats\" souhaités par Sa Majesté.",
          DialogueId = 80070115,
          GUID = "C872773E",
          IsBlack = 1,
          SpeakNpcId = 790013,
          Subtitle = "When our missions intersect with other internal organisations, the \"process\" becomes irrelevant. The 13th Legion focuses solely on achieving the \"results\" His Majesty desires.",
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872773E"
        },
        [80070116] = {
          Camera = "524.42627,-192.475586,223.517578,0.000009,-12.600278,160.80278,35.000008,369.962646,false,Manual,9.880018",
          ContentFR = "Monsieur Willers, vous êtes accusé de trafic d’équipements alchimiques sur le marché noir. Vous vous rendez volontairement, ou dois-je vous escorter ?",
          DialogueId = 80070116,
          FinalCamera = "532.717896,-168.658752,223.517578,0.000009,-12.600278,160.80278,35.000008,369.962646,false,Manual,9.880018",
          GUID = "C8727768",
          NextDialogue = 80070117,
          SpeakNpcId = 790015,
          Subtitle = "Mr Willers, you stand accused of smuggling alchemical equipment to the black market. Would you prefer to come quietly, or shall I assist you?",
          TalkActionId = {
            [1] = "790015:Explain01_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727768"
        },
        [80070117] = {
          Camera = "-216.380081,-25.239105,134.419922,0.000003,0.599745,13.60984,35.0,100000.0,false,Manual,10.0",
          ContentFR = "Je suis un alchimiste de haut rang ! Même si la XIIIᵉ agit au nom de l’Empereur, vous ne pouvez pas faire ce que bon vous semble !",
          DialogueId = 80070117,
          GUID = "C8727792",
          NextDialogue = 80070118,
          SpeakNpcId = 790016,
          Subtitle = "I'm a senior alchemist. Even with the Emperor backing the 13th Legion, you cannot simply do as you please!",
          TalkActionId = {
            [1] = "790015:Explain01_End",
            [2] = "790016:Shock_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727792"
        },
        [80070118] = {
          Camera = "-28.744118,-95.146759,106.203125,0.000002,9.199704,137.200348,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Chut. Réfléchis bien avant de parler. Le trafic, c’est pardonnable, et certains ont la chance de survivre. Mais insulter Sa Majesté, c’est trahison, passible de la peine capitale.",
          DialogueId = 80070118,
          GUID = "C87277BC",
          NextDialogue = 80070119,
          SpeakNpcId = 790015,
          Subtitle = "Ssh, I'd advise you to think carefully before you speak. If this is just about smuggling, the lucky ones might still be spared. But if you slander and question His Majesty, then it would be considered treason.",
          TalkActionId = {
            [1] = "790015:Talk03_Start",
            [2] = "790016:Shock_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87277BC"
        },
        [80070119] = {
          Camera = "-216.380081,-25.239105,134.419922,0.000003,0.599745,13.60984,35.0,100000.0,false,Manual,10.0",
          ContentFR = "Hmm... En fait, tu ferais mieux de continuer. Ça m’évitera de t’escorter, je peux te descendre ici et maintenant. Vas-y, parle.",
          DialogueId = 80070119,
          GUID = "C87277E6",
          NextDialogue = 80070120,
          Scripts = "SEQ{PlayAnimation{ActorId{790015},AnimationId{\"Talk03_End\"},Duration{1}},PlayAnimation{ActorId{790015},AnimationId{\"Think_Start\"},Duration{3}}}",
          SpeakNpcId = 790015,
          Subtitle = "Hmm, you know what, you might as well go on — it saves me the trouble of dragging you back — I could just shoot you on the spot. Come on, keep talking.",
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87277E6"
        },
        [80070120] = {
          ContentFR = "N-non... Je suis loyal à Sa Majesté et à l’Empire, sans la moindre arrière-pensée... Ces appareils étaient défectueux, je voulais juste les échanger contre de l’argent pour en acheter de nouveaux...",
          DialogueId = 80070120,
          GUID = "C8727810",
          NextDialogue = 80070121,
          SpeakNpcId = 790016,
          Subtitle = "No, no... I am utterly loyal to His Majesty and the Empire... I harbour no ulterior motives... Those devices were faulty, so I thought it better to exchange them for money to buy new ones than to let them go to waste...",
          TalkActionId = {
            [1] = "790015:Think_End",
            [2] = "790016:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727810"
        },
        [80070121] = {
          Camera = "1.974182,790.534241,-2.171875,0.0,7.599726,-89.396553,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ces appareils ne servent plus à l’Académie, mais s’ils tombent entre les mains des Déchus ou pire, des Élyséens via le marché noir, tu imagines les conséquences ?",
          DialogueId = 80070121,
          FinalCamera = "1.650574,821.253418,-6.269531,0.0,7.599726,-89.396553,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C872783A",
          NextDialogue = 80070122,
          SpeakNpcId = 790013,
          Subtitle = "Those devices might be useless to the Academy, but if they end up in the hands of The Forsakens — or even worse, the Elysians — through the black market, have you considered the consequences?",
          TalkActionId = {
            [1] = "790013:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "790015:n(790013)",
            [2] = "790016:n(790013)"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872783A"
        },
        [80070122] = {
          Camera = "133.41275,-15.108414,77.826172,0.000001,3.799675,-114.404198,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Même s’ils sont défectueux, ils seront démontés, étudiés. Les secrets techniques de l’Académie seraient alors compromis, ce qui causerait davantage de morts.",
          DialogueId = 80070122,
          GUID = "C8727864",
          NextDialogue = 80070123,
          SpeakNpcId = 790013,
          Subtitle = "They could reverse-engineer our tech through those rejects, which would lead to more casualties.",
          TalkActionId = {
            [1] = "790013:Explain01_End"
          },
          TurnTo = {
            [1] = "790013:n(790016)"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727864"
        },
        [80070123] = {
          ContentFR = "L’argent que tu as gagné en contrebande est taché du sang de nos soldats au front. Tu as réfléchi à ça ?",
          DialogueId = 80070123,
          GUID = "C872788E",
          NextDialogue = 80070124,
          SpeakNpcId = 790013,
          Subtitle = "The money you've made through smuggling is tainted with the blood of our soldiers fighting at the front.",
          TalkActionId = {
            [1] = "790013:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872788E"
        },
        [80070124] = {
          Camera = "802.744385,-2917.147705,950.736328,0.000016,-14.799558,100.006508,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Eux ne te dénonceront pas, ce sont déjà des héros tombés au combat. Toi, tu n’es qu’un charognard puant, en train de rôder autour de leurs cadavres.",
          DialogueId = 80070124,
          GUID = "C87278B8",
          NextDialogue = 80070125,
          SpeakNpcId = 790013,
          Subtitle = "They won't accuse you, for they're fallen heroes, and you're just a vile vulture circling their corpses.",
          TalkActionId = {
            [1] = "790013:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87278B8"
        },
        [80070125] = {
          ContentFR = "L’Empire n’a que faire des mouches qui bourdonnent des serments de loyauté.",
          DialogueId = 80070125,
          GUID = "C87278E2",
          NextDialogue = 80070126,
          SpeakNpcId = 790013,
          Subtitle = "The Empire has no need for loyalty-chanting flies.",
          TalkActionId = {
            [1] = "790013:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87278E2"
        },
        [80070126] = {
          ContentFR = "N-non... Ces montants ne méritent pas la peine de mort à Hyperborea. Vous avez dit que j’aurais une chance de m’en sortir ! Je réclame un procès équitable !",
          DialogueId = 80070126,
          GUID = "C872790C",
          NextDialogue = 80070127,
          SpeakNpcId = 790016,
          Subtitle = "No, please... In Hyperborea, my smuggling amount wouldn't warrant a death sentence... You even said yourself I could live — I demand a fair trial!",
          TalkActionId = {
            [1] = "790016:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872790C"
        },
        [80070127] = {
          Camera = "-5.173111,14.265663,123.404297,0.000001,4.199979,-175.594803,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai dit « certains ». Pas toi.",
          DialogueId = 80070127,
          GUID = "C8727936",
          NextDialogue = 800701271,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"790015:n(790016)\"}},PlayAnimation{ActorId{790015},AnimationId{\"Talk03_Start\"},Duration{2}}}",
          SpeakNpcId = 790015,
          Subtitle = "Well, I said \"the lucky ones.\"",
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727936"
        },
        [80070128] = {
          Camera = "-18.071548,-70.088799,137.375,0.000012,-1.200228,-84.797432,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Simple et direct. J’aime ça.",
          DialogueId = 80070128,
          FinalCamera = "-18.661856,-63.606865,137.505859,0.000012,-1.200228,-84.797432,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8727960",
          NextDialogue = 80070129,
          SpeakNpcId = 790014,
          Subtitle = "That's certainly simple and efficient.",
          TalkActionId = {
            [1] = "790014:Agree"
          },
          ToFinalCameraBlendTime = 6,
          TurnTo = {
            [1] = "790013:n(790014)"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727960"
        },
        [80070129] = {
          Camera = "-64.542519,-9.4065,79.558594,0.000028,16.399981,62.800785,35.000008,369.962646,false,Manual,9.880018",
          ContentFR = "Pas si simple. La XIIIᵉ ne répond qu’à l’Empereur. Dans l’ombre, nous sommes sa lame secrète, son poignard. En plein jour, nous sommes le messager de sa clémence.",
          DialogueId = 80070129,
          GUID = "C872798A",
          NextDialogue = 80070130,
          Scripts = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Disagree\"},Duration{2}},PlayAnimation{ActorId{790013},AnimationId{\"Explain01_Start\"},Duration{3}}}",
          SpeakNpcId = 790013,
          Subtitle = "It's not that simple. The 13th Legion only takes orders from the Emperor. In the shadows, we are His Majesty's hidden blade, but in the light, we also serve as the messenger of his benevolence.",
          VoiceName = "voice/$Locale$/inv/Xibi/001/C872798A"
        },
        [80070130] = {
          ContentFR = "Exécuter un trafiquant ne clôt pas une affaire. Nous avons dû rassembler les alchimistes pour leur faire passer un message.",
          DialogueId = 80070130,
          GUID = "C87279B4",
          NextDialogue = 80070131,
          SpeakNpcId = 790013,
          Subtitle = "Executing a smuggler didn't close the case. We still needed to gather the alchemists together to deliver a message.",
          TalkActionId = {
            [1] = "790013:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87279B4"
        },
        [80070131] = {
          Camera = "-1357.414917,-1285.646851,0.798828,0.000054,2.999491,42.001163,35.000008,369.962646,false,Manual,9.880018",
          ContentFR = "Ils ont dû être trop terrifiés pour parler, non ?",
          DialogueId = 80070131,
          FinalCamera = "-1393.55542,-1245.51001,0.798828,0.000054,2.999491,42.001163,35.000008,369.962646,false,Manual,9.880018",
          GUID = "C87279DE",
          NextDialogue = 80070132,
          SpeakNpcId = 790014,
          Subtitle = "I bet they were too scared to even speak.",
          TalkActionId = {
            [1] = "790014:Agree"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87279DE"
        },
        [80070132] = {
          ContentFR = "Oui, mais ce n’était pas un massacre, juste un discours. Le corps de Willers cloué à la tribune, et l’annonce d’un financement accru pour les Spathatoi.",
          DialogueId = 80070132,
          GUID = "C8727A08",
          NextDialogue = 80070133,
          SpeakNpcId = 790013,
          Subtitle = "That was true. But what awaited them wasn't execution, but a speech announcing increased funding for the Spathatoi... With Willers's corpse nailed to the podium.",
          TalkActionId = {
            [1] = "790013:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727A08"
        },
        [80070133] = {
          ContentFR = "L’Empire avance comme un char de guerre grondant, et l’Académie d’Alchimie est son moteur. Si on ralentit ses recherches à cause d’un grain de sable, c’est aller contre la volonté de Sa Majesté.",
          DialogueId = 80070133,
          GUID = "C8727A32",
          NextDialogue = 80070134,
          SpeakNpcId = 790013,
          Subtitle = "The Empire advances like a rumbling war chariot, and it cannot do without the academy as its engine. If we let a single act of smuggling impede the academy's research progress, that would be going against His Majesty's wishes.",
          TalkActionId = {
            [1] = "790013:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727A32"
        },
        [80070134] = {
          Camera = "-108.692429,383.760162,74.947266,0.000001,8.799756,-69.593491,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors les autres s'en sont tirés comme ça, sans autre forme de procès ?",
          DialogueId = 80070134,
          GUID = "C8727A5C",
          NextDialogue = 80070135,
          SpeakNpcId = 790014,
          Subtitle = "So the rest of them just got off the hook just like that?",
          TalkActionId = {
            [1] = "790014:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727A5C"
        },
        [80070135] = {
          ContentFR = "C’est suffisant. Tous ont vu ce qu’il arrive à ceux qui trahissent l’Empire.",
          DialogueId = 80070135,
          GUID = "C8727A86",
          NextDialogue = 80070136,
          SpeakNpcId = 790013,
          Subtitle = "A spectacle of deterrence would suffice. All have witnessed the fate of those who betrayed the Empire.",
          TalkActionId = {
            [1] = "790014:Explain01_End",
            [2] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727A86"
        },
        [80070136] = {
          ContentFR = "Les parasites comme Willers vivront hantés par la peur, craignant qu’on frappe à leur porte la nuit. Ceux qui hésitent respireront un peu, heureux de ne pas avoir commis d’erreur.",
          DialogueId = 80070136,
          GUID = "C8727AB0",
          NextDialogue = 80070137,
          SpeakNpcId = 790013,
          Subtitle = "The vermin and parasites like Willers would live in perpetual fear, dreading the knock at their doors every night. Those fence-sitters would breathe a sigh of relief, grateful for their prudence before making the wrong choice.",
          TalkActionId = {
            [1] = "790013:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727AB0"
        },
        [80070137] = {
          ContentFR = "Les loyaux, par la purge des pécheurs et la louange des vertueux, verront leur foi en la justice de Sa Majesté plus profondément ancrée.",
          DialogueId = 80070137,
          GUID = "C8727ADA",
          NextDialogue = 80070138,
          SpeakNpcId = 790013,
          Subtitle = "While the loyal — through the purge of the sinful and the commendation of the virtuous — will further cement their faith in His Majesty's justice.",
          TalkActionId = {
            [1] = "790013:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727ADA"
        },
        [80070138] = {
          Camera = "-87.774124,-53.601727,54.482422,0.000029,17.19998,61.800571,35.000008,369.962646,false,Manual,9.880018",
          ContentFR = "La carotte et le bâton, la règle d’or pour inspirer la loyauté. Il faut savoir tolérer quelques impuretés, et ajuster son emprise selon les circonstances.",
          DialogueId = 80070138,
          GUID = "C8727B04",
          NextDialogue = 80070139,
          SpeakNpcId = 790013,
          Subtitle = "Carrot and stick — the golden rule for commanding loyalty. We must tolerate some impurities, adjusting our grip as necessary.",
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727B04"
        },
        [80070139] = {
          Camera = "-108.692429,383.760162,74.947266,0.000001,8.799756,-69.593491,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Trop compliqué pour moi... Finalement, être major, c’est peut-être pas si génial. Autant me contenter de ce que je maîtrise, comme jeter cette liste à la poubelle.",
          DialogueId = 80070139,
          GUID = "C8727B2E",
          NextDialogue = 80070140,
          SpeakNpcId = 790014,
          Subtitle = "Sounds too complicated for me to understand. I'm starting to think becoming a Major isn't all that great for me. Maybe I should stick to what I understand, like getting rid of this list.",
          TalkActionId = {
            [1] = "790014:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727B2E"
        },
        [80070140] = {
          Camera = "-29.486694,-231.213272,139.712891,0.000004,-3.599571,79.597282,45.0,369.962646,false,Manual,9.880018",
          ContentFR = "Ne te laisse pas submerger par la pression. La XIIIᵉ incarne la mort pour nos ennemis, mais elle est un pilier pour nos alliés. Prends Randy avec toi, il t’aidera à gérer les détails.",
          DialogueId = 80070140,
          GUID = "C8727B58",
          LookAt = {
            [1] = "790013:n(790014)"
          },
          NextDialogue = 80070141,
          SpeakNpcId = 790013,
          Subtitle = "Don't let the pressure overwhelm you. The 13th Legion spells death for our enemies but serves as a steadfast anchor for our allies. Take Randy — he'll help you navigate the minutiae.",
          TalkActionId = {
            [1] = "790013:Disagree"
          },
          TurnTo = {
            [1] = "790013:n(790014)"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727B58"
        },
        [80070141] = {
          Camera = "-27.108675,189.212509,103.496094,0.000003,3.399535,-80.992088,45.0,357.136719,false,Manual,9.443032",
          ContentFR = "Lui ? Il m’a déjà roulée plusieurs fois.",
          DialogueId = 80070141,
          GUID = "C8727B82",
          NextDialogue = 80070142,
          SpeakNpcId = 790014,
          Subtitle = "Randy? He's tricked me more times than I can count.",
          TalkActionId = {
            [1] = "790014:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727B82"
        },
        [80070142] = {
          Camera = "-29.486694,-231.213272,139.712891,0.000004,-3.599571,79.597282,45.0,369.962646,false,Manual,9.880018",
          ContentFR = "Tomber dans ses pièges est aussi une leçon. Il ne te fera jamais vraiment de mal. La XIIIᵉ est la plus petite, mais la plus affûtée des légions. Apprends à t’intégrer et à collaborer avec chacun.",
          DialogueId = 80070142,
          GUID = "C8727BAC",
          NextDialogue = 80070143,
          SpeakNpcId = 790013,
          Subtitle = "His tricking you is also a lesson in disguise. He would never truly harm you. Though the smallest in number, the 13th Legion is composed of the forces' finest warriors. You need to learn how to blend in and build rapport with everyone.",
          TalkActionId = {
            [1] = "790014:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727BAC"
        },
        [80070143] = {
          Camera = "-27.108675,189.212509,103.496094,0.000003,3.399535,-80.992088,45.0,357.136719,false,Manual,9.443032",
          ContentFR = "Hmm, je vais faire de mon mieux.",
          DialogueId = 80070143,
          GUID = "C8727BD6",
          SpeakNpcId = 790014,
          Subtitle = "Alright, I'll give it my best shot.",
          TalkActionId = {
            [1] = "790014:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727BD6"
        },
        [80070201] = {
          Camera = "-178.038208,706.88324,245.560547,0.000045,-15.599693,-71.79892,25.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Commandante, les listes de marchandises de contrebande ont été traitées. Il ne reste qu’un magnétophone hors service et une vieille photo à valider.",
          DialogueId = 80070201,
          FinalCamera = "-192.709595,702.058655,245.560547,0.000045,-15.599693,-71.798897,25.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C872855A",
          LookAt = {
            [1] = "790014:n(790013)"
          },
          NextDialogue = 80070202,
          Scripts = "MoveTo{ActorId{790014},MoveSpeed{75},TargetPoint{\"TargetPoint_430102\"}}",
          SpeakNpcId = 790014,
          Subtitle = "Chief, the lists of smuggled items have been dealt with. All that's left is a broken recorder and an old photo for your review.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Xibi/002/C872855A"
        },
        [80070202] = {
          ContentFR = "Ce truc fait un boucan d’enfer dès qu’on l’allume... J’ai cru que c’était un instrument de torture.",
          DialogueId = 80070202,
          GUID = "C8728584",
          LookAt = {
            [1] = "790013:n(790014)"
          },
          NextDialogue = 80070203,
          SpeakNpcId = 790014,
          Subtitle = "The recorder just keeps buzzing non-stop when it's on — I almost thought it was some kind of torture device.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728584"
        },
        [80070203] = {
          Camera = "-88.759552,-172.692947,120.162109,0.000021,-5.59915,67.009216,28.0,453.595306,false,Manual,8.167668",
          ContentFR = "Celui-là ? Pose-le là. J’ai toute une collection d’enregistrements similaires. Un de plus ne changera pas grand-chose.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070203,
          GUID = "C87285AE",
          NextDialogue = 80070204,
          SpeakNpcId = 790013,
          Subtitle = "Uh, that one. Just leave it here. Though I have many like it, one more won't hurt.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87285AE"
        },
        [80070204] = {
          ContentFR = "Et pour le contenu... rien d’étonnant que tu ne reconnaisses pas ce bruit. C’est un vieux moteur de dirigeable, un modèle d’il y a une dizaine d’années.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070204,
          GUID = "C87285D8",
          NextDialogue = 80070205,
          SpeakNpcId = 790013,
          Subtitle = "As for what's on it, it's no surprise you don't know — it's the sound of an airship engine model used over a decade ago.",
          TalkActionId = {
            [1] = "790013:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87285D8"
        },
        [80070205] = {
          ContentFR = "Aujourd’hui, l’Empire privilégie la stabilité et l’endurance. À l’époque de cette guerre, seule comptait la vitesse, et la capacité d’emport.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070205,
          GUID = "C8728602",
          NextDialogue = 80070206,
          SpeakNpcId = 790013,
          Subtitle = "Modern Empire airships prioritise stability and endurance, unlike during that war when speed and firepower were all that mattered.",
          TurnTo = {
            [1] = "790013:n(790014)"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728602"
        },
        [80070206] = {
          Camera = "-63.979523,366.17868,112.912109,0.000001,-2.799961,-78.5989,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vous parlez de l’offensive de l’Élégie Divine contre l’Église Élyséenne, il y a vingt ans ? La XIIIᵉ a foncé sur leur tour dans des dirigeables prototypes. Même les gamins dans la rue en fredonnent les exploits.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070206,
          GUID = "C872862C",
          NextDialogue = 80070207,
          Scripts = "SEQ{PlayAnimation{ActorId{790014},AnimationId{\"Explain02_Start\"},Duration{3}},PlayAnimation{ActorId{790014},AnimationId{\"Explain02_End\"},Duration{1}}}",
          SpeakNpcId = 790014,
          Subtitle = "You mean the \"Divine Elegy\" offensive against the Elysian Church more than 20 years ago, right? In that battle, the 13th Legion stormed their tower in prototype airships. That's a story even kids in the street can sing a verse or two about.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C872862C"
        },
        [80070207] = {
          ContentFR = "Et c’est grâce à cette bataille que vous êtes devenue la plus jeune commandante de la Légion de l’histoire de l’Empire.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070207,
          GUID = "C8728656",
          NextDialogue = 80070208,
          SpeakNpcId = 790014,
          Subtitle = "And it was your valour in that battle that made you the youngest chief in Empire history.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728656"
        },
        [80070208] = {
          Camera = "-88.759552,-172.692947,120.162109,0.000021,-5.59915,67.009216,28.0,453.595306,false,Manual,8.167668",
          ContentFR = "... Sur le papier, c’est vrai. La XIIIᵉ a contourné les lignes de front, attaqué une tour jamais approchée, et pour la première fois, affronté les \"dieux\" de près. Digne d’être chanté, oui.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070208,
          GUID = "C8728680",
          NextDialogue = 80070209,
          Scripts = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Think_Start\"},Duration{2}},PlayAnimation{ActorId{790013},AnimationId{\"Think_End\"},Duration{1}},PlayAnimation{ActorId{790013},AnimationId{\"Agree\"},Duration{1}}}",
          SpeakNpcId = 790013,
          Subtitle = "...Mm, we bypassed the hot zone at the border and struck directly at their normally untouchable tower, reaching the gods' lair for the first time. It's a tale worth retelling indeed.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728680"
        },
        [80070209] = {
          ContentFR = "Mais pour la XIIIᵉ Légion, pour moi, cette bataille n’a laissé que colère et honte.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070209,
          GUID = "C87286AA",
          NextDialogue = 80070210,
          SpeakNpcId = 790013,
          Subtitle = "But for the 13th Legion — or more precisely, for me — the campaign brought not only glory but also... anger and shame.",
          TalkActionId = {
            [1] = "790013:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87286AA"
        },
        [80070210] = {
          ContentFR = "Les douze officiers envoyés dans la tour sont tous morts. Si je n’étais pas restée en retrait sur le dirigeable, mon nom ne serait plus qu’un chiffre sur la liste des morts.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070210,
          GUID = "C87286D4",
          NextDialogue = 80070211,
          SpeakNpcId = 790013,
          Subtitle = "All 12 officers who attacked the tower were killed. Had I not been left to guard the airship outside, I might just be another number on the casualty list.",
          TalkActionId = {
            [1] = "790013:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87286D4"
        },
        [80070211] = {
          Camera = "-63.415112,74.612396,161.78125,0.000025,-23.199345,52.011242,35.000008,453.595306,false,DoNotOverride,8.167668",
          ContentFR = "Derrière la gloire, une défaite cuisante.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070211,
          GUID = "C87286FE",
          NextDialogue = 80070212,
          SpeakNpcId = 790013,
          Subtitle = "Behind the glory was our grievous defeat.",
          TalkActionId = {
            [1] = "790013:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87286FE"
        },
        [80070212] = {
          ContentFR = "Mon dernier souvenir de cette bataille est de piloter un dirigeable hors de contrôle, fendant un ciel en flammes sous un feu croisé de canons et de projectiles magiques.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070212,
          GUID = "C8728728",
          NextDialogue = 80070213,
          SpeakNpcId = 790013,
          Subtitle = "My last memory of that battle is piloting an out-of-control airship, weaving through relentless artillery fire and magical barrages across the border.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728728"
        },
        [80070213] = {
          ContentFR = "Cet enregistrement me ramène là-bas, au cœur du vacarme du moteur, à l’odeur du sang dans mes narines.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070213,
          GUID = "C8728752",
          NextDialogue = 80070214,
          SpeakNpcId = 790013,
          Subtitle = "This recording takes me back to that airship... to that moment. It reminds me of the smell of blood in my nose and the weary roar of the engines in my ears.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728752"
        },
        [80070214] = {
          Camera = "-63.979523,366.17868,112.912109,0.000001,-2.799961,-78.5989,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Maintenant que vous le dites, vous vous asseyez toujours près du moteur quand on vole...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070214,
          GUID = "C872877C",
          NextDialogue = 80070215,
          SpeakNpcId = 790014,
          Subtitle = "That explains why you always choose the spot closest to the engine on flights.",
          TalkActionId = {
            [1] = "790014:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C872877C"
        },
        [80070215] = {
          Camera = "-1015.568604,-969.672852,166.992188,0.0,-4.99948,47.392773,35.000008,100000.0,false,Manual,2.8",
          ContentFR = "La guerre change tout. Et tout le monde.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070215,
          FinalCamera = "-985.23938,-936.698364,163.091797,0.0,-4.99948,47.392773,35.000008,100000.0,false,Manual,2.8",
          GUID = "C87287A6",
          NextDialogue = 80070216,
          SpeakNpcId = 790013,
          Subtitle = "This is war. It changes people.",
          TalkActionId = {
            [1] = "790013:Talk03_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87287A6"
        },
        [80070216] = {
          ContentFR = "J’ai vu tant de soldats brisés, même loin du front, dans les hôpitaux, toujours hantés par la guerre. Parfois, un simple coup de canon lors d’une fête, ou le claquement d’un jouet, suffit à les faire s’effondrer.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070216,
          GUID = "C87287D0",
          NextDialogue = 80070217,
          Scripts = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Talk03_End\"},Duration{1}},PlayAnimation{ActorId{790013},AnimationId{\"Explain02_Start\"},Duration{1}}}",
          SpeakNpcId = 790013,
          Subtitle = "I've seen too many soldiers in hospitals, still haunted by the war long after leaving the front. Sometimes, a ceremonial cannon or even a child's toy gun can trigger a breakdown.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87287D0"
        },
        [80070217] = {
          ContentFR = "Même les plus solides gardent des séquelles. Par exemple, le commandant de la XIᵉ Légion, stationnée à la frontière, dort toujours un œil ouvert.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070217,
          GUID = "C87287FA",
          NextDialogue = 80070218,
          Scripts = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Explain02_End\"},Duration{1}},PlayAnimation{ActorId{790013},AnimationId{\"Explain01_Start\"},Duration{1}}}",
          SpeakNpcId = 790013,
          Subtitle = "War leaves its mark even on the toughest among us. Take the Chief of the 11th Legion stationed at the border, who sleeps with one eye open.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87287FA"
        },
        [80070218] = {
          Camera = "-63.415112,74.612396,161.78125,0.000025,-23.199345,52.011242,35.000008,453.595306,false,DoNotOverride,8.167668",
          ContentFR = "Ils ont dû retenir la plus grande partie des troupes élyséennes à la frontière. Leur pression et leurs pertes étaient comparables aux nôtres.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070218,
          GUID = "C8728824",
          NextDialogue = 80070219,
          SpeakNpcId = 790013,
          Subtitle = "In that campaign, their forces held off the bulk of the Elysian army at the border, bearing just as much burden and bloodshed as we did.",
          TalkActionId = {
            [1] = "790013:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728824"
        },
        [80070219] = {
          Camera = "-9.893036,212.023102,120.853516,0.000003,-4.000004,-89.204086,45.0,100000.0,false,Manual,16.970627",
          ContentFR = "Vous réécoutez cet enregistrement encore et encore... par culpabilité envers ceux qui sont tombés ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070219,
          GUID = "C872884E",
          NextDialogue = 80070220,
          SpeakNpcId = 790014,
          Subtitle = "Is that why you replay this recording over and over? Out of guilt over your comrades' deaths?",
          TalkActionId = {
            [1] = "790014:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C872884E"
        },
        [80070220] = {
          Camera = "-88.759552,-172.692947,120.162109,0.000021,-5.59915,67.009216,28.0,453.595306,false,Manual,8.167668",
          ContentFR = "Non. Pour rester éveillée. Quand je fatigue, ça m’aide à me concentrer.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070220,
          GUID = "C8728878",
          NextDialogue = 80070221,
          SpeakNpcId = 790013,
          Subtitle = "No, just to keep myself sharp. When I feel tired, it helps me focus.",
          TalkActionId = {
            [1] = "790014:Explain02_End",
            [2] = "790013:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728878"
        },
        [80070221] = {
          ContentFR = "Beaucoup se complaisent dans la culpabilité. Ils ressassent leurs échecs, s’apitoient sur leur impuissance. C’est un réflexe... et un luxe de faible.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070221,
          GUID = "C87288A2",
          NextDialogue = 80070222,
          SpeakNpcId = 790013,
          Subtitle = "Many dwell on past failures, lamenting their impotence, wallowing in guilt, and torturing themselves — this is the instinct and privilege of the weak.",
          TalkActionId = {
            [1] = "790013:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87288A2"
        },
        [80070222] = {
          Camera = "-52.902649,28.740311,59.359375,0.000018,21.000099,65.212578,35.000008,158.228317,false,Manual,8.167668",
          ContentFR = "Pour moi, l’échec est une cicatrice. Elle me fait mal, mais elle me garde lucide. Elle me pousse à avancer, à grimper, à transformer honte et douleur en victoire.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070222,
          GUID = "C87288CC",
          NextDialogue = 80070223,
          SpeakNpcId = 790013,
          Subtitle = "But to me, failure is the scar of the past. It's a harsh reminder for me to keep pushing, to climb from all the pain and shame to victory.",
          TalkActionId = {
            [1] = "790013:Talk03_End",
            [2] = "790014:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87288CC"
        },
        [80070223] = {
          ContentFR = "J’honore mes camarades tombés. Et justement pour cela, je ne m’autorise pas à chuter. S’arrêter pour pleurer les morts avant la victoire, c’est trahir leur sacrifice.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070223,
          GUID = "C87288F6",
          NextDialogue = 80070224,
          SpeakNpcId = 790013,
          Subtitle = "I honour my comrades' sacrifices, which is precisely why I refuse to fall as they did. Pausing for breath or to mourn the fallen before claiming final victory would only squander their sacrifices.",
          TalkActionId = {
            [1] = "790014:Think_End",
            [2] = "790013:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87288F6"
        },
        [80070224] = {
          Camera = "-63.979523,366.17868,112.912109,0.000001,-2.799961,-78.5989,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Beaucoup me disent insensible, inhumaine. D’autres invoquent mes origines modestes, prétendant que la cruauté coule dans le sang des Charon.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070224,
          GUID = "C8728920",
          NextDialogue = 80070225,
          SpeakNpcId = 790013,
          Subtitle = "Many call me cold-hearted, and some even cite my humble origins, claiming that cruelty is in my Charon blood.",
          TalkActionId = {
            [1] = "790013:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728920"
        },
        [80070225] = {
          ContentFR = "Mais eux, ils oublient jusqu’aux noms des morts. Ils bavardent comme des insectes avant de s’effacer, un à un, pendant que je poursuis mon ascension.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070225,
          GUID = "C872894A",
          NextDialogue = 80070226,
          SpeakNpcId = 790013,
          Subtitle = "But in the end, they'd forget the failures and even the names of the fallen, just buzzing like bugs before they perish.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C872894A"
        },
        [80070226] = {
          Camera = "-56.278519,-30.622166,132.205078,0.000009,-9.000037,-85.60675,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et à la fin, il ne restera que moi, marquée par l’échec, mais toujours plus haut.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070226,
          GUID = "C8728974",
          NextDialogue = 80070227,
          SpeakNpcId = 790013,
          Subtitle = "All that remains is me, bearing the scars of defeat, continually climbing upward.",
          TalkActionId = {
            [1] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728974"
        },
        [80070227] = {
          ContentFR = "À mes yeux, vous êtes déjà bien au-dessus de ce que la plupart atteindront un jour...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070227,
          GUID = "C872899E",
          NextDialogue = 80070228,
          SpeakNpcId = 790014,
          Subtitle = "From my perspective, Chief, you've already reached heights many can't even dream of...",
          TalkActionId = {
            [1] = "790014:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C872899E"
        },
        [80070228] = {
          Camera = "-52.902649,28.740311,59.359375,0.000018,21.000099,65.212578,35.000008,158.228317,false,Manual,8.167668",
          ContentFR = "Pas assez. La XIIIᵉ Légion porte un idéal que le monde ignore encore.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070228,
          GUID = "C87289C8",
          NextDialogue = 80070229,
          SpeakNpcId = 790013,
          Subtitle = "No, it's not enough. The 13th Legion bears a \"true ideal\" not yet known to the world.",
          TalkActionId = {
            [1] = "790014:Explain02_End",
            [2] = "790013:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87289C8"
        },
        [80070229] = {
          Camera = "-1154.983398,-1628.61377,1072.589844,0.000071,-26.199942,47.398281,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pendant que des larves nées avec des armoiries s’enivrent de leur pouvoir, nous, nous portons le vrai combat. Et eux, tout là-haut, ne rêvent que d’abattre ceux qui s’élèvent pour de bon.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070229,
          FinalCamera = "-1186.510742,-1599.621582,1072.589844,0.000071,-26.199942,47.398281,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C87289F2",
          NextDialogue = 80070230,
          SpeakNpcId = 790013,
          Subtitle = "Some of those born into privilege have long been drunk with fame, power, and glory. They only look downward, always plotting to shove those bearing true ideals off the cliff.",
          TalkActionId = {
            [1] = "790013:Talk03_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Xibi/002/C87289F2"
        },
        [80070230] = {
          ContentFR = "Ces nobles incapables de monter à cheval ou de lire un manuel tactique... Ils n’ont rien à faire dans ce pays.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070230,
          GUID = "C8728A1C",
          NextDialogue = 80070231,
          Scripts = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Talk03_End\"},Duration{1}},PlayAnimation{ActorId{790013},AnimationId{\"Explain01_Start\"},Duration{1}}}",
          SpeakNpcId = 790013,
          Subtitle = "Nobles who can barely ride or understand the basics of command don't belong in this country.",
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728A1C"
        },
        [80070231] = {
          Camera = "-52.902649,28.740311,59.359375,0.000018,21.000099,65.212578,35.000008,158.228317,false,Manual,8.167668",
          ContentFR = "Je ne peux pas m’arrêter ici. Je dois aller plus haut. Gagner un pouvoir qui domine tout.",
          DialogueId = 80070231,
          GUID = "C8728A46",
          LookAt = {
            [1] = "790013:n(790013)"
          },
          NextDialogue = 80070232,
          SpeakNpcId = 790013,
          Subtitle = "I cannot afford to mark time like they do. I must climb higher, to the utmost power.",
          TalkActionId = {
            [1] = "790013:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728A46"
        },
        [80070232] = {
          Camera = "-83.885132,575.331421,43.728516,0.0,8.799899,-79.398201,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce jour-là, nous mènerons l’Empire Hyperboréen... non, toute l’humanité, vers un nouvel avenir. Tu comprends, Lynn ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070232,
          FinalCamera = "-90.078613,608.423706,38.511719,0.0,8.799899,-79.398201,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8728A70",
          NextDialogue = 80070233,
          Scripts = "SEQ{MoveTo{ActorId{790013},MoveSpeed{75},TargetPoint{\"TargetPoint_43010201\"}},LookAt{_delay{2},LookAtDescription{\"790013:n(790014)\"}}}",
          SpeakNpcId = 790013,
          Subtitle = "When that time comes, we shall lead the Hyperborean Empire — no, all of humanity, into a new tomorrow. Do you understand, Lynn?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728A70"
        },
        [80070233] = {
          ContentFR = "... Pour être honnête, pas tout. Vous savez, je suis ici pour survivre, j’ai pas vraiment eu le choix.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070233,
          GUID = "C8728A9A",
          NextDialogue = 80070234,
          SpeakNpcId = 790014,
          Subtitle = "Honestly, I didn't quite follow. You know, I'm just here for the cash — didn't have much choice.",
          TalkActionId = {
            [1] = "790014:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728A9A"
        },
        [80070234] = {
          Camera = "-85.702591,-181.152481,118.537109,0.000021,-1.599391,69.810509,45.0,453.595306,false,Manual,8.167668",
          ContentFR = "Mais si ce que vous dites, c’est que le monde va basculer... alors je me battrai, de toutes mes forces. Pour protéger les miens. Pas vraiment le choix non plus.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070234,
          GUID = "C8728AC4",
          NextDialogue = 80070235,
          SpeakNpcId = 790014,
          Subtitle = "But if you're saying big changes are coming... Then when they do, I'll definitely fight my hardest to protect my family — didn't have much choice on that either.",
          TalkActionId = {
            [1] = "790014:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728AC4"
        },
        [80070235] = {
          Camera = "-17.806854,326.852264,116.085938,0.000009,2.799769,-82.405029,45.0,80.247894,false,DoNotOverride,16.970627",
          ContentFR = "J’apprécie ta franchise, Lynn. Tu es peut-être modeste, mais tu grimpes aussi vers quelque chose qui compte. C’est tout ce qui importe.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80070235,
          GUID = "C8728AEE",
          Scripts = "LookAt{_delay{2},LookAtDescription{\"790013:n(790013)\"}}",
          SpeakNpcId = 790013,
          Subtitle = "I appreciate your candour, Lynn. However modest, you have something worth fighting for — that's all that matters.",
          TalkActionId = {
            [1] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/002/C8728AEE"
        },
        [80070301] = {
          Camera = "1179.431641,-1065.483887,93.511719,0.000004,-0.200466,138.797653,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai rangé le magnétophone. Pour la photo... c’est celle de mon professeur et de cette élève naïve, ma camarade à l’époque.",
          DialogueId = 80070301,
          FinalCamera = "1156.185791,-1092.036255,93.511719,0.000004,-0.200466,138.797653,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C87295C2",
          NextDialogue = 80070302,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
          SpeakNpcId = 790013,
          Subtitle = "I've taken care of the recorder. As for the photo… it's of my teacher and that naive fellow pupil of mine, right?",
          TalkActionId = {
            [1] = "790013:Explain01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87295C2"
        },
        [80070302] = {
          Camera = "32.871628,241.033554,128.292969,0.000024,-4.399693,-100.193977,45.000011,419.787506,false,Manual,10.901892",
          ContentFR = "Pourquoi vous appelez tout le monde \"naïf\", commandante ?",
          DialogueId = 80070302,
          GUID = "C87295EC",
          NextDialogue = 80070303,
          SpeakNpcId = 790014,
          Subtitle = "Why do you call everybody naive, Chief?",
          TalkActionId = {
            [1] = "790013:Explain01_End",
            [2] = "790014:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87295EC"
        },
        [80070303] = {
          ContentFR = "Ah... oui, je t’ai déjà dit ça. Mais sa naïveté n’était pas la même que la tienne. Elle était une autre élève de mon professeur, une personne au cœur pur.",
          DialogueId = 80070303,
          GUID = "C8729616",
          NextDialogue = 80070304,
          SpeakNpcId = 790013,
          Subtitle = "Ha, yes, I've said the same about you. But her naivety was different to yours. She was another pupil of my teacher, with a remarkably pure heart.",
          TalkActionId = {
            [1] = "790014:Sigh_End",
            [2] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729616"
        },
        [80070304] = {
          Camera = "26.439392,-248.712524,118.015625,0.000024,-2.799531,101.20755,45.000011,384.833771,false,Manual,10.901892",
          ContentFR = "Alors qu’elle était dans les Spathatoi, elle nourrissait des rêves irréalistes sur l’alchimie. La première fois que je l’ai vue, elle nous a demandé, à moi et à notre professeur : « L’alchimie, ça rendra la vie meilleure pour tous, n’est-ce pas ? »",
          DialogueId = 80070304,
          GUID = "C8729640",
          NextDialogue = 80070305,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0067_story_daphnis_theme_piano\"}}",
          SpeakNpcId = 790013,
          Subtitle = "Even within the Spathatoi, she held onto some rather fanciful ideas about alchemy. I remember the first time I met her, she asked me and our teacher: \"Alchemy will make everyone's life better, right?\"",
          TalkActionId = {
            [1] = "790013:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729640"
        },
        [80070305] = {
          ContentFR = "Et toi, qu’en penses-tu, Lynn ?",
          DialogueId = 80070305,
          GUID = "C872966A",
          NextDialogue = 80070306,
          SpeakNpcId = 790013,
          Subtitle = "So, what do you think of alchemy, Lynn?",
          TalkActionId = {
            [1] = "790013:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C872966A"
        },
        [80070306] = {
          Camera = "32.871628,241.033554,128.292969,0.000024,-4.399693,-100.193977,45.000011,419.787506,false,Manual,10.901892",
          ContentFR = "C’est une technologie avancée, mais je ne l’ai jamais vraiment utilisée.",
          DialogueId = 80070306,
          GUID = "C8729694",
          NextDialogue = 80070307,
          SpeakNpcId = 790014,
          Subtitle = "Some fancy tech. I've never really used it myself.",
          TalkActionId = {
            [1] = "790014:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729694"
        },
        [80070307] = {
          Camera = "26.439392,-248.712524,118.015625,0.000024,-2.799531,101.20755,45.000011,384.833771,false,Manual,10.901892",
          ContentFR = "Haha, nos ancêtres ont fait de l’alchimie la pierre angulaire de la vie dans l’Empire. Tu l’utilises depuis toujours, sans même t’en rendre compte.",
          DialogueId = 80070307,
          GUID = "C87296BE",
          NextDialogue = 80070308,
          SpeakNpcId = 790013,
          Subtitle = "Haha, our ancestors had long ago refined alchemy into the very foundation of the Empire's lifestyle. You've been using it all along. You just didn't realise it.",
          TalkActionId = {
            [1] = "790013:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87296BE"
        },
        [80070308] = {
          Camera = "24.780663,-23.754013,119.826172,0.000024,-1.399649,-100.595001,45.0,100000.0,false,DoNotOverride,10.901892",
          ContentFR = "Par exemple, tes balles et tes armes à feu sont des créations issues de l’alchimie.",
          DialogueId = 80070308,
          GUID = "C87296E8",
          NextDialogue = 80070309,
          SpeakNpcId = 790013,
          Subtitle = "Take the bullets and firearms you use — they are one of the products of alchemical technology.",
          TalkActionId = {
            [1] = "790013:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87296E8"
        },
        [80070309] = {
          ContentFR = "Ah oui ? Bah, mes armes, c’est ce qui me nourrit. Sans elles, je serais bien embêtée. Ceux qui étudient l’alchimie doivent être des chercheurs incroyables.",
          DialogueId = 80070309,
          GUID = "C8729712",
          NextDialogue = 80070310,
          Scripts = "SEQ{PlayAnimation{ActorId{790014},AnimationId{\"Think_Start\"},Duration{2}},PlayAnimation{ActorId{790014},AnimationId{\"Think_End\"},Duration{1}}}",
          SpeakNpcId = 790014,
          Subtitle = "Really? Huh, well, I'd sure be lost without my guns. Those alchemists must be some talented scholars.",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729712"
        },
        [80070310] = {
          Camera = "26.439392,-248.712524,118.015625,0.000024,-2.799531,101.20755,45.000011,384.833771,false,Manual,10.901892",
          ContentFR = "C’est vrai. La plupart ici partagent ton avis : les alchimistes sont un peu étranges, mais leurs inventions changent peu à peu notre pays.",
          DialogueId = 80070310,
          GUID = "C872973C",
          NextDialogue = 80070311,
          SpeakNpcId = 790013,
          Subtitle = "Most would agree. Alchemists might be a bit eccentric, but their inventions have been steadily transforming this country.",
          TalkActionId = {
            [1] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C872973C"
        },
        [80070311] = {
          ContentFR = "Mon professeur me répétait que l’alchimie est une science profonde, capable de changer l’avenir de l’Empire. Ma camarade, elle, voyait en elle la clé de la paix et de l’espoir.",
          DialogueId = 80070311,
          GUID = "C8729766",
          NextDialogue = 80070312,
          SpeakNpcId = 790013,
          Subtitle = "My teacher always said alchemy was a profound science that would change the future of the Empire. While my fellow pupil believed it was the key to peace and hope.",
          TalkActionId = {
            [1] = "790013:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729766"
        },
        [80070312] = {
          Camera = "-0.956041,3.409428,92.585938,0.000023,10.400335,91.608727,45.0,100000.0,false,DoNotOverride,10.901892",
          ContentFR = "Pour moi, c’est plus pragmatique, un outil pour gravir les échelons du pouvoir.",
          DialogueId = 80070312,
          GUID = "C8729790",
          NextDialogue = 80070313,
          SpeakNpcId = 790013,
          Subtitle = "But for me, alchemy is something more pragmatic — a tool for climbing the ladder of power.",
          TalkActionId = {
            [1] = "790013:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729790"
        },
        [80070313] = {
          ContentFR = "C’est grâce à cette maîtrise que l’Empereur m’a remarquée, reconnaissant ma loyauté et mes compétences, et que j’ai pu devenir officier dans l’offensive de l’Élégie Divine.",
          DialogueId = 80070313,
          GUID = "C87297BA",
          NextDialogue = 80070314,
          SpeakNpcId = 790013,
          Subtitle = "It was my alchemy skills, coupled with my loyalty and competence, that first got the Emperor's attention, making me a key player in the Divine Elegy offensive.",
          TalkActionId = {
            [1] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87297BA"
        },
        [80070314] = {
          ContentFR = "À l’Académie, j’avais les meilleures notes dans toutes les matières, mais je ne m’investissais jamais vraiment dans la recherche. La théorie pure et complexe ne m’intéressait pas.",
          DialogueId = 80070314,
          GUID = "C87297E4",
          NextDialogue = 80070315,
          SpeakNpcId = 790013,
          Subtitle = "I aced every subject at the academy but never really poured my heart into any research. The deep theoretical knowledge just didn't resonate with me.",
          TalkActionId = {
            [1] = "790013:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87297E4"
        },
        [80070315] = {
          ContentFR = "Ça mettait mon professeur en colère. Lors de la cérémonie de fin d’études, elle a dit que je ne comprendrais jamais la vraie connaissance. Mais dis-moi, combien ont vraiment percé le secret du savoir à travers l’Histoire ?",
          DialogueId = 80070315,
          GUID = "C872980E",
          NextDialogue = 80070316,
          Scripts = "SEQ{PlayAnimation{ActorId{790013},AnimationId{\"Explain01_End\"},Duration{1}},PlayAnimation{ActorId{790013},AnimationId{\"Disagree\"},Duration{1}}}",
          SpeakNpcId = 790013,
          Subtitle = "That infuriated my teacher. At the graduation ceremony, she even said that I would never grasp true knowledge. But riddle me this — how many have truly understood knowledge and truth through the ages?",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C872980E"
        },
        [80070316] = {
          Camera = "68.550446,-309.161438,92.363281,0.000028,-0.200043,106.210724,45.000011,450.975708,false,Manual,5.23506",
          ContentFR = "Et aujourd’hui, où sont-ils ?",
          DialogueId = 80070316,
          GUID = "C8729838",
          NextDialogue = 80070317,
          Scripts = "TurnTo{TurnToDescription{\"790013:p(180)\"}}",
          SpeakNpcId = 790013,
          Subtitle = "And where are they now?",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729838"
        },
        [80070317] = {
          ContentFR = "Après tout ce temps, si elle me reposait la question, ma réponse serait la même. Dommage que je n’en aurai plus jamais l’occasion.",
          DialogueId = 80070317,
          GUID = "C8729862",
          NextDialogue = 80070318,
          Scripts = "PlayAnimation{_delay{2},ActorId{790013},AnimationId{\"Disagree\"},Duration{1}}",
          SpeakNpcId = 790013,
          Subtitle = "After all this time, if she were to ask me that question again, my answer would still be the same. Only now, there's no chance of that.",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729862"
        },
        [80070318] = {
          Camera = "42.315338,214.12384,94.9375,-0.0,-0.600128,-103.201942,35.000015,384.64978,false,Manual,7.401211",
          ContentFR = "Oh, j’ai entendu Randy dire que la Première Alchimiste est décédée, et que sa relation avec cette camarade était... compliquée.",
          DialogueId = 80070318,
          GUID = "C872988C",
          NextDialogue = 80070319,
          SpeakNpcId = 790014,
          Subtitle = "Right, I heard from Randy that the chief alchemist has passed away and that her relationship with her star pupil was... complicated.",
          TalkActionId = {
            [1] = "790014:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C872988C"
        },
        [80070319] = {
          ContentFR = "Oui. Tristement, même à sa mort, la préférée du professeur, cette camarade, n’est jamais venue. J’étais la seule, avec quelques corbeaux sinistres autour de la chambre d’hôpital.",
          DialogueId = 80070319,
          GUID = "C87298B6",
          NextDialogue = 80070320,
          SpeakNpcId = 790013,
          Subtitle = "Yes. Sadly, even when my teacher passed away, her favourite student — my fellow pupil — never showed up. It was just me there... along with a few ominous crows outside the hospital room.",
          TalkActionId = {
            [1] = "790013:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87298B6"
        },
        [80070320] = {
          ContentFR = "Encore plus triste, c’est que le professeur n’a jamais percé la formule symbolisant la vérité. Son travail monumental est devenu un gribouillis indéchiffrable.",
          DialogueId = 80070320,
          GUID = "C87298E0",
          NextDialogue = 80070321,
          SpeakNpcId = 790013,
          Subtitle = "What's sadder is that she never solved the formula that epitomized truth. Her monumental research ended up as indecipherable scribbles.",
          TalkActionId = {
            [1] = "790013:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87298E0"
        },
        [80070321] = {
          Camera = "149.89209,-233.861969,6.462891,0.000063,12.797854,113.801712,35.000008,100000.0,false,DoNotOverride,7.401211",
          ContentFR = "Elle a confié ses idéaux et ses rêves à cette camarade, mais elle est tombée en chemin, à la poursuite de la vérité. Et cette camarade, que fait-elle ?",
          DialogueId = 80070321,
          FinalCamera = "132.743332,-194.975647,16.105469,0.000063,12.797854,113.801628,35.000011,100000.0,false,DoNotOverride,7.401211",
          GUID = "C872990A",
          NextDialogue = 80070322,
          SpeakNpcId = 790013,
          Subtitle = "She entrusted her ideals and dreams to her, collapsing in her pursuit of truth. And what did she do?",
          TalkActionId = {
            [1] = "790013:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Xibi/003/C872990A"
        },
        [80070322] = {
          ContentFR = "Elle a tout abandonné : son statut, ses ressources, gaspillant son talent dans un domaine totalement différent.",
          DialogueId = 80070322,
          GUID = "C8729934",
          NextDialogue = 80070323,
          SpeakNpcId = 790013,
          Subtitle = "She abandoned her prospects and resources, wasting her talents in a completely different field.",
          TalkActionId = {
            [1] = "790013:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729934"
        },
        [80070323] = {
          Camera = "19.332775,-55.147057,119.476562,0.000024,0.000417,-99.596123,45.0,100000.0,false,DoNotOverride,10.901892",
          ContentFR = "Mais vous avez dit que vous ne viviez pas dans le passé.",
          DialogueId = 80070323,
          FacialId = {
            [1] = "790013:None"
          },
          GUID = "C872995E",
          NextDialogue = 80070324,
          SpeakNpcId = 790014,
          Subtitle = "Didn't you say you don't dwell on the past?",
          TalkActionId = {
            [1] = "790014:Explain01L_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C872995E"
        },
        [80070324] = {
          Camera = "68.539764,281.670898,93.375,0.0,5.399783,-108.200027,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est vrai, mais ça ne veut pas dire que je suis insensible. À chaque souvenir, montent en moi colère, incompréhension, regrets, et même jalousie.",
          DialogueId = 80070324,
          GUID = "C8729988",
          NextDialogue = 80070325,
          SpeakNpcId = 790013,
          Subtitle = "I did, but that doesn't mean I'm devoid of feelings. Every time I look back, I'm overwhelmed by a mix of anger, confusion, regret, and even jealousy.",
          TalkActionId = {
            [1] = "790014:Explain01L_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729988"
        },
        [80070325] = {
          ContentFR = "Je savais que je n’étais pas la meilleure élève, que les autres avaient des rêves, des ambitions, et un avenir plein de promesses.",
          DialogueId = 80070325,
          GUID = "C87299B2",
          NextDialogue = 80070326,
          SpeakNpcId = 790013,
          Subtitle = "I always knew I wasn't one of her best students, who had their dreams, their ambitions, and limitless prospects.",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87299B2"
        },
        [80070326] = {
          Camera = "93.881493,148.724472,103.033203,-0.000001,9.39976,-174.598511,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais je sais que je serai celle qui ira jusqu’au bout.",
          DialogueId = 80070326,
          FacialId = {
            [1] = "790013:None"
          },
          GUID = "C87299DC",
          NextDialogue = 80070327,
          SpeakNpcId = 790013,
          Subtitle = "But I know I'll be the one who makes it to the end.",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C87299DC"
        },
        [80070327] = {
          Camera = "68.550446,-309.161438,92.363281,0.000028,-0.200043,106.210785,45.000011,451.021332,false,Manual,5.197097",
          ContentFR = "... Au fait, même si je sais que tu ne parleras pas de ça à qui que ce soit, je te le rappelle, garde ça pour toi.",
          DialogueId = 80070327,
          GUID = "C8729A06",
          LookAt = {
            [1] = "790013:n(790014)"
          },
          NextDialogue = 80070328,
          SpeakNpcId = 790013,
          Subtitle = "By the way, though I know you wouldn't mention this conversation to anyone, I still have to remind you to keep it between us.",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729A06"
        },
        [80070328] = {
          Camera = "28.509796,241.818237,128.292969,0.000024,-3.59966,-101.194298,45.0,100000.0,false,Manual,16.626261",
          ContentFR = "Je sais, je sais, je n’ai personne à qui en parler. Mais si vous ne voulez pas que les autres sachent, pourquoi me dire tout ça ?",
          DialogueId = 80070328,
          GUID = "C8729A30",
          NextDialogue = 80070329,
          SpeakNpcId = 790014,
          Subtitle = "Understood! I don't really have anyone to talk to anyway. But I'm curious, Chief — if you don't want anyone to know, why share all this with me?",
          TalkActionId = {
            [1] = "790014:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729A30"
        },
        [80070329] = {
          ContentFR = "Parce que tu es la seule qui convienne pour ça. Je sais que tu ne t’intéresses pas aux histoires compliquées ni aux émotions, et que tu ne vas pas faire de jolies phrases pleines d’empathie, qu’elles soient sincères ou non.",
          DialogueId = 80070329,
          GUID = "C8729A5A",
          NextDialogue = 80070330,
          SpeakNpcId = 790013,
          Subtitle = "Because you're the right person for this. I know you don't care about nor understand those complex past events and emotions, and you're not one to offer empty sympathies, sincere or not.",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729A5A"
        },
        [80070330] = {
          Camera = "20.92244,-217.006439,116.833984,0.000028,-1.999476,97.407928,45.000011,359.358795,false,Manual,10.901892",
          ContentFR = "Je n’ai jamais eu besoin de la pitié de qui que ce soit.",
          DialogueId = 80070330,
          GUID = "C8729A84",
          NextDialogue = 80070331,
          SpeakNpcId = 790013,
          Subtitle = "I've never needed any sympathy or pity from anyone.",
          TurnTo = {
            [1] = "790013:n(790014)"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729A84"
        },
        [80070331] = {
          ContentFR = "Au final, on ne peut compter que sur ce qu’on tient entre nos mains. Je crois que tu comprends ça.",
          DialogueId = 80070331,
          GUID = "C8729AAE",
          NextDialogue = 80070332,
          SpeakNpcId = 790013,
          Subtitle = "All we can truly rely on is what we wield. I think you understand that too.",
          TalkActionId = {
            [1] = "790013:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729AAE"
        },
        [80070332] = {
          Camera = "1185.878418,-1058.124756,135.4375,0.000004,-0.200466,138.797653,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Voilà pour aujourd’hui. Si jamais tu doutes, tu peux toujours venir m’en parler.",
          DialogueId = 80070332,
          FinalCamera = "1255.99585,-1119.513062,135.765625,0.0,-0.200466,138.797638,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8729AD8",
          NextDialogue = 80070333,
          SpeakNpcId = 790013,
          Subtitle = "That will be all for today. If you ever feel lost, you're welcome to talk to me.",
          TalkActionId = {
            [1] = "790013:Angry01_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729AD8"
        },
        [80070333] = {
          ContentFR = "Je ne te réconforterai pas, mais je peux t’aider à trouver des solutions.",
          DialogueId = 80070333,
          GUID = "C8729B02",
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0067_story_daphnis_theme_piano\"}}",
          SpeakNpcId = 790013,
          Subtitle = "While I may not offer comfort, I can guide you through resolving your doubts.",
          VoiceName = "voice/$Locale$/inv/Xibi/003/C8729B02"
        },
        [80080101] = {
          Camera = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Je n’avais jamais vu un Souillé aussi énorme... J’avais la tête qui bourdonnait, les bras et les jambes paralysés. Je sais que je vais bientôt retourner à la Mer du Silence, auprès de Mère Embla... mais je ne pensais pas que ce jour arriverait si vite.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080101,
          GUID = "C878DD92",
          NextDialogue = 80080102,
          SpeakNpcId = 790004,
          Subtitle = "I'd never seen such a huge Filthoid before... My head was spinning, and I couldn't move my arms or legs. I knew I'd soon be returning to the Misty Sea and the bosom of Mother Embla, but I didn't expect that day to come so soon.",
          TalkActionId = {
            [1] = "790004:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DD92"
        },
        [80080102] = {
          Camera = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et puis, {性别:il|elle} a surgi d’un coup ! Quand j’ai rouvert les yeux, {性别:il|elle} se tenait déjà devant moi pour me protéger !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080102,
          GUID = "C878DDBC",
          NextDialogue = 80080103,
          SpeakNpcId = 790004,
          Subtitle = "Then — {性别:he|she} suddenly charged forward. When I opened my eyes, {性别:he|she} was already shielding me from that Filthoid!",
          TalkActionId = {
            [1] = "790004:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DDBC"
        },
        [80080103] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{性别:Il|Elle} n’est pas bien costaud, pourtant... mais {性别:il|elle} a tenu tête au Souillé sans reculer d’un pas...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080103,
          GUID = "C878DDE6",
          NextDialogue = 80080104,
          Scripts = "SEQ{PlayAnimation{ActorId{790004},AnimationId{\"Disagree\"},Duration{2}},PlayAnimation{ActorId{790004},AnimationId{\"Explain02_Start\"},Duration{3}},PlayAnimation{ActorId{790004},AnimationId{\"Explain02_End\"},Duration{1}}}",
          SpeakNpcId = 790004,
          Subtitle = "{性别:He|She} wasn't exactly strong, but {性别:he|she} bravely stared down the Filthoid, not backing down an inch...",
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DDE6"
        },
        [80080104] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et ensuite, ce gros machin a sauté et frappé le sol, vous êtes tombés ensemble, puis vous vous êtes battus côte à côte et vous l’avez vaincu. Et après, un type appelé l’Étranger a débarqué. Et ensuite...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080104,
          GUID = "C878DE10",
          NextDialogue = 80080105,
          SpeakNpcId = 790002,
          Subtitle = "And then that giant Filthoid leapt up, slammed down, and you both fell. Then you fought side by side and took it down. Then a man named Outsider popped up. And then—",
          TalkActionId = {
            [1] = "790002:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DE10"
        },
        [80080105] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Elisa ! Ne me coupe pas, tu vas gâcher la surprise !",
          DialogueId = 80080105,
          GUID = "C878DE3A",
          NextDialogue = 80080106,
          SpeakNpcId = 790004,
          Subtitle = "Aw, Elisa! No spoilers, please!",
          TalkActionId = {
            [1] = "790004:Sigh_Start",
            [2] = "790002:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DE3A"
        },
        [80080106] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est la troisième fois que tu racontes ton expédition dans la Fosse de Glevum... mes oreilles vont finir par faner.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080106,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878DE64",
          NextDialogue = 80080107,
          SpeakNpcId = 790002,
          Subtitle = "You've told your Glevum Pit adventure three times already. I wish I had a coin for every time you told that story...",
          TalkActionId = {
            [1] = "790002:Talk02_Start",
            [2] = "790004:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DE64"
        },
        [80080107] = {
          Camera = "-182.740234,418.929565,109.427734,0.000006,0.00002,-72.598679,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Pa-parce que je l’ai pas encore racontée à Fred... Voilà pourquoi, oui.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080107,
          GUID = "C878DE8E",
          NextDialogue = 80080108,
          SpeakNpcId = 790004,
          Subtitle = "Well, I haven't told Fred yet, so... Um, right, that's what happened in the pit.",
          TalkActionId = {
            [1] = "790002:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DE8E"
        },
        [80080108] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Psyche, tu l’aimes bien, {性别:ce nouvel ami|cette nouvelle amie}, pas vrai ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080108,
          GUID = "C878DEB8",
          NextDialogue = 80080109,
          SpeakNpcId = 790001,
          Subtitle = "You must really like your new friend, Psyche.",
          TalkActionId = {
            [1] = "790001:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DEB8"
        },
        [80080109] = {
          Camera = "-330.722656,-239.585709,105.560547,0.000012,0.0,51.204865,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu parles encore plus que d’habitude aujourd’hui... et pourtant, tu parles déjà beaucoup.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080109,
          GUID = "C878DEE2",
          NextDialogue = 80080110,
          SpeakNpcId = 790001,
          Subtitle = "Because you're especially talkative today, not that you're ever really quiet...",
          TalkActionId = {
            [1] = "790001:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DEE2"
        },
        [80080110] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Euh... je-je parle tant que ça... ?",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080110,
          GUID = "C878DF0C",
          NextDialogue = 80080111,
          SpeakNpcId = 790004,
          Subtitle = "...Um, am I?",
          TalkActionId = {
            [1] = "790001:Explain01_End",
            [2] = "790004:Shock_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DF0C"
        },
        [80080111] = {
          Camera = "-293.373047,-99.673187,105.125,0.0,0.200002,27.605503,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je n’ai effectivement jamais entendu cette histoire. Laissons Psyche terminer.",
          DialogueId = 80080111,
          GUID = "C878DF36",
          LookAt = {
            [1] = "790003:n(790004)",
            [2] = "790004:n(790003)"
          },
          NextDialogue = 80080112,
          SpeakNpcId = 790003,
          Subtitle = "I've indeed never heard this story before. Let Psyche finish.",
          TalkActionId = {
            [1] = "790004:Shock_End",
            [2] = "790003:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DF36"
        },
        [80080112] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui ! Alors, où j’en étais... Ah, Elisa a déjà raconté toute la fin.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080112,
          GUID = "C878DF60",
          LookAt = {
            [1] = "790004:n(790002)"
          },
          NextDialogue = 80080113,
          SpeakNpcId = 790004,
          Subtitle = "Alright! Now, where was I... Oh, Elisa already finished the second half for me.",
          TalkActionId = {
            [1] = "790004:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DF60"
        },
        [80080113] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais attends... je me souviens d’un truc que j’ai pas encore dit ! Cette personne ne venait pas d’ici, mais d’un endroit bien plus loin qu’Hyperborea, une petite île au sud !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080113,
          FacialId = {
            [1] = "790004:Happy01"
          },
          GUID = "C878DF8A",
          NextDialogue = 80080114,
          SpeakNpcId = 790004,
          Subtitle = "Ooh! I just thought of something I haven't told you guys — that person isn't from around here but from a place far beyond Hyperborea — a small island to the south!",
          TalkActionId = {
            [1] = "790004:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878DF8A"
        },
        [80080114] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{性别:Il|Elle} m’a dit que là-bas, le sable est doré, et il y a du romarin blanc qui pousse partout... Et puis la mer ! Immense, comme si cent Lacs du Deuil s’étaient unis !",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080114,
          FacialId = {
