          GUID = "C878E476",
          LookAt = {
            [1] = "790004:n(790001)",
            [2] = "790003:n(790004)",
            [3] = "790002:n(790001)",
            [4] = "790001:n(790004)"
          },
          NextDialogue = 80080144,
          SpeakNpcId = 790001,
          Subtitle = "And about the Heaventree.",
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E476"
        },
        [80080144] = {
          Camera = "-115.056641,157.29718,104.279297,0.000006,2.600007,-78.7966,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui, oui, c’est noté... La prochaine fois, je lui demanderai tout ça pour vous.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080144,
          FacialId = {
            [1] = "790004:Smile01"
          },
          GUID = "C878E4A0",
          LookAt = {
            [1] = "790004:n(790002)"
          },
          SpeakNpcId = 790004,
          Subtitle = "Sure! I'll keep all this in mind. I'll ask for you next time I see {性别:him|her}.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/001/C878E4A0"
        },
        [80080201] = {
          Camera = "152.138672,195.628784,134.539062,0.0,-1.200071,-127.200096,35.000008,100000.0,false,DoNotOverride,2.8",
          CameraBlendCurve = "linear",
          ContentFR = "Elisa, je suis rentrée.",
          DialogueId = 80080201,
          FinalCamera = "131.03125,210.858398,134.539062,0.0,-1.000056,-125.00016,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C878EDFA",
          NextDialogue = 80080202,
          Scripts = "SEQ{MoveTo{ActorId{790004},MoveSpeed{75},TargetPoint{\"QuestPoint_530102\"}},TurnTo{TurnToDescription{\"790004:n(790006)\"}}}",
          SpeakNpcId = 790004,
          Subtitle = "Elisa, I'm back.",
          ToFinalCameraBlendTime = 2,
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EDFA"
        },
        [80080202] = {
          Camera = "-81.119141,-25.830444,135.263672,0.0,0.599909,-131.198853,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tiens, du pain ! Allez, mange, je parie que t’as encore sauté un repas. Je reste ici et je te regarde jusqu’à ce que tu aies tout fini !",
          DialogueId = 80080202,
          GUID = "C878EE24",
          NextDialogue = 80080203,
          SpeakNpcId = 790004,
          Subtitle = "I brought you some bread — I bet you've skipped the meals again. I'm not going anywhere until you finish it.",
          TalkActionId = {
            [1] = "790004:Give"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EE24"
        },
        [80080203] = {
          Camera = "131.03125,210.858398,134.539062,0.0,-1.000056,-125.00016,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... À quoi bon... Dans l’état où on est, manger, c’est du gâchis.",
          DialogueId = 80080203,
          GUID = "C878EE4E",
          NextDialogue = 80080204,
          SpeakNpcId = 790006,
          Subtitle = "Why waste food... We're all going to leave the world soon anyway.",
          TalkActionId = {
            [1] = "790006:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EE4E"
        },
        [80080204] = {
          Camera = "131.03125,210.858398,134.539062,0.0,-1.000056,-125.00016,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Faut pas dire ça... Regarde cette plante, là-bas ! Même si on sait qu’elle finira par faner, on continue quand même à l’arroser, à la nourrir, pour qu’elle reste jolie, pas vrai ?",
          DialogueId = 80080204,
          GUID = "C878EE78",
          NextDialogue = 80080205,
          SpeakNpcId = 790004,
          Subtitle = "Don't say that... Do you see that plant over there? It'll eventually wither for sure, but we still water and take care of it so that it'll bloom one day.",
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EE78"
        },
        [80080205] = {
          Camera = "-0.818359,59.526489,190.207031,0.000001,-10.400117,20.598642,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et si elle ne fleurit jamais ?",
          DialogueId = 80080205,
          FinalCamera = "-0.818359,59.526489,206.207031,0.000001,-10.400117,20.598642,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C878EEA2",
          NextDialogue = 80080206,
          SpeakNpcId = 790006,
          Subtitle = "But what if it never blooms?",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EEA2"
        },
        [80080206] = {
          Camera = "-78.357422,-27.765015,126.353516,0.000021,3.399993,-132.00238,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors, la voir germer, grandir un peu... c’est déjà merveilleux, non ?",
          DialogueId = 80080206,
          GUID = "C878EECC",
          NextDialogue = 80080207,
          SpeakNpcId = 790004,
          Subtitle = "Then, just watching it sprout and grow bigger is still wonderful, isn't it?",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EECC"
        },
        [80080207] = {
          Camera = "-263.033203,-174.554382,138.316406,0.000001,-1.800322,23.388023,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Laisse tomber. Je m’y connais pas autant que toi en plantes.",
          DialogueId = 80080207,
          GUID = "C878EEF6",
          NextDialogue = 80080208,
          SpeakNpcId = 790006,
          Subtitle = "...Forget it. I don't have your green thumb.",
          TalkActionId = {
            [1] = "790004:Explain02_End",
            [2] = "790006:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EEF6"
        },
        [80080208] = {
          Camera = "-263.033203,-174.554382,138.316406,0.000001,-1.800322,23.388023,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et cette personne, elle est venue faire quoi tout à l’heure ? C’est pas un Dégradé, et pourtant {性别:il|elle} vient sans arrêt... Tu crois pas que ce serait {性别:un espion|une espionne} du Bureau de la Sécurité ?",
          DialogueId = 80080208,
          GUID = "C878EF20",
          NextDialogue = 80080209,
          SpeakNpcId = 790006,
          Subtitle = "By the way, why was that person here earlier? {性别:He|She} is not a Deteriorator, so why the frequent visits? Is {性别:he|she} a spy for the Security Bureau?",
          TurnTo = {
            [1] = "790006:n(790004)"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EF20"
        },
        [80080209] = {
          Camera = "26.732422,82.374146,145.716797,0.000007,-5.80006,-125.792847,30.000002,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu parles de {nickname} ? {性别:Il|Elle} vient de l’extérieur, maintenant {性别:il est Chasseur de Phoxène|elle est Chasseuse de Phoxène}. Aucun lien avec le Bureau, t’en fais pas. Cette fois, je crois que c’était pour une mission...",
          DialogueId = 80080209,
          GUID = "C878EF4A",
          NextDialogue = 80080210,
          SpeakNpcId = 790004,
          Subtitle = "You mean ? {性别:He|She}'s not a local. {性别:He|She} now works as a Phoxhunter and has nothing to do with the Security Bureau. I think {性别:he|she} was here for a commission.",
          TalkActionId = {
            [1] = "790004:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EF4A"
        },
        [80080210] = {
          Camera = "26.732422,82.374146,145.716797,0.000007,-5.80006,-125.792847,30.000002,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Apparemment, {性别:il|elle} a trouvé ce dont le Docteur Henrik avait besoin. Si ça peut aider, alors peut-être que... non, rien.",
          DialogueId = 80080210,
          GUID = "C878EF74",
          NextDialogue = 80080211,
          SpeakNpcId = 790004,
          Subtitle = "I heard {性别:he|she} found something Dr Henrik needs. If it helps, maybe we... um, never mind.",
          TalkActionId = {
            [1] = "790004:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EF74"
        },
        [80080211] = {
          Camera = "-147.058594,-85.52063,138.552734,0.000007,-0.200043,29.804741,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "T’as dit hier que t’étais sortie de la ville avec {性别:lui|elle}, et qu’en rentrant, le Docteur Henrik t’avait passé un sacré savon, non ?",
          DialogueId = 80080211,
          GUID = "C878EF9E",
          NextDialogue = 80080212,
          SpeakNpcId = 790006,
          Subtitle = "Didn't you say you went out of town with that person yesterday and got an earful from Dr Henrik?",
          TalkActionId = {
            [1] = "790006:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EF9E"
        },
        [80080212] = {
          Camera = "-160.625,-5.968567,134.414062,0.000007,0.199988,-105.995361,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hein... ? Oui...",
          DialogueId = 80080212,
          GUID = "C878EFC8",
          NextDialogue = 80080213,
          SpeakNpcId = 790004,
          Subtitle = "Huh? Um, yes...",
          TalkActionId = {
            [1] = "790004:Shock_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EFC8"
        },
        [80080213] = {
          Camera = "-164.548828,-79.17041,134.091797,0.000007,0.80002,25.802954,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et malgré ça, tu t’occupes encore de ses affaires ? {性别:Il|Elle} n’est ni Dégradé ni un agent du Bureau de la Sécurité, {性别:il|elle} n’a rien à voir avec nous, non ?",
          DialogueId = 80080213,
          GUID = "C878EFF2",
          NextDialogue = 80080214,
          SpeakNpcId = 790006,
          Subtitle = "Then why still mix up with {性别:him|her}? Since {性别:he|she}'s not one of us and not with the Security Bureau, {性别:he|she} has nothing to do with us, right?",
          TalkActionId = {
            [1] = "790004:Shock_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878EFF2"
        },
        [80080214] = {
          Camera = "22.615234,70.785767,148.324219,0.000011,-8.000091,-127.191437,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je... je voulais juste voir si je pouvais aider un peu...",
          DialogueId = 80080214,
          GUID = "C878F01C",
          NextDialogue = 80080215,
          SpeakNpcId = 790004,
          Subtitle = "I... I just thought there might be something I could do—",
          TalkActionId = {
            [1] = "790006:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F01C"
        },
        [80080215] = {
          Camera = "-266.458984,-177.625977,138.392578,0.000013,-3.601074,26.590097,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Psyche, franchement, je te comprends pas.",
          DialogueId = 80080215,
          GUID = "C878F046",
          NextDialogue = 80080216,
          SpeakNpcId = 790006,
          Subtitle = "Honestly, Psyche, I don't understand you sometimes.",
          TalkActionId = {
            [1] = "790006:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F046"
        },
        [80080216] = {
          Camera = "-266.458984,-177.625977,138.392578,0.000013,-3.601074,26.590097,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{nickname}, c’est juste {性别:un étranger de passage. Peut-être que demain, il sera déjà reparti. Et puis, il|une étrangère de passage. Peut-être que demain, elle sera déjà repartie. Et puis, elle} saura même pas ce qui va... t’arriver. Quant à nous... on sait bien qu’on n’en a plus pour longtemps.",
          DialogueId = 80080216,
          GUID = "C878F070",
          NextDialogue = 80080217,
          SpeakNpcId = 790006,
          Subtitle = "{性别:He|She} is just a stranger, and might just leave Icelake tomorrow. {性别:He|She} doesn't even know... what will happen to you... You know it — everyone here is not long for this world.",
          TalkActionId = {
            [1] = "790006:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F070"
        },
        [80080217] = {
          Camera = "-266.458984,-177.625977,138.392578,0.000013,-3.601074,26.590097,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu passes ton temps à aider tout le monde, à offrir des fleurs, à préparer à manger, à raconter des histoires, à chercher un toit pour les voyageurs... Mais à quoi bon ?",
          DialogueId = 80080217,
          GUID = "C878F09A",
          NextDialogue = 80080218,
          SpeakNpcId = 790006,
          Subtitle = "Yet you're always out helping others, giving away flowers, making meals, telling stories, helping travellers with accommodations... What's the point?",
          TalkActionId = {
            [1] = "790006:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F09A"
        },
        [80080218] = {
          Camera = "-266.458984,-177.625977,138.392578,0.000013,-3.601074,26.590097,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu devrais penser un peu plus à toi.",
          DialogueId = 80080218,
          GUID = "C878F0C4",
          NextDialogue = 80080219,
          SpeakNpcId = 790006,
          Subtitle = "Maybe you should stop meddling in other people's business and focus on yourself more.",
          TalkActionId = {
            [1] = "790006:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F0C4"
        },
        [80080219] = {
          Camera = "-168.683594,-113.112,154.904297,0.000071,-9.99997,-127.581398,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Tu n’as pas tort...",
          DialogueId = 80080219,
          FacialId = {
            [1] = "790004:Unhappy01"
          },
          GUID = "C878F0EE",
          NextDialogue = 80080220,
          SpeakNpcId = 790004,
          Subtitle = "...You have a point.",
          TalkActionId = {
            [1] = "790004:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F0EE"
        },
        [80080220] = {
          Camera = "-168.683594,-113.112,154.904297,0.000071,-9.99997,-127.581398,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais... y’a peut-être un truc que tu comprends pas. Je ne suis pas aussi altruiste que tu le crois.",
          DialogueId = 80080220,
          GUID = "C878F118",
          NextDialogue = 80080221,
          SpeakNpcId = 790004,
          Subtitle = "But you got one thing wrong — I'm not as selfless as you think.",
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F118"
        },
        [80080221] = {
          Camera = "-168.683594,-113.112,154.904297,0.000071,-9.99997,-127.581398,30.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "En fait... c’est pour moi que je fais tout ça.",
          DialogueId = 80080221,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878F142",
          NextDialogue = 80080222,
          SpeakNpcId = 790004,
          Subtitle = "To be more precise... I did all those things for myself.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F142"
        },
        [80080222] = {
          Camera = "37.734375,86.957642,146.630859,0.000001,-5.400023,-127.39193,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai pas peur de mourir, enfin si, c’est pas vrai... j’ai peur, quand même.",
          DialogueId = 80080222,
          GUID = "C878F16C",
          NextDialogue = 80080223,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790004},AnimationId{"Explain02_End"},Duration{1}},
PlayAnimation{ActorId{790004},AnimationId{"DisagreeHead"},Duration{1}}
}]],
          SpeakNpcId = 790004,
          Subtitle = "I'm not afraid of dying — no, that's an overstatement... I am afraid.",
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F16C"
        },
        [80080223] = {
          Camera = "-130.748047,-103.410034,139.367188,0.00001,3.199786,-140.194809,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais ce qui me fait encore plus peur que la mort, c’est... disparaître. Si plus personne ne se souvient de toi, c’est comme si t’avais jamais existé.",
          DialogueId = 80080223,
          GUID = "C878F196",
          NextDialogue = 80080224,
          SpeakNpcId = 790004,
          Subtitle = "But what terrifies me even more than death is... the idea of \"disappearing.\" Once you're forgotten, it's like the very evidence of your existence just gets wiped away.",
          TalkActionId = {
            [1] = "790004:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F196"
        },
        [80080224] = {
          Camera = "-142.1875,-33.322571,140.789062,0.0,0.0,12.604458,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors tu fais tout ça dans l’espoir qu’on se souvienne de toi ? Même si c’est qu’une personne, même si c’est pour un jour de plus ?",
          DialogueId = 80080224,
          GUID = "C878F1C0",
          NextDialogue = 80080225,
          SpeakNpcId = 790006,
          Subtitle = "So you go out of your way to help as many people as possible, hoping they'll remember you for as long as they can — is that it?",
          TalkActionId = {
            [1] = "790004:Explain01_End",
            [2] = "790006:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F1C0"
        },
        [80080225] = {
          Camera = "-162.773438,-40.854614,119.160156,0.000047,10.199575,-109.797279,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oui... En vérité, je suis égoïste. Tu as raison, {性别:il|elle} finira par partir.",
          DialogueId = 80080225,
          GUID = "C878F1EA",
          NextDialogue = 80080226,
          SpeakNpcId = 790004,
          Subtitle = "Yes... I'm actually... very selfish. You're right, {性别:he|she} will leave one day.",
          TalkActionId = {
            [1] = "790004:Agree",
            [2] = "790006:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F1EA"
        },
        [80080226] = {
          Camera = "-162.773438,-40.854614,119.160156,0.000047,10.199575,-109.797279,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{性别:Il vient pas d’ici, je l’ai toujours su. Il est différent. Il restera pas coincé ici comme nous.|Elle vient pas d’ici, je l’ai toujours su. Elle est différente. Elle restera pas coincée ici comme nous.}",
          DialogueId = 80080226,
          GUID = "C878F214",
          NextDialogue = 80080227,
          SpeakNpcId = 790004,
          Subtitle = "{性别:He|She} doesn't belong here. I've always known that {性别:he|she} is different — unlike us, trapped in Icelake forever.",
          TalkActionId = {
            [1] = "790004:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F214"
        },
        [80080227] = {
          Camera = "-162.773438,-40.854614,119.160156,0.000047,10.199575,-109.797279,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "{性别:C’est justement pour ça que je voulais devenir ami avec lui... Comme ça, il emmènera avec lui mes souvenirs, dans tous les endroits où il ira.|C’est justement pour ça que je voulais devenir amie avec elle... Comme ça, elle emmènera avec elle mes souvenirs, dans tous les endroits où elle ira.}",
          DialogueId = 80080227,
          GUID = "C878F23E",
          NextDialogue = 80080228,
          SpeakNpcId = 790004,
          Subtitle = "And that's exactly why I want to be friends with {性别:him|her} — so that {性别:he|she} will carry memories of me while going on wonderful adventures around the world.",
          TalkActionId = {
            [1] = "790004:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F23E"
        },
        [80080228] = {
          Camera = "-2481.224609,-566.944275,10.640625,0.0,1.999715,-93.189522,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Dans les livres, ils disent qu’au nord, à Askard, il y a un soleil qui ne se couche jamais. Qu’au sud, à Élysium, il y a une tour plus haute que les montagnes. Et qu’à l’est, à Huaxu, des navires s’envolent vers les étoiles...",
          DialogueId = 80080228,
          FinalCamera = "-2069.626953,-579.504761,10.279297,0.0,1.999715,-93.189522,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "C878F268",
          NextDialogue = 80080229,
          SpeakNpcId = 790004,
          Subtitle = "I've read about the never-setting sun in Askard to the north, the cloud-capped tower of Elysium down the south, and further east, the star-bound ships of Huaxu...",
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F268"
        },
        [80080229] = {
          Camera = "-142.1875,-33.322571,140.789062,0.0,0.0,12.604458,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais toi, tu ne seras plus là.",
          DialogueId = 80080229,
          GUID = "C878F292",
          NextDialogue = 80080230,
          SpeakNpcId = 790006,
          Subtitle = "But you'll be gone by then.",
          TalkActionId = {
            [1] = "790004:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/002/C878F292"
        },
        [80080230] = {
          Camera = "28.722656,72.22937,144.703125,0.00001,-5.200185,-127.592773,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais je vivrai dans ses souvenirs. Alors, quelque part, ma vie continuera avec {性别:lui|elle}.",
          DialogueId = 80080230,
          GUID = "C878F2BC",
          NextDialogue = 80080231,
          SpeakNpcId = 790004,
          Subtitle = "But I'll live on in {性别:his|her} memories. That way, it's like my life continues with {性别:him|her}.",
