          ContentFR = "Mais je sais que, même si {性别:il|elle} était là, devant moi, {性别:il|elle} était en fait très loin, aussi loin que Givrelac est de l’océan.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080306,
          GUID = "C878FF34",
          LookAt = {
            [1] = "790004:n(790004)"
          },
          NextDialogue = 80080307,
          SpeakNpcId = 790004,
          Subtitle = "But I know that even though {性别:he|she} was right in front of me, {性别:he|she} was actually very far away, as far as Icelake is from the ocean.",
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FF34"
        },
        [80080307] = {
          Camera = "-252.96875,-122.314819,187.210938,0.000079,-18.400009,32.607815,32.000004,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Alors, même si {性别:il m’a tendu|elle m’a tendue} la main, je ne pouvais pas vraiment la saisir. C’est comme si je fixais son visage sans rien voir.",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080307,
          FacialId = {
            [1] = "790004:None"
          },
          GUID = "C878FF5E",
          LookAt = {
