          ContentFR = "Déjà ? Je pensais que la recherche prendrait plus de temps...",
          DefaultLookAt = "TalkNpc",
          DialogueId = 80080310,
          FacialId = {
            [1] = "790004:Shock01"
          },
          GUID = "C878FFDC",
          NextDialogue = 80080311,
          SpeakNpcId = 790004,
          Subtitle = "Already? I thought the research would take longer...",
          TalkActionId = {
            [1] = "790004:Alright_Start"
          },
          VoiceName = "voice/$Locale$/inv/Saiqi/003/C878FFDC"
        },
        [80080311] = {
          Camera = "-96.466797,191.58667,114.650391,0.000046,4.999999,-93.795868,32.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "J’ai commencé il y a des années, mais j’ai mis ça de côté après la mort de Hayley. C’est pour toi... pour vous tous, que je m’y suis remis.",
