        },
        [80110104] = {
          ContentFR = "Attends... t’as dit \"Légion\"...",
          DialogueId = 80110104,
          FacialId = {
            [1] = "93101:Doubt01"
          },
          GUID = "C88C17F0",
          NextDialogue = 80110105,
          SpeakNpcId = 93101,
