          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C17F0"
        },
        [80110105] = {
          ContentFR = "... Qu’est-ce que tu veux ? Quel est ton plan ? Qui es-tu ? Qui t’envoie ? Tu cherches quoi comme infos ? Vas-y, cause.",
          DialogueId = 80110105,
          GUID = "C88C181A",
          NextOptions = {
            [1] = 801101051,
            [2] = 801101052
          },
          SpeakNpcId = 93101,
          Subtitle = "...What do you want? What are you planning? Who are you? Who sent you? What intel are you after? Spill it.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C181A"
        },
        [80110106] = {
          ContentFR = "Pour {性别:un simple Chasseur de Phoxène|une simple Chasseuse de Phoxène}, tu en sais un peu trop.",
          DialogueId = 80110106,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1844",
          NextDialogue = 80110107,
          SpeakNpcId = 93101,
          Subtitle = "You're too well-informed for a mere Phoxhunter.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1844"
        },
        [80110107] = {
          ContentFR = "... Je me doutais bien que ce n’était pas gratuit, personne ne fait de cadeaux sans attendre quelque chose en retour.",
          DialogueId = 80110107,
          GUID = "C88C186E",
          NextDialogue = 80110108,
          SpeakNpcId = 93101,
          Subtitle = "…I should've known. No one offers gifts without wanting something in return.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C186E"
        },
        [80110108] = {
          ContentFR = "Allez, viens avec moi pour un interrogatoire à la Légion. Sois {性别:coopératif|coopérative}, sinon je te passerai les menottes, et ça va pas être joli pour nous deux.",
          DialogueId = 80110108,
          FacialId = {
            [1] = "93101:Confident01"
          },
          GUID = "C88C1898",
          NextDialogue = 80110109,
          SpeakNpcId = 93101,
          Subtitle = "Time to take you to the Legion for questioning. Cooperate, and don't make me tie you up — it won't look good for either of us.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1898"
        },
        [80110109] = {
          ContentFR = "<I>Lynn sort son flingue sans prévenir, le canon noir braqué sur ton front, cette image te traverse l’esprit. </>",
          DialogueId = 80110109,
          GUID = "C88C18C2",
          IsBlack = 1,
          NextDialogue = 80110110,
          Subtitle = "(The following quickly flashes through your mind: Lynn takes out her gun immediately, and the dark muzzle is pointed straight at your forehead.)",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C18C2"
        },
        [80110110] = {
          ContentFR = "<I>C’est le scénario inévitable. Tu secoues la tête, renonçant à ce coup trop risqué pour soutirer des infos.</>",
          DialogueId = 80110110,
          GUID = "C88C18EC",
          IsBlack = 1,
          NextDialogue = 80110111,
          Subtitle = "(This outcome is predictable. You shook your head and dismissed the risky idea to keep fishing out intel from her.)",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C18EC"
        },
        [80110111] = {
          ContentFR = "Tu te méprends, je t’ai juste vue et je voulais t’inviter à boire un verre.",
          DialogueId = 80110111,
          GUID = "C88C1916",
          NextDialogue = 80110112,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "You've got it wrong. I just saw you and thought I'd invite you for a drink.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1916"
        },
        [80110112] = {
          ContentFR = "...",
          DialogueId = 80110112,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1940",
          NextDialogue = 80110113,
          SpeakNpcId = 93101,
          Subtitle = "......",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1940"
        },
        [80110113] = {
          ContentFR = "Ouais, j’étais trop nerveuse... Pardon.",
          DialogueId = 80110113,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C196A",
          NextDialogue = 80110114,
          SpeakNpcId = 93101,
          Subtitle = "Guess I was too on edge. Ahem, sorry about that.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C196A"
        },
        [80110114] = {
          ContentFR = "Y’a déjà eu des Chasseurs de Phoxène assez audacieux qui, sachant que j’en étais une avant, ont essayé de me soutirer des secrets de la Légion.",
          DialogueId = 80110114,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1994",
          NextOptions = {
            [1] = 801101141,
            [2] = 801101142
          },
          SpeakNpcId = 93101,
          Subtitle = "It's just there have been some audacious Phoxhunters who, seeing that I was one of them, tried to get close to me and fish for the secrets of the legion.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1994"
        },
        [80110115] = {
          ContentFR = "Ouais, ça fait un bail... Peut-être que j’aurais pas dû dire ça.",
          DialogueId = 80110115,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C19BE",
          NextDialogue = 80110116,
          SpeakNpcId = 93101,
          Subtitle = "Yeah, that was years ago. Wait, should I reveal this to others?",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C19BE"
        },
        [80110116] = {
          ContentFR = "... Tant pis, la Légion oblige pas à cacher son passé.",
          DialogueId = 80110116,
          GUID = "C88C19E8",
          NextOptions = {
            [1] = 801101161
          },
          SpeakNpcId = 93101,
          Subtitle = "...Never mind. The Legion doesn't say we have to hide who we were.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C19E8"
        },
        [80110117] = {
          ContentFR = "Ah, tu n’as aucune idée de ce que c’est, la Légion.",
          DialogueId = 80110117,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C1A12",
          NextDialogue = 80110118,
          SpeakNpcId = 93101,
          Subtitle = "Ugh, you have no idea what it's like in the Legion.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A12"
        },
        [80110118] = {
          ContentFR = "Les camps de la Légion sont entourés de clôtures électriques en Phoxichor, ça crépite, ça empêche les déserteurs, les voleurs, et aussi les espions.",
          DialogueId = 80110118,
          GUID = "C88C1A3C",
          NextDialogue = 80110119,
          SpeakNpcId = 93101,
          Subtitle = "Legion camps are surrounded by electric fences powered by Phoxichor. They crackle with sparks, detering deserters, as well as discouraging thieves and spies.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A3C"
        },
        [80110119] = {
          ContentFR = "Mais au moins, ces grillages, tu les vois venir. Le vrai danger, c’est la couche invisible, tu fais une erreur, tu dis une bêtise, et paf, t’es grillé.",
          DialogueId = 80110119,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1A66",
          NextDialogue = 80110120,
          SpeakNpcId = 93101,
          Subtitle = "But at least you can see those fences. It's the invisible ones you have to worry about — if you slip up, say the wrong thing, one zap, and you're gone.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A66"
        },
        [80110120] = {
          ContentFR = "Surtout que ma supérieure déteste les traîtres. Je veux pas finir grillée pour une fuite par accident.",
          DialogueId = 80110120,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C1A90",
          NextOptions = {
            [1] = 801101201,
            [2] = 801101202
          },
          SpeakNpcId = 93101,
          Subtitle = "My supreme officer has something personal against traitors. I don't want to end up dead over some accidental leak.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A90"
        },
        [80110121] = {
          ContentFR = "Tu rigoles ? C’est pas comme si j’avais eu le choix.",
          DialogueId = 80110121,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1ABA",
          NextDialogue = 80110123,
          SpeakNpcId = 93101,
          Subtitle = "You think? I never wanted to be in the Legion.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1ABA"
        },
        [80110122] = {
          ContentFR = "Bien ? Tu trouves que \"c’est avoir la classe\", de risquer sa peau tous les jours ? Tu le ferais, toi ?",
          DialogueId = 80110122,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1AE4",
          NextDialogue = 80110123,
          SpeakNpcId = 93101,
          Subtitle = "Status and prestige? Sure, if you think risking your neck daily is worth it.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1AE4"
        },
        [80110123] = {
          ContentFR = "Franchement, c’était mieux quand j’étais Chasseuse de Phoxène. C’était pas facile tous les jours, mais au moins j’étais libre.",
          DialogueId = 80110123,
          GUID = "C88C1B0E",
          NextDialogue = 80110124,
          SpeakNpcId = 93101,
          Subtitle = "...I was happier as a Phoxhunter. It wasn't an easy gig, but at least I was free.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B0E"
        },
        [80110124] = {
          ContentFR = "Pas besoin de risquer ta vie à chaque mission. Parfois, tu tombais sur un truc peinard, comme surveiller un chien, traquer un cerf... Et si tu faisais un bon coup, tu finissais la soirée à boire un verre aux Asphodèles, histoire de te réchauffer un peu l’estomac.",
          DialogueId = 80110124,
          GUID = "C88C1B38",
          NextDialogue = 80110125,
          SpeakNpcId = 93101,
          Subtitle = "Not all commissions were about cheating death. Sometimes you'd get to walk dogs or hunt deer. And after a big score, you could enjoy a pint at The Asphodel.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B38"
        },
        [80110125] = {
          ContentFR = "Tu bosses seul, pas besoin de convaincre qui que ce soit, ni de traîner des boulets pendant l’action.",
          DialogueId = 80110125,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C1B62",
          NextDialogue = 80110126,
          SpeakNpcId = 93101,
          Subtitle = "You can do it on your own. No need to explain to anyone about your plans or worry about dead weight.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B62"
        },
        [80110126] = {
          ContentFR = "Et surtout, t’avais pas à supporter des supérieurs qui jacassent comme des moineaux.",
          DialogueId = 80110126,
          GUID = "C88C1B8C",
          NextOptions = {
            [1] = 801101261
          },
          SpeakNpcId = 93101,
          Subtitle = "Most importantly, you didn't have to deal with commanders who can't stop their yapping.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B8C"
        },
        [80110127] = {
          ContentFR = "Tu crois pas que ce genre de propos pourrait te faire \"griller\" ?",
          DialogueId = 80110127,
          GUID = "C88C1BB6",
          NextDialogue = 80110128,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "I thought bad-mouthing your superiors can be considered as something wrong. Wouldn't that get you zapped?",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1BB6"
        },
        [80110128] = {
          ContentFR = "... !",
          DialogueId = 80110128,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C1BE0",
          NextDialogue = 80110129,
          SpeakNpcId = 93101,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1BE0"
        },
        [80110129] = {
          ContentFR = "Bien sûr que oui ! Je suis pas une de ces nobles à la peau dure qui encaisse tout. Mais si mes supérieurs apprennent ça, je finirai grillée, ou pire.",
          DialogueId = 80110129,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1C0A",
          NextDialogue = 80110130,
          SpeakNpcId = 93101,
          Subtitle = "A...Absolutely! I'm no noble — those thick-skinned aristocrats can definitely survive a zap. But if my superiors heard this, they'd fry me, or worse.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C0A"
        },
        [80110130] = {
          ContentFR = "Et si tu le répètes à qui que ce soit, t’es {性别:mort|morte}, pigé ?",
          DialogueId = 80110130,
          GUID = "C88C1C34",
          NextOptions = {
            [1] = 801101301
          },
          SpeakNpcId = 93101,
          Subtitle = "If you go around telling people what I just said, I'll put a bullet in your head. Understood?",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C34"
        },
        [80110131] = {
          ContentFR = "Pourtant, je t’avoue que tu me surprends un peu.",
          DialogueId = 80110131,
          GUID = "C88C1C5E",
          NextDialogue = 80110132,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "Anyway, I find you quite... different.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C5E"
        },
        [80110132] = {
          ContentFR = "Je pensais qu’un officier d’Hyperborea aurait... je sais pas, un peu plus de foi ? Genre honneur, loyauté, tout ce baratin.",
          DialogueId = 80110132,
          GUID = "C88C1C88",
          NextDialogue = 80110133,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "I thought as a Hyperborean officer, you would have some... belief in the Empire. Like, talk about honour, loyalty, stuff like that...",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C88"
        },
        [80110133] = {
          ContentFR = "Pff, ce genre de blabla, ça peut peut-être passer avec les bleus, mais pas avec moi...",
          DialogueId = 80110133,
          GUID = "C88C1CB2",
          NextDialogue = 80110134,
          SpeakNpcId = 93101,
          Subtitle = "Pfft, that kind of crap might work on the noobs.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1CB2"
        },
        [80110134] = {
          ContentFR = "Beaucoup donneraient tout pour ces trucs invisibles, insaisissables, comme la foi ou le sens de l’honneur, mais moi, non. Je sais très bien pourquoi je suis devenue Chasseuse de Phoxène, et pourquoi j’ai rejoint la Légion.",
          DialogueId = 80110134,
          GUID = "C88C1CDC",
          NextDialogue = 80110135,
          SpeakNpcId = 93101,
          Subtitle = "Many would sacrifice everything for those invisible and untouchable things like sense of faith, but I am not one of them. I know exactly why I became a Phoxhunter and why I joined the Legion.",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1CDC"
        },
        [80110135] = {
          ContentFR = "... C’était juste pour avoir de quoi manger. Ça, je l’ai compris dès le départ. La Légion veut que je fasse le boulot, et moi, je veux leur salaire. Fin de l’histoire.",
          DialogueId = 80110135,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C1D06",
          NextDialogue = 80110136,
          SpeakNpcId = 93101,
          Subtitle = "...I just needed a job that brings food to the table. I got that figured out from the start. The Legion needs my skills and I need their paycheck. Simple exchange.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D06"
        },
        [80110136] = {
          ContentFR = "Toute cette histoire d’honneur et de foi ? Ça me passe complètement au-dessus.",
          DialogueId = 80110136,
          GUID = "C88C1D30",
          NextOptions = {
            [1] = 801101361
          },
          SpeakNpcId = 93101,
          Subtitle = "All that talk of \"glory\" and \"faith\" — it's not why I'm here.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D30"
        },
        [80110137] = {
          ContentFR = "... !",
          DialogueId = 80110137,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C1D5A",
          NextDialogue = 80110138,
          SpeakNpcId = 93101,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D5A"
        },
        [80110138] = {
          ContentFR = "Bordel ! J’aurais pas dû toucher à cette bouteille, dès que je bois un coup, j’arrive plus à me taire.",
          DialogueId = 80110138,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1D84",
          NextDialogue = 80110139,
          SpeakNpcId = 93101,
          Subtitle = "D**n it! I knew I shouldn't have had this drink. Can't keep my mouth shut when I'm a bit tipsy.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D84"
        },
        [80110139] = {
          ContentFR = "Allez, c’est fini, j’arrête là ! Et t’as intérêt à rien répéter de ce que t’as entendu, compris ?",
          DialogueId = 80110139,
          GUID = "C88C1DAE",
          SpeakNpcId = 93101,
          Subtitle = "I'm done here! And don't you dare let today's conversation out!",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1DAE"
        },
        [80110201] = {
          Camera = "127.060242,12.009277,131.847168,0.0,-0.799959,-137.39563,30.0,150.0,false,Manual,2.8",
          ContentFR = "… Encore un verre.",
          DialogueId = 80110201,
          GUID = "C88C27DA",
          LookAt = {
            [1] = "93101:p(18000P3)"
          },
          NextDialogue = 80110202,
          SpeakNpcId = 93101,
          Subtitle = "...Hit me with another.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C27DA"
        },
        [80110202] = {
          ContentFR = "Hé, à Givrelac, tu bosses toujours comme avant ? T’es encore aux Asphodèles ?",
          DialogueId = 80110202,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2804",
          NextOptions = {
            [1] = 801102021
          },
          SpeakNpcId = 93101,
          Subtitle = "Hey, how do you usually pick up your gigs? Still at The Asphodel?",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2804"
        },
        [80110203] = {
          ContentFR = "Ah ouais ? Rien n’a changé alors. Les Asphodèles, c’est tranquille... au moins, Camilla te balance pas des missions de pillage et d’assassinat à l’improviste.",
          DialogueId = 80110203,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C282E",
          NextOptions = {
            [1] = 801102031
          },
          SpeakNpcId = 93101,
          Subtitle = "Hmm, just like old times. The Asphodel is a neat place... At least Camilla doesn't suddenly throw in jobs where you have to kill people and rob their stuff.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C282E"
        },
        [80110204] = {
          ContentFR = "Ah ! Givrelac a beau être paumé, c’est rempli de types plus dangereux qu’à la capitale. Et encore plus dans les coins paumés où le Bureau de la Sécurité lève même pas un sourcil. Mais t’en fais pas, tant que tu restes chez Camilla et que tu fais pas dans les petites magouilles perso, t’auras pas ce genre de boulot.",
          DialogueId = 80110204,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2858",
          NextDialogue = 80110205,
          SpeakNpcId = 93101,
          Subtitle = "Hah, never underestimate Icelake. It's teeming with tougher nuts than the capital, especially with the Security Bureau ignoring the outskirts. But don't worry — Camilla's gigs are clean, unless you're dabbling in the sketchy ones.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2858"
        },
        [80110205] = {
          ContentFR = "Et Camilla, d’ailleurs ? Elle est toujours aussi mordante qu’avant ?",
          DialogueId = 80110205,
          GUID = "C88C2882",
          NextOptions = {
            [1] = 801102051,
            [2] = 801102052
          },
          SpeakNpcId = 93101,
          Subtitle = "Speaking of which, how is Camilla these days? Still got that edge?",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2882"
        },
        [80110206] = {
          ContentFR = "Eh ben ! Le temps file... Même Camilla s’adoucit. Dommage que ma supérieure, elle, soit toujours aussi infernale.",
          DialogueId = 80110206,
          FacialId = {
            [1] = "93101:Happy01"
          },
          GUID = "C88C28AC",
          NextOptions = {
            [1] = 801102071
          },
          SpeakNpcId = 93101,
          Subtitle = "That's good to hear! Ugh, time flies, even turned Camilla sweet, but it still couldn't soften up my iron-fisted supreme officer.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C28AC"
        },
        [80110207] = {
          ContentFR = "Ah, donc elle a pas changé d’un poil... Pareille que ma supérieure. Très belle, mais elle se donne des airs de tempête en colère tous les jours.",
          DialogueId = 80110207,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C28D6",
          NextOptions = {
            [1] = 801102071
          },
          SpeakNpcId = 93101,
          Subtitle = "Okay, so Camilla hasn't changed at all... Ugh, she's just like my supreme officer — pretty but goes around acting like a pissed volcano.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C28D6"
        },
        [80110208] = {
          ContentFR = "Son nom ? Je peux pas te le dire. Si je le balance, je finis grillée sur les grilles électrifiées de la Légion.",
          DialogueId = 80110208,
          GUID = "C88C2900",
          NextDialogue = 80110209,
          SpeakNpcId = 93101,
          Subtitle = "Her name is... Sorry, can't tell you. I'd rather not end up on the electric fence getting zapped to ashes.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2900"
        },
        [80110209] = {
          ContentFR = "Elle a toujours l’air de vouloir étrangler le monde entier, comme si on lui devait trois vies de salaire.",
          DialogueId = 80110209,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C292A",
          NextOptions = {
            [1] = 801102091
          },
          SpeakNpcId = 93101,
          Subtitle = "She's always got this long face like the entire Legion owes her money or something.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C292A"
        },
        [80110210] = {
          ContentFR = "Eh oh ! Et attends, ses lubies ! Sérieusement... qui utilise encore un fouet électrifié à notre époque ? Tout le monde a un flingue, sauf elle. Elle jure que « ça tient mieux en main » !",
          DialogueId = 80110210,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2954",
          NextDialogue = 80110211,
          SpeakNpcId = 93101,
          Subtitle = "Ugh, and her quirks! Like, who doesn't use a gun these days? But she insists on using her electrified whip and claims it works better.",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2954"
        },
        [80110211] = {
          ContentFR = "<I>Ton cœur rate un battement. Ce portrait te rappelle quelqu’un que tu cherches, Sibylle.</>",
          DialogueId = 80110211,
          GUID = "C88C297E",
          NextDialogue = 80110212,
          Subtitle = "(Your heart skipped a beat. Her descriptions reminded you of someone you're looking for — Sibylle.)",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C297E"
        },
        [80110212] = {
          ContentFR = "Et quand elle réfléchit, c’est pas dans le silence... Non, elle écoute à fond un enregistrement bruyant, disant que ça l’aide à se concentrer.",
          DialogueId = 80110212,
          GUID = "C88C29A8",
          NextDialogue = 80110213,
          SpeakNpcId = 93101,
          Subtitle = "And people usually prefer peace and quiet when they have something to think about, right? Not her — she always blasts a loud recording and says it pumps her up and helps her think better.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29A8"
        },
        [80110213] = {
          ContentFR = "Et elle garde des corbeaux dans son bureau ! Je te jure. Elle se dit jamais que les fientes pourraient tomber pile sur un rapport destiné à Sa M-... euh, enfin, à ses supérieurs ?",
          DialogueId = 80110213,
          GUID = "C88C29D2",
          NextDialogue = 80110214,
          SpeakNpcId = 93101,
          Subtitle = "She even keeps crows in her office. Hasn't she ever worried about bird droppings on her reports to His M—um, her higher-ups?",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29D2"
        },
        [80110214] = {
          ContentFR = "Et les rivières ! Les gens normaux y vont pour se détendre, hein ? Elle, elle y va juste pour regarder les pêcheurs rentrer bredouille. « C’est marrant et ça détend », qu’elle dit.",
          DialogueId = 80110214,
          GUID = "C88C29FC",
          NextDialogue = 80110215,
          SpeakNpcId = 93101,
          Subtitle = "And then there's this: normal people go to the riverside to unwind and enjoy the breeze and scenery, right? My boss? She goes there only to watch anglers come back empty-handed, says it's funny and stress-relieving.",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29FC"
        },
        [80110215] = {
          ContentFR = "Franchement... qui fait ça ?",
          DialogueId = 80110215,
          GUID = "C88C2A26",
          NextOptions = {
            [1] = 801102151
          },
          SpeakNpcId = 93101,
          Subtitle = "I mean — who does that!?",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A26"
        },
        [80110216] = {
          ContentFR = "Particulière ? Tu veux dire carrément étrange, ouais. Et encore, c’est juste ma supérieure. Mon supérieur direct ? Encore plus bizarre.",
          DialogueId = 80110216,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C2A50",
          NextDialogue = 80110217,
          SpeakNpcId = 93101,
          Subtitle = "She's nuts. Trust me, she's far less interesting in person. Oh, and that's just the top boss. My direct superior? Even nuttier.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A50"
        },
        [80110217] = {
          ContentFR = "Ce gars parle comme s’il avait avalé un dictionnaire. Il croit être raffiné... mais on dirait juste une oie molle qui cancane.",
          DialogueId = 80110217,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2A7A",
          NextDialogue = 80110218,
          SpeakNpcId = 93101,
          Subtitle = "Now this dude rambles in circles and thinks he's all classy. Honestly? He sounds like a wishy-washy wet goose.",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A7A"
        },
        [80110218] = {
          ContentFR = "Il radote tout le temps sur l’efficacité, l’optimisation, blablabla... En vrai, c’est juste une excuse pour glander. Personne n’est dupe.",
          DialogueId = 80110218,
          GUID = "C88C2AA4",
          NextDialogue = 80110219,
          SpeakNpcId = 93101,
          Subtitle = "That guy's always babbling about efficiency and energy saving. Ugh, everyone knows that he's just making excuses for his laziness.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2AA4"
        },
        [80110219] = {
          ContentFR = "Bon, il est pas idiot non plus. Il fait genre il bosse pas, mais au final, le boulot est fait, et bien, en plus.",
          DialogueId = 80110219,
          GUID = "C88C2ACE",
          NextDialogue = 80110220,
          SpeakNpcId = 93101,
          Subtitle = "But I'll give him this — he's sharp. Slacks off, sure, but somehow still manages to get the job done. No one can really fault him for that.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2ACE"
        },
        [80110220] = {
          ContentFR = "Récemment, il a carrément deviné où se trouvait un trésor que ma supérieure cherchait depuis des années, juste à partir de quelques indices. Bon... ça s’est pas passé sans accroc...",
          DialogueId = 80110220,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2AF8",
          NextDialogue = 80110221,
          SpeakNpcId = 93101,
          Subtitle = "Not long ago, he cracked the location of treasure with just a few clues. That's something my supreme officer had been chasing for years. But, well, there was... a little hiccup.",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2AF8"
        },
        [80110221] = {
          ContentFR = "<I>Si je ne me trompe pas, le « trésor » dont parle Lynn... ça pourrait bien être Berry.</>",
          DialogueId = 80110221,
          GUID = "C88C2B22",
          NextOptions = {
            [1] = 801102211
          },
          Subtitle = "(If I guessed correctly, the \"treasure\" that Lynn mentioned could very well be Berry.)",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2B22"
        },
        [80110222] = {
          ContentFR = "Me demande pas... C’était leur mission à tous les deux. Classée secret défense. J’en sais rien, et même si je savais, je dirais rien.",
          DialogueId = 80110222,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2B4C",
          NextDialogue = 80110223,
          SpeakNpcId = 93101,
          Subtitle = "Don't ask me... The two of them handled that mission together. It's all top secret — how would I know?",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2B4C"
        },
        [80110223] = {
          ContentFR = "...",
          DialogueId = 80110223,
          GUID = "C88C2B76",
          NextDialogue = 80110224,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "......",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2B76"
        },
        [80110224] = {
          ContentFR = "Mince... J’ai vraiment dit trop de trucs que j’aurais pas dû, là... Argh, c’est à cause de cette fichue boisson ! T’aurais pas glissé un sérum de vérité dans ma bouteille, par hasard ?",
          DialogueId = 80110224,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C2BA0",
          NextDialogue = 80110225,
          SpeakNpcId = 93101,
          Subtitle = "Crap. I really said a load of stuff I shouldn't be saying at all... It must be this lousy booze! You didn't spike it with a truth serum or something, did you?",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2BA0"
        },
        [80110225] = {
          ContentFR = "Bon allez, je me tire. Et heureusement que je bois pas quand je suis à Dismania, sinon un jour je me ferais électrocuter en pleine rue par un coup de fouet de ma supérieure... enfin bref, faut que j’arrête de parler.",
          DialogueId = 80110225,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2BCA",
          SpeakNpcId = 93101,
          Subtitle = "Sheesh. I'm outta here. Ugh — thank goodness I don't drink in Dismania, or I'd end up zapped by my superior's whip... Argh, better stop talking now...",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2BCA"
        },
        [80110226] = {
          Camera = "164.130432,-127.039795,145.762421,0.000003,0.8,176.399841,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Je sais que tu ne répéteras rien.",
          DialogueId = 80110226,
          FinalCamera = "164.130432,-118.0,145.762421,0.000003,0.8,176.399841,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C88C2BF4",
          LookAt = {
            [1] = "790014:n(790008)"
          },
          NextDialogue = 80110227,
          SpeakNpcId = 790014,
          Subtitle = "And I trust you won't go blabbing about what I said.",
          ToFinalCameraBlendTime = 7,
          TurnTo = {
            [1] = "790008:n(790014)"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2BF4"
        },
        [80110227] = {
          Camera = "13.894012,-267.815552,157.042679,0.00001,-2.999996,96.801392,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tout comme je sais que tu m’as fait boire plus fort exprès, histoire de me faire parler... Mais j’ai fait semblant de rien.",
          DialogueId = 80110227,
          GUID = "C88C2C1E",
          NextDialogue = 80110228,
          SpeakNpcId = 790014,
          Subtitle = "I know exactly why you chose that extra-strong drink. You had your own reasons for coaxing intel from me — but I chose to act the fool and play along.",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2C1E"
        },
        [80110228] = {
          Camera = "13.276428,-53.140625,124.735672,0.000025,0.0,86.600571,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "On va s’arrêter là. Ne va pas plus loin. Je peux pas me permettre d’aller contre la Légion, faut bien survivre, pas vrai ?",
          DialogueId = 80110228,
          FinalCamera = "13.276428,-68.0,124.735672,0.000025,0.0,86.600571,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C88C2C48",
          LookAt = {
            [1] = "790014:n(790014)"
          },
          NextDialogue = 80110229,
          SpeakNpcId = 790014,
          Subtitle = "Let's stop here. Don't push any further. I can't cross the Legion — everyone's gotta live, right?",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2C48"
        },
        [80110229] = {
          Camera = "14.200928,-236.600464,163.609055,-0.0,-7.599944,97.395355,35.0,180.0,false,Manual,2.8",
          ContentFR = "Et j’ai pas envie de perdre quelqu’un... avec qui je peux être un peu honnête.",
          DialogueId = 80110229,
          FinalCamera = "12.948349,-226.679688,163.609055,0.000001,-7.599944,97.195381,35.0,130.0,false,Manual,2.8",
          GUID = "C88C2C72",
          NextDialogue = 80110230,
          SpeakNpcId = 790014,
          Subtitle = "And I don't want to... lose someone that I can actually talk to.",
          TalkActionId = {
            [1] = "790014:Disagree",
            [2] = "790008:Think_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2C72"
        },
        [80110230] = {
          ContentFR = "Bon. À plus.",
          DialogueId = 80110230,
          GUID = "C88C2C9C",
          IsBlack = 1,
          SpeakNpcId = 790014,
          Subtitle = "Alright, that's it. I'm off!",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2C9C"
        },
        [80110301] = {
          Camera = "127.060242,12.009277,131.847168,0.0,-0.799959,-137.39563,30.0,150.0,false,Manual,2.8",
          ContentFR = "Hé, fais-moi une faveur. Je te paierai.",
          DialogueId = 80110301,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3842",
          LookAt = {
            [1] = "93101:p(18000P3)"
          },
          NextDialogue = 80110302,
          SpeakNpcId = 93101,
          Subtitle = "Hey, do me a favor. I'll pay you.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3842"
        },
        [80110302] = {
          ContentFR = "Je pars pour la capitale demain. J’ai un colis à faire livrer au 48, rue du Chêne, dans les faubourgs ouest. C’est pour une femme qui s’appelle Riola Baker.",
          DialogueId = 80110302,
          GUID = "C88C386C",
          NextOptions = {
            [1] = 801103021
          },
          SpeakNpcId = 93101,
          Subtitle = "I'm off to the capital tomorrow and I've got a package here that needs to be delivered to No. 48, Oak Street in the west suburbs. It's for a lady named Riola Baker.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C386C"
        },
        [80110303] = {
          ContentFR = "Tu poses trop de questions.",
          DialogueId = 80110303,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3896",
          NextOptions = {
            [1] = 801103031,
            [2] = 801103032
          },
          SpeakNpcId = 93101,
          Subtitle = "You're asking too many questions.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3896"
        },
        [80110304] = {
          ContentFR = "Hmm, pas faux. Bon, je vais te dire, c’est un pistolet et un masque.",
          DialogueId = 80110304,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C38C0",
          NextDialogue = 80110305,
          SpeakNpcId = 93101,
          Subtitle = "Fair point. Alright, I'll spill it. There's a gun and a mask in there.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C38C0"
        },
        [80110305] = {
          ContentFR = "Pas besoin de paniquer, hein. C’est un jouet. Si t’as des doutes, tire-moi dessus.",
          DialogueId = 80110305,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C38EA",
          NextOptions = {
            [1] = 801103051
          },
          SpeakNpcId = 93101,
          Subtitle = "Don't be nervous. It's just a toy gun. If you don't believe me, feel free to test it on me.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C38EA"
        },
        [80110306] = {
          ContentFR = "BANG !",
          DialogueId = 80110306,
          GUID = "C88C3914",
          NextDialogue = 80110307,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_toysshot\"},PlayAs2D{true}}",
          Subtitle = "(BANG—)",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3914"
        },
        [80110307] = {
          ContentFR = "Aïe, aïe, aïe ! Même les fausses balles, ça fait mal ! Et t’as visé la tête en plus ?! Ramène-toi que je t’en colle une ! Put***, t’y es pas {性别:allé|allée} de main morte...",
          DialogueId = 80110307,
          FacialId = {
            [1] = "93101:Sad01"
          },
          GUID = "C88C393E",
          NextDialogue = 80110308,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_toysshot\"},PlayAs2D{true}}",
          SpeakNpcId = 93101,
          Subtitle = "Ow! Fake bullets hurt too! And why aim at the head!? Get over here, I'm gonna give you a thrashing! D**n, that friggin' hurt.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C393E"
        },
        [80110308] = {
          ContentFR = "Tu sais quoi, ça m’a rappelé un truc. Moi et Riola, gamines, on se tirait dessus à la fronde, et on visait direct la tête. On a eu du bol de s’en sortir. Ce pistolet... c’est pour elle.",
          DialogueId = 80110308,
          GUID = "C88C3968",
          NextOptions = {
            [1] = 801103081
          },
          SpeakNpcId = 93101,
          Subtitle = "*sigh* You know what, this reminds me of the fights I used to have with Riola when we were little. We'd use slingshots to hit each other in the head. Lucky I'm still alive, huh? Anyway, this gun... is my present for her.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3968"
        },
        [80110309] = {
          ContentFR = "Ouais, en quelque sorte... Comme j’étais en mission à Givrelac, je me suis dit que je pouvais lui ramener un truc.",
          DialogueId = 80110309,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3992",
          NextDialogue = 80110310,
          SpeakNpcId = 93101,
          Subtitle = "Yeah, sort of... Had to come to Icelake for a mission, figured I might as well bring something.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3992"
        },
        [80110310] = {
          ContentFR = "Mais bon, tu poses trop de questions. Alors, tu le fais ou pas ? Sinon je file la tâche à un autre Chasseur de Phoxène.",
          DialogueId = 80110310,
          GUID = "C88C39BC",
          NextOptions = {
            [1] = 801103101
          },
          SpeakNpcId = 93101,
          Subtitle = "And you've had way too many questions. Look, are you in or out? There's no shortage of Phoxhunters for the job, you know.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C39BC"
        },
        [80110311] = {
          ContentFR = "Moi ? Plutôt crever. Si c’était pas un ordre d’en haut, j’aurais jamais remis les pieds à Givrelac.",
          DialogueId = 80110311,
          FacialId = {
            [1] = "93101:Sad01"
          },
          GUID = "C88C39E6",
          NextOptions = {
            [1] = 801103111,
            [2] = 801103112
          },
          SpeakNpcId = 93101,
          Subtitle = "Deliver it myself? Forget it. If it weren't for orders from the top, I wouldn't bother coming back to Icelake.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C39E6"
        },
        [80110312] = {
          ContentFR = "Pff, arrête ton cirque.",
          DialogueId = 80110312,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3A10",
          NextDialogue = 80110313,
          SpeakNpcId = 93101,
          Subtitle = "Tsk, cut it out.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A10"
        },
        [80110313] = {
          ContentFR = "Je suis déjà revenue une fois. J’avais dans l’idée de revoir les vieux potes, ceux avec qui je grimpais aux arbres et piquais des patates, gamine. Boire un coup, rigoler des conneries du passé... et oublier un peu la Légion.",
          DialogueId = 80110313,
          GUID = "C88C3A3A",
          NextDialogue = 80110314,
          SpeakNpcId = 93101,
          Subtitle = "I did come back here before and had plans to catch up with the old gang. We used to climb trees and swipe veg together as kids. I wanted to chat with them, laugh about those silly pranks over a pint or two, and forget about life in the Legion for a while.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A3A"
        },
        [80110314] = {
          ContentFR = "Mais le mot s’était répandu. Ils s’étaient tous alignés, m’ont saluée de loin en hurlant « Major Lynn » si fort que même les piafs sur les toits ont déguerpi.",
          DialogueId = 80110314,
          GUID = "C88C3A64",
          NextDialogue = 80110315,
          SpeakNpcId = 93101,
          Subtitle = "But word got out I was coming. They all lined up, saluted from a distance, yelling \"Officer Lynn\" so loud it scared the birds off the roofs.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A64"
        },
        [80110315] = {
          ContentFR = "Je m’étais dit, bon, qu’ils fassent leurs manières, qu’ils se calment... et après, on pourrait briser la glace, parler des jours où on courait comme des fous dans les rues quand on était mômes. Peut-être que ça nous rapprocherait un peu.",
          DialogueId = 80110315,
          GUID = "C88C3A8E",
          NextDialogue = 80110316,
          SpeakNpcId = 93101,
          Subtitle = "I thought I'd let them do their thing. Get it out of their system. Then we'd all loosen up a bit reminiscing about tearing down the streets as kids.",
          TalkActionId = {
            [1] = "93101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A8E"
        },
        [80110316] = {
          ContentFR = "Mais non. Ils se sont contentés de courber l’échine, la tête presque dans leurs godasses, pas un seul regard dans les yeux.",
          DialogueId = 80110316,
          GUID = "C88C3AB8",
          NextOptions = {
            [1] = 801103161
          },
          SpeakNpcId = 93101,
          Subtitle = "But the old gang never gave me the chance. Everyone was too busy saluting, bowing like they owed me something. Couldn't even look me in the eye.",
          TalkActionId = {
            [1] = "93101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3AB8"
        },
        [80110317] = {
          ContentFR = "Évidemment. J’ai grandi avec ça, je sais très bien pourquoi ils ont peur. Si j’étais pas devenue soldat, c’est moi qui me planquerais dès qu’un uniforme approche.",
          DialogueId = 80110317,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3AE2",
          NextDialogue = 80110318,
          SpeakNpcId = 93101,
          Subtitle = "Of course it's normal. I've seen my fair share of things to know why they're so afraid of me. If it weren't for my joining the Legion, I'd be the one who trembles at the sight of soldiers.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3AE2"
        },
        [80110318] = {
          ContentFR = "Givrelac... non, tout Hyperborea, c’est comme ça : les forts écrasent les faibles, les riches piétinent les pauvres. C’était déjà comme ça quand j’étais gosse, et ça a pas changé d’un poil.",
          DialogueId = 80110318,
          GUID = "C88C3B0C",
          NextDialogue = 80110319,
          SpeakNpcId = 93101,
          Subtitle = "Icelake... No, it's the same for the whole of Hyperborea — the strong and rich walk all over the weak and poor... This has always been the way since I was a little girl. Nothing's changed.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B0C"
        },
        [80110319] = {
          ContentFR = "Tu sais à quoi servent le pistolet et le masque, au fait ?",
          DialogueId = 80110319,
          GUID = "C88C3B36",
          NextDialogue = 80110320,
          SpeakNpcId = 93101,
          Subtitle = "Anyway, do you know what the gun and mask are for?",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B36"
        },
        [80110320] = {
          ContentFR = "Moi et Riola, on lisait une BD quand on était petites. Ça racontait l’histoire d’un voleur masqué, Leblanc. Il volait les riches pour aider les pauvres. On l’appelait \"le héros masqué\".",
          DialogueId = 80110320,
          GUID = "C88C3B60",
          NextDialogue = 80110321,
          SpeakNpcId = 93101,
          Subtitle = "When we were kids, Riola and I were obsessed with this comic about Leblanc, a rogue who'd steal from wicked rich folks and give to the poor. They called him the \"Masked Hero.\"",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B60"
        },
        [80110321] = {
          ContentFR = "On se faisait des masques en carton, les frondes en guise de flingues, et on grimpait sur les remparts de Givrelac pour crier ses répliques. On s’en fichait d’avoir l’air ridicules.",
          DialogueId = 80110321,
          FacialId = {
            [1] = "93101:Syouganai01"
          },
          GUID = "C88C3B8A",
          NextDialogue = 80110322,
          SpeakNpcId = 93101,
          Subtitle = "We made masks from scrap cardboard and used slingshots as our guns. We'd climb the town walls of Icelake, shouting Leblanc's lines from the comics. Silly, I know, but we didn't feel a bit embarrassed.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B8A"
        },
        [80110322] = {
          ContentFR = "Parce qu’on croyait vraiment qu’un jour... on deviendrait des héros, nous aussi.",
          DialogueId = 80110322,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3BB4",
          NextDialogue = 80110323,
          SpeakNpcId = 93101,
          Subtitle = "Those were the days when we felt we could... well... eventually become heroes ourselves.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3BB4"
        },
        [80110323] = {
          ContentFR = "Des années plus tard, j’ai vu un masque de Leblanc et un faux pistolet dans une boutique à Dismania. Super bien faits. Je les ai achetés.",
          DialogueId = 80110323,
          GUID = "C88C3BDE",
          NextDialogue = 80110324,
          SpeakNpcId = 93101,
          Subtitle = "Years later, I spotted a beautifully crafted Leblanc mask and toy gun in a Dismania store. I couldn't resist, so I bought them.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3BDE"
        },
        [80110324] = {
          ContentFR = "Je me suis dit : « Je suis peut-être devenue une saleté qui bute du Charon, mais Riola... elle, elle a peut-être encore une chance d’être une héroïne. »",
          DialogueId = 80110324,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3C08",
          NextDialogue = 80110325,
          SpeakNpcId = 93101,
          Subtitle = "Back then, I thought, \"I might have turned into a Charon-killing baddie, but at least Riola could still be a hero...\"",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C08"
        },
        [80110325] = {
          ContentFR = "... Jusqu’à ce que je la revoie à Givrelac, en train de trembler comme une oie et de m’appeler « Major Lynn ». Là, j’ai compris, y a pas de retour possible pour nous deux.",
          DialogueId = 80110325,
          GUID = "C88C3C32",
          NextDialogue = 80110326,
          SpeakNpcId = 93101,
          Subtitle = "The last time I saw her in Icelake, she trembled like a scared goose and called me \"Officer Lynn.\" That's when I knew, we'd both changed. There's no going back to the good old days.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C32"
        },
        [80110326] = {
          ContentFR = "... Pff, je me file la migraine. Encore un verre !",
          DialogueId = 80110326,
          FacialId = {
            [1] = "93101:Syouganai01"
          },
          GUID = "C88C3C5C",
          NextDialogue = 80110327,
          SpeakNpcId = 93101,
          Subtitle = "...Ugh, my head's hurting. Hit me with another!",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C5C"
        },
        [80110327] = {
          ContentFR = "C’est pour ça que je ne veux plus revenir ici. Même mes propres frangins, je veux pas les voir. Tant que je les aperçois de loin, qu’ils sont vivants, plus grands, qu’ils vont bien... ça me suffit.",
          DialogueId = 80110327,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3C86",
          NextOptions = {
            [1] = 801103271
          },
          SpeakNpcId = 93101,
          Subtitle = "These are the reasons why I avoid being back at Icelake. I don't even want to meet my own siblings. Just seeing them from afar, knowing they're alive and well, that's enough for me.",
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C86"
        },
        [80110328] = {
          ContentFR = "Non. C’est même l’inverse. Ils m’écrivent tout le temps. Ils veulent que je passe les voir.",
          DialogueId = 80110328,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C3CB0",
          NextDialogue = 80110329,
          SpeakNpcId = 93101,
          Subtitle = "No, quite the opposite. They write all the time, saying how much they miss me and wish I'd visit.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3CB0"
        },
        [80110329] = {
          ContentFR = "Mais qu’est-ce que je pourrais leur dire ? Que j’ai encore vu des horreurs à l’Académie ? Que j’ai arrêté je ne sais combien de Charons ?",
          DialogueId = 80110329,
          GUID = "C88C3CDA",
          NextDialogue = 80110330,
          SpeakNpcId = 93101,
          Subtitle = "But what could I tell them? About the latest horrors I've seen at the Academy? Or how many Charon prisoners I took?",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3CDA"
        },
        [80110330] = {
          ContentFR = "... Laisse tomber. Tout le monde a ses propres démon. C’est ça, la norme aujourd’hui.",
          DialogueId = 80110330,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3D04",
          NextOptions = {
            [1] = 801103301
          },
          SpeakNpcId = 93101,
          Subtitle = "...Forget it. Everyone's got their own burdens. It's all so damn normal these days.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D04"
        },
        [80110331] = {
          ContentFR = "Ce monde devrait être un endroit où on peut rentrer chez soi quand on en a envie... Peut-être que c’est à notre génération de faire en sorte que ce soit possible.",
          DialogueId = 80110331,
          GUID = "C88C3D2E",
          NextDialogue = 80110332,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "This should be a world where you can return home whenever you want... Perhaps our generation should try to make it one.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D2E"
        },
        [80110332] = {
          ContentFR = "T’es vraiment pas d’ici, toi. Tu crois encore que tout ça peut changer.",
          DialogueId = 80110332,
          GUID = "C88C3D58",
          NextDialogue = 80110333,
          SpeakNpcId = 93101,
          Subtitle = "Only outsiders like you would think this is weird and believe this can change.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D58"
        },
        [80110333] = {
          ContentFR = "Tu penses quoi, aussi ? Que les Charons et les Solariens vont un jour vivre main dans la main ? Qu’on les regardera plus de travers à cause de leurs cornes, leur dos bizarre ou leur magie ?",
          DialogueId = 80110333,
          GUID = "C88C3D82",
          NextDialogue = 80110334,
          SpeakNpcId = 93101,
          Subtitle = "Perhaps you also believe a day will come when Charons and Solas can live together in peace, and that people won't be judged for their strange-looking horns and spines, and the weird magic in their veins.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D82"
        },
        [80110334] = {
          ContentFR = "Peut-être bien.",
          DialogueId = 80110334,
          GUID = "C88C3DAC",
          NextDialogue = 80110335,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "That could happen.",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3DAC"
        },
        [80110335] = {
          ContentFR = "Même si tu ne peux pas arrêter la neige à Givrelac, tu peux toujours la pelleter... ou en faire un bonhomme de neige.",
          DialogueId = 80110335,
          GUID = "C88C3DD6",
          NextDialogue = 80110336,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "Even if you can't stop the snow in Icelake, you can at least shovel it away and make snowmen out of it, right?",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3DD6"
        },
        [80110336] = {
          ContentFR = "Et tu peux toujours aller voir ton amie et lui dire que tu te souviens de vos rêves d’enfance, même s’ils sont brisés. Tu peux toujours frapper à la porte de ta famille, leur dire que tu les aimes encore. Peu importe qui tu es devenue, ça, ça changera jamais.",
          DialogueId = 80110336,
          GUID = "C88C3E00",
          NextDialogue = 80110337,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          Subtitle = "You can at least go to your friend and tell her you remember your childhood dreams, even if they're broken now. You should be able to knock on the door of your family home and tell your folks that you'll always miss them no matter who you've become. That part of you never changes.",
          TalkActionId = {
            [1] = "93101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E00"
        },
        [80110337] = {
          ContentFR = "... Haha. Je dois dire, j’aime bien ta façon de voir les choses. Un peu idéaliste, mais c’est quand même mieux que ce fatalisme habituel du genre « c’est comme ça, on y peut rien ».",
          DialogueId = 80110337,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3E2A",
          NextDialogue = 80110338,
          SpeakNpcId = 93101,
          Subtitle = "...Hah. To be honest, I like your way of thinking, even if it's a bit naive for my taste. It's way better than the usual crap like \"Oh, that's the way it is, nobody can change the world.\"",
          TalkActionId = {
            [1] = "93101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E2A"
        },
        [80110338] = {
          ContentFR = "Au moins, avec toi, j’ai presque l’impression que le vent de Givrelac est un peu moins froid. Allez, sers-moi encore un verre.",
          DialogueId = 80110338,
          FacialId = {
            [1] = "93101:Happy02"
          },
          GUID = "C88C3E54",
          NextDialogue = 80110339,
          SpeakNpcId = 93101,
          Subtitle = "And your words actually made this Icelake breeze a bit warmer, I must say. Hmm... Pour me another.",
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E54"
        },
        [80110339] = {
          ContentFR = "Je veux voir jusqu’où tu peux aller avec ce rêve de changer le monde. Je suis curieuse de savoir si {性别:un gars comme toi, un rêveur naïf|une fille comme toi, une rêveuse naïve}, peut vraiment faire une différence, ne serait-ce qu’un peu.",
          DialogueId = 80110339,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3E7E",
          NextDialogue = 80110340,
          SpeakNpcId = 93101,
          Subtitle = "Let's see how far you can take this dream of changing the world. I'm curious if a naive fool can actually make a difference, even a little.",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E7E"
        },
        [80110340] = {
          ContentFR = "Si t’as besoin d’un coup de main, et que je suis dispo, je peux aider... tant que c’est pas contre la Légion. Mais pas ce soir. J’ai changé d’avis, j’ai autre chose à faire.",
          DialogueId = 80110340,
          GUID = "C88C3EA8",
          NextDialogue = 80110341,
          SpeakNpcId = 93101,
          Subtitle = "And if you ever need help, and I'm free, just ask — as long as it's nothing against the Legion. But not today — I've just changed my mind about something and will be busy later.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3EA8"
        },
        [80110341] = {
          ContentFR = "J’annule la commande. Rends-moi le masque et le flingue.",
          DialogueId = 80110341,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3ED2",
          SpeakNpcId = 93101,
          Subtitle = "I'm cancelling the commission. Now, gimme back my mask and gun.",
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3ED2"
        },
        [80120000] = {
          ContentFR = "Ah, c’est la vie, un fauteuil confortable, une boisson, des snacks, un feu de cheminée, et ta compagnie. Tout est bien douillet...",
          DialogueId = 80120000,
          GUID = "C8926F80",
          Subtitle = "Ahh, this is the life — a comfy chair, a drink, some snacks, a warm fireplace, and your company. All nice and cosy..."
        },
        [80120100] = {
          Camera = "254.617188,-63.0,110.607666,0.0,0.0,155.600769,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Les meubles à l’intérieur ? Je les ai rapportés il y a trente ans de la capitale impériale, Dismania. La rareté des matériaux et la qualité du travail dépassent tout ce que vous pouvez imaginer.",
          DialogueId = 80120100,
          FinalCamera = "254.617188,-54.528625,110.607666,0.0,0.0,155.600739,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8927FE8",
          NextDialogue = 80120101,
          SpeakNpcId = 790018,
          Subtitle = "The pieces of furniture inside? I brought them from the Imperial capital of Dismania thirty years ago. The rarity of the materials and the craftsmanship are beyond your wildest dreams.",
          TalkActionId = {
            [1] = "790018:Explain01_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/001/C8927FE8"
        },
        [80120101] = {
          Camera = "-270.549316,-21.425171,153.719727,0.000001,-9.200162,19.797686,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Vu leur valeur, vous êtes sûr de vouloir qu’on s’en occupe ? Nous, on n’est que des récupérateurs modestes. Si jamais vous revenez en arrière...",
          DialogueId = 80120101,
          FacialId = {
            [1] = "790019:Iyada01"
          },
          GUID = "C8928012",
          NextDialogue = 80120102,
          SpeakNpcId = 790019,
          Subtitle = "Um, are you sure you want me to handle these valuable items, sir? If you change your mind all of a sudden, there's no way for a scavenger like me to...",
          TalkActionId = {
            [1] = "790019:Explain02_Start",
            [2] = "790018:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928012"
        },
        [80120102] = {
          Camera = "254.617188,-54.528625,110.607666,0.0,0.0,155.600739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu m’as posé la question plusieurs fois, et j’ai répété ma réponse : ces meubles, c’est à vous de les gérer. Mes vraies richesses sont mes partitions, bien à l’abri là où elles doivent être.",
          DialogueId = 80120102,
          GUID = "C892803C",
          NextDialogue = 80120103,
          SpeakNpcId = 790018,
          Subtitle = "You've already asked multiple times, and my answer remains: yes, these pieces are yours to handle. My true treasures are my music scores, and they have been well secured where they belong.",
          TalkActionId = {
            [1] = "790019:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C892803C"
        },
        [80120103] = {
          Camera = "-91.792969,-17.010254,119.101807,0.000001,-2.600096,26.798737,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bon... juste pour être sûre, j’ai ramassé plein de feuilles dans le bureau. Ça fait une pile énorme ! Ça ressemble aussi à des partitions...",
          DialogueId = 80120103,
          GUID = "C8928066",
          NextDialogue = 80120104,
          SpeakNpcId = 790019,
          Subtitle = "Well then, just to double-check before we start: about this huge pile of sheets — I collected them from the study. They look like music scores too...",
          TalkActionId = {
            [1] = "790019:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928066"
        },
        [80120104] = {
          Camera = "188.380859,5.304199,118.568604,0.000005,0.0,165.387512,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Brûle-les.",
          DialogueId = 80120104,
          GUID = "C8928090",
          NextDialogue = 80120105,
          SpeakNpcId = 790018,
          Subtitle = "Just burn them.",
          TalkActionId = {
            [1] = "790019:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928090"
        },
        [80120105] = {
          Camera = "-194.875488,-9.761597,155.702393,0.000033,-32.798512,130.396423,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ce ne sont que des brouillons, des déchets inutiles. Trouve quelqu’un qui a froid, qu’il s’en serve pour se réchauffer.",
          DialogueId = 80120105,
          FinalCamera = "-183.950195,-22.665466,181.275146,0.000027,-35.598583,129.996002,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89280BA",
          NextDialogue = 80120106,
          SpeakNpcId = 790018,
          Subtitle = "They're nothing but useless drafts, rubbish. Give them to someone struggling to stay warm to burn.",
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/inv/Maer/001/C89280BA"
        },
        [80120106] = {
          Camera = "7.850098,-71.797974,9.991455,0.000032,31.599302,132.795364,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est risible, si ces feuilles avaient vraiment de la valeur, elles seraient déjà rangées, non ? Pas besoin de me poser des questions inutiles.",
          DialogueId = 80120106,
          GUID = "C89280E4",
          NextDialogue = 80120107,
          SpeakNpcId = 790018,
          Subtitle = "How laughable — if they were important to me, before you waste my time with these stupid questions, don't you think I'd have properly saved them already?",
          TalkActionId = {
            [1] = "790018:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89280E4"
        },
        [80120107] = {
          Camera = "-65.708008,-20.782593,149.700928,0.000017,-11.799984,31.404984,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 80120107,
          FacialId = {
            [1] = "790019:Sad01"
          },
          GUID = "C892810E",
          LookAt = {
            [1] = "790019:p(P33010101)"
          },
          NextDialogue = 80120108,
          SpeakNpcId = 790019,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Maer/001/C892810E"
        },
        [80120108] = {
          Camera = "10.617676,-39.324158,127.336182,0.000074,1.400339,142.991364,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Au loin, le sifflement d’un train retentit, pressant ce musicien un peu grognon de prendre le chemin de Dismania.",
          DialogueId = 80120108,
          GUID = "C8928138",
          LookAt = {
            [1] = "790018:p(P33010102)"
          },
          NextDialogue = 80120109,
          Subtitle = "The distant sound of a train whistle echoes, as if hurrying the eccentric musician on his journey back to Dismania.",
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928138"
        },
        [80120109] = {
          Camera = "-272.822754,-25.003113,137.138184,0.0,-3.399993,22.39842,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Il est temps pour moi de partir. À jamais, Charon.",
          DialogueId = 80120109,
          GUID = "C8928162",
          LookAt = {
            [1] = "790019:n(790018)"
          },
          NextDialogue = 80120110,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"790018:n(790018)"}},
MoveTo{ActorId{790018},MoveSpeed{75},TargetPoint{"MovePoint_33010102"}}
}]],
          SpeakNpcId = 790018,
          Subtitle = "It's time I left. See you never, Charon.",
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928162"
        },
        [80120110] = {
          Camera = "41.422852,127.761597,116.559082,0.000003,-0.200043,-76.786568,25.0,73.935852,false,Manual,2.8",
          ContentFR = "...",
          DialogueId = 80120110,
          FacialId = {
            [1] = "790019:Sad02"
          },
          FinalCamera = "36.748535,126.659424,116.559082,0.000003,-0.200043,-76.586166,25.0,235.730316,false,Manual,3.0",
          GUID = "C892818C",
          LookAt = {
            [1] = "790008:n(790019)",
            [2] = "790019:p(P33010101)"
          },
          NextOptions = {
            [1] = 801201101,
            [2] = 801201102
          },
          Scripts = "MoveTo{ActorId{790008},MoveSpeed{75},TargetPoint{\"MovePoint_33010101\"}}",
          SpeakNpcId = 790019,
          Subtitle = "...",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Maer/001/C892818C"
        },
        [80120111] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentFR = "Oh, c’est toi. Attends-moi une minute !",
          DialogueId = 80120111,
          GUID = "C89281B6",
          NextDialogue = 80120112,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"790019:n(790008)"}},
TurnTo{TurnToDescription{"790019:n(790008)"}},
PlayAnimation{ActorId{790019},AnimationId{"Agree"},Duration{1}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Oh, it's you. Excuse me for a minute!",
          VoiceName = "voice/$Locale$/inv/Maer/001/C89281B6"
        },
        [80120112] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentFR = "Margie inspire profondément et murmure à voix basse, mais on l’entend parfaitement.",
          DialogueId = 80120112,
          GUID = "C89281E0",
          NextDialogue = 80120113,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"790019:n(790019)"}},
TurnTo{TurnToDescription{"790019:p(180)"}}
}]],
          Subtitle = "(Margie takes a deep breath and begins to murmur to herself under her breath, though you can still hear her, even more clearly.)",
          VoiceName = "voice/$Locale$/inv/Maer/001/C89281E0"
        },
        [80120113] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentFR = "La vie, c’est une décharge, les déchets font partie du paysage. Eux restent là, moi j’ai des jambes, je m’éloigne quand ça sent le carnage...",
          DialogueId = 80120113,
          GUID = "C892820A",
          NextDialogue = 80120114,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790019},AnimationId{"Angry01_Start"},Duration{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Angry01_End"},Duration{1},_delay{2},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Life's a dump, full of junk. They can't move but I can run, to keep my life safe and sound...",
          VoiceName = "voice/$Locale$/inv/Maer/001/C892820A"
        },
        [80120114] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentFR = "Les cris ? Faut pas s’en faire, c’est juste un p’tit chien en colère. Te battre avec, c’est perdre ton temps, va plutôt bronzer, peinard, au soleil d’un instant...",
          DialogueId = 80120114,
          GUID = "C8928234",
          NextDialogue = 80120115,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790019},AnimationId{"Sigh_Start"},Duration{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Sigh_End"},Duration{1},_delay{2},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Don't get pissed, the jerks would win. Save your strength, unclench your fist, go soak up the sun with a grin...",
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928234"
        },
        [80120115] = {
          Camera = "32.413086,166.017761,96.0354,0.000066,5.199563,-79.384827,60.0,248.284149,false,Manual,5.0",
          ContentFR = "Pfiou, calme-toi, calme-toi.",
          DialogueId = 80120115,
          GUID = "C892825E",
          NextDialogue = 80120116,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790008},AnimationId{"Explain02_Start"},Duration{1},_click{false}},
PlayAnimation{ActorId{790008},AnimationId{"Explain02_End"},Duration{1},_delay{3},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Whew — Go to your happy place. Go to your happy place...",
          TalkActionId = {
            [1] = "790019:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C892825E"
        },
        [80120116] = {
          Camera = "11.712891,-198.739746,128.95752,0.000035,-5.299714,71.19236,35.000008,243.854416,false,Manual,4.0",
          ContentFR = "Voilà... ça va mieux ! Ce ne sont que des aboiements. Après tout ce temps à Givrelac, je suis habituée.",
          DialogueId = 80120116,
          FacialId = {
            [1] = "790019:Unhappy01"
          },
          GUID = "C8928288",
          NextOptions = {
            [1] = 801201161
          },
          SpeakNpcId = 790019,
          Subtitle = "All set... I'm all good now! Just some barking noise. After all these years in Icelake, I'm so used to it.",
          TurnTo = {
            [1] = "790019:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928288"
        },
        [80120117] = {
          ContentFR = "Petit chien ? Où ça ? Je veux le caresser... Ah, tu parles de Monsieur Kossak.",
          DialogueId = 80120117,
          GUID = "C89282B2",
          NextDialogue = 80120118,
          Scripts = [[
SEQ{
PlayFacial{ActorId{790019},FacialId{"Smile02"}},
PlayFacial{_delay{4},ActorId{790019},FacialId{"Shock01"}},
}]],
          SpeakNpcId = 790019,
          Subtitle = "Doggie? Where? I wanna pet it... Oh, you mean Mr Kossak.",
          TalkActionId = {
            [1] = "790019:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89282B2"
        },
        [80120118] = {
          ContentFR = "Il paraît que c’est un grand compositeur de Dismania, très célèbre. Il a composé une pièce, “L’Hymne de Julius”, que même l’Empereur adore. Chaque année, les soldats la chantent en boucle pendant toute la fête nationale.",
          DialogueId = 80120118,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C89282DC",
          NextDialogue = 80120119,
          SpeakNpcId = 790019,
          Subtitle = "Well, I heard he's a famous composer from Dismania. That \"Julius Anthem\" he wrote — don't know if I got the name right — impressed even the Emperor. Those soldiers sing it every year on National Day.",
          TalkActionId = {
            [1] = "790019:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89282DC"
        },
        [80120119] = {
          Camera = "26.599121,-60.766174,127.509766,0.00013,-3.899717,69.789467,35.000008,130.711365,false,Manual,4.0",
          ContentFR = "Mais je sais pas pourquoi, à l’apogée de sa carrière, il s’est fait virer de la capitale. Depuis, il tape sur son vieux gong au Théâtre Galea. Trente ans que ça dure.",
          DialogueId = 80120119,
          FacialId = {
            [1] = "790019:Doubt01"
          },
          FinalCamera = "26.599121,-60.766174,127.509766,0.00013,-3.899717,69.789467,37.0,130.711365,false,Manual,4.0",
          GUID = "C8928306",
          NextDialogue = 80120120,
          SpeakNpcId = 790019,
          Subtitle = "But for some reason, he was thrown out of the capital at the height of his fame. Ended up in Icelake, banging on that beat-up gong at Galea Theatre for thirty years.",
          TalkActionId = {
            [1] = "790019:Disagree"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928306"
        },
        [80120120] = {
          Camera = "25.643555,148.86615,117.203857,0.000134,-1.299553,-75.005913,35.0,286.089264,false,Manual,4.0",
          ContentFR = "Il paraît qu’il a écrit récemment une symphonie appelée <I>La Gloire d’Hyperborea</>, que des gros bonnets ont aimé et l’ont fait revenir.",
          DialogueId = 80120120,
          GUID = "C8928330",
          NextDialogue = 80120121,
          SpeakNpcId = 790019,
          Subtitle = "But I heard he recently wrote some symphonic works called \"The Glory of Hyperborea,\" and some big shots in the capital liked them enough to bring him back.",
          TalkActionId = {
            [1] = "790019:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928330"
        },
        [80120121] = {
          Camera = "13.561035,-82.322632,125.807861,0.000016,-12.60006,31.003906,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tout ce qu’il restait dans la maison, c’est Camilla qui a été chargée de le gérer. Elle m’a refilé le contrat. Au début, je pensais avoir tiré le gros lot, mais le client... quel numéro. Pas de bol.",
          DialogueId = 80120121,
          FacialId = {
            [1] = "790019:Sad02"
          },
          FinalCamera = "3.181641,-88.561157,128.515381,0.000017,-12.60006,31.004112,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C892835A",
          NextOptions = {
            [1] = 801201211
          },
          Scripts = [[
PARA{
PlayAnimation{ActorId{790019},AnimationId{"Explain02_End"},Duration{1},_click{false}},
SEQ{
PlayAnimation{_delay{8},ActorId{790019},AnimationId{"ScratchHead_Start"},Duration{1},_click{false}},
PlayAnimation{_delay{3},ActorId{790019},AnimationId{"ScratchHead_End"},Duration{1},_click{false}},
},
SEQ{
CameraMoveTo{_delay{7.6},TargetPosition{"32.449707,-25.237549,113.582275,0.000057,3.999902,67.00164,35.0,100000.0,false,DoNotOverride,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"33.751953,-22.16748,113.815186,0.000057,3.999902,67.001724,35.0,100000.0,false,DoNotOverride,2.8"},duration{7}},
},
}]],
          SpeakNpcId = 790019,
          Subtitle = "He turned to Camilla to deal with all the stuff he left behind, and Camilla passed the big job on to me. I thought it was a stroke of luck at first, but it turned out the client was quite the character. Tough break...",
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/inv/Maer/001/C892835A"
        },
        [80120122] = {
          Camera = "13.058594,-189.487427,130.297607,0.000067,-5.400023,73.400612,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ouais, d’habitude je cours entre deux bennes, je récupère ce qui peut encore servir, et je revends à ceux que ça intéresse.",
          DialogueId = 80120122,
          FacialId = {
            [1] = "790019:Ahaha02"
          },
          FinalCamera = "10.127441,-188.613403,130.297607,0.000069,-5.400023,72.800484,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8928384",
          NextDialogue = 80120123,
          SpeakNpcId = 790019,
          Subtitle = "Uh-huh. Normally I'm just hustling between rubbish bins trying to collect anything useful to resell.",
          TalkActionId = {
            [1] = "790019:Agree"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928384"
        },
        [80120123] = {
          Camera = "-379.716797,343.199707,394.461182,0.000096,-29.400166,-38.797962,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais un riche qui laisse autant de trucs derrière sans se retourner, c’est rare. Ce qu’il a laissé vaut une fortune, bon, j’exagère, pas cent poubelles, mais cinquante, c’est sûr !",
          DialogueId = 80120123,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "-379.716797,343.199707,372.476074,0.000104,-27.00005,-39.19701,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89283AE",
          NextDialogue = 80120124,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1},ActorId{790019},AnimationId{"DisagreeHead"},Duration{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Think_Start"},Duration{3},_delay{2},_click{false}},
PlayAnimation{_delay{3},ActorId{790019},AnimationId{"Think_End"},Duration{1},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "It's not often you find a rich guy who leaves behind a houseful of stuff without a second thought. His leftover belongings are worth a fortune — okay, maybe not a hundred bins worth, but definitely fifty at least!",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/inv/Maer/001/C89283AE"
        },
        [80120124] = {
          Camera = "-46.604492,-258.057495,81.282959,0.000152,2.599918,66.012314,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ces vieux meubles en bois sont top, on peut en faire des planches pour des lits ou des tables. J’ai demandé au tailleur, les rideaux, nappes et tapis, après un bon lavage, ça peut servir pour faire des fringues.",
          DialogueId = 80120124,
          FacialId = {
            [1] = "790019:Confident02"
          },
          GUID = "C89283D8",
          NextDialogue = 80120125,
          SpeakNpcId = 790019,
          Subtitle = "Take those antique furniture pieces — the wood is top quality. You could turn them into beds or tables. I also checked with the tailor — those curtains, tablecloths, and rugs can be made into clothes after a few washes.",
          TalkActionId = {
            [1] = "790019:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89283D8"
        },
        [80120125] = {
          Camera = "3.307129,189.679504,120.907227,0.0,-2.599973,-71.797028,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quelques familles des taudis pourront mieux dormir et s’habiller, et moi, je me fais un peu de blé. Même si le musicien a été dur, il a bien payé, hé hé...",
          DialogueId = 80120125,
          GUID = "C8928402",
          NextDialogue = 80120126,
          SpeakNpcId = 790019,
          Subtitle = "A few more families in the slums will get to sleep and dress better, and I'll make a tiny fortune. Plus, even though that musician was quite mean, he was pretty generous with the pay, hehe...",
          TalkActionId = {
            [1] = "790008:Think_Start",
            [2] = "790019:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928402"
        },
        [80120126] = {
          Camera = "30.832031,-69.490662,105.26709,0.000002,4.999924,73.193848,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu trouves pas ça drôle ? J’étais furieuse tout à l’heure, et maintenant, plus du tout !",
          DialogueId = 80120126,
          FacialId = {
            [1] = "790019:Happy01"
          },
          GUID = "C892842C",
          NextDialogue = 80120127,
          SpeakNpcId = 790019,
          Subtitle = "Can you believe it? I was totally upset just a moment ago, but now I'm not mad at all!",
          TalkActionId = {
            [1] = "790019:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C892842C"
        },
        [80120127] = {
          Camera = "-37.370605,-328.404663,168.14209,0.000007,-11.000026,70.593628,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bref, Monsieur Kossak est parti pour Dismania, les pauvres ont du matos, même si j’ai pris une petite engueulade, c’est pas grave ! Dès que je bosse, j’oublie tout !",
          DialogueId = 80120127,
          FacialId = {
            [1] = "790019:Smile01"
          },
          FinalCamera = "-37.370605,-328.404663,152.396973,0.000009,-9.199978,70.193542,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8928456",
          NextOptions = {
            [1] = 801201271,
            [2] = 801201272
          },
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790019},AnimationId{"Explain02_End"},Duration{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"DisagreeHead"},Duration{3},_delay{4},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Anyway, Kossak's off to Dismania, and the folks in the slums get some good supplies. It doesn't matter that I got a little scolding — once I start to get busy, I'll forget all about it!",
          ToFinalCameraBlendTime = 11.5,
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928456"
        },
        [80120128] = {
          Camera = "60.682129,-56.353577,120.300049,0.000009,-0.999721,86.391335,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Super, ça me fera de l’aide pour sortir ses armoires. Prends ce que tu veux pendant qu’on y est.",
          DialogueId = 80120128,
          FacialId = {
            [1] = "790019:Happy02"
          },
          GUID = "C8928480",
          SpeakNpcId = 790019,
          Subtitle = "Oh, that would be great! It's a bit of a chore hauling out his cabinets on my own. Feel free to pick anything you like while we're at it.",
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928480"
        },
        [80120129] = {
          Camera = "60.682129,-56.353577,120.300049,0.000009,-0.999721,86.391335,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Parfait ! Considère ça comme un remerciement d’avoir écouté mes plaintes. Allez, viens m’aider. Choisis ce que tu veux.",
          DialogueId = 80120129,
          FacialId = {
            [1] = "790019:Happy02"
          },
          GUID = "C89284AA",
          SpeakNpcId = 790019,
          Subtitle = "Sure thing! Consider it a thank you for putting up with my grumble. Come on, help me out here. You can pick whatever catches your eye.",
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89284AA"
        },
        [80120130] = {
          ContentFR = "Tu as passé une journée bien remplie avec Margie... Mais une fois chez toi, difficile d’ignorer la douleur dans les bras.",
          DialogueId = 80120130,
          GUID = "C89284D4",
          Subtitle = "You spent a productive day with Margie... Though your arms were sore from all the lifting by bedtime...",
          VoiceName = "voice/$Locale$/inv/Maer/001/C89284D4"
        },
        [80120201] = {
          Camera = "1333.655273,158.495117,593.059387,0.000084,-23.399462,-148.791443,45.0,1393.645752,false,Manual,2.8",
          ContentFR = "Margie a récupéré les affaires que le grand musicien Kossak avait laissées derrière lui et a carrément réquisitionné une pièce entière du Sanctuaire. On entend souvent des bruits de ferraille et de coups de marteau s’en échapper : visiblement, elle y transforme sans relâche du vieux bric-à-brac en trésor.",
          DialogueId = 80120201,
          FinalCamera = "1329.534668,166.603516,574.799133,0.000082,-22.599415,-147.989853,45.0,1393.645752,false,Manual,2.8",
          GUID = "C892907A",
          Scripts = [[
SEQ{
CameraMoveTo{TargetPosition{"-536.0,361.0,216.0,0.000089,-19.999989,-58.799721,35.0,100000.0,false,DoNotOverride,2.8"},duration{3}},
CameraMoveTo{TargetPosition{"-180.185974,-395.118164,75.62677,0.0,0.0,-10.200821,35.0,100000.0,false,DoNotOverride,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"-180.185974,-405.0,75.62677,0.0,0.0,-10.200821,35.0,100000.0,false,DoNotOverride,2.8"},duration{3}},
}]],
          Subtitle = "Margie has taken up a room at Sanctuary to sort through the items left behind by the famous musician Kossak. The constant clatters and clanking from the room suggest she's busy turning waste into treasure.",
          TalkActionId = {
            [1] = "790019:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Maer/002/C892907A"
        },
        [80120202] = {
          ContentFR = "Tu décides d’aller jeter un œil...",
          DialogueId = 80120202,
          GUID = "C89290A4",
          Subtitle = "You decide to check on her...",
          VoiceName = "voice/$Locale$/inv/Maer/002/C89290A4"
        },
        [80120203] = {
          Camera = "-153.358521,286.205566,141.870239,0.000003,-7.000151,-147.997467,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Eh ? {nickname}, c’est toi ? Tu tombes à pic ! Viens voir, j’ai trouvé un truc bizarre !",
          DialogueId = 80120203,
          FacialId = {
            [1] = "790019:Smile01"
          },
          GUID = "C89290CE",
          NextDialogue = 80120204,
          SpeakNpcId = 790019,
          Subtitle = "Oh! , it's you! Come here — I've just stumbled upon something strange!",
          TurnTo = {
            [1] = "790019:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C89290CE"
        },
        [80120204] = {
          Camera = "-225.281067,222.903564,116.151337,0.000004,-0.80002,-144.597412,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est en démontant une armoire que je suis tombée sur cette planche en bois. Tu vas comprendre ce qui cloche si je la tape un peu.",
          DialogueId = 80120204,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "-234.476318,216.367676,116.006004,0.000004,-0.600005,-144.597412,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89290F8",
          NextOptions = {
            [1] = 801202041,
            [2] = 801202042
          },
          SpeakNpcId = 790019,
          Subtitle = "Found this wooden plank while I was taking apart a cabinet. Now, listen to how it sounds when I tap it.",
          TalkActionId = {
            [1] = "790019:Give"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89290F8"
        },
        [80120205] = {
          Camera = "-284.374023,129.285156,139.56041,0.000053,-11.399346,-170.182327,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Exactement ! On dirait bien qu’il y a quelque chose caché dedans.",
          DialogueId = 80120205,
          FacialId = {
            [1] = "790019:Smile02"
          },
          GUID = "C8929122",
          NextDialogue = 80120207,
          SpeakNpcId = 790019,
          Subtitle = "Exactly! The sound isn't right. There's definitely something stashed inside.",
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929122"
        },
        [80120206] = {
          Camera = "-284.374023,129.285156,139.56041,0.000053,-11.399346,-170.182327,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ouais, Kossak se vantait toujours que ses meubles étaient faits en... je sais plus quel bois noble. Mais ce qui compte, c’est que c’est creux !",
          DialogueId = 80120206,
          FacialId = {
            [1] = "790019:Smile02"
          },
          GUID = "C892914C",
          NextDialogue = 80120207,
          SpeakNpcId = 790019,
          Subtitle = "Oh, yeah. Kossak bragged that all his furniture was made from some fancy wood, though I can't remember the name. But what I'm trying to tell you is — it's hollow!",
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C892914C"
        },
        [80120207] = {
          Camera = "232.653351,361.8125,281.633331,0.000094,-18.999201,-161.593491,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Avec mon flair de \"détective\", je te le dis : cette planche cache forcément un truc ! Depuis que je fouille les poubelles, tous les secrets du coin, que je les cherche ou pas, viennent finir dans mon sac.",
          DialogueId = 80120207,
          FacialId = {
            [1] = "790019:Doubt01"
          },
          GUID = "C8929176",
          NextDialogue = 80120208,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790019},AnimationId{"Agree"},Duration{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Think_Start"},Duration{4},_delay{1},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Think_End"},Duration{1},_click{false}}
}]],
          SpeakNpcId = 790019,
          Subtitle = "My detective instincts are telling me this piece of wood must have a breathtaking backstory! Ever since I started treasure hunting around the city's rubbish bins, secrets keep finding their way to me, whether I want them or not.",
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929176"
        },
        [80120208] = {
          Camera = "-233.092163,217.391113,116.084183,0.0,-0.600005,-144.397369,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Des vitres brisées dans les poubelles ? En général, ça veut dire qu’il y a eu une engueulade. Un sac rempli de fringues usées ? Bingo, ils ont touché un héritage. Et je te parle même pas des lettres d’amour déchirées que je ramasse parfois...",
          DialogueId = 80120208,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C89291A0",
          NextDialogue = 80120209,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790019},AnimationId{"Explain01_Start"},Duration{3},_click{false}},
PlayAnimation{ActorId{790019},AnimationId{"Explain01_End"},Duration{1},_click{false}},
PARA{
PlayFacial{_delay{6.5},ActorId{790008},FacialId{"Happy02"}},
LookAt{LookAtDescription{"790019:p(P33010202)"}},
}
}]],
          SpeakNpcId = 790019,
          Subtitle = "Like, if there's broken glass in the bin, it usually means the household just had a fight. If it's a huge bunch of old clothes, then they must've come into cash all of a sudden. And don't get me started on those torn-up love letters I found...",
          VoiceName = "voice/$Locale$/inv/Maer/002/C89291A0"
        },
        [80120209] = {
          Camera = "96.989166,365.946533,258.328094,0.000015,-19.39859,-156.192947,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bon, je m’égare. Revenons à cette planche creuse. Il faisait trop sombre dans la pièce, alors je l’ai sortie ici. J’allais l’ouvrir quand tu es {性别:arrivé|arrivée}. Y a forcément quelque chose là-dedans...",
          DialogueId = 80120209,
          FacialId = {
            [1] = "790019:Ahaha02"
          },
          FinalCamera = "135.622986,382.351562,322.567413,0.000009,-24.598625,-156.393433,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89291CA",
          LookAt = {
            [1] = "790019:n(790008)"
          },
          NextDialogue = 80120290,
          SpeakNpcId = 790019,
          Subtitle = "Anyway, back to this hollow plank. It was too dark in the room, so I brought it out here. I was just about to crack it open when you showed up. There's got to be something interesting hidden inside. Let's see...",
          TalkActionId = {
            [1] = "790019:DisagreeHead"
          },
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89291CA"
        },
        [80120210] = {
          Camera = "-181.880615,263.347656,136.257751,0.000037,-5.797976,-149.392807,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Encore une partition ? Pourtant il avait dit avoir emporté toutes les précieuses avec lui. Alors pourquoi cacher celle-ci ?",
          DialogueId = 80120210,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Atlas/Prop/Item/T_Read_02.T_Read_02'}",
          FacialId = {
            [1] = "790019:Shock01"
          },
          GUID = "C89291F4",
          NextDialogue = 80120211,
          SpeakNpcId = 790019,
          Subtitle = "...Another music score? Kossak said he'd take all the valuable ones with him. But if this one wasn't important to him, why did he go through the trouble of hiding it so carefully?",
          VoiceName = "voice/$Locale$/inv/Maer/002/C89291F4"
        },
        [80120211] = {
          Camera = "-288.548035,170.670166,120.789764,0.000075,0.402121,-147.390503,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Voyons un peu... <I>Les Démons brisent leurs chaînes</> ? Jamais entendu parler de celle-là...",
          DialogueId = 80120211,
          FacialId = {
            [1] = "790019:Doubt01"
          },
          GUID = "C892921E",
          NextOptions = {
            [1] = 801202111
          },
          Scripts = "PlayAnimation{_delay{3},ActorId{790019},AnimationId{\"Think_End\"},Duration{1},_click{false}},",
          SpeakNpcId = 790019,
          Subtitle = "Lemme see what it's about... \"Demons Broken Loose\"? Never heard of this piece before...",
          TalkActionId = {
            [1] = "790019:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C892921E"
        },
        [80120212] = {
          Camera = "-409.604431,-6.535156,126.660339,0.000048,-2.997824,66.607025,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "« Salut, Kossak du futur. Est-ce que t’es heureux ? Ou toujours pas ? Juste pour te prévenir : je vais tenter quelque chose de risqué. »",
          DialogueId = 80120212,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "-407.011719,-7.655762,126.660339,0.000048,-2.997797,66.607208,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929248",
          LookAt = {
            [1] = "790019:p(P33010202)"
          },
          NextDialogue = 80120213,
          SpeakNpcId = 790019,
          Subtitle = "\"Hello there, future me. How are you? Are you happy with your life now? Just a heads up — I'm about to take a risky leap:\"",
          TalkActionId = {
            [1] = "790008:Talk03_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929248"
        },
        [80120213] = {
          Camera = "-144.685608,266.765869,90.548981,0.000028,3.199581,-150.191788,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "« Je vais composer une œuvre sur le peuple qu’on ignore le plus dans notre pays : les Charons. Bonne idée, non ? »",
          DialogueId = 80120213,
          FacialId = {
            [1] = "790019:Shock01"
          },
          FinalCamera = "-143.404663,264.529785,90.548981,0.000028,3.199581,-150.191788,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929272",
          LookAt = {
            [1] = "790019:p(P33010202)"
          },
          NextDialogue = 80120214,
          SpeakNpcId = 790019,
          Subtitle = "\"I'm writing a composition about our land's most overlooked community — Charons. Sounds like a great idea, doesn't it?\"",
          TalkActionId = {
            [1] = "790008:Talk03_End"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929272"
        },
        [80120214] = {
          Camera = "117.682922,273.904541,278.035675,0.000035,-23.000122,-167.605408,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "« Je ne sais pas ce que ça va donner... Si tout se passe bien, ça me fera un nom et peut-être qu’on commencera à compatir pour eux. Mais y a plus de chances que les anciens me hurlent dessus pour avoir \"souillé\" l’art. »",
          DialogueId = 80120214,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "149.964203,280.998291,292.065369,0.000035,-23.000122,-167.605408,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C892929C",
          NextDialogue = 80120215,
          SpeakNpcId = 790019,
          Subtitle = "\"I don't know what will come of it after it's published. Hopefully, it'll earn me some recognition and maybe even get people to sympathize with the Charon community. But it's more likely that the old guard will scold me for 'sullying music.'\"",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/inv/Maer/002/C892929C"
        },
        [80120215] = {
          Camera = "401.697601,87.518555,94.828476,0.000034,-2.599092,173.794434,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "« Peut-être que je regretterai bientôt cette impulsion, mais là, tout de suite, je suis sûr d’une chose : je fais ce qu’il faut. »",
          DialogueId = 80120215,
          FacialId = {
            [1] = "790019:None"
          },
          FinalCamera = "401.697601,87.518555,124.666946,0.000034,-4.599217,173.394348,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89292C6",
          NextDialogue = 80120216,
          SpeakNpcId = 790019,
          Subtitle = "\"I might regret this decision someday, but at the moment, I believe in what I'm doing.\"",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89292C6"
        },
        [80120216] = {
          Camera = "787.620972,-53.718506,1202.445679,0.000004,-45.999557,170.397659,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "« Alors je laisse une copie ici, au cas où toi, ou ces vieux croûtons, décidiez de réduire mon œuvre en cendres. »",
          DialogueId = 80120216,
          FinalCamera = "697.515381,213.27832,1078.197266,0.000005,-44.799149,-177.402649,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89292F0",
          NextDialogue = 80120217,
          SpeakNpcId = 790019,
          Subtitle = "\"So, I'm leaving a copy here, just in case the cold shoulder — or those old guard bigots — end up destroying my hard work.\"",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89292F0"
        },
        [80120217] = {
          Camera = "1272.104248,1465.506348,636.589355,0.000045,-20.798307,-178.202515,60.0,1238.551392,false,Manual,2.8",
          ContentFR = "« J’espère qu’en rouvrant cette lettre, t’entendras les Charons chanter cette musique sous ta fenêtre. Et surtout, que tu pourras sourire, comme moi maintenant. »",
          DialogueId = 80120217,
          FinalCamera = "1271.768799,1475.04248,636.589355,0.000045,-20.598291,-178.002518,60.0,1238.551392,false,Manual,2.8",
          GUID = "C892931A",
          LookAt = {
            [1] = "790019:n(790008)"
          },
          NextDialogue = 80120218,
          SpeakNpcId = 790019,
          Subtitle = "\"I really hope that by the time you read this letter, you'll hear Charons singing this song outside your window. And I hope you'll be able to smile at life, like I'm doing right now.\"",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C892931A"
        },
        [80120218] = {
          Camera = "-393.488953,121.270996,118.823044,0.000066,3.202293,41.604927,60.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 80120218,
          FacialId = {
            [1] = "790019:Sad01"
          },
          GUID = "C8929344",
          LookAt = {
            [1] = "790019:n(790008)"
          },
          NextOptions = {
            [1] = 801202181,
            [2] = 801202182
          },
          SpeakNpcId = 790019,
          Subtitle = "...",
          TalkActionId = {
            [1] = "790008:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929344"
        },
        [80120219] = {
          Camera = "-318.570557,225.146973,124.440643,0.000003,-1.999934,-117.594925,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ouais... ce Kossak-là, du passé... il avait l’air d’un chic type.",
          DialogueId = 80120219,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C892936E",
          NextDialogue = 80120222,
          SpeakNpcId = 790019,
          Subtitle = "That Kossak... he was really a decent fellow back then.",
          TalkActionId = {
            [1] = "790019:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C892936E"
        },
        [80120220] = {
          Camera = "-318.570557,225.146973,124.440643,0.000003,-1.999934,-117.594925,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hmm... Pas impossible. Il se fichait de la plupart de ses partitions, mais il était certain que ses plus précieuses étaient « bien à l’abri là où elles doivent être »...",
          DialogueId = 80120220,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C8929398",
          LookAt = {
            [1] = "790019:p(P33010201)",
            [2] = "790008:p(P33010201)"
          },
          NextDialogue = 80120221,
          SpeakNpcId = 790019,
          Subtitle = "Hmm... You might be right. He didn't care about most of his music scores, but he was awfully sure that his most important pieces had been \"well secured where they belong\"...",
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929398"
        },
        [80120221] = {
          Camera = "-440.217041,86.593506,117.899193,0.000059,-0.799351,34.609612,35.0,234.284531,false,Manual,5.0",
          ContentFR = "Donc peut-être que pour lui, celle-là était la plus précieuse. Et « là où elles doivent être », c’était dans les mains d’un Charon, parce qu’elle leur était destinée.",
          DialogueId = 80120221,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C89293C2",
          LookAt = {
            [1] = "790019:n(790008)",
            [2] = "790008:n(790019)"
          },
          NextDialogue = 80120222,
          SpeakNpcId = 790019,
          Subtitle = "So maybe, just maybe, this score was the one he cherished most. And the \"right place\" for it was in the hands of a Charon — because it was written for them.",
          TalkActionId = {
            [1] = "790019:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C89293C2"
        },
        [80120222] = {
          Camera = "-252.260193,281.916748,126.221512,0.000009,-3.999636,-119.588837,35.0,234.284531,false,Manual,5.0",
          ContentFR = "Les paroles sont superbes... J’aimerais bien savoir à quoi elle ressemble, chantée.",
          DialogueId = 80120222,
          FacialId = {
            [1] = "790019:Ahaha02"
          },
          GUID = "C89293EC",
          LookAt = {
            [1] = "790019:n(790019)"
          },
          NextDialogue = 80120223,
          SpeakNpcId = 790019,
          Subtitle = "The lyrics are really something... I wonder what this song will sound like.",
          TalkActionId = {
            [1] = "790019:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C89293EC"
        },
        [80120223] = {
          Camera = "-304.703491,193.633301,104.081329,-0.0,7.999981,-131.396408,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Bon, c’est décidé !",
          DialogueId = 80120223,
          FacialId = {
            [1] = "790019:Confident02"
          },
          GUID = "C8929416",
          LookAt = {
            [1] = "790019:n(790008)"
          },
          NextDialogue = 80120224,
          SpeakNpcId = 790019,
          Subtitle = "Alright — I've made up my mind!",
          TalkActionId = {
            [1] = "790019:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929416"
        },
        [80120224] = {
          Camera = "-255.582703,344.383789,69.178757,0.000035,7.599951,-112.388451,35.000008,264.602783,false,Manual,2.8",
          ContentFR = "Qu’il l’ait oubliée ou laissée volontairement, peu importe. Il m’a confié ses affaires. Je dois faire ça sérieusement.",
          DialogueId = 80120224,
          GUID = "C8929440",
          NextDialogue = 80120225,
          SpeakNpcId = 790019,
          Subtitle = "Whether Kossak forgot about this score or left it behind on purpose, he trusted me to handle his stuff, so I'm going to take it seriously.",
          TalkActionId = {
            [1] = "790019:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929440"
        },
        [80120225] = {
          Camera = "-501.36084,57.133301,131.599701,0.000011,-4.399932,31.404215,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Viens, {nickname}, on va voir Camilla. Je crois qu’elle sait lire les partitions. Je vais lui demander de m’apprendre à la chanter.",
          DialogueId = 80120225,
          FacialId = {
            [1] = "790019:None"
          },
          GUID = "C892946A",
          NextDialogue = 80120226,
          SpeakNpcId = 790019,
          Subtitle = "Come on, , let's head over to Ms Camilla's tavern. I think she can read music. I'm going to ask her to teach me this song.",
          TalkActionId = {
            [1] = "790019:Explain02_End",
            [2] = [[

790008:AgreeHead]]
          },
          VoiceName = "voice/$Locale$/inv/Maer/002/C892946A"
        },
        [80120226] = {
          Camera = "-302.98645,187.943359,114.158592,0.000014,3.400027,-133.7966,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Et une fois que je saurai, j’apprendrai cette chanson aux Charons de Givrelac. Je leur dirai qu’un grand musicien a écrit ça spécialement pour eux.",
          DialogueId = 80120226,
          FacialId = {
            [1] = "790019:Happy01"
          },
          FinalCamera = "-302.98645,187.943359,114.158592,0.000026,3.400027,-133.7966,36.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929494",
          NextDialogue = 80120227,
          SpeakNpcId = 790019,
          Subtitle = "Once I've learned it, I'll teach it to all the Charons in Icelake. I'll tell them it's a song written especially for us by a respected musician.",
          TalkActionId = {
            [1] = "790019:Talk02_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929494"
        },
        [80120227] = {
          Camera = "193.657837,-330.853027,153.108017,0.0,0.0,179.200912,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Comme ça, elle ne finira pas en fumée, brûlée avec les autres partitions ratées.",
          DialogueId = 80120227,
          FinalCamera = "153.661621,-330.320312,153.108017,0.0,0.0,179.200912,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89294BE",
          NextDialogue = 80120228,
          SpeakNpcId = 790019,
          Subtitle = "That way, this song won't end up like his discarded drafts, tossed into the fire and burned to ashes.",
          TalkActionId = {
            [1] = "790019:Talk02_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89294BE"
        },
        [80120228] = {
          Camera = "79.69873,985.43457,55.531265,0.000044,12.80017,92.181931,55.0,490.84668,false,Manual,1.2",
          ContentFR = "Et qui sait ? Peut-être qu’un jour, cette chanson résonnera jusqu’à la capitale. Peut-être qu’il entendra les Charons la chanter. Mais même s’il ne l’entend jamais, c’est pas grave. J’aurai fait ma part.",
          DialogueId = 80120228,
          FinalCamera = "103.997955,961.556152,69.737282,0.000067,10.600037,97.981682,55.0,490.84668,false,Manual,1.2",
          GUID = "C89294E8",
          NextDialogue = 80120229,
          SpeakNpcId = 790019,
          Subtitle = "Who knows? Maybe one day, this song will reach the capital, so he'll hear Charons singing it outside his window. But even if that won't happen, it doesn't matter. I'll have done my job—",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Maer/002/C89294E8"
        },
        [80120229] = {
          Camera = "-312.233704,183.148438,116.782532,0.000004,2.399917,-130.594269,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Redonner vie à ce qui n’aurait jamais dû finir à la benne, c’est ça, ma mission !",
          DialogueId = 80120229,
          FacialId = {
            [1] = "790019:Happy02"
          },
          FinalCamera = "-316.72876,177.902344,117.07206,0.000004,2.399917,-130.594269,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C8929512",
          Scripts = "CameraMoveTo{_delay{2},TargetPosition{\"-285.357117,180.728271,121.084183,0.0,0.0,-143.597351,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}}",
          SpeakNpcId = 790019,
          Subtitle = "Bringing forgotten treasures back into the light and letting their value be seen — that's my mission!",
          TalkActionId = {
            [1] = "790019:Angry01_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929512"
        },
        [80120230] = {
          ContentFR = "D’après Camilla, <I>Les Démons brisent leurs chaînes</> est effectivement une œuvre brillante, mais aussi redoutablement difficile à chanter.",
          DialogueId = 80120230,
          Duration = 4,
          GUID = "C892953C",
          NextDialogue = 80120231,
          Subtitle = "Later, according to Camilla, \"Demons Broken Loose\" is indeed a brilliant piece, and quite a challenging one.",
          VoiceName = "voice/$Locale$/inv/Maer/002/C892953C"
        },
        [80120231] = {
          ContentFR = "Il aura fallu trois jours à Margie pour la maîtriser, en descendant même d’un octave. Peu après, on entendait déjà sa mélodie flotter dans les rues de Givrelac.",
          DialogueId = 80120231,
          Duration = 5,
          GUID = "C8929566",
          NextDialogue = 80120232,
          Subtitle = "It took Margie three full days to master the song, and even then, she had to transpose it down an octave. Before long, echoes of the melody began to drift through the streets of Icelake.",
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929566"
        },
        [80120232] = {
          ContentFR = "C’est ça, selon Margie, l’art de transformer les déchets en trésors.",
          DialogueId = 80120232,
          Duration = 3,
          GUID = "C8929590",
          Subtitle = "Seems like Margie has accomplished her mission of bringing forgotten treasures back into the light.",
          VoiceName = "voice/$Locale$/inv/Maer/002/C8929590"
        },
        [80120290] = {
          DialogueId = 80120290,
          GUID = "C89291CB",
          IsBlack = 1,
          NextDialogue = 80120210,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_woodbrk\"},PlayAs2D{true}}"
        },
        [80120301] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentFR = "Hmm...",
          DialogueId = 80120301,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892A0E2",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextDialogue = 80120302,
          SpeakNpcId = 93301,
          Subtitle = "Hmm...",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A0E2"
        },
        [80120302] = {
          ContentFR = "C’est à la fois amer et sucré... Beurk, c’est exactement le genre de goût que mon vieux crétin adore ! Moi, je pense qu’il me faudra encore dix, non, vingt ans pour apprécier ça.",
          DialogueId = 80120302,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A10C",
          NextOptions = {
            [1] = 801203021,
            [2] = 801203031
          },
          SpeakNpcId = 93301,
          Subtitle = "Bitter and sweet at the same time... Ugh, this tastes like something my stupid old man would love! As for me, I think I'll need another ten... no, make that twenty years to appreciate this taste.",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A10C"
        },
        [80120303] = {
          ContentFR = "Je ne comprends pas du tout ! Pourquoi s’infliger un goût aussi amer ?!",
          DialogueId = 80120303,
          FacialId = {
            [1] = "93301:Doubt01"
          },
          GUID = "C892A136",
          NextOptions = {
            [1] = 801203041
          },
          SpeakNpcId = 93301,
          Subtitle = "I just don't get this drink! Why would anyone want to torture themselves with this bitter taste?",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A136"
        },
        [80120304] = {
          ContentFR = "Exact ! Après une journée de boulot, quelques verres bien frais, ça dénoue tout, de la tête aux pieds !",
          DialogueId = 80120304,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A160",
          NextOptions = {
            [1] = 801203041
          },
          SpeakNpcId = 93301,
          Subtitle = "Exactly! Nothing beats a refreshing drink after a day's work — it's like a cool wave from head to toe!",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A160"
        },
        [80120305] = {
          ContentFR = "Mon père ! Tout le monde l’appelle le vieux Martin. Avant que je reprenne le flambeau, il gérait toutes les poubelles de Givrelac.",
          DialogueId = 80120305,
          FacialId = {
            [1] = "93301:Syouganai01"
          },
          GUID = "C892A18A",
          NextDialogue = 80120306,
          SpeakNpcId = 93301,
          Subtitle = "Oh, that's my dad! They call him Old Martin. Before I took over, he was the one managing all the rubbish bins in Icelake.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A18A"
        },
        [80120306] = {
          ContentFR = "Si tout le monde ne l’avait pas surnommé « Roi des Déchets », je n’aurais pas hérité du ridicule surnom de « Princesse des Déchets »... Ce vieux crétin m’a vraiment mise dans une sacrée galère !",
          DialogueId = 80120306,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A1B4",
          NextDialogue = 80120307,
          SpeakNpcId = 93301,
          Subtitle = "If it weren't for his stupid title \"King of the Bins,\" I wouldn't be stuck with that tacky, lame nickname \"Princess Rubbish Bin\"... Ugh, it's all that flashy old man's fault!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A1B4"
        },
        [80120307] = {
          ContentFR = "Moi, j’aurais préféré un surnom plus cool, plus intelligent, plus fiable...",
          DialogueId = 80120307,
          FacialId = {
            [1] = "93301:Iyada01"
          },
          GUID = "C892A1DE",
          NextOptions = {
            [1] = 801203071,
            [2] = 801203081
          },
          SpeakNpcId = 93301,
          Subtitle = "I mean, I was hoping for something cooler, smarter, and more reliable...",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A1DE"
        },
        [80120308] = {
          ContentFR = "Exactement ! Hé hé, tu me comprends !",
          DialogueId = 80120308,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A208",
          NextDialogue = 80120310,
          SpeakNpcId = 93301,
          Subtitle = "That's right! Hehe, you totally get me!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A208"
        },
        [80120309] = {
          ContentFR = "Aaah, tais-toi, tais-toi ! Sinon, je t’assomme avec ma pelle !",
          DialogueId = 80120309,
          FacialId = {
            [1] = "93301:Disappoint01"
          },
          GUID = "C892A232",
          NextDialogue = 80120310,
          SpeakNpcId = 93301,
          Subtitle = "Aaaah! Stop it! I'll whack you with my shovel if you say that again!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A232"
        },
        [80120310] = {
          ContentFR = "Pfff... Depuis qu’il m’a refilé tout le boulot, je ne le vois plus. Aucune idée de ce qu’il fout. J’espère qu’il ne va pas nous attirer d’ennuis, à moi et à Madame Camilla !",
          DialogueId = 80120310,
          FacialId = {
            [1] = "93301:Unhappy01"
          },
          GUID = "C892A25C",
          NextOptions = {
            [1] = 801203101
          },
          SpeakNpcId = 93301,
          Subtitle = "Ugh... ever since that stupid old man dumped all the work on me, I barely see him around. No idea what he's been doing. He better not be causing trouble for me and Ms Camilla!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A25C"
        },
        [80120311] = {
          ContentFR = "Euh, si ce n’était pas pour ce goût amer... en fait, ça fait un moment que je ne pense plus trop à ce vieux crétin...",
          DialogueId = 80120311,
          FacialId = {
            [1] = "93301:Uninterested01"
          },
          GUID = "C892A286",
          NextOptions = {
            [1] = 801203111,
            [2] = 801203121
          },
          SpeakNpcId = 93301,
          Subtitle = "Uh, well... if it weren't for this bitter taste, I guess I haven't really thought about him in a while...",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A286"
        },
        [80120312] = {
          ContentFR = "Je bosse beaucoup aussi, hein ! Et puis, au final, tout ce boulot, c’est lui qui me l’a refilé !",
          DialogueId = 80120312,
          FacialId = {
            [1] = "93301:Shock02"
          },
          GUID = "C892A2B0",
          NextDialogue = 80120314,
          SpeakNpcId = 93301,
          Subtitle = "Well, in my defence, I've been swamped with work! His work, to be precise!",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A2B0"
        },
        [80120313] = {
          ContentFR = "Hé hé... Quand les petits animaux grandissent, ils quittent le nid pour se débrouiller seuls. C’est normal.",
          DialogueId = 80120313,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A2DA",
          NextDialogue = 80120314,
          SpeakNpcId = 93301,
          Subtitle = "Ahem... Well, you know, when little animals grow up, they leave the nest to fend for themselves. It's totally normal.",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A2DA"
        },
        [80120314] = {
          ContentFR = "Et puis, pendant les dix premières années de ma vie, ce vieux crétin ne me lâchait pas. Surtout après qu’on a quitté notre vieille maison pour Givrelac, on a passé une année entière dans les champs enneigés, rien que tous les deux, sans croiser âme qui vive.",
          DialogueId = 80120314,
          GUID = "C892A304",
          NextDialogue = 80120315,
          SpeakNpcId = 93301,
          Subtitle = "Besides, that stupid old man has been fussing over me for more than ten years. Especially after we left our old home for Icelake — we spent a whole year trekking across the snowfields, just the two of us, not another living soul in sight.",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A304"
        },
        [80120315] = {
          ContentFR = "J’en ai déjà trop entendu de ses histoires, ses chansons, ses combines... Alors, je ne pense plus tellement à lui... Enfin, presque.",
          DialogueId = 80120315,
          GUID = "C892A32E",
          NextDialogue = 80120316,
          SpeakNpcId = 93301,
          Subtitle = "I've had enough of his tales, his songs, and his tricks to last me a lifetime. So... I guess that's why I don't really miss him that much... probably.",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A32E"
        },
        [80120316] = {
          ContentFR = "Et puis, à peine arrivés à Givrelac, ce vieux crétin a commencé à \"se tailler son territoire\", \"recruter des hommes de main\", \"organiser un racket de protection\", \"s’allier avec les puissants locaux\" et \"devenir le grand chef\". Il avait l’air de bien s’amuser tout seul.",
          DialogueId = 80120316,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892A358",
          NextOptions = {
            [1] = 801203161
          },
          SpeakNpcId = 93301,
          Subtitle = "Plus, soon after we arrived in Icelake, he jumped right into \"staking out territories,\" \"recruiting the local henchmen,\" \"figuring out the protection racket,\" \"making alliances with local powers,\" and \"becoming the top dog.\" He seemed to enjoy himself just fine on his own.",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A358"
        },
        [80120317] = {
          ContentFR = "Ah non, non, c’est juste qu’il a cartographié les emplacements des poubelles, recruté les éboueurs, fixé les règles pour la collecte, trouvé des commerçants intéressés par le recyclage grâce à Camilla, et fini par devenir le « Roi des Déchets ».",
          DialogueId = 80120317,
          FacialId = {
            [1] = "93301:Smile02"
          },
          GUID = "C892A382",
          NextDialogue = 80120318,
          SpeakNpcId = 93301,
          Subtitle = "Oh, it's actually just mapping out the rubbish bin locations, recruiting the sanitation workers, setting rules for rubbish collection, finding buyers through Ms Camilla, and becoming the \"King of the Bins.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A382"
        },
        [80120318] = {
          ContentFR = "Ce vieux crétin adore raconter ses histoires grandiloquentes, comme un comédien avec ses dialogues tout écrits ! Il doit traîner ces mauvaises habitudes depuis son patelin où ça bastonnait tout le temps. Il n’arrive pas à s’en défaire, pfff...",
          DialogueId = 80120318,
          GUID = "C892A3AC",
          NextOptions = {
            [1] = 801203181
          },
          SpeakNpcId = 93301,
          Subtitle = "Ugh, that stupid old man loves spouting off fancy talk — he sounds like a flashy character from a drama script! Bad habits from his rough-and-tumble days back home, I guess. He can't seem to shake them off. Gah!",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A3AC"
        },
        [80120319] = {
          ContentFR = "C’est pas simple à dire ! Le vieux adore se vanter de ses \"exploits glorieux\" là-bas. Genre...",
          DialogueId = 80120319,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A3D6",
          NextDialogue = 80120320,
          SpeakNpcId = 93301,
          Subtitle = "It's hard to say! The old man always liked to brag about his \"glorious past\" back home. Stuff like...",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A3D6"
        },
        [80120320] = {
          ContentFR = "« Chaque mission d’un récupérateur touche à l’honneur personnel et à l’intérêt familial. Du plan au moindre détail, tout doit être parfait. Et ton père, c’est le meilleur récupérateur de tous. »",
          DialogueId = 80120320,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A400",
          NextDialogue = 80120321,
          SpeakNpcId = 93301,
          Subtitle = "\"A scavenger's every mission is a matter of personal honour and family interest. From daily planning to personal grooming, everything must be meticulously prepared. And your father, my dear, was the finest scavenger of all.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A400"
        },
        [80120321] = {
          ContentFR = "C’est à cause de son influence que, quand je suis arrivée à Givrelac, je parlais exactement comme un « petit Martin ». Camilla en avait marre et a mis un temps fou à me faire perdre cet accent.",
          DialogueId = 80120321,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A42A",
          NextOptions = {
            [1] = 801203211
          },
          SpeakNpcId = 93301,
          Subtitle = "Ugh, his bad influence is why, when I first got to Icelake, I talked exactly like a \"Mini-Martin.\" Ms Camilla said it was really annoying, and it took her forever to help me lose that tone...",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A42A"
        },
        [80120322] = {
          ContentFR = "Non merci, c’est trop honteux !",
          DialogueId = 80120322,
          FacialId = {
            [1] = "93301:Unacceptable01"
          },
          GUID = "C892A454",
          NextOptions = {
            [1] = 801203221,
            [2] = 801203231
          },
          SpeakNpcId = 93301,
          Subtitle = "No way! That's too embarrassing!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A454"
        },
        [80120323] = {
          ContentFR = "Bon, juste cette fois, hein ! Après, plus jamais.",
          DialogueId = 80120323,
          FacialId = {
            [1] = "93301:Smile02"
          },
          GUID = "C892A47E",
          NextDialogue = 80120325,
          SpeakNpcId = 93301,
          Subtitle = "Fine, just this once, okay? No encores!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A47E"
        },
        [80120324] = {
          ContentFR = "Aaaah ! J’abandonne, j’abandonne ! Arrête, s’il te plaît !",
          DialogueId = 80120324,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A4A8",
          NextDialogue = 80120325,
          SpeakNpcId = 93301,
          Subtitle = "Aaaahhhh!!! Okay, okay! I'll do it! Just stop already!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4A8"
        },
        [80120325] = {
          ContentFR = "Alors voilà... Quand le vieux Martin m’a déposée chez Camilla pour partir gérer ses affaires, je lui disais...",
          DialogueId = 80120325,
          FacialId = {
            [1] = "93301:Think01"
          },
          GUID = "C892A4D2",
          NextDialogue = 80120326,
          SpeakNpcId = 93301,
          Subtitle = "Uh… When Old Martin dropped me off at Ms Camilla's tavern before he went off to do who-knows-what, I'd say...",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4D2"
        },
        [80120326] = {
          ContentFR = "« Souviens-toi de ta mission, Père. Notre avenir dépend de chacune de tes actions. J’espère que tu as bien lavé ton visage, brossé tes dents, et que tu as un plan béton. »",
          DialogueId = 80120326,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A4FC",
          NextOptions = {
            [1] = 801203261
          },
          SpeakNpcId = 93301,
          Subtitle = "\"Remember your mission, Father. Our future hinges on your every move, so I trust you've washed your face, brushed your teeth, and made a thorough plan.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4FC"
        },
        [80120327] = {
          ContentFR = "Et lui, il ôtait son chapeau et me répondait : « À vos ordres, madame ! Si l’un de nous échoue, on écrira son nom avec \"idiot\" sur la porte des Asphodèles pour que tout le monde voie. »",
          DialogueId = 80120327,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A526",
          NextOptions = {
            [1] = 801203271
          },
          SpeakNpcId = 93301,
          Subtitle = "And then Old Martin would tip his hat and say, \"As you command, ma'am! Should either of us fail, we'll inscribe that person's name with the modifier \"idiot\" on The Asphodel's door for all to see.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A526"
        }
      }
    end
  },
  {
    MinKey = 80120328,
    MaxKey = 80130409,
    Loader = function()
      return {
        [80120328] = {
          ContentFR = "Et je lui rétorquais : « Puisqu’on porte le même nom, autant l’écrire au fond d’une marmite, ça m’évitera la honte et le feu du foyer brûlera ta disgrâce ! »",
          DialogueId = 80120328,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A550",
          NextOptions = {
            [1] = 801203281
          },
          SpeakNpcId = 93301,
          Subtitle = "And I'd reply, \"Oh, considering we share a last name, better to inscribe it on the bottom of a pot instead — saves me the shame and allows the stove fire to scorch your disgrace!\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A550"
        },
        [80120329] = {
          ContentFR = "Hahahahahaha !",
          DialogueId = 80120329,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A57A",
          NextDialogue = 80120330,
          SpeakNpcId = 100001,
          Subtitle = "Ahahahahahahaha!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A57A"
        },
        [80120330] = {
          ContentFR = "Maintenant, je comprends mieux pourquoi tu t’appelles « Princesse des Déchets », c’est pas entièrement la faute de Martin, hein.",
          DialogueId = 80120330,
          GUID = "C892A5A4",
          NextDialogue = 80120331,
          SpeakNpcId = 100001,
          Subtitle = "Now I see why you ended up with the title \"Princess Rubbish Bin\" — it's not all Old Martin's fault!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5A4"
        },
        [80120331] = {
          ContentFR = "Je m’en fiche ! C’est entièrement sa faute ! Rien que de penser que j’ai failli devenir un fanfaron comme lui, j’en ai des frissons.",
          DialogueId = 80120331,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892A5CE",
          NextDialogue = 80120332,
          SpeakNpcId = 93301,
          Subtitle = "I don't care! It's totally his fault! Just thinking I almost turned into a pompous blowhard like him gives me the chills.",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5CE"
        },
        [80120332] = {
          ContentFR = "Tu sais, j’ai capté que, même si ce vieux crétin critique le chaos de notre ancien chez-nous, il y est attaché et fier en secret. Je crois pas qu’il soit parti juste parce qu’il détestait l’anarchie.",
          DialogueId = 80120332,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A5F8",
          NextDialogue = 80120333,
          SpeakNpcId = 93301,
          Subtitle = "And I don't know if you figured this out — the stupid old man clearly misses and takes pride in his past. I don't think he left home just because he hated the chaos there.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5F8"
        },
        [80120333] = {
          ContentFR = "Mais qu’est-ce qui a bien pu se passer pour qu’il prenne la décision de me traîner à travers la neige, à fuir notre patelin ?",
          DialogueId = 80120333,
          FacialId = {
            [1] = "93301:Unhappy02"
          },
          GUID = "C892A622",
          NextDialogue = 80120334,
          SpeakNpcId = 93301,
          Subtitle = "But what could have happened that made him leave home and drag me across the snowfields?",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A622"
        },
        [80120334] = {
          ContentFR = "Il doit cacher un secret énorme ! Mais dès que je lui pose la question, il me répond toujours : « Je ne te dirai rien. Si tu veux savoir, débrouille-toi toute seule. »",
          DialogueId = 80120334,
          FacialId = {
            [1] = "93301:Doubt01"
          },
          GUID = "C892A64C",
          NextDialogue = 80120335,
          SpeakNpcId = 93301,
          Subtitle = "He's definitely hiding something huge from me! But every time I ask, all he says is, \"I won't tell you. If you do want to know, use your head and figure it out yourself.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A64C"
        },
        [80120335] = {
          ContentFR = "Alors l’année dernière, je l’ai espionné pendant des mois. Mais ce vieux est une vraie ombre, et les affaires qu’il a ramenées de chez nous, personne ne sait où elles sont cachées.",
          DialogueId = 80120335,
          GUID = "C892A676",
          NextDialogue = 80120336,
          SpeakNpcId = 93301,
          Subtitle = "So last year, I secretly investigated him for months. But the old man's so crafty and sneaky, he even hid the stuff he brought from our hometown. I couldn't find it no matter what.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A676"
        },
        [80120336] = {
          ContentFR = "J’ai creusé pendant des mois, sans rien trouver. Et pour couronner le tout, il s’est moqué de moi.",
          DialogueId = 80120336,
          FacialId = {
            [1] = "93301:Syouganai01"
          },
          GUID = "C892A6A0",
          NextOptions = {
            [1] = 801203361
          },
          SpeakNpcId = 93301,
          Subtitle = "After months of digging, I came up empty. And to top it off, he had the nerve to mock me—",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6A0"
        },
        [80120337] = {
          ContentFR = "Oui, moqué ! Un jour, alors qu’on s’y attendait le moins, le vieux est revenu. Il a passé la journée avec moi, et en partant, il a carrément oublié sa valise, celle qu’il avait ramenée de chez nous !",
          DialogueId = 80120337,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A6CA",
          NextDialogue = 80120338,
          SpeakNpcId = 93301,
          Subtitle = "One day, out of nowhere, the old man actually showed up. He spent the whole day with me, and even forgot to take his suitcase with him when he left — the one he brought from our hometown!",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6CA"
        },
        [80120338] = {
          ContentFR = "Je me suis dit : « Enfin, le vieux a laissé une trace ! » J’ouvre la valise, et dedans, y’avait juste une marmite...",
          DialogueId = 80120338,
          GUID = "C892A6F4",
          NextDialogue = 80120339,
          SpeakNpcId = 93301,
          Subtitle = "I thought, \"Ha! That old man slipped up at last!\" So I opened the suitcase, and inside... was just a pot.",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6F4"
        },
        [80120339] = {
          ContentFR = "Margie tape avec colère sur la marmite posée sur sa tête, ça fait un bruit creux.",
          DialogueId = 80120339,
          GUID = "C892A71E",
          NextDialogue = 80120340,
          Subtitle = "(Margie angrily taps on the pot she's wearing on her head, producing a hollow sound.)",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A71E"
        },
        [80120340] = {
          ContentFR = "C’est ça ! Et y’avait un mot dans la valise...",
          DialogueId = 80120340,
          GUID = "C892A748",
          NextDialogue = 80120341,
          SpeakNpcId = 93301,
          Subtitle = "This thing right here! And he left a note in the suitcase...",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A748"
        },
        [80120341] = {
          ContentFR = "« Chère Margie, je savais que tu fouillerais cette valise pour découvrir mon secret. J’ai donc déplacé le secret là où tu ne t’y attendra pas. »",
          DialogueId = 80120341,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A772",
          NextDialogue = 80120342,
          SpeakNpcId = 93301,
          Subtitle = "\"Dear Miss Margie, I knew you'd snoop in this suitcase, so I've relocated the secret to a place you'd least expect.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A772"
        },
        [80120342] = {
          ContentFR = "« Pour te faire pardonner ta déception, je t’offre cet objet, un casque multifonction ! Porté à l’endroit, il protège ta tête, retourné, c’est une marmite pour cuisiner, et la lampe fixée à l’avant éclaire le chemin. L’outil parfait, à la maison comme en voyage. »",
          DialogueId = 80120342,
          GUID = "C892A79C",
          NextDialogue = 80120343,
          SpeakNpcId = 93301,
          Subtitle = "\"To make up for your disappointment, I've left you this — an all-purpose pot helmet! Worn normally, it protects your head; flip it over, and it's a perfect cooking pot. The attached lamp even works as a flashlight. Truly, the ultimate all-in-one tool.\"",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A79C"
        },
        [80120343] = {
          ContentFR = "« Et puis, joyeux anniversaire. Martin. »",
          DialogueId = 80120343,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A7C6",
          NextOptions = {
            [1] = 801203431,
            [2] = 801203432
          },
          SpeakNpcId = 93301,
          Subtitle = "\"By the way, happy birthday. — Martin.\"",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A7C6"
        },
        [80120344] = {
          ContentFR = "... Je suis sûre qu’il se moquait de moi !",
          DialogueId = 80120344,
          GUID = "C892A7F0",
          NextDialogue = 80120345,
          SpeakNpcId = 93301,
          Subtitle = "...I'm pretty sure he was mocking me!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A7F0"
        },
        [80120345] = {
          ContentFR = "Bref, après ça, j’ai laissé tomber son secret.",
          DialogueId = 80120345,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892A81A",
          NextDialogue = 80120346,
          SpeakNpcId = 93301,
          Subtitle = "Anyway, after that, I gave up caring about his stupid secret.",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A81A"
        },
        [80120346] = {
          ContentFR = "<I>Tiens, en parlant de secret, j’ai une intuition...</>",
          DialogueId = 80120346,
          GUID = "C892A844",
          NextDialogue = 80120347,
          SpeakNpcId = 100001,
          Subtitle = "Speaking of secrets, I've got a hunch...",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A844"
        },
        [80120347] = {
          ContentFR = "Quelle intuition ?",
          DialogueId = 80120347,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A86E",
          NextDialogue = 80120348,
          SpeakNpcId = 93301,
          Subtitle = "What is it?",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A86E"
        },
        [80120348] = {
          ContentFR = "Son secret... il serait pas caché dans ce « casque multifonction » ?",
          DialogueId = 80120348,
          GUID = "C892A898",
          NextDialogue = 80120349,
          SpeakNpcId = 100001,
          Subtitle = "Could his secret be hidden... inside this \"all-purpose helmet\"?",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A898"
        },
        [80120349] = {
          ContentFR = "Il a dit « là où tu ne t’y attendra pas », alors... et si c’était justement là, sous notre nez, que ça se trouvait ?",
          DialogueId = 80120349,
          GUID = "C892A8C2",
          NextDialogue = 80120350,
          SpeakNpcId = 100001,
          Subtitle = "I mean, he did say it was at a place you'd least expect, so... maybe the most obvious place is the place you'd never expect.",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A8C2"
        },
        [80120350] = {
          ContentFR = "Ah... ! En y repensant, j’étais tellement dépitée à l’époque que je n’ai même pas fouillé ce casque ! Si c’est un objet modifié, il pourrait bien cacher quelque chose ! Laisse-moi voir ça de plus près !",
          DialogueId = 80120350,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A8EC",
          NextDialogue = 80120351,
          SpeakNpcId = 93301,
          Subtitle = "Ah...!!! Come to think of it, I was so bummed back then I didn't even check this helmet carefully! You might be right — it's been modified, so it's possible that he had hidden something inside! Let's take it apart now!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A8EC"
        },
        [80120351] = {
          ContentFR = "Vraiment ! Sous la couche d’absorption des chocs, il y a une cavité secrète ! Je savais que tu avais l’étoffe d’{性别:un|une} détective !",
          DialogueId = 80120351,
          GUID = "C892A916",
          IsBlack = 1,
          NextDialogue = 80120352,
          SpeakNpcId = 93301,
          Subtitle = "Aha! A hidden compartment under the padding! I knew you had a detective's knack!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A916"
        },
        [80120352] = {
          ContentFR = "Vieux crétin ! Cette fois, c’est toi qui vas voir !",
          DialogueId = 80120352,
          GUID = "C892A940",
          IsBlack = 1,
          NextDialogue = 80120353,
          SpeakNpcId = 93301,
          Subtitle = "Gotcha, stupid old man! The jig's up!",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A940"
        },
        [80120353] = {
          ContentFR = "Margie manipule habilement le casque marmite, visiblement expérimentée dans le bricolage à partir de déchets, ses doigts agiles démontent rapidement l’objet.",
          DialogueId = 80120353,
          GUID = "C892A96A",
          IsBlack = 1,
          NextDialogue = 80120354,
          Subtitle = "(Margie skillfully manipulates the pot helmet — her experience with repurposing scrap obviously helps a lot. Her fingers move deftly, and soon the pot is fully disassembled.)",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A96A"
        },
        [80120354] = {
          ContentFR = "C’est... ça...",
          DialogueId = 80120354,
          GUID = "C892A994",
          IsBlack = 1,
          NextDialogue = 80120355,
          SpeakNpcId = 93301,
          Subtitle = "Ah, this is...",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A994"
        },
        [80120355] = {
          ContentFR = "Margie ouvre grand les yeux, bouche bée devant la marmite. Tu prends l’objet et remarques une petite inscription gravée sous le fond.",
          DialogueId = 80120355,
          GUID = "C892A9BE",
          IsBlack = 1,
          NextDialogue = 80120356,
          Subtitle = "(Margie stares wide-eyed at the pot, speechless. You take the pot from her and see a small inscription on the bottom—)",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A9BE"
        },
        [80120356] = {
          ContentFR = "« À ma fille Margie l’Idiote : »",
          DialogueId = 80120356,
          GUID = "C892A9E8",
          IsBlack = 1,
          NextDialogue = 80120357,
          Subtitle = "\"Dear Margie, my silly daughter,\"",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A9E8"
        },
        [80120357] = {
          ContentFR = "« Félicitations pour avoir encore perdu dans le jeu \"Chercher le secret de Martin\". Par conséquent, j’ajoute \"idiote\" à ton prénom. »",
          DialogueId = 80120357,
          GUID = "C892AA12",
          IsBlack = 1,
          NextDialogue = 80120358,
          Subtitle = "\"Congratulations on failing yet again in the 'Find Old Martin's Secret' game. As punishment, I shall add the modifier 'Idiot' to your name.\"",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892AA12"
        },
        [80120358] = {
          ContentFR = "« Puisque nous partageons le même nom, j’ai gravé ton nom au fond cette marmite, ça m’évitera la honte et le feu du foyer brûlera ta disgrâce ! »",
          DialogueId = 80120358,
          GUID = "C892AA3C",
          IsBlack = 1,
          Subtitle = "\"Considering we share a last name, I hereby inscribe it on the bottom of this pot instead, which saves me the shame, and allows the stove fire to scorch your disgrace.\"",
          VoiceName = "voice/$Locale$/inv/Maer/003/C892AA3C"
        },
        [80120401] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentFR = "<I>Snif snif</>... Margie la détective vient encore de résoudre une affaire explosive...",
          DialogueId = 80120401,
          GUID = "C892B14A",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204011
          },
          SpeakNpcId = 93301,
          Subtitle = "*sniffles* ...Detective Margie has cracked yet another groundbreaking case...",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B14A"
        },
        [80120402] = {
          ContentFR = "Ce... ce sont des larmes de joie !",
          DialogueId = 80120402,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892B174",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204021
          },
          SpeakNpcId = 93301,
          Subtitle = "Th—These are tears of joy!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B174"
        },
        [80120403] = {
          ContentFR = "Margie boit une grande gorgée d’eau, puis sort délicatement de sa poche quelque chose qu’elle te tend, une touffe de poils d’animal, dont la couleur te semble familière...",
          DialogueId = 80120403,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B19E",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextDialogue = 80120404,
          Subtitle = "(Margie gulps down a full glass of water, then gingerly pulls something from her pocket and presents it to you — it's a clump of fur, somewhat familiar in colour.)",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B19E"
        },
        [80120404] = {
          ContentFR = "J’ai retrouvé Touffu !",
          DialogueId = 80120404,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B1C8",
          NextOptions = {
            [1] = 801204041
          },
          SpeakNpcId = 93301,
          Subtitle = "I found Plumpytail!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B1C8"
        },
        [80120405] = {
          ContentFR = "C’est le gros chat avec qui je vagabondais dans les champs enneigés !",
          DialogueId = 80120405,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B1F2",
          NextDialogue = 80120406,
          SpeakNpcId = 93301,
          Subtitle = "Plumpytail's the little cat I used to roam the snowfields with!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B1F2"
        },
        [80120406] = {
          ContentFR = "Puis je suis venue à Givrelac, mais elle ne voulait pas me suivre, elle est restée dehors. Je lui ai même cousu une peluche qui lui ressemble à s’y méprendre, pour me souvenir d’elle !",
          DialogueId = 80120406,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B21C",
          NextDialogue = 80120407,
          SpeakNpcId = 93301,
          Subtitle = "Then I came to Icelake, but she didn't want to come with me and stayed in the wilderness. I made a plushie that looks just like her to remember her!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B21C"
        },
        [80120407] = {
          ContentFR = "Aujourd’hui, je comptais fouiller les poubelles près des portes de la ville, mais j’ai trouvé cette touffe de poils par hasard, regarde !",
          DialogueId = 80120407,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B246",
          NextDialogue = 80120408,
          SpeakNpcId = 93301,
          Subtitle = "I was just going to check the bins near the city gates today, but instead, I stumbled upon this clump of fur! Look!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B246"
        },
        [80120408] = {
          ContentFR = "Cette couleur grisâtre tachetée de noir, ce toucher à la fois doux et un peu rêche, et le fait qu’elle soit encore un peu humide... c’est forcément Touffu qui est venue me chercher, j’en suis sûre !",
          DialogueId = 80120408,
          GUID = "C892B270",
          NextDialogue = 80120409,
          SpeakNpcId = 93301,
          Subtitle = "The greyish colour with black spots, the soft yet coarse feel, and the fact that it was even a bit damp when I found it... It's definitely Plumpytail! She came back for me!",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B270"
        },
        [80120409] = {
          ContentFR = "Avant, quand on jouait au « suspect à suivre », elle laissait des touffes de poils dans plusieurs directions pour me perdre, c’était son truc fétiche.",
          DialogueId = 80120409,
          GUID = "C892B29A",
          NextDialogue = 80120410,
          SpeakNpcId = 93301,
          Subtitle = "Back in the day, when Plumpytail and I played \"Tailing the Suspect,\" she would leave bits of furball from her grooming in different directions to throw me off. That was one of her signature tricks.",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B29A"
        },
        [80120410] = {
          ContentFR = "À l’époque, j’étais une débutante, je me faisais toujours avoir, je ne savais plus où donner de la tête. Quand j’étais épuisée et essoufflée, elle passait devant moi la tête haute, la queue fièrement dressée, toute hautaine !",
          DialogueId = 80120410,
          FacialId = {
            [1] = "93301:Sad01"
          },
          GUID = "C892B2C4",
          NextDialogue = 80120411,
          SpeakNpcId = 93301,
          Subtitle = "I was such a rookie detective back then, so I always walked straight into Plumpytail's traps. By the time I was worn out from running in circles, Plumpytail would prance around with her head held high, tail swaying like she was king of the world!",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B2C4"
        },
        [80120411] = {
          ContentFR = "Ça me revient... Toute la colère d’être roulée par ce « chat suspect », la frustration de perdre la piste, la peur de me perdre dans la neige... et ce moment d’incertitude en tenant cette touffe humide dans mes mains !",
          DialogueId = 80120411,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892B2EE",
          NextOptions = {
            [1] = 801204111
          },
          SpeakNpcId = 93301,
          Subtitle = "...It's all coming back to me — the irritation of being toyed with by the \"Suspect Cat,\" the frustration of losing the trail, the panic of getting lost in the snowfields, and the bafflement of holding a handful of wet fur!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B2EE"
        },
        [80120412] = {
          ContentFR = "Hmph ! Ça fait des années, je ne suis plus la débutante d’avant ! Et puis Givrelac, c’est mon territoire. Cette fois, je vais attraper ce « chat suspect », quoi qu’il arrive.",
          DialogueId = 80120412,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B318",
          NextDialogue = 80120413,
          SpeakNpcId = 93301,
          Subtitle = "Hmph! Those days are long behind me! I'm no longer the rookie I once was! Plus, Icelake is my turf now, and this time, I'm definitely going to catch the \"Suspect Cat\"!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B318"
        },
        [80120413] = {
          ContentFR = "En plus de deviner sa cachette selon la géographie des ruelles, j’ai même soudoyé les chats errants du quartier avec des petits poissons secs. Toute info sur cette intruse sera généreusement récompensée !",
          DialogueId = 80120413,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B342",
          NextOptions = {
            [1] = 801204131,
            [2] = 801204141
          },
          SpeakNpcId = 93301,
          Subtitle = "I've been mapping out the possible hiding spots based on the alley layouts and even bribed the local strays with fish treats. Anyone who can provide a lead on this outsider cat will be handsomely rewarded!",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B342"
        },
        [80120414] = {
          ContentFR = "Pris sur le fait, un gros matou blanc qui colportait de fausses infos ! Interdiction de poisson sec pour deux semaines !",
          DialogueId = 80120414,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B36C",
          NextDialogue = 80120416,
          SpeakNpcId = 93301,
          Subtitle = "Aha! Caught a white-furred big cat spreading false alarms! As punishment, no fish treats for half a month!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B36C"
        },
        [80120415] = {
          ContentFR = "Hé hé, même en me flattant comme ça, je ne vais pas prendre la grosse tête, hé hé !",
          DialogueId = 80120415,
          FacialId = {
            [1] = "93301:Happy02"
          },
          GUID = "C892B396",
          NextDialogue = 80120416,
          SpeakNpcId = 93301,
          Subtitle = "Hehe, even if you flatter me like that... hehe, I won't let it go to my head, hehe!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B396"
        },
        [80120416] = {
          ContentFR = "Bon, revenons au sujet... Grâce à mes déductions précises, j’ai finalement trouvé Touffu dans une ruelle remplie de cartons, un vrai paradis pour un chat sauvage !",
          DialogueId = 80120416,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B3C0",
          NextDialogue = 80120417,
          SpeakNpcId = 93301,
          Subtitle = "Ahem, as I was saying... my detailed deductions finally led me to a narrow alley full of cardboard boxes — it's like an irresistible paradise for a cat used to living in the wild!",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B3C0"
        },
        [80120417] = {
          ContentFR = "Et effectivement, la suspecte était là, étendue dans un carton au soleil, agitant la queue d’un air tranquille, comme si elle était la reine du quartier !",
          DialogueId = 80120417,
          FacialId = {
            [1] = "93301:Happy01"
          },
          GUID = "C892B3EA",
          NextDialogue = 80120418,
          SpeakNpcId = 93301,
          Subtitle = "And sure enough, there was the suspect, basking in the sun inside a cardboard box, casually flicking her tail at me as if she owned the place!",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B3EA"
        },
        [80120418] = {
          ContentFR = "Après tout ce temps, Touffu est toujours la même, mais elle a changé un peu...",
          DialogueId = 80120418,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B414",
          NextDialogue = 80120419,
          Scripts = "PlayAnimation{_delay{2},ActorId{93301},AnimationId{\"Sit_DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 93301,
          Subtitle = "It's been so long, yet Plumpytail was still the same Plumpytail I knew... No, actually, she seemed a bit different this time.",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B414"
        },
        [80120419] = {
          ContentFR = "Quand on s’est quittées, elle venait de grandir, elle n’aimait pas qu’on la touche, et disparaissait dès qu’elle était contrariée. Cette fois, elle semblait plus mûre, presque un peu âgée.",
          DialogueId = 80120419,
          GUID = "C892B43E",
          NextDialogue = 80120420,
          SpeakNpcId = 93301,
          Subtitle = "When we last parted, Plumpytail had just grown up and didn't like being petted — one wrong move, and she'd vanish in a flash. But today, she seemed more mature, almost like an old cat.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B43E"
        },
        [80120420] = {
          ContentFR = "Est-ce que le dicton « avec l’âge, on devient plus doux » s’applique aussi aux animaux ? Même sans lui offrir ses friandises préférées, elle me laissait la caresser partout : le ventre, les pattes, la queue.",
          DialogueId = 80120420,
          GUID = "C892B468",
          NextDialogue = 80120421,
          SpeakNpcId = 93301,
          Subtitle = "Does \"mellow with age\" also apply to animals? Even without her favourite jerky, she let me pet her all over — belly rubs, paw squeezes, tail strokes and all.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B468"
        },
        [80120421] = {
          ContentFR = "Cette fois, Touffu est même venue avec quelques chatons, qui, eux, restent timides et ne sortent la tête que pour jeter un œil. Mais rien que leur pelage montre qu’elle prend bien soin d’eux !",
          DialogueId = 80120421,
          GUID = "C892B492",
          NextDialogue = 80120422,
          Scripts = "SEQ{PlayAnimation{ActorId{93301},AnimationId{\"Sit_Talk01_Start\"},Duration{1}},PlayAnimation{_delay{2},ActorId{93301},AnimationId{\"Sit_Talk01_End\"},Duration{1}}}",
          SpeakNpcId = 93301,
          Subtitle = "This time, Plumpytail even brought a few kittens along. They're just as timid as Plumpytail used to be, peeking their little heads out from the box. But just from their fur, I could tell Plumpytail has been taking great care of them!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B492"
        },
        [80120422] = {
          ContentFR = "C’est émouvant... ce chat maladroit qui ne capturait même pas un mulot des neiges est maintenant capable de veiller sur ses petits !",
          DialogueId = 80120422,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B4BC",
          NextOptions = {
            [1] = 801204221
          },
          SpeakNpcId = 93301,
          Subtitle = "It's amazing... that clumsy cat who couldn't even catch a snowfield rat is now providing for a whole litter of kittens of her own!",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B4BC"
        },
        [80120423] = {
          ContentFR = "Oui, on a toutes les deux mûri depuis notre rencontre. Hé hé... c’est un peu gênant de le dire...",
          DialogueId = 80120423,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B4E6",
          NextDialogue = 80120424,
          SpeakNpcId = 93301,
          Subtitle = "You're right... we've both grown since we first met. Hehe... it's kinda embarrassing to admit though...",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B4E6"
        },
        [80120424] = {
          ContentFR = "Pour être honnête, quand je suis arrivée à Givrelac, je n’étais pas comme maintenant. Je pleurais souvent, hein, surtout ne te moque pas !",
          DialogueId = 80120424,
          GUID = "C892B510",
          NextDialogue = 80120425,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"93301:p(18000P2)\"}}",
          SpeakNpcId = 93301,
          Subtitle = "Actually, when I first came to Icelake, I was such a crybaby — hey, don't you dare make fun of me!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B510"
        },
        [80120425] = {
          ContentFR = "Plusieurs fois, j’ai voulu quitter Givrelac, faire comme si je n’y étais jamais venue. J’avais envie de retrouver Touffu et de vagabonder avec elle, ça semblait chouette.",
          DialogueId = 80120425,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B53A",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204251
          },
          SpeakNpcId = 93301,
          Subtitle = "I thought about leaving Icelake more than once. I figured I could just pretend I'd never come and wander the world with Plumpytail, which seemed pretty great.",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B53A"
        },
        [80120426] = {
          ContentFR = "Le vieux Martin disait que la cité était un bon endroit, alors j’y croyais aussi. Je m’imaginais la « cité » comme un refuge où des gens avec des torches se serrent les coudes pour s’entraider.",
          DialogueId = 80120426,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B564",
          NextDialogue = 80120427,
          SpeakNpcId = 93301,
          Subtitle = "Old Martin always said the city was a good place, so I believed it too. I imagined a \"city\" as a sanctuary where torch-bearing folks huddle together for warmth and protection.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B564"
        },
        [80120427] = {
          ContentFR = "Mais... pff, qu’est-ce qu’il se passe dans ce refuge ! Les Charons sont discriminés sans raison, les riches ont des fourrures pour plusieurs vies alors que les pauvres des taudis risquent de ne pas survivre à l’hiver...",
          DialogueId = 80120427,
          FacialId = {
            [1] = "93301:Sad01"
          },
          GUID = "C892B58E",
          NextDialogue = 80120428,
          SpeakNpcId = 93301,
          Subtitle = "But... Ugh! The things that go on in this \"sanctuary\" are just absurd. Charons are discriminated against for no reason; rich folks have more furs than they could wear in a lifetime, while the poor in the slums might not even survive the cold winter...",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B58E"
        },
        [80120428] = {
          ContentFR = "Et puis, Touffu me manquait tellement ! Partout il y a du bon et du mauvais, alors pourquoi ne pas rester avec mon chat préféré ?",
          DialogueId = 80120428,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B5B8",
          NextOptions = {
            [1] = 801204281,
            [2] = 801204291
          },
          SpeakNpcId = 93301,
          Subtitle = "And I just missed Plumpytail so much! I figured, every place has its good and bad, so why not just stick with my favourite cat?",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B5B8"
        },
        [80120429] = {
          ContentFR = "Lui ? Il ne pleurerait pas... enfin, peut-être... enfin bref, je suis toujours à Givrelac, non ?",
          DialogueId = 80120429,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892B5E2",
          NextDialogue = 80120431,
          Scripts = "PlayAnimation{_delay{1},ActorId{93301},AnimationId{\"Sit_DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 93301,
          Subtitle = "Huh? He wouldn't... um, maybe... Anyway, I'm still here in Icelake, aren't I?",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B5E2"
        },
        [80120430] = {
          ContentFR = "Avec du recul, j’étais juste une gamine qui voulait fuir ses problèmes.",
          DialogueId = 80120430,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B60C",
          NextDialogue = 80120431,
          SpeakNpcId = 93301,
          Subtitle = "Yeah, now that I think about it, I was just a kid trying to run away from problems.",
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B60C"
        },
        [80120431] = {
          ContentFR = "Une fois, des enfants Solariens m’ont lancé des cailloux, j’ai perdu la tête et couru vers la porte de la ville, criant le nom de Touffu encore et encore.",
          DialogueId = 80120431,
          FacialId = {
            [1] = "93301:Uninterested01"
          },
          GUID = "C892B636",
          NextDialogue = 80120432,
          SpeakNpcId = 93301,
          Subtitle = "I actually did it once. One time, some Sola kids threw rocks at me, and I got so mad that I ran straight for the city gate. I just kept running, calling out for Plumpytail.",
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B636"
        },
        [80120432] = {
          ContentFR = "Et puis... je l’ai vraiment vue. Elle se battait contre un loup des neiges pour une souris au dos argenté, leur proie commune.",
          DialogueId = 80120432,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B660",
          NextDialogue = 80120433,
          SpeakNpcId = 93301,
          Subtitle = "And then... I did run into Plumpytail. She was fighting a snow wolf over a silverback vole.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B660"
        },
        [80120433] = {
          ContentFR = "Je pensais qu’elle devait avoir faim, alors je lui ai lancé un morceau de viande séchée. Elle n’a même pas regardé, ses yeux étaient fixés sur sa proie et son ennemi.",
          DialogueId = 80120433,
          GUID = "C892B68A",
          NextDialogue = 80120434,
          SpeakNpcId = 93301,
          Subtitle = "I figured Plumpytail must've been starving, so I threw her a piece of jerky. But she didn't even look at it. Her eyes were fixed only on her prey and her enemy.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B68A"
        },
        [80120434] = {
          ContentFR = "Elle a gagné le combat, et est venue vers moi, la tête haute, miaulant comme pour se vanter ou peut-être pour me montrer qu’elle était contente de me revoir.",
          DialogueId = 80120434,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B6B4",
          NextDialogue = 80120435,
          SpeakNpcId = 93301,
          Subtitle = "In the end, Plumpytail won. She strutted over to me all proud-like, meowing — either showing off or maybe just happy to see me after so long.",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B6B4"
        },
        [80120435] = {
          ContentFR = "Je lui ai caressé la tête duveteuse et lui ai dit : « Touffu, je viens avec toi. Vivons ensemble dans les champs enneigés. »",
          DialogueId = 80120435,
          FacialId = {
            [1] = "93301:Happy02"
          },
          GUID = "C892B6DE",
          NextDialogue = 80120436,
          SpeakNpcId = 93301,
          Subtitle = "I petted her fluffy head and said, \"Plumpytail, I'll go with you. Let's live together in the snowfields.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B6DE"
        },
        [80120436] = {
          ContentFR = "Mais elle ne m’a pas emmenée chez elle. Elle s’est échappée de mes bras en miaulant vers une direction... c’était celle de Givrelac.",
          DialogueId = 80120436,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B708",
          NextDialogue = 80120437,
          SpeakNpcId = 93301,
          Subtitle = "But Plumpytail didn't take me to her home. She darted out of my arms and kept meowing in one direction — it was the direction of Icelake.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B708"
        },
        [80120437] = {
          ContentFR = "Je crois qu’elle voulait me dire que les champs n’étaient pas ma maison, que ma place était à Givrelac.",
          DialogueId = 80120437,
          GUID = "C892B732",
          NextDialogue = 80120438,
          SpeakNpcId = 93301,
          Subtitle = "I guess she was trying to tell me the snowfields weren't my home, and I belonged to Icelake.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B732"
        },
        [80120438] = {
          ContentFR = "À ce moment, j’ai compris. Même si je lui donnais à manger, Touffu devait continuer à chasser... c’était sa façon de vivre.",
          DialogueId = 80120438,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B75C",
          NextDialogue = 80120439,
          SpeakNpcId = 93301,
          Subtitle = "That's when I realised... Even with me feeding her, Plumpytail would still try her best to hunt, because that was her way of living.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B75C"
        },
        [80120439] = {
          ContentFR = "Moi aussi j’ai ma façon de survivre, mais j’avais peur de la cité, je voulais fuir vers Touffu, pfff, j’étais vraiment une poule mouillée !",
          DialogueId = 80120439,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B786",
          NextOptions = {
            [1] = 801204391,
            [2] = 801204401
          },
          Scripts = "LookAt{_delay{2},LookAtDescription{\"93301:p(18000P2)\"}}",
          SpeakNpcId = 93301,
          Subtitle = "And I had my way of living too, but I was too chicken to face my life in the city, always thinking of running back to Plumpytail — ugh, I was such a coward!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B786"
        },
        [80120440] = {
          ContentFR = "Oui, alors je l’ai écoutée et je suis rentrée. Mais il y a eu un petit problème...",
          DialogueId = 80120440,
          GUID = "C892B7B0",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextDialogue = 80120442,
          SpeakNpcId = 93301,
          Subtitle = "Yeah. So I listened to her advice and went back. But there was a slight mishap...",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B7B0"
        },
        [80120441] = {
          ContentFR = "<I>Snif...</> Arrête de me gronder, même le vieux Martin ne m’a jamais grondée ! En parlant de lui, il s’est inquiété comme jamais ce jour-là, parce que je me suis perdue en rentrant...",
          DialogueId = 80120441,
          FacialId = {
            [1] = "93301:Pain01"
          },
          GUID = "C892B7DA",
          NextDialogue = 80120442,
          SpeakNpcId = 93301,
          Subtitle = "Waaah, I know I messed up... I'm sorry! Not even Old Martin scolded me for that! Speaking of which, the old man was actually worried sick for once, because I ran into a little trouble on the way back...",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B7DA"
        },
        [80120442] = {
          ContentFR = "Je suis partie en courant, sans regarder où j’allais ! J’ai dit au revoir à Touffu, puis j’ai tourné en rond, de plus en plus fatiguée, jusqu’à m’endormir dans la neige...",
          DialogueId = 80120442,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B804",
          NextDialogue = 80120443,
          SpeakNpcId = 93301,
          Subtitle = "I was so mad when I ran out that I didn't even pay attention to remembering the way! So after I said goodbye to Plumpytail, I got lost... And I just kept walking, feeling more and more tired, until I fell asleep in the snow...",
          TalkActionId = {
            [1] = "93301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B804"
        },
        [80120443] = {
          ContentFR = "Je me suis réveillée en sentant des secousses, c’était le vieux crétin qui me portait sur son dos. Il n’est pas grand, mais il a un dos solide, comme quand j’étais petite.",
          DialogueId = 80120443,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B82E",
          NextDialogue = 80120444,
          SpeakNpcId = 93301,
          Subtitle = "I woke up to a bumpy ride — turned out that stupid old man was carrying me on his back. He's not tall, but his back is as sturdy as it was when I was little.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B82E"
        },
        [80120444] = {
          ContentFR = "J’avais chaud partout, parce qu’il m’avait enveloppée dans une longue écharpe, plusieurs fois autour, la bouche aussi couverte, comme font les Solariens.",
          DialogueId = 80120444,
          GUID = "C892B858",
          NextDialogue = 80120445,
          SpeakNpcId = 93301,
          Subtitle = "I felt very warm because he had bundled me up in a long scarf, wrapping me in layer after layer, covering even my mouth, like Solas do.",
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B858"
        },
        [80120445] = {
          ContentFR = "Et voilà comment ma première aventure hors de la ville s’est terminée en catastrophe.",
          DialogueId = 80120445,
          GUID = "C892B882",
          NextDialogue = 80120446,
          SpeakNpcId = 93301,
          Subtitle = "And that's how Margie's first adventure outside Icelake sloppily ended.",
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B882"
        },
        [80120446] = {
          ContentFR = "Depuis, j’apprends à vivre à Givrelac, mais à chaque problème, le vieux me taquine en m’appelant « Petite Touffu, la chasseuse pas douée ».",
          DialogueId = 80120446,
          GUID = "C892B8AC",
          NextDialogue = 80120447,
          SpeakNpcId = 93301,
          Subtitle = "Since then, I've been learning how to make a life for myself in Icelake. But every time I run into trouble, that stupid old man still teases me, calling me \"Can't-catch-anything Plumpytail Junior.\"",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B8AC"
        },
        [80120447] = {
          ContentFR = "Mais il a tort ! Touffu est devenue une chasseuse accomplie, et moi aussi j’ai appris à survivre ici, comme tu l’as dit, on a grandi.",
          DialogueId = 80120447,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B8D6",
          NextOptions = {
            [1] = 801204471
          },
          SpeakNpcId = 93301,
          Subtitle = "But he's wrong! Plumpytail had already become a skilled hunter, and I've learned to survive here too — just like you said, we've both grown.",
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B8D6"
        },
        [80120448] = {
          ContentFR = "Ce n’est pas ma faute, c’est Touffu ! Pourquoi repartir avant le coucher du soleil ? J’ai supplié Touffu de rester mille fois dans ma tête, mais elle est partie avec ses petits...",
          DialogueId = 80120448,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B900",
          NextDialogue = 80120449,
          SpeakNpcId = 93301,
          Subtitle = "Well, it's all Plumpytail's fault! Why did she have to leave so soon!? I must've begged her to stay a thousand times in my head, yet she still left before the sun even set...",
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B900"
        },
        [80120449] = {
          ContentFR = "... Bon, assez d’excuses ! La prochaine fois que Touffu et moi nous verrons, je lui dirai au revoir avec le sourire !",
          DialogueId = 80120449,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B92A",
          SpeakNpcId = 93301,
          Subtitle = "...Alright, no more excuses! Next time Plumpytail and I meet again, I'll see her off with a smile!",
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B92A"
        },
        [80130000] = {
          ContentFR = "B-bonjour... J’espère que je ne te dérange pas...",
          DialogueId = 80130000,
          GUID = "C898D820",
          SpeakNpcId = 93103,
          Subtitle = "H—Hi... I hope I'm not being a bother...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898D820"
        },
        [80130101] = {
          Camera = "126.583923,7.386108,128.715088,0.0,-0.799959,-137.795624,30.0,150.0,false,Manual,2.8",
          ContentFR = "B-bonjour...",
          DialogueId = 80130101,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898E8B2",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130102,
          SpeakNpcId = 93103,
          Subtitle = "H—Hello...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E8B2"
        },
        [80130102] = {
          ContentFR = "Euh... p-permets-moi de me présenter... Je m’appelle Yale, je viens de Rougerive, et... je tiens une petite boutique de jouets qu’on appelle \"Crac’n’Pop\".",
          DialogueId = 80130102,
          GUID = "C898E8DC",
          NextDialogue = 80130103,
          SpeakNpcId = 93103,
          Subtitle = "P—Please allow me to introduce myself. I... I'm Yale, from Scarletriver... I run a little shop called Snap 'n' Spark...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E8DC"
        },
        [80130103] = {
          ContentFR = "Euh... on vend toutes sortes de petits jouets qui explosent, enfin, de façon amusante ! Les enfants de Rougerive aiment beaucoup notre magasin...",
          DialogueId = 80130103,
          FacialId = {
            [1] = "93103:Ahaha02"
          },
          GUID = "C898E906",
          NextDialogue = 80130104,
          SpeakNpcId = 93103,
          Subtitle = "We sell, um... little toys that explode... in a fun way! The kids in Scarletriver love them...",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E906"
        },
        [80130104] = {
          ContentFR = "V-voici notre catalogue. Si quelque chose t’intéresse, tu peux nous écrire, on... on fait la livraison à domicile aussi...",
          DialogueId = 80130104,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898E930",
          NextDialogue = 80130105,
          SpeakNpcId = 93103,
          Subtitle = "Here's a catalogue of our products. If anything catches your eye, just drop us a note. We do home delivery as well...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E930"
        },
        [80130105] = {
          ContentFR = "Eh bien, il commence à se faire tard, et dehors, c’est pas très sûr... Je vais y aller, alors...",
          DialogueId = 80130105,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898E95A",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextOptions = {
            [1] = 801301051,
            [2] = 801301052
          },
          SpeakNpcId = 93103,
          Subtitle = "Er... I should get going. It's not safe to stay out too late...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E95A"
        },
        [80130106] = {
          ContentFR = "Eh bien... je peux rester un peu plus longtemps, si tu veux...",
          DialogueId = 80130106,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898E984",
          NextDialogue = 80130108,
          SpeakNpcId = 93103,
          Subtitle = "O—Okay... I can stay a little longer...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E984"
        },
        [80130107] = {
          ContentFR = "Tu... tu as l’air un peu contrarié. E-est-ce que j’ai été impoli ? P-pardonne-moi, je ne voulais pas...",
          DialogueId = 80130107,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898E9AE",
          NextDialogue = 80130108,
          SpeakNpcId = 93103,
          Subtitle = "You look upset... I—I'm sorry... Did I say something wrong? I didn't mean to...",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E9AE"
        },
        [80130108] = {
          ContentFR = "Oh, allez, laisse-moi faire ! T’avais juré que tu flancherais pas, que tu vendrais nos jouets jusqu’à Givrelac, non ?",
          DialogueId = 80130108,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898E9D8",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130109,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Oh, for crying out loud — move over. Didn't you swear you wouldn't chicken out this time? That you'd pitch our toys to Icelake?",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898E9D8"
        },
        [80130109] = {
          ContentFR = "Et voilà le résultat... C’est encore moi qui vais devoir sauver la situation.",
          DialogueId = 80130109,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EA02",
          NextDialogue = 80130110,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "And now look at you! Ugh, looks like I'll have to bail you out again.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA02"
        },
        [80130110] = {
          ContentFR = "J-je suis désolé... C’est juste que... {性别:il est un Chasseur de Phoxène|elle est une Chasseuse de Phoxène} très célèbre à Givrelac, alors... je suis un peu intimidé... Je savais pas comment commencer...",
          DialogueId = 80130110,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EA2C",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130111,
          SpeakNpcId = 93103,
          Subtitle = "I—I'm sorry... It's just... {性别：he|she}'s a really famous Phoxhunter in Icelake... I got nervous...",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA2C"
        },
        [80130111] = {
          ContentFR = "Arrête de faire ta mauviette. {性别:Il|Elle} va pas te manger. Parle-lui comme tu parles aux gamins qui viennent chez nous.",
          DialogueId = 80130111,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EA56",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801301111,
            [2] = 801301112
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Don't be a chicken. {性别：He|She}'s not gonna eat you alive. Just talk to {性别：him|her} like you talk to the kids at our shop.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA56"
        },
        [80130112] = {
          ContentFR = "...",
          DialogueId = 80130112,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EA80",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130113,
          SpeakNpcId = 93103,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EA80"
        },
        [80130113] = {
          ContentFR = "C’est pas effrayant du tout. Tu voulais juste me détendre, hein ? Merci.",
          DialogueId = 80130113,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898EAAA",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130115,
          SpeakNpcId = 93103,
          Subtitle = "That wasn't scary at all. You were just trying to help me relax, right? Thank you...",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EAAA"
        },
        [80130114] = {
          ContentFR = "Au grand... cœur ? Je... j’avais jamais entendu ce terme. Tu... tu es très {性别:différent|différente} de ce que j’imaginais : {性别:grand et bruyant|grande et bruyante} comme une bombe.",
          DialogueId = 80130114,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898EAD4",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130115,
          SpeakNpcId = 93103,
          Subtitle = "H...heartwarming type...? I've never heard of that type before, but you're definitely not what I pictured — you know, huge, louder than a bomb...",
          TalkActionId = {
            [1] = "93103:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EAD4"
        },
        [80130115] = {
          ContentFR = "Euh, alors, laisse-moi te présenter mon ami Oliver. Il vit dans cette bombe, un alchimiste l’a enfermée dedans.",
          DialogueId = 80130115,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EAFE",
          NextDialogue = 80130116,
          SpeakNpcId = 93103,
          Subtitle = "Anyway, let me introduce my friend. This is Oliver. He, um, lives in this bomb. An alchemist sealed him inside...",
          TalkActionId = {
            [1] = "93103:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EAFE"
        },
        [80130116] = {
          ContentFR = "En fait, Crac’n’Pop c’est notre boutique à tous les deux. Moi, je m’occupe des clients, et lui, il invente les nouveaux jouets.",
          DialogueId = 80130116,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898EB28",
          NextDialogue = 80130117,
          SpeakNpcId = 93103,
          Subtitle = "We run Snap 'n' Spark together: I serve customers, and he comes up with new products.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EB28"
        },
        [80130117] = {
          ContentFR = "Franchement, Yale se bloque souvent en parlant, alors je dois souvent prendre le relais, comme aujourd’hui.",
          DialogueId = 80130117,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EB52",
          NextDialogue = 80130118,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Let's be real — Yale freezes halfway through his pitch more often than not, so I end up handling the talking too, like today.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EB52"
        },
        [80130118] = {
          ContentFR = "Yale a déjà parlé des jouets explosifs qu’on vend. Le mois dernier, nos trois meilleures ventes étaient : le Boom-Zeppelin, la Pyro-Fusée, et la Toupie Boum-Boum.",
          DialogueId = 80130118,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898EB7C",
          NextOptions = {
            [1] = 801301181,
            [2] = 801301182
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "He already mentioned we sell explosive little toys. Last month's top three sellers were: Boom-Blimp, Whizpop Firework, and Kaboom-Spinner.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EB7C"
        },
        [80130119] = {
          ContentFR = "Calme-toi, ce n’était que l’échauffement. Les vraies bombes arrivent maintenant !",
          DialogueId = 80130119,
          GUID = "C898EBA6",
          NextDialogue = 80130121,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Tsk, hear me out first — I haven't even gotten to the real boom yet!",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EBA6"
        },
        [80130120] = {
          ContentFR = "Oh... tu es {性别:intéressé|intéressée} ? Ce n’était que l’intro. Ce qu’on veut vraiment te montrer, c’est ça...",
          DialogueId = 80130120,
          GUID = "C898EBD0",
          NextDialogue = 80130121,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Heh... so you're interested, huh? Well, those were just the warm-up. What we really want to show you is this—",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EBD0"
        },
        [80130121] = {
          ContentFR = "Ça ressemble à un simple réveil, hein ? Mais en réalité, c’est une bombe ultra-puissante, capable d’anéantir tout ce qui te casse les pieds, la Brise-Étoiles.",
          DialogueId = 80130121,
          GUID = "C898EBFA",
          NextDialogue = 80130122,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Looks like an ordinary alarm clock, right? But just one of these — and boom, all your troubles go up in smoke. Introducing: the Starshatterer.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EBFA"
        },
        [80130122] = {
          ContentFR = "J’ai entendu dire que tu es {性别:un Chasseur de Phoxène prometteur|une Chasseuse de Phoxène prometteuse} à Rougerive. Tu pourrais avoir besoin de ce genre de puissance.",
          DialogueId = 80130122,
          GUID = "C898EC24",
          NextDialogue = 80130123,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Word about you's even made it to Scarletriver. Bet an awesome Phoxhunter like you could use a little extra firepower.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC24"
        },
        [80130123] = {
          ContentFR = "Si le nom est dur à retenir, tu peux juste les appeler P’tits Boum, c’est comme ça que je les appelle. Ça aide à tromper les soldats de l’Empire, ils pensent que c’est juste des jouets d’enfants.",
          DialogueId = 80130123,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EC4E",
          NextDialogue = 80130124,
          SpeakNpcId = 93103,
          Subtitle = "If the name's too hard to remember, you can just call them Tot Poppers. That's what I call them... it helps throw off Empire soldiers... makes them think it's just some kid's toy, so they drop their guard.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC4E"
        },
        [80130124] = {
          ContentFR = "Et les petits dessins dessus, c’est moi qui les fais. Ça rend les bombes un peu moins effrayantes.",
          DialogueId = 80130124,
          GUID = "C898EC78",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130125,
          SpeakNpcId = 93103,
          Subtitle = "And the little drawings on the casings — they're also from me... This way the bombs look a bit less scary...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC78"
        },
        [80130125] = {
          ContentFR = "Pff, je te l’ai déjà dit mille fois, les acheteurs veulent du BOUM, pas des dessins mignons.",
          DialogueId = 80130125,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ECA2",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130126,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Ugh. How many times do I have to say it? People who buy bombs just want a good BOOM, not some cutesy nonsense.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECA2"
        },
        [80130126] = {
          ContentFR = "M-mais je pense que ça rend nos produits uniques. Et quand je dessinais, c’est toi qui me donnais plein de conseils pour les rendre encore plus chouettes !",
          DialogueId = 80130126,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898ECCC",
          NextDialogue = 80130127,
          SpeakNpcId = 93103,
          Subtitle = "But I think the drawings make our products stand out. And when I was sketching them, you were the one shouting all those tips about how to make them even cuter...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECCC"
        },
        [80130127] = {
          ContentFR = "Ben ouais, tu crois quoi ? Si ton truc ressemble à un gribouillis de bébé, tu penses qu’on va en vendre ? Évidemment que j’ai dû intervenir.",
          DialogueId = 80130127,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ECF6",
          NextDialogue = 80130128,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "I... I only did that so you wouldn't botch it, all right? If the logo's ugly, no one's gonna buy them — duh!",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECF6"
        },
        [80130128] = {
          ContentFR = "Bon, voilà, le topo est fait. Si t’es {性别:tenté|tentée}, t’as qu’à nous écrire. Tu dis que tu veux une \"Brise-Étoiles\", et c’est tout.",
          DialogueId = 80130128,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ED20",
          NextDialogue = 80130129,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Ahem. Anyway — that's our big sales pitch. If you'd like to place an order, just send us a note.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED20"
        },
        [80130129] = {
          ContentFR = "Mais écris bien \"P’tit Boum\", sinon on va se faire griller.",
          DialogueId = 80130129,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ED4A",
          NextDialogue = 80130130,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "But make sure you write Tot Poppers on your order, not Starshatterers. Otherwise... we'll both be in hot water.",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED4A"
        },
        [80130130] = {
          ContentFR = "L’adresse de la boutique est sur le catalogue. On attend ta commande...",
          DialogueId = 80130130,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898ED74",
          NextDialogue = 80130131,
          SpeakNpcId = 93103,
          Subtitle = "Our shop address is on the catalogue. We'll be waiting for your order...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED74"
        },
        [80130131] = {
          ContentFR = "Yale et Oliver, ce duo un peu étrange de Rougerive, ne passent pas inaperçus. Si tu en as l’occasion, essaie leurs jouets, la Toupie Boum-Boum et la Pyro-Fusée promettent du spectacle !",
          DialogueId = 80130131,
          GUID = "C898ED9E",
          Subtitle = "Yale and Oliver — the unforgettable duo from Scarletriver. If you ever have the chance, why not pick up a few of their creations? Those Kaboom Spinners and Whizpop Fireworks sound like an absolute blast...",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED9E"
        },
        [80130201] = {
          Camera = "126.583923,7.386108,128.715088,0.0,-0.799959,-137.795624,30.0,150.0,false,Manual,2.8",
          ContentFR = "B-Bonjour…",
          DialogueId = 80130201,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F91A",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130202,
          SpeakNpcId = 93103,
          Subtitle = "Hello...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F91A"
        },
        [80130202] = {
          ContentFR = "Tu te souviens de moi ? Je suis Yale, le vendeur de jouets de chez Crac’n’Pop.",
          DialogueId = 80130202,
          FacialId = {
            [1] = "93103:Ahaha02"
          },
          GUID = "C898F944",
          NextOptions = {
            [1] = 801302021,
            [2] = 801302022
          },
          SpeakNpcId = 93103,
          Subtitle = "Do you remember me? I'm Yale, from Snap 'n' Spark...",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F944"
        },
        [80130203] = {
          ContentFR = "O-Oh... C’est vrai... Mais à l’époque, on ne se connaissait pas encore. Maintenant, ça va mieux.",
          DialogueId = 80130203,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F96E",
          NextDialogue = 80130205,
          SpeakNpcId = 93103,
          Subtitle = "Th—That was because we barely knew each other then. It's better now.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F96E"
        },
        [80130204] = {
          ContentFR = "Mmh... C’est vrai qu’il a toujours été bien plus à l’aise pour parler que moi...",
          DialogueId = 80130204,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F998",
          NextDialogue = 80130205,
          SpeakNpcId = 93103,
          Subtitle = "Mm... He's always been much better at talking than I am.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F998"
        },
        [80130205] = {
          ContentFR = "Aujourd’hui, je suis venu tout seul.",
          DialogueId = 80130205,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898F9C2",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130206,
          SpeakNpcId = 93103,
          Subtitle = "I came by myself today, though.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F9C2"
        },
        [80130206] = {
          ContentFR = "Mais ne t’en fais pas, on ne s’est pas disputés ! En vrai, on s’entend très bien. C’est justement parce qu’on s’entend bien... que parfois, y’a des choses que j’ose pas lui dire.",
          DialogueId = 80130206,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898F9EC",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130207,
          SpeakNpcId = 93103,
          Subtitle = "It's not that we had a fight or anything — Oliver and I get along just fine. Which... might be exactly why there are things I can't quite say to him.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F9EC"
        },
        [80130207] = {
          ContentFR = "Alors voilà, je me suis dit que peut-être... je pourrais t’en parler, à toi. Je m’attends pas vraiment à des conseils. J-juste... m’écouter. T’as l’air d’être {性别:doué|douée} pour ça.",
          DialogueId = 80130207,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FA16",
          NextDialogue = 80130208,
          SpeakNpcId = 93103,
          Subtitle = "So... I thought maybe... I could tell you instead. N—No pressure — I'm not here asking for advice. I... just need someone to listen. And... you seemed like a good listener.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA16"
        },
        [80130208] = {
          ContentFR = "En fait... Crac’n’Pop, à la base, c’était pas ma boutique. Ni celle d’Oliver. C’était celle d’un vieux monsieur très très grincheux.",
          DialogueId = 80130208,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898FA40",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130209,
          SpeakNpcId = 93103,
          Subtitle = "I never told you this, but Snap 'n' Spark wasn't ours to begin with. It belonged to a very, very grumpy old man.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA40"
        },
        [80130209] = {
          ContentFR = "Il criait tout le temps, me disait de faire ci, de pas faire ça... Et moi, j’étais nul, j’arrivais jamais à bien faire les choses. Mais à force, à force de me faire engueuler, j’ai fini par comprendre deux-trois trucs.",
          DialogueId = 80130209,
          FacialId = {
            [1] = "93103:Unhappy01"
          },
          GUID = "C898FA6A",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130210,
          SpeakNpcId = 93103,
          Subtitle = "He yelled a lot... always bossing me around. I messed up a lot of things at first... But after a while, even through all the shouting... I started to pick up how to run the place.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA6A"
        },
        [80130210] = {
          ContentFR = "Et puis, un jour, sans prévenir, il m’a dit qu’il partait très loin. Et il m’a laissé la boutique.",
          DialogueId = 80130210,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FA94",
          NextDialogue = 80130211,
          SpeakNpcId = 93103,
          Subtitle = "Then one day he simply announced he was off somewhere far away — and left the place to me.",
          TalkActionId = {
            [1] = "93103:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA94"
        },
        [80130211] = {
          ContentFR = "Du coup, je me suis retrouvé tout seul. Sans lui pour m’apprendre à faire de nouveaux jouets, j’ai dû me débrouiller comme j’ai pu, en vendant les vieux stocks qu’il avait laissés.",
          DialogueId = 80130211,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FABE",
          NextOptions = {
            [1] = 801302111,
            [2] = 801302112
          },
          SpeakNpcId = 93103,
          Subtitle = "After that, it was just me. Without him there... I didn't really know how to make new toys anymore. So I just kept selling whatever stock he'd left behind...",
          TalkActionId = {
            [1] = "93103:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FABE"
        },
        [80130212] = {
          ContentFR = "O-ouais. J’ai trouvé ça bizarre aussi. Il a vraiment disparu du jour au lendemain.",
          DialogueId = 80130212,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FAE8",
          NextDialogue = 80130214,
          SpeakNpcId = 93103,
          Subtitle = "I... I didn't understand it either. It all happened so suddenly.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FAE8"
        },
        [80130213] = {
          ContentFR = "Merci... C’est vrai qu’à l’époque, je me suis accroché, j’ai appris plein de choses par moi-même.",
          DialogueId = 80130213,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FB12",
          NextDialogue = 80130214,
          SpeakNpcId = 93103,
          Subtitle = "Thank you... I really did try my best to learn everything I could back then.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB12"
        },
        [80130214] = {
          ContentFR = "Puis, après quelques mois, des adultes que je n’avais jamais vus sont venus avec leurs enfants. Petit à petit, la boutique a recommencé à marcher.",
          DialogueId = 80130214,
          FacialId = {
            [1] = "93103:Happy01"
          },
          GUID = "C898FB3C",
          NextDialogue = 80130215,
          SpeakNpcId = 93103,
          Subtitle = "Anyway... a few months passed. More parents came in with their kids, business was finally picking up...",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB3C"
        },
        [80130215] = {
          ContentFR = "Et puis un jour, y’a un garçon à peu près de mon âge qui est entré. Je croyais que c’était juste un client, alors j’ai voulu lui proposer des jouets...",
          DialogueId = 80130215,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898FB66",
          NextDialogue = 80130216,
          SpeakNpcId = 93103,
          Subtitle = "Then one day a boy about my age showed up. I thought he was just another customer, so I started recommending toys.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB66"
        },
        [80130216] = {
          ContentFR = "... Mais lui, il m’a regardé froidement et il m’a dit que Crac’n’Pop n’était même pas à ce vieux monsieur, que le magasin lui avait été volé.",
          DialogueId = 80130216,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FB90",
          NextDialogue = 80130217,
          SpeakNpcId = 93103,
          Subtitle = "But he just looked at me and said, in this cold voice, that Snap 'n' Spark wasn't the old man's shop at all — that he had stolen it from him.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB90"
        },
        [80130217] = {
          ContentFR = "J’ai pas voulu le croire. Mais il est allé direct à l’établi, il a pris les outils comme s’il les utilisait tous les jours...",
          DialogueId = 80130217,
          GUID = "C898FBBA",
          NextDialogue = 80130218,
          SpeakNpcId = 93103,
          Subtitle = "I didn't believe him at first. But then he marched straight to the workbench, picked up the tools like he'd been using them forever...",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FBBA"
        },
        [80130218] = {
          ContentFR = "J’ai voulu l’avertir, lui dire que c’était dangereux, mais il a fabriqué une bombe avant même que je termine ma phrase. Plus vite que le vieux grincheux lui-même.",
          DialogueId = 80130218,
          GUID = "C898FBE4",
          NextDialogue = 80130219,
          SpeakNpcId = 93103,
          Subtitle = "I tried to warn him that the materials were dangerous and not to mess with them — but before I could even finish, he had already put together a bomb. Faster than the old man ever could.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FBE4"
        },
        [80130219] = {
          ContentFR = "Et après, il m’a dit, toujours avec cette voix dure, que le vieux était un voleur... et que moi aussi, j’étais un voleur.",
          DialogueId = 80130219,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FC0E",
          NextDialogue = 80130220,
          SpeakNpcId = 93103,
          Subtitle = "He looked at me — and, in this really harsh, accusing voice — said the old man was a thief... and that I was one too.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC0E"
        },
        [80130220] = {
          ContentFR = "J’ai pas eu envie d’y croire, mais... vu la façon dont il connaissait chaque recoin de la boutique... il avait vraiment l’air d’en être le vrai propriétaire.",
          DialogueId = 80130220,
          GUID = "C898FC38",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130221,
          SpeakNpcId = 93103,
          Subtitle = "I didn't want to believe him. But the way he handled everything... it felt like... he really belonged there. Like he was the real owner all along.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC38"
        },
        [80130221] = {
          ContentFR = "Donc... donc maintenant...",
          DialogueId = 80130221,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898FC62",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801302211,
            [2] = 801302212
          },
          SpeakNpcId = 93103,
          Subtitle = "So... now I...",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC62"
        },
        [80130222] = {
          ContentFR = "Oui. Je veux comprendre si ce qu’il dit est vrai. Et si c’est le cas... peut-être que je devrais lui rendre Crac’n’Pop.",
          DialogueId = 80130222,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FC8C",
          NextDialogue = 80130224,
          SpeakNpcId = 93103,
          Subtitle = "Yes. If what he said is true... maybe I should give Snap 'n' Spark back.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC8C"
        },
        [80130223] = {
          ContentFR = "Si c’est vraiment à lui... alors je pense que je dois le faire.",
          DialogueId = 80130223,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FCB6",
          NextDialogue = 80130224,
          SpeakNpcId = 93103,
          Subtitle = "If he really was the owner... then I think I should.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FCB6"
        },
        [80130224] = {
          ContentFR = "Mais j’ai peur aussi... Si c’est vraiment lui le vrai propriétaire... je fais quoi, moi ?",
          DialogueId = 80130224,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898FCE0",
          NextDialogue = 80130225,
          SpeakNpcId = 93103,
          Subtitle = "The truth is, I'm scared. B—but... if he really is the true owner of Snap 'n' Spark... what am I supposed to do?",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FCE0"
        },
        [80130225] = {
          ContentFR = "J’ai tellement appris ici... J’ai enfin réussi à parler aux enfants, à leur proposer des jouets, à les faire rire. Il pourrait faire tout ça, lui ?",
          DialogueId = 80130225,
          GUID = "C898FD0A",
          NextDialogue = 80130226,
          SpeakNpcId = 93103,
          Subtitle = "I've grown so attached to the place... I worked really hard — learning how to greet customers, recommend toys, get better at talking to other kids... Could he do all that too?",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD0A"
        },
        [80130226] = {
          ContentFR = "Et puis... comment je pourrais le dédommager ? Je sais même pas pourquoi il avait quitté la boutique à l’origine... mais j’ai envie de réparer ça, d’une manière ou d’une autre.",
          DialogueId = 80130226,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FD34",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130227,
          SpeakNpcId = 93103,
          Subtitle = "And if it was his shop all along... how could I ever make it up to him? I don't know why he left in the first place, but... it just feels wrong.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD34"
        },
        [80130227] = {
          ContentFR = "Revenir et découvrir que sa propre boutique est tenue par un inconnu... ça doit faire un sacré choc.",
          DialogueId = 80130227,
          GUID = "C898FD5E",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801302271
          },
          SpeakNpcId = 93103,
          Subtitle = "Imagine losing your own shop, then coming back to find a stranger behind the counter... I can't even picture how awful that must feel...",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD5E"
        },
        [80130229] = {
          ContentFR = "Je le connais, il me hurlerait dessus. Il me dirait que je suis idiot, que je suis le gérant maintenant, et que je dois pas tout laisser tomber comme ça.",
          DialogueId = 80130229,
          FacialId = {
            [1] = "93103:Confident02"
          },
          GUID = "C898FDB2",
          NextDialogue = 80130230,
          SpeakNpcId = 93103,
          Subtitle = "I know exactly what he'd say: yell at me, call me an idiot, insist I'm the rightful owner now — tell me to focus on running it better instead of handing it over.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FDB2"
        },
        [80130230] = {
          ContentFR = "Il voudrait m’en empêcher, j’en suis sûr... Il est un peu brusque, mais au fond, c’est quelqu’un de bien.",
          DialogueId = 80130230,
          FacialId = {
            [1] = "93103:Syouganai01"
          },
          GUID = "C898FDDC",
          NextDialogue = 80130231,
          SpeakNpcId = 93103,
          Subtitle = "He'd definitely try to stop me... But I know — underneath it all, he's actually really kind.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FDDC"
        },
        [80130231] = {
          ContentFR = "Et ce garçon-là aussi avait l’air d’être quelqu’un de bien. Je trouve que les gens bien méritent un peu de justice, eux aussi.",
          DialogueId = 80130231,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FE06",
          NextDialogue = 80130232,
          SpeakNpcId = 93103,
          Subtitle = "But... that boy was a good person too. And I don't think good people should always get the short end of the stick. Someone ought to do right by him as well.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE06"
        },
        [80130232] = {
          ContentFR = "Merci pour le thé. Je crois que maintenant, je sais ce que je dois faire... Merci beaucoup. Je retourne à Rougerive.",
          DialogueId = 80130232,
          FacialId = {
            [1] = "93103:Happy02"
          },
          GUID = "C898FE30",
          NextDialogue = 80130233,
          SpeakNpcId = 93103,
          Subtitle = "Thanks for the tea. I think I know what I need to do now. Really — thank you. I'll head back to Scarletriver.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE30"
        },
        [80130233] = {
          ContentFR = "Ah ! Et si tu veux encore commander des P’tits Boum, tu peux toujours nous écrire. La boutique reste ouverte, quoi qu’il arrive.",
          DialogueId = 80130233,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FE5A",
          NextDialogue = 80130234,
          SpeakNpcId = 93103,
          Subtitle = "Oh! And if you still want to order something from Snap 'n' Spark, just send a letter. The shop's staying open either way.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE5A"
        },
        [80130234] = {
          ContentFR = "Yale s’éloigne en courant, visiblement décidé à rendre la boutique à son véritable propriétaire.",
          DialogueId = 80130234,
          GUID = "C898FE84",
          IsBlack = 1,
          Subtitle = "Yale hurries off — clearly, he's made up his mind to return Snap 'n' Spark to its rightful owner.",
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE84"
        },
        [80130301] = {
          Camera = "126.583923,7.386108,128.715088,0.0,-0.799959,-137.795624,30.0,150.0,false,Manual,2.8",
          ContentFR = "Yo.",
          DialogueId = 80130301,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990982",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130302,
          SpeakNpcId = 93103,
          Subtitle = "Yo.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990982"
        },
        [80130302] = {
          ContentFR = "T’as une minute ? On peut parler un peu ?",
          DialogueId = 80130302,
          GUID = "C89909AC",
          NextOptions = {
            [1] = 801303021,
            [2] = 801303022
          },
          SpeakNpcId = 93103,
          Subtitle = "Got a minute?",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89909AC"
        },
        [80130303] = {
          ContentFR = "Pff, je suis pas ce crétin.",
          DialogueId = 80130303,
          GUID = "C89909D6",
          NextDialogue = 80130305,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_YeerWenhao",
          Subtitle = "Tch. I'm not that idiot.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89909D6"
        },
        [80130304] = {
          ContentFR = "Bien sûr que non, j’en ai marre de jouer au « salut, moi c’est la bombe qui parle ».",
          DialogueId = 80130304,
          GUID = "C8990A00",
          NextDialogue = 80130305,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_YeerWenhao",
          Subtitle = "Duh. I'm done playing \"say hello to my talking bomb.\"",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A00"
        },
        [80130305] = {
          ContentFR = "Moi c’est Oliver, Oliver Kuzka. Pas une créature enfermée dans une bombe, hein.",
          DialogueId = 80130305,
          GUID = "C8990A2A",
          NextDialogue = 80130306,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Name's Oliver. Oliver Kuzka. Not some fantastic creature holed up inside a bomb.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A2A"
        },
        [80130306] = {
          ContentFR = "Tu connais sûrement pas ce nom, mais retiens-le. Si un jour tu passes par Dismania, à quinze bornes au nord de la ville, y’a une forteresse en ruine. C’est moi qui l’ai fait sauter.",
          DialogueId = 80130306,
          GUID = "C8990A54",
          NextDialogue = 80130307,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "You probably haven't heard the name. Doesn't matter. Just remember it. If you ever swing by Dismania, head fifteen kilometres out from the north gate. You'll find a ruined fortress. My signature work.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A54"
        },
        [80130307] = {
          ContentFR = "Pourquoi je suis là ? Ça dépend de toi, dis-moi ce que Yale t’a raconté la dernière fois.",
          DialogueId = 80130307,
          GUID = "C8990A7E",
          NextOptions = {
            [1] = 801303071,
            [2] = 801303072
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "As for why I'm here... That depends. Tell me — what did Yale say to you last time he was here?",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A7E"
        },
        [80130308] = {
          ContentFR = "T’es plus {性别:dur|dure} que t’en as l’air, intéressant. T’aimes qu’on te parle franchement, hein ? On se ressemble.",
          DialogueId = 80130308,
          GUID = "C8990AA8",
          NextDialogue = 80130310,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Hah. Tougher than you look — I like that. You only play along when asked nicely, huh? Guess we're the same type.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990AA8"
        },
        [80130309] = {
          ContentFR = "Ça marche, j’aime les gens qui vont droit au but.",
          DialogueId = 80130309,
          GUID = "C8990AD2",
          NextDialogue = 80130310,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Fair enough. I like straight talk.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990AD2"
        },
        [80130310] = {
          ContentFR = "Alors je vais te raconter toute l’histoire, depuis le début.",
          DialogueId = 80130310,
          GUID = "C8990AFC",
          NextDialogue = 80130311,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "The truth, then. But fair warning — it's a long story.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990AFC"
        },
        [80130311] = {
          ContentFR = "Cette carcasse, c’est la mienne à la base. Oliver Kuzka, génie de la bombe.",
          DialogueId = 80130311,
          GUID = "C8990B26",
          NextDialogue = 80130312,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Like I said — I'm Oliver Kuzka, the real owner of this body. And the best damn bomb maker you'll ever meet.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990B26"
        },
        [80130312] = {
          ContentFR = "À l’époque, j’étais qu’un gamin, persuadé de pouvoir faire exploser tout l’Empire avec mes jouets. J’ai jamais envisagé qu’on me capture... ou alors je voulais pas y penser.",
          DialogueId = 80130312,
          GUID = "C8990B50",
          NextDialogue = 80130313,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Back then, I was barely more than a kid myself. Thought I could blow the whole Empire sky-high with my little toys. Never even stopped to think what'd happen if I got caught... or maybe I just figured it wouldn't happen.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990B50"
        },
        [80130313] = {
          ContentFR = "Quand la Légion m’a chopé, j’avais aucune idée de ce qui m’attendait.",
          DialogueId = 80130313,
          GUID = "C8990B7A",
          NextDialogue = 80130314,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "So when the Legion finally bagged me, I had no clue what was coming.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990B7A"
        },
        [80130314] = {
          ContentFR = "Ils m’ont emmené dans un labo des Spathatoi, devant un vieux bonhomme qui s’appelait Jones. Gentil en apparence.",
          DialogueId = 80130314,
          GUID = "C8990BA4",
          NextDialogue = 80130315,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "They hauled me off to some Spathatoi lab and sat me in front of this kindly looking old man called Jones.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990BA4"
        },
        [80130315] = {
          ContentFR = "Il me parlait calmement, me racontait que la criminalité, c’était un problème mental et que des médicaments pouvaient soigner ça. Des conneries.",
          DialogueId = 80130315,
          GUID = "C8990BCE",
          NextDialogue = 80130316,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Spoke real gentle, that one — kept saying crime was just \"a mental hiccup\" curable with right medication. Rubbish.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990BCE"
        },
        [80130316] = {
          ContentFR = "Ils me donnaient à manger correctement, mais ils m’obligeaient à prendre leurs pilules et à faire des examens. Les médicaments n’étaient pas amers, mais après chaque dose, j’avais l’impression que ma tête ralentissait... petit à petit, j’oubliais des trucs.",
          DialogueId = 80130316,
          GUID = "C8990BF8",
          NextDialogue = 80130317,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "They didn't starve me, not really. Fed me fine, even. But they did force drugs down my throat and ran endless \"check-ups.\" The stuff didn't taste bad, but after every dose, my thoughts would slow to a crawl... and little by little, my memories started slipping away.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990BF8"
        },
        [80130317] = {
          ContentFR = "Au début, je pouvais encore l’insulter ce vieux, mais avec le temps, j’oubliais même les gros mots.",
          DialogueId = 80130317,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8990C22",
          NextDialogue = 80130318,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "At first, I still had enough fire left to cuss that shady codger out — but the more meds I swallowed, the harder it was to remember the curse words.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990C22"
        },
        [80130318] = {
          ContentFR = "Quelqu’un a dit un jour : celui qui ne jure jamais a perdu sa voix.",
          DialogueId = 80130318,
          GUID = "C8990C4C",
          NextDialogue = 80130319,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Someone once said: a man who never swears is a man who's lost his voice.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990C4C"
        },
        [80130319] = {
          ContentFR = "C’était que le début. J’ai commencé à oublier comment marcher, bouger les mains, même respirer.",
          DialogueId = 80130319,
          GUID = "C8990C76",
          NextDialogue = 80130320,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "And that was only the beginning. Slowly, I forgot how to walk straight, how to grip things — even how to breathe.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990C76"
        },
        [80130320] = {
          ContentFR = "Je savais que leurs médicaments étaient foireux, mais je pouvais pas me souvenir de comment les recracher, alors je laissais mes souvenirs se dissoudre... j’aurais préféré exploser en mille morceaux.",
          DialogueId = 80130320,
          GUID = "C8990CA0",
          NextDialogue = 80130321,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "I knew there was something wrong with those drugs. But every time they poured something down my throat, I couldn't even remember how to spit it out. All I could do was sit there and watch my memories dissolve. I'd have preferred being blown to bits.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990CA0"
        },
        [80130321] = {
          ContentFR = "À la fin, j’étais qu’un spectateur, à regarder dans le miroir ce corps d’Oliver Kuzka, sans savoir qui j’étais.",
          DialogueId = 80130321,
          GUID = "C8990CCA",
          NextDialogue = 80130322,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "In the end, all that was left of me was a shadow — watching some puppet called \"Oliver Kuzka\" move in the mirror, without a clue who the hell he was anymore.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990CCA"
        },
        [80130322] = {
          ContentFR = "Puis un jour, Jones est rentré et a dit à ce corps : « Tu t’appelles Yale. »",
          DialogueId = 80130322,
          GUID = "C8990CF4",
          NextDialogue = 80130323,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Until one day, that old bastard walked in, stared at my body, and said: \"Your name is Yale.\"",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990CF4"
        },
        [80130323] = {
          ContentFR = "Alors c’est lui Yale... et moi, je suis qui, du coup ?",
          DialogueId = 80130323,
          GUID = "C8990D1E",
          NextOptions = {
            [1] = 801303231,
            [2] = 801303232
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "So he's Yale... then who the hell am I?",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D1E"
        },
        [80130324] = {
          ContentFR = "Normal, j’ai mis du temps à piger aussi. Jones... a créé une nouvelle personnalité.",
          DialogueId = 80130324,
          GUID = "C8990D48",
          NextDialogue = 80130326,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Figures. Took me a while, too. Jones... he created a new alter ego inside my body.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D48"
        },
        [80130325] = {
          ContentFR = "Exact. Il a cultivé une nouvelle personnalité pour remplacer Oliver Kuzka, le criminel Charon.",
          DialogueId = 80130325,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990D72",
          NextDialogue = 80130326,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Too right. He created a new alter ego inside my body — meant to overwrite the Charon criminal named Oliver Kuzka.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D72"
        },
        [80130326] = {
          ContentFR = "Mais la venue de Yale, au fond, c’était une bonne chose. Avant lui, j’avais plus le contrôle du corps. Impossible de bouger.",
          DialogueId = 80130326,
          GUID = "C8990D9C",
          NextDialogue = 80130327,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "But I'll give it to him — without Yale, I'd have lost control of my body forever. No matter how hard I fought, I couldn't move a finger.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D9C"
        },
        [80130327] = {
          ContentFR = "Cependant, mes pensées pouvaient passer à Yale. Chaque fois que je pensais « t’es qu’une copie », il sursautait comme une caille effarouchée.",
          DialogueId = 80130327,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8990DC6",
          NextDialogue = 80130328,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "But my thoughts could get through to him. Every time I so much as thought \"You're a knock-off,\" he'd flinch like a startled quail — eyes darting, shoulders hunched.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990DC6"
        },
        [80130328] = {
          ContentFR = "Tu peux imaginer à quel point je le détestais. Je passais mes journées à le maudire avec ce qui me restait d’insultes.",
          DialogueId = 80130328,
          GUID = "C8990DF0",
          NextDialogue = 80130329,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "You can imagine how much I hated him back then. I spent every waking second hurling every insult I could still remember at him.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990DF0"
        },
        [80130329] = {
          ContentFR = "Pour lui, je devais être juste une voix folle dans sa tête.",
          DialogueId = 80130329,
          GUID = "C8990E1A",
          NextDialogue = 80130330,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "To him, I must have been just a crazy voice in his head.",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E1A"
        },
        [80130330] = {
          ContentFR = "Il a essayé de me chasser, mais comment j’aurais pu perdre ? Ce corps est à moi.",
          DialogueId = 80130330,
          GUID = "C8990E44",
          NextDialogue = 80130331,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "He tried to shut me out, of course. But how could he? That body was mine.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E44"
        },
        [80130331] = {
          ContentFR = "Ce fichu Jones a senti que quelque chose clochait. Il a demandé à Yale s’il connaissait Oliver.",
          DialogueId = 80130331,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990E6E",
          NextDialogue = 80130332,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Then that old bastard caught on. He asked Yale if he'd ever heard the name \"Oliver.\"",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E6E"
        },
        [80130332] = {
          ContentFR = "Yale a nié, mais Jones le regardait droit dans les yeux, comme s’il me voyait derrière.",
          DialogueId = 80130332,
          GUID = "C8990E98",
          NextDialogue = 80130333,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Yale denied it. But Jones just kept staring into his eyes... like he could see me hiding behind them.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E98"
        },
        [80130333] = {
          ContentFR = "Après ça, Jones a amené un tourne-disque. À chaque fois que l’aiguille tombait et que la musique commençait, je sombrais, comme une bougie qu’on souffle dans l’obscurité.",
          DialogueId = 80130333,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8990EC2",
          NextDialogue = 80130334,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "After that, Jones wheeled in a record player. Each time the needle dropped and the music started, I blacked out— like someone snuffing a candle.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990EC2"
        },
        [80130334] = {
          ContentFR = "J’ai compris que c’était le plan de Jones pour me faire disparaître et laisser Yale prendre le contrôle.",
          DialogueId = 80130334,
          GUID = "C8990EEC",
          NextDialogue = 80130335,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "I knew the record player and the music was his new trick to wipe me out, so Yale could take the body for good.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990EEC"
        },
        [80130335] = {
          ContentFR = "J’étais prisonnier de ce cycle sans fin d’évanouissements et de brefs réveils. Je pensais que j’allais tout perdre, mes souvenirs, mes pensées, les derniers fragments de moi-même. Puis, un jour, j’ai entendu la voix de Yale, qui m’a dit qu’il n’avait plus envie d’écouter cette musique.",
          DialogueId = 80130335,
          GUID = "C8990F16",
          NextDialogue = 80130336,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Caught in that endless loop of blackouts and brief flashes of waking, I figured I'd lose everything — memories, thoughts, even the last scraps of who I was. But then, one day, I heard Yale's voice, telling me he didn't want to listen to the music any more.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F16"
        },
        [80130336] = {
          ContentFR = "C’est là que j’ai compris. Ce type que je traitais de contrefaçon depuis le début... c’était pas une copie. C’était quelqu’un. Un gars à part entière. Alors on a passé un marché. On a monté un plan. Et on s’est tirés du foutu labo de ce vieux pourri, une bonne fois pour toutes.",
          DialogueId = 80130336,
          GUID = "C8990F40",
          NextDialogue = 80130337,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "That's when it hit me: the \"knock-off\" I kept abusing... was a real person. So we made a deal. Put together a plan. And broke out of that old bastard's lab for good.",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F40"
        },
        [80130337] = {
          ContentFR = "On a atterri à Rougerive, ouvert un magasin de jouets. Yale lui a donné un nom nul : Crac’n’Pop. Et on n’a plus jamais reparlé du labo.",
          DialogueId = 80130337,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990F6A",
          NextDialogue = 80130338,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "We made it to Scarletriver and opened a toy shop. He named it Snap 'n' Spark — stupid name, if you ask me — and we never spoke of the lab again.",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F6A"
        },
        [80130338] = {
          ContentFR = "Il y a quelques jours, j’ai encore perdu conscience, la même sensation familière. Je me suis dit qu’il s’était drogué pour m’éteindre. J’ai fouiné, j’ai appris qu’il était allé à Givrelac.",
          DialogueId = 80130338,
          GUID = "C8990F94",
          NextDialogue = 80130339,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Couple days ago, I blacked out again — that same old, familiar feeling. Figured he must've dosed himself to shut me down. No idea what he got up to while I was under, so I asked around. Turns out he'd taken a trip to Icelake.",
          TalkActionId = {
            [1] = "93103:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F94"
        },
        [80130339] = {
          ContentFR = "Honnêtement, je suis celui qui le connaît le mieux. Timide, réservé, mais trop gentil. Il ne me cacherait rien... sauf si quelque chose le ronge.",
          DialogueId = 80130339,
          GUID = "C8990FBE",
          NextDialogue = 80130340,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Thing is, I know him better than anyone — timid, shy... but too kind and soft for his own good. Definitely not the type to pull a stunt behind my back — not unless something was eating at him.",
          TalkActionId = {
            [1] = "93103:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990FBE"
        },
        [80130340] = {
          ContentFR = "Alors j’ai pris le médicament aussi, pour l’assommer, et je suis venu ici. Je veux savoir ce qu’il a pu dire dans mon dos.",
          DialogueId = 80130340,
          GUID = "C8990FE8",
          NextOptions = {
            [1] = 801303401
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "So I took the meds myself, knocked him out, and came here. I need to know what he said behind my back.",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990FE8"
        },
        [80130341] = {
          ContentFR = "<I>Tu racontes l’histoire que Yale t’a confiée sur Crac’n’Pop et son ancien propriétaire, une histoire qui, en réalité, parlait de son propre corps... et d’Oliver.</>",
          DialogueId = 80130341,
          GUID = "C8991012",
          IsBlack = 1,
          NextDialogue = 80130342,
          Subtitle = "(You recount Yale's tale about Snap 'n' Spark and the mysterious former shopkeeper, which, in fact, is a metaphor of his very body and its true owner.)",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8991012"
        },
        [80130342] = {
          ContentFR = "Alors... il s’est drogué pour s’endormir, et il a décidé ici qu’il allait me rendre mon corps ?",
          DialogueId = 80130342,
          GUID = "C899103C",
          NextDialogue = 80130343,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "So... he drugged me, came here, and decided to give the body back to me!?",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C899103C"
        },
        [80130343] = {
          ContentFR = "Quel... quel idiot. Incorrigible crétin au cœur trop tendre...",
          DialogueId = 80130343,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8991066",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextOptions = {
            [1] = 801303431,
            [2] = 801303432
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "That... that idiot... that hopeless, soft-hearted wimp!",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8991066"
        },
        [80130344] = {
          ContentFR = "... Très drôle. Ce que je dois faire, c’est attendre qu’il se réveille pour qu’on règle ça une bonne fois pour toutes.",
          DialogueId = 80130344,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8991090",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130346,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "...Hilarious. What I need to do now is wait for him to wake up, so that we can sort all this out.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8991090"
        },
        [80130345] = {
          ContentFR = "Je sais pas. Je vais rester là jusqu’à ce qu’il se réveille, et on parlera de tout.",
          DialogueId = 80130345,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C89910BA",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130346,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Maybe. Maybe not. Either way, I'm staying put till he wakes, and we'll sort it out.",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89910BA"
        },
        [80130346] = {
          ContentFR = "Merci, au fait, de m’avoir écouté. Quand Yale se réveillera, s’il est trop têtu, je vais avoir besoin que tu le raisonnes.",
          DialogueId = 80130346,
          FacialId = {
            [1] = "93103:Happy02"
          },
          GUID = "C89910E4",
          NextDialogue = 80130347,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          Subtitle = "Thanks, by the way, for hearing me out. When Yale wakes up... if he turns out to be too stubborn, I might need you to back me up.",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89910E4"
        },
        [80130347] = {
          ContentFR = "Oliver est assis, anxieux, tapant du pied. On dirait que ça va prendre un moment avant que Yale se réveille...",
          DialogueId = 80130347,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C899110E",
          IsBlack = 1,
          Subtitle = "Oliver sits restlessly, one leg bouncing non-stop. It looks like it'll be a while before Yale wakes up...",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C899110E"
        },
        [80130401] = {
          Camera = "-49.926758,-243.0,161.0,0.000036,-19.199852,68.998772,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Où est-ce que... je suis ?",
          DialogueId = 80130401,
          FacialId = {
            [1] = "790023:Smile01"
          },
          FinalCamera = "-49.926758,-249.212219,161.0,0.000036,-19.199852,68.998741,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89919EA",
          NextDialogue = 80130402,
          SpeakNpcId = 790023,
          Subtitle = "Where am I...?",
          TalkActionId = {
            [1] = "790023:Talk03_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Yeer/004/C89919EA"
        },
        [80130402] = {
          Camera = "-75.0,-188.0,153.0,0.000051,-4.999999,-66.802383,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "C’est... lumineux. Et chaud. Pas comme ce lieu qui revient tout le temps dans mes rêves... Là-bas, les lumières restent allumées, mais il y fait toujours froid.",
          DialogueId = 80130402,
          FinalCamera = "-58.0,-188.0,153.0,0.000051,-4.999999,-66.802383,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8991A14",
          LookAt = {
