          NextDialogue = 80130403,
          Scripts = "SetLocation{ActorId{100001},TargetPoint{\"TargetPoint_Nvzhu\"},Visibility{\"Show\"}}",
          SpeakNpcId = 790023,
          Subtitle = "So bright... and warm... Not like the place in my dreams— lights always on, yet freezing cold.",
