        [80130411] = {
          Camera = "-315.086426,-472.144592,127.0,-0.0,-4.000004,58.795139,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Non, pas du tout !",
          DialogueId = 80130411,
          FacialId = {
            [1] = "790023:None"
          },
          GUID = "C8991B8E",
          LookAt = {
            [1] = "790023:n(100001)",
