          SpeakNpcId = 790036,
          Subtitle = "Will I...",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7690"
        },
        [80140329] = {
          ContentFR = "Hmm ? Ce truc marmonne quoi, là ?",
          DialogueId = 80140329,
          GUID = "C89F76BA",
          LookAt = {
            [1] = "100337:n(790058)",
            [2] = "100336:n(790058)"
