          GUID = "C89F778C",
          NextDialogue = 80140335,
          SpeakNpcId = 100337,
          SpeakNpcName = "UI_Npc_Name_LaoLianjin",
          Subtitle = "\"Why\"?",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F778C"
        }
      }
    end
