  {
    MinKey = 80140335,
    MaxKey = 80160114,
    Loader = function()
      return {
        [80140335] = {
          ContentFR = "Est-ce que tu t’excuses quand tu écrases une fourmi ? Tu expliques à une cerise pourquoi tu la broies entre tes dents ?",
          DialogueId = 80140335,
          GUID = "C89F77B6",
          NextDialogue = 80140336,
          SpeakNpcId = 100337,
          SpeakNpcName = "UI_Npc_Name_LaoLianjin",
          Subtitle = "Would you explain to an ant why you're crushing it underfoot? Would you justify to a cherry why you're chewing it to a pulp?",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F77B6"
        },
        [80140336] = {
          ContentFR = "Ah, pardon... J’avais oublié. Un rebut comme toi a sans doute jamais goûté une cerise de sa vie.",
          DialogueId = 80140336,
          GUID = "C89F77E0",
          NextDialogue = 80140337,
          SpeakNpcId = 100337,
          SpeakNpcName = "UI_Npc_Name_LaoLianjin",
          Subtitle = "Oh, wait — I forgot. A wretched thing like you has probably never even tasted a cherry.",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F77E0"
        },
        [80140337] = {
          ContentFR = "Tu n’as toujours pas fait l’injection ? Dépêche-toi. On n’a pas de temps à perdre.",
          DialogueId = 80140337,
          GUID = "C89F780A",
          LookAt = {
            [1] = "100337:n(100336)",
            [2] = "100336:n(100337)"
          },
          NextDialogue = 80140338,
          SpeakNpcId = 100337,
          SpeakNpcName = "UI_Npc_Name_LaoLianjin",
          Subtitle = "Why is the injection taking so long? Hurry up and get it done.",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F780A"
        },
        [80140338] = {
          ContentFR = "C’est fait, professeur.",
          DialogueId = 80140338,
          GUID = "C89F7834",
          SpeakNpcId = 100336,
          SpeakNpcName = "UI_Npc_Name_XiaoLianjin",
          Subtitle = "It's done, Professor.",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7834"
        },
        [80140339] = {
          Camera = "-94.440186,-1.264404,77.296875,0.000404,36.399063,-23.382465,14.951323,125.0,false,DoNotOverride,2.8",
          ContentFR = "... Je sais.",
          DialogueId = 80140339,
          GUID = "C89F785E",
          NextDialogue = 80140340,
          SpeakNpcId = 790036,
          Subtitle = "...I have.",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F785E"
        },
        [80140340] = {
          ContentFR = "Hein ? Tu sais quoi ?",
          DialogueId = 80140340,
          GUID = "C89F7888",
          LookAt = {
            [1] = "100337:n(790058)",
            [2] = "100336:n(790058)"
          },
          NextDialogue = 80140341,
          SpeakNpcId = 100336,
          SpeakNpcName = "UI_Npc_Name_XiaoLianjin",
          Subtitle = "Hmm? You have what?",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7888"
        },
        [80140341] = {
          ContentFR = "Je sais quel goût ont les cerises. La première fois que ma mère et moi avons été recueillis par le théâtre... la directrice nous a offert un vrai festin. En dessert, il y avait une tarte aux cerises.",
          DialogueId = 80140341,
          GUID = "C89F78B2",
          NextDialogue = 80140342,
          SpeakNpcId = 790036,
          Subtitle = "I have tasted a cherry. The first time my mother and I were taken in by the theatre, the director treated us to a hearty meal. For dessert, we had cherry pie.",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F78B2"
        },
        [80140342] = {
          ContentFR = "Je me souviens... Quand elle a été coupée, un sirop rouge sombre a coulé hors de sa croûte dorée. Un parfum sucré... intense... bien plus noble que n’importe quelle friandise bon marché. Ce parfum-là... il a rempli toute la salle en une seconde.",
          DialogueId = 80140342,
          GUID = "C89F78DC",
          NextDialogue = 80140343,
          SpeakNpcId = 790036,
          Subtitle = "I still remember when it was cut open — deep red syrup spilling from the golden crust, its sweet aroma filling the dining hall at once. It was so much richer than any cheap candy could ever be.",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F78DC"
        },
        [80140343] = {
          ContentFR = "La directrice a dit qu’à son âge, elle ne pouvait plus manger sucré. Mais je savais qu’elle me mentait... Elle voulait juste me laisser sa part. Parce qu’elle avait vu dans mes yeux à quel point je la voulais.",
          DialogueId = 80140343,
          GUID = "C89F7906",
          NextDialogue = 80140344,
          SpeakNpcId = 790036,
          Subtitle = "The director said she couldn't eat sweets at her age, but I knew... she just wanted me to have her slice. She could see how much I loved that cherry pie.",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7906"
        },
        [80140344] = {
          ContentFR = "À l’époque, Madame Violetta, ma professeure, était encore jeune, vive... Elle mangeait sa part à toutes petites bouchées, et jetait des regards furtifs à son miroir de poche, pour voir si elle avait des miettes sur le visage.",
          DialogueId = 80140344,
          GUID = "C89F7930",
          NextDialogue = 80140345,
          SpeakNpcId = 790036,
          Subtitle = "In those days, Ms Violetta — my mentor — was a bright young woman. She took dainty nibbles of her portion, all the while checking a compact mirror to ensure she hadn't gotten crumbs on her face.",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7930"
        },
        [80140345] = {
          ContentFR = "Et puis il y avait Susanna et Dennis, encore enfants... Ils se battaient pour la dernière part. Ils ont décidé de faire un concours de récitation pour la gagner... mais ils ont tellement cafouillé que Madame Violetta a failli s’étouffer de rire.",
          DialogueId = 80140345,
          GUID = "C89F795A",
          NextDialogue = 80140346,
          SpeakNpcId = 790036,
          Subtitle = "And then there were little Susanna and Dennis, bickering over who'd get the last slice. They decided to settle it with a line-reading contest, but both messed up so badly that Ms Violetta nearly choked from frustration.",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F795A"
        },
        [80140346] = {
          ContentFR = "Ahah... Je me demande ce qu’ils deviennent maintenant. Sans moi, le \"menteur\", la troupe peut sûrement jouer en paix, non ?",
          DialogueId = 80140346,
          GUID = "C89F7984",
          NextDialogue = 80140347,
          SpeakNpcId = 790036,
          Subtitle = "Ha... I wonder how they're all doing now. Without this \"lying fraud\" around, the troupe can finally perform properly... right?",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7984"
        },
        [80140347] = {
          ContentFR = "...",
          DialogueId = 80140347,
          GUID = "C89F79AE",
          NextDialogue = 80140348,
          SpeakNpcId = 100336,
          SpeakNpcName = "UI_Npc_Name_XiaoLianjin",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F79AE"
        },
        [80140348] = {
          Camera = "-94.440186,-1.264404,77.296875,0.000404,36.399063,-23.382465,14.951323,125.0,false,DoNotOverride,2.8",
          ContentFR = "Quoi ? Un souci ?",
          DialogueId = 80140348,
          FinalCamera = "-94.440186,-1.264404,77.296875,0.000426,42.395412,-2.778932,14.951323,125.0,false,DoNotOverride,2.8",
          GUID = "C89F79D8",
          NextDialogue = 80140349,
          Scripts = "MoveTo{ActorId{100337},MoveSpeed{60},TargetPoint{\"Move\"}}",
          SpeakNpcId = 100337,
          SpeakNpcName = "UI_Npc_Name_LaoLianjin",
          Subtitle = "Is there a problem?",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F79D8"
