          DialogueId = 80140356,
          GUID = "C89F7B28",
          IsBlack = 1,
          SpeakNpcId = 790036,
          Subtitle = "(You — have become a monster too.)",
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7B28"
        },
        [80140357] = {
