        [80140407] = {
          Camera = "226.189453,553.110352,113.588379,0.000044,-4.199979,-87.397324,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Quoi, déjà ? Il est même pas si tard ! Allez, reste un peu, fais une dernière réplique avec moi ! Celle que Madame Violetta nous a faite bosser aujourd’hui, je la maîtrise pas encore.",
          DialogueId = 80140407,
          FacialId = {
            [1] = "790027:CM_Smile01"
          },
          GUID = "C89F8386",
          NextDialogue = 80140408,
          SpeakNpcId = 790026,
          Subtitle = "Oh, come on, it's not even that late! Practise with me for a bit. I still haven't memorised the lines Ms Violetta taught us today.",
          TalkActionId = {
            [1] = "790027:Talk03_End",
            [2] = "790026:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8386"
        },
        [80140408] = {
          Camera = "602.087891,-88.831787,85.242676,0.000014,-0.400024,133.199921,35.000008,525.224243,false,Manual,2.8",
          ContentFR = "Encore ?! Aïe... bon, bon, d’accord, je te suis... mais arrête de frapper d’abord !",
          DialogueId = 80140408,
          FinalCamera = "510.33252,8.879395,84.308105,0.000014,-0.400024,133.199921,35.000008,2024.230103,false,Manual,2.8",
          GUID = "C89F83B0",
          NextDialogue = 80140409,
          Scripts = "MoveTo{ActorId{790026},MoveSpeed{60},TargetPoint{\"P80140426\"}}",
          SpeakNpcId = 790027,
          Subtitle = "Ow! Not again... Alright, alright! I'll do it. No need to start throwing punches, just saying...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F83B0"
        },
        [80140409] = {
          ContentFR = "<I>Ils n’ont pas changé... Pas du tout.</>",
          DialogueId = 80140409,
          GUID = "C89F83DA",
          NextDialogue = 80140410,
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Tuosi",
          Subtitle = "(Those two... they haven't changed a bit.)",
          TalkActionId = {
            [1] = "790025:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F83DA"
        },
        [80140410] = {
          Camera = "136.138672,760.375244,255.158691,0.000026,-19.999907,-75.596756,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Au fait, la pièce du mois prochain, elle est choisie ?",
          DialogueId = 80140410,
          FinalCamera = "-128.058105,642.81958,243.39624,0.000037,-18.99983,-43.396786,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F8404",
          NextDialogue = 80140411,
          SpeakNpcId = 790026,
          Subtitle = "By the way, has the play for next month been decided yet?",
          TalkActionId = {
            [1] = "790026:Think_Start"
          },
          ToFinalCameraBlendTime = 35,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8404"
        },
        [80140411] = {
          ContentFR = "La directrice a dit qu’on jouerait <I>Pluie d’automne</>.",
          DialogueId = 80140411,
          GUID = "C89F842E",
          NextDialogue = 80140412,
          SpeakNpcId = 790027,
          Subtitle = "The director said we'll be performing Rainy Days.",
          TalkActionId = {
            [1] = "790027:Explain01_Start",
            [2] = "790026:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F842E"
        },
        [80140412] = {
          ContentFR = "<I>Pluie d’automne</> ? C’est pas super populaire, non ? Pour se faire remarquer, c’est pas l’idéal... <I>Soupir...</> Si seulement on pouvait refaire <I>Né du blizzard</>. À Givrelac, tout le monde adore cette pièce...",
          DialogueId = 80140412,
          GUID = "C89F8458",
          NextDialogue = 80140413,
          SpeakNpcId = 790026,
          Subtitle = "Rainy Days isn't exactly a crowd-pleaser, is it? It's hard to make a name for yourself with that one. *sigh* ...If only we could put on Children From the Snowfield again. That was such a hit in Icelake...",
          TalkActionId = {
            [1] = "790026:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8458"
        },
        [80140413] = {
          ContentFR = "Carrément ! Je voudrais rejouer la fée sans nom. C’était mon rôle préféré, même si les chants étaient horribles à apprendre... Quand je l’ai fait en entier, c’était magique.",
          DialogueId = 80140413,
          GUID = "C89F8482",
          NextDialogue = 80140414,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790027},AnimationId{"Agree"},Duration{1}},
PlayAnimation{ActorId{790027},AnimationId{"Explain02_Start"},Duration{3},_delay{1}},
PlayAnimation{ActorId{790027},AnimationId{"Explain02_End"},Duration{1}}
}]],
          SpeakNpcId = 790027,
          Subtitle = "Exactly! I'd love to play the Nameless Fairy again. That was my best role! Sure, the singing parts were tough, but performing it all the way through felt incredible.",
          TalkActionId = {
            [1] = "790026:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8482"
        },
        [80140414] = {
          Camera = "245.842773,452.263184,118.095703,0.000008,-6.0,-87.99778,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh ? Vraiment ? Je pensais que Fane l’avait mieux interprété que toi.",
          DialogueId = 80140414,
          FacialId = {
            [1] = "790026:CM_Shock01"
          },
          GUID = "C89F84AC",
          NextDialogue = 80140415,
          SpeakNpcId = 790026,
          Subtitle = "Really? Personally, I think Fane is the best among us.",
          TalkActionId = {
            [1] = "790026:Shock_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F84AC"
        },
        [80140415] = {
          Camera = "132.975586,162.901611,104.536133,0.000011,-0.800081,44.600689,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu plaisantes ? C’est moi qui ai assuré dans le final, tu le sais très bien !",
          DialogueId = 80140415,
          FacialId = {
            [1] = "790027:CM_Angry01"
          },
          GUID = "C89F84D6",
          LookAt = {
            [1] = "790025:n(790025)"
          },
          NextDialogue = 80140416,
          SpeakNpcId = 790027,
          Subtitle = "No, he is not! Those final arias in the last act? I nailed them better than he did!",
          TalkActionId = {
            [1] = "790027:Angry01_Start",
            [2] = "790026:Shock_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F84D6"
        },
        [80140416] = {
          Camera = "-499.695312,1424.604492,320.095459,0.000023,-18.799973,-178.997177,35.000008,446.117035,false,Manual,1.236337",
          ContentFR = "...",
          DialogueId = 80140416,
          GUID = "C89F8500",
          NextDialogue = 80140417,
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Tuosi",
          Subtitle = "...",
          TalkActionId = {
            [1] = "790027:Angry01_End"
          },
          TurnTo = {
            [1] = "790025:p(150)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8500"
        },
        [80140417] = {
          ContentFR = "... En vrai, ni Fane ni moi n’étions les meilleurs.",
          DialogueId = 80140417,
          GUID = "C89F852A",
          NextDialogue = 80140418,
          SpeakNpcId = 790027,
          Subtitle = "...Actually, neither Fane nor I is the best.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F852A"
        },
        [80140418] = {
          ContentFR = "...",
          DialogueId = 80140418,
          GUID = "C89F8554",
          LookAt = {
            [1] = "790025:n(790026)"
          },
          NextDialogue = 80140419,
          SpeakNpcId = 790026,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8554"
        },
        [80140419] = {
          ContentFR = "Non, c’est vrai. Pour <I>Né du blizzard</>, personne n’arrivait à la cheville de Parsifal. Je me demande bien ce qu’il est devenu...",
          DialogueId = 80140419,
          GUID = "C89F857E",
          NextDialogue = 80140420,
          SpeakNpcId = 790026,
          Subtitle = "Yeah, you're right. When it comes to Children From the Snowfield, no one could outshine Parsifal. I just wonder... where is he now?",
          TurnTo = {
            [1] = "790025:p(-50)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F857E"
        },
        [80140420] = {
          Camera = "220.45752,2492.598633,1532.584961,0.000103,-41.999317,-110.678604,24.770275,100000.0,false,DoNotOverride,2.8",
          ContentFR = "<I>Je suis là.</>",
          DialogueId = 80140420,
          FinalCamera = "309.450684,2728.375977,1759.494141,0.000103,-41.999317,-110.678604,24.770275,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F85A8",
          LookAt = {
            [1] = "790025:n(790026)"
          },
          NextDialogue = 80140421,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt03/0081_scene_alchemyacademy\"}}",
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Tuosi",
          Subtitle = "(I'm right here.)",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F85A8"
        },
        [80140421] = {
          ContentFR = "<I>Je suis juste là, devant vous...</>",
          DialogueId = 80140421,
          GUID = "C89F85D2",
          NextDialogue = 80140422,
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Tuosi",
          Subtitle = "(Right in front of you...)",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F85D2"
        },
        [80140422] = {
          ContentFR = "<I>Je...</>",
          DialogueId = 80140422,
          GUID = "C89F85FC",
          NextDialogue = 80140423,
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Tuosi",
          Subtitle = "(I...)",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F85FC"
        },
        [80140423] = {
          Camera = "121.94873,146.241211,123.842773,0.00001,-6.600128,46.39674,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Parsifal...",
          DialogueId = 80140423,
          GUID = "C89F8626",
          NextDialogue = 80140424,
          SpeakNpcId = 790027,
          Subtitle = "Parsifal...",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8626"
        },
        [80140424] = {
          Camera = "149.733398,593.0,86.0,0.0,0.0,-72.599388,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ah zut, j’aurais pas dû le mentionner. La dernière fois que la directrice a dit son nom, t’as crié si fort que t’as failli casser tous les décors...",
          DialogueId = 80140424,
          FacialId = {
            [1] = "790026:CM_Sad01"
          },
          GUID = "C89F8650",
          LookAt = {
            [1] = "790027:n(790027)"
          },
          NextDialogue = 80140425,
          SpeakNpcId = 790026,
          Subtitle = "Oh, right. I shouldn't have mentioned him in front of you. Last time the director brought him up, you got so mad you nearly smashed the props.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8650"
        },
        [80140425] = {
          Camera = "43.179199,176.508789,110.248047,0.000011,-3.59994,23.599939,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "... Ouais. J’étais furieux. À cause de lui et de Madame Violetta, on a annulé la pièce. Tout ce travail... gâché.",
          DialogueId = 80140425,
          FacialId = {
            [1] = "790026:CM_Shock01"
          },
          GUID = "C89F867A",
          LookAt = {
            [1] = "790026:n(790027)"
          },
          NextDialogue = 80140426,
          SpeakNpcId = 790027,
          Subtitle = "Yeah... I was furious back then. If not for him and Ms Violetta deceiving the audience, Children From the Snowfield wouldn't have been cancelled. All those rehearsals wouldn't have gone to waste..",
          TurnTo = {
            [1] = "790027:p(90)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F867A"
        },
        [80140426] = {
          ContentFR = "Mais... je me suis souvent demandé depuis, est-ce qu’il avait vraiment tort de monter sur scène ? Est-ce que c’était sa faute à lui, ou celle de cette foutue règle qui interdit aux Charons de jouer ?",
          DialogueId = 80140426,
          GUID = "C89F86A4",
          LookAt = {
            [1] = "790027:n(790026)"
          },
          NextDialogue = 80140427,
          SpeakNpcId = 790027,
          Subtitle = " But.. I've asked myself many times since then — was he really wrong for stepping on that stage? Was it his fault for breaking the rule that says \"Charons can't perform,\" or... was the rule itself at fault?",
          TurnTo = {
            [1] = "790027:n(790026)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F86A4"
        },
        [80140427] = {
          ContentFR = "Pourquoi on monte sur scène ? Pour <H>célébrer l’art, ce qu’il a de plus pur</>...",
          DialogueId = 80140427,
          GUID = "C89F86CE",
          NextDialogue = 80140428,
          SpeakNpcId = 790027,
          Subtitle = "Why do we stand on the stage? To honour the unparalleled value of art.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F86CE"
        },
        [80140428] = {
          ContentFR = "Alors pourquoi les gens regardent les cornes avant la performance ? Si on jouait tous derrière un rideau, Parsifal serait-il différent de nous ?",
          DialogueId = 80140428,
          GUID = "C89F86F8",
          NextDialogue = 80140429,
          SpeakNpcId = 790027,
          Subtitle = "But why do people care more about whether a performer has horns than about the performance itself? If we all stood behind the curtain, how would Parsifal be any different from the rest of us?",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F86F8"
        },
        [80140429] = {
          Camera = "184.165039,231.606201,98.688477,0.00003,4.399932,43.401665,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Oh si, y’a une différence. Il chantait mieux que moi.",
          DialogueId = 80140429,
          FacialId = {
            [1] = "790027:CM_Idle"
          },
          GUID = "C89F8722",
          NextDialogue = 80140430,
          SpeakNpcId = 790027,
          Subtitle = "Oh, there is one difference — he sings better than I do.",
          TalkActionId = {
            [1] = "790027:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8722"
        },
        [80140430] = {
          Camera = "201.510254,546.49585,122.383301,0.000004,-6.400051,-77.79879,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ouah. Entendre ça de toi, c’est rare. Dennis, le grand impulsif, aurait-il mûri ?",
          DialogueId = 80140430,
          FacialId = {
            [1] = "790026:CM_Happy01"
          },
          GUID = "C89F874C",
          NextDialogue = 80140431,
          SpeakNpcId = 790026,
          Subtitle = "Wow, it's rare to hear you say something like that. Looks like our reckless little Dennis is finally growing up!",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F874C"
        },
        [80140431] = {
          Camera = "96.443359,130.570557,116.894043,0.000003,-3.99997,42.200706,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Hé ! Commence pas à jouer la directrice, toi !",
          DialogueId = 80140431,
          FacialId = {
            [1] = "790027:CM_Angry01"
          },
          GUID = "C89F8776",
          NextDialogue = 80140432,
          SpeakNpcId = 790027,
          Subtitle = "Hey, don't start acting like the director and giving me lectures, alright?",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8776"
        },
        [80140432] = {
          Camera = "201.510254,546.49585,122.383301,0.000004,-6.400051,-77.79879,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Mais non, c’était un compliment ! Mais si Parsifal réapparaît un jour, je lui passerai un sacré savon. Disparaître comme ça, sans une lettre... Je lui en veux, mais il me manque.",
          DialogueId = 80140432,
          FacialId = {
            [1] = "790026:CM_Smile01"
          },
          GUID = "C89F87A0",
          NextDialogue = 80140433,
          SpeakNpcId = 790026,
          Subtitle = "That wasn't a lecture — it was a compliment! But if Parsifal ever comes back, I'll give him a real telling-off. Vanishing without so much as a note... What was he thinking? *sigh* I really miss him.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F87A0"
        },
        [80140433] = {
          Camera = "-1153.268066,1960.390137,235.713867,0.000035,-6.800218,-58.593773,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentFR = "<I>Susanna... Dennis...</>",
          DialogueId = 80140433,
          GUID = "C89F87CA",
          NextDialogue = 80140434,
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Paxi",
          Subtitle = "(Susanna... Dennis...)",
          TalkActionId = {
            [1] = "790025:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F87CA"
        },
        [80140434] = {
          Camera = "185.86377,442.624756,59.498047,0.000046,11.799335,-73.192505,47.811131,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Tu te souviens de ce que disait Violetta ? « Peut-être pas aujourd’hui, mais un jour, notre art connaîtra une époque plus pure. Une époque sans Solariens ni Charons, où seule comptera la beauté du jeu. »",
          DialogueId = 80140434,
          FacialId = {
            [1] = "790026:CM_Smile01"
          },
          FinalCamera = "199.419434,397.746582,69.291504,0.000046,11.799335,-73.192505,47.811131,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F87F4",
          NextDialogue = 80140435,
          SpeakNpcId = 790026,
          Subtitle = "Do you remember what Ms Violetta used to say? \"Someday — not now, but in the future — our art will usher in a purer era, one free of prejudice or discrimination, with no divide between Solas and Charons.\"",
          TalkActionId = {
            [1] = "790025:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F87F4"
        },
        [80140435] = {
          ContentFR = "Je pense que, même si Violetta et Parsifal ont été rejetés, s’ils ont couvert notre troupe de honte... c’est justement grâce à des gens comme eux qu’un avenir meilleur pourra voir le jour.",
          DialogueId = 80140435,
          GUID = "C89F881E",
          NextDialogue = 80140436,
          SpeakNpcId = 790026,
          Subtitle = "I believe that even though Ms Violetta and Parsifal were scorned by so many, which brought shame upon the troupe... it's people like them who will bring about that brighter future.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F881E"
        },
        [80140436] = {
          ContentFR = "Ce jour-là, ils ne seront plus une \"honte\", mais des \"héros\" qui ont simplement ouvert les yeux avant les autres.",
          DialogueId = 80140436,
          FacialId = {
            [1] = "790026:CM_Happy01"
          },
          GUID = "C89F8848",
          NextDialogue = 80140437,
          SpeakNpcId = 790026,
          Subtitle = "When that day arrives, they won't be remembered as \"disgraces.\" They'll be seen as \"heroes\" — visionaries who woke up before the rest of us.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8848"
        },
        [80140437] = {
          Camera = "-475.065918,1530.032227,242.341553,0.000032,-7.199647,-170.999466,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 80140437,
          GUID = "C89F8872",
          NextDialogue = 80140438,
          SpeakNpcId = 790025,
          SpeakNpcName = "UI_Npc_Name_Paxi",
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8872"
        },
        [80140438] = {
          Camera = "52.178223,609.198242,243.78833,0.000039,-21.399986,-59.798325,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Souhaitons-lui bonne chance ! Peut-être qu’il est déjà dans un endroit où les Charons ont le droit de monter sur scène, comme à Luca ou à Aethyrie.",
          DialogueId = 80140438,
          FinalCamera = "-116.030762,898.193115,370.702637,0.000039,-21.399986,-59.798325,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F889C",
          NextDialogue = 80140439,
          SpeakNpcId = 790026,
          Subtitle = "Let's wish him well, wherever he is! Maybe he's already found somewhere Charons can stand on stage — like Luca or Aethyrie.",
          TalkActionId = {
            [1] = "790026:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F889C"
        },
        [80140439] = {
          ContentFR = "Et qui sait, quand on partira en tournée là-bas, peut-être qu’on tombera sur lui... devenu une grande star comme Madame Violetta !",
          DialogueId = 80140439,
          GUID = "C89F88C6",
          LookAt = {
            [1] = "790025:n(790025)"
          },
          NextDialogue = 80140440,
          SpeakNpcId = 790026,
          Subtitle = "Who knows? Next time we tour those countries, we might find he's already become a superstar, just like Ms Violetta!",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F88C6"
        },
        [80140440] = {
          ContentFR = "Ouais. J’espère qu’un jour, on remontera tous ensemble sur scène.",
          DialogueId = 80140440,
          GUID = "C89F88F0",
          LookAt = {
            [1] = "790027:n(790027)",
            [2] = "790026:n(790026)"
          },
          NextDialogue = 80140454,
          SpeakNpcId = 790027,
          Subtitle = "Yeah. I hope we get to share the stage with him again someday.",
          TalkActionId = {
            [1] = "790026:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F88F0"
        },
        [80140441] = {
          Camera = "644.496094,-490.569336,714.540771,0.000021,-32.197926,139.796692,23.178257,407.658783,false,DoNotOverride,1.2",
          ContentFR = "Si... si toi et moi nous étions rencontrés en tant qu’humains... est-ce qu’on serait tous les quatre sortis ensemble du théâtre, en riant comme ce soir ?",
          DialogueId = 80140441,
          FinalCamera = "644.496094,-490.569336,603.562866,0.000021,-32.197926,139.796692,23.178257,407.658783,false,DoNotOverride,1.2",
          GUID = "C89F891A",
          LookAt = {
            [1] = "790029:n(790028)"
          },
          NextDialogue = 80140442,
          SpeakNpcId = 790029,
          Subtitle = "If we had met as humans... would it have been the four of us leaving the theatre together, laughing and chatting?",
          TalkActionId = {
            [1] = "790029:Explain02_Start",
            [2] = "790028:Tuosi02_Emo_Idle_Pose"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F891A"
        },
        [80140442] = {
          ContentFR = "Susanna t’aurait sauté dessus pour que tu l’accompagnes gratuitement, et toi, évidemment, t’aurais accepté sans discuter. On aurait tous fini dehors à répéter dans le froid, juste pour lui faire plaisir.",
          DialogueId = 80140442,
          GUID = "C89F8944",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_110304_02.T_Story_Recall_110304_02'",
          NextDialogue = 80140443,
          SpeakNpcId = 790029,
          Subtitle = "Susanna wouldn't let you off the hook as her free accompanist. And knowing you, you'd agree without hesitation. Before we knew it, we'd all be out there, rehearsing on the freezing streets just to humour her.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8944"
        },
        [80140443] = {
          ContentFR = "Mais toi... tu avais une famille. Ta sœur, toujours sérieuse, toujours droite, serait sûrement venue te chercher. Ou alors... c’est toi qui l’aurais embarquée avec nous. Oui, c’est plus ton genre, ça.",
          DialogueId = 80140443,
          GUID = "C89F896E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_110304_01.T_Story_Recall_110304_01'",
          NextDialogue = 80140444,
          SpeakNpcId = 790029,
          Subtitle = "Oh wait... you had family. Your no-nonsense big sister would probably show up to drag you home. Or maybe... maybe you'd convince her to join us instead — yes, that's more like how it would end up.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F896E"
        },
        [80140444] = {
          ContentFR = "Non. Impossible. Qu’est-ce que je suis encore en train de m’inventer ?",
          DialogueId = 80140444,
          GUID = "C89F8998",
          IsBlack = 1,
          NextDialogue = 80140445,
          SpeakNpcId = 790029,
          Subtitle = "No. That's never going to happen. What am I thinking, now that things have come to this?",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8998"
        },
        [80140445] = {
          ContentFR = "Cette scène, ces rôles, ces amis... c’était Parsifal. Ce n’est plus moi.",
          DialogueId = 80140445,
          GUID = "C89F89C2",
          IsBlack = 1,
          NextDialogue = 80140446,
          SpeakNpcId = 790029,
          Subtitle = "That stage, those scripts, those friends... they belong to Parsifal. I no longer have them.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F89C2"
        },
        [80140446] = {
          ContentFR = "Mais...",
          DialogueId = 80140446,
          GUID = "C89F89EC",
          IsBlack = 1,
          NextDialogue = 80140447,
          SpeakNpcId = 790029,
          Subtitle = "But—",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F89EC"
        },
        [80140447] = {
          Camera = "612.479492,-311.0,51.0,-0.0,6.400003,149.998077,35.0,407.658783,false,DoNotOverride,1.2",
          ContentFR = "Ici, il me reste un dernier rôle. Et moi seul peux l’interpréter.",
          DialogueId = 80140447,
          GUID = "C89F8A16",
          NextDialogue = 80140448,
          Scripts = "PlayAnimation{_click{false},_delay{5},ActorId{790029},AnimationId{\"Explain02_End\"},Duration{1}}",
          SpeakNpcId = 790029,
          Subtitle = "Here, there's one final performance. One only I can deliver.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8A16"
        },
        [80140448] = {
          Camera = "101.459473,-124.397461,114.37085,0.00001,19.398399,147.190094,35.000008,407.658783,false,DoNotOverride,1.2",
          ContentFR = "J’ai trouvé assez de peintures, d’huiles, pour me faire passer pour toi. J’ai vu votre planque. Et avec la chaîne que tu m’as laissée...",
          DialogueId = 80140448,
          FinalCamera = "33.354004,-80.496094,142.904297,0.00001,19.398399,147.190094,35.000008,407.658783,false,DoNotOverride,1.2",
          GUID = "C89F8A40",
          NextDialogue = 80140449,
          Scripts = [[
SEQ{
PlayAnimation{_click{false},ActorId{790029},AnimationId{"Talk01_Start"},Duration{1}},
PlayAnimation{_click{false},_delay{5},ActorId{790029},AnimationId{"Talk01_End"},Duration{1}},
PlayAnimation{_click{false},ActorId{790029},AnimationId{"Agree"},Duration{1},_delay{1}}
}]],
          SpeakNpcId = 790029,
          Subtitle = "I've gathered paints and oils, enough to make myself look almost identical to you. I've seen your secret hideout. And with the harmonica chain you left me...",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8A40"
        },
        [80140449] = {
          Camera = "-1737.0,1331.0,973.443848,-0.000001,29.000006,-64.800743,35.0,407.658783,false,DoNotOverride,1.2",
          ContentFR = "Le comédien est prêt. Le costume, les accessoires, le décor aussi. Il ne manque plus que le rideau qui se lève.",
          DialogueId = 80140449,
          FinalCamera = "-1737.0,1331.0,973.443848,-0.000001,30.999987,-64.80072,35.0,407.658783,false,DoNotOverride,1.2",
          GUID = "C89F8A6A",
          LookAt = {
            [1] = "790029:n(790029)"
          },
          NextDialogue = 80140450,
          SpeakNpcId = 790029,
          Subtitle = "The performer, the costume, the props, the set — all ready. Now, all that's left is for the curtain to rise.",
          ToFinalCameraBlendTime = 6,
          TurnTo = {
            [1] = "790029:p(-90)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8A6A"
        },
        [80140450] = {
          Camera = "613.405762,312.25,52.490479,0.000005,6.699862,-153.800339,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Ne t’en fais pas, Blues. J’ai promis. Et je tiendrai parole.",
          DialogueId = 80140450,
          FinalCamera = "640.817383,256.542969,52.490479,0.000005,6.699862,-153.800339,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F8A94",
          Scripts = [[
SEQ{
MoveTo{_click{false},ActorId{790029},MoveSpeed{95},TargetPoint{"P80140449"}},
CameraMoveTo{_click{false},_delay{4},TargetPosition{"58.193848,40.453125,189.723633,0.0,2.899996,-130.398499,35.0,100000.0,false,DoNotOverride,2.8"},duration{0}},
LookAt{_click{false},LookAtDescription{"790029:n(790028)"}}
}]],
          SpeakNpcId = 790029,
          Subtitle = "Don't worry, Blues. I'll keep my promise and see it through.",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8A94"
        },
        [80140451] = {
          ContentFR = "Je suis un comédien. Fier. Voici mon chant d’adieu.",
          DialogueId = 80140451,
          Duration = 4,
          GUID = "C89F8ABE",
          Subtitle = "I am a proud performer, delivering my swan song.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8ABE"
        },
        [80140452] = {
          ContentFR = "Puis, je quitterai la scène. Rideau.",
          DialogueId = 80140452,
          Duration = 3,
          GUID = "C89F8AE8",
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt03/0081_scene_alchemyacademy\"}}",
          Subtitle = "And in the end, I take my bow and leave the stage.",
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8AE8"
        },
        [80140453] = {
          Camera = "-1100.918945,1811.1875,204.0,0.0,-4.200006,-54.398975,35.000008,100000.0,false,DoNotOverride,2.8",
          DialogueId = 80140453,
          DialoguePanelType = "None",
          FinalCamera = "-1069.729492,1833.51709,204.0,0.0,-4.200006,-54.398975,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F82B5",
          NextDialogue = 80140403,
          ToFinalCameraBlendTime = 7
        },
        [80140454] = {
          Camera = "-580.74707,2433.777832,1315.769531,0.000017,-44.999565,-77.270569,21.224024,100000.0,false,DoNotOverride,2.8",
          DialogueId = 80140454,
          DialoguePanelType = "None",
          Duration = 5,
          FinalCamera = "-593.387207,2489.751953,1373.1521,0.000017,-44.999565,-77.270569,21.224024,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F88F1",
          Scripts = [[
PARA{
MoveTo{ActorId{790026},MoveSpeed{80},TargetPoint{"P790026"}},
MoveTo{ActorId{790027},MoveSpeed{80},TargetPoint{"P790027"}},
MoveTo{ActorId{790025},MoveSpeed{80},TargetPoint{"P790029"}}
}]],
          ToFinalCameraBlendTime = 15
        },
        [80150001] = {
          ContentFR = "Est-ce que... tu avais besoin de moi pour quelque chose ? Une... invitation ? Pour moi ?",
          DialogueId = 80150001,
          GUID = "C8A5A98A",
          Subtitle = "Is there something you need assistance with? Huh? An invitation... for me?",
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5A98A"
        },
        [80150101] = {
          Camera = "-432.783447,-252.461426,34.288513,0.000162,5.008967,35.653843,25.0,503.514496,false,Manual,3.0",
          ContentFR = "Rhythm est déjà là. Elle est arrivée en avance au lieu de rendez-vous.",
          DialogueId = 80150101,
          FinalCamera = "-429.728973,-256.719727,34.288513,0.000162,5.008967,35.653843,25.0,503.514496,false,Manual,3.0",
          GUID = "C8A5B9F2",
          NextDialogue = 80150102,
          Subtitle = "(Rhythm appears to have arrived early.)",
          TalkActionId = {
            [1] = "790044:Lise_Emo_Clean_Loop"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5B9F2"
        },
        [80150102] = {
          Camera = "-34.298531,29.784668,139.973953,0.000186,-2.391133,-69.942337,25.0,94.575653,false,Manual,3.0",
          ContentFR = "Tu la vois, sans ses gants habituels, elle ajuste rapidement sa coiffure devant la vitre, le regard fuyant.",
          DialogueId = 80150102,
          GUID = "C8A5BA1C",
          NextOptions = {
            [1] = 801501021,
            [2] = 801501022
          },
          Subtitle = "(You notice she's uncharacteristically taken off her gloves and is checking her reflection in the window, adjusting her hair.)",
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BA1C"
        },
        [80150103] = {
          Camera = "-33.815468,132.302734,128.652939,0.000185,-0.989838,-71.132233,25.0,208.607803,false,Manual,3.0",
          ContentFR = "Ah ?!",
          DialogueId = 80150103,
          FacialId = {
            [1] = "790044:Shock01"
          },
          GUID = "C8A5BA46",
          NextDialogue = 80150104,
          SpeakNpcId = 790044,
          Subtitle = "Ah!?",
          TalkActionId = {
            [1] = "790044:Shock_Start"
          },
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BA46"
        },
        [80150104] = {
          ContentFR = "Elle sursaute. Tu ne comprends pas exactement ce qui se passe, un éclair de lumière surgit, et ton corps se met à se contracter de façon incontrôlable.",
          DialogueId = 80150104,
          GUID = "C8A5BA70",
          IsBlack = 1,
          NextDialogue = 80150105,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/player/Lise/skill01_hit_str\"},PlayAs2D{true}}",
          Subtitle = "(Your sudden appearance catches Rhythm off guard. It all happens so quickly — there's a flash of bright light, and you feel a strange twitch in your body.)",
          TurnTo = {
            [1] = "790044:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BA70"
        },
        [80150105] = {
          Camera = "-445.195038,-405.307617,388.882507,0.000286,-26.194109,45.102966,25.0,1.5,false,DoNotOverride,15.0",
          ContentFR = "{nickname} ! Tu vas bien ?!",
          DialogueId = 80150105,
          FinalCamera = "-445.195038,-405.307617,377.687317,0.000285,-25.194054,44.502701,25.0,1.5,false,DoNotOverride,15.0",
          GUID = "C8A5BA9A",
          NextDialogue = 80150106,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/player/Lise/skill01_hit_str\"},PlayAs2D{true}}",
          SpeakNpcId = 790044,
          Subtitle = "?! Are you alright?",
          TalkActionId = {
            [1] = "790044:Shock_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BA9A"
        },
        [80150106] = {
          Camera = "-40.058441,39.776855,134.843063,0.000255,1.20561,-70.709114,35.000008,1.5,false,DoNotOverride,15.0",
          ContentFR = "Ou-oui... juste... comme si j’avais pris... une décharge...",
          DialogueId = 80150106,
          FacialId = {
            [1] = "790008:Ahaha02"
          },
          FinalCamera = "-39.278023,37.547852,134.892807,0.000255,1.20561,-71.109024,35.000008,1.5,false,DoNotOverride,15.0",
          GUID = "C8A5BAC4",
          NextDialogue = 80150107,
          SpeakNpcId = 790008,
          Subtitle = "I—I—I'm fine... just... felt an... e—e—electric...shock...",
          TalkActionId = {
            [1] = "790008:Sigh_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BAC4"
        },
        [80150107] = {
          Camera = "-57.003677,-15.846191,180.836349,0.000262,-21.793663,58.104839,35.000011,1.5,false,DoNotOverride,15.0",
          ContentFR = "Pardon. Je... je n’ai pas bien contrôlé mes pouvoirs...",
          DialogueId = 80150107,
          FacialId = {
            [1] = "790044:Sad01",
            [2] = [[

790008:None]]
          },
          GUID = "C8A5BAEE",
          NextDialogue = 80150110,
          SpeakNpcId = 790044,
          Subtitle = "Sorry, I failed to control my powers properly...",
          TalkActionId = {
            [1] = "790008:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BAEE"
        },
        [80150108] = {
          Camera = "-33.815468,132.302734,128.652939,0.000185,-0.989838,-71.132233,25.0,208.607803,false,Manual,3.0",
          ContentFR = "Ah, te voilà... Il y avait beaucoup de vent en venant, mes cheveux étaient en bataille. Je voulais les arranger un peu.",
          DialogueId = 80150108,
          GUID = "C8A5BB18",
          NextDialogue = 80150109,
          SpeakNpcId = 790044,
          Subtitle = "Oh, it's you... It was really windy on my way here, and my hair got all messy, so I thought I'd tidy up a bit.",
          TalkActionId = {
            [1] = "790044:Sigh_End"
          },
          TurnTo = {
            [1] = "790044:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BB18"
        },
        [80150109] = {
          Camera = "-36.580048,-34.005859,134.240494,0.000189,0.610011,71.466766,25.0,116.244736,false,Manual,3.0",
          ContentFR = "Attends. Je remets mes gants. Je ne voudrais pas te blesser par accident.",
          DialogueId = 80150109,
          GUID = "C8A5BB42",
          NextDialogue = 80150110,
          SpeakNpcId = 790044,
          Subtitle = "Wait a second, let me put my gloves back on — I'd hate to hurt you by accident.",
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BB42"
        },
        [80150110] = {
          Camera = "-28.686066,121.959473,136.35405,0.000194,-1.994627,-75.695625,35.000008,189.677307,false,Manual,5.0",
          ContentFR = "{性别:Désolé|Désolée}, je t’ai fait attendre ?",
          DialogueId = 80150110,
          FacialId = {
            [1] = "790044:None"
          },
          GUID = "C8A5BB6C",
          NextDialogue = 80150111,
          SpeakNpcId = 790008,
          Subtitle = "Sorry I'm late.",
          TalkActionId = {
            [1] = "790008:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BB6C"
        },
        [80150111] = {
          Camera = "-61.534256,-174.127441,136.342422,0.000261,-1.99352,69.701683,35.000011,1.5,false,DoNotOverride,15.0",
          ContentFR = "Non, ce n’est rien... C’est moi qui suis arrivée trop tôt.",
          DialogueId = 80150111,
          FacialId = {
            [1] = "790044:Smile01"
          },
          GUID = "C8A5BB96",
          NextDialogue = 80150112,
          SpeakNpcId = 790044,
          Subtitle = "No, it's fine... I actually came too early.",
          TalkActionId = {
            [1] = "790044:DisagreeHead",
            [2] = [[

790008:Talk02_End]]
          },
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BB96"
        },
        [80150112] = {
          Camera = "-248.447357,-402.659668,260.974548,0.000288,-18.193834,59.49369,35.000011,1.5,false,DoNotOverride,15.0",
          ContentFR = "Et... merci de m’avoir invitée. Je suis restée trop longtemps dans les rangs des Veilleurs. Là-bas, tout était réglé : lever, patrouille, repas... Depuis que j’ai quitté la Légion, sans horaires fixes, je me sens un peu... perdue.",
          DialogueId = 80150112,
          FinalCamera = "-276.814423,-450.70166,295.601501,0.000289,-21.193995,59.893017,35.000011,1.5,false,DoNotOverride,15.0",
          GUID = "C8A5BBC0",
          NextDialogue = 80150113,
          SpeakNpcId = 790044,
          Subtitle = "And thank you for having me here. After serving in the Escort for so long, I've become accustomed to a strict routine — getting up, patrolling, meals... But now that I've left the Legion, without that fixed schedule, I'm not quite sure what to do with myself anymore.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BBC0"
        },
        [80150113] = {
          Camera = "-28.686066,121.959473,136.35405,0.000194,-1.994627,-75.695625,35.000008,189.677307,false,Manual,5.0",
          ContentFR = "Tu n’as jamais été en retard, n’est-ce pas ?",
          DialogueId = 80150113,
          FacialId = {
            [1] = "790008:Smile02"
          },
          GUID = "C8A5BBEA",
          NextDialogue = 80150114,
          SpeakNpcId = 790008,
          Subtitle = "You must have never been late, right?",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BBEA"
        },
        [80150114] = {
          Camera = "-57.786217,-158.110352,137.150558,0.000258,-2.393585,70.501198,35.000011,1.5,false,DoNotOverride,15.0",
          ContentFR = "Chez les Veilleurs, le retard équivalait à un blâme. Et puis... je me disais que si j’arrivais plus tôt, je pourrais toujours en faire un peu plus que les autres.",
          DialogueId = 80150114,
          GUID = "C8A5BC14",
          NextDialogue = 80150115,
          SpeakNpcId = 790044,
          Subtitle = "In the Escort, tardiness would get you written up... Plus, back then, I always thought that the earlier I arrived, the more I could accomplish compared to others.",
          TalkActionId = {
            [1] = "790044:Explain01_Start",
            [2] = [[

790008:Think_End]]
          },
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BC14"
        },
        [80150115] = {
          ContentFR = "Les Veilleurs s’occupaient de tout ce que les autres refusaient de faire, patrouilles urbaines, traque des Souillés, médiation des conflits, nettoyage des égouts... Parfois même, ils étaient chargés de missions classées secret par le haut commandement de la Légion.",
          DialogueId = 80150115,
          GUID = "C8A5BC3E",
          NextOptions = {
            [1] = 801501151,
            [2] = 801501152
          },
          Scripts = "PlayAnimation{_delay{2},ActorId{790044},AnimationId{\"Confident_Start\"},Duration{1}}",
          SpeakNpcId = 790044,
          Subtitle = "In the Escort, we were responsible for pretty much everything in the city — patrols, dealing with Filthoids, resolving disputes, clearing out the sewers... Sometimes, we'd even assist with confidential tasks for the higher-ups in the Legion.",
          TalkActionId = {
            [1] = "790044:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BC3E"
        },
        [80150116] = {
          Camera = "-136.425461,-331.263672,112.150925,0.000309,-0.393275,66.71666,35.000011,1.5,false,DoNotOverride,15.0",
          ContentFR = "Peut-être... Au départ, j’ai pris ce poste en espérant devenir une Charon Couronnée, et aider ceux de mon peuple du mieux que je pouvais.",
          DialogueId = 80150116,
          FinalCamera = "-147.876663,-326.149902,112.150925,0.000309,0.006735,65.517342,35.000011,1.5,false,DoNotOverride,15.0",
          GUID = "C8A5BC68",
          NextDialogue = 80150117,
          SpeakNpcId = 790044,
          Subtitle = "I suppose so... At first, I took the job hoping that, as I worked my way towards the title of Laurelled Charon, I could also do something to help my fellow Charons.",
          TalkActionId = {
            [1] = "790044:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BC68"
        },
        [80150117] = {
          Camera = "-301.315765,-406.490723,309.517883,0.00037,-23.193838,54.118931,25.0,1.5,false,DoNotOverride,15.0",
          ContentFR = "Mais une fois sur le terrain, j’ai vu des réalités que je n’aurais jamais imaginées...",
          DialogueId = 80150117,
          FinalCamera = "-310.991913,-420.473145,319.580383,0.000366,-23.593794,54.918797,25.0,1.5,false,DoNotOverride,15.0",
          GUID = "C8A5BC92",
          NextDialogue = 80150118,
          SpeakNpcId = 790044,
          Subtitle = "But once I started, I realised that the situation many Charons face is far worse than I had imagined...",
          TalkActionId = {
            [1] = "790044:Talk03_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BC92"
        },
        [80150118] = {
          Camera = "-378.580231,-484.69873,32.48877,0.0,4.605992,51.329815,25.0,577.353577,false,Manual,3.0",
          ContentFR = "Certains Charons triment jour et nuit dans des échoppes tenues par des Solariens, sans contrat, sous-payés, juste pour économiser de quoi acheter un permis de circulation et pouvoir s’installer à Givrelac.",
          DialogueId = 80150118,
          FacialId = {
            [1] = "790044:Think01"
          },
          FinalCamera = "-389.878632,-475.570312,32.48877,0.000001,4.805994,50.930901,25.0,577.353577,false,Manual,3.0",
          GUID = "C8A5BCBC",
          NextDialogue = 80150119,
          SpeakNpcId = 790044,
          Subtitle = "Some of them work themselves to the bone in back-alley shops run by Solas, taking menial jobs without proper contracts, just to save up for a travel permit to stay in Icelake.",
          TalkActionId = {
            [1] = "790044:Talk03ToThink_Start"
          },
          ToFinalCameraBlendTime = 9.5,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BCBC"
        },
        [80150119] = {
          Camera = "-34.448036,24.091309,124.4207,0.000072,6.405153,-69.263062,25.0,577.353577,false,DoNotOverride,3.0",
          ContentFR = "Et il suffit d’une lettre d’accusation, même totalement inventée, pour qu’un Charon sans permis soit arrêté sur-le-champ. Quant au commerçant, il s’en tire sans verser le moindre salaire.",
          DialogueId = 80150119,
          FacialId = {
            [1] = "790008:Unhappy01"
          },
          GUID = "C8A5BCE6",
          NextDialogue = 80150120,
          SpeakNpcId = 790044,
          Subtitle = "However, before they could scrape together enough money for a travel permit, it only took one complaint letter for a Charon to be thrown in jail, while the shop owners would get away with not paying them.",
          TalkActionId = {
            [1] = "790008:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BCE6"
        },
        [80150120] = {
          Camera = "-44.109055,-126.602539,136.444473,0.0001,-3.194643,70.337288,25.0,577.353577,false,DoNotOverride,3.0",
          ContentFR = "À chaque fois que je voyais ça, je faisais ce que je pouvais, réprimander ces patrons véreux, plaider la cause des victimes, les blanchir... Mais les salaires perdus, eux, ne revenaient jamais.",
          DialogueId = 80150120,
          FacialId = {
            [1] = "790008:None"
          },
          FinalCamera = "-37.875015,-128.81543,136.444473,0.0001,-3.194643,71.137253,25.0,577.353577,false,DoNotOverride,3.0",
          GUID = "C8A5BD10",
          NextDialogue = 80150121,
          Scripts = "PlayAnimation{_delay{8},ActorId{790044},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 790044,
          Subtitle = "Every time I came across these cases, all I could do was reprimand the unscrupulous shopkeepers and try my best to help those Charons clear their names. Most of the time, I couldn't even recover their wages.",
          TalkActionId = {
            [1] = "790044:Think_End",
            [2] = [[

790008:Explain02_End]]
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BD10"
        },
        [80150121] = {
          Camera = "-5.2649,-7.188477,165.547684,0.000205,-19.394308,83.935265,27.000002,577.353577,false,DoNotOverride,3.0",
          ContentFR = "En y repensant, j’ai l’impression de n’avoir servi à rien. Je venais juste plus tôt, veillais à ce que mes hommes ne brutalisent pas les Charons... rien de plus.",
          DialogueId = 80150121,
          FacialId = {
            [1] = "790044:Sad01"
          },
          FinalCamera = "-5.2649,-7.188477,165.547684,0.000213,-19.394308,83.935249,29.0,577.353577,false,DoNotOverride,3.0",
          GUID = "C8A5BD3A",
          NextDialogue = 80150122,
          SpeakNpcId = 790044,
          Subtitle = "In retrospect, I feel like I haven't really done anything useful. The best I did was go to work early every day and make sure my subordinates weren't rough with Charon citizens during their shifts.",
          TalkActionId = {
            [1] = "790044:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BD3A"
        },
        [80150122] = {
          Camera = "1.409618,-55.074219,133.131363,0.000191,-2.394548,92.124672,25.0,577.353577,false,DoNotOverride,3.0",
          ContentFR = "C’est ironique, tu ne trouves pas ? J’ai mis tant d’efforts à m’adapter à la Légion, à vouloir la réformer... Et au final, je n’ai rien changé. C’est elle qui m’a changée.",
          DialogueId = 80150122,
          FacialId = {
            [1] = "790044:Ahaha01"
          },
          FinalCamera = "11.094885,-54.509277,133.131363,0.000189,-2.194546,94.124893,25.0,577.353577,false,DoNotOverride,3.0",
          GUID = "C8A5BD64",
          NextDialogue = 80150123,
          Scripts = "PlayAnimation{_delay{2},ActorId{790044},AnimationId{\"ExplainTwo_Start\"},Duration{1}}",
          SpeakNpcId = 790044,
          Subtitle = "It's ironic, isn't it? I spent so much time trying to fit in with the Legion, thinking I could make a difference. But in the end, I realised I couldn't change anything... and instead, the Legion changed me.",
          TalkActionId = {
            [1] = "790044:ScratchHead_End"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BD64"
        },
        [80150123] = {
          Camera = "35.181286,178.780762,145.219193,0.000211,-4.794485,-103.074188,35.0,577.353577,false,DoNotOverride,3.0",
          ContentFR = "Je me souviens encore... Il y a quelques mois, un jeune Charon a été abattu en pleine rue par un soldat... Je n’ai pas pu faire en sorte que son meurtrier soit puni.",
          DialogueId = 80150123,
          FacialId = {
            [1] = "790044:Sad02"
          },
          FinalCamera = "41.404854,177.280762,145.219193,0.000211,-4.19446,-105.474739,35.0,577.353577,false,DoNotOverride,3.0",
          GUID = "C8A5BD8E",
          NextDialogue = 80150124,
          SpeakNpcId = 790044,
          Subtitle = "I still remember a few months ago, a young Charon man was shot dead in the street by one of the soldiers... I couldn't even get justice for him.",
          TalkActionId = {
            [1] = "790044:ExplainTwo_End",
            [2] = [[

790008:Think_Start]]
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BD8E"
        },
        [80150124] = {
          Camera = "38.396221,-28.182129,144.513809,0.000195,-3.394488,111.523338,35.0,577.353577,false,DoNotOverride,3.0",
          ContentFR = "J’ai plaidé son cas devant mes supérieurs. Tout ce que j’ai reçu, c’est un avertissement : « Occupe-toi de tes affaires. » Alors j’ai compris que cette affaire serait enterrée comme tant d’autres.",
          DialogueId = 80150124,
          FacialId = {
            [1] = "790044:Sad01"
          },
          FinalCamera = "38.396221,-28.182129,144.513809,0.000205,-3.394488,111.523308,37.0,577.353577,false,DoNotOverride,3.0",
          GUID = "C8A5BDB8",
          NextDialogue = 80150125,
          SpeakNpcId = 790044,
          Subtitle = "I tried to argue with my superiors about the soldier's punishment, but all I got was a warning to \"mind my own business\"... I knew right then that there was no point in pushing further, and the case was swept under the rug just like that.",
          TalkActionId = {
            [1] = "790044:Sigh_Start"
          },
          ToFinalCameraBlendTime = 11.5,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BDB8"
        },
        [80150125] = {
          Camera = "8.642662,54.186523,123.681046,0.000211,6.805033,-95.275452,37.0,577.353577,false,DoNotOverride,3.0",
          ContentFR = "La seule chose que j’ai pu faire... c’est organiser ses funérailles. Et laisser un peu d’argent à son père. Mais pour le reste... j’étais impuissante.",
          DialogueId = 80150125,
          FacialId = {
            [1] = "790008:Sad01"
          },
          GUID = "C8A5BDE2",
          NextOptions = {
            [1] = 801501251,
            [2] = 801501252
          },
          SpeakNpcId = 790044,
          Subtitle = "In the end, all I could do was help bury the young man properly and leave some money for his father to live on... As for the source of the tragedy, I was completely powerless to do anything about it.",
          TalkActionId = {
            [1] = "790044:Sigh_End",
            [2] = [[

790008:Think_End]]
          },
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BDE2"
        },
        [80150126] = {
          Camera = "64.037247,-191.337891,135.108414,0.000222,-1.59517,110.723915,35.0,577.353577,false,DoNotOverride,3.0",
          ContentFR = "Hein... ?",
          DialogueId = 80150126,
          FacialId = {
            [1] = "790044:Shock01"
          },
          GUID = "C8A5BE0C",
          NextDialogue = 80150127,
          SpeakNpcId = 790044,
          Subtitle = "Huh?",
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BE0C"
        },
        [80150127] = {
          Camera = "42.326603,34.966309,162.393936,0.000196,-12.195159,-114.703926,35.000008,1.5,false,DoNotOverride,15.0",
          ContentFR = "J’étais sous le choc. Je n’ai rien pu faire...",
          DialogueId = 80150127,
          FacialId = {
            [1] = "790008:Unhappy01"
          },
          FinalCamera = "42.326603,34.966309,162.393936,0.000204,-12.195159,-114.703911,36.0,1.5,false,DoNotOverride,15.0",
          GUID = "C8A5BE36",
          NextDialogue = 80150129,
          SpeakNpcId = 790008,
          Subtitle = "But I just stood by... totally in shock.",
          TalkActionId = {
            [1] = "790008:Explain02_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BE36"
        },
        [80150128] = {
          Camera = "51.694923,-135.471191,130.445541,0.000198,-2.39004,114.467331,25.0,222.044281,false,Manual,3.0",
          ContentFR = "Mais toi, tu as agi. Comparé à ceux qui ont détourné le regard, tu t’es tenue droite.",
          DialogueId = 80150128,
          FacialId = {
            [1] = "790008:Unhappy01"
          },
          FinalCamera = "54.578606,-134.157715,130.445541,0.000198,-2.39004,114.467331,25.0,222.044281,false,Manual,3.0",
          GUID = "C8A5BE60",
          NextDialogue = 80150129,
          SpeakNpcId = 790008,
          Subtitle = "Compared to other Legion members who turned a blind eye, you did more than most.",
          TalkActionId = {
            [1] = "790008:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BE60"
        },
        [80150129] = {
          Camera = "64.961464,239.010254,146.234573,0.000215,-4.794485,-107.101105,36.0,1.5,false,DoNotOverride,15.0",
          ContentFR = "Tu as ressenti de la colère, de l’injustice, et tu as essayé de changer les choses. Et maintenant, tu as quitté la Légion. C’est la preuve que tu ne t’es pas laissée corrompre. Tu es restée toi-même.",
          DialogueId = 80150129,
          FacialId = {
            [1] = "790044:Sad01",
            [2] = [[

790008:None]]
          },
          FinalCamera = "78.562416,234.505371,146.234573,0.000217,-4.594483,-110.301086,36.0,1.5,false,DoNotOverride,15.0",
          GUID = "C8A5BE8A",
          NextDialogue = 80150130,
          Scripts = "PlayAnimation{_delay{2},ActorId{790008},AnimationId{\"Explain01L_Start\"},Duration{1}}",
          SpeakNpcId = 790008,
          Subtitle = "At least you still care. You saw injustice, you felt indignation, and you tried to make a difference. And now, your decision to leave the Legion shows that you haven't let them change you — you refused to become one of them.",
          TalkActionId = {
            [1] = "790008:Explain02_End"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BE8A"
        },
        [80150130] = {
          Camera = "18.275681,-22.90625,132.089951,0.000379,3.803268,101.912422,35.000008,1.5,false,DoNotOverride,15.0",
          ContentFR = "... Merci.",
          DialogueId = 80150130,
          GUID = "C8A5BEB4",
          NextDialogue = 80150131,
          Scripts = [[
PARA{
PlayAnimation{_delay{2},ActorId{790044},AnimationId{"AgreeHead"},Duration{2}},
PlayFacial{_delay{2},ActorId{790044},FacialId{"Ahaha01"}},
}]],
          SpeakNpcId = 790044,
          Subtitle = "...Thank you.",
          TalkActionId = {
            [1] = "790008:Explain01L_End"
          },
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BEB4"
        },
        [80150131] = {
          Camera = "544.644653,-481.905273,0.226059,0.000371,7.4029,139.905487,25.0,764.135925,false,Manual,3.0",
          ContentFR = "Je croyais être la seule à ressentir ce genre de choses. Les autres... ils ont préféré devenir complices, ou se convaincre que suivre les ordres sans réfléchir était la bonne voie.",
          DialogueId = 80150131,
          FacialId = {
            [1] = "790044:None"
          },
          FinalCamera = "544.644653,-481.905273,19.850174,0.000372,4.802879,139.905487,25.0,764.135925,false,Manual,3.0",
          GUID = "C8A5BEDE",
          NextDialogue = 80150132,
          SpeakNpcId = 790044,
          Subtitle = "I thought I was the only one carrying this burden. Everyone else either became the Legion's accomplices or convinced themselves to follow orders blindly, never questioning anything.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BEDE"
        },
        [80150132] = {
          Camera = "79.820587,-183.252441,89.199783,0.000411,6.203034,115.097778,30.0,287.422333,false,Manual,3.0",
          ContentFR = "Mais après tout... dans ce système, c’était normal. Même un Charon Couronné peut finir au cachot, juste à cause d’une dénonciation.",
          DialogueId = 80150132,
          FinalCamera = "84.749573,-180.955078,89.199783,0.000408,6.203034,114.897316,30.0,287.422333,false,Manual,3.0",
          GUID = "C8A5BF08",
          NextDialogue = 80150133,
          SpeakNpcId = 790044,
          Subtitle = "Although... I guess, serving in the Legion, they had no other choice. After all, even a Laurelled Charon can end up in jail because of a complaint letter, just like those without a travel permit.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BF08"
        },
        [80150133] = {
          Camera = "30.429073,138.662598,138.840347,0.000409,-3.196897,-105.904358,30.0,287.422333,false,Manual,3.0",
          ContentFR = "Mais... tu as raison. Je n’ai plus à craindre de devenir comme eux. Je suis libre, à nouveau moi-même. Même si je n’ai plus d’horaires fixes... c’est toujours mieux que de devoir obéir aveuglément aux règles de la Légion.",
          DialogueId = 80150133,
          FinalCamera = "32.942013,137.945801,138.840347,0.000409,-3.196897,-105.904396,30.0,287.422333,false,Manual,3.0",
          GUID = "C8A5BF32",
          NextDialogue = 80150134,
          SpeakNpcId = 790044,
          Subtitle = "But... you're right. I don't have to worry about turning into one of them anymore. I'm free to be myself again. Though I still feel a bit lost without an official schedule, it's so much better than living by their rules.",
          TalkActionId = {
            [1] = "790008:Talk03_Start",
            [2] = [[

790044:AgreeHead]]
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BF32"
        },
        [80150134] = {
          Camera = "-6.938042,-5.080078,140.156479,0.000421,-0.797117,86.295319,30.0,80.256699,false,Manual,3.0",
          ContentFR = "La prochaine fois qu’on se voit... je ne viendrai pas en avance.",
          DialogueId = 80150134,
          FacialId = {
            [1] = "790044:Happy01"
          },
          FinalCamera = "-6.938042,-5.080078,140.156479,0.000422,-0.797117,86.295303,31.0,81.0,false,Manual,3.0",
          GUID = "C8A5BF5C",
          SpeakNpcId = 790044,
          Subtitle = "Next time we meet, I won't come too early.",
          TalkActionId = {
            [1] = "790008:Talk03_End",
            [2] = [[

790044:Explain02_Start]]
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Lise/001/C8A5BF5C"
        },
        [80150201] = {
          Camera = "618.764404,403.857422,222.649796,0.000534,-8.595123,-145.30249,30.0,782.587708,false,Manual,3.0",
          ContentFR = "Cette fois, Rhythm n’est ni en avance, ni en retard, elle arrive pile à l’heure.",
          DialogueId = 80150201,
          FinalCamera = "618.764404,403.857422,258.947632,0.000537,-13.19516,-147.301575,30.0,782.587708,false,Manual,3.0",
          GUID = "C8A5CA5A",
          NextDialogue = 80150202,
          Subtitle = "(This time, Rhythm arrives on time.)",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CA5A"
        },
        [80150202] = {
          Camera = "128.130157,-64.091309,138.956345,0.00055,-1.994538,156.287964,35.0,209.939255,false,Manual,5.0",
          ContentFR = "Mais à peine arrivée, tu la vois déjà concentrée, le regard fixé vers un coin de la pièce, comme perdue dans ses pensées.",
          DialogueId = 80150202,
          FinalCamera = "129.21524,-61.620605,138.956345,0.00055,-1.994538,156.287964,35.0,209.939255,false,Manual,5.0",
          GUID = "C8A5CA84",
          NextOptions = {
            [1] = 801502021,
            [2] = 801502022
          },
          Subtitle = "(She's staring at the corner of the room, seemingly lost in thought.)",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CA84"
        },
        [80150203] = {
          Camera = "129.21524,-61.620605,138.956345,0.00055,-1.994538,156.287964,35.0,209.939255,false,Manual,5.0",
          ContentFR = "... Je t’en prie, ne me fais plus ce genre de surprise. Si jamais je perds à nouveau le contrôle de mes pouvoirs, tu pourrais te blesser.",
          DialogueId = 80150203,
          FacialId = {
            [1] = "790044:Iyada01"
          },
          GUID = "C8A5CAAE",
          NextDialogue = 80150204,
          SpeakNpcId = 790044,
          Subtitle = "...Please, don't spook me like that again. If I lose control of my powers, you might get hurt.",
          TurnTo = {
            [1] = "790044:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CAAE"
        },
        [80150204] = {
          Camera = "-49.563354,59.401855,141.255112,0.001375,-2.999081,-45.834862,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "Quel dommage... {性别:J’étais curieux|J’étais curieuse} de revivre ce petit choc électrique.",
          DialogueId = 80150204,
          FacialId = {
            [1] = "790008:Blink"
          },
          FinalCamera = "-49.563354,59.401855,141.255112,0.001375,-2.999081,-45.834862,36.0,291.99585,false,DoNotOverride,15.0",
          GUID = "C8A5CAD8",
          NextDialogue = 80150205,
          SpeakNpcId = 790008,
          Subtitle = "Too bad. I kinda miss that shock.",
          TalkActionId = {
            [1] = "790008:Talk01_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CAD8"
        },
        [80150205] = {
          Camera = "35.557709,-28.460938,135.738373,0.00136,0.802158,141.569565,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "... Je crains de ne pas comprendre ce genre de... lubie étrange.",
          DialogueId = 80150205,
          FacialId = {
            [1] = "790044:Doubt01"
          },
          FinalCamera = "35.557709,-28.460938,135.738373,0.00136,0.802158,141.569565,36.0,291.99585,false,DoNotOverride,15.0",
          GUID = "C8A5CB02",
          NextDialogue = 80150206,
          SpeakNpcId = 790044,
          Subtitle = "I... don't really understand this quirk of yours.",
          TalkActionId = {
            [1] = "790044:DisagreeHead"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CB02"
        },
        [80150206] = {
          Camera = "-111.224487,148.813965,141.615067,0.001381,-3.399535,-55.230232,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "Tu faisais quoi, à l’instant ?",
          DialogueId = 80150206,
          FacialId = {
            [1] = "790008:None"
          },
          FinalCamera = "-108.748169,150.532227,141.615021,0.001381,-3.599537,-55.829838,35.000008,291.99585,false,DoNotOverride,15.0",
          GUID = "C8A5CB2C",
          NextDialogue = 80150208,
          SpeakNpcId = 790008,
          Subtitle = "What were you doing just now?",
          TalkActionId = {
            [1] = "790008:Talk01_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CB2C"
        },
        [80150207] = {
          Camera = "129.21524,-61.620605,138.956345,0.00055,-1.994538,156.287964,35.0,209.939255,false,Manual,5.0",
          ContentFR = "Ah, salut.",
          DialogueId = 80150207,
          GUID = "C8A5CB56",
          NextDialogue = 80150208,
          SpeakNpcId = 790044,
          Subtitle = "Ah, you came.",
          TurnTo = {
            [1] = "790044:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CB56"
        },
        [80150208] = {
          Camera = "221.280334,-79.913574,140.015259,0.001379,-3.598205,162.369766,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "Je viens de refaire un tour dans ton logement. J’ai trouvé quelques toiles d’araignée et boules de poils planquées dans les coins... Je les ai nettoyées.",
          DialogueId = 80150208,
          FacialId = {
            [1] = "790044:Confident01"
          },
          FinalCamera = "222.133209,-77.229492,140.015289,0.001379,-3.598205,162.369766,35.000008,291.99585,false,DoNotOverride,15.0",
          GUID = "C8A5CB80",
          NextOptions = {
            [1] = 801502081,
            [2] = 801502082
          },
          SpeakNpcId = 790044,
          Subtitle = "I just inspected your place again and noticed some cobwebs and hairballs hidden in the corners. I went ahead and cleaned them up for you.",
          TalkActionId = {
            [1] = "790044:Confident_Start"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CB80"
        },
        [80150209] = {
          ContentFR = "Ce n’est pas grand-chose. Quand je commence quelque chose, j’aime le faire jusqu’au bout.",
          DialogueId = 80150209,
          FacialId = {
            [1] = "790044:Confident01"
          },
          GUID = "C8A5CBAA",
          NextDialogue = 80150211,
          SpeakNpcId = 790044,
          Subtitle = "It's fine. Once I start something, I like to follow through.",
          TalkActionId = {
            [1] = "790044:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CBAA"
        },
        [80150210] = {
          ContentFR = "Oh non, surtout pas... Je voulais juste me rendre utile, rien de plus.",
          DialogueId = 80150210,
          GUID = "C8A5CBD4",
          NextDialogue = 80150211,
          SpeakNpcId = 790044,
          Subtitle = "No... please don't. I just wanted to help, that's all.",
          TalkActionId = {
            [1] = "790044:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CBD4"
        },
        [80150211] = {
          Camera = "-101.272095,139.332031,145.298187,0.001379,-5.399469,-56.236126,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "Tu n’as pas changé. Toujours aussi appliquée.",
          DialogueId = 80150211,
          FacialId = {
            [1] = "790008:Happy02"
          },
          FinalCamera = "-99.371521,136.48877,144.974991,0.001379,-5.399469,-56.235954,35.000008,291.99585,false,DoNotOverride,15.0",
          GUID = "C8A5CBFE",
          NextDialogue = 80150212,
          SpeakNpcId = 790008,
          Subtitle = "You're still as diligent as ever.",
          TalkActionId = {
            [1] = "790008:Talk02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CBFE"
        },
        [80150212] = {
          Camera = "75.613556,-25.058594,134.501633,0.001379,-0.598174,152.772156,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "Appliquée, hein... Peut-être. À force, c’est devenu une habitude. Tu sais, je n’ai jamais eu beaucoup de talent. J’ai toujours dû compenser... à l’ancienne.",
          DialogueId = 80150212,
          FacialId = {
            [1] = "790044:Unhappy01"
          },
          FinalCamera = "75.613556,-25.058594,134.501633,0.001382,-0.598174,152.772156,37.0,291.99585,false,DoNotOverride,15.0",
          GUID = "C8A5CC28",
          NextOptions = {
            [1] = 801502121,
            [2] = 801502122
          },
          SpeakNpcId = 790044,
          Subtitle = "Diligent, huh... Maybe. It's become a habit. You know, I'm not really gifted at anything, so I've always had to make up for it with hard work.",
          TalkActionId = {
            [1] = "790044:Think_Start",
            [2] = [[

790008:Talk02_End]]
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CC28"
        },
        [80150213] = {
          Camera = "213.222778,-79.430664,146.874283,0.001398,-4.998319,160.351501,35.0,291.99585,false,DoNotOverride,15.0",
          ContentFR = "Les officiers disaient toujours que la Légion était l’endroit le plus juste de tout l’Empire. « Le mérite ne ment pas, et l’effort finit toujours par être récompensé. » Tant que tu acceptes d’en baver, même une Charon comme moi peut obtenir de la reconnaissance.",
          DialogueId = 80150213,
          FacialId = {
            [1] = "790044:Think01"
          },
          FinalCamera = "204.465332,-76.303711,146.061005,0.001398,-4.998319,160.351501,35.0,291.99585,false,DoNotOverride,15.0",
          GUID = "C8A5CC52",
          NextDialogue = 80150214,
          SpeakNpcId = 790044,
          Subtitle = "My former superiors used to say the Legion was the fairest place in the Empire, because \"meritorious service never goes unnoticed, and hard work is always rewarded.\" As long as you're willing to put in the effort, even a Charon can earn recognition.",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CC52"
        },
        [80150214] = {
          Camera = "312.985168,222.499512,18.860168,0.001343,9.600622,-145.63736,20.0,471.113068,false,Manual,1.2",
          ContentFR = "Alors j’ai foncé tête baissée, sans me poser de questions. Je poursuivais ce mirage glorieux qu’on appelle \"Charon Couronnée\", pensant avancer... Mais au bout du compte, ce que je cherchais se trouvait dans la direction opposée.",
          DialogueId = 80150214,
          FacialId = {
            [1] = "790044:Sad01"
          },
          FinalCamera = "312.985168,222.499512,33.452301,0.001343,8.40062,-145.637222,20.0,471.113068,false,Manual,1.2",
          GUID = "C8A5CC7C",
          NextDialogue = 80150215,
          SpeakNpcId = 790044,
          Subtitle = "So I kept pushing myself, chasing the dream of becoming a \"Laurelled Charon,\" but in the end, I realised the path I was on was taking me further away from what I truly wanted.",
          TalkActionId = {
            [1] = "790044:Talk01_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CC7C"
        },
        [80150215] = {
          Camera = "518.667297,378.844238,282.734802,0.00135,-19.199818,-144.032669,20.0,688.641724,false,Manual,1.2",
          ContentFR = "Je me dis parfois que c’est une chance de ne pas être douée. Au moins, je n’ai pas été assez rapide pour aller trop loin.",
          DialogueId = 80150215,
          FinalCamera = "534.613464,390.330078,296.944946,0.001353,-19.999872,-144.232666,20.0,688.641724,false,Manual,1.2",
          GUID = "C8A5CCA6",
          NextDialogue = 80150216,
          SpeakNpcId = 790044,
          Subtitle = "I can only comfort myself by thinking that, luckily, my lack of talent has kept me from going too far.",
          TalkActionId = {
            [1] = "790044:Talk01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CCA6"
        },
        [80150216] = {
          Camera = "17.473877,-22.0,137.696609,0.001373,0.600271,139.371307,35.0,688.641724,false,DoNotOverride,1.2",
          ContentFR = "Si j’avais été plus maligne, plus politique... Peut-être que je serais montée plus haut. Mais je me serais perdue en route. Et à ce stade, tout ce qui reste, c’est de pourrir lentement.",
          DialogueId = 80150216,
          FacialId = {
            [1] = "790044:Disappoint01"
          },
          FinalCamera = "17.473877,-22.0,137.696609,0.001373,0.600271,139.371307,37.0,688.641724,false,DoNotOverride,1.2",
          GUID = "C8A5CCD0",
          NextOptions = {
            [1] = 801502161,
            [2] = 801502162
          },
          SpeakNpcId = 790044,
          Subtitle = "Were I more sophisticated, more tactful, I probably would have climbed higher. But then, I'd have lost track of who I truly am and eventually rotted from the inside.",
          TalkActionId = {
            [1] = "790044:Explain02_Start"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CCD0"
        },
        [80150217] = {
          Camera = "-69.954895,82.007324,132.937286,0.001387,-0.599581,-53.436954,35.000008,173.536774,false,Manual,15.0",
          ContentFR = "Si tu devais choisir entre monter en grade ou aider quelqu’un, tu choisirais toujours d’aider.",
          DialogueId = 80150217,
          FinalCamera = "-69.954895,82.007324,135.66391,0.001388,-1.399601,-53.43697,35.000008,173.536774,false,Manual,15.0",
          GUID = "C8A5CCFA",
          NextDialogue = 80150219,
          SpeakNpcId = 790008,
          Subtitle = "If you had to choose between helping others and climbing the ladder, you'd always choose the former.",
          TalkActionId = {
            [1] = "790008:Talk02_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CCFA"
        },
        [80150218] = {
          Camera = "-69.954895,82.007324,132.937286,0.001387,-0.599581,-53.436954,35.000008,173.536774,false,Manual,15.0",
          ContentFR = "Et d’ailleurs, tu as un talent, toi aussi, celui de ne jamais trahir tes principes.",
          DialogueId = 80150218,
          FinalCamera = "-69.954895,82.007324,135.66391,0.001388,-1.399601,-53.43697,35.000008,173.536774,false,Manual,15.0",
          GUID = "C8A5CD24",
          NextDialogue = 80150219,
          SpeakNpcId = 790008,
          Subtitle = "You're gifted in your own way: you're capable of sticking to your principles better than anyone else.",
          TalkActionId = {
            [1] = "790008:Talk02_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CD24"
        },
        [80150219] = {
          Camera = "45.089478,-18.761719,132.263748,0.001392,2.401699,148.560776,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "... Merci.",
          DialogueId = 80150219,
          FacialId = {
            [1] = "790044:Happy01"
          },
          GUID = "C8A5CD4E",
          NextDialogue = 80150220,
          SpeakNpcId = 790044,
          Subtitle = "Mmm... Thank you for your kind words...",
          TalkActionId = {
            [1] = "790044:Explain02_End",
            [2] = [[

790008:Talk02_End]]
          },
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CD4E"
        },
        [80150220] = {
          Camera = "103.385284,-50.706055,132.141708,0.001397,-0.59827,154.763184,35.000008,187.416504,false,Manual,5.0",
          ContentFR = "Ton regard la touche. Elle semble vouloir dire quelque chose... mais se ravise.",
          DialogueId = 80150220,
          FacialId = {
            [1] = "790044:Doubt01"
          },
          GUID = "C8A5CD78",
          NextOptions = {
            [1] = 801502201
          },
          Subtitle = "(Rhythm looks at you as if she wants to say something but hesitates.)",
          TalkActionId = {
            [1] = "790044:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CD78"
        },
        [80150221] = {
          Camera = "18.037659,16.478027,158.897934,0.001394,-14.398284,159.76268,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "Je...",
          DialogueId = 80150221,
          FinalCamera = "14.119385,17.922363,157.825867,0.001394,-14.398284,159.76268,35.000008,291.99585,false,DoNotOverride,15.0",
          GUID = "C8A5CDA2",
          NextDialogue = 80150222,
          SpeakNpcId = 790044,
          Subtitle = "I...",
          TalkActionId = {
            [1] = "790044:Think_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CDA2"
        },
        [80150222] = {
          Camera = "107.989838,3.304688,102.144806,0.001394,10.202198,166.347549,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "Pour être honnête, je ne sais pas encore ce que je veux faire.",
          DialogueId = 80150222,
          FacialId = {
            [1] = "790044:Think01"
          },
          FinalCamera = "113.353882,2.002441,101.151398,0.001394,10.202198,166.347549,35.000008,291.99585,false,DoNotOverride,15.0",
          GUID = "C8A5CDCC",
          NextDialogue = 80150223,
          SpeakNpcId = 790044,
          Subtitle = "To be honest, I still haven't figured out what I'm supposed to be doing.",
          TalkActionId = {
            [1] = "790044:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CDCC"
        },
        [80150223] = {
          Camera = "-107.190308,170.004395,154.377823,0.001395,-7.197776,-60.649319,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "Je fais quelques petits boulots pour survivre, mais je sais que ce n’est pas ça, ma voie. Ce n’est pas un objectif. Juste une occupation.",
          DialogueId = 80150223,
          FacialId = {
            [1] = "790044:None"
          },
          FinalCamera = "-105.4422,170.974121,154.377792,0.001396,-7.197776,-60.849224,35.000008,291.99585,false,DoNotOverride,15.0",
          GUID = "C8A5CDF6",
          NextDialogue = 80150224,
          SpeakNpcId = 790044,
          Subtitle = "I've been doing odd jobs, but deep down, I know they're just work, not a real life purpose.",
          TalkActionId = {
            [1] = "790044:ScratchHead_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CDF6"
        },
        [80150224] = {
          Camera = "407.091949,-65.960449,176.961502,0.001397,-9.59744,171.546249,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "Un nouveau but... je n’en ai pas encore trouvé. En fait, je crois que j’ai toujours attendu qu’on m’en donne un.",
          DialogueId = 80150224,
          FacialId = {
            [1] = "790008:Confident01"
          },
          GUID = "C8A5CE20",
          NextDialogue = 80150225,
          SpeakNpcId = 790044,
          Subtitle = "As for what my new purpose is... I still haven't found it. More accurately, I realised I'd been waiting for someone else to give me that purpose.",
          TalkActionId = {
            [1] = "790008:Think_Start",
            [2] = [[

790044:ExplainTwo_Start]]
          },
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CE20"
        },
        [80150225] = {
          Camera = "432.948853,337.427246,446.11792,0.001453,-32.598656,-143.248642,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "J’ai avalé tout ce que la Légion m’a enseigné, sans remettre en question. J’en avais besoin. Mais quand tout ça a disparu... j’ai découvert le vide. Absolu.",
          DialogueId = 80150225,
          FinalCamera = "472.58075,367.021973,477.749329,0.001453,-32.598656,-143.248642,35.000008,291.99585,false,DoNotOverride,15.0",
          GUID = "C8A5CE4A",
          NextDialogue = 80150226,
          SpeakNpcId = 790044,
          Subtitle = "I took in all the doctrines the Legion taught me, swallowing them whole, because I needed something to hold onto. But once they were gone, my life suddenly felt empty and meaningless.",
          TalkActionId = {
            [1] = "790044:ExplainTwo_End"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CE4A"
        },
        [80150226] = {
          Camera = "98.584686,-58.58252,136.45752,0.001476,-0.397852,150.748535,50.0,186.33757,false,Manual,5.0",
          ContentFR = "Et maintenant... je ne sais plus dans quelle direction aller.",
          DialogueId = 80150226,
          FacialId = {
            [1] = "790044:Disappoint01"
          },
          FinalCamera = "99.451996,-57.033203,136.45752,0.001476,-0.397852,151.14856,50.0,186.33757,false,Manual,5.0",
          GUID = "C8A5CE74",
          NextOptions = {
            [1] = 801502261,
            [2] = 801502262
          },
          SpeakNpcId = 790044,
          Subtitle = "I don't know what to do anymore...",
          TalkActionId = {
            [1] = "790008:Think_End",
            [2] = [[

790044:Explain02_Start]]
          },
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CE74"
        },
        [80150227] = {
          Camera = "248.291321,-55.748535,179.893402,0.001385,-11.398623,168.355377,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "Hein... ?",
          DialogueId = 80150227,
          FacialId = {
            [1] = "790044:Shock01"
          },
          GUID = "C8A5CE9E",
          NextDialogue = 80150228,
          SpeakNpcId = 790044,
          Subtitle = "Huh?",
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CE9E"
        },
        [80150228] = {
          Camera = "-76.836426,91.370605,133.208633,0.001474,-0.599151,-50.636719,35.000008,190.311249,false,Manual,5.0",
          ContentFR = "Je suis {性别:sérieux|sérieuse}. Les Vagabonds de la Nuit auraient bien besoin d’une personne calme et fiable comme toi.",
          DialogueId = 80150228,
          FacialId = {
            [1] = "790008:Confident01"
          },
          FinalCamera = "-74.867371,92.984863,133.208603,0.001474,-0.599151,-52.437115,35.000008,190.311249,false,Manual,5.0",
          GUID = "C8A5CEC8",
          NextDialogue = 80150229,
          SpeakNpcId = 790008,
          Subtitle = "I'm serious. The Noctoyagers could really use someone as calm and reliable as you.",
          TalkActionId = {
            [1] = "790008:Explain02_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CEC8"
        },
        [80150229] = {
          Camera = "52.279388,10.377441,120.222504,0.001475,8.600294,162.56015,35.000008,190.311249,false,DoNotOverride,5.0",
          ContentFR = "En plus, tu pourrais continuer à aider les Charons, comme avant. Et puis, observer les différents métiers à Givrelac, voir ce qui te parle vraiment.",
          DialogueId = 80150229,
          FinalCamera = "52.279388,10.377441,120.222504,0.001475,8.600294,162.56015,36.0,190.311249,false,DoNotOverride,5.0",
          GUID = "C8A5CEF2",
          NextDialogue = 80150232,
          SpeakNpcId = 790008,
          Subtitle = "In the meantime, you could help the Charon community like before, while observing the various jobs in Icelake to find something that truly speaks to you.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CEF2"
        },
        [80150230] = {
          Camera = "248.291321,-55.748535,179.893402,0.001385,-11.398623,168.355377,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "L’objectif viendra tout seul ?",
          DialogueId = 80150230,
          FacialId = {
            [1] = "790044:Shock01"
          },
          GUID = "C8A5CF1C",
          NextDialogue = 80150231,
          SpeakNpcId = 790044,
          Subtitle = "What do you mean?",
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CF1C"
        },
        [80150231] = {
          Camera = "-76.836426,91.370605,133.208633,0.001474,-0.599151,-50.636719,35.000008,190.311249,false,Manual,5.0",
          ContentFR = "Oui. Toi, même dans les boulots les plus simples, tu donnes toujours ton maximum. Alors essaie différentes choses. Un jour ou l’autre, tu tomberas sur ce qui t’appelle vraiment.",
          DialogueId = 80150231,
          FacialId = {
            [1] = "790008:Confident01"
          },
          FinalCamera = "-74.867371,92.984863,133.208603,0.001474,-0.599151,-52.437115,35.000008,190.311249,false,Manual,5.0",
          GUID = "C8A5CF46",
          NextDialogue = 80150232,
          SpeakNpcId = 790008,
          Subtitle = "Even if it's odd jobs, you'll give your best. So why not try different jobs for now? You'll surely find what you truly want to do someday.",
          TalkActionId = {
            [1] = "790008:Explain02_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CF46"
        },
        [80150232] = {
          Camera = "-37.119324,29.090332,128.276199,0.001491,4.400479,-39.829708,35.000008,116.135979,false,Manual,3.0",
          ContentFR = "Et puis... ton avenir est une page blanche. Tu peux devenir qui tu veux. Rhythm Fischer, ce n’est plus juste un ancien grade. Ce nom-là peut s’enrichir de quelque chose de plus fort, de plus personnel.",
          DialogueId = 80150232,
          FinalCamera = "-26.108215,19.671387,115.03653,0.001497,13.200249,-39.628651,35.000008,116.135979,false,Manual,3.0",
          GUID = "C8A5CF70",
          NextDialogue = 80150233,
          Scripts = "PlayAnimation{_delay{1.5},ActorId{790008},AnimationId{\"ExplainTwo_Start\"},Duration{1}}",
          SpeakNpcId = 790008,
          Subtitle = "Right now, your life is a blank slate. You can become anyone. Rhythm Fischer — not just a Warrant Officer anymore, but someone with far more interesting and meaningful titles in the future.",
          TalkActionId = {
            [1] = "790008:Explain02_End",
            [2] = [[

790044:Explain02_End]]
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CF70"
        },
        [80150233] = {
          Camera = "297.921814,214.879883,19.846474,-3.000002,10.399884,-142.621796,15.0,379.470764,false,Manual,1.2",
          ContentFR = "Imagine : Rhythm Fischer, libraire. Ou passionnée de pêche. Dompteuse de chevaux, romancière, pâtissière... Tout est possible. Bon, sauf électricienne peut-être.",
          DialogueId = 80150233,
          FinalCamera = "324.730652,173.219727,15.300781,-1.0,11.19987,-154.821091,15.0,379.470764,false,Manual,1.2",
          GUID = "C8A5CF9A",
          NextDialogue = 80150234,
          SpeakNpcId = 790008,
          Subtitle = "Imagine this: Rhythm Fischer, the Bookstore Owner. Rhythm Fischer, the Fishing Enthusiast. Or even the Horse Whisperer, the Writer, the Pastry Chef... Anything's possible. Well, except, maybe, an electrician.",
          TalkActionId = {
            [1] = "790008:Explain01_Start"
          },
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CF9A"
        },
        [80150234] = {
          Camera = "-78.589966,94.686035,134.853287,0.001496,-1.799427,-53.230885,35.000008,195.09996,false,Manual,5.0",
          ContentFR = "Et d’ici là, tu peux aussi... juste faire une pause. C’est permis.",
          DialogueId = 80150234,
          FacialId = {
            [1] = "790008:Smile02"
          },
          FinalCamera = "-75.819092,96.756348,134.853226,0.001495,-1.799427,-54.030926,35.000008,195.09996,false,Manual,5.0",
          GUID = "C8A5CFC4",
          NextDialogue = 80150235,
          SpeakNpcId = 790008,
          Subtitle = "And before you find that new title that suits you best, it's okay to take a break. Just enjoy the time off.",
          TalkActionId = {
            [1] = "790008:Explain01_End"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CFC4"
        },
        [80150235] = {
          Camera = "150.443146,-68.690918,141.779251,0.001374,-3.398005,157.561905,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "Tu veux dire... que ne pas avancer, c’est acceptable ?",
          DialogueId = 80150235,
          FacialId = {
            [1] = "790008:Smile01"
          },
          FinalCamera = "151.495178,-66.144043,141.779282,0.001374,-3.398005,158.361923,35.000008,291.99585,false,DoNotOverride,15.0",
          GUID = "C8A5CFEE",
          NextDialogue = 80150236,
          SpeakNpcId = 790044,
          Subtitle = "You mean... it's okay to hit the pause button?",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5CFEE"
        },
        [80150236] = {
          Camera = "-71.889221,108.26416,104.530975,0.001504,5.40033,-58.024708,30.0,206.628311,false,Manual,5.0",
          ContentFR = "Bien sûr que oui. Même une machine finit par casser si elle tourne sans arrêt.",
          DialogueId = 80150236,
          FacialId = {
            [1] = "790044:None"
          },
          GUID = "C8A5D018",
          NextDialogue = 80150237,
          Scripts = "PlayAnimation{_delay{1},ActorId{790008},AnimationId{\"Talk02_Start\"},Duration{1}}",
          SpeakNpcId = 790008,
          Subtitle = "Of course. Even machines break down if they're running non-stop.",
          TalkActionId = {
            [1] = "790008:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5D018"
        },
        [80150237] = {
          ContentFR = "Essaie de savourer ce moment. Peut-être que c’est en faisant une pause que tu découvriras, sans t’en rendre compte, ce que tu cherches vraiment. Ce ne sera pas un but imposé par les autres, mais un but que tu te fixes toi-même.",
          DialogueId = 80150237,
          GUID = "C8A5D042",
          NextDialogue = 80150238,
          SpeakNpcId = 790008,
          Subtitle = "I think you should try to enjoy this little \"pit stop.\" Maybe, in doing so, you'll naturally find what your true purpose is, and understand what it really means to move forward — not towards a goal someone else sets for you, but one that you set for yourself.",
          TalkActionId = {
            [1] = "790008:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5D042"
        },
        [80150238] = {
          Camera = "37.151489,10.179688,162.34816,0.00138,-13.798518,160.361816,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "... D’accord. Je te crois.",
          DialogueId = 80150238,
          FacialId = {
            [1] = "790044:Confident01"
          },
          GUID = "C8A5D06C",
          NextDialogue = 80150239,
          SpeakNpcId = 790044,
          Subtitle = "...Alright. I believe you.",
          TalkActionId = {
            [1] = "790044:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5D06C"
        },
        [80150239] = {
          Camera = "701.533142,-19.678223,342.430603,0.001379,-20.598722,179.159149,35.000008,291.99585,false,DoNotOverride,15.0",
          ContentFR = "Alors c’est décidé. À partir d’aujourd’hui, je vais sérieusement... \"m’arrêter\". Et tester les métiers... dans l’ordre alphabétique.",
          DialogueId = 80150239,
          FinalCamera = "750.443481,-20.394043,360.815552,0.001379,-20.598722,179.159149,35.000008,291.99585,false,DoNotOverride,15.0",
          GUID = "C8A5D096",
          NextDialogue = 80150240,
          SpeakNpcId = 790044,
          Subtitle = "Okay... it's settled then! Starting today, I'll follow your advice. I'll take it slow and try out all those jobs, one by one... alphabetically.",
          TalkActionId = {
            [1] = "790044:Angry01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5D096"
        },
        [80150240] = {
          Camera = "-70.064331,125.332031,101.724655,0.000002,6.400775,-59.833042,30.0,211.591843,false,Manual,5.0",
          ContentFR = "... Ce n’était pas ce que je voulais dire !",
          DialogueId = 80150240,
          FacialId = {
            [1] = "790008:Ahaha02"
          },
          FinalCamera = "-70.064331,125.332031,101.724655,0.000003,6.400775,-59.833019,32.0,211.591843,false,Manual,5.0",
          GUID = "C8A5D0C0",
          SpeakNpcId = 790008,
          Subtitle = "...That's not what \"taking it slow\" means!",
          TalkActionId = {
            [1] = "790008:Sigh_Start"
          },
          ToFinalCameraBlendTime = 3.5,
          VoiceName = "voice/$Locale$/inv/Lise/002/C8A5D0C0"
        },
        [80150301] = {
          Camera = "378.598389,-357.041016,313.750732,0.000139,-24.203033,136.98111,20.0,100000.0,false,DoNotOverride,3.0",
          ContentFR = "C’est l’heure du rendez-vous avec Rhythm, mais elle est introuvable.",
          DialogueId = 80150301,
          GUID = "C8A5DAC2",
          IsBlack = 1,
          NextDialogue = 80150302,
          Subtitle = "(It's the time you and Rhythm were supposed to meet, but she's nowhere in sight.)",
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DAC2"
        },
        [80150302] = {
          ContentFR = "Tu vérifies l’heure une nouvelle fois et regardes autour de toi, sûre qu’elle est en retard, ce n’est pas dans ses habitudes. Alors que tu commences à t’inquiéter, un son d’harmonica flotte jusqu’à toi par la fenêtre.",
          DialogueId = 80150302,
          GUID = "C8A5DAEC",
          IsBlack = 1,
          NextDialogue = 80150303,
          Subtitle = "(You check the time again and scan the surroundings, realising she's unusually late. Just as you begin to worry if something has happened to her, the sound of a harmonica drifts in through the window.)",
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DAEC"
        },
        [80150303] = {
          ContentFR = "♪—♪——",
          DialogueId = 80150303,
          GUID = "C8A5DB16",
          IsBlack = 1,
          NextOptions = {
            [1] = 801503031
          },
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_kouqin\"},EventKey{\"yaoyue_kouqin\"},PlayAs2D{true}}",
          SpeakNpcId = 790044,
          Subtitle = "♪—♪——",
          TalkActionId = {
            [1] = "790044:Lise_Sing_Start"
          },
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DB16"
        },
        [80150304] = {
          Camera = "-162.97998,-47.925293,139.780518,0.000136,-4.003618,17.769627,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "Ah... c’est moi. Désolée pour le retard.",
          DialogueId = 80150304,
          FacialId = {
            [1] = "790044:Ahaha01"
          },
          GUID = "C8A5DB40",
          NextDialogue = 80150305,
          Scripts = [[
SEQ{
StopNormalSound{EventKey{"yaoyue_kouqin"}},
PlayAnimation{_delay{1.5},ActorId{790044},AnimationId{"ScratchHead_Start"},Duration{1}}
}]],
          SpeakNpcId = 790044,
          Subtitle = "Ah... yes. Sorry I'm late.",
          TalkActionId = {
            [1] = "790044:Lise_Sing_End"
          },
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DB40"
        },
        [80150305] = {
          Camera = "15.73584,-25.139648,130.758057,0.000128,5.396846,161.76976,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "Tu jouais de l’harmonica tout à l’heure ? C’est rare de te voir faire ça.",
          DialogueId = 80150305,
          FacialId = {
            [1] = "790008:Shock01"
          },
          GUID = "C8A5DB6A",
          NextDialogue = 80150306,
          SpeakNpcId = 790008,
          Subtitle = "Were you playing the harmonica just now? That was a rare scene.",
          TalkActionId = {
            [1] = "790044:ScratchHead_End"
          },
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DB6A"
        },
        [80150306] = {
          Camera = "-162.97998,-47.925293,139.780518,0.000136,-4.003618,17.769627,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "Euh... Tu te souviens quand tu m’as dit de chercher « ce que je veux vraiment faire » ?",
          DialogueId = 80150306,
          FacialId = {
            [1] = "790044:Confident01",
            [2] = [[

790008:None]]
          },
          GUID = "C8A5DB94",
          NextDialogue = 80150307,
          SpeakNpcId = 790044,
          Subtitle = "Well... remember when you told me to try and find \"what I truly want to do\"?",
          TalkActionId = {
            [1] = "790044:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DB94"
        },
        [80150307] = {
          Camera = "-64.259766,-53.155762,98.869629,0.000149,12.995964,23.367174,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "J’ai pensé que c’était compliqué de trouver ça comme ça, sans réfléchir, alors j’ai décidé de commencer par ce que je connais... comme jouer de l’harmonica.",
          DialogueId = 80150307,
          FacialId = {
            [1] = "790044:Think01"
          },
          FinalCamera = "-64.259766,-53.155762,98.869629,0.000149,12.995951,23.367155,36.0,100000.0,false,DoNotOverride,3.0",
          GUID = "C8A5DBBE",
          NextDialogue = 80150308,
          SpeakNpcId = 790044,
          Subtitle = "I thought it would be hard to just \"find\" something out of thin air, so I decided to start with something I'm familiar with... like playing the harmonica.",
          TalkActionId = {
            [1] = "790044:Think_Start"
          },
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DBBE"
        },
        [80150308] = {
          Camera = "-333.883301,-207.240234,206.4021,0.000138,-13.203909,33.370224,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "Je ne suis pas très douée en musique, mais j’aimerais la comprendre un peu mieux. J’ai choisi un nouveau morceau. Le libraire m’a dit que c’était une chanson qui célèbre le printemps et l’espoir.",
          DialogueId = 80150308,
          FinalCamera = "-330.20752,-212.821289,206.4021,0.000139,-13.403891,33.770519,35.000008,100000.0,false,DoNotOverride,3.0",
          GUID = "C8A5DBE8",
          NextDialogue = 80150309,
          SpeakNpcId = 790044,
          Subtitle = "I'm not particularly good with music, but I want to understand it better. I picked a new song to learn. The owner of the second-hand bookstore said it's a piece about spring and hope.",
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DBE8"
        },
        [80150309] = {
          Camera = "19.719727,-47.332031,127.602783,0.000157,6.795505,151.16304,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "J’avais envie de te la jouer, mais je ne suis pas encore très sûre de moi, alors j’ai voulu m’entraîner dehors un peu avant...",
          DialogueId = 80150309,
          FacialId = {
            [1] = "790044:Doubt01"
          },
          FinalCamera = "19.719727,-47.332031,127.602783,0.000157,6.795505,151.16304,37.0,100000.0,false,DoNotOverride,3.0",
          GUID = "C8A5DC12",
          NextOptions = {
            [1] = 801503091,
            [2] = 801503092
          },
          SpeakNpcId = 790044,
          Subtitle = "I wanted to play it for you, but... I'm still a little unsure of myself. So, I thought I'd practice outside first...",
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DC12"
        },
        [80150310] = {
          Camera = "-112.624023,-27.073242,130.754395,0.000127,0.396267,16.373621,35.000008,186.892487,false,Manual,5.0",
          ContentFR = "Merci...",
          DialogueId = 80150310,
          FacialId = {
            [1] = "790044:Smile01"
          },
          GUID = "C8A5DC3C",
          NextDialogue = 80150311,
          SpeakNpcId = 790044,
          Subtitle = "Thank you...",
          TalkActionId = {
            [1] = "790044:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DC3C"
        },
        [80150311] = {
          ContentFR = "Tu sais, mon prénom signifie « rythme ».",
          DialogueId = 80150311,
          GUID = "C8A5DC66",
          NextDialogue = 80150312,
          SpeakNpcId = 790044,
          Subtitle = "Did you notice that my brother's name and mine both have something to do with music?",
          TalkActionId = {
            [1] = "790044:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DC66"
        },
        [80150312] = {
          Camera = "-275.132812,-182.827148,169.665527,0.000138,-8.603729,34.369663,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "Mes parents y ont vraiment réfléchi, j’aime beaucoup ce nom. Mais malheureusement, je suis naturellement maladroite avec la musique. J’ai l’impression de gâcher ce beau prénom...",
          DialogueId = 80150312,
          FinalCamera = "-285.81543,-190.133301,177.608398,0.00014,-9.803801,34.369843,35.000008,100000.0,false,DoNotOverride,3.0",
          GUID = "C8A5DC90",
          NextDialogue = 80150313,
          SpeakNpcId = 790044,
          Subtitle = "My parents put a lot of thought into our names. I really like them. But the truth is, I'm not exactly good with music. I feel like I've wasted such a beautiful name...",
          TalkActionId = {
            [1] = "790044:ConfidentLToTalk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DC90"
        },
        [80150313] = {
          Camera = "619.86084,-362.304688,120.789062,0.000158,-3.203878,149.565842,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "Le seul morceau que je peux jouer en entier, c’est « Requiem pour les sans-noms ». Je m’en souviens parce que Blues le jouait en boucle à côté de moi.",
          DialogueId = 80150313,
          FinalCamera = "619.86084,-362.304688,144.250488,0.000159,-5.003967,149.765717,35.000008,100000.0,false,DoNotOverride,3.0",
          GUID = "C8A5DCBA",
          NextDialogue = 80150314,
          SpeakNpcId = 790044,
          Subtitle = "The only piece I can play all the way through is Requiem for the Nameless. And the only reason I can do that is because Blues used to play it over and over in my ear.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DCBA"
        },
        [80150314] = {
          Camera = "141.552734,-26.657715,132.482422,0.000145,0.396588,168.366455,50.0,213.991577,false,Manual,6.0",
          ContentFR = "Pour être honnête, je ne comprends rien aux partitions. Je me contente d’associer les notes aux trous de l’harmonica et de mémoriser les mouvements... C’est surtout une question de mémoire musculaire.",
          DialogueId = 80150314,
          FacialId = {
            [1] = "790044:Sad01"
          },
          FinalCamera = "141.041504,-29.135254,132.482422,0.000145,0.396588,168.366455,50.0,213.991577,false,Manual,6.0",
          GUID = "C8A5DCE4",
          NextOptions = {
            [1] = 801503141,
            [2] = 801503142
          },
          SpeakNpcId = 790044,
          Subtitle = "Honestly, I don't even understand the sheet music. I just memorised the positions of the holes on the harmonica and how they should be played. It's all about muscle memory, really...",
          TalkActionId = {
            [1] = "790044:Talk01_End",
            [2] = [[

790008:Think_Start]]
          },
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DCE4"
        },
        [80150315] = {
          Camera = "-50.819824,-10.924316,129.908691,0.000116,2.996124,7.37299,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "Entendre ça me rassure un peu.",
          DialogueId = 80150315,
          FacialId = {
            [1] = "790044:Smile01"
          },
          GUID = "C8A5DD0E",
          NextDialogue = 80150316,
          SpeakNpcId = 790044,
          Subtitle = "Well, I'm a bit relieved hearing you say that.",
          TalkActionId = {
            [1] = "790044:Explain02_Start",
            [2] = [[

790008:Think_End]]
          },
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DD0E"
        },
        [80150316] = {
          Camera = "460.504395,-291.947754,239.943115,0.000159,-14.603743,146.764069,35.0,213.991577,false,DoNotOverride,6.0",
          ContentFR = "Puisque tu es là, j’ai une faveur à te demander... Pourrais-tu chanter la mélodie pendant que je joue ? Comme ça, je saurai si je suis juste.",
          DialogueId = 80150316,
          FinalCamera = "460.504395,-291.947754,215.802734,0.00016,-13.203704,146.76355,35.0,213.991577,false,DoNotOverride,6.0",
          GUID = "C8A5DD38",
          NextOptions = {
            [1] = 801503161,
            [2] = 801503162
          },
          SpeakNpcId = 790044,
          Subtitle = "While I have you, I have a favour to ask... Would you mind singing the melody while I play? That way, I'll know if I'm getting it right.",
          TalkActionId = {
            [1] = "790044:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DD38"
        },
        [80150317] = {
          Camera = "-178.790039,-52.550781,147.112793,0.000133,-5.203948,18.972607,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "Alors, je compte sur toi.",
          DialogueId = 80150317,
          GUID = "C8A5DD62",
          NextDialogue = 80150319,
          SpeakNpcId = 790044,
          Subtitle = "Thank you! Let's give it a try.",
          TalkActionId = {
            [1] = "790044:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DD62"
        },
        [80150318] = {
          Camera = "-178.790039,-52.550781,147.112793,0.000133,-5.203948,18.972607,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "Ce n’est pas grave, on va apprendre ensemble alors.",
          DialogueId = 80150318,
          GUID = "C8A5DD8C",
          NextDialogue = 80150319,
          SpeakNpcId = 790044,
          Subtitle = "That's okay. We'll figure it out together.",
          TalkActionId = {
            [1] = "790044:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DD8C"
        },
        [80150319] = {
          Camera = "-548.878906,-136.409668,668.428467,5.000547,-47.202866,15.77405,25.0,100000.0,false,DoNotOverride,5.0",
          ContentFR = "Sous le regard encourageant de Rhythm, tu commences à fredonner doucement la mélodie en suivant la partition.",
          DialogueId = 80150319,
          FinalCamera = "-559.611816,50.6875,643.750977,-0.0,-45.602726,-5.025548,25.0,100000.0,false,DoNotOverride,5.0",
          GUID = "C8A5DDB6",
          NextDialogue = 80150320,
          Subtitle = "(Under Rhythm's encouraging gaze, you start humming the melody of the song slowly, following the sheet music.)",
          TalkActionId = {
            [1] = "790008:Explain02_Start",
            [2] = [[

790044:Talk02_End]]
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DDB6"
        },
        [80150320] = {
          Camera = "162.047363,487.058594,377.543457,0.000115,-29.804956,-110.623787,25.0,638.752747,false,Manual,1.2",
          ContentFR = "Elle lève son harmonica, joue maladroitement quelques notes en suivant ton chant. Après votre duo, elle rejoue le morceau toute seule.",
          DialogueId = 80150320,
          FinalCamera = "171.548828,483.431641,377.543457,0.000112,-30.004972,-111.623634,25.0,638.752747,false,Manual,1.2",
          GUID = "C8A5DDE0",
          NextDialogue = 80150321,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_kouqin\"},EventKey{\"yaoyue_kouqin\"},PlayAs2D{true}}",
          Subtitle = "(She raises the harmonica to her lips and, despite a slight clumsiness, tries to play along with you. After your duet ends, she plays the song once more on her own.)",
          TalkActionId = {
            [1] = "790044:Lise_Sing_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DDE0"
        },
        [80150321] = {
          Camera = "-62.52002,52.065918,137.690918,0.000125,-1.003751,-20.827768,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "Mmmh... La hauteur des notes est à peu près correcte, mais le rythme est complètement à côté. Quand je me concentre sur les notes, je perds le tempo. Je vais devoir m’entraîner encore...",
          DialogueId = 80150321,
          FacialId = {
            [1] = "790044:Think01"
          },
          FinalCamera = "-54.942383,49.181641,137.548828,0.000125,-0.803742,-20.827745,35.000008,100000.0,false,DoNotOverride,3.0",
          GUID = "C8A5DE0A",
          NextDialogue = 80150322,
          Scripts = "StopNormalSound{EventKey{\"yaoyue_kouqin\"}}",
          SpeakNpcId = 790044,
          Subtitle = "Hmm... The pitch is okay, but the rhythm is all over the place. Once I focus on the pitch, it's hard to keep the rhythm steady. I guess I'll need more practice...",
          TalkActionId = {
            [1] = "790044:Lise_Sing_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DE0A"
        },
        [80150322] = {
          Camera = "139.77832,42.777832,138.025635,0.000151,-2.403414,-164.424194,35.000011,216.461411,false,Manual,3.0",
          ContentFR = "Honnêtement, je trouvais que ta version sonnait bien.",
          DialogueId = 80150322,
          FacialId = {
            [1] = "790008:Smile01",
            [2] = [[

790044:None]]
          },
          FinalCamera = "139.365234,44.257812,138.025635,0.000151,-2.403414,-164.424194,35.000011,216.461411,false,Manual,3.0",
          GUID = "C8A5DE34",
          NextDialogue = 80150323,
          SpeakNpcId = 790008,
          Subtitle = "I thought it sounded pretty good, honestly.",
          TalkActionId = {
            [1] = "790008:Explain02_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DE34"
        },
        [80150323] = {
          ContentFR = "Ce n’est pas grave si le rythme déraille, ce n’est pas un examen. La musique, c’est fait pour être libre.",
          DialogueId = 80150323,
          GUID = "C8A5DE5E",
          NextDialogue = 80150324,
          SpeakNpcId = 790008,
          Subtitle = "It's okay if the rhythm's off. This is not an exam. Besides, music is supposed to be free of restrictions.",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DE5E"
        },
        [80150324] = {
          Camera = "38.568848,23.305664,122.765625,0.000132,6.796339,-167.826828,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "Je pense que ton prénom, « Rhythm », veut dire un peu la même chose... Ce n’est pas que tu dois vivre selon un rythme imposé, mais que tu trouves le tien, à toi.",
          DialogueId = 80150324,
          FacialId = {
            [1] = "790008:Smile02"
          },
          FinalCamera = "38.568848,23.305664,122.765625,0.000139,6.796339,-167.826813,37.0,100000.0,false,DoNotOverride,3.0",
          GUID = "C8A5DE88",
          NextDialogue = 80150325,
          SpeakNpcId = 790008,
          Subtitle = "I think your name, \"Rhythm,\" carries the same meaning. It's not about living your life according to some fixed \"beat,\" but about finding your own rhythm.",
          ToFinalCameraBlendTime = 11,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DE88"
        },
        [80150325] = {
          Camera = "-167.373047,41.786133,148.665527,0.000146,-6.203799,-14.629342,35.0,245.243332,false,Manual,5.0",
          ContentFR = "Alors, tu n’as pas à être toujours aussi tendue, à te surcharger. Vis un peu plus librement, décide toi-même quand avancer, quand t’arrêter. Quel est ton propre « rythme », Rhythm ? Je crois qu’une fois que tu maîtriseras vraiment ce morceau, tu comprendras.",
          DialogueId = 80150325,
          GUID = "C8A5DEB2",
          NextDialogue = 80150326,
          SpeakNpcId = 790008,
          Subtitle = "So, you don't have to be so tense all the time, always keeping yourself busy. Live freely — decide for yourself when to move forward, and when to take a break. What is your own \"rhythm,\" Rhythm? I think once you really get the hang of this piece, you'll see what I mean.",
          TalkActionId = {
            [1] = "790008:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DEB2"
        },
        [80150326] = {
          Camera = "244.240723,98.888672,201.875,0.000206,-16.603704,-157.425842,35.000008,334.226532,false,Manual,5.0",
          ContentFR = "Pour bien jouer ce morceau, il faut du temps pour pratiquer, pour apprendre d’autres chansons, il faudra retourner à la librairie, et si tu veux partager ce printemps et cet espoir, il faudra les jouer pour d’autres.",
          DialogueId = 80150326,
          FacialId = {
            [1] = "790008:None"
          },
          FinalCamera = "247.649902,90.350098,201.875,0.000204,-16.203674,-160.425781,35.000008,334.226532,false,Manual,5.0",
          GUID = "C8A5DEDC",
          NextDialogue = 80150327,
          SpeakNpcId = 790008,
          Subtitle = "To master this song, you'll need to practice. To learn more songs, you may have to visit the bookstore again. And if you wish to share the spirit of spring and hope with others, you'll need to play it for them.",
          TalkActionId = {
            [1] = "790008:Explain01_Start"
          },
          ToFinalCameraBlendTime = 14,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DEDC"
        },
        [80150327] = {
          Camera = "66.17334,44.016113,92.894775,5.000216,15.596025,-162.825012,35.0,141.857666,false,Manual,3.0",
          ContentFR = "Il n’y a pas de calendrier pour ça. C’est toi qui décides quand faire ces choses, selon ton humeur. Et ces hauts et bas, c’est ton propre « rythme ».",
          DialogueId = 80150327,
          FinalCamera = "66.17334,44.016113,92.894775,5.000216,15.596025,-162.825012,35.0,141.857666,false,Manual,3.0",
          GUID = "C8A5DF06",
          NextDialogue = 80150328,
          SpeakNpcId = 790008,
          Subtitle = "There's no set schedule for when to do these things. It's all up to you. You can do them whenever you feel like it. And what you feel like doing — or not doing — that's your \"rhythm.\"",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DF06"
        },
        [80150328] = {
          Camera = "140.223633,32.546387,132.494873,0.000125,0.796605,-167.824188,55.0,206.818161,false,Manual,6.0",
          ContentFR = "Et si jamais tu as besoin d’aide pour la lecture des partitions... je suis toujours là.",
          DialogueId = 80150328,
          FinalCamera = "139.521973,35.797363,132.494873,0.000125,0.796605,-167.024063,55.0,206.818161,false,Manual,6.0",
          GUID = "C8A5DF30",
          NextDialogue = 80150329,
          SpeakNpcId = 790008,
          Subtitle = "Of course, if you ever need someone to help you with the sheet music... I'm always here.",
          TalkActionId = {
            [1] = "790008:Explain01_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DF30"
        },
        [80150329] = {
          Camera = "-7.366699,20.205078,123.453613,0.000125,11.996175,-13.829354,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "{nickname}...",
          DialogueId = 80150329,
          FacialId = {
            [1] = "790044:Shock01"
          },
          GUID = "C8A5DF5A",
          NextDialogue = 80150330,
          SpeakNpcId = 790044,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DF5A"
        },
        [80150330] = {
          Camera = "-169.143555,52.443359,147.212646,0.000124,-5.404018,-18.232069,35.000008,100000.0,false,DoNotOverride,3.0",
          ContentFR = "Merci. C’est la plus belle interprétation de mon prénom que j’ai jamais entendue.",
          DialogueId = 80150330,
          FacialId = {
            [1] = "790044:Happy01"
          },
          FinalCamera = "-168.707031,53.768555,147.212646,0.000124,-5.404018,-18.832098,35.000008,100000.0,false,DoNotOverride,3.0",
          GUID = "C8A5DF84",
          NextDialogue = 80150331,
          SpeakNpcId = 790044,
          Subtitle = "Thank you. That's the most beautiful interpretation of my name I've ever heard.",
          TalkActionId = {
            [1] = "790044:Explain02_Start"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DF84"
        },
        [80150331] = {
          Camera = "7.588379,267.65625,167.518799,0.00021,-12.203245,-91.424835,25.0,260.775696,false,Manual,1.2",
          ContentFR = "Je garderai tes paroles précieusement.",
          DialogueId = 80150331,
          FinalCamera = "7.588379,267.65625,174.300049,0.000211,-14.003322,-91.624878,25.0,260.775696,false,Manual,1.2",
          GUID = "C8A5DFAE",
          NextDialogue = 80150332,
          SpeakNpcId = 790044,
          Subtitle = "I'll always remember your kind words.",
          TalkActionId = {
            [1] = "790044:AgreeHead"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DFAE"
        },
        [80150332] = {
          Camera = "-8.575684,5.778809,133.86499,0.000219,2.596681,-3.625247,25.0,73.127831,false,Manual,5.0",
          ContentFR = "Si tu acceptes mes maladresses et veux être témoin de ma transformation... Je te promets que dès que je trouverai mon propre « rythme », tu seras {性别:le premier|la première} à le savoir.",
          DialogueId = 80150332,
          FinalCamera = "-8.575684,5.778809,133.86499,0.000219,2.596688,-3.625247,28.0,73.127831,false,Manual,5.0",
          GUID = "C8A5DFD8",
          SpeakNpcId = 790044,
          Subtitle = "If you don't mind bearing with my clumsiness and would like to witness my change... I promise you this: once I find my own \"rhythm,\" I'll share it with you first, before anyone else.",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/inv/Lise/003/C8A5DFD8"
        },
        [80160001] = {
          ContentFR = "J’espère que tu sauras me satisfaire.",
          DialogueId = 80160001,
          GUID = "C8AC122A",
          SpeakNpcId = 790055,
          Subtitle = "Let's hope your drink won't disappoint me.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC122A"
        },
        [80160101] = {
          Camera = "151.585999,-190.824707,95.898872,0.000003,1.80011,-153.390167,39.474983,223.616684,false,Manual,2.8",
          ContentFR = "C’est un endroit plutôt calme.",
          DialogueId = 80160101,
          Duration = 1,
          GUID = "C8AC2292",
          NextDialogue = 80160102,
          Scripts = "MoveTo{ActorId{790055},TargetPoint{\"Move_320101\"},MoveSpeed{80},Visibility{\"Show\"}}",
          SpeakNpcId = 790055,
          Subtitle = "A quiet place indeed.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2292"
        },
        [80160102] = {
          Camera = "-31.074158,-13.146484,130.436157,0.000003,0.199305,-130.376617,28.875509,223.616684,false,Manual,2.8",
          ContentFR = "Donne-moi un verre, s’il te plaît.",
          DialogueId = 80160102,
          Duration = 3,
          GUID = "C8AC22BC",
          LookAt = {
            [1] = "790055:n(790008)"
          },
          NextOptions = {
            [1] = 801601021,
            [2] = 801601022
          },
          SpeakNpcId = 790055,
          Subtitle = "I'll have a drink, please.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC22BC"
        },
        [80160103] = {
          ContentFR = "Au nord de Givrelac, il y a une maison où se trouvent un piano, une enclume et un sablier. Là-bas, {性别:un|une} hôte reçoit ses amis avec des breuvages faits maison. {性别:Il|Elle} aime aussi écouter ceux qui viennent sans mauvaises intentions.",
          DialogueId = 80160103,
          Duration = 3,
          GUID = "C8AC22E6",
          NextDialogue = 80160104,
          SpeakNpcId = 790055,
          Subtitle = "Up north in Icelake, there's a house with a piano, an anvil, and an hourglass. The lodger there entertains friends with homemade drinks — and is always happy to befriend strangers who mean no harm.",
          TalkActionId = {
            [1] = "790055:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC22E6"
        },
        [80160104] = {
          ContentFR = "« Là où je peux boire tranquillement, sans être dérangée. »",
          DialogueId = 80160104,
          Duration = 3,
          GUID = "C8AC2310",
          NextDialogue = 80160105,
          SpeakNpcId = 790055,
          Subtitle = "\"A place where you can drink in peace. Unbothered.\"",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2310"
        },
        [80160105] = {
          ContentFR = "C’est ce que m’a dit Camilla Scarlet, des Asphodèles. Elle mentirait, selon toi ?",
          DialogueId = 80160105,
          Duration = 3,
          GUID = "C8AC233A",
          NextOptions = {
            [1] = 801601071
          },
          SpeakNpcId = 790055,
          Subtitle = "That's what Camilla Scarlet of the Asphodel told me. Was she lying?",
          TalkActionId = {
            [1] = "790055:Talk01_Loop"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC233A"
        },
        [80160106] = {
          ContentFR = "Tu veux dire les Asphodèles, de Camilla Scarlet ? En fait, c’est elle qui m’a envoyée ici.",
          DialogueId = 80160106,
          Duration = 3,
          GUID = "C8AC2364",
          NextDialogue = 80160107,
          SpeakNpcId = 790055,
          Subtitle = "The Asphodel, you mean. Camilla Scarlet's establishment. Actually, she's the one who sent me here.",
          TalkActionId = {
            [1] = "790055:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2364"
        },
        [80160107] = {
          ContentFR = "Ses boissons peuvent rivaliser avec celles de la capitale, l’endroit est toujours bondé. Mais aujourd’hui, je cherche un peu de calme, un lieu où je peux baisser ma garde et boire tranquillement.",
          DialogueId = 80160107,
          Duration = 3,
          GUID = "C8AC238E",
          NextOptions = {
            [1] = 801601071
          },
          SpeakNpcId = 790055,
          Subtitle = "Her drinks could rival those of the finest taverns in the capital — it's no wonder the place is always packed. But today, I seek peace. A place where I can lower my guard.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC238E"
        },
        [80160108] = {
          ContentFR = "C’est ma peau rouge ou mon arme qui t’inquiètent ? Détends-toi, Camilla m’a donné ce papier, c’est pour toi.",
          DialogueId = 80160108,
          Duration = 3,
          GUID = "C8AC23B8",
          NextDialogue = 80160109,
          Scripts = "PlayAnimation{_delay{2},ActorId{790055},AnimationId{\"Talk02_Start\"},Duration{1}}",
          SpeakNpcId = 790055,
          Subtitle = "Is it the colour of my skin or the weapon in my hand that unsettles you? Relax. She gave me this. It's for you.",
          TalkActionId = {
            [1] = "790055:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC23B8"
        },
        [80160109] = {
          ContentFR = "« Prends soin de cette invitée. Le paiement t’attendra demain aux Asphodèles. »",
          DialogueId = 80160109,
          Duration = 3,
          GUID = "C8AC23E2",
          IsBlack = 1,
          Subtitle = "\"Take good care of this guest. Payment will be ready at The Asphodel tomorrow.\"",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC23E2"
        },
        [80160110] = {
          Camera = "-147.684692,-116.645508,164.708984,0.000248,-3.398497,41.200367,42.28323,451.476898,false,DoNotOverride,10.496961",
          ContentFR = "<I>Soupir...</> Honnêtement, je n’ai aucune envie de vous refuser l’entrée. Fâcher une personnalité de votre rang ne me serait d’aucun avantage.",
          DialogueId = 80160110,
          Duration = 5,
          GUID = "C8AC240C",
          NextDialogue = 80160111,
          SpeakNpcId = 790052,
          Subtitle = "*sigh* ...Believe me, I've no wish to turn you away. Offending someone of your standing would do me no good at all.",
          TalkActionId = {
            [1] = "790052:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC240C"
        },
        [80160111] = {
          Camera = "359.205933,-102.777344,311.273438,0.000032,-20.600035,174.999359,25.177044,203.023346,false,Manual,5.70148",
          ContentFR = "Je ne suis venue ni avec des gardes, ni en faisant de bruit. Si vous m’avez reconnue malgré tout, alors j’estime avoir au moins mérité un verre ici.",
          DialogueId = 80160111,
          Duration = 5,
          FinalCamera = "359.205933,-102.777344,276.765625,0.000032,-20.600035,174.999359,25.177044,203.023346,false,Manual,5.70148",
          GUID = "C8AC2436",
          NextDialogue = 80160112,
          SpeakNpcId = 790055,
          Subtitle = "I came without escort and kept my route quiet. If you recognised me regardless — then at the very least, I deserve a drink.",
          TalkActionId = {
            [1] = "790055:Talk03_Start",
            [2] = "790052:Talk01_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2436"
        },
        [80160112] = {
          Camera = "-310.237366,-391.768555,153.707031,0.000077,-1.999442,56.994724,43.855331,203.023346,false,Manual,5.70148",
          ContentFR = "De la frontière sud, là où l’Empire touche Élysium, jusqu’aux Monts Vidofnir au nord, votre nom est sur toutes les lèvres.",
          DialogueId = 80160112,
          Duration = 5,
          GUID = "C8AC2460",
          NextDialogue = 80160113,
          SpeakNpcId = 790052,
          Subtitle = "From the southern borders brushing Elysium to the Vidofnir Mountains in the far north — your name is known everywhere.",
          TalkActionId = {
            [1] = "790052:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2460"
        },
        [80160113] = {
          Camera = "14.798828,-154.951172,149.396484,0.000091,-9.39922,-174.809311,43.855331,203.023346,false,Manual,5.70148",
          ContentFR = "Et toutes les rumeurs parlent de votre peau flamboyante.",
          DialogueId = 80160113,
          Duration = 3,
          FinalCamera = "14.798828,-154.951172,177.433594,0.000091,-9.39922,-174.809311,43.855331,203.023346,false,Manual,5.70148",
          GUID = "C8AC248A",
          NextDialogue = 80160114,
          SpeakNpcId = 790052,
          Subtitle = "And every tale about you mentions your flame-red skin.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC248A"
        },
        [80160114] = {
          ContentFR = "Givrelac décline peut-être, mais c’est encore la plus grande ville du nord... Et moi, cela fait bien longtemps que je tiens cette taverne. Croyez-moi, reconnaître une légende n’a rien d’extraordinaire.",
          DialogueId = 80160114,
          Duration = 5,
          GUID = "C8AC24B4",
          NextDialogue = 80160115,
          SpeakNpcId = 790052,
          Subtitle = "Icelake may be fading, but it's still the North's largest city. And I, madam, have run this tavern long enough to know a legend when she walks in.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC24B4"
        }
      }
    end
  },
  {
    MinKey = 80160115,
    MaxKey = 80170150,
    Loader = function()
      return {
        [80160115] = {
          Camera = "263.591919,95.413086,166.505859,0.000114,-4.198818,-154.60791,49.593163,451.476898,false,DoNotOverride,10.496961",
          ContentFR = "Quelle corvée... Je pensais n’attirer que quelques regards curieux, pas être reconnue sur-le-champ dans un bar presque vide.",
          DialogueId = 80160115,
          Duration = 3,
          GUID = "C8AC24DE",
          NextDialogue = 80160116,
          SpeakNpcId = 790055,
          Subtitle = "How troublesome. I'd hoped to draw no more than a few curious glances — yet even in a near-empty bar, I am recognised at once.",
          TalkActionId = {
            [1] = "790055:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC24DE"
        },
        [80160116] = {
          Camera = "-318.082764,-391.271484,146.335938,0.000113,-0.998813,54.392494,49.593163,451.476898,false,DoNotOverride,10.496961",
          ContentFR = "Madame, vous avez sans doute trop fréquenté les prisonniers, vous semblez avoir oublié comment fonctionne le monde réel. Une taverne avec un seul client à cette heure aurait déjà mis la clé sous la porte.",
          DialogueId = 80160116,
          Duration = 3,
          GUID = "C8AC2508",
          NextDialogue = 80160117,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{3},TargetPosition{"-46.92395,-890.245117,476.808594,0.000107,-12.998778,134.186493,25.505644,451.476898,false,DoNotOverride,10.496961"},duration{0}},
CameraMoveTo{TargetPosition{"-46.92395,-890.245117,476.808594,0.000113,-11.398554,-178.21524,25.505644,451.476898,false,DoNotOverride,10.496961"},duration{40}}
}]],
          SpeakNpcId = 790052,
          Subtitle = "Ma'am, you must've spent so long among convicts you've forgotten how the real world works. A tavern with just one patron at this hour would've gone under long ago.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2508"
        },
        [80160117] = {
          ContentFR = "Regardez dehors, plusieurs personnes attendent, mais n’osent pas entrer. Visiblement, je ne suis pas la seule à vous avoir reconnue. Je vous servirais volontiers seule, mais si la rumeur court qu’une haute fonctionnaire de la capitale a monopolisé mon établissement... je ne pourrais rien faire contre ça.",
          DialogueId = 80160117,
          Duration = 5,
          GUID = "C8AC2532",
          NextDialogue = 80160118,
          SpeakNpcId = 790052,
          Subtitle = "Look beyond the door. You'll see them — folks loitering outside, too scared to step in. I'm not the only one who recognised you. I would gladly serve you alone, but if word gets out that a dignitary from the capital commandeered my bar for herself... Well, I doubt even I could sweep those rumours away.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2532"
        },
        [80160118] = {
          Camera = "393.698364,122.831055,270.308594,0.000183,-14.198112,-159.790924,28.136471,451.476898,false,DoNotOverride,10.496961",
          ContentFR = "Vous avez raison, attirer l’attention n’était pas dans mes intentions. Merci de m’avoir prévenue, même si je doute que votre geste soit purement désintéressé.",
          DialogueId = 80160118,
          Duration = 3,
          FinalCamera = "378.453979,117.220703,266.197266,0.000183,-14.198112,-159.790924,28.136471,451.476898,false,DoNotOverride,10.496961",
          GUID = "C8AC255C",
          NextDialogue = 80160119,
          SpeakNpcId = 790055,
          Subtitle = "You're not wrong. I had no intention of drawing attention. I appreciate the warning — though I doubt you're being helpful out of sheer goodwill.",
          TalkActionId = {
            [1] = "790055:Talk02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC255C"
        },
        [80160119] = {
          Camera = "-65.366943,-360.875,145.677734,0.000188,-1.99826,138.407349,28.136471,451.476898,false,DoNotOverride,10.496961",
          ContentFR = "Vulcera jette un regard perçant aux engrenages mécaniques incrustés dans la salle. Il est évident qu’elle devine un secret soigneusement dissimulé derrière cette façade.",
          DialogueId = 80160119,
          Duration = 3,
          GUID = "C8AC2586",
          LookAt = {
            [1] = "790055:p(Look_H)"
          },
          NextDialogue = 80160120,
          Subtitle = "(Hellfire's sharp gaze sweeps over the mechanical gears built into the tavern's hall. It's clear she senses the elaborate secrets hidden just beyond.)",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2586"
        },
        [80160120] = {
          Camera = "-75.942627,-56.601562,151.488281,0.000211,-2.598238,-139.994705,35.0,451.476898,false,DoNotOverride,10.496961",
          ContentFR = "Il y a quelque chose de caché là-dessous. C’est audacieux, de dissimuler un secret en pleine vue.",
          DialogueId = 80160120,
          Duration = 3,
          GUID = "C8AC25B0",
          LookAt = {
            [1] = "790055:n(790052)"
          },
          NextDialogue = 80160121,
          SpeakNpcId = 790055,
          Subtitle = "There's something hidden behind that panelling. Bold, hiding your secret right in plain sight. I rather admire that.",
          TalkActionId = {
            [1] = "790055:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC25B0"
        },
        [80160121] = {
          ContentFR = "Ou peut-être êtes-vous plus influente que je ne le pensais. Assez pour que les gens vous couvrent, en échange d’un bon verre, ou d’un moyen de survivre ici.",
          DialogueId = 80160121,
          Duration = 3,
          GUID = "C8AC25DA",
          NextDialogue = 80160122,
          SpeakNpcId = 790055,
          Subtitle = "Or perhaps you have more influence here than I assumed — enough to have people guard your secret, whether by a fine drink... or by offering them a way to survive in this city.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC25DA"
        },
        [80160122] = {
          Camera = "-59.147827,-133.68457,134.808594,0.000211,8.401542,69.408882,35.0,451.476898,false,DoNotOverride,10.496961",
          ContentFR = "Haha... Vous me flattez. Je ne suis qu’une humble tenancière qui n’oserait même pas avoir de retard sur ses impôts. Et puis, qui n’a pas un ou deux secrets ?",
          DialogueId = 80160122,
          Duration = 5,
          FacialId = {
            [1] = "790052:Smile01"
          },
          FinalCamera = "-46.137329,-99.043945,142.054688,0.000211,8.401542,69.408882,35.0,451.476898,false,DoNotOverride,10.496961",
          GUID = "C8AC2604",
          NextDialogue = 80160123,
          SpeakNpcId = 790052,
          Subtitle = "Heh... you flatter me, ma'am. I'm just a humble tavern keeper who'd never dare fall behind on her taxes. As for secrets — well, who doesn't have one or two?",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2604"
        },
        [80160123] = {
          ContentFR = "Un secret n’est pas toujours une lame bien affûtée. Parfois, c’est juste une vieille recette de jambon fumé transmise depuis trois générations. Si je ne vous l’ai pas encore servie, c’est simplement parce que je ne sais pas si elle vous plairait.",
          DialogueId = 80160123,
          Duration = 5,
          GUID = "C8AC262E",
          NextDialogue = 80160124,
          SpeakNpcId = 790052,
          Subtitle = "Besides, not every secret's dangerous. Sometimes, it's just something harmless — like an old family recipe for smoked ham. I haven't served it yet... only because I wasn't sure it would suit your palate.",
          TalkActionId = {
            [1] = "790052:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC262E"
        },
        [80160124] = {
          Camera = "-86.051514,-78.273438,146.841797,0.000205,-1.598749,-143.392212,35.0,451.476898,false,DoNotOverride,10.496961",
          ContentFR = "Intéressant... Un de mes lieutenants, expert en fouilles approfondies, aimait faire ce genre de plaisanterie.",
          DialogueId = 80160124,
          Duration = 3,
          GUID = "C8AC2658",
          NextDialogue = 80160125,
          SpeakNpcId = 790055,
          Subtitle = "Amusing. One of my lieutenants — an expert in \"thorough searches\" — used to crack jokes like that.",
          TalkActionId = {
            [1] = "790055:Confident_Start",
            [2] = "790052:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2658"
        },
        [80160125] = {
          ContentFR = "Ne vous en faites pas, Madame Scarlet.",
          DialogueId = 80160125,
          Duration = 3,
          GUID = "C8AC2682",
          NextDialogue = 80160126,
          SpeakNpcId = 790055,
          Subtitle = "Relax, Ms Scarlet.",
          TalkActionId = {
            [1] = "790055:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2682"
        },
        [80160126] = {
          Camera = "279.85791,105.764648,170.447266,0.000227,-3.998898,-152.592499,68.94529,451.476898,false,DoNotOverride,10.496961",
          ContentFR = "Ici, c’est les Asphodèles, pas un tribunal, encore moins la Prison Militaire Royale. Personne ne vous plantera de sérum de vérité dans le cou.",
          DialogueId = 80160126,
          Duration = 3,
          GUID = "C8AC26AC",
          NextDialogue = 80160127,
          SpeakNpcId = 790055,
          Subtitle = "This is your ground, not a courtroom — and certainly not the Royal Military Prison. No one here's going to jab a truth serum into your neck and drag a confession out of you.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC26AC"
        },
        [80160127] = {
          ContentFR = "Je suis venue à Givrelac pour mes raisons, et vous avez les vôtres. Inutile de perdre du temps à débattre de \"recettes de jambon\".",
          DialogueId = 80160127,
          Duration = 3,
          GUID = "C8AC26D6",
          NextDialogue = 80160128,
          SpeakNpcId = 790055,
          Subtitle = "I came to Icelake on my own business, and you have your way of keeping things running. Let's not waste time trading riddles about \"ham recipes.\"",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC26D6"
        },
        [80160128] = {
          ContentFR = "Cela étant dit, je vais vous laisser, avant que ma présence ne fasse fuir vos clients.",
          DialogueId = 80160128,
          GUID = "C8AC2700",
          NextDialogue = 80160129,
          Scripts = [[
SEQ{
LookAt{_delay{1},LookAtDescription{"790055:n(790055)"}},
TurnTo{TurnToDescription{"790055:p(-180)"}},
MoveTo{ActorId{790055},TargetPoint{"Move_H"},MoveSpeed{80},Visibility{"Show"}}
}]],
          SpeakNpcId = 790055,
          Subtitle = "With that settled, I'll step away before my presence drives off the rest of your patrons.",
          TalkActionId = {
            [1] = "790055:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2700"
        },
        [80160129] = {
          Camera = "-105.736328,-382.012695,149.125,0.000248,-3.398559,147.008057,39.565411,252.247864,false,Manual,2.892425",
          ContentFR = "Vous vous demandez peut-être pourquoi j’ai mentionné votre secret.",
          DialogueId = 80160129,
          Duration = 3,
          GUID = "C8AC272A",
          NextDialogue = 80160130,
          SpeakNpcId = 790055,
          Subtitle = "Perhaps you wonder why I bothered to remark upon your little secret.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC272A"
        },
        [80160130] = {
          ContentFR = "Ce n’était pas une menace. Appelez cela un réflexe professionnel, j’ai du mal à ignorer les mensonges ou les non-dits, surtout quand ils dansent juste sous mon nez.",
          DialogueId = 80160130,
          Duration = 5,
          GUID = "C8AC2754",
          LookAt = {
            [1] = "790055:n(790052)"
          },
          NextDialogue = 80160131,
          SpeakNpcId = 790055,
          Subtitle = "It wasn't meant as a threat. Call it a professional reflex — I find it hard to ignore lies and secrets that sit under my nose.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2754"
        },
        [80160131] = {
          ContentFR = "Dommage que je ne puisse pas boire un verre dans la meilleure taverne de Givrelac. Adieu.",
          DialogueId = 80160131,
          Duration = 3,
          GUID = "C8AC277E",
          LookAt = {
            [1] = "790055:n(790055)"
          },
          NextDialogue = 80160132,
          SpeakNpcId = 790055,
          Subtitle = "Pity I won't be able to enjoy a drink at Icelake's finest tavern. Farewell.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC277E"
        },
        [80160132] = {
          Camera = "-141.847046,-192.130859,169.498047,0.000235,-3.798828,56.604771,47.597221,451.476898,false,DoNotOverride,10.496961",
          ContentFR = "Ne partez pas si vite.",
          DialogueId = 80160132,
          Duration = 3,
          FacialId = {
            [1] = "790052:None"
          },
          GUID = "C8AC27A8",
          LookAt = {
            [1] = "790055:n(790052)"
          },
          NextDialogue = 80160133,
          SpeakNpcId = 790052,
          Subtitle = "A moment, if you please.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC27A8"
        },
        [80160133] = {
          Camera = "204.932251,65.897461,166.253906,0.000237,-5.198696,-153.398605,35.000008,451.476898,false,DoNotOverride,10.496961",
          ContentFR = "Oui ?",
          DialogueId = 80160133,
          Duration = 3,
          GUID = "C8AC27D2",
          LookAt = {
            [1] = "790055:n(790052)"
          },
          NextDialogue = 80160134,
          SpeakNpcId = 790055,
          Subtitle = "Yes?",
          TurnTo = {
            [1] = "790055:p(75)"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC27D2"
        },
        [80160134] = {
          Camera = "-146.874878,-117.574219,164.708984,0.000248,-3.398497,41.200367,42.28323,451.476898,false,DoNotOverride,10.496961",
          ContentFR = "Au nord de Givrelac, il y a une maison où se trouvent un piano, une enclume et un sablier. Là-bas, {性别:un|une} hôte reçoit ses amis avec des breuvages faits maison. {性别:Il|Elle} aime aussi écouter ceux qui viennent sans mauvaises intentions.",
          DialogueId = 80160134,
          Duration = 5,
          FinalCamera = "-117.245117,-91.633789,163.6875,0.000248,-3.398497,41.200367,42.28323,451.476898,false,DoNotOverride,10.496961",
          GUID = "C8AC27FC",
          NextDialogue = 80160135,
          SpeakNpcId = 790052,
          Subtitle = "Up north in Icelake, there's a house with a piano, an anvil, and an hourglass. The lodger there entertains friends with homemade drinks — and is always happy to befriend strangers who mean no harm.",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC27FC"
        },
        [80160135] = {
          ContentFR = "Si vous avez besoin de parler, {性别:il|elle} saura vous écouter. Avec ma recommandation, {性别:il|elle} ne vous refusera pas.",
          DialogueId = 80160135,
          Duration = 3,
          GUID = "C8AC2826",
          NextDialogue = 80160136,
          SpeakNpcId = 790052,
          Subtitle = "If ever you find yourself in need of someone to talk to, {性别：he|she} would be a good listener. Take this note — with it, you won't be turned away.",
          TalkActionId = {
            [1] = "790052:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2826"
        },
        [80160136] = {
          Camera = "209.813721,89.859375,159.263672,0.000217,-2.798328,-149.798874,61.554684,451.476898,false,DoNotOverride,10.496961",
          ContentFR = "Merci. Avec votre clairvoyance, vous pourriez viser bien plus haut que tenir une simple taverne dans une ville frontalière.",
          DialogueId = 80160136,
          Duration = 3,
          GUID = "C8AC2850",
          LookAt = {
            [1] = "790055:n(790052)"
          },
          NextDialogue = 80160137,
          SpeakNpcId = 790055,
          Subtitle = "My thanks. With such discernment, I daresay you're capable of far more than running a border-town tavern.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2850"
        },
        [80160137] = {
          Camera = "-246.633789,-309.449219,143.691406,0.00022,0.201757,52.802853,61.554684,451.476898,false,DoNotOverride,10.496961",
          ContentFR = "Et pourtant, la réalité nous emmène rarement là où nous l’espérions... Comme je n’aurais jamais cru qu’une geôlière puisse être une invitée aussi civilisée.",
          DialogueId = 80160137,
          Duration = 3,
          GUID = "C8AC287A",
          NextDialogue = 80160138,
          SpeakNpcId = 790052,
          Subtitle = "Reality rarely turns out the way we expect, does it? Much like how I never imagined the Warden of the Royal Military Prison would turn out to be such a courteous guest.",
          TalkActionId = {
            [1] = "790052:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC287A"
        },
        [80160138] = {
          ContentFR = "Pour certaines raisons, je ne me présenterai pas. Considère-moi comme une voyageuse fatiguée, accablée par les soucis, en quête d’un verre assez fort pour oublier ses peines, ne serait-ce qu’une heure.",
          DialogueId = 80160138,
          Duration = 5,
          GUID = "C8AC28A4",
          IsBlack = 1,
          SpeakNpcId = 790055,
          Subtitle = "For reasons I would rather not share, I won't be introducing myself. Just think of me as a weary traveller, laden with troubles, seeking a drink strong enough to drown them for an hour.",
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC28A4"
        },
        [80160201] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentFR = "...",
          DialogueId = 80160201,
          GUID = "C8AC32FA",
          NextOptions = {
            [1] = 801602011
          },
          SpeakNpcId = 93201,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC32FA"
        },
        [80160202] = {
          ContentFR = "Ce n’est rien. J’ai toute la nuit devant moi.",
          DialogueId = 80160202,
          GUID = "C8AC3324",
          NextDialogue = 80160203,
          SpeakNpcId = 93201,
          Subtitle = "Take your time. I've the whole night free.",
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3324"
        },
        [80160203] = {
          ContentFR = "Vu l’état des lieux, j’imagine que tu vis ici depuis un moment. Pourtant... tu sembles étrangement {性别:perdu|perdue} quand il s’agit de retrouver tes affaires.",
          DialogueId = 80160203,
          GUID = "C8AC334E",
          NextDialogue = 80160204,
          SpeakNpcId = 93201,
          Subtitle = "Judging by the state of things, I'd wager you've been living here for some time — yet you still seem oddly unfamiliar with where everything is.",
          TalkActionId = {
            [1] = "93201:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC334E"
        },
        [80160204] = {
          ContentFR = "Même en tant que simple locataire, je te conseille de passer un bon coup de balai dès que tu en auras l’occasion. Apprends à connaître chaque recoin. On ne sait jamais ce qui traîne dans une maison bon marché.",
          DialogueId = 80160204,
          GUID = "C8AC3378",
          NextOptions = {
            [1] = 801602041,
            [2] = 801602042
          },
          SpeakNpcId = 93201,
          Subtitle = "Even if you're only a tenant, I'd advise giving the place a proper sweep when you have the chance. Best to know what's tucked into every corner.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3378"
        },
        [80160205] = {
          ContentFR = "Disons que je parle d’expérience. J’ai visité bien des maisons avec ma plus fidèle collègue. Des \"foyers chaleureux\", en apparence.",
          DialogueId = 80160205,
          GUID = "C8AC33A2",
          NextDialogue = 80160206,
          SpeakNpcId = 93201,
          Subtitle = "Call it professional advice. I've toured more homes than I care to count with a trusted partner. And in those so-called \"sweet\" homes—",
          TalkActionId = {
            [1] = "93201:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC33A2"
        },
        [80160206] = {
          ContentFR = "Sous des pots de fleurs exotiques, on trouvait des charges explosives. Sous les journaux d’enfants, des registres de contrebandiers. Et dans une bouteille de vin soi-disant offerte avec le cœur... de quoi empoisonner tout un peloton.",
          DialogueId = 80160206,
          GUID = "C8AC33CC",
          NextOptions = {
            [1] = 801602061,
            [2] = 801602062
          },
          SpeakNpcId = 93201,
          Subtitle = "A flowerpot of rare blooms might be hiding a shaped charge; a child's diary, tucked in a drawer, could mask a smuggler's contact book; a bottle of wine offered as a gift might carry enough poison to kill a dozen men...",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC33CC"
        },
        [80160207] = {
          ContentFR = "Pas besoin de me regarder comme ça. Je partage juste quelques souvenirs. Surtout dans un endroit comme celui-ci, à bas loyer, loué à quelqu’un qui n’est pas d’ici... faut rester sur ses gardes.",
          DialogueId = 80160207,
          GUID = "C8AC33F6",
          NextDialogue = 80160208,
          SpeakNpcId = 93201,
          Subtitle = "No need for alarm. Just passing on a little field wisdom. Places like this — cheap, let to out-of-towners — often have a past. You'd do well to stay vigilant.",
          TalkActionId = {
            [1] = "93201:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC33F6"
        },
        [80160208] = {
          ContentFR = "Les propriétaires savent parler, mais pas un mot sur ce qui s’est passé entre ces murs. Et pourquoi c’est si peu cher ? Mystère.",
          DialogueId = 80160208,
          GUID = "C8AC3420",
          NextOptions = {
            [1] = 801602081,
            [2] = 801602082
          },
          SpeakNpcId = 93201,
          Subtitle = "Landlords are always quick to take your silver. As for what might have happened inside these walls before you arrived, and why the rent is such a bargain... that part's rarely on the lease.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3420"
        },
        [80160209] = {
          ContentFR = "Un conseil, sois {性别:attentif|attentive} à tout, sinon le changement te tombera dessus sans prévenir.",
          DialogueId = 80160209,
          GUID = "C8AC344A",
          NextDialogue = 80160210,
          SpeakNpcId = 93201,
          Subtitle = "Here's a free bit of advice: Pay close attention to everything around you — or danger will find you before you're ready.",
          TalkActionId = {
            [1] = "93201:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC344A"
        },
        [80160210] = {
          ContentFR = "Hélas... je suis mal placée pour prêcher cette prudence. Je n’en suis pas l’exemple.",
          DialogueId = 80160210,
          GUID = "C8AC3474",
          NextDialogue = 80160211,
          SpeakNpcId = 93201,
          Subtitle = "Easier said than done, of course. I'm not exactly a model of vigilance myself.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3474"
        },
        [80160211] = {
          ContentFR = "Ma partenaire était bien meilleure que moi pour dénicher la moindre anomalie. Elle avait l’œil. Et les mains. Elle repérait chaque piège, chaque nom caché, chaque flacon suspect.",
          DialogueId = 80160211,
          GUID = "C8AC349E",
          NextDialogue = 80160212,
          SpeakNpcId = 93201,
          Subtitle = "My partner was always sharper than me at spotting the hidden threads. Sharp eyes, deft hands — she spotted every clue the moment we walked in: shaped charges, smuggling ledgers, poisoned wine, you name it.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC349E"
        },
        [80160212] = {
          ContentFR = "Rien ne lui échappait.",
          DialogueId = 80160212,
          GUID = "C8AC34C8",
          NextDialogue = 80160213,
          SpeakNpcId = 93201,
          Subtitle = "Nothing ever escaped her eyes.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC34C8"
        },
        [80160213] = {
          ContentFR = "Elle était mes mains, littéralement. Les miennes... brûlent le papier, font fondre le verre. Je ne peux pas toujours examiner les preuves sans les détruire.",
          DialogueId = 80160213,
          GUID = "C8AC34F2",
          NextDialogue = 80160214,
          SpeakNpcId = 93201,
          Subtitle = "She was my right hand — not just metaphorically. These hands of mine... they can melt glass, set books ablaze. Makes it hard to inspect evidence without destroying it.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC34F2"
        },
        [80160214] = {
          ContentFR = "Alors sur le terrain, elle était mes secondes mains.",
          DialogueId = 80160214,
          GUID = "C8AC351C",
          NextOptions = {
            [1] = 801602141
          },
          SpeakNpcId = 93201,
          Subtitle = "So out in the field, she was my second pair of hands.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC351C"
        },
        [80160215] = {
          ContentFR = "Hmm... On peut dire ça.",
          DialogueId = 80160215,
          GUID = "C8AC3546",
          NextDialogue = 80160216,
          SpeakNpcId = 93201,
          Subtitle = "...In a manner of speaking, yes.",
          TalkActionId = {
            [1] = "93201:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3546"
        },
        [80160216] = {
          ContentFR = "Nous étions proches. On se couvrait mutuellement sous les balles, on déchiffrait des codes sans dormir, on poursuivait l’ombre d’une piste jusqu’à l’épuisement.",
          DialogueId = 80160216,
          GUID = "C8AC3570",
          NextDialogue = 80160217,
          SpeakNpcId = 93201,
          Subtitle = "We were inseparable once — covering each other in firefights, cracking cyphers through sleepless nights, chasing half-dead leads down blind alleys.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3570"
        },
        [80160217] = {
          ContentFR = "Une fois, pour un renseignement crucial, elle a risqué sa vie. Elle a survécu, mais a perdu l’ouïe de l’oreille gauche. Tout ça pour que je puisse envoyer un criminel à la potence.",
          DialogueId = 80160217,
          GUID = "C8AC359A",
          NextDialogue = 80160218,
          SpeakNpcId = 93201,
          Subtitle = "Once, she even risked her life to retrieve a vital piece of intel — lived to tell it, but lost all hearing in her left ear — just so I could put a criminal on the scaffold.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC359A"
        },
        [80160218] = {
          ContentFR = "Je croyais que nous resterions partenaires à vie... Mais rien ne prévient avant de changer.",
          DialogueId = 80160218,
          GUID = "C8AC35C4",
          NextDialogue = 80160219,
          SpeakNpcId = 93201,
          Subtitle = "I thought we'd always be the closest of comrades. But change never sends a warning before it comes.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC35C4"
        },
        [80160219] = {
          ContentFR = "Je vais te confier un secret. Si je suis venue à Givrelac, c’est pour réceptionner une taupe liée aux Déchus. À cause d’elle, bien trop de soldats sont morts, certains étaient mes propres hommes.",
          DialogueId = 80160219,
          GUID = "C8AC35EE",
          NextDialogue = 80160220,
          SpeakNpcId = 93201,
          Subtitle = "Against my better judgment... I'll share a secret with you. I've come to Icelake to take custody of a mole — a traitor who sided with The Forsakens. She's responsible for the deaths of many Imperial soldiers who should never have fallen — some of them had served beside me for years.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC35EE"
        },
        [80160220] = {
          ContentFR = "J’avais l’intention de la pendre de mes propres mains. La forcer à regarder les morts qu’elle a causés.",
          DialogueId = 80160220,
          GUID = "C8AC3618",
          NextOptions = {
            [1] = 801602201,
            [2] = 801602202
          },
          SpeakNpcId = 93201,
          Subtitle = "I intended to cinch the noose myself — and watch her repent for it...",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3618"
        },
        [80160221] = {
          ContentFR = "J’aurais préféré qu’elle meure pour l’Empire. Mais non, elle a choisi la trahison. C’est elle, la taupe.",
          DialogueId = 80160221,
          GUID = "C8AC3642",
          NextDialogue = 80160223,
          SpeakNpcId = 93201,
          Subtitle = "It would have been an honour if she'd died for the Empire. But no — she chose treason. The mole is no one else, but her.",
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3642"
        },
        [80160222] = {
          ContentFR = "Oui. Elle m’a trahie.",
          DialogueId = 80160222,
          GUID = "C8AC366C",
          NextDialogue = 80160223,
          SpeakNpcId = 93201,
          Subtitle = "Yes. She betrayed me.",
          TalkActionId = {
            [1] = "93201:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC366C"
        },
        [80160223] = {
          ContentFR = "Écran noir — Vulcera se sert un verre et l’avale d’un trait, avant toute réponse.",
          DialogueId = 80160223,
          GUID = "C8AC3696",
          IsBlack = 1,
          NextDialogue = 80160224,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "Before you can respond, the mysterious guest has already poured herself a drink — and downs it in one gulp.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3696"
        },
        [80160224] = {
          ContentFR = "Pfiou... Plus forte, plus amère que prévu. Assez pour faire paraître mon devoir un peu moins amer, tiens.",
          DialogueId = 80160224,
          GUID = "C8AC36C0",
          NextOptions = {
            [1] = 801602241,
            [2] = 801602242
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 93201,
          Subtitle = "Haa... Stronger than I expected. Bitter, too — bitter enough to make the judgment I'll have to pass seem mild.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC36C0"
        },
        [80160225] = {
          ContentFR = "Non. Je sais ce que j’ai à faire. Je n’ai juste... pas encore décidé comment lui répondre quand elle m’expliquera, à sa manière, pourquoi elle a fait tout ça.",
          DialogueId = 80160225,
          GUID = "C8AC36EA",
          NextDialogue = 80160226,
          SpeakNpcId = 93201,
          Subtitle = "...No. My intent hasn't wavered. Not for a second. I just haven't yet decided what words to throw back at her sophistry when we meet again.",
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC36EA"
        },
        [80160226] = {
          ContentFR = "« Commandante... Je te déteste, je déteste ce métier. Tu veux vivre dans l’ombre, dans la crasse ? C’est ton problème. Moi, j’en peux plus. Les humains vont vers la lumière. Sauf les monstres comme toi. »",
          DialogueId = 80160226,
          GUID = "C8AC3714",
          NextDialogue = 80160227,
          SpeakNpcId = 93201,
          Subtitle = "\"Commander, I've had enough — of you, of this filthy job. You like crawling through the gutter, living without sunlight — that's your choice. But I won't. Humans seek the light. Maybe you really are a monster.\"",
          TalkActionId = {
            [1] = "93201:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3714"
        },
        [80160227] = {
          ContentFR = "En y repensant, ce genre de dispute... on l’a eue plus d’une fois. Peut-être que la fin était déjà écrite. Mais j’ai fermé les yeux. La confiance m’a rendue aveugle.",
          DialogueId = 80160227,
          GUID = "C8AC373E",
          NextDialogue = 80160228,
          SpeakNpcId = 93201,
          Subtitle = "By the time I noticed, that argument had played on repeat. Perhaps this ending was written long ago, and I was just too blind — too trusting — to see it.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC373E"
        },
        [80160228] = {
          ContentFR = "Quand je la verrai… est-ce que je dois la condamner ? Ou la pleurer ? Suis-je son amie ? Sa supérieure ? Une juge ? Ou simplement une ex-partenaire brisée ?",
          DialogueId = 80160228,
          GUID = "C8AC3768",
          NextDialogue = 80160229,
          SpeakNpcId = 93201,
          Subtitle = "When I face her... should I condemn her? Or mourn her? As her friend, her partner, her superior... or her executioner?",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3768"
        },
        [80160229] = {
          ContentFR = "Il ne me reste qu’une nuit pour répondre à cette question.",
          DialogueId = 80160229,
          GUID = "C8AC3792",
          NextDialogue = 80160230,
          SpeakNpcId = 93201,
          Subtitle = "I have one night left to decide.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3792"
        },
        [80160230] = {
          ContentFR = "Et en attendant... ressers-moi un verre, veux-tu ?",
          DialogueId = 80160230,
          GUID = "C8AC37BC",
          SpeakNpcId = 93201,
          Subtitle = "Until then... pour me another.",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC37BC"
        },
        [80160301] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentFR = "Encore un verre.",
          DialogueId = 80160301,
          GUID = "C8AC4362",
          NextOptions = {
            [1] = 801603051,
            [2] = 801603052
          },
          SpeakNpcId = 93201,
          Subtitle = "Another.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4362"
        },
        [80160306] = {
          ContentFR = "Ne me sous-estime pas. La plupart de l’alcool s’évapore avant d’atteindre mon sang. Je n’ai encore jamais rencontré de distillateur capable de me faire tomber ivre.",
          DialogueId = 80160306,
          FacialId = {
            [1] = "93201:Angry01"
          },
          GUID = "C8AC4434",
          NextOptions = {
            [1] = 801603071
          },
          SpeakNpcId = 93201,
          Subtitle = "Do not underestimate me. Most of the alcohol boils off before it can reach my blood. I have yet to meet a brewer whose spirits can fell me.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4434"
        },
        [80160307] = {
          ContentFR = "Ce que je t’ai payé suffirait à t’acheter dix bouteilles comme celle-ci.",
          DialogueId = 80160307,
          FacialId = {
            [1] = "93201:Angry01"
          },
          GUID = "C8AC445E",
          NextOptions = {
            [1] = 801603071
          },
          SpeakNpcId = 93201,
          Subtitle = "The fee I paid could buy ten more bottles of this.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC445E"
        },
        [80160308] = {
          ContentFR = "Peut-être bien.",
          DialogueId = 80160308,
          FacialId = {
            [1] = "93201:Doubt01"
          },
          GUID = "C8AC4488",
          NextDialogue = 80160309,
          SpeakNpcId = 93201,
          Subtitle = "Perhaps.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4488"
        },
        [80160309] = {
          ContentFR = "Tu sors toutes les sucreries du Sanctuaire et les disposes devant Vulcera.",
          DialogueId = 80160309,
          GUID = "C8AC44B2",
          IsBlack = 1,
          NextOptions = {
            [1] = 801603091
          },
          Subtitle = "You gather every piece of confectionery in the house and set them out before her.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC44B2"
        },
        [80160310] = {
          ContentFR = "Je prends celui-ci.",
          DialogueId = 80160310,
          FacialId = {
            [1] = "93201:None"
          },
          GUID = "C8AC44DC",
          NextOptions = {
            [1] = 801603101
          },
          SpeakNpcId = 93201,
          Subtitle = "This will do.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC44DC"
        },
        [80160311] = {
          ContentFR = "Un bon souvenir ? Hum...",
          DialogueId = 80160311,
          GUID = "C8AC4506",
          NextDialogue = 80160312,
          SpeakNpcId = 93201,
          Subtitle = "Happier? Heh...",
          TalkActionId = {
            [1] = "93201:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4506"
        },
        [80160312] = {
          ContentFR = "Ce miel me rappelle seulement une maîtresse parfumeuse, et une criminelle jusqu’au bout des ongles. Elle utilisait la Rosée pourpre pour créer un parfum envoûtant, capable d’envoyer les gens dans un sommeil éternel : \"L’être destiné\".",
          DialogueId = 80160312,
          GUID = "C8AC4530",
          NextOptions = {
            [1] = 801603121
          },
          SpeakNpcId = 93201,
          Subtitle = "It recalls only a master perfumer — a criminal, through and through. She distilled dewiolet nectar into her signature fragrance, The Destined One: a scent so sweet it could lull the unwary into eternal sleep.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4530"
        },
        [80160313] = {
          ContentFR = "... Non.",
          DialogueId = 80160313,
          GUID = "C8AC455A",
          NextDialogue = 80160314,
          SpeakNpcId = 93201,
          Subtitle = "...No.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC455A"
        },
        [80160314] = {
          ContentFR = "C’est une petite maligne, pleine de ruses et de mots doux. Son esprit ne pense qu’à ce qu’elle appelle « l’amour », mais si tu la prends pour une idiote, tu finis empoisonné jusqu’à la mort.",
          DialogueId = 80160314,
          GUID = "C8AC4584",
          NextDialogue = 80160315,
          SpeakNpcId = 93201,
          Subtitle = "Silver-tongued, serpentine, and sly — a charming liar who spoke endlessly of \"romance\" and \"love.\" But do not mistake her for some love-struck fool. Trust her, and you would find yourself a cold corpse, with venom seeping through your skin.",
          TalkActionId = {
            [1] = "93201:Sit_Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4584"
        },
        [80160315] = {
          ContentFR = "Rebecca la parfumeuse, célèbre à Luca, mais introuvable dans les archives de l’Empire.",
          DialogueId = 80160315,
          GUID = "C8AC45AE",
          NextDialogue = 80160316,
          SpeakNpcId = 93201,
          Subtitle = "\"Rebecca the Perfumer\" — infamous across Luca, yet no more than a ghost in the Empire's records.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC45AE"
        },
        [80160316] = {
          ContentFR = "Personne ne sait pourquoi elle a quitté sa terre natale, ni quand elle est arrivée à Dismania. Elle est simplement apparue, comme tirée du brouillard.",
          DialogueId = 80160316,
          GUID = "C8AC45D8",
          NextDialogue = 80160317,
          SpeakNpcId = 93201,
          Subtitle = "No one knows why she fled her homeland, nor when she drifted into Dismania. She was simply... there, as if conjured from the mist.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC45D8"
        },
        [80160317] = {
          ContentFR = "Toute menace envers la sécurité impériale doit être éliminée, surtout si elle vient d’un Daimon puissant. J’ai donc étudié son passé, deviné ses intentions, et j’ai mal jugé.",
          DialogueId = 80160317,
          GUID = "C8AC4602",
          NextDialogue = 80160318,
          SpeakNpcId = 93201,
          Subtitle = "Any threat to Imperial security must be excised — all the more so when it comes from a Daimon of uncommon strength. I traced her movements, inferred her purpose — and misjudged her.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4602"
        },
        [80160318] = {
          ContentFR = "Plus que son ambition, j’ai sous-estimé les problèmes qu’elle allait causer.",
          DialogueId = 80160318,
          GUID = "C8AC462C",
          NextDialogue = 80160319,
          SpeakNpcId = 93201,
          Subtitle = "I overestimated her ambition — and fatally underestimated the chaos she would unleash.",
          TalkActionId = {
            [1] = "93201:Sit_Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC462C"
        },
        [80160319] = {
          ContentFR = "Elle ne voulait pas voler tout l’or de la Banque Impériale, ni assassiner l’Empereur lors d’une parade. Les plans de forteresse, les messages secrets transportés par des espions, pour elle, ce n’étaient que des brouillons pour calculer des formules de parfum.",
          DialogueId = 80160319,
          GUID = "C8AC4656",
          NextDialogue = 80160320,
          SpeakNpcId = 93201,
          Subtitle = "She was not there to raid the Imperial Bank, nor to assassinate the Emperor at some parade. Fortress blueprints, top-secret dispatches smuggled out by agents at risk to their lives — to her, they were little more than scrap paper for jotting down perfume recipes.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4656"
        },
        [80160320] = {
          ContentFR = "Rebecca la parfumeuse avait un but simple et ridicule : trouver l’amant parfait, et elle ferait tout pour ça, sans limites.",
          DialogueId = 80160320,
          GUID = "C8AC4680",
          NextDialogue = 80160321,
          SpeakNpcId = 93201,
          Subtitle = "Rebecca the Perfumer had one ludicrously simple ambition — to find the perfect lover. And she would stop at nothing to realise it.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4680"
        },
        [80160321] = {
          ContentFR = "Pour les vermines tapis dans l’ombre de Dismania, c’était un pion parfait, étrangère, experte en poison, et surtout, une romantique naïve.",
          DialogueId = 80160321,
          GUID = "C8AC46AA",
          NextDialogue = 80160322,
          SpeakNpcId = 93201,
          Subtitle = "To the vermin and gutter-rats skulking in Dismania's underbelly, she was the perfect pawn — a foreign Daimon, mistress of poisons, and, best of all, a dreamy-eyed romantic.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC46AA"
        },
        [80160322] = {
          ContentFR = "Elle fut vite mêlée à un complot. Après avoir éliminé plusieurs nobles frivoles, elle devint un bouc émissaire et fut emprisonnée.",
          DialogueId = 80160322,
          GUID = "C8AC46D4",
          NextDialogue = 80160323,
          SpeakNpcId = 93201,
          Subtitle = "Naturally, she was swept into their schemes. A handful of lecherous aristocrats fell by her hand, and when she had outlived her usefulness, they cast her aside and consigned her to prison.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC46D4"
        },
        [80160323] = {
          ContentFR = "Et c’est à moi qu’on confia la mission de découvrir toute la vérité.",
          DialogueId = 80160323,
          GUID = "C8AC46FE",
          NextDialogue = 80160324,
          SpeakNpcId = 93201,
          Subtitle = "It fell to me to oversee the investigation.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC46FE"
        },
        [80160324] = {
          ContentFR = "Lors de son interrogatoire, je lui ai dit qu’elle risquait cinquante ans de prison selon le Code pénal d’Hyperborea. Mais si elle coopérait, je demanderais une réduction de dix ans.",
          DialogueId = 80160324,
          GUID = "C8AC4728",
          NextOptions = {
            [1] = 801603241
          },
          SpeakNpcId = 93201,
          Subtitle = "During interrogation I told her: under the Hyperborean Criminal Code, her offences warranted fifty years of imprisonment. But if she cooperated, I would petition for a ten-year reduction.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4728"
        },
        [80160325] = {
          ContentFR = "Elle n’a même pas attendu que je finisse ma phrase pour dire oui.",
          DialogueId = 80160325,
          GUID = "C8AC4752",
          NextOptions = {
            [1] = 801603251,
            [2] = 801603252
          },
          SpeakNpcId = 93201,
          Subtitle = "She accepted before I could finish the terms.",
          TalkActionId = {
            [1] = "93201:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4752"
        },
        [80160326] = {
          ContentFR = "Peu de condamnés coopèrent comme elle l’a fait. Ce n’était pas juste pour gagner sa liberté, mais comme si elle poursuivait un désir secret, implacable et méthodique.",
          DialogueId = 80160326,
          GUID = "C8AC477C",
          NextDialogue = 80160327,
          SpeakNpcId = 93201,
          Subtitle = "Few convicts ever cooperated as she did. It was as if — rather than bargaining for her freedom — she was pursuing some private, twisted ambition — methodical, relentless, unflinching.",
          TalkActionId = {
            [1] = "93201:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC477C"
        },
        [80160327] = {
          ContentFR = "Je pensais qu’elle voulait se venger de ceux qui l’avaient manipulée, mais elle a nié cela.",
          DialogueId = 80160327,
          GUID = "C8AC47A6",
          NextDialogue = 80160328,
          SpeakNpcId = 93201,
          Subtitle = "I assumed it was revenge against the puppeteers who used her. She denied it.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC47A6"
        },
        [80160328] = {
          ContentFR = "Elle m’a dit : « Le nez d’une parfumeuse est fin, et en toi... j’ai senti une âme semblable. »",
          DialogueId = 80160328,
          GUID = "C8AC47D0",
          NextOptions = {
            [1] = 801603281,
            [2] = 801603282
          },
          SpeakNpcId = 93201,
          Subtitle = "\"A perfumer's nose is keen,\" she told me. \"And on you... I catch the scent of a kindred soul.\"",
          TalkActionId = {
            [1] = "93201:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC47D0"
        },
        [80160329] = {
          ContentFR = "Comme tu le dis, après avoir percé le mystère, nous avons été attaqués par le véritable instigateur. Gravement blessée, j’ai perdu toute capacité d’agir.",
          DialogueId = 80160329,
          GUID = "C8AC47FA",
          NextDialogue = 80160330,
          SpeakNpcId = 93201,
          Subtitle = "You're perceptive. Indeed — once the investigation neared the heart of it, we were ambushed by the true orchestrator. I was gravely wounded — left helpless.",
          TalkActionId = {
            [1] = "93201:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC47FA"
        },
        [80160330] = {
          ContentFR = "Elle ne s’est pas enfuie, ni profité de l’occasion pour me tuer. Au contraire, elle m’a soignée. Mais quand je refusais de perdre conscience, elle m’a vaporisé son parfum signature, \"L’être destiné\".",
          DialogueId = 80160330,
          GUID = "C8AC4824",
          NextDialogue = 80160331,
          SpeakNpcId = 93201,
          Subtitle = "She did not flee, nor finish me. Instead she bound my wounds — then, when I refused to black out, she misted me with her signature scent: The Destined One.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4824"
        },
        [80160331] = {
          ContentFR = "Ce parfum de Rosée pourpre m’a plongée dans un rêve sans fin.",
          DialogueId = 80160331,
          GUID = "C8AC484E",
          NextDialogue = 80160332,
          SpeakNpcId = 93201,
          Subtitle = "The dewiolet fragrance instantly drew me into a dream without end.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC484E"
        },
        [80160332] = {
          ContentFR = "...",
          DialogueId = 80160332,
          GUID = "C8AC4878",
          NextDialogue = 80160333,
          SpeakNpcId = 93201,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4878"
        },
        [80160333] = {
          ContentFR = "As-tu déjà imaginé comment ta vie aurait pu être si un \"accident\" particulier ne s’était jamais produit ? ",
          DialogueId = 80160333,
          GUID = "C8AC48A2",
          NextDialogue = 80160334,
          SpeakNpcId = 93201,
          Subtitle = "Tell me — have you ever wondered how different your life might be, had a single \"accident\" never occurred?",
          TalkActionId = {
            [1] = "93201:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC48A2"
        },
        [80160334] = {
          ContentFR = "Dans ce rêve... je n’étais pas devenue un Daimon à la peau rouge, mes proches ne me vénéraient pas comme une sainte, et la main de ma mère pouvait encore effleurer ma joue.",
          DialogueId = 80160334,
          GUID = "C8AC48CC",
          NextDialogue = 80160335,
          SpeakNpcId = 93201,
          Subtitle = "In that dream... I never awakened as a red-skinned Daimon. My kin never revered me as a divine figure. My mother could still cup my cheek gently, without being scorched.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC48CC"
        },
        [80160335] = {
          ContentFR = "Je me suis rappelée... à quel point mes mains étaient autrefois pâles.",
          DialogueId = 80160335,
          GUID = "C8AC48F6",
          NextDialogue = 80160336,
          SpeakNpcId = 93201,
          Subtitle = "For the first time in years, I remembered how pale my hands once were.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC48F6"
        },
        [80160336] = {
          ContentFR = "J’étais une Charon ordinaire, sans corne cassée, sans brûlure. Je ne brûlais personne par ma simple présence, je dormais dans un lit, pas sur le sol froid, et les preuves et documents passaient naturellement entre mes mains sans jamais s’effriter...",
          DialogueId = 80160336,
          GUID = "C8AC4920",
          NextDialogue = 80160337,
          SpeakNpcId = 93201,
          Subtitle = "I was just an ordinary Charon. No shattered horn. No scorched skin to sear anyone who came too close.\nI slept in a bed, not on stone floors for fear of fire. I turned over papers — evidence, reports — without worrying they might blacken and crumble at my touch.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4920"
        },
        [80160337] = {
          ContentFR = "Comme mes ancêtres, je remplissais la mission que la famille m’avait confiée. Une vie dans l’ombre, certes, mais privée de certains dons, j’étais entourée, pas seule.",
          DialogueId = 80160337,
          GUID = "C8AC494A",
          NextDialogue = 80160338,
          SpeakNpcId = 93201,
          Subtitle = "I bore my family's duty as a warden of the Empire, as all my forebears had. A life still spent in shadow, yes — but without the legacy passed on to me by the first of our line, I found myself... somehow less alone.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC494A"
        },
        [80160338] = {
          ContentFR = "Au début, j’avais encore les yeux ouverts sur ce monde trop \"gentil\", un leurre sucré. Quelqu’un tirait les ficelles.",
          DialogueId = 80160338,
          GUID = "C8AC4974",
          NextDialogue = 80160339,
          SpeakNpcId = 93201,
          Subtitle = "At first I saw the seams — that suspiciously gentle world was a sugared mirage. Some unseen hand had to be pulling its strings.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4974"
        },
        [80160339] = {
          ContentFR = "Mais les jours paisibles se sont enchaînés... Un an, deux ans, trois ans... Dix ans. Le mal caché n’est jamais sorti. Ce rêve n’avait pas de fin.",
          DialogueId = 80160339,
          GUID = "C8AC499E",
          NextDialogue = 80160340,
          SpeakNpcId = 93201,
          Subtitle = "Yet the quiet days stretched on. One year. Then two. Three. Ten. Whatever malice lay hidden behind the curtain never emerged. The dream endured — endless, unbroken.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC499E"
        },
        [80160340] = {
          ContentFR = "Oui. Ce genre de \"bonheur\" dure sans fin.",
          DialogueId = 80160340,
          GUID = "C8AC49C8",
          NextDialogue = 80160341,
          SpeakNpcId = 93201,
          Subtitle = "Yes. That kind of \"happiness\"... stretched on without end.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC49C8"
        },
        [80160341] = {
          ContentFR = "C’était une torture lente... Subir des supplices est une douleur, mais refuser un bonheur enfin atteint est une douleur qui ronge le cœur.",
          DialogueId = 80160341,
          GUID = "C8AC49F2",
          NextDialogue = 80160342,
          SpeakNpcId = 93201,
          Subtitle = "It was, in its way, a quieter brand of torment. Not all torture is wrought by iron and flame. There is another cruelty — having to tear oneself away from a peace one had longed for. And that cuts far deeper.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC49F2"
        },
        [80160342] = {
          ContentFR = "Hélas, j’ai fini par oublier que ce n’était qu’une illusion concoctée par une parfumeuse rusée. J’ai accepté, j’ai cru que c’était ma vraie vie.",
          DialogueId = 80160342,
          GUID = "C8AC4A1C",
          NextDialogue = 80160343,
          SpeakNpcId = 93201,
          Subtitle = "In the end, I began to forget the truth: the peace, the warmth, the ordinary life were only a dream — spun by a perfumer's cunning hand.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4A1C"
        },
        [80160343] = {
          ContentFR = "Quand ai-je vraiment cédé ? Peut-être lors de ma fête d’anniversaire, quand j’ai ouvert toutes les cartes reçues, une à une...",
          DialogueId = 80160343,
          GUID = "C8AC4A46",
          NextDialogue = 80160344,
          SpeakNpcId = 93201,
          Subtitle = "When did I first yield to the illusion? Perhaps it was at that birthday celebration... when I opened each card, one by one.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4A46"
        },
        [80160344] = {
          ContentFR = "Oui, je me souviens encore de chaque mot, comme si c’était hier...",
          DialogueId = 80160344,
          GUID = "C8AC4A70",
          SpeakNpcId = 93201,
          Subtitle = "Yes — even now, I can still recall the words written inside every single one.",
          TalkActionId = {
            [1] = "93201:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4A70"
        },
        [80160345] = {
          ContentFR = "« Ma petite boule de neige,\nje suis si fière de voir comme tu as grandi !\nPar la grâce de Sa Majesté,\nj’ai longtemps craint que tu ne sois pas vraiment heureuse.\nTu travailles sans relâche, jour et nuit,\ncomme si une seule minute d’oisiveté était un crime.\nMais en tant que mère, tout ce que je souhaite,\nc’est que tu vives pleinement ta vie.\nLa vie est courte, et nous n’en avons qu’une.\nSois plus douce avec toi-même, tu veux bien, ma chérie ? »",
          DialogueId = 80160345,
          Duration = 30,
          GUID = "C8AC4A9A",
          IsBlack = 1,
          NextDialogue = 80160346,
          SpeakNpcId = 93201,
          Subtitle = "\"My dear little snowball, \nNothing fills my heart with greater pride than seeing how you have grown!\nBy His Majesty's grace,\nI have long feared you rarely allow yourself true happiness.\nMy little snowball, you work so hard, day and night,\nas though a single idle minute were a crime.\nBut as your mother, all I wish is for you to live — truly, fully, without regret.\nLife is short, and we only get to live it once.\nSo be gentle with yourself, my baby.\nIt is no sin to laugh, to rest, to let go once in a while.\"",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4A9A"
        },
        [80160346] = {
          ContentFR = "« Commandante,\nMerci pour une année de plus à te démener sans relâche, et bon anniversaire.\nBon, ça, c’était pour la politesse.\nMaintenant, arrête de tourner comme une toupie.\nEt surtout : le travail, c’est pas censé être une fuite.\nFranchement, ça fait presque dix ans qu’on se connaît,\net même moi, qui suis plutôt douée pour déterrer des vérités,\nje n’ai toujours pas compris ce que tu redoutes autant.\nSouviens-toi : le monde n’est pas (encore) en train de s’écrouler.\nAlors arrête de trop penser, et vis un peu, tu ne crois pas ?\nToi, t’as peut-être pas besoin de repos, mais moi, si. »",
          DialogueId = 80160346,
          Duration = 30,
          GUID = "C8AC4AC4",
          IsBlack = 1,
          NextDialogue = 80160347,
          SpeakNpcId = 93201,
          Subtitle = "\"Boss,\nThanks for another year of hard graft — and happy birthday.\nNow, enough of the formalities.\nI mean it — stop working yourself into the bone.\nAnd someone has to say it — using work as a coping mechanism is not healthy at all.\nWe've known each other nearly ten years, \nand even someone as good at digging up leads as I am still hasn't figured it out:\nWhat exactly are you always fretting about?\nRemember — unless the sky is actually falling, you can ease off.\nSo stop overthinking and actually live a little, would you?\n—You may not need a holiday, but I certainly do!\"",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4AC4"
        },
        [80160347] = {
          ContentFR = "« Madame la Geôlière,\nMerci pour toutes ces années de service fidèle au sein de l’Empire Hyperboréen. Recevez nos plus sincères respects, ainsi que nos vœux les plus chaleureux pour votre anniversaire.\nNous espérons que vous saurez savourer chaque minute de cette journée mémorable, et que les jours à venir vous offriront autant de joie que celui-ci.\n\nVeuillez trouver ci-joint votre allocation annuelle de repas, votre prime d’heures supplémentaires, ainsi qu’une invitation à votre bilan médical. Nous vous prions d’en accuser réception. »",
          DialogueId = 80160347,
          Duration = 30,
          GUID = "C8AC4AEE",
          IsBlack = 1,
          NextDialogue = 80160348,
          SpeakNpcId = 93201,
          Subtitle = [[
"Dear Madam Warden,
Thank you for your years of loyal service to the Empire. Our deepest respect and warmest birthday wishes to you.
May you enjoy this day to the full,
and may the year ahead bring you even more happiness.

Enclosed are your annual meal stipend, overtime bonus, and a voucher for a full medical examination.
Kindly acknowledge receipt at your earliest convenience."]],
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4AEE"
        },
        [80160348] = {
          ContentFR = "« Très chère Madame la Geôlière,\nPardonnez-moi de ne pas signer, pensez à moi comme à une admiratrice discrète, qui vous observe de loin.\nPeut-être ne vous souvenez-vous pas de moi, mais moi, je n’ai jamais oublié comment vous faisiez face aux criminels...\nPour vos idéaux, pour les attentes des autres... peut-être même pour une personne insignifiante comme moi (hihi).\nVous vous consumiez sans hésiter, flamboyante, aussi ardente que votre nom le laisse entendre.\nBon anniversaire !\nJ’aimerais que vous sachiez que vous méritez pleinement tout ce que vous avez accompli.\nAlors, je vous en prie, acceptez cette reconnaissance et ces vœux avec fierté et sérénité. »",
          DialogueId = 80160348,
          Duration = 30,
          GUID = "C8AC4B18",
          IsBlack = 1,
          SpeakNpcId = 93201,
          Subtitle = "\"Your Honour,\nDo excuse the anonymity — think of me as a quiet admirer, watching from a respectful distance~\nYou may not remember me, but I have never forgotten the way you stood against those thugs...\nYou fight for your ideals, for others, and maybe even for someone insignificant like me. (Teehee)\nYou shine so brightly, like a raging flame — true to your name.\nHappy birthday!\nI want you to know you deserve every honour, reward, and best wish that has come your way.\nSo please, enjoy them with all the peace of mind in the world.\"",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4B18"
        },
        [80160349] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentFR = "Depuis cette nuit-là... j’ai cessé de m’accrocher à ce que fut ma vie.",
          DialogueId = 80160349,
          GUID = "C8AC4B42",
          NextOptions = {
            [1] = 801603491,
            [2] = 801603492
          },
          SpeakNpcId = 93201,
          Subtitle = "From that night onwards, I ceased struggling to hold onto reality.",
          TalkActionId = {
            [1] = "93201:Sit_Idle_Loop"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4B42"
        },
        [80160350] = {
          ContentFR = "J’ai vécu une vie entière dans ce rêve. Et quand il s’est terminé, je suis morte paisiblement, entourée de ma famille, de mes amis, de mes collègues... Il n’y aurait pas pu avoir de plus belle fin.",
          DialogueId = 80160350,
          GUID = "C8AC4B6C",
          NextDialogue = 80160351,
          SpeakNpcId = 93201,
          Subtitle = "I lived a full lifetime within that dream. When it ended, I passed peacefully — surrounded by family, comrades, all those I held dear. There could have been no finer ending.",
          TalkActionId = {
            [1] = "93201:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4B6C"
        },
        [80160351] = {
          ContentFR = "Une vie sans trahison, sans tragédie, sans adieux, sans regrets.",
          DialogueId = 80160351,
          GUID = "C8AC4B96",
          NextDialogue = 80160352,
          SpeakNpcId = 93201,
          Subtitle = "A life without betrayal, loss, grief, or regret.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4B96"
        },
        [80160352] = {
          ContentFR = "Mais à mon réveil, il ne restait que des cendres, de la douleur... et un vertige étouffant.",
          DialogueId = 80160352,
          GUID = "C8AC4BC0",
          NextDialogue = 80160353,
          SpeakNpcId = 93201,
          Subtitle = "Then I opened my eyes. The peaceful death dissolved. Reality roared back — smoke, ash, searing pain, and bewilderment.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4BC0"
        },
        [80160353] = {
          ContentFR = "Ce qu’il me restait de force... m’a tout juste permis de lever une main...",
          DialogueId = 80160353,
          GUID = "C8AC4BEA",
          NextDialogue = 80160354,
          SpeakNpcId = 93201,
          Subtitle = "I summoned what strength remained and lifted my arm.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4BEA"
        },
        [80160354] = {
          ContentFR = ".... Une main rouge, tremblante, maculée de suie et de sang. Peut-être ai-je pleuré, à ce moment-là. C’est alors qu’elle a saisi ma main, sans la moindre hésitation.",
          DialogueId = 80160354,
          GUID = "C8AC4C14",
          NextDialogue = 80160355,
          SpeakNpcId = 93201,
          Subtitle = "A red, trembling hand, smeared with blood and soot. But she took it in both of hers, unflinching. I think... I wept.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4C14"
        },
        [80160355] = {
          ContentFR = "Même si la chaleur aurait dû lui brûler la peau. Même si je pensais qu’elle s’était enfuie depuis longtemps.",
          DialogueId = 80160355,
          GUID = "C8AC4C3E",
          NextDialogue = 80160356,
          SpeakNpcId = 93201,
          Subtitle = "The heat could have blistered her skin, yet she would not let go. I had thought she would have fled long before.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4C3E"
        },
        [80160356] = {
          ContentFR = "C’était Rebecca.",
          DialogueId = 80160356,
          GUID = "C8AC4C68",
          NextOptions = {
            [1] = 801603561,
            [2] = 801603562
          },
          SpeakNpcId = 93201,
          Subtitle = "It was Rebecca.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4C68"
        },
        [80160357] = {
          ContentFR = "Elle m’a dit : « Aux yeux des autres, nous sommes des monstres. Mais même les monstres ont le droit de rêver... et de poursuivre leurs rêves jusqu’à ce qu’ils deviennent réalité. »",
          DialogueId = 80160357,
          GUID = "C8AC4C92",
          NextDialogue = 80160358,
          SpeakNpcId = 93201,
          Subtitle = "She said: \"They call us monsters. But even monsters deserve the right to dream — and to chase those dreams until they are real.\"",
          TalkActionId = {
            [1] = "93201:Sit_Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4C92"
        },
        [80160358] = {
          ContentFR = "Je n’ai pas eu envie de la contredire. Peut-être est-ce pour cela... que je l’ai laissée partir.",
          DialogueId = 80160358,
          GUID = "C8AC4CBC",
          NextDialogue = 80160359,
          SpeakNpcId = 93201,
          Subtitle = "I wouldn't want to refute her. Perhaps that was why... I let her walk free.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4CBC"
        },
        [80160359] = {
          ContentFR = "Je porte une responsabilité, si je l’abandonne, ce sont d’autres qui en paieront le prix. Alors, juste cette fois, j’ai renoncé à mon droit de rêver... et je le lui ai offert.",
          DialogueId = 80160359,
          GUID = "C8AC4CE6",
          NextDialogue = 80160363,
          SpeakNpcId = 93201,
          Subtitle = "I bear a duty — one I cannot forsake. Were I to falter, others would suffer for it. So, just this once, I surrendered my own dream... and gave it to her instead.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4CE6"
        },
        [80160360] = {
          ContentFR = "Elle m’a dit : « Aux yeux des autres, nous sommes des monstres. Mais même les monstres ont le droit de rêver... et de poursuivre leurs rêves jusqu’à ce qu’ils deviennent réalité. »",
          DialogueId = 80160360,
          GUID = "C8AC4D10",
          NextDialogue = 80160361,
          SpeakNpcId = 93201,
          Subtitle = "She said: \"They call us monsters. But even monsters deserve the right to dream — and to chase those dreams until they are real.\"",
          TalkActionId = {
            [1] = "93201:Sit_Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4D10"
        },
        [80160361] = {
          ContentFR = "Aujourd’hui, je sais que ces rêves n’étaient qu’un mirage. Mais à cet instant... cette impression de nous ressembler m’a troublée. Et j’ai commis une faute irréparable.",
          DialogueId = 80160361,
          GUID = "C8AC4D3A",
          NextDialogue = 80160362,
          SpeakNpcId = 93201,
          Subtitle = "Now, I see how hollow those dreams were. But at the time, I was caught in that fleeting sense of kinship — and I made a mistake I cannot undo.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4D3A"
        },
        [80160362] = {
          ContentFR = "Mais je refuse de me mentir à moi-même avec de jolies excuses. J’assume ce désir, afin qu’il ne me contrôle plus jamais.",
          DialogueId = 80160362,
          GUID = "C8AC4D64",
          NextDialogue = 80160363,
          SpeakNpcId = 93201,
          Subtitle = "Still, I will not soften it with excuses. I acknowledge the desire within me — so it will never command me again.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4D64"
        },
        [80160363] = {
          ContentFR = "Je ne chercherai pas d’excuse. Je ne répéterai pas mon erreur. La prochaine fois... elle paiera pour ce qu’elle a fait.",
          DialogueId = 80160363,
          GUID = "C8AC4D8E",
          NextDialogue = 80160364,
          SpeakNpcId = 93201,
          Subtitle = "I will not plead for forgiveness. I committed a fault, and I will not repeat it. The next time we meet... she will pay for what she has done.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4D8E"
        },
        [80160364] = {
          ContentFR = "Depuis, l’odeur de la Rosée pourpre suffit à apaiser mon esprit lorsque celui-ci menace de vaciller.",
          DialogueId = 80160364,
          GUID = "C8AC4DB8",
          NextDialogue = 80160365,
          SpeakNpcId = 93201,
          Subtitle = "Since then, the scent of dewiolet steadies my mind when it threatens to stray.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4DB8"
        },
        [80160365] = {
          ContentFR = "Peut-être qu’un jour, ce rêve s’effacera complètement, et que je me libérerai enfin de cette prison d’illusions qu’a forgée \"L’être destiné\" . Mais aujourd’hui... j’ai encore besoin de ce calme.",
          DialogueId = 80160365,
          GUID = "C8AC4DE2",
          NextDialogue = 80160366,
          SpeakNpcId = 93201,
          Subtitle = "Perhaps, in time, the dream will fade and I shall break free of the illusion woven by The Destined One. For now... I still need the calm it brings.",
          TalkActionId = {
            [1] = "93201:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4DE2"
        },
        [80160366] = {
          ContentFR = "Pour finir...",
          DialogueId = 80160366,
          GUID = "C8AC4E0C",
          NextDialogue = 80160367,
          SpeakNpcId = 93201,
          Subtitle = "One last matter.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4E0C"
        },
        [80160367] = {
          ContentFR = "Voici son avis de recherche. Si tu apprends quoi que ce soit à son sujet, transmets l’information au bureau des Veilleurs le plus proche.",
          DialogueId = 80160367,
          GUID = "C8AC4E36",
          NextOptions = {
            [1] = 801603671,
            [2] = 801603672
          },
          SpeakNpcId = 93201,
          Subtitle = "Here is a wanted poster for Rebecca. Should you learn anything of her whereabouts, report it immediately to the nearest Escort post.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4E36"
        },
        [80160368] = {
          ContentFR = "Sers-moi un autre verre, tu veux bien ? Avec un peu de miel de Rosée pourpre, cette fois.",
          DialogueId = 80160368,
          GUID = "C8AC4E60",
          SpeakNpcId = 93201,
          Subtitle = "Another drink, please — and this time, with a little dewiolet honey.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4E60"
        },
        [80160401] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentFR = "Merci pour la tournée.",
          DialogueId = 80160401,
          GUID = "C8AC53CA",
          NextDialogue = 80160402,
          SpeakNpcId = 93201,
          Subtitle = "Thanks for the drink.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC53CA"
        },
        [80160402] = {
          ContentFR = "Je comprends maintenant ce que Camilla disait de toi, tu as ce don de faire baisser la garde des gens. Patience, perspicacité, empathie... voilà des qualités admirables pour {性别:un barman|une barmaid}.",
          DialogueId = 80160402,
          GUID = "C8AC53F4",
          NextDialogue = 80160403,
          SpeakNpcId = 93201,
          Subtitle = "I understand now what Camilla meant about you — you have a way of lowering people's guard. Patience, perception, empathy: admirable traits in a bartender.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC53F4"
        },
        [80160403] = {
          ContentFR = "Si un jour tu ouvres ta propre taverne... je crois bien que je deviendrai une habituée.",
          DialogueId = 80160403,
          GUID = "C8AC541E",
          NextOptions = {
            [1] = 801604031
          },
          SpeakNpcId = 93201,
          Subtitle = "If you ever open a tavern of your own... I might just become a regular.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC541E"
        },
        [80160404] = {
          ContentFR = "Hmm... Des <I>{性别:amis|amies}</>, hein.",
          DialogueId = 80160404,
          FacialId = {
            [1] = "93201:Smile01"
          },
          GUID = "C8AC5448",
          NextDialogue = 80160405,
          SpeakNpcId = 93201,
          Subtitle = "Heh. Friends...",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5448"
        },
        [80160405] = {
          ContentFR = "Ceci dit, je ne peux pas me permettre de rester là éternellement. Quand j’aurai fini ce verre, il sera temps d’aller retrouver une vieille amie.",
          DialogueId = 80160405,
          GUID = "C8AC5472",
          NextOptions = {
            [1] = 801604051
          },
          SpeakNpcId = 93201,
          Subtitle = "That reminds me. I can't afford to linger forever. Once I finish this glass, it's time I paid an old friend a visit.",
          TalkActionId = {
            [1] = "93201:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5472"
        },
        [80160406] = {
          ContentFR = "Pas besoin, quelque chose de simple suffira.",
          DialogueId = 80160406,
          GUID = "C8AC549C",
          NextDialogue = 80160407,
          SpeakNpcId = 93201,
          Subtitle = "No need. Let's keep it simple.",
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC549C"
        },
        [80160407] = {
          ContentFR = "« L’Inflexible », amer sur la langue, comme avaler une lame, et brûlant comme un feu dans l’estomac. Maintenant que j’y pense... c’est vraiment la boisson des terres gelées et des neiges éternelles.",
          DialogueId = 80160407,
          GUID = "C8AC54C6",
          NextDialogue = 80160408,
          SpeakNpcId = 93201,
          Subtitle = "The Unyielding — harsh upon the tongue, like swallowing a blade, and burning like fire once it hits the stomach. Thinking on it now... it truly is the drink for snowfields and frozen earth.",
          TalkActionId = {
            [1] = "93201:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC54C6"
        },
        [80160408] = {
          ContentFR = "Ce sera ça. Accorde-moi juste un instant.",
          DialogueId = 80160408,
          GUID = "C8AC54F0",
          NextDialogue = 80160409,
          SpeakNpcId = 93201,
          Subtitle = "I'll have it. One moment.",
          TalkActionId = {
            [1] = "93201:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC54F0"
        },
        [80160409] = {
          ContentFR = "Vulcera casse doucement la glace tombée des toits, sans laisser ses doigts toucher le bord du verre. Elle te fait signe de le remplir d’« Inflexible » jusqu’en haut.",
          DialogueId = 80160409,
          GUID = "C8AC551A",
          IsBlack = 1,
          NextDialogue = 80160410,
          SpeakNpcId = 93201,
          Subtitle = "Hellfire chips ice from the eaves, dropping it into the glass without letting her fingers touch the rim. She slides it across, then gestures for you to fill it to the brim with The Unyielding.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC551A"
        },
        [80160410] = {
          ContentFR = "La glace fond vite. Elle vide le verre d’un trait, puis un autre, encore un autre...",
          DialogueId = 80160410,
          GUID = "C8AC5544",
          IsBlack = 1,
          NextDialogue = 80160411,
          SpeakNpcId = 93201,
          Subtitle = "The ice melts fast. She drains the glass in one go. Then another. And another.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5544"
        },
        [80160411] = {
          ContentFR = "...",
          DialogueId = 80160411,
          FacialId = {
            [1] = "93201:Pain01"
          },
          GUID = "C8AC556E",
          NextDialogue = 80160412,
          SpeakNpcId = 93201,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC556E"
        },
        [80160412] = {
          ContentFR = "...",
          DialogueId = 80160412,
          GUID = "C8AC5598",
          NextOptions = {
            [1] = 801604121,
            [2] = 801604122
          },
          SpeakNpcId = 93201,
          Subtitle = ".........",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5598"
        },
        [80160413] = {
          ContentFR = "Arrête de faire tout un plat. Avec tous ces glaçons dans le verre, combien d’alcool tu crois qu’il reste ?",
          DialogueId = 80160413,
          FacialId = {
            [1] = "93201:Confident01"
          },
          GUID = "C8AC55C2",
          NextDialogue = 80160414,
          SpeakNpcId = 93201,
          Subtitle = "Relax. With the glass half-full of ice, how much liquor could it possibly hold?",
          TalkActionId = {
            [1] = "93201:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC55C2"
        },
        [80160414] = {
          ContentFR = "Je regrette juste que la glace fonde trop vite entre mes mains. Je fais tout pour la retenir, mais elle s’évapore avec l’alcool...",
          DialogueId = 80160414,
          GUID = "C8AC55EC",
          NextDialogue = 80160415,
          SpeakNpcId = 93201,
          Subtitle = "What I regret is how swiftly the ice dissolves in my hands. I do my best to preserve it, but it always turns to vapour and slips away — just like the liquor itself.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC55EC"
        },
        [80160415] = {
          ContentFR = "Je n’aime pas les longues métaphores, mais la glace qui fond et les idéaux qui s’effacent, c’est trop semblable pour que ce soit une coïncidence.",
          DialogueId = 80160415,
          GUID = "C8AC5616",
          NextDialogue = 80160416,
          SpeakNpcId = 93201,
          Subtitle = "I do not care for florid metaphors — yet melting ice and fading ideals... they are too alike for comfort.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5616"
        },
        [80160416] = {
          ContentFR = "Ça me ramène des années en arrière... Avant que je m’éveille, que mes cornes soient brisées, et que mes amis me trahissent, nous étions un groupe de jeunes sortis tout juste de l’école, pleins d’espoir et d’idéal.",
          DialogueId = 80160416,
          GUID = "C8AC5640",
          NextDialogue = 80160417,
          SpeakNpcId = 93201,
          Subtitle = "It takes me back — before I awakened, when my horns were whole, and my most trusted comrade had yet to betray me. We had just graduated, brimming with hope and unseasoned ambition.",
          TalkActionId = {
            [1] = "93201:Sit_Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5640"
        },
        [80160417] = {
          ContentFR = "On buvait le moins cher des alcools, et les acclamations de nos camarades couvraient le bruit des verres qui s’entrechoquaient.",
          DialogueId = 80160417,
          GUID = "C8AC566A",
          NextDialogue = 80160418,
          SpeakNpcId = 93201,
          Subtitle = "Back then, we celebrated with cheap spirits, our roaring toasts drowning out the clink of glasses.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC566A"
        },
        [80160418] = {
          ContentFR = "Tous les visages rougis à l’unisson, on répétait notre serment d’entrée, encore et encore :",
          DialogueId = 80160418,
          GUID = "C8AC5694",
          NextDialogue = 80160419,
          SpeakNpcId = 93201,
          Subtitle = "Every face flushed the same red as mine while we repeated the oath from induction day, again and again:",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5694"
        },
        [80160419] = {
          ContentFR = " « Combattre pour la justice d’Hyperborea, brûler pour sa lumière, tenir pour son endurance. »",
          DialogueId = 80160419,
          GUID = "C8AC56BE",
          NextDialogue = 80160420,
          SpeakNpcId = 93201,
          Subtitle = "\"To fight for Hyperborea's justice. To burn for her light. To stand for her endurance.\"",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC56BE"
        },
        [80160420] = {
          ContentFR = "« À l’Inflexible, à ceux qui ne cèdent jamais. »",
          DialogueId = 80160420,
          GUID = "C8AC56E8",
          NextDialogue = 80160421,
          SpeakNpcId = 93201,
          Subtitle = "\"The Unyielding — to those who never yield.\"",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC56E8"
        },
        [80160421] = {
          ContentFR = "Peu de camarades restent, mais il en reste deux : moi... et mon ami Artin.",
          DialogueId = 80160421,
          FacialId = {
            [1] = "93201:Sad01"
          },
          GUID = "C8AC5712",
          NextDialogue = 80160422,
          SpeakNpcId = 93201,
          Subtitle = "Of all those comrades, only two remain: myself... and that friend of mine named Artin.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5712"
        },
        [80160422] = {
          ContentFR = "Mais bientôt, il n’en restera plus qu’un.",
          DialogueId = 80160422,
          GUID = "C8AC573C",
          NextOptions = {
            [1] = 801604221
          },
          SpeakNpcId = 93201,
          Subtitle = "And soon enough, there will be only one.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC573C"
        },
        [80160423] = {
          ContentFR = "...",
          DialogueId = 80160423,
          FacialId = {
            [1] = "93201:None"
          },
          GUID = "C8AC5766",
          NextDialogue = 80160424,
          SpeakNpcId = 93201,
          Subtitle = "...",
          TalkActionId = {
            [1] = "93201:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5766"
        },
        [80160424] = {
          ContentFR = "Je ne referai pas la même erreur.",
          DialogueId = 80160424,
          GUID = "C8AC5790",
          NextDialogue = 80160425,
          SpeakNpcId = 93201,
          Subtitle = "I will not repeat the same mistake.",
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5790"
        },
        [80160425] = {
          ContentFR = "Nous sommes passées de camarades à supérieure et subordonnée, puis à juge et criminelle. Peut-être avons-nous changé, mais je tiendrai la promesse que j’ai faite.",
          DialogueId = 80160425,
          GUID = "C8AC57BA",
          NextDialogue = 80160426,
          SpeakNpcId = 93201,
          Subtitle = "We were comrades once, then officer and subordinate — now judge and criminal. Perhaps we both changed. But I will keep the vow I swore at any cost.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC57BA"
        },
        [80160426] = {
          ContentFR = "Même si je suis la seule à marcher ce chemin.",
          DialogueId = 80160426,
          GUID = "C8AC57E4",
          NextOptions = {
            [1] = 801604261
          },
          SpeakNpcId = 93201,
          Subtitle = "Even if it means I'll have to walk that path alone.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC57E4"
        },
        [80160427] = {
          ContentFR = "Rien.",
          DialogueId = 80160427,
          GUID = "C8AC580E",
          NextDialogue = 80160428,
          SpeakNpcId = 93201,
          Subtitle = "Nothing.",
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC580E"
        },
        [80160428] = {
          ContentFR = "Le camarade que j’honore, c’est celui qu’on appelait « l’Inflexible ». Quant aux criminels, je n’ai qu’une seule attitude.",
          DialogueId = 80160428,
          GUID = "C8AC5838",
          NextDialogue = 80160429,
          SpeakNpcId = 93201,
          Subtitle = "The comrade I honoured was that unyielding young woman. I have nothing to say to a criminal.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5838"
        },
        [80160429] = {
          ContentFR = "Vulcera vide le dernier fond d’eau glacée dans son verre.",
          DialogueId = 80160429,
          GUID = "C8AC5862",
          IsBlack = 1,
          NextDialogue = 80160430,
          SpeakNpcId = 93201,
          Subtitle = "Hellfire drains the last of the melted ice-water.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5862"
        },
        [80160430] = {
          ContentFR = "Peu importe d’où viennent les criminels, de l’Académie d’Alchimie ou de l’École Militaire Impériale, alliés ou ennemis, je les jugerai tous sans distinction.",
          DialogueId = 80160430,
          GUID = "C8AC588C",
          NextDialogue = 80160431,
          SpeakNpcId = 93201,
          Subtitle = "Whether from the Alchemy Academy or the Imperial Military College, whether once an ally or a lifelong enemy — I will judge them without distinction.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC588C"
        },
        [80160431] = {
          ContentFR = "C’est là le devoir d’une geôlière de la Prison Militaire Royale. C’est le seul chemin qui me reste.",
          DialogueId = 80160431,
          GUID = "C8AC58B6",
          SpeakNpcId = 93201,
          Subtitle = "Such is the duty of a warden of the Royal Prison. It is the only path left to me.",
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC58B6"
        },
        [80170001] = {
          ContentFR = "Mon enfant, si tu es {性别:fatigué|fatiguée}... assieds-toi un instant. Repose-toi.",
          DialogueId = 80170001,
          GUID = "C8B27ACA",
          SpeakNpcId = 91502,
          Subtitle = "My child, if you're feeling tired, take a seat and rest for a moment.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B27ACA"
        },
        [80170101] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentFR = "Merci de m’avoir invitée, mon enfant. Il y a bien longtemps que je n’ai pas eu l’occasion de bavarder ainsi avec {性别:un ami|une amie}. Je dois avouer que cela m’a manqué.",
          DialogueId = 80170101,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B28B32",
          LookAt = {
            [1] = "91502:p(18000P1)"
          },
          NextDialogue = 80170102,
          SpeakNpcId = 91502,
          Subtitle = "Thank you for having me, my child. It's been many years since I've had the pleasure of sitting down and conversing with a friend like this. I must admit, I do miss it.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28B32"
        },
        [80170102] = {
          ContentFR = "« Il y a bien longtemps » ? Depuis combien de temps, exactement ?",
          DialogueId = 80170102,
          GUID = "C8B28B5C",
          NextDialogue = 80170103,
          SpeakNpcId = 790008,
          Subtitle = "\"Many years\"? How long are we talking about?",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28B5C"
        },
        [80170103] = {
          ContentFR = "Hmm... Une dizaine d’années, peut-être. Et avant cela... quelques siècles ?",
          DialogueId = 80170103,
          GUID = "C8B28B86",
          NextDialogue = 80170104,
          SpeakNpcId = 91502,
          Subtitle = "Hmm... It has probably been over a decade, I would say. And before that... perhaps a few centuries.",
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28B86"
        },
        [80170104] = {
          ContentFR = "Hein... ?",
          DialogueId = 80170104,
          GUID = "C8B28BB0",
          NextDialogue = 80170105,
          SpeakNpcId = 790008,
          Subtitle = "Huh...?",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28BB0"
        },
        [80170105] = {
          ContentFR = "Hé hé... Tu sembles {性别:surpris|surprise}. En vérité, j’ai vu plus d’années que l’Empire Hyperboréen lui-même, sur lequel nous marchons.",
          DialogueId = 80170105,
          GUID = "C8B28BDA",
          NextOptions = {
            [1] = 801701051,
            [2] = 801701052
          },
          SpeakNpcId = 91502,
          Subtitle = "Hehe, I must have caught you by surprise. In truth, my age stretches far beyond the land beneath our feet — older than even the Hyperborean Empire itself.",
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28BDA"
        },
        [80170106] = {
          ContentFR = "La magie des Daimons est aussi vaste que mystérieuse. La plupart de ces dons sont innés ou transmis par le sang. Je crains qu’on ne puisse les enseigner.",
          DialogueId = 80170106,
          GUID = "C8B28C04",
          NextDialogue = 80170107,
          SpeakNpcId = 91502,
          Subtitle = "The magic powers of Daimons differ greatly — most are innate or passed down through bloodlines. I'm afraid it is not something that can be easily taught.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C04"
        },
        [80170107] = {
          ContentFR = "Oh, ce n’était qu’une blague. Mais... pour être honnête...",
          DialogueId = 80170107,
          GUID = "C8B28C2E",
          NextDialogue = 80170108,
          SpeakNpcId = 790008,
          Subtitle = "That's alright. I was just joking around. But seriously...",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C2E"
        },
        [80170108] = {
          ContentFR = "Je ne m’attendais pas à ce que tu sois si... âgée. C’est un honneur de pouvoir discuter avec toi.",
          DialogueId = 80170108,
          GUID = "C8B28C58",
          NextDialogue = 80170109,
          SpeakNpcId = 790008,
          Subtitle = "I didn't realise you had so many years of wisdom, Lady Nifle... It's truly an honour to speak with you.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C58"
        },
        [80170109] = {
          ContentFR = "Nulle nécessité de te montrer si solennel. Considère-moi juste comme une amie... quelqu’un à qui parler.",
          DialogueId = 80170109,
          GUID = "C8B28C82",
          NextDialogue = 80170110,
          SpeakNpcId = 91502,
          Subtitle = "There is no need for such formality. Think of me simply as a friend, someone with whom you may share your thoughts.",
          TalkActionId = {
            [1] = "91502:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C82"
        },
        [80170110] = {
          ContentFR = "Mais dis-moi... de quoi souhaites-tu discuter ? Je suis loin du monde depuis bien longtemps. Je doute pouvoir suivre les sujets à la mode. En revanche, si c’est le passé ou les lointains horizons qui t’intriguent, alors j’ai bien des histoires à partager.",
          DialogueId = 80170110,
          GUID = "C8B28CAC",
          NextOptions = {
            [1] = 801701101
          },
          SpeakNpcId = 91502,
          Subtitle = "But tell me, what would you like to discuss? I have long distanced myself from the fleeting trends of the world. However, if you seek stories from distant lands or times long past, I would not mind sharing what I know.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28CAC"
        },
        [80170111] = {
          ContentFR = "Je me souviens que tu as parlé de ton rôle de \"Passeuse de la Mer du Silence\". Mais je dois avouer que je ne comprends pas encore très bien ce que ça signifie...",
          DialogueId = 80170111,
          GUID = "C8B28CD6",
          NextDialogue = 80170112,
          SpeakNpcId = 790008,
          Subtitle = "I recall you saying that you were a \"Ferrywoman of the Misty Sea.\" I must admit, I'm still not entirely clear on what that means.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28CD6"
        },
        [80170112] = {
          ContentFR = "Hmm... Peut-être as-tu entendu les récits sur le peuple des Charons ?",
          DialogueId = 80170112,
          GUID = "C8B28D00",
          NextDialogue = 80170113,
          SpeakNpcId = 91502,
          Subtitle = "Hmm... Perhaps you've heard of the Charon lore.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D00"
        },
        [80170113] = {
          ContentFR = "Au commencement, il n’y avait que la Mer du Silence, enveloppée d’une brume primordiale. C’est de cette brume que naquit l’arbre sacré. Il donna des fleurs immaculées, d’où sortit notre ancêtre première, la Déesse-Mère de la vie, Embla. Et de ses mains, elle façonna le monde",
          DialogueId = 80170113,
          GUID = "C8B28D2A",
          NextDialogue = 80170114,
          SpeakNpcId = 91502,
          Subtitle = "In the beginning, the world was a chaotic sea of mist. From this mist arose the sacred tree, its branches adorned with pure white flowers. These flowers gave birth to our primordial ancestor — the goddess of life, Mother Embla, from whom all living things came.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D2A"
        },
        [80170114] = {
          ContentFR = "Toute vie vient de la Mer du Silence. Après avoir vogué un temps sur le fleuve nommé \"Monde Mortel\", tout finit par y retourner.",
          DialogueId = 80170114,
          GUID = "C8B28D54",
          NextDialogue = 80170115,
          SpeakNpcId = 91502,
          Subtitle = "All life emerged from the Misty Sea. After drifting through the river of the \"Mortal Realm,\" all things eventually return to the Misty Sea.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D54"
        },
        [80170115] = {
          ContentFR = "Le rôle de la Passeuse est d’aider les âmes égarées à retrouver leur chemin vers la Mer du Silence. La plupart du temps, je tends l’oreille aux murmures des morts... et je leur réponds en chuchotant.",
          DialogueId = 80170115,
          GUID = "C8B28D7E",
          NextDialogue = 80170116,
          SpeakNpcId = 91502,
          Subtitle = "The role of the Ferrywoman is to guide wandering souls back to the Misty Sea. Thus, I spend most of my time listening to the murmurs of the departed, responding with whispers.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D7E"
        },
        [80170116] = {
          ContentFR = "C’est un peu... inquiétant.",
          DialogueId = 80170116,
          GUID = "C8B28DA8",
          NextDialogue = 80170117,
          SpeakNpcId = 790008,
          Subtitle = "That sounds... rather unsettling.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28DA8"
        },
        [80170117] = {
          ContentFR = "Hé hé. En effet. Pour beaucoup, la mort fait peur.",
          DialogueId = 80170117,
          GUID = "C8B28DD2",
          NextOptions = {
            [1] = 801701171
          },
          SpeakNpcId = 91502,
          Subtitle = "Hehe, yes. To most, death is indeed a terrifying notion.",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28DD2"
        },
        [80170118] = {
          ContentFR = "Hmm... Puisqu’on en parle, laisse-moi te conter une histoire. Un récit sur la mort. C’est celui d’une jeune fille... et de sa petite sœur, gravement malade.",
          DialogueId = 80170118,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B28DFC",
          NextDialogue = 80170119,
          SpeakNpcId = 91502,
          Subtitle = "Hmm... Since the topic has arisen, allow me to share with you a tale about \"death.\" It is the story of a girl and her ailing younger sister.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28DFC"
        },
        [80170119] = {
          ContentFR = "Elles étaient pauvres, nées à Élysium. Orphelines dès l’enfance, elles se soutenaient l’une l’autre, affrontant le froid et la faim. Un hiver, la cadette contracta une maladie incurable.",
          DialogueId = 80170119,
          GUID = "C8B28E26",
          NextDialogue = 80170120,
          SpeakNpcId = 91502,
          Subtitle = "The girl and her sister were born into poverty in Elysium. Orphaned at a tender age, they had no choice but to fend for themselves, enduring both hunger and cold. Alas, one harsh winter, the younger sister succumbed to a fatal illness.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28E26"
        },
        [80170120] = {
          ContentFR = "La grande sœur chercha désespérément un remède. Alors qu’elle perdait tout espoir, un vieil homme lui parla d’une légende, celle du Sang d’Or.",
          DialogueId = 80170120,
          GUID = "C8B28E50",
          NextDialogue = 80170121,
          SpeakNpcId = 91502,
          Subtitle = "Desperate to save her sister, the girl searched far and wide for any possible cure, yet none came. It was then she heard a tale from an old man — the legend of the \"golden blood.\"",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28E50"
        },
        [80170121] = {
          ContentFR = "On raconte qu’autrefois, les nobles d’Élysium adoraient une femme bénie des dieux. Son sang, disait-on, guérissait les maladies, empêchait le vieillissement, aussi précieux que de l’or en fusion.",
          DialogueId = 80170121,
          GUID = "C8B28E7A",
          NextDialogue = 80170122,
          SpeakNpcId = 91502,
          Subtitle = "It is said that a woman, blessed by the gods, was once revered by the nobles of Elysium. Her blood, believed to cure ailments and preserve youth, was as precious as gold.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28E7A"
        },
        [80170122] = {
          ContentFR = "Les puissants offraient des montagnes de trésors pour quelques gouttes de ce miracle. Mais la guerre frappa à Élysium. Durant la Grande Migration, la femme fut enlevée par des rebelles... et disparut.",
          DialogueId = 80170122,
          GUID = "C8B28EA4",
          NextDialogue = 80170123,
          SpeakNpcId = 91502,
          Subtitle = "Countless nobles offered vast sums of gold for but a single phial of her blood. Yet, before long, war descended upon Elysium. During the Great Migration, she was taken by rebels, and her whereabouts were lost to history.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28EA4"
        },
        [80170123] = {
          ContentFR = "La jeune fille, tenace, retrouva sa trace. Contre toute attente, la femme vivait encore, cachée au cœur du Royaume Sylvestre : Aethyrie.",
          DialogueId = 80170123,
          GUID = "C8B28ECE",
          NextDialogue = 80170124,
          SpeakNpcId = 91502,
          Subtitle = "Driven by her resolve to save her sister, the girl set out on a long and arduous journey. Eventually, much to her astonishment, she discovered that the woman was still alive — over a century old — and living in Aethyrie, the Woodland Kingdom.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28ECE"
        },
        [80170124] = {
          ContentFR = "Portant sa sœur mourante dans ses bras, elle traversa forêts et montagnes, jusqu’à enfin trouver la femme bénie. En larmes, elle la supplia de partager un peu de son sang.",
          DialogueId = 80170124,
          GUID = "C8B28EF8",
          NextDialogue = 80170125,
          SpeakNpcId = 91502,
          Subtitle = "So, the girl carried her dying sister through mountains and rivers, and finally they found the so-called \"blessed woman.\" Cradling her nearly lifeless sister, the girl tearfully begged for just a drop of her miraculous blood.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28EF8"
        },
        [80170125] = {
          ContentFR = "Mais la légende n’était qu’un mensonge. Le Sang d’Or n’était qu’une illusion, un conte inventé par les nobles pour dissimuler leur cruauté. La femme n’était qu’une prisonnière, exploitée pour ses dons de guérison.",
          DialogueId = 80170125,
          GUID = "C8B28F22",
          NextDialogue = 80170126,
          SpeakNpcId = 91502,
          Subtitle = "But the \"golden blood,\" once believed to be a divine gift, turned out to be nothing more than a myth — a tale spun by the greed of the nobles to conceal their own sins. In truth, the woman had been imprisoned for her healing powers, enduring great suffering before finally escaping Elysium.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28F22"
        },
        [80170126] = {
          ContentFR = "Brisée par le passé, elle avait juré de ne plus jamais utiliser ses pouvoirs.",
          DialogueId = 80170126,
          GUID = "C8B28F4C",
          NextDialogue = 80170127,
          SpeakNpcId = 91502,
          Subtitle = "She had long since decided never to use her abilities again, lest they cause even more pain and suffering.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28F4C"
        },
        [80170127] = {
          ContentFR = "Donc... les efforts de la fille n’ont servi à rien ?",
          DialogueId = 80170127,
          GUID = "C8B28F76",
          NextDialogue = 80170128,
          SpeakNpcId = 790008,
          Subtitle = "So the girl went through all that for nothing...?",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28F76"
        },
        [80170128] = {
          ContentFR = "Non, attends. Si tu me racontes tout ça, c’est que l’histoire ne s’arrête pas là, n’est-ce pas ?",
          DialogueId = 80170128,
          GUID = "C8B28FA0",
          NextDialogue = 80170129,
          SpeakNpcId = 790008,
          Subtitle = "No... wait. Since you've spent so much time telling the story, surely it's not over yet?",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28FA0"
        },
        [80170129] = {
          ContentFR = "Hé hé. Bien vu. Tu as raison, la femme a fini par accepter.",
          DialogueId = 80170129,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B28FCA",
          NextDialogue = 80170130,
          SpeakNpcId = 91502,
          Subtitle = "Hehe, you're perceptive. After much hesitation, the woman eventually agreed to help.",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28FCA"
        },
        [80170130] = {
          ContentFR = "Pourquoi ?",
          DialogueId = 80170130,
          GUID = "C8B28FF4",
          NextDialogue = 80170131,
          SpeakNpcId = 790008,
          Subtitle = "Why would she do that?",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28FF4"
        },
        [80170131] = {
          ContentFR = "Parce qu’elle n’avait jamais cessé d’y penser. Deux fois déjà, elle avait tenté de sauver quelqu’un avec son sang, son amie la plus chère... et sa propre fille.",
          DialogueId = 80170131,
          GUID = "C8B2901E",
          NextDialogue = 80170132,
          SpeakNpcId = 91502,
          Subtitle = "Because, you see, the woman had not fully closed her heart to the idea of healing others. Twice before, she had tried to use her blood to extend the life of others — once for her closest friend, and once for her daughter.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2901E"
        },
        [80170132] = {
          ContentFR = "La première, une guerrière tombée au combat. L’autre, une érudite qui touchait paisiblement à sa fin.",
          DialogueId = 80170132,
          GUID = "C8B29048",
          NextDialogue = 80170133,
          SpeakNpcId = 91502,
          Subtitle = "Her friend was a valiant warrior, fatally wounded on the battlefield. Her daughter, a respected scholar, was peacefully nearing the end of her days.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29048"
        },
        [80170133] = {
          ContentFR = "Toutes deux refusèrent. Elles ne voulaient pas de cette vie volée, prolongée par un don qu’elles jugeaient contre nature.",
          DialogueId = 80170133,
          GUID = "C8B29072",
          NextDialogue = 80170134,
          SpeakNpcId = 91502,
          Subtitle = "Although their circumstances were vastly different, their decisions were the same: both refused to accept the woman's blood, choosing death over a life prolonged by such a means.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29072"
        },
        [80170134] = {
          ContentFR = "En voyant cette détresse mêlée de révolte sur le visage de la jeune sœur, elle vacilla.\nCar en elle, quelque chose s’éveilla, le souvenir d’un passé douloureux, d’une question laissée sans réponse.",
          DialogueId = 80170134,
          GUID = "C8B2909C",
          NextDialogue = 80170135,
          SpeakNpcId = 91502,
          Subtitle = "The sorrow in the girl's eyes reminded the woman of her own past, and her thoughts turned to a question that had long lingered:",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2909C"
        },
        [80170135] = {
          ContentFR = "Que se serait-il passé... si elle avait pu sauver son amie, et sa propre fille ?\nQuel avenir l’attendait, au bout de ce chemin qu’elle n’a jamais pu prendre ?",
          DialogueId = 80170135,
          GUID = "C8B290C6",
          NextDialogue = 80170136,
          SpeakNpcId = 91502,
          Subtitle = "What could have been, had she been able to save her friend and daughter? What might the path she did not take have offered?",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B290C6"
        },
        [80170136] = {
          ContentFR = "Le doute la rongeait depuis trop longtemps. Elle devait savoir. Alors elle s’entailla le bras... et donna son sang aux deux sœurs.",
          DialogueId = 80170136,
          GUID = "C8B290F0",
          NextDialogue = 80170137,
          SpeakNpcId = 91502,
          Subtitle = "She needed to know the answer. So, she cut her own arm and gave her blood to the girl.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B290F0"
        },
        [80170137] = {
          ContentFR = "La cadette but le Sang d’Or... et elle ouvrit les yeux.",
          DialogueId = 80170137,
          GUID = "C8B2911A",
          NextOptions = {
            [1] = 801701371,
            [2] = 801701372
          },
          SpeakNpcId = 91502,
          Subtitle = "The ailing little sister drank the \"golden blood\" and soon regained consciousness.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2911A"
        },
        [80170138] = {
          ContentFR = "Tu as bon cœur, mon enfant... Mais le miracle du Sang d’Or n’était qu’une douce illusion.",
          DialogueId = 80170138,
          GUID = "C8B29144",
          NextDialogue = 80170140,
          SpeakNpcId = 91502,
          Subtitle = "You are a kind child... but the so-called miraculous blood is, in truth, but an illusion. It is a fantasy people have chosen to believe in.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29144"
        },
        [80170139] = {
          ContentFR = "Non. C’était une illusion. Un mensonge façonné par le besoin d’y croire.",
          DialogueId = 80170139,
          GUID = "C8B2916E",
          NextDialogue = 80170140,
          SpeakNpcId = 91502,
          Subtitle = "Indeed. The so-called miraculous blood is, in truth, but an illusion. It is a fantasy people have chosen to believe in.",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2916E"
        },
        [80170140] = {
          ContentFR = "Le sang possédait certes un pouvoir. Mais il ne guérissait rien. Il ne repoussait pas la mort. Il figeait simplement... la vie.",
          DialogueId = 80170140,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B29198",
          NextDialogue = 80170141,
          SpeakNpcId = 91502,
          Subtitle = "The woman's blood did possess a unique power, but it neither cured disease nor halted the process of ageing. Instead, it preserved the body in a state of mere \"existence.\"",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29198"
        },
        [80170141] = {
          ContentFR = "Comme un insecte piégé dans de l’ambre. Ni mort... ni vivant.",
          DialogueId = 80170141,
          GUID = "C8B291C2",
          NextDialogue = 80170142,
          SpeakNpcId = 91502,
          Subtitle = "Like an insect trapped in amber — unspoiled, yet not truly \"alive.\"",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B291C2"
        },
        [80170142] = {
          ContentFR = "Elle avait bu ce sang, oui. Et elle n’est pas morte. Mais son corps... lui, était déjà condamné.",
          DialogueId = 80170142,
          GUID = "C8B291EC",
          NextDialogue = 80170143,
          SpeakNpcId = 91502,
          Subtitle = "So, after drinking the blood, her little sister did not die, but her body was still in an irreversible decline.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B291EC"
        },
        [80170143] = {
          ContentFR = "La cadette resta clouée au lit. Trop faible pour boire. Incapable de goûter la nourriture, de lire un mot, ou même d’entendre sa sœur.",
          DialogueId = 80170143,
          GUID = "C8B29216",
          NextDialogue = 80170144,
          SpeakNpcId = 91502,
          Subtitle = "She could do nothing but lie in bed, struggling even to swallow water. She could not taste her food, nor understand the words on the pages, nor hear clearly her sister's voice.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29216"
        },
        [80170144] = {
          ContentFR = "Pour rester auprès d’elle, l’aînée acceptait les rares petits boulots qui lui laissaient un peu de temps. Mais pour subvenir à leurs besoins, elle n’avait pas d’autre choix que d’accepter les tâches les plus dures, les plus ingrates, celles que personne ne voulait.",
          DialogueId = 80170144,
          GUID = "C8B29240",
          NextDialogue = 80170145,
          SpeakNpcId = 91502,
          Subtitle = "The girl took on various odd jobs, hoping to have enough time to stay by her sister's side and take care of her. To make ends meet, she had no choice but to take on the most gruelling work — the kind that others would avoid.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29240"
        },
        [80170145] = {
          ContentFR = "Elle tenait bon, mue par une volonté inébranlable. Elle s’accrochait à ce \"miracle\" si chèrement obtenu. Mais son corps, fragile, ne pouvait suivre. Chaque jour, elle frôlait l’effondrement.",
          DialogueId = 80170145,
          GUID = "C8B2926A",
          NextOptions = {
            [1] = 801701451
          },
          SpeakNpcId = 91502,
          Subtitle = "Her will was indeed unwavering, desperately clinging to the hard-won \"miracle.\" Yet her frail body couldn't withstand the constant strain, and each day she came closer to collapse.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2926A"
        },
        [80170146] = {
          ContentFR = "Ensuite... la cadette mit fin à ses jours. Avec ses dernières forces, elle repoussa le petit flacon de \"miracle\" que sa sœur lui avait rapporté... et la brisa au sol.",
          DialogueId = 80170146,
          GUID = "C8B29294",
          NextDialogue = 80170147,
          SpeakNpcId = 91502,
          Subtitle = "Eventually, the younger sister chose to end her own life. With the last of her strength, she pushed the small phial of \"miracle\" — the one her elder sister had so desperately begged for — to the ground and shattered it.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29294"
        },
        [80170147] = {
          ContentFR = "Peut-être avait-elle compris, enfin, que ce \"miracle\", pour elle comme pour sa sœur... n’était qu’un fardeau. Une chaîne invisible.",
          DialogueId = 80170147,
          GUID = "C8B292BE",
          NextDialogue = 80170148,
          SpeakNpcId = 91502,
          Subtitle = "Perhaps, in the end, she realised that this so-called \"miracle\" was but a pair of heavy shackles — for both herself and her elder sister.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B292BE"
        },
        [80170148] = {
          ContentFR = "C’est moi qui ai conduit son âme vers la Mer du Silence. Saurais-tu deviner ce qu’elle m’a dit ?",
          DialogueId = 80170148,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B292E8",
          NextDialogue = 80170149,
          SpeakNpcId = 91502,
          Subtitle = "It was I who guided her soul to the Misty Sea. Would you care to guess what she said to me?",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B292E8"
        },
        [80170149] = {
          ContentFR = "Vu ton regard... quelque chose de doux, non ? Comme... \"merci\" ?",
          DialogueId = 80170149,
          GUID = "C8B29312",
          NextDialogue = 80170150,
          SpeakNpcId = 790008,
          Subtitle = "From the look on your face, I imagine she said something gentle, like \"Thank you\"?",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29312"
        },
        [80170150] = {
          ContentFR = "... Tu es bien trop perspicace. À force, je vais finir par paraître prétentieuse. Mais oui. Tu as vu juste.",
          DialogueId = 80170150,
          GUID = "C8B2933C",
          NextDialogue = 80170151,
          SpeakNpcId = 91502,
          Subtitle = "...You are quite perceptive. I may have been too subtle, and perhaps not as sincere as I should have been.",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2933C"
        }
      }
    end
  },
  {
    MinKey = 80170151,
    MaxKey = 80180216,
    Loader = function()
      return {
        [80170151] = {
          ContentFR = "Elle a remercié sa sœur. Et elle a remercié cette femme. Malgré la douleur, elle était en paix. Elle avait accepté la fin.",
          DialogueId = 80170151,
          GUID = "C8B29366",
          NextDialogue = 80170152,
          SpeakNpcId = 91502,
          Subtitle = "She expressed her gratitude to her elder sister, and to that woman as well. Though her life ended in suffering, it was through this very suffering that she found peace and the strength to accept her passing.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29366"
        },
        [80170152] = {
          ContentFR = "En entendant cela, l’aînée n’a pu s’empêcher de pleurer, répétant mille fois \"pardon\"...\n Mais à la fin, elle s’est tournée vers l’urne funéraire de sa sœur, emportée par le courant, et lui a simplement dit... \"merci\".",
          DialogueId = 80170152,
          GUID = "C8B29390",
          NextDialogue = 80170153,
          SpeakNpcId = 91502,
          Subtitle = "Upon hearing this, the girl wept, breaking into profuse apologies. Yet, in the end, she spoke but a single word of thanks — directed at the urn carrying her sister's ashes as it drifted away.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29390"
        },
        [80170153] = {
          ContentFR = "La jeune fille s’est ensuite installée à Aethyrie, et est devenue une excellente médecin. Elle a fondé une famille. Puis, un jour, elle est retournée voir la femme... pour lui dire qu’elle était heureuse.",
          DialogueId = 80170153,
          GUID = "C8B293BA",
          NextDialogue = 80170154,
          SpeakNpcId = 91502,
          Subtitle = "The girl later journeyed to Aethyrie, where she became a skilled physician and settled there. After starting her own family, she visited the woman, sharing with her that she had found happiness in her life.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B293BA"
        },
        [80170154] = {
          ContentFR = "C’est à ce moment-là que la femme comprit enfin pourquoi son amie... et sa fille... avaient refusé d’être \"sauvées\".",
          DialogueId = 80170154,
          GUID = "C8B293E4",
          NextDialogue = 80170155,
          SpeakNpcId = 91502,
          Subtitle = "It was then, in that moment, that the woman finally understood why her friend and daughter had refused to let her \"save\" them.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B293E4"
        },
        [80170155] = {
          ContentFR = "La mort n’est pas toujours cruelle. Elle peut être douce. Comme les pétales qui tombent lorsqu’un fruit arrive à maturité. Une fin... pour laisser place à un commencement.",
          DialogueId = 80170155,
          GUID = "C8B2940E",
          NextDialogue = 80170156,
          SpeakNpcId = 91502,
          Subtitle = "In the grand design of life, death is not always an unwelcome guest. At times, it arrives with quiet grace — like petals drifting from a flower as fruit begins to ripen, marking not just an end, but the birth of something new.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2940E"
        },
        [80170156] = {
          ContentFR = "À force de lutter contre la mort, on finit parfois par oublier de vivre.",
          DialogueId = 80170156,
          GUID = "C8B29438",
          NextOptions = {
            [1] = 801701561,
            [2] = 801701562
          },
          SpeakNpcId = 91502,
          Subtitle = "To resist death is to remain in stasis. It may actually cause them to miss out on the beauty life has to offer.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29438"
        },
        [80170157] = {
          ContentFR = "C’est une réponse empreinte de force.",
          DialogueId = 80170157,
          GUID = "C8B29462",
          NextDialogue = 80170159,
          SpeakNpcId = 91502,
          Subtitle = "You're a strong and compassionate child.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29462"
        },
        [80170158] = {
          ContentFR = "C’est une réponse empreinte de courage.",
          DialogueId = 80170158,
          GUID = "C8B2948C",
          NextDialogue = 80170159,
          SpeakNpcId = 91502,
          Subtitle = "You're a brave child.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2948C"
        },
        [80170159] = {
          ContentFR = "Mais ce n’était là qu’un récit. L’histoire d’une femme, son point de vue. Rien ne t’oblige à y adhérer. Tu es libre de chercher ta propre vérité.",
          DialogueId = 80170159,
          GUID = "C8B294B6",
          NextDialogue = 80170160,
          SpeakNpcId = 91502,
          Subtitle = "However, this story reflects only the perspective of that woman. Do not let it weigh heavily on your heart. You are free to carve your own path, should you choose.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B294B6"
        },
        [80170160] = {
          ContentFR = "Je crois en toi. Tant que tu restes lucide... que tu refuses les illusions... Tu trouveras ta voie.",
          DialogueId = 80170160,
          GUID = "C8B294E0",
          SpeakNpcId = 91502,
          Subtitle = "I believe that, no matter the path you take, as long as you remain clear of mind and not led astray by falsehoods, you will find the right way in the end.",
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B294E0"
        },
        [80170201] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentFR = "Bonjour, mon enfant. Tu as l’air {性别:fatigué|fatiguée}... quelque chose te tourmente, n’est-ce pas ?",
          DialogueId = 80170201,
          GUID = "C8B29B9A",
          LookAt = {
            [1] = "91502:p(18000P1)"
          },
          NextOptions = {
            [1] = 801702011,
            [2] = 801702012
          },
          SpeakNpcId = 91502,
          Subtitle = "Greetings, my child. You seem weary. Has something been troubling you?",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29B9A"
        },
        [80170202] = {
          ContentFR = "Depuis que j’ai quitté mon village, j’ai vécu tant de choses... Et j’ai accumulé pas mal de regrets. Parfois, j’ai ce sentiment d’impuissance... Comme si tout ce que je faisais n’avait aucun sens.",
          DialogueId = 80170202,
          GUID = "C8B29BC4",
          NextDialogue = 80170203,
          SpeakNpcId = 790008,
          Subtitle = "Since leaving my homeland, I've been through so much and experienced many regrets. At times, I feel so powerless, as though all my efforts will be in vain.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29BC4"
        },
        [80170203] = {
          ContentFR = "Tu as beaucoup vécu, Dame Nifle... Est-ce que tu aurais un conseil à me donner ?",
          DialogueId = 80170203,
          GUID = "C8B29BEE",
          NextDialogue = 80170204,
          SpeakNpcId = 790008,
          Subtitle = "Lady Nifle, as someone with centuries of wisdom, do you have any advice for me?",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29BEE"
        },
        [80170204] = {
          ContentFR = "Je vois... Dans ce cas, laisse-moi te raconter une autre histoire.",
          DialogueId = 80170204,
          GUID = "C8B29C18",
          NextDialogue = 80170205,
          SpeakNpcId = 91502,
          Subtitle = "I see... Well, let me share another story with you.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C18"
        },
        [80170205] = {
          ContentFR = "C’est l’histoire d’un jeune homme et d’une jeune fille. Une histoire de courage, d’espoir... et d’avenir.",
          DialogueId = 80170205,
          GUID = "C8B29C42",
          NextDialogue = 80170206,
          SpeakNpcId = 91502,
          Subtitle = "This is a story about a young man and a young woman — one filled with hope, courage, and dreams of the future.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C42"
        },
        [80170206] = {
          ContentFR = "Cela remonte à mille ans. À l’époque, il n’existait qu’un seul royaume sur ce continent, Élysium. Le garçon était un simple roturier. La fille, une noble.",
          DialogueId = 80170206,
          GUID = "C8B29C6C",
          NextDialogue = 80170207,
          SpeakNpcId = 91502,
          Subtitle = "The story takes place a millennium ago, when Elysium was the only nation on the continent. One was a commoner, the other a noble.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C6C"
        },
        [80170207] = {
          ContentFR = "Le garçon, passionné de lecture, se plongeait dans les mythes et l’histoire dès son plus jeune âge. Il avait une soif de savoir telle qu’on disait de lui qu’il deviendrait un grand érudit.",
          DialogueId = 80170207,
          GUID = "C8B29C96",
          NextDialogue = 80170208,
          SpeakNpcId = 91502,
          Subtitle = "The young man, born a commoner, developed a profound love for books from an early age, particularly history and mythology. Even as a youth, his vast knowledge became widely known, and many expected him to become a great scholar.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C96"
        },
        [80170208] = {
          ContentFR = "Mais plus il lisait, plus il comprenait. Et plus il comprenait... plus il voyait que cette terre était semée d’erreurs. Des choses que tout le monde considérait comme normales... mais qui étaient profondément injustes.",
          DialogueId = 80170208,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B29CC0",
          NextDialogue = 80170209,
          SpeakNpcId = 91502,
          Subtitle = "But the more he read, the more he learned, and the deeper he thought, the more he came to realise that this land was rife with injustices. What people had come to accept as normal was not always right.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29CC0"
        },
        [80170209] = {
          ContentFR = "Les roturiers peinaient à se nourrir, alors que les prêtres festoyaient à volonté. Et derrière les hymnes sacrés résonnaient les cris d’innocents, exécutés sur les potences pour hérésie.",
          DialogueId = 80170209,
          GUID = "C8B29CEA",
          NextDialogue = 80170210,
          SpeakNpcId = 91502,
          Subtitle = "The commoners toiled endlessly, barely scraping by, while the priests dined in excess. Beneath the loud chorus of hymns, the cries of the innocent could be heard — condemned as heretics and executed beneath the gallows.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29CEA"
        },
        [80170210] = {
          ContentFR = "Et parmi ces pleurs... se trouvait une jeune fille, qu’on disait bénie d’un \"Sang d’Or\".",
          DialogueId = 80170210,
          GUID = "C8B29D14",
          NextDialogue = 80170211,
          SpeakNpcId = 91502,
          Subtitle = "—Of course, one of those cries belonged to a young girl, said to possess the \"golden blood.\"",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D14"
        },
        [80170211] = {
          ContentFR = "Le jour, elle offrait ce sang, en tremblant, à ceux venus la vénérer. La nuit, elle pleurait seule dans sa cellule, en priant les dieux de lui faire grâce.",
          DialogueId = 80170211,
          GUID = "C8B29D3E",
          NextDialogue = 80170212,
          SpeakNpcId = 91502,
          Subtitle = "By day, she trembled as she slit her arm, offering her blood to those who came to worship her; by night, she curled in her cell, weeping in pain and praying for mercy from the gods.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D3E"
        },
        [80170212] = {
          ContentFR = "Un jour, le jeune érudit prit le risque d’entrer dans le sanctuaire, et prononça un discours enflammé devant la foule venue réclamer le Sang d’Or. Mais en guise de réponse... ce furent les lances des gardes qui lui tombèrent dessus.",
          DialogueId = 80170212,
          GUID = "C8B29D68",
          NextDialogue = 80170213,
          SpeakNpcId = 91502,
          Subtitle = "One day, the young scholar ventured into the temple and delivered an impassioned speech to the gathered crowd, all of whom sought the so-called \"golden blood.\" In response, however, all he received was the sharp point of the guards' spears.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D68"
        },
        [80170213] = {
          ContentFR = "Il fut jeté dans un cachot froid et humide. Et c’est là qu’il rencontra l’autre héroïne de cette histoire : Une jeune noble venue accompagner son père, haut dignitaire, pour une inspection.",
          DialogueId = 80170213,
          GUID = "C8B29D92",
          NextDialogue = 80170214,
          SpeakNpcId = 91502,
          Subtitle = "He was thrown into a cold, damp cell, where, by a twist of fate, he encountered another key figure in the story — the noble young woman, who had arrived with her father for an inspection.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D92"
        },
        [80170214] = {
          ContentFR = "C’était une jeune fille fougueuse, éprise d’équitation et de combat. Mais elle avait aussi un bon cœur. Touchée par ce garçon de son âge égaré si jeune, elle alla en secret lui conseiller d’avouer ses fautes pour alléger sa peine.",
          DialogueId = 80170214,
          GUID = "C8B29DBC",
          NextDialogue = 80170215,
          SpeakNpcId = 91502,
          Subtitle = "The young woman had a deep passion for riding and martial arts, and beneath her spirited nature was a kind and compassionate heart. When she came across the \"misguided\" young scholar — one of her own age — she couldn't help but feel sympathy for him. In secret, she visited his cell, hoping to persuade him to confess and earn a lighter sentence.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29DBC"
        },
        [80170215] = {
          ContentFR = "Mais lui... déclara qu’il n’avait commis aucun crime. Et au lieu d’écouter ses conseils, il tenta de la convaincre, elle, d’ouvrir enfin les yeux.",
          DialogueId = 80170215,
          GUID = "C8B29DE6",
          NextDialogue = 80170216,
          SpeakNpcId = 91502,
          Subtitle = "But the scholar insisted on his innocence. He even urged the young noblewoman to awaken from her own ignorance.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29DE6"
        },
        [80170216] = {
          ContentFR = "Il lui expliqua que la jeune fille au \"Sang d’Or\" n’était pas une sainte... Mais une prisonnière, exploitée par un grand noble pour sa richesse. Ce noble n’était autre que le père de la jeune noble.",
          DialogueId = 80170216,
          GUID = "C8B29E10",
          NextDialogue = 80170217,
          SpeakNpcId = 91502,
          Subtitle = "He revealed to her that the girl, said to possess the \"golden blood\" whom people revered, was in fact a poor soul held captive by a powerful nobleman — the noble young woman's very own father — who sought to profit from her.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E10"
        },
        [80170217] = {
          ContentFR = "Bien sûr, au début, la noble refusa d’y croire. Elle trouvait cela absurde. Mais les mots du garçon... et surtout, son regard ardent... restaient ancrés dans sa mémoire.",
          DialogueId = 80170217,
          GUID = "C8B29E3A",
          NextDialogue = 80170218,
          SpeakNpcId = 91502,
          Subtitle = "At first, the young woman dismissed his words as absurd. Yet, the fervour in his bright eyes lingered in her thoughts, refusing to fade.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E3A"
        },
        [80170218] = {
          ContentFR = "Ce regard-là... ne pouvait pas mentir. Alors elle fit le premier pas. Elle déroba une clé à son père, et s’introduisit dans les tréfonds du sanctuaire. Elle y découvrit une enfant enchaînée, blême, à peine en vie.",
          DialogueId = 80170218,
          GUID = "C8B29E64",
          NextDialogue = 80170219,
          SpeakNpcId = 91502,
          Subtitle = "She saw sincerity in those eyes. And so, with a heart moved by his words, she took the first step toward uncovering the truth. Stealing the key from her father, she ventured into the deepest chamber of the temple, where she found the pale, emaciated girl — shackled and imprisoned.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E64"
        },
        [80170219] = {
          ContentFR = "Une fois la vérité découverte, elle retourna voir le garçon. Son regard, si grave, n’avait plus rien de l’arrogance noble qu’il avait vu en elle la première fois. Le garçon comprit qu’elle était prête à entendre. Alors il lui révéla d’autres crimes, bien plus sombres encore.",
          DialogueId = 80170219,
          GUID = "C8B29E8E",
          NextDialogue = 80170220,
          SpeakNpcId = 91502,
          Subtitle = "After learning the truth, the noblewoman returned to the scholar's cell and stood before him once more. Seeing her grave and sympathetic expression, the scholar understood that she was now ready. And so, he shared with her the dark truths of the nobleman.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E8E"
        },
        [80170220] = {
          ContentFR = "Ses paroles furent comme une lame, déchirant la toile dorée de la vie de la jeune noble. Derrière les apparences... ne restaient que sang, larmes et mensonges. Et à partir de ce jour... elle commença à voir ce qu’elle avait toujours ignoré.",
          DialogueId = 80170220,
          GUID = "C8B29EB8",
          NextDialogue = 80170221,
          SpeakNpcId = 91502,
          Subtitle = "The young man's words struck like a blade, tearing through the delicate fabric of the young woman's privileged life, exposing the grotesque reality beneath. In that moment, she began to see the dark corners of her world that had once remained hidden.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29EB8"
        },
        [80170221] = {
          ContentFR = "Elle raconta tout à son père. Elle espérait qu’il libérerait le garçon. Mais ce qu’elle obtint, ce fut l’enfermement. La surveillance. Et ce fut là qu’elle comprit : Depuis le début... son propre père avait toujours été du côté des bourreaux.",
          DialogueId = 80170221,
          GUID = "C8B29EE2",
          NextOptions = {
            [1] = 801702211,
            [2] = 801702212
          },
          SpeakNpcId = 91502,
          Subtitle = "She confided in her father, hoping he would release the young man. Instead, she found herself placed under house arrest, constantly watched. It was then that she realised — her father had always been complicit in their suffering.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29EE2"
        },
        [80170222] = {
          ContentFR = "Oui... Eux aussi ont connu le désespoir. Eux aussi ont douté. Ils ont connu la fatigue. Ils se sont demandé, comme toi, si ça valait vraiment la peine de continuer. Mais ils ont choisi de ne pas abandonner.",
          DialogueId = 80170222,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B29F0C",
          NextDialogue = 80170223,
          SpeakNpcId = 91502,
          Subtitle = "Yes. There were times when they, too, despaired. Exhausted, much like you are now, they questioned the very meaning of their struggle. Yet, despite it all, they chose to persevere.",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F0C"
        },
        [80170223] = {
          ContentFR = "Même en prison, le garçon continuait à écrire. Il affûtait ses théories, dessinait un monde nouveau, fondé sur la liberté et la justice.",
          DialogueId = 80170223,
          GUID = "C8B29F36",
          NextDialogue = 80170224,
          SpeakNpcId = 91502,
          Subtitle = "Even in prison, the young man continued to develop his theories, tirelessly sketching a vision of a new world rooted in justice and freedom.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F36"
        },
        [80170224] = {
          ContentFR = "Et même privée de tout, la fille refusa les plaisirs faciles. Elle choisit de tendre la main aux plus démunis. Et petit à petit... elle rassembla des alliés.",
          DialogueId = 80170224,
          GUID = "C8B29F60",
          NextDialogue = 80170225,
          SpeakNpcId = 91502,
          Subtitle = "Without the support of her family, the young woman rejected the temptations of wealth, dedicating herself to uplifting the downtrodden and seeking out those willing to contribute to the cause.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F60"
        },
        [80170225] = {
          ContentFR = "Leurs actes semblaient dérisoires. Comme le battement d’aile d’un papillon. Mais ce battement... déclencha une tempête. Une tempête qui fendit la carapace d’Élysium.",
          DialogueId = 80170225,
          GUID = "C8B29F8A",
          NextDialogue = 80170226,
          SpeakNpcId = 91502,
          Subtitle = "At first, their efforts were as subtle as the flutter of a butterfly's wings. Yet, over time, their actions stirred a storm, cracking the seemingly impenetrable structure of Elysium.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F8A"
        },
        [80170226] = {
          ContentFR = "Ils devinrent les chefs de ce qu’on appela plus tard la Grande Migration. Ils guidèrent les opprimés, et brisèrent leurs chaînes.",
          DialogueId = 80170226,
          GUID = "C8B29FB4",
          NextDialogue = 80170227,
          SpeakNpcId = 91502,
          Subtitle = "Together, they became the leaders of the legendary Great Migration, leading a resistance that freed the oppressed from the grasp of Elysium.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29FB4"
        },
        [80170227] = {
          ContentFR = "La résistance d’Élysium... La Grande Migration...",
          DialogueId = 80170227,
          GUID = "C8B29FDE",
          NextDialogue = 80170228,
          SpeakNpcId = 790008,
          Subtitle = "The Elysium resistance... the Great Migration...",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29FDE"
        },
        [80170228] = {
          ContentFR = "J’en ai lu quelques récits. Mais ces gens... ils n’ont jamais vraiment atteint l’égalité qu’ils cherchaient, si ?",
          DialogueId = 80170228,
          GUID = "C8B2A008",
          NextDialogue = 80170229,
          SpeakNpcId = 790008,
          Subtitle = "I've read about it in books. But they never truly achieved their vision of equality, did they?",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A008"
        },
        [80170229] = {
          ContentFR = "... Tu as raison. Le destin est cruel. Il peut balayer une vie en un instant. Souvent, oui... nos efforts sont vains.",
          DialogueId = 80170229,
          GUID = "C8B2A032",
          NextDialogue = 80170230,
          SpeakNpcId = 91502,
          Subtitle = "...Indeed, fate is a cruel force. It can stir a storm in the calmest of seas or extinguish flames with the power of a tidal wave. As you've said, often, our efforts yield nothing in the end.",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A032"
        },
        [80170230] = {
          ContentFR = "Mais ces instants de lumière, eux... ont bien existé. Et c’est la mémoire qui les rend éternels.",
          DialogueId = 80170230,
          FacialId = {
            [1] = "91502:Confident01"
          },
          GUID = "C8B2A05C",
          NextDialogue = 80170231,
          SpeakNpcId = 91502,
          Subtitle = "However, those glorious moments were real, and they will be eternally etched in memory.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A05C"
        },
        [80170231] = {
          ContentFR = "La Grande Migration a semé les graines du courage et de la liberté sur tout le Continent d’Atlasia. Elle a fait voler en éclat les mensonges des dieux. Et permis aux hommes de regarder enfin leurs émotions en face.",
          DialogueId = 80170231,
          GUID = "C8B2A086",
          NextDialogue = 80170232,
          SpeakNpcId = 91502,
          Subtitle = "The Great Migration shed the light of courage and freedom across the Atlasia Continent, piercing through the veils of deceit woven by the gods. For the first time, people were allowed to confront their own desires and emotions.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A086"
        },
        [80170232] = {
          ContentFR = "Même aujourd’hui, des siècles plus tard... Des gens ouvrent les vieux livres, découvrent cette lumière... Et reprennent le flambeau.",
          DialogueId = 80170232,
          GUID = "C8B2A0B0",
          NextDialogue = 80170233,
          SpeakNpcId = 91502,
          Subtitle = "Even after centuries, that spark of light endures in the weighty tomes of history, continuing to inspire those who strive toward the world envisioned by the young man and woman.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A0B0"
        },
        [80170233] = {
          ContentFR = "...",
          DialogueId = 80170233,
          GUID = "C8B2A0DA",
          NextDialogue = 80170234,
          SpeakNpcId = 790008,
          Subtitle = "Mmm...",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A0DA"
        },
        [80170234] = {
          ContentFR = "Tu voulais un conseil. Mais vois-tu... j’ai passé tant d’années loin du monde... Je ne sais plus vraiment donner de réponses précises.",
          DialogueId = 80170234,
          GUID = "C8B2A104",
          NextDialogue = 80170235,
          SpeakNpcId = 91502,
          Subtitle = "You asked for my advice earlier, but having lived in seclusion for so long, I find it difficult to offer concrete guidance.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A104"
        },
        [80170235] = {
          ContentFR = "Tout ce que je peux te dire, c’est ceci : Plus on vit longtemps... plus on comprend que ce qui compte, ce ne sont pas les grandes victoires. Ce sont les moments. Les instants où tu as résisté. Où tu as agi selon ton cœur. Ces instants-là... rien ni personne ne pourra jamais les effacer.",
          DialogueId = 80170235,
          GUID = "C8B2A12E",
          NextDialogue = 80170236,
          SpeakNpcId = 91502,
          Subtitle = "What I can share with you is: the longer I have lived, the more I've come to realise that what's truly precious in life lies in those fleeting moments. The moments you've fought for what you cherish will remain timeless, regardless of the outcome.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A12E"
        },
        [80170236] = {
          ContentFR = "Alors n’aie pas peur, {nickname}. N’hésite pas. Tu as en toi une force hors du commun. Et j’ai la conviction... que tu laisseras ta propre lumière dans le cours du temps.",
          DialogueId = 80170236,
          GUID = "C8B2A158",
          NextOptions = {
            [1] = 801702361,
            [2] = 801702362
          },
          SpeakNpcId = 91502,
          Subtitle = ", do not fear, nor hesitate — within you lies extraordinary strength, and I have no doubt that you will leave an indelible mark upon the course of time.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A158"
        },
        [80170237] = {
          ContentFR = "Je le crois, oui. De tout cœur.",
          DialogueId = 80170237,
          FacialId = {
            [1] = "91502:Satisfy01"
          },
          GUID = "C8B2A182",
          NextDialogue = 80170238,
          SpeakNpcId = 91502,
          Subtitle = "I have faith in you.",
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A182"
        },
        [80170238] = {
          ContentFR = "Et pour l’instant... Oublions tout ça un instant. Buvons cette théière ensemble. Et profitons de cette paix si rare.",
          DialogueId = 80170238,
          GUID = "C8B2A1AC",
          SpeakNpcId = 91502,
          Subtitle = "For now... let us set aside the weight of our thoughts and savour this rare moment of peace together, over a pot of tea.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A1AC"
        },
        [80170301] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentFR = "Bonjour, mon enfant. Tu sembles aller bien mieux que la dernière fois.",
          DialogueId = 80170301,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2AC02",
          LookAt = {
            [1] = "91502:p(18000P1)"
          },
          NextOptions = {
            [1] = 801703011,
            [2] = 801703012
          },
          SpeakNpcId = 91502,
          Subtitle = "Greetings, my child. You seem much improved since last time.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC02"
        },
        [80170302] = {
          ContentFR = "Je suis heureuse si mes récits ont pu t’être utiles. Et aujourd’hui ? Y a-t-il un sujet que tu aimerais aborder ?",
          DialogueId = 80170302,
          FacialId = {
            [1] = "91502:Happy01"
          },
          GUID = "C8B2AC2C",
          NextDialogue = 80170303,
          SpeakNpcId = 91502,
          Subtitle = "I am pleased that my story was of some help to you. Now, is there anything on your mind today that you'd like to discuss?",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC2C"
        },
        [80170303] = {
          ContentFR = "Je me demandais... que penses-tu des \"erreurs\", Dame Nifle ?",
          DialogueId = 80170303,
          GUID = "C8B2AC56",
          NextDialogue = 80170304,
          SpeakNpcId = 790008,
          Subtitle = "I've been wondering... What are your thoughts on \"mistakes,\" Lady Nifle?",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC56"
        },
        [80170304] = {
          ContentFR = "J’ai traversé tant d’épreuves... perdu tant de choses. Parfois, je ne peux m’empêcher de penser : et si j’avais fait d’autres choix ? Est-ce que tout aurait pu mieux se passer ?",
          DialogueId = 80170304,
          GUID = "C8B2AC80",
          NextDialogue = 80170305,
          SpeakNpcId = 790008,
          Subtitle = "I... I've been through so much, and lost even more. At times, I wonder if I've made the wrong choices. If I had taken a different path, would things have turned out differently?",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC80"
        },
        [80170305] = {
          ContentFR = "Mais je ne peux pas revenir en arrière. Je ne connaîtrai jamais la réponse.",
          DialogueId = 80170305,
          GUID = "C8B2ACAA",
          NextDialogue = 80170306,
          SpeakNpcId = 790008,
          Subtitle = "But I can't go back in time, and so, I'll never know the answer.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ACAA"
        },
        [80170306] = {
          ContentFR = "Je comprends ce tourment. Alors, laisse-moi te conter aujourd’hui une histoire... sur les erreurs. C’est l’histoire d’un couple.",
          DialogueId = 80170306,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2ACD4",
          NextDialogue = 80170307,
          SpeakNpcId = 91502,
          Subtitle = "Mmm... I can see your confusion. Well then, allow me to share a tale about \"mistakes\" this time. It is the story of a couple.",
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ACD4"
        },
        [80170307] = {
          ContentFR = "Ils vivaient à la lisière d’Élysium. Lui était chasseur, elle était servante dans la ville. Ils désiraient un enfant, mais le destin s’était longtemps refusé à eux.",
          DialogueId = 80170307,
          GUID = "C8B2ACFE",
          NextDialogue = 80170308,
          SpeakNpcId = 91502,
          Subtitle = "They lived on the outskirts of Elysium. He was a hunter, and she, a maid in the city. For years, they yearned for a child, yet fate remained unyielding to their prayers.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ACFE"
        },
        [80170308] = {
          ContentFR = "Un jour, dans la forêt, le mari croisa une enfant errante, sale, blessée, tremblante. Elle faisait peine à voir. Il la ramena chez lui.",
          DialogueId = 80170308,
          GUID = "C8B2AD28",
          NextDialogue = 80170309,
          SpeakNpcId = 91502,
          Subtitle = "Then, one day, while hunting in the forest, the man stumbled upon a wandering child — battered, bloodied, and trembling in the cold. A pitiful sight indeed. Without hesitation, he brought her home.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AD28"
        },
        [80170309] = {
          ContentFR = "Sa femme lui donna un bain. Elle n’avait pas de blessures apparentes, mais semblait profondément traumatisée. Elle ne parlait pas, les yeux grands ouverts, figés.",
          DialogueId = 80170309,
          GUID = "C8B2AD52",
          NextDialogue = 80170310,
          SpeakNpcId = 91502,
          Subtitle = "His wife bathed the child and found no visible wounds upon her frail form. Yet, the child seemed to have been deeply traumatized. No matter what they asked, she simply stared at them, unblinking and silent.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AD52"
        },
        [80170310] = {
          ContentFR = "Le couple décida de l’héberger quelque temps. Grâce à leur bienveillance, la fillette reprit peu à peu vie, réagissant au monde, et finit enfin par prononcer ses premiers mots.",
          DialogueId = 80170310,
          GUID = "C8B2AD7C",
          NextDialogue = 80170311,
          SpeakNpcId = 91502,
          Subtitle = "Still, the couple took her in, tending to her with patience and care. In time, the girl, like a frost-laden bud beneath the warmth of spring, began to open herself to the world once more. And one day, at long last, she spoke.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AD7C"
        },
        [80170311] = {
          ContentFR = "Elle leur dit qu’elle avait perdu ses parents. Après réflexion, le couple décida de l’adopter. Ils la chérissaient comme leur propre fille, et l’enfant leur rendait bien leur amour. Une vraie petite famille était née.",
          DialogueId = 80170311,
          GUID = "C8B2ADA6",
          NextOptions = {
            [1] = 801703111
          },
          SpeakNpcId = 91502,
          Subtitle = "She told them she had lost her birth parents. After some deliberation, the couple chose to adopt her as their own. They showered her with kindness, and in return, she blossomed into a sweet and well-mannered daughter. Thus, beneath their humble roof, a family found its quiet harmony.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ADA6"
        },
        [80170312] = {
          ContentFR = "En apparence, oui. Mais cette enfant cachait un terrible secret.",
          DialogueId = 80170312,
          FacialId = {
            [1] = "91502:Unhappy01"
          },
          GUID = "C8B2ADD0",
          NextDialogue = 80170313,
          SpeakNpcId = 91502,
          Subtitle = "On the surface, yes. But beneath it all, the girl carried with her a terrible secret.",
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ADD0"
        },
        [80170313] = {
          ContentFR = "Elle était née dans une famille d’hérétiques, qui vénéraient les anciens mythes Charon. Ses parents avaient été exécutés. Elle, seule, avait survécu, grâce à une étrange capacité d’auto-guérison.",
          DialogueId = 80170313,
          GUID = "C8B2ADFA",
          NextDialogue = 80170314,
          SpeakNpcId = 91502,
          Subtitle = "She was born into a family of heretics, followers of the ancient Charon myths. As a result, her parents were executed, and yet she survived — saved by a mysterious healing gift that she possessed.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ADFA"
        },
        [80170314] = {
          ContentFR = "Ses mains en lambeaux, elle avait creusé sa propre tombe pour s’échapper, avant de fuir à travers bois.",
          DialogueId = 80170314,
          GUID = "C8B2AE24",
          NextDialogue = 80170315,
          SpeakNpcId = 91502,
          Subtitle = "With hands horribly mutilated, she dug herself free from their graves and fled into the wilderness, seeking refuge in the forests.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AE24"
        },
        [80170315] = {
          ContentFR = "En Élysium, il n’existe pas de crime plus grave que celui d’hérésie. Si la vérité venait à se savoir, ses parents adoptifs l’auraient sans doute abandonnée... ou pire.",
          DialogueId = 80170315,
          GUID = "C8B2AE4E",
          NextDialogue = 80170316,
          SpeakNpcId = 91502,
          Subtitle = "In Elysium, nothing was deemed more sinful than heresy. Had her secret been revealed, even if her adoptive parents did not have the heart to hand her over to the executioners, they would have undoubtedly abandoned her.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AE4E"
        },
        [80170316] = {
          ContentFR = "Mais elle tenait trop à cette nouvelle chaleur qu’elle appelait « foyer ». Alors, elle fit le choix de se taire, espérant secrètement que la vérité ne ressurgirait jamais.",
          DialogueId = 80170316,
          GUID = "C8B2AE78",
          NextDialogue = 80170317,
          SpeakNpcId = 91502,
          Subtitle = "Having at last found a place she could call \"home,\" the girl could not bear the thought of losing it. Thus, she chose to conceal her true identity, clinging to the fragile hope that the truth would remain undiscovered.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AE78"
        },
        [80170317] = {
          ContentFR = "Les années passèrent. La fillette grandit, choyée. Son secret resta bien enfoui. Elle finit même par l’oublier, croyant pouvoir mener une vie heureuse pour toujours.",
          DialogueId = 80170317,
          GUID = "C8B2AEA2",
          NextDialogue = 80170318,
          SpeakNpcId = 91502,
          Subtitle = "Time passed, and under the care of her adoptive parents, the girl grew. Her secret remained well-guarded, and as the years went by, she even forgot it herself. She began to believe that, with her new family, she could live a happy, peaceful life forever.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AEA2"
        },
        [80170318] = {
          ContentFR = "Quand sa mère adoptive lui proposa de venir en ville travailler dans un manoir comme domestique, elle accepta sans méfiance. Après tout, ce n’était qu’un humble emploi.",
          DialogueId = 80170318,
          GUID = "C8B2AECC",
          NextDialogue = 80170319,
          SpeakNpcId = 91502,
          Subtitle = "When her adoptive mother suggested they travel to the city, to work and experience the world beyond, the girl did not hesitate. After all, they would merely be lowly maids in the houses of the nobility, unnoticed and insignificant.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AECC"
        },
        [80170319] = {
          ContentFR = "Mais un jour, sa mère brisa accidentellement un objet précieux. Selon les règles de la maison, cela valait une flagellation. L’enfant, ne supportant pas cette idée, s’accusa à sa place.",
          DialogueId = 80170319,
          GUID = "C8B2AEF6",
          NextDialogue = 80170320,
          SpeakNpcId = 91502,
          Subtitle = "One day, while cleaning, her adoptive mother accidentally broke a valuable artefact. According to her employer's house rules, such a mistake would result in a flogging. Unable to bear the thought of her mother enduring such a punishment, the girl decided to take the blame herself.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AEF6"
        },
        [80170320] = {
          ContentFR = "Le fouet la lacéra violemment... mais quelques minutes plus tard, sa peau était intacte.",
          DialogueId = 80170320,
          GUID = "C8B2AF20",
          NextDialogue = 80170321,
          SpeakNpcId = 91502,
          Subtitle = "As the flogging began, the whip tore into her skin, leaving a gaping wound. Yet, within moments, the wound healed, as though no harm had been done.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF20"
        },
        [80170321] = {
          ContentFR = "Ce \"miracle\" parvint jusqu’à l’oreille du maître des lieux, le noble Seigneur \"Générosité\". Il accourut, planta une dague dans la poitrine de la fillette... et vit, stupéfait, qu’elle ne mourait pas.",
          DialogueId = 80170321,
          GUID = "C8B2AF4A",
          NextDialogue = 80170322,
          SpeakNpcId = 91502,
          Subtitle = "This \"miracle\" soon reached the ears of the house's master — Lord \"Generous.\" He rushed to the scene, and with a swift motion, plunged a knife into the girl's chest. She fought through the agony for minutes, only to rise again, alive.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF4A"
        },
        [80170322] = {
          ContentFR = "Il la fit enfermer, enquêta sur son passé, et découvrit qu’elle était la fille des deux hérétiques exécutés autrefois.",
          DialogueId = 80170322,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B2AF74",
          NextDialogue = 80170323,
          SpeakNpcId = 91502,
          Subtitle = "Lord \"Generous\" took her away. Upon investigation, he discovered that she was the daughter of the two heretics from years past.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF74"
        },
        [80170323] = {
          ContentFR = "D’abord furieux, il eut vite une idée \"brillante\" : ce pouvoir, jamais vu à Élysium, pouvait passer pour une manifestation divine. En l’exploitant ainsi, il gagnerait richesse et prestige.",
          DialogueId = 80170323,
          GUID = "C8B2AF9E",
          NextDialogue = 80170324,
          SpeakNpcId = 91502,
          Subtitle = "At first, he was enraged. But then, a \"brilliant\" idea crossed his mind: if he could exploit her power, which had never been seen in Elysium, masking it as a \"divine miracle,\" it would not only be profitable but would also thrust him into the spotlight.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF9E"
        },
        [80170324] = {
          ContentFR = "Mais pour cela, il fallait effacer toute trace de son passé. Il l’enferma, inventa une nouvelle identité... et fit exécuter sa mère adoptive dans le secret.",
          DialogueId = 80170324,
          GUID = "C8B2AFC8",
          NextOptions = {
            [1] = 801703241
          },
          SpeakNpcId = 91502,
          Subtitle = "To achieve this, however, he needed to conceal her true identity. So, he imprisoned her, created a new identity for her, and secretly had her adoptive mother executed.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AFC8"
        },
        [80170325] = {
          ContentFR = "La fillette regretta amèrement. Si elle n’avait pas caché son origine, ses parents adoptifs n’auraient jamais souffert autant.",
          DialogueId = 80170325,
          GUID = "C8B2AFF2",
          NextDialogue = 80170326,
          SpeakNpcId = 91502,
          Subtitle = "The girl was filled with deep regret. Had she not hidden her true identity in her desperate search for the warmth of a family, her kind, innocent adoptive parents would never have suffered such a fate.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AFF2"
        },
        [80170326] = {
          ContentFR = "Même après avoir été libérée par la résistance lors de la Grande Migration, elle ne retourna jamais voir son père adoptif. Cette rencontre... avait été une erreur. Elle ne voulait pas lui nuire davantage.",
          DialogueId = 80170326,
          GUID = "C8B2B01C",
          NextDialogue = 80170327,
          SpeakNpcId = 91502,
          Subtitle = "Though the girl was rescued by the resistance during the Great Migration, she never sought out her adoptive father again. Their encounter had been a mistake from the beginning, and she did not want to bring any further misfortune upon him.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B01C"
        },
        [80170327] = {
          ContentFR = "Pendant des décennies, elle garda ce fardeau en elle, se demandant ce qu’il était devenu. Puis un jour, alors que je passais par Élysium, je suis allée le voir à sa place.",
          DialogueId = 80170327,
          FacialId = {
            [1] = "91502:None"
          },
          GUID = "C8B2B046",
          NextDialogue = 80170328,
          SpeakNpcId = 91502,
          Subtitle = "For decades, she could not rid herself of the burden of the past, constantly worrying about her adoptive father's well-being. In time, as my journey took me through Elysium, I visited him on her behalf.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B046"
        },
        [80170328] = {
          ContentFR = "Il était devenu un vieil homme aux tempes grisonnantes. Caché depuis des années. En me voyant, il fut surpris qu’on se souvienne encore de son nom.",
          DialogueId = 80170328,
          GUID = "C8B2B070",
          NextDialogue = 80170329,
          SpeakNpcId = 91502,
          Subtitle = "By then, her adoptive father had grown old, his hair streaked with silver. He had spent much of his life in hiding, and when I showed up, he was astonished that anyone still remembered his name.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B070"
        },
        [80170329] = {
          ContentFR = "Comme elle me l’avait demandé, je n’ai pas dit pourquoi j’étais là. J’ai seulement parlé avec lui, comme le ferait une passeuse d’âmes, évoquant le passé.",
          DialogueId = 80170329,
          GUID = "C8B2B09A",
          NextDialogue = 80170330,
          SpeakNpcId = 91502,
          Subtitle = "Honouring the girl's wishes, I did not reveal the true purpose of my visit. Instead, I simply sat with him as a Ferrywoman, reminiscing about days long past.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B09A"
        },
        [80170330] = {
          ContentFR = "Il se souvenait de tout. De la nuit où il avait tout perdu. De sa fuite. De ses années d’errance.",
          DialogueId = 80170330,
          GUID = "C8B2B0C4",
          NextDialogue = 80170331,
          SpeakNpcId = 91502,
          Subtitle = "He remembered everything vividly — the night he lost both his wife and daughter, the moment his life unravelled, casting him into a fugitive's existence, wandering from place to place in perpetual flight.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B0C4"
        },
        [80170331] = {
          ContentFR = "Mais contre toute attente, il me dit ceci : il ne regrettait pas d’avoir recueilli cette enfant.",
          DialogueId = 80170331,
          FacialId = {
            [1] = "91502:Shock01"
          },
          GUID = "C8B2B0EE",
          NextDialogue = 80170332,
          SpeakNpcId = 91502,
          Subtitle = "And yet, to my surprise, he told me he had no regrets in choosing to take the girl in.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B0EE"
        },
        [80170332] = {
          ContentFR = "Il me tendit une petite boîte, les cendres de sa femme. Il attendait depuis longtemps une Passeuse, pour lui offrir enfin un repos mérité.",
          DialogueId = 80170332,
          GUID = "C8B2B118",
          NextDialogue = 80170333,
          SpeakNpcId = 91502,
          Subtitle = "He then handed me a small box — a keepsake containing his wife's ashes. He told me he had long been waiting for a Ferrywoman, so that her soul might finally find peace.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B118"
        },
        [80170333] = {
          ContentFR = "C’est ainsi que j’ai pu, après tant d’années, célébrer un adieu trop longtemps différé. Et dans ce silence, j’ai cru entendre un murmure...",
          DialogueId = 80170333,
          GUID = "C8B2B142",
          NextDialogue = 80170334,
          SpeakNpcId = 91502,
          Subtitle = "With quiet astonishment, I performed the long-overdue farewell ritual for his wife. To my surprise, even after all these years, I could still hear the whisper of her soul...",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B142"
        },
        [80170334] = {
          ContentFR = "Elle disait, comme son époux : « Merci d’avoir été notre fille. »",
          DialogueId = 80170334,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2B16C",
          NextDialogue = 80170335,
          SpeakNpcId = 91502,
          Subtitle = "She spoke the same words as her husband: \"Thank you for becoming our daughter.\"",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B16C"
        },
        [80170335] = {
          ContentFR = "Le vieil homme m’a confié qu’ils avaient su, dès le début, qui elle était. Le soir où ses parents ont été exécutés, ils avaient vu les bourreaux, torches en main, s’enfoncer dans la forêt.",
          DialogueId = 80170335,
          GUID = "C8B2B196",
          NextDialogue = 80170336,
          SpeakNpcId = 91502,
          Subtitle = "He then told me that, from the very beginning, they had known the girl's true identity. On the night her parents were executed, they watched as the executioners, torches in hand, marched into the forest.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B196"
        },
        [80170336] = {
          ContentFR = "Alors, le lendemain, quand ils ont vu cette fillette errante, ils ont deviné sa véritable identité. Ils ont choisi de l’adopter en sachant parfaitement ce que cela impliquait.",
          DialogueId = 80170336,
          GUID = "C8B2B1C0",
          NextDialogue = 80170337,
          SpeakNpcId = 91502,
          Subtitle = "And the next morning, when they saw the wandering girl, they recognized her at once. Fully aware of the consequences, they made their choice to take her in.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B1C0"
        },
        [80170337] = {
          ContentFR = "Pour eux, rencontrer cette enfant, la protéger, l’élever... c’était un bonheur. Même si ce bonheur était menacé, ils l’ont accepté sans regret.",
          DialogueId = 80170337,
          GUID = "C8B2B1EA",
          NextDialogue = 80170338,
          SpeakNpcId = 91502,
          Subtitle = "For them, meeting the girl, protecting her, and raising her brought great joy. Though it was a joy shadowed by danger, they embraced it without hesitation.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B1EA"
        },
        [80170338] = {
          ContentFR = "Il m’a dit que sa seule véritable erreur, c’était de ne pas avoir eu le courage de fuir plus tôt. Peut-être qu’alors, ils auraient pu vivre ensemble, heureux, ailleurs.",
          DialogueId = 80170338,
          GUID = "C8B2B214",
          NextDialogue = 80170339,
          SpeakNpcId = 91502,
          Subtitle = "The old man confided that his only regret was lacking the courage to leave sooner. Had he taken his wife and daughter away from Elysium earlier, perhaps they might still have been living a peaceful life together today.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B214"
        },
        [80170339] = {
          ContentFR = "Depuis ce jour, cet ancien chasseur est devenu un véritable \"hérétique\", aidant des civils à fuir Élysium, dans l’ombre, pendant des années.",
          DialogueId = 80170339,
          GUID = "C8B2B23E",
          NextOptions = {
            [1] = 801703391
          },
          SpeakNpcId = 91502,
          Subtitle = "And so, in the years that followed, the once wronged hunter became a true \"heretic.\" For decades, he quietly aided Elysium's oppressed, guiding them across the border to freedom.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B23E"
        },
        [80170340] = {
          ContentFR = "... Je ne l’ai pas dit à voix haute. Mais à voir son regard serein... je crois qu’il l’avait deviné.",
          DialogueId = 80170340,
          GUID = "C8B2B268",
          NextDialogue = 80170341,
          SpeakNpcId = 91502,
          Subtitle = "...I did not say it outright. Yet, from the quiet relief in his eyes, I believe he had already understood.",
          TalkActionId = {
            [1] = "91502:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B268"
        },
        [80170341] = {
          ContentFR = "Ils ne se reverront peut-être jamais... mais savoir que l’autre vit encore, en paix, c’est déjà un réconfort.",
          DialogueId = 80170341,
          GUID = "C8B2B292",
          NextDialogue = 80170342,
          SpeakNpcId = 790008,
          Subtitle = "Though they may never meet again, knowing that their loved ones are safe is, perhaps, comfort enough.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B292"
        },
        [80170342] = {
          ContentFR = "Finalement, ce n’est pas une fin si triste...",
          DialogueId = 80170342,
          GUID = "C8B2B2BC",
          NextDialogue = 80170343,
          SpeakNpcId = 790008,
          Subtitle = "This story's ending doesn't seem so tragic after all.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B2BC"
        },
        [80170343] = {
          ContentFR = "Non. Et en l’écoutant, je me suis dit ceci...",
          DialogueId = 80170343,
          GUID = "C8B2B2E6",
          NextDialogue = 80170344,
          SpeakNpcId = 91502,
          Subtitle = "Indeed. Hearing his words, I found myself reflecting...",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B2E6"
        },
        [80170344] = {
          ContentFR = "Nous, les humains, nous faisons tous des erreurs. Par aveuglement. Par espoir. Ou même délibérément.",
          DialogueId = 80170344,
          FacialId = {
            [1] = "91502:Confident01"
          },
          GUID = "C8B2B310",
          NextDialogue = 80170345,
          SpeakNpcId = 91502,
          Subtitle = "As long as we live, mistakes are inevitable. Some stem from a narrow vision, others from misplaced hope, and at times, even willful ignorance.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B310"
        },
        [80170345] = {
          ContentFR = "Mais une erreur ne mène pas toujours à une mauvaise fin. Sa douleur ou sa douceur, seuls ceux qui l’ont vécue peuvent vraiment en juger.",
          DialogueId = 80170345,
          GUID = "C8B2B33A",
          NextDialogue = 80170346,
          SpeakNpcId = 91502,
          Subtitle = "However, a misguided choice does not always yield a misguided outcome. The taste of its sweetness or bitterness is known only to those who have lived through it.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B33A"
        },
        [80170346] = {
          ContentFR = "Ce qui compte plus que nos erreurs... c’est ce que nous faisons de l’avenir.",
          DialogueId = 80170346,
          GUID = "C8B2B364",
          NextDialogue = 80170347,
          SpeakNpcId = 91502,
          Subtitle = "What truly matters, more than the mistake itself, is the future that lies before us.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B364"
        },
        [80170347] = {
          ContentFR = "Nous pouvons réparer. Changer. Donner un sens nouveau à ce que nous avons traversé.",
          DialogueId = 80170347,
          GUID = "C8B2B38E",
          NextDialogue = 80170348,
          SpeakNpcId = 91502,
          Subtitle = "It grants us the opportunity to make amends, to bring about change, and to transform what we've endured into something more meaningful.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B38E"
        },
        [80170348] = {
          ContentFR = "Et ce vieil homme... quand il m’a parlé de tout cela, ce n’est ni le remords ni le chagrin que j’ai vus dans ses yeux. C’était de la paix. Et même un peu de bonheur.",
          DialogueId = 80170348,
          GUID = "C8B2B3B8",
          NextOptions = {
            [1] = 801703481
          },
          SpeakNpcId = 91502,
          Subtitle = "Perhaps that is why, when the old man spoke to me of his past, there was neither regret nor sorrow in his eyes — only the quiet contentment of one who has made peace with his journey.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B3B8"
        },
        [80170349] = {
          ContentFR = "Merci pour cette histoire. J’en ai encore beaucoup appris aujourd’hui.",
          DialogueId = 80170349,
          GUID = "C8B2B3E2",
          NextDialogue = 80170350,
          SpeakNpcId = 790008,
          Subtitle = "Thank you for sharing this story with me. I've learned so much today, just like before.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B3E2"
        },
        [80170350] = {
          ContentFR = "Hé hé... c’est à moi de te remercier, en vérité.",
          DialogueId = 80170350,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2B40C",
          NextDialogue = 80170351,
          SpeakNpcId = 91502,
          Subtitle = "Hehe, it is I who should thank you.",
          TalkActionId = {
            [1] = "91502:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B40C"
        },
        [80170351] = {
          ContentFR = "Avec l’âge, je deviens sans doute trop bavarde... Merci de m’avoir écoutée, toi qui prends le temps d’écouter les vieux souvenirs d’une vieille femme.",
          DialogueId = 80170351,
          GUID = "C8B2B436",
          SpeakNpcId = 91502,
          Subtitle = "Perhaps it's my age, but I do tend to be long-winded. I appreciate your patience — for keeping this old lady company and listening to my endless ramblings about the past.",
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B436"
        },
        [80170401] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentFR = "Te voilà, mon enfant. Dis-moi, que souhaites-tu entendre aujourd’hui ?",
          DialogueId = 80170401,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2BC6A",
          LookAt = {
            [1] = "91502:p(18000P1)"
          },
          NextOptions = {
            [1] = 801704011
          },
          SpeakNpcId = 91502,
          Subtitle = "Ah, you've arrived, my child. Tell me, what is it you wish to speak of today?",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BC6A"
        },
        [80170402] = {
          ContentFR = "Aujourd’hui, j’aimerais entendre ton histoire, Dame Nifle. La tienne.",
          DialogueId = 80170402,
          GUID = "C8B2BC94",
          NextDialogue = 80170403,
          SpeakNpcId = 790008,
          Subtitle = "Lady Nifle, today... I'd like to hear your story.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BC94"
        },
        [80170403] = {
          ContentFR = "Mon histoire, hmm... Tu es perspicace, je suis certaine que tu l’as devinée, au moins en partie.",
          DialogueId = 80170403,
          GUID = "C8B2BCBE",
          NextOptions = {
            [1] = 801704031,
            [2] = 801704032
          },
          SpeakNpcId = 91502,
          Subtitle = "My story, hmm... You are an insightful child. I suspect you have already caught glimpses of it, have you not?",
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BCBE"
        },
        [80170404] = {
          ContentFR = "Les histoires que tu as partagées... ce sont en réalité des épisodes de ta propre vie, n’est-ce pas ?",
          DialogueId = 80170404,
          GUID = "C8B2BCE8",
          NextDialogue = 80170405,
          SpeakNpcId = 790008,
          Subtitle = "The stories you've told me... they are all your own experiences, aren't they?",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BCE8"
        },
        [80170405] = {
          ContentFR = "C’est exact.",
          DialogueId = 80170405,
          GUID = "C8B2BD12",
          NextDialogue = 80170407,
          SpeakNpcId = 91502,
          Subtitle = "Indeed.",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD12"
        },
        [80170406] = {
          ContentFR = "Mon histoire est dissimulée dans celles que je t’ai déjà contées.",
          DialogueId = 80170406,
          GUID = "C8B2BD3C",
          NextDialogue = 80170407,
          SpeakNpcId = 91502,
          Subtitle = "The truth is, my story is interwoven with the very tales I have shared with you.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD3C"
        },
        [80170407] = {
          ContentFR = "Ce sont les récits d’autres vies... mais ils sont aussi les miens.",
          DialogueId = 80170407,
          GUID = "C8B2BD66",
          NextDialogue = 80170408,
          SpeakNpcId = 91502,
          Subtitle = "They are not merely events that happened; they are, in truth, fragments of my own past.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD66"
        },
        [80170408] = {
          ContentFR = "J’ai été cette femme dotée d’un pouvoir incapable d’adoucir la souffrance des autres. Cette jeune fille enfermée dans un sanctuaire, incapable de se défendre. Cette enfant dont l’existence a causé la perte de ses parents adoptifs.",
          DialogueId = 80170408,
          GUID = "C8B2BD90",
          NextDialogue = 80170409,
          SpeakNpcId = 91502,
          Subtitle = "I am the woman who bore a gift yet failed to ease people's suffering. I am the helpless girl once imprisoned in the temple's cold embrace. I am the child whose very existence became the harbinger of misfortune for those who took her in.",
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD90"
        },
        [80170409] = {
          ContentFR = "Peut-être... Mais j’aimerais l’entendre autrement. Pas comme une témoin, mais comme l’héroïne. Toi, Nifle. Raconte ton histoire, en ton nom.",
          DialogueId = 80170409,
          GUID = "C8B2BDBA",
          NextDialogue = 80170410,
          SpeakNpcId = 790008,
          Subtitle = "Right... but still, I wish to hear it from you directly — not as an observer, but as you, Nifle, the protagonist of your own story.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BDBA"
        },
        [80170410] = {
          ContentFR = "Je vois... Très bien. Puisque tu y tiens, je vais, pour une fois, replonger dans mes souvenirs.",
          DialogueId = 80170410,
          GUID = "C8B2BDE4",
          NextDialogue = 80170411,
          SpeakNpcId = 91502,
          Subtitle = "Ah... I see. Very well. Since you wish to hear it, I shall, albeit uncharacteristically, recount my past.",
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BDE4"
        },
        [80170411] = {
          ContentFR = "Je suis née en Élysium, dans une famille qui vénérait les anciens mythes des Charons.",
          DialogueId = 80170411,
          GUID = "C8B2BE0E",
          NextDialogue = 80170412,
          SpeakNpcId = 91502,
          Subtitle = "I was born in Elysium, into a family devoted to the ancient Charon myths.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE0E"
        },
        [80170412] = {
          ContentFR = "J’avais dix ans quand mes parents furent exécutés pour hérésie. Je devais mourir avec eux... Mais à cet instant, je me suis éveillée en tant que Daimon. J’ai hérité de l’immortalité et j’ai survécu.",
          DialogueId = 80170412,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B2BE38",
          NextDialogue = 80170413,
          SpeakNpcId = 91502,
          Subtitle = "When I was ten, my parents were executed for heresy. I was meant to perish alongside them. Yet, in that moment, I unexpectedly awakened as a Daimon, gaining the power of immortality. And so, I survived.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE38"
        },
        [80170413] = {
          ContentFR = "Orpheline, j’ai erré seule dans la forêt jusqu’à ce qu’un chasseur me recueille. Grâce à lui, j’ai connu un second foyer.",
          DialogueId = 80170413,
          GUID = "C8B2BE62",
          NextDialogue = 80170414,
          SpeakNpcId = 91502,
          Subtitle = "Orphaned and adrift, I wandered the forests until a passing hunter found me. He took me in, offering the quiet warmth of a home I had lost.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE62"
        },
        [80170414] = {
          ContentFR = "À dix-huit ans, mon secret fut dévoilé par accident. C’est ainsi que le noble Seigneur \"Générosité\" apprit mon existence, et me gratifia du titre de \"Bénie\", un nom tressé d’épines.",
          DialogueId = 80170414,
          GUID = "C8B2BE8C",
          NextDialogue = 80170415,
          SpeakNpcId = 91502,
          Subtitle = "At eighteen, my true nature was inadvertently exposed. Word soon reached Lord \"Generous,\" who bestowed upon me the title of \"the Blessed One\" — a crown woven of thorns.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE8C"
        },
        [80170415] = {
          ContentFR = "Dès lors, ma vie se réduisit à un petit sanctuaire. Le Seigneur \"Générosité\", lui, s’enrichissait en vendant mon sang.",
          DialogueId = 80170415,
          GUID = "C8B2BEB6",
          NextDialogue = 80170416,
          SpeakNpcId = 91502,
          Subtitle = "For years, my world was confined within the walls of a small temple, while Lord \"Generous\" reaped immense wealth from selling my blood.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BEB6"
        },
        [80170416] = {
          ContentFR = "Ce cauchemar n’a pris fin qu’avec l’arrivée de deux rebelles courageux, le jeune érudit et la noble dame de mon deuxième récit. Mes sauveurs. Mes amis les plus chers. Ceux qui m’ont aidée à trouver ma voie.",
          DialogueId = 80170416,
          FacialId = {
            [1] = "91502:Confident01"
          },
          GUID = "C8B2BEE0",
          NextDialogue = 80170417,
          SpeakNpcId = 91502,
          Subtitle = "It was not until two brave souls — the young scholar and noblewoman from my second tale — rescued me from that lasting nightmare. They were my saviours, my dearest friends, and the ones who first cast light upon my path ahead.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BEE0"
        },
        [80170417] = {
          ContentFR = "Plus tard, Erika périt lors d’une bataille sur la route du nord. Quant à Alexis, s’il parvint à s’échapper, il ne trouva jamais le royaume idéal qu’il cherchait. Il s’éteignit seul, entouré de manuscrits inachevés.",
          DialogueId = 80170417,
          GUID = "C8B2BF0A",
          NextDialogue = 80170418,
          SpeakNpcId = 91502,
          Subtitle = "Later, Erika fell in battle during our journey north. As for Lexis, though he escaped, he never found the answers he sought for his ideal world. In the end, he faded away amidst stacks of unfinished manuscripts, his vision left incomplete.",
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF0A"
        },
        [80170418] = {
          ContentFR = "Durant mes années à Aethyrie, j’ai adopté une enfant. Pour la première fois, j’ai vu un être humain grandir sous mes yeux.",
          DialogueId = 80170418,
          GUID = "C8B2BF34",
          NextDialogue = 80170419,
          SpeakNpcId = 91502,
          Subtitle = "During my years in Aethyrie, I adopted a child. It was my first experience as a caretaker, witnessing a life unfold before my eyes.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF34"
        },
        [80170419] = {
          ContentFR = "Je l’ai vue passer du nourrisson fragile à la jeune fille rayonnante, puis à la femme posée et sage. Je me souviens de ses pleurs, de ses premiers mots, de sa première récitation des anciens vers...",
          DialogueId = 80170419,
          GUID = "C8B2BF5E",
          NextDialogue = 80170420,
          SpeakNpcId = 91502,
          Subtitle = "I watched her grow — from a tiny infant wrapped in swaddling clothes to a radiant young woman, and later into a figure of calm wisdom. I remember her first cries, her first words, the first time she recited the ancient verses...",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF5E"
        },
        [80170420] = {
          ContentFR = "Je me souviens de ses débats sans fin avec Alexis, et du moment où elle a accepté, en larmes, la clé de sa bibliothèque, au chevet de son lit de mort.",
          DialogueId = 80170420,
          GUID = "C8B2BF88",
          NextDialogue = 80170421,
          SpeakNpcId = 91502,
          Subtitle = "I recall her endless debates with Lexis, and the solemn moment when she accepted the key to his library as he lay upon his deathbed.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF88"
        },
        [80170421] = {
          ContentFR = "Chaque transformation m’a remplie de joie. Mais je savais aussi, avec une lucidité cruelle, qu’elle, comme Erika et Alexis, ne pourrait rester éternellement à mes côtés.",
          DialogueId = 80170421,
          GUID = "C8B2BFB2",
          NextDialogue = 80170422,
          SpeakNpcId = 91502,
          Subtitle = "Each change in her filled me with joy and pride. Yet, I remained painfully aware that, like Erika and Lexis, she too was bound by the limits of mortality. She could not stay by my side forever.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BFB2"
        },
        [80170422] = {
          ContentFR = "Ils sont tous partis. J’en ai pleuré, autrefois. Mais après ma rencontre avec les deux sœurs avides de mon sang, après tant de séparations, j’ai fini par accepter l’impermanence de ce monde.",
          DialogueId = 80170422,
          FacialId = {
            [1] = "91502:None"
          },
          GUID = "C8B2BFDC",
          NextDialogue = 80170423,
          SpeakNpcId = 91502,
          Subtitle = "In the end, they all left me. Once, I mourned their passing. But after meeting the two sisters who sought my blood, and bearing witness to countless partings between life and death, I came to accept the impermanence of this world.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BFDC"
        },
        [80170423] = {
          ContentFR = "J’ai renoncé aux joies comme aux chagrins. J’ai abandonné tout désir. Je n’ai plus ni colère ni peine face aux douleurs humaines. Depuis neuf siècles, je parcours les terres d’Atlasia, guidant les âmes défuntes.",
          DialogueId = 80170423,
          GUID = "C8B2C006",
          NextDialogue = 80170424,
          SpeakNpcId = 91502,
          Subtitle = "I have let go of both joy and sorrow, renounced desire, and no longer grieve or rage at the suffering woven into the fabric of existence. For the past nine centuries, I have wandered across Atlasia, guiding the souls of the departed.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C006"
        },
        [80170424] = {
          ContentFR = "Je me suis arrêtée ici, en Hyperborea, à cause d’une enfant dont le visage m’est étrangement familier. Mais je ne suis pas là pour intervenir, encore moins pour changer quoi que ce soit. Je veux simplement être témoin de son histoire.",
          DialogueId = 80170424,
          GUID = "C8B2C030",
          NextDialogue = 80170425,
          SpeakNpcId = 91502,
          Subtitle = "Now, I remain in Hyperborea for a time, drawn here by a child whose face is strangely familiar. Yet, I do not seek to meddle in conflicts or alter the course of fate. I wish only to bear witness to her story.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C030"
        },
        [80170425] = {
          ContentFR = "Bientôt, je repartirai. Rien ne pourra vraiment mettre fin à mon errance... sauf si la Mort, un jour, daigne enfin m’ouvrir les bras.",
          DialogueId = 80170425,
          GUID = "C8B2C05A",
          NextDialogue = 80170426,
          SpeakNpcId = 91502,
          Subtitle = "Soon enough, I will resume my journey. Nothing in this world will ever truly bring my wandering to a halt — unless, at last, death itself chooses to embrace me.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C05A"
        },
        [80170426] = {
          ContentFR = "Voilà mon histoire. Est-ce qu’elle t’a satisfaite, mon enfant ?",
          DialogueId = 80170426,
          GUID = "C8B2C084",
          NextOptions = {
            [1] = 801704261
          },
          SpeakNpcId = 91502,
          Subtitle = "—And that is my story. Tell me, my child, does it sate your curiosity?",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C084"
        },
        [80170427] = {
          ContentFR = "Je voudrais aussi savoir... avant tout ça. Avant l’immortalité, avant les drames. Qui était Nifle, à ce moment-là ?",
          DialogueId = 80170427,
          GUID = "C8B2C0AE",
          NextDialogue = 80170428,
          SpeakNpcId = 790008,
          Subtitle = "I would still like to know... before you assumed all these roles, before you gained immortality — what was Nifle like, back then?",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C0AE"
        },
        [80170428] = {
          ContentFR = "...",
          DialogueId = 80170428,
          FacialId = {
            [1] = "91502:Shock01"
          },
          GUID = "C8B2C0D8",
          NextDialogue = 80170429,
          SpeakNpcId = 91502,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C0D8"
        },
        [80170429] = {
          ContentFR = "Beaucoup s’interrogent sur mon passé, mais tu es {性别:le premier|la première} à me demander ce que fut mon enfance. Et pour être honnête, comparé à ce qui a suivi... ce sont des souvenirs bien simples, presque insignifiants.",
          DialogueId = 80170429,
          GUID = "C8B2C102",
          NextDialogue = 80170430,
          SpeakNpcId = 91502,
          Subtitle = "You are the first to ask of my childhood. Many have been curious about my past, but none have sought to know the life I led before fate wove me into grander tales. Compared to what followed, it was quite unremarkable.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C102"
        },
        [80170430] = {
          ContentFR = "Laisse-moi voir...",
          DialogueId = 80170430,
          FacialId = {
            [1] = "91502:Think01"
          },
          GUID = "C8B2C12C",
          NextDialogue = 80170431,
          SpeakNpcId = 91502,
          Subtitle = "Let me think...",
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C12C"
        },
        [80170431] = {
          ContentFR = "Mon tout premier foyer se trouvait au nord d’Élysium, dans une forêt luxuriante. Il n’y avait là ni nobles ni clergé, juste des lièvres, des baies sauvages et la paix.",
          DialogueId = 80170431,
          GUID = "C8B2C156",
          NextDialogue = 80170432,
          SpeakNpcId = 91502,
          Subtitle = "My first home — the one of my birth — lay deep within the northern forests of Elysium. There were no churches, no nobility — only the soft rustle of hares darting through the underbrush, and the fragrance of wild berries.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C156"
        },
        [80170432] = {
          ContentFR = "Mes souvenirs d’enfance... ce sont les éclats du soleil à travers les feuilles, et le murmure d’un ruisseau entre les pierres.",
          DialogueId = 80170432,
          GUID = "C8B2C180",
          NextDialogue = 80170433,
          SpeakNpcId = 91502,
          Subtitle = "My earliest memories are of dappled sunlight filtering through the leaves, and the gentle murmur of a stream winding its way through the quiet woods.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C180"
        },
        [80170433] = {
          ContentFR = "J’étais une enfant comme les autres. Je suppliais mon père de m’emmener jouer en forêt, et je trempais mes pieds dans la rivière en riant, malgré les avertissements de ma mère.",
          DialogueId = 80170433,
          GUID = "C8B2C1AA",
          NextDialogue = 80170434,
          SpeakNpcId = 91502,
          Subtitle = "In those days, I was no different from any other child. I would beg my father to take me into the forest to play, and I would ignore my mother's gentle warnings, splashing carelessly in the stream.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C1AA"
        },
        [80170434] = {
          ContentFR = "Ma mère, elle aussi, était passeuse d’âmes. Des inconnus venaient lui remettre de petits coffrets, puis elle dansait au clair de lune en les laissant dériver sur le courant.",
          DialogueId = 80170434,
          GUID = "C8B2C1D4",
          NextDialogue = 80170435,
          SpeakNpcId = 91502,
          Subtitle = "My mother, too, was a Ferrywoman. Strangers would pass through the forest, entrusting her with small caskets. Under the moonlight, she would dance, letting them drift down the river's current.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C1D4"
        },
        [80170435] = {
          ContentFR = "Je lui ai demandé un jour : « Que contiennent ces coffrets ? » Elle m’a répondu : « Des souvenirs que les gens chérissent. »",
          DialogueId = 80170435,
          GUID = "C8B2C1FE",
          NextDialogue = 80170436,
          SpeakNpcId = 91502,
          Subtitle = "Once, I asked her what lay within those caskets. She told me they carried what people cherished and missed dearly.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C1FE"
        },
        [80170436] = {
          ContentFR = "Alors j’ai demandé : « Mais pourquoi les jeter à la rivière ? » Et elle a dit : « Parce qu’il faut lâcher prise, si l’on veut avancer. »",
          DialogueId = 80170436,
          GUID = "C8B2C228",
          NextDialogue = 80170437,
          SpeakNpcId = 91502,
          Subtitle = "So I asked, \"Why would people cast away what they held dear?\" She said, \"Because to move forward, one must learn to let go.\"",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C228"
        },
        [80170437] = {
          ContentFR = "Je ne comprenais pas. Mon père m’a regardée, m’a ébouriffé les cheveux, et a dit en souriant : « Tu comprendras quand tu seras grande. »",
          DialogueId = 80170437,
          GUID = "C8B2C252",
          NextDialogue = 80170438,
          SpeakNpcId = 91502,
          Subtitle = "I did not understand. Sensing my confusion, my father only smiled, ruffled my hair, and said, \"One day, when you are older, you will understand.\"",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C252"
        },
        [80170438] = {
          ContentFR = "Mais ils n’ont jamais vu ce jour-là. Le jour où ils ont été tués... c’est celui où la petite Nifle, insouciante, a disparu à jamais.",
          DialogueId = 80170438,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B2C27C",
          NextOptions = {
            [1] = 801704381
          },
          SpeakNpcId = 91502,
          Subtitle = "But they never lived to see that day. The moment they were executed, the carefree days of the young Nifle came to an end.",
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C27C"
        },
        [80170439] = {
          ContentFR = "Il m’arrive d’y repenser. Mais je ne caresse pas ces souvenirs avec nostalgie, comme le font tant de gens. Je les laisse simplement flotter dans mon esprit, comme des feuilles mortes au fil du vent.",
          DialogueId = 80170439,
          FacialId = {
            [1] = "91502:None"
          },
          GUID = "C8B2C2A6",
          NextDialogue = 80170440,
          SpeakNpcId = 91502,
          Subtitle = "At times, memories of that distant past resurface. But unlike most, I do not cling to them with longing or nostalgia. I simply let them drift through my thoughts, like fallen leaves carried by the wind.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C2A6"
        },
        [80170440] = {
          ContentFR = "Pour moi, ce passé, comme tous les autres, fait partie de ma vie. Ni plus précieux, ni plus lourd.",
          DialogueId = 80170440,
          GUID = "C8B2C2D0",
          NextDialogue = 80170441,
          SpeakNpcId = 91502,
          Subtitle = "To me, the past — like all that has come and gone — is simply another thread woven into the fabric of my existence, neither weighted with sorrow nor imbued with special meaning.",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C2D0"
        },
        [80170441] = {
          ContentFR = "... Mais peut-être est-ce ta présence aujourd’hui qui me trouble un peu. En te parlant, il me semble qu’un léger remous agite encore les eaux calmes de mon cœur.",
          DialogueId = 80170441,
          GUID = "C8B2C2FA",
          NextDialogue = 80170442,
          SpeakNpcId = 91502,
          Subtitle = "And yet, as I recount these tales to you, I sense the faintest of ripples stirring within me...",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C2FA"
        },
        [80170442] = {
          ContentFR = "... Je suis fatiguée. Permets-moi de me reposer un instant.",
          DialogueId = 80170442,
          FacialId = {
            [1] = "91502:Close"
          },
          GUID = "C8B2C324",
          NextDialogue = 80170443,
          SpeakNpcId = 91502,
          Subtitle = "...I find myself weary. If you do not mind, I shall rest here for a moment.",
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C324"
        },
        [80170443] = {
          ContentFR = "<I>Dame Nifle ferme doucement les yeux, et vient appuyer sa tête contre ton épaule.</>",
          DialogueId = 80170443,
          GUID = "C8B2C34E",
          IsBlack = 1,
          NextDialogue = 80170444,
          Subtitle = "(As Lady Nifle speaks, she closes her eyes, her head gently coming to rest against your shoulder.)",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C34E"
        },
        [80170444] = {
          ContentFR = "<I>Sa respiration est calme, régulière. Elle semble paisible, presque heureuse... sans doute rêve-t-elle d’un temps ancien.</>",
          DialogueId = 80170444,
          GUID = "C8B2C378",
          IsBlack = 1,
          NextDialogue = 80170445,
          Subtitle = "(Her breathing slows, steady and serene, and a faint smile graces her lips. It seems she has drifted into a peaceful dream.)",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C378"
        },
        [80170445] = {
          ContentFR = "<I>Un rêve qui sent la chaleur du soleil et les baies sauvages... Peut-être même qu’un petit lièvre y bondit au loin, espiègle et libre.</>",
          DialogueId = 80170445,
          GUID = "C8B2C3A2",
          IsBlack = 1,
          Subtitle = "(A dream laced with the sweet scent of wild berries, bathed in the golden warmth of sunlight, where perhaps, a hare flits playfully through the underbrush in the distance...)",
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C3A2"
        },
        [80180001] = {
          DialogueId = 80180001,
          GUID = "C8B8E36A",
          SpeakNpcId = 790045,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8E36A"
        },
        [80180101] = {
          Camera = "452.71582,-120.713928,293.808594,0.000068,-25.999489,160.803513,30.000002,125.0,false,DoNotOverride,2.8",
          ContentFR = "<I>C’était il y a six mois. Je m’étais rendue à l’hôpital pour rendre visite à Roger Gaston, un vétéran blessé lors de la guerre contre l’Église Élyséenne, sur le front sud.</>",
          DialogueId = 80180101,
          FacialId = {
            [1] = "790045:Unhappy01"
          },
          FinalCamera = "452.71582,-120.713928,293.808594,0.000071,-23.999413,157.603546,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B8F3D2",
          NextDialogue = 80180102,
          SpeakNpcId = 790045,
          Subtitle = "(That was six months ago. I'd gone to visit Roger Gaston — a wounded veteran of the war against the Elysian Church on the Southern Front.)",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F3D2"
        },
        [80180102] = {
          Camera = "-17.312012,189.65033,156.878906,0.000039,-12.39904,-60.39682,30.000002,247.327988,false,Manual,3.162369",
          ContentFR = "Emilia... tu es là...",
          DialogueId = 80180102,
          FinalCamera = "-15.135742,190.885254,156.878906,0.00004,-12.399033,-61.39677,30.000002,247.327988,false,Manual,3.162369",
          GUID = "C8B8F3FC",
          NextDialogue = 80180103,
          SpeakNpcId = 790059,
          Subtitle = "Emilia... you've come...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F3FC"
        },
        [80180103] = {
          Camera = "93.808105,84.920227,124.542969,0.000044,9.600609,157.202698,30.000008,107.300728,false,Manual,3.162369",
          ContentFR = "...",
          DialogueId = 80180103,
          GUID = "C8B8F426",
          NextDialogue = 80180104,
          SpeakNpcId = 790045,
          Subtitle = "...",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F426"
        },
        [80180104] = {
          ContentFR = "... Oui, Papa. Je suis venue vous voir.",
          DialogueId = 80180104,
          GUID = "C8B8F450",
          NextDialogue = 80180105,
          SpeakNpcId = 790045,
          Subtitle = "...Yes, Father. I've come to see you.",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F450"
        },
        [80180105] = {
          Camera = "233.50293,-42.842896,169.013672,0.000073,-14.598969,150.198013,30.000002,247.327988,false,DoNotOverride,3.162369",
          ContentFR = "J’ai apporté quelques douceurs et du miel, les meilleurs de Dismania ! C’est la pâtisserie la plus célèbre de la ville. Je... j’espère que vous aimerez.",
          DialogueId = 80180105,
          FinalCamera = "233.50293,-42.842896,169.013672,0.000074,-10.998831,146.797302,30.000002,247.327988,false,DoNotOverride,3.162369",
          GUID = "C8B8F47A",
          NextDialogue = 80180106,
          SpeakNpcId = 790045,
          Subtitle = "I brought you some pastries and honey — from Dismania's most famous bakery. I... hope you like them.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F47A"
        },
        [80180106] = {
          Camera = "-0.36084,492.293091,78.546875,0.000105,4.201092,-82.801735,30.000002,247.327988,false,DoNotOverride,3.162369",
          ContentFR = "Approche un peu, Emilia... que je te voie de près...",
          DialogueId = 80180106,
          FinalCamera = "-15.919922,490.611572,78.546875,0.000109,4.201092,-79.201218,30.000002,247.327988,false,DoNotOverride,3.162369",
          GUID = "C8B8F4A4",
          NextDialogue = 80180107,
          SpeakNpcId = 790059,
          Subtitle = "Come a little closer, Emilia... Let me have a good look at you...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F4A4"
        },
        [80180107] = {
          ContentFR = "Tu as grandi... et tu es si maigre... L’Académie t’épuise encore, pas vrai...?",
          DialogueId = 80180107,
          GUID = "C8B8F4CE",
          NextDialogue = 80180108,
          SpeakNpcId = 790059,
          Subtitle = "You've gotten so tall... and so thin. Life at the Academy's still wearing you out, isn't it...?",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F4CE"
        },
        [80180108] = {
          Camera = "124.885254,73.358887,114.648438,0.000111,8.801046,154.798798,30.000002,247.327988,false,DoNotOverride,3.162369",
          ContentFR = "Ne vous inquiétez pas. Je vais bien ! Les chercheurs sont très gentils avec moi. Ils prennent soin de moi, vraiment.",
          DialogueId = 80180108,
          FinalCamera = "129.206543,80.562866,114.648438,0.000111,8.801046,157.199387,30.000002,247.327988,false,DoNotOverride,3.162369",
          GUID = "C8B8F4F8",
          NextDialogue = 80180109,
          SpeakNpcId = 790045,
          Subtitle = "It's all right — I've been doing fine. Everyone at the Academy's been kind, and they've really looked after me.",
          TalkActionId = {
            [1] = "790045:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F4F8"
        },
        [80180109] = {
          Camera = "-22.415527,411.51062,217.269531,0.000075,-19.597588,-75.394966,30.000002,247.327988,false,DoNotOverride,3.162369",
          ContentFR = "... Non...",
          DialogueId = 80180109,
          FinalCamera = "-37.787109,408.08606,217.269531,0.000077,-19.597588,-72.99453,30.000002,247.327988,false,DoNotOverride,3.162369",
          GUID = "C8B8F522",
          NextDialogue = 80180110,
          SpeakNpcId = 790059,
          Subtitle = "...No...",
          TalkActionId = {
            [1] = "790045:Talk02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F522"
        },
        [80180110] = {
          ContentFR = "Chaque fois qu’Emilia parlait de l’Académie, elle pleurait. Elle disait toujours qu’elle regrettait d’y être allée.",
          DialogueId = 80180110,
          GUID = "C8B8F54C",
          NextDialogue = 80180111,
          SpeakNpcId = 790059,
          Subtitle = "Every time Emilia talked about the Academy, she'd cry. She always regretted going there.",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F54C"
        },
        [80180111] = {
          Camera = "114.473145,81.809021,158.171875,0.000098,-23.197474,-77.990166,30.000002,247.327988,false,DoNotOverride,3.162369",
          ContentFR = "Tu n’es pas Emilia... Qui es-tu ?",
          DialogueId = 80180111,
          FinalCamera = "110.792969,99.114258,165.755859,0.000092,-22.997458,-77.989754,30.000002,247.327988,false,DoNotOverride,3.162369",
          GUID = "C8B8F576",
          NextDialogue = 80180112,
          SpeakNpcId = 790059,
          Subtitle = "You're not Emilia! ...Who are you?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F576"
        },
        [80180112] = {
          Camera = "211.481445,-34.879761,148.429688,0.000081,-6.797363,148.809708,30.000002,268.824341,false,Manual,3.162369",
          ContentFR = "Pardon... Monsieur Gaston. Je suis Daphne Theodore. Une... amie d’Emilia. Je suis venue en son nom.",
          DialogueId = 80180112,
          FinalCamera = "214.442383,-29.989197,148.429688,0.000082,-6.797363,151.209473,30.000002,268.824341,false,Manual,3.162369",
          GUID = "C8B8F5A0",
          NextDialogue = 80180113,
          SpeakNpcId = 790045,
          Subtitle = "I'm sorry... Mr Gaston. My name is Daphne Theodore. I was... Emilia's friend. I came to visit on her behalf.",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F5A0"
        },
        [80180113] = {
          Camera = "389.942871,-15.916992,216.761719,0.000082,-16.596901,170.208176,30.000002,379.770111,false,Manual,3.162369",
          ContentFR = "Ah... Pardon, Mademoiselle Theodore. Excusez-moi, je ne peux même pas me lever pour vous saluer...",
          DialogueId = 80180113,
          FacialId = {
            [1] = "790059:CM_Sad01"
          },
          FinalCamera = "391.346191,-7.785767,216.761719,0.000082,-16.596901,170.208176,30.000002,379.770111,false,Manual,3.162369",
          GUID = "C8B8F5CA",
          NextDialogue = 80180114,
          SpeakNpcId = 790059,
          Subtitle = "Ah... Forgive me, Miss Theodore. I can't even stand to greet you properly.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F5CA"
        },
        [80180114] = {
          ContentFR = "Je perds la mémoire. Je ne sais plus ce qui est rêve ou réalité... Ces derniers temps... j’ai l’impression qu’Emilia est toujours vivante.",
          DialogueId = 80180114,
          GUID = "C8B8F5F4",
          NextDialogue = 80180115,
          SpeakNpcId = 790059,
          Subtitle = "I've become so forgetful lately... I can barely tell dream from waking. And recently... I keep seeing Emilia. As if she were still alive.",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F5F4"
        },
        [80180115] = {
          Camera = "-14.48877,190.756897,161.263672,0.000049,-12.396656,-61.593624,30.000008,244.623566,false,Manual,3.301471",
          ContentFR = "Je la revois si petite... comme autrefois. Elle descend les marches quatre à quatre, se jette dans mes bras en criant « Papa ! »",
          DialogueId = 80180115,
          FinalCamera = "-7.308105,195.172363,161.263672,0.000047,-12.396656,-65.793968,30.000008,244.623566,false,Manual,3.301471",
          GUID = "C8B8F61E",
          NextDialogue = 80180116,
          SpeakNpcId = 790059,
          Subtitle = "She's so small... just like when she was little... jumping down the stairs into my arms, calling out, \"Daddy!\"",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F61E"
        },
        [80180116] = {
          Camera = "116.074707,70.821228,122.748047,0.000048,6.402981,152.803696,30.000008,131.13031,false,Manual,3.301471",
          ContentFR = "Monsieur Gaston... je...",
          DialogueId = 80180116,
          FinalCamera = "120.910645,79.414978,122.748047,0.000047,6.402981,155.80397,30.000008,131.026245,false,Manual,3.301471",
          GUID = "C8B8F648",
          NextDialogue = 80180117,
          SpeakNpcId = 790045,
          Subtitle = "Mr Gaston... I'm —",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F648"
        },
        [80180117] = {
          ContentFR = "Non, mon enfant... tu n’as pas à me consoler. Je me souviens maintenant... Emilia a été enterrée il y a un mois. Une infirmière compatissante m’a conduit en fauteuil jusqu’à la cérémonie. J’ai posé sur sa tombe son vieux canard en caoutchouc... celui avec lequel elle jouait tout le temps.",
          DialogueId = 80180117,
          GUID = "C8B8F672",
          NextDialogue = 80180118,
          SpeakNpcId = 790059,
          Subtitle = "No, child. Don't be. I remember now. Emilia was buried a month ago. A kind nurse wheeled me to the service. I left her old rubber duck on the grave — the one she always played with.",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F672"
        },
        [80180118] = {
          Camera = "437.276855,-80.072693,281.332031,0.000106,-25.192556,163.998383,30.000008,507.135406,false,Manual,2.479588",
          ContentFR = "Elle parlait souvent de vous, Mademoiselle Theodore. Elle disait que vous étiez sa plus proche amie. Faites attention à vous... L’Académie n’est pas un endroit sûr...",
          DialogueId = 80180118,
          FinalCamera = "437.276855,-80.072693,281.332031,0.000103,-22.392521,159.3983,30.000008,507.135406,false,Manual,2.479588",
          GUID = "C8B8F69C",
          NextDialogue = 80180119,
          SpeakNpcId = 790059,
          Subtitle = "She often spoke of you, Miss Theodore. Said you were her closest friend. Please... be careful. The Academy is a dangerous place...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F69C"
        },
        [80180119] = {
          Camera = "437.276855,-80.072693,281.332031,0.000103,-22.392521,159.3983,30.000008,507.135406,false,Manual,2.479588",
          ContentFR = "<I>Je savais très bien ce qu’il voulait dire. Ma chère camarade, Emilia Gaston, avait trouvé la mort dans un accident aux Spathatoi.</>",
          DialogueId = 80180119,
          GUID = "C8B8F6C6",
          IsBlack = 1,
          NextDialogue = 80180120,
          SpeakNpcId = 790045,
          Subtitle = "(I knew exactly what Mr Gaston meant. Emilia Gaston — my dear friend — had died in an accident at the Spathatoi.)",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F6C6"
        },
        [80180120] = {
          Camera = "567.892578,244.198547,75.826172,0.000136,1.407784,-158.007095,35.0,646.375061,false,Manual,1.2",
          ContentFR = "... Argh !",
          DialogueId = 80180120,
          GUID = "C8B8F6F0",
          NextDialogue = 80180121,
          SpeakNpcId = 790059,
          Subtitle = "—Aargh!",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F6F0"
        },
        [80180121] = {
          Camera = "567.892578,244.198547,75.826172,0.000136,1.407784,-158.007095,35.0,646.375061,false,Manual,1.2",
          ContentFR = "Monsieur Gaston !",
          DialogueId = 80180121,
          GUID = "C8B8F71A",
          NextDialogue = 80180122,
          SpeakNpcId = 790045,
          Subtitle = "...Mr Gaston!",
          TalkActionId = {
            [1] = "790045:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F71A"
        },
        [80180122] = {
          Camera = "245.396484,-74.086365,158.837891,0.00012,-8.591114,143.39476,40.0,301.252777,false,Manual,1.955812",
          ContentFR = "Vous avez mal ? Attendez, je vais chercher un médecin !",
          DialogueId = 80180122,
          FinalCamera = "245.396484,-74.086365,158.837891,0.000121,-6.791072,142.994873,40.0,301.252777,false,Manual,1.955812",
          GUID = "C8B8F744",
          NextDialogue = 80180123,
          SpeakNpcId = 790045,
          Subtitle = "Are you in pain? I'll get the doctor!",
          TalkActionId = {
            [1] = "790045:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F744"
        },
        [80180123] = {
          Camera = "70.369141,68.184753,163.933594,0.000103,-23.59066,-52.404755,40.0,301.252777,false,DoNotOverride,1.955812",
          ContentFR = "Non... C’est inutile, mon enfant...",
          DialogueId = 80180123,
          FinalCamera = "64.535645,75.762634,168.109375,0.000104,-23.590666,-52.404778,40.0,301.252777,false,DoNotOverride,1.955812",
          GUID = "C8B8F76E",
          NextDialogue = 80180124,
          SpeakNpcId = 790059,
          Subtitle = "No... child...",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F76E"
        },
        [80180124] = {
          ContentFR = "Mes jambes sont fichues. Pourries jusqu’à l’os, après des mois dans la boue des tranchées... L’une a déjà été amputée. L’autre ne vaut guère mieux.",
          DialogueId = 80180124,
          GUID = "C8B8F798",
          NextDialogue = 80180125,
          SpeakNpcId = 790059,
          Subtitle = "My legs are done for. Too long in the trenches... One's been amputated. The other's rotted through.",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F798"
        },
        [80180125] = {
          Camera = "-42.722656,257.672241,151.652344,0.000059,-6.989933,-60.00206,40.0,311.952545,false,Manual,2.256478",
          ContentFR = "Mais bon... ce n’est que de la douleur. Au moins je suis encore là, c’est toujours mieux que ceux qui y sont restés... pas vrai ?",
          DialogueId = 80180125,
          FinalCamera = "-33.669922,263.006287,151.652344,0.000065,-6.989933,-63.602329,40.0,311.952545,false,Manual,2.256478",
          GUID = "C8B8F7C2",
          NextDialogue = 80180126,
          SpeakNpcId = 790059,
          Subtitle = "Hurts like hell — but what of it? I'm still breathing. That's more than I can say for the others... right?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F7C2"
        },
        [80180126] = {
          ContentFR = "Gnnn... Aahh...",
          DialogueId = 80180126,
          GUID = "C8B8F7EC",
          NextDialogue = 80180127,
          SpeakNpcId = 790059,
          Subtitle = "Ugh... aahhh...",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F7EC"
        },
        [80180127] = {
          ContentFR = "<I>La douleur l’a de nouveau saisi. Ses mains s’agrippent aux draps, les veines saillantes. Ce n’est pas à la vie qu’il s’accroche, c’est sa dignité. Le dernier éclat d’un soldat.</>",
          DialogueId = 80180127,
          GUID = "C8B8F816",
          IsBlack = 1,
          NextDialogue = 80180128,
          Subtitle = "(Mr Gaston's pain flared up again. His fists clenched the sheets, veins bulging. He wasn't clinging to life — he was clinging to dignity. The last thing a soldier has left.)",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F816"
        },
        [80180128] = {
          Camera = "-196.821289,36.408081,111.78125,0.000072,-0.789276,-6.604747,40.000011,311.952545,false,Manual,2.256478",
          ContentFR = "Aaahhh... !",
          DialogueId = 80180128,
          FinalCamera = "-228.835938,40.114746,112.220703,0.000072,-0.789276,-6.604747,40.000011,311.952545,false,Manual,2.256478",
          GUID = "C8B8F840",
          NextDialogue = 80180129,
          SpeakNpcId = 790059,
          Subtitle = "Aaaghhh—!",
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F840"
        },
        [80180129] = {
          Camera = "146.449707,-106.377991,109.685547,0.000106,5.210492,114.589401,40.000011,311.952545,false,Manual,2.256478",
          ContentFR = "Mademoiselle Theodore, je vous en supplie... achevez-moi. Je ne suis plus qu’un fardeau. Cloué à ce lit, bon à rien. Et maintenant, même ma fille...",
          DialogueId = 80180129,
          FinalCamera = "141.276367,-109.157471,109.685547,0.000106,5.210492,112.589111,40.000011,311.952545,false,Manual,2.256478",
          GUID = "C8B8F86A",
          NextDialogue = 80180130,
          SpeakNpcId = 790059,
          Subtitle = "Miss Theodore — please. Just shoot me. I'm worthless now... I can't even get out of this bed. And now even my only daughter's...",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F86A"
        },
        [80180130] = {
          ContentFR = "Je rédigerai un testament. Je jurerai que c’était ma volonté. Et mes biens... Je n’ai plus de famille. Je peux même vous léguer la maison de famille.",
          DialogueId = 80180130,
          GUID = "C8B8F894",
          NextDialogue = 80180131,
          SpeakNpcId = 790059,
          Subtitle = "I'll put it in my will — swear it was my choice. I've got no family left anyway. You can even take my old house!",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F894"
        },
        [80180131] = {
          Camera = "9.807129,54.86792,159.228516,-28.800745,-17.989195,-27.007662,40.000011,311.952545,false,DoNotOverride,2.256478",
          ContentFR = "Tuez-moi, je vous en supplie ! Ou au moins... tranchez-moi l’autre jambe !",
          DialogueId = 80180131,
          FinalCamera = "-10.913086,65.429382,166.779297,-18.000868,-17.989195,-27.007536,40.000011,311.952545,false,DoNotOverride,2.256478",
          GUID = "C8B8F8BE",
          NextDialogue = 80180132,
          SpeakNpcId = 790059,
          Subtitle = "Please, I'm begging you — put me out of my misery! Or at least... cut off the other leg!",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F8BE"
        },
        [80180132] = {
          Camera = "92.85498,2.856323,117.208984,-0.001006,7.810587,122.38958,40.000011,311.952545,false,DoNotOverride,2.256478",
          ContentFR = "Non... Monsieur Gaston, je ne peux pas faire ça !",
          DialogueId = 80180132,
          FinalCamera = "102.462891,-12.291992,114.761719,-0.001006,7.810587,122.38958,40.000011,311.952545,false,DoNotOverride,2.256478",
          GUID = "C8B8F8E8",
          NextDialogue = 80180133,
          SpeakNpcId = 790045,
          Subtitle = "No... Mr Gaston, I can't do that!",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F8E8"
        },
        [80180133] = {
          Camera = "-328.205566,88.299622,110.056641,-0.001007,2.210365,-3.410769,40.000011,466.053558,false,Manual,1.2",
          ContentFR = "Tenez bon, je vous en supplie ! Donnez-moi un an... non, six mois ! Je le jure sur l’Ordre d’Émeraude : je vous guérirai !",
          DialogueId = 80180133,
          FinalCamera = "-329.355469,68.979004,110.056641,-0.001007,2.210365,-0.410614,40.000011,466.053558,false,Manual,1.2",
          GUID = "C8B8F912",
          NextDialogue = 80180134,
          SpeakNpcId = 790045,
          Subtitle = "Please hang in there! Just a little longer! One year... no — six months! I swear, by the Emerald Order, I'll find a cure!",
          TalkActionId = {
            [1] = "790045:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F912"
        },
        [80180134] = {
          ContentFR = "Vivez... C’est ce qu’Emilia aurait voulu, j’en suis certaine !",
          DialogueId = 80180134,
          GUID = "C8B8F93C",
          NextDialogue = 80180135,
          SpeakNpcId = 790045,
          Subtitle = "Please — don't give up. Emilia would never have wanted that.",
          TalkActionId = {
            [1] = "790045:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F93C"
        },
        [80180135] = {
          Camera = "-195.09668,210.955811,166.289062,-0.001007,-8.589727,-28.414295,45.0,388.30954,false,Manual,1.750545",
          ContentFR = "Gnn... <I>pleurs étouffés</>",
          DialogueId = 80180135,
          FinalCamera = "-214.103516,221.238892,169.546875,-0.001007,-8.589727,-28.414295,45.0,411.829193,false,Manual,1.750545",
          GUID = "C8B8F966",
          NextDialogue = 80180136,
          SpeakNpcId = 790059,
          Subtitle = "Hngh...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F966"
        },
        [80180136] = {
          ContentFR = "<I>Après s’être violemment agité, il s’est enfin calmé. Monsieur Gaston s’est endormi, en larmes. Je ne sais pas si c’est la douleur ou le nom d’Emilia qui l’a apaisé...</>",
          DialogueId = 80180136,
          GUID = "C8B8F990",
          IsBlack = 1,
          NextDialogue = 80180137,
          SpeakNpcId = 790045,
          Subtitle = "(After the episode passed, the bed finally stilled. Mr Gaston drifted off, sobbing quietly. Whether it was the pain or Emilia's name, I couldn't tell — but something had soothed him.)",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F990"
        },
        [80180137] = {
          ContentFR = "<I>Pour certains, la souffrance est plus cruelle encore que la mort. Elle use les êtres comme un torrent polit la pierre... jusqu’à ce qu’il ne reste plus ni fierté, ni éclat.</>",
          DialogueId = 80180137,
          GUID = "C8B8F9BA",
          IsBlack = 1,
          NextDialogue = 80180138,
          SpeakNpcId = 790045,
          Subtitle = "(For some, pain is a fate much crueller — and more humiliating — than death. Like a river stone worn smooth over time, it grinds down even the toughest — stripping away their pride and fire.)",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F9BA"
        },
        [80180138] = {
          ContentFR = "<I>Ses frères d’armes et sa fille reposent au cimetière. Lui... n’a pour tombe que ce lit d’hôpital, étroit et blanchi.</>",
          DialogueId = 80180138,
          GUID = "C8B8F9E4",
          IsBlack = 1,
          NextDialogue = 80180139,
          SpeakNpcId = 790045,
          Subtitle = "(His comrades and daughter rest in the public cemetery. And this small white bed... is his grave.)",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F9E4"
        },
        [80180139] = {
          ContentFR = "<I>Et ce jour-là, au chevet de Monsieur Gaston... j’ai pris ma décision.</>",
          DialogueId = 80180139,
          GUID = "C8B8FA0E",
          IsBlack = 1,
          SpeakNpcId = 790045,
          Subtitle = "(That day, by his bedside, I finally made that decision.)",
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8FA0E"
        },
        [80180201] = {
          Camera = "-21.269043,-387.99707,181.142334,0.000059,-9.599646,87.198402,30.000008,489.123169,false,Manual,1.2",
          ContentFR = "Regarde, Daphne ! On a réussi à synthétiser l’AG-1899, un puissant analgésique !",
          DialogueId = 80180201,
          FinalCamera = "-21.269043,-387.99707,181.142334,0.000052,-11.999659,87.198425,30.000008,489.123169,false,Manual,1.2",
          GUID = "C8B9043A",
          NextDialogue = 80180202,
          SpeakNpcId = 790056,
          Subtitle = "We did it, Daphne! We finally synthesized the AG-1899 high-potency painkiller!",
          TalkActionId = {
            [1] = "790056:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B9043A"
        },
        [80180202] = {
          Camera = "40.555176,-36.499023,178.654053,0.000067,-22.199459,72.391502,30.000008,489.123169,false,DoNotOverride,1.2",
          ContentFR = "Enfin... c’est surtout toi. C’est toi qui as tout pensé, tout testé... Moi, j’ai juste été ton assistante.",
          DialogueId = 80180202,
          FinalCamera = "45.767578,-38.120117,178.654053,0.000066,-22.199451,74.391289,30.000008,489.123169,false,DoNotOverride,1.2",
          GUID = "C8B90464",
          NextDialogue = 80180203,
          SpeakNpcId = 790056,
          Subtitle = "Well... I mean, you did it. You did most of the design and experiments, after all. I just helped out...",
          TalkActionId = {
            [1] = "790056:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90464"
        },
        [80180203] = {
          Camera = "141.903809,100.63916,144.927734,0.000075,-3.59927,-147.809128,35.0,267.386597,false,Manual,2.319523",
          ContentFR = "Ne dis pas ça ! Si tu ne m’avais pas poussée, je n’aurais jamais rejoint ce projet...",
          DialogueId = 80180203,
          FinalCamera = "144.20166,96.986328,144.927734,0.000075,-3.59927,-149.008759,35.0,267.386597,false,Manual,2.319523",
          GUID = "C8B9048E",
          NextDialogue = 80180204,
          SpeakNpcId = 790045,
          Subtitle = "Don't say that! I never would've joined the project if you hadn't been so insistent.",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B9048E"
        },
        [80180204] = {
          Camera = "134.325195,-279.771973,156.985107,0.00007,-7.199005,97.99205,35.0,361.466309,false,Manual,2.319523",
          ContentFR = "Tu te rappelles ? Tu disais que si notre formule passait les tests de toxicité... si l’Académie l’acceptait pour une production à grande échelle...",
          DialogueId = 80180204,
          FinalCamera = "123.702637,-281.262207,156.985107,0.00007,-7.199005,97.99205,35.0,361.466309,false,Manual,2.319523",
          GUID = "C8B904B8",
          NextDialogue = 80180205,
          SpeakNpcId = 790056,
          Subtitle = "Daphne... if our drug passes toxicity trials — if the Academy approves mass production...",
          TalkActionId = {
            [1] = "790056:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B904B8"
        },
        [80180205] = {
          Camera = "-93.812012,-132.799805,142.472168,0.000076,-3.198878,58.991425,35.0,264.274048,false,Manual,3.676726",
          ContentFR = "Si elle arrivait jusqu’aux hôpitaux... jusqu’aux champs de bataille...",
          DialogueId = 80180205,
          FinalCamera = "-89.988281,-135.097168,142.472168,0.000077,-3.198878,60.79129,35.0,264.274048,false,Manual,3.676726",
          GUID = "C8B904E2",
          NextDialogue = 80180206,
          SpeakNpcId = 790056,
          Subtitle = "If it makes it to every hospital — every battlefield—",
          TalkActionId = {
            [1] = "790056:Think_End",
            [2] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B904E2"
        },
        [80180206] = {
          ContentFR = "Alors peut-être... que ceux qui souffrent auront un peu moins mal...",
          DialogueId = 80180206,
          GUID = "C8B9050C",
          SpeakNpcId = 790056,
          Subtitle = "Then maybe... those tormented by pain might suffer just a little less.",
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B9050C"
        },
        [80180207] = {
          Camera = "154.316406,-437.40625,81.189453,0.000059,11.198689,114.994148,30.000002,125.0,false,DoNotOverride,2.8",
          ContentFR = "...",
          DialogueId = 80180207,
          FinalCamera = "154.316406,-437.40625,81.189453,0.000059,11.198689,114.994148,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B90536",
          NextDialogue = 80180208,
          SpeakNpcId = 790045,
          Subtitle = "...",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90536"
        },
        [80180208] = {
          Camera = "59.469727,2.3125,118.984375,0.000144,2.398797,-108.205406,30.000002,125.0,false,DoNotOverride,2.8",
          ContentFR = "Daphne Theodore.",
          DialogueId = 80180208,
          FinalCamera = "78.555176,-4.228027,118.984375,0.000145,2.398797,-112.405106,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B90560",
          NextDialogue = 80180209,
          SpeakNpcId = 790013,
          Subtitle = "Daphne Theodore.",
          TalkActionId = {
            [1] = "790013:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90560"
        },
        [80180209] = {
          Camera = "30.060059,-266.956055,146.386719,0.000153,-4.000885,105.797691,30.000002,284.222046,false,Manual,2.8",
          ContentFR = "... Oui, Madame Mason. Non... je devrais dire : \"Commandante\".",
          DialogueId = 80180209,
          FinalCamera = "34.405273,-265.727051,146.386719,0.000154,-4.000885,106.997757,30.000002,284.222046,false,Manual,2.8",
          GUID = "C8B9058A",
          NextDialogue = 80180210,
          SpeakNpcId = 790045,
          Subtitle = "...Yes, Miss Mason. No... I suppose I should call you Chief now.",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B9058A"
        },
        [80180210] = {
          Camera = "27.647949,-145.186035,176.830078,0.000124,-27.800474,-122.401695,30.000002,284.222046,false,DoNotOverride,2.8",
          ContentFR = "Tu m’appelais \"Sibylle\" avant... Mais peu importe.",
          DialogueId = 80180210,
          FinalCamera = "30.851074,-147.144043,176.830078,0.000117,-27.800474,-125.801666,30.000002,284.222046,false,DoNotOverride,2.8",
          GUID = "C8B905B4",
          NextDialogue = 80180211,
          SpeakNpcId = 790013,
          Subtitle = "That's not what you used to call me at the Academy... Not that it matters anymore.",
          TalkActionId = {
            [1] = "790013:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B905B4"
        },
        [80180211] = {
          Camera = "1375.89209,139.100586,164.9375,0.000093,-2.600458,-169.596542,30.000002,1368.736572,false,Manual,2.8",
          ContentFR = "Explique-toi, Daphne. Qu’est-ce que tu as fait pour mettre le doyen Silas en rogne ?",
          DialogueId = 80180211,
          FinalCamera = "1377.645996,129.715332,164.9375,0.000093,-2.600458,-170.996094,30.000002,1368.736572,false,Manual,2.8",
          GUID = "C8B905DE",
          NextDialogue = 80180212,
          SpeakNpcId = 790013,
          Subtitle = "Now, explain what you have done, Daphne. How did you tick off Dean Silas?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B905DE"
        },
        [80180212] = {
          Camera = "42.463379,-180.554199,119.259766,0.000107,2.599891,102.002693,30.000002,284.222046,false,DoNotOverride,2.8",
          ContentFR = "Je n’ai rien à ajouter. J’ai menti au doyen. À tous les Spathatoi.",
          DialogueId = 80180212,
          FinalCamera = "51.740234,-178.580566,119.259766,0.000108,2.599891,105.003036,30.000002,284.222046,false,DoNotOverride,2.8",
          GUID = "C8B90608",
          NextDialogue = 80180213,
          SpeakNpcId = 790045,
          Subtitle = "There's nothing to explain. I lied — to Dean Silas, and to the Spathatoi.",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90608"
        },
        [80180213] = {
          Camera = "51.740234,-178.580566,119.259766,0.000108,2.599891,105.003036,30.000002,284.222046,false,DoNotOverride,2.8",
          ContentFR = "J’ai remis un faux dossier et obtenu un financement pour une recherche fictive. En réalité, je n’ai jamais travaillé sur le sérum d’intensification que Silas voulait... J’ai poursuivi nos travaux inachevés sur l’analgésique.",
          DialogueId = 80180213,
          GUID = "C8B90632",
          NextDialogue = 80180214,
          SpeakNpcId = 790045,
          Subtitle = "I submitted a fake proposal and requested research funding. But I never worked on the intensification serum as Mr Silas required. Instead... I resumed our unfinished painkiller project.",
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90632"
        },
        [80180214] = {
          Camera = "229.41748,-451.871582,304.970703,0.000153,-26.199333,122.002304,30.000002,1368.736572,false,DoNotOverride,2.8",
          ContentFR = "... Parce que je crois qu’il a bien plus de valeur.",
          DialogueId = 80180214,
          FinalCamera = "248.888184,-441.256836,304.970703,0.000167,-26.19932,127.202431,30.000002,1368.736572,false,DoNotOverride,2.8",
          GUID = "C8B9065C",
          NextDialogue = 80180215,
          SpeakNpcId = 790045,
          Subtitle = "Because I believe it holds far greater value.",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B9065C"
        },
        [80180215] = {
          Camera = "33.566895,-94.611328,178.189453,0.000141,-24.198963,109.400581,30.000002,1368.736572,false,DoNotOverride,2.8",
          ContentFR = "J’accepterai n’importe quelle sanction. Mais si je suis ici, c’est pour vous demander d’user de votre autorité de commandante... et d’approuver exceptionnellement la mise en production de l’AG-1899.",
          DialogueId = 80180215,
          FinalCamera = "33.566895,-94.611328,178.189453,0.000154,-21.798882,108.600464,30.000002,1368.736572,false,DoNotOverride,2.8",
          GUID = "C8B90686",
          NextDialogue = 80180216,
          SpeakNpcId = 790045,
          Subtitle = "I'll accept whatever punishment you see fit, but please — exercise your power as a chief to specially approve AG-1899 for mass production.",
          TalkActionId = {
            [1] = "790045:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90686"
        },
        [80180216] = {
          Camera = "34.025391,-264.680176,161.505859,0.000184,-10.198838,108.00029,30.000002,293.752045,false,Manual,2.8",
          ContentFR = "Ce n’est qu’un médicament. Il n’a rien fait de mal. Et il peut soulager des milliers de vies.",
          DialogueId = 80180216,
          FinalCamera = "42.447266,-262.075195,161.505859,0.000186,-10.198838,110.800125,30.000002,293.752045,false,Manual,2.8",
          GUID = "C8B906B0",
          NextDialogue = 80180217,
          SpeakNpcId = 790045,
          Subtitle = "It's just a drug. It's done no wrong. And it could spare countless lives from agony.",
          TalkActionId = {
            [1] = "790045:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B906B0"
        }
      }
    end
  },
  {
    MinKey = 80180217,
    MaxKey = 80200001,
    Loader = function()
      return {
        [80180217] = {
          Camera = "69.490723,-197.728516,145.714844,0.000191,0.801079,171.39772,30.000002,293.752045,false,DoNotOverride,2.8",
          ContentFR = "Je ne nie pas l’intérêt de l’AG-1899. Mais un tel médicament... d’autres alchimistes finiront par y parvenir. Il leur faudra simplement plus de temps.",
          DialogueId = 80180217,
          FinalCamera = "68.950684,-201.303711,145.714844,0.000191,0.801079,171.39772,30.000002,293.752045,false,DoNotOverride,2.8",
          GUID = "C8B906DA",
          NextDialogue = 80180218,
          SpeakNpcId = 790013,
          Subtitle = "I don't deny its value. But a drug like this — it could be developed by other alchemists. It would simply take more time.",
          TalkActionId = {
            [1] = "790013:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B906DA"
        },
        [80180218] = {
          Camera = "32.769043,41.966309,152.269531,0.000203,-6.59857,-107.203644,30.000002,249.2892,false,Manual,2.8",
          ContentFR = "En tant que chercheuse d’exception, tu aurais dû travailler là où l’Empire a le plus besoin de toi. C’est ce que l’Académie attendait de toi.",
          DialogueId = 80180218,
          FinalCamera = "40.151367,39.748047,152.269531,0.000204,-6.59857,-109.603592,30.000002,249.2892,false,Manual,2.8",
          GUID = "C8B90704",
          NextDialogue = 80180219,
          SpeakNpcId = 790013,
          Subtitle = "As a researcher superior to others, you should have served where the Empire needs you most, to meet what the Academy expects.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90704"
        },
        [80180219] = {
          Camera = "971.158691,717.543945,7.337891,0.000212,3.801465,-145.200256,30.000002,1297.015747,false,Manual,2.8",
          ContentFR = "Et maintenant que tu as fait ça, avec le caractère de Silas... Même s’il te laisse tranquille, toutes tes recherches seront placées sous surveillance à l’avenir.",
          DialogueId = 80180219,
          FinalCamera = "971.158691,717.543945,7.337891,0.000213,4.001452,-142.200302,30.000002,1297.015747,false,Manual,2.8",
          GUID = "C8B9072E",
          NextDialogue = 80180220,
          SpeakNpcId = 790013,
          Subtitle = "Now that you've pulled this stunt, even if Silas doesn't punish you, all your research will now be conducted under direct oversight, given his temper.",
          TalkActionId = {
            [1] = "790013:Talk03_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B9072E"
        },
        [80180220] = {
          Camera = "971.158691,717.543945,7.337891,0.000213,4.001452,-142.200302,30.000002,1297.015747,false,Manual,2.8",
          ContentFR = "...",
          DialogueId = 80180220,
          GUID = "C8B90758",
          NextDialogue = 80180221,
          SpeakNpcId = 790045,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90758"
        },
        [80180221] = {
          Camera = "44.922852,-289.09082,141.619141,0.000184,-3.598758,107.796936,30.000002,298.325684,false,Manual,2.8",
          ContentFR = "Je refuse, Commandante. Je refuse de participer à ce projet d’intensification... Parce que je ne veux pas devenir la prochaine Emilia Gaston.",
          DialogueId = 80180221,
          FinalCamera = "52.822266,-286.523438,141.619141,0.000183,-3.398798,109.996681,30.000002,298.325684,false,Manual,2.8",
          GUID = "C8B90782",
          NextDialogue = 80180222,
          SpeakNpcId = 790045,
          Subtitle = "No, Chief. I won't join the Intensification Project as the dean required. Because I refuse to become the next Emilia Gaston.",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90782"
        },
        [80180222] = {
          Camera = "66.137207,-83.689941,127.6875,0.000023,5.200861,-122.401611,30.000002,298.325684,false,DoNotOverride,2.8",
          ContentFR = "Emilia Gaston ?",
          DialogueId = 80180222,
          FinalCamera = "63.108887,-81.731445,127.6875,0.000025,5.200861,-120.00177,30.000002,298.325684,false,DoNotOverride,2.8",
          GUID = "C8B907AC",
          NextDialogue = 80180223,
          SpeakNpcId = 790013,
          Subtitle = "Emilia Gaston?",
          TalkActionId = {
            [1] = "790013:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B907AC"
        },
        [80180223] = {
          Camera = "479.37207,-381.822266,18.287109,0.000066,7.800827,150.999481,30.000002,298.325684,false,DoNotOverride,2.8",
          ContentFR = "Elle a été transférée au projet d’intensification avant qu’on ait fini notre travail. Elle ne voulait pas y aller. Pas le moins du monde. Mais elle n’a pas eu le choix : c’était l’ordre des Spathatoi.",
          DialogueId = 80180223,
          FinalCamera = "479.37207,-381.822266,18.287109,0.000066,9.800829,150.799469,30.000002,298.325684,false,DoNotOverride,2.8",
          GUID = "C8B907D6",
          NextDialogue = 80180224,
          SpeakNpcId = 790045,
          Subtitle = "She was reassigned to the Intensification Project before we could finish our work. She didn't want it — not for anything — but she had no say. Because that was the Spathatoi's order.",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B907D6"
        },
        [80180224] = {
          Camera = "40.990723,54.654297,136.542969,0.000085,-1.399444,-109.997879,30.000002,249.443985,false,Manual,2.8",
          ContentFR = "Ah... Tu parles de l’alchimiste morte dans l’accident il y a six mois.",
          DialogueId = 80180224,
          FinalCamera = "47.699219,52.181641,136.542969,0.000085,-1.399444,-113.197594,30.000002,249.443985,false,Manual,2.8",
          GUID = "C8B90800",
          NextDialogue = 80180225,
          SpeakNpcId = 790013,
          Subtitle = "Ah... the alchemist who died in that accident six months ago.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90800"
        },
        [80180225] = {
          Camera = "47.699219,52.181641,136.542969,0.000085,-1.399444,-113.197594,30.000002,249.443985,false,Manual,2.8",
          ContentFR = "Tu t’inquiètes trop. Tu as toujours été prudente. Pas comme elle. Elle a oublié d’attacher les sangles de sécurité... et s’est fait transpercer la poitrine par un cobaye devenu fou.",
          DialogueId = 80180225,
          GUID = "C8B9082A",
          NextDialogue = 80180226,
          SpeakNpcId = 790013,
          Subtitle = "You're being paranoid. You've always been careful — not like her. She was reckless. Forgot to fasten the restraints... and ended up impaled by a berserk test subject.",
          TalkActionId = {
            [1] = "790013:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B9082A"
        },
        [80180226] = {
          Camera = "40.967773,-116.154785,129.154297,0.000088,3.600206,109.805168,30.000002,249.443985,false,DoNotOverride,2.8",
          ContentFR = "Non, Commandante. Vous ne la connaissiez pas.",
          DialogueId = 80180226,
          FinalCamera = "40.967773,-116.154785,129.154297,0.00009,5.800196,110.005104,30.000002,249.443985,false,DoNotOverride,2.8",
          GUID = "C8B90854",
          NextDialogue = 80180227,
          SpeakNpcId = 790045,
          Subtitle = "...No, Chief. You never really knew Emilia Gaston.",
          TalkActionId = {
            [1] = "790045:DisagreeHead"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90854"
        },
        [80180227] = {
          Camera = "40.967773,-116.154785,129.154297,0.00009,5.800196,110.005104,30.000002,249.443985,false,DoNotOverride,2.8",
          ContentFR = "J’ai travaillé longtemps avec elle. Emilia était bien plus rigoureuse que moi.",
          DialogueId = 80180227,
          GUID = "C8B9087E",
          NextDialogue = 80180228,
          SpeakNpcId = 790045,
          Subtitle = "I worked with her for a long time. She was far more meticulous than I ever was.",
          TalkActionId = {
            [1] = "790045:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B9087E"
        },
        [80180228] = {
          Camera = "543.975098,-643.192871,207.191406,0.000092,-8.199464,137.000534,30.000002,861.833862,false,Manual,1.2",
          ContentFR = "Vous avez lu un rapport. Mais vous ne savez pas ce que j’ai vu... Le sang qui coulait encore de son corps... Elle baignait dedans. Et pourtant, elle n’a jamais dit « aidez-moi ».",
          DialogueId = 80180228,
          FinalCamera = "563.548828,-622.201172,207.191406,0.000092,-8.199464,138.8004,30.000002,861.833862,false,Manual,1.2",
          GUID = "C8B908A8",
          NextDialogue = 80180229,
          SpeakNpcId = 790045,
          Subtitle = "The report just said she died. What it didn't say was... there was blood everywhere. Still pouring from her chest... And... and even then... not once did she ask for help...",
          TalkActionId = {
            [1] = "790045:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B908A8"
        },
        [80180229] = {
          Camera = "54.456055,-318.109375,151.507812,0.000091,-5.799561,105.601219,30.000002,319.662201,false,Manual,1.2",
          ContentFR = "Elle disait juste... encore et encore... « Pardon » à ce cobaye qui la maudissait encore en la regardant mourir.",
          DialogueId = 80180229,
          FinalCamera = "49.29834,-299.633301,149.564453,0.000087,-6.199557,105.001999,30.000002,319.662201,false,Manual,1.2",
          GUID = "C8B908D2",
          NextDialogue = 80180230,
          SpeakNpcId = 790045,
          Subtitle = "She just kept saying... \"I'm sorry\" over and over... to the test subject who was still cursing her.",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B908D2"
        },
        [80180230] = {
          Camera = "49.29834,-299.633301,149.564453,0.000087,-6.199557,105.001999,30.000002,319.662201,false,Manual,1.2",
          ContentFR = "Ce n’était pas un oubli. Elle a enlevé les sangles. Parce qu’elle ne supportait pas de voir souffrir un autre être humain.",
          DialogueId = 80180230,
          GUID = "C8B908FC",
          NextDialogue = 80180231,
          SpeakNpcId = 790045,
          Subtitle = "She didn't forget the restraints. She released them... because she couldn't bear to see another human being suffer.",
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B908FC"
        },
        [80180231] = {
          Camera = "962.483398,712.037109,2.564453,0.00009,7.400503,-144.79744,30.000002,1383.023071,false,Manual,1.2",
          ContentFR = "Si ça avait été moi à sa place... J’aurais peut-être fait la même chose. La seule chose qui m’a séparée de son sort, c’était une lettre de mutation.",
          DialogueId = 80180231,
          FinalCamera = "964.055176,709.811035,2.564453,0.000089,7.400503,-143.597458,30.000002,1383.023071,false,Manual,1.2",
          GUID = "C8B90926",
          NextDialogue = 80180232,
          SpeakNpcId = 790045,
          Subtitle = "Had it been me... I might've done the same. The only thing that spared me from her fate — was a reassignment letter.",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90926"
        },
        [80180232] = {
          Camera = "98.930664,135.452148,204.640625,-10.808317,-18.599213,-115.984474,30.000002,368.927856,false,Manual,1.2",
          ContentFR = "Ces cobayes ne sont que des déchets de la société. Je croyais que la mort d’Emilia t’aurait appris quelque chose.",
          DialogueId = 80180232,
          FinalCamera = "89.845215,140.586426,202.753906,-10.808901,-18.599213,-114.383667,30.000002,368.927856,false,Manual,1.2",
          GUID = "C8B90950",
          NextDialogue = 80180233,
          SpeakNpcId = 790013,
          Subtitle = "Those test subjects were just dregs of society. I thought Emilia's death might've at least taught you something.",
          TalkActionId = {
            [1] = "790013:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90950"
        },
        [80180233] = {
          Camera = "24.695312,-121.806152,171.394531,-10.819184,-18.998465,-112.377495,30.000002,368.927856,false,DoNotOverride,1.2",
          ContentFR = "Les Charons sont des serpents. Froids. Égoïstes. Rusés. Tu leur tournes le dos, ils te mordent sans hésiter.",
          DialogueId = 80180233,
          FinalCamera = "18.752441,-119.948242,170.269531,-10.820675,-18.398371,-107.777733,30.000002,368.927856,false,DoNotOverride,1.2",
          GUID = "C8B9097A",
          NextDialogue = 80180234,
          SpeakNpcId = 790013,
          Subtitle = "Most Charons are cold, selfish, and cunning. Turn your back, and they'll sink their fangs into your heel without a second thought.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B9097A"
        },
        [80180234] = {
          Camera = "18.752441,-119.948242,170.269531,-10.820675,-18.398371,-107.777733,30.000002,368.927856,false,DoNotOverride,1.2",
          ContentFR = "Et moi aussi. Je suis froide. Égoïste. Rusée. Si tu m’étais supérieure, tu pourrais m’écraser. Mais là, c’est moi qui peux t’écraser.",
          DialogueId = 80180234,
          GUID = "C8B909A4",
          NextDialogue = 80180235,
          SpeakNpcId = 790013,
          Subtitle = "And I'm no different. Cold, selfish, cunning. If you stood above me, you'd crush me — just as easily as I could crush you now.",
          TalkActionId = {
            [1] = "790013:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B909A4"
        },
        [80180235] = {
          Camera = "274.801758,201.754395,22.921875,-0.001008,14.001088,-135.975983,30.000002,368.927856,false,DoNotOverride,1.2",
          ContentFR = "Et pour l’instant, tu n’en as pas le droit. La compassion est un luxe réservé aux forts, Daphne.",
          DialogueId = 80180235,
          FinalCamera = "274.801758,201.754395,22.921875,-0.001008,11.201038,-136.775848,30.000002,368.927856,false,DoNotOverride,1.2",
          GUID = "C8B909CE",
          NextDialogue = 80180236,
          SpeakNpcId = 790013,
          Subtitle = "But you don't. Mercy is a privilege of the strong, Daphne.",
          TalkActionId = {
            [1] = "790013:Talk01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B909CE"
        },
        [80180236] = {
          Camera = "38.126953,-294.654297,141.544922,-0.001007,-3.199267,106.030937,35.0,300.532867,false,Manual,3.442178",
          ContentFR = "... C’est vrai. Emilia a eu pitié, elle a desserré les liens... et il l’a tuée d’un coup au cœur. Ils sont vraiment froids... et cruels...",
          DialogueId = 80180236,
          FinalCamera = "44.895996,-292.64502,141.544922,-0.001008,-3.199267,107.03141,35.0,300.532867,false,Manual,3.442178",
          GUID = "C8B909F8",
          NextDialogue = 80180237,
          SpeakNpcId = 790045,
          Subtitle = "...You're right. Emilia unshackled that test subject out of kindness — and he repaid her with a blade to the heart. Yes, they're cold and cunning.",
          TalkActionId = {
            [1] = "790013:Talk01_End",
            [2] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B909F8"
        },
        [80180237] = {
          Camera = "44.895996,-292.64502,141.544922,-0.001008,-3.199267,107.03141,35.0,300.532867,false,Manual,3.442178",
          ContentFR = "Mais... qui les a rendus comme ça ?",
          DialogueId = 80180237,
          GUID = "C8B90A22",
          NextDialogue = 80180238,
          SpeakNpcId = 790045,
          Subtitle = "But who made them that way?",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90A22"
        },
        [80180238] = {
          Camera = "38.929199,-70.45166,156.289062,-0.001007,-6.799528,-109.573471,30.000002,368.927856,false,DoNotOverride,1.2",
          ContentFR = "...",
          DialogueId = 80180238,
          FinalCamera = "45.669922,-72.849121,156.289062,-0.001008,-6.799528,-112.173264,30.000002,368.927856,false,DoNotOverride,1.2",
          GUID = "C8B90A4C",
          NextDialogue = 80180239,
          SpeakNpcId = 790013,
          Subtitle = "......",
          TalkActionId = {
            [1] = "790013:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90A4C"
        },
        [80180239] = {
          Camera = "384.644531,-492.653809,29.773438,-0.001008,8.000091,136.426346,35.0,300.532867,false,DoNotOverride,3.442178",
          ContentFR = "Commandante... non. Sibylle... J’ai fait mon choix. Je ne reviendrai pas en arrière.",
          DialogueId = 80180239,
          FinalCamera = "396.825684,-480.255859,29.773438,-0.001007,8.000091,138.426254,35.0,300.532867,false,DoNotOverride,3.442178",
          GUID = "C8B90A76",
          NextDialogue = 80180240,
          SpeakNpcId = 790045,
          Subtitle = "Chief — no, Sibylle... I've made my choice. And I won't turn back.",
          TalkActionId = {
            [1] = "790045:DisagreeHead"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90A76"
        },
        [80180240] = {
          Camera = "396.825684,-480.255859,29.773438,-0.001007,8.000091,138.426254,35.0,300.532867,false,DoNotOverride,3.442178",
          ContentFR = "« L’alchimie existe pour rendre la vie meilleure. » C’est avec cet <H>idéal</> que je suis entrée à l’Académie.",
          DialogueId = 80180240,
          GUID = "C8B90AA0",
          NextDialogue = 80180241,
          SpeakNpcId = 790045,
          Subtitle = "\"Alchemy exists to make life better.\" That's the ideal I believed in when I entered the Academy.",
          TalkActionId = {
            [1] = "790013:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90AA0"
        },
        [80180241] = {
          Camera = "51.583496,-229.13623,99.591797,-0.001008,6.199721,102.229668,35.0,300.532867,false,DoNotOverride,3.442178",
          ContentFR = "Je retourne là-bas. Pour recevoir ma punition... Mais je vous en supplie une dernière fois, si vous ordonnez la mise en production de l’AG-1899, ceux qui souffrent de la douleur vous en seront éternellement reconnaissants.",
          DialogueId = 80180241,
          FinalCamera = "62.180664,-226.969727,99.591797,-0.001007,6.199721,105.430244,35.0,300.532867,false,DoNotOverride,3.442178",
          GUID = "C8B90ACA",
          NextDialogue = 80180242,
          SpeakNpcId = 790045,
          Subtitle = "I'm going back, Sibylle, to accept the punishment at the Academy... But I still want to beg you for one last time — if you would order the Alchemy to produce AG-1899, all those who are tortured by pain will be extremely grateful to you.",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90ACA"
        },
        [80180242] = {
          Camera = "38.126953,-294.654297,141.544922,-0.001007,-3.199267,106.030937,35.0,300.532867,false,Manual,3.442178",
          ContentFR = "Puisque tu es aussi déterminée... Je vais te donner quelques conseils.",
          DialogueId = 80180242,
          FinalCamera = "44.895996,-292.64502,141.544922,-0.001008,-3.199267,107.03141,35.0,300.532867,false,Manual,3.442178",
          GUID = "C8B90AF4",
          NextDialogue = 80180243,
          SpeakNpcId = 790013,
          Subtitle = "Since you're so set on it, I'll give you a few pieces of advice.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90AF4"
        },
        [80180243] = {
          Camera = "47.391602,-123.157227,200.138672,-0.001004,-26.399937,111.230003,35.0,300.532867,false,DoNotOverride,3.442178",
          ContentFR = "Après tout ce temps à l’Académie, tu en sais trop. Silas ne te laissera jamais partir librement. Tu n’as plus que trois options.",
          DialogueId = 80180243,
          FinalCamera = "55.6875,-120.101562,200.138672,-0.001007,-26.399929,114.229691,35.0,300.532867,false,DoNotOverride,3.442178",
          GUID = "C8B90B1E",
          NextDialogue = 80180244,
          SpeakNpcId = 790013,
          Subtitle = "You have been at the Academy for so long and know so many core secrets, Silas will certainly not allow you to go wherever you please. So, you have three options now.",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90B1E"
        },
        [80180244] = {
          ContentFR = "{空格}",
          DialogueId = 80180244,
          GUID = "C8B90B48",
          IsBlack = 1,
          NextDialogue = 80180245,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_load\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90B48"
        },
        [80180245] = {
          Camera = "41.63623,-81.270996,178.802734,-10.80179,-16.399618,-113.192589,30.000002,125.0,false,DoNotOverride,2.8",
          ContentFR = "Première option : te laisser enfermer dans une prison ou un asile. Tu y passeras le reste de ta vie.",
          DialogueId = 80180245,
          FinalCamera = "48.197266,-83.916504,180.082031,-10.802736,-16.999601,-116.99115,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B90B72",
          NextDialogue = 80180246,
          SpeakNpcId = 790013,
          Subtitle = "A: Let them imprison you or commit you to an asylum, where you will spend the rest of your life.",
          TalkActionId = {
            [1] = "790013:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90B72"
        },
        [80180246] = {
          Camera = "109.578125,-199.028809,139.896484,-0.001007,2.399862,174.2034,30.000002,125.0,false,DoNotOverride,2.8",
          ContentFR = "Deuxième option : pointer cette arme sur ta tempe... et descendre en enfer.",
          DialogueId = 80180246,
          FinalCamera = "109.203613,-202.743164,139.896484,-0.001007,2.399862,174.2034,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B90B9C",
          NextDialogue = 80180247,
          SpeakNpcId = 790013,
          Subtitle = "B: Put this gun to your temple — and go straight to hell.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90B9C"
        },
        [80180247] = {
          Camera = "38.126953,-294.654297,141.544922,-0.001007,-3.199267,106.030937,35.0,300.532867,false,Manual,3.442178",
          ContentFR = "J’ai pensé à ces deux-là. Et la troisième ?",
          DialogueId = 80180247,
          FinalCamera = "44.895996,-292.64502,141.544922,-0.001008,-3.199267,107.03141,35.0,300.532867,false,Manual,3.442178",
          GUID = "C8B90B9D",
          NextDialogue = 80180248,
          SpeakNpcId = 790045,
          Subtitle = "I've thought about both of these options. What's the third one?",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90B9D"
        },
        [80180248] = {
          Camera = "250.523438,210.553223,66.386719,-0.001007,9.000072,-133.994293,30.000002,125.0,false,DoNotOverride,2.8",
          ContentFR = "Troisième option : faire une demande de transfert pour Fulvis. Partir au front... et mourir comme une vermine.",
          DialogueId = 80180248,
          FinalCamera = "250.523438,210.553223,66.386719,-0.001007,5.80006,-132.794342,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B90B9E",
          NextDialogue = 80180249,
          SpeakNpcId = 790013,
          Subtitle = "C: File a transfer request to Fulvis. Head to the front lines — and die like a maggot.",
          TalkActionId = {
            [1] = "790013:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90B9E"
        },
        [80180249] = {
          Camera = "46.905762,-84.696289,145.484375,-0.001007,-2.400326,-115.394318,30.000002,125.0,false,DoNotOverride,2.8",
          ContentFR = "Les balles te voleront ton orgueil. La douleur rongera ta dignité. Tes camarades tomberont un à un, jusqu’à briser ta volonté. Et ta foi... s’effondrera dans une mort sans sens.",
          DialogueId = 80180249,
          FinalCamera = "52.906738,-87.544922,145.484375,-0.001007,-2.400326,-118.794006,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B90BC6",
          NextDialogue = 80180250,
          SpeakNpcId = 790013,
          Subtitle = "The hail of bullets will shred your pride. The pain will rot your dignity. Watching your comrades fall — one by one — will grind your will to dust. And in the end, a meaningless death will devour what you once believed in.",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90BC6"
        },
        [80180250] = {
          Camera = "37.298828,51.883789,147.867188,-0.001007,-3.200312,-109.992836,30.000002,250.348099,false,Manual,2.8",
          ContentFR = "Mais si, par miracle, tu survis... Alors, reviens me voir.",
          DialogueId = 80180250,
          FinalCamera = "44.025879,49.503418,147.867188,-0.001007,-3.200319,-113.192429,30.000002,250.348099,false,Manual,2.8",
          GUID = "C8B90BF0",
          NextDialogue = 80180251,
          SpeakNpcId = 790013,
          Subtitle = "But if, by some miracle, you survive... Then come back to me —",
          TalkActionId = {
            [1] = "790045:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90BF0"
        },
        [80180251] = {
          Camera = "972.825684,719.781738,4.660156,-0.001007,3.199554,-144.190918,30.000002,250.348099,false,Manual,2.8",
          ContentFR = "Et dis-moi si <H>tu crois encore à tes idéaux.</>",
          DialogueId = 80180251,
          FinalCamera = "973.912109,718.088379,4.660156,-0.001007,3.399556,-143.391037,30.000002,250.348099,false,Manual,2.8",
          GUID = "C8B90C1A",
          SpeakNpcId = 790013,
          Subtitle = "And tell me if you still stay true to your ideals.",
          TalkActionId = {
            [1] = "790045:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90C1A"
        },
        [80180301] = {
          Camera = "269.386719,-113.140137,157.827637,0.000044,-6.800259,160.204285,30.000002,309.33728,false,Manual,1.2",
          ContentFR = "Voilà pourquoi j’ai quitté les Spathatoi. J’ai choisi de devenir infirmière de terrain, c’est sans doute la dernière décision que je puisse prendre pour moi-même.",
          DialogueId = 80180301,
          FinalCamera = "271.535156,-107.079102,157.827637,0.000044,-6.800259,160.80426,30.000002,309.33728,false,Manual,1.2",
          GUID = "C8B914A2",
          NextDialogue = 80180302,
          SpeakNpcId = 790045,
          Subtitle = "This is why I left the Spathatoi. I chose to become a field medic — perhaps the last decision I'll ever get to make for myself.",
          TalkActionId = {
            [1] = "790057:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B914A2"
        },
        [80180302] = {
          Camera = "-121.863525,337.176758,36.699707,0.000079,9.19965,-61.996338,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentFR = "Chère maman, quand tu entendras cet enregistrement, je serai déjà en route vers le front. Peut-être que je ne reviendrai pas. Je suis désolée de te dire adieu comme ça.",
          DialogueId = 80180302,
          FinalCamera = "-121.863525,337.176758,36.699707,0.000074,10.999657,-62.196552,30.000002,309.33728,false,DoNotOverride,1.2",
          GUID = "C8B914CC",
          NextDialogue = 80180303,
          SpeakNpcId = 790045,
          Subtitle = "Dear Mother... By the time you hear this recording, I'll be en route to the front lines. I may not return. I'm sorry to say goodbye this way.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B914CC"
        },
        [80180303] = {
          Camera = "-121.863525,337.176758,36.699707,0.000074,10.999657,-62.196552,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentFR = "Sur mon bureau, il y a une boîte de médicaments contre la douleur. Merci de la remettre à monsieur Roger Gaston à l’Hôpital des Deux-Rives. Je l’ai testée sur moi... ça fonctionne.",
          DialogueId = 80180303,
          GUID = "C8B914F6",
          NextDialogue = 80180304,
          SpeakNpcId = 790045,
          Subtitle = "There's a box of painkillers on my desk. Please pass it on to Mr Roger Gaston at Riverside Hospital. I've tested it on myself — it works.",
          TalkActionId = {
            [1] = "790057:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B914F6"
        },
        [80180304] = {
          Camera = "79.812988,-4.779297,137.84375,0.00008,-2.80035,168.601562,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentFR = "Pardonne-moi de ne pas avoir été à la hauteur de tes attentes, maman. Je suis la pire des filles... et la plus honteuse des désertrices.",
          DialogueId = 80180304,
          FinalCamera = "79.812988,-4.779297,137.84375,0.00008,2.399684,168.800461,30.000002,309.33728,false,DoNotOverride,1.2",
          GUID = "C8B91520",
          NextDialogue = 80180305,
          SpeakNpcId = 790045,
          Subtitle = "Forgive me for failing to live up to your hopes, Mother. I'm the world's worst daughter... and the most disgraceful deserter.",
          TalkActionId = {
            [1] = "790057:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91520"
        },
        [80180305] = {
          Camera = "429.874512,-79.35791,282.631104,0.000086,-25.399929,174.798096,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentFR = "Mais je ne regrette pas mon choix, car je crois qu’un jour, bien loin dans le futur,\n nous verrons l’aube d’une époque plus lumineuse.",
          DialogueId = 80180305,
          FinalCamera = "431.295898,-62.712891,282.631104,0.000086,-25.399921,179.798019,30.000002,309.33728,false,DoNotOverride,1.2",
          GUID = "C8B9154A",
          NextDialogue = 80180306,
          SpeakNpcId = 790045,
          Subtitle = "But I don't regret my choice. Because I believe — someday, far in the future — we'll witness the dawn of a brighter age.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9154A"
        },
        [80180306] = {
          Camera = "431.295898,-62.712891,282.631104,0.000086,-25.399921,179.798019,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentFR = "Alors, peut-être que quelqu’un viendra un jour se recueillir sur ma tombe et dira...",
          DialogueId = 80180306,
          GUID = "C8B91574",
          NextDialogue = 80180307,
          SpeakNpcId = 790045,
          Subtitle = "And maybe then, someone will stand at my grave... and say—",
          TalkActionId = {
            [1] = "790057:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91574"
        },
        [80180307] = {
          Camera = "126.79541,-93.274414,133.225342,0.000073,-1.399772,139.192261,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentFR = "Daphne Theodore, tu as fait ce qu’il fallait.",
          DialogueId = 80180307,
          FinalCamera = "105.866211,-75.204102,132.549316,0.000073,-0.599752,139.192261,30.000002,309.33728,false,DoNotOverride,1.2",
          GUID = "C8B9159E",
          NextDialogue = 80180308,
          SpeakNpcId = 790045,
          Subtitle = "Daphne Theodore, you did the right thing.",
          TalkActionId = {
            [1] = "790057:Explain02_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9159E"
        },
        [80180308] = {
          Camera = "105.866211,-75.204102,132.549316,0.000073,-0.599752,139.192261,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentFR = "...",
          DialogueId = 80180308,
          GUID = "C8B915C8",
          NextDialogue = 80180309,
          SpeakNpcId = 790057,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B915C8"
        },
        [80180309] = {
          Camera = "503.694824,337.953125,141.101562,21.599174,-5.399681,-139.205948,30.000002,606.763855,false,Manual,1.2",
          ContentFR = "Avar... regarde la fille que tu as élevée, elle te ressemble comme deux gouttes d’eau ! Comment a-t-elle pu... être aussi stupide, égoïste et bornée ?",
          DialogueId = 80180309,
          FinalCamera = "527.729492,358.695312,144.101807,21.599174,-5.399681,-139.205948,30.000002,606.763855,false,Manual,1.2",
          GUID = "C8B915F2",
          NextDialogue = 80180310,
          SpeakNpcId = 790057,
          Subtitle = "Avar... look at your daughter. She's just like you — cut from the same cloth! How could she be so... foolish, so selfish, so impossibly stubborn!",
          TalkActionId = {
            [1] = "790057:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B915F2"
        },
        [80180310] = {
          Camera = "173.015625,-19.455566,210.615723,0.000005,-26.399349,169.588226,30.000002,606.763855,false,DoNotOverride,1.2",
          ContentFR = "Incroyable ! Ne voit-elle pas qu’un simple aveu d’erreur, un peu d’humilité, ou même demander mon aide, aurait tout changé ?!",
          DialogueId = 80180310,
          FinalCamera = "175.425293,-8.150879,210.615723,0.000005,-26.399342,172.787903,30.000002,606.763855,false,DoNotOverride,1.2",
          GUID = "C8B9161C",
          NextDialogue = 80180311,
          SpeakNpcId = 790057,
          Subtitle = "Unbelievable! Doesn't she see it? A simple apology — a little compromise — or just asking for my help — and everything could've turned out differently!",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9161C"
        },
        [80180311] = {
          Camera = "175.425293,-8.150879,210.615723,0.000005,-26.399342,172.787903,30.000002,606.763855,false,DoNotOverride,1.2",
          ContentFR = "...",
          DialogueId = 80180311,
          GUID = "C8B91646",
          NextDialogue = 80180312,
          SpeakNpcId = 790057,
          Subtitle = "...",
          TalkActionId = {
            [1] = "790057:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91646"
        },
        [80180312] = {
          Camera = "-121.863525,337.176758,36.699707,0.000079,9.19965,-61.996338,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentFR = "... Mais... je me souviens maintenant.",
          DialogueId = 80180312,
          FinalCamera = "-121.863525,337.176758,36.699707,0.000074,10.999657,-62.196552,30.000002,309.33728,false,DoNotOverride,1.2",
          GUID = "C8B91670",
          NextDialogue = 80180313,
          SpeakNpcId = 790057,
          Subtitle = "...But now I remember.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91670"
        },
        [80180313] = {
          Camera = "-121.863525,337.176758,36.699707,0.000074,10.999657,-62.196552,30.000002,309.33728,false,DoNotOverride,1.2",
          ContentFR = "C’est cette même naïveté, cette même obstination folle, qui m’a poussée à te choisir, il y a des années. Au final... la vraie idiote, c’était moi.",
          DialogueId = 80180313,
          GUID = "C8B9169A",
          NextDialogue = 80180314,
          SpeakNpcId = 790057,
          Subtitle = "It was that same naivety... that same foolish defiance... that made me choose you, all those years ago. In the end... the real fool was me.",
          TalkActionId = {
            [1] = "790057:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9169A"
        },
        [80180314] = {
          ContentFR = "Vous deux... vous devez... revenir vivants.",
          DialogueId = 80180314,
          GUID = "C8B916C4",
          IsBlack = 1,
          SpeakNpcId = 790057,
          Subtitle = "You two... Please... Come back alive.",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B916C4"
        },
        [80180315] = {
          Camera = "6.101562,-49.640625,124.166504,0.000013,8.197476,156.384064,30.000002,125.0,false,DoNotOverride,2.8",
          ContentFR = "Tu es là, tant mieux ! Viens vite, suis-moi...",
          DialogueId = 80180315,
          FinalCamera = "8.539062,-43.953125,124.166504,0.000013,8.19747,159.784409,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B916EE",
          NextDialogue = 80180316,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_battlegroundamb\"},PlayAs2D{true}}",
          SpeakNpcId = 790045,
          Subtitle = "Thank goodness you're here! Hurry, come with—",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B916EE"
        },
        [80180316] = {
          Camera = "-207.921875,-77.121094,192.568481,-0.000763,-28.411339,25.592079,30.000002,125.0,false,DoNotOverride,2.8",
          ContentFR = "Daphne, ma jambe est cassée, je ne peux plus marcher.",
          DialogueId = 80180316,
          FinalCamera = "-207.921875,-77.121094,192.568481,-0.000763,-31.811392,25.591383,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B91718",
          NextDialogue = 80180317,
          SpeakNpcId = 110029,
          SpeakNpcName = "UI_Npc_Name_Shibing1",
          Subtitle = "Daphne... my leg's broken. I can't move...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91718"
        },
        [80180317] = {
          Camera = "-14.828125,-78.089844,22.154419,-0.000763,8.188918,41.38969,30.000002,125.0,false,DoNotOverride,2.8",
          ContentFR = "Laisse-moi... va sauver... les autres...",
          DialogueId = 80180317,
          FinalCamera = "-20.101562,-71.96875,22.154419,-0.000763,8.188918,38.389439,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B91742",
          NextDialogue = 80180318,
          SpeakNpcId = 110029,
          SpeakNpcName = "UI_Npc_Name_Shibing1",
          Subtitle = "Just leave me here... Go help the others...",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91742"
        },
        [80180318] = {
          Camera = "264.460938,-208.398438,17.238892,-0.000763,7.587547,140.188553,30.000002,125.0,false,DoNotOverride,2.8",
          ContentFR = "Non, on est encore en zone de tir ennemie. Si tu restes ici, tu vas mourir !",
          DialogueId = 80180318,
          FinalCamera = "264.460938,-208.398438,17.238892,-0.000763,9.787565,140.388489,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B9176C",
          LookAt = {
            [1] = "790045:n(110029)"
          },
          NextDialogue = 80180319,
          SpeakNpcId = 790045,
          Subtitle = "No — we're still in range of enemy fire. If you stay, you'll die!",
          TalkActionId = {
            [1] = "790045:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9176C"
        },
        [80180319] = {
          Camera = "839.445312,-1032.527344,775.925781,-0.000763,-28.213598,126.587334,30.000002,1439.973022,false,Manual,1.2",
          ContentFR = "Je vais faire un bandage pour immobiliser ta jambe... je vais t’emmener au poste de secours. Ça ira, tu verras !",
          DialogueId = 80180319,
          FinalCamera = "808.445312,-1055.539062,775.925781,-0.000763,-28.213598,126.587334,30.000002,1439.973022,false,Manual,1.2",
          GUID = "C8B91796",
          NextDialogue = 80180320,
          SpeakNpcId = 790045,
          Subtitle = "We'll stabilise the fracture now. I'll carry you to the temporary shelter. You're going to be all right!",
          TalkActionId = {
            [1] = "790045:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91796"
        },
        [80180320] = {
          ContentFR = "N’aie pas peur, monte sur mon dos...",
          DialogueId = 80180320,
          GUID = "C8B917C0",
          IsBlack = 1,
          SpeakNpcId = 790045,
          Subtitle = "Don't be afraid... Climb on my back.",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B917C0"
        },
        [80180321] = {
          Camera = "513.552734,-224.316406,18.752075,0.000019,6.799938,154.605255,30.000002,529.988831,false,Manual,1.2",
          ContentFR = "Les bombardements... les grognements des Souillés... je n’entends plus rien...",
          DialogueId = 80180321,
          FinalCamera = "506.753906,-238.71875,18.752075,0.000019,6.799938,152.005585,30.000002,529.988831,false,Manual,1.2",
          GUID = "C8B917EA",
          LookAt = {
            [1] = "790045:n(110028)"
          },
          NextDialogue = 80180322,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_battlegroundamb\"},PlayAs2D{true}}",
          SpeakNpcId = 110028,
          SpeakNpcName = "UI_Npc_Name_Shibing2",
          Subtitle = "The shelling... The Filthoid growls... I can't hear them anymore...",
          TalkActionId = {
            [1] = "790045:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B917EA"
        },
        [80180322] = {
          Camera = "196.876953,34.6875,120.079834,0.000088,-26.199738,159.806366,30.000002,529.988831,false,DoNotOverride,1.2",
          ContentFR = "Mademoiselle, on... rentre à la maison... ?",
          DialogueId = 80180322,
          FinalCamera = "196.876953,34.6875,120.079834,0.000088,-22.799608,159.406357,30.000002,529.988831,false,DoNotOverride,1.2",
          GUID = "C8B91814",
          NextDialogue = 80180323,
          SpeakNpcId = 110028,
          SpeakNpcName = "UI_Npc_Name_Shibing2",
          Subtitle = "Miss... are we... going home?",
          TalkActionId = {
            [1] = "790045:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91814"
        },
        [80180323] = {
          Camera = "87.494141,6.46875,123.438232,0.000091,8.600396,-139.792511,30.000002,529.988831,false,DoNotOverride,1.2",
          ContentFR = "Oui... Je t’ai donné un puissant antidouleur, il marche bien. Ferme les yeux, repose-toi un peu... on sera bientôt chez nous.",
          DialogueId = 80180323,
          FinalCamera = "90.357422,3.183594,123.438232,0.00009,8.600396,-141.992706,30.000002,529.988831,false,DoNotOverride,1.2",
          GUID = "C8B9183E",
          NextDialogue = 80180324,
          SpeakNpcId = 790045,
          Subtitle = "...Yes. I gave you a strong painkiller. Just close your eyes and rest... We'll be home soon.",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9183E"
        },
        [80180324] = {
          Camera = "3.556641,-141.828125,170.939697,0.000186,-23.799309,78.602211,30.000002,249.318649,false,Manual,2.618686",
          ContentFR = "Non, tu mens... on ne rentrera pas.",
          DialogueId = 80180324,
          FinalCamera = "0.082031,-141.308594,170.939697,0.000187,-23.799301,76.601868,30.000002,249.318649,false,Manual,2.618686",
          GUID = "C8B91868",
          NextDialogue = 80180325,
          SpeakNpcId = 110028,
          SpeakNpcName = "UI_Npc_Name_Shibing2",
          Subtitle = "No... you're lying. There's no way back.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91868"
        },
        [80180325] = {
          Camera = "173.759766,145.246094,54.668579,0.000196,13.199661,-141.398911,30.000002,249.318649,false,DoNotOverride,2.618686",
          ContentFR = "Dismania est trop loin, il pleut des trombes d’eau, les routes sont boueuses... on ne pourra pas revenir...",
          DialogueId = 80180325,
          FinalCamera = "173.759766,145.246094,54.668579,0.000197,10.999637,-141.39917,30.000002,249.318649,false,DoNotOverride,2.618686",
          GUID = "C8B91892",
          NextDialogue = 80180326,
          SpeakNpcId = 110028,
          SpeakNpcName = "UI_Npc_Name_Shibing2",
          Subtitle = "Dismania's too far... The rain's pouring. The roads are all mud. We'll never make it back...",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91892"
        },
        [80180326] = {
          Camera = "173.759766,145.246094,54.668579,0.000197,10.999637,-141.39917,30.000002,249.318649,false,DoNotOverride,2.618686",
          ContentFR = "Mademoiselle... veuillez transmettre un message à ma mère...",
          DialogueId = 80180326,
          GUID = "C8B918BC",
          NextDialogue = 80180327,
          SpeakNpcId = 110028,
          SpeakNpcName = "UI_Npc_Name_Shibing2",
          Subtitle = "Miss... please... Tell my mother...",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B918BC"
        },
        [80180327] = {
          Camera = "10.199219,-121.546875,161.82373,0.000328,-23.799868,82.186981,30.000002,233.226471,false,Manual,4.18986",
          ContentFR = "Troisième tiroir de la bibliothèque... le parfum... c’était pour son anniversaire... je voulais lui faire une surprise...",
          DialogueId = 80180327,
          FinalCamera = "6.730469,-121.144531,161.82373,0.000328,-23.799868,79.786621,30.000002,233.226471,false,Manual,4.18986",
          GUID = "C8B918E6",
          NextDialogue = 80180328,
          SpeakNpcId = 110028,
          Subtitle = "Third drawer in the bookshelf... The perfume... It was for her birthday... I wanted to... surprise her...",
          TalkActionId = {
            [1] = "790045:Talk03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B918E6"
        },
        [80180328] = {
          Camera = "513.552734,-224.316406,18.752075,0.000019,6.799938,154.605255,30.000002,529.988831,false,Manual,1.2",
          ContentFR = "D’accord... je te le promets. Je lui transmettrai.",
          DialogueId = 80180328,
          FinalCamera = "506.753906,-238.71875,18.752075,0.000019,6.799938,152.005585,30.000002,529.988831,false,Manual,1.2",
          GUID = "C8B91910",
          NextDialogue = 80180329,
          SpeakNpcId = 790045,
          Subtitle = "...I promise. I'll get your message to her.",
          TalkActionId = {
            [1] = "790045:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91910"
        },
        [80180329] = {
          Camera = "87.494141,6.46875,123.438232,0.000091,8.600396,-139.792511,30.000002,529.988831,false,DoNotOverride,1.2",
          ContentFR = "Attention ! C’est un Drone magnétique ennemi !",
          DialogueId = 80180329,
          FinalCamera = "90.357422,3.183594,123.438232,0.00009,8.600396,-141.992706,30.000002,529.988831,false,DoNotOverride,1.2",
          GUID = "C8B9193A",
          NextDialogue = 80180330,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_cibao\"},PlayAs2D{true}}",
          SpeakNpcName = "UI_Npc_Name_Shibing3",
          Subtitle = "Look out! Hostile Magnetix Drones!",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9193A"
        },
        [80180330] = {
          ContentFR = "... !",
          DialogueId = 80180330,
          GUID = "C8B91964",
          IsBlack = 1,
          SpeakNpcId = 790045,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91964"
        },
        [80180331] = {
          Camera = "146.429688,96.429688,150.266846,0.000012,-9.59936,-155.996857,30.000002,288.725769,false,Manual,2.8",
          ContentFR = "Tu te sens mieux ?",
          DialogueId = 80180331,
          FinalCamera = "148.185547,92.328125,150.266846,0.000011,-9.59936,-156.997086,30.000002,288.725769,false,Manual,2.8",
          GUID = "C8B9198E",
          NextDialogue = 80180332,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_cibao\"},PlayAs2D{true}}",
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          Subtitle = "Feeling better now?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B9198E"
        },
        [80180332] = {
          Camera = "47.626953,1.003906,177.767212,0.000037,-24.198778,64.204277,30.000002,288.725769,false,DoNotOverride,2.8",
          ContentFR = "Oui. Merci d’avoir détruit ces drones.",
          DialogueId = 80180332,
          FinalCamera = "43.027344,3.367188,177.767212,0.000031,-24.198792,61.204487,30.000002,288.725769,false,DoNotOverride,2.8",
          GUID = "C8B919B8",
          NextDialogue = 80180333,
          SpeakNpcId = 790045,
          Subtitle = "Yeah. Thanks for taking out the Magnetix Drones.",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B919B8"
        },
        [80180333] = {
          Camera = "-277.273438,-616.734375,167.08728,0.00006,-8.597869,70.799004,30.000002,598.523071,false,Manual,1.2",
          ContentFR = "Tu es folle ? Te jeter sur un blessé comme ça ! Il était condamné, tu voulais mourir avec lui ? Si tu mourais, que feraient les autres blessés sans toi ?",
          DialogueId = 80180333,
          FinalCamera = "-264.697266,-621.226562,167.08728,0.00006,-8.597869,71.198959,30.000002,598.523071,false,Manual,1.2",
          GUID = "C8B919E2",
          NextDialogue = 80180334,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          Subtitle = "Are you out of your mind? Throwing yourself over a dying soldier like that!? He was clearly a goner — were you trying to get yourself killed too? If you'd died, what were the rest of the wounded supposed to do without you?",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B919E2"
        },
        [80180334] = {
          Camera = "-264.697266,-621.226562,167.08728,0.00006,-8.597869,71.198959,30.000002,598.523071,false,Manual,1.2",
          ContentFR = "...",
          DialogueId = 80180334,
          GUID = "C8B91A0C",
          NextDialogue = 80180335,
          SpeakNpcId = 790045,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91A0C"
        },
        [80180335] = {
          Camera = "19.4375,-31.675781,136.009277,0.000104,1.00259,58.791103,30.000008,598.523071,false,DoNotOverride,1.2",
          ContentFR = "... Hé hé.",
          DialogueId = 80180335,
          FinalCamera = "23.224609,-34.007812,136.009277,0.000104,1.00259,60.590927,30.000008,598.523071,false,DoNotOverride,1.2",
          GUID = "C8B91A36",
          NextDialogue = 80180336,
          SpeakNpcId = 790045,
          Subtitle = "...Hehe.",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91A36"
        },
        [80180336] = {
          Camera = "163.349609,102.542969,151.724365,0.000122,-8.39728,-154.012268,30.000008,303.919434,false,Manual,2.099485",
          ContentFR = "Pourquoi tu ris ?",
          DialogueId = 80180336,
          FinalCamera = "166.277344,96.828125,151.724365,0.000123,-8.39728,-157.012573,30.000008,303.919434,false,Manual,2.099485",
          GUID = "C8B91A60",
          NextDialogue = 80180337,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          Subtitle = "What's so funny?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91A60"
        },
        [80180337] = {
          Camera = "-236.851562,-653.707031,37.399048,0.000145,5.401894,72.381973,40.0,784.897949,false,Manual,1.422013",
          ContentFR = "Tu me rappelles ma mère... et mon aînée, quand j’étais étudiante. Si elles étaient ici, elles diraient la même chose.",
          DialogueId = 80180337,
          FinalCamera = "-221.035156,-658.710938,37.399048,0.000145,5.401894,73.181877,40.0,784.897949,false,Manual,1.422013",
          GUID = "C8B91A8A",
          NextDialogue = 80180338,
          SpeakNpcId = 790045,
          Subtitle = "You remind me of my mother. And my senior, back when I was a student. If they were here... they'd have said the same thing.",
          TalkActionId = {
            [1] = "790045:Sigh_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91A8A"
        },
        [80180338] = {
          Camera = "-221.035156,-658.710938,37.399048,0.000145,5.401894,73.181877,40.0,784.897949,false,Manual,1.422013",
          ContentFR = "Elles espéraient que j’apprenne, mais je n’y suis jamais parvenue.",
          DialogueId = 80180338,
          GUID = "C8B91AB4",
          NextDialogue = 80180339,
          SpeakNpcId = 790045,
          Subtitle = "They always hoped I'd learn. But I never did.",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91AB4"
        },
        [80180339] = {
          Camera = "-4.738281,-90.714844,105.755493,0.000144,6.801099,61.380829,40.0,784.897949,false,DoNotOverride,1.422013",
          ContentFR = "Il y a tant de gens rationnels dans ce monde. Ils pèsent le pour et le contre... choisissent toujours \"la moins mauvaise\" option. Ce sont des leaders nés, qui tracent la voie de chaque époque.",
          DialogueId = 80180339,
          FinalCamera = "-4.738281,-90.714844,105.755493,0.00014,8.801094,61.180855,40.0,784.897949,false,DoNotOverride,1.422013",
          GUID = "C8B91ADE",
          NextDialogue = 80180340,
          SpeakNpcId = 790045,
          Subtitle = "There are so many rational people in this world. They weigh cost against benefit — always choose the \"least bad\" option. They're born leaders. They steer the course of every era.",
          TalkActionId = {
            [1] = "790045:Sigh_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91ADE"
        },
        [80180340] = {
          Camera = "997.089844,-499.308594,-19.915771,0.000057,6.20341,151.968689,40.0,1144.406128,false,Manual,1.422013",
          ContentFR = "Mais moi, je ne suis pas comme eux. Je n’ai jamais su me calmer au point de penser si loin. Tout ce que j’entends... ce sont les pleurs juste devant moi.",
          DialogueId = 80180340,
          FinalCamera = "993.359375,-506.820312,-19.915771,0.000057,6.20341,150.768692,40.0,1144.406128,false,Manual,1.422013",
          GUID = "C8B91B08",
          NextDialogue = 80180341,
          SpeakNpcId = 790045,
          Subtitle = "But I'm not one of them. I've never been calm enough to think that far ahead. All I can hear... are the cries right in front of me.",
          TalkActionId = {
            [1] = "790045:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91B08"
        },
        [80180341] = {
          Camera = "32.263672,-32.617188,205.199585,0.00012,-27.195707,64.570541,40.0,1144.406128,false,DoNotOverride,1.422013",
          ContentFR = "Pourtant... je crois qu’une ère meilleure doit laisser une place, même aux imprudents comme moi qui ne voient pas loin.",
          DialogueId = 80180341,
          FinalCamera = "37.583984,-35.265625,205.105835,0.000127,-27.195707,67.17112,40.0,1144.406128,false,DoNotOverride,1.422013",
          GUID = "C8B91B32",
          NextDialogue = 80180342,
          SpeakNpcId = 790045,
          Subtitle = "Still... I believe a better era should have room — even for short-sighted fools like me.",
          TalkActionId = {
            [1] = "790045:Explain01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91B32"
        },
        [80180342] = {
          Camera = "163.349609,102.542969,151.724365,0.000122,-8.39728,-154.012268,30.000008,303.919434,false,Manual,2.099485",
          ContentFR = "Qu’est-ce que tu racontes...",
          DialogueId = 80180342,
          FinalCamera = "166.277344,96.828125,151.724365,0.000123,-8.39728,-157.012573,30.000008,303.919434,false,Manual,2.099485",
          GUID = "C8B91B5C",
          NextDialogue = 80180343,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          Subtitle = "What are you talking about...",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91B5C"
        },
        [80180343] = {
          Camera = "-173.388672,-447.8125,33.189331,0.00006,9.004928,71.363441,40.0,1144.406128,false,DoNotOverride,1.422013",
          ContentFR = "Désolée... je me suis un peu emportée. Ne t’inquiète pas pour le reste. Sache juste que si tu es blessé, je ne t’abandonnerai pas.",
          DialogueId = 80180343,
          FinalCamera = "-154.09375,-454.523438,33.189331,0.000057,9.004921,73.362991,40.0,1144.406128,false,DoNotOverride,1.422013",
          GUID = "C8B91B86",
          NextDialogue = 80180344,
          SpeakNpcId = 790045,
          Subtitle = "Sorry... I got a little carried away. Just remember this — if you're ever hurt, I won't leave you behind.",
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91B86"
        },
        [80180344] = {
          Camera = "62.640625,-18.921875,119.119995,0.000043,3.604052,-161.235825,40.0,1144.406128,false,DoNotOverride,1.422013",
          ContentFR = "... Alors souviens-toi aussi de ne pas prendre ta vie à la légère. Les vivants peuvent faire bien plus que les morts.",
          DialogueId = 80180344,
          FinalCamera = "65.09375,-25.960938,119.119995,0.000042,3.604052,-162.835632,40.0,1144.406128,false,DoNotOverride,1.422013",
          GUID = "C8B91BB0",
          NextDialogue = 80180345,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          Subtitle = "...Then you remember this — your life matters too. Don't act like it doesn't. The living can do far more than the dead.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91BB0"
        },
        [80180345] = {
          Camera = "65.09375,-25.960938,119.119995,0.000042,3.604052,-162.835632,40.0,1144.406128,false,DoNotOverride,1.422013",
          ContentFR = "« Porter la volonté de ses camarades en vivant est aussi noble que de mourir pour eux », c’est ce que le Commandant Avar nous a dit.",
          DialogueId = 80180345,
          GUID = "C8B91BDA",
          NextDialogue = 80180346,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          Subtitle = "\"To carry your comrades' will and live — that's as noble as dying for them.\" That's what Commander Avar once told us.",
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91BDA"
        },
        [80180346] = {
          Camera = "-150.710938,-191.480469,126.76355,0.000074,-0.195801,55.361076,45.0,362.249939,false,Manual,3.206755",
          ContentFR = "Il... il a vraiment dit ça ?",
          DialogueId = 80180346,
          FinalCamera = "-145.195312,-195.398438,126.76355,0.000074,-0.195801,57.360607,45.0,362.249939,false,Manual,3.206755",
          GUID = "C8B91C04",
          NextDialogue = 80180347,
          SpeakNpcId = 790045,
          Subtitle = "He... said that?",
          TalkActionId = {
            [1] = "790045:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91C04"
        },
        [80180347] = {
          Camera = "-23.109375,-128.339844,101.804077,0.0001,7.60392,62.159901,45.0,242.334976,false,Manual,3.206755",
          ContentFR = "Je m’en souviendrai.",
          DialogueId = 80180347,
          FinalCamera = "-19.283203,-130.453125,101.804077,0.000098,7.60392,63.560059,45.0,254.569183,false,Manual,3.206755",
          GUID = "C8B91C2E",
          NextDialogue = 80180348,
          SpeakNpcId = 790045,
          Subtitle = "I'll keep that in mind.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91C2E"
        },
        [80180348] = {
          Camera = "-19.283203,-130.453125,101.804077,0.000098,7.60392,63.560059,45.0,254.569183,false,Manual,3.206755",
          ContentFR = "Ça ira pour le moment, il est temps que je parte.",
          DialogueId = 80180348,
          GUID = "C8B91C58",
          NextDialogue = 80180349,
          SpeakNpcId = 790045,
          Subtitle = "That's enough rest. Time to move on.",
          TalkActionId = {
            [1] = "790045:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91C58"
        },
        [80180349] = {
          Camera = "1023.142578,-512.480469,-28.856567,0.000109,7.203766,151.359207,45.0,1202.78186,false,Manual,2.168443",
          ContentFR = "Où ça ?",
          DialogueId = 80180349,
          FinalCamera = "1013.601562,-529.96875,-28.856567,0.000109,7.203766,151.359207,45.0,1202.78186,false,Manual,2.168443",
          GUID = "C8B91C82",
          NextDialogue = 80180350,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          Subtitle = "Where are you going?",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91C82"
        },
        [80180350] = {
          Camera = "1013.601562,-529.96875,-28.856567,0.000109,7.203766,151.359207,45.0,1202.78186,false,Manual,2.168443",
          ContentFR = "Chercher du matériel d’urgence... et puis...",
          DialogueId = 80180350,
          GUID = "C8B91CAC",
          NextDialogue = 80180351,
          SpeakNpcId = 790045,
          Subtitle = "To check for emergency supplies. And then...",
          TalkActionId = {
            [1] = "790045:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91CAC"
        },
        [80180351] = {
          Camera = "-128.251953,-146.082031,134.427856,0.000144,-1.196642,52.959221,45.0,317.18219,false,Manual,6.360716",
          ContentFR = "Retrouver le Capitaine {nickname2} pour m’assurer {性别:qu’il|qu’elle} va bien.",
          DialogueId = 80180351,
          FinalCamera = "-126.076172,-147.757812,134.427856,0.000144,-1.196642,53.559261,45.0,317.18219,false,Manual,6.360716",
          GUID = "C8B91CD6",
          SpeakNpcId = 790045,
          Subtitle = "To find Captain , and make sure {性别2:he|she}'s safe.",
          TalkActionId = {
            [1] = "790045:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91CD6"
        },
        [80180352] = {
          Camera = "-14.550781,-91.125,107.247437,0.000139,8.803205,58.55764,45.0,317.18219,false,Manual,6.360716",
          ContentFR = "<I>En traversant un chemin jonché de cadavres, j’entends mon souffle lourd, je sens les battements de mon cœur. Jamais je ne me suis sentie aussi petite.</>",
          DialogueId = 80180352,
          FinalCamera = "-9.892578,-94.234375,107.247437,0.000138,8.803205,60.757439,45.0,317.18219,false,Manual,6.360716",
          GUID = "C8B91D00",
          IsBlack = 1,
          NextDialogue = 80180353,
          SpeakNpcId = 790045,
          Subtitle = [[
As I moved through the path strewn with corpses, I could hear my own ragged breath.
Feel the thud of my own heartbeat. Never had I felt so small.]],
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D00"
        },
        [80180353] = {
          Camera = "-9.892578,-94.234375,107.247437,0.000138,8.803205,60.757439,45.0,317.18219,false,Manual,6.360716",
          ContentFR = "<I>J’ai vaincu mes camarades, survécu aux expériences, dompté la douleur... Je pensais être invincible. Mais aujourd’hui, je comprends : il y a bien plus de choses que je ne pourrai jamais vaincre, que celles que je peux.</>",
          DialogueId = 80180353,
          GUID = "C8B91D2A",
          IsBlack = 1,
          NextDialogue = 80180354,
          SpeakNpcId = 790045,
          Subtitle = "I had bested my classmates, survived experiments, overcome pain... I once thought I was invincible.\nBut now I understand — there are far more things I cannot conquer... than those I can.",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D2A"
        },
        [80180354] = {
          Camera = "47.957031,-1250.3125,16.771729,0.000155,3.202962,92.956001,45.0,317.18219,false,Manual,6.360716",
          ContentFR = "<I>Quoi qu’il arrive, j’espère qu’à la fin de cette bataille, que ce soit moi, ou mon âme seulement, je pourrai porter ces mots à Sibylle Mason...</>",
          DialogueId = 80180354,
          FinalCamera = "76.232422,-1248.960938,16.771729,0.000158,3.202962,93.755997,45.0,317.18219,false,Manual,6.360716",
          GUID = "C8B91D54",
          IsBlack = 1,
          SpeakNpcId = 790045,
          Subtitle = "Still, whatever lies ahead... When this battle ends... Whether I make it out alive, or only my soul returns —\nI hope I can carry these words to Sibylle Mason—",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D54"
        },
        [80180355] = {
          Camera = "76.232422,-1248.960938,16.771729,0.000158,3.202962,93.755997,45.0,317.18219,false,Manual,6.360716",
          ContentFR = "<H>Daphne Theodore reste fidèle à ses idéaux.</>",
          DialogueId = 80180355,
          GUID = "C8B91D7E",
          IsBlack = 1,
          SpeakNpcId = 790045,
          Subtitle = "\"Daphne Theodore stays true to her ideals.\"",
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D7E"
        },
        [80190001] = {
          ContentFR = "Manger et boire gratuitement ? Je ne vais pas me gêner, faut pas être idiot au point de laisser passer ça.",
          DialogueId = 80190001,
          GUID = "C8BF4C0A",
          Subtitle = "Free food and drink? Don't mind if I do — only a fool would turn down a freebie."
        },
        [80190101] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          DialogueId = 80190101,
          Duration = 3,
          GUID = "C8BF5C72",
          NextDialogue = 80190102,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190102] = {
          ContentFR = "Tu vis {性别:tout seul|toute seule} dans une maison aussi grande ? Pas mal... et en plus t’as même un vrai bar installé.",
          DialogueId = 80190102,
          FacialId = {
            [1] = "95102:Shock01"
          },
          GUID = "C8BF5C9C",
          NextDialogue = 80190103,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "You've got this big place all to yourself? Not bad — even set up a proper bar, I see.",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190103] = {
          ContentFR = "C’est bien ça. Faut inviter plus d’amis, comme ça tu te fais un réseau à Givrelac.",
          DialogueId = 80190103,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF5CC6",
          NextDialogue = 80190104,
          SpeakNpcId = 95102,
          Subtitle = "Good for you. You ought to have friends over more often — never hurts to build a few ties in Icelake."
        },
        [80190104] = {
          ContentFR = "Bon, alors, qu’est-ce que tu veux cette fois ? Si c’est trop compliqué, oublie. J’ai un boulot important en ce moment.",
          DialogueId = 80190104,
          GUID = "C8BF5CF0",
          NextOptions = {
            [1] = 801901041,
            [2] = 801901042
          },
          SpeakNpcId = 95102,
          Subtitle = "Alright then — what do you want this time? If it's anything too much of a bother, I'm out. Got a big job hanging over me lately.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190105] = {
          ContentFR = "Beurk... ça me donne la chair de poule. Je peux le supporter, mais si tu sors ce genre de phrase à tout le monde, y’en a qui vont s’étouffer avec leur bière.",
          DialogueId = 80190105,
          GUID = "C8BF5D1A",
          NextDialogue = 80190107,
          SpeakNpcId = 95102,
          Subtitle = "Oof... That's sweet enough to rot my teeth. I'll let it slide — but if you say that to everyone you drink with, someone's bound to choke on their pint.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190106] = {
          ContentFR = "Voilà qui me plaît. Laisse-moi goûter à ta préparation.",
          DialogueId = 80190106,
          GUID = "C8BF5D44",
          NextDialogue = 80190107,
          SpeakNpcId = 95102,
          Subtitle = "Now that's more like it. Let's see if your mix is worth the pour.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190107] = {
          ContentFR = "{空格}",
          DialogueId = 80190107,
          Duration = 3,
          GUID = "C8BF5D6E",
          NextDialogue = 80190108,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190108] = {
          ContentFR = "Hmm... Sucré avec une pointe d’acidité, servi chaud. Ça vaut presque le niveau des Asphodèles, mais avec ta touche perso.",
          DialogueId = 80190108,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF5D98",
          NextDialogue = 80190109,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "Hmm... Sweet, with a tangy edge. Served warm, too — not bad at all. I'd say it's on par with the stuff back at The Asphodel, though you've definitely added your own twist.",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190109] = {
          ContentFR = "Cette boisson a dû te demander pas mal d’efforts. Franchement, c’est au-dessus de mes attentes. Honnêtement, j’aurais bu un simple verre d’eau chaude sans râler, pas besoin de se prendre la tête.",
          DialogueId = 80190109,
          GUID = "C8BF5DC2",
          NextDialogue = 80190110,
          SpeakNpcId = 95102,
          Subtitle = "Bet this one took a fair bit of effort, eh? Didn't expect a drink this good, to be honest. Even just a warm cup of water would've done the trick — I'm easy. No need to pull out all the stops."
        },
        [80190110] = {
          ContentFR = "Mais bon, tu as l’air {性别:motivé|motivée}... Ah, j’ai compris. T’as mis un peu d’argent de côté et maintenant tu veux te faire plaisir : inviter des gens, boire un coup, acheter des babioles... En langage moderne, ça s’appelle \"payer pour s’amuser\", non ?",
          DialogueId = 80190110,
          GUID = "C8BF5DEC",
          NextOptions = {
            [1] = 801901101,
            [2] = 801901102
          },
          SpeakNpcId = 95102,
          Subtitle = "You're looking rather chipper though... ah, I get it. Got a bit of coin lying around, huh? Thought you'd splash out — parties, drinks, maybe a new trinket or two. That's what they call \"buying a good time\" these days, right?"
        },
        [80190111] = {
          ContentFR = "Mais t’invites les gens pour parler, non ? Ça prouve que je suis celui qui te comprend le mieux, et que je suis le plus respectueux.",
          DialogueId = 80190111,
          GUID = "C8BF5E16",
          NextDialogue = 80190113,
          SpeakNpcId = 95102,
          Subtitle = "Well, isn't that the whole point? You pour someone a drink, you get a proper chat. Just means I know how to read the room — and I've got the decency to play along.",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190112] = {
          ContentFR = "Hé, hé, c’est ma faute, c’est ma faute. C’est ta maison, c’est toi {性别:le patron|la patronne}. Tu peux même me frapper pour te défouler.",
          DialogueId = 80190112,
          GUID = "C8BF5E40",
          NextDialogue = 80190113,
          SpeakNpcId = 95102,
          Subtitle = "Whoa now, my bad! Your place, your booze — that makes you the boss. Here — throw a punch if it'll help you blow off some steam.",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190113] = {
          ContentFR = "Je plaisante, mais soyons clairs. Crois-en quelqu’un qui a roulé sa bosse : tout le monde ne mérite pas qu’on l’invite à boire comme un \"ami\".",
          DialogueId = 80190113,
          GUID = "C8BF5E6A",
          NextDialogue = 80190114,
          SpeakNpcId = 95102,
          Subtitle = "Kidding, obviously. But if you're after a bit of advice from someone who's been around — not everyone's worth the drink or the word \"friend.\"",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190114] = {
          ContentFR = "Surtout dans un endroit comme Givrelac, y’a toujours des profiteurs qui te tournent autour, essayant de grappiller ce que t’as.",
          DialogueId = 80190114,
          GUID = "C8BF5E94",
          NextDialogue = 80190115,
          SpeakNpcId = 95102,
          Subtitle = "Especially not in a place like Icelake. Always some grinning bastard eyeing your pockets, buttering you up just to find a way in."
        },
        [80190115] = {
          ContentFR = "Ils sourient, te flattent, te mettent sur un piédestal... mais quand ça chauffe, tu as plus de chances en comptant sur un chien errant.",
          DialogueId = 80190115,
          GUID = "C8BF5EBE",
          NextOptions = {
            [1] = 801901151
          },
          SpeakNpcId = 95102,
          Subtitle = "They'll smile, flatter, make you feel like you're the sun — and the second you're in trouble? You'd have better luck counting on a stray dog.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190116] = {
          ContentFR = "Ah, t’as tout pigé. Moi, l’Étranger, je suis le roi des profiteurs. Si y’a de la bouffe ou de l’alcool gratuit, je le sens à des kilomètres, et tu peux être sûr que je débarque.",
          DialogueId = 80190116,
          GUID = "C8BF5EE8",
          NextDialogue = 80190117,
          SpeakNpcId = 95102,
          Subtitle = "Ding ding ding — got me! I, Outsider, am the finest freeloader you'll ever meet. Disguised, of course, as a charming drinking buddy. If there's free booze or a hot meal, I'll sniff it out from a mile off.",
          TalkActionId = {
            [1] = "95102:Sit_AgreeHead"
          }
        },
        [80190117] = {
          ContentFR = "Ceux qui veulent ce titre doivent se mesurer à moi. Et ceux qui espèrent profiter de toi devront attendre que j’aie fini mon festin.",
          DialogueId = 80190117,
          GUID = "C8BF5F12",
          NextOptions = {
            [1] = 801901171,
            [2] = 801901172
          },
          SpeakNpcId = 95102,
          Subtitle = "Anyone wants the title, they'll have to fight me for it. And those who're planning to eat off your plate, they can only wait until I've had my fill."
        },
        [80190118] = {
          ContentFR = "Hé, attends ! J’ai pas fini moi.",
          DialogueId = 80190118,
          GUID = "C8BF5F3C",
          NextDialogue = 80190120,
          SpeakNpcId = 95102,
          Subtitle = "Oi, oi — no need to be hasty. I've only just got comfy.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190119] = {
          ContentFR = "Hein ? De quoi tu parles ? Ça m’échappe complètement.",
          DialogueId = 80190119,
          GUID = "C8BF5F66",
          NextDialogue = 80190120,
          SpeakNpcId = 95102,
          Subtitle = "Hmm? What's that now? No idea what you're talking about.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190120] = {
          ContentFR = "La boisson est bonne, verse-m’en une autre. Après ça, je retourne bosser.",
          DialogueId = 80190120,
          GUID = "C8BF5F90",
          SpeakNpcId = 95102,
          Subtitle = "But hey — the drink's good. Pour me another before I drag myself back to the grind."
        },
        [80190201] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentFR = "Ah, je suis en retard d’une demi-heure, hein ? C’est ma faute. Pour me faire pardonner, même si ton breuvage du jour avait le goût de hareng dans une chaussette sale, je le descends cul sec !",
          DialogueId = 80190201,
          FacialId = {
            [1] = "95102:Ahaha01"
          },
          GUID = "C8BF6CDA",
          NextOptions = {
            [1] = 801902011,
            [2] = 801902012
          },
          SpeakNpcId = 95102,
          Subtitle = "Ah — half an hour late, huh? My bad. To make it up to you, I swear — even if today's drink tastes like bad fish in a dirty sock, I'll down it in one go!"
        },
        [80190202] = {
          ContentFR = "Haha, tu m’as grillé direct.",
          DialogueId = 80190202,
          FacialId = {
            [1] = "95102:Smile02"
          },
          GUID = "C8BF6D04",
          NextDialogue = 80190203,
          SpeakNpcId = 95102,
          Subtitle = "Haha — sharp one. Saw right through me."
        },
        [80190203] = {
          ContentFR = "Tu te rappelles le gros boulot dont je t’ai parlé l’autre jour ? On vient juste de finir avec Wells, ça a pris plus de temps que prévu.",
          DialogueId = 80190203,
          FacialId = {
            [1] = "95102:None"
          },
          GUID = "C8BF6D2E",
          NextDialogue = 80190204,
          SpeakNpcId = 95102,
          Subtitle = "Remember that big job I mentioned the other day? Just wrapped it up with Wells. Took a bit longer than we thought."
        },
        [80190204] = {
          ContentFR = "Le boulot en lui-même, c’était rien. Ce sont les gars impliqués qui ont causé les problèmes.",
          DialogueId = 80190204,
          GUID = "C8BF6D58",
          NextOptions = {
            [1] = 801902041
          },
          SpeakNpcId = 95102,
          Subtitle = "The job wasn't the problem — it was the people involved that made it a pain."
        },
        [80190205] = {
          ContentFR = "Non, pas eux. Tant que tu respectes les règles, que tu sais lire entre les lignes et que tu évites de marcher sur les pieds de l’Empire, tu peux contourner la Légion sans trop de soucis.",
          DialogueId = 80190205,
          GUID = "C8BF6D82",
          NextDialogue = 80190206,
          SpeakNpcId = 95102,
          Subtitle = "Nah. The Legion's manageable — long as you know the rules, read the room, and steer clear of stepping on the Empire's toes, you can find ways around most of their messes.",
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190206] = {
          ContentFR = "La Légion, c’est comme une épée : tranchante et mortelle, mais au moins tu sais quand elle va tomber.",
          DialogueId = 80190206,
          GUID = "C8BF6DAC",
          NextDialogue = 80190207,
          SpeakNpcId = 95102,
          Subtitle = "They're like a drawn blade — sharp and deadly, sure, but at least you see it coming."
        },
        [80190207] = {
          ContentFR = "Mais y a une autre bande, plus violente et complètement chaotique. Comme une bombe cachée, prête à exploser.",
          DialogueId = 80190207,
          GUID = "C8BF6DD6",
          NextDialogue = 80190208,
          SpeakNpcId = 95102,
          Subtitle = "It's the other lot you need to watch out for. The ones with no rules, just chaos. Like a live bomb buried just out of sight—",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190208] = {
          ContentFR = "Les Déchus. Ce groupe de fous furieux. S’impliquer avec eux, c’est signer pour un bordel sans fin.",
          DialogueId = 80190208,
          GUID = "C8BF6E00",
          NextDialogue = 80190209,
          SpeakNpcId = 95102,
          Subtitle = "The Forsakens. That mad bunch. Once they drag you in, everything gets ten times messier."
        },
        [80190209] = {
          ContentFR = "Par exemple, ce boulot de livraison, au départ banal. Wells a senti que le poids clochait, il a discrètement percé la caisse et devine quoi ? Des armes interdites pour les Déchus.",
          DialogueId = 80190209,
          GUID = "C8BF6E2A",
          NextDialogue = 80190210,
          SpeakNpcId = 95102,
          Subtitle = "Take this job, for example — just your standard delivery gig, right? But Wells thought something felt off with the weight, so he quietly chiselled a hole in the crate and had a peek. And what do you know? It was packed with contraband weapons, all marked for the Forsakens."
        },
        [80190210] = {
          ContentFR = "Si on avait passé ça par la grande porte, les gardes nous auraient éliminés directement.",
          DialogueId = 80190210,
          GUID = "C8BF6E54",
          NextDialogue = 80190211,
          SpeakNpcId = 95102,
          Subtitle = "If we'd hauled that through the city gates, the guards would've gunned us down before we got a word in."
        },
        [80190211] = {
          ContentFR = "Mais c’était sûrement leur plan. Peut-être qu’ils voulaient quelques morts parmi les Chasseurs de Phoxène, ou un bon bordel pour s’infiltrer à Givrelac.",
          DialogueId = 80190211,
          GUID = "C8BF6E7E",
          NextDialogue = 80190212,
          SpeakNpcId = 95102,
          Subtitle = "Which was probably the plan. Maybe they wanted a few Phoxhunters dead. Maybe a little public chaos to slip into Icelake."
        },
        [80190212] = {
          ContentFR = "Ou peut-être que c’était juste un spectacle pour montrer à leurs fans à quel point les Solariens sont cruels envers les Charons.",
          DialogueId = 80190212,
          GUID = "C8BF6EA8",
          NextDialogue = 80190213,
          SpeakNpcId = 95102,
          Subtitle = "Or maybe it was all for show — a nice live performance, so their followers could watch exactly how cruel Solas are to Charons.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190213] = {
          ContentFR = "Complètement incompréhensible, hein ? Normal que personne pige leurs méthodes ou leurs buts.",
          DialogueId = 80190213,
          FacialId = {
            [1] = "95102:Angry01"
          },
          GUID = "C8BF6ED2",
          NextDialogue = 80190214,
          SpeakNpcId = 95102,
          Subtitle = "Point is, there's no guessing with them. Their motives don't make sense to normal folk — and their methods are even worse.",
          TalkActionId = {
            [1] = "95102:Sit_Talk02_Start"
          }
        },
        [80190214] = {
          ContentFR = "Au final, on a dû faire passer ces armes par les égouts pour boucler la \"livraison\".",
          DialogueId = 80190214,
          GUID = "C8BF6EFC",
          NextDialogue = 80190215,
          SpeakNpcId = 95102,
          Subtitle = "In the end, we had to smuggle the weapons in through the sewers just to finish the so-called \"delivery.\""
        },
        [80190215] = {
          ContentFR = "Ça a l’air simple dit comme ça, mais Wells et moi, on n’a pas fermé l’œil depuis des jours.",
          DialogueId = 80190215,
          GUID = "C8BF6F26",
          NextOptions = {
            [1] = 801902151,
            [2] = 801902152
          },
          SpeakNpcId = 95102,
          Subtitle = "Sounds simple when I say it, right? But Wells and I haven't had a proper night's sleep in days."
        },
        [80190216] = {
          ContentFR = "C’est pas pareil. Même si Wells était occupé, j’ai quand même commis une erreur en arrivant en retard.",
          DialogueId = 80190216,
          GUID = "C8BF6F50",
          NextDialogue = 80190218,
          SpeakNpcId = 95102,
          Subtitle = "Still — wrong's wrong. Doesn't matter how busy I was, I showed up late.",
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190217] = {
          ContentFR = "Nan, {性别:un ami|une amie} pour boire un coup, ça se refuse pas. Même six pieds sous terre, je me lèverais pour une gorgée.",
          DialogueId = 80190217,
          GUID = "C8BF6F7A",
          NextDialogue = 80190218,
          SpeakNpcId = 95102,
          Subtitle = "Nah. I'd never say no to a drinking buddy. Even if I were six feet under, I'd still claw my way up for a sip.",
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190218] = {
          ContentFR = "{空格}",
          DialogueId = 80190218,
          Duration = 3,
          GUID = "C8BF6FA4",
          NextDialogue = 80190219,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190219] = {
          ContentFR = "Mais bon, faut que je dorme. Avant de partir, un conseil : pour ta sécurité et ceux qui tiennent à toi... fuis les Déchus.",
          DialogueId = 80190219,
          GUID = "C8BF6FCE",
          NextOptions = {
            [1] = 801902191
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "But yeah, I do need sleep. Before I go — one last bit of advice. For your own safety, and for the sake of those who care about you... steer clear of the Forsakens.",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190220] = {
          ContentFR = "... Comme tout le monde. Voir le danger, c’est savoir rester à distance, point barre.",
          DialogueId = 80190220,
          FacialId = {
            [1] = "95102:Sad01"
          },
          GUID = "C8BF6FF8",
          NextDialogue = 80190221,
          SpeakNpcId = 95102,
          Subtitle = "...Just survival instinct. Like most folk — I see danger, I walk the other way."
        },
        [80190221] = {
          ContentFR = "Des années à survivre coincé entre des machines de guerre qui s’entretuent m’ont appris une chose : fuir les Déchus à tout prix.",
          DialogueId = 80190221,
          GUID = "C8BF7022",
          NextDialogue = 80190222,
          SpeakNpcId = 95102,
          Subtitle = "I've spent years scraping by between the grinding gears of clashing war machines. And if there's one thing I've learned, it's this: stay the hell away from the Forsakens."
        },
        [80190222] = {
          ContentFR = "C’est pas des conneries de beuverie, c’est une question de vie ou de mort.",
          DialogueId = 80190222,
          GUID = "C8BF704C",
          SpeakNpcId = 95102,
          Subtitle = "This isn't some drunken ramble. This is life-or-death advice."
        },
        [80190301] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentFR = "L’Étranger arrive comme prévu, mais après une seule gorgée, il reste silencieux.",
          DialogueId = 80190301,
          Duration = 3,
          FacialId = {
            [1] = "95102:Unhappy02"
          },
          GUID = "C8BF7D42",
          NextDialogue = 80190302,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "Outsider shows up right on time. But after just one sip, he goes completely quiet.",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190302] = {
          ContentFR = "...",
          DialogueId = 80190302,
          GUID = "C8BF7D6C",
          NextDialogue = 80190303,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "...",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190303] = {
          ContentFR = "...",
          DialogueId = 80190303,
          GUID = "C8BF7D96",
          NextOptions = {
            [1] = 801903031,
            [2] = 801903032
          },
          SpeakNpcId = 95102,
          Subtitle = "..."
        },
        [80190304] = {
          ContentFR = "...",
          DialogueId = 80190304,
          GUID = "C8BF7DC0",
          NextDialogue = 80190305,
          SpeakNpcId = 95102,
          Subtitle = "..."
        },
        [80190305] = {
          ContentFR = "... Ah... ouais, ça va. La boisson est bonne. Comme d’habitude, pas décevante.",
          DialogueId = 80190305,
          GUID = "C8BF7DEA",
          NextDialogue = 80190306,
          SpeakNpcId = 95102,
          Subtitle = "...Ah... yeah. I'm fine. Good drink. Solid as ever."
        },
        [80190306] = {
          ContentFR = "...",
          DialogueId = 80190306,
          GUID = "C8BF7E14",
          NextOptions = {
            [1] = 801903061,
            [2] = 801903062
          },
          SpeakNpcId = 95102,
          Subtitle = "..."
        },
        [80190307] = {
          ContentFR = "Quoi ? Faut pas déconner. Pleurer devant des gens ? T’as cru que j’étais du genre à m’apitoyer ? Pas du tout, mon {性别:ami|amie}.",
          DialogueId = 80190307,
          FacialId = {
            [1] = "95102:Shock01"
          },
          GUID = "C8BF7E3E",
          NextDialogue = 80190308,
          SpeakNpcId = 95102,
          Subtitle = "Hah? Don't be ridiculous. Like I'd cry in front of people. Do I look like the soft-hearted type to you, buddy?",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190308] = {
          ContentFR = "Mais... ces derniers temps, je repense souvent à mon passé... Peut-être que c’est l’âge qui fait ça.",
          DialogueId = 80190308,
          FacialId = {
            [1] = "95102:Sad01"
          },
          GUID = "C8BF7E68",
          NextDialogue = 80190309,
          SpeakNpcId = 95102,
          Subtitle = "That said... lately, I've been thinking about the past more than I used to. Maybe I'm just getting old."
        },
        [80190309] = {
          ContentFR = "Arrête de me regarder comme ça, sérieux. J’ai pas l’intention de tout déballer. Tu crois vraiment qu’avec quelques verres, je vais te raconter toute ma vie ?",
          DialogueId = 80190309,
          GUID = "C8BF7E92",
          NextDialogue = 80190310,
          SpeakNpcId = 95102,
          Subtitle = "Don't give me that look. I'm not about to open up and bare my soul. You didn't seriously think a few drinks would buy my whole life story, did you?"
        },
        [80190310] = {
          ContentFR = "Chacun a ses secrets qu’il emporte dans la tombe. Pas forcément enfouis dans le cercueil, mais ce sont les compagnons les plus fidèles qu’on garde là-bas.",
          DialogueId = 80190310,
          GUID = "C8BF7EBC",
          NextDialogue = 80190311,
          SpeakNpcId = 95102,
          Subtitle = "Everyone's got things they'll take with them to the grave. They might not be buried in the coffin, but make no mistake — they're the most loyal companions we carry down there."
        },
        [80190311] = {
          ContentFR = "Ces secrets peuvent être futiles, comme aimer l’odeur du Phoxichor, ou se casser une dent sur un pain d’épice trop dur. Ou bien des choses plus lourdes, un passé qu’on ne partage pas.",
          DialogueId = 80190311,
          GUID = "C8BF7EE6",
          NextDialogue = 80190312,
          SpeakNpcId = 95102,
          Subtitle = "Could be something silly — like being weirdly fond of the smell of Phoxichor, or cracking a tooth on your favourite rock-hard gingersnap. Could be... a past you never talk about."
        },
        [80190312] = {
          ContentFR = "On ne voit rien de tout ça à l’extérieur, ce sont des secrets, pour une raison. Mais c’est ça qui guide la plupart des décisions d’une personne. Pas toujours la raison principale, peut-être, mais presque. Tu vois ce que je veux dire.",
          DialogueId = 80190312,
          GUID = "C8BF7F10",
          NextDialogue = 80190313,
          SpeakNpcId = 95102,
          Subtitle = "You won't see that stuff on the surface — they're called secrets for a reason. But truth is, it's that very stuff that drives a person. Not the whole reason, maybe — but close enough. You get the point."
        },
        [80190313] = {
          ContentFR = "Quand quelqu’un balance ses secrets trop facilement, c’est souvent pour deux raisons : soit ce passé ne compte plus pour lui...",
          DialogueId = 80190313,
          GUID = "C8BF7F3A",
          NextDialogue = 80190314,
          SpeakNpcId = 95102,
          Subtitle = "When someone shares their secrets too easily, it's usually for one of a few reasons. Either those memories don't mean much to them anymore..."
        },
        [80190314] = {
          ContentFR = "Soit il invente une histoire pour chercher un peu de compassion.",
          DialogueId = 80190314,
          GUID = "C8BF7F64",
          NextDialogue = 80190315,
          SpeakNpcId = 95102,
          Subtitle = "Or they're just spinning a tale to fish for sympathy."
        },
        [80190315] = {
          ContentFR = "Quoi qu’il en soit, révéler ses secrets à n’importe qui, c’est risqué. Tu donnes des billes aux autres, et en plus ça peut passer pour de la légèreté. Ou pire, du désespoir.",
          DialogueId = 80190315,
          GUID = "C8BF7F8E",
          NextOptions = {
            [1] = 801903151,
            [2] = 801903152
          },
          SpeakNpcId = 95102,
          Subtitle = "Either way — spilling your guts to just anyone? That's reckless. You're handing over leverage. People might just see it as carelessness. Or worse... desperation.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190316] = {
          ContentFR = "Oui, oui, tu as raison la plupart du temps. Je dis ça, mais moi aussi, parfois, j’ai lâché quelques secrets à la taverne, comme quand j’ai chopé un boulot juteux.",
          DialogueId = 80190316,
          GUID = "C8BF7FB8",
          NextDialogue = 80190317,
          SpeakNpcId = 95102,
          Subtitle = "Yeah, yeah, I get it. And you're not wrong. I say all this, but even I've let slip a secret or two at the tavern — like when I landed a juicy side gig or two.",
          TalkActionId = {
            [1] = "95102:Sit_AgreeHead"
          }
        },
        [80190317] = {
          ContentFR = "Mais bon... faut avouer que tous les secrets ne pèsent pas pareil.",
          DialogueId = 80190317,
          GUID = "C8BF7FE2",
          NextOptions = {
            [1] = 801903171
          },
          SpeakNpcId = 95102,
          Subtitle = "But... let's just say, not all secrets weigh the same.",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190318] = {
          ContentFR = "Qu’est-ce que tu racontes ? Dis pas n’importe quoi.",
          DialogueId = 80190318,
          GUID = "C8BF800C",
          NextDialogue = 80190319,
          SpeakNpcId = 95102,
          Subtitle = "Hey! How could you say that?",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190319] = {
          ContentFR = "C’est justement parce que tu es mon {性别:ami|amie} que je ne peux pas te confier mon passé. Je ne cherche pas à jouer les mystérieux, d'accord ? Considère ça comme un conseil de quelqu'un qui tient à toi :",
          DialogueId = 80190319,
          GUID = "C8BF8036",
          NextDialogue = 80190320,
          SpeakNpcId = 95102,
          Subtitle = "It's exactly because you're my friend that I can't tell you. I'm not trying to be cryptic or dramatic, alright? Think of it as a word of advice from someone who cares about you:"
        },
        [80190320] = {
          ContentFR = "Creuser dans le passé, c’est risquer de tomber sur autre chose que des trésors. Parfois, c’est la mort qui refait surface. Alors, pour t’épargner ça, je préfère porter ce fardeau seul.",
          DialogueId = 80190320,
          GUID = "C8BF8060",
          NextDialogue = 80190321,
          SpeakNpcId = 95102,
          Subtitle = "Digging up old graves doesn't always lead to treasure. Sometimes, all you find is rot. And I'd rather you never have to deal with the stench. Let me carry it."
        },
        [80190321] = {
          ContentFR = "T’inquiète pas, j’ai réussi à laisser le passé loin derrière moi ces années-ci. Et si jamais il revient frapper à la porte, je serai là pour répondre. Pas toi. Toi, profite du moment présent, je m’occupe du reste.",
          DialogueId = 80190321,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF808A",
          NextDialogue = 80190322,
          SpeakNpcId = 95102,
          Subtitle = "It's fine. I've done a pretty good job of leaving the past behind. And if it ever comes knocking again — hey, I'll be the one answering the door. Not you. You just focus on the moment and let me handle the rest."
        },
        [80190322] = {
          ContentFR = "Allez, encore un verre ! Le précédent est passé trop vite, je n’ai pas senti le goût.",
          DialogueId = 80190322,
          GUID = "C8BF80B4",
          NextOptions = {
            [1] = 801903221,
            [2] = 801903222
          },
          SpeakNpcId = 95102,
          Subtitle = "Alright then — another round, please! That last one went down so smooth, I barely tasted it."
        },
        [80190323] = {
          ContentFR = "Hahaha ! Un bon verre, {性别:un ami|une amie} qui sait y faire, et un peu de taquinerie, voilà une belle journée.",
          DialogueId = 80190323,
          FacialId = {
            [1] = "95102:Smile02"
          },
          GUID = "C8BF80DE",
          NextOptions = {
            [1] = 801903231
          },
          SpeakNpcId = 95102,
          Subtitle = "Hahaha! A stiff drink, a sharp-tongued friend, and a bit of banter — now this is the life."
        },
        [80190324] = {
          ContentFR = "T’es en train de te moquer de moi, là ?",
          DialogueId = 80190324,
          GUID = "C8BF8108",
          SpeakNpcId = 95102,
          Subtitle = "What was that!?",
          TalkActionId = {
            [1] = "95102:Sit_Think_Start"
          }
        },
        [80190401] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentFR = "{空格}",
          DialogueId = 80190401,
          GUID = "C8BF8DAA",
          NextDialogue = 80190402,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190402] = {
          ContentFR = "Hmm ? Tu viens de m’appeler ?",
          DialogueId = 80190402,
          FacialId = {
            [1] = "95102:Doubt01"
          },
          GUID = "C8BF8DD4",
          NextOptions = {
            [1] = 801904021
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "Hm? What did you just call me?"
        },
        [80190403] = {
          ContentFR = "Ah... c’était sûrement mon imagination. Je suis un peu parano ces derniers temps, désolé.",
          DialogueId = 80190403,
          FacialId = {
            [1] = "95102:Unhappy01"
          },
          GUID = "C8BF8DFE",
          NextDialogue = 80190404,
          SpeakNpcId = 95102,
          Subtitle = "Ah... must've been my imagination again. Been a bit on edge lately — sorry about that.",
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190404] = {
          ContentFR = "En vérité, ça fait des années que j’entends des voix m’appeler par mon vrai nom. Certaines sont douces, d’autres fermes.",
          DialogueId = 80190404,
          GUID = "C8BF8E28",
          NextDialogue = 80190405,
          SpeakNpcId = 95102,
          Subtitle = "Truth is, I've been hearing voices calling my real name in my head for years. Some soft, some firm.",
          TalkActionId = {
            [1] = "95102:Sit_Talk02_Start"
          }
        },
        [80190405] = {
          ContentFR = "C’est comme un acouphène, on finit par s’y habituer. Parfois, je réponds juste pour passer le temps, je sais bien que ce n’est pas réel.",
          DialogueId = 80190405,
          GUID = "C8BF8E52",
          NextDialogue = 80190406,
          SpeakNpcId = 95102,
          Subtitle = "It's like tinnitus — you get used to it. Sometimes I even answer back, just for kicks. They're not real, after all."
        },
        [80190406] = {
          ContentFR = "Mais hier, il s’est passé quelque chose d’étrange. J’ai répondu machinalement par un « hmm ? », et cette fois, quelqu’un m’a vraiment répondu.",
          DialogueId = 80190406,
          GUID = "C8BF8E7C",
          NextDialogue = 80190407,
          SpeakNpcId = 95102,
          Subtitle = "But yesterday... something strange happened. I replied on reflex — just a little \"hm?\" — and this time, someone actually answered."
        },
        [80190407] = {
          ContentFR = "Une poubelle a basculé au coin de la rue, et un type sombre en est sorti pour me saluer.",
          DialogueId = 80190407,
          GUID = "C8BF8EA6",
          NextDialogue = 80190408,
          SpeakNpcId = 95102,
          Subtitle = "A rubbish bin tipped over near the street corner, and some shady character popped out from behind it and said hello."
        },
        [80190408] = {
          ContentFR = "J’aurais tellement voulu que ce soit une blague d’un gamin, mais il a prononcé un nom que seuls les Déchus connaissent, pas celui que tu connais.",
          DialogueId = 80190408,
          GUID = "C8BF8ED0",
          NextDialogue = 80190409,
          SpeakNpcId = 95102,
          Subtitle = "Oof, I wanted to think it was just some brat messing around. But no — he called me by a name only the Forsakens would know. Not the name you know. Not Outsider."
        },
        [80190409] = {
          ContentFR = "J’ai fait comme si je n’avais rien entendu, en jouant le passant, mais je ne sais pas s’il m’a cru... J’aurais dû laisser Wells gérer ce boulot pour les Déchus.",
          DialogueId = 80190409,
          GUID = "C8BF8EFA",
          NextOptions = {
            [1] = 801904091
          },
          SpeakNpcId = 95102,
          Subtitle = "I played dumb. Told him he had the wrong guy. No idea if he bought it... Ugh, should've let Wells handle that Forsakens' gig on his own.",
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190410] = {
          ContentFR = "...",
          DialogueId = 80190410,
          GUID = "C8BF8F24",
          NextDialogue = 80190411,
          SpeakNpcId = 95102,
          Subtitle = "..."
        },
        [80190411] = {
          ContentFR = "{空格}",
          DialogueId = 80190411,
          GUID = "C8BF8F4E",
          NextDialogue = 80190412,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190412] = {
          ContentFR = "Bon, je suppose que je te dois la vérité. Sinon, si tu te fais poignarder un jour par un fou des Déchus, tu sauras pas à qui t’en prendre.",
          DialogueId = 80190412,
          GUID = "C8BF8F78",
          NextDialogue = 80190413,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "Yeah. I suppose I owe you the truth. You deserve to know — wouldn't want you catching a blade in some back alley one day, just because you didn't know what I'd gotten tangled up in.",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190413] = {
          ContentFR = "J’ai un passé... compliqué avec eux. Il y a du ressentiment. Ce dernier boulot a peut-être laissé des traces.",
          DialogueId = 80190413,
          GUID = "C8BF8FA2",
          NextDialogue = 80190414,
          SpeakNpcId = 95102,
          Subtitle = "I've got... history with the Forsakens. Bad blood. They've been hunting me for a while now. That last gig? Might've given 'em a whiff of my trail."
        },
        [80190414] = {
          ContentFR = "Du coup, je dois effacer mes traces de Givrelac, pour qu’ils ne me retrouvent pas.",
          DialogueId = 80190414,
          GUID = "C8BF8FCC",
          NextDialogue = 80190415,
          SpeakNpcId = 95102,
          Subtitle = "So now I've gotta cover my tracks in Icelake. Make sure nothing leads back to me."
        },
        [80190415] = {
          ContentFR = "Si jamais ils me mettent la main dessus, ce seront mes amis qui trinqueront, un par un, jusqu’à ce que quelqu’un craque et parle. Toi aussi, tu ne t’en sortiras pas.",
          DialogueId = 80190415,
          GUID = "C8BF8FF6",
          NextDialogue = 80190416,
          SpeakNpcId = 95102,
          Subtitle = "Because if it does... my friends'll be the first to suffer. They'll go after them, one by one — until someone cracks and gives me up. And you? You wouldn't walk away, either."
        },
        [80190416] = {
          ContentFR = "Mais tu peux toujours dire que je n’étais qu’un simple ami de beuverie. Que tu ne me connais pas vraiment.",
          DialogueId = 80190416,
          GUID = "C8BF9020",
          NextOptions = {
            [1] = 801904161,
            [2] = 801904162
          },
          SpeakNpcId = 95102,
          Subtitle = "But hey — if that day comes, just say I was some drinking buddy. That you don't know me well. Don't know a thing about any of this.",
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190417] = {
          ContentFR = "Hé, tu vas pas me couper la parole. Ce n’est que si ce jour arrive...",
          DialogueId = 80190417,
          GUID = "C8BF904A",
          NextDialogue = 80190418,
          SpeakNpcId = 95102,
          Subtitle = "Uh-uh. Hear me out. I'm just saying if. But if the worst does come...",
          TalkActionId = {
            [1] = "95102:Sit_Think_Start"
          }
        },
        [80190418] = {
          ContentFR = "À ce moment-là, je devrai partir. Quitter la ville, vous laisser derrière. Et Fina... prends soin d’elle pour moi, d’accord ?",
          DialogueId = 80190418,
          GUID = "C8BF9074",
          NextDialogue = 80190419,
          SpeakNpcId = 95102,
          Subtitle = "I'll have to leave. Leave the city. Leave you lot behind. And Fina... take care of her for me, yeah?"
        },
        [80190419] = {
          ContentFR = "Si elle demande, dis-lui que j’ai pris un gros contrat. J’ai écrit quelques lettres, donne-lui une par mois, ça devrait l’apaiser un moment.",
          DialogueId = 80190419,
          GUID = "C8BF909E",
          NextDialogue = 80190420,
          SpeakNpcId = 95102,
          Subtitle = "If she asks, tell her I landed a big job. One that needs me gone a while. Here — these are letters I wrote. Give her one each month. That should buy you some time."
        },
        [80190420] = {
          ContentFR = "Ah, et il y a un peu d’argent caché derrière la troisième brique à droite de la cheminée, prends-le si tu en as besoin. Voyons voir...",
          DialogueId = 80190420,
          GUID = "C8BF90C8",
          NextDialogue = 80190421,
          SpeakNpcId = 95102,
          Subtitle = "Oh, right — there's some cash behind the third brick to the right of my fireplace. Take it if you need it. What else, what else...",
          TalkActionId = {
            [1] = "95102:Sit_Think_End"
          }
        },
        [80190421] = {
          ContentFR = "L’Étranger, calme-toi.",
          DialogueId = 80190421,
          GUID = "C8BF90F2",
          NextDialogue = 80190422,
          SpeakNpcId = 790008,
          Subtitle = "Outsider, breathe. Calm down."
        },
        [80190422] = {
          ContentFR = "Je suis calme. Récite-moi tout ce que je viens de te dire. Si je ne suis plus là, il faudra que quelqu’un tienne la baraque.",
          DialogueId = 80190422,
          GUID = "C8BF911C",
          NextDialogue = 80190423,
          SpeakNpcId = 95102,
          Subtitle = "I am calm. Now repeat everything I just told you. If I'm not around, someone's gotta hold the line."
        },
        [80190423] = {
          ContentFR = "Tu n’es pas comme d’habitude, c’est à cause des Déchus ?",
          DialogueId = 80190423,
          GUID = "C8BF9146",
          NextDialogue = 80190424,
          SpeakNpcId = 790008,
          Subtitle = "This really isn't like you. Is it because of the Forsakens?"
        },
        [80190424] = {
          ContentFR = "Comme d'habitude ? Mon moi habituel ne tiendrait pas cinq minutes face à ces fous sans foi ni loi.",
          DialogueId = 80190424,
          FacialId = {
            [1] = "95102:Unacceptable01"
          },
          GUID = "C8BF9170",
          NextDialogue = 80190425,
          SpeakNpcId = 95102,
          Subtitle = "\"Like me,\" huh? Pretty sure the regular me wouldn't last five minutes against those lunatics with no moral scruples—",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190425] = {
          ContentFR = "Pour une info, ils t’arracheraient les ongles un par un.",
          DialogueId = 80190425,
          GUID = "C8BF919A",
          NextDialogue = 80190426,
          SpeakNpcId = 95102,
          Subtitle = "For a scrap of intel, they'd pull your fingernails out. One by one."
        },
        [80190426] = {
          ContentFR = "Et ça ne serait que le début de leurs tortures... Je refuse que ça arrive à quelqu’un que j’apprécie.",
          DialogueId = 80190426,
          GUID = "C8BF91C4",
          NextDialogue = 80190427,
          SpeakNpcId = 95102,
          Subtitle = "And that's just their idea of a warm-up. I'm not letting that happen... Not to anyone I care about."
        },
        [80190427] = {
          ContentFR = "Mais ça n’est pas encore arrivé, et tu as dit que ta piste n’avait que <H>peut-être</> été compromise, non ?",
          DialogueId = 80190427,
          GUID = "C8BF91EE",
          NextDialogue = 80190428,
          SpeakNpcId = 790008,
          Subtitle = "But none of that's happened yet. You said your location might've been compromised — not that it has."
        },
        [80190428] = {
          ContentFR = "Même si ce n’est que peut-être... il faut se préparer au pire.",
          DialogueId = 80190428,
          GUID = "C8BF9218",
          NextDialogue = 80190429,
          SpeakNpcId = 95102,
          Subtitle = "Still. I've gotta start planning for the worst. Can't take any chances."
        },
        [80190429] = {
          ContentFR = "Ça n’est pas la première fois, c’est ça ? Cette fois est-elle vraiment plus dangereuse ?",
          DialogueId = 80190429,
          GUID = "C8BF9242",
          NextDialogue = 80190430,
          SpeakNpcId = 790008,
          Subtitle = "This isn't the first time, is it? Is this one really more dangerous than the others?"
        },
        [80190430] = {
          ContentFR = "Si je devais classer la pire, celle-ci ne serait même pas dans le top cinq.",
          DialogueId = 80190430,
          FacialId = {
            [1] = "95102:Think01"
          },
          GUID = "C8BF926C",
          NextDialogue = 80190431,
          SpeakNpcId = 95102,
          Subtitle = "Hmm... Come to think of it, this one might not even crack the top five.",
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190431] = {
          ContentFR = "Alors, comment t’as fait pour t’en sortir avant ?",
          DialogueId = 80190431,
          GUID = "C8BF9296",
          NextDialogue = 80190432,
          SpeakNpcId = 790008,
          Subtitle = "Right? And how did you get through those?"
        },
        [80190432] = {
          ContentFR = "Certaines étaient de fausses alertes. D’autres, je les ai gérées avec bluff, ruse, en attirant la Légion dans le piège, ou en faisant quelques apparitions dans d’autres villes.",
          DialogueId = 80190432,
          GUID = "C8BF92C0",
          NextOptions = {
            [1] = 801904321,
            [2] = 801904322
          },
          SpeakNpcId = 95102,
          Subtitle = "Well... some turned out to be false alarms. Others... bluffing, baiting, dragging the Legion into it, staging a few \"cameos\" in far-off cities — you know, the usual."
        },
        [80190433] = {
          ContentFR = "{空格}",
          DialogueId = 80190433,
          GUID = "C8BF92EA",
          NextDialogue = 80190434,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190434] = {
          ContentFR = "Ouais... tu as raison. J’ai dû un peu perdre la tête. J’ai traversé pire, pourtant voilà que je te confie déjà mes dernières volontés.",
          DialogueId = 80190434,
          FacialId = {
            [1] = "95102:None"
          },
          GUID = "C8BF9314",
          NextDialogue = 80190435,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "Yeah... you're right. What was I thinking? I've lived through worse. One little scare, and here I am — handing you my last words like it's the end of the world.",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190435] = {
          ContentFR = "Peut-être que je passe trop de temps avec toi. Ou que je commence à dépendre de toi, {性别:mon|ma} capitaine. Ou alors... je deviens faible.",
          DialogueId = 80190435,
          GUID = "C8BF933E",
          NextDialogue = 80190436,
          SpeakNpcId = 95102,
          Subtitle = "Maybe I've been spending too much time with you. Or maybe now that you're my Captain, some part of me thought I could lean a little. Or maybe... I've just gone soft."
        },
        [80190436] = {
          ContentFR = "Non, non, ce n’est pas possible ! C’est sûrement cette foutue boisson. Je n’ai pas dit de conneries, hein ? Sois honnête, j’ai rien dit, quand même.",
          DialogueId = 80190436,
          GUID = "C8BF9368",
          NextOptions = {
            [1] = 801904361,
            [2] = 801904362
          },
          SpeakNpcId = 95102,
          Subtitle = "No, no, no — can't be. Must be this drink. You spiked it, didn't you? I didn't say anything soppy just now, right? Be honest — I didn't, yeah?",
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190437] = {
          ContentFR = "Bref, au lieu de t’inquiéter pour ce qui pourrait arriver, attends que ça arrive, on trouvera peut-être une meilleure solution.",
          DialogueId = 80190437,
          GUID = "C8BF9392",
          NextDialogue = 80190438,
          SpeakNpcId = 790008,
          Subtitle = "Anyway — rather than worry about what might happen, maybe we stay cool until it actually does. Who knows? By then, we might've already found a way through."
        },
        [80190438] = {
          ContentFR = "Hmm, pas faux. À la tienne, à moi dans le futur. Qu’il soit plus sage que celui d’aujourd’hui. Et à toi, mon {性别:ami|amie}.",
          DialogueId = 80190438,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF93BC",
          NextDialogue = 80190439,
          SpeakNpcId = 95102,
          Subtitle = "Hmm... good point. Cheers to that — here's to future me. May he be wiser and more put-together than current me. And to you — for being a good friend."
        },
        [80190439] = {
          ContentFR = "{空格}",
          DialogueId = 80190439,
          GUID = "C8BF93E6",
          NextDialogue = 80190440,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          Subtitle = "{空格}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190440] = {
          ContentFR = "Par contre, je dois encore m’excuser. J’ai fait la paix avec l’avenir, mais mon passé... je ne peux pas encore tout te raconter.",
          DialogueId = 80190440,
          GUID = "C8BF9410",
          NextDialogue = 80190441,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          Subtitle = "Still... I owe you an apology. I've made peace with whatever's ahead — but my past? I still can't tell you everything. Not yet.",
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190441] = {
          ContentFR = "Mais je te promets qu’un jour, je te montrerai le chemin qui m’a mené à Givrelac. Ce sera dur, et ça pourrait te faire douter de moi.",
          DialogueId = 80190441,
          GUID = "C8BF943A",
          NextDialogue = 80190442,
          SpeakNpcId = 95102,
          Subtitle = "But I promise — someday, I'll show you the path that led me here. It won't be easy. And you might not like what you find."
        },
        [80190442] = {
          ContentFR = "Mais je crois qu’à ce moment-là, tu n’hésiteras pas à me servir un verre comme ce soir, mon {性别:ami|amie}.",
          DialogueId = 80190442,
          GUID = "C8BF9464",
          SpeakNpcId = 95102,
          Subtitle = "But when that day comes... I believe you won't mind making me a drink like this one. Just like tonight, my friend."
        },
        [80200001] = {
          Camera = "-1480.738281,3129.994141,100.084961,0.000177,18.397858,-82.573738,35.0,3295.439453,false,Manual,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Au printemps, cueillir la vesce ; en été, voir croître l’amarante ; en automne, récolter le bigaradier ; en hiver, chercher le ganoderma...",
          DialogueId = 80200001,
          Duration = 1,
          FinalCamera = "-1480.738281,3129.994141,100.084961,0.000191,0.799146,-69.377235,35.0,3295.439453,false,Manual,2.8",
          GUID = "C8C5B4AA",
          NextDialogue = 80200002,
          SpeakNpcId = 790053,
          Subtitle = "Spring vetch, summer amaranth; autumn citrus, winter ganoderma...",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B4AA"
        }
      }
    end
  },
  {
    MinKey = 80200002,
    MaxKey = 80210104,
    Loader = function()
      return {
        [80200002] = {
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Là où le soleil n’atteint pas, croît le Bois Sans-Cendre. Au cœur de la glace fleurit la Rosée pourpre. Sous les herbes épaisses se cache le Biru, et parmi les parfums insolites repose le Lys céleste...",
          DialogueId = 80200002,
          GUID = "C8C5B4D4",
          NextOptions = {
            [1] = 802000021,
            [2] = 802000022,
            [3] = 802000023
          },
          Scripts = [[
PARA{
MoveTo{_delay{10},ActorId{790008},TargetPoint{"BP_200101a_nvzhu01"},MoveSpeed{55},Visibility{"Show"}},
SEQ{
CameraMoveTo{_delay{4},TargetPosition{"-6.146816,120.018967,141.563477,0.000095,5.200048,-128.788574,45.000023,110.798798,false,Manual,7.870067"},duration{0}},
CameraMoveTo{TargetPosition{"-9.100973,100.566628,143.263672,0.000098,5.199925,-138.591827,45.000023,93.368507,false,Manual,7.870067"},duration{35}}
},
SEQ{
CameraMoveTo{_delay{12},TargetPosition{"244.989624,223.965759,137.616211,0.000058,-2.599365,-155.996475,30.000008,381.480011,false,Manual,3.425282"},duration{0}},
CameraMoveTo{TargetPosition{"236.706024,240.90596,137.616211,0.000058,-2.599365,-152.396286,30.000008,381.480011,false,Manual,3.425282"},duration{10}}
},
LookAt{_delay{9.5},LookAtDescription{"790053:n(790008)"}},
TurnTo{_delay{10.6},TurnToDescription{"790053:n(790008)"}},
PlayAnimation{_delay{11.5},ActorId{790053},AnimationId{"Baiheng_Story_Special03_End"},Duration{1}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "Where no sun shines, Ashless Wood thrives; in hearts of frost, Dewiolet blooms. Beneath thick grasses, Verdawort coils; from hidden scents, Vesperleaf stirs.",
          ToFinalCameraBlendTime = 35,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B4D4"
        },
        [80200004] = {
          ContentFR = "En effet. Toutes celles que je viens de citer peuvent entrer dans la composition de remèdes, et certaines sont même comestibles.",
          DialogueId = 80200004,
          GUID = "C8C5B528",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          Subtitle = "Indeed. Each one bears medicinal properties — a few are even edible.",
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B528"
        },
        [80200006] = {
          ContentFR = "Hé hé... je ne te savais pas si {性别:érudit|érudite}. C’est bien extrait du <I>Guide des plantes médicinales</>.",
          DialogueId = 80200006,
          GUID = "C8C5B57C",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          Subtitle = "Hehe... I didn't know you were so well-read. You're right — it's from Essentials of Medicinal Herbs.",
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B57C"
        },
        [80200008] = {
          ContentFR = "Pas du tout. Inutile d’être si précautionneux entre nous. Ta visite m’est toujours agréable.",
          DialogueId = 80200008,
          GUID = "C8C5B5D0",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          Subtitle = "Not at all. There's no need for such formality between us. You're always welcome here.",
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B5D0"
        },
        [80200009] = {
          Camera = "330.082214,-1013.532104,415.926758,0.000049,-15.199328,108.205627,45.0,1011.382263,false,DoNotOverride,1.2",
          ContentFR = "À vrai dire, cela fait déjà un moment que je lis. Une pause serait bienvenue.",
          DialogueId = 80200009,
          FinalCamera = "357.199249,-1095.939087,439.499023,0.000049,-15.199328,108.205627,45.0,1011.382263,false,DoNotOverride,1.2",
          GUID = "C8C5B5FA",
          NextDialogue = 80200010,
          Scripts = [[
PARA{
LookAt{_delay{3.1},LookAtDescription{"790053:n(790053)"}},
LookAt{_delay{3.5},LookAtDescription{"790008:n(790053)"}},
TurnTo{_delay{3},TurnToDescription{"790053:p(90)"}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "I've been reading for quite some time now... A short respite may be in order.",
          TalkActionId = {
            [1] = "790053:Talk02_End",
            [2] = [[

790008:Talk03_Start]]
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B5FA"
        },
        [80200010] = {
          Camera = "58.601952,177.411819,149.177734,0.000077,-2.599174,-139.997375,35.000008,198.557495,false,Manual,10.616697",
          ContentFR = "Mais le Pavillon de l’Éphémère est désert depuis longtemps... je n’ai même pas de bon thé à t’offrir. J’en suis navrée.",
          DialogueId = 80200010,
          FacialId = {
            [1] = "790053:Sad03"
          },
          FinalCamera = "65.497627,183.20816,149.582031,0.000077,-2.599174,-139.997391,35.000008,198.557495,false,Manual,10.616697",
          GUID = "C8C5B624",
          NextOptions = {
            [1] = 802000101,
            [2] = 802000102,
            [3] = 802000103
          },
          Scripts = "LookAt{_delay{5.1},LookAtDescription{\"790053:n(790008)\"}}",
          SpeakNpcId = 790053,
          Subtitle = "Though this Hall of Ephemerality lies long deserted, I've no fine tea to serve... I fear I've made a poor host.",
          TalkActionId = {
            [1] = "790008:Talk03_End",
            [2] = "790053:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B624"
        },
        [80200012] = {
          ContentFR = "Au début, oui. Mais je suis attachée à cet endroit. À force, même l’inconfort finit par devenir habitude.",
          DialogueId = 80200012,
          GUID = "C8C5B678",
          NextDialogue = 80200017,
          SpeakNpcId = 790053,
          Subtitle = "It was, at first. But my ties to this place run deep... and in time, I came to embrace the solitude.",
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B678"
        },
        [80200014] = {
          ContentFR = "Merci de ta compréhension. Voilà ce qu’on appelle, je crois, une amitié aussi limpide que l’eau.",
          DialogueId = 80200014,
          GUID = "C8C5B6CC",
          NextDialogue = 80200017,
          SpeakNpcId = 790053,
          Subtitle = "Thank you for your forbearance. I suppose this is what they call \"a friendship as calm as water\".",
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B6CC"
        },
        [80200016] = {
          ContentFR = "Tu as faim ? Mais il est encore un peu tôt pour manger convenablement. Attends encore un peu.",
          DialogueId = 80200016,
          GUID = "C8C5B720",
          NextDialogue = 80200017,
          SpeakNpcId = 790053,
          Subtitle = "Feeling hungry already? But it's still a touch early for a proper meal. Bear with it a while longer, if you can.",
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B720"
        },
        [80200017] = {
          Camera = "-634.981689,1124.922974,959.174805,0.000074,-35.198467,-55.38472,30.0,1833.385742,false,DoNotOverride,10.243358",
          ContentFR = "Puisque le hasard nous a réunis aujourd’hui, je vais être franche... J’aurais une faveur à te demander.",
          DialogueId = 80200017,
          Duration = 1,
          FinalCamera = "-886.519958,1045.29541,1024.44043,0.000078,-35.798367,-46.98473,30.0,1833.385742,false,DoNotOverride,10.243358",
          GUID = "C8C5B74A",
          NextDialogue = 80200018,
          Scripts = "PlayAnimation{_delay{3.5},ActorId{790053},AnimationId{\"Baiheng_Story_Special01_Start\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "Since fate has granted us this rare encounter, allow me to speak plainly. There is... something I wish to ask of you.",
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "790053:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B74A"
        },
        [80200018] = {
          Camera = "-368.470367,-21.31028,215.013672,0.000096,-14.799707,17.818779,30.0,498.626465,false,Manual,4.781349",
          ContentFR = "Je t’écoute.",
          DialogueId = 80200018,
          Duration = 1,
          FinalCamera = "-368.470367,-21.31028,204.082031,0.000096,-14.799714,17.818808,30.0,498.626465,false,Manual,4.781349",
          GUID = "C8C5B774",
          NextDialogue = 80200019,
          SpeakNpcId = 790008,
          Subtitle = "Go ahead. I'm listening.",
          TalkActionId = {
            [1] = "790008:Talk02_Start",
            [2] = "790053:Baiheng_Story_Special01_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B774"
        },
        [80200019] = {
          ContentFR = "La dernière fois, j’ai soigné une jeune femme blessée par un Bi’an obscur, grâce à une formule retrouvée dans les notes de ma sœur. Cela a éveillé mon intérêt pour la pharmacologie.",
          DialogueId = 80200019,
          GUID = "C8C5B79E",
          NextDialogue = 80200020,
          SpeakNpcId = 790053,
          Subtitle = "The other day, I treated the young lady wounded by that Sable Bi'an using a remedy I found in one of my sister's old notes. It stirred in me... an interest in pharmacology.",
          TalkActionId = {
            [1] = "790008:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B79E"
        },
        [80200020] = {
          Camera = "13.768398,198.582336,146.612305,0.000078,-0.599117,-112.591949,35.0,194.999741,false,Manual,7.870067",
          ContentFR = "Ma famille a toujours sauvé des vies grâce à l’Art de l’Éphémère. Mais la science médicinale moderne n’existe que depuis moins d’un siècle. Ma sœur y excellait... moi, je n’en maîtrise que les bases.",
          DialogueId = 80200020,
          FinalCamera = "13.768398,198.582336,142.704102,0.000078,-0.599117,-112.591949,35.0,194.999741,false,Manual,7.870067",
          GUID = "C8C5B7C8",
          NextDialogue = 80200021,
          Scripts = [[
PARA{
PlayAnimation{_delay{10},ActorId{790053},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{5.5},ActorId{790053},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "My clan has long practised the Art of Ephemerality. But pharmacology — as a formal discipline — has only emerged in the past century. My sister excelled in it. As for me... my grasp is but fragmentary.",
          TalkActionId = {
            [1] = "790008:Think_Start",
            [2] = "790053:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B7C8"
        },
        [80200021] = {
          Camera = "0.365,149.368027,144.621094,0.000082,-0.199114,-123.592377,35.0,139.78009,false,Manual,10.0",
          ContentFR = "Je n’ai jamais renoncé à la mission transmise par mes ancêtres. Et pourtant, mon réveil après ce long sommeil n’a été possible que grâce aux efforts acharnés de ma sœur et de ses disciples. Je ne peux pas trahir ce sacrifice.",
          DialogueId = 80200021,
          FinalCamera = "-2.978582,144.336792,144.600586,0.000082,-0.199114,-123.592377,35.0,139.78009,false,Manual,10.0",
          GUID = "C8C5B7F2",
          NextDialogue = 80200022,
          SpeakNpcId = 790053,
          Subtitle = "I've never wavered in my wish to carry forward our family's calling. Yet my return from a long slumber — that miracle was wrought by the lifelong efforts of my sister and her disciples. Such devotion... cannot go unanswered.",
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B7F2"
        },
        [80200022] = {
          Camera = "-56.301811,69.71508,137.660156,0.000099,-1.798833,52.211357,30.000002,113.82692,false,Manual,7.870067",
          ContentFR = "C’est pourquoi j’essaie d’étudier la médecine contemporaine. Mais ce que l’on apprend dans les livres reste toujours superficiel.",
          DialogueId = 80200022,
          FinalCamera = "-51.461147,75.961639,137.414062,0.000099,-1.798833,52.211399,30.000002,113.82692,false,Manual,7.870067",
          GUID = "C8C5B81C",
          NextDialogue = 80200023,
          SpeakNpcId = 790053,
          Subtitle = "That's why I've begun studying modern medicine. But books alone can only take one so far.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B81C"
        },
        [80200023] = {
          Camera = "-1016.887939,779.020264,118.349609,0.000108,1.800718,-34.790836,35.0,1192.438843,false,Manual,1.460963",
          ContentFR = "J’aimerais pratiquer réellement : observer, écouter, examiner, diagnostiquer... Comprendre ce qu’est la maladie dans un corps vivant.",
          DialogueId = 80200023,
          Duration = 2,
          FinalCamera = "-1097.473145,835.017334,72.382812,0.00011,1.800718,-34.790791,35.0,1303.897095,false,Manual,1.460963",
          GUID = "C8C5B846",
          NextDialogue = 80200024,
          SpeakNpcId = 790053,
          Subtitle = "What I truly long for is practice — to observe, to examine, to diagnose... To understand what illness means in the living body.",
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B846"
        },
        [80200024] = {
          ContentFR = "Mais cent années ont passé. Ici, je n’ai plus ni proches ni amis.",
          DialogueId = 80200024,
          GUID = "C8C5B870",
          NextDialogue = 80200025,
          SpeakNpcId = 790053,
          Subtitle = "But a century has passed in the blink of an eye. I have no kin left... no companions in this era.",
          TalkActionId = {
            [1] = "790053:Baiheng_Story_Special03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B870"
        },
        [80200025] = {
          Camera = "37.140533,321.639557,117.170898,0.00008,4.200812,-104.992432,35.0,316.709778,false,Manual,7.870067",
          ContentFR = "Si je soignais quelqu’un à la légère et qu’une erreur survenait... ce serait une faute médicale impardonnable.",
          DialogueId = 80200025,
          FinalCamera = "22.796768,325.479004,117.170898,0.000079,4.200812,-101.992027,35.0,309.972931,false,Manual,7.870067",
          GUID = "C8C5B89A",
          NextDialogue = 80200026,
          SpeakNpcId = 790053,
          Subtitle = "And if I were to err in treating a stranger... it would be malpractice, no different from harm.",
          TalkActionId = {
            [1] = "790008:Think_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B89A"
        },
        [80200026] = {
          ContentFR = "Alors j’ai réfléchi à quelqu’un qui me connaîtrait suffisamment... et accepterait de me faire confiance. Et finalement... il n’y a que toi.",
          DialogueId = 80200026,
          Duration = 2,
          GUID = "C8C5B8C4",
          NextDialogue = 80200027,
          SpeakNpcId = 790053,
          Subtitle = "So I searched my thoughts for someone who knows me — who might be willing to take that risk for me. In the end... there is only you.",
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B8C4"
        },
        [80200027] = {
          Camera = "-290.514648,-38.780998,123.578125,0.000118,-0.99953,28.606005,40.000011,357.798157,false,Manual,3.557784",
          ContentFR = "Bien sûr, l’état de santé relève de l’intime. Si tu refuses, je ne t’y contraindrai jamais.",
          DialogueId = 80200027,
          FacialId = {
            [1] = "790008:Smile01"
          },
          FinalCamera = "-316.806091,-53.123318,124.101562,0.00012,-0.99953,28.606005,40.000011,391.280212,false,Manual,3.557784",
          GUID = "C8C5B8EE",
          NextOptions = {
            [1] = 802000271,
            [2] = 802000272,
            [3] = 802000273
          },
          SpeakNpcId = 790053,
          Subtitle = "That said, health is a deeply private matter. If you are unwilling, I shall not press you.",
          TalkActionId = {
            [1] = "790008:Laugh01_Start",
            [2] = "790053:Baiheng_Story_Special03_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B8EE"
        },
        [80200029] = {
          ContentFR = "Merci... Pour toi, ce n’est peut-être qu’un petit service, mais je n’oublierai pas cette confiance.",
          DialogueId = 80200029,
          GUID = "C8C5B942",
          NextDialogue = 80200034,
          SpeakNpcId = 790053,
          Subtitle = "My thanks... It may seem a small kindness to you, but I shall carry it close to heart.",
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B942"
        },
        [80200031] = {
          ContentFR = "Q–Quoi ? Tu me fais confiance à ce point ? Attends, inutile d’enlever ton manteau si vite... !",
          DialogueId = 80200031,
          GUID = "C8C5B996",
          NextDialogue = 80200034,
          SpeakNpcId = 790053,
          Subtitle = "Eh—? Y—You trust me that much!? Wait, there's no need to take off your cloak just yet...",
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B996"
        },
        [80200033] = {
          ContentFR = "Jamais je ne te demanderais une chose aussi dangereuse ! Mais... est-ce un oui ?",
          DialogueId = 80200033,
          GUID = "C8C5B9EA",
          NextDialogue = 80200034,
          SpeakNpcId = 790053,
          Subtitle = "Heavens, I'd never ask anything so perilous! But... was that a yes?",
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5B9EA"
        },
        [80200034] = {
          Camera = "-12.930632,116.6409,137.194336,0.000094,6.600558,-127.588852,45.000011,194.999756,false,DoNotOverride,7.870067",
          ContentFR = "Merci de ne pas m’avoir rejetée. Je ferai de mon mieux.",
          DialogueId = 80200034,
          FacialId = {
            [1] = "790053:None"
          },
          GUID = "C8C5BA14",
          NextDialogue = 80200035,
          SpeakNpcId = 790053,
          Subtitle = "Then... you have my deepest thanks. I'll give it everything I have.",
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BA14"
        },
        [80200035] = {
          ContentFR = "Fushu procède à un examen minutieux.",
          DialogueId = 80200035,
          GUID = "C8C5BA3E",
          IsBlack = 1,
          Subtitle = "Fushu conducts a thorough and meticulous examination.",
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BA3E"
        },
        [80200036] = {
          Camera = "-40.848995,85.709183,149.865234,0.000094,1.200781,-124.785934,45.000011,194.999756,false,DoNotOverride,7.870067",
          ContentFR = "Hmm... ton corps est en excellente santé. Du moins, à ce que je peux constater. Mais...",
          DialogueId = 80200036,
          Duration = 2,
          FinalCamera = "-27.404249,104.783081,149.896484,0.000094,0.000697,-124.58551,45.000023,194.999756,false,DoNotOverride,7.870067",
          GUID = "C8C5BA68",
          NextDialogue = 80200037,
          Scripts = [[
PARA{
PlayAnimation{_delay{5.5},ActorId{790053},AnimationId{"Think_Start"},Duration{1}},
PlayFacial{_delay{5.5},ActorId{790053},FacialId{"Sad03"}},
LookAt{_delay{5.5},LookAtDescription{"790053:n(790008)"}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "Hm... You're in good health overall — at least, from what I can observe. However...",
          TalkActionId = {
            [1] = "790053:AgreeHead"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BA68"
        },
        [80200037] = {
          Camera = "392.614807,235.654694,222.652344,0.000092,-12.197959,-161.590683,35.0,526.995789,false,Manual,5.0",
          ContentFR = "Même si ton teint ne le trahit pas... cela fait très, très longtemps que tu ne dors plus correctement, n’est-ce pas ?",
          DialogueId = 80200037,
          FinalCamera = "428.94931,247.75415,230.928711,0.000092,-12.197959,-161.590683,35.0,575.327454,false,Manual,5.0",
          GUID = "C8C5BA92",
          NextOptions = {
            [1] = 802000371,
            [2] = 802000372,
            [3] = 802000373
          },
          Scripts = "PlayAnimation{_delay{5.5},ActorId{790053},AnimationId{\"Think_End\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "It doesn't show in your face, but... you've been without proper rest for quite some time, haven't you?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BA92"
        },
        [80200039] = {
          Camera = "-68.012299,-87.562286,149.491211,0.000127,-4.999302,78.203064,45.000023,243.328293,false,Manual,7.870067",
          ContentFR = "À la longue, cela peut laisser des séquelles. Sois {性别:prudent|prudente}. Si tu n’as pas d’endroit où te reposer, le Pavillon de l’Éphémère peut t’accueillir quelque temps.",
          DialogueId = 80200039,
          FinalCamera = "-71.695663,-105.224762,151.068359,0.000125,-4.999302,78.203476,45.000023,243.328293,false,Manual,7.870067",
          GUID = "C8C5BAE6",
          NextDialogue = 80200049,
          Scripts = "PlayAnimation{_delay{5.5},ActorId{790008},AnimationId{\"Sad02_End\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "If this keeps up, it could take a real toll on your health. Please take care. And if you've nowhere else to rest... the Hall of Ephemerality is open to you — for as long as you need.",
          TalkActionId = {
            [1] = "790008:Sad02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BAE6"
        },
        [80200041] = {
          Camera = "83.14875,64.28849,101.996094,0.000119,14.400353,-169.600876,45.000023,174.605179,false,Manual,13.342517",
          ContentFR = "Chercher la fortune est humain... mais s’épuiser ainsi ne l’est pas. Si tu continues, la prochaine consultation ne sera plus gratuite. Je pourrais même... envisager des honoraires très élevés.",
          DialogueId = 80200041,
          FinalCamera = "100.070984,67.397232,97.577148,0.000119,14.400353,-169.600876,45.000023,174.605179,false,Manual,13.342517",
          GUID = "C8C5BB3A",
          NextDialogue = 80200042,
          Scripts = [[
PARA{
PlayAnimation{_delay{1.5},ActorId{790053},AnimationId{"Talk03_Start"},Duration{1}},
PlayAnimation{_delay{9},ActorId{790053},AnimationId{"Talk03_End"},Duration{1}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "Seeking fortune is only natural... but pushing yourself to exhaustion is far from wise. If this persists, your next check-up won't be complimentary. I might even have to levy a rather steep consultation fee.",
          TalkActionId = {
            [1] = "790053:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BB3A"
        },
        [80200042] = {
          Camera = "-68.012299,-87.562286,149.491211,0.000127,-4.999302,78.203064,45.000023,243.328293,false,Manual,7.870067",
          ContentFR = "N–Non—attends—je—je—annule—j’annule !",
          DialogueId = 80200042,
          FacialId = {
            [1] = "790008:Shock01"
          },
          FinalCamera = "-71.695663,-105.224762,151.068359,0.000125,-4.999302,78.203476,45.000023,243.328293,false,Manual,7.870067",
          GUID = "C8C5BB64",
          NextDialogue = 80200049,
          SpeakNpcId = 790008,
          Subtitle = "Nooo... I take it back!",
          TalkActionId = {
            [1] = "790008:Deny01_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BB64"
        },
        [80200044] = {
          Camera = "18.80476,51.77895,116.756836,0.000134,19.000513,-169.000351,45.000023,104.895348,false,Manual,13.342517",
          ContentFR = "Hmm... si le patient se montre aussi peu coopératif, je devrai peut-être changer de traitement.",
          DialogueId = 80200044,
          FacialId = {
            [1] = "790053:None"
          },
          FinalCamera = "31.438776,54.239975,112.322266,0.000134,19.000513,-169.000351,45.000023,104.895348,false,Manual,13.342517",
          GUID = "C8C5BBB8",
          NextDialogue = 80200045,
          SpeakNpcId = 790053,
          Subtitle = "Hm... If the patient proves especially noncompliant, I may have to prescribe a more... hands-on remedy.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BBB8"
        },
        [80200045] = {
          Camera = "-59.732349,80.69458,137.875,0.000137,3.600158,57.199467,45.000023,104.895348,false,Manual,13.342517",
          ContentFR = "Par exemple ?",
          DialogueId = 80200045,
          FacialId = {
            [1] = "790008:Shock01"
          },
          FinalCamera = "-46.697857,72.286606,137.875,0.000137,3.600158,57.199017,45.000023,104.895348,false,Manual,13.342517",
          GUID = "C8C5BBE2",
          NextDialogue = 80200046,
          SpeakNpcId = 790008,
          Subtitle = "Like what?",
          ToFinalCameraBlendTime = 0.5,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BBE2"
        },
        [80200046] = {
          Camera = "86.032745,191.327408,140.46875,0.000115,0.600701,-140.191589,45.000011,194.999756,false,Manual,7.870067",
          ContentFR = "Je me suis entraînée aux arts martiaux dès l’enfance. Pour de simples fractures ou entorses, je peux soigner sans recourir à l’Art de l’Éphémère.",
          DialogueId = 80200046,
          FinalCamera = "77.175941,183.945618,140.588867,0.000115,0.600701,-140.191589,45.000011,215.31575,false,Manual,7.870067",
          GUID = "C8C5BC0C",
          NextDialogue = 80200047,
          SpeakNpcId = 790053,
          Subtitle = "I trained in martial arts from a young age. For ordinary sprains or fractures, I can manage treatment even without the Art of Ephemerality.",
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BC0C"
        },
        [80200047] = {
          Camera = "-68.012299,-87.562286,149.491211,0.000127,-4.999302,78.203064,45.000023,243.328293,false,Manual,7.870067",
          ContentFR = "Mais quand un patient souffre trop et se débat, cela peut empirer son état. Dans ces cas-là, frapper ici permet de le rendre inconscient temporairement. Viens, je te montre...",
          DialogueId = 80200047,
          FinalCamera = "-71.695663,-105.224762,151.068359,0.000125,-4.999302,78.203476,45.000023,243.328293,false,Manual,7.870067",
          GUID = "C8C5BC36",
          NextDialogue = 80200048,
          Scripts = "PlayAnimation{_delay{6.5},ActorId{790008},AnimationId{\"Shock03_Start\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "But if a patient thrashes in pain, it could aggravate the injury... In such cases, a strike here may render them unconscious. Come — allow me to show you.",
          TalkActionId = {
            [1] = "790053:Talk02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BC36"
        },
        [80200048] = {
          Camera = "-62.237785,15.439123,144.02832,0.000127,-1.999053,63.202065,45.000023,156.11145,false,Manual,7.870067",
          ContentFR = "N–Non merci ! Je vais opter pour un traitement plus... prudent !",
          DialogueId = 80200048,
          GUID = "C8C5BC60",
          NextDialogue = 80200049,
          SpeakNpcId = 790008,
          Subtitle = "N—No, thank you! I'll take the conservative treatment!",
          TalkActionId = {
            [1] = "790008:Shock03_End",
            [2] = "790008:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BC60"
        },
        [80200049] = {
          Camera = "917.762695,-1503.946777,620.68457,0.00014,-11.399223,120.200478,50.0,1992.261841,false,Manual,7.870067",
          ContentFR = "Il est clair que ton temps de sommeil est anormalement réduit... Souffres-tu d’insomnie ? Ou de difficultés à t’endormir ?",
          DialogueId = 80200049,
          FacialId = {
            [1] = "790008:None"
          },
          FinalCamera = "906.586975,-1504.471436,476.373047,0.000145,-11.399176,120.200394,50.0,1992.261841,false,Manual,7.870067",
          GUID = "C8C5BC8A",
          NextDialogue = 80200050,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.5},ActorId{790053},AnimationId{"Talk01_Start"},Duration{1}},
PlayAnimation{_delay{9.5},ActorId{790053},AnimationId{"Talk01_End"},Duration{1}}
}
]],
          SpeakNpcId = 790053,
          Subtitle = "Your level of sleep deprivation is quite severe... Have you been struggling with insomnia? Or difficulty falling asleep?",
          TalkActionId = {
            [1] = "790053:AgreeHead"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BC8A"
        },
        [80200050] = {
          Camera = "29.712376,30.286741,171.701172,0.000042,-16.598623,100.198341,35.0,121.834335,false,Manual,7.870067",
          ContentFR = "Je dors peu de nature... mais je rêve beaucoup. Il m’arrive de me réveiller en sursaut et de ne plus pouvoir me rendormir.",
          DialogueId = 80200050,
          FinalCamera = "31.944149,17.895794,175.456055,0.000043,-16.598602,100.198334,35.0,141.404282,false,Manual,7.870067",
          GUID = "C8C5BCB4",
          NextDialogue = 80200051,
          SpeakNpcId = 790008,
          Subtitle = "Maybe I'm just someone who doesn't need much sleep by nature... But I do dream a lot. Sometimes I wake suddenly and can't fall back asleep.",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BCB4"
        },
        [80200051] = {
          Camera = "21.420506,52.709782,178.382812,0.00004,-17.199427,-170.186905,35.0,194.999756,false,DoNotOverride,7.870067",
          ContentFR = "Je vois. Je pensais que cela venait de ton arrivée récente à Huaxu... mais il s’agit visiblement d’un trouble ancien.",
          DialogueId = 80200051,
          FinalCamera = "38.83992,55.71632,183.859375,0.000053,-17.199413,-170.186905,35.0,194.999756,false,DoNotOverride,7.870067",
          GUID = "C8C5BCDE",
          NextDialogue = 80200052,
          SpeakNpcId = 790053,
          Subtitle = "I see. I had assumed it was merely the pace of life since arriving in Huaxu... but this runs deeper. You've carried it with you far longer.",
          TalkActionId = {
            [1] = "790053:Explain02_Start",
            [2] = "790008:Think_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BCDE"
        },
        [80200052] = {
          Camera = "360.680786,-114.169701,136.203125,0.000063,-0.798668,151.998245,40.0,439.529266,false,Manual,7.870067",
          ContentFR = "J’ai toutefois préparé une formule. Je ne peux garantir une guérison immédiate, mais avec de la persévérance, elle devrait t’aider.",
          DialogueId = 80200052,
          FinalCamera = "383.679688,-126.399124,136.564453,0.000063,-0.798668,151.998245,40.0,439.529266,false,Manual,7.870067",
          GUID = "C8C5BD08",
          NextDialogue = 80200053,
          SpeakNpcId = 790053,
          Subtitle = "In any case, I've prepared a formula. I can't promise immediate results, but with consistent use, it should gradually ease the symptoms.",
          TalkActionId = {
            [1] = "790008:Shy03_Start",
            [2] = "790053:Explain02_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BD08"
        },
        [80200053] = {
          Camera = "-677.720764,380.481873,76.758789,0.000025,-31.199032,162.811325,35.0,313.548645,false,Manual,1.445948",
          ContentFR = "Cependant... l’ingrédient principal, la Rêvolis, n’est pas disponible ici. Il faut normalement la commander à Éternel Printemps, ce qui prendrait plusieurs jours.",
          DialogueId = 80200053,
          FinalCamera = "-710.28772,390.565186,56.109375,0.000025,-31.199032,162.811325,35.000008,732.714722,false,DoNotOverride,1.445948",
          GUID = "C8C5BD32",
          NextDialogue = 80200054,
          SpeakNpcId = 790053,
          Subtitle = "That said... the key ingredient is Oneirowort — and the Hall of Ephemerality is currently out of stock. It's normally sourced from EverSpring, but procuring it may take days.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BD32"
        },
        [80200054] = {
          Camera = "778.143555,49.141846,84.628906,0.000074,3.000878,175.011826,35.0,841.834229,false,Manual,1.445948",
          ContentFR = "Le mieux serait de chercher aux alentours du pavillon. Avec un peu de chance, tu pourras enfin dormir paisiblement cette nuit. Qu’en dis-tu ?",
          DialogueId = 80200054,
          FinalCamera = "775.015259,13.243744,84.628906,0.000074,3.000878,175.011826,35.0,841.834229,false,Manual,1.445948",
          GUID = "C8C5BD5C",
          NextDialogue = 80200055,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.5},ActorId{790053},AnimationId{"Think_End"},Duration{1}},
PlayAnimation{_delay{5.5},ActorId{790053},AnimationId{"Baiheng_Story_Special03_Start"},Duration{1}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "Our best chance may be to search the nearby area. With luck, you might sleep soundly as soon as tonight. What do you think?",
          TalkActionId = {
            [1] = "790053:Think_Start",
            [2] = "790008:Shy03_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BD5C"
        },
        [80200055] = {
          Camera = "-138.100891,-376.441467,153.882812,0.000078,-5.798817,78.616974,35.0,194.999756,false,DoNotOverride,7.870067",
          ContentFR = "Alors je compte sur toi !",
          DialogueId = 80200055,
          FinalCamera = "-148.366501,-427.434601,159.165039,0.000079,-5.798817,78.617157,35.0,194.999756,false,DoNotOverride,7.870067",
          GUID = "C8C5BD86",
          NextDialogue = 80200056,
          SpeakNpcId = 790008,
          Subtitle = "Sounds great! I'd appreciate that.",
          TalkActionId = {
            [1] = "790008:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BD86"
        },
        [80200056] = {
          Camera = "233.269958,261.403778,125.821289,0.000096,0.201415,-148.185486,35.000008,194.999756,false,DoNotOverride,7.870067",
          ContentFR = "Le temps presse. Partons sans tarder.",
          DialogueId = 80200056,
          FinalCamera = "260.721527,278.433655,125.711914,0.000096,0.201415,-148.185486,35.000008,194.999756,false,DoNotOverride,7.870067",
          GUID = "C8C5BDB0",
          Scripts = "PlayAnimation{_delay{3.5},ActorId{790008},AnimationId{\"AgreeHead\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "Come — no sense in lingering.",
          TalkActionId = {
            [1] = "790008:ScratchHead_End",
            [2] = "790053:Baiheng_Story_Special03_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/001/C8C5BDB0"
        },
        [80200101] = {
          Camera = "1531.92334,3538.163574,1883.558594,0.000098,-23.599333,-116.380653,25.0,3742.911621,false,Manual,1.2",
          ContentFR = "Sous l’eau vive pousse la Xing-flottante, sur l’étang calme fleurit le Lotus d’hiver. Sous l’arbre, parmi les champignons, croît la Rêvolis — Mais l’Échorine s’y confond, indiscernable...",
          DialogueId = 80200101,
          FinalCamera = "1369.106445,3209.869629,1836.991211,0.0001,-23.599354,-116.380653,25.0,3742.911621,false,Manual,1.2",
          GUID = "C8C5C512",
          NextDialogue = 80200102,
          Scripts = [[
PARA{
MoveTo{ActorId{790008},TargetPoint{"BP_Stage_200201a nvzhu00"},MoveSpeed{75},Visibility{"Show"}},
MoveTo{ActorId{790053},TargetPoint{"BP_Stage_200201a fushu00"},MoveSpeed{75},Visibility{"Show"}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "Liltfern sways where waters stream; Eclipta blooms where ripples gleam. Where fungi root beneath the tree, Oneirowort and Echowort be — Which is which, none e'er could see.",
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C512"
        },
        [80200102] = {
          Camera = "272.323822,540.773193,-5.51709,0.000158,1.596106,-125.767914,25.0,504.355042,false,Manual,2.8",
          ContentFR = "Je t’ai entendue réciter ces vers tout à l’heure. Ont-ils une signification particulière ?",
          DialogueId = 80200102,
          FinalCamera = "285.816895,531.043884,-5.51709,0.000157,1.596106,-125.767914,25.0,504.355042,false,Manual,2.8",
          GUID = "C8C5C53C",
          NextDialogue = 80200103,
          Scripts = "PlayAnimation{_delay{3.5},ActorId{790053},AnimationId{\"Shy02_Start\"},Duration{1}}",
          SpeakNpcId = 790008,
          Subtitle = "I heard you reciting something earlier — what do those lines mean?",
          TalkActionId = {
            [1] = "790008:Explain01_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C53C"
        },
        [80200103] = {
          ContentFR = "Il s’agit d’une comptine annexée au <I>Guide des plantes médicinales</>. Elle décrit simplement les milieux où poussent certaines herbes, afin d’aider ceux qui en auraient besoin à les trouver.",
          DialogueId = 80200103,
          GUID = "C8C5C566",
          NextDialogue = 80200104,
          Scripts = "PlayAnimation{_delay{5.5},ActorId{790053},AnimationId{\"Shy02_End\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "A rhyme from the appendix of Essentials of Medicinal Herbs — a simple mnemonic verse describing where certain plants tend to grow. It was written to help folk find remedies in times of need.",
          TalkActionId = {
            [1] = "790008:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C566"
        },
        [80200104] = {
          ContentFR = "De nos jours, à Huaxu, presque tout le monde en connaît quelques vers. On peut dire qu’elle est passée dans le langage courant.",
          DialogueId = 80200104,
          GUID = "C8C5C590",
          NextDialogue = 80200105,
          SpeakNpcId = 790053,
          Subtitle = "These days in Huaxu, most people know at least a few lines. It's become something of a common chant.",
          TurnTo = {
            [1] = "790053:p(-170)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C590"
        },
        [80200105] = {
          ContentFR = "Une fois mémorisée, elle permet de savoir où chercher un remède en cas de morsure, de piqûre, ou de maladie soudaine.",
          DialogueId = 80200105,
          GUID = "C8C5C5BA",
          NextDialogue = 80200106,
          SpeakNpcId = 790053,
          Subtitle = "Once committed to memory, it teaches you where to search — should you be bitten by a snake, stung by an insect, or fall ill far from aid.",
          TalkActionId = {
            [1] = "790053:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C5BA"
        },
        [80200106] = {
          Camera = "1127.049072,-417.77417,137.300293,0.000186,-4.403259,-49.972614,45.0,865.540161,false,Manual,2.8",
          ContentFR = "Les vers que je récitais expliquent que la Xing-flottante se trouve sous l’eau courante, le Lotus d’hiver dans les étangs, et que la Rêvolis pousse généralement au pied des arbres, près des champignons. Cependant...",
          DialogueId = 80200106,
          FinalCamera = "1169.831299,-381.845581,137.300293,0.000186,-4.403259,-49.972614,45.0,865.540161,false,Manual,2.8",
          GUID = "C8C5C5E4",
          NextDialogue = 80200107,
          SpeakNpcId = 790053,
          Subtitle = "The part I was reciting says Liltfern grows beneath the stream, Eclipta Grass by the water's edge, and Oneirowort by tree roots — often where fungi thrive. However...",
          TalkActionId = {
            [1] = "790053:Explain01_End"
          },
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C5E4"
        },
        [80200107] = {
          ContentFR = "Il existe une plante nommée Échorine, presque identique à la Rêvolis. Sans l’œil d’un médecin ou d’un herboriste expérimenté, il est pratiquement impossible de les distinguer.",
          DialogueId = 80200107,
          GUID = "C8C5C60E",
          NextDialogue = 80200108,
          SpeakNpcId = 790053,
          Subtitle = "There's another plant, Echowort, that so closely resembles Oneirowort it's near impossible to tell them apart, unless you're a seasoned herbalist or physician.",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C60E"
        },
        [80200108] = {
          Camera = "-43.556976,175.887131,26.972168,0.00019,2.19607,-57.766472,35.0,102.559563,false,Manual,8.468321",
          ContentFR = "Ma sœur avait bien joint des croquis comparatifs dans ses notes, mais...",
          DialogueId = 80200108,
          GUID = "C8C5C638",
          NextDialogue = 80200109,
          SpeakNpcId = 790053,
          Subtitle = "My sister left behind some comparative sketches in her notes, but...",
          TalkActionId = {
            [1] = "790053:Think_Start"
          },
          TurnTo = {
            [1] = "790008:n(790053)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C638"
        },
        [80200109] = {
          Camera = "-2162.862305,-1856.842285,475.34668,0.000297,-6.00418,31.439232,25.0,3742.911621,false,Manual,2.8",
          ContentFR = "Fushu ouvre devant vous un vieux livre. Vous jetez un œil aux illustrations — dignes d’un manifeste d’art avant-gardiste de Luca. Vous échangez un regard désemparé.",
          DialogueId = 80200109,
          Duration = 8,
          FinalCamera = "-2293.00708,-1643.934814,475.34668,0.000282,-6.004153,31.438747,25.0,3742.911621,false,Manual,2.8",
          GUID = "C8C5C662",
          LookAt = {
            [1] = "790053:n(790008)"
          },
          NextDialogue = 80200110,
          Scripts = "MoveTo{ActorId{790008},TargetPoint{\"BP_Stage_200201a nvzhu01\"},MoveSpeed{75},Visibility{\"Show\"}}",
          Subtitle = "(Fushu opens a weathered tome before you. You glance at the illustration — it wouldn't look out of place in one of Luca's avant-garde exhibits. You and Fushu exchange a helpless look.)",
          TalkActionId = {
            [1] = "790053:Think_End"
          },
          ToFinalCameraBlendTime = 15,
          TurnTo = {
            [1] = "790053:p(70)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C662"
        },
        [80200110] = {
          Camera = "-17.572052,-65.612328,29.06543,0.000324,-4.803699,88.838623,25.000006,198.752441,false,Manual,2.86577",
          ContentFR = "... Il n’y aurait vraiment aucun autre moyen ?",
          DialogueId = 80200110,
          FinalCamera = "-17.572052,-65.612328,22.90918,0.000324,-4.603697,89.038612,25.000006,198.752441,false,Manual,2.86577",
          GUID = "C8C5C68C",
          LookAt = {
            [1] = "790008:n(790053)"
          },
          NextDialogue = 80200111,
          SpeakNpcId = 790008,
          Subtitle = "...Is there any other way?",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C68C"
        },
        [80200111] = {
          ContentFR = "Si.",
          DialogueId = 80200111,
          GUID = "C8C5C6B6",
          NextDialogue = 80200112,
          SpeakNpcId = 790053,
          Subtitle = "There is.",
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C6B6"
        },
        [80200112] = {
          ContentFR = "Tu arrives à distinguer ça, et tu dis encore ne pas être versée en pharmacologie ? Ce n’est pas de la fausse modestie, j’espère.",
          DialogueId = 80200112,
          GUID = "C8C5C6E0",
          NextDialogue = 80200113,
          SpeakNpcId = 790008,
          Subtitle = "You can actually make sense of this? And you still say you're not good at pharmacology?",
          TalkActionId = {
            [1] = "790053:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C6E0"
        },
        [80200113] = {
          Camera = "-100.957642,97.399895,23.348633,-0.0,2.59638,5.238194,25.000006,107.654762,false,Manual,8.945262",
          ContentFR = "Non. Je parlais en toute sincérité.",
          DialogueId = 80200113,
          FinalCamera = "-110.44091,100.271729,22.933105,-0.0,2.59638,5.238703,25.000006,107.654762,false,Manual,9.192281",
          GUID = "C8C5C70A",
          NextDialogue = 80200114,
          SpeakNpcId = 790053,
          Subtitle = "I meant what I said. My knowledge barely scratches the surface.",
          TalkActionId = {
            [1] = "790008:Think_End",
            [2] = "790053:Shy03_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C70A"
        },
        [80200114] = {
          ContentFR = "C’est pourquoi... je vais y goûter.",
          DialogueId = 80200114,
          GUID = "C8C5C734",
          NextOptions = {
            [1] = 802001141,
            [2] = 802001142,
            [3] = 802001143
          },
          SpeakNpcId = 790053,
          Subtitle = "Which is why... I plan to taste it.",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C734"
        },
        [80200118] = {
          Camera = "-7.335266,63.901058,19.666992,0.000328,0.796134,114.242729,25.000006,73.700699,false,Manual,6.954087",
          ContentFR = "Maintenant ?",
          DialogueId = 80200118,
          GUID = "C8C5C7DC",
          NextDialogue = 80200119,
          SpeakNpcId = 790008,
          Subtitle = "Right now?",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C7DC"
        },
        [80200119] = {
          Camera = "-124.730896,121.885643,18.354492,0.000339,4.396244,-8.16414,40.000011,142.142242,false,Manual,10.751457",
          ContentFR = "Maintenant.",
          DialogueId = 80200119,
          GUID = "C8C5C806",
          NextDialogue = 80200120,
          SpeakNpcId = 790053,
          Subtitle = "Right now.",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C806"
        },
        [80200120] = {
          Camera = "-19.875801,64.694672,26.397461,0.000339,-4.003659,104.637611,35.000008,61.685242,false,Manual,8.529664",
          ContentFR = "Comme ça... directement ?",
          DialogueId = 80200120,
          FacialId = {
            [1] = "790008:Shock01"
          },
          GUID = "C8C5C830",
          NextDialogue = 80200121,
          SpeakNpcId = 790008,
          Subtitle = "You're really going to eat it?",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C830"
        },
        [80200121] = {
          Camera = "-61.263931,118.475212,29.812012,0.000339,1.596277,-18.963583,40.000011,71.518158,false,Manual,10.743117",
          ContentFR = "Directement.",
          DialogueId = 80200121,
          FacialId = {
            [1] = "790053:Confident02"
          },
          GUID = "C8C5C85A",
          NextDialogue = 80200122,
          SpeakNpcId = 790053,
          Subtitle = "I am.",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C85A"
        },
        [80200122] = {
          Camera = "56.401764,-276.272797,359.396973,0.000302,-23.203312,-69.771858,35.0,957.564941,false,DoNotOverride,1.963203",
          ContentFR = "Rassure-toi. La toxicité de l’Échorine est extrêmement faible. Chez certaines personnes, elle n’a même aucun effet. Au pire, elle provoque quelques hallucinations passagères — d’ailleurs, le nom de la plante vient de l’expression « conserver l’écho et le visage d’un être cher »...",
          DialogueId = 80200122,
          FinalCamera = "184.088745,-229.228088,359.396484,0.000302,-23.203312,-69.771858,35.0,957.564941,false,DoNotOverride,1.963203",
          GUID = "C8C5C884",
          NextDialogue = 80200123,
          SpeakNpcId = 790053,
          Subtitle = "Don't worry — Echowort's toxins are exceedingly mild. Some feel nothing at all. At most, you may glimpse a fleeting vision. Its name stems from an old saying: \"to leave one's echoes and smiles in another's memory\" — a poetic way of remembering the departed.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C884"
        },
        [80200123] = {
          ContentFR = "... J’ai l’impression que ça ne me rassure pas du tout.",
          DialogueId = 80200123,
          GUID = "C8C5C8AE",
          NextDialogue = 80200124,
          SpeakNpcId = 790008,
          Subtitle = "...You do know that doesn't exactly make me less worried about you, right?",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C8AE"
        },
        [80200124] = {
          Camera = "-849.182129,91.680786,200.708984,0.000292,-14.003527,-4.370487,35.0,193.602356,false,DoNotOverride,1.963203",
          ContentFR = "Tout est affaire de dosage. Le poison ou le remède se distinguent souvent par la quantité.",
          DialogueId = 80200124,
          FinalCamera = "-1086.069824,90.220459,259.590332,0.000292,-14.003512,-4.37048,35.0,957.564941,false,DoNotOverride,1.963203",
          GUID = "C8C5C8D8",
          NextDialogue = 80200125,
          SpeakNpcId = 790053,
          Subtitle = "There's no need for alarm. In most cases, whether a plant is poisonous or not lies in the dose.",
          TalkActionId = {
            [1] = "790053:Shy02_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C8D8"
        },
        [80200125] = {
          ContentFR = "Si l’on n’en mange qu’un fragment de feuille, même une hallucination ne dure que quelques minutes.",
          DialogueId = 80200125,
          GUID = "C8C5C902",
          NextDialogue = 80200126,
          SpeakNpcId = 790053,
          Subtitle = "A single sliver of Echowort may bring on a vision — but it fades swiftly.",
          TalkActionId = {
            [1] = "790008:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C902"
        },
        [80200126] = {
          ContentFR = "Bien que la plupart des médecins le déconseillent... c’est bel et bien la méthode la plus simple pour différencier les deux plantes. De nombreux herboristes y ont recours.",
          DialogueId = 80200126,
          GUID = "C8C5C92C",
          LookAt = {
            [1] = "790053:n(790053)"
          },
          NextDialogue = 80200127,
          SpeakNpcId = 790053,
          Subtitle = "Most physicians discourage this method... yet for many herb gatherers, it remains the surest test.",
          TalkActionId = {
            [1] = "790053:Shy02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C92C"
        },
        [80200127] = {
          Camera = "24.366035,-108.460983,18.662598,0.000304,5.595769,91.042618,25.000006,87.857491,false,Manual,5.644706",
          ContentFR = "Et puis, je suis héritière de l’Art de l’Éphémère. Même si une réaction survenait, je me rétablirais aussitôt. Tu n’as rien à craindre.",
          DialogueId = 80200127,
          FacialId = {
            [1] = "790008:Sad03"
          },
          FinalCamera = "29.917435,-114.85643,18.026367,0.000304,5.595769,91.042618,25.000006,88.778442,false,Manual,9.148426",
          GUID = "C8C5C956",
          NextDialogue = 80200128,
          Scripts = "MoveTo{_delay{0.5},ActorId{790053},TargetPoint{\"BP_Stage_200201a fushu01\"},MoveSpeed{75},Visibility{\"Show\"}}",
          SpeakNpcId = 790053,
          Subtitle = "Besides — I practise the Art of Ephemerality. Even if a reaction occurs, I can recover at once. Truly, there's no need to worry.",
          TalkActionId = {
            [1] = "790008:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "790053:p(100)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C956"
        },
        [80200128] = {
          Camera = "-110.911285,136.177673,10.118164,0.000291,2.795774,-37.361984,25.000006,193.602356,false,Manual,1.963203",
          ContentFR = "Fushu cueille l’extrémité d’une feuille et la porte à sa bouche. Peu après, son regard se trouble, et elle commence à murmurer.",
          DialogueId = 80200128,
          FacialId = {
            [1] = "790053:Pain01"
          },
          FinalCamera = "-88.784508,117.885399,13.398438,0.000292,3.395786,-42.959278,25.000006,193.602356,false,Manual,1.963203",
          GUID = "C8C5C980",
          NextDialogue = 80200129,
          Subtitle = "(Fushu plucks the tip of the grass and places it on her tongue. Before long, her gaze dips low — and she begins to murmur softly beneath her breath.)",
          TalkActionId = {
            [1] = "790053:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C980"
        },
        [80200129] = {
          ContentFR = "Hmm...",
          DialogueId = 80200129,
          GUID = "C8C5C9AA",
          NextDialogue = 80200130,
          SpeakNpcId = 790053,
          Subtitle = "Mmh...",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C9AA"
        },
        [80200130] = {
          ContentFR = "Pourquoi... avoir renoncé...",
          DialogueId = 80200130,
          GUID = "C8C5C9D4",
          NextDialogue = 80200131,
          SpeakNpcId = 790053,
          Subtitle = "Why... forsake...",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C9D4"
        },
        [80200131] = {
          ContentFR = "Toi... l’Art de l’Éphémère...",
          DialogueId = 80200131,
          GUID = "C8C5C9FE",
          NextDialogue = 80200132,
          SpeakNpcId = 790053,
          Subtitle = "You... the Art of Ephemerality...",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5C9FE"
        },
        [80200132] = {
          Camera = "113.499001,-31.578545,43.0,0.000285,-6.404784,175.03244,25.000006,68.417297,false,Manual,5.395136",
          ContentFR = "... Fushu ? Fushu ? Tu sais encore qui tu es ?",
          DialogueId = 80200132,
          FinalCamera = "112.918457,-38.210022,43.0,0.000285,-6.404784,175.03244,25.000006,68.417297,false,Manual,5.395136",
          GUID = "C8C5CA28",
          NextDialogue = 80200133,
          Scripts = [[
SEQ{
MoveTo{ActorId{790008},TargetPoint{"BP_Stage_200201a nvzhu02"},MoveSpeed{95},Visibility{"Show"}},
TurnTo{TurnToDescription{"790008:n(790053)"}}
}]],
          SpeakNpcId = 790008,
          Subtitle = "...Fushu? Fushu!? Do you still know who you are?",
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CA28"
        },
        [80200133] = {
          Camera = "81.298691,-86.003426,-26.211426,0.000293,34.992874,120.430283,25.000006,94.024963,false,Manual,6.516896",
          ContentFR = "Bien sûr. Je suis Fushu, praticienne du Zhuyou.",
          DialogueId = 80200133,
          FinalCamera = "90.446938,-101.709572,-38.469238,0.000291,33.992943,120.230286,25.000006,109.357407,false,Manual,5.14559",
          GUID = "C8C5CA52",
          LookAt = {
            [1] = "790008:n(790053)"
          },
          NextDialogue = 80200134,
          SpeakNpcId = 790053,
          Subtitle = "Of course. I am Fushu, the Zhuyou therapy user.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CA52"
        },
        [80200134] = {
          ContentFR = "Dotée du pouvoir divin conféré par les Neuf Chapitres de Dafeng, je dois sauver les vies et soulager les souffrances, accomplir mon devoir sans faillir, fût-ce au prix de mon sang. Ainsi ont agi tous les membres de la famille Fu...",
          DialogueId = 80200134,
          GUID = "C8C5CA7C",
          NextDialogue = 80200135,
          SpeakNpcId = 790053,
          Subtitle = "Endowed with divine power by the Nine Chapters of Dafeng, I must heal the sick and tend the dying — to uphold my duty without fail, even at the cost of my last breath. That is the path passed down through generations of my bloodline...",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CA7C"
        },
        [80200135] = {
          Camera = "1.20282,-148.704437,-23.814941,-8.000016,20.99094,79.829399,25.000006,137.399506,false,Manual,3.949137",
          ContentFR = "Alors pourquoi toi, Fufeng, serais-tu différente ? Pourquoi défier la volonté du Ciel, mépriser les vies d’en bas, abandonner le devoir du Zhuyou et t’écarter de la voie ?",
          DialogueId = 80200135,
          FacialId = {
            [1] = "790053:Angry01"
          },
          FinalCamera = "-1.691193,-164.853149,-30.109375,-8.000016,20.99094,79.829399,25.000006,137.399506,false,Manual,3.949137",
          GUID = "C8C5CAA6",
          LookAt = {
            [1] = "790053:n(790008)"
          },
          NextDialogue = 80200136,
          SpeakNpcId = 790053,
          Subtitle = "So why do you, Fufeng... defy that path without shame? You spurn Heaven's order above, disregard life below... abandon your healer's oath, and stray from our family's creed...",
          TalkActionId = {
            [1] = "790008:Explain02_Start",
            [2] = "790053:Sigh_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CAA6"
        },
        [80200136] = {
          ContentFR = "Attends ! Je ne suis pas ta sœur—",
          DialogueId = 80200136,
          GUID = "C8C5CAD0",
          NextDialogue = 80200137,
          SpeakNpcId = 790008,
          Subtitle = "Hold on! I'm not your sis—",
          TalkActionId = {
            [1] = "790008:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CAD0"
        },
        [80200137] = {
          Camera = "236.822632,-103.189087,84.118164,0.000283,-14.803396,162.835953,35.0,231.354126,false,Manual,6.101897",
          ContentFR = "Après ce que tu as fait... tu ne peux plus l’être.",
          DialogueId = 80200137,
          FinalCamera = "311.739746,-126.329514,104.841797,0.000284,-14.803334,162.835846,35.0,319.934235,false,Manual,6.101897",
          GUID = "C8C5CAFA",
          LookAt = {
            [1] = "790053:n(790053)"
          },
          NextOptions = {
            [1] = 802001371,
            [2] = 802001372,
            [3] = 802001373
          },
          SpeakNpcId = 790053,
          Subtitle = "After what you did... could you still call yourself my sister?",
          TalkActionId = {
            [1] = "790053:Talk03_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CAFA"
        },
        [80200139] = {
          ContentFR = "Quelle histoire absurde... Et pourtant... {nickname}... ce nom m’est étrangement familier...",
          DialogueId = 80200139,
          GUID = "C8C5CB4E",
          NextDialogue = 80200144,
          SpeakNpcId = 790053,
          Subtitle = "What sort of ridiculous tale is that supposed to be...? Although... ... that name... it does feel... familiar...",
          TalkActionId = {
            [1] = "790053:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CB4E"
        },
        [80200141] = {
          ContentFR = "... Tu t’en rends compte, à présent ? C’est... soudain. Je... je ne suis pas prête à te pardonner.",
          DialogueId = 80200141,
          GUID = "C8C5CBA2",
          NextDialogue = 80200144,
          SpeakNpcId = 790053,
          Subtitle = "You... truly regret it? This is... unexpected. I... I wasn't ready to forgive you...",
          TalkActionId = {
            [1] = "790053:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CBA2"
        },
        [80200143] = {
          ContentFR = "Mère... ? Mais... tu es morte depuis longtemps... Pardonne-moi... Si tu es venue me réprimander, c’est que j’ai dû te décevoir profondément...",
          DialogueId = 80200143,
          GUID = "C8C5CBF6",
          NextDialogue = 80200144,
          SpeakNpcId = 790053,
          Subtitle = "Mother...? But... you passed long ago... I must have failed so deeply that you've come to chastise me yourself...",
          TalkActionId = {
            [1] = "790053:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CBF6"
        },
        [80200144] = {
          Camera = "316.662354,-321.98291,-17.210449,0.000328,1.794318,137.019302,25.000006,416.265686,false,Manual,3.949137",
          ContentFR = "Non... ce n’est pas juste... Je ne suis plus la Fushu d’il y a cent ans...",
          DialogueId = 80200144,
          FacialId = {
            [1] = "790053:Sad03"
          },
          FinalCamera = "348.058899,-351.249207,-18.554199,0.000328,1.794318,137.019318,25.000006,416.265686,false,Manual,3.949137",
          GUID = "C8C5CC20",
          NextDialogue = 80200145,
          SpeakNpcId = 790053,
          Subtitle = "No... no, this isn't right... I'm not the Fushu of a century past.",
          TalkActionId = {
            [1] = "790053:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CC20"
        },
        [80200145] = {
          ContentFR = "Et ma sœur aussi...",
          DialogueId = 80200145,
          GUID = "C8C5CC4A",
          NextDialogue = 80200146,
          SpeakNpcId = 790053,
          Subtitle = "And my sister... she's long gone too...",
          TalkActionId = {
            [1] = "790053:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CC4A"
        },
        [80200146] = {
          Camera = "202.944183,-80.828308,97.52002,0.000333,-20.805847,168.223129,25.000006,235.269485,false,Manual,3.949137",
          ContentFR = "... Laisse-moi seule un instant. Ne me suis pas.",
          DialogueId = 80200146,
          FinalCamera = "205.474915,-68.67897,97.52002,0.000333,-20.805847,168.223129,25.000006,235.269485,false,Manual,3.949137",
          GUID = "C8C5CC74",
          NextDialogue = 80200147,
          Scripts = "MoveTo{_delay{2},ActorId{790053},TargetPoint{\"BP_Stage_200201a fushu02\"},MoveSpeed{65},Visibility{\"Show\"}}",
          SpeakNpcId = 790053,
          Subtitle = "...Please. Leave me be. I need a moment alone.",
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "790053:p(-170)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CC74"
        },
        [80200147] = {
          ContentFR = "Un bâton d’encens plus tard, Fushu revient à l’endroit où vous vous êtes séparés.",
          DialogueId = 80200147,
          GUID = "C8C5CC9E",
          IsBlack = 1,
          Subtitle = "An incense's time later, Fushu returns to where you parted.",
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CC9E"
        },
        [80200148] = {
          Camera = "514.843018,-282.773102,136.926758,0.000068,-3.999574,142.810944,30.000008,609.051941,false,Manual,2.015938",
          ContentFR = "Ça va mieux ?",
          DialogueId = 80200148,
          FacialId = {
            [1] = "790008:None",
            [2] = "790053:Sad01"
          },
          FinalCamera = "432.307831,-370.087555,136.926758,0.000073,-3.199554,131.41127,30.000008,609.051941,false,Manual,2.015938",
          GUID = "C8C5CCC8",
          NextDialogue = 80200149,
          Scripts = "PlayAnimation{_delay{1},ActorId{790008},AnimationId{\"Explain01_End\"},Duration{1}}",
          SpeakNpcId = 790008,
          Subtitle = "Feeling better?",
          TalkActionId = {
            [1] = "790008:Explain01_Start",
            [2] = "790053:Sigh_Loop"
          },
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CCC8"
        },
        [80200149] = {
          ContentFR = "Oui. Tout va bien. Pardonne-moi... J’ai perdu mon sang-froid.",
          DialogueId = 80200149,
          GUID = "C8C5CCF2",
          NextDialogue = 80200150,
          Scripts = "PlayAnimation{_delay{2},ActorId{790053},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "Mm. I'm all right now. Forgive me... I lost my composure.",
          TalkActionId = {
            [1] = "790053:Disagree",
            [2] = "790053:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CCF2"
        },
        [80200150] = {
          ContentFR = "Je ne t’ai pas effrayé, j’espère ?",
          DialogueId = 80200150,
          GUID = "C8C5CD1C",
          NextOptions = {
            [1] = 802001501,
            [2] = 802001502
          },
          SpeakNpcId = 790053,
          Subtitle = "Did I startle you?",
          TalkActionId = {
            [1] = "790053:Explain02_End",
            [2] = "790008:Confident_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CD1C"
        },
        [80200153] = {
          Camera = "158.343323,112.661469,131.67627,0.000074,1.799714,-170.205048,40.0,197.229141,false,Manual,8.780489",
          ContentFR = "Si cela ne t’a pas dérangé, tant mieux.",
          DialogueId = 80200153,
          FacialId = {
            [1] = "790053:Sad02"
          },
          FinalCamera = "148.15004,110.905052,132.002441,0.000074,1.799714,-170.205048,40.0,197.229141,false,Manual,8.780489",
          GUID = "C8C5CD9A",
          NextDialogue = 80200154,
          SpeakNpcId = 790053,
          Subtitle = "Then I'm relieved.",
          TalkActionId = {
            [1] = "790008:Confident_End"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CD9A"
        },
        [80200154] = {
          ContentFR = "... J’ai revu une dispute avec ma sœur, vieille de plus d’un siècle. Je pensais l’avoir dépassée, mais...",
          DialogueId = 80200154,
          FacialId = {
            [1] = "790053:Sad02"
          },
          GUID = "C8C5CDC4",
          NextDialogue = 80200155,
          Scripts = [[
PARA{
TurnTo{_delay{2},TurnToDescription{"790053:p(170)"}},
PlayAnimation{_delay{4.5},ActorId{790053},AnimationId{"Sad02_Start"},Duration{1}},
SEQ{
CameraMoveTo{_delay{5.01},TargetPosition{"-515.03064,-883.369263,360.678711,0.000062,-15.199882,63.794632,30.000008,125.0,false,DoNotOverride,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"-551.471924,-865.434082,360.678711,0.000064,-15.199888,63.79414,30.000008,125.0,false,DoNotOverride,2.8"},duration{15}}
}
}]],
          SpeakNpcId = 790053,
          Subtitle = "In that vision, I glimpsed an argument with my sister — a memory more than a century old. I thought I'd long made peace with it... but perhaps not entirely.",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CDC4"
        },
        [80200155] = {
          Camera = "-64.305794,-38.344486,108.832031,1.0,4.399236,53.000343,40.0,213.353607,false,Manual,8.188937",
          ContentFR = "Il y a cependant eu une découverte inattendue. Dans cette hallucination, il semblait que l’Échorine soit aussi une épice rare, et pas seulement une plante hallucinogène.",
          DialogueId = 80200155,
          FinalCamera = "-73.563438,-50.619896,107.648438,0.999998,4.399222,53.000751,40.0,213.353607,false,Manual,8.188937",
          GUID = "C8C5CDEE",
          NextDialogue = 80200156,
          Scripts = "TurnTo{_delay{2},TurnToDescription{\"790053:n(790008)\"}}",
          SpeakNpcId = 790053,
          Subtitle = "Still... there was something unexpected. It seemed to hint that Echowort is more than a simple hallucinogen — it's also a rare culinary herb.",
          TalkActionId = {
            [1] = "790053:Sad02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CDEE"
        },
        [80200156] = {
          Camera = "158.343323,112.661469,131.67627,0.000074,1.799714,-170.205048,40.0,197.229141,false,Manual,8.780489",
          ContentFR = "Elle enregistrerait les « souvenirs » de son environnement durant sa croissance. Celui qui la consomme pourrait alors entrevoir le passé de ces lieux...",
          DialogueId = 80200156,
          FacialId = {
            [1] = "790053:Confident01"
          },
          FinalCamera = "148.15004,110.905052,132.002441,0.000074,1.799714,-170.205048,40.0,197.229141,false,Manual,8.780489",
          GUID = "C8C5CE18",
          NextDialogue = 80200157,
          Scripts = "PlayAnimation{_delay{4},ActorId{790053},AnimationId{\"Think_End\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "Some say it absorbs the memories of the places it grows. Those who consume it may glimpse echoes of the past — stories rooted in the soil beneath it.",
          TalkActionId = {
            [1] = "790053:Think_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CE18"
        },
        [80200157] = {
          ContentFR = "Je n’ai jamais vu cette mention dans les éditions récentes du <I>Guide des plantes médicinales</>. Une omission, sans doute. Il faudrait la corriger.",
          DialogueId = 80200157,
          GUID = "C8C5CE42",
          NextDialogue = 80200158,
          Scripts = "PlayAnimation{_delay{4},ActorId{790053},AnimationId{\"Talk01_End\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "This isn't noted in the current edition of Essentials of Medicinal Herbs... likely a scribal omission. I should make a record — and see it restored.",
          TalkActionId = {
            [1] = "790053:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CE42"
        },
        [80200158] = {
          Camera = "-64.305794,-38.344486,108.832031,1.0,4.399236,53.000343,40.0,213.353607,false,Manual,8.188937",
          ContentFR = "Allons-y. Nous pourrions encore trouver la Rêvolis dans les environs.",
          DialogueId = 80200158,
          FacialId = {
            [1] = "790008:Beg"
          },
          FinalCamera = "-73.563438,-50.619896,107.648438,0.999998,4.399222,53.000751,40.0,213.353607,false,Manual,8.188937",
          GUID = "C8C5CE6C",
          NextDialogue = 80200159,
          SpeakNpcId = 790053,
          Subtitle = "Come. We may still find Oneirowort nearby.",
          TalkActionId = {
            [1] = "790053:Confident_Start",
            [2] = "790008:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CE6C"
        },
        [80200159] = {
          ContentFR = "On ne devrait pas laisser tomber ? Tu avais l’air vraiment mal...",
          DialogueId = 80200159,
          GUID = "C8C5CE96",
          NextDialogue = 80200160,
          SpeakNpcId = 790008,
          Subtitle = "I don't know... that looked like a serious case of food poisoning.",
          TalkActionId = {
            [1] = "790008:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CE96"
        },
        [80200160] = {
          Camera = "83.435791,64.057053,136.885742,0.000068,1.999476,179.598953,40.0,108.610825,false,Manual,7.645144",
          ContentFR = "Renoncer à mi-chemin n’est pas dans les habitudes de la famille Fu. Ne t’inquiète pas, je vais bien. Et si cela t’intéresse, je pourrais même te montrer une série complète des Cinq Jeux des Animaux — c’est excellent pour la santé, à condition de pouvoir suivre...",
          DialogueId = 80200160,
          GUID = "C8C5CEC0",
          NextDialogue = 80200161,
          SpeakNpcId = 790053,
          Subtitle = "It's not my nature to leave things half-done. Truly — I'm quite well. If you're curious, I could even demonstrate the full Five-Animal Frolics sequence. It's excellent for circulation... assuming you can keep up.",
          TalkActionId = {
            [1] = "790008:Talk02_End",
            [2] = "790053:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CEC0"
        },
        [80200161] = {
          Camera = "134.218704,-27.63744,135.273926,0.000073,-1.000513,111.398094,40.000011,154.959457,false,Manual,10.744748",
          ContentFR = "Euh... Peut-être après avoir trouvé la Rêvolis ?",
          DialogueId = 80200161,
          FacialId = {
            [1] = "790008:Smile02"
          },
          GUID = "C8C5CEEA",
          NextDialogue = 80200162,
          SpeakNpcId = 790008,
          Subtitle = "Uhh... maybe teach me after we find the Oneirowort?",
          TalkActionId = {
            [1] = "790008:Deny01"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CEEA"
        },
        [80200162] = {
          Camera = "476.449219,-253.639587,133.560059,0.000068,-3.999574,142.810989,30.000008,609.051941,false,Manual,2.015938",
          ContentFR = "Hé hé. Marché conclu.",
          DialogueId = 80200162,
          FinalCamera = "514.843018,-282.773102,136.926758,0.000068,-3.999574,142.810989,30.000008,609.051941,false,Manual,2.015938",
          GUID = "C8C5CF14",
          SpeakNpcId = 790053,
          Subtitle = "Heh. It's a promise.",
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/002/C8C5CF14"
        },
        [80200201] = {
          Camera = "296.831238,2487.655029,978.387207,0.000159,-0.599212,-85.411514,35.0,111.63089,false,DoNotOverride,20.07291",
          ContentFR = "La voilà.",
          DialogueId = 80200201,
          FinalCamera = "296.831238,2487.655029,978.387207,0.00016,-19.599077,-96.010071,35.0,111.63089,false,DoNotOverride,20.07291",
          GUID = "C8C5CF3E",
          NextDialogue = 80200202,
          SpeakNpcId = 790053,
          Subtitle = "Here's one.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5CF3E"
        },
        [80200202] = {
          ContentFR = "Je vais goûter la première. Si tu crains que je ne sois à nouveau prise d’un malaise, recule un peu. Reviens vérifier mon état dans quelques minutes.",
          DialogueId = 80200202,
          GUID = "C8C5CF68",
          LookAt = {
            [1] = "790053:n(790008)"
          },
          NextDialogue = 80200203,
          SpeakNpcId = 790053,
          Subtitle = "I'll try it. Should the effects prove unpleasant, you may step aside and return once they pass.",
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5CF68"
        },
        [80200203] = {
          Camera = "89.105469,150.867188,132.969238,0.000064,-0.998505,-137.796677,30.000002,198.114532,false,Manual,4.214613",
          ContentFR = "Attends !",
          DialogueId = 80200203,
          GUID = "C8C5CF92",
          NextDialogue = 80200204,
          SpeakNpcId = 790008,
          Subtitle = "Wait!",
          TalkActionId = {
            [1] = "790008:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5CF92"
        },
        [80200204] = {
          Camera = "-37.011719,125.353516,135.46582,0.000068,-2.597596,-30.799438,30.000008,198.114532,false,DoNotOverride,4.214613",
          ContentFR = "Et si... on échangeait ? Laisse-moi essayer à ta place.",
          DialogueId = 80200204,
          GUID = "C8C5CFBC",
          NextDialogue = 80200205,
          SpeakNpcId = 790008,
          Subtitle = "How about we switch — let me try it this time?",
          TalkActionId = {
            [1] = "790008:Explain02_End",
            [2] = "790053:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5CFBC"
        },
        [80200205] = {
          Camera = "89.105469,150.867188,132.969238,0.000064,-0.998505,-137.796631,30.000002,198.114532,false,Manual,4.214613",
          ContentFR = "Je ne peux accepter. Je n’ai aucune intention de te faire souffrir inutilement — ce n’était pas le but de ce soin.",
          DialogueId = 80200205,
          GUID = "C8C5CFE6",
          NextDialogue = 80200206,
          SpeakNpcId = 790053,
          Subtitle = "I cannot allow you to bear this in my stead. When I offered to treat you, I never intended to subject you to harm — however slight.",
          TalkActionId = {
            [1] = "790053:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5CFE6"
        },
        [80200206] = {
          Camera = "-37.011719,125.353516,135.46582,0.000068,-2.597596,-30.799438,30.000008,198.114532,false,DoNotOverride,4.214613",
          ContentFR = "Justement parce que tu es médecin, c’est à moi de prendre le risque.",
          DialogueId = 80200206,
          GUID = "C8C5D010",
          NextDialogue = 80200207,
          SpeakNpcId = 790008,
          Subtitle = "Exactly — you're the doctor here. So it should be me.",
          TalkActionId = {
            [1] = "790008:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D010"
        },
        [80200207] = {
          ContentFR = "S’il arrive quelque chose, je sais que tu pourras me sauver. Mais si c’est toi qui t’effondres... je ne connais rien à la médecine, ni à l’Art de l’Éphémère. Je ne pourrais que rester là, {性别:impuissant|impuissante}.",
          DialogueId = 80200207,
          FacialId = {
            [1] = "790008:Nervous"
          },
          GUID = "C8C5D03A",
          NextDialogue = 80200208,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.1},ActorId{790008},AnimationId{"Explain02_Start"},Duration{1}},
PlayAnimation{_delay{7.1},ActorId{790008},AnimationId{"Explain02_End"},Duration{1}}
}]],
          SpeakNpcId = 790008,
          Subtitle = "If something goes wrong, I know you'll be able to save me. But if you collapse... I wouldn't know where to begin. I'd be helpless.",
          TalkActionId = {
            [1] = "790008:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D03A"
        },
        [80200208] = {
          Camera = "-75.154465,1007.605713,531.828613,0.000125,-25.599077,-85.208382,35.0,1081.229736,false,DoNotOverride,6.835649",
          ContentFR = "C’est... Je ne peux pas être d’accord. Mais je reconnais que je n’y avais pas suffisamment réfléchi. Peut-être devrions-nous chercher une autre mé—",
          DialogueId = 80200208,
          FinalCamera = "-85.453995,1130.481567,590.911621,0.000125,-25.599077,-85.208382,35.0,1081.229736,false,DoNotOverride,6.835649",
          GUID = "C8C5D064",
          LookAt = {
            [1] = "790053:n(790053)",
            [2] = "790008:n(790053)"
          },
          NextDialogue = 80200209,
          Scripts = [[
LookAt{_delay{6.01},LookAtDescription{"790053:n(790008)"}}



]],
          SpeakNpcId = 790053,
          Subtitle = "I... I can't agree to that. But I see your reasoning — I didn't consider it carefully enough. Perhaps we should find ano—",
          TalkActionId = {
            [1] = "790053:Think_End"
          },
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "790053:p(75)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D064"
        },
        [80200209] = {
          ContentFR = "Sans lui laisser le temps de finir, vous arrachez un fragment de feuille, à peine grand comme un ongle, et l’enfournez dans votre bouche.",
          DialogueId = 80200209,
          Duration = 2,
          GUID = "C8C5D08E",
          NextDialogue = 80200210,
          Scripts = "PlayAnimation{_delay{1.9},ActorId{790008},AnimationId{\"Laugh01_Start\"},Duration{1}}",
          Subtitle = "(Before she can finish, you pinch off a sliver of the herb's blade and place it on your tongue.)",
          TurnTo = {
            [1] = "790008:n(790053)",
            [2] = "790053:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D08E"
        },
        [80200210] = {
          Camera = "-26.813253,90.971672,125.448242,0.000143,18.400255,-128.598114,45.0,69.91674,false,Manual,9.337125",
          ContentFR = "Ah !",
          DialogueId = 80200210,
          FacialId = {
            [1] = "790053:Shock02"
          },
          GUID = "C8C5D0B8",
          NextDialogue = 80200211,
          SpeakNpcId = 790053,
          Subtitle = "Ah—!",
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D0B8"
        },
        [80200211] = {
          ContentFR = "Mais... qu’est-ce que— Attends, ce n’est pas—",
          DialogueId = 80200211,
          GUID = "C8C5D0E2",
          NextDialogue = 80200212,
          Scripts = "MoveTo{_delay{2.01},ActorId{790053},TargetPoint{\"BP_200301a_fushu01\"},MoveSpeed{100},Visibility{\"Show\"}}\n",
          SpeakNpcId = 790053,
          Subtitle = "What are you—!? No... this isn't the time to—",
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D0E2"
        },
        [80200212] = {
          Camera = "-3.932695,151.455307,158.64209,0.000183,-14.39743,-63.200489,35.0,81.946014,false,Manual,9.956834",
          ContentFR = "Comment te sens-tu ?",
          DialogueId = 80200212,
          FacialId = {
            [1] = "790008:Uninterested01"
          },
          GUID = "C8C5D10C",
          NextDialogue = 80200213,
          SpeakNpcId = 790053,
          Subtitle = "How do you feel!?",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D10C"
        },
        [80200213] = {
          ContentFR = "Hmm... pas mal. Le goût est frais, un peu mentholé... c’est même plutôt agréa—",
          DialogueId = 80200213,
          GUID = "C8C5D136",
          NextDialogue = 80200214,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6.01},TargetPosition{"43.367142,98.584366,137.931641,0.000168,18.599136,163.187195,35.000008,111.63089,false,Manual,20.07291"},duration{0}},
CameraMoveTo{TargetPosition{"43.367142,98.584366,137.931641,0.00015,46.798969,165.587006,35.000008,111.63089,false,Manual,20.07291"},Blend{"easeInOutQuad"},duration{3}}
}]],
          SpeakNpcId = 790008,
          Subtitle = "Mmm... not bad. Kinda minty. It's got this clean, cooool...",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D136"
        },
        [80200214] = {
          ContentFR = "Le visage de Fushu se brouille peu à peu. Une chose devient évidente : vous ne faites pas partie des personnes tolérantes à l’Échorine.",
          DialogueId = 80200214,
          GUID = "C8C5D160",
          IsBlack = 1,
          Subtitle = "(Her face begins to blur before your eyes. One thing becomes clear: you are not naturally tolerant to Echowort.)",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D160"
        },
        [80200215] = {
          ContentFR = "Entrée dans l’illusion. Le protagoniste apparaît dans le Pavillon de l’Éphémère. Une silhouette se tient plus loin, dos tourné.",
          DialogueId = 80200215,
          GUID = "C8C5D18A",
          Subtitle = "Enter an illusory realm. The protagonist is transported to the Hall of Ephemerality. An NPC (Fufeng) stands with her back turned.",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D18A"
        },
        [80200216] = {
          Camera = "-166.21434,-364.135559,166.314453,5.0,-28.801657,28.80596,30.000008,107.243362,false,Manual,2.8",
          ContentFR = "La tête... tourne... C’est... le Pavillon de l’Éphémère ?",
          DialogueId = 80200216,
          FinalCamera = "-193.228027,-378.986328,183.258789,5.000042,-29.001637,30.205877,30.000008,107.243362,false,Manual,2.8",
          GUID = "C8C5D1B4",
          NextDialogue = 80200217,
          Scripts = [[
PARA{
SEQ{
CameraMoveTo{_delay{3.01},TargetPosition{"-100.220222,-4.642982,23.701172,-8.017351,11.596875,-97.81694,25.0,107.243362,false,DoNotOverride,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"-100.220222,-4.642982,23.701172,-8.018849,14.59651,-92.416206,25.000002,107.243362,false,DoNotOverride,2.8"},duration{8}}
},
PlayAnimation{_delay{4.01},ActorId{790008},AnimationId{"Story_Headache_End"},Duration{1}},
TurnTo{_delay{6.01},TurnToDescription{"790008:p(-140)"}},
LookAt{_delay{7.01},LookAtDescription{"790008:p(BP_200301_nvzhu01)"}}
}
]],
          SpeakNpcId = 790008,
          Subtitle = "Ugh... my head... This place — is this the Hall of Ephemerality?",
          TalkActionId = {
            [1] = "790008:Story_Headache_Loop"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D1B4"
        },
        [80200217] = {
          ContentFR = "Et là-bas... c’est Fushu ?",
          DialogueId = 80200217,
          FacialId = {
            [1] = "790008:Shock01"
          },
          GUID = "C8C5D1DE",
          LookAt = {
            [1] = "790008:n(790054)"
          },
          NextDialogue = 80200218,
          Scripts = "PlayAnimation{_delay{1.01},ActorId{790008},AnimationId{\"Talk03_Start\"},Duration{1}}",
          SpeakNpcId = 790008,
          Subtitle = "And is that... Fushu?",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D1DE"
        },
        [80200218] = {
          Camera = "-84.304626,35.644173,65.415039,0.000002,2.396269,78.78582,35.0,107.243362,false,DoNotOverride,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Quelle plaie... quelle plaie... quelle plaie !",
          DialogueId = 80200218,
          FacialId = {
            [1] = "790054:Angry01"
          },
          FinalCamera = "-66.061569,127.614021,68.84082,0.000002,1.396248,78.785858,35.0,107.243362,false,DoNotOverride,2.8",
          GUID = "C8C5D208",
          NextDialogue = 80200219,
          SpeakNpcId = 790054,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Ugh... what a nuisance. Truly, what a wretched nuisance!",
          TalkActionId = {
            [1] = "790054:Angry01_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D208"
        },
        [80200219] = {
          ContentFR = "Je me l’étais pourtant répété ce matin : ne la provoque pas, ne la provoque pas ! Et voilà qu’avant même d’avoir fini le petit-déjeuner, j’ai déjà rompu ma promesse !",
          DialogueId = 80200219,
          GUID = "C8C5D232",
          NextDialogue = 80200220,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Sigh_Start"},Duration{1}},
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{"Sigh_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Told myself again and again this morning — don't snap, don't prod her. And yet what happened? Didn't even get through our breakfast before I provoked that stubborn mule again!",
          TalkActionId = {
            [1] = "790054:Angry01_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D232"
        },
        [80200220] = {
          Camera = "-2343.795166,1023.041992,114.227539,0.000092,-0.803982,-4.996912,35.0,2401.962891,false,Manual,2.8",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Fufeng, franchement... comment peux-tu être aussi incapable de te retenir ? Même si cette gamine a un caractère exécrable, c’est ta propre sœur ! Tu n’allais pas l’abandonner de toute façon, alors pourquoi t’acharner à la faire enrager ?",
          DialogueId = 80200220,
          FinalCamera = "-2335.671875,1115.896973,114.227539,0.000092,-0.803982,-4.997154,35.0,2401.962891,false,Manual,2.8",
          GUID = "C8C5D25C",
          NextDialogue = 80200221,
          Scripts = [[
PARA{
TurnTo{_delay{1.01},TurnToDescription{"790054:p(90))"}},
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Talk03_Start"},Duration{1}},
PlayAnimation{_delay{9.01},ActorId{790054},AnimationId{"Talk03_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Fufeng, honestly... must you always rise to it? Prickly as she is, she's still your little sister. It's not as though you can simply turn your back on her. So why keep needling her?",
          TalkActionId = {
            [1] = "790008:Talk03_End"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D25C"
        },
        [80200221] = {
          Camera = "76.413086,1077.357422,133.182617,0.000061,0.986498,-55.45702,40.000011,61.390137,false,Manual,9.159348",
          ContentFR = "Mais c’est plus fort que moi ! Cette expression trop sérieuse, trop appliquée... elle est tellement facile à taquiner... Le sourire n’a pas disparu — il a simplement quitté le visage de ma petite sœur pour s’installer sur le mien...",
          DialogueId = 80200221,
          FacialId = {
            [1] = "790054:Sad01"
          },
          GUID = "C8C5D286",
          NextDialogue = 80200222,
          Scripts = [[
PARA{
SetLocation{ActorId{790008},TargetPoint{"BP_200301b_fushu01"},Visibility{"Show"}},
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Angry01_End"},Duration{1}},
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{"Think_Start"},Duration{1}},
PlayFacial{_delay{8.01},ActorId{790054},FacialId{"Smile02"}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "But I can't help it! That solemn little face — it's infuriating. And now, the smile's gone from her lips... and somehow ended up on mine.",
          TalkActionId = {
            [1] = "790054:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D286"
        },
        [80200222] = {
          Camera = "76.413086,1077.357422,133.182617,0.000061,0.986498,-55.45702,40.000011,61.390137,false,Manual,9.159348",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "C’est humain, non ? Tout à fait humain...",
          DialogueId = 80200222,
          FinalCamera = "108.321411,1110.508301,147.339844,0.000063,-8.613893,-93.255981,40.0,218.69223,false,Manual,11.861392",
          GUID = "C8C5D2B0",
          NextDialogue = 80200223,
          Scripts = "MoveTo{ActorId{790008},TargetPoint{\"BP_200301b_nvzhu01\"},MoveSpeed{100},Visibility{\"Show\"}}",
          SpeakNpcId = 790054,
          Subtitle = "Human nature, isn't it? Just plain human nature...",
          TalkActionId = {
            [1] = "790054:Think_End"
          },
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D2B0"
        },
        [80200223] = {
          ContentFR = "Fu... Fushu ? C’est bien toi ?",
          DialogueId = 80200223,
          Duration = 1,
          GUID = "C8C5D2DA",
          LookAt = {
            [1] = "790008:n(790054)",
            [2] = "790054:n(790008)"
          },
          NextDialogue = 80200224,
          SpeakNpcId = 790008,
          Subtitle = "F—Fushu? Is that you?",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D2DA"
        },
        [80200224] = {
          Camera = "-5.917664,812.056946,114.511719,0.000043,2.986077,54.542389,35.000015,234.030762,false,Manual,3.823875",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Non, pas du tout. Je suis Fufeng, sa sœur jumelle. Tu n’es pas le premier à nous confondre.",
          DialogueId = 80200224,
          FacialId = {
            [1] = "790008:None",
            [2] = "790054:None"
          },
          FinalCamera = "-19.185059,822.114929,114.511719,0.000044,2.786068,50.5424,35.000015,234.030762,false,Manual,3.823875",
          GUID = "C8C5D304",
          NextDialogue = 80200225,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Confident_Start"},Duration{1}},
PlayAnimation{_delay{6.01},ActorId{790054},AnimationId{"Confident_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "Ah — I'm afraid not. I'm Fufeng, her twin sister. You wouldn't be the first to mix us up.",
          TalkActionId = {
            [1] = "790054:DisagreeHead"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D304"
        },
        [80200225] = {
          ContentFR = "Tu cherchais Fushu ? Étrange... Elle n’est pas du genre à fréquenter qui que ce soit. Un vrai coquillage refermé sur lui-même. Je ne pensais pas qu’elle avait des proches.",
          DialogueId = 80200225,
          GUID = "C8C5D32E",
          NextOptions = {
            [1] = 802002251,
            [2] = 802002252,
            [3] = 802002253
          },
          Scripts = [[
PARA{
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Talk01_End"},Duration{1}},
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{6.01},ActorId{790054},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "You're looking for Fushu? How curious. She's not one to mingle — closed up like a little clamshell, that one. Didn't think she had anyone she'd call a friend.",
          TalkActionId = {
            [1] = "790054:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D32E"
        },
        [80200226] = {
          ContentFR = "Oh... À ton âge, ne pas la trouver ennuyeuse, et même la louer ainsi... Voilà qui est rare. Dans ce cas, {性别:un ami de Fushu est aussi un ami de Fufeng|une amie de Fushu est aussi une amie de Fufeng}.",
          DialogueId = 80200226,
          FacialId = {
            [1] = "790054:Smile01"
          },
          GUID = "C8C5D382",
          NextDialogue = 80200229,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Confident_Start"},Duration{1}},
PlayAnimation{_delay{5.01},ActorId{790054},AnimationId{"Confident_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "Huh... Someone your age, speaking so earnestly of her quiet ways? That's rare. Well, if you're a friend of hers, then you have a friend in me.",
          TalkActionId = {
            [1] = "790054:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D382"
        },
        [80200227] = {
          ContentFR = "Escroquer quelqu’un jusqu’au Pavillon de l’Éphémère ? Va donc demander aux gens d’ici : même en la secouant tête en bas, pas une seule pièce ne tomberait de ses poches. Si tu veux mentir, choisis au moins une cible crédible.",
          DialogueId = 80200227,
          FacialId = {
            [1] = "790054:Angry01"
          },
          GUID = "C8C5D3D6",
          NextDialogue = 80200229,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Angry01_Start"},Duration{1}},
PlayAnimation{_delay{8.01},ActorId{790054},AnimationId{"Angry01_End"},Duration{1}},
PlayAnimation{_delay{8.5},ActorId{790054},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{_delay{10},ActorId{790054},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "What, here to swindle my little sister now? Please — shake her upside down and not a single coin would fall. If you're going to lie, at least pick a more plausible mark.",
          TalkActionId = {
            [1] = "790054:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D3D6"
        },
        [80200228] = {
          ContentFR = "<I>Beurk,</> langue bien pendue. Si tu n’es ni malade ni {性别:blessé|blessée}, rentre donc jouer ailleurs, sois sage.",
          DialogueId = 80200228,
          GUID = "C8C5D42A",
          NextDialogue = 80200229,
          Scripts = "PlayAnimation{_delay{4.01},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 790054,
          Subtitle = "Ugh, smooth talker. If you're neither sick or wounded, best run along and try your luck elsewhere.",
          TalkActionId = {
            [1] = "790054:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D42A"
        },
        [80200229] = {
          Camera = "-30.235046,1285.589722,155.125977,0.000064,-7.212188,-68.241211,35.000019,393.319,false,Manual,3.482719",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Alors, qu’est-ce qui t’amène au Pavillon de l’Éphémère ?",
          DialogueId = 80200229,
          FacialId = {
            [1] = "790054:None"
          },
          FinalCamera = "31.76886,1303.230225,155.125977,0.00006,-7.012207,-79.441032,35.000019,393.319,false,Manual,3.482719",
          GUID = "C8C5D454",
          NextDialogue = 80200230,
          SpeakNpcId = 790054,
          Subtitle = "So... what brings you to the Hall of Ephemerality?",
          TalkActionId = {
            [1] = "790054:Confident_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D454"
        },
        [80200230] = {
          ContentFR = "J’ai mangé de l’Échorine par erreur. J’ai la tête qui tourne et je vois des choses étranges. Je me suis dit que Fushu saurait quoi faire.",
          DialogueId = 80200230,
          FacialId = {
            [1] = "790008:Sad03"
          },
          GUID = "C8C5D47E",
          NextDialogue = 80200231,
          Scripts = "PlayAnimation{_delay{7.01},ActorId{790008},AnimationId{\"Explain02_End\"},Duration{1}}\n",
          SpeakNpcId = 790008,
          Subtitle = "I accidentally ate some Echowort. My head's spinning and I'm seeing strange things. I thought Fushu might know what to do, so I came looking for her.",
          TalkActionId = {
            [1] = "790008:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D47E"
        },
        [80200231] = {
          Camera = "-1451.951172,1624.570801,804.917969,0.000134,-23.215143,-28.063692,35.000019,2117.26001,false,Manual,1.2",
          ContentFR = "Tu tombes mal. Elle est de mauvaise humeur — mieux vaut éviter de l’irriter davantage. Mais je suis médecin moi aussi.",
          DialogueId = 80200231,
          FinalCamera = "-1614.322998,1711.163574,883.839844,0.000134,-23.215143,-28.063692,35.000015,2117.26001,false,Manual,1.2",
          GUID = "C8C5D4A8",
          NextDialogue = 80200232,
          Scripts = [[
PARA{
PlayAnimation{_delay{5.01},ActorId{790054},AnimationId{"Think_End"},Duration{1}},
TurnTo{_delay{5.8},TurnToDescription{"790054:n(790008)"}},
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{"Confident_Start"},Duration{1}},
PlayAnimation{_delay{9.01},ActorId{790054},AnimationId{"Confident_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "Unlucky timing — she's sulking right now. Best not to poke the beehive. But I'm a physician too, you know. I could help.",
          TalkActionId = {
            [1] = "790054:Think_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D4A8"
        },
        [80200232] = {
          Camera = "-253.072449,961.222961,89.996094,0.000045,3.386319,-1.453428,35.000015,323.748901,false,Manual,3.482719",
          ContentFR = "Laisse-moi regarder...",
          DialogueId = 80200232,
          FinalCamera = "-253.819214,931.512756,89.996094,0.000045,3.186317,-1.253389,35.000015,323.748901,false,Manual,3.482719",
          GUID = "C8C5D4D2",
          NextDialogue = 80200233,
          Scripts = "MoveTo{ActorId{790054},TargetPoint{\"BP_200301b_fushu03\"},MoveSpeed{80},Visibility{\"Show\"}}",
          SpeakNpcId = 790054,
          Subtitle = "Let me have a look...",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D4D2"
        },
        [80200233] = {
          ContentFR = "Hmm... démarche stable, regard encore focalisé, parole claire... La dose ingérée est faible. Une demi-feuille, environ ?",
          DialogueId = 80200233,
          GUID = "C8C5D4FC",
          NextDialogue = 80200234,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Think_Start"},Duration{1}},
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{"Think_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "Hmm... your footing's steady, eyes still sharp, speech coherent — I'd wager it was a small dose. Half a blade, perhaps?",
          TalkActionId = {
            [1] = "790054:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D4FC"
        },
        [80200234] = {
          ContentFR = "Rien de grave. Tu iras mieux avant même que l’antidote ne soit prêt. Patiente un peu, tout va se dissiper.",
          DialogueId = 80200234,
          FacialId = {
            [1] = "790054:Smile01"
          },
          GUID = "C8C5D526",
          NextDialogue = 80200235,
          Scripts = "PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{\"Talk01_End\"},Duration{1}}",
          SpeakNpcId = 790054,
          Subtitle = "Nothing serious. You'll feel fine before the antidote even finishes steeping. Just sit tight — it'll pass.",
          TalkActionId = {
            [1] = "790054:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D526"
        },
        [80200235] = {
          Camera = "24.030762,840.372314,98.698242,0.000059,12.985261,58.542137,35.000023,135.488754,false,Manual,8.071544",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Si l’inconfort devient trop fort, j’ai sur moi quelques pilules d’agrume. Mâche-en deux, cela t’aidera.",
          DialogueId = 80200235,
          FinalCamera = "14.792786,846.531738,98.698242,0.000066,12.985261,54.742638,35.000023,135.488754,false,Manual,8.071544",
          GUID = "C8C5D550",
          NextDialogue = 80200236,
          SpeakNpcId = 790054,
          Subtitle = "If it grows unbearable, I've some tangerine tonic on hand. Chew a few — they ought to ease the discomfort.",
          ToFinalCameraBlendTime = 20,
          TurnTo = {
            [1] = "790054:p(-30)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D550"
        },
        [80200236] = {
          ContentFR = "Je parie que tu souffres aussi de peu de sommeil et de trop de rêves. Tu cherchais la Rêvolis, et tu as confondu avec l’Échorine.",
          DialogueId = 80200236,
          FacialId = {
            [1] = "790054:Angry01"
          },
          GUID = "C8C5D57A",
          LookAt = {
            [1] = "790054:n(790054)"
          },
          NextDialogue = 80200237,
          SpeakNpcId = 790054,
          Subtitle = "Let me guess — trouble sleeping? Too many dreams? Went hunting Oneirowort and picked Echowort instead?",
          TalkActionId = {
            [1] = "790054:Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D57A"
        },
        [80200237] = {
          ContentFR = "Mais pour ce genre de trouble, un breuvage de Vrilles rampantes et de Fleur-des-Fissures serait plus approprié. La Rêvolis aide à dormir, certes... mais elle fait ressurgir dans les rêves des souvenirs qu’on préférerait oublier.",
          DialogueId = 80200237,
          GUID = "C8C5D5A4",
          LookAt = {
            [1] = "790054:n(790008)"
          },
          NextDialogue = 80200238,
          Scripts = [[
PARA{
PlayAnimation{_delay{3.01},ActorId{790054},AnimationId{"Talk02_Start"},Duration{1}},
PlayAnimation{_delay{7.01},ActorId{790054},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{_delay{10.01},ActorId{790054},AnimationId{"DisagreeHead"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "If it's true relief you seek, you'd do better with a decoction of Creeping Tendrils and Crackblooms. Oneirowort may lull you to sleep, yes — but the memories it stirs will cling to your dreams, and weigh upon the heart.",
          TalkActionId = {
            [1] = "790054:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D5A4"
        },
        [80200238] = {
          Camera = "60.828491,978.365967,136.150391,0.000078,-7.614254,-76.449127,35.0,78.697502,false,Manual,8.071544",
          ContentFR = "... En dehors de l’apparence, toi et Fushu vous vous ressemblez beaucoup.",
          DialogueId = 80200238,
          FacialId = {
            [1] = "790008:Smile01"
          },
          GUID = "C8C5D5CE",
          NextDialogue = 80200239,
          SpeakNpcId = 790008,
          Subtitle = "...Looks aside, you and Fushu really are quite alike.",
          TalkActionId = {
            [1] = "790008:Laugh01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D5CE"
        },
        [80200239] = {
          Camera = "41.295807,880.312378,133.982422,0.00011,0.385721,62.549858,35.000011,88.438805,false,Manual,8.071544",
          ContentFR = "On me dit rarement ça. Nous sommes jumelles, mais on me trouve souvent trop impulsive, trop « hors des règles » — pas vraiment en accord avec le neuvième précepte des Neuf Chapitres de Dafeng.",
          DialogueId = 80200239,
          FacialId = {
            [1] = "790054:Smile01"
          },
          GUID = "C8C5D5F8",
          NextDialogue = 80200240,
          SpeakNpcId = 790054,
          Subtitle = "Now that's a rare remark. We may be twins, but I've always been the unruly one — ever toeing the line of Dafeng's Ninth Admonition.",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D5F8"
        },
        [80200240] = {
          Camera = "60.828491,978.365967,136.150391,0.000078,-7.614254,-76.449127,35.0,78.697502,false,Manual,8.071544",
          ContentFR = "Fushu paraît distante, toi pleine d’entrain. Mais dès qu’il s’agit de soigner quelqu’un, vous êtes identiques : sérieuses, patientes, profondément bienveillantes.",
          DialogueId = 80200240,
          FacialId = {
            [1] = "790008:Shy"
          },
          GUID = "C8C5D622",
          NextDialogue = 80200241,
          SpeakNpcId = 790008,
          Subtitle = "Fushu may seem cold and distant, and you blaze like fire — but when you're tending the sick, you're the same. Meticulous, gentle... utterly sincere.",
          TalkActionId = {
            [1] = "790008:Laugh01_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D622"
        },
        [80200241] = {
          Camera = "41.295807,880.312378,133.982422,0.00011,0.385721,62.549858,35.000011,88.438805,false,Manual,8.071544",
          ContentFR = "Toi... Maintenant, je te crois quand tu dis être proche d’elle.",
          DialogueId = 80200241,
          FacialId = {
            [1] = "790054:None"
          },
          GUID = "C8C5D64C",
          NextDialogue = 80200242,
          SpeakNpcId = 790054,
          Subtitle = "You... hah. Now I believe you're truly close to her.",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D64C"
        },
        [80200242] = {
          Camera = "-225.803223,724.690369,-5.095703,0.00006,18.385708,34.549988,35.000015,390.386017,false,Manual,3.482719",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Cette enfant est obstinée. Elle garde tout pour elle, et quand elle essaie de parler avec le cœur, les mots prennent toujours des détours étranges.",
          DialogueId = 80200242,
          FinalCamera = "-314.394165,663.687378,-40.84668,0.000058,18.385708,34.550003,35.000015,390.386017,false,Manual,3.482719",
          GUID = "C8C5D676",
          NextDialogue = 80200243,
          SpeakNpcId = 790054,
          Subtitle = "That girl... so hopelessly stubborn. Bottles up every thought. And when she tries to speak from the heart, the words twist themselves into knots.",
          TalkActionId = {
            [1] = "790054:Talk03_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D676"
        },
        [80200243] = {
          Camera = "60.795898,983.703857,142.798828,0.000097,-11.615378,-75.852562,35.000019,86.947418,false,Manual,4.75455",
          ContentFR = "Il faut sans doute quelqu’un d’aussi attentif que toi pour réussir à la comprendre.",
          DialogueId = 80200243,
          GUID = "C8C5D6A0",
          NextDialogue = 80200244,
          SpeakNpcId = 790054,
          Subtitle = "Takes someone patient and perceptive to understand her... Like you.",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D6A0"
        },
        [80200244] = {
          Camera = "41.295807,880.312378,133.982422,0.00011,0.385721,62.549858,35.000011,88.438805,false,Manual,8.071544",
          ContentFR = "Moi, la grande sœur, j’ai toujours eu la langue trop bien pendue... Je reconnais ma défaite.",
          DialogueId = 80200244,
          FacialId = {
            [1] = "790054:Smile01"
          },
          GUID = "C8C5D6CA",
          NextDialogue = 80200245,
          SpeakNpcId = 790054,
          Subtitle = "I've always had the sharper tongue — no wonder I rub her the wrong way. Some big sister I turned out to be.",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D6CA"
        },
        [80200245] = {
          Camera = "-1451.951172,1624.570801,804.917969,0.000134,-23.215143,-28.063692,35.000019,2117.26001,false,Manual,1.2",
          ContentFR = "Alors, proche de Fushu... J’ai une petite faveur à te demander. Pour elle, tu accepteras, n’est-ce pas ?",
          DialogueId = 80200245,
          FinalCamera = "-1614.322998,1711.163574,883.839844,0.000134,-23.215143,-28.063692,35.000015,2117.26001,false,Manual,1.2",
          GUID = "C8C5D6F4",
          NextDialogue = 80200246,
          SpeakNpcId = 790054,
          Subtitle = "Now then, friend of Fushu — I have a small favour to ask. And I trust you won't turn me down. Not when it's for her sake.",
          TalkActionId = {
            [1] = "790054:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D6F4"
        },
        [80200246] = {
          ContentFR = "Je t’écoute.",
          DialogueId = 80200246,
          GUID = "C8C5D71E",
          NextDialogue = 80200247,
          SpeakNpcId = 790008,
          Subtitle = "Sure. What is it?",
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D71E"
        },
        [80200247] = {
          Camera = "-272.939331,626.305969,174.68457,0.000111,-7.414948,45.139679,35.000015,466.027344,false,Manual,1.2",
          ContentFR = "Pourrais-tu m’aider à préparer un cadeau d’excuses pour Fushu ?",
          DialogueId = 80200247,
          GUID = "C8C5D748",
          NextDialogue = 80200248,
          SpeakNpcId = 790054,
          Subtitle = "May I trouble you to help me prepare an apology gift?",
          TalkActionId = {
            [1] = "790008:Confident_Start",
            [2] = "790054:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D748"
        },
        [80200248] = {
          Camera = "-272.939331,626.305969,174.68457,0.000111,-7.414948,45.139679,35.000015,466.027344,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Il y a non loin d’ici des eaux où l’on trouve souvent des Poulpes Shouxing. M’en rapporter quelques-unes... ce ne devrait pas être trop difficile, non ?",
          DialogueId = 80200248,
          FinalCamera = "-248.974243,678.924866,174.214844,0.000118,0.185153,65.936897,35.000019,4716.592773,false,Manual,1.2",
          GUID = "C8C5D772",
          Scripts = "PlayAnimation{_delay{1.01},ActorId{790054},AnimationId{\"Talk03_Start\"},Duration{1}}",
          SpeakNpcId = 790054,
          Subtitle = "There's a stretch of water not far from here where Shouxing Squid tend to gather. Could you catch a few for me? It shouldn't prove too difficult.",
          TalkActionId = {
            [1] = "790054:Talk02_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/003/C8C5D772"
        },
        [80200301] = {
          Camera = "-979.67981,-2224.893066,758.677734,0.000011,-14.599727,63.197662,30.000002,2650.537109,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Ouaah... Tu as vraiment réussi à en pêcher. Impressionnant. Moi qui me prétends bonne à tout, je pourrais rester assise ici toute une journée sans en attraper un seul...",
          DialogueId = 80200301,
          Duration = 1,
          FinalCamera = "-1096.155396,-2166.05835,758.677734,0.000011,-14.599727,63.197662,30.000002,2650.537109,false,Manual,1.2",
          GUID = "C8C5E5E2",
          NextDialogue = 80200302,
          Scripts = [[
PARA{
MoveTo{ActorId{790008},TargetPoint{"BP_200401a_nvzhu01"},MoveSpeed{90},Visibility{"Show"}},
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{"Explain01_Start"},Duration{1}},
PlayAnimation{_delay{6.1},ActorId{790054},AnimationId{"Explain01_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "Well now... you actually caught some? Impressive. As for me — jack of all trades though I claim to be — I could sit here all day and still come up empty...",
          ToFinalCameraBlendTime = 25,
          TurnTo = {
            [1] = "790054:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E5E2"
        },
        [80200302] = {
          Camera = "0.420166,-219.716721,163.364258,0.000018,-7.399601,85.99836,45.0,289.463654,false,Manual,6.00204",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "« Bonne à tout », c’est discutable.",
          DialogueId = 80200302,
          FacialId = {
            [1] = "790008:Smile01"
          },
          FinalCamera = "-18.45842,-218.633926,160.760742,0.000016,-6.999639,81.997551,45.0,289.463654,false,Manual,6.00204",
          GUID = "C8C5E60C",
          NextDialogue = 80200303,
          SpeakNpcId = 790008,
          Subtitle = "\"All trades\" might've been a stretch.",
          TalkActionId = {
            [1] = "790008:Laugh01_Start"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E60C"
        },
        [80200303] = {
          ContentFR = "Fushu m’a montré tes peintures. Très... abstraites.",
          DialogueId = 80200303,
          Duration = 3,
          FacialId = {
            [1] = "790008:Smile02"
          },
          GUID = "C8C5E636",
          LookAt = {
            [1] = "790008:n(790054)"
          },
          NextDialogue = 80200304,
          SpeakNpcId = 790008,
          Subtitle = "Fushu showed me your paintings. Very... avant-garde.",
          TalkActionId = {
            [1] = "790008:Laugh01_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E636"
        },
        [80200304] = {
          Camera = "-212.935883,315.686401,125.688477,0.000042,-0.800628,-54.792068,40.0,423.583282,false,Manual,6.00204",
          ContentFR = "... Vous êtes donc si proches que ça ? Elle t’a même montré ce genre de honte familiale ?",
          DialogueId = 80200304,
          FinalCamera = "-271.671875,398.944336,125.233398,0.000042,-0.800628,-54.792068,40.0,423.583282,false,Manual,6.00204",
          GUID = "C8C5E660",
          NextDialogue = 80200305,
          Scripts = "PlayAnimation{_delay{3.1},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 790054,
          Subtitle = "...She showed you those? Just how close are the two of you?",
          TalkActionId = {
            [1] = "790054:Confident_Start"
          },
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E660"
        },
        [80200305] = {
          ContentFR = "Euh... Mais je ne savais pas que Fushu aimait les Poulpes Shouxing.",
          DialogueId = 80200305,
          GUID = "C8C5E68A",
          LookAt = {
            [1] = "790054:n(790054)"
          },
          NextDialogue = 80200306,
          Scripts = "PlayAnimation{_delay{1.1},ActorId{790054},AnimationId{\"Confident_End\"},Duration{1}}",
          SpeakNpcId = 790008,
          Subtitle = "Well... not close enough to know she had a thing for Shouxing Squid.",
          TalkActionId = {
            [1] = "790008:Explain01L_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E68A"
        },
        [80200306] = {
          ContentFR = "Ce n’est pas le cas.",
          DialogueId = 80200306,
          GUID = "C8C5E6B4",
          NextDialogue = 80200307,
          SpeakNpcId = 790054,
          Subtitle = "Not quite.",
          TalkActionId = {
            [1] = "790008:Explain01L_End"
          },
          TurnTo = {
            [1] = "790054:p(70)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E6B4"
        },
        [80200307] = {
          ContentFR = "Elle les déteste. Petite, il suffisait qu’elle en voie un pour fondre en larmes.",
          DialogueId = 80200307,
          FacialId = {
            [1] = "790054:Smile02"
          },
          GUID = "C8C5E6DE",
          LookAt = {
            [1] = "790054:n(790008)"
          },
          NextOptions = {
            [1] = 802003071,
            [2] = 802003072,
            [3] = 802003073
          },
          SpeakNpcId = 790054,
          Subtitle = "She loathes them. When we were little, just seeing one would have her bawling her eyes out.",
          TalkActionId = {
            [1] = "790054:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E6DE"
        },
        [80200311] = {
          Camera = "-1.582031,-202.988312,154.458984,0.000054,-4.600522,86.210663,50.000008,127.993942,false,Manual,11.517033",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Ces derniers temps, nous nous sommes disputées plus d’une fois. Tu sais sans doute pourquoi.",
          DialogueId = 80200311,
          FacialId = {
            [1] = "790008:Beg",
            [2] = "790054:Sad01"
          },
          FinalCamera = "-4.151443,-241.749527,157.583984,0.000054,-4.600494,86.210938,50.000008,320.172394,false,Manual,6.00204",
          GUID = "C8C5E786",
          LookAt = {
            [1] = "790054:n(790054)"
          },
          NextDialogue = 80200312,
          SpeakNpcId = 790054,
          Subtitle = "We've been at odds a lot lately. I imagine you know why.",
          TalkActionId = {
            [1] = "790054:Angry01_End",
            [2] = "790008:Shy03_Start"
          },
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E786"
        },
        [80200312] = {
          ContentFR = "Je veux explorer de nouvelles méthodes pour soigner et sauver des vies. Elle, en revanche, tient à s’en tenir strictement à l’Art de l’Éphémère.",
          DialogueId = 80200312,
          Duration = 1,
          GUID = "C8C5E7B0",
          NextDialogue = 80200313,
          SpeakNpcId = 790054,
          Subtitle = "Simple, really — I want to explore new ways of healing. But she insists on clinging to the Art of Ephemerality.",
          TalkActionId = {
            [1] = "790054:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E7B0"
        },
        [80200313] = {
          Camera = "-96.161865,159.932739,99.22168,0.000047,7.599357,-58.392002,40.0,273.733917,false,Manual,6.00204",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "À vrai dire... elle n’a pas tort. Mes recherches sont incertaines, leurs effets encore inconnus — et surtout, elles s’écartent des Neuf Chapitres de Dafeng.",
          DialogueId = 80200313,
          FinalCamera = "-122.544006,202.442444,84.046875,0.000046,8.199416,-58.192867,40.0,320.911621,false,Manual,6.00204",
          GUID = "C8C5E7DA",
          NextDialogue = 80200314,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{"Think_Start"}},
LookAt{_delay{1.1},LookAtDescription{"790054:n(790008)"}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "And truthfully? I can't entirely fault her. My methods are untested, uncertain... and they stray far from the Nine Chapters of Dafeng.",
          TalkActionId = {
            [1] = "790054:Talk03_End"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E7DA"
        },
        [80200314] = {
          ContentFR = "Personne ne sait quelle fin m’attend, moi ou mes travaux.",
          DialogueId = 80200314,
          Duration = 2,
          GUID = "C8C5E804",
          LookAt = {
            [1] = "790054:n(790054)"
          },
          NextDialogue = 80200315,
          Scripts = "PlayAnimation{_delay{3.1},ActorId{790054},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 790054,
          Subtitle = "What lies ahead for me — or my work — I can't say.",
          TalkActionId = {
            [1] = "790054:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E804"
        },
        [80200315] = {
          Camera = "-63.858021,-9.877949,179.9375,0.000124,-18.402338,-38.786407,50.000011,105.212311,false,Manual,8.395343",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Mais une chose est sûre : si Fushu continue à abuser de l’Art de l’Éphémère, elle mourra jeune.",
          DialogueId = 80200315,
          FinalCamera = "-57.449242,-15.032286,177.196289,0.000124,-18.402338,-38.786407,50.000011,105.212311,false,Manual,8.395343",
          GUID = "C8C5E82E",
          NextDialogue = 80200316,
          Scripts = "PlayAnimation{_delay{5.1},ActorId{790054},AnimationId{\"Explain02_End\"},Duration{1}}",
          SpeakNpcId = 790054,
          Subtitle = "But one thing I do know: if she keeps pushing herself like this, the Art of Ephemerality will consume her.",
          TalkActionId = {
            [1] = "790054:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E82E"
        },
        [80200316] = {
          Camera = "-43.131927,125.243118,128.523438,0.000069,4.597353,-67.988014,55.0,219.25647,false,Manual,17.764473",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Et ça... je ne veux pas en être témoin. Alors je ne céderai pas. Et nos disputes ne sont pas près de s’arrêter.",
          DialogueId = 80200316,
          FinalCamera = "-50.373177,143.161255,126.967773,0.000069,4.597353,-67.987976,55.0,219.25647,false,Manual,17.764473",
          GUID = "C8C5E858",
          LookAt = {
            [1] = "790054:n(790008)"
          },
          NextDialogue = 80200317,
          Scripts = [[
PARA{
PlayAnimation{_delay{4.1},ActorId{790054},AnimationId{"Confident_Start"},Duration{1}},
PlayAnimation{_delay{11.1},ActorId{790054},AnimationId{"Confident_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "And that... I couldn't bear. So no — I won't back down, which means we'll probably keep clashing, again and again.",
          ToFinalCameraBlendTime = 20,
          TurnTo = {
            [1] = "790054:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E858"
        },
        [80200317] = {
          Camera = "-826.984375,564.034241,566.810547,0.00006,-22.002954,-35.181374,30.0,1155.509888,false,Manual,17.764473",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "<I>Hmpf...</> Avoir une petite sœur incapable de comprendre les inquiétudes de son aînée... Même si c’est à moi de m’excuser, je ne lui rendrai pas la tâche facile !",
          DialogueId = 80200317,
          FinalCamera = "-826.984375,564.034241,531.505859,0.000068,-22.202971,-35.380627,30.0,1155.509888,false,Manual,17.764473",
          GUID = "C8C5E882",
          NextDialogue = 80200318,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{5.1},ActorId{790054},AnimationId{"Talk01_End"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "That little sister of mine... never realises just how much I worry. Hmph. Even if I'm the one who has to apologise — I'm not making it easy on her!",
          TalkActionId = {
            [1] = "790054:Talk01_Start"
          },
          ToFinalCameraBlendTime = 40,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E882"
        },
        [80200318] = {
          ContentFR = "Mais elle refuse désormais de me voir. Alors je te confie ces petites « merveilles ». À toi de les lui offrir. Elle te fait confiance — elle ne se méfiera pas. Qui sait ? Peut-être hurlera-t-elle encore comme quand elle était enfant.",
          DialogueId = 80200318,
          FacialId = {
            [1] = "790054:Smile01"
          },
          GUID = "C8C5E8AC",
          NextOptions = {
            [1] = 80200319
          },
          Scripts = [[
PARA{
PlayAnimation{_delay{6.1},ActorId{790054},AnimationId{"Explain01_End"},Duration{1}},
PlayAnimation{_delay{9.1},ActorId{790054},AnimationId{"Angry01_Start"},Duration{1}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "She won't even let me near her right now. So, I'm counting on you to deliver these little \"sweethearts.\" She trusts you — won't suspect a thing. Might even shriek like she did as a child — wouldn't that be amusing?",
          TalkActionId = {
            [1] = "790054:Explain01_Start",
            [2] = "790008:Shy03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E8AC"
        },
        [80200319] = {
          ContentFR = "<I>Poulpes Shouxing...</>",
          DialogueId = 80200319,
          GUID = "C8C5E8D6",
          NextDialogue = 80200320,
          Subtitle = "Shouxing squid..."
        },
        [80200320] = {
          Camera = "-40.08873,-25.583652,132.830078,0.000071,0.997262,64.819328,40.0,103.979561,false,Manual,17.764473",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "C’est ta façon détournée de lui dire : « J’espère que tu vivras longtemps », n’est-ce pas ?",
          DialogueId = 80200320,
          Duration = 1,
          FinalCamera = "-44.77795,-23.377747,132.830078,0.000071,0.997262,64.819717,40.0,103.979561,false,Manual,17.764473",
          GUID = "C8C5E900",
          NextDialogue = 80200321,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.1},ActorId{790008},AnimationId{"Think_End"},Duration{1}},
PlayFacial{_delay{4.1},ActorId{790008},FacialId{"Smile02"}}
}]],
          SpeakNpcId = 790008,
          Subtitle = "This is actually your way of saying, \"May you live a long and healthy life,\" isn't it?",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E900"
        },
        [80200321] = {
          Camera = "-335.726562,-30.426773,87.43457,-0.299988,4.600269,5.00543,28.0,371.52066,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Euh... Chut. Dire ce genre de chose à voix haute enlève tout le charme. Et puis... j’avais envie de la voir se fâcher un peu.",
          DialogueId = 80200321,
          FinalCamera = "-376.866547,-34.026245,84.112305,-0.299988,4.600269,5.00543,28.0,383.921387,false,Manual,1.2",
          GUID = "C8C5E92A",
          LookAt = {
            [1] = "790054:n(790054)"
          },
          NextDialogue = 80200322,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.1},ActorId{790054},AnimationId{"Talk03_Start"},Duration{1}},
LookAt{_delay{6.1},LookAtDescription{"790054:n(790008)"}}
}]],
          SpeakNpcId = 790054,
          Subtitle = "Ehh—! Must you spoil it by putting it into words? Sentiments lose their charm once spelled out. I was hoping to see that flustered little face of hers!",
          TalkActionId = {
            [1] = "790054:Angry01_End"
          },
          ToFinalCameraBlendTime = 20,
          TurnTo = {
            [1] = "790054:p(70)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E92A"
        },
        [80200322] = {
          ContentFR = "Allez, va ! File !",
          DialogueId = 80200322,
          GUID = "C8C5E954",
          SpeakNpcId = 790054,
          Subtitle = "Now go on! Shoo, shoo!",
          TalkActionId = {
            [1] = "790008:AgreeHead",
            [2] = "790054:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E954"
        },
        [80200323] = {
          ContentFR = "Fin de l’illusion. Retour au point de collecte. Fushu est immobile.",
          DialogueId = 80200323,
          GUID = "C8C5E97E",
          Subtitle = "Exit the illusory realm. Return to Collection Site 1. Speak with Fushu.",
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E97E"
        },
        [80200324] = {
          Camera = "119.887146,130.070343,137.368652,0.000012,2.799851,-138.98819,45.0,175.296234,false,Manual,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Tu es {性别:réveillé|réveillée}.",
          DialogueId = 80200324,
          FacialId = {
            [1] = "790053:Shock01"
          },
          FinalCamera = "141.731094,149.066513,136.484863,0.000012,1.599883,-138.98819,45.0,202.350357,false,Manual,12.098981",
          GUID = "C8C5E9A8",
          NextDialogue = 80200325,
          SpeakNpcId = 790053,
          Subtitle = "Ah... you've come to!",
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          },
          ToFinalCameraBlendTime = 20,
          TurnTo = {
            [1] = "790008:n(790053)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E9A8"
        },
        [80200325] = {
          ContentFR = "À peine trois ou quatre minutes se sont écoulées... et pourtant, je n’ai pas cessé de m’inquiéter. J’en suis même venue à douter des écrits — la toxicité aurait-elle été plus forte que prévu ?",
          DialogueId = 80200325,
          FacialId = {
            [1] = "790053:Sad01"
          },
          GUID = "C8C5E9D2",
          NextDialogue = 80200326,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.1},ActorId{790053},AnimationId{"DisagreeHead"},Duration{1}},
PlayAnimation{_delay{3.1},ActorId{790053},AnimationId{"Think_Start"},Duration{1}},
PlayAnimation{_delay{7.1},ActorId{790053},AnimationId{"Think_End"},Duration{1}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "Only three or four minutes passed, yet I was already fretting... I even began to question the texts — could the toxin have been more potent than I thought?",
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E9D2"
        },
        [80200326] = {
          ContentFR = "J’ai hésité à recourir à l’Art de l’Éphémère... mais j’avais peur que tu ne sois déjà rétabli avant la fin du rituel.",
          DialogueId = 80200326,
          GUID = "C8C5E9FC",
          NextDialogue = 80200327,
          Scripts = "PlayAnimation{_delay{7.1},ActorId{790053},AnimationId{\"Explain01_End\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "I nearly invoked the Art of Ephemerality — but feared you'd recover before the spell was done...",
          TalkActionId = {
            [1] = "790053:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5E9FC"
        },
        [80200327] = {
          Camera = "30.172951,-5.828094,146.924805,0.000022,-4.600405,68.410217,45.0,131.244232,false,Manual,6.805237",
          ContentFR = "Ha ha... Vous vous ressemblez vraiment, toutes les deux.",
          DialogueId = 80200327,
          FacialId = {
            [1] = "790008:Smile02"
          },
          GUID = "C8C5EA26",
          NextDialogue = 80200328,
          SpeakNpcId = 790008,
          Subtitle = "Haha — you two really are twin sisters...",
          TalkActionId = {
            [1] = "790008:Laugh01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EA26"
        },
        [80200328] = {
          Camera = "141.731094,149.066513,136.484863,0.000012,1.599883,-138.98822,45.0,202.350357,false,Manual,6.805237",
          ContentFR = "... Tu as vu ma sœur ?",
          DialogueId = 80200328,
          FacialId = {
            [1] = "790053:Unacceptable01"
          },
          GUID = "C8C5EA50",
          NextDialogue = 80200329,
          SpeakNpcId = 790053,
          Subtitle = "You saw my sister...?",
          TalkActionId = {
            [1] = "790053:Shy02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EA50"
        },
        [80200329] = {
          Camera = "-15.628626,-121.557404,164.124023,0.000028,-8.000521,72.409447,45.0,254.346725,false,Manual,6.805237",
          ContentFR = "Oui. Vous vous êtes disputées. Et elle t’a offert ce que tu détestes le plus : des Poulpes Shouxing.",
          DialogueId = 80200329,
          GUID = "C8C5EA7A",
          NextDialogue = 80200330,
          SpeakNpcId = 790008,
          Subtitle = "I did. You two had a fight. Then she tried to make peace — with Shouxing Squid, of all things.",
          TalkActionId = {
            [1] = "790008:Talk01_Start",
            [2] = "790053:Shy02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EA7A"
        },
        [80200330] = {
          Camera = "95.230194,90.889275,139.040527,0.000013,1.999715,-138.388199,45.0,129.860046,false,Manual,6.805237",
          ContentFR = "... J’avais oublié. C’est une histoire d’il y a très, très longtemps.",
          DialogueId = 80200330,
          FacialId = {
            [1] = "790053:Sad03"
          },
          GUID = "C8C5EAA4",
          LookAt = {
            [1] = "790053:n(790053)"
          },
          NextDialogue = 80200331,
          Scripts = "PlayAnimation{_delay{2.1},ActorId{790053},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 790053,
          Subtitle = "...I'd forgotten. That was long, long ago.",
          TalkActionId = {
            [1] = "790053:DisagreeHead",
            [2] = "790008:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EAA4"
        },
        [80200331] = {
          Camera = "415.101501,-1311.599854,42.874023,0.000077,2.399227,107.206627,45.0,1317.139771,false,Manual,6.805237",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "As-tu accepté ses excuses ?",
          DialogueId = 80200331,
          FinalCamera = "448.243896,-1301.340576,42.874023,0.000077,2.399227,107.206627,45.0,1317.139771,false,Manual,6.805237",
          GUID = "C8C5EACE",
          NextDialogue = 80200332,
          SpeakNpcId = 790008,
          Subtitle = "Did you accept her apology?",
          TalkActionId = {
            [1] = "790008:Talk02_Start",
            [2] = "790053:Explain02_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EACE"
        },
        [80200332] = {
          ContentFR = "Eh bien... Non. Nous nous sommes encore disputées. Je ne regrette pas... mais...",
          DialogueId = 80200332,
          GUID = "C8C5EAF8",
          NextDialogue = 80200333,
          SpeakNpcId = 790053,
          Subtitle = "No... we argued once more. I do not regret my words — and yet...",
          TalkActionId = {
            [1] = "790008:Talk02_End",
            [2] = "790053:Sad02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EAF8"
        },
        [80200333] = {
          Camera = "106.505447,46.279133,180.103516,0.000015,-17.200472,-157.386368,45.0,118.629143,false,Manual,12.098981",
          ContentFR = "Peut-être qu’aujourd’hui... je pourrais accepter ce Poulpe Shouxing.",
          DialogueId = 80200333,
          FacialId = {
            [1] = "790053:SpecialSmile"
          },
          FinalCamera = "93.592377,40.89082,175.773438,0.000015,-17.200472,-157.386368,45.0,109.419518,false,Manual,12.098981",
          GUID = "C8C5EB22",
          NextDialogue = 80200334,
          SpeakNpcId = 790053,
          Subtitle = "Perhaps now, I might bring myself to accept the offering.",
          TalkActionId = {
            [1] = "790053:Sad02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EB22"
        },
        [80200334] = {
          ContentFR = "Seulement peut-être. Je n’ai jamais eu beaucoup d’affection pour les créatures aux multiples pattes, c’est indéniable.",
          DialogueId = 80200334,
          FacialId = {
            [1] = "790053:Pain01"
          },
          GUID = "C8C5EB4C",
          NextDialogue = 80200335,
          SpeakNpcId = 790053,
          Subtitle = "Only perhaps. My aversion to multi-legged creatures remains wholly undiminished.",
          TalkActionId = {
            [1] = "790053:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EB4C"
        },
        [80200335] = {
          Camera = "48.175987,-418.433289,149.098633,0.000042,-4.200382,92.013222,45.0,450.246735,false,Manual,12.098981",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Je n’aurais sans doute pas dû te laisser voir ces souvenirs. Les personnes du passé ne sont plus — les raviver ne fait que raviver la peine.",
          DialogueId = 80200335,
          FacialId = {
            [1] = "790008:Beg"
          },
          FinalCamera = "-69.18502,-422.553558,149.098633,0.000043,-3.200346,79.0131,45.0,450.246735,false,Manual,12.098981",
          GUID = "C8C5EB76",
          NextDialogue = 80200336,
          SpeakNpcId = 790053,
          Subtitle = "I shouldn't have let you glimpse such things. The past is long buried... to unearth it only invites old sorrow.",
          TalkActionId = {
            [1] = "790053:Sigh_End",
            [2] = "790008:Confident_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EB76"
        },
        [80200336] = {
          ContentFR = "Mais ce Pavillon... c’est ici que nous avons grandi. Il est probable que chaque brin d’Échorine conserve une part de notre histoire.",
          DialogueId = 80200336,
          GUID = "C8C5EBA0",
          NextDialogue = 80200337,
          SpeakNpcId = 790053,
          Subtitle = "But this place — the Hall of Ephemerality — was where we came of age. I suppose every blade of Echowort here bears a sliver of our story.",
          TurnTo = {
            [1] = "790053:p(70)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EBA0"
        },
        [80200337] = {
          Camera = "-23.33609,-427.601105,149.098633,0.00004,16.598991,57.414169,45.0,450.246735,false,Manual,12.098981",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "La prochaine fois... laisse-moi goûter à ta place. D’accord ?",
          DialogueId = 80200337,
          FinalCamera = "-23.33609,-427.601105,149.098633,0.000045,22.798664,61.012764,45.0,450.246735,false,Manual,12.098981",
          GUID = "C8C5EBCA",
          NextOptions = {
            [1] = 802003371,
            [2] = 802003372
          },
          SpeakNpcId = 790053,
          Subtitle = "So next time... allow me to be the one to taste it. Would you?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EBCA"
        },
        [80200339] = {
          ContentFR = "Merci.",
          DialogueId = 80200339,
          GUID = "C8C5EC1E",
          NextDialogue = 80200342,
          SpeakNpcId = 790053,
          Subtitle = "Thank you.",
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EC1E"
        },
        [80200341] = {
          ContentFR = "Hé hé... La prochaine fois, je te raconterai tout moi-même.",
          DialogueId = 80200341,
          GUID = "C8C5EC72",
          NextDialogue = 80200342,
          SpeakNpcId = 790053,
          Subtitle = "Hehe... Then next time we meet, I'll recount the whole tale myself.",
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EC72"
        },
        [80200342] = {
          ContentFR = "Bien. Allons au prochain endroit.",
          DialogueId = 80200342,
          GUID = "C8C5EC9C",
          SpeakNpcId = 790053,
          Subtitle = "Come — take this. Let's move on.",
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EC9C"
        },
        [80200343] = {
          ContentFR = "Transition — Abords du Pavillon de l’Éphémère",
          DialogueId = 80200343,
          GUID = "C8C5ECC6",
          Subtitle = "Scene Transition – Surrounding Wilds of the Hall of Ephemerality",
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5ECC6"
        },
        [80200344] = {
          Camera = "172.202026,4449.555664,2332.257812,0.00004,-26.399895,-95.595238,30.000002,4788.840332,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Trouvée.",
          DialogueId = 80200344,
          FinalCamera = "402.414307,4427.007812,2332.257812,0.00004,-26.399895,-95.595238,30.000002,4788.840332,false,Manual,1.2",
          GUID = "C8C5ECF0",
          NextDialogue = 80200345,
          SpeakNpcId = 790053,
          Subtitle = "Here's one.",
          ToFinalCameraBlendTime = 10,
          TurnTo = {
            [1] = "790008:n(790053)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5ECF0"
        },
        [80200345] = {
          ContentFR = "À ton avis... Échorine ou Rêvolis ?",
          DialogueId = 80200345,
          GUID = "C8C5ED1A",
          NextOptions = {
            [1] = 802003451,
            [2] = 802003452
          },
          SpeakNpcId = 790053,
          Subtitle = "Care to guess — is it Echowort, or Oneirowort?",
          TalkActionId = {
            [1] = "790008:Think_Start"
          },
          TurnTo = {
            [1] = "790053:n(790008)"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5ED1A"
        },
        [80200348] = {
          Camera = "-514.179199,-65.437241,130.561523,0.000188,1.6034,11.198832,50.000008,636.943848,false,Manual,3.221528",
          ContentFR = "À l’œil, la différence est infime... mais au toucher, on sent une nuance très subtile. Je pense que c’est bien la Rêvolis.",
          DialogueId = 80200348,
          FinalCamera = "-516.200806,-55.210449,130.561523,0.000188,1.6034,11.198832,50.000008,636.943848,false,Manual,3.221528",
          GUID = "C8C5ED98",
          NextDialogue = 80200349,
          Scripts = [[
PARA{
PlayAnimation{_delay{5.1},ActorId{790053},AnimationId{"Confident_End"},Duration{1}},
PlayAnimation{_delay{6.1},ActorId{790053},AnimationId{"Explain01_Start"},Duration{1}},
PlayAnimation{_delay{8.1},ActorId{790053},AnimationId{"Explain01_End"},Duration{1}}
}]],
          SpeakNpcId = 790053,
          Subtitle = "It appears nearly identical to what we found before — but in the hand, the texture feels subtly different. I believe this is Oneirowort.",
          TalkActionId = {
            [1] = "790053:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5ED98"
        },
        [80200349] = {
          Camera = "83.302071,146.197098,182.37207,0.000091,-11.599047,-118.401756,40.000011,172.35437,false,Manual,3.813417",
          ContentFR = "Si nous n’avions pas échoué deux fois auparavant, je n’aurais sans doute jamais remarqué cela.",
          DialogueId = 80200349,
          GUID = "C8C5EDC2",
          NextDialogue = 80200350,
          SpeakNpcId = 790053,
          Subtitle = "Had we not failed twice before, I might never have caught the difference.",
          TalkActionId = {
            [1] = "790053:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EDC2"
        },
        [80200350] = {
          Camera = "5.743984,121.353485,148.166016,0.000061,-2.198931,1.794543,40.000023,104.974152,false,Manual,8.259511",
          ContentFR = "Comment la première personne a-t-elle réussi à les distinguer ? Par essais successifs, comme nous ?",
          DialogueId = 80200350,
          GUID = "C8C5EDEC",
          NextDialogue = 80200351,
          Scripts = "PlayAnimation{_delay{5.1},ActorId{790008},AnimationId{\"Talk03_Start\"},Duration{1}}",
          SpeakNpcId = 790008,
          Subtitle = "How did the first person ever tell them apart? Trial and error, like us?",
          TalkActionId = {
            [1] = "790008:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EDEC"
        },
        [80200351] = {
          Camera = "30.070026,119.496765,121.788086,0.000079,14.400496,-100.208359,50.000011,123.697914,false,Manual,9.225292",
          ContentFR = "... Qui sait ?",
          DialogueId = 80200351,
          FacialId = {
            [1] = "790053:Think01"
          },
          GUID = "C8C5EE16",
          LookAt = {
            [1] = "790053:n(790053)"
          },
          NextDialogue = 80200352,
          Scripts = "PlayFacial{_delay{2.1},ActorId{790053},FacialId{\"Sad03\"}}",
          SpeakNpcId = 790053,
          Subtitle = "Heh... how did she do that, indeed?",
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EE16"
        },
        [80200352] = {
          Camera = "30.070026,119.496765,121.788086,0.000079,14.400496,-100.208359,50.000011,123.697914,false,Manual,9.225292",
          ContentFR = "Elle a sans doute affronté d’innombrables dangers, passé des nuits sans sommeil à étudier, incomprise, blessée parfois — mais sans jamais renoncer.",
          DialogueId = 80200352,
          FinalCamera = "30.070026,119.496765,135.290039,0.000068,30.998163,-82.200356,50.000008,3999.122314,false,Manual,9.225292",
          GUID = "C8C5EE40",
          LookAt = {
            [1] = "790053:p(BP_200401fushu)"
          },
          NextDialogue = 80200353,
          SpeakNpcId = 790053,
          Subtitle = "She must've endured countless perils, sleepless nights, tireless study... Misunderstood, perhaps even hurt — yet never once losing heart.",
          ToFinalCameraBlendTime = 32,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EE40"
        },
        [80200353] = {
          ContentFR = "Tout cela pour préserver un idéal ancien : soigner le monde, génération après génération.",
          DialogueId = 80200353,
          Duration = 2,
          GUID = "C8C5EE6A",
          NextDialogue = 80200354,
          SpeakNpcId = 790053,
          Subtitle = "All for the sake of an ancient vow — to mend, to soothe, to care — carried forward by healer after healer through the ages.",
          TalkActionId = {
            [1] = "790008:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EE6A"
        },
        [80200354] = {
          Camera = "-159.132416,-51.042709,147.863281,0.00019,-2.796628,27.59856,50.000011,312.992676,false,Manual,3.221528",
          ContentFR = "Au fait... Fufeng m’a dit que les Vrilles rampantes et les Fleurs-des-Fissures étaient plus adaptées pour les troubles du sommeil.",
          DialogueId = 80200354,
          FacialId = {
            [1] = "790008:Beg"
          },
          GUID = "C8C5EE94",
          LookAt = {
            [1] = "790053:n(790053)"
          },
          NextDialogue = 80200355,
          SpeakNpcId = 790008,
          Subtitle = "There's something I forgot to mention. Fufeng said Creeping Tendrils and Crackblooms work better for insomnia and restless sleep.",
          TalkActionId = {
            [1] = "790008:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EE94"
        },
        [80200355] = {
          ContentFR = "La Rêvolis aide à dormir, mais elle fait resurgir des souvenirs difficiles.",
          DialogueId = 80200355,
          GUID = "C8C5EEBE",
          NextDialogue = 80200356,
          Scripts = "PlayAnimation{_delay{2.1},ActorId{790008},AnimationId{\"DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 790008,
          Subtitle = "Oneirowort may help one sleep, but it also stirs old memories that weigh upon the heart.",
          TalkActionId = {
            [1] = "790008:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EEBE"
        },
        [80200356] = {
          Camera = "71.251167,76.700455,164.569336,0.000129,-5.199686,-133.204468,50.000011,99.112167,false,Manual,15.973291",
          ContentFR = "Donc je n’en ai plus vraiment besoin. Malgré tout... veux-tu encore essayer ?",
          DialogueId = 80200356,
          Duration = 1,
          FinalCamera = "66.068237,71.181648,163.882812,0.000129,-5.199686,-133.204468,50.000011,99.112167,false,Manual,15.973291",
          GUID = "C8C5EEE8",
          NextDialogue = 80200357,
          SpeakNpcId = 790008,
          Subtitle = "So I don't really need it anymore. But... do you still want to try it?",
          TalkActionId = {
            [1] = "790008:Shy03_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EEE8"
        },
        [80200357] = {
          ContentFR = "Fushu ne répond pas. Comme précédemment, elle porte la pointe de la feuille à ses lèvres. Cette fois, il n’y a ni tension, ni reproche. Seulement une respiration régulière... et un murmure, à peine audible, échappé d’un rêve.",
          DialogueId = 80200357,
          Duration = 2,
          GUID = "C8C5EF12",
          IsBlack = 1,
          NextDialogue = 80200358,
          Subtitle = "Fushu does not reply. As before, she places the grass blade upon her tongue. But this time, there is no tension, no reproach — only the rhythm of her breath, and a faint murmur from the depths of a dream.",
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EF12"
        },
        [80200358] = {
          Camera = "10.260178,29.508621,158.517578,0.00016,-13.799194,-104.60054,55.0,26.127415,false,Manual,15.973291",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "... La prochaine fois... choisis un cadeau d’excuses un peu plus approprié.",
          DialogueId = 80200358,
          FacialId = {
            [1] = "790053:Close"
          },
          FinalCamera = "13.641603,40.02512,158.702148,0.000164,-2.999177,-107.99968,55.000008,38.118717,false,Manual,15.973291",
          GUID = "C8C5EF3C",
          Scripts = "PlayFacial{_delay{1.5},ActorId{790053},FacialId{\"SpecialSmile\"}}",
          SpeakNpcId = 790053,
          Subtitle = "... Next time, pick a more fitting gift of apology, would you?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Fushu/004/C8C5EF3C"
        },
        [80210101] = {
          Camera = "805.707031,-8.211914,540.876953,0.0,0.0,-177.666962,25.0,125.0,false,DoNotOverride,2.8",
          ContentFR = "Les héros, dit-on, vivent pour régler haines et injustices. L’épée à la main, ils se plaisent à redresser les torts.",
          DialogueId = 80210101,
          FinalCamera = "506.652344,-9.29248,134.94043,0.0,-5.548217,-178.123627,25.0,125.0,false,DoNotOverride,2.8",
          GUID = "C8CC2DB2",
          NextDialogue = 80210102,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
          Subtitle = "A hero wanders with blades keen, hearts unbound, and rights the world's wrongs.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC2DB2"
        },
        [80210102] = {
          ContentFR = "Ils errent aux confins du monde, libres de toute attache. Celui qui doit rentrer chez lui à heure fixe, fût-il maître dans l’art du sabre, ressemble bien davantage à un garde d’escorte — et cela sonne infiniment moins héroïque.",
          DialogueId = 80210102,
          GUID = "C8CC2DDC",
          NextDialogue = 80210103,
          Subtitle = "The righteous roam free, untethered and unfettered. To keep a curfew is to be a guard, not a hero. For true grace lies not in the blade, but in the freedom it brings.",
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC2DDC"
        },
        [80210103] = {
          Camera = "506.652344,-9.29248,134.94043,0.0,-5.548217,-178.123627,25.0,125.0,false,DoNotOverride,2.8",
          ContentFR = "Tu pars.",
          DialogueId = 80210103,
          FacialId = {
            [1] = "790065:CM_Sad01",
            [2] = "790066:CM_Sad01"
          },
          GUID = "C8CC2E06",
          LookAt = {
            [1] = "790065:n(790066)"
          },
          NextDialogue = 80210104,
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundPriority{\"Invite\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
          SpeakNpcId = 790065,
          Subtitle = "So you're leaving.",
          TalkActionId = {
            [1] = "790067:ScratchHead_Start"
          },
          ToFinalCameraBlendTime = 5,
          TurnTo = {
            [1] = "790065:n(790066)"
          },
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC2E06"
        },
        [80210104] = {
          Camera = "390.390625,-180.267578,96.469727,0.000003,-1.798122,157.194687,30.0,337.309082,false,Manual,2.8",
          ContentFR = "Je pars.",
          DialogueId = 80210104,
          FinalCamera = "310.414062,-146.627441,93.75,0.000003,0.0,157.194702,30.0,323.332245,false,Manual,2.8",
          GUID = "C8CC2E30",
          NextDialogue = 80210105,
          SpeakNpcId = 790066,
          Subtitle = "So I am.",
          TalkActionId = {
            [1] = "790066:Talk03_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Kezhou/001/C8CC2E30"
        }
      }
    end
