        [90010101] = {
          ContentFR = "Allez... encore un coup... Pas question... de s’arrêter... pas encore !",
          DialogueId = 90010101,
          Duration = 3,
          GUID = "E154B232",
          SpeakNpcId = 900001,
          Subtitle = "Don't falter, keep hammering...",
          VoiceName = "voice/$Locale$/char/Bai/vo_forge_05"
        },
        [90010201] = {
          Camera = "192.657425,-208.698975,78.959908,0.000142,-5.798523,129.981186,35.0,250.0,false,DoNotOverride,2.8",
          ContentFR = "As-tu déniché quelque chose de précieux, dernièrement ? Montre-moi ça ! Qui sait... je pourrais peut-être en tirer une arme exceptionnelle !",
          DialogueId = 90010201,
          GUID = "E154C29A",
          SpeakNpcId = 900001,
          Subtitle = "Have you come across any treasures lately? Show me, and I might forge a truly extraordinary weapon out of it!",
          VoiceName = "voice/$Locale$/char/Bai/vo_forge_r02"
        },
        [90010301] = {
          Camera = "192.657425,-208.698975,78.959908,0.000142,-5.798523,129.981186,35.0,250.0,false,DoNotOverride,2.8",
          ContentFR = "C’est mon ami. Il a beau être petit, il est sacrément costaud — il attise le feu de la forge pour moi.",
          DialogueId = 90010301,
          GUID = "E154D302",
          SpeakNpcId = 900001,
          Subtitle = "That's my little friend. Tiny, but strong — it keeps the forge fire going."
        },
        [90020101] = {
          ContentFR = "<I>Bâille...</> Bonjour... Hein ? Ah, il est trop tard pour dire bonjour ? Euh... bonsoir, alors ?",
          DialogueId = 90020101,
          Duration = 3,
          GUID = "E15B1AD2",
          SpeakNpcId = 900002,
          Subtitle = "Good morning...",
          VoiceName = "voice/$Locale$/char/Bai/vo_shop_r03"
        },
        [90020201] = {
          ContentFR = "Hein ?! J-Je ne faisais pas la sieste... Hum hum ! Tu veux acheter quelque chose ?",
          DialogueId = 90020201,
          GUID = "E15B2B3A",
          SpeakNpcId = 900002,
          Subtitle = "Ah! I... I wasn't slacking off... Ahem! I mean, what can I get you?",
          TalkActionId = {
            [1] = "900002:Shangdian_Write_Start"
          },
          VoiceName = "voice/$Locale$/char/Bai/vo_shop_r01"
        },
        [90020301] = {
          ContentFR = "<I>Parlons d’autre chose.</>",
          DialogueId = 90020301,
          GUID = "E15B3BA2",
          Subtitle = "Let's talk about something else"
        },
        [90020302] = {
          ContentFR = "<I>À bientôt.</>",
          DialogueId = 90020302,
          GUID = "E15B3BCC",
          Subtitle = "Goodbye"
        },
        [90030000] = {
          ContentFR = "{性别:Il n’a jamais été fait pour vivre en cage. J’ai toujours su qu’un jour, il quitterait l’île pour s’envoler vers le ciel. Ce que je n’ai jamais su, c’est si ce serait une bénédiction… ou une malédiction, pour nous.|Elle n’a jamais été faite pour vivre en cage. J’ai toujours su qu’un jour, elle quitterait l’île pour s’envoler vers le ciel. Ce que je n’ai jamais su, c’est si ce serait une bénédiction… ou une malédiction, pour nous.}",
          DialogueId = 90030000,
          GUID = "E15B3BCB",
          SpeakNpcId = 81101,
          Subtitle = "{性别:He|She} was never meant to be caged. I always knew {性别:he|she} would someday leave the island to reach for the sky. What I couldn't tell was whether that would be a blessing or a curse for us.",
          VoiceName = "voice/$Locale$/char/Heitao/vo_idle"
        },
        [90030001] = {
          ContentFR = "Tu es de retour. Qu’est-ce que tu comptes faire aujourd’hui ? Te reposer à la maison, peut-être ?",
          DialogueId = 90030001,
          GUID = "E161730A",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextOptions = {
            [1] = 900300011,
            [2] = 900300013,
            [3] = 900300014,
            [4] = 900300015,
            [5] = 900300016,
            [6] = 900300018
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81101,
          Subtitle = "Welcome back. What are your plans for today? Or are you planning to rest at home?",
          TalkActionId = {
            [1] = "81101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_welcome",
          bForbidSkipOptions = true
        },
        [90030002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90030002,
          GUID = "90030002.0",
          NextDialogue = 90030001,
          Subtitle = "Let's talk about something else"
        },
        [90030003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90030003,
          GUID = "90030003.0",
          Subtitle = "Goodbye"
        },
        [90030101] = {
          ContentFR = "Un souhait ? Honnêtement... non, rien de particulier. Tant que je peux voir ton sourire chaque matin, ça me suffit.",
          DialogueId = 90030101,
          GUID = "E1618372",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030103,
          SpeakNpcId = 81101,
          Subtitle = "Wishes? I... can't think of any. Your smile in the morning is already the greatest pick-me-up of all.",
          TalkActionId = {
            [1] = "81101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_02_1"
        },
        [90030103] = {
          ContentFR = "Alors je te le promets, je vais tout faire pour que ça continue.",
          DialogueId = 90030103,
          GUID = "E16183C6",
          NextDialogue = 90030104,
          SpeakNpcId = 100001,
          Subtitle = "I promise I'll get you back.",
          TalkActionId = {
            [1] = "81101:Explain02_End"
          }
        },
        [90030104] = {
          ContentFR = "Mais ne te force pas. Si tu te sens mal, viens simplement me parler un moment. Ou si tu préfères garder le silence, on pourra rester là, ensemble, tranquillement.",
          DialogueId = 90030104,
          GUID = "E16183F0",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          Subtitle = "Don't push yourself. If you ever feel down, just come to me for a chat. Or, if you don't feel like talking, we can just spend some quiet time together.",
          TalkActionId = {
            [1] = "81101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90030301] = {
          ContentFR = "C’est pas comme sur l’Île du Purgatoire, ici il neige tous les jours. Mais heureusement, tu as un toit bien chaud. Comparé à notre vieille cabane sur l’île, ce logement, c’est presque du luxe.",
          DialogueId = 90030301,
          GUID = "E161A442",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030303,
          SpeakNpcId = 81101,
          Subtitle = "Unlike Purgatorio Island, it snows here every day. Thankfully, you have a warm place to stay. Compared to our little shack back on the island, this place feels quite luxurious.",
          TalkActionId = {
            [1] = "81101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_03_1"
        },
        [90030303] = {
          ContentFR = "Pourtant, j’ai toujours un peu froid.",
          DialogueId = 90030303,
          GUID = "E161A443",
          NextDialogue = 90030304,
          SpeakNpcId = 100001,
          Subtitle = "But I'm still a bit chilly.",
          TalkActionId = {
            [1] = "81101:Think_End"
          }
        },
        [90030304] = {
          ContentFR = "Je me souviens, en hiver, tes mains étaient toujours gelées… Viens, donne-moi tes mains, je vais te les réchauffer.",
          DialogueId = 90030304,
          GUID = "E161A46C",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          Subtitle = "Remember how your hands would always get very cold in winter? Here, let me warm them up.",
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90030401] = {
          ContentFR = "Ce que je fais ici... ? Je ne sais pas. Disons simplement que c’est un beau rêve, fais comme si j’étais encore à tes côtés, comme autrefois.",
          DialogueId = 90030401,
          GUID = "E161B4AA",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030403,
          SpeakNpcId = 81101,
          Subtitle = "...I'm not sure either. Maybe it's a beautiful dream where I've never left your side, as always.",
          TalkActionId = {
            [1] = "81101:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_01_1"
        },
        [90030403] = {
          ContentFR = "Je donnerais tout pour te revoir.",
          DialogueId = 90030403,
          GUID = "E161B4FE",
          NextDialogue = 90030404,
          SpeakNpcId = 100001,
          Subtitle = "I'd give anything to see you again.",
          TalkActionId = {
            [1] = "81101:Talk02_End"
          }
        },
        [90030404] = {
          ContentFR = "Oui, moi aussi… plus que tout. Puissions-nous un jour nous retrouver… pour de vrai.",
          DialogueId = 90030404,
          GUID = "E161B528",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          Subtitle = "I feel the same, very much so... May we truly reunite one day.",
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90030501] = {
          ContentFR = "Comment dire... C’est une ville de métal, froide et impitoyable... Non, en fait, c’est plutôt une prison. C’est là que j’ai passé mon enfance.",
          DialogueId = 90030501,
          GUID = "E161C512",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030503,
          SpeakNpcId = 81101,
          Subtitle = "Well, that place is like a city made of steel... Mm, more like a prison, to be precise. I spent my early years there.",
          TalkActionId = {
            [1] = "81101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_04_1"
        },
        [90030503] = {
          ContentFR = "Plus tard, quelqu’un m’a aidée à m’échapper. Elle nous a emmenés, toi et moi, sur l’Île du Purgatoire. Mais à propos d’elle... je ne peux rien dire de plus. Désolée, je lui ai promis de garder le secret.",
          DialogueId = 90030503,
          GUID = "E161C566",
          NextDialogue = 90030504,
          SpeakNpcId = 81101,
          Subtitle = "Later on, along with you, I was taken away from there by someone, and we ended up on Purgatorio Island. I can't share much about her, though — Sorry, I promised her.",
          TalkActionId = {
            [1] = "81101:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_04_2"
        },
        [90030504] = {
          ContentFR = "... Les jours passés sur l’Île du Purgatoire étaient si paisibles que j’ai cru qu’on pourrait y vivre toute notre vie. Jusqu’au jour où ils sont revenus. C’est là que j’ai compris que je n’avais jamais vraiment fui cette prison.",
          DialogueId = 90030504,
          GUID = "E161C590",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          Subtitle = "...Life on Purgatorio Island was so peaceful, that I almost believed we could live that way forever. But it wasn't until the day they came for me that I realised I had never truly escaped that prison.",
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90030601] = {
          ContentFR = "C’est un peu animé, oui... mais ça ne me dérange pas. Tu t’es fait plein de nouveaux amis, et c’est une bonne chose. Je suis vraiment contente pour toi.",
          DialogueId = 90030601,
          GUID = "E161D57A",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextDialogue = 90030603,
          SpeakNpcId = 81101,
          Subtitle = "It's somewhat noisy, but I don't hate it. You've made many new friends here, which is a good thing — I'm really happy for you.",
          TalkActionId = {
            [1] = "81101:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_05_1"
        },
        [90030603] = {
          ContentFR = "{性别:Comme ça, même si je ne suis pas là… tu ne te sentiras plus seul.|Comme ça, même si je ne suis pas là… tu ne te sentiras plus seule. }",
          DialogueId = 90030603,
          GUID = "E161D5A4",
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          Subtitle = "This way, you'll never feel lonely, even when I'm not around.",
          TalkActionId = {
            [1] = "81101:Sigh_End"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_05_2",
          bForbidSkipOptions = true
        },
        [90030801] = {
          ContentFR = "Alors repose-toi un peu, pose ta tête sur mes genoux... comme avant.",
          DialogueId = 90030801,
          GUID = "E161F64A",
          LookAt = {
            [1] = "81101:n(0)",
            [2] = "0:n(81101)"
          },
          NextOptions = {
            [1] = 90030002,
            [2] = 90030003
          },
          SpeakNpcId = 81101,
          Subtitle = "Then rest your head on my lap for a while, just like old times.",
          TalkActionId = {
            [1] = "81101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Heitao/vo_topic_06_1",
          bForbidSkipOptions = true
        },
        [90031001] = {
          ContentFR = "Mademoiselle Truffle, est-ce que je peux… toucher votre cochon ? Juste une fois, promis. Vous pourriez le tenir un peu, s’il vous plaît ? J’ai peur qu’il s’enfuie... Les petits animaux me fuient toujours.",
          DialogueId = 90031001,
          GUID = "E162171A",
          NextDialogue = 90031002,
          SpeakNpcId = 81101,
          Subtitle = "Miss Truffle, may I... pet your pig? Just one stroke will do. Please hold her still for me; I'm afraid she might run off... Little animals always seem to flee from me.",
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_02_1"
        },
        [90031002] = {
          ContentFR = "Merci... Ah... c’est tout chaud... et tout doux... C’est vraiment agréable...",
          DialogueId = 90031002,
          GUID = "E1621744",
          SpeakNpcId = 81101,
          Subtitle = "Thank you... Ah, it's so warm and soft. How nice...",
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_02_2"
        },
        [90031101] = {
          ContentFR = "Je ne suis pas le \"n° 0\" de la Légion. Et encore moins un jouet entre tes mains. Pars. Ou emmène mon cadavre, mais jamais je ne te suivrai vivante.",
          DialogueId = 90031101,
          GUID = "E1622782",
          SpeakNpcId = 81101,
          Subtitle = "I'm not that \"No.0\" from the Legion, nor am I your stooge. Leave, as I will never leave with you alive.",
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_03"
        },
        [90031201] = {
          ContentFR = "On dit que vous êtes un fin gourmet... Vous accepteriez de me montrer quelques-unes de vos recettes ? {nickname} ne tarit pas d’éloges sur votre cuisine et ça sonnait vrai, pas juste un compliment de courtoisie.",
          DialogueId = 90031201,
          GUID = "E16237EA",
          NextDialogue = 90031202,
          SpeakNpcId = 81101,
          Subtitle = "I heard you're quite the gourmet. Could you show me some of your recipes?  always raves about your cooking, and it was genuine, not just flattery.",
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_04_1"
        },
        [90031202] = {
          ContentFR = "...Vous n’utilisez pourtant que des ingrédients très simples ? Alors pourquoi... ? Quel est votre secret ?",
          DialogueId = 90031202,
          GUID = "E1623814",
          SpeakNpcId = 81101,
          Subtitle = "Wait, is that all? Then why... What's your secret?",
          VoiceName = "voice/$Locale$/char/Heitao/vo_companio_04_2"
        },
        [90040000] = {
          ContentFR = "Tu es là pour partager un doux instant à deux avec moi... J’ai hâte que ça commence.",
          DialogueId = 90040000,
          GUID = "E167DBA9",
          SpeakNpcId = 82101,
          Subtitle = "Are you staying here to spend some lovely time with me? I'm already looking forward to it.",
          VoiceName = "voice/$Locale$/char/Shuimu/vo_idle"
        },
        [90040001] = {
          ContentFR = "Je t’ai attendue ici depuis que je me suis réveillée. Mon venin est presque épuisé... C’est donc une bonne chose que tu sois venu. Je le sens à nouveau bouillonner dans mes veines. Peux-tu t’approcher un peu plus ?",
          DialogueId = 90040001,
          GUID = "E167DBAA",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextOptions = {
            [1] = 900400011,
            [2] = 900400012,
            [3] = 900400013,
            [4] = 900400014,
            [5] = 900400015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 82101,
          Subtitle = "I've been waiting here ever since I woke up. My venom has almost run dry... So, it's a good thing you came. I can feel it bubbling through my veins again. Can you come a little closer...?",
          TalkActionId = {
            [1] = "82101:Give"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90040002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90040002,
          GUID = "90040002.0",
          NextDialogue = 90040001,
          Subtitle = "Let's talk about something else"
        },
        [90040003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90040003,
          GUID = "90040003.0",
          Subtitle = "Goodbye"
        },
        [90040101] = {
          ContentFR = "Oui, j’adore la pluie. Dans les romans que j’ai lus, les rencontres amoureuses ont toujours lieu sous la pluie.",
          DialogueId = 90040101,
          GUID = "E167EC12",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040103,
          SpeakNpcId = 82101,
          Subtitle = "Yes, I love rainy days. They remind me of the love stories I've read, where romantic encounters always happen on a rainy day.",
          TalkActionId = {
            [1] = "82101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_01_1"
        },
        [90040103] = {
          ContentFR = "La pluie, c’est plutôt fait pour rester au lit, non ? Pourquoi y aurait-il des rencontres romantiques ?",
          DialogueId = 90040103,
          GUID = "E167EC13",
          NextDialogue = 90040104,
          SpeakNpcId = 100001,
          Subtitle = "Aren't rainy days more for sleeping in? Why would there be romantic encounters?",
          TalkActionId = {
            [1] = "82101:Explain02_End"
          }
        },
        [90040104] = {
          ContentFR = "As-tu déjà observé ceux qui se protègent de la pluie ? Sous l’auvent, ils se croisent, l’humidité exhale un parfum de verdure, et l’amour naît doucement...",
          DialogueId = 90040104,
          GUID = "E167EC3C",
          NextDialogue = 90040105,
          SpeakNpcId = 82101,
          Subtitle = "Have you ever observed those seeking shelter from the rain? They meet under eaves, the damp air enhancing the fragrance of greenery, love gently flowing with tentative advances...",
          TalkActionId = {
            [1] = "82101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_01_2"
        },
        [90040105] = {
          ContentFR = "Hihi... La prochaine fois qu’il pleuvra, viens donc te promener avec moi. Tu comprendras.",
          DialogueId = 90040105,
          GUID = "E167EC3B",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          Subtitle = "Hehe, join me next time it rains, and you'll see what I mean.",
          TalkActionId = {
            [1] = "82101:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90040201] = {
          ContentFR = "Ah, tu t'engages dans une conversation sur l'amour avec moi, comme c'est inattendu.",
          DialogueId = 90040201,
          GUID = "E167FC7A",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040203,
          SpeakNpcId = 82101,
          Subtitle = "Ah, you're initiating a conversation about love with me — how unexpected.",
          TalkActionId = {
            [1] = "82101:Shock_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_02_1"
        },
        [90040203] = {
          ContentFR = "Comment décrire ça ? C’est comme l’eau dans un parfum : elle embrasse chaque ingrédient, en absorbe l’essence, et crée un sillage qui dure longtemps...",
          DialogueId = 90040203,
          GUID = "E167FCA4",
          NextDialogue = 90040204,
          SpeakNpcId = 82101,
          Subtitle = "Hmm, how should I put it? ...It's like water in perfume, which kisses and embraces each ingredient, devours and absorbs their fragrance, and eventually blends with them to create a long-lasting aroma...",
          TalkActionId = {
            [1] = "82101:Shock_End"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_02_2"
        },
        [90040204] = {
          ContentFR = "Ça veut dire rester collés toute la journée ?",
          DialogueId = 90040204,
          GUID = "E167FCA5",
          NextDialogue = 90040205,
          SpeakNpcId = 100001,
          Subtitle = "You mean it's about cuddling up together every day?"
        },
        [90040205] = {
          ContentFR = "Il y a bien plus que cela. Ce que je veux, c’est un amour si profond que nous devenions véritablement inséparables... Et si l’un de nous devait disparaître, son corps nourrirait le jardin d’aromates, les fleurs qui y pousseraient deviendraient un parfum, pour flotter à jamais autour de l’autre...",
          DialogueId = 90040205,
          GUID = "E167FCA6",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          Subtitle = "There's much more to that. I seek a love so profound that we become truly inseparable... Even if life itself ends, one will become the mulch for the flowers in our garden; the blooms will turn into perfume, lingering around the other for eternity.",
          TalkActionId = {
            [1] = "82101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90040301] = {
          ContentFR = "Spéciale ? Oui... depuis que je suis petite, beaucoup m’ont traitée de \"monstre\".",
          DialogueId = 90040301,
          GUID = "E1680CE2",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040303,
          SpeakNpcId = 82101,
          Subtitle = "Special? Indeed... Many have seen me as a \"monster\" since I was young.",
          TalkActionId = {
            [1] = "82101:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_03_1"
        },
        [90040303] = {
          ContentFR = "Chaque fois, les expressions de dégoût sur leurs visages sont désagréables, il faudrait y remédier...",
          DialogueId = 90040303,
          GUID = "E1680D36",
          NextDialogue = 90040304,
          SpeakNpcId = 82101,
          Subtitle = "The looks of disgust on their faces aren't pleasant, which should be corrected...",
          TalkActionId = {
            [1] = "82101:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_03_2"
        },
        [90040304] = {
          ContentFR = "Peut-être qu’un peu de mon venin rendra leur expression moins dur... Hihi.",
          DialogueId = 90040304,
          GUID = "E1680D60",
          NextDialogue = 90040305,
          SpeakNpcId = 82101,
          Subtitle = "Perhaps a little sting of my toxin in their skin will soften those harsh looks... Hehe.",
          TalkActionId = {
            [1] = "82101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_03_3"
        },
        [90040305] = {
          ContentFR = "Dis-moi, quand tu dis \"spéciale\", tu veux dire spécial comme un monstre... ou plutôt spécialement envoûtante ?",
          DialogueId = 90040305,
          GUID = "E1680D8A",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          Subtitle = "So, when you say \"special\", do you mean special like a monster... or specially enchanting?",
          TalkActionId = {
            [1] = "82101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90040401] = {
          ContentFR = "Je vais très bien. Mon venin fait partie de moi, comme un cadeau du Dieu de l'Amour, il est inoffensif pour moi et m’aidera à trouver l’amour de ma vie.",
          DialogueId = 90040401,
          GUID = "E1681D4A",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040403,
          SpeakNpcId = 82101,
          Subtitle = "I'm perfectly fine. My venom is part of me, like a gift from the God of Love — it's harmless to me, and will help me find my destined lover.",
          TalkActionId = {
            [1] = "82101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_04_1"
        },
        [90040403] = {
          ContentFR = "On dirait que tu apprécies vraiment ce cadeau.",
          DialogueId = 90040403,
          GUID = "E1681D4B",
          NextDialogue = 90040404,
          SpeakNpcId = 100001,
          Subtitle = "Sounds like you really appreciate this gift."
        },
        [90040404] = {
          ContentFR = "Bien sûr. Même si cela me fait souvent passer pour un monstre, cela me distingue également des autres. Je pense que le partenaire destiné à un monstre doit être quelqu'un de très spécial, tu ne crois pas ?",
          DialogueId = 90040404,
          GUID = "E1681D74",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          Subtitle = "Of course. Though it often casts me as a monster, it also sets me apart. I believe that the destined lover meant for a monster must be quite special, don't you think?",
          TalkActionId = {
            [1] = "82101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90040501] = {
          ContentFR = "C’est mon parfum personnel : en notes de tête, une rencontre intense, en notes de cœur, des mots doux qui fixent le parfum, et en notes de fond, une amertume persistante.",
          DialogueId = 90040501,
          GUID = "E1682DB2",
          LookAt = {
            [1] = "82101:n(0)",
            [2] = "0:n(82101)"
          },
          NextDialogue = 90040503,
          SpeakNpcId = 82101,
          Subtitle = "It's my signature perfume, with top notes as intense as a first encounter, heart notes of sweet nothings that fix the scent, and a base note that lingers with a bittersweet aftertaste.",
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_05_1"
        },
        [90040503] = {
          ContentFR = "Qu’est-ce qu’il y a dedans, exactement ?",
          DialogueId = 90040503,
          GUID = "E1682E06",
          NextDialogue = 90040504,
          SpeakNpcId = 100001,
          Subtitle = "What exactly are the ingredients?"
        },
        [90040504] = {
          ContentFR = "C’est mon petit secret. Mais je serais ravie de te guider moi-même, pas à pas, tout au long du processus de fabrication.",
          DialogueId = 90040504,
          GUID = "E1682E30",
          NextOptions = {
            [1] = 90040002,
            [2] = 90040003
          },
          SpeakNpcId = 82101,
          Subtitle = "That's my little secret. However, I'd be delighted to guide you through the blending process myself, one step at a time.",
          TalkActionId = {
            [1] = "82101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Shuimu/vo_topic_05_2",
          bForbidSkipOptions = true
        },
        [90040601] = {
          ContentFR = "Ce parfum sec... c’est toi, hein ? Ça fait longtemps. Tu veux toujours m’embarquer ? Ça a l’air plutôt amusant... Après tout, même si je te donnais mille chances, je m’échapperais quand même de ton emprise... Tu ne crois pas, Mme la Geôlière ?",
          DialogueId = 90040601,
          GUID = "E1683E1A",
          SpeakNpcId = 82101,
          Subtitle = [[
That dry scent... Oh, it's you. Long time no see. Still planning to take me away in handcuffs? That sounds like a fun idea...
After all, even if I gave you a thousand chances, I would still escape from your grasp... Wouldn't you agree, Ms. Warden?]],
          VoiceName = "voice/$Locale$/char/Shuimu/vo_companio_01"
        },
        [90040701] = {
          ContentFR = "Tu as peur de moi ? Ne t’inquiète pas, je finirai par te faire m’aimer. Viens, sens ce parfum que j’ai créé. Il est très doux, et je suis sûre que tu ressentiras un bonheur que tu n’as jamais connu.",
          DialogueId = 90040701,
          GUID = "E1684E82",
          SpeakNpcId = 82101,
          Subtitle = "You're scared of me? Don't worry. I'll make you love me eventually. Come, have a whiff of the perfume I've blended. It smells very sweet, and I believe you'll love it.",
          VoiceName = "voice/$Locale$/char/Shuimu/vo_companio_02"
        },
        [90050000] = {
          ContentFR = "Hé ho, laisse-moi me battre avec toi. Je m’ennuie à mourir et mes tentacules ont besoin de s’étirer !",
          DialogueId = 90050000,
          GUID = "E16E4449",
          SpeakNpcId = 82301,
          Subtitle = "Heyyyy, lemme fight with you. I'm bored stiff and my tentacles need to stretch out!",
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_idle"
        },
        [90050001] = {
          ContentFR = "Hmm, c’est le moment parfait pour agir... Faut vite filer avant que... Waaah ! Depuis quand t’es là toi ?",
          DialogueId = 90050001,
          GUID = "E16E444A",
          LookAt = {
            [1] = "82301:n(0)",
            [2] = "0:n(82301)"
          },
          NextOptions = {
            [1] = 900500011,
            [2] = 900500012,
            [3] = 900500013,
            [4] = 900500014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 82301,
          Subtitle = "Now's the perfect timing. I should head out before... Huh?! When did you get here?",
          TalkActionId = {
            [1] = "82301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90050002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90050002,
          GUID = "90050002.0",
          NextDialogue = 90050001,
          Subtitle = "Let's talk about something else"
        },
        [90050003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90050003,
          GUID = "90050003.0",
          Subtitle = "Goodbye"
        },
        [90050101] = {
          ContentFR = "« Berry, je... »",
          DialogueId = 90050101,
          GUID = "E16E54B2",
          LookAt = {
            [1] = "82301:n(0)",
            [2] = "0:n(82301)"
          },
          NextDialogue = 90050103,
          SpeakNpcId = 82301,
          Subtitle = "\"Berry, I...\"",
          TalkActionId = {
            [1] = "82301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_01_1"
        },
        [90050103] = {
          ContentFR = "?",
          DialogueId = 90050103,
          GUID = "E16E5506",
          NextDialogue = 90050104,
          SpeakNpcId = 100001,
          Subtitle = "?"
        },
        [90050104] = {
          ContentFR = "« Ton sourire du matin me suffit pour bien commencer la journée. À partir d’aujourd’hui, je serai toujours là pour te protéger. » Hihi, j’imite bien ou pas ?",
          DialogueId = 90050104,
          GUID = "E16E5530",
          NextDialogue = 90050105,
          SpeakNpcId = 82301,
          Subtitle = "\"Your smile in the morning is already the greatest pick-me-up of all. From now on, I'll always be there to keep you safe.\" Hee hee, pretty convincing, isn't it?",
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_01_2"
        },
        [90050105] = {
          ContentFR = "Non ! Pas du tout ! Arrête de m’imiter !",
          DialogueId = 90050105,
          GUID = "E16E555A",
          NextDialogue = 90050106,
          SpeakNpcId = 100001,
          Subtitle = "No! Not even close! And stop mimicking us!",
          TalkActionId = {
            [1] = "82301:Explain02_End"
          }
        },
        [90050106] = {
          ContentFR = "Tu es en colère ? Hihihi, cette grimace sur ton visage me donne encore plus envie de t'imiter !",
          DialogueId = 90050106,
          GUID = "E16E5584",
          NextOptions = {
            [1] = 90050002,
            [2] = 90050003
          },
          SpeakNpcId = 82301,
          Subtitle = "Are you angry? Hehehe, that scowl on your face makes me want to mimic you even more!",
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90050201] = {
          ContentFR = "Facile ! Je peux changer d’apparence comme je veux ! Hihi, je peux prendre n’importe quelle forme, n’importe quelle couleur, et me fondre parfaitement dans n’importe quel environnement. Personne ne peut me repérer !",
          DialogueId = 90050201,
          GUID = "E16E651A",
          LookAt = {
            [1] = "82301:n(0)",
            [2] = "0:n(82301)"
          },
          NextDialogue = 90050203,
          SpeakNpcId = 82301,
          Subtitle = "Easy, I can change my look however I want! Hehe, I can take any shape, any colour, and blend in anywhere perfectly. No one can spot me!",
          TalkActionId = {
            [1] = "82301:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_02_1"
        },
        [90050203] = {
          ContentFR = "Une fois, je m’étais même changée en tonneau pour te faire peur... mais t’es même pas venu...",
          DialogueId = 90050203,
          GUID = "E16E6544",
          NextDialogue = 90050204,
          SpeakNpcId = 82301,
          Subtitle = "One time, I even turned into a barrel just to scare you, but you never came near...",
          TalkActionId = {
            [1] = "82301:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_02_2"
        },
        [90050204] = {
          ContentFR = "Eh bien, un tonneau qui apparaît en plein milieu de la pièce ? Fallait pas être devin...",
          DialogueId = 90050204,
          GUID = "E16E6546",
          NextDialogue = 90050205,
          SpeakNpcId = 100001,
          Subtitle = "Well, a random barrel popping up in the middle of a room? That's a bit of a giveaway..."
        },
        [90050205] = {
          ContentFR = "Hein ? Donc tu savais et t’as fait exprès de m’ignorer ! T’es trop {性别:méchant|méchante} !",
          DialogueId = 90050205,
          GUID = "E16E6545",
          NextOptions = {
            [1] = 90050002,
            [2] = 90050003
          },
          SpeakNpcId = 82301,
          Subtitle = "What?! Wait, so you knew it was me and just walked away? That's not cool!",
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90050301] = {
          ContentFR = "Hé ho ! Je ne suis pas comme ces voleurs pleins de mauvaises intentions, ok ?",
          DialogueId = 90050301,
          GUID = "E16E7582",
          LookAt = {
            [1] = "82301:n(0)",
            [2] = "0:n(82301)"
          },
          NextDialogue = 90050303,
          SpeakNpcId = 82301,
          Subtitle = "Hey! Don't lump me together with those baddies who steal from just anyone! I'm nothing like them!",
          TalkActionId = {
            [1] = "82301:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_03_1"
        },
        [90050303] = {
          ContentFR = "En quoi es-tu différente ?",
          DialogueId = 90050303,
          GUID = "E16E7584",
          NextDialogue = 90050304,
          SpeakNpcId = 100001,
          Subtitle = "How are you any different?",
          TalkActionId = {
            [1] = "82301:Talk01_End"
          }
        },
        [90050304] = {
          ContentFR = "Moi, je ne vole que les voleurs. Je me fonds dans la masse, je m’approche discrètement et je leur vole leurs trésors préférés directement dans leurs poches !",
          DialogueId = 90050304,
          GUID = "E16E7585",
          NextDialogue = 90050305,
          SpeakNpcId = 82301,
          Subtitle = "I only steal from thieves. I blend in, sneak up close, and pluck my favourite treasures right from their pockets!",
          TalkActionId = {
            [1] = "82301:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_03_2"
        },
        [90050305] = {
          ContentFR = "Quand ils pigent, c’est déjà trop tard ! Hihihi... C’est pour ça que je suis une justicière, pas une méchante !",
          DialogueId = 90050305,
          GUID = "E16E7583",
          NextOptions = {
            [1] = 90050002,
            [2] = 90050003
          },
          SpeakNpcId = 82301,
          Subtitle = "When they find out, their faces are priceless! Hehe... If anything, I'm more like a vigilante!",
          TalkActionId = {
            [1] = "82301:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90050401] = {
          ContentFR = "Bien sûr que non. Tu n’aimerais pas non plus que les gens te traitent de démon en fronçant les sourcils et en te regardant avec dégoût.",
          DialogueId = 90050401,
          GUID = "E16E85EA",
          LookAt = {
            [1] = "82301:n(0)",
            [2] = "0:n(82301)"
          },
          NextDialogue = 90050403,
          SpeakNpcId = 82301,
          Subtitle = "Of course not. You wouldn't like it either if people called you a \"demon\" with a frown and disgust.",
          TalkActionId = {
            [1] = "82301:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_04_1"
        },
        [90050403] = {
          ContentFR = "Alors pourquoi tu t’appelles \"Démon Tabethe, la Main Rouge\" ?",
          DialogueId = 90050403,
          GUID = "E16E85EC",
          NextDialogue = 90050404,
          SpeakNpcId = 100001,
          Subtitle = "Then why do you call yourself \"Demon Tabethe the Red Hand\"?",
          TalkActionId = {
            [1] = "82301:Talk03_End"
          }
        },
        [90050404] = {
          ContentFR = "C’est parce que je veux rendre le mot \"démon\" cool. Maintenant, la simple mention de mon titre \"Démon Tabethe la Main Rouge\" fait frissonner ces voleurs.",
          DialogueId = 90050404,
          GUID = "E16E85EB",
          NextDialogue = 90050405,
          SpeakNpcId = 82301,
          Subtitle = "That's because I want to make the word \"demon\" cool. Now, the mere mention of my title \"Demon Tabethe the Red Hand\" sends shivers down the spine of those thieves.",
          TalkActionId = {
            [1] = "82301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_04_2"
        },
        [90050405] = {
          ContentFR = "Un jour, quand on entendra \"démon\", on pensera juste à moi, la plus cool de toutes ! C’est pas un rêve génial, ça ?",
          DialogueId = 90050405,
          GUID = "E16E85ED",
          NextOptions = {
            [1] = 90050002,
            [2] = 90050003
          },
          SpeakNpcId = 82301,
          Subtitle = "And one day, the word \"demon\" will only make people think how awesome I am. That'll be pretty cool, don't you think?",
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90050501] = {
          ContentFR = "Hein ? Tu veux m’attraper ? Mais je suis gentille, moi ! J’ai juste piqué un truc à un autre voleur... Hé, t’approche pas ! Aïe ! Ça brûle !",
          DialogueId = 90050501,
          GUID = "E16E9652",
          SpeakNpcId = 82301,
          Subtitle = "You wanna catch me? Why? I'm not a bad girl! I only steal from other thieves. It's no big deal... Hey, stay away from me! Ow! That burnt!",
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_companio_01"
        },
        [90050601] = {
          ContentFR = "C’est pour moi ? Hmm... t’as une tête louche, toi... Oh non, ce parfum... j’ai la tête qui tourne, et mes tentacules picotent ! T’es vraiment trop suspecte !",
          DialogueId = 90050601,
          GUID = "E16EA6BA",
          SpeakNpcId = 82301,
          Subtitle = "This is for me? Hmm, but you look pretty dangerous, so you'd better keep it. Wait... this scent is making me feel light-headed... My tentacles are going numb... You really are dangerous!",
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_companio_02"
        },
        [90050701] = {
          ContentFR = "T’es trop marrante quand tu parles à ton épée ! « Samaël, tu aimes cet endroit ? Allons explorer encore plein d’autres lieux ! » ... Pourquoi tu fais cette tête ? Hihi, encore plus drôle comme ça !",
          DialogueId = 90050701,
          GUID = "E16EB722",
          SpeakNpcId = 82301,
          Subtitle = [[
I love the way you talk to your sword! "Samael, do you like this place? Let's explore more places together!"
Hey, what's up with you, getting all riled up? Haha, you're a proper laugh!]],
          VoiceName = "voice/$Locale$/char/Zhangyu/vo_companio_03"
        },
        [90060000] = {
          ContentFR = "Quelle sérénité... Tu ne crains donc pas mes flammes ? Hmpf, pauvre insecte. Tu regretteras ton ignorance quand je t’écraserai.",
          DialogueId = 90060000,
          GUID = "E174ACE9",
          SpeakNpcId = 83201,
          Subtitle = "What a blissful sight... Aren't you afraid of my fire, insect? Hmph, you'll regret your ignorance when I stomp you into the dirt.",
          VoiceName = "voice/$Locale$/char/Haier/vo_idle"
        },
        [90060001] = {
          ContentFR = "{性别:Prêt|Prête} pour l’interrogatoire du jour ?",
          DialogueId = 90060001,
          GUID = "E174ACEA",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextOptions = {
            [1] = 900600011,
            [2] = 900600012,
            [3] = 900600013,
            [4] = 900600014,
            [5] = 900600015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83201,
          Subtitle = "Ready for the interrogation?",
          TalkActionId = {
            [1] = "83201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_welcome",
          bForbidSkipOptions = true
        },
        [90060002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90060002,
          GUID = "90060002.0",
          NextDialogue = 90060001,
          Subtitle = "Let's talk about something else"
        },
        [90060003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90060003,
          GUID = "90060003.0",
          Subtitle = "Goodbye"
        },
        [90060101] = {
          ContentFR = "Si tu avais étudié l’histoire, tu saurais que la toute première geôlière de la Prison Militaire Royale avait la peau rouge, comme de la lave en fusion. Même les criminels les plus endurcis redoutaient ses interrogatoires.",
          DialogueId = 90060101,
          GUID = "E174BD52",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060102,
          SpeakNpcId = 83201,
          Subtitle = "If you learned about history, you'd know that the first warden of the Royal Military Prison had skin like molten lava. Even the most ruthless criminals feared her interrogations.",
          TalkActionId = {
            [1] = "83201:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_1"
        },
        [90060102] = {
          ContentFR = "En tant que sa descendante, je porte fièrement son nom, prête à incinérer tous les péchés avec mon feu.",
          DialogueId = 90060102,
          GUID = "E174BD53",
          NextDialogue = 90060103,
          SpeakNpcId = 83201,
          Subtitle = "As her descendant, I proudly bear her name, ready to incinerate all sins with my fire.",
          TalkActionId = {
            [1] = "83201:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_2"
        },
        [90060103] = {
          ContentFR = "Votre peau... aussi brûlante, ça ne rend pas la vie difficile ?",
          DialogueId = 90060103,
          GUID = "E174BD54",
          NextDialogue = 90060104,
          SpeakNpcId = 100001,
          Subtitle = "Then... does your scorching skin make everyday life difficult?"
        },
        [90060104] = {
          ContentFR = "Cela pose certes quelques difficultés : je ne peux dormir que sur des lits en fer et je ne peux pas rester longtemps dans des structures en bois. Cependant, cela me permet de sauver des criminels de bâtiments en feu et de rendre justice. Et le froid ne me dérange jamais.",
          DialogueId = 90060104,
          GUID = "E174BD55",
          NextDialogue = 90060105,
          SpeakNpcId = 83201,
          Subtitle = "It does pose some challenges — I can only sleep on iron beds and can't linger in wooden structures for long. However, it allows me to pull criminals from burning buildings and administer justice. And the cold never bothers me.",
          TalkActionId = {
            [1] = "83201:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_3"
        },
        [90060105] = {
          ContentFR = "Mon apparence inhabituelle, je la vois plutôt comme un don. S’il faut vraiment lui trouver un inconvénient... j’ai toujours voulu goûter une glace, mais elle fond avant même que je puisse en prendre une bouchée.",
          DialogueId = 90060105,
          GUID = "E174BD56",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          Subtitle = "My unusual appearance is more of a gift. If there's any downside... I've always wanted to try ice cream, but it melts in my hand before I can taste it...",
          TalkActionId = {
            [1] = "83201:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90060201] = {
          ContentFR = "Depuis la création de l'Empire, ma famille veille sur les pires détenus, rendant justice et supprimant les dangers.",
          DialogueId = 90060201,
          GUID = "E174CDBA",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060202,
          SpeakNpcId = 83201,
          Subtitle = "Since the Empire's inception, my family has managed the prison that holds the most heinous criminals, correcting wrongs and neutralising threats.",
          TalkActionId = {
            [1] = "83201:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_02_1"
        },
        [90060202] = {
          ContentFR = "Ma peau rouge comme le feu, héritée de mes ancêtres, m’a destinée à porter ce titre. Ce n’est pas moi qui ai choisi, c’est le rôle qui m’a choisie.",
          DialogueId = 90060202,
          GUID = "E174CDBB",
          NextDialogue = 90060203,
          SpeakNpcId = 83201,
          Subtitle = "My fiery red skin, a legacy from the first warden, predestined me to continue enforcing the iron-clad code she established. So it wasn't me who chose to become a warden; it was the mantle of warden that chose me.",
          TalkActionId = {
            [1] = "83201:Angry01_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_02_2"
        },
        [90060203] = {
          ContentFR = "Cela signifie-t-il que vous avez déjà réalisé vos ambitions ?",
          DialogueId = 90060203,
          GUID = "E174CDBC",
          NextDialogue = 90060204,
          SpeakNpcId = 100001,
          Subtitle = "Does that mean you've already achieved your aspirations?"
        },
        [90060204] = {
          ContentFR = "Être geôlière n’est pas un accomplissement, mais le commencement. Je resterai sur le qui-vive, traquant chaque injustice jusqu’à ce que la mort m’emporte.",
          DialogueId = 90060204,
          GUID = "E174CDBD",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          Subtitle = "Becoming a warden is merely the beginning. It compels me to remain vigilant, eradicating any injustice within the Empire until my final breath.",
          TalkActionId = {
            [1] = "83201:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90060301] = {
          ContentFR = "Certainement. La prison impériale regorge de criminels perfides. Mes fonctions consistent à mener des interrogatoires, examiner des dossiers et déjouer les tentatives d’évasion.",
          DialogueId = 90060301,
          GUID = "E174DE22",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060302,
          SpeakNpcId = 83201,
          Subtitle = "Certainly. The Imperial Prison is teeming with devious criminals. My duties include conducting interrogations, reviewing case files, and thwarting escape attempts.",
          TalkActionId = {
            [1] = "83201:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_03_1"
        },
        [90060302] = {
          ContentFR = "Le moindre moment de pause retarde la justice. Et quand la justice tarde, c’est le chaos et la loi du plus fort qui règnent.",
          DialogueId = 90060302,
          GUID = "E174DE23",
          NextDialogue = 90060303,
          SpeakNpcId = 83201,
          Subtitle = "Every minute of rest delays justice a bit, and when justice is delayed, chaos and the law of the jungle take over.",
          TalkActionId = {
            [1] = "83201:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_03_2"
        },
        [90060303] = {
          ContentFR = "Votre travail serait-il plus facile s’il y avait moins de prisonniers ?",
          DialogueId = 90060303,
          GUID = "E174DE24",
          NextDialogue = 90060304,
          SpeakNpcId = 100001,
          Subtitle = "Would your job be easier if there were fewer prisoners?"
        },
        [90060304] = {
          ContentFR = "Certains chercheurs ont imaginé un monde sans crime. Si un tel jour venait à arriver, ma raison d'être disparaîtrait, car le mal nécessite l’existence d’une geôlière. D’ici là, je m’engage à maintenir l’ordre.",
          DialogueId = 90060304,
          GUID = "E174DE25",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          Subtitle = "Some scholars have envisioned a crime-free world. Should such a day come, my purpose would vanish, for evil necessitates a warden's existence. Until then, I am committed to upholding order.",
          TalkActionId = {
            [1] = "83201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90060401] = {
          ContentFR = "La justice ? C’est dompter le désir par le pouvoir, enchaîner le mal par la force, et châtier les coupables par les puissants.",
          DialogueId = 90060401,
          GUID = "E174EE8A",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060402,
          SpeakNpcId = 83201,
          Subtitle = "Justice? It is the restraint of desire through power, the suppression of evil through strength, and the punishment of the wicked by the mighty.",
          TalkActionId = {
            [1] = "83201:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_04_1"
        },
        [90060402] = {
          ContentFR = "Ce n’est pas un peu trop tranché comme vision ?",
          DialogueId = 90060402,
          GUID = "E174EE8B",
          NextDialogue = 90060403,
          SpeakNpcId = 100001,
          Subtitle = "Isn't that a bit \"painting with a broad brush\"?",
          TalkActionId = {
            [1] = "83201:Explain01_End"
          }
        },
        [90060403] = {
          ContentFR = "Hmpf, tranché ? Je ne m’attendrais pas à ce {性别:qu’un enfant naïf|qu’une enfant naïve} comprenne. Nous ne vivons pas dans une utopie où les gens se tiennent simplement la main et s’aiment les uns les autres. Ce n'est que par le pouvoir absolu et l’ordre que la véritable justice peut être garantie !",
          DialogueId = 90060403,
          GUID = "E174EE8C",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          Subtitle = "Hmph, broad? I wouldn't expect a naive child to understand. We don't live in a utopia where people simply hold hands and love each other. Only through absolute power and order can true justice be secured!",
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90060501] = {
          ContentFR = "Avec des criminels partout dans les rues de l’Empire, une geôlière n’a pas de loisirs. Je profite juste de quelques verres quand je peux.",
          DialogueId = 90060501,
          GUID = "E174FEF2",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060502,
          SpeakNpcId = 83201,
          Subtitle = "With criminals still roaming the streets of the Empire, spare time is a luxury for a warden. The only respite I get is when I sneak in a few strong drinks amidst a busy schedule.",
          TalkActionId = {
            [1] = "83201:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_05_1"
        },
        [90060502] = {
          ContentFR = "Quoi ?! Vous buvez ?",
          DialogueId = 90060502,
          GUID = "E174FF1C",
          LookAt = {
            [1] = "83201:n(0)",
            [2] = "0:n(83201)"
          },
          NextDialogue = 90060503,
          SpeakNpcId = 100001,
          Subtitle = "What!? You drink!?",
          TalkActionId = {
            [1] = "83201:Talk01_End"
          }
        },
        [90060503] = {
          ContentFR = "Ça te surprend ? Ce n’est qu’un passe-temps. Pendant les interrogatoires, j’entends constamment parler de toutes sortes d’alcools, ce qui m’a rendue curieuse au sujet de cette soi-disant potion maléfique souvent liée au crime. Alors j’en bois à l’occasion.",
          DialogueId = 90060503,
          GUID = "E174FF1D",
          NextDialogue = 90060504,
          SpeakNpcId = 83201,
          Subtitle = "Why so surprised? It's merely a diversion. During interrogations, I always hear about various kinds of alcohol, which made me curious about this so-called wicked potion that seems to be associated with crime. So I drink once in a while.",
          TalkActionId = {
            [1] = "83201:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_05_2"
        },
        [90060504] = {
          ContentFR = "Et plus j’en bois, plus je suis convaincue que le mal ne vient pas de l’alcool lui-même.",
          DialogueId = 90060504,
          GUID = "E174FF1E",
          NextOptions = {
            [1] = 90060002,
            [2] = 90060003
          },
          SpeakNpcId = 83201,
          Subtitle = "And the more I drink, the more I'm convinced that it's not the drink that is wicked.",
          TalkActionId = {
            [1] = "83201:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Haier/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90060601] = {
          ContentFR = "Moi, geôlière. Vous, commandante de la Légion. Deux visages d’un même ordre implacable. Que l’on nous craigne ou nous haïsse, tant que l’Empire vit, cela n’a aucune importance.",
          DialogueId = 90060601,
          GUID = "E1750F5A",
          SpeakNpcId = 83201,
          Subtitle = "I'm the warden and you're the Legion's chief. Together, we're the merciless keepers of the dark order that is the Empire. Their hatred of us means nothing, as long as we serve Hyperborea!",
          VoiceName = "voice/$Locale$/char/Haier/vo_companio_01"
        },
        [90060701] = {
          ContentFR = "Tiens, encore toi.",
          DialogueId = 90060701,
          GUID = "E1751FC2",
          SpeakNpcId = 83201,
          Subtitle = "We meet again.",
          VoiceName = "voice/$Locale$/char/Haier/vo_companio_02"
        },
        [90060801] = {
          ContentFR = "Tss, l’adjoint de Sibylle... Celui qu’on accuse sans cesse d’incompétence, pas vrai ? Je vois clair dans ton petit jeu : tu caches tes talents et ton ambition pour rester dans son ombre. Dis-moi, qu’est-ce que tu mijotes ?",
          DialogueId = 90060801,
          GUID = "E175302A",
          SpeakNpcId = 83201,
          Subtitle = "Tsk, you're Sibylle's adjutant... the one who's always being accused of failing your duties, huh? I can tell that you're hiding your prowess and ambition just so you can stand alongside Sibylle. So what are your ulterior motives.",
          VoiceName = "voice/$Locale$/char/Haier/vo_companio_03"
        },
        [90070000] = {
          ContentFR = "Une journée sans incident est une bonne journée.",
          DialogueId = 90070000,
          GUID = "E17B1589",
          SpeakNpcId = 84201,
          Subtitle = "An uneventful day is a good day.",
          VoiceName = "voice/$Locale$/char/Yuming/vo_idle"
        },
        [90070001] = {
          ContentFR = "Profite de ta liberté, tant que la loi ne t’a pas encore enchaîné.",
          DialogueId = 90070001,
          GUID = "E17B158A",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextOptions = {
            [1] = 900700011,
            [2] = 900700012,
            [3] = 900700013,
            [4] = 900700014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84201,
          Subtitle = "Do what you need to. Cherish your freedom before the chains of law bind you.",
          TalkActionId = {
            [1] = "84201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_welcome",
          bForbidSkipOptions = true
        },
        [90070002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90070002,
          GUID = "90070002.0",
          NextDialogue = 90070001,
          Subtitle = "Let's talk about something else"
        },
        [90070003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90070003,
          GUID = "90070003.0",
          Subtitle = "Goodbye"
        },
        [90070101] = {
          ContentFR = "... Pour ce genre de bavardages, il y a sûrement de meilleures personnes. Va discuter avec les marchands itinérants, ou ouvre un livre.",
          DialogueId = 90070101,
          GUID = "E17B25F2",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070102,
          SpeakNpcId = 84201,
          Subtitle = "...Go read a tome or seek another's company for such trivial discourse. Perhaps the Starweavers peddling their crafts would indulge your curiosity.",
          TalkActionId = {
            [1] = "84201:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_01_1"
        },
        [90070102] = {
          ContentFR = "Chacun a son regard sur le monde. Je veux connaître le tien.",
          DialogueId = 90070102,
          GUID = "E17B25F3",
          NextDialogue = 90070103,
          SpeakNpcId = 100001,
          Subtitle = "Everyone looks at the world differently. I'm asking about your views.",
          TalkActionId = {
            [1] = "84201:Talk03_End"
          }
        },
        [90070103] = {
          ContentFR = "Ma vision est obscurcie par mes devoirs. Si tu veux comprendre Huaxu, il te faudra t’y rendre toi-même.",
          DialogueId = 90070103,
          GUID = "E17B25F4",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          Subtitle = "I am often preoccupied, and my perspectives are notably skewed. Should your curiosity truly beckon, a visit thither would enlighten you far beyond any second-hand account.",
          TalkActionId = {
            [1] = "84201:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90070201] = {
          ContentFR = "Les Neuf Chapitres de Dafeng sont les lois absolues de Huaxu, que nul ne peut enfreindre. Pourtant, si un jour quelqu’un devait défier le destin, il reviendrait à certains de contenir ce chaos.",
          DialogueId = 90070201,
          GUID = "E17B365A",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070202,
          SpeakNpcId = 84201,
          Subtitle = "The Nine Chapters are the sacred laws of Huaxu, brooking no defiance. Should anyone dare to challenge divine decree, it falls upon some to quell the ensuing turmoil.",
          TalkActionId = {
            [1] = "84201:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_02_1"
        },
        [90070202] = {
          ContentFR = "Tu dois être très respecté, alors.",
          DialogueId = 90070202,
          GUID = "E17B365B",
          NextDialogue = 90070203,
          SpeakNpcId = 100001,
          Subtitle = "Does that make you a respected senior official then?",
          TalkActionId = {
            [1] = "84201:Explain01_End"
          }
        },
        [90070203] = {
          ContentFR = "... Peut-être bien. Je ne m’attarde guère en discussions futiles. Chaque fois que j’interviens, il y a des blessés, parfois des morts. Ainsi, la majorité des habitants de Huaxu ne se réjouissent pas de ma présence.",
          DialogueId = 90070203,
          GUID = "E17B365C",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          Subtitle = "...Perhaps in title. I seldom consort with the commoners. My presence, necessary as it may be for law's enforcement, often brings collateral grief. Few in Huaxu would greet me with joy.",
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90070301] = {
          ContentFR = "Rien ne mérite d’être célébré. C’est ainsi.",
          DialogueId = 90070301,
          GUID = "E17B46C2",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070302,
          SpeakNpcId = 84201,
          Subtitle = "There is nought to celebrate. That is the entirety of the matter.",
          TalkActionId = {
            [1] = "84201:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_03_1"
        },
        [90070302] = {
          ContentFR = "Tu pourrais essayer d’en parler, tu sais.",
          DialogueId = 90070302,
          GUID = "E17B46C3",
          NextDialogue = 90070303,
          SpeakNpcId = 100001,
          Subtitle = "Maybe you can try sharing your troubles with me."
        },
        [90070303] = {
          ContentFR = "Je te remercie de ta sollicitude, mais je ne voudrais pas accabler quelqu'un d’autre avec mes malheurs. Ce n’est pas nécessaire.",
          DialogueId = 90070303,
          GUID = "E17B46C4",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          Subtitle = "Your concern is appreciated, yet I would not burden another soul with my woes. It is unnecessary.",
          TalkActionId = {
            [1] = "84201:Agree"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90070401] = {
          ContentFR = "Oui. La lune est pure. Elle efface les souillures du jour, même les plus sanglantes. À travers les âges, son croissant veille silencieusement depuis son promontoire céleste.",
          DialogueId = 90070401,
          GUID = "E17B572A",
          LookAt = {
            [1] = "84201:n(0)",
            [2] = "0:n(84201)"
          },
          NextDialogue = 90070402,
          SpeakNpcId = 84201,
          Subtitle = "Indeed. The moon, a celestial marvel, purifies the remnants of the day, be it festivity or foul deed. Through the ages, the crescent merely watches from its lofty perch.",
          TalkActionId = {
            [1] = "84201:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_04_1"
        },
        [90070402] = {
          ContentFR = "Tu penses au passé ?",
          DialogueId = 90070402,
          GUID = "E17B572B",
          NextDialogue = 90070403,
          SpeakNpcId = 100001,
          Subtitle = "Are you thinking about the past?",
          TalkActionId = {
            [1] = "84201:Talk02_End"
          }
        },
        [90070403] = {
          ContentFR = "Non, j’ai fait mes adieux au passé. Ce soir, je me suis simplement permis un demi-verre de vin en plus.",
          DialogueId = 90070403,
          GUID = "E17B572C",
          NextOptions = {
            [1] = 90070002,
            [2] = 90070003
          },
          SpeakNpcId = 84201,
          Subtitle = "No, I am one who has bid farewell to the past. Tonight, I simply indulged in an extra half cup of wine.",
          VoiceName = "voice/$Locale$/char/Yuming/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90070501] = {
          ContentFR = "Je ne connais pas le passé que tu as laissé derrière toi, mais nos esprits se ressemblent. Garde tes distances, je n’apprécie guère les semblables.",
          DialogueId = 90070501,
          GUID = "E17B6792",
          SpeakNpcId = 84201,
          Subtitle = "I know not of the history you've forsaken, but our scents are alike. Keep your distance - I find little comfort in my own kind.",
          VoiceName = "voice/$Locale$/char/Yuming/vo_companio_01"
        },
        [90070601] = {
          ContentFR = "Nous ne sommes plus les camarades d’autrefois. Comme le vent qui passe, les gens vont et viennent. Mieux vaut laisser le passé derrière soi.",
          DialogueId = 90070601,
          GUID = "E17B77FA",
          SpeakNpcId = 84201,
          Subtitle = "We are no longer comrades of old. Like the fleeting wind, people drift by. Best leave yesteryear behind.",
          VoiceName = "voice/$Locale$/char/Yuming/vo_companio_02"
        },
        [90070701] = {
          ContentFR = "Ta détermination et ton respect des règles m’impressionnent. As-tu déjà été assailli par le doute ?",
          DialogueId = 90070701,
          GUID = "E17B8862",
          SpeakNpcId = 84201,
          Subtitle = "Your resolve and adherence to law command my respect. Do moments of doubt ever cloud your certitude?",
          VoiceName = "voice/$Locale$/char/Yuming/vo_companio_03"
        },
        [90080000] = {
          ContentFR = "Hum... Ce fusil pliant semi-automatique pourrait être amélioré... Plus de puissance de feu, et on pourrait finir les missions encore plus vite, pour rentrer plus tôt.",
          DialogueId = 90080000,
          GUID = "E1817E29",
          SpeakNpcId = 84202,
          Subtitle = "Hmm... This sneak folding shotgun could use an auto-fire upgrade, and if I give it more firepower... Then, we can take out our enemies even faster on our next mission and head home early.",
          VoiceName = "voice/$Locale$/char/Landi/vo_idle"
        },
        [90080001] = {
          ContentFR = "Ahh... Cette sensation après un bon réveil, c’est le pied. Écoute, {性别:mec|l’amie}, faut pas être tendu tout le temps. Ta liste de trucs à faire sera jamais finie. Faut savoir se détendre, c’est pas un luxe, c’est vital.",
          DialogueId = 90080001,
          GUID = "E1817E2A",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextOptions = {
            [1] = 900800011,
            [2] = 900800012,
            [3] = 900800013,
            [4] = 900800014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84202,
          Subtitle = "Ahh... I feel so fresh after just waking up. Listen, buddy, there's no point in working all day. Your to-do list will never end. Remember, relaxation is a necessity, not a luxury.",
          VoiceName = "voice/$Locale$/char/Landi/vo_welcome",
          bForbidSkipOptions = true
        },
        [90080002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90080002,
          GUID = "90080002.0",
          NextDialogue = 90080001,
          Subtitle = "Let's talk about something else"
        },
        [90080003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90080003,
          GUID = "90080003.0",
          Subtitle = "Goodbye"
        },
        [90080101] = {
          ContentFR = "Ma famille ? Mes parents m’ont laissé tranquille depuis des années. Juste mes deux sœurs qui me donnent des ordres parfois, mais maintenant que je suis dans la Légion, elles peuvent rien faire.",
          DialogueId = 90080101,
          GUID = "E1818E92",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080103,
          SpeakNpcId = 84202,
          Subtitle = "My family? My parents haven't really fussed over me for years; just my sisters occasionally trying to boss me around. But now that I'm in the Legion, they're out of reach.",
          TalkActionId = {
            [1] = "84202:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_01_1"
        },
        [90080103] = {
          ContentFR = "On dirait que tes sœurs sont sévères.",
          DialogueId = 90080103,
          GUID = "E1818EE6",
          NextDialogue = 90080104,
          SpeakNpcId = 100001,
          Subtitle = "Sounds like your sisters are pretty mean."
        },
        [90080104] = {
          ContentFR = "Non, pas du tout ! Elles sont adorables, intelligentes, gentilles, élégantes, optimistes... Bref, elles ont tout pour elles ! Bon... un peu plus de retenue ne leur ferait pas de mal.",
          DialogueId = 90080104,
          GUID = "E1818F10",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          Subtitle = "Oh, not at all! T-They're absolutely delightful, smart, kind-hearted, gentle, charming, beautiful, and just about perfect! Though, a bit more decorum would be nice...",
          TalkActionId = {
            [1] = "84202:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90080201] = {
          ContentFR = "Toi, tu dois être du genre à pas savoir te détendre. Écoute : le lit, c’est un refuge pour l’âme, le toit, un sanctuaire pour l’esprit, l’après-midi, le jardin devient un écrin de lumière... Et la sieste ? Une douce symphonie.",
          DialogueId = 90080201,
          GUID = "E1819EFA",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080203,
          SpeakNpcId = 84202,
          Subtitle = "Huh, you're one of those who don't appreciate a good rest! Listen up: Beds are havens, where souls find ease; rooftops sanctuaries, where anxieties cease. In afternoon gardens, the sunlight gleams; take a nap, and enjoy the symphony of sweet dreams...",
          TalkActionId = {
            [1] = "84202:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_02_1"
        },
        [90080203] = {
          ContentFR = "(L’ignorer et partir en silence.)",
          DialogueId = 90080203,
          GUID = "E1819F4E",
          NextDialogue = 90080204,
          SpeakNpcId = 100001,
          Subtitle = "(Turn around and leave)"
        },
        [90080204] = {
          ContentFR = "Hé ! Attends, j’ai pas fini !",
          DialogueId = 90080204,
          GUID = "E1819F78",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          Subtitle = "...Hey! I wasn't done!",
          TalkActionId = {
            [1] = "84202:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90080301] = {
          ContentFR = "Elle sait vraiment comment te faire courir partout... Il me faudrait trois moi pour suivre le rythme... Euh, je veux dire, la commandante Sibylle est très stricte avec ses subordonnés.",
          DialogueId = 90080301,
          GUID = "E181AF62",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080303,
          SpeakNpcId = 84202,
          Subtitle = "She sure knows how to run you ragged... I'd need to split myself in three just to keep up... Ahem, I mean, Chief Sibylle is always perfectly strict with us.",
          TalkActionId = {
            [1] = "84202:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_03_1"
        },
        [90080303] = {
          ContentFR = "C’est trop tard, j’ai entendu.",
          DialogueId = 90080303,
          GUID = "E181AFB6",
          NextDialogue = 90080304,
          SpeakNpcId = 100001,
          Subtitle = "Too late, I heard that clearly."
        },
        [90080304] = {
          ContentFR = "Voilà ce que je te propose : un goûter, et on fait comme si tu n’avais rien entendu, ça te va ? T’inquiète, y a pas de truc bizarre dedans.",
          DialogueId = 90080304,
          GUID = "E181AFE0",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          Subtitle = "...How about I treat you to some afternoon tea, and we pretend this conversation never happened? Don't worry, it won't be spiked.",
          TalkActionId = {
            [1] = "84202:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90080401] = {
          ContentFR = "J’ai créé un truc génial pour toi : un petit robot compagnon ! En combat, il te suit, agite un drapeau et crie \"Allez ! T’assures grave !\"",
          DialogueId = 90080401,
          GUID = "E181BFCA",
          LookAt = {
            [1] = "84202:n(0)",
            [2] = "0:n(84202)"
          },
          NextDialogue = 90080403,
          SpeakNpcId = 84202,
          Subtitle = "I've rigged up something awesome for you — a tiny robot sidekick! It'll follow you around in battle, waving a little banner and cheering, \"Go get'em! You're smashing it!\"",
          TalkActionId = {
            [1] = "84202:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_04_1"
        },
        [90080403] = {
          ContentFR = "Plutôt cool, non ? Attends que je le fasse vraiment fonctionner...",
          DialogueId = 90080403,
          GUID = "E181BFF4",
          NextDialogue = 90080404,
          SpeakNpcId = 84202,
          Subtitle = "Pretty cool, huh? Just wait till I actually get it working...",
          TalkActionId = {
            [1] = "84202:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_04_2"
        },
        [90080404] = {
          ContentFR = "(L’ignorer et partir en silence.)",
          DialogueId = 90080404,
          GUID = "E181BFF5",
          NextDialogue = 90080405,
          SpeakNpcId = 100001,
          Subtitle = "(Turn around and leave)"
        },
        [90080405] = {
          ContentFR = "Hé, attends, j’ai pas fini ! J’ai dessiné ces plans sans que la commandante Sibylle ne le sache, pendant mes rares pauses...",
          DialogueId = 90080405,
          GUID = "E181BFF6",
          NextOptions = {
            [1] = 90080002,
            [2] = 90080003
          },
          SpeakNpcId = 84202,
          Subtitle = "Hey, I didn't finish! I drew up these plans during my precious breaks — do you know how hard it was for me to keep them from Chief Sibylle?",
          VoiceName = "voice/$Locale$/char/Landi/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90080501] = {
          ContentFR = "Au rapport rapport, commandante Sibylle. Les tâches du jour sont toutes assignées. Si vous avez d’autres consignes, je suis prêt à les exécuter. Mais la journée a été chargée, pensez à vous reposer pour ne pas vous épuiser.",
          DialogueId = 90080501,
          GUID = "E181D032",
          SpeakNpcId = 84202,
          Subtitle = "Reporting, Chief Sibylle. Today's tasks have been arranged. If you have any additional orders, I'm ready to carry them out. However, today was quite demanding, so you should take some rest to avoid burning out.",
          VoiceName = "voice/$Locale$/char/Landi/vo_companio_01"
        },
        [90080601] = {
          ContentFR = "Beau boulot pour la dernière mission, mais j’ai reçu quelques plaintes à propos de dégâts matériels... Et devine qui doit aller présenter ses excuses à ta place ? Moi ! Et tu me connais, je suis bien trop timide pour ça... Alors, ma très chère, adorable et gentille Lynn, tu pourrais pas t’occuper de ces petites urgences à ma place ? Allez, sois un amour, juste cette fois.",
          DialogueId = 90080601,
          GUID = "E181E09A",
          SpeakNpcId = 84202,
          Subtitle = "Great job on the last mission, but I've received some complaints about damage to public property... I find it kinda awkward to apologise to people on your behalf... After all, I'm a bit shy. Soooo, lovely and kind-hearted Miss Lynn, could you handle these urgent tasks for me? Pretty please with a cherry on top!",
          VoiceName = "voice/$Locale$/char/Landi/vo_companio_02"
        },
        [90080701] = {
          ContentFR = "Hein, comment as-tu pu... ? Je dois être épuisé, j’ai des hallucinations... Je vais déclarer ça comme accident de travail et prendre un congé maladie.",
          DialogueId = 90080701,
          GUID = "E181F102",
          SpeakNpcId = 84202,
          Subtitle = "Wha... How can this be? Maybe I'm just so tired that I'm seeing things now. Might as well file for a work-related injury and take a few more days off.",
          VoiceName = "voice/$Locale$/char/Landi/vo_companio_03"
        },
        [90090000] = {
          ContentFR = "Exposer ainsi ton dos... Est-ce de l’ignorance ou de la pure idiotie ?",
          DialogueId = 90090000,
          GUID = "E187E6C9",
          SpeakNpcId = 84301,
          Subtitle = "Exposing your back to your enemy so carelessly... Is it naivety or sheer folly?",
          VoiceName = "voice/$Locale$/char/Xibi/vo_idle"
        },
        [90090001] = {
          ContentFR = "Toute cette ardeur... Je commence à espérer que tu sois bientôt {性别:prêt|prête} à me défier de nouveau.",
          DialogueId = 90090001,
          GUID = "E187E6CA",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextOptions = {
            [1] = 900900011,
            [2] = 900900012,
            [3] = 900900013,
            [4] = 900900014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84301,
          Subtitle = "Watching your relentless efforts to strengthen yourself, I can't help but look forward to the day you challenge me again.",
          TalkActionId = {
            [1] = "84301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_welcome",
          bForbidSkipOptions = true
        },
        [90090002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90090002,
          GUID = "90090002.0",
          NextDialogue = 90090001,
          Subtitle = "Let's talk about something else"
        },
        [90090003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90090003,
          GUID = "90090003.0",
          Subtitle = "Goodbye"
        },
        [90090101] = {
          ContentFR = "Une unité d’élite sous les ordres directs de l’Empereur. Chargée de missions secrètes et d’interventions ciblées.",
          DialogueId = 90090101,
          GUID = "E187F732",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090103,
          SpeakNpcId = 84301,
          Subtitle = "A special force under the direct command of the Emperor, tasked with covert missions and serving as a hammer ready to strike on the battlefield.",
          TalkActionId = {
            [1] = "84301:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_01_1"
        },
        [90090103] = {
          ContentFR = "Pas étonnant que vous soyez aussi arrogantes, avec l’Empereur dans votre dos.",
          DialogueId = 90090103,
          GUID = "E187F786",
          NextDialogue = 90090104,
          SpeakNpcId = 100001,
          Subtitle = "Huh, backed by the Emperor — no wonder you're always so overbearing.",
          TalkActionId = {
            [1] = "84301:Talk03_End"
          }
        },
        [90090104] = {
          ContentFR = "Tu te trompes. Sans l’Empereur, la Légion existe toujours. Sans la Légion, la couronne tombe.",
          DialogueId = 90090104,
          GUID = "E187F7B0",
          NextDialogue = 90090105,
          SpeakNpcId = 84301,
          Subtitle = "You got it all wrong. Without the Emperor, the Legion still stands; without the Legion, however, the crown would surely fall.",
          TalkActionId = {
            [1] = "84301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_01_2"
        },
        [90090105] = {
          ContentFR = "Avec ce que vous venez de dire, puis-je vous accuser de tentative de rébellion ?",
          DialogueId = 90090105,
          GUID = "E187F7DA",
          NextDialogue = 90090106,
          SpeakNpcId = 100001,
          Subtitle = "Should I report you for treason based on that statement?",
          TalkActionId = {
            [1] = "84301:Confident_Start"
          }
        },
        [90090106] = {
          ContentFR = "Tu peux me dénoncer, oui. Et ta plainte finira... sur mon bureau.",
          DialogueId = 90090106,
          GUID = "E187F804",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          Subtitle = "Feel free to try. Treason is a grave offence, and any accusation would work its way up through the ranks and end up right on my desk.",
          TalkActionId = {
            [1] = "84301:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90090201] = {
          ContentFR = "Je ne sers pas l’Empire. Je sers un idéal. Quelqu’un a tout sacrifié pour lui. Je ne laisserai pas son combat se perdre.",
          DialogueId = 90090201,
          GUID = "E188079A",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090203,
          SpeakNpcId = 84301,
          Subtitle = "Hmph, my allegiance is not to the Empire, but to my ideals. A man once gave everything for these, and it is his legacy that I strive to uphold.",
          TalkActionId = {
            [1] = "84301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_02_1"
        },
        [90090203] = {
          ContentFR = "Ce ne sont que des excuses. Peu importe vos raisons, vos actes ne font que renforcer la tyrannie.",
          DialogueId = 90090203,
          GUID = "E18807EE",
          NextDialogue = 90090204,
          SpeakNpcId = 100001,
          Subtitle = "You're just making excuses. No matter the reason, your actions are nothing more than enabling tyranny."
        },
        [90090204] = {
          ContentFR = "Tu n’as pas tort. Pour obtenir ce que je veux, j’utilise tout ce que j’ai sous la main et je grimpe les échelons par tous les moyens. Mais à chaque pas, je me rapproche de ce en quoi je crois. Et toi, où tes pas t’ont-ils mené ?",
          DialogueId = 90090204,
          GUID = "E1880818",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          Subtitle = "You're not wrong. To get what I desire, I'll use everything at my disposal and climb the ladder by any means necessary; but each step I take is a step closer to what I believe in. Where have your steps led you?",
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90090301] = {
          ContentFR = "Ma famille est partie depuis longtemps. Ce genre de douleur ne m’atteint plus.",
          DialogueId = 90090301,
          GUID = "E1881802",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090303,
          SpeakNpcId = 84301,
          Subtitle = "It's okay. My family's long gone anyway.",
          TalkActionId = {
            [1] = "84301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_03_1"
        },
        [90090303] = {
          ContentFR = "...",
          DialogueId = 90090303,
          GUID = "E1881856",
          NextDialogue = 90090304,
          SpeakNpcId = 100001,
          Subtitle = "..."
        },
        [90090304] = {
          ContentFR = "Je trouve ça libérateur. Plus aucune distraction, juste un chemin dégagé pour affronter mes ennemis, qu’ils soient visibles ou tapis dans l’ombre.",
          DialogueId = 90090304,
          GUID = "E1881880",
          NextDialogue = 90090305,
          SpeakNpcId = 84301,
          Subtitle = "I find it liberating, actually. It means no more distractions — just a clear path to contend with my enemies, both known and hidden.",
          TalkActionId = {
            [1] = "84301:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_03_2"
        },
        [90090305] = {
          ContentFR = "Pour ceux qui rejoignent la Légion, les émotions ne sont rien d’autre qu’une faille.",
          DialogueId = 90090305,
          GUID = "E18818AA",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          Subtitle = "Sentiment and feelings are merely weaknesses for anyone in the Legion.",
          TalkActionId = {
            [1] = "84301:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90090401] = {
          ContentFR = "Bien sûr. J’ai entendu bien des insultes et moqueries... Et les murmures dans l’ombre sont encore plus nombreux.",
          DialogueId = 90090401,
          GUID = "E188286A",
          LookAt = {
            [1] = "84301:n(0)",
            [2] = "0:n(84301)"
          },
          NextDialogue = 90090403,
          SpeakNpcId = 84301,
          Subtitle = "Indeed. I've endured my share of curses and jibes to my face, and those from the gutter surely grumble even more.",
          TalkActionId = {
            [1] = "84301:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_04_1"
        },
        [90090403] = {
          ContentFR = "Heureusement, malgré l’injustice du monde, posséder une force au-dessus de tous suffit à obtenir un minimum de respect.",
          DialogueId = 90090403,
          GUID = "E18828BE",
          NextDialogue = 90090404,
          SpeakNpcId = 84301,
          Subtitle = "Fortunately, in this unjust world, absolute power can still earn one a modicum of respect.",
          TalkActionId = {
            [1] = "84301:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_04_2"
        },
        [90090404] = {
          ContentFR = "Dans ce cas, si vous veniez à perdre votre force, ils s’acharneraient aussitôt sur vous.",
          DialogueId = 90090404,
          GUID = "E18828E8",
          NextDialogue = 90090405,
          SpeakNpcId = 100001,
          Subtitle = "In that case, if you ever lost your power, they'd certainly kick you hard while you're down."
        },
        [90090405] = {
          ContentFR = "Évidemment. C’est précisément pour cela que je ne leur montrerai jamais la moindre faiblesse. Sinon, ils se jetteraient sur moi comme des loups à l’odeur du sang.",
          DialogueId = 90090405,
          GUID = "E1882912",
          NextOptions = {
            [1] = 90090002,
            [2] = 90090003
          },
          SpeakNpcId = 84301,
          Subtitle = "Exactly, which is why I'll never show weakness; otherwise, they'd pounce like wolves at the scent of blood, eager to tear me apart.",
          TalkActionId = {
            [1] = "84301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Xibi/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90090501] = {
          ContentFR = "... Il est temps que nous réglions nos différends.",
          DialogueId = 90090501,
          GUID = "E18838D2",
          SpeakNpcId = 84301,
          Subtitle = "...It's time we resolve our differences.",
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_01"
        },
        [90090801] = {
          ContentFR = "Une si belle façade... ça ne fait que révéler à quel point tu as poli tes crocs dans l’ombre. J’attends patiemment le jour où tu montreras les crocs... pour mieux te les briser.",
          DialogueId = 90090801,
          GUID = "E1886A0A",
          SpeakNpcId = 84301,
          Subtitle = "The more flawless your disguise, the sharper the fangs you've honed in the dark. I await the day you reveal your true nature, so I can shatter those fangs without mercy.",
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_04"
        },
        [90091001] = {
          ContentFR = "Les derniers rapports d’opérations, les plans tactiques, documents logistiques et rapports de pertes sont bien organisés ?\nBien. Alors passons aux slogans de campagne, aux analyses internes, aux rapports réguliers à l’Empereur, et les résultats des tests des nouvelles armes des Spathatoi. Ce n’est pas une charge supplémentaire, c’est notre boulot.",
          DialogueId = 90091001,
          GUID = "E1888ADA",
          SpeakNpcId = 84301,
          Subtitle = [[
Have all the recent mission briefings, combat plans, logistical documents, and loss reports been organised?
Good. Then let's also finalise the external campaign slogans, domestic case analyses, routine reports to the Emperor, and the test data for the new weapons from Spathatoi today. These are part of our job, not an extra burden.]],
          VoiceName = "voice/$Locale$/char/Xibi/vo_companio_05"
        },
        [90100000] = {
          ContentFR = "Parfois, il suffit de vous regarder pour que le temps file... J’aimerais qu’il ralentisse un peu.",
          DialogueId = 90100000,
          GUID = "E18E4F69",
          SpeakNpcId = 85301,
          Subtitle = "I feel like time flies when I do nothing but watch you guys... I wish time wouldn't go so fast.",
          VoiceName = "voice/$Locale$/char/Saiqi/vo_idle"
        },
        [90100001] = {
          ContentFR = "Je suis encore ici aujourd’hui... et toi aussi. Quel soulagement.",
          DialogueId = 90100001,
          GUID = "E18E4F6A",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextOptions = {
            [1] = 901000011,
            [2] = 901000012,
            [3] = 901000013,
            [4] = 901000014,
            [5] = 901000015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85301,
          Subtitle = "Such a relief — I'm still here today. And so are you...",
          TalkActionId = {
            [1] = "85301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_welcome",
          bForbidSkipOptions = true
        },
        [90100002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90100002,
          GUID = "90100002.0",
          NextDialogue = 90100001,
          Subtitle = "Let's talk about something else"
        },
        [90100003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90100003,
          GUID = "90100003.0",
          Subtitle = "Goodbye"
        },
        [90100101] = {
          ContentFR = "Merci ! En fait, nous, les Charons, sommes assez résistants au froid, donc pas besoin d’acheter de gros manteaux chers.",
          DialogueId = 90100101,
          GUID = "E18E5FD2",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100103,
          SpeakNpcId = 85301,
          Subtitle = "Thank you! Actually, we Charons are quite resilient to the cold, so there's no need for expensive, heavy coats.",
          TalkActionId = {
            [1] = "85301:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_01_1"
        },
        [90100103] = {
          ContentFR = "Ma mère a confectionné cette robe, mais c’est moi qui ai choisi la couleur, ce vert vif, et les détails papillon. Ils seraient parfaitement à leur place dans un endroit chaud, comme le sud.",
          DialogueId = 90100103,
          GUID = "E18E6026",
          NextDialogue = 90100104,
          SpeakNpcId = 85301,
          Subtitle = "My mom made this dress, but I chose the colour — this vibrant green — and the butterfly details too. They'd look right at home somewhere warm, like the south.",
          TalkActionId = {
            [1] = "85301:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_01_2"
        },
        [90100104] = {
          ContentFR = "Je vois. Les papillons sont une bonne idée, ils te vont à merveille.",
          DialogueId = 90100104,
          GUID = "E18E6050",
          NextDialogue = 90100105,
          SpeakNpcId = 100001,
          Subtitle = "I see. The butterflies are a nice touch — they suit you perfectly."
        },
        [90100105] = {
          ContentFR = "Vraiment ? Merci ! Je n’ai vu que des papillons bleus près de Givrelac. J’aimerais beaucoup voir un jour quelles autres couleurs ils peuvent avoir.",
          DialogueId = 90100105,
          GUID = "E18E607A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          Subtitle = "Really? That's so nice to hear! Actually, I've only seen blue butterflies around Icelake. I'd love to see what other colours are out there someday.",
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90100201] = {
          ContentFR = "Oui, c’est comme ça depuis toujours. On nous traite comme des parasites et j’ai été victime de harcèlement et d’insultes sans raison.",
          DialogueId = 90100201,
          GUID = "E18E703A",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100203,
          SpeakNpcId = 85301,
          Subtitle = "Yeah, it's been that way for ages. We're treated like pests and I've faced harassment and insults for no reason.",
          TalkActionId = {
            [1] = "85301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_1"
        },
        [90100203] = {
          ContentFR = "C’est parce que les Solariens craignent les pouvoirs des Charons ?",
          DialogueId = 90100203,
          GUID = "E18E708E",
          NextDialogue = 90100204,
          SpeakNpcId = 100001,
          Subtitle = "Is it because Solas fear what Charons can do?"
        },
        [90100204] = {
          ContentFR = "Probablement. On dit que « la magie est la source de tous les maux ». Les livres d'histoire affirment que nos ancêtres l’ont utilisée pour régner sur les Solariens il y a plus de mille ans, commettant des actes terribles.",
          DialogueId = 90100204,
          GUID = "E18E70B8",
          NextDialogue = 90100205,
          SpeakNpcId = 85301,
          Subtitle = "Probably. They say \"Magic is the root of all evil.\" History books claim our ancestors used it to rule over Solas more than a thousand years ago, committing terrible acts.",
          TalkActionId = {
            [1] = "85301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_2"
        },
        [90100205] = {
          ContentFR = "Honnêtement, j’ai du mal à y croire... Les Charons que je connais ont trop peur des Solariens pour oser parler en leur présence, alors utiliser la magie, n’en parlons pas.",
          DialogueId = 90100205,
          GUID = "E18E70E2",
          NextDialogue = 90100206,
          SpeakNpcId = 85301,
          Subtitle = "Honestly, I can hardly imagine that... The Charons I know are too terrified of Solas to even speak up around them, let alone use magic.",
          TalkActionId = {
            [1] = "85301:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_3"
        },
        [90100206] = {
          ContentFR = "Et la plupart des sorts des Charons sont assez ordinaires, ils ne servent qu’à des choses simples comme allumer des cheminées ou congeler des aliments.",
          DialogueId = 90100206,
          GUID = "E18E710C",
          NextDialogue = 90100207,
          SpeakNpcId = 85301,
          Subtitle = "And Most Charon magic is quite ordinary — just good for simple things like lighting fireplaces or freezing food.",
          TalkActionId = {
            [1] = "85301:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_4"
        },
        [90100207] = {
          ContentFR = "Tu aimerais revenir à cette époque ? Quand les Charons régnaient sur les Solariens ?",
          DialogueId = 90100207,
          GUID = "E18E7136",
          NextDialogue = 90100208,
          SpeakNpcId = 100001,
          Subtitle = "Would you wish to go back to those times — when Charons ruled over Solas?",
          TalkActionId = {
            [1] = "85301:Talk01_End"
          }
        },
        [90100208] = {
          ContentFR = "Pas du tout. Pourquoi l’un doit-il régner sur l’autre ? Pourquoi Charons et Solariens ne peuvent-ils pas simplement vivre en paix ?",
          DialogueId = 90100208,
          GUID = "E18E7160",
          NextDialogue = 90100209,
          SpeakNpcId = 85301,
          Subtitle = "Not at all. Why must one rule over the other? Why can't Charons and Solas just live in peace?",
          TalkActionId = {
            [1] = "85301:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_5"
        },
        [90100209] = {
          ContentFR = "Tout ce que je souhaite... c’est que, au retour du printemps, on puisse aller voir les fleurs ensemble. C’est tout.",
          DialogueId = 90100209,
          GUID = "E18E718A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          Subtitle = "All I wish for is that when spring comes, everyone can go out together to enjoy all kinds of flowers. That would be enough for me.",
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_02_6",
          bForbidSkipOptions = true
        },
        [90100301] = {
          ContentFR = "Ah, cela vient peut-être de mon nouveau projet de jardinage. La cour de la Maison d’Hypnos semblait un peu vide avec seulement quelques arbres, alors j’y ai planté des fleurs blanches.",
          DialogueId = 90100301,
          GUID = "E18E80A2",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100303,
          SpeakNpcId = 85301,
          Subtitle = "Ah, that might be from my new gardening project. The courtyard at the Hypnos' House looked a bit barren with just a few trees, so I planted some white flowers there.",
          TalkActionId = {
            [1] = "85301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_03_1"
        },
        [90100303] = {
          ContentFR = "Peut-être devrions-nous en planter ici aussi, des muguets, des anémones des bois, des dryades blanches... Lesquelles conviendraient le mieux à cet endroit ?",
          DialogueId = 90100303,
          GUID = "E18E80F6",
          NextDialogue = 90100304,
          SpeakNpcId = 85301,
          Subtitle = "Perhaps we should plant some here too — bellflowers, windflowers, white dryas... Which would suit this place best?",
          TalkActionId = {
            [1] = "85301:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_03_2"
        },
        [90100304] = {
          ContentFR = "Peut-être pourrions-nous demander l’avis de tout le monde.",
          DialogueId = 90100304,
          GUID = "E18E8120",
          NextDialogue = 90100305,
          SpeakNpcId = 100001,
          Subtitle = "Maybe you could ask around and gather everyone's thoughts on it."
        },
        [90100305] = {
          ContentFR = "Tu as raison, ce serait mieux si tout le monde décidait ensemble... Je vais leur demander ! Ah, au fait, il y en a une que tu préfères ? Quand elles auront fleuri, je t’en cueillerai.",
          DialogueId = 90100305,
          GUID = "E18E814A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          Subtitle = "Right, it should be a group decision... I'll ask around! By the way, which flower do you like best? I'll pick some for you when they bloom.",
          TalkActionId = {
            [1] = "85301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90100401] = {
          ContentFR = "Non, je suis ici depuis toujours. J’entends les trains tous les jours, mais je n’ai jamais vu ce qu’il y a au bout des rails. Si j’en avais l’occasion, j’aimerais vraiment découvrir le monde extérieur.",
          DialogueId = 90100401,
          GUID = "E18E80CC",
          LookAt = {
            [1] = "85301:n(0)",
            [2] = "0:n(85301)"
          },
          NextDialogue = 90100403,
          SpeakNpcId = 85301,
          Subtitle = "No, I've been here my whole life. I always hear those trains and wonder about the places they're heading to. I'd really love to see what's out there.",
          TalkActionId = {
            [1] = "85301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_04_1"
        },
        [90100403] = {
          ContentFR = "Quels endroits tu aimerais voir un jour ?",
          DialogueId = 90100403,
          GUID = "E18E80CB",
          NextDialogue = 90100404,
          SpeakNpcId = 100001,
          Subtitle = "What places are on your wish list?",
          TalkActionId = {
            [1] = "85301:Explain02_End"
          }
        },
        [90100404] = {
          ContentFR = "Hmm... Je dirais la capitale, forcément. Et mon oncle Henrik m’a parlé des couchers de soleil magnifiques à Rougerive. Ah, et aussi cette île dans le sud dont tu m’as parlé, l’Île du Purgatoire ! Je veux sentir si l’air marin est vraiment salé !",
          DialogueId = 90100404,
          GUID = "E18E910A",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          Subtitle = "Mm, I'd definitely want to visit the capital, for starters; Uncle Henrik once told me the sunsets in Scarletriver are breathtaking... Oh, and I'd love to visit Purgatorio Island you told me about — to feel the sea breeze and see if it's as salty as you described!",
          TalkActionId = {
            [1] = "85301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90100501] = {
          ContentFR = "Non, c’est juste que... j’aimerais vous observer un peu plus longtemps. Pour garder une image bien nette de vous tous dans ma tête.",
          DialogueId = 90100501,
          GUID = "E18EA172",
          NextDialogue = 90100502,
          SpeakNpcId = 85301,
          Subtitle = "Oh, it's just that... I want to take a good look at you all, to memorize your faces better.",
          TalkActionId = {
            [1] = "85301:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_05_1"
        },
        [90100502] = {
          ContentFR = "Tu veux bien me regarder aussi ? Juste un peu... J’aimerais que tu te souviennes de moi... de moi telle que je suis maintenant.",
          DialogueId = 90100502,
          GUID = "E18EA19C",
          NextOptions = {
            [1] = 90100002,
            [2] = 90100003
          },
          SpeakNpcId = 85301,
          Subtitle = "Could you maybe take a moment to look at me carefully? I'd like you to remember me... just as I am right now.",
          TalkActionId = {
            [1] = "85301:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Saiqi/vo_topic_05_2",
          bForbidSkipOptions = true
        },
        [90100601] = {
          Content = "我听说奥特赛德先生为菲娜的生日精心准备了很久。虽然嘴上不饶人，但你其实是个很体贴的人吧？下一次菲娜生日，我可以和你们一起为她准备惊喜吗？",
          DialogueId = 90100601,
          GUID = "E18EB1DA",
          SpeakNpcId = 85301,
          VoiceName = "voice/$Locale$/char/Saiqi/vo_companio_01"
        },
        [90100801] = {
          ContentFR = "Tu vas vraiment me raconter l’histoire d’Élysium ? Merci beaucoup ! Hmm... et si je t’offrais une fleur en échange ? Quoi ? Une fleur... à manger ?",
          DialogueId = 90100801,
          GUID = "E18ED2AA",
          SpeakNpcId = 85301,
          Subtitle = [[
Are you gonna tell me the story of Elysium? Thank you so much! I wonder what kind of flowers you'd like in return?
Delicious ones, you say?]],
          VoiceName = "voice/$Locale$/char/Saiqi/vo_companio_03"
        }
      }
    end
  },
  {
    MinKey = 90110000,
    MaxKey = 90190203,
    Loader = function()
      return {
        [90110000] = {
          ContentFR = "Aérer le matin après avoir nettoyé, vaporiser de l’alcool fort à midi, brûler de l’encens au crépuscule, il n’y a pas mieux pour assainir une pièce.",
          DialogueId = 90110000,
          GUID = "E194B809",
          SpeakNpcId = 82401,
          Subtitle = "Sweeping up and venting in the morning, spraying strong liquor in the afternoon, and lighting incense sticks at dusk to drive away insects — that's the only way to keep a room clean.",
          VoiceName = "voice/$Locale$/char/Baiheng/vo_idle"
        },
        [90110001] = {
          ContentFR = "L'environnement façonne l'esprit, et prendre soin de soi renforce le corps. Peut-être qu'une promenade sous ce ciel clément pourrait te faire du bien.",
          DialogueId = 90110001,
          GUID = "E194B80A",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextOptions = {
            [1] = 901100011,
            [2] = 901100012,
            [3] = 901100013,
            [4] = 901100014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 82401,
          Subtitle = "One's surroundings shape the spirit, and mindful care strengthens the body. Perhaps a walk beneath these kindly skies would do wonders for your health.",
          VoiceName = "voice/$Locale$/char/Baiheng/vo_welcome",
          bForbidSkipOptions = true
        },
        [90110002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90110002,
          GUID = "90110002.0",
          NextDialogue = 90110001,
          Subtitle = "Let's talk about something else"
        },
        [90110003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90110003,
          GUID = "90110003.0",
          Subtitle = "Goodbye"
        },
        [90110101] = {
          ContentFR = "En effet. Cependant, le contenu est dense et cryptique, et même les distinctions entre certains remèdes me semblent difficiles à saisir. Peut-être ne suis-je pas faite pour cette discipline.",
          DialogueId = 90110101,
          GUID = "E194C872",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110103,
          SpeakNpcId = 82401,
          Subtitle = "Indeed. Yet, the contents are dense and cryptic, and even the distinctions between certain remedies remain elusive to me. Perhaps I simply lack the aptitude for this craft.",
          TalkActionId = {
            [1] = "82401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_1"
        },
        [90110103] = {
          ContentFR = "Vraiment ? Je pensais que pour une guérisseuse, comprendre ce genre de choses serait un jeu d'enfant.",
          DialogueId = 90110103,
          GUID = "E194C8C6",
          NextDialogue = 90110104,
          SpeakNpcId = 100001,
          Subtitle = "Really? I thought for a healer, grasping this kind of stuff would be a walk in the park."
        },
        [90110104] = {
          ContentFR = "À mon époque, la médecine n’était pas centrée sur les remèdes, on pratiquait un art miraculeux appelé \"Zhuyou\" pour chasser la maladie.",
          DialogueId = 90110104,
          GUID = "E194C8F0",
          NextDialogue = 90110105,
          SpeakNpcId = 82401,
          Subtitle = "In my time... medication was not the primary means of healing. People practised a miraculous healing art called \"Zhuyou\" to ward off illness.",
          TalkActionId = {
            [1] = "82401:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_2"
        },
        [90110105] = {
          ContentFR = "Mais cet art, bien qu’apportant guérison et paix, exigeait un prix, le sacrifice même de la force vitale du guérisseur. Aucun d’entre nous ne vivait jusqu’à un âge avancé, puiser dans notre essence jusqu’à la mort était la seule voie que nous connaissions.",
          DialogueId = 90110105,
          GUID = "E194C8F1",
          NextDialogue = 90110106,
          SpeakNpcId = 82401,
          Subtitle = "While this method could bring healing and peace, it demanded the sacrifice of a healer's very life force. None of us lived to see old age — pouring out our essence unto death was the only path we knew.",
          TalkActionId = {
            [1] = "82401:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_3"
        },
        [90110106] = {
          ContentFR = "... Un fardeau bien lourd à porter.",
          DialogueId = 90110106,
          GUID = "E194C8F2",
          NextDialogue = 90110107,
          SpeakNpcId = 100001,
          Subtitle = "...That's such a heavy burden to bear."
        },
        [90110107] = {
          ContentFR = "Le Pavillon de l’Éphémère n’est aujourd’hui plus qu’un souvenir, mais la vocation de guérir ne s’éteint jamais. Il y aura toujours ceux qui porteront cette mission jusqu’au bout, avec une détermination inébranlable.",
          DialogueId = 90110107,
          GUID = "E194C8F3",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          Subtitle = "The Hall of Ephemerality may now be but a relic of time, yet the path of healing and saving lives has never lacked successors. Even under the heaviest burdens, there will always be those who press forward with unwavering resolve.",
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90110201] = {
          ContentFR = "Je rêve d’un monde sans maladies incurables.",
          DialogueId = 90110201,
          GUID = "E194D8DA",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110203,
          SpeakNpcId = 82401,
          Subtitle = "I dream of a world without incurable maladies.",
          TalkActionId = {
            [1] = "82401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_04_1"
        },
        [90110203] = {
          ContentFR = "C'est un rêve assez ambitieux...",
          DialogueId = 90110203,
          GUID = "E194D92E",
          NextDialogue = 90110204,
          SpeakNpcId = 100001,
          Subtitle = "That's quite a grand dream...",
          TalkActionId = {
            [1] = "82401:Explain02_End"
          }
        },
        [90110204] = {
          ContentFR = "C’est peut-être utopique, mais même sans miracles, la vocation du guérisseur ne change pas. Dire ça alors que je peine à comprendre les ouvrages médicaux…",
          DialogueId = 90110204,
          GUID = "E194D958",
          NextDialogue = 90110205,
          SpeakNpcId = 82401,
          Subtitle = "It rings as but a fanciful daydream, doesn't it? Yet, even without the miracles of healing magic, the purpose of a healer remains unchanged. I must admit, coming from someone who still struggles to fully grasp medical texts, such a speech must sound absurd.",
          TalkActionId = {
            [1] = "82401:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_04_2"
        },
        [90110205] = {
          ContentFR = "Pourtant, je suivrai ce chemin, pour les gens, pour le Pavillon de l’Éphémère, et pour moi-même aussi.",
          DialogueId = 90110205,
          GUID = "E194D982",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          Subtitle = "But... I'll continue treading this path — not merely for the sake of others or the legacy of the Hall of Ephemerality, but for my own fulfilment as well.",
          TalkActionId = {
            [1] = "82401:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90110301] = {
          ContentFR = "Un endroit pour soigner et sauver des vies.",
          DialogueId = 90110301,
          GUID = "E194E942",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110303,
          SpeakNpcId = 82401,
          Subtitle = "It's a place for healing and saving lives.",
          TalkActionId = {
            [1] = "82401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_1"
        },
        [90110303] = {
          ContentFR = "Peux-tu m'en dire plus à ce sujet ?",
          DialogueId = 90110303,
          GUID = "E194E944",
          NextDialogue = 90110304,
          SpeakNpcId = 100001,
          Subtitle = "Can you tell me more about it?"
        },
        [90110304] = {
          ContentFR = "Sa mission est unique : guérir. Chaque médecin plante un abricotier en commençant sa formation. Cependant, au fil du temps, les intempéries ont emporté beaucoup d'entre eux. Aujourd’hui, il en reste moins de la moitié.",
          DialogueId = 90110304,
          GUID = "E194E943",
          NextDialogue = 90110305,
          SpeakNpcId = 82401,
          Subtitle = "The Hall's mission is singular — to heal, and to heal alone. If one were to speak of other aspects... every healer who trained within its walls planted an apricot tree on the first day of their practice. Yet, as time passed, storms and decay claimed many. Now, fewer than half remain.",
          TalkActionId = {
            [1] = "82401:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_2"
        },
        [90110305] = {
          ContentFR = "Après un long sommeil, je me suis éveillée et suis partie à la recherche de l’abricotier que j’avais planté dans ma jeunesse. Hélas, il n’était plus qu’un bois desséché. Même ce printemps si doux n’a su lui faire renaître le moindre bourgeon.",
          DialogueId = 90110305,
          GUID = "E194E945",
          NextDialogue = 90110306,
          SpeakNpcId = 82401,
          Subtitle = "Waking up from a long slumber, I sought the apricot tree I once planted in my youth. Sadly, the tree had withered to barren wood, and not even this warm spring could coax new buds from its branches.",
          TalkActionId = {
            [1] = "82401:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_3"
        },
        [90110306] = {
          ContentFR = "La vie s’écoule en un éclair, un cheval lancé au galop dans un défilé étroit, une étincelle jaillie d’un silex, une ombre qui erre dans un rêve. Comment retrouver sa route au cœur d’une existence si fugace ? Le passé s’éloigne un peu plus chaque jour, et les espoirs de réparer ce qui fut s’effacent comme la brume aux premières lueurs du matin.",
          DialogueId = 90110306,
          GUID = "E194E946",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          Subtitle = "Life rushes by, like a fleeting horse through a narrow chasm, a spark struck from flint, or a phantom wandering in a dream. How does one find their way back through such transience? The past slips further from reach, while hopes to amend it vanish like morning mist.",
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90110401] = {
          ContentFR = "La mort est semblable à une lampe qui s’éteint : toutes les traces s’effacent, toutes les voix se taisent. Cet isolement, ce silence profond, engloutit toute lueur d’espoir et toute possibilité. Si cela était en mon pouvoir, je ne laisserais aucun patient sombrer dans un tel néant.",
          DialogueId = 90110401,
          GUID = "E194F9AA",
          LookAt = {
            [1] = "82401:n(0)",
            [2] = "0:n(82401)"
          },
          NextDialogue = 90110403,
          SpeakNpcId = 82401,
          Subtitle = "Death is like a lamp extinguished — all traces vanish, all voices fade. That isolation, that profound stillness, consumes every glimmer of hope and possibility. If it lies within my power, I would spare any patient from falling into such an abyss.",
          TalkActionId = {
            [1] = "82401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_02_1"
        },
        [90110403] = {
          ContentFR = "On dirait presque que tu l’as vécu toi-même.",
          DialogueId = 90110403,
          GUID = "E194F9FE",
          NextDialogue = 90110404,
          SpeakNpcId = 100001,
          Subtitle = "It almost sounds as though you've experienced it firsthand."
        },
        [90110404] = {
          ContentFR = "En effet, j’ai autrefois frôlé la mort, terrassée par une grave maladie. Si une telle épreuve devait se représenter, je ne saurais dire avec certitude si je referais le même choix.",
          DialogueId = 90110404,
          GUID = "E194FA28",
          NextOptions = {
            [1] = 90110002,
            [2] = 90110003
          },
          SpeakNpcId = 82401,
          Subtitle = "You're not mistaken. I... once returned from the brink of death, clawing my way back from the clutches of grave illness. Should such a trial confront me again, I cannot say with certainty that I would make the same choice.",
          TalkActionId = {
            [1] = "82401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Baiheng/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90110501] = {
          ContentFR = "Monsieur Randy, à mon humble avis, la léthargie et le laxisme ne sont pas moins des symptômes de maladie. Ils ne vous dérangent peut-être pas pour l'instant, mais ils sèment les graines de futurs maux. Peut-être pourrions-nous faire un peu d’entraînement physique ? Un peu d'exercice pourrait vous faire du bien.",
          DialogueId = 90110501,
          GUID = "E1950A12",
          SpeakNpcId = 82401,
          Subtitle = "Mr. Randy, in my humble opinion, lethargy and laxity are no less symptoms of illness. They may not trouble you now, but they sow the seeds of future ailments. Perhaps we could engage in some light sparring? A touch of exercise might do you good.",
          VoiceName = "voice/$Locale$/char/Baiheng/vo_companio_01"
        },
        [90110601] = {
          ContentFR = "Si un guérisseur peut soulager la souffrance, défier le destin est au-delà de nos capacités. Je peux vous offrir un remède pour apaiser la chaleur de votre cœur, mais la cause profonde de vos problèmes échappe à mon contrôle. Il vaut mieux accepter et s’adapter au cours du temps pour trouver votre propre chemin vers le réconfort...",
          DialogueId = 90110601,
          GUID = "E1951A7A",
          SpeakNpcId = 82401,
          Subtitle = [[
While a healer may ease affliction, defying fate is beyond us. I can offer a remedy to cool the heart's heat, yet the root of your troubles lies beyond my grasp. It is best to accept and adapt to the flow of time to find your own path to solace...
 ]],
          VoiceName = "voice/$Locale$/char/Baiheng/vo_companio_02"
        },
        [90110701] = {
          ContentFR = "Vous entendez souvent une autre voix qui vous parle ? Les autres l’entendent-ils aussi ? Comment se passe votre sommeil ? Quelque chose vous pèse-t-il sur le cœur ? Les afflictions de l’esprit sont les plus difficiles à guérir, même avec l’aide des techniques Zhuyou. Mais en tant que guérisseuse, je ne ménagerai aucun effort.",
          DialogueId = 90110701,
          GUID = "E1952AE2",
          SpeakNpcId = 82401,
          Subtitle = "You often hear another voice speaking to you? Can others hear it too? How has your slumber been? Has something been weighing on your heart? The mind's afflictions are the most elusive to heal, even with the aid of Zhuyou techniques. But as a healer, I will spare no effort.",
          VoiceName = "voice/$Locale$/char/Baiheng/vo_companio_03"
        },
        [90120000] = {
          ContentFR = "Pause goûter, Filbert ! Un peu de blé, quelques noix... et hop, des fleurs pour grignoter. Et si t’as plus faim, je les mettrai sur mon chapeau !",
          DialogueId = 90120000,
          GUID = "E19B20A9",
          SpeakNpcId = 85101,
          Subtitle = "Let's take some rest, Filbert. Have some grains and nuts, and a few flowers for snacks. If you're full, I'll pin them to my hat for now.",
          VoiceName = "voice/$Locale$/char/Songlu/vo_idle"
        },
        [90120001] = {
          ContentFR = "Le soleil brille fort, les nuages sont tout doux, et les petits oiseaux ont bien mangé. Est-ce que ton ventre fait aussi des petits bruits ? On va manger quelque chose ?",
          DialogueId = 90120001,
          GUID = "E19B20AA",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextOptions = {
            [1] = 901200011,
            [2] = 901200012,
            [3] = 901200013,
            [4] = 901200014,
            [5] = 901200015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85101,
          Subtitle = "The sun is shining bright, and the little birdies are chirping with joy after a hearty meal. Are you hungry too? Wanna grab something to eat as well?",
          TalkActionId = {
            [1] = "85101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90120002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90120002,
          GUID = "90120002.0",
          NextDialogue = 90120001,
          Subtitle = "Let's talk about something else"
        },
        [90120003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90120003,
          GUID = "90120003.0",
          Subtitle = "Goodbye"
        },
        [90120101] = {
          ContentFR = "Hein ? Tu sais pas ? Moi, je fais en sorte que tout le monde ait à manger tous les jours, avec plein de bonnes choses !",
          DialogueId = 90120101,
          GUID = "E19B3112",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120103,
          SpeakNpcId = 85101,
          Subtitle = "Huh? You don't know? A commissary's job is to make sure everyone's well-fed, dealing with all sorts of food every day.",
          TalkActionId = {
            [1] = "85101:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_1"
        },
        [90120103] = {
          ContentFR = "Par exemple, je vais chercher plein de choses dans la nature, et Filbert les ramène en ville. Après, on demande à Monsieur Barbe, le boulanger, de préparer des bons petits plats pour tout le monde.",
          DialogueId = 90120103,
          GUID = "E19B3166",
          NextDialogue = 90120104,
          SpeakNpcId = 85101,
          Subtitle = "For example, I go out to gather all kinds of ingredients from the wild, have Filbert haul them back, and then get Mr Beard at the bakery to turn them into yummy food for everyone.",
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_2"
        },
        [90120104] = {
          ContentFR = "Et devine quoi ? Marchander avec Monsieur Barbe, c’est aussi mon boulot ! Hé hé.",
          DialogueId = 90120104,
          GUID = "E19B3190",
          NextDialogue = 90120105,
          SpeakNpcId = 85101,
          Subtitle = "And just so you know, haggling with Mr Beard is part of my job too! Hehe.",
          TalkActionId = {
            [1] = "85101:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_3"
        },
        [90120105] = {
          ContentFR = "Ouah, ça a l’air super ! C’est comme ça pour tous les commissaires au ravitaillement ?",
          DialogueId = 90120105,
          GUID = "E19B31BA",
          NextDialogue = 90120106,
          SpeakNpcId = 100001,
          Subtitle = "Wow! That sounds impressive. Is it the same for all commissaries?"
        },
        [90120106] = {
          ContentFR = "Ah non, pas du tout ! Les autres, ils sont plus à faire des papiers, des demandes, et puis après, plein de nourriture arrive par train.",
          DialogueId = 90120106,
          GUID = "E19B31E4",
          NextDialogue = 90120107,
          SpeakNpcId = 85101,
          Subtitle = "Oh, not at all! The others seem to be brainy types; they're all about the paperwork — filling out application forms, then waiting for trains loaded with food to roll in.",
          TalkActionId = {
            [1] = "85101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_4"
        },
        [90120107] = {
          ContentFR = "Mais dans notre petite ville, moi et Filbert, ça suffit ! Sinon, il faudrait que j’apprenne à faire les papiers… et c’est trop compliqué pour moi !",
          DialogueId = 90120107,
          GUID = "E19B320E",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          Subtitle = "But for a small town like ours, just Filbert and I can feed everyone! Otherwise, I might have to start filling out those forms too — ugh, it's all gibberish to me.",
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_01_5",
          bForbidSkipOptions = true
        },
        [90120201] = {
          ContentFR = "Bah, peut-être ? Je ne sais pas trop. Mais Filbert ne fonce que sur les vilains qui crient et se bagarrent ! Ils l'ont bien cherché !",
          DialogueId = 90120201,
          GUID = "E19B417A",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120203,
          SpeakNpcId = 85101,
          Subtitle = "Hmm... maybe it does? I've never really thought about it, but Filbert only knocks down those no-good, shouty, fighty troublemakers! They totally deserve it!",
          TalkActionId = {
            [1] = "85101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_1"
        },
        [90120203] = {
          ContentFR = "Ces vilains se battent et ont toujours faim après. Ils feraient mieux de cultiver la terre, comme ça y’aurait plus de nourriture pour tout le monde.",
          DialogueId = 90120203,
          GUID = "E19B41CE",
          NextDialogue = 90120204,
          SpeakNpcId = 85101,
          Subtitle = "Those guys always end up hungry after their brawls. They'd do more good ploughing fields than swinging weapons — that way, less people would go to bed hungry.",
          TalkActionId = {
            [1] = "85101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_2"
        },
        [90120204] = {
          ContentFR = "Du coup, tu détestes la guerre, hein ?",
          DialogueId = 90120204,
          GUID = "E19B41F8",
          NextDialogue = 90120205,
          SpeakNpcId = 100001,
          Subtitle = "You must really hate wars, then."
        },
        [90120205] = {
          ContentFR = "Évidemment que je déteste ça ! Se battre, ça finit toujours par creuser l’estomac... et c’est pas drôle du tout. On m’a dit qu’en temps de guerre, personne ne mange à sa faim. J’espère que ça m’arrivera jamais.",
          DialogueId = 90120205,
          GUID = "E19B4222",
          NextDialogue = 90120206,
          SpeakNpcId = 85101,
          Subtitle = "Absolutely! Fighting just leads to hunger — that's really awful! I've heard that in times of war, everyone ends up starving, which is just the worst! I hope I never have to see that.",
          TalkActionId = {
            [1] = "85101:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_3"
        },
        [90120206] = {
          ContentFR = "Si la guerre éclate, tu pourrais grimper sur Filbert et foncer sur les vilains.",
          DialogueId = 90120206,
          GUID = "E19B424C",
          NextDialogue = 90120207,
          SpeakNpcId = 100001,
          Subtitle = "If war does break out, you could mount Filbert and ram those troublemakers.",
          TalkActionId = {
            [1] = "85101:Confident_End"
          }
        },
        [90120207] = {
          ContentFR = "Oui ! Tous ceux qui affament les autres finiront tous par se faire renverser par Filbert !",
          DialogueId = 90120207,
          GUID = "E19B4276",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          Subtitle = "Right! Anyone who makes people go hungry will sooner or later get knocked over by Filbert!",
          TalkActionId = {
            [1] = "85101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90120301] = {
          ContentFR = "Oui, elle mange pas mal, mais elle trouve sa propre nourriture. Même à travers plusieurs ruisseaux, elle sent les baies mûres et me porte pour qu’on aille les chercher. Incroyable, non ?",
          DialogueId = 90120301,
          GUID = "E19B51E2",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120303,
          SpeakNpcId = 85101,
          Subtitle = "Yeah, she is! And you know what, even across several creeks, Filbert can sniff out ripe berries and then off we go charging! Pretty awesome, isn't she?",
          TalkActionId = {
            [1] = "85101:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_03_1"
        },
        [90120303] = {
          ContentFR = "Génial. Il n'y a donc pas besoin de s’inquiéter pour les provisions.",
          DialogueId = 90120303,
          GUID = "E19B5236",
          NextDialogue = 90120304,
          SpeakNpcId = 100001,
          Subtitle = "Awesome. No risk of food shortage then.",
          TalkActionId = {
            [1] = "85101:Talk02_End"
          }
        },
        [90120304] = {
          ContentFR = "T’en fais pas ! Filbert apporte toujours plus de nourriture. Alors ne te moque jamais d'elle, ça la blesserait, et moi aussi.",
          DialogueId = 90120304,
          GUID = "E19B5260",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          Subtitle = "No worries at all! Filbert always brings more food. So never ever make fun of her — it would hurt her feelings, and mine too.",
          TalkActionId = {
            [1] = "85101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90120401] = {
          ContentFR = "Merci ! Mais ce sont des shorts, pas une robe. Avant, c’était une belle robe blanche longue, mais la couturière me l’a changé en short.",
          DialogueId = 90120401,
          GUID = "E19B624A",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120403,
          SpeakNpcId = 85101,
          Subtitle = "Thank you! Actually, these are shorts, not a dress. They did start as a pretty, long, white dress; then the lady at the tailor's shop turned them into shorts for me.",
          TalkActionId = {
            [1] = "85101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_04_1"
        },
        [90120403] = {
          ContentFR = "Pourquoi ?",
          DialogueId = 90120403,
          GUID = "E19B629E",
          NextDialogue = 90120404,
          SpeakNpcId = 100001,
          Subtitle = "Why is that?",
          TalkActionId = {
            [1] = "85101:Explain01_End"
          }
        },
        [90120404] = {
          ContentFR = "Parce que courir en robe, c’est pas pratique. Une fois, j'ai trébuché sur l'ourlet et tout le pain que je portais est tombé.",
          DialogueId = 90120404,
          GUID = "E19B62C8",
          NextDialogue = 90120405,
          SpeakNpcId = 85101,
          Subtitle = "Because dresses aren't the best for all the running around I do. One time, I tripped over the hem and all the bread in my arms went flying.",
          TalkActionId = {
            [1] = "85101:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_04_2"
        },
        [90120405] = {
          ContentFR = "Donc, si un jour personne n’a plus faim, je les ferai changer à nouveau en robe !",
          DialogueId = 90120405,
          GUID = "E19B62F2",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          Subtitle = "But if the day comes, when no one's starving anymore, I'll have them changed back into a dress!",
          TalkActionId = {
            [1] = "85101:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90120501] = {
          ContentFR = "Pas du tout ! Je médite. Je fais partie de l’Église Élyséenne, après tout, alors j'essaie de réfléchir profondément de temps en temps.",
          DialogueId = 90120501,
          GUID = "E19B72B2",
          LookAt = {
            [1] = "85101:n(0)",
            [2] = "0:n(85101)"
          },
          NextDialogue = 90120503,
          SpeakNpcId = 85101,
          Subtitle = "Oh, I was meditating, not zoning out. I'm a member of the Elysian Church after all, so I do try to give some deep thought occasionally.",
          TalkActionId = {
            [1] = "85101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_05_1"
        },
        [90120503] = {
          ContentFR = "Tu pensais à quoi ? Pourquoi il n’y a pas de dieu des ventres pleins ?",
          DialogueId = 90120503,
          GUID = "E19B7306",
          NextDialogue = 90120504,
          SpeakNpcId = 100001,
          Subtitle = "What were you thinking, then? Why isn't there a god of full bellies, perhaps?"
        },
        [90120504] = {
          ContentFR = "Je me posais souvent la question, mais les prêtres disait que c'était... blasphématoire ou quelque chose comme ça. Alors j'ai arrêté d'y penser.",
          DialogueId = 90120504,
          GUID = "E19B7330",
          NextDialogue = 90120505,
          SpeakNpcId = 85101,
          Subtitle = "I used to wonder about that, but the clergy said it was... blastphomy or something. So I stopped thinking about that.",
          TalkActionId = {
            [1] = "85101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_05_2"
        },
        [90120505] = {
          ContentFR = "J’ai jamais trop compris ce qu’ils racontent... Ils disent que la gourmandise, c’est un péché grave, mais plus t’es important, plus tu manges.",
          DialogueId = 90120505,
          GUID = "E19B735A",
          NextOptions = {
            [1] = 90120002,
            [2] = 90120003
          },
          SpeakNpcId = 85101,
          Subtitle = "I never quite get what they say, like how gluttony is a terrible sin... but it seems like the higher someone's status, the more they eat.",
          TalkActionId = {
            [1] = "85101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Songlu/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90120601] = {
          ContentFR = "Tu as trouvé des patates qui germent dans le bac ? Ne les jette pas ! On les plante, on les arrose, et on aura plein de patates pour tout le monde !",
          DialogueId = 90120601,
          GUID = "E19B831A",
          SpeakNpcId = 85101,
          Subtitle = "You found sprouting potatoes in the bin? Don't throw them away — let's plant them! With a little digging and watering, we'll have lots of potatoes for everyone soon enough!",
          VoiceName = "voice/$Locale$/char/Songlu/vo_companio_01"
        },
        [90120701] = {
          ContentFR = "Tu travailles tout le temps... T’as pas un petit creux ? Tu devrais rejoindre l’Église ! Moi, je prends soin des ventres vides.",
          DialogueId = 90120701,
          GUID = "E19B9382",
          SpeakNpcId = 85101,
          Subtitle = "You're always working so hard. Don't you get hungry? Why not join the Church? I'm sure I'll make your tummy full!",
          VoiceName = "voice/$Locale$/char/Songlu/vo_companio_02"
        },
        [90120801] = {
          ContentFR = "Coucou ! Dis, c’est vrai que prier, ça remplit l’âme ? Moi je trouve qu’un bon repas, ça marche pareil ! Tu préfères quoi, toi ?",
          DialogueId = 90120801,
          GUID = "E19BA3EA",
          SpeakNpcId = 85101,
          Subtitle = "Helloooo! I heard that praying can make one's soul feel uplifted. Personally, I think that a good meal does the same thing. But which one works better, praying or dining?",
          VoiceName = "voice/$Locale$/char/Songlu/vo_companio_03"
        },
        [90130000] = {
          ContentFR = "Pas mal. Je devrais avoir assez pour ce mois. Je pensais que ce foutu Randy allait tout me piquer. Je renvoie le reste à la maison, ça devrait suffire pour vivre.",
          DialogueId = 90130000,
          GUID = "E1A18949",
          SpeakNpcId = 83101,
          Subtitle = "Not bad. I should have enough for this month. I thought that ** Randy would take it all himself. I'll send this lot home and get by with the rest.",
          VoiceName = "voice/$Locale$/char/Linen/vo_idle"
        },
        [90130001] = {
          ContentFR = "Tu as besoin de quelque chose ? Parle vite, j’ai une mission à finir.",
          DialogueId = 90130001,
          GUID = "E1A1894A",
          LookAt = {
            [1] = "83101:n(0)",
            [2] = "0:n(83101)"
          },
          NextOptions = {
            [1] = 901300011,
            [2] = 901300012,
            [3] = 901300013,
            [4] = 901300014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83101,
          Subtitle = "Need anything? Spit it out quickly. I've got a mission to finish.",
          VoiceName = "voice/$Locale$/char/Linen/vo_welcome",
          bForbidSkipOptions = true
        },
        [90130002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90130002,
          GUID = "90130002.0",
          NextDialogue = 90130001,
          Subtitle = "Let's talk about something else"
        },
        [90130003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90130003,
          GUID = "90130003.0",
          Subtitle = "Goodbye"
        },
        [90130101] = {
          ContentFR = "Sibylle ? C’est la commandante de la XIIIᵉ Légion.",
          DialogueId = 90130101,
          GUID = "E1A199B2",
          LookAt = {
            [1] = "83101:n(0)",
            [2] = "0:n(83101)"
          },
          NextDialogue = 90130103,
          SpeakNpcId = 83101,
          Subtitle = "Sibylle? She's the chief of the 13th Legion.",
          TalkActionId = {
            [1] = "83101:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_01_1"
        },
        [90130103] = {
          ContentFR = "Et ?",
          DialogueId = 90130103,
          GUID = "E1A199B3",
          NextDialogue = 90130104,
          SpeakNpcId = 100001,
          Subtitle = "Anything else?",
          TalkActionId = {
            [1] = "83101:Talk03_End"
          }
        },
        [90130104] = {
          ContentFR = "Pff, qu’est-ce que tu veux que je sache ? C’est elle qui décide, moi je fais le boulot. C’est tout.",
          DialogueId = 90130104,
          GUID = "E1A199B4",
          NextOptions = {
            [1] = 90130002,
            [2] = 90130003
          },
          SpeakNpcId = 83101,
          Subtitle = "Ugh, what do you expect me to know? She calls the shots, I do the work. That's all.",
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90130201] = {
          ContentFR = "Des conseils ? Le seul que je connais, c’est qu’il n’y a aucun problème qu’un bon coup de poing ne puisse résoudre. Et si ça ne suffit pas, frappe encore.",
          DialogueId = 90130201,
          GUID = "E1A1AA1A",
          LookAt = {
            [1] = "83101:n(0)",
            [2] = "0:n(83101)"
          },
          NextDialogue = 90130203,
          SpeakNpcId = 83101,
          Subtitle = "Tips? The only tip I have is there's no problem a good punch can't fix. If that doesn't work, throw another.",
          TalkActionId = {
            [1] = "83101:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_02_1"
        },
        [90130203] = {
          ContentFR = "Et si deux coups de poing ne suffisent pas non plus ?",
          DialogueId = 90130203,
          GUID = "E1A1AA6E",
          NextDialogue = 90130204,
          SpeakNpcId = 100001,
          Subtitle = "What if two punches don't sort it out either?"
        },
        [90130204] = {
          ContentFR = "Dans ce cas, une balle suffit généralement.",
          DialogueId = 90130204,
          GUID = "E1A1AA98",
          NextDialogue = 90130205,
          SpeakNpcId = 83101,
          Subtitle = "Then a bullet usually does the trick.",
          TalkActionId = {
            [1] = "83101:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_02_2"
        },
        [90130205] = {
          ContentFR = "Mais j'ai entendu dire que certaines personnes peuvent encaisser une balle sans mourir.",
          DialogueId = 90130205,
          GUID = "E1A1AAC2",
          NextDialogue = 90130206,
          SpeakNpcId = 100001,
          Subtitle = "But I heard some people can take a bullet and still stand."
        },
        [90130206] = {
          ContentFR = "Eh, c’est juste une façon de parler. Tant que tes poings sont solides et tes tirs précis, c’est tout ce qui compte. Si tu continues à chipoter, je t’en colle deux !",
          DialogueId = 90130206,
          GUID = "E1A1AAEC",
          NextOptions = {
            [1] = 90130002,
            [2] = 90130003
          },
          SpeakNpcId = 83101,
          Subtitle = "It's just a figure of speech. My point is: be as tough and strong as you can be, and that's all you need. Keep nitpicking, and your face will be getting those punches next.",
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90130301] = {
          ContentFR = "J’ai vu un flingue sympa l’autre jour... Mais bon, pas question de crever la dalle pour ça. L’ancien fait encore l’affaire.",
          DialogueId = 90130301,
          GUID = "E1A1BA82",
          LookAt = {
            [1] = "83101:n(0)",
            [2] = "0:n(83101)"
          },
          NextDialogue = 90130303,
          SpeakNpcId = 83101,
          Subtitle = "Saw a really nice gun the other day... Forget it, can't skimp on food just to buy it. The old one feels better in my hands anyway.",
          TalkActionId = {
            [1] = "83101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_03_1"
        },
        [90130303] = {
          ContentFR = "Si tu l’aimes vraiment, je pourrais peut-être t'en obtenir un.",
          DialogueId = 90130303,
          GUID = "E1A1BAD6",
          NextDialogue = 90130304,
          SpeakNpcId = 100001,
          Subtitle = "If you really like it, maybe I can get one for you.",
          TalkActionId = {
            [1] = "83101:Think_End"
          }
        },
        [90130304] = {
          ContentFR = "Vraiment ? T’as l’air aussi fauché que moi... J’apprécie, mais te ruine pas pour moi. Je veux rien devoir à personne.",
          DialogueId = 90130304,
          GUID = "E1A1BB00",
          NextOptions = {
            [1] = 90130002,
            [2] = 90130003
          },
          SpeakNpcId = 83101,
          Subtitle = "Really?... Nah, you look as broke as me... I appreciate the gesture, but don't go break a piggy bank for me. I don't wanna owe anyone anything.",
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90130401] = {
          ContentFR = "Si je bosse pas, je mange pas. C’est clair, non ?",
          DialogueId = 90130401,
          GUID = "E1A1CAEA",
          LookAt = {
            [1] = "83101:n(0)",
            [2] = "0:n(83101)"
          },
          NextDialogue = 90130403,
          SpeakNpcId = 83101,
          Subtitle = "No work, no food. What don't you get?",
          TalkActionId = {
            [1] = "83101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_04_1"
        },
        [90130403] = {
          ContentFR = "Tu sais, c’est important de te ménager un peu aussi.",
          DialogueId = 90130403,
          GUID = "E1A1CB3E",
          NextDialogue = 90130404,
          SpeakNpcId = 100001,
          Subtitle = "But it's also important to find a balance, right?"
        },
        [90130404] = {
          ContentFR = "J’aimerais bien, mais les clients, eux, s’en fichent. Tous les deux jours, c’est \"Alors, c’est fini ?\", \"Dépêche-toi un peu !\"… Toujours à me harceler. Si j’avais pas une famille à nourrir, je leur aurais déjà collé quelques bastos.",
          DialogueId = 90130404,
          GUID = "E1A1CB68",
          NextOptions = {
            [1] = 90130002,
            [2] = 90130003
          },
          SpeakNpcId = 83101,
          Subtitle = "Balance would be great, but my clients don't see it that way — always hounding me, \"Is the job done yet? Hurry up!\" Ugh, if I didn't have a family to feed, I'd punch them in their stupid faces.",
          TalkActionId = {
            [1] = "83101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Linen/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90130501] = {
          ContentFR = "La prochaine fois, va droit au but, ok ? Tes bavardages, ça me gonfle.",
          DialogueId = 90130501,
          GUID = "E1A1DB52",
          SpeakNpcId = 83101,
          Subtitle = "Keep it short and cut to the chase next time, will you? All this unnecessary mumbling is getting on my nerves.",
          VoiceName = "voice/$Locale$/char/Linen/vo_companio_01"
        },
        [90130601] = {
          ContentFR = "Bonjour, madame...",
          DialogueId = 90130601,
          GUID = "E1A1EBBA",
          SpeakNpcId = 83101,
          Subtitle = "Good day, ma'am...",
          VoiceName = "voice/$Locale$/char/Linen/vo_companio_02"
        },
        [90130701] = {
          ContentFR = "T’es un bon soldat, ça c’est dit. Et… profite un peu de la vie aussi, hein ? Allez, assez causé, va-t’en.",
          DialogueId = 90130701,
          GUID = "E1A1FC22",
          SpeakNpcId = 83101,
          Subtitle = "You're a top soldier. That's all I've got to say. Also... make sure you look after yourself in your downtime. Chop-chop, you've heard enough, now get out of here.",
          VoiceName = "voice/$Locale$/char/Linen/vo_companio_03"
        },
        [90150000] = {
          ContentFR = "♪ Mon tout petit foyer... niché parmi les feuilles nouvelles, au creux d’un fleuve d’or... Le feu danse dans la cheminée, crépitant doucement... Je serre fort le soldat de plomb réparé par Papa, tandis que Maman me berce d’un chant... Dors maintenant...",
          DialogueId = 90150000,
          GUID = "E1AE5A8B",
          SpeakNpcId = 81801,
          Subtitle = "♪ What a tiny, tiny, little home... It rests in and hides in the treetops; and the magical golden river flow... Do you see that stove? The embers crackle, crackle... Papa making a toy shining so bright, and Mama humming a lullaby... Good night~",
          VoiceName = "voice/$Locale$/char/Feina/vo_idle"
        },
        [90150001] = {
          ContentFR = "Ah, c’est toi. Bonjour, comment vas-tu ?",
          DialogueId = 90150001,
          GUID = "E1AE5A8A",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextOptions = {
            [1] = 901500011,
            [2] = 901500012,
            [3] = 901500013,
            [4] = 901500014,
            [5] = 901500015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81801,
          Subtitle = "...Ah, it's you. Hello, how are you?",
          VoiceName = "voice/$Locale$/char/Feina/vo_welcome",
          bForbidSkipOptions = true
        },
        [90150002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90150002,
          GUID = "90150002.0",
          NextDialogue = 90150001,
          Subtitle = "Let's talk about something else"
        },
        [90150003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90150003,
          GUID = "90150003.0",
          Subtitle = "Goodbye"
        },
        [90150101] = {
          ContentFR = "Hmm, je me demandais... s’il existait un bonbon qui pourrait me faire énormément grandir...",
          DialogueId = 90150101,
          GUID = "E1AE6AF2",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150103,
          SpeakNpcId = 81801,
          Subtitle = "Um, I was wondering... if there were a candy that could make me grow very tall...",
          TalkActionId = {
            [1] = "81801:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_01_1"
        },
        [90150103] = {
          ContentFR = "Si grande que je pouvais voir au-dessus des nuages et même toucher les étoiles !",
          DialogueId = 90150103,
          GUID = "E1AE6B46",
          NextDialogue = 90150104,
          SpeakNpcId = 81801,
          Subtitle = "So tall that I could see above the clouds and even touch the stars!",
          TalkActionId = {
            [1] = "81801:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_01_2"
        },
        [90150104] = {
          ContentFR = "Mais que se passerait-il si tu me marchais dessus accidentellement et m’aplatissais comme une crêpe...",
          DialogueId = 90150104,
          GUID = "E1AE6B70",
          NextDialogue = 90150105,
          SpeakNpcId = 100001,
          Subtitle = "But what if you accidentally stepped on me and flattened me like a pancake..."
        },
        [90150105] = {
          ContentFR = "Ne t’inquiète pas, je ferai attention ! Et si tu as peur, tu peux te poser dans ma paume, et on ira faire un tour. Qu’en penses-tu ?",
          DialogueId = 90150105,
          GUID = "E1AE6B9A",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          Subtitle = "I'd walk carefully, I promise! Well... if you're really worried, you could perch on my hand and we'll go for a spin. What do you think?",
          TalkActionId = {
            [1] = "81801:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90150201] = {
          ContentFR = "J’ai une grande boîte en verre remplie de neige fine provenant de l’extérieur de ma fenêtre et de guimauves aussi blanches que la neige. J’aimerais également y mettre des nuages aussi moelleux que ces guimauves, et des brises aussi chaudes que ces nuages...",
          DialogueId = 90150201,
          GUID = "E1AE7B5A",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150203,
          SpeakNpcId = 81801,
          Subtitle = "I have a big glass chest filled with the soft snow from outside my window and marshmallows as white as the snow. I'd also like to put in clouds as fluffy as those marshmallows, and breezes as warm as those clouds...",
          TalkActionId = {
            [1] = "81801:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_1"
        },
        [90150203] = {
          ContentFR = "Et vos rires aussi, tous sans exception, enfermés dans la boîte.",
          DialogueId = 90150203,
          GUID = "E1AE7BAE",
          NextDialogue = 90150204,
          SpeakNpcId = 81801,
          Subtitle = "And our giggles and chuckles in there too, every single one~",
          TalkActionId = {
            [1] = "81801:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_2"
        },
        [90150204] = {
          ContentFR = "Ouah... ça doit être divin de se blottir à l'intérieur.",
          DialogueId = 90150204,
          GUID = "E1AE7BD8",
          NextDialogue = 90150205,
          SpeakNpcId = 100001,
          Subtitle = "Wow... it must be heavenly to nestle inside."
        },
        [90150205] = {
          ContentFR = "Eh bien... si tu croques un de ces bonbons qui te font tout petit, tu pourrais y entrer. Mais tout est blanc là-dedans, alors fais bien attention à ne pas te perdre.",
          DialogueId = 90150205,
          GUID = "E1AE7C02",
          NextDialogue = 90150206,
          SpeakNpcId = 81801,
          Subtitle = "Well... if you nibble one of those candies that shrinks you down tiny, you could get in for a visit. But everything's white in there, so be careful not to wander off and lose your way.",
          TalkActionId = {
            [1] = "81801:Agree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_3"
        },
        [90150206] = {
          ContentFR = "Si je me perds là-bas, Fina viendra-t-elle me chercher ?",
          DialogueId = 90150206,
          GUID = "E1AE7C2C",
          NextDialogue = 90150207,
          SpeakNpcId = 100001,
          Subtitle = "If I do get lost in there, will Fina come to find me?",
          TalkActionId = {
            [1] = "81801:Think_Start"
          }
        },
        [90150207] = {
          ContentFR = "Laisse-moi réfléchir... Si tu te perds, je casserai du pain en miettes, je ferai un chemin... Tu n’auras qu’à suivre les miettes pour retrouver la sortie !",
          DialogueId = 90150207,
          GUID = "E1AE7C56",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          Subtitle = "Mmm... If you get lost, I'll scatter breadcrumbs in a trail for you... Follow them and you'll find the way out!",
          TalkActionId = {
            [1] = "81801:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90150301] = {
          ContentFR = "Oui... ! J'ai rêvé d’un rossignol, pur comme la neige immaculée, qui se posait sur ma main un instant, puis jouait à cache-cache avec moi l’instant d’après... Hmm, est-ce moi qui ai rêvé, ou est-ce lui qui a rêvé de moi, je me le demande ?",
          DialogueId = 90150301,
          GUID = "E1AE8BC2",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150303,
          SpeakNpcId = 81801,
          Subtitle = "Mm-hmm! I dreamed of a nightingale, pure as driven snow, resting on my hand one moment, and playing hide-and-seek with me the next... Hmm, was it me who dreamed, or did it dream of me, I wonder?",
          TalkActionId = {
            [1] = "81801:Agree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_03_1"
        },
        [90150303] = {
          ContentFR = "Peut-être que vous avez partagé un même rêve ?",
          DialogueId = 90150303,
          GUID = "E1AE8C16",
          NextDialogue = 90150304,
          SpeakNpcId = 100001,
          Subtitle = "Perhaps you both visited the same dreamland."
        },
        [90150304] = {
          ContentFR = "Tu as raison ! C’est peut-être un pays magique où tous les enfants et les petites bêtes endormis peuvent jouer ensemble. Hmm... Qui vais-je rencontrer dans mon prochain rêve ? Grand-père Hibou, Mademoiselle Canari, ou Monsieur Lapin ?",
          DialogueId = 90150304,
          GUID = "E1AE8C40",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          Subtitle = "You might be right! Maybe it's a wonderland where all the sleeping children and little animals can play together. Hmm... I wonder who I'll meet in my next dream — Owl the Wise, Miss Canary, or Sir Rabbit?",
          TalkActionId = {
            [1] = "81801:Agree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90150401] = {
          ContentFR = "J’avais une maman et deux papas. Mais ils ne sont plus là...",
          DialogueId = 90150401,
          GUID = "E1AE9C2A",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150402,
          SpeakNpcId = 81801,
          Subtitle = "I used to have a mum and two dads. But they've all gone...",
          TalkActionId = {
            [1] = "81801:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_04_1"
        },
        [90150402] = {
          ContentFR = "Le premier papa est parti dans un pays lointain avec maman. Et le deuxième... il est aussi dans ce pays lointain... C’est moi qui l’ai envoyé là-bas.",
          DialogueId = 90150402,
          GUID = "E1AE9C54",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          Subtitle = "The first dad went to a faraway land with mum. And the second one... he's in that faraway land too... I sent him there.",
          TalkActionId = {
            [1] = "81801:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90150501] = {
          ContentFR = "Il est le plus grand magicien, avec la voix la plus apaisante et l’âme la plus douce au monde...",
          DialogueId = 90150501,
          GUID = "E1AEAC92",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150503,
          SpeakNpcId = 81801,
          Subtitle = "He's the greatest magician, with the most soothing voice and the gentlest soul in the world...",
          TalkActionId = {
            [1] = "81801:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_05_1"
        },
        [90150503] = {
          ContentFR = "?",
          DialogueId = 90150503,
          GUID = "E1AEACE6",
          NextDialogue = 90150504,
          SpeakNpcId = 100001,
          Subtitle = "?",
          TalkActionId = {
            [1] = "81801:Explain02_End"
          }
        },
        [90150504] = {
          ContentFR = "Euh, qu’est-ce qui ne va pas ? Tu as l’air perplexe.",
          DialogueId = 90150504,
          GUID = "E1AEAD10",
          NextDialogue = 90150505,
          SpeakNpcId = 81801,
          Subtitle = "Er, what's wrong? You look very confused.",
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_05_2"
        },
        [90150505] = {
          ContentFR = "Ce n’est pas du tout l’Étranger que je connais !",
          DialogueId = 90150505,
          GUID = "E1AEAD3A",
          NextDialogue = 90150506,
          SpeakNpcId = 100001,
          Subtitle = "This is so not the Outsider I know!"
        },
        [90150506] = {
          ContentFR = "Hein... ? Il n’est pas gentil avec toi ? Je suis désolée... Je vais lui donner un petit coup sur la tête pour qu’il s’améliore !",
          DialogueId = 90150506,
          GUID = "E1AEAD64",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          Subtitle = "Huh...? You mean he's not kind or gentle to you? I'm so sorry... I'll give him a little tap on his head and ask him to be nicer!",
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90150601] = {
          ContentFR = "Promets-moi que tu n’iras jamais, jamais, jamais... dans cet endroit effrayant où il y a plein de mauvais sorciers, d’accord ?",
          DialogueId = 90150601,
          GUID = "E1AEBCFA",
          SpeakNpcId = 81801,
          Subtitle = "Promise me that you'll never, ever, ever... go to that scary place with lots and lots of bad sorcerers, okay?",
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_01"
        },
        [90150701] = {
          ContentFR = "Qu’est-ce que c’est ? Ton petit esprit, Mlle Hamster ? Incroyable... Il doit pouvoir te porter et t’emporter au-dessus des murailles de tous les châteaux !",
          DialogueId = 90150701,
          GUID = "E1AECD62",
          SpeakNpcId = 81801,
          Subtitle = "What's that? Is it your elf pet, Miss Hamster? Wow, unbelievable... It must be able to carry you as it flies over the walls of castles.",
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_02"
        },
        [90150801] = {
          ContentFR = "Dis, Mlle Lionne, tu veux réveiller la fée qui dort dans cette épée géante ? Alors il te faudra sûrement chanter des tas de sortilèges, comme : « Ô toi qui as éveillé l’épée sacrée Samaël... un jour, tu deviendras le roi d’Élysium ! »",
          DialogueId = 90150801,
          GUID = "E1AEDDCA",
          SpeakNpcId = 81801,
          Subtitle = "Miss Lioness, are you trying to wake up the fairy inside the giant sword? Perhaps you need to chant a lot of incantations, like, \"O chosen one who awoke the sacred greatsword Samael, destined to be the king of Elysium!\"",
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_03"
        },
        [90160000] = {
          ContentFR = "Cette tranquillité, ça fait drôle... j’aurais jamais cru pouvoir me sentir à ma place, même après tout ce temps.",
          DialogueId = 90160000,
          GUID = "E1B4C329",
          SpeakNpcId = 85102,
          Subtitle = "It's nice having peace of mind and a place I can feel attached to after so many years.",
          VoiceName = "voice/$Locale$/char/Aote/vo_idle"
        },
        [90160001] = {
          ContentFR = "Ah, te voilà enfin. J’ai fini tous les trucs en retard... Pas gagné un rond, et j’ai bien failli y laisser ma peau. Franchement... t’as de la chance que je vous aime bien.",
          DialogueId = 90160001,
          GUID = "E1B4C32A",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextOptions = {
            [1] = 901600011,
            [2] = 901600012,
            [3] = 901600013,
            [4] = 901600014,
            [5] = 901600015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85102,
          Subtitle = "Here you are, finally! I've finished all my chores and got absolutely knackered, but I've only earned a few quid. Urgh... You know I do much for you guys.",
          TalkActionId = {
            [1] = "85102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_welcome",
          bForbidSkipOptions = true
        },
        [90160002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90160002,
          GUID = "90160002.0",
          NextDialogue = 90160001,
          Subtitle = "Let's talk about something else"
        },
        [90160003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90160003,
          GUID = "90160003.0",
          Subtitle = "Goodbye"
        },
        [90160101] = {
          ContentFR = "Un guide ? N’y compte pas. Ici, on se fait pas aux bouquins, mais aux bonnes combines. Comme ma devise : « Deux coups dans les côtes, un à la tête, même l’empereur peut pas y faire grand-chose. »",
          DialogueId = 90160101,
          GUID = "E1B4D392",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160103,
          SpeakNpcId = 85102,
          Subtitle = "A guide? No, most folks in this trade aren't the type to stick their nose in a book. But I do have a few mottoes to share, like my personal fighting mantra: \"Two hits in the ribs, one on the head; so dead even the emperor can't pull 'em back.\"",
          TalkActionId = {
            [1] = "85102:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_01_1"
        },
        [90160103] = {
          ContentFR = "J’aime bien. T’en as d’autres dans le genre ?",
          DialogueId = 90160103,
          GUID = "E1B4D3E6",
          NextDialogue = 90160104,
          SpeakNpcId = 100001,
          Subtitle = "Interesting, got any more?",
          TalkActionId = {
            [1] = "85102:Confident_Start"
          }
        },
        [90160104] = {
          ContentFR = "Ne sois pas trop gourmand. Le plus grand danger dans ce boulot, c’est la cupidité. Parfois elle vient des autres, mais surtout de toi-même.",
          DialogueId = 90160104,
          GUID = "E1B4D410",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          Subtitle = "Don't bite off more than you can chew. In our line of work, greed is the biggest enemy — sometimes it comes from others, but more often, it comes from within.",
          TalkActionId = {
            [1] = "85102:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90160201] = {
          ContentFR = "Ce sont des braises qui refusent de s’éteindre. Suffit d’un souffle pour que tout reprenne feu. Crois-moi, mieux vaut les éviter.",
          DialogueId = 90160201,
          GUID = "E1B4E3FA",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160203,
          SpeakNpcId = 85102,
          Subtitle = "They're like a wildfire that's never fully extinguished, ready to flare up at any moment. For your own good, better keep your distance...",
          TalkActionId = {
            [1] = "85102:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_02_1"
        },
        [90160203] = {
          ContentFR = "T’as l’air bien tendu. C’est si grave que ça ?",
          DialogueId = 90160203,
          GUID = "E1B4E44E",
          NextDialogue = 90160204,
          SpeakNpcId = 100001,
          Subtitle = "Why? What's it to me?",
          TalkActionId = {
            [1] = "85102:Talk03_End"
          }
        },
        [90160204] = {
          ContentFR = "Disons... qu’on a eu quelques accrochages. Si jamais tu les croises, surtout, dis pas que tu me connais.",
          DialogueId = 90160204,
          GUID = "E1B4E478",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          Subtitle = "Well... let's just say we've had our little scuffles. If you ever deal with them, make sure my name doesn't come up.",
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90160301] = {
          ContentFR = "Ouais. Tu peux me passer ce bandage là-bas ? Si Fina le voit, elle va encore faire toute une histoire.",
          DialogueId = 90160301,
          GUID = "E1B4F462",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160303,
          SpeakNpcId = 85102,
          Subtitle = "Yeah. Can you grab that bandage over there for me? I need to keep it from Fina, or she'll make a big fuss again.",
          TalkActionId = {
            [1] = "85102:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_03_1"
        },
        [90160303] = {
          ContentFR = "Elle s’inquiète pour toi, c’est normal.",
          DialogueId = 90160303,
          GUID = "E1B4F4B6",
          NextDialogue = 90160304,
          SpeakNpcId = 100001,
          Subtitle = "She's just concerned about you.",
          TalkActionId = {
            [1] = "85102:Explain02_End"
          }
        },
        [90160304] = {
          ContentFR = "Je sais, mais les blessures font partie du métier. Je préfère qu’elle ne s’inquiète pas trop. Tu peux me couvrir si elle me pose des questions ? Je te revaudrai ça.",
          DialogueId = 90160304,
          GUID = "E1B4F4E0",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          Subtitle = "I know, but injuries are part of the job. I'd rather she not worry so much. Cover for me if she asks, will you? I owe you one.",
          TalkActionId = {
            [1] = "85102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90160401] = {
          ContentFR = "Oh, tu veux tester ? Ils sont moches mais une fois la tête enlevée, ça croustille comme un biscuit... avec un petit arrière-goût de viande.",
          DialogueId = 90160401,
          GUID = "E1B504CA",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160403,
          SpeakNpcId = 85102,
          Subtitle = "Oh, would you like some? Don't mind their looks — just pop off the head, and they're crunchy like cookies, even with a hint of meaty aftertaste...",
          TalkActionId = {
            [1] = "85102:Give"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_04_1"
        },
        [90160403] = {
          ContentFR = "(Fait demi-tour et prend la fuite.)",
          DialogueId = 90160403,
          GUID = "E1B5051E",
          NextDialogue = 90160404,
          SpeakNpcId = 100001,
          Subtitle = "(Turn around and run)"
        },
        [90160404] = {
          ContentFR = "Hé ! Reviens ! C’est des conseils de survie... Si tu te perds dans la nature sans nourriture, ces petites bêtes pourraient te sauver la vie.",
          DialogueId = 90160404,
          GUID = "E1B50548",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          Subtitle = "Wha... where are you going!? This is vital survival wisdom... If you got lost in the wild with no food, these little critters could be a lifesaver.",
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90160501] = {
          ContentFR = "Attends... Pourquoi t’as presque rien ? Me dis pas que t’as encore filé ta paie aux autres ?",
          DialogueId = 90160501,
          GUID = "E1B51532",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160503,
          SpeakNpcId = 85102,
          Subtitle = "Wait a sec, why do you only have a few coins in your hand? Did you give away your share of the bounty again?",
          TalkActionId = {
            [1] = "85102:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_05_1"
        },
        [90160503] = {
          ContentFR = "Ils en avaient plus besoin que moi.",
          DialogueId = 90160503,
          GUID = "E1B51586",
          NextDialogue = 90160504,
          SpeakNpcId = 100001,
          Subtitle = "They needed the money more than I did.",
          TalkActionId = {
            [1] = "85102:Confident_End"
          }
        },
        [90160504] = {
          ContentFR = "Mais... Peu importe, c’est tout toi, toujours {性别:prêt|prête} à aider les autres. Fais-moi signe si jamais tu as besoin d'argent.",
          DialogueId = 90160504,
          GUID = "E1B515B0",
          NextDialogue = 90160505,
          SpeakNpcId = 85102,
          Subtitle = "But... Never mind, this is you, always looking out for others. Let me know if you're ever short on cash.",
          TalkActionId = {
            [1] = "85102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_05_2"
        },
        [90160505] = {
          ContentFR = "Ah, bah voilà, je suis fauché !",
          DialogueId = 90160505,
          GUID = "E1B515DA",
          NextDialogue = 90160506,
          SpeakNpcId = 100001,
          Subtitle = "Actually, I'm short right now."
        },
        [90160506] = {
          ContentFR = "... Je t’aide en tant qu’ami, pas pour que tu m’arnaques !",
          DialogueId = 90160506,
          GUID = "E1B51604",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          Subtitle = "...You're milking it, buddy.",
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90160601] = {
          Content = "你怎么也在这儿？身体不要紧吗，病没问题吗，饭吃过了吗？哎……有什么想要的给我说就好，没事还是不要瞎跑了。",
          DialogueId = 90160601,
          GUID = "E1B5259A",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_01"
        },
        [90160701] = {
          ContentFR = "C’est toi, la fille proche de {nickname}, c’est ça ? J’ai entendu que t’étais pas en forme. Tu devrais t’asseoir un moment.",
          DialogueId = 90160701,
          GUID = "E1B53602",
          NextDialogue = 90160702,
          SpeakNpcId = 85102,
          Subtitle = "You're the girl who's very close to , right? I heard you've been feeling unwell. Do you want to sit down and have a rest?",
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_02_1"
        },
        [90160702] = {
          ContentFR = "Si t’as faim, soif, ou besoin de quoi que ce soit, dis-le-moi. J’ai l’habitude de veiller sur les autres... Ma petite sœur est malade, alors tu sais, je gère. Et puis, une amie de {nickname}, c’est aussi une amie à moi.",
          DialogueId = 90160702,
          GUID = "E1B5362C",
          SpeakNpcId = 85102,
          Subtitle = "If you're hungry, thirsty, or need anything, just say the word. It's no bother — I look after my sickly sister back home all the time. A friend of 's is a friend of mine.",
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_02_2"
        },
        [90170000] = {
          ContentFR = "Hmm, quel temps magnifique, parfait pour cueillir des fleurs et sentir bon après ! {nickname}, tu veux venir te balader avec moi ?",
          DialogueId = 90170000,
          GUID = "E1BB2BC9",
          SpeakNpcId = 83301,
          Subtitle = "Aww~ What a lovely day! Perfect for picking flowers, and I'd smell great after that~ Care to join me?",
          VoiceName = "voice/$Locale$/char/Maer/vo_idle"
        },
        [90170001] = {
          ContentFR = "En arrivant, j’ai dégagé la neige devant ta porte ! Touchée ? Ça mérite bien un chocolat chaud, non ?",
          DialogueId = 90170001,
          GUID = "E1BB2BCA",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextOptions = {
            [1] = 901700011,
            [2] = 901700012,
            [3] = 901700013,
            [4] = 901700014,
            [5] = 901700015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83301,
          Subtitle = "I've cleared the snow from your doorstep on my way here! Touched, huh? Bet you're thinking of treating me to a cup of cocoa~",
          VoiceName = "voice/$Locale$/char/Maer/vo_welcome",
          bForbidSkipOptions = true
        },
        [90170002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90170002,
          GUID = "90170002.0",
          NextDialogue = 90170001,
          Subtitle = "Let's talk about something else"
        },
        [90170003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90170003,
          GUID = "90170003.0",
          Subtitle = "Goodbye"
        },
        [90170101] = {
          ContentFR = "Eh bien... il s’agit de donner une nouvelle vie aux objets mis au rebut et d’offrir à ceux qui en ont besoin une chance d’avoir une vie meilleure.",
          DialogueId = 90170101,
          GUID = "E1BB3C32",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170103,
          SpeakNpcId = 83301,
          Subtitle = "Well... it's about giving discarded items a new home and providing those in need with a chance at a better life.",
          TalkActionId = {
            [1] = "83301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_1"
        },
        [90170103] = {
          ContentFR = "Et comment fait-on cela ?",
          DialogueId = 90170103,
          GUID = "E1BB3C86",
          NextDialogue = 90170104,
          SpeakNpcId = 100001,
          Subtitle = "And how's that done?"
        },
        [90170104] = {
          ContentFR = "Par exemple, transformer les rideaux de velours dont se sont débarrassés des aristocrates en manteaux d’hiver chauds pour les personnes âgées, ou apporter des poupées jetées à des enfants dont les seuls jouets sont des cailloux. Ils seront ravis pendant longtemps.",
          DialogueId = 90170104,
          GUID = "E1BB3CB0",
          NextDialogue = 90170105,
          SpeakNpcId = 83301,
          Subtitle = "For instance, turning an aristocrat's cast-off velvet curtains into warm winter coats for the elderly, or bringing discarded dolls to children whose only playthings are pebbles — they'll be overjoyed for a long time.",
          TalkActionId = {
            [1] = "83301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_2"
        },
        [90170105] = {
          ContentFR = "Une fois, j’ai ramené une vieille bibliothèque toute cassée que quelqu’un avait jetée. J’étais épuisée à en tomber, mais rapidement, elle est devenue un terrain de jeu pour une portée de chatons et leurs mamans, ils y ont joué du lever au coucher du soleil. Ça en valait vraiment la peine !",
          DialogueId = 90170105,
          GUID = "E1BB3CDA",
          NextDialogue = 90170106,
          SpeakNpcId = 83301,
          Subtitle = "There was one time, I dragged back a broken bookshelf someone had thrown out. Though I was half-dead from the effort, it quickly turned into a non-stop playground for a litter of kittens — totally worth it!",
          TalkActionId = {
            [1] = "83301:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_3"
        },
        [90170106] = {
          ContentFR = "Voilà ce que c’est que d’être récupérateur ! Ce sont surtout des petites choses, mais on ne s’ennuie jamais. Alors, qu’en dis-tu, tu veux te joindre à nous ?",
          DialogueId = 90170106,
          GUID = "E1BB3D04",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          Subtitle = "That's scavenging for you! It's mostly small fry stuff, but never a dull moment. So, what do you say, wanna join us?",
          TalkActionId = {
            [1] = "83301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90170201] = {
          ContentFR = "Chuuuut ! C’est un secret bien gardé des récupérateurs ! Je ne t’aurais pas mis dans la confidence si tu ne m’avais pas aidé à attraper ce voleur !",
          DialogueId = 90170201,
          GUID = "E1BB4C9A",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170203,
          SpeakNpcId = 83301,
          Subtitle = "Shhhh! That's a scavenger's top secret! I wouldn't have let you in on it if you hadn't helped me out with that thief!",
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_1"
        },
        [90170203] = {
          ContentFR = "Cette carte répertorie toutes les poubelles de Givrelac. J’y ai noté celles où on trouve les meilleurs trésors. J’ai même remplacé ces poubelles par des modèles plus grands, et je calcule précisément le meilleur moment pour y passer.",
          DialogueId = 90170203,
          GUID = "E1BB4CEE",
          NextDialogue = 90170204,
          SpeakNpcId = 83301,
          Subtitle = "This map charts every rubbish bin in Icelake, and I've marked the few where the best stuff tends to gather — I've upgraded those bins to larger sizes and timed my visits to perfection!",
          TalkActionId = {
            [1] = "83301:Give"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_2"
        },
        [90170204] = {
          ContentFR = "Mais ce métier dépend beaucoup de la chance, la plupart du temps c’est du hasard...",
          DialogueId = 90170204,
          GUID = "E1BB4D18",
          NextDialogue = 90170205,
          SpeakNpcId = 83301,
          Subtitle = "But scavenging is really hit-or-miss — mostly, it all comes down to luck...",
          TalkActionId = {
            [1] = "83301:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_3"
        },
        [90170205] = {
          ContentFR = "La récupération des déchets n’est pas une partie de plaisir, c’est certain...",
          DialogueId = 90170205,
          GUID = "E1BB4D42",
          NextDialogue = 90170206,
          SpeakNpcId = 100001,
          Subtitle = "Scavenging's no picnic, that's for sure...",
          TalkActionId = {
            [1] = "83301:Sigh_End"
          }
        },
        [90170206] = {
          ContentFR = "Ah, je savais que tu comprendrais !",
          DialogueId = 90170206,
          GUID = "E1BB4D6C",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          Subtitle = "Ha, I knew you'd understand!",
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90170301] = {
          ContentFR = "Non, pas du tout ! J’adore Givrelac de tout mon cœur. C’est juste que je repense souvent aux jours où je parcourais les champs de neige avec mon père, c'est comme ça que j’ai grandi.",
          DialogueId = 90170301,
          GUID = "E1BB5D02",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170303,
          SpeakNpcId = 83301,
          Subtitle = "Oh, you've got it backwards! I love Icelake through and through. It's just that I often reminisce about the days I spent wandering the snowfields with my dad; that's how I grew up.",
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_1"
        },
        [90170303] = {
          ContentFR = "Que penses-tu de ces moments ?",
          DialogueId = 90170303,
          GUID = "E1BB5D56",
          NextDialogue = 90170304,
          SpeakNpcId = 100001,
          Subtitle = "How do you feel about those days?",
          TalkActionId = {
            [1] = "83301:Agree"
          }
        },
        [90170304] = {
          ContentFR = "D’ici, les champs de neige ressemblent à un paysage de conte de fées. Mais une fois que tu y mets les pieds, tu te sens tout petit. Tu peux marcher pendant des heures dans la neige jusqu’aux genoux, cette sensation ne te quitte jamais.",
          DialogueId = 90170304,
          GUID = "E1BB5D80",
          NextDialogue = 90170305,
          SpeakNpcId = 83301,
          Subtitle = "From here, the snowfields look like something out of a fairy tale. But once you step into it, you'd feel so very small. Even after trudging through knee-high snow for hours, that feeling would never leave.",
          TalkActionId = {
            [1] = "83301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_2"
        },
        [90170305] = {
          ContentFR = "Je ne déteste pas ces moments-là. Mais Givrelac animé et vivant est mon préféré !",
          DialogueId = 90170305,
          GUID = "E1BB5DAA",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          Subtitle = "I don't hate those days. But the bustling, lively Icelake is my absolute favourite!",
          TalkActionId = {
            [1] = "83301:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90170401] = {
          ContentFR = "C’est le gros chat qui me suivait dans les champs enneigés quand j’étais petite ! On l’appelait Touffu. Il ne me laissait le caresser qu’en échange d’un peu de viande séchée, mais sa fourrure... oh là là, c’est un vrai bonheur, hé hé hé, la meilleure qui soit !",
          DialogueId = 90170401,
          GUID = "E1BB6D6A",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170403,
          SpeakNpcId = 83301,
          Subtitle = "That's the big cat that used to roam the snowfields with me when I was little! We called him \"Plumpytail\". He would only let me pet him in exchange for some jerky, but oh, the feel of his fur — hehehe, it's the best of the best!",
          TalkActionId = {
            [1] = "83301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_04_1"
        },
        [90170403] = {
          ContentFR = "Quel est le cri d’un gros chat des neiges ? Ressemble-t-il davantage à celui d’un chat ou d’un tigre ?",
          DialogueId = 90170403,
          GUID = "E1BB6DBE",
          NextDialogue = 90170404,
          SpeakNpcId = 100001,
          Subtitle = "What does a big snowfield cat sound like? More like a cat or a tiger?",
          TalkActionId = {
            [1] = "83301:Explain02_End"
          }
        },
        [90170404] = {
          ContentFR = "Mmmh... ce n’est sûrement pas un « miaou miaou », c’est plutôt un « grrraou, grrraou, grrraou » !",
          DialogueId = 90170404,
          GUID = "E1BB6DE8",
          NextDialogue = 90170405,
          SpeakNpcId = 83301,
          Subtitle = "Mmm... it's certainly not like \"meow\"; it's more like, \"raawr—raawr—!\"",
          TalkActionId = {
            [1] = "83301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_04_2"
        },
        [90170405] = {
          ContentFR = "Est-ce que Touffu est toujours dans le coin ?",
          DialogueId = 90170405,
          GUID = "E1BB6E12",
          NextDialogue = 90170406,
          SpeakNpcId = 100001,
          Subtitle = "Is Plumpytail still around?",
          TalkActionId = {
            [1] = "83301:Think_End"
          }
        },
        [90170406] = {
          ContentFR = "Touffu préfère la vie sauvage à la vie urbaine. Nous avons dû nous séparer, mais elle fera toujours partie de moi, tout comme les champs de neige.",
          DialogueId = 90170406,
          GUID = "E1BB6E3C",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          Subtitle = "Plumpytail prefers the wild over city life. We had to go our separate ways, but she'll always be a part of me, just like the snowfields.",
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90170501] = {
          ContentFR = "Non, non ! Ce n’est pas moi ! Je suis trop grande pour un titre aussi enfantin ! Je t’en supplie, ne m’appelle plus jamais comme ça !",
          DialogueId = 90170501,
          GUID = "E1BB7DD2",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170503,
          SpeakNpcId = 83301,
          Subtitle = "Nah-uh! That's not me! I'm too grown up for such a childish title! Please, I beg of you, don't ever call me that again!",
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_05_1"
        },
        [90170503] = {
          ContentFR = "Alors comment veux-tu qu’on t’appelle ?",
          DialogueId = 90170503,
          GUID = "E1BB7E26",
          NextDialogue = 90170504,
          SpeakNpcId = 100001,
          Subtitle = "Then how would you like to be referred to?"
        },
        [90170504] = {
          ContentFR = "Hem hem... Dame Margie, la détective taciturne, la solitaire qui arpente les ruelles de la ville ! Aujourd’hui encore, je vais te révéler les secrets cachés de Givrelac !",
          DialogueId = 90170504,
          GUID = "E1BB7E50",
          NextDialogue = 90170505,
          SpeakNpcId = 83301,
          Subtitle = "Ahem, that would be — Lady Margie the reticent detective, a lone shadow-walker of the city! Today, I will unveil for you the secrets of Icelake, as always!",
          TalkActionId = {
            [1] = "83301:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_05_2"
        },
        [90170505] = {
          ContentFR = "Hé hé, voilà un titre qui me va bien !",
          DialogueId = 90170505,
          GUID = "E1BB7E7A",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          Subtitle = "Hehe, now that's a proper title for me~",
          TalkActionId = {
            [1] = "83301:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90170701] = {
          ContentFR = "Petite Fina ! Ça fait une éternité. Tu veux connaître la suite de \"Flocon la Ranger et Gingembre la Détective\" ? Parfait ! Je vais chercher un petit tabouret et te raconter ça tranquillement !",
          DialogueId = 90170701,
          GUID = "E1BB9EA2",
          SpeakNpcId = 83301,
          Subtitle = "Little Fina! It's been ages~ Wanna hear the next chapter of \"Snowball the Cat Ranger & Ginger the Cat Detective\"? No problem! Let me just grab a stool and settle in for a good tale!",
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_02"
        },
        [90170801] = {
          ContentFR = "Je vous assure, Madame la geôlière, que je suis une citoyenne respectable ! Je n’ai jamais volé ni pillé, je me contente juste de récupérer quelques restes dans les poubelles pour calmer ma faim. Même votre zèle ne va pas jusqu’aux ordures, si ?",
          DialogueId = 90170801,
          GUID = "E1BBAF0A",
          SpeakNpcId = 83301,
          Subtitle = "I assure you I'm an upstanding citizen, Ms Warden! Never pilfered or plundered, merely collecting some scraps from the bins to quiet my stomach. Even your dedication doesn't extend to rubbish, does it?",
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_03"
        },
        [90170901] = {
          ContentFR = "Tu vis au jour le jour, n’est-ce pas... ? C’est vraiment difficile. Tu veux venir avec moi faire un peu de récupération ? Ça pourrait te faciliter un peu les choses...",
          DialogueId = 90170901,
          GUID = "E1BBBF72",
          SpeakNpcId = 83301,
          Subtitle = "You're living hand to mouth, aren't you...? That's really tough. Would you like to join me in scavenging? Might make things a bit easier...",
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_04"
        },
        [90180000] = {
          ContentFR = "Yale : Le ch-chasseur... s-sachant ch... chasse sans s... son ch-ch-chapeau...",
          DialogueId = 90180000,
          GUID = "E1C19467",
          NextDialogue = 90180002,
          SpeakNpcId = 83103,
          Subtitle = "Yale: Peter Piker p-picked a peck of p-p-peckled peppers...",
          VoiceName = "voice/$Locale$/char/Yeer/vo_idle_1"
        },
        [90180001] = {
          ContentFR = "Yale : T-Te voilà... Il fait si beau aujourd’hui... Parfait pour quelques expériences explosives... V-Vraiment une belle journée...",
          DialogueId = 90180001,
          GUID = "E1C1946A",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextOptions = {
            [1] = 901800011,
            [2] = 901800012,
            [3] = 901800013,
            [4] = 901800014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83103,
          Subtitle = "Yale: Hi... Such a nice day, isn't it... Perfect for some explosive experiments... Um, what a nice day.",
          TalkActionId = {
            [1] = "83103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_welcome",
          bForbidSkipOptions = true
        },
        [90180002] = {
          ContentFR = "Oliver : T’es sérieux ? C’est « Un chasseur sachant chasser sans son chien... » Allez, recommence !",
          DialogueId = 90180002,
          GUID = "E1C19468",
          NextDialogue = 90180003,
          SpeakNpcId = 83103,
          Subtitle = "Oliver: It's \"Peter Piper picked a peck of pickled peppers!\" Come on, Yale, keep up!",
          VoiceName = "voice/$Locale$/char/Yeer/vo_idle_2"
        },
        [90180003] = {
          ContentFR = "Yale : D-d’accord... un chass... chasseur... chassant… sans... chien...",
          DialogueId = 90180003,
          GUID = "E1C19469",
          SpeakNpcId = 83103,
          Subtitle = "Yale: O-Okay! P-Peter Piker p-picked...",
          VoiceName = "voice/$Locale$/char/Yeer/vo_idle_3"
        },
        [90180004] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90180004,
          GUID = "90180004.0",
          NextDialogue = 90180001,
          Subtitle = "Let's talk about something else"
        },
        [90180005] = {
          ContentFR = "À bientôt.",
          DialogueId = 90180005,
          GUID = "90180005.0",
          Subtitle = "Goodbye"
        },
        [90180101] = {
          ContentFR = "Yale : Oliver n’est pas une bombe qui parle... C-C’est peut-être dur à croire, mais... en fait, il est... ",
          DialogueId = 90180101,
          GUID = "E1C1A4D2",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180103,
          SpeakNpcId = 83103,
          Subtitle = "Yale: Oliver is not a talking bomb... It might sound strange, but... he's actually...",
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_1"
        },
        [90180103] = {
          ContentFR = "Oliver : Tais-toi, tu vas me faire péter un fusible ! Moi, c’est Yale. Et Yale, c’est moi. Tu piges ? Non ? Bah, je me doute que t’as pas les neurones pour.",
          DialogueId = 90180103,
          GUID = "E1C1A526",
          NextDialogue = 90180104,
          SpeakNpcId = 83103,
          Subtitle = "Oliver: Ugh, you're killing me here! I am Yale, and Yale is me. Got it? Not that I'd expect someone with your pea-sized brain to understand.",
          TalkActionId = {
            [1] = "83103:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_2"
        },
        [90180104] = {
          ContentFR = "Quelle bombe grossière, tu devrais peut-être t’en débarrasser.",
          DialogueId = 90180104,
          GUID = "E1C1A550",
          NextDialogue = 90180105,
          SpeakNpcId = 100001,
          Subtitle = "What a rude bomb, maybe you should get rid of it.",
          TalkActionId = {
            [1] = "83103:Angry01_End"
          }
        },
        [90180105] = {
          ContentFR = "Yale : Oliver est en fait très g-gentil ! Même s’il a l’air grognon, parle un peu fort... et surgit s-souvent sans prévenir... mais...",
          DialogueId = 90180105,
          GUID = "E1C1A57A",
          NextDialogue = 90180106,
          SpeakNpcId = 83103,
          Subtitle = "Yale: Oliver's a-a-actually a nice guy! He might s-seem a bit rough, and mean, a-and likes to pop up out of the b-blue, but...",
          TalkActionId = {
            [1] = "83103:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_3"
        },
        [90180106] = {
          ContentFR = "Oliver : Hé, c’est censé être un compliment, ça ?",
          DialogueId = 90180106,
          GUID = "E1C1A5A4",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          Subtitle = "Oliver: Hey! That's your idea of nice words?",
          TalkActionId = {
            [1] = "83103:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90180201] = {
          ContentFR = "Yale : J-je suis pas très utile... Mon seul vrai talent, c’est de fabriquer des... P’tits Boum...",
          DialogueId = 90180201,
          GUID = "E1C1B53A",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180203,
          SpeakNpcId = 83103,
          Subtitle = "Yale: I... I might not be much help. The only thing I'm good at... is probably making Tot Poppers...",
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_02_1"
        },
        [90180203] = {
          ContentFR = "Hmm ? Qu’est-ce qu’un P’tit Boum ?",
          DialogueId = 90180203,
          GUID = "E1C1B58E",
          NextDialogue = 90180204,
          SpeakNpcId = 100001,
          Subtitle = "Hmm? What's a Tot Popper?"
        },
        [90180204] = {
          ContentFR = "Les P’tits Boum, c’est ce qu’on vend le plus chez Crac’n’Pop... et c’est super long à fabriquer...",
          DialogueId = 90180204,
          GUID = "E1C1B5B8",
          NextDialogue = 90180205,
          SpeakNpcId = 83103,
          Subtitle = "Yale: They're the most popular items at our \"Snap 'n' Spark\" toy store... They take a lot of time to make.",
          TalkActionId = {
            [1] = "83103:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_02_2"
        },
        [90180205] = {
          ContentFR = "Yale : M-Mais c’est pas parce que je suis doué... C’est grâce à Oliver, il connaît tout par cœur.",
          DialogueId = 90180205,
          GUID = "E1C1B5E2",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          Subtitle = "Yale: But it's not because I'm skilled... It's all thanks to Oliver's expertise.",
          TalkActionId = {
            [1] = "83103:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90180301] = {
          ContentFR = "Yale : Ah, d-désolé ! S-Si je parle trop vite... ma langue s’emmêle...",
          DialogueId = 90180301,
          GUID = "E1C1C5A2",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180303,
          SpeakNpcId = 83103,
          Subtitle = "Yale: Ah, sorry! B-But if I start speaking fast, my tongue tends to get all t-t-tied up.",
          TalkActionId = {
            [1] = "83103:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_03_1"
        },
        [90180303] = {
          ContentFR = "Cela doit être difficile pour toi de communiquer avec les autres alors.",
          DialogueId = 90180303,
          GUID = "E1C1C5F6",
          NextDialogue = 90180304,
          SpeakNpcId = 100001,
          Subtitle = "It must be hard for you to communicate with others then.",
          TalkActionId = {
            [1] = "83103:Sigh_End"
          }
        },
        [90180304] = {
          ContentFR = "Yale : Ç-Ça va... Parfois, c’est Oliver qui parle pour moi... Et quand y’a personne autour, il m’écoute toujours jusqu’au bout...",
          DialogueId = 90180304,
          GUID = "E1C1C620",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          Subtitle = "Yale: I-It's okay, sometimes Oliver speaks for me... And when no one else's around, Oliver would always hear me out.",
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90180401] = {
          ContentFR = "Yale : Je n’ai jamais vraiment eu d’enfance... D’aussi loin que je me souvienne, j’ai toujours été dans ce corps. Peut-être qu’Oliver, lui, en a eu une.",
          DialogueId = 90180401,
          GUID = "E1C1D60A",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180403,
          SpeakNpcId = 83103,
          Subtitle = "Yale: I never really had a \"childhood\"... From my earliest memories, I've been in this body. Oliver might have one, though.",
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_1"
        },
        [90180403] = {
          ContentFR = "Ne pas vivre pleinement son enfance, c’est un peu triste.",
          DialogueId = 90180403,
          GUID = "E1C1D65E",
          NextDialogue = 90180404,
          SpeakNpcId = 100001,
          Subtitle = "Missing out on childhood, that's kind of sad."
        },
        [90180404] = {
          ContentFR = "Yale : Je me suis souvent demandé... si j’avais eu une enfance, est-ce que... Monsieur Jones serait venu me raconter une histoire avant de dormir ? Comme un vrai papa...",
          DialogueId = 90180404,
          GUID = "E1C1D688",
          NextDialogue = 90180405,
          SpeakNpcId = 83103,
          Subtitle = "Yale: I've sometimes wondered what having a \"childhood\" would be like... Would Mr Jones have told me bedtime stories every night, like a normal dad...?",
          TalkActionId = {
            [1] = "83103:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_2"
        },
        [90180405] = {
          ContentFR = "Oliver : Jones, ce taré raconter une histoire ? T’as avalé du dissolvant ou quoi ?",
          DialogueId = 90180405,
          GUID = "E1C1D6B2",
          NextDialogue = 90180406,
          SpeakNpcId = 83103,
          Subtitle = "Oliver: You expect that jerk to tell you bedtime stories? Have you lost your mind?",
          TalkActionId = {
            [1] = "83103:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_3"
        },
        [90180406] = {
          ContentFR = "Yale : D-Désolé ! Je sais bien qu’il ne pense qu’à ses expériences... Il ferait jamais un truc comme ça...",
          DialogueId = 90180406,
          GUID = "E1C1D6DC",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          Subtitle = "Yale: S-Sorry! I-I know he only cared about his experiments... He wouldn't have done that...",
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_4",
          bForbidSkipOptions = true
        },
        [90180501] = {
          ContentFR = "Yale : B-bonjour... V-votre voix est vraiment... vraiment magnifique.",
          DialogueId = 90180501,
          GUID = "E1C1E672",
          NextDialogue = 90180502,
          SpeakNpcId = 83103,
          Subtitle = "Yale: H-hello... Your singing is really b-beautiful.",
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_01_1"
        },
        [90180502] = {
          ContentFR = "Oliver : Pff. Encore une pauvre victime.",
          DialogueId = 90180502,
          GUID = "E1C1E69C",
          SpeakNpcId = 83103,
          Subtitle = "Oliver: Hmph, just another victim.",
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_01_2"
        },
        [90180601] = {
          ContentFR = "Yale : F-Filbert... c’est ton ami ? Moi aussi j’ai un ami... aussi f-fiable que Filbert...",
          DialogueId = 90180601,
          GUID = "E1C1F6DA",
          NextDialogue = 90180602,
          SpeakNpcId = 83103,
          Subtitle = "Yale: Is Filbert... your friend? I have a good friend too. He's as r-reliable as F-Filbert.",
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_02_1"
        },
        [90180602] = {
          ContentFR = "Oliver : Tu traites qui de cochon, au juste ?",
          DialogueId = 90180602,
          GUID = "E1C1F704",
          SpeakNpcId = 83103,
          Subtitle = "Oliver: Wait, seriously?",
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_02_2"
        },
        [90180701] = {
          ContentFR = "Yale : S-S’il te plaît ne t’énerve pas ! Mes expériences avec les bombes respectent t-toutes les n-n-normes de sécurité...",
          DialogueId = 90180701,
          GUID = "E1C20742",
          SpeakNpcId = 83103,
          Subtitle = "Yale: Uh... p-please don't be mad, a-all my bomb experiments are up to s-s-s-safety s-standards...",
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_03"
        },
        [90190000] = {
          ContentFR = "Ces moments de calme sont rares, pas de blessés, ni de rapports urgents. Hmm... Je vais me faire un café et finir ce roman. Je me demande avec qui la princesse va finir ?",
          DialogueId = 90190000,
          GUID = "E1C7FD09",
          SpeakNpcId = 85401,
          Subtitle = "Moments like these are rare — no cries for help, no urgent reports. Hmm... Perhaps I'll make some coffee and finally finish that novel. Whom does the princess end up with, I wonder?",
          VoiceName = "voice/$Locale$/char/Dafu/vo_idle"
        },
        [90190001] = {
          ContentFR = "Je suis heureuse de vous voir sain et sauf aujourd’hui. Prenez bien soin de vous... en attendant ce jour où la paix règnera enfin.",
          DialogueId = 90190001,
          GUID = "E1C7FD0A",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextOptions = {
            [1] = 901900011,
            [2] = 901900012,
            [3] = 901900013,
            [4] = 901900014,
            [5] = 901900015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85401,
          Subtitle = "It's delightful to see you safe and well today. Take care... The peace we all long for will surely arrive someday.",
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90190002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90190002,
          GUID = "90190002.0",
          NextDialogue = 90190001,
          Subtitle = "Let's talk about something else"
        },
        [90190003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90190003,
          GUID = "90190003.0",
          Subtitle = "Goodbye"
        },
        [90190101] = {
          ContentFR = "Je... je ne pense pas avoir de loisirs particuliers. La lecture, peut-être, si ça compte.",
          DialogueId = 90190101,
          GUID = "E1C80D72",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190102,
          SpeakNpcId = 85401,
          Subtitle = "I... don't think I have any particular hobbies. Reading, maybe, if that counts.",
          TalkActionId = {
            [1] = "85401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_1"
        },
        [90190102] = {
          ContentFR = "Ma mère ne cesse de me dire que je reste enfermée chez moi, ratant les bals et les salons, ce qui me prive de bien des occasions d’avancer socialement...",
          DialogueId = 90190102,
          GUID = "E1C80D9C",
          NextDialogue = 90190103,
          SpeakNpcId = 85401,
          Subtitle = "My mother always says staying home with my books and skipping all those balls and salons will cost me countless opportunities to climb the social ladder...",
          TalkActionId = {
            [1] = "85401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_2"
        },
        [90190103] = {
          ContentFR = "Mais je trouve que cela me convient bien ainsi.",
          DialogueId = 90190103,
          GUID = "E1C80DC6",
          NextDialogue = 90190104,
          SpeakNpcId = 85401,
          Subtitle = "But honestly, I prefer it this way.",
          TalkActionId = {
            [1] = "85401:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_3"
        },
        [90190104] = {
          ContentFR = "Qu’est-ce que tu lis en ce moment ?",
          DialogueId = 90190104,
          GUID = "E1C80DF0",
          NextDialogue = 90190105,
          SpeakNpcId = 100001,
          Subtitle = "What are you reading these days?"
        },
        [90190105] = {
          ContentFR = "Principalement des ouvrages sur les soins en champ de bataille : \"Stratégies d’intervention d’urgence\", \"Traumatologie pratique\", \"Montage d’un hôpital de campagne\"...",
          DialogueId = 90190105,
          GUID = "E1C80E1A",
          NextDialogue = 90190106,
          SpeakNpcId = 85401,
          Subtitle = "Mostly books on battlefield medicine — Emergency Field Aid Manual, Practical Guide to Trauma Care, How to Set Up a Temporary Field Hospital...",
          TalkActionId = {
            [1] = "85401:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_4"
        },
        [90190106] = {
          ContentFR = "Vous savez peut-être que mes études initiales ne portaient pas sur les soins, et malgré mes qualifications d’infirmière militaire, j’éprouve encore souvent un lourd sentiment d’impuissance.",
          DialogueId = 90190106,
          GUID = "E1C80E44",
          NextDialogue = 90190107,
          SpeakNpcId = 85401,
          Subtitle = "You may know that my previous studies never focused on first aid, so even with my medic qualifications, I still feel out of my depth sometimes.",
          TalkActionId = {
            [1] = "85401:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_5"
        },
        [90190107] = {
          ContentFR = "Essaie de te relaxer un peu, ne te stresse pas trop.",
          DialogueId = 90190107,
          GUID = "E1C80E6E",
          NextDialogue = 90190108,
          SpeakNpcId = 100001,
          Subtitle = "You should try to unwind now and then. Don't push yourself too hard."
        },
        [90190108] = {
          ContentFR = "Oui, je lis aussi un livre qui s’appelle \"Chaussure de verre\". C’est une histoire de... euh, princesse et chevalier... Ce n’est pas que j’aime particulièrement les romans d’amour, je l’ai juste feuilleté...",
          DialogueId = 90190108,
          GUID = "E1C80E98",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          Subtitle = "I know, which is why I've been reading... Glass Heels. It's about a—a princess and a knight... Not that I'm into romantic novels or anything! I just... happened to flip through it, that's all...",
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_6",
          bForbidSkipOptions = true
        },
        [90190201] = {
          ContentFR = "Bien sûr ! C’est le fondement d’Hyperborea, ce que les érudits nomment « le miracle originel ».",
          DialogueId = 90190201,
          GUID = "E1C81DDA",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190202,
          SpeakNpcId = 85401,
          Subtitle = "Certainly! Alchemy is the cornerstone of Hyperborea — scholars call it the \"primordial miracle.\"",
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_1"
        },
        [90190202] = {
          ContentFR = "Au début, on cherchait à extraire de l’or du Phoxène. Puis on a découvert qu’elle pouvait aussi faire tourner les engrenages, produire des étincelles électriques... C’est la \"magie\" des Solariens.",
          DialogueId = 90190202,
          GUID = "E1C81E04",
          NextDialogue = 90190203,
          SpeakNpcId = 85401,
          Subtitle = "At first, its purpose was simple: to extract gold from Phoxene. But over time, we discovered this tiny crystal could do so much more — power machinery, generate electricity... It's Solarian magic.",
          TalkActionId = {
            [1] = "85401:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_2"
        },
        [90190203] = {
          ContentFR = "... Mais ensuite, l’Académie d’Alchimie...",
          DialogueId = 90190203,
          GUID = "E1C81E2E",
          NextDialogue = 90190204,
          SpeakNpcId = 85401,
          Subtitle = "...But then, the Academy...",
          TalkActionId = {
            [1] = "85401:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_3"
        }
      }
    end
  },
  {
    MinKey = 90190204,
    MaxKey = 90250106,
    Loader = function()
      return {
        [90190204] = {
          ContentFR = "Tu as étudié là-bas, n’est-ce pas ?",
          DialogueId = 90190204,
          GUID = "E1C81E58",
          NextDialogue = 90190205,
          SpeakNpcId = 100001,
          Subtitle = "You used to study there, didn't you?"
        },
        [90190205] = {
          ContentFR = "... Oui, au Spathatoi. Mais ce chapitre de ma vie est désormais clos.",
          DialogueId = 90190205,
          GUID = "E1C81E82",
          NextDialogue = 90190206,
          SpeakNpcId = 85401,
          Subtitle = "...Yes, in the Spathatoi. But that chapter of my life is over now.",
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_4"
        },
        [90190206] = {
          ContentFR = "Pourquoi as-tu quitté l’Académie d’Alchimie ?",
          DialogueId = 90190206,
          GUID = "E1C81EAC",
          NextDialogue = 90190207,
          SpeakNpcId = 100001,
          Subtitle = "Why did you leave?"
        },
        [90190207] = {
          ContentFR = "Parce que le Spathatoi, tel qu’il est devenu, a dévié de sa voie, empruntant un chemin erroné. Il est devenu le cœur ardent de la machine de guerre d’Hyperborea, mais son carburant, c’est la douleur et le malheur de trop de gens.",
          DialogueId = 90190207,
          GUID = "E1C81ED6",
          NextDialogue = 90190208,
          SpeakNpcId = 85401,
          Subtitle = "I left because the Spathatoi lost its way. What began as a pursuit of knowledge turned into something darker. It's become the blazing core of Hyperborea's war machine, but its fuel brings suffering and misfortune to its people.",
          TalkActionId = {
            [1] = "85401:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_5"
        },
        [90190208] = {
          ContentFR = "Je pense que je suis bien plus faible que je ne le croyais. Je n’ai pas pu me convaincre de l’accepter, et je n’avais ni le courage ni la force de le combattre. Alors, je n’ai eu d’autre choix que de m’en éloigner.",
          DialogueId = 90190208,
          GUID = "E1C81F00",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          Subtitle = "I suppose... I wasn't as strong as I thought. I couldn't reconcile with what it had become, and I lacked the courage or strength to change it. So, I did the only thing I could — I walked away.",
          TalkActionId = {
            [1] = "85401:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_6",
          bForbidSkipOptions = true
        },
        [90190301] = {
          ContentFR = "Des outils et des médicaments d’urgence : bandages, désinfectants, anesthésiques, ainsi que des scalpels et des fils pour les plaies.",
          DialogueId = 90190301,
          GUID = "E1C82E42",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190302,
          SpeakNpcId = 85401,
          Subtitle = "Some emergency tools and supplies — bandages, antiseptics, anesthetics, and the basic tools for wound care like surgical blades and sutures.",
          TalkActionId = {
            [1] = "85401:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_1"
        },
        [90190302] = {
          ContentFR = "J’ai aussi un mouchoir et un peigne.",
          DialogueId = 90190302,
          GUID = "E1C82E6C",
          NextDialogue = 90190303,
          SpeakNpcId = 85401,
          Subtitle = "I also keep a handkerchief and a comb in it.",
          TalkActionId = {
            [1] = "85401:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_2"
        },
        [90190303] = {
          ContentFR = "Tu emportes tes accessoires de beauté sur le champ de bataille ? Je ne te savais pas si attachée à l’élégance, Daphne.",
          DialogueId = 90190303,
          GUID = "E1C82E96",
          NextDialogue = 90190304,
          SpeakNpcId = 100001,
          Subtitle = "You bring beauty supplies to the battlefield? You must take great care in staying elegant."
        },
        [90190304] = {
          ContentFR = "Oh, ce n’est pas ce que tu crois... Ce n’est pas pour moi, c’est pour mes patients. Pour ceux que je ne peux pas sauver... Je les aide à garder un peu de dignité.",
          DialogueId = 90190304,
          GUID = "E1C82EC0",
          NextDialogue = 90190305,
          SpeakNpcId = 85401,
          Subtitle = "Oh, it's not what you think... They're not for me — they're for my patients. I use them to help those who don't make it... tidy up a bit.",
          TalkActionId = {
            [1] = "85401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_3"
        },
        [90190305] = {
          ContentFR = "La souffrance est cruelle. Elle ne se contente pas de voler des vies, elle arrache aussi toute dignité à ceux qu’elle frappe.",
          DialogueId = 90190305,
          GUID = "E1C82EEA",
          NextDialogue = 90190306,
          SpeakNpcId = 85401,
          Subtitle = "The cruelty of death robs people of more than just their lives — it strips them of their dignity.",
          TalkActionId = {
            [1] = "85401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_4"
        },
        [90190306] = {
          ContentFR = "J’aimerais juste... que leurs proches puissent les voir apaisés, propres, comme s’ils dormaient. Après une si longue séparation, aucun parent ne devrait revoir le visage de son enfant déformé par la douleur.",
          DialogueId = 90190306,
          GUID = "E1C82F14",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          Subtitle = "I just want... when their families come to say their final goodbyes, for them to see their loved ones at peace, as though they're merely asleep. After being apart for so long, no parent should have to see their child's face twisted in pain...",
          TalkActionId = {
            [1] = "85401:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_5",
          bForbidSkipOptions = true
        },
        [90190401] = {
          ContentFR = "Oh, ça va ! Ce n’est pas si dur... Enfin, un peu quand même. Tout ce qui est soins et premiers secours, ça va encore. Mais les tests physiques... je dois avouer que c’est vraiment difficile pour moi.",
          DialogueId = 90190401,
          GUID = "E1C83EAA",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190402,
          SpeakNpcId = 85401,
          Subtitle = "Oh, it's fine! I can handle it... Well, maybe just a little tough sometimes. The emergency care and nursing lessons aren't too bad, but the physical fitness tests... those are a real struggle for me.",
          TalkActionId = {
            [1] = "85401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_1"
        },
        [90190402] = {
          ContentFR = "Même en me levant plus tôt que tout le monde pour m’entraîner seule, je n’arrive qu’à peine à décrocher la moyenne... Ne vous moquez pas, d’accord ? Travailler son endurance, c’est bien plus difficile que de réviser ses cours !",
          DialogueId = 90190402,
          GUID = "E1C83ED4",
          NextDialogue = 90190403,
          SpeakNpcId = 85401,
          Subtitle = "Even though I get up earlier than everyone else for extra training, I still only manage to scrape by with passing scores... Please don't make fun of me! Building stamina is so much harder than studying.",
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_2"
        },
        [90190403] = {
          ContentFR = "Se lever tôt pour s’entraîner, ça a l’air épuisant.",
          DialogueId = 90190403,
          GUID = "E1C83EFE",
          NextDialogue = 90190404,
          SpeakNpcId = 100001,
          Subtitle = "Waking up early for extra training sounds exhausting."
        },
        [90190404] = {
          ContentFR = "Oui, c’est vrai que c’est dur. Mais quand je détourne mon attention de mes jambes fatiguées, que je regarde les champs de blé en périphérie, les chaumières à l’horizon, que j’entends le bruit des moulins et le sifflement des bergers, tout s’apaise en moi.",
          DialogueId = 90190404,
          GUID = "E1C83F28",
          NextDialogue = 90190405,
          SpeakNpcId = 85401,
          Subtitle = "It is. But when I take my mind off my tired legs and look up, I see the wheat fields stretching beyond the city and the cottages on the horizon, and hear the windmills creaking and the herdsmen whistling. It always helps me feel so much better.",
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_3"
        },
        [90190405] = {
          ContentFR = "Parce que... peut-être que courir sur ce chemin, c’est ma façon de protéger ces choses simples et ordinaires de disparaître.",
          DialogueId = 90190405,
          GUID = "E1C83F52",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          Subtitle = "Because... running along that road feels like my way of protecting these simple, precious things from being taken away.",
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_4",
          bForbidSkipOptions = true
        },
        [90190501] = {
          ContentFR = "La dernière fois que j’ai parlé à mon père, c’était au talkie-walkie, dans la Forteresse de Lonza. Malgré le danger, il m’a dit : « Ne t’inquiète pas. »",
          DialogueId = 90190501,
          GUID = "E1C84F12",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190502,
          SpeakNpcId = 85401,
          Subtitle = "...The last time I spoke with my father was over the radio. It was on the battlefield of Lonza Fortress, and despite the danger, he told me, \"Don't worry, I'll be fine.\"",
          TalkActionId = {
            [1] = "85401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_1"
        },
        [90190502] = {
          ContentFR = "Plus tard, je rallumais souvent mon talkie-walkie en pleine nuit, réglais sa fréquence, et appuyais sur le bouton d’appel, espérant entendre sa voix...",
          DialogueId = 90190502,
          GUID = "E1C84F3C",
          NextDialogue = 90190503,
          SpeakNpcId = 85401,
          Subtitle = "After everything that happened, I'd often turn on my radio in the dead of night, tune to his channel, and press the call button, hoping to hear his voice again...",
          TalkActionId = {
            [1] = "85401:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_2"
        },
        [90190503] = {
          ContentFR = "Ce n’est qu’après être restée assise en silence pendant ce qui m’a paru une éternité que j’ai compris... qu’il ne reviendrait jamais.",
          DialogueId = 90190503,
          GUID = "E1C84F66",
          NextDialogue = 90190504,
          SpeakNpcId = 85401,
          Subtitle = "It wasn't until I sat there in silence for what felt like an eternity that I realized... he was never coming back.",
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_3"
        },
        [90190504] = {
          ContentFR = "Mes condoléances...",
          DialogueId = 90190504,
          GUID = "E1C84F90",
          NextDialogue = 90190505,
          SpeakNpcId = 100001,
          Subtitle = "My condolences..."
        },
        [90190505] = {
          ContentFR = "Merci. Ne t’inquiète pas, je vais rester forte et continuer à avancer. Tant que je n’aurai pas lavé l’honneur de mon père et des victimes innocentes de la bataille de Lonza, je ne m’arrêterai pas.",
          DialogueId = 90190505,
          GUID = "E1C84FBA",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          Subtitle = "Thank you. Don't worry, I'll stay strong and keep pushing on. Until I clear my father's name and honour the wronged who fell in the Lonza battle, I won't stop.",
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_4",
          bForbidSkipOptions = true
        },
        [90190601] = {
          ContentFR = "J’ai lu un jour, à la bibliothèque de la capitale, des traités médicaux de Huaxu. Bien que leurs théories diffèrent de celles des traditions médicales d’Hyperborea, elles se sont avérées remarquablement efficaces pour le traitement. Il reste cependant des passages que je ne maîtrise pas complètement, pourriez-vous m’aider à les éclaircir ?",
          DialogueId = 90190601,
          GUID = "E1C85F7A",
          SpeakNpcId = 85401,
          Subtitle = "I once read medical texts from Huaxu in the capital's library. While their theories differ from those of Hyperborea's medical traditions, they've proven remarkably effective in treatment. There are still parts I don't fully understand — would you mind helping me with them?",
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_01"
        },
        [90190701] = {
          ContentFR = "Madame la geôlière, je me demande : une justice qui arrive tardivement mérite-t-elle encore d’être appelée justice ?",
          DialogueId = 90190701,
          GUID = "E1C86FE2",
          SpeakNpcId = 85401,
          Subtitle = "Madam Warden, I wonder — does justice that arrives late still deserve to be called justice?",
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_02"
        },
        [90190801] = {
          ContentFR = "Ça fait si longtemps. Depuis que j’ai quitté les Spathatoi, nous nous sommes à peine parlé. Comment... vas-tu ?",
          DialogueId = 90190801,
          GUID = "E1C8804A",
          SpeakNpcId = 85401,
          Subtitle = "It's been so long. Since I left the Spathatoi, we've barely spoken. How... have you been?",
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_03"
        },
        [90190901] = {
          ContentFR = "Même si j’ai quitté les Spathatoi, c’est un lieu qui m’a profondément marquée. Je sais que demander pardon est peut-être trop, mais je tiens quand même à dire... je suis désolée.",
          DialogueId = 90190901,
          GUID = "E1C890B2",
          SpeakNpcId = 85401,
          Subtitle = "Even though I've left the Spathatoi, it remains a place that shaped me. I know forgiveness might be too much to hope for, but I still want to say — I'm sorry.",
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_04"
        },
        [90200000] = {
          ContentFR = "Chut... Je suis presque dans mon personnage.",
          DialogueId = 90200000,
          GUID = "E1CE65A9",
          SpeakNpcId = 81103,
          Subtitle = "Hush... I am nearly in character.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_idle"
        },
        [90200001] = {
          ContentFR = "J’endosse le rôle du prisonnier brisé, et toi, tu es {性别:le geôlier qui veille sur mes chaînes.|la geôlière qui veille sur mes chaînes.}",
          DialogueId = 90200001,
          GUID = "E1CE65AA",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextOptions = {
            [1] = 902000011,
            [2] = 902000012,
            [3] = 902000013,
            [4] = 902000014,
            [5] = 902000015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81103,
          Subtitle = "I assume the role of the shattered prisoner, and you, as a watchful warden, stand sentinel over my chains.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_welcome",
          bForbidSkipOptions = true
        },
        [90200002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90200002,
          GUID = "90200002.0",
          NextDialogue = 90200001,
          Subtitle = "Let's talk about something else"
        },
        [90200003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90200003,
          GUID = "90200003.0",
          Subtitle = "Goodbye"
        },
        [90200101] = {
          ContentFR = "Il était une lampe de cristal brisée, une étoile tombée dans un égout obscur.",
          DialogueId = 90200101,
          GUID = "E1CE7612",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200102,
          SpeakNpcId = 81103,
          Subtitle = "He was a shattered crystal lamp, a fallen star plunged into a filthy gutter.",
          TalkActionId = {
            [1] = "81103:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_1"
        },
        [90200102] = {
          ContentFR = "... ?",
          DialogueId = 90200102,
          GUID = "E1CE763C",
          NextDialogue = 90200103,
          SpeakNpcId = 100001,
          Subtitle = "...?",
          TalkActionId = {
            [1] = "81103:Talk01_End"
          }
        },
        [90200103] = {
          ContentFR = "Tout comme ces choses, il était d’un ridicule désarmant, et éclairait le monde d’une lueur étincelante.",
          DialogueId = 90200103,
          GUID = "E1CE7666",
          NextDialogue = 90200104,
          SpeakNpcId = 81103,
          Subtitle = "He was just like those things — laughably absurd, yet somehow, they shine brilliantly.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_2"
        },
        [90200104] = {
          ContentFR = "Le mur entre nos cellules était si fin que chaque son le traversait. Il était là, à peine à un mètre, parlant de sa famille, s’égarant dans ses rêves, ou chantant un air faux et maladroit.",
          DialogueId = 90200104,
          GUID = "E1CE7690",
          NextDialogue = 90200105,
          SpeakNpcId = 81103,
          Subtitle = "The wall between our cells was so thin, every sound passed through. There he was, barely a metre away — rambling about his family, spinning dreams of the future, or singing some hopelessly off-key tune.",
          TalkActionId = {
            [1] = "81103:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_3"
        },
        [90200105] = {
          ContentFR = "Parfois, j’avais presque l’impression que je n’étais pas une bête enfermée dans une cage, mais un élève insouciant, réveillé d’un cauchemar pendant sa sieste de l’après-midi par un camarade bruyant assis à côté de lui.",
          DialogueId = 90200105,
          GUID = "E1CE76BA",
          NextDialogue = 90200106,
          SpeakNpcId = 81103,
          Subtitle = "For a moment, I'd forget I was a caged beast. Instead, I'd feel like an ordinary child in school, waking from a nightmare during an afternoon nap to the racket of a noisy classmate beside me.",
          TalkActionId = {
            [1] = "81103:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_4"
        },
        [90200106] = {
          ContentFR = "Tu as donc été attiré par lui, et vous êtes devenus amis.",
          DialogueId = 90200106,
          GUID = "E1CE76E4",
          NextDialogue = 90200107,
          SpeakNpcId = 100001,
          Subtitle = "So, you were drawn to him, and you became friends."
        },
        [90200107] = {
          ContentFR = "... Hum. Peut-être bien.",
          DialogueId = 90200107,
          GUID = "E1CE770E",
          NextDialogue = 90200108,
          SpeakNpcId = 81103,
          Subtitle = "...Heh. Perhaps.",
          TalkActionId = {
            [1] = "81103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_5"
        },
        [90200108] = {
          ContentFR = "Le mot \"ami\" brille trop fort pour moi. Nous étions plutôt deux poissons échoués, abandonnés sur le lit desséché d’une rivière.",
          DialogueId = 90200108,
          GUID = "E1CE7738",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          Subtitle = "But \"friend\" is far too bright a word for someone like me. We were more like two stranded fish, floundering together in a drying riverbed.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_01_6",
          bForbidSkipOptions = true
        },
        [90200201] = {
          ContentFR = "Pourquoi ? La vie de Parsifal est finie. Ce nom est un écho lointain, si lointain que je doute qu’il ait jamais été mien.",
          DialogueId = 90200201,
          GUID = "E1CE867A",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200202,
          SpeakNpcId = 81103,
          Subtitle = "Why should I? Parsifal's story ended long ago. That name is but a distant echo now, so faint and far away that I sometimes wonder if it was ever real.",
          TalkActionId = {
            [1] = "81103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_02_1"
        },
        [90200202] = {
          ContentFR = "Mais pour moi, tu es bien réel.",
          DialogueId = 90200202,
          GUID = "E1CE86A4",
          NextDialogue = 90200203,
          SpeakNpcId = 100001,
          Subtitle = "But to me, you're real."
        },
        [90200203] = {
          ContentFR = "... Vraiment ?",
          DialogueId = 90200203,
          GUID = "E1CE86CE",
          NextDialogue = 90200204,
          SpeakNpcId = 81103,
          Subtitle = "...Is that so?",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_02_2"
        },
        [90200204] = {
          ContentFR = "Dans ce cas, je jouerai jusqu’au bout cette dernière scène, pour toi, mon seul et dernier spectateur.",
          DialogueId = 90200204,
          GUID = "E1CE86F8",
          NextDialogue = 90200205,
          SpeakNpcId = 81103,
          Subtitle = "Then I shall carry this final performance to its conclusion — for you, my last and only audience.",
          TalkActionId = {
            [1] = "81103:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_02_3"
        },
        [90200205] = {
          ContentFR = "Merci de m’avoir offert une scène où reposer mon âme fatiguée.",
          DialogueId = 90200205,
          GUID = "E1CE8722",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          Subtitle = "Thank you, for granting me a stage to rest my weary soul.",
          TalkActionId = {
            [1] = "81103:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90200301] = {
          ContentFR = "Merci pour ta bonté, mais mes serments sont accomplis, et mon cœur est désormais vide de désirs.",
          DialogueId = 90200301,
          GUID = "E1CE96E2",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200302,
          SpeakNpcId = 81103,
          Subtitle = "You're so kind. Thank you. Yet, all my vows have been fulfilled. There's little left that stirs my heart.",
          TalkActionId = {
            [1] = "81103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_1"
        },
        [90200302] = {
          ContentFR = "...",
          DialogueId = 90200302,
          GUID = "E1CE970C",
          NextDialogue = 90200303,
          SpeakNpcId = 81103,
          Subtitle = "...",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_2"
        },
        [90200303] = {
          ContentFR = "Si jamais tu passes par le Théâtre Galea, s’il te plaît, fais savoir à Madame Violetta que je me suis installé à Aethyrie. Qu’elle ne s’inquiète pas, je vais très bien maintenant.",
          DialogueId = 90200303,
          GUID = "E1CE9736",
          NextDialogue = 90200304,
          SpeakNpcId = 81103,
          Subtitle = "Should you ever find yourself at the Galea Theatre, please convey to Ms Violetta that I've settled down in Aethyrie. Assure her not to worry, as I am doing very well now.",
          TalkActionId = {
            [1] = "81103:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_3"
        },
        [90200304] = {
          ContentFR = "« Là-bas, tout est musique et poésie, chaque pierre bat la mesure, chaque source chante une mélodie. »",
          DialogueId = 90200304,
          GUID = "E1CE9760",
          NextDialogue = 90200305,
          SpeakNpcId = 81103,
          Subtitle = "\"A land of music and poetry, where every pebble taps out a rhythm, and every brook sings a melody.\"",
          TalkActionId = {
            [1] = "81103:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_4"
        },
        [90200305] = {
          ContentFR = "Ainsi, elle cessera de chercher mes traces. J’étais son élève préféré... Je ne veux pas ternir sa mémoire.",
          DialogueId = 90200305,
          GUID = "E1CE978A",
          NextDialogue = 90200306,
          SpeakNpcId = 81103,
          Subtitle = "Hopefully, that'll keep her from enquiring after me. Once her favoured pupil... I'd rather not tarnish her memories.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_5"
        },
        [90200306] = {
          ContentFR = "Un mensonge bienveillant, alors...",
          DialogueId = 90200306,
          GUID = "E1CE97B4",
          NextDialogue = 90200307,
          SpeakNpcId = 100001,
          Subtitle = "A little white lie, I see."
        },
        [90200307] = {
          ContentFR = "Oui... ne rien savoir rend souvent plus heureux.",
          DialogueId = 90200307,
          GUID = "E1CE97DE",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          Subtitle = "Indeed. Ignorance is always bliss.",
          TalkActionId = {
            [1] = "81103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_03_6",
          bForbidSkipOptions = true
        },
        [90200401] = {
          ContentFR = "Pourquoi vouloir apprendre à jouer ? Tu n’as pas besoin de devenir quelqu’un d’autre.",
          DialogueId = 90200401,
          GUID = "E1CEA74A",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200402,
          SpeakNpcId = 81103,
          Subtitle = "Why seek to learn acting? You have no need to become someone else.",
          TalkActionId = {
            [1] = "81103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_04_1"
        },
        [90200402] = {
          ContentFR = "« Devenir quelqu’un d’autre » ?",
          DialogueId = 90200402,
          GUID = "E1CEA774",
          NextDialogue = 90200403,
          SpeakNpcId = 100001,
          Subtitle = "Become someone else?"
        },
        [90200403] = {
          ContentFR = "Monter sur scène, livrer chaque os, chaque souffle à la pièce, c’est se métamorphoser, oublier ses douleurs et franchir un monde inconnu.",
          DialogueId = 90200403,
          GUID = "E1CEA79E",
          NextDialogue = 90200404,
          SpeakNpcId = 81103,
          Subtitle = "When you're on stage, every part of you — from your very bones to the breaths you take — is surrendered to the character. In that moment, you can shed all your sorrows and pain, stepping into a world unblemished by reality.",
          TalkActionId = {
            [1] = "81103:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_04_2"
        },
        [90200404] = {
          ContentFR = "Mais toi, tu es {性别:né pour être le héros de ton propre récit, porté par les regards, guidé|tu es née pour être l’héroïne de ton propre récit, portée par les regards, guidée} par la confiance. Ta lumière n’a pas besoin de projecteurs.",
          DialogueId = 90200404,
          GUID = "E1CEA7C8",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          Subtitle = "But you... you were born the {性别：hero|heroine} of your own story, already carrying the admiration and trust of those around you. You shine effortlessly, needing no spotlight to dazzle.",
          TalkActionId = {
            [1] = "81103:Angry01_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90200501] = {
          ContentFR = "Il se dresse là depuis bien plus longtemps que ma propre vie. D’un côté de ses murs imposants s’élève la cité intérieure, haute comme les nuages, plus froide encore.",
          DialogueId = 90200501,
          GUID = "E1CEB7B2",
          LookAt = {
            [1] = "81103:n(0)",
            [2] = "0:n(81103)"
          },
          NextDialogue = 90200502,
          SpeakNpcId = 81103,
          Subtitle = "It stands, enduring time far beyond my years. On one side of its towering walls lies the imposing inner city — majestic as storm clouds, yet colder.",
          TalkActionId = {
            [1] = "81103:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_1"
        },
        [90200502] = {
          ContentFR = "Des silhouettes élégamment vêtues descendent de carrosses tapissés de soie, discutant d’art, de poésie, et de ce ciel toujours chargé de nuages. Ils parlent de bals, de fiançailles, tout en se plaignant que la boue mêlée à la neige fondue de la cité extérieure salisse leurs belles bottes de cuir.",
          DialogueId = 90200502,
          GUID = "E1CEB7DC",
          NextDialogue = 90200503,
          SpeakNpcId = 81103,
          Subtitle = "Elegantly clad figures alight from silk-lined carriages, discussing art, poetry, and the perpetual gloom of the skies. They gossip about balls and betrothals, lamenting how the mire of melting snow from the outer city soils their fine leather boots.",
          TalkActionId = {
            [1] = "81103:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_2"
        },
        [90200503] = {
          ContentFR = "De l’autre côté des murs s’étend le quartier brumeux et bruyant, grouillant de chaos. Les marchands ambulants crient à pleins poumons leurs offres, tandis que les mères serrent leurs enfants contre elles, implorant un morceau de pain de seigle. Des mains espiègles griffonnent des graffitis provocateurs, toujours un pas devant les patrouilles.",
          DialogueId = 90200503,
          GUID = "E1CEB806",
          NextDialogue = 90200504,
          SpeakNpcId = 81103,
          Subtitle = "On the other side of the walls, the rowdy fog district buzzes with chaos. Vendors hawk loudly, mothers clutch their children, begging for a scrap of rye bread. Mischievous hands sketch defiant graffiti, always a step ahead of the patrols.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_3"
        },
        [90200504] = {
          ContentFR = "Et c'est ainsi que se dresse notre Théâtre Galea, pris entre ces deux mondes, entendant tout mais ne comprenant rien.",
          DialogueId = 90200504,
          GUID = "E1CEB830",
          NextDialogue = 90200505,
          SpeakNpcId = 81103,
          Subtitle = "And so stands our Galea Theatre, caught between these two worlds, hearing all yet understanding none.",
          TalkActionId = {
            [1] = "81103:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_4"
        },
        [90200505] = {
          ContentFR = "Y a-t-il des souvenirs qui te sont chers, là-bas ?",
          DialogueId = 90200505,
          GUID = "E1CEB85A",
          NextDialogue = 90200506,
          SpeakNpcId = 100001,
          Subtitle = "Any personal memories there?",
          TalkActionId = {
            [1] = "81103:Confident_End"
          }
        },
        [90200506] = {
          ContentFR = "Curieusement, ce ne sont ni les textes, ni les costumes, ni même la réserve d’accessoires que je balayais chaque jour qui me viennent à l’esprit en premier.",
          DialogueId = 90200506,
          GUID = "E1CEB884",
          NextDialogue = 90200507,
          SpeakNpcId = 81103,
          Subtitle = "Oddly, it's not the scripts or the lavish costumes that first come to mind, nor the cluttered prop room I swept daily.",
          TalkActionId = {
            [1] = "81103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_5"
        },
        [90200507] = {
          ContentFR = "C’est ce tapis de velours fin, posé sur la scène après le spectacle. Quand j’étais enfant, à la fin de la première représentation dont je garde un souvenir, ma mère et moi répétions les chansons du spectacle, dansant toute la nuit sur ce tapis.",
          DialogueId = 90200507,
          GUID = "E1CEB8AE",
          NextDialogue = 90200508,
          SpeakNpcId = 81103,
          Subtitle = "It's the velvet carpet that blanketed the stage after the curtain fell. As a child, after the earliest performance I can remember, my mother and I lingered on the stage after everyone left, reciting lines and dancing through the night.",
          TalkActionId = {
            [1] = "81103:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_6"
        },
        [90200508] = {
          ContentFR = "À l’aube, fatigué, je me couchais sur ce tapis, la tête posée sur ses genoux, et sombrais dans un long sommeil.",
          DialogueId = 90200508,
          GUID = "E1CEB8D8",
          NextOptions = {
            [1] = 90200002,
            [2] = 90200003
          },
          SpeakNpcId = 81103,
          Subtitle = "When dawn broke, exhaustion finally overtook me. I lay down on that carpet, resting my head on Mother's lap, and drifted into a long, sweet dream.",
          TalkActionId = {
            [1] = "81103:Sigh_End"
          },
          VoiceName = "voice/$Locale$/char/Tuosi/vo_topic_05_7",
          bForbidSkipOptions = true
        },
        [90200601] = {
          ContentFR = "Comment allez-vous, ces derniers temps ?\n... Pardonnez mon audace. Nous ne nous connaissons guère, c’est vrai. Je me renseignais... pour un ami.",
          DialogueId = 90200601,
          GUID = "E1CEC81A",
          SpeakNpcId = 81103,
          Subtitle = [[
How have you been lately?
...Apologies for the abruptness. We don't actually know each other. I was... merely enquiring for a friend.]],
          VoiceName = "voice/$Locale$/char/Tuosi/vo_companio_01"
        },
        [90200701] = {
          ContentFR = "Vraiment ? Tu as trouvé un foyer, une famille attentionnée... C’est merveilleux. Tu as réussi à te libérer de ta propre cage, il faut du courage pour cela.",
          DialogueId = 90200701,
          GUID = "E1CED882",
          SpeakNpcId = 81103,
          Subtitle = "Is that so? You've found a new home and a family who cares for you... That's wonderful. You've broken free of your cage — what a brave soul you are.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_companio_02"
        },
        [90200901] = {
          ContentFR = "Votre capacité de mimétisme est exceptionnelle, même le meilleur des accessoiristes ne pourrait créer un tel chef-d’œuvre.",
          DialogueId = 90200901,
          GUID = "E1CEF952",
          SpeakNpcId = 81103,
          Subtitle = "Your mimicry is extraordinary. Even the finest stage prop artists couldn't craft something so exquisitely detailed.",
          VoiceName = "voice/$Locale$/char/Tuosi/vo_companio_04"
        },
        [90210000] = {
          ContentFR = "Tu n’aurais pas une mission à me confier ? Ce n’est pas que j’adore bosser… mais quand je ne fais rien, je me sens nerveuse.",
          DialogueId = 90210000,
          GUID = "E1D4CE49",
          SpeakNpcId = 84101,
          Subtitle = "Is there anything I can help with? It's not that I'm a workaholic — it's just... a habit, I guess. When I'm not busy, I feel unsettled.",
          VoiceName = "voice/$Locale$/char/Lise/vo_idle"
        },
        [90210001] = {
          ContentFR = "Patrouille terminée aujourd’hui. Aucun danger, aucune fissure dans les murs, aucun signe suspect. Menaces écartées. La vie peut reprendre son cours normal. Rapport terminé.",
          DialogueId = 90210001,
          GUID = "E1D4CE4A",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextOptions = {
            [1] = 902100011,
            [2] = 902100012,
            [3] = 902100013,
            [4] = 902100014,
            [5] = 902100015,
            [6] = 902100016,
            [7] = 902100017
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84101,
          Subtitle = "Patrol complete. No signs of dangerous creatures, structural damage, or suspicious markings. Routine operations may proceed without interruption. Report concluded.",
          TalkActionId = {
            [1] = "84101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_welcome",
          bForbidSkipOptions = true
        },
        [90210002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90210002,
          GUID = "90210002.0",
          NextDialogue = 90210001,
          Subtitle = "Let's talk about something else"
        },
        [90210003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90210003,
          GUID = "90210003.0",
          Subtitle = "Goodbye"
        },
        [90210101] = {
          ContentFR = "Ah... tu as remarqué. C’est un harmonica laissé par un proche. Je le garde bien verrouillé, mais j’ai toujours peur qu’il disparaisse, alors je vérifie de temps en temps.",
          DialogueId = 90210101,
          GUID = "E1D4DEB2",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210102,
          SpeakNpcId = 84101,
          Subtitle = "Oh... You've noticed. Yes, I have one — it was given to me by someone very dear. I keep it locked away safely, but... I can't help checking on it now and then, worried it might just vanish somehow.",
          TalkActionId = {
            [1] = "84101:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_1"
        },
        [90210102] = {
          ContentFR = "Du coup, tu sais jouer beaucoup de chansons ?",
          DialogueId = 90210102,
          GUID = "E1D4DEDC",
          NextDialogue = 90210103,
          SpeakNpcId = 100001,
          Subtitle = "Then you must know how to play lots of tunes on it.",
          TalkActionId = {
            [1] = "84101:Explain02_End"
          }
        },
        [90210103] = {
          ContentFR = "En vérité, je ne connais qu’une seule chanson. Celle que ce proche m’a apprise. Je n’ai pas été très rapide à l’apprendre à l'époque... Peut-être parce que je n’ai jamais été doué pour les choses qui nécessitent une certaine expression émotionnelle...",
          DialogueId = 90210103,
          GUID = "E1D4DF06",
          NextDialogue = 90210104,
          SpeakNpcId = 84101,
          Subtitle = "Actually, I only know one. The person who gave it to me taught me. I wasn't quick to pick it up back then... maybe because I've never been good at things that require emotional expression...",
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_2"
        },
        [90210104] = {
          ContentFR = "Mais lorsque je suis trop tendue... ou trop euphorique, je serre instinctivement l’harmonica dans ma main. Il agit comme une ancre, un rappel de ce qui compte, de ce en quoi je peux croire. Il m’aide toujours à retrouver mon calme.",
          DialogueId = 90210104,
          GUID = "E1D4DF30",
          NextDialogue = 90210105,
          SpeakNpcId = 84101,
          Subtitle = "But whenever I'm too tense or carried away, I find myself reaching for it. It's like an anchor — a reminder of the things that matter, the things I can trust. It always helps me find my calm again.",
          TalkActionId = {
            [1] = "84101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_3"
        },
        [90210105] = {
          ContentFR = "Beaucoup de mes camarades vont voir des médecins à cause du stress, pour s’apaiser ou se stimuler. Moi, je n’en ai pas besoin. Que mon cœur batte trop vite ou trop lentement, l’harmonica m’aide à retrouver un rythme normal.",
          DialogueId = 90210105,
          GUID = "E1D4DF5A",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "Many of my peers rely on doctors for stress relief — sedatives, stimulants, that kind of stuff. I've never needed that. Whether my heart races or slows, the harmonica always steadies me.",
          TalkActionId = {
            [1] = "84101:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90210201] = {
          ContentFR = "Ça va. La Légion fait partie des rares endroits où l’on est vraiment récompensé pour ses efforts. J’ai gagné ma place ici, et aujourd’hui j’ai même quelques soldats sous ma responsabilité. Je veille à ce qu’ils traitent les Charons et Sola avec le même respect.",
          DialogueId = 90210201,
          GUID = "E1D4EF1A",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210202,
          SpeakNpcId = 84101,
          Subtitle = "Not bad. The Legion is one of the few places where hard work truly gets rewarded. I've earned my position here, and now I even have a few subordinates. I make sure they treat Charons and Solas with the same respect.",
          TalkActionId = {
            [1] = "84101:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_1"
        },
        [90210202] = {
          ContentFR = "J’ai entendu de nombreuses plaintes, parfois même des accusations amères, sur la sévérité de la Légion envers les Charons. Je fais tout ce que je peux pour changer cette perception... Peut-être qu’un jour, les gens verront la Légion d’un autre œil.",
          DialogueId = 90210202,
          GUID = "E1D4EF44",
          NextDialogue = 90210203,
          SpeakNpcId = 84101,
          Subtitle = "I've heard plenty of complaints — and bitter accusations — about how harshly the Legion treats the Charon community. I do everything I can to change that... Maybe someday, people will start to see the Legion in a better light.",
          TalkActionId = {
            [1] = "84101:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_2"
        },
        [90210203] = {
          ContentFR = "Mais y a-t-il suffisamment de personnes comme toi pour vraiment faire la différence ?",
          DialogueId = 90210203,
          GUID = "E1D4EF6E",
          NextDialogue = 90210204,
          SpeakNpcId = 100001,
          Subtitle = "But are there enough people like you to really make a difference?"
        },
        [90210204] = {
          ContentFR = "Pas encore. Mais ça viendra peu à peu. À une époque, il n’y avait même pas un seul Charon dans la Légion. Je ne peux pas tout changer à moi seule, mais si je continue à former mes subordonnés dans ce sens, les tensions entre Charons et Sola finiront par s’atténuer.",
          DialogueId = 90210204,
          GUID = "E1D4EF98",
          NextDialogue = 90210205,
          SpeakNpcId = 84101,
          Subtitle = "Not yet. But there will be. There was a time when you wouldn't find even a single Charon in the Legion. I know I can't make a big difference just yet, but if I guide my subordinates down the right path, I believe the conflicts between Charons and Solas will ease, bit by bit.",
          TalkActionId = {
            [1] = "84101:Agree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_3"
        },
        [90210205] = {
          ContentFR = "Oui... traiter chacun équitablement, les protéger des Souillés et de la Dégradation... Je pense que ces efforts peuvent vraiment améliorer le quotidien des Charons. Peut-être qu’alors, les soupirs fatigués résonneront un peu moins à Givrelac.",
          DialogueId = 90210205,
          GUID = "E1D4EFC2",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "Treating everyone fairly and keeping them safe from Filthoids and Deterioration... I believe these efforts can improve life for the Charon community. Maybe, it will quiet the weary sighs echoing through Icelake a little bit.",
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90210301] = {
          ContentFR = "Ce n’est pas une question de sérieux. Je ne fais que suivre à la lettre le règlement des Veilleurs.",
          DialogueId = 90210301,
          GUID = "E1D4FF82",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210302,
          SpeakNpcId = 84101,
          Subtitle = "I wouldn't call it responsibility. I'm simply following the Escort's regulations to the letter.",
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_1"
        },
        [90210302] = {
          ContentFR = "Pourtant, les autres ne semblent suivre aucune règle. Ils agissent comme bon leur semble, sans se soucier de rien.",
          DialogueId = 90210302,
          GUID = "E1D4FFAC",
          NextDialogue = 90210303,
          SpeakNpcId = 100001,
          Subtitle = "But the other soldiers don't seem to do the same — they're always so reckless and rude."
        },
        [90210303] = {
          ContentFR = "Le règlement des Veilleurs interdit de commenter librement la conduite de ses camarades. Ce serait une entorse à la discipline.",
          DialogueId = 90210303,
          GUID = "E1D4FFD6",
          NextDialogue = 90210304,
          SpeakNpcId = 84101,
          Subtitle = "The Escort's regulations forbid any legionary from commenting on the conduct of their fellow legionaries.",
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_2"
        },
        [90210304] = {
          ContentFR = "Mais pour être honnête, je ne comprends pas ce qui leur passe par la tête. Peut-être qu’ils voient juste les Veilleurs comme un boulot banal. Du moment que leurs supérieurs ne remarquent rien, ils pensent pouvoir faire n’importe quoi.",
          DialogueId = 90210304,
          GUID = "E1D50000",
          NextDialogue = 90210305,
          SpeakNpcId = 84101,
          Subtitle = "That said, I really don't understand them. Maybe, to them, it's just a job. As long as their superiors don't notice, they think it's fine to slack off or mess around.",
          TalkActionId = {
            [1] = "84101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_3"
        },
        [90210305] = {
          ContentFR = "Moi, je pense que ce n’est pas comme ça qu’on devrait vivre. Il faut des règles pour rester fidèle à soi-même. Sans cadre, on finit par baisser ses exigences, vivre au jour le jour... et finir comme un rat dans les égouts.",
          DialogueId = 90210305,
          GUID = "E1D5002A",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "I think that kind of attitude is wrong. People need something to keep themselves in check. Without it, they'll just drift through life, letting their standards erode little by little — until they're no better than rats in the sewers.",
          TalkActionId = {
            [1] = "84101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90210401] = {
          ContentFR = "Non, merci... Je n’aime pas trop me voir dans un miroir. Voir mes cornes dès le premier regard me dérange un peu.",
          DialogueId = 90210401,
          GUID = "E1D50FEA",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210402,
          SpeakNpcId = 84101,
          Subtitle = "No... Thank you. I don't really enjoy looking at myself in the mirror. Seeing my horns always makes me feel... uncomfortable.",
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_04_1"
        },
        [90210402] = {
          ContentFR = "Tu n’es pas à l’aise avec l’apparence des Charons ?",
          DialogueId = 90210402,
          GUID = "E1D51014",
          NextDialogue = 90210403,
          SpeakNpcId = 100001,
          Subtitle = "So, you're not comfortable with how Charons look?"
        },
        [90210403] = {
          ContentFR = "Non, pas du tout. Je ne renie pas notre apparence. C’est juste que je trouverais mes cornes plus jolies si elles étaient plus régulières, plus symétriques. Ah, ne te méprends pas, je ne critique pas tes cornes...",
          DialogueId = 90210403,
          GUID = "E1D5103E",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "No, that's not it at all. I'm not ashamed of my Charon heritage. It's just... I think my horns would look much better if they were more regular, more symmetrical. Ah, don't get me wrong! I'm not saying there's anything wrong with your horn...",
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90210501] = {
          ContentFR = "Oui... mais il est devenu si lourd. Trop lourd... Je ne sais pas si j’aurai encore la force de le reprendre, de rejouer.",
          DialogueId = 90210501,
          GUID = "E1D52052",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210502,
          SpeakNpcId = 84101,
          Subtitle = "I do... but it feels so heavy now, almost unbearably so. I'm not sure I have the strength to pick it up and play anymore.",
          TalkActionId = {
            [1] = "84101:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_05_1"
        },
        [90210502] = {
          ContentFR = "Après tout, cet harmonica portait tous mes espoirs et mes rêves. Aujourd’hui, il ne me rappelle plus que tout ce que j’ai perdu.",
          DialogueId = 90210502,
          GUID = "E1D5207C",
          NextDialogue = 90210503,
          SpeakNpcId = 84101,
          Subtitle = "After all, it once carried all my hopes and dreams. Now, it just reminds me of everything I've lost.",
          TalkActionId = {
            [1] = "84101:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_05_2"
        },
        [90210503] = {
          ContentFR = "Si un jour tu te sens prête à en rejouer... laisse-moi être le premier à t’écouter.",
          DialogueId = 90210503,
          GUID = "E1D520A6",
          NextDialogue = 90210504,
          SpeakNpcId = 100001,
          Subtitle = "If you ever feel ready to play it again, I'd be honoured to be your first listener."
        },
        [90210504] = {
          ContentFR = "...D’accord. Je te le promets. Quand je pourrai le reprendre, quand je me sentirai prête à apprendre un nouvel air... tu seras le premier à l’entendre.",
          DialogueId = 90210504,
          GUID = "E1D520D0",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "...Thank you. I promise, when the day comes that I can pick it up again — when I'm ready to learn a new tune — I'll make sure you're the first to hear it.",
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90210601] = {
          ContentFR = "Je prends des petits boulots, un peu chaque jour. Ça suffit pour couvrir mes besoins. Mais honnêtement, ce n’est plus vraiment pour l’argent. Aujourd’hui, je travaille surtout pour le travail lui-même.",
          DialogueId = 90210601,
          GUID = "E1D530BA",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210602,
          SpeakNpcId = 84101,
          Subtitle = "I've been taking on odd jobs here and there. It's enough to cover my expenses. But honestly, earning a living isn't the point anymore. These days, work is more about keeping myself busy.",
          TalkActionId = {
            [1] = "84101:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_06_1"
        },
        [90210602] = {
          ContentFR = "Pour le travail lui-même ?",
          DialogueId = 90210602,
          GUID = "E1D530E4",
          NextDialogue = 90210603,
          SpeakNpcId = 100001,
          Subtitle = "Keeping busy?",
          TalkActionId = {
            [1] = "84101:Talk02_End"
          }
        },
        [90210603] = {
          ContentFR = "Oui... Le travail remplit mes journées, il donne du sens à ce que je fais. Il me rend un peu plus heureuse. Quand je travaille, j’ai l’impression que même le soleil brille plus fort.",
          DialogueId = 90210603,
          GUID = "E1D5310E",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "Yes... Work gives me purpose. It makes me happy. When I'm busy, even the sunlight feels a little warmer.",
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_06_2",
          bForbidSkipOptions = true
        },
        [90210701] = {
          ContentFR = "Mieux que si j’étais restée, en tout cas. La Légion, c’était mon refuge... le lieu où j’avais placé tous mes rêves. Mais ces rêves se sont révélés être des mensonges, et ce que je croyais être un abri s’est transformé en enfer, celui qui a englouti ma famille à jamais...",
          DialogueId = 90210701,
          GUID = "E1D54122",
          LookAt = {
            [1] = "84101:n(0)",
            [2] = "0:n(84101)"
          },
          NextDialogue = 90210702,
          SpeakNpcId = 84101,
          Subtitle = "Better than if I'd stayed, I suppose. The Legion was once my refuge, the place where I thought my dreams could take flight. But those dreams... they turned out to be illusions, and that so-called refuge was a hell that dragged my loved one into an unending abyss of despair...",
          TalkActionId = {
            [1] = "84101:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_07_1"
        },
        [90210702] = {
          ContentFR = "Je ne peux pas tourner la page sur cette haine. Mais je n’arrive pas non plus à pointer mon arme sur ceux qui ont été mes camarades. Je suis perdue... Dis-moi, qu’est-ce que je suis censée faire ?",
          DialogueId = 90210702,
          GUID = "E1D5414C",
          NextDialogue = 90210703,
          SpeakNpcId = 84101,
          Subtitle = "Now, my heart burns with the desire for vengeance, yet I can't bring myself to aim my weapon at those I once called comrades. I feel lost... Tell me, what should I do?",
          TalkActionId = {
            [1] = "84101:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_07_2"
        },
        [90210703] = {
          ContentFR = "Je crois que c’est une question à laquelle toi seule peux répondre.",
          DialogueId = 90210703,
          GUID = "E1D54176",
          NextDialogue = 90210704,
          SpeakNpcId = 100001,
          Subtitle = "I think that's a question only you can answer."
        },
        [90210704] = {
          ContentFR = "...Pardon, je me suis laissée emporter. Tu as raison, c’est à moi de trouver la réponse, pas à toi de la porter. Même si ça risque de prendre longtemps...",
          DialogueId = 90210704,
          GUID = "E1D541A0",
          NextOptions = {
            [1] = 90210002,
            [2] = 90210003
          },
          SpeakNpcId = 84101,
          Subtitle = "...Sorry, I lost my cool. You're right — I need to figure it out on my own, instead of placing that weight on you. Though... it might take me some time.",
          TalkActionId = {
            [1] = "84101:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Lise/vo_topic_07_3",
          bForbidSkipOptions = true
        },
        [90210901] = {
          ContentFR = "Ce plan est ultra précis, calibré à la seconde. Le suivre doit procurer une vraie satisfaction. Juste... difficile à croire que ça vienne de l’officier Randy.",
          DialogueId = 90210901,
          GUID = "E1D561F2",
          SpeakNpcId = 84101,
          Subtitle = "This proposal is remarkably detailed, down to every second accounted for. Following it through must be immensely satisfying. It's just... hard to believe something like this was put together by Lieutenant Colonel Randy.",
          VoiceName = "voice/$Locale$/char/Lise/vo_companio_02"
        },
        [90220000] = {
          ContentFR = "Dans ce monde en proie aux tourments, trouver un havre de paix pour s’accorder un bref répit est déjà un doux privilège.",
          DialogueId = 90220000,
          GUID = "E1DB36E9",
          SpeakNpcId = 81502,
          Subtitle = "In a land so fraught with turmoil, having such a tranquil place for even a brief moment of peace is a rare comfort.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_idle"
        },
        [90220001] = {
          ContentFR = "Ah, te voilà, {性别:mon cher enfant|ma chère enfant}. Bonjour. Veux-tu me parler de quelque chose ?",
          DialogueId = 90220001,
          GUID = "E1DB36EA",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextOptions = {
            [1] = 902200011,
            [2] = 902200012,
            [3] = 902200013,
            [4] = 902200014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81502,
          Subtitle = "Ah, it's you, my dear child. Good day. Is there something on your mind you'd like to share with me?",
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90220002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90220002,
          GUID = "90220002.0",
          NextDialogue = 90220001,
          Subtitle = "Let's talk about something else"
        },
        [90220003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90220003,
          GUID = "90220003.0",
          Subtitle = "Goodbye"
        },
        [90220101] = {
          ContentFR = "Oui, durant ces longues années, j’ai parcouru Atlasia, ou plutôt, j’ai erré. J’ai foulé chaque parcelle de terre et caressé chaque grain de sable du bout des doigts.",
          DialogueId = 90220101,
          GUID = "E1DB4752",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220102,
          SpeakNpcId = 81502,
          Subtitle = "Indeed. Over the course of endless time, I've travelled — or perhaps wandered — through every corner of Atlasia, treading upon every inch of its soil and tracing every grain of sand with my fingertips.",
          TalkActionId = {
            [1] = "81502:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_1"
        },
        [90220102] = {
          ContentFR = "Alors, quel est ton endroit préféré ?",
          DialogueId = 90220102,
          GUID = "E1DB477C",
          NextDialogue = 90220103,
          SpeakNpcId = 100001,
          Subtitle = "So, which place is your favourite?",
          TalkActionId = {
            [1] = "81502:Explain01_End"
          }
        },
        [90220103] = {
          ContentFR = "Quand on a vu assez d’endroits, on réalise que les paysages sont semblables. Qu’il s'agisse des neiges du Nord, des sables de Khemet ou de la fumée qui s’échappe des cheminées de Huaxu, ce ne sont que différentes nuances de brume flottant à travers la forêt.",
          DialogueId = 90220103,
          GUID = "E1DB47A6",
          NextDialogue = 90220104,
          SpeakNpcId = 81502,
          Subtitle = "Once you've seen enough, you'll find that the scenery of all places is not so different after all. Whether it's the snows of the North, the sands of Khemet, or the smoke curling from the chimneys of Huaxu, they are all but different shades of mist drifting through the forest.",
          TalkActionId = {
            [1] = "81502:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_2"
        },
        [90220104] = {
          ContentFR = "Si je devais choisir... Ce serait les montagnes et les forêts d’Aethyrie. L’air qui y règne m'apporte la paix.",
          DialogueId = 90220104,
          GUID = "E1DB47D0",
          NextDialogue = 90220105,
          SpeakNpcId = 81502,
          Subtitle = "If I had to choose, though... it would be the mountains and forests of Aethyrie. The air there brings me the most peace.",
          TalkActionId = {
            [1] = "81502:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_3"
        },
        [90220105] = {
          ContentFR = "Il faudra que j’aille voir ça un jour.",
          DialogueId = 90220105,
          GUID = "E1DB47FA",
          NextDialogue = 90220106,
          SpeakNpcId = 100001,
          Subtitle = "I'll have to visit someday."
        },
        [90220106] = {
          ContentFR = "Peut-être le feras-tu.",
          DialogueId = 90220106,
          GUID = "E1DB4824",
          NextDialogue = 90220107,
          SpeakNpcId = 81502,
          Subtitle = "Perhaps you will.",
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_4"
        },
        [90220107] = {
          ContentFR = "Si un jour tu te rends dans la Forêt d’Émeraude, pourrais-tu m’y rapporter un bouquet d’asters blancs ? Sous cette terre reposent mes amis, mon enfant, et une part de moi-même d’autrefois.",
          DialogueId = 90220107,
          GUID = "E1DB484E",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          Subtitle = "Should you wander into the Emerald Forest, would you mind bringing a bouquet of white asters for me? Beneath its earth rest my friends, my child, and a version of myself from long ago.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_01_5",
          bForbidSkipOptions = true
        },
        [90220201] = {
          ContentFR = "La Mer du Silence est le berceau et le dernier refuge de tous les êtres vivants. C’est vers elle que retournent les défunts, et c’est d’elle que naît à nouveau la vie... Tout comme les nuages mourants se fondent en pluie dans la terre, pour que les fleurs y renaissent.",
          DialogueId = 90220201,
          GUID = "E1DB57BA",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220202,
          SpeakNpcId = 81502,
          Subtitle = "The Misty Sea is the birthplace and final rest of all living beings. To the Misty Sea, the deceased return, and from there, life begins anew... just as dying clouds dissolve into the earth as rain, only for flowers to bloom again from that very soil.",
          TalkActionId = {
            [1] = "81502:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_1"
        },
        [90220202] = {
          ContentFR = "Vais-je y aller un jour, moi aussi ?",
          DialogueId = 90220202,
          GUID = "E1DB57E4",
          NextDialogue = 90220203,
          SpeakNpcId = 100001,
          Subtitle = "Will I go there someday, too?",
          TalkActionId = {
            [1] = "81502:Confident_End"
          }
        },
        [90220203] = {
          ContentFR = "Je le crois, mon enfant. Un jour, tu rejoindras la Mer du Silence, dans les bras de la Déesse Embla.",
          DialogueId = 90220203,
          GUID = "E1DB580E",
          NextDialogue = 90220204,
          SpeakNpcId = 81502,
          Subtitle = "I believe so, my child. One day, you will journey to the Misty Sea, into the embrace of Mother Embla.",
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_2"
        },
        [90220204] = {
          ContentFR = "Ça fait un peu peur...",
          DialogueId = 90220204,
          GUID = "E1DB5838",
          NextDialogue = 90220205,
          SpeakNpcId = 100001,
          Subtitle = "That sounds... a bit scary."
        },
        [90220205] = {
          ContentFR = "Mon enfant, aime tout ce que la vie offre, mais n’aie pas peur de la fin. La mort n’est pas une souffrance, mais la conclusion inévitable.",
          DialogueId = 90220205,
          GUID = "E1DB5862",
          NextDialogue = 90220206,
          SpeakNpcId = 81502,
          Subtitle = "My dear child, cherish all that life offers, yet do not shrink from its passing. Demise is not suffering, but the inevitable conclusion of life's journey.",
          TalkActionId = {
            [1] = "81502:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_3"
        },
        [90220206] = {
          ContentFR = "Si tu es {性别:fatigué|fatiguée}, viens te reposer dans mes bras... N’aie crainte, ce ne sera pas un sommeil éternel. Il te reste tant à accomplir.",
          DialogueId = 90220206,
          GUID = "E1DB588C",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          Subtitle = "Should you ever grow weary, rest in my arms for a while... There is no need to fear — this will not be your eternal sleep. There is still much for you to fulfil in this world.",
          TalkActionId = {
            [1] = "81502:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90220301] = {
          ContentFR = "Cela t’étonne ? Lors de la Grande Migration, j’ai combattu en première ligne. J’étais alors une guerrière chevronnée.",
          DialogueId = 90220301,
          GUID = "E1DB6822",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220302,
          SpeakNpcId = 81502,
          Subtitle = "Did that surprise you? Long ago, during the Great Migration, I stood on the front lines as a soldier well-versed in close combat.",
          TalkActionId = {
            [1] = "81502:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_1"
        },
        [90220302] = {
          ContentFR = "Même si cela remonte à très longtemps, je connais encore les bases du combat.",
          DialogueId = 90220302,
          GUID = "E1DB684C",
          NextDialogue = 90220303,
          SpeakNpcId = 81502,
          Subtitle = "Though those days are far behind me, I still remember the essentials of fighting.",
          TalkActionId = {
            [1] = "81502:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_2"
        },
        [90220303] = {
          ContentFR = "Au cours de mes errances, il m’est souvent arrivé d’affronter des bêtes errantes. Leurs griffes m’ont laissé des cicatrices, des hématomes... et parfois, une mort que j’aurais dû accepter.",
          DialogueId = 90220303,
          GUID = "E1DB6876",
          NextDialogue = 90220304,
          SpeakNpcId = 81502,
          Subtitle = "During my wanderings, I've often faced roaming beasts. Their claws and fangs have left me with scars, bruises, and even deaths I should have rightfully endured.",
          TalkActionId = {
            [1] = "81502:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_3"
        },
        [90220304] = {
          ContentFR = "C’est difficile de t’imaginer en combat rapproché...",
          DialogueId = 90220304,
          GUID = "E1DB68A0",
          NextDialogue = 90220305,
          SpeakNpcId = 100001,
          Subtitle = "It's hard to picture you grappling hand-to-hand...",
          TalkActionId = {
            [1] = "81502:Talk02_End"
          }
        },
        [90220305] = {
          ContentFR = "Même la lune éternelle décroît et renaît, changeant chaque nuit. Les êtres humains sont, bien sûr, bien plus complexes... surtout ceux qui, comme moi, ont vécu plusieurs vies au-delà du temps des mortels.",
          DialogueId = 90220305,
          GUID = "E1DB68CA",
          NextDialogue = 90220306,
          SpeakNpcId = 81502,
          Subtitle = "Even the eternal moon wanes and waxes, ever changing. Humans, naturally, are far more complex — especially one who's lived countless lifetimes beyond a mortal span.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_4"
        },
        [90220306] = {
          ContentFR = "Si tu veux, je te raconterai un jour cette histoire en détail.",
          DialogueId = 90220306,
          GUID = "E1DB68F4",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          Subtitle = "If you're curious about those days, I'll recount them in detail for you another time.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_03_5",
          bForbidSkipOptions = true
        },
        [90220401] = {
          ContentFR = "Des amis... Si l’on s’en tient à la définition habituelle du mot, alors oui, j’en ai eu beaucoup au fil de ma longue existence.",
          DialogueId = 90220401,
          GUID = "E1DB788A",
          LookAt = {
            [1] = "81502:n(0)",
            [2] = "0:n(81502)"
          },
          NextDialogue = 90220402,
          SpeakNpcId = 81502,
          Subtitle = "\"Friends\"... By the common definition of the word, I've had many over my long years.",
          TalkActionId = {
            [1] = "81502:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_1"
        },
        [90220402] = {
          ContentFR = "Mais quand j’entends ce mot, je pense d’abord à Alexis et Erika, ceux qui m’ont menée hors d’Élysium.",
          DialogueId = 90220402,
          GUID = "E1DB78B4",
          NextDialogue = 90220403,
          SpeakNpcId = 81502,
          Subtitle = "Yet when I hear that word, the first who come to mind are Lexis and Erika, the two who once led me away from Elysium.",
          TalkActionId = {
            [1] = "81502:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_2"
        },
        [90220403] = {
          ContentFR = "Comment étaient-ils ?",
          DialogueId = 90220403,
          GUID = "E1DB78DE",
          NextDialogue = 90220404,
          SpeakNpcId = 100001,
          Subtitle = "What were they like?"
        },
        [90220404] = {
          ContentFR = "Dans les annales de l’histoire et les récits héroïques, ils sont souvent représentés comme le Sage ayant levé le voile d’ignorance qui recouvrait les dieux, apportant la vérité au monde, et l’Héroïne qui, en croyant en cette vérité, a sacrifié sa vie pour la cause qu’ils servaient...",
          DialogueId = 90220404,
          GUID = "E1DB7908",
          NextDialogue = 90220405,
          SpeakNpcId = 81502,
          Subtitle = "In the annals of history and the tales of heroes, they're often portrayed as the Sage who tore away the gods' veil of ignorance, and the Heroine who gave her life for the Sage's cause...",
          TalkActionId = {
            [1] = "81502:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_3"
        },
        [90220405] = {
          ContentFR = "Pourtant, dans mes souvenirs, ce sont simplement Alexis et Erika.",
          DialogueId = 90220405,
          GUID = "E1DB7932",
          NextDialogue = 90220406,
          SpeakNpcId = 81502,
          Subtitle = "But in my memories, they are simply Lexis and Erika.",
          TalkActionId = {
            [1] = "81502:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_4"
        },
        [90220406] = {
          ContentFR = "Erika était une jeune fille joyeuse et courageuse, adorée de tous. Alexis, brillant mais souvent plongé dans ses pensées, donnait parfois l’impression d’être un peu lent.",
          DialogueId = 90220406,
          GUID = "E1DB795C",
          NextDialogue = 90220407,
          SpeakNpcId = 81502,
          Subtitle = "Erika was a brave and lively young woman, with a spirit that drew everyone to her. Lexis, though brilliant, often overthought things. He'd suddenly lapse into deep musings, which, ironically, made him seem a bit slow.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_5"
        },
        [90220407] = {
          ContentFR = "Tu te souviens d’anecdotes amusantes ?",
          DialogueId = 90220407,
          GUID = "E1DB7986",
          NextDialogue = 90220408,
          SpeakNpcId = 100001,
          Subtitle = "Any fun stories?"
        },
        [90220408] = {
          ContentFR = "Hmm... Je me souviens d’une fois où Alexis cherchait à s’excuser auprès d’Erika pour quelque chose qu’il avait fait. Alors, sur un coup de tête, Erika a pointé du doigt une cible que les soldats utilisaient pour s’entraîner au tir à l’arc, et lui a dit qu’elle le pardonnerait... s’il parvenait à toucher le centre.",
          DialogueId = 90220408,
          GUID = "E1DB79B0",
          NextDialogue = 90220409,
          SpeakNpcId = 81502,
          Subtitle = "Mm... There was one time Lexis tried to apologize to Erika for something he'd done. On a whim, she pointed to one of the soldiers' archery training dummies, saying she'd forgive him if he could hit the bullseye...",
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_6"
        },
        [90220409] = {
          ContentFR = "Bien sûr, elle ne le pensait pas vraiment. Même les soldats ne touchaient pas toujours le centre... et Alexis, lui, n’était pas fait pour l’arc, mais pour la plume.",
          DialogueId = 90220409,
          GUID = "E1DB79DA",
          NextDialogue = 90220410,
          SpeakNpcId = 81502,
          Subtitle = "Of course, she didn't mean it seriously. Not even all the soldiers could manage it, let alone Lexis, whose hands were meant for quills and scrolls, not bows or blades.",
          TalkActionId = {
            [1] = "81502:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_7"
        },
        [90220410] = {
          ContentFR = "Mais il l’a prise au sérieux et s’est entraîné toute la nuit après le départ des soldats.",
          DialogueId = 90220410,
          GUID = "E1DB7A04",
          NextDialogue = 90220411,
          SpeakNpcId = 81502,
          Subtitle = "But he took her words to heart. After the soldiers left, he stayed behind and practised alone, long into the night.",
          TalkActionId = {
            [1] = "81502:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_8"
        },
        [90220411] = {
          ContentFR = "Comme tu peux l’imaginer, l’histoire n’est pas un conte de héros. Même un esprit aussi brillant que Alexis avait ses limites. Il s’est tant exercé que ses paumes en sont devenues ensanglantées. Erika lui a alors bandé les mains, mais il n’a jamais réussi à toucher le centre de la cible.",
          DialogueId = 90220411,
          GUID = "E1DB7A2E",
          NextDialogue = 90220412,
          SpeakNpcId = 81502,
          Subtitle = "As you might guess, true history is not a tale of omnipotent heroes. Even someone as brilliant as Lexis had his limits — he practised until his palms bled. Erika ended up wrapping them in linen, but he never did strike the mark.",
          TalkActionId = {
            [1] = "81502:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_9"
        },
        [90220412] = {
          ContentFR = "Ce qui est drôle, c’est que je ne me souviens même plus pourquoi ils s’étaient disputés au départ. C’est étrange, non ? Aujourd’hui, quand je repense à eux, ce sont toujours ces petits riens, ces détails sans importance, qui me reviennent en premier.",
          DialogueId = 90220412,
          GUID = "E1DB7A58",
          NextDialogue = 90220413,
          SpeakNpcId = 81502,
          Subtitle = "The funny thing is, I can't even recall why they argued in the first place. Strange, isn't it? When I think of them now, it's always these small, insignificant details that come to mind first.",
          TalkActionId = {
            [1] = "81502:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_10"
        },
        [90220413] = {
          ContentFR = "Ça avait l’air d’être une époque très heureuse.",
          DialogueId = 90220413,
          GUID = "E1DB7A82",
          NextDialogue = 90220414,
          SpeakNpcId = 100001,
          Subtitle = "Sounds like some golden memories."
        },
        [90220414] = {
          ContentFR = "Oui, c’était... vraiment des jours heureux. Mais c’était il y a bien longtemps.",
          DialogueId = 90220414,
          GUID = "E1DB7AAC",
          NextOptions = {
            [1] = 90220002,
            [2] = 90220003
          },
          SpeakNpcId = 81502,
          Subtitle = "Indeed. Those were such precious, joyful days... But they are far behind me now.",
          TalkActionId = {
            [1] = "81502:Agree"
          },
          VoiceName = "voice/$Locale$/char/Nifu/vo_topic_04_11",
          bForbidSkipOptions = true
        },
        [90220501] = {
          ContentFR = "Nul ne peut fuir son passé éternellement. Un jour viendra où tu devras lui faire face... Puisses-tu alors trouver la force qui te permettra de le combattre.",
          DialogueId = 90220501,
          GUID = "E1DB88F2",
          SpeakNpcId = 81502,
          Subtitle = "No soul can outrun its past forever. In time, you will have to confront yours. May you have the strength to face it when that moment arrives.",
          VoiceName = "voice/$Locale$/char/Nifu/vo_companio_01"
        },
        [90220601] = {
          ContentFR = "Ma chère enfant, il y a en toi une essence qui me semble familière... Serait-ce que toi aussi, tu viens d’une époque révolue, comme moi ?",
          DialogueId = 90220601,
          GUID = "E1DB995A",
          SpeakNpcId = 81502,
          Subtitle = "My dear, you carry an aura I find quite familiar. Could it be that you, like me, hail from bygone days?",
          VoiceName = "voice/$Locale$/char/Nifu/vo_companio_02"
        },
        [90230000] = {
          ContentFR = "J’ai fait repousser tous mes rendez-vous. Ces jours-ci, je veux seulement savourer la tranquillité à tes côtés, loin du tumulte extérieur. Cette fois, est-ce sincérité... ou simple stratégie ? À toi de deviner.",
          DialogueId = 90230000,
          GUID = "E1E19F60",
          SpeakNpcId = 84102,
          Subtitle = "I had my secretary clear my schedule for the next few days. For now, I wish only to savour this tranquillity with you, untouched by the clamour of the outside world. Is this out of sincerity, or another calculated move? Why don't you take a guess?",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_idle"
        },
        [90230001] = {
          ContentFR = "Tu as choisi de venir me voir... Es-tu encore en colère ? {性别:Perdu ? Ou simplement indifférent|Perdue ? Ou simplement indifférente} à mon égard ? Peu importe. Nous avons tout le temps pour y voir clair.",
          DialogueId = 90230001,
          GUID = "E1E19F8A",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextOptions = {
            [1] = 902300011,
            [2] = 902300012,
            [3] = 902300013,
            [4] = 902300014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 84102,
          Subtitle = "Ah, so you've come to see me... Are you still resentful? Conflicted, perhaps? Or have you become indifferent toward me? It makes no difference. We have all the time in the world to figure it out.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90230002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90230002,
          GUID = "E1E19FB4",
          NextDialogue = 90230001,
          Subtitle = "Let's talk about something else"
        },
        [90230003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90230003,
          GUID = "E1E19FDE",
          Subtitle = "Goodbye"
        },
        [90230101] = {
          ContentFR = "Rien n’échappe à la table des négociations. La seule question est de savoir : quel prix suffit à faire pencher la balance en ta faveur ?",
          DialogueId = 90230101,
          GUID = "E1E1AFF2",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230102,
          SpeakNpcId = 84102,
          Subtitle = "There is nothing that cannot be leveraged in a negotiation. The only question is — what price will move the scales in your favour?",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_1"
        },
        [90230102] = {
          ContentFR = "Même une vie ?",
          DialogueId = 90230102,
          GUID = "E1E1B01C",
          NextDialogue = 90230103,
          SpeakNpcId = 100001,
          Subtitle = "Even when the price is your life?"
        },
        [90230103] = {
          ContentFR = "Exactement. La tienne, la mienne, ou celle de milliers d'autres... face à des enjeux plus grands, elles ne sont que des jetons à miser.",
          DialogueId = 90230103,
          GUID = "E1E1B046",
          NextDialogue = 90230104,
          SpeakNpcId = 84102,
          Subtitle = "Indeed. Your life, mine, and the lives of countless others — each is but a piece on a grander board, their worth determined only by the stakes at play.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_2"
        },
        [90230104] = {
          ContentFR = "Pour des êtres aussi insignifiants que nous, pouvoir troquer ce que l’on possède contre ce que l’on désire... n’est-ce pas déjà une forme de chance ?",
          DialogueId = 90230104,
          GUID = "E1E1B070",
          NextDialogue = 90230105,
          SpeakNpcId = 84102,
          Subtitle = "For those as insignificant as we, to exchange what little we have for what we desire... is that not, in itself, a stroke of fortune?",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_3"
        },
        [90230105] = {
          ContentFR = "Cette réponse te dérange ? Alors vas-y, prouve-moi que j’ai tort.",
          DialogueId = 90230105,
          GUID = "E1E1B09A",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          Subtitle = "Does my answer unsettle you? Then, by all means, prove me wrong.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90230201] = {
          ContentFR = "Hmm... Ne t’attarde pas sur les gains ou les pertes immédiats. Apprends à céder quand il le faut. Savoir lire les gens, les utiliser, leur offrir des faveurs... Il faut qu’ils te respectent, qu’ils t’estiment, mais aussi qu’ils te craignent. Le vrai pouvoir naît de cet équilibre subtil.",
          DialogueId = 90230201,
          GUID = "E1E1C05A",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230202,
          SpeakNpcId = 84102,
          Subtitle = "Mmm... Never lose yourself in fleeting profits and losses. Play the long game. Be generous when needed. Learn to read people, to use them, and to grant them favours, so that they respect you, admire you, and also fear you. True power lies in that delicate balance.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_02_1"
        },
        [90230202] = {
          ContentFR = "Ce n’est pas vraiment ce que j’imaginais...",
          DialogueId = 90230202,
          GUID = "E1E1C084",
          NextDialogue = 90230203,
          SpeakNpcId = 100001,
          Subtitle = "That's not quite what I had in mind."
        },
        [90230203] = {
          ContentFR = "Hé hé... Les marchandises ont un prix. Les relations humaines, elles, n’en ont pas. Ceux qui comptent chaque sou ne quitteront jamais l’étal devant leur porte. Mais ceux qui savent se servir des vents de l’influence... ceux-là peuvent atteindre des sommets que le simple commerce ne permettra jamais.",
          DialogueId = 90230203,
          GUID = "E1E1C0AE",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          Subtitle = "Heh. Goods have fixed prices, but human connections are a different currency altogether. Those who haggle over every coin will remain forever bound to their little corner of the market. Only by mastering the art of influence can one rise above mere trade and ascend to true greatness.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90230301] = {
          ContentFR = "Je suis bien souvent prise dans une foule de détails sans importance, rarement libre de mon temps.\nLe mot loisir a, pour moi, un goût de luxe.",
          DialogueId = 90230301,
          GUID = "E1E1D0C2",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230302,
          SpeakNpcId = 84102,
          Subtitle = "I am often entangled in the minutiae of business and rarely afforded the luxury of leisure.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_1"
        },
        [90230302] = {
          ContentFR = "Mais si par chance le destin m’accordait une parenthèse, aussi brève soit-elle... je crois que j’irais au théâtre. Qu’il s’agisse des contes chantés de Huaxu, des opéras de l’Empire, des pièces dramatiques, ou même des projections venues d’outre-mer, j’y trouve toujours un certain plaisir.",
          DialogueId = 90230302,
          GUID = "E1E1D0EC",
          NextDialogue = 90230303,
          SpeakNpcId = 84102,
          Subtitle = "Yet, if fate were to grant me a fleeting moment of respite... I would likely seek solace in the theatre. Be it the age-old storytelling traditions of Huaxu, the refined operas of the Empire, or the avant-garde films gaining traction overseas — each offers its own intrigue.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_2"
        },
        [90230303] = {
          ContentFR = "Alors notre rencontre au théâtre n’était pas fortuite.",
          DialogueId = 90230303,
          GUID = "E1E1D116",
          NextDialogue = 90230304,
          SpeakNpcId = 100001,
          Subtitle = "It seems our meeting at the theatre wasn't just a coincidence, then."
        },
        [90230304] = {
          ContentFR = "Hé hé... Non, en effet. Le théâtre capture quelques fragments de lumière, et pourtant, il dit tant sur l’ombre du cœur humain. Ce cœur-là... insaisissable, indéchiffrable, toujours surprenant, toujours fascinant.",
          DialogueId = 90230304,
          GUID = "E1E1D140",
          NextDialogue = 90230305,
          SpeakNpcId = 84102,
          Subtitle = "Heh... No, I suppose not. Theatre distils fleeting moments of life, yet within those fragments, it unveils profound truths about the human soul — one that defies reason, thrives in contradiction, and remains endlessly captivating in its unpredictability.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_3"
        },
        [90230305] = {
          ContentFR = "Et toi, dans les jours à venir... quelles surprises m’as-tu réservées ? Je suis curieuse de le découvrir.",
          DialogueId = 90230305,
          GUID = "E1E1D16A",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          Subtitle = "So, what unexpected turns will you bring to my story? I shall be watching with keen interest.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90230401] = {
          ContentFR = "Oh ? Tu as perçu cela aussi... Ce n’est qu’une vieille habitude qui me poursuit encore.",
          DialogueId = 90230401,
          GUID = "E1E1E12A",
          LookAt = {
            [1] = "84102:n(0)",
            [2] = "0:n(84102)"
          },
          NextDialogue = 90230402,
          SpeakNpcId = 84102,
          Subtitle = "Hmm? So, you've noticed. An old habit, nothing more.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_1"
        },
        [90230402] = {
          ContentFR = "Enfant, j’ai été prise au piège dans un ravin après un accident, trois jours et trois nuits sans lumière, sans repère. C’est probablement là que cette faiblesse a germé.",
          DialogueId = 90230402,
          GUID = "E1E1E154",
          NextDialogue = 90230403,
          SpeakNpcId = 84102,
          Subtitle = "When I was little, an accident left me stranded in a pitch-black ravine for three days and nights. It was then this... tendency took root.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_2"
        },
        [90230403] = {
          ContentFR = "Dans ce monde, chacun a ses propres ombres à craindre. Je ne fais pas exception... Ce regard étonné, est-ce que tu t’attendais à autre chose ?",
          DialogueId = 90230403,
          GUID = "E1E1E17E",
          NextDialogue = 90230404,
          SpeakNpcId = 84102,
          Subtitle = "In this world, everyone harbours their own fears. I am no exception... You seem surprised. May I ask why?",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_3"
        },
        [90230404] = {
          ContentFR = "Je pensais simplement... que tu n’avais pas de faille.",
          DialogueId = 90230404,
          GUID = "E1E1E1A8",
          NextDialogue = 90230405,
          SpeakNpcId = 100001,
          Subtitle = "I just thought... you don't seem like someone who has fears or weaknesses."
        },
        [90230405] = {
          ContentFR = "Hé hé... Tu as raison. Une faiblesse, pour un marchand, n’est rien d’autre qu’un obstacle.",
          DialogueId = 90230405,
          GUID = "E1E1E1D2",
          NextDialogue = 90230406,
          SpeakNpcId = 84102,
          Subtitle = "Heh... Correct. Weakness can be a merchant's undoing.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_4"
        },
        [90230406] = {
          ContentFR = "J’ai donc appris à la dompter. Face à un adversaire, je suis capable de l’effacer d’un revers. Mais face à toi... je peux me permettre d’être vraie.",
          DialogueId = 90230406,
          GUID = "E1E1E1FC",
          NextOptions = {
            [1] = 90230002,
            [2] = 90230003
          },
          SpeakNpcId = 84102,
          Subtitle = "I underwent rigorous trainings to suppress this fear. At the negotiating table, I can cast it aside with ease. But in your presence, there's no need for such pretences.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_topic_04_5",
          bForbidSkipOptions = true
        },
        [90230501] = {
          ContentFR = "Ton parfum est intense, passionné, empreint d’une douceur sans retenue, un contraste marqué avec la subtilité des senteurs de Huaxu. Cela éveille ma curiosité.",
          DialogueId = 90230501,
          GUID = "E1E1F192",
          SpeakNpcId = 84102,
          Subtitle = "Your perfume carries a bold, intoxicating sweetness — unrestrained, unapologetic. A striking contrast to the subtle fragrances of Huaxu. I'm intrigued.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_companio_01"
        },
        [90230601] = {
          ContentFR = "J’ai cru voir en toi un reflet de quelqu’un que j’ai connu autrefois... Non, je dois me tromper. Oublie ce que je viens de dire. ",
          DialogueId = 90230601,
          GUID = "E1E201FA",
          SpeakNpcId = 84102,
          Subtitle = "I saw a trace of someone I once knew in you... No, I must be mistaken. Pay me no mind.",
          VoiceName = "voice/$Locale$/char/Zhiliu/vo_companio_03"
        },
        [90240000] = {
          ContentFR = "C’est lumineux et grand, mais il y a trop de tables et de chaises. Sinon, ce serait parfait pour s’entraîner au combat.",
          DialogueId = 90240000,
          GUID = "E1E80800",
          SpeakNpcId = 81503,
          Subtitle = "Bright and roomy — would be a perfect spot for sparring if there weren't so many tables and chairs in the way.",
          VoiceName = "voice/$Locale$/char/Kezhou/vo_idle"
        },
        [90240001] = {
          ContentFR = "Un jour parfait pour boire un coup et chanter ! Allez, laisse-moi finir ce verre, et ensuite, on ira régler leur compte à ceux qui le méritent.\nQuoi ? J’ai dit la même chose hier ? Normal. Chaque jour devrait commencer comme ça.",
          DialogueId = 90240001,
          GUID = "E1E8082A",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextOptions = {
            [1] = 902400011,
            [2] = 902400012,
            [3] = 902400013,
            [4] = 902400014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81503,
          Subtitle = "Today's perfect for drinking and singing! Come on, let me finish this glass, and then we'll chase down the sinners who deserve my sword. What? I said the same thing yesterday? Well, every day's a fine day to live like this, don't you think?",
          VoiceName = "voice/$Locale$/char/Kezhou/vo_welcome",
          bForbidSkipOptions = true
        },
        [90240002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90240002,
          GUID = "E1E80854",
          NextDialogue = 90240001,
          Subtitle = "Let's talk about something else"
        },
        [90240003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90240003,
          GUID = "E1E8087E",
          Subtitle = "Goodbye"
        },
        [90240101] = {
          ContentFR = "Tu aimes aussi le maniement de l’épée ? Je m’en doutais, avec une lame comme la tienne, tu dois pas être {性别:mauvais|mauvaise}. Allez, un petit duel amical, qu’on voie ce que tu vaux !",
          DialogueId = 90240101,
          GUID = "E1E81892",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240102,
          SpeakNpcId = 81503,
          Subtitle = "You're into swordplay too? Figured as much — you've got a fine blade there. You must be pretty good with it. Let's have a friendly spar and see what you've got!",
          TalkActionId = {
            [1] = "81503:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_1"
        },
        [90240102] = {
          ContentFR = "Pour être honnête, ça fait un bail que j’ai pas croisé un vrai adversaire à ma hauteur. Mais d’après mon maître, je suis trop franc, pas assez rusé, il disait que pour progresser, je devais apprendre à jouer la comédie.",
          DialogueId = 90240102,
          GUID = "E1E818BC",
          NextDialogue = 90240103,
          SpeakNpcId = 81503,
          Subtitle = "Honestly, it's been ages since I've met anyone truly on par with me. Though, my shifu always said I need more honing because I'm too blunt — and that I should work on my acting.",
          TalkActionId = {
            [1] = "81503:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_2"
        },
        [90240103] = {
          ContentFR = "L’art de jouer la comédie, ça fait aussi partie du maniement de l’épée ?",
          DialogueId = 90240103,
          GUID = "E1E818E6",
          NextDialogue = 90240104,
          SpeakNpcId = 100001,
          Subtitle = "Is acting part of swordsmanship?"
        },
        [90240104] = {
          ContentFR = "Pas pour moi. Mais lui disait toujours qu’une épée, ça se manie avec la tête autant qu’avec les bras. « Dissimuler sa force en feignant la faiblesse », « vaincre sans combattre », « submerger le petit nombre par le grand nombre »... Pour lui, c’était ça, la vraie maîtrise.",
          DialogueId = 90240104,
          GUID = "E1E81910",
          NextDialogue = 90240105,
          SpeakNpcId = 81503,
          Subtitle = "Not exactly how I see it, but he always said that swordsmanship isn't just about skill; it's about strategy. Stuff like \"conceal your strength by feigning weakness,\" \"subdue the enemy without fighting,\" and \"overwhelm the few with the many.\" Said that's what separates the good from the great.",
          TalkActionId = {
            [1] = "81503:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_3"
        },
        [90240105] = {
          ContentFR = "Quand j’étais gosse, il me jouait toujours le même numéro : il faisait semblant d’être rouillé, pas très doué. Il disait : « Si tu arrives à me foutre au sol, t’auras plus jamais besoin de t’entraîner. » J’ai passé un an à essayer... j’ai même pas effleuré sa manche.",
          DialogueId = 90240105,
          GUID = "E1E8193A",
          NextDialogue = 90240106,
          SpeakNpcId = 81503,
          Subtitle = "Back when I was a kid, he used to pull that same trick on me. He'd claim his skills were mediocre and tell me if I could knock him down, I wouldn't have to train anymore. Took me a whole year to realize I couldn't even touch his sleeve.",
          TalkActionId = {
            [1] = "81503:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_4"
        },
        [90240106] = {
          ContentFR = "Un jour, à bout de force, j’étais allongé par terre. J’ai levé les yeux : pas une trace de fatigue chez lui. Même ses faux pas étaient calculés. Toute cette mascarade... c’était de l’art.",
          DialogueId = 90240106,
          GUID = "E1E81964",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          Subtitle = "One day, I was so wiped out I just collapsed. That's when I noticed — not a single drop of sweat beneath his feet. That doddering, clumsy look of his? All an act.",
          TalkActionId = {
            [1] = "81503:Talk03_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_01_5",
          bForbidSkipOptions = true
        },
        [90240201] = {
          ContentFR = "J’ai des tas de raisons, mais au fond, c’est simple : je refuse d’être enchaîné.",
          DialogueId = 90240201,
          GUID = "E1E828FA",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240202,
          SpeakNpcId = 81503,
          Subtitle = "Plenty of reasons, really, but if I had to sum it up: I hate being bound by them.",
          TalkActionId = {
            [1] = "81503:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_1"
        },
        [90240202] = {
          ContentFR = "J’ai grandi libre comme le vent, faisant tout à ma façon, dégainant l’épée dès que je voyais une injustice. Les paroles du maître ou de Yuming ? Je n’écoutais que ce qui m’arrangeait. Le reste, ça passait par une oreille et sortait par l’autre, comme le vent qui souffle. Alors, pourquoi je me laisserais enchaîner par des lois ?",
          DialogueId = 90240202,
          GUID = "E1E82924",
          NextDialogue = 90240203,
          SpeakNpcId = 81503,
          Subtitle = "I've been free-spirited all my life, doing everything my way, drawing my sword wherever I saw injustice. I only ever listened to what I wanted to hear from my Shifu or Yuming. The rest? In one ear and out the other, like the wind passing by. So tell me, why would I let myself be chained by some laws?",
          TalkActionId = {
            [1] = "81503:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_2"
        },
        [90240203] = {
          ContentFR = "Alors, dis-moi la raison principale.",
          DialogueId = 90240203,
          GUID = "E1E8294E",
          NextDialogue = 90240204,
          SpeakNpcId = 100001,
          Subtitle = "Tell me the biggest reason then."
        },
        [90240204] = {
          ContentFR = "Je dirais que c’est le problème de beaucoup d’épéistes. Au début, tu apprends les enchaînements du rouleau, mouvement par mouvement. Contre des adversaires ordinaires, ça suffit, ton épée bouge presque toute seule.",
          DialogueId = 90240204,
          GUID = "E1E82978",
          NextDialogue = 90240205,
          SpeakNpcId = 81503,
          Subtitle = "I'd say it's the concern of a swordsman. Think of it this way — when you first learn swordsmanship, you follow the swordplay scroll move by move, right? Against regular foes, that's enough. Your sword moves instinctively.",
          TalkActionId = {
            [1] = "81503:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_3"
        },
        [90240205] = {
          ContentFR = "Mais si tu t’en tiens trop rigoureusement au rouleau, sans savoir improviser, ton épée devient juste un morceau de métal : lente, maladroite, inutile. Dès que ça sort de l’ordinaire, tu perds complètement tes moyens.",
          DialogueId = 90240205,
          GUID = "E1E829A2",
          NextDialogue = 90240206,
          SpeakNpcId = 81503,
          Subtitle = "But if you stick too closely to the scroll and can't think on your feet, your sword's no better than a lump of scrap — dull, clumsy, useless. Face something unexpected, and you'll flail around like a headless chicken.",
          TalkActionId = {
            [1] = "81503:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_4"
        },
        [90240206] = {
          ContentFR = "Pour moi, Huaxu, c’est un épéiste prisonnier de ses Neuf Chapitres de Dafeng. Ils ne peuvent même pas vaincre un vagabond comme moi, alors face à une vraie menace, ils sont condamnés. Ce ne sera qu’une question de temps avant qu’ils ne tombent.",
          DialogueId = 90240206,
          GUID = "E1E829CC",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          Subtitle = "To me, Huaxu is like a clumsy swordsman glued to their Nine Chapters of Dafeng. They can't even deal with a Drifter like me — what chance do they have against a true threat? It's only a matter of time before they fall.",
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_02_5",
          bForbidSkipOptions = true
        },
        [90240301] = {
          ContentFR = "Bien sûr ! Être épéiste, c’est maîtriser l’épée, pas forcément s’en tenir qu’à elle. À Huaxu, certains se battent même avec un pinceau ou des baguettes. Si un épéiste devait se limiter à son épée, comment ferait-il pour écrire ou manger ?",
          DialogueId = 90240301,
          GUID = "E1E83962",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240302,
          SpeakNpcId = 81503,
          Subtitle = "Of course! Being good with a sword doesn't mean you're stuck using only it. In Huaxu, there are people who can use pens and chopsticks as weapons — does that mean swordsmen are supposed to starve or never write?",
          TalkActionId = {
            [1] = "81503:Agree"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_03_1"
        },
        [90240302] = {
          ContentFR = "C’est dommage... Je pensais que tu pouvais trancher une balle en deux avec ton épée.",
          DialogueId = 90240302,
          GUID = "E1E8398C",
          NextDialogue = 90240303,
          SpeakNpcId = 100001,
          Subtitle = "That's disappointing. I was hoping you could do stuff like slicing a bullet in half with your sword."
        },
        [90240303] = {
          ContentFR = "Je peux, oui. Mais à quoi bon ? Esquiver, c’est bien plus simple. Même les sangliers savent qu’il vaut mieux croquer un radis que ronger de l’écorce.",
          DialogueId = 90240303,
          GUID = "E1E839B6",
          NextDialogue = 90240304,
          SpeakNpcId = 81503,
          Subtitle = "Oh, I can do that. But why bother? Dodging is way easier, after all. Even boars in the woods know to go for radishes over tree bark when they can.",
          TalkActionId = {
            [1] = "81503:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_03_2"
        },
        [90240304] = {
          ContentFR = "Cela dit, si jamais je tombe sur un adversaire digne de ce nom, tu peux être sûr que je dégainerai mon épée et que je me battrai à fond.",
          DialogueId = 90240304,
          GUID = "E1E839E0",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          Subtitle = "That said, if I ever meet a worthy opponent, you can bet I'll draw my sword and go all out.",
          TalkActionId = {
            [1] = "81503:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90240401] = {
          ContentFR = "C'est vrai. Maintenant que tu le dis, je peux t’en citer pas mal. Des « Roi Untel », « Seigneur Machin », ou des « Immortels Bidule ». Les animaux sont populaires comme surnoms : dragon, tigre, lion, grue... un vrai zoo !",
          DialogueId = 90240401,
          GUID = "E1E849CA",
          LookAt = {
            [1] = "81503:n(0)",
            [2] = "0:n(81503)"
          },
          NextDialogue = 90240402,
          SpeakNpcId = 81503,
          Subtitle = "They sure do. Now that you mention it, I can think of quite a few. Stuff like \"King So-and-So,\" \"Lord Something,\" or \"Immortal This-and-That.\" Animals are the go-to — dragons, tigers, lions, cranes, you name it. It's like a whole zoo out there.",
          TalkActionId = {
            [1] = "81503:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_1"
        },
        [90240402] = {
          ContentFR = "Et tu sais comment ça marche ? Plus le surnom est long, moins le gars est doué. Quatre mots ? Un débutant. Trois ? Pas mal. Deux ? Quelqu’un avec qui il vaut mieux ne pas chercher des ennuis. Et ceux qui n'ont pas de surnom du tout ? Ce sont les véritables grands maîtres.",
          DialogueId = 90240402,
          GUID = "E1E849F4",
          NextDialogue = 90240403,
          SpeakNpcId = 81503,
          Subtitle = "Here's how it works: the longer the title, the lousier the skills. Four words? A newbie. Three? Not bad. Two — that's someone you don't want to mess with. And those with no nickname at all? They're the true grandmasters.",
          TalkActionId = {
            [1] = "81503:Angry01_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_2"
        },
        [90240403] = {
          ContentFR = "Kezhou, c’est ton vrai nom ou un surnom ?",
          DialogueId = 90240403,
          GUID = "E1E84A1E",
          NextDialogue = 90240404,
          SpeakNpcId = 100001,
          Subtitle = "So is Kezhou your real name or a nickname?"
        },
        [90240404] = {
          ContentFR = "Je parcours ce monde sous mon vrai nom, bien sûr. Je sais, ça peut sembler inventé. Même mon maître me le répétait souvent : un nom comme celui-ci fait croire aux gens que tu es un prodige, et ça ne t’apporte que des ennuis.",
          DialogueId = 90240404,
          GUID = "E1E84A48",
          NextDialogue = 90240405,
          SpeakNpcId = 81503,
          Subtitle = "I walk this world with my real name, of course. I know, it sounds made-up, doesn't it? Even my shifu used to say so — warned me that a name like this would have people mistaking me for some prodigy, and that'd only bring me trouble.",
          TalkActionId = {
            [1] = "81503:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_3"
        },
        [90240405] = {
          ContentFR = "Mais c’est le nom que mon père m’a donné. Peut-être espérait-il que je devienne un héros. Il ne m’a pas laissé grand-chose, mais tant que je porte ce nom, c’est comme si son épée laissait encore une trace dans ce monde.",
          DialogueId = 90240405,
          GUID = "E1E84A72",
          NextOptions = {
            [1] = 90240002,
            [2] = 90240003
          },
          SpeakNpcId = 81503,
          Subtitle = "But it's the name my old man gave me. Maybe he hoped I'd grow up to be some kind of hero. He didn't leave much behind, but carrying this name feels like his sword still leaves its mark on the world.",
          TalkActionId = {
            [1] = "81503:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Kezhou/vo_topic_04_4",
          bForbidSkipOptions = true
        },
        [90240601] = {
          ContentFR = "Je garde ton ancienne épée pour l’instant. Quand tu cesseras de faire la tête, je te la rendrai, mais seulement si tu me bats en duel. Si tu perds, elle sera à moi pour de bon.",
          DialogueId = 90240601,
          GUID = "E1E86A9A",
          SpeakNpcId = 81503,
          Subtitle = "I'm holding onto your old sword for now. When you stop moping around with that gloomy face, I'll give it back — but only if you beat me in a duel. Lose, and it's mine for good.",
          VoiceName = "voice/$Locale$/char/Kezhou/vo_companio_02"
        },
        [90240701] = {
          ContentFR = "Une épée peut être une amie, un jouet, voire un outil pour couper, faire levier ou raser. Mais elle ne doit jamais devenir ton maître. Ne laisse pas cette lame t’empêcher d’avancer.",
          DialogueId = 90240701,
          GUID = "E1E87B02",
          SpeakNpcId = 81503,
          Subtitle = "A sword can be a friend, a toy, or even a tool for all sorts of things — cutting, prying, shaving. But it should never be your master. Don't let that blade hold you back.",
          VoiceName = "voice/$Locale$/char/Kezhou/vo_companio_03"
        },
        [90250000] = {
          ContentFR = "Samaël, regarde ce soleil éclatant... Ce serait parfait pour manger quelque chose de frais, non ? On dit que la Capitale Élyséenne vend une douceur appelée glace. C’est de la nourriture de simples roturiers, mais sûrement bien meilleure que les plats de ces vieux grincheux... Je t’en achèterai en cachette !",
          DialogueId = 90250000,
          GUID = "E1EE70A0",
          SpeakNpcId = 81501,
          Subtitle = "Samael, it's a beautiful day outside! Isn't this the perfect weather to eat something cool? I've heard the Holy City has an amazing dessert called ice cream. It's a commoner's food, but I bet it's way tastier than anything those old farts are handing out. I'll secretly grab you some!",
          VoiceName = "voice/$Locale$/char/Baonu/vo_idle"
        },
        [90250001] = {
          ContentFR = "Bonjour ! Je fais prendre l’air à Samaël. On respire, on s’imprègne du soleil et de l’atmosphère d’ici... Tu veux lui dire bonjour ? Ça lui ferait très plaisir. Oui. Enfin... probablement !",
          DialogueId = 90250001,
          GUID = "E1EE70CA",
          LookAt = {
            [1] = "81501:n(0)",
            [2] = "0:n(81501)"
          },
          NextOptions = {
            [1] = 90250100,
            [2] = 90250200,
            [3] = 90250300,
            [4] = 90250400
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81501,
          Subtitle = "Hey! I'm taking Samael out for some fresh air — soaking up the sunlight, getting a feel for this place together. Wanna say hi? It'll be thrilled! ...Well, probably! Hehe~",
          VoiceName = "voice/$Locale$/char/Baonu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90250002] = {
          ContentFR = "Parlons d’autre chose.",
          DialogueId = 90250002,
          GUID = "E1EE70F4",
          NextDialogue = 90250001,
          Subtitle = "Let's talk about something else"
        },
        [90250003] = {
          ContentFR = "À bientôt.",
          DialogueId = 90250003,
          GUID = "E1EE711E",
          Subtitle = "Goodbye"
        },
        [90250100] = {
          ContentFR = "Ton arme a l’air redoutable...",
          DialogueId = 90250100,
          GUID = "E1EE8108",
          NextDialogue = 90250101,
          Subtitle = "Your weapon looks pretty powerful..."
        },
        [90250101] = {
          ContentFR = "Samaël n’est pas une simple arme. C’est mon meilleur ami !",
          DialogueId = 90250101,
          GUID = "E1EE8132",
          LookAt = {
            [1] = "81501:n(0)",
            [2] = "0:n(81501)"
          },
          NextDialogue = 90250102,
          SpeakNpcId = 81501,
          Subtitle = "Samael's not just a weapon — it's my best friend!",
          TalkActionId = {
            [1] = "81501:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_01_1"
        },
        [90250102] = {
          ContentFR = "Pourquoi considérer une épée comme un ami ?",
          DialogueId = 90250102,
          GUID = "E1EE815C",
          NextDialogue = 90250103,
          SpeakNpcId = 100001,
          Subtitle = "Why would you call a sword your friend?"
        },
        [90250103] = {
          ContentFR = "À l’Église Élyséenne, seuls ceux choisis par l’un des Sept Reliquaires sacrés peuvent devenir une Vertu. Ce jour-là, il y avait des dizaines de guerriers surpuissants... mais moi seule ai pu dégainer Samaël. Puisqu’il m’a choisie, je lui dois tout mon respect !",
          DialogueId = 90250103,
          GUID = "E1EE8186",
          NextDialogue = 90250104,
          SpeakNpcId = 81501,
          Subtitle = "In the Church, only those chosen by one of the Seven Relics can become one of the \"Seven Virtues.\" There were loads of strong warriors that day, but I was the only one who could pull Samael free. It chose me, so of course I've got to treat it right!",
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_01_2"
        },
        [90250104] = {
          ContentFR = "... Seulement voilà. Depuis ce jour, il ne répond plus à mes appels. H-Hé ! C’est un secret ! Tu n’as absolument pas le droit d’en parler !",
          DialogueId = 90250104,
          GUID = "E1EE81B0",
          NextDialogue = 90250105,
          SpeakNpcId = 81501,
          Subtitle = "...Only thing is, ever since then, it hasn't responded to me. Not once... W—Wait — that's top secret! You can't tell anyone, got it!?",
          TalkActionId = {
            [1] = "81501:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_01_3"
        },
        [90250105] = {
          ContentFR = "Tu lui étales de la crème tous les jours sur la lame. Évidemment qu’il t’ignore.",
          DialogueId = 90250105,
          GUID = "E1EE81DA",
          NextDialogue = 90250106,
          SpeakNpcId = 100001,
          Subtitle = "You smother its blade in ice cream every day. No wonder it's giving you the silent treatment."
        },
        [90250106] = {
          ContentFR = "Hein ?! Il n’aime pas la glace ?! Alors... de la purée ? De la vinaigrette, peut-être ?",
          DialogueId = 90250106,
          GUID = "E1EE8204",
          NextOptions = {
            [1] = 90250002,
            [2] = 90250003
          },
          SpeakNpcId = 81501,
          Subtitle = "Huh!? It doesn't like ice cream!? Then... what about mashed potatoes? Or salad dressing!?",
          TalkActionId = {
            [1] = "81501:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_01_4",
          bForbidSkipOptions = true
        }
      }
    end
  },
  {
    MinKey = 90250200,
    MaxKey = 120120031,
    Loader = function()
      return {
        [90250200] = {
          ContentFR = "Et les gens de l’Église Élyséenne, ils sont comment avec toi ?",
          DialogueId = 90250200,
          GUID = "E1EE9170",
          NextDialogue = 90250201,
          Subtitle = "So... what are the Church folks like?"
        },
        [90250201] = {
          ContentFR = "Tais-toi ! Ne me parle pas de ces vieux rabat-joie ! Aaah... Tu m’as gâché ma bonne humeur... Non. Calme-toi, Lisbell. Je ne dois pas me mettre en colère...",
          DialogueId = 90250201,
          GUID = "E1EE919A",
          LookAt = {
            [1] = "81501:n(0)",
            [2] = "0:n(81501)"
          },
          NextDialogue = 90250202,
          SpeakNpcId = 81501,
          Subtitle = "Ugh—! Shut up! I don't want to talk about those old stick-in-the-muds! Ughhh, you've ruined my day— ...No, no, I can't get angry. Stay calm, Lisbell...",
          TalkActionId = {
            [1] = "81501:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_02_1"
        },
        [90250202] = {
          ContentFR = "On dirait que tu leur en veux beaucoup...",
          DialogueId = 90250202,
          GUID = "E1EE91C4",
          NextDialogue = 90250203,
          SpeakNpcId = 100001,
          Subtitle = "Sounds like you've got some issues with them."
        },
        [90250203] = {
          ContentFR = "<I>Hum hum.</> Pas du tout ! Les prêtres sont adorables, vraiment. Se tromper dans un hymne ? Trente copies suffisent. Donner de la glace à Samaël ? Deux jours de méditation face au mur. Je les adore. Vraiment. Absolument.",
          DialogueId = 90250203,
          GUID = "E1EE91EE",
          NextOptions = {
            [1] = 90250002,
            [2] = 90250003
          },
          SpeakNpcId = 81501,
          Subtitle = "Ahem! Not at all! They are absolutely wonderful. So kind and understanding. When you mess up a hymn, you just have to copy it thirty times. And if they catch you feeding cream to Samael, it's only two days locked up for solitary reflection. Really, they're the best. Absolutely lovely...",
          TalkActionId = {
            [1] = "81501:Angry01_End"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90250300] = {
          ContentFR = "Que signifie réellement la Résilience ?",
          DialogueId = 90250300,
          GUID = "E1EEA1D8",
          NextDialogue = 90250301,
          Subtitle = "What does Patience mean, exactly?"
        },
        [90250301] = {
          ContentFR = "C’est évident, non ? Être résilient, c’est rester ferme, endurer... et ne jamais se mettre en colère !",
          DialogueId = 90250301,
          GUID = "E1EEA202",
          LookAt = {
            [1] = "81501:n(0)",
            [2] = "0:n(81501)"
          },
          NextDialogue = 90250302,
          SpeakNpcId = 81501,
          Subtitle = "Just what it says. Being patient means staying strong and stoic — putting up with anything and never, ever blowing up!",
          TalkActionId = {
            [1] = "81501:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_03_1"
        },
        [90250302] = {
          ContentFR = "Ça a l’air incroyablement difficile...",
          DialogueId = 90250302,
          GUID = "E1EEA22C",
          NextDialogue = 90250303,
          SpeakNpcId = 100001,
          Subtitle = "That sounds... really tough."
        },
        [90250303] = {
          ContentFR = "Tu m’étonnes... À cause de ce titre, on m’enseigne sans cesse à étouffer ma colère par la patience. Mais c’est comme retenir un bâillement à mi-chemin, ou lever son épée pour frapper... et découvrir que l’ennemi est en fait un allié. Ça rend encore plus fur—",
          DialogueId = 90250303,
          GUID = "E1EEA256",
          NextDialogue = 90250304,
          SpeakNpcId = 81501,
          Subtitle = "Right!? But because of this title, they're always telling me to \"swallow my anger with patience.\" But it's like... like being forced to stop mid-yawn or raising your sword for a perfect strike, only to be told, \"Hey! That's not an enemy, it's a friend!\" It just makes you even more—",
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_03_2"
        },
        [90250304] = {
          ContentFR = "<I>Gnh...</> Ils disent que la colère est un péché grave. Je ne dois pas me mettre en colère. Je ne dois pas...",
          DialogueId = 90250304,
          GUID = "E1EEA280",
          NextDialogue = 90250305,
          SpeakNpcId = 81501,
          Subtitle = "Argh, they say anger is a grave sin. I mustn't get angry. I mustn't...",
          TalkActionId = {
            [1] = "81501:Talk01_End"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_03_3"
        },
        [90250305] = {
          ContentFR = "Cela doit être éprouvant.",
          DialogueId = 90250305,
          GUID = "E1EEA2AA",
          NextDialogue = 90250306,
          SpeakNpcId = 100001,
          Subtitle = "That must be hard on you."
        },
        [90250306] = {
          ContentFR = "Hé hé. Après tout, je suis Seigneur Résilience !",
          DialogueId = 90250306,
          GUID = "E1EEA2D4",
          NextOptions = {
            [1] = 90250002,
            [2] = 90250003
          },
          SpeakNpcId = 81501,
          Subtitle = "Well... it comes with the job! I am Lord Patience, after all! Hehe!",
          TalkActionId = {
            [1] = "81501:Agree"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_03_4",
          bForbidSkipOptions = true
        },
        [90250400] = {
          ContentFR = "Que sont exactement les Sept Vertus ?",
          DialogueId = 90250400,
          GUID = "E1EEB240",
          NextDialogue = 90250401,
          Subtitle = "What exactly are the \"Seven Virtues?\""
        },
        [90250401] = {
          ContentFR = "Les Sept Vertus, ce sont les sept personnes les plus imposantes, nobles et puissantes d’Élysium ! Et, bien entendu, celles dont la vertu est la plus éclatante... Héhé.",
          DialogueId = 90250401,
          GUID = "E1EEB26A",
          LookAt = {
            [1] = "81501:n(0)",
            [2] = "0:n(81501)"
          },
          NextDialogue = 90250402,
          SpeakNpcId = 81501,
          Subtitle = "The \"Seven Virtues\" are the most noble, most powerful, and most drop-dead dazzling champions in all of Elysium! Naturally, they're also the most virtuous — it's in the name!",
          TalkActionId = {
            [1] = "81501:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_04_1"
        },
        [90250402] = {
          ContentFR = "Euh...",
          DialogueId = 90250402,
          GUID = "E1EEB294",
          NextDialogue = 90250403,
          SpeakNpcId = 100001,
          Subtitle = "Uh..."
        },
        [90250403] = {
          ContentFR = "C’est quoi, cette tête ?! Quelle insolence ! Oser douter de moi ! Je te condamne à recopier les Préceptes trente— non, cent fois !",
          DialogueId = 90250403,
          GUID = "E1EEB2BE",
          NextOptions = {
            [1] = 90250002,
            [2] = 90250003
          },
          SpeakNpcId = 81501,
          Subtitle = "What's with that look...? How dare you doubt me! I hereby sentence you to copy the Codex thirty — no, a hundred times!",
          TalkActionId = {
            [1] = "81501:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Baonu/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90250601] = {
          ContentFR = "« La Résilience est l’une des Sept Vertus... Celui qui la cultive peut voir ce que nul autre ne voit, accomplir ce que— ce que... »\nAaaah ! J’en peux plus ! Espèce de nabot, si tu continues à m’imiter, je te jure par les Neuf Dieux d’Élysium que je te tranche en rondelles avec Samaël ! Et je le ferai vraiment !",
          DialogueId = 90250601,
          GUID = "E1EED33A",
          SpeakNpcId = 81501,
          Subtitle = [[
"Patience is one of the Seven Virtues. Those gifted with patience can discover hidden secrets and accomplish extraordinary... feats..."
I can't take it anymore! Don't imitate me dwarf in the name of the Nine Gods I'll cut you in half with Samel if you do that one more time!]],
          VoiceName = "voice/$Locale$/char/Baonu/vo_companio_02"
        },
        [90250701] = {
          ContentFR = "De la crème ? Et alors ? C’est comme ça que les Élyséens entretiennent leurs armes. Une objection ?",
          DialogueId = 90250701,
          GUID = "E1EEE3A2",
          SpeakNpcId = 81501,
          Subtitle = "Cream? What's wrong? That's how we Elysians take care of our weapons. You got a problem with that?",
          VoiceName = "voice/$Locale$/char/Baonu/vo_companio_03"
        },
        [100365691] = {
          DialogueId = 100365691,
          DialoguePanelType = "None",
          Duration = 3,
          GUID = "100365691",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10036571.T_Story_Recall_10036571'",
          NextDialogue = 10036570
        },
        [100365862] = {
          Camera = "-369.931641,-193.570129,443.070312,-0.001404,-42.627155,6.081401,35.000008,371.172089,false,Manual,3.0",
          ContentFR = "Une fine entaille traverse le poignet du soldat, nette, trop régulière, manifestement infligée par une épée. Mais <H>sur cette scène, seuls la Légion et le \"monstre\" devraient avoir laissé leurs marques.</>",
          DialogueId = 100365862,
          FinalCamera = "-388.837891,-106.715332,443.070312,-0.001404,-46.226898,-0.518005,35.000008,371.172089,false,Manual,3.0",
          GUID = "100365862",
          NextOptions = {
            [1] = 100365863
          },
          Subtitle = "(A faint cut crosses the soldier's wrist — fine, clean, unmistakably made by a blade. But in this version of the story, only the legionaries and the \"monster\" should've left their marks.)",
          ToFinalCameraBlendTime = 8
        },
        [100365863] = {
          ContentFR = "<I>Effacer l’entaille</>",
          DialogueId = 100365863,
          GUID = "100365863",
          NextDialogue = 100365864,
          Subtitle = "(Erase the blade cut)"
        },
        [100365864] = {
          Camera = "237.636719,751.144104,145.707031,-0.001404,-4.425778,-101.517555,35.0,844.950317,false,Manual,3.0",
          ContentFR = "La coupure est si fine qu’un simple geste suffit à en brouiller les contours. Des perles écarlates roulent, <H>comme si jamais aucun Chasseur de Phoxène armé d’une épée n’avait foulé cet endroit.</>",
          DialogueId = 100365864,
          FinalCamera = "359.826172,861.536682,156.921875,-0.001403,-4.82574,-105.317894,35.0,844.950317,false,Manual,3.0",
          GUID = "100365864",
          NextDialogue = 100365865,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/02/stab\"},PlayAs2D{true}}",
          Subtitle = "(The cut is fine enough that a simple smear disrupts the shape. Crimson beads well up and roll down — as if no sword-wielding Phoxhunter had ever set foot here.)",
          ToFinalCameraBlendTime = 8
        },
        [100365865] = {
          Camera = "-197.347656,-337.183167,364.167969,-0.001403,-31.025061,92.480331,35.000008,844.950317,false,Manual,3.0",
          ContentFR = "Le corps est couvert de larges plaques noirâtres, brûlures électriques évidentes. Mais <H>sur cette scène, seuls la Légion et le \"monstre\" devraient avoir laissé leurs marques.</>",
          DialogueId = 100365865,
          FinalCamera = "-290.177734,-277.0578,492.726562,-0.001407,-42.224854,94.280289,35.000008,844.950317,false,Manual,3.0",
          GUID = "100365865",
          LookAt = {
            [1] = "100327:n(100352)"
          },
          NextOptions = {
            [1] = 100365866
          },
          Scripts = "SetLocation{ActorId{100327},TargetPoint{\"BP_NewTargetPoint_ch2fix62_2\"},Visibility{\"Show\"}}",
          Subtitle = "(The soldier's body is marred with scorched welts — telltale signs of electrical burns. But in this version of the story, only the legionaries and the \"monster\" should've left their marks.)",
          TalkActionId = {
            [1] = "100327:Angry01_Start"
          },
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "100327:p(110)"
          }
        },
        [100365866] = {
          ContentFR = "<I>Arracher le câble</>",
          DialogueId = 100365866,
          GUID = "100365866",
          NextDialogue = 100365867,
          Subtitle = "(Pull the cable)"
        },
        [100365867] = {
          Camera = "-1248.921875,692.722961,215.214844,-0.001404,-8.02483,-50.121822,35.0,549.465881,false,Manual,3.0",
          ContentFR = "La lampe sur pied éclate. Un câble rompu pend mollement, sectionné net. Des étincelles jaillissent dans une danse joyeuse, <H>comme si jamais aucun officier maniant la foudre n’avait mis les pieds ici.</> Dommage... c’était une si belle lampe.",
          DialogueId = 100365867,
          FinalCamera = "-1248.921875,692.722961,215.214844,-0.001403,-4.82477,-49.922085,35.0,549.465881,false,Manual,3.0",
          GUID = "100365867",
          NextDialogue = 100365868,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/02/stab\"},PlayAs2D{true}}",
          Subtitle = "(The floor lamp shatters. A loose cable swings down, severed clean through. Sparks rise in a cheerful little dance — as if no lightning-wielding officer had ever set foot here. A pity, though... it was such a lovely lamp.)",
          ToFinalCameraBlendTime = 8
        },
        [100365868] = {
          Camera = "-314.880859,882.889343,174.027344,-0.001404,0.975194,-93.919266,15.0,328.721466,false,Manual,3.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentFR = "Maintenant, le décor est en place : la XIIIᵉ Légion a traqué la créature jusqu’au Théâtre Galea. <H>L’avant-garde, bien qu’ayant évacué les civils, est tombée sous les griffes du \"monstre\".</> Le gros des troupes est ensuite arrivé, a terrassé la bête, et clos la Traque aux Charons. Une chute de rideau parfaite... comme si l’histoire avait toujours été écrite ainsi.",
          DialogueId = 100365868,
          FinalCamera = "-324.787109,1630.875977,511.484375,-0.001404,0.175338,-91.318481,15.000005,768.242798,false,Manual,3.0",
          GUID = "100365868",
          LookAt = {
            [1] = "100327:n(100310)"
          },
          Scripts = "SetLocation{ActorId{100327},TargetPoint{\"tuosi02_62\"},Visibility{\"Show\"}}",
          Subtitle = "(And now, the stage is set: the 13th Legion pursued the creature to the Galea Theatre. The advance team evacuated the civilians — but fell to the \"monster.\" The main force arrived soon after, struck it down, and brought the Charon Hunt to its proper close. A fitting curtain call... as if the tale had always been written this way.",
          TalkActionId = {
            [1] = "100327:Angry01_End"
          },
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "100327:p(-70)"
          }
        },
        [101002151] = {
          ContentFR = "<I>Suivre Camilla et Snow vers Givrelac</>",
          DialogueId = 101002151,
          GUID = "101002151",
          ImprPlusId = 1006,
          NextDialogue = 10100223,
          Subtitle = "(Follow Camilla and Snow to Icelake.)"
        },
        [101002152] = {
          ContentFR = "<I>– Je ne peux pas faire confiance à des inconnues.</>",
          DialogueId = 101002152,
          GUID = "101002152",
          ImprPlusId = 1008,
          NextDialogue = 10100216,
          Subtitle = "(I can't trust strangers.)"
        },
        [101004021] = {
          ContentFR = "<I>Tout va bien maintenant, n’aie plus peur.</>",
          DialogueId = 101004021,
          GUID = "101004021",
          ImprPlusId = 1009,
          NextDialogue = 10100403,
          Subtitle = "Don't be afraid, everything's all right now."
        },
        [101004022] = {
          ContentFR = "<I>Il me semble que quelqu’un avait promis de me protéger, non ?</>",
          DialogueId = 101004022,
          GUID = "101004022",
          ImprPlusId = 1010,
          NextDialogue = 10100404,
          Subtitle = "I remember someone just promised to protect me."
        },
        [101006061] = {
          ContentFR = "<I>D’une petite île du Sud.</>",
          DialogueId = 101006061,
          GUID = "101006061",
          ImprPlusId = 1007,
          NextDialogue = 10100607,
          Subtitle = "From a small island in the South."
        },
        [101006062] = {
          ContentFR = "<I>Je suis de la famille de Madame Camilla.</>",
          DialogueId = 101006062,
          GUID = "101006062.0",
          ImprPlusId = 1010,
          NextDialogue = 10100609,
          Subtitle = "I'm a relative of Ms Camilla."
        },
        [101006063] = {
          ContentFR = "<I>Garder le silence et tourner les yeux vers Camilla</>",
          DialogueId = 101006063,
          GUID = "101006063.0",
          ImprPlusId = 1008,
          NextDialogue = 101006110,
          Subtitle = "(Remain silent and look at Camilla.)"
        },
        [101006110] = {
          Camera = "31.592773,-132.096191,174.667969,0.00129,-11.999296,124.201492,40.60326,233.368286,false,Manual,1.2",
          CameraBlendCurve = "easeInOutQuad",
          DialogueId = 101006110,
          DialoguePanelType = "None",
          Duration = 3,
          FinalCamera = "20.211914,-139.831543,174.667969,0.001292,-11.999235,124.201599,40.60326,188.175873,false,Manual,1.2",
          GUID = "19492B55",
          LookAt = {
            [1] = "100001:n(200003)"
          },
          NextDialogue = 10100611,
          ToFinalCameraBlendTime = 3
        },
        [101006121] = {
          ContentFR = "<I>Faire une tête triste</>",
          DialogueId = 101006121,
          GUID = "101006121.0",
          NextDialogue = 10100613,
          Subtitle = "(Make a sad face.)"
        },
        [101006122] = {
          ContentFR = "<I>Forcer quelques larmes</>",
          DialogueId = 101006122,
          GUID = "101006122.0",
          NextDialogue = 10100613,
          Subtitle = "(Squeeze out a few tears.)"
        },
        [101008011] = {
          ContentFR = "<I>... J’ai perçu le danger.</>",
          DialogueId = 101008011,
          GUID = "101008011.0",
          NextDialogue = 10100802,
          Subtitle = "...I just felt a hint of danger there."
        },
        [101008012] = {
          ContentFR = "<I>Vous vous en êtes bien sortie, vous aussi.</>",
          DialogueId = 101008012,
          GUID = "101008012.0",
          NextDialogue = 10100802,
          Subtitle = "Right back at you."
        },
        [101008061] = {
          ContentFR = "<I>Ce n’était pas un hasard que vous m’ayez {性别:sauvé|sauvée}. C’est ça, \"l’accord\" dont tu parles ?</>",
          DialogueId = 101008061,
          GUID = "101008061",
          NextDialogue = 10100807,
          Subtitle = "Your saving me doesn't seem like a coincidence. Is this the \"deal\" you just mentioned?"
        },
        [101008062] = {
          DialogueId = 101008062,
          DialoguePanelType = "None",
          Duration = 0.1,
          FinalDialogueId = 10100824,
          GUID = "101008062",
          NextOptions = {
            [1] = 101008061,
            [2] = 101008151,
            [3] = 101008191
          }
        },
        [101008151] = {
          ContentFR = "<I>Je veux savoir comment retourner sur l’Île du Purgatoire.</>",
          DialogueId = 101008151,
          GUID = "101008151",
          NextDialogue = 10100816,
          Subtitle = "I want to know how to get back to Purgatorio Island."
        },
        [101008191] = {
          ContentFR = "<I>Je veux quand même retrouver Sibylle. Je ne plaisante pas.</>",
          DialogueId = 101008191,
          GUID = "101008191",
          NextDialogue = 10100820,
          Subtitle = "I still want to see Sibylle. I'm serious."
        },
        [101012131] = {
          ContentFR = "<I>Allons-nous-en, on trouvera bien un autre moyen.</>",
          DialogueId = 101012131,
          GUID = "101012131",
          ImprPlusId = 1007,
          Subtitle = "Let's go, there'll be other ways."
        },
        [101012132] = {
          ContentFR = "<I>Tu ne crains pas de couler ton affaire, à traiter les gens comme ça ?</>",
          DialogueId = 101012132,
          GUID = "101012132",
          ImprPlusId = 1006,
          Subtitle = "Aren't you afraid that you'd go out of business with that attitude?"
        },
        [101012133] = {
          ContentFR = "<I>En réalité, je viens du Bureau de la Sécurité. Tu vas le regretter.</>",
          DialogueId = 101012133,
          GUID = "101012133.0",
          ImprPlusId = 1010,
          Subtitle = "Actually, I'm here on behalf of the Security Bureau. You will pay for this."
        },
        [101016051] = {
          ContentFR = "<I>Je suis {nickname}.</>",
          DialogueId = 101016051,
          GUID = "101016051.0",
          NextDialogue = 10101606,
          Subtitle = "I'm ."
        },
        [101016101] = {
          ContentFR = "<I>Pardon...</>",
          DialogueId = 101016101,
          GUID = "101016101",
          ImprPlusId = 1007,
          NextDialogue = 10101612,
          Subtitle = "Excuse me..."
        },
        [101016102] = {
          ContentFR = "<I>Snow, c’est ton ventre qui a grogné ?</>",
          DialogueId = 101016102,
          GUID = "101016102.0",
          ImprPlusId = 1010,
          NextDialogue = 10101611,
          Subtitle = "Snow, was that you?"
        },
        [101024191] = {
          ContentFR = "<I>Ce n’est pas comme s’ils avaient le choix.</>",
          DialogueId = 101024191,
          GUID = "101024191",
          ImprPlusId = 1009,
          NextDialogue = 10102420,
          Subtitle = "It's not really up to them, I suppose."
        },
        [101024192] = {
          ContentFR = "<I>Snow a raison. Œil pour œil, dent pour dent.</>",
          DialogueId = 101024192,
          GUID = "101024192",
          ImprPlusId = 1007,
          NextDialogue = 10102420,
          Subtitle = "Snow has a point. An eye for an eye."
        },
        [101026091] = {
          ContentFR = "<I>J’ai déjà affronté des dangers bien plus grands.</>",
          DialogueId = 101026091,
          GUID = "101026091",
          ImprPlusId = 1008,
          NextDialogue = 10102610,
          Subtitle = "I've been faced with greater dangers."
        },
        [101026092] = {
          ContentFR = "<I>Plutôt que mourir de faim, je choisis le risque.</>",
          DialogueId = 101026092,
          GUID = "101026092",
          ImprPlusId = 1006,
          NextDialogue = 10102610,
          Subtitle = "Between starvation and danger, I choose the latter."
        },
        [101038121] = {
          ContentFR = "<I>?</>",
          DialogueId = 101038121,
          GUID = "101038121.0",
          NextDialogue = 10103813,
          Subtitle = "?"
        },
        [101040051] = {
          ContentFR = "<I>« Patate chaude » ?</>",
          DialogueId = 101040051,
          GUID = "101040051.0",
          NextDialogue = 10104006,
          Subtitle = "\"Hot potato\"?"
        },
        [101040061] = {
          ContentFR = "<I>Raconte-moi, je suis {性别:curieux|curieuse}.</>",
          DialogueId = 101040061,
          GUID = "101040061.0",
          NextDialogue = 10104007,
          Subtitle = "Tell me. I'm curious."
        },
        [101040141] = {
          ContentFR = "<I>Je vais essayer.</>",
          DialogueId = 101040141,
          GUID = "101040141.0",
          NextDialogue = 10104015,
          Subtitle = "I think I'll give it a try."
        },
        [101043011] = {
          ContentFR = "<I>Parlez-moi un peu de Givrelac.</>",
          DialogueId = 101043011,
          GUID = "101043011",
          NextDialogue = 10104302,
          Subtitle = "Please tell me more about Icelake."
        },
        [101043051] = {
          ContentFR = "<I>Parlez-moi des Chasseurs de Phoxène.</>",
          DialogueId = 101043051,
          GUID = "101043051",
          NextDialogue = 10104306,
          Subtitle = "Please tell me more about Phoxhunters."
        },
        [101043091] = {
          ContentFR = "<I>Parlez-moi de vous.</>",
          DialogueId = 101043091,
          GUID = "101043091",
          NextDialogue = 10104310,
          Subtitle = "Please tell me more about yourself."
        },
        [101043111] = {
          ContentFR = "<I>Parlons d’autre chose.</>",
          DialogueId = 101043111,
          ExStoryInfo = "Player",
          GUID = "101043111",
          SpeakNpcId = 100001,
          Subtitle = "Let's talk about something else."
        },
        [101043112] = {
          ContentFR = "<I>Merci, je n’ai rien d'autre à demander. </>",
          DialogueId = 101043112,
          GUID = "101043112",
          Subtitle = "Thanks, I'm done here."
        },
        [101044051] = {
          ContentFR = "<I>Merci, je te dois encore une fière chandelle.</>",
          DialogueId = 101044051,
          GUID = "101044051",
          ImprPlusId = 1009,
          NextDialogue = 10104406,
          Subtitle = "Thanks, I owe you another one."
        },
        [101044052] = {
          ContentFR = "<I>Puisque c'est un travail que vous proposez, c'est tout à fait normal.</>",
          DialogueId = 101044052,
          GUID = "101044052",
          ImprPlusId = 1006,
          NextDialogue = 10104406,
          Subtitle = "Since it's a job offered by you guys, it's only right."
        },
        [101046091] = {
          ContentFR = "<I>Alors, allons-y ensemble.</>",
          DialogueId = 101046091,
          GUID = "101046091",
          ImprPlusId = 1009,
          NextDialogue = 10104612,
          Subtitle = "Let's go then."
        },
        [101046092] = {
          ContentFR = "<I>N’écoute pas Snow, elle veut juste se rassurer en ayant quelqu’un avec elle.</>",
          DialogueId = 101046092,
          GUID = "101046092",
          ImprPlusId = 1008,
          NextDialogue = 10104610,
          Subtitle = "Don't listen to Snow, she just wants extra help."
        },
        [101054041] = {
          ContentFR = "<I>On a battu ce Souillé. Rends-le.</>",
          DialogueId = 101054041,
          GUID = "101054041",
          ImprPlusId = 1007,
          NextDialogue = 10105406,
          Subtitle = "We defeated that Filthoid. Give it back."
        },
        [101054042] = {
          ContentFR = "<I>Si y’a pas de priorité, alors ça veut dire qu’on peut juste te le reprendre par la force.</>",
          DialogueId = 101054042,
          GUID = "101054042",
          ImprPlusId = 1010,
          NextDialogue = 10105406,
          Subtitle = "If there's no such thing as dibs, that means we can just beat you up and take the Crystallo back."
        },
        [101054091] = {
          ContentFR = "<I>Pas question !</>",
          DialogueId = 101054091,
          GUID = "101054091.0",
          NextDialogue = 10105410,
          Subtitle = "No way!"
        },
        [101054092] = {
          ContentFR = "<I>Absolument pas !</>",
          DialogueId = 101054092,
          GUID = "101054092.0",
          NextDialogue = 10105410,
          Subtitle = "Absolutely no!"
        },
        [101054141] = {
          ContentFR = "<I>Très bien, marché conclu.</>",
          DialogueId = 101054141,
          GUID = "101054141.0",
          NextDialogue = 10105417,
          Subtitle = "Fine, let's make that deal."
        },
        [101054142] = {
          ContentFR = "<I>On va voir ça !</>",
          DialogueId = 101054142,
          GUID = "101054142.0",
          NextDialogue = 10105415,
          Subtitle = "Let's find out!"
        },
        [101054151] = {
          ContentFR = "<I>On arrête, marché conclu.</>",
          DialogueId = 101054151,
          GUID = "101054151.0",
          NextDialogue = 10105417,
          Subtitle = "Fine, let's make that deal."
        },
        [101054152] = {
          ContentFR = "<I>Quelle coïncidence ! Moi aussi !</>",
          DialogueId = 101054152,
          GUID = "101054152.0",
          NextDialogue = 10105416,
          Subtitle = "What a coincidence — so am I!"
        },
        [101054191] = {
          ContentFR = "<I>Il y a une prime de cinq mille pièces d’argent dessus.</>",
          DialogueId = 101054191,
          GUID = "101054191",
          NextDialogue = 10105420,
          Subtitle = "There's a bounty worth 5,000 silver coins on it."
        },
        [101054211] = {
          ContentFR = "<I>D’accord.</>",
          DialogueId = 101054211,
          GUID = "101054211",
          NextDialogue = 10105425,
          Subtitle = "Fine."
        },
        [101054212] = {
          ContentFR = "<I>Comment puis-je savoir que tu tiendras parole ?</>",
          DialogueId = 101054212,
          GUID = "101054212",
          NextDialogue = 10105422,
          Subtitle = "How do I know you'll keep your word?"
        },
        [101058131] = {
          ContentFR = "<I>Elle n’est pas votre fille.</>",
          DialogueId = 101058131,
          GUID = "101058131",
          NextDialogue = 10105814,
          Subtitle = "She is not your daughter, you know."
        },
        [101058132] = {
          ContentFR = "<I>Vous êtes toujours aussi aimable avec tout le monde ?</>",
          DialogueId = 101058132,
          GUID = "101058132",
          NextDialogue = 10105815,
          Subtitle = "You are quite a polite, friendly person."
        },
        [101063031] = {
          ContentFR = "<I>Tu voulais empêcher Snow d’entendre ?</>",
          DialogueId = 101063031,
          GUID = "101063031",
          NextDialogue = 10106304,
          Subtitle = "You didn't want Snow to hear?"
        },
        [101063032] = {
          ContentFR = "<I>Tu voulais empêcher Psyche d’entendre ?</>",
          DialogueId = 101063032,
          GUID = "101063032",
          NextDialogue = 10106305,
          Subtitle = "You didn't want Psyche to hear?"
        },
        [101063245] = {
          Content = "如果恩里克真的有什么阴谋，相比怀疑，我更担心恩里克会对她不利。她不会做坏事……我相信我的直觉。",
          DialogueId = 101063245,
          ExStoryInfo = "Player",
          GUID = "194CD3A2",
          NextDialogue = 10106325,
          SpeakNpcId = 100001,
          Subtitle = "If Henrik is up to something evil, I'm worried that he might harm her. She's too kind to do anything bad... I trust my instincts.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101063/194CD3A2"
        },
        [101068021] = {
          ContentFR = "<I>Le voilà.</>",
          DialogueId = 101068021,
          GUID = "101068021",
          NextDialogue = 10106803,
          Subtitle = "Here you are."
        },
        [101070021] = {
          ContentFR = "<I>Merci, Psyche. Mais j’ai réussi à récupérer l’Éclat stellaire auprès de l’Étranger.</>",
          DialogueId = 101070021,
          GUID = "101070021.0",
          NextDialogue = 10107003,
          Subtitle = "Thank you, Psyche. But I managed to get the Crystallo back from Outsider."
        },
        [101070031] = {
          ContentFR = "<I>Je lui ai raconté une histoire qui l’a fait pleurer.</>",
          DialogueId = 101070031,
          GUID = "101070031",
          ImprPlusId = 1009,
          NextDialogue = 10107004,
          Subtitle = "I told him a story that brought him to tears."
        },
        [101070032] = {
          ContentFR = "<I>Sur le chemin du retour, il s’est cassé la jambe. Il est chez lui, à hurler de douleur.</>",
          DialogueId = 101070032,
          GUID = "101070032",
          ImprPlusId = 1010,
          NextDialogue = 10107006,
          Subtitle = "He broke his leg on his way back and is now howling in pain at home."
        },
        [101070071] = {
          ContentFR = "<I>Les pensionnaires d’ici ont l’air un peu... sans énergie.</>",
          DialogueId = 101070071,
          GUID = "101070071.0",
          NextDialogue = 10107008,
          Subtitle = "The lodgers here all seem... a bit listless."
        },
        [101070131] = {
          ContentFR = "<I>Dis-moi, Monsieur Henrik est surtout chez lui à quel moment ?</>",
          DialogueId = 101070131,
          GUID = "101070131",
          NextDialogue = 10107014,
          Subtitle = "When is Mr Henrik usually at home?"
        },
        [101070171] = {
          ContentFR = "<I>Et toi, ça va ?</>",
          DialogueId = 101070171,
          GUID = "101070171",
          NextDialogue = 10107018,
          Subtitle = "Are you alright?"
        },
        [101070291] = {
          ContentFR = "<I>Merci, elle est vraiment jolie.</>",
          DialogueId = 101070291,
          GUID = "101070291.0",
          NextDialogue = 10107030,
          Subtitle = "Thanks, it's really lovely."
        },
        [101071031] = {
          ContentFR = "<I>N’est-ce pas encore plus intriguant ?</>",
          DialogueId = 101071031,
          GUID = "101071031",
          NextDialogue = 10107104,
          Subtitle = "Doesn't that just make it more intriguing?"
        },
        [101071032] = {
          ContentFR = "<I>Que fais-tu ici ?</>",
          DialogueId = 101071032,
          GUID = "101071032.0",
          NextDialogue = 10107106,
          Subtitle = "What are you doing here?"
        },
        [101071051] = {
          ContentFR = "<I>Que fais-tu ici ?</>",
          DialogueId = 101071051,
          GUID = "101071051.0",
          NextDialogue = 10107106,
          Subtitle = "What are you doing here?"
        },
        [101071061] = {
          ContentFR = "<I>Chaque jour ? C’est beaucoup de travail.</>",
          DialogueId = 101071061,
          GUID = "101071061.0",
          NextDialogue = 10107107,
          Subtitle = "Every day? Sounds like a lot of work."
        },
        [101071062] = {
          ContentFR = "<I>Cette porte est déjà propre, pas besoin d’en faire plus.</>",
          DialogueId = 101071062,
          GUID = "101071062.0",
          NextDialogue = 10107107,
          Subtitle = "This door's spotless, no need for further cleaning now."
        },
        [101071081] = {
          ContentFR = "<I>C’est logique, je devrais adopter une habitude moi aussi. Et Monsieur Henrik, a-t-il des habitudes ?</>",
          DialogueId = 101071081,
          GUID = "101071081",
          ImprPlusId = 1008,
          NextDialogue = 10107109,
          Subtitle = "That makes sense; I should adopt a habit too. Does Mr Henrik have any?"
        },
        [101071121] = {
          ContentFR = "<I>C’est déjà suffisant. Ce sont des habitudes très significatives.</>",
          DialogueId = 101071121,
          GUID = "101071121.0",
          NextDialogue = 10107113,
          Subtitle = "It's more than enough. Those are certainly meaningful habits."
        },
        [101073021] = {
          ContentFR = "<I>Tu as dit « Hunt » ?</>",
          DialogueId = 101073021,
          GUID = "101073021.0",
          NextDialogue = 10107303,
          Subtitle = "Did you just say \"Hunt\"?"
        },
        [101073041] = {
          ContentFR = "<I>C’est toi qui as parlé trop fort...</>",
          DialogueId = 101073041,
          GUID = "101073041.0",
          NextDialogue = 10107305,
          Subtitle = "I didn't mean to, you were loud..."
        },
        [101073051] = {
          ContentFR = "<I>Parlons de « Hunt ». Où est-il allé ?</>",
          DialogueId = 101073051,
          GUID = "101073051",
          NextDialogue = 10107306,
          Subtitle = "Let's talk about Hunt. Where has he gone?"
        },
        [101073071] = {
          ContentFR = "<I>{性别:Désolé|Désolée}, je m’en vais tout de suite.</>",
          DialogueId = 101073071,
          GUID = "101073071.0",
          NextDialogue = 10107308,
          Subtitle = "Sorry, I'll leave right now."
        },
        [101078021] = {
          ContentFR = "<I>Les résidents de la Maison d’Hypnos sont en réalité... des malades.</>",
          DialogueId = 101078021,
          GUID = "101078021.0",
          NextDialogue = 10107803,
          Subtitle = "The Hypnos' House is actually a sanatorium."
        },
        [101078071] = {
