          GUID = "120102101.0",
          NextDialogue = 12010211,
          Subtitle = "The world's greatest Demon King? Or a sleepyhead who won't get out of bed until nearly noon?"
        },
        [120102102] = {
          ContentFR = "<I>Le plus grand Roi Démon du monde... qui se cache toujours derrière moi quand ça se bat ?</>",
          DialogueId = 120102102,
          GUID = "120102102.0",
          NextDialogue = 12010211,
          Subtitle = "The world's greatest Demon King? Or a big scaredy-cat who always hides behind me when there's a fight?"
