        [120104121] = {
          ContentFR = "<I>Ils punissent les criminels... Les Bi’an ne sont donc pas de simples bêtes.</>",
          DialogueId = 120104121,
          GUID = "120104121.0",
          ImprPlusId = 1203,
          NextDialogue = 12010413,
          Subtitle = "They punish evildoers? That makes them seem less like ordinary beasts."
