        [120104122] = {
          ContentFR = "<I>Ils sont si puissants... on peut en ramener un à Givrelac ?</>",
          DialogueId = 120104122,
          GUID = "120104122.0",
          ImprPlusId = 1201,
          NextDialogue = 12010414,
          Subtitle = "They sound amazing... Can I take one back to Icelake and keep it?"
        },
        [120104291] = {
          ContentFR = "<I>« La parole fonde l’homme et établit la confiance. »</>",
          DialogueId = 120104291,
          GUID = "120104291.0",
          NextDialogue = 12010432,
          Subtitle = "A man is measured by the strength of his word"
        },
        [120104292] = {
          ContentFR = "<I>« Rompre un serment ou trahir une alliance — cela est proscrit. »</>",
          DialogueId = 120104292,
          GUID = "120104292.0",
          NextDialogue = 12010432,
          Subtitle = "To break faith or betray a vow — this must not be done"
        },
        [120104401] = {
          ContentFR = "<I>Ça m’étonnerait quand même...</>",
          DialogueId = 120104401,
          GUID = "120104401.0",
          ImprPlusId = 1202,
          NextDialogue = 12010441,
          Subtitle = "I highly doubt that."
        },
        [120104402] = {
          ContentFR = "<I>Je t’ai menti tout ce temps. En réalité, je suis Yang. Je ne suis pas morte — j’étais juste coincée dans l’Empire Hyperboréen.</>",
          DialogueId = 120104402,
          GUID = "120104402.0",
          ImprPlusId = 1205,
          NextDialogue = 12010441,
          Subtitle = "Huh. Guess it's time — yes, I am Yang. I never died — I just got stuck in the Hyperborean Empire."
