        [120351151] = {
          Content = "起床！",
          DialogueId = 120351151,
          GUID = "120351151.0"
        },
        [120351152] = {
          Content = "再睡一会儿~",
          DialogueId = 120351152,
          GUID = "120351152.0"
        },
        [200005261] = {
          ContentFR = "<I>– Un prix aussi bas... ça donne envie.</>",
          DialogueId = 200005261,
          GUID = "200005261",
          ImprPlusId = 1001,
          NextDialogue = 20000533,
          Subtitle = "(Cheap labour. Not bad.)"
        },
        [200005262] = {
          ContentFR = "<I>– Trop beau pour être vrai... Méfiance.</>",
          DialogueId = 200005262,
          GUID = "200005262.0",
          ImprPlusId = 1003,
          NextDialogue = 20000528,
          Subtitle = "(Labour never comes this cheap. I'd better be careful.)"
        },
        [200006051] = {
          ContentFR = "<I>Peux-tu m’en dire plus sur les Lunariens ?</>",
          DialogueId = 200006051,
          GUID = "200006051",
          NextDialogue = 20000606,
          Subtitle = "Could you tell me more about Lunos?"
        },
        [200006151] = {
          ContentFR = "<I>Oui, Votre Altesse !</>",
          DialogueId = 200006151,
          GUID = "200006151",
          ImprPlusId = 1004,
          NextDialogue = 20000619,
          Subtitle = "Yes, Your Highness!"
        },
        [200006152] = {
          ContentFR = "<I>Combien ça paie, au juste, un commandant de ta Légion ?</>",
          DialogueId = 200006152,
          GUID = "200006152",
          ImprPlusId = 1001,
          NextDialogue = 20000618,
          Subtitle = "How much will the leader of your legion get paid?"
        },
        [200008091] = {
          ContentFR = "<I>– Tu remarques qu’elle a l’air abattue, comme si quelque chose la tracassait.</>",
          DialogueId = 200008091,
          GUID = "200008091",
          ImprPlusId = 1004,
          NextDialogue = 20000810,
          Subtitle = "(She looks rather lethargic. Something seems to be on her mind.)"
        },
        [200008092] = {
          ContentFR = "<I>– Tu remarques les fleurs qu’elle observait, c’est sans doute à elles qu’elle soupirait.</>",
          DialogueId = 200008092,
          GUID = "200008092.0",
          ImprPlusId = 1003,
          NextDialogue = 20000811,
          Subtitle = "(You noticed the potted plant she was taking care of, and she was sighing at it.)"
        },
        [200008093] = {
          ContentFR = "<I>Le repos ne suffit pas toujours. Sortir prendre l’air pourrait te faire du bien.</>",
          DialogueId = 200008093,
          GUID = "200008093.0",
          ImprPlusId = 1005,
          NextDialogue = 20000812,
          Subtitle = "Resting might not do much. Why not try going out and doing something fun to lift your spirits?"
        },
        [200008161] = {
          ContentFR = "<I>Elle a l’air un peu fatiguée...</>",
          DialogueId = 200008161,
          GUID = "200008161.0",
          NextDialogue = 20000817,
          Subtitle = "The flowers seem a bit under the weather."
        },
        [200008162] = {
          ContentFR = "<I>Elle fleurit à merveille !</>",
          DialogueId = 200008162,
          GUID = "200008162.0",
          NextDialogue = 20000818,
          Subtitle = "They're thriving and blooming!"
        },
        [200008201] = {
          ContentFR = "<I>Observer la couleur</>",
          DialogueId = 200008201,
          GUID = "200008201.0",
          NextDialogue = 20000821,
          Subtitle = "(Describe the colour of the flowers)"
        },
        [200008202] = {
          ContentFR = "<I>Examiner la forme</>",
          DialogueId = 200008202,
          GUID = "200008202.0",
          NextDialogue = 20000823,
          Subtitle = "(Describe the shape of the flowers)"
        },
        [200008203] = {
          ContentFR = "<I>Regarder les pétales de près</>",
          DialogueId = 200008203,
          GUID = "200008203.0",
          NextDialogue = 20000827,
          Subtitle = "(Describe the petal details)"
        },
        [200008341] = {
          ContentFR = "<I>La réconforter — même les fleurs les plus fortes finissent par dépérir.</>",
          DialogueId = 200008341,
          GUID = "200008341",
          ImprPlusId = 1004,
          NextDialogue = 20000835,
          Subtitle = "(Comfort her — even the toughest flower can be vulnerable and will wilt one day.)"
        },
        [200008342] = {
          ContentFR = "<I>Lui demander si quelque chose a changé dans sa manière de s’en occuper.</>",
          DialogueId = 200008342,
          GUID = "200008342",
          ImprPlusId = 1003,
          NextDialogue = 20000836,
          Subtitle = "(Ask her to think of any changes or differences compared to the way the plant used to be nurtured.)"
        },
        [200008411] = {
          ContentFR = "<I>– Je suis {性别:intrigué|intriguée} par cette \"terre spéciale\".</>",
          DialogueId = 200008411,
          GUID = "200008411",
          ImprPlusId = 1001,
          NextDialogue = 20000842,
          Subtitle = "(You are interested in this special soil.)"
        },
        [200008412] = {
          ContentFR = "<I>– Je vais l’aider.</>",
          DialogueId = 200008412,
          GUID = "200008412",
          ImprPlusId = 1002,
          NextDialogue = 20000842,
          Subtitle = "(You decide to help Psyche.)"
        },
        [200009111] = {
          ContentFR = "<I>En effet... si elles avaient le choix, elles ne voudraient pas être cueillies.</>",
          DialogueId = 200009111,
          GUID = "200009111",
          ImprPlusId = 1004,
          NextDialogue = 20000913,
          Subtitle = "Indeed... If flowers had a choice, they probably wouldn't want to be snipped off."
        },
        [200009112] = {
          ContentFR = "<I>Peut-être que leur rôle est d’être admirées par les gens.</>",
          DialogueId = 200009112,
          GUID = "200009112",
          ImprPlusId = 1001,
          NextDialogue = 20000912,
          Subtitle = "But maybe that is the flowers' purpose, to have their beauty appreciated by others."
        },
        [200009151] = {
          ContentFR = "<I>Je ferai de mon mieux pour qu’elles vivent le plus longtemps possible.</>",
          DialogueId = 200009151,
          GUID = "200009151",
          ImprPlusId = 1002,
          NextDialogue = 20000916,
          Subtitle = "I'll do my best to make them survive for as long as I can."
        },
        [200009152] = {
          ContentFR = "<I>Je chérirai leur moment d’épanouissement.</>",
          DialogueId = 200009152,
          GUID = "200009152",
          ImprPlusId = 1001,
          NextDialogue = 20000917,
          Subtitle = "I will cherish the moment of their blossoming."
        },
        [200009153] = {
          ContentFR = "<I>Je les trouve aussi un peu tristes...</>",
          DialogueId = 200009153,
          GUID = "200009153",
          ImprPlusId = 1004,
          NextDialogue = 20000918,
          Subtitle = "I actually feel sorry for them as well..."
        },
        [200009221] = {
          ContentFR = "<I>Oui, elles sont vraiment impressionnantes.</>",
          DialogueId = 200009221,
          GUID = "200009221.0",
          NextDialogue = 20000923,
          Subtitle = "Indeed. They're amazing."
        },
        [200009222] = {
          ContentFR = "<I>Je préfère qu’elles ne soient pas coupées.</>",
          DialogueId = 200009222,
          GUID = "200009222.0",
          NextDialogue = 20000924,
          Subtitle = "Personally, I prefer to leave them on the plant rather than snipping them off."
        },
        [200009261] = {
          ContentFR = "<I>De rien. Si ça ne suffit pas, je peux en ramener plus.</>",
          DialogueId = 200009261,
          GUID = "200009261.0",
          NextDialogue = 20000929,
          Subtitle = "You're welcome. And if you ever need more, just let me know."
        },
        [200009262] = {
          ContentFR = "<I>Super, alors tu pourras m’apprendre à jardiner quand tu as le temps ?</>",
          DialogueId = 200009262,
          GUID = "200009262.0",
          NextDialogue = 20000927,
          Subtitle = "I could really use a teacher if you're available."
        },
        [200017011] = {
          ContentFR = "<I>Partons.</>",
          DialogueId = 200017011,
          GUID = "200017011",
          Subtitle = "Let's go."
        },
        [200017012] = {
          ContentFR = "<I>Je ne suis pas encore {性别:prêt|prête}.</>",
          DialogueId = 200017012,
          GUID = "200017012",
          SpeakNpcId = 200021,
          Subtitle = "Not ready yet."
        },
        [200023011] = {
          ContentFR = "<I>La réveiller</>",
          DialogueId = 200023011,
          GUID = "200023011",
          Subtitle = "Awaken her."
        },
        [200023012] = {
          ContentFR = "<I>Je ne suis pas encore {性别:prêt|prête}.</>",
          DialogueId = 200023012,
          GUID = "200023012",
          Subtitle = "I'm not ready."
        },
        [200048041] = {
          ContentFR = "<I>Ce n’est pas une si mauvaise nouvelle, non ? Dis-moi, tu préfères rôti ou braisé ?</>",
          DialogueId = 200048041,
          GUID = "200048041",
          NextDialogue = 20004805,
          Subtitle = "Oh wow, should we go with roast or braised? What's your pick?"
        },
        [200048042] = {
          ContentFR = "<I>Donc, la \"chose terrible\", c’est juste qu’on a vu... un cochon géant ?</>",
          DialogueId = 200048042,
          GUID = "200048042.0",
          NextDialogue = 20004806,
          Subtitle = "So... the \"big news\" is that someone saw a really big pig?"
        },
        [200049011] = {
          Content = "可以。",
          DialogueId = 200049011,
          GUID = "200049011.0"
        },
        [200049012] = {
          Content = "猪的事先放一放。",
          DialogueId = 200049012,
          GUID = "200049012.0"
        },
        [200054111] = {
          ContentFR = "<I>Un peu comme les Charons et les Solariens, d’apparence différente, mais tous des humains ?</>",
          DialogueId = 200054111,
          GUID = "200054111",
          ImprPlusId = 1003,
          NextDialogue = 20005412,
          Subtitle = "Kind of like how Charons and Solas look different but are both human?"
        },
        [200054112] = {
          ContentFR = "<I>Un peu comme un fusil et un arc, d’apparence différente, mais tous deux des armes à distance ?</>",
          DialogueId = 200054112,
          GUID = "200054112.0",
          ImprPlusId = 1001,
          NextDialogue = 20005413,
          Subtitle = "Kind of like how guns and bows look different but are both ranged weapons?"
        },
        [200054113] = {
          ContentFR = "<I>Un peu comme la neige et le brouillard, différents, mais composés tous deux d’eau.</>",
          DialogueId = 200054113,
          GUID = "200054113.0",
          ImprPlusId = 1005,
          NextDialogue = 20005414,
          Subtitle = "Kind of like how snow and mist look totally different but are both mainly made of water?"
        },
        [200054311] = {
          ContentFR = "<I>Bien sûr, tu peux compter sur moi.</>",
          DialogueId = 200054311,
          GUID = "200054311",
          NextDialogue = 20005432,
          Subtitle = "Sure, you can count on me."
        },
        [200054312] = {
          ContentFR = "<I>Attends... tu comprends vraiment ce qu’ils disent ?</>",
          DialogueId = 200054312,
          GUID = "200054312.0",
          NextDialogue = 20005433,
          Subtitle = "Wait, you can understand the Geniemon language?"
        },
        [200055011] = {
          ContentFR = "<I>Filbert est vraiment immense !</>",
          DialogueId = 200055011,
          GUID = "200055011.0",
          NextDialogue = 20005502,
          Subtitle = "Filbert's really big."
        },
        [200055012] = {
          ContentFR = "<I>Ta famille ne s’inquiète pas pour toi ?</>",
          DialogueId = 200055012,
          GUID = "200055012.0",
          NextDialogue = 20005504,
          Subtitle = "Don't your family worry about you, running around in the wild all the time?"
        },
        [200055013] = {
          ContentFR = "<I>D’accord.</>",
          DialogueId = 200055013,
          GUID = "200055013.0",
          Subtitle = "Alright."
        },
        [200056041] = {
          ContentFR = "<I>D’accord.</>",
          DialogueId = 200056041,
          GUID = "200056041",
          Subtitle = "Okay."
        },
        [200056042] = {
          ContentFR = "<I>Attendons un peu.</>",
          DialogueId = 200056042,
          GUID = "200056042",
          Subtitle = "Maybe later."
        },
