          }
        },
        [200065131] = {
          ContentFR = "<I>Et je suis {nickname}, capitaine des Vagabonds de la Nuit ! Vos méfaits s’arrêtent ici !</>",
          DialogueId = 200065131,
          GUID = "200065131",
          ImprPlusId = 1004,
          NextDialogue = 20006514,
          Subtitle = "And I am , captain of the Noctoyagers! Your crimes end here!"
        },
        [200065132] = {
          ContentFR = "<I>{性别:Et je suis Mario, un simple plombier passionné de champignons qui passe par là. Je n’ai aucune idée de qui ils sont|Et je suis une simple plombier passionnée de champignons qui passe par là. Je n’ai aucune idée de qui ils sont}.</>",
          DialogueId = 200065132,
          GUID = "200065132",
          ImprPlusId = 1005,
          NextDialogue = 20006516,
          Subtitle = "And I am just a mushroom-loving plumber passing by. Have no idea who they are."
        },
        [200065133] = {
          ContentFR = "<I>Libérez ces Géniemon !</>",
          DialogueId = 200065133,
          GUID = "200065133",
          ImprPlusId = 1002,
          NextDialogue = 20006518,
          Subtitle = "Release the Geniemons now!"
        },
        [200070081] = {
          ContentFR = "<I>Arrête tes bêtises, Snow, ne rends pas les choses plus difficiles pour Truffle.</>",
          DialogueId = 200070081,
          GUID = "200070081",
          NextDialogue = 20007009,
          Subtitle = "Stop it, Snow, don't make it harder for Truffle."
        },
        [200070161] = {
          ContentFR = "<I>Promis !</>",
          DialogueId = 200070161,
          GUID = "200070161",
          NextDialogue = 20007017,
          Subtitle = "Pinky swear!"
        },
        [200071011] = {
          ContentFR = "<I>À propos de Paniemon...</>",
          DialogueId = 200071011,
          GUID = "200071011",
          NextDialogue = 20007102,
          Subtitle = "What do you know about Paniemon?"
        },
        [200071012] = {
          ContentFR = "<I>Comment est la vie d’un chercheur en Géniemon ?</>",
          DialogueId = 200071012,
          GUID = "200071012",
          NextDialogue = 20007105,
          Subtitle = "How's life as a Geniemon scholar?"
        },
        [200071013] = {
          ContentFR = "<I>Ce n’est rien. À bientôt.</>",
          DialogueId = 200071013,
          GUID = "200071013",
          Subtitle = "Nothing. Goodbye."
        },
        [510001041] = {
          ContentFR = "<I>Aaah ! Je vais boire ! Merci !</>",
          DialogueId = 510001041,
          GUID = "510001041.0",
          ImprPlusId = 1004,
          NextDialogue = 51000105,
          Subtitle = "Ahhh! I'll drink it myself! Thank you!"
        },
        [510001042] = {
          ContentFR = "<I>Tu esquives habilement, cette générosité soudaine te paraît suspecte.</>",
          DialogueId = 510001042,
          GUID = "510001042.0",
          ImprPlusId = 1001,
          NextDialogue = 51000107,
          Subtitle = "(Skillfully sidestep — You're wary of over-the-top kindness from strangers.)"
        },
        [510001101] = {
          ContentFR = "<I>La dame dont vous parlez... elle est malade ?</>",
          DialogueId = 510001101,
          GUID = "510001101",
          NextDialogue = 51000111,
          Subtitle = "The lady you mentioned — is she sick?"
        },
        [510003021] = {
          ContentFR = "<I>Tu remarques que ses vêtements, bien que usés, sont de facture luxueuse.</>",
          DialogueId = 510003021,
          GUID = "510003021.0",
          ImprPlusId = 1001,
          NextDialogue = 51000303,
          Subtitle = "(The fabric of her outfit appears quite luxurious.)"
        },
        [510003022] = {
          ContentFR = "<I>Elle semble chercher quelqu’un.</>",
          DialogueId = 510003022,
          GUID = "510003022.0",
          ImprPlusId = 1003,
          NextDialogue = 51000304,
          Subtitle = "(She seems to be looking for someone.)"
        },
        [510003023] = {
          ContentFR = "<I>Elle est noyée dans le chagrin.</>",
          DialogueId = 510003023,
          GUID = "510003023.0",
          ImprPlusId = 1004,
          NextDialogue = 51000305,
          Subtitle = "(She appears mournful.)"
        },
        [510003051] = {
          ContentFR = "<I>Peut-être pourrais-je lui venir en aide...</>",
          DialogueId = 510003051,
          GUID = "510003051.0",
          NextDialogue = 510003052,
          Subtitle = "(Perhaps I can offer some help.)"
        },
        [510003052] = {
          ContentFR = "<I>Peut-être pourrais-je lui venir en aide...</>",
