        [510003111] = {
          ContentFR = "<I>Non, cela ne me dit rien...</>",
          DialogueId = 510003111,
          GUID = "510003111.0",
          NextDialogue = 51000312,
          Subtitle = "Not really, sorry."
        },
        [510004031] = {
          ContentFR = "<I>Euh... {性别:Je suis un homme|Je ne suis pas votre fille}.</>",
          DialogueId = 510004031,
          GUID = "510004031.0",
          ImprPlusId = 1001,
          NextDialogue = 51000490,
          Subtitle = "Umm... {性别:I am a man.|I am not your daughter.}"
        },
        [510004032] = {
          ContentFR = "<I>Calmez-vous. Vous cherchez quelqu’un ? Je peux vous aider à la trouver.</>",
          DialogueId = 510004032,
          GUID = "510004032.0",
          ImprPlusId = 1004,
          NextDialogue = 51000490,
          Subtitle = "Please calm down. Are you looking for someone? I'll keep an eye out for you."
        },
        [510004033] = {
          ContentFR = "<I>Maman !</>",
          DialogueId = 510004033,
          GUID = "510004033.0",
          ImprPlusId = 1005,
          NextDialogue = 51000404,
          Subtitle = "Mum!!!"
        },
        [510004071] = {
          ContentFR = "<I>Accepter</>",
          DialogueId = 510004071,
          GUID = "510004071.0",
          NextDialogue = 51000408,
          Subtitle = "(Accept)"
        },
        [510004921] = {
          ContentFR = "<I>Rappelez-vous bien des caractéristiques de votre fille et des circonstances de sa disparition, afin que je puisse voir comment vous aider.</>",
          DialogueId = 510004921,
          FailDialogue = 51000405,
          GUID = "510004921.0",
          ImprCheckId = 1007,
          NextDialogue = 51000406,
          Subtitle = "Please think carefully about your daughter's features and how she disappeared, so I can see what I can do."
        },
        [510005011] = {
          ContentFR = "<I>Elsa, j’ai des nouvelles d’Annie...</>",
          DialogueId = 510005011,
          GUID = "510005011.0",
          NextDialogue = 51000502,
          Subtitle = "Elsa, I have news about Annie..."
        },
        [510005021] = {
          ContentFR = "Je suis {性别:navré|navrée}... Annie n’est plus de ce monde. Dans ses derniers instants, elle a sauvé une autre jeune fille. Sa bonté mérite d’être honorée et jamais oubliée.",
          DialogueId = 510005021,
          GUID = "510005021.0",
          NextDialogue = 51000503,
          Subtitle = "I'm so sorry, but Annie has passed away... my condolences. In her final moments, she helped another girl survive, and her kindness will always be remembered."
        },
        [510006011] = {
          ContentFR = "<I>Elsa, j’ai retrouvé votre fille.</>",
          DialogueId = 510006011,
          GUID = "510006011.0",
          NextDialogue = 51000602,
          Subtitle = "Elsa, I've found your daughter."
        },
        [510007011] = {
          ContentFR = "<I>Tu traînes ici depuis longtemps ? Je peux t’aider en quoi que ce soit ?</>",
          DialogueId = 510007011,
          GUID = "510007011.0",
          NextDialogue = 51000702,
          Subtitle = "Have you been wandering around here all this time? Is there anything I can help you with?"
        },
        [510007031] = {
          ContentFR = "<I>Je comprends ta confusion, perdre son identité est terrible.</>",
          DialogueId = 510007031,
          GUID = "510007031.0",
          ImprPlusId = 1004,
          NextDialogue = 51000705,
          Subtitle = "I understand. Losing a sense of belonging is awful."
        },
        [510007032] = {
          ContentFR = "<I>Rester dehors n’est pas sûr. Il vaut mieux découvrir ta véritable identité rapidement.</>",
          DialogueId = 510007032,
          GUID = "510007032.0",
          ImprPlusId = 1002,
          NextDialogue = 51000705,
          Subtitle = "Staying out here isn't safe. It's best to figure out your true identity as soon as possible."
        },
        [510007033] = {
          ContentFR = "<I>Ce que l’on voit n’est pas toujours la vérité. Il faut enquêter avant de tirer des conclusions.</>",
          DialogueId = 510007033,
          GUID = "510007033.0",
          ImprPlusId = 1003,
          NextDialogue = 51000705,
          Subtitle = "Seeing is not always believing. You've got to investigate everything thoroughly before jumping to conclusions."
        },
        [510007051] = {
          ContentFR = "<I>Accepter</>",
          DialogueId = 510007051,
          GUID = "510007051.0",
          NextDialogue = 51000706,
          Subtitle = "(Accept)"
        },
        [510008121] = {
          ContentFR = "<I>Ne pas montrer le journal</>",
          DialogueId = 510008121,
          GUID = "510008121.0",
          NextDialogue = 51000813,
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "(Do not show Alice's diary)"
        },
        [510008141] = {
          ContentFR = "<I>C’est elle qui m’a demandé de te chercher. Je vais te conduire à elle.</>",
          DialogueId = 510008141,
          GUID = "510008141.0",
          NextDialogue = 51000814,
          Subtitle = "Exactly. Your mother asked me to find you. I will take you to her."
        },
        [510008921] = {
          ContentFR = "<I>Montrer le journal d’Alice</>",
          DialogueId = 510008921,
          GUID = "510008921.0",
          NextDialogue = 51000803,
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = " (Show Alice's diary)"
        },
        [510009031] = {
          ContentFR = "<I>Je ne vois ici que des vieilleries. À vue de nez, ça ne vaut pas plus que quelques cailloux.</>",
          DialogueId = 510009031,
          GUID = "510009031.0",
          ImprPlusId = 1001,
          NextDialogue = 51000904,
          Subtitle = "I only see some junk here. According to my evaluation, they're not worth more than a few stones."
        },
        [510009032] = {
          ContentFR = "<I>Piller sans demander n’est pas exactement une vertu.</>",
          DialogueId = 510009032,
          GUID = "510009032.0",
          ImprPlusId = 1002,
          NextDialogue = 51000905,
          Subtitle = "It's better not to take things without asking."
        },
        [510009033] = {
          ContentFR = "<I>Tu as trouvé ça où ? Emmène-moi avec toi !</>",
          DialogueId = 510009033,
          GUID = "510009033.0",
          ImprPlusId = 1005,
          NextDialogue = 51000906,
          Subtitle = "Where did you swipe these from? Teach me that!"
        },
        [510009071] = {
          ContentFR = "<I>Dommage... rien de ce dont j’ai besoin.</>",
          DialogueId = 510009071,
          GUID = "510009071.0",
          NextDialogue = 51000907,
          Subtitle = "Sadly, there's nothing I need here."
        },
        [510009072] = {
          ContentFR = "Martin te dévisage longuement, l’air songeur.",
          DialogueId = 510009072,
          GUID = "510009072.0",
          ImprCheckId = 1004,
          NextDialogue = 51000909,
          Subtitle = "(He scrutinises you closely, revealing a thoughtful expression)"
        },
        [510009101] = {
          ContentFR = "<I>On dit que quelqu’un fournit du combustible et du tissu bon marché. Grâce à ça, beaucoup de pauvres survivent à l’hiver.</>",
          DialogueId = 510009101,
          GUID = "510009101.0",
          ImprPlusId = 1002,
          Subtitle = "I heard someone can provide some low-priced fuel and cloth to help many poor people get through the winter."
        },
        [510009102] = {
          ContentFR = "<I>Tu vends des informations. Pourtant, tu n’as pas l’air d’un détective... Quelle est donc ta source ?</>",
          DialogueId = 510009102,
          GUID = "510009102.0",
          ImprPlusId = 1003,
          Subtitle = "You sell information, but you don't look like a private detective. Do you have a special source for receiving intelligence?"
        },
        [510009103] = {
          ContentFR = "<I>Voilà trois fois que tu répètes « Martin ». Mais qui es-tu, au juste ?</>",
          DialogueId = 510009103,
          GUID = "510009103.0",
          ImprPlusId = 1005,
          Subtitle = "I've already heard you say Martin three times. Who exactly are you?"
        },
        [510009121] = {
          ContentFR = "<I>C’est vraiment aussi incroyable que ça ?</>",
          DialogueId = 510009121,
          GUID = "510009121",
          Subtitle = "Is it really that magical?"
        },
        [510009161] = {
          ContentFR = "<I>Accepter</>",
          DialogueId = 510009161,
          GUID = "510009161.0",
          Subtitle = "(Accept) "
        },
        [510010071] = {
          ContentFR = "<I>Tu as perdu quelque chose. Cet objet prouve que tu n’es qu’une riche des taudis, comme lui.</>",
          DialogueId = 510010071,
          GUID = "510010071.0",
          ImprCheckId = 1005,
          NextDialogue = 51001008,
          Subtitle = "You've lost something. That thing proves that you are a shack-dwelling tycoon just like him."
        },
        [510010072] = {
          ContentFR = "<I>Tu as perdu quelque chose. Normalement, les billets périmés doivent être détruits pour éviter les contrefaçons, et les garder est clairement interdit.</>",
          DialogueId = 510010072,
          GUID = "510010072.0",
          ImprCheckId = 1006,
          NextDialogue = 51001008,
          Subtitle = "You've lost something. Normally, expired tickets should be destroyed to prevent counterfeiting, and keeping them is obviously a violation."
        },
        [510010101] = {
          ContentFR = "<I>On raconte que les étoiles peuvent réaliser les vœux. Tu as plié des centaines d’étoiles avec ces billets... quel vœu voulais-tu exaucer ?</>",
          DialogueId = 510010101,
          GUID = "510010101.0",
          Subtitle = "Legend has it that stars have the power to fulfil wishes. You folded hundreds of stars from tickets, so what's your wish?"
        },
        [510010181] = {
          ContentFR = "<I>Je comprends ton amertume et ta peine. La vie réserve des déceptions, mais ce qui semble infranchissable aujourd’hui pourrait devenir un chemin plus tard.</>",
          DialogueId = 510010181,
          GUID = "510010181.0",
          ImprPlusId = 1004,
          NextDialogue = 51001019,
          Subtitle = "I understand your frustration and sorrow. Life always has disappointment, but what's insurmountable now might one day become a clear path."
        },
        [510010182] = {
          ContentFR = "<I>De toute façon, le monsieur tout à l’heure n’aurait pas dû subir ton humiliation. Je ne peux approuver que tu décharges ta colère sur quelqu’un d’autre.</>",
          DialogueId = 510010182,
          GUID = "510010182.0",
          ImprPlusId = 1002,
          NextDialogue = 51001020,
          Subtitle = "Regardless, the gentleman earlier should not have been humiliated by you, and I disagree with your act of venting your anger on others."
        },
        [510010183] = {
          ContentFR = "<I>Peu importe ce que tu penses, si tu ne veux pas de problèmes, récupère cet objet et garde-le correctement, ou détruis-le. C’est ton affaire.</>",
          DialogueId = 510010183,
          GUID = "510010183.0",
          ImprPlusId = 1001,
          NextDialogue = 51001021,
          Subtitle = "Whatever you think, if you don't want any trouble, you should either take this thing back and store it properly or destroy it. That's something you should take care of."
        },
        [510010184] = {
          ContentFR = "<I>Pourquoi ne pas t’asseoir sur le toit du train pour un petit tour, histoire de te défouler ?</>",
          DialogueId = 510010184,
          GUID = "510010184.0",
          ImprPlusId = 1005,
          NextDialogue = 51001022,
          Subtitle = "Why don't you sit up on the roof of the car for a round trip for fun?"
        },
        [510012011] = {
          ContentFR = "<I>Ces oiseaux-là, ce sont les tiens ?</>",
          DialogueId = 510012011,
          GUID = "510012011.0",
          ImprPlusId = 1003,
          NextDialogue = 51001202,
          Subtitle = "Are these golden plume birds yours?"
        },
        [510012012] = {
          ContentFR = "<I>Dommage qu’ils volent si haut... Sinon, on aurait pu s’en faire un festin.</>",
          DialogueId = 510012012,
          GUID = "510012012.0",
          ImprPlusId = 1005,
          NextDialogue = 51001203,
          Subtitle = "So, these birds are yours? I was hoping to have some fresh poultry for dinner."
        },
        [510012041] = {
          ContentFR = "<I>Se rappeler avoir lu à propos des oiseaux à plumes d’or — leur comportement, et pourquoi ils sont utilisés comme outils de détection.</>",
          DialogueId = 510012041,
          GUID = "510012041.0",
          ImprPlusId = 1003,
          NextDialogue = 51001205,
          Subtitle = "(Recalling what you've read about golden plume birds — their behaviour and their utility as detection tools.)"
        },
        [510012042] = {
          ContentFR = "<I>Approuver et déplorer comme lui que l’on ait tourné le dos aux traditions.</>",
          DialogueId = 510012042,
          GUID = "510012042.0",
          ImprPlusId = 1004,
          NextDialogue = 51001206,
          Subtitle = "(Agree with him and lament the disregard for tradition.)"
        },
        [510012043] = {
          ContentFR = "<I>Saluer les progrès technologiques qui ont permis à la société de gagner en efficacité.</>",
          DialogueId = 510012043,
          GUID = "510012043.0",
          ImprPlusId = 1001,
          NextDialogue = 51001207,
          Subtitle = "(Commend the progress in technology for enhancing the efficiency of human society.)"
        },
        [510013011] = {
          ContentFR = "<I>Tu peux pas insulter une dame respectée comme ça.</>",
          DialogueId = 510013011,
          GUID = "510013011.0",
          ImprPlusId = 1002,
          NextDialogue = 51001302,
          Subtitle = "You can't insult a respected lady like that."
        },
        [510013012] = {
          ContentFR = "<I>Donner un coup de poing</>",
          DialogueId = 510013012,
          GUID = "510013012.0",
          ImprPlusId = 1005,
          NextDialogue = 51001303,
          Subtitle = "(Sucker-punch him right in the face)"
        },
        [510013013] = {
          ContentFR = "Tu lui fais un compliment et elle te marche dessus. Elle ose dire que ma gnôle ne vaut rien ?! Je finirai par lui faire ravaler ses paroles, tôt ou tard !",
          DialogueId = 510013013,
          GUID = "510013013",
          NextOptions = {
            [1] = 510013011,
            [2] = 510013012
          },
          SpeakNpcId = 700014,
          Subtitle = "Throw her a compliment and she's walking all over me. Thinks she's too good for my booze? I'll make her regret it someday!",
          bForbidSkipOptions = true
        },
        [510013041] = {
          ContentFR = "<I>Je préfère considérer Camilla comme une alliée forte et fiable. Elle nous a aidés à de nombreuses reprises. Pas seulement nous, d’ailleurs : au moins la moitié de Givrelac lui doit quelque chose.</>",
          DialogueId = 510013041,
          FailDialogue = 51001305,
          GUID = "510013041.0",
          ImprCheckId = 1008,
          NextDialogue = 51001306,
          Subtitle = "No, Ms Camilla is a trustworthy friend and she's helped me out before."
        },
        [510013042] = {
          ContentFR = "<I>Ce n’est pas une raison pour déblatérer ici. Je crois en l’intégrité de Camilla, et ce n’est pas avec tes accusations ridicules que tu la saliras.</>",
          DialogueId = 510013042,
          FailDialogue = 51001305,
          GUID = "510013042.0",
          ImprCheckId = 1009,
          NextDialogue = 51001306,
          Subtitle = "Save your breath. Ms Camilla's integrity is not up for debate. I trust my own judgment of her."
        },
        [510013043] = {
          ContentFR = "<I>J’ai vu de mes yeux le discernement de Camilla : qu’il s’agisse des gens ou des boissons, rien ne lui échappe. Celui qui ne reconnaît rien, ici, c’est toi.</>",
          DialogueId = 510013043,
          FailDialogue = 51001305,
          GUID = "510013043.0",
          ImprCheckId = 1010,
          NextDialogue = 51001306,
          Subtitle = "Let me guess — she turned down your swill, and now you're bitter."
        },
        [510013061] = {
          ContentFR = "<I>Hum... kof...</> J’entends à ton accent que tu n’es pas du coin. Laisse-moi deviner, depuis que tu es arrivé à Givrelac, tu n’as jamais mis les pieds ailleurs qu’au bar de Camilla ?",
          DialogueId = 510013061,
          GUID = "510013061.0",
          SpeakNpcId = 700014,
          Subtitle = "Ahem... you ain't from around here, huh? Let me guess — you haven't been to any taverns other than Camilla's since hitting town, right?"
        },
        [510013062] = {
          ContentFR = "<I>Et alors ?</>",
          DialogueId = 510013062,
          GUID = "510013062",
          Subtitle = "So what?"
        },
        [510013091] = {
          ContentFR = "<I>D’accord, je prends une pinte.</>",
          DialogueId = 510013091,
          GUID = "510013091.0",
          NextDialogue = 51001310,
          Subtitle = "Alright, I'll take a can."
        },
        [510013092] = {
          ContentFR = "<I>On en a pour son argent.</>",
          DialogueId = 510013092,
          GUID = "510013092.0",
          NextDialogue = 51001313,
          Subtitle = "You get what you pay for. I'll pass."
        },
        [510013231] = {
          ContentFR = "<I>La concurrence, passe encore. Mais si ton faux alcool rend les gens malades ?</>",
          DialogueId = 510013231,
          GUID = "510013231.0",
          ImprPlusId = 1002,
          NextDialogue = 51001324,
          Subtitle = "Competing for business is one thing, but what if your fake booze causes actual harm to people?"
        },
        [510013232] = {
          ContentFR = "<I>Ouais ! Faut pas avoir peur d’elle. Mon pote, bois un tonneau et montre-nous !</>",
          DialogueId = 510013232,
          GUID = "510013232.0",
          ImprPlusId = 1005,
          NextDialogue = 51001326,
          Subtitle = "Yeah! Don't let her words scare you, buddy! Why not chug a barrel to prove how good your stuff is?"
        },
        [510013281] = {
          ContentFR = "<I>Sa camelote fait vraiment des ravages...</>",
          DialogueId = 510013281,
          GUID = "510013281.0",
          NextDialogue = 51001329,
          Subtitle = "He's not wrong — his stuff knocks people out..."
        },
        [510014021] = {
          ContentFR = "<I>Les enfants sont des poètes nés, capables de voir l’essence même de la vie.</>",
          DialogueId = 510014021,
          GUID = "510014021.0",
          ImprPlusId = 1004,
          NextDialogue = 51001403,
          Subtitle = "Children are natural poets seeing through life's essence, aren't they?"
        },
        [510014022] = {
          ContentFR = "<I>Vous semblez très fière d’eux.</>",
          DialogueId = 510014022,
          GUID = "510014022.0",
          ImprPlusId = 1003,
          NextDialogue = 51001403,
          Subtitle = "You seem to be very proud of them."
        },
        [510014023] = {
          ContentFR = "<I>Eh bien, on dirait que j’étais déjà à la traîne dès la ligne de départ.</>",
          DialogueId = 510014023,
          GUID = "510014023.0",
          ImprPlusId = 1005,
          NextDialogue = 51001403,
          Subtitle = "Darn it, it seems I was behind right from the start."
        },
        [510014061] = {
          ContentFR = "<I>Pas du tout. Vous leur enseignez la plus grande des choses : la pureté et le rêve.</>",
          DialogueId = 510014061,
          FailDialogue = 51001407,
          GUID = "510014061.0",
          ImprCheckId = 1011,
          NextDialogue = 51001409,
          Subtitle = "Not at all. You've preserved the children's precious innocence and sense of wonder."
        },
        [510014901] = {
          ContentFR = "<I>On dirait que ces enfants vous ont beaucoup appris, vous aussi.</>",
          DialogueId = 510014901,
          GUID = "510014901.0",
          ImprPlusId = 1003,
          NextDialogue = 51001412,
          Subtitle = "It seems you've gained a lot from your time with the children."
        },
        [510014902] = {
          ContentFR = "<I>Faire autant de sacrifices pour eux... en valait-il vraiment la peine ?</>",
          DialogueId = 510014902,
          GUID = "510014902.0",
          ImprPlusId = 1001,
          NextDialogue = 51001412,
          Subtitle = "Is it really worth it?"
        },
        [510015021] = {
          ContentFR = "<I>Faire tremper dans un peu de détergent, puis frotter ?</>",
          DialogueId = 510015021,
          GUID = "510015021.0",
          ImprPlusId = 1003,
          NextDialogue = 51001503,
          Subtitle = "Maybe try soaking it in detergent first?"
        },
        [510015022] = {
          ContentFR = "<I>Tu me payes, et je le fais pour toi.</>",
          DialogueId = 510015022,
          GUID = "510015022.0",
          ImprPlusId = 1001,
          NextDialogue = 51001503,
          Subtitle = "You got cash? I can clean it for you."
        },
        [510015023] = {
          ContentFR = "<I>Se faire frapper forge le caractère, non ?</>",
          DialogueId = 510015023,
          GUID = "510015023.0",
          ImprPlusId = 1005,
          NextDialogue = 51001503,
          Subtitle = "Getting beaten up is good for character building, isn't it?"
        },
        [510015071] = {
          ContentFR = "<I>Tu ne trouves pas ça un peu froid, comme propos ?</>",
          DialogueId = 510015071,
          GUID = "510015071.0",
          ImprCheckId = 1012,
          NextDialogue = 51001509,
          Subtitle = "What a heartless thing to say!"
        },
        [510016021] = {
          ContentFR = "<I>– Il a l’air colérique... Peut-être que lui toucher les cornes le calmerait.</>",
          DialogueId = 510016021,
          GUID = "510016021.0",
          ImprPlusId = 1005,
          NextDialogue = 51001603,
          Subtitle = "(He seems temperamental. Maybe touching his horns will calm him down.)"
        },
        [510016022] = {
          ContentFR = "<I>Charons et Solariens sont égaux. Tu ne devrais pas avoir de préjugés.</>",
          DialogueId = 510016022,
          GUID = "510016022.0",
          ImprPlusId = 1002,
          NextDialogue = 51001605,
          Subtitle = "Charons and Solas are equals. Prejudice is not cool."
        },
        [510016023] = {
          ContentFR = "<I>Mais... tu es un Charon, toi aussi... non ?</>",
          DialogueId = 510016023,
          GUID = "510016023.0",
          ImprPlusId = 1003,
          NextDialogue = 51001607,
          Subtitle = "But you're a Charon too... aren't you?"
        },
        [510016121] = {
          ContentFR = "<I>Puis-je admirer votre médaille de Charon Couronné ?</>",
          DialogueId = 510016121,
          FailDialogue = 51001690,
          GUID = "510016121.0",
          ImprCheckId = 1013,
          NextDialogue = 51001613,
          Subtitle = "May I have the honour to take a peek at your \"Laurelled Charon\" medal?"
        },
        [510017031] = {
          ContentFR = "<I>Conseiller sincèrement de faire plus attention à son hygiène</>",
          DialogueId = 510017031,
          GUID = "510017031.0",
          ImprPlusId = 1003,
          NextDialogue = 51001704,
          Subtitle = "(Sincerely suggest he looks into personal hygiene.)"
        },
        [510017032] = {
          ContentFR = "<I>Présenter ses excuses pour la réaction déplacée</>",
          DialogueId = 510017032,
          GUID = "510017032.0",
          ImprPlusId = 1004,
          NextDialogue = 51001704,
          Subtitle = "(Apologise for your rather impolite reaction just now.)"
        },
        [510017033] = {
          ContentFR = "<I>Reprocher de sentir si mauvais que ça en devient insupportable</>",
          DialogueId = 510017033,
          GUID = "510017033.0",
          ImprPlusId = 1002,
          NextDialogue = 51001704,
          Subtitle = "(Complain that his stench is unbearable and affects those around him.)"
        },
        [510017081] = {
          ContentFR = "<I>Un homme qui sauve des vies ne devrait pas se retrouver à réparer des canalisations.</>",
          DialogueId = 510017081,
          FailDialogue = 51001709,
          GUID = "510017081.0",
          ImprCheckId = 1014,
          NextDialogue = 51001711,
          Subtitle = "A life-saver like you shouldn't be stuck mending sewers."
        },
        [510017161] = {
          ContentFR = "<I>Si tu pouvais revivre ta vie, referais-tu le même choix ?</>",
          DialogueId = 510017161,
          GUID = "510017161.0",
          NextDialogue = 51001717,
          Subtitle = "If you had a chance to do it all over, would you make the same choice to save him?"
        },
        [510018011] = {
          ContentFR = "<I>Accepter</>",
          DialogueId = 510018011,
          GUID = "510018011.0",
