          ImprCheckId = 1028,
          NextDialogue = 51003903,
          Subtitle = "(Try to talk to her)"
        },
        [510039131] = {
          ContentFR = "<I>Tu n’as rien fait de mal.</>",
          DialogueId = 510039131,
          GUID = "510039131.0",
          ImprPlusId = 1002,
          NextDialogue = 51003914,
          Subtitle = "You did nothing wrong."
        },
        [510039132] = {
          ContentFR = "<I>Pourquoi jouer avec eux ? Mieux vaudrait leur coller une bonne raclée.</>",
          DialogueId = 510039132,
          GUID = "510039132.0",
          ImprPlusId = 1005,
          NextDialogue = 51003917,
          Subtitle = "Why bother playing with them? You should give them a thrashing."
        },
        [510039133] = {
          ContentFR = "<I>Ils t’ont menti. Ne les crois pas.</>",
          DialogueId = 510039133,
          GUID = "510039133.0",
          ImprPlusId = 1003,
          NextDialogue = 51003919,
          Subtitle = "They lied. Don't believe a word they say."
        },
        [510040011] = {
          ContentFR = "<I>Imagine que tu es un démon féroce.</>",
          DialogueId = 510040011,
          GUID = "510040011.0",
          NextDialogue = 51004002,
          Subtitle = "Imagine that you're a vicious demon."
        },
        [510040012] = {
          ContentFR = "<I>Répète-leur les insultes qu’ils t’adressent.</>",
          DialogueId = 510040012,
          GUID = "510040012.0",
          NextDialogue = 51004002,
          Subtitle = "They call you names, right? It's tit-for-tat time."
        },
        [510040061] = {
          ContentFR = "<I>Vous savez qui nous sommes. Alors dégagez.</>",
          DialogueId = 510040061,
          GUID = "510040061.0",
          NextDialogue = 51004008,
          Subtitle = "Since you know we're Charons, you better scram."
        },
        [510040062] = {
          ContentFR = "<I>Pas de panique. Cette jeune fille a des choses à vous dire.</>",
          DialogueId = 510040062,
          GUID = "510040062.0",
          NextDialogue = 51004007,
          Subtitle = "Easy, kids. This young lady has something nice to say."
        },
        [510041091] = {
          ContentFR = "<I>Toi aussi, tu sais manier les mots. Entraîne-toi quand tu en as l’occasion.</>",
          DialogueId = 510041091,
          GUID = "510041091.0",
          ImprPlusId = 1005,
          NextDialogue = 51004110,
          Subtitle = "And you seem to be really good at spouting insults. Practice when you have the chance. You'll get better."
        },
        [510041092] = {
          ContentFR = "<I>Merci du compliment. Mais l’important, c’est que tu as osé leur tenir tête.</>",
          DialogueId = 510041092,
          GUID = "510041092.0",
          ImprPlusId = 1003,
          NextDialogue = 51004110,
          Subtitle = "You flatter me. The most important lesson is that you learned to stand up for yourself."
        },
        [510041141] = {
          ContentFR = "<I>Essayer de la convaincre</>",
          DialogueId = 510041141,
          FailDialogue = 51004115,
          GUID = "510041141.0",
          ImprCheckId = 1029,
          NextDialogue = 51004116,
          Subtitle = "(Try to persuade Faye)"
        },
        [510041211] = {
          ContentFR = "<I>Accepter</>",
          DialogueId = 510041211,
          GUID = "510041211.0",
          NextDialogue = 51004122,
          Subtitle = "(Agree)"
        },
        [510041212] = {
          ContentFR = "<I>Refuser</>",
          DialogueId = 510041212,
          GUID = "510041212.0",
          NextDialogue = 51004124,
          Subtitle = "(Refuse)"
        },
        [510041271] = {
          ContentFR = "Tes tresses aussi sont jolies.",
          DialogueId = 510041271,
          GUID = "510041271.0",
          NextDialogue = 51004128,
          Subtitle = "Your pigtails are cute too."
        },
        [510041301] = {
          ContentFR = "<I>Oui.</>",
          DialogueId = 510041301,
          GUID = "510041301.0",
          NextDialogue = 51004131,
          Subtitle = "Yes, they do."
        },
        [510041302] = {
          ContentFR = "<I>Plutôt des cornes de chèvre...</>",
          DialogueId = 510041302,
          GUID = "510041302.0",
          NextDialogue = 51004132,
          Subtitle = "Actually, they look more like goat horns..."
        },
        [510041331] = {
          ContentFR = "<I>Accepter</>",
          DialogueId = 510041331,
          GUID = "510041331.0",
          NextDialogue = 51004136,
          Subtitle = "(Accept)"
        },
        [510041332] = {
          ContentFR = "<I>Refuser</>",
          DialogueId = 510041332,
          GUID = "510041332.0",
          NextDialogue = 51004134,
          Subtitle = "(Refuse)"
        },
        [510041421] = {
          ContentFR = "Je m’appelle {nickname}.",
          DialogueId = 510041421,
          GUID = "510041421.0",
          NextDialogue = 51004143,
          Subtitle = "."
        },
        [510041491] = {
          ContentFR = "<I>Oui.</>",
          DialogueId = 510041491,
          GUID = "510041491.0",
          NextDialogue = 51004150,
          Subtitle = "You're right."
        },
        [510041492] = {
          ContentFR = "<I>...</>",
          DialogueId = 510041492,
          GUID = "510041492.0",
          NextDialogue = 51004150,
          Subtitle = "..."
        },
        [510042031] = {
          ContentFR = "<I>Ce n’est pas toi qui m’as fait venir ?</>",
          DialogueId = 510042031,
          GUID = "510042031.0",
          ImprPlusId = 1005,
          NextDialogue = 51004204,
          Subtitle = "You did, didn't you?"
        },
        [510042032] = {
          ContentFR = "<I>C’est la personne que tu attends qui m’envoie.</>",
          DialogueId = 510042032,
          GUID = "510042032.0",
          ImprPlusId = 1003,
          NextDialogue = 51004205,
          Subtitle = "The person you're waiting for."
        },
        [510042033] = {
          ContentFR = "<I>Ce sont les pièces d’argent dans ma poche qui m’envoient.</>",
          DialogueId = 510042033,
          GUID = "510042033.0",
          ImprPlusId = 1001,
          NextDialogue = 51004206,
          Subtitle = "The silver coins in my pocket sent me here."
        },
        [510042151] = {
          ContentFR = "<I>Tu...</>",
          DialogueId = 510042151,
          GUID = "510042151.0",
          NextDialogue = 51004216,
          Subtitle = "You..."
        },
        [510042152] = {
          ContentFR = "<I>Bien...</>",
          DialogueId = 510042152,
          GUID = "510042152.0",
          NextDialogue = 51004216,
          Subtitle = "Well..."
        },
        [510042171] = {
          ContentFR = "<I>Si ça venait à tomber entre de mauvaises mains...</>",
          DialogueId = 510042171,
          FailDialogue = 51004218,
          GUID = "510042171.0",
          ImprCheckId = 1030,
          NextDialogue = 51004219,
          Subtitle = "(Well, can't let it fall into the wrong hands...)"
        },
        [510042172] = {
          ContentFR = "<I>Ça a l’air redoutable, je le veux...</>",
          DialogueId = 510042172,
          FailDialogue = 51004218,
          GUID = "510042172.0",
          ImprCheckId = 1031,
          NextDialogue = 51004219,
          Subtitle = "(It looks like a handy piece. I gotta get it...)"
        },
        [510043111] = {
          ContentFR = "Qu’est-ce que tu veux ?",
          DialogueId = 510043111,
          GUID = "510043111.0",
          SpeakNpcId = 700096,
          Subtitle = "What do you want?"
        },
        [510044011] = {
          ContentFR = "<I>Le rat des caniveaux.</>",
          DialogueId = 510044011,
          GUID = "510044011.0",
          NextDialogue = 51004402,
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = "The Rat in the Gutter"
        },
        [510044012] = {
          ContentFR = "<I>La mousse des profondeurs.</>",
          DialogueId = 510044012,
          GUID = "510044012.0",
          NextDialogue = 51004403,
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "The Moss Beneath the Ground"
        },
        [510044013] = {
          ContentFR = "<I>La gloire des jours anciens.</>",
          DialogueId = 510044013,
          GUID = "510044013.0",
          NextDialogue = 51004403,
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "The Glory of Days Long Gone"
        },
        [510049011] = {
          ContentFR = "<I>Montrer un indice</>",
          DialogueId = 510049011,
          GUID = "510049011.0",
          NextDialogue = 51004902,
          Subtitle = "(Show her the thing)"
        },
        [510049012] = {
          ContentFR = "<I>Partir</>",
          DialogueId = 510049012,
          GUID = "510049012.0",
          Scripts = "SetOutport{FinishType{\"Fail\"}}",
          Subtitle = "(Leave)"
        },
        [510049021] = {
          ContentFR = "<I>Montrer la boîte d’étoiles en papier</>",
          DialogueId = 510049021,
          GUID = "510049021.0",
          NextDialogue = 51004903,
          Subtitle = "(A Box of Paper Stars)"
        },
        [510049022] = {
          ContentFR = "<I>Montrer l’ordonnance</>",
          DialogueId = 510049022,
          GUID = "510049022.0",
          NextDialogue = 51004905,
          Subtitle = "(A Dangerous Prescription)"
        },
        [510049023] = {
          ContentFR = "<I>Montrer la clé</>",
          DialogueId = 510049023,
          GUID = "510049023.0",
          NextDialogue = 51004903,
          Subtitle = "(A Key to a Safe)"
        },
        [510049031] = {
          ContentFR = "<I>Montrer un autre indice</>",
          DialogueId = 510049031,
          GUID = "510049031.0",
          NextDialogue = 51004902,
          Subtitle = "(Show her another one)"
        },
        [510049032] = {
          ContentFR = "<I>Partir</>",
          DialogueId = 510049032,
          GUID = "510049032.0",
          Scripts = "SetOutport{FinishType{\"Fail\"}}",
          Subtitle = "(Leave)"
        },
        [510049091] = {
          ContentFR = "<I>Ne vous inquiétez pas. Je ne suis pas là pour vous menacer.</>",
          DialogueId = 510049091,
          GUID = "510049091.0",
          ImprPlusId = 1002,
          NextDialogue = 51004910,
          Subtitle = "Relax. I'm not here to threaten you."
        },
        [510049092] = {
          ContentFR = "<I>Imiter ses gestes avec tes mains</>",
          DialogueId = 510049092,
          GUID = "510049092.0",
          ImprPlusId = 1005,
          NextDialogue = 51004911,
          Subtitle = "Gesture like she does."
        },
        [510049141] = {
          ContentFR = "« Jusqu’à ce qu’ils me fassent boire du poison à base de Lotus d’hiver. Je n’en suis pas morte, mais je ne pouvais plus parler. »",
          DialogueId = 510049141,
          GUID = "510049141.0",
          NextDialogue = 51004915,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          Subtitle = "\"Then they forced poison brewed from Eclipta Grass down my throat. It didn't kill me... but it took my voice.\"",
          TalkActionId = {
            [1] = "700010:Explain02_End"
          }
        },
        [510049171] = {
          ContentFR = "<I>Mais à quoi bon écrire tout cela ? Cela ne changera rien, et cela ne fera que vous attirer des ennuis.</>",
          DialogueId = 510049171,
          GUID = "510049171.0",
          ImprPlusId = 1001,
          NextDialogue = 51004918,
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = "But it won't change anything. It only gets you in trouble."
        },
        [510049172] = {
          ContentFR = "<I>Même après tout cela, vous continuez d’écrire. J’admire votre courage.</>",
          DialogueId = 510049172,
          GUID = "510049172.0",
          ImprPlusId = 1004,
          NextDialogue = 51004923,
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          Subtitle = "Despite enduring such a great misfortune, you still keep on writing. I truly admire your courage."
        },
        [510049173] = {
          ContentFR = "<I>Cette ordonnance est entre mes mains. Si vous la voulez, il faudra payer pour la récupérer.</>",
          DialogueId = 510049173,
          GUID = "510049173.0",
          ImprPlusId = 1005,
          NextDialogue = 51004927,
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          Subtitle = "This \"prescription\" is now in my hands. Better pay up if you want it back."
        },
        [510050121] = {
          ContentFR = "<I>Tout le monde voit cette demeure comme une maison hantée. Pourtant, vous ne semblez ni effrayée ni surprise.</>",
          DialogueId = 510050121,
          FailDialogue = 51005013,
          GUID = "510050121.0",
          ImprCheckId = 1024,
          NextDialogue = 51005015,
          Subtitle = "Everyone sees this house as a haunted place, but you seem neither disturbed nor surprised."
        },
        [510050171] = {
          ContentFR = "<I>Vous connaissiez Monsieur Henrik depuis longtemps ?</>",
          DialogueId = 510050171,
          GUID = "510050171.0",
          NextDialogue = 51005018,
          Subtitle = "Have you known Mr Henrik for a long time?"
        },
        [510050201] = {
          ContentFR = "<I>Hélas, ses bonnes actions ne lui ont pas valu la reconnaissance méritée.</>",
          DialogueId = 510050201,
          GUID = "510050201.0",
          ImprPlusId = 1001,
          NextDialogue = 51005021,
          Subtitle = "Too bad his kindness failed to earn him the reputation he deserved."
        },
        [510050202] = {
          ContentFR = "<I>Il a toujours défendu ce qu’il y avait d’humain en lui.</>",
          DialogueId = 510050202,
          GUID = "510050202.0",
          ImprPlusId = 1002,
          NextDialogue = 51005022,
          Subtitle = "He upheld the fundamental values that define the humanity."
        },
        [510050203] = {
          ContentFR = "<I>Peut-être... a-t-il pensé à sa propre fille.</>",
          DialogueId = 510050203,
          GUID = "510050203.0",
          ImprPlusId = 1004,
          NextDialogue = 51005023,
          Subtitle = "Perhaps... that Charon girl reminded him of his own daughter."
        },
        [510050231] = {
          ContentFR = "<I>S’il savait que vous continuez de veiller sur cette maison même après sa mort... il en serait heureux.</>",
          DialogueId = 510050231,
          GUID = "510050231.0",
          NextDialogue = 51005024,
          Subtitle = "Mr Henrik would be pleased to know his home has been well cared for after his departure."
        },
        [510050261] = {
          ContentFR = "La clé qu’elle tient éveille en toi un étrange sentiment de familiarité.",
          DialogueId = 510050261,
          FailDialogue = 51005027,
          GUID = "510050261.0",
          ImprCheckId = 1025,
          NextDialogue = 51005028,
          Subtitle = "(The key in Ms Lina's hand stirs a sense of familiarity.)"
        },
        [510050291] = {
          ContentFR = "<I>Madame Lina, reconnaissez-vous cette clé ?</>",
          DialogueId = 510050291,
          GUID = "510050291.0",
          NextDialogue = 51005030,
          Subtitle = "Ms Lina, is this key familiar to you?"
        },
        [510050391] = {
          Camera = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
          ContentFR = "Prenez-la. J’en suis {性别:le|la} témoin, cette clé vous appartient désormais.",
          DialogueId = 510050391,
          GUID = "510050391.0",
          SpeakNpcId = 100001,
          Subtitle = "Please accept this. I shall bear witness to this transfer. This key is, and shall forever be, yours."
        },
        [510050411] = {
          ContentFR = "Tous ceux qui vivent sous la lumière du soleil... n’ont pas forcément la conscience en paix.",
          DialogueId = 510050411,
          GUID = "510050411.0",
          SpeakNpcId = 700013,
          Subtitle = "Not all who dwell in the light live with a clear conscience."
        },
        [510051051] = {
          ContentFR = "<I>Je ne juge pas et ça m’importe peu. Je ne reste ici que pour accomplir certaines choses.</>",
          DialogueId = 510051051,
          GUID = "510051051.0",
          ImprPlusId = 1001,
          NextDialogue = 51005106,
          Subtitle = "I don't judge and I don't care. I've got things to do here, and that's why I'm staying for now."
        },
        [510051052] = {
          ContentFR = "<I>C’est ma première fois dans une grande ville. L’ambiance est étrange et j’ai rencontré des gens et vécu des choses inédites... Honnêtement, je ne m’y suis pas encore fait.</>",
          DialogueId = 510051052,
          GUID = "510051052.0",
          ImprPlusId = 1004,
          NextDialogue = 51005107,
          Subtitle = "It's my first visit to a large city like this. The place has a unique vibe. I've met plenty of interesting people and had some bizarre adventures here. Truth be told, I'm not very used to it..."
        },
        [510051053] = {
          ContentFR = "<I>Je m’y sens comme chez moi !</>",
          DialogueId = 510051053,
          GUID = "510051053.0",
          ImprPlusId = 1005,
          NextDialogue = 51005108,
          Subtitle = "Feels just like home!"
        },
        [510051111] = {
          ContentFR = "<I>Ce ne sont que des objets d’occasion, ça n’a pas beaucoup de valeur.</>",
          DialogueId = 510051111,
          GUID = "510051111.0",
          ImprPlusId = 1001,
          NextDialogue = 51005112,
          Subtitle = "Just a bunch of second-hand stuff with no real value."
        },
        [510051112] = {
          ContentFR = "<I>Je veux juste vérifier, ce n’est pas... volé, j’espère ?</>",
          DialogueId = 510051112,
          GUID = "510051112.0",
          ImprPlusId = 1002,
          NextDialogue = 51005113,
          Subtitle = "I have to ask this first — these aren't... stolen, by any chance?"
        },
        [510051113] = {
          ContentFR = "<I>Où as‑tu trouvé ça ? Je veux voir !</>",
          DialogueId = 510051113,
          GUID = "510051113.0",
          ImprPlusId = 1005,
          NextDialogue = 51005114,
          Subtitle = "Where did you get them? Count me in!"
        },
        [510051151] = {
          ContentFR = "<I>Tu prends une ordonnance avec un poème un peu insolent griffonné derrière.</>",
          DialogueId = 510051151,
          FailDialogue = 51005116,
          GUID = "510051151.0",
          ImprCheckId = 1040,
          NextDialogue = 51005117,
          Subtitle = "(You pick up a prescription. A seemingly seditious poem is written behind it.)"
        },
        [510051152] = {
          ContentFR = "<I>Tu prends une boîte d’étoiles en papier. Son propriétaire avait probablement un vœu qu’il voulait réaliser.</>",
          DialogueId = 510051152,
          FailDialogue = 51005116,
          GUID = "510051152.0",
          ImprCheckId = 1041,
          NextDialogue = 51005117,
          Subtitle = "(You pick up a box of paper stars. Its owner probably had a wish they wanted to fulfil.)"
        },
        [510051153] = {
          ContentFR = "<I>Tu prends une clé qui te semble familière. Tu as déjà vu quelque chose de similaire chez Henrik.</>",
          DialogueId = 510051153,
          FailDialogue = 51005116,
          GUID = "510051153.0",
          ImprCheckId = 1042,
          NextDialogue = 51005117,
          Subtitle = "(You pick up a key that looks rather familiar — you remember seeing a similar key at Henrik's place.)"
        },
        [510051251] = {
          ContentFR = "<I>C’est suffisant ?</>",
          DialogueId = 510051251,
          GUID = "510051251.0",
          ImprPlusId = 1002,
          NextDialogue = 51005126,
          Subtitle = "Will these coins be enough?"
        },
        [510051252] = {
          ContentFR = "<I>Et mes 20 % de réduction ?</>",
          DialogueId = 510051252,
          GUID = "510051252.0",
          ImprPlusId = 1001,
          NextDialogue = 51005127,
          Subtitle = "What about my 20% discount?"
        },
        [510051253] = {
          ContentFR = "<I>Je m’en vais.</>",
          DialogueId = 510051253,
          GUID = "510051253.0",
          ImprPlusId = 1005,
          NextDialogue = 51005128,
          Subtitle = "Outta here."
        },
        [510051321] = {
          ContentFR = "Bonne chance pour tes enquêtes, détective !",
          DialogueId = 510051321,
          GUID = "510051321.0",
          NextDialogue = 510051322,
          SpeakNpcId = 700115,
          Subtitle = "Good luck with your investigations, Detective!"
        },
        [510051322] = {
          ContentFR = "Quand tu auras découvert les histoires derrière ces objets, reviens me raconter ce que tu penses de Givrelac !",
          DialogueId = 510051322,
          GUID = "510051322.0",
          SpeakNpcId = 700115,
          Subtitle = "Once you've investigated the stories behind them, come back and tell me what you think about Icelake!"
        },
        [510052021] = {
          ContentFR = "<I>L’ordonnance appartient au Docteur Luna. Elle fut autrefois une ménestrelle itinérante, mais ceux qui haïssent les Charon lui ont volé sa voix. Ces poèmes sont désormais son seul exutoire, son unique façon de se confier.</>",
          DialogueId = 510052021,
          GUID = "510052021.0",
          NextDialogue = 51005203,
          Subtitle = "Dr Luna wrote the prescription. She was once a wandering bard, but some Charon-haters took her voice. Now, composing poems in this way is her only outlet for expressing her anguish."
        },
        [510052022] = {
          ContentFR = "<I>Jessica, la vendeuse de billets, rêvait de prendre le train et de partir, mais elle ne pouvait que plier des billets expirés en étoiles, espérant un miracle.</>",
          DialogueId = 510052022,
          GUID = "510052022.0",
          NextDialogue = 51005204,
          Subtitle = "The biggest dream of Jessica, the ticket seller, is to take a train and leave this place. All she could do was fold expired tickets into paper stars and pray for a miracle."
        },
        [510052023] = {
          ContentFR = "La clé ouvre un coffre. Nous y avons trouvé un testament. Madame Lina est devenue ma nouvelle propriétaire et m’a dispensée de loyer.",
          DialogueId = 510052023,
          GUID = "510052023.0",
          NextDialogue = 51005205,
          Subtitle = "That key opens a safe. Inside, we found a will, and Ms Lina became my new landlady. She also said I could stay rent-free."
        },
        [510052081] = {
          ContentFR = "<I>Mieux vaut toujours faire attention à Givrelac, dépasser les limites ne fait que nuire à soi et aux autres.</>",
          DialogueId = 510052081,
          GUID = "510052081.0",
          ImprPlusId = 1001,
          NextDialogue = 51005209,
          Subtitle = "Always try to play it \"safe\" in Icelake. Going the extra mile will just get yourself and others into trouble. It really isn't worth it."
        },
        [510052082] = {
          ContentFR = "<I>La vie n’est jamais simple. À Givrelac, il faut rester fidèle à ses principes.</>",
          DialogueId = 510052082,
          GUID = "510052082.0",
          ImprPlusId = 1002,
          NextDialogue = 51005209,
          Subtitle = "Life is seldom a breeze. The only thing we can do in Icelake is stick to our principles."
        },
        [510052083] = {
          ContentFR = "<I>Tout le monde ne suit pas les \"lois de la ville\". Combien transgressent en secret ?</>",
          DialogueId = 510052083,
          GUID = "510052083.0",
          ImprPlusId = 1003,
          NextDialogue = 51005209,
          Subtitle = "Not everyone believes in the \"city laws\". It makes you wonder how many people break the rules in the dark."
        },
        [510052084] = {
          ContentFR = "<I>Les gens ici s’accrochent à leurs espoirs, à leurs croyances et à leurs circonstances... C’est tout ce qu’ils ont. Ils essaient de s’accrocher, et puis de mauvaises choses arrivent.</>",
          DialogueId = 510052084,
          GUID = "510052084.0",
          ImprPlusId = 1004,
          NextDialogue = 51005209,
          Subtitle = "The people here cling to their hopes, faiths, and circumstances... These are all they have. They try to hold on, and then bad things happen."
        },
        [510052085] = {
          ContentFR = "<I>Cette cité est comme une poudrière sur le point d’exploser ! Le Lac du Deuil pourrait s’évaporer à tout moment !</>",
          DialogueId = 510052085,
          GUID = "510052085.0",
          ImprPlusId = 1005,
          NextDialogue = 51005209,
          Subtitle = "The city's like powder kegs ready to explode! Lamenting Lake shall vaporize and give us a show!"
        },
        [510052131] = {
          ContentFR = "Tout se passe bien, détective ?",
          DialogueId = 510052131,
          GUID = "510052131.0",
          SpeakNpcId = 700128,
          Subtitle = "Is everything going smooth, Detective?"
        },
        [510053031] = {
          ContentFR = "<I>S’approcher pour jeter un œil au carnet</>",
          DialogueId = 510053031,
          GUID = "510053031.0",
          ImprPlusId = 1003,
          NextDialogue = 51005304,
          Subtitle = "(Take a closer look at his notes)"
        },
        [510053032] = {
          ContentFR = "<I>S’éloigner silencieusement</>",
          DialogueId = 510053032,
          GUID = "510053032.0",
          ImprPlusId = 1004,
          NextDialogue = 51005306,
          Subtitle = "(Leave silently)"
        },
        [510053111] = {
          ContentFR = "<I>Une marinade... ça se mange... crue ?</>",
          DialogueId = 510053111,
          GUID = "510053111.0",
          NextDialogue = 51005312,
          Subtitle = "Marinated seafood? So, is it eaten... raw?"
        },
        [510053112] = {
          ContentFR = "<I>Ça a l’air vraiment... unique.</>",
          DialogueId = 510053112,
          GUID = "510053112.0",
          NextDialogue = 51005312,
          Subtitle = "That does sound quite... unique."
        },
        [510053121] = {
          ContentFR = "Je compte sur toi pour les ingrédients. Moi, je vais réfléchir à de possibles améliorations de la recette.",
          DialogueId = 510053121,
          GUID = "510053121.0",
          SpeakNpcId = 700116,
          Subtitle = "Please help me gather the ingredients. I'll use this time to refine the recipe."
        },
        [510054021] = {
          DialogueId = 510054021,
          GUID = "510054021.0",
          IsBlack = 1
        },
        [510054061] = {
          ContentFR = "<I>C’est encore cru, je passe !</>",
          DialogueId = 510054061,
          GUID = "510054061.0",
          ImprPlusId = 1003,
          NextDialogue = 51005407,
          Subtitle = "They're raw, aren't they? I'm good."
        },
        [510054062] = {
          ContentFR = "<I>Prendre une bouchée avec précaution et complimenter le plat</>",
          DialogueId = 510054062,
          GUID = "510054062.0",
          ImprPlusId = 1004,
          NextDialogue = 51005408,
          Subtitle = "(Take a cautious bite and muster a compliment)"
        },
        [510054063] = {
          ContentFR = "<I>Même {性别:affamé|affamée}, je préférerais manger de la neige.</>",
          DialogueId = 510054063,
          GUID = "510054063.0",
          ImprPlusId = 1005,
          NextDialogue = 51005409,
          Subtitle = "Even if I were starving, I'd rather eat ice and snow."
        },
        [510055071] = {
          ContentFR = "Je compte sur toi pour les Phoxénotruites. Moi, je vais réfléchir à comment améliorer la recette.",
          DialogueId = 510055071,
          GUID = "510055071.0",
          SpeakNpcId = 700117,
          Subtitle = "While you're out fishing, I'll brainstorm some enhancements to the recipe."
        },
        [510056011] = {
          ContentFR = "<I>Remarquer les traces de sang sur les peaux des Baies boréales</>",
          DialogueId = 510056011,
          GUID = "510056011.0",
          ImprPlusId = 1003,
          NextDialogue = 51005602,
          Subtitle = "(You notice bloodstains on the Borealberry peels.)"
        },
        [510056012] = {
          ContentFR = "<I>Remarquer le sang sur Marcus</>",
          DialogueId = 510056012,
          GUID = "510056012.0",
          ImprPlusId = 1004,
          NextDialogue = 51005603,
          Subtitle = "(You notice the bloodstains on Marcus's clothes.)"
        },
        [510057121] = {
          ContentFR = "<I>Exprimer honnêtement combien c’est délicieux, convaincu que tout le monde l’adorera</>",
          DialogueId = 510057121,
          GUID = "510057121.0",
          ImprPlusId = 1002,
          NextDialogue = 51005713,
          Subtitle = "(Be honest and tell him it's very delicious and people will definitely love it.)"
        },
        [510057122] = {
          ContentFR = "<I>Mentir, dire que c’est bon mais sans grande originalité, et conseiller Marcus de soigner sa santé avant de chercher un nouveau travail</>",
          DialogueId = 510057122,
          GUID = "510057122.0",
          ImprPlusId = 1004,
          NextDialogue = 51005716,
          Subtitle = "(Lie to Marcus by saying that the dish is good but ordinary. Advise him to take good care of himself first and find another job once he gets better.)"
        },
        [510058021] = {
          ContentFR = "<I>Hein ? Tous les coffres de la cité ne sont-ils pas pour moi ?</>",
          DialogueId = 510058021,
          GUID = "510058021.0",
          ImprPlusId = 1005,
          NextDialogue = 51005803,
          Subtitle = "Aren't all the chests in this city mine?"
        },
        [510058022] = {
          ContentFR = "{性别:Désolé|Désolée}, je ne savais pas que ce coffre était à vous.",
          DialogueId = 510058022,
          GUID = "510058022.0",
          ImprPlusId = 1002,
          NextDialogue = 51005804,
          Subtitle = "Sorry. I didn't know this chest belonged to you."
        },
        [510058023] = {
          ContentFR = "Il n’y a pas vos noms sur ce coffre, non ?",
          DialogueId = 510058023,
          GUID = "510058023.0",
          ImprPlusId = 1001,
          NextDialogue = 51005807,
          Subtitle = "This chest doesn't have your names on it."
        },
        [510059041] = {
          ContentFR = "<I>Pff... prenez le coffre, ça suffit, non ?</>",
          DialogueId = 510059041,
          GUID = "510059041.0",
          ImprPlusId = 1004,
          Subtitle = "Ugh... Fine, you can have it."
        },
        [510059042] = {
          ContentFR = "<I>Donne un violent coup de pied à Petit Frère avec l’autre jambe</>",
          DialogueId = 510059042,
          GUID = "510059042.0",
          ImprPlusId = 1005,
          Subtitle = "(Give Small Bro a vicious kick with the other leg)"
        },
        [510059251] = {
          ContentFR = "<I>Partenaire.</>",
          DialogueId = 510059251,
          GUID = "510059251.0",
          ImprPlusId = 1001,
          NextDialogue = 51005926,
          Subtitle = "A partner."
        },
        [510059252] = {
          ContentFR = "<I>Esclave.</>",
          DialogueId = 510059252,
          GUID = "510059252.0",
          ImprPlusId = 1005,
          NextDialogue = 51005926,
          Subtitle = "A slave."
        },
        [510059253] = {
          ContentFR = "<I>Ami.</>",
          DialogueId = 510059253,
          GUID = "510059253.0",
          ImprPlusId = 1002,
          NextDialogue = 51005926,
          Subtitle = "A friend."
        },
        [510059371] = {
          ContentFR = "<I>... On profite de ces simples d’esprit. Je me sens un peu coupable.</>",
          DialogueId = 510059371,
          GUID = "510059371.0",
          ImprPlusId = 1002,
          NextDialogue = 51005938,
          Subtitle = "...Feels like we're taking advantage of these simpletons. I somehow feel a bit guilty."
        },
        [510059372] = {
          ContentFR = "<I>Ce n’est pas assez. Donnez tout ce que vous avez pour récompenser votre {性别:Super Frère|Super Sœur}.</>",
          DialogueId = 510059372,
          GUID = "510059372.0",
          ImprPlusId = 1005,
          NextDialogue = 51005939,
          Subtitle = "Nah, that's not enough. Hand over all you have and make your Super Bros happy."
        },
        [510060171] = {
          ContentFR = "<I>Certains seront mal à l’aise rien qu’en lisant ce nom.</>",
          DialogueId = 510060171,
          GUID = "510060171.0",
          ImprPlusId = 1004,
          NextDialogue = 51006018,
          Subtitle = "The name might make some people uncomfortable."
        },
        [510060172] = {
          ContentFR = "<I>Ça risque de faire fuir les clients.</>",
          DialogueId = 510060172,
          GUID = "510060172.0",
          ImprPlusId = 1001,
          NextDialogue = 51006019,
          Subtitle = "It might scare off potential clients."
        },
        [510060173] = {
          ContentFR = "<I>Moi j’aime bien. On devrait vraiment étudier les insectes comestibles !</>",
          DialogueId = 510060173,
          GUID = "510060173.0",
          ImprPlusId = 1005,
          NextDialogue = 51006020,
          Subtitle = "I like it. We should look into edible insects."
        },
        [510067091] = {
          ContentFR = "<I>Honnêtement, je comprends. Personne n’a envie de défier un record imbattable.</>",
          DialogueId = 510067091,
          GUID = "510067091.0",
          ImprPlusId = 1004,
          NextDialogue = 51006710,
          Subtitle = "That's understandable. I wouldn't want to compete against an unbeatable record either."
        },
        [510067092] = {
          ContentFR = "<I>Donc tu t’es servi de moi pour te venger de l’Étranger.</>",
          DialogueId = 510067092,
          GUID = "510067092.0",
          ImprPlusId = 1001,
          NextDialogue = 51006712,
          Subtitle = "So you were using me to get back at Outsider."
        },
        [510067093] = {
          ContentFR = "<I>L’Étranger, tu es trop lent ! Quelle honte... tu ferais mieux de changer de métier !</>",
          DialogueId = 510067093,
          GUID = "510067093.0",
          ImprPlusId = 1005,
          NextDialogue = 51006715,
          Subtitle = "You're too slow, Outsider. That's just embarrassing. Maybe it's time for a career switch."
        },
        [510070011] = {
          ContentFR = "<I>Cette ville est comme ça. À force, on finit par s’y habituer.</>",
          DialogueId = 510070011,
          GUID = "510070011.0",
          ImprPlusId = 1004,
          NextDialogue = 51007002,
          Subtitle = "Seems par for the course in this city. You'll get used to it after a while."
        },
        [510070012] = {
          ContentFR = "<I>Tu sais même pas répliquer ?</>",
          DialogueId = 510070012,
          GUID = "510070012.0",
          ImprPlusId = 1005,
          NextDialogue = 51007003,
          Subtitle = "You can't even throw a comeback?"
        },
        [510070051] = {
          ContentFR = "<I>Laissez-moi passer, je crois avoir une solution.</>",
          DialogueId = 510070051,
          FailDialogue = 51007006,
          GUID = "510070051.0",
          ImprCheckId = 1060,
          NextDialogue = 51007007,
          Subtitle = "Excuse me, I think I can smooth things over here."
        },
        [510071161] = {
          ContentFR = "<I>C’est important pour toi, non ? Tu veux vraiment laisser ça partir ?</>",
          DialogueId = 510071161,
          GUID = "510071161.0",
          ImprPlusId = 1004,
          NextDialogue = 51007117,
          Subtitle = "These stars obviously hold sentimental value. Is it really okay to let someone else take them away?"
        },
        [510071162] = {
          ContentFR = "<I>Déplier une autre étoile et lire son contenu à voix haute</>",
          DialogueId = 510071162,
          GUID = "510071162.0",
          ImprPlusId = 1005,
          NextDialogue = 51007119,
          Subtitle = "(Unfolds another star and reads the message aloud.)"
        },
        [510073021] = {
          ContentFR = "<I>Le désir, c’est chercher à comprendre ce que vous voulez vraiment.</>",
          DialogueId = 510073021,
          GUID = "510073021.0",
          ImprPlusId = 1001,
          NextDialogue = 510073024,
          Subtitle = "Passion is the will to unravel what you really want."
        },
        [510073022] = {
          ContentFR = "<I>Le désir est la force première qui anime toute vie.</>",
          DialogueId = 510073022,
          GUID = "510073022.0",
          ImprPlusId = 1003,
          NextDialogue = 510073025,
          Subtitle = "Passion is the force that sustains life itself."
        },
        [510073023] = {
          ContentFR = "<I>Le désir est un sujet qu’on évite en public.</>",
          DialogueId = 510073023,
          GUID = "510073023.0",
          ImprPlusId = 1005,
          NextDialogue = 510073026,
          Subtitle = "Passion is the unspoken that hides from the light of day."
        },
        [510073024] = {
          ContentFR = "Je... je ne sais même pas ce que je veux...",
          DialogueId = 510073024,
          GUID = "7FB1017D",
          NextDialogue = 51007303,
          SpeakNpcId = 700077,
          Subtitle = "I don't even know what I really want..."
        },
        [510073025] = {
          ContentFR = "C’est si profond... trop vaste pour moi...",
          DialogueId = 510073025,
          GUID = "7FB1017E",
          NextDialogue = 51007303,
          SpeakNpcId = 700077,
          Subtitle = "Such depth — too vast for me to grasp..."
        },
        [510073026] = {
          ContentFR = "Je comprends mieux... voilà pourquoi je n’y comprenais rien.",
          DialogueId = 510073026,
          GUID = "7FB1017F",
          NextDialogue = 51007303,
          SpeakNpcId = 700077,
          Subtitle = "Oh, I see! No wonder I didn't get it."
        },
        [510073031] = {
          ContentFR = "<I>Accepter</>",
          DialogueId = 510073031,
          GUID = "510073031.0",
          NextDialogue = 51007304,
          Subtitle = "(Accept)"
        },
        [510073032] = {
          ContentFR = "<I>Refuser</>",
          DialogueId = 510073032,
          GUID = "510073032.0",
          Scripts = "SetOutport{FinishType{\"Fail\"}}",
          Subtitle = "(Refuse)"
        },
        [510073131] = {
          ContentFR = "<I>Ce rapport... ne semble pas très académique.</>",
          DialogueId = 510073131,
          GUID = "510073131.0",
          ImprPlusId = 1005,
          NextDialogue = 51007314,
          Subtitle = "For an academic report, it doesn't really sound that academic."
        },
        [510073132] = {
          ContentFR = "<I>Quel est le lien avec l’archéologie, exactement ?</>",
          DialogueId = 510073132,
          GUID = "510073132.0",
          ImprPlusId = 1004,
          NextDialogue = 51007314,
          Subtitle = "Tell me... Has any of your work to do with true archaeology?"
        },
        [510073141] = {
          ContentFR = "C’est précisément cette attitude expéditive qui empêche l’investisseur de « ressentir le désir ».",
          DialogueId = 510073141,
          GUID = "510073141.0",
          ImprPlusId = 1002,
          NextDialogue = 510073142,
          Subtitle = "That's it — you see nothing up top and give up right away. No wonder the investor said he can't feel any passion. "
        },
        [510073142] = {
          ContentFR = "Je le sais bien... mais qu’est-ce que le désir, au juste ? À Givrelac, je ne l’ai jamais trouvé...",
          DialogueId = 510073142,
          GUID = "510073142.0",
          NextOptions = {
            [1] = 51007315
          },
          RestartTag = 510073142,
          SpeakNpcId = 700077,
          Subtitle = "It's not like I want it this way! Passion, what is it? I am sure haven't found it here in Icelake."
        },
        [510073151] = {
          ContentFR = "Si j’en avais un, croyez-vous que je serais encore là à me lamenter ?",
          DialogueId = 510073151,
          GUID = "510073151.0",
          SpeakNpcId = 700077,
          Subtitle = "Ugh... if I had one, do you think I'd still be stuck here worrying?"
        },
        [510073152] = {
          ContentFR = "Impossible d’en trouver. Les Chasseurs de Phoxène d’ici ne pensent qu’à se battre et à boire. Quand je leur ai demandé s’il y avait des vestiges anciens, ils m’ont répondu que leur marmite familiale comptait peut-être comme relique...",
          DialogueId = 510073152,
          GUID = "510073152",
          NextDialogue = 510073156,
          SpeakNpcId = 700077,
          Subtitle = "I can't find one. Phoxhunters here only care about fights and drinks. I once asked if there were any historic ruins nearby, only to be asked back whether their stewpots counted as relics."
        },
        [510073153] = {
          ContentFR = "<I>Très bien, voyons si je peux vous inspirer.</>",
          DialogueId = 510073153,
          GUID = "510073153",
          ImprPlusId = 1004,
          NextDialogue = 51007316,
          Subtitle = "Alright, let's see if we can dig up some inspiration for you."
        },
        [510073154] = {
          ContentFR = "<I>Offrez-moi une récompense, et je réfléchirai avec vous.</>",
          DialogueId = 510073154,
          GUID = "510073154",
          ImprPlusId = 1001,
          NextDialogue = 51007316,
          Subtitle = "Pay up, and I'll help you brainstorm. "
        },
        [510073155] = {
          ContentFR = "<I>Vous avez trouvé la bonne personne : partagez vos fonds de recherche.</>",
          DialogueId = 510073155,
          GUID = "510073155",
          ImprPlusId = 1005,
          NextDialogue = 51007316,
          Subtitle = "You came to the right person — I am the top-notch intellectual. Now share some of your research funding with me and I shall help you."
        },
        [510073156] = {
          ContentFR = "Et si... vous m’accompagniez explorer les environs ? Parmi les habitués des Asphodèles, vous êtes celui qui boit le moins et lit le plus.",
          DialogueId = 510073156,
          GUID = "7FB1039F",
          NextOptions = {
            [1] = 510073153,
            [2] = 510073154,
            [3] = 510073155
          },
          SpeakNpcId = 700077,
          Subtitle = "How about.... you take me around and see if we can find some inspiration. Of all the regulars at the Asphodel, you looks like the one who drinks the least and reads the most."
        },
        [510073231] = {
          ContentFR = "Les techniques et les installations diffèrent nettement. Les sections les plus anciennes sont faites de pierre et de briques, tandis que les parties récentes intègrent davantage de mécanismes...",
          DialogueId = 510073231,
          GUID = "7FB104C5",
          NextDialogue = 510073232,
          SpeakNpcId = 700172,
          Subtitle = "The craft and design differ. The older sections are mostly stone and brick, while the newer ones feature more mechanical elements."
        },
        [510073232] = {
          ContentFR = "Il y aurait matière à rédiger un rapport... même s’il s’agirait plutôt d’histoire urbaine. Je me demande si quelqu’un a déjà travaillé sur ce sujet...",
          DialogueId = 510073232,
          GUID = "7FB104C6",
          NextDialogue = 510073233,
          SpeakNpcId = 700172,
          Subtitle = "I could probably write a report on this. It's kind of more like urban history... I wonder if anyone has already worked on it. "
        },
        [510073233] = {
          ContentFR = "Oh, pardon, je me suis laissée emporter par mes pensées. Mais oui, j’ai bel et bien trouvé de l’inspiration. Pourriez-vous m’emmener ailleurs ? N’importe quel endroit que vous jugez intéressant.",
          DialogueId = 510073233,
          GUID = "7FB104EE",
          SpeakNpcId = 700172,
          Subtitle = "Ah, forgive me. I was lost in my thought. Indeed, I got inspired. Can you take me to some other sites? Anywhere you think is interesting will do. "
        },
        [510073411] = {
          ContentFR = "<I>J’espérais rester </>{性别:<I>discret</>|<I>discrète</>}...",
          DialogueId = 510073411,
          GUID = "510073411.0",
          ImprPlusId = 1005,
          NextDialogue = 51007344,
          Subtitle = "I was hoping to keep a low profile..."
        },
        [510073412] = {
          ContentFR = "<I>Je ne suis {性别:qu’un Chasseur de Phoxène|qu’une Chasseuse de Phoxène} de passage.</>",
          DialogueId = 510073412,
          GUID = "510073412.0",
          ImprPlusId = 1002,
          NextDialogue = 510073441,
          Subtitle = "I'm just an ordinary Phoxhunter passing by."
        },
        [510073413] = {
          ContentFR = "<I>Épargnez-moi les flatteries. Et ma récompense ?</>",
          DialogueId = 510073413,
          GUID = "510073413.0",
          ImprPlusId = 1001,
          NextDialogue = 51007342,
          Subtitle = "Spare me your flattery. My reward — now."
        },
        [510073441] = {
          ContentFR = "Je comprends, Maître. Vous préférez dissimuler votre identité aux yeux du monde.",
          DialogueId = 510073441,
          GUID = "510073441.0",
          NextDialogue = 51007342,
          SpeakNpcId = 700173,
          Subtitle = "I get it. You're trying to keep your identity secret from others."
        },
        [510073841] = {
          Content = "（真诚建议他注意个人卫生问题）",
          DialogueId = 510073841,
          GUID = "510073841.0",
          ImprPlusId = 1003,
          NextDialogue = 51007388,
          Subtitle = "(Sincerely suggest he looks into personal hygiene.)"
        },
        [510073842] = {
          Content = "（为自己刚才失礼的动作道歉）",
          DialogueId = 510073842,
          GUID = "510073842.0",
          ImprPlusId = 1004,
          NextDialogue = 51007388,
          Subtitle = "(Apologise for your rather impolite reaction just now.)"
        },
        [510073843] = {
          Content = "（指责他的味道过于腥臭有恶劣影响）",
          DialogueId = 510073843,
          GUID = "510073843.0",
          ImprPlusId = 1002,
          NextDialogue = 51007388,
          Subtitle = "(Complain that his stench is unbearable and affects those around him.)"
        },
        [510073931] = {
          ContentFR = "Tu ne comprends pas sa façon d’agir et tu as l’impression que la conversation ne pourra pas aller plus loin.",
          DialogueId = 510073931,
          GUID = "510073931.0",
          Subtitle = "You don't understand his behavior and feel you can't continue this conversation."
        },
        [510073991] = {
          Content = "我去跟你一起。",
          DialogueId = 510073991,
          GUID = "510073991.0"
        },
        [510073992] = {
          Content = "算了， 不太感兴趣。",
          DialogueId = 510073992,
          GUID = "510073992.0"
        },
        [510074041] = {
          Content = "将扳手递给达顿。",
          DialogueId = 510074041,
          GUID = "510074041.0",
          NextDialogue = 510074042
        },
        [510074042] = {
          Content = "嗯……差不多了，走吧，下一个。",
          DialogueId = 510074042,
          GUID = "510074042.0",
          SpeakNpcId = 700193
        },
        [510074043] = {
          Content = "再帮我一下。",
          DialogueId = 510074043,
          GUID = "510074043.0",
