        [710015031] = {
          ContentFR = "<I>Je vais essayer.</>",
          DialogueId = 710015031,
          GUID = "710015031.0",
          Subtitle = "Alright, let me see what I can do."
        },
        [710015032] = {
          ContentFR = "<I>Pas besoin de se compliquer, un petit coup suffit.</>",
          DialogueId = 710015032,
          GUID = "710015032.0",
          Subtitle = "Just give it a good smack. That should do the trick."
        },
        [710015033] = {
          ContentFR = "<I>Mieux vaut ne pas se mêler à la Légion, je m’éloigne.</>",
          DialogueId = 710015033,
          GUID = "710015033.0",
          Subtitle = "(Better not get involved with the Legion. Just walk away)"
        },
        [710016081] = {
