          DialogueId = 710055022,
          GUID = "710055042.0",
          Subtitle = "(Refuse to help)"
        },
        [710055031] = {
          ContentFR = "<I>– Rien ici. Le bruit vient de plus loin. Ça vaut le coup de vérifier plus en profondeur.</>",
          DialogueId = 710055031,
          GUID = "710055061.0",
          Subtitle = "(Still — sound can carry far in places like this. Might be worth checking a bit deeper in.)"
        },
        [710055032] = {
          ContentFR = "<I>– Quelque chose près du cours d’eau brille, il faudrait y jeter un œil.</>",
          DialogueId = 710055032,
          GUID = "710055062.0",
          Subtitle = "(Something near the waterway glints in the light. Might be worth a closer look.)"
        },
