        [760000101] = {
          Camera = "562.100586,152.578491,110.129761,0.000036,-1.199948,-164.795944,35.000011,100000.0,false,Disable,2.17",
          Content = "Idle 无由生01",
          DialogueId = 760000101,
          NextDialogue = 760000102
        },
        [760000102] = {
          Camera = "562.100586,152.578491,110.129761,0.000036,-1.199948,-164.795944,35.000011,100000.0,false,Disable,2.17",
          Content = "Agree 无由生01",
          DialogueId = 760000102,
          NextDialogue = 760000103,
          TalkActionId = {
            [1] = "75000002:Wuyou_Agree"
          }
        },
        [760000103] = {
          Camera = "562.100586,152.578491,110.129761,0.000036,-1.199948,-164.795944,35.000011,100000.0,false,Disable,2.17",
          Content = "Disagree 无由生01",
          DialogueId = 760000103,
          TalkActionId = {
            [1] = "75000002:Wuyou_Disagree"
          }
        },
        [800202021] = {
          ContentFR = "<I>Tu devrais te reposer alors, notre petite pause peut attendre.</>",
          DialogueId = 800202021,
          GUID = "800202021.0",
          NextDialogue = 80020203,
          Subtitle = "Ah, why don't you go take a rest now? Our little tea party can wait."
        },
        [800202022] = {
          ContentFR = "<I>Tu exagères un peu, non ?</>",
          DialogueId = 800202022,
          GUID = "800202022.0",
          NextDialogue = 80020204,
          Subtitle = "That's a slight exaggeration, isn't it?"
        },
        [800202091] = {
          ContentFR = "<I>Tu es vraiment qu’une simple servante ?</>",
          DialogueId = 800202091,
          GUID = "800202091.0",
          NextDialogue = 80020210,
          Subtitle = "Are you really just a maid?"
        },
        [800202092] = {
          ContentFR = "<I>Ça a l’air terriblement dangereux.</>",
          DialogueId = 800202092,
          GUID = "800202092.0",
          NextDialogue = 80020211,
          Subtitle = "That sounds extremely dangerous."
        },
        [800202161] = {
          ContentFR = "<I>Ça sonne comme une aventure pleine de charme.</>",
          DialogueId = 800202161,
          GUID = "800202161.0",
          NextDialogue = 80020217,
          Subtitle = "Sounds like a wondrous adventure."
        },
        [800202162] = {
          ContentFR = "<I>Ça semble être un métier difficile.</>",
          DialogueId = 800202162,
          GUID = "800202162.0",
          NextDialogue = 80020218,
          Subtitle = "Sounds like a tough job."
        },
        [800203021] = {
          ContentFR = "<I>Je peux venir avec toi ?</>",
          DialogueId = 800203021,
          GUID = "800203021.0",
          NextDialogue = 80020303,
          Subtitle = "Can I come with?"
        },
        [800203022] = {
          ContentFR = "<I>Toi, faire les boutiques ?</>",
          DialogueId = 800203022,
          GUID = "800203022.0",
          NextDialogue = 80020304,
          Subtitle = "You'd go shopping?"
        },
        [800203121] = {
