          ContentFR = "<I>Ouah, je plaisantais !</>",
          DialogueId = 801101301,
          GUID = "801101301.0",
          NextDialogue = 80110131,
          Subtitle = "I was just joking."
        },
        [801101361] = {
          ContentFR = "<I>Je note rien, promis. Mais t’es sûre de vouloir finir grillée ?</>",
          DialogueId = 801101361,
          GUID = "801101361.0",
          NextDialogue = 80110137,
          Subtitle = "Um... Again, zap-zap warning~"
        },
        [801102021] = {
          ContentFR = "<I>Oui, chez Madame Camilla.</>",
          DialogueId = 801102021,
          GUID = "801102021.0",
          NextDialogue = 80110203,
          Subtitle = "Yep, at Ms Camilla's tavern."
        },
        [801102031] = {
          ContentFR = "<I>Quoi ? Y’a carrément des missions de pillage et d’assassinat dans le coin ?</>",
          DialogueId = 801102031,
          GUID = "801102031.0",
          NextDialogue = 80110204,
          Subtitle = "You mean there are commissions that involve killing and robbing people!?"
        },
        [801102051] = {
          ContentFR = "<I>Non, maintenant elle est super gentille.</>",
          DialogueId = 801102051,
          GUID = "801102051.0",
          NextDialogue = 80110206,
          Subtitle = "Nah, she's a very kind lady now."
        },
        [801102052] = {
          ContentFR = "<I>Oh que oui, toujours aussi féroce.</>",
          DialogueId = 801102052,
          GUID = "801102052.0",
          NextDialogue = 80110207,
          Subtitle = "Yes, still being fierce and sharp-tongued."
        },
        [801102071] = {
          ContentFR = "<I>… C’est qui, ta supérieure ?</>",
          DialogueId = 801102071,
          GUID = "801102071.0",
          NextDialogue = 80110208,
          Subtitle = "...Who's your supreme officer?"
        },
        [801102091] = {
          ContentFR = "<I>Franchement... t’as un peu le même genre d’aura.</>",
          DialogueId = 801102091,
          GUID = "801102091.0",
          NextDialogue = 80110210,
          Subtitle = "You give me the same vibes..."
        },
        [801102151] = {
          ContentFR = "<I>... Elle a l’air plutôt particulière, ta supérieure. Tu peux m’en dire plus ?</>",
          DialogueId = 801102151,
          GUID = "801102151.0",
          NextDialogue = 80110216,
          Subtitle = "...Your superior officer sounds like an interesting person. Can you tell me more about her?"
        },
        [801102211] = {
          ContentFR = "<I>Et alors ? Ils l’ont trouvé, ce trésor ? Il est où maintenant ?</>",
          DialogueId = 801102211,
          GUID = "801102211.0",
          NextDialogue = 80110222,
          Subtitle = "Keep going. Did they finally find the treasure? Where is it now?"
        },
        [801103021] = {
          ContentFR = "<I>Qu’est-ce qu’il y a dans le colis ?</>",
          DialogueId = 801103021,
          GUID = "801103021.0",
          NextDialogue = 80110303,
          Subtitle = "What's in the package?"
        },
        [801103031] = {
          ContentFR = "<I>Faut bien que je vérifie qu’il n’y a rien de dangereux.</>",
          DialogueId = 801103031,
          GUID = "801103031.0",
          NextDialogue = 80110304,
          Subtitle = "I need to know if there are any hazardous materials."
        },
        [801103032] = {
          ContentFR = "<I>Je ne veux pas livrer quelque chose d'illégal et finir {性别:grillé|grillée}.</>",
          DialogueId = 801103032,
          GUID = "801103032.0",
          NextDialogue = 80110304,
          Subtitle = "I don't want to end up delivering something illegal and get zapped for it."
        },
        [801103051] = {
          ContentFR = "<I>Allez, je teste !</>",
          DialogueId = 801103051,
          GUID = "801103051.0",
          NextDialogue = 80110306,
          Subtitle = "Try it out!"
        },
        [801103081] = {
          ContentFR = "<I>C’est un cadeau, alors ?</>",
          DialogueId = 801103081,
          GUID = "801103081.0",
          NextDialogue = 80110309,
          Subtitle = "This gun is... a present?"
        },
        [801103101] = {
          ContentFR = "<I>Ça va, je m’en occupe. Mais si c’est pour une amie, pourquoi tu ne vas pas lui remettre toi-même ?</>",
          DialogueId = 801103101,
          GUID = "801103101.0",
          NextDialogue = 80110311,
          Subtitle = "I can do the job. But if it's a gift for a friend, why don't you deliver it yourself?"
        },
        [801103111] = {
          ContentFR = "<I>Pourquoi ?</>",
          DialogueId = 801103111,
          GUID = "801103111.0",
          NextDialogue = 80110312,
          Subtitle = "Why is that?"
        },
        [801103112] = {
          ContentFR = "<I>Tu t’es trop habituée à la grande ville pour encore supporter Givrelac, c’est ça ?</>",
          DialogueId = 801103112,
          GUID = "801103112.0",
          NextDialogue = 80110312,
          Subtitle = "What, gotten too used to the big city life to care about your humble hometown?"
        },
        [801103161] = {
          ContentFR = "<I>Tu trouves ça normal ?</>",
          DialogueId = 801103161,
          GUID = "801103161.0",
          NextDialogue = 80110317,
          Subtitle = "Do you think this is normal?"
        },
        [801103271] = {
          ContentFR = "<I>Ta famille a peur de toi ?</>",
          DialogueId = 801103271,
          GUID = "801103271.0",
          NextDialogue = 80110328,
          Subtitle = "Is your family afraid of you?"
        },
        [801103301] = {
          ContentFR = "<I>Je ne pense pas que ce soit normal, justement.</>",
          DialogueId = 801103301,
          GUID = "801103301.0",
          NextDialogue = 80110331,
          Subtitle = "I don't think any of this feels normal."
        },
        [801201101] = {
          ContentFR = "<I>Tu vas bien ?</>",
          DialogueId = 801201101,
          GUID = "801201101.0",
          NextDialogue = 80120111,
          Subtitle = "You okay?"
        },
        [801201102] = {
          ContentFR = "<I>Tapoter l’épaule de Margie</>",
          DialogueId = 801201102,
          GUID = "801201102.0",
          NextDialogue = 80120111,
          Subtitle = "(Pats Margie on the shoulder)"
        },
        [801201161] = {
          ContentFR = "<I>Alors ce « p’tit chien », c’était qui ?</>",
          DialogueId = 801201161,
          GUID = "801201161.0",
          NextDialogue = 80120117,
          Subtitle = "Barking? Right. So who was that doggie?"
        },
        [801201211] = {
          ContentFR = "<I>Tiré le gros lot ? Pourquoi ?</>",
          DialogueId = 801201211,
          GUID = "801201211.0",
          NextDialogue = 80120122,
          Subtitle = "A stroke of luck? Why's that?"
        },
        [801201271] = {
          ContentFR = "<I>Tu veux un coup de main ?</>",
          DialogueId = 801201271,
          GUID = "801201271.0",
          NextDialogue = 80120128,
          Subtitle = "Mind if I lend a hand?"
        },
        [801201272] = {
          ContentFR = "<I>Qui trouve garde... mais je me prends une part aussi.</>",
          DialogueId = 801201272,
          GUID = "801201272.0",
          NextDialogue = 80120129,
          Subtitle = "Finders keepers. I'd like a share of the finds too."
        },
        [801202041] = {
          ContentFR = "<I>Ça sonne creux, non ?</>",
          DialogueId = 801202041,
          GUID = "801202041.0",
          NextDialogue = 80120205,
          Subtitle = "Sounds like it's hollow inside."
        },
        [801202042] = {
          ContentFR = "<I>Joli son. C’est du bon bois.</>",
          DialogueId = 801202042,
          GUID = "801202042.0",
          NextDialogue = 80120206,
          Subtitle = "It's got a nice ring to it. Quality wood."
        },
        [801202111] = {
          ContentFR = "<I>Il y a un mot coincé dans la page. Qu’est-ce qu’il dit ?</>",
          DialogueId = 801202111,
          GUID = "801202111.0",
          NextDialogue = 80120212,
          Subtitle = "There's a note tucked in here. What does it say?"
        },
        [801202181] = {
          ContentFR = "<I>Le temps a fini par le changer.</>",
          DialogueId = 801202181,
          GUID = "801202181.0",
          NextDialogue = 80120219,
          Subtitle = "Time has changed him after all."
        },
        [801202182] = {
          ContentFR = "<I>Ou alors, il n’a jamais changé. Il a fait exprès de laisser cette partition.</>",
          DialogueId = 801202182,
          GUID = "801202182.0",
          NextDialogue = 80120220,
          Subtitle = "Maybe he never really changed. That's why he left this score behind on purpose."
        },
        [801203021] = {
          ContentFR = "<I>Même avec du sucre, notre Margie ne s’habitue toujours pas au café.</>",
          DialogueId = 801203021,
          GUID = "801203021.0",
          NextDialogue = 80120303,
          Subtitle = "Even with sugar, our Margie still can't stomach coffee."
        },
        [801203031] = {
          ContentFR = "<I>Tu préfères les boissons fraîches ou sucrées, c’est ça ?</>",
          DialogueId = 801203031,
          GUID = "801203031.0",
          NextDialogue = 80120304,
          Subtitle = "You're more of a fan of cool, refreshing drinks or something sweet, huh?"
        },
        [801203041] = {
          ContentFR = "<I>« Ton vieux crétin », c’est qui ?</>",
          DialogueId = 801203041,
          GUID = "801203041.0",
          NextDialogue = 80120305,
          Subtitle = "Who is your \"stupid old man\"?"
        },
        [801203071] = {
          ContentFR = "Com<I>pris ! Mademoiselle Détective Taciturne !</>",
          DialogueId = 801203071,
          GUID = "801203071.0",
          NextDialogue = 80120308,
          Subtitle = "Understood! Miss Reticent Detective it is!"
        },
        [801203081] = {
          ContentFR = "<I>Compris ! La plus cool, la plus intelligente et la plus fiable des « Princesse des Déchets » !</>",
          DialogueId = 801203081,
          GUID = "801203081.0",
          NextDialogue = 80120309,
          Subtitle = "Understood! The coolest, smartest, most reliable Princess Rubbish Bin!"
        },
        [801203101] = {
          ContentFR = "<I>Je ne t’ai jamais entendue parler de ton père avant ?</>",
          DialogueId = 801203101,
          GUID = "801203101.0",
          NextDialogue = 80120311,
          Subtitle = "I've never heard you talk about your dad before."
        },
        [801203111] = {
          ContentFR = "<I>C’est un peu pareil pour vous deux, non ?</>",
          DialogueId = 801203111,
          GUID = "801203111.0",
          NextDialogue = 80120312,
          Subtitle = "Sounds like you're no better than him on this!"
        },
        [801203121] = {
          ContentFR = "<I>Tel père, telle fille, hein ?</>",
          DialogueId = 801203121,
          GUID = "801203121.0",
          NextDialogue = 80120313,
          Subtitle = "Like father, like daughter, huh?"
        },
        [801203161] = {
          ContentFR = "<I>Hein ? Tu viens de balancer un truc super louche, là ?!</>",
          DialogueId = 801203161,
          GUID = "801203161.0",
          NextDialogue = 80120317,
          Subtitle = "...Wait, what did you just say!? Should I report this?"
        },
        [801203181] = {
          ContentFR = "<I>Mais puisqu’il t’a emmenée loin de là-bas, il n’aimait sûrement pas vraiment cet endroit, non ?</>",
          DialogueId = 801203181,
          GUID = "801203181.0",
          NextDialogue = 80120319,
          Subtitle = "But since Martin brought you away from your old home, maybe he didn't like it there either."
        },
        [801203211] = {
          ContentFR = "<I>Ah ouais ? Comment tu parlais exactement ? Tu peux me faire une petite démo ?</>",
          DialogueId = 801203211,
          GUID = "801203211.0",
          NextDialogue = 80120322,
          Subtitle = "Really? How did you talk back then? Can you give me a demo?"
        },
        [801203221] = {
          ContentFR = "<I>S’il te plaît Mademoiselle Détective Réticente, je t’échange ta boisson préférée contre une démonstration !</>",
          DialogueId = 801203221,
          GUID = "801203221.0",
          NextDialogue = 80120323,
          Subtitle = "Please, Miss Reticent Detective, I'll trade you your favourite drink for it!"
        },
        [801203231] = {
          ContentFR = "<I>Si tu refuses, je serai obligé de... Princesse des Déchets, votre altesse...</>",
          DialogueId = 801203231,
          GUID = "801203231.0",
          NextDialogue = 80120324,
          Subtitle = "If you won't, I'll just have to play dirty — Princess Rubbish Bin, Your Highness—"
        },
        [801203261] = {
          ContentFR = "<I>Tenter de ne pas éclater de rire</>",
          DialogueId = 801203261,
          GUID = "801203261.0",
          NextDialogue = 80120327,
          Subtitle = "(Holding back a laugh.)"
        },
        [801203271] = {
          ContentFR = "<I>Ne parvient plus à se retenir</>",
          DialogueId = 801203271,
          GUID = "801203271.0",
          NextDialogue = 80120328,
          Subtitle = "(It's increasingly hard to hold it back!)"
        },
        [801203281] = {
          ContentFR = "<I>Exploser de rire !</>",
          DialogueId = 801203281,
          GUID = "801203281.0",
          NextDialogue = 80120329,
          Subtitle = "(Can't hold it back anymore!)"
        },
        [801203361] = {
          ContentFR = "<I>Il s’est moqué de toi ? Comment ça ?</>",
          DialogueId = 801203361,
          GUID = "801203361.0",
          NextDialogue = 80120337,
          Subtitle = "Mock you? How?"
        },
        [801203431] = {
          ContentFR = "<I>Un casque fait d’une marmite... Martin a vraiment un style unique.</>",
          DialogueId = 801203431,
          GUID = "801203431.0",
          NextDialogue = 80120344,
          Subtitle = "A pot helmet... Old Martin sure has a unique sense of style."
        },
        [801203432] = {
          ContentFR = "<I>C’était un cadeau d’anniversaire... On dirait que Martin tient vraiment à toi.</>",
          DialogueId = 801203432,
          GUID = "801203432.0",
          NextDialogue = 80120344,
          Subtitle = "So it was a birthday gift... Looks like Old Martin really cares about you."
        },
        [801204011] = {
          ContentFR = "<I>Pourquoi tu pleures ? Tu devrais sourire, c’est une bonne nouvelle !</>",
          DialogueId = 801204011,
          GUID = "801204011.0",
          NextDialogue = 80120402,
          Subtitle = "What's with the tears? Isn't that a good thing?"
        },
        [801204021] = {
          ContentFR = "<I>Tiens, bois un peu d’eau, raconte-moi tranquillement.</>",
          DialogueId = 801204021,
          GUID = "801204021.0",
          NextDialogue = 80120403,
          Subtitle = "Here, have some water. I'm here whenever you're ready to talk."
        },
        [801204041] = {
          ContentFR = "<I>Touffu ? C’est quoi ?</>",
          DialogueId = 801204041,
          GUID = "801204041.0",
          NextDialogue = 80120405,
          Subtitle = "Plumpytail? What's that?"
        },
        [801204111] = {
          ContentFR = "<I>Oh, pauvre détective, complètement manipulée par Touffu !</>",
          DialogueId = 801204111,
          GUID = "801204111.0",
          NextDialogue = 80120412,
          Subtitle = "Aww, poor detective, completely at the mercy of Plumpytail!"
        },
        [801204131] = {
          ContentFR = "<I>Miaou miaou ! Mademoiselle l’enquêtrice, j’ai une piste sérieuse !</>",
          DialogueId = 801204131,
          GUID = "801204131.0",
          NextDialogue = 80120414,
          Subtitle = "Meow meow! Miss Detective, I've got a major lead!"
        },
        [801204141] = {
          ContentFR = "<I>Tu connais les poubelles comme ta poche, et tu as monté un réseau d’infos chez les chats errants. Mademoiselle Détective Taciturne de Givrelac, chapeau !</>",
          DialogueId = 801204141,
          GUID = "801204141.0",
          NextDialogue = 80120415,
          Subtitle = "Not only do you know the bins' locations like the back of your hand, but you've even set up a kitten intel network. Bravo, Miss Reticent Detective of Icelake!"
        },
        [801204221] = {
          ContentFR = "<I>Toi aussi tu as grandi, tu n’as plus besoin du vieux Martin et tu prends soin de ceux qui ont besoin d’aide, comme Touffu.</>",
          DialogueId = 801204221,
          GUID = "801204221.0",
          NextDialogue = 80120423,
          Subtitle = "You've also grown and no longer needed Old Martin's care, just like Plumpytail, looking after those in need."
        },
        [801204251] = {
          ContentFR = "<I>Pourquoi pensais-tu ça ?</>",
          DialogueId = 801204251,
          GUID = "801204251.0",
          NextDialogue = 80120426,
          Subtitle = "What made you feel that way?"
        },
        [801204281] = {
          ContentFR = "<I>Tu as choisi Touffu plutôt que le vieux Martin, il va pleurer s’il l’apprend.</>",
          DialogueId = 801204281,
          GUID = "801204281.0",
          NextDialogue = 80120429,
          Subtitle = "You chose Plumpytail over Old Martin? He'd cry if he knew."
        },
        [801204291] = {
          ContentFR = "<I>Mais tu étais trop jeune, retourner dans les champs enneigés n’aurait pas été sûr.</>",
          DialogueId = 801204291,
          GUID = "801204291.0",
          NextDialogue = 80120430,
          Subtitle = "But given how young you were, the snowfields wouldn't have been safe for you."
        },
        [801204391] = {
          ContentFR = "<I>Touffu est vraiment intelligente.</>",
          DialogueId = 801204391,
          GUID = "801204391.0",
          NextDialogue = 80120440,
          Subtitle = "Plumpytail is really smart."
        },
        [801204401] = {
          ContentFR = "<I>Le chat t’a rappelée à la maison, c’est bien. Mais tu l’as inquiétée, et ça, c’est pas bien.</>",
          DialogueId = 801204401,
          GUID = "801204401.0",
          NextDialogue = 80120441,
          Subtitle = "Kitty looked out for you, good kitty. Margie made kitty worried, bad Margie."
        },
        [801204471] = {
          ContentFR = "<I>Oui, grandi... et aujourd’hui encore, tu es venue en pleurant.</>",
          DialogueId = 801204471,
          GUID = "801204471.0",
          NextDialogue = 80120448,
          Subtitle = "Right, grown into an older crybaby who came to me all tearful today."
        },
        [801301051] = {
          ContentFR = "<I>Tu pars déjà ?</>",
          DialogueId = 801301051,
          GUID = "801301051.0",
          NextDialogue = 80130106,
          Subtitle = "You're leaving already?"
        },
        [801301052] = {
          ContentFR = "<I>– Ce gamin est vraiment trop timide...</>",
          DialogueId = 801301052,
          GUID = "801301052.0",
          NextDialogue = 80130107,
          Subtitle = "(This kid is painfully shy...)"
        },
        [801301111] = {
          ContentFR = "<I>Awooo ! Je vais te manger tout cru !</>",
          DialogueId = 801301111,
          GUID = "801301111.0",
          NextDialogue = 80130112,
          Subtitle = "Awoo! I'm gonna eat you alive!"
        },
        [801301112] = {
          ContentFR = "<I>Je suis {性别:un Chasseur de Phoxène|une Chasseuse de Phoxène} au grand cœur, n’aie pas peur.</>",
          DialogueId = 801301112,
          GUID = "801301112.0",
          NextDialogue = 80130114,
          Subtitle = "I'm a Phoxhunter of the heartwarming type. No need to be afraid."
        },
        [801301181] = {
          ContentFR = "<I>Euh... pourquoi tu me dis tout ça ?</>",
          DialogueId = 801301181,
          GUID = "801301181.0",
          NextDialogue = 80130119,
          Subtitle = "Uh... why are you telling me all this?"
        },
        [801301182] = {
          ContentFR = "<I>Ça a l’air amusant. Où peut-on les acheter ?</>",
          DialogueId = 801301182,
          GUID = "801301182.0",
          NextDialogue = 80130120,
          Subtitle = "Sounds fun. Where can I buy some?"
        },
        [801302021] = {
          ContentFR = "<I>Bien sûr. Je me rappelle surtout que tu n’étais pas très à l’aise avec les inconnus.</>",
          DialogueId = 801302021,
          GUID = "801302021.0",
          NextDialogue = 80130203,
          Subtitle = "Of course. I remember you were shy around strangers."
        },
        [801302022] = {
          ContentFR = "<I>Je me souviens aussi de ton partenaire, Oliver.</>",
          DialogueId = 801302022,
          GUID = "801302022.0",
          NextDialogue = 80130204,
          Subtitle = "Yeah. And I remember your partner, Oliver, too."
        },
        [801302111] = {
          ContentFR = "<I>Il est juste parti comme ça ? C’est un peu irresponsable.</>",
          DialogueId = 801302111,
          GUID = "801302111.0",
          NextDialogue = 80130212,
          Subtitle = "He just walked away? That's pretty irresponsible."
        },
        [801302112] = {
          ContentFR = "<I>C’est déjà impressionnant que tu sois parvenu à tenir la boutique tout seul.</>",
          DialogueId = 801302112,
          GUID = "801302112.0",
          NextDialogue = 80130213,
          Subtitle = "It's impressive you managed to keep the place running by yourself."
        },
        [801302211] = {
          ContentFR = "<I>Tu veux connaître la vérité ?</>",
          DialogueId = 801302211,
          GUID = "801302211.0",
          NextDialogue = 80130222,
          Subtitle = "You want to find out the truth, right?"
        },
        [801302212] = {
          ContentFR = "<I>Tu penses lui rendre Crac’n’Pop ?</>",
          DialogueId = 801302212,
          GUID = "801302212.0",
          NextDialogue = 80130223,
          Subtitle = "You're thinking of giving him the shop?"
        },
        [801302271] = {
          ContentFR = "<I>Pourquoi tu n’en parles pas à Oliver ?</>",
          DialogueId = 801302271,
          GUID = "801302271.0",
          NextDialogue = 80130229,
          Subtitle = "Why not talk to Oliver about it?"
        },
        [801303021] = {
          ContentFR = "<I>Qu’est-ce qui se passe, Yale ?</>",
          DialogueId = 801303021,
          GUID = "801303021.0",
          NextDialogue = 80130303,
          Subtitle = "What's with you today, Yale?"
        },
        [801303022] = {
          ContentFR = "<I>Tu n’es pas Yale.</>",
          DialogueId = 801303022,
          GUID = "801303022.0",
          NextDialogue = 80130304,
          Subtitle = "You're not Yale."
        },
        [801303071] = {
          ContentFR = "<I>Je sais pas ce qui se passe, mais t’as pas l’air de demander un service.</>",
          DialogueId = 801303071,
          GUID = "801303071.0",
          NextDialogue = 80130308,
          Subtitle = "I don't know what this is, but you don't sound like you're asking for a favour."
        },
        [801303072] = {
          ContentFR = "<I>Dis-moi où est Yale, ensuite nous pourrons discuter.</>",
          DialogueId = 801303072,
          GUID = "801303072.0",
          NextDialogue = 80130309,
          Subtitle = "Tell me where Yale is, then we can talk."
        },
        [801303231] = {
          ContentFR = "<I>{性别:Désolé|Désolée}... j’ai pas tout suivi.</>",
          DialogueId = 801303231,
          GUID = "801303231.0",
          NextDialogue = 80130324,
          Subtitle = "Sorry... you've lost me."
        },
        [801303232] = {
          ContentFR = "<I>Jones a fait quelque chose d’impardonnable...</>",
