          DialogueId = 801703011,
          GUID = "801703011.0",
          NextDialogue = 80170302,
          Subtitle = "The credit all goes to the story you shared with me, Lady Nifle."
        },
        [801703012] = {
          ContentFR = "<I>J’ai essayé de savourer le moment présent, comme tu me l’avais conseillé.</>",
          DialogueId = 801703012,
          GUID = "801703012.0",
          NextDialogue = 80170302,
          Subtitle = "I've tried to live in the present moment, as you advised last time."
        },
        [801703111] = {
          ContentFR = "<I>On dirait une histoire qui finit bien, non ?</>",
          DialogueId = 801703111,
          GUID = "801703111.0",
          NextDialogue = 80170312,
          Subtitle = "That sounds like a story with a happy ending, doesn't it?"
        },
        [801703241] = {
          ContentFR = "<I>C’est... horrible...</>",
          DialogueId = 801703241,
          GUID = "801703241.0",
          NextDialogue = 80170325,
          Subtitle = "How could this happen...?"
        },
        [801703391] = {
          ContentFR = "<I>Tu lui as dit que sa fille adoptive était encore en vie ?</>",
          DialogueId = 801703391,
          GUID = "801703391.0",
          NextDialogue = 80170340,
          Subtitle = "Did you tell him his adopted daughter was still alive?"
        },
        [801703481] = {
          ContentFR = "<I>Je crois... que je comprends un peu mieux maintenant...</>",
          DialogueId = 801703481,
          GUID = "801703481.0",
          NextDialogue = 80170349,
          Subtitle = "I think I understand now..."
        },
        [801704011] = {
          ContentFR = "<I>Tu as raconté tant d’histoires... mais jamais la tienne.</>",
          DialogueId = 801704011,
          GUID = "801704011.0",
          NextDialogue = 80170402,
          Subtitle = "You've shared many stories of others, yet you have never spoken of your own."
        },
        [801704031] = {
          ContentFR = "<I>Oui, je crois avoir compris.</>",
          DialogueId = 801704031,
          GUID = "801704031.0",
          NextDialogue = 80170404,
          Subtitle = "Yes, I believe I have."
        },
        [801704032] = {
          ContentFR = "<I>Hein ? Que veux-tu dire ?</>",
          DialogueId = 801704032,
          GUID = "801704032.0",
          NextDialogue = 80170406,
          Subtitle = "Huh? What do you mean?"
        },
        [801704261] = {
          ContentFR = "<I>Non... ce n’est pas encore toute l’histoire.</>",
          DialogueId = 801704261,
          GUID = "801704261.0",
          NextDialogue = 80170427,
          Subtitle = "No, this isn't the full story."
        },
        [801704381] = {
          ContentFR = "<I>Regrettes-tu ce temps-là ?</>",
          DialogueId = 801704381,
          GUID = "801704381.0",
          NextDialogue = 80170439,
          Subtitle = "Do you miss those days?"
        },
        [801901041] = {
          ContentFR = "<I>Je voulais juste te voir.</>",
          DialogueId = 801901041,
          GUID = "801901041.0",
          NextDialogue = 80190105,
          Subtitle = "I just missed you."
        },
        [801901042] = {
          ContentFR = "<I>Je voulais juste t’inviter à boire un verre.</>",
          DialogueId = 801901042,
          GUID = "801901042.0",
          NextDialogue = 80190106,
          Subtitle = "I just wanted to share a drink with you."
        },
        [801901101] = {
          ContentFR = "<I>T’es le plus bavard de tous ceux que j’ai invités.</>",
          DialogueId = 801901101,
          GUID = "801901101.0",
          NextDialogue = 80190111,
          Subtitle = "You're the biggest chatterbox of those I've invited for a drink."
        },
        [801901102] = {
          ContentFR = "<I>Je t’invite à boire et tu balances des remarques ? Continue comme ça, et je fais la tête.</>",
          DialogueId = 801901102,
          GUID = "801901102.0",
          NextDialogue = 80190112,
          Subtitle = "I offer you a drink and all I get is this rude comment? I should be offended."
        },
        [801901151] = {
          ContentFR = "<I>Tu veux dire que tu es l’un d’eux ?</>",
          DialogueId = 801901151,
          GUID = "801901151.0",
          NextDialogue = 80190116,
          Subtitle = "How do you know? Are you one of them?"
        },
        [801901171] = {
          ContentFR = "<I>Je te raccompagne pas.</>",
          DialogueId = 801901171,
          GUID = "801901171.0",
          NextDialogue = 80190118,
          Subtitle = "Well then, you should see yourself out."
        },
        [801901172] = {
          ContentFR = "<I>Alors c’est toi qui t’occupes de chasser les profiteurs pour moi ?</>",
          DialogueId = 801901172,
          GUID = "801901172.0",
          NextDialogue = 80190119,
          Subtitle = "So you've been chasing off the freeloaders for me?"
        },
        [801902011] = {
          ContentFR = "<I>Tu es invité et tu arrives en retard ? Pas cool.</>",
          DialogueId = 801902011,
          GUID = "801902011.0",
          NextDialogue = 80190203,
          Subtitle = "It's rude to be late when someone invites you for a drink."
        },
        [801902012] = {
          ContentFR = "<I>C’est pas une excuse, tu veux juste grappiller quelques verres de plus.</>",
          DialogueId = 801902012,
          GUID = "801902012.0",
          NextDialogue = 80190202,
          Subtitle = "That's not an apology. You're just angling for more drinks."
        },
        [801902041] = {
          ContentFR = "<I>La Légion ?</>",
          DialogueId = 801902041,
          GUID = "801902041.0",
          NextDialogue = 80190205,
          Subtitle = "The Legion?"
        },
        [801902151] = {
          ContentFR = "<I>Comparé à ça, trente minutes de retard, ce n’est rien.</>",
          DialogueId = 801902151,
          GUID = "801902151.0",
          NextDialogue = 80190216,
          Subtitle = "In that case, thirty minutes late doesn't sound so bad."
        },
        [801902152] = {
          ContentFR = "<I>Tu devrais plutôt te reposer que boire ici.</>",
          DialogueId = 801902152,
          GUID = "801902152.0",
          NextDialogue = 80190217,
          Subtitle = "You should be getting rest, not drinking."
        },
        [801902191] = {
          ContentFR = "<I>On dirait que tu les détestes.</>",
          DialogueId = 801902191,
          GUID = "801902191.0",
          NextDialogue = 80190220,
          Subtitle = "You really hate them, don't you?"
        },
        [801903031] = {
          ContentFR = "<I>Dis quelque chose.</>",
          DialogueId = 801903031,
          GUID = "801903031.0",
          NextDialogue = 80190304,
          Subtitle = "Say something."
        },
        [801903032] = {
          ContentFR = "<I>Ça va ?</>",
          DialogueId = 801903032,
          GUID = "801903032.0",
          NextDialogue = 80190304,
          Subtitle = "You okay?"
        },
        [801903061] = {
          ContentFR = "<I>Je devrais te préparer un mouchoir pour tes larmes ?</>",
          DialogueId = 801903061,
          GUID = "801903061.0",
          NextDialogue = 80190307,
          Subtitle = "Should I be getting you a handkerchief?"
        },
        [801903062] = {
          ContentFR = "<I>Tu vas finir par pleurer, non ?</>",
          DialogueId = 801903062,
          GUID = "801903062.0",
          NextDialogue = 80190307,
          Subtitle = "Are you gonna cry?"
        },
        [801903151] = {
          ContentFR = "<I>Entre amis, c’est normal de se confier.</>",
          DialogueId = 801903151,
          GUID = "801903151.0",
          NextDialogue = 80190316,
          Subtitle = "I think it's totally normal to open up to friends."
        },
        [801903152] = {
          ContentFR = "<I>Tu es trop cynique, moi je crois encore aux gens.</>",
          DialogueId = 801903152,
          GUID = "801903152.0",
          NextDialogue = 80190316,
          Subtitle = "That's a bit cynical. I still believe in people."
        },
        [801903171] = {
          ContentFR = "<I>Alors, ça veut dire que je suis pas vraiment ton {性别:ami|amie} ?</>",
          DialogueId = 801903171,
          GUID = "801903171.0",
          NextDialogue = 80190318,
          Subtitle = "So what you're saying is, I'm not really your friend..."
        },
        [801903221] = {
          ContentFR = "<I>Je ne tiens pas un resto ici !</>",
          DialogueId = 801903221,
          GUID = "801903221.0",
          NextDialogue = 80190323,
          Subtitle = "I'm not running a soup kitchen here, you know."
        },
        [801903222] = {
          ContentFR = "<I>Si tu veux. Essaie juste de pas le descendre aussi vite cette fois.</>",
          DialogueId = 801903222,
          GUID = "801903222.0",
          NextDialogue = 80190323,
          Subtitle = "Sure. Just try not to gulp this one down too."
        },
        [801903231] = {
          ContentFR = "<I>Mmmh. Un bon verre, un bon ami... et un sacré moulin à paroles.</>",
          DialogueId = 801903231,
          GUID = "801903231.0",
          NextDialogue = 80190324,
          Subtitle = "Mhm. Good booze, good banter, and one very talkative mutt."
        },
        [801904021] = {
          ContentFR = "<I>Non, je n’ai rien dit.</>",
          DialogueId = 801904021,
          GUID = "801904021.0",
          NextDialogue = 80190403,
          Subtitle = "I didn't say anything."
        },
        [801904091] = {
          ContentFR = "<I>Tu parles du travail de livraison pour les Déchus dont tu m’as parlé ?</>",
          DialogueId = 801904091,
          GUID = "801904091.0",
          NextDialogue = 80190410,
          Subtitle = "You mean the delivery job from earlier?"
        },
        [801904161] = {
          ContentFR = "<I>D’accord, va-t’en vite.</>",
          DialogueId = 801904161,
          GUID = "801904161.0",
          NextDialogue = 80190417,
          Subtitle = "Got it. You should go."
        },
        [801904162] = {
          ContentFR = "<I>Mais tu n’es pas qu’un simple ami de beuverie.</>",
          DialogueId = 801904162,
          GUID = "801904162.0",
          NextDialogue = 80190417,
          Subtitle = "You're not just a drinking buddy."
        },
        [801904321] = {
          ContentFR = "<I>Pour un gars sans scrupules, tu n’es pas mauvais non plus.</>",
          DialogueId = 801904321,
          GUID = "801904321.0",
          NextDialogue = 80190433,
          Subtitle = "Talk about having no moral scruples... you'd almost rival the Forsakens."
        },
        [801904322] = {
          ContentFR = "<I>Donc tu n’as pas encore de raison de fuir, c’est ça ?</>",
          DialogueId = 801904322,
          GUID = "801904322.0",
          NextDialogue = 80190433,
          Subtitle = "So you've got no reason to run away this time either, right?"
        },
        [801904361] = {
          ContentFR = "<I>Non, pas du tout. Tu veux un autre verre ?</>",
          DialogueId = 801904361,
          GUID = "801904361.0",
          NextDialogue = 80190437,
          Subtitle = "Not at all. Want another drink?"
        },
        [801904362] = {
          ContentFR = "<I>Tu as été dégoûtant. Tu me dois de l’argent pour le traumatisme émotionnel.</>",
          DialogueId = 801904362,
          GUID = "801904362.0",
          NextDialogue = 80190437,
          Subtitle = "You absolutely did. You owe me money for emotional damage."
        },
        [802000021] = {
          ContentFR = "<I>On dirait des noms de plantes. Si c’est consigné dans un livre, ça doit bien servir à quelque chose.</>",
          DialogueId = 802000021,
          GUID = "C8C5B4FE",
          NextDialogue = 80200004,
          Subtitle = "They sound like plant names. If they're listed in that book you're reading, I figure they must be useful for something."
        },
        [802000022] = {
          ContentFR = "<I>On dirait un passage d’un traité médical... sur les plantes, non ?</>",
          DialogueId = 802000022,
          GUID = "C8C5B552",
          NextDialogue = 80200006,
          Subtitle = "That sounds like something from a medical text. Is it about herbs?"
        },
        [802000023] = {
          ContentFR = "<I>Je te dérange ? Tu avais l’air absorbée par ta lecture.</>",
          DialogueId = 802000023,
          GUID = "C8C5B5A6",
          NextDialogue = 80200008,
          Subtitle = "Am I interrupting? You seemed deeply absorbed in your reading."
        },
        [802000101] = {
          ContentFR = "<I>Vivre ici seule, ce n’est pas trop difficile ?</>",
          DialogueId = 802000101,
          GUID = "C8C5B64E",
          NextDialogue = 80200012,
          Subtitle = "Is it hard, living here all on your own?"
        },
        [802000102] = {
          ContentFR = "<I>Ce n’est vraiment pas un souci.</>",
          DialogueId = 802000102,
          GUID = "C8C5B6A2",
          NextDialogue = 80200014,
          Subtitle = "It's nothing."
        },
        [802000103] = {
          ContentFR = "<I>Mince... encore un repas gratuit en moins.</>",
          DialogueId = 802000103,
          GUID = "C8C5B6F6",
          NextDialogue = 80200016,
          Subtitle = "Oh no — there goes my free meal!"
        },
        [802000271] = {
          ContentFR = "<I>Si ça t’aide à moins dépendre de l’Art de l’Éphémère, je t’aiderai volontiers.</>",
          DialogueId = 802000271,
          GUID = "C8C5B918",
          NextDialogue = 80200029,
          Subtitle = "If it helps you rely less on the Art of Ephemerality, I'd be glad to help."
        },
        [802000272] = {
          ContentFR = "<I>Une consultation gratuite ? J’arrive ! On commence par quoi ?</>",
          DialogueId = 802000272,
          GUID = "C8C5B96C",
          NextDialogue = 80200031,
          Subtitle = "Free check-ups? Count me in! How do we start?"
        },
        [802000273] = {
          ContentFR = "<I>Je pensais que tu allais m’envoyer combattre Zhuyin... tout ça pour ça ?</>",
          DialogueId = 802000273,
          GUID = "C8C5B9C0",
          NextDialogue = 80200033,
          Subtitle = "That's it? I thought you were going to ask me to fight Zhuyin or something!"
        },
        [802000371] = {
          ContentFR = "<I>J’ai beaucoup voyagé ces derniers temps... je dors peu, c’est vrai.</>",
          DialogueId = 802000371,
          GUID = "C8C5BABC",
          NextDialogue = 80200039,
          Subtitle = "I've just been on the move a lot lately. Haven't really had the chance..."
        },
        [802000372] = {
          ContentFR = "<I>Je voulais surtout toucher l’énorme argent de poche de la Patronne Zhiliu.</>",
          DialogueId = 802000372,
          GUID = "C8C5BB10",
          NextDialogue = 80200041,
          Subtitle = "I've been chasing Proprietress Zhiliu's sky-high allowance — who has time to sleep with that kind of reward dangling in front of you?"
        },
        [802000373] = {
          ContentFR = "<I>Bah, le sommeil, c’est surfait. J’en ai pas vraiment besoin.</>",
          DialogueId = 802000373,
          GUID = "C8C5BB8E",
          NextDialogue = 80200044,
          Subtitle = "Bah, sleep's overrated. Who really needs it anyway?"
        },
        [802001141] = {
          ContentFR = "<I>?</>",
          DialogueId = 802001141,
          GUID = "C8C5C75E",
          NextDialogue = 80200118,
          Subtitle = "?"
        },
        [802001142] = {
          ContentFR = "<I>??</>",
          DialogueId = 802001142,
          GUID = "C8C5C788",
          NextDialogue = 80200118,
          Subtitle = "??"
        },
        [802001143] = {
          ContentFR = "<I>???</>",
          DialogueId = 802001143,
          GUID = "C8C5C7B2",
          NextDialogue = 80200118,
          Subtitle = "???"
        },
        [802001371] = {
          ContentFR = "<I>Je ne suis pas ta sœur. Je suis ton </>{性别:ami|amie}. Je m’appelle {nickname}. Nous cherchons des plantes ensemble.",
          DialogueId = 802001371,
          GUID = "C8C5CB24",
          NextDialogue = 80200139,
          Subtitle = "I'm not your sister. I'm your friend — . We're here gathering herbs, remember?"
        },
        [802001372] = {
          ContentFR = "<I>Je suis ta sœur. Je sais que j’ai eu tort.</>",
          DialogueId = 802001372,
          GUID = "C8C5CB78",
          NextDialogue = 80200141,
          Subtitle = "I AM your sister. I've realised how wrong I was."
        },
        [802001373] = {
          ContentFR = "<I>Non, je ne suis pas ta sœur. Je suis ta mère.</>",
          DialogueId = 802001373,
          GUID = "C8C5CBCC",
          NextDialogue = 80200143,
          Subtitle = "Actually, I'm your mother."
        },
        [802001501] = {
          ContentFR = "<I>Tu as goûté cette plante uniquement pour que je puisse dormir. Comment pourrais-je t’en vouloir ?</>",
          DialogueId = 802001501,
          GUID = "C8C5CD46",
          NextDialogue = 80200153,
          Subtitle = "You ate that herb just to help me sleep — how could I blame you?"
        },
        [802001502] = {
          ContentFR = "<I>C’est la première fois qu’on me prend pour la sœur aînée de quelqu’un de cent ans plus vieux. C’était... une expérience.</>",
          DialogueId = 802001502,
          GUID = "C8C5CD70",
          NextDialogue = 80200153,
          Subtitle = "First time someone a century older than me mistook me for their big sister. Weirdly exhilarating."
        },
        [802002251] = {
          ContentFR = "<I>Fushu est sincère avec les autres, attentive à ses patients. Nous sommes </>{性别:amis|amies}.",
          DialogueId = 802002251,
          GUID = "C8C5D358",
          NextDialogue = 80200226,
          Subtitle = "Fushu treats everyone with sincerity. She's a good physician — and a good friend."
        },
        [802002252] = {
          ContentFR = "<I>Je suis </>{性别:un de ses patients|une de ses patientes}. Elle m’a fait payer une fortune, je viens réclamer mon argent.",
          DialogueId = 802002252,
          GUID = "C8C5D3AC",
          NextDialogue = 80200227,
          Subtitle = "I'm actually one of her patients. She charged me a fortune last time — I'm here to get my money back."
        },
        [802002253] = {
          ContentFR = "<I>Belle grande sœur ! Ce n’est pas Fushu que je cherchais — c’est toi !</>",
          DialogueId = 802002253,
          GUID = "C8C5D400",
          NextDialogue = 80200228,
          Subtitle = "Hello, pretty lady! I'm not here for Fushu — I came for you!"
        },
        [802003071] = {
          ContentFR = "<I>?</>",
          DialogueId = 802003071,
          GUID = "C8C5E708",
          NextDialogue = 80200311,
          Subtitle = "?"
        },
        [802003072] = {
          ContentFR = "<I>??</>",
          DialogueId = 802003072,
          GUID = "C8C5E732",
          NextDialogue = 80200311,
          Subtitle = "??"
        },
        [802003073] = {
          ContentFR = "<I>???</>",
          DialogueId = 802003073,
          GUID = "C8C5E75C",
          NextDialogue = 80200311,
          Subtitle = "???"
        },
        [802003371] = {
          ContentFR = "<I>Ce sont vos souvenirs. C’est à toi d’en décider.</>",
          DialogueId = 802003371,
          GUID = "C8C5EBF4",
          NextDialogue = 80200339,
          Subtitle = "Sure — it's your memory. You should decide what to do with it."
        },
        [802003372] = {
          ContentFR = "<I>Je dois avouer que j’aimerais bien connaître la suite...</>",
          DialogueId = 802003372,
          GUID = "C8C5EC48",
          NextDialogue = 80200341,
          Subtitle = "But I was really hoping for some juicy drama..."
        },
        [802003451] = {
          ContentFR = "<I>Rêvolis.</>",
          DialogueId = 802003451,
          GUID = "C8C5ED44",
          NextDialogue = 80200348,
          Subtitle = "It's Oneirowort."
        },
        [802003452] = {
          ContentFR = "<I>Échorine.</>",
          DialogueId = 802003452,
          GUID = "C8C5ED6E",
          NextDialogue = 80200348,
          Subtitle = "It's Echowort."
        },
        [900103011] = {
          ContentFR = "<I>Qu’est-ce que c’est que ce truc noir, là-bas ?</>",
          DialogueId = 900103011,
          GUID = "900103011.0",
          Subtitle = "What's that black thingy over there?"
        },
        [900103012] = {
          ContentFR = "<I>À bientôt.</>",
          DialogueId = 900103012,
          GUID = "900103012.0",
          Subtitle = "Goodbye."
        },
        [900300011] = {
          ContentFR = "Berry, as-tu un souhait ?",
          DialogueId = 900300011,
          GUID = "900300011.0",
          NextDialogue = 90030101,
          Subtitle = "Do you have any wishes, Berry?"
        },
        [900300013] = {
          ContentFR = "Givrelac... Il fait vraiment un froid glacial ici.",
          DialogueId = 900300013,
          GUID = "900300013.0",
          NextDialogue = 90030301,
          Subtitle = "It's so bitterly cold here in Icelake..."
        },
        [900300014] = {
          ContentFR = "Berry ? Qu’est-ce que tu fais ici ?",
          DialogueId = 900300014,
          GUID = "900300014.0",
          NextDialogue = 90030401,
          Subtitle = "Berry? How come you are here?"
        },
        [900300015] = {
          ContentFR = "La Légion Hyperboréenne, c’est comment, exactement ?",
          DialogueId = 900300015,
          GUID = "900300015.0",
          NextDialogue = 90030501,
          Subtitle = "What's the Hyperborean Legion like?"
        },
        [900300016] = {
          ContentFR = " Tu as toujours aimé le calme... Ce n’est pas trop bruyant pour toi, ici ?",
          DialogueId = 900300016,
          GUID = "900300016.0",
          NextDialogue = 90030601,
          Subtitle = "You've always preferred quiet settings; does the noise here bother you?"
        },
        [900300018] = {
          ContentFR = "Berry, je suis fatigué.",
          DialogueId = 900300018,
          GUID = "900300018.0",
          NextDialogue = 90030801,
          Subtitle = "Berry, I'm tired..."
        },
        [900400011] = {
          ContentFR = "Tu as l’air toujours si heureuse quand il pleut.",
          DialogueId = 900400011,
          GUID = "900400011.0",
          NextDialogue = 90040101,
          Subtitle = "You always seem so happy when it rains."
        },
        [900400012] = {
          ContentFR = "Tu parles sans cesse d’amour. Qu’est-ce que l’amour pour toi ?",
          DialogueId = 900400012,
          GUID = "900400012.0",
          NextDialogue = 90040201,
          Subtitle = "You're always talking about love. What does \"love\" really mean to you...?"
        },
        [900400013] = {
          ContentFR = "Tu as une façon de penser vraiment spéciale.",
          DialogueId = 900400013,
          GUID = "900400013.0",
          NextDialogue = 90040301,
          Subtitle = "Your way of thinking is quite special."
        },
        [900400014] = {
          ContentFR = "Est-ce que tu vas bien avec autant de venin dans ton corps ?",
          DialogueId = 900400014,
          GUID = "900400014.0",
          NextDialogue = 90040401,
          Subtitle = "Are you alright with that much toxin in your body?"
        },
        [900400015] = {
          ContentFR = "Il y a toujours une odeur agréable autour de toi.",
          DialogueId = 900400015,
          GUID = "900400015.0",
          NextDialogue = 90040501,
          Subtitle = "There's always a pleasant smell around you."
        },
        [900500011] = {
          ContentFR = "Tu es si calme aujourd’hui... On dirait que tu es une personne complètement différente.",
          DialogueId = 900500011,
          GUID = "900500011.0",
